window.VOCAB_MINNA = {"N5":[{"word":"私","reading":"わたし","meaning":"tôi","hanViet":"TƯ","lesson":1,"ex":[["私は学生です。","Tôi là học sinh."],["私は日本語を勉強します。","Tôi học tiếng Nhật."],["私は来月、ベトナムへ帰ります。","Tháng sau tôi về Việt Nam."],["私は先生です。","Tôi là thầy giáo."],["私は毎朝六時に起きます。","Mỗi sáng tôi dậy lúc 6 giờ."]]},{"word":"私たち","reading":"わたしたち","meaning":"chúng ta, chúng tôi","hanViet":"","lesson":1,"ex":[["私たちは日本人です。","Chúng tôi là người Nhật."],["私たちは学生です。","Chúng tôi là học sinh."],["私たちは日本語を勉強します。","Chúng tôi học tiếng Nhật."],["私たちは友だちです。","Chúng tôi là bạn bè."],["私たちはいっしょに学校へ行きます。","Chúng tôi cùng đi học."]]},{"word":"あなた","reading":"あなた","meaning":"bạn","hanViet":"","lesson":1,"ex":[["あなたは学生ですか。","Bạn là học sinh à?"],["あなたは先生ですか。","Bạn là thầy giáo à?"],["あなたはどこから来ましたか。","Bạn đến từ đâu?"],["あなたのお名前は何ですか。","Tên bạn là gì?"],["あなたは日本語がわかりますか。","Bạn có hiểu tiếng Nhật không?"]]},{"word":"あの人","reading":"あのひと","meaning":"người kia","hanViet":"NHÂN","lesson":1,"ex":[["あの人は先生です。","Người kia là thầy giáo."],["あの人は学生です。","Người kia là học sinh."],["あの人は私の友だちです。","Người kia là bạn tôi."],["あの人はベトナムの学生です。","Người kia là học sinh Việt Nam."],["あの人は会社員です。","Người kia là nhân viên công ty."]]},{"word":"あの方","reading":"あのかた","meaning":"vị kia","hanViet":"PHƯƠNG","lesson":1,"ex":[["あの方はどなたですか。","Vị kia là ai?"],["あの方は先生です。","Vị kia là thầy giáo."],["あの方は日本の方です。","Vị kia là người Nhật."],["あの方は私の先生です。","Vị kia là thầy giáo của tôi."],["あの方は会社員ですか。","Vị kia là nhân viên công ty à?"]]},{"word":"皆さん","reading":"みなさん","meaning":"Mọi người (cách nói thân mật)","hanViet":"GIAI","lesson":1,"ex":[["皆さんは元気ですか。","Mọi người có khỏe không?"],["皆さんは学生ですか。","Mọi người có phải là học sinh không?"],["皆さん、ありがとうございました。","Mọi người, cảm ơn mọi người."],["皆さんはどこから来ましたか。","Mọi người đến từ đâu?"],["皆さんといっしょに勉強します。","Tôi học cùng với mọi người."]]},{"word":"先生","reading":"せんせい","meaning":"Thầy giáo, bác sĩ (kính ngữ)","hanViet":"TIÊN SINH","lesson":1,"ex":[["田中先生は日本語の先生です。","Thầy Tanaka là giáo viên tiếng Nhật."],["先生はどこですか。","Thầy giáo ở đâu?"],["私の先生は日本人です。","Thầy giáo của tôi là người Nhật."],["先生に手紙を書きます。","Tôi viết thư cho thầy giáo."],["田中先生は毎日、午後六時まで働きます。","Thầy Tanaka làm việc đến 6 giờ chiều mỗi ngày."]]},{"word":"教師","reading":"きょうし","meaning":"Giáo viên","hanViet":"GIÁO SƯ","lesson":1,"ex":[["私の父は教師です。","Bố tôi là giáo viên."],["母は教師です。","Mẹ tôi là giáo viên."],["私は教師です。","Tôi là giáo viên."],["田中さんは大学の教師です。","Anh Tanaka là giáo viên đại học."],["私の友達は教師です。","Bạn tôi là giáo viên."]]},{"word":"学生","reading":"がくせい","meaning":"Học sinh","hanViet":"HỌC SINH","lesson":1,"ex":[["私は大学の学生です。","Tôi là sinh viên đại học."],["弟は高校の学生です。","Em trai tôi là học sinh cấp ba."],["山田さんは学生です。","Anh Yamada là học sinh."],["私の友達は学生です。","Bạn tôi là học sinh."],["学生は学校で勉強します。","Học sinh học ở trường."]]},{"word":"会社員","reading":"かいしゃいん","meaning":"nhân viên công ty","hanViet":"HỘI XÃ VIÊN","lesson":1,"ex":[["私は会社員です。","Tôi là nhân viên công ty."],["兄は銀行の会社員です。","Anh trai tôi là nhân viên ngân hàng."],["山田さんは会社員です。","Anh Yamada là nhân viên công ty."],["私の兄は会社員です。","Anh trai tôi là nhân viên công ty."],["会社員は会社で働きます。","Nhân viên công ty làm việc ở công ty."]]},{"word":"社員","reading":"しゃいん","meaning":"Nhân viên công ty","hanViet":"XÃ VIÊN","lesson":1,"ex":[["山田さんは会社の社員です。","Anh Yamada là nhân viên công ty."],["私は会社の社員です。","Tôi là nhân viên công ty."],["田中さんは銀行の社員です。","Anh Tanaka là nhân viên ngân hàng."],["私の父は会社の社員です。","Bố tôi là nhân viên công ty."],["この人は会社の社員です。","Người này là nhân viên công ty."]]},{"word":"銀行員","reading":"ぎんこういん","meaning":"nhân viên ngân hàng","hanViet":"HÀNH","lesson":1,"ex":[["兄は銀行員です。","Anh trai tôi là nhân viên ngân hàng."],["私は銀行員です。","Tôi là nhân viên ngân hàng."],["父は銀行員です。","Bố tôi là nhân viên ngân hàng."],["田中さんは銀行員です。","Anh Tanaka là nhân viên ngân hàng."],["私の友達は銀行員です。","Bạn tôi là nhân viên ngân hàng."]]},{"word":"医者","reading":"いしゃ","meaning":"Bác sĩ","hanViet":"Y GIẢ","lesson":1,"ex":[["父は医者です。","Bố tôi là bác sĩ."],["私は医者です。","Tôi là bác sĩ."],["母は医者です。","Mẹ tôi là bác sĩ."],["田中さんは医者です。","Anh Tanaka là bác sĩ."],["医者は病院で働きます。","Bác sĩ làm việc ở bệnh viện."]]},{"word":"研究者","reading":"けんきゅうしゃ","meaning":"nhà nghiên cứu","hanViet":"NGHIÊN CỨU GIẢ","lesson":1,"ex":[["あの人は大学の研究者です。","Người kia là nghiên cứu viên đại học."],["私は研究者です。","Tôi là nhà nghiên cứu."],["父は研究者です。","Bố tôi là nhà nghiên cứu."],["田中さんは研究者です。","Anh Tanaka là nhà nghiên cứu."],["研究者は大学で研究します。","Nhà nghiên cứu làm nghiên cứu ở trường đại học."]]},{"word":"大学","reading":"だいがく","meaning":"Đại học","hanViet":"ĐẠI HỌC","lesson":1,"ex":[["大学へ行きます。","Tôi đi đến trường đại học."],["大学は大きいです。","Trường đại học to."],["大学で日本語を勉強します。","Tôi học tiếng Nhật ở trường đại học."],["大学はどこですか。","Trường đại học ở đâu?"],["大学は駅の近くにあります。","Trường đại học ở gần ga."]]},{"word":"病院","reading":"びょういん","meaning":"Bệnh viện","hanViet":"BỆNH VIỆN","lesson":1,"ex":[["病院はどこですか。","Bệnh viện ở đâu?"],["病院へ行きます。","Tôi đi đến bệnh viện."],["父は病院で働きます。","Bố tôi làm việc ở bệnh viện."],["病院で医者に会います。","Tôi gặp bác sĩ ở bệnh viện."],["病院は静かです。","Bệnh viện yên tĩnh."]]},{"word":"電気","reading":"でんき","meaning":"Điện, đèn điện","hanViet":"ĐIỆN KHÍ","lesson":1,"ex":[["電気を消してください。","Hãy tắt đèn."],["電気をつけてください。","Hãy bật đèn."],["夜、電気をつけます。","Buổi tối, tôi bật đèn."],["電気を消します。","Tôi tắt đèn."],["部屋の電気は明るいです。","Đèn trong phòng sáng."]]},{"word":"だれ","reading":"だれ","meaning":"ai (hỏi người nào đó)","hanViet":"","lesson":1,"ex":[["あの人はだれですか。","Người kia là ai?"],["この人はだれですか。","Người này là ai?"],["その人はだれですか。","Người đó là ai?"],["先生はだれですか。","Thầy giáo là ai?"],["あの女の人はだれですか。","Người phụ nữ kia là ai?"]]},{"word":"どなた","reading":"どなた","meaning":"ngài nào, vị nào (cùng nghĩa trên nhưng lịch sự hơn)","hanViet":"","lesson":1,"ex":[["こちらはどなたですか。","Vị này là ai?"],["あちらはどなたですか。","Vị đằng kia là ai?"],["あしたここに来る方はどなたですか。","Ngày mai người đến đây là vị nào ạ?"],["先生はどなたですか。","Thầy giáo là vị nào?"],["あの男の人はどなたですか。","Người đàn ông kia là vị nào?"]]},{"word":"何歳","reading":"なんさい","meaning":"Mấy tuổi","hanViet":"HÀ TUẾ","lesson":1,"ex":[["あなたは何歳ですか。","Bạn mấy tuổi?"],["弟は何歳ですか。","Em trai mấy tuổi?"],["妹さんは何歳ですか。","Em gái mấy tuổi?"],["あの子どもは何歳ですか。","Đứa trẻ kia mấy tuổi?"],["お父さんは何歳ですか。","Bố mấy tuổi?"]]},{"word":"失礼ですが","reading":"しつれいですが","meaning":"xin lỗi ( khi muốn nhờ ai việc gì đó)","hanViet":"THẤT LỄ","lesson":1,"ex":[["失礼ですが、お名前は？","Xin lỗi, bạn tên gì?"],["失礼ですが、駅はどこですか。","Xin lỗi, ga ở đâu?"],["失礼ですが、電話番号は何ですか。","Xin lỗi, số điện thoại là gì?"],["失礼ですが、今何時ですか。","Xin lỗi, bây giờ là mấy giờ?"],["失礼ですが、この本は日本語で何ですか。","Xin lỗi, quyển sách này tiếng Nhật là gì?"]]},{"word":"お名前は？","reading":"おなまえは？","meaning":"bạn tên gì?","hanViet":"DANH","lesson":1,"ex":[["お名前は？","Bạn tên gì?"],["すみません、お名前は？","Xin lỗi, bạn tên gì?"],["初めまして、お名前は？","Chào lần đầu gặp nhau, bạn tên gì?"],["こちらは田中です。お名前は？","Đây là Tanaka. Bạn tên gì?"],["お名前は？私は田中です。","Bạn tên gì? Tôi là Tanaka."]]},{"word":"初めまして","reading":"はじめまして","meaning":"chào lần đầu gặp nhau","hanViet":"SƠ","lesson":1,"ex":[["初めまして、田中です。","Chào lần đầu gặp nhau, tôi là Tanaka."],["初めまして、私は山田です。","Chào lần đầu gặp nhau, tôi là Yamada."],["初めまして、私はベトナムから来ました。","Chào lần đầu gặp nhau, tôi đến từ Việt Nam."],["初めまして、私は学生です。","Chào lần đầu gặp nhau, tôi là học sinh."],["初めまして、どうぞよろしくお願いします。","Chào lần đầu gặp nhau, rất hân hạnh được làm quen."]]},{"word":"どうぞよろしく","reading":"どうぞよろしく","meaning":"rất hân hạnh được làm quen","hanViet":"","lesson":1,"ex":[["どうぞよろしく。","Rất hân hạnh được làm quen."],["私は田中です。どうぞよろしく。","Tôi là Tanaka. Rất hân hạnh được làm quen."],["私はベトナムの留学生です。どうぞよろしく。","Tôi là du học sinh Việt Nam. Rất hân hạnh được làm quen."],["あしたから大学で勉強します。どうぞよろしく。","Từ ngày mai tôi học ở trường đại học. Rất hân hạnh được làm quen."],["私はエンジニアです。どうぞよろしく。","Tôi là kỹ sư. Rất hân hạnh được làm quen."]]},{"word":"こちらは～さんです","reading":"こちらは～さんです","meaning":"đây là ngài ～","hanViet":"","lesson":1,"ex":[["こちらは田中さんです。","Đây là anh Tanaka."],["こちらは山田さんです。","Đây là anh Yamada."],["こちらは大学の先生の田中さんです。","Đây là anh Tanaka, giáo viên đại học."],["こちらは私の友達の山田さんです。","Đây là bạn tôi, anh Yamada."],["こちらは会社の田中さんです。","Đây là anh Tanaka ở công ty."]]},{"word":"韓国","reading":"かんこく","meaning":"Hàn Quốc","hanViet":"HÀN QUỐC","lesson":1,"ex":[["私は韓国から来ました。","Tôi đến từ Hàn Quốc."],["韓国の友達がいます。","Tôi có bạn người Hàn Quốc."],["韓国へ行ったことがあります。","Tôi đã từng đi Hàn Quốc."],["韓国から友達が来ました。","Bạn tôi đã đến từ Hàn Quốc."],["韓国は寒いです。","Hàn Quốc lạnh."]]},{"word":"中国","reading":"ちゅうごく","meaning":"Trung Quốc","hanViet":"TRUNG QUỐC","lesson":1,"ex":[["あの人は中国から来ました。","Người kia đến từ Trung Quốc."],["私の友達は中国人です。","Bạn tôi là người Trung Quốc."],["中国へ行ったことがありません。","Tôi chưa từng đi Trung Quốc."],["中国は大きいです。","Trung Quốc rộng lớn."],["中国の友達に手紙を書きます。","Tôi viết thư cho bạn người Trung Quốc."]]},{"word":"～さん","reading":"～さん","meaning":"anh ～, chị ～","hanViet":"","lesson":1,"ex":[["田中さんは学生です。","Anh Tanaka là học sinh."],["田中さんは先生です。","Anh Tanaka là thầy giáo."],["山田さんは銀行員です。","Anh Yamada là nhân viên ngân hàng."],["田中さんは日本人です。","Anh Tanaka là người Nhật."],["山田さんは医者です。","Anh Yamada là bác sĩ."]]},{"word":"～ちゃん","reading":"～ちゃん","meaning":"bé ( dùng cho nữ) hoặc gọi thân mật cho trẻ con ( cả nam lẫn nữ)","hanViet":"","lesson":1,"ex":[["ゆみちゃんは学生です。","Bé Yumi là học sinh."],["ゆみちゃんは小さいです。","Bé Yumi còn nhỏ."],["ゆみちゃんは元気です。","Bé Yumi khỏe."],["ゆみちゃんは私の友達です。","Bé Yumi là bạn tôi."],["ゆみちゃんは学校へ行きます。","Bé Yumi đi học."]]},{"word":"～くん","reading":"～くん","meaning":"bé (dùng cho nam) hoặc gọi thân mật","hanViet":"QUÂN","lesson":1,"ex":[["たろうくんは学生です。","Bé Taro là học sinh."],["たろうくんは私の弟です。","Bé Taro là em trai tôi."],["たろうくんはサッカーが好きです。","Bé Taro thích bóng đá."],["たろうくんは日本人です。","Bé Taro là người Nhật."],["たろうくんは六歳です。","Bé Taro 6 tuổi."]]},{"word":"～人","reading":"～じん","meaning":"Người","hanViet":"NHÂN","lesson":1,"ex":[["私はベトナム人です。","Tôi là người Việt Nam."],["あの人は日本人です。","Người kia là người Nhật."],["田中さんは中国人です。","Anh Tanaka là người Trung Quốc."],["私の友達は韓国人です。","Bạn tôi là người Hàn Quốc."],["山田さんはアメリカ人です。","Anh Yamada là người Mỹ."]]},{"word":"～歳","reading":"～さい","meaning":"～tuổi","hanViet":"TUẾ","lesson":1,"ex":[["私は十五歳です。","Tôi 15 tuổi."],["私は二十歳です。","Tôi 20 tuổi."],["弟は十五歳です。","Em trai tôi 15 tuổi."],["妹は十二歳です。","Em gái tôi 12 tuổi."],["田中さんは三十歳です。","Anh Tanaka 30 tuổi."]]},{"word":"エンジニア","reading":"エンジニア","meaning":"kỹ sư","hanViet":"","lesson":1,"ex":[["私はエンジニアです。","Tôi là kỹ sư."],["父はエンジニアです。","Bố tôi là kỹ sư."],["田中さんはエンジニアです。","Anh Tanaka là kỹ sư."],["私の友達はエンジニアです。","Bạn tôi là kỹ sư."],["エンジニアは会社で働きます。","Kỹ sư làm việc ở công ty."]]},{"word":"おいくつ","reading":"おいくつ","meaning":"mấy tuổi (Dùng lịch sự hơn)","hanViet":"","lesson":1,"ex":[["あなたはおいくつですか。","Bạn mấy tuổi?"],["お父さんはおいくつですか。","Bố mấy tuổi?"],["お母さんはおいくつですか。","Mẹ mấy tuổi?"],["先生はおいくつですか。","Thầy giáo mấy tuổi?"],["おじいさんはおいくつですか。","Ông mấy tuổi?"]]},{"word":"はい","reading":"はい","meaning":"vâng, dạ","hanViet":"","lesson":1,"ex":[["はい、私は学生です。","Vâng, tôi là học sinh."],["はい、そうです。","Vâng, đúng vậy."],["はい、わかります。","Vâng, tôi hiểu."],["はい、行きます。","Vâng, tôi đi."],["はい、あります。","Vâng, có."]]},{"word":"いいえ","reading":"いいえ","meaning":"không","hanViet":"","lesson":1,"ex":[["いいえ、私は学生じゃありません。","Không, tôi không phải là học sinh."],["いいえ、知りません。","Không, tôi không biết."],["いいえ、行きません。","Không, tôi không đi."],["いいえ、ありません。","Không, không có."],["いいえ、まだです。","Không, chưa."]]},{"word":"よろしくお願いします","reading":"よろしくおねがいします","meaning":"Rất mong được giúp đỡ","hanViet":"","lesson":1,"ex":[["よろしくお願いします。","Rất mong được giúp đỡ."],["日本語が下手です。よろしくお願いします。","Tiếng Nhật của tôi còn kém. Rất mong được giúp đỡ."],["あしたから会社で働きます。よろしくお願いします。","Từ ngày mai tôi làm việc ở công ty. Rất mong được giúp đỡ."],["私は田中です。よろしくお願いします。","Tôi là Tanaka. Rất mong được giúp đỡ."],["これから日本語を勉強します。よろしくお願いします。","Từ nay tôi học tiếng Nhật. Rất mong được giúp đỡ."]]},{"word":"どうぞよろしくお願いします","reading":"どうぞよろしくおねがいします","meaning":"rất hân hạnh được làm quen","hanViet":"","lesson":1,"ex":[["どうぞよろしくお願いします。","Rất hân hạnh được làm quen."],["初めまして、私は山田です。どうぞよろしくお願いします。","Chào lần đầu gặp nhau, tôi là Yamada. Rất hân hạnh được làm quen."],["私はベトナムから来ました。どうぞよろしくお願いします。","Tôi đến từ Việt Nam. Rất hân hạnh được làm quen."],["あしたから日本で働きます。どうぞよろしくお願いします。","Từ ngày mai tôi làm việc ở Nhật Bản. Rất hân hạnh được làm quen."],["私は大学の学生です。どうぞよろしくお願いします。","Tôi là sinh viên đại học. Rất hân hạnh được làm quen."]]},{"word":"～から来ました","reading":"～からきました","meaning":"đến từ ～","hanViet":"LAI","lesson":1,"ex":[["私はベトナムから来ました。","Tôi đến từ Việt Nam."],["私は日本から来ました。","Tôi đến từ Nhật Bản."],["あの人はアメリカから来ました。","Người kia đến từ Mỹ."],["友達は中国から来ました。","Bạn tôi đến từ Trung Quốc."],["田中さんは韓国から来ました。","Anh Tanaka đến từ Hàn Quốc."]]},{"word":"アメリカ","reading":"アメリカ","meaning":"Mỹ","hanViet":"","lesson":1,"ex":[["あの人はアメリカ人です。","Người kia là người Mỹ."],["私はアメリカから来ました。","Tôi đến từ Mỹ."],["アメリカへ行ったことがあります。","Tôi đã từng đi Mỹ."],["アメリカの友達に会います。","Tôi gặp bạn người Mỹ."],["アメリカの映画が好きです。","Tôi thích phim Mỹ."]]},{"word":"イギリス","reading":"イギリス","meaning":"Anh","hanViet":"","lesson":1,"ex":[["私はイギリスから来ました。","Tôi đến từ Anh."],["あの人はイギリス人です。","Người kia là người Anh."],["イギリスへ行きます。","Tôi đi Anh."],["イギリスの紅茶が好きです。","Tôi thích trà đen Anh."],["イギリスで英語を勉強します。","Tôi học tiếng Anh ở Anh."]]},{"word":"インド","reading":"インド","meaning":"Ấn Độ","hanViet":"","lesson":1,"ex":[["あの人はインドから来ました。","Người kia đến từ Ấn Độ."],["私はインドへ行ったことがあります。","Tôi đã từng đi Ấn Độ."],["インドの友達がいます。","Tôi có bạn người Ấn Độ."],["インドのカレーライスが好きです。","Tôi thích cơm cà ri Ấn Độ."],["インドは暑いです。","Ấn Độ nóng."]]},{"word":"インドネシア","reading":"インドネシア","meaning":"Indonesia","hanViet":"","lesson":1,"ex":[["私はインドネシアから来ました。","Tôi đến từ Indonesia."],["あの人はインドネシア人です。","Người kia là người Indonesia."],["インドネシアへ行きます。","Tôi đi Indonesia."],["インドネシアの友達から手紙をもらいました。","Tôi đã nhận thư từ bạn người Indonesia."],["インドネシアの音楽が好きです。","Tôi thích âm nhạc Indonesia."]]},{"word":"タイ","reading":"タイ","meaning":"Thái Lan","hanViet":"","lesson":1,"ex":[["あの人はタイから来ました。","Người kia đến từ Thái Lan."],["私はタイへ行ったことがあります。","Tôi đã từng đi Thái Lan."],["タイの友達がいます。","Tôi có bạn người Thái Lan."],["タイの料理が好きです。","Tôi thích món ăn Thái Lan."],["この人はタイから来た友達です。","Người này là bạn đến từ Thái Lan."]]},{"word":"ドイツ","reading":"ドイツ","meaning":"Đức","hanViet":"","lesson":1,"ex":[["私はドイツから来ました。","Tôi đến từ Đức."],["あの人はドイツ人です。","Người kia là người Đức."],["ドイツへ行ったことがありません。","Tôi chưa từng đi Đức."],["ドイツのビールが好きです。","Tôi thích bia Đức."],["ドイツの友達と話します。","Tôi nói chuyện với bạn người Đức."]]},{"word":"フランス","reading":"フランス","meaning":"Pháp","hanViet":"","lesson":1,"ex":[["あの人はフランスから来ました。","Người kia đến từ Pháp."],["私はフランスへ行ったことがあります。","Tôi đã từng đi Pháp."],["フランスの友達がいます。","Tôi có bạn người Pháp."],["フランスのパンが好きです。","Tôi thích bánh mì Pháp."],["フランスはきれいです。","Pháp đẹp."]]},{"word":"ブラジル","reading":"ブラジル","meaning":"Brazil","hanViet":"","lesson":1,"ex":[["私はブラジルから来ました。","Tôi đến từ Brazil."],["あの人はブラジル人です。","Người kia là người Brazil."],["ブラジルへ行ったことがありません。","Tôi chưa từng đi Brazil."],["ブラジルのサッカーが好きです。","Tôi thích bóng đá Brazil."],["この人はブラジルから来た学生です。","Người này là học sinh đến từ Brazil."]]},{"word":"日本","reading":"にほん","meaning":"Nhật Bản","hanViet":"NHẬT BẢN","lesson":1,"ex":[["私は日本人です。","Tôi là người Nhật."],["私は日本へ行ったことがあります。","Tôi đã từng đi Nhật Bản."],["日本の桜が好きです。","Tôi thích hoa anh đào Nhật Bản."],["日本で日本語を勉強します。","Tôi học tiếng Nhật ở Nhật Bản."],["日本の食べ物が好きです。","Tôi thích món ăn Nhật Bản."]]},{"word":"ベトナム","reading":"ベトナム","meaning":"Việt Nam","hanViet":"","lesson":1,"ex":[["私の国はベトナムです。","Nước tôi là Việt Nam."],["私はベトナムの学生です。","Tôi là học sinh Việt Nam."],["ベトナムへ帰ります。","Tôi về Việt Nam."],["ベトナムのごはんが好きです。","Tôi thích cơm Việt Nam."],["ベトナムは暑いです。","Việt Nam nóng."]]},{"word":"本","reading":"ほん","meaning":"Quyển sách","hanViet":"BẢN","lesson":2,"ex":[["これは本です。","Đây là quyển sách."],["本を読みます。","Tôi đọc sách."],["本を買います。","Tôi mua sách."],["この本は新しいです。","Quyển sách này mới."],["本はかばんの中にあります。","Quyển sách ở trong cặp."]]},{"word":"辞書","reading":"じしょ","meaning":"từ điển","hanViet":"TỪ THƯ","lesson":2,"ex":[["辞書は机の上にあります。","Từ điển ở trên bàn."],["辞書を使います。","Tôi dùng từ điển."],["日本語の辞書を買います。","Tôi mua từ điển tiếng Nhật."],["この辞書は重いです。","Quyển từ điển này nặng."],["辞書で漢字を調べます。","Tôi tra chữ Hán bằng từ điển."]]},{"word":"雑誌","reading":"ざっし","meaning":"Tạp chí","hanViet":"TẠP CHÍ","lesson":2,"ex":[["雑誌を読みます。","Tôi đọc tạp chí."],["雑誌は本屋にあります。","Tạp chí ở hiệu sách."],["この雑誌はおもしろいです。","Tạp chí này hay."],["雑誌は高いです。","Tạp chí đắt."],["毎日雑誌を読みます。","Mỗi ngày tôi đọc tạp chí."]]},{"word":"新聞","reading":"しんぶん","meaning":"Báo chí, tin tức","hanViet":"TÂN VĂN","lesson":2,"ex":[["毎朝新聞を読みます。","Mỗi sáng tôi đọc báo."],["新聞を買います。","Tôi mua báo."],["新聞はどこですか。","Báo ở đâu?"],["毎晩新聞を読みます。","Mỗi tối tôi đọc báo."],["父は新聞を読みます。","Bố tôi đọc báo."]]},{"word":"手帳","reading":"てちょう","meaning":"sổ tay, sổ ghi chép","hanViet":"THỦ TRƯỚNG","lesson":2,"ex":[["手帳に書きます。","Tôi viết vào sổ tay."],["手帳を買います。","Tôi mua sổ tay."],["手帳に名前を書きます。","Tôi viết tên vào sổ tay."],["この手帳は小さいです。","Quyển sổ tay này nhỏ."],["手帳はどこですか。","Sổ tay ở đâu?"]]},{"word":"名刺","reading":"めいし","meaning":"Danh thiếp","hanViet":"DANH THỨ","lesson":2,"ex":[["これは名刺です。","Đây là danh thiếp."],["名刺をください。","Hãy cho tôi danh thiếp."],["名刺をもらいました。","Tôi đã nhận danh thiếp."],["これは私の名刺です。","Đây là danh thiếp của tôi."],["友達に名刺をあげます。","Tôi đưa danh thiếp cho bạn."]]},{"word":"鉛筆","reading":"えんぴつ","meaning":"Bút chì","hanViet":"DIÊN BÚT","lesson":2,"ex":[["鉛筆で書きます。","Tôi viết bằng bút chì."],["鉛筆を買います。","Tôi mua bút chì."],["鉛筆で漢字を書きます。","Tôi viết chữ Hán bằng bút chì."],["鉛筆はどこですか。","Bút chì ở đâu?"],["鉛筆をください。","Hãy cho tôi bút chì."]]},{"word":"鍵","reading":"かぎ","meaning":"Chìa khoá","hanViet":"KIỆN","lesson":2,"ex":[["鍵はどこですか。","Chìa khóa ở đâu?"],["鍵は部屋の机の上にあります。","Chìa khóa ở trên bàn trong phòng."],["鍵はかばんの中にあります。","Chìa khóa ở trong cặp."],["これは私の鍵です。","Đây là chìa khóa của tôi."],["鍵を持っています。","Tôi đang mang theo chìa khóa."]]},{"word":"時計","reading":"とけい","meaning":"Đồng hồ","hanViet":"THỜI KẾ","lesson":2,"ex":[["これは時計です。","Đây là đồng hồ."],["時計はどこですか。","Đồng hồ ở đâu?"],["この時計は新しいです。","Chiếc đồng hồ này mới."],["時計を買いました。","Tôi đã mua đồng hồ."],["私の時計は古いです。","Đồng hồ của tôi cũ."]]},{"word":"傘","reading":"かさ","meaning":"Ô, dù","hanViet":"TÁN","lesson":2,"ex":[["傘を持っています。","Tôi đang mang theo ô."],["傘を買います。","Tôi mua ô."],["傘はどこですか。","Ô ở đâu?"],["雨の日、傘を使います。","Ngày mưa, tôi dùng ô."],["傘は玄関にあります。","Ô ở cửa ra vào."]]},{"word":"かばん","reading":"かばん","meaning":"Cái cặp","hanViet":"","lesson":2,"ex":[["かばんは重いです。","Cái cặp nặng."],["かばんは大きいです。","Cái cặp to."],["かばんを買います。","Tôi mua cặp."],["新しいかばんをデパートで買いました。","Tôi đã mua cặp mới ở cửa hàng bách hóa."],["このかばんは新しいです。","Cái cặp này mới."]]},{"word":"自動車","reading":"じどうしゃ","meaning":"Ô tô","hanViet":"TỰ ĐỘNG XA","lesson":2,"ex":[["自動車は速いです。","Ô tô nhanh."],["自動車で学校へ行きます。","Tôi đi học bằng ô tô."],["私の自動車は新しいです。","Ô tô của tôi mới."],["自動車は便利です。","Ô tô tiện lợi."],["父は自動車で会社へ行きます。","Bố tôi đi làm bằng ô tô."]]},{"word":"机","reading":"つくえ","meaning":"Cái bàn","hanViet":"CƠ","lesson":2,"ex":[["机は大きいです。","Cái bàn to."],["この机は小さいです。","Cái bàn này nhỏ."],["机の上に本があります。","Trên bàn có quyển sách."],["机を買います。","Tôi mua bàn."],["机は部屋にあります。","Cái bàn ở trong phòng."]]},{"word":"いす","reading":"いす","meaning":"Cái ghế","hanViet":"","lesson":2,"ex":[["いすはここにあります。","Cái ghế ở đây."],["いすはどこですか。","Cái ghế ở đâu?"],["教室にいすが三十あります。","Trong lớp học có 30 cái ghế."],["このいすは新しいです。","Cái ghế này mới."],["いすは教室にあります。","Cái ghế ở trong lớp học."]]},{"word":"英語","reading":"えいご","meaning":"Tiếng Anh","hanViet":"ANH NGỮ","lesson":2,"ex":[["英語が好きです。","Tôi thích tiếng Anh."],["英語を勉強します。","Tôi học tiếng Anh."],["英語がわかります。","Tôi hiểu tiếng Anh."],["英語を話します。","Tôi nói tiếng Anh."],["英語の本を読みます。","Tôi đọc sách tiếng Anh."]]},{"word":"日本語","reading":"にほんご","meaning":"Tiếng Nhật","hanViet":"NHẬT BẢN NGỮ","lesson":2,"ex":[["日本語を勉強します。","Tôi học tiếng Nhật."],["日本語が好きです。","Tôi thích tiếng Nhật."],["日本語の本を読みます。","Tôi đọc sách tiếng Nhật."],["私は日本語の学生です。","Tôi là học sinh tiếng Nhật."],["日本語で話します。","Tôi nói bằng tiếng Nhật."]]},{"word":"何","reading":"なん","meaning":"Cái gì","hanViet":"HÀ","lesson":2,"ex":[["これは何ですか。","Đây là cái gì?"],["これは何の本ですか。","Đây là sách gì?"],["あなたの名前は何ですか。","Tên của bạn là gì?"],["今晩何を食べますか。","Tối nay bạn ăn gì?"],["何を買いますか。","Bạn mua gì?"]]},{"word":"違います","reading":"ちがいます","meaning":"Không phải, sai rồi","hanViet":"","lesson":2,"ex":[["いいえ、違います。","Không, không phải."],["それは違います。","Cái đó không phải."],["あれは違います。","Cái kia không phải."],["私の答えは違います。","Câu trả lời của tôi sai rồi."],["この答えは違います。","Câu trả lời này sai rồi."]]},{"word":"そうですか","reading":"そうですか","meaning":"thế à, vậy à","hanViet":"","lesson":2,"ex":[["そうですか。","Thế à, vậy à."],["あしたは休みです。そうですか。","Ngày mai là ngày nghỉ. Thế à."],["田中さんは学生です。そうですか。","Anh Tanaka là học sinh. Thế à."],["あしたは雨です。そうですか。","Ngày mai mưa. Thế à."],["そうですか、それはいいですね。","Thế à, vậy thì tốt nhỉ."]]},{"word":"あのう","reading":"あのう","meaning":"À... ừm... (ngập ngừng)","hanViet":"","lesson":2,"ex":[["あのう、これは何ですか。","À... đây là cái gì?"],["あのう、すみません。","À... xin lỗi."],["あのう、駅はどこですか。","À... ga ở đâu?"],["あのう、トイレはどこですか。","À... nhà vệ sinh ở đâu?"],["あのう、お名前は？","À... bạn tên gì?"]]},{"word":"ほんの気持ちです","reading":"ほんのきもちです","meaning":"Đây là chút lòng thành của tôi","hanViet":"KHÍ","lesson":2,"ex":[["どうぞ、ほんの気持ちです。","Xin mời, đây là chút lòng thành của tôi."],["これはベトナムのお土産です。ほんの気持ちです。","Đây là quà lưu niệm Việt Nam. Đây là chút lòng thành của tôi."],["これはプレゼントです。ほんの気持ちです。","Đây là quà tặng. Đây là chút lòng thành của tôi."],["これはケーキです。ほんの気持ちです。","Đây là bánh ngọt. Đây là chút lòng thành của tôi."],["どうぞ、これはお菓子です。ほんの気持ちです。","Xin mời, đây là bánh kẹo. Đây là chút lòng thành của tôi."]]},{"word":"どうぞ","reading":"どうぞ","meaning":"Xin mời","hanViet":"","lesson":2,"ex":[["どうぞ、食べてください。","Xin mời, hãy ăn đi."],["どうぞ、座ってください。","Xin mời, hãy ngồi."],["どうぞ、入ってください。","Xin mời, hãy vào."],["どうぞ、お茶を飲んでください。","Xin mời, hãy uống trà."],["どうぞ、見てください。","Xin mời, hãy xem."]]},{"word":"これからお世話になります","reading":"これからおせわになります","meaning":"Từ nay mong được giúp đỡ","hanViet":"THOẠI","lesson":2,"ex":[["これからお世話になります。","Từ nay mong được giúp đỡ."],["あしたから会社で働きます。これからお世話になります。","Từ ngày mai tôi làm việc ở công ty. Từ nay mong được giúp đỡ."],["私はベトナムから来ました。これからお世話になります。","Tôi đến từ Việt Nam. Từ nay mong được giúp đỡ."],["来週から大学で勉強します。これからお世話になります。","Từ tuần sau tôi học ở trường đại học. Từ nay mong được giúp đỡ."],["私は田中です。これからお世話になります。","Tôi là Tanaka. Từ nay mong được giúp đỡ."]]},{"word":"こちらこそよろしく","reading":"こちらこそよろしく","meaning":"Chính tôi mới là người mong được giúp đỡ","hanViet":"","lesson":2,"ex":[["こちらこそよろしく。","Chính tôi mới là người mong được giúp đỡ."],["田中です。こちらこそよろしく。","Tôi là Tanaka. Chính tôi mới là người mong được giúp đỡ."],["私は山田です。こちらこそよろしくお願いします。","Tôi là Yamada. Chính tôi mới là người mong được giúp đỡ."],["こちらこそよろしく。私は学生です。","Chính tôi mới là người mong được giúp đỡ. Tôi là học sinh."],["あしたからいっしょに勉強します。こちらこそよろしく。","Từ ngày mai chúng ta học cùng nhau. Chính tôi mới là người mong được giúp đỡ."]]},{"word":"これ","reading":"これ","meaning":"cái này, đây (gần người nói)","hanViet":"","lesson":2,"ex":[["これは辞書です。","Đây là từ điển."],["これは私の本です。","Đây là quyển sách của tôi."],["これは新しいです。","Cái này mới."],["これをください。","Hãy cho tôi cái này."],["これはだれの本ですか。","Đây là quyển sách của ai?"]]},{"word":"それ","reading":"それ","meaning":"cái đó (gần người nghe)","hanViet":"","lesson":2,"ex":[["それは何ですか。","Cái đó là cái gì?"],["それは本です。","Cái đó là quyển sách."],["それは私の時計です。","Cái đó là đồng hồ của tôi."],["それをください。","Hãy cho tôi cái đó."],["それはだれの傘ですか。","Cái đó là ô của ai?"]]},{"word":"あれ","reading":"あれ","meaning":"cái kia (xa cả người nói và người nghe)","hanViet":"","lesson":2,"ex":[["あれは自動車です。","Cái kia là ô tô."],["あれは何ですか。","Cái kia là cái gì?"],["あれは私の自動車です。","Cái kia là ô tô của tôi."],["あれをください。","Hãy cho tôi cái kia."],["あれはだれの自転車ですか。","Cái kia là xe đạp của ai?"]]},{"word":"この～","reading":"この～","meaning":"~này","hanViet":"","lesson":2,"ex":[["この本はおもしろいです。","Quyển sách này hay."],["この辞書は新しいです。","Quyển từ điển này mới."],["この傘は新しいです。","Cái ô này mới."],["この先生は日本人です。","Thầy giáo này là người Nhật."],["この学生はベトナム人です。","Học sinh này là người Việt Nam."]]},{"word":"その～","reading":"その～","meaning":"~đó","hanViet":"","lesson":2,"ex":[["その本は新しいです。","Quyển sách đó mới."],["その辞書は古いです。","Quyển từ điển đó cũ."],["その時計は高いです。","Chiếc đồng hồ đó đắt."],["その傘はだれの傘ですか。","Chiếc ô đó là ô của ai?"],["そのかばんは重いですか。","Cái cặp đó có nặng không?"]]},{"word":"あの～","reading":"あの～","meaning":"~kia","hanViet":"","lesson":2,"ex":[["あの自動車は速いです。","Chiếc ô tô kia nhanh."],["あの本はおもしろいです。","Quyển sách kia hay."],["あの建物は大きいです。","Tòa nhà kia to."],["あの店は新しいです。","Cửa hàng kia mới."],["あのレストランは安いです。","Nhà hàng kia rẻ."]]},{"word":"ノート","reading":"ノート","meaning":"Vở","hanViet":"","lesson":2,"ex":[["ノートに書きます。","Tôi viết vào vở."],["ノートを買います。","Tôi mua vở."],["ノートに漢字を書きます。","Tôi viết chữ Hán vào vở."],["このノートは新しいです。","Quyển vở này mới."],["ノートはどこですか。","Vở ở đâu?"]]},{"word":"カード","reading":"カード","meaning":"Card","hanViet":"","lesson":2,"ex":[["これはカードです。","Đây là tấm thẻ."],["カードをください。","Hãy cho tôi tấm thẻ."],["これは私のカードです。","Đây là thẻ của tôi."],["カードで買い物をします。","Tôi mua sắm bằng thẻ."],["このカードは新しいです。","Tấm thẻ này mới."]]},{"word":"テレホンカード","reading":"テレホンカード","meaning":"Card điện thoại","hanViet":"","lesson":2,"ex":[["テレホンカードで電話します。","Tôi gọi điện bằng thẻ điện thoại."],["テレホンカードを買います。","Tôi mua thẻ điện thoại."],["テレホンカードはどこですか。","Thẻ điện thoại ở đâu?"],["これはテレホンカードです。","Đây là thẻ điện thoại."],["テレホンカードをください。","Hãy cho tôi thẻ điện thoại."]]},{"word":"ボールペン","reading":"ボールペン","meaning":"bút bi","hanViet":"","lesson":2,"ex":[["ボールペンで書きます。","Tôi viết bằng bút bi."],["ボールペンを買います。","Tôi mua bút bi."],["このボールペンは新しいです。","Cây bút bi này mới."],["ボールペンで名前を書きます。","Tôi viết tên bằng bút bi."],["ボールペンはどこですか。","Bút bi ở đâu?"]]},{"word":"シャープペンシル","reading":"シャープペンシル","meaning":"Bút chì kim","hanViet":"","lesson":2,"ex":[["これはシャープペンシルです。","Đây là bút chì kim."],["シャープペンシルで書きます。","Tôi viết bằng bút chì kim."],["シャープペンシルを買います。","Tôi mua bút chì kim."],["シャープペンシルで漢字を書きます。","Tôi viết chữ Hán bằng bút chì kim."],["シャープペンシルをください。","Hãy cho tôi bút chì kim."]]},{"word":"カセットテープ","reading":"カセットテープ","meaning":"băng cassette","hanViet":"","lesson":2,"ex":[["カセットテープを聞きます。","Tôi nghe băng cassette."],["カセットテープを買います。","Tôi mua băng cassette."],["このカセットテープは新しいです。","Cuộn băng cassette này mới."],["カセットテープで日本語を勉強します。","Tôi học tiếng Nhật bằng băng cassette."],["カセットテープはどこですか。","Băng cassette ở đâu?"]]},{"word":"テープレコーダー","reading":"テープレコーダー","meaning":"máy ghi âm","hanViet":"","lesson":2,"ex":[["テープレコーダーで聞きます。","Tôi nghe bằng máy ghi âm."],["このテープレコーダーは新しいです。","Cái máy ghi âm này mới."],["母はテープレコーダーで音楽を聞きます。","Mẹ tôi nghe nhạc bằng máy ghi âm."],["テープレコーダーはどこですか。","Máy ghi âm ở đâu?"],["友達にテープレコーダーを貸しました。","Tôi đã cho bạn mượn máy ghi âm."]]},{"word":"テレビ","reading":"テレビ","meaning":"Tivi","hanViet":"","lesson":2,"ex":[["テレビを見ます。","Tôi xem tivi."],["毎晩、テレビでニュースを見ます。","Mỗi tối tôi xem tin tức trên tivi."],["テレビは大きいです。","Tivi to."],["父はテレビを見ながらごはんを食べます。","Bố tôi vừa xem tivi vừa ăn cơm."],["このテレビはいくらですか。","Cái tivi này giá bao nhiêu?"]]},{"word":"ラジオ","reading":"ラジオ","meaning":"Radio","hanViet":"","lesson":2,"ex":[["ラジオを聞きます。","Tôi nghe radio."],["朝、ラジオで天気を聞きます。","Buổi sáng tôi nghe dự báo thời tiết trên radio."],["ラジオは小さいです。","Radio nhỏ."],["母は料理をしながらラジオを聞きます。","Mẹ tôi vừa nấu ăn vừa nghe radio."],["ラジオで日本語を勉強します。","Tôi học tiếng Nhật qua radio."]]},{"word":"カメラ","reading":"カメラ","meaning":"Camera","hanViet":"","lesson":2,"ex":[["カメラで写真を撮ります。","Tôi chụp ảnh bằng máy ảnh."],["カメラは新しいです。","Máy ảnh mới."],["旅行にカメラを持っていきます。","Tôi mang máy ảnh đi du lịch."],["カメラで桜の写真を撮りました。","Tôi đã chụp ảnh hoa anh đào bằng máy ảnh."],["友達はカメラが好きです。","Bạn tôi thích máy ảnh."]]},{"word":"コンピューター","reading":"コンピューター","meaning":"Máy vi tính","hanViet":"","lesson":2,"ex":[["コンピューターは高いです。","Máy vi tính đắt."],["コンピューターでメールを書きます。","Tôi viết email bằng máy vi tính."],["学校にコンピューターがあります。","Ở trường có máy vi tính."],["兄はコンピューターを使います。","Anh trai tôi dùng máy vi tính."],["コンピューターで日本語を勉強します。","Tôi học tiếng Nhật bằng máy vi tính."]]},{"word":"チョコレート","reading":"チョコレート","meaning":"Sô cô la","hanViet":"","lesson":2,"ex":[["チョコレートが好きです。","Tôi thích sô cô la."],["チョコレートを食べます。","Tôi ăn sô cô la."],["母にチョコレートをあげました。","Tôi đã tặng sô cô la cho mẹ."],["このチョコレートは甘いです。","Sô cô la này ngọt."],["チョコレートを二つ買いました。","Tôi đã mua hai cái sô cô la."]]},{"word":"コーヒー","reading":"コーヒー","meaning":"Cà phê","hanViet":"","lesson":2,"ex":[["コーヒーを飲みます。","Tôi uống cà phê."],["朝、コーヒーを飲みます。","Buổi sáng tôi uống cà phê."],["喫茶店でコーヒーを飲みました。","Tôi đã uống cà phê ở quán cà phê."],["コーヒーは熱いです。","Cà phê nóng."],["友達とコーヒーを飲みます。","Tôi uống cà phê với bạn."]]},{"word":"シーディー","reading":"シーディー","meaning":"đĩa CD","hanViet":"","lesson":2,"ex":[["シーディーを聞きます。","Tôi nghe đĩa CD."],["このシーディーは新しいです。","Đĩa CD này mới."],["シーディーで音楽を聞きます。","Tôi nghe nhạc bằng đĩa CD."],["友達からシーディーをもらいました。","Tôi đã nhận đĩa CD từ bạn."],["シーディーを買いました。","Tôi đã mua đĩa CD."]]},{"word":"～語","reading":"～ご","meaning":"Tiếng ~","hanViet":"NGỮ","lesson":2,"ex":[["わたしはベトナム語を話します。","Tôi nói tiếng Việt."],["ベトナム語を勉強します。","Tôi học tiếng Việt."],["ベトナム語が好きです。","Tôi thích tiếng Việt."],["母は中国語を話します。","Mẹ tôi nói tiếng Trung."],["「ありがとう」は英語で何ですか。","“Arigatou” trong tiếng Anh là gì?"]]},{"word":"どうも","reading":"どうも","meaning":"Cảm ơn","hanViet":"","lesson":2,"ex":[["どうも、ありがとう。","Cảm ơn nhé."],["どうも、ありがとうございました。","Cảm ơn bạn rất nhiều."],["どうもすみません。","Xin lỗi nhiều nhé."],["どうも、ごちそうさまでした。","Cảm ơn về bữa ăn."],["どうも、ありがとうございます。","Cảm ơn bạn nhiều."]]},{"word":"ありがとう","reading":"ありがとう","meaning":"Cảm ơn","hanViet":"","lesson":2,"ex":[["ありがとう。","Cảm ơn."],["プレゼント、ありがとう。","Cảm ơn về món quà."],["教えてくれて、ありがとう。","Cảm ơn đã dạy tôi."],["ありがとう、楽しかったです。","Cảm ơn, tôi đã rất vui."],["ありがとう、また明日。","Cảm ơn, hẹn gặp lại ngày mai."]]},{"word":"どうもありがとう","reading":"どうもありがとう","meaning":"Cảm ơn rất nhiều","hanViet":"","lesson":2,"ex":[["どうもありがとう。","Cảm ơn rất nhiều."],["プレゼントをくれて、どうもありがとう。","Cảm ơn đã tặng quà cho tôi."],["手伝ってくれて、どうもありがとう。","Cảm ơn đã giúp tôi."],["どうもありがとう、また明日。","Cảm ơn rất nhiều, hẹn gặp lại ngày mai."],["どうもありがとう、おいしかったです。","Cảm ơn rất nhiều, ngon lắm."]]},{"word":"どうもありがとうございます","reading":"どうもありがとうございます","meaning":"xin chân thành cám ơn","hanViet":"","lesson":2,"ex":[["どうもありがとうございます。","Xin chân thành cảm ơn."],["教えてくれて、どうもありがとうございます。","Cảm ơn đã dạy tôi."],["プレゼントをくれて、どうもありがとうございます。","Cảm ơn đã tặng quà cho tôi."],["手伝ってくれて、どうもありがとうございます。","Cảm ơn đã giúp tôi."],["どうもありがとうございます、またよろしくお願いします。","Xin chân thành cảm ơn, mong tiếp tục được giúp đỡ."]]},{"word":"教室","reading":"きょうしつ","meaning":"Phòng học, lớp học","hanViet":"GIÁO THẤT","lesson":3,"ex":[["わたしの教室は二階です。","Phòng học của tôi ở tầng hai."],["教室は明るいです。","Phòng học sáng sủa."],["教室で日本語を勉強します。","Tôi học tiếng Nhật trong phòng học."],["教室に学生がいます。","Trong phòng học có học sinh."],["この教室は広いです。","Phòng học này rộng."]]},{"word":"食堂","reading":"しょくどう","meaning":"Nhà ăn, căng tin","hanViet":"THỰC ĐƯỜNG","lesson":3,"ex":[["昼ごはんは食堂で食べます。","Tôi ăn trưa ở nhà ăn."],["食堂は一階です。","Nhà ăn ở tầng một."],["食堂で友達と昼ごはんを食べます。","Tôi ăn trưa với bạn ở nhà ăn."],["食堂は広いです。","Nhà ăn rộng."],["食堂のごはんはおいしいです。","Cơm ở nhà ăn ngon."]]},{"word":"事務所","reading":"じむしょ","meaning":"văn phòng","hanViet":"SỰ VỤ SỞ","lesson":3,"ex":[["事務所は三階です。","Văn phòng ở tầng ba."],["事務所で働きます。","Tôi làm việc ở văn phòng."],["事務所はどこですか。","Văn phòng ở đâu?"],["事務所に電話をかけます。","Tôi gọi điện thoại đến văn phòng."],["事務所は静かです。","Văn phòng yên tĩnh."]]},{"word":"会議室","reading":"かいぎしつ","meaning":"Phòng họp","hanViet":"HỘI NGHỊ THẤT","lesson":3,"ex":[["明日、会議室で会議があります。","Ngày mai có cuộc họp ở phòng họp."],["会議室は二階です。","Phòng họp ở tầng hai."],["会議室で先生と話します。","Tôi nói chuyện với thầy giáo ở phòng họp."],["会議室は広いです。","Phòng họp rộng."],["会議室はどこですか。","Phòng họp ở đâu?"]]},{"word":"受付","reading":"うけつけ","meaning":"Quầy lễ tân, tiếp nhận","hanViet":"THỤ PHÓ","lesson":3,"ex":[["受付は一階です。","Quầy lễ tân ở tầng một."],["受付で名前を書きます。","Tôi viết tên ở quầy lễ tân."],["受付はあちらです。","Quầy lễ tân ở đằng kia."],["受付の人は親切です。","Người ở quầy lễ tân thân thiện."],["受付で聞きました。","Tôi đã hỏi ở quầy lễ tân."]]},{"word":"部屋","reading":"へや","meaning":"Căn phòng","hanViet":"BỘ ỐC","lesson":3,"ex":[["私の部屋は小さいです。","Phòng của tôi nhỏ."],["部屋は明るいです。","Căn phòng sáng sủa."],["部屋で本を読みます。","Tôi đọc sách trong phòng."],["部屋を掃除します。","Tôi dọn dẹp phòng."],["この部屋は静かです。","Căn phòng này yên tĩnh."]]},{"word":"階段","reading":"かいだん","meaning":"Cầu thang","hanViet":"GIAI ĐOẠN","lesson":3,"ex":[["階段はあそこです。","Cầu thang ở đằng kia."],["階段はここです。","Cầu thang ở đây."],["階段で二階へ行きます。","Tôi đi lên tầng hai bằng cầu thang."],["階段は狭いです。","Cầu thang hẹp."],["階段の近くにトイレがあります。","Gần cầu thang có nhà vệ sinh."]]},{"word":"国","reading":"くに","meaning":"đất nước, quốc gia","hanViet":"QUỐC","lesson":3,"ex":[["あなたの国はどこですか。","Nước của bạn ở đâu?"],["わたしの国はベトナムです。","Nước tôi là Việt Nam."],["国へ帰ります。","Tôi về nước."],["あなたの国は大きいですか。","Nước bạn có lớn không?"],["わたしの国の料理が好きです。","Tôi thích món ăn của nước tôi."]]},{"word":"会社","reading":"かいしゃ","meaning":"Công ty","hanViet":"HỘI XÃ","lesson":3,"ex":[["会社は駅の近くにあります。","Công ty ở gần ga."],["会社へ行きます。","Tôi đi đến công ty."],["兄は会社で働きます。","Anh trai tôi làm việc ở công ty."],["会社は大きいです。","Công ty to."],["会社を休みます。","Tôi nghỉ làm ở công ty."]]},{"word":"うち","reading":"うち","meaning":"nhà","hanViet":"","lesson":3,"ex":[["うちは駅から近いです。","Nhà tôi gần ga."],["うちは小さいです。","Nhà tôi nhỏ."],["うちでテレビを見ます。","Tôi xem tivi ở nhà."],["うちへ帰ります。","Tôi về nhà."],["うちの近くに公園があります。","Gần nhà tôi có công viên."]]},{"word":"電話","reading":"でんわ","meaning":"Điện thoại","hanViet":"ĐIỆN THOẠI","lesson":3,"ex":[["電話で友達と話します。","Tôi nói chuyện với bạn qua điện thoại."],["電話をかけます。","Tôi gọi điện thoại."],["母に電話をかけました。","Tôi đã gọi điện cho mẹ."],["電話番号は何番ですか。","Số điện thoại là số mấy?"],["電話で先生と話しました。","Tôi đã nói chuyện với thầy qua điện thoại."]]},{"word":"靴","reading":"くつ","meaning":"Giày","hanViet":"NGOA","lesson":3,"ex":[["靴は玄関にあります。","Giày ở cửa ra vào."],["靴を買いました。","Tôi đã mua giày."],["この靴は新しいです。","Đôi giày này mới."],["新しい靴を買いました。","Tôi đã mua giày mới."],["靴は安いです。","Giày rẻ."]]},{"word":"たばこ","reading":"たばこ","meaning":"thuốc lá","hanViet":"","lesson":3,"ex":[["ここでは、たばこを吸ってはいけません。","Ở đây không được hút thuốc."],["たばこを吸います。","Tôi hút thuốc lá."],["父はたばこを吸いません。","Bố tôi không hút thuốc."],["たばこは体に悪いです。","Thuốc lá có hại cho sức khỏe."],["ここでたばこを吸ってもいいですか。","Tôi hút thuốc ở đây được không?"]]},{"word":"売り場","reading":"うりば","meaning":"Quầy bán hàng","hanViet":"MẠI TRƯỜNG","lesson":3,"ex":[["売り場は二階にあります。","Quầy bán hàng ở tầng hai."],["売り場で靴を買います。","Tôi mua giày ở quầy bán hàng."],["売り場はどこですか。","Quầy bán hàng ở đâu?"],["売り場は広いです。","Quầy bán hàng rộng."],["本の売り場は三階です。","Quầy bán sách ở tầng ba."]]},{"word":"地下","reading":"ちか","meaning":"Tầng hầm, dưới lòng đất","hanViet":"ĐỊA HẠ","lesson":3,"ex":[["駐車場は地下にあります。","Bãi đỗ xe ở tầng hầm."],["地下に店があります。","Dưới tầng hầm có cửa hàng."],["地下で買い物をします。","Tôi mua sắm ở tầng hầm."],["地下は暗いです。","Tầng hầm tối."],["地下に食堂があります。","Dưới tầng hầm có nhà ăn."]]},{"word":"～階","reading":"～かい","meaning":"～lần, tầng lầu","hanViet":"HỒI","lesson":3,"ex":[["私の部屋は五階にあります。","Phòng của tôi ở tầng năm."],["会社は四階です。","Công ty ở tầng bốn."],["教室は二階にあります。","Phòng học ở tầng hai."],["三階にトイレがあります。","Ở tầng ba có nhà vệ sinh."],["うちは一階です。","Nhà tôi ở tầng một."]]},{"word":"～円","reading":"～えん","meaning":"~ yên","hanViet":"VIÊN","lesson":3,"ex":[["この本は千円です。","Cuốn sách này giá một nghìn yên."],["このりんごは百円です。","Quả táo này giá một trăm yên."],["コーヒーは三百円です。","Cà phê giá ba trăm yên."],["このかばんは五千円です。","Cái cặp này giá năm nghìn yên."],["切手は八十円です。","Tem giá tám mươi yên."]]},{"word":"いくら","reading":"いくら","meaning":"bao nhiêu","hanViet":"","lesson":3,"ex":[["この時計はいくらですか。","Cái đồng hồ này giá bao nhiêu?"],["この本はいくらですか。","Cuốn sách này giá bao nhiêu?"],["かばんはいくらですか。","Cái cặp giá bao nhiêu?"],["いくらですか。","Giá bao nhiêu?"],["全部でいくらですか。","Tổng cộng bao nhiêu tiền?"]]},{"word":"百","reading":"ひゃく","meaning":"một trăm","hanViet":"BÁCH","lesson":3,"ex":[["このボールペンは百円です。","Cây bút bi này giá một trăm yên."],["百円でりんごを買いました。","Tôi đã mua táo với giá một trăm yên."],["百円あります。","Tôi có một trăm yên."],["この本は百円です。","Cuốn sách này giá một trăm yên."],["百円を払いました。","Tôi đã trả một trăm yên."]]},{"word":"千","reading":"せん","meaning":"một nghìn","hanViet":"THIÊN","lesson":3,"ex":[["千円で本を買いました。","Tôi đã mua sách với giá một nghìn yên."],["千円あります。","Tôi có một nghìn yên."],["千円でかばんを買いました。","Tôi đã mua cặp với giá một nghìn yên."],["千円を払いました。","Tôi đã trả một nghìn yên."],["この本は千五百円です。","Quyển sách này giá 1500 yên."]]},{"word":"万","reading":"まん","meaning":"mười nghìn","hanViet":"VẠN","lesson":3,"ex":[["このカメラは三万円です。","Cái máy ảnh này giá ba mươi nghìn yên."],["一万円あります。","Tôi có mười nghìn yên."],["この自転車は二万円です。","Chiếc xe đạp này giá hai mươi nghìn yên."],["一万円を払いました。","Tôi đã trả mười nghìn yên."],["このテレビは五万円です。","Cái tivi này giá năm mươi nghìn yên."]]},{"word":"すみません","reading":"すみません","meaning":"xin lỗi","hanViet":"","lesson":3,"ex":[["すみません、トイレはどこですか。","Xin lỗi, nhà vệ sinh ở đâu?"],["すみません、銀行はどこですか。","Xin lỗi, ngân hàng ở đâu?"],["すみません、もう一度お願いします。","Xin lỗi, xin hãy nói lại lần nữa."],["すみません、わかりません。","Xin lỗi, tôi không hiểu."],["すみません、この本を見せてください。","Xin lỗi, cho tôi xem cuốn sách này."]]},{"word":"～でございます","reading":"～でございます","meaning":"(cách nói lịch sự của 「です」)","hanViet":"","lesson":3,"ex":[["こちらは受付でございます。","Đây là quầy lễ tân."],["こちらは教室でございます。","Đây là phòng học."],["こちらは事務所でございます。","Đây là văn phòng."],["あちらは食堂でございます。","Đằng kia là nhà ăn."],["ここは学校でございます。","Đây là trường học."]]},{"word":"駐車場","reading":"ちゅうしゃじょう","meaning":"Bãi đỗ xe","hanViet":"TRÚ XA TRƯỜNG","lesson":3,"ex":[["駐車場はあそこです。","Bãi đỗ xe ở đằng kia."],["駐車場は地下です。","Bãi đỗ xe ở tầng hầm."],["駐車場に車があります。","Trong bãi đỗ xe có xe ô tô."],["駐車場は広いです。","Bãi đỗ xe rộng."],["駐車場はどこですか。","Bãi đỗ xe ở đâu?"]]},{"word":"食料品","reading":"しょくりょうひん","meaning":"thực phẩm","hanViet":"THỰC","lesson":3,"ex":[["食料品は地下にあります。","Thực phẩm ở tầng hầm."],["食料品を買います。","Tôi mua thực phẩm."],["食料品は一階です。","Thực phẩm ở tầng một."],["食料品売り場で買い物をします。","Tôi mua sắm ở quầy thực phẩm."],["食料品は安いです。","Thực phẩm rẻ."]]},{"word":"化粧品","reading":"けしょうひん","meaning":"mỹ phẩm","hanViet":"HÓA TRANG PHẨM","lesson":3,"ex":[["化粧品は一階にあります。","Mỹ phẩm ở tầng một."],["化粧品を買いました。","Tôi đã mua mỹ phẩm."],["化粧品は二階です。","Mỹ phẩm ở tầng hai."],["母は化粧品が好きです。","Mẹ tôi thích mỹ phẩm."],["化粧品は高いです。","Mỹ phẩm đắt."]]},{"word":"婦人服","reading":"ふじんふく","meaning":"quần áo phụ nữ","hanViet":"NHÂN","lesson":3,"ex":[["婦人服は三階です。","Quần áo phụ nữ ở tầng ba."],["婦人服を買います。","Tôi mua quần áo phụ nữ."],["婦人服は四階にあります。","Quần áo phụ nữ ở tầng bốn."],["婦人服売り場は広いです。","Quầy quần áo phụ nữ rộng."],["母は婦人服を見ます。","Mẹ tôi xem quần áo phụ nữ."]]},{"word":"紳士服","reading":"しんしふく","meaning":"trang phục nam giới","hanViet":"THÂN SĨ PHỤC","lesson":3,"ex":[["紳士服は二階です。","Trang phục nam giới ở tầng hai."],["紳士服を買いました。","Tôi đã mua trang phục nam giới."],["紳士服は三階にあります。","Trang phục nam giới ở tầng ba."],["父は紳士服が好きです。","Bố tôi thích trang phục nam giới."],["紳士服売り場はどこですか。","Quầy trang phục nam giới ở đâu?"]]},{"word":"家具","reading":"かぐ","meaning":"Đồ nội thất","hanViet":"GIA CỤ","lesson":3,"ex":[["家具は五階にあります。","Đồ nội thất ở tầng năm."],["家具を買います。","Tôi mua đồ nội thất."],["この家具は新しいです。","Đồ nội thất này mới."],["家具は高いです。","Đồ nội thất đắt."],["家具売り場は四階です。","Quầy đồ nội thất ở tầng bốn."]]},{"word":"食器","reading":"しょっき","meaning":"bát đĩa, đồ dùng ăn uống","hanViet":"THỰC KHÍ","lesson":3,"ex":[["食器は四階です。","Bát đĩa ở tầng bốn."],["食器を買いました。","Tôi đã mua bát đĩa."],["食器は三階にあります。","Bát đĩa ở tầng ba."],["この食器はきれいです。","Bát đĩa này đẹp."],["食器を洗います。","Tôi rửa bát đĩa."]]},{"word":"電気製品","reading":"でんきせいひん","meaning":"đồ điện","hanViet":"ĐIỆN KHÍ","lesson":3,"ex":[["電気製品は地下にあります。","Đồ điện ở tầng hầm."],["電気製品を買います。","Tôi mua đồ điện."],["電気製品は一階です。","Đồ điện ở tầng một."],["電気製品は高いです。","Đồ điện đắt."],["電気製品売り場はどこですか。","Quầy đồ điện ở đâu?"]]},{"word":"子ども服","reading":"こどもふく","meaning":"quần áo trẻ em","hanViet":"TỬ","lesson":3,"ex":[["子ども服は六階です。","Quần áo trẻ em ở tầng sáu."],["子ども服を買いました。","Tôi đã mua quần áo trẻ em."],["子ども服は五階にあります。","Quần áo trẻ em ở tầng năm."],["子ども服は安いです。","Quần áo trẻ em rẻ."],["子ども服売り場は広いです。","Quầy quần áo trẻ em rộng."]]},{"word":"おもちゃ","reading":"おもちゃ","meaning":"đồ chơi","hanViet":"","lesson":3,"ex":[["子どもにおもちゃを買いました。","Tôi đã mua đồ chơi cho con."],["おもちゃで遊びます。","Tôi chơi với đồ chơi."],["このおもちゃは新しいです。","Đồ chơi này mới."],["おもちゃはどこですか。","Đồ chơi ở đâu?"],["子どもはおもちゃが好きです。","Trẻ em thích đồ chơi."]]},{"word":"文房具","reading":"ぶんぼうぐ","meaning":"văn phòng phẩm","hanViet":"","lesson":3,"ex":[["文房具は三階です。","Văn phòng phẩm ở tầng ba."],["文房具を買います。","Tôi mua văn phòng phẩm."],["文房具は二階にあります。","Văn phòng phẩm ở tầng hai."],["文房具売り場でボールペンを買いました。","Tôi đã mua bút bi ở quầy văn phòng phẩm."],["文房具は安いです。","Văn phòng phẩm rẻ."]]},{"word":"スポーツ用品","reading":"スポーツようひん","meaning":"dụng cụ thể thao","hanViet":"","lesson":3,"ex":[["スポーツ用品は四階です。","Dụng cụ thể thao ở tầng bốn."],["スポーツ用品を買います。","Tôi mua dụng cụ thể thao."],["スポーツ用品は三階にあります。","Dụng cụ thể thao ở tầng ba."],["スポーツ用品は高いです。","Dụng cụ thể thao đắt."],["スポーツ用品売り場はどこですか。","Quầy dụng cụ thể thao ở đâu?"]]},{"word":"旅行用品","reading":"りょこうようひん","meaning":"đồ dùng du lịch","hanViet":"HÀNH","lesson":3,"ex":[["旅行用品は五階です。","Đồ dùng du lịch ở tầng năm."],["旅行用品を買いました。","Tôi đã mua đồ dùng du lịch."],["旅行用品は四階にあります。","Đồ dùng du lịch ở tầng bốn."],["旅行用品は便利です。","Đồ dùng du lịch tiện lợi."],["旅行用品売り場は広いです。","Quầy đồ dùng du lịch rộng."]]},{"word":"眼鏡","reading":"めがね","meaning":"Kính mắt, kính đeo","hanViet":"NHÃN KÍNH","lesson":3,"ex":[["私は眼鏡をかけます。","Tôi đeo kính."],["眼鏡を買いました。","Tôi đã mua kính."],["この眼鏡は新しいです。","Cái kính này mới."],["眼鏡をかけますか。","Bạn có đeo kính không?"],["眼鏡はどこですか。","Kính ở đâu?"]]},{"word":"催し物会場","reading":"もよおしものかいじょう","meaning":"địa điểm tổ chức sự kiện","hanViet":"VẬT","lesson":3,"ex":[["催し物会場は七階です。","Địa điểm tổ chức sự kiện ở tầng bảy."],["催し物会場はどこですか。","Địa điểm tổ chức sự kiện ở đâu?"],["催し物会場でコンサートがあります。","Ở địa điểm tổ chức sự kiện có buổi hòa nhạc."],["催し物会場は広いです。","Địa điểm tổ chức sự kiện rộng."],["催し物会場は八階です。","Địa điểm tổ chức sự kiện ở tầng tám."]]},{"word":"屋上","reading":"おくじょう","meaning":"Sân thượng, mái nhà","hanViet":"ỐC THƯỢNG","lesson":3,"ex":[["屋上は広いです。","Sân thượng rộng."],["屋上で遊びます。","Tôi chơi trên sân thượng."],["屋上は明るいです。","Sân thượng sáng sủa."],["屋上に花があります。","Trên sân thượng có hoa."],["屋上へ行きます。","Tôi đi lên sân thượng."]]},{"word":"遊園地","reading":"ゆうえんち","meaning":"Công viên giải trí","hanViet":"DU VIÊN ĐỊA","lesson":3,"ex":[["遊園地で遊びます。","Tôi chơi ở công viên giải trí."],["遊園地へ行きます。","Tôi đi đến công viên giải trí."],["遊園地は楽しいです。","Công viên giải trí vui."],["子どもと遊園地へ行きました。","Tôi đã đi công viên giải trí cùng con."],["遊園地は大きいです。","Công viên giải trí to."]]},{"word":"ここ","reading":"ここ","meaning":"ở đây","hanViet":"","lesson":3,"ex":[["ここは学校です。","Đây là trường học."],["ここは教室です。","Đây là phòng học."],["ここに本があります。","Ở đây có sách."],["ここで待ってください。","Xin hãy đợi ở đây."],["ここは静かです。","Ở đây yên tĩnh."]]},{"word":"そこ","reading":"そこ","meaning":"ở đó","hanViet":"","lesson":3,"ex":[["本はそこにあります。","Cuốn sách ở đó."],["そこは会社です。","Đó là công ty."],["そこに座ってください。","Xin hãy ngồi ở đó."],["そこはどこですか。","Đó là đâu?"],["そこは静かです。","Ở đó yên tĩnh."]]},{"word":"あそこ","reading":"あそこ","meaning":"ở đằng kia (xa người nói và người nghe)","hanViet":"","lesson":3,"ex":[["あそこは駅です。","Đằng kia là nhà ga."],["あそこは学校です。","Đằng kia là trường học."],["あそこに銀行があります。","Đằng kia có ngân hàng."],["あそこは遠いです。","Đằng kia xa."],["あそこに車があります。","Đằng kia có xe ô tô."]]},{"word":"どこ","reading":"どこ","meaning":"ở đâu","hanViet":"","lesson":3,"ex":[["すみません、駅はどこですか。","Xin lỗi, nhà ga ở đâu?"],["あなたはどこに住んでいますか。","Bạn sống ở đâu?"],["教室はどこですか。","Phòng học ở đâu?"],["どこへ行きますか。","Bạn đi đâu?"],["どこで買いましたか。","Bạn đã mua ở đâu?"]]},{"word":"こちら","reading":"こちら","meaning":"ở đây (cách nói lịch sự của ここ)","hanViet":"","lesson":3,"ex":[["こちらへどうぞ。","Mời anh đi lối này."],["こちらは先生です。","Đây là thầy giáo."],["こちらはわたしの友達の田中さんです。","Đây là bạn tôi, anh Tanaka."],["こちらに座ってください。","Xin mời ngồi ở đây."],["こちらは受付です。","Đây là quầy lễ tân."]]},{"word":"あちら","reading":"あちら","meaning":"ở kia (cách nói lịch sự của あちら)","hanViet":"","lesson":3,"ex":[["あちらは山田さんです。","Kia là anh Yamada."],["あちらは先生です。","Kia là thầy giáo."],["あちらはトイレです。","Kia là nhà vệ sinh."],["あちらに座ってください。","Xin mời ngồi ở đằng kia."],["あちらは駅です。","Kia là nhà ga."]]},{"word":"どちら","reading":"どちら","meaning":"ở đâu (cách nói lịch sự của どこ); cái nào (trong hai cái)","hanViet":"","lesson":3,"ex":[["すみません、トイレはどちらですか。","Xin lỗi, nhà vệ sinh ở đâu?"],["どちらが好きですか。","Bạn thích cái nào hơn?"],["すみません、駅はどちらですか。","Xin lỗi, nhà ga ở đâu?"],["どちらも好きです。","Tôi thích cả hai."],["どちらへ行きますか。","Bạn đi đâu?"]]},{"word":"ロビー","reading":"ロビー","meaning":"hành lang (lobby)","hanViet":"","lesson":3,"ex":[["ロビーは一階にあります。","Sảnh ở tầng một."],["ロビーで待ちます。","Tôi đợi ở sảnh."],["ロビーは広いです。","Sảnh rộng."],["ロビーで友達と会いました。","Tôi đã gặp bạn ở sảnh."],["ロビーはどこですか。","Sảnh ở đâu?"]]},{"word":"トイレ","reading":"トイレ","meaning":"nhà vệ sinh (toilet)","hanViet":"","lesson":3,"ex":[["トイレは二階にあります。","Nhà vệ sinh ở tầng hai."],["トイレはどこですか。","Nhà vệ sinh ở đâu?"],["トイレは一階です。","Nhà vệ sinh ở tầng một."],["トイレへ行きます。","Tôi đi vệ sinh."],["トイレはきれいです。","Nhà vệ sinh sạch đẹp."]]},{"word":"お手洗い","reading":"おてあらい","meaning":"nhà vệ sinh","hanViet":"THỦ","lesson":3,"ex":[["お手洗いはあちらです。","Nhà vệ sinh ở đằng kia."],["すみません、お手洗いはどこですか。","Xin lỗi, nhà vệ sinh ở đâu?"],["お手洗いは二階にあります。","Nhà vệ sinh ở tầng hai."],["お手洗いはここです。","Nhà vệ sinh ở đây."],["お手洗いはきれいです。","Nhà vệ sinh sạch đẹp."]]},{"word":"エレベーター","reading":"エレベーター","meaning":"thang máy (elevator)","hanViet":"","lesson":3,"ex":[["エレベーターはあそこです。","Thang máy ở đằng kia."],["エレベーターで三階へ行きます。","Tôi đi lên tầng ba bằng thang máy."],["エレベーターはここです。","Thang máy ở đây."],["エレベーターは便利です。","Thang máy tiện lợi."],["エレベーターはどこですか。","Thang máy ở đâu?"]]},{"word":"エスカレーター","reading":"エスカレーター","meaning":"thang cuốn (escalator)","hanViet":"","lesson":3,"ex":[["エスカレーターはここです。","Thang cuốn ở đây."],["エスカレーターで二階へ行きます。","Tôi đi lên tầng hai bằng thang cuốn."],["エスカレーターはあそこです。","Thang cuốn ở đằng kia."],["エスカレーターは便利です。","Thang cuốn tiện lợi."],["エスカレーターはどこですか。","Thang cuốn ở đâu?"]]},{"word":"自動販売機","reading":"じどうはんばいき","meaning":"Máy bán hàng tự động","hanViet":"TỰ ĐỘNG PHÁN MẠI CƠ","lesson":3,"ex":[["自動販売機でジュースを買います。","Tôi mua nước trái cây ở máy bán hàng tự động."],["自動販売機でコーヒーを買います。","Tôi mua cà phê ở máy bán hàng tự động."],["自動販売機はあそこです。","Máy bán hàng tự động ở đằng kia."],["自動販売機で水を買いました。","Tôi đã mua nước ở máy bán hàng tự động."],["自動販売機はどこですか。","Máy bán hàng tự động ở đâu?"]]},{"word":"ネクタイ","reading":"ネクタイ","meaning":"cà vạt (necktie)","hanViet":"","lesson":3,"ex":[["このネクタイはいくらですか。","Cái cà vạt này giá bao nhiêu?"],["ネクタイを買いました。","Tôi đã mua cà vạt."],["このネクタイは新しいです。","Cái cà vạt này mới."],["父にネクタイをあげました。","Tôi đã tặng cà vạt cho bố."],["ネクタイはいくらですか。","Cà vạt giá bao nhiêu?"]]},{"word":"ワイン","reading":"ワイン","meaning":"rượu vang (wine)","hanViet":"","lesson":3,"ex":[["ワインを飲みます。","Tôi uống rượu vang."],["ワインはおいしいです。","Rượu vang ngon."],["レストランでワインを飲みました。","Tôi đã uống rượu vang ở nhà hàng."],["ワインを買いました。","Tôi đã mua rượu vang."],["ワインを飲みません。","Tôi không uống rượu vang."]]},{"word":"何階","reading":"なんかい","meaning":"tầng mấy","hanViet":"HÀ","lesson":3,"ex":[["あなたの部屋は何階ですか。","Phòng của bạn ở tầng mấy?"],["会社は何階ですか。","Công ty ở tầng mấy?"],["教室は何階ですか。","Phòng học ở tầng mấy?"],["あなたのうちは何階ですか。","Nhà bạn ở tầng mấy?"],["事務所は何階ですか。","Văn phòng ở tầng mấy?"]]},{"word":"見せてください","reading":"みせてください","meaning":"xin cho xem ~","hanViet":"KIẾN","lesson":3,"ex":[["すみません、この時計を見せてください。","Xin lỗi, cho tôi xem cái đồng hồ này."],["この本を見せてください。","Cho tôi xem cuốn sách này."],["そのかばんを見せてください。","Cho tôi xem cái cặp đó."],["このカメラを見せてください。","Cho tôi xem cái máy ảnh này."],["その靴を見せてください。","Cho tôi xem đôi giày đó."]]},{"word":"ください","reading":"ください","meaning":"cho tôi [~]","hanViet":"","lesson":3,"ex":[["コーヒーをください。","Cho tôi cà phê."],["水をください。","Cho tôi nước."],["この本をください。","Cho tôi cuốn sách này."],["コーヒーと紅茶をください。","Cho tôi cà phê và trà."],["切手をください。","Cho tôi tem."]]},{"word":"じゃ","reading":"じゃ","meaning":"thế thì, vậy thì","hanViet":"","lesson":3,"ex":[["じゃ、帰ります。","Vậy thì, tôi về đây."],["じゃ、また来週。","Vậy thì, hẹn gặp lại tuần sau."],["じゃ、行きます。","Vậy thì, tôi đi đây."],["じゃ、始めます。","Vậy thì, chúng ta bắt đầu."],["じゃ、買い物に行きます。","Vậy thì, tôi đi mua sắm."]]},{"word":"起きます","reading":"おきます","meaning":"Thức dậy","hanViet":"KHỞI","lesson":4,"ex":[["毎朝６時に起きます。","Mỗi sáng tôi thức dậy lúc 6 giờ."],["朝、七時に起きます。","Buổi sáng tôi thức dậy lúc 7 giờ."],["毎日、六時に起きます。","Mỗi ngày tôi thức dậy lúc 6 giờ."],["早く起きました。","Tôi đã dậy sớm."],["あしたは早く起きます。","Ngày mai tôi sẽ dậy sớm."]]},{"word":"寝ます","reading":"ねます","meaning":"Ngủ, đi ngủ; nằm","hanViet":"TẨM","lesson":4,"ex":[["毎晩１１時に寝ます。","Mỗi tối tôi đi ngủ lúc 11 giờ."],["夜、十時に寝ます。","Buổi tối tôi đi ngủ lúc 10 giờ."],["毎日、十一時に寝ます。","Mỗi ngày tôi đi ngủ lúc 11 giờ."],["早く寝ました。","Tôi đã đi ngủ sớm."],["子どもは早く寝ます。","Trẻ em đi ngủ sớm."]]},{"word":"働きます","reading":"はたらきます","meaning":"Làm việc","hanViet":"ĐỘNG","lesson":4,"ex":[["父は会社で働きます。","Bố tôi làm việc ở công ty."],["わたしは会社で働きます。","Tôi làm việc ở công ty."],["毎日働きます。","Tôi làm việc mỗi ngày."],["母は病院で働きます。","Mẹ tôi làm việc ở bệnh viện."],["銀行で働きます。","Tôi làm việc ở ngân hàng."]]},{"word":"休みます","reading":"やすみます","meaning":"Nghỉ ngơi","hanViet":"HƯU","lesson":4,"ex":[["あした会社を休みます。","Ngày mai tôi nghỉ làm ở công ty."],["あした学校を休みます。","Ngày mai tôi nghỉ học ở trường."],["日曜日は休みます。","Chủ nhật tôi nghỉ."],["きょうはうちで休みます。","Hôm nay tôi nghỉ ngơi ở nhà."],["疲れましたから、休みます。","Vì tôi mệt nên tôi nghỉ ngơi."]]},{"word":"勉強します","reading":"べんきょうします","meaning":"học tập","hanViet":"MIỄN CƯỜNG","lesson":4,"ex":[["毎晩日本語を勉強します。","Mỗi tối tôi học tiếng Nhật."],["学校で日本語を勉強します。","Tôi học tiếng Nhật ở trường."],["毎日、漢字を勉強します。","Mỗi ngày tôi học chữ Hán."],["図書館で勉強します。","Tôi học ở thư viện."],["日本語を勉強したいです。","Tôi muốn học tiếng Nhật."]]},{"word":"終わります","reading":"おわります","meaning":"Kết thúc","hanViet":"CHUNG","lesson":4,"ex":[["仕事は５時に終わります。","Công việc kết thúc lúc 5 giờ."],["会議は三時に終わります。","Cuộc họp kết thúc lúc 3 giờ."],["仕事は六時に終わりました。","Công việc đã kết thúc lúc 6 giờ."],["仕事が終わってから、帰ります。","Sau khi công việc kết thúc, tôi về nhà."],["映画は九時に終わります。","Bộ phim kết thúc lúc 9 giờ."]]},{"word":"銀行","reading":"ぎんこう","meaning":"Ngân hàng","hanViet":"NGÂN HÀNH","lesson":4,"ex":[["銀行は駅の近くです。","Ngân hàng ở gần nhà ga."],["銀行へ行きます。","Tôi đi đến ngân hàng."],["銀行でお金を払います。","Tôi trả tiền ở ngân hàng."],["銀行はどこですか。","Ngân hàng ở đâu?"],["銀行は大きいです。","Ngân hàng to."]]},{"word":"郵便局","reading":"ゆうびんきょく","meaning":"Bưu điện","hanViet":"BƯU TIỆN CỤC","lesson":4,"ex":[["郵便局で切手を買います。","Tôi mua tem ở bưu điện."],["郵便局へ行きます。","Tôi đi đến bưu điện."],["郵便局は学校の前にあります。","Bưu điện ở trước trường học."],["郵便局はどこですか。","Bưu điện ở đâu?"],["郵便局は駅の近くにあります。","Bưu điện ở gần nhà ga."]]},{"word":"図書館","reading":"としょかん","meaning":"Thư viện","hanViet":"ĐỒ THƯ QUÁN","lesson":4,"ex":[["図書館で本を読みます。","Tôi đọc sách ở thư viện."],["図書館は学校の近くです。","Thư viện ở gần trường học."],["毎日、図書館で日本語を勉強します。","Mỗi ngày tôi học tiếng Nhật ở thư viện."],["友達と図書館へ行きます。","Tôi đi thư viện cùng bạn."],["図書館で雑誌を読みますか。","Bạn có đọc tạp chí ở thư viện không?"]]},{"word":"美術館","reading":"びじゅつかん","meaning":"bảo tàng mỹ thuật","hanViet":"MỸ THUẬT QUÁN","lesson":4,"ex":[["日曜日に美術館へ行きます。","Chủ nhật tôi đi bảo tàng mỹ thuật."],["美術館で絵を見ます。","Tôi xem tranh ở bảo tàng mỹ thuật."],["あした、母と美術館へ行きます。","Ngày mai tôi đi bảo tàng mỹ thuật cùng mẹ."],["美術館は駅の近くにあります。","Bảo tàng mỹ thuật ở gần nhà ga."],["美術館は大きいです。","Bảo tàng mỹ thuật lớn."]]},{"word":"今","reading":"いま","meaning":"Bây giờ","hanViet":"KIM","lesson":4,"ex":[["今、何時ですか。","Bây giờ là mấy giờ?"],["今、学校で勉強しています。","Bây giờ tôi đang học ở trường."],["今、雨が降っています。","Bây giờ trời đang mưa."],["今は忙しいです。","Bây giờ tôi bận."],["今、何をしていますか。","Bây giờ bạn đang làm gì?"]]},{"word":"～時","reading":"～じ","meaning":"~giờ","hanViet":"THỜI","lesson":4,"ex":[["毎朝７時に起きます。","Mỗi sáng tôi dậy lúc 7 giờ."],["仕事は9時から5時までです。","Công việc từ 9 giờ đến 5 giờ."],["会議は3時です。","Cuộc họp lúc 3 giờ."],["バスは何時に来ますか。","Xe buýt đến lúc mấy giờ?"],["わたしは10時に寝ます。","Tôi đi ngủ lúc 10 giờ."]]},{"word":"～分","reading":"～ふん","meaning":"～phút","hanViet":"PHÂN","lesson":4,"ex":[["学校まで１０分かかります。","Đến trường mất 10 phút."],["電車は5分で来ます。","Tàu điện đến sau 5 phút."],["うちから学校まで20分です。","Từ nhà đến trường mất 20 phút."],["休みは15分です。","Giờ nghỉ là 15 phút."],["3分、待ってください。","Xin hãy đợi 3 phút."]]},{"word":"半","reading":"はん","meaning":"Nửa (2 giờ rưỡi…)","hanViet":"BÁN","lesson":4,"ex":[["昼ごはんは１２時半です。","Bữa trưa lúc 12 giờ rưỡi."],["会議は2時半からです。","Cuộc họp bắt đầu lúc 2 giờ rưỡi."],["わたしは6時半に起きます。","Tôi dậy lúc 6 giờ rưỡi."],["映画は7時半です。","Phim lúc 7 giờ rưỡi."],["電車は9時半に来ます。","Tàu điện đến lúc 9 giờ rưỡi."]]},{"word":"何時","reading":"なんじ","meaning":"Mấy giờ","hanViet":"HÀ THỜI","lesson":4,"ex":[["会議は何時からですか。","Cuộc họp bắt đầu lúc mấy giờ?"],["電車は何時に来ますか。","Tàu điện đến lúc mấy giờ?"],["何時に寝ますか。","Bạn đi ngủ lúc mấy giờ?"],["晩ごはんは何時ですか。","Bữa tối lúc mấy giờ?"],["店は何時までですか。","Cửa hàng mở đến mấy giờ?"]]},{"word":"何分","reading":"なんぷん","meaning":"mấy phút","hanViet":"HÀ PHÂN","lesson":4,"ex":[["バスは何分で来ますか。","Xe buýt đến sau mấy phút nữa?"],["学校まで何分かかりますか。","Đến trường mất mấy phút?"],["歩いて何分ですか。","Đi bộ mất mấy phút?"],["昼休みは何分ですか。","Giờ nghỉ trưa dài mấy phút?"],["何分待っていますか。","Bạn đã đợi mấy phút rồi?"]]},{"word":"午前","reading":"ごぜん","meaning":"Buổi sáng (trước 12 giờ)","hanViet":"NGỌ TIỀN","lesson":4,"ex":[["午前は学校で勉強します。","Buổi sáng tôi học ở trường."],["午前は図書館で本を読みます。","Buổi sáng tôi đọc sách ở thư viện."],["午前10時に会議があります。","Lúc 10 giờ sáng có cuộc họp."],["午前、友達とテニスをします。","Buổi sáng tôi chơi quần vợt cùng bạn."],["午前は雨が降りました。","Buổi sáng trời đã mưa."]]},{"word":"午後","reading":"ごご","meaning":"Buổi chiều (sau 12 giờ)","hanViet":"NGỌ HẬU","lesson":4,"ex":[["午後は図書館へ行きます。","Buổi chiều tôi đi thư viện."],["午後はうちでテレビを見ます。","Buổi chiều tôi xem ti vi ở nhà."],["午後3時に友達に会います。","Lúc 3 giờ chiều tôi gặp bạn."],["午後、デパートで買い物をします。","Buổi chiều tôi mua sắm ở cửa hàng bách hóa."],["午後は天気がいいです。","Buổi chiều thời tiết đẹp."]]},{"word":"朝","reading":"あさ","meaning":"Buổi sáng","hanViet":"TRIỀU","lesson":4,"ex":[["朝、パンを食べます。","Buổi sáng tôi ăn bánh mì."],["朝、牛乳を飲みます。","Buổi sáng tôi uống sữa."],["朝、6時に起きます。","Buổi sáng tôi dậy lúc 6 giờ."],["朝は学校へ行きます。","Buổi sáng tôi đi học."],["朝、テレビでニュースを見ます。","Buổi sáng tôi xem tin tức trên ti vi."]]},{"word":"昼","reading":"ひる","meaning":"trưa","hanViet":"TRÚ","lesson":4,"ex":[["昼、レストランでごはんを食べます。","Buổi trưa tôi ăn cơm ở nhà hàng."],["昼、友達とごはんを食べます。","Buổi trưa tôi ăn cơm cùng bạn."],["昼は学校で勉強します。","Buổi trưa tôi học ở trường."],["昼、デパートへ行きます。","Buổi trưa tôi đi cửa hàng bách hóa."],["昼は暑いです。","Buổi trưa trời nóng."]]},{"word":"夜","reading":"よる","meaning":"Ban đêm, đêm","hanViet":"DẠ","lesson":4,"ex":[["夜、テレビを見ます。","Buổi tối tôi xem ti vi."],["夜、日本語を勉強します。","Buổi tối tôi học tiếng Nhật."],["夜、友達と電話で話します。","Buổi tối tôi nói chuyện điện thoại với bạn."],["夜は早く寝ます。","Buổi tối tôi đi ngủ sớm."],["夜、うちで音楽を聞きます。","Buổi tối tôi nghe nhạc ở nhà."]]},{"word":"晩","reading":"ばん","meaning":"tối","hanViet":"VÃN","lesson":4,"ex":[["晩ごはんは７時です。","Bữa tối lúc 7 giờ."],["晩ごはんはうちで食べます。","Bữa tối tôi ăn ở nhà."],["晩、友達と映画を見ます。","Buổi tối tôi xem phim cùng bạn."],["晩ごはんのあとで、散歩します。","Sau bữa tối, tôi đi dạo."],["晩、宿題をします。","Buổi tối tôi làm bài tập."]]},{"word":"おととい","reading":"おととい","meaning":"ngày hôm kia","hanViet":"","lesson":4,"ex":[["おととい、デパートへ行きました。","Hôm kia tôi đã đi cửa hàng bách hóa."],["おととい、友達に会いました。","Hôm kia tôi đã gặp bạn."],["おととい、映画を見ました。","Hôm kia tôi đã xem phim."],["おとといは休みでした。","Hôm kia là ngày nghỉ."],["おととい、雨が降りました。","Hôm kia trời đã mưa."]]},{"word":"きのう","reading":"きのう","meaning":"ngày hôm qua","hanViet":"","lesson":4,"ex":[["きのう、学校を休みました。","Hôm qua tôi đã nghỉ học."],["きのう、テニスをしました。","Hôm qua tôi đã chơi quần vợt."],["きのう、友達と買い物をしました。","Hôm qua tôi đã đi mua sắm cùng bạn."],["きのうは天気がよかったです。","Hôm qua thời tiết đẹp."],["きのう、図書館で本を読みました。","Hôm qua tôi đã đọc sách ở thư viện."]]},{"word":"きょう","reading":"きょう","meaning":"hôm nay","hanViet":"KIM NHẬT","lesson":4,"ex":[["きょうは金曜日です。","Hôm nay là thứ sáu."],["きょうは学校で試験があります。","Hôm nay ở trường có kỳ thi."],["きょう、学校へ行きます。","Hôm nay tôi đi học."],["きょうは忙しいです。","Hôm nay tôi bận."],["きょう、友達と映画を見ます。","Hôm nay tôi xem phim cùng bạn."]]},{"word":"あした","reading":"あした","meaning":"ngày mai","hanViet":"MINH NHẬT","lesson":4,"ex":[["あした、友達と映画を見ます。","Ngày mai tôi cùng bạn xem phim."],["あした、学校へ行きます。","Ngày mai tôi đi học."],["あしたは日曜日です。","Ngày mai là chủ nhật."],["あした、デパートで買い物をします。","Ngày mai tôi mua sắm ở cửa hàng bách hóa."],["あした、テニスをします。","Ngày mai tôi chơi quần vợt."]]},{"word":"あさって","reading":"あさって","meaning":"ngày mốt","hanViet":"","lesson":4,"ex":[["あさって、山田さんに会います。","Ngày mốt tôi gặp anh Yamada."],["あさって、友達と映画を見ます。","Ngày mốt tôi xem phim cùng bạn."],["あさっては土曜日です。","Ngày mốt là thứ bảy."],["あさって、学校へ行きます。","Ngày mốt tôi đi học."],["あさって、テニスをします。","Ngày mốt tôi chơi quần vợt."]]},{"word":"今朝","reading":"けさ","meaning":"Sáng nay","hanViet":"KIM TRIỀU","lesson":4,"ex":[["今朝、６時に起きました。","Sáng nay tôi đã dậy lúc 6 giờ."],["今朝、パンを食べました。","Sáng nay tôi đã ăn bánh mì."],["今朝、雨が降りました。","Sáng nay trời đã mưa."],["今朝は忙しかったです。","Sáng nay tôi bận."],["今朝、友達に会いました。","Sáng nay tôi đã gặp bạn."]]},{"word":"今晩","reading":"こんばん","meaning":"tối nay","hanViet":"KIM VÃN","lesson":4,"ex":[["今晩、うちでテレビを見ます。","Tối nay tôi xem ti vi ở nhà."],["今晩、友達とごはんを食べます。","Tối nay tôi ăn cơm cùng bạn."],["今晩は映画を見ます。","Tối nay tôi xem phim."],["今晩、うちで本を読みます。","Tối nay tôi đọc sách ở nhà."],["今晩、早く寝ます。","Tối nay tôi đi ngủ sớm."]]},{"word":"休み","reading":"やすみ","meaning":"nghỉ ngơi (danh từ)","hanViet":"HƯU","lesson":4,"ex":[["あしたは休みです。","Ngày mai là ngày nghỉ."],["きょうは休みです。","Hôm nay là ngày nghỉ."],["あさっては休みです。","Ngày mốt là ngày nghỉ."],["休みはうちで本を読みます。","Ngày nghỉ tôi đọc sách ở nhà."],["休みに友達とテニスをします。","Ngày nghỉ tôi chơi quần vợt cùng bạn."]]},{"word":"昼休み","reading":"ひるやすみ","meaning":"Nghỉ trưa","hanViet":"NGỌ HƯU","lesson":4,"ex":[["昼休みは１２時から１時までです。","Giờ nghỉ trưa từ 12 giờ đến 1 giờ."],["昼休みにごはんを食べます。","Giờ nghỉ trưa tôi ăn cơm."],["昼休みは1時間です。","Giờ nghỉ trưa là 1 tiếng."],["昼休みに友達と話します。","Giờ nghỉ trưa tôi nói chuyện với bạn."],["昼休みは図書館で本を読みます。","Giờ nghỉ trưa tôi đọc sách ở thư viện."]]},{"word":"毎朝","reading":"まいあさ","meaning":"Mỗi buổi sáng","hanViet":"MỖI TRIỀU","lesson":4,"ex":[["毎朝、牛乳を飲みます。","Mỗi sáng tôi uống sữa."],["毎朝、6時に起きます。","Mỗi sáng tôi dậy lúc 6 giờ."],["毎朝、パンを食べます。","Mỗi sáng tôi ăn bánh mì."],["毎朝、学校へ歩いて行きます。","Mỗi sáng tôi đi bộ đến trường."],["毎朝、テレビでニュースを見ます。","Mỗi sáng tôi xem tin tức trên ti vi."]]},{"word":"毎晩","reading":"まいばん","meaning":"mỗi tối, hằng đêm","hanViet":"MỖI VÃN","lesson":4,"ex":[["毎晩、シャワーを浴びます。","Mỗi tối tôi tắm vòi sen."],["毎晩、日本語を勉強します。","Mỗi tối tôi học tiếng Nhật."],["毎晩、10時に寝ます。","Mỗi tối tôi đi ngủ lúc 10 giờ."],["毎晩、うちでテレビを見ます。","Mỗi tối tôi xem ti vi ở nhà."],["毎晩、本を読みます。","Mỗi tối tôi đọc sách."]]},{"word":"毎日","reading":"まいにち","meaning":"Mỗi ngày, hằng ngày","hanViet":"MỖI NHẬT","lesson":4,"ex":[["毎日、日本語を勉強します。","Mỗi ngày tôi học tiếng Nhật."],["毎日、学校へ行きます。","Mỗi ngày tôi đi học."],["毎日、電車で会社へ行きます。","Mỗi ngày tôi đi làm bằng tàu điện."],["毎日、テレビを見ます。","Mỗi ngày tôi xem ti vi."],["毎日、8時間働きます。","Mỗi ngày tôi làm việc 8 tiếng."]]},{"word":"月曜日","reading":"げつようび","meaning":"Thứ hai","hanViet":"NGUYỆT DIỆU NHẬT","lesson":4,"ex":[["月曜日は学校へ行きます。","Thứ hai tôi đi học."],["月曜日はテニスをします。","Thứ hai tôi chơi quần vợt."],["月曜日は忙しいです。","Thứ hai tôi bận."],["月曜日に友達に会います。","Thứ hai tôi gặp bạn."],["月曜日は図書館へ行きます。","Thứ hai tôi đi thư viện."]]},{"word":"火曜日","reading":"かようび","meaning":"Thứ ba","hanViet":"HỎA DIỆU NHẬT","lesson":4,"ex":[["火曜日はテニスをします。","Thứ ba tôi chơi quần vợt."],["火曜日は学校へ行きます。","Thứ ba tôi đi học."],["火曜日は買い物をします。","Thứ ba tôi đi mua sắm."],["火曜日に映画を見ます。","Thứ ba tôi xem phim."],["火曜日は友達に会います。","Thứ ba tôi gặp bạn."]]},{"word":"水曜日","reading":"すいようび","meaning":"Thứ tư","hanViet":"THỦY DIỆU NHẬT","lesson":4,"ex":[["水曜日は図書館へ行きます。","Thứ tư tôi đi thư viện."],["水曜日はテニスをします。","Thứ tư tôi chơi quần vợt."],["水曜日は学校へ行きます。","Thứ tư tôi đi học."],["水曜日に買い物をします。","Thứ tư tôi đi mua sắm."],["水曜日は休みです。","Thứ tư là ngày nghỉ."]]},{"word":"木曜日","reading":"もくようび","meaning":"Thứ năm","hanViet":"MỘC DIỆU NHẬT","lesson":4,"ex":[["木曜日は買い物をします。","Thứ năm tôi đi mua sắm."],["木曜日は学校へ行きます。","Thứ năm tôi đi học."],["木曜日はテニスをします。","Thứ năm tôi chơi quần vợt."],["木曜日に友達に会います。","Thứ năm tôi gặp bạn."],["木曜日は映画を見ます。","Thứ năm tôi xem phim."]]},{"word":"金曜日","reading":"きんようび","meaning":"Thứ sáu","hanViet":"KIM DIỆU NHẬT","lesson":4,"ex":[["金曜日は友達に会います。","Thứ sáu tôi gặp bạn."],["金曜日は学校へ行きます。","Thứ sáu tôi đi học."],["金曜日は買い物をします。","Thứ sáu tôi đi mua sắm."],["金曜日にテニスをします。","Thứ sáu tôi chơi quần vợt."],["金曜日は映画を見ます。","Thứ sáu tôi xem phim."]]},{"word":"土曜日","reading":"どようび","meaning":"Thứ bảy","hanViet":"THỔ DIỆU NHẬT","lesson":4,"ex":[["土曜日はデパートへ行きます。","Thứ bảy tôi đi cửa hàng bách hóa."],["土曜日はテニスをします。","Thứ bảy tôi chơi quần vợt."],["土曜日は友達に会います。","Thứ bảy tôi gặp bạn."],["土曜日に映画を見ます。","Thứ bảy tôi xem phim."],["土曜日は休みです。","Thứ bảy là ngày nghỉ."]]},{"word":"日曜日","reading":"にちようび","meaning":"Chủ nhật","hanViet":"NHẬT DIỆU NHẬT","lesson":4,"ex":[["日曜日は休みです。","Chủ nhật là ngày nghỉ."],["日曜日はテニスをします。","Chủ nhật tôi chơi quần vợt."],["日曜日は友達に会います。","Chủ nhật tôi gặp bạn."],["日曜日に映画を見ます。","Chủ nhật tôi xem phim."],["日曜日はうちで本を読みます。","Chủ nhật tôi đọc sách ở nhà."]]},{"word":"番号","reading":"ばんごう","meaning":"Số (điện thoại, phòng…)","hanViet":"PHIÊN HỌ","lesson":4,"ex":[["部屋の番号は２０５です。","Số phòng là 205."],["暗証番号は1234です。","Mã số bí mật là 1234."],["部屋の番号を教えてください。","Xin hãy cho tôi biết số phòng."],["番号がわかりません。","Tôi không biết số."],["わたしの部屋の番号は101です。","Số phòng của tôi là 101."]]},{"word":"何番","reading":"なんばん","meaning":"số mấy","hanViet":"HÀ","lesson":4,"ex":[["田中さんの部屋は何番ですか。","Phòng của anh Tanaka là số mấy?"],["あなたの部屋は何番ですか。","Phòng của bạn là số mấy?"],["バスは何番ですか。","Xe buýt số mấy?"],["教室は何番ですか。","Phòng học là số mấy?"],["何番の電車に乗りますか。","Bạn đi tàu điện số mấy?"]]},{"word":"～から","reading":"～から","meaning":"từ ~","hanViet":"","lesson":4,"ex":[["駅からうちまで10分です。","Từ ga đến nhà mất 10 phút."],["学校からうちまで歩いて15分です。","Từ trường đến nhà đi bộ mất 15 phút."],["9時から仕事をします。","Tôi làm việc từ 9 giờ."],["月曜日から金曜日まで学校へ行きます。","Tôi đi học từ thứ hai đến thứ sáu."],["わたしはベトナムから来ました。","Tôi đến từ Việt Nam."]]},{"word":"～まで","reading":"～まで","meaning":"~ đến","hanViet":"","lesson":4,"ex":[["仕事は５時までです。","Công việc đến 5 giờ."],["学校は3時までです。","Trường học đến 3 giờ."],["駅まで歩きます。","Tôi đi bộ đến ga."],["図書館までバスで行きます。","Tôi đi xe buýt đến thư viện."],["晩ごはんまで勉強します。","Tôi học đến bữa tối."]]},{"word":"～と～","reading":"～と～","meaning":"~ và (dùng để nối hai danh từ)","hanViet":"","lesson":4,"ex":[["パンと牛乳を買います。","Tôi mua bánh mì và sữa."],["りんごとみかんを食べます。","Tôi ăn táo và quýt."],["父と母は日本にいます。","Bố và mẹ tôi ở Nhật Bản."],["友達と先生とテニスをします。","Tôi chơi quần vợt cùng bạn và thầy giáo."],["本と雑誌を読みます。","Tôi đọc sách và tạp chí."]]},{"word":"そちら","reading":"そちら","meaning":"ở đó (cách nói lịch sự của そこ)","hanViet":"","lesson":4,"ex":[["そちらは郵便局ですか。","Ở đó có phải là bưu điện không?"],["そちらは学校ですか。","Ở đó có phải là trường học không?"],["そちらへ行きます。","Tôi đi đến chỗ đó."],["そちらに電話します。","Tôi gọi điện đến đó."],["そちらは静かですか。","Ở đó có yên tĩnh không?"]]},{"word":"大変ですね","reading":"たいへんですね","meaning":"vất vả nhỉ","hanViet":"ĐẠI","lesson":4,"ex":[["毎日９時まで働きます。大変ですね。","Mỗi ngày tôi làm việc đến 9 giờ. Vất vả nhỉ."],["2時間、歩きました。大変ですね。","Tôi đã đi bộ 2 tiếng.Vất vả nhỉ."],["毎日6時に起きます。大変ですね。","Mỗi ngày tôi dậy lúc 6 giờ.Vất vả nhỉ."],["仕事が忙しいです。大変ですね。","Công việc bận.Vất vả nhỉ."],["試験が難しいです。大変ですね。","Kỳ thi khó.Vất vả nhỉ."]]},{"word":"ええと","reading":"ええと","meaning":"Ừ, à, để tôi xem nào","hanViet":"","lesson":4,"ex":[["ええと、電話番号は０３ー１２３４ー５６７８です。","Ừ, số điện thoại là 03-1234-5678."],["ええと、学校は9時からです。","Ừ, trường học bắt đầu lúc 9 giờ."],["ええと、わたしの部屋は203です。","Ừ, phòng của tôi là số 203."],["ええと、あしたは金曜日です。","Ừ, ngày mai là thứ sáu."],["ええと、会議は2時です。","Ừ, cuộc họp lúc 2 giờ."]]},{"word":"お願いします","reading":"おねがいします","meaning":"Nhờ anh/chị. Phiền anh/chị. Xin vui lòng giúp đỡ","hanViet":"","lesson":4,"ex":[["コーヒーをお願いします。","Cho tôi một ly cà phê."],["紅茶をお願いします。","Cho tôi một ly trà đen."],["切符をお願いします。","Cho tôi một vé."],["これをお願いします。","Cho tôi cái này."],["電話番号をお願いします。","Cho tôi xin số điện thoại."]]},{"word":"かしこまりました","reading":"かしこまりました","meaning":"Đã hiểu rồi","hanViet":"","lesson":4,"ex":[["はい、かしこまりました。","Vâng, tôi đã hiểu."],["はい、かしこまりました。あした行きます。","Vâng, tôi đã hiểu.Ngày mai tôi sẽ đi."],["かしこまりました。9時に行きます。","Tôi đã hiểu.Tôi sẽ đi lúc 9 giờ."],["はい、かしこまりました。すぐ行きます。","Vâng, tôi đã hiểu.Tôi đi ngay."],["かしこまりました。電話します。","Tôi đã hiểu.Tôi sẽ gọi điện."]]},{"word":"お問い合わせの番号","reading":"おといあわせのばんごう","meaning":"Số điện thoại mà ông/ bà muốn hỏi","hanViet":"","lesson":4,"ex":[["お問い合わせの番号は何番ですか。","Số điện thoại ông/bà muốn hỏi là số mấy?"],["お問い合わせの番号を教えてください。","Xin hãy cho tôi biết số điện thoại ông/bà muốn hỏi."],["お問い合わせの番号は03ー1234ー5678です。","Số điện thoại muốn hỏi là 03-1234-5678."],["お問い合わせの番号がわかりません。","Tôi không biết số điện thoại muốn hỏi."],["お問い合わせの番号は何ですか。","Số điện thoại ông/bà muốn hỏi là số nào?"]]},{"word":"警察署","reading":"けいさつしょ","meaning":"Đồn cảnh sát, sở cảnh sát","hanViet":"CẢNH SÁT THỰ","lesson":4,"ex":[["警察署は駅の前です。","Đồn cảnh sát ở trước nhà ga."],["警察署は学校の近くです。","Đồn cảnh sát ở gần trường học."],["警察署へ行きます。","Tôi đi đến đồn cảnh sát."],["警察署はどこですか。","Đồn cảnh sát ở đâu?"],["警察署で働きます。","Tôi làm việc ở đồn cảnh sát."]]},{"word":"消防署","reading":"しょうぼうしょ","meaning":"Sở cứu hỏa, trạm phòng cháy","hanViet":"TIÊU PHÒNG THỰ","lesson":4,"ex":[["消防署は市役所の近くです。","Sở cứu hỏa ở gần tòa thị chính."],["消防署は病院の近くです。","Sở cứu hỏa ở gần bệnh viện."],["消防署はどこですか。","Sở cứu hỏa ở đâu?"],["消防署で働きます。","Tôi làm việc ở sở cứu hỏa."],["消防署は大きいです。","Sở cứu hỏa lớn."]]},{"word":"電話番号案内","reading":"でんわばんごうあんない","meaning":"tổng đài tra cứu số điện thoại","hanViet":"ĐIỆN THOẠI NỘI","lesson":4,"ex":[["電話番号案内は１０４番です。","Tổng đài tra cứu số điện thoại là số 104."],["電話番号案内に電話します。","Tôi gọi điện cho tổng đài tra cứu số điện thoại."],["電話番号案内で番号を調べます。","Tôi tra cứu số ở tổng đài tra cứu số điện thoại."],["電話番号案内は便利です。","Tổng đài tra cứu số điện thoại tiện lợi."],["電話番号案内に聞きます。","Tôi hỏi tổng đài tra cứu số điện thoại."]]},{"word":"デパート","reading":"デパート","meaning":"cửa hàng bách hóa","hanViet":"","lesson":4,"ex":[["日曜日にデパートで買い物をします。","Chủ nhật tôi mua sắm ở cửa hàng bách hóa."],["デパートで服を買います。","Tôi mua quần áo ở cửa hàng bách hóa."],["デパートは駅の近くです。","Cửa hàng bách hóa ở gần nhà ga."],["あした、デパートへ行きます。","Ngày mai tôi đi cửa hàng bách hóa."],["デパートは大きいです。","Cửa hàng bách hóa lớn."]]},{"word":"電話番号","reading":"でんわばんごう","meaning":"số điện thoại","hanViet":"ĐIỆN THOẠI PHIÊN HIỆU","lesson":4,"ex":[["わたしの電話番号は０９０ー１２３４ー５６７８です。","Số điện thoại của tôi là 090-1234-5678."],["田中さんの電話番号は何番ですか。","Số điện thoại của anh Tanaka là số mấy?"],["電話番号を教えてください。","Xin hãy cho tôi biết số điện thoại."],["電話番号がわかりません。","Tôi không biết số điện thoại."],["先生の電話番号を聞きます。","Tôi hỏi số điện thoại của thầy giáo."]]},{"word":"どうもありがとうございました","reading":"どうもありがとうございました","meaning":"Xin cám ơn ông/bà","hanViet":"","lesson":4,"ex":[["どうもありがとうございました。","Xin cảm ơn ông/bà rất nhiều."],["どうもありがとうございました。楽しかったです。","Cảm ơn ông/bà rất nhiều.Tôi đã rất vui."],["手伝ってくれて、どうもありがとうございました。","Cảm ơn ông/bà rất nhiều vì đã giúp tôi."],["きのうはどうもありがとうございました。","Hôm qua cảm ơn ông/bà rất nhiều."],["どうもありがとうございました。また会いましょう。","Cảm ơn ông/bà rất nhiều.Hẹn gặp lại."]]},{"word":"ありがとうございました","reading":"ありがとうございました","meaning":"Xin cám ơn ông/bà","hanViet":"","lesson":4,"ex":[["ありがとうございました。","Xin cảm ơn ông/bà."],["ありがとうございました。おいしかったです。","Cảm ơn ông/bà.Ngon lắm."],["きのうはありがとうございました。","Hôm qua cảm ơn ông/bà."],["教えてくれて、ありがとうございました。","Cảm ơn ông/bà vì đã chỉ cho tôi."],["ありがとうございました。またあした。","Cảm ơn ông/bà.Hẹn gặp lại ngày mai."]]},{"word":"行きます","reading":"いきます","meaning":"Đi","hanViet":"HÀNH","lesson":5,"ex":[["わたしは毎日電車で学校へ行きます。","Tôi đi học bằng tàu điện mỗi ngày."],["あした、友達とデパートへ行きます。","Ngày mai tôi đi cửa hàng bách hóa cùng bạn."],["毎日、自転車で学校へ行きます。","Mỗi ngày tôi đi học bằng xe đạp."],["日曜日に図書館へ行きます。","Chủ nhật tôi đi thư viện."],["来月、友達と日本へ行きます。","Tháng sau tôi đi Nhật Bản cùng bạn."]]},{"word":"来ます","reading":"きます","meaning":"Đến","hanViet":"LAI","lesson":5,"ex":[["田中さんはあした日本へ来ます。","Ngày mai anh Tanaka đến Nhật Bản."],["友達がうちへ来ます。","Bạn đến nhà tôi."],["先生が学校へ来ます。","Thầy giáo đến trường."],["来週、母が日本へ来ます。","Tuần sau mẹ tôi đến Nhật Bản."],["バスが来ます。","Xe buýt đến."]]},{"word":"帰ります","reading":"かえります","meaning":"Về nhà","hanViet":"QUY","lesson":5,"ex":[["わたしは毎日7時にうちへ帰ります。","Tôi về nhà lúc 7 giờ mỗi ngày."],["あした、国へ帰ります。","Ngày mai tôi về nước."],["学校のあとで、うちへ帰ります。","Sau giờ học, tôi về nhà."],["5時に会社から帰ります。","Lúc 5 giờ tôi từ công ty về nhà."],["友達といっしょに帰ります。","Tôi về cùng bạn."]]},{"word":"学校","reading":"がっこう","meaning":"Trường học","hanViet":"HỌC HIỆU","lesson":5,"ex":[["わたしの学校は駅の近くにあります。","Trường học của tôi ở gần nhà ga."],["学校は8時からです。","Trường học bắt đầu lúc 8 giờ."],["学校で漢字を習います。","Tôi học chữ Hán ở trường."],["学校は大きいです。","Trường học lớn."],["あした、学校を休みます。","Ngày mai tôi nghỉ học."]]},{"word":"駅","reading":"えき","meaning":"Nhà ga","hanViet":"DỊCH","lesson":5,"ex":[["駅の前に大きい店があります。","Trước nhà ga có một cửa hàng lớn."],["駅はうちの近くです。","Nhà ga ở gần nhà tôi."],["駅で友達に会います。","Tôi gặp bạn ở nhà ga."],["駅まで歩いて行きます。","Tôi đi bộ đến ga."],["駅の近くにデパートがあります。","Gần nhà ga có cửa hàng bách hóa."]]},{"word":"飛行機","reading":"ひこうき","meaning":"Máy bay","hanViet":"PHI HÀNH CƠ","lesson":5,"ex":[["飛行機で日本へ行きます。","Tôi đi Nhật Bản bằng máy bay."],["飛行機でベトナムへ行きます。","Tôi đi Việt Nam bằng máy bay."],["飛行機は速いです。","Máy bay nhanh."],["あした、飛行機に乗ります。","Ngày mai tôi đi máy bay."],["飛行機で旅行します。","Tôi đi du lịch bằng máy bay."]]},{"word":"船","reading":"ふね","meaning":"Thuyền, tàu","hanViet":"THUYỀN","lesson":5,"ex":[["わたしは船で旅行します。","Tôi đi du lịch bằng tàu."],["船で国へ帰ります。","Tôi về nước bằng tàu."],["船は大きいです。","Tàu lớn."],["あした、船に乗ります。","Ngày mai tôi đi tàu."],["船で海へ行きます。","Tôi đi biển bằng tàu."]]},{"word":"電車","reading":"でんしゃ","meaning":"Tàu điện","hanViet":"ĐIỆN XA","lesson":5,"ex":[["まいにち電車で学校へ行きます。","Mỗi ngày tôi đi học bằng tàu điện."],["電車は速いです。","Tàu điện nhanh."],["電車に乗って、会社へ行きます。","Tôi đi tàu điện đến công ty."],["電車は9時に来ます。","Tàu điện đến lúc 9 giờ."],["電車で会社へ行きます。","Tôi đi làm bằng tàu điện."]]},{"word":"地下鉄","reading":"ちかてつ","meaning":"Tàu điện ngầm","hanViet":"ĐỊA HẠ THIẾT","lesson":5,"ex":[["地下鉄で会社へ行きます。","Tôi đi làm bằng tàu điện ngầm."],["地下鉄で学校へ行きます。","Tôi đi học bằng tàu điện ngầm."],["地下鉄は速いです。","Tàu điện ngầm nhanh."],["地下鉄に乗ります。","Tôi đi tàu điện ngầm."],["地下鉄は便利です。","Tàu điện ngầm tiện lợi."]]},{"word":"新幹線","reading":"しんかんせん","meaning":"Tàu siêu tốc Shinkansen","hanViet":"TÂN CÁN TUYẾN","lesson":5,"ex":[["新幹線は速いです。","Tàu Shinkansen nhanh."],["新幹線で旅行します。","Tôi đi du lịch bằng tàu Shinkansen."],["新幹線に乗ります。","Tôi đi tàu Shinkansen."],["新幹線は便利です。","Tàu Shinkansen tiện lợi."],["新幹線は新しいです。","Tàu Shinkansen mới."]]},{"word":"自転車","reading":"じてんしゃ","meaning":"Xe đạp","hanViet":"TỰ CHUYỂN XA","lesson":5,"ex":[["わたしは自転車で学校へ行きます。","Tôi đi học bằng xe đạp."],["自転車で会社へ行きます。","Tôi đi làm bằng xe đạp."],["自転車は便利です。","Xe đạp tiện lợi."],["自転車に乗ります。","Tôi đi xe đạp."],["自転車は新しいです。","Xe đạp mới."]]},{"word":"歩いて","reading":"あるいて","meaning":"đi bộ","hanViet":"BỘ","lesson":5,"ex":[["わたしは歩いて学校へ行きます。","Tôi đi bộ đến trường."],["歩いて会社へ行きます。","Tôi đi bộ đi làm."],["駅からうちまで歩いて10分です。","Từ ga đến nhà đi bộ mất 10 phút."],["歩いて公園へ行きます。","Tôi đi bộ đến công viên."],["歩いて帰ります。","Tôi đi bộ về nhà."]]},{"word":"人","reading":"ひと","meaning":"Người","hanViet":"NHÂN","lesson":5,"ex":[["あの人は田中さんです。","Người đó là anh Tanaka."],["この会社には、人が二百人います。","Công ty này có 200 người."],["公園に人がたくさんいます。","Trong công viên có nhiều người."],["この人は友達です。","Người này là bạn tôi."],["あの人は有名です。","Người đó nổi tiếng."]]},{"word":"友達","reading":"ともだち","meaning":"Bạn bè","hanViet":"HỮU","lesson":5,"ex":[["わたしは友達と映画を見ます。","Tôi xem phim cùng bạn bè."],["友達は多いです。","Tôi có nhiều bạn."],["友達とテニスをします。","Tôi chơi quần vợt cùng bạn."],["友達に会います。","Tôi gặp bạn."],["友達といっしょに学校へ行きます。","Tôi đi học cùng bạn."]]},{"word":"彼","reading":"かれ","meaning":"Anh ấy, anh ta","hanViet":"BỈ","lesson":5,"ex":[["彼は日本の学生です。","Anh ấy là sinh viên Nhật Bản."],["彼は先生です。","Anh ấy là thầy giáo."],["彼はテニスが上手です。","Anh ấy chơi quần vợt giỏi."],["彼は毎日学校へ行きます。","Anh ấy đi học mỗi ngày."],["彼は日本語を勉強します。","Anh ấy học tiếng Nhật."]]},{"word":"彼女","reading":"かのじょ","meaning":"Cô ấy, bạn gái","hanViet":"BỈ NỮ","lesson":5,"ex":[["彼女は先生です。","Cô ấy là giáo viên."],["彼女は学生です。","Cô ấy là sinh viên."],["彼女は日本語が上手です。","Cô ấy giỏi tiếng Nhật."],["彼女は友達です。","Cô ấy là bạn tôi."],["彼女は毎日テニスをします。","Cô ấy chơi quần vợt mỗi ngày."]]},{"word":"家族","reading":"かぞく","meaning":"Gia đình","hanViet":"GIA TỘC","lesson":5,"ex":[["わたしの家族は4人です。","Gia đình tôi có 4 người."],["わたしの家族は日本にいます。","Gia đình tôi ở Nhật Bản."],["家族といっしょにごはんを食べます。","Tôi ăn cơm cùng gia đình."],["家族は5人です。","Gia đình tôi có 5 người."],["家族と旅行します。","Tôi đi du lịch cùng gia đình."]]},{"word":"一人で","reading":"ひとりで","meaning":"một mình","hanViet":"NHẤT NHÂN","lesson":5,"ex":[["わたしは一人で旅行します。","Tôi đi du lịch một mình."],["一人で映画を見ます。","Tôi xem phim một mình."],["一人で買い物をします。","Tôi đi mua sắm một mình."],["一人でごはんを食べます。","Tôi ăn cơm một mình."],["一人で日本語を勉強します。","Tôi học tiếng Nhật một mình."]]},{"word":"先週","reading":"せんしゅう","meaning":"tuần trước","hanViet":"TIÊN","lesson":5,"ex":[["先週、友達と映画を見ました。","Tuần trước, tôi đã xem phim cùng bạn bè."],["先週、テニスをしました。","Tuần trước tôi đã chơi quần vợt."],["先週は忙しかったです。","Tuần trước tôi bận."],["先週、学校を休みました。","Tuần trước tôi đã nghỉ học."],["先週、デパートで買い物をしました。","Tuần trước tôi đã mua sắm ở cửa hàng bách hóa."]]},{"word":"今週","reading":"こんしゅう","meaning":"Tuần này","hanViet":"KIM CHU","lesson":5,"ex":[["今週は忙しいです。","Tuần này tôi bận."],["今週、テニスをします。","Tuần này tôi chơi quần vợt."],["今週は天気がいいです。","Tuần này thời tiết đẹp."],["今週、友達に会います。","Tuần này tôi gặp bạn."],["今週、試験があります。","Tuần này có kỳ thi."]]},{"word":"来週","reading":"らいしゅう","meaning":"Tuần sau, tuần tới","hanViet":"LAI CHU","lesson":5,"ex":[["来週、友達とテニスをします。","Tuần sau, tôi sẽ chơi tennis cùng bạn bè."],["来週、映画を見ます。","Tuần sau tôi xem phim."],["来週は休みです。","Tuần sau là ngày nghỉ."],["来週、日本へ行きます。","Tuần sau tôi đi Nhật Bản."],["来週、試験があります。","Tuần sau có kỳ thi."]]},{"word":"先月","reading":"せんげつ","meaning":"Tháng trước","hanViet":"TIÊN NGUYỆT","lesson":5,"ex":[["先月、日本へ来ました。","Tháng trước, tôi đã đến Nhật Bản."],["先月、テニスをしました。","Tháng trước tôi đã chơi quần vợt."],["先月は忙しかったです。","Tháng trước tôi bận."],["先月、友達に会いました。","Tháng trước tôi đã gặp bạn."],["先月、旅行しました。","Tháng trước tôi đã đi du lịch."]]},{"word":"今月","reading":"こんげつ","meaning":"Tháng này","hanViet":"KIM NGUYỆT","lesson":5,"ex":[["今月は仕事が忙しいです。","Tháng này công việc bận."],["今月、テニスをします。","Tháng này tôi chơi quần vợt."],["今月は天気がいいです。","Tháng này thời tiết đẹp."],["今月、友達に会います。","Tháng này tôi gặp bạn."],["今月、試験があります。","Tháng này có kỳ thi."]]},{"word":"来月","reading":"らいげつ","meaning":"Tháng sau","hanViet":"LAI NGUYỆT","lesson":5,"ex":[["来月、国へ帰ります。","Tháng sau, tôi sẽ về nước."],["来月、友達と旅行します。","Tháng sau tôi đi du lịch cùng bạn."],["来月、日本へ行きます。","Tháng sau tôi đi Nhật Bản."],["来月は休みです。","Tháng sau là ngày nghỉ."],["来月、試験があります。","Tháng sau có kỳ thi."]]},{"word":"去年","reading":"きょねん","meaning":"Năm ngoái","hanViet":"KHỨ NIÊN","lesson":5,"ex":[["去年、日本語を勉強しました。","Năm ngoái, tôi đã học tiếng Nhật."],["去年、日本へ行きました。","Năm ngoái tôi đã đi Nhật Bản."],["去年は忙しかったです。","Năm ngoái tôi bận."],["去年、テニスをしました。","Năm ngoái tôi đã chơi quần vợt."],["去年、友達に会いました。","Năm ngoái tôi đã gặp bạn."]]},{"word":"今年","reading":"ことし","meaning":"Năm nay","hanViet":"KIM NIÊN","lesson":5,"ex":[["今年は日本へ行きます。","Năm nay, tôi sẽ đi Nhật Bản."],["今年、日本語を勉強します。","Năm nay tôi học tiếng Nhật."],["今年は忙しいです。","Năm nay tôi bận."],["今年、テニスをします。","Năm nay tôi chơi quần vợt."],["今年、旅行します。","Năm nay tôi đi du lịch."]]},{"word":"来年","reading":"らいねん","meaning":"Năm sau","hanViet":"LAI NIÊN","lesson":5,"ex":[["来年、大学へ行きます。","Năm sau, tôi sẽ vào đại học."],["来年、日本へ行きます。","Năm sau tôi đi Nhật Bản."],["来年、仕事をします。","Năm sau tôi làm việc."],["来年、テニスをします。","Năm sau tôi chơi quần vợt."],["来年、旅行します。","Năm sau tôi đi du lịch."]]},{"word":"～月","reading":"～がつ","meaning":"Tháng～","hanViet":"NGUYỆT","lesson":5,"ex":[["わたしの誕生日は5月です。","Sinh nhật của tôi là tháng 5."],["旅行は7月です。","Chuyến du lịch vào tháng 7."],["田中さんの誕生日は3月です。","Sinh nhật của anh Tanaka vào tháng 3."],["休みは8月です。","Kỳ nghỉ vào tháng 8."],["試験は6月です。","Kỳ thi vào tháng 6."]]},{"word":"何月","reading":"なんがつ","meaning":"tháng mấy","hanViet":"HÀ NGUYỆT","lesson":5,"ex":[["誕生日は何月ですか。","Sinh nhật vào tháng mấy?"],["旅行は何月ですか。","Chuyến du lịch vào tháng mấy?"],["試験は何月ですか。","Kỳ thi vào tháng mấy?"],["休みは何月ですか。","Kỳ nghỉ vào tháng mấy?"],["田中さんの誕生日は何月ですか。","Sinh nhật của anh Tanaka vào tháng mấy?"]]},{"word":"一日","reading":"ついたち","meaning":"Một ngày, ngày mùng 1","hanViet":"NHẤT NHẬT","lesson":5,"ex":[["わたしの誕生日は1月1日です。","Sinh nhật của tôi là ngày 1 tháng 1."],["一月一日に友達に会います。","Ngày 1 tháng 1 tôi gặp bạn."],["きょうは一日です。","Hôm nay là mùng 1."],["一日、うちで休みます。","Tôi nghỉ ở nhà một ngày."],["一月一日に母に電話をします。","Ngày 1 tháng 1 tôi gọi điện cho mẹ."]]},{"word":"二日","reading":"ふつか","meaning":"Hai ngày, ngày mùng 2","hanViet":"NHỊ NHẬT","lesson":5,"ex":[["わたしの誕生日は3月2日です。","Sinh nhật của tôi là ngày 2 tháng 3."],["二月二日に試験があります。","Ngày 2 tháng 2 có kỳ thi."],["二日、旅行をします。","Tôi đi du lịch hai ngày."],["母の誕生日は二月二日です。","Sinh nhật của mẹ tôi là ngày 2 tháng 2."],["二日は友達の誕生日です。","Ngày 2 là sinh nhật bạn tôi."]]},{"word":"三日","reading":"みっか","meaning":"ngày mồng 3, 3 ngày","hanViet":"TAM NHẬT","lesson":5,"ex":[["田中さんの誕生日は5月3日です。","Sinh nhật của anh Tanaka là ngày 3 tháng 5."],["三月三日に花見をします。","Ngày 3 tháng 3 tôi đi ngắm hoa anh đào."],["三日、学校を休みます。","Tôi nghỉ học ba ngày."],["三日に友達と映画を見ます。","Ngày mồng 3 tôi đi xem phim cùng bạn."],["田中さんは三月三日に来ます。","Anh Tanaka đến vào ngày 3 tháng 3."]]},{"word":"四日","reading":"よっか","meaning":"ngày mồng 4, 4 ngày","hanViet":"TỨ NHẬT","lesson":5,"ex":[["4月4日に旅行へ行きます。","Ngày 4 tháng 4, tôi sẽ đi du lịch."],["四月四日に映画を見ます。","Ngày 4 tháng 4 tôi xem phim."],["四日、うちにいます。","Bốn ngày tôi ở nhà."],["会議は四月四日です。","Cuộc họp vào ngày 4 tháng 4."],["四日は父の誕生日です。","Mùng 4 là sinh nhật của bố tôi."]]},{"word":"五日","reading":"いつか","meaning":"Năm ngày, ngày mùng 5","hanViet":"NGŨ NHẬT","lesson":5,"ex":[["会議は5月5日です。","Cuộc họp vào ngày 5 tháng 5."],["五月五日は子供の日です。","Ngày 5 tháng 5 là Ngày Thiếu nhi."],["五日、旅行をします。","Tôi đi du lịch năm ngày."],["五日は金曜日です。","Mùng 5 là thứ Sáu."],["五月五日にデパートへ行きます。","Ngày 5 tháng 5 tôi đi cửa hàng bách hoá."]]},{"word":"六日","reading":"むいか","meaning":"ngày mồng 6, 6 ngày","hanViet":"LỤC NHẬT","lesson":5,"ex":[["試験は6月6日です。","Kỳ thi vào ngày 6 tháng 6."],["六月六日に友達と買い物をします。","Ngày 6 tháng 6 tôi đi mua sắm với bạn."],["六日は土曜日です。","Mùng 6 là thứ Bảy."],["六月六日に母に会います。","Ngày 6 tháng 6 tôi gặp mẹ."],["六日は休みです。","Mùng 6 được nghỉ."]]},{"word":"七日","reading":"なのか","meaning":"Bảy ngày, ngày mùng 7","hanViet":"THẤT NHẬT","lesson":5,"ex":[["わたしの誕生日は7月7日です。","Sinh nhật của tôi là ngày 7 tháng 7."],["七月七日に映画館へ行きます。","Ngày 7 tháng 7 tôi đi rạp chiếu phim."],["七日は父の誕生日です。","Ngày 7 là sinh nhật bố tôi."],["七月七日にプールへ行きます。","Ngày 7 tháng 7 tôi đi bể bơi."],["七日は休みです。","Mùng 7 được nghỉ."]]},{"word":"八日","reading":"ようか","meaning":"ngày mồng 8, 8 ngày","hanViet":"BÁT NHẬT","lesson":5,"ex":[["旅行は8月8日からです。","Chuyến du lịch bắt đầu từ ngày 8 tháng 8."],["八月八日に海へ行きます。","Ngày 8 tháng 8 tôi đi biển."],["八日に母の誕生日があります。","Ngày mồng 8 là sinh nhật của mẹ tôi."],["八月八日に母と買い物をします。","Ngày 8 tháng 8 tôi đi mua sắm với mẹ."],["八日、会社を休みます。","Tôi nghỉ làm tám ngày."]]},{"word":"九日","reading":"ここのか","meaning":"Chín ngày, ngày mùng 9","hanViet":"CỬU NHẬT","lesson":5,"ex":[["映画は9月9日に見ます。","Tôi sẽ xem phim vào ngày 9 tháng 9."],["九月九日に学校へ行きます。","Ngày 9 tháng 9 tôi đi học."],["九日は母の誕生日です。","Mùng 9 là sinh nhật của mẹ tôi."],["九月九日に友達に電話をします。","Ngày 9 tháng 9 tôi gọi điện cho bạn."],["九日、旅行をします。","Tôi đi du lịch chín ngày."]]},{"word":"十日","reading":"とおか","meaning":"Mười ngày, ngày mùng 10","hanViet":"THẬP NHẬT","lesson":5,"ex":[["誕生日は10月10日です。","Sinh nhật vào ngày 10 tháng 10."],["十月十日にスポーツをします。","Ngày 10 tháng 10 tôi chơi thể thao."],["十日、うちで休みます。","Tôi nghỉ ở nhà mười ngày."],["十月十日に友達と映画を見ます。","Ngày 10 tháng 10 tôi xem phim với bạn."],["十日は試験です。","Mùng 10 có kỳ thi."]]},{"word":"十四日","reading":"じゅうよっか","meaning":"ngày 14, 14 ngày","hanViet":"THẬP TỨ NHẬT","lesson":5,"ex":[["田中さんの誕生日は2月14日です。","Sinh nhật của anh Tanaka là ngày 14 tháng 2."],["二月十四日に友達にプレゼントをあげます。","Ngày 14 tháng 2 tôi tặng quà cho bạn."],["十四日に試験があります。","Ngày 14 có bài kiểm tra."],["十四日、旅行をします。","Tôi đi du lịch 14 ngày."],["二月十四日にチョコレートを買います。","Ngày 14 tháng 2 tôi mua sô cô la."]]},{"word":"二十日","reading":"はつか","meaning":"ngày 20, 20 ngày","hanViet":"NHỊ THẬP NHẬT","lesson":5,"ex":[["会議は10月20日です。","Cuộc họp vào ngày 20 tháng 10."],["十月二十日に試験があります。","Ngày 20 tháng 10 có kỳ thi."],["二十日に旅行へ行きます。","Ngày 20 tôi đi du lịch."],["二十日、学校を休みます。","Tôi nghỉ học 20 ngày."],["十月二十日に友達に会います。","Ngày 20 tháng 10 tôi gặp bạn."]]},{"word":"二十四日","reading":"にじゅよっか","meaning":"ngày 24, 24 ngày","hanViet":"NHỊ THẬP TỨ NHẬT","lesson":5,"ex":[["クリスマスは12月24日です。","Giáng sinh là ngày 24 tháng 12."],["十二月二十四日にケーキを買います。","Ngày 24 tháng 12 tôi mua bánh."],["二十四日に友達と会います。","Ngày 24 tôi gặp bạn."],["十二月二十四日に友達とごはんを食べます。","Ngày 24 tháng 12 tôi ăn cơm với bạn."],["二十四日は休みです。","Ngày 24 được nghỉ."]]},{"word":"何日","reading":"なんにち","meaning":"ngày mấy, ngày bao nhiêu, mấy ngày, bao nhiêu ngày","hanViet":"HÀ NHẬT","lesson":5,"ex":[["きょうは何日ですか。","Hôm nay là ngày mấy?"],["何日旅行をしますか。","Bạn đi du lịch mấy ngày?"],["田中さんの誕生日は何日ですか。","Sinh nhật của anh Tanaka là ngày mấy?"],["何日休みますか。","Bạn nghỉ mấy ngày?"],["会議は何日ですか。","Cuộc họp ngày mấy?"]]},{"word":"いつ","reading":"いつ","meaning":"bao giờ, khi nào","hanViet":"","lesson":5,"ex":[["田中さんはいつ日本へ来ますか。","Anh Tanaka đến Nhật Bản khi nào?"],["いつ学校へ行きますか。","Khi nào bạn đi học?"],["誕生日はいつですか。","Sinh nhật của bạn khi nào?"],["いつ買い物をしますか。","Khi nào bạn đi mua sắm?"],["いつ日本へ行きますか。","Khi nào bạn đi Nhật Bản?"]]},{"word":"誕生日","reading":"たんじょうび","meaning":"Sinh nhật","hanViet":"ĐẢN SINH NHẬT","lesson":5,"ex":[["きょうは友達の誕生日です。","Hôm nay là sinh nhật của bạn tôi."],["あしたは母の誕生日です。","Ngày mai là sinh nhật của mẹ tôi."],["誕生日に友達からプレゼントをもらいます。","Vào sinh nhật, tôi nhận quà từ bạn."],["田中さんの誕生日にプレゼントをあげます。","Vào sinh nhật anh Tanaka tôi tặng quà cho anh ấy."],["誕生日に友達とごはんを食べます。","Vào sinh nhật tôi ăn cơm với bạn."]]},{"word":"普通","reading":"ふつう","meaning":"Thông thường, bình thường","hanViet":"PHỔ THÔNG","lesson":5,"ex":[["普通、7時に起きます。","Thông thường, tôi dậy lúc 7 giờ."],["普通、8時に学校へ行きます。","Thông thường, tôi đi học lúc 8 giờ."],["普通、日曜日に休みます。","Thông thường, tôi nghỉ vào chủ nhật."],["普通、うちでごはんを食べます。","Thông thường, tôi ăn cơm ở nhà."],["普通、電車で会社へ行きます。","Thông thường, tôi đi làm bằng tàu điện."]]},{"word":"急行","reading":"きゅうこう","meaning":"tàu tốc hành","hanViet":"HÀNH","lesson":5,"ex":[["急行で学校へ行きます。","Tôi đi học bằng tàu tốc hành."],["急行は電車より速いです。","Tàu tốc hành nhanh hơn tàu điện."],["急行に乗りますか。","Bạn đi tàu tốc hành à?"],["急行は9時に来ます。","Tàu tốc hành đến lúc 9 giờ."],["急行で会社へ行きます。","Tôi đi làm bằng tàu tốc hành."]]},{"word":"特急","reading":"とっきゅう","meaning":"Tàu tốc hành đặc biệt","hanViet":"ĐẶC CẤP","lesson":5,"ex":[["特急は速いです。","Tàu tốc hành đặc biệt nhanh."],["特急で旅行へ行きます。","Tôi đi du lịch bằng tàu tốc hành đặc biệt."],["特急は急行より速いです。","Tàu tốc hành đặc biệt nhanh hơn tàu tốc hành."],["特急は高いです。","Tàu tốc hành đặc biệt đắt."],["特急で学校へ行きます。","Tôi đi học bằng tàu tốc hành đặc biệt."]]},{"word":"次の","reading":"つぎの","meaning":"tiếp theo","hanViet":"THỨ","lesson":5,"ex":[["次の電車は3時です。","Chuyến tàu điện tiếp theo lúc 3 giờ."],["次の駅はどこですか。","Ga tiếp theo ở đâu?"],["次の日曜日に友達に会います。","Chủ nhật tới tôi gặp bạn."],["次の電車は何時ですか。","Chuyến tàu điện tiếp theo mấy giờ?"],["次の休みは来週です。","Kỳ nghỉ tiếp theo là tuần sau."]]},{"word":"どういたしまして","reading":"どういたしまして","meaning":"Không có chi","hanViet":"","lesson":5,"ex":[["「ありがとう。」「どういたしまして。」","“Cảm ơn bạn.” “Không có chi.”"],["「どうもありがとう。」「どういたしまして。」","“Cảm ơn bạn nhiều.” “Không có chi.”"],["「ありがとうございました。」「どういたしまして。」","“Cảm ơn bạn.” “Không có chi.”"],["「手伝ってくれてありがとう。」「どういたしまして。」","“Cảm ơn bạn đã giúp tôi.” “Không có chi.”"],["「プレゼント、ありがとう。」「どういたしまして。」","“Cảm ơn bạn vì món quà.” “Không có chi.”"]]},{"word":"～番線","reading":"～ばんせん","meaning":"Bến tàu số ～ , Đường tàu số ～","hanViet":"","lesson":5,"ex":[["3番線で電車に乗ります。","Tôi lên tàu điện ở đường tàu số 3."],["急行は何番線ですか。","Tàu tốc hành ở đường tàu số mấy?"],["2番線で電車を待ちます。","Tôi đợi tàu điện ở đường tàu số 2."],["4番線はどこですか。","Đường tàu số 4 ở đâu?"],["1番線から電車に乗ります。","Tôi lên tàu điện từ đường tàu số 1."]]},{"word":"祝祭日","reading":"しゅくさいじつ","meaning":"NGÀY NGHỈ QUỐC GIA","hanViet":"NHẬT","lesson":5,"ex":[["祝祭日は休みです。","Ngày nghỉ quốc gia thì được nghỉ."],["祝祭日に旅行へ行きます。","Vào ngày nghỉ quốc gia tôi đi du lịch."],["祝祭日は会社が休みです。","Vào ngày nghỉ quốc gia công ty được nghỉ."],["あしたは祝祭日ですか。","Ngày mai là ngày nghỉ quốc gia à?"],["祝祭日に友達に会います。","Vào ngày nghỉ quốc gia tôi gặp bạn."]]},{"word":"元日","reading":"がんじつ","meaning":"Nguyên Đán","hanViet":"NGUYÊN NHẬT","lesson":5,"ex":[["元日は1月1日です。","Ngày Nguyên Đán là ngày 1 tháng 1."],["元日に母に会います。","Vào ngày Nguyên Đán tôi gặp mẹ."],["元日は休みです。","Ngày Nguyên Đán được nghỉ."],["元日にうちでごはんを食べます。","Vào ngày Nguyên Đán tôi ăn cơm ở nhà."],["元日に友達に電話をします。","Vào ngày Nguyên Đán tôi gọi điện cho bạn."]]},{"word":"成人の日","reading":"せいじんのひ","meaning":"Ngày Thành Nhân","hanViet":"NHÂN NHẬT","lesson":5,"ex":[["成人の日は1月です。","Ngày Thành Nhân vào tháng 1."],["成人の日は学校が休みです。","Vào Ngày Thành Nhân trường học được nghỉ."],["成人の日に友達に会います。","Vào Ngày Thành Nhân tôi gặp bạn."],["成人の日に旅行へ行きます。","Vào Ngày Thành Nhân tôi đi du lịch."],["成人の日は月曜日です。","Ngày Thành Nhân là thứ Hai."]]},{"word":"建国記念の日","reading":"きんこくきねんひ","meaning":"Ngày quốc khánh","hanViet":"NHẬT","lesson":5,"ex":[["建国記念の日は2月11日です。","Ngày Quốc khánh là ngày 11 tháng 2."],["建国記念の日は会社が休みです。","Vào Ngày Quốc khánh công ty được nghỉ."],["建国記念の日にうちで休みます。","Vào Ngày Quốc khánh tôi nghỉ ở nhà."],["建国記念の日は2月です。","Ngày Quốc khánh vào tháng 2."],["建国記念の日に友達と買い物をします。","Vào Ngày Quốc khánh tôi đi mua sắm với bạn."]]},{"word":"春分の日","reading":"しゅんぶんのひ","meaning":"Ngày xuân phân","hanViet":"PHÂN NHẬT","lesson":5,"ex":[["春分の日は3月です。","Ngày Xuân phân vào tháng 3."],["春分の日は休みです。","Ngày Xuân phân được nghỉ."],["春分の日に花見をします。","Vào Ngày Xuân phân tôi đi ngắm hoa anh đào."],["春分の日に公園へ行きます。","Vào Ngày Xuân phân tôi đi công viên."],["春分の日に母に会います。","Vào Ngày Xuân phân tôi gặp mẹ."]]},{"word":"昭和の日","reading":"しょうわのひ","meaning":"Ngày Chiêu Hòa","hanViet":"NHẬT","lesson":5,"ex":[["昭和の日は4月29日です。","Ngày Chiêu Hòa là ngày 29 tháng 4."],["昭和の日は学校が休みです。","Vào Ngày Chiêu Hòa trường học được nghỉ."],["昭和の日に旅行へ行きます。","Vào Ngày Chiêu Hòa tôi đi du lịch."],["昭和の日は4月です。","Ngày Chiêu Hòa vào tháng 4."],["昭和の日に友達に会います。","Vào Ngày Chiêu Hòa tôi gặp bạn."]]},{"word":"憲法記念日","reading":"けんぽうきねんび","meaning":"Ngày kỷ niệm Hiến pháp","hanViet":"NHẬT","lesson":5,"ex":[["憲法記念日は5月3日です。","Ngày kỷ niệm Hiến pháp là ngày 3 tháng 5."],["憲法記念日は会社が休みです。","Vào Ngày kỷ niệm Hiến pháp công ty được nghỉ."],["憲法記念日にうちで本を読みます。","Vào Ngày kỷ niệm Hiến pháp tôi đọc sách ở nhà."],["憲法記念日は5月です。","Ngày kỷ niệm Hiến pháp vào tháng 5."],["憲法記念日に公園へ行きます。","Vào Ngày kỷ niệm Hiến pháp tôi đi công viên."]]},{"word":"緑の日","reading":"みどりのひ","meaning":"Ngày cây xanh","hanViet":"NHẬT","lesson":5,"ex":[["緑の日は5月4日です。","Ngày Cây xanh là ngày 4 tháng 5."],["緑の日は休みです。","Ngày Cây xanh được nghỉ."],["緑の日に山へ行きます。","Vào Ngày Cây xanh tôi đi núi."],["緑の日は5月です。","Ngày Cây xanh vào tháng 5."],["緑の日に花を見ます。","Vào Ngày Cây xanh tôi ngắm hoa."]]},{"word":"子供の日","reading":"こどものひ","meaning":"Ngày thiếu nhi","hanViet":"TỬ NHẬT","lesson":5,"ex":[["子供の日は5月5日です。","Ngày Thiếu nhi là ngày 5 tháng 5."],["子供の日は学校が休みです。","Vào Ngày Thiếu nhi trường học được nghỉ."],["子供の日に子どもと遊びます。","Vào Ngày Thiếu nhi tôi chơi với con."],["子供の日は5月です。","Ngày Thiếu nhi vào tháng 5."],["子供の日にケーキを食べます。","Vào Ngày Thiếu nhi tôi ăn bánh."]]},{"word":"海の日","reading":"うみのひ","meaning":"Ngày của biển","hanViet":"NHẬT","lesson":5,"ex":[["海の日は7月です。","Ngày của Biển vào tháng 7."],["海の日は会社が休みです。","Vào Ngày của Biển công ty được nghỉ."],["海の日に海へ行きます。","Vào Ngày của Biển tôi đi biển."],["海の日は月曜日です。","Ngày của Biển là thứ Hai."],["海の日に泳ぎます。","Vào Ngày của Biển tôi bơi."]]},{"word":"敬老の日","reading":"けいろうのひ","meaning":"Ngày kính lão","hanViet":"NHẬT","lesson":5,"ex":[["敬老の日は9月です。","Ngày Kính lão vào tháng 9."],["敬老の日は休みです。","Ngày Kính lão được nghỉ."],["敬老の日におじいさんに会います。","Vào Ngày Kính lão tôi gặp ông."],["敬老の日は月曜日です。","Ngày Kính lão là thứ Hai."],["敬老の日におばあさんに電話をします。","Vào Ngày Kính lão tôi gọi điện cho bà."]]},{"word":"秋分の日","reading":"しゅうぶんのひ","meaning":"Ngày thu phân","hanViet":"PHÂN NHẬT","lesson":5,"ex":[["秋分の日は9月です。","Ngày Thu phân vào tháng 9."],["秋分の日は学校が休みです。","Vào Ngày Thu phân trường học được nghỉ."],["秋分の日に母に会います。","Vào Ngày Thu phân tôi gặp mẹ."],["秋分の日に旅行へ行きます。","Vào Ngày Thu phân tôi đi du lịch."],["秋分の日に公園で散歩をします。","Vào Ngày Thu phân tôi đi dạo ở công viên."]]},{"word":"体育の日","reading":"たいいくのひ","meaning":"Ngày thể thao","hanViet":"THỂ NHẬT","lesson":5,"ex":[["体育の日は10月です。","Ngày Thể thao vào tháng 10."],["体育の日は会社が休みです。","Vào Ngày Thể thao công ty được nghỉ."],["体育の日にスポーツをします。","Vào Ngày Thể thao tôi chơi thể thao."],["体育の日は月曜日です。","Ngày Thể thao là thứ Hai."],["体育の日に友達とテニスをします。","Vào Ngày Thể thao tôi chơi tennis với bạn."]]},{"word":"文化の日","reading":"ぶんかのひ","meaning":"Ngày văn hóa","hanViet":"NHẬT","lesson":5,"ex":[["文化の日は11月3日です。","Ngày Văn hóa là ngày 3 tháng 11."],["文化の日は休みです。","Ngày Văn hóa được nghỉ."],["文化の日に本を読みます。","Vào Ngày Văn hóa tôi đọc sách."],["文化の日は11月です。","Ngày Văn hóa vào tháng 11."],["文化の日に美術館へ行きます。","Vào Ngày Văn hóa tôi đi bảo tàng mỹ thuật."]]},{"word":"勤労感謝の日","reading":"きんろうかんしゃのひ","meaning":"Ngày Cảm tạ Lao động","hanViet":"NHẬT","lesson":5,"ex":[["勤労感謝の日は11月23日です。","Ngày Cảm tạ Lao động là ngày 23 tháng 11."],["勤労感謝の日は会社が休みです。","Vào Ngày Cảm tạ Lao động công ty được nghỉ."],["勤労感謝の日に母にありがとうと言います。","Vào Ngày Cảm tạ Lao động tôi nói cảm ơn mẹ."],["勤労感謝の日は11月です。","Ngày Cảm tạ Lao động vào tháng 11."],["勤労感謝の日にうちで休みます。","Vào Ngày Cảm tạ Lao động tôi nghỉ ở nhà."]]},{"word":"天皇誕生日","reading":"てんのうたんじょうび","meaning":"Sinh nhật Thiên hoàng","hanViet":"SINH NHẬT","lesson":5,"ex":[["天皇誕生日は2月23日です。","Sinh nhật Thiên hoàng là ngày 23 tháng 2."],["天皇誕生日は学校が休みです。","Vào Sinh nhật Thiên hoàng trường học được nghỉ."],["天皇誕生日は2月です。","Sinh nhật Thiên hoàng vào tháng 2."],["天皇誕生日に友達に会います。","Vào Sinh nhật Thiên hoàng tôi gặp bạn."],["天皇誕生日に旅行へ行きます。","Vào Sinh nhật Thiên hoàng tôi đi du lịch."]]},{"word":"スーパー","reading":"スーパー","meaning":"siêu thị","hanViet":"","lesson":5,"ex":[["スーパーで食べ物を買います。","Tôi mua đồ ăn ở siêu thị."],["スーパーで野菜を買います。","Tôi mua rau củ ở siêu thị."],["スーパーはうちの近くにあります。","Siêu thị ở gần nhà tôi."],["あした、スーパーへ行きます。","Ngày mai tôi đi siêu thị."],["スーパーで友達に会いました。","Tôi đã gặp bạn ở siêu thị."]]},{"word":"バス","reading":"バス","meaning":"xe Buýt (bus)","hanViet":"","lesson":5,"ex":[["バスで学校へ行きます。","Tôi đi học bằng xe buýt."],["バスで会社へ行きます。","Tôi đi làm bằng xe buýt."],["バスは9時に来ます。","Xe buýt đến lúc 9 giờ."],["バスに乗ります。","Tôi lên xe buýt."],["バスは電車より遅いです。","Xe buýt chậm hơn tàu điện."]]},{"word":"タクシー","reading":"タクシー","meaning":"tắc-xi (taxi)","hanViet":"","lesson":5,"ex":[["タクシーで駅へ行きます。","Tôi đi đến nhà ga bằng taxi."],["タクシーで空港へ行きます。","Tôi đi sân bay bằng taxi."],["タクシーは高いです。","Taxi đắt."],["タクシーに乗ります。","Tôi lên taxi."],["雨の日はタクシーで行きます。","Vào ngày mưa tôi đi bằng taxi."]]},{"word":"～日","reading":"～にち","meaning":"Ngày～ , (～ ngày)","hanViet":"NHẬT","lesson":5,"ex":[["わたしの誕生日は5月20日です。","Sinh nhật của tôi là ngày 20 tháng 5."],["誕生日は3月15日です。","Sinh nhật của tôi là ngày 15 tháng 3."],["旅行は5月10日から5月12日までです。","Chuyến du lịch từ ngày 10 đến ngày 12 tháng 5."],["会議は7月8日です。","Cuộc họp vào ngày 8 tháng 7."],["7月8日に友達に会います。","Ngày 8 tháng 7 tôi gặp bạn."]]},{"word":"食べます","reading":"たべます","meaning":"Ăn","hanViet":"THỰC","lesson":6,"ex":[["わたしはまいにちごはんを食べます。","Tôi ăn cơm mỗi ngày."],["わたしは昼ごはんにカレーライスを食べます。","Tôi ăn cơm cà ri vào bữa trưa."],["わたしは友達と寿司を食べます。","Tôi ăn sushi với bạn."],["あした、うちで肉を食べます。","Ngày mai tôi ăn thịt ở nhà."],["わたしは昼、パンを食べます。","Buổi trưa tôi ăn bánh mì."]]},{"word":"飲みます","reading":"のみます","meaning":"Uống","hanViet":"ẨM","lesson":6,"ex":[["わたしはまいにち水を飲みます。","Tôi uống nước mỗi ngày."],["わたしはコーヒーを飲みます。","Tôi uống cà phê."],["わたしは昼、ジュースを飲みます。","Buổi trưa tôi uống nước trái cây."],["友達とビールを飲みます。","Tôi uống bia với bạn."],["のどがかわきましたから、水を飲みます。","Vì khát nước nên tôi uống nước."]]},{"word":"吸います","reading":"すいます","meaning":"hút [thuốc lá]","hanViet":"HẤP","lesson":6,"ex":[["田中さんはたばこを吸います。","Anh Tanaka hút thuốc lá."],["お父さんはたばこを吸いません。","Bố tôi không hút thuốc lá."],["ここでたばこを吸ってはいけません。","Ở đây không được hút thuốc lá."],["田中さんはたばこを吸いません。","Anh Tanaka không hút thuốc lá."],["わたしはたばこを吸ったことがありません。","Tôi chưa từng hút thuốc lá."]]},{"word":"見ます","reading":"みます","meaning":"Nhìn, xem","hanViet":"KIẾN","lesson":6,"ex":[["わたしはテレビを見ます。","Tôi xem tivi."],["わたしは夜、テレビを見ます。","Buổi tối tôi xem tivi."],["わたしは友達とテレビを見ます。","Tôi cùng bạn xem ti vi."],["あした、美術館で絵を見ます。","Ngày mai tôi xem tranh ở bảo tàng mỹ thuật."],["わたしは海を見ます。","Tôi ngắm biển."]]},{"word":"聞きます","reading":"ききます","meaning":"Nghe","hanViet":"VĂN","lesson":6,"ex":[["わたしはまいにち音楽を聞きます。","Tôi nghe nhạc mỗi ngày."],["わたしは電車で音楽を聞きます。","Tôi nghe nhạc trên tàu điện."],["わたしは先生の話を聞きます。","Tôi nghe thầy cô nói."],["わたしはラジオを聞きます。","Tôi nghe đài."],["わたしは夜、クラシックを聞きます。","Buổi tối tôi nghe nhạc cổ điển."]]},{"word":"読みます","reading":"よみます","meaning":"Đọc","hanViet":"ĐỘC","lesson":6,"ex":[["わたしは新聞を読みます。","Tôi đọc báo."],["わたしは夜、本を読みます。","Buổi tối tôi đọc sách."],["わたしは電車で雑誌を読みます。","Tôi đọc tạp chí trên tàu điện."],["わたしは日本語の本を読みます。","Tôi đọc sách tiếng Nhật."],["わたしは手紙を読みます。","Tôi đọc thư."]]},{"word":"書きます","reading":"かきます","meaning":"Viết","hanViet":"THƯ","lesson":6,"ex":[["わたしは手紙を書きます。","Tôi viết thư."],["わたしは日記を書きます。","Tôi viết nhật ký."],["わたしは友達にメールを書きます。","Tôi viết mail cho bạn."],["わたしは日本語でレポートを書きます。","Tôi viết báo cáo bằng tiếng Nhật."],["わたしは漢字を書きます。","Tôi viết chữ Hán."]]},{"word":"買います","reading":"かいます","meaning":"Mua","hanViet":"MÃI","lesson":6,"ex":[["わたしはデパートで本を買います。","Tôi mua sách ở cửa hàng bách hoá."],["わたしはコンビニでパンを買います。","Tôi mua bánh mì ở cửa hàng tiện lợi."],["わたしはデパートで服を買います。","Tôi mua quần áo ở cửa hàng bách hoá."],["わたしは友達にプレゼントを買います。","Tôi mua quà cho bạn."],["わたしは本屋で辞書を買います。","Tôi mua từ điển ở hiệu sách."]]},{"word":"撮ります","reading":"とります","meaning":"chụp [ảnh]","hanViet":"TOÁT TẢ CHÂN","lesson":6,"ex":[["わたしは写真を撮ります。","Tôi chụp ảnh."],["わたしはカメラで写真を撮ります。","Tôi chụp ảnh bằng máy ảnh."],["わたしは公園で花の写真を撮ります。","Tôi chụp ảnh hoa ở công viên."],["わたしは友達の写真を撮ります。","Tôi chụp ảnh bạn."],["わたしは海で写真を撮ります。","Tôi chụp ảnh ở biển."]]},{"word":"会います","reading":"あいます","meaning":"gặp, gặp gỡ","hanViet":"HỘI","lesson":6,"ex":[["わたしはあした友達に会います。","Ngày mai tôi gặp bạn."],["わたしは駅で友達に会います。","Tôi gặp bạn ở ga."],["わたしはあした先生に会います。","Ngày mai tôi gặp thầy cô."],["わたしは日曜日に母に会います。","Chủ nhật tôi gặp mẹ."],["わたしは学校で田中さんに会いました。","Tôi đã gặp anh Tanaka ở trường."]]},{"word":"ごはん","reading":"ごはん","meaning":"cơm, bữa ăn","hanViet":"","lesson":6,"ex":[["きょうのごはんはおいしいです。","Cơm hôm nay ngon."],["うちでごはんを食べます。","Tôi ăn cơm ở nhà."],["ごはんはもうできましたか。","Cơm đã xong chưa?"],["わたしはごはんが好きです。","Tôi thích cơm."],["ごはんとみそ汁を食べます。","Tôi ăn cơm với súp miso."]]},{"word":"朝ごはん","reading":"あさごはん","meaning":"cơm sáng","hanViet":"TRIỀU","lesson":6,"ex":[["わたしはまいにち朝ごはんを食べます。","Tôi ăn sáng mỗi ngày."],["朝ごはんにパンを食べます。","Bữa sáng tôi ăn bánh mì."],["朝ごはんは7時です。","Bữa sáng lúc 7 giờ."],["わたしは朝ごはんを食べませんでした。","Tôi đã không ăn sáng."],["朝ごはんに卵を食べます。","Bữa sáng tôi ăn trứng."]]},{"word":"昼ごはん","reading":"ひるごはん","meaning":"cơm trưa","hanViet":"TRÚ","lesson":6,"ex":[["きょうの昼ごはんはカレーライスです。","Bữa trưa hôm nay là cơm cà ri."],["昼ごはんは12時です。","Bữa trưa lúc 12 giờ."],["昼ごはんにうどんを食べます。","Bữa trưa tôi ăn mì udon."],["わたしは友達と昼ごはんを食べます。","Tôi ăn trưa với bạn."],["昼ごはんはおいしかったです。","Bữa trưa ngon."]]},{"word":"晩ごはん","reading":"ばんごはん","meaning":"cơm tối","hanViet":"VÃN","lesson":6,"ex":[["わたしは晩ごはんをうちで食べます。","Tôi ăn tối ở nhà."],["晩ごはんに魚を食べます。","Bữa tối tôi ăn cá."],["晩ごはんは7時です。","Bữa tối lúc 7 giờ."],["わたしは母と晩ごはんを食べます。","Tôi ăn tối với mẹ."],["晩ごはんにカレーライスを食べました。","Bữa tối tôi đã ăn cơm cà ri."]]},{"word":"卵","reading":"たまご","meaning":"Trứng (gà…)","hanViet":"NOÃN","lesson":6,"ex":[["卵は体にいいです。","Trứng tốt cho sức khoẻ."],["卵を二つ買います。","Tôi mua hai quả trứng."],["わたしは卵が好きです。","Tôi thích trứng."],["卵は安いです。","Trứng rẻ."],["スーパーで卵を買います。","Tôi mua trứng ở siêu thị."]]},{"word":"肉","reading":"にく","meaning":"Thịt","hanViet":"NHỤC","lesson":6,"ex":[["わたしは肉を食べません。","Tôi không ăn thịt."],["わたしは肉が好きです。","Tôi thích thịt."],["肉は高いです。","Thịt đắt."],["スーパーで肉を買います。","Tôi mua thịt ở siêu thị."],["わたしは昼ごはんに肉を食べます。","Bữa trưa tôi ăn thịt."]]},{"word":"魚","reading":"さかな","meaning":"Con cá","hanViet":"NGƯ","lesson":6,"ex":[["きょうは魚を食べます。","Hôm nay tôi ăn cá."],["わたしは魚が好きです。","Tôi thích cá."],["魚は体にいいです。","Cá tốt cho sức khoẻ."],["スーパーで魚を買います。","Tôi mua cá ở siêu thị."],["魚は高いです。","Cá đắt."]]},{"word":"野菜","reading":"やさい","meaning":"Rau củ","hanViet":"DÃ THÁI","lesson":6,"ex":[["わたしは野菜が好きです。","Tôi thích rau củ."],["わたしは野菜を食べます。","Tôi ăn rau củ."],["野菜をたくさん食べます。","Tôi ăn nhiều rau."],["わたしは八百屋で野菜を買います。","Tôi mua rau củ ở cửa hàng rau quả."],["わたしは野菜が好きではありません。","Tôi không thích rau củ."]]},{"word":"果物","reading":"くだもの","meaning":"trái cây, hoa quả","hanViet":"QUẢ VẬT","lesson":6,"ex":[["わたしは果物が好きです。","Tôi thích trái cây."],["わたしは果物を食べます。","Tôi ăn trái cây."],["果物は体にいいです。","Trái cây tốt cho sức khoẻ."],["りんごは果物です。","Táo là trái cây."],["スーパーで果物を買います。","Tôi mua trái cây ở siêu thị."]]},{"word":"水","reading":"みず","meaning":"Nước","hanViet":"THỦY","lesson":6,"ex":[["水を飲みます。","Tôi uống nước."],["毎日、水をたくさん飲みます。","Mỗi ngày tôi uống nhiều nước."],["水は冷たいです。","Nước lạnh."],["わたしは朝、水を飲みます。","Buổi sáng tôi uống nước."],["水を三本買います。","Tôi mua ba chai nước."]]},{"word":"お茶","reading":"おちゃ","meaning":"Trà","hanViet":"TRÀ","lesson":6,"ex":[["わたしはまいにちお茶を飲みます。","Tôi uống trà mỗi ngày."],["お茶をください。","Cho tôi trà."],["お茶は熱いです。","Trà nóng."],["わたしは昼、お茶を飲みます。","Buổi trưa tôi uống trà."],["友達とお茶を飲みます。","Tôi uống trà với bạn."]]},{"word":"紅茶","reading":"こうちゃ","meaning":"Hồng trà, trà đen","hanViet":"HỒNG TRÀ","lesson":6,"ex":[["わたしは紅茶を飲みます。","Tôi uống hồng trà."],["紅茶をください。","Cho tôi hồng trà."],["紅茶は甘いです。","Hồng trà ngọt."],["わたしは紅茶が好きです。","Tôi thích hồng trà."],["わたしは夜、紅茶を飲みます。","Buổi tối tôi uống hồng trà."]]},{"word":"牛乳","reading":"ぎゅうにゅう","meaning":"Sữa bò","hanViet":"NGƯU NHŨ","lesson":6,"ex":[["わたしは朝、牛乳を飲みます。","Buổi sáng tôi uống sữa bò."],["牛乳をください。","Cho tôi sữa bò."],["牛乳は体にいいです。","Sữa bò tốt cho sức khoẻ."],["わたしは牛乳が好きです。","Tôi thích sữa bò."],["スーパーで牛乳を買います。","Tôi mua sữa bò ở siêu thị."]]},{"word":"酒","reading":"さけ","meaning":"rượu, đồ uống có cồn","hanViet":"TỬU","lesson":6,"ex":[["田中さんは酒を飲みません。","Anh Tanaka không uống rượu."],["わたしは酒を飲みません。","Tôi không uống rượu."],["酒は高いです。","Rượu đắt."],["父は酒が好きです。","Bố tôi thích rượu."],["酒屋で酒を買います。","Tôi mua rượu ở cửa hàng rượu."]]},{"word":"映画","reading":"えいが","meaning":"Phim, điện ảnh","hanViet":"ÁNH HỌA","lesson":6,"ex":[["きのう、映画を見ました。","Hôm qua tôi đã xem phim."],["映画はおもしろいです。","Phim thú vị."],["映画館で新しい映画を見ます。","Tôi xem phim mới ở rạp chiếu phim."],["あした、友達と新しい映画を見ます。","Ngày mai tôi cùng bạn xem phim mới."],["映画は長いです。","Phim dài."]]},{"word":"手紙","reading":"てがみ","meaning":"Thư (giấy viết tay)","hanViet":"THỦ CHỈ","lesson":6,"ex":[["わたしは母に手紙を書きます。","Tôi viết thư cho mẹ."],["手紙を書きますか。","Bạn viết thư à?"],["わたしは母から手紙をもらいました。","Tôi đã nhận thư từ mẹ."],["わたしは友達に手紙を書きます。","Tôi viết thư cho bạn."],["手紙を読みました。","Tôi đã đọc thư."]]},{"word":"写真","reading":"しゃしん","meaning":"Ảnh, bức ảnh","hanViet":"TẢ CHÂN","lesson":6,"ex":[["これはわたしの写真です。","Đây là ảnh của tôi."],["写真を撮りましょうか。","Chúng ta chụp ảnh nhé?"],["この写真はきれいです。","Bức ảnh này đẹp."],["わたしは写真を見ます。","Tôi xem ảnh."],["友達に写真をあげます。","Tôi tặng ảnh cho bạn."]]},{"word":"店","reading":"みせ","meaning":"Cửa hàng, tiệm","hanViet":"ĐIẾM","lesson":6,"ex":[["あそこに新しい店があります。","Ở đằng kia có một cửa hàng mới."],["この店は安いです。","Cửa hàng này rẻ."],["店で本を買います。","Tôi mua sách ở cửa hàng."],["あの店は大きいです。","Cửa hàng kia lớn."],["店に友達がいます。","Ở cửa hàng có bạn tôi."]]},{"word":"庭","reading":"にわ","meaning":"Sân, vườn","hanViet":"ĐÌNH","lesson":6,"ex":[["うちの庭に花があります。","Trong vườn nhà có hoa."],["庭に木と花があります。","Trong vườn có cây và hoa."],["庭で子どもが遊びます。","Trẻ con chơi trong vườn."],["庭は広いです。","Vườn rộng."],["庭で写真を撮ります。","Tôi chụp ảnh trong vườn."]]},{"word":"宿題","reading":"しゅくだい","meaning":"Bài tập về nhà","hanViet":"TÚC ĐỀ","lesson":6,"ex":[["わたしは宿題をします。","Tôi làm bài tập về nhà."],["宿題は難しいです。","Bài tập về nhà khó."],["わたしは夜、宿題をします。","Buổi tối tôi làm bài tập về nhà."],["きょうは宿題がありません。","Hôm nay không có bài tập về nhà."],["宿題は多いです。","Bài tập về nhà nhiều."]]},{"word":"花見","reading":"はなみ","meaning":"Ngắm hoa anh đào","hanViet":"HOA KIẾN","lesson":6,"ex":[["わたしは春に花見をします。","Vào mùa xuân tôi đi ngắm hoa anh đào."],["花見は楽しいです。","Ngắm hoa anh đào vui."],["友達と花見をします。","Tôi đi ngắm hoa anh đào với bạn."],["日曜日に花見をします。","Chủ nhật tôi đi ngắm hoa anh đào."],["花見で写真を撮ります。","Tôi chụp ảnh khi ngắm hoa anh đào."]]},{"word":"いっしょに","reading":"いっしょに","meaning":"cùng, cùng nhau","hanViet":"","lesson":6,"ex":[["わたしは友達といっしょにごはんを食べます。","Tôi ăn cơm cùng bạn."],["友達といっしょに映画を見ます。","Tôi xem phim cùng bạn."],["母といっしょに買い物をします。","Tôi đi mua sắm cùng mẹ."],["田中さんといっしょに学校へ行きます。","Tôi đi học cùng anh Tanaka."],["いっしょにごはんを食べましょうか。","Chúng ta ăn cơm cùng nhau nhé?"]]},{"word":"ちょっと","reading":"ちょっと","meaning":"một chút","hanViet":"","lesson":6,"ex":[["ちょっと待ってください。","Xin chờ một chút."],["ちょっと休みます。","Tôi nghỉ một chút."],["ちょっと見せてください。","Cho tôi xem một chút."],["ちょっと高いです。","Hơi đắt."],["ちょっと日本語がわかります。","Tôi hiểu tiếng Nhật một chút."]]},{"word":"いつも","reading":"いつも","meaning":"luôn luôn, lúc nào cũng","hanViet":"","lesson":6,"ex":[["わたしはいつも7時に起きます。","Tôi luôn thức dậy lúc 7 giờ."],["わたしはいつも電車で学校へ行きます。","Tôi luôn đi học bằng tàu điện."],["わたしはいつもうちでごはんを食べます。","Tôi luôn ăn cơm ở nhà."],["田中さんはいつも元気です。","Anh Tanaka lúc nào cũng khoẻ."],["わたしはいつも11時に寝ます。","Tôi luôn đi ngủ lúc 11 giờ."]]},{"word":"時々","reading":"ときどき","meaning":"Thỉnh thoảng","hanViet":"THỜI THỜI","lesson":6,"ex":[["わたしは時々映画を見ます。","Thỉnh thoảng tôi xem phim."],["わたしは時々テレビを見ます。","Thỉnh thoảng tôi xem tivi."],["わたしは時々母に電話をします。","Thỉnh thoảng tôi gọi điện cho mẹ."],["わたしは時々泳ぎます。","Thỉnh thoảng tôi bơi."],["わたしは時々本を読みます。","Thỉnh thoảng tôi đọc sách."]]},{"word":"それから","reading":"それから","meaning":"sau đó, tiếp theo","hanViet":"","lesson":6,"ex":[["ごはんを食べます。それから、学校へ行きます。","Tôi ăn cơm. Sau đó, tôi đi học."],["学校へ行きます。それから、うちへ帰ります。","Tôi đi học. Sau đó, tôi về nhà."],["ごはんを食べます。それから、テレビを見ます。","Tôi ăn cơm. Sau đó, tôi xem tivi."],["本を読みます。それから、寝ます。","Tôi đọc sách. Sau đó, tôi đi ngủ."],["買い物をします。それから、うちへ帰ります。","Tôi đi mua sắm. Sau đó, tôi về nhà."]]},{"word":"きゅうり","reading":"きゅうり","meaning":"Dưa chuột","hanViet":"","lesson":6,"ex":[["わたしはきゅうりを食べます。","Tôi ăn dưa chuột."],["きゅうりは安いです。","Dưa chuột rẻ."],["わたしはきゅうりが好きです。","Tôi thích dưa chuột."],["スーパーできゅうりを買います。","Tôi mua dưa chuột ở siêu thị."],["わたしはきゅうりを食べません。","Tôi không ăn dưa chuột."]]},{"word":"茄子","reading":"なす","meaning":"cà","hanViet":"TỬ","lesson":6,"ex":[["わたしは茄子が好きです。","Tôi thích cà."],["茄子は安いです。","Cà rẻ."],["わたしは茄子を食べます。","Tôi ăn cà."],["スーパーで茄子を買います。","Tôi mua cà ở siêu thị."],["わたしは茄子が好きではありません。","Tôi không thích cà."]]},{"word":"豆","reading":"まめ","meaning":"hạt đậu","hanViet":"ĐẬU","lesson":6,"ex":[["豆は体にいいです。","Đậu tốt cho sức khoẻ."],["母は豆の料理を作ります。","Mẹ tôi nấu món đậu."],["スーパーで豆を買いました。","Tôi đã mua đậu ở siêu thị."],["豆は小さいです。","Hạt đậu nhỏ."],["わたしは毎朝、豆を食べます。","Mỗi sáng tôi ăn đậu."]]},{"word":"ねぎ","reading":"ねぎ","meaning":"hành","hanViet":"","lesson":6,"ex":[["わたしはねぎを買います。","Tôi mua hành."],["母はねぎを切ります。","Mẹ tôi cắt hành."],["みそ汁にねぎを入れます。","Tôi cho hành vào súp miso."],["ねぎは緑です。","Hành lá có màu xanh."],["八百屋でねぎを買いました。","Tôi đã mua hành ở cửa hàng rau quả."]]},{"word":"白菜","reading":"はくさい","meaning":"rau cải bẹ trắng","hanViet":"","lesson":6,"ex":[["白菜は安いです。","Cải bẹ trắng rẻ."],["白菜を洗います。","Tôi rửa cải bẹ trắng."],["冬は白菜が安いです。","Mùa đông cải bẹ trắng rẻ."],["わたしは白菜が好きです。","Tôi thích cải bẹ trắng."],["白菜は白いです。","Cải bẹ trắng có màu trắng."]]},{"word":"ほうれん草","reading":"ほうれんそう","meaning":"rau bina","hanViet":"","lesson":6,"ex":[["わたしはほうれん草を食べます。","Tôi ăn rau bina."],["ほうれん草は体にいいです。","Rau bina tốt cho sức khoẻ."],["母はほうれん草を買いました。","Mẹ tôi đã mua rau bina."],["ほうれん草が好きですか。","Bạn có thích rau bina không?"],["スーパーにほうれん草があります。","Ở siêu thị có rau bina."]]},{"word":"じゃが芋","reading":"じゃがいも","meaning":"khoai tây","hanViet":"","lesson":6,"ex":[["わたしはじゃが芋を買います。","Tôi mua khoai tây."],["じゃが芋は大きいです。","Khoai tây to."],["母はじゃが芋の料理を作ります。","Mẹ tôi nấu món khoai tây."],["じゃが芋を三つ買いました。","Tôi đã mua ba củ khoai tây."],["わたしはじゃが芋が好きです。","Tôi thích khoai tây."]]},{"word":"大根","reading":"だいこん","meaning":"củ cải","hanViet":"ĐẠI","lesson":6,"ex":[["大根は白いです。","Củ cải màu trắng."],["大根は長いです。","Củ cải dài."],["大根を切って、みそ汁を作ります。","Tôi cắt củ cải rồi nấu súp miso."],["大根は安いです。","Củ cải rẻ."],["スーパーで大根を買いました。","Tôi đã mua củ cải ở siêu thị."]]},{"word":"玉ねぎ","reading":"たまねぎ","meaning":"củ hành","hanViet":"","lesson":6,"ex":[["わたしは玉ねぎを切ります。","Tôi cắt củ hành."],["玉ねぎは白いです。","Củ hành màu trắng."],["スーパーで玉ねぎを二つ買いました。","Tôi đã mua hai củ hành ở siêu thị."],["玉ねぎは料理に使います。","Tôi dùng củ hành để nấu ăn."],["わたしは玉ねぎが好きです。","Tôi thích củ hành."]]},{"word":"人参","reading":"にんじん","meaning":"cà rốt","hanViet":"NHÂN","lesson":6,"ex":[["人参は体にいいです。","Cà rốt tốt cho sức khoẻ."],["人参は赤いです。","Cà rốt màu đỏ."],["人参を洗います。","Tôi rửa cà rốt."],["八百屋で人参を二つ買いました。","Tôi đã mua hai củ cà rốt ở cửa hàng rau quả."],["わたしは人参が好きです。","Tôi thích cà rốt."]]},{"word":"苺","reading":"いちご","meaning":"dâu tây","hanViet":"","lesson":6,"ex":[["苺は甘いです。","Dâu tây ngọt."],["苺は赤いです。","Dâu tây màu đỏ."],["ケーキに苺を入れます。","Tôi cho dâu tây vào bánh."],["苺が好きですか。","Bạn có thích dâu tây không?"],["苺は高いです。","Dâu tây đắt."]]},{"word":"桃","reading":"もも","meaning":"quả đào","hanViet":"ĐÀO","lesson":6,"ex":[["わたしは桃が好きです。","Tôi thích quả đào."],["桃は甘いです。","Quả đào ngọt."],["桃は夏の果物です。","Quả đào là trái cây mùa hè."],["桃を二つ買いました。","Tôi đã mua hai quả đào."],["桃はおいしいです。","Quả đào ngon."]]},{"word":"西瓜","reading":"すいか","meaning":"dưa hấu","hanViet":"TÂY","lesson":6,"ex":[["西瓜は大きいです。","Dưa hấu to."],["夏に西瓜を食べます。","Vào mùa hè tôi ăn dưa hấu."],["西瓜は甘いです。","Dưa hấu ngọt."],["西瓜は重いです。","Dưa hấu nặng."],["西瓜が好きですか。","Bạn có thích dưa hấu không?"]]},{"word":"葡萄","reading":"ぶどう","meaning":"nho","hanViet":"","lesson":6,"ex":[["わたしは葡萄を食べます。","Tôi ăn nho."],["葡萄は甘いです。","Nho ngọt."],["葡萄は紫です。","Nho có màu tím."],["葡萄は小さいです。","Quả nho nhỏ."],["秋に葡萄を食べます。","Vào mùa thu tôi ăn nho."]]},{"word":"梨","reading":"なし","meaning":"quả lê Nhật","hanViet":"LÊ","lesson":6,"ex":[["梨はおいしいです。","Lê Nhật ngon."],["梨は甘いです。","Lê Nhật ngọt."],["梨は秋の果物です。","Lê Nhật là trái cây mùa thu."],["梨を二つ買いました。","Tôi đã mua hai quả lê Nhật."],["梨が好きですか。","Bạn có thích lê Nhật không?"]]},{"word":"柿","reading":"かき","meaning":"quả hồng (Nhật)","hanViet":"—","lesson":6,"ex":[["わたしは柿を食べます。","Tôi ăn quả hồng."],["柿は甘いです。","Quả hồng ngọt."],["柿は赤いです。","Quả hồng màu đỏ."],["スーパーで柿を買いました。","Tôi đã mua quả hồng ở siêu thị."],["柿はおいしいです。","Quả hồng ngon."]]},{"word":"みかん","reading":"みかん","meaning":"quýt","hanViet":"","lesson":6,"ex":[["みかんは安いです。","Quýt rẻ."],["みかんは甘いです。","Quýt ngọt."],["みかんは冬の果物です。","Quýt là trái cây mùa đông."],["みかんを三つ食べました。","Tôi đã ăn ba quả quýt."],["みかんが好きですか。","Bạn có thích quýt không?"]]},{"word":"りんご","reading":"りんご","meaning":"quả táo","hanViet":"","lesson":6,"ex":[["わたしはりんごを買います。","Tôi mua táo."],["りんごは赤いです。","Quả táo màu đỏ."],["りんごは甘いです。","Quả táo ngọt."],["りんごを三つ買いました。","Tôi đã mua ba quả táo."],["りんごはおいしいです。","Quả táo ngon."]]},{"word":"米","reading":"こめ","meaning":"Gạo","hanViet":"MỄ","lesson":6,"ex":[["わたしは米を買います。","Tôi mua gạo."],["米は白いです。","Gạo màu trắng."],["米を洗います。","Tôi vo gạo."],["米からごはんを作ります。","Tôi nấu cơm từ gạo."],["台所に米があります。","Trong bếp có gạo."]]},{"word":"パン","reading":"パン","meaning":"bánh mì","hanViet":"","lesson":6,"ex":[["わたしは朝、パンを食べます。","Buổi sáng tôi ăn bánh mì."],["パンはおいしいです。","Bánh mì ngon."],["店でパンを買いました。","Tôi đã mua bánh mì ở cửa hàng."],["パンは安いです。","Bánh mì rẻ."],["パンが好きですか。","Bạn có thích bánh mì không?"]]},{"word":"ミルク","reading":"ミルク","meaning":"sữa","hanViet":"","lesson":6,"ex":[["赤ちゃんはミルクを飲みます。","Em bé uống sữa."],["わたしは毎朝、ミルクを飲みます。","Mỗi sáng tôi uống sữa."],["ミルクは白いです。","Sữa màu trắng."],["ミルクは体にいいです。","Sữa tốt cho sức khoẻ."],["冷蔵庫にミルクがあります。","Trong tủ lạnh có sữa."]]},{"word":"ジュース","reading":"ジュース","meaning":"nước hoa quả","hanViet":"","lesson":6,"ex":[["わたしはジュースを飲みます。","Tôi uống nước hoa quả."],["ジュースは甘いです。","Nước hoa quả ngọt."],["ジュースは冷たいです。","Nước hoa quả lạnh."],["ジュースをください。","Cho tôi nước hoa quả."],["ジュースが好きですか。","Bạn có thích nước hoa quả không?"]]},{"word":"ビール","reading":"ビール","meaning":"bia","hanViet":"","lesson":6,"ex":[["田中さんはビールを飲みます。","Anh Tanaka uống bia."],["父はビールを飲みます。","Cha tôi uống bia."],["ビールは苦いです。","Bia đắng."],["ビールは高いです。","Bia đắt."],["わたしはビールを飲みません。","Tôi không uống bia."]]},{"word":"ビデオ","reading":"ビデオ","meaning":"video, băng video, đầu video","hanViet":"","lesson":6,"ex":[["わたしはビデオを見ます。","Tôi xem video."],["ビデオはおもしろいです。","Video thú vị."],["友達とビデオを見ます。","Tôi xem video cùng bạn."],["ビデオを借ります。","Tôi mượn video."],["きのう、ビデオを見ました。","Hôm qua tôi đã xem video."]]},{"word":"レポート","reading":"レポート","meaning":"báo cáo","hanViet":"","lesson":6,"ex":[["わたしはレポートを書きます。","Tôi viết báo cáo."],["レポートは難しいです。","Báo cáo khó."],["パソコンでレポートを書きます。","Tôi viết báo cáo bằng máy tính."],["レポートを読みます。","Tôi đọc báo cáo."],["レポートを出します。","Tôi nộp báo cáo."]]},{"word":"テニス","reading":"テニス","meaning":"quần vợt (～をします: đánh quần vợt)","hanViet":"","lesson":6,"ex":[["わたしはテニスをします。","Tôi chơi quần vợt."],["テニスは楽しいです。","Quần vợt thú vị."],["土曜日に友達とテニスをします。","Thứ bảy tôi cùng bạn đánh quần vợt."],["日曜日にテニスをします。","Vào chủ nhật tôi chơi quần vợt."],["テニスが好きですか。","Bạn có thích quần vợt không?"]]},{"word":"サッカー","reading":"サッカー","meaning":"bóng đá (～をします: chơi bóng đá)","hanViet":"","lesson":6,"ex":[["わたしはサッカーをします。","Tôi chơi bóng đá."],["サッカーが好きです。","Tôi thích bóng đá."],["学校でサッカーをします。","Tôi chơi bóng đá ở trường."],["土曜日にサッカーをします。","Vào thứ bảy tôi chơi bóng đá."],["サッカーを見ます。","Tôi xem bóng đá."]]},{"word":"します","reading":"します","meaning":"làm","hanViet":"","lesson":6,"ex":[["きょう、何をしますか。","Hôm nay bạn làm gì?"],["あした、買い物をします。","Ngày mai tôi đi mua sắm."],["日曜日に何をしますか。","Vào chủ nhật bạn làm gì?"],["わたしは毎日、宿題をします。","Mỗi ngày tôi làm bài tập về nhà."],["きのう、掃除をしました。","Hôm qua tôi đã dọn dẹp."]]},{"word":"ええ","reading":"ええ","meaning":"vâng, được, dạ (cách nói thân mật của 「はい」)","hanViet":"","lesson":6,"ex":[["「コーヒーを飲みますか。」「ええ、飲みます。」","— Bạn có uống cà phê không? — Vâng, tôi uống."],["「あした来ますか。」「ええ、来ます。」","— Ngày mai bạn đến không? — Vâng, tôi đến."],["「日本語がわかりますか。」「ええ、わかります。」","— Bạn có hiểu tiếng Nhật không? — Vâng, tôi hiểu."],["「テニスをしますか。」「ええ、します。」","— Bạn có chơi quần vợt không? — Vâng, tôi chơi."],["「お元気ですか。」「ええ、元気です。」","— Anh có khỏe không? — Vâng, tôi khỏe."]]},{"word":"いいですね","reading":"いいですね","meaning":"Được đấy nhỉ./ hay quá.","hanViet":"","lesson":6,"ex":[["この映画はいいですね。","Bộ phim này hay nhỉ."],["この本はいいですね。","Quyển sách này hay nhỉ."],["あしたは休みです。いいですね。","Ngày mai là ngày nghỉ. Thích nhỉ."],["この歌はいいですね。","Bài hát này hay nhỉ."],["「いっしょに行きましょう。」「いいですね。」","— Cùng đi nhé. — Được đấy."]]},{"word":"わかりました","reading":"わかりました","meaning":"Tôi hiểu rồi/ vâng ạ.","hanViet":"","lesson":6,"ex":[["はい、わかりました。","Vâng, tôi hiểu rồi."],["はい、わかりました。ありがとうございます。","Vâng, tôi hiểu rồi. Cảm ơn anh."],["「あした来てください。」「はい、わかりました。」","— Ngày mai hãy đến nhé. — Vâng, tôi hiểu rồi."],["わかりました。あした行きます。","Tôi hiểu rồi. Ngày mai tôi sẽ đi."],["「宿題をしてください。」「はい、わかりました。」","— Hãy làm bài tập về nhà. — Vâng, tôi hiểu rồi."]]},{"word":"何ですか","reading":"なんですか","meaning":"Có gì đấy ạ?/ cái gì vậy?/ vâng có tôi. (câu trả lời khi người khác gọi tên mình)","hanViet":"HÀ","lesson":6,"ex":[["「田中さん。」「何ですか。」","— Anh Tanaka. — Vâng, có tôi."],["はい、何ですか。","Vâng, có gì ạ?"],["「山田さん。」「はい、何ですか。」","— Anh Yamada. — Vâng, có gì ạ?"],["すみません、何ですか。","Xin lỗi, có gì ạ?"],["「すみません。」「何ですか。」","— Xin lỗi. — Có gì ạ?"]]},{"word":"じゃ、また明日","reading":"じゃ、またあした","meaning":"Vậy nhé, hẹn gặp lại ngày mai","hanViet":"MINH NHẬT","lesson":6,"ex":[["じゃ、また明日。","Vậy nhé, hẹn gặp lại ngày mai."],["「じゃ、また明日。」「はい、また明日。」","— Vậy nhé, hẹn gặp lại ngày mai. — Vâng, hẹn gặp lại ngày mai."],["学校で友達に「じゃ、また明日」と言います。","Ở trường tôi nói với bạn \"Vậy nhé, hẹn gặp lại ngày mai\"."],["じゃ、また明日。ありがとう。","Vậy nhé, hẹn gặp lại ngày mai. Cảm ơn nhé."],["きょうは楽しかったです。じゃ、また明日。","Hôm nay vui quá. Vậy nhé, hẹn gặp lại ngày mai."]]},{"word":"切ります","reading":"きります","meaning":"Cắt","hanViet":"THIẾT","lesson":7,"ex":[["はさみで紙を切ります。","Tôi cắt giấy bằng kéo."],["母は野菜を切ります。","Mẹ tôi cắt rau."],["紙を切ってください。","Xin hãy cắt giấy."],["りんごを切ります。","Tôi cắt táo."],["きのう、紙を切りました。","Hôm qua tôi đã cắt giấy."]]},{"word":"送ります","reading":"おくります","meaning":"Gửi; tiễn đưa","hanViet":"TỐNG","lesson":7,"ex":[["友達に手紙を送ります。","Tôi gửi thư cho bạn."],["母にメールを送ります。","Tôi gửi email cho mẹ."],["先生に手紙を送りました。","Tôi đã gửi thư cho thầy giáo."],["友達にプレゼントを送ります。","Tôi gửi quà tặng cho bạn."],["母に荷物を送ります。","Tôi gửi hành lý cho mẹ."]]},{"word":"あげます","reading":"あげます","meaning":"cho, tặng","hanViet":"","lesson":7,"ex":[["母に花をあげます。","Tôi tặng hoa cho mẹ."],["友達に本をあげます。","Tôi tặng sách cho bạn."],["子どもにお菓子をあげます。","Tôi cho trẻ em bánh kẹo."],["先生に花をあげました。","Tôi đã tặng hoa cho thầy giáo."],["誕生日にプレゼントをあげます。","Vào sinh nhật tôi tặng quà."]]},{"word":"もらいます","reading":"もらいます","meaning":"nhận","hanViet":"","lesson":7,"ex":[["先生に本をもらいます。","Tôi nhận sách từ thầy giáo."],["友達にプレゼントをもらいました。","Tôi đã nhận quà tặng từ bạn."],["母にお金をもらいます。","Tôi nhận tiền từ mẹ."],["誕生日に花をもらいました。","Vào sinh nhật tôi đã nhận hoa."],["先生に辞書をもらいます。","Tôi nhận từ điển từ thầy giáo."]]},{"word":"貸します","reading":"かします","meaning":"cho mượn, cho vay","hanViet":"","lesson":7,"ex":[["友達に本を貸します。","Tôi cho bạn mượn sách."],["友達に辞書を貸します。","Tôi cho bạn mượn từ điển."],["友達にお金を貸しました。","Tôi đã cho bạn vay tiền."],["ボールペンを貸してください。","Xin hãy cho tôi mượn bút bi."],["友達に傘を貸します。","Tôi cho bạn mượn ô."]]},{"word":"借ります","reading":"かります","meaning":"Mượn, thuê","hanViet":"TÁ","lesson":7,"ex":[["友達から辞書を借ります。","Tôi mượn từ điển của bạn."],["友達から本を借ります。","Tôi mượn sách của bạn."],["先生から辞書を借りました。","Tôi đã mượn từ điển của thầy giáo."],["図書館で本を借ります。","Tôi mượn sách ở thư viện."],["傘を借りてもいいですか。","Tôi mượn ô được không ạ?"]]},{"word":"教えます","reading":"おしえます","meaning":"Dạy, cho biết","hanViet":"GIÁO","lesson":7,"ex":[["先生は私に日本語を教えます。","Thầy giáo dạy tiếng Nhật cho tôi."],["先生は私に英語を教えます。","Thầy giáo dạy tiếng Anh cho tôi."],["友達に日本語を教えます。","Tôi dạy tiếng Nhật cho bạn."],["道を教えてください。","Xin hãy chỉ đường cho tôi."],["母は私に料理を教えます。","Mẹ dạy tôi nấu ăn."]]},{"word":"習います","reading":"ならいます","meaning":"Học (được dạy)","hanViet":"TẬP","lesson":7,"ex":[["先生に日本語を習います。","Tôi học tiếng Nhật với thầy giáo."],["先生に英語を習います。","Tôi học tiếng Anh với thầy giáo."],["田中さんは大学で英語を習います。","Anh Tanaka học tiếng Anh ở trường đại học."],["先生に歌を習います。","Tôi học hát với thầy giáo."],["学校で日本語を習います。","Tôi học tiếng Nhật ở trường."]]},{"word":"かけます","reading":"かけます","meaning":"gọi [điện thoại]","hanViet":"","lesson":7,"ex":[["母に電話をかけます。","Tôi gọi điện thoại cho mẹ."],["父に電話をかけます。","Tôi gọi điện thoại cho cha."],["先生に電話をかけました。","Tôi đã gọi điện thoại cho thầy giáo."],["きのう、母に電話をかけました。","Hôm qua tôi đã gọi điện thoại cho mẹ."],["電話をかけてください。","Xin hãy gọi điện thoại."]]},{"word":"手","reading":"て","meaning":"Tay","hanViet":"THỦ","lesson":7,"ex":[["手で食べます。","Tôi ăn bằng tay."],["ごはんの前に手を洗います。","Trước bữa cơm tôi rửa tay."],["手が痛いです。","Tay tôi đau."],["手で書きます。","Tôi viết bằng tay."],["手で作ります。","Tôi làm bằng tay."]]},{"word":"はし","reading":"はし","meaning":"đũa","hanViet":"","lesson":7,"ex":[["はしでごはんを食べます。","Tôi ăn cơm bằng đũa."],["はしで魚を食べます。","Tôi ăn cá bằng đũa."],["はしで肉を食べます。","Tôi ăn thịt bằng đũa."],["はしを使います。","Tôi dùng đũa."],["はしは長いです。","Đũa dài."]]},{"word":"はさみ","reading":"はさみ","meaning":"cái kéo","hanViet":"","lesson":7,"ex":[["はさみは机の上にあります。","Cái kéo ở trên bàn."],["はさみを貸してください。","Xin hãy cho tôi mượn cái kéo."],["はさみは箱の中にあります。","Cái kéo ở trong hộp."],["はさみを使います。","Tôi dùng kéo."],["はさみを買いました。","Tôi đã mua kéo."]]},{"word":"紙","reading":"かみ","meaning":"giấy","hanViet":"CHỈ","lesson":7,"ex":[["紙に名前を書きます。","Tôi viết tên vào giấy."],["紙に字を書きます。","Tôi viết chữ vào giấy."],["紙を切ります。","Tôi cắt giấy."],["紙は白いです。","Giấy màu trắng."],["店で紙を買いました。","Tôi đã mua giấy ở cửa hàng."]]},{"word":"花","reading":"はな","meaning":"Hoa","hanViet":"HOA","lesson":7,"ex":[["花はきれいです。","Hoa đẹp."],["花が好きです。","Tôi thích hoa."],["店で花を買いました。","Tôi đã mua hoa ở cửa hàng."],["庭に花があります。","Trong sân có hoa."],["花は赤いです。","Hoa màu đỏ."]]},{"word":"荷物","reading":"にもつ","meaning":"Hành lý, hàng hóa","hanViet":"HÀ VẬT","lesson":7,"ex":[["荷物は重いです。","Hành lý nặng."],["荷物は多いです。","Hành lý nhiều."],["荷物を持ちます。","Tôi mang hành lý."],["荷物を送ります。","Tôi gửi hành lý."],["荷物は大きいです。","Hành lý to."]]},{"word":"お金","reading":"おかね","meaning":"Tiền","hanViet":"KIM","lesson":7,"ex":[["お金を貸してください。","Xin hãy cho tôi mượn tiền."],["お金がありません。","Tôi không có tiền."],["きのう銀行でお金を借りました。","Hôm qua tôi đã vay tiền ở ngân hàng."],["お金は大切です。","Tiền quan trọng."],["お金を借ります。","Tôi vay tiền."]]},{"word":"切符","reading":"きっぷ","meaning":"Vé (tàu, xe)","hanViet":"THIẾT PHÙ","lesson":7,"ex":[["駅で切符を買います。","Tôi mua vé ở ga."],["切符は高いです。","Vé đắt."],["駅で切符を二枚買いました。","Tôi đã mua hai vé ở ga."],["切符をください。","Cho tôi vé."],["切符がありません。","Tôi không có vé."]]},{"word":"父","reading":"ちち","meaning":"Cha (của mình)","hanViet":"PHỤ","lesson":7,"ex":[["父は会社員です。","Cha tôi là nhân viên công ty."],["父は先生です。","Cha tôi là giáo viên."],["父は元気です。","Cha tôi khỏe."],["父は会社へ行きます。","Cha tôi đi đến công ty."],["父はビールが好きです。","Cha tôi thích bia."]]},{"word":"母","reading":"はは","meaning":"Mẹ (của mình)","hanViet":"MẪU","lesson":7,"ex":[["母は先生です。","Mẹ tôi là giáo viên."],["母は会社員です。","Mẹ tôi là nhân viên công ty."],["母は料理が上手です。","Mẹ tôi nấu ăn giỏi."],["母は元気です。","Mẹ tôi khỏe."],["母は買い物をします。","Mẹ tôi đi mua sắm."]]},{"word":"お父さん","reading":"おとうさん","meaning":"cha (anh)","hanViet":"PHỤ","lesson":7,"ex":[["お父さんは元気ですか。","Cha anh có khỏe không?"],["お父さんは会社員ですか。","Cha anh có phải là nhân viên công ty không?"],["お父さんは来週、ベトナムへ行きます。","Tuần sau bố tôi đi Việt Nam."],["お父さんは先生ですか。","Cha anh có phải là giáo viên không?"],["お父さんはどこにいますか。","Cha anh ở đâu?"]]},{"word":"お母さん","reading":"おかあさん","meaning":"mẹ(anh)","hanViet":"MẪU","lesson":7,"ex":[["お母さんは料理が上手です。","Mẹ anh nấu ăn giỏi."],["お母さんは元気ですか。","Mẹ anh có khỏe không?"],["お母さんは先生ですか。","Mẹ anh có phải là giáo viên không?"],["お母さんは何歳ですか。","Mẹ anh bao nhiêu tuổi?"],["お母さんはどこにいますか。","Mẹ anh ở đâu?"]]},{"word":"もう","reading":"もう","meaning":"đã rồi","hanViet":"","lesson":7,"ex":[["もうごはんを食べました。","Tôi đã ăn cơm rồi."],["もう宿題をしました。","Tôi đã làm bài tập về nhà rồi."],["もう昼ごはんを食べました。","Tôi đã ăn trưa rồi."],["「もう行きましたか。」「はい、もう行きました。」","— Bạn đã đi rồi à? — Vâng, tôi đã đi rồi."],["もう本を読みました。","Tôi đã đọc sách rồi."]]},{"word":"まだ","reading":"まだ","meaning":"vẫn còn , vẫn chưa","hanViet":"","lesson":7,"ex":[["まだごはんを食べていません。","Tôi vẫn chưa ăn cơm."],["まだ宿題をしていません。","Tôi vẫn chưa làm bài tập về nhà."],["まだ学校へ行っていません。","Tôi vẫn chưa đi đến trường."],["まだ本を読んでいません。","Tôi vẫn chưa đọc sách."],["「もう食べましたか。」「いいえ、まだです。」","— Bạn đã ăn rồi à? — Chưa, vẫn chưa."]]},{"word":"これから","reading":"これから","meaning":"từ bây giờ-","hanViet":"","lesson":7,"ex":[["これから学校へ行きます。","Từ bây giờ tôi đi đến trường."],["これから買い物をします。","Từ bây giờ tôi đi mua sắm."],["これから何をしますか。","Từ bây giờ bạn làm gì?"],["これから日本語を勉強します。","Từ bây giờ tôi học tiếng Nhật."],["これから友達に会います。","Từ bây giờ tôi gặp bạn."]]},{"word":"ごめんください","reading":"ごめんください","meaning":"Xin lỗi, có ai ở nhà không?/ Tôi có thể vào được chứ?","hanViet":"","lesson":7,"ex":[["ごめんください。田中さんはいらっしゃいますか。","Xin lỗi, có anh Tanaka ở nhà không?"],["ごめんください。山田さんはいますか。","Xin lỗi, anh Yamada có ở nhà không?"],["「ごめんください。」「はい、どうぞ。」","— Xin lỗi, có ai ở nhà không? — Vâng, xin mời vào."],["ごめんください。入ってもいいですか。","Xin lỗi, tôi vào được không ạ?"],["ごめんください。わたしは田中です。","Xin lỗi, tôi là Tanaka."]]},{"word":"いらっしゃい","reading":"いらっしゃい","meaning":"xin mời","hanViet":"","lesson":7,"ex":[["いらっしゃい。お元気ですか。","Xin mời vào. Anh có khỏe không?"],["「ごめんください。」「はい、いらっしゃい。」","— Xin lỗi, có ai ở nhà không? — Vâng, xin mời vào."],["いらっしゃい。どうぞ入ってください。","Xin mời vào. Xin hãy vào."],["いらっしゃい。コーヒーをどうぞ。","Xin mời vào. Mời anh uống cà phê."],["いらっしゃい。お茶をどうぞ。","Xin mời vào. Mời anh uống trà."]]},{"word":"失礼します","reading":"しつれいします","meaning":"Xin thất lễ","hanViet":"","lesson":7,"ex":[["失礼します。入ってもいいですか。","Xin thất lễ. Tôi vào được không ạ?"],["失礼します。田中先生に会いたいです。","Xin thất lễ. Tôi muốn gặp thầy Tanaka."],["「失礼します。」「はい、どうぞ。」","— Xin thất lễ. — Vâng, xin mời."],["失礼します。もう帰ります。","Xin thất lễ. Tôi về đây."],["失礼します。教室に入ってもいいですか。","Xin thất lễ. Tôi vào lớp học được không ạ?"]]},{"word":"いかがですか","reading":"いかがですか","meaning":"Anh/chị dùng [~] có được không?","hanViet":"","lesson":7,"ex":[["コーヒーはいかがですか。","Anh dùng cà phê có được không?"],["お茶はいかがですか。","Anh dùng trà có được không?"],["ケーキはいかがですか。","Anh dùng bánh có được không?"],["「ジュースはいかがですか。」「ありがとうございます。」","— Anh dùng nước hoa quả có được không? — Cảm ơn anh."],["紅茶はいかがですか。","Anh dùng hồng trà có được không?"]]},{"word":"いただきます","reading":"いただきます","meaning":"Xin nhận ~. (cách nói dùng trước khi ăn hoặc uống)","hanViet":"","lesson":7,"ex":[["ごはんを食べる前に、『いただきます』と言います。","Trước khi ăn cơm, chúng ta nói “いただきます”."],["昼ごはんの前に「いただきます」と言います。","Trước bữa trưa, tôi nói \"いただきます\"."],["わたしは「いただきます」と言って、ごはんを食べます。","Tôi nói \"いただきます\" rồi ăn cơm."],["母と「いただきます」と言います。","Tôi nói \"いただきます\" cùng mẹ."],["「いただきます」と言って、みそ汁を飲みます。","Tôi nói \"いただきます\" rồi uống súp miso."]]},{"word":"旅行","reading":"りょこう","meaning":"Du lịch","hanViet":"LỮ HÀNH","lesson":7,"ex":[["夏に日本へ旅行します。","Mùa hè tôi đi du lịch Nhật Bản."],["旅行は楽しいです。","Du lịch thú vị."],["友達と旅行します。","Tôi đi du lịch cùng bạn."],["冬に旅行します。","Vào mùa đông tôi đi du lịch."],["旅行が好きです。","Tôi thích du lịch."]]},{"word":"お土産","reading":"おみやげ","meaning":"Quà lưu niệm, đặc sản","hanViet":"THỔ SẢN","lesson":7,"ex":[["友達にお土産をあげます。","Tôi tặng quà lưu niệm cho bạn."],["日本でお土産を買いました。","Tôi đã mua quà lưu niệm ở Nhật Bản."],["母にお土産をあげました。","Tôi đã tặng quà lưu niệm cho mẹ."],["お土産をもらいました。","Tôi đã nhận quà lưu niệm."],["お土産はきれいです。","Quà lưu niệm đẹp."]]},{"word":"ごちそうさまでした","reading":"ごちそうさまでした","meaning":"Cảm ơn vì bữa ăn","hanViet":"","lesson":7,"ex":[["ごちそうさまでした。おいしかったです。","Cảm ơn vì bữa ăn. Ngon lắm."],["ごちそうさまでした。ありがとうございました。","Cảm ơn vì bữa ăn. Cảm ơn anh nhiều."],["ごはんを食べて、「ごちそうさまでした」と言います。","Ăn cơm xong, tôi nói \"ごちそうさまでした\"."],["「ごちそうさまでした。」「どういたしまして。」","— Cảm ơn vì bữa ăn. — Không có gì."],["ごちそうさまでした。おなかがいっぱいです。","Cảm ơn vì bữa ăn. Tôi no rồi."]]},{"word":"メール","reading":"メール","meaning":"thư điện tử, email","hanViet":"","lesson":7,"ex":[["友達にメールを送ります。","Tôi gửi email cho bạn."],["メールを書きます。","Tôi viết email."],["メールを読みます。","Tôi đọc email."],["先生にメールを送りました。","Tôi đã gửi email cho thầy giáo."],["メールが来ました。","Email đã đến."]]},{"word":"ケータイ","reading":"ケータイ","meaning":"điện thoại di động","hanViet":"","lesson":7,"ex":[["ケータイで電話をかけます。","Tôi gọi điện thoại bằng điện thoại di động."],["ケータイを持っています。","Tôi có điện thoại di động."],["ケータイは新しいです。","Điện thoại di động mới."],["ケータイを買いました。","Tôi đã mua điện thoại di động."],["ケータイでメールを書きます。","Tôi viết email bằng điện thoại di động."]]},{"word":"スプーン","reading":"スプーン","meaning":"muỗng (spoon)","hanViet":"","lesson":7,"ex":[["スプーンでごはんを食べます。","Tôi ăn cơm bằng muỗng."],["スプーンでケーキを食べます。","Tôi ăn bánh bằng muỗng."],["スプーンを使います。","Tôi dùng muỗng."],["スプーンをください。","Cho tôi cái muỗng."],["スプーンは机の上にあります。","Cái muỗng ở trên bàn."]]},{"word":"ナイフ","reading":"ナイフ","meaning":"con dao (knife)","hanViet":"","lesson":7,"ex":[["ナイフでパンを切ります。","Tôi cắt bánh mì bằng dao."],["ナイフで肉を切ります。","Tôi cắt thịt bằng dao."],["ナイフを使います。","Tôi dùng dao."],["ナイフをください。","Cho tôi con dao."],["ナイフは台所にあります。","Con dao ở trong bếp."]]},{"word":"フォーク","reading":"フォーク","meaning":"nĩa (fork)","hanViet":"","lesson":7,"ex":[["フォークで肉を食べます。","Tôi ăn thịt bằng nĩa."],["フォークで魚を食べます。","Tôi ăn cá bằng nĩa."],["フォークを使います。","Tôi dùng nĩa."],["フォークをください。","Cho tôi cái nĩa."],["フォークは机の上にあります。","Cái nĩa ở trên bàn."]]},{"word":"ファックス","reading":"ファックス","meaning":"fax","hanViet":"","lesson":7,"ex":[["ファックスで手紙を送ります。","Tôi gửi thư bằng fax."],["ファックスを送ります。","Tôi gửi fax."],["ファックスで手紙を送りました。","Tôi đã gửi thư bằng fax."],["ファックスが来ました。","Fax đã đến."],["ファックスを使います。","Tôi dùng fax."]]},{"word":"ワープロ","reading":"ワープロ","meaning":"máy đánh chữ","hanViet":"","lesson":7,"ex":[["ワープロで手紙を書きます。","Tôi viết thư bằng máy đánh chữ."],["ワープロでレポートを書きます。","Tôi viết báo cáo bằng máy đánh chữ."],["ワープロを使います。","Tôi dùng máy đánh chữ."],["ワープロは古いです。","Máy đánh chữ cũ."],["ワープロを買いました。","Tôi đã mua máy đánh chữ."]]},{"word":"パソコン","reading":"パソコン","meaning":"máy tính","hanViet":"","lesson":7,"ex":[["パソコンでメールを書きます。","Tôi viết email bằng máy tính."],["パソコンで宿題をします。","Tôi làm bài tập về nhà bằng máy tính."],["パソコンで日本語を勉強します。","Tôi học tiếng Nhật bằng máy tính."],["パソコンは新しいです。","Máy tính mới."],["パソコンを買いました。","Tôi đã mua máy tính."]]},{"word":"パンチ","reading":"パンチ","meaning":"cái đục lỗ","hanViet":"","lesson":7,"ex":[["パンチを貸してください。","Xin hãy cho tôi mượn cái đục lỗ."],["パンチを使います。","Tôi dùng cái đục lỗ."],["パンチは机の上にあります。","Cái đục lỗ ở trên bàn."],["パンチを借りてもいいですか。","Tôi mượn cái đục lỗ được không ạ?"],["パンチを買いました。","Tôi đã mua cái đục lỗ."]]},{"word":"ホチキス","reading":"ホチキス","meaning":"cái dập ghim","hanViet":"","lesson":7,"ex":[["ホチキスで紙をとめます。","Tôi dập ghim giấy lại bằng cái dập ghim."],["ホチキスを使います。","Tôi dùng cái dập ghim."],["ホチキスで紙をとめました。","Tôi đã dập ghim giấy lại."],["ホチキスを貸してください。","Xin hãy cho tôi mượn cái dập ghim."],["ホチキスは机の上にあります。","Cái dập ghim ở trên bàn."]]},{"word":"セロテープ","reading":"セロテープ","meaning":"băng keo nhựa","hanViet":"","lesson":7,"ex":[["セロテープで箱を閉めます。","Tôi dán kín hộp bằng băng keo nhựa."],["セロテープを使います。","Tôi dùng băng keo nhựa."],["セロテープで箱を閉めました。","Tôi đã dán kín hộp bằng băng keo nhựa."],["セロテープを貸してください。","Xin hãy cho tôi mượn băng keo nhựa."],["セロテープは机の上にあります。","Băng keo nhựa ở trên bàn."]]},{"word":"消しゴム","reading":"けしゴム","meaning":"cục tẩy","hanViet":"","lesson":7,"ex":[["消しゴムで字を消します。","Tôi xóa chữ bằng cục tẩy."],["消しゴムを使います。","Tôi dùng cục tẩy."],["消しゴムで字を消しました。","Tôi đã xóa chữ bằng cục tẩy."],["消しゴムを貸してください。","Xin hãy cho tôi mượn cục tẩy."],["消しゴムは机の上にあります。","Cục tẩy ở trên bàn."]]},{"word":"シャツ","reading":"シャツ","meaning":"áo sơ mi","hanViet":"","lesson":7,"ex":[["新しいシャツを買います。","Tôi mua áo sơ mi mới."],["シャツは白いです。","Áo sơ mi màu trắng."],["デパートでシャツを買いました。","Tôi đã mua áo sơ mi ở cửa hàng bách hóa."],["シャツは安いです。","Áo sơ mi rẻ."],["シャツを着ます。","Tôi mặc áo sơ mi."]]},{"word":"プレゼント","reading":"プレゼント","meaning":"quà tặng (present)","hanViet":"","lesson":7,"ex":[["友達にプレゼントをあげます。","Tôi tặng quà cho bạn."],["プレゼントをもらいました。","Tôi đã nhận quà tặng."],["母にプレゼントをあげました。","Tôi đã tặng quà cho mẹ."],["デパートでプレゼントを買いました。","Tôi đã mua quà tặng ở cửa hàng bách hóa."],["プレゼントはきれいです。","Quà tặng đẹp."]]},{"word":"クリスマス","reading":"クリスマス","meaning":"Lễ Giáng sinh","hanViet":"","lesson":7,"ex":[["クリスマスにプレゼントをもらいます。","Vào lễ Giáng sinh, tôi nhận quà tặng."],["クリスマスは12月25日です。","Lễ Giáng sinh là ngày 25 tháng 12."],["クリスマスにケーキを食べます。","Vào lễ Giáng sinh tôi ăn bánh."],["クリスマスは楽しいです。","Lễ Giáng sinh vui."],["クリスマスに友達に会います。","Vào lễ Giáng sinh tôi gặp bạn."]]},{"word":"年賀状","reading":"ねんがじょう","meaning":"thiệp mừng năm mới","hanViet":"NIÊN HẠ TRẠNG","lesson":7,"ex":[["お正月に年賀状を送ります。","Ngày Tết tôi gửi thiệp mừng năm mới."],["年賀状を書きます。","Tôi viết thiệp mừng năm mới."],["友達に年賀状を送りました。","Tôi đã gửi thiệp mừng năm mới cho bạn."],["年賀状をもらいました。","Tôi đã nhận thiệp mừng năm mới."],["年賀状はきれいです。","Thiệp mừng năm mới đẹp."]]},{"word":"きれい","reading":"きれい","meaning":"(cảnh) đẹp, đẹp (gái), sạch","hanViet":"","lesson":8,"ex":[["この花はきれいです。","Bông hoa này đẹp."],["この部屋はきれいです。","Căn phòng này sạch đẹp."],["海はきれいです。","Biển đẹp."],["これはきれいな花です。","Đây là bông hoa đẹp."],["山はきれいです。","Núi đẹp."]]},{"word":"静か","reading":"しずか","meaning":"yên tĩnh","hanViet":"TĨNH","lesson":8,"ex":[["この町は静かです。","Thị trấn này yên tĩnh."],["この図書館は静かです。","Thư viện này yên tĩnh."],["夜はこの町が静かになります。","Ban đêm thị trấn này trở nên yên tĩnh."],["静かな所で本を読みたいです。","Tôi muốn đọc sách ở nơi yên tĩnh."],["寮の部屋は静かですか。","Phòng ký túc xá có yên tĩnh không?"]]},{"word":"にぎやか","reading":"にぎやか","meaning":"nhộn nhịp","hanViet":"","lesson":8,"ex":[["駅の前はにぎやかです。","Trước ga nhộn nhịp."],["日曜日は店がにぎやかです。","Chủ nhật cửa hàng nhộn nhịp."],["祭りはにぎやかでした。","Lễ hội đã rất nhộn nhịp."],["にぎやかな町に住んでいます。","Tôi đang sống ở thị trấn nhộn nhịp."],["このレストランは夜にぎやかになります。","Nhà hàng này buổi tối trở nên nhộn nhịp."]]},{"word":"有名","reading":"ゆうめい","meaning":"Nổi tiếng","hanViet":"HỮU DANH","lesson":8,"ex":[["このレストランは有名です。","Nhà hàng này nổi tiếng."],["この歌は有名です。","Bài hát này nổi tiếng."],["あの先生は日本で有名です。","Thầy giáo kia nổi tiếng ở Nhật."],["有名なレストランでごはんを食べました。","Tôi đã ăn cơm ở nhà hàng nổi tiếng."],["この山は有名ですか。","Ngọn núi này có nổi tiếng không?"]]},{"word":"親切","reading":"しんせつ","meaning":"Tử tế, tốt bụng","hanViet":"THÂN THIẾT","lesson":8,"ex":[["田中さんは親切です。","Anh Tanaka tử tế."],["店員は親切です。","Nhân viên cửa hàng tử tế."],["親切な友達がいます。","Tôi có bạn bè tử tế."],["先生は親切でした。","Thầy giáo đã rất tử tế."],["あの人は親切ですか。","Người kia có tử tế không?"]]},{"word":"元気","reading":"げんき","meaning":"Khoẻ mạnh","hanViet":"NGUYÊN KHÍ","lesson":8,"ex":[["お母さんは元気です。","Mẹ tôi khỏe mạnh."],["おじいさんは八十歳ですが、元気です。","Ông tôi 80 tuổi nhưng vẫn khỏe mạnh."],["お母さんは元気でしたか。","Mẹ bạn đã khỏe không?"],["元気な子どもがたくさんいます。","Có nhiều trẻ em khỏe mạnh."],["病気でしたけど、今は元気です。","Tôi đã bị bệnh nhưng bây giờ khỏe rồi."]]},{"word":"暇","reading":"ひま","meaning":"rảnh rỗi, thời gian rỗi","hanViet":"HẠ","lesson":8,"ex":[["日曜日は暇です。","Chủ nhật tôi rảnh."],["あしたは暇です。","Ngày mai tôi rảnh."],["暇なとき、本を読みます。","Khi rảnh, tôi đọc sách."],["日曜日は暇でした。","Chủ nhật tôi đã rảnh."],["暇な時間がありますか。","Bạn có thời gian rảnh không?"]]},{"word":"便利","reading":"べんり","meaning":"Tiện lợi","hanViet":"TIỆN LỢI","lesson":8,"ex":[["電車は便利です。","Tàu điện tiện lợi."],["この店は便利です。","Cửa hàng này tiện lợi."],["この町は便利です。","Thị trấn này tiện lợi."],["便利なコンピューターを買いました。","Tôi đã mua máy tính tiện lợi."],["コンビニは便利ですか。","Cửa hàng tiện lợi có tiện không?"]]},{"word":"すてき","reading":"すてき","meaning":"tuyệt vời","hanViet":"","lesson":8,"ex":[["この歌はすてきです。","Bài hát này tuyệt vời."],["この花はすてきです。","Bông hoa này tuyệt vời."],["すてきな歌を聞きました。","Tôi đã nghe bài hát tuyệt vời."],["あの絵はすてきでした。","Bức tranh kia đã rất tuyệt vời."],["すてきなプレゼントをもらいました。","Tôi đã nhận được món quà tuyệt vời."]]},{"word":"大きい","reading":"おおきい","meaning":"To, lớn","hanViet":"ĐẠI","lesson":8,"ex":[["この山は大きいです。","Ngọn núi này lớn."],["このかばんは大きいです。","Cái cặp này to."],["大きい犬が好きです。","Tôi thích chó to."],["この部屋は大きくありません。","Căn phòng này không to."],["あの山よりこの山のほうが大きいです。","Ngọn núi này to hơn ngọn núi kia."]]},{"word":"小さい","reading":"ちいさい","meaning":"Nhỏ, bé","hanViet":"TIỂU","lesson":8,"ex":[["この部屋は小さいです。","Căn phòng này nhỏ."],["このみかんは小さいです。","Quả quýt này nhỏ."],["小さい花を買いました。","Tôi đã mua bông hoa nhỏ."],["小さい車が好きです。","Tôi thích xe nhỏ."],["この字は小さいですか。","Chữ này có nhỏ không?"]]},{"word":"新しい","reading":"あたらしい","meaning":"Mới","hanViet":"TÂN","lesson":8,"ex":[["新しい本を買いました。","Tôi đã mua sách mới."],["この本は新しいですか。","Cuốn sách này có mới không?"],["新しい辞書が欲しいです。","Tôi muốn có từ điển mới."],["あした新しい本を読みます。","Ngày mai tôi sẽ đọc sách mới."],["新しい先生に会いました。","Tôi đã gặp thầy giáo mới."]]},{"word":"古い","reading":"ふるい","meaning":"Cũ","hanViet":"CỔ","lesson":8,"ex":[["この本は古いです。","Cuốn sách này cũ."],["この辞書は古いです。","Cuốn từ điển này cũ."],["古い車に乗ります。","Tôi đi xe cũ."],["古い本を読みました。","Tôi đã đọc sách cũ."],["このうちは古いですか。","Ngôi nhà này có cũ không?"]]},{"word":"いい","reading":"いい","meaning":"tốt","hanViet":"","lesson":8,"ex":[["きょうは天気がいいです。","Hôm nay thời tiết tốt."],["この本はいいです。","Cuốn sách này hay."],["あしたは天気がいいでしょう。","Ngày mai thời tiết chắc sẽ tốt."],["いい歌ですね。","Bài hát hay nhỉ."],["このレストランはいいと思います。","Tôi nghĩ nhà hàng này tốt."]]},{"word":"悪い","reading":"わるい","meaning":"Xấu, tệ, không tốt","hanViet":"ÁC","lesson":8,"ex":[["きょうは天気が悪いです。","Hôm nay thời tiết xấu."],["きのうは天気が悪かったです。","Hôm qua thời tiết xấu."],["この本は悪くありません。","Cuốn sách này không tệ."],["この映画は悪かったです。","Bộ phim này đã tệ."],["きのうの天気は悪かったです。","Thời tiết hôm qua tệ."]]},{"word":"暑い","reading":"あつい","meaning":"Nóng (thời tiết)","hanViet":"THỬ","lesson":8,"ex":[["きょうは暑いです。","Hôm nay nóng."],["今日は暑いですから、水を飲みます。","Hôm nay nóng nên tôi uống nước."],["きのうは暑かったです。","Hôm qua nóng."],["暑いとき、ジュースを飲みます。","Khi trời nóng, tôi uống nước ép."],["あしたは暑いでしょう。","Ngày mai chắc sẽ nóng."]]},{"word":"寒い","reading":"さむい","meaning":"Lạnh (thời tiết)","hanViet":"HÀN","lesson":8,"ex":[["きょうは寒いです。","Hôm nay lạnh."],["今日は寒いですから、コートを着ます。","Hôm nay lạnh nên tôi mặc áo khoác."],["きのうは寒かったです。","Hôm qua lạnh."],["寒いとき、コートを着ます。","Khi trời lạnh, tôi mặc áo khoác."],["今朝は寒くありませんでした。","Sáng nay không lạnh."]]},{"word":"冷たい","reading":"つめたい","meaning":"Lạnh (khi chạm vào)","hanViet":"LÃNH","lesson":8,"ex":[["この水は冷たいです。","Nước này lạnh."],["このジュースは冷たいです。","Nước ép này lạnh."],["冷たい水を飲みたいです。","Tôi muốn uống nước lạnh."],["このビールは冷たくありません。","Bia này không lạnh."],["冷たいお茶をください。","Cho tôi trà lạnh."]]},{"word":"難しい","reading":"むずかしい","meaning":"khó","hanViet":"NÁN","lesson":8,"ex":[["日本語は難しいです。","Tiếng Nhật khó."],["日本語は難しいですか。","Tiếng Nhật có khó không?"],["この問題は難しかったです。","Bài tập này đã khó."],["難しい本を読みます。","Tôi đọc sách khó."],["この試験は難しくありませんでした。","Kỳ thi này đã không khó."]]},{"word":"易しい","reading":"やさしい","meaning":"Dễ, dễ hiểu","hanViet":"DỊCH","lesson":8,"ex":[["この本は易しいです。","Cuốn sách này dễ."],["この問題は易しいです。","Bài tập này dễ."],["易しい日本語で話します。","Tôi nói bằng tiếng Nhật dễ."],["この本は易しいですか。","Cuốn sách này có dễ không?"],["易しい歌を歌います。","Tôi hát bài hát dễ."]]},{"word":"高い","reading":"たかい","meaning":"Cao, đắt","hanViet":"CAO","lesson":8,"ex":[["この車は高いです。","Chiếc xe này đắt."],["この山は高いですか。","Ngọn núi này có cao không?"],["高い山に登ります。","Tôi leo núi cao."],["このかばんは高くありません。","Cái cặp này không đắt."],["高い本を買いました。","Tôi đã mua sách đắt."]]},{"word":"安い","reading":"やすい","meaning":"Rẻ","hanViet":"AN","lesson":8,"ex":[["この本は安いです。","Cuốn sách này rẻ."],["このりんごは安いです。","Quả táo này rẻ."],["安い本を買いたいです。","Tôi muốn mua sách rẻ."],["この店の魚は安かったです。","Cá ở cửa hàng này đã rẻ."],["安いレストランがありますか。","Có nhà hàng rẻ không?"]]},{"word":"低い","reading":"ひくい","meaning":"Thấp","hanViet":"ĐÊ","lesson":8,"ex":[["この山は低いです。","Ngọn núi này thấp."],["このビルは低いです。","Tòa nhà này thấp."],["低い机を買いました。","Tôi đã mua bàn thấp."],["あの山は低くありません。","Ngọn núi kia không thấp."],["この棚は低いです。","Cái kệ này thấp."]]},{"word":"おもしろい","reading":"おもしろい","meaning":"thú vị","hanViet":"","lesson":8,"ex":[["この映画はおもしろいです。","Bộ phim này thú vị."],["この話はおもしろいです。","Câu chuyện này thú vị."],["おもしろい話を聞きました。","Tôi đã nghe câu chuyện thú vị."],["このテレビはおもしろくありません。","Chương trình TV này không thú vị."],["おもしろい映画を見たいです。","Tôi muốn xem phim thú vị."]]},{"word":"おいしい","reading":"おいしい","meaning":"ngon","hanViet":"","lesson":8,"ex":[["寿司はおいしいです。","Sushi ngon."],["このパンはおいしいです。","Bánh mì này ngon."],["おいしい魚を食べました。","Tôi đã ăn cá ngon."],["この料理はおいしくありませんでした。","Món ăn này đã không ngon."],["おいしいケーキがありますか。","Có bánh ngon không?"]]},{"word":"忙しい","reading":"いそがしい","meaning":"Bận, bận rộn","hanViet":"MANG","lesson":8,"ex":[["先生は忙しいです。","Thầy giáo bận."],["父は忙しいです。","Bố tôi bận."],["忙しいとき、昼ごはんを食べません。","Khi bận, tôi không ăn trưa."],["今週は忙しかったです。","Tuần này tôi đã bận."],["忙しい日は早く寝ます。","Vào ngày bận, tôi ngủ sớm."]]},{"word":"楽しい","reading":"たのしい","meaning":"Vui, vui vẻ","hanViet":"LẠC","lesson":8,"ex":[["日本の生活は楽しいです。","Cuộc sống ở Nhật vui vẻ."],["学校は楽しいです。","Trường học vui."],["楽しい旅行をしました。","Tôi đã có chuyến du lịch vui vẻ."],["きのうのパーティーは楽しかったです。","Bữa tiệc hôm qua đã vui."],["楽しい歌を歌います。","Tôi hát bài hát vui."]]},{"word":"白い","reading":"しろい","meaning":"Trắng","hanViet":"BẠCH","lesson":8,"ex":[["この花は白いです。","Bông hoa này trắng."],["このシャツは白いです。","Áo sơ mi này trắng."],["白い花が好きです。","Tôi thích hoa trắng."],["白い猫がいます。","Có con mèo trắng."],["白い紙に字を書きます。","Tôi viết chữ lên giấy trắng."]]},{"word":"黒い","reading":"くろい","meaning":"Đen","hanViet":"HẮC","lesson":8,"ex":[["この車は黒いです。","Chiếc xe này đen."],["このかばんは黒いです。","Cái cặp này đen."],["黒い車を買いました。","Tôi đã mua xe đen."],["黒い犬がいます。","Có con chó đen."],["黒いシャツを買いました。","Tôi đã mua áo sơ mi đen."]]},{"word":"赤い","reading":"あかい","meaning":"Đỏ","hanViet":"XÍCH","lesson":8,"ex":[["赤いりんごを買いました。","Tôi đã mua táo đỏ."],["この花は赤いです。","Bông hoa này đỏ."],["赤いりんごは甘いです。","Táo đỏ ngọt."],["赤い車があります。","Có chiếc xe đỏ."],["赤いシャツを着ました。","Tôi đã mặc áo sơ mi đỏ."]]},{"word":"青い","reading":"あおい","meaning":"Xanh dương, xanh lam","hanViet":"THANH","lesson":8,"ex":[["海は青いです。","Biển xanh."],["青いシャツを着ます。","Tôi mặc áo sơ mi xanh."],["青い車を買いました。","Tôi đã mua xe xanh."],["青いボールペンで書きます。","Tôi viết bằng bút bi xanh."],["青い服が好きです。","Tôi thích quần áo xanh."]]},{"word":"桜","reading":"さくら","meaning":"hoa anh đào, cây anh đào","hanViet":"ANH","lesson":8,"ex":[["桜はきれいです。","Hoa anh đào đẹp."],["公園で桜を見ました。","Tôi đã ngắm hoa anh đào ở công viên."],["桜の花が好きです。","Tôi thích hoa anh đào."],["日本の桜は有名です。","Hoa anh đào Nhật nổi tiếng."],["春に桜を見ます。","Vào mùa xuân tôi ngắm hoa anh đào."]]},{"word":"山","reading":"やま","meaning":"Núi","hanViet":"SƠN","lesson":8,"ex":[["この山は高いです。","Ngọn núi này cao."],["うちのうしろに高い山があります。","Sau nhà tôi có ngọn núi cao."],["山の近くに住んでいます。","Tôi đang sống gần núi."],["山で写真を撮ります。","Tôi chụp ảnh ở núi."],["山と海が好きです。","Tôi thích núi và biển."]]},{"word":"町","reading":"まち","meaning":"Thị trấn, khu phố","hanViet":"ĐINH","lesson":8,"ex":[["わたしの町は小さいです。","Thị trấn của tôi nhỏ."],["この町はにぎやかです。","Thị trấn này nhộn nhịp."],["町の近くに駅があります。","Gần thị trấn có ga."],["小さい町に住んでいます。","Tôi đang sống ở thị trấn nhỏ."],["町で友達に会いました。","Tôi đã gặp bạn ở thị trấn."]]},{"word":"食べ物","reading":"たべもの","meaning":"Thức ăn, đồ ăn","hanViet":"THỰC VẬT","lesson":8,"ex":[["日本の食べ物はおいしいです。","Đồ ăn Nhật ngon."],["ベトナムの食べ物が好きです。","Tôi thích đồ ăn Việt Nam."],["食べ物を買いました。","Tôi đã mua đồ ăn."],["この食べ物は辛いです。","Đồ ăn này cay."],["食べ物をたくさん食べました。","Tôi đã ăn nhiều đồ ăn."]]},{"word":"車","reading":"くるま","meaning":"Xe, ô tô","hanViet":"XA","lesson":8,"ex":[["わたしの車は新しいです。","Xe của tôi mới."],["車で学校へ行きます。","Tôi đi học bằng xe."],["父の車は新しいです。","Xe của bố tôi mới."],["車を運転します。","Tôi lái xe."],["父の車は白いです。","Xe của bố tôi màu trắng."]]},{"word":"所","reading":"ところ","meaning":"Nơi, chỗ","hanViet":"SỞ","lesson":8,"ex":[["ここは静かな所です。","Đây là nơi yên tĩnh."],["ここはいい所です。","Đây là nơi tốt."],["静かな所に住みたいです。","Tôi muốn sống ở nơi yên tĩnh."],["図書館は勉強する所です。","Thư viện là nơi học bài."],["いい所がありますか。","Có nơi nào tốt không?"]]},{"word":"寮","reading":"りょう","meaning":"ký túc xá, nhà tập thể","hanViet":"LIÊU","lesson":8,"ex":[["わたしは寮に住んでいます。","Tôi đang sống ở ký túc xá."],["寮は学校の近くです。","Ký túc xá gần trường."],["寮で友達と話します。","Tôi nói chuyện với bạn ở ký túc xá."],["寮の部屋は小さいです。","Phòng ký túc xá nhỏ."],["寮に住みたいです。","Tôi muốn sống ở ký túc xá."]]},{"word":"勉強","reading":"べんきょう","meaning":"Học, học bài","hanViet":"MIỄN CƯỜNG","lesson":8,"ex":[["日本語の勉強は楽しいです。","Việc học tiếng Nhật vui."],["勉強は楽しいです。","Việc học vui."],["毎日日本語を勉強します。","Tôi học tiếng Nhật mỗi ngày."],["勉強が好きです。","Tôi thích học."],["勉強する時間がありますか。","Bạn có thời gian học không?"]]},{"word":"生活","reading":"せいかつ","meaning":"sinh hoạt, đời sống","hanViet":"SINH HOẠT","lesson":8,"ex":[["日本の生活は忙しいです。","Cuộc sống ở Nhật bận rộn."],["ベトナムの生活はどうですか。","Cuộc sống ở Việt Nam thế nào?"],["生活は大変です。","Cuộc sống vất vả."],["寮の生活は楽しいです。","Cuộc sống ký túc xá vui vẻ."],["日本の生活は便利です。","Cuộc sống ở Nhật tiện lợi."]]},{"word":"仕事","reading":"しごと","meaning":"Công việc","hanViet":"SĨ SỰ","lesson":8,"ex":[["仕事は楽しいです。","Công việc vui vẻ."],["仕事は忙しいです。","Công việc bận rộn."],["父の仕事は大変です。","Công việc của bố tôi vất vả."],["仕事が終わりました。","Công việc đã xong."],["あしたは仕事があります。","Ngày mai tôi có việc."]]},{"word":"どう","reading":"どう","meaning":"như thế nào","hanViet":"","lesson":8,"ex":[["日本の生活はどうですか。","Cuộc sống ở Nhật thế nào?"],["この本はどうですか。","Cuốn sách này thế nào?"],["きのうの映画はどうでしたか。","Bộ phim hôm qua thế nào?"],["日本語の勉強はどうですか。","Việc học tiếng Nhật thế nào?"],["あなたの町はどうですか。","Thị trấn của bạn thế nào?"]]},{"word":"どんな～","reading":"どんな～","meaning":"~ như thế nào","hanViet":"","lesson":8,"ex":[["どんな食べ物が好きですか。","Bạn thích đồ ăn như thế nào?"],["どんな本が好きですか。","Bạn thích sách như thế nào?"],["どんな音楽を聞きますか。","Bạn nghe nhạc như thế nào?"],["どんな映画を見ましたか。","Bạn đã xem phim như thế nào?"],["どんな仕事をしていますか。","Bạn đang làm công việc như thế nào?"]]},{"word":"緑","reading":"みどり","meaning":"Màu xanh lá cây","hanViet":"LỤC","lesson":8,"ex":[["山は緑です。","Núi xanh lá cây."],["このかばんは緑です。","Cái cặp này màu xanh lá."],["緑の山が好きです。","Tôi thích núi xanh lá."],["緑の車があります。","Có chiếc xe xanh lá."],["あの車は緑ですか。","Chiếc xe kia màu xanh lá không?"]]},{"word":"紫","reading":"むらさき","meaning":"Tím","hanViet":"","lesson":8,"ex":[["この花は紫です。","Bông hoa này màu tím."],["このセーターは紫です。","Áo len này màu tím."],["紫の花が好きです。","Tôi thích hoa tím."],["紫のかばんを買いました。","Tôi đã mua cặp tím."],["この花は紫ですか。","Bông hoa này màu tím không?"]]},{"word":"黄色い","reading":"きいろい","meaning":"màu vàng","hanViet":"HOÀNG SẮC","lesson":8,"ex":[["黄色いりんごは甘いです。","Táo vàng ngọt."],["このコートは黄色いです。","Áo khoác này màu vàng."],["黄色い花があります。","Có hoa vàng."],["黄色い車に乗ります。","Tôi đi xe vàng."],["黄色いりんごが好きです。","Tôi thích táo vàng."]]},{"word":"茶色い","reading":"ちゃいろい","meaning":"màu nâu","hanViet":"TRÀ","lesson":8,"ex":[["茶色い犬がいます。","Có một con chó màu nâu."],["このかばんは茶色いです。","Cái cặp này màu nâu."],["茶色い猫がいます。","Có con mèo nâu."],["茶色いコートを着ました。","Tôi đã mặc áo khoác nâu."],["茶色い犬が好きです。","Tôi thích chó nâu."]]},{"word":"味","reading":"あじ","meaning":"Vị, mùi vị","hanViet":"VỊ","lesson":8,"ex":[["この料理の味はいいです。","Món ăn này có vị ngon."],["この料理の味が好きです。","Tôi thích vị của món ăn này."],["味はどうですか。","Vị thế nào?"],["このケーキの味は甘いです。","Vị của bánh này ngọt."],["魚の味はいいですか。","Vị của cá có ngon không?"]]},{"word":"甘い","reading":"あまい","meaning":"Ngọt; dễ dãi, nhẹ tay","hanViet":"CAM","lesson":8,"ex":[["このケーキは甘いです。","Chiếc bánh này ngọt."],["このジュースは甘いです。","Nước ép này ngọt."],["甘いケーキが好きです。","Tôi thích bánh ngọt."],["このケーキは甘くありません。","Bánh này không ngọt."],["甘いりんごを買いました。","Tôi đã mua táo ngọt."]]},{"word":"辛い","reading":"からい","meaning":"Cay","hanViet":"TÂN","lesson":8,"ex":[["このカレーライスは辛いです。","Món cơm cà ri này cay."],["この料理は辛いです。","Món ăn này cay."],["辛いカレーライスが好きです。","Tôi thích cơm cà ri cay."],["このカレーライスは辛くありません。","Cơm cà ri này không cay."],["辛い料理を食べました。","Tôi đã ăn món cay."]]},{"word":"苦い","reading":"にがい","meaning":"Đắng","hanViet":"KHỔ","lesson":8,"ex":[["コーヒーは苦いです。","Cà phê đắng."],["このお茶は苦いです。","Trà này đắng."],["苦いコーヒーを飲みました。","Tôi đã uống cà phê đắng."],["この薬は苦いです。","Thuốc này đắng."],["苦いお茶が好きですか。","Bạn có thích trà đắng không?"]]},{"word":"塩辛い","reading":"しおからい","meaning":"Mặn, mặn chát","hanViet":"DIÊM TÂN","lesson":8,"ex":[["この魚は塩辛いです。","Con cá này mặn."],["この料理は塩辛いです。","Món ăn này mặn."],["塩辛い魚が好きですか。","Bạn có thích cá mặn không?"],["このみそ汁は塩辛くありません。","Súp miso này không mặn."],["塩辛い料理は好きじゃありません。","Tôi không thích món mặn."]]},{"word":"酸っぱい","reading":"すっぱい","meaning":"chua","hanViet":"","lesson":8,"ex":[["このレモンは酸っぱいです。","Quả chanh này chua."],["このりんごは酸っぱいです。","Quả táo này chua."],["酸っぱいレモンを食べました。","Tôi đã ăn chanh chua."],["このジュースは酸っぱくありません。","Nước ép này không chua."],["酸っぱい果物が好きです。","Tôi thích trái cây chua."]]},{"word":"濃い","reading":"こい","meaning":"Đậm, đặc, nồng","hanViet":"NỒNG","lesson":8,"ex":[["このコーヒーは濃いです。","Cà phê này đậm."],["このお茶は濃いです。","Trà này đậm."],["濃いコーヒーを飲みました。","Tôi đã uống cà phê đậm."],["このお茶は濃くありません。","Trà này không đậm."],["濃い味が好きです。","Tôi thích vị đậm."]]},{"word":"薄い","reading":"うすい","meaning":"Mỏng, nhạt","hanViet":"BẠC","lesson":8,"ex":[["この本は薄いです。","Cuốn sách này mỏng."],["このコーヒーは薄いです。","Cà phê này nhạt."],["薄い本が好きです。","Tôi thích sách mỏng."],["この本は薄くありません。","Cuốn sách này không mỏng."],["薄い紙に書きます。","Tôi viết lên giấy mỏng."]]},{"word":"レストラン","reading":"レストラン","meaning":"nhà hàng","hanViet":"","lesson":8,"ex":[["あのレストランでごはんを食べました。","Tôi đã ăn cơm ở nhà hàng kia."],["レストランは駅の近くです。","Nhà hàng gần ga."],["あしたレストランへ行きます。","Ngày mai tôi sẽ đi nhà hàng."],["このレストランは安いです。","Nhà hàng này rẻ."],["レストランで友達に会いました。","Tôi đã gặp bạn ở nhà hàng."]]},{"word":"ハンサム","reading":"ハンサム","meaning":"đẹp trai","hanViet":"","lesson":8,"ex":[["田中さんはハンサムです。","Anh Tanaka đẹp trai."],["山田さんはハンサムです。","Anh Yamada đẹp trai."],["ハンサムな人がいます。","Có người đẹp trai."],["あの俳優はハンサムです。","Diễn viên kia đẹp trai."],["弟はハンサムですか。","Em trai bạn có đẹp trai không?"]]},{"word":"熱い","reading":"あつい","meaning":"Nóng (vật, khi chạm)","hanViet":"NHIỆT","lesson":8,"ex":[["このお茶は熱いです。","Trà này nóng."],["このコーヒーは熱いです。","Cà phê này nóng."],["熱いお茶を飲みました。","Tôi đã uống trà nóng."],["このコーヒーは熱くありません。","Cà phê này không nóng."],["熱いお風呂に入ります。","Tôi tắm bồn nóng."]]},{"word":"とても","reading":"とても","meaning":"rất","hanViet":"","lesson":8,"ex":[["この本はとてもおもしろいです。","Cuốn sách này rất thú vị."],["この映画はとてもおもしろいです。","Bộ phim này rất thú vị."],["きょうはとても暑いです。","Hôm nay rất nóng."],["日本語はとても難しいです。","Tiếng Nhật rất khó."],["とてもおいしいケーキを食べました。","Tôi đã ăn bánh rất ngon."]]},{"word":"あまり","reading":"あまり","meaning":"không ~ lắm","hanViet":"","lesson":8,"ex":[["この本はあまりおもしろくありません。","Cuốn sách này không thú vị lắm."],["この映画はあまりおもしろくありません。","Bộ phim này không thú vị lắm."],["きょうはあまり暑くありません。","Hôm nay không nóng lắm."],["日本語はあまり難しくありません。","Tiếng Nhật không khó lắm."],["あまりお金がありません。","Tôi không có nhiều tiền lắm."]]},{"word":"そして","reading":"そして","meaning":"và","hanViet":"","lesson":8,"ex":[["わたしは学生です。そして、山田さんも学生です。","Tôi là học sinh. Và anh Yamada cũng là học sinh."],["朝ごはんを食べました。そして、学校へ行きました。","Tôi đã ăn sáng. Và tôi đã đi học."],["わたしは日本語を勉強します。そして、英語も勉強します。","Tôi học tiếng Nhật. Và tôi cũng học tiếng Anh."],["雨が降りました。そして、雪も降りました。","Trời đã mưa. Và tuyết cũng đã rơi."],["本を読みました。そして、音楽を聞きました。","Tôi đã đọc sách. Và tôi đã nghe nhạc."]]},{"word":"～が～","reading":"～が～","meaning":"～nhưng～","hanViet":"","lesson":8,"ex":[["この本は高いですが、おもしろいです。","Cuốn sách này đắt nhưng thú vị."],["この車は高いですが、便利です。","Chiếc xe này đắt nhưng tiện lợi."],["日本語は難しいですが、おもしろいです。","Tiếng Nhật khó nhưng thú vị."],["きょうは寒いですが、いい天気です。","Hôm nay lạnh nhưng thời tiết đẹp."],["このレストランは小さいですが、有名です。","Nhà hàng này nhỏ nhưng nổi tiếng."]]},{"word":"お元気ですか","reading":"おげんきですか","meaning":"có khỏe không","hanViet":"NGUYÊN KHÍ","lesson":8,"ex":[["お元気ですか。","Bạn có khỏe không?"],["お父さんはお元気ですか。","Bố bạn có khỏe không?"],["お母さんはお元気でしたか。","Mẹ bạn đã khỏe không?"],["先生、お元気ですか。","Thầy có khỏe không?"],["田中さんにお元気ですかと聞きました。","Tôi đã hỏi anh Tanaka là có khỏe không."]]},{"word":"いいえ、けっこうです","reading":"いいえ、けっこうです","meaning":"thôi, đủ rồi","hanViet":"","lesson":8,"ex":[["いいえ、けっこうです。","Thôi, đủ rồi."],["コーヒーはどうですか。いいえ、けっこうです。","Cà phê nhé? Thôi, đủ rồi."],["お茶はいかがですか。いいえ、けっこうです。","Trà nhé? Thôi, đủ rồi."],["ケーキはどうですか。いいえ、けっこうです。","Bánh nhé? Thôi, đủ rồi."],["田中さんはいいえ、けっこうですと言いました。","Anh Tanaka đã nói \"Thôi, đủ rồi\"."]]},{"word":"そうですね","reading":"そうですね","meaning":"thế à./Để tôi xem","hanViet":"","lesson":8,"ex":[["そうですね、考えます。","Để tôi xem, tôi sẽ suy nghĩ."],["そうですね、あした行きます。","Để tôi xem, ngày mai tôi sẽ đi."],["そうですね、考えてあした電話します。","Để tôi xem, tôi sẽ suy nghĩ rồi ngày mai gọi điện."],["そうですね、これはいい本です。","Để tôi xem, đây là sách hay."],["そうですね、ちょっと待ってください。","Để tôi xem, hãy đợi một chút."]]},{"word":"どれ","reading":"どれ","meaning":"cái nào (trong ba cái trở lên)","hanViet":"","lesson":9,"ex":[["どれがあなたの本ですか？","Quyển nào là sách của bạn?"],["どれが好きですか。","Bạn thích cái nào?"],["どれを買いますか。","Bạn sẽ mua cái nào?"],["どれがあなたの車ですか。","Chiếc nào là xe của bạn?"],["どれが一番好きですか。","Bạn thích cái nào nhất?"]]},{"word":"わかります","reading":"わかります","meaning":"hiểu, nắm được","hanViet":"","lesson":9,"ex":[["日本語がわかります。","Tôi hiểu tiếng Nhật."],["先生の話がよくわかります。","Tôi hiểu rõ lời thầy nói."],["先生の話がわかりますか。","Bạn có hiểu lời thầy nói không?"],["漢字がよくわかりません。","Tôi không hiểu rõ chữ Hán."],["この問題はわかりませんでした。","Bài tập này tôi đã không hiểu."]]},{"word":"好き","reading":"すき","meaning":"Thích","hanViet":"HẢO","lesson":9,"ex":[["わたしは音楽が好きです。","Tôi thích âm nhạc."],["わたしは本が好きです。","Tôi thích sách."],["父はスポーツが好きです。","Bố tôi thích thể thao."],["好きな食べ物は何ですか。","Đồ ăn yêu thích của bạn là gì?"],["犬が好きですか。","Bạn có thích chó không?"]]},{"word":"嫌い","reading":"きらい","meaning":"ghét, không thích","hanViet":"HIỀM","lesson":9,"ex":[["わたしはたばこが嫌いです。","Tôi ghét thuốc lá."],["わたしは魚が嫌いです。","Tôi ghét cá."],["母は野菜が嫌いです。","Mẹ tôi ghét rau."],["嫌いな食べ物はありません。","Tôi không có đồ ăn nào ghét."],["雨が嫌いですか。","Bạn có ghét mưa không?"]]},{"word":"上手","reading":"じょうず","meaning":"Giỏi, khéo","hanViet":"THƯỢNG THỦ","lesson":9,"ex":[["山田さんは歌が上手です。","Anh Yamada hát giỏi."],["田中さんは日本語が上手です。","Anh Tanaka giỏi tiếng Nhật."],["姉はピアノが上手です。","Chị tôi chơi piano giỏi."],["上手な歌を聞きました。","Tôi đã nghe bài hát hay."],["日本語が上手になりたいです。","Tôi muốn trở nên giỏi tiếng Nhật."]]},{"word":"下手","reading":"へた","meaning":"Kém, vụng về","hanViet":"HẠ THỦ","lesson":9,"ex":[["わたしは絵が下手です。","Tôi vẽ tranh kém."],["わたしは歌が下手です。","Tôi hát kém."],["弟はスポーツが下手です。","Em trai tôi chơi thể thao kém."],["日本語が下手ですけど、頑張ります。","Tiếng Nhật của tôi kém nhưng tôi sẽ cố gắng."],["下手な字を書きました。","Tôi đã viết chữ xấu."]]},{"word":"料理","reading":"りょうり","meaning":"Nấu ăn; món ăn","hanViet":"LIỆU LÝ","lesson":9,"ex":[["わたしの母は料理が上手です。","Mẹ tôi nấu ăn giỏi."],["料理を作ります。","Tôi nấu ăn."],["日本の料理が好きです。","Tôi thích món Nhật."],["料理の本を読みました。","Tôi đã đọc sách nấu ăn."],["料理は楽しいです。","Nấu ăn vui vẻ."]]},{"word":"飲み物","reading":"のみもの","meaning":"Đồ uống","hanViet":"ẨM VẬT","lesson":9,"ex":[["何か飲み物をください。","Cho tôi đồ uống gì đó."],["何か飲み物を買いました。","Tôi đã mua đồ uống gì đó."],["飲み物は何がいいですか。","Đồ uống nào ngon?"],["冷たい飲み物が欲しいです。","Tôi muốn đồ uống lạnh."],["飲み物はジュースです。","Đồ uống là nước ép."]]},{"word":"野球","reading":"やきゅう","meaning":"Bóng chày","hanViet":"DÃ CẦU","lesson":9,"ex":[["弟は野球が好きです。","Em trai tôi thích bóng chày."],["野球を見ます。","Tôi xem bóng chày."],["野球が好きですか。","Bạn có thích bóng chày không?"],["日曜日に野球をします。","Chủ nhật tôi chơi bóng chày."],["兄は野球が上手です。","Anh trai tôi chơi bóng chày giỏi."]]},{"word":"音楽","reading":"おんがく","meaning":"Âm nhạc","hanViet":"ÂM NHẠC","lesson":9,"ex":[["毎日音楽を聞きます。","Tôi nghe nhạc mỗi ngày."],["音楽が好きです。","Tôi thích âm nhạc."],["音楽を聞きながら、勉強します。","Tôi học bài trong khi nghe nhạc."],["日本の音楽は有名です。","Âm nhạc Nhật nổi tiếng."],["音楽のコンサートへ行きます。","Tôi đi buổi hòa nhạc."]]},{"word":"歌","reading":"うた","meaning":"Bài hát","hanViet":"CA","lesson":9,"ex":[["この歌が好きです。","Tôi thích bài hát này."],["母は古い歌が好きです。","Mẹ tôi thích những bài hát xưa."],["日本の歌が好きです。","Tôi thích bài hát Nhật."],["この歌はおもしろいです。","Bài hát này thú vị."],["歌を聞きながら、電車に乗ります。","Tôi đi tàu trong khi nghe bài hát."]]},{"word":"絵","reading":"え","meaning":"Tranh, bức tranh","hanViet":"HỘI","lesson":9,"ex":[["姉は絵が上手です。","Chị tôi vẽ tranh giỏi."],["絵を見ます。","Tôi xem tranh."],["絵の本が好きです。","Tôi thích sách tranh."],["この絵はきれいです。","Bức tranh này đẹp."],["絵が好きですか。","Bạn có thích tranh không?"]]},{"word":"字","reading":"じ","meaning":"Chữ, ký tự","hanViet":"TỰ","lesson":9,"ex":[["先生の字はきれいです。","Chữ của thầy giáo rất đẹp."],["字を書きます。","Tôi viết chữ."],["この字は小さいです。","Chữ này nhỏ."],["字が上手です。","Chữ viết đẹp."],["大きい字で書いてください。","Hãy viết bằng chữ to."]]},{"word":"漢字","reading":"かんじ","meaning":"Chữ Hán","hanViet":"HÁN TỰ","lesson":9,"ex":[["漢字は難しいです。","Chữ Hán rất khó."],["漢字を勉強します。","Tôi học chữ Hán."],["漢字が好きです。","Tôi thích chữ Hán."],["漢字を覚えます。","Tôi nhớ chữ Hán."],["漢字の本を買いました。","Tôi đã mua sách chữ Hán."]]},{"word":"細かいお金","reading":"こまかいおかね","meaning":"tiền lẻ","hanViet":"KIM","lesson":9,"ex":[["すみません、細かいお金がありません。","Xin lỗi, tôi không có tiền lẻ."],["細かいお金がありますか。","Bạn có tiền lẻ không?"],["細かいお金をください。","Cho tôi tiền lẻ."],["細かいお金がいります。","Tôi cần tiền lẻ."],["細かいお金がありませんでした。","Tôi đã không có tiền lẻ."]]},{"word":"時間","reading":"じかん","meaning":"Thời gian","hanViet":"THỜI GIAN","lesson":9,"ex":[["今、時間がありますか？","Bây giờ bạn có thời gian không?"],["時間がありません。","Tôi không có thời gian."],["勉強する時間があります。","Tôi có thời gian học bài."],["時間はどのくらいですか。","Mất bao lâu?"],["時間がかかります。","Mất thời gian."]]},{"word":"用事","reading":"ようじ","meaning":"Việc cần làm","hanViet":"DỤNG SỰ","lesson":9,"ex":[["きょうは用事があります。","Hôm nay tôi có việc cần làm."],["あした、用事があるから、うちにいます。","Ngày mai tôi có việc nên ở nhà."],["日曜日は用事がありません。","Chủ nhật tôi không có việc gì."],["用事があるとき、電話します。","Khi có việc, tôi gọi điện thoại."],["母はあした用事があります。","Mẹ tôi ngày mai có việc."]]},{"word":"約束","reading":"やくそく","meaning":"Lời hứa, hẹn ước","hanViet":"ƯỚC THÚC","lesson":9,"ex":[["あした、友達と約束があります。","Ngày mai tôi có hẹn với bạn."],["来週、山田さんと約束があります。","Tuần sau tôi có hẹn với anh Yamada."],["約束の時間は三時です。","Giờ hẹn là ba giờ."],["約束を忘れました。","Tôi đã quên mất lời hẹn."],["きのう、友達と約束をしました。","Hôm qua tôi đã hẹn với bạn."]]},{"word":"ご主人","reading":"ごしゅじん","meaning":"chồng (dùng khi nói về chồng người khác)","hanViet":"NHÂN","lesson":9,"ex":[["田中さんのご主人は先生です。","Chồng của chị Tanaka là giáo viên."],["山田さんのご主人は会社員です。","Chồng của chị Yamada là nhân viên công ty."],["ご主人はお元気ですか。","Chồng chị có khỏe không?"],["あの人のご主人は医者です。","Chồng của người kia là bác sĩ."],["ご主人は日本語が上手です。","Chồng chị giỏi tiếng Nhật."]]},{"word":"夫","reading":"おっと","meaning":"chồng","hanViet":"PHU","lesson":9,"ex":[["わたしの夫は会社員です。","Chồng tôi là nhân viên công ty."],["夫は毎日会社へ行きます。","Chồng tôi hằng ngày đi làm ở công ty."],["夫はスポーツが好きです。","Chồng tôi thích thể thao."],["夫と映画を見ました。","Tôi đã xem phim với chồng."],["夫は日本語を勉強します。","Chồng tôi học tiếng Nhật."]]},{"word":"主人","reading":"しゅじん","meaning":"Chồng, ông chủ","hanViet":"CHỦ NHÂN","lesson":9,"ex":[["主人は会社で働きます。","Chồng tôi làm việc ở công ty."],["主人は今、うちにいません。","Chồng tôi bây giờ không ở nhà."],["主人はテニスが上手です。","Chồng tôi chơi tennis giỏi."],["主人と買い物をしました。","Tôi đã đi mua sắm với chồng."],["主人は毎朝六時に起きます。","Chồng tôi mỗi sáng dậy lúc sáu giờ."]]},{"word":"奥さん","reading":"おくさん","meaning":"vợ (dùng khi nói về vợ người khác)","hanViet":"ÁO","lesson":9,"ex":[["山田さんの奥さんは医者です。","Vợ của anh Yamada là bác sĩ."],["田中さんの奥さんは先生です。","Vợ của anh Tanaka là giáo viên."],["奥さんはお元気ですか。","Vợ anh có khỏe không?"],["あの人の奥さんは日本語が上手です。","Vợ của người kia giỏi tiếng Nhật."],["山田さんの奥さんは会社員です。","Vợ của anh Yamada là nhân viên công ty."]]},{"word":"妻","reading":"つま","meaning":"Vợ (của mình)","hanViet":"THÊ","lesson":9,"ex":[["わたしの妻は看護婦です。","Vợ tôi là y tá."],["妻は毎日料理をします。","Vợ tôi hằng ngày nấu ăn."],["妻と子どもが公園へ行きます。","Vợ và con tôi đi công viên."],["妻はピアノが上手です。","Vợ tôi chơi piano giỏi."],["妻は今、うちで休みます。","Vợ tôi bây giờ đang nghỉ ở nhà."]]},{"word":"家内","reading":"かない","meaning":"Vợ (cách gọi khiêm tốn)","hanViet":"GIA NỘI","lesson":9,"ex":[["家内は今、うちにいます。","Vợ tôi bây giờ đang ở nhà."],["家内は日本語を勉強します。","Vợ tôi học tiếng Nhật."],["家内と映画を見ました。","Tôi đã xem phim với vợ."],["家内は料理が上手です。","Vợ tôi nấu ăn giỏi."],["家内は毎日会社へ行きます。","Vợ tôi hằng ngày đi làm ở công ty."]]},{"word":"子ども","reading":"こども","meaning":"con cái","hanViet":"TỬ","lesson":9,"ex":[["わたしたちは子どもが二人います。","Chúng tôi có hai con."],["子どもは学校へ行きます。","Con tôi đi học ở trường."],["子どもは外で遊びます。","Con tôi chơi ở ngoài."],["子どもが三人います。","Tôi có ba đứa con."],["子どもはテレビが好きです。","Con tôi thích ti vi."]]},{"word":"よく","reading":"よく","meaning":"tốt, rõ (chỉ mức độ)","hanViet":"","lesson":9,"ex":[["日本語がよくわかります。","Tôi hiểu rõ tiếng Nhật."],["わたしはよくこの店へ行きます。","Tôi thường đến cửa hàng này."],["彼はよくスポーツをします。","Anh ấy thường chơi thể thao."],["この本をよく読みます。","Tôi thường đọc quyển sách này."],["日本語をよく勉強します。","Tôi học tiếng Nhật chăm chỉ."]]},{"word":"だいたい","reading":"だいたい","meaning":"đại khái, đại thể","hanViet":"","lesson":9,"ex":[["日本語がだいたいわかります。","Tôi hiểu đại khái tiếng Nhật."],["だいたい三時に来ます。","Tôi đến vào khoảng ba giờ."],["だいたいわかりました。","Tôi đã hiểu đại khái rồi."],["この本はだいたい読みました。","Quyển sách này tôi đã đọc gần hết rồi."],["だいたい毎日、日本語を勉強します。","Hầu như ngày nào tôi cũng học tiếng Nhật."]]},{"word":"たくさん","reading":"たくさん","meaning":"nhiều","hanViet":"","lesson":9,"ex":[["本をたくさん読みます。","Tôi đọc nhiều sách."],["きのう、たくさん食べました。","Hôm qua tôi đã ăn nhiều."],["うちに本がたくさんあります。","Ở nhà tôi có nhiều sách."],["たくさんのお金が要ります。","Cần nhiều tiền."],["友達がたくさんいます。","Tôi có nhiều bạn."]]},{"word":"少し","reading":"すこし","meaning":"Một chút","hanViet":"THIẾU","lesson":9,"ex":[["少し休みます。","Tôi nghỉ một chút."],["日本語が少しわかります。","Tôi hiểu tiếng Nhật một chút."],["少し水を飲みます。","Tôi uống một chút nước."],["少し待ってください。","Hãy đợi một chút."],["きょうは少し寒いです。","Hôm nay hơi lạnh."]]},{"word":"全然","reading":"ぜんぜん","meaning":"Hoàn toàn (không/tuyệt đối)","hanViet":"TOÀN NHIÊN","lesson":9,"ex":[["漢字が全然わかりません。","Tôi hoàn toàn không hiểu chữ Hán."],["全然難しくありません。","Không khó chút nào."],["きのうは全然食べませんでした。","Hôm qua tôi hoàn toàn không ăn gì."],["日本語が全然できません。","Tôi hoàn toàn không biết tiếng Nhật."],["全然疲れませんでした。","Tôi không mệt chút nào."]]},{"word":"早く","reading":"はやく","meaning":"sớm, nhanh","hanViet":"TẢO, TỐC","lesson":9,"ex":[["早く来てください。","Hãy đến sớm nhé."],["毎日早く起きます。","Hằng ngày tôi dậy sớm."],["あした、早く行きます。","Ngày mai tôi sẽ đi sớm."],["早く食べてください。","Hãy ăn nhanh lên."],["きのう、早く帰りました。","Hôm qua tôi đã về sớm."]]},{"word":"どうして","reading":"どうして","meaning":"tại sao","hanViet":"","lesson":9,"ex":[["どうして日本語を勉強しますか？","Tại sao bạn học tiếng Nhật?"],["どうして来ませんでしたか。","Tại sao bạn đã không đến?"],["どうしてこの本を買いましたか。","Tại sao bạn đã mua quyển sách này?"],["どうして学校へ行きませんか。","Tại sao bạn không đi học?"],["どうしてあしたはだめですか。","Tại sao ngày mai không được?"]]},{"word":"残念です","reading":"ざんねんです","meaning":"Thật đáng tiếc nhỉ/ buồn nhỉ","hanViet":"TÀN NIỆM","lesson":9,"ex":[["あしたは雨です。残念です。","Ngày mai trời mưa. Thật đáng tiếc."],["残念です、あしたは用事があります。","Tiếc quá, ngày mai tôi có việc."],["残念ですが、きょうは雨です。","Tiếc quá, hôm nay trời mưa."],["きのうはコンサートへ行きませんでした。残念です。","Hôm qua tôi đã không đi xem hòa nhạc. Thật đáng tiếc."],["残念です、チケットがありません。","Tiếc quá, không còn vé."]]},{"word":"民謡","reading":"みんよう","meaning":"dân ca","hanViet":"DÂN DAO","lesson":9,"ex":[["母は民謡が好きです。","Mẹ tôi thích dân ca."],["わたしは民謡を聞きます。","Tôi nghe dân ca."],["おじいさんは民謡を歌います。","Ông tôi hát dân ca."],["民謡はおもしろいです。","Dân ca rất hay."],["日本の民謡を勉強します。","Tôi học dân ca Nhật Bản."]]},{"word":"演歌","reading":"えんか","meaning":"enka (một thể loại ba₫lát của Nhật)","hanViet":"","lesson":9,"ex":[["おじいさんは演歌が好きです。","Ông tôi thích nhạc enka."],["父は演歌を聞きます。","Bố tôi nghe nhạc enka."],["母は演歌を歌います。","Mẹ tôi hát nhạc enka."],["演歌はいいです。","Nhạc enka hay."],["演歌のコンサートへ行きます。","Tôi đi xem hòa nhạc enka."]]},{"word":"喜劇","reading":"きげき","meaning":"Hài kịch","hanViet":"HỶ KỊCH","lesson":9,"ex":[["きのう、喜劇を見ました。","Hôm qua tôi đã xem hài kịch."],["喜劇はおもしろいです。","Hài kịch rất hay."],["テレビで喜劇を見ます。","Tôi xem hài kịch trên ti vi."],["喜劇が好きです。","Tôi thích hài kịch."],["友達と喜劇を見ました。","Tôi đã xem hài kịch với bạn."]]},{"word":"卓球","reading":"たっきゅう","meaning":"bóng bàn","hanViet":"TRÁC CẦU","lesson":9,"ex":[["弟は卓球が上手です。","Em trai tôi chơi bóng bàn giỏi."],["わたしは卓球が好きです。","Tôi thích bóng bàn."],["学校で卓球をします。","Tôi chơi bóng bàn ở trường."],["卓球は楽しいです。","Bóng bàn rất vui."],["日曜日、友達と卓球をします。","Chủ nhật tôi chơi bóng bàn với bạn."]]},{"word":"相撲","reading":"すもう","meaning":"vật sumo","hanViet":"TƯƠNG PHÁC","lesson":9,"ex":[["父は相撲が好きです。","Bố tôi thích vật sumo."],["テレビで相撲を見ます。","Tôi xem vật sumo trên ti vi."],["相撲はおもしろいです。","Vật sumo rất hay."],["兄は相撲が好きです。","Anh trai tôi thích vật sumo."],["友達と相撲を見ました。","Tôi đã xem vật sumo với bạn."]]},{"word":"柔道","reading":"じゅうどう","meaning":"Môn Judo","hanViet":"NHU ĐẠO","lesson":9,"ex":[["山田さんは柔道をします。","Anh Yamada tập judo."],["わたしは柔道が好きです。","Tôi thích judo."],["弟は柔道を習います。","Em trai tôi học judo."],["柔道は難しいです。","Judo khó."],["学校で柔道をします。","Tôi tập judo ở trường."]]},{"word":"剣道","reading":"けんどう","meaning":"kiếm đạo (kendo)","hanViet":"KIẾM ĐẠO","lesson":9,"ex":[["兄は剣道をします。","Anh trai tôi tập kendo."],["剣道が好きです。","Tôi thích kendo."],["剣道を習います。","Tôi học kendo."],["剣道はおもしろいです。","Kendo rất hay."],["友達は剣道が上手です。","Bạn tôi tập kendo giỏi."]]},{"word":"水泳","reading":"すいえい","meaning":"Bơi lội","hanViet":"THỦY VỊNH","lesson":9,"ex":[["夏、水泳をします。","Mùa hè tôi đi bơi."],["水泳が好きです。","Tôi thích bơi lội."],["プールで水泳をします。","Tôi bơi ở bể bơi."],["水泳は楽しいです。","Bơi lội rất vui."],["子どもは水泳を習います。","Con tôi học bơi."]]},{"word":"あります","reading":"あります","meaning":"có (sở hữu)","hanViet":"","lesson":9,"ex":[["わたしは車があります。","Tôi có xe ô tô."],["わたしは時間があります。","Tôi có thời gian."],["お金がありますか。","Bạn có tiền không?"],["きょう、時間がありますから、映画を見ます。","Hôm nay tôi có thời gian nên đi xem phim."],["兄は車が二台あります。","Anh trai tôi có hai chiếc xe."]]},{"word":"スポーツ","reading":"スポーツ","meaning":"thể thao (～をします：chơi thể thao)","hanViet":"","lesson":9,"ex":[["わたしはスポーツが好きです。","Tôi thích thể thao."],["わたしはスポーツをします。","Tôi chơi thể thao."],["スポーツは楽しいです。","Thể thao rất vui."],["日曜日、スポーツをします。","Chủ nhật tôi chơi thể thao."],["子どもはスポーツが好きです。","Con tôi thích thể thao."]]},{"word":"ダンス","reading":"ダンス","meaning":"nhảy, khiêu vũ (～をします：nhảy, khiêu vũ)","hanViet":"","lesson":9,"ex":[["友達とダンスをします。","Tôi nhảy với bạn bè."],["ダンスが好きです。","Tôi thích nhảy."],["ダンスを習います。","Tôi học nhảy."],["ダンスは楽しいです。","Nhảy múa rất vui."],["パーティーでダンスをします。","Tôi nhảy ở bữa tiệc."]]},{"word":"クラシック","reading":"クラシック","meaning":"nhạc cổ điển","hanViet":"","lesson":9,"ex":[["母はクラシックが好きです。","Mẹ tôi thích nhạc cổ điển."],["クラシックを聞きます。","Tôi nghe nhạc cổ điển."],["クラシックはいいです。","Nhạc cổ điển hay."],["父はクラシックが好きです。","Bố tôi thích nhạc cổ điển."],["クラシックのコンサートへ行きます。","Tôi đi xem hòa nhạc cổ điển."]]},{"word":"ジャズ","reading":"ジャズ","meaning":"nhạc jazz","hanViet":"","lesson":9,"ex":[["父はジャズを聞きます。","Bố tôi nghe nhạc jazz."],["ジャズが好きです。","Tôi thích nhạc jazz."],["ジャズはいいです。","Nhạc jazz hay."],["ジャズのコンサートへ行きます。","Tôi đi xem hòa nhạc jazz."],["母はジャズを聞きます。","Mẹ tôi nghe nhạc jazz."]]},{"word":"コンサート","reading":"コンサート","meaning":"buổi hòa nhạc","hanViet":"","lesson":9,"ex":[["あした、コンサートへ行きます。","Ngày mai tôi đi xem hòa nhạc."],["コンサートは楽しいです。","Buổi hòa nhạc rất vui."],["コンサートのチケットを買います。","Tôi mua vé hòa nhạc."],["きのう、コンサートを見ました。","Hôm qua tôi đã xem hòa nhạc."],["友達とコンサートへ行きます。","Tôi đi xem hòa nhạc với bạn."]]},{"word":"カラオケ","reading":"カラオケ","meaning":"karaoke","hanViet":"","lesson":9,"ex":[["友達とカラオケへ行きます。","Tôi đi hát karaoke với bạn bè."],["カラオケが好きです。","Tôi thích karaoke."],["カラオケで歌を歌います。","Tôi hát ở karaoke."],["カラオケは楽しいです。","Karaoke rất vui."],["日曜日、カラオケへ行きます。","Chủ nhật tôi đi hát karaoke."]]},{"word":"歌舞伎","reading":"かぶき","meaning":"kịch Kabuki truyền thống","hanViet":"CA VŨ KĨ","lesson":9,"ex":[["きのう、歌舞伎を見ました。","Hôm qua tôi đã xem kịch Kabuki."],["歌舞伎が好きです。","Tôi thích kịch Kabuki."],["歌舞伎はおもしろいです。","Kịch Kabuki rất hay."],["友達と歌舞伎を見ました。","Tôi đã xem kịch Kabuki với bạn."],["歌舞伎のチケットを買いました。","Tôi đã mua vé xem kịch Kabuki."]]},{"word":"ひらがな","reading":"ひらがな","meaning":"chữ Hiragana","hanViet":"","lesson":9,"ex":[["ひらがなは易しいです。","Chữ Hiragana rất dễ."],["ひらがなを書きます。","Tôi viết chữ Hiragana."],["ひらがなを読みます。","Tôi đọc chữ Hiragana."],["ひらがなで名前を書きます。","Tôi viết tên bằng chữ Hiragana."],["ひらがなを勉強します。","Tôi học chữ Hiragana."]]},{"word":"かたかな","reading":"かたかな","meaning":"Chữ Katakana","hanViet":"","lesson":9,"ex":[["かたかなを勉強します。","Tôi học chữ Katakana."],["かたかなは難しいです。","Chữ Katakana khó."],["かたかなを書きます。","Tôi viết chữ Katakana."],["かたかなで名前を書きます。","Tôi viết tên bằng chữ Katakana."],["かたかなを読みます。","Tôi đọc chữ Katakana."]]},{"word":"ローマ字","reading":"ローマじ","meaning":"chữ La Mã","hanViet":"TỰ","lesson":9,"ex":[["ローマ字で名前を書きます。","Tôi viết tên bằng chữ La Mã."],["ローマ字を読みます。","Tôi đọc chữ La Mã."],["ローマ字は易しいです。","Chữ La Mã dễ."],["ローマ字で手紙を書きます。","Tôi viết thư bằng chữ La Mã."],["ローマ字を勉強します。","Tôi học chữ La Mã."]]},{"word":"チケット","reading":"チケット","meaning":"vé (xem hòa nhạc, xem phim)","hanViet":"","lesson":9,"ex":[["コンサートのチケットを買いました。","Tôi đã mua vé hòa nhạc."],["チケットが二枚あります。","Tôi có hai vé."],["映画のチケットを買います。","Tôi mua vé xem phim."],["チケットはいくらですか。","Vé giá bao nhiêu?"],["チケットをください。","Cho tôi vé."]]},{"word":"アルバイト","reading":"アルバイト","meaning":"việc làm thêm (をします: làm thêm)","hanViet":"","lesson":9,"ex":[["わたしはレストランでアルバイトをします。","Tôi làm thêm ở nhà hàng."],["毎日アルバイトをします。","Hằng ngày tôi làm thêm."],["アルバイトは大変です。","Việc làm thêm vất vả."],["コンビニでアルバイトをします。","Tôi làm thêm ở cửa hàng tiện lợi."],["アルバイトのお金で本を買います。","Tôi mua sách bằng tiền làm thêm."]]},{"word":"ああ","reading":"ああ","meaning":"a (cách nói khi đã gặp được đúng người trên điện thoại)","hanViet":"","lesson":9,"ex":[["もしもし、ああ、田中さんですか。お元気ですか。","A lô, à, có phải anh Tanaka không? Anh có khỏe không?"],["ああ、山田さんですか。","À, có phải anh Yamada không?"],["ああ、そうですか。","À, thế à."],["もしもし、ああ、先生ですか。","A lô, à, có phải thầy không?"],["ああ、わかりました。","À, tôi hiểu rồi."]]},{"word":"いっしょにいかがですか","reading":"いっしょにいかがですか","meaning":"Anh/chị cùng ~ (làm cái gì đó) với chúng tôi được không?","hanViet":"","lesson":9,"ex":[["あした、映画へいっしょにいかがですか？","Ngày mai cùng đi xem phim với chúng tôi nhé?"],["コンサートへいっしょにいかがですか。","Cùng đi xem hòa nhạc nhé?"],["昼ごはんをいっしょにいかがですか。","Cùng ăn trưa nhé?"],["日曜日、公園へいっしょにいかがですか。","Chủ nhật cùng đi công viên nhé?"],["きょう、買い物をいっしょにいかがですか。","Hôm nay cùng đi mua sắm nhé?"]]},{"word":"～はちょっと…","reading":"～はちょっと…","meaning":"[~ thì] có lẽ không được rồi","hanViet":"","lesson":9,"ex":[["日曜日はちょっと…","Chủ nhật thì có lẽ không được rồi…"],["あしたはちょっと…用事があります。","Ngày mai thì có lẽ không được rồi… tôi có việc."],["夜はちょっと…","Buổi tối thì có lẽ không được rồi…"],["月曜日はちょっと…","Thứ hai thì có lẽ không được rồi…"],["今週はちょっと…","Tuần này thì có lẽ không được rồi…"]]},{"word":"だめですか","reading":"だめですか","meaning":"Không được à?","hanViet":"","lesson":9,"ex":[["あしたはだめですか？","Ngày mai không được à?"],["日曜日はだめですか？","Chủ nhật không được à?"],["夜はだめですか？","Buổi tối không được à?"],["三時はだめですか？","Ba giờ không được à?"],["きょうはだめですか？","Hôm nay không được à?"]]},{"word":"また今度お願いします","reading":"またこんどおねがいします","meaning":"hẹn lần sau","hanViet":"KIM ĐỘ NGUYỆT","lesson":9,"ex":[["あしたは用事があります。また今度お願いします。","Ngày mai tôi có việc. Hẹn lần sau nhé."],["きょうは忙しいです。また今度お願いします。","Hôm nay tôi bận. Hẹn lần sau nhé."],["日曜日はちょっと…また今度お願いします。","Chủ nhật thì có lẽ không được… Hẹn lần sau nhé."],["あしたはだめです。また今度お願いします。","Ngày mai không được. Hẹn lần sau nhé."],["今週は用事があります。また今度お願いします。","Tuần này tôi có việc. Hẹn lần sau nhé."]]},{"word":"いいですよ","reading":"いいですよ","meaning":"Được, không sao đâu","hanViet":"","lesson":9,"ex":[["いいですよ。あした行きます。","Được, không sao đâu. Ngày mai tôi đi."],["いいですよ。日曜日行きます。","Được, không sao đâu. Chủ nhật tôi đi."],["いいですよ。いっしょに行きます。","Được, không sao đâu. Tôi đi cùng."],["いいですよ。あした来てください。","Được, không sao đâu. Ngày mai hãy đến nhé."],["いいですよ。コンサートへ行きます。","Được, không sao đâu. Tôi đi xem hòa nhạc."]]},{"word":"いろいろ","reading":"いろいろ","meaning":"nhiều, đa dạng","hanViet":"","lesson":10,"ex":[["私のうちにいろいろな本があります。","Nhà tôi có nhiều loại sách."],["いろいろな本を読みます。","Tôi đọc nhiều loại sách."],["いろいろな国へ行きました。","Tôi đã đi nhiều nước."],["この店にいろいろな物があります。","Ở cửa hàng này có nhiều thứ."],["いろいろな食べ物を食べます。","Tôi ăn nhiều món ăn."]]},{"word":"男の人","reading":"おとこのひと","meaning":"người đàn ông","hanViet":"NAM NHÂN","lesson":10,"ex":[["その男の人は先生です。","Người đàn ông đó là giáo viên."],["あの男の人は会社員です。","Người đàn ông kia là nhân viên công ty."],["男の人は本を読みます。","Người đàn ông đọc sách."],["この男の人はだれですか。","Người đàn ông này là ai?"],["男の人は日本語が上手です。","Người đàn ông giỏi tiếng Nhật."]]},{"word":"女の人","reading":"おんなのひと","meaning":"người đàn bà","hanViet":"NỮ NHÂN","lesson":10,"ex":[["あの女の人は母です。","Người phụ nữ kia là mẹ tôi."],["その女の人は先生です。","Người phụ nữ đó là giáo viên."],["この女の人はだれですか。","Người phụ nữ này là ai?"],["女の人は会社で働きます。","Người phụ nữ làm việc ở công ty."],["あの女の人は歌が上手です。","Người phụ nữ kia hát hay."]]},{"word":"男の子","reading":"おとこのこ","meaning":"cậu con trai","hanViet":"NAM TỬ","lesson":10,"ex":[["男の子は公園で遊びます。","Cậu con trai chơi ở công viên."],["男の子は学校へ行きます。","Cậu con trai đi học."],["男の子は本を読みます。","Cậu con trai đọc sách."],["あの男の子は弟です。","Cậu con trai kia là em trai tôi."],["男の子はサッカーが好きです。","Cậu con trai thích bóng đá."]]},{"word":"女の子","reading":"おんなのこ","meaning":"cô con gái","hanViet":"NỮ TỬ","lesson":10,"ex":[["女の子はピアノを弾きます。","Cô con gái chơi đàn piano."],["女の子は歌を歌います。","Cô con gái hát."],["女の子は学校へ行きます。","Cô con gái đi học."],["あの女の子は妹です。","Cô con gái kia là em gái tôi."],["女の子は本が好きです。","Cô con gái thích sách."]]},{"word":"犬","reading":"いぬ","meaning":"Con chó","hanViet":"KHUYỂN","lesson":10,"ex":[["犬が庭にいます。","Con chó ở trong sân."],["うちに白い犬がいます。","Nhà tôi có một con chó trắng."],["犬は大きいです。","Con chó to."],["犬が好きです。","Tôi thích chó."],["犬と散歩します。","Tôi đi dạo với chó."]]},{"word":"猫","reading":"ねこ","meaning":"Con mèo","hanViet":"MIÊU","lesson":10,"ex":[["猫がベッドの上にいます。","Con mèo ở trên giường."],["猫が二匹います。","Có hai con mèo."],["猫は小さいです。","Con mèo nhỏ."],["猫が好きです。","Tôi thích mèo."],["猫は外にいます。","Con mèo ở bên ngoài."]]},{"word":"木","reading":"き","meaning":"Cây","hanViet":"MỘC","lesson":10,"ex":[["庭に木があります。","Trong sân có cây."],["公園に木がたくさんあります。","Trong công viên có nhiều cây."],["木は大きいです。","Cây to."],["学校の前に木があります。","Trước trường học có cây."],["木の下に犬がいます。","Dưới gốc cây có con chó."]]},{"word":"物","reading":"もの","meaning":"Đồ vật, thứ","hanViet":"VẬT","lesson":10,"ex":[["この箱にいろいろな物があります。","Trong hộp này có nhiều thứ."],["机の上に物があります。","Trên bàn có đồ vật."],["この物は何ですか。","Thứ này là cái gì?"],["かばんにいろいろな物があります。","Trong cặp có nhiều thứ."],["この物は高いです。","Thứ này đắt."]]},{"word":"電池","reading":"でんち","meaning":"Pin","hanViet":"ĐIỆN TRÌ","lesson":10,"ex":[["この時計は電池が要ります。","Chiếc đồng hồ này cần pin."],["電池を買います。","Tôi mua pin."],["電池が二つあります。","Có hai cục pin."],["ラジオは電池が要ります。","Cái đài cần pin."],["電池はいくらですか。","Pin giá bao nhiêu?"]]},{"word":"箱","reading":"はこ","meaning":"Cái hộp, thùng","hanViet":"TƯƠNG","lesson":10,"ex":[["箱に本を入れます。","Tôi cho sách vào hộp."],["箱に物があります。","Trong hộp có đồ vật."],["箱は大きいです。","Cái hộp to."],["箱を買います。","Tôi mua hộp."],["箱に本がたくさんあります。","Trong hộp có nhiều sách."]]},{"word":"冷蔵庫","reading":"れいぞうこ","meaning":"Tủ lạnh","hanViet":"LÃNH TÀNG KHỐ","lesson":10,"ex":[["牛乳は冷蔵庫にあります。","Sữa ở trong tủ lạnh."],["冷蔵庫にジュースがあります。","Trong tủ lạnh có nước trái cây."],["冷蔵庫は大きいです。","Tủ lạnh to."],["冷蔵庫に卵があります。","Trong tủ lạnh có trứng."],["冷蔵庫を開けます。","Tôi mở tủ lạnh."]]},{"word":"棚","reading":"たな","meaning":"Kệ, giá để đồ","hanViet":"BẰNG","lesson":10,"ex":[["本は棚にあります。","Sách ở trên kệ."],["棚に本がたくさんあります。","Trên kệ có nhiều sách."],["棚は大きいです。","Cái kệ to."],["棚に花があります。","Trên kệ có hoa."],["棚に辞書があります。","Trên kệ có từ điển."]]},{"word":"窓","reading":"まど","meaning":"Cửa sổ","hanViet":"SONG","lesson":10,"ex":[["窓が大きいです。","Cửa sổ to."],["教室の窓は大きいです。","Cửa sổ của lớp học thì lớn."],["窓を閉めます。","Tôi đóng cửa sổ."],["窓の前に机があります。","Trước cửa sổ có bàn."],["窓は小さいです。","Cửa sổ nhỏ."]]},{"word":"公園","reading":"こうえん","meaning":"Công viên","hanViet":"CÔNG VIÊN","lesson":10,"ex":[["公園で子どもが遊びます。","Trẻ con chơi ở công viên."],["日曜日、公園へ行きます。","Chủ nhật tôi đi công viên."],["公園は広いです。","Công viên rộng."],["公園に花がたくさんあります。","Trong công viên có nhiều hoa."],["公園で散歩します。","Tôi đi dạo trong công viên."]]},{"word":"喫茶店","reading":"きっさてん","meaning":"Quán trà","hanViet":"TRÀ ĐIẾM","lesson":10,"ex":[["喫茶店でコーヒーを飲みます。","Tôi uống cà phê ở quán trà."],["友達と喫茶店へ行きます。","Tôi đi quán trà với bạn."],["喫茶店で紅茶を飲みます。","Tôi uống trà ở quán trà."],["喫茶店は静かです。","Quán trà yên tĩnh."],["喫茶店で本を読みます。","Tôi đọc sách ở quán trà."]]},{"word":"本屋","reading":"ほんや","meaning":"Hiệu sách","hanViet":"BẢN ỐC","lesson":10,"ex":[["本屋で本を買います。","Tôi mua sách ở hiệu sách."],["あした、本屋へ行きます。","Ngày mai tôi đi hiệu sách."],["本屋で辞書を買います。","Tôi mua từ điển ở hiệu sách."],["本屋は大きいです。","Hiệu sách to."],["本屋は駅の近くにあります。","Hiệu sách ở gần ga."]]},{"word":"乗り場","reading":"のりば","meaning":"bến xe, điểm lên xuống xe","hanViet":"THỪA TRƯỜNG","lesson":10,"ex":[["バスの乗り場は駅の前です。","Bến xe buýt ở trước ga."],["タクシーの乗り場はどこですか。","Bến taxi ở đâu?"],["乗り場に人がたくさんいます。","Ở bến xe có nhiều người."],["バスの乗り場はここです。","Bến xe buýt ở đây."],["乗り場でバスを待ちます。","Tôi đợi xe buýt ở bến xe."]]},{"word":"県","reading":"けん","meaning":"Tỉnh (Nhật Bản)","hanViet":"HUYỆN","lesson":10,"ex":[["この県に大きい山があります。","Tỉnh này có ngọn núi lớn."],["この県は大きいです。","Tỉnh này lớn."],["県に川があります。","Trong tỉnh có sông."],["あの県に住みます。","Tôi sống ở tỉnh kia."],["この県に大学があります。","Tỉnh này có trường đại học."]]},{"word":"上","reading":"うえ","meaning":"Phía trên","hanViet":"THƯỢNG","lesson":10,"ex":[["本は机の上にあります。","Quyển sách ở trên bàn."],["猫はテーブルの上にいます。","Con mèo ở trên bàn."],["辞書は本の上にあります。","Từ điển ở trên sách."],["上に時計があります。","Phía trên có đồng hồ."],["かばんは机の上にあります。","Cái cặp ở trên bàn."]]},{"word":"下","reading":"した","meaning":"Phía dưới","hanViet":"HẠ","lesson":10,"ex":[["靴はベッドの下にあります。","Đôi giày ở dưới giường."],["本は机の下にあります。","Quyển sách ở dưới bàn."],["猫はテーブルの下にいます。","Con mèo ở dưới bàn."],["下に靴があります。","Phía dưới có giày."],["かばんは机の下にあります。","Cái cặp ở dưới bàn."]]},{"word":"前","reading":"まえ","meaning":"Trước, phía trước","hanViet":"TIỀN","lesson":10,"ex":[["学校の前に公園があります。","Trước trường học có công viên."],["駅の前に本屋があります。","Trước ga có hiệu sách."],["私の前に山田さんがいます。","Trước mặt tôi có anh Yamada."],["店の前に車があります。","Trước cửa hàng có xe ô tô."],["前に公園があります。","Phía trước có công viên."]]},{"word":"うしろ","reading":"うしろ","meaning":"sau","hanViet":"HẬU","lesson":10,"ex":[["私のうしろに田中さんがいます。","Phía sau tôi có anh Tanaka."],["学校のうしろに公園があります。","Phía sau trường học có công viên."],["私のうしろに人がいます。","Phía sau tôi có người."],["店のうしろに駐車場があります。","Phía sau cửa hàng có bãi đỗ xe."],["うしろに山があります。","Phía sau có núi."]]},{"word":"右","reading":"みぎ","meaning":"Bên phải","hanViet":"HỮU","lesson":10,"ex":[["銀行は交差点の右にあります。","Ngân hàng ở phía bên phải ngã tư."],["右に郵便局があります。","Phía bên phải có bưu điện."],["交差点の右に店があります。","Ở bên phải ngã tư có cửa hàng."],["右へ曲がります。","Tôi rẽ phải."],["私の右に田中さんがいます。","Bên phải tôi có anh Tanaka."]]},{"word":"左","reading":"ひだり","meaning":"Bên trái","hanViet":"TẢ","lesson":10,"ex":[["左に郵便局があります。","Phía bên trái có bưu điện."],["左に銀行があります。","Phía bên trái có ngân hàng."],["交差点の左に公園があります。","Ở bên trái ngã tư có công viên."],["左へ曲がります。","Tôi rẽ trái."],["私の左に山田さんがいます。","Bên trái tôi có chị Yamada."]]},{"word":"中","reading":"なか","meaning":"Ở giữa, bên trong","hanViet":"TRUNG","lesson":10,"ex":[["かばんの中に本があります。","Trong cặp có sách."],["箱の中に物があります。","Trong hộp có đồ vật."],["冷蔵庫の中に牛乳があります。","Trong tủ lạnh có sữa."],["教室の中に学生がいます。","Trong lớp học có học sinh."],["中に猫がいます。","Bên trong có con mèo."]]},{"word":"外","reading":"そと","meaning":"Bên ngoài","hanViet":"NGOẠI","lesson":10,"ex":[["外に犬がいます。","Bên ngoài có con chó."],["外に猫がいます。","Bên ngoài có con mèo."],["外は寒いです。","Bên ngoài lạnh."],["外に車があります。","Bên ngoài có xe ô tô."],["外で遊びます。","Tôi chơi ở bên ngoài."]]},{"word":"隣","reading":"となり","meaning":"bên cạnh, nhà bên cạnh","hanViet":"LÂN","lesson":10,"ex":[["私の隣に山田さんがいます。","Bên cạnh tôi có chị Yamada."],["学校の隣に公園があります。","Bên cạnh trường học có công viên."],["隣に本屋があります。","Bên cạnh có hiệu sách."],["私の隣に田中さんがいます。","Bên cạnh tôi có anh Tanaka."],["隣の部屋は広いです。","Phòng bên cạnh rộng."]]},{"word":"近く","reading":"ちかく","meaning":"Gần đây; xung quanh gần","hanViet":"CẬN","lesson":10,"ex":[["駅の近くにコンビニがあります。","Gần ga có cửa hàng tiện lợi."],["学校の近くに公園があります。","Gần trường học có công viên."],["近くに店があります。","Gần đây có cửa hàng."],["うちの近くに駅があります。","Gần nhà tôi có ga."],["近くに住みます。","Tôi sống ở gần đây."]]},{"word":"間","reading":"あいだ","meaning":"Khoảng giữa, khoảng thời gian","hanViet":"GIAN","lesson":10,"ex":[["学校と駅の間に公園があります。","Giữa trường học và ga có công viên."],["机といすの間に猫がいます。","Giữa bàn và ghế có con mèo."],["本屋と銀行の間に店があります。","Giữa hiệu sách và ngân hàng có cửa hàng."],["二時と三時の間に来ます。","Tôi sẽ đến trong khoảng từ hai giờ đến ba giờ."],["学校とうちの間に公園があります。","Giữa trường học và nhà tôi có công viên."]]},{"word":"玄関","reading":"げんかん","meaning":"Lối vào nhà, sảnh trước","hanViet":"HUỲNH QUAN","lesson":10,"ex":[["玄関に靴があります。","Ở lối vào nhà có giày."],["玄関で靴を脱ぎます。","Tôi cởi giày ở lối vào nhà."],["玄関に傘があります。","Ở lối vào nhà có ô."],["玄関は広いです。","Lối vào nhà rộng."],["玄関に花があります。","Ở lối vào nhà có hoa."]]},{"word":"風呂場","reading":"ふろば","meaning":"phòng tắm, nhà tắm","hanViet":"PHONG LỮ TRƯỜNG","lesson":10,"ex":[["風呂場で体を洗います。","Tôi rửa người trong phòng tắm."],["風呂場で顔を洗います。","Tôi rửa mặt trong phòng tắm."],["風呂場は広いです。","Phòng tắm rộng."],["風呂場でシャワーを浴びます。","Tôi tắm vòi sen trong phòng tắm."],["風呂場で歌を歌います。","Tôi hát trong phòng tắm."]]},{"word":"洗面所","reading":"せんめんじょ","meaning":"Chỗ rửa mặt, bồn rửa","hanViet":"TẨY DIỆN SỞ","lesson":10,"ex":[["洗面所で顔を洗います。","Tôi rửa mặt ở chỗ rửa mặt."],["洗面所で手を洗います。","Tôi rửa tay ở chỗ rửa mặt."],["洗面所は小さいです。","Chỗ rửa mặt nhỏ."],["洗面所で髪を洗います。","Tôi gội đầu ở chỗ rửa mặt."],["洗面所は風呂場の隣にあります。","Chỗ rửa mặt ở bên cạnh phòng tắm."]]},{"word":"台所","reading":"だいどころ","meaning":"Nhà bếp","hanViet":"ĐÀI SỞ","lesson":10,"ex":[["台所で料理をします。","Tôi nấu ăn trong bếp."],["台所でごはんを食べます。","Tôi ăn cơm trong bếp."],["台所は広いです。","Nhà bếp rộng."],["台所に冷蔵庫があります。","Trong bếp có tủ lạnh."],["母は台所で働きます。","Mẹ tôi làm việc trong bếp."]]},{"word":"居間","reading":"いま","meaning":"phòng khách, phòng sinh hoạt","hanViet":"CƯ GIAN","lesson":10,"ex":[["居間でテレビを見ます。","Tôi xem ti vi ở phòng khách."],["居間で本を読みます。","Tôi đọc sách ở phòng khách."],["居間は広いです。","Phòng khách rộng."],["居間で友達と話します。","Tôi nói chuyện với bạn ở phòng khách."],["居間にテレビがあります。","Trong phòng khách có ti vi."]]},{"word":"寝室","reading":"しんしつ","meaning":"Phòng ngủ","hanViet":"TẨM THẤT","lesson":10,"ex":[["寝室で寝ます。","Tôi ngủ trong phòng ngủ."],["寝室にベッドがあります。","Trong phòng ngủ có giường."],["寝室は小さいです。","Phòng ngủ nhỏ."],["寝室で本を読みます。","Tôi đọc sách trong phòng ngủ."],["寝室は二階にあります。","Phòng ngủ ở tầng hai."]]},{"word":"廊下","reading":"ろうか","meaning":"Hành lang","hanViet":"LANG HẠ","lesson":10,"ex":[["廊下に子どもがいます。","Ở hành lang có trẻ con."],["廊下はきれいです。","Hành lang sạch đẹp."],["子どもは廊下で遊びます。","Trẻ con chơi ở hành lang."],["教室の前に廊下があります。","Trước phòng học có hành lang."],["廊下の奥にトイレがあります。","Ở cuối hành lang có nhà vệ sinh."]]},{"word":"象","reading":"ぞう","meaning":"con voi","hanViet":"","lesson":10,"ex":[["動物園に象がいます。","Trong sở thú có voi."],["象は大きいです。","Voi to lớn."],["子どもは象が好きです。","Trẻ con thích voi."],["動物園で象の写真を撮りました。","Tôi đã chụp ảnh voi ở sở thú."],["象は耳が大きいです。","Voi có đôi tai to."]]},{"word":"パンダ","reading":"パンダ","meaning":"gấu trúc","hanViet":"","lesson":10,"ex":[["動物園でパンダを見ます。","Tôi xem gấu trúc ở sở thú."],["パンダは中国にいます。","Gấu trúc sống ở Trung Quốc."],["動物園にパンダが二匹います。","Trong sở thú có hai con gấu trúc."],["わたしはパンダの写真を撮りました。","Tôi đã chụp ảnh gấu trúc."],["きのう動物園へパンダを見に行きました。","Hôm qua tôi đã đi sở thú để xem gấu trúc."]]},{"word":"コンビニ","reading":"コンビニ","meaning":"của hàng tiện lợi","hanViet":"","lesson":10,"ex":[["コンビニでおにぎりを買います。","Tôi mua cơm nắm ở cửa hàng tiện lợi."],["コンビニは夜も買い物ができます。","Ở cửa hàng tiện lợi ban đêm cũng mua sắm được."],["駅の前にコンビニがあります。","Trước ga có cửa hàng tiện lợi."],["コンビニでジュースを買いました。","Tôi đã mua nước ép ở cửa hàng tiện lợi."],["コンビニはうちの近くにあります。","Cửa hàng tiện lợi ở gần nhà tôi."]]},{"word":"フィルム","reading":"フィルム","meaning":"phim","hanViet":"","lesson":10,"ex":[["カメラにフィルムを入れます。","Tôi cho phim vào máy ảnh."],["カメラのフィルムは古いです。","Phim của máy ảnh đã cũ."],["フィルムを買いに店へ行きました。","Tôi đã đi đến cửa hàng để mua phim."],["このフィルムは高いです。","Cuộn phim này đắt."],["きのうフィルムを二つ買いました。","Hôm qua tôi đã mua hai cuộn phim."]]},{"word":"スイッチ","reading":"スイッチ","meaning":"công tắc","hanViet":"","lesson":10,"ex":[["スイッチを押します。","Tôi bấm công tắc."],["電気のスイッチはどこですか。","Công tắc điện ở đâu?"],["スイッチを押して、テレビをつけます。","Tôi bấm công tắc để bật ti vi."],["スイッチが小さいです。","Công tắc nhỏ."],["スイッチはドアの近くにあります。","Công tắc ở gần cửa."]]},{"word":"テーブル","reading":"テーブル","meaning":"bàn","hanViet":"","lesson":10,"ex":[["テーブルの上に本があります。","Trên bàn có quyển sách."],["テーブルの上に花があります。","Trên bàn có hoa."],["テーブルで昼ごはんを食べます。","Tôi ăn trưa ở bàn."],["このテーブルは大きいです。","Cái bàn này to."],["テーブルの下に猫がいます。","Dưới bàn có con mèo."]]},{"word":"ベッド","reading":"ベッド","meaning":"giường","hanViet":"","lesson":10,"ex":[["ベッドで寝ます。","Tôi ngủ trên giường."],["ベッドは広いです。","Giường rộng."],["新しいベッドを買いました。","Tôi đã mua giường mới."],["ベッドで本を読みます。","Tôi đọc sách trên giường."],["ベッドは部屋にあります。","Giường ở trong phòng."]]},{"word":"ドア","reading":"ドア","meaning":"cửa","hanViet":"","lesson":10,"ex":[["ドアは大きいです。","Cửa to."],["ドアを開けてください。","Xin hãy mở cửa."],["ドアのうしろに傘があります。","Sau cửa có cái ô."],["ドアの前に犬がいます。","Trước cửa có con chó."],["教室のドアは白いです。","Cửa phòng học màu trắng."]]},{"word":"ポスト","reading":"ポスト","meaning":"hộp thư, hòm thư","hanViet":"","lesson":10,"ex":[["ポストに手紙を入れます。","Tôi bỏ thư vào hòm thư."],["ポストは駅の前にあります。","Hòm thư ở trước ga."],["ポストは赤いです。","Hòm thư màu đỏ."],["ポストは郵便局の前です。","Hòm thư ở trước bưu điện."],["ポストにエアメールを入れました。","Tôi đã bỏ thư hàng không vào hòm thư."]]},{"word":"ビル","reading":"ビル","meaning":"toà nhà","hanViet":"","lesson":10,"ex":[["駅の前に大きいビルがあります。","Trước ga có tòa nhà lớn."],["あのビルは高いです。","Tòa nhà kia cao."],["ビルに会社があります。","Trong tòa nhà có công ty."],["新しいビルで働きます。","Tôi làm việc ở tòa nhà mới."],["このビルは十階です。","Tòa nhà này có mười tầng."]]},{"word":"～屋","reading":"～や","meaning":"hiệu ~, cửa hàng ~","hanViet":"ỐC","lesson":10,"ex":[["パン屋でパンを買います。","Tôi mua bánh mì ở hiệu bánh."],["肉屋で牛肉を買いました。","Tôi đã mua thịt bò ở hiệu thịt."],["駅の前に新しい本屋があります。","Trước ga có hiệu sách mới."],["魚屋は駅の近くにあります。","Hiệu cá ở gần ga."],["酒屋でビールを買いました。","Tôi đã mua bia ở hiệu rượu."]]},{"word":"など","reading":"など","meaning":"v.v., vân vân","hanViet":"","lesson":10,"ex":[["机の上に本や鉛筆などがあります。","Trên bàn có sách, bút chì, v.v."],["りんごやみかんなどを買いました。","Tôi đã mua táo, quýt, v.v."],["部屋に机やいすなどがあります。","Trong phòng có bàn, ghế, v.v."],["日本や中国などへ旅行に行きたいです。","Tôi muốn đi du lịch Nhật Bản, Trung Quốc, v.v."],["ケーキやアイスクリームなどが好きです。","Tôi thích bánh kem, kem, v.v."]]},{"word":"～段目","reading":"～だんめ","meaning":"ngăn thứ ~","hanViet":"MỤC","lesson":10,"ex":[["本は棚の二段目にあります。","Quyển sách ở ngăn thứ hai của kệ."],["辞書は棚の三段目にあります。","Từ điển ở ngăn thứ ba của kệ."],["一段目に本があります。","Ở ngăn thứ nhất có sách."],["四段目に雑誌があります。","Ở ngăn thứ tư có tạp chí."],["五段目に何がありますか。","Ở ngăn thứ năm có gì?"]]},{"word":"どうもすみません","reading":"どうもすみません","meaning":"rất xin lỗi","hanViet":"","lesson":10,"ex":[["遅くなって、どうもすみません。","Tôi đến muộn, rất xin lỗi."],["宿題を忘れて、どうもすみません。","Tôi quên bài tập về nhà, rất xin lỗi."],["本をなくして、どうもすみません。","Tôi làm mất sách, rất xin lỗi."],["きのうはどうもすみません。","Hôm qua rất xin lỗi."],["約束を忘れて、どうもすみません。","Tôi quên lời hẹn, rất xin lỗi."]]},{"word":"チリソース","reading":"チリソース","meaning":"tương ớt","hanViet":"","lesson":10,"ex":[["この料理にチリソースを入れます。","Tôi cho tương ớt vào món ăn này."],["チリソースは辛いです。","Tương ớt cay."],["チリソースを買いにスーパーへ行きました。","Tôi đã đi siêu thị để mua tương ớt."],["うどんにチリソースを入れました。","Tôi đã cho tương ớt vào mì udon."],["チリソースが好きです。","Tôi thích tương ớt."]]},{"word":"奥","reading":"おく","meaning":"Phía trong sâu, bên trong","hanViet":"ÁO","lesson":10,"ex":[["奥にトイレがあります。","Phía trong sâu có nhà vệ sinh."],["店の奥に本があります。","Phía trong cửa hàng có sách."],["部屋の奥にベッドがあります。","Phía trong phòng có giường."],["奥にだれがいますか。","Ở phía trong có ai?"],["教室の奥に先生がいます。","Ở phía trong phòng học có thầy giáo."]]},{"word":"スパイス・コーナー","reading":"スパイス・コーナー","meaning":"quầy gia vị","hanViet":"","lesson":10,"ex":[["スパイス・コーナーにチリソースがあります。","Ở quầy gia vị có tương ớt."],["スパイス・コーナーで塩を買いました。","Tôi đã mua muối ở quầy gia vị."],["スパイス・コーナーはスーパーの奥にあります。","Quầy gia vị ở phía trong siêu thị."],["スパイス・コーナーに砂糖があります。","Ở quầy gia vị có đường."],["スパイス・コーナーはどこですか。","Quầy gia vị ở đâu?"]]},{"word":"エーティーエム","reading":"エーティーエム","meaning":"máy ATM","hanViet":"","lesson":10,"ex":[["エーティーエムでお金を引きます。","Tôi rút tiền ở máy ATM."],["エーティーエムは銀行にあります。","Máy ATM ở trong ngân hàng."],["エーティーエムの前に人がいます。","Trước máy ATM có người."],["コンビニにエーティーエムがあります。","Trong cửa hàng tiện lợi có máy ATM."],["エーティーエムは便利です。","Máy ATM tiện lợi."]]},{"word":"います","reading":"います","meaning":"có, ở (tồn tại, dùng cho người và động vật)","hanViet":"","lesson":11,"ex":[["部屋に猫がいます。","Trong phòng có một con mèo."],["学校に先生がいます。","Ở trường có thầy giáo."],["公園に子どもがいます。","Ở công viên có trẻ con."],["うちに犬がいます。","Ở nhà tôi có con chó."],["クラスに学生が二十人います。","Trong lớp có hai mươi học sinh."]]},{"word":"かかります","reading":"かかります","meaning":"mất, tốn","hanViet":"","lesson":11,"ex":[["学校まで三十分かかります。","Đi đến trường mất ba mươi phút."],["駅まで十分かかります。","Đi đến ga mất mười phút."],["日本まで飛行機で六時間かかります。","Đi đến Nhật bằng máy bay mất sáu tiếng."],["うちから会社まで三十分かかります。","Từ nhà đến công ty mất ba mươi phút."],["宿題に一時間かかります。","Làm bài tập mất một tiếng."]]},{"word":"一つ","reading":"ひとつ","meaning":"1 cái (đồ vật)","hanViet":"NHẤT","lesson":11,"ex":[["りんごを一つください。","Cho tôi một quả táo."],["みかんを一つ食べました。","Tôi đã ăn một quả quýt."],["卵が一つあります。","Có một quả trứng."],["ケーキを一つ買いました。","Tôi đã mua một cái bánh kem."],["机の上に鉛筆が一つあります。","Trên bàn có một cây bút chì."]]},{"word":"二つ","reading":"ふたつ","meaning":"2 cái","hanViet":"NHỊ","lesson":11,"ex":[["おにぎりを二つ買いました。","Tôi đã mua hai cái cơm nắm."],["りんごを二つ食べました。","Tôi đã ăn hai quả táo."],["本が二つあります。","Có hai quyển sách."],["コーヒーを二つください。","Cho tôi hai ly cà phê."],["卵を二つ買いました。","Tôi đã mua hai quả trứng."]]},{"word":"三つ","reading":"みっつ","meaning":"3 cái","hanViet":"TAM","lesson":11,"ex":[["机の上に本が三つあります。","Trên bàn có ba quyển sách."],["日曜日に弟はりんごを三つ買いました。","Chủ nhật em trai tôi đã mua ba quả táo."],["りんごが三つあります。","Có ba quả táo."],["おにぎりを三つ作りました。","Tôi đã làm ba cái cơm nắm."],["鉛筆を三つ買いました。","Tôi đã mua ba cây bút chì."]]},{"word":"四つ","reading":"よっつ","meaning":"4 cái","hanViet":"TỨ","lesson":11,"ex":[["みかんを四つ食べました。","Tôi đã ăn bốn quả quýt."],["りんごを四つ買いました。","Tôi đã mua bốn quả táo."],["卵が四つあります。","Có bốn quả trứng."],["おにぎりを四つ作りました。","Tôi đã làm bốn cái cơm nắm."],["いすが四つあります。","Có bốn cái ghế."]]},{"word":"五つ","reading":"いつつ","meaning":"5 cái","hanViet":"NGŨ","lesson":11,"ex":[["卵が五つあります。","Có năm quả trứng."],["みかんを五つ買いました。","Tôi đã mua năm quả quýt."],["りんごが五つあります。","Có năm quả táo."],["おにぎりを五つ食べました。","Tôi đã ăn năm cái cơm nắm."],["本を五つ買いました。","Tôi đã mua năm quyển sách."]]},{"word":"六つ","reading":"むっつ","meaning":"6 cái","hanViet":"LỤC","lesson":11,"ex":[["鉛筆を六つ買いました。","Tôi đã mua sáu cây bút chì."],["みかんを六つ食べました。","Tôi đã ăn sáu quả quýt."],["りんごが六つあります。","Có sáu quả táo."],["卵を六つ買いました。","Tôi đã mua sáu quả trứng."],["おにぎりを六つ作りました。","Tôi đã làm sáu cái cơm nắm."]]},{"word":"七つ","reading":"ななつ","meaning":"7 cái","hanViet":"THẤT","lesson":11,"ex":[["箱の中にりんごが七つあります。","Trong hộp có bảy quả táo."],["みかんを七つ買いました。","Tôi đã mua bảy quả quýt."],["卵が七つあります。","Có bảy quả trứng."],["おにぎりを七つ作りました。","Tôi đã làm bảy cái cơm nắm."],["鉛筆を七つ買いました。","Tôi đã mua bảy cây bút chì."]]},{"word":"八つ","reading":"やっつ","meaning":"8 cái","hanViet":"BÁT","lesson":11,"ex":[["いすが八つあります。","Có tám cái ghế."],["みかんを八つ食べました。","Tôi đã ăn tám quả quýt."],["りんごが八つあります。","Có tám quả táo."],["卵を八つ買いました。","Tôi đã mua tám quả trứng."],["おにぎりを八つ作りました。","Tôi đã làm tám cái cơm nắm."]]},{"word":"九つ","reading":"ここのつ","meaning":"9 cái","hanViet":"CỬU","lesson":11,"ex":[["みかんを九つください。","Cho tôi chín quả quýt."],["りんごを九つ買いました。","Tôi đã mua chín quả táo."],["卵が九つあります。","Có chín quả trứng."],["おにぎりを九つ作りました。","Tôi đã làm chín cái cơm nắm."],["鉛筆を九つ買いました。","Tôi đã mua chín cây bút chì."]]},{"word":"十","reading":"とお","meaning":"10 cái","hanViet":"THẬP","lesson":11,"ex":[["りんごが十あります。","Có mười quả táo."],["みかんを十買いました。","Tôi đã mua mười quả quýt."],["卵が十あります。","Có mười quả trứng."],["おにぎりを十作りました。","Tôi đã làm mười cái cơm nắm."],["鉛筆を十買いました。","Tôi đã mua mười cây bút chì."]]},{"word":"いくつ","reading":"いくつ","meaning":"bao nhiêu cái","hanViet":"","lesson":11,"ex":[["本はいくつありますか。","Có mấy quyển sách?"],["教室にいすはいくつありますか。","Trong lớp học có bao nhiêu cái ghế?"],["みかんをいくつ食べましたか。","Bạn đã ăn mấy quả quýt?"],["卵はいくつ要りますか。","Cần mấy quả trứng?"],["鉛筆はいくつ買いましたか。","Bạn đã mua mấy cây bút chì?"]]},{"word":"一人","reading":"ひとり","meaning":"Một người","hanViet":"NHẤT NHÂN","lesson":11,"ex":[["クラスに留学生が一人います。","Trong lớp có một du học sinh."],["一人で旅行に行きました。","Tôi đã đi du lịch một mình."],["クラスに先生が一人います。","Trong lớp có một thầy giáo."],["子どもが一人います。","Tôi có một đứa con."],["一人で映画を見ました。","Tôi đã xem phim một mình."]]},{"word":"二人","reading":"ふたり","meaning":"Hai người","hanViet":"NHỊ NHÂN","lesson":11,"ex":[["子どもが二人います。","Tôi có hai đứa con."],["クラスに先生が二人います。","Trong lớp có hai thầy giáo."],["二人で昼ごはんを食べました。","Hai người đã cùng ăn trưa."],["友達が二人来ました。","Hai người bạn đã đến."],["二人で旅行に行きました。","Hai người đã đi du lịch cùng nhau."]]},{"word":"ー人","reading":"ーにん","meaning":"người","hanViet":"NHÂN","lesson":11,"ex":[["家族は四人です。","Gia đình tôi có bốn người."],["クラスは三十人です。","Lớp học có ba mươi người."],["家族は五人です。","Gia đình tôi có năm người."],["パーティーに十人が来ました。","Mười người đã đến bữa tiệc."],["学校に学生が二百人います。","Ở trường có hai trăm học sinh."]]},{"word":"ー台","reading":"ーだい","meaning":"~ chiếc, ~ cái (dùng để đếm máy móc, xe cộ…)","hanViet":"","lesson":11,"ex":[["車が二台あります。","Có hai chiếc xe."],["自転車が三台あります。","Có ba chiếc xe đạp."],["テレビが一台あります。","Có một cái ti vi."],["パソコンを二台買いました。","Tôi đã mua hai cái máy tính."],["車を一台買いたいです。","Tôi muốn mua một chiếc xe ô tô."]]},{"word":"ー枚","reading":"ーまい","meaning":"~ tờ, chiếc, cái (đơn vị dùng để đếm vật mỏng)","hanViet":"","lesson":11,"ex":[["写真を三枚撮りました。","Tôi đã chụp ba tấm ảnh."],["はがきを二枚買いました。","Tôi đã mua hai tấm bưu thiếp."],["写真を一枚撮りました。","Tôi đã chụp một tấm ảnh."],["旅行で写真を二枚撮りました。","Trong chuyến du lịch tôi đã chụp hai tấm ảnh."],["写真を五枚見せました。","Tôi đã cho xem năm tấm ảnh."]]},{"word":"ー回","reading":"ーかい","meaning":"~ lần (đơn vị chỉ tần xuất)","hanViet":"","lesson":11,"ex":[["一週間に二回泳ぎます。","Tôi bơi hai lần một tuần."],["一日に三回ごはんを食べます。","Một ngày tôi ăn cơm ba lần."],["一週間に一回映画を見ます。","Một tuần tôi xem phim một lần."],["一か月に二回買い物に行きます。","Một tháng tôi đi mua sắm hai lần."],["一年に一回旅行に行きます。","Một năm tôi đi du lịch một lần."]]},{"word":"切手","reading":"きって","meaning":"Con tem","hanViet":"THIẾT THỦ","lesson":11,"ex":[["切手を五枚買いました。","Tôi đã mua năm con tem."],["切手を二枚買いました。","Tôi đã mua hai con tem."],["切手を十枚買いました。","Tôi đã mua 10 con tem."],["この切手は八十円です。","Con tem này giá tám mươi yên."],["郵便局で切手を五枚買いました。","Tôi đã mua năm con tem ở bưu điện."]]},{"word":"はがき","reading":"はがき","meaning":"bưu thiếp","hanViet":"","lesson":11,"ex":[["友達にはがきを送りました。","Tôi đã gửi bưu thiếp cho bạn."],["はがきを三枚買いました。","Tôi đã mua ba tấm bưu thiếp."],["母にはがきを送ります。","Tôi gửi bưu thiếp cho mẹ."],["はがきを書きました。","Tôi đã viết bưu thiếp."],["日本からはがきが来ました。","Bưu thiếp đã đến từ Nhật Bản."]]},{"word":"封筒","reading":"ふうとう","meaning":"Phong bì","hanViet":"PHONG ĐỒNG","lesson":11,"ex":[["手紙を封筒に入れました。","Tôi đã bỏ thư vào phong bì."],["封筒を買いに郵便局へ行きました。","Tôi đã đi bưu điện để mua phong bì."],["封筒は机の上にあります。","Phong bì ở trên bàn."],["白い封筒を買いました。","Tôi đã mua phong bì trắng."],["封筒に名前を書きました。","Tôi đã viết tên lên phong bì."]]},{"word":"速達","reading":"そくたつ","meaning":"chuyển phát nhanh","hanViet":"TỐC ĐẠT","lesson":11,"ex":[["この手紙を速達で送ってください。","Xin hãy gửi bức thư này bằng chuyển phát nhanh."],["速達で荷物を送りました。","Tôi đã gửi hàng bằng chuyển phát nhanh."],["速達は便利です。","Chuyển phát nhanh tiện lợi."],["このはがきを速達で送ります。","Tôi gửi tấm bưu thiếp này bằng chuyển phát nhanh."],["速達はいくらですか。","Chuyển phát nhanh giá bao nhiêu?"]]},{"word":"書留","reading":"かきとめ","meaning":"gửi bảo đảm","hanViet":"THƯ","lesson":11,"ex":[["この手紙は書留で送りました。","Tôi đã gửi bức thư này bằng thư bảo đảm."],["書留で荷物を送りました。","Tôi đã gửi hàng bằng thư bảo đảm."],["このはがきは書留で送ります。","Tôi gửi tấm bưu thiếp này bằng thư bảo đảm."],["書留はいくらですか。","Gửi bảo đảm giá bao nhiêu?"],["書留で送ってください。","Xin hãy gửi bằng thư bảo đảm."]]},{"word":"航空便","reading":"こうくうびん","meaning":"chuyến bay, bưu phẩm gửi đường hàng không","hanViet":"HÀNG KHÔNG TIỆN","lesson":11,"ex":[["この荷物を航空便で送りました。","Tôi đã gửi gói hàng này bằng đường hàng không."],["航空便で手紙を送ります。","Tôi gửi thư bằng đường hàng không."],["航空便は速いです。","Đường hàng không nhanh."],["航空便で送ってください。","Xin hãy gửi bằng đường hàng không."],["航空便はいくらですか。","Gửi đường hàng không giá bao nhiêu?"]]},{"word":"船便","reading":"ふなびん","meaning":"Gửi đường biển (thư, hàng)","hanViet":"THUYỀN TIỆN","lesson":11,"ex":[["荷物を船便で送りました。","Tôi đã gửi hàng bằng đường biển."],["船便で手紙を送ります。","Tôi gửi thư bằng đường biển."],["船便は遅いです。","Đường biển chậm."],["船便で送ってください。","Xin hãy gửi bằng đường biển."],["船便はいくらですか。","Gửi đường biển giá bao nhiêu?"]]},{"word":"両親","reading":"りょうしん","meaning":"bố mẹ, song thân","hanViet":"LƯỠNG THÂN","lesson":11,"ex":[["両親はベトナムに住んでいます。","Bố mẹ tôi sống ở Việt Nam."],["両親は日本に住んでいます。","Bố mẹ tôi sống ở Nhật Bản."],["両親に手紙を書きました。","Tôi đã viết thư cho bố mẹ."],["両親は元気です。","Bố mẹ tôi khỏe."],["両親に会いにベトナムへ帰ります。","Tôi về Việt Nam để gặp bố mẹ."]]},{"word":"兄弟","reading":"きょうだい","meaning":"Anh em","hanViet":"HUYNH ĐỆ","lesson":11,"ex":[["兄弟は三人います。","Tôi có ba anh chị em."],["兄弟は二人います。","Tôi có hai anh chị em."],["兄弟はいますか。","Bạn có anh chị em không?"],["兄弟と旅行に行きました。","Tôi đã đi du lịch cùng anh chị em."],["兄弟は学校で勉強しています。","Anh chị em tôi đang học ở trường."]]},{"word":"兄","reading":"あに","meaning":"Anh trai (của mình)","hanViet":"HUYNH","lesson":11,"ex":[["兄は会社員です。","Anh trai tôi là nhân viên công ty."],["兄は学生です。","Anh trai tôi là học sinh."],["兄は大学で勉強しています。","Anh trai tôi đang học ở đại học."],["兄は二十歳です。","Anh trai tôi hai mươi tuổi."],["兄と映画を見ました。","Tôi đã xem phim cùng anh trai."]]},{"word":"お兄さん","reading":"おにいさん","meaning":"Anh (gọi kính trọng)","hanViet":"HUYNH","lesson":11,"ex":[["田中さんのお兄さんは先生です。","Anh trai của anh Tanaka là giáo viên."],["山田さんのお兄さんは会社員です。","Anh trai của chị Yamada là nhân viên công ty."],["お兄さんは元気ですか。","Anh trai bạn có khỏe không?"],["お兄さんは先生ですか。","Anh trai bạn là giáo viên à?"],["田中さんのお兄さんは医者です。","Anh trai của anh Tanaka là bác sĩ."]]},{"word":"姉","reading":"あね","meaning":"Chị gái (của mình)","hanViet":"TỶ","lesson":11,"ex":[["姉は大学で勉強しています。","Chị gái tôi đang học ở đại học."],["姉は会社員です。","Chị gái tôi là nhân viên công ty."],["姉は看護婦です。","Chị gái tôi là y tá."],["姉と買い物に行きました。","Tôi đã đi mua sắm cùng chị gái."],["姉は大学で日本語を勉強しています。","Chị gái tôi đang học tiếng Nhật ở trường đại học."]]},{"word":"お姉さん","reading":"おねえさん","meaning":"Chị (gọi kính trọng)","hanViet":"TỶ","lesson":11,"ex":[["山田さんのお姉さんは看護婦です。","Chị gái của chị Yamada là y tá."],["田中さんのお姉さんは先生です。","Chị gái của anh Tanaka là giáo viên."],["お姉さんは元気ですか。","Chị gái bạn có khỏe không?"],["山田さんのお姉さんは会社員です。","Chị gái của chị Yamada là nhân viên công ty."],["お姉さんはピアノを弾きます。","Chị gái bạn chơi piano."]]},{"word":"弟","reading":"おとうと","meaning":"Em trai (của mình)","hanViet":"ĐỆ","lesson":11,"ex":[["弟は学生です。","Em trai tôi là học sinh."],["弟は学校で勉強しています。","Em trai tôi đang học ở trường."],["弟はサッカーが好きです。","Em trai tôi thích bóng đá."],["弟と公園で遊びました。","Tôi đã chơi cùng em trai ở công viên."],["弟は十二歳です。","Em trai tôi mười hai tuổi."]]},{"word":"弟さん","reading":"おとうとさん","meaning":"Em trai (của người khác)","hanViet":"ĐỆ","lesson":11,"ex":[["田中さんの弟さんは会社員です。","Em trai của anh Tanaka là nhân viên công ty."],["山田さんの弟さんは学生です。","Em trai của chị Yamada là học sinh."],["弟さんは元気ですか。","Em trai bạn có khỏe không?"],["田中さんの弟さんは先生です。","Em trai của anh Tanaka là giáo viên."],["弟さんはサッカーが好きです。","Em trai bạn thích bóng đá."]]},{"word":"妹","reading":"いもうと","meaning":"Em gái (của mình)","hanViet":"MUỘI","lesson":11,"ex":[["妹はピアノを弾きます。","Em gái tôi chơi piano."],["妹は学生です。","Em gái tôi là học sinh."],["妹はダンスが好きです。","Em gái tôi thích khiêu vũ."],["妹と買い物に行きました。","Tôi đã đi mua sắm cùng em gái."],["妹は十歳です。","Em gái tôi mười tuổi."]]},{"word":"妹さん","reading":"いもうとさん","meaning":"Em gái (của người khác)","hanViet":"MUỘI","lesson":11,"ex":[["山田さんの妹さんは学生です。","Em gái của chị Yamada là học sinh."],["田中さんの妹さんは会社員です。","Em gái của anh Tanaka là nhân viên công ty."],["妹さんは元気ですか。","Em gái bạn có khỏe không?"],["山田さんの妹さんは先生です。","Em gái của chị Yamada là giáo viên."],["妹さんはピアノを弾きます。","Em gái bạn chơi piano."]]},{"word":"外国","reading":"がいこく","meaning":"Nước ngoài","hanViet":"NGOẠI QUỐC","lesson":11,"ex":[["外国で日本語を勉強しました。","Tôi đã học tiếng Nhật ở nước ngoài."],["外国へ旅行に行きたいです。","Tôi muốn đi du lịch nước ngoài."],["外国に住みたいです。","Tôi muốn sống ở nước ngoài."],["外国から友達が来ました。","Bạn đã đến từ nước ngoài."],["外国で働きたいです。","Tôi muốn làm việc ở nước ngoài."]]},{"word":"ー時間","reading":"ーじかん","meaning":"thời gian","hanViet":"THỜI GIAN","lesson":11,"ex":[["日本語を二時間勉強しました。","Tôi đã học tiếng Nhật hai tiếng."],["日本語を一時間勉強します。","Tôi học tiếng Nhật một tiếng."],["テレビを二時間見ました。","Tôi đã xem ti vi hai tiếng."],["三時間日本語を勉強しました。","Tôi đã học tiếng Nhật ba tiếng."],["電車で一時間かかります。","Đi bằng tàu điện mất một tiếng."]]},{"word":"ー週間","reading":"ーしゅうかん","meaning":"~ tuần","hanViet":"GIAN","lesson":11,"ex":[["二週間日本へ旅行に行きました。","Tôi đã đi du lịch Nhật Bản hai tuần."],["一週間日本にいました。","Tôi đã ở Nhật một tuần."],["三週間ベトナムへ帰ります。","Tôi về Việt Nam ba tuần."],["一週間休みます。","Tôi nghỉ một tuần."],["二週間日本語を勉強しました。","Tôi đã học tiếng Nhật hai tuần."]]},{"word":"ーか月","reading":"ーかげつ","meaning":"~ tháng","hanViet":"NGUYỆT","lesson":11,"ex":[["日本に三か月住んでいます。","Tôi đã sống ở Nhật ba tháng."],["日本語を六か月勉強しています。","Tôi đã học tiếng Nhật sáu tháng."],["一か月ベトナムにいました。","Tôi đã ở Việt Nam một tháng."],["二か月日本へ旅行に行きました。","Tôi đã đi du lịch Nhật Bản hai tháng."],["四か月日本語を勉強しました。","Tôi đã học tiếng Nhật bốn tháng."]]},{"word":"ー年","reading":"ーねん","meaning":"~ năm","hanViet":"NIÊN","lesson":11,"ex":[["日本語を一年勉強しています。","Tôi đã học tiếng Nhật một năm."],["日本に二年住んでいます。","Tôi đã sống ở Nhật hai năm."],["三年日本語を勉強しました。","Tôi đã học tiếng Nhật ba năm."],["一年日本にいました。","Tôi đã ở Nhật một năm."],["五年会社で働いています。","Tôi đã làm việc ở công ty năm năm."]]},{"word":"～ぐらい","reading":"～ぐらい","meaning":"khoảng～","hanViet":"","lesson":11,"ex":[["日本語を二時間ぐらい勉強しました。","Tôi đã học tiếng Nhật khoảng hai tiếng."],["日本語を一時間ぐらい勉強します。","Tôi học tiếng Nhật khoảng một tiếng."],["駅まで十分ぐらいかかります。","Đi đến ga mất khoảng mười phút."],["本を三冊ぐらい買いました。","Tôi đã mua khoảng ba quyển sách."],["二千円ぐらいです。","Khoảng hai nghìn yên."]]},{"word":"どのくらい","reading":"どのくらい","meaning":"bao lâu","hanViet":"","lesson":11,"ex":[["日本語をどのくらい勉強しましたか。","Bạn đã học tiếng Nhật bao lâu rồi?"],["日本にどのくらい住んでいますか。","Bạn đã sống ở Nhật bao lâu rồi?"],["学校までどのくらいかかりますか。","Đi đến trường mất bao lâu?"],["テレビをどのくらい見ますか。","Bạn xem ti vi bao lâu?"],["どのくらい待ちましたか。","Bạn đã đợi bao lâu?"]]},{"word":"全部で","reading":"ぜんぶで","meaning":"tất cả, toàn bộ","hanViet":"TOÀN BỘ","lesson":11,"ex":[["全部で千円です。","Tất cả là một nghìn yên."],["全部で二千円です。","Tất cả là hai nghìn yên."],["全部で五人です。","Tất cả là năm người."],["りんごは全部で十あります。","Táo tất cả có mười quả."],["全部で一時間かかります。","Tất cả mất một tiếng."]]},{"word":"みんな","reading":"みんな","meaning":"mọi người","hanViet":"","lesson":11,"ex":[["みんなで昼ごはんを食べました。","Mọi người đã cùng ăn trưa."],["みんなで映画を見ました。","Mọi người đã cùng xem phim."],["みんなで旅行に行きました。","Mọi người đã cùng đi du lịch."],["みんなは元気です。","Mọi người đều khỏe."],["みんなで歌を歌いました。","Mọi người đã cùng hát."]]},{"word":"～だけ","reading":"～だけ","meaning":"～chỉ","hanViet":"","lesson":11,"ex":[["水だけ飲みました。","Tôi chỉ uống nước."],["りんごだけ食べました。","Tôi chỉ ăn táo."],["日本語だけ話します。","Tôi chỉ nói tiếng Nhật."],["一人だけ来ました。","Chỉ một người đến."],["少しだけ食べました。","Tôi chỉ ăn một ít."]]},{"word":"天どん","reading":"てんどん","meaning":"cơm và tôm chiên tẩm bột","hanViet":"","lesson":11,"ex":[["昼ごはんに天どんを食べました。","Tôi đã ăn cơm tôm chiên tẩm bột vào bữa trưa."],["天どんはおいしいです。","Cơm tôm chiên tẩm bột ngon."],["天どんを食べたいです。","Tôi muốn ăn cơm tôm chiên tẩm bột."],["レストランで天どんを食べました。","Tôi đã ăn cơm tôm chiên tẩm bột ở nhà hàng."],["天どんは八百円です。","Cơm tôm chiên tẩm bột giá tám trăm yên."]]},{"word":"親子どん","reading":"おやこどん","meaning":"cơm với thịt gà và trứng","hanViet":"TỬ","lesson":11,"ex":[["親子どんを食べたいです。","Tôi muốn ăn cơm gà trứng."],["親子どんはおいしいです。","Cơm gà trứng ngon."],["昼ごはんに親子どんを食べました。","Tôi đã ăn cơm gà trứng vào bữa trưa."],["親子どんを作りました。","Tôi đã làm cơm gà trứng."],["親子どんは六百円です。","Cơm gà trứng giá sáu trăm yên."]]},{"word":"牛どん","reading":"ぎゅうどん","meaning":"món cơm thịt bò","hanViet":"NGƯU","lesson":11,"ex":[["牛どんはおいしいです。","Cơm thịt bò ngon."],["牛どんを食べたいです。","Tôi muốn ăn cơm thịt bò."],["昼ごはんに牛どんを食べました。","Tôi đã ăn cơm thịt bò vào bữa trưa."],["牛どんは五百円です。","Cơm thịt bò giá năm trăm yên."],["牛どんを作りました。","Tôi đã làm cơm thịt bò."]]},{"word":"焼肉","reading":"やきにく","meaning":"Thịt nướng","hanViet":"THIÊU NHỤC","lesson":11,"ex":[["友達と焼肉を食べに行きました。","Tôi đã đi ăn thịt nướng với bạn."],["焼肉はおいしいです。","Thịt nướng ngon."],["焼肉を食べたいです。","Tôi muốn ăn thịt nướng."],["レストランで焼肉を食べました。","Tôi đã ăn thịt nướng ở nhà hàng."],["晩ごはんに焼肉を食べました。","Tôi đã ăn thịt nướng vào bữa tối."]]},{"word":"野菜いため","reading":"やさいいため","meaning":"rau xào","hanViet":"","lesson":11,"ex":[["晩ごはんに野菜いためを作りました。","Tôi đã làm rau xào cho bữa tối."],["野菜いためはおいしいです。","Rau xào ngon."],["野菜いためを食べました。","Tôi đã ăn rau xào."],["昼ごはんに野菜いためを作りました。","Tôi đã làm rau xào cho bữa trưa."],["野菜いためを作りたいです。","Tôi muốn làm rau xào."]]},{"word":"漬物","reading":"つけもの","meaning":"đồ muối chua, dưa muối","hanViet":"TÍ VẬT","lesson":11,"ex":[["漬物は少し塩辛いです。","Dưa muối hơi mặn."],["漬物はおいしいです。","Dưa muối ngon."],["ごはんと漬物を食べました。","Tôi đã ăn cơm với dưa muối."],["漬物を作りました。","Tôi đã làm dưa muối."],["漬物が好きです。","Tôi thích dưa muối."]]},{"word":"みそ汁","reading":"みそしる","meaning":"súp miso","hanViet":"","lesson":11,"ex":[["朝ごはんにみそ汁を飲みました。","Tôi đã uống súp miso vào bữa sáng."],["みそ汁はおいしいです。","Súp miso ngon."],["晩ごはんにみそ汁を飲みました。","Tôi đã uống súp miso vào bữa tối."],["みそ汁を作りました。","Tôi đã làm súp miso."],["みそ汁が好きです。","Tôi thích súp miso."]]},{"word":"おにぎり","reading":"おにぎり","meaning":"cơm nắm","hanViet":"","lesson":11,"ex":[["おにぎりを二つ作りました。","Tôi đã làm hai cái cơm nắm."],["おにぎりはおいしいです。","Cơm nắm ngon."],["昼ごはんにおにぎりを食べました。","Tôi đã ăn cơm nắm vào bữa trưa."],["おにぎりを買いにコンビニへ行きました。","Tôi đã đi cửa hàng tiện lợi để mua cơm nắm."],["おにぎりが好きです。","Tôi thích cơm nắm."]]},{"word":"うどん","reading":"うどん","meaning":"mì được làm từ bột lúa mạch","hanViet":"","lesson":11,"ex":[["昼ごはんにうどんを食べました。","Tôi đã ăn mì udon vào bữa trưa."],["うどんはおいしいです。","Mì udon ngon."],["うどんを食べたいです。","Tôi muốn ăn mì udon."],["晩ごはんにうどんを食べました。","Tôi đã ăn mì udon vào bữa tối."],["うどんを作りました。","Tôi đã làm mì udon."]]},{"word":"クラス","reading":"クラス","meaning":"lớp học","hanViet":"","lesson":11,"ex":[["クラスで日本語を勉強します。","Tôi học tiếng Nhật ở lớp."],["クラスは大きいです。","Lớp học rộng."],["クラスで日本語を話します。","Tôi nói tiếng Nhật ở lớp."],["クラスに新しい学生が来ました。","Học sinh mới đã đến lớp."],["クラスは三階にあります。","Lớp học ở tầng ba."]]},{"word":"いってきます","reading":"いってきます","meaning":"tôi đi đây","hanViet":"","lesson":11,"ex":[["学校へ行くとき、「いってきます」と言います。","Khi đi học, tôi nói “Tôi đi đây”."],["会社へ行くとき、「いってきます」と言います。","Khi đi làm, tôi nói “Tôi đi đây”."],["「いってきます」と言って、学校へ行きました。","Tôi nói “Tôi đi đây” rồi đi đến trường."],["母に「いってきます」と言いました。","Tôi đã nói “Tôi đi đây” với mẹ."],["朝、「いってきます」と言います。","Buổi sáng, tôi nói “Tôi đi đây”."]]},{"word":"サンドイッチ","reading":"サンドイッチ","meaning":"sandwich","hanViet":"","lesson":11,"ex":[["昼ごはんにサンドイッチを食べました。","Tôi đã ăn sandwich vào bữa trưa."],["サンドイッチはおいしいです。","Sandwich ngon."],["サンドイッチを食べたいです。","Tôi muốn ăn sandwich."],["サンドイッチを作りました。","Tôi đã làm sandwich."],["サンドイッチを買いにコンビニへ行きました。","Tôi đã đi cửa hàng tiện lợi để mua sandwich."]]},{"word":"カレーライス","reading":"カレーライス","meaning":"cơm ca-ri","hanViet":"","lesson":11,"ex":[["カレーライスが好きです。","Tôi thích cơm cà ri."],["カレーライスはおいしいです。","Cơm cà ri ngon."],["カレーライスを食べたいです。","Tôi muốn ăn cơm cà ri."],["昼ごはんにカレーライスを食べました。","Tôi đã ăn cơm cà ri vào bữa trưa."],["カレーライスを作りました。","Tôi đã làm cơm cà ri."]]},{"word":"アイスクリーム","reading":"アイスクリーム","meaning":"kem","hanViet":"","lesson":11,"ex":[["アイスクリームを食べたいです。","Tôi muốn ăn kem."],["アイスクリームはおいしいです。","Kem ngon."],["アイスクリームが好きです。","Tôi thích kem."],["アイスクリームを買いにコンビニへ行きました。","Tôi đã đi cửa hàng tiện lợi để mua kem."],["夏にアイスクリームを食べます。","Vào mùa hè tôi ăn kem."]]},{"word":"エアメール","reading":"エアメール","meaning":"(gửi bằng) đường hàng không","hanViet":"","lesson":11,"ex":[["この手紙はエアメールで送りました。","Tôi đã gửi bức thư này bằng đường hàng không."],["エアメールで荷物を送ります。","Tôi gửi hàng bằng đường hàng không."],["エアメールは速いです。","Đường hàng không nhanh."],["エアメールで送ってください。","Xin hãy gửi bằng đường hàng không."],["エアメールはいくらですか。","Gửi đường hàng không giá bao nhiêu?"]]},{"word":"いらっしゃいませ","reading":"いらっしゃいませ","meaning":"Xin mời vào./ xin chào quýkhách. (lời chào của người bánhàng đối với khách hàng)","hanViet":"","lesson":11,"ex":[["店に入ると、店員が「いらっしゃいませ」と言いました。","Khi vào cửa hàng, nhân viên đã nói “Xin mời vào”."],["日本の店では、店員が「いらっしゃいませ」と言います。","Ở các cửa hàng ở Nhật Bản, nhân viên nói “Xin mời vào”."],["スーパーに入ると、店員が「いらっしゃいませ」と言いました。","Khi vào siêu thị, nhân viên đã nói “Xin mời vào”."],["「いらっしゃいませ」は店で使う言葉です。","“Irasshaimase” là từ dùng ở cửa hàng."],["デパートへ行くと、店員が「いらっしゃいませ」と言います。","Khi đến cửa hàng bách hóa, nhân viên nói “Xin mời vào”."]]},{"word":"いいお天気ですね","reading":"いいおてんきですね","meaning":"trời đẹp quá nhỉ!","hanViet":"KHÍ","lesson":11,"ex":[["今日はいいお天気ですね。","Hôm nay trời đẹp quá nhỉ!"],["朝、公園で「いいお天気ですね」と言いました。","Buổi sáng ở công viên, tôi đã nói “Trời đẹp quá nhỉ!”."],["友達に会うと、「いいお天気ですね」と言います。","Khi gặp bạn, tôi nói “Trời đẹp quá nhỉ!”."],["今日はいいお天気ですね。公園で散歩しませんか。","Hôm nay trời đẹp quá nhỉ! Chúng ta đi dạo ở công viên nhé?"],["きのうはいいお天気でしたね。","Hôm qua trời đẹp quá nhỉ!"]]},{"word":"お出かけですか","reading":"おでかけですか","meaning":"Anh/ chị đi ra ngoài đấy à?","hanViet":"XUẤT","lesson":11,"ex":[["山田さんに「お出かけですか」と聞きました。","Tôi đã hỏi chị Yamada “Chị đi ra ngoài đấy à?”."],["隣の人に「お出かけですか」と聞きました。","Tôi đã hỏi người hàng xóm “Anh/chị đi ra ngoài đấy à?”."],["田中さんは「お出かけですか」と言いました。","Anh Tanaka đã nói “Anh/chị đi ra ngoài đấy à?”."],["「お出かけですか」と聞くと、「はい、ちょっと買い物へ行きます」と言いました。","Khi tôi hỏi “Chị đi ra ngoài đấy à?”, chị ấy nói “Vâng, tôi đi mua sắm một chút”."],["友達が「お出かけですか」と聞きました。","Bạn tôi đã hỏi “Bạn đi ra ngoài đấy à?”."]]},{"word":"ちょっと～まで","reading":"ちょっと～まで","meaning":"đến～một chút","hanViet":"","lesson":11,"ex":[["ちょっと郵便局まで行ってきます。","Tôi đi đến bưu điện một chút."],["ちょっと駅まで行きます。","Tôi đi đến ga một chút."],["ちょっとコンビニまで買い物に行きます。","Tôi đi mua sắm ở cửa hàng tiện lợi một chút."],["ちょっと図書館まで行って、本を返します。","Tôi đi đến thư viện một chút để trả sách."],["ちょっとスーパーまで行ってきます。","Tôi đi đến siêu thị một chút rồi về."]]},{"word":"いっていらっしゃい","reading":"いっていらっしゃい","meaning":"(anh) đi nhé (lịch sự hơn)","hanViet":"","lesson":11,"ex":[["母が「いっていらっしゃい」と言いました。","Mẹ đã nói “Đi nhé”."],["父が「いっていらっしゃい」と言いました。","Bố đã nói “Đi nhé”."],["学校へ行くとき、母が「いっていらっしゃい」と言います。","Khi tôi đi học, mẹ nói “Đi nhé”."],["会社へ行くとき、妻が「いっていらっしゃい」と言います。","Khi tôi đi làm, vợ tôi nói “Anh đi nhé”."],["母はいつも「いっていらっしゃい」と言います。","Mẹ luôn nói “Đi nhé”."]]},{"word":"いってまいります","reading":"いってまいります","meaning":"(tôi) đi đây (lịch sự hơn)","hanViet":"","lesson":11,"ex":[["会社へ行くとき、「いってまいります」と言います。","Khi đi làm, tôi nói “Tôi đi đây” (lịch sự)."],["学校へ行くとき、「いってまいります」と言います。","Khi đi học, tôi nói “Tôi đi đây”."],["朝、「いってまいります」と言って、うちを出ます。","Buổi sáng, tôi nói “Tôi đi đây” rồi ra khỏi nhà."],["出かけるとき、「いってまいります」と言います。","Khi ra ngoài, tôi nói “Tôi đi đây”."],["「いってまいります」と言って、学校へ行きました。","Tôi đã nói “Tôi đi đây” rồi đi học."]]},{"word":"留学生","reading":"りゅうがくせい","meaning":"du học sinh","hanViet":"HỌC SINH","lesson":11,"ex":[["私は留学生です。","Tôi là du học sinh."],["田中さんのクラスには留学生がたくさんいます。","Lớp của anh Tanaka có nhiều du học sinh."],["留学生は日本語を勉強します。","Du học sinh học tiếng Nhật."],["わたしの友達は留学生です。","Bạn tôi là du học sinh."],["大学にはいろいろな国の留学生がいます。","Ở trường đại học có du học sinh từ nhiều nước khác nhau."]]},{"word":"簡単","reading":"かんたん","meaning":"Đơn giản","hanViet":"GIẢN ĐƠN","lesson":12,"ex":[["この問題は簡単です。","Bài này đơn giản."],["日本語の試験は簡単でした。","Bài thi tiếng Nhật đã dễ."],["この問題は簡単ですから、すぐできます。","Bài này đơn giản nên tôi làm được ngay."],["簡単な日本語で話してください。","Hãy nói bằng tiếng Nhật đơn giản."],["ひらがなは簡単です。","Hiragana đơn giản."]]},{"word":"近い","reading":"ちかい","meaning":"Gần","hanViet":"CẬN","lesson":12,"ex":[["駅はうちから近いです。","Nhà ga gần nhà tôi."],["スーパーは駅から近いです。","Siêu thị gần ga."],["学校まで近いですか。","Đến trường có gần không?"],["このホテルは空港に近いです。","Khách sạn này gần sân bay."],["駅まで近いですから、歩いて行きます。","Vì gần ga nên tôi đi bộ."]]},{"word":"遠い","reading":"とおい","meaning":"Xa","hanViet":"VIỄN","lesson":12,"ex":[["学校はうちから遠いです。","Trường học xa nhà tôi."],["空港はうちから遠いです。","Sân bay xa nhà tôi."],["会社まで遠いですか。","Đến công ty có xa không?"],["海はここから遠いです。","Biển xa đây."],["学校まで遠いですから、電車で行きます。","Vì đến trường xa nên tôi đi bằng tàu điện."]]},{"word":"速い","reading":"はやい","meaning":"Nhanh","hanViet":"TỐC","lesson":12,"ex":[["この電車は速いです。","Tàu điện này nhanh."],["新幹線は電車より速いです。","Tàu Shinkansen nhanh hơn tàu điện."],["田中さんは速く走ります。","Anh Tanaka chạy nhanh."],["電車はバスより速いです。","Tàu điện nhanh hơn xe buýt."],["飛行機は速いですから、三時間で着きます。","Vì máy bay nhanh nên đến nơi trong ba giờ."]]},{"word":"遅い","reading":"おそい","meaning":"Chậm; muộn","hanViet":"TRÌ","lesson":12,"ex":[["この時計は遅いです。","Cái đồng hồ này chạy chậm."],["わたしの時計は少し遅いです。","Đồng hồ của tôi chạy chậm một chút."],["もう遅いですから、寝ます。","Đã muộn rồi nên tôi đi ngủ."],["このパソコンは遅いです。","Máy tính này chậm."],["きょうは遅い時間に晩ごはんを食べました。","Hôm nay tôi đã ăn tối vào giờ muộn."]]},{"word":"多い","reading":"おおい","meaning":"Nhiều","hanViet":"ĐA","lesson":12,"ex":[["この町は人が多いです。","Thị trấn này đông người."],["日本は雨が多いです。","Nhật Bản nhiều mưa."],["わたしのクラスは学生が多いです。","Lớp tôi đông học sinh."],["きょうは宿題が多いです。","Hôm nay nhiều bài tập về nhà."],["あしたは人が多いですから、早く行きます。","Ngày mai đông người nên tôi sẽ đi sớm."]]},{"word":"少ない","reading":"すくない","meaning":"Ít","hanViet":"THIẾU","lesson":12,"ex":[["わたしのクラスは人が少ないです。","Lớp của tôi ít người."],["この町は人が少ないです。","Thị trấn này ít người."],["きょうは宿題が少ないです。","Hôm nay ít bài tập về nhà."],["ベトナムは雪が少ないです。","Việt Nam ít tuyết."],["お金が少ないですから、買い物しません。","Vì ít tiền nên tôi không mua sắm."]]},{"word":"暖かい","reading":"あたたかい","meaning":"Ấm, ấm áp","hanViet":"NOÃN","lesson":12,"ex":[["春は暖かいです。","Mùa xuân ấm áp."],["きょうは暖かいです。","Hôm nay ấm áp."],["ベトナムは日本より暖かいです。","Việt Nam ấm hơn Nhật Bản."],["あしたは暖かいですから、海へ行きます。","Ngày mai ấm áp nên tôi đi biển."],["この部屋は暖かいです。","Căn phòng này ấm áp."]]},{"word":"涼しい","reading":"すずしい","meaning":"Mát mẻ","hanViet":"LƯƠNG","lesson":12,"ex":[["秋は涼しいです。","Mùa thu mát mẻ."],["きょうは涼しいです。","Hôm nay mát mẻ."],["山は涼しいですから、夏に山へ行きます。","Vì trên núi mát mẻ nên mùa hè tôi đi lên núi."],["夜は涼しいです。","Buổi tối mát mẻ."],["秋は涼しくなります。","Mùa thu trở nên mát mẻ."]]},{"word":"重い","reading":"おもい","meaning":"nặng","hanViet":"TRỌNG","lesson":12,"ex":[["このかばんは重いです。","Cái cặp này nặng."],["この本は重いです。","Cuốn sách này nặng."],["荷物が重いですから、タクシーで行きます。","Vì hành lý nặng nên tôi đi bằng taxi."],["この辞書は重いですか。","Cuốn từ điển này có nặng không?"],["重い荷物を持って、駅へ行きます。","Mang hành lý nặng, tôi đi đến ga."]]},{"word":"軽い","reading":"かるい","meaning":"Nhẹ","hanViet":"KHINH","lesson":12,"ex":[["このかばんは軽いです。","Cái cặp này nhẹ."],["この自転車は軽いです。","Chiếc xe đạp này nhẹ."],["かばんが軽いですから、歩いて行きます。","Vì cặp nhẹ nên tôi đi bộ."],["このコートは軽いですか。","Cái áo khoác này có nhẹ không?"],["軽いかばんが欲しいです。","Tôi muốn có một chiếc cặp nhẹ."]]},{"word":"季節","reading":"きせつ","meaning":"Mùa","hanViet":"QUÝ TIẾT","lesson":12,"ex":[["一番好きな季節は春です。","Mùa tôi thích nhất là mùa xuân."],["日本には四つの季節があります。","Nhật Bản có bốn mùa."],["どの季節が好きですか。","Bạn thích mùa nào?"],["夏は暑い季節です。","Mùa hè là mùa nóng."],["冬は寒い季節です。","Mùa đông là mùa lạnh."]]},{"word":"春","reading":"はる","meaning":"mùa xuân","hanViet":"XUÂN","lesson":12,"ex":[["春は桜がきれいです。","Mùa xuân hoa anh đào đẹp."],["春は暖かい季節です。","Mùa xuân là mùa ấm áp."],["春に花見をします。","Mùa xuân tôi đi ngắm hoa."],["春は桜の季節です。","Mùa xuân là mùa hoa anh đào."],["春が来ました。","Mùa xuân đã đến."]]},{"word":"夏","reading":"なつ","meaning":"Mùa hè","hanViet":"HẠ","lesson":12,"ex":[["夏は暑いです。","Mùa hè nóng."],["夏に海へ行きます。","Mùa hè tôi đi biển."],["夏は友達と海へ行きます。","Mùa hè tôi đi biển cùng bạn."],["夏は暑いですから、アイスクリームを食べます。","Vì mùa hè nóng nên tôi ăn kem."],["夏は雨が多いです。","Mùa hè nhiều mưa."]]},{"word":"秋","reading":"あき","meaning":"Mùa thu","hanViet":"THU","lesson":12,"ex":[["秋は紅葉がきれいです。","Mùa thu lá đỏ đẹp."],["秋は涼しい季節です。","Mùa thu là mùa mát mẻ."],["秋に山へ行きます。","Mùa thu tôi đi lên núi."],["秋は果物がおいしいです。","Mùa thu trái cây ngon."],["秋は短いです。","Mùa thu ngắn."]]},{"word":"冬","reading":"ふゆ","meaning":"Mùa đông","hanViet":"ĐÔNG","lesson":12,"ex":[["冬は寒いです。","Mùa đông lạnh."],["冬は寒いですから、コートを着ます。","Vì mùa đông lạnh nên tôi mặc áo khoác."],["冬にスキーをします。","Mùa đông tôi trượt tuyết."],["冬は夜が長いです。","Mùa đông đêm dài."],["冬は雪がきれいです。","Mùa đông tuyết đẹp."]]},{"word":"天気","reading":"てんき","meaning":"Thời tiết","hanViet":"THIÊN KHÍ","lesson":12,"ex":[["きょうの天気はいいです。","Thời tiết hôm nay đẹp."],["あしたの天気はどうですか。","Thời tiết ngày mai thế nào?"],["天気がいいですから、散歩します。","Vì thời tiết đẹp nên tôi đi dạo."],["きょうの天気は悪いです。","Thời tiết hôm nay xấu."],["天気が悪いですから、うちにいます。","Vì thời tiết xấu nên tôi ở nhà."]]},{"word":"雨","reading":"あめ","meaning":"Mưa","hanViet":"VŨ","lesson":12,"ex":[["あしたは雨が降ります。","Ngày mai trời mưa."],["きょうは雨が降ります。","Hôm nay trời mưa."],["雨が降りましたから、傘を買いました。","Vì trời đã mưa nên tôi đã mua ô."],["雨の日はうちにいます。","Ngày mưa tôi ở nhà."],["雨が好きではありません。","Tôi không thích mưa."]]},{"word":"雪","reading":"ゆき","meaning":"tuyết","hanViet":"TUYẾT","lesson":12,"ex":[["冬は雪が降ります。","Mùa đông tuyết rơi."],["あしたは雪が降ります。","Ngày mai tuyết rơi."],["雪が降りましたから、寒いです。","Vì tuyết đã rơi nên trời lạnh."],["雪が好きです。","Tôi thích tuyết."],["山は雪が多いです。","Trên núi nhiều tuyết."]]},{"word":"曇り","reading":"くもり","meaning":"Trời nhiều mây","hanViet":"ĐÀM","lesson":12,"ex":[["きょうは曇りです。","Hôm nay trời nhiều mây."],["あしたは曇りです。","Ngày mai trời nhiều mây."],["きょうは曇りですから、傘を持っていきます。","Vì hôm nay trời nhiều mây nên tôi mang theo ô."],["曇りの日は洗濯しません。","Ngày nhiều mây tôi không giặt quần áo."],["あしたは曇りでしょう。","Ngày mai chắc là trời nhiều mây."]]},{"word":"空港","reading":"くうこう","meaning":"Sân bay","hanViet":"KHÔNG CẢNG","lesson":12,"ex":[["空港までバスで行きます。","Tôi đi xe buýt đến sân bay."],["空港で友達を迎えます。","Tôi đón bạn ở sân bay."],["空港はここから遠いです。","Sân bay xa đây."],["空港までタクシーで行きます。","Tôi đi taxi đến sân bay."],["空港で飛行機を見ます。","Tôi ngắm máy bay ở sân bay."]]},{"word":"海","reading":"うみ","meaning":"Biển","hanViet":"HẢI","lesson":12,"ex":[["夏、海で泳ぎます。","Mùa hè tôi bơi ở biển."],["日曜日に友達と海へ行きました。","Chủ nhật tôi đã đi biển cùng bạn."],["海で泳ぎました。","Tôi đã bơi ở biển."],["海へ行きたいです。","Tôi muốn đi biển."],["海の近くにホテルがあります。","Gần biển có khách sạn."]]},{"word":"世界","reading":"せかい","meaning":"Thế giới","hanViet":"THẾ GIỚI","lesson":12,"ex":[["世界にはいろいろな国があります。","Trên thế giới có nhiều nước khác nhau."],["世界にはいろいろな食べ物があります。","Trên thế giới có nhiều món ăn khác nhau."],["世界は広いです。","Thế giới rộng lớn."],["世界の音楽が好きです。","Tôi thích âm nhạc thế giới."],["世界で日本語を勉強する人が多いです。","Trên thế giới có nhiều người học tiếng Nhật."]]},{"word":"祭り","reading":"まつり","meaning":"Lễ hội","hanViet":"TẾ","lesson":12,"ex":[["夏、日本で祭りがあります。","Mùa hè ở Nhật Bản có lễ hội."],["祭りは楽しいです。","Lễ hội vui."],["町で祭りがあります。","Ở thị trấn có lễ hội."],["祭りを見ました。","Tôi đã xem lễ hội."],["夏の祭りが好きです。","Tôi thích lễ hội mùa hè."]]},{"word":"試験","reading":"しけん","meaning":"Kỳ thi, bài kiểm tra","hanViet":"THÍ NGHIỆM","lesson":12,"ex":[["あした、試験があります。","Ngày mai có bài kiểm tra."],["試験は難しいです。","Bài thi khó."],["試験はいつですか。","Kỳ thi khi nào?"],["試験の前に勉強します。","Trước kỳ thi tôi học bài."],["試験が終わりました。","Kỳ thi đã kết thúc."]]},{"word":"生け花","reading":"いけばな","meaning":"Nghệ thuật cắm hoa (～をします：cắm hoa)","hanViet":"SINH HOA","lesson":12,"ex":[["母は生け花をします。","Mẹ tôi cắm hoa."],["生け花が好きです。","Tôi thích cắm hoa."],["母は生け花が上手です。","Mẹ tôi cắm hoa giỏi."],["生け花を習います。","Tôi học cắm hoa."],["生け花をしました。","Tôi đã cắm hoa."]]},{"word":"紅葉","reading":"もみじ","meaning":"lá đỏ mùa thu","hanViet":"HỒNG DIỆP","lesson":12,"ex":[["秋は山で紅葉を見ます。","Mùa thu tôi ngắm lá đỏ trên núi."],["紅葉はきれいです。","Lá đỏ đẹp."],["山で紅葉を見ました。","Tôi đã ngắm lá đỏ trên núi."],["秋の紅葉が好きです。","Tôi thích lá đỏ mùa thu."],["紅葉の写真を撮りました。","Tôi đã chụp ảnh lá đỏ."]]},{"word":"どちらも","reading":"どちらも","meaning":"cả hai","hanViet":"","lesson":12,"ex":[["すしと天ぷらはどちらも好きです。","Tôi thích cả sushi lẫn tempura."],["父と母はどちらも元気です。","Cả bố và mẹ đều khỏe."],["日本語と英語はどちらも難しいです。","Cả tiếng Nhật và tiếng Anh đều khó."],["この本とあの本はどちらもおもしろいです。","Cả cuốn sách này và cuốn sách kia đều thú vị."],["肉も魚もどちらも食べません。","Tôi không ăn cả thịt lẫn cá."]]},{"word":"ずっと","reading":"ずっと","meaning":"(hơn) hẳn (dùng để nhấn mạnh sự khác biệt giữa hai đối tượng)","hanViet":"","lesson":12,"ex":[["日本はベトナムよりずっと寒いです。","Nhật Bản lạnh hơn Việt Nam hẳn."],["新幹線のほうがバスよりずっと速いです。","Tàu Shinkansen nhanh hơn xe buýt hẳn."],["この本はあの本よりずっとおもしろいです。","Cuốn sách này thú vị hơn cuốn sách kia hẳn."],["夏は春よりずっと暑いです。","Mùa hè nóng hơn mùa xuân hẳn."],["冬は秋よりずっと寒いです。","Mùa đông lạnh hơn mùa thu hẳn."]]},{"word":"ただいま","reading":"ただいま","meaning":"Tôi đã về đây. (dùng nói khi về đến nhà)","hanViet":"","lesson":12,"ex":[["ただいま。","Tôi đã về đây."],["うちに帰ると、「ただいま」と言います。","Khi về nhà, tôi nói “Tôi đã về đây”."],["「ただいま」と言って、うちに入りました。","Tôi đã nói “Tôi đã về đây” rồi đi vào nhà."],["学校から帰ると、「ただいま」と言いました。","Khi từ trường về, tôi đã nói “Tôi đã về đây”."],["夜、うちに帰って、「ただいま」と言います。","Buổi tối, tôi về nhà và nói “Tôi đã về đây”."]]},{"word":"お帰りなさい","reading":"おかえになさい","meaning":"Anh/Chị đã về đấy à.","hanViet":"QUY","lesson":12,"ex":[["お帰りなさい。","Anh/chị đã về đấy à."],["母が「お帰りなさい」と言いました。","Mẹ đã nói “Con đã về đấy à”."],["うちに帰ると、母が「お帰りなさい」と言います。","Khi tôi về nhà, mẹ nói “Con đã về đấy à”."],["父は「お帰りなさい」と言いました。","Bố đã nói “Con đã về đấy à”."],["「お帰りなさい」と言って、母はごはんを作りました。","Mẹ nói “Con đã về đấy à” rồi nấu cơm."]]},{"word":"でも","reading":"でも","meaning":"Nhưng","hanViet":"","lesson":12,"ex":[["きょうは雨です。でも、学校へ行きます。","Hôm nay trời mưa. Nhưng tôi vẫn đi học."],["日本語は難しいです。でも、楽しいです。","Tiếng Nhật khó. Nhưng thú vị."],["きょうは寒いです。でも、散歩します。","Hôm nay lạnh. Nhưng tôi vẫn đi dạo."],["この本は高いです。でも、買います。","Cuốn sách này đắt. Nhưng tôi vẫn mua."],["あしたは休みです。でも、うちにいます。","Ngày mai là ngày nghỉ. Nhưng tôi ở nhà."]]},{"word":"疲れました","reading":"つかれました","meaning":"Mệt, mệt mỏi","hanViet":"BÌ","lesson":12,"ex":[["きょうはたくさん歩きました。疲れました。","Hôm nay tôi đã đi bộ nhiều. Tôi mệt rồi."],["たくさん勉強しました。疲れました。","Tôi đã học nhiều. Tôi mệt rồi."],["きょうは仕事で疲れました。","Hôm nay tôi mệt vì công việc."],["山に登って、疲れました。","Tôi đã leo núi nên mệt."],["試験のあとで、疲れました。","Sau kỳ thi, tôi mệt rồi."]]},{"word":"レモン","reading":"レモン","meaning":"quả chanh","hanViet":"","lesson":12,"ex":[["レモンはすっぱいです。","Chanh chua."],["レモンは黄色いです。","Chanh màu vàng."],["レモンを買いました。","Tôi đã mua chanh."],["紅茶にレモンを入れます。","Tôi cho chanh vào trà."],["レモンが好きです。","Tôi thích chanh."]]},{"word":"牛肉","reading":"ぎゅうにく","meaning":"Thịt bò","hanViet":"NGƯU NHỤC","lesson":12,"ex":[["すき焼きは牛肉の料理です。","Sukiyaki là món ăn từ thịt bò."],["牛肉は高いです。","Thịt bò đắt."],["牛肉を買いました。","Tôi đã mua thịt bò."],["牛肉が好きです。","Tôi thích thịt bò."],["牛肉は豚肉より高いです。","Thịt bò đắt hơn thịt lợn."]]},{"word":"豚肉","reading":"ぶたにく","meaning":"Thịt lợn","hanViet":"TRƯ NHỤC","lesson":12,"ex":[["豚肉は牛肉より安いです。","Thịt lợn rẻ hơn thịt bò."],["豚肉は安いです。","Thịt lợn rẻ."],["豚肉の料理を作ります。","Tôi nấu món thịt lợn."],["豚肉が好きではありません。","Tôi không thích thịt lợn."],["豚肉を食べました。","Tôi đã ăn thịt lợn."]]},{"word":"鶏肉","reading":"とりにく","meaning":"Thịt gà","hanViet":"KÊ NHỤC","lesson":12,"ex":[["きょうの晩ごはんは鶏肉です。","Bữa tối hôm nay là thịt gà."],["鶏肉は安いです。","Thịt gà rẻ."],["鶏肉が好きです。","Tôi thích thịt gà."],["鶏肉を買いました。","Tôi đã mua thịt gà."],["鶏肉の料理を作りました。","Tôi đã nấu món thịt gà."]]},{"word":"一番","reading":"いちばん","meaning":"Số một, nhất","hanViet":"NHẤT BẢN","lesson":12,"ex":[["一番好きな食べ物はすしです。","Món ăn tôi thích nhất là sushi."],["一番安い本はどれですか。","Cuốn sách rẻ nhất là cuốn nào?"],["この店で一番おいしい料理は何ですか。","Món ăn ngon nhất ở cửa hàng này là món gì?"],["一番前に座ります。","Tôi ngồi ở phía trước nhất."],["一番好きな歌は何ですか。","Bài hát bạn thích nhất là bài gì?"]]},{"word":"温かい","reading":"あたたかい","meaning":"Ấm, ấm áp","hanViet":"ÔN","lesson":12,"ex":[["このお茶は温かいです。","Trà này ấm."],["このみそ汁は温かいです。","Món súp miso này ấm."],["温かいお茶を飲みます。","Tôi uống trà ấm."],["温かいお風呂に入ります。","Tôi tắm bồn nước ấm."],["温かいごはんが好きです。","Tôi thích cơm ấm."]]},{"word":"ホテル","reading":"ホテル","meaning":"khách sạn","hanViet":"","lesson":12,"ex":[["ホテルに泊まります。","Tôi ở khách sạn."],["ホテルは駅の近くにあります。","Khách sạn ở gần ga."],["このホテルは高いです。","Khách sạn này đắt."],["ホテルに泊まりました。","Tôi đã ở khách sạn."],["駅の近くに新しいホテルがあります。","Gần ga có khách sạn mới."]]},{"word":"パーティー","reading":"パーティー","meaning":"tiệc (~をします：tổ chức tiệc)","hanViet":"","lesson":12,"ex":[["土曜日にパーティーをします。","Thứ bảy tôi tổ chức tiệc."],["パーティーに友達が来ます。","Bạn bè đến bữa tiệc."],["誕生日にパーティーをします。","Vào sinh nhật tôi tổ chức tiệc."],["パーティーは楽しいです。","Bữa tiệc vui."],["パーティーで歌を歌います。","Ở bữa tiệc tôi hát."]]},{"word":"すき焼き","reading":"すきやき","meaning":"Sukiyaki (món thịt bò nấu rau)","hanViet":"","lesson":12,"ex":[["すき焼きはおいしいです。","Sukiyaki ngon."],["レストランですき焼きを食べました。","Tôi đã ăn sukiyaki ở nhà hàng."],["すき焼きは日本の料理です。","Sukiyaki là món ăn Nhật Bản."],["すき焼きが好きです。","Tôi thích sukiyaki."],["すき焼きを作ります。","Tôi nấu sukiyaki."]]},{"word":"刺身","reading":"さしみ","meaning":"Sashimi, cá sống thái lát","hanViet":"THÍCH THÂN","lesson":12,"ex":[["刺身は魚の料理です。","Sashimi là món ăn từ cá."],["刺身を食べました。","Tôi đã ăn sashimi."],["刺身が好きです。","Tôi thích sashimi."],["刺身はおいしいです。","Sashimi ngon."],["初めて刺身を食べました。","Tôi đã ăn sashimi lần đầu tiên."]]},{"word":"寿司","reading":"すし","meaning":"sushi","hanViet":"THỌ TƯ","lesson":12,"ex":[["日本で寿司を食べました。","Tôi đã ăn sushi ở Nhật Bản."],["寿司が好きです。","Tôi thích sushi."],["日曜日に母と寿司を食べに行きます。","Chủ nhật tôi đi ăn sushi cùng mẹ."],["寿司を作ります。","Tôi làm sushi."],["寿司を食べたいです。","Tôi muốn ăn sushi."]]},{"word":"天ぷら","reading":"てんぷら","meaning":"Tempura (món hải sản và rau chiên tẩm bột","hanViet":"","lesson":12,"ex":[["きょうの晩ごはんは天ぷらです。","Bữa tối hôm nay là tempura."],["天ぷらが好きです。","Tôi thích tempura."],["天ぷらはおいしいです。","Tempura ngon."],["天ぷらを食べました。","Tôi đã ăn tempura."],["天ぷらは魚と野菜の料理です。","Tempura là món ăn từ cá và rau."]]},{"word":"初めて","reading":"はじめて","meaning":"lần đầu tiên","hanViet":"SƠ","lesson":12,"ex":[["初めてすしを食べました。","Tôi đã ăn sushi lần đầu tiên."],["初めて日本へ行きました。","Tôi đã đi Nhật lần đầu tiên."],["初めてスキーをしました。","Tôi đã trượt tuyết lần đầu tiên."],["初めて飛行機に乗りました。","Tôi đã đi máy bay lần đầu tiên."],["初めて日本語で話しました。","Tôi đã nói bằng tiếng Nhật lần đầu tiên."]]},{"word":"遊びます","reading":"あそびます","meaning":"Chơi, vui chơi","hanViet":"DU","lesson":13,"ex":[["子どもは公園で遊びます。","Trẻ em chơi ở công viên."],["子どもはうちで遊びます。","Trẻ em chơi ở nhà."],["友達と公園で遊びました。","Tôi đã chơi với bạn ở công viên."],["日曜日に友達と遊びます。","Chủ nhật tôi chơi với bạn."],["子どもはプールで遊びます。","Trẻ em chơi ở bể bơi."]]},{"word":"泳ぎます","reading":"およぎます","meaning":"Bơi","hanViet":"VỊNH","lesson":13,"ex":[["私は海で泳ぎます。","Tôi bơi ở biển."],["弟はプールで泳ぐことができます。","Em trai tôi có thể bơi ở bể bơi."],["川で泳ぎました。","Tôi đã bơi ở sông."],["子どもは速く泳ぎます。","Trẻ em bơi nhanh."],["海で泳ぎたいです。","Tôi muốn bơi ở biển."]]},{"word":"迎えます","reading":"むかえます","meaning":"Đón, tiếp đón","hanViet":"NGHÊNH","lesson":13,"ex":[["駅で友達を迎えます。","Tôi đón bạn ở ga."],["空港で母を迎えます。","Tôi đón mẹ ở sân bay."],["駅で先生を迎えます。","Tôi đón thầy ở ga."],["友達を迎えました。","Tôi đã đón bạn."],["空港で家族を迎えました。","Tôi đã đón gia đình ở sân bay."]]},{"word":"疲れます","reading":"つかれます","meaning":"Mệt, mệt mỏi","hanViet":"BÌ","lesson":13,"ex":[["たくさん歩きましたから、疲れました。","Vì đã đi bộ nhiều nên tôi mệt."],["たくさん歩くと、疲れます。","Nếu đi bộ nhiều, tôi sẽ mệt."],["仕事で疲れます。","Tôi mệt vì công việc."],["長い時間勉強すると、疲れます。","Nếu học trong thời gian dài, tôi sẽ mệt."],["たくさん泳ぐと、疲れます。","Nếu bơi nhiều, tôi sẽ mệt."]]},{"word":"出します","reading":"だします","meaning":"gửi[thư]","hanViet":"XUẤT","lesson":13,"ex":[["郵便局で手紙を出します。","Tôi gửi thư ở bưu điện."],["手紙を出しました。","Tôi đã gửi thư."],["ポストで手紙を出します。","Tôi gửi thư ở hòm thư."],["友達に手紙を出します。","Tôi gửi thư cho bạn."],["手紙を出したいです。","Tôi muốn gửi thư."]]},{"word":"入ります","reading":"はいります","meaning":"Đi vào","hanViet":"NHẬP","lesson":13,"ex":[["教室に入ります。","Tôi đi vào lớp học."],["部屋に入ります。","Tôi đi vào phòng."],["夜九時にお風呂に入ります。","9 giờ tối tôi đi tắm."],["学校に入ります。","Tôi vào trường."],["店に入りました。","Tôi đã vào cửa hàng."]]},{"word":"出ます","reading":"でます","meaning":"Đi ra, ra ngoài","hanViet":"XUẤT","lesson":13,"ex":[["学校を出ます。","Tôi ra khỏi trường."],["部屋を出ます。","Tôi ra khỏi phòng."],["朝八時にうちを出ます。","Buổi sáng tám giờ tôi ra khỏi nhà."],["教室を出ました。","Tôi đã ra khỏi lớp học."],["駅を出ます。","Tôi ra khỏi ga."]]},{"word":"結婚します","reading":"けっこんします","meaning":"kết hôn, lập gia đình, cưới","hanViet":"KẾT HÔN","lesson":13,"ex":[["来年、田中さんは結婚します。","Sang năm, anh Tanaka sẽ kết hôn."],["姉は来年結婚します。","Chị gái tôi sẽ kết hôn vào năm sau."],["田中さんは去年結婚しました。","Anh Tanaka đã kết hôn năm ngoái."],["友達は結婚しました。","Bạn tôi đã kết hôn."],["来年結婚したいです。","Tôi muốn kết hôn vào năm sau."]]},{"word":"買い物します","reading":"かいものします","meaning":"mua hàng","hanViet":"MÃI VẬT","lesson":13,"ex":[["日曜日にデパートで買い物します。","Chủ nhật tôi mua hàng ở cửa hàng bách hóa."],["土曜日にスーパーで買い物します。","Thứ bảy tôi mua hàng ở siêu thị."],["友達と買い物します。","Tôi mua hàng với bạn."],["きのうデパートで買い物しました。","Hôm qua tôi đã mua hàng ở cửa hàng bách hóa."],["買い物したいです。","Tôi muốn mua hàng."]]},{"word":"食事します","reading":"しょくじします","meaning":"ăn cơm","hanViet":"THỰC","lesson":13,"ex":[["友達とレストランで食事します。","Tôi ăn cơm với bạn ở nhà hàng."],["家族と食事します。","Tôi ăn cơm với gia đình."],["昼にレストランで食事します。","Buổi trưa tôi ăn cơm ở nhà hàng."],["友達と食事しました。","Tôi đã ăn cơm với bạn."],["レストランで食事したいです。","Tôi muốn ăn cơm ở nhà hàng."]]},{"word":"散歩します","reading":"さんぽします","meaning":"đi dạo [ở công viên]","hanViet":"TẢN BỘ CÔNG VIÊN","lesson":13,"ex":[["朝、公園で散歩します。","Buổi sáng tôi đi dạo ở công viên."],["夜、公園で散歩します。","Buổi tối tôi đi dạo ở công viên."],["毎朝公園で散歩します。","Mỗi sáng tôi đi dạo ở công viên."],["毎日散歩します。","Mỗi ngày tôi đi dạo."],["海で散歩しました。","Tôi đã đi dạo ở biển."]]},{"word":"大変","reading":"たいへん","meaning":"Rất, vô cùng; vất vả, khó khăn","hanViet":"ĐẠI BIẾN","lesson":13,"ex":[["今日は大変暑いです。","Hôm nay rất nóng."],["今日は大変寒いです。","Hôm nay rất lạnh."],["仕事は大変です。","Công việc vất vả."],["日本語の勉強は大変です。","Việc học tiếng Nhật vất vả."],["試験は大変でした。","Kỳ thi đã vất vả."]]},{"word":"欲しい","reading":"ほしい","meaning":"muốn có","hanViet":"DỤC","lesson":13,"ex":[["新しい自転車が欲しいです。","Tôi muốn có một chiếc xe đạp mới."],["新しい本が欲しいです。","Tôi muốn có cuốn sách mới."],["車が欲しいです。","Tôi muốn có ô tô."],["お金が欲しいです。","Tôi muốn có tiền."],["何が欲しいですか。","Bạn muốn có cái gì?"]]},{"word":"寂しい","reading":"さびしい","meaning":"buồn, cô đơn, vắng vẻ","hanViet":"TỊCH","lesson":13,"ex":[["一人でいると、寂しいです。","Khi ở một mình, tôi thấy cô đơn."],["友達がいないと、寂しいです。","Nếu không có bạn, tôi thấy cô đơn."],["夜は寂しいです。","Buổi tối tôi thấy cô đơn."],["町は寂しいです。","Thị trấn vắng vẻ."],["一人でごはんを食べると、寂しいです。","Khi ăn cơm một mình, tôi thấy cô đơn."]]},{"word":"広い","reading":"ひろい","meaning":"Rộng, rộng rãi","hanViet":"QUẢNG","lesson":13,"ex":[["この部屋は広いです。","Căn phòng này rộng."],["この公園は広いです。","Công viên này rộng."],["部屋は広いですから、友達を呼びます。","Vì phòng rộng nên tôi mời bạn đến."],["この学校は広いです。","Trường này rộng."],["広い部屋が欲しいです。","Tôi muốn có căn phòng rộng."]]},{"word":"狭い","reading":"せまい","meaning":"hẹp, chật hẹp","hanViet":"HIỆP","lesson":13,"ex":[["この部屋は狭いです。","Căn phòng này hẹp."],["この道は狭いです。","Con đường này hẹp."],["部屋は狭いですから、大きい机は置きません。","Vì phòng hẹp nên tôi không đặt bàn lớn."],["この教室は狭いです。","Lớp học này hẹp."],["狭い部屋に住んでいます。","Tôi đang sống trong căn phòng hẹp."]]},{"word":"市役所","reading":"しやくしょ","meaning":"Toà thị chính, UBND thành phố","hanViet":"THỊ DỊCH SỞ","lesson":13,"ex":[["市役所は駅の近くにあります。","Tòa thị chính ở gần ga."],["市役所へ行きます。","Tôi đi đến tòa thị chính."],["市役所で働きます。","Tôi làm việc ở tòa thị chính."],["市役所はここから近いです。","Tòa thị chính gần đây."],["市役所へ行って、登録をします。","Tôi đến tòa thị chính để đăng ký."]]},{"word":"経済","reading":"けいざい","meaning":"Kinh tế","hanViet":"KINH TẾ","lesson":13,"ex":[["大学で経済を勉強します。","Tôi học kinh tế ở trường đại học."],["経済が好きです。","Tôi thích kinh tế."],["経済を勉強しています。","Tôi đang học kinh tế."],["経済の本を読みます。","Tôi đọc sách kinh tế."],["大学で経済を勉強しました。","Tôi đã học kinh tế ở trường đại học."]]},{"word":"美術","reading":"びじゅつ","meaning":"Mỹ thuật","hanViet":"MỸ THUẬT","lesson":13,"ex":[["私は美術が好きです。","Tôi thích mỹ thuật."],["美術館で美術を見ます。","Tôi xem mỹ thuật ở bảo tàng mỹ thuật."],["美術を勉強します。","Tôi học mỹ thuật."],["美術の本を読みます。","Tôi đọc sách mỹ thuật."],["美術が上手です。","Tôi giỏi mỹ thuật."]]},{"word":"釣り","reading":"つり","meaning":"việc câu cá","hanViet":"ĐIẾU","lesson":13,"ex":[["日曜日に川で釣りをします。","Chủ nhật tôi câu cá ở sông."],["釣りが好きです。","Tôi thích câu cá."],["海で釣りをします。","Tôi câu cá ở biển."],["きのう川で釣りをしました。","Hôm qua tôi đã câu cá ở sông."],["週末に釣りをします。","Cuối tuần tôi câu cá."]]},{"word":"会議","reading":"かいぎ","meaning":"Cuộc họp, hội nghị","hanViet":"HỘI NGHỊ","lesson":13,"ex":[["午後三時に会議があります。","Ba giờ chiều có cuộc họp."],["会議は十時です。","Cuộc họp lúc mười giờ."],["会議室で会議をします。","Tôi họp ở phòng họp."],["会議が終わりました。","Cuộc họp đã kết thúc."],["あした会議があります。","Ngày mai có cuộc họp."]]},{"word":"登録","reading":"とうろく","meaning":"Đăng ký","hanViet":"ĐĂNG LỤC","lesson":13,"ex":[["ここで登録ができます。","Bạn có thể đăng ký ở đây."],["市役所で登録をします。","Tôi đăng ký ở tòa thị chính."],["学校で登録をしました。","Tôi đã đăng ký ở trường."],["登録ができますか。","Tôi có thể đăng ký không?"],["ここで登録をしてください。","Hãy đăng ký ở đây."]]},{"word":"週末","reading":"しゅうまつ","meaning":"Cuối tuần","hanViet":"CHU MẠT","lesson":13,"ex":[["週末に友達と遊びます。","Cuối tuần tôi chơi với bạn."],["週末に買い物します。","Cuối tuần tôi mua sắm."],["週末はうちにいます。","Cuối tuần tôi ở nhà."],["週末に映画を見ます。","Cuối tuần tôi xem phim."],["週末に旅行に行きます。","Cuối tuần tôi đi du lịch."]]},{"word":"何か","reading":"なにか","meaning":"Cái gì đó","hanViet":"HÀ CẢ","lesson":13,"ex":[["何か食べたいです。","Tôi muốn ăn cái gì đó."],["何か飲みたいです。","Tôi muốn uống cái gì đó."],["何か買いました。","Tôi đã mua cái gì đó."],["何か食べますか。","Bạn có muốn ăn gì đó không?"],["何か読みたいです。","Tôi muốn đọc cái gì đó."]]},{"word":"どこか","reading":"どこか","meaning":"đâu đó, chỗ nào đó","hanViet":"","lesson":13,"ex":[["どこかでコーヒーを飲みたいです。","Tôi muốn uống cà phê ở đâu đó."],["どこかでごはんを食べたいです。","Tôi muốn ăn cơm ở đâu đó."],["どこかへ行きたいです。","Tôi muốn đi đâu đó."],["どこかで休みたいです。","Tôi muốn nghỉ ở đâu đó."],["どこか静かな所で勉強したいです。","Tôi muốn học ở một nơi yên tĩnh nào đó."]]},{"word":"おなかがすきました","reading":"おなかがすきました","meaning":"(tôi) đói rồi.","hanViet":"","lesson":13,"ex":[["おなかがすきましたから、ごはんを食べます。","Vì đói rồi nên tôi ăn cơm."],["おなかがすきました。ごはんを食べましょうか。","Tôi đói rồi. Chúng ta ăn cơm nhé?"],["たくさん歩きました。おなかがすきました。","Tôi đã đi bộ nhiều. Tôi đói rồi."],["おなかがすきましたから、パンを食べます。","Vì đói rồi nên tôi ăn bánh mì."],["おなかがすきましたか。","Bạn đói chưa?"]]},{"word":"おなかがいっぱいです","reading":"おなかがいっぱいです","meaning":"(tôi) no rồi.","hanViet":"","lesson":13,"ex":[["ごはんをたくさん食べましたから、おなかがいっぱいです。","Vì đã ăn nhiều cơm nên tôi no rồi."],["すしをたくさん食べました。おなかがいっぱいです。","Tôi đã ăn nhiều sushi. Tôi no rồi."],["おなかがいっぱいですから、もう食べません。","Vì no rồi nên tôi không ăn nữa."],["おなかがいっぱいですか。","Bạn no chưa?"],["もうおなかがいっぱいです。","Tôi đã no rồi."]]},{"word":"のどがかわきました","reading":"のどがかわきました","meaning":"(tôi) khát.","hanViet":"","lesson":13,"ex":[["暑いですから、のどがかわきました。","Vì nóng nên tôi khát."],["泳ぎましたから、のどがかわきました。","Vì đã bơi nên tôi khát."],["たくさん歩きましたから、のどがかわきました。","Vì đã đi bộ nhiều nên tôi khát."],["のどがかわきましたから、お茶を飲みます。","Vì khát nên tôi uống trà."],["のどがかわきました。ジュースをください。","Tôi khát. Cho tôi nước trái cây."]]},{"word":"定食","reading":"ていしょく","meaning":"Suất ăn theo set, cơm phần","hanViet":"ĐỊNH THỰC","lesson":13,"ex":[["昼ごはんに定食を食べます。","Bữa trưa tôi ăn cơm phần."],["このレストランの定食はおいしいです。","Cơm phần ở nhà hàng này ngon."],["定食はごはんとみそ汁です。","Cơm phần gồm cơm và súp miso."],["晩ごはんに定食を食べました。","Bữa tối tôi đã ăn cơm phần."],["定食はいくらですか。","Cơm phần bao nhiêu tiền?"]]},{"word":"別々に","reading":"べつべつに","meaning":"để riêng ra","hanViet":"BIỆT","lesson":13,"ex":[["別々に払います。","Chúng tôi trả riêng ra."],["荷物を別々に持ちます。","Chúng tôi mang hành lý riêng ra."],["友達と別々に帰りました。","Tôi và bạn đã về riêng."],["切符を別々に買いました。","Chúng tôi đã mua vé riêng ra."],["別々に座ってもいいですか。","Ngồi riêng có được không?"]]},{"word":"博物館","reading":"はくぶつかん","meaning":"bảo tàng","hanViet":"BÁC VẬT QUÁN","lesson":13,"ex":[["日曜日に博物館へ行きます。","Chủ nhật tôi đi bảo tàng."],["博物館で古い絵を見ました。","Tôi đã xem tranh cổ ở bảo tàng."],["博物館は公園の近くにあります。","Bảo tàng ở gần công viên."],["博物館は九時から五時までです。","Bảo tàng mở cửa từ 9 giờ đến 5 giờ."],["博物館で写真を撮りました。","Tôi đã chụp ảnh ở bảo tàng."]]},{"word":"映画館","reading":"えいがかん","meaning":"rạp chiếu phim","hanViet":"ÁNH HỌA QUÁN","lesson":13,"ex":[["映画館で映画を見ます。","Tôi xem phim ở rạp chiếu phim."],["映画館で新しい映画を見ました。","Tôi đã xem phim mới ở rạp chiếu phim."],["映画館はデパートの近くにあります。","Rạp chiếu phim ở gần trung tâm thương mại."],["土曜日に友達と映画館へ行きます。","Thứ bảy tôi đi rạp chiếu phim với bạn."],["映画館の前に人がたくさんいます。","Trước rạp chiếu phim có nhiều người."]]},{"word":"動物園","reading":"どうぶつえん","meaning":"Vườn thú, sở thú","hanViet":"ĐỘNG VẬT VIÊN","lesson":13,"ex":[["動物園にパンダがいます。","Ở vườn thú có gấu trúc."],["動物園で象を見ました。","Tôi đã xem voi ở vườn thú."],["子どもと動物園へ行きます。","Tôi đi vườn thú với con."],["動物園は山の近くにあります。","Vườn thú ở gần núi."],["日曜日に動物園で写真を撮ります。","Chủ nhật tôi chụp ảnh ở vườn thú."]]},{"word":"植物園","reading":"しょくぶつえん","meaning":"Vườn bách thảo","hanViet":"VẬT","lesson":13,"ex":[["植物園で花を見ます。","Tôi ngắm hoa ở vườn bách thảo."],["植物園で桜を見ました。","Tôi đã ngắm hoa anh đào ở vườn bách thảo."],["春に植物園へ行きます。","Mùa xuân tôi đi vườn bách thảo."],["植物園は静かです。","Vườn bách thảo yên tĩnh."],["植物園で紅葉を見ました。","Tôi đã ngắm lá đỏ ở vườn bách thảo."]]},{"word":"教会","reading":"きょうかい","meaning":"nhà thờ","hanViet":"","lesson":13,"ex":[["教会は駅の近くにあります。","Nhà thờ ở gần ga."],["日曜日に教会へ行きます。","Chủ nhật tôi đi nhà thờ."],["教会は山の上にあります。","Nhà thờ ở trên núi."],["教会の前に広い庭があります。","Trước nhà thờ có sân rộng."],["教会で音楽を聞きました。","Tôi đã nghe nhạc ở nhà thờ."]]},{"word":"体育館","reading":"たいくかん","meaning":"nhà thể dục thể thao","hanViet":"THỂ","lesson":13,"ex":[["体育館でテニスをします。","Tôi chơi tennis ở nhà thể dục thể thao."],["体育館で卓球をします。","Tôi chơi bóng bàn ở nhà thể dục thể thao."],["体育館は学校の近くにあります。","Nhà thể dục thể thao ở gần trường học."],["体育館で柔道をします。","Tôi tập judo ở nhà thể dục thể thao."],["体育館で試合がありました。","Ở nhà thể dục thể thao đã có trận đấu."]]},{"word":"大使館","reading":"たいしかん","meaning":"đại sứ quán","hanViet":"ĐẠI","lesson":13,"ex":[["大使館でビザをもらいます。","Tôi nhận visa ở đại sứ quán."],["大使館はどこですか。","Đại sứ quán ở đâu?"],["大使館でパスポートを見せました。","Tôi đã trình hộ chiếu ở đại sứ quán."],["ベトナムの大使館はここですか。","Đại sứ quán Việt Nam ở đây phải không?"],["大使館へ電話しました。","Tôi đã gọi điện cho đại sứ quán."]]},{"word":"入国管理局","reading":"にゅうこくかんりきょく","meaning":"cục xuất nhập cảnh","hanViet":"NHẬP","lesson":13,"ex":[["入国管理局は市役所の近くにあります。","Cục xuất nhập cảnh ở gần tòa thị chính."],["入国管理局でビザをもらいました。","Tôi đã nhận visa ở cục xuất nhập cảnh."],["入国管理局は駅から遠いです。","Cục xuất nhập cảnh xa ga."],["パスポートを持って、入国管理局へ行きます。","Tôi mang hộ chiếu đi cục xuất nhập cảnh."],["入国管理局は九時からです。","Cục xuất nhập cảnh mở cửa từ 9 giờ."]]},{"word":"交番","reading":"こうばん","meaning":"bốt cảnh sát","hanViet":"","lesson":13,"ex":[["交番は駅の前にあります。","Bốt cảnh sát ở trước ga."],["交番で道を聞きました。","Tôi đã hỏi đường ở bốt cảnh sát."],["交番はどこですか。","Bốt cảnh sát ở đâu?"],["交番の前に警察官がいます。","Trước bốt cảnh sát có cảnh sát."],["かばんをなくしましたから、交番へ行きます。","Vì mất cặp nên tôi đi bốt cảnh sát."]]},{"word":"高校","reading":"こうこう","meaning":"Trường cấp 3","hanViet":"CAO ĐẲNG HỌC HIỆU","lesson":13,"ex":[["弟は高校で勉強します。","Em trai tôi học ở trường cấp 3."],["高校は駅の近くにあります。","Trường cấp 3 ở gần ga."],["兄は高校の先生です。","Anh trai tôi là giáo viên trường cấp 3."],["高校でテニスをしました。","Tôi đã chơi tennis ở trường cấp 3."],["高校へ自転車で行きます。","Tôi đi xe đạp đến trường cấp 3."]]},{"word":"中学校","reading":"ちゅうがっこう","meaning":"Trường cấp 2","hanViet":"TRUNG HỌC HIỆU","lesson":13,"ex":[["妹は中学校で勉強します。","Em gái tôi học ở trường cấp 2."],["中学校はうちの近くにあります。","Trường cấp 2 ở gần nhà tôi."],["中学校で英語を勉強します。","Tôi học tiếng Anh ở trường cấp 2."],["弟は中学校の学生です。","Em trai tôi là học sinh trường cấp 2."],["中学校へ歩いて行きます。","Tôi đi bộ đến trường cấp 2."]]},{"word":"小学校","reading":"しょうがっこう","meaning":"Trường tiểu học","hanViet":"TIỂU HỌC HIỆU","lesson":13,"ex":[["子どもは小学校へ行きます。","Trẻ em đi đến trường tiểu học."],["小学校は公園の近くにあります。","Trường tiểu học ở gần công viên."],["子どもは小学校で日本語を勉強します。","Trẻ em học tiếng Nhật ở trường tiểu học."],["小学校の前に桜があります。","Trước trường tiểu học có cây anh đào."],["小学校へバスで行きます。","Tôi đi xe buýt đến trường tiểu học."]]},{"word":"幼稚園","reading":"ようちえん","meaning":"Trường mẫu giáo","hanViet":"ẤU TRĨ VIÊN","lesson":13,"ex":[["幼稚園はうちの近くにあります。","Trường mẫu giáo ở gần nhà tôi."],["子どもは幼稚園で遊びます。","Trẻ em chơi ở trường mẫu giáo."],["幼稚園へ子どもを連れて行きます。","Tôi đưa con đi trường mẫu giáo."],["幼稚園は小学校の近くにあります。","Trường mẫu giáo ở gần trường tiểu học."],["幼稚園で歌を歌います。","Tôi hát ở trường mẫu giáo."]]},{"word":"肉や","reading":"にくや","meaning":"Cửa hàng thịt","hanViet":"NHỤC","lesson":13,"ex":[["肉やで牛肉を買います。","Tôi mua thịt bò ở cửa hàng thịt."],["肉やで豚肉を買いました。","Tôi đã mua thịt lợn ở cửa hàng thịt."],["肉やは駅の前にあります。","Cửa hàng thịt ở trước ga."],["肉やで鶏肉を買います。","Tôi mua thịt gà ở cửa hàng thịt."],["肉やは日曜日は休みです。","Cửa hàng thịt nghỉ chủ nhật."]]},{"word":"魚屋","reading":"さかなや","meaning":"Hàng cá","hanViet":"NGƯ ỐC","lesson":13,"ex":[["魚屋で魚を買います。","Tôi mua cá ở hàng cá."],["魚屋で刺身を買いました。","Tôi đã mua sashimi ở hàng cá."],["魚屋はスーパーの近くにあります。","Hàng cá ở gần siêu thị."],["魚屋で魚を買って、うちで食べます。","Tôi mua cá ở hàng cá rồi ăn ở nhà."],["魚屋は朝八時からです。","Hàng cá mở cửa từ 8 giờ sáng."]]},{"word":"酒屋","reading":"さかや","meaning":"cửa hàng rượu, tiệm bán rượu","hanViet":"TỬU ỐC","lesson":13,"ex":[["酒屋でビールを買います。","Tôi mua bia ở cửa hàng rượu."],["酒屋でワインを買いました。","Tôi đã mua rượu vang ở cửa hàng rượu."],["酒屋はどこですか。","Cửa hàng rượu ở đâu?"],["父は酒屋で酒を買います。","Bố tôi mua rượu ở cửa hàng rượu."],["酒屋はスーパーの前にあります。","Cửa hàng rượu ở trước siêu thị."]]},{"word":"八百屋","reading":"やおや","meaning":"cửa hàng rau","hanViet":"BÁT BÁCH","lesson":13,"ex":[["八百屋で野菜を買います。","Tôi mua rau ở cửa hàng rau."],["八百屋でりんごを買いました。","Tôi đã mua táo ở cửa hàng rau."],["八百屋はうちの近くにあります。","Cửa hàng rau ở gần nhà tôi."],["八百屋で玉ねぎと人参を買います。","Tôi mua hành tây và cà rốt ở cửa hàng rau."],["八百屋で果物を買いました。","Tôi đã mua trái cây ở cửa hàng rau."]]},{"word":"お正月","reading":"おしょうがつ","meaning":"Tết (dương lịch)","hanViet":"NGUYỆT","lesson":13,"ex":[["お正月に家族とごはんを食べます。","Ngày Tết tôi ăn cơm với gia đình."],["お正月にうちへ帰ります。","Ngày Tết tôi về nhà."],["お正月は一月です。","Tết vào tháng 1."],["お正月にお年玉をもらいます。","Ngày Tết tôi nhận tiền lì xì."],["お正月に友達と遊びます。","Ngày Tết tôi chơi với bạn."]]},{"word":"プール","reading":"プール","meaning":"bể bơi","hanViet":"","lesson":13,"ex":[["夏はプールで泳ぎます。","Mùa hè tôi bơi ở bể bơi."],["学校のプールは大きいです。","Bể bơi của trường thì lớn."],["プールは学校の近くにあります。","Bể bơi ở gần trường học."],["子どもとプールへ行きます。","Tôi đi bể bơi với con."],["プールの水は冷たいです。","Nước ở bể bơi lạnh."]]},{"word":"川","reading":"かわ","meaning":"Sông","hanViet":"XUYÊN","lesson":13,"ex":[["川で泳ぎます。","Tôi bơi ở sông."],["川の近くに公園があります。","Gần sông có công viên."],["川で魚を見ました。","Tôi đã thấy cá ở sông."],["川は広いです。","Sông rộng."],["川の水はきれいです。","Nước sông sạch đẹp."]]},{"word":"スキー","reading":"スキー","meaning":"trượt tuyết","hanViet":"","lesson":13,"ex":[["冬は山でスキーをします。","Mùa đông tôi trượt tuyết ở núi."],["スキーは楽しいです。","Trượt tuyết vui."],["冬に友達とスキーをします。","Mùa đông tôi trượt tuyết với bạn."],["スキーが好きです。","Tôi thích trượt tuyết."],["冬にスキーに行きます。","Mùa đông tôi đi trượt tuyết."]]},{"word":"～ごろ","reading":"～ごろ","meaning":"Khoảng ~ (dùng cho thời gian)","hanViet":"","lesson":13,"ex":[["午後七時ごろ、うちへ帰ります。","Khoảng bảy giờ chiều, tôi về nhà."],["午前九時ごろ、学校へ行きます。","Khoảng 9 giờ sáng, tôi đi học."],["昼ごろ、昼ごはんを食べます。","Khoảng trưa, tôi ăn trưa."],["夜八時ごろ、うちへ帰ります。","Khoảng 8 giờ tối, tôi về nhà."],["三時ごろ、友達が来ます。","Khoảng 3 giờ, bạn tôi đến."]]},{"word":"そうしましょう","reading":"そうしましょう","meaning":"Nhất trí./ Chúng ta thống nhất như thế.","hanViet":"","lesson":13,"ex":[["「あした、公園で遊びましょう。」「そうしましょう。」","“Ngày mai chúng ta chơi ở công viên nhé.” “Nhất trí.”"],["「あした、映画を見ましょう。」「そうしましょう。」","“Ngày mai chúng ta xem phim nhé.” “Nhất trí.”"],["「昼ごはんを食べましょう。」「そうしましょう。」","“Chúng ta ăn trưa nhé.” “Nhất trí.”"],["「電車で行きましょう。」「そうしましょう。」","“Chúng ta đi bằng tàu điện nhé.” “Nhất trí.”"],["「あした、テニスをしましょう。」「そうしましょう。」","“Ngày mai chúng ta chơi tennis nhé.” “Nhất trí.”"]]},{"word":"ご注文は？","reading":"ごちゅうもんは？","meaning":"Anh/Chị dùng món gì ạ","hanViet":"","lesson":13,"ex":[["「いらっしゃいませ。ご注文は？」","“Xin mời vào. Anh/chị dùng món gì ạ?”"],["「ご注文は？」「コーヒーをください。」","“Anh/chị dùng món gì ạ?” “Cho tôi cà phê.”"],["「ご注文は？」「定食をください。」","“Anh/chị dùng món gì ạ?” “Cho tôi cơm phần.”"],["「ご注文は？」「ケーキと紅茶をください。」","“Anh/chị dùng món gì ạ?” “Cho tôi bánh và trà.”"],["「ご注文は？」「すみません、もう少し待ってください。」","“Anh/chị dùng món gì ạ?” “Xin lỗi, hãy đợi thêm một chút nữa.”"]]},{"word":"少々お待ちください","reading":"しょうしょうおまちください","meaning":"xin vui lòng đợi một chút","hanViet":"THIỂU ĐÃI","lesson":13,"ex":[["少々お待ちください。先生を呼びます。","Xin vui lòng đợi một chút. Tôi sẽ gọi thầy giáo."],["少々お待ちください。かばんを取ります。","Xin vui lòng đợi một chút. Tôi lấy cặp."],["少々お待ちください。友達を呼びます。","Xin vui lòng đợi một chút. Tôi gọi bạn."],["少々お待ちください。電話をかけます。","Xin vui lòng đợi một chút. Tôi gọi điện thoại."],["少々お待ちください。地図を見ます。","Xin vui lòng đợi một chút. Tôi xem bản đồ."]]},{"word":"つけます","reading":"つけます","meaning":"bật (điện, máy điều hòa)","hanViet":"","lesson":14,"ex":[["部屋の電気をつけます。","Tôi bật đèn trong phòng."],["テレビをつけます。","Tôi bật ti vi."],["ラジオをつけます。","Tôi bật đài."],["暗いですから、電気をつけます。","Vì tối nên tôi bật đèn."],["午後六時に、部屋の電気をつけます。","Lúc 6 giờ chiều, tôi bật điện trong phòng."]]},{"word":"消します","reading":"けします","meaning":"tắt (điện, máy điều hòa)","hanViet":"","lesson":14,"ex":[["エアコンを消します。","Tôi tắt điều hòa."],["テレビを消します。","Tôi tắt ti vi."],["部屋の電気を消します。","Tôi tắt đèn trong phòng."],["寝ますから、電気を消します。","Vì đi ngủ nên tôi tắt đèn."],["寝る前に、電気を消します。","Trước khi đi ngủ, tôi tắt điện."]]},{"word":"開けます","reading":"あけます","meaning":"mở (cửa, cửa sổ)","hanViet":"","lesson":14,"ex":[["窓を開けます。","Tôi mở cửa sổ."],["ドアを開けます。","Tôi mở cửa."],["本を開けます。","Tôi mở sách."],["冷蔵庫を開けて、牛乳を取ります。","Tôi mở tủ lạnh và lấy sữa."],["ドアを開けて、教室に入ります。","Tôi mở cửa và vào lớp học."]]},{"word":"閉めます","reading":"しめます","meaning":"đóng (cửa, cửa sổ)","hanViet":"","lesson":14,"ex":[["ドアを閉めます。","Tôi đóng cửa."],["寝る前に窓を閉めます。","Trước khi ngủ tôi đóng cửa sổ."],["本を閉めます。","Tôi đóng sách."],["寒いですから、窓を閉めます。","Vì lạnh nên tôi đóng cửa sổ."],["ドアを閉めてください。","Hãy đóng cửa giúp tôi."]]},{"word":"急ぎます","reading":"いそぎます","meaning":"vội, gấp","hanViet":"","lesson":14,"ex":[["もう八時ですから、急ぎます。","Đã 8 giờ rồi nên tôi vội."],["電車に乗りたいですから、急ぎます。","Vì muốn lên tàu nên tôi vội."],["急いでください。","Hãy nhanh lên."],["急いで学校へ行きます。","Tôi vội vã đi học."],["急ぎましょう。","Chúng ta nhanh lên nào."]]},{"word":"待ちます","reading":"まちます","meaning":"đợi, chờ","hanViet":"","lesson":14,"ex":[["駅で友達を待ちます。","Tôi đợi bạn ở ga."],["うちで友達を待ちます。","Tôi đợi bạn ở nhà."],["先生を待ちます。","Tôi đợi thầy giáo."],["喫茶店で友達を待ちます。","Tôi đợi bạn ở quán cà phê."],["バスを待ちます。","Tôi đợi xe buýt."]]},{"word":"止めます","reading":"とめます","meaning":"dừng (băng, ôtô), đỗ (ôtô)","hanViet":"","lesson":14,"ex":[["ここで車を止めます。","Tôi đỗ xe ở đây."],["駐車場で車を止めます。","Tôi đỗ xe ở bãi đỗ xe."],["車を止めてください。","Hãy dừng xe lại."],["音楽を止めます。","Tôi dừng nhạc."],["信号で車を止めました。","Tôi đã dừng xe ở đèn giao thông."]]},{"word":"曲がります","reading":"まがります","meaning":"rẽ, quẹo [phải]","hanViet":"","lesson":14,"ex":[["信号を右へ曲がります。","Tôi rẽ phải ở đèn giao thông."],["角を左へ曲がります。","Tôi rẽ trái ở góc đường."],["銀行の前を左へ曲がります。","Tôi rẽ trái trước ngân hàng."],["交差点を右へ曲がります。","Tôi rẽ phải ở ngã tư."],["ここを右へ曲がってください。","Hãy rẽ phải ở đây."]]},{"word":"持ちます","reading":"もちます","meaning":"mang, cầm","hanViet":"","lesson":14,"ex":[["かばんを持ちます。","Tôi cầm cặp."],["私は重いかばんを持ちます。","Tôi mang cái cặp nặng."],["傘を持ちます。","Tôi mang ô."],["本を持って、学校へ行きます。","Tôi mang sách đi học."],["かばんを持ってください。","Hãy cầm cặp giúp tôi."]]},{"word":"取ります","reading":"とります","meaning":"lấy (muối)","hanViet":"","lesson":14,"ex":[["塩を取ってください。","Lấy muối giúp tôi."],["かばんから本を取ります。","Tôi lấy sách từ trong cặp."],["砂糖を取ってください。","Lấy đường giúp tôi."],["冷蔵庫から牛乳を取ります。","Tôi lấy sữa từ tủ lạnh."],["鉛筆を取ります。","Tôi lấy bút chì."]]},{"word":"手伝います","reading":"てつだいます","meaning":"giúp (làm việc)","hanViet":"","lesson":14,"ex":[["母を手伝います。","Tôi giúp mẹ."],["父を手伝います。","Tôi giúp bố."],["先生を手伝います。","Tôi giúp thầy giáo."],["友達の仕事を手伝います。","Tôi giúp công việc của bạn."],["掃除を手伝ってください。","Hãy giúp tôi dọn dẹp."]]},{"word":"呼びます","reading":"よびます","meaning":"gọi (taxi, tên)","hanViet":"","lesson":14,"ex":[["タクシーを呼びます。","Tôi gọi taxi."],["先生を呼びます。","Tôi gọi thầy giáo."],["名前を呼びます。","Tôi gọi tên."],["友達を呼んでください。","Hãy gọi bạn giúp tôi."],["タクシーを呼んで、駅へ行きます。","Tôi gọi taxi rồi đi ga."]]},{"word":"話します","reading":"はなします","meaning":"nói, nói chuyện","hanViet":"THOẠI","lesson":14,"ex":[["友達と話します。","Tôi nói chuyện với bạn."],["先生と話します。","Tôi nói chuyện với thầy giáo."],["友達と日本語で話します。","Tôi nói chuyện với bạn bằng tiếng Nhật."],["電話で話します。","Tôi nói chuyện qua điện thoại."],["話しましょう。","Chúng ta nói chuyện nhé."]]},{"word":"見せます","reading":"みせます","meaning":"cho xem, trình","hanViet":"KIẾN","lesson":14,"ex":[["友達に写真を見せます。","Tôi cho bạn xem ảnh."],["先生に宿題を見せます。","Tôi cho thầy xem bài tập."],["友達に切符を見せます。","Tôi cho bạn xem vé."],["地図を見せてください。","Hãy cho tôi xem bản đồ."],["写真を見せてもらいました。","Tôi đã được cho xem ảnh."]]},{"word":"始めます","reading":"はじめます","meaning":"bắt đầu","hanViet":"","lesson":14,"ex":[["勉強を始めます。","Tôi bắt đầu học."],["仕事を始めます。","Tôi bắt đầu làm việc."],["日本語の勉強を始めました。","Tôi đã bắt đầu học tiếng Nhật."],["スポーツを始めます。","Tôi bắt đầu chơi thể thao."],["会議を始めます。","Tôi bắt đầu cuộc họp."]]},{"word":"降ります","reading":"ふります","meaning":"rơi [mưa, tuyết]","hanViet":"","lesson":14,"ex":[["雨が降ります。","Trời mưa."],["雪が降ります。","Tuyết rơi."],["あした、雨が降るでしょう。","Ngày mai có lẽ trời sẽ mưa."],["雨が降りましたから、うちにいます。","Vì trời đã mưa nên tôi ở nhà."],["雨が降っています。","Trời đang mưa."]]},{"word":"名前","reading":"なまえ","meaning":"Tên","hanViet":"DANH","lesson":14,"ex":[["私の名前は田中です。","Tên tôi là Tanaka."],["この本の名前は何ですか。","Quyển sách này tên là gì?"],["名前を教えてください。","Hãy cho tôi biết tên."],["名前を書きます。","Tôi viết tên."],["友達の名前は山田です。","Tên bạn tôi là Yamada."]]},{"word":"住所","reading":"じゅうしょ","meaning":"Địa chỉ","hanViet":"TRÚ SỞ","lesson":14,"ex":[["住所は何ですか。","Địa chỉ là gì?"],["私の住所はここです。","Địa chỉ của tôi ở đây."],["住所を教えてください。","Hãy cho tôi biết địa chỉ."],["住所を書きます。","Tôi viết địa chỉ."],["友達の住所を知っていますか。","Bạn có biết địa chỉ của bạn tôi không?"]]},{"word":"地図","reading":"ちず","meaning":"Bản đồ","hanViet":"ĐỊA ĐỒ","lesson":14,"ex":[["地図を見ます。","Tôi xem bản đồ."],["地図を買います。","Tôi mua bản đồ."],["地図で道を調べます。","Tôi tra đường trên bản đồ."],["地図を見てください。","Hãy xem bản đồ."],["地図を持っています。","Tôi đang mang bản đồ."]]},{"word":"塩","reading":"しお","meaning":"Muối","hanViet":"DIÊM","lesson":14,"ex":[["塩を少し入れます。","Tôi cho một ít muối."],["塩を入れてください。","Hãy cho muối vào."],["塩がありません。","Không có muối."],["この料理は塩が少し多いです。","Món này hơi nhiều muối."],["塩を買います。","Tôi mua muối."]]},{"word":"砂糖","reading":"さとう","meaning":"Đường ăn (đường cát)","hanViet":"SA ĐƯỜNG","lesson":14,"ex":[["コーヒーに砂糖が入っています。","Trong cà phê có đường."],["紅茶に砂糖を入れます。","Tôi cho đường vào trà."],["砂糖を少しください。","Cho tôi một ít đường."],["砂糖がありません。","Không có đường."],["砂糖を買います。","Tôi mua đường."]]},{"word":"読み方","reading":"よみかた","meaning":"cách đọc","hanViet":"ĐỘC PHƯƠNG","lesson":14,"ex":[["この漢字の読み方は何ですか。","Cách đọc của chữ Hán này là gì?"],["この漢字の読み方を教えてください。","Hãy chỉ cho tôi cách đọc chữ Hán này."],["読み方がわかりません。","Tôi không biết cách đọc."],["このことばの読み方は何ですか。","Cách đọc của từ này là gì?"],["読み方を覚えます。","Tôi nhớ cách đọc."]]},{"word":"ゆっくり","reading":"ゆっくり","meaning":"chậm, thong thả, thoải mái","hanViet":"","lesson":14,"ex":[["ゆっくり話してください。","Hãy nói chậm lại."],["ゆっくり食べます。","Tôi ăn chậm."],["ゆっくり歩きます。","Tôi đi bộ thong thả."],["ゆっくり休みます。","Tôi nghỉ ngơi thoải mái."],["ゆっくり読みます。","Tôi đọc chậm."]]},{"word":"すぐ","reading":"すぐ","meaning":"ngay, lập tức","hanViet":"","lesson":14,"ex":[["すぐ行きます。","Tôi đi ngay."],["すぐ来ます。","Tôi đến ngay."],["すぐ帰ります。","Tôi về ngay."],["すぐ食べます。","Tôi ăn ngay."],["すぐ電話します。","Tôi gọi điện ngay."]]},{"word":"また","reading":"また","meaning":"lại (~đến)","hanViet":"","lesson":14,"ex":[["また明日来ます。","Ngày mai tôi lại đến."],["また会いましょう。","Chúng ta lại gặp nhau nhé."],["また来週来ます。","Tuần sau tôi lại đến."],["また電話します。","Tôi lại gọi điện."],["また明日遊びます。","Ngày mai tôi lại chơi."]]},{"word":"あとで","reading":"あとで","meaning":"sau","hanViet":"","lesson":14,"ex":[["あとで電話します。","Tôi sẽ gọi điện sau."],["あとで来ます。","Tôi sẽ đến sau."],["あとで食べます。","Tôi sẽ ăn sau."],["あとで会いましょう。","Chúng ta gặp nhau sau nhé."],["あとで勉強します。","Tôi sẽ học sau."]]},{"word":"もう少し","reading":"もうすこし","meaning":"thêm một chút nữa thôi","hanViet":"THIẾU","lesson":14,"ex":[["もう少しゆっくり話してください。","Hãy nói chậm thêm một chút nữa."],["もう少し食べます。","Tôi ăn thêm một chút nữa."],["もう少し待ってください。","Hãy đợi thêm một chút nữa."],["もう少し水をください。","Cho tôi thêm một chút nước nữa."],["もう少し勉強します。","Tôi học thêm một chút nữa."]]},{"word":"まっすぐ","reading":"まっすぐ","meaning":"thẳng","hanViet":"","lesson":14,"ex":[["まっすぐ行ってください。","Hãy đi thẳng."],["まっすぐ行きます。","Tôi đi thẳng."],["まっすぐ歩きます。","Tôi đi bộ thẳng."],["まっすぐ行って、公園へ行きます。","Đi thẳng rồi đến công viên."],["ここからまっすぐです。","Từ đây đi thẳng."]]},{"word":"お釣り","reading":"おつり","meaning":"tiền lẻ","hanViet":"","lesson":14,"ex":[["お釣りは500円です。","Tiền thừa là 500 yên."],["お釣りはいくらですか。","Tiền thừa là bao nhiêu?"],["お釣りをください。","Cho tôi tiền thừa."],["お釣りを忘れました。","Tôi đã quên lấy tiền thừa."],["お釣りをもらいました。","Tôi đã nhận tiền thừa."]]},{"word":"切符売り場","reading":"きっぷうりば","meaning":"Quầy bán vé","hanViet":"","lesson":14,"ex":[["切符売り場はどこですか。","Quầy bán vé ở đâu?"],["切符売り場で切符を買います。","Tôi mua vé ở quầy bán vé."],["切符売り場は駅の入口にあります。","Quầy bán vé ở lối vào ga."],["切符売り場はあちらです。","Quầy bán vé ở đằng kia."],["切符売り場で往復の切符を買いました。","Tôi đã mua vé khứ hồi ở quầy bán vé."]]},{"word":"自動券売機","reading":"じどうけんばいき","meaning":"Máy bán vé tự động","hanViet":"","lesson":14,"ex":[["自動券売機で切符を買います。","Tôi mua vé ở máy bán vé tự động."],["自動券売機はどこですか。","Máy bán vé tự động ở đâu?"],["自動券売機で往復の切符を買います。","Tôi mua vé khứ hồi ở máy bán vé tự động."],["自動券売機の前に人がいます。","Trước máy bán vé tự động có người."],["自動券売機は改札口の近くにあります。","Máy bán vé tự động ở gần cổng soát vé."]]},{"word":"精算機","reading":"せいさんき","meaning":"Máy điều chỉnh tiền vé","hanViet":"","lesson":14,"ex":[["精算機でお金を払います。","Tôi trả tiền ở máy điều chỉnh tiền vé."],["精算機はどこですか。","Máy điều chỉnh tiền vé ở đâu?"],["精算機でお金を入れます。","Tôi bỏ tiền vào máy điều chỉnh tiền vé."],["精算機は改札口の近くにあります。","Máy điều chỉnh tiền vé ở gần cổng soát vé."],["精算機の使い方を教えてください。","Hãy chỉ cho tôi cách dùng máy điều chỉnh tiền vé."]]},{"word":"改札口","reading":"かいさつぐち","meaning":"Cổng soát vé","hanViet":"","lesson":14,"ex":[["改札口で切符を見せます。","Tôi trình vé ở cổng soát vé."],["改札口はどこですか。","Cổng soát vé ở đâu?"],["改札口で会いましょう。","Chúng ta gặp nhau ở cổng soát vé."],["改札口の前に人がたくさんいます。","Trước cổng soát vé có nhiều người."],["改札口から出ます。","Tôi ra từ cổng soát vé."]]},{"word":"出口","reading":"でぐち","meaning":"Lối ra","hanViet":"XUẤT KHẨU","lesson":14,"ex":[["出口はあそこです。","Lối ra ở đằng kia."],["出口はどこですか。","Lối ra ở đâu?"],["出口から出ます。","Tôi ra từ lối ra."],["出口はあちらです。","Lối ra ở đằng kia."],["出口の前にタクシーがいます。","Trước lối ra có taxi."]]},{"word":"入口","reading":"いりぐち","meaning":"Lối vào","hanViet":"NHẬP KHẨU","lesson":14,"ex":[["入口はここです。","Lối vào ở đây."],["入口はどこですか。","Lối vào ở đâu?"],["入口から入ります。","Tôi vào từ lối vào."],["入口はあそこです。","Lối vào ở đằng kia."],["入口の前に車があります。","Trước lối vào có xe."]]},{"word":"東口","reading":"ひがしぐち","meaning":"Lối ra phía Đông","hanViet":"ĐÔNG KHẨU","lesson":14,"ex":[["東口で友達と会います。","Tôi gặp bạn ở lối ra phía Đông."],["東口はどこですか。","Lối ra phía Đông ở đâu?"],["東口から出ます。","Tôi ra từ lối ra phía Đông."],["東口でタクシーに乗ります。","Tôi lên taxi ở lối ra phía Đông."],["東口へ行きます。","Tôi đi đến lối ra phía Đông."]]},{"word":"西口","reading":"にしぐち","meaning":"Lối ra phía Tây","hanViet":"TÂY KHẨU","lesson":14,"ex":[["西口から出ます。","Tôi ra từ lối ra phía Tây."],["西口はどこですか。","Lối ra phía Tây ở đâu?"],["西口で会いましょう。","Chúng ta gặp nhau ở lối ra phía Tây."],["西口の前に公園があります。","Trước lối ra phía Tây có công viên."],["西口へ行きます。","Tôi đi đến lối ra phía Tây."]]},{"word":"南口","reading":"みなみぐち","meaning":"Lối ra phía Nam","hanViet":"NAM KHẨU","lesson":14,"ex":[["南口はあちらです。","Lối ra phía Nam ở đằng kia."],["南口はどこですか。","Lối ra phía Nam ở đâu?"],["南口から出ます。","Tôi ra từ lối ra phía Nam."],["南口でバスに乗ります。","Tôi lên xe buýt ở lối ra phía Nam."],["南口の前に店があります。","Trước lối ra phía Nam có cửa hàng."]]},{"word":"北口","reading":"きたぐち","meaning":"Lối ra phía Bắc","hanViet":"BẮC KHẨU","lesson":14,"ex":[["北口の前に店があります。","Trước lối ra phía Bắc có một cửa hàng."],["北口はどこですか。","Lối ra phía Bắc ở đâu?"],["北口から出ます。","Tôi ra từ lối ra phía Bắc."],["北口で友達と会います。","Tôi gặp bạn ở lối ra phía Bắc."],["北口へ行きます。","Tôi đi đến lối ra phía Bắc."]]},{"word":"中央口","reading":"ちゅうおうぐち","meaning":"Cửa trung tâm","hanViet":"","lesson":14,"ex":[["中央口で会いましょう。","Chúng ta hãy gặp nhau ở cửa trung tâm."],["中央口はどこですか。","Cửa trung tâm ở đâu?"],["中央口から出ます。","Tôi ra từ cửa trung tâm."],["中央口の前に人がたくさんいます。","Trước cửa trung tâm có nhiều người."],["中央口で友達と会います。","Tôi gặp bạn ở cửa trung tâm."]]},{"word":"売店","reading":"ばいてん","meaning":"Quầy hàng","hanViet":"","lesson":14,"ex":[["売店で水を買います。","Tôi mua nước ở quầy hàng."],["売店で新聞を買います。","Tôi mua báo ở quầy hàng."],["売店は駅の中にあります。","Quầy hàng ở trong ga."],["売店でジュースを買いました。","Tôi đã mua nước trái cây ở quầy hàng."],["売店はどこですか。","Quầy hàng ở đâu?"]]},{"word":"片道","reading":"かたみち","meaning":"Đường một chiều, vé một lượt","hanViet":"PHIẾN ĐẠO","lesson":14,"ex":[["片道の切符をください。","Cho tôi vé một lượt."],["片道の切符を買います。","Tôi mua vé một lượt."],["片道はいくらですか。","Vé một lượt bao nhiêu tiền?"],["片道の切符は500円です。","Vé một lượt là 500 yên."],["片道で帰ります。","Tôi về bằng vé một lượt."]]},{"word":"往復","reading":"おうふく","meaning":"Khứ hồi, đi và về","hanViet":"VÃNG PHỤC","lesson":14,"ex":[["往復の切符を買います。","Tôi mua vé khứ hồi."],["往復の切符をください。","Cho tôi vé khứ hồi."],["往復はいくらですか。","Vé khứ hồi bao nhiêu tiền?"],["往復の切符は1000円です。","Vé khứ hồi là 1000 yên."],["往復で二時間かかります。","Đi và về mất hai tiếng."]]},{"word":"コピーします","reading":"コピーします","meaning":"photo, sao chụp","hanViet":"","lesson":14,"ex":[["この紙をコピーします。","Tôi photo tờ giấy này."],["この本をコピーします。","Tôi photo quyển sách này."],["紙を二枚コピーします。","Tôi photo hai tờ giấy."],["コピーしてください。","Hãy photo giúp tôi."],["レポートをコピーしました。","Tôi đã photo bản báo cáo."]]},{"word":"エアコン","reading":"エアコン","meaning":"điều hòa","hanViet":"","lesson":14,"ex":[["エアコンをつけます。","Tôi bật điều hòa."],["エアコンを買います。","Tôi mua điều hòa."],["エアコンがありません。","Không có điều hòa."],["エアコンは新しいです。","Điều hòa mới."],["エアコンをつけてください。","Hãy bật điều hòa giúp tôi."]]},{"word":"パスポート","reading":"パスポート","meaning":"hộ chiếu","hanViet":"","lesson":14,"ex":[["パスポートを見せてください。","Xin trình hộ chiếu."],["パスポートを持っています。","Tôi đang mang hộ chiếu."],["パスポートを忘れました。","Tôi đã quên hộ chiếu."],["パスポートはどこですか。","Hộ chiếu ở đâu?"],["パスポートをなくしました。","Tôi đã làm mất hộ chiếu."]]},{"word":"～方","reading":"～かた","meaning":"cách ~","hanViet":"","lesson":14,"ex":[["この機械の使い方を教えてください。","Hãy chỉ cho tôi cách dùng cái máy này."],["この漢字の書き方を教えてください。","Hãy chỉ cho tôi cách viết chữ Hán này."],["使い方がわかりません。","Tôi không biết cách dùng."],["日本語の話し方を練習します。","Tôi luyện cách nói tiếng Nhật."],["この料理の作り方を教えてください。","Hãy chỉ cho tôi cách làm món ăn này."]]},{"word":"もう～","reading":"もう～","meaning":"hơn nữa","hanViet":"","lesson":14,"ex":[["もう一度言ってください。","Hãy nói lại một lần nữa."],["もう一つください。","Cho tôi thêm một cái nữa."],["もう三つ買います。","Tôi mua thêm ba cái nữa."],["もう一回見ます。","Tôi xem lại một lần nữa."],["もう一人来ました。","Thêm một người nữa đã đến."]]},{"word":"さあ","reading":"さあ","meaning":"nào","hanViet":"","lesson":14,"ex":[["さあ、始めましょう。","Nào, chúng ta bắt đầu thôi."],["さあ、行きましょう。","Nào, chúng ta đi thôi."],["さあ、食べましょう。","Nào, chúng ta ăn thôi."],["さあ、勉強しましょう。","Nào, chúng ta học thôi."],["さあ、どうぞ。","Nào, mời bạn."]]},{"word":"あれ？","reading":"あれ？","meaning":"hả? ơ?","hanViet":"","lesson":14,"ex":[["あれ？かばんはどこですか。","Ơ? Cái cặp đâu rồi?"],["あれ？先生はどこですか。","Ơ? Thầy giáo đâu rồi?"],["あれ？鍵がありません。","Ơ? Không có chìa khóa."],["あれ？お金がありません。","Ơ? Không có tiền."],["あれ？雨が降っています。","Ơ? Trời đang mưa."]]},{"word":"信号を右へ曲がってください","reading":"しんごうをみぎへまがってください","meaning":"hãy rẽ phải ở đèn giao thông","hanViet":"","lesson":14,"ex":[["信号を右へ曲がってください。","Hãy rẽ phải ở đèn giao thông."],["信号を右へ曲がってください。駅はそこです。","Hãy rẽ phải ở đèn giao thông. Ga ở đó."],["まっすぐ行って、信号を右へ曲がってください。","Đi thẳng rồi rẽ phải ở đèn giao thông."],["信号を右へ曲がってください。学校は左にあります。","Hãy rẽ phải ở đèn giao thông. Trường học ở bên trái."],["信号を右へ曲がってください。銀行はそこにあります。","Hãy rẽ phải ở đèn giao thông. Ngân hàng ở đó."]]},{"word":"これでお願いします","reading":"これでおねがいします","meaning":"cho tôi cái này","hanViet":"","lesson":14,"ex":[["これでお願いします。","Cho tôi cái này."],["これでお願いします。いくらですか。","Cho tôi cái này. Bao nhiêu tiền?"],["「これでお願いします。」「はい、わかりました。」","“Cho tôi cái này.” “Vâng, tôi hiểu rồi.”"],["これでお願いします。ありがとうございます。","Cho tôi cái này. Cảm ơn."],["すみません、これでお願いします。","Xin lỗi, cho tôi cái này."]]},{"word":"立ちます","reading":"たちます","meaning":"đứng","hanViet":"LẬP","lesson":15,"ex":[["いすから立ちます。","Tôi đứng dậy khỏi ghế."],["電車の中で立ちました。","Tôi đã đứng trong tàu điện."],["先生が来ましたから、立ちました。","Vì thầy giáo đã đến nên tôi đã đứng dậy."],["会議で立って話します。","Tôi đứng nói trong cuộc họp."],["どうぞ立ってください。","Xin mời đứng lên."]]},{"word":"座ります","reading":"すわります","meaning":"ngồi","hanViet":"","lesson":15,"ex":[["いすに座ります。","Tôi ngồi xuống ghế."],["ベッドに座りました。","Tôi đã ngồi lên giường."],["先生の前に座ります。","Tôi ngồi trước mặt thầy giáo."],["座って、テレビを見ます。","Tôi ngồi xem ti vi."],["どうぞ座ってください。","Xin mời ngồi xuống."]]},{"word":"使います","reading":"つかいます","meaning":"sử dụng","hanViet":"","lesson":15,"ex":[["コンピューターを使います。","Tôi sử dụng máy tính."],["辞書を使って、日本語を勉強します。","Tôi dùng từ điển để học tiếng Nhật."],["雨の日は傘を使います。","Ngày mưa tôi dùng ô."],["はさみを使いますか。","Bạn có dùng kéo không?"],["毎日コンピューターを使います。","Hàng ngày tôi dùng máy tính."]]},{"word":"置きます","reading":"おきます","meaning":"đặt, để","hanViet":"","lesson":15,"ex":[["本を机の上に置きます。","Tôi đặt sách lên bàn."],["かばんを机の下に置きました。","Tôi đã để cặp dưới bàn."],["傘を玄関に置きます。","Tôi để ô ở cửa ra vào."],["ここに荷物を置いてください。","Xin hãy để hành lý ở đây."],["花を窓の前に置きました。","Tôi đã đặt hoa trước cửa sổ."]]},{"word":"作ります","reading":"つくります","meaning":"làm, chế tạo","hanViet":"","lesson":15,"ex":[["ケーキを作ります。","Tôi làm bánh."],["母は毎日ごはんを作ります。","Mẹ tôi nấu cơm hàng ngày."],["友達とケーキを作りました。","Tôi đã làm bánh cùng bạn."],["兄は机を作ります。","Anh trai tôi làm bàn."],["この会社は車を作ります。","Công ty này sản xuất ô tô."]]},{"word":"売ります","reading":"うります","meaning":"bán","hanViet":"","lesson":15,"ex":[["店で本を売ります。","Tôi bán sách ở cửa hàng."],["本屋で雑誌を売ります。","Tôi bán tạp chí ở hiệu sách."],["この店は野菜を売りますか。","Cửa hàng này có bán rau không?"],["父は会社で車を売ります。","Bố tôi bán ô tô ở công ty."],["きのう、本を売りました。","Hôm qua tôi đã bán sách."]]},{"word":"知ります","reading":"しります","meaning":"biết","hanViet":"","lesson":15,"ex":[["そのニュースを知りました。","Tôi đã biết tin tức đó."],["あの人の名前を知りません。","Tôi không biết tên của người kia."],["試験の日を知りました。","Tôi đã biết ngày thi."],["友達からニュースを知りました。","Tôi đã biết tin tức từ bạn."],["電話番号を知りました。","Tôi đã biết số điện thoại."]]},{"word":"住みます","reading":"すみます","meaning":"sống, ở","hanViet":"","lesson":15,"ex":[["日本に住みます。","Tôi sống ở Nhật Bản."],["私はベトナムに住みます。","Tôi sống ở Việt Nam."],["友達は中国に住みます。","Bạn tôi sống ở Trung Quốc."],["町の近くに住みます。","Tôi sống gần thị trấn."],["どこに住みますか。","Bạn sống ở đâu?"]]},{"word":"研究します","reading":"けんきゅうします","meaning":"nghiên cứu","hanViet":"","lesson":15,"ex":[["日本語を研究します。","Tôi nghiên cứu tiếng Nhật."],["大学で日本語を研究します。","Tôi nghiên cứu tiếng Nhật ở đại học."],["先生は英語を研究します。","Thầy giáo nghiên cứu tiếng Anh."],["兄は音楽を研究します。","Anh trai tôi nghiên cứu âm nhạc."],["私は日本語を研究したいです。","Tôi muốn nghiên cứu tiếng Nhật."]]},{"word":"知っています","reading":"しっています","meaning":"biết","hanViet":"","lesson":15,"ex":[["田中さんを知っています。","Tôi biết anh Tanaka."],["山田さんを知っていますか。","Bạn có biết anh Yamada không?"],["私はその店を知っています。","Tôi biết cửa hàng đó."],["あの先生の名前を知っています。","Tôi biết tên của thầy giáo kia."],["友達の電話番号を知っています。","Tôi biết số điện thoại của bạn."]]},{"word":"住んでいます","reading":"すんでいます","meaning":"sống","hanViet":"","lesson":15,"ex":[["今、アパートに住んでいます。","Bây giờ tôi sống ở chung cư."],["私は日本に住んでいます。","Tôi đang sống ở Nhật Bản."],["友達はベトナムに住んでいます。","Bạn tôi đang sống ở Việt Nam."],["兄はアパートに住んでいますか。","Anh trai bạn có sống ở chung cư không?"],["田中さんはどこに住んでいますか。","Anh Tanaka đang sống ở đâu?"]]},{"word":"資料","reading":"しりょう","meaning":"Tài liệu, tư liệu","hanViet":"TƯ LIỆU","lesson":15,"ex":[["資料を読みます。","Tôi đọc tài liệu."],["資料をコピーします。","Tôi sao chép tài liệu."],["先生に資料をもらいました。","Tôi đã nhận tài liệu từ thầy giáo."],["机の上に資料があります。","Trên bàn có tài liệu."],["資料を調べます。","Tôi tra cứu tài liệu."]]},{"word":"時刻表","reading":"じこくひょう","meaning":"bảng ghi thời gian tàu chạy","hanViet":"","lesson":15,"ex":[["時刻表を見ます。","Tôi xem bảng giờ tàu chạy."],["時刻表を見て、電車に乗ります。","Tôi xem bảng giờ tàu rồi lên tàu điện."],["駅で時刻表をもらいました。","Tôi đã nhận bảng giờ tàu ở ga."],["時刻表はどこですか。","Bảng giờ tàu ở đâu?"],["この時刻表は古いです。","Bảng giờ tàu này cũ."]]},{"word":"服","reading":"ふく","meaning":"Quần áo","hanViet":"PHỤC","lesson":15,"ex":[["新しい服を買います。","Tôi mua quần áo mới."],["服を着ます。","Tôi mặc quần áo."],["服を洗います。","Tôi giặt quần áo."],["この服は高いです。","Bộ quần áo này đắt."],["きれいな服が好きです。","Tôi thích quần áo đẹp."]]},{"word":"製品","reading":"せいひん","meaning":"sản phẩm, chế phẩm","hanViet":"CHẾ PHẨM","lesson":15,"ex":[["この製品は有名です。","Sản phẩm này nổi tiếng."],["日本の製品は有名です。","Sản phẩm Nhật Bản nổi tiếng."],["新しい製品を買いました。","Tôi đã mua sản phẩm mới."],["この会社は製品を作ります。","Công ty này sản xuất sản phẩm."],["製品を見せてください。","Xin hãy cho tôi xem sản phẩm."]]},{"word":"専門","reading":"せんもん","meaning":"Chuyên môn","hanViet":"CHUYÊN MÔN","lesson":15,"ex":[["私の専門は日本語です。","Chuyên môn của tôi là tiếng Nhật."],["田中さんの専門は英語です。","Chuyên môn của anh Tanaka là tiếng Anh."],["専門は何ですか。","Chuyên môn của bạn là gì?"],["専門の本を読みます。","Tôi đọc sách chuyên môn."],["大学で専門を勉強します。","Tôi học chuyên môn ở đại học."]]},{"word":"歯医者","reading":"はいしゃ","meaning":"Nha sĩ, bác sĩ răng","hanViet":"XỈ Y GIẢ","lesson":15,"ex":[["歯医者へ行きます。","Tôi đi nha sĩ."],["歯が痛いですから、歯医者へ行きます。","Vì đau răng nên tôi đi nha sĩ."],["歯医者で歯を見せました。","Ở chỗ nha sĩ, tôi đã cho xem răng."],["歯医者は忙しいです。","Nha sĩ bận rộn."],["あの歯医者は有名です。","Nha sĩ kia nổi tiếng."]]},{"word":"床屋","reading":"とこや","meaning":"Tiệm cắt tóc nam","hanViet":"SÀNG ỐC","lesson":15,"ex":[["床屋へ行きます。","Tôi đi tiệm cắt tóc nam."],["床屋で髪を切ります。","Tôi cắt tóc ở tiệm cắt tóc nam."],["あした、床屋へ行きます。","Ngày mai tôi đi tiệm cắt tóc nam."],["床屋はどこですか。","Tiệm cắt tóc nam ở đâu?"],["父は床屋で働きます。","Bố tôi làm việc ở tiệm cắt tóc nam."]]},{"word":"独身","reading":"どくしん","meaning":"độc thân","hanViet":"","lesson":15,"ex":[["田中さんは独身です。","Anh Tanaka độc thân."],["私の兄はまだ独身です。","Anh trai tôi vẫn còn độc thân."],["山田さんは独身ですか。","Anh Yamada độc thân phải không?"],["あの人は独身です。","Người kia độc thân."],["独身ですから、一人で住みます。","Vì độc thân nên tôi sống một mình."]]},{"word":"特に","reading":"とくに","meaning":"Đặc biệt là, nhất là","hanViet":"ĐẶC","lesson":15,"ex":[["特に、映画が好きです。","Đặc biệt là tôi thích phim."],["日本語の中で、特に漢字が難しいです。","Trong tiếng Nhật, đặc biệt là chữ Hán thì khó."],["特に、きょうは寒いです。","Đặc biệt hôm nay trời lạnh."],["田中さんは特に英語が上手です。","Anh Tanaka đặc biệt giỏi tiếng Anh."],["特に日曜日は店がにぎやかです。","Đặc biệt ngày chủ nhật cửa hàng rất đông vui."]]},{"word":"思い出します","reading":"おもいだします","meaning":"nhớ lại, hồi tưởng","hanViet":"","lesson":15,"ex":[["小学校の友達を思い出します。","Tôi nhớ lại bạn học tiểu học."],["友達の顔を思い出します。","Tôi nhớ lại khuôn mặt của bạn."],["きのうの話を思い出しました。","Tôi đã nhớ lại chuyện hôm qua."],["学校の先生を思い出します。","Tôi nhớ lại thầy giáo ở trường."],["歌を聞いて、友達を思い出しました。","Nghe bài hát, tôi đã nhớ lại bạn bè."]]},{"word":"公務員","reading":"こうむいん","meaning":"Công chức","hanViet":"CÔNG VỤ VIÊN","lesson":15,"ex":[["父は公務員です。","Bố tôi là công chức."],["兄は公務員です。","Anh trai tôi là công chức."],["私は公務員になりたいです。","Tôi muốn trở thành công chức."],["市役所で公務員が働きます。","Công chức làm việc ở tòa thị chính."],["公務員は忙しいです。","Công chức bận rộn."]]},{"word":"駅員","reading":"えきいん","meaning":"Nhân viên nhà ga","hanViet":"DỊCH VIÊN","lesson":15,"ex":[["駅員に聞きます。","Tôi hỏi nhân viên nhà ga."],["駅員に道を聞きました。","Tôi đã hỏi đường nhân viên nhà ga."],["駅員は親切です。","Nhân viên nhà ga thân thiện."],["駅で駅員に会いました。","Tôi đã gặp nhân viên nhà ga ở ga."],["駅員が切符を売ります。","Nhân viên nhà ga bán vé."]]},{"word":"郵便局員","reading":"ゆうびんきょくいん","meaning":"nhân viên bưu điện","hanViet":"","lesson":15,"ex":[["郵便局員は親切です。","Nhân viên bưu điện thân thiện."],["郵便局で郵便局員に聞きました。","Tôi đã hỏi nhân viên bưu điện ở bưu điện."],["郵便局員は切手を売ります。","Nhân viên bưu điện bán tem."],["父は郵便局員です。","Bố tôi là nhân viên bưu điện."],["郵便局員は元気です。","Nhân viên bưu điện khỏe mạnh."]]},{"word":"店員","reading":"てんいん","meaning":"Nhân viên cửa hàng","hanViet":"ĐIẾM VIÊN","lesson":15,"ex":[["店員に聞きます。","Tôi hỏi nhân viên cửa hàng."],["店員は元気です。","Nhân viên cửa hàng khỏe mạnh."],["店員に聞いて、シャツを買いました。","Tôi đã hỏi nhân viên rồi mua áo sơ mi."],["店員が服を売ります。","Nhân viên cửa hàng bán quần áo."],["店員に新しい服を見せてもらいました。","Tôi đã nhờ nhân viên cho xem quần áo mới."]]},{"word":"調理師","reading":"ちょうりし","meaning":"đầu bếp","hanViet":"","lesson":15,"ex":[["調理師は料理を作ります。","Đầu bếp nấu món ăn."],["父は調理師です。","Bố tôi là đầu bếp."],["私は調理師になりたいです。","Tôi muốn trở thành đầu bếp."],["レストランで調理師が働きます。","Đầu bếp làm việc ở nhà hàng."],["調理師の料理はおいしいです。","Món ăn của đầu bếp ngon."]]},{"word":"理容師","reading":"りようし","meaning":"thợ cắt tóc nam","hanViet":"","lesson":15,"ex":[["父は理容師です。","Bố tôi là thợ cắt tóc nam."],["床屋で理容師が働きます。","Thợ cắt tóc nam làm việc ở tiệm cắt tóc nam."],["理容師の仕事は大変です。","Công việc của thợ cắt tóc nam vất vả."],["理容師に髪を切ってもらいました。","Tôi đã nhờ thợ cắt tóc nam cắt tóc."],["あの人は理容師です。","Người kia là thợ cắt tóc nam."]]},{"word":"美容師","reading":"びようし","meaning":"tạo mẫu tóc","hanViet":"","lesson":15,"ex":[["姉は美容師です。","Chị gái tôi là tạo mẫu tóc."],["美容師に髪を切ってもらいました。","Tôi đã nhờ tạo mẫu tóc cắt tóc."],["美容師の仕事は楽しいです。","Công việc của tạo mẫu tóc thú vị."],["姉の友達は美容師です。","Bạn của chị gái tôi là tạo mẫu tóc."],["美容師は元気です。","Tạo mẫu tóc khỏe mạnh."]]},{"word":"弁護士","reading":"べんごし","meaning":"luật sư","hanViet":"BIỆN HỘ SĨ","lesson":15,"ex":[["田中さんは弁護士です。","Anh Tanaka là luật sư."],["私は弁護士になりたいです。","Tôi muốn trở thành luật sư."],["事務所で弁護士に会いました。","Tôi đã gặp luật sư ở văn phòng."],["弁護士の仕事は難しいです。","Công việc của luật sư khó."],["山田さんは弁護士です。","Anh Yamada là luật sư."]]},{"word":"看護婦","reading":"かんごふ","meaning":"Y tá (cách gọi cũ)","hanViet":"KHÁN HỘ PHỤ","lesson":15,"ex":[["母は看護婦です。","Mẹ tôi là y tá."],["病院で看護婦が働きます。","Y tá làm việc ở bệnh viện."],["看護婦は親切です。","Y tá thân thiện."],["看護婦の仕事は大変です。","Công việc của y tá vất vả."],["田中さんは病院で看護婦をしています。","Chị Tanaka làm y tá ở bệnh viện."]]},{"word":"運転手","reading":"うんてんしゅ","meaning":"Tài xế","hanViet":"VẬN CHUYỂN THỦ","lesson":15,"ex":[["父は運転手です。","Bố tôi là tài xế."],["バスの運転手は親切です。","Tài xế xe buýt thân thiện."],["運転手は朝早く起きます。","Tài xế dậy sớm vào buổi sáng."],["タクシーの運転手に聞きました。","Tôi đã hỏi tài xế taxi."],["兄は運転手です。","Anh trai tôi là tài xế."]]},{"word":"警察官","reading":"けいさつかん","meaning":"Cán bộ cảnh sát","hanViet":"CẢNH SÁT QUAN","lesson":15,"ex":[["警察官に道を聞きます。","Tôi hỏi đường cảnh sát."],["警察官は親切です。","Cảnh sát thân thiện."],["交番で警察官に会いました。","Tôi đã gặp cảnh sát ở đồn cảnh sát."],["私は警察官になりたいです。","Tôi muốn trở thành cảnh sát."],["警察署で警察官が働きます。","Cảnh sát làm việc ở sở cảnh sát."]]},{"word":"外交官","reading":"がいこうかん","meaning":"nhà ngoại giao","hanViet":"","lesson":15,"ex":[["田中さんは外交官です。","Anh Tanaka là nhà ngoại giao."],["外交官は英語が上手です。","Nhà ngoại giao giỏi tiếng Anh."],["大使館で外交官が働きます。","Nhà ngoại giao làm việc ở đại sứ quán."],["外交官は有名です。","Nhà ngoại giao nổi tiếng."],["あの人は外交官です。","Người kia là nhà ngoại giao."]]},{"word":"政治家","reading":"せいじか","meaning":"Chính trị gia","hanViet":"CHÍNH TRỊ GIA","lesson":15,"ex":[["あの人は政治家です。","Người kia là chính trị gia."],["政治家は有名です。","Chính trị gia nổi tiếng."],["政治家は大変です。","Chính trị gia vất vả."],["テレビで政治家を見ました。","Tôi đã thấy chính trị gia trên ti vi."],["田中さんは政治家です。","Anh Tanaka là chính trị gia."]]},{"word":"画家","reading":"がか","meaning":"Họa sĩ","hanViet":"HỌA GIA","lesson":15,"ex":[["山田さんは画家です。","Anh Yamada là họa sĩ."],["私は画家になりたいです。","Tôi muốn trở thành họa sĩ."],["画家は絵をかきます。","Họa sĩ vẽ tranh."],["画家の絵はきれいです。","Tranh của họa sĩ đẹp."],["美術館で画家に会いました。","Tôi đã gặp họa sĩ ở bảo tàng mỹ thuật."]]},{"word":"作家","reading":"さっか","meaning":"nhà văn","hanViet":"","lesson":15,"ex":[["あの人は有名な作家です。","Người kia là nhà văn nổi tiếng."],["作家は本を書きます。","Nhà văn viết sách."],["作家の話が好きです。","Tôi thích truyện của nhà văn."],["作家の本はおもしろいです。","Sách của nhà văn thú vị."],["山田さんは作家です。","Anh Yamada là nhà văn."]]},{"word":"音楽家","reading":"おんがくか","meaning":"nhạc sĩ","hanViet":"","lesson":15,"ex":[["田中さんは音楽家です。","Anh Tanaka là nhạc sĩ."],["音楽家はピアノを弾きます。","Nhạc sĩ chơi đàn piano."],["音楽家は歌が上手です。","Nhạc sĩ hát hay."],["音楽家のコンサートに行きます。","Tôi đi xem buổi hòa nhạc của nhạc sĩ."],["町で音楽家に会いました。","Tôi đã gặp nhạc sĩ trong thị trấn."]]},{"word":"建築家","reading":"けんちくか","meaning":"kiến trúc sư","hanViet":"","lesson":15,"ex":[["兄は建築家です。","Anh trai tôi là kiến trúc sư."],["建築家の仕事は楽しいです。","Công việc của kiến trúc sư thú vị."],["建築家は建物を作ります。","Kiến trúc sư xây dựng tòa nhà."],["会社で建築家に会いました。","Tôi đã gặp kiến trúc sư ở công ty."],["父は建築家です。","Bố tôi là kiến trúc sư."]]},{"word":"歌手","reading":"かしゅ","meaning":"Ca sĩ","hanViet":"CA THỦ","lesson":15,"ex":[["あの歌手は有名です。","Ca sĩ đó nổi tiếng."],["歌手は歌を歌います。","Ca sĩ hát bài hát."],["私は歌手になりたいです。","Tôi muốn trở thành ca sĩ."],["歌手は歌が上手です。","Ca sĩ hát hay."],["あの歌手の歌が好きです。","Tôi thích bài hát của ca sĩ kia."]]},{"word":"俳優","reading":"はいゆう","meaning":"diễn viên","hanViet":"BÀI ƯU","lesson":15,"ex":[["田中さんは俳優です。","Anh Tanaka là diễn viên."],["俳優はハンサムです。","Diễn viên đẹp trai."],["俳優は映画に出ます。","Diễn viên đóng phim."],["テレビで俳優を見ました。","Tôi đã thấy diễn viên trên ti vi."],["あの俳優は有名です。","Diễn viên kia nổi tiếng."]]},{"word":"電子辞書","reading":"でんしじしょ","meaning":"từ điển điện tử","hanViet":"","lesson":15,"ex":[["電子辞書を使います。","Tôi dùng từ điển điện tử."],["電子辞書で日本語を調べます。","Tôi tra tiếng Nhật bằng từ điển điện tử."],["新しい電子辞書を買いました。","Tôi đã mua từ điển điện tử mới."],["電子辞書は便利です。","Từ điển điện tử tiện lợi."],["私は電子辞書を持っています。","Tôi có từ điển điện tử."]]},{"word":"カタログ","reading":"カタログ","meaning":"catalogue","hanViet":"","lesson":15,"ex":[["カタログを見ます。","Tôi xem catalogue."],["カタログを見て、服を買います。","Tôi xem catalogue rồi mua quần áo."],["カタログをもらいました。","Tôi đã nhận catalogue."],["このカタログは新しいです。","Catalogue này mới."],["カタログで車を調べます。","Tôi tra cứu ô tô trong catalogue."]]},{"word":"ソフト","reading":"ソフト","meaning":"phần mềm","hanViet":"","lesson":15,"ex":[["新しいソフトを使います。","Tôi dùng phần mềm mới."],["新しいソフトを買いました。","Tôi đã mua phần mềm mới."],["ソフトを使って、日本語を勉強します。","Tôi dùng phần mềm để học tiếng Nhật."],["このソフトは便利です。","Phần mềm này tiện lợi."],["ソフトをコンピューターに入れます。","Tôi cài phần mềm vào máy tính."]]},{"word":"プレイガイド","reading":"プレイガイド","meaning":"quầy bán vé","hanViet":"","lesson":15,"ex":[["プレイガイドでチケットを買います。","Tôi mua vé ở quầy bán vé."],["プレイガイドでコンサートのチケットを買います。","Tôi mua vé hòa nhạc ở quầy bán vé."],["プレイガイドはどこですか。","Quầy bán vé ở đâu?"],["プレイガイドに電話します。","Tôi gọi điện cho quầy bán vé."],["プレイガイドは駅の近くにあります。","Quầy bán vé ở gần ga."]]},{"word":"ご家族","reading":"ごかぞく","meaning":"gia đình (người khác)","hanViet":"","lesson":15,"ex":[["ご家族は何人ですか？","Gia đình anh/chị có mấy người?"],["ご家族はお元気ですか。","Gia đình anh/chị có khỏe không?"],["ご家族と日本へ来ましたか。","Anh/chị đã đến Nhật cùng gia đình phải không?"],["ご家族に会いました。","Tôi đã gặp gia đình anh/chị."],["ご家族はベトナムに住んでいますか。","Gia đình anh/chị đang sống ở Việt Nam phải không?"]]},{"word":"いらっしゃいます","reading":"いらっしゃいます","meaning":"có, ở (kính ngữ của います)","hanViet":"","lesson":15,"ex":[["田中さんはいらっしゃいますか？","Anh Tanaka có ở đây không?"],["先生はいらっしゃいますか。","Thầy giáo có ở đây không ạ?"],["社長はいらっしゃいます。","Giám đốc có ở đây."],["田中さんはいらっしゃいません。","Anh Tanaka không có ở đây."],["先生はどこにいらっしゃいますか。","Thầy giáo đang ở đâu ạ?"]]},{"word":"乗ります","reading":"のります","meaning":"đi, lên (tàu)","hanViet":"","lesson":16,"ex":[["電車に乗ります。","Tôi lên tàu điện."],["毎日、八時にバスに乗ります。","Mỗi ngày lúc 8 giờ tôi lên xe buýt."],["タクシーに乗って、駅へ行きます。","Tôi đi taxi đến ga."],["新幹線に乗りました。","Tôi đã lên tàu Shinkansen."],["飛行機に乗ります。","Tôi lên máy bay."]]},{"word":"降ります","reading":"おります","meaning":"xuống (tàu)","hanViet":"","lesson":16,"ex":[["駅で電車を降ります。","Tôi xuống tàu ở ga."],["次の駅で降ります。","Tôi xuống ở ga tiếp theo."],["バスを降りて、歩きます。","Tôi xuống xe buýt rồi đi bộ."],["地下鉄を降ります。","Tôi xuống tàu điện ngầm."],["ここでバスを降りてください。","Xin hãy xuống xe buýt ở đây."]]},{"word":"乗り換えます","reading":"のりかえます","meaning":"chuyển xe","hanViet":"","lesson":16,"ex":[["次の駅で電車を乗り換えます。","Tôi chuyển tàu ở ga tiếp theo."],["駅でバスに乗り換えます。","Tôi chuyển sang xe buýt ở ga."],["電車からバスに乗り換えました。","Tôi đã chuyển từ tàu điện sang xe buýt."],["次の駅で乗り換えますか。","Bạn có chuyển xe ở ga tiếp theo không?"],["地下鉄に乗り換えて、会社へ行きます。","Tôi chuyển sang tàu điện ngầm rồi đến công ty."]]},{"word":"浴びます","reading":"あびます","meaning":"tắm","hanViet":"","lesson":16,"ex":[["毎朝シャワーを浴びます。","Mỗi sáng tôi tắm vòi sen."],["夜、シャワーを浴びます。","Buổi tối tôi tắm vòi sen."],["暑い日はシャワーを浴びます。","Ngày nóng tôi tắm vòi sen."],["シャワーを浴びて、寝ます。","Tôi tắm vòi sen rồi đi ngủ."],["きょうはシャワーを浴びませんでした。","Hôm nay tôi đã không tắm vòi sen."]]},{"word":"入れます","reading":"いれます","meaning":"cho vào, bỏ vào","hanViet":"NHẬP","lesson":16,"ex":[["コーヒーに砂糖を入れます。","Tôi cho đường vào cà phê."],["お茶に砂糖を入れません。","Tôi không cho đường vào trà."],["かばんに本を入れます。","Tôi cho sách vào cặp."],["冷蔵庫に牛乳を入れます。","Tôi cho sữa vào tủ lạnh."],["コーヒーにミルクを入れてください。","Xin hãy cho sữa vào cà phê."]]},{"word":"やめます","reading":"やめます","meaning":"bỏ, thôi","hanViet":"","lesson":16,"ex":[["たばこをやめます。","Tôi bỏ thuốc lá."],["会社をやめました。","Tôi đã nghỉ công ty."],["仕事をやめます。","Tôi bỏ việc."],["酒をやめます。","Tôi bỏ rượu."],["あしたから、たばこをやめます。","Từ ngày mai tôi sẽ bỏ thuốc lá."]]},{"word":"押します","reading":"おします","meaning":"bấm, ấn","hanViet":"","lesson":16,"ex":[["ボタンを押します。","Tôi bấm nút."],["エレベーターのボタンを押して、上へ行きます。","Tôi bấm nút thang máy và đi lên."],["エレベーターのボタンを押しました。","Tôi đã bấm nút thang máy."],["ボタンを押して、テレビをつけます。","Tôi bấm nút và bật ti vi."],["ボタンを押して、エレベーターに乗ります。","Tôi bấm nút rồi lên thang máy."]]},{"word":"若い","reading":"わかい","meaning":"trẻ, trẻ tuổi","hanViet":"NHƯỢC","lesson":16,"ex":[["田中さんは若いです。","Anh Tanaka còn trẻ."],["山田さんは若いです。","Anh Yamada còn trẻ."],["私の先生は若いです。","Thầy giáo của tôi còn trẻ."],["あの女の人は若いですか。","Người phụ nữ kia còn trẻ phải không?"],["若い人は元気です。","Người trẻ thì khỏe mạnh."]]},{"word":"長い","reading":"ながい","meaning":"Dài","hanViet":"TRƯỜNG","lesson":16,"ex":[["この川は長いです。","Con sông này dài."],["この道は長いです。","Con đường này dài."],["山田さんの髪は長いです。","Tóc của anh Yamada dài."],["長い時間、勉強します。","Tôi học trong thời gian dài."],["夏の休みは長いです。","Kỳ nghỉ hè dài."]]},{"word":"短い","reading":"みじかい","meaning":"Ngắn","hanViet":"ĐOẢN","lesson":16,"ex":[["この鉛筆は短いです。","Cây bút chì này ngắn."],["この道は短いです。","Con đường này ngắn."],["私の髪は短いです。","Tóc tôi ngắn."],["昼休みは短いです。","Giờ nghỉ trưa ngắn."],["短い手紙を書きました。","Tôi đã viết một bức thư ngắn."]]},{"word":"明るい","reading":"あかるい","meaning":"Sáng, sáng sủa","hanViet":"MINH","lesson":16,"ex":[["この部屋は明るいです。","Căn phòng này sáng sủa."],["この教室は明るいです。","Phòng học này sáng sủa."],["昼は明るいです。","Ban ngày thì sáng."],["明るい部屋が好きです。","Tôi thích căn phòng sáng sủa."],["田中さんは明るい人です。","Anh Tanaka là người vui vẻ."]]},{"word":"暗い","reading":"くらい","meaning":"Tối","hanViet":"ÁM","lesson":16,"ex":[["この部屋は暗いです。","Căn phòng này tối."],["この教室は暗いです。","Phòng học này tối."],["夜は暗いです。","Ban đêm thì tối."],["暗い部屋は嫌いです。","Tôi ghét căn phòng tối."],["山の夜は暗いです。","Ban đêm trên núi thì tối."]]},{"word":"背が高い","reading":"せがたかい","meaning":"cao (người)","hanViet":"","lesson":16,"ex":[["田中さんは背が高いです。","Anh Tanaka cao."],["山田さんは背が高いです。","Anh Yamada cao."],["私の兄は背が高いです。","Anh trai tôi cao."],["あの男の人は背が高いです。","Người đàn ông kia cao."],["山田さんは田中さんより背が高いです。","Anh Yamada cao hơn anh Tanaka."]]},{"word":"頭がいい","reading":"あたまがいい","meaning":"thông minh (người)","hanViet":"","lesson":16,"ex":[["田中さんは頭がいいです。","Anh Tanaka thông minh."],["山田さんは頭がいいです。","Anh Yamada thông minh."],["私の友達は頭がいいです。","Bạn tôi thông minh."],["あの学生は頭がいいです。","Học sinh kia thông minh."],["山田さんは田中さんより頭がいいです。","Anh Yamada thông minh hơn anh Tanaka."]]},{"word":"体","reading":"からだ","meaning":"Cơ thể","hanViet":"THỂ","lesson":16,"ex":[["体を洗います。","Tôi tắm rửa người."],["体が痛いです。","Tôi đau người."],["体にいい食べ物を食べます。","Tôi ăn đồ ăn tốt cho cơ thể."],["毎日歩いて、体を元気にします。","Mỗi ngày tôi đi bộ để cơ thể khỏe mạnh."],["体が強いです。","Cơ thể tôi khỏe mạnh."]]},{"word":"頭","reading":"あたま","meaning":"cái đầu","hanViet":"ĐẦU","lesson":16,"ex":[["頭を洗います。","Tôi gội đầu."],["頭が痛いですから、薬を飲みます。","Vì đau đầu nên tôi uống thuốc."],["頭が大きいです。","Đầu to."],["頭に帽子をかぶります。","Tôi đội mũ lên đầu."],["子どもの頭は小さいです。","Đầu của trẻ em nhỏ."]]},{"word":"髪","reading":"かみ","meaning":"tóc","hanViet":"","lesson":16,"ex":[["田中さんの髪は長いです。","Tóc của anh Tanaka dài."],["山田さんの髪は短いです。","Tóc của anh Yamada ngắn."],["髪を洗います。","Tôi gội đầu."],["髪を切ります。","Tôi cắt tóc."],["私の髪は黒いです。","Tóc tôi đen."]]},{"word":"顔","reading":"かお","meaning":"mặt","hanViet":"","lesson":16,"ex":[["田中さんの顔は小さいです。","Mặt của anh Tanaka nhỏ."],["顔を洗います。","Tôi rửa mặt."],["山田さんの顔は大きいです。","Mặt của anh Yamada to."],["赤ちゃんの顔は小さいです。","Mặt của em bé nhỏ."],["顔が赤いです。","Mặt đỏ."]]},{"word":"目","reading":"め","meaning":"Mắt","hanViet":"MỤC","lesson":16,"ex":[["山田さんは目が大きいです。","Chị Yamada có đôi mắt to."],["目が痛いです。","Tôi đau mắt."],["田中さんは目が小さいです。","Anh Tanaka có đôi mắt nhỏ."],["目が疲れました。","Mắt tôi mỏi."],["赤ちゃんは目が大きいです。","Em bé có đôi mắt to."]]},{"word":"耳","reading":"みみ","meaning":"Tai","hanViet":"NHĨ","lesson":16,"ex":[["耳が痛いです。","Tôi đau tai."],["私の耳は大きいです。","Tai tôi to."],["犬の耳は小さいです。","Tai chó nhỏ."],["耳がかゆいです。","Tai tôi ngứa."],["耳を洗います。","Tôi rửa tai."]]},{"word":"口","reading":"くち","meaning":"Miệng","hanViet":"KHẨU","lesson":16,"ex":[["赤ちゃんの口は小さいです。","Miệng của em bé nhỏ."],["口が小さいです。","Miệng nhỏ."],["口を開けます。","Tôi mở miệng."],["口を閉めます。","Tôi ngậm miệng."],["田中さんの口は大きいです。","Miệng của anh Tanaka to."]]},{"word":"歯","reading":"は","meaning":"Răng","hanViet":"XỈ","lesson":16,"ex":[["歯が白いです。","Răng trắng."],["姉の歯は白いです。","Răng của chị tôi thì trắng."],["歯を見せてください。","Xin hãy cho tôi xem răng."],["子どもの歯は白いです。","Răng của trẻ em trắng."],["歯が強いです。","Răng chắc khỏe."]]},{"word":"おなか","reading":"おなか","meaning":"bụng","hanViet":"","lesson":16,"ex":[["おなかがすきました。","Tôi đói bụng."],["おなかが痛いですから、病院へ行きます。","Vì đau bụng nên tôi đi bệnh viện."],["おなかがすきましたから、昼ごはんを食べます。","Vì đói bụng nên tôi ăn trưa."],["おなかは大丈夫ですか。","Bụng bạn có sao không?"],["ごはんを食べて、おなかがいっぱいです。","Ăn cơm xong, tôi no bụng."]]},{"word":"足","reading":"あし","meaning":"Chân","hanViet":"TÚC","lesson":16,"ex":[["足が痛いです。","Tôi đau chân."],["足が長いです。","Chân dài."],["足を洗います。","Tôi rửa chân."],["足が疲れました。","Chân tôi mỏi."],["子どもの足は小さいです。","Chân của trẻ em nhỏ."]]},{"word":"寺","reading":"てら","meaning":"chùa","hanViet":"TỰ","lesson":16,"ex":[["山の近くに寺があります。","Gần núi có chùa."],["あした、寺へ行きます。","Ngày mai tôi đi chùa."],["山の寺を見ます。","Tôi ngắm chùa trên núi."],["この寺は古いです。","Ngôi chùa này cổ."],["寺は静かです。","Chùa yên tĩnh."]]},{"word":"神社","reading":"じんじゃ","meaning":"Đền thờ Thần đạo","hanViet":"THẦN XÃ","lesson":16,"ex":[["町の神社に行きます。","Tôi đi đến đền thờ Thần đạo trong thị trấn."],["あした、神社へ行きます。","Ngày mai tôi đi đền thờ Thần đạo."],["神社は山の近くにあります。","Đền thờ Thần đạo ở gần núi."],["この神社は大きいです。","Đền thờ Thần đạo này to."],["神社で写真を撮ります。","Tôi chụp ảnh ở đền thờ Thần đạo."]]},{"word":"まず","reading":"まず","meaning":"trước tiên","hanViet":"","lesson":16,"ex":[["まず、手を洗います。","Trước tiên, tôi rửa tay."],["まず、顔を洗います。","Trước tiên, tôi rửa mặt."],["まず、宿題をして、テレビを見ます。","Trước tiên tôi làm bài tập, rồi xem ti vi."],["まず、駅へ行って、切符を買います。","Trước tiên tôi đến ga, rồi mua vé."],["まず、日本語を勉強します。","Trước tiên, tôi học tiếng Nhật."]]},{"word":"お引き出しですか。","reading":"おひきだしですか。","meaning":"anh/chị rút tiền ạ?","hanViet":"","lesson":16,"ex":[["お引き出しですか。","Anh/chị rút tiền ạ?"],["銀行員は「お引き出しですか。」と聞きました。","Nhân viên ngân hàng hỏi: \"Anh/chị rút tiền ạ?\""],["銀行へ行くと、銀行員が「お引き出しですか。」と聞きます。","Khi tôi đến ngân hàng, nhân viên ngân hàng hỏi: \"Anh/chị rút tiền ạ?\""],["エーティーエムの前で銀行員が「お引き出しですか。」と言いました。","Trước máy ATM, nhân viên ngân hàng nói: \"Anh/chị rút tiền ạ?\""],["銀行員が「お引き出しですか。」と聞きましたから、「はい」と言いました。","Vì nhân viên ngân hàng hỏi: \"Anh/chị rút tiền ạ?\" nên tôi đã nói: \"Vâng.\""]]},{"word":"次に","reading":"つぎに","meaning":"tiếp theo","hanViet":"","lesson":16,"ex":[["まず手を洗って、次にごはんを食べます。","Trước tiên tôi rửa tay, tiếp theo tôi ăn cơm."],["手を洗って、次に顔を洗います。","Tôi rửa tay, tiếp theo rửa mặt."],["ごはんを食べて、次にテレビを見ます。","Tôi ăn cơm, tiếp theo xem ti vi."],["日本語を勉強して、次に宿題をします。","Tôi học tiếng Nhật, tiếp theo làm bài tập."],["駅へ行って、次に電車に乗ります。","Tôi đến ga, tiếp theo lên tàu điện."]]},{"word":"お預け入れ","reading":"おあずけいれ","meaning":"gửi tiền (vào tài khoản)","hanViet":"","lesson":16,"ex":[["銀行でお預け入れをします。","Tôi gửi tiền vào tài khoản ở ngân hàng."],["エーティーエムでお預け入れをします。","Tôi gửi tiền vào tài khoản ở máy ATM."],["お預け入れができますか。","Có thể gửi tiền được không?"],["お預け入れをしたいです。","Tôi muốn gửi tiền."],["午前にお預け入れをします。","Tôi gửi tiền vào buổi sáng."]]},{"word":"お振込み","reading":"おふりこみ","meaning":"chuyển tiền","hanViet":"","lesson":16,"ex":[["銀行でお振込みをします。","Tôi chuyển tiền ở ngân hàng."],["エーティーエムでお振込みをします。","Tôi chuyển tiền ở máy ATM."],["友達にお振込みをします。","Tôi chuyển tiền cho bạn."],["お振込みをしたいです。","Tôi muốn chuyển tiền."],["午後にお振込みをしました。","Tôi đã chuyển tiền vào buổi chiều."]]},{"word":"お振り替え","reading":"おふりかえ","meaning":"chuyển khoản","hanViet":"","lesson":16,"ex":[["エーティーエムでお振り替えをします。","Tôi chuyển khoản ở máy ATM."],["銀行でお振り替えをします。","Tôi chuyển khoản ở ngân hàng."],["お振り替えができますか。","Có thể chuyển khoản được không?"],["お振り替えをしたいです。","Tôi muốn chuyển khoản."],["午前にお振り替えをしました。","Tôi đã chuyển khoản vào buổi sáng."]]},{"word":"通帳記入","reading":"つうちょうきにゅう","meaning":"kí sổ ngân hàng","hanViet":"","lesson":16,"ex":[["銀行で通帳記入をします。","Tôi làm thủ tục ghi sổ ở ngân hàng."],["エーティーエムで通帳記入をします。","Tôi làm thủ tục ghi sổ ở máy ATM."],["通帳記入ができますか。","Có thể ghi sổ được không?"],["通帳記入をしたいです。","Tôi muốn ghi sổ."],["きょう、銀行で通帳記入をしました。","Hôm nay tôi đã làm thủ tục ghi sổ ở ngân hàng."]]},{"word":"残高照会","reading":"ざんだかしょうかい","meaning":"kiểm tra số dư trong tài khoản","hanViet":"","lesson":16,"ex":[["エーティーエムで残高照会をします。","Tôi kiểm tra số dư tài khoản ở máy ATM."],["銀行で残高照会をします。","Tôi kiểm tra số dư tài khoản ở ngân hàng."],["残高照会ができますか。","Có thể kiểm tra số dư tài khoản được không?"],["残高照会をしたいです。","Tôi muốn kiểm tra số dư tài khoản."],["きょう、エーティーエムで残高照会をしました。","Hôm nay tôi đã kiểm tra số dư tài khoản ở máy ATM."]]},{"word":"暗証番号","reading":"あんしょうばんごう","meaning":"mã PIN, mật khẩu","hanViet":"","lesson":16,"ex":[["暗証番号を押します。","Tôi bấm mã PIN."],["暗証番号を押してください。","Hãy bấm mã PIN."],["暗証番号を忘れました。","Tôi quên mã PIN rồi."],["暗証番号がわかりません。","Tôi không biết mã PIN."],["暗証番号を教えてください。","Hãy cho tôi biết mã PIN."]]},{"word":"サービス","reading":"サービス","meaning":"dịch vụ","hanViet":"","lesson":16,"ex":[["このホテルのサービスはいいです。","Dịch vụ của khách sạn này tốt."],["このレストランのサービスはいいです。","Dịch vụ của nhà hàng này tốt."],["日本のサービスはいいです。","Dịch vụ của Nhật tốt."],["サービスはいいですか。","Dịch vụ có tốt không ạ?"],["このホテルのサービスはどうですか。","Dịch vụ của khách sạn này thế nào?"]]},{"word":"ジョギング","reading":"ジョギング","meaning":"chạy bộ","hanViet":"","lesson":16,"ex":[["毎朝ジョギングをします。","Mỗi sáng tôi chạy bộ."],["毎晩ジョギングをします。","Mỗi tối tôi chạy bộ."],["公園でジョギングをします。","Tôi chạy bộ ở công viên."],["友達とジョギングをします。","Tôi chạy bộ cùng bạn."],["あした、ジョギングをします。","Ngày mai tôi sẽ chạy bộ."]]},{"word":"シャワー","reading":"シャワー","meaning":"vòi hoa sen","hanViet":"","lesson":16,"ex":[["シャワーを浴びます。","Tôi tắm vòi sen."],["朝、シャワーを浴びて、会社へ行きます。","Buổi sáng tôi tắm vòi sen rồi đi làm."],["寝る前にシャワーを浴びます。","Trước khi ngủ tôi tắm vòi sen."],["シャワーはどこですか。","Vòi hoa sen ở đâu ạ?"],["シャワーを浴びますか。","Bạn có tắm vòi sen không?"]]},{"word":"キャッシュカード","reading":"キャッシュカード","meaning":"thẻ ngân hàng, thẻ ATM","hanViet":"","lesson":16,"ex":[["キャッシュカードでお金を引きます。","Tôi rút tiền bằng thẻ ATM."],["キャッシュカードを忘れました。","Tôi quên thẻ ATM rồi."],["キャッシュカードを持っています。","Tôi có thẻ ATM."],["キャッシュカードはかばんにあります。","Thẻ ATM ở trong cặp."],["キャッシュカードをなくしました。","Tôi đánh mất thẻ ATM rồi."]]},{"word":"金額","reading":"きんがく","meaning":"Số tiền","hanViet":"KIM NGẠCH","lesson":16,"ex":[["金額を確認します。","Tôi xác nhận số tiền."],["金額は千円です。","Số tiền là 1000 yên."],["金額を確認してください。","Hãy xác nhận số tiền."],["金額がわかりません。","Tôi không biết số tiền."],["金額を確認しますか。","Bạn có xác nhận số tiền không?"]]},{"word":"確認","reading":"かくにん","meaning":"xác nhận, kiểm tra","hanViet":"XÁC NHẬN","lesson":16,"ex":[["電話番号を確認します。","Tôi xác nhận số điện thoại."],["住所を確認します。","Tôi xác nhận địa chỉ."],["時間を確認してください。","Hãy xác nhận giờ."],["名前を確認しましたか。","Bạn đã xác nhận tên chưa?"],["宿題を確認して、学校へ行きます。","Tôi xác nhận bài tập về nhà rồi đi học."]]},{"word":"ボタン","reading":"ボタン","meaning":"nút","hanViet":"","lesson":16,"ex":[["このボタンを押してください。","Hãy bấm nút này."],["赤いボタンを押します。","Tôi bấm nút đỏ."],["ボタンはどこですか。","Nút ở đâu ạ?"],["このボタンを押しますか。","Bạn có bấm nút này không?"],["ボタンを押して、ドアを開けます。","Tôi bấm nút rồi mở cửa."]]},{"word":"どうやって","reading":"どうやって","meaning":"làm thế nào","hanViet":"","lesson":16,"ex":[["どうやって行きますか。","Đi bằng cách nào ạ?"],["どうやって日本語を勉強しますか。","Bạn học tiếng Nhật bằng cách nào?"],["どうやって漢字を覚えますか。","Bạn nhớ chữ Hán bằng cách nào?"],["どうやってここへ来ましたか。","Bạn đã đến đây bằng cách nào?"],["どうやってお金を払いますか。","Tôi trả tiền bằng cách nào?"]]},{"word":"どの～","reading":"どの～","meaning":"cái nào ~","hanViet":"","lesson":16,"ex":[["どの電車に乗りますか。","Anh/chị lên tàu nào ạ?"],["どの本を読みますか。","Bạn đọc quyển sách nào?"],["どの服を買いますか。","Bạn mua bộ quần áo nào?"],["どのレストランへ行きますか。","Bạn đi nhà hàng nào?"],["どの写真が好きですか。","Bạn thích bức ảnh nào?"]]},{"word":"～番","reading":"～ばん","meaning":"số ~","hanViet":"","lesson":16,"ex":[["3番の電車に乗ります。","Tôi lên tàu số 3."],["1番のバスに乗ります。","Tôi lên xe buýt số 1."],["三番の電車に乗ります。","Tôi lên tàu số 3."],["3番のバスに乗りますか。","Bạn có lên xe buýt số 3 không?"],["私の番号は5番です。","Số của tôi là số 5."]]},{"word":"いいえ、まだまだです","reading":"いいえ、まだまだです","meaning":"không, tôi còn kém lắm","hanViet":"","lesson":16,"ex":[["日本語は上手ですか。いいえ、まだまだです。","Tiếng Nhật của bạn giỏi à? Không, tôi còn kém lắm."],["英語は上手ですか。いいえ、まだまだです。","Tiếng Anh của bạn giỏi à? Không, tôi còn kém lắm."],["ピアノは上手ですか。いいえ、まだまだです。","Bạn chơi piano giỏi à? Không, tôi còn kém lắm."],["日本語ができますか。いいえ、まだまだです。","Bạn biết tiếng Nhật à? Không, tôi còn kém lắm."],["料理は上手ですか。いいえ、まだまだです。","Bạn nấu ăn giỏi à? Không, tôi còn kém lắm."]]},{"word":"覚えます","reading":"おばえます","meaning":"nhớ","hanViet":"","lesson":17,"ex":[["新しい漢字を覚えます。","Tôi nhớ chữ Hán mới."],["日本語のことばを覚えます。","Tôi nhớ từ tiếng Nhật."],["電話番号を覚えましたか。","Bạn đã nhớ số điện thoại chưa?"],["友達の名前を覚えてください。","Hãy nhớ tên của bạn."],["歌を覚えて、歌います。","Tôi nhớ bài hát rồi hát."]]},{"word":"忘れます","reading":"わすれます","meaning":"quên","hanViet":"","lesson":17,"ex":[["宿題を忘れました。","Tôi quên bài tập về nhà."],["かばんを忘れました。","Tôi quên cặp rồi."],["傘を忘れましたか。","Bạn quên ô rồi à?"],["約束を忘れないでください。","Xin đừng quên lời hẹn."],["本を忘れて、学校へ行きました。","Tôi quên sách rồi đi học."]]},{"word":"なくします","reading":"なくします","meaning":"mất, đánh mất","hanViet":"","lesson":17,"ex":[["鍵をなくしました。","Tôi đánh mất chìa khóa."],["かばんをなくしましたから、先生に話します。","Vì đánh mất cặp nên tôi nói với thầy."],["電車で傘をなくしました。","Tôi đã đánh mất ô trên tàu điện."],["手袋をなくしましたか。","Bạn đánh mất găng tay rồi à?"],["切符をなくしました。","Tôi đánh mất vé rồi."]]},{"word":"払います","reading":"はらいます","meaning":"trả tiền","hanViet":"","lesson":17,"ex":[["お金を払います。","Tôi trả tiền."],["レストランでお金を払います。","Tôi trả tiền ở nhà hàng."],["家賃を払います。","Tôi trả tiền thuê nhà."],["カードで払います。","Tôi trả bằng thẻ."],["デパートでカードで払います。","Tôi trả bằng thẻ ở cửa hàng bách hóa."]]},{"word":"返します","reading":"かえします","meaning":"trả lại","hanViet":"","lesson":17,"ex":[["友達に本を返します。","Tôi trả sách cho bạn."],["図書館に本を返します。","Tôi trả sách cho thư viện."],["友達にお金を返します。","Tôi trả tiền cho bạn."],["先生に辞書を返します。","Tôi trả từ điển cho thầy."],["かばんを返してください。","Hãy trả lại cặp cho tôi."]]},{"word":"出かけます","reading":"でかけます","meaning":"ra ngoài","hanViet":"XUẤT","lesson":17,"ex":[["あした、友達と出かけます。","Ngày mai tôi ra ngoài cùng bạn."],["公園へ出かけます。","Tôi đi ra công viên."],["友達とデパートへ出かけます。","Tôi cùng bạn đi cửa hàng bách hóa."],["あした、友達と映画館へ出かけます。","Ngày mai tôi cùng bạn đi rạp phim."],["日曜日、友達と公園へ出かけます。","Chủ nhật tôi cùng bạn đi công viên."]]},{"word":"脱ぎます","reading":"ぬぎます","meaning":"cởi (quần áo)","hanViet":"","lesson":17,"ex":[["靴を脱ぎます。","Tôi cởi giày."],["帽子を脱ぎます。","Tôi cởi mũ."],["コートを脱いでください。","Hãy cởi áo khoác."],["うちでセーターを脱ぎます。","Tôi cởi áo len ở nhà."],["手袋を脱ぎましたか。","Bạn đã cởi găng tay chưa?"]]},{"word":"持っていきます","reading":"もっていきます","meaning":"mang đi, mang theo","hanViet":"","lesson":17,"ex":[["学校へ本を持っていきます。","Tôi mang sách đến trường."],["傘を持っていきます。","Tôi mang ô đi."],["学校へ弁当を持っていきます。","Tôi mang hộp cơm đến trường."],["カメラを持っていきますか。","Bạn có mang máy ảnh đi không?"],["お土産を持っていきます。","Tôi mang quà đi."]]},{"word":"持ってきます","reading":"もってきます","meaning":"mang đến","hanViet":"","lesson":17,"ex":[["あした、本を持ってきます。","Ngày mai tôi mang sách đến."],["お茶を持ってきます。","Tôi mang trà đến."],["お菓子を持ってきますか。","Bạn có mang bánh kẹo đến không?"],["あした、写真を持ってきます。","Ngày mai tôi mang ảnh đến."],["辞書を持ってきてください。","Hãy mang từ điển đến."]]},{"word":"心配します","reading":"しんぱいします","meaning":"lo lắng","hanViet":"","lesson":17,"ex":[["母は私を心配します。","Mẹ lo lắng cho tôi."],["試験を心配します。","Tôi lo lắng về kỳ thi."],["天気を心配しますか。","Bạn có lo lắng về thời tiết không?"],["友達を心配しています。","Tôi đang lo lắng cho bạn."],["子どもを心配します。","Tôi lo lắng cho con."]]},{"word":"残業します","reading":"ざんぎょうします","meaning":"làm thêm","hanViet":"","lesson":17,"ex":[["きょう、残業します。","Hôm nay tôi làm thêm."],["毎日、残業します。","Mỗi ngày tôi làm thêm."],["きのう、夜まで残業しました。","Hôm qua tôi làm thêm đến tối."],["あしたは残業しません。","Ngày mai tôi không làm thêm."],["今週、残業します。","Tuần này tôi làm thêm."]]},{"word":"出張します","reading":"しゅっちょうします","meaning":"đi công tác","hanViet":"","lesson":17,"ex":[["来週、出張します。","Tuần sau tôi đi công tác."],["中国へ出張します。","Tôi đi công tác ở Trung Quốc."],["アメリカへ出張します。","Tôi đi công tác ở Mỹ."],["来月、出張します。","Tháng sau tôi đi công tác."],["きのう、出張しました。","Hôm qua tôi đi công tác."]]},{"word":"大切","reading":"たいせつ","meaning":"Quý trọng, quan trọng","hanViet":"ĐẠI THIẾT","lesson":17,"ex":[["私の家族は大切です。","Gia đình tôi rất quan trọng."],["友達は大切です。","Bạn bè rất quan trọng."],["時間は大切です。","Thời gian rất quan trọng."],["この写真は大切です。","Bức ảnh này rất quan trọng."],["大切な友達と話します。","Tôi nói chuyện với người bạn quan trọng."]]},{"word":"大丈夫","reading":"だいじょうぶ","meaning":"không sao, ổn","hanViet":"ĐẠI TRƯỢNG PHU","lesson":17,"ex":[["私は大丈夫です。","Tôi ổn."],["大丈夫ですか。","Bạn có ổn không?"],["試験は大丈夫です。","Kỳ thi thì ổn."],["お金は大丈夫です。","Tiền thì ổn."],["あしたは大丈夫です。","Ngày mai thì ổn."]]},{"word":"危ない","reading":"あぶない","meaning":"Nguy hiểm; suýt nữa thì...","hanViet":"NGUY","lesson":17,"ex":[["この道は危ないです。","Con đường này nguy hiểm."],["夜の道は危ないです。","Đường buổi tối nguy hiểm."],["危ないですから、気をつけてください。","Nguy hiểm đấy, hãy cẩn thận."],["ここは危ないです。","Chỗ này nguy hiểm."],["車が多いですから、危ないです。","Vì nhiều xe nên nguy hiểm."]]},{"word":"問題","reading":"もんだい","meaning":"Vấn đề, câu hỏi (bài tập)","hanViet":"VẤN ĐỀ","lesson":17,"ex":[["この問題は難しいです。","Câu hỏi này khó."],["問題がわかります。","Tôi hiểu câu hỏi."],["問題を考えます。","Tôi suy nghĩ về câu hỏi."],["試験の問題は易しいです。","Câu hỏi trong kỳ thi dễ."],["問題を読みます。","Tôi đọc câu hỏi."]]},{"word":"答え","reading":"こたえ","meaning":"Đáp án, câu trả lời","hanViet":"ĐÁP","lesson":17,"ex":[["答えを書きます。","Tôi viết đáp án."],["答えがわかります。","Tôi biết đáp án."],["答えを考えます。","Tôi suy nghĩ về đáp án."],["答えを教えてください。","Hãy cho tôi biết đáp án."],["答えを言います。","Tôi nói đáp án."]]},{"word":"禁煙","reading":"きんえん","meaning":"Cấm hút thuốc","hanViet":"CẤM YÊN","lesson":17,"ex":[["この部屋は禁煙です。","Phòng này cấm hút thuốc."],["ここは禁煙です。","Chỗ này cấm hút thuốc."],["病院は禁煙です。","Bệnh viện cấm hút thuốc."],["電車の中は禁煙です。","Trong tàu cấm hút thuốc."],["禁煙ですから、たばこを吸いません。","Vì cấm hút thuốc nên tôi không hút thuốc."]]},{"word":"保険証","reading":"ほけんしょう","meaning":"thẻ bảo hiểm","hanViet":"","lesson":17,"ex":[["保険証はかばんにあります。","Thẻ bảo hiểm ở trong cặp."],["保険証を持っていきます。","Tôi mang thẻ bảo hiểm đi."],["保険証を忘れました。","Tôi quên thẻ bảo hiểm rồi."],["保険証はうちにあります。","Thẻ bảo hiểm ở nhà."],["病院へ保険証を持っていきます。","Tôi mang thẻ bảo hiểm đến bệnh viện."]]},{"word":"かぜ","reading":"かぜ","meaning":"cảm, cúm","hanViet":"","lesson":17,"ex":[["かぜをひきました。","Tôi bị cảm."],["かぜをひきましたから、学校を休みます。","Vì bị cảm nên tôi nghỉ học."],["かぜをひきましたか。","Bạn bị cảm à?"],["冬にかぜをひきます。","Vào mùa đông tôi bị cảm."],["かぜで熱があります。","Vì bị cảm nên tôi bị sốt."]]},{"word":"熱","reading":"ねつ","meaning":"Sốt; nhiệt độ","hanViet":"NHIỆT","lesson":17,"ex":[["熱が少し高いです。","Tôi sốt hơi cao."],["熱が高いです。","Tôi sốt cao."],["熱が出ました。","Tôi bị sốt."],["熱が高いですか。","Bạn có sốt cao không?"],["熱があるとき、薬を飲みます。","Khi bị sốt, tôi uống thuốc."]]},{"word":"病気","reading":"びょうき","meaning":"Bệnh, ốm","hanViet":"BỆNH KHÍ","lesson":17,"ex":[["父は病気です。","Bố tôi bị ốm."],["病気ですから、学校を休みます。","Vì bị ốm nên tôi nghỉ học."],["病気になりました。","Tôi bị ốm."],["病気ですか。","Bạn bị ốm à?"],["病気の友達にお見舞いに行きます。","Tôi đi thăm bạn bị ốm."]]},{"word":"薬","reading":"くすり","meaning":"Thuốc","hanViet":"DƯỢC","lesson":17,"ex":[["薬を飲みます。","Tôi uống thuốc."],["薬を飲みましたか。","Bạn đã uống thuốc chưa?"],["病院で薬をもらいました。","Tôi nhận thuốc ở bệnh viện."],["薬を買います。","Tôi mua thuốc."],["毎朝薬を飲みます。","Mỗi sáng tôi uống thuốc."]]},{"word":"ふろ","reading":"ふろ","meaning":"bồn tắm","hanViet":"","lesson":17,"ex":[["ふろに入ります。","Tôi vào bồn tắm."],["ふろに入って、寝ます。","Tôi vào bồn tắm rồi đi ngủ."],["毎晩ふろに入ります。","Mỗi tối tôi vào bồn tắm."],["ふろはどこですか。","Bồn tắm ở đâu ạ?"],["ふろに入りますか。","Bạn có vào bồn tắm không?"]]},{"word":"上着","reading":"うわぎ","meaning":"Áo khoác ngoài","hanViet":"THƯỢNG TRƯỚC","lesson":17,"ex":[["上着を脱ぎます。","Tôi cởi áo khoác ngoài."],["上着を着ます。","Tôi mặc áo khoác ngoài."],["上着を買います。","Tôi mua áo khoác ngoài."],["上着を忘れました。","Tôi quên áo khoác ngoài rồi."],["この上着は新しいです。","Áo khoác ngoài này mới."]]},{"word":"下着","reading":"したぎ","meaning":"Đồ lót","hanViet":"HẠ TRƯỚC","lesson":17,"ex":[["下着を買います。","Tôi mua đồ lót."],["下着を洗います。","Tôi giặt đồ lót."],["下着を買いました。","Tôi đã mua đồ lót."],["下着はどこにありますか。","Đồ lót ở đâu ạ?"],["新しい下着を買います。","Tôi mua đồ lót mới."]]},{"word":"どうしましたか。","reading":"どうしましたか。","meaning":"anh/chị bị sao thế?","hanViet":"","lesson":17,"ex":[["山田さん、どうしましたか。","Anh Yamada, anh bị sao thế?"],["田中さん、どうしましたか。","Anh Tanaka, anh bị sao thế?"],["お母さん、どうしましたか。","Mẹ ơi, mẹ bị sao thế?"],["どうしましたか。頭が痛いですか。","Bạn bị sao thế? Bạn đau đầu à?"],["どうしましたか。熱がありますか。","Bạn bị sao thế? Bạn có bị sốt không?"]]},{"word":"頭が痛い","reading":"あたまがいたい","meaning":"đau đầu","hanViet":"","lesson":17,"ex":[["頭が痛いです。","Tôi đau đầu."],["頭が痛いですから、学校を休みます。","Vì đau đầu nên tôi nghỉ học."],["頭が痛いですか。","Bạn đau đầu à?"],["頭が痛いです。薬を飲みます。","Tôi đau đầu. Tôi uống thuốc."],["頭が痛いけど、仕事をします。","Tuy đau đầu nhưng tôi vẫn làm việc."]]},{"word":"おなかが痛い","reading":"おなかが痛い","meaning":"đau bụng","hanViet":"","lesson":17,"ex":[["おなかが痛いです。","Tôi đau bụng."],["おなかが痛いですから、ごはんを食べません。","Vì đau bụng nên tôi không ăn cơm."],["おなかが痛いですか。","Bạn đau bụng à?"],["おなかが痛いです。病院へ行きます。","Tôi đau bụng. Tôi đi bệnh viện."],["おなかが痛いけど、薬を飲みました。","Tuy đau bụng nhưng tôi đã uống thuốc."]]},{"word":"歯が痛い","reading":"はがいたい","meaning":"đau răng","hanViet":"","lesson":17,"ex":[["歯が痛いです。","Tôi đau răng."],["きのうから歯が痛いです。","Từ hôm qua tôi bị đau răng."],["歯が痛いですか。","Bạn đau răng à?"],["歯が痛いです。歯医者へ行きます。","Tôi đau răng. Tôi đi nha sĩ."],["歯が痛いけど、ごはんを食べます。","Tuy đau răng nhưng tôi vẫn ăn cơm."]]},{"word":"熱がある","reading":"ねつがある","meaning":"bị sốt","hanViet":"","lesson":17,"ex":[["熱があります。","Tôi bị sốt."],["熱がありますから、学校を休みます。","Vì bị sốt nên tôi nghỉ học."],["熱がありますか。","Bạn có bị sốt không?"],["熱があります。薬を飲みます。","Tôi bị sốt. Tôi uống thuốc."],["熱がありますけど、仕事をします。","Tuy bị sốt nhưng tôi vẫn làm việc."]]},{"word":"せきが出る","reading":"せきがでる","meaning":"ho","hanViet":"XUẤT","lesson":17,"ex":[["せきが出ます。","Tôi bị ho."],["せきが出ますから、病院へ行きます。","Vì bị ho nên tôi đi bệnh viện."],["せきが出ますか。","Bạn có bị ho không?"],["せきが出ます。薬を飲みます。","Tôi bị ho. Tôi uống thuốc."],["せきが出ますけど、学校へ行きます。","Tuy bị ho nhưng tôi vẫn đi học."]]},{"word":"鼻水が出る","reading":"はなみずがでる","meaning":"chảy nước mũi, sổ mũi","hanViet":"","lesson":17,"ex":[["鼻水が出ます。","Tôi bị chảy nước mũi."],["鼻水が出ますか。","Bạn có bị chảy nước mũi không?"],["鼻水が出ます。かぜです。","Tôi bị chảy nước mũi. Tôi bị cảm."],["鼻水が出ますけど、元気です。","Tuy bị chảy nước mũi nhưng tôi vẫn khỏe."],["かぜで鼻水が出ます。","Vì bị cảm nên tôi bị chảy nước mũi."]]},{"word":"血が出る","reading":"ちがでる","meaning":"chảy máu","hanViet":"","lesson":17,"ex":[["足をけがしました。血が出ます。","Tôi bị thương ở chân. Chân chảy máu."],["手をけがしました。血が出ます。","Tôi bị thương ở tay. Tay chảy máu."],["血が出ますから、病院へ行きます。","Vì chảy máu nên tôi đi bệnh viện."],["血が出ますか。","Bạn có bị chảy máu không?"],["血が出ます。痛いです。","Chảy máu rồi. Đau quá."]]},{"word":"吐き気がする","reading":"はきけがする","meaning":"buồn nôn","hanViet":"","lesson":17,"ex":[["吐き気がします。","Tôi buồn nôn."],["吐き気がしますから、ごはんを食べません。","Vì buồn nôn nên tôi không ăn cơm."],["吐き気がしますか。","Bạn có buồn nôn không?"],["吐き気がします。病院へ行きます。","Tôi buồn nôn. Tôi đi bệnh viện."],["吐き気がしますけど、仕事をします。","Tuy buồn nôn nhưng tôi vẫn làm việc."]]},{"word":"寒気がする","reading":"さむけがする","meaning":"gai người, ớn lạnh","hanViet":"","lesson":17,"ex":[["寒気がします。","Tôi thấy ớn lạnh."],["寒気がしますから、ふろに入ります。","Vì ớn lạnh nên tôi vào bồn tắm."],["寒気がしますか。","Bạn có thấy ớn lạnh không?"],["寒気がします。かぜです。","Tôi thấy ớn lạnh. Tôi bị cảm."],["寒気がしますけど、元気です。","Tuy thấy ớn lạnh nhưng tôi vẫn khỏe."]]},{"word":"下痢をする","reading":"げりをする","meaning":"tiêu chảy","hanViet":"","lesson":17,"ex":[["下痢をします。","Tôi bị tiêu chảy."],["下痢をしますから、学校を休みます。","Vì bị tiêu chảy nên tôi nghỉ học."],["下痢をしますか。","Bạn có bị tiêu chảy không?"],["下痢をします。薬を飲みます。","Tôi bị tiêu chảy. Tôi uống thuốc."],["下痢をしますけど、仕事をします。","Tuy bị tiêu chảy nhưng tôi vẫn làm việc."]]},{"word":"便秘をする","reading":"べんぴをする","meaning":"táo bón","hanViet":"","lesson":17,"ex":[["便秘をします。","Tôi bị táo bón."],["便秘をしますから、病院へ行きます。","Vì bị táo bón nên tôi đi bệnh viện."],["便秘をしますか。","Bạn có bị táo bón không?"],["便秘をします。薬を飲みます。","Tôi bị táo bón. Tôi uống thuốc."],["便秘をしますけど、元気です。","Tuy bị táo bón nhưng tôi vẫn khỏe."]]},{"word":"けがをする","reading":"けがをする","meaning":"bị thương","hanViet":"","lesson":17,"ex":[["サッカーでけがをしました。","Tôi bị thương khi chơi bóng đá."],["自転車でけがをしました。","Tôi bị thương vì xe đạp."],["けがをしましたから、病院へ行きます。","Vì bị thương nên tôi đi bệnh viện."],["けがをしましたか。","Bạn bị thương à?"],["けがをしました。足が痛いです。","Tôi bị thương. Chân tôi đau."]]},{"word":"やけどをする","reading":"やけどをする","meaning":"bị bỏng","hanViet":"","lesson":17,"ex":[["熱いお茶でやけどをしました。","Tôi bị bỏng vì trà nóng."],["料理でやけどをしました。","Tôi bị bỏng khi nấu ăn."],["やけどをしましたから、病院へ行きます。","Vì bị bỏng nên tôi đi bệnh viện."],["やけどをしましたか。","Bạn bị bỏng à?"],["やけどをしました。手が痛いです。","Tôi bị bỏng. Tay tôi đau."]]},{"word":"食欲がない","reading":"しょくよくがない","meaning":"không muốn ăn","hanViet":"","lesson":17,"ex":[["食欲がありません。","Tôi không muốn ăn."],["食欲がありませんから、ごはんを食べません。","Vì không muốn ăn nên tôi không ăn cơm."],["食欲がありませんか。","Bạn không muốn ăn à?"],["食欲がありません。病気です。","Tôi không muốn ăn. Tôi bị ốm."],["食欲がありませんけど、水を飲みます。","Tuy không muốn ăn nhưng tôi vẫn uống nước."]]},{"word":"肩がこる","reading":"かたがこる","meaning":"đau vai","hanViet":"","lesson":17,"ex":[["肩がこります。","Tôi bị đau vai."],["肩がこりますから、ふろに入ります。","Vì đau vai nên tôi vào bồn tắm."],["肩がこりますか。","Bạn có đau vai không?"],["肩がこります。仕事が忙しいです。","Tôi đau vai. Công việc bận."],["肩がこりますけど、元気です。","Tuy đau vai nhưng tôi vẫn khỏe."]]},{"word":"体がだるい","reading":"からだがだるい","meaning":"mỏi người","hanViet":"THỂ","lesson":17,"ex":[["体がだるいです。","Tôi mỏi người."],["体がだるいですから、学校を休みます。","Vì mỏi người nên tôi nghỉ học."],["体がだるいですか。","Bạn có mỏi người không?"],["体がだるいです。寝ます。","Tôi mỏi người. Tôi đi ngủ."],["体がだるいですけど、仕事をします。","Tuy mỏi người nhưng tôi vẫn làm việc."]]},{"word":"かゆい","reading":"かゆい","meaning":"ngứa","hanViet":"","lesson":17,"ex":[["足がかゆいです。","Chân tôi bị ngứa."],["手がかゆいです。","Tay tôi bị ngứa."],["顔がかゆいです。","Mặt tôi bị ngứa."],["目がかゆいです。","Mắt tôi bị ngứa."],["足がかゆいですから、病院へ行きます。","Vì chân bị ngứa nên tôi đi bệnh viện."]]},{"word":"盲腸","reading":"もうちょう","meaning":"ruột thừa","hanViet":"MANH TRÀNG","lesson":17,"ex":[["盲腸になりました。","Tôi bị đau ruột thừa."],["盲腸になりましたから、病院へ行きます。","Vì bị đau ruột thừa nên tôi đi bệnh viện."],["盲腸ですか。","Bạn bị đau ruột thừa à?"],["盲腸になりました。おなかが痛いです。","Tôi bị đau ruột thừa. Tôi đau bụng."],["盲腸になりましたから、学校を休みます。","Vì bị đau ruột thừa nên tôi nghỉ học."]]},{"word":"ぎっくり腰","reading":"ぎっくりごし","meaning":"trật đốt sống, trẹo hông","hanViet":"","lesson":17,"ex":[["ぎっくり腰になりました。","Tôi bị trẹo hông."],["ぎっくり腰になりましたから、病院へ行きます。","Vì bị trẹo hông nên tôi đi bệnh viện."],["ぎっくり腰ですか。","Bạn bị trẹo hông à?"],["ぎっくり腰になりました。仕事を休みます。","Tôi bị trẹo hông. Tôi nghỉ làm."],["ぎっくり腰になりましたから、寝ます。","Vì bị trẹo hông nên tôi đi ngủ."]]},{"word":"ねんざ","reading":"ねんざ","meaning":"bong gân","hanViet":"","lesson":17,"ex":[["足をねんざしました。","Tôi bị bong gân chân."],["手をねんざしました。","Tôi bị bong gân tay."],["ねんざしましたから、病院へ行きます。","Vì bị bong gân nên tôi đi bệnh viện."],["ねんざしましたか。","Bạn bị bong gân à?"],["サッカーでねんざしました。","Tôi bị bong gân khi chơi bóng đá."]]},{"word":"骨折","reading":"こっせつ","meaning":"Gãy xương","hanViet":"CỐT TRIẾT","lesson":17,"ex":[["足を骨折しました。","Tôi bị gãy xương chân."],["手を骨折しました。","Tôi bị gãy xương tay."],["骨折しましたから、病院へ行きます。","Vì bị gãy xương nên tôi đi bệnh viện."],["骨折しましたか。","Bạn bị gãy xương à?"],["自転車で骨折しました。","Tôi bị gãy xương vì xe đạp."]]},{"word":"二日酔い","reading":"ふつかよい","meaning":"say rượu kéo dài sang hôm sau","hanViet":"NHỊ NHẬT TÚY","lesson":17,"ex":[["きのう、酒をたくさん飲みました。二日酔いです。","Hôm qua tôi uống nhiều rượu. Tôi bị say rượu kéo dài sang hôm sau."],["二日酔いですから、学校を休みます。","Vì say rượu kéo dài sang hôm sau nên tôi nghỉ học."],["二日酔いですか。","Bạn bị say rượu kéo dài sang hôm sau à?"],["二日酔いです。頭が痛いです。","Tôi bị say rượu kéo dài sang hôm sau. Tôi đau đầu."],["ビールをたくさん飲みました。二日酔いです。","Tôi uống nhiều bia. Tôi bị say rượu kéo dài sang hôm sau."]]},{"word":"めまいがする","reading":"めまいがする","meaning":"chóng mặt","hanViet":"","lesson":17,"ex":[["めまいがします。","Tôi bị chóng mặt."],["めまいがしますから、学校を休みます。","Vì chóng mặt nên tôi nghỉ học."],["めまいがしますか。","Bạn có chóng mặt không?"],["めまいがします。病院へ行きます。","Tôi chóng mặt. Tôi đi bệnh viện."],["めまいがしますけど、元気です。","Tuy chóng mặt nhưng tôi vẫn khỏe."]]},{"word":"二、三日","reading":"に、さんにち","meaning":"vài ngày","hanViet":"NHỊ TAM NHẬT","lesson":17,"ex":[["二、三日、休みます。","Tôi nghỉ vài ngày."],["二、三日、学校を休みます。","Tôi nghỉ học vài ngày."],["二、三日、旅行に行きます。","Tôi đi du lịch vài ngày."],["二、三日、うちにいます。","Tôi ở nhà vài ngày."],["二、三日、薬を飲みます。","Tôi uống thuốc vài ngày."]]},{"word":"二、三～","reading":"に、さん～","meaning":"vài ~","hanViet":"","lesson":17,"ex":[["本を二、三冊買います。","Tôi mua vài quyển sách."],["友達が二、三人来ます。","Vài người bạn đến."],["りんごを二、三つ買います。","Tôi mua vài quả táo."],["写真を二、三枚撮ります。","Tôi chụp vài bức ảnh."],["本を二、三冊読みます。","Tôi đọc vài quyển sách."]]},{"word":"～までに","reading":"～までに","meaning":"trước ~ (chỉ thời hạn)","hanViet":"","lesson":17,"ex":[["五時までに宿題が終わります。","Bài tập sẽ xong trước 5 giờ."],["十二時までに寝ます。","Tôi đi ngủ trước 12 giờ."],["あしたまでに宿題をします。","Tôi làm bài tập trước ngày mai."],["来週までに手紙を書きます。","Tôi viết thư trước tuần sau."],["五時までに学校へ行きます。","Tôi đến trường trước 5 giờ."]]},{"word":"ですから","reading":"ですから","meaning":"vì thế, vì vậy","hanViet":"","lesson":17,"ex":[["あしたは雨です。ですから、うちにいます。","Ngày mai trời mưa. Vì thế tôi ở nhà."],["あしたは試験です。ですから、勉強します。","Ngày mai có kỳ thi. Vì thế tôi học."],["きょうは暑いです。ですから、水を飲みます。","Hôm nay trời nóng. Vì thế tôi uống nước."],["病気です。ですから、学校を休みます。","Tôi bị ốm. Vì thế tôi nghỉ học."],["日本語が難しいです。ですから、毎日勉強します。","Tiếng Nhật khó. Vì thế tôi học mỗi ngày."]]},{"word":"喉","reading":"のど","meaning":"cổ họng","hanViet":"","lesson":17,"ex":[["喉が痛いです。","Tôi đau họng."],["喉が痛いですから、病院へ行きます。","Vì đau họng nên tôi đi bệnh viện."],["喉が痛いですか。","Bạn đau họng à?"],["喉が痛いです。薬を飲みます。","Tôi đau họng. Tôi uống thuốc."],["喉がかわきました。水を飲みます。","Tôi khát nước. Tôi uống nước."]]},{"word":"お大事に","reading":"おだいじに","meaning":"chúc anh/chị mau khỏi bệnh","hanViet":"","lesson":17,"ex":[["山田さん、お大事に。","Anh Yamada, chúc anh mau khỏi bệnh."],["田中さん、お大事に。","Anh Tanaka, chúc anh mau khỏi bệnh."],["お母さん、お大事に。","Mẹ ơi, chúc mẹ mau khỏi bệnh."],["病気ですか。お大事に。","Bạn bị ốm à? Chúc bạn mau khỏi bệnh."],["かぜですか。お大事に。","Bạn bị cảm à? Chúc bạn mau khỏi bệnh."]]},{"word":"健康保険証","reading":"けんこうほけんしょう","meaning":"thẻ bảo hiểm y tế","hanViet":"","lesson":17,"ex":[["健康保険証を見せてください。","Cho tôi xem thẻ bảo hiểm y tế."],["健康保険証を持っていきます。","Tôi mang thẻ bảo hiểm y tế đi."],["健康保険証を忘れました。","Tôi quên thẻ bảo hiểm y tế rồi."],["健康保険証を見せます。","Tôi cho xem thẻ bảo hiểm y tế."],["健康保険証はどこですか。","Thẻ bảo hiểm y tế ở đâu ạ?"]]},{"word":"お風呂","reading":"おふろ","meaning":"bồn tắm","hanViet":"","lesson":17,"ex":[["お風呂に入ります。","Tôi vào bồn tắm."],["お風呂に入って、寝ます。","Tôi vào bồn tắm rồi đi ngủ."],["毎晩お風呂に入ります。","Mỗi tối tôi vào bồn tắm."],["お風呂に入りますか。","Bạn có vào bồn tắm không?"],["あした、お風呂に入ります。","Ngày mai tôi sẽ vào bồn tắm."]]},{"word":"痛いです","reading":"いたいです","meaning":"tôi bị đau","hanViet":"","lesson":17,"ex":[["ここが痛いです。","Chỗ này đau."],["足が痛いですから、今日は歩きません。","Vì chân bị đau nên hôm nay tôi không đi bộ."],["手が痛いですから、今日は仕事を休みます。","Vì tay bị đau nên hôm nay tôi nghỉ làm."],["どこが痛いですか。","Chỗ nào đau ạ?"],["ここが痛いですから、病院へ行きます。","Vì chỗ này đau nên tôi đi bệnh viện."]]},{"word":"できます","reading":"できます","meaning":"có thể","hanViet":"","lesson":18,"ex":[["わたしは日本語ができます。","Tôi biết tiếng Nhật."],["わたしは英語ができます。","Tôi biết tiếng Anh."],["水泳ができます。","Tôi biết bơi."],["サッカーができます。","Tôi biết chơi bóng đá."],["日本語で話すことができます。","Tôi có thể nói bằng tiếng Nhật."]]},{"word":"洗います","reading":"あらいます","meaning":"rửa","hanViet":"","lesson":18,"ex":[["手を洗います。","Tôi rửa tay."],["ごはんの前に、手を洗います。","Trước bữa ăn, tôi rửa tay."],["朝、顔を洗って、ごはんを食べます。","Buổi sáng tôi rửa mặt rồi ăn cơm."],["日曜日に服を洗います。","Chủ nhật tôi giặt quần áo."],["野菜を洗います。","Tôi rửa rau."]]},{"word":"弾きます","reading":"ひきます","meaning":"chơi (nhạc cụ)","hanViet":"","lesson":18,"ex":[["ピアノを弾きます。","Tôi chơi piano."],["ピアノを弾きますか。","Bạn có chơi piano không?"],["毎日ピアノを弾きます。","Mỗi ngày tôi chơi piano."],["友達とピアノを弾きます。","Tôi chơi piano cùng bạn."],["ピアノを弾くことができます。","Tôi có thể chơi piano."]]},{"word":"歌います","reading":"うたいます","meaning":"hát","hanViet":"","lesson":18,"ex":[["歌を歌います。","Tôi hát bài hát."],["田中さんはカラオケで日本の歌を歌います。","Anh Tanaka hát bài hát Nhật ở quán karaoke."],["友達と歌を歌います。","Tôi hát cùng bạn."],["日本の歌を歌います。","Tôi hát bài hát Nhật."],["歌を歌うことができます。","Tôi có thể hát."]]},{"word":"集めます","reading":"あつめます","meaning":"sưu tầm, thu thập","hanViet":"","lesson":18,"ex":[["切手を集めます。","Tôi sưu tầm tem."],["写真を集めます。","Tôi sưu tầm ảnh."],["本を集めています。","Tôi đang sưu tầm sách."],["絵を集めますか。","Bạn có sưu tầm tranh không?"],["おもちゃを集めます。","Tôi sưu tầm đồ chơi."]]},{"word":"捨てます","reading":"すてます","meaning":"vứt, bỏ đi","hanViet":"","lesson":18,"ex":[["古い新聞を捨てます。","Tôi vứt tờ báo cũ."],["古い服を捨てます。","Tôi vứt quần áo cũ."],["古い雑誌を捨てました。","Tôi đã vứt tạp chí cũ."],["古い本を捨てますか。","Bạn có vứt sách cũ không?"],["古い靴を捨ててください。","Hãy vứt giày cũ đi."]]},{"word":"換えます","reading":"かえます","meaning":"đổi","hanViet":"","lesson":18,"ex":[["お金を換えます。","Tôi đổi tiền."],["銀行でお金を換えます。","Tôi đổi tiền ở ngân hàng."],["空港でお金を換えます。","Tôi đổi tiền ở sân bay."],["旅行の前にお金を換えます。","Trước chuyến du lịch tôi đổi tiền."],["お金を換えますか。","Bạn có đổi tiền không?"]]},{"word":"運転します","reading":"うんてんします","meaning":"lái","hanViet":"","lesson":18,"ex":[["自動車を運転します。","Tôi lái ô tô."],["父は毎朝車を運転して会社へ行きます。","Mỗi sáng bố tôi lái xe đi làm."],["バスを運転します。","Tôi lái xe buýt."],["タクシーを運転します。","Tôi lái taxi."],["毎日自動車を運転します。","Mỗi ngày tôi lái ô tô."]]},{"word":"予約します","reading":"よやくします","meaning":"đặt chỗ","hanViet":"","lesson":18,"ex":[["ホテルを予約します。","Tôi đặt chỗ ở khách sạn."],["レストランを予約します。","Tôi đặt chỗ ở nhà hàng."],["飛行機を予約します。","Tôi đặt chỗ máy bay."],["新幹線を予約します。","Tôi đặt chỗ tàu Shinkansen."],["コンサートのチケットを予約します。","Tôi đặt vé hòa nhạc."]]},{"word":"見学します","reading":"けんがくします","meaning":"thăm quan để học tập","hanViet":"KIẾN HỌC","lesson":18,"ex":[["会社を見学します。","Tôi tham quan công ty để học tập."],["留学生は会社を見学しました。","Du học sinh đã tham quan công ty để học tập."],["学生は博物館を見学します。","Học sinh tham quan bảo tàng để học tập."],["わたしたちは動物園を見学します。","Chúng tôi tham quan vườn thú để học tập."],["来週、学校を見学します。","Tuần sau tôi tham quan trường học để học tập."]]},{"word":"国際~","reading":"こくさい~","meaning":"quốc tế","hanViet":"","lesson":18,"ex":[["国際電話をかけます。","Tôi gọi điện thoại quốc tế."],["国際会議があります。","Có hội nghị quốc tế."],["国際空港へ行きます。","Tôi đi đến sân bay quốc tế."],["国際ニュースを見ます。","Tôi xem tin tức quốc tế."],["国際電話は高いです。","Điện thoại quốc tế đắt."]]},{"word":"現金","reading":"げんきん","meaning":"Tiền mặt","hanViet":"HIỆN KIM","lesson":18,"ex":[["現金で払います。","Tôi trả bằng tiền mặt."],["現金で買います。","Tôi mua bằng tiền mặt."],["現金がありません。","Tôi không có tiền mặt."],["わたしは現金を持っています。","Tôi có mang tiền mặt."],["現金で払ってもいいですか。","Tôi trả bằng tiền mặt được không?"]]},{"word":"趣味","reading":"しゅみ","meaning":"sở thích","hanViet":"THÚ VỊ","lesson":18,"ex":[["趣味は音楽です。","Sở thích của tôi là âm nhạc."],["わたしの趣味は映画です。","Sở thích của tôi là phim ảnh."],["田中さんの趣味はゴルフです。","Sở thích của anh Tanaka là chơi gôn."],["趣味はスポーツと音楽です。","Sở thích của tôi là thể thao và âm nhạc."],["あなたの趣味は何ですか。","Sở thích của bạn là gì?"]]},{"word":"日記","reading":"にっき","meaning":"nhật ký","hanViet":"NHẬT KÍ","lesson":18,"ex":[["毎日日記を書きます。","Mỗi ngày tôi viết nhật ký."],["日本語で日記を書きます。","Tôi viết nhật ký bằng tiếng Nhật."],["毎晩日記を書きます。","Mỗi tối tôi viết nhật ký."],["日記を読んで、思い出します。","Tôi đọc nhật ký và nhớ lại."],["わたしの日記は日本語です。","Nhật ký của tôi viết bằng tiếng Nhật."]]},{"word":"祈り","reading":"いのり","meaning":"Lời cầu nguyện","hanViet":"KỲ","lesson":18,"ex":[["神社でお祈りをします。","Tôi cầu nguyện ở đền thờ."],["母は毎朝祈りをします。","Mẹ tôi cầu nguyện mỗi sáng."],["みんなで祈りをします。","Mọi người cùng cầu nguyện."],["祈りは大切です。","Lời cầu nguyện rất quan trọng."],["お正月に神社で祈りをします。","Vào dịp Tết tôi cầu nguyện ở đền thờ."]]},{"word":"課長","reading":"かちょう","meaning":"Trưởng phòng","hanViet":"KHÓA TRƯỞNG","lesson":18,"ex":[["田中さんは課長です。","Anh Tanaka là trưởng phòng."],["課長は会議に行きます。","Trưởng phòng đi họp."],["わたしの課長は山田さんです。","Trưởng phòng của tôi là anh Yamada."],["課長に会います。","Tôi gặp trưởng phòng."],["課長はあした出張します。","Ngày mai trưởng phòng đi công tác."]]},{"word":"部長","reading":"ぶちょう","meaning":"trưởng bộ phận","hanViet":"","lesson":18,"ex":[["山田さんは部長です。","Anh Yamada là trưởng bộ phận."],["部長は会議をします。","Trưởng bộ phận họp."],["わたしの部長は田中さんです。","Trưởng bộ phận của tôi là anh Tanaka."],["部長に話します。","Tôi nói chuyện với trưởng bộ phận."],["部長はあした会社に来ません。","Ngày mai trưởng bộ phận không đến công ty."]]},{"word":"社長","reading":"しゃちょう","meaning":"Giám đốc công ty","hanViet":"XÃ TRƯỞNG","lesson":18,"ex":[["社長は忙しいです。","Giám đốc công ty bận."],["社長はアメリカへ行きます。","Giám đốc đi Mỹ."],["社長に会いました。","Tôi đã gặp giám đốc."],["わたしの会社の社長は田中さんです。","Giám đốc công ty tôi là anh Tanaka."],["社長は車で行きます。","Giám đốc đi bằng ô tô."]]},{"word":"動物","reading":"どうぶつ","meaning":"Động vật","hanViet":"ĐỘNG VẬT","lesson":18,"ex":[["動物園に動物がいます。","Ở vườn thú có động vật."],["動物が好きです。","Tôi thích động vật."],["動物園で動物を見ました。","Tôi đã xem động vật ở vườn thú."],["この動物は大きいです。","Con vật này to."],["日本に動物がたくさんいます。","Ở Nhật có nhiều động vật."]]},{"word":"馬","reading":"うま","meaning":"con ngựa","hanViet":"MÃ","lesson":18,"ex":[["牧場に馬がいます。","Ở trang trại có ngựa."],["馬は速いです。","Ngựa chạy nhanh."],["牧場で馬を見ました。","Tôi đã xem ngựa ở trang trại."],["馬に乗りました。","Tôi đã cưỡi ngựa."],["馬は強いです。","Ngựa khoẻ."]]},{"word":"牧場","reading":"ぼくじょう","meaning":"trang trại chăn nuôi, đồng cỏ","hanViet":"MỤC TRƯỜNG","lesson":18,"ex":[["牧場は広いです。","Trang trại rộng."],["あした牧場へ行きます。","Ngày mai tôi đi trang trại."],["牧場で牛乳を飲みます。","Tôi uống sữa ở trang trại."],["牧場は山の近くにあります。","Trang trại ở gần núi."],["牧場に動物がいます。","Ở trang trại có động vật."]]},{"word":"ほんとうですか。","reading":"ほんとうですか。","meaning":"thật không ạ?","hanViet":"","lesson":18,"ex":[["ほんとうですか。","Thật không ạ?"],["ほんとうですか。すごいですね。","Thật không ạ? Tuyệt quá nhỉ."],["ほんとうですか。わたしも行きたいです。","Thật không ạ? Tôi cũng muốn đi."],["ほんとうですか。田中さんは先生になりましたか。","Thật không ạ? Anh Tanaka đã trở thành giáo viên à?"],["ほんとうですか。日本語は難しいですね。","Thật không ạ? Tiếng Nhật khó nhỉ."]]},{"word":"ぜひ","reading":"ぜひ","meaning":"nhất định, rất","hanViet":"","lesson":18,"ex":[["ぜひ見てください。","Nhất định hãy xem nhé."],["ぜひこの映画を見てください。","Nhất định hãy xem bộ phim này nhé."],["ぜひ食べてください。","Nhất định hãy ăn nhé."],["ぜひ日本へ来てください。","Nhất định hãy đến Nhật nhé."],["ぜひこの本を読んでください。","Nhất định hãy đọc quyển sách này nhé."]]},{"word":"飛ぶ","reading":"とぶ","meaning":"Bay","hanViet":"PHI","lesson":18,"ex":[["飛行機は飛びます。","Máy bay bay."],["飛行機は速く飛びます。","Máy bay bay nhanh."],["飛行機は高く飛びます。","Máy bay bay cao."],["飛行機が飛んでいます。","Máy bay đang bay."],["紙の飛行機は飛びます。","Máy bay giấy bay."]]},{"word":"跳ぶ","reading":"とぶ","meaning":"nhảy, nhảy qua","hanViet":"KHIÊU","lesson":18,"ex":[["犬は高く跳びます。","Con chó nhảy cao."],["猫は高く跳びます。","Con mèo nhảy cao."],["子どもは跳んで、遊びます。","Đứa trẻ vừa nhảy vừa chơi."],["犬は跳ぶことができます。","Con chó có thể nhảy."],["子どもは高く跳びました。","Đứa trẻ đã nhảy cao."]]},{"word":"登る","reading":"のぼる","meaning":"Leo, trèo lên","hanViet":"ĐĂNG","lesson":18,"ex":[["山に登ります。","Tôi leo núi."],["日曜日に兄と山に登ります。","Chủ nhật tôi leo núi cùng anh trai."],["春に山に登ります。","Vào mùa xuân tôi leo núi."],["山に登って、写真を撮ります。","Tôi leo núi và chụp ảnh."],["山に登ることができます。","Tôi có thể leo núi."]]},{"word":"走る","reading":"はしる","meaning":"chạy","hanViet":"TẨU","lesson":18,"ex":[["毎日走ります。","Mỗi ngày tôi chạy."],["公園で走ります。","Tôi chạy ở công viên."],["朝早く走ります。","Tôi chạy vào sáng sớm."],["犬と公園で走ります。","Tôi chạy cùng con chó ở công viên."],["わたしは学校まで走ります。","Tôi chạy đến trường."]]},{"word":"泳ぐ","reading":"およぐ","meaning":"Bơi","hanViet":"VỊNH","lesson":18,"ex":[["プールで泳ぎます。","Tôi bơi ở bể bơi."],["海で泳ぎます。","Tôi bơi ở biển."],["夏にプールで泳ぎます。","Vào mùa hè tôi bơi ở bể bơi."],["友達と海で泳ぎます。","Tôi bơi cùng bạn ở biển."],["子どもはプールで泳ぐことができます。","Đứa trẻ có thể bơi ở bể bơi."]]},{"word":"もぐる","reading":"もぐる","meaning":"lặn","hanViet":"","lesson":18,"ex":[["海でもぐります。","Tôi lặn ở biển."],["プールでもぐります。","Tôi lặn ở bể bơi."],["海でもぐって、魚を見ます。","Tôi lặn ở biển và ngắm cá."],["子どもはプールでもぐります。","Đứa trẻ lặn ở bể bơi."],["夏に海でもぐります。","Vào mùa hè tôi lặn ở biển."]]},{"word":"飛び込む","reading":"とびこむ","meaning":"nhảy xuống (nước)","hanViet":"","lesson":18,"ex":[["プールに飛び込みます。","Tôi nhảy xuống bể bơi."],["海に飛び込みます。","Tôi nhảy xuống biển."],["犬は川に飛び込みました。","Con chó đã nhảy xuống sông."],["プールに飛び込んではいけません。","Không được nhảy xuống bể bơi."],["夏に友達と海に飛び込みます。","Vào mùa hè tôi cùng bạn nhảy xuống biển."]]},{"word":"逆立ちする","reading":"さかだちする","meaning":"trồng cây chuối","hanViet":"","lesson":18,"ex":[["子どもは逆立ちします。","Đứa trẻ trồng cây chuối."],["弟は逆立ちが上手です。","Em trai tôi trồng cây chuối giỏi."],["わたしは逆立ちができません。","Tôi không trồng cây chuối được."],["友達と公園で逆立ちをします。","Tôi cùng bạn trồng cây chuối ở công viên."],["子どもは逆立ちをして、遊びます。","Đứa trẻ vừa trồng cây chuối vừa chơi."]]},{"word":"はう","reading":"はう","meaning":"bò","hanViet":"","lesson":18,"ex":[["赤ちゃんははいます。","Em bé bò."],["赤ちゃんはゆっくりはいます。","Em bé bò chậm."],["赤ちゃんは庭ではいます。","Em bé bò ở sân."],["赤ちゃんは部屋ではいます。","Em bé bò trong phòng."],["赤ちゃんははうことができます。","Em bé có thể bò."]]},{"word":"ける","reading":"ける","meaning":"đá","hanViet":"","lesson":18,"ex":[["犬をけってはいけません。","Không được đá con chó."],["子どもは雪をけります。","Đứa trẻ đá tuyết."],["わたしは犬をけりません。","Tôi không đá con chó."],["猫をけってはいけません。","Không được đá con mèo."],["子どもは雪をけって、遊びます。","Đứa trẻ vừa đá tuyết vừa chơi."]]},{"word":"振る","reading":"ふる","meaning":"vẫy, lắc, rắc","hanViet":"CHẤN","lesson":18,"ex":[["手を振ります。","Tôi vẫy tay."],["塩を振ります。","Tôi rắc muối."],["友達に手を振りました。","Tôi đã vẫy tay với bạn."],["手を振って、友達を呼びます。","Tôi vẫy tay và gọi bạn."],["子どもは頭を振ります。","Đứa trẻ lắc đầu."]]},{"word":"投げる","reading":"なげる","meaning":"Ném, vứt","hanViet":"ĐẦU","lesson":18,"ex":[["子どもは雪を投げます。","Đứa trẻ ném tuyết."],["子どもは雪を投げました。","Đứa trẻ đã ném tuyết."],["友達に雪を投げてはいけません。","Không được ném tuyết vào bạn."],["紙を投げてはいけません。","Không được ném giấy."],["りんごを投げてはいけません。","Không được ném quả táo."]]},{"word":"持ち上げる","reading":"もちあげる","meaning":"nhấc lên","hanViet":"","lesson":18,"ex":[["重いかばんを持ち上げます。","Tôi nhấc chiếc cặp nặng lên."],["重い箱を持ち上げます。","Tôi nhấc chiếc hộp nặng lên."],["子どもを持ち上げます。","Tôi nhấc đứa trẻ lên."],["父は重い荷物を持ち上げました。","Bố tôi đã nhấc hành lý nặng lên."],["荷物を持ち上げて、車に入れます。","Tôi nhấc hành lý lên và cho vào xe."]]},{"word":"たたく","reading":"たたく","meaning":"vỗ, đánh","hanViet":"","lesson":18,"ex":[["ドアをたたきます。","Tôi gõ cửa."],["手をたたきます。","Tôi vỗ tay."],["ドアをたたいて、入ります。","Tôi gõ cửa rồi vào."],["机をたたいてはいけません。","Không được đập bàn."],["友達はドアをたたきました。","Bạn tôi đã gõ cửa."]]},{"word":"引く","reading":"ひく","meaning":"Kéo; tra (từ điển); bị (cảm)","hanViet":"DẪN","lesson":18,"ex":[["辞書を引きます。","Tôi tra từ điển."],["かぜを引きました。","Tôi đã bị cảm."],["辞書を引いて、意味を調べます。","Tôi tra từ điển để tìm nghĩa."],["電子辞書でことばを引きます。","Tôi tra từ bằng từ điển điện tử."],["子どもはドアを引いて、入ります。","Đứa trẻ kéo cửa rồi vào."]]},{"word":"押す","reading":"おす","meaning":"Ấn, nhấn, đẩy","hanViet":"ÁP","lesson":18,"ex":[["ボタンを押してください。","Hãy bấm nút."],["重いドアを押して、入ります。","Tôi đẩy cánh cửa nặng và đi vào."],["ドアを押して、入ります。","Tôi đẩy cửa rồi vào."],["エレベーターのボタンを押します。","Tôi bấm nút thang máy."],["ボタンを押して、電気をつけます。","Tôi bấm nút để bật điện."]]},{"word":"曲げる","reading":"まげる","meaning":"uốn cong","hanViet":"","lesson":18,"ex":[["紙を曲げます。","Tôi uốn cong tờ giấy."],["足を曲げて、座ります。","Tôi co chân lại và ngồi."],["紙を曲げて、船を作ります。","Tôi gấp giấy làm thuyền."],["この紙を曲げてください。","Hãy uốn cong tờ giấy này."],["子どもは紙を曲げて、遊びます。","Đứa trẻ vừa gấp giấy vừa chơi."]]},{"word":"伸ばす","reading":"のばす","meaning":"Kéo dài, duỗi ra, gia hạn","hanViet":"THÂN","lesson":18,"ex":[["手を伸ばします。","Tôi duỗi tay ra."],["足を伸ばします。","Tôi duỗi chân ra."],["髪を伸ばします。","Tôi để tóc dài."],["手を伸ばして、本を取ります。","Tôi với tay lấy quyển sách."],["朝、体を伸ばします。","Buổi sáng tôi duỗi người ra."]]},{"word":"転ぶ","reading":"ころぶ","meaning":"Ngã, lăn","hanViet":"CHUYỂN","lesson":18,"ex":[["子どもは転びました。","Đứa trẻ đã ngã."],["わたしは道で転びました。","Tôi đã ngã trên đường."],["子どもは走って、転びました。","Đứa trẻ chạy rồi ngã."],["雪の日に転んで、けがをしました。","Tôi ngã vào ngày tuyết và bị thương."],["自転車で転びました。","Tôi ngã xe đạp."]]},{"word":"振り向く","reading":"ふりむく","meaning":"quay lại nhìn","hanViet":"","lesson":18,"ex":[["友達は振り向きました。","Bạn tôi đã quay lại nhìn."],["母は振り向きました。","Mẹ tôi đã quay lại nhìn."],["犬は振り向きました。","Con chó đã quay lại nhìn."],["友達は振り向いて、話しました。","Bạn tôi quay lại nhìn và nói chuyện."],["わたしは振り向いて、友達を見ました。","Tôi quay lại nhìn và thấy bạn."]]},{"word":"インターネット","reading":"インターネット","meaning":"internet","hanViet":"","lesson":18,"ex":[["インターネットで調べます。","Tôi tra cứu trên internet."],["インターネットでニュースを見ます。","Tôi xem tin tức trên internet."],["インターネットで買い物をします。","Tôi mua sắm trên internet."],["インターネットで友達にメールを書きます。","Tôi viết thư cho bạn trên internet."],["インターネットで日本語を勉強します。","Tôi học tiếng Nhật trên internet."]]},{"word":"ピアノ","reading":"ピアノ","meaning":"piano","hanViet":"","lesson":18,"ex":[["ピアノを習います。","Tôi học piano."],["姉は毎晩ピアノを弾きます。","Mỗi tối chị gái tôi chơi piano."],["ピアノが上手です。","Tôi chơi piano giỏi."],["毎日ピアノを練習します。","Mỗi ngày tôi luyện tập piano."],["私はピアノを弾くことができません。","Tôi không thể chơi piano."]]},{"word":"～メートル","reading":"～メートル","meaning":"mét","hanViet":"","lesson":18,"ex":[["プールは25メートルです。","Bể bơi dài 25 mét."],["この部屋は5メートルです。","Căn phòng này dài 5 mét."],["この道は100メートルです。","Con đường này dài 100 mét."],["この山は1000メートルです。","Ngọn núi này cao 1000 mét."],["この橋は50メートルです。","Cây cầu này dài 50 mét."]]},{"word":"へえ","reading":"へえ","meaning":"thế à (ngạc nhiên)","hanViet":"","lesson":18,"ex":[["へえ、そうですか。","Ồ, thế à."],["へえ、山田さんはピアノが上手ですね。","Ồ, anh Yamada chơi piano giỏi nhỉ."],["へえ、田中さんは先生ですか。","Ồ, anh Tanaka là giáo viên à?"],["へえ、日本語は難しいですね。","Ồ, tiếng Nhật khó nhỉ."],["へえ、あしたは休みですか。","Ồ, ngày mai được nghỉ à?"]]},{"word":"それはおもしろいですね","reading":"それはおもしろいですね","meaning":"hay thật nhỉ","hanViet":"","lesson":18,"ex":[["それはおもしろいですね。","Hay thật nhỉ."],["犬はピアノを弾きます。それはおもしろいですね。","Con chó chơi piano. Hay thật nhỉ."],["子どもは毎日逆立ちをします。それはおもしろいですね。","Đứa trẻ trồng cây chuối mỗi ngày. Hay thật nhỉ."],["田中さんは山に登ります。それはおもしろいですね。","Anh Tanaka leo núi. Hay thật nhỉ."],["子どもは雪で遊びます。それはおもしろいですね。","Đứa trẻ chơi với tuyết. Hay thật nhỉ."]]},{"word":"なかなか","reading":"なかなか","meaning":"khó mà, mãi mà (dùng với phủ định)","hanViet":"","lesson":18,"ex":[["日本語はなかなか上手になりません。","Tiếng Nhật mãi mà vẫn chưa giỏi lên được."],["子どもはなかなか寝ません。","Đứa trẻ mãi mà vẫn chưa ngủ."],["電車はなかなか来ません。","Tàu mãi mà vẫn chưa đến."],["母はなかなか元気になりません。","Mẹ tôi mãi mà vẫn chưa khoẻ lại."],["この問題はなかなかわかりません。","Bài toán này mãi mà tôi vẫn chưa hiểu."]]},{"word":"ビートルズ","reading":"ビートルズ","meaning":"ban nhạc Beatles (nổi tiếng nước Anh)","hanViet":"","lesson":18,"ex":[["ビートルズの歌が好きです。","Tôi thích các bài hát của ban nhạc Beatles."],["ビートルズの歌を歌います。","Tôi hát các bài hát của Beatles."],["わたしはビートルズのコンサートに行きたいです。","Tôi muốn đi xem buổi hoà nhạc của Beatles."],["父はビートルズが好きです。","Bố tôi thích Beatles."],["ビートルズの歌は有名です。","Các bài hát của Beatles nổi tiếng."]]},{"word":"登ります","reading":"のぼります","meaning":"leo (núi)","hanViet":"","lesson":19,"ex":[["わたしは山に登ります。","Tôi leo núi."],["父と山に登ります。","Tôi leo núi cùng bố."],["夏に山に登ります。","Vào mùa hè tôi leo núi."],["山に登って、昼ごはんを食べます。","Tôi leo núi rồi ăn trưa."],["山に登りますから、早く起きます。","Vì tôi leo núi nên tôi dậy sớm."]]},{"word":"泊まります","reading":"とまります","meaning":"trọ","hanViet":"","lesson":19,"ex":[["わたしはホテルに泊まります。","Tôi trọ ở khách sạn."],["友達のうちに泊まりました。","Tôi đã trọ ở nhà bạn."],["ホテルに三日泊まります。","Tôi trọ ở khách sạn ba ngày."],["あしたホテルに泊まります。","Ngày mai tôi trọ ở khách sạn."],["来週、友達のうちに泊まります。","Tuần sau tôi trọ ở nhà bạn."]]},{"word":"掃除します","reading":"そうじします","meaning":"dọn dẹp","hanViet":"","lesson":19,"ex":[["わたしはまいにち部屋を掃除します。","Tôi dọn phòng mỗi ngày."],["台所を掃除しました。","Tôi đã dọn bếp."],["毎朝部屋を掃除します。","Mỗi sáng tôi dọn phòng."],["あした、うちを掃除します。","Ngày mai tôi dọn nhà."],["掃除して、買い物をします。","Tôi dọn dẹp rồi đi mua sắm."]]},{"word":"洗濯します","reading":"せんたくします","meaning":"giặt","hanViet":"","lesson":19,"ex":[["わたしはまいにち洗濯します。","Tôi giặt đồ mỗi ngày."],["セーターを洗濯します。","Tôi giặt áo len."],["毎朝洗濯します。","Mỗi sáng tôi giặt đồ."],["あした洗濯して、掃除します。","Ngày mai tôi giặt đồ rồi dọn dẹp."],["母は洗濯します。","Mẹ tôi giặt đồ."]]},{"word":"練習します","reading":"れんしゅうします","meaning":"luyện tập","hanViet":"","lesson":19,"ex":[["わたしはまいにち日本語を練習します。","Tôi luyện tập tiếng Nhật mỗi ngày."],["ピアノを練習します。","Tôi luyện tập piano."],["テニスを練習します。","Tôi luyện tập quần vợt."],["毎日漢字を練習します。","Mỗi ngày tôi luyện tập chữ Hán."],["友達と日本語を練習します。","Tôi luyện tập tiếng Nhật cùng bạn."]]},{"word":"なります","reading":"なります","meaning":"trở nên","hanViet":"","lesson":19,"ex":[["わたしは先生になります。","Tôi trở thành giáo viên."],["医者になります。","Tôi trở thành bác sĩ."],["会社員になります。","Tôi trở thành nhân viên công ty."],["日本語が上手になります。","Tiếng Nhật của tôi trở nên giỏi hơn."],["子どもは大きくなります。","Đứa trẻ lớn lên."]]},{"word":"眠い","reading":"ねむい","meaning":"Buồn ngủ","hanViet":"MIÊN","lesson":19,"ex":[["わたしは眠いです。","Tôi buồn ngủ."],["きょうは眠いです。","Hôm nay tôi buồn ngủ."],["子どもは眠いです。","Đứa trẻ buồn ngủ."],["わたしはとても眠いです。","Tôi rất buồn ngủ."],["夜は眠くなります。","Buổi tối tôi trở nên buồn ngủ."]]},{"word":"強い","reading":"つよい","meaning":"Mạnh, khoẻ","hanViet":"CƯỜNG","lesson":19,"ex":[["田中さんは強いです。","Anh Tanaka khoẻ."],["山田さんは体が強いです。","Anh Yamada khoẻ mạnh."],["父はとても強いです。","Bố tôi rất khoẻ."],["強い雨が降ります。","Mưa to."],["わたしの弟は強いです。","Em trai tôi khoẻ."]]},{"word":"弱い","reading":"よわい","meaning":"Yếu","hanViet":"NHƯỢC","lesson":19,"ex":[["山田さんは体が弱いです。","Anh Yamada sức khoẻ yếu."],["田中さんは体が弱いです。","Anh Tanaka sức khoẻ yếu."],["わたしは酒が弱いです。","Tôi uống rượu kém."],["弱い雨が降ります。","Mưa nhỏ."],["子どもはまだ弱いです。","Đứa trẻ vẫn còn yếu."]]},{"word":"調子がいい","reading":"ちょうしがいい","meaning":"trong tình trạng tốt","hanViet":"","lesson":19,"ex":[["きょうは調子がいいです。","Hôm nay tôi khoẻ."],["母は調子がいいです。","Mẹ tôi khoẻ."],["父は調子がいいです。","Bố tôi khoẻ."],["車の調子がいいです。","Xe chạy tốt."],["友達は調子がいいです。","Bạn tôi khoẻ."]]},{"word":"調子が悪い","reading":"ちょうしがわるい","meaning":"trong tình trạng xấu","hanViet":"","lesson":19,"ex":[["きょうは調子が悪いです。","Hôm nay tôi không khoẻ."],["きのうは調子が悪かったです。","Hôm qua tôi không khoẻ."],["子どもは調子が悪いです。","Đứa trẻ không khoẻ."],["車の調子が悪いです。","Xe chạy không tốt."],["母は調子が悪いです。","Mẹ tôi không khoẻ."]]},{"word":"調子","reading":"ちょうし","meaning":"tình trạng, nhịp điệu, giọng điệu","hanViet":"ĐIỀU TỬ","lesson":19,"ex":[["調子はどうですか。","Bạn có khoẻ không?"],["あなたの調子はどうですか。","Bạn có khoẻ không?"],["調子はいいです。","Tôi khoẻ."],["車の調子はどうですか。","Xe chạy thế nào?"],["母の調子はいいです。","Mẹ tôi khoẻ."]]},{"word":"一度","reading":"いちど","meaning":"Một lần","hanViet":"NHẤT ĐỘ","lesson":19,"ex":[["わたしは一度日本へ行きました。","Tôi đã đi Nhật một lần."],["わたしは一度だけ日本へ行きました。","Tôi chỉ đi Nhật một lần."],["一度、先生に会いました。","Tôi đã gặp thầy một lần."],["一度日本へ行きたいです。","Tôi muốn đi Nhật một lần."],["一度、映画館へ行きました。","Tôi đã đi rạp chiếu phim một lần."]]},{"word":"一度も","reading":"いちども","meaning":"chưa lần nào","hanViet":"","lesson":19,"ex":[["わたしは一度も日本へ行ったことがありません。","Tôi chưa từng đi Nhật lần nào."],["一度も映画を見たことがありません。","Tôi chưa từng xem phim lần nào."],["一度も泳いだことがありません。","Tôi chưa từng bơi lần nào."],["一度も外国へ行ったことがありません。","Tôi chưa từng ra nước ngoài lần nào."],["一度もスキーをしたことがありません。","Tôi chưa từng trượt tuyết lần nào."]]},{"word":"だんだん","reading":"だんだん","meaning":"dần dần","hanViet":"","lesson":19,"ex":[["だんだん寒くなります。","Trời dần trở nên lạnh."],["だんだん暖かくなります。","Trời dần trở nên ấm."],["だんだん日本語が上手になります。","Tiếng Nhật dần trở nên giỏi hơn."],["だんだん暑くなります。","Trời dần trở nên nóng."],["だんだん元気になります。","Tôi dần trở nên khoẻ."]]},{"word":"もうすぐ","reading":"もうすぐ","meaning":"sắp","hanViet":"","lesson":19,"ex":[["もうすぐ春です。","Sắp đến mùa xuân."],["もうすぐ夏です。","Sắp đến mùa hè."],["もうすぐ試験です。","Sắp đến kỳ thi."],["もうすぐ日本へ行きます。","Sắp đi Nhật."],["もうすぐ昼ごはんです。","Sắp đến bữa trưa."]]},{"word":"おかげさまで","reading":"おかげさまで","meaning":"cảm ơn (bày tỏ sự cảm ơn khi nhận được sự giúp đỡ)","hanViet":"","lesson":19,"ex":[["おかげさまで、元気です。","Nhờ ơn bạn, tôi vẫn khoẻ."],["おかげさまで、家族は元気です。","Nhờ ơn bạn, gia đình tôi vẫn khoẻ."],["おかげさまで、日本語が上手になりました。","Nhờ ơn bạn, tiếng Nhật của tôi đã giỏi lên."],["おかげさまで、元気になりました。","Nhờ ơn bạn, tôi đã khoẻ lại."],["おかげさまで、毎日楽しいです。","Nhờ ơn bạn, mỗi ngày tôi đều vui."]]},{"word":"乾杯","reading":"かんぱい","meaning":"Cạn ly! (chúc mừng khi uống)","hanViet":"CAN BÔI","lesson":19,"ex":[["みんなで乾杯しましょう。","Mọi người cùng cạn ly nào."],["みんなで乾杯しました。","Mọi người đã cùng cạn ly."],["ビールで乾杯しましょう。","Cùng cạn ly bằng bia nào."],["あした、みんなで乾杯します。","Ngày mai mọi người cùng cạn ly."],["先生と乾杯します。","Tôi cạn ly với thầy."]]},{"word":"ゴルフ","reading":"ゴルフ","meaning":"gôn","hanViet":"","lesson":19,"ex":[["わたしはゴルフをします。","Tôi chơi gôn."],["父はゴルフをします。","Bố tôi chơi gôn."],["ゴルフは楽しいです。","Chơi gôn vui."],["あしたゴルフをします。","Ngày mai tôi chơi gôn."],["ゴルフが好きです。","Tôi thích chơi gôn."]]},{"word":"パチンコ","reading":"パチンコ","meaning":"trò chơi pachinko","hanViet":"","lesson":19,"ex":[["田中さんはパチンコをします。","Anh Tanaka chơi pachinko."],["父はパチンコをします。","Bố tôi chơi pachinko."],["パチンコはおもしろいです。","Pachinko thú vị."],["あしたパチンコをします。","Ngày mai tôi chơi pachinko."],["山田さんはパチンコが好きです。","Anh Yamada thích pachinko."]]},{"word":"日","reading":"ひ","meaning":"ngày","hanViet":"NHẬT","lesson":19,"ex":[["きょうはいい日です。","Hôm nay là một ngày tốt đẹp."],["きょうは楽しい日です。","Hôm nay là một ngày vui."],["あしたは忙しい日です。","Ngày mai là một ngày bận rộn."],["きのうはいい日でした。","Hôm qua là một ngày tốt đẹp."],["きょうは暑い日です。","Hôm nay là một ngày nóng."]]},{"word":"ダイエット","reading":"ダイエット","meaning":"việc ăn kiêng","hanViet":"","lesson":19,"ex":[["わたしはダイエットをします。","Tôi ăn kiêng."],["母はダイエットをします。","Mẹ tôi ăn kiêng."],["ダイエットは大変です。","Ăn kiêng vất vả."],["あしたからダイエットをします。","Từ ngày mai tôi ăn kiêng."],["ダイエットをして、野菜を食べます。","Tôi ăn kiêng và ăn rau củ."]]},{"word":"しかし","reading":"しかし","meaning":"tuy nhiên","hanViet":"","lesson":19,"ex":[["あしたは休みです。しかし、わたしはうちにいます。","Ngày mai tôi được nghỉ. Tuy nhiên, tôi ở nhà."],["きょうは雨です。しかし、わたしは学校へ行きます。","Hôm nay trời mưa. Tuy nhiên, tôi đi học."],["日本語は難しいです。しかし、楽しいです。","Tiếng Nhật khó. Tuy nhiên, nó thú vị."],["わたしは忙しいです。しかし、映画を見ます。","Tôi bận. Tuy nhiên, tôi xem phim."],["車は高いです。しかし、便利です。","Ô tô đắt. Tuy nhiên, nó tiện lợi."]]},{"word":"無理な","reading":"むりな","meaning":"không thể, quá sức","hanViet":"","lesson":19,"ex":[["それは無理な仕事です。","Đó là công việc quá sức."],["無理な仕事はしません。","Tôi không làm công việc quá sức."],["それは無理な話です。","Đó là chuyện không thể."],["無理な時間に来ないでください。","Đừng đến vào giờ không hợp lý."],["それは無理な仕事ですから、しません。","Vì đó là công việc quá sức nên tôi không làm."]]},{"word":"体にいい","reading":"からだにいい","meaning":"tốt cho sức khoẻ","hanViet":"","lesson":19,"ex":[["野菜は体にいいです。","Rau củ tốt cho sức khoẻ."],["果物と牛乳は体にいいです。","Trái cây và sữa tốt cho sức khỏe."],["牛乳は子どもの体にいいです。","Sữa tốt cho sức khỏe của trẻ em."],["魚と野菜は体にいいです。","Cá và rau tốt cho sức khỏe."],["水は体にいいです。","Nước tốt cho sức khoẻ."]]},{"word":"何回も","reading":"なんかいも","meaning":"nhiều lần","hanViet":"","lesson":19,"ex":[["わたしはその映画を何回も見ました。","Tôi đã xem bộ phim đó nhiều lần."],["その歌を何回も聞きました。","Tôi đã nghe bài hát đó nhiều lần."],["その本を何回も読みました。","Tôi đã đọc quyển sách đó nhiều lần."],["日本へ何回も行きました。","Tôi đã đi Nhật nhiều lần."],["その映画を何回も見たいです。","Tôi muốn xem bộ phim đó nhiều lần."]]},{"word":"実は","reading":"じつは","meaning":"thật ra là","hanViet":"","lesson":19,"ex":[["実は、わたしはあした日本へ行きます。","Thật ra, ngày mai tôi đi Nhật."],["実は、わたしは学生です。","Thật ra, tôi là học sinh."],["実は、きのう日本へ行きました。","Thật ra, hôm qua tôi đã đi Nhật."],["実は、わたしはピアノが好きです。","Thật ra, tôi thích piano."],["実は、あしたは休みです。","Thật ra, ngày mai tôi được nghỉ."]]},{"word":"要ります","reading":"いります","meaning":"cần","hanViet":"","lesson":20,"ex":[["日本語の辞書が要ります。","Tôi cần từ điển tiếng Nhật."],["お金が要ります。","Tôi cần tiền."],["時間が要ります。","Tôi cần thời gian."],["この本が要ります。","Tôi cần quyển sách này."],["あした、車が要ります。","Ngày mai tôi cần ô tô."]]},{"word":"調べます","reading":"しらべます","meaning":"tìm hiểu, điều tra","hanViet":"","lesson":20,"ex":[["辞書でことばを調べます。","Tôi tra từ bằng từ điển."],["辞書で意味を調べます。","Tôi tra nghĩa bằng từ điển."],["インターネットで天気を調べます。","Tôi tra thời tiết trên internet."],["電話番号を調べます。","Tôi tra số điện thoại."],["新聞で天気を調べます。","Tôi xem thời tiết trên báo."]]},{"word":"直します","reading":"なおします","meaning":"sửa, chữa","hanViet":"","lesson":20,"ex":[["宿題を直しました。","Tôi đã sửa bài tập về nhà."],["漢字を直してください。","Hãy sửa chữ Hán."],["レポートを直しました。","Tôi đã sửa bản báo cáo."],["名前を直しますか。","Bạn có sửa tên không?"],["住所を直して、送ります。","Tôi sửa địa chỉ rồi gửi."]]},{"word":"修理します","reading":"しゅうりします","meaning":"sửa chữa, tu sửa","hanViet":"","lesson":20,"ex":[["自転車を修理します。","Tôi sửa xe đạp."],["車を修理してもらいます。","Tôi nhờ sửa xe."],["時計を修理します。","Tôi sửa đồng hồ."],["パソコンを修理しました。","Tôi đã sửa máy tính."],["自転車を修理してください。","Hãy sửa xe đạp."]]},{"word":"電話します","reading":"でんわします","meaning":"gọi điện","hanViet":"ĐIỆN THOẠI","lesson":20,"ex":[["母に電話します。","Tôi gọi điện cho mẹ."],["友達に電話しました。","Tôi đã gọi điện cho bạn."],["先生に電話してください。","Hãy gọi điện cho thầy."],["あした、会社に電話します。","Ngày mai tôi gọi điện đến công ty."],["母に電話して、話します。","Tôi gọi điện cho mẹ và nói chuyện."]]},{"word":"僕","reading":"ぼく","meaning":"tớ, tôi (nam giới xưng hô)","hanViet":"BỘC","lesson":20,"ex":[["僕は学生です。","Tớ là học sinh."],["僕は日本語を勉強します。","Tớ học tiếng Nhật."],["僕は先生です。","Tớ là giáo viên."],["僕はあした学校へ行きます。","Ngày mai tớ đi học."],["僕は映画が好きです。","Tớ thích phim."]]},{"word":"君","reading":"きみ","meaning":"Bạn, cậu (thân mật)","hanViet":"QUÂN","lesson":20,"ex":[["君は学生ですか。","Cậu là học sinh à?"],["君はどこへ行きますか。","Cậu đi đâu đấy?"],["君は日本語が上手ですね。","Cậu giỏi tiếng Nhật nhỉ."],["君はあした来ますか。","Ngày mai cậu có đến không?"],["君の名前は何ですか。","Tên cậu là gì?"]]},{"word":"～君","reading":"～くん","meaning":"thêm vào sau tên con trai, cách gọi thân mật","hanViet":"","lesson":20,"ex":[["田中君は学生です。","Cậu Tanaka là học sinh."],["山田君は学生です。","Cậu Yamada là học sinh."],["田中君はあした来ますか。","Ngày mai cậu Tanaka có đến không?"],["山田君は日本語が上手です。","Cậu Yamada giỏi tiếng Nhật."],["田中君は友達です。","Cậu Tanaka là bạn tôi."]]},{"word":"うん","reading":"うん","meaning":"ừ","hanViet":"","lesson":20,"ex":[["うん、わかりました。","Ừ, tôi hiểu rồi."],["うん、見ました。","Ừ, tôi đã xem rồi."],["うん、行きます。","Ừ, tôi đi."],["うん、食べます。","Ừ, tôi ăn."],["うん、好きです。","Ừ, tôi thích."]]},{"word":"ううん","reading":"ううん","meaning":"không (thân mật của いいえ)","hanViet":"","lesson":20,"ex":[["ううん、行きません。","Không, tôi không đi."],["ううん、食べません。","Không, tôi không ăn."],["ううん、わかりません。","Không, tôi không hiểu."],["ううん、好きではありません。","Không, tôi không thích."],["ううん、見ません。","Không, tôi không xem."]]},{"word":"ことば","reading":"ことば","meaning":"từ, tiếng","hanViet":"","lesson":20,"ex":[["このことばは難しいです。","Từ này khó."],["新しいことばを覚えます。","Tôi học thuộc từ mới."],["このことばは易しいです。","Từ này dễ."],["日本語のことばを勉強します。","Tôi học từ tiếng Nhật."],["ことばの意味を調べます。","Tôi tra nghĩa của từ."]]},{"word":"物価","reading":"ぶっか","meaning":"giá cả, vật giá","hanViet":"","lesson":20,"ex":[["日本の物価は高いです。","Giá cả ở Nhật cao."],["ベトナムの物価は安いです。","Giá cả ở Việt Nam rẻ."],["日本の物価は高いですから、大変です。","Vì giá cả ở Nhật cao nên vất vả."],["この町の物価は安いです。","Giá cả ở thị trấn này rẻ."],["物価は高いですね。","Giá cả cao nhỉ."]]},{"word":"着物","reading":"きもの","meaning":"kimono","hanViet":"","lesson":20,"ex":[["母は着物が好きです。","Mẹ tôi thích kimono."],["おばあさんは着物を着ます。","Bà tôi mặc kimono."],["この着物は高いです。","Chiếc kimono này đắt."],["母は正月に着物を着ました。","Vào dịp Tết mẹ tôi đã mặc kimono."],["妹は赤い着物が好きです。","Em gái tôi thích kimono đỏ."]]},{"word":"初め","reading":"はじめ","meaning":"bắt đầu, đầu tiên","hanViet":"SƠ","lesson":20,"ex":[["初めは日本語が難しかったです。","Lúc đầu tiếng Nhật khó."],["初めに名前を書いてください。","Trước tiên hãy viết tên."],["仕事の初めは九時です。","Công việc bắt đầu lúc 9 giờ."],["映画の初めはおもしろいです。","Phần đầu của bộ phim thú vị."],["初めから日本語で話してください。","Hãy nói bằng tiếng Nhật từ đầu."]]},{"word":"終わり","reading":"おわり","meaning":"kết thúc","hanViet":"","lesson":20,"ex":[["試験の終わりは三時です。","Kỳ thi kết thúc lúc 3 giờ."],["会議の終わりは五時です。","Cuộc họp kết thúc lúc 5 giờ."],["仕事の終わりに買い物をします。","Sau khi tan làm tôi đi mua sắm."],["休みの終わりは日曜日です。","Kỳ nghỉ kết thúc vào chủ nhật."],["本の終わりはおもしろいです。","Phần cuối của quyển sách thú vị."]]},{"word":"こっち","reading":"こっち","meaning":"phía này","hanViet":"","lesson":20,"ex":[["こっちに来てください。","Hãy đến phía này."],["こっちは静かです。","Phía này yên tĩnh."],["こっちの道を行ってください。","Hãy đi theo con đường phía này."],["こっちの本は安いです。","Quyển sách phía này rẻ."],["こっちで待ってください。","Hãy đợi ở phía này."]]},{"word":"そっち","reading":"そっち","meaning":"phía đó","hanViet":"","lesson":20,"ex":[["そっちは寒いですか。","Phía đó có lạnh không?"],["そっちに行きます。","Tôi đi về phía đó."],["そっちの天気はどうですか。","Thời tiết phía đó thế nào?"],["そっちで何をしていますか。","Bạn đang làm gì ở phía đó?"],["そっちのほうが近いです。","Phía đó gần hơn."]]},{"word":"あっち","reading":"あっち","meaning":"phía kia","hanViet":"","lesson":20,"ex":[["あっちに駅があります。","Phía kia có ga."],["あっちに学校があります。","Phía kia có trường học."],["あっちはにぎやかです。","Phía kia nhộn nhịp."],["あっちの店で買い物をします。","Tôi mua sắm ở cửa hàng phía kia."],["あっちに行ってください。","Hãy đi về phía kia."]]},{"word":"どっち","reading":"どっち","meaning":"phía nào","hanViet":"","lesson":20,"ex":[["どっちがいいですか。","Bên nào tốt hơn?"],["どっちのほうが安いですか。","Bên nào rẻ hơn?"],["どっちに行きますか。","Bạn đi phía nào?"],["どっちも好きです。","Tôi thích cả hai bên."],["どっちの電車に乗りますか。","Bạn đi tàu điện nào?"]]},{"word":"この間","reading":"このあいだ","meaning":"vừa rồi, hôm nọ","hanViet":"GIAN","lesson":20,"ex":[["この間、友達に会いました。","Hôm nọ tôi đã gặp bạn."],["この間、母に手紙を書きました。","Hôm nọ tôi đã viết thư cho mẹ."],["この間、デパートで買い物をしました。","Hôm nọ tôi đã mua sắm ở cửa hàng bách hóa."],["この間、山田さんとテニスをしました。","Hôm nọ tôi đã chơi tennis với anh Yamada."],["この間、おいしい寿司を食べました。","Hôm nọ tôi đã ăn sushi ngon."]]},{"word":"みんなで","reading":"みんなで","meaning":"mọi người cùng","hanViet":"","lesson":20,"ex":[["みんなでごはんを食べました。","Mọi người cùng ăn cơm."],["みんなでサッカーをします。","Mọi người cùng chơi bóng đá."],["みんなで歌を歌います。","Mọi người cùng hát."],["みんなで昼ごはんを食べます。","Mọi người cùng ăn trưa."],["みんなで写真を撮ります。","Mọi người cùng chụp ảnh."]]},{"word":"～けど","reading":"～けど","meaning":"nhưng, tuy nhiên","hanViet":"","lesson":20,"ex":[["日本語は難しいけど、おもしろいです。","Tiếng Nhật khó nhưng thú vị."],["この本は古いけど、おもしろいです。","Quyển sách này cũ nhưng thú vị."],["雨が降っていますけど、買い物に行きます。","Trời đang mưa nhưng tôi vẫn đi mua sắm."],["忙しいけど、映画を見ました。","Bận nhưng tôi đã xem phim."],["田中さんは学生ですけど、日本語が上手です。","Anh Tanaka là học sinh nhưng tiếng Nhật giỏi."]]},{"word":"サラリーマン","reading":"サラリーマン","meaning":"người làm công ăn lương","hanViet":"","lesson":20,"ex":[["父はサラリーマンです。","Bố tôi là người làm công ăn lương."],["山田さんはサラリーマンです。","Anh Yamada là người làm công ăn lương."],["サラリーマンは毎日電車に乗ります。","Người làm công ăn lương ngày nào cũng đi tàu điện."],["兄はサラリーマンになりました。","Anh trai tôi đã trở thành người làm công ăn lương."],["サラリーマンは会社で働きます。","Người làm công ăn lương làm việc ở công ty."]]},{"word":"ビザ","reading":"ビザ","meaning":"thị thực, visa","hanViet":"","lesson":20,"ex":[["ビザをもらいました。","Tôi đã nhận được visa."],["ビザを取ります。","Tôi lấy visa."],["ビザが要ります。","Cần có visa."],["ビザは大使館でもらいます。","Tôi nhận visa ở đại sứ quán."],["ビザについて教えてください。","Hãy cho tôi biết về visa."]]},{"word":"国へ帰るの？","reading":"くにへかえるの？","meaning":"bạn có về nước không?","hanViet":"","lesson":20,"ex":[["来月、国へ帰るの？","Tháng sau bạn có về nước không?"],["今月、国へ帰るの？","Tháng này bạn có về nước không?"],["来年、国へ帰るの？","Năm sau bạn có về nước không?"],["休みに国へ帰るの？","Vào kỳ nghỉ bạn có về nước không?"],["友達と国へ帰るの？","Bạn về nước cùng bạn bè à?"]]},{"word":"どうするの？","reading":"どうするの？","meaning":"làm thế nào đây?","hanViet":"","lesson":20,"ex":[["あした、どうするの？","Ngày mai bạn làm thế nào đây?"],["今晩、どうするの？","Tối nay bạn làm thế nào đây?"],["電車がありません。どうするの？","Không có tàu điện. Làm thế nào đây?"],["雨です。どうするの？","Trời mưa. Làm thế nào đây?"],["先生がいません。どうするの？","Không có thầy giáo. Làm thế nào đây?"]]},{"word":"どうしようかな","reading":"どうしようかな","meaning":"Làm thế nào được nhỉ?","hanViet":"","lesson":20,"ex":[["あした、どうしようかな。","Ngày mai làm thế nào được nhỉ?"],["今晩、どうしようかな。","Tối nay làm thế nào được nhỉ?"],["プレゼントはどうしようかな。","Quà tặng thì làm thế nào được nhỉ?"],["暑いですね。どうしようかな。","Trời nóng nhỉ. Làm thế nào được nhỉ?"],["電車がありません。どうしようかな。","Không có tàu điện. Làm thế nào được nhỉ?"]]},{"word":"よかったら","reading":"よかったら","meaning":"nếu được thì…","hanViet":"","lesson":20,"ex":[["よかったら、来てください。","Nếu được thì hãy đến nhé."],["よかったら、見てください。","Nếu được thì hãy xem nhé."],["よかったら、食べてください。","Nếu được thì hãy ăn nhé."],["よかったら、電話してください。","Nếu được thì hãy gọi điện nhé."],["よかったら、いっしょに行きましょう。","Nếu được thì chúng ta cùng đi nhé."]]},{"word":"このあいだ","reading":"このあいだ","meaning":"vừa rồi, hôm nọ","hanViet":"","lesson":20,"ex":[["このあいだ、映画を見ました。","Hôm nọ tôi đã xem phim."],["このあいだ、友達とごはんを食べました。","Hôm nọ tôi đã ăn cơm với bạn."],["このあいだ、山田さんに手紙をもらいました。","Hôm nọ tôi đã nhận thư của anh Yamada."],["このあいだ、新しいかばんを買いました。","Hôm nọ tôi đã mua cặp mới."],["このあいだ、公園で散歩しました。","Hôm nọ tôi đã đi dạo ở công viên."]]},{"word":"思います","reading":"おもいます","meaning":"nghĩ","hanViet":"","lesson":21,"ex":[["日本語は難しいと思います。","Tôi nghĩ tiếng Nhật khó."],["この本はおもしろいと思います。","Tôi nghĩ quyển sách này thú vị."],["田中さんはいい人だと思います。","Tôi nghĩ anh Tanaka là người tốt."],["あしたは雨だと思います。","Tôi nghĩ ngày mai trời mưa."],["あしたは寒いと思います。","Tôi nghĩ ngày mai trời lạnh."]]},{"word":"言います","reading":"いいます","meaning":"nói","hanViet":"NGÔN","lesson":21,"ex":[["田中さんはあした来ると言います。","Anh Tanaka nói ngày mai sẽ đến."],["先生は日本語で話すと言います。","Thầy giáo nói sẽ nói bằng tiếng Nhật."],["母は早く帰ると言いました。","Mẹ tôi nói sẽ về sớm."],["田中さんは日本が好きだと言います。","Anh Tanaka nói thích Nhật Bản."],["兄は先生だと言います。","Anh trai tôi nói anh ấy là thầy giáo."]]},{"word":"足ります","reading":"たります","meaning":"đủ","hanViet":"TÚC","lesson":21,"ex":[["お金が足りますか？","Tiền có đủ không?"],["お金が足りません。","Tiền không đủ."],["時間が足りますか。","Thời gian có đủ không?"],["このお金で足ります。","Số tiền này là đủ."],["一万円で足りますか。","10.000 yên có đủ không?"]]},{"word":"勝ちます","reading":"かちます","meaning":"thắng","hanViet":"","lesson":21,"ex":[["日本は試合に勝ちました。","Nhật Bản đã thắng trận đấu."],["あした、試合に勝ちます。","Ngày mai tôi sẽ thắng trận đấu."],["田中さんはテニスの試合に勝ちました。","Anh Tanaka đã thắng trận đấu tennis."],["日本はサッカーの試合に勝ちます。","Nhật Bản sẽ thắng trận đấu bóng đá."],["兄は卓球の試合に勝ちました。","Anh trai tôi đã thắng trận đấu bóng bàn."]]},{"word":"負けます","reading":"まけます","meaning":"thua","hanViet":"","lesson":21,"ex":[["日本は試合に負けました。","Nhật Bản đã thua trận đấu."],["わたしたちは試合に負けました。","Chúng tôi đã thua trận đấu."],["田中さんはテニスの試合に負けました。","Anh Tanaka đã thua trận đấu tennis."],["きのう、日本はサッカーの試合に負けました。","Hôm qua Nhật Bản đã thua trận đấu bóng đá."],["兄は卓球の試合に負けました。","Anh trai tôi đã thua trận đấu bóng bàn."]]},{"word":"役に立ちます","reading":"やくにたちます","meaning":"giúp ích","hanViet":"","lesson":21,"ex":[["日本語は仕事に役に立ちます。","Tiếng Nhật giúp ích cho công việc."],["英語は旅行に役に立ちます。","Tiếng Anh giúp ích cho du lịch."],["この辞書は勉強に役に立ちます。","Quyển từ điển này giúp ích cho việc học."],["コンピューターは仕事に役に立ちます。","Máy tính giúp ích cho công việc."],["日本語は生活に役に立ちます。","Tiếng Nhật giúp ích cho cuộc sống."]]},{"word":"むだ","reading":"むだ","meaning":"lãng phí, vô ích","hanViet":"","lesson":21,"ex":[["それはむだです。","Việc đó là lãng phí."],["時間がむだです。","Thời gian bị lãng phí."],["むだなお金を使いました。","Tôi đã tiêu tiền lãng phí."],["これはむだです。","Việc này là lãng phí."],["お金をむだにしました。","Tôi đã lãng phí tiền."]]},{"word":"不便","reading":"ふべん","meaning":"Bất tiện","hanViet":"BẤT TIỆN","lesson":21,"ex":[["ここは交通が不便です。","Giao thông ở đây bất tiện."],["ここは不便です。","Ở đây bất tiện."],["このアパートは駅から遠いですから、不便です。","Căn hộ này xa ga nên bất tiện."],["電車がありませんから、不便です。","Không có tàu điện nên bất tiện."],["ここは買い物が不便です。","Mua sắm ở đây bất tiện."]]},{"word":"同じ","reading":"おなじ","meaning":"Giống nhau, cùng","hanViet":"ĐỒNG","lesson":21,"ex":[["田中さんと同じ意見です。","Tôi có cùng ý kiến với anh Tanaka."],["わたしと同じ本です。","Đó là quyển sách giống của tôi."],["友達と同じかばんです。","Đó là chiếc cặp giống của bạn tôi."],["山田さんと同じ会社で働きます。","Tôi làm việc ở cùng công ty với anh Yamada."],["母と同じ服を着ます。","Tôi mặc quần áo giống mẹ."]]},{"word":"すごい","reading":"すごい","meaning":"giỏi","hanViet":"","lesson":21,"ex":[["田中さんはテニスがすごいです。","Anh Tanaka chơi tennis giỏi thật."],["山田さんはサッカーがすごいです。","Anh Yamada chơi bóng đá giỏi thật."],["先生はピアノがすごいです。","Thầy giáo chơi piano giỏi thật."],["田中さんの日本語はすごいです。","Tiếng Nhật của anh Tanaka giỏi thật."],["友達の歌はすごいです。","Bài hát của bạn tôi tuyệt vời."]]},{"word":"首相","reading":"しゅしょう","meaning":"Thủ tướng","hanViet":"THỦ TƯỚNG","lesson":21,"ex":[["首相はテレビで話します。","Thủ tướng nói chuyện trên ti vi."],["首相は有名です。","Thủ tướng nổi tiếng."],["首相は会議に行きます。","Thủ tướng đi họp."],["首相の話を聞きます。","Tôi nghe câu chuyện của thủ tướng."],["テレビで首相を見ました。","Tôi đã thấy thủ tướng trên ti vi."]]},{"word":"大統領","reading":"だいとうりょう","meaning":"Tổng thống","hanViet":"ĐẠI THỐNG LÃNH","lesson":21,"ex":[["アメリカの大統領は有名です。","Tổng thống Mỹ rất nổi tiếng."],["大統領はテレビで話します。","Tổng thống nói chuyện trên ti vi."],["大統領は国で有名です。","Tổng thống nổi tiếng trong nước."],["ニュースで大統領を見ました。","Tôi đã thấy tổng thống trên bản tin."],["大統領のスピーチを聞きました。","Tôi đã nghe bài phát biểu của tổng thống."]]},{"word":"政治","reading":"せいじ","meaning":"Chính trị","hanViet":"CHÍNH TRỊ","lesson":21,"ex":[["父は政治について話します。","Bố tôi nói về chính trị."],["政治について勉強します。","Tôi học về chính trị."],["政治は難しいです。","Chính trị khó."],["政治のニュースを見ます。","Tôi xem tin tức chính trị."],["父は政治が好きです。","Bố tôi thích chính trị."]]},{"word":"試合","reading":"しあい","meaning":"Trận đấu, trận thi đấu","hanViet":"SĨ HỢP","lesson":21,"ex":[["あした、サッカーの試合があります。","Ngày mai có trận đấu bóng đá."],["試合は三時からです。","Trận đấu bắt đầu từ 3 giờ."],["きのう、試合を見ました。","Hôm qua tôi đã xem trận đấu."],["テニスの試合はおもしろいです。","Trận đấu tennis thú vị."],["あした、野球の試合があります。","Ngày mai có trận đấu bóng chày."]]},{"word":"意見","reading":"いけん","meaning":"Ý kiến","hanViet":"Ý KIẾN","lesson":21,"ex":[["あなたの意見を聞きます。","Tôi nghe ý kiến của bạn."],["いい意見ですね。","Ý kiến hay nhỉ."],["あなたの意見はどうですか。","Ý kiến của bạn thế nào?"],["意見を言ってください。","Hãy nói ý kiến của bạn."],["意見が違います。","Ý kiến khác nhau."]]},{"word":"話","reading":"はなし","meaning":"câu chuyện","hanViet":"THOẠI","lesson":21,"ex":[["先生の話はおもしろいです。","Câu chuyện của thầy giáo rất thú vị."],["母の話は楽しいです。","Câu chuyện của mẹ vui."],["友達の話を聞きます。","Tôi nghe câu chuyện của bạn."],["おじいさんの話はおもしろいです。","Câu chuyện của ông tôi rất thú vị."],["話が長いです。","Câu chuyện dài."]]},{"word":"交通","reading":"こうつう","meaning":"Giao thông","hanViet":"GIAO THÔNG","lesson":21,"ex":[["ここの交通は便利です。","Giao thông ở đây thuận tiện."],["日本の交通は便利です。","Giao thông Nhật Bản thuận tiện."],["交通について話します。","Tôi nói về giao thông."],["ここの交通はどうですか。","Giao thông ở đây thế nào?"],["交通が大変です。","Giao thông rất tệ."]]},{"word":"最近","reading":"さいきん","meaning":"Gần đây, dạo này","hanViet":"TỐI CẬN","lesson":21,"ex":[["最近、日本語を勉強しています。","Gần đây tôi đang học tiếng Nhật."],["最近、映画を見ました。","Gần đây tôi đã xem phim."],["最近、忙しいです。","Dạo này tôi bận."],["最近、テニスをしています。","Gần đây tôi đang chơi tennis."],["最近、友達に会いませんでした。","Gần đây tôi đã không gặp bạn."]]},{"word":"たぶん","reading":"たぶん","meaning":"có lẽ","hanViet":"","lesson":21,"ex":[["たぶん、あしたは雨です。","Có lẽ ngày mai trời mưa."],["たぶん、あしたは寒いです。","Có lẽ ngày mai trời lạnh."],["たぶん、田中さんは来ます。","Có lẽ anh Tanaka sẽ đến."],["たぶん、試験は難しいです。","Có lẽ kỳ thi khó."],["たぶん、電車は遅いです。","Có lẽ tàu điện chậm."]]},{"word":"きっと","reading":"きっと","meaning":"chắc chắn","hanViet":"","lesson":21,"ex":[["きっと、日本は試合に勝ちます。","Chắc chắn Nhật Bản sẽ thắng trận đấu."],["きっと、あしたはいい天気です。","Chắc chắn ngày mai thời tiết đẹp."],["きっと、試験は大丈夫です。","Chắc chắn kỳ thi sẽ ổn."],["きっと、日本語が上手になります。","Chắc chắn tiếng Nhật sẽ giỏi lên."],["きっと、友達は来ます。","Chắc chắn bạn tôi sẽ đến."]]},{"word":"ほんとうに","reading":"ほんとうに","meaning":"thật sự","hanViet":"","lesson":21,"ex":[["ほんとうに、おいしいです。","Thật sự rất ngon."],["ほんとうに、楽しいです。","Thật sự rất vui."],["ほんとうに、ありがとうございます。","Thật sự cảm ơn bạn."],["ほんとうに、日本語は難しいです。","Thật sự tiếng Nhật khó."],["この映画はほんとうにおもしろいです。","Bộ phim này thật sự thú vị."]]},{"word":"そんなに","reading":"そんなに","meaning":"(không) ~ lắm","hanViet":"","lesson":21,"ex":[["この本はそんなに高くありません。","Quyển sách này không đắt lắm."],["この本はそんなに安くありません。","Quyển sách này không rẻ lắm."],["日本語はそんなに難しくありません。","Tiếng Nhật không khó lắm."],["あしたはそんなに暑くありません。","Ngày mai không nóng lắm."],["このかばんはそんなに重くありません。","Chiếc cặp này không nặng lắm."]]},{"word":"ニュース","reading":"ニュース","meaning":"tin tức","hanViet":"","lesson":21,"ex":[["毎朝、ニュースを見ます。","Mỗi sáng tôi xem tin tức."],["ニュースを聞きます。","Tôi nghe tin tức."],["ニュースで天気を見ます。","Tôi xem thời tiết trên bản tin."],["ニュースはおもしろいです。","Tin tức thú vị."],["日本語のニュースは難しいです。","Tin tức tiếng Nhật khó."]]},{"word":"スピーチ","reading":"スピーチ","meaning":"bài phát biểu","hanViet":"","lesson":21,"ex":[["田中さんのスピーチはおもしろいです。","Bài phát biểu của anh Tanaka rất thú vị."],["先生のスピーチを聞きました。","Tôi đã nghe bài phát biểu của thầy giáo."],["スピーチは難しいです。","Bài phát biểu khó."],["あした、スピーチをします。","Ngày mai tôi phát biểu."],["山田さんのスピーチは長いです。","Bài phát biểu của anh Yamada dài."]]},{"word":"ユーモア","reading":"ユーモア","meaning":"hài hước","hanViet":"","lesson":21,"ex":[["先生はユーモアがあります。","Thầy giáo có khiếu hài hước."],["田中さんはユーモアがあります。","Anh Tanaka có khiếu hài hước."],["ユーモアのある話は楽しいです。","Câu chuyện hài hước vui."],["先生のユーモアはおもしろいです。","Sự hài hước của thầy giáo thú vị."],["母はユーモアがあります。","Mẹ tôi có khiếu hài hước."]]},{"word":"デザイン","reading":"デザイン","meaning":"thiết kế","hanViet":"","lesson":21,"ex":[["この車のデザインはすてきです。","Thiết kế của chiếc xe này rất đẹp."],["この服のデザインが好きです。","Tôi thích thiết kế của bộ quần áo này."],["デザインは新しいです。","Thiết kế mới."],["デザインを勉強します。","Tôi học thiết kế."],["この本のデザインはきれいです。","Thiết kế của quyển sách này đẹp."]]},{"word":"ラッシュ","reading":"ラッシュ","meaning":"giờ cao điểm","hanViet":"","lesson":21,"ex":[["朝のラッシュは大変です。","Giờ cao điểm buổi sáng rất vất vả."],["朝のラッシュはすごいです。","Giờ cao điểm buổi sáng thật kinh khủng."],["ラッシュの時間に電車に乗ります。","Tôi đi tàu điện vào giờ cao điểm."],["ラッシュは八時からです。","Giờ cao điểm bắt đầu từ 8 giờ."],["朝のラッシュが嫌いです。","Tôi ghét giờ cao điểm buổi sáng."]]},{"word":"～について","reading":"～について","meaning":"về ~","hanViet":"","lesson":21,"ex":[["日本の政治について話します。","Tôi nói về chính trị Nhật Bản."],["日本について勉強します。","Tôi học về Nhật Bản."],["旅行について話します。","Tôi nói về du lịch."],["日本語について聞きます。","Tôi hỏi về tiếng Nhật."],["本について先生に聞きました。","Tôi đã hỏi thầy giáo về quyển sách."]]},{"word":"しかたがありません","reading":"しかたがありません","meaning":"không còn cách nào khác","hanViet":"","lesson":21,"ex":[["電車がありません。しかたがありません。","Không có tàu điện. Không còn cách nào khác."],["雨です。しかたがありません。","Trời mưa. Không còn cách nào khác."],["お金がありません。しかたがありません。","Không có tiền. Không còn cách nào khác."],["電車が遅いです。しかたがありません。","Tàu điện chậm. Không còn cách nào khác."],["先生がいません。しかたがありません。","Không có thầy giáo. Không còn cách nào khác."]]},{"word":"しばらくですね","reading":"しばらくですね","meaning":"lâu không gặp nhỉ","hanViet":"","lesson":21,"ex":[["しばらくですね。お元気ですか？","Lâu không gặp nhỉ. Bạn có khỏe không?"],["田中さん、しばらくですね。","Anh Tanaka, lâu không gặp nhỉ."],["しばらくですね。あした、会いましょう。","Lâu không gặp nhỉ. Ngày mai chúng ta gặp nhau nhé."],["しばらくですね。日本語は上手になりましたね。","Lâu không gặp nhỉ. Tiếng Nhật của bạn đã giỏi lên nhỉ."],["しばらくですね。きょうはいい天気ですね。","Lâu không gặp nhỉ. Hôm nay thời tiết đẹp nhỉ."]]},{"word":"～でも飲みませんか","reading":"～でものみませんか","meaning":"uống ~ nhé?","hanViet":"","lesson":21,"ex":[["コーヒーでも飲みませんか？","Uống cà phê nhé?"],["あした、お茶でも飲みませんか？","Ngày mai uống trà nhé?"],["ジュースでも飲みませんか？","Uống nước trái cây nhé?"],["今晩、ビールでも飲みませんか？","Tối nay uống bia nhé?"],["水でも飲みませんか？","Uống nước nhé?"]]},{"word":"もちろん","reading":"もちろん","meaning":"tất nhiên","hanViet":"","lesson":21,"ex":[["もちろん、行きます。","Tất nhiên là tôi đi."],["もちろん、日本語を勉強します。","Tất nhiên tôi học tiếng Nhật."],["もちろん、友達も来ます。","Tất nhiên bạn tôi cũng đến."],["もちろん、大丈夫です。","Tất nhiên là ổn."],["もちろん、あしたは休みです。","Tất nhiên ngày mai là ngày nghỉ."]]},{"word":"着ます","reading":"きます","meaning":"mặc","hanViet":"","lesson":22,"ex":[["今日はコートを着ます。","Hôm nay tôi mặc áo khoác."],["毎日、スーツを着ます。","Ngày nào tôi cũng mặc com-lê."],["山田さんはコートを着ます。","Anh Yamada mặc áo khoác."],["寒いですから、セーターを着ます。","Vì trời lạnh nên tôi mặc áo len."],["新しい服を着ました。","Tôi đã mặc quần áo mới."]]},{"word":"はきます","reading":"はきます","meaning":"đi, mặc (giày, quần)","hanViet":"","lesson":22,"ex":[["くつしたをはきます。","Tôi đi tất."],["靴をはきます。","Tôi đi giày."],["白いくつしたをはきます。","Tôi đi đôi tất trắng."],["学校で靴をはきます。","Ở trường tôi đi giày."],["寒いですから、くつしたをはきます。","Vì trời lạnh nên tôi đi tất."]]},{"word":"かぶります","reading":"かぶります","meaning":"đội (mũ)","hanViet":"","lesson":22,"ex":[["帽子をかぶります。","Tôi đội mũ."],["新しい帽子をかぶります。","Tôi đội chiếc mũ mới."],["夏に帽子をかぶります。","Vào mùa hè tôi đội mũ."],["妹は帽子をかぶります。","Em gái tôi đội mũ."],["暑いですから、帽子をかぶります。","Vì trời nóng nên tôi đội mũ."]]},{"word":"生まれます","reading":"うまれます","meaning":"sinh ra","hanViet":"SINH","lesson":22,"ex":[["わたしはベトナムで生まれました。","Tôi sinh ra ở Việt Nam."],["田中さんは日本で生まれました。","Anh Tanaka sinh ra ở Nhật Bản."],["わたしは四月に生まれました。","Tôi sinh ra vào tháng 4."],["子どもが生まれます。","Đứa trẻ sẽ ra đời."],["わたしは2000年に生まれました。","Tôi sinh ra vào năm 2000."]]},{"word":"帽子","reading":"ぼうし","meaning":"Mũ, nón","hanViet":"MẠO TỬ","lesson":22,"ex":[["赤い帽子をかぶります。","Tôi đội chiếc mũ đỏ."],["この帽子は新しいです。","Chiếc mũ này mới."],["帽子を買いました。","Tôi đã mua mũ."],["白い帽子が好きです。","Tôi thích chiếc mũ trắng."],["帽子はどこですか。","Mũ ở đâu?"]]},{"word":"おめでとうございます","reading":"おめでとうございます","meaning":"chúc mừng","hanViet":"","lesson":22,"ex":[["誕生日おめでとうございます。","Chúc mừng sinh nhật."],["結婚おめでとうございます。","Chúc mừng kết hôn."],["卒業おめでとうございます。","Chúc mừng tốt nghiệp."],["就職おめでとうございます。","Chúc mừng có việc làm."],["子どもが生まれました。おめでとうございます。","Đứa trẻ đã ra đời. Chúc mừng."]]},{"word":"家賃","reading":"やちん","meaning":"Tiền thuê nhà","hanViet":"GIA THẢI","lesson":22,"ex":[["家賃は五万円です。","Tiền thuê nhà là 50.000 yên."],["家賃は高いです。","Tiền thuê nhà đắt."],["家賃は安いです。","Tiền thuê nhà rẻ."],["家賃を銀行で払います。","Tôi trả tiền thuê nhà ở ngân hàng."],["家賃はいくらですか。","Tiền thuê nhà là bao nhiêu?"]]},{"word":"和室","reading":"わしつ","meaning":"Phòng kiểu Nhật","hanViet":"HÒA THẤT","lesson":22,"ex":[["このアパートに和室があります。","Căn hộ này có phòng kiểu Nhật."],["和室は広いです。","Phòng kiểu Nhật rộng."],["和室で寝ます。","Tôi ngủ trong phòng kiểu Nhật."],["うちに和室があります。","Nhà tôi có phòng kiểu Nhật."],["和室は静かです。","Phòng kiểu Nhật yên tĩnh."]]},{"word":"押し入れ","reading":"おしいれ","meaning":"tủ nằm trong tường","hanViet":"","lesson":22,"ex":[["押し入れに布団があります。","Trong tủ âm tường có chăn nệm."],["押し入れに服があります。","Trong tủ âm tường có quần áo."],["押し入れは小さいです。","Tủ âm tường nhỏ."],["押し入れに布団を置きます。","Tôi cất chăn nệm vào tủ âm tường."],["押し入れを開けます。","Tôi mở tủ âm tường."]]},{"word":"布団","reading":"ふとん","meaning":"Chăn nệm (futon)","hanViet":"BỐ ĐOÀN","lesson":22,"ex":[["布団で寝ます。","Tôi ngủ trên chăn nệm."],["布団は暖かいです。","Chăn nệm ấm."],["新しい布団を買いました。","Tôi đã mua chăn nệm mới."],["布団で休みます。","Tôi nghỉ ngơi trên chăn nệm."],["布団はどこにありますか。","Chăn nệm ở đâu?"]]},{"word":"手袋","reading":"てぶくろ","meaning":"Găng tay","hanViet":"THỦ ĐÁI","lesson":22,"ex":[["この手袋は暖かいです。","Đôi găng tay này ấm."],["手袋を買いました。","Tôi đã mua găng tay."],["寒いですから、手袋をします。","Vì trời lạnh nên tôi đeo găng tay."],["この手袋は新しいです。","Đôi găng tay này mới."],["白い手袋が好きです。","Tôi thích đôi găng tay trắng."]]},{"word":"コート","reading":"コート","meaning":"áo khoác","hanViet":"","lesson":22,"ex":[["冬はコートを着ます。","Mùa đông tôi mặc áo khoác."],["新しいコートを買いました。","Tôi đã mua áo khoác mới."],["このコートは高いです。","Chiếc áo khoác này đắt."],["コートはどこですか。","Áo khoác ở đâu?"],["黒いコートを着ます。","Tôi mặc áo khoác đen."]]},{"word":"スーツ","reading":"スーツ","meaning":"com-lê","hanViet":"","lesson":22,"ex":[["会社でスーツを着ます。","Ở công ty tôi mặc com-lê."],["父は新しいスーツを買いました。","Bố tôi đã mua com-lê mới."],["山田さんのスーツはすてきです。","Bộ com-lê của anh Yamada đẹp."],["父はスーツを着ます。","Bố tôi mặc com-lê."],["山田さんはスーツが好きです。","Anh Yamada thích com-lê."]]},{"word":"セーター","reading":"セーター","meaning":"áo len","hanViet":"","lesson":22,"ex":[["このセーターは高いです。","Chiếc áo len này đắt."],["母はセーターを買いました。","Mẹ tôi đã mua áo len."],["このセーターは暖かいです。","Chiếc áo len này ấm."],["冬はセーターを着ます。","Mùa đông tôi mặc áo len."],["赤いセーターが好きです。","Tôi thích chiếc áo len đỏ."]]},{"word":"スカート","reading":"スカート","meaning":"váy","hanViet":"","lesson":22,"ex":[["このスカートは短いです。","Chiếc váy này ngắn."],["妹は新しいスカートを買いました。","Em gái tôi đã mua váy mới."],["このスカートは長いです。","Chiếc váy này dài."],["妹はスカートを着ます。","Em gái tôi mặc váy."],["白いスカートを着ました。","Tôi đã mặc chiếc váy trắng."]]},{"word":"くつした","reading":"くつした","meaning":"tất","hanViet":"","lesson":22,"ex":[["赤いくつしたをはきます。","Tôi đi đôi tất đỏ."],["白いくつしたを買いました。","Tôi đã mua đôi tất trắng."],["このくつしたは新しいです。","Đôi tất này mới."],["新しいくつしたはどこですか。","Đôi tất mới ở đâu?"],["毎日、くつしたをはきます。","Ngày nào tôi cũng đi tất."]]},{"word":"ダイニングキッチン","reading":"ダイニングキッチン","meaning":"bếp kèm phòng ăn","hanViet":"","lesson":22,"ex":[["このアパートにダイニングキッチンがあります。","Căn hộ này có bếp kèm phòng ăn."],["ダイニングキッチンは広いです。","Bếp kèm phòng ăn rộng."],["ダイニングキッチンでごはんを食べます。","Tôi ăn cơm ở bếp kèm phòng ăn."],["うちにダイニングキッチンがあります。","Nhà tôi có bếp kèm phòng ăn."],["ダイニングキッチンは新しいです。","Bếp kèm phòng ăn mới."]]},{"word":"アパート","reading":"アパート","meaning":"căn hộ","hanViet":"","lesson":22,"ex":[["わたしのアパートは小さいです。","Căn hộ của tôi nhỏ."],["アパートは駅の近くにあります。","Căn hộ ở gần ga."],["新しいアパートに引っ越しします。","Tôi chuyển đến căn hộ mới."],["アパートの家賃は四万円です。","Tiền thuê căn hộ là 40.000 yên."],["このアパートは新しいです。","Căn hộ này mới."]]},{"word":"ケーキ","reading":"ケーキ","meaning":"bánh ngọt","hanViet":"","lesson":22,"ex":[["誕生日にケーキを食べます。","Vào sinh nhật tôi ăn bánh ngọt."],["ケーキを買いました。","Tôi đã mua bánh ngọt."],["このケーキはおいしいです。","Chiếc bánh này ngon."],["ケーキは甘いです。","Bánh ngọt ngọt."],["友達にケーキをあげます。","Tôi tặng bánh cho bạn."]]},{"word":"うーん","reading":"うーん","meaning":"để xem sao","hanViet":"","lesson":22,"ex":[["うーん、わかりません。","Để xem sao, tôi không biết."],["うーん、難しいです。","Để xem sao, khó thật."],["うーん、どうしようかな。","Để xem sao, làm thế nào được nhỉ?"],["うーん、高いですね。","Để xem sao, đắt nhỉ."],["うーん、行きます。","Để xem sao, tôi sẽ đi."]]},{"word":"回します","reading":"まわします","meaning":"vặn","hanViet":"","lesson":23,"ex":[["つまみを右に回します。","Tôi vặn núm sang phải."],["つまみを左に回します。","Tôi vặn núm sang trái."],["つまみを回してください。","Hãy vặn núm."],["テレビのつまみを回します。","Tôi vặn núm của ti vi."],["つまみをゆっくり回します。","Tôi vặn núm từ từ."]]},{"word":"引きます","reading":"ひきます","meaning":"kéo","hanViet":"","lesson":23,"ex":[["ドアを引きます。","Tôi kéo cửa."],["ドアを引いてください。","Hãy kéo cửa."],["ドアを引くことができます。","Tôi có thể kéo cửa."],["ドアをゆっくり引きます。","Tôi kéo cửa từ từ."],["重いドアを引きます。","Tôi kéo cánh cửa nặng."]]},{"word":"変えます","reading":"かえます","meaning":"đổi","hanViet":"","lesson":23,"ex":[["約束の時間を変えます。","Tôi đổi giờ hẹn."],["時間を変えます。","Tôi đổi giờ."],["約束を変えました。","Tôi đã đổi lời hẹn."],["服を変えます。","Tôi đổi quần áo."],["日を変えます。","Tôi đổi ngày."]]},{"word":"触ります","reading":"さわります","meaning":"chạm, sờ","hanViet":"","lesson":23,"ex":[["機械に触らないでください。","Xin đừng chạm vào máy."],["犬に触ります。","Tôi chạm vào con chó."],["猫に触らないでください。","Xin đừng chạm vào con mèo."],["機械に触ります。","Tôi chạm vào máy."],["熱い物に触らないでください。","Xin đừng chạm vào đồ nóng."]]},{"word":"動きます","reading":"うごきます","meaning":"chuyển động","hanViet":"","lesson":23,"ex":[["車が動きます。","Xe chuyển động."],["電車が動きます。","Tàu điện chuyển động."],["車が動きません。","Xe không chuyển động."],["自転車が動きます。","Xe đạp chuyển động."],["時計が動きます。","Đồng hồ chạy."]]},{"word":"歩きます","reading":"あるきます","meaning":"đi bộ","hanViet":"","lesson":23,"ex":[["学校まで歩きます。","Tôi đi bộ đến trường."],["毎日、駅まで歩きます。","Mỗi ngày tôi đi bộ đến ga."],["毎日、歩きます。","Ngày nào tôi cũng đi bộ."],["公園を歩きます。","Tôi đi bộ trong công viên."],["友達と歩きます。","Tôi đi bộ với bạn."]]},{"word":"渡ります","reading":"わたります","meaning":"qua, đi qua (cầu)","hanViet":"","lesson":23,"ex":[["橋を渡ります。","Tôi đi qua cầu."],["橋を渡って、学校に行きます。","Tôi đi qua cầu rồi đến trường."],["川を渡ります。","Tôi đi qua sông."],["道を渡ります。","Tôi đi qua đường."],["横断歩道を渡って、学校へ行きます。","Tôi qua đường dành cho người đi bộ rồi đi học."]]},{"word":"気をつけます","reading":"きをつけます","meaning":"cẩn thận","hanViet":"KHÍ","lesson":23,"ex":[["車に気をつけてください。","Hãy cẩn thận với xe cộ."],["電車に気をつけてください。","Hãy cẩn thận với tàu điện."],["車に気をつけます。","Tôi cẩn thận với xe cộ."],["自転車に気をつけてください。","Hãy cẩn thận với xe đạp."],["寒いですから、体に気をつけてください。","Vì trời lạnh nên hãy giữ gìn sức khỏe."]]},{"word":"引っ越しします","reading":"ひっこしします","meaning":"chuyển nhà","hanViet":"","lesson":23,"ex":[["来月、引っ越しします。","Tháng sau tôi chuyển nhà."],["来年、引っ越しします。","Năm sau tôi chuyển nhà."],["四月に引っ越しします。","Tôi chuyển nhà vào tháng 4."],["引っ越ししますから、荷物が多いです。","Vì tôi chuyển nhà nên có nhiều hành lý."],["引っ越しの前に掃除をします。","Trước khi chuyển nhà tôi dọn dẹp."]]},{"word":"電気屋","reading":"でんきや","meaning":"cửa hàng đồ điện","hanViet":"","lesson":23,"ex":[["電気屋でテレビを買います。","Tôi mua ti vi ở cửa hàng đồ điện."],["電気屋でパソコンを買います。","Tôi mua máy tính ở cửa hàng đồ điện."],["電気屋は駅の近くにあります。","Cửa hàng đồ điện ở gần ga."],["電気屋で電池を買いました。","Tôi đã mua pin ở cửa hàng đồ điện."],["電気屋に電話します。","Tôi gọi điện cho cửa hàng đồ điện."]]},{"word":"音","reading":"おと","meaning":"Âm thanh, tiếng","hanViet":"ÂM","lesson":23,"ex":[["大きい音がします。","Có tiếng động lớn."],["小さい音がします。","Có tiếng động nhỏ."],["音が大きいです。","Tiếng động lớn."],["ピアノの音はきれいです。","Tiếng đàn piano hay."],["音がしますか。","Có tiếng động không?"]]},{"word":"機械","reading":"きかい","meaning":"Máy móc, máy cơ khí","hanViet":"CƠ GIỚI","lesson":23,"ex":[["この機械は新しいです。","Cái máy này mới."],["会社に新しい機械があります。","Công ty có máy móc mới."],["この機械は大きくて、重いです。","Cái máy này to và nặng."],["田中さんは機械を直しました。","Anh Tanaka đã sửa máy."],["この機械は動きます。","Cái máy này chạy được."]]},{"word":"つまみ","reading":"つまみ","meaning":"núm vặn","hanViet":"","lesson":23,"ex":[["つまみを回します。","Tôi vặn núm."],["つまみを右へ回してください。","Hãy vặn núm sang phải."],["このつまみは小さいです。","Cái núm này nhỏ."],["ラジオのつまみを回します。","Tôi vặn núm của radio."],["テレビのつまみを右に回します。","Tôi vặn núm của ti vi sang phải."]]},{"word":"故障","reading":"こしょう","meaning":"hỏng hóc, trục trặc","hanViet":"CỐ CHƯỚNG","lesson":23,"ex":[["車が故障しました。","Xe bị hỏng."],["エアコンが故障しました。","Điều hòa bị hỏng."],["機械が故障して、動きません。","Máy bị hỏng nên không chạy."],["故障した車を直します。","Tôi sửa chiếc xe bị hỏng."],["エレベーターが故障しました。","Thang máy bị hỏng."]]},{"word":"道","reading":"みち","meaning":"Con đường, đường đi","hanViet":"ĐẠO","lesson":23,"ex":[["この道は広いです。","Con đường này rộng."],["道が狭いです。","Đường hẹp."],["学校までの道を歩きます。","Tôi đi bộ trên đường đến trường."],["道に車がたくさんあります。","Trên đường có nhiều xe."],["この道をまっすぐ行きます。","Tôi đi thẳng con đường này."]]},{"word":"交差点","reading":"こうさてん","meaning":"ngã tư, điểm giao nhau","hanViet":"GIAO SAI ĐIỂM","lesson":23,"ex":[["交差点で右へ曲がります。","Tôi rẽ phải ở ngã tư."],["交差点で左へ曲がってください。","Hãy rẽ trái ở ngã tư."],["交差点の前に信号があります。","Trước ngã tư có đèn giao thông."],["次の交差点で車を止めます。","Tôi dừng xe ở ngã tư tiếp theo."],["交差点は危ないから、気をつけてください。","Ngã tư nguy hiểm nên hãy cẩn thận."]]},{"word":"信号","reading":"しんごう","meaning":"tín hiệu, đèn giao thông","hanViet":"TÍN HIỆU","lesson":23,"ex":[["信号が赤いです。","Đèn giao thông đang đỏ."],["信号が青いです。","Đèn giao thông đang xanh."],["信号の前で車を止めます。","Tôi dừng xe trước đèn giao thông."],["信号が赤いから、行きません。","Vì đèn đỏ nên tôi không đi."],["次の信号を左へ曲がります。","Tôi rẽ trái ở đèn giao thông tiếp theo."]]},{"word":"角","reading":"かど","meaning":"Góc (nhà, đường)","hanViet":"GIÁC","lesson":23,"ex":[["角に郵便局があります。","Ở góc đường có bưu điện."],["角の店でパンを買います。","Tôi mua bánh mì ở cửa hàng góc đường."],["角を右へ曲がります。","Tôi rẽ phải ở góc đường."],["角に交番があります。","Ở góc đường có đồn cảnh sát."],["その角に大きい木があります。","Ở góc đó có cây to."]]},{"word":"橋","reading":"はし","meaning":"Cây cầu","hanViet":"KIỀU","lesson":23,"ex":[["この橋は長いです。","Cây cầu này dài."],["橋の上で写真を撮ります。","Tôi chụp ảnh trên cầu."],["川に橋があります。","Trên sông có cây cầu."],["橋を渡って、学校へ行きます。","Tôi đi qua cầu rồi đến trường."],["あの橋は古いです。","Cây cầu kia cũ."]]},{"word":"正月","reading":"しょうがつ","meaning":"tháng Giêng, dịp Tết năm mới","hanViet":"CHÍNH NGUYỆT","lesson":23,"ex":[["正月に国へ帰ります。","Dịp Tết tôi về nước."],["正月に家族とごはんを食べます。","Dịp Tết tôi ăn cơm cùng gia đình."],["正月は一月です。","Tết vào tháng một."],["正月にお年玉をもらいました。","Dịp Tết tôi nhận được tiền lì xì."],["正月に神社へ行きます。","Dịp Tết tôi đi đền thờ."]]},{"word":"ごちそうさま","reading":"ごちそうさま","meaning":"cảm ơn vì bữa ăn","hanViet":"","lesson":23,"ex":[["ごちそうさま、おいしかったです。","Cảm ơn vì bữa ăn, ngon quá."],["ごちそうさま、ありがとうございました。","Cảm ơn vì bữa ăn, cảm ơn anh/chị rất nhiều."],["ごはんのあとで、ごちそうさまと言います。","Sau bữa cơm, tôi nói \"cảm ơn vì bữa ăn\"."],["おいしいごはんを食べて、ごちそうさまと言いました。","Tôi ăn cơm ngon rồi nói cảm ơn vì bữa ăn."],["母にごちそうさまと言いました。","Tôi đã nói \"cảm ơn vì bữa ăn\" với mẹ."]]},{"word":"建物","reading":"たてもの","meaning":"tòa nhà, công trình","hanViet":"KIẾN VẬT","lesson":23,"ex":[["この建物は大きいです。","Tòa nhà này lớn."],["あの建物は学校です。","Tòa nhà kia là trường học."],["建物の前に公園があります。","Trước tòa nhà có công viên."],["建物の中で働きます。","Tôi làm việc trong tòa nhà."],["建物の二階に教室があります。","Trên tầng hai của tòa nhà có phòng học."]]},{"word":"外国人登録証","reading":"がいこくじんとうろくしょう","meaning":"thẻ đăng kí người nước ngoài","hanViet":"","lesson":23,"ex":[["外国人登録証を持っています。","Tôi đang mang theo thẻ đăng ký người nước ngoài."],["外国人登録証を見せてください。","Hãy cho tôi xem thẻ đăng ký người nước ngoài."],["外国人登録証をなくしました。","Tôi đã làm mất thẻ đăng ký người nước ngoài."],["外国人登録証をうちに忘れました。","Tôi để quên thẻ đăng ký người nước ngoài ở nhà."],["市役所で外国人登録証をもらいました。","Tôi đã nhận thẻ đăng ký người nước ngoài ở tòa thị chính."]]},{"word":"歩道","reading":"ほどう","meaning":"Vỉa hè, lối đi bộ","hanViet":"BỘ ĐẠO","lesson":23,"ex":[["歩道を歩きます。","Tôi đi bộ trên vỉa hè."],["歩道は広いです。","Vỉa hè rộng."],["歩道の上に木があります。","Trên vỉa hè có cây."],["歩道と車道があります。","Có vỉa hè và đường xe chạy."],["歩道をまっすぐ行きます。","Tôi đi thẳng trên vỉa hè."]]},{"word":"車道","reading":"しゃどう","meaning":"đường xe chạy","hanViet":"","lesson":23,"ex":[["車道を歩いてはいけません。","Không được đi bộ trên đường xe chạy."],["車道を車が走ります。","Xe chạy trên đường xe chạy."],["車道は広いです。","Đường xe chạy rộng."],["車道を渡ります。","Tôi đi qua đường xe chạy."],["車道で自転車に乗ります。","Tôi đạp xe trên đường xe chạy."]]},{"word":"高速道路","reading":"こうそくどうろ","meaning":"đường cao tốc","hanViet":"","lesson":23,"ex":[["高速道路で車を運転します。","Tôi lái xe trên đường cao tốc."],["高速道路で車が速く走ります。","Xe chạy nhanh trên đường cao tốc."],["高速道路は長いです。","Đường cao tốc dài."],["高速道路の近くに店があります。","Gần đường cao tốc có cửa hàng."],["あした、高速道路で旅行へ行きます。","Ngày mai tôi đi du lịch bằng đường cao tốc."]]},{"word":"通り","reading":"とおり","meaning":"đường phố","hanViet":"","lesson":23,"ex":[["この通りはにぎやかです。","Phố này nhộn nhịp."],["通りに店がたくさんあります。","Trên phố có nhiều cửa hàng."],["この通りをまっすぐ行きます。","Tôi đi thẳng phố này."],["通りは静かです。","Phố yên tĩnh."],["通りで買い物をします。","Tôi mua sắm trên phố."]]},{"word":"横断歩道","reading":"おうだんほどう","meaning":"đường dành cho người đi bộ","hanViet":"","lesson":23,"ex":[["横断歩道を渡ります。","Tôi đi qua đường dành cho người đi bộ."],["横断歩道で信号を待ちます。","Tôi chờ đèn ở vạch qua đường."],["横断歩道を渡ってください。","Hãy đi qua vạch qua đường."],["横断歩道の前で車を止めます。","Tôi dừng xe trước vạch qua đường."],["横断歩道は白いです。","Vạch qua đường màu trắng."]]},{"word":"歩道橋","reading":"ほどうきょう","meaning":"Cầu vượt cho người đi bộ","hanViet":"BỘ ĐẠO KIỀU","lesson":23,"ex":[["歩道橋を渡ります。","Tôi đi qua cầu vượt cho người đi bộ."],["歩道橋は高いです。","Cầu vượt cao."],["子どもと歩道橋を渡ります。","Tôi cùng trẻ con đi qua cầu vượt."],["歩道橋の下を車が走ります。","Xe chạy dưới cầu vượt."],["あの歩道橋は新しいです。","Cầu vượt kia mới."]]},{"word":"坂","reading":"さか","meaning":"Con dốc","hanViet":"BẢN","lesson":23,"ex":[["この坂は長いです。","Con dốc này dài."],["坂を自転車で登ります。","Tôi đạp xe lên dốc."],["坂の下に公園があります。","Dưới dốc có công viên."],["坂を歩いて、学校へ行きます。","Tôi đi bộ qua dốc rồi đến trường."],["あの坂は短いです。","Con dốc kia ngắn."]]},{"word":"踏切","reading":"ふみきり","meaning":"đường ngang qua đường sắt","hanViet":"ĐẠP THIẾT","lesson":23,"ex":[["踏切の前で電車を待ちます。","Tôi chờ tàu trước đường ngang qua đường sắt."],["踏切を渡ります。","Tôi đi qua đường ngang qua đường sắt."],["踏切の前に車がたくさんあります。","Trước đường ngang qua đường sắt có nhiều xe."],["踏切の前で自転車を止めます。","Tôi dừng xe đạp trước đường ngang qua đường sắt."],["踏切の近くに駅があります。","Gần đường ngang qua đường sắt có ga."]]},{"word":"止まれ","reading":"とまれ","meaning":"dừng lại","hanViet":"","lesson":23,"ex":[["信号の前に「止まれ」があります。","Trước đèn giao thông có biển \"Dừng lại\"."],["「止まれ」の前に車を止めます。","Tôi dừng xe trước biển \"Dừng lại\"."],["交差点の前に「止まれ」があります。","Trước ngã tư có biển \"Dừng lại\"."],["「止まれ」を見て、車を止めました。","Tôi thấy biển \"Dừng lại\" rồi dừng xe."],["踏切の前に「止まれ」があります。","Trước đường ngang qua đường sắt có biển \"Dừng lại\"."]]},{"word":"進入禁止","reading":"しんにゅうきんし","meaning":"cấm đi vào","hanViet":"","lesson":23,"ex":[["ここは進入禁止です。","Ở đây cấm đi vào."],["この建物は進入禁止です。","Tòa nhà này cấm đi vào."],["学校は夜、進入禁止です。","Trường học buổi tối cấm đi vào."],["ここは進入禁止ですから、入ってはいけません。","Ở đây cấm đi vào nên không được vào."],["公園は進入禁止ですか。","Công viên có cấm đi vào không?"]]},{"word":"一方通行","reading":"いっぽうつうこう","meaning":"đường 1 chiều","hanViet":"","lesson":23,"ex":[["この道は一方通行です。","Con đường này là đường một chiều."],["この通りは一方通行です。","Phố này là đường một chiều."],["一方通行の道を歩きます。","Tôi đi bộ trên đường một chiều."],["あの道は一方通行ですか。","Con đường kia có phải đường một chiều không?"],["一方通行の道で車を運転します。","Tôi lái xe trên đường một chiều."]]},{"word":"駐車禁止","reading":"ちゅうしゃきんし","meaning":"cấm đỗ xe","hanViet":"","lesson":23,"ex":[["ここは駐車禁止です。","Ở đây cấm đỗ xe."],["学校の前は駐車禁止です。","Trước trường học cấm đỗ xe."],["ここは駐車禁止ですから、車を止めてはいけません。","Ở đây cấm đỗ xe nên không được dừng xe."],["駅の前は駐車禁止ですか。","Trước ga có cấm đỗ xe không?"],["この道は駐車禁止です。","Con đường này cấm đỗ xe."]]},{"word":"右折禁止","reading":"うせつきんし","meaning":"cấm rẽ phải","hanViet":"","lesson":23,"ex":[["ここは右折禁止です。","Ở đây cấm rẽ phải."],["この交差点は右折禁止です。","Ngã tư này cấm rẽ phải."],["ここは右折禁止ですから、左へ曲がります。","Ở đây cấm rẽ phải nên tôi rẽ trái."],["次の交差点は右折禁止ですか。","Ngã tư tiếp theo có cấm rẽ phải không?"],["右折禁止の交差点で左へ曲がります。","Tôi rẽ trái ở ngã tư cấm rẽ phải."]]},{"word":"～目","reading":"～め","meaning":"thứ ~, số ~","hanViet":"","lesson":23,"ex":[["二つ目の信号を右へ曲がります。","Rẽ phải ở đèn giao thông thứ hai."],["三つ目の角を左へ曲がります。","Rẽ trái ở góc thứ ba."],["一つ目の信号で車を止めます。","Tôi dừng xe ở đèn giao thông đầu tiên."],["二つ目の店でパンを買いました。","Tôi đã mua bánh mì ở cửa hàng thứ hai."],["四つ目の橋を渡ります。","Tôi đi qua cây cầu thứ tư."]]},{"word":"サイズ","reading":"サイズ","meaning":"kích cỡ","hanViet":"","lesson":23,"ex":[["このシャツはサイズが大きいです。","Cái áo sơ mi này cỡ lớn."],["この靴のサイズは小さいです。","Đôi giày này cỡ nhỏ."],["このサイズはどうですか。","Cỡ này thế nào?"],["大きいサイズのシャツをください。","Cho tôi áo sơ mi cỡ lớn."],["店員にサイズを聞きました。","Tôi đã hỏi nhân viên về cỡ."]]},{"word":"くれます","reading":"くれます","meaning":"cho, tặng (tôi)","hanViet":"","lesson":24,"ex":[["田中さんが私に本をくれました。","Anh Tanaka đã cho tôi quyển sách."],["母が私にセーターをくれました。","Mẹ đã tặng tôi áo len."],["友達が私に花をくれます。","Bạn tặng tôi hoa."],["先生が私に辞書をくれました。","Thầy giáo đã cho tôi quyển từ điển."],["だれがこの本をくれましたか。","Ai đã cho tôi quyển sách này?"]]},{"word":"連れて行きます","reading":"つれていきます","meaning":"dẫn đi","hanViet":"","lesson":24,"ex":[["友達を病院へ連れて行きました。","Tôi đã dẫn bạn đến bệnh viện."],["子どもを公園へ連れて行きます。","Tôi dẫn trẻ con đến công viên."],["母を買い物へ連れて行きます。","Tôi dẫn mẹ đi mua sắm."],["田中さんを駅へ連れて行きます。","Tôi dẫn anh Tanaka đến ga."],["犬を動物園へ連れて行きますか。","Bạn có dẫn chó đến sở thú không?"]]},{"word":"連れて来ます","reading":"つれてきます","meaning":"dẫn đến","hanViet":"","lesson":24,"ex":[["友達をうちへ連れて来ました。","Tôi đã dẫn bạn về nhà."],["子どもを学校へ連れて来ました。","Tôi đã dẫn trẻ con đến trường."],["田中さんを会社へ連れて来ました。","Tôi đã dẫn anh Tanaka đến công ty."],["犬を公園へ連れて来ます。","Tôi dẫn chó đến công viên."],["母を病院へ連れて来ました。","Tôi đã dẫn mẹ đến bệnh viện."]]},{"word":"紹介します","reading":"しょうかいします","meaning":"giới thiệu","hanViet":"","lesson":24,"ex":[["友達を田中さんに紹介しました。","Tôi đã giới thiệu bạn với anh Tanaka."],["先生を友達に紹介します。","Tôi giới thiệu thầy giáo với bạn."],["日本の歌を友達に紹介しました。","Tôi đã giới thiệu bài hát Nhật với bạn."],["新しい友達を母に紹介しました。","Tôi đã giới thiệu bạn mới với mẹ."],["田中さんを社長に紹介します。","Tôi giới thiệu anh Tanaka với giám đốc."]]},{"word":"案内します","reading":"あんないします","meaning":"hướng dẫn","hanViet":"","lesson":24,"ex":[["田中さんに学校を案内しました。","Tôi đã hướng dẫn anh Tanaka tham quan trường học."],["友達に町を案内します。","Tôi hướng dẫn bạn tham quan thị trấn."],["先生に会社を案内しました。","Tôi đã hướng dẫn thầy giáo tham quan công ty."],["母に大学を案内します。","Tôi hướng dẫn mẹ tham quan trường đại học."],["田中さんに公園を案内しました。","Tôi đã hướng dẫn anh Tanaka tham quan công viên."]]},{"word":"説明します","reading":"せつめいします","meaning":"giải thích","hanViet":"","lesson":24,"ex":[["先生が意味を説明しました。","Thầy giáo đã giải thích ý nghĩa."],["先生が漢字を説明します。","Thầy giáo giải thích chữ Hán."],["田中さんが道を説明しました。","Anh Tanaka đã giải thích đường đi."],["友達が問題を説明してくれました。","Bạn đã giải thích bài tập cho tôi."],["先生に意味を説明してもらいました。","Tôi đã nhờ thầy giáo giải thích ý nghĩa."]]},{"word":"いれます","reading":"いれます","meaning":"pha (cà phê)","hanViet":"","lesson":24,"ex":[["コーヒーをいれました。","Tôi đã pha cà phê."],["紅茶をいれます。","Tôi pha trà."],["お茶をいれてください。","Hãy pha trà giúp tôi."],["母にコーヒーをいれます。","Tôi pha cà phê cho mẹ."],["朝、コーヒーをいれます。","Buổi sáng tôi pha cà phê."]]},{"word":"おじいさん","reading":"おじいさん","meaning":"ông (nội, ngoại)","hanViet":"","lesson":24,"ex":[["おじいさんは田舎に住んでいます。","Ông tôi sống ở quê."],["おじいさんは八十歳です。","Ông tôi 80 tuổi."],["おじいさんに手紙を書きます。","Tôi viết thư cho ông."],["おじいさんと散歩します。","Tôi đi dạo cùng ông."],["おじいさんは毎日新聞を読みます。","Ông tôi đọc báo mỗi ngày."]]},{"word":"おばあさん","reading":"おばあさん","meaning":"bà (nội, ngoại)","hanViet":"","lesson":24,"ex":[["おばあさんは元気です。","Bà tôi khỏe mạnh."],["おばあさんは料理が上手です。","Bà tôi nấu ăn giỏi."],["おばあさんに花をあげます。","Tôi tặng hoa cho bà."],["おばあさんと買い物をします。","Tôi đi mua sắm cùng bà."],["おばあさんは田舎に住んでいます。","Bà tôi sống ở quê."]]},{"word":"準備","reading":"じゅんび","meaning":"Chuẩn bị","hanViet":"CHUẨN BỊ","lesson":24,"ex":[["旅行の準備をしました。","Tôi đã chuẩn bị cho chuyến du lịch."],["試験の準備をします。","Tôi chuẩn bị cho kỳ thi."],["昼ごはんの準備をしました。","Tôi đã chuẩn bị bữa trưa."],["パーティーの準備を手伝います。","Tôi giúp chuẩn bị bữa tiệc."],["準備が終わりました。","Việc chuẩn bị đã xong."]]},{"word":"意味","reading":"いみ","meaning":"Ý nghĩa","hanViet":"Ý VỊ","lesson":24,"ex":[["この漢字の意味がわかりません。","Tôi không hiểu ý nghĩa của chữ Hán này."],["このことばの意味は何ですか。","Từ này nghĩa là gì?"],["意味がわかりました。","Tôi đã hiểu ý nghĩa."],["先生に意味を聞きました。","Tôi đã hỏi thầy giáo ý nghĩa."],["わからないことばの意味を調べます。","Tôi tra nghĩa của từ tôi không hiểu."]]},{"word":"お菓子","reading":"おかし","meaning":"Bánh kẹo, đồ ngọt","hanViet":"QUẢ TỬ","lesson":24,"ex":[["子どもにお菓子をあげました。","Tôi đã cho trẻ con bánh kẹo."],["お菓子を食べます。","Tôi ăn bánh kẹo."],["店でお菓子を買います。","Tôi mua bánh kẹo ở cửa hàng."],["友達にお菓子をもらいました。","Tôi nhận được bánh kẹo từ bạn."],["このお菓子は甘いです。","Bánh kẹo này ngọt."]]},{"word":"全部","reading":"ぜんぶ","meaning":"Toàn bộ, tất cả","hanViet":"TOÀN BỘ","lesson":24,"ex":[["宿題を全部しました。","Tôi đã làm hết bài tập về nhà."],["ごはんを全部食べました。","Tôi đã ăn hết cơm."],["本を全部読みました。","Tôi đã đọc hết sách."],["全部で三千円です。","Tổng cộng là 3.000 yên."],["りんごを全部食べましたか。","Bạn đã ăn hết táo chưa?"]]},{"word":"自分で","reading":"じぶんで","meaning":"tự, tự mình","hanViet":"","lesson":24,"ex":[["自分で昼ごはんを作りました。","Tôi tự nấu bữa trưa."],["自分で買い物をします。","Tôi tự đi mua sắm."],["自分で掃除します。","Tôi tự dọn dẹp."],["自分で日本語を勉強します。","Tôi tự học tiếng Nhật."],["自分でケーキを作りました。","Tôi tự làm bánh."]]},{"word":"ほかに","reading":"ほかに","meaning":"ngoài ra, bên cạnh đó","hanViet":"","lesson":24,"ex":[["ほかに何かありますか。","Còn gì khác nữa không?"],["ほかにりんごがあります。","Ngoài ra còn có táo."],["ほかに友達がいます。","Ngoài ra còn có bạn."],["ほかに何を買いますか。","Bạn mua gì nữa?"],["ほかにどこへ行きますか。","Bạn đi đâu nữa?"]]},{"word":"弁当","reading":"べんとう","meaning":"cơm hộp","hanViet":"BIỆN ĐƯƠNG","lesson":24,"ex":[["昼ごはんに弁当を食べました。","Tôi đã ăn cơm hộp vào bữa trưa."],["弁当を作ります。","Tôi làm cơm hộp."],["母が弁当を作りました。","Mẹ đã làm cơm hộp."],["店で弁当を買います。","Tôi mua cơm hộp ở cửa hàng."],["弁当を会社へ持って行きます。","Tôi mang cơm hộp đến công ty."]]},{"word":"お年玉","reading":"おとしだま","meaning":"tiền lì xì","hanViet":"","lesson":24,"ex":[["子どもにお年玉をあげました。","Tôi đã lì xì cho trẻ con."],["子どもがお年玉をもらいました。","Trẻ con đã nhận được tiền lì xì."],["正月にお年玉をあげます。","Dịp Tết tôi lì xì."],["お年玉はいくらですか。","Tiền lì xì bao nhiêu?"],["おじいさんがお年玉をくれました。","Ông đã lì xì cho tôi."]]},{"word":"入学祝い","reading":"にゅうがくいわい","meaning":"quà mừng nhập học","hanViet":"","lesson":24,"ex":[["弟に入学祝いをあげました。","Tôi đã tặng em trai quà mừng nhập học."],["妹に入学祝いをあげました。","Tôi đã tặng em gái quà mừng nhập học."],["入学祝いに本をもらいました。","Tôi đã nhận được sách làm quà mừng nhập học."],["入学祝いを買います。","Tôi mua quà mừng nhập học."],["友達に入学祝いをあげます。","Tôi tặng bạn quà mừng nhập học."]]},{"word":"卒業祝い","reading":"そつぎょういわい","meaning":"quà mừng tốt nghiệp","hanViet":"","lesson":24,"ex":[["友達に卒業祝いをあげました。","Tôi đã tặng bạn quà mừng tốt nghiệp."],["弟に卒業祝いをあげました。","Tôi đã tặng em trai quà mừng tốt nghiệp."],["卒業祝いに花をもらいました。","Tôi đã nhận được hoa làm quà mừng tốt nghiệp."],["卒業祝いを買います。","Tôi mua quà mừng tốt nghiệp."],["先生に卒業祝いをあげます。","Tôi tặng thầy giáo quà mừng tốt nghiệp."]]},{"word":"結婚祝い","reading":"けっこんいわい","meaning":"Quà mừng cưới","hanViet":"KẾT HÔN CHÚC","lesson":24,"ex":[["田中さんに結婚祝いをあげました。","Tôi đã tặng anh Tanaka quà mừng cưới."],["友達に結婚祝いをあげました。","Tôi đã tặng bạn quà mừng cưới."],["結婚祝いに食器をもらいました。","Tôi đã nhận được bát đĩa làm quà mừng cưới."],["結婚祝いを買います。","Tôi mua quà mừng cưới."],["妹に結婚祝いをあげます。","Tôi tặng em gái quà mừng cưới."]]},{"word":"出産祝い","reading":"しゅっさんいわい","meaning":"quà mừng sinh con","hanViet":"","lesson":24,"ex":[["友達に出産祝いをあげました。","Tôi đã tặng bạn quà mừng sinh con."],["妹に出産祝いをあげました。","Tôi đã tặng em gái quà mừng sinh con."],["出産祝いに赤ちゃんの服をもらいました。","Tôi đã nhận được quần áo em bé làm quà mừng sinh con."],["出産祝いを買います。","Tôi mua quà mừng sinh con."],["田中さんに出産祝いをあげます。","Tôi tặng anh Tanaka quà mừng sinh con."]]},{"word":"お中元","reading":"おちゅげん","meaning":"quà biếu giữa năm","hanViet":"TRUNG NGUYÊN","lesson":24,"ex":[["先生にお中元を送りました。","Tôi đã gửi quà biếu giữa năm cho thầy giáo."],["母にお中元を送ります。","Tôi gửi quà biếu giữa năm cho mẹ."],["お中元をもらいました。","Tôi đã nhận được quà biếu giữa năm."],["お中元を買います。","Tôi mua quà biếu giữa năm."],["田中さんにお中元を送りました。","Tôi đã gửi quà biếu giữa năm cho anh Tanaka."]]},{"word":"お香典","reading":"おこうでん","meaning":"tiền phúng viếng","hanViet":"","lesson":24,"ex":[["お香典を持って行きました。","Tôi đã mang tiền phúng viếng đi."],["お香典はいくらですか。","Tiền phúng viếng bao nhiêu?"],["お香典を持っています。","Tôi đang mang theo tiền phúng viếng."],["お香典を封筒に入れます。","Tôi bỏ tiền phúng viếng vào phong bì."],["お香典を準備しました。","Tôi đã chuẩn bị tiền phúng viếng."]]},{"word":"お見舞い","reading":"おみまい","meaning":"quà thăm người ốm","hanViet":"","lesson":24,"ex":[["友達にお見舞いを持って行きました。","Tôi đã mang quà thăm người ốm đến cho bạn."],["友達にお見舞いをあげました。","Tôi đã tặng bạn quà thăm người ốm."],["病院へお見舞いを持って行きます。","Tôi mang quà thăm người ốm đến bệnh viện."],["お見舞いに花を買います。","Tôi mua hoa làm quà thăm người ốm."],["先生にお見舞いを持って行きました。","Tôi đã mang quà thăm người ốm đến cho thầy giáo."]]},{"word":"ワゴン車","reading":"ワゴンしゃ","meaning":"xe ô tô có thùng đóng kín","hanViet":"","lesson":24,"ex":[["ワゴン車で旅行に行きました。","Tôi đã đi du lịch bằng xe wagon."],["ワゴン車は大きいです。","Xe wagon to."],["ワゴン車で買い物に行きます。","Tôi đi mua sắm bằng xe wagon."],["ワゴン車を運転します。","Tôi lái xe wagon."],["ワゴン車に荷物を入れます。","Tôi cho hành lý vào xe wagon."]]},{"word":"ホームステイ","reading":"ホームステイ","meaning":"homestay","hanViet":"","lesson":24,"ex":[["日本でホームステイをしました。","Tôi đã ở homestay ở Nhật Bản."],["アメリカでホームステイをしました。","Tôi đã ở homestay ở Mỹ."],["ホームステイは楽しいです。","Ở homestay vui."],["来年、ホームステイをします。","Năm sau tôi sẽ ở homestay."],["ホームステイで日本語を勉強します。","Tôi học tiếng Nhật khi ở homestay."]]},{"word":"母の日","reading":"ははのひ","meaning":"Ngày của mẹ","hanViet":"MẪU NHẬT","lesson":24,"ex":[["母の日に花をあげました。","Vào Ngày của Mẹ, tôi đã tặng mẹ hoa."],["母の日にケーキを買います。","Vào Ngày của Mẹ tôi mua bánh."],["母の日は五月です。","Ngày của Mẹ vào tháng năm."],["母の日に母とごはんを食べます。","Vào Ngày của Mẹ tôi ăn cơm cùng mẹ."],["母の日に手紙を書きます。","Vào Ngày của Mẹ tôi viết thư."]]},{"word":"考えます","reading":"かんがえます","meaning":"suy nghĩ","hanViet":"","lesson":25,"ex":[["旅行のことを考えます。","Tôi suy nghĩ về chuyến du lịch."],["仕事のことを考えます。","Tôi suy nghĩ về công việc."],["母のことを考えます。","Tôi nghĩ về mẹ."],["よく考えます。","Tôi suy nghĩ kỹ."],["田中さんは何を考えますか。","Anh Tanaka đang nghĩ gì?"]]},{"word":"着きます","reading":"つきます","meaning":"đến (ga)","hanViet":"","lesson":25,"ex":[["電車は3時に駅に着きます。","Tàu điện đến ga lúc 3 giờ."],["飛行機は10時に空港に着きます。","Máy bay đến sân bay lúc 10 giờ."],["バスは駅に着きました。","Xe buýt đã đến ga."],["あした、国に着きます。","Ngày mai tôi về đến nước."],["電車はもう着きましたか。","Tàu điện đã đến chưa?"]]},{"word":"留学します","reading":"りゅうがくします","meaning":"du học","hanViet":"","lesson":25,"ex":[["来年、日本へ留学します。","Năm sau, tôi sẽ đi du học Nhật Bản."],["日本で留学します。","Tôi du học ở Nhật Bản."],["アメリカへ留学しました。","Tôi đã đi du học Mỹ."],["留学して、日本語を勉強します。","Tôi du học rồi học tiếng Nhật."],["友達は来年留学します。","Bạn tôi sẽ du học vào năm sau."]]},{"word":"田舎","reading":"いなか","meaning":"nông thôn, quê","hanViet":"ĐIỀN XÁ","lesson":25,"ex":[["わたしの田舎は小さい町です。","Quê tôi là một thị trấn nhỏ."],["田舎に両親が住んでいます。","Ở quê có bố mẹ tôi sống."],["田舎は静かです。","Quê yên tĩnh."],["田舎へ帰ります。","Tôi về quê."],["田舎に大きい川があります。","Ở quê có con sông lớn."]]},{"word":"億","reading":"おく","meaning":"Một trăm triệu","hanViet":"ỨC","lesson":25,"ex":[["日本には1億人います。","Ở Nhật Bản có 100 triệu người."],["中国には10億人います。","Ở Trung Quốc có 1 tỷ người."],["この車は1億円です。","Chiếc xe này 100 triệu yên."],["会社は1億円で建物を買いました。","Công ty đã mua tòa nhà với giá 100 triệu yên."],["世界には70億人います。","Trên thế giới có 7 tỷ người."]]},{"word":"もし～たら","reading":"もし～たら","meaning":"nếu ~ thì","hanViet":"","lesson":25,"ex":[["もし雨が降ったら、うちにいます。","Nếu trời mưa thì tôi ở nhà."],["もしお金があったら、車を買います。","Nếu có tiền thì tôi mua xe."],["もし時間があったら、映画を見ます。","Nếu có thời gian thì tôi xem phim."],["もしお金がなかったら、買い物をしません。","Nếu không có tiền thì tôi không mua sắm."],["もし田中さんに会ったら、話します。","Nếu gặp anh Tanaka thì tôi nói chuyện."]]},{"word":"いくら～ても","reading":"いくら「～でも」","meaning":"cho dù ~","hanViet":"","lesson":25,"ex":[["いくら勉強しても、日本語は難しいです。","Dù học bao nhiêu, tiếng Nhật vẫn khó."],["いくら食べても、まだ食べたいです。","Dù ăn bao nhiêu tôi vẫn muốn ăn."],["いくら練習しても、漢字は難しいです。","Dù luyện tập bao nhiêu, chữ Hán vẫn khó."],["いくら聞いても、わかりません。","Dù nghe bao nhiêu tôi vẫn không hiểu."],["いくら寝ても、疲れます。","Dù ngủ bao nhiêu tôi vẫn mệt."]]},{"word":"転勤","reading":"てんきん","meaning":"việc chuyển công tác","hanViet":"","lesson":25,"ex":[["田中さんの転勤は来月です。","Việc chuyển công tác của anh Tanaka vào tháng sau."],["田中さんは転勤します。","Anh Tanaka chuyển công tác."],["転勤で国へ帰ります。","Tôi về nước do chuyển công tác."],["社長は転勤しました。","Giám đốc đã chuyển công tác."],["転勤は大変です。","Chuyển công tác vất vả."]]},{"word":"赤ちゃん","reading":"あかちゃん","meaning":"Em bé sơ sinh","hanViet":"XÍCH NHI","lesson":25,"ex":[["赤ちゃんは小さいです。","Em bé sơ sinh nhỏ."],["赤ちゃんは元気です。","Em bé khỏe mạnh."],["赤ちゃんが生まれました。","Em bé đã sinh ra."],["赤ちゃんにミルクをあげます。","Tôi cho em bé uống sữa."],["赤ちゃんは寝ています。","Em bé đang ngủ."]]},{"word":"保育園","reading":"ほいくえん","meaning":"Nhà trẻ, trường mầm non","hanViet":"BẢO DỤC VIÊN","lesson":25,"ex":[["わたしの子どもは保育園へ行きます。","Con tôi đi nhà trẻ."],["子どもは保育園で遊びます。","Trẻ con chơi ở nhà trẻ."],["保育園の前に公園があります。","Trước nhà trẻ có công viên."],["保育園は駅の近くにあります。","Nhà trẻ ở gần ga."],["子どもを保育園へ連れて行きます。","Tôi dẫn trẻ con đến nhà trẻ."]]},{"word":"学校に入ります","reading":"がっこうにはいります","meaning":"nhập học","hanViet":"HỌC HIỆU NHẬP","lesson":25,"ex":[["わたしの子どもは学校に入ります。","Con tôi nhập học."],["弟は来年学校に入ります。","Em trai tôi nhập học vào năm sau."],["わたしは4月に学校に入ります。","Tôi nhập học vào tháng tư."],["友達の子どもは学校に入りました。","Con của bạn tôi đã nhập học."],["子どもは小学校に入ります。","Trẻ con nhập học tiểu học."]]},{"word":"大学院","reading":"だいがくいん","meaning":"Cao học, sau đại học","hanViet":"ĐẠI HỌC VIỆN","lesson":25,"ex":[["わたしは大学院で勉強します。","Tôi học ở cao học."],["大学院へ行きます。","Tôi đi học cao học."],["田中さんは大学院で研究します。","Anh Tanaka nghiên cứu ở cao học."],["大学院は大学の近くにあります。","Cao học ở gần trường đại học."],["大学院に入ります。","Tôi vào học cao học."]]},{"word":"学校を出ます","reading":"がっこうをでます","meaning":"tốt nghiệp, ra trường","hanViet":"HỌC HIỆU XUẤT","lesson":25,"ex":[["わたしは来年学校を出ます。","Năm sau, tôi sẽ tốt nghiệp."],["友達は今年学校を出ます。","Bạn tôi tốt nghiệp năm nay."],["学校を出て、会社で働きます。","Tôi tốt nghiệp rồi làm việc ở công ty."],["学校を出て、留学します。","Tôi tốt nghiệp rồi đi du học."],["弟は来月学校を出ます。","Em trai tôi tốt nghiệp vào tháng sau."]]},{"word":"就職します","reading":"しゅうしょくします","meaning":"xin việc, đi làm","hanViet":"","lesson":25,"ex":[["大学を出て、就職します。","Tôi tốt nghiệp đại học rồi đi làm."],["来年、就職します。","Năm sau tôi sẽ đi làm."],["友達は会社に就職しました。","Bạn tôi đã xin việc vào công ty."],["日本で就職します。","Tôi xin việc ở Nhật Bản."],["大学を出てから、就職します。","Sau khi tốt nghiệp đại học tôi sẽ đi làm."]]},{"word":"子どもが生まれます","reading":"こどもがうまれます","meaning":"sinh con","hanViet":"TỬ SINH","lesson":25,"ex":[["来年、わたしの子どもが生まれます。","Năm sau, con tôi sẽ sinh ra."],["田中さんの子どもが生まれました。","Con của anh Tanaka đã sinh ra."],["来月、子どもが生まれます。","Tháng sau con tôi sẽ sinh ra."],["春に子どもが生まれます。","Con tôi sẽ sinh ra vào mùa xuân."],["子どもが生まれましたから、忙しいです。","Vì con đã sinh ra nên tôi bận."]]},{"word":"離婚します","reading":"りこんします","meaning":"ly hôn","hanViet":"","lesson":25,"ex":[["田中さんは離婚しました。","Anh Tanaka đã ly hôn."],["田中さんは去年離婚しました。","Anh Tanaka đã ly hôn năm ngoái."],["田中さんの両親は離婚しました。","Bố mẹ của anh Tanaka đã ly hôn."],["離婚して、国へ帰りました。","Tôi đã ly hôn rồi về nước."],["離婚して、仕事をやめました。","Tôi đã ly hôn rồi nghỉ việc."]]},{"word":"再婚します","reading":"さいこんします","meaning":"tái hôn","hanViet":"","lesson":25,"ex":[["田中さんは再婚しました。","Anh Tanaka đã tái hôn."],["田中さんは来年再婚します。","Anh Tanaka sẽ tái hôn vào năm sau."],["田中さんは再婚して、国へ帰りました。","Anh Tanaka đã tái hôn rồi về nước."],["田中さんのお父さんは再婚しました。","Bố của anh Tanaka đã tái hôn."],["再婚して、子どもが生まれました。","Tôi đã tái hôn rồi con đã sinh ra."]]},{"word":"仕事をやめます","reading":"しごとをやめます","meaning":"nghỉ việc","hanViet":"","lesson":25,"ex":[["来年、仕事をやめます。","Năm sau, tôi sẽ nghỉ việc."],["田中さんは仕事をやめました。","Anh Tanaka đã nghỉ việc."],["仕事をやめて、国へ帰ります。","Tôi nghỉ việc rồi về nước."],["仕事をやめて、留学します。","Tôi nghỉ việc rồi đi du học."],["仕事をやめますか。","Bạn có nghỉ việc không?"]]},{"word":"死にます","reading":"しにます","meaning":"chết","hanViet":"","lesson":25,"ex":[["犬が死にました。","Con chó đã chết."],["猫が死にました。","Con mèo đã chết."],["おじいさんは去年死にました。","Ông tôi đã mất năm ngoái."],["犬は病気で死にました。","Con chó đã chết vì bệnh."],["魚が死にました。","Con cá đã chết."]]},{"word":"グループ","reading":"グループ","meaning":"nhóm","hanViet":"","lesson":25,"ex":[["わたしはグループで勉強します。","Tôi học theo nhóm."],["グループで旅行に行きます。","Tôi đi du lịch theo nhóm."],["グループで仕事をします。","Tôi làm việc theo nhóm."],["このグループは大きいです。","Nhóm này lớn."],["グループに友達がいます。","Trong nhóm có bạn."]]},{"word":"チャンス","reading":"チャンス","meaning":"cơ hội","hanViet":"","lesson":25,"ex":[["これはいいチャンスです。","Đây là một cơ hội tốt."],["いいチャンスをもらいました。","Tôi đã nhận được cơ hội tốt."],["チャンスがあります。","Có cơ hội."],["これは大きいチャンスです。","Đây là cơ hội lớn."],["日本語を勉強するチャンスがあります。","Tôi có cơ hội học tiếng Nhật."]]},{"word":"頑張ります","reading":"がんばります","meaning":"cố gắng lên","hanViet":"","lesson":25,"ex":[["試験で頑張ります。","Tôi sẽ cố gắng trong kỳ thi."],["日本語の勉強を頑張ります。","Tôi cố gắng học tiếng Nhật."],["仕事を頑張ります。","Tôi cố gắng làm việc."],["あした、頑張ります。","Ngày mai tôi sẽ cố gắng."],["試験で頑張ってください。","Hãy cố gắng trong kỳ thi."]]},{"word":"どうぞお元気で","reading":"どうぞおげんきで","meaning":"chúc anh/chị khỏe mạnh","hanViet":"","lesson":25,"ex":[["どうぞお元気で。","Chúc anh/chị khỏe mạnh."],["どうぞお元気で、また会いましょう。","Chúc anh/chị khỏe mạnh, hẹn gặp lại."],["先生、どうぞお元気で。","Thưa thầy, chúc thầy khỏe mạnh."],["田中さん、どうぞお元気で。","Anh Tanaka, chúc anh khỏe mạnh."],["田中さんにどうぞお元気でと言いました。","Tôi đã nói \"chúc anh khỏe mạnh\" với anh Tanaka."]]},{"word":"もしもし","reading":"もしもし","meaning":"a-lô (khi nghe điện thoại)","hanViet":"","lesson":25,"ex":[["もしもし、田中さんですか。","A-lô, có phải anh Tanaka không?"],["もしもし、山田さんですか。","A-lô, có phải anh Yamada không?"],["もしもし、私は田中です。","A-lô, tôi là Tanaka."],["電話で、もしもしと言います。","Khi nghe điện thoại, tôi nói \"a-lô\"."],["もしもし、田中さん、いますか。","A-lô, anh Tanaka có ở đó không?"]]},{"word":"色々お世話になりました","reading":"いろいろおせわになりました","meaning":"cảm ơn anh/chị đã giúp đỡ tôi nhiều","hanViet":"","lesson":25,"ex":[["色々お世話になりました。","Cảm ơn anh/chị đã giúp đỡ tôi nhiều."],["先生、色々お世話になりました。","Thưa thầy, cảm ơn thầy đã giúp đỡ tôi nhiều."],["田中さん、色々お世話になりました。","Anh Tanaka, cảm ơn anh đã giúp đỡ tôi nhiều."],["日本で色々お世話になりました。","Ở Nhật Bản, cảm ơn anh/chị đã giúp đỡ tôi nhiều."],["会社で色々お世話になりました。","Ở công ty, cảm ơn anh/chị đã giúp đỡ tôi nhiều."]]},{"word":"一杯飲みましょう","reading":"いっぱいのみましょう","meaning":"cùng uống một chén nhá","hanViet":"","lesson":25,"ex":[["ビールを一杯飲みましょう。","Cùng uống một cốc bia nhé."],["ワインを一杯飲みましょう。","Cùng uống một ly rượu vang nhé."],["お茶を一杯飲みましょう。","Cùng uống một chén trà nhé."],["コーヒーを一杯飲みましょう。","Cùng uống một cốc cà phê nhé."],["ジュースを一杯飲みましょう。","Cùng uống một cốc nước trái cây nhé."]]}],"N4":[{"word":"見ます","reading":"みます","meaning":"Nhìn, xem","hanViet":"KIẾN","lesson":26,"ex":[["毎晩、テレビを見ます。","Mỗi tối tôi xem ti vi."],["きのう、友達と映画を見ました。","Hôm qua tôi đã xem phim cùng bạn."],["窓から海を見ます。","Tôi nhìn biển từ cửa sổ."],["先生は私の宿題を見ます。","Thầy giáo xem bài tập về nhà của tôi."],["母は古い写真を見ます。","Mẹ tôi xem những tấm ảnh cũ."]]},{"word":"探します","reading":"さがします","meaning":"Tìm kiếm","hanViet":"THÁM","lesson":26,"ex":[["かばんの中で鍵を探します。","Tôi tìm chìa khóa trong cặp."],["母は台所で眼鏡を探しています。","Mẹ đang tìm kính trong bếp."],["きのう、公園で財布を探しました。","Hôm qua tôi đã tìm ví ở công viên."],["図書館で新しい本を探します。","Tôi tìm cuốn sách mới ở thư viện."],["山田さんは新しい仕事を探しています。","Anh Yamada đang tìm việc mới."]]},{"word":"捜します","reading":"さがします","meaning":"Tìm, tìm kiếm","hanViet":"SƯU","lesson":26,"ex":[["警察は山で子どもを捜しています。","Cảnh sát đang tìm đứa trẻ trên núi."],["警察は海で船を捜しています。","Cảnh sát đang tìm con tàu trên biển."],["警察は町で車を捜しています。","Cảnh sát đang tìm chiếc xe trong thành phố."],["警察は公園で財布を捜しています。","Cảnh sát đang tìm ví ở công viên."],["父は引き出しの中で古い手紙を捜しています。","Bố đang tìm những lá thư cũ trong ngăn kéo."]]},{"word":"遅れます","reading":"おくれます","meaning":"Bị trễ, chậm trễ","hanViet":"TRÌ","lesson":26,"ex":[["電車が遅れて、学校に遅れました。","Tàu điện trễ nên tôi đến trường muộn."],["バスが遅れて、会社に遅れます。","Xe buýt trễ nên tôi sẽ đến công ty muộn."],["会議に遅れないでください。","Xin đừng đến muộn buổi họp."],["あしたの飛行機に遅れないように、7時に出ます。","Để không trễ chuyến bay ngày mai, tôi sẽ đi lúc 7 giờ."],["山田さんはよく授業に遅れます。","Anh Yamada thường xuyên đến lớp muộn."]]},{"word":"間に合います","reading":"まにあいます","meaning":"kịp giờ","hanViet":"GIAN HỢP","lesson":26,"ex":[["急げば、電車に間に合います。","Nếu vội thì sẽ kịp tàu điện."],["7時の電車に間に合いました。","Tôi đã kịp chuyến tàu điện lúc 7 giờ."],["あと5分で授業に間に合いますか。","Còn 5 phút nữa thì có kịp giờ học không?"],["バスに間に合わなくて、タクシーに乗りました。","Vì không kịp xe buýt nên tôi đã đi taxi."],["急いでください。飛行機に間に合いませんよ。","Hãy nhanh lên. Bạn sẽ không kịp máy bay đâu."]]},{"word":"やります","reading":"やります","meaning":"làm","hanViet":"","lesson":26,"ex":[["毎晩、宿題をやります。","Mỗi tối tôi làm bài tập về nhà."],["きのう、日本語の宿題をやりました。","Hôm qua tôi đã làm bài tập tiếng Nhật."],["あしたまでに宿題をやらなければなりません。","Tôi phải làm xong bài tập về nhà trước ngày mai."],["山田さんは仕事を速くやります。","Anh Yamada làm việc nhanh."],["弟は部屋で宿題をやっています。","Em trai đang làm bài tập trong phòng."]]},{"word":"参加します","reading":"さんかします","meaning":"tham gia, dự [buổi tiệc]","hanViet":"THAM GIA","lesson":26,"ex":[["あしたのパーティーに参加します。","Tôi sẽ tham gia buổi tiệc ngày mai."],["運動会に参加しました。","Tôi đã tham gia hội thi thể thao."],["山田さんは会議に参加しませんでした。","Anh Yamada đã không tham gia buổi họp."],["だれでもこのボランティアに参加できます。","Ai cũng có thể tham gia hoạt động tình nguyện này."],["来週、クラスの旅行に参加します。","Tuần tới tôi sẽ tham gia chuyến du lịch của lớp."]]},{"word":"申し込みます","reading":"もうしこみます","meaning":"Đăng ký, nộp đơn xin","hanViet":"THÂN","lesson":26,"ex":[["日本語の試験に申し込みました。","Tôi đã đăng ký thi tiếng Nhật."],["旅行に申し込みます。","Tôi đăng ký đi du lịch."],["図書館のカードを申し込みました。","Tôi đã đăng ký thẻ thư viện."],["あしたまでに試合に申し込んでください。","Hãy đăng ký trận đấu trước ngày mai."],["山田さんは大学に申し込みました。","Anh Yamada đã nộp đơn vào đại học."]]},{"word":"都合がいい","reading":"つごうがいい","meaning":"có thời gian, thuận tiện","hanViet":"ĐÔ HỢP","lesson":26,"ex":[["あしたの午後は都合がいいです。","Chiều mai tôi rảnh."],["日曜日は都合がいいです。","Chủ nhật tôi rảnh."],["何時が都合がいいですか。","Mấy giờ thì tiện cho bạn?"],["金曜日の午前は都合がいいです。","Sáng thứ sáu tôi rảnh."],["来週の月曜日は都合がいいですか。","Thứ hai tuần tới bạn có rảnh không?"]]},{"word":"都合が悪い","reading":"つごうがわるい","meaning":"không có thời gian, bận, không thuận tiện","hanViet":"ĐÔ HỢP ÁC","lesson":26,"ex":[["きょうは都合が悪いです。","Hôm nay tôi bận."],["あしたの午前は都合が悪いです。","Sáng mai tôi bận."],["月曜日は都合が悪いです。","Thứ hai tôi bận."],["今週は都合が悪いから、来週にしましょう。","Tuần này tôi bận nên để tuần sau nhé."],["山田さんは金曜日は都合が悪いです。","Anh Yamada bận vào thứ sáu."]]},{"word":"気分がいい","reading":"きぶんがいい","meaning":"tâm trạng,thể trạng tốt","hanViet":"KHÍ PHÂN","lesson":26,"ex":[["きょうは天気がよくて、気分がいいです。","Hôm nay trời đẹp nên tâm trạng tôi tốt."],["運動したあとは気分がいいです。","Sau khi vận động, tôi cảm thấy dễ chịu."],["海を見ると、気分がいいです。","Nhìn biển, tôi cảm thấy dễ chịu."],["朝、散歩すると、気分がいいです。","Đi dạo buổi sáng, tôi cảm thấy sảng khoái."],["音楽を聞くと、気分がいいです。","Nghe nhạc, tôi cảm thấy dễ chịu."]]},{"word":"気分が悪い","reading":"きぶんがわるい","meaning":"tâm trạng,thể trạng xấu","hanViet":"KHÍ PHÂN ÁC","lesson":26,"ex":[["きょうは頭が痛くて、気分が悪いです。","Hôm nay tôi đau đầu nên cảm thấy khó chịu."],["船に乗ると、気分が悪いです。","Đi tàu, tôi cảm thấy khó chịu."],["あまり食べすぎて、気分が悪いです。","Ăn quá nhiều nên tôi cảm thấy khó chịu."],["雨の日は気分が悪いです。","Những ngày mưa, tâm trạng tôi không tốt."],["山田さんはきょう、気分が悪いです。","Hôm nay anh Yamada cảm thấy không khỏe."]]},{"word":"新聞社","reading":"しんぶんしゃ","meaning":"công ty phát hành báo, tòa soạn báo","hanViet":"TÂN VĂN XÃ","lesson":26,"ex":[["父は新聞社で働いています。","Bố tôi làm việc ở tòa soạn báo."],["新聞社は駅の近くにあります。","Tòa soạn báo ở gần ga."],["山田さんは新聞社の人です。","Anh Yamada là người làm ở tòa soạn báo."],["新聞社に電話をしました。","Tôi đã gọi điện đến tòa soạn báo."],["あの新聞社は有名です。","Tòa soạn báo đó nổi tiếng."]]},{"word":"柔道","reading":"じゅうどう","meaning":"Môn Judo","hanViet":"NHU ĐẠO","lesson":26,"ex":[["私は柔道を習っています。","Tôi đang học judo."],["弟は柔道が上手です。","Em trai tôi giỏi judo."],["学校で柔道をします。","Tôi tập judo ở trường."],["柔道は日本のスポーツです。","Judo là môn thể thao của Nhật Bản."],["山田さんは柔道の先生です。","Anh Yamada là thầy dạy judo."]]},{"word":"運動会","reading":"うんどうかい","meaning":"hội thi thể thao","hanViet":"VẬN ĐỘNG HỘI","lesson":26,"ex":[["あした、学校で運動会があります。","Ngày mai ở trường có hội thi thể thao."],["運動会で走りました。","Tôi đã chạy ở hội thi thể thao."],["子どもたちは運動会が好きです。","Các con thích hội thi thể thao."],["きのうの運動会は楽しかったです。","Hội thi thể thao hôm qua rất vui."],["運動会の写真を撮りました。","Tôi đã chụp ảnh ở hội thi thể thao."]]},{"word":"場所","reading":"ばしょ","meaning":"Địa điểm, nơi chốn","hanViet":"TRƯỜNG SỞ","lesson":26,"ex":[["会議の場所はどこですか。","Địa điểm buổi họp ở đâu?"],["この場所は静かです。","Nơi này yên tĩnh."],["運動会の場所は学校です。","Địa điểm hội thi thể thao là trường học."],["パーティーの場所を教えてください。","Hãy cho tôi biết địa điểm buổi tiệc."],["車を止める場所がありません。","Không có chỗ đỗ xe."]]},{"word":"～弁","reading":"～べん","meaning":"tiếng ~, giọng ~","hanViet":"BIỆN","lesson":26,"ex":[["京都弁は有名です。","Giọng Kyoto nổi tiếng."],["京都弁が好きです。","Tôi thích giọng Kyoto."],["京都弁がわかりません。","Tôi không hiểu giọng Kyoto."],["山田さんは京都弁を使います。","Anh Yamada dùng giọng Kyoto."],["東京弁と京都弁は違います。","Giọng Tokyo và giọng Kyoto khác nhau."]]},{"word":"今度","reading":"こんど","meaning":"Lần này; lần tới","hanViet":"KIM ĐỘ","lesson":26,"ex":[["今度、東京へ行きます。","Lần tới tôi sẽ đi Tokyo."],["今度のパーティーに参加します。","Tôi sẽ tham gia buổi tiệc lần tới."],["今度の日曜日に海へ行きます。","Chủ nhật tới tôi sẽ đi biển."],["今度は遅れないようにします。","Lần này tôi sẽ cố không đến muộn."],["今度の試験は難しいです。","Kỳ thi lần này khó."]]},{"word":"ずいぶん","reading":"ずいぶん","meaning":"khá ,tương đối","hanViet":"","lesson":26,"ex":[["きょうはずいぶん寒いです。","Hôm nay khá lạnh."],["日本語がずいぶん上手になりました。","Tiếng Nhật của tôi đã khá giỏi lên."],["この映画はずいぶん楽しいです。","Bộ phim này khá thú vị."],["きのうはずいぶん疲れました。","Hôm qua tôi khá mệt."],["田中さんはずいぶん元気になりました。","Anh Tanaka đã khỏe lên nhiều."]]},{"word":"直接","reading":"ちょくせつ","meaning":"Trực tiếp","hanViet":"TRỰC TIẾP","lesson":26,"ex":[["先生に直接聞いてください。","Hãy hỏi trực tiếp thầy giáo."],["会社に直接電話をしました。","Tôi đã gọi điện trực tiếp đến công ty."],["直接会って話したいです。","Tôi muốn gặp trực tiếp để nói chuyện."],["山田さんに直接渡してください。","Hãy đưa trực tiếp cho anh Yamada."],["直接、学校へ行きます。","Tôi sẽ đến trường trực tiếp."]]},{"word":"いつでも","reading":"いつでも","meaning":"lúc nào cũng","hanViet":"","lesson":26,"ex":[["いつでも電話してください。","Lúc nào cũng có thể gọi điện cho tôi."],["図書館はいつでも開いています。","Thư viện lúc nào cũng mở cửa."],["いつでも遊びに来てください。","Lúc nào cũng có thể đến chơi."],["この店はいつでも人が多いです。","Cửa hàng này lúc nào cũng đông người."],["いつでも手伝います。","Lúc nào tôi cũng sẽ giúp."]]},{"word":"どこでも","reading":"どこでも","meaning":"ở đâu cũng","hanViet":"","lesson":26,"ex":[["どこでも日本語を勉強できます。","Ở đâu cũng có thể học tiếng Nhật."],["この本はどこでも買えます。","Cuốn sách này ở đâu cũng mua được."],["どこでも寝ることができます。","Ở đâu tôi cũng có thể ngủ được."],["この辞書はどこでも使えます。","Cuốn từ điển này ở đâu cũng dùng được."],["子どもはどこでも遊びます。","Trẻ con chơi ở đâu cũng được."]]},{"word":"だれでも","reading":"だれでも","meaning":"ai cũng","hanViet":"","lesson":26,"ex":[["だれでも参加できます。","Ai cũng có thể tham gia."],["この問題はだれでもわかります。","Bài toán này ai cũng hiểu."],["だれでもこの本を読めます。","Ai cũng có thể đọc cuốn sách này."],["だれでも歌えます。","Ai cũng có thể hát."],["この料理はだれでも作れます。","Món ăn này ai cũng có thể làm được."]]},{"word":"何でも","reading":"なんでも","meaning":"cái gì cũng","hanViet":"HÀ","lesson":26,"ex":[["何でも食べます。","Cái gì tôi cũng ăn."],["何でも聞いてください。","Cái gì cũng có thể hỏi."],["山田さんは何でも知っています。","Anh Yamada cái gì cũng biết."],["何でも買えます。","Cái gì cũng mua được."],["この店では何でも売っています。","Cửa hàng này cái gì cũng bán."]]},{"word":"片付きます","reading":"かたづきます","meaning":"được dọn dẹp, gọn gàng","hanViet":"PHIẾN PHÓ","lesson":26,"ex":[["部屋が片付きました。","Phòng đã được dọn dẹp."],["机の上が片付きました。","Trên bàn đã gọn gàng."],["きのう、仕事が片付きました。","Hôm qua công việc đã xong."],["台所が片付いていません。","Bếp vẫn chưa được dọn dẹp."],["部屋が片付くと、気分がいいです。","Phòng gọn gàng thì tôi cảm thấy dễ chịu."]]},{"word":"ごみ","reading":"ごみ","meaning":"rác","hanViet":"","lesson":26,"ex":[["ごみを出します。","Tôi đổ rác."],["ごみはここに置いてください。","Hãy để rác ở đây."],["ごみを捨てました。","Tôi đã vứt rác."],["ごみが多いです。","Rác nhiều."],["ごみを出す日は月曜日です。","Ngày đổ rác là thứ hai."]]},{"word":"燃えます","reading":"もえます","meaning":"Cháy, bốc cháy","hanViet":"NHIÊN","lesson":26,"ex":[["紙はよく燃えます。","Giấy dễ cháy."],["木が燃えています。","Cây đang cháy."],["このごみは燃えますか。","Rác này có cháy được không?"],["紙くずが燃えました。","Giấy vụn đã cháy."],["木が燃えて、火が大きくなりました。","Cây cháy nên lửa to lên."]]},{"word":"置き場","reading":"おきば","meaning":"chỗ để,chỗ đặt","hanViet":"TRÍ TRƯỜNG","lesson":26,"ex":[["自転車の置き場はここです。","Chỗ để xe đạp ở đây."],["ごみの置き場はどこですか。","Chỗ để rác ở đâu?"],["車の置き場がありません。","Không có chỗ để xe."],["傘の置き場は玄関です。","Chỗ để ô ở lối vào."],["かばんの置き場を教えてください。","Hãy cho tôi biết chỗ để cặp."]]},{"word":"横","reading":"よこ","meaning":"ngang, phía bên","hanViet":"HOÀNH","lesson":26,"ex":[["机の横にいすがあります。","Bên cạnh bàn có ghế."],["学校の横に公園があります。","Bên cạnh trường học có công viên."],["私の横に山田さんがいます。","Bên cạnh tôi có anh Yamada."],["テレビの横に本があります。","Bên cạnh ti vi có sách."],["横に座ってください。","Hãy ngồi bên cạnh."]]},{"word":"瓶","reading":"びん","meaning":"Chai, lọ","hanViet":"BÌNH","lesson":26,"ex":[["瓶に水を入れます。","Tôi đổ nước vào chai."],["瓶が割れました。","Cái chai đã vỡ."],["この瓶は大きいです。","Cái chai này to."],["瓶を捨てました。","Tôi đã vứt chai."],["瓶に花を入れました。","Tôi đã cắm hoa vào lọ."]]},{"word":"缶","reading":"かん","meaning":"Lon, hộp thiếc","hanViet":"PHẪU","lesson":26,"ex":[["缶ジュースを買いました。","Tôi đã mua nước trái cây lon."],["缶を捨てました。","Tôi đã vứt lon."],["缶ビールを飲みました。","Tôi đã uống bia lon."],["缶はここに置いてください。","Hãy để lon ở đây."],["缶コーヒーを買いました。","Tôi đã mua cà phê lon."]]},{"word":"湯","reading":"ゆ","meaning":"Nước nóng","hanViet":"THANG","lesson":26,"ex":[["お風呂の湯が熱いです。","Nước trong bồn tắm nóng."],["湯を沸かします。","Tôi đun nước nóng."],["湯で手を洗います。","Tôi rửa tay bằng nước nóng."],["お風呂の湯が冷たいです。","Nước trong bồn tắm lạnh."],["コーヒーに湯を入れます。","Tôi đổ nước nóng vào cà phê."]]},{"word":"連絡します","reading":"れんらくします","meaning":"liên lạc","hanViet":"LIÊN LẠC","lesson":26,"ex":[["あした、先生に連絡します。","Ngày mai tôi sẽ liên lạc với thầy giáo."],["電話で会社に連絡しました。","Tôi đã liên lạc với công ty bằng điện thoại."],["母に連絡してください。","Hãy liên lạc với mẹ."],["学校に連絡しました。","Tôi đã liên lạc với trường học."],["遅れるときは、連絡してください。","Khi đến muộn, hãy liên lạc nhé."]]},{"word":"困ったなあ。","reading":"こまったなあ","meaning":"Làm thế nào đây!/ căng quá nhỉ!/ gay quá!","hanViet":"KHỐN","lesson":26,"ex":[["財布がない。困ったなあ。","Không có ví. Gay quá."],["電車が遅れた。困ったなあ。","Tàu điện trễ. Làm thế nào đây?"],["宿題が終わらない。困ったなあ。","Bài tập về nhà làm mãi không xong. Gay quá."],["傘を忘れた。困ったなあ。","Tôi quên ô rồi. Làm thế nào đây?"],["鍵がない。困ったなあ。","Không có chìa khóa. Gay quá."]]},{"word":"宇宙","reading":"うちゅう","meaning":"Vũ trụ","hanViet":"VŨ TRỤ","lesson":26,"ex":[["宇宙は広いです。","Vũ trụ rộng lớn."],["宇宙について勉強します。","Tôi học về vũ trụ."],["宇宙には星がたくさんあります。","Trong vũ trụ có rất nhiều ngôi sao."],["宇宙の写真を見ました。","Tôi đã xem ảnh vũ trụ."],["宇宙へ行きたいです。","Tôi muốn đi vào vũ trụ."]]},{"word":"怖い","reading":"こわい","meaning":"đáng sợ, sợ","hanViet":"BỐ","lesson":26,"ex":[["夜の山は怖いです。","Núi vào ban đêm đáng sợ."],["私は犬が怖いです。","Tôi sợ chó."],["この映画は怖いです。","Bộ phim này đáng sợ."],["子どもは雷が怖いです。","Trẻ con sợ sấm sét."],["高い所は怖いです。","Nơi cao đáng sợ."]]},{"word":"宇宙船","reading":"うちゅうせん","meaning":"Tàu vũ trụ","hanViet":"VŨ TRỤ THUYỀN","lesson":26,"ex":[["宇宙船が空を飛びます。","Tàu vũ trụ bay trên trời."],["宇宙船に乗ってみたいです。","Tôi muốn thử đi tàu vũ trụ."],["宇宙船の写真を見ました。","Tôi đã xem ảnh tàu vũ trụ."],["宇宙船が宇宙へ行きました。","Tàu vũ trụ đã đi vào vũ trụ."],["子どもは宇宙船が好きです。","Trẻ con thích tàu vũ trụ."]]},{"word":"別の","reading":"べつの","meaning":"khác","hanViet":"BIỆT","lesson":26,"ex":[["別の本を読みたいです。","Tôi muốn đọc cuốn sách khác."],["別の日に来てください。","Hãy đến vào ngày khác."],["別の場所で会いましょう。","Hãy gặp nhau ở nơi khác."],["別の色のシャツを買いました。","Tôi đã mua áo sơ mi màu khác."],["別の電車に乗りました。","Tôi đã đi chuyến tàu điện khác."]]},{"word":"宇宙飛行士","reading":"うちゅうひこうし","meaning":"Phi hành gia","hanViet":"VŨ TRỤ PHI HÀNH SĨ","lesson":26,"ex":[["宇宙飛行士は宇宙へ行きます。","Phi hành gia đi vào vũ trụ."],["私の夢は宇宙飛行士です。","Ước mơ của tôi là phi hành gia."],["宇宙飛行士の話を聞きました。","Tôi đã nghe chuyện của phi hành gia."],["宇宙飛行士は宇宙船に乗ります。","Phi hành gia đi tàu vũ trụ."],["子どもは宇宙飛行士になりたいです。","Trẻ con muốn trở thành phi hành gia."]]},{"word":"紙くず","reading":"かみくず","meaning":"giấy vụn","hanViet":"CHỈ","lesson":26,"ex":[["机の上に紙くずがあります。","Trên bàn có giấy vụn."],["紙くずを捨てました。","Tôi đã vứt giấy vụn."],["紙くずを集めました。","Tôi đã gom giấy vụn."],["紙くずは燃えるごみです。","Giấy vụn là rác cháy được."],["部屋に紙くずが多いです。","Trong phòng có nhiều giấy vụn."]]},{"word":"生ごみ","reading":"なまごみ","meaning":"rác nhà bếp","hanViet":"SINH","lesson":26,"ex":[["生ごみは燃えるごみです。","Rác nhà bếp là rác cháy được."],["生ごみを出しました。","Tôi đã đổ rác nhà bếp."],["台所に生ごみがあります。","Trong bếp có rác nhà bếp."],["生ごみはにおいがします。","Rác nhà bếp có mùi."],["生ごみは月曜日に出します。","Rác nhà bếp thì đổ vào thứ hai."]]},{"word":"フリーマーケット","reading":"フリーマーケット","meaning":"chợ đồ cũ,chợ trời","hanViet":"","lesson":26,"ex":[["日曜日にフリーマーケットへ行きます。","Chủ nhật tôi đi chợ trời."],["フリーマーケットで古い本を買いました。","Tôi đã mua sách cũ ở chợ trời."],["フリーマーケットで服を売ります。","Tôi bán quần áo ở chợ trời."],["フリーマーケットは楽しいです。","Chợ trời rất vui."],["あした、フリーマーケットがあります。","Ngày mai có chợ trời."]]},{"word":"ボランティア","reading":"ボランティア","meaning":"việc từ thiện,tình nguyện viên","hanViet":"","lesson":26,"ex":[["ボランティアをします。","Tôi làm tình nguyện."],["山田さんはボランティアです。","Anh Yamada là tình nguyện viên."],["ボランティアに参加しました。","Tôi đã tham gia hoạt động tình nguyện."],["日曜日にボランティアをします。","Chủ nhật tôi làm tình nguyện."],["ボランティアの仕事は楽しいです。","Công việc tình nguyện rất thú vị."]]},{"word":"国会議事堂","reading":"こっかいぎじどう","meaning":"tòa nhà quốc hội","hanViet":"QUỐC HỘI NGHỊ SỰ ĐƯỜNG","lesson":26,"ex":[["国会議事堂は東京にあります。","Tòa nhà quốc hội ở Tokyo."],["国会議事堂を見ました。","Tôi đã xem tòa nhà quốc hội."],["あした、国会議事堂へ行きます。","Ngày mai tôi sẽ đến tòa nhà quốc hội."],["国会議事堂は大きいです。","Tòa nhà quốc hội rất lớn."],["国会議事堂の写真を撮りました。","Tôi đã chụp ảnh tòa nhà quốc hội."]]},{"word":"平日","reading":"へいじつ","meaning":"ngày thường","hanViet":"BÌNH NHẬT","lesson":26,"ex":[["平日は会社へ行きます。","Ngày thường tôi đi làm."],["平日は図書館が開いています。","Ngày thường thư viện mở cửa."],["平日の午前は暇です。","Sáng ngày thường tôi rảnh."],["平日に図書館へ行きます。","Ngày thường tôi đến thư viện."],["平日は6時に起きます。","Ngày thường tôi dậy lúc 6 giờ."]]},{"word":"こんな～","reading":"こんな～","meaning":"..như thế này","hanViet":"","lesson":26,"ex":[["こんな本が好きです。","Tôi thích cuốn sách như thế này."],["こんな問題は難しいです。","Bài toán như thế này khó."],["こんな天気の日は家にいます。","Những ngày thời tiết như thế này, tôi ở nhà."],["こんなに暑い日は初めてです。","Ngày nóng như thế này là lần đầu tiên."],["こんな所に住みたいです。","Tôi muốn sống ở nơi như thế này."]]},{"word":"そんな～","reading":"そんな～","meaning":"…như thế đó","hanViet":"","lesson":26,"ex":[["そんな本は読みません。","Tôi không đọc cuốn sách như thế đó."],["そんなことを言わないでください。","Xin đừng nói những điều như thế đó."],["そんなに高い物は買えません。","Tôi không thể mua đồ đắt như thế đó."],["そんな日は学校を休みます。","Những ngày như thế đó, tôi nghỉ học."],["そんな話は聞きたくありません。","Tôi không muốn nghe câu chuyện như thế đó."]]},{"word":"あんな～","reading":"あんな～","meaning":"…như thế kia","hanViet":"","lesson":26,"ex":[["あんな車が欲しいです。","Tôi muốn chiếc xe như thế kia."],["あんな所へ行きたくありません。","Tôi không muốn đến nơi như thế kia."],["あんなに大きい家に住みたいです。","Tôi muốn sống trong ngôi nhà to như thế kia."],["あんな本は好きではありません。","Tôi không thích cuốn sách như thế kia."],["あんな人は嫌いです。","Tôi ghét người như thế kia."]]},{"word":"出します","reading":"だします","meaning":"đổ,để (rác)","hanViet":"XUẤT","lesson":26,"ex":[["月曜日にごみを出します。","Thứ hai tôi đổ rác."],["朝、ごみを出しました。","Buổi sáng tôi đã đổ rác."],["燃えるごみを出します。","Tôi đổ rác cháy được."],["ごみは8時に出してください。","Hãy đổ rác lúc 8 giờ."],["きょうはごみを出す日です。","Hôm nay là ngày đổ rác."]]},{"word":"燃えるごみ","reading":"もえるごみ","meaning":"rác cháy được","hanViet":"NHIÊN","lesson":26,"ex":[["紙は燃えるごみです。","Giấy là rác cháy được."],["燃えるごみは月曜日に出します。","Rác cháy được thì đổ vào thứ hai."],["このごみは燃えるごみですか。","Rác này có phải rác cháy được không?"],["この袋は燃えるごみです。","Cái túi này là rác cháy được."],["燃えるごみを出しました。","Tôi đã đổ rác cháy được."]]},{"word":"ガス","reading":"ガス","meaning":"ga","hanViet":"","lesson":26,"ex":[["ガスでごはんを作ります。","Tôi nấu cơm bằng ga."],["ガスが止まりました。","Ga đã bị ngắt."],["ガスのにおいがします。","Có mùi ga."],["ガスを使います。","Tôi dùng ga."],["ガスの会社に電話をしました。","Tôi đã gọi điện cho công ty ga."]]},{"word":"ガス会社","reading":"ガスがいしゃ","meaning":"cty ga","hanViet":"HỘI XÃ","lesson":26,"ex":[["ガス会社の人に会いました。","Tôi đã gặp người của công ty ga."],["ガス会社の人が来ました。","Người của công ty ga đã đến."],["ガス会社は駅の近くにあります。","Công ty ga ở gần ga."],["ガス会社に連絡しました。","Tôi đã liên lạc với công ty ga."],["ガス会社で働いています。","Tôi làm việc ở công ty ga."]]},{"word":"様","reading":"さま","meaning":"ngài,vị","hanViet":"DẠNG","lesson":26,"ex":[["田中様に会いました。","Tôi đã gặp ngài Tanaka."],["山田様の家は大きいです。","Nhà của ngài Yamada to."],["田中様のお宅はここですか。","Nhà của ngài Tanaka ở đây phải không?"],["山田様に手紙を書きました。","Tôi đã viết thư cho ngài Yamada."],["田中様に電話をしました。","Tôi đã gọi điện cho ngài Tanaka."]]},{"word":"診ます","reading":"みます","meaning":"chẩn đoán, khám bệnh","hanViet":"CHẨN","lesson":26,"ex":[["医者が私を診ます。","Bác sĩ khám cho tôi."],["あした、医者に診てもらいます。","Ngày mai tôi sẽ nhờ bác sĩ khám."],["医者は目を診ました。","Bác sĩ đã khám mắt."],["歯医者が歯を診ます。","Nha sĩ khám răng."],["病院で医者に診てもらいました。","Tôi đã được bác sĩ khám ở bệnh viện."]]},{"word":"飼います","reading":"かいます","meaning":"nuôi,chăn nuôi","hanViet":"TỰ","lesson":27,"ex":[["犬を飼っています。","Tôi đang nuôi chó."],["猫を飼いたいです。","Tôi muốn nuôi mèo."],["山田さんは鳥を飼っています。","Anh Yamada đang nuôi chim."],["子どもは魚を飼っています。","Con tôi đang nuôi cá."],["昔、馬を飼っていました。","Ngày xưa tôi đã nuôi ngựa."]]},{"word":"建てます","reading":"たてます","meaning":"xây dựng","hanViet":"KIẾN","lesson":27,"ex":[["新しい家を建てます。","Tôi xây nhà mới."],["来年、家を建てるつもりです。","Năm tới tôi định xây nhà."],["駅の近くにビルを建てました。","Họ đã xây tòa nhà gần ga."],["父は家を建てました。","Bố tôi đã xây nhà."],["学校を建てています。","Họ đang xây trường học."]]},{"word":"走ります","reading":"はしります","meaning":"chạy","hanViet":"TẨU","lesson":27,"ex":[["毎朝、公園で走ります。","Mỗi sáng tôi chạy ở công viên."],["子どもが走っています。","Đứa trẻ đang chạy."],["犬が速く走ります。","Con chó chạy nhanh."],["海の近くで走りました。","Tôi đã chạy gần biển."],["電車に間に合うように走りました。","Tôi đã chạy để kịp tàu điện."]]},{"word":"見えます","reading":"みえます","meaning":"có thể nhìn thấy","hanViet":"KIẾN","lesson":27,"ex":[["ここから山が見えます。","Từ đây có thể nhìn thấy núi."],["窓から海が見えます。","Từ cửa sổ có thể nhìn thấy biển."],["夜、星が見えます。","Ban đêm có thể nhìn thấy sao."],["あの山が見えますか。","Bạn có nhìn thấy ngọn núi kia không?"],["部屋から公園が見えます。","Từ phòng có thể nhìn thấy công viên."]]},{"word":"聞こえます","reading":"きこえます","meaning":"có thể nghe thấy","hanViet":"VĂN","lesson":27,"ex":[["ここから音楽が聞こえます。","Từ đây có thể nghe thấy nhạc."],["隣の部屋から声が聞こえます。","Từ phòng bên cạnh có thể nghe thấy tiếng nói."],["鳥の声が聞こえます。","Có thể nghe thấy tiếng chim."],["海の波の音が聞こえます。","Có thể nghe thấy tiếng sóng biển."],["遠くから電車の音が聞こえます。","Từ xa có thể nghe thấy tiếng tàu điện."]]},{"word":"できます","reading":"できます","meaning":"được hoàn thành,được làm","hanViet":"","lesson":27,"ex":[["新しい家ができました。","Ngôi nhà mới đã hoàn thành."],["駅の前に店ができました。","Trước ga đã có cửa hàng mới."],["来年、新しい学校ができます。","Năm tới sẽ có trường học mới."],["ビルができました。","Tòa nhà đã hoàn thành."],["橋ができました。","Cây cầu đã hoàn thành."]]},{"word":"開きます","reading":"ひらきます","meaning":"mở ra, nở ra","hanViet":"KHAI","lesson":27,"ex":[["春に花が開きます。","Mùa xuân hoa nở."],["桜が開きました。","Hoa anh đào đã nở."],["窓が開きます。","Cửa sổ mở ra."],["店が9時に開きます。","Cửa hàng mở cửa lúc 9 giờ."],["ドアが開きました。","Cửa đã mở."]]},{"word":"鳥","reading":"とり","meaning":"Con chim","hanViet":"ĐIỂU","lesson":27,"ex":[["空に鳥が飛んでいます。","Chim đang bay trên trời."],["鳥が木にいます。","Chim ở trên cây."],["公園に鳥がたくさんいます。","Ở công viên có rất nhiều chim."],["鳥を飼っています。","Tôi đang nuôi chim."],["子どもは鳥が好きです。","Trẻ con thích chim."]]},{"word":"声","reading":"こえ","meaning":"Giọng, tiếng nói","hanViet":"THANH","lesson":27,"ex":[["山田さんの声は大きいです。","Giọng anh Yamada to."],["子どもの声が聞こえます。","Có thể nghe thấy tiếng trẻ con."],["先生の声が好きです。","Tôi thích giọng thầy giáo."],["声が小さいです。","Giọng nhỏ."],["母の声が聞こえません。","Tôi không nghe thấy giọng mẹ."]]},{"word":"波","reading":"なみ","meaning":"Sóng (biển, hồ)","hanViet":"BA","lesson":27,"ex":[["海の波が高いです。","Sóng biển cao."],["波の音が聞こえます。","Có thể nghe thấy tiếng sóng."],["子どもは波で遊びます。","Trẻ con chơi với sóng."],["波が静かです。","Sóng lặng."],["きょうは波が強いです。","Hôm nay sóng mạnh."]]},{"word":"花火","reading":"はなび","meaning":"Pháo hoa","hanViet":"HOA HỎA","lesson":27,"ex":[["夏に花火を見ます。","Mùa hè tôi xem pháo hoa."],["花火がきれいです。","Pháo hoa đẹp."],["川で花火をしました。","Tôi đã đốt pháo hoa ở sông."],["花火の音が大きいです。","Tiếng pháo hoa to."],["子どもは花火が好きです。","Trẻ con thích pháo hoa."]]},{"word":"景色","reading":"けしき","meaning":"Phong cảnh","hanViet":"CẢNH SẮC","lesson":27,"ex":[["ここからの景色はきれいです。","Phong cảnh từ đây rất đẹp."],["山の景色がすばらしいです。","Phong cảnh núi tuyệt vời."],["海の景色を見ました。","Tôi đã xem phong cảnh biển."],["窓からの景色がいいです。","Phong cảnh từ cửa sổ đẹp."],["景色の写真を撮りました。","Tôi đã chụp ảnh phong cảnh."]]},{"word":"昼間","reading":"ひるま","meaning":"ban ngày","hanViet":"TRÚ GIAN","lesson":27,"ex":[["昼間は会社で働きます。","Ban ngày tôi làm việc ở công ty."],["昼間は暖かいです。","Ban ngày ấm áp."],["昼間、公園へ行きます。","Ban ngày tôi đến công viên."],["昼間は人が多いです。","Ban ngày đông người."],["昼間は明るいです。","Ban ngày trời sáng."]]},{"word":"昔","reading":"むかし","meaning":"ngày xưa, trước đây","hanViet":"TÍCH","lesson":27,"ex":[["昔、ここに家がありませんでした。","Ngày xưa, ở đây không có nhà."],["昔の写真を見ました。","Tôi đã xem ảnh ngày xưa."],["昔、日本へ行きました。","Ngày xưa tôi đã đi Nhật Bản."],["昔は電車がありませんでした。","Ngày xưa không có tàu điện."],["昔の話を聞きました。","Tôi đã nghe chuyện ngày xưa."]]},{"word":"道具","reading":"どうぐ","meaning":"Dụng cụ, công cụ","hanViet":"ĐẠO CỤ","lesson":27,"ex":[["料理の道具を買いました。","Tôi đã mua dụng cụ nấu ăn."],["道具を使います。","Tôi dùng dụng cụ."],["この道具は便利です。","Dụng cụ này tiện lợi."],["掃除の道具があります。","Có dụng cụ dọn dẹp."],["道具を箱に入れました。","Tôi đã cho dụng cụ vào hộp."]]},{"word":"自動販売機","reading":"じどうはんばいき","meaning":"Máy bán hàng tự động","hanViet":"TỰ ĐỘNG PHÁN MẠI CƠ","lesson":27,"ex":[["自動販売機でジュースを買いました。","Tôi đã mua nước trái cây ở máy bán hàng tự động."],["駅に自動販売機があります。","Ở ga có máy bán hàng tự động."],["自動販売機でコーヒーを買います。","Tôi mua cà phê ở máy bán hàng tự động."],["自動販売機は便利です。","Máy bán hàng tự động tiện lợi."],["自動販売機の前に人がいます。","Trước máy bán hàng tự động có người."]]},{"word":"通信販売","reading":"つうしんはんばい","meaning":"mua hàng qua bưu điện, điện thoại","hanViet":"THÔNG TÍN PHÁN MẠI","lesson":27,"ex":[["通信販売で本を買いました。","Tôi đã mua sách qua đặt hàng từ xa."],["通信販売で服を買います。","Tôi mua quần áo qua đặt hàng từ xa."],["通信販売は便利です。","Đặt hàng từ xa tiện lợi."],["通信販売でコンピューターを買いました。","Tôi đã mua máy tính qua đặt hàng từ xa."],["母は通信販売で買い物します。","Mẹ tôi mua sắm qua đặt hàng từ xa."]]},{"word":"台所","reading":"だいどころ","meaning":"Nhà bếp","hanViet":"ĐÀI SỞ","lesson":27,"ex":[["台所で料理をします。","Tôi nấu ăn trong bếp."],["台所が広いです。","Bếp rộng."],["母は台所にいます。","Mẹ đang ở trong bếp."],["台所を掃除しました。","Tôi đã dọn dẹp bếp."],["台所でごはんを食べます。","Tôi ăn cơm trong bếp."]]},{"word":"ほかの","reading":"ほかの","meaning":"khác","hanViet":"","lesson":27,"ex":[["ほかの本を読みたいです。","Tôi muốn đọc cuốn sách khác."],["ほかの先生に聞きます。","Tôi hỏi thầy giáo khác."],["ほかの店で買いました。","Tôi đã mua ở cửa hàng khác."],["ほかの日に来てください。","Hãy đến vào ngày khác."],["ほかの人が来ました。","Người khác đã đến."]]},{"word":"はっきり","reading":"はっきり","meaning":"rõ, rõ ràng","hanViet":"","lesson":27,"ex":[["はっきり話してください。","Hãy nói rõ ràng."],["声がはっきり聞こえます。","Nghe rõ giọng nói."],["はっきりわかりません。","Tôi không hiểu rõ."],["山がはっきり見えます。","Nhìn rõ ngọn núi."],["はっきり答えてください。","Hãy trả lời rõ ràng."]]},{"word":"ほとんど","reading":"ほとんど","meaning":"hầu hết, hầu như","hanViet":"","lesson":27,"ex":[["ほとんど毎日、運動します。","Hầu như mỗi ngày tôi đều vận động."],["ほとんどわかりました。","Tôi đã hiểu hầu hết."],["学生はほとんど来ました。","Hầu hết học sinh đã đến."],["ほとんど食べました。","Tôi đã ăn hầu hết."],["この本はほとんど読みました。","Tôi đã đọc gần hết cuốn sách này."]]},{"word":"夢","reading":"ゆめ","meaning":"Giấc mơ; ước mơ","hanViet":"MỘNG","lesson":27,"ex":[["私の夢は先生です。","Ước mơ của tôi là làm thầy giáo."],["きのう、楽しい夢を見ました。","Hôm qua tôi đã có giấc mơ vui."],["夢があります。","Tôi có ước mơ."],["子どもの夢は宇宙飛行士です。","Ước mơ của trẻ con là phi hành gia."],["夢で海を見ました。","Trong mơ tôi đã thấy biển."]]},{"word":"いつか","reading":"いつか","meaning":"một ngày nào đó","hanViet":"","lesson":27,"ex":[["いつか日本へ行きたいです。","Một ngày nào đó tôi muốn đi Nhật Bản."],["いつか会いましょう。","Một ngày nào đó chúng ta hãy gặp nhau."],["いつか東京へ行きたいです。","Một ngày nào đó tôi muốn đi Tokyo."],["いつか自分の家を建てたいです。","Một ngày nào đó tôi muốn xây nhà của mình."],["いつか海を見たいです。","Một ngày nào đó tôi muốn nhìn biển."]]},{"word":"家","reading":"いえ","meaning":"Ngôi nhà","hanViet":"GIA","lesson":27,"ex":[["私の家は駅の近くにあります。","Nhà tôi ở gần ga."],["家に帰ります。","Tôi về nhà."],["家が大きいです。","Nhà to."],["家で勉強します。","Tôi học ở nhà."],["家の前に木があります。","Trước nhà có cây."]]},{"word":"すばらしい","reading":"すばらしい","meaning":"tuyệt vời","hanViet":"","lesson":27,"ex":[["すばらしい景色です。","Phong cảnh tuyệt vời."],["すばらしい天気です。","Thời tiết tuyệt vời."],["山田さんの歌はすばらしいです。","Bài hát của anh Yamada tuyệt vời."],["すばらしい本でした。","Đó là cuốn sách tuyệt vời."],["すばらしい一日でした。","Đó là một ngày tuyệt vời."]]},{"word":"漫画","reading":"まんが","meaning":"Truyện tranh","hanViet":"MẠN HỌA","lesson":27,"ex":[["漫画を読みます。","Tôi đọc truyện tranh."],["漫画が好きです。","Tôi thích truyện tranh."],["子どもは漫画を読みます。","Trẻ con đọc truyện tranh."],["日本語の漫画を買いました。","Tôi đã mua truyện tranh tiếng Nhật."],["漫画を集めています。","Tôi đang sưu tập truyện tranh."]]},{"word":"主人公","reading":"しゅじんこう","meaning":"nhân vật chính","hanViet":"CHỦ NHÂN CÔNG","lesson":27,"ex":[["この小説の主人公は男の子です。","Nhan vật chính của tiểu thuyết này là một cậu bé."],["映画の主人公は若い医者です。","Nhân vật chính của bộ phim là một bác sĩ trẻ."],["子どもたちはこの本の主人公が大好きです。","Bọn trẻ rất thích nhân vật chính của cuốn sách này."],["主人公の名前は田中さんです。","Tên của nhân vật chính là anh Tanaka."],["主人公は町で友達と会います。","Nhân vật chính gặp bạn ở thị trấn."]]},{"word":"形","reading":"かたち","meaning":"hình dạng, hình dáng","hanViet":"HÌNH","lesson":27,"ex":[["このケーキは星の形です。","Chiếc bánh này có hình ngôi sao."],["月の形は毎日違います。","Hình dạng của mặt trăng mỗi ngày đều khác nhau."],["この時計の形は丸いです。","Chiếc đồng hồ này có hình tròn."],["子どもは紙で丸い形を作ります。","Trẻ em làm hình tròn bằng giấy."],["この花の形はとてもきれいです。","Hình dạng của bông hoa này rất đẹp."]]},{"word":"不思議な","reading":"ふしぎな","meaning":"Kỳ lạ, khó hiểu","hanViet":"BẤT TƯ NGHỊ","lesson":27,"ex":[["きのう、不思議な夢を見ました。","Hôm qua tôi mơ một giấc mơ kỳ lạ."],["あの家から不思議な音が聞こえます。","Từ ngôi nhà đó vọng ra âm thanh kỳ lạ."],["不思議な話を聞きました。","Tôi đã nghe một câu chuyện kỳ lạ."],["山田さんは不思議な人です。","Anh Yamada là một người kỳ lạ."],["その本には不思議な世界が書いてあります。","Trong cuốn sách đó viết về một thế giới kỳ lạ."]]},{"word":"例えば","reading":"たとえば","meaning":"Ví dụ, chẳng hạn","hanViet":"LỆ","lesson":27,"ex":[["例えば、りんごやみかんは果物です。","Ví dụ, táo và quýt là trái cây."],["日本の食べ物は、例えば、ごはんや魚です。","Món ăn Nhật, ví dụ như cơm và cá."],["スポーツには、例えば、サッカーやテニスがあります。","Thể thao, ví dụ như bóng đá và tennis."],["例えば、東京にはたくさんの大学があります。","Ví dụ, ở Tokyo có rất nhiều trường đại học."],["休みの日は、例えば、映画を見たり、音楽を聞いたりします。","Ngày nghỉ, ví dụ như tôi xem phim, nghe nhạc."]]},{"word":"付けます","reading":"つけます","meaning":"Gắn, bật, để (đèn…)","hanViet":"PHÓ","lesson":27,"ex":[["夜、電気を付けます。","Buổi tối tôi bật điện."],["テレビを付けて、ニュースを見ます。","Tôi bật tivi và xem tin tức."],["かばんに名前を付けました。","Tôi đã gắn tên lên túi."],["壁にポスターを付けました。","Tôi đã dán áp phích lên tường."],["店員は品物に値段を付けます。","Nhân viên cửa hàng gắn giá lên hàng hóa."]]},{"word":"自由に","reading":"じゆうに","meaning":"tự do","hanViet":"TỰ DO","lesson":27,"ex":[["休みの日は自由に時間を使います。","Ngày nghỉ tôi dùng thời gian tự do."],["子どもたちは公園で自由に遊びます。","Bọn trẻ chơi tự do ở công viên."],["私は自由に日本語を話したいです。","Tôi muốn nói tiếng Nhật tự do."],["学生は自由に本を選びます。","Học sinh tự do chọn sách."],["旅行では自由に歩きます。","Khi đi du lịch tôi đi bộ tự do."]]},{"word":"空","reading":"そら","meaning":"Bầu trời","hanViet":"KHÔNG","lesson":27,"ex":[["きょうの空は青いです。","Bầu trời hôm nay xanh."],["空に飛行機が飛んでいます。","Trên bầu trời có máy bay đang bay."],["夜、空に星が見えます。","Buổi tối, trên bầu trời nhìn thấy sao."],["空が暗くなりました。","Bầu trời đã tối lại."],["空に月が見えます。","Trên bầu trời nhìn thấy mặt trăng."]]},{"word":"飛びます","reading":"とびます","meaning":"Bay","hanViet":"PHI","lesson":27,"ex":[["鳥が空を飛びます。","Chim bay trên bầu trời."],["飛行機が空を飛びます。","Máy bay bay trên bầu trời."],["子どもは高く飛びます。","Đứa trẻ nhảy lên cao."],["ボールが高く飛びました。","Quả bóng bay lên cao."],["春になると、鳥が北へ飛びます。","Khi mùa xuân đến, chim bay về phía bắc."]]},{"word":"自分","reading":"じぶん","meaning":"Bản thân mình","hanViet":"TỰ PHÂN","lesson":27,"ex":[["自分で昼ごはんを作ります。","Tôi tự nấu bữa trưa."],["自分の部屋で勉強します。","Tôi học trong phòng của mình."],["自分の名前を書きました。","Tôi đã viết tên của mình."],["自分で服を選びます。","Tôi tự chọn quần áo."],["自分の車で行きます。","Tôi đi bằng xe của mình."]]},{"word":"将来","reading":"しょうらい","meaning":"Tương lai","hanViet":"TƯƠNG LAI","lesson":27,"ex":[["将来、医者になりたいです。","Trong tương lai tôi muốn trở thành bác sĩ."],["将来、日本で働きたいです。","Trong tương lai tôi muốn làm việc ở Nhật."],["将来の夢は先生です。","Ước mơ tương lai của tôi là làm giáo viên."],["将来、自分の店を持ちたいです。","Trong tương lai tôi muốn có cửa hàng của riêng mình."],["将来、東京に住みたいです。","Trong tương lai tôi muốn sống ở Tokyo."]]},{"word":"現像","reading":"げんぞう","meaning":"rửa ảnh","hanViet":"HIỆN TƯỢNG","lesson":27,"ex":[["この店で写真の現像ができます。","Ở cửa hàng này có thể rửa ảnh."],["現像は一週間かかります。","Rửa ảnh mất một tuần."],["旅行の写真を現像します。","Tôi rửa ảnh chuyến du lịch."],["現像は500円です。","Rửa ảnh là 500 yên."],["子どもの写真を現像しました。","Tôi đã rửa ảnh của con."]]},{"word":"焼き増し","reading":"やきまし","meaning":"in thêm","hanViet":"THIÊU TĂNG","lesson":27,"ex":[["この写真を焼き増ししてください。","Xin in thêm tấm ảnh này."],["焼き増しは1枚100円です。","In thêm là 100 yên một tấm."],["友達にあげますから、写真を焼き増しします。","Vì để tặng bạn nên tôi in thêm ảnh."],["焼き増しは3日かかります。","In thêm mất 3 ngày."],["子どもの写真を2枚焼き増ししました。","Tôi đã in thêm 2 tấm ảnh của con."]]},{"word":"引き伸ばし","reading":"ひきのばし","meaning":"phóng đại","hanViet":"DẪN THÂN","lesson":27,"ex":[["この写真を引き伸ばししてください。","Xin phóng to tấm ảnh này."],["引き伸ばしは1枚500円です。","Phóng to là 500 yên một tấm."],["家族の写真を引き伸ばして、壁に飾ります。","Tôi phóng to ảnh gia đình và treo lên tường."],["引き伸ばしは1週間かかります。","Phóng to mất một tuần."],["小さい写真を引き伸ばしました。","Tôi đã phóng to tấm ảnh nhỏ."]]},{"word":"水洗い","reading":"みずあらい","meaning":"giặt nước","hanViet":"THỦY TẨY","lesson":27,"ex":[["このシャツは水洗いができます。","Chiếc áo sơ mi này có thể giặt nước."],["水洗いしてください。","Xin giặt nước."],["コートは水洗いができません。","Áo khoác không thể giặt nước."],["水洗いとクリーニングがあります。","Có giặt nước và giặt ủi."],["服の水洗いは500円です。","Giặt nước quần áo là 500 yên."]]},{"word":"染み抜き","reading":"しみぬき","meaning":"tẩy vết bẩn","hanViet":"NHIỄM BẠT","lesson":27,"ex":[["このシャツの染み抜きをお願いします。","Xin tẩy vết bẩn trên chiếc áo này."],["コーヒーの染み抜きができますか。","Có tẩy được vết cà phê không?"],["染み抜きは300円です。","Tẩy vết bẩn là 300 yên."],["ズボンの染み抜きをしました。","Tôi đã tẩy vết bẩn trên quần."],["染み抜きは2日かかります。","Tẩy vết bẩn mất 2 ngày."]]},{"word":"防水加工","reading":"ぼうすいかこう","meaning":"gia công chống nước","hanViet":"PHÒNG THỦY GIA CÔNG","lesson":27,"ex":[["このコートに防水加工をしてください。","Xin gia công chống nước cho chiếc áo khoác này."],["防水加工は1,000円です。","Gia công chống nước là 1.000 yên."],["靴に防水加工をしました。","Tôi đã gia công chống nước cho giày."],["かばんの防水加工ができますか。","Có gia công chống nước cho túi được không?"],["雨の日は防水加工が便利です。","Ngày mưa thì gia công chống nước rất tiện."]]},{"word":"縮む","reading":"ちぢむ","meaning":"co lại, thu lại","hanViet":"SÚC","lesson":27,"ex":[["このセーターは洗うと縮みます。","Chiếc áo len này giặt sẽ bị co lại."],["ズボンが縮みました。","Quần đã bị co lại."],["この服は水で縮みます。","Quần áo này gặp nước sẽ co lại."],["セーターが小さく縮みました。","Áo len đã co lại nhỏ hơn."],["熱い水で服が縮みます。","Nước nóng làm quần áo co lại."]]},{"word":"伸びる","reading":"のびる","meaning":"Dài ra, cao lên, tăng trưởng","hanViet":"THÂN","lesson":27,"ex":[["髪が長く伸びました。","Tóc đã dài ra."],["木が大きく伸びました。","Cây đã lớn lên."],["春になると、木が伸びます。","Khi mùa xuân đến, cây lớn lên."],["日本語の力が伸びました。","Năng lực tiếng Nhật của tôi đã tăng lên."],["毎日練習すると、力が伸びます。","Luyện tập mỗi ngày thì năng lực sẽ tăng lên."]]},{"word":"宅配便の受付","reading":"たくはいびんおうけつけ","meaning":"nhận gửi đồ đến nhà","hanViet":"TRẠCH PHỐI TIỆN THỤ PHÓ","lesson":27,"ex":[["コンビニで宅配便の受付ができます。","Ở cửa hàng tiện lợi có thể nhận gửi đồ đến nhà."],["宅配便の受付は24時間です。","Nhận gửi đồ đến nhà phục vụ 24 giờ."],["荷物の宅配便の受付をお願いします。","Xin nhận gửi hành lý đến nhà."],["宅配便の受付で荷物を送りました。","Tôi đã gửi hành lý ở quầy nhận gửi đồ đến nhà."],["この店は宅配便の受付をしています。","Cửa hàng này có nhận gửi đồ đến nhà."]]},{"word":"写真現像","reading":"しゃしんげんぞう","meaning":"rửa ảnh","hanViet":"TẢ CHÂN HIỆN TƯỢNG","lesson":27,"ex":[["この店で写真現像ができます。","Ở cửa hàng này có thể rửa ảnh."],["写真現像は3日かかります。","Rửa ảnh mất 3 ngày."],["写真現像は1枚30円です。","Rửa ảnh là 30 yên một tấm."],["旅行の写真現像をお願いします。","Xin rửa ảnh chuyến du lịch."],["写真現像の店が近くにあります。","Gần đây có cửa hàng rửa ảnh."]]},{"word":"公共料金振込み","reading":"こうきょうりょうきんふりこえ","meaning":"trả tiền dịch vụ công cộng","hanViet":"CÔNG CỘNG LIỆU KIM CHẤN —","lesson":27,"ex":[["コンビニで公共料金振込みができます。","Ở cửa hàng tiện lợi có thể trả tiền dịch vụ công cộng."],["電気の公共料金振込みをしました。","Tôi đã trả tiền điện."],["公共料金振込みは銀行でもできます。","Trả tiền dịch vụ công cộng cũng có thể làm ở ngân hàng."],["毎月、公共料金振込みをします。","Mỗi tháng tôi trả tiền dịch vụ công cộng."],["水道の公共料金振込みをしました。","Tôi đã trả tiền nước."]]},{"word":"はがき、切手の販売","reading":"はがき、きってのはんばい","meaning":"bán bưu thiếp và tem","hanViet":"THIẾT THỦ PHÁN MẠI","lesson":27,"ex":[["郵便局ではがき、切手の販売をしています。","Bưu điện có bán bưu thiếp và tem."],["コンビニではがき、切手の販売があります。","Ở cửa hàng tiện lợi có bán bưu thiếp và tem."],["はがき、切手の販売は9時からです。","Bán bưu thiếp và tem bắt đầu từ 9 giờ."],["はがき、切手の販売で切手を買いました。","Tôi đã mua tem ở quầy bán bưu thiếp và tem."],["この店ではがき、切手の販売をしています。","Cửa hàng này có bán bưu thiếp và tem."]]},{"word":"ペット","reading":"ペット","meaning":"thú cưng,động vật nuôi","hanViet":"","lesson":27,"ex":[["私のペットは犬です。","Thú cưng của tôi là chó."],["ペットの猫はかわいいです。","Con mèo cưng rất dễ thương."],["ペットを飼っています。","Tôi đang nuôi thú cưng."],["このマンションはペットが飼えません。","Chung cư này không được nuôi thú cưng."],["ペットの犬と公園へ行きます。","Tôi đi công viên với chú chó cưng."]]},{"word":"クリーニング","reading":"クリーニング","meaning":"giặt ủi","hanViet":"","lesson":27,"ex":[["スーツをクリーニングに出しました。","Tôi đã mang bộ vest đi giặt ủi."],["クリーニングは3日かかります。","Giặt ủi mất 3 ngày."],["コートをクリーニングに出します。","Tôi mang áo khoác đi giặt ủi."],["クリーニングの店が近くにあります。","Gần đây có tiệm giặt ủi."],["シャツのクリーニングは300円です。","Giặt ủi áo sơ mi là 300 yên."]]},{"word":"マンション","reading":"マンション","meaning":"chung cư","hanViet":"","lesson":27,"ex":[["私はマンションに住んでいます。","Tôi đang sống ở chung cư."],["マンションの3階に住んでいます。","Tôi sống ở tầng 3 của chung cư."],["新しいマンションは駅の近くにあります。","Chung cư mới ở gần ga."],["マンションの家賃は高いです。","Tiền thuê chung cư đắt."],["友達は大きいマンションに住んでいます。","Bạn tôi sống ở chung cư lớn."]]},{"word":"～後","reading":"～ご","meaning":"~ sau (khoảng thời gian)","hanViet":"HẬU","lesson":27,"ex":[["1時間後、会社へ行きます。","Sau 1 giờ tôi đi làm."],["3日後、友達に会います。","Sau 3 ngày tôi gặp bạn."],["1週間後、テストがあります。","Sau 1 tuần có bài kiểm tra."],["食事の後、テレビを見ます。","Sau bữa ăn tôi xem tivi."],["1年後、日本へ行きます。","Sau 1 năm tôi đi Nhật."]]},{"word":"～しか","reading":"～しか","meaning":"chỉ","hanViet":"","lesson":27,"ex":[["お金は100円しかありません。","Tôi chỉ có 100 yên."],["日本語しか話せません。","Tôi chỉ nói được tiếng Nhật."],["時間は1時間しかありません。","Tôi chỉ có 1 giờ."],["教室に学生が3人しかいません。","Trong lớp chỉ có 3 học sinh."],["この店には本しかありません。","Cửa hàng này chỉ có sách."]]},{"word":"～教室","reading":"～きょうしつ","meaning":"lớp học","hanViet":"GIÁO THẤT","lesson":27,"ex":[["日本語教室に通います。","Tôi đi học lớp tiếng Nhật."],["ピアノ教室でピアノを習います。","Tôi học piano ở lớp piano."],["料理教室に行きたいです。","Tôi muốn đi học lớp nấu ăn."],["英語教室の先生はアメリカの人です。","Giáo viên lớp tiếng Anh là người Mỹ."],["子どもはダンス教室に通っています。","Con tôi đang học lớp nhảy."]]},{"word":"パーティールーム","reading":"パーティールーム","meaning":"phòng tiệc","hanViet":"","lesson":27,"ex":[["パーティールームを借りました。","Tôi đã thuê phòng tiệc."],["誕生日にパーティールームを使います。","Tôi dùng phòng tiệc vào sinh nhật."],["パーティールームは20人まで入ります。","Phòng tiệc chứa tối đa 20 người."],["友達とパーティールームで会います。","Tôi gặp bạn ở phòng tiệc."],["このマンションにパーティールームがあります。","Chung cư này có phòng tiệc."]]},{"word":"関西空港","reading":"かんさいくうこう","meaning":"sân bay Kansai","hanViet":"QUAN TÂY KHÔNG CẢNG","lesson":27,"ex":[["関西空港へ飛行機で行きます。","Tôi đi máy bay đến sân bay Kansai."],["関西空港は大きいです。","Sân bay Kansai lớn."],["友達を関西空港で迎えます。","Tôi đón bạn ở sân bay Kansai."],["関西空港から東京へ行きます。","Tôi đi từ sân bay Kansai đến Tokyo."],["関西空港に9時に着きます。","Tôi đến sân bay Kansai lúc 9 giờ."]]},{"word":"秋葉原","reading":"あきはばら","meaning":"khu bán đồ điện tử nổi tiếng ở Tokyo","hanViet":"THU DIỆP NGUYÊN","lesson":27,"ex":[["秋葉原でパソコンを買いました。","Tôi đã mua máy tính ở Akihabara."],["秋葉原は電気の店が多いです。","Akihabara có nhiều cửa hàng điện tử."],["友達と秋葉原へ行きます。","Tôi đi Akihabara với bạn."],["秋葉原でカメラを買いたいです。","Tôi muốn mua máy ảnh ở Akihabara."],["秋葉原は東京にあります。","Akihabara ở Tokyo."]]},{"word":"伊豆","reading":"いず","meaning":"bán đảo Izu ở tỉnh Shizuoka","hanViet":"ĐẬU","lesson":27,"ex":[["伊豆へ旅行に行きました。","Tôi đã đi du lịch Izu."],["伊豆の海はきれいです。","Biển ở Izu rất đẹp."],["伊豆で温泉に入りました。","Tôi đã tắm suối nước nóng ở Izu."],["友達と伊豆へ行きます。","Tôi đi Izu với bạn."],["伊豆は静かです。","Izu yên tĩnh."]]},{"word":"日曜日大工","reading":"にちようびだいく","meaning":"thợ mộc chủ nhật","hanViet":"NHẬT DIỆU NHẬT ĐẠI CÔNG","lesson":27,"ex":[["父の趣味は日曜日大工です。","Sở thích của bố tôi là làm mộc ngày chủ nhật."],["日曜日大工で本棚を作りました。","Tôi đã tự làm kệ sách vào ngày chủ nhật."],["日曜日大工が好きです。","Tôi thích làm mộc ngày chủ nhật."],["日曜日、日曜日大工をします。","Ngày chủ nhật tôi làm mộc."],["日曜日大工で机を作ります。","Tôi tự làm bàn vào ngày chủ nhật."]]},{"word":"本棚","reading":"ほんだな","meaning":"kệ sách,giá sách","hanViet":"BẢN BẰNG","lesson":27,"ex":[["本棚に本がたくさんあります。","Trên kệ sách có rất nhiều sách."],["新しい本棚を買いました。","Tôi đã mua kệ sách mới."],["本棚に本を並べます。","Tôi xếp sách lên kệ."],["父は本棚を作りました。","Bố tôi đã làm kệ sách."],["私の部屋に本棚があります。","Trong phòng tôi có kệ sách."]]},{"word":"子どもたち","reading":"こどもたち","meaning":"bọn trẻ","hanViet":"TỬ","lesson":27,"ex":[["子どもたちは公園で遊んでいます。","Bọn trẻ đang chơi ở công viên."],["子どもたちは歌が好きです。","Bọn trẻ thích hát."],["子どもたちは学校へ行きます。","Bọn trẻ đi học."],["子どもたちに本を読みます。","Tôi đọc sách cho bọn trẻ."],["子どもたちは元気です。","Bọn trẻ khỏe mạnh."]]},{"word":"大好き","reading":"だいすき","meaning":"rất thích","hanViet":"ĐẠI HẢO","lesson":27,"ex":[["私は日本語が大好きです。","Tôi rất thích tiếng Nhật."],["母は花が大好きです。","Mẹ tôi rất thích hoa."],["子どもは犬が大好きです。","Trẻ em rất thích chó."],["私はこの歌が大好きです。","Tôi rất thích bài hát này."],["弟はサッカーが大好きです。","Em trai tôi rất thích bóng đá."]]},{"word":"ポケット","reading":"ポケット","meaning":"túi","hanViet":"","lesson":27,"ex":[["ポケットに鍵があります。","Trong túi có chìa khóa."],["財布をポケットに入れました。","Tôi đã bỏ ví vào túi."],["この服のポケットは小さいです。","Túi của bộ quần áo này nhỏ."],["ポケットから財布を出しました。","Tôi lấy ví ra từ túi."],["手をポケットに入れます。","Tôi bỏ tay vào túi."]]},{"word":"ドラえもん","reading":"ドラえもん","meaning":"đô-rê-mon","hanViet":"","lesson":27,"ex":[["子どもはドラえもんが大好きです。","Trẻ em rất thích Doraemon."],["ドラえもんの漫画を読みます。","Tôi đọc truyện Doraemon."],["ドラえもんはテレビで見ます。","Tôi xem Doraemon trên tivi."],["ドラえもんの映画を見ました。","Tôi đã xem phim Doraemon."],["弟はドラえもんの本を持っています。","Em trai tôi có sách Doraemon."]]},{"word":"取ります","reading":"とります","meaning":"xin(nghỉ)","hanViet":"THỦ","lesson":27,"ex":[["来週、休みを取ります。","Tuần sau tôi xin nghỉ."],["3日、休みを取りました。","Tôi đã xin nghỉ 3 ngày."],["夏に休みを取りたいです。","Tôi muốn xin nghỉ vào mùa hè."],["母は休みを取りました。","Mẹ tôi đã xin nghỉ."],["来月、1週間休みを取ります。","Tháng sau tôi xin nghỉ 1 tuần."]]},{"word":"踊ります","reading":"おどります","meaning":"Nhảy múa","hanViet":"DŨNG","lesson":28,"ex":[["パーティーで踊ります。","Tôi nhảy múa ở bữa tiệc."],["子どもたちは歌って、踊ります。","Bọn trẻ vừa hát vừa nhảy."],["妹はダンスが上手で、よく踊ります。","Em gái tôi nhảy giỏi, thường xuyên nhảy múa."],["運動会で踊りました。","Tôi đã nhảy múa ở hội thao."],["友達と踊ります。","Tôi nhảy múa cùng bạn."]]},{"word":"かみます","reading":"かみます","meaning":"nhai,cắn","hanViet":"","lesson":28,"ex":[["ごはんをよくかみます。","Tôi nhai kỹ cơm."],["肉をよくかんで食べます。","Tôi nhai kỹ thịt rồi ăn."],["ガムをかみます。","Tôi nhai kẹo cao su."],["子どもはりんごをかみます。","Đứa trẻ cắn táo."],["犬はパンをかみます。","Chó gặm bánh mì."]]},{"word":"選びます","reading":"えらびます","meaning":"Chọn, lựa chọn","hanViet":"TUYỂN","lesson":28,"ex":[["服を選びます。","Tôi chọn quần áo."],["プレゼントを選びました。","Tôi đã chọn quà."],["色を選んでください。","Xin hãy chọn màu."],["本を選びます。","Tôi chọn sách."],["仕事を選びます。","Tôi chọn công việc."]]},{"word":"違います","reading":"ちがいます","meaning":"khác,không phải","hanViet":"VI","lesson":28,"ex":[["これは私の本と違います。","Cái này khác với sách của tôi."],["答えが違います。","Đáp án khác."],["電話番号が違います。","Số điện thoại khác."],["色が違います。","Màu sắc khác."],["意味が違います。","Ý nghĩa khác."]]},{"word":"通います","reading":"かよいます","meaning":"đi học(đại học)","hanViet":"THÔNG","lesson":28,"ex":[["大学に通います。","Tôi đi học đại học."],["日本語学校に通っています。","Tôi đang học trường tiếng Nhật."],["1週間に3回、学校に通います。","Tôi đi học 3 lần một tuần."],["妹は大学に通っています。","Em gái tôi đang học đại học."],["電車で学校に通います。","Tôi đi học bằng tàu điện."]]},{"word":"まじめな","reading":"まじめな","meaning":"nghiêm túc, nghiêm chỉnh","hanViet":"","lesson":28,"ex":[["田中さんはまじめな学生です。","Anh Tanaka là học sinh nghiêm túc."],["弟はまじめな人です。","Em trai tôi là người nghiêm túc."],["まじめに勉強します。","Tôi học hành nghiêm túc."],["山田さんはまじめに働きます。","Anh Yamada làm việc nghiêm túc."],["まじめな先生です。","Là giáo viên nghiêm túc."]]},{"word":"熱心な","reading":"ねっしんな","meaning":"Nhiệt tình, nhiệt tâm","hanViet":"NHIỆT TÂM","lesson":28,"ex":[["先生は熱心な人です。","Thầy giáo là người nhiệt tình."],["田中さんは仕事に熱心です。","Anh Tanaka nhiệt tình với công việc."],["熱心に日本語を勉強します。","Tôi học tiếng Nhật một cách nhiệt tình."],["熱心な学生です。","Là học sinh nhiệt tình."],["母は熱心に料理を教えます。","Mẹ tôi nhiệt tình dạy nấu ăn."]]},{"word":"優しい","reading":"やさしい","meaning":"dịu dàng, tốt bụng, dễ tính","hanViet":"ƯU","lesson":28,"ex":[["母は優しい人です。","Mẹ tôi là người dịu dàng."],["先生は優しいです。","Thầy giáo tốt bụng."],["優しい声で話します。","Tôi nói bằng giọng dịu dàng."],["友達は優しいです。","Bạn tôi tốt bụng."],["優しい先生に習います。","Tôi học với thầy giáo tốt bụng."]]},{"word":"偉い","reading":"えらい","meaning":"vĩ đại, giỏi giang; (cũng: tệ, mệt)","hanViet":"VĨ","lesson":28,"ex":[["あの先生は偉い人です。","Thầy giáo đó là người vĩ đại."],["偉い小説家です。","Là tiểu thuyết gia vĩ đại."],["父は偉い医者です。","Bố tôi là bác sĩ giỏi giang."],["偉い歌手の歌を聞きました。","Tôi đã nghe bài hát của ca sĩ vĩ đại."],["偉い人になりたいです。","Tôi muốn trở thành người vĩ đại."]]},{"word":"ちょうどいい","reading":"ちょうどいい","meaning":"vừa đủ, vừa đúng","hanViet":"","lesson":28,"ex":[["この服はちょうどいいです。","Bộ quần áo này vừa vặn."],["この部屋はちょうどいいです。","Căn phòng này vừa đủ."],["時間がちょうどいいです。","Thời gian vừa đúng."],["この値段はちょうどいいです。","Giá này vừa đúng."],["この量はちょうどいいです。","Lượng này vừa đủ."]]},{"word":"習慣","reading":"しゅうかん","meaning":"Thói quen, tập quán","hanViet":"TẬP QUÁN","lesson":28,"ex":[["朝、歩く習慣があります。","Tôi có thói quen đi bộ buổi sáng."],["毎朝、牛乳を飲む習慣があります。","Tôi có thói quen uống sữa mỗi sáng."],["日本の習慣を勉強します。","Tôi học tập quán Nhật Bản."],["早く寝る習慣があります。","Tôi có thói quen ngủ sớm."],["いい習慣です。","Là thói quen tốt."]]},{"word":"経験","reading":"けいけん","meaning":"Kinh nghiệm","hanViet":"KINH NGHIỆM","lesson":28,"ex":[["仕事の経験があります。","Tôi có kinh nghiệm làm việc."],["日本へ行った経験があります。","Tôi có kinh nghiệm đi Nhật."],["経験がありません。","Tôi không có kinh nghiệm."],["先生は経験が多いです。","Thầy giáo có nhiều kinh nghiệm."],["旅行の経験を話します。","Tôi kể về kinh nghiệm du lịch."]]},{"word":"力","reading":"ちから","meaning":"sức, sức mạnh","hanViet":"LỰC","lesson":28,"ex":[["力が強いです。","Sức mạnh lớn."],["日本語の力があります。","Tôi có năng lực tiếng Nhật."],["力がありません。","Tôi không có sức."],["力でドアを開けます。","Tôi mở cửa bằng sức."],["力を入れて、持ちます。","Tôi dùng sức để cầm lên."]]},{"word":"人気","reading":"にんき","meaning":"Được yêu thích, nổi tiếng","hanViet":"NHÂN KHÍ","lesson":28,"ex":[["この歌は人気があります。","Bài hát này được yêu thích."],["あの歌手は人気です。","Ca sĩ đó nổi tiếng."],["この本は人気があります。","Cuốn sách này được yêu thích."],["人気の店です。","Là cửa hàng nổi tiếng."],["この映画は人気があります。","Bộ phim này được yêu thích."]]},{"word":"色","reading":"いろ","meaning":"Màu sắc","hanViet":"SẮC","lesson":28,"ex":[["この服の色は赤です。","Màu của bộ quần áo này là đỏ."],["色がきれいです。","Màu sắc đẹp."],["好きな色は青です。","Màu yêu thích của tôi là xanh dương."],["花の色がきれいです。","Màu của hoa đẹp."],["色を選びます。","Tôi chọn màu."]]},{"word":"味","reading":"あじ","meaning":"Vị, mùi vị","hanViet":"VỊ","lesson":28,"ex":[["この料理の味はいいです。","Món ăn này có vị ngon."],["味が甘いです。","Vị ngọt."],["魚の味はおいしいです。","Vị của cá ngon."],["味を見てください。","Xin hãy nếm thử vị."],["このお茶の味は苦いです。","Trà này có vị đắng."]]},{"word":"品物","reading":"しなもの","meaning":"Hàng hoá, mặt hàng","hanViet":"PHẨM VẬT","lesson":28,"ex":[["この店の品物は安いです。","Hàng hóa của cửa hàng này rẻ."],["品物を選びます。","Tôi chọn hàng hóa."],["品物の値段を聞きます。","Tôi hỏi giá hàng hóa."],["いい品物があります。","Có hàng hóa tốt."],["品物を買います。","Tôi mua hàng hóa."]]},{"word":"値段","reading":"ねだん","meaning":"Giá tiền, giá cả","hanViet":"TRỊ ĐOẠN","lesson":28,"ex":[["この本の値段はいくらですか。","Cuốn sách này giá bao nhiêu?"],["値段が高いです。","Giá đắt."],["値段を聞きました。","Tôi đã hỏi giá."],["服の値段は安いです。","Giá quần áo rẻ."],["値段がちょうどいいです。","Giá vừa đúng."]]},{"word":"給料","reading":"きゅうりょう","meaning":"Tiền lương","hanViet":"CẤP LIỆU","lesson":28,"ex":[["給料は月に20万円です。","Lương tháng là 200.000 yên."],["給料が上がりました。","Lương đã tăng."],["給料は銀行に入ります。","Lương được chuyển vào ngân hàng."],["給料が少ないです。","Lương ít."],["毎月、給料をもらいます。","Mỗi tháng tôi nhận lương."]]},{"word":"番組","reading":"ばんぐみ","meaning":"Chương trình (TV, radio)","hanViet":"PHIÊN TỔ","lesson":28,"ex":[["テレビの番組を見ます。","Tôi xem chương trình tivi."],["この番組はおもしろいです。","Chương trình này thú vị."],["ニュースの番組を見ました。","Tôi đã xem chương trình tin tức."],["毎週、この番組を見ます。","Mỗi tuần tôi xem chương trình này."],["ラジオの番組を聞きます。","Tôi nghe chương trình radio."]]},{"word":"小説","reading":"しょうせつ","meaning":"Tiểu thuyết","hanViet":"TIỂU THUYẾT","lesson":28,"ex":[["小説を読みます。","Tôi đọc tiểu thuyết."],["この小説はおもしろいです。","Tiểu thuyết này thú vị."],["図書館で小説を借ります。","Tôi mượn tiểu thuyết ở thư viện."],["小説を書きます。","Tôi viết tiểu thuyết."],["小説の主人公は学生です。","Nhân vật chính của tiểu thuyết là học sinh."]]},{"word":"小説家","reading":"しょうせつか","meaning":"tiểu thuyết gia","hanViet":"TIỂU THUYẾT GIA","lesson":28,"ex":[["有名な小説家です。","Là tiểu thuyết gia nổi tiếng."],["小説家になりたいです。","Tôi muốn trở thành tiểu thuyết gia."],["小説家に会いました。","Tôi đã gặp tiểu thuyết gia."],["あの小説家の本を読みます。","Tôi đọc sách của tiểu thuyết gia đó."],["小説家は本を書きます。","Tiểu thuyết gia viết sách."]]},{"word":"歌手","reading":"かしゅ","meaning":"Ca sĩ","hanViet":"CA THỦ","lesson":28,"ex":[["有名な歌手です。","Là ca sĩ nổi tiếng."],["歌手の歌を聞きます。","Tôi nghe bài hát của ca sĩ."],["歌手になりたいです。","Tôi muốn trở thành ca sĩ."],["あの歌手は人気があります。","Ca sĩ đó được yêu thích."],["歌手のコンサートへ行きます。","Tôi đi buổi hòa nhạc của ca sĩ."]]},{"word":"管理人","reading":"かんりにん","meaning":"Người quản lý (toà nhà…)","hanViet":"QUẢN LÝ NHÂN","lesson":28,"ex":[["マンションの管理人に会いました。","Tôi đã gặp người quản lý chung cư."],["管理人に鍵をもらいました。","Tôi đã nhận chìa khóa từ người quản lý."],["管理人は部屋のことを知っています。","Người quản lý biết về phòng."],["管理人に聞きました。","Tôi đã hỏi người quản lý."],["管理人は毎日働きます。","Người quản lý làm việc mỗi ngày."]]},{"word":"息子","reading":"むすこ","meaning":"Con trai","hanViet":"TỨC TỬ","lesson":28,"ex":[["私の息子は小学生です。","Con trai tôi là học sinh tiểu học."],["息子は元気です。","Con trai tôi khỏe mạnh."],["息子は大学に通っています。","Con trai tôi đang học đại học."],["息子と公園へ行きます。","Tôi đi công viên với con trai."],["息子はサッカーが好きです。","Con trai tôi thích bóng đá."]]},{"word":"息子さん","reading":"むすこさん","meaning":"con trai(dùng cho người khác)","hanViet":"TỨC TỬ","lesson":28,"ex":[["田中さんの息子さんは大学生です。","Con trai của anh Tanaka là sinh viên đại học."],["息子さんは元気ですか。","Con trai của anh/chị có khỏe không?"],["山田さんの息子さんは会社で働いています。","Con trai của anh Yamada đang làm việc ở công ty."],["息子さんは何歳ですか。","Con trai của anh/chị bao nhiêu tuổi?"],["田中さんの息子さんは先生になりました。","Con trai của anh Tanaka đã trở thành giáo viên."]]},{"word":"娘","reading":"むすめ","meaning":"Con gái; cô gái trẻ","hanViet":"NƯƠNG","lesson":28,"ex":[["私の娘は小学生です。","Con gái tôi là học sinh tiểu học."],["娘はピアノを習っています。","Con gái tôi đang học piano."],["娘は元気です。","Con gái tôi khỏe mạnh."],["娘と公園へ行きます。","Tôi đi công viên với con gái."],["娘は歌が好きです。","Con gái tôi thích hát."]]},{"word":"娘さん","reading":"むすめさん","meaning":"con gái(dùng cho người khác)","hanViet":"NƯƠNG","lesson":28,"ex":[["田中さんの娘さんは大学生です。","Con gái của anh Tanaka là sinh viên đại học."],["娘さんは元気ですか。","Con gái của anh/chị có khỏe không?"],["山田さんの娘さんは会社で働いています。","Con gái của anh Yamada đang làm việc ở công ty."],["娘さんは何歳ですか。","Con gái của anh/chị bao nhiêu tuổi?"],["田中さんの娘さんは医者になりました。","Con gái của anh Tanaka đã trở thành bác sĩ."]]},{"word":"しばらく","reading":"しばらく","meaning":"một khoảng thời gian ngắn, một chút, một lát","hanViet":"","lesson":28,"ex":[["しばらく待ってください。","Xin đợi một lát."],["しばらく休みます。","Tôi nghỉ một lát."],["しばらく会っていません。","Đã lâu tôi không gặp."],["しばらく日本に住みます。","Tôi sống ở Nhật một thời gian."],["しばらく雨が降ります。","Mưa rơi một lúc."]]},{"word":"たいてい","reading":"たいてい","meaning":"thường, thông thường","hanViet":"","lesson":28,"ex":[["たいてい、朝7時に起きます。","Thường tôi dậy lúc 7 giờ sáng."],["たいてい、昼ごはんは家で食べます。","Thường tôi ăn trưa ở nhà."],["たいてい、電車で会社へ行きます。","Thường tôi đi làm bằng tàu điện."],["たいてい、夜10時に寝ます。","Thường tôi ngủ lúc 10 giờ đêm."],["たいてい、日曜日に休みます。","Thường tôi nghỉ vào chủ nhật."]]},{"word":"それに","reading":"それに","meaning":"ngoài ra","hanViet":"","lesson":28,"ex":[["この店は安いです。それに、近いです。","Cửa hàng này rẻ. Ngoài ra, còn gần."],["この部屋は広いです。それに、明るいです。","Căn phòng này rộng. Ngoài ra, còn sáng."],["この料理はおいしいです。それに、安いです。","Món ăn này ngon. Ngoài ra, còn rẻ."],["田中さんは親切です。それに、まじめです。","Anh Tanaka tốt bụng. Ngoài ra, còn nghiêm túc."],["この本はおもしろいです。それに、易しいです。","Cuốn sách này thú vị. Ngoài ra, còn dễ."]]},{"word":"それで","reading":"それで","meaning":"do đó","hanViet":"","lesson":28,"ex":[["雨でした。それで、うちにいました。","Trời mưa. Do đó, tôi ở nhà."],["電車が遅れました。それで、会社に遅れました。","Tàu điện bị trễ. Do đó, tôi đến công ty muộn."],["忙しいです。それで、行けません。","Tôi bận. Do đó, tôi không đi được."],["病気です。それで、休みます。","Tôi bị bệnh. Do đó, tôi nghỉ."],["お金がありません。それで、買いません。","Tôi không có tiền. Do đó, tôi không mua."]]},{"word":"会話","reading":"かいわ","meaning":"Hội thoại, đàm thoại","hanViet":"HỘI THOẠI","lesson":28,"ex":[["日本語の会話を勉強します。","Tôi học hội thoại tiếng Nhật."],["友達と会話をします。","Tôi trò chuyện với bạn."],["会話が楽しいです。","Cuộc trò chuyện vui vẻ."],["授業で会話を習います。","Tôi học hội thoại trong giờ học."],["会話の本を読みます。","Tôi đọc sách hội thoại."]]},{"word":"お知らせ","reading":"おしらせ","meaning":"bản thông báo","hanViet":"TRI","lesson":28,"ex":[["学校のお知らせを見ました。","Tôi đã xem bản thông báo của trường."],["お知らせがあります。","Có thông báo."],["会社のお知らせを読みます。","Tôi đọc thông báo của công ty."],["お知らせに休みの日が書いてあります。","Trong thông báo có ghi ngày nghỉ."],["先生のお知らせを聞きました。","Tôi đã nghe thông báo của thầy giáo."]]},{"word":"日にち","reading":"ひにち","meaning":"ngày","hanViet":"NHẬT","lesson":28,"ex":[["旅行の日にちを決めます。","Tôi quyết định ngày đi du lịch."],["パーティーの日にちはいつですか。","Ngày của bữa tiệc là khi nào?"],["試験の日にちがわかりません。","Tôi không biết ngày thi."],["会議の日にちを教えてください。","Xin cho tôi biết ngày họp."],["日にちが違います。","Ngày khác."]]},{"word":"体育館","reading":"たいいくかん","meaning":"phòng thể dục","hanViet":"THỂ DỤC QUÁN","lesson":28,"ex":[["学校の体育館で運動します。","Tôi tập thể dục ở phòng thể dục của trường."],["体育館は大きいです。","Phòng thể dục lớn."],["体育館でテニスをします。","Tôi chơi tennis ở phòng thể dục."],["子どもたちは体育館に集まります。","Bọn trẻ tập trung ở phòng thể dục."],["体育館で運動会があります。","Ở phòng thể dục có hội thao."]]},{"word":"無料","reading":"むりょう","meaning":"Miễn phí","hanViet":"VÔ LIỆU","lesson":28,"ex":[["この映画は無料です。","Bộ phim này miễn phí."],["公園は無料です。","Công viên miễn phí."],["この授業は無料です。","Buổi học này miễn phí."],["この本は無料です。","Cuốn sách này miễn phí."],["無料で見ることができます。","Có thể xem miễn phí."]]},{"word":"中央線","reading":"ちゅうおうせん","meaning":"Tuyến Chuo (đường sắt)","hanViet":"TRUNG ƯƠNG TUYẾN","lesson":28,"ex":[["中央線で東京へ行きます。","Tôi đi Tokyo bằng tuyến Chuo."],["中央線の電車に乗ります。","Tôi lên tàu tuyến Chuo."],["中央線は速いです。","Tuyến Chuo nhanh."],["中央線で会社へ行きます。","Tôi đi làm bằng tuyến Chuo."],["中央線の駅は近くにあります。","Ga tuyến Chuo ở gần đây."]]},{"word":"西荻窪駅","reading":"にしおぎくぼえき","meaning":"ga gần nhất, ga nishiogikubo","hanViet":"TÂY ĐỊCH OA DỊCH","lesson":28,"ex":[["西荻窪駅で降ります。","Tôi xuống ở ga Nishiogikubo."],["西荻窪駅は中央線の駅です。","Ga Nishiogikubo là ga của tuyến Chuo."],["西荻窪駅の近くに住んでいます。","Tôi sống gần ga Nishiogikubo."],["西荻窪駅から電車に乗ります。","Tôi lên tàu từ ga Nishiogikubo."],["西荻窪駅は小さい駅です。","Ga Nishiogikubo là ga nhỏ."]]},{"word":"家賃","reading":"やちん","meaning":"Tiền thuê nhà","hanViet":"GIA NHẪM","lesson":28,"ex":[["家賃は月に5万円です。","Tiền thuê nhà là 50.000 yên một tháng."],["家賃が高いです。","Tiền thuê nhà đắt."],["家賃を払います。","Tôi trả tiền thuê nhà."],["このマンションの家賃は安いです。","Tiền thuê của chung cư này rẻ."],["家賃は毎月1日に払います。","Tiền thuê nhà trả vào ngày 1 mỗi tháng."]]},{"word":"敷金","reading":"しききん","meaning":"tiền đặt cọc thuê nhà","hanViet":"PHU KIM","lesson":28,"ex":[["敷金は10万円です。","Tiền đặt cọc là 100.000 yên."],["敷金を払います。","Tôi trả tiền đặt cọc."],["このマンションの敷金は高いです。","Tiền đặt cọc của chung cư này cao."],["敷金は部屋を出るときに返してもらいます。","Tiền đặt cọc sẽ được trả lại khi tôi dọn ra khỏi phòng."],["敷金がありません。","Không có tiền đặt cọc."]]},{"word":"礼金","reading":"れいきん","meaning":"Tiền lễ (khi thuê nhà ở Nhật)","hanViet":"LỄ KIM","lesson":28,"ex":[["このアパートの礼金は3万円です。","Tiền lễ của căn hộ này là 30.000 yên."],["礼金がないアパートを探しています。","Tôi đang tìm căn hộ không có tiền lễ."],["家賃と礼金を払わなければなりません。","Tôi phải trả tiền thuê nhà và tiền lễ."],["礼金は家賃と同じです。","Tiền lễ bằng tiền thuê nhà."],["新しいアパートの礼金は高いです。","Tiền lễ của căn hộ mới đắt."]]},{"word":"管理費","reading":"かんりひ","meaning":"phí quản lí","hanViet":"QUẢN LÝ PHÍ","lesson":28,"ex":[["管理費は毎月5千円です。","Phí quản lí mỗi tháng là 5.000 yên."],["家賃は7万円で、管理費は5千円です。","Tiền thuê nhà là 70.000 yên, phí quản lí là 5.000 yên."],["管理費でエレベーターを直します。","Dùng phí quản lí để sửa thang máy."],["このアパートは管理費が安いです。","Căn hộ này phí quản lí rẻ."],["管理費を毎月払います。","Tôi trả phí quản lí hàng tháng."]]},{"word":"売れます","reading":"うれます","meaning":"bán","hanViet":"MẠI","lesson":28,"ex":[["この本はよく売れます。","Cuốn sách này bán rất chạy."],["冬はコートがよく売れます。","Mùa đông áo khoác bán rất chạy."],["この店のケーキは毎日売れます。","Bánh của cửa hàng này bán được mỗi ngày."],["新しい時計はあまり売れません。","Đồng hồ mới không bán chạy lắm."],["夏はアイスクリームがたくさん売れます。","Mùa hè kem bán được rất nhiều."]]},{"word":"メモします","reading":"メモします","meaning":"ghi chép lại,ghi lại","hanViet":"","lesson":28,"ex":[["先生の話をメモします。","Tôi ghi chép lại lời thầy giáo."],["電話番号をメモしました。","Tôi đã ghi lại số điện thoại."],["旅行の前に、持って行く物をメモします。","Trước chuyến đi, tôi ghi lại những đồ mang theo."],["大切なことをノートにメモします。","Tôi ghi những điều quan trọng vào sổ."],["会議で大切なことをメモしてください。","Hãy ghi lại những điều quan trọng trong cuộc họp."]]},{"word":"ガム","reading":"ガム","meaning":"kẹo cao su","hanViet":"","lesson":28,"ex":[["子どもはガムが好きです。","Trẻ con thích kẹo cao su."],["店でガムを3つ買いました。","Tôi đã mua 3 cái kẹo cao su ở cửa hàng."],["ガムは100円です。","Kẹo cao su giá 100 yên."],["母はガムが好きではありません。","Mẹ tôi không thích kẹo cao su."],["ガムをください。","Cho tôi kẹo cao su."]]},{"word":"ドラマ","reading":"ドラマ","meaning":"kịch,phim truyền hình","hanViet":"","lesson":28,"ex":[["毎週、金曜日にドラマを見ます。","Mỗi tuần, thứ sáu tôi xem phim truyền hình."],["日本のドラマが好きです。","Tôi thích phim truyền hình Nhật Bản."],["このドラマは有名です。","Bộ phim truyền hình này nổi tiếng."],["夜9時にドラマが始まります。","Phim truyền hình bắt đầu lúc 9 giờ tối."],["母とドラマを見ました。","Tôi đã xem phim truyền hình cùng mẹ."]]},{"word":"ホームステイ","reading":"ホームステイ","meaning":"homestay","hanViet":"","lesson":28,"ex":[["日本でホームステイをしました。","Tôi đã ở homestay ở Nhật Bản."],["ホームステイは楽しいです。","Homestay rất vui."],["来月、京都でホームステイをします。","Tháng sau tôi sẽ ở homestay ở Kyoto."],["ホームステイの家族はいい人です。","Gia đình homestay là người tốt."],["ホームステイで日本語を勉強しました。","Tôi đã học tiếng Nhật khi ở homestay."]]},{"word":"おしゃべりします","reading":"おしゃべりします","meaning":"trò chuyện","hanViet":"","lesson":28,"ex":[["友達とおしゃべりします。","Tôi trò chuyện với bạn."],["学校で友達とおしゃべりしました。","Tôi đã trò chuyện với bạn ở trường."],["母と電話でおしゃべりします。","Tôi trò chuyện với mẹ qua điện thoại."],["喫茶店で友達とおしゃべりしました。","Tôi đã trò chuyện với bạn ở quán cà phê."],["友達とおしゃべりするのは楽しいです。","Trò chuyện với bạn rất vui."]]},{"word":"土","reading":"ど","meaning":"thứ 7","hanViet":"THỔ","lesson":28,"ex":[["土は学校が休みです。","Thứ bảy trường nghỉ."],["土に友達に会います。","Thứ bảy tôi gặp bạn."],["土は店に行きます。","Thứ bảy tôi đi cửa hàng."],["土の午後、テニスをします。","Chiều thứ bảy tôi chơi tennis."],["土は家で休みます。","Thứ bảy tôi nghỉ ở nhà."]]},{"word":"「ちょっと」お願いがあるんですが","reading":"「ちょっと」おねがいがあるんですが","meaning":"tôi có chút việc muốn nhờ anh chị","hanViet":"NGUYỆN","lesson":28,"ex":[["「ちょっとお願いがあるんですが、時間がありますか。」","Tôi có chút việc muốn nhờ anh, anh có thời gian không?"],["「ちょっとお願いがあるんですが、手伝ってください。」","Tôi có chút việc muốn nhờ anh, hãy giúp tôi."],["先生に「ちょっとお願いがあるんですが」と言いました。","Tôi đã nói với thầy giáo: \"Tôi có chút việc muốn nhờ thầy\"."],["「ちょっとお願いがあるんですが、明日、会社を休んでもいいですか。」","Tôi có chút việc muốn nhờ anh, ngày mai tôi nghỉ làm có được không?"],["友達に「ちょっとお願いがあるんですが」と言って、電話を借りました。","Tôi đã nói với bạn: \"Tôi có chút việc muốn nhờ cậu\", rồi mượn điện thoại."]]},{"word":"ボーナス","reading":"ボーナス","meaning":"thưởng","hanViet":"","lesson":28,"ex":[["冬にボーナスをもらいました。","Mùa đông tôi đã nhận thưởng."],["ボーナスで新しい時計を買いました。","Tôi đã mua đồng hồ mới bằng tiền thưởng."],["ボーナスは20万円です。","Tiền thưởng là 200.000 yên."],["会社からボーナスをもらいます。","Tôi nhận thưởng từ công ty."],["ボーナスで旅行をします。","Tôi đi du lịch bằng tiền thưởng."]]},{"word":"開きます","reading":"あきます","meaning":"mở (cửa)","hanViet":"KHAI","lesson":29,"ex":[["ドアが開きます。","Cửa mở."],["窓が開きました。","Cửa sổ đã mở."],["店は9時に開きます。","Cửa hàng mở cửa lúc 9 giờ."],["図書館は8時に開きます。","Thư viện mở cửa lúc 8 giờ."],["このドアは開きません。","Cánh cửa này không mở."]]},{"word":"閉まります","reading":"しまります","meaning":"đóng(cửa)","hanViet":"BẾ","lesson":29,"ex":[["夜、ドアが閉まります。","Buổi tối cửa đóng."],["窓が閉まりました。","Cửa sổ đã đóng."],["店は夜9時に閉まります。","Cửa hàng đóng cửa lúc 9 giờ tối."],["電車のドアが閉まります。","Cửa tàu điện đóng."],["寒いので、窓が閉まっています。","Vì lạnh nên cửa sổ đóng kín."]]},{"word":"つきます","reading":"つきます","meaning":"bật,thắp sáng(đèn)","hanViet":"","lesson":29,"ex":[["電気がつきます。","Đèn bật sáng."],["夜、部屋の電気がつきます。","Buổi tối đèn trong phòng bật sáng."],["部屋に入ると、電気がつきます。","Khi vào phòng, đèn bật sáng."],["町の電気がつきました。","Đèn trong thị trấn đã bật sáng."],["電気がつきません。","Đèn không bật."]]},{"word":"消えます","reading":"きえます","meaning":"Tắt, biến mất","hanViet":"TIÊU","lesson":29,"ex":[["電気が消えます。","Đèn tắt."],["夜、部屋の電気が消えました。","Buổi tối đèn trong phòng đã tắt."],["星が消えました。","Ngôi sao đã biến mất."],["雪が消えました。","Tuyết đã tan hết."],["電気が消えません。","Đèn không tắt."]]},{"word":"込みます","reading":"こみます","meaning":"đông(đường)","hanViet":"","lesson":29,"ex":[["朝、電車が込みます。","Buổi sáng tàu điện đông."],["雨の日は道が込みます。","Ngày mưa đường đông."],["日曜日に店が込みます。","Chủ nhật cửa hàng đông."],["朝、バスが込みます。","Buổi sáng xe buýt đông."],["昼、レストランが込みます。","Buổi trưa nhà hàng đông."]]},{"word":"すきます","reading":"すきます","meaning":"vắng(đường)","hanViet":"","lesson":29,"ex":[["夜、電車がすきます。","Buổi tối tàu điện vắng."],["朝早く、道がすきます。","Sáng sớm đường vắng."],["平日、店がすきます。","Ngày thường cửa hàng vắng."],["夜、バスがすきます。","Buổi tối xe buýt vắng."],["午後、レストランがすきます。","Buổi chiều nhà hàng vắng."]]},{"word":"壊れます","reading":"こわれます","meaning":"bị hỏng, bị vỡ","hanViet":"HOẠI","lesson":29,"ex":[["テレビが壊れました。","Ti vi đã bị hỏng."],["パソコンが壊れて、仕事ができません。","Máy tính hỏng nên tôi không làm việc được."],["時計が壊れたから、新しい時計を買いました。","Vì đồng hồ hỏng nên tôi đã mua đồng hồ mới."],["自転車が壊れました。","Xe đạp đã bị hỏng."],["車が壊れて、会社に遅れました。","Xe ô tô hỏng nên tôi đến công ty muộn."]]},{"word":"割れます","reading":"われます","meaning":"vỡ(cốc)","hanViet":"CÁT","lesson":29,"ex":[["コップが割れました。","Cốc đã vỡ."],["卵が割れました。","Trứng đã vỡ."],["鏡が割れました。","Gương đã vỡ."],["窓のガラスが割れました。","Kính cửa sổ đã vỡ."],["コップを落として、割れました。","Tôi làm rơi cốc nên nó đã vỡ."]]},{"word":"折れます","reading":"おれます","meaning":"Bị gãy, gập lại","hanViet":"TRIẾT","lesson":29,"ex":[["木の枝が折れました。","Cành cây đã gãy."],["鉛筆が折れました。","Bút chì đã gãy."],["傘が折れました。","Ô đã gãy."],["紙が折れます。","Giấy gấp lại được."],["強い風で、木が折れました。","Gió mạnh làm cây gãy."]]},{"word":"破れます","reading":"やぶれます","meaning":"rách(giấy)","hanViet":"PHÁ","lesson":29,"ex":[["紙が破れました。","Giấy đã rách."],["服が破れました。","Quần áo đã rách."],["袋が破れました。","Túi đã rách."],["シャツが破れました。","Áo sơ mi đã rách."],["本が破れました。","Sách đã rách."]]},{"word":"汚れます","reading":"よごれます","meaning":"Bị bẩn, bị dơ","hanViet":"Ô","lesson":29,"ex":[["服が汚れました。","Quần áo đã bị bẩn."],["靴が汚れました。","Giày đã bị bẩn."],["雨で車が汚れました。","Mưa làm xe ô tô bị bẩn."],["子どもは服が汚れます。","Quần áo của trẻ con hay bị bẩn."],["白いシャツが汚れました。","Áo sơ mi trắng đã bị bẩn."]]},{"word":"付きます","reading":"つきます","meaning":"Dính vào, đi kèm","hanViet":"PHÓ","lesson":29,"ex":[["この時計に電池が付いています。","Đồng hồ này có kèm pin."],["服にボタンが付いています。","Quần áo có nút."],["かばんにポケットが付いています。","Túi có ngăn."],["この部屋にエアコンが付いています。","Phòng này có điều hòa."],["この本にDVDが付いています。","Cuốn sách này có kèm DVD."]]},{"word":"外れます","reading":"はずれます","meaning":"tuột,bung,rời ra(sút nút)","hanViet":"NGOẠI","lesson":29,"ex":[["服のボタンが外れました。","Nút áo đã bị tuột."],["シャツのボタンが外れました。","Nút áo sơ mi đã bị tuột."],["時計の針が外れました。","Kim đồng hồ đã bị rời ra."],["ボタンが外れて、困りました。","Nút bị tuột nên tôi gặp rắc rối."],["ズボンのボタンが外れました。","Nút quần đã bị tuột."]]},{"word":"止まります","reading":"とまります","meaning":"Dừng lại","hanViet":"CHỈ","lesson":29,"ex":[["電車が駅で止まります。","Tàu điện dừng ở ga."],["バスが止まりました。","Xe buýt đã dừng lại."],["雨が止まりました。","Mưa đã tạnh."],["時計が止まりました。","Đồng hồ đã dừng."],["車が信号で止まりました。","Xe ô tô đã dừng ở đèn tín hiệu."]]},{"word":"まちがえます","reading":"まちがえます","meaning":"nhầm lẫn,sai","hanViet":"","lesson":29,"ex":[["電話番号をまちがえました。","Tôi đã nhầm số điện thoại."],["道をまちがえました。","Tôi đã nhầm đường."],["答えをまちがえました。","Tôi đã trả lời sai."],["名前をまちがえました。","Tôi đã nhầm tên."],["時間をまちがえました。","Tôi đã nhầm giờ."]]},{"word":"落とします","reading":"おとします","meaning":"làm rơi, đánh rơi","hanViet":"LẠC","lesson":29,"ex":[["財布を落としました。","Tôi đã đánh rơi ví tiền."],["電車でかばんを落としました。","Tôi đã đánh rơi túi trên tàu điện."],["電話を落として、壊れました。","Tôi làm rơi điện thoại nên nó đã hỏng."],["傘を落としました。","Tôi đã đánh rơi ô."],["本を落としました。","Tôi đã đánh rơi sách."]]},{"word":"掛かります","reading":"かかります","meaning":"Được treo; tốn (thời gian, tiền)","hanViet":"QUÁI","lesson":29,"ex":[["壁に絵が掛かっています。","Tranh được treo trên tường."],["東京まで2時間掛かります。","Đến Tokyo mất 2 tiếng."],["お金が掛かります。","Tốn tiền."],["この部屋にカレンダーが掛かっています。","Lịch được treo trong phòng này."],["仕事に時間が掛かります。","Công việc tốn thời gian."]]},{"word":"皿","reading":"さら","meaning":"Đĩa, dĩa","hanViet":"MÃNH","lesson":29,"ex":[["皿を洗います。","Tôi rửa đĩa."],["皿に肉を入れます。","Tôi cho thịt vào đĩa."],["皿を5つ買いました。","Tôi đã mua 5 cái đĩa."],["白い皿を使います。","Tôi dùng đĩa trắng."],["皿が割れました。","Đĩa đã vỡ."]]},{"word":"ちゃわん","reading":"ちゃわん","meaning":"cái bát","hanViet":"","lesson":29,"ex":[["ちゃわんにごはんを入れます。","Tôi cho cơm vào bát."],["ちゃわんを洗います。","Tôi rửa bát."],["ちゃわんが割れました。","Bát đã vỡ."],["ちゃわんを3つ買いました。","Tôi đã mua 3 cái bát."],["ちゃわんにみそ汁を入れます。","Tôi cho canh miso vào bát."]]},{"word":"袋","reading":"ふくろ","meaning":"Túi, bao","hanViet":"ĐÁI","lesson":29,"ex":[["袋に本を入れます。","Tôi cho sách vào túi."],["袋は大きいです。","Túi lớn."],["袋にりんごが入っています。","Trong túi có táo."],["袋を買いました。","Tôi đã mua túi."],["袋を持っています。","Tôi mang túi."]]},{"word":"財布","reading":"さいふ","meaning":"ví tiền","hanViet":"TÀI BỐ","lesson":29,"ex":[["財布は小さいです。","Ví tiền nhỏ."],["財布にお金が入っています。","Trong ví có tiền."],["新しい財布を買いました。","Tôi đã mua ví tiền mới."],["財布を忘れました。","Tôi đã quên ví tiền."],["財布はかばんの中にあります。","Ví tiền ở trong túi."]]},{"word":"枝","reading":"えだ","meaning":"Cành cây","hanViet":"CHI","lesson":29,"ex":[["木の枝は長いです。","Cành cây dài."],["枝に葉が付いています。","Trên cành có lá."],["枝を切りました。","Tôi đã cắt cành cây."],["強い風で枝が折れました。","Gió mạnh làm cành cây gãy."],["枝が曲がっています。","Cành cây cong."]]},{"word":"この辺","reading":"このへん","meaning":"Quanh đây, khu vực này","hanViet":"THỬ BIÊN","lesson":29,"ex":[["この辺は静かです。","Quanh đây yên tĩnh."],["この辺に店があります。","Quanh đây có cửa hàng."],["この辺は便利です。","Quanh đây tiện lợi."],["この辺に公園があります。","Quanh đây có công viên."],["この辺は安全です。","Quanh đây an toàn."]]},{"word":"～辺","reading":"～へん","meaning":"xung quanh ~, chỗ ~","hanViet":"BIÊN","lesson":29,"ex":[["東京の辺はにぎやかです。","Xung quanh Tokyo náo nhiệt."],["駅の辺に店があります。","Xung quanh ga có cửa hàng."],["海の辺に家があります。","Quanh biển có nhà."],["山の辺は静かです。","Xung quanh núi yên tĩnh."],["学校の辺に公園があります。","Xung quanh trường học có công viên."]]},{"word":"このくらい","reading":"このくらい","meaning":"cỡ tầm này,cỡ chừng này","hanViet":"","lesson":29,"ex":[["このくらいの大きさがいいです。","Cỡ tầm này là tốt."],["このくらいのお金がかかります。","Tốn cỡ chừng này tiền."],["このくらいの時間でできます。","Làm được trong cỡ chừng này thời gian."],["このくらいの大きさの本がほしいです。","Tôi muốn cuốn sách cỡ tầm này."],["このくらいでいいです。","Cỡ tầm này là được."]]},{"word":"お先にどうぞ。","reading":"おさきにどうぞ","meaning":"mời anh/chị cứ về trước","hanViet":"TIÊN","lesson":29,"ex":[["「お先にどうぞ。」と言いました。","Tôi đã nói: \"Mời anh cứ về trước\"."],["田中さんに「お先にどうぞ。」と言いました。","Tôi đã nói với anh Tanaka: \"Mời anh cứ về trước\"."],["「お先にどうぞ。私はあとで帰ります。」","Mời anh cứ về trước. Tôi sẽ về sau."],["先生に「お先にどうぞ。」と言いました。","Tôi đã nói với thầy giáo: \"Mời thầy cứ về trước\"."],["友達が「お先にどうぞ。」と言いました。","Bạn tôi đã nói: \"Mời cậu cứ về trước\"."]]},{"word":"よかった。","reading":"よかった","meaning":"ồ, may quá.","hanViet":"","lesson":29,"ex":[["「よかった。」と言いました。","Tôi đã nói: \"May quá\"."],["雨が止まりました。よかった。","Mưa đã tạnh. May quá."],["財布が見つかりました。よかった。","Tìm thấy ví tiền rồi. May quá."],["「よかった。ありがとうございます。」","May quá. Cảm ơn anh."],["電車に間に合いました。よかった。","Tôi đã kịp tàu điện. May quá."]]},{"word":"確か","reading":"たしか","meaning":"chắc là","hanViet":"XÁC","lesson":29,"ex":[["確かあの店は9時に開きます。","Chắc là cửa hàng đó mở cửa lúc 9 giờ."],["確か田中さんは東京に住んでいます。","Chắc là anh Tanaka sống ở Tokyo."],["確か明日は休みです。","Chắc là ngày mai được nghỉ."],["確かこの本は高いです。","Chắc là cuốn sách này đắt."],["確か電車は10時に来ます。","Chắc là tàu điện đến lúc 10 giờ."]]},{"word":"網棚","reading":"あみだな","meaning":"giá để hành lý","hanViet":"VÕNG BẰNG","lesson":29,"ex":[["網棚にかばんを置きます。","Tôi để túi lên giá để hành lý."],["網棚に荷物があります。","Trên giá để hành lý có hành lý."],["網棚からかばんを取りました。","Tôi đã lấy túi từ giá để hành lý."],["網棚にコートを置きました。","Tôi đã để áo khoác lên giá để hành lý."],["網棚は電車の上にあります。","Giá để hành lý ở phía trên tàu điện."]]},{"word":"地震","reading":"じしん","meaning":"Động đất","hanViet":"ĐỊA CHẤN","lesson":29,"ex":[["地震がありました。","Đã có động đất."],["きのう、地震がありました。","Hôm qua đã có động đất."],["地震は危険です。","Động đất nguy hiểm."],["地震で家が壊れました。","Động đất làm nhà bị hỏng."],["地震のとき、外へ出ます。","Khi động đất, tôi ra ngoài."]]},{"word":"壁","reading":"かべ","meaning":"Bức tường","hanViet":"BÍCH","lesson":29,"ex":[["壁は白いです。","Tường màu trắng."],["壁にポスターをはります。","Tôi dán áp phích lên tường."],["壁をふきます。","Tôi lau tường."],["壁に時計が掛かっています。","Đồng hồ được treo trên tường."],["壁に写真を飾ります。","Tôi trưng bày ảnh trên tường."]]},{"word":"指します","reading":"さします","meaning":"Chỉ, trỏ","hanViet":"CHỈ","lesson":29,"ex":[["地図を指します。","Tôi chỉ vào bản đồ."],["先生は絵を指しました。","Thầy giáo đã chỉ vào tranh."],["地図で東京を指します。","Tôi chỉ vào Tokyo trên bản đồ."],["子どもは犬を指しました。","Đứa trẻ đã chỉ vào con chó."],["時計を指します。","Tôi chỉ vào đồng hồ."]]},{"word":"針","reading":"はり","meaning":"Kim (may, tiêm, đồng hồ)","hanViet":"CHÂM","lesson":29,"ex":[["針は小さいです。","Kim nhỏ."],["時計の針は細いです。","Kim đồng hồ mảnh."],["針を買いました。","Tôi đã mua kim."],["針が落ちました。","Kim đã rơi."],["針が見えません。","Không nhìn thấy kim."]]},{"word":"倒れます","reading":"たおれます","meaning":"ngã xuống, sụp đổ","hanViet":"ĐẢO","lesson":29,"ex":[["木が倒れました。","Cây đã ngã xuống."],["強い風で木が倒れました。","Gió mạnh làm cây ngã xuống."],["自転車が倒れました。","Xe đạp đã ngã xuống."],["地震で家が倒れました。","Động đất làm nhà sụp đổ."],["子どもが倒れました。","Đứa trẻ đã ngã xuống."]]},{"word":"方","reading":"ほう","meaning":"hướng, phương hướng","hanViet":"PHƯƠNG","lesson":29,"ex":[["西の方は山です。","Phía tây là núi."],["東の方は海です。","Phía đông là biển."],["右の方に公園があります。","Phía bên phải có công viên."],["左の方に学校があります。","Phía bên trái có trường học."],["どちらの方ですか。","Là phía nào?"]]},{"word":"太っている","reading":"ふとっている","meaning":"béo","hanViet":"THÁI","lesson":29,"ex":[["あの人は太っています。","Người đó béo."],["猫が太っています。","Con mèo béo."],["犬が太っています。","Con chó béo."],["弟は太っています。","Em trai tôi béo."],["太っている人は元気です。","Người béo khỏe mạnh."]]},{"word":"やせている","reading":"やせている","meaning":"gầy","hanViet":"","lesson":29,"ex":[["あの人はやせています。","Người đó gầy."],["猫がやせています。","Con mèo gầy."],["犬がやせています。","Con chó gầy."],["弟はやせています。","Em trai tôi gầy."],["やせている人は元気です。","Người gầy khỏe mạnh."]]},{"word":"膨らんでいる","reading":"ふくらんでいる","meaning":"phồng","hanViet":"BÀNH","lesson":29,"ex":[["袋が膨らんでいます。","Túi phồng lên."],["顔が膨らんでいます。","Mặt sưng phồng."],["パンが膨らんでいます。","Bánh mì phồng lên."],["おなかが膨らんでいます。","Bụng phồng lên."],["紙の袋が膨らんでいます。","Túi giấy phồng lên."]]},{"word":"穴が開いている","reading":"あながあいている","meaning":"thủng lỗ","hanViet":"HUYỆT KHAI","lesson":29,"ex":[["靴下に穴が開いています。","Tất bị thủng lỗ."],["服に穴が開いています。","Quần áo bị thủng lỗ."],["壁に穴が開いています。","Tường bị thủng lỗ."],["袋に穴が開いています。","Túi bị thủng lỗ."],["紙に穴が開いています。","Giấy bị thủng lỗ."]]},{"word":"曲がっている","reading":"まがっている","meaning":"cong","hanViet":"KHÚC","lesson":29,"ex":[["道が曲がっています。","Đường cong."],["木が曲がっています。","Cây cong."],["針が曲がっています。","Kim cong."],["傘が曲がっています。","Ô cong."],["鉛筆が曲がっています。","Bút chì cong."]]},{"word":"ゆがんでいる","reading":"ゆがんでいる","meaning":"méo","hanViet":"","lesson":29,"ex":[["写真がゆがんでいます。","Bức ảnh bị méo."],["鏡がゆがんでいます。","Gương bị méo."],["絵がゆがんでいます。","Tranh bị méo."],["顔がゆがんでいます。","Mặt bị méo."],["時計がゆがんでいます。","Đồng hồ bị méo."]]},{"word":"へこんでいる","reading":"へこんでいる","meaning":"lõm","hanViet":"","lesson":29,"ex":[["車がへこんでいます。","Xe ô tô bị lõm."],["缶がへこんでいます。","Lon bị lõm."],["ボールがへこんでいます。","Quả bóng bị lõm."],["壁がへこんでいます。","Tường bị lõm."],["帽子がへこんでいます。","Mũ bị lõm."]]},{"word":"ねじれている","reading":"ねじれている","meaning":"xoắn","hanViet":"","lesson":29,"ex":[["タオルがねじれています。","Khăn bị xoắn."],["服がねじれています。","Quần áo bị xoắn."],["木がねじれています。","Cây bị xoắn."],["枝がねじれています。","Cành cây bị xoắn."],["紙がねじれています。","Giấy bị xoắn."]]},{"word":"欠けている","reading":"かけている","meaning":"sứt","hanViet":"KHIẾM","lesson":29,"ex":[["コップが欠けています。","Cốc bị sứt."],["皿が欠けています。","Đĩa bị sứt."],["ちゃわんが欠けています。","Bát bị sứt."],["ガラスが欠けています。","Ly bị sứt."],["歯が欠けています。","Răng bị sứt."]]},{"word":"ひびが入っている","reading":"ひびがはいっている","meaning":"nứt","hanViet":"NHẬP","lesson":29,"ex":[["コップにひびが入っています。","Cốc bị nứt."],["皿にひびが入っています。","Đĩa bị nứt."],["壁にひびが入っています。","Tường bị nứt."],["ガラスにひびが入っています。","Ly bị nứt."],["鏡にひびが入っています。","Gương bị nứt."]]},{"word":"腐っている","reading":"くさっている","meaning":"thiu","hanViet":"HỦ","lesson":29,"ex":[["肉が腐っています。","Thịt bị thiu."],["魚が腐っています。","Cá bị thiu."],["牛乳が腐っています。","Sữa bị thiu."],["パンが腐っています。","Bánh mì bị thiu."],["野菜が腐っています。","Rau bị thiu."]]},{"word":"乾いている","reading":"かわいている","meaning":"khô","hanViet":"CAN","lesson":29,"ex":[["服が乾いています。","Quần áo đã khô."],["タオルが乾いています。","Khăn đã khô."],["紙が乾いています。","Giấy đã khô."],["髪が乾いています。","Tóc đã khô."],["道が乾いています。","Đường đã khô."]]},{"word":"ぬれている","reading":"ぬれている","meaning":"ướt","hanViet":"","lesson":29,"ex":[["服がぬれています。","Quần áo bị ướt."],["靴がぬれています。","Giày bị ướt."],["髪がぬれています。","Tóc bị ướt."],["道がぬれています。","Đường bị ướt."],["紙がぬれています。","Giấy bị ướt."]]},{"word":"凍っている","reading":"こおっている","meaning":"đóng băng","hanViet":"ĐÔNG","lesson":29,"ex":[["水が凍っています。","Nước đóng băng."],["池の水が凍っています。","Nước trong ao đóng băng."],["道が凍っています。","Đường đóng băng."],["川が凍っています。","Sông đóng băng."],["窓が凍っています。","Cửa sổ đóng băng."]]},{"word":"とりかえます","reading":"とりかえます","meaning":"thay(pin)","hanViet":"","lesson":29,"ex":[["電池をとりかえます。","Tôi thay pin."],["時計の電池をとりかえました。","Tôi đã thay pin đồng hồ."],["電池をとりかえてください。","Hãy thay pin."],["古い電池を新しい電池にとりかえます。","Tôi thay pin cũ bằng pin mới."],["ラジオの電池をとりかえました。","Tôi đã thay pin đài."]]},{"word":"コップ","reading":"コップ","meaning":"cốc","hanViet":"","lesson":29,"ex":[["コップに水を入れます。","Tôi cho nước vào cốc."],["コップは大きいです。","Cốc lớn."],["コップを3つ買いました。","Tôi đã mua 3 cái cốc."],["コップにジュースを入れます。","Tôi cho nước ép vào cốc."],["コップを洗います。","Tôi rửa cốc."]]},{"word":"ガラス","reading":"ガラス","meaning":"ly","hanViet":"","lesson":29,"ex":[["ガラスに水を入れます。","Tôi cho nước vào ly."],["ガラスが割れました。","Ly đã vỡ."],["ガラスを2つ買いました。","Tôi đã mua 2 cái ly."],["ガラスにビールを入れます。","Tôi cho bia vào ly."],["ガラスを洗います。","Tôi rửa ly."]]},{"word":"駅員","reading":"えきいん","meaning":"nhân viên nhà ga","hanViet":"DỊCH VIÊN","lesson":29,"ex":[["駅員に道を聞きました。","Tôi đã hỏi đường nhân viên nhà ga."],["駅員から切符を買いました。","Tôi đã mua vé từ nhân viên nhà ga."],["駅員はいい人です。","Nhân viên nhà ga là người tốt."],["駅員が忘れ物を探します。","Nhân viên nhà ga tìm đồ bỏ quên."],["駅員に電車の時間を聞きました。","Tôi đã hỏi nhân viên nhà ga giờ tàu điện."]]},{"word":"スピーチ","reading":"スピーチ","meaning":"diễn văn","hanViet":"","lesson":29,"ex":[["学校でスピーチをしました。","Tôi đã diễn thuyết ở trường."],["スピーチは難しいです。","Diễn thuyết khó."],["日本語でスピーチをします。","Tôi diễn thuyết bằng tiếng Nhật."],["先生のスピーチを聞きました。","Tôi đã nghe diễn văn của thầy giáo."],["明日、スピーチをします。","Ngày mai tôi sẽ diễn thuyết."]]},{"word":"返事","reading":"へんじ","meaning":"trả lời","hanViet":"PHẢN SỰ","lesson":29,"ex":[["友達に返事を書きました。","Tôi đã viết thư trả lời cho bạn."],["返事をもらいました。","Tôi đã nhận được trả lời."],["先生に返事をしました。","Tôi đã trả lời thầy giáo."],["返事が遅れました。","Trả lời bị muộn."],["返事を待っています。","Tôi đang chờ trả lời."]]},{"word":"源氏物語","reading":"げんじものがたり","meaning":"tiểu thuyết được viết thời heian","hanViet":"NGUYÊN THỊ VẬT NGỮ","lesson":29,"ex":[["源氏物語は有名な本です。","Truyện Genji là cuốn sách nổi tiếng."],["源氏物語は昔の日本の本です。","Truyện Genji là cuốn sách Nhật Bản xưa."],["源氏物語を読みました。","Tôi đã đọc Truyện Genji."],["源氏物語は長い本です。","Truyện Genji là cuốn sách dài."],["先生は源氏物語が好きです。","Thầy giáo thích Truyện Genji."]]},{"word":"今の電車","reading":"いまのでんしゃ","meaning":"tàu điện vừa chạy","hanViet":"KIM ĐIỆN XA","lesson":29,"ex":[["今の電車に乗れませんでした。","Tôi đã không kịp lên tàu điện vừa chạy."],["今の電車に忘れ物をしました。","Tôi đã bỏ quên đồ trên tàu điện vừa chạy."],["今の電車はどこへ行きましたか。","Tàu điện vừa chạy đã đi đâu?"],["今の電車は速かったです。","Tàu điện vừa chạy nhanh."],["今の電車に人がたくさんいました。","Trên tàu điện vừa chạy có rất nhiều người."]]},{"word":"忘れ物","reading":"わすれもの","meaning":"đồ bỏ quên","hanViet":"VONG VẬT","lesson":29,"ex":[["電車に忘れ物をしました。","Tôi đã bỏ quên đồ trên tàu điện."],["学校に忘れ物をしました。","Tôi đã bỏ quên đồ ở trường."],["忘れ物を探しています。","Tôi đang tìm đồ bỏ quên."],["駅で忘れ物を取りました。","Tôi đã lấy đồ bỏ quên ở ga."],["忘れ物は駅にあります。","Đồ bỏ quên ở ga."]]},{"word":"側","reading":"がわ","meaning":"phía…","hanViet":"TRẮC","lesson":29,"ex":[["道の右側に店があります。","Phía bên phải đường có cửa hàng."],["川の向こう側に山があります。","Phía bên kia sông có núi."],["こちらの側に来てください。","Hãy đến phía bên này."],["左側に公園があります。","Phía bên trái có công viên."],["駅の側にホテルがあります。","Gần ga có khách sạn."]]},{"word":"覚えていません","reading":"おぼえていません","meaning":"tôi không nhớ","hanViet":"GIÁC","lesson":29,"ex":[["名前を覚えていません。","Tôi không nhớ tên."],["電話番号を覚えていません。","Tôi không nhớ số điện thoại."],["彼の名前を覚えていません。","Tôi không nhớ tên anh ấy."],["あの人の顔を覚えていません。","Tôi không nhớ mặt người đó."],["きのうのことを覚えていません。","Tôi không nhớ chuyện hôm qua."]]},{"word":"ああ、よかった","reading":"ああ、よかった","meaning":"ôi, may quá","hanViet":"","lesson":29,"ex":[["「ああ、よかった。」と言いました。","Tôi đã nói: \"Ôi, may quá\"."],["財布が見つかって、ああ、よかった。","Tìm thấy ví tiền, ôi may quá."],["雨が止まって、ああ、よかった。","Mưa tạnh, ôi may quá."],["「ああ、よかった。ありがとうございます。」","Ôi, may quá. Cảm ơn anh."],["電車に間に合って、ああ、よかった。","Kịp tàu điện, ôi may quá."]]},{"word":"駅前","reading":"えきまえ","meaning":"khu vực trước nhà ga","hanViet":"DỊCH TIỀN","lesson":29,"ex":[["駅前に店があります。","Trước ga có cửa hàng."],["駅前に公園があります。","Trước ga có công viên."],["駅前で友達に会いました。","Tôi đã gặp bạn trước ga."],["駅前はにぎやかです。","Trước ga náo nhiệt."],["駅前にホテルがあります。","Trước ga có khách sạn."]]},{"word":"西の方","reading":"にしのほう","meaning":"phía tây","hanViet":"TÂY PHƯƠNG","lesson":29,"ex":[["西の方は山が多いです。","Phía tây có nhiều núi."],["西の方に海があります。","Phía tây có biển."],["西の方へ行きます。","Tôi đi về phía tây."],["西の方は静かです。","Phía tây yên tĩnh."],["西の方に公園があります。","Phía tây có công viên."]]},{"word":"ふきます","reading":"ふきます","meaning":"lau(cửa)","hanViet":"","lesson":29,"ex":[["窓をふきます。","Tôi lau cửa sổ."],["机をふきます。","Tôi lau bàn."],["ドアをふきます。","Tôi lau cửa."],["顔をふきます。","Tôi lau mặt."],["手をふきます。","Tôi lau tay."]]},{"word":"はります","reading":"はります","meaning":"dán","hanViet":"","lesson":30,"ex":[["ポスターをはります。","Tôi dán áp phích."],["紙をはります。","Tôi dán giấy."],["壁に写真をはります。","Tôi dán ảnh lên tường."],["カレンダーをはります。","Tôi dán lịch."],["切手をはります。","Tôi dán tem."]]},{"word":"掛けます","reading":"かけます","meaning":"Treo; gọi (điện thoại); đeo (kính)","hanViet":"QUÁI","lesson":30,"ex":[["壁に絵を掛けます。","Tôi treo tranh lên tường."],["友達に電話を掛けます。","Tôi gọi điện cho bạn."],["眼鏡を掛けます。","Tôi đeo kính."],["壁に時計を掛けます。","Tôi treo đồng hồ lên tường."],["コートを掛けます。","Tôi treo áo khoác."]]},{"word":"飾ります","reading":"かざります","meaning":"Trang trí, trưng bày","hanViet":"SỨC","lesson":30,"ex":[["部屋に花を飾ります。","Tôi trang trí hoa trong phòng."],["壁に絵を飾ります。","Tôi trưng bày tranh trên tường."],["机に写真を飾ります。","Tôi trưng bày ảnh trên bàn."],["部屋を飾ります。","Tôi trang trí phòng."],["家に花を飾りました。","Tôi đã trang trí hoa trong nhà."]]},{"word":"並べます","reading":"ならべます","meaning":"Sắp xếp, bày thành hàng","hanViet":"TỊNH","lesson":30,"ex":[["本を並べます。","Tôi xếp sách thành hàng."],["机に本を並べます。","Tôi bày sách trên bàn."],["皿を並べます。","Tôi bày đĩa thành hàng."],["靴を並べます。","Tôi xếp giày thành hàng."],["花を並べます。","Tôi bày hoa thành hàng."]]},{"word":"植えます","reading":"うえます","meaning":"Trồng (cây)","hanViet":"THỰC","lesson":30,"ex":[["庭に木を植えます。","Tôi trồng cây trong vườn."],["花を植えます。","Tôi trồng hoa."],["桜を植えました。","Tôi đã trồng hoa anh đào."],["庭に花を植えます。","Tôi trồng hoa trong vườn."],["野菜を植えます。","Tôi trồng rau."]]},{"word":"戻します","reading":"もどします","meaning":"Đưa về, trả lại chỗ cũ","hanViet":"LỆ","lesson":30,"ex":[["本を元の所に戻します。","Tôi trả sách về chỗ cũ."],["借りた辞書を友達に戻しました。","Tôi đã trả từ điển đã mượn cho bạn."],["いすを元の所に戻してください。","Xin hãy trả ghế về chỗ cũ."],["お金を財布に戻します。","Tôi bỏ tiền lại vào ví."],["鍵をかばんに戻しました。","Tôi đã bỏ chìa khóa lại vào túi."]]},{"word":"まとめます","reading":"まとめます","meaning":"nhóm lại, tóm tắt","hanViet":"","lesson":30,"ex":[["先生の話をノートにまとめます。","Tôi tóm tắt lời thầy giáo vào vở."],["本を一つの箱にまとめました。","Tôi đã gom sách vào một cái hộp."],["みんなの意見をまとめます。","Tôi tổng hợp ý kiến của mọi người."],["宿題の答えをまとめます。","Tôi tổng hợp đáp án của bài tập về nhà."],["旅行の写真を一冊の本にまとめました。","Tôi đã gom ảnh du lịch thành một cuốn sách."]]},{"word":"片づけます","reading":"かたづけます","meaning":"dọn dẹp, sắp xếp","hanViet":"PHIẾN","lesson":30,"ex":[["部屋を片づけます。","Tôi dọn dẹp phòng."],["ごはんの後で、机の上を片づけました。","Sau bữa cơm, tôi đã dọn mặt bàn."],["母は毎朝、台所を片づけます。","Mẹ tôi dọn bếp mỗi buổi sáng."],["本を片づけてから、寝ます。","Tôi dọn sách xong rồi mới đi ngủ."],["仕事の後で、机を片づけます。","Sau giờ làm việc, tôi dọn bàn làm việc."]]},{"word":"しまいます","reading":"しまいます","meaning":"cất vào, để vào","hanViet":"","lesson":30,"ex":[["本をかばんにしまいます。","Tôi cất sách vào túi."],["服を引き出しにしまいました。","Tôi đã cất quần áo vào ngăn kéo."],["冬の服を箱にしまいます。","Tôi cất quần áo mùa đông vào hộp."],["お金を財布にしまいます。","Tôi cất tiền vào ví."],["鍵をかばんにしまいました。","Tôi đã cất chìa khóa vào túi."]]},{"word":"決めます","reading":"きめます","meaning":"Quyết định (chủ động)","hanViet":"QUYẾT","lesson":30,"ex":[["旅行の日を決めます。","Tôi quyết định ngày đi du lịch."],["あした、何を食べるか決めました。","Tôi đã quyết định ngày mai ăn gì."],["先生はテストの日を決めました。","Thầy giáo đã quyết định ngày kiểm tra."],["家族で旅行に行く所を決めます。","Cả nhà cùng quyết định nơi đi du lịch."],["もう決めましたか。","Bạn đã quyết định chưa?"]]},{"word":"知らせます","reading":"しらせます","meaning":"Thông báo, cho biết","hanViet":"TRI","lesson":30,"ex":[["母に電話で知らせます。","Tôi báo cho mẹ bằng điện thoại."],["会議の時間をみんなに知らせました。","Tôi đã thông báo giờ họp cho mọi người."],["旅行の日を友達に知らせます。","Tôi báo ngày đi du lịch cho bạn."],["電話番号が変わりましたから、友達に知らせます。","Vì số điện thoại đã đổi nên tôi báo cho bạn."],["先生は休みの日を学生に知らせました。","Thầy giáo đã thông báo ngày nghỉ cho học sinh."]]},{"word":"相談します","reading":"そうだんします","meaning":"trao đổi, bàn bạc, tư vấn","hanViet":"TƯƠNG ĐÀM","lesson":30,"ex":[["先生に勉強のことを相談します。","Tôi hỏi ý kiến thầy giáo về việc học."],["友達と旅行のことを相談しました。","Tôi đã bàn bạc với bạn về chuyến du lịch."],["母に仕事のことを相談します。","Tôi hỏi ý kiến mẹ về công việc."],["わからないときは、先生に相談してください。","Khi không hiểu, xin hãy hỏi ý kiến thầy giáo."],["兄に仕事のことを相談しました。","Tôi đã hỏi ý kiến anh trai về công việc."]]},{"word":"予習します","reading":"よしゅうします","meaning":"chuẩn bị bài mới","hanViet":"DỰ TẬP","lesson":30,"ex":[["あしたの授業の予習をします。","Tôi chuẩn bị bài cho giờ học ngày mai."],["毎晩、一時間予習をします。","Mỗi buổi tối tôi chuẩn bị bài mới một tiếng đồng hồ."],["日本語の予習をしました。","Tôi đã chuẩn bị bài tiếng Nhật."],["予習をしてから、学校へ行きます。","Tôi chuẩn bị bài xong rồi mới đến trường."],["予習をしないで、授業に行きました。","Tôi đã đến giờ học mà không chuẩn bị bài."]]},{"word":"復習します","reading":"ふくしゅうします","meaning":"ôn bài cũ","hanViet":"PHỤC TẬP","lesson":30,"ex":[["きょう習った文法を復習します。","Tôi ôn lại ngữ pháp đã học hôm nay."],["毎晩、一時間復習をします。","Mỗi buổi tối tôi ôn bài một tiếng đồng hồ."],["テストの前に、よく復習をします。","Trước kỳ kiểm tra, tôi ôn bài thật kỹ."],["復習をしてから、寝ます。","Tôi ôn bài xong rồi mới đi ngủ."],["漢字を復習しました。","Tôi đã ôn lại chữ Hán."]]},{"word":"そのままにします","reading":"そのままにします","meaning":"để nguyên như thế","hanViet":"","lesson":30,"ex":[["本はそのままにしてください。","Xin hãy để quyển sách nguyên như thế."],["机の上はそのままにします。","Tôi để mặt bàn nguyên như thế."],["ドアはそのままにしてください。","Xin hãy để cửa nguyên như thế."],["部屋はそのままにしておきます。","Tôi cứ để căn phòng nguyên như thế."],["窓はそのままにします。","Tôi để cửa sổ nguyên như thế."]]},{"word":"お子さん","reading":"おこさん","meaning":"con (dùng đối với người khác)","hanViet":"TỬ","lesson":30,"ex":[["田中さんのお子さんは何歳ですか。","Con của anh Tanaka mấy tuổi?"],["山田さんのお子さんは元気です。","Con của chị Yamada khỏe mạnh."],["お子さんは何人いますか。","Bạn có mấy người con?"],["田中さんのお子さんは学校へ行きます。","Con của anh Tanaka đi học."],["お子さんはおいくつですか。","Con của bạn mấy tuổi?"]]},{"word":"授業","reading":"じゅぎょう","meaning":"Giờ học, tiết học","hanViet":"THỤ NGHIỆP","lesson":30,"ex":[["授業は九時に始まります。","Giờ học bắt đầu lúc 9 giờ."],["日本語の授業は楽しいです。","Giờ học tiếng Nhật rất vui."],["きょうは授業が三つあります。","Hôm nay tôi có ba tiết học."],["授業の後で、友達と話します。","Sau giờ học, tôi nói chuyện với bạn."],["授業が終わりました。","Giờ học đã kết thúc."]]},{"word":"講義","reading":"こうぎ","meaning":"Bài giảng","hanViet":"GIẢNG NGHĨA","lesson":30,"ex":[["先生の講義を聞きます。","Tôi nghe bài giảng của thầy giáo."],["きょうの講義は難しかったです。","Bài giảng hôm nay khó."],["大学で歴史の講義を受けます。","Tôi nghe bài giảng lịch sử ở trường đại học."],["講義の後で、質問しました。","Sau bài giảng, tôi đã đặt câu hỏi."],["講義は二時間です。","Bài giảng kéo dài hai tiếng đồng hồ."]]},{"word":"予定","reading":"よてい","meaning":"Dự định, kế hoạch","hanViet":"DỰ ĐỊNH","lesson":30,"ex":[["あしたの予定は何ですか。","Ngày mai bạn có dự định gì?"],["旅行の予定があります。","Tôi có kế hoạch đi du lịch."],["あさっての予定はありません。","Ngày kia tôi không có dự định gì."],["予定がありますから、行けません。","Vì tôi có kế hoạch nên không đi được."],["予定を教えてください。","Xin hãy cho tôi biết kế hoạch của bạn."]]},{"word":"案内書","reading":"あんないしょ","meaning":"tài liệu hướng dẫn","hanViet":"ÁN NỘI THƯ","lesson":30,"ex":[["案内書を見てください。","Xin hãy xem tài liệu hướng dẫn."],["旅行の案内書を買いました。","Tôi đã mua tài liệu hướng dẫn du lịch."],["案内書に地図があります。","Trong tài liệu hướng dẫn có bản đồ."],["学校の案内書をもらいました。","Tôi đã nhận được tài liệu hướng dẫn của trường."],["案内書を読みます。","Tôi đọc tài liệu hướng dẫn."]]},{"word":"ごみ箱","reading":"ごみばこ","meaning":"thùng rác","hanViet":"TƯƠNG","lesson":30,"ex":[["ごみはごみ箱に捨ててください。","Xin hãy vứt rác vào thùng rác."],["ごみ箱は台所にあります。","Thùng rác ở trong bếp."],["ごみ箱にごみがたくさんあります。","Trong thùng rác có rất nhiều rác."],["部屋にごみ箱がありません。","Trong phòng không có thùng rác."],["新しいごみ箱を買いました。","Tôi đã mua thùng rác mới."]]},{"word":"人形","reading":"にんぎょう","meaning":"búp bê, con rối","hanViet":"NHÂN HÌNH","lesson":30,"ex":[["妹は人形が好きです。","Em gái tôi thích búp bê."],["日本の人形を買いました。","Tôi đã mua búp bê Nhật Bản."],["人形は棚の上にあります。","Búp bê ở trên kệ."],["子どもに人形をあげました。","Tôi đã tặng búp bê cho đứa trẻ."],["かわいい人形ですね。","Búp bê dễ thương quá nhỉ."]]},{"word":"花瓶","reading":"かびん","meaning":"Bình hoa, lọ hoa","hanViet":"HOA BÌNH","lesson":30,"ex":[["花瓶に花を入れます。","Tôi cắm hoa vào bình hoa."],["花瓶は机の上にあります。","Bình hoa ở trên bàn."],["花瓶が割れました。","Bình hoa đã bị vỡ."],["新しい花瓶を買いました。","Tôi đã mua bình hoa mới."],["花瓶に水を入れました。","Tôi đã đổ nước vào bình hoa."]]},{"word":"鏡","reading":"かがみ","meaning":"Cái gương","hanViet":"KÍNH","lesson":30,"ex":[["鏡を見ます。","Tôi soi gương."],["鏡は壁にあります。","Cái gương ở trên tường."],["鏡の前に立ちます。","Tôi đứng trước gương."],["大きい鏡を買いました。","Tôi đã mua cái gương lớn."],["鏡を掃除します。","Tôi lau gương."]]},{"word":"引き出し","reading":"ひきだし","meaning":"Ngăn kéo","hanViet":"DẪN XUẤT","lesson":30,"ex":[["引き出しに服をしまいます。","Tôi cất quần áo vào ngăn kéo."],["引き出しを開けます。","Tôi mở ngăn kéo."],["鍵は引き出しの中にあります。","Chìa khóa ở trong ngăn kéo."],["引き出しを閉じます。","Tôi đóng ngăn kéo."],["引き出しの中に手紙があります。","Trong ngăn kéo có lá thư."]]},{"word":"玄関","reading":"げんかん","meaning":"Lối vào nhà, sảnh trước","hanViet":"HUYỀN QUAN","lesson":30,"ex":[["玄関で靴を脱ぎます。","Tôi cởi giày ở lối vào nhà."],["玄関に傘があります。","Ở lối vào nhà có cái ô."],["だれかが玄関にいます。","Có ai đó ở lối vào nhà."],["玄関の前に立ちます。","Tôi đứng trước lối vào nhà."],["玄関を掃除します。","Tôi dọn dẹp lối vào nhà."]]},{"word":"廊下","reading":"ろうか","meaning":"Hành lang","hanViet":"LANG HẠ","lesson":30,"ex":[["廊下を歩きます。","Tôi đi bộ dọc hành lang."],["廊下で友達に会いました。","Tôi đã gặp bạn ở hành lang."],["廊下は長いです。","Hành lang dài."],["教室の前に廊下があります。","Trước phòng học có hành lang."],["廊下を走ってはいけません。","Không được chạy ở hành lang."]]},{"word":"池","reading":"いけ","meaning":"Cái ao","hanViet":"TRÌ","lesson":30,"ex":[["公園に池があります。","Trong công viên có cái ao."],["池に魚がいます。","Trong ao có cá."],["池の周りを散歩します。","Tôi đi dạo quanh ao."],["池の水はきれいです。","Nước ao trong sạch."],["池のそばに木があります。","Bên cạnh ao có cây."]]},{"word":"交番","reading":"こうばん","meaning":"trạm cảnh sát","hanViet":"GIAO PHIÊN","lesson":30,"ex":[["交番は駅の前にあります。","Trạm cảnh sát ở trước nhà ga."],["道がわからないときは、交番で聞きます。","Khi không biết đường, tôi hỏi ở trạm cảnh sát."],["交番で警察官に聞きました。","Tôi đã hỏi cảnh sát ở trạm cảnh sát."],["交番はどこですか。","Trạm cảnh sát ở đâu?"],["財布を交番に届けました。","Tôi đã đem ví đến nộp ở trạm cảnh sát."]]},{"word":"元の所","reading":"もとのところ","meaning":"địa điểm ban đầu, địa điểm gốc","hanViet":"NGUYÊN SỞ","lesson":30,"ex":[["辞書を元の所に戻しました。","Tôi đã trả từ điển về chỗ cũ."],["自転車を元の所に置きます。","Tôi đặt xe đạp về chỗ cũ."],["鍵は元の所にありますか。","Chìa khóa có ở chỗ cũ không?"],["かばんを元の所に置きました。","Tôi đã đặt túi xách về chỗ cũ."],["傘を元の所に戻します。","Tôi trả cái ô về chỗ cũ."]]},{"word":"周り","reading":"まわり","meaning":"Xung quanh, vòng quanh","hanViet":"CHU","lesson":30,"ex":[["家の周りに木があります。","Xung quanh nhà có cây."],["学校の周りを散歩します。","Tôi đi dạo quanh trường học."],["机の周りに本があります。","Xung quanh bàn có sách."],["駅の周りに店がたくさんあります。","Xung quanh nhà ga có nhiều cửa hàng."],["周りを見てください。","Xin hãy nhìn xung quanh."]]},{"word":"真ん中","reading":"まんなか","meaning":"Chính giữa","hanViet":"CHÂN TRUNG","lesson":30,"ex":[["部屋の真ん中に机があります。","Chính giữa căn phòng có cái bàn."],["真ん中に座ります。","Tôi ngồi ở chính giữa."],["写真の真ん中に母がいます。","Chính giữa bức ảnh là mẹ tôi."],["机の真ん中に本があります。","Chính giữa bàn có quyển sách."],["真ん中に立ってください。","Xin hãy đứng ở chính giữa."]]},{"word":"隅","reading":"すみ","meaning":"Góc, xó","hanViet":"NGU","lesson":30,"ex":[["部屋の隅に机があります。","Ở góc phòng có cái bàn."],["隅にごみがあります。","Ở góc có rác."],["教室の隅に座ります。","Tôi ngồi ở góc phòng học."],["本は部屋の隅に置きます。","Tôi đặt sách ở góc phòng."],["隅を掃除します。","Tôi dọn dẹp góc phòng."]]},{"word":"まだ","reading":"まだ","meaning":"chưa","hanViet":"","lesson":30,"ex":[["まだごはんを食べていません。","Tôi vẫn chưa ăn cơm."],["宿題はまだ終わっていません。","Bài tập về nhà vẫn chưa xong."],["まだ日本語が話せません。","Tôi vẫn chưa nói được tiếng Nhật."],["田中さんはまだ来ていません。","Anh Tanaka vẫn chưa đến."],["まだ寝ません。","Tôi vẫn chưa đi ngủ."]]},{"word":"～ほど","reading":"～ほど","meaning":"khoảng ~, chừng ~","hanViet":"","lesson":30,"ex":[["三時間ほど勉強しました。","Tôi đã học khoảng ba tiếng đồng hồ."],["一週間ほど旅行をしました。","Tôi đã đi du lịch khoảng một tuần."],["十人ほど来ました。","Khoảng mười người đã đến."],["五千円ほど使いました。","Tôi đã tiêu khoảng năm nghìn yên."],["一か月ほど日本にいました。","Tôi đã ở Nhật khoảng một tháng."]]},{"word":"予定表","reading":"よていひょう","meaning":"bảng lịch trình, bảng kế hoạch","hanViet":"DỰ ĐỊNH BIỂU","lesson":30,"ex":[["予定表を見てください。","Xin hãy xem bảng lịch trình."],["予定表にテストの日を書きます。","Tôi ghi ngày kiểm tra vào bảng lịch trình."],["予定表は壁にあります。","Bảng lịch trình ở trên tường."],["予定表を作ります。","Tôi làm bảng lịch trình."],["予定表を忘れました。","Tôi đã quên bảng lịch trình."]]},{"word":"ご苦労様","reading":"ごくろうさま","meaning":"anh, chị đã làm việc vất vả/cảm ơn anh, chị","hanViet":"KHỔ LAO DẠNG","lesson":30,"ex":[["ご苦労様でした。","Anh/chị đã vất vả rồi."],["仕事の後で、「ご苦労様。」と言います。","Sau giờ làm việc, tôi nói \"Anh đã vất vả rồi\"."],["田中さんに「ご苦労様でした。」と言いました。","Tôi đã nói với anh Tanaka \"Anh đã vất vả rồi\"."],["ご苦労様、ゆっくり休んでください。","Anh đã vất vả rồi, xin hãy nghỉ ngơi thong thả."],["皆さん、ご苦労様でした。","Mọi người đã vất vả rồi."]]},{"word":"希望","reading":"きぼう","meaning":"Hy vọng, mong muốn","hanViet":"HY VỌNG","lesson":30,"ex":[["私の希望は日本で働くことです。","Mong muốn của tôi là làm việc ở Nhật Bản."],["希望がありますか。","Bạn có mong muốn gì không?"],["将来の希望は医者になることです。","Mong muốn trong tương lai của tôi là trở thành bác sĩ."],["希望を教えてください。","Xin hãy cho tôi biết mong muốn của bạn."],["希望の仕事を見つけました。","Tôi đã tìm được công việc như mong muốn."]]},{"word":"丸い","reading":"まるい","meaning":"Tròn","hanViet":"HOÀN","lesson":30,"ex":[["月は丸いです。","Mặt trăng tròn."],["丸いテーブルを買いました。","Tôi đã mua cái bàn tròn."],["このりんごは丸いです。","Quả táo này tròn."],["丸い顔ですね。","Khuôn mặt tròn quá nhỉ."],["地球は丸いです。","Trái đất tròn."]]},{"word":"地球","reading":"ちきゅう","meaning":"Trái đất, địa cầu","hanViet":"ĐỊA CẦU","lesson":30,"ex":[["私たちは地球に住んでいます。","Chúng ta sống trên trái đất."],["地球は大きいです。","Trái đất rất lớn."],["地球の周りに月があります。","Quanh trái đất có mặt trăng."],["地球にはたくさんの国があります。","Trên trái đất có rất nhiều quốc gia."],["地球の写真を見ました。","Tôi đã xem ảnh trái đất."]]},{"word":"うれしい","reading":"うれしい","meaning":"vui","hanViet":"","lesson":30,"ex":[["友達に会えて、うれしいです。","Gặp được bạn bè, tôi rất vui."],["プレゼントをもらって、うれしいです。","Nhận được quà, tôi rất vui."],["日本語が話せて、うれしいです。","Nói được tiếng Nhật, tôi rất vui."],["うれしいニュースです。","Đó là tin vui."],["母の手紙を読んで、うれしかったです。","Đọc thư của mẹ, tôi rất vui."]]},{"word":"嫌な","reading":"いやな","meaning":"chán, ghét, không chấp nhận được","hanViet":"HIỀM","lesson":30,"ex":[["嫌な天気です。","Thời tiết thật khó chịu."],["嫌な音が聞こえます。","Tôi nghe thấy âm thanh khó chịu."],["嫌なにおいがします。","Có mùi khó chịu."],["嫌な夢を見ました。","Tôi đã mơ một giấc mơ khó chịu."],["嫌なことを言われました。","Tôi đã bị nói những điều khó chịu."]]},{"word":"目が覚めます","reading":"めがさめます","meaning":"tỉnh giấc, mở mắt","hanViet":"MỤC GIÁC","lesson":30,"ex":[["朝六時に目が覚めます。","Tôi tỉnh giấc lúc 6 giờ sáng."],["大きい音で目が覚めました。","Tôi đã tỉnh giấc vì tiếng động lớn."],["目が覚めて、時計を見ました。","Tỉnh giấc, tôi nhìn đồng hồ."],["子どもはまだ目が覚めていません。","Đứa trẻ vẫn chưa tỉnh giấc."],["目が覚めたら、窓を開けます。","Khi tỉnh giấc, tôi mở cửa sổ."]]},{"word":"位置","reading":"いち","meaning":"vị trí","hanViet":"VỊ TRÍ","lesson":30,"ex":[["学校の位置を教えてください。","Xin hãy cho tôi biết vị trí của trường học."],["地図で位置を見ます。","Tôi xem vị trí trên bản đồ."],["位置がわかりません。","Tôi không biết vị trí."],["ホテルの位置は駅の近くです。","Vị trí của khách sạn ở gần nhà ga."],["位置を地図に書きます。","Tôi ghi vị trí vào bản đồ."]]},{"word":"上から二段目","reading":"うえからにだんめ","meaning":"ngăn thứ 2 từ trên xuống","hanViet":"THƯỢNG NHỊ ĐOẠN MỤC","lesson":30,"ex":[["本は上から二段目にあります。","Quyển sách ở ngăn thứ hai từ trên xuống."],["上から二段目に服をしまいます。","Tôi cất quần áo vào ngăn thứ hai từ trên xuống."],["上から二段目の本を取ってください。","Xin hãy lấy quyển sách ở ngăn thứ hai từ trên xuống."],["辞書は上から二段目にあります。","Từ điển ở ngăn thứ hai từ trên xuống."],["上から二段目に何がありますか。","Ngăn thứ hai từ trên xuống có gì?"]]},{"word":"～の横","reading":"～のよこ","meaning":"bên cạnh ~","hanViet":"HOÀNH","lesson":30,"ex":[["本棚の横に机があります。","Bên cạnh kệ sách có cái bàn."],["冷蔵庫の横にごみ箱があります。","Bên cạnh tủ lạnh có thùng rác."],["私の横に友達が座ります。","Bạn tôi ngồi bên cạnh tôi."],["ベッドの横に電話があります。","Bên cạnh giường có điện thoại."],["駅の横に銀行があります。","Bên cạnh nhà ga có ngân hàng."]]},{"word":"奥","reading":"おく","meaning":"Phía trong sâu, bên trong","hanViet":"ÁO","lesson":30,"ex":[["部屋の奥に机があります。","Ở phía trong căn phòng có cái bàn."],["奥に座ってください。","Xin hãy ngồi vào phía trong."],["店の奥にトイレがあります。","Ở phía trong cửa hàng có nhà vệ sinh."],["冷蔵庫の奥に牛乳があります。","Ở phía trong tủ lạnh có sữa."],["部屋の奥で寝ます。","Tôi ngủ ở phía trong căn phòng."]]},{"word":"手前","reading":"てまえ","meaning":"phía trước","hanViet":"THỦ TIỀN","lesson":30,"ex":[["駅の手前に銀行があります。","Trước nhà ga có ngân hàng."],["手前に座ってください。","Xin hãy ngồi ở phía trước."],["信号の手前で止まります。","Tôi dừng lại trước đèn giao thông."],["学校の手前に公園があります。","Trước trường học có công viên."],["手前の席に座りました。","Tôi đã ngồi vào ghế phía trước."]]},{"word":"前から二列目","reading":"まえからにれつめ","meaning":"dãy (hàng) thứ 2 tính từ phía trước","hanViet":"TIỀN NHỊ LIỆT MỤC","lesson":30,"ex":[["前から二列目に座ります。","Tôi ngồi ở hàng thứ hai tính từ phía trước."],["前から二列目は静かです。","Hàng thứ hai tính từ phía trước yên tĩnh."],["田中さんは前から二列目にいます。","Anh Tanaka ở hàng thứ hai tính từ phía trước."],["前から二列目で映画を見ました。","Tôi đã xem phim ở hàng thứ hai tính từ phía trước."],["前から二列目に友達が座りました。","Bạn tôi đã ngồi ở hàng thứ hai tính từ phía trước."]]},{"word":"机の周り","reading":"つくえのまわり","meaning":"xung quanh (cái bàn)","hanViet":"CƠ CHU","lesson":30,"ex":[["机の周りを片づけます。","Tôi dọn dẹp xung quanh cái bàn."],["机の周りにいすがあります。","Xung quanh cái bàn có ghế."],["机の周りに座ります。","Tôi ngồi xung quanh cái bàn."],["机の周りを掃除します。","Tôi quét dọn xung quanh cái bàn."],["机の周りに友達がいます。","Xung quanh cái bàn có bạn bè."]]},{"word":"斜め前","reading":"ななめまえ","meaning":"(vị trí) chếch trước mặt","hanViet":"TÀ TIỀN","lesson":30,"ex":[["斜め前に田中さんが座っています。","Anh Tanaka đang ngồi ở vị trí chếch trước mặt tôi."],["私の斜め前に先生がいます。","Thầy giáo ở vị trí chếch trước mặt tôi."],["斜め前の席に友達がいます。","Ở ghế chếch trước mặt có bạn tôi."],["斜め前を見てください。","Xin hãy nhìn chếch về phía trước."],["斜め前に公園があります。","Chếch phía trước có công viên."]]},{"word":"斜め後ろ","reading":"ななめうしろ","meaning":"(vị trí) chếch sau lưng","hanViet":"TÀ HẬU","lesson":30,"ex":[["斜め後ろに山田さんが座っています。","Chị Yamada đang ngồi ở vị trí chếch sau lưng tôi."],["私の斜め後ろに友達がいます。","Bạn tôi ở vị trí chếch sau lưng tôi."],["斜め後ろの席に先生がいます。","Ở ghế chếch sau lưng có thầy giáo."],["斜め後ろを見てください。","Xin hãy nhìn chếch về phía sau."],["斜め後ろに本棚があります。","Chếch phía sau có kệ sách."]]},{"word":"～のそば","reading":"～のそば","meaning":"bên cạnh ~","hanViet":"","lesson":30,"ex":[["学校のそばに公園があります。","Bên cạnh trường học có công viên."],["私のそばに座ってください。","Xin hãy ngồi bên cạnh tôi."],["駅のそばにホテルがあります。","Bên cạnh nhà ga có khách sạn."],["川のそばに家があります。","Bên cạnh con sông có ngôi nhà."],["机のそばにごみ箱があります。","Bên cạnh cái bàn có thùng rác."]]},{"word":"二行目","reading":"にぎょうめ","meaning":"dòng thứ 2","hanViet":"NHỊ HÀNH MỤC","lesson":30,"ex":[["二行目を読んでください。","Xin hãy đọc dòng thứ hai."],["二行目に名前を書きます。","Tôi viết tên ở dòng thứ hai."],["二行目を見てください。","Xin hãy nhìn dòng thứ hai."],["二行目に何が書いてありますか。","Dòng thứ hai viết gì vậy?"],["二行目から読んでください。","Xin hãy đọc từ dòng thứ hai."]]},{"word":"ミーティング","reading":"ミーティング","meaning":"cuộc họp","hanViet":"","lesson":30,"ex":[["ミーティングは三時に始まります。","Cuộc họp bắt đầu lúc 3 giờ."],["ミーティングに出席します。","Tôi tham dự cuộc họp."],["あした、ミーティングがあります。","Ngày mai có cuộc họp."],["ミーティングの後で、昼ごはんを食べます。","Sau cuộc họp, tôi ăn trưa."],["ミーティングは一時間です。","Cuộc họp kéo dài một tiếng đồng hồ."]]},{"word":"カレンダー","reading":"カレンダー","meaning":"lịch , tờ lịch","hanViet":"","lesson":30,"ex":[["カレンダーを見ます。","Tôi xem lịch."],["カレンダーは壁にあります。","Tờ lịch ở trên tường."],["カレンダーに予定を書きます。","Tôi ghi kế hoạch vào lịch."],["新しいカレンダーを買いました。","Tôi đã mua tờ lịch mới."],["カレンダーで日を見ます。","Tôi xem ngày trên tờ lịch."]]},{"word":"ポスター","reading":"ポスター","meaning":"tờ quảng cáo, tờ áp phích","hanViet":"","lesson":30,"ex":[["ポスターを壁にはります。","Tôi dán áp phích lên tường."],["駅にポスターがあります。","Ở nhà ga có áp phích."],["映画のポスターを見ました。","Tôi đã xem áp phích phim."],["ポスターを作ります。","Tôi làm áp phích."],["部屋にポスターをはりました。","Tôi đã dán áp phích trong phòng."]]},{"word":"ミュージカル","reading":"ミュージカル","meaning":"ca kịch","hanViet":"","lesson":30,"ex":[["ミュージカルを見ました。","Tôi đã xem ca kịch."],["ミュージカルは楽しいです。","Ca kịch rất thú vị."],["友達とミュージカルを見に行きます。","Tôi đi xem ca kịch cùng bạn."],["ミュージカルのチケットを買いました。","Tôi đã mua vé xem ca kịch."],["ミュージカルで歌を歌います。","Trong ca kịch, người ta hát."]]},{"word":"すると","reading":"すると","meaning":"sau đó, tiếp đó","hanViet":"","lesson":30,"ex":[["ドアを開けました。すると、友達がいました。","Tôi mở cửa ra. Sau đó, tôi thấy bạn ở đó."],["電話をしました。すると、母が出ました。","Tôi gọi điện thoại. Sau đó, mẹ tôi bắt máy."],["箱を開けました。すると、中に本がありました。","Tôi mở hộp ra. Sau đó, tôi thấy bên trong có sách."],["外を見ました。すると、雪が降っていました。","Tôi nhìn ra ngoài. Sau đó, tôi thấy tuyết đang rơi."],["部屋に入りました。すると、友達がいませんでした。","Tôi bước vào phòng. Sau đó, tôi thấy bạn không ở đó."]]},{"word":"何かご希望がありますか","reading":"なにかごきぼうがありますか","meaning":"anh/chị có nguyện vọng gì không?","hanViet":"HÀ HY VỌNG","lesson":30,"ex":[["何かご希望がありますか。","Anh/chị có nguyện vọng gì không?"],["店員は「何かご希望がありますか。」と聞きました。","Nhân viên cửa hàng đã hỏi anh/chị có nguyện vọng gì không."],["旅行の前に、「何かご希望がありますか。」と聞きました。","Trước chuyến du lịch, tôi đã hỏi anh/chị có nguyện vọng gì không."],["先生は学生に「何かご希望がありますか。」と聞きました。","Thầy giáo đã hỏi học sinh có nguyện vọng gì không."],["ホテルで「何かご希望がありますか。」と聞かれました。","Ở khách sạn, tôi đã được hỏi có nguyện vọng gì không."]]},{"word":"それはいいですね","reading":"それはいいですね","meaning":"Điều đó được đấy nhỉ./ Hay quá nhỉ","hanViet":"","lesson":30,"ex":[["それはいいですね。","Điều đó hay quá nhỉ."],["「旅行に行きます。」「それはいいですね。」","\"Tôi đi du lịch.\" \"Hay quá nhỉ\"."],["友達の話を聞いて、「それはいいですね。」と言いました。","Nghe bạn kể chuyện, tôi nói \"Hay quá nhỉ\"."],["「新しい仕事を見つけました。」「それはいいですね。」","\"Tôi đã tìm được công việc mới rồi.\" \"Hay quá nhỉ\"."],["先生は「それはいいですね。」と言いました。","Thầy giáo đã nói \"Hay quá nhỉ\"."]]},{"word":"始まります","reading":"はじまります","meaning":"Bắt đầu (tự diễn ra)","hanViet":"THỈ","lesson":31,"ex":[["映画は七時に始まります。","Bộ phim bắt đầu lúc 7 giờ."],["会議は十時に始まりました。","Cuộc họp đã bắt đầu lúc 10 giờ."],["休みはあしたから始まります。","Kỳ nghỉ bắt đầu từ ngày mai."],["パーティーは六時に始まります。","Bữa tiệc bắt đầu lúc 6 giờ."],["仕事は九時に始まります。","Công việc bắt đầu lúc 9 giờ."]]},{"word":"続けます","reading":"つづけます","meaning":"Tiếp tục làm","hanViet":"TỤC","lesson":31,"ex":[["日本語の勉強を続けます。","Tôi tiếp tục học tiếng Nhật."],["雨が降っても、散歩を続けます。","Dù trời mưa, tôi vẫn tiếp tục đi dạo."],["仕事を続けますか。","Bạn có tiếp tục công việc không?"],["ジョギングを続けています。","Tôi đang tiếp tục chạy bộ."],["話を続けてください。","Xin hãy tiếp tục câu chuyện."]]},{"word":"見つけます","reading":"みつけます","meaning":"tìm, tìm thấy","hanViet":"KIẾN","lesson":31,"ex":[["鍵を見つけました。","Tôi đã tìm thấy chìa khóa."],["いい仕事を見つけました。","Tôi đã tìm được công việc tốt."],["財布を見つけられません。","Tôi không tìm thấy ví."],["友達を駅で見つけました。","Tôi đã tìm thấy bạn ở nhà ga."],["新しい店を見つけました。","Tôi đã tìm thấy cửa hàng mới."]]},{"word":"受けます","reading":"うけます","meaning":"Nhận, dự thi","hanViet":"THỤ","lesson":31,"ex":[["試験を受けます。","Tôi dự thi."],["日本語の試験を受けました。","Tôi đã dự thi tiếng Nhật."],["テストを受けます。","Tôi làm bài kiểm tra."],["電話を受けました。","Tôi đã nhận điện thoại."],["プレゼントを受けました。","Tôi đã nhận quà."]]},{"word":"入学します","reading":"にゅうがくします","meaning":"nhập học","hanViet":"NHẬP HỌC","lesson":31,"ex":[["四月に大学に入学します。","Tháng 4 tôi nhập học đại học."],["弟は高校に入学しました。","Em trai tôi đã nhập học cấp ba."],["あした、学校に入学します。","Ngày mai tôi nhập học."],["入学してから、日本語を勉強します。","Sau khi nhập học, tôi học tiếng Nhật."],["妹は小学校に入学しました。","Em gái tôi đã nhập học tiểu học."]]},{"word":"卒業します","reading":"そつぎょうします","meaning":"tốt nghiệp","hanViet":"TỐT NGHIỆP","lesson":31,"ex":[["三月に大学を卒業します。","Tháng 3 tôi tốt nghiệp đại học."],["兄は高校を卒業しました。","Anh trai tôi đã tốt nghiệp cấp ba."],["卒業してから、会社で働きます。","Sau khi tốt nghiệp, tôi làm việc ở công ty."],["卒業したら、日本へ行きます。","Sau khi tốt nghiệp, tôi sẽ đi Nhật Bản."],["卒業する前に、写真を撮ります。","Trước khi tốt nghiệp, tôi chụp ảnh."]]},{"word":"出席します","reading":"しゅっせきします","meaning":"tham dự, tham gia [cuộc họp]","hanViet":"XUẤT TỊCH","lesson":31,"ex":[["会議に出席します。","Tôi tham dự cuộc họp."],["パーティーに出席します。","Tôi tham dự bữa tiệc."],["結婚式に出席します。","Tôi tham dự lễ cưới."],["あしたの会議に出席できません。","Ngày mai tôi không thể tham dự cuộc họp."],["授業に出席しました。","Tôi đã tham dự giờ học."]]},{"word":"休憩します","reading":"きゅうけいします","meaning":"giải lao","hanViet":"HƯU KHẾ","lesson":31,"ex":[["十時に休憩します。","Lúc 10 giờ tôi giải lao."],["仕事の後で、休憩します。","Sau giờ làm việc, tôi giải lao."],["コーヒーを飲んで、休憩します。","Tôi uống cà phê và giải lao."],["少し休憩してください。","Xin hãy giải lao một chút."],["休憩してから、勉強します。","Tôi giải lao xong rồi mới học."]]},{"word":"連休","reading":"れんきゅう","meaning":"Kỳ nghỉ dài nhiều ngày liên tiếp","hanViet":"LIÊN HƯU","lesson":31,"ex":[["連休に旅行に行きます。","Kỳ nghỉ dài tôi đi du lịch."],["連休は五日です。","Kỳ nghỉ dài là năm ngày."],["連休に家で休みます。","Kỳ nghỉ dài tôi nghỉ ở nhà."],["連休の後で、学校へ行きます。","Sau kỳ nghỉ dài, tôi đi học."],["連休に友達に会います。","Kỳ nghỉ dài tôi gặp bạn."]]},{"word":"作文","reading":"さくぶん","meaning":"Bài tập làm văn","hanViet":"TÁC VĂN","lesson":31,"ex":[["作文を書きます。","Tôi viết bài tập làm văn."],["日本語の作文を書きました。","Tôi đã viết bài văn tiếng Nhật."],["作文は難しいです。","Bài tập làm văn khó."],["作文を先生に見せます。","Tôi đưa bài văn cho thầy giáo xem."],["作文の宿題があります。","Tôi có bài tập làm văn về nhà."]]},{"word":"展覧会","reading":"てんらんかい","meaning":"Triển lãm","hanViet":"TRIỂN LÃM HỘI","lesson":31,"ex":[["展覧会に行きます。","Tôi đi xem triển lãm."],["絵の展覧会を見ました。","Tôi đã xem triển lãm tranh."],["展覧会は美術館であります。","Triển lãm ở bảo tàng mỹ thuật."],["写真の展覧会を見に行きます。","Tôi đi xem triển lãm ảnh."],["展覧会は来週までです。","Triển lãm kéo dài đến tuần sau."]]},{"word":"結婚式","reading":"けっこんしき","meaning":"Lễ cưới","hanViet":"KẾT HÔN THỨC","lesson":31,"ex":[["友達の結婚式に行きます。","Tôi đi dự lễ cưới của bạn."],["結婚式は六月です。","Lễ cưới vào tháng 6."],["結婚式で写真を撮りました。","Tôi đã chụp ảnh ở lễ cưới."],["結婚式はホテルであります。","Lễ cưới ở khách sạn."],["結婚式に何を着ますか。","Bạn mặc gì đến lễ cưới?"]]},{"word":"葬式","reading":"そうしき","meaning":"Tang lễ, đám tang","hanViet":"TÁNG THỨC","lesson":31,"ex":[["葬式に出席しました。","Tôi đã tham dự đám tang."],["葬式はあしたです。","Đám tang vào ngày mai."],["祖父の葬式がありました。","Đã có đám tang của ông tôi."],["葬式に行きます。","Tôi đi dự đám tang."],["葬式の後で、家に帰りました。","Sau đám tang, tôi đã về nhà."]]},{"word":"式","reading":"しき","meaning":"Nghi thức, buổi lễ","hanViet":"THỨC","lesson":31,"ex":[["入学式は四月です。","Lễ nhập học vào tháng 4."],["卒業式に出席します。","Tôi tham dự lễ tốt nghiệp."],["式は九時に始まります。","Buổi lễ bắt đầu lúc 9 giờ."],["式の後で、写真を撮ります。","Sau buổi lễ, tôi chụp ảnh."],["結婚式は大きな式です。","Lễ cưới là một buổi lễ lớn."]]},{"word":"本社","reading":"ほんしゃ","meaning":"trụ sở chính","hanViet":"BẢN XÃ","lesson":31,"ex":[["本社は東京にあります。","Trụ sở chính ở Tokyo."],["本社で働きます。","Tôi làm việc ở trụ sở chính."],["本社に電話をします。","Tôi gọi điện thoại cho trụ sở chính."],["あした、本社へ行きます。","Ngày mai tôi đến trụ sở chính."],["本社は大きいです。","Trụ sở chính rất lớn."]]},{"word":"支店","reading":"してん","meaning":"chi nhánh","hanViet":"CHI ĐIẾM","lesson":31,"ex":[["支店は京都にあります。","Chi nhánh ở Kyoto."],["支店で働きます。","Tôi làm việc ở chi nhánh."],["支店に電話をします。","Tôi gọi điện thoại cho chi nhánh."],["支店は小さいです。","Chi nhánh nhỏ."],["支店の社員に会いました。","Tôi đã gặp nhân viên của chi nhánh."]]},{"word":"温泉","reading":"おんせん","meaning":"Suối nước nóng","hanViet":"ÔN TUYỀN","lesson":31,"ex":[["温泉に入ります。","Tôi tắm suối nước nóng."],["温泉は温かいです。","Suối nước nóng ấm áp."],["旅行で温泉に行きました。","Tôi đã đi suối nước nóng trong chuyến du lịch."],["温泉でゆっくり休みます。","Tôi nghỉ ngơi thong thả ở suối nước nóng."],["日本の温泉は有名です。","Suối nước nóng Nhật Bản rất nổi tiếng."]]},{"word":"お客","reading":"おきゃく","meaning":"Khách, vị khách","hanViet":"KHÁCH","lesson":31,"ex":[["お客が来ました。","Khách đã đến."],["お客は三人です。","Có ba vị khách."],["お客にお茶を出します。","Tôi mời khách uống trà."],["お客と話します。","Tôi nói chuyện với khách."],["お客がたくさん来ました。","Rất nhiều khách đã đến."]]},{"word":"だれか","reading":"だれか","meaning":"ai đó","hanViet":"","lesson":31,"ex":[["だれか来ました。","Có ai đó đã đến."],["だれかいますか。","Có ai ở đó không?"],["だれかに会いました。","Tôi đã gặp ai đó."],["だれかがドアを開けました。","Ai đó đã mở cửa."],["だれか手伝ってください。","Ai đó giúp tôi với."]]},{"word":"ずっと","reading":"ずっと","meaning":"suốt,liền","hanViet":"","lesson":31,"ex":[["ずっと家にいました。","Tôi ở nhà suốt."],["ずっと雨が降っています。","Trời mưa suốt."],["ずっと待っています。","Tôi đang chờ suốt."],["ずっとここにいます。","Tôi ở đây suốt."],["ずっとテレビを見ていました。","Tôi đã xem tivi suốt."]]},{"word":"残ります","reading":"のこります","meaning":"Còn lại, sót lại","hanViet":"TÀN","lesson":31,"ex":[["お金が少し残ります。","Còn lại một ít tiền."],["ごはんが残りました。","Cơm còn thừa lại."],["時間が残っていません。","Không còn thời gian nữa."],["仕事が残っています。","Công việc vẫn còn dở dang."],["宿題が残りました。","Bài tập về nhà vẫn còn."]]},{"word":"月に","reading":"つきに","meaning":"(trong) một tháng","hanViet":"NGUYỆT","lesson":31,"ex":[["月に二回、映画を見ます。","Một tháng tôi xem phim hai lần."],["月に一回、母に電話をします。","Một tháng tôi gọi điện thoại cho mẹ một lần."],["月に三回、プールで泳ぎます。","Một tháng tôi bơi ở hồ bơi ba lần."],["月に何回、買い物をしますか。","Một tháng bạn đi mua sắm mấy lần?"],["月に五回、図書館へ行きます。","Một tháng tôi đến thư viện năm lần."]]},{"word":"普通の","reading":"ふつうの","meaning":"thường","hanViet":"PHỔ THÔNG","lesson":31,"ex":[["普通の生活です。","Đó là cuộc sống bình thường."],["普通の服を着ます。","Tôi mặc quần áo bình thường."],["普通の大きさです。","Kích thước bình thường."],["普通の電車で行きます。","Tôi đi bằng tàu thường."],["普通のごはんを食べます。","Tôi ăn cơm bình thường."]]},{"word":"閉じます","reading":"とじます","meaning":"đóng, khép, nhắm (mắt, sách)","hanViet":"BẾ","lesson":31,"ex":[["本を閉じます。","Tôi đóng sách lại."],["目を閉じます。","Tôi nhắm mắt lại."],["ドアを閉じました。","Tôi đã đóng cửa lại."],["窓を閉じてください。","Xin hãy đóng cửa sổ lại."],["ノートを閉じます。","Tôi đóng vở lại."]]},{"word":"世界中","reading":"せかいじゅう","meaning":"Khắp thế giới","hanViet":"THẾ GIỚI TRUNG","lesson":31,"ex":[["この歌は世界中で有名です。","Bài hát này nổi tiếng khắp thế giới."],["世界中から学生が日本へ来ます。","Sinh viên từ khắp thế giới đến Nhật Bản."],["世界中の子どもたちがこの本を読みます。","Trẻ em khắp thế giới đọc cuốn sách này."],["この映画は世界中で見られます。","Bộ phim này có thể xem được khắp thế giới."],["世界中の人が日本語を勉強しています。","Người dân khắp thế giới đang học tiếng Nhật."]]},{"word":"美しい","reading":"うつくしい","meaning":"Đẹp","hanViet":"MỸ","lesson":31,"ex":[["京都は美しい町です。","Kyoto là thành phố đẹp."],["この花はとても美しいです。","Bông hoa này rất đẹp."],["海の色は美しいです。","Màu của biển rất đẹp."],["美しい声で歌を歌います。","Tôi hát bằng giọng hát đẹp."],["あの絵は美しいです。","Bức tranh kia rất đẹp."]]},{"word":"自然","reading":"しぜん","meaning":"Tự nhiên, thiên nhiên","hanViet":"TỰ NHIÊN","lesson":31,"ex":[["日本は自然が美しい国です。","Nhật Bản là đất nước có thiên nhiên đẹp."],["田舎は自然がたくさんあります。","Ở quê có nhiều thiên nhiên."],["自然の中で散歩します。","Tôi đi dạo trong thiên nhiên."],["自然を大切にします。","Tôi trân trọng thiên nhiên."],["子どもたちは自然が好きです。","Trẻ em thích thiên nhiên."]]},{"word":"すばらしさ","reading":"すばらしさ","meaning":"sự tuyệt vời","hanViet":"","lesson":31,"ex":[["自然のすばらしさがわかります。","Tôi hiểu được sự tuyệt vời của thiên nhiên."],["日本のすばらしさを友達に話します。","Tôi kể cho bạn nghe về sự tuyệt vời của Nhật Bản."],["この歌のすばらしさは声です。","Sự tuyệt vời của bài hát này là giọng hát."],["母はこの花のすばらしさをよく知っています。","Mẹ tôi biết rõ sự tuyệt vời của bông hoa này."],["山のすばらしさを写真で見ました。","Tôi đã nhìn thấy sự tuyệt vời của ngọn núi qua ảnh."]]},{"word":"薬学","reading":"やくがく","meaning":"dược học","hanViet":"DƯỢC HỌC","lesson":31,"ex":[["兄は大学で薬学を勉強しています。","Anh trai tôi đang học dược học ở đại học."],["薬学の本を図書館で借りました。","Tôi đã mượn sách dược học ở thư viện."],["薬学を勉強して、病院で働きたいです。","Tôi muốn học dược học rồi làm việc ở bệnh viện."],["田中さんは薬学の先生です。","Anh Tanaka là giáo viên dạy dược học."],["薬学の試験は来週です。","Kỳ thi dược học là tuần sau."]]},{"word":"生化学","reading":"せいかがく","meaning":"sinh hóa học","hanViet":"SINH HÓA HỌC","lesson":31,"ex":[["姉は大学で生化学を勉強しています。","Chị gái tôi đang học sinh hóa học ở đại học."],["生化学の授業はとても難しいです。","Giờ học sinh hóa học rất khó."],["生化学の本を買いました。","Tôi đã mua sách sinh hóa học."],["生化学を勉強すると、体のことがわかります。","Học sinh hóa học thì sẽ hiểu về cơ thể."],["生化学の研究室で実験をします。","Tôi làm thí nghiệm ở phòng nghiên cứu sinh hóa học."]]},{"word":"生物学","reading":"せいぶつがく","meaning":"sinh vật học","hanViet":"SINH VẬT HỌC","lesson":31,"ex":[["弟は生物学が好きです。","Em trai tôi thích sinh vật học."],["生物学の授業で動物のことを勉強します。","Trong giờ sinh vật học, tôi học về động vật."],["生物学の先生は山田さんです。","Giáo viên dạy sinh vật học là anh Yamada."],["生物学の本に鳥の写真があります。","Trong sách sinh vật học có ảnh chim."],["大学で生物学を勉強したいです。","Tôi muốn học sinh vật học ở đại học."]]},{"word":"農学","reading":"のうがく","meaning":"nông học","hanViet":"NÔNG HỌC","lesson":31,"ex":[["父は大学で農学を勉強しました。","Bố tôi đã học nông học ở đại học."],["農学の授業で米のことを勉強します。","Trong giờ nông học, tôi học về lúa gạo."],["農学の本を図書館で借りました。","Tôi đã mượn sách nông học ở thư viện."],["農学の試験は来月です。","Kỳ thi nông học là tháng sau."],["農学が好きな学生は田舎へ行きます。","Sinh viên thích nông học đi về vùng quê."]]},{"word":"土木工学","reading":"どうぼくこうがく","meaning":"kỹ thuật xây dựng","hanViet":"THỔ MỘC CÔNG HỌC","lesson":31,"ex":[["兄は土木工学を勉強しています。","Anh trai tôi đang học kỹ thuật xây dựng."],["土木工学の授業で橋のことを勉強します。","Trong giờ kỹ thuật xây dựng, tôi học về cầu."],["土木工学の仕事をしたいです。","Tôi muốn làm công việc về kỹ thuật xây dựng."],["土木工学の本を買いました。","Tôi đã mua sách kỹ thuật xây dựng."],["土木工学の試験は明日です。","Kỳ thi kỹ thuật xây dựng là ngày mai."]]},{"word":"電子工学","reading":"でんしこうがく","meaning":"kỹ thuật điện tử","hanViet":"ĐIỆN TỬ CÔNG HỌC","lesson":31,"ex":[["弟は電子工学を勉強しています。","Em trai tôi đang học kỹ thuật điện tử."],["電子工学の授業でパソコンのことを勉強します。","Trong giờ kỹ thuật điện tử, tôi học về máy tính."],["電子工学の会社で働きたいです。","Tôi muốn làm việc ở công ty kỹ thuật điện tử."],["電子工学はとても難しいです。","Kỹ thuật điện tử rất khó."],["電子工学の先生は山田さんです。","Giáo viên dạy kỹ thuật điện tử là anh Yamada."]]},{"word":"電気工学","reading":"でんきこうがく","meaning":"kỹ thuật điện","hanViet":"ĐIỆN KHÍ CÔNG HỌC","lesson":31,"ex":[["山田さんは大学で電気工学を勉強しています。","Anh Yamada đang học kỹ thuật điện ở đại học."],["電気工学の授業で電気のことを勉強します。","Trong giờ kỹ thuật điện, tôi học về điện."],["電気工学の仕事は大変です。","Công việc kỹ thuật điện vất vả."],["電気工学の本を図書館で読みました。","Tôi đã đọc sách kỹ thuật điện ở thư viện."],["将来、電気工学の会社で働きたいです。","Trong tương lai, tôi muốn làm việc ở công ty kỹ thuật điện."]]},{"word":"遺伝子工学","reading":"いでんしこうがく","meaning":"kỹ thuật di truyền","hanViet":"DI TRUYỀN TỬ CÔNG HỌC","lesson":31,"ex":[["姉は遺伝子工学を勉強しています。","Chị gái tôi đang học kỹ thuật di truyền."],["遺伝子工学の授業は難しいです。","Giờ học kỹ thuật di truyền khó."],["遺伝子工学の本を買いました。","Tôi đã mua sách kỹ thuật di truyền."],["遺伝子工学の研究室で勉強します。","Tôi học ở phòng nghiên cứu kỹ thuật di truyền."],["遺伝子工学の先生に会いました。","Tôi đã gặp giáo viên dạy kỹ thuật di truyền."]]},{"word":"建築学","reading":"けんちくがく","meaning":"kiến trúc học","hanViet":"KIẾN TRÚC HỌC","lesson":31,"ex":[["父は建築学を勉強しました。","Bố tôi đã học kiến trúc học."],["建築学の授業で建物のことを勉強します。","Trong giờ kiến trúc học, tôi học về các tòa nhà."],["建築学の仕事をしたいです。","Tôi muốn làm công việc về kiến trúc học."],["建築学の本に美しい建物の写真があります。","Trong sách kiến trúc học có ảnh những tòa nhà đẹp."],["建築学の試験は来週です。","Kỳ thi kiến trúc học là tuần sau."]]},{"word":"環境科学","reading":"かんきょうかがく","meaning":"khoa học môi trường","hanViet":"HOÀN CẢNH KHOA HỌC","lesson":31,"ex":[["妹は環境科学を勉強しています。","Em gái tôi đang học khoa học môi trường."],["環境科学の授業で自然のことを勉強します。","Trong giờ khoa học môi trường, tôi học về thiên nhiên."],["環境科学の本を読みました。","Tôi đã đọc sách khoa học môi trường."],["環境科学はとても大切です。","Khoa học môi trường rất quan trọng."],["環境科学の先生は田中さんです。","Giáo viên dạy khoa học môi trường là anh Tanaka."]]},{"word":"国際関係学","reading":"こくさいかんけいがく","meaning":"quan hệ quốc tế","hanViet":"QUỐC TẾ QUAN HỆ HỌC","lesson":31,"ex":[["友達は国際関係学を勉強しています。","Bạn tôi đang học quan hệ quốc tế."],["国際関係学の授業で世界のことを勉強します。","Trong giờ quan hệ quốc tế, tôi học về thế giới."],["国際関係学の本を借りました。","Tôi đã mượn sách quan hệ quốc tế."],["国際関係学を勉強して、外国で働きたいです。","Tôi muốn học quan hệ quốc tế rồi làm việc ở nước ngoài."],["国際関係学の試験は難しいです。","Kỳ thi quan hệ quốc tế khó."]]},{"word":"法律学","reading":"ほうりつがく","meaning":"luật học","hanViet":"PHÁP LUẬT HỌC","lesson":31,"ex":[["兄は法律学を勉強しています。","Anh trai tôi đang học luật học."],["法律学の授業で法律のことを勉強します。","Trong giờ luật học, tôi học về pháp luật."],["法律学の本を図書館で借りました。","Tôi đã mượn sách luật học ở thư viện."],["法律学を勉強して、弁護士になりたいです。","Tôi muốn học luật học rồi trở thành luật sư."],["法律学の先生は山田さんです。","Giáo viên dạy luật học là anh Yamada."]]},{"word":"経営学","reading":"けいえいがく","meaning":"quản trị kinh doanh","hanViet":"KINH DOANH HỌC","lesson":31,"ex":[["姉は経営学を勉強しています。","Chị gái tôi đang học quản trị kinh doanh."],["経営学の授業で会社のことを勉強します。","Trong giờ quản trị kinh doanh, tôi học về công ty."],["経営学の本を買いました。","Tôi đã mua sách quản trị kinh doanh."],["経営学を勉強して、会社で働きたいです。","Tôi muốn học quản trị kinh doanh rồi làm việc ở công ty."],["経営学の試験は明日です。","Kỳ thi quản trị kinh doanh là ngày mai."]]},{"word":"社会学","reading":"しゃかいがく","meaning":"xã hội học","hanViet":"XÃ HỘI HỌC","lesson":31,"ex":[["弟は社会学を勉強しています。","Em trai tôi đang học xã hội học."],["社会学の授業で社会のことを勉強します。","Trong giờ xã hội học, tôi học về xã hội."],["社会学の本を読みました。","Tôi đã đọc sách xã hội học."],["社会学の先生は山田さんです。","Giáo viên dạy xã hội học là anh Yamada."],["社会学はとてもおもしろいです。","Xã hội học rất thú vị."]]},{"word":"言語学","reading":"げんごがく","meaning":"ngôn ngữ học","hanViet":"NGÔN NGỮ HỌC","lesson":31,"ex":[["友達は言語学を勉強しています。","Bạn tôi đang học ngôn ngữ học."],["言語学の授業で日本語のことを勉強します。","Trong giờ ngôn ngữ học, tôi học về tiếng Nhật."],["言語学の本を図書館で借りました。","Tôi đã mượn sách ngôn ngữ học ở thư viện."],["言語学を勉強して、英語の先生になりたいです。","Tôi muốn học ngôn ngữ học rồi trở thành giáo viên tiếng Anh."],["言語学の試験は来月です。","Kỳ thi ngôn ngữ học là tháng sau."]]},{"word":"心理学","reading":"しんりがく","meaning":"tâm lí học","hanViet":"TÂM LÝ HỌC","lesson":31,"ex":[["妹は心理学を勉強しています。","Em gái tôi đang học tâm lý học."],["心理学の授業で人の気持ちを勉強します。","Trong giờ tâm lý học, tôi học về cảm xúc của con người."],["心理学の本を買いました。","Tôi đã mua sách tâm lý học."],["心理学はとてもおもしろいです。","Tâm lý học rất thú vị."],["心理学の先生は田中さんです。","Giáo viên dạy tâm lý học là anh Tanaka."]]},{"word":"哲学","reading":"てつがく","meaning":"triết học","hanViet":"TRIẾT HỌC","lesson":31,"ex":[["父は哲学が好きです。","Bố tôi thích triết học."],["哲学の本を読みました。","Tôi đã đọc sách triết học."],["哲学の授業は難しいです。","Giờ học triết học khó."],["哲学の先生は田中さんです。","Giáo viên dạy triết học là anh Tanaka."],["大学で哲学を勉強したいです。","Tôi muốn học triết học ở đại học."]]},{"word":"宗教学","reading":"しゅうきょうがく","meaning":"tôn giáo học","hanViet":"TÔNG GIÁO HỌC","lesson":31,"ex":[["姉は宗教学を勉強しています。","Chị gái tôi đang học tôn giáo học."],["宗教学の授業で教会のことを勉強します。","Trong giờ tôn giáo học, tôi học về nhà thờ."],["宗教学の本を借りました。","Tôi đã mượn sách tôn giáo học."],["宗教学の試験は来週です。","Kỳ thi tôn giáo học là tuần sau."],["宗教学の先生に会いました。","Tôi đã gặp giáo viên dạy tôn giáo học."]]},{"word":"芸術","reading":"げいじゅつ","meaning":"Nghệ thuật","hanViet":"NGHỆ THUẬT","lesson":31,"ex":[["妹は芸術が好きです。","Em gái tôi thích nghệ thuật."],["芸術の本を読みました。","Tôi đã đọc sách nghệ thuật."],["芸術の授業で絵のことを勉強します。","Trong giờ nghệ thuật, tôi học về tranh."],["日本の芸術は美しいです。","Nghệ thuật Nhật Bản đẹp."],["芸術の先生は山田さんです。","Giáo viên dạy nghệ thuật là anh Yamada."]]},{"word":"美術","reading":"びじゅつ","meaning":"Mỹ thuật","hanViet":"MỸ THUẬT","lesson":31,"ex":[["弟は美術が好きです。","Em trai tôi thích mỹ thuật."],["美術の授業で絵を見ます。","Trong giờ mỹ thuật, tôi xem tranh."],["美術の本を買いました。","Tôi đã mua sách mỹ thuật."],["美術館で美術の絵を見ました。","Tôi đã xem tranh mỹ thuật ở bảo tàng mỹ thuật."],["美術の先生は田中さんです。","Giáo viên dạy mỹ thuật là anh Tanaka."]]},{"word":"教会","reading":"きょうかい","meaning":"nhà thờ","hanViet":"GIÁO HỘI","lesson":31,"ex":[["日曜日に教会へ行きます。","Chủ nhật tôi đi nhà thờ."],["教会は駅の近くにあります。","Nhà thờ ở gần ga."],["友達と教会で歌を歌います。","Tôi hát cùng bạn ở nhà thờ."],["あの教会はとても美しいです。","Nhà thờ kia rất đẹp."],["教会の前に大きい木があります。","Trước nhà thờ có cây to."]]},{"word":"大学院","reading":"だいがくいん","meaning":"cao học, cơ sở giáo dục trên đại học","hanViet":"ĐẠI HỌC VIỆN","lesson":31,"ex":[["兄は大学院で勉強しています。","Anh trai tôi đang học ở cao học."],["大学院の試験は難しいです。","Kỳ thi cao học khó."],["大学を卒業して、大学院へ行きます。","Tốt nghiệp đại học rồi tôi sẽ học cao học."],["大学院で薬学を勉強したいです。","Tôi muốn học dược học ở cao học."],["大学院の先生は田中さんです。","Giáo viên ở cao học là anh Tanaka."]]},{"word":"動物園","reading":"どうぶつえん","meaning":"sở thú","hanViet":"ĐỘNG VẬT VIÊN","lesson":31,"ex":[["子どもたちと動物園へ行きました。","Tôi đã đi sở thú cùng bọn trẻ."],["動物園で鳥を見ました。","Tôi đã xem chim ở sở thú."],["日曜日に動物園へ行きます。","Chủ nhật tôi đi sở thú."],["動物園は駅から近いです。","Sở thú gần ga."],["動物園は広いです。","Sở thú rộng."]]},{"word":"インターネット","reading":"インターネット","meaning":"internet","hanViet":"","lesson":31,"ex":[["インターネットで本を買います。","Tôi mua sách trên internet."],["インターネットでニュースを読みます。","Tôi đọc tin tức trên internet."],["インターネットで映画を見ます。","Tôi xem phim trên internet."],["インターネットで友達と話します。","Tôi nói chuyện với bạn trên internet."],["インターネットは便利です。","Internet rất tiện lợi."]]},{"word":"映画館","reading":"えいがかん","meaning":"rạp chiếu phim","hanViet":"ÁNH HỌA QUÁN","lesson":31,"ex":[["映画館で映画を見ます。","Tôi xem phim ở rạp chiếu phim."],["土曜日に映画館へ行きます。","Thứ bảy tôi đi rạp chiếu phim."],["映画館はデパートの近くにあります。","Rạp chiếu phim ở gần trung tâm thương mại."],["友達と映画館へ行きました。","Tôi đã đi rạp chiếu phim cùng bạn."],["映画館の映画はおもしろいです。","Phim ở rạp chiếu phim thú vị."]]},{"word":"都会","reading":"とかい","meaning":"thành phố","hanViet":"ĐÔ HỘI","lesson":31,"ex":[["東京は大きい都会です。","Tokyo là thành phố lớn."],["都会はにぎやかです。","Thành phố nhộn nhịp."],["都会で働きたいです。","Tôi muốn làm việc ở thành phố."],["都会は電車が便利です。","Ở thành phố, tàu điện tiện lợi."],["都会の夜は明るいです。","Ban đêm ở thành phố sáng."]]},{"word":"子供たち","reading":"こどもたち","meaning":"bọn trẻ","hanViet":"TỬ CUNG","lesson":31,"ex":[["子供たちは公園で遊びます。","Bọn trẻ chơi ở công viên."],["子供たちが学校へ行きます。","Bọn trẻ đi học."],["子供たちに本をあげました。","Tôi đã tặng sách cho bọn trẻ."],["子供たちは歌が好きです。","Bọn trẻ thích hát."],["子供たちは元気です。","Bọn trẻ khỏe mạnh."]]},{"word":"集まります","reading":"あつまります","meaning":"tập hợp","hanViet":"TẬP","lesson":31,"ex":[["友達が駅に集まります。","Bạn bè tập hợp ở ga."],["子供たちが公園に集まりました。","Bọn trẻ đã tập hợp ở công viên."],["9時に教室に集まります。","9 giờ chúng tôi tập hợp ở phòng học."],["家族が家に集まります。","Gia đình tập hợp ở nhà."],["学生が図書館の前に集まります。","Sinh viên tập hợp trước thư viện."]]},{"word":"気が付きます","reading":"きがつきます","meaning":"nhận thấy, phát hiện","hanViet":"KHÍ PHÓ","lesson":31,"ex":[["財布がないことに気が付きました。","Tôi đã nhận thấy là không có ví."],["雨が降っていることに気が付きませんでした。","Tôi đã không nhận thấy trời đang mưa."],["友達が来たことに気が付きました。","Tôi đã nhận thấy bạn đã đến."],["鍵を忘れたことに気が付きました。","Tôi đã nhận thấy mình quên chìa khóa."],["母が疲れていることに気が付きました。","Tôi đã nhận thấy mẹ đang mệt."]]},{"word":"運動します","reading":"うんどうします","meaning":"vận động, tập thể thao","hanViet":"VẬN ĐỘNG","lesson":32,"ex":[["毎朝、運動します。","Mỗi sáng tôi tập thể dục."],["毎週、公園で運動します。","Mỗi tuần tôi tập thể dục ở công viên."],["友達と運動します。","Tôi tập thể dục cùng bạn."],["週末に友達と運動します。","Cuối tuần tôi tập thể dục cùng bạn."],["雨の日は家で運動します。","Ngày mưa tôi tập thể dục ở nhà."]]},{"word":"成功します","reading":"せいこうします","meaning":"thành công","hanViet":"THÀNH CÔNG","lesson":32,"ex":[["兄は仕事に成功しました。","Anh trai tôi đã thành công trong công việc."],["田中さんは会社で成功しました。","Anh Tanaka đã thành công ở công ty."],["山田さんは若いときに成功しました。","Anh Yamada đã thành công khi còn trẻ."],["毎日頑張って、成功しました。","Tôi đã cố gắng mỗi ngày và thành công."],["成功するまで、頑張ります。","Tôi sẽ cố gắng cho đến khi thành công."]]},{"word":"失敗します","reading":"しっぱいします","meaning":"thất bại, trượt","hanViet":"THẤT BẠI","lesson":32,"ex":[["試験に失敗しました。","Tôi đã trượt kỳ thi."],["料理に失敗しました。","Tôi đã nấu ăn thất bại."],["仕事に失敗しました。","Tôi đã thất bại trong công việc."],["失敗しても、頑張ります。","Dù thất bại, tôi vẫn cố gắng."],["失敗したくないです。","Tôi không muốn thất bại."]]},{"word":"合格します","reading":"ごうかくします","meaning":"đỗ","hanViet":"HỢP CÁCH","lesson":32,"ex":[["試験に合格しました。","Tôi đã đỗ kỳ thi."],["大学に合格しました。","Tôi đã đỗ đại học."],["合格して、とてもうれしいです。","Đỗ rồi, tôi rất vui."],["合格するために、毎日勉強します。","Để đỗ, tôi học mỗi ngày."],["弟も試験に合格しました。","Em trai tôi cũng đỗ kỳ thi."]]},{"word":"戻ります","reading":"もどります","meaning":"Quay lại, trở về","hanViet":"LỆ","lesson":32,"ex":[["家に戻ります。","Tôi trở về nhà."],["5時に家に戻ります。","5 giờ tôi trở về nhà."],["学校に戻りました。","Tôi đã quay lại trường."],["日本に戻りたいです。","Tôi muốn trở về Nhật Bản."],["友達の家から戻りました。","Tôi đã trở về từ nhà bạn."]]},{"word":"やみます","reading":"やみます","meaning":"tạnh ,ngừng","hanViet":"","lesson":32,"ex":[["雨がやみました。","Mưa đã tạnh."],["雨がやんだら、散歩します。","Khi mưa tạnh, tôi sẽ đi dạo."],["雪がやみました。","Tuyết đã ngừng rơi."],["風がやみました。","Gió đã ngừng thổi."],["午後、雨がやみます。","Buổi chiều mưa sẽ tạnh."]]},{"word":"晴れます","reading":"はれます","meaning":"Trời nắng, quang đãng","hanViet":"TÌNH","lesson":32,"ex":[["明日は晴れます。","Ngày mai trời sẽ nắng."],["今日は晴れました。","Hôm nay trời đã nắng."],["あしたは晴れるでしょう。","Ngày mai có lẽ trời sẽ nắng."],["晴れたら、公園へ行きます。","Nếu trời nắng, tôi sẽ đi công viên."],["空が晴れました。","Bầu trời đã quang đãng."]]},{"word":"曇ります","reading":"くもります","meaning":"Nhiều mây, trở nên u ám","hanViet":"ĐÀM","lesson":32,"ex":[["明日は曇ります。","Ngày mai trời sẽ nhiều mây."],["空が曇りました。","Bầu trời đã trở nên u ám."],["午後は曇るでしょう。","Buổi chiều có lẽ trời sẽ nhiều mây."],["空が曇っています。","Bầu trời đang nhiều mây."],["明日は曇りますか。","Ngày mai trời có nhiều mây không?"]]},{"word":"吹きます","reading":"ふきます","meaning":"thổi","hanViet":"XUY","lesson":32,"ex":[["風が吹きます。","Gió thổi."],["強い風が吹いています。","Gió mạnh đang thổi."],["海で風が吹きます。","Gió thổi ở biển."],["冬は冷たい風が吹きます。","Mùa đông gió lạnh thổi."],["風が強く吹きます。","Gió thổi mạnh."]]},{"word":"治ります","reading":"なおります","meaning":"Khỏi (bệnh), được chữa lành","hanViet":"TRỊ","lesson":32,"ex":[["病気が治りました。","Bệnh đã khỏi."],["かぜが治りました。","Cảm đã khỏi."],["けがが治りました。","Vết thương đã lành."],["もうすぐ治ります。","Sắp khỏi rồi."],["病気が治って、うれしいです。","Bệnh đã khỏi nên tôi vui."]]},{"word":"続きます","reading":"つづきます","meaning":"Tiếp diễn, kéo dài","hanViet":"TỤC","lesson":32,"ex":[["雨が3日続きます。","Mưa kéo dài 3 ngày."],["暑い日が続きます。","Những ngày nóng tiếp diễn."],["会議が2時間続きました。","Cuộc họp kéo dài 2 giờ."],["勉強は毎日続きます。","Việc học tiếp diễn mỗi ngày."],["この映画は2時間続きます。","Bộ phim này kéo dài 2 giờ."]]},{"word":"ひきます","reading":"ひきます","meaning":"bị [cảm]","hanViet":"","lesson":32,"ex":[["かぜをひきました。","Tôi đã bị cảm."],["冬にかぜをひきました。","Tôi đã bị cảm vào mùa đông."],["かぜをひいて、学校を休みました。","Tôi bị cảm nên đã nghỉ học."],["かぜをひきましたから、病院へ行きました。","Vì bị cảm nên tôi đã đi bệnh viện."],["母もかぜをひきました。","Mẹ tôi cũng bị cảm."]]},{"word":"冷やします","reading":"ひやします","meaning":"làm lạnh","hanViet":"LÃNH","lesson":32,"ex":[["水を冷やします。","Tôi làm lạnh nước."],["ビールを冷やします。","Tôi làm lạnh bia."],["ジュースを冷やして、飲みます。","Tôi làm lạnh nước ép rồi uống."],["冷蔵庫で水を冷やします。","Tôi làm lạnh nước trong tủ lạnh."],["お茶を冷やしました。","Tôi đã làm lạnh trà."]]},{"word":"心配な","reading":"しんぱいな","meaning":"Lo lắng","hanViet":"TÂM PHỐI","lesson":32,"ex":[["試験が心配です。","Tôi lo lắng về kỳ thi."],["母の病気が心配です。","Tôi lo lắng về bệnh của mẹ."],["心配なことがあります。","Tôi có điều lo lắng."],["天気が心配です。","Tôi lo lắng về thời tiết."],["弟の試験が心配です。","Tôi lo lắng về kỳ thi của em trai."]]},{"word":"十分な","reading":"じゅうぶんな","meaning":"Đầy đủ, thừa","hanViet":"THẬP PHÂN","lesson":32,"ex":[["お金が十分です。","Tiền đủ rồi."],["時間が十分にあります。","Có đủ thời gian."],["十分な時間があります。","Có thời gian đầy đủ."],["十分な水があります。","Có đủ nước."],["十分に休みました。","Tôi đã nghỉ ngơi đầy đủ."]]},{"word":"おかしい","reading":"おかしい","meaning":"có vấn đề, không bình thường","hanViet":"","lesson":32,"ex":[["この時計はおかしいです。","Chiếc đồng hồ này có vấn đề."],["パソコンがおかしいです。","Máy tính có vấn đề."],["おかしい音がします。","Có tiếng động lạ."],["体がおかしいです。","Cơ thể tôi có gì không ổn."],["あの人はおかしいです。","Người kia kỳ lạ."]]},{"word":"うるさい","reading":"うるさい","meaning":"ồn ào","hanViet":"","lesson":32,"ex":[["隣の部屋がうるさいです。","Phòng bên cạnh ồn ào."],["この町はうるさいです。","Thị trấn này ồn ào."],["子供たちがうるさいです。","Bọn trẻ ồn ào."],["音楽がうるさいです。","Nhạc ồn ào."],["電車の中がうるさいです。","Trong tàu điện ồn ào."]]},{"word":"やけどをします","reading":"やけどをします","meaning":"bị bỏng","hanViet":"","lesson":32,"ex":[["熱い水でやけどをしました。","Tôi đã bị bỏng nước nóng."],["手にやけどをしました。","Tôi bị bỏng ở tay."],["料理をして、やけどをしました。","Tôi nấu ăn và bị bỏng."],["やけどをして、病院へ行きました。","Tôi bị bỏng nên đã đi bệnh viện."],["熱いお茶でやけどをしました。","Tôi đã bị bỏng do trà nóng."]]},{"word":"けがをします","reading":"けがをします","meaning":"bị thương","hanViet":"","lesson":32,"ex":[["足にけがをしました。","Tôi bị thương ở chân."],["けがをして、病院へ行きました。","Tôi bị thương nên đã đi bệnh viện."],["スポーツでけがをしました。","Tôi bị thương khi chơi thể thao."],["弟はけがをしました。","Em trai tôi bị thương."],["けがをして、学校を休みました。","Tôi bị thương nên đã nghỉ học."]]},{"word":"せきをします","reading":"せきをします","meaning":"bị ho","hanViet":"","lesson":32,"ex":[["かぜをひいて、せきをします。","Tôi bị cảm nên ho."],["夜、せきをしました。","Ban đêm tôi đã ho."],["せきをして、病院へ行きました。","Tôi ho nên đã đi bệnh viện."],["せきが止まりません。","Ho không dứt."],["母もせきをしています。","Mẹ tôi cũng đang ho."]]},{"word":"太陽","reading":"たいよう","meaning":"Mặt trời","hanViet":"THÁI DƯƠNG","lesson":32,"ex":[["太陽が明るいです。","Mặt trời sáng."],["太陽が空にあります。","Mặt trời ở trên bầu trời."],["太陽が出ました。","Mặt trời đã mọc."],["太陽を見ました。","Tôi đã nhìn thấy mặt trời."],["太陽の下で遊びます。","Tôi chơi dưới ánh mặt trời."]]},{"word":"星","reading":"ほし","meaning":"Ngôi sao","hanViet":"TINH","lesson":32,"ex":[["星がきれいです。","Sao đẹp."],["星が好きです。","Tôi thích sao."],["空に星がたくさんあります。","Trên bầu trời có nhiều sao."],["星を見ました。","Tôi đã nhìn thấy sao."],["山で星を見ました。","Tôi đã ngắm sao ở núi."]]},{"word":"月","reading":"つき","meaning":"Mặt trăng","hanViet":"NGUYỆT","lesson":32,"ex":[["月がきれいです。","Mặt trăng đẹp."],["夜、月が見えます。","Ban đêm có thể nhìn thấy mặt trăng."],["月を見ました。","Tôi đã nhìn thấy mặt trăng."],["月が空にあります。","Mặt trăng ở trên bầu trời."],["月と星を見ました。","Tôi đã nhìn thấy mặt trăng và sao."]]},{"word":"風","reading":"かぜ","meaning":"gió","hanViet":"PHONG","lesson":32,"ex":[["風が強いです。","Gió mạnh."],["風が冷たいです。","Gió lạnh."],["風が吹いています。","Gió đang thổi."],["海で風が強いです。","Gió mạnh ở biển."],["風が涼しいです。","Gió mát."]]},{"word":"水道","reading":"すいどう","meaning":"Đường nước, nước máy","hanViet":"THỦY ĐẠO","lesson":32,"ex":[["水道の水を飲みます。","Tôi uống nước máy."],["水道が止まりました。","Nước máy đã ngừng chảy."],["水道の水で手を洗います。","Tôi rửa tay bằng nước máy."],["水道の水は冷たいです。","Nước máy lạnh."],["水道の水を使います。","Tôi dùng nước máy."]]},{"word":"今夜","reading":"こんや","meaning":"Tối nay, đêm nay","hanViet":"KIM DẠ","lesson":32,"ex":[["今夜は雨が降ります。","Tối nay trời sẽ mưa."],["今夜、友達に会います。","Tối nay tôi gặp bạn."],["今夜は家にいます。","Tối nay tôi ở nhà."],["今夜、映画を見ます。","Tối nay tôi xem phim."],["今夜は月が見えます。","Tối nay có thể nhìn thấy mặt trăng."]]},{"word":"夕方","reading":"ゆうがた","meaning":"Chiều tối","hanViet":"TỊCH PHƯƠNG","lesson":32,"ex":[["夕方、散歩します。","Chiều tối tôi đi dạo."],["夕方に友達に会います。","Chiều tối tôi gặp bạn."],["夕方は涼しいです。","Chiều tối mát mẻ."],["夕方、雨が降りました。","Chiều tối trời đã mưa."],["夕方に家に帰ります。","Chiều tối tôi về nhà."]]},{"word":"遅く","reading":"おそく","meaning":"muộn , khuya","hanViet":"TRÌ","lesson":32,"ex":[["遅くまで勉強します。","Tôi học đến khuya."],["遅くまで働きます。","Tôi làm việc đến khuya."],["遅く起きました。","Tôi đã dậy muộn."],["遅くまでテレビを見ます。","Tôi xem tivi đến khuya."],["遅くに家に帰りました。","Tôi đã về nhà muộn."]]},{"word":"こんなに","reading":"こんなに","meaning":"như thế này","hanViet":"","lesson":32,"ex":[["こんなに暑いです。","Nóng như thế này."],["こんなにたくさんの本があります。","Có nhiều sách như thế này."],["こんなに難しいです。","Khó như thế này."],["こんなに楽しいです。","Vui như thế này."],["こんなに安いです。","Rẻ như thế này."]]},{"word":"そんなに","reading":"そんなに","meaning":"như thế đó","hanViet":"","lesson":32,"ex":[["そんなに暑くありません。","Không nóng đến thế."],["そんなに難しくありません。","Không khó đến thế."],["そんなに高くありません。","Không đắt đến thế."],["そんなに食べません。","Tôi không ăn nhiều đến thế."],["そんなに忙しくありません。","Tôi không bận đến thế."]]},{"word":"もしかしたら","reading":"もしかしたら","meaning":"có thể, biết đâu là, có khả năng","hanViet":"","lesson":32,"ex":[["もしかしたら、明日は雨かもしれません。","Có thể ngày mai trời sẽ mưa."],["もしかしたら、田中さんが来るかもしれません。","Có thể anh Tanaka sẽ đến."],["もしかしたら、試験に合格するかもしれません。","Có thể tôi sẽ đỗ kỳ thi."],["もしかしたら、彼は学生かもしれません。","Có thể anh ấy là học sinh."],["もしかしたら、明日は晴れるかもしれません。","Có thể ngày mai trời sẽ nắng."]]},{"word":"それはいけませんね","reading":"それはいけませんね","meaning":"thế thì thật không tốt.","hanViet":"","lesson":32,"ex":[["それはいけませんね。病気ですから、休んでください。","Thế thì không tốt. Vì bị ốm nên hãy nghỉ ngơi."],["それはいけませんね。病院へ行ったほうがいいです。","Thế thì không tốt. Bạn nên đi bệnh viện."],["それはいけませんね。薬を飲んでください。","Thế thì không tốt. Hãy uống thuốc."],["それはいけませんね。先生に聞いてください。","Thế thì không tốt. Hãy hỏi thầy giáo."],["それはいけませんね。友達に手伝ってもらってください。","Thế thì không tốt. Hãy nhờ bạn giúp đỡ."]]},{"word":"胃","reading":"い","meaning":"Dạ dày","hanViet":"VỊ","lesson":32,"ex":[["胃が重いです。","Dạ dày tôi nặng."],["胃の薬を飲みます。","Tôi uống thuốc dạ dày."],["胃が悪いです。","Dạ dày tôi không tốt."],["胃のために、ゆっくり食べます。","Vì dạ dày, tôi ăn chậm rãi."],["胃が弱いです。","Dạ dày tôi yếu."]]},{"word":"働きすぎ","reading":"はたらきすぎ","meaning":"làm việc quá sức","hanViet":"ĐỘNG","lesson":32,"ex":[["働きすぎは体に悪いです。","Làm việc quá sức không tốt cho cơ thể."],["働きすぎで病気になりました。","Tôi bị ốm do làm việc quá sức."],["父は働きすぎです。","Bố tôi làm việc quá sức."],["働きすぎはよくありません。","Làm việc quá sức không tốt."],["働きすぎで疲れました。","Tôi mệt vì làm việc quá sức."]]},{"word":"無理をします","reading":"むりをします","meaning":"làm quá sức","hanViet":"VÔ LÝ","lesson":32,"ex":[["病気ですから、無理をしません。","Vì bị ốm nên tôi không làm quá sức."],["無理をしないでください。","Xin đừng làm quá sức."],["無理をして、病気になりました。","Tôi làm quá sức nên đã bị ốm."],["無理をすると、体に悪いです。","Làm quá sức thì không tốt cho cơ thể."],["今日は無理をしません。","Hôm nay tôi không làm quá sức."]]},{"word":"ゆっくりします","reading":"ゆっくりします","meaning":"nghỉ ngơi, thư thái, dưỡng sức","hanViet":"","lesson":32,"ex":[["休みの日は家でゆっくりします。","Ngày nghỉ tôi nghỉ ngơi thư thái ở nhà."],["お風呂でゆっくりします。","Tôi thư giãn trong bồn tắm."],["今日はゆっくりします。","Hôm nay tôi nghỉ ngơi thư thái."],["仕事のあと、ゆっくりします。","Sau công việc, tôi nghỉ ngơi thư thái."],["ゆっくりして、元気になりました。","Tôi đã nghỉ ngơi thư thái và khỏe lại."]]},{"word":"星占い","reading":"ほしうらない","meaning":"bói sao","hanViet":"TINH CHIÊM","lesson":32,"ex":[["星占いが好きです。","Tôi thích bói sao."],["毎朝、星占いを見ます。","Mỗi sáng tôi xem bói sao."],["テレビで星占いを見ます。","Tôi xem bói sao trên tivi."],["星占いはおもしろいです。","Bói sao thú vị."],["新聞で星占いを読みます。","Tôi đọc bói sao trên báo."]]},{"word":"牡牛座","reading":"おうしざ","meaning":"chòm sao Kim Ngưu","hanViet":"MẪU NGƯU TỌA","lesson":32,"ex":[["私は牡牛座です。","Tôi thuộc chòm sao Kim Ngưu."],["母は牡牛座です。","Mẹ tôi thuộc chòm sao Kim Ngưu."],["牡牛座の友達がいます。","Tôi có bạn thuộc chòm Kim Ngưu."],["今日の牡牛座はいいです。","Hôm nay chòm Kim Ngưu tốt."],["田中さんは牡牛座です。","Anh Tanaka thuộc chòm Kim Ngưu."]]},{"word":"困ります","reading":"こまります","meaning":"Gặp khó khăn, bối rối","hanViet":"KHỐN","lesson":32,"ex":[["お金がなくて、困ります。","Tôi hết tiền nên gặp khó khăn."],["雨が降って、困りました。","Trời mưa nên tôi gặp khó khăn."],["日本語がわからなくて、困ります。","Tôi không hiểu tiếng Nhật nên gặp khó khăn."],["困ったら、友達に聞きます。","Khi gặp khó khăn, tôi hỏi bạn."],["財布を忘れて、困りました。","Tôi quên ví nên gặp khó khăn."]]},{"word":"宝くじ","reading":"たからくじ","meaning":"xổ số","hanViet":"BẢO","lesson":32,"ex":[["宝くじを買いました。","Tôi đã mua vé số."],["宝くじで1万円当たりました。","Tôi đã trúng 10.000 yên xổ số."],["宝くじを毎週買います。","Tôi mua vé số mỗi tuần."],["宝くじは店で買います。","Vé số mua ở cửa hàng."],["宝くじが当たったら、車を買います。","Nếu trúng xổ số, tôi sẽ mua xe."]]},{"word":"当たります","reading":"あたります","meaning":"trúng(số)","hanViet":"ĐƯƠNG","lesson":32,"ex":[["宝くじに当たりました。","Tôi đã trúng xổ số."],["ボールが体に当たりました。","Quả bóng đã trúng vào người tôi."],["宝くじが当たったら、旅行に行きます。","Nếu trúng xổ số, tôi sẽ đi du lịch."],["当たって、うれしいです。","Trúng rồi, tôi vui."],["当たらなくて、残念です。","Không trúng nên tôi tiếc."]]},{"word":"健康","reading":"けんこう","meaning":"Sức khoẻ; khoẻ mạnh","hanViet":"KIỆN KHANG","lesson":32,"ex":[["健康は大切です。","Sức khỏe quan trọng."],["健康のために、野菜を食べます。","Vì sức khỏe, tôi ăn rau."],["健康で、元気です。","Tôi khỏe mạnh và tràn đầy sức sống."],["健康を大切にします。","Tôi trân trọng sức khỏe."],["健康のために、毎日歩きます。","Vì sức khỏe, tôi đi bộ mỗi ngày."]]},{"word":"恋愛","reading":"れんあい","meaning":"tình yêu","hanViet":"LUYẾN ÁI","lesson":32,"ex":[["恋愛の映画が好きです。","Tôi thích phim tình yêu."],["恋愛の本を読みました。","Tôi đã đọc sách tình yêu."],["恋愛の歌を歌います。","Tôi hát bài hát tình yêu."],["恋愛は難しいです。","Tình yêu khó."],["恋愛は楽しいです。","Tình yêu vui vẻ."]]},{"word":"恋人","reading":"こいびと","meaning":"Người yêu","hanViet":"LUYẾN NHÂN","lesson":32,"ex":[["恋人がいます。","Tôi có người yêu."],["恋人と映画を見ます。","Tôi xem phim cùng người yêu."],["恋人と公園へ行きます。","Tôi đi công viên cùng người yêu."],["恋人に花をあげました。","Tôi đã tặng hoa cho người yêu."],["恋人とごはんを食べます。","Tôi ăn cơm cùng người yêu."]]},{"word":"金持ち","reading":"かねもち","meaning":"người giàu có, người có nhiều tiền","hanViet":"KIM TRÌ","lesson":32,"ex":[["田中さんは金持ちです。","Anh Tanaka giàu có."],["金持ちの人は大きい家に住んでいます。","Người giàu sống trong nhà lớn."],["金持ちになりたいです。","Tôi muốn trở nên giàu có."],["金持ちの友達がいます。","Tôi có bạn giàu có."],["あの人は金持ちです。","Người kia giàu có."]]},{"word":"天気予報","reading":"てんきよほう","meaning":"Dự báo thời tiết","hanViet":"THIÊN KHÍ DỰ BÁO","lesson":32,"ex":[["天気予報を見ます。","Tôi xem dự báo thời tiết."],["テレビで天気予報を見ます。","Tôi xem dự báo thời tiết trên tivi."],["天気予報では明日は雨です。","Theo dự báo thời tiết, ngày mai trời mưa."],["朝、天気予報を聞きます。","Buổi sáng tôi nghe dự báo thời tiết."],["天気予報を見て、傘を持っていきます。","Tôi xem dự báo thời tiết rồi mang theo ô."]]},{"word":"降水確率","reading":"こうすいかりつ","meaning":"xác suất mưa","hanViet":"GIÁNG THỦY XÁC SUẤT","lesson":32,"ex":[["きょうの降水確率は80パーセントです。","Xác suất mưa hôm nay là 80 phần trăm."],["あしたの降水確率は10パーセントですから、傘は要りません。","Xác suất mưa ngày mai là 10 phần trăm nên không cần ô."],["テレビで降水確率を聞きました。","Tôi đã nghe xác suất mưa trên ti vi."],["降水確率が高いですから、洗濯物をうちの中に入れました。","Vì xác suất mưa cao nên tôi đã mang đồ giặt vào trong nhà."],["旅行の前に降水確率を調べます。","Trước khi đi du lịch, tôi kiểm tra xác suất mưa."]]},{"word":"最高気温","reading":"さいこうきおん","meaning":"nhiệt độ cao nhất","hanViet":"TỐI CAO KHÍ ÔN","lesson":32,"ex":[["きょうの最高気温はきのうより高いです。","Nhiệt độ cao nhất hôm nay cao hơn hôm qua."],["夏の最高気温はとても高いです。","Nhiệt độ cao nhất mùa hè rất cao."],["東京の最高気温は京都より低いです。","Nhiệt độ cao nhất ở Tokyo thấp hơn Kyoto."],["最高気温が高い日は水をたくさん飲みます。","Những ngày nhiệt độ cao nhất cao, tôi uống nhiều nước."],["新聞で明日の最高気温を調べました。","Tôi đã tra nhiệt độ cao nhất ngày mai trên báo."]]},{"word":"最低気温","reading":"さいていきおん","meaning":"nhiệt độ thấp nhất","hanViet":"TỐI ĐÊ KHÍ ÔN","lesson":32,"ex":[["きょうの最低気温はとても低いです。","Nhiệt độ thấp nhất hôm nay rất thấp."],["冬の最低気温はとても低いですから、コートを着ます。","Vì nhiệt độ thấp nhất mùa đông rất thấp nên tôi mặc áo khoác."],["明日の最低気温はきょうより高いでしょう。","Nhiệt độ thấp nhất ngày mai có lẽ cao hơn hôm nay."],["最低気温が低い日は早く家へ帰ります。","Những ngày nhiệt độ thấp nhất thấp, tôi về nhà sớm."],["テレビで最低気温を聞いて、セーターを着ました。","Tôi nghe nhiệt độ thấp nhất trên ti vi rồi mặc áo len."]]},{"word":"曇り","reading":"くもり","meaning":"Trời nhiều mây","hanViet":"ĐÀM","lesson":32,"ex":[["きょうは曇りです。","Hôm nay trời nhiều mây."],["あしたも曇りでしょう。","Ngày mai có lẽ cũng nhiều mây."],["曇りの日は洗濯物が乾きません。","Những ngày nhiều mây, đồ giặt không khô."],["曇りですが、雨は降りません。","Trời nhiều mây nhưng không mưa."],["きのうは曇りでしたから、海へ行きませんでした。","Hôm qua trời nhiều mây nên tôi đã không đi biển."]]},{"word":"雪","reading":"ゆき","meaning":"tuyết","hanViet":"TUYẾT","lesson":32,"ex":[["冬は雪がたくさん降ります。","Mùa đông tuyết rơi nhiều."],["雪が降りましたから、道が白いです。","Vì tuyết đã rơi nên đường trắng xóa."],["子どもは雪で遊びます。","Trẻ con chơi với tuyết."],["雪の日に車を運転しません。","Ngày có tuyết tôi không lái xe."],["東京に雪が降りました。","Ở Tokyo đã có tuyết rơi."]]},{"word":"晴れのち曇り","reading":"はれのちくもり","meaning":"nắng sau đó chuyển mây","hanViet":"TÌNH ĐÀM","lesson":32,"ex":[["きょうの天気は晴れのち曇りです。","Thời tiết hôm nay nắng rồi chuyển mây."],["あしたは晴れのち曇りですから、午後は傘を持っていきます。","Ngày mai nắng rồi chuyển mây nên buổi chiều tôi sẽ mang ô theo."],["天気予報は晴れのち曇りでした。","Dự báo thời tiết là nắng rồi chuyển mây."],["晴れのち曇りの日は洗濯物を早く入れます。","Ngày nắng rồi chuyển mây, tôi thu đồ giặt sớm."],["東京は晴れのち曇りですが、京都は雨です。","Tokyo nắng rồi chuyển mây nhưng Kyoto thì mưa."]]},{"word":"曇り時々雨","reading":"くもりときどきあめ","meaning":"có mây thỉnh thoảng có mưa","hanViet":"ĐÀM THỜI VŨ","lesson":32,"ex":[["きょうの天気は曇り時々雨です。","Thời tiết hôm nay có mây, thỉnh thoảng có mưa."],["あしたは曇り時々雨ですから、傘を持っていきます。","Ngày mai có mây thỉnh thoảng mưa nên tôi mang ô theo."],["曇り時々雨の日は出かけません。","Ngày có mây thỉnh thoảng mưa tôi không ra ngoài."],["天気予報は曇り時々雨でしたが、雨は降りませんでした。","Dự báo thời tiết là có mây thỉnh thoảng mưa nhưng trời đã không mưa."],["曇り時々雨ですが、山田さんは散歩します。","Trời có mây thỉnh thoảng mưa nhưng anh Yamada vẫn đi dạo."]]},{"word":"曇り所によって雨","reading":"くもりところによってあめ","meaning":"có mây, một vài nơi có mưa","hanViet":"ĐÀM SỞ VŨ","lesson":32,"ex":[["きょうの天気は曇り所によって雨です。","Thời tiết hôm nay có mây, một vài nơi có mưa."],["東京は曇り所によって雨ですが、京都はいい天気です。","Tokyo có mây, một vài nơi có mưa, nhưng Kyoto thì trời đẹp."],["曇り所によって雨ですから、傘を持っていったほうがいいです。","Vì trời có mây, một vài nơi có mưa nên mang ô theo thì tốt hơn."],["天気予報は曇り所によって雨でした。","Dự báo thời tiết là có mây, một vài nơi có mưa."],["曇り所によって雨の日は、山へ行きません。","Ngày có mây, một vài nơi có mưa, tôi không đi núi."]]},{"word":"にわか雨","reading":"にわかあめ","meaning":"mưa bất chợt, mưa rào","hanViet":"VŨ","lesson":32,"ex":[["午後ににわか雨が降りました。","Buổi chiều đã có mưa rào bất chợt."],["にわか雨が降りましたから、すぐ家へ帰りました。","Vì mưa rào bất chợt nên tôi đã về nhà ngay."],["にわか雨が降りましたから、洗濯物を入れました。","Vì mưa rào bất chợt nên tôi đã thu đồ giặt vào."],["夏はにわか雨が多いです。","Mùa hè mưa rào bất chợt nhiều."],["にわか雨でしたが、すぐ晴れました。","Trời mưa rào bất chợt nhưng nhanh chóng nắng trở lại."]]},{"word":"雷","reading":"かみなり","meaning":"sấm sét","hanViet":"LÔI","lesson":32,"ex":[["雷が鳴りました。","Sấm đã vang lên."],["雷が怖いです。","Tôi sợ sấm sét."],["雷が鳴っていますから、外へ出ません。","Vì sấm đang vang nên tôi không ra ngoài."],["夜、雷と雨がひどかったです。","Ban đêm, sấm và mưa rất dữ dội."],["子どもは雷の音を聞いて、泣きました。","Đứa trẻ nghe tiếng sấm và đã khóc."]]},{"word":"台風","reading":"たいふう","meaning":"Cơn bão","hanViet":"ĐÀI PHONG","lesson":32,"ex":[["台風が来ました。","Bão đã đến."],["台風ですから、学校は休みです。","Vì có bão nên trường học nghỉ."],["台風が来ますから、窓を閉めます。","Vì bão sắp đến nên tôi đóng cửa sổ."],["台風で電車が止まりました。","Vì bão mà tàu điện đã dừng."],["台風のあと、空はきれいになりました。","Sau bão, bầu trời đã trở nên đẹp."]]},{"word":"虹","reading":"にじ","meaning":"cầu vồng","hanViet":"HỒNG","lesson":32,"ex":[["雨のあと、虹が見えました。","Sau cơn mưa, tôi đã thấy cầu vồng."],["空に虹がかかっています。","Trên trời có cầu vồng."],["虹はとてもきれいです。","Cầu vồng rất đẹp."],["子どもは虹を見て、笑いました。","Đứa trẻ thấy cầu vồng và đã cười."],["虹の写真を撮りました。","Tôi đã chụp ảnh cầu vồng."]]},{"word":"湿度","reading":"しつど","meaning":"Độ ẩm","hanViet":"THẤP ĐỘ","lesson":32,"ex":[["きょうの湿度は80パーセントです。","Độ ẩm hôm nay là 80 phần trăm."],["夏は湿度が高いです。","Mùa hè độ ẩm cao."],["湿度が高い日は蒸し暑いです。","Ngày độ ẩm cao thì oi bức."],["部屋の湿度を調べました。","Tôi đã kiểm tra độ ẩm trong phòng."],["湿度が低い日は水をたくさん飲みます。","Ngày độ ẩm thấp tôi uống nhiều nước."]]},{"word":"蒸し暑い","reading":"むしあつい","meaning":"Oi bức, nóng ẩm","hanViet":"CHƯNG THỬ","lesson":32,"ex":[["きょうは蒸し暑いです。","Hôm nay oi bức."],["夏の東京は蒸し暑いです。","Mùa hè ở Tokyo oi bức."],["蒸し暑い日はエアコンをつけます。","Ngày oi bức tôi bật điều hòa."],["蒸し暑いですから、シャワーを浴びます。","Vì oi bức nên tôi tắm vòi sen."],["雨の前の日は蒸し暑いです。","Ngày trước cơn mưa thì oi bức."]]},{"word":"さわやかな","reading":"さわやかな","meaning":"thoáng, ráo","hanViet":"","lesson":32,"ex":[["秋はさわやかな季節です。","Mùa thu là mùa thoáng mát."],["さわやかな風が吹いています。","Gió mát đang thổi."],["雨のあとの空気はさわやかです。","Không khí sau mưa thoáng mát."],["さわやかな朝に散歩します。","Tôi đi dạo vào buổi sáng thoáng mát."],["海の風はさわやかです。","Gió biển thoáng mát."]]},{"word":"インフルエンザ","reading":"インフルエンザ","meaning":"bệnh cúm","hanViet":"","lesson":32,"ex":[["冬はインフルエンザに気をつけます。","Mùa đông tôi cẩn thận với bệnh cúm."],["インフルエンザになりました。","Tôi đã bị cúm."],["インフルエンザで学校を休みました。","Tôi đã nghỉ học vì bị cúm."],["インフルエンザの薬を飲みました。","Tôi đã uống thuốc cúm."],["インフルエンザの人が多いですから、手をよく洗います。","Vì nhiều người bị cúm nên tôi rửa tay kỹ."]]},{"word":"北","reading":"きた","meaning":"phía bắc","hanViet":"BẮC","lesson":32,"ex":[["日本の北は寒いです。","Phía bắc Nhật Bản lạnh."],["駅は家の北にあります。","Ga ở phía bắc nhà tôi."],["北の風が吹いています。","Gió bắc đang thổi."],["北へ行くと、雪が多くなります。","Đi về phía bắc, tuyết nhiều hơn."],["北の空は曇っています。","Bầu trời phía bắc đang nhiều mây."]]},{"word":"南","reading":"みなみ","meaning":"phía nam","hanViet":"NAM","lesson":32,"ex":[["日本の南は暖かいです。","Phía nam Nhật Bản ấm áp."],["海は学校の南にあります。","Biển ở phía nam trường học."],["南の風が吹いています。","Gió nam đang thổi."],["南へ行くと、暖かくなります。","Đi về phía nam, trời ấm lên."],["南の島へ旅行しました。","Tôi đã đi du lịch đảo phía nam."]]},{"word":"西","reading":"にし","meaning":"phía tây","hanViet":"TÂY","lesson":32,"ex":[["夕方、太陽は西に見えます。","Buổi chiều, mặt trời hiện ở phía tây."],["山は町の西にあります。","Núi ở phía tây thị trấn."],["西の空が赤いです。","Bầu trời phía tây đỏ rực."],["西へ行くと、海があります。","Đi về phía tây có biển."],["西の空に月が見えます。","Trăng hiện trên bầu trời phía tây."]]},{"word":"東","reading":"ひがし","meaning":"phía đông","hanViet":"ĐÔNG","lesson":32,"ex":[["太陽は東から出ます。","Mặt trời mọc từ phía đông."],["東京は日本の東にあります。","Tokyo ở phía đông Nhật Bản."],["東の空が明るいです。","Bầu trời phía đông sáng."],["東へ行くと、海があります。","Đi về phía đông có biển."],["東の風が吹いています。","Gió đông đang thổi."]]},{"word":"エンジン","reading":"エンジン","meaning":"động cơ","hanViet":"","lesson":32,"ex":[["車のエンジンが壊れました。","Động cơ xe đã hỏng."],["エンジンをかけました。","Tôi đã khởi động động cơ."],["エンジンの音が大きいです。","Tiếng động cơ to."],["寒い日はエンジンがかかりません。","Ngày lạnh động cơ không nổ máy."],["エンジンを止めました。","Tôi đã tắt động cơ."]]},{"word":"チーム","reading":"チーム","meaning":"đội","hanViet":"","lesson":32,"ex":[["私のチームは試合に勝ちました。","Đội của tôi đã thắng trận đấu."],["チームの友達と練習します。","Tôi luyện tập cùng bạn trong đội."],["サッカーのチームに入りました。","Tôi đã vào đội bóng đá."],["チームは5人です。","Đội có 5 người."],["チームで旅行しました。","Cả đội đã đi du lịch cùng nhau."]]},{"word":"前","reading":"まえ","meaning":"trước","hanViet":"TIỀN","lesson":32,"ex":[["学校の前に公園があります。","Trước trường học có công viên."],["食事の前に手を洗います。","Trước khi ăn tôi rửa tay."],["試験の前にたくさん勉強しました。","Trước kỳ thi tôi đã học nhiều."],["駅の前で友達に会いました。","Tôi đã gặp bạn trước ga."],["寝る前に本を読みます。","Trước khi ngủ tôi đọc sách."]]},{"word":"あんなに","reading":"あんなに","meaning":"như thế kia","hanViet":"","lesson":32,"ex":[["あんなに雨が降るとは思いませんでした。","Tôi không nghĩ mưa lại rơi nhiều như thế."],["あんなに暑い日は初めてです。","Ngày nóng như thế kia là lần đầu tiên."],["あんなにたくさん食べられません。","Tôi không ăn được nhiều như thế."],["あんなに速く走れません。","Tôi không chạy nhanh được như thế."],["あんなに高い山に登れません。","Tôi không leo được ngọn núi cao như thế."]]},{"word":"オリンピック","reading":"オリンピック","meaning":"olympic","hanViet":"","lesson":32,"ex":[["オリンピックは4年に1かいあります。","Olympic có 1 lần trong 4 năm."],["オリンピックをテレビで見ました。","Tôi đã xem Olympic trên ti vi."],["日本でオリンピックがありました。","Olympic đã diễn ra ở Nhật Bản."],["オリンピックの試合はおもしろいです。","Các trận đấu Olympic rất thú vị."],["オリンピックに出たいです。","Tôi muốn tham dự Olympic."]]},{"word":"元気","reading":"げんき","meaning":"khỏe mạnh","hanViet":"NGUYÊN KHÍ","lesson":32,"ex":[["田中さんは元気です。","Anh Tanaka khỏe mạnh."],["元気ですか。","Bạn có khỏe không?"],["祖父は80歳ですが、元気です。","Ông tôi 80 tuổi nhưng vẫn khỏe mạnh."],["病気でしたが、もう元気になりました。","Tôi đã bị ốm nhưng giờ đã khỏe lại."],["元気な子どもが公園で遊んでいます。","Đứa trẻ khỏe mạnh đang chơi ở công viên."]]},{"word":"ストレス","reading":"ストレス","meaning":"stress, căng thẳng tâm lý","hanViet":"","lesson":32,"ex":[["仕事のストレスが多いです。","Stress công việc nhiều."],["ストレスで寝られません。","Vì stress nên tôi không ngủ được."],["ストレスが多いですから、ゆっくり休みます。","Vì nhiều stress nên tôi nghỉ ngơi thong thả."],["試験のストレスで、ごはんが食べられません。","Vì stress thi cử nên tôi không ăn được cơm."],["散歩すると、ストレスが少なくなります。","Đi dạo thì stress giảm bớt."]]},{"word":"やけど","reading":"やけど","meaning":"bỏng","hanViet":"","lesson":32,"ex":[["お風呂でやけどをしました。","Tôi bị bỏng trong bồn tắm."],["顔にやけどをしました。","Tôi bị bỏng ở mặt."],["やけどが痛いです。","Vết bỏng đau quá."],["やけどをして、泣きました。","Tôi bị bỏng và đã khóc."],["やけどの薬を買いました。","Tôi đã mua thuốc trị bỏng."]]},{"word":"けが","reading":"けが","meaning":"bị thương","hanViet":"","lesson":32,"ex":[["サッカーでけがをしました。","Tôi đã bị thương khi chơi bóng đá."],["けがをして、会社を休みました。","Tôi bị thương nên đã nghỉ làm."],["頭にけがをしました。","Tôi bị thương ở đầu."],["けがはもうよくなりました。","Vết thương đã đỡ rồi."],["けがに気をつけてください。","Hãy cẩn thận đừng bị thương."]]},{"word":"せき","reading":"せき","meaning":"ho","hanViet":"","lesson":32,"ex":[["せきが出ます。","Tôi bị ho."],["朝、せきが出ます。","Buổi sáng tôi bị ho."],["せきが出ますから、病院へ行きます。","Vì bị ho nên tôi đi bệnh viện."],["夜、せきがひどいです。","Ban đêm cơn ho dữ dội."],["せきの薬を飲みました。","Tôi đã uống thuốc ho."]]},{"word":"逃げます","reading":"にげます","meaning":"Chạy trốn, bỏ chạy","hanViet":"ĐÀO","lesson":33,"ex":[["犬から逃げました。","Tôi đã chạy trốn khỏi con chó."],["泥棒は警察から逃げました。","Tên trộm đã chạy trốn khỏi cảnh sát."],["地震ですから、外へ逃げました。","Vì động đất nên tôi đã chạy ra ngoài."],["猫は犬から逃げます。","Con mèo chạy trốn khỏi con chó."],["火事ですから、早く逃げてください。","Vì có hỏa hoạn nên hãy chạy trốn nhanh."]]},{"word":"騒ぎます","reading":"さわぎます","meaning":"làm ồn, nhốn nháo","hanViet":"TAO","lesson":33,"ex":[["子どもが騒いでいます。","Trẻ con đang làm ồn."],["夜、隣の人が騒ぎました。","Ban đêm, người hàng xóm đã làm ồn."],["教室で騒がないでください。","Đừng làm ồn trong lớp học."],["試合に勝って、みんなが騒ぎました。","Thắng trận đấu, mọi người đều nhốn nháo vui mừng."],["犬が騒いで、寝られませんでした。","Con chó làm ồn nên tôi không ngủ được."]]},{"word":"あきらめます","reading":"あきらめます","meaning":"từ bỏ, đầu hàng","hanViet":"","lesson":33,"ex":[["試験に落ちましたが、あきらめません。","Tôi đã trượt kỳ thi nhưng không từ bỏ."],["雨ですが、あきらめないで、山に登ります。","Trời mưa nhưng đừng từ bỏ, hãy leo núi."],["あきらめないで、もう一度やってみます。","Đừng từ bỏ, tôi sẽ thử lại lần nữa."],["彼は全然あきらめませんでした。","Anh ấy hoàn toàn không từ bỏ."],["難しいですが、あきらめません。","Khó nhưng tôi không từ bỏ."]]},{"word":"投げます","reading":"なげます","meaning":"Ném, vứt","hanViet":"ĐẦU","lesson":33,"ex":[["ボールを投げました。","Tôi đã ném quả bóng."],["紙を投げないでください。","Đừng ném giấy."],["石を川へ投げました。","Tôi đã ném đá xuống sông."],["子どもはボールを高く投げました。","Đứa trẻ đã ném bóng lên cao."],["ボールを友達に投げました。","Tôi đã ném bóng cho bạn."]]},{"word":"守ります","reading":"まもります","meaning":"bảo vệ, giữ, tuân thủ","hanViet":"THỦ","lesson":33,"ex":[["規則を守ります。","Tôi tuân thủ nội quy."],["子どもを守ります。","Tôi bảo vệ trẻ con."],["約束を守りました。","Tôi đã giữ lời hứa."],["信号を守ります。","Tôi tuân thủ tín hiệu giao thông."],["時間を守ります。","Tôi giữ đúng giờ."]]},{"word":"上げます","reading":"あげます","meaning":"nâng lên, tăng lên","hanViet":"THƯỢNG","lesson":33,"ex":[["手を上げます。","Tôi giơ tay lên."],["値段を上げました。","Tôi đã tăng giá."],["声を上げて、歌います。","Tôi cất cao giọng hát."],["荷物を上に上げました。","Tôi đã nâng hành lý lên trên."],["給料を上げてください。","Hãy tăng lương cho tôi."]]},{"word":"下げます","reading":"さげます","meaning":"hạ xuống, giảm xuống","hanViet":"HẠ","lesson":33,"ex":[["手を下げます。","Tôi hạ tay xuống."],["値段を下げました。","Tôi đã giảm giá."],["声を下げて、話します。","Tôi hạ giọng nói."],["荷物を下に下げました。","Tôi đã hạ hành lý xuống dưới."],["カーテンを下げました。","Tôi đã hạ rèm xuống."]]},{"word":"伝えます","reading":"つたえます","meaning":"Truyền đạt, cho biết","hanViet":"TRUYỀN","lesson":33,"ex":[["田中さんに伝えます。","Tôi sẽ cho anh Tanaka biết."],["母に電話で伝えます。","Tôi sẽ báo cho mẹ qua điện thoại."],["先生に伝えてください。","Hãy truyền đạt cho thầy giáo."],["友達の住所を伝えます。","Tôi sẽ cho biết địa chỉ của bạn tôi."],["この話をみんなに伝えます。","Tôi sẽ kể chuyện này cho mọi người."]]},{"word":"注意します","reading":"ちゅういします","meaning":"chú ý, nhắc nhở","hanViet":"CHÚ Ý","lesson":33,"ex":[["車に注意します。","Tôi chú ý xe cộ."],["先生は学生に注意しました。","Thầy giáo đã nhắc nhở học sinh."],["火に注意してください。","Hãy chú ý lửa."],["けがに注意します。","Tôi chú ý đừng bị thương."],["道に注意して、歩きます。","Tôi chú ý đường và đi bộ."]]},{"word":"外します","reading":"はずします","meaning":"rời, không có ở (chỗ ngồi)","hanViet":"NGOẠI","lesson":33,"ex":[["田中さんは今、席を外しています。","Anh Tanaka hiện đang rời khỏi chỗ ngồi."],["課長は席を外しました。","Trưởng phòng đã rời khỏi chỗ ngồi."],["ちょっと席を外します。","Tôi rời khỏi chỗ ngồi một chút."],["山田さんは席を外していますから、あとで電話をください。","Anh Yamada đang rời chỗ ngồi nên hãy gọi lại sau."],["社長は今、席を外しています。","Giám đốc hiện đang rời khỏi chỗ ngồi."]]},{"word":"だめな","reading":"だめな","meaning":"không được, không thể","hanViet":"","lesson":33,"ex":[["ここでたばこを吸うのはだめです。","Hút thuốc ở đây là không được."],["学校に遅れるのはだめです。","Đi học muộn là không được."],["子どもが一人で出かけるのはだめです。","Trẻ con đi ra ngoài một mình là không được."],["この部屋で食べるのはだめです。","Ăn trong phòng này là không được."],["宿題をしないのはだめです。","Không làm bài tập là không được."]]},{"word":"席","reading":"せき","meaning":"Chỗ ngồi, ghế","hanViet":"TỊCH","lesson":33,"ex":[["席に座ります。","Tôi ngồi vào chỗ."],["席はまだありますか。","Vẫn còn chỗ ngồi chứ?"],["席を予約しました。","Tôi đã đặt chỗ ngồi."],["先生の席はここです。","Chỗ ngồi của thầy giáo ở đây."],["窓のそばの席が好きです。","Tôi thích chỗ ngồi cạnh cửa sổ."]]},{"word":"洗濯機","reading":"せんたくき","meaning":"Máy giặt","hanViet":"TẨY TRẠC CƠ","lesson":33,"ex":[["洗濯機で服を洗います。","Tôi giặt quần áo bằng máy giặt."],["洗濯機が壊れました。","Máy giặt đã hỏng."],["新しい洗濯機を買いました。","Tôi đã mua máy giặt mới."],["洗濯機の音が大きいです。","Tiếng máy giặt to."],["洗濯機に洗濯物を入れました。","Tôi đã cho đồ giặt vào máy giặt."]]},{"word":"～機","reading":"～き","meaning":"máy ~","hanViet":"CƠ","lesson":33,"ex":[["飛行機で東京へ行きます。","Tôi đi Tokyo bằng máy bay."],["洗濯機はとても便利です。","Máy giặt rất tiện lợi."],["飛行機は速いです。","Máy bay nhanh."],["この機械は新しいです。","Cái máy này mới."],["機械が壊れました。","Cái máy đã hỏng."]]},{"word":"規則","reading":"きそく","meaning":"Quy tắc, nội quy","hanViet":"QUY TẮC","lesson":33,"ex":[["学校の規則を守ります。","Tôi tuân thủ nội quy trường học."],["規則を守らない人はだめです。","Người không tuân thủ nội quy là không được."],["会社の規則は厳しいです。","Nội quy công ty nghiêm ngặt."],["新しい規則ができました。","Nội quy mới đã được đặt ra."],["規則を読んでください。","Hãy đọc nội quy."]]},{"word":"使用禁止","reading":"しようきんし","meaning":"cấm sử dụng","hanViet":"SỬ DỤNG CẤM CHỈ","lesson":33,"ex":[["ここは使用禁止です。","Ở đây cấm sử dụng."],["このエレベーターは使用禁止ですから、階段を使います。","Thang máy này cấm sử dụng nên tôi dùng cầu thang."],["「使用禁止」と書いてありますから、入りません。","Có viết \"Cấm sử dụng\" nên tôi không vào."],["壊れた洗濯機は使用禁止です。","Máy giặt hỏng thì cấm sử dụng."],["プールはきょう、使用禁止です。","Hôm nay hồ bơi cấm sử dụng."]]},{"word":"立入禁止","reading":"たちいりきんし","meaning":"Cấm vào, khu vực cấm","hanViet":"LẬP NHẬP CẤM CHỈ","lesson":33,"ex":[["ここは立入禁止です。","Ở đây cấm vào."],["「立入禁止」と書いてあります。","Có viết \"Cấm vào\"."],["工場の中は立入禁止です。","Bên trong nhà máy cấm vào."],["立入禁止ですから、入りません。","Vì cấm vào nên tôi không vào."],["この部屋は立入禁止です。","Phòng này cấm vào."]]},{"word":"入口","reading":"いりぐち","meaning":"Lối vào","hanViet":"NHẬP KHẨU","lesson":33,"ex":[["入口はあそこです。","Lối vào ở đằng kia."],["入口で靴を脱ぎます。","Tôi cởi giày ở lối vào."],["入口の前に人がたくさんいます。","Trước lối vào có nhiều người."],["デパートの入口は1階です。","Lối vào cửa hàng bách hóa ở tầng 1."],["入口がわかりません。","Tôi không biết lối vào ở đâu."]]},{"word":"出口","reading":"でぐち","meaning":"Lối ra","hanViet":"XUẤT KHẨU","lesson":33,"ex":[["出口はあそこです。","Lối ra ở đằng kia."],["駅の出口で友達に会いました。","Tôi đã gặp bạn ở lối ra của ga."],["出口の前に車が止まっています。","Trước lối ra có xe đang đỗ."],["デパートの出口は1階です。","Lối ra của cửa hàng bách hóa ở tầng 1."],["出口がわかりません。","Tôi không biết lối ra ở đâu."]]},{"word":"非常口","reading":"ひじょうぐち","meaning":"cửa thoát hiểm","hanViet":"PHI THƯỜNG KHẨU","lesson":33,"ex":[["非常口はあそこです。","Cửa thoát hiểm ở đằng kia."],["火事のとき、非常口から逃げます。","Khi hỏa hoạn, tôi thoát ra bằng cửa thoát hiểm."],["非常口の前に荷物を置かないでください。","Đừng để hành lý trước cửa thoát hiểm."],["非常口は2階にあります。","Cửa thoát hiểm ở tầng 2."],["非常口の場所を確かめました。","Tôi đã xác nhận vị trí cửa thoát hiểm."]]},{"word":"本日休業","reading":"ほんじつきゅうぎょう","meaning":"hôm nay đóng cửa, hôm nay nghỉ","hanViet":"BẢN NHẬT HƯU NGHIỆP","lesson":33,"ex":[["「本日休業」と書いてあります。","Có viết \"Hôm nay đóng cửa\"."],["店は本日休業です。","Cửa hàng hôm nay đóng cửa."],["本日休業ですから、あした来ます。","Vì hôm nay đóng cửa nên ngày mai tôi đến."],["レストランは本日休業です。","Nhà hàng hôm nay đóng cửa."],["銀行は本日休業です。","Ngân hàng hôm nay đóng cửa."]]},{"word":"営業中","reading":"えいぎょうちゅう","meaning":"đang mở cửa","hanViet":"DOANH NGHIỆP TRUNG","lesson":33,"ex":[["店は営業中です。","Cửa hàng đang mở cửa."],["レストランは営業中ですから、入ります。","Nhà hàng đang mở cửa nên tôi vào."],["「営業中」と書いてあります。","Có viết \"Đang mở cửa\"."],["銀行は営業中ですか。","Ngân hàng có đang mở cửa không?"],["営業中の店でパンを買いました。","Tôi đã mua bánh mì ở cửa hàng đang mở cửa."]]},{"word":"使用中","reading":"しようちゅう","meaning":"đang sử dụng","hanViet":"SỬ DỤNG TRUNG","lesson":33,"ex":[["トイレは使用中です。","Nhà vệ sinh đang có người sử dụng."],["電話は使用中です。","Điện thoại đang được sử dụng."],["この部屋は使用中です。","Phòng này đang được sử dụng."],["「使用中」と書いてあります。","Có viết \"Đang sử dụng\"."],["シャワーは使用中ですから、待ってください。","Vòi sen đang được sử dụng nên hãy đợi."]]},{"word":"～中","reading":"～ちゅう","meaning":"đang ~","hanViet":"TRUNG","lesson":33,"ex":[["会議中です。","Đang họp."],["授業中です。","Đang trong giờ học."],["勉強中ですから、静かにしてください。","Tôi đang học nên hãy giữ yên lặng."],["仕事中です。","Đang làm việc."],["旅行中です。","Đang đi du lịch."]]},{"word":"どういう～","reading":"どういう～","meaning":"~ gì, ~ thế nào","hanViet":"","lesson":33,"ex":[["どういう本が好きですか。","Bạn thích sách gì?"],["どういう意味ですか。","Nghĩa là gì?"],["どういう人が好きですか。","Bạn thích người như thế nào?"],["どういう仕事をしていますか。","Bạn đang làm công việc gì?"],["どういう映画を見ましたか。","Bạn đã xem phim gì?"]]},{"word":"駐車違反","reading":"ちゅうしゃいはん","meaning":"đỗ xe trái phép","hanViet":"TRÚ XA VI PHẢN","lesson":33,"ex":[["駐車違反をしました。","Tôi đã đỗ xe trái phép."],["駐車違反で警察に注意されました。","Tôi đã bị cảnh sát nhắc nhở vì đỗ xe trái phép."],["ここに車を止めると、駐車違反です。","Đỗ xe ở đây là đỗ xe trái phép."],["駐車違反の車が多いです。","Nhiều xe đỗ trái phép."],["駐車違反をしないでください。","Đừng đỗ xe trái phép."]]},{"word":"そりゃあ","reading":"そりゃあ","meaning":"thế thì ,ồ","hanViet":"","lesson":33,"ex":[["「そりゃあ、よかったですね。」","Thế thì tốt quá nhỉ."],["そりゃあ、すごいですね。","Ồ, tuyệt vời nhỉ."],["そりゃあ、大変ですね。","Ồ, vất vả nhỉ."],["「あしたは雨です。」「そりゃあ、傘を持っていきます。」","Ngày mai trời mưa. Thế thì tôi sẽ mang ô theo."],["そりゃあ、うれしいですね。","Ồ, vui quá nhỉ."]]},{"word":"～以内","reading":"～いない","meaning":"trong khoảng ~, trong vòng ~","hanViet":"DĨ NỘI","lesson":33,"ex":[["3日以内に返事をください。","Hãy trả lời trong vòng 3 ngày."],["10分以内に来ます。","Tôi sẽ đến trong vòng 10 phút."],["1時間以内に終わります。","Tôi sẽ xong trong vòng 1 giờ."],["5分以内に駅へ行きます。","Tôi sẽ đến ga trong vòng 5 phút."],["1か月以内に宿題を出します。","Tôi sẽ nộp bài tập trong vòng 1 tháng."]]},{"word":"警察","reading":"けいさつ","meaning":"Cảnh sát","hanViet":"CẢNH SÁT","lesson":33,"ex":[["警察を呼びました。","Tôi đã gọi cảnh sát."],["警察に電話しました。","Tôi đã gọi điện cho cảnh sát."],["警察が来ました。","Cảnh sát đã đến."],["泥棒を警察に連絡しました。","Tôi đã báo cảnh sát về tên trộm."],["警察の車が通ります。","Xe cảnh sát đi qua."]]},{"word":"罰金","reading":"ばっきん","meaning":"tiền phạt","hanViet":"PHẠT KIM","lesson":33,"ex":[["罰金を払いました。","Tôi đã nộp tiền phạt."],["罰金は1万円です。","Tiền phạt là 10.000 yên."],["罰金が高いです。","Tiền phạt cao."],["罰金を払わないと、だめです。","Không nộp tiền phạt thì không được."],["罰金の紙をもらいました。","Tôi đã nhận giấy phạt."]]},{"word":"電報","reading":"でんぽう","meaning":"điện báo","hanViet":"ĐIỆN BÁO","lesson":33,"ex":[["お祝いの電報を送りました。","Tôi đã gửi điện báo chúc mừng."],["電報でお祝いを伝えました。","Tôi đã gửi lời chúc mừng bằng điện báo."],["祖父に電報を送りました。","Tôi đã gửi điện báo cho ông."],["電報は速いです。","Điện báo nhanh."],["電報が届きました。","Điện báo đã đến."]]},{"word":"人々","reading":"ひとびと","meaning":"nhiều người","hanViet":"NHÂN","lesson":33,"ex":[["人々が公園に集まります。","Nhiều người tụ tập ở công viên."],["人々は電車に乗ります。","Nhiều người đi tàu điện."],["町の人々は親切です。","Người dân trong thị trấn thân thiện."],["人々が駅で待っています。","Nhiều người đang đợi ở ga."],["お正月に人々は神社へ行きます。","Vào dịp năm mới nhiều người đi đền."]]},{"word":"急用","reading":"きゅうよう","meaning":"việc gấp","hanViet":"CẤP DỤNG","lesson":33,"ex":[["急用があります。","Tôi có việc gấp."],["急用で会社を休みました。","Tôi đã nghỉ làm vì việc gấp."],["急用ができました。","Tôi có việc gấp phát sinh."],["急用ですから、早く帰ります。","Vì có việc gấp nên tôi về sớm."],["急用で電話をしました。","Tôi đã gọi điện vì việc gấp."]]},{"word":"打ちます","reading":"うちます","meaning":"Đánh, đập, gõ","hanViet":"ĐẢ","lesson":33,"ex":[["ボールを打ちました。","Tôi đã đánh quả bóng."],["電報を打ちました。","Tôi đã gửi điện báo."],["パソコンで字を打ちます。","Tôi gõ chữ trên máy tính."],["テニスでボールを打ちます。","Tôi đánh bóng trong tennis."],["電報を打つのは初めてです。","Gửi điện báo là lần đầu tiên."]]},{"word":"電報代","reading":"でんぽうだい","meaning":"phí điện báo","hanViet":"ĐIỆN BÁO ĐẠI","lesson":33,"ex":[["電報代はいくらですか。","Phí điện báo là bao nhiêu?"],["電報代を払いました。","Tôi đã trả phí điện báo."],["電報代は高いです。","Phí điện báo cao."],["電報代は1万円です。","Phí điện báo là 10.000 yên."],["電報代を調べました。","Tôi đã kiểm tra phí điện báo."]]},{"word":"できるだけ","reading":"できるだけ","meaning":"hết sức có thể","hanViet":"","lesson":33,"ex":[["できるだけ早く来てください。","Hãy đến sớm hết sức có thể."],["できるだけ安い本を買います。","Tôi mua sách rẻ hết sức có thể."],["できるだけ日本語で話します。","Tôi nói tiếng Nhật hết sức có thể."],["できるだけ早く返事をください。","Hãy trả lời sớm hết sức có thể."],["できるだけたくさん勉強します。","Tôi học nhiều hết sức có thể."]]},{"word":"短く","reading":"みじかく","meaning":"ngắn gọn","hanViet":"ĐOẢN","lesson":33,"ex":[["短く話してください。","Hãy nói ngắn gọn."],["電報は短く打ちます。","Tôi gửi điện báo ngắn gọn."],["手紙を短く書きました。","Tôi đã viết thư ngắn gọn."],["名前を短く書きました。","Tôi đã viết tên ngắn gọn."],["短く書いてください。","Hãy viết ngắn gọn."]]},{"word":"重い病気","reading":"おもいびょうき","meaning":"bệnh nặng","hanViet":"TRỌNG BỆNH KHÍ","lesson":33,"ex":[["祖父は重い病気です。","Ông tôi bị bệnh nặng."],["重い病気で病院に入りました。","Tôi đã nhập viện vì bệnh nặng."],["重い病気になりました。","Tôi đã bị bệnh nặng."],["重い病気の人を助けます。","Tôi giúp người bị bệnh nặng."],["重い病気ですが、元気です。","Bị bệnh nặng nhưng vẫn khỏe mạnh."]]},{"word":"明日","reading":"あす","meaning":"ngày mai","hanViet":"MINH NHẬT","lesson":33,"ex":[["明日は雨です。","Ngày mai trời mưa."],["明日、友達に会います。","Ngày mai tôi gặp bạn."],["明日は学校へ行きます。","Ngày mai tôi đi học."],["明日、試験があります。","Ngày mai có kỳ thi."],["明日は休みです。","Ngày mai được nghỉ."]]},{"word":"留守","reading":"るす","meaning":"Vắng nhà","hanViet":"LƯU THỦ","lesson":33,"ex":[["母は留守です。","Mẹ vắng nhà."],["留守のとき、電話がありました。","Khi vắng nhà, đã có điện thoại gọi đến."],["田中さんは留守です。","Anh Tanaka vắng nhà."],["留守ですから、あとで来てください。","Vì vắng nhà nên hãy đến sau."],["家族はみんな留守です。","Cả gia đình đều vắng nhà."]]},{"word":"留守番","reading":"るすばん","meaning":"Trông nhà, giữ nhà","hanViet":"LƯU THỦ PHIÊN","lesson":33,"ex":[["留守番をします。","Tôi trông nhà."],["弟は留守番です。","Em trai tôi trông nhà."],["留守番のとき、本を読みます。","Khi trông nhà, tôi đọc sách."],["母が留守番を頼みました。","Mẹ đã nhờ tôi trông nhà."],["留守番をしていますから、出かけられません。","Vì đang trông nhà nên tôi không ra ngoài được."]]},{"word":"祝い","reading":"いわい","meaning":"việc mừng, vật mừng","hanViet":"CHÚC","lesson":33,"ex":[["祝いの電報を送りました。","Tôi đã gửi điện báo chúc mừng."],["結婚式の祝いを送りました。","Tôi đã gửi quà mừng đám cưới."],["祝いのパーティーがあります。","Có bữa tiệc mừng."],["誕生日の祝いをしました。","Tôi đã tổ chức mừng sinh nhật."],["祝いの手紙を書きました。","Tôi đã viết thư chúc mừng."]]},{"word":"悲しみ","reading":"かなしみ","meaning":"Nỗi buồn","hanViet":"BI","lesson":33,"ex":[["悲しみがわかります。","Tôi hiểu nỗi buồn."],["悲しみで泣きました。","Tôi đã khóc vì nỗi buồn."],["悲しみを忘れません。","Tôi không quên nỗi buồn."],["悲しみが大きいです。","Nỗi buồn lớn."],["悲しみを友達に話しました。","Tôi đã kể nỗi buồn với bạn."]]},{"word":"準備中","reading":"じゅんびちゅう","meaning":"đang chuẩn bị","hanViet":"CHUẨN BỊ TRUNG","lesson":33,"ex":[["店は準備中です。","Cửa hàng đang chuẩn bị."],["レストランは準備中です。","Nhà hàng đang chuẩn bị."],["「準備中」と書いてあります。","Có viết \"Đang chuẩn bị\"."],["準備中ですから、待ってください。","Vì đang chuẩn bị nên hãy đợi."],["パーティーの準備中です。","Đang chuẩn bị cho bữa tiệc."]]},{"word":"化粧室","reading":"けしょうしつ","meaning":"phòng trang điểm, nhà vệ sinh","hanViet":"HÓA TRANG THẤT","lesson":33,"ex":[["化粧室はどこですか。","Phòng vệ sinh ở đâu?"],["化粧室へ行きます。","Tôi đi vệ sinh."],["化粧室は2階にあります。","Phòng vệ sinh ở tầng 2."],["デパートの化粧室はきれいです。","Phòng vệ sinh của cửa hàng bách hóa sạch đẹp."],["化粧室で手を洗います。","Tôi rửa tay ở phòng vệ sinh."]]},{"word":"禁煙席","reading":"きんえんせき","meaning":"ghế cấm hút thuốc","hanViet":"CẤM YÊN TỊCH","lesson":33,"ex":[["禁煙席に座ります。","Tôi ngồi ở ghế cấm hút thuốc."],["禁煙席はどこですか。","Ghế cấm hút thuốc ở đâu?"],["禁煙席を予約しました。","Tôi đã đặt ghế cấm hút thuốc."],["レストランに禁煙席があります。","Nhà hàng có ghế cấm hút thuốc."],["禁煙席でたばこを吸ってはいけません。","Không được hút thuốc ở ghế cấm hút thuốc."]]},{"word":"予約席","reading":"よやくせき","meaning":"ghế đặt","hanViet":"DỰ ƯỚC TỊCH","lesson":33,"ex":[["予約席に座ります。","Tôi ngồi ở ghế đặt."],["予約席はどこですか。","Ghế đặt ở đâu?"],["新幹線の予約席を予約しました。","Tôi đã đặt ghế đặt trên tàu Shinkansen."],["予約席ですから、座れません。","Vì là ghế đặt nên không ngồi được."],["予約席の番号は5番です。","Số ghế đặt là số 5."]]},{"word":"火気厳禁","reading":"かきげんきん","meaning":"cấm lửa","hanViet":"HỎA KHÍ NGHIÊM CẤM","lesson":33,"ex":[["ここは火気厳禁です。","Ở đây cấm lửa."],["「火気厳禁」と書いてあります。","Có viết \"Cấm lửa\"."],["ガソリンのそばは火気厳禁です。","Gần xăng thì cấm lửa."],["火気厳禁ですから、たばこを吸ってはいけません。","Vì cấm lửa nên không được hút thuốc."],["工場は火気厳禁です。","Nhà máy cấm lửa."]]},{"word":"割れ物注意","reading":"われものちゅうい","meaning":"chú ý đồ dễ vỡ","hanViet":"CÁT VẬT CHÚ Ý","lesson":33,"ex":[["「割れ物注意」と書いてあります。","Có viết \"Chú ý đồ dễ vỡ\"."],["箱に割れ物注意と書いてあります。","Trên hộp có viết \"Chú ý đồ dễ vỡ\"."],["割れ物注意の荷物です。","Đây là hành lý chú ý đồ dễ vỡ."],["割れ物注意ですから、気をつけて運びます。","Vì chú ý đồ dễ vỡ nên tôi vận chuyển cẩn thận."],["割れ物注意の箱を送りました。","Tôi đã gửi hộp chú ý đồ dễ vỡ."]]},{"word":"運転初心者注意","reading":"うんてんしょしんしゃちゅうい","meaning":"chú ý người mới lái xe","hanViet":"VẬN CHUYỂN SƠ TÂM GIẢ CHÚ Ý","lesson":33,"ex":[["車のうしろに「運転初心者注意」と書いてあります。","Phía sau xe có ghi \"Chú ý người mới lái xe\"."],["運転初心者注意の車のうしろでは、ゆっくり運転します。","Khi ở sau xe có biển \"Chú ý người mới lái xe\", tôi lái xe chậm rãi."],["弟は運転初心者注意のマークを車につけました。","Em trai tôi đã dán biển \"Chú ý người mới lái xe\" lên xe."],["「運転初心者注意」は、運転がまだ上手じゃない人のマークです。","\"Chú ý người mới lái xe\" là biển của người lái xe vẫn chưa giỏi."],["運転初心者注意の車を見たら、気をつけて運転してください。","Nếu thấy xe có biển \"Chú ý người mới lái xe\", hãy lái xe cẩn thận."]]},{"word":"工事中","reading":"こうじちゅう","meaning":"đang thi công","hanViet":"CÔNG SỰ TRUNG","lesson":33,"ex":[["ここは工事中ですから、入ってはいけません。","Chỗ này đang thi công nên không được vào."],["駅の前は工事中で、歩道が狭いです。","Trước ga đang thi công nên vỉa hè hẹp."],["工事中の建物の前に、車がたくさん止まっています。","Trước tòa nhà đang thi công có nhiều xe đang đỗ."],["この橋は工事中ですから、来月まで使えません。","Cây cầu này đang thi công nên đến tháng sau không dùng được."],["工事中と書いてある道で、ゆっくり歩きます。","Tôi đi bộ chậm rãi trên con đường có ghi \"Đang thi công\"."]]},{"word":"塩素系漂白剤不可","reading":"えんそけいひょうはくざいふか","meaning":"không được dùng thuốc tẩy có chất clo","hanViet":"DIÊM TỐ HỆ PHIÊU BẠCH TỄ BẤT KHẢ","lesson":33,"ex":[["このシャツに「塩素系漂白剤不可」と書いてあります。","Trên áo sơ mi này có ghi \"Không được dùng thuốc tẩy có chất clo\"."],["塩素系漂白剤不可の服を洗うときは、気をつけてください。","Khi giặt quần áo có ghi \"Không được dùng thuốc tẩy có chất clo\", hãy cẩn thận."],["母は塩素系漂白剤不可のシャツを手洗いします。","Mẹ tôi giặt tay áo sơ mi có ghi \"Không được dùng thuốc tẩy có chất clo\"."],["このセーターは塩素系漂白剤不可ですから、水で洗います。","Vì chiếc áo len này ghi \"Không được dùng thuốc tẩy có chất clo\" nên tôi giặt bằng nước."],["塩素系漂白剤不可のマークの意味がわかりませんでした。","Tôi đã không hiểu ý nghĩa của ký hiệu \"Không được dùng thuốc tẩy có chất clo\"."]]},{"word":"手洗い","reading":"てあらい","meaning":"giặt tay","hanViet":"THỦ TẨY","lesson":33,"ex":[["このセーターは手洗いしてください。","Hãy giặt tay chiếc áo len này."],["母はシャツを手洗いします。","Mẹ tôi giặt tay áo sơ mi."],["手洗いの服は、洗濯機で洗いません。","Quần áo giặt tay thì không giặt bằng máy giặt."],["着物は手洗いがいいです。","Kimono thì nên giặt tay."],["手洗いは時間がかかりますから、週末にします。","Vì giặt tay tốn thời gian nên tôi làm vào cuối tuần."]]},{"word":"標識","reading":"ひょうしき","meaning":"biển báo, dấu hiệu","hanViet":"TIÊU THỨC","lesson":33,"ex":[["道に新しい標識ができました。","Trên đường có biển báo mới."],["この標識は「止まれ」という意味です。","Biển báo này có nghĩa là \"Dừng lại\"."],["標識を見て、右へ曲がりました。","Nhìn biển báo, tôi đã rẽ phải."],["駅の前に大きい標識があります。","Trước ga có biển báo lớn."],["標識の意味がわからないときは、先生に聞きます。","Khi không hiểu ý nghĩa biển báo, tôi hỏi thầy giáo."]]},{"word":"マーク","reading":"マーク","meaning":"kí hiệu","hanViet":"","lesson":33,"ex":[["このマークはトイレのマークです。","Ký hiệu này là ký hiệu nhà vệ sinh."],["会社のマークは赤い色です。","Ký hiệu của công ty màu đỏ."],["マークを見て、この店がわかりました。","Nhìn ký hiệu, tôi đã nhận ra cửa hàng này."],["子どもは星のマークが好きです。","Trẻ con thích ký hiệu hình ngôi sao."],["このマークの意味を教えてください。","Hãy cho tôi biết ý nghĩa của ký hiệu này."]]},{"word":"ボール","reading":"ボール","meaning":"quả bóng","hanViet":"","lesson":33,"ex":[["子どもは公園でボールを投げます。","Trẻ con ném bóng ở công viên."],["このボールはサッカーのボールです。","Quả bóng này là bóng đá."],["ボールが道へ出ました。","Quả bóng đã lăn ra đường."],["弟に新しいボールを買いました。","Tôi đã mua bóng mới cho em trai."],["ボールをなくしましたから、もう一つ買います。","Vì làm mất bóng nên tôi mua thêm một quả nữa."]]},{"word":"ファイト","reading":"ファイト","meaning":"cố lên, quyết chiến","hanViet":"","lesson":33,"ex":[["「ファイト！」と言って、友達を応援します。","Tôi nói \"Cố lên!\" để cổ vũ bạn."],["試合の前に、みんなで「ファイト！」と言いました。","Trước trận đấu, mọi người cùng nói \"Cố lên!\"."],["先生は「ファイト！」と言って、学生を応援しました。","Thầy giáo nói \"Cố lên!\" để cổ vũ học sinh."],["「ファイト！」と聞いて、元気になりました。","Nghe \"Cố lên!\", tôi đã khỏe khoắn trở lại."],["弟の試合で「ファイト！」と大きい声で言いました。","Trong trận đấu của em trai, tôi đã nói \"Cố lên!\" bằng giọng lớn."]]},{"word":"もう","reading":"もう","meaning":"không—nữa","hanViet":"","lesson":33,"ex":[["もう甘いケーキを食べません。","Tôi không ăn bánh ngọt nữa."],["もう遅くまでテレビを見ません。","Tôi không xem ti vi đến khuya nữa."],["母はもうこの店へ行きません。","Mẹ tôi không đến cửa hàng này nữa."],["もうこの本を読みません。","Tôi không đọc cuốn sách này nữa."],["兄はもう車を運転しません。","Anh trai tôi không lái xe nữa."]]},{"word":"あと","reading":"あと","meaning":"còn~","hanViet":"","lesson":33,"ex":[["あと少しで学校に着きます。","Còn một chút nữa là đến trường."],["あと三つりんごがあります。","Còn ba quả táo."],["あと一人、友達が来ます。","Còn một người bạn nữa sẽ đến."],["あと少し待ってください。","Hãy đợi thêm một chút nữa."],["あと二つください。","Cho tôi thêm hai cái nữa."]]},{"word":"また","reading":"また","meaning":"thêm nữa","hanViet":"","lesson":33,"ex":[["また一つください。","Cho tôi thêm một cái nữa."],["また明日、学校へ来ます。","Ngày mai tôi lại đến trường."],["また来週、友達に会います。","Tuần sau tôi lại gặp bạn."],["また電話します。","Tôi sẽ gọi điện lại."],["また今度、いっしょに映画を見ましょう。","Lần sau chúng ta cùng xem phim nhé."]]},{"word":"危篤","reading":"きとく","meaning":"tình trạng hiểm nghèo","hanViet":"NGUY ĐỐC","lesson":33,"ex":[["おじいさんは危篤です。","Ông nội đang trong tình trạng hiểm nghèo."],["祖父が危篤で、母は病院へ行きました。","Ông nội nguy kịch nên mẹ tôi đã đến bệnh viện."],["危篤の祖父のお見舞いに、病院へ行きました。","Tôi đã đến bệnh viện thăm ông nội đang nguy kịch."],["祖父は危篤ですが、きのう少しよくなりました。","Ông nội đang nguy kịch nhưng hôm qua đã khá hơn một chút."],["祖父が危篤だと聞いて、とても心配しました。","Nghe tin ông nội nguy kịch, tôi đã rất lo lắng."]]},{"word":"悲しい","reading":"かなしい","meaning":"buồn","hanViet":"BI","lesson":33,"ex":[["悲しい映画を見て、泣きました。","Xem phim buồn, tôi đã khóc."],["友達と別れますから、悲しいです。","Vì phải chia tay bạn nên tôi buồn."],["悲しいニュースを聞きました。","Tôi đã nghe tin buồn."],["犬が死にましたから、悲しいです。","Vì con chó đã chết nên tôi buồn."],["悲しい歌を聞いて、涙が出ました。","Nghe bài hát buồn, tôi đã rơi nước mắt."]]},{"word":"利用します","reading":"りようします","meaning":"sử dụng","hanViet":"LỢI DỤNG","lesson":33,"ex":[["図書館をよく利用します。","Tôi thường sử dụng thư viện."],["インターネットを利用して、日本語を勉強します。","Tôi dùng internet để học tiếng Nhật."],["このカードを利用すれば、安く買えます。","Nếu dùng thẻ này thì mua được rẻ."],["電車を利用して、会社へ行きます。","Tôi dùng tàu điện để đi làm."],["バスを利用する人が多いです。","Có nhiều người sử dụng xe buýt."]]},{"word":"磨きます","reading":"みがきます","meaning":"Đánh bóng, mài, chải","hanViet":"MA","lesson":34,"ex":[["毎朝、歯を磨きます。","Mỗi sáng tôi đánh răng."],["父は車を磨くのが好きです。","Bố tôi thích đánh bóng xe."],["鏡を磨きましたから、きれいになりました。","Vì đã lau gương nên gương đã sạch bóng."],["靴を磨いてから、学校へ行きます。","Sau khi đánh giày, tôi đi học."],["弟は歯を磨きません。","Em trai tôi không đánh răng."]]},{"word":"組み立てます","reading":"くみたてます","meaning":"lắp ráp, lắp đặt","hanViet":"TỔ LẬP","lesson":34,"ex":[["説明書を読んで、机を組み立てます。","Đọc hướng dẫn, tôi lắp ráp bàn."],["父と本棚を組み立てました。","Tôi đã cùng bố lắp ráp giá sách."],["このベッドを組み立てるのは難しいです。","Việc lắp ráp chiếc giường này thì khó."],["新しいいすを組み立てて、部屋に置きます。","Tôi lắp ráp ghế mới rồi đặt vào phòng."],["説明書を見ながら、家具を組み立てます。","Vừa xem hướng dẫn, tôi vừa lắp ráp đồ nội thất."]]},{"word":"折ります","reading":"おります","meaning":"Bẻ, gấp","hanViet":"TRIẾT","lesson":34,"ex":[["紙を半分に折ります。","Tôi gấp đôi tờ giấy."],["紙を折って、船を作ります。","Tôi gấp giấy làm thuyền."],["母は手紙を小さく折りました。","Mẹ tôi đã gấp nhỏ bức thư."],["鉛筆を折りました。","Tôi đã bẻ gãy cây bút chì."],["紙を四つに折ってください。","Hãy gấp tờ giấy làm tư."]]},{"word":"つけます","reading":"つけます","meaning":"chấm [xì-dầu]","hanViet":"","lesson":34,"ex":[["寿司をしょうゆにつけます。","Tôi chấm sushi vào xì dầu."],["刺身をしょうゆにつけて、食べます。","Tôi chấm sashimi vào xì dầu rồi ăn."],["天ぷらをしょうゆにつけますか。","Bạn có chấm tempura vào xì dầu không?"],["母は魚をしょうゆにつけて、焼きます。","Mẹ tôi chấm cá vào xì dầu rồi nướng."],["しょうゆをつけすぎると、辛くなります。","Nếu chấm quá nhiều xì dầu sẽ bị mặn."]]},{"word":"見つかります","reading":"みつかります","meaning":"được tìm thấy","hanViet":"KIẾN","lesson":34,"ex":[["なくした財布が見つかりました。","Chiếc ví đã mất đã được tìm thấy."],["鍵が机の上に見つかりました。","Chìa khóa đã được tìm thấy trên bàn."],["図書館で本が見つかりました。","Cuốn sách đã được tìm thấy ở thư viện."],["眼鏡が見つからなくて、こまりました。","Không tìm thấy kính nên tôi đã gặp rắc rối."],["かばんが見つかって、安心しました。","Tìm thấy túi xách, tôi đã yên tâm."]]},{"word":"します","reading":"します","meaning":"đeo , thắt","hanViet":"","lesson":34,"ex":[["父は毎日ネクタイをします。","Bố tôi thắt cà vạt mỗi ngày."],["母は指輪をしています。","Mẹ tôi đang đeo nhẫn."],["眼鏡をしないと、字が見えません。","Nếu không đeo kính thì không nhìn thấy chữ."],["姉は新しい時計をしました。","Chị tôi đã đeo đồng hồ mới."],["冬は手袋をしますが、夏はしません。","Mùa đông tôi đeo găng tay nhưng mùa hè thì không."]]},{"word":"細い","reading":"ほそい","meaning":"Mảnh, thon, gầy","hanViet":"TẾ","lesson":34,"ex":[["この道は細いです。","Con đường này hẹp."],["細い線を引きます。","Tôi kẻ một đường thẳng mảnh."],["弟は細いです。","Em trai tôi gầy."],["細い鉛筆で字を書きます。","Tôi viết chữ bằng bút chì mảnh."],["母は細い字を書きます。","Mẹ tôi viết chữ nhỏ."]]},{"word":"太い","reading":"ふとい","meaning":"To, béo, dày","hanViet":"THÁI","lesson":34,"ex":[["この木は太いです。","Cây này to."],["太い線を引きました。","Tôi đã kẻ một đường thẳng đậm."],["父は太い声で話します。","Bố tôi nói bằng giọng trầm."],["太いボールペンで字を書きます。","Tôi viết chữ bằng bút bi nét đậm."],["この木は太いですから、一人で切れません。","Cây này to nên một mình tôi không chặt được."]]},{"word":"盆踊り","reading":"ぼんおどり","meaning":"Điệu múa Bon Odori (lễ Obon)","hanViet":"BỒN DŨNG","lesson":34,"ex":[["夏の祭りで盆踊りを踊ります。","Tôi nhảy múa Bon Odori ở lễ hội mùa hè."],["母は盆踊りが上手です。","Mẹ tôi nhảy Bon Odori giỏi."],["盆踊りの音楽を聞きました。","Tôi đã nghe nhạc múa Bon Odori."],["祖母は盆踊りを踊るのが好きです。","Bà tôi thích nhảy múa Bon Odori."],["盆踊りの日は、町に人が多いです。","Vào ngày múa Bon Odori, trong thị trấn có nhiều người."]]},{"word":"家具","reading":"かぐ","meaning":"Đồ nội thất","hanViet":"GIA CỤ","lesson":34,"ex":[["新しい家具を買いました。","Tôi đã mua đồ nội thất mới."],["この店は家具が安いです。","Cửa hàng này bán đồ nội thất rẻ."],["家具を部屋に置きます。","Tôi đặt đồ nội thất vào phòng."],["机やいすは家具です。","Bàn và ghế là đồ nội thất."],["家具を組み立てるのが好きです。","Tôi thích lắp ráp đồ nội thất."]]},{"word":"説明書","reading":"せつめいしょ","meaning":"quyển hướng dẫn","hanViet":"THUYẾT MINH THƯ","lesson":34,"ex":[["説明書を読んでから、使ってください。","Hãy đọc hướng dẫn rồi mới dùng."],["説明書がわかりませんから、店員に聞きます。","Vì không hiểu hướng dẫn nên tôi hỏi nhân viên cửa hàng."],["新しい炊飯器の説明書を読みました。","Tôi đã đọc hướng dẫn của nồi cơm điện mới."],["説明書をなくしましたから、組み立てられません。","Vì làm mất hướng dẫn nên tôi không lắp ráp được."],["この説明書は日本語と英語で書いてあります。","Hướng dẫn này được viết bằng tiếng Nhật và tiếng Anh."]]},{"word":"線","reading":"せん","meaning":"Đường, tuyến, đường kẻ","hanViet":"TUYẾN","lesson":34,"ex":[["紙に赤い線を引きます。","Tôi kẻ đường thẳng màu đỏ trên giấy."],["太い線と細い線を引いてください。","Hãy kẻ đường đậm và đường mảnh."],["地下鉄の線がわかりません。","Tôi không biết tuyến tàu điện ngầm."],["電車の線で、事故がありました。","Trên tuyến tàu điện đã xảy ra tai nạn."],["線の右に名前を書きます。","Tôi viết tên ở phía bên phải đường kẻ."]]},{"word":"矢印","reading":"やじるし","meaning":"dấu mũi tên, ký hiệu mũi tên","hanViet":"THỈ ẤN","lesson":34,"ex":[["矢印を見て、右へ曲がりました。","Nhìn mũi tên, tôi đã rẽ phải."],["駅の矢印を見て、電車に乗りました。","Nhìn mũi tên ở ga, tôi đã lên tàu điện."],["この矢印は左です。","Mũi tên này chỉ sang trái."],["標識の矢印がわかりません。","Tôi không hiểu mũi tên trên biển báo."],["矢印が赤いですから、気をつけてください。","Vì mũi tên màu đỏ nên hãy cẩn thận."]]},{"word":"黒","reading":"くろ","meaning":"Màu đen","hanViet":"HẮC","lesson":34,"ex":[["私の車は黒です。","Xe của tôi màu đen."],["黒のシャツを買いました。","Tôi đã mua áo sơ mi màu đen."],["黒い靴が好きです。","Tôi thích giày đen."],["空が黒くなりました。","Bầu trời đã trở nên đen."],["黒と白のボールペンがあります。","Có bút bi màu đen và màu trắng."]]},{"word":"白","reading":"しろ","meaning":"Màu trắng","hanViet":"BẠCH","lesson":34,"ex":[["私のシャツは白です。","Áo sơ mi của tôi màu trắng."],["白い雪が降っています。","Tuyết trắng đang rơi."],["白の車が好きです。","Tôi thích xe màu trắng."],["白い紙に字を書きます。","Tôi viết chữ trên giấy trắng."],["母の髪は白くなりました。","Tóc mẹ tôi đã bạc."]]},{"word":"赤","reading":"あか","meaning":"Màu đỏ","hanViet":"XÍCH","lesson":34,"ex":[["信号が赤ですから、止まります。","Vì đèn tín hiệu màu đỏ nên tôi dừng lại."],["赤いりんごを食べました。","Tôi đã ăn táo đỏ."],["赤のセーターを買いました。","Tôi đã mua áo len màu đỏ."],["弟の顔が赤くなりました。","Mặt em trai tôi đã đỏ lên."],["赤い花が好きです。","Tôi thích hoa đỏ."]]},{"word":"青","reading":"あお","meaning":"màu xanh da trời","hanViet":"THANH","lesson":34,"ex":[["空は青です。","Bầu trời màu xanh."],["青い海を見ました。","Tôi đã nhìn thấy biển xanh."],["青のシャツを着ます。","Tôi mặc áo sơ mi màu xanh."],["青いボールを買いました。","Tôi đã mua quả bóng màu xanh."],["信号が青になりました。","Đèn tín hiệu đã chuyển sang màu xanh."]]},{"word":"紺","reading":"こん","meaning":"màu xanh navy đậm","hanViet":"CÁM","lesson":34,"ex":[["私のズボンは紺です。","Quần của tôi màu xanh navy."],["紺のセーターを買いました。","Tôi đã mua áo len màu xanh navy."],["紺のスカートが好きです。","Tôi thích váy màu xanh navy."],["紺のネクタイをしました。","Tôi đã thắt cà vạt màu xanh navy."],["紺と白のシャツがあります。","Có áo sơ mi màu xanh navy và trắng."]]},{"word":"黄色","reading":"きいろ","meaning":"Màu vàng","hanViet":"HOÀNG SẮC","lesson":34,"ex":[["黄色い花が好きです。","Tôi thích hoa vàng."],["黄色のりんごを食べました。","Tôi đã ăn táo vàng."],["信号が黄色ですから、気をつけてください。","Vì đèn tín hiệu màu vàng nên hãy cẩn thận."],["黄色いボールを買いました。","Tôi đã mua quả bóng màu vàng."],["私のかばんは黄色です。","Túi xách của tôi màu vàng."]]},{"word":"茶色","reading":"ちゃいろ","meaning":"màu nâu","hanViet":"TRÀ SẮC","lesson":34,"ex":[["茶色の靴を買いました。","Tôi đã mua giày màu nâu."],["茶色い机があります。","Có bàn màu nâu."],["私のコートは茶色です。","Áo khoác của tôi màu nâu."],["茶色の犬がいます。","Có con chó màu nâu."],["茶色いかばんが好きです。","Tôi thích túi xách màu nâu."]]},{"word":"しょうゆ","reading":"しょうゆ","meaning":"xì- dầu","hanViet":"","lesson":34,"ex":[["しょうゆを少しください。","Cho tôi một ít xì dầu."],["魚にしょうゆをかけます。","Tôi rưới xì dầu lên cá."],["しょうゆがもうありませんから、買います。","Vì đã hết xì dầu nên tôi mua."],["この料理はしょうゆの味がします。","Món ăn này có vị xì dầu."],["しょうゆと砂糖で味をつけます。","Tôi nêm bằng xì dầu và đường."]]},{"word":"～か～","reading":"～か～","meaning":"~hay ~","hanViet":"","lesson":34,"ex":[["コーヒーか紅茶か、どちらが好きですか。","Cà phê hay trà, bạn thích cái nào?"],["電車かバスか、どちらで行きますか。","Bạn đi bằng tàu điện hay xe buýt?"],["土曜日か日曜日か、映画を見に行きます。","Tôi đi xem phim vào thứ Bảy hay Chủ nhật."],["肉か魚か、どちらを食べますか。","Bạn ăn thịt hay cá?"],["学校か会社か、どちらへ行きますか。","Bạn đến trường hay đến công ty?"]]},{"word":"ゆうべ","reading":"ゆうべ","meaning":"tối qua, đêm qua","hanViet":"","lesson":34,"ex":[["ゆうべ、友達と電話で話しました。","Tối qua tôi đã nói chuyện điện thoại với bạn."],["ゆうべ、テレビで映画を見ました。","Tối qua tôi đã xem phim trên ti vi."],["ゆうべは雨でした。","Tối qua trời đã mưa."],["ゆうべ、母と料理を作りました。","Tối qua tôi đã cùng mẹ nấu ăn."],["ゆうべは早く寝ました。","Tối qua tôi đã đi ngủ sớm."]]},{"word":"さっき","reading":"さっき","meaning":"vừa rồi, vừa lúc nãy","hanViet":"","lesson":34,"ex":[["さっき、友達が来ました。","Vừa rồi bạn tôi đã đến."],["さっき、母に電話しました。","Vừa rồi tôi đã gọi điện cho mẹ."],["さっき、学校から帰りました。","Vừa rồi tôi đã về từ trường."],["さっき食べたケーキはおいしかったです。","Chiếc bánh vừa ăn rất ngon."],["さっき、雨が降りました。","Vừa rồi trời đã mưa."]]},{"word":"茶道","reading":"さどう","meaning":"trà đạo","hanViet":"TRÀ ĐẠO","lesson":34,"ex":[["母は茶道を習います。","Mẹ tôi học trà đạo."],["茶道の先生は有名です。","Thầy dạy trà đạo nổi tiếng."],["茶道の教室でお茶を飲みました。","Tôi đã uống trà ở lớp học trà đạo."],["祖母は茶道が好きです。","Bà tôi thích trà đạo."],["茶道を習うのは難しいです。","Học trà đạo thì khó."]]},{"word":"お茶をたてます","reading":"おちゃをたてます","meaning":"pha trà","hanViet":"TRÀ","lesson":34,"ex":[["母はお茶をたてます。","Mẹ tôi pha trà."],["祖母はお茶をたてるのが上手です。","Bà tôi pha trà giỏi."],["お茶をたてて、友達に出します。","Tôi pha trà rồi mời bạn."],["茶道の教室でお茶をたてました。","Tôi đã pha trà ở lớp học trà đạo."],["お茶をたてるときは、湯を使います。","Khi pha trà, tôi dùng nước nóng."]]},{"word":"先に","reading":"さきに","meaning":"trước","hanViet":"TIÊN","lesson":34,"ex":[["先にごはんを食べます。","Tôi ăn cơm trước."],["先に学校へ行ってください。","Hãy đến trường trước."],["先に手を洗います。","Tôi rửa tay trước."],["先に宿題をします。","Tôi làm bài tập trước."],["友達は先に帰りました。","Bạn tôi đã về trước."]]},{"word":"載せます","reading":"のせます","meaning":"đặt lên","hanViet":"TẢI","lesson":34,"ex":[["皿に魚を載せます。","Tôi đặt cá lên đĩa."],["ごはんをどんぶりに載せます。","Tôi đặt cơm lên bát ô tô."],["テーブルの上に本を載せました。","Tôi đã đặt sách lên bàn."],["ケーキを皿に載せてください。","Hãy đặt bánh lên đĩa."],["車に荷物を載せます。","Tôi đặt hành lý lên xe."]]},{"word":"苦い","reading":"にがい","meaning":"Đắng","hanViet":"KHỔ","lesson":34,"ex":[["このコーヒーは苦いです。","Cà phê này đắng."],["薬は苦いです。","Thuốc đắng."],["苦いお茶を飲みました。","Tôi đã uống trà đắng."],["苦いコーヒーに砂糖を入れます。","Tôi cho đường vào cà phê đắng."],["弟は苦い顔をしました。","Em trai tôi đã nhăn mặt."]]},{"word":"親子どんぶり","reading":"おやこどんぶり","meaning":"món oyako-don","hanViet":"THÂN TỬ","lesson":34,"ex":[["母は親子どんぶりを作ります。","Mẹ tôi nấu món oyako-don."],["親子どんぶりが好きです。","Tôi thích món oyako-don."],["親子どんぶりの材料を買いました。","Tôi đã mua nguyên liệu cho món oyako-don."],["昼ごはんに親子どんぶりを食べました。","Tôi đã ăn oyako-don vào bữa trưa."],["親子どんぶりは日本の料理です。","Oyako-don là món ăn Nhật Bản."]]},{"word":"材料","reading":"ざいりょう","meaning":"Nguyên liệu","hanViet":"TÀI LIỆU","lesson":34,"ex":[["料理の材料を買います。","Tôi mua nguyên liệu nấu ăn."],["親子どんぶりの材料は鳥肉と卵です。","Nguyên liệu của oyako-don là thịt gà và trứng."],["材料をスーパーで買いました。","Tôi đã mua nguyên liệu ở siêu thị."],["材料がありませんから、料理ができません。","Vì không có nguyên liệu nên tôi không nấu ăn được."],["この料理の材料を教えてください。","Hãy cho tôi biết nguyên liệu của món ăn này."]]},{"word":"鳥肉","reading":"とりにく","meaning":"thịt gà","hanViet":"ĐIỂU NHỤC","lesson":34,"ex":[["鳥肉を買いました。","Tôi đã mua thịt gà."],["鳥肉を焼いて、食べます。","Tôi nướng thịt gà rồi ăn."],["親子どんぶりに鳥肉を入れます。","Tôi cho thịt gà vào oyako-don."],["鳥肉は安いです。","Thịt gà rẻ."],["鳥肉と野菜をいためます。","Tôi xào thịt gà với rau."]]},{"word":"たまねぎ","reading":"たまねぎ","meaning":"hành củ","hanViet":"","lesson":34,"ex":[["たまねぎを切ります。","Tôi thái hành củ."],["たまねぎを小さく切ります。","Tôi thái nhỏ hành củ."],["たまねぎの４分の１を使います。","Tôi dùng một phần tư củ hành."],["たまねぎを切ると、涙が出ます。","Khi thái hành củ, nước mắt chảy ra."],["たまねぎをスーパーで買いました。","Tôi đã mua hành củ ở siêu thị."]]},{"word":"４分の１","reading":"よんぶんのいち","meaning":"một phần tư","hanViet":"PHÂN NHẤT","lesson":34,"ex":[["たまねぎの４分の１を切ります。","Tôi thái một phần tư củ hành."],["ケーキの４分の１を食べました。","Tôi đã ăn một phần tư chiếc bánh."],["りんごの４分の１をください。","Cho tôi một phần tư quả táo."],["このケーキの４分の１は弟のです。","Một phần tư chiếc bánh này là của em trai."],["一日の４分の１は六時間です。","Một phần tư của một ngày là 6 giờ."]]},{"word":"調味料","reading":"ちょうみりょう","meaning":"gia vị","hanViet":"ĐIỀU VỊ LIỆU","lesson":34,"ex":[["調味料を買います。","Tôi mua gia vị."],["しょうゆは調味料です。","Xì dầu là gia vị."],["調味料は冷蔵庫にあります。","Gia vị ở trong tủ lạnh."],["塩と砂糖は調味料です。","Muối và đường là gia vị."],["調味料をたくさん使います。","Tôi dùng nhiều gia vị."]]},{"word":"なべ","reading":"なべ","meaning":"nồi","hanViet":"","lesson":34,"ex":[["なべで野菜を煮ます。","Tôi ninh rau trong nồi."],["なべに水を入れます。","Tôi cho nước vào nồi."],["大きいなべを買いました。","Tôi đã mua nồi lớn."],["なべのふたを開けます。","Tôi mở nắp nồi."],["なべを洗います。","Tôi rửa nồi."]]},{"word":"火にかけます","reading":"ひにかけます","meaning":"đun","hanViet":"HỎA","lesson":34,"ex":[["なべを火にかけます。","Tôi đặt nồi lên bếp."],["やかんを火にかけて、湯を沸かします。","Tôi đặt ấm lên bếp để đun nước nóng."],["なべを火にかけて、卵をゆでます。","Tôi đặt nồi lên bếp để luộc trứng."],["母はなべを火にかけました。","Mẹ tôi đã đặt nồi lên bếp."],["火にかけたなべは熱いですから、気をつけてください。","Nồi đang đun thì nóng nên hãy cẩn thận."]]},{"word":"煮ます","reading":"にます","meaning":"nấu, luộc, ninh","hanViet":"CHỬ","lesson":34,"ex":[["野菜を煮ます。","Tôi ninh rau."],["卵を煮ました。","Tôi đã luộc trứng."],["肉をなべで煮ます。","Tôi ninh thịt trong nồi."],["母は魚を煮るのが上手です。","Mẹ tôi nấu cá giỏi."],["人参を煮ます。","Tôi ninh cà rốt."]]},{"word":"煮えます","reading":"にえます","meaning":"chín,được nấu","hanViet":"CHỬ","lesson":34,"ex":[["卵が煮えました。","Trứng đã chín."],["野菜が煮えるまで、待ちます。","Tôi đợi cho đến khi rau chín."],["卵が煮えたら、食べてください。","Khi trứng chín, hãy ăn nhé."],["肉がまだ煮えていません。","Thịt vẫn chưa chín."],["野菜が煮えたら、火を消します。","Khi rau chín, tôi tắt bếp."]]},{"word":"どんぶり","reading":"どんぶり","meaning":"bát ô tô lớn","hanViet":"","lesson":34,"ex":[["ごはんをどんぶりに入れます。","Tôi cho cơm vào bát ô tô."],["どんぶりでごはんを食べます。","Tôi ăn cơm bằng bát ô tô."],["大きいどんぶりを買いました。","Tôi đã mua bát ô tô lớn."],["どんぶりは大きいです。","Bát ô tô lớn."],["どんぶりは食器です。","Bát ô tô là đồ dùng để ăn."]]},{"word":"焼きます","reading":"やきます","meaning":"Nướng, đốt, rán","hanViet":"THIÊU","lesson":34,"ex":[["魚を焼きます。","Tôi nướng cá."],["パンを焼きました。","Tôi đã nướng bánh mì."],["肉を焼いて、食べます。","Tôi nướng thịt rồi ăn."],["ケーキを焼くのが好きです。","Tôi thích nướng bánh."],["魚を焼きすぎました。","Tôi đã nướng cá quá lửa."]]},{"word":"揚げます","reading":"あげます","meaning":"chiên, rán; giơ lên","hanViet":"DƯƠNG","lesson":34,"ex":[["天ぷらを揚げます。","Tôi chiên tempura."],["魚を揚げて、食べます。","Tôi chiên cá rồi ăn."],["鳥肉を揚げました。","Tôi đã chiên thịt gà."],["手を揚げてください。","Hãy giơ tay lên."],["野菜を揚げます。","Tôi chiên rau."]]},{"word":"いためます","reading":"いためます","meaning":"xào","hanViet":"","lesson":34,"ex":[["野菜をいためます。","Tôi xào rau."],["肉と野菜をいためます。","Tôi xào thịt với rau."],["鳥肉をいためて、ごはんと食べます。","Tôi xào thịt gà rồi ăn với cơm."],["たまねぎをいためます。","Tôi xào hành củ."],["人参をいためました。","Tôi đã xào cà rốt."]]},{"word":"ゆでます","reading":"ゆでます","meaning":"luộc","hanViet":"","lesson":34,"ex":[["卵をゆでます。","Tôi luộc trứng."],["野菜をゆでて、食べます。","Tôi luộc rau rồi ăn."],["うどんをゆでました。","Tôi đã luộc mì udon."],["卵をゆでるのは易しいです。","Luộc trứng thì dễ."],["人参をゆでます。","Tôi luộc cà rốt."]]},{"word":"蒸します","reading":"むします","meaning":"Hấp, chưng (thức ăn)","hanViet":"CHƯNG","lesson":34,"ex":[["野菜を蒸します。","Tôi hấp rau."],["魚を蒸して、食べます。","Tôi hấp cá rồi ăn."],["卵を蒸しました。","Tôi đã hấp trứng."],["肉を蒸します。","Tôi hấp thịt."],["母は魚を蒸すのが上手です。","Mẹ tôi hấp cá giỏi."]]},{"word":"炊きます","reading":"たきます","meaning":"nấu (cơm)","hanViet":"XUY","lesson":34,"ex":[["ごはんを炊きます。","Tôi nấu cơm."],["母は毎朝ごはんを炊きます。","Mẹ tôi nấu cơm mỗi sáng."],["朝、炊飯器でごはんを炊きます。","Sáng tôi nấu cơm bằng nồi cơm điện."],["ごはんを炊いて、弁当を作ります。","Tôi nấu cơm rồi làm cơm hộp."],["米を炊きました。","Tôi đã nấu gạo."]]},{"word":"むきます","reading":"むきます","meaning":"gọt, bóc","hanViet":"","lesson":34,"ex":[["りんごをむきます。","Tôi gọt táo."],["みかんをむいて、食べます。","Tôi bóc quýt rồi ăn."],["人参をむきます。","Tôi gọt cà rốt."],["りんごをむいて、母にあげました。","Tôi đã gọt táo rồi đưa cho mẹ."],["みかんをむくのは易しいです。","Bóc quýt thì dễ."]]},{"word":"刻みます","reading":"きざみます","meaning":"Khắc, chạm; thái nhỏ, băm","hanViet":"KHẮC","lesson":34,"ex":[["たまねぎを刻みます。","Tôi băm hành củ."],["ねぎを刻んで、料理に入れます。","Tôi thái hành lá rồi cho vào món ăn."],["人参を小さく刻みます。","Tôi thái nhỏ cà rốt."],["母はたまねぎを刻むのが上手です。","Mẹ tôi băm hành giỏi."],["名前を木に刻みました。","Tôi đã khắc tên lên gỗ."]]},{"word":"かき混ぜます","reading":"かきまぜます","meaning":"khuấy","hanViet":"HỖN","lesson":34,"ex":[["卵をかき混ぜます。","Tôi khuấy trứng."],["コーヒーに砂糖を入れて、かき混ぜます。","Tôi cho đường vào cà phê rồi khuấy."],["なべの中をかき混ぜます。","Tôi khuấy trong nồi."],["ジュースをかき混ぜて、飲みます。","Tôi khuấy nước ép rồi uống."],["おたまでかき混ぜます。","Tôi khuấy bằng muôi."]]},{"word":"台所用品","reading":"だいどころようひん","meaning":"Đồ dùng trong bếp","hanViet":"ĐÀI SỞ DỤNG PHẨM","lesson":34,"ex":[["台所用品を買いました。","Tôi đã mua đồ dùng nhà bếp."],["この店は台所用品が多いです。","Cửa hàng này có nhiều đồ dùng nhà bếp."],["台所用品を台所に置きます。","Tôi đặt đồ dùng nhà bếp vào bếp."],["なべややかんは台所用品です。","Nồi và ấm nước là đồ dùng nhà bếp."],["台所用品は便利です。","Đồ dùng nhà bếp tiện lợi."]]},{"word":"やかん","reading":"やかん","meaning":"cái ấm nước","hanViet":"","lesson":34,"ex":[["やかんに水を入れます。","Tôi cho nước vào ấm."],["やかんを火にかけます。","Tôi đặt ấm lên bếp."],["やかんの湯は熱いです。","Nước nóng trong ấm thì nóng."],["やかんを店で買いました。","Tôi đã mua ấm nước ở cửa hàng."],["やかんのふたを開けます。","Tôi mở nắp ấm."]]},{"word":"ふた","reading":"ふた","meaning":"cái nắp","hanViet":"","lesson":34,"ex":[["なべのふたを開けました。","Tôi đã mở nắp nồi."],["ふたを閉めてください。","Hãy đậy nắp lại."],["やかんのふたがありません。","Ấm nước không có nắp."],["ふたを開けて、なべの中を見ます。","Tôi mở nắp rồi nhìn vào trong nồi."],["このふたは大きいです。","Chiếc nắp này lớn."]]},{"word":"おたま","reading":"おたま","meaning":"cái muỗng","hanViet":"","lesson":34,"ex":[["おたまをスーパーで買いました。","Tôi đã mua muôi ở siêu thị."],["おたまでなべの野菜を皿に入れます。","Tôi dùng muôi múc rau trong nồi cho vào đĩa."],["おたまは台所用品です。","Muôi là đồ dùng nhà bếp."],["新しいおたまを使います。","Tôi dùng muôi mới."],["おたまがありませんから、買います。","Vì không có muôi nên tôi mua."]]},{"word":"まな板","reading":"まないた","meaning":"cái thớt","hanViet":"BẢN","lesson":34,"ex":[["まな板で野菜を切ります。","Tôi thái rau trên thớt."],["まな板を洗います。","Tôi rửa thớt."],["新しいまな板を買いました。","Tôi đã mua thớt mới."],["まな板が小さいですから、大きいまな板を買います。","Vì thớt nhỏ nên tôi mua thớt lớn."],["まな板と包丁を使います。","Tôi dùng thớt và dao."]]},{"word":"包丁","reading":"ほうちょう","meaning":"Dao làm bếp","hanViet":"BAO ĐINH","lesson":34,"ex":[["包丁で野菜を切ります。","Tôi thái rau bằng dao."],["包丁は危ないですから、気をつけてください。","Dao nguy hiểm nên hãy cẩn thận."],["新しい包丁を買いました。","Tôi đã mua dao mới."],["母は包丁を使うのが上手です。","Mẹ tôi dùng dao giỏi."],["包丁をまな板の上に置きます。","Tôi đặt dao lên thớt."]]},{"word":"ふきん","reading":"ふきん","meaning":"khăn lau, giấy lau","hanViet":"","lesson":34,"ex":[["ふきんでテーブルをきれいにします。","Tôi lau bàn sạch bằng khăn."],["ふきんを洗います。","Tôi giặt khăn lau."],["ふきんを二枚買いました。","Tôi đã mua hai chiếc khăn lau."],["ふきんが汚いですから、洗います。","Vì khăn lau bẩn nên tôi giặt."],["ふきんは台所にあります。","Khăn lau ở trong bếp."]]},{"word":"炊飯器","reading":"すいはんき","meaning":"nồi cơm điện","hanViet":"XUY PHẠN KHÍ","lesson":34,"ex":[["新しい炊飯器を買いました。","Tôi đã mua nồi cơm điện mới."],["炊飯器でごはんを炊きます。","Tôi nấu cơm bằng nồi cơm điện."],["炊飯器のごはんはおいしいです。","Cơm nấu bằng nồi cơm điện ngon."],["炊飯器の中を洗います。","Tôi rửa bên trong nồi cơm điện."],["炊飯器は台所にあります。","Nồi cơm điện ở trong bếp."]]},{"word":"しゃもじ","reading":"しゃもじ","meaning":"thìa dẹt xới cơm","hanViet":"","lesson":34,"ex":[["しゃもじでごはんを入れます。","Tôi xới cơm bằng thìa dẹt."],["しゃもじを店で買いました。","Tôi đã mua thìa xới cơm ở cửa hàng."],["しゃもじは台所用品です。","Thìa xới cơm là đồ dùng nhà bếp."],["新しいしゃもじを使います。","Tôi dùng thìa xới cơm mới."],["しゃもじはごはんを入れるときに使います。","Thìa dẹt dùng khi xới cơm."]]},{"word":"缶切り","reading":"かんきり","meaning":"Đồ khui lon","hanViet":"PHẪU THIẾT","lesson":34,"ex":[["缶切りで缶詰を開けます。","Tôi khui đồ hộp bằng đồ khui lon."],["缶切りをスーパーで買いました。","Tôi đã mua đồ khui lon ở siêu thị."],["缶切りがありませんから、開けられません。","Vì không có đồ khui lon nên tôi không mở được."],["缶切りは台所にあります。","Đồ khui lon ở trong bếp."],["新しい缶切りを使います。","Tôi dùng đồ khui lon mới."]]},{"word":"ざる","reading":"ざる","meaning":"cái rá","hanViet":"","lesson":34,"ex":[["ざるで野菜を洗います。","Tôi rửa rau bằng rá."],["ざるに野菜を入れます。","Tôi cho rau vào rá."],["大きいざるを買いました。","Tôi đã mua rá lớn."],["ざるで水を切ります。","Tôi để ráo nước bằng rá."],["ざるは台所用品です。","Rá là đồ dùng nhà bếp."]]},{"word":"ガス台","reading":"ガスだい","meaning":"bếp ga","hanViet":"ĐÀI","lesson":34,"ex":[["ガス台で料理を作ります。","Tôi nấu ăn bằng bếp ga."],["ガス台の火をつけます。","Tôi bật lửa bếp ga."],["ガス台の火を消します。","Tôi tắt lửa bếp ga."],["ガス台を掃除します。","Tôi dọn bếp ga."],["新しいガス台を買いました。","Tôi đã mua bếp ga mới."]]},{"word":"流し台","reading":"ながしだい","meaning":"chậu rửa, bồn rửa","hanViet":"LƯU ĐÀI","lesson":34,"ex":[["流し台で皿を洗います。","Tôi rửa đĩa ở bồn rửa."],["流し台の水が止まりません。","Nước ở bồn rửa không ngừng chảy."],["流し台を掃除します。","Tôi dọn bồn rửa."],["流し台に水があります。","Trong bồn rửa có nước."],["流し台は台所にあります。","Bồn rửa ở trong bếp."]]},{"word":"換気扇","reading":"かんきせん","meaning":"quạt hút khí","hanViet":"HOÁN KHÍ PHIẾN","lesson":34,"ex":[["換気扇を回してください。","Hãy bật quạt hút khí."],["料理のときは、換気扇を回します。","Khi nấu ăn, tôi bật quạt hút khí."],["換気扇の音が聞こえます。","Nghe thấy tiếng quạt hút khí."],["換気扇を掃除します。","Tôi dọn quạt hút khí."],["換気扇が古いですから、新しいのを買います。","Vì quạt hút khí cũ nên tôi mua cái mới."]]},{"word":"質問します","reading":"しつもんします","meaning":"hỏi","hanViet":"CHẤT VẤN","lesson":34,"ex":[["先生に質問します。","Tôi hỏi thầy giáo."],["わからないときは、質問してください。","Khi không hiểu, hãy hỏi nhé."],["友達に日本語の質問をしました。","Tôi đã hỏi bạn câu hỏi tiếng Nhật."],["授業で質問します。","Tôi hỏi trong giờ học."],["質問したいことがたくさんあります。","Tôi có nhiều điều muốn hỏi."]]},{"word":"スポーツクラブ","reading":"スポーツクラブ","meaning":"câu lạc bộ thể thao","hanViet":"","lesson":34,"ex":[["スポーツクラブへ行きます。","Tôi đến câu lạc bộ thể thao."],["スポーツクラブで泳ぎます。","Tôi bơi ở câu lạc bộ thể thao."],["スポーツクラブの会員です。","Tôi là hội viên câu lạc bộ thể thao."],["スポーツクラブでテニスをします。","Tôi chơi tennis ở câu lạc bộ thể thao."],["スポーツクラブは日曜日も開いています。","Câu lạc bộ thể thao mở cả Chủ nhật."]]},{"word":"キー","reading":"キー","meaning":"chìa khóa","hanViet":"","lesson":34,"ex":[["車のキーをどこに置きましたか。","Bạn đã để chìa khóa xe ở đâu?"],["家のキーをなくしました。","Tôi đã làm mất chìa khóa nhà."],["このキーはドアのキーです。","Chiếc chìa khóa này là chìa khóa cửa."],["キーをかばんに入れました。","Tôi đã bỏ chìa khóa vào cặp."],["母はキーを私にくれました。","Mẹ đã đưa chìa khóa cho tôi."]]},{"word":"シートベルト","reading":"シートベルト","meaning":"dây an toàn (ở ghế ngồi)","hanViet":"","lesson":34,"ex":[["車に乗ったら、シートベルトをしてください。","Khi lên xe, hãy thắt dây an toàn."],["シートベルトをしないと、危ないです。","Không thắt dây an toàn thì nguy hiểm."],["運転手はシートベルトをしています。","Tài xế đang thắt dây an toàn."],["子どももシートベルトをしなければなりません。","Trẻ em cũng phải thắt dây an toàn."],["シートベルトが壊れました。","Dây an toàn bị hỏng rồi."]]},{"word":"図","reading":"ず","meaning":"sơ đồ, hình vẽ","hanViet":"ĐỒ","lesson":34,"ex":[["この図を見てください。","Hãy xem sơ đồ này."],["図を見て、作ります。","Tôi nhìn sơ đồ rồi làm theo."],["本に大きい図があります。","Trong sách có một hình vẽ lớn."],["先生は図を書きました。","Thầy giáo đã vẽ sơ đồ."],["図の色は赤です。","Màu của hình vẽ là đỏ."]]},{"word":"ソース","reading":"ソース","meaning":"nước chấm, nước xốt","hanViet":"","lesson":34,"ex":[["このソースは辛いです。","Nước xốt này cay."],["肉にソースをかけます。","Tôi rưới nước xốt lên thịt."],["ソースをもう少しください。","Cho tôi thêm một chút nước xốt."],["この店のソースはおいしいです。","Nước xốt của quán này ngon."],["スーパーでソースを買いました。","Tôi đã mua nước xốt ở siêu thị."]]},{"word":"これでいいですか","reading":"これでいいですか","meaning":"Thế này được không/đã được chưa","hanViet":"","lesson":34,"ex":[["これでいいですか。","Thế này được không?"],["荷物はこれでいいですか。","Hành lý thế này được chưa?"],["写真はこれでいいですか。","Ảnh thế này được không?"],["部屋はこれでいいですか。","Phòng thế này được không?"],["これでいいですか、と店員に聞きました。","Tôi hỏi nhân viên cửa hàng: Thế này được không?"]]},{"word":"火","reading":"ひ","meaning":"lửa","hanViet":"HỎA","lesson":34,"ex":[["火がつきました。","Lửa đã cháy."],["火を消してください。","Hãy dập lửa."],["火は危ないです。","Lửa nguy hiểm."],["火で肉を焼きます。","Tôi nướng thịt bằng lửa."],["火が消えました。","Lửa đã tắt."]]},{"word":"咲きます","reading":"さきます","meaning":"Nở (hoa)","hanViet":"TIẾU","lesson":35,"ex":[["桜が咲きました。","Hoa anh đào đã nở."],["春に花が咲きます。","Mùa xuân hoa nở."],["庭に花が咲いています。","Trong vườn hoa đang nở."],["桜はいつ咲きますか。","Hoa anh đào nở khi nào?"],["この花は夏に咲きます。","Bông hoa này nở vào mùa hè."]]},{"word":"変わります","reading":"かわります","meaning":"Thay đổi, biến đổi","hanViet":"BIẾN","lesson":35,"ex":[["天気が変わりました。","Thời tiết đã thay đổi."],["町は変わりました。","Thị trấn đã thay đổi."],["値段が変わりました。","Giá đã thay đổi."],["季節が変わります。","Mùa thay đổi."],["私の生活が変わりました。","Cuộc sống của tôi đã thay đổi."]]},{"word":"拾います","reading":"ひろいます","meaning":"nhặt (lên)","hanViet":"THẬP","lesson":35,"ex":[["道でお金を拾いました。","Tôi nhặt được tiền trên đường."],["公園でごみを拾います。","Tôi nhặt rác ở công viên."],["子どもが石を拾いました。","Đứa trẻ đã nhặt một hòn đá."],["落ちた本を拾いました。","Tôi đã nhặt quyển sách bị rơi."],["母は落ちたボールを拾いました。","Mẹ đã nhặt quả bóng bị rơi."]]},{"word":"かかります","reading":"かかります","meaning":"có điện thoại gọi đến","hanViet":"","lesson":35,"ex":[["電話がかかりました。","Có điện thoại gọi đến."],["母から電話がかかります。","Mẹ gọi điện thoại đến."],["昼に電話がかかりました。","Buổi trưa có điện thoại gọi đến."],["知らない人から電話がかかりました。","Có điện thoại gọi đến từ người lạ."],["電話がかかると、母が出ます。","Khi có điện thoại gọi đến, mẹ nghe máy."]]},{"word":"楽な","reading":"らくな","meaning":"Thoải mái, nhẹ nhõm, dễ dàng","hanViet":"LẠC","lesson":35,"ex":[["この仕事は楽です。","Công việc này nhẹ nhàng."],["楽な服を着ます。","Tôi mặc quần áo thoải mái."],["このいすは楽です。","Chiếc ghế này ngồi thoải mái."],["楽な生活をしています。","Tôi đang sống thoải mái."],["電車で行くと、楽です。","Đi bằng tàu điện thì thoải mái."]]},{"word":"正しい","reading":"ただしい","meaning":"đúng, chính xác","hanViet":"CHÍNH","lesson":35,"ex":[["答えは正しいです。","Đáp án đúng."],["正しい答えを教えてください。","Hãy cho tôi biết đáp án đúng."],["山田さんの答えは正しいです。","Đáp án của anh Yamada đúng."],["正しい道を教えてください。","Hãy chỉ cho tôi đường đúng."],["正しい日本語を話したいです。","Tôi muốn nói tiếng Nhật đúng."]]},{"word":"珍しい","reading":"めずらしい","meaning":"Hiếm, hiếm có, lạ","hanViet":"TRÂN","lesson":35,"ex":[["珍しい花を見ました。","Tôi đã thấy một bông hoa hiếm."],["これは珍しい本です。","Đây là một quyển sách hiếm."],["珍しい鳥がいます。","Có một con chim lạ."],["珍しい料理を食べました。","Tôi đã ăn một món ăn lạ."],["その魚は珍しいです。","Con cá đó hiếm."]]},{"word":"方","reading":"かた","meaning":"Người, vị (kính ngữ)","hanViet":"PHƯƠNG","lesson":35,"ex":[["あの方は先生です。","Vị kia là thầy giáo."],["この方は山田さんです。","Vị này là anh Yamada."],["あの方はどなたですか。","Vị kia là ai?"],["その方は日本語が上手です。","Vị ấy giỏi tiếng Nhật."],["あの方は私の父です。","Vị kia là bố tôi."]]},{"word":"向こう","reading":"むこう","meaning":"Phía bên kia, đằng kia","hanViet":"HƯỚNG","lesson":35,"ex":[["向こうに山が見えます。","Phía đằng kia nhìn thấy núi."],["川の向こうに家があります。","Bên kia sông có một ngôi nhà."],["向こうの店で買いました。","Tôi đã mua ở cửa hàng đằng kia."],["向こうに海が見えます。","Phía đằng kia nhìn thấy biển."],["道の向こうに公園があります。","Bên kia đường có công viên."]]},{"word":"島","reading":"しま","meaning":"Đảo, hòn đảo","hanViet":"ĐẢO","lesson":35,"ex":[["その島は小さいです。","Hòn đảo đó nhỏ."],["島へ船で行きます。","Tôi đi tàu ra đảo."],["島に住んでいます。","Tôi sống trên đảo."],["その島は有名です。","Hòn đảo đó nổi tiếng."],["島の海はきれいです。","Biển của đảo đẹp."]]},{"word":"村","reading":"むら","meaning":"Làng","hanViet":"THÔN","lesson":35,"ex":[["村に住んでいます。","Tôi sống ở làng."],["その村は山の中にあります。","Làng đó nằm trong núi."],["村の人は元気です。","Người làng khỏe mạnh."],["小さい村で生まれました。","Tôi sinh ra ở một làng nhỏ."],["村に学校があります。","Trong làng có trường học."]]},{"word":"港","reading":"みなと","meaning":"Cảng, bến cảng","hanViet":"CẢNG","lesson":35,"ex":[["港に船があります。","Ở cảng có tàu."],["港で魚を買いました。","Tôi đã mua cá ở cảng."],["この港は大きいです。","Cảng này lớn."],["港から船が出ます。","Tàu rời cảng."],["港の近くに住んでいます。","Tôi sống gần cảng."]]},{"word":"近所","reading":"きんじょ","meaning":"Hàng xóm, vùng lân cận","hanViet":"CẬN SỞ","lesson":35,"ex":[["近所に公園があります。","Gần nhà có công viên."],["近所の人が来ました。","Người hàng xóm đã đến."],["近所の店で買いました。","Tôi đã mua ở cửa hàng gần nhà."],["近所は静かです。","Khu vực gần nhà yên tĩnh."],["近所を散歩します。","Tôi đi dạo quanh khu vực gần nhà."]]},{"word":"屋上","reading":"おくじょう","meaning":"Sân thượng, mái nhà","hanViet":"ỐC THƯỢNG","lesson":35,"ex":[["屋上で写真を撮りました。","Tôi đã chụp ảnh trên sân thượng."],["屋上から海が見えます。","Từ sân thượng nhìn thấy biển."],["屋上で花を育てます。","Tôi trồng hoa trên sân thượng."],["屋上に上がりました。","Tôi đã lên sân thượng."],["子どもは屋上で遊びます。","Trẻ em chơi trên sân thượng."]]},{"word":"海外","reading":"かいがい","meaning":"Nước ngoài, hải ngoại","hanViet":"HẢI NGOẠI","lesson":35,"ex":[["海外へ旅行します。","Tôi đi du lịch nước ngoài."],["海外で働いています。","Tôi đang làm việc ở nước ngoài."],["海外の友達に会いました。","Tôi đã gặp bạn bè ở nước ngoài."],["海外から手紙が来ました。","Có thư từ nước ngoài gửi đến."],["海外へ行ったことがあります。","Tôi đã từng đi nước ngoài."]]},{"word":"山登り","reading":"やまのぼり","meaning":"leo núi","hanViet":"SƠN ĐĂNG","lesson":35,"ex":[["山登りが好きです。","Tôi thích leo núi."],["日曜日に山登りをします。","Chủ nhật tôi đi leo núi."],["友達と山登りをしました。","Tôi đã leo núi cùng bạn."],["山登りは楽しいです。","Leo núi vui."],["秋に山登りをします。","Mùa thu tôi đi leo núi."]]},{"word":"機会","reading":"きかい","meaning":"cơ hội","hanViet":"CƠ HỘI","lesson":35,"ex":[["いい機会です。","Đây là cơ hội tốt."],["機会があれば、行きたいです。","Nếu có cơ hội, tôi muốn đi."],["日本語を話す機会がありません。","Tôi không có cơ hội nói tiếng Nhật."],["この機会に、勉強します。","Nhân cơ hội này, tôi sẽ học."],["先生に会う機会がありました。","Tôi đã có cơ hội gặp thầy giáo."]]},{"word":"許可","reading":"きょか","meaning":"Cho phép, giấy phép","hanViet":"HỨA KHẢ","lesson":35,"ex":[["許可をもらいました。","Tôi đã được cho phép."],["先生の許可が要ります。","Cần sự cho phép của thầy giáo."],["許可がなければ、入れません。","Nếu không có sự cho phép thì không vào được."],["許可をください。","Xin hãy cho phép tôi."],["許可をもらって、写真を撮りました。","Tôi được phép rồi chụp ảnh."]]},{"word":"丸","reading":"まる","meaning":"Hình tròn, viên tròn","hanViet":"HOÀN","lesson":35,"ex":[["丸を書いてください。","Hãy vẽ một hình tròn."],["この丸は大きいです。","Hình tròn này lớn."],["答えに丸をつけました。","Tôi đã đánh dấu tròn vào đáp án."],["丸の形が好きです。","Tôi thích hình tròn."],["このケーキは丸です。","Chiếc bánh này hình tròn."]]},{"word":"操作","reading":"そうさ","meaning":"thao tác, vận hành","hanViet":"THAO TÁC","lesson":35,"ex":[["操作は簡単です。","Thao tác đơn giản."],["操作の方法を教えてください。","Hãy chỉ cho tôi cách thao tác."],["この機械の操作は難しいです。","Việc vận hành máy này khó."],["操作がわかりません。","Tôi không hiểu cách thao tác."],["パソコンの操作を習います。","Tôi học cách thao tác máy tính."]]},{"word":"方法","reading":"ほうほう","meaning":"Phương pháp","hanViet":"PHƯƠNG PHÁP","lesson":35,"ex":[["方法を教えてください。","Hãy chỉ cho tôi phương pháp."],["いい方法があります。","Có một cách hay."],["この方法は簡単です。","Cách này đơn giản."],["日本語の勉強の方法を習いました。","Tôi đã học phương pháp học tiếng Nhật."],["新しい方法を考えます。","Tôi nghĩ cách mới."]]},{"word":"設備","reading":"せつび","meaning":"Thiết bị, trang bị","hanViet":"THIẾT BỊ","lesson":35,"ex":[["このホテルの設備はいいです。","Thiết bị của khách sạn này tốt."],["設備が新しいです。","Thiết bị mới."],["学校の設備を直します。","Tôi sửa thiết bị của trường."],["設備が壊れました。","Thiết bị bị hỏng."],["この部屋の設備は古いです。","Thiết bị của phòng này cũ."]]},{"word":"ひも","reading":"ひも","meaning":"sợi dây","hanViet":"","lesson":35,"ex":[["このひもは長いです。","Sợi dây này dài."],["ひもをください。","Cho tôi sợi dây."],["ひもが切れました。","Dây bị đứt."],["赤いひもを買いました。","Tôi đã mua sợi dây màu đỏ."],["長いひもが要ります。","Tôi cần một sợi dây dài."]]},{"word":"葉","reading":"は","meaning":"lá cây","hanViet":"DIỆP","lesson":35,"ex":[["葉が落ちました。","Lá đã rơi."],["木の葉は緑です。","Lá cây màu xanh."],["葉を集めます。","Tôi gom lá."],["秋に葉の色が変わります。","Mùa thu màu lá thay đổi."],["葉が大きくなりました。","Lá đã lớn lên."]]},{"word":"曲","reading":"きょく","meaning":"Bản nhạc, bài hát","hanViet":"KHÚC","lesson":35,"ex":[["この曲は有名です。","Bản nhạc này nổi tiếng."],["好きな曲を聞きます。","Tôi nghe bản nhạc yêu thích."],["曲を歌います。","Tôi hát bài hát."],["新しい曲を買いました。","Tôi đã mua bản nhạc mới."],["この曲が好きです。","Tôi thích bản nhạc này."]]},{"word":"楽しみ","reading":"たのしみ","meaning":"Điều mong chờ, niềm vui sắp tới","hanViet":"LẠC","lesson":35,"ex":[["旅行が楽しみです。","Tôi mong chờ chuyến du lịch."],["週末が楽しみです。","Tôi mong chờ cuối tuần."],["あしたの試合が楽しみです。","Tôi mong chờ trận đấu ngày mai."],["母に会うのが楽しみです。","Tôi mong chờ được gặp mẹ."],["誕生日が楽しみです。","Tôi mong chờ sinh nhật."]]},{"word":"もっと","reading":"もっと","meaning":"hơn , nữa","hanViet":"","lesson":35,"ex":[["もっと勉強します。","Tôi học nhiều hơn."],["もっと速く走ります。","Tôi chạy nhanh hơn."],["もっと水をください。","Cho tôi thêm nước."],["もっと日本語を話したいです。","Tôi muốn nói tiếng Nhật nhiều hơn."],["もっと大きな部屋に住みたいです。","Tôi muốn sống trong căn phòng lớn hơn."]]},{"word":"初めに","reading":"はじめに","meaning":"đầu tiên , trước hết","hanViet":"SƠ","lesson":35,"ex":[["初めに、名前を書いてください。","Trước hết, hãy viết tên."],["初めに、部屋を掃除します。","Trước hết, tôi dọn phòng."],["初めに、この本を読みます。","Trước hết, tôi đọc quyển sách này."],["初めに、先生にあいさつをします。","Trước hết, tôi chào thầy giáo."],["初めに、手を洗います。","Trước hết, tôi rửa tay."]]},{"word":"それなら","reading":"それなら","meaning":"nếu thế thì, vậy thì","hanViet":"","lesson":35,"ex":[["それなら、行きません。","Nếu thế thì tôi không đi."],["それなら、明日行きましょう。","Vậy thì ngày mai chúng ta đi nhé."],["それなら、大丈夫です。","Vậy thì không sao."],["それなら、電車で行きます。","Vậy thì tôi đi bằng tàu điện."],["それなら、ここで待ちます。","Vậy thì tôi đợi ở đây."]]},{"word":"夜行バス","reading":"やこうバス","meaning":"xe buýt chạy đêm","hanViet":"DẠ HÀNH","lesson":35,"ex":[["夜行バスで京都へ行きます。","Tôi đi Kyoto bằng xe buýt đêm."],["夜行バスは安いです。","Xe buýt đêm rẻ."],["夜行バスに乗りました。","Tôi đã đi xe buýt đêm."],["夜行バスで東京へ帰ります。","Tôi về Tokyo bằng xe buýt đêm."],["夜行バスのチケットを買いました。","Tôi đã mua vé xe buýt đêm."]]},{"word":"旅行社","reading":"りょこうしゃ","meaning":"công ty du lịch","hanViet":"LỮ HÀNH XÃ","lesson":35,"ex":[["旅行社でチケットを買いました。","Tôi đã mua vé ở công ty du lịch."],["旅行社に電話をしました。","Tôi đã gọi điện cho công ty du lịch."],["旅行社の人が教えてくれました。","Người của công ty du lịch đã chỉ cho tôi."],["旅行社で働いています。","Tôi làm việc ở công ty du lịch."],["旅行社に行きました。","Tôi đã đến công ty du lịch."]]},{"word":"詳しい","reading":"くわしい","meaning":"cụ thể, chi tiết","hanViet":"TƯỜNG","lesson":35,"ex":[["詳しく教えてください。","Hãy nói cho tôi biết chi tiết."],["詳しい地図があります。","Có một tấm bản đồ chi tiết."],["山田さんは日本について詳しいです。","Anh Yamada biết rõ về Nhật Bản."],["詳しい話を聞きました。","Tôi đã nghe câu chuyện chi tiết."],["詳しい本を読みます。","Tôi đọc quyển sách chi tiết."]]},{"word":"スキー場","reading":"スキーじょう","meaning":"bãi trượt tuyết","hanViet":"TRƯỜNG","lesson":35,"ex":[["スキー場へ行きます。","Tôi đi bãi trượt tuyết."],["スキー場でスキーをします。","Tôi trượt tuyết ở bãi trượt tuyết."],["このスキー場は大きいです。","Bãi trượt tuyết này lớn."],["冬にスキー場へ行きます。","Mùa đông tôi đi bãi trượt tuyết."],["スキー場は山にあります。","Bãi trượt tuyết nằm trên núi."]]},{"word":"朱","reading":"しゅ","meaning":"màu đỏ son","hanViet":"CHU","lesson":35,"ex":[["朱の色が好きです。","Tôi thích màu đỏ son."],["この花は朱です。","Bông hoa này màu đỏ son."],["朱色の花が咲きました。","Hoa màu đỏ son đã nở."],["朱の服を着ます。","Tôi mặc quần áo màu đỏ son."],["朱のカーテンを買いました。","Tôi đã mua rèm màu đỏ son."]]},{"word":"交わります","reading":"まじわります","meaning":"giao lưu, quan hệ với","hanViet":"GIAO","lesson":35,"ex":[["町の人と交わります。","Tôi giao lưu với người dân trong thị trấn."],["日本でたくさんの人と交わりました。","Ở Nhật tôi đã giao lưu với nhiều người."],["外国の人と交わりたいです。","Tôi muốn giao lưu với người nước ngoài."],["学校で友達と交わります。","Ở trường tôi giao lưu với bạn bè."],["交わる機会が少ないです。","Cơ hội giao lưu ít."]]},{"word":"ことわざ","reading":"ことわざ","meaning":"tục ngữ","hanViet":"","lesson":35,"ex":[["ことわざを習いました。","Tôi đã học tục ngữ."],["日本のことわざを知っています。","Tôi biết tục ngữ Nhật."],["先生がことわざを教えてくれました。","Thầy giáo đã dạy tôi tục ngữ."],["ことわざの本を読みます。","Tôi đọc sách tục ngữ."],["このことわざは有名です。","Câu tục ngữ này nổi tiếng."]]},{"word":"仲よくします","reading":"なかよくします","meaning":"quan hệ tốt với, chơi thân với","hanViet":"TRỌNG","lesson":35,"ex":[["友達と仲よくします。","Tôi chơi thân với bạn."],["隣の人と仲よくしています。","Tôi đang chơi thân với người hàng xóm."],["子どもと仲よくします。","Tôi chơi thân với trẻ em."],["クラスの人と仲よくします。","Tôi chơi thân với mọi người trong lớp."],["山田さんと仲よくしています。","Tôi đang thân với anh Yamada."]]},{"word":"必要な","reading":"ひつような","meaning":"cần thiết","hanViet":"TẤT YẾU","lesson":35,"ex":[["お金が必要です。","Cần tiền."],["必要な本を持ってきました。","Tôi đã mang quyển sách cần thiết."],["日本語の勉強に必要な本です。","Đây là quyển sách cần thiết cho việc học tiếng Nhật."],["必要な時間は2時間です。","Thời gian cần thiết là 2 tiếng."],["必要なとき、電話してください。","Khi cần, hãy gọi điện."]]},{"word":"ハイキング","reading":"ハイキング","meaning":"đi bộ trên núi","hanViet":"","lesson":35,"ex":[["ハイキングが好きです。","Tôi thích đi bộ trên núi."],["日曜日にハイキングをします。","Chủ nhật tôi đi bộ trên núi."],["友達とハイキングをしました。","Tôi đã đi bộ trên núi cùng bạn."],["ハイキングは楽しいです。","Đi bộ trên núi vui."],["春にハイキングをします。","Mùa xuân tôi đi bộ trên núi."]]},{"word":"カーテン","reading":"カーテン","meaning":"cái rèm","hanViet":"","lesson":35,"ex":[["カーテンを開けます。","Tôi mở rèm."],["カーテンを閉めます。","Tôi đóng rèm."],["新しいカーテンを買いました。","Tôi đã mua rèm mới."],["カーテンは青いです。","Rèm màu xanh dương."],["カーテンを洗います。","Tôi giặt rèm."]]},{"word":"これで終わります","reading":"これでおわります","meaning":"đến đây là hết, chúng ta dừng ở đây","hanViet":"CHUNG","lesson":35,"ex":[["これで終わります。","Đến đây là hết."],["きょうの授業はこれで終わります。","Buổi học hôm nay đến đây là hết."],["これで終わります、と先生が言いました。","Thầy giáo nói: Đến đây là hết."],["会議はこれで終わります。","Cuộc họp đến đây là hết."],["話はこれで終わります。","Câu chuyện đến đây là hết."]]},{"word":"届きます","reading":"とどきます","meaning":"Đến nơi, tới tay (thư, hàng)","hanViet":"GIỚI","lesson":36,"ex":[["手紙が届きました。","Thư đã đến."],["荷物が届きました。","Hàng đã đến."],["本が届きます。","Sách sẽ đến."],["母からの手紙が届きました。","Thư của mẹ đã đến."],["プレゼントが届きました。","Quà đã đến."]]},{"word":"出ます","reading":"でます","meaning":"Đi ra, ra ngoài","hanViet":"XUẤT","lesson":36,"ex":[["家を出ます。","Tôi ra khỏi nhà."],["部屋を出ました。","Tôi đã ra khỏi phòng."],["7時に家を出ます。","7 giờ tôi ra khỏi nhà."],["駅を出て、右へ行きます。","Ra khỏi ga, đi sang phải."],["会社を出ました。","Tôi đã rời công ty."]]},{"word":"貯金します","reading":"ちょきんします","meaning":"tiết kiệm tiền, để dành tiền","hanViet":"TRỮ KIM","lesson":36,"ex":[["貯金をします。","Tôi tiết kiệm tiền."],["毎月、貯金します。","Mỗi tháng tôi tiết kiệm tiền."],["旅行のために、貯金しています。","Tôi đang tiết kiệm tiền để đi du lịch."],["銀行に貯金します。","Tôi gửi tiết kiệm ở ngân hàng."],["貯金が増えました。","Tiền tiết kiệm đã tăng."]]},{"word":"太ります","reading":"ふとります","meaning":"béo lên, tăng cân","hanViet":"THÁI","lesson":36,"ex":[["太りました。","Tôi đã béo lên."],["たくさん食べて、太りました。","Tôi ăn nhiều nên béo lên."],["弟は太りました。","Em trai tôi đã béo lên."],["太らないように、運動します。","Tôi tập thể dục để không béo lên."],["このごろ、太りました。","Dạo này tôi béo lên."]]},{"word":"やせます","reading":"やせます","meaning":"gầy đi, giảm cân","hanViet":"","lesson":36,"ex":[["やせました。","Tôi đã gầy đi."],["病気で、やせました。","Tôi bị ốm nên gầy đi."],["運動して、やせました。","Tôi tập thể dục nên gầy đi."],["母はやせました。","Mẹ tôi đã gầy đi."],["やせて、元気になりました。","Tôi gầy đi và trở nên khỏe mạnh."]]},{"word":"過ぎます","reading":"すぎます","meaning":"Trôi qua; quá (mức), quá đà","hanViet":"QUÁ","lesson":36,"ex":[["時間が過ぎました。","Thời gian đã trôi qua."],["10時を過ぎました。","Đã quá 10 giờ."],["夏が過ぎました。","Mùa hè đã trôi qua."],["駅を過ぎました。","Tôi đã đi qua ga."],["1年が過ぎました。","Một năm đã trôi qua."]]},{"word":"慣れます","reading":"なれます","meaning":"Quen, quen thuộc","hanViet":"QUÁN","lesson":36,"ex":[["日本の生活に慣れました。","Tôi đã quen với cuộc sống ở Nhật."],["新しい仕事に慣れました。","Tôi đã quen với công việc mới."],["東京の生活に慣れました。","Tôi đã quen với cuộc sống ở Tokyo."],["日本語に慣れました。","Tôi đã quen với tiếng Nhật."],["新しい学校に慣れました。","Tôi đã quen với trường mới."]]},{"word":"硬い","reading":"かたい","meaning":"Cứng","hanViet":"NGẠNH","lesson":36,"ex":[["このパンは硬いです。","Bánh mì này cứng."],["硬い石があります。","Có một hòn đá cứng."],["この肉は硬いです。","Thịt này cứng."],["硬いベッドで寝ます。","Tôi ngủ trên giường cứng."],["このいすは硬いです。","Chiếc ghế này cứng."]]},{"word":"軟らかい","reading":"やわらかい","meaning":"mềm","hanViet":"NHUYỄN","lesson":36,"ex":[["このパンは軟らかいです。","Bánh mì này mềm."],["軟らかいベッドで寝ます。","Tôi ngủ trên giường mềm."],["この肉は軟らかいです。","Thịt này mềm."],["軟らかい布団が好きです。","Tôi thích chăn mềm."],["赤ちゃんの手は軟らかいです。","Tay em bé mềm."]]},{"word":"電子～","reading":"でんし～","meaning":"~ điện tử","hanViet":"ĐIỆN TỬ","lesson":36,"ex":[["電子辞書を使います。","Tôi dùng từ điển điện tử."],["電子辞書は便利です。","Từ điển điện tử tiện lợi."],["電子辞書を買いました。","Tôi đã mua từ điển điện tử."],["電子メールを送ります。","Tôi gửi thư điện tử."],["先生に電子メールを書きました。","Tôi đã viết thư điện tử cho thầy giáo."]]},{"word":"携帯～","reading":"けいたい～","meaning":"cầm tay","hanViet":"HUỀ ĐÁI","lesson":36,"ex":[["携帯電話を持っています。","Tôi có điện thoại cầm tay."],["携帯電話で電話をします。","Tôi gọi điện bằng điện thoại cầm tay."],["携帯電話を買いました。","Tôi đã mua điện thoại cầm tay."],["携帯電話が壊れました。","Điện thoại cầm tay bị hỏng."],["携帯電話をなくしました。","Tôi đã làm mất điện thoại cầm tay."]]},{"word":"工場","reading":"こうじょう","meaning":"Nhà máy, xưởng","hanViet":"CÔNG TRƯỜNG","lesson":36,"ex":[["工場で働いています。","Tôi làm việc ở nhà máy."],["この工場は大きいです。","Nhà máy này lớn."],["工場を見学しました。","Tôi đã tham quan nhà máy."],["父は工場で働いています。","Bố tôi làm việc ở nhà máy."],["工場の近くに住んでいます。","Tôi sống gần nhà máy."]]},{"word":"剣道","reading":"けんどう","meaning":"kiếm đạo (kendo)","hanViet":"KIẾM ĐẠO","lesson":36,"ex":[["剣道を習います。","Tôi học kendo."],["剣道が好きです。","Tôi thích kendo."],["弟は剣道をしています。","Em trai tôi tập kendo."],["剣道の試合を見ました。","Tôi đã xem trận đấu kendo."],["剣道は日本のスポーツです。","Kendo là môn thể thao của Nhật."]]},{"word":"毎週","reading":"まいしゅう","meaning":"Mỗi tuần","hanViet":"MỖI CHU","lesson":36,"ex":[["毎週、日曜日に休みます。","Mỗi tuần tôi nghỉ vào chủ nhật."],["毎週、テニスをします。","Mỗi tuần tôi chơi tennis."],["毎週、友達に会います。","Mỗi tuần tôi gặp bạn."],["毎週、2回泳ぎます。","Mỗi tuần tôi bơi 2 lần."],["毎週、母に電話をします。","Mỗi tuần tôi gọi điện cho mẹ."]]},{"word":"毎月","reading":"まいつき","meaning":"hàng tháng","hanViet":"MỖI NGUYỆT","lesson":36,"ex":[["毎月、10日に給料をもらいます。","Hàng tháng ngày 10 tôi nhận lương."],["毎月、本を買います。","Hàng tháng tôi mua sách."],["毎月、友達に会います。","Hàng tháng tôi gặp bạn."],["毎月、1回映画を見ます。","Hàng tháng tôi xem phim 1 lần."],["毎月、家賃を払います。","Hàng tháng tôi trả tiền thuê nhà."]]},{"word":"毎年","reading":"まいねん","meaning":"Mỗi năm","hanViet":"MỖI NIÊN","lesson":36,"ex":[["毎年、旅行します。","Mỗi năm tôi đi du lịch."],["毎年、桜を見ます。","Mỗi năm tôi ngắm hoa anh đào."],["毎年、夏に海へ行きます。","Mỗi năm mùa hè tôi đi biển."],["毎年、新しい本を買います。","Mỗi năm tôi mua sách mới."],["毎年、正月に母に会います。","Mỗi năm dịp Tết tôi gặp mẹ."]]},{"word":"やっと","reading":"やっと","meaning":"cuối cùng thì","hanViet":"","lesson":36,"ex":[["やっと、宿題が終わりました。","Cuối cùng bài tập đã xong."],["やっと、日本語が話せるようになりました。","Cuối cùng tôi đã nói được tiếng Nhật."],["やっと、電車が来ました。","Cuối cùng tàu điện đã đến."],["やっと、春が来ました。","Cuối cùng mùa xuân đã đến."],["やっと、仕事が終わりました。","Cuối cùng công việc đã xong."]]},{"word":"かなり","reading":"かなり","meaning":"khá, tương đối","hanViet":"","lesson":36,"ex":[["かなり暑いです。","Khá nóng."],["かなり難しいです。","Khá khó."],["かなり疲れました。","Tôi khá mệt."],["日本語がかなり上手になりました。","Tiếng Nhật của tôi đã khá giỏi lên."],["かなり高いです。","Khá đắt."]]},{"word":"必ず","reading":"かならず","meaning":"nhất định, chắc chắn","hanViet":"TẤT","lesson":36,"ex":[["必ず、行きます。","Tôi nhất định sẽ đi."],["必ず、宿題をします。","Tôi nhất định làm bài tập."],["必ず、電話してください。","Nhất định hãy gọi điện."],["必ず、9時に来てください。","Nhất định hãy đến lúc 9 giờ."],["必ず、試験に合格します。","Tôi nhất định sẽ đỗ kỳ thi."]]},{"word":"絶対に","reading":"ぜったいに","meaning":"tuyệt đối","hanViet":"TUYỆT ĐỐI","lesson":36,"ex":[["絶対に、行きません。","Tôi tuyệt đối không đi."],["絶対に、忘れません。","Tôi tuyệt đối không quên."],["絶対に、遅れません。","Tôi tuyệt đối không đến muộn."],["絶対に、合格します。","Tôi tuyệt đối sẽ đỗ."],["絶対に、やめません。","Tôi tuyệt đối không bỏ."]]},{"word":"上手に","reading":"じょうずに","meaning":"giỏi, khéo","hanViet":"THƯỢNG THỦ","lesson":36,"ex":[["日本語を上手に話します。","Tôi nói tiếng Nhật giỏi."],["上手に歌います。","Tôi hát hay."],["上手に泳ぎます。","Tôi bơi giỏi."],["字を上手に書きます。","Tôi viết chữ đẹp."],["料理を上手に作ります。","Tôi nấu ăn khéo."]]},{"word":"このごろ","reading":"このごろ","meaning":"gần đây, dạo này","hanViet":"","lesson":36,"ex":[["このごろ、忙しいです。","Dạo này tôi bận."],["このごろ、雨が多いです。","Dạo này mưa nhiều."],["このごろ、よく勉強します。","Dạo này tôi học chăm."],["このごろ、やせました。","Dạo này tôi gầy đi."],["このごろ、寒いです。","Dạo này lạnh."]]},{"word":"～ずつ","reading":"～ずつ","meaning":"từng ~, ~ một","hanViet":"","lesson":36,"ex":[["一つずつ、見てください。","Hãy xem từng cái một."],["一人ずつ、話してください。","Hãy nói từng người một."],["二つずつ、食べました。","Tôi đã ăn từng 2 cái."],["三つずつ、買いました。","Tôi đã mua từng 3 cái."],["少しずつ、勉強します。","Tôi học từng chút một."]]},{"word":"そのほうが～","reading":"そのほうが～","meaning":"cái đó ~ hơn, như thế ~ hơn","hanViet":"","lesson":36,"ex":[["そのほうが安いです。","Cái đó rẻ hơn."],["そのほうがいいです。","Cái đó tốt hơn."],["そのほうが速いです。","Cái đó nhanh hơn."],["そのほうが便利です。","Cái đó tiện lợi hơn."],["そのほうが安全です。","Cái đó an toàn hơn."]]},{"word":"お客様","reading":"おきゃくさま","meaning":"Quý khách (kính trọng)","hanViet":"KHÁCH DẠNG","lesson":36,"ex":[["お客様がいらっしゃいました。","Quý khách đã đến."],["お客様にコーヒーを出します。","Tôi mang cà phê ra cho quý khách."],["お客様は多いです。","Quý khách đông."],["お客様をお待ちしています。","Tôi đang đợi quý khách."],["お客様に手紙を書きます。","Tôi viết thư cho quý khách."]]},{"word":"特別","reading":"とくべつ","meaning":"Đặc biệt","hanViet":"ĐẶC BIỆT","lesson":36,"ex":[["特別な日です。","Là một ngày đặc biệt."],["特別なプレゼントを買いました。","Tôi đã mua một món quà đặc biệt."],["特別な料理を作ります。","Tôi nấu một món ăn đặc biệt."],["きょうは特別です。","Hôm nay đặc biệt."],["特別な花をもらいました。","Tôi đã nhận một bông hoa đặc biệt."]]},{"word":"していらっしゃいます","reading":"していらっしゃいます","meaning":"đang làm (tôn kính ngữ của しています）","hanViet":"","lesson":36,"ex":[["先生は何をしていらっしゃいますか。","Thầy giáo đang làm gì ạ?"],["社長は会議をしていらっしゃいます。","Giám đốc đang họp."],["田中さんは仕事をしていらっしゃいます。","Anh Tanaka đang làm việc."],["先生は勉強をしていらっしゃいます。","Thầy giáo đang học."],["山田さんは旅行をしていらっしゃいます。","Anh Yamada đang đi du lịch."]]},{"word":"水泳","reading":"すいえい","meaning":"Bơi lội","hanViet":"THỦY VỊNH","lesson":36,"ex":[["水泳が好きです。","Tôi thích bơi lội."],["水泳を習います。","Tôi học bơi."],["夏に水泳をします。","Mùa hè tôi bơi."],["水泳は体にいいです。","Bơi lội tốt cho cơ thể."],["毎週、水泳をします。","Mỗi tuần tôi bơi."]]},{"word":"～とか、～とか","reading":"～とか、～とか","meaning":"như là...và～và","hanViet":"","lesson":36,"ex":[["りんごとか、みかんとか、買いました。","Tôi đã mua táo, quýt và các thứ."],["本とか、雑誌とか、読みます。","Tôi đọc sách, tạp chí và các thứ."],["映画とか、音楽とか、好きです。","Tôi thích phim, nhạc và các thứ."],["テニスとか、水泳とか、します。","Tôi chơi tennis, bơi lội và các thứ."],["コーヒーとか、紅茶とか、飲みます。","Tôi uống cà phê, trà và các thứ."]]},{"word":"気持ち","reading":"きもち","meaning":"Cảm xúc, tâm trạng","hanViet":"KHÍ TRÌ","lesson":36,"ex":[["気持ちがいいです。","Cảm thấy dễ chịu."],["気持ちが悪いです。","Cảm thấy khó chịu."],["気持ちがわかります。","Tôi hiểu cảm xúc đó."],["気持ちを伝えます。","Tôi truyền đạt cảm xúc."],["いい気持ちです。","Cảm giác tốt."]]},{"word":"乗り物","reading":"のりもの","meaning":"Phương tiện đi lại","hanViet":"THỪA VẬT","lesson":36,"ex":[["乗り物が好きです。","Tôi thích phương tiện đi lại."],["乗り物の中で、電車が好きです。","Trong các phương tiện, tôi thích tàu điện."],["乗り物に乗ります。","Tôi đi phương tiện."],["電車は便利な乗り物です。","Tàu điện là phương tiện tiện lợi."],["乗り物で旅行します。","Tôi đi du lịch bằng phương tiện."]]},{"word":"～世紀","reading":"～せいき","meaning":"thế kỉ-","hanViet":"THẾ KỈ","lesson":36,"ex":[["20世紀に生まれました。","Tôi sinh ra vào thế kỷ 20."],["21世紀になりました。","Đã sang thế kỷ 21."],["19世紀の本です。","Đây là sách của thế kỷ 19."],["20世紀は大変でした。","Thế kỷ 20 vất vả."],["21世紀の日本は変わります。","Nhật Bản thế kỷ 21 thay đổi."]]},{"word":"遠く","reading":"とおく","meaning":"Nơi xa, ở xa","hanViet":"VIỄN","lesson":36,"ex":[["学校は家から遠くにあります。","Trường học ở xa nhà tôi."],["遠くに山が見えます。","Từ xa nhìn thấy núi."],["遠くの友達に手紙を書きました。","Tôi đã viết thư cho người bạn ở xa."],["弟は遠くへ旅行に行きました。","Em trai tôi đã đi du lịch nơi xa."],["遠くから来た友達に会いました。","Tôi đã gặp người bạn từ xa đến."]]},{"word":"汽車","reading":"きしゃ","meaning":"tàu hỏa, xe lửa","hanViet":"KHÍ XA","lesson":36,"ex":[["昔、汽車で東京へ行きました。","Ngày xưa, tôi đã đi Tokyo bằng tàu hỏa."],["汽車はゆっくり走ります。","Tàu hỏa chạy chậm."],["子どものとき、汽車に乗りました。","Khi còn nhỏ, tôi đã đi tàu hỏa."],["汽車の窓から山が見えました。","Từ cửa sổ tàu hỏa nhìn thấy núi."],["あの汽車は古いです。","Chiếc tàu hỏa kia cũ rồi."]]},{"word":"汽船","reading":"きせん","meaning":"tàu thủy chạy hơi nước","hanViet":"KHÍ THUYỀN","lesson":36,"ex":[["昔、汽船で外国へ行きました。","Ngày xưa, người ta đi nước ngoài bằng tàu thủy hơi nước."],["汽船は船です。","Tàu thủy hơi nước là một loại thuyền."],["汽船に乗って、島へ行きました。","Tôi đã đi tàu thủy hơi nước đến đảo."],["汽船はゆっくり走ります。","Tàu thủy hơi nước chạy chậm."],["博物館に古い汽船があります。","Trong bảo tàng có một chiếc tàu thủy hơi nước cổ."]]},{"word":"大勢の～","reading":"おおぜいの～","meaning":"nhiều (người)","hanViet":"ĐẠI THẾ","lesson":36,"ex":[["大勢の人が駅にいます。","Có nhiều người ở nhà ga."],["大勢の学生が図書館で勉強します。","Nhiều sinh viên học ở thư viện."],["きのう、大勢の友達がうちに来ました。","Hôm qua, nhiều bạn đã đến nhà tôi."],["公園に大勢の子どもがいます。","Trong công viên có nhiều trẻ em."],["大勢の人が電車を待っています。","Nhiều người đang đợi tàu điện."]]},{"word":"運びます","reading":"はこびます","meaning":"Vận chuyển, mang vác","hanViet":"VẬN","lesson":36,"ex":[["たくさんの本を運びました。","Tôi đã mang nhiều sách."],["父は会社で荷物を運びます。","Bố tôi vận chuyển hàng hóa ở công ty."],["車で野菜を運びます。","Vận chuyển rau bằng ô tô."],["新しい家へ机とベッドを運びました。","Tôi đã mang bàn và giường đến nhà mới."],["船で車を外国へ運びます。","Vận chuyển ô tô ra nước ngoài bằng tàu."]]},{"word":"安全な","reading":"あんぜんな","meaning":"An toàn","hanViet":"AN TOÀN","lesson":36,"ex":[["この道は安全です。","Con đường này an toàn."],["日本は安全な国です。","Nhật Bản là đất nước an toàn."],["子どもは安全な場所で遊びます。","Trẻ em chơi ở nơi an toàn."],["電車は安全な乗り物です。","Tàu điện là phương tiện an toàn."],["安全な水を飲みます。","Tôi uống nước an toàn."]]},{"word":"規則正しい生活をする","reading":"きそくただしいせいかつをする","meaning":"sinh hoạt đúng giờ giấc","hanViet":"QUY TẮC CHÍNH SINH HOẠT","lesson":36,"ex":[["私は規則正しい生活をします。","Tôi sinh hoạt đúng giờ giấc."],["健康のために、規則正しい生活をします。","Vì sức khỏe, tôi sinh hoạt đúng giờ giấc."],["母は規則正しい生活をしています。","Mẹ tôi đang sinh hoạt đúng giờ giấc."],["規則正しい生活をすると、元気になります。","Sinh hoạt đúng giờ giấc thì sẽ khỏe mạnh."],["子どものときから規則正しい生活をしています。","Tôi sinh hoạt đúng giờ giấc từ khi còn nhỏ."]]},{"word":"早寝、早起きをする","reading":"はやね、はやおきをする","meaning":"ngủ sớm, dậy sớm","hanViet":"TẢO TẨM TẢO KHỞI","lesson":36,"ex":[["私は早寝、早起きをします。","Tôi ngủ sớm, dậy sớm."],["健康のために、早寝、早起きをします。","Vì sức khỏe, tôi ngủ sớm, dậy sớm."],["母は毎日、早寝、早起きをしています。","Mẹ tôi ngày nào cũng ngủ sớm, dậy sớm."],["早寝、早起きをすると、朝、元気です。","Ngủ sớm dậy sớm thì buổi sáng sẽ khỏe khoắn."],["子どもは早寝、早起きをしたほうがいいです。","Trẻ em nên ngủ sớm, dậy sớm."]]},{"word":"運動する","reading":"うんどうする","meaning":"vận động/ chơi thể thao","hanViet":"VẬN ĐỘNG","lesson":36,"ex":[["私は毎朝、運動します。","Mỗi sáng tôi vận động."],["公園で運動します。","Tôi vận động ở công viên."],["健康のために、よく運動します。","Vì sức khỏe, tôi thường xuyên vận động."],["友達といっしょに運動します。","Tôi vận động cùng bạn bè."],["雨の日はうちで運動します。","Ngày mưa tôi vận động ở nhà."]]},{"word":"よく歩く","reading":"よくあるく","meaning":"đi bộ nhiều","hanViet":"BỘ","lesson":36,"ex":[["私はよく歩きます。","Tôi đi bộ nhiều."],["健康のために、よく歩きます。","Vì sức khỏe, tôi đi bộ nhiều."],["母は毎日、よく歩きます。","Mẹ tôi ngày nào cũng đi bộ nhiều."],["犬とよく歩きます。","Tôi thường đi bộ với chó."],["駅までよく歩きます。","Tôi thường đi bộ đến nhà ga."]]},{"word":"好き嫌いがない","reading":"すききらいがない","meaning":"không có gì không thích cả","hanViet":"HẢO HIỀM","lesson":36,"ex":[["私は好き嫌いがありません。","Tôi không kén ăn."],["弟は好き嫌いがありません。","Em trai tôi không kén ăn."],["好き嫌いがない人は健康です。","Người không kén ăn thì khỏe mạnh."],["好き嫌いがないので、何でも食べます。","Vì không kén ăn nên tôi ăn gì cũng được."],["子どもは好き嫌いがありません。","Đứa trẻ không kén ăn."]]},{"word":"栄養のバランスを考えて食べる","reading":"えいようのバランスをかんがえてたべる","meaning":"ăn đảm bảo cân bằng dinh dưỡng","hanViet":"VINH DƯỠNG KHẢO THỰC","lesson":36,"ex":[["私は栄養のバランスを考えて食べます。","Tôi ăn uống cân bằng dinh dưỡng."],["母は毎日、栄養のバランスを考えて食べます。","Mẹ tôi ngày nào cũng ăn uống cân bằng dinh dưỡng."],["健康のために、栄養のバランスを考えて食べます。","Vì sức khỏe, tôi ăn uống cân bằng dinh dưỡng."],["毎日、栄養のバランスを考えて食べます。","Mỗi ngày tôi ăn uống cân bằng dinh dưỡng."],["栄養のバランスを考えて食べると、元気になります。","Ăn uống cân bằng dinh dưỡng thì sẽ khỏe mạnh."]]},{"word":"健康診断を受ける","reading":"けんこうしんだんをうける","meaning":"khám sức khỏe","hanViet":"KIỆN KHANG CHẨN ĐOẠN THỤ","lesson":36,"ex":[["私は毎年、健康診断を受けます。","Mỗi năm tôi khám sức khỏe một lần."],["会社で健康診断を受けます。","Tôi khám sức khỏe ở công ty."],["きのう、病院で健康診断を受けました。","Hôm qua tôi đã khám sức khỏe ở bệnh viện."],["健康診断を受けて、元気だと言われました。","Tôi khám sức khỏe và được nói là khỏe mạnh."],["父は健康診断を受けました。","Bố tôi đã khám sức khỏe."]]},{"word":"夜更かしをする","reading":"よふかしをする","meaning":"thức khuya","hanViet":"DẠ CANH","lesson":36,"ex":[["私はよく夜更かしをします。","Tôi hay thức khuya."],["夜更かしをすると、朝、起きられません。","Thức khuya thì buổi sáng không dậy nổi."],["試験の前に夜更かしをしました。","Trước kỳ thi tôi đã thức khuya."],["子どもは夜更かしをしないほうがいいです。","Trẻ em không nên thức khuya."],["テレビを見て、夜更かしをしました。","Tôi đã thức khuya xem ti vi."]]},{"word":"あまり運動しない","reading":"あまりうんどうしない","meaning":"ít vận động","hanViet":"VẬN ĐỘNG","lesson":36,"ex":[["私はあまり運動しません。","Tôi ít vận động."],["冬はあまり運動しません。","Mùa đông tôi ít vận động."],["忙しいので、あまり運動しません。","Vì bận nên tôi ít vận động."],["あまり運動しない人は太ります。","Người ít vận động sẽ béo lên."],["父はあまり運動しません。","Bố tôi ít vận động."]]},{"word":"好き嫌いがある","reading":"すききらいがある","meaning":"có nhiều thứ không thích","hanViet":"HẢO HIỀM","lesson":36,"ex":[["私は好き嫌いがあります。","Tôi kén ăn."],["弟は好き嫌いがあります。","Em trai tôi kén ăn."],["好き嫌いがあるので、野菜を食べません。","Vì kén ăn nên tôi không ăn rau."],["子どもは好き嫌いがあります。","Trẻ em kén ăn."],["好き嫌いがあると、体によくありません。","Kén ăn thì không tốt cho cơ thể."]]},{"word":"よくインスタント食品を食べる","reading":"よくインスタントしょくひんをたべる","meaning":"hay ăn đồ ăn liền","hanViet":"THỰC PHẨM THỰC","lesson":36,"ex":[["私はよくインスタント食品を食べます。","Tôi hay ăn đồ ăn liền."],["忙しいとき、よくインスタント食品を食べます。","Khi bận, tôi hay ăn đồ ăn liền."],["よくインスタント食品を食べると、体によくありません。","Hay ăn đồ ăn liền thì không tốt cho cơ thể."],["学生はよくインスタント食品を食べます。","Sinh viên hay ăn đồ ăn liền."],["夜、よくインスタント食品を食べます。","Buổi tối tôi hay ăn đồ ăn liền."]]},{"word":"外食が多い","reading":"がいしょくがおおい","meaning":"thường ăn tiệm","hanViet":"NGOẠI THỰC ĐA","lesson":36,"ex":[["私は外食が多いです。","Tôi thường ăn tiệm."],["忙しいので、外食が多いです。","Vì bận nên tôi thường ăn tiệm."],["会社員は外食が多いです。","Nhân viên công ty thường ăn tiệm."],["外食が多いと、お金がかかります。","Ăn tiệm nhiều thì tốn tiền."],["弟は外食が多いです。","Em trai tôi thường ăn tiệm."]]},{"word":"たばこを吸う","reading":"たばこをすう","meaning":"hút thuốc","hanViet":"HẤP","lesson":36,"ex":[["父はたばこを吸います。","Bố tôi hút thuốc."],["ここでたばこを吸ってはいけません。","Không được hút thuốc ở đây."],["私はたばこを吸いません。","Tôi không hút thuốc."],["たばこを吸うと、体によくありません。","Hút thuốc không tốt cho cơ thể."],["田中さんはたばこを吸います。","Anh Tanaka hút thuốc."]]},{"word":"よくお酒を飲む","reading":"よくおさけをのむ","meaning":"hay uống rượu","hanViet":"TỬU ẨM","lesson":36,"ex":[["父はよくお酒を飲みます。","Bố tôi hay uống rượu."],["田中さんはよくお酒を飲みます。","Anh Tanaka hay uống rượu."],["よくお酒を飲むと、体によくありません。","Hay uống rượu thì không tốt cho cơ thể."],["私はよくお酒を飲みません。","Tôi không hay uống rượu."],["週末、友達とよくお酒を飲みます。","Cuối tuần tôi hay uống rượu với bạn bè."]]},{"word":"炭水化物","reading":"たんすいかぶつ","meaning":"Chất bột","hanViet":"THÁN THỦY HÓA VẬT","lesson":36,"ex":[["ごはんには炭水化物が多いです。","Cơm có nhiều chất bột."],["パンには炭水化物が多いです。","Bánh mì có nhiều chất bột."],["炭水化物は体の力になります。","Chất bột trở thành năng lượng cho cơ thể."],["いもには炭水化物が多いです。","Khoai có nhiều chất bột."],["炭水化物を食べすぎると、太ります。","Ăn quá nhiều chất bột sẽ béo lên."]]},{"word":"いも","reading":"いも","meaning":"khoai","hanViet":"","lesson":36,"ex":[["いもはおいしいです。","Khoai ngon."],["いもを食べます。","Tôi ăn khoai."],["母はいもを買いました。","Mẹ tôi đã mua khoai."],["いもは安いです。","Khoai rẻ."],["スーパーでいもを買いました。","Tôi đã mua khoai ở siêu thị."]]},{"word":"脂肪","reading":"しぼう","meaning":"Chất béo, mỡ (trong cơ thể)","hanViet":"CHI PHÒNG","lesson":36,"ex":[["肉には脂肪が多いです。","Thịt có nhiều chất béo."],["脂肪を食べすぎると、太ります。","Ăn quá nhiều chất béo sẽ béo lên."],["体に脂肪が多いです。","Cơ thể tôi có nhiều mỡ."],["脂肪が少ない食べ物がいいです。","Đồ ăn ít chất béo thì tốt."],["運動すると、脂肪が減ります。","Vận động thì mỡ sẽ giảm."]]},{"word":"海草","reading":"かいそう","meaning":"rong tảo biển","hanViet":"HẢI THẢO","lesson":36,"ex":[["海草は海にあります。","Rong biển ở dưới biển."],["海草を食べます。","Tôi ăn rong biển."],["海草は体にいいです。","Rong biển tốt cho cơ thể."],["母は海草で料理を作ります。","Mẹ tôi nấu ăn bằng rong biển."],["スーパーで海草を買いました。","Tôi đã mua rong biển ở siêu thị."]]},{"word":"たんぱく質","reading":"たんぱくしつ","meaning":"Chất đạm","hanViet":"CHẤT","lesson":36,"ex":[["肉にはたんぱく質が多いです。","Thịt có nhiều chất đạm."],["魚にはたんぱく質が多いです。","Cá có nhiều chất đạm."],["卵にはたんぱく質が多いです。","Trứng có nhiều chất đạm."],["たんぱく質は体に必要です。","Chất đạm cần thiết cho cơ thể."],["豆にはたんぱく質が多いです。","Đậu có nhiều chất đạm."]]},{"word":"豆","reading":"まめ","meaning":"hạt đậu","hanViet":"ĐẬU","lesson":36,"ex":[["豆は体にいいです。","Đậu tốt cho cơ thể."],["豆を食べます。","Tôi ăn đậu."],["豆は安いです。","Đậu rẻ."],["母は豆で料理を作ります。","Mẹ tôi nấu ăn bằng đậu."],["スーパーで豆を買いました。","Tôi đã mua đậu ở siêu thị."]]},{"word":"タンゴ","reading":"タンゴ","meaning":"tango","hanViet":"","lesson":36,"ex":[["タンゴはダンスです。","Tango là một điệu nhảy."],["タンゴを踊ります。","Tôi nhảy tango."],["母はタンゴが好きです。","Mẹ tôi thích tango."],["タンゴの音楽を聞きます。","Tôi nghe nhạc tango."],["タンゴを踊るのは難しいです。","Nhảy tango rất khó."]]},{"word":"チャレンジします","reading":"チャレンジします","meaning":"thách thức, thử thách","hanViet":"","lesson":36,"ex":[["新しいスポーツにチャレンジします。","Tôi thử thách với môn thể thao mới."],["日本語の試験にチャレンジしました。","Tôi đã thử sức với kỳ thi tiếng Nhật."],["難しい仕事にチャレンジします。","Tôi thử thách với công việc khó."],["来年、マラソンにチャレンジします。","Năm sau tôi sẽ thử thách chạy marathon."],["英語の試験にチャレンジします。","Tôi thử sức với kỳ thi tiếng Anh."]]},{"word":"歴史","reading":"れきし","meaning":"lịch sử","hanViet":"LỊCH SỬ","lesson":36,"ex":[["日本の歴史を勉強します。","Tôi học lịch sử Nhật Bản."],["歴史の本を読みます。","Tôi đọc sách lịch sử."],["歴史が好きです。","Tôi thích lịch sử."],["先生は歴史を教えます。","Thầy giáo dạy lịch sử."],["博物館で歴史を勉強しました。","Tôi đã học lịch sử ở bảo tàng."]]},{"word":"褒めます","reading":"ほめます","meaning":"khen","hanViet":"BAO","lesson":37,"ex":[["先生は私を褒めました。","Thầy giáo đã khen tôi."],["母は子どもを褒めます。","Mẹ khen con."],["仕事がいいので、社長に褒められました。","Vì làm việc tốt nên tôi được giám đốc khen."],["先生に褒められて、うれしいです。","Được thầy khen nên tôi vui."],["母は弟を褒めました。","Mẹ đã khen em trai."]]},{"word":"しかります","reading":"しかります","meaning":"mắng","hanViet":"","lesson":37,"ex":[["母は私をしかりました。","Mẹ đã mắng tôi."],["先生は学生をしかりました。","Thầy giáo đã mắng học sinh."],["遅刻したので、先生にしかられました。","Vì đến muộn nên tôi bị thầy mắng."],["父は弟をしかりました。","Bố đã mắng em trai."],["母にしかられて、泣きました。","Bị mẹ mắng nên tôi đã khóc."]]},{"word":"誘います","reading":"さそいます","meaning":"mời, rủ rê","hanViet":"DỤ","lesson":37,"ex":[["友達を映画に誘いました。","Tôi đã rủ bạn đi xem phim."],["友達に旅行に誘われました。","Tôi được bạn rủ đi du lịch."],["山田さんを晩ごはんに誘います。","Tôi mời anh Yamada ăn tối."],["友達をパーティーに誘いました。","Tôi đã mời bạn đến bữa tiệc."],["週末、友達を公園に誘いました。","Cuối tuần tôi đã rủ bạn ra công viên."]]},{"word":"起こします","reading":"おこします","meaning":"Đánh thức; gây ra","hanViet":"KHỞI","lesson":37,"ex":[["母は朝、7時に私を起こします。","Mẹ đánh thức tôi lúc 7 giờ sáng."],["目覚まし時計が私を起こしました。","Đồng hồ báo thức đã đánh thức tôi."],["弟を起こしてください。","Hãy đánh thức em trai dậy."],["車が事故を起こしました。","Xe ô tô đã gây ra tai nạn."],["地震が私を起こしました。","Động đất đã đánh thức tôi."]]},{"word":"招待します","reading":"しょうたいします","meaning":"mời","hanViet":"CHIÊU ĐÃI","lesson":37,"ex":[["友達をうちに招待しました。","Tôi đã mời bạn đến nhà."],["結婚式に招待されました。","Tôi được mời đến đám cưới."],["田中さんをパーティーに招待します。","Tôi mời anh Tanaka đến bữa tiệc."],["先生を晩ごはんに招待しました。","Tôi đã mời thầy giáo ăn tối."],["友達に誕生日のパーティーに招待されました。","Tôi được bạn mời đến tiệc sinh nhật."]]},{"word":"頼みます","reading":"たのみます","meaning":"nhờ, yêu cầu","hanViet":"LẠI","lesson":37,"ex":[["友達に仕事を頼みました。","Tôi đã nhờ bạn làm việc giúp."],["母に料理を頼みました。","Tôi đã nhờ mẹ nấu ăn."],["田中さんに電話をかけるのを頼みました。","Tôi đã nhờ anh Tanaka gọi điện thoại."],["弟に本を買うのを頼みました。","Tôi đã nhờ em trai mua sách."],["友達に仕事を頼まれました。","Tôi được bạn nhờ làm việc."]]},{"word":"とります","reading":"とります","meaning":"ăn trộm , lấy cắp","hanViet":"","lesson":37,"ex":[["泥棒がお金をとりました。","Kẻ trộm đã lấy cắp tiền."],["かばんをとられました。","Tôi bị lấy cắp túi xách."],["泥棒が車をとりました。","Kẻ trộm đã lấy cắp ô tô."],["自転車をとられました。","Tôi bị lấy cắp xe đạp."],["子どもがお菓子をとりました。","Đứa trẻ đã lấy trộm kẹo."]]},{"word":"踏みます","reading":"ふみます","meaning":"giẫm, đạp lên","hanViet":"ĐẠP","lesson":37,"ex":[["花を踏みました。","Tôi đã giẫm lên hoa."],["犬の足を踏みました。","Tôi đã giẫm lên chân chó."],["足を踏まれました。","Tôi bị giẫm lên chân."],["雪を踏みます。","Tôi giẫm lên tuyết."],["母の靴を踏みました。","Tôi đã giẫm lên giày của mẹ."]]},{"word":"壊します","reading":"こわします","meaning":"làm hỏng, phá vỡ","hanViet":"HOẠI","lesson":37,"ex":[["パソコンを壊しました。","Tôi đã làm hỏng máy tính."],["子どもがおもちゃを壊しました。","Đứa trẻ đã làm hỏng đồ chơi."],["時計を壊しました。","Tôi đã làm hỏng đồng hồ."],["カメラを壊しました。","Tôi đã làm hỏng máy ảnh."],["自転車を壊しました。","Tôi đã làm hỏng xe đạp."]]},{"word":"汚します","reading":"よごします","meaning":"Làm bẩn, làm dơ","hanViet":"Ô","lesson":37,"ex":[["服を汚しました。","Tôi đã làm bẩn quần áo."],["手を汚しました。","Tôi đã làm bẩn tay."],["シャツを汚しました。","Tôi đã làm bẩn áo sơ mi."],["子どもが部屋を汚しました。","Đứa trẻ đã làm bẩn phòng."],["靴を汚しました。","Tôi đã làm bẩn giày."]]},{"word":"行います","reading":"おこないます","meaning":"thực hiện, tiến hành","hanViet":"HÀNH","lesson":37,"ex":[["会議を行います。","Tôi tiến hành cuộc họp."],["学校で試験を行います。","Trường tiến hành kỳ thi."],["調査を行います。","Tôi tiến hành điều tra."],["会社で会議を行いました。","Công ty đã tiến hành cuộc họp."],["結婚式を行います。","Tôi tổ chức đám cưới."]]},{"word":"輸出します","reading":"ゆしゅつします","meaning":"xuất khẩu","hanViet":"THÂU XUẤT","lesson":37,"ex":[["日本は車を輸出します。","Nhật Bản xuất khẩu ô tô."],["日本はアメリカへ車を輸出します。","Nhật Bản xuất khẩu ô tô sang Mỹ."],["この会社はコンピューターを輸出します。","Công ty này xuất khẩu máy tính."],["日本はカメラを外国へ輸出します。","Nhật Bản xuất khẩu máy ảnh ra nước ngoài."],["米を輸出します。","Tôi xuất khẩu gạo."]]},{"word":"輸入します","reading":"ゆにゅうします","meaning":"nhập khẩu","hanViet":"THÂU NHẬP","lesson":37,"ex":[["日本は石油を輸入します。","Nhật Bản nhập khẩu dầu mỏ."],["日本は中国から米を輸入します。","Nhật Bản nhập khẩu gạo từ Trung Quốc."],["この会社はコーヒーを輸入します。","Công ty này nhập khẩu cà phê."],["日本は外国から肉を輸入します。","Nhật Bản nhập khẩu thịt từ nước ngoài."],["石油を輸入します。","Tôi nhập khẩu dầu mỏ."]]},{"word":"翻訳します","reading":"ほんやくします","meaning":"dịch (sách, tài liệu)","hanViet":"PHIÊN DỊCH","lesson":37,"ex":[["本を翻訳します。","Tôi dịch sách."],["日本語を英語に翻訳します。","Tôi dịch tiếng Nhật sang tiếng Anh."],["小説を翻訳しました。","Tôi đã dịch tiểu thuyết."],["田中さんは本を翻訳します。","Anh Tanaka dịch sách."],["ベトナム語を日本語に翻訳します。","Tôi dịch tiếng Việt sang tiếng Nhật."]]},{"word":"発明します","reading":"はつめいします","meaning":"phát minh","hanViet":"PHÁT MINH","lesson":37,"ex":[["電話を発明しました。","Người ta đã phát minh ra điện thoại."],["科学者が新しいものを発明しました。","Nhà khoa học đã phát minh ra thứ mới."],["飛行機を発明しました。","Người ta đã phát minh ra máy bay."],["コンピューターを発明しました。","Người ta đã phát minh ra máy tính."],["車を発明しました。","Người ta đã phát minh ra ô tô."]]},{"word":"発見します","reading":"はっけんします","meaning":"phát kiến, tìm ra","hanViet":"PHÁT KIẾN","lesson":37,"ex":[["新しい星を発見しました。","Người ta đã phát hiện ra ngôi sao mới."],["島を発見しました。","Người ta đã phát hiện ra hòn đảo."],["間違いを発見しました。","Tôi đã phát hiện ra lỗi sai."],["科学者が新しい病気を発見しました。","Nhà khoa học đã phát hiện ra căn bệnh mới."],["古い本を発見しました。","Tôi đã tìm thấy cuốn sách cổ."]]},{"word":"設計します","reading":"せっけいします","meaning":"thiết kế","hanViet":"THIẾT KẾ","lesson":37,"ex":[["家を設計します。","Tôi thiết kế nhà."],["建築家が家を設計しました。","Kiến trúc sư đã thiết kế ngôi nhà."],["橋を設計します。","Tôi thiết kế cầu."],["建物を設計します。","Tôi thiết kế tòa nhà."],["車を設計します。","Tôi thiết kế ô tô."]]},{"word":"米","reading":"こめ","meaning":"Gạo","hanViet":"MỄ","lesson":37,"ex":[["米は日本の食べ物です。","Gạo là thực phẩm của Nhật Bản."],["米でごはんを作ります。","Tôi nấu cơm bằng gạo."],["米を買いました。","Tôi đã mua gạo."],["日本は米を作ります。","Nhật Bản trồng lúa gạo."],["米は白いです。","Gạo màu trắng."]]},{"word":"麦","reading":"むぎ","meaning":"lúa mạch","hanViet":"MẠCH","lesson":37,"ex":[["麦でパンを作ります。","Tôi làm bánh mì bằng lúa mạch."],["麦は食べ物です。","Lúa mạch là thực phẩm."],["麦からビールを作ります。","Người ta làm bia từ lúa mạch."],["麦を食べます。","Tôi ăn lúa mạch."],["麦は体にいいです。","Lúa mạch tốt cho cơ thể."]]},{"word":"石油","reading":"せきゆ","meaning":"Dầu mỏ","hanViet":"THẠCH DU","lesson":37,"ex":[["石油は車に必要です。","Dầu mỏ cần thiết cho ô tô."],["日本は石油を外国から輸入します。","Nhật Bản nhập khẩu dầu mỏ từ nước ngoài."],["石油からガソリンを作ります。","Người ta làm xăng từ dầu mỏ."],["石油は大切です。","Dầu mỏ rất quan trọng."],["石油の値段が高いです。","Giá dầu mỏ cao."]]},{"word":"原料","reading":"げんりょう","meaning":"Nguyên liệu","hanViet":"NGUYÊN LIỆU","lesson":37,"ex":[["パンの原料は麦です。","Nguyên liệu của bánh mì là lúa mạch."],["ケーキの原料は卵と砂糖です。","Nguyên liệu của bánh ngọt là trứng và đường."],["ビールの原料は麦です。","Nguyên liệu của bia là lúa mạch."],["紙の原料は木です。","Nguyên liệu của giấy là gỗ."],["料理の原料を買います。","Tôi mua nguyên liệu nấu ăn."]]},{"word":"泥棒","reading":"どろぼう","meaning":"Kẻ trộm, kẻ cắp","hanViet":"NÊ BỔNG","lesson":37,"ex":[["泥棒がうちに入りました。","Kẻ trộm đã vào nhà tôi."],["泥棒が店のお金をとりました。","Kẻ trộm đã lấy cắp tiền của cửa hàng."],["泥棒は警察に見つかりました。","Kẻ trộm đã bị cảnh sát tìm thấy."],["夜、泥棒が来ました。","Ban đêm kẻ trộm đã đến."],["泥棒は怖いです。","Kẻ trộm đáng sợ."]]},{"word":"警官","reading":"けいかん","meaning":"cảnh sát","hanViet":"CẢNH QUAN","lesson":37,"ex":[["警官が道にいます。","Cảnh sát ở trên đường."],["警官に道を聞きました。","Tôi đã hỏi đường cảnh sát."],["警官が泥棒を見つけました。","Cảnh sát đã tìm thấy kẻ trộm."],["警官は事故のことを調べます。","Cảnh sát điều tra về vụ tai nạn."],["警官が車を止めました。","Cảnh sát đã dừng xe lại."]]},{"word":"建築家","reading":"けんちくか","meaning":"kiến trúc sư","hanViet":"KIẾN TRÚC GIA","lesson":37,"ex":[["建築家は家を設計します。","Kiến trúc sư thiết kế nhà."],["父は建築家です。","Bố tôi là kiến trúc sư."],["有名な建築家がこの建物を設計しました。","Kiến trúc sư nổi tiếng đã thiết kế tòa nhà này."],["建築家になりたいです。","Tôi muốn trở thành kiến trúc sư."],["建築家の仕事は大変です。","Công việc của kiến trúc sư rất vất vả."]]},{"word":"科学者","reading":"かがくしゃ","meaning":"nhà khoa học","hanViet":"KHOA HỌC GIẢ","lesson":37,"ex":[["科学者は新しいものを発見します。","Nhà khoa học phát hiện ra thứ mới."],["父は科学者です。","Bố tôi là nhà khoa học."],["有名な科学者が電話を発明しました。","Nhà khoa học nổi tiếng đã phát minh ra điện thoại."],["科学者になりたいです。","Tôi muốn trở thành nhà khoa học."],["科学者は大学で働きます。","Nhà khoa học làm việc ở trường đại học."]]},{"word":"～中","reading":"～じゅう","meaning":"khắp ~, toàn ~","hanViet":"TRUNG","lesson":37,"ex":[["世界中に友達がいます。","Tôi có bạn bè khắp thế giới."],["日本中に桜があります。","Khắp Nhật Bản đều có hoa anh đào."],["町中に店があります。","Khắp thị trấn đều có cửa hàng."],["学校中に学生がいます。","Khắp trường đều có học sinh."],["世界中の人が日本へ来ます。","Người khắp thế giới đến Nhật Bản."]]},{"word":"～によって","reading":"～によって","meaning":"do ~; tùy theo ~","hanViet":"","lesson":37,"ex":[["雨によって、試合が中止になりました。","Do mưa nên trận đấu bị hủy."],["人によって、好きな食べ物が違います。","Tùy người mà món ăn yêu thích khác nhau."],["国によって、料理が違います。","Tùy nước mà món ăn khác nhau."],["事故によって、電車が止まりました。","Do tai nạn nên tàu điện đã dừng."],["地震によって、建物が壊れました。","Do động đất nên tòa nhà bị hỏng."]]},{"word":"よかったですね。","reading":"よかったですね","meaning":"may nhỉ","hanViet":"","lesson":37,"ex":[["「試験に合格しました。」「よかったですね。」","Tôi đã đỗ kỳ thi. May quá nhỉ."],["「電車が来ました。」「よかったですね。」","Tàu điện đã đến. May quá nhỉ."],["「病気が治りました。」「よかったですね。」","Bệnh đã khỏi. May quá nhỉ."],["「かばんが見つかりました。」「よかったですね。」","Đã tìm thấy túi xách. May quá nhỉ."],["「天気がよくなりました。」「よかったですね。」","Thời tiết đã tốt lên. May quá nhỉ."]]},{"word":"埋め立てます","reading":"うめたてます","meaning":"lấp","hanViet":"MAI LẬP","lesson":37,"ex":[["海を埋め立てます。","Người ta lấp biển."],["海を埋め立てて、土地を作ります。","Người ta lấp biển để tạo đất."],["海を埋め立てて、空港を作りました。","Người ta đã lấp biển để xây sân bay."],["土地が少ないので、海を埋め立てます。","Vì ít đất nên người ta lấp biển."],["昔、海を埋め立てました。","Ngày xưa người ta đã lấp biển."]]},{"word":"技術","reading":"ぎじゅつ","meaning":"Kỹ thuật","hanViet":"KỸ THUẬT","lesson":37,"ex":[["日本の技術は高いです。","Kỹ thuật của Nhật Bản cao."],["新しい技術を勉強します。","Tôi học kỹ thuật mới."],["コンピューターの技術が進みました。","Kỹ thuật máy tính đã tiến bộ."],["技術は大切です。","Kỹ thuật rất quan trọng."],["会社で技術を習います。","Tôi học kỹ thuật ở công ty."]]},{"word":"土地","reading":"とち","meaning":"Đất đai, vùng đất","hanViet":"THỔ ĐỊA","lesson":37,"ex":[["土地を買います。","Tôi mua đất."],["広い土地があります。","Có vùng đất rộng."],["この土地は高いです。","Mảnh đất này đắt."],["土地に家を建てます。","Tôi xây nhà trên đất."],["日本の土地は狭いです。","Đất đai Nhật Bản chật hẹp."]]},{"word":"騒音","reading":"そうおん","meaning":"tiếng ồn","hanViet":"TAO ÂM","lesson":37,"ex":[["車の騒音がうるさいです。","Tiếng ồn xe cộ ồn ào."],["夜、騒音が聞こえます。","Ban đêm nghe thấy tiếng ồn."],["工場の騒音が大きいです。","Tiếng ồn nhà máy lớn."],["騒音で眠れません。","Vì tiếng ồn nên tôi không ngủ được."],["飛行機の騒音がうるさいです。","Tiếng ồn máy bay ồn ào."]]},{"word":"豪華な","reading":"ごうかな","meaning":"xa hoa, lộng lẫy","hanViet":"HÀO HOA","lesson":37,"ex":[["豪華なホテルに泊まりました。","Tôi đã ở khách sạn sang trọng."],["豪華な家があります。","Có ngôi nhà lộng lẫy."],["豪華な料理を食べました。","Tôi đã ăn món ăn sang trọng."],["豪華な結婚式を行いました。","Tôi đã tổ chức đám cưới xa hoa."],["豪華なパーティーに行きました。","Tôi đã đến bữa tiệc xa hoa."]]},{"word":"彫刻","reading":"ちょうこく","meaning":"điêu khắc, tượng khắc","hanViet":"ĐIÊU KHẮC","lesson":37,"ex":[["美術館に彫刻があります。","Trong bảo tàng mỹ thuật có tượng điêu khắc."],["木の彫刻を見ました。","Tôi đã xem tượng điêu khắc bằng gỗ."],["彫刻は美しいです。","Tượng điêu khắc đẹp."],["石の彫刻を作ります。","Tôi làm tượng điêu khắc bằng đá."],["有名な彫刻を見に行きました。","Tôi đã đi xem tượng điêu khắc nổi tiếng."]]},{"word":"眠ります","reading":"ねむります","meaning":"Ngủ","hanViet":"MIÊN","lesson":37,"ex":[["子どもは眠っています。","Đứa trẻ đang ngủ."],["赤ちゃんが眠りました。","Em bé đã ngủ."],["夜、早く眠ります。","Buổi tối tôi ngủ sớm."],["静かな部屋で眠ります。","Tôi ngủ trong phòng yên tĩnh."],["疲れて、すぐ眠りました。","Vì mệt nên tôi đã ngủ ngay."]]},{"word":"彫ります","reading":"ほります","meaning":"chạm, khắc (gỗ, đá)","hanViet":"ĐIÊU","lesson":37,"ex":[["木を彫ります。","Tôi khắc gỗ."],["石を彫ります。","Tôi khắc đá."],["名前を彫ります。","Tôi khắc tên."],["木に花を彫りました。","Tôi đã khắc hoa lên gỗ."],["田中さんが石を彫ります。","Anh Tanaka khắc đá."]]},{"word":"仲間","reading":"なかま","meaning":"Bạn bè, đồng đội, phe nhóm","hanViet":"TRỌNG GIAN","lesson":37,"ex":[["仲間と旅行に行きました。","Tôi đã đi du lịch với bạn bè."],["会社の仲間と昼ごはんを食べます。","Tôi ăn trưa với đồng nghiệp."],["仲間がたくさんいます。","Tôi có nhiều bạn bè."],["クラスに仲間がいます。","Trong lớp tôi có bạn bè."],["仲間とサッカーをします。","Tôi chơi bóng đá với bạn bè."]]},{"word":"そのあと","reading":"そのあと","meaning":"sau đó","hanViet":"","lesson":37,"ex":[["映画を見て、そのあと、ごはんを食べました。","Tôi xem phim, sau đó ăn cơm."],["仕事をして、そのあと、うちへ帰りました。","Tôi làm việc, sau đó về nhà."],["学校へ行って、そのあと、図書館へ行きました。","Tôi đến trường, sau đó đến thư viện."],["朝ごはんを食べて、そのあと、会社へ行きました。","Tôi ăn sáng, sau đó đến công ty."],["勉強して、そのあと、寝ました。","Tôi học bài, sau đó đi ngủ."]]},{"word":"一生懸命","reading":"いっしょうけんめい","meaning":"Hết sức mình, cố gắng hết sức","hanViet":"NHẤT SINH HUYỀN MỆNH","lesson":37,"ex":[["一生懸命、勉強します。","Tôi học hết sức mình."],["一生懸命、仕事をします。","Tôi làm việc hết sức mình."],["試験のために、一生懸命、勉強しました。","Vì kỳ thi, tôi đã học hết sức mình."],["一生懸命、日本語を勉強しています。","Tôi đang học tiếng Nhật hết sức mình."],["弟は一生懸命、走りました。","Em trai đã chạy hết sức mình."]]},{"word":"ねずみ","reading":"ねずみ","meaning":"chuột","hanViet":"","lesson":37,"ex":[["ねずみは小さいです。","Chuột nhỏ."],["家にねずみがいます。","Trong nhà có chuột."],["猫がねずみを見つけました。","Mèo đã tìm thấy chuột."],["ねずみが食べ物を食べました。","Chuột đã ăn đồ ăn."],["夜、ねずみが出ました。","Ban đêm chuột đã xuất hiện."]]},{"word":"殺します","reading":"ころします","meaning":"giết","hanViet":"SÁT","lesson":37,"ex":[["戦争でたくさんの人が殺されました。","Trong chiến tranh, nhiều người đã bị giết."],["犯人が人を殺しました。","Kẻ phạm tội đã giết người."],["猫がねずみを殺しました。","Mèo đã giết chuột."],["ニュースで人が殺されたと聞きました。","Tôi nghe tin có người bị giết trên bản tin."],["犯人が警官を殺しました。","Kẻ phạm tội đã giết cảnh sát."]]},{"word":"撃ちます","reading":"うちます","meaning":"bắn, nã đạn","hanViet":"KÍCH","lesson":37,"ex":[["警官が犯人を撃ちました。","Cảnh sát đã bắn kẻ phạm tội."],["戦争で人を撃ちました。","Trong chiến tranh, người ta đã bắn người."],["ニュースで人が撃たれたと聞きました。","Tôi nghe tin có người bị bắn trên bản tin."],["犯人に撃たれました。","Tôi bị kẻ phạm tội bắn."],["犯人が警官を撃ちました。","Kẻ phạm tội đã bắn cảnh sát."]]},{"word":"刺します","reading":"さします","meaning":"Đâm, chích","hanViet":"THÍCH","lesson":37,"ex":[["針で手を刺しました。","Tôi đã đâm kim vào tay."],["はちに刺されました。","Tôi bị ong chích."],["犯人がナイフで人を刺しました。","Kẻ phạm tội đã đâm người bằng dao."],["犯人に刺されました。","Tôi bị kẻ phạm tội đâm."],["子どもが針で手を刺しました。","Đứa trẻ đã đâm kim vào tay."]]},{"word":"はねます","reading":"はねます","meaning":"đâm phải, va chạm","hanViet":"","lesson":37,"ex":[["車が人をはねました。","Xe ô tô đã đâm phải người."],["車にはねられました。","Tôi bị xe đâm phải."],["車が犬をはねました。","Xe ô tô đã đâm phải chó."],["自転車が人をはねました。","Xe đạp đã đâm phải người."],["夜、車が猫をはねました。","Ban đêm, xe ô tô đã đâm phải mèo."]]},{"word":"衝突します","reading":"しょうとつします","meaning":"đâm nhau","hanViet":"XUNG ĐỘT","lesson":37,"ex":[["車と車が衝突しました。","Hai xe ô tô đã đâm nhau."],["車とバスが衝突しました。","Xe ô tô và xe buýt đã đâm nhau."],["電車が車と衝突しました。","Tàu điện đã đâm vào ô tô."],["船が船と衝突しました。","Hai con tàu đã đâm nhau."],["飛行機が山に衝突しました。","Máy bay đã đâm vào núi."]]},{"word":"追突します","reading":"ついとつします","meaning":"đâm phải đuôi, đâm từ phía sau","hanViet":"TRUY ĐỘT","lesson":37,"ex":[["車が前の車に追突しました。","Xe ô tô đã đâm vào đuôi xe phía trước."],["信号で車に追突されました。","Tôi bị xe đâm từ phía sau ở đèn giao thông."],["雨の日に車が追突しました。","Ngày mưa, xe ô tô đã đâm từ phía sau."],["バスが車に追突しました。","Xe buýt đã đâm vào đuôi ô tô."],["高速道路で車が追突しました。","Trên đường cao tốc, xe ô tô đã đâm từ phía sau."]]},{"word":"盗みます","reading":"ぬすみます","meaning":"ăn trộm, đánh cắp","hanViet":"ĐẠO","lesson":37,"ex":[["泥棒がお金を盗みました。","Kẻ trộm đã ăn trộm tiền."],["かばんを盗まれました。","Tôi bị trộm mất túi xách."],["自転車を盗まれました。","Tôi bị trộm mất xe đạp."],["泥棒が車を盗みました。","Kẻ trộm đã ăn trộm ô tô."],["子どもがお菓子を盗みました。","Đứa trẻ đã ăn trộm kẹo."]]},{"word":"誘拐します","reading":"ゆうかいします","meaning":"bắt cóc","hanViet":"DỤ QUẢI","lesson":37,"ex":[["犯人が子どもを誘拐しました。","Kẻ phạm tội đã bắt cóc trẻ em."],["子どもが誘拐されました。","Đứa trẻ đã bị bắt cóc."],["ニュースで誘拐のことを聞きました。","Tôi nghe tin về vụ bắt cóc trên bản tin."],["警察が誘拐された子どもを探しています。","Cảnh sát đang tìm đứa trẻ bị bắt cóc."],["犯人が女の人を誘拐しました。","Kẻ phạm tội đã bắt cóc người phụ nữ."]]},{"word":"墜落します","reading":"ついらくします","meaning":"(máy bay) rơi","hanViet":"TRỤY LẠC","lesson":37,"ex":[["飛行機が墜落しました。","Máy bay đã rơi."],["飛行機が山に墜落しました。","Máy bay đã rơi xuống núi."],["飛行機が海に墜落しました。","Máy bay đã rơi xuống biển."],["ニュースで飛行機が墜落したと聞きました。","Tôi nghe tin máy bay rơi trên bản tin."],["小さい飛行機が墜落しました。","Chiếc máy bay nhỏ đã rơi."]]},{"word":"爆発します","reading":"ばくはつします","meaning":"nổ","hanViet":"BẠO PHÁT","lesson":37,"ex":[["ガスが爆発しました。","Khí gas đã nổ."],["車が爆発しました。","Xe ô tô đã nổ."],["工場でガスが爆発しました。","Khí gas đã nổ ở nhà máy."],["火事で車が爆発しました。","Vì hỏa hoạn nên xe ô tô đã nổ."],["ニュースで爆発のことを聞きました。","Tôi nghe tin về vụ nổ trên bản tin."]]},{"word":"助けます","reading":"たすけます","meaning":"cứu giúp, giúp đỡ","hanViet":"TRỢ","lesson":37,"ex":[["田中さんは困っている友達を助けました。","Anh Tanaka đã giúp đỡ người bạn đang gặp khó khăn."],["先生はいつも学生を助けます。","Thầy giáo lúc nào cũng giúp đỡ học sinh."],["私は日本語がわからない友達を助けます。","Tôi giúp đỡ người bạn không hiểu tiếng Nhật."],["雨の日に友達が傘を貸して、私を助けました。","Vào ngày mưa, bạn tôi đã cho tôi mượn ô và giúp tôi."],["犬が川で泳いでいる子どもを助けました。","Con chó đã cứu đứa trẻ đang bơi ở sông."]]},{"word":"沈没します","reading":"ちんぼつします","meaning":"chìm, đắm","hanViet":"TRẦM MỘT","lesson":37,"ex":[["大きな船が海で沈没しました。","Con tàu lớn đã chìm ở biển."],["雨と風が強い日に、船が沈没しました。","Vào ngày mưa to gió lớn, con tàu đã chìm."],["古い船は海で沈没するかもしれません。","Con tàu cũ có thể sẽ chìm ở biển."],["映画で船が沈没するのを見ました。","Tôi đã xem cảnh tàu chìm trong phim."],["船が沈没しましたが、人はみんな元気でした。","Tàu đã chìm nhưng mọi người đều khỏe mạnh."]]},{"word":"デート","reading":"デート","meaning":"cuộc hẹn hò","hanViet":"","lesson":37,"ex":[["日曜日に彼女とデートをします。","Chủ nhật tôi hẹn hò với bạn gái."],["田中さんはデートの前に、花を買いました。","Trước buổi hẹn hò, anh Tanaka đã mua hoa."],["初めてのデートは映画館でした。","Buổi hẹn hò đầu tiên là ở rạp chiếu phim."],["デートで公園を散歩しました。","Trong buổi hẹn hò, chúng tôi đã đi dạo ở công viên."],["あした、デートがあります。","Ngày mai tôi có buổi hẹn hò."]]},{"word":"アクセス","reading":"アクセス","meaning":"nối, giao thông đi đến","hanViet":"","lesson":37,"ex":[["この駅は東京へのアクセスがいいです。","Ga này đi đến Tokyo rất tiện."],["新しいホテルは駅からのアクセスがいいです。","Khách sạn mới đi từ ga đến rất tiện."],["学校へのアクセスが悪いので、バスで通います。","Đi đến trường không tiện nên tôi đi học bằng xe buýt."],["この空港は町へのアクセスが便利です。","Sân bay này đi đến thành phố rất tiện lợi."],["アクセスがいいホテルを探しました。","Tôi đã tìm khách sạn có giao thông thuận tiện."]]},{"word":"ドミニカ","reading":"ドミニカ","meaning":"Dominica(tên một quốc gia ở Trung Mỹ)","hanViet":"","lesson":37,"ex":[["ドミニカは小さな国です。","Dominica là một quốc gia nhỏ."],["ドミニカは海がきれいな国です。","Dominica là quốc gia có biển đẹp."],["友達はドミニカへ旅行に行きました。","Bạn tôi đã đi du lịch đến Dominica."],["ドミニカは暑い国です。","Dominica là quốc gia nóng."],["ドミニカの人は英語を話します。","Người Dominica nói tiếng Anh."]]},{"word":"一匹もいません","reading":"いっぴきもいません","meaning":"không có con nào cả","hanViet":"NHẤT THẤT","lesson":37,"ex":[["この池に魚は一匹もいません。","Trong cái ao này không có con cá nào cả."],["家に犬は一匹もいません。","Ở nhà không có con chó nào cả."],["公園に猫は一匹もいませんでした。","Ở công viên không có con mèo nào cả."],["庭に犬は一匹もいません。","Sân nhà không có con chó nào cả."],["山田さんの家に猫は一匹もいません。","Nhà anh Yamada không có con mèo nào cả."]]},{"word":"育てます","reading":"そだてます","meaning":"Nuôi nấng, dưỡng dục","hanViet":"DỤC","lesson":38,"ex":[["母は三人の子どもを育てました。","Mẹ tôi đã nuôi nấng ba đứa con."],["祖父は庭で花を育てています。","Ông tôi đang trồng hoa ở sân."],["田中さんは犬を育てています。","Anh Tanaka đang nuôi một con chó."],["母は野菜を育てています。","Mẹ tôi đang trồng rau."],["父は私を育てました。","Bố tôi đã nuôi nấng tôi."]]},{"word":"亡くなります","reading":"なくなります","meaning":"qua đời; mất đi","hanViet":"VONG","lesson":38,"ex":[["祖父は去年、亡くなりました。","Ông tôi đã qua đời năm ngoái."],["祖母は90歳で亡くなりました。","Bà tôi qua đời lúc 90 tuổi."],["田中さんのお父さんは先月、亡くなりました。","Bố của anh Tanaka đã qua đời tháng trước."],["先生が亡くなりました。","Thầy giáo đã qua đời."],["祖父が亡くなって、もう10年たちました。","Ông tôi qua đời đã 10 năm rồi."]]},{"word":"入院します","reading":"にゅういんします","meaning":"nhập viện","hanViet":"NHẬP VIỆN","lesson":38,"ex":[["祖母は病気で入院しました。","Bà tôi nhập viện vì bị bệnh."],["父はけがをして、入院しました。","Bố tôi bị thương và đã nhập viện."],["友達が入院したので、病院へ行きました。","Bạn tôi nhập viện nên tôi đã đến bệnh viện."],["母は来週、入院します。","Mẹ tôi sẽ nhập viện tuần sau."],["田中さんは足が痛くて、入院しました。","Anh Tanaka bị đau chân và đã nhập viện."]]},{"word":"退院します","reading":"たいいんします","meaning":"xuất viện","hanViet":"THOÁI VIỆN","lesson":38,"ex":[["祖母は来週、退院します。","Bà tôi sẽ xuất viện tuần sau."],["父は元気になって、退院しました。","Bố tôi đã khỏe lại và xuất viện."],["友達はきのう、退院しました。","Bạn tôi đã xuất viện hôm qua."],["田中さんはあした退院する予定です。","Anh Tanaka dự định xuất viện ngày mai."],["病院に7日いて、退院しました。","Tôi ở bệnh viện 7 ngày rồi xuất viện."]]},{"word":"入れます","reading":"いれます","meaning":"bật","hanViet":"NHẬP","lesson":38,"ex":[["テレビの電源を入れます。","Tôi bật nguồn tivi."],["暗くなったので、電気を入れました。","Trời tối nên tôi đã bật điện."],["ラジオを入れて、音楽を聞きます。","Tôi bật radio và nghe nhạc."],["パソコンの電源を入れて、仕事を始めます。","Tôi bật nguồn máy tính và bắt đầu làm việc."],["先生は教室の電気を入れました。","Thầy giáo đã bật điện trong lớp học."]]},{"word":"切ります","reading":"きります","meaning":"Cắt","hanViet":"THIẾT","lesson":38,"ex":[["はさみで紙を切ります。","Tôi cắt giấy bằng kéo."],["肉を切って、料理を作ります。","Tôi cắt thịt rồi nấu ăn."],["母はパンを切りました。","Mẹ tôi đã cắt bánh mì."],["髪を切りました。","Tôi đã cắt tóc."],["りんごを切って、食べました。","Tôi đã cắt táo và ăn."]]},{"word":"気持ちがいい","reading":"きもちがいい","meaning":"dễ chịu, thư giãn","hanViet":"KHÍ TRÌ","lesson":38,"ex":[["お風呂に入ると、気持ちがいいです。","Tắm bồn thật dễ chịu."],["朝の空気は気持ちがいいです。","Không khí buổi sáng thật dễ chịu."],["海で泳ぐと、気持ちがいいです。","Bơi ở biển thật dễ chịu."],["春の風は気持ちがいいです。","Gió mùa xuân thật dễ chịu."],["散歩すると、気持ちがいいです。","Đi dạo thật dễ chịu."]]},{"word":"気持ちが悪い","reading":"きもちがわるい","meaning":"khó chịu","hanViet":"KHÍ TRÌ ÁC","lesson":38,"ex":[["バスに乗ると、気持ちが悪いです。","Đi xe buýt tôi thấy khó chịu."],["朝から気持ちが悪いです。","Từ sáng tôi đã thấy khó chịu."],["熱があって、気持ちが悪いです。","Tôi bị sốt và thấy khó chịu."],["船に乗ると、気持ちが悪くなります。","Đi tàu tôi thấy khó chịu."],["きのうは食べすぎて、気持ちが悪かったです。","Hôm qua tôi ăn quá nhiều nên thấy khó chịu."]]},{"word":"大きな～","reading":"おおきな～","meaning":"~ to, ~ lớn","hanViet":"ĐẠI","lesson":38,"ex":[["大きな犬がいます。","Có một con chó to."],["大きな家に住んでいます。","Tôi sống trong một ngôi nhà lớn."],["大きな木の下で休みました。","Tôi đã nghỉ dưới gốc cây lớn."],["大きな船が海にあります。","Có một con tàu lớn ở biển."],["大きな声で話してください。","Hãy nói bằng giọng lớn."]]},{"word":"小さな～","reading":"ちいさな～","meaning":"nhỏ, ~ bé","hanViet":"TIỂU","lesson":38,"ex":[["小さな猫がいます。","Có một con mèo nhỏ."],["小さな花が咲いています。","Có bông hoa nhỏ đang nở."],["小さな子どもが公園で遊んでいます。","Đứa trẻ nhỏ đang chơi ở công viên."],["小さな店でパンを買いました。","Tôi đã mua bánh mì ở cửa hàng nhỏ."],["小さな声で話しました。","Tôi đã nói bằng giọng nhỏ."]]},{"word":"赤ちゃん","reading":"あかちゃん","meaning":"Em bé sơ sinh","hanViet":"XÍCH NHI","lesson":38,"ex":[["赤ちゃんが生まれました。","Em bé đã ra đời."],["赤ちゃんはよく寝ます。","Em bé ngủ nhiều."],["姉の赤ちゃんはかわいいです。","Em bé của chị tôi dễ thương."],["赤ちゃんが笑っています。","Em bé đang cười."],["赤ちゃんはミルクを飲みます。","Em bé uống sữa."]]},{"word":"海岸","reading":"かいがん","meaning":"Bờ biển","hanViet":"HẢI NGẠN","lesson":38,"ex":[["海岸を散歩しました。","Tôi đã đi dạo ở bờ biển."],["夏は海岸で泳ぎます。","Mùa hè tôi bơi ở bờ biển."],["海岸にたくさんの人がいます。","Ở bờ biển có rất nhiều người."],["海岸から船が見えます。","Từ bờ biển có thể nhìn thấy tàu."],["海岸で写真を撮りました。","Tôi đã chụp ảnh ở bờ biển."]]},{"word":"うそ","reading":"うそ","meaning":"nói dối, lời nói dối","hanViet":"","lesson":38,"ex":[["うそをついてはいけません。","Không được nói dối."],["それはうそです。","Đó là lời nói dối."],["弟はうそをつきました。","Em trai tôi đã nói dối."],["うそをつくと、友達がいなくなります。","Nói dối sẽ mất bạn bè."],["それは本当ですか、うそですか。","Đó là thật hay là nói dối?"]]},{"word":"書類","reading":"しょるい","meaning":"Giấy tờ, tài liệu, hồ sơ","hanViet":"THƯ LOẠI","lesson":38,"ex":[["書類を整理します。","Tôi sắp xếp giấy tờ."],["書類を会社に持って行きます。","Tôi mang giấy tờ đến công ty."],["大切な書類をなくしました。","Tôi đã làm mất giấy tờ quan trọng."],["書類に名前を書きました。","Tôi đã viết tên vào giấy tờ."],["先生に書類を渡しました。","Tôi đã đưa giấy tờ cho thầy giáo."]]},{"word":"電源","reading":"でんげん","meaning":"nguồn điện","hanViet":"ĐIỆN NGUYÊN","lesson":38,"ex":[["パソコンの電源を切ります。","Tôi tắt nguồn máy tính."],["電源を切ってください。","Hãy tắt nguồn điện giúp tôi."],["電源が入っていません。","Nguồn điện chưa được bật."],["電源を入れると、テレビがつきます。","Bật nguồn điện thì tivi sẽ mở."],["この機械の電源はどこですか。","Nguồn điện của máy này ở đâu?"]]},{"word":"～製","reading":"～せい","meaning":"sản xuất tại ~","hanViet":"CHẾ","lesson":38,"ex":[["この時計は日本製です。","Chiếc đồng hồ này sản xuất tại Nhật Bản."],["この車はドイツ製です。","Chiếc xe này sản xuất tại Đức."],["このかばんはフランス製です。","Chiếc túi này sản xuất tại Pháp."],["この服は中国製です。","Bộ quần áo này sản xuất tại Trung Quốc."],["このカメラは日本製ですか。","Chiếc máy ảnh này sản xuất tại Nhật Bản phải không?"]]},{"word":"あ、いけない。","reading":"あ、いけない","meaning":"Ôi, hỏng mất rồi./Ôi, trời ơi","hanViet":"","lesson":38,"ex":[["あ、いけない。傘を忘れました。","Ôi, hỏng rồi. Tôi quên ô mất rồi."],["あ、いけない。電車がもう出ました。","Ôi, trời ơi. Tàu điện đã chạy rồi."],["あ、いけない。宿題を忘れました。","Ôi, hỏng rồi. Tôi quên bài tập về nhà mất rồi."],["あ、いけない。財布がありません。","Ôi, trời ơi. Không có ví rồi."],["あ、いけない。もう8時です。","Ôi, hỏng rồi. Đã 8 giờ rồi."]]},{"word":"お先に失礼します","reading":"おさきにしつれいします","meaning":"tôi xin phép về trước","hanViet":"TIÊN THẤT LỄ","lesson":38,"ex":[["お先に失礼します。あした、また会いましょう。","Tôi xin phép về trước. Mai gặp lại nhé."],["きょうは疲れたので、お先に失礼します。","Hôm nay tôi mệt nên xin phép về trước."],["田中さんは「お先に失礼します」と言って、帰りました。","Anh Tanaka nói \"Tôi xin phép về trước\" rồi về."],["お先に失礼します。お疲れ様でした。","Tôi xin phép về trước. Anh/chị đã vất vả rồi."],["6時になったので、お先に失礼します。","Đã 6 giờ nên tôi xin phép về trước."]]},{"word":"回覧","reading":"かいらん","meaning":"Tập thông báo","hanViet":"HỒI LÃM","lesson":38,"ex":[["回覧が来ました。","Tập thông báo đã đến."],["回覧を見て、はんこを押します。","Tôi xem tập thông báo và đóng dấu."],["回覧を隣の家に持って行きます。","Tôi mang tập thông báo đến nhà hàng xóm."],["回覧に祭りのことが書いてありました。","Trong tập thông báo có viết về lễ hội."],["回覧を読みました。","Tôi đã đọc tập thông báo."]]},{"word":"研究室","reading":"けんきゅうしつ","meaning":"Phòng nghiên cứu","hanViet":"NGHIÊN CỨU THẤT","lesson":38,"ex":[["先生は研究室にいます。","Thầy giáo đang ở phòng nghiên cứu."],["研究室で実験をします。","Tôi làm thí nghiệm ở phòng nghiên cứu."],["研究室は大学にあります。","Phòng nghiên cứu ở trong trường đại học."],["研究室で本を読みます。","Tôi đọc sách ở phòng nghiên cứu."],["田中先生の研究室は広いです。","Phòng nghiên cứu của thầy Tanaka rộng."]]},{"word":"きちんと","reading":"きちんと","meaning":"Nghiêm chỉnh, hẳn hoi, đứng đắn","hanViet":"","lesson":38,"ex":[["部屋をきちんと掃除します。","Tôi dọn dẹp phòng ốc cẩn thận."],["きちんと座ってください。","Hãy ngồi ngay ngắn."],["宿題をきちんとしました。","Tôi đã làm bài tập về nhà cẩn thận."],["服をきちんと整理します。","Tôi sắp xếp quần áo gọn gàng."],["きちんとあいさつをします。","Tôi chào hỏi đàng hoàng."]]},{"word":"整理します","reading":"せいりします","meaning":"sắp xếp","hanViet":"CHỈNH LÝ","lesson":38,"ex":[["部屋を整理します。","Tôi sắp xếp phòng."],["本棚の本を整理しました。","Tôi đã sắp xếp sách trên giá sách."],["机の上を整理します。","Tôi sắp xếp trên bàn."],["写真を整理しました。","Tôi đã sắp xếp ảnh."],["かばんの中を整理します。","Tôi sắp xếp trong túi."]]},{"word":"～という本","reading":"～というほん","meaning":"quyển sách có tên là ~","hanViet":"BẢN","lesson":38,"ex":[["「日本の歴史」という本を読みました。","Tôi đã đọc quyển sách có tên là \"Lịch sử Nhật Bản\"."],["「日本の料理」という本を買いました。","Tôi đã mua quyển sách có tên là \"Món ăn Nhật Bản\"."],["「日本の昔話」という本はおもしろいです。","Quyển sách có tên là \"Truyện cổ Nhật Bản\" rất thú vị."],["先生は「日本語の文法」という本を使っています。","Thầy giáo đang dùng quyển sách có tên là \"Ngữ pháp tiếng Nhật\"."],["「日本の歌」という本を知っていますか。","Bạn có biết quyển sách có tên là \"Bài hát Nhật Bản\" không?"]]},{"word":"～冊","reading":"～さつ","meaning":"(đơn vị đếm sách, v.v.)","hanViet":"SÁCH","lesson":38,"ex":[["本を3冊買いました。","Tôi đã mua 3 quyển sách."],["図書館で本を2冊借りました。","Tôi đã mượn 2 quyển sách ở thư viện."],["机の上に本が5冊あります。","Trên bàn có 5 quyển sách."],["雑誌を1冊読みました。","Tôi đã đọc 1 quyển tạp chí."],["何冊の本を持っていますか。","Bạn có bao nhiêu quyển sách?"]]},{"word":"はんこ","reading":"はんこ","meaning":"con dấu, dấu","hanViet":"","lesson":38,"ex":[["書類にはんこを押します。","Tôi đóng dấu vào giấy tờ."],["はんこを忘れました。","Tôi quên con dấu mất rồi."],["新しいはんこを買いました。","Tôi đã mua con dấu mới."],["回覧にはんこを押しました。","Tôi đã đóng dấu vào tập thông báo."],["はんこはどこですか。","Con dấu ở đâu?"]]},{"word":"押します","reading":"おします","meaning":"Ấn, nhấn, đẩy","hanViet":"ÁP","lesson":38,"ex":[["ボタンを押します。","Tôi nhấn nút."],["はんこを押しました。","Tôi đã đóng dấu."],["ドアを押して、開けました。","Tôi đẩy cửa và mở ra."],["エレベーターのボタンを押してください。","Hãy nhấn nút thang máy giúp tôi."],["車が動かないので、押します。","Xe không chạy nên tôi đẩy."]]},{"word":"双子","reading":"ふたご","meaning":"Song sinh, trẻ sinh đôi","hanViet":"SONG TỬ","lesson":38,"ex":[["あの二人は双子です。","Hai người kia là sinh đôi."],["双子の姉妹がいます。","Tôi có chị em sinh đôi."],["姉は双子です。","Chị tôi là sinh đôi."],["双子はよく似ています。","Cặp sinh đôi rất giống nhau."],["双子の赤ちゃんが生まれました。","Cặp em bé sinh đôi đã ra đời."]]},{"word":"姉妹","reading":"しまい","meaning":"Chị em gái","hanViet":"TỶ MUỘI","lesson":38,"ex":[["私には姉妹が二人います。","Tôi có hai chị em gái."],["あの姉妹はよく似ています。","Hai chị em gái kia rất giống nhau."],["姉妹でデパートへ行きました。","Hai chị em đã cùng đi trung tâm thương mại."],["山田さんの姉妹は学生です。","Chị em gái của anh Yamada là học sinh."],["姉妹は二人で遊びます。","Hai chị em chơi với nhau."]]},{"word":"五年生","reading":"ごねんせい","meaning":"học sinh năm thứ 5","hanViet":"NGŨ NIÊN SINH","lesson":38,"ex":[["弟は五年生です。","Em trai tôi là học sinh lớp 5."],["五年生の子どもが小学校に通っています。","Học sinh lớp 5 đang học ở trường tiểu học."],["妹は五年生になりました。","Em gái tôi đã lên lớp 5."],["五年生の山田さんは英語が好きです。","Bạn Yamada lớp 5 thích môn tiếng Anh."],["五年生が運動会で走りました。","Học sinh lớp 5 đã chạy trong hội thao."]]},{"word":"似ています","reading":"にています","meaning":"giống","hanViet":"TỰ","lesson":38,"ex":[["姉と妹はよく似ています。","Chị gái và em gái rất giống nhau."],["弟は父に似ています。","Em trai tôi giống bố."],["この花は桜に似ています。","Bông hoa này giống hoa anh đào."],["双子はとても似ています。","Cặp sinh đôi rất giống nhau."],["私は母に似ています。","Tôi giống mẹ."]]},{"word":"性格","reading":"せいかく","meaning":"Tính cách","hanViet":"TÍNH CÁCH","lesson":38,"ex":[["田中さんは性格がいいです。","Anh Tanaka có tính cách tốt."],["姉と妹は性格が違います。","Chị gái và em gái có tính cách khác nhau."],["先生は性格がおとなしいです。","Thầy giáo có tính cách trầm."],["性格が明るい人が好きです。","Tôi thích người có tính cách vui vẻ."],["友達の性格を知っています。","Tôi biết tính cách của bạn."]]},{"word":"おとなしい","reading":"おとなしい","meaning":"hiền lành, trầm","hanViet":"","lesson":38,"ex":[["妹はおとなしいです。","Em gái tôi hiền lành."],["おとなしい犬を飼っています。","Tôi đang nuôi một con chó hiền lành."],["あの学生はおとなしい性格です。","Học sinh kia có tính cách trầm."],["クラスにおとなしい学生がいます。","Trong lớp có một học sinh trầm tính."],["猫はおとなしいです。","Con mèo hiền lành."]]},{"word":"世話をします","reading":"せわをします","meaning":"chăm sóc , giúp đỡ","hanViet":"THẾ THOẠI","lesson":38,"ex":[["母は祖母の世話をします。","Mẹ tôi chăm sóc bà."],["先生は学生の世話をします。","Thầy giáo chăm sóc học sinh."],["姉は弟の世話をします。","Chị gái chăm sóc em trai."],["田中さんは犬の世話をします。","Anh Tanaka chăm sóc chó."],["子どもの世話をするのは大変です。","Chăm sóc trẻ con rất vất vả."]]},{"word":"時間がたちます","reading":"じかんがたちます","meaning":"thời gian trôi đi","hanViet":"THỜI GIAN","lesson":38,"ex":[["時間がたちますね。","Thời gian trôi qua thật đấy."],["日本に来て、時間がたちました。","Từ khi đến Nhật, thời gian đã trôi qua."],["楽しいときは時間がたつのが速いです。","Lúc vui vẻ thời gian trôi thật nhanh."],["時間がたって、子どもは大きくなりました。","Thời gian trôi qua, đứa trẻ đã lớn lên."],["あの日から、時間がたちました。","Từ ngày đó, thời gian đã trôi qua."]]},{"word":"大好きな","reading":"だいすきな","meaning":"Rất thích","hanViet":"ĐẠI HẢO","lesson":38,"ex":[["大好きな歌を聞きます。","Tôi nghe bài hát rất thích."],["大好きな映画を見ました。","Tôi đã xem bộ phim rất thích."],["私は大好きな本を読みます。","Tôi đọc quyển sách rất thích."],["大好きな先生に会いました。","Tôi đã gặp thầy giáo rất thích."],["大好きな料理を作ります。","Tôi nấu món ăn rất thích."]]},{"word":"～点","reading":"～てん","meaning":"- điểm","hanViet":"ĐIỂM","lesson":38,"ex":[["テストで90点を取りました。","Tôi đã đạt 90 điểm trong bài kiểm tra."],["日本語のテストは80点でした。","Bài kiểm tra tiếng Nhật được 80 điểm."],["100点を取りたいです。","Tôi muốn đạt 100 điểm."],["英語のテストで70点を取りました。","Tôi đã đạt 70 điểm trong bài kiểm tra tiếng Anh."],["50点しか取れませんでした。","Tôi chỉ đạt 50 điểm."]]},{"word":"けんかします","reading":"けんかします","meaning":"cãi nhau","hanViet":"","lesson":38,"ex":[["弟とけんかしました。","Tôi đã cãi nhau với em trai."],["姉妹はよくけんかします。","Hai chị em thường cãi nhau."],["友達とけんかして、悲しかったです。","Tôi cãi nhau với bạn và cảm thấy buồn."],["子どもがけんかしています。","Trẻ con đang cãi nhau."],["けんかしないでください。","Đừng cãi nhau."]]},{"word":"お正月","reading":"おしょうがつ","meaning":"tháng Giêng, dịp Tết năm mới","hanViet":"CHÍNH NGUYỆT","lesson":38,"ex":[["お正月に家族で集まります。","Vào dịp Tết, cả gia đình tụ họp."],["お正月は1月1日です。","Tết là ngày 1 tháng 1."],["お正月に神社へ行きます。","Vào dịp Tết tôi đi đền thờ."],["お正月に年賀状を書きます。","Vào dịp Tết tôi viết thiệp chúc mừng năm mới."],["お正月は家でゆっくり休みます。","Vào dịp Tết, tôi nghỉ ngơi thong thả ở nhà."]]},{"word":"ひな祭り","reading":"ひなまつり","meaning":"Lễ hội búp bê","hanViet":"TẾ","lesson":38,"ex":[["ひな祭りは3月3日です。","Lễ hội búp bê là ngày 3 tháng 3."],["ひな祭りに人形を飾ります。","Vào lễ hội búp bê, tôi trưng bày búp bê."],["ひな祭りは女の子の日です。","Lễ hội búp bê là ngày của bé gái."],["ひな祭りに家族でケーキを食べました。","Vào lễ hội búp bê, cả gia đình đã ăn bánh cùng nhau."],["妹はひな祭りが好きです。","Em gái tôi thích lễ hội búp bê."]]},{"word":"お月見","reading":"おつきみ","meaning":"Hội ngắm trăng","hanViet":"NGUYỆT KIẾN","lesson":38,"ex":[["お月見は秋にあります。","Hội ngắm trăng diễn ra vào mùa thu."],["お月見で月を見ます。","Trong hội ngắm trăng, tôi ngắm trăng."],["お月見でお酒を飲みます。","Trong hội ngắm trăng, tôi uống rượu."],["家族でお月見をしました。","Cả gia đình đã cùng ngắm trăng."],["お月見の夜は月がきれいです。","Đêm ngắm trăng, mặt trăng rất đẹp."]]},{"word":"小学校","reading":"しょうがっこう","meaning":"trường tiểu học","hanViet":"TIỂU HỌC HIỆU","lesson":38,"ex":[["弟は小学校に通っています。","Em trai tôi đang học ở trường tiểu học."],["小学校は家の近くにあります。","Trường tiểu học ở gần nhà."],["小学校の先生をしています。","Tôi làm giáo viên trường tiểu học."],["小学校で運動会があります。","Ở trường tiểu học có hội thao."],["妹は来年、小学校に入ります。","Em gái tôi năm sau sẽ vào trường tiểu học."]]},{"word":"中学校","reading":"ちゅうがっこう","meaning":"trường trung học cơ sở","hanViet":"TRUNG HỌC HIỆU","lesson":38,"ex":[["兄は中学校に通っています。","Anh trai tôi đang học ở trường trung học cơ sở."],["中学校は駅の近くにあります。","Trường trung học cơ sở ở gần ga."],["中学校で英語を勉強します。","Tôi học tiếng Anh ở trường trung học cơ sở."],["中学校の先生をしています。","Tôi làm giáo viên trường trung học cơ sở."],["弟は来年、中学校に入ります。","Em trai tôi năm sau sẽ vào trường trung học cơ sở."]]},{"word":"クラス","reading":"クラス","meaning":"lớp học, lớp","hanViet":"","lesson":38,"ex":[["私のクラスは30人です。","Lớp của tôi có 30 người."],["クラスで日本語を勉強します。","Tôi học tiếng Nhật trong lớp."],["クラスに友達がたくさんいます。","Trong lớp có nhiều bạn bè."],["田中さんは私のクラスの学生です。","Anh Tanaka là học sinh lớp tôi."],["クラスで歌を歌いました。","Trong lớp, chúng tôi đã hát."]]},{"word":"答えます","reading":"こたえます","meaning":"trả lời","hanViet":"ĐÁP","lesson":39,"ex":[["先生が聞いたことに答えます。","Tôi trả lời điều thầy giáo đã hỏi."],["電話に出て、答えました。","Tôi nghe điện thoại và trả lời."],["友達の手紙に答えました。","Tôi đã trả lời thư của bạn."],["テストの問題に答えます。","Tôi trả lời câu hỏi trong bài kiểm tra."],["手紙に答えてください。","Hãy trả lời thư giúp tôi."]]},{"word":"焼けます","reading":"やけます","meaning":"cháy","hanViet":"THIÊU","lesson":39,"ex":[["パンが焼けました。","Bánh mì đã chín."],["家が火事で焼けました。","Nhà đã cháy trong hỏa hoạn."],["夏にたくさん泳いで、体が焼けました。","Mùa hè tôi bơi nhiều nên da bị cháy nắng."],["肉がよく焼けました。","Thịt đã chín kỹ."],["ケーキが焼けました。","Bánh đã chín."]]},{"word":"通ります","reading":"とおります","meaning":"đi qua","hanViet":"THÔNG","lesson":39,"ex":[["この道を通ります。","Tôi đi qua con đường này."],["電車が駅を通ります。","Tàu điện đi qua ga."],["橋を通って、学校へ行きます。","Tôi đi qua cầu đến trường."],["毎日、この店の前を通ります。","Mỗi ngày tôi đi qua trước cửa hàng này."],["バスが家の前を通ります。","Xe buýt đi qua trước nhà tôi."]]},{"word":"死にます","reading":"しにます","meaning":"chết","hanViet":"TỬ","lesson":39,"ex":[["犬が死にました。","Con chó đã chết."],["祖父は90歳で死にました。","Ông tôi qua đời lúc 90 tuổi."],["事故で人が死にました。","Trong tai nạn, có người đã chết."],["魚が死にました。","Con cá đã chết."],["猫が死んで、悲しかったです。","Con mèo chết nên tôi buồn."]]},{"word":"びっくりします","reading":"びっくりします","meaning":"ngạc nhiên, giật mình","hanViet":"","lesson":39,"ex":[["大きな音にびっくりしました。","Tôi giật mình vì tiếng động lớn."],["友達の話にびっくりしました。","Tôi ngạc nhiên trước câu chuyện của bạn."],["値段を見て、びっくりしました。","Nhìn giá tiền, tôi rất ngạc nhiên."],["犬が出てきて、びっくりしました。","Con chó xuất hiện làm tôi giật mình."],["テストの点にびっくりしました。","Tôi ngạc nhiên trước điểm bài kiểm tra."]]},{"word":"がっかりします","reading":"がっかりします","meaning":"thất vọng","hanViet":"","lesson":39,"ex":[["テストの点にがっかりしました。","Tôi thất vọng về điểm bài kiểm tra."],["雨で旅行に行けなくて、がっかりしました。","Trời mưa không đi du lịch được nên tôi thất vọng."],["映画がおもしろくなくて、がっかりしました。","Phim không thú vị nên tôi thất vọng."],["友達が来なくて、がっかりしました。","Bạn không đến nên tôi thất vọng."],["試合に負けて、がっかりしました。","Thua trận đấu nên tôi thất vọng."]]},{"word":"安心します","reading":"あんしんします","meaning":"yên tâm","hanViet":"AN TÂM","lesson":39,"ex":[["友達が元気だと聞いて、安心しました。","Nghe nói bạn khỏe mạnh, tôi đã yên tâm."],["先生の話を聞いて、安心しました。","Nghe thầy giáo nói, tôi đã yên tâm."],["電話があって、安心しました。","Có điện thoại nên tôi đã yên tâm."],["家族が元気で、安心しました。","Gia đình khỏe mạnh nên tôi yên tâm."],["テストが終わって、安心しました。","Bài kiểm tra kết thúc nên tôi yên tâm."]]},{"word":"遅刻します","reading":"ちこくします","meaning":"đến chậm, đến muộn","hanViet":"TRÌ KHẮC","lesson":39,"ex":[["電車が遅れて、学校に遅刻しました。","Tàu điện đến muộn nên tôi đi học muộn."],["朝、起きるのが遅れて、会社に遅刻しました。","Buổi sáng tôi dậy muộn nên đi làm muộn."],["遅刻してはいけません。","Không được đến muộn."],["田中さんはよく遅刻します。","Anh Tanaka thường đến muộn."],["会議に遅刻しました。","Tôi đã đến muộn cuộc họp."]]},{"word":"早退します","reading":"そうたいします","meaning":"về sớm, ra sớm","hanViet":"TẢO THOÁI","lesson":39,"ex":[["熱があって、会社を早退しました。","Tôi bị sốt nên đã về sớm khỏi công ty."],["頭が痛くて、学校を早退しました。","Tôi đau đầu nên đã về sớm khỏi trường."],["用事があって、早退します。","Tôi có việc bận nên sẽ về sớm."],["田中さんはきのう、早退しました。","Anh Tanaka hôm qua đã về sớm."],["疲れて、早退しました。","Tôi mệt nên đã về sớm."]]},{"word":"離婚します","reading":"りこんします","meaning":"ly dị, ly hôn","hanViet":"LY HÔN","lesson":39,"ex":[["田中さんの両親は離婚しました。","Bố mẹ anh Tanaka đã ly hôn."],["山田さんと奥さんは離婚しました。","Anh Yamada và vợ đã ly hôn."],["離婚して、子どもと住んでいます。","Sau khi ly hôn, tôi sống cùng con."],["両親が離婚して、悲しかったです。","Bố mẹ ly hôn nên tôi buồn."],["離婚する人が増えています。","Số người ly hôn đang tăng lên."]]},{"word":"複雑","reading":"ふくざつ","meaning":"Phức tạp","hanViet":"PHỨC TẠP","lesson":39,"ex":[["この問題は複雑です。","Vấn đề này phức tạp."],["複雑な文法を勉強します。","Tôi học ngữ pháp phức tạp."],["この機械は複雑です。","Máy này phức tạp."],["日本語の文法は複雑です。","Ngữ pháp tiếng Nhật phức tạp."],["複雑な気持ちです。","Tôi có cảm xúc phức tạp."]]},{"word":"邪魔","reading":"じゃま","meaning":"cản trở, vướng víu; làm phiền","hanViet":"TÀ MA","lesson":39,"ex":[["荷物が邪魔です。","Hành lý vướng víu."],["勉強の邪魔をしないでください。","Đừng làm phiền việc học của tôi."],["車が道の邪魔になっています。","Xe đang cản trở đường đi."],["邪魔をして、すみません。","Xin lỗi đã làm phiền."],["この箱は邪魔です。","Cái hộp này vướng víu."]]},{"word":"汚い","reading":"きたない","meaning":"Bẩn, dơ","hanViet":"Ô","lesson":39,"ex":[["この部屋は汚いです。","Phòng này bẩn."],["汚い手を洗ってください。","Hãy rửa bàn tay bẩn."],["靴が汚いです。","Giày bẩn."],["川の水が汚いです。","Nước sông bẩn."],["汚い服を着ています。","Tôi đang mặc quần áo bẩn."]]},{"word":"恥ずかしい","reading":"はずかしい","meaning":"Xấu hổ, ngại ngùng","hanViet":"SỈ","lesson":39,"ex":[["人の前で話すのは恥ずかしいです。","Nói trước mặt mọi người thật xấu hổ."],["名前を忘れて、恥ずかしかったです。","Tôi quên tên nên xấu hổ."],["恥ずかしくて、顔が赤くなりました。","Xấu hổ quá nên mặt tôi đỏ lên."],["日本語で話すのは恥ずかしいです。","Nói bằng tiếng Nhật thật ngại ngùng."],["みんなに見られて、恥ずかしかったです。","Bị mọi người nhìn nên tôi xấu hổ."]]},{"word":"火事","reading":"かじ","meaning":"hỏa hoạn","hanViet":"HỎA SỰ","lesson":39,"ex":[["隣の家で火事がありました。","Nhà hàng xóm xảy ra hỏa hoạn."],["火事で店が焼けました。","Cửa hàng đã cháy trong hỏa hoạn."],["火事のときは、逃げてください。","Khi có hỏa hoạn, hãy chạy đi."],["火事が起きました。","Đã xảy ra hỏa hoạn."],["火事でけがをした人がいます。","Có người bị thương trong hỏa hoạn."]]},{"word":"事故","reading":"じこ","meaning":"tai nạn, sự cố","hanViet":"SỰ CỐ","lesson":39,"ex":[["車の事故がありました。","Đã xảy ra tai nạn xe."],["事故で車が壊れました。","Trong tai nạn, xe đã bị hỏng."],["事故に気をつけてください。","Hãy cẩn thận với tai nạn."],["駅の前で事故がありました。","Trước ga đã xảy ra tai nạn."],["事故のニュースを見ました。","Tôi đã xem tin tức về tai nạn."]]},{"word":"見合い","reading":"みあい","meaning":"nam nữ làm quen qua giới thiệu, làm mối","hanViet":"KIẾN HỢP","lesson":39,"ex":[["姉は見合いをしました。","Chị gái tôi đã đi xem mặt."],["見合いで結婚しました。","Tôi đã kết hôn qua mai mối."],["母は見合いの話をしました。","Mẹ tôi đã nói chuyện mai mối."],["見合いの相手は先生です。","Đối tượng xem mặt là thầy giáo."],["田中さんは見合いをします。","Anh Tanaka sẽ đi xem mặt."]]},{"word":"電話代","reading":"でんわだい","meaning":"Tiền điện thoại","hanViet":"ĐIỆN THOẠI ĐẠI","lesson":39,"ex":[["電話代が高いです。","Tiền điện thoại đắt."],["今月の電話代は5000円です。","Tiền điện thoại tháng này là 5000 yên."],["電話代を払います。","Tôi trả tiền điện thoại."],["電話代が安くなりました。","Tiền điện thoại đã rẻ hơn."],["電話代は母が払います。","Mẹ tôi trả tiền điện thoại."]]},{"word":"～代","reading":"～だい","meaning":"tiền ~, phí ~","hanViet":"ĐẠI","lesson":39,"ex":[["電車代はいくらですか。","Tiền tàu điện bao nhiêu?"],["ガス代を払いました。","Tôi đã trả tiền ga."],["昼ごはん代は1000円でした。","Tiền ăn trưa là 1000 yên."],["バス代が高いです。","Tiền xe buýt đắt."],["タクシー代を払います。","Tôi trả tiền taxi."]]},{"word":"～号室","reading":"～ごうしつ","meaning":"phòng số–","hanViet":"HIỆU THẤT","lesson":39,"ex":[["私の部屋は201号室です。","Phòng của tôi là phòng số 201."],["田中さんは305号室に住んでいます。","Anh Tanaka sống ở phòng số 305."],["会議は101号室であります。","Cuộc họp diễn ra ở phòng số 101."],["502号室の人が来ました。","Người ở phòng số 502 đã đến."],["ホテルの部屋は408号室です。","Phòng khách sạn là phòng số 408."]]},{"word":"汗","reading":"あせ","meaning":"Mồ hôi","hanViet":"HÃN","lesson":39,"ex":[["汗が出ました。","Tôi đã đổ mồ hôi."],["暑い日は汗が出ます。","Ngày nóng tôi đổ mồ hôi."],["汗が出たので、シャツを洗いました。","Tôi đổ mồ hôi nên đã giặt áo sơ mi."],["運動して、汗が出ました。","Tôi vận động nên đã đổ mồ hôi."],["汗をふきました。","Tôi đã lau mồ hôi."]]},{"word":"せっけん","reading":"せっけん","meaning":"xà phòng","hanViet":"","lesson":39,"ex":[["せっけんで手を洗います。","Tôi rửa tay bằng xà phòng."],["せっけんを買いました。","Tôi đã mua xà phòng."],["せっけんのにおいがいいです。","Mùi xà phòng thơm."],["顔をせっけんで洗います。","Tôi rửa mặt bằng xà phòng."],["せっけんがありません。","Không có xà phòng."]]},{"word":"大勢","reading":"おおぜい","meaning":"Đông người","hanViet":"ĐẠI THẾ","lesson":39,"ex":[["公園に大勢の人がいます。","Ở công viên có đông người."],["大勢の学生が集まりました。","Đông học sinh đã tụ họp."],["祭りに大勢の人が来ました。","Lễ hội có đông người đến."],["大勢の友達と遊びました。","Tôi đã chơi với đông bạn bè."],["駅に大勢の人がいました。","Ở ga có đông người."]]},{"word":"お疲れ様でした","reading":"おつかれさまでした","meaning":"chắc anh/chị đã mệt vì làm việc","hanViet":"BÌ DẠNG","lesson":39,"ex":[["お疲れ様でした。あした、また会いましょう。","Anh/chị đã vất vả rồi. Mai gặp lại nhé."],["先生、お疲れ様でした。","Thầy đã vất vả rồi."],["仕事が終わって、「お疲れ様でした」と言いました。","Tan làm, tôi đã nói \"Anh/chị đã vất vả rồi\"."],["お疲れ様でした。ゆっくり休んでください。","Anh/chị đã vất vả rồi. Hãy nghỉ ngơi thoải mái nhé."],["会議が終わって、お疲れ様でした。","Cuộc họp kết thúc, mọi người đã vất vả rồi."]]},{"word":"伺います","reading":"うかがいます","meaning":"tôi đến thăm","hanViet":"TỨ","lesson":39,"ex":[["あした、先生の家に伺います。","Ngày mai tôi sẽ đến thăm nhà thầy giáo."],["3時に会社に伺います。","Lúc 3 giờ tôi sẽ đến thăm công ty."],["来週、お客様の家に伺います。","Tuần sau tôi sẽ đến thăm nhà khách hàng."],["田中さんのうちに伺いました。","Tôi đã đến thăm nhà anh Tanaka."],["あした、伺ってもいいですか。","Ngày mai tôi đến thăm có được không?"]]},{"word":"途中で","reading":"とちゅうで","meaning":"giữa đường, giữa chừng","hanViet":"ĐỒ TRUNG","lesson":39,"ex":[["学校への途中で、友達に会いました。","Giữa đường đến trường, tôi đã gặp bạn."],["途中で雨が降ってきました。","Giữa đường trời bắt đầu mưa."],["話の途中で、電話が鳴りました。","Đang nói chuyện giữa chừng thì điện thoại reo."],["途中でバスを降りました。","Giữa đường tôi đã xuống xe buýt."],["途中で本を読むのをやめました。","Đang đọc giữa chừng thì tôi bỏ dở quyển sách."]]},{"word":"ぶつかります","reading":"ぶつかります","meaning":"đâm, va chạm","hanViet":"","lesson":39,"ex":[["車が木にぶつかりました。","Xe đã đâm vào cây."],["自転車にぶつかりました。","Tôi đã va chạm với xe đạp."],["暗い道で人にぶつかりました。","Trên đường tối, tôi đã va phải người."],["子どもがドアにぶつかりました。","Đứa trẻ đã đâm vào cửa."],["頭が壁にぶつかりました。","Đầu tôi đã đập vào tường."]]},{"word":"並びます","reading":"ならびます","meaning":"xếp hàng","hanViet":"TỊNH","lesson":39,"ex":[["店の前で並びます。","Tôi xếp hàng trước cửa hàng."],["大勢の人が並んでいます。","Đông người đang xếp hàng."],["切符を買うために、並びました。","Tôi đã xếp hàng để mua vé."],["バス停で並びます。","Tôi xếp hàng ở trạm xe buýt."],["レストランの前で30分並びました。","Tôi đã xếp hàng 30 phút trước nhà hàng."]]},{"word":"大人","reading":"おとな","meaning":"người lớn","hanViet":"ĐẠI NHÂN","lesson":39,"ex":[["大人になりました。","Tôi đã trở thành người lớn."],["大人は子どもの世話をします。","Người lớn chăm sóc trẻ con."],["大人が5人います。","Có 5 người lớn."],["大人でも、子どもでも楽しめます。","Cả người lớn lẫn trẻ con đều vui được."],["大人の服を買いました。","Tôi đã mua quần áo người lớn."]]},{"word":"洋服","reading":"ようふく","meaning":"Quần áo kiểu Tây","hanViet":"DƯƠNG PHỤC","lesson":39,"ex":[["洋服を買いました。","Tôi đã mua quần áo kiểu Tây."],["洋服を着ています。","Tôi đang mặc quần áo kiểu Tây."],["新しい洋服を買いたいです。","Tôi muốn mua quần áo kiểu Tây mới."],["デパートで洋服を買いました。","Tôi đã mua quần áo kiểu Tây ở trung tâm thương mại."],["洋服を洗濯します。","Tôi giặt quần áo kiểu Tây."]]},{"word":"西洋化します","reading":"せいようかします","meaning":"tây âu hóa","hanViet":"TÂY DƯƠNG HÓA","lesson":39,"ex":[["日本の生活は西洋化しました。","Cuộc sống ở Nhật đã tây âu hóa."],["この町は西洋化しています。","Thị trấn này đang tây âu hóa."],["日本の家は西洋化しました。","Nhà ở Nhật đã tây âu hóa."],["若い人の生活は西洋化しています。","Cuộc sống của người trẻ đang tây âu hóa."],["食べ物も西洋化しています。","Đồ ăn cũng đang tây âu hóa."]]},{"word":"合います","reading":"あいます","meaning":"vừa, hợp","hanViet":"HỢP","lesson":39,"ex":[["この靴は私に合います。","Đôi giày này vừa với tôi."],["このシャツは田中さんに合います。","Chiếc áo sơ mi này hợp với anh Tanaka."],["この帽子は母に合いますか。","Chiếc mũ này có hợp với mẹ tôi không?"],["このズボンは私に合いません。","Chiếc quần này không vừa với tôi."],["この眼鏡は山田さんによく合います。","Chiếc kính này rất hợp với anh Yamada."]]},{"word":"今では","reading":"いまでは","meaning":"bây giờ (thì)","hanViet":"KIM","lesson":39,"ex":[["今では日本語が話せます。","Bây giờ thì tôi nói được tiếng Nhật."],["今では毎朝走っています。","Bây giờ thì tôi chạy bộ mỗi sáng."],["今では一人で料理ができます。","Bây giờ thì tôi nấu ăn một mình được."],["今では東京に住んでいます。","Bây giờ thì tôi sống ở Tokyo."],["今ではパソコンを使います。","Bây giờ thì tôi dùng máy tính."]]},{"word":"成人式","reading":"せいじんしき","meaning":"lễ trưởng thành, lễ thành nhân","hanViet":"THÀNH NHÂN THỨC","lesson":39,"ex":[["妹は今年成人式に出ます。","Em gái tôi năm nay dự lễ trưởng thành."],["成人式は1月にあります。","Lễ trưởng thành diễn ra vào tháng 1."],["成人式で着物を着ました。","Tôi đã mặc kimono ở lễ trưởng thành."],["友達は成人式の写真を見せました。","Bạn tôi đã cho tôi xem ảnh lễ trưởng thành."],["成人式の日はとても寒かったです。","Ngày lễ trưởng thành rất lạnh."]]},{"word":"うらやましい","reading":"うらやましい","meaning":"đáng ghen tị","hanViet":"","lesson":39,"ex":[["山田さんの新しい車がうらやましいです。","Tôi ghen tị với chiếc xe mới của anh Yamada."],["田中さんの旅行がうらやましいです。","Tôi ghen tị với chuyến du lịch của anh Tanaka."],["田中さんの日本語がうらやましいです。","Tôi ghen tị với tiếng Nhật của anh Tanaka."],["友達の大きい家がうらやましいです。","Tôi ghen tị với ngôi nhà lớn của bạn tôi."],["弟の新しいパソコンがうらやましいです。","Tôi ghen tị với chiếc máy tính mới của em trai tôi."]]},{"word":"懐かしい","reading":"なつかしい","meaning":"hoài niệm, gợi nhớ, thân thương","hanViet":"HOÀI","lesson":39,"ex":[["この歌は懐かしいです。","Bài hát này gợi nhớ nhiều kỷ niệm."],["子どものときの写真は懐かしいです。","Ảnh hồi nhỏ gợi nhớ nhiều kỷ niệm."],["昔の学校が懐かしいです。","Ngôi trường ngày xưa khiến tôi nhớ nhung."],["母の料理が懐かしいです。","Món ăn của mẹ khiến tôi nhớ nhung."],["この町の景色は懐かしいです。","Phong cảnh thị trấn này gợi nhớ nhiều kỷ niệm."]]},{"word":"うっとりします","reading":"うっとりします","meaning":"mải mê, bị hút vào","hanViet":"","lesson":39,"ex":[["美しい歌にうっとりしました。","Tôi mải mê nghe bài hát hay."],["海の景色にうっとりしました。","Tôi mải mê ngắm cảnh biển."],["きれいな花にうっとりしました。","Tôi mải mê ngắm những bông hoa đẹp."],["月を見て、うっとりしました。","Tôi mải mê ngắm mặt trăng."],["先生の話にうっとりしました。","Tôi mải mê nghe thầy giáo kể chuyện."]]},{"word":"いらいらします","reading":"いらいらします","meaning":"nóng ruột, thiếu kiên nhẫn","hanViet":"","lesson":39,"ex":[["電車が来ないから、いらいらします。","Tàu điện mãi không đến nên tôi nóng ruột."],["友達が遅いから、いらいらしました。","Bạn tôi đến muộn nên tôi nóng ruột."],["仕事が終わらないから、いらいらします。","Công việc mãi không xong nên tôi nóng ruột."],["弟は宿題をしないから、母はいらいらしました。","Em trai không làm bài tập nên mẹ tôi nóng ruột."],["バスが来ないから、いらいらしています。","Xe buýt mãi không đến nên tôi đang nóng ruột."]]},{"word":"どきどきします","reading":"どきどきします","meaning":"hồi hộp, run","hanViet":"","lesson":39,"ex":[["試験の前にどきどきしました。","Trước kỳ thi tôi hồi hộp."],["先生の前で話すとき、どきどきします。","Khi nói trước thầy giáo, tôi hồi hộp."],["飛行機に乗るとき、どきどきします。","Khi lên máy bay, tôi hồi hộp."],["友達に会う前にどきどきしました。","Trước khi gặp bạn, tôi hồi hộp."],["初めてのデートの前にどきどきしました。","Trước buổi hẹn đầu tiên, tôi hồi hộp."]]},{"word":"はらはらします","reading":"はらはらします","meaning":"hồi hộp, thót tim","hanViet":"","lesson":39,"ex":[["サッカーの試合を見て、はらはらしました。","Xem trận bóng đá, tôi thót tim."],["子どもが木に登るとき、はらはらしました。","Khi đứa trẻ trèo cây, tôi thót tim."],["兄が車を運転するとき、はらはらしました。","Khi anh trai lái xe, tôi thót tim."],["弟が自転車に乗るとき、はらはらしました。","Khi em trai đi xe đạp, tôi thót tim."],["高い所に立つと、はらはらします。","Đứng ở chỗ cao, tôi thót tim."]]},{"word":"わくわくします","reading":"わくわくします","meaning":"ngóng đợi, nóng lòng","hanViet":"","lesson":39,"ex":[["明日の旅行が楽しみで、わくわくします。","Mong chờ chuyến du lịch ngày mai, tôi nóng lòng."],["旅行の前はわくわくします。","Trước chuyến du lịch, tôi nóng lòng."],["新しい学校に行く前はわくわくしました。","Trước khi đến trường mới, tôi nóng lòng."],["誕生日の前はわくわくします。","Trước sinh nhật, tôi nóng lòng."],["映画が始まるまで待って、わくわくしました。","Chờ phim bắt đầu, tôi nóng lòng."]]},{"word":"フロント","reading":"フロント","meaning":"bộ phận tiếp tân","hanViet":"","lesson":39,"ex":[["ホテルのフロントで鍵をもらいました。","Tôi đã nhận chìa khóa ở quầy tiếp tân khách sạn."],["フロントでタオルを借りました。","Tôi đã mượn khăn ở quầy tiếp tân."],["フロントに電話をしました。","Tôi đã gọi điện đến quầy tiếp tân."],["フロントの人が荷物を持ってくれました。","Nhân viên tiếp tân đã mang hành lý giúp tôi."],["フロントで部屋の鍵を返しました。","Tôi đã trả chìa khóa phòng ở quầy tiếp tân."]]},{"word":"タオル","reading":"タオル","meaning":"khăn lau, khăn tắm","hanViet":"","lesson":39,"ex":[["お風呂のあとでタオルを使います。","Sau khi tắm, tôi dùng khăn."],["新しいタオルを買いました。","Tôi đã mua khăn mới."],["タオルで顔をふきました。","Tôi đã lau mặt bằng khăn."],["プールでタオルを忘れました。","Tôi đã quên khăn ở bể bơi."],["白いタオルを二枚買いました。","Tôi đã mua hai chiếc khăn trắng."]]},{"word":"痩せます","reading":"やせます","meaning":"gầy đi, giảm cân","hanViet":"SẨU","lesson":39,"ex":[["毎日走って、痩せました。","Tôi chạy bộ mỗi ngày nên đã gầy đi."],["妹は少し痩せました。","Em gái tôi đã gầy đi một chút."],["野菜を食べて、痩せたいです。","Tôi muốn ăn rau để gầy đi."],["病気で痩せました。","Tôi bị ốm nên đã gầy đi."],["毎日泳いで、痩せました。","Tôi bơi mỗi ngày nên đã gầy đi."]]},{"word":"首相","reading":"しゅしょう","meaning":"Thủ tướng","hanViet":"THỦ TƯỚNG","lesson":39,"ex":[["首相はテレビで話しました。","Thủ tướng đã phát biểu trên truyền hình."],["首相は外国へ行きました。","Thủ tướng đã đi nước ngoài."],["首相が変わりました。","Thủ tướng đã thay đổi."],["首相は会議に出ました。","Thủ tướng đã dự hội nghị."],["首相の話をニュースで聞きました。","Tôi đã nghe bài phát biểu của Thủ tướng trên tin tức."]]},{"word":"津波","reading":"つなみ","meaning":"Sóng thần","hanViet":"TÂN BA","lesson":39,"ex":[["地震のあとで津波が来ました。","Sau trận động đất, sóng thần đã đến."],["津波で家が壊れました。","Sóng thần đã phá hủy nhà cửa."],["津波のニュースを見ました。","Tôi đã xem tin tức về sóng thần."],["海の近くは津波が危険です。","Gần biển thì sóng thần rất nguy hiểm."],["津波が来たら、高い所へ逃げます。","Nếu sóng thần đến, hãy chạy lên chỗ cao."]]},{"word":"会場","reading":"かいじょう","meaning":"Địa điểm tổ chức, hội trường","hanViet":"HỘI TRƯỜNG","lesson":39,"ex":[["会場は駅の近くです。","Hội trường ở gần ga."],["会場に人がたくさん集まりました。","Nhiều người đã tập trung ở hội trường."],["結婚式の会場はホテルです。","Địa điểm tổ chức đám cưới là khách sạn."],["会場で音楽を聞きました。","Tôi đã nghe nhạc ở hội trường."],["会場は9時に開きます。","Hội trường mở cửa lúc 9 giờ."]]},{"word":"～屋","reading":"～や","meaning":"tiệm~, quầy~, người bán ~","hanViet":"ỐC","lesson":39,"ex":[["駅の前にパン屋があります。","Trước ga có tiệm bánh mì."],["本屋で辞書を買いました。","Tôi đã mua từ điển ở hiệu sách."],["花屋で花を買いました。","Tôi đã mua hoa ở tiệm hoa."],["肉屋は日曜日に休みます。","Tiệm thịt nghỉ vào chủ nhật."],["魚屋で魚を買いました。","Tôi đã mua cá ở tiệm cá."]]},{"word":"しかし","reading":"しかし","meaning":"nhưng","hanViet":"","lesson":39,"ex":[["雨が降りました。しかし、試合はありました。","Trời đã mưa. Nhưng trận đấu vẫn diễn ra."],["日本語は難しいです。しかし、楽しいです。","Tiếng Nhật khó. Nhưng rất thú vị."],["彼は忙しいです。しかし、いつも手伝います。","Anh ấy bận. Nhưng lúc nào cũng giúp đỡ."],["この本は高いです。しかし、とてもいい本です。","Cuốn sách này đắt. Nhưng là cuốn sách rất hay."],["電車は遅れました。しかし、時間に間に合いました。","Tàu điện đến muộn. Nhưng tôi vẫn kịp giờ."]]},{"word":"伝統的な","reading":"でんとうてきな","meaning":"mang tính truyền thống","hanViet":"TRUYỀN THỐNG ĐÍCH","lesson":39,"ex":[["京都には伝統的な建物があります。","Ở Kyoto có những tòa nhà mang tính truyền thống."],["この町は伝統的な祭りで有名です。","Thị trấn này nổi tiếng với lễ hội truyền thống."],["伝統的な日本の家に住みたいです。","Tôi muốn sống trong ngôi nhà truyền thống của Nhật."],["この料理は伝統的な味です。","Món ăn này có hương vị truyền thống."],["伝統的な着物を着ました。","Tôi đã mặc kimono truyền thống."]]},{"word":"数えます","reading":"かぞえます","meaning":"đếm","hanViet":"SỐ","lesson":40,"ex":[["子どもを数えました。","Tôi đã đếm số trẻ em."],["お金を数えました。","Tôi đã đếm tiền."],["りんごを数えてください。","Hãy đếm số táo giúp tôi."],["教室の学生を数えました。","Tôi đã đếm học sinh trong lớp học."],["星を数えました。","Tôi đã đếm sao."]]},{"word":"測ります","reading":"はかります","meaning":"đo, cân","hanViet":"TRẮC","lesson":40,"ex":[["自分の重さを測ります。","Tôi cân trọng lượng của mình."],["紙の長さを測りました。","Tôi đã đo chiều dài tờ giấy."],["箱の高さを測りました。","Tôi đã đo chiều cao của chiếc hộp."],["子どもの重さを測りました。","Tôi đã cân trọng lượng của đứa trẻ."],["荷物の重さを測ってください。","Hãy cân trọng lượng hành lý giúp tôi."]]},{"word":"確かめます","reading":"たしかめます","meaning":"xác nhận","hanViet":"XÁC","lesson":40,"ex":[["電車の時間を確かめました。","Tôi đã xác nhận giờ tàu điện."],["電話番号を確かめました。","Tôi đã xác nhận số điện thoại."],["財布の中を確かめました。","Tôi đã kiểm tra bên trong ví."],["宿題を確かめました。","Tôi đã kiểm tra bài tập về nhà."],["試験の日を確かめました。","Tôi đã xác nhận ngày thi."]]},{"word":"出発します","reading":"しゅっぱつします","meaning":"xuất phát, khởi hành","hanViet":"XUẤT PHÁT","lesson":40,"ex":[["バスは9時に出発します。","Xe buýt xuất phát lúc 9 giờ."],["明日、東京へ出発します。","Ngày mai tôi xuất phát đi Tokyo."],["飛行機は10時に出発しました。","Máy bay đã cất cánh lúc 10 giờ."],["家を7時に出発しました。","Tôi đã rời nhà lúc 7 giờ."],["旅行に出発する前に、荷物を確かめました。","Trước khi xuất phát đi du lịch, tôi đã kiểm tra hành lý."]]},{"word":"到着します","reading":"とうちゃくします","meaning":"đến, đến nơi","hanViet":"ĐÁO TRƯỚC","lesson":40,"ex":[["電車は10時に到着します。","Tàu điện đến nơi lúc 10 giờ."],["飛行機は京都に到着しました。","Máy bay đã đến Kyoto."],["明日、東京に到着します。","Ngày mai tôi sẽ đến Tokyo."],["バスは駅に到着しました。","Xe buýt đã đến ga."],["荷物はきのう到着しました。","Hành lý đã đến hôm qua."]]},{"word":"酔います","reading":"よいます","meaning":"say","hanViet":"TÚY","lesson":40,"ex":[["ビールを飲んで、酔いました。","Tôi uống bia nên đã say."],["酒を飲むと、すぐ酔います。","Uống rượu là tôi say ngay."],["車に乗ると、酔います。","Đi ô tô là tôi say xe."],["船に乗って、酔いました。","Tôi đi tàu nên đã say sóng."],["父はビールを三杯飲んで、酔いました。","Bố tôi uống ba cốc bia nên đã say."]]},{"word":"危険","reading":"きけん","meaning":"Nguy hiểm","hanViet":"NGUY HIỂM","lesson":40,"ex":[["ここは車が多くて、危険です。","Ở đây nhiều xe nên nguy hiểm."],["夜、一人で歩くことは危険です。","Ban đêm đi bộ một mình rất nguy hiểm."],["この川で泳ぐことは危険です。","Bơi ở con sông này rất nguy hiểm."],["危険な所には行かないでください。","Đừng đến chỗ nguy hiểm."],["子どもが道で遊ぶことは危険です。","Trẻ em chơi ngoài đường rất nguy hiểm."]]},{"word":"必要","reading":"ひつよう","meaning":"cần thiết","hanViet":"TẤT YẾU","lesson":40,"ex":[["日本語の勉強には辞書が必要です。","Học tiếng Nhật cần có từ điển."],["旅行にはお金が必要です。","Đi du lịch cần có tiền."],["この仕事にはパソコンが必要です。","Công việc này cần có máy tính."],["健康には野菜が必要です。","Sức khỏe cần có rau xanh."],["試験には鉛筆が必要です。","Thi cử cần có bút chì."]]},{"word":"忘年会","reading":"ぼうねんかい","meaning":"Tiệc tất niên","hanViet":"VONG NIÊN HỘI","lesson":40,"ex":[["忘年会は12月にあります。","Tiệc tất niên diễn ra vào tháng 12."],["会社の忘年会に出ました。","Tôi đã dự tiệc tất niên của công ty."],["忘年会で歌を歌いました。","Tôi đã hát ở tiệc tất niên."],["忘年会はレストランでありました。","Tiệc tất niên được tổ chức ở nhà hàng."],["友達と忘年会をしました。","Tôi đã tổ chức tiệc tất niên với bạn bè."]]},{"word":"新年会","reading":"しんねんかい","meaning":"tiệc tân niên","hanViet":"TÂN NIÊN HỘI","lesson":40,"ex":[["新年会は1月にあります。","Tiệc tân niên diễn ra vào tháng 1."],["新年会で今年のことを話しました。","Ở tiệc tân niên, tôi đã nói về chuyện năm nay."],["会社の新年会に出ました。","Tôi đã dự tiệc tân niên của công ty."],["新年会はホテルでありました。","Tiệc tân niên được tổ chức ở khách sạn."],["新年会で友達に会いました。","Tôi đã gặp bạn bè ở tiệc tân niên."]]},{"word":"二次会","reading":"にじかい","meaning":"bữa tiệc thứ hai, tăng hai","hanViet":"NHỊ THỨ HỘI","lesson":40,"ex":[["忘年会のあとで二次会に行きました。","Sau tiệc tất niên, tôi đã đi tăng hai."],["二次会はカラオケでした。","Tăng hai là đi hát karaoke."],["結婚式の二次会に出ました。","Tôi đã dự tăng hai sau đám cưới."],["二次会で歌を歌いました。","Tôi đã hát ở tăng hai."],["二次会は11時に終わりました。","Tăng hai kết thúc lúc 11 giờ."]]},{"word":"大会","reading":"たいかい","meaning":"đại hội, cuộc thi","hanViet":"ĐẠI HỘI","lesson":40,"ex":[["サッカーの大会に出ました。","Tôi đã tham gia giải bóng đá."],["大会は来月あります。","Giải đấu sẽ diễn ra vào tháng sau."],["歌の大会で1番になりました。","Tôi đã đứng nhất cuộc thi hát."],["大会の会場は体育館です。","Địa điểm tổ chức giải đấu là nhà thi đấu."],["テニスの大会を見ました。","Tôi đã xem giải quần vợt."]]},{"word":"表","reading":"おもて","meaning":"mặt ngoài, bề mặt","hanViet":"BIỂU","lesson":40,"ex":[["表に名前を書いてください。","Hãy viết tên ở mặt ngoài."],["この紙の表を見てください。","Hãy xem mặt ngoài của tờ giấy này."],["コートの表は青いです。","Mặt ngoài của áo khoác màu xanh."],["表に住所を書きました。","Tôi đã viết địa chỉ ở mặt ngoài."],["このシャツの表は白いです。","Mặt ngoài của chiếc áo này màu trắng."]]},{"word":"裏","reading":"うら","meaning":"Mặt sau, phía sau","hanViet":"LÝ","lesson":40,"ex":[["裏に名前を書いてください。","Hãy viết tên ở mặt sau."],["紙の裏に絵を書きました。","Tôi đã vẽ tranh ở mặt sau tờ giấy."],["家の裏に庭があります。","Sau nhà có vườn."],["学校の裏に公園があります。","Sau trường có công viên."],["この写真の裏に住所を書きました。","Tôi đã viết địa chỉ ở mặt sau tấm ảnh này."]]},{"word":"申し込み","reading":"もうしこみ","meaning":"đăng ký","hanViet":"THÂN","lesson":40,"ex":[["申し込みは明日までです。","Đăng ký đến hết ngày mai."],["試験の申し込みをしました。","Tôi đã đăng ký thi."],["申し込みの紙を出しました。","Tôi đã nộp giấy đăng ký."],["旅行の申し込みをしました。","Tôi đã đăng ký đi du lịch."],["申し込みはフロントでできます。","Có thể đăng ký ở quầy tiếp tân."]]},{"word":"本当","reading":"ほんとう","meaning":"Thật, sự thật","hanViet":"BẢN ĐƯƠNG","lesson":40,"ex":[["本当ですか。","Thật không?"],["それは本当の話です。","Đó là câu chuyện có thật."],["本当のことを言ってください。","Hãy nói sự thật."],["彼は本当に忙しいです。","Anh ấy thực sự rất bận."],["本当は日本語が好きです。","Thực ra tôi thích tiếng Nhật."]]},{"word":"間違い","reading":"まちがい","meaning":"Sai sót, nhầm lẫn","hanViet":"GIAN VI","lesson":40,"ex":[["間違いがありました。","Đã có sai sót."],["間違いが三つありました。","Đã có ba lỗi sai."],["間違いを直しました。","Tôi đã sửa lỗi sai."],["電話番号の間違いがありました。","Đã có nhầm lẫn về số điện thoại."],["間違いがないか確かめました。","Tôi đã xác nhận xem có sai sót không."]]},{"word":"傷","reading":"きず","meaning":"vết thương","hanViet":"THƯƠNG","lesson":40,"ex":[["足に傷があります。","Chân tôi có vết thương."],["傷がまだ治りません。","Vết thương vẫn chưa lành."],["手に小さい傷があります。","Tay tôi có vết thương nhỏ."],["自転車から落ちて、傷ができました。","Tôi ngã xe đạp nên bị thương."],["傷に薬をつけました。","Tôi đã bôi thuốc vào vết thương."]]},{"word":"長さ","reading":"ながさ","meaning":"chiều dài","hanViet":"TRƯỜNG","lesson":40,"ex":[["部屋の長さを測りました。","Tôi đã đo chiều dài căn phòng."],["川の長さを調べました。","Tôi đã tìm hiểu chiều dài con sông."],["長さが違います。","Chiều dài khác nhau."],["このひもは長さがちょうどいいです。","Sợi dây này có độ dài vừa phải."],["机の長さを測ってください。","Hãy đo chiều dài cái bàn giúp tôi."]]},{"word":"重さ","reading":"おもさ","meaning":"cân nặng, trọng lượng","hanViet":"TRỌNG","lesson":40,"ex":[["このかばんの重さを測りました。","Tôi đã cân trọng lượng chiếc cặp này."],["重さを測ってください。","Hãy cân trọng lượng giúp tôi."],["赤ちゃんの重さが増えました。","Cân nặng của em bé đã tăng lên."],["二つのかばんの重さは同じです。","Trọng lượng của hai chiếc cặp bằng nhau."],["重さが違います。","Trọng lượng khác nhau."]]},{"word":"高さ","reading":"たかさ","meaning":"chiều cao","hanViet":"CAO","lesson":40,"ex":[["ビルの高さを測りました。","Tôi đã đo chiều cao tòa nhà."],["山の高さを調べました。","Tôi đã tìm hiểu chiều cao ngọn núi."],["机の高さを測りました。","Tôi đã đo chiều cao của cái bàn."],["高さが違います。","Chiều cao khác nhau."],["木の高さを測ってください。","Hãy đo chiều cao của cây giúp tôi."]]},{"word":"大きさ","reading":"おおきさ","meaning":"cỡ, kích thước","hanViet":"ĐẠI","lesson":40,"ex":[["二つの箱の大きさは同じです。","Hai chiếc hộp này cùng cỡ."],["大きさを確かめました。","Tôi đã xác nhận kích thước."],["魚の大きさを測りました。","Tôi đã đo cỡ con cá."],["部屋の大きさが違います。","Kích thước phòng khác nhau."],["このケーキの大きさはちょうどいいです。","Chiếc bánh này vừa cỡ."]]},{"word":"～便","reading":"～びん","meaning":"chuyến bay–","hanViet":"TIỆN","lesson":40,"ex":[["明日の朝の便で東京へ行きます。","Tôi đi Tokyo bằng chuyến bay sáng mai."],["電話で便を確かめました。","Tôi đã xác nhận chuyến bay qua điện thoại."],["午後の便で京都へ行きます。","Tôi đi Kyoto bằng chuyến bay buổi chiều."],["便が遅れました。","Chuyến bay đã bị hoãn."],["夜の便で京都へ行きます。","Tôi đi Kyoto bằng chuyến bay buổi tối."]]},{"word":"～号","reading":"～ごう","meaning":"số–","hanViet":"HIỆU","lesson":40,"ex":[["私の部屋は305号です。","Phòng của tôi là số 305."],["3号の電車に乗りました。","Tôi đã lên tàu điện số 3."],["新幹線の5号に乗りました。","Tôi đã lên tàu Shinkansen số 5."],["このバスは3号です。","Xe buýt này là số 3."],["10号の部屋に住んでいます。","Tôi sống ở phòng số 10."]]},{"word":"～個","reading":"～こ","meaning":"cái, cục, viên","hanViet":"CÁ","lesson":40,"ex":[["りんごを3個買いました。","Tôi đã mua 3 quả táo."],["ケーキを2個食べました。","Tôi đã ăn 2 miếng bánh."],["みかんを5個ください。","Cho tôi 5 quả quýt."],["卵を10個買いました。","Tôi đã mua 10 quả trứng."],["チョコレートを1個食べました。","Tôi đã ăn 1 viên sô cô la."]]},{"word":"～本","reading":"～ほん、～ぽん、～ぼん","meaning":"cái (đơn vị đếm vật dài)","hanViet":"BẢN","lesson":40,"ex":[["ビールを3本飲みました。","Tôi đã uống 3 chai bia."],["鉛筆を5本持っています。","Tôi có 5 cây bút chì."],["花を10本買いました。","Tôi đã mua 10 bông hoa."],["傘を1本買いました。","Tôi đã mua 1 chiếc ô."],["ジュースを2本買いました。","Tôi đã mua 2 chai nước trái cây."]]},{"word":"～杯","reading":"～はい、～ぱい、～ばい","meaning":"–chén, –cốc","hanViet":"BÔI","lesson":40,"ex":[["コーヒーを2杯飲みました。","Tôi đã uống 2 cốc cà phê."],["お茶を1杯ください。","Cho tôi 1 cốc trà."],["ビールを3杯飲みました。","Tôi đã uống 3 cốc bia."],["ごはんを2杯食べました。","Tôi đã ăn 2 bát cơm."],["ジュースを1杯飲みました。","Tôi đã uống 1 cốc nước trái cây."]]},{"word":"～以上","reading":"～いじょう","meaning":"trở lên, trên","hanViet":"DĨ THƯỢNG","lesson":40,"ex":[["20歳以上の人が酒を飲めます。","Người từ 20 tuổi trở lên được uống rượu."],["18歳以上は大人です。","Từ 18 tuổi trở lên là người lớn."],["3人以上で来てください。","Hãy đến từ 3 người trở lên."],["60点以上はいい成績です。","Từ 60 điểm trở lên là thành tích tốt."],["10個以上買うと、安くなります。","Mua từ 10 cái trở lên thì rẻ hơn."]]},{"word":"～以下","reading":"～いか","meaning":"trở xuống, dưới","hanViet":"DĨ HẠ","lesson":40,"ex":[["18歳以下の子どもは入れません。","Trẻ em dưới 18 tuổi không được vào."],["10歳以下の子どもは無料です。","Trẻ em từ 10 tuổi trở xuống được miễn phí."],["100円以下のお菓子を買いました。","Tôi đã mua bánh kẹo dưới 100 yên."],["2人以下で来てください。","Hãy đến tối đa 2 người."],["60点以下はいい成績ではありません。","Dưới 60 điểm thì không phải thành tích tốt."]]},{"word":"さあ","reading":"さあ","meaning":"à.., ồ..,(dùng khi không rõ về điều gì đó)","hanViet":"","lesson":40,"ex":[["「あしたは雨ですか。」「さあ、わかりません。」","Ngày mai có mưa không? À, tôi không biết."],["「山田さんは来ますか。」「さあ、わかりません。」","Anh Yamada có đến không? À, tôi không biết."],["「試験はいつですか。」「さあ、知りません。」","Khi nào thi? À, tôi không biết."],["「この本はいくらですか。」「さあ、わかりません。」","Cuốn sách này bao nhiêu tiền? À, tôi không biết."],["「田中さんはどこですか。」「さあ、わかりません。」","Anh Tanaka ở đâu? À, tôi không biết."]]},{"word":"どうでしょうか","reading":"どうでしょうか","meaning":"thế nào? (cách nói lịch sự của どうですか)","hanViet":"","lesson":40,"ex":[["このシャツはどうでしょうか。","Chiếc áo sơ mi này thế nào?"],["来週の旅行はどうでしょうか。","Chuyến du lịch tuần sau thế nào?"],["この本はどうでしょうか。","Cuốn sách này thế nào?"],["明日の天気はどうでしょうか。","Thời tiết ngày mai thế nào?"],["この料理はどうでしょうか。","Món ăn này thế nào?"]]},{"word":"成績","reading":"せいせき","meaning":"Thành tích, điểm số, kết quả học tập","hanViet":"THÀNH TÍCH","lesson":40,"ex":[["成績がよくなりました。","Thành tích học tập của tôi đã tốt lên."],["日本語の成績がいいです。","Điểm tiếng Nhật của tôi tốt."],["成績を確かめました。","Tôi đã kiểm tra điểm số."],["弟の成績はよくありません。","Thành tích học tập của em trai tôi không tốt."],["成績が上がりました。","Điểm số của tôi đã tăng lên."]]},{"word":"ところで","reading":"ところで","meaning":"nhân tiện","hanViet":"","lesson":40,"ex":[["ところで、明日の会議は何時ですか。","Nhân tiện, cuộc họp ngày mai mấy giờ?"],["ところで、田中さんは元気ですか。","Nhân tiện, anh Tanaka có khỏe không?"],["ところで、試験はいつですか。","Nhân tiện, khi nào thi?"],["ところで、来週の旅行はどうですか。","Nhân tiện, chuyến du lịch tuần sau thế nào?"],["ところで、新しい仕事はどうですか。","Nhân tiện, công việc mới thế nào?"]]},{"word":"様子","reading":"ようす","meaning":"vẻ, tình hình","hanViet":"DẠNG TỬ","lesson":40,"ex":[["子どもの様子を見ました。","Tôi đã xem tình hình của đứa trẻ."],["天気の様子を見ました。","Tôi đã xem tình hình thời tiết."],["母の様子が心配です。","Tôi lo lắng về tình hình của mẹ."],["仕事の様子を聞きました。","Tôi đã hỏi về tình hình công việc."],["様子がおかしいです。","Tình hình có vẻ lạ."]]},{"word":"事件","reading":"じけん","meaning":"sự việc, vụ án","hanViet":"SỰ KIỆN","lesson":40,"ex":[["事件が起きました。","Đã xảy ra một vụ việc."],["事件のニュースを見ました。","Tôi đã xem tin tức về vụ án."],["きのうの事件をテレビで見ました。","Tôi đã xem vụ án hôm qua trên truyền hình."],["警察が事件を調べています。","Cảnh sát đang điều tra vụ án."],["大きな事件がありました。","Đã có một vụ án lớn."]]},{"word":"爆弾","reading":"ばくだん","meaning":"Bom","hanViet":"BẠO ĐẠN","lesson":40,"ex":[["爆弾が見つかりました。","Đã tìm thấy một quả bom."],["爆弾のニュースを見ました。","Tôi đã xem tin tức về quả bom."],["警察が爆弾を調べました。","Cảnh sát đã kiểm tra quả bom."],["古い爆弾が見つかりました。","Đã tìm thấy một quả bom cũ."],["爆弾は危険です。","Bom rất nguy hiểm."]]},{"word":"積みます","reading":"つみます","meaning":"chuyển lên, xếp hàng lên","hanViet":"TÍCH","lesson":40,"ex":[["荷物を車に積みました。","Tôi đã xếp hành lý lên xe."],["本を箱に積みました。","Tôi đã xếp sách vào hộp."],["野菜を車に積みました。","Tôi đã xếp rau lên xe."],["荷物を船に積みます。","Tôi xếp hành lý lên tàu."],["箱を車に積みました。","Tôi đã xếp hộp lên xe."]]},{"word":"運転手","reading":"うんてんしゅ","meaning":"Tài xế","hanViet":"VẬN CHUYỂN THỦ","lesson":40,"ex":[["運転手はバスを運転します。","Tài xế lái xe buýt."],["タクシーの運転手に道を聞きました。","Tôi đã hỏi đường tài xế taxi."],["運転手は親切です。","Tài xế rất tốt bụng."],["兄は車の運転手です。","Anh trai tôi là tài xế ô tô."],["運転手が荷物を運びました。","Tài xế đã vận chuyển hành lý."]]},{"word":"離れた","reading":"はなれた","meaning":"xa cách, xa","hanViet":"LY","lesson":40,"ex":[["離れた所に学校があります。","Ở chỗ xa có trường học."],["駅から離れた所に住んでいます。","Tôi sống ở chỗ xa ga."],["離れた島に行きました。","Tôi đã đến hòn đảo xa."],["会社から離れた所に家があります。","Nhà tôi ở chỗ xa công ty."],["離れた町に友達がいます。","Ở thị trấn xa có bạn tôi."]]},{"word":"急に","reading":"きゅうに","meaning":"Đột ngột, bất ngờ","hanViet":"CẤP","lesson":40,"ex":[["急に雨が降りました。","Trời đột ngột đổ mưa."],["急に寒くなりました。","Trời đột ngột trở lạnh."],["急に電話が来ました。","Đột ngột có điện thoại gọi đến."],["急に仕事が忙しくなりました。","Công việc đột ngột trở nên bận rộn."],["急に電車が止まりました。","Tàu điện đột ngột dừng lại."]]},{"word":"動かします","reading":"うごかします","meaning":"di chuyển (vật gì đó); vận hành (máy móc)","hanViet":"ĐỘNG","lesson":40,"ex":[["机を動かしました。","Tôi đã di chuyển cái bàn."],["車を少し動かしました。","Tôi đã di chuyển xe một chút."],["機械を動かします。","Tôi vận hành máy móc."],["いすを動かしてください。","Hãy di chuyển ghế giúp tôi."],["荷物を動かしました。","Tôi đã di chuyển hành lý."]]},{"word":"犯人","reading":"はんにん","meaning":"Thủ phạm, tội phạm","hanViet":"PHẠM NHÂN","lesson":40,"ex":[["警察が犯人を見つけました。","Cảnh sát đã tìm ra thủ phạm."],["犯人は逃げました。","Thủ phạm đã bỏ trốn."],["犯人はまだ逃げています。","Thủ phạm vẫn đang bỏ trốn."],["犯人はまだ見つかりません。","Vẫn chưa tìm thấy thủ phạm."],["事件の犯人はだれですか。","Thủ phạm của vụ án là ai?"]]},{"word":"手に入れます","reading":"てにいれます","meaning":"có được, lấy được, đoạt được","hanViet":"THỦ NHẬP","lesson":40,"ex":[["新しい本を手に入れました。","Tôi đã có được cuốn sách mới."],["いい仕事を手に入れました。","Tôi đã có được công việc tốt."],["チケットを手に入れました。","Tôi đã có được vé."],["古い切手を手に入れました。","Tôi đã có được con tem cũ."],["ほしい物を手に入れました。","Tôi đã có được thứ mình muốn."]]},{"word":"今でも","reading":"いまでも","meaning":"ngay cả bây giờ","hanViet":"KIM","lesson":40,"ex":[["今でも日本語を勉強しています。","Ngay cả bây giờ tôi vẫn học tiếng Nhật."],["今でも母の料理が好きです。","Ngay cả bây giờ tôi vẫn thích món ăn của mẹ."],["今でも毎朝走っています。","Ngay cả bây giờ tôi vẫn chạy bộ mỗi sáng."],["今でもあの歌を覚えています。","Ngay cả bây giờ tôi vẫn nhớ bài hát đó."],["今でも東京に住んでいます。","Ngay cả bây giờ tôi vẫn sống ở Tokyo."]]},{"word":"うわさします","reading":"うわさします","meaning":"đồn đại","hanViet":"","lesson":40,"ex":[["友達がうわさしています。","Bạn bè đang đồn đại."],["みんながその話をうわさしています。","Mọi người đang đồn đại câu chuyện đó."],["会社でうわさされています。","Ở công ty đang đồn đại."],["田中さんのことをうわさしています。","Người ta đang đồn đại về anh Tanaka."],["先生のことをうわさしています。","Người ta đang đồn đại về thầy giáo."]]},{"word":"単位","reading":"たんい","meaning":"Đơn vị; tín chỉ (đại học)","hanViet":"ĐƠN VỊ","lesson":40,"ex":[["単位を取らなければなりません。","Tôi phải lấy tín chỉ."],["単位が足りません。","Tôi thiếu tín chỉ."],["日本語の単位を取りました。","Tôi đã lấy tín chỉ tiếng Nhật."],["単位を4つ取りました。","Tôi đã lấy 4 tín chỉ."],["単位が足りないから、来年も勉強します。","Vì thiếu tín chỉ nên năm sau tôi vẫn học tiếp."]]},{"word":"模様","reading":"もよう","meaning":"Hoa văn, hoạ tiết","hanViet":"MÔ DẠNG","lesson":40,"ex":[["このシャツの模様が好きです。","Tôi thích hoa văn của chiếc áo này."],["花の模様のスカートを買いました。","Tôi đã mua chiếc váy có hoa văn hoa."],["きれいな模様の着物を着ました。","Tôi đã mặc kimono có hoa văn đẹp."],["このカーテンの模様は青いです。","Hoa văn của chiếc rèm này màu xanh."],["このシャツの模様は小さいです。","Hoa văn của chiếc áo này nhỏ."]]},{"word":"面積","reading":"めんせき","meaning":"Diện tích","hanViet":"DIỆN TÍCH","lesson":40,"ex":[["日本の面積は大きいです。","Diện tích của Nhật Bản lớn."],["部屋の面積を測りました。","Tôi đã đo diện tích căn phòng."],["この土地の面積は広いです。","Diện tích mảnh đất này rộng."],["面積が同じです。","Diện tích bằng nhau."],["公園の面積は大きいです。","Diện tích công viên lớn."]]},{"word":"体積","reading":"たいせき","meaning":"thể tích","hanViet":"THỂ TÍCH","lesson":40,"ex":[["箱の体積を測りました。","Tôi đã đo thể tích của chiếc hộp."],["この箱の体積は大きいです。","Thể tích của chiếc hộp này lớn."],["体積を計算しました。","Tôi đã tính thể tích."],["二つの箱の体積は同じです。","Thể tích của hai chiếc hộp bằng nhau."],["体積が違います。","Thể tích khác nhau."]]},{"word":"容積","reading":"ようせき","meaning":"dung tích","hanViet":"DUNG TÍCH","lesson":40,"ex":[["このコップの容積は大きいです。","Dung tích của chiếc cốc này lớn."],["コップの容積を測りました。","Tôi đã đo dung tích của chiếc cốc."],["容積を測ってください。","Hãy đo dung tích giúp tôi."],["この瓶の容積は小さいです。","Dung tích của chiếc chai này nhỏ."],["容積が同じです。","Dung tích bằng nhau."]]},{"word":"計算","reading":"けいさん","meaning":"Tính toán","hanViet":"KẾ TOÁN","lesson":40,"ex":[["計算をしました。","Tôi đã tính toán."],["計算は正しいです。","Phép tính đúng."],["計算が速いです。","Tôi tính toán nhanh."],["お金の計算をしました。","Tôi đã tính tiền."],["計算を確かめました。","Tôi đã kiểm tra phép tính."]]},{"word":"たす","reading":"たす","meaning":"cộng","hanViet":"","lesson":40,"ex":[["2たす3は5です。","2 cộng 3 bằng 5."],["10たす20は30です。","10 cộng 20 bằng 30."],["5たす5は10です。","5 cộng 5 bằng 10."],["100たす200は300です。","100 cộng 200 bằng 300."],["1たす1は2です。","1 cộng 1 bằng 2."]]},{"word":"ひく","reading":"ひく","meaning":"trừ","hanViet":"","lesson":40,"ex":[["5ひく2は3です。","5 trừ 2 bằng 3."],["10ひく4は6です。","10 trừ 4 bằng 6."],["100ひく30は70です。","100 trừ 30 bằng 70."],["20ひく10は10です。","20 trừ 10 bằng 10."],["8ひく3は5です。","8 trừ 3 bằng 5."]]},{"word":"かける","reading":"かける","meaning":"nhân","hanViet":"","lesson":40,"ex":[["2かける3は6です。","2 nhân 3 bằng 6."],["5かける4は20です。","5 nhân 4 bằng 20."],["10かける10は100です。","10 nhân 10 bằng 100."],["3かける7は21です。","3 nhân 7 bằng 21."],["6かける6は36です。","6 nhân 6 bằng 36."]]},{"word":"わる","reading":"わる","meaning":"chia","hanViet":"","lesson":40,"ex":[["10わる2は5です。","10 chia 2 bằng 5."],["20わる4は5です。","20 chia 4 bằng 5."],["100わる10は10です。","100 chia 10 bằng 10."],["9わる3は3です。","9 chia 3 bằng 3."],["12わる6は2です。","12 chia 6 bằng 2."]]},{"word":"イコール","reading":"いこーる","meaning":"dấu bằng","hanViet":"","lesson":40,"ex":[["2たす3イコール5です。","2 cộng 3 bằng 5."],["10ひく4イコール6です。","10 trừ 4 bằng 6."],["5かける4イコール20です。","5 nhân 4 bằng 20."],["20わる4イコール5です。","20 chia 4 bằng 5."],["1たす1イコール2です。","1 cộng 1 bằng 2."]]},{"word":"直線","reading":"ちょくせん","meaning":"đường thẳng","hanViet":"TRỰC TUYẾN","lesson":40,"ex":[["直線を引いてください。","Hãy vẽ đường thẳng."],["直線はまっすぐです。","Đường thẳng thì thẳng."],["紙に直線を書きました。","Tôi đã vẽ đường thẳng lên giấy."],["直線と曲線を書きました。","Tôi đã vẽ đường thẳng và đường cong."],["直線をまっすぐ引きました。","Tôi đã vẽ đường thẳng thật thẳng."]]},{"word":"曲線","reading":"きょくせん","meaning":"Đường cong","hanViet":"KHÚC TUYẾN","lesson":40,"ex":[["曲線を引いてください。","Hãy vẽ đường cong."],["紙に曲線を書きました。","Tôi đã vẽ đường cong lên giấy."],["曲線は曲がっています。","Đường cong thì cong."],["直線と曲線があります。","Có đường thẳng và đường cong."],["曲線をきれいに書きました。","Tôi đã vẽ đường cong thật đẹp."]]},{"word":"点線","reading":"てんせん","meaning":"đường chấm chấm","hanViet":"ĐIỂM TUYẾN","lesson":40,"ex":[["点線を引いてください。","Hãy vẽ đường chấm chấm."],["紙に点線を書きました。","Tôi đã vẽ đường chấm chấm lên giấy."],["点線で切ってください。","Hãy cắt theo đường chấm chấm."],["点線と直線があります。","Có đường chấm chấm và đường thẳng."],["点線をきれいに書きました。","Tôi đã vẽ đường chấm chấm thật đẹp."]]},{"word":"円（丸）","reading":"えん（まる）","meaning":"hình tròn","hanViet":"VIÊN HOÀN","lesson":40,"ex":[["この時計は円の形です。","Chiếc đồng hồ này có hình tròn."],["子どもは紙に大きい円を書きました。","Đứa trẻ đã vẽ một hình tròn lớn lên giấy."],["りんごは丸い形です。","Quả táo có hình tròn."],["丸いボールを買いました。","Tôi đã mua một quả bóng tròn."],["今夜の月は丸くて、きれいです。","Mặt trăng đêm nay tròn và đẹp."]]},{"word":"三角（形）","reading":"さんかく（けい）","meaning":"hình tam giác","hanViet":"TAM GIÁC HÌNH","lesson":40,"ex":[["三角のケーキを買いました。","Tôi đã mua một chiếc bánh hình tam giác."],["紙を三角形に切ってください。","Hãy cắt tờ giấy thành hình tam giác."],["山の形は三角形です。","Hình dạng của ngọn núi là hình tam giác."],["子どもは三角形をたくさん書きました。","Đứa trẻ đã vẽ nhiều hình tam giác."],["このサンドイッチは三角形です。","Chiếc bánh sandwich này có hình tam giác."]]},{"word":"四角（形）","reading":"しかく（けい）","meaning":"hình vuông","hanViet":"TỨ GIÁC HÌNH","lesson":40,"ex":[["このテーブルは四角形です。","Chiếc bàn này có hình vuông."],["四角形の窓が大きいです。","Cửa sổ hình vuông rất lớn."],["四角形のチョコレートを買いました。","Tôi đã mua sô-cô-la hình vuông."],["この写真は四角形です。","Bức ảnh này có hình vuông."],["子どもは四角形を書きました。","Đứa trẻ đã vẽ một hình vuông."]]},{"word":"縦じま","reading":"たてじま","meaning":"sọc dọc","hanViet":"TUNG","lesson":40,"ex":[["父は縦じまのシャツを着ています。","Bố tôi đang mặc áo sơ mi sọc dọc."],["この縦じまのズボンは私のものです。","Chiếc quần sọc dọc này là của tôi."],["縦じまのスカートを買いました。","Tôi đã mua một chiếc váy sọc dọc."],["縦じまのシャツが好きですか。","Bạn có thích áo sơ mi sọc dọc không?"],["あの店で縦じまのセーターを見ました。","Tôi đã thấy một chiếc áo len sọc dọc ở cửa hàng đó."]]},{"word":"横じま","reading":"よこじま","meaning":"sọc ngang","hanViet":"HOÀNH","lesson":40,"ex":[["母は横じまのセーターを着ています。","Mẹ tôi đang mặc áo len sọc ngang."],["横じまのシャツを買いました。","Tôi đã mua một chiếc áo sơ mi sọc ngang."],["この横じまのスカートは安いです。","Chiếc váy sọc ngang này rẻ."],["横じまの服と無地の服と、どちらが好きですか。","Bạn thích quần áo sọc ngang hay quần áo trơn hơn?"],["子どもは横じまのズボンをはいています。","Đứa trẻ đang mặc quần sọc ngang."]]},{"word":"水玉","reading":"みずたま","meaning":"Giọt nước; họa tiết chấm bi","hanViet":"THỦY NGỌC","lesson":40,"ex":[["母は水玉のスカートを買いました。","Mẹ tôi đã mua một chiếc váy chấm bi."],["この水玉のシャツはかわいいです。","Chiếc áo sơ mi chấm bi này dễ thương."],["水玉の服が好きです。","Tôi thích quần áo chấm bi."],["あの水玉のかばんは妹のものです。","Chiếc túi chấm bi kia là của em gái tôi."],["水玉の傘をさして、学校へ行きました。","Tôi đã che ô chấm bi đi đến trường."]]},{"word":"花柄","reading":"はながら","meaning":"họa tiết hoa","hanViet":"HOA BÍNH","lesson":40,"ex":[["母は花柄のスカートが好きです。","Mẹ tôi thích váy họa tiết hoa."],["花柄のシャツを買いました。","Tôi đã mua một chiếc áo sơ mi họa tiết hoa."],["この花柄のかばんはきれいです。","Chiếc túi họa tiết hoa này đẹp."],["花柄の服を着て、公園へ行きました。","Tôi mặc quần áo họa tiết hoa đi đến công viên."],["姉の傘は花柄です。","Chiếc ô của chị tôi có họa tiết hoa."]]},{"word":"無地","reading":"むじ","meaning":"trơn (không họa tiết)","hanViet":"VÔ ĐỊA","lesson":40,"ex":[["私は無地のシャツが好きです。","Tôi thích áo sơ mi trơn."],["無地のズボンを買いました。","Tôi đã mua một chiếc quần trơn."],["この無地のセーターは安いです。","Chiếc áo len trơn này rẻ."],["無地の服と花柄の服と、どちらが好きですか。","Bạn thích quần áo trơn hay quần áo họa tiết hoa hơn?"],["父は無地のスーツを着ています。","Bố tôi đang mặc bộ vest trơn."]]},{"word":"マラソン","reading":"マラソン","meaning":"ma-ra-tong","hanViet":"","lesson":40,"ex":[["来週の日曜日にマラソンがあります。","Chủ nhật tuần sau có cuộc thi ma-ra-tông."],["田中さんはマラソンに参加しました。","Anh Tanaka đã tham gia cuộc thi ma-ra-tông."],["毎日マラソンを練習しています。","Tôi luyện tập chạy ma-ra-tông mỗi ngày."],["マラソンで42キロ走ります。","Tôi chạy 42 ki-lô-mét trong cuộc thi ma-ra-tông."],["マラソンは体にいいです。","Chạy ma-ra-tông tốt cho sức khỏe."]]},{"word":"コンテスト","reading":"コンテスト","meaning":"cuộc thi","hanViet":"","lesson":40,"ex":[["歌のコンテストに参加しました。","Tôi đã tham gia cuộc thi hát."],["来月、スピーチコンテストがあります。","Tháng sau có cuộc thi hùng biện."],["コンテストで1位になりました。","Tôi đã đạt giải nhất trong cuộc thi."],["妹は絵のコンテストに参加しました。","Em gái tôi đã tham gia cuộc thi vẽ."],["毎日コンテストのために練習しています。","Tôi luyện tập mỗi ngày cho cuộc thi."]]},{"word":"ズボン","reading":"ズボン","meaning":"cái quần","hanViet":"","lesson":40,"ex":[["新しいズボンを買いました。","Tôi đã mua một chiếc quần mới."],["このズボンは少し大きいです。","Chiếc quần này hơi rộng."],["ズボンをはいて、学校へ行きました。","Tôi mặc quần đi đến trường."],["黒いズボンと白いシャツを着ています。","Tôi đang mặc quần đen và áo sơ mi trắng."],["ズボンのポケットにお金を入れました。","Tôi đã bỏ tiền vào túi quần."]]},{"word":"～グラム","reading":"～グラム","meaning":"–gam","hanViet":"","lesson":40,"ex":[["この肉は300グラムです。","Miếng thịt này nặng 300 gam."],["砂糖を100グラム入れてください。","Hãy cho 100 gam đường vào."],["りんごは200グラムぐらいです。","Quả táo nặng khoảng 200 gam."],["パンを500グラム買いました。","Tôi đã mua 500 gam bánh mì."],["この魚は400グラムです。","Con cá này nặng 400 gam."]]},{"word":"～センチ","reading":"～センチ","meaning":"–xăng-ti-mét","hanViet":"","lesson":40,"ex":[["この机は120センチです。","Chiếc bàn này dài 120 xăng-ti-mét."],["この紙は30センチです。","Tờ giấy này dài 30 xăng-ti-mét."],["テレビは80センチぐらいです。","Chiếc tivi rộng khoảng 80 xăng-ti-mét."],["この本は20センチです。","Cuốn sách này dài 20 xăng-ti-mét."],["子どもは100センチになりました。","Đứa trẻ đã cao 100 xăng-ti-mét."]]},{"word":"～ミリ","reading":"～ミリ","meaning":"–mi-li-mét","hanViet":"","lesson":40,"ex":[["この紙は1ミリぐらいです。","Tờ giấy này dày khoảng 1 mi-li-mét."],["雨が5ミリ降りました。","Mưa đã rơi 5 mi-li-mét."],["この本は30ミリです。","Cuốn sách này dày 30 mi-li-mét."],["この鉛筆は7ミリです。","Cây bút chì này dày 7 mi-li-mét."],["2ミリの線を書きました。","Tôi đã vẽ một đường thẳng dày 2 mi-li-mét."]]},{"word":"テスト","reading":"テスト","meaning":"bài kiểm tra","hanViet":"","lesson":40,"ex":[["あした、日本語のテストがあります。","Ngày mai có bài kiểm tra tiếng Nhật."],["テストの勉強をしています。","Tôi đang ôn bài kiểm tra."],["テストは来週の月曜日です。","Bài kiểm tra vào thứ Hai tuần sau."],["英語のテストは難しかったです。","Bài kiểm tra tiếng Anh rất khó."],["テストで100点を取りました。","Tôi đã được 100 điểm trong bài kiểm tra."]]},{"word":"うまくいきます","reading":"うまくいきます","meaning":"tốt, thuận lợi","hanViet":"","lesson":40,"ex":[["仕事はうまくいっています。","Công việc đang tiến triển tốt."],["日本語の勉強はうまくいっていますか。","Việc học tiếng Nhật của bạn có tiến triển tốt không?"],["旅行はうまくいきました。","Chuyến du lịch đã diễn ra tốt đẹp."],["料理はうまくいきました。","Món ăn đã nấu thành công."],["テストはうまくいきましたか。","Bài kiểm tra có làm tốt không?"]]},{"word":"お年寄り","reading":"おとしより","meaning":"người già, người cao tuổi","hanViet":"NIÊN KÍ","lesson":40,"ex":[["お年寄りを助けました。","Tôi đã giúp đỡ người cao tuổi."],["電車でお年寄りに席をあげました。","Trên tàu điện, tôi đã nhường ghế cho người cao tuổi."],["お年寄りは経験がたくさんあります。","Người cao tuổi có nhiều kinh nghiệm."],["祖父はお年寄りですが、元気です。","Ông tôi tuy cao tuổi nhưng vẫn khỏe mạnh."],["お年寄りの話を聞きました。","Tôi đã nghe câu chuyện của người cao tuổi."]]},{"word":"発表会","reading":"はっぴょうかい","meaning":"buổi phát biểu","hanViet":"PHÁT BIỂU HỘI","lesson":40,"ex":[["来週、発表会があります。","Tuần sau có buổi phát biểu."],["発表会で日本語を話しました。","Tôi đã nói tiếng Nhật trong buổi phát biểu."],["子どもの発表会を見に行きました。","Tôi đã đi xem buổi phát biểu của con tôi."],["発表会のために練習しています。","Tôi đang luyện tập cho buổi phát biểu."],["発表会は学校の教室であります。","Buổi phát biểu diễn ra ở lớp học của trường."]]},{"word":"～キロ","reading":"～キロ","meaning":"–ki-lo, –cân","hanViet":"","lesson":40,"ex":[["この肉は2キロです。","Miếng thịt này nặng 2 ki-lô."],["学校まで3キロあります。","Từ đây đến trường là 3 ki-lô-mét."],["りんごを1キロ買いました。","Tôi đã mua 1 ki-lô táo."],["東京から京都まで370キロあります。","Từ Tokyo đến Kyoto là 370 ki-lô-mét."],["この魚は3キロです。","Con cá này nặng 3 ki-lô."]]},{"word":"オートバイ","reading":"オートバイ","meaning":"xe máy","hanViet":"","lesson":40,"ex":[["父はオートバイで会社へ行きます。","Bố tôi đi làm bằng xe máy."],["オートバイを買いました。","Tôi đã mua một chiếc xe máy."],["オートバイは速いです。","Xe máy chạy nhanh."],["オートバイに乗ることができますか。","Bạn có thể lái xe máy không?"],["雨が降る日はオートバイに乗りません。","Ngày mưa tôi không đi xe máy."]]},{"word":"長崎","reading":"ながさき","meaning":"Nagasaki","hanViet":"TRƯỜNG KỲ","lesson":40,"ex":[["長崎へ旅行に行きました。","Tôi đã đi du lịch đến Nagasaki."],["長崎は海がきれいです。","Biển ở Nagasaki rất đẹp."],["長崎でおいしい魚を食べました。","Tôi đã ăn cá ngon ở Nagasaki."],["長崎は有名な町です。","Nagasaki là một thành phố nổi tiếng."],["来年、長崎へ行くつもりです。","Sang năm tôi dự định đi Nagasaki."]]},{"word":"仙台","reading":"せんだい","meaning":"Sendai (thành phố ở Nhật)","hanViet":"TIÊN ĐÀI","lesson":40,"ex":[["仙台へ旅行に行きました。","Tôi đã đi du lịch đến Sendai."],["仙台は七夕祭りで有名です。","Sendai nổi tiếng với lễ hội Tanabata."],["仙台でおいしい肉を食べました。","Tôi đã ăn thịt ngon ở Sendai."],["仙台はきれいな町です。","Sendai là một thành phố đẹp."],["仙台に友達がいます。","Tôi có bạn ở Sendai."]]},{"word":"七夕祭り","reading":"たなばたまつり","meaning":"Lễ hội Tanabata","hanViet":"THẤT TỊCH TẾ","lesson":40,"ex":[["七夕祭りは8月にあります。","Lễ hội Tanabata diễn ra vào tháng 8."],["仙台の七夕祭りは有名です。","Lễ hội Tanabata ở Sendai rất nổi tiếng."],["七夕祭りを見に行きました。","Tôi đã đi xem lễ hội Tanabata."],["七夕祭りで花火を見ました。","Tôi đã xem pháo hoa ở lễ hội Tanabata."],["七夕祭りは夏の祭りです。","Lễ hội Tanabata là lễ hội mùa hè."]]},{"word":"東照宮","reading":"とうしょうぐう","meaning":"tên đền thờ Tokugawa Ieyasu ở Nikko, tỉnh Tochigi","hanViet":"ĐÔNG CHIẾU CUNG","lesson":40,"ex":[["東照宮は有名な神社です。","Đền Đông Chiếu Cung là một ngôi đền nổi tiếng."],["東照宮を見に行きました。","Tôi đã đi xem đền Đông Chiếu Cung."],["東照宮は古い建物です。","Đền Đông Chiếu Cung là một tòa nhà cổ."],["東照宮で写真を撮りました。","Tôi đã chụp ảnh ở đền Đông Chiếu Cung."],["東照宮へ旅行に行きました。","Tôi đã đi du lịch đến đền Đông Chiếu Cung."]]},{"word":"男","reading":"おとこ","meaning":"Đàn ông","hanViet":"NAM","lesson":40,"ex":[["あの男の人は先生です。","Người đàn ông kia là giáo viên."],["男の子が公園で遊んでいます。","Cậu bé đang chơi ở công viên."],["あの男の人は会社員です。","Người đàn ông kia là nhân viên công ty."],["男の子はサッカーが好きです。","Cậu bé thích bóng đá."],["あの男の子は私の弟です。","Cậu bé kia là em trai tôi."]]},{"word":"いただきます","reading":"いただきます","meaning":"nhận (kính ngữ của もらいます)","hanViet":"","lesson":41,"ex":[["先生から本をいただきました。","Tôi đã nhận sách từ thầy giáo."],["社長からプレゼントをいただきました。","Tôi đã nhận quà từ giám đốc."],["お母さんからお金をいただきました。","Tôi đã nhận tiền từ mẹ."],["田中さんから手紙をいただきました。","Tôi đã nhận thư từ anh Tanaka."],["先生からお菓子をいただきました。","Tôi đã nhận bánh kẹo từ thầy giáo."]]},{"word":"くださいます","reading":"くださいます","meaning":"cho, tặng (kính ngữ của くれます)","hanViet":"","lesson":41,"ex":[["先生が本をくださいました。","Thầy giáo đã cho tôi cuốn sách."],["社長がプレゼントをくださいました。","Giám đốc đã tặng tôi món quà."],["お母さんがお金をくださいました。","Mẹ đã cho tôi tiền."],["田中さんが手紙をくださいました。","Anh Tanaka đã gửi cho tôi bức thư."],["先生が辞書をくださいました。","Thầy giáo đã cho tôi cuốn từ điển."]]},{"word":"呼びます","reading":"よびます","meaning":"gọi; mời","hanViet":"HÔ","lesson":41,"ex":[["先生を呼びました。","Tôi đã gọi thầy giáo."],["医者を呼んでください。","Hãy gọi bác sĩ."],["田中さんをパーティーに呼びました。","Tôi đã mời anh Tanaka đến bữa tiệc."],["友達を家に呼びました。","Tôi đã mời bạn đến nhà."],["タクシーを呼んでください。","Hãy gọi taxi."]]},{"word":"取り替えます","reading":"とりかえます","meaning":"đổi, thay","hanViet":"THỦ THẾ","lesson":41,"ex":[["古い時計を新しい時計に取り替えました。","Tôi đã thay chiếc đồng hồ cũ bằng chiếc mới."],["電池を取り替えました。","Tôi đã thay pin."],["壊れた傘を取り替えました。","Tôi đã thay chiếc ô bị hỏng."],["パスポートを取り替えました。","Tôi đã đổi hộ chiếu."],["古い車を新しい車に取り替えました。","Tôi đã đổi chiếc xe cũ lấy chiếc xe mới."]]},{"word":"親切にします","reading":"しんせつにします","meaning":"giúp đỡ, đối xử thân thiện","hanViet":"THÂN THIẾT","lesson":41,"ex":[["先生は学生に親切にします。","Thầy giáo đối xử tốt với học sinh."],["田中さんは私に親切にしてくれました。","Anh Tanaka đã đối xử tốt với tôi."],["お年寄りに親切にします。","Tôi đối xử tốt với người cao tuổi."],["母はいつも私に親切にします。","Mẹ luôn đối xử tốt với tôi."],["留学生に親切にしてください。","Hãy đối xử tốt với du học sinh."]]},{"word":"かわいい","reading":"かわいい","meaning":"xinh, đáng yêu","hanViet":"","lesson":41,"ex":[["この犬はかわいいです。","Con chó này dễ thương."],["妹はかわいいです。","Em gái tôi dễ thương."],["かわいい猫がいます。","Có một con mèo dễ thương."],["この服はかわいいです。","Bộ quần áo này dễ thương."],["赤ちゃんはかわいいです。","Em bé dễ thương."]]},{"word":"お祝い","reading":"おいわい","meaning":"Quà mừng, tiệc mừng","hanViet":"CHÚC","lesson":41,"ex":[["誕生日のお祝いをしました。","Tôi đã tổ chức tiệc mừng sinh nhật."],["結婚式のお祝いにプレゼントをあげました。","Tôi đã tặng quà mừng đám cưới."],["お祝いをありがとうございます。","Cảm ơn món quà mừng của bạn."],["先生のお祝いをしました。","Chúng tôi đã tổ chức tiệc mừng cho thầy giáo."],["お祝いに花をあげました。","Tôi đã tặng hoa chúc mừng."]]},{"word":"お年玉","reading":"おとしだま","meaning":"tiền mừng tuổi","hanViet":"NIÊN NGỌC","lesson":41,"ex":[["子どもにお年玉をあげました。","Tôi đã lì xì cho trẻ em."],["お年玉をもらって、うれしかったです。","Tôi đã nhận tiền lì xì nên rất vui."],["祖父からお年玉をもらいました。","Tôi đã nhận tiền lì xì từ ông."],["お年玉で本を買いました。","Tôi đã mua sách bằng tiền lì xì."],["お年玉は5000円でした。","Tiền lì xì là 5000 yên."]]},{"word":"見舞い","reading":"みまい","meaning":"thăm người ốm","hanViet":"KIẾN VŨ","lesson":41,"ex":[["先生の見舞いに行きました。","Tôi đã đi thăm thầy giáo ốm."],["病院へ見舞いに行きました。","Tôi đã đi thăm người ốm ở bệnh viện."],["見舞いに花を買いました。","Tôi đã mua hoa để đi thăm người ốm."],["友達の見舞いに行きました。","Tôi đã đi thăm bạn ốm."],["見舞いの手紙を書きました。","Tôi đã viết thư thăm hỏi người ốm."]]},{"word":"興味","reading":"きょうみ","meaning":"Hứng thú, sở thích","hanViet":"HƯNG VỊ","lesson":41,"ex":[["日本語に興味があります。","Tôi có hứng thú với tiếng Nhật."],["音楽に興味があります。","Tôi có hứng thú với âm nhạc."],["歴史に興味があります。","Tôi có hứng thú với lịch sử."],["スポーツに興味がありません。","Tôi không có hứng thú với thể thao."],["先生は科学に興味があります。","Thầy giáo có hứng thú với khoa học."]]},{"word":"情報","reading":"じょうほう","meaning":"Thông tin","hanViet":"TÌNH BÁO","lesson":41,"ex":[["旅行の情報を集めました。","Tôi đã thu thập thông tin du lịch."],["新しい情報を教えてください。","Hãy cho tôi biết thông tin mới."],["インターネットで情報を調べました。","Tôi đã tra cứu thông tin trên internet."],["情報が足りません。","Thông tin không đủ."],["この情報は古いです。","Thông tin này đã cũ."]]},{"word":"文法","reading":"ぶんぽう","meaning":"Ngữ pháp","hanViet":"VĂN PHÁP","lesson":41,"ex":[["日本語の文法は難しいです。","Ngữ pháp tiếng Nhật khó."],["文法の勉強をしています。","Tôi đang học ngữ pháp."],["文法のテストがあります。","Có bài kiểm tra ngữ pháp."],["文法の本を買いました。","Tôi đã mua sách ngữ pháp."],["先生に文法を教えてもらいました。","Tôi đã nhờ thầy giáo dạy ngữ pháp."]]},{"word":"発音","reading":"はつおん","meaning":"phát âm","hanViet":"PHÁT ÂM","lesson":41,"ex":[["日本語の発音は難しいです。","Phát âm tiếng Nhật khó."],["発音を練習しています。","Tôi đang luyện tập phát âm."],["先生の発音はきれいです。","Phát âm của thầy giáo rất hay."],["発音を直してください。","Hãy sửa phát âm cho tôi."],["発音がよくなりました。","Phát âm của tôi đã tốt hơn."]]},{"word":"猿","reading":"さる","meaning":"Con khỉ","hanViet":"VIÊN","lesson":41,"ex":[["動物園で猿を見ました。","Tôi đã xem khỉ ở sở thú."],["猿は木に登ります。","Khỉ leo lên cây."],["猿はりんごが好きです。","Khỉ thích táo."],["猿はかわいいです。","Khỉ dễ thương."],["山に猿がいます。","Trên núi có khỉ."]]},{"word":"えさ","reading":"えさ","meaning":"mồi; thức ăn","hanViet":"","lesson":41,"ex":[["犬にえさをあげました。","Tôi đã cho chó ăn."],["動物園で猿にえさをあげました。","Tôi đã cho khỉ ăn ở sở thú."],["犬のえさを買いました。","Tôi đã mua thức ăn cho chó."],["鳥のえさを買いました。","Tôi đã mua thức ăn cho chim."],["魚にえさをあげる時間です。","Đã đến giờ cho cá ăn."]]},{"word":"玩具","reading":"おもちゃ","meaning":"đồ chơi","hanViet":"NGOẠN CỤ","lesson":41,"ex":[["子どもは新しい玩具で遊びます。","Trẻ con chơi đồ chơi mới."],["弟の誕生日に玩具を買いました。","Tôi đã mua đồ chơi tặng sinh nhật em trai."],["この店は玩具がたくさんあります。","Cửa hàng này có rất nhiều đồ chơi."],["子どものとき、玩具でよく遊びました。","Hồi còn nhỏ, tôi thường chơi đồ chơi."],["母は弟に玩具を買ってあげました。","Mẹ đã mua đồ chơi cho em trai."]]},{"word":"絵本","reading":"えほん","meaning":"Sách tranh","hanViet":"HỘI BẢN","lesson":41,"ex":[["母は毎晩、子どもに絵本を読んであげます。","Mỗi tối, mẹ đọc sách tranh cho con nghe."],["図書館で絵本を借りました。","Tôi đã mượn sách tranh ở thư viện."],["この絵本は絵がきれいです。","Cuốn sách tranh này có tranh vẽ đẹp."],["子どもは絵本が好きです。","Trẻ con thích sách tranh."],["妹に絵本を買ってあげました。","Tôi đã mua sách tranh tặng em gái."]]},{"word":"絵はがき","reading":"えはがき","meaning":"bưu ảnh","hanViet":"HỘI","lesson":41,"ex":[["京都で絵はがきを買いました。","Tôi đã mua bưu ảnh ở Kyoto."],["友達に絵はがきを送りました。","Tôi đã gửi bưu ảnh cho bạn."],["この絵はがきはきれいです。","Tấm bưu ảnh này đẹp."],["旅行のとき、絵はがきをたくさん買います。","Khi đi du lịch, tôi mua nhiều bưu ảnh."],["絵はがきに手紙を書きました。","Tôi đã viết thư lên bưu ảnh."]]},{"word":"靴下","reading":"くつした","meaning":"Tất, vớ","hanViet":"NGOA HẠ","lesson":41,"ex":[["白い靴下を買いました。","Tôi đã mua đôi tất trắng."],["冬は靴下をはきます。","Mùa đông tôi đi tất."],["靴下が破れました。","Tất bị rách rồi."],["靴下を洗いました。","Tôi đã giặt tất."],["弟は赤い靴下が好きです。","Em trai tôi thích tất đỏ."]]},{"word":"手袋","reading":"てぶくろ","meaning":"Găng tay","hanViet":"THỦ ĐÁI","lesson":41,"ex":[["冬は手袋をします。","Mùa đông tôi đeo găng tay."],["寒いから、手袋を買いました。","Vì trời lạnh nên tôi đã mua găng tay."],["雪の日は手袋をします。","Ngày có tuyết tôi đeo găng tay."],["母に手袋をあげました。","Tôi đã tặng găng tay cho mẹ."],["手袋を忘れました。","Tôi đã quên găng tay."]]},{"word":"指輪","reading":"ゆびわ","meaning":"Nhẫn (đeo tay)","hanViet":"CHỈ LUÂN","lesson":41,"ex":[["母はきれいな指輪をしています。","Mẹ tôi đang đeo chiếc nhẫn đẹp."],["結婚したとき、指輪をもらいました。","Khi kết hôn, tôi đã nhận được nhẫn."],["この指輪は高いです。","Chiếc nhẫn này đắt."],["妻に指輪をあげました。","Tôi đã tặng nhẫn cho vợ."],["指輪をなくしました。","Tôi đã làm mất nhẫn."]]},{"word":"祖父","reading":"そふ","meaning":"Ông (nội/ngoại)","hanViet":"TỔ PHỤ","lesson":41,"ex":[["祖父は田舎に住んでいます。","Ông tôi sống ở quê."],["祖父は八十歳です。","Ông tôi 80 tuổi."],["祖父は元気です。","Ông tôi khỏe mạnh."],["休みの日に祖父に会いに行きます。","Ngày nghỉ tôi đi thăm ông."],["祖父は昔、先生でした。","Ngày xưa ông tôi là giáo viên."]]},{"word":"祖母","reading":"そぼ","meaning":"Bà (ngoại/nội)","hanViet":"TỔ MẪU","lesson":41,"ex":[["祖母は料理が上手です。","Bà tôi nấu ăn giỏi."],["祖母に手紙を書きました。","Tôi đã viết thư cho bà."],["祖母は八十五歳です。","Bà tôi 85 tuổi."],["祖母は毎日、庭で花に水をやります。","Mỗi ngày bà tưới nước cho hoa trong vườn."],["祖母は昔話が好きです。","Bà thích truyện cổ."]]},{"word":"孫","reading":"まご","meaning":"Cháu","hanViet":"TÔN","lesson":41,"ex":[["祖父は孫が大好きです。","Ông rất yêu cháu."],["孫は三人います。","Tôi có ba đứa cháu."],["孫と公園で遊びます。","Tôi chơi với cháu ở công viên."],["孫の誕生日にプレゼントをあげました。","Tôi đã tặng quà sinh nhật cho cháu."],["孫は今年、小学校へ入ります。","Năm nay cháu vào tiểu học."]]},{"word":"伯父、叔父","reading":"おじ","meaning":"chú, bác, cậu (của mình)","hanViet":"BÁ PHỤ THÚC PHỤ","lesson":41,"ex":[["伯父はおおさかに住んでいます。","Bác tôi sống ở Osaka."],["叔父は会社で働いています。","Chú tôi làm việc ở công ty."],["伯父は医者です。","Bác tôi là bác sĩ."],["叔父に会いに行きました。","Tôi đã đi gặp chú."],["伯父は車を持っています。","Bác tôi có ô tô."]]},{"word":"おじさん","reading":"おじさん","meaning":"chú, bác, cậu (của người khác)","hanViet":"","lesson":41,"ex":[["山田さんのおじさんは先生です。","Chú của anh Yamada là giáo viên."],["あのおじさんはだれですか。","Chú kia là ai?"],["おじさんは優しい人です。","Chú ấy là người hiền lành."],["田中さんのおじさんはおおさかに住んでいます。","Bác của anh Tanaka sống ở Osaka."],["おじさんが来ました。","Chú ấy đã đến."]]},{"word":"伯母、叔母","reading":"おば","meaning":"cô, dì (của mình)","hanViet":"BÁ MẪU THÚC MẪU","lesson":41,"ex":[["伯母は東京に住んでいます。","Bác gái tôi sống ở Tokyo."],["叔母は料理が上手です。","Dì tôi nấu ăn giỏi."],["伯母に手紙を書きました。","Tôi đã viết thư cho bác gái."],["叔母は花が好きです。","Dì tôi thích hoa."],["伯母は先生です。","Bác gái tôi là giáo viên."]]},{"word":"おばさん","reading":"おばさん","meaning":"cô, dì (của người khác)","hanViet":"","lesson":41,"ex":[["山田さんのおばさんは先生です。","Dì của chị Yamada là giáo viên."],["あのおばさんはだれですか。","Cô kia là ai?"],["おばさんは優しい人です。","Cô ấy là người hiền lành."],["田中さんのおばさんは京都に住んでいます。","Dì của chị Tanaka sống ở Kyoto."],["おばさんがケーキを作りました。","Cô ấy đã làm bánh."]]},{"word":"おととし","reading":"おととし","meaning":"năm kia","hanViet":"","lesson":41,"ex":[["おととし、日本へ来ました。","Năm kia tôi đã đến Nhật."],["おととし、大学を卒業しました。","Năm kia tôi đã tốt nghiệp đại học."],["おととし、京都へ旅行しました。","Năm kia tôi đã đi du lịch Kyoto."],["おととし、結婚しました。","Năm kia tôi đã kết hôn."],["おととし、東京で働いていました。","Năm kia tôi đã làm việc ở Tokyo."]]},{"word":"はあ","reading":"はあ","meaning":"vâng, tôi hiểu rồi","hanViet":"","lesson":41,"ex":[["「はあ、わかりました。」と言いました。","Tôi đã nói: \"Vâng, tôi hiểu rồi\"."],["先生が「はあ、そうですか。」と言いました。","Thầy giáo đã nói: \"Vâng, vậy sao\"."],["「はあ、ありがとうございます。」と答えました。","Tôi đã đáp: \"Vâng, cảm ơn anh/chị\"."],["「はあ、行きます。」と言って、出かけました。","Tôi nói \"Vâng, tôi đi đây\" rồi ra ngoài."],["「はあ、大丈夫です。」と母に言いました。","Tôi đã nói với mẹ: \"Vâng, không sao đâu\"."]]},{"word":"申し訳ありません","reading":"もうしわけありません","meaning":"Xin lỗi","hanViet":"THÂN DỊCH","lesson":41,"ex":[["遅れて、申し訳ありません。","Tôi đến muộn, xin lỗi anh/chị."],["申し訳ありませんが、ゆっくり言ってください。","Xin lỗi, anh/chị nói chậm lại được không?"],["約束を忘れて、申し訳ありません。","Tôi đã quên lời hẹn, xin lỗi anh/chị."],["申し訳ありません。きょうは行けません。","Xin lỗi. Hôm nay tôi không đi được."],["申し訳ありませんが、わかりません。","Xin lỗi, tôi không hiểu."]]},{"word":"預かります","reading":"あずかります","meaning":"bảo quản; thu nhận; giữ giùm","hanViet":"DỰ","lesson":41,"ex":[["すみません、この荷物を預かってください。","Xin lỗi, anh/chị giữ giùm hành lý này được không?"],["先生が私のバッグを預かってくれました。","Thầy giáo đã giữ giùm túi của tôi."],["子どもを預かってもらいました。","Tôi đã nhờ giữ giùm con."],["鍵を預かります。","Tôi giữ chìa khóa giùm."],["駅で荷物を預かってもらいました。","Tôi đã nhờ giữ hành lý ở ga."]]},{"word":"先日","reading":"せんじつ","meaning":"hôm trước","hanViet":"TIÊN NHẬT","lesson":41,"ex":[["先日、友達に会いました。","Hôm trước tôi đã gặp bạn."],["先日、京都へ行きました。","Hôm trước tôi đã đi Kyoto."],["先日、先生に手紙を書きました。","Hôm trước tôi đã viết thư cho thầy giáo."],["先日、母から電話がありました。","Hôm trước mẹ đã gọi điện cho tôi."],["先日、買った本を読みました。","Hôm trước tôi đã đọc cuốn sách đã mua."]]},{"word":"助かります","reading":"たすかります","meaning":"Được giúp","hanViet":"TRỢ","lesson":41,"ex":[["手伝ってくれて、助かります。","Anh/chị giúp tôi, thật may quá."],["荷物を持ってくれて、助かりました。","Anh/chị xách hành lý giúp tôi, thật may quá."],["教えてくれて、助かります。","Anh/chị chỉ giúp tôi, thật may quá."],["車で送ってくれて、助かりました。","Anh/chị chở tôi bằng ô tô, thật may quá."],["電話をくれて、助かりました。","Anh/chị gọi điện cho tôi, thật may quá."]]},{"word":"昔話","reading":"むかしばなし","meaning":"truyện cổ, chuyện ngày xưa","hanViet":"TÍCH THOẠI","lesson":41,"ex":[["祖母は昔話をよく話します。","Bà thường kể chuyện cổ."],["子どものとき、昔話が好きでした。","Hồi còn nhỏ, tôi thích truyện cổ."],["この昔話は有名です。","Truyện cổ này nổi tiếng."],["昔話を読んで、日本語を勉強しました。","Tôi đã đọc truyện cổ để học tiếng Nhật."],["母は昔話を話してくれました。","Mẹ đã kể truyện cổ cho tôi nghe."]]},{"word":"ある～","reading":"ある～","meaning":"có một~","hanViet":"","lesson":41,"ex":[["むかし、ある村に男の人がいました。","Ngày xưa, ở một ngôi làng nọ có một người đàn ông."],["ある日、友達に会いました。","Một hôm, tôi đã gặp bạn."],["ある店でこの本を買いました。","Tôi đã mua cuốn sách này ở một cửa hàng nọ."],["ある朝、雪が降りました。","Một buổi sáng nọ, tuyết đã rơi."],["ある人にこの話を聞きました。","Tôi đã nghe câu chuyện này từ một người nọ."]]},{"word":"いじめます","reading":"いじめます","meaning":"bắt nạt","hanViet":"","lesson":41,"ex":[["学校で友達をいじめてはいけません。","Không được bắt nạt bạn ở trường."],["大きい子どもが小さい子どもをいじめました。","Đứa trẻ lớn đã bắt nạt đứa trẻ nhỏ."],["だれかをいじめることはよくありません。","Bắt nạt ai đó là không tốt."],["弟をいじめないでください。","Đừng bắt nạt em trai tôi."],["猫をいじめてはいけません。","Không được bắt nạt mèo."]]},{"word":"亀","reading":"かめ","meaning":"con rùa","hanViet":"QUY","lesson":41,"ex":[["亀はゆっくり歩きます。","Rùa đi chậm rãi."],["海に亀がいます。","Ở biển có rùa."],["亀は長生きします。","Rùa sống lâu."],["子どもは亀が好きです。","Trẻ con thích rùa."],["亀は陸に上がります。","Rùa lên đất liền."]]},{"word":"城","reading":"しろ","meaning":"Lâu đài, thành","hanViet":"THÀNH","lesson":41,"ex":[["おおさかの城は有名です。","Lâu đài ở Osaka nổi tiếng."],["城を見学しました。","Tôi đã tham quan lâu đài."],["むかし、この城にお姫様が住んでいました。","Ngày xưa, công chúa đã sống trong lâu đài này."],["京都に古い城があります。","Ở Kyoto có lâu đài cổ."],["城は山の上にあります。","Lâu đài nằm trên núi."]]},{"word":"お姫様","reading":"おひめさま","meaning":"công chúa","hanViet":"CƠ DẠNG","lesson":41,"ex":[["お姫様は城に住んでいます。","Công chúa sống trong lâu đài."],["お姫様はきれいです。","Công chúa xinh đẹp."],["昔話にお姫様が出ます。","Trong truyện cổ có công chúa xuất hiện."],["子どもはお姫様が好きです。","Trẻ con thích công chúa."],["お姫様はきれいな服を着ています。","Công chúa đang mặc bộ váy đẹp."]]},{"word":"楽しく","reading":"たのしく","meaning":"vui sướng","hanViet":"LẠC","lesson":41,"ex":[["友達と楽しく話しました。","Tôi đã nói chuyện vui vẻ với bạn."],["家族と楽しく過ごしました。","Tôi đã trải qua thời gian vui vẻ cùng gia đình."],["子どもは楽しく遊びます。","Trẻ con chơi đùa vui vẻ."],["みんなで楽しく歌いました。","Mọi người đã cùng hát vui vẻ."],["楽しく勉強します。","Tôi học tập vui vẻ."]]},{"word":"暮らします","reading":"くらします","meaning":"sống","hanViet":"MỘ","lesson":41,"ex":[["田舎で暮らしています。","Tôi đang sống ở quê."],["家族と東京で暮らしています。","Tôi đang sống ở Tokyo cùng gia đình."],["むかし、村で暮らしていました。","Ngày xưa, tôi đã sống ở làng."],["日本で暮らしたいです。","Tôi muốn sống ở Nhật."],["一人で暮らしています。","Tôi đang sống một mình."]]},{"word":"陸","reading":"りく","meaning":"Đất liền","hanViet":"LỤC","lesson":41,"ex":[["船から陸が見えます。","Từ trên tàu nhìn thấy đất liền."],["海の反対は陸です。","Phía đối diện biển là đất liền."],["鳥は陸に住んでいます。","Chim sống trên đất liền."],["陸に家を建てました。","Tôi đã xây nhà trên đất liền."],["島から陸へ船で行きます。","Tôi đi tàu từ đảo đến đất liền."]]},{"word":"煙","reading":"けむり","meaning":"Khói","hanViet":"YÊN","lesson":41,"ex":[["たばこの煙は体に悪いです。","Khói thuốc lá có hại cho sức khỏe."],["火事で煙が出ました。","Cháy nhà nên khói bốc lên."],["煙が見えます。","Nhìn thấy khói."],["煙は目に悪いです。","Khói có hại cho mắt."],["煙がたくさん出ました。","Khói bốc lên rất nhiều."]]},{"word":"真っ白","reading":"まっしろ","meaning":"trắng xoá","hanViet":"CHÂN BẠCH","lesson":41,"ex":[["雪で山が真っ白です。","Núi trắng xóa vì tuyết."],["シャツが真っ白です。","Áo sơ mi trắng tinh."],["紙は真っ白です。","Giấy trắng tinh."],["雪が降って、道が真っ白になりました。","Tuyết rơi nên đường trắng xóa."],["歯が真っ白です。","Răng trắng tinh."]]},{"word":"中身","reading":"なかみ","meaning":"nội dung; bên trong","hanViet":"TRUNG THÂN","lesson":41,"ex":[["バッグの中身を見ました。","Tôi đã xem bên trong túi xách."],["箱の中身は何ですか。","Bên trong hộp là gì?"],["冷蔵庫の中身を見ました。","Tôi đã xem bên trong tủ lạnh."],["手紙の中身を読みました。","Tôi đã đọc nội dung bức thư."],["財布の中身はお金だけです。","Trong ví chỉ có tiền."]]},{"word":"ドライバー","reading":"ドライバー","meaning":"đồ vặn ốc; tua-vít","hanViet":"","lesson":41,"ex":[["ドライバーで自転車を直しました。","Tôi đã sửa xe đạp bằng tua-vít."],["ドライバーを貸してください。","Cho tôi mượn tua-vít."],["ドライバーを買いました。","Tôi đã mua tua-vít."],["ドライバーはどこですか。","Tua-vít ở đâu?"],["ドライバーを使います。","Tôi dùng tua-vít."]]},{"word":"ハンカチ","reading":"ハンカチ","meaning":"khăn tay","hanViet":"","lesson":41,"ex":[["ハンカチで手をふきました。","Tôi đã lau tay bằng khăn tay."],["白いハンカチを買いました。","Tôi đã mua khăn tay trắng."],["ハンカチを忘れました。","Tôi đã quên khăn tay."],["ハンカチを洗いました。","Tôi đã giặt khăn tay."],["母にハンカチをあげました。","Tôi đã tặng khăn tay cho mẹ."]]},{"word":"バッグ","reading":"バッグ","meaning":"túi xách","hanViet":"","lesson":41,"ex":[["新しいバッグを買いました。","Tôi đã mua túi xách mới."],["バッグに本を入れました。","Tôi đã bỏ sách vào túi."],["バッグが重いです。","Túi xách nặng."],["バッグを忘れました。","Tôi đã quên túi xách."],["母にバッグをあげました。","Tôi đã tặng túi xách cho mẹ."]]},{"word":"二人","reading":"ふたり","meaning":"Hai người","hanViet":"NHỊ NHÂN","lesson":41,"ex":[["二人で映画を見ました。","Hai người cùng xem phim."],["二人でごはんを食べました。","Hai người cùng ăn cơm."],["教室に二人がいます。","Trong lớp học có hai người."],["二人で旅行しました。","Hai người cùng đi du lịch."],["二人で写真を撮りました。","Hai người cùng chụp ảnh."]]},{"word":"包みます","reading":"つつみます","meaning":"bọc; gói","hanViet":"BAO","lesson":42,"ex":[["プレゼントを紙で包みます。","Tôi gói quà bằng giấy."],["母はプレゼントをきれいに包みました。","Mẹ đã gói quà rất đẹp."],["ケーキを包んでください。","Gói bánh giúp tôi."],["お菓子を包みました。","Tôi đã gói bánh kẹo."],["花を紙で包みました。","Tôi đã gói hoa bằng giấy."]]},{"word":"沸かします","reading":"わかします","meaning":"đun sôi","hanViet":"PHÍ","lesson":42,"ex":[["毎朝、母はお茶のために湯を沸かします。","Mỗi sáng mẹ tôi đun nước sôi để pha trà."],["やかんで湯を沸かしました。","Tôi đã đun nước sôi bằng ấm."],["お茶のために、湯を沸かしました。","Tôi đã đun nước sôi để pha trà."],["鍋で湯を沸かします。","Tôi đun nước sôi bằng nồi."],["朝、湯を沸かして、コーヒーを作りました。","Buổi sáng, tôi đun nước sôi rồi pha cà phê."]]},{"word":"混ぜます","reading":"まぜます","meaning":"trộn; khuấy","hanViet":"HỖN","lesson":42,"ex":[["砂糖と牛乳を混ぜます。","Tôi trộn đường với sữa."],["卵と牛乳を混ぜました。","Tôi đã trộn trứng với sữa."],["スプーンでよく混ぜてください。","Hãy khuấy đều bằng thìa."],["塩と砂糖を混ぜました。","Tôi đã trộn muối với đường."],["ごはんと卵を混ぜて、食べました。","Tôi đã trộn cơm với trứng rồi ăn."]]},{"word":"計算します","reading":"けいさんします","meaning":"tính toán","hanViet":"KẾ TOÁN","lesson":42,"ex":[["お金を計算します。","Tôi tính tiền."],["頭で計算しました。","Tôi đã tính nhẩm."],["紙に書いて、計算しました。","Tôi đã viết ra giấy rồi tính."],["値段を計算します。","Tôi tính giá tiền."],["先生が計算を教えてくれました。","Thầy giáo đã dạy tôi cách tính."]]},{"word":"厚い","reading":"あつい","meaning":"Dày","hanViet":"HẬU","lesson":42,"ex":[["辞書は厚いです。","Từ điển dày."],["冬は厚いコートを着ます。","Mùa đông tôi mặc áo khoác dày."],["厚い本を読みました。","Tôi đã đọc cuốn sách dày."],["厚いセーターを買いました。","Tôi đã mua áo len dày."],["厚い紙を使います。","Tôi dùng giấy dày."]]},{"word":"薄い","reading":"うすい","meaning":"Mỏng, nhạt","hanViet":"BẠC","lesson":42,"ex":[["紙は薄いです。","Giấy mỏng."],["夏は薄いシャツを着ます。","Mùa hè tôi mặc áo sơ mi mỏng."],["コーヒーは薄いです。","Cà phê nhạt."],["お茶が薄いです。","Trà nhạt."],["薄い本を読みました。","Tôi đã đọc cuốn sách mỏng."]]},{"word":"弁護士","reading":"べんごし","meaning":"luật sư","hanViet":"BIỆN HỘ SĨ","lesson":42,"ex":[["弁護士は法律をよく知っています。","Luật sư hiểu rõ pháp luật."],["田中さんは有名な弁護士です。","Anh Tanaka là luật sư nổi tiếng."],["母は弁護士に仕事の問題を話しました。","Mẹ tôi đã kể vấn đề công việc với luật sư."],["弁護士になりたいですから、大学で法律を勉強します。","Vì muốn trở thành luật sư nên tôi học luật ở đại học."],["弟は弁護士になりたいと思っています。","Em trai tôi đang nghĩ muốn trở thành luật sư."]]},{"word":"音楽家","reading":"おんがくか","meaning":"nhạc sĩ","hanViet":"ÂM LẠC GIA","lesson":42,"ex":[["山田さんは有名な音楽家です。","Anh Yamada là nhạc sĩ nổi tiếng."],["音楽家はコンサートでピアノを弾きます。","Nhạc sĩ chơi piano trong buổi hòa nhạc."],["私は音楽家になりたいです。","Tôi muốn trở thành nhạc sĩ."],["音楽家の歌をテレビで聞きました。","Tôi đã nghe bài hát của nhạc sĩ trên TV."],["母は音楽家のコンサートの切符を買いました。","Mẹ tôi đã mua vé hòa nhạc của nhạc sĩ."]]},{"word":"教育","reading":"きょういく","meaning":"Giáo dục","hanViet":"GIÁO DỤC","lesson":42,"ex":[["子どもの教育はとても大切です。","Giáo dục trẻ em rất quan trọng."],["日本の教育を勉強します。","Tôi học giáo dục Nhật Bản."],["先生は教育の仕事が好きです。","Thầy giáo thích công việc giáo dục."],["母は子どもの教育を大切にします。","Mẹ tôi coi trọng việc giáo dục con cái."],["大学で教育を勉強するつもりです。","Tôi định học giáo dục ở đại học."]]},{"word":"文化","reading":"ぶんか","meaning":"Văn hoá","hanViet":"VĂN HÓA","lesson":42,"ex":[["日本の文化に興味があります。","Tôi có hứng thú với văn hóa Nhật Bản."],["外国の文化を勉強します。","Tôi học văn hóa nước ngoài."],["日本と外国の文化は違います。","Văn hóa Nhật Bản và nước ngoài khác nhau."],["音楽は日本の文化の一つです。","Âm nhạc là một nét văn hóa của Nhật Bản."],["母は日本の文化が好きです。","Mẹ tôi thích văn hóa Nhật Bản."]]},{"word":"社会","reading":"しゃかい","meaning":"Xã hội","hanViet":"XÃ HỘI","lesson":42,"ex":[["社会の問題を勉強します。","Tôi học các vấn đề của xã hội."],["社会は毎日変わります。","Xã hội thay đổi mỗi ngày."],["父は会社で社会の問題を話しました。","Bố tôi đã nói về vấn đề xã hội ở công ty."],["大学を卒業したら、社会で働きたいです。","Sau khi tốt nghiệp đại học, tôi muốn làm việc trong xã hội."],["社会で日本語を使うことができます。","Tôi có thể dùng tiếng Nhật trong xã hội."]]},{"word":"法律","reading":"ほうりつ","meaning":"Pháp luật","hanViet":"PHÁP LUẬT","lesson":42,"ex":[["法律を守らなければなりません。","Phải tuân thủ pháp luật."],["大学で法律を勉強します。","Tôi học luật ở đại học."],["法律が変わりました。","Luật đã thay đổi."],["新しい法律の話を新聞で読みました。","Tôi đã đọc chuyện về luật mới trên báo."],["子どもも法律を守らなければなりません。","Trẻ em cũng phải tuân thủ pháp luật."]]},{"word":"戦争","reading":"せんそう","meaning":"Chiến tranh","hanViet":"CHIẾN TRANH","lesson":42,"ex":[["戦争は悲しいです。","Chiến tranh thật buồn."],["昔、日本で戦争がありました。","Ngày xưa, ở Nhật Bản đã có chiến tranh."],["戦争の映画を見ました。","Tôi đã xem phim về chiến tranh."],["戦争の本を読みました。","Tôi đã đọc sách về chiến tranh."],["戦争がない世界がいいです。","Một thế giới không có chiến tranh thì tốt."]]},{"word":"平和","reading":"へいわ","meaning":"Hoà bình","hanViet":"BÌNH HÒA","lesson":42,"ex":[["平和は大切です。","Hòa bình rất quan trọng."],["世界の平和を守りたいです。","Tôi muốn bảo vệ hòa bình thế giới."],["平和な国に住みたいです。","Tôi muốn sống ở một đất nước hòa bình."],["平和な社会で働きたいです。","Tôi muốn làm việc trong một xã hội hòa bình."],["平和を学校で勉強しました。","Tôi đã học về hòa bình ở trường."]]},{"word":"目的","reading":"もくてき","meaning":"Mục đích","hanViet":"MỤC ĐÍCH","lesson":42,"ex":[["日本語を勉強する目的は何ですか。","Mục đích học tiếng Nhật của bạn là gì?"],["私の目的は日本で働くことです。","Mục đích của tôi là làm việc ở Nhật Bản."],["旅行の目的は日本の文化を見ることです。","Mục đích của chuyến du lịch là xem văn hóa Nhật Bản."],["目的を決めてから、勉強を始めました。","Sau khi quyết định mục đích, tôi đã bắt đầu học."],["目的のために、毎日日本語を勉強します。","Vì mục đích, tôi học tiếng Nhật mỗi ngày."]]},{"word":"安全","reading":"あんぜん","meaning":"An toàn","hanViet":"AN TOÀN","lesson":42,"ex":[["安全は一番大切です。","An toàn là quan trọng nhất."],["子どもの安全を守ります。","Tôi bảo vệ an toàn của trẻ em."],["安全な運転をしなければなりません。","Phải lái xe an toàn."],["夜の道も安全です。","Đường buổi tối cũng an toàn."],["安全のために、車をゆっくり運転します。","Vì an toàn, tôi lái xe chậm."]]},{"word":"論文","reading":"ろんぶん","meaning":"Luận văn, bài luận","hanViet":"LUẬN VĂN","lesson":42,"ex":[["大学で論文を書きます。","Tôi viết luận văn ở đại học."],["論文は長くて難しいです。","Luận văn dài và khó."],["先生に論文を見てもらいました。","Tôi đã nhờ thầy xem luận văn."],["論文を書くために、図書館で本を読みます。","Để viết luận văn, tôi đọc sách ở thư viện."],["卒業の前に、論文を出さなければなりません。","Trước khi tốt nghiệp, phải nộp luận văn."]]},{"word":"関係","reading":"かんけい","meaning":"Quan hệ, liên quan","hanViet":"QUAN HỆ","lesson":42,"ex":[["田中さんと山田さんは友達の関係です。","Anh Tanaka và anh Yamada có quan hệ bạn bè."],["仕事と健康は関係があります。","Công việc và sức khỏe có liên quan."],["母と私はいい関係です。","Mẹ và tôi có quan hệ tốt."],["仕事の問題は私と関係がありません。","Vấn đề công việc không liên quan đến tôi."],["家族の関係は大切です。","Quan hệ gia đình rất quan trọng."]]},{"word":"薬缶","reading":"やかん","meaning":"ấm đun nước","hanViet":"DƯỢC PHẪU","lesson":42,"ex":[["薬缶で湯を沸かします。","Tôi đun nước bằng ấm."],["台所に新しい薬缶があります。","Trong bếp có ấm đun nước mới."],["薬缶の湯でお茶を作ります。","Tôi pha trà bằng nước trong ấm."],["母は薬缶を買いました。","Mẹ tôi đã mua ấm đun nước."],["薬缶が古くなりましたから、新しいのを買います。","Vì ấm đã cũ nên tôi mua cái mới."]]},{"word":"栓抜き","reading":"せんぬき","meaning":"đồ khui nút chai","hanViet":"THUYÊN BẠT","lesson":42,"ex":[["栓抜きでビールの瓶を開けます。","Tôi mở chai bia bằng đồ khui nút chai."],["台所に栓抜きがあります。","Trong bếp có đồ khui nút chai."],["栓抜きが見つかりません。","Tôi không tìm thấy đồ khui nút chai."],["父は栓抜きを使います。","Bố tôi dùng đồ khui nút chai."],["新しい栓抜きを買いました。","Tôi đã mua đồ khui nút chai mới."]]},{"word":"缶詰","reading":"かんづめ","meaning":"Đồ hộp","hanViet":"PHẪU KHẤT","lesson":42,"ex":[["スーパーで魚の缶詰を買いました。","Tôi đã mua đồ hộp cá ở siêu thị."],["缶詰は長く置くことができます。","Đồ hộp có thể để được lâu."],["果物の缶詰を食べました。","Tôi đã ăn đồ hộp trái cây."],["母は缶詰を台所に置きました。","Mẹ tôi đã để đồ hộp trong bếp."],["缶詰は便利ですが、新しい魚のほうがおいしいです。","Đồ hộp tiện nhưng cá tươi ngon hơn."]]},{"word":"風呂敷","reading":"ふろしき","meaning":"khăn gói","hanViet":"PHONG LỮ PHU","lesson":42,"ex":[["風呂敷で荷物を包みます。","Tôi gói hành lý bằng khăn gói."],["母は風呂敷にお土産を包みました。","Mẹ tôi đã gói quà bằng khăn gói."],["風呂敷は日本の古いものです。","Khăn gói là đồ vật cổ của Nhật Bản."],["風呂敷を使えば、荷物がまとめやすいです。","Nếu dùng khăn gói thì dễ gom hành lý."],["赤い風呂敷を買いました。","Tôi đã mua khăn gói màu đỏ."]]},{"word":"算盤","reading":"そろばん","meaning":"bàn tính","hanViet":"TOÁN BÀN","lesson":42,"ex":[["子どもは学校で算盤を習います。","Trẻ em học bàn tính ở trường."],["算盤で計算します。","Tôi tính toán bằng bàn tính."],["昔の人は算盤を使いました。","Người ngày xưa đã dùng bàn tính."],["母は算盤が上手です。","Mẹ tôi giỏi bàn tính."],["算盤を買って、子どもにあげました。","Tôi đã mua bàn tính và tặng cho con."]]},{"word":"体温計","reading":"たいおんけい","meaning":"cặp nhiệt độ","hanViet":"THỂ ÔN KẾ","lesson":42,"ex":[["熱がありますから、体温計で熱を測ります。","Vì bị sốt nên tôi đo nhiệt độ bằng cặp nhiệt độ."],["体温計は病院にあります。","Cặp nhiệt độ có ở bệnh viện."],["母は体温計で子どもの熱を測りました。","Mẹ tôi đã đo nhiệt độ cho con bằng cặp nhiệt độ."],["新しい体温計を買いました。","Tôi đã mua cặp nhiệt độ mới."],["体温計が壊れました。","Cặp nhiệt độ đã hỏng."]]},{"word":"石","reading":"いし","meaning":"Hòn đá","hanViet":"THẠCH","lesson":42,"ex":[["公園に大きい石があります。","Trong công viên có hòn đá lớn."],["川で小さい石を拾いました。","Tôi đã nhặt hòn đá nhỏ ở sông."],["石は重いです。","Hòn đá nặng."],["子どもは石を投げてはいけません。","Trẻ em không được ném đá."],["海の石は白くてきれいです。","Đá ở biển trắng và đẹp."]]},{"word":"なぜ","reading":"なぜ","meaning":"tại sao","hanViet":"","lesson":42,"ex":[["なぜ日本語を勉強しますか。","Tại sao bạn học tiếng Nhật?"],["なぜきのう来ませんでしたか。","Tại sao hôm qua bạn không đến?"],["なぜ新しい本を買いましたか。","Tại sao bạn mua sách mới?"],["なぜ会社を休みましたか。","Tại sao bạn nghỉ làm?"],["なぜ夜は道が暗いですか。","Tại sao ban đêm đường tối?"]]},{"word":"国連","reading":"こくれん","meaning":"liên hiệp quốc","hanViet":"QUỐC LIÊN","lesson":42,"ex":[["国連は世界の平和を守ります。","Liên Hiệp Quốc bảo vệ hòa bình thế giới."],["国連の仕事は大切です。","Công việc của Liên Hiệp Quốc rất quan trọng."],["国連で会議があります。","Ở Liên Hiệp Quốc có hội nghị."],["国連の本を読みました。","Tôi đã đọc sách về Liên Hiệp Quốc."],["国連の話を学校で聞きました。","Tôi đã nghe chuyện về Liên Hiệp Quốc ở trường."]]},{"word":"鍋","reading":"なべ","meaning":"nồi, nồi lẩu","hanViet":"OA","lesson":42,"ex":[["鍋で野菜を煮ます。","Tôi nấu rau trong nồi."],["冬は鍋がおいしいです。","Mùa đông ăn lẩu ngon."],["母は新しい鍋を買いました。","Mẹ tôi đã mua nồi mới."],["鍋に肉と野菜を入れます。","Tôi cho thịt và rau vào nồi."],["台所に大きい鍋があります。","Trong bếp có nồi lớn."]]},{"word":"丼ぶり","reading":"どんぶり","meaning":"bát lớn, cơm tô","hanViet":"","lesson":42,"ex":[["丼ぶりにごはんを入れます。","Tôi cho cơm vào bát lớn."],["昼ごはんに丼ぶりを食べました。","Bữa trưa tôi đã ăn cơm tô."],["牛肉の丼ぶりはおいしいです。","Cơm tô thịt bò rất ngon."],["大きい丼ぶりを買いました。","Tôi đã mua bát lớn."],["母は丼ぶりに肉と野菜を入れました。","Mẹ tôi đã cho thịt và rau vào bát lớn."]]},{"word":"食品","reading":"しょくひん","meaning":"Thực phẩm","hanViet":"THỰC PHẨM","lesson":42,"ex":[["スーパーで食品を買います。","Tôi mua thực phẩm ở siêu thị."],["食品の値段が上がりました。","Giá thực phẩm đã tăng."],["新しい食品を食べたいです。","Tôi muốn ăn thực phẩm mới."],["食品は安全でなければなりません。","Thực phẩm phải an toàn."],["日本の食品は有名です。","Thực phẩm Nhật Bản nổi tiếng."]]},{"word":"調査","reading":"ちょうさ","meaning":"Điều tra, khảo sát","hanViet":"ĐIỀU TRA","lesson":42,"ex":[["会社で調査をします。","Tôi làm khảo sát ở công ty."],["調査の仕事は大変です。","Công việc khảo sát vất vả."],["市場調査をしました。","Tôi đã làm điều tra thị trường."],["調査のために、多くの人に会いました。","Để khảo sát, tôi đã gặp nhiều người."],["新しい調査を始めました。","Tôi đã bắt đầu khảo sát mới."]]},{"word":"～の代わりに","reading":"～のかわりに","meaning":"thay cho","hanViet":"ĐẠI","lesson":42,"ex":[["母の代わりに、スーパーへ行きました。","Tôi đã đi siêu thị thay cho mẹ."],["田中さんの代わりに、会議へ行きます。","Tôi đi họp thay anh Tanaka."],["肉の代わりに、魚を食べました。","Tôi đã ăn cá thay cho thịt."],["電車の代わりに、バスで会社へ行きました。","Tôi đã đi xe buýt đến công ty thay cho tàu điện."],["コーヒーの代わりに、お茶を飲みました。","Tôi đã uống trà thay cho cà phê."]]},{"word":"どこででも","reading":"どこででも","meaning":"bất cứ nơi nào","hanViet":"","lesson":42,"ex":[["日本の本はどこででも買えます。","Sách Nhật Bản mua ở đâu cũng được."],["どこででも日本語を勉強できます。","Học tiếng Nhật ở đâu cũng được."],["電話はどこででも使うことができます。","Điện thoại dùng ở đâu cũng được."],["どこででも音楽を聞くことができます。","Nghe nhạc ở đâu cũng được."],["インターネットはどこででも使えます。","Internet dùng ở đâu cũng được."]]},{"word":"綴じる","reading":"とじる","meaning":"ghim lại, đóng (tài liệu)","hanViet":"","lesson":42,"ex":[["紙を綴じて、本を作ります。","Tôi đóng giấy lại để làm sách."],["書類を綴じて、先生に出しました。","Tôi đã đóng tài liệu lại và nộp cho thầy."],["ホチキスで紙を綴じます。","Tôi ghim giấy bằng dập ghim."],["論文を綴じて、大学に出しました。","Tôi đã đóng luận văn lại và nộp cho trường đại học."],["宿題の紙を綴じました。","Tôi đã đóng giấy bài tập lại."]]},{"word":"挟みます","reading":"はさみます","meaning":"kẹp (vào giữa)","hanViet":"HIỆP","lesson":42,"ex":[["本に写真を挟みます。","Tôi kẹp ảnh vào sách."],["辞書に紙を挟みました。","Tôi đã kẹp giấy vào từ điển."],["本に切符を挟みました。","Tôi đã kẹp vé vào sách."],["ノートに写真を挟みます。","Tôi kẹp ảnh vào vở."],["本に花を挟みました。","Tôi đã kẹp hoa vào sách."]]},{"word":"留めます","reading":"とめます","meaning":"cố định lại","hanViet":"LƯU","lesson":42,"ex":[["ホチキスで紙を留めます。","Tôi ghim giấy bằng dập ghim."],["髪を留めます。","Tôi cố định tóc."],["ボタンを留めました。","Tôi đã cài nút."],["写真を壁に留めました。","Tôi đã cố định ảnh lên tường."],["封筒を糊で留めます。","Tôi dán phong bì bằng keo."]]},{"word":"張ります","reading":"はります","meaning":"dán","hanViet":"TRƯƠNG","lesson":42,"ex":[["壁にポスターを張ります。","Tôi dán áp phích lên tường."],["写真を壁に張りました。","Tôi đã dán ảnh lên tường."],["封筒に切手を張ります。","Tôi dán tem lên phong bì."],["紙を窓に張りました。","Tôi đã dán giấy lên cửa sổ."],["切手を封筒に張って、送りました。","Tôi đã dán tem lên phong bì và gửi đi."]]},{"word":"糊","reading":"のり","meaning":"keo dán","hanViet":"","lesson":42,"ex":[["糊で紙を張ります。","Tôi dán giấy bằng keo."],["糊を買いました。","Tôi đã mua keo dán."],["封筒に糊をつけます。","Tôi bôi keo lên phong bì."],["糊が無くなりました。","Đã hết keo dán."],["子どもは糊で紙を張るのが好きです。","Trẻ em thích dán giấy bằng keo."]]},{"word":"鉛筆削り","reading":"えんぴつけずり","meaning":"cái gọt bút chì","hanViet":"DIÊN BÚT TƯỚC","lesson":42,"ex":[["鉛筆削りを使います。","Tôi dùng cái gọt bút chì."],["学校で鉛筆削りを買いました。","Tôi đã mua cái gọt bút chì ở trường."],["鉛筆削りが壊れました。","Cái gọt bút chì đã hỏng."],["子どもは新しい鉛筆削りを買いたいです。","Đứa trẻ muốn mua cái gọt bút chì mới."],["鉛筆削りは机の上にあります。","Cái gọt bút chì ở trên bàn."]]},{"word":"消します","reading":"けします","meaning":"xóa","hanViet":"TIÊU","lesson":42,"ex":[["寝る前に電気を消します。","Trước khi ngủ, tôi tắt điện."],["テレビを消してください。","Hãy tắt TV."],["火を消しました。","Tôi đã dập lửa."],["間違いを消しました。","Tôi đã xóa lỗi sai."],["部屋を出るとき、電気を消します。","Khi ra khỏi phòng, tôi tắt điện."]]},{"word":"締めます","reading":"しめます","meaning":"siết chặt","hanViet":"ĐẾ","lesson":42,"ex":[["ネクタイを締めます。","Tôi thắt cà vạt."],["瓶のふたを締めます。","Tôi vặn chặt nắp chai."],["螺子を締めました。","Tôi đã siết chặt ốc vít."],["ドアを締めました。","Tôi đã đóng chặt cửa."],["ネクタイを締めて、会社へ行きます。","Tôi thắt cà vạt rồi đi làm."]]},{"word":"緩めます","reading":"ゆるめます","meaning":"nới lỏng","hanViet":"HOÃN","lesson":42,"ex":[["ネクタイを緩めます。","Tôi nới lỏng cà vạt."],["螺子を緩めました。","Tôi đã nới lỏng ốc vít."],["ひもを緩めました。","Tôi đã nới lỏng dây."],["暑いですから、ネクタイを緩めました。","Vì nóng nên tôi đã nới lỏng cà vạt."],["自転車の螺子を緩めて、直しました。","Tôi đã nới lỏng ốc vít xe đạp rồi sửa."]]},{"word":"螺子","reading":"ねじ","meaning":"ốc vít","hanViet":"","lesson":42,"ex":[["螺子をドライバーで締めます。","Tôi siết ốc vít bằng tua vít."],["自転車の螺子が取れました。","Ốc vít xe đạp đã tuột."],["機械の螺子が壊れました。","Ốc vít của máy đã hỏng."],["新しい螺子を買いました。","Tôi đã mua ốc vít mới."],["螺子を緩めて、機械を開けました。","Tôi đã nới ốc vít ra và mở máy."]]},{"word":"ミキサー","reading":"ミキサー","meaning":"máy trộn (mixer)","hanViet":"","lesson":42,"ex":[["ミキサーでジュースを作ります。","Tôi làm nước ép bằng máy trộn."],["ミキサーで果物と牛乳を混ぜます。","Tôi trộn trái cây và sữa bằng máy trộn."],["母は新しいミキサーを買いました。","Mẹ tôi đã mua máy trộn mới."],["ミキサーが壊れました。","Máy trộn đã hỏng."],["台所にミキサーがあります。","Trong bếp có máy trộn."]]},{"word":"ピラミッド","reading":"ピラミッド","meaning":"kim tự tháp","hanViet":"","lesson":42,"ex":[["ピラミッドはとても大きいです。","Kim tự tháp rất lớn."],["ピラミッドを見るために、外国へ旅行に行きました。","Để xem kim tự tháp, tôi đã đi du lịch nước ngoài."],["ピラミッドの写真を見ました。","Tôi đã xem ảnh kim tự tháp."],["ピラミッドは昔の建物です。","Kim tự tháp là công trình cổ."],["ピラミッドの本を読みました。","Tôi đã đọc sách về kim tự tháp."]]},{"word":"ローン","reading":"ローン","meaning":"tiền vay; trả góp","hanViet":"","lesson":42,"ex":[["家を買うために、ローンを借ります。","Để mua nhà, tôi vay tiền."],["車のローンを払います。","Tôi trả tiền vay mua xe."],["銀行でローンを借りました。","Tôi đã vay tiền ở ngân hàng."],["ローンを返すのは大変です。","Trả tiền vay thì vất vả."],["ローンで新しい家を買いました。","Tôi đã mua nhà mới bằng tiền vay."]]},{"word":"セット","reading":"セット","meaning":"bộ","hanViet":"","lesson":42,"ex":[["食器のセットを買いました。","Tôi đã mua bộ đồ ăn."],["コップのセットをプレゼントしました。","Tôi đã tặng bộ cốc."],["3つのセットを買いました。","Tôi đã mua 3 bộ."],["セットは安いです。","Mua theo bộ thì rẻ."],["新しいセットを使います。","Tôi dùng bộ mới."]]},{"word":"のし袋","reading":"のしぶくろ","meaning":"phong bì bỏ tiền mừng, bao lì xì","hanViet":"ĐÁI","lesson":42,"ex":[["のし袋にお金を入れます。","Tôi bỏ tiền vào bao lì xì."],["結婚のお祝いにのし袋をあげました。","Tôi đã tặng bao lì xì mừng cưới."],["のし袋を買いました。","Tôi đã mua bao lì xì."],["お正月にのし袋をもらいました。","Tôi đã nhận bao lì xì vào dịp Tết."],["のし袋にお金を入れて、友達にあげました。","Tôi đã bỏ tiền vào bao lì xì và tặng bạn."]]},{"word":"政治","reading":"せいじ","meaning":"Chính trị","hanViet":"CHÍNH TRỊ","lesson":42,"ex":[["政治のニュースを見ます。","Tôi xem tin tức chính trị."],["政治に興味があります。","Tôi có hứng thú với chính trị."],["政治を勉強します。","Tôi học chính trị."],["新聞で政治の話を読みました。","Tôi đã đọc chuyện chính trị trên báo."],["父は政治の話が好きです。","Bố tôi thích nói chuyện chính trị."]]},{"word":"アパート","reading":"アパート","meaning":"phòng trọ","hanViet":"","lesson":42,"ex":[["私はアパートに住んでいます。","Tôi đang sống ở phòng trọ."],["新しいアパートを借りました。","Tôi đã thuê phòng trọ mới."],["アパートは駅の近くにあります。","Phòng trọ ở gần ga."],["アパートの家賃は安いです。","Tiền thuê phòng trọ rẻ."],["友達のアパートへ行きました。","Tôi đã đến phòng trọ của bạn."]]},{"word":"国際連合","reading":"こくさいれんごう","meaning":"liên hiệp quốc","hanViet":"QUỐC TẾ LIÊN HỢP","lesson":42,"ex":[["国際連合には多くの国があります。","Liên Hiệp Quốc có nhiều nước."],["国際連合は1945年に始まりました。","Liên Hiệp Quốc bắt đầu năm 1945."],["国際連合のニュースをテレビで見ました。","Tôi đã xem tin tức về Liên Hiệp Quốc trên TV."],["国際連合は平和のために働きます。","Liên Hiệp Quốc làm việc vì hòa bình."],["国際連合の話を先生がしました。","Thầy đã kể chuyện về Liên Hiệp Quốc."]]},{"word":"ポーランド","reading":"ポーランド","meaning":"Ba Lan","hanViet":"","lesson":42,"ex":[["ポーランドは寒い国です。","Ba Lan là đất nước lạnh."],["ポーランドへ旅行に行きたいです。","Tôi muốn đi du lịch Ba Lan."],["ポーランドの友達がいます。","Tôi có bạn ở Ba Lan."],["ポーランドの料理を食べました。","Tôi đã ăn món Ba Lan."],["ポーランドの話を友達から聞きました。","Tôi đã nghe bạn kể chuyện về Ba Lan."]]},{"word":"カップラーメン","reading":"カップラーメン","meaning":"mì ăn liền","hanViet":"","lesson":42,"ex":[["カップラーメンに湯を注ぎます。","Tôi đổ nước nóng vào mì ly."],["夜、カップラーメンを食べました。","Buổi tối, tôi đã ăn mì ly."],["カップラーメンは便利です。","Mì ly tiện lợi."],["カップラーメンを作るのは簡単です。","Làm mì ly thì dễ."],["スーパーでカップラーメンを買いました。","Tôi đã mua mì ly ở siêu thị."]]},{"word":"インスタントラーメン","reading":"インスタントラーメン","meaning":"mì ăn liền","hanViet":"","lesson":42,"ex":[["インスタントラーメンは便利です。","Mì ăn liền tiện lợi."],["インスタントラーメンに湯を注ぎます。","Tôi đổ nước nóng vào mì ăn liền."],["夜、インスタントラーメンを食べました。","Buổi tối, tôi đã ăn mì ăn liền."],["インスタントラーメンは安いです。","Mì ăn liền rẻ."],["世界初のインスタントラーメンはチキンラーメンです。","Mì ăn liền đầu tiên trên thế giới là Chicken Ramen."]]},{"word":"カップ","reading":"カップ","meaning":"tách; chén","hanViet":"","lesson":42,"ex":[["カップにコーヒーを注ぎます。","Tôi rót cà phê vào tách."],["新しいカップを買いました。","Tôi đã mua tách mới."],["カップが割れました。","Tách đã vỡ."],["カップにお茶を入れます。","Tôi cho trà vào tách."],["赤いカップが好きです。","Tôi thích tách màu đỏ."]]},{"word":"どのくらい","reading":"どのくらい","meaning":"bao nhiêu","hanViet":"","lesson":42,"ex":[["東京までどのくらいかかりますか。","Đến Tokyo mất bao lâu?"],["辞書はどのくらいですか。","Từ điển giá bao nhiêu?"],["日本語をどのくらい勉強しましたか。","Bạn đã học tiếng Nhật bao lâu rồi?"],["駅までどのくらい歩きますか。","Đi bộ đến ga mất bao lâu?"],["どのくらい待ちますか。","Phải đợi bao lâu?"]]},{"word":"エリーゼのために","reading":"エリーゼのために","meaning":"Dành cho Elise (tên bản nhạc)","hanViet":"","lesson":42,"ex":[["「エリーゼのために」は有名な曲です。","“Dành cho Elise” là bản nhạc nổi tiếng."],["ピアノで「エリーゼのために」を弾きます。","Tôi chơi “Dành cho Elise” bằng piano."],["「エリーゼのために」を練習します。","Tôi luyện tập “Dành cho Elise”."],["「エリーゼのために」はベートーベンが作りました。","“Dành cho Elise” do Beethoven sáng tác."],["「エリーゼのために」を聞くのが好きです。","Tôi thích nghe “Dành cho Elise”."]]},{"word":"ベートーベン","reading":"ベートーベン","meaning":"Beethoven (1770-1827), nhà soạn nhạc người Đức","hanViet":"","lesson":42,"ex":[["ベートーベンは有名な音楽家です。","Beethoven là nhạc sĩ nổi tiếng."],["ベートーベンはドイツの音楽家です。","Beethoven là nhạc sĩ người Đức."],["ベートーベンは「エリーゼのために」を作りました。","Beethoven đã sáng tác “Dành cho Elise”."],["ベートーベンの曲をピアノで弾きます。","Tôi chơi nhạc của Beethoven bằng piano."],["ベートーベンの音楽が好きです。","Tôi thích nhạc của Beethoven."]]},{"word":"こどもニュース","reading":"こどもニュース","meaning":"Bản tin thiếu nhi (chương trình tin tức giả định)","hanViet":"","lesson":42,"ex":[["子どもはこどもニュースを見ます。","Trẻ em xem bản tin thiếu nhi."],["こどもニュースはテレビの番組です。","Bản tin thiếu nhi là chương trình TV."],["こどもニュースは子どもにいいです。","Bản tin thiếu nhi tốt cho trẻ em."],["毎日、こどもニュースを見ます。","Tôi xem bản tin thiếu nhi mỗi ngày."],["こどもニュースで天気を知りました。","Tôi đã biết thời tiết qua bản tin thiếu nhi."]]},{"word":"カップめん","reading":"カップめん","meaning":"mì ly, mì ăn liền đựng trong cốc","hanViet":"","lesson":42,"ex":[["会社でカップめんを食べました。","Tôi đã ăn mì ly ở công ty."],["カップめんに湯を注いで、3分待ちます。","Tôi đổ nước nóng vào mì ly và đợi 3 phút."],["忙しいとき、カップめんを食べます。","Khi bận, tôi ăn mì ly."],["カップめんは安くて便利です。","Mì ly rẻ và tiện lợi."],["弟はカップめんが好きです。","Em trai tôi thích mì ly."]]},{"word":"世界初","reading":"せかいはつ","meaning":"đầu tiên trên thế giới","hanViet":"THẾ GIỚI SƠ","lesson":42,"ex":[["チキンラーメンは世界初のインスタントラーメンです。","Chicken Ramen là mì ăn liền đầu tiên trên thế giới."],["世界初のカップラーメンは日本で作られました。","Mì ly đầu tiên trên thế giới được làm ở Nhật Bản."],["日本は世界初の新幹線を作りました。","Nhật Bản đã làm tàu cao tốc đầu tiên trên thế giới."],["世界初のカップめんは1971年に売られました。","Mì ly đầu tiên trên thế giới được bán năm 1971."],["世界初のものを作りたいです。","Tôi muốn làm ra thứ đầu tiên trên thế giới."]]},{"word":"めん","reading":"めん","meaning":"mì sợi","hanViet":"","lesson":42,"ex":[["めんを食べます。","Tôi ăn mì."],["うどんは日本のめんです。","Udon là mì của Nhật Bản."],["店でめんを食べました。","Tôi đã ăn mì ở quán."],["めんを作るのは簡単です。","Làm mì thì dễ."],["昼にめんを食べました。","Buổi trưa tôi đã ăn mì."]]},{"word":"広めます","reading":"ひろめます","meaning":"nhân rộng, mở rộng","hanViet":"QUẢNG","lesson":42,"ex":[["日本語を世界に広めます。","Tôi truyền bá tiếng Nhật ra thế giới."],["日本の文化を広めたいです。","Tôi muốn truyền bá văn hóa Nhật Bản."],["音楽を広める仕事をしています。","Tôi làm công việc truyền bá âm nhạc."],["インターネットでニュースを広めます。","Tôi lan truyền tin tức qua internet."],["友達に日本の歌を広めました。","Tôi đã giới thiệu bài hát Nhật Bản cho bạn."]]},{"word":"市場調査","reading":"しじょうちょうさ","meaning":"điều tra thị trường","hanViet":"THỊ TRƯỜNG ĐIỀU TRA","lesson":42,"ex":[["会社で市場調査をします。","Tôi làm điều tra thị trường ở công ty."],["市場調査の仕事は大変です。","Công việc điều tra thị trường vất vả."],["新しいものを売る前に、市場調査をします。","Trước khi bán thứ mới, tôi làm điều tra thị trường."],["市場調査で人の意見を聞きます。","Tôi nghe ý kiến mọi người qua điều tra thị trường."],["市場調査が終わりました。","Điều tra thị trường đã xong."]]},{"word":"割ります","reading":"わります","meaning":"bẻ ra, chia nhỏ","hanViet":"CÁT","lesson":42,"ex":[["卵を割ります。","Tôi đập trứng."],["ガラスを割ってはいけません。","Không được làm vỡ kính."],["コップを割りました。","Tôi đã làm vỡ cốc."],["チョコレートを割って、友達にあげました。","Tôi đã bẻ sô cô la và cho bạn."],["卵を割って、料理を作ります。","Tôi đập trứng và nấu ăn."]]},{"word":"注ぎます","reading":"そそぎます","meaning":"đổ vào","hanViet":"CHÚ","lesson":42,"ex":[["コーヒーをカップに注ぎます。","Tôi rót cà phê vào tách."],["湯をカップラーメンに注ぎます。","Tôi đổ nước nóng vào mì ly."],["お茶をカップに注ぎました。","Tôi đã rót trà vào tách."],["ビールをコップに注ぎます。","Tôi rót bia vào cốc."],["湯を注いで、お茶を作ります。","Tôi đổ nước nóng và pha trà."]]},{"word":"チキンラーメン","reading":"チキンラーメン","meaning":"tên của một loại mì ăn liền","hanViet":"","lesson":42,"ex":[["チキンラーメンは1958年に売られました。","Chicken Ramen được bán năm 1958."],["チキンラーメンに湯を注ぎます。","Tôi đổ nước nóng vào Chicken Ramen."],["夜、チキンラーメンを食べました。","Buổi tối, tôi đã ăn Chicken Ramen."],["チキンラーメンは安藤百福が作りました。","Chicken Ramen do Ando Momofuku sáng tạo."],["チキンラーメンは有名です。","Chicken Ramen nổi tiếng."]]},{"word":"安藤百福","reading":"あんどうももふく","meaning":"nhà kinh doanh, nhà phát minh người Nhật (1910-2007)","hanViet":"AN ĐẰNG BÁCH PHÚC","lesson":42,"ex":[["安藤百福はチキンラーメンを作りました。","Ando Momofuku đã sáng tạo ra Chicken Ramen."],["安藤百福は有名な日本の人です。","Ando Momofuku là người Nhật nổi tiếng."],["安藤百福はインスタントラーメンを作りました。","Ando Momofuku đã sáng tạo ra mì ăn liền."],["安藤百福の本を読みました。","Tôi đã đọc sách về Ando Momofuku."],["安藤百福は会社を作りました。","Ando Momofuku đã lập công ty."]]},{"word":"増えます","reading":"ふえます","meaning":"tăng, tăng lên","hanViet":"TĂNG","lesson":43,"ex":[["東京の人が増えました。","Người ở Tokyo đã tăng."],["車が増えました。","Xe ô tô đã tăng."],["仕事が増えました。","Công việc đã tăng."],["人口が増えています。","Dân số đang tăng."],["お金が増えました。","Tiền đã tăng."]]},{"word":"減ります","reading":"へります","meaning":"giảm, giảm xuống","hanViet":"GIẢM","lesson":43,"ex":[["人が減りました。","Người đã giảm."],["車が減りました。","Xe ô tô đã giảm."],["お金が減りました。","Tiền đã giảm."],["仕事が減りました。","Công việc đã giảm."],["人口が減っています。","Dân số đang giảm."]]},{"word":"上がります","reading":"あがります","meaning":"tăng, tăng lên (giá)","hanViet":"THƯỢNG","lesson":43,"ex":[["値段が上がりました。","Giá đã tăng."],["家賃が上がりました。","Tiền thuê nhà đã tăng."],["熱が上がりました。","Sốt đã tăng."],["物価が上がっています。","Giá cả đang tăng."],["本の値段が上がりました。","Giá sách đã tăng."]]},{"word":"下がります","reading":"さがります","meaning":"giảm, giảm xuống (giá)","hanViet":"HẠ","lesson":43,"ex":[["値段が下がりました。","Giá đã giảm."],["給料が下がりました。","Lương đã giảm."],["熱が下がりました。","Sốt đã giảm."],["物価が下がっています。","Giá cả đang giảm."],["食品の値段が下がりました。","Giá thực phẩm đã giảm."]]},{"word":"切れます","reading":"きれます","meaning":"đứt","hanViet":"THIẾT","lesson":43,"ex":[["靴のひもが切れました。","Dây giày đã đứt."],["電気が切れました。","Điện đã mất."],["電話が切れました。","Điện thoại đã bị ngắt."],["紙が切れました。","Giấy đã rách."],["ひもが切れそうです。","Dây sắp đứt."]]},{"word":"取れます","reading":"とれます","meaning":"tuột","hanViet":"THỦ","lesson":43,"ex":[["ボタンが取れました。","Nút đã tuột."],["ふたが取れました。","Nắp đã tuột."],["かばんのボタンが取れました。","Nút của cặp đã tuột."],["写真が壁から取れました。","Ảnh đã rơi khỏi tường."],["ボタンが取れそうです。","Nút sắp tuột."]]},{"word":"落ちます","reading":"おちます","meaning":"rơi","hanViet":"LẠC","lesson":43,"ex":[["財布が落ちました。","Ví đã rơi."],["鍵が落ちました。","Chìa khóa đã rơi."],["木からりんごが落ちました。","Táo đã rơi từ trên cây."],["帽子が落ちました。","Mũ đã rơi."],["本が机から落ちました。","Sách đã rơi khỏi bàn."]]},{"word":"無くなります","reading":"なくなります","meaning":"mất, hết (xăng)","hanViet":"VÔ","lesson":43,"ex":[["お金が無くなりました。","Tôi đã hết tiền."],["ガソリンが無くなりました。","Đã hết xăng."],["時間が無くなりました。","Đã hết thời gian."],["食べ物が無くなりました。","Đã hết đồ ăn."],["紙が無くなりました。","Đã hết giấy."]]},{"word":"丈夫","reading":"じょうぶ","meaning":"khỏe mạnh, chắc chắn","hanViet":"TRƯỢNG PHU","lesson":43,"ex":[["私は体が丈夫です。","Tôi có cơ thể khỏe mạnh."],["靴は丈夫で、長く使えます。","Giày chắc chắn, dùng được lâu."],["かばんは丈夫です。","Cặp chắc chắn."],["子どもは丈夫です。","Đứa trẻ khỏe mạnh."],["自転車は丈夫です。","Xe đạp chắc chắn."]]},{"word":"変","reading":"へん","meaning":"lạ, kì quặc","hanViet":"BIẾN","lesson":43,"ex":[["変な音がします。","Có âm thanh lạ."],["変な味がします。","Có vị lạ."],["変な天気が続いています。","Thời tiết lạ cứ tiếp diễn."],["変な人が来ました。","Người kỳ lạ đã đến."],["変な様子です。","Trông có vẻ lạ."]]},{"word":"幸せ","reading":"しあわせ","meaning":"Hạnh phúc","hanViet":"HẠNH","lesson":43,"ex":[["私は幸せです。","Tôi hạnh phúc."],["幸せな家族です。","Gia đình hạnh phúc."],["結婚して、幸せになりました。","Kết hôn rồi, tôi đã trở nên hạnh phúc."],["幸せな時間を大切にします。","Tôi trân trọng thời gian hạnh phúc."],["子どもの幸せが一番大切です。","Hạnh phúc của con trẻ là quan trọng nhất."]]},{"word":"美味い","reading":"うまい","meaning":"ngon","hanViet":"MỸ VỊ","lesson":43,"ex":[["うどんが美味いです。","Udon ngon."],["母の料理は美味いです。","Món ăn của mẹ ngon."],["店の魚は美味いです。","Cá ở quán ngon."],["ごはんが美味いです。","Cơm ngon."],["肉が美味いです。","Thịt ngon."]]},{"word":"不味い","reading":"まずい","meaning":"dở","hanViet":"BẤT VỊ","lesson":43,"ex":[["料理が不味いです。","Món ăn dở."],["コーヒーが不味いです。","Cà phê dở."],["薬は不味いです。","Thuốc đắng."],["ごはんが不味いです。","Cơm dở."],["味が不味いです。","Vị dở."]]},{"word":"詰まらない","reading":"つまらない","meaning":"buồn tẻ, không hấp dẫn, không thú vị","hanViet":"KHẤT","lesson":43,"ex":[["映画が詰まらないです。","Phim chán."],["本が詰まらないです。","Sách chán."],["テレビが詰まらないです。","TV chán."],["話が詰まらないです。","Câu chuyện chán."],["授業が詰まらないです。","Tiết học chán."]]},{"word":"暖房","reading":"だんぼう","meaning":"Hệ thống sưởi, máy sưởi","hanViet":"NOÃN PHÒNG","lesson":43,"ex":[["冬は暖房をつけます。","Mùa đông tôi bật máy sưởi."],["暖房を消しました。","Tôi đã tắt máy sưởi."],["暖房が壊れました。","Máy sưởi đã hỏng."],["部屋に暖房があります。","Trong phòng có máy sưởi."],["暖房の部屋は暖かいです。","Phòng có máy sưởi thì ấm."]]},{"word":"冷房","reading":"れいぼう","meaning":"Điều hoà (chế độ lạnh)","hanViet":"LÃNH PHÒNG","lesson":43,"ex":[["夏は冷房が強すぎて、部屋が寒くなります。","Mùa hè điều hòa bật mạnh quá nên phòng trở nên lạnh."],["冷房をつけてもいいですか。","Tôi bật điều hòa được không?"],["電車の冷房は涼しくて、気持ちがいいです。","Điều hòa trên tàu mát mẻ, dễ chịu."],["母は夜、冷房を消して寝ます。","Buổi tối mẹ tắt điều hòa rồi đi ngủ."],["冷房のスイッチはどこですか。","Công tắc điều hòa ở đâu?"]]},{"word":"今にも","reading":"いまにも","meaning":"(có vẻ sắp) ~ đến nơi","hanViet":"KIM","lesson":43,"ex":[["空が暗くなりました。今にも雨が降りそうです。","Trời đã tối sầm. Có vẻ sắp mưa đến nơi."],["赤ちゃんは今にも泣きそうです。","Em bé có vẻ sắp khóc đến nơi."],["父は疲れて、今にも寝そうです。","Bố mệt đến mức có vẻ sắp ngủ đến nơi."],["子どもは今にも笑いそうです。","Đứa trẻ có vẻ sắp cười đến nơi."],["電車は今にも出そうです。急いでください。","Tàu có vẻ sắp chạy đến nơi. Hãy nhanh lên."]]},{"word":"わあ","reading":"わあ","meaning":"ôi!","hanViet":"","lesson":43,"ex":[["わあ、きれいな花ですね。","Ôi, hoa đẹp quá nhỉ."],["わあ、このケーキは大きいですね。","Ôi, cái bánh này to quá nhỉ."],["わあ、海がきれいですね。","Ôi, biển đẹp quá nhỉ."],["わあ、雪がたくさん降っていますね。","Ôi, tuyết rơi nhiều quá nhỉ."],["わあ、星がたくさん見えますね。","Ôi, nhìn thấy nhiều sao quá nhỉ."]]},{"word":"会員","reading":"かいいん","meaning":"Hội viên, thành viên","hanViet":"HỘI VIÊN","lesson":43,"ex":[["私は図書館の会員です。","Tôi là hội viên của thư viện."],["会員になると、本を5冊借りられます。","Trở thành hội viên thì mượn được 5 cuốn sách."],["この店の会員は、服が安く買えます。","Hội viên của cửa hàng này mua quần áo với giá rẻ."],["会員になるのは難しいですか。","Trở thành hội viên có khó không?"],["会員でなければ、この部屋は使えません。","Nếu không phải hội viên thì không dùng được phòng này."]]},{"word":"適当","reading":"てきとう","meaning":"vừa phải, phù hợp; tùy tiện","hanViet":"THÍCH ĐƯƠNG","lesson":43,"ex":[["この服は私に適当な大きさです。","Bộ quần áo này có kích cỡ vừa với tôi."],["適当な時間に来てください。","Hãy đến vào thời gian phù hợp."],["弟は宿題を適当にします。","Em trai làm bài tập tùy tiện."],["この部屋は勉強に適当です。","Phòng này phù hợp để học."],["適当な答えを書かないでください。","Đừng viết câu trả lời tùy tiện."]]},{"word":"年齢","reading":"ねんれい","meaning":"Tuổi, tuổi tác","hanViet":"NIÊN LINH","lesson":43,"ex":[["年齢を教えてください。","Hãy cho tôi biết tuổi của bạn."],["彼女の年齢は25歳です。","Tuổi của cô ấy là 25 tuổi."],["子どもの年齢を知りません。","Tôi không biết tuổi của đứa trẻ."],["年齢が若い人は、よく走ります。","Người trẻ tuổi thường chạy nhiều."],["この本は年齢が高い人にも読みやすいです。","Cuốn sách này người lớn tuổi cũng dễ đọc."]]},{"word":"収入","reading":"しゅうにゅう","meaning":"Thu nhập","hanViet":"THÂU NHẬP","lesson":43,"ex":[["父の収入は母より多いです。","Thu nhập của bố nhiều hơn mẹ."],["収入が少ないので、新しい車は買えません。","Vì thu nhập ít nên không mua được xe mới."],["収入は毎月どのくらいですか。","Thu nhập mỗi tháng khoảng bao nhiêu?"],["兄は収入が多いです。","Anh trai tôi thu nhập cao."],["収入が多くなったら、大きい家に住みたいです。","Nếu thu nhập nhiều lên, tôi muốn sống ở nhà to."]]},{"word":"ぴったり","reading":"ぴったり","meaning":"vừa vặn, đúng","hanViet":"","lesson":43,"ex":[["この靴は私の足にぴったりです。","Đôi giày này vừa vặn với chân tôi."],["この帽子は頭にぴったり合います。","Chiếc mũ này vừa vặn với đầu."],["7時にぴったり来てください。","Hãy đến đúng 7 giờ."],["この服は妹にぴったりです。","Bộ quần áo này vừa vặn với em gái."],["答えがぴったり合いました。","Câu trả lời trùng khớp hoàn toàn."]]},{"word":"そのうえ","reading":"そのうえ","meaning":"thêm vào đó, hơn thế","hanViet":"","lesson":43,"ex":[["この部屋は広いです。そのうえ、静かです。","Phòng này rộng. Hơn nữa, còn yên tĩnh."],["田中さんは日本語が上手です。そのうえ、英語も話せます。","Anh Tanaka giỏi tiếng Nhật. Hơn nữa, còn nói được cả tiếng Anh."],["このレストランは安いです。そのうえ、料理がおいしいです。","Nhà hàng này rẻ. Hơn nữa, món ăn còn ngon."],["雨が降りました。そのうえ、風も強くなりました。","Trời đã mưa. Hơn nữa, gió còn mạnh lên."],["彼女は頭がいいです。そのうえ、親切です。","Cô ấy thông minh. Hơn nữa, còn tốt bụng."]]},{"word":"薔薇","reading":"ばら","meaning":"hoa hồng","hanViet":"","lesson":43,"ex":[["庭に赤い薔薇が咲いています。","Trong vườn có hoa hồng đỏ đang nở."],["母に薔薇の花をプレゼントしました。","Tôi đã tặng mẹ hoa hồng."],["薔薇の色は赤だけではありません。","Màu của hoa hồng không chỉ có màu đỏ."],["私は白い薔薇が好きです。","Tôi thích hoa hồng trắng."],["デパートで薔薇を3本買いました。","Tôi đã mua 3 bông hồng ở cửa hàng bách hóa."]]},{"word":"大人しい","reading":"おとなしい","meaning":"hiền lành, trầm tính","hanViet":"ĐẠI NHÂN","lesson":43,"ex":[["妹は大人しい子どもです。","Em gái tôi là đứa trẻ hiền lành."],["あの犬は大人しくて、かわいいです。","Con chó kia hiền lành và dễ thương."],["田中さんは大人しい人です。","Anh Tanaka là người trầm tính."],["授業中、子どもは大人しくしています。","Trong giờ học, đứa trẻ ngoan ngoãn."],["大人しい猫は、よく寝ます。","Con mèo hiền lành thường hay ngủ."]]},{"word":"厳しい","reading":"きびしい","meaning":"Nghiêm khắc; khắc nghiệt, gay gắt","hanViet":"NGHIÊM","lesson":43,"ex":[["私の先生はとても厳しいです。","Thầy giáo của tôi rất nghiêm khắc."],["冬の山はとても厳しいです。","Mùa đông trên núi rất khắc nghiệt."],["父は勉強に厳しいです。","Bố tôi nghiêm khắc trong việc học."],["厳しい試験でしたが、頑張りました。","Kỳ thi khó nhưng tôi đã cố gắng."],["母は厳しいですが、優しいです。","Mẹ tôi nghiêm khắc nhưng dịu dàng."]]},{"word":"気が長い","reading":"きがながい","meaning":"kiên nhẫn","hanViet":"KHÍ TRƯỜNG","lesson":43,"ex":[["父は気が長いので、子どもの話をよく聞きます。","Bố tôi kiên nhẫn nên thường lắng nghe con nói."],["先生は気が長くて、ゆっくり教えてくれます。","Thầy giáo kiên nhẫn, dạy tôi từ từ."],["気が長い人は、長い時間待てます。","Người kiên nhẫn có thể chờ lâu."],["祖父は気が長くて、釣りが好きです。","Ông tôi kiên nhẫn và thích câu cá."],["気が長い店員は、お客様の話をよく聞きます。","Nhân viên kiên nhẫn lắng nghe khách hàng kỹ."]]},{"word":"気が短い","reading":"きがみじかい","meaning":"nóng tính","hanViet":"KHÍ ĐOẢN","lesson":43,"ex":[["兄は気が短いので、待つのが嫌いです。","Anh trai tôi nóng tính nên ghét chờ đợi."],["気が短い人は、長い話が嫌いです。","Người nóng tính ghét những câu chuyện dài."],["父は気が短いですが、優しい人です。","Bố tôi nóng tính nhưng là người tốt bụng."],["気が短い人は、ゆっくり話せません。","Người nóng tính không thể nói chuyện từ từ."],["弟は気が短くて、宿題が嫌いです。","Em trai nóng tính nên ghét bài tập."]]},{"word":"気が強い","reading":"きがつよい","meaning":"cứng rắn, mạnh mẽ","hanViet":"KHÍ CƯỜNG","lesson":43,"ex":[["姉は気が強くて、だれにも負けません。","Chị gái tôi mạnh mẽ, không thua ai."],["気が強い人は、自分の意見を言います。","Người cứng rắn nói ra ý kiến của mình."],["彼女は気が強くて、いつも頑張ります。","Cô ấy cứng rắn và luôn cố gắng."],["気が強い人は、難しい仕事も頑張ります。","Người cứng rắn cũng cố gắng với công việc khó."],["母は気が強くて、家族を守ります。","Mẹ tôi mạnh mẽ và bảo vệ gia đình."]]},{"word":"気が弱い","reading":"きがよわい","meaning":"yếu đuối, nhút nhát","hanViet":"KHÍ NHƯỢC","lesson":43,"ex":[["弟は気が弱くて、犬が怖いです。","Em trai tôi nhút nhát nên sợ chó."],["気が弱い人は、よく泣きます。","Người yếu đuối thường hay khóc."],["妹は気が弱いですが、優しいです。","Em gái tôi nhút nhát nhưng dịu dàng."],["気が弱い子どもは、暗い部屋が怖いです。","Đứa trẻ nhút nhát sợ phòng tối."],["田中さんは気が弱いので、意見が言えません。","Anh Tanaka nhút nhát nên không nói được ý kiến."]]},{"word":"活発","reading":"かっぱつ","meaning":"sôi nổi, tích cực","hanViet":"HOẠT PHÁT","lesson":43,"ex":[["妹は活発な子どもです。","Em gái tôi là đứa trẻ sôi nổi."],["山田さんは活発で、スポーツが好きです。","Anh Yamada sôi nổi và thích thể thao."],["活発な犬は、よく走ります。","Con chó sôi nổi thường hay chạy."],["公園で子どもが活発に遊んでいます。","Ở công viên, trẻ con đang chơi đùa sôi nổi."],["彼女は活発で、よく話します。","Cô ấy sôi nổi và hay nói chuyện."]]},{"word":"誠実","reading":"せいじつ","meaning":"thành thật, chân thành","hanViet":"THÀNH THẬT","lesson":43,"ex":[["田中さんは誠実な人です。","Anh Tanaka là người thành thật."],["誠実な人は、うそをつきません。","Người thành thật không nói dối."],["社長は誠実に仕事をします。","Giám đốc làm việc chân thành."],["誠実な答えをしてください。","Hãy trả lời thành thật."],["誠実な友達は大切です。","Người bạn chân thành rất quý giá."]]},{"word":"我が侭","reading":"わがまま","meaning":"ích kỷ, bướng bỉnh","hanViet":"","lesson":43,"ex":[["弟は我が侭な子どもです。","Em trai tôi là đứa trẻ bướng bỉnh."],["我が侭な人は、自分のことだけ考えます。","Người ích kỷ chỉ nghĩ cho bản thân."],["彼女は我が侭ですが、かわいいです。","Cô ấy bướng bỉnh nhưng dễ thương."],["我が侭な子どもは、よく泣きます。","Đứa trẻ bướng bỉnh thường hay khóc."],["妹は我が侭で、よく母を困らせます。","Em gái bướng bỉnh, thường làm mẹ khó xử."]]},{"word":"真面目","reading":"まじめ","meaning":"Nghiêm túc, chăm chỉ","hanViet":"CHÂN DIỆN MỤC","lesson":43,"ex":[["田中さんは真面目な学生です。","Anh Tanaka là sinh viên nghiêm túc."],["真面目な人は、宿題を忘れません。","Người nghiêm túc không quên bài tập."],["姉は真面目に勉強します。","Chị gái tôi học chăm chỉ."],["真面目な社員は、会社に大切です。","Nhân viên nghiêm túc rất quan trọng với công ty."],["山田さんは真面目ですが、おもしろい人です。","Anh Yamada nghiêm túc nhưng là người thú vị."]]},{"word":"不真面目","reading":"ふまじめ","meaning":"không nghiêm túc","hanViet":"BẤT CHÂN DIỆN MỤC","lesson":43,"ex":[["不真面目な学生は、宿題をしません。","Học sinh không nghiêm túc không làm bài tập."],["弟は不真面目で、授業を聞きません。","Em trai tôi không nghiêm túc, không nghe giảng."],["不真面目な社員は、仕事を忘れます。","Nhân viên không nghiêm túc quên việc."],["不真面目に勉強してはいけません。","Không được học hành không nghiêm túc."],["不真面目な人は、約束を守りません。","Người không nghiêm túc không giữ lời hứa."]]},{"word":"頑固","reading":"がんこ","meaning":"bướng bỉnh, cố chấp","hanViet":"NGOAN CỐ","lesson":43,"ex":[["祖父は頑固な人です。","Ông tôi là người cố chấp."],["頑固な人は、意見を変えません。","Người cố chấp không thay đổi ý kiến."],["父は頑固で、医者の話を聞きません。","Bố tôi cố chấp, không nghe lời bác sĩ."],["頑固な子どもは、服を着ません。","Đứa trẻ bướng bỉnh không chịu mặc quần áo."],["頑固な人と話すのは難しいです。","Nói chuyện với người cố chấp rất khó."]]},{"word":"素直","reading":"すなお","meaning":"ngoan ngoãn, thẳng thắn","hanViet":"TỐ TRỰC","lesson":43,"ex":[["妹は素直な子どもです。","Em gái tôi là đứa trẻ ngoan ngoãn."],["素直な人は、人の話をよく聞きます。","Người thẳng thắn lắng nghe người khác kỹ."],["弟は素直に謝りました。","Em trai đã xin lỗi một cách thẳng thắn."],["素直な答えをしてください。","Hãy trả lời thẳng thắn."],["素直な犬は、よく言うことを聞きます。","Con chó ngoan ngoãn thường nghe lời."]]},{"word":"意地悪","reading":"いじわる","meaning":"xấu tính, hay bắt nạt","hanViet":"Ý ĐỊA ÁC","lesson":43,"ex":[["意地悪な子どもは、友達をいじめます。","Đứa trẻ xấu tính bắt nạt bạn bè."],["あの男の子は意地悪です。","Cậu bé kia xấu tính."],["意地悪なことを言わないでください。","Đừng nói những điều xấu tính."],["意地悪な人は、友達が少ないです。","Người xấu tính ít bạn bè."],["妹は意地悪なことをしません。","Em gái tôi không làm điều xấu tính."]]},{"word":"勝ち気","reading":"かちき","meaning":"hiếu thắng","hanViet":"THẮNG KHÍ","lesson":43,"ex":[["姉は勝ち気で、テニスが上手です。","Chị gái tôi hiếu thắng và giỏi tennis."],["勝ち気な人は、負けるのが嫌いです。","Người hiếu thắng ghét thua cuộc."],["勝ち気な子どもは、よく頑張ります。","Đứa trẻ hiếu thắng thường cố gắng nhiều."],["彼女は勝ち気ですが、優しいです。","Cô ấy hiếu thắng nhưng dịu dàng."],["勝ち気な社員は、よく働きます。","Nhân viên hiếu thắng làm việc chăm chỉ."]]},{"word":"神経質","reading":"しんけいしつ","meaning":"hay lo lắng, nhạy cảm","hanViet":"THẦN KINH CHẤT","lesson":43,"ex":[["母は神経質で、小さいことをよく心配します。","Mẹ tôi hay lo lắng, thường lo những chuyện nhỏ."],["神経質な人は、音が怖いです。","Người nhạy cảm sợ tiếng ồn."],["田中さんは神経質で、よく手を洗います。","Anh Tanaka nhạy cảm, thường rửa tay."],["神経質な子どもは、よく泣きます。","Đứa trẻ nhạy cảm thường hay khóc."],["神経質な人は、掃除をよくします。","Người nhạy cảm thường dọn dẹp nhiều."]]},{"word":"ガソリン","reading":"ガソリン","meaning":"xăng","hanViet":"","lesson":43,"ex":[["車にガソリンを入れます。","Tôi đổ xăng vào xe."],["車のガソリンがもうありません。","Xe không còn xăng nữa."],["ガソリンの値段が高いです。","Giá xăng cao."],["ガソリンを買いに行きました。","Tôi đã đi mua xăng."],["この車はガソリンをたくさん使います。","Chiếc xe này dùng nhiều xăng."]]},{"word":"センス","reading":"センス","meaning":"có khiếu, gu","hanViet":"","lesson":43,"ex":[["彼女はセンスがいいです。","Cô ấy có gu tốt."],["姉は服のセンスがいいです。","Chị gái tôi có gu ăn mặc tốt."],["田中さんは音楽のセンスがあります。","Anh Tanaka có khiếu âm nhạc."],["センスがいい店員に服を選んでもらいました。","Tôi đã nhờ nhân viên có gu tốt chọn quần áo."],["この部屋はセンスがいいです。","Phòng này có gu thẩm mỹ tốt."]]},{"word":"～と言います","reading":"～といいます","meaning":"tên là~/ được gọi là~","hanViet":"NGÔN","lesson":43,"ex":[["私の名前は田中と言います。","Tên tôi là Tanaka."],["この花は桜と言います。","Hoa này gọi là hoa anh đào."],["あの人は山田さんと言います。","Người kia tên là Yamada."],["この店は「さくら」と言います。","Cửa hàng này tên là \"Sakura\"."],["日本では、この料理を寿司と言います。","Ở Nhật, món này được gọi là sushi."]]},{"word":"ドライブ","reading":"ドライブ","meaning":"lái xe (đi chơi)","hanViet":"","lesson":43,"ex":[["週末に海へドライブに行きました。","Cuối tuần tôi đã lái xe đi biển."],["父はドライブが好きです。","Bố tôi thích lái xe đi chơi."],["山へドライブに行きませんか。","Cùng lái xe lên núi nhé?"],["ドライブの途中で、雨が降りました。","Đang lái xe thì trời mưa."],["友達とドライブをしました。","Tôi đã lái xe đi chơi với bạn."]]},{"word":"泣きます","reading":"なきます","meaning":"khóc","hanViet":"KHẤP","lesson":44,"ex":[["妹は怖くて、泣いています。","Em gái sợ quá nên đang khóc."],["映画を見て、泣きました。","Xem phim, tôi đã khóc."],["悲しいとき、泣きます。","Khi buồn, tôi khóc."],["子どもは転んで、泣きました。","Đứa trẻ ngã rồi khóc."],["泣かないでください。","Đừng khóc."]]},{"word":"笑います","reading":"わらいます","meaning":"cười","hanViet":"TIẾU","lesson":44,"ex":[["子どもが笑っています。","Đứa trẻ đang cười."],["おもしろい話を聞いて、笑いました。","Nghe chuyện thú vị, tôi đã cười."],["彼女はいつも笑います。","Cô ấy lúc nào cũng cười."],["笑わないでください。","Đừng cười."],["みんなで笑いました。","Mọi người cùng cười."]]},{"word":"乾きます","reading":"かわきます","meaning":"khô","hanViet":"CAN","lesson":44,"ex":[["タオルが乾きました。","Khăn đã khô."],["雨で濡れた服が乾きません。","Quần áo ướt vì mưa không khô."],["髪が乾きました。","Tóc đã khô."],["冬は洗濯物が乾きにくいです。","Mùa đông quần áo giặt khó khô."],["洗濯物は外で乾きます。","Quần áo giặt khô ở ngoài."]]},{"word":"濡れます","reading":"ぬれます","meaning":"ướt","hanViet":"","lesson":44,"ex":[["雨で服が濡れました。","Quần áo ướt vì mưa."],["傘がないので、濡れました。","Vì không có ô nên tôi bị ướt."],["子どもは川で遊んで、濡れました。","Đứa trẻ chơi ở sông nên bị ướt."],["靴が濡れています。","Giày đang bị ướt."],["雪で髪が濡れました。","Tóc ướt vì tuyết."]]},{"word":"滑ります","reading":"すべります","meaning":"trượt chân","hanViet":"HOẠT","lesson":44,"ex":[["雪の日は道が滑ります。","Ngày tuyết rơi đường trơn."],["階段で滑りました。","Tôi đã trượt chân ở cầu thang."],["濡れた床で滑らないように、気をつけてください。","Hãy cẩn thận để không trượt trên sàn ướt."],["子どもは雪の上で滑って、転びました。","Đứa trẻ trượt trên tuyết rồi ngã."],["雨の日は、道が滑りやすいです。","Ngày mưa đường dễ trơn."]]},{"word":"起きます","reading":"おきます","meaning":"xảy ra","hanViet":"KHỞI","lesson":44,"ex":[["事故が起きました。","Đã xảy ra tai nạn."],["地震が起きました。","Đã xảy ra động đất."],["夜に火事が起きました。","Ban đêm đã xảy ra hỏa hoạn."],["問題が起きたら、先生に言ってください。","Nếu có vấn đề xảy ra, hãy nói với thầy giáo."],["大きな問題が起きました。","Đã xảy ra vấn đề lớn."]]},{"word":"調節します","reading":"ちょうせつします","meaning":"điều chỉnh","hanViet":"ĐIỀU TIẾT","lesson":44,"ex":[["冷房を調節してください。","Hãy điều chỉnh điều hòa."],["テレビの音を調節します。","Tôi điều chỉnh âm lượng TV."],["自転車の高さを調節します。","Tôi điều chỉnh chiều cao xe đạp."],["暖房を調節して、部屋を暖かくします。","Tôi điều chỉnh máy sưởi để phòng ấm lên."],["時間を調節して、会議に行きます。","Tôi sắp xếp thời gian để đi họp."]]},{"word":"丁寧","reading":"ていねい","meaning":"lịch sự, cẩn thận, tử tế","hanViet":"ĐINH NINH","lesson":44,"ex":[["彼女は丁寧な人です。","Cô ấy là người lịch sự."],["丁寧に話してください。","Hãy nói chuyện lịch sự."],["店員は丁寧に教えてくれました。","Nhân viên đã chỉ cho tôi một cách tử tế."],["丁寧な字を書いてください。","Hãy viết chữ cẩn thận."],["丁寧な手紙を書きました。","Tôi đã viết thư cẩn thận."]]},{"word":"細かい","reading":"こまかい","meaning":"Nhỏ, li ti; chi tiết","hanViet":"TẾ","lesson":44,"ex":[["細かい字が読めません。","Tôi không đọc được chữ nhỏ."],["細かいお金がありません。","Tôi không có tiền lẻ."],["母は細かいことをよく注意します。","Mẹ tôi thường chú ý những việc nhỏ nhặt."],["細かい雨が降っています。","Mưa phùn đang rơi."],["細かいことを教えてください。","Hãy cho tôi biết chi tiết."]]},{"word":"濃い","reading":"こい","meaning":"Đậm, đặc, nồng","hanViet":"NỒNG","lesson":44,"ex":[["このコーヒーは濃いです。","Cà phê này đậm."],["濃いお茶が好きです。","Tôi thích trà đậm."],["このみそ汁は味が濃いです。","Món súp miso này đậm vị."],["濃い色の服を着ます。","Tôi mặc quần áo màu đậm."],["コーヒーが濃すぎます。","Cà phê đậm quá."]]},{"word":"空気","reading":"くうき","meaning":"Không khí","hanViet":"KHÔNG KHÍ","lesson":44,"ex":[["山の空気はきれいです。","Không khí trên núi trong lành."],["部屋の空気が悪いです。","Không khí trong phòng xấu."],["窓を開けて、空気を入れましょう。","Mở cửa sổ để không khí vào nào."],["朝の空気は涼しいです。","Không khí buổi sáng mát mẻ."],["空気がきれいな所に住みたいです。","Tôi muốn sống ở nơi không khí trong lành."]]},{"word":"涙","reading":"なみだ","meaning":"Nước mắt","hanViet":"LỆ","lesson":44,"ex":[["涙が出ました。","Nước mắt chảy ra."],["悲しい話を聞いて、涙が出ました。","Nghe chuyện buồn, nước mắt tôi chảy ra."],["子どもは涙をふきました。","Đứa trẻ lau nước mắt."],["涙が止まりません。","Nước mắt không ngừng rơi."],["涙が出そうです。","Tôi sắp khóc."]]},{"word":"和食","reading":"わしょく","meaning":"Món ăn Nhật","hanViet":"HÒA THỰC","lesson":44,"ex":[["和食が好きです。","Tôi thích món ăn Nhật."],["和食のレストランに行きました。","Tôi đã đi nhà hàng món Nhật."],["母は和食が上手です。","Mẹ tôi giỏi nấu món Nhật."],["和食は体にいいです。","Món Nhật tốt cho sức khỏe."],["和食と洋食と、どちらが好きですか。","Món Nhật và món Tây, bạn thích món nào hơn?"]]},{"word":"洋食","reading":"ようしょく","meaning":"Món ăn kiểu Tây","hanViet":"DƯƠNG THỰC","lesson":44,"ex":[["洋食が好きです。","Tôi thích món ăn kiểu Tây."],["洋食のレストランで昼ごはんを食べました。","Tôi đã ăn trưa ở nhà hàng món Tây."],["洋食はパンといっしょに食べます。","Món Tây ăn cùng bánh mì."],["母は洋食が上手です。","Mẹ tôi giỏi nấu món Tây."],["和食より洋食が好きです。","Tôi thích món Tây hơn món Nhật."]]},{"word":"おかず","reading":"おかず","meaning":"thức ăn","hanViet":"","lesson":44,"ex":[["おかずがたくさんあります。","Có nhiều thức ăn."],["ごはんとおかずを食べました。","Tôi đã ăn cơm và thức ăn."],["おかずは何ですか。","Thức ăn là gì?"],["母はおかずを作ります。","Mẹ tôi nấu thức ăn."],["おかずが足りません。","Thức ăn không đủ."]]},{"word":"量","reading":"りょう","meaning":"lượng","hanViet":"LƯỢNG","lesson":44,"ex":[["ごはんの量が少ないです。","Lượng cơm ít."],["量を半分にしてください。","Hãy giảm lượng xuống một nửa."],["この店は料理の量が多いです。","Cửa hàng này lượng món ăn nhiều."],["水の量を調節してください。","Hãy điều chỉnh lượng nước."],["量が多すぎます。","Lượng nhiều quá."]]},{"word":"～倍","reading":"～ばい","meaning":"lần","hanViet":"BỘI","lesson":44,"ex":[["このりんごはあれの2倍大きいです。","Quả táo này to gấp 2 lần quả kia."],["値段が3倍になりました。","Giá đã tăng gấp 3 lần."],["父の収入は私の2倍です。","Thu nhập của bố gấp 2 lần tôi."],["この部屋はあの部屋の2倍広いです。","Phòng này rộng gấp 2 lần phòng kia."],["弟は兄の2倍食べます。","Em trai ăn gấp 2 lần anh trai."]]},{"word":"半分","reading":"はんぶん","meaning":"Một nửa","hanViet":"BÁN PHÂN","lesson":44,"ex":[["ケーキを半分食べました。","Tôi đã ăn một nửa cái bánh."],["半分ください。","Cho tôi một nửa."],["お金を半分払いました。","Tôi đã trả một nửa số tiền."],["仕事が半分終わりました。","Công việc đã xong một nửa."],["りんごを半分に切りました。","Tôi đã cắt quả táo làm đôi."]]},{"word":"たんす","reading":"たんす","meaning":"tủ quần áo","hanViet":"","lesson":44,"ex":[["たんすに服を入れます。","Tôi cất quần áo vào tủ."],["たんすの中にシャツがあります。","Trong tủ có áo sơ mi."],["新しいたんすを買いました。","Tôi đã mua tủ quần áo mới."],["たんすの上に本を置きました。","Tôi đã đặt sách lên trên tủ."],["たんすを開けて、服を出しました。","Tôi mở tủ và lấy quần áo ra."]]},{"word":"洗濯物","reading":"せんたくもの","meaning":"Quần áo cần giặt","hanViet":"TẨY TRẠC VẬT","lesson":44,"ex":[["洗濯物が乾きました。","Quần áo giặt đã khô."],["洗濯物を洗濯機に入れます。","Tôi cho quần áo giặt vào máy giặt."],["洗濯物がたくさんあります。","Có nhiều quần áo cần giặt."],["洗濯物を部屋に入れました。","Tôi đã mang quần áo giặt vào phòng."],["雨で洗濯物が濡れました。","Quần áo giặt ướt vì mưa."]]},{"word":"理由","reading":"りゆう","meaning":"Lý do","hanViet":"LÝ DO","lesson":44,"ex":[["遅れた理由を教えてください。","Hãy cho tôi biết lý do đến muộn."],["理由を知りません。","Tôi không biết lý do."],["休んだ理由は何ですか。","Lý do nghỉ là gì?"],["理由を聞きました。","Tôi đã hỏi lý do."],["理由があって、早く帰りました。","Vì có lý do nên tôi về sớm."]]},{"word":"どうなさいますか","reading":"どうなさいますか","meaning":"Anh/chị định như thế nào?","hanViet":"","lesson":44,"ex":[["お飲み物はどうなさいますか。","Đồ uống anh/chị định thế nào?"],["ジュースはどうなさいますか。","Nước trái cây anh/chị định thế nào?"],["昼ごはんはどうなさいますか。","Bữa trưa anh/chị định thế nào?"],["部屋はどうなさいますか。シングルですか、ツインですか。","Phòng anh/chị định thế nào? Phòng đơn hay phòng đôi?"],["コーヒーと紅茶と、どうなさいますか。","Cà phê và hồng trà, anh/chị định thế nào?"]]},{"word":"どういうふうになさいますか","reading":"どういうふうになさいますか","meaning":"ông muốn làm ra sao?","hanViet":"","lesson":44,"ex":[["髪はどういうふうになさいますか。","Tóc ông muốn làm ra sao?"],["料理はどういうふうになさいますか。","Món ăn ông muốn làm ra sao?"],["部屋はどういうふうになさいますか。","Phòng ông muốn làm ra sao?"],["ケーキはどういうふうになさいますか。","Bánh ông muốn làm ra sao?"],["髪の色はどういうふうになさいますか。","Màu tóc ông muốn làm ra sao?"]]},{"word":"～みたいにしてください","reading":"～みたいにしてください","meaning":"xin làm giống như","hanViet":"","lesson":44,"ex":[["姉みたいにしてください。","Xin làm giống như chị gái tôi."],["この絵みたいにしてください。","Xin làm giống như bức tranh này."],["先生みたいにしてください。","Xin làm giống như thầy giáo."],["この色みたいにしてください。","Xin làm giống như màu này."],["母みたいにしてください。","Xin làm giống như mẹ tôi."]]},{"word":"これでよろしいでしょうか","reading":"これでよろしいでしょうか","meaning":"thế này được chưa ạ?","hanViet":"","lesson":44,"ex":[["これでよろしいでしょうか。","Thế này được chưa ạ?"],["髪はこれでよろしいでしょうか。","Tóc thế này được chưa ạ?"],["色はこれでよろしいでしょうか。","Màu thế này được chưa ạ?"],["長さはこれでよろしいでしょうか。","Độ dài thế này được chưa ạ?"],["これでよろしいでしょうか。もう少し短くしますか。","Thế này được chưa ạ? Cắt ngắn thêm chút nữa không?"]]},{"word":"嫌がります","reading":"いやがります","meaning":"không thích, tỏ thái độ không thích","hanViet":"HIỀM","lesson":44,"ex":[["子どもは野菜を嫌がります。","Đứa trẻ không thích rau."],["犬は水を嫌がります。","Con chó không thích nước."],["妹は勉強を嫌がります。","Em gái không thích học."],["猫はお風呂を嫌がります。","Con mèo không thích tắm."],["弟は歯を磨くのを嫌がります。","Em trai không thích đánh răng."]]},{"word":"順序","reading":"じゅんじょ","meaning":"Trình tự, thứ tự","hanViet":"THUẬN TỰ","lesson":44,"ex":[["順序を忘れました。","Tôi đã quên thứ tự."],["順序を教えてください。","Hãy cho tôi biết trình tự."],["正しい順序で並べてください。","Hãy xếp theo thứ tự đúng."],["順序が大切です。","Trình tự rất quan trọng."],["料理の順序を変えました。","Tôi đã thay đổi trình tự nấu ăn."]]},{"word":"表現","reading":"ひょうげん","meaning":"biểu hiện, diễn đạt","hanViet":"BIỂU HIỆN","lesson":44,"ex":[["日本語の表現を勉強します。","Tôi học cách diễn đạt tiếng Nhật."],["新しい表現を覚えました。","Tôi đã nhớ cách diễn đạt mới."],["この表現は難しいです。","Cách diễn đạt này khó."],["いい表現ですね。","Cách diễn đạt hay nhỉ."],["この表現はよくありません。","Cách diễn đạt này không tốt."]]},{"word":"別れます","reading":"わかれます","meaning":"chia cách; chia tay","hanViet":"BIỆT","lesson":44,"ex":[["駅で友達と別れました。","Tôi đã chia tay bạn ở ga."],["彼女と別れました。","Tôi đã chia tay bạn gái."],["学校で先生と別れました。","Tôi đã chia tay thầy giáo ở trường."],["空港で家族と別れました。","Tôi đã chia tay gia đình ở sân bay."],["別れるのは悲しいです。","Chia tay thật buồn."]]},{"word":"これら","reading":"これら","meaning":"những thứ này","hanViet":"","lesson":44,"ex":[["これらは私の本です。","Những thứ này là sách của tôi."],["これらは全部新しいです。","Những thứ này đều mới."],["これらをください。","Cho tôi những thứ này."],["これらは母からのプレゼントです。","Những thứ này là quà của mẹ."],["これらの写真を見てください。","Hãy xem những bức ảnh này."]]},{"word":"縁起が悪い","reading":"えんぎがわるい","meaning":"điềm xấu","hanViet":"DUYÊN KHỞI ÁC","lesson":44,"ex":[["「4」は縁起が悪いです。","Số \"4\" là điềm xấu."],["黒い猫は縁起が悪いと言います。","Người ta nói mèo đen là điềm xấu."],["この日は縁起が悪いです。","Ngày này là điềm xấu."],["縁起が悪いので、やめました。","Vì điềm xấu nên tôi đã dừng lại."],["縁起が悪いことを言わないでください。","Đừng nói điều xui xẻo."]]},{"word":"美容院","reading":"びよういん","meaning":"Tiệm làm tóc, salon","hanViet":"MỸ DUNG VIỆN","lesson":44,"ex":[["美容院で髪を切りました。","Tôi đã cắt tóc ở tiệm làm tóc."],["美容院を予約しました。","Tôi đã đặt lịch ở tiệm làm tóc."],["近くにいい美容院があります。","Gần đây có tiệm làm tóc tốt."],["母は美容院に行きました。","Mẹ tôi đã đi tiệm làm tóc."],["美容院の店員は親切です。","Nhân viên tiệm làm tóc tốt bụng."]]},{"word":"理髪店","reading":"りはつてん","meaning":"tiệm cắt tóc (nam)","hanViet":"LÝ PHÁT ĐIẾM","lesson":44,"ex":[["理髪店で髪を切りました。","Tôi đã cắt tóc ở tiệm cắt tóc nam."],["父は理髪店に行きます。","Bố tôi đi tiệm cắt tóc nam."],["理髪店で顔を剃りました。","Tôi đã cạo mặt ở tiệm cắt tóc nam."],["近くの理髪店は安いです。","Tiệm cắt tóc nam gần đây rẻ."],["理髪店を予約しました。","Tôi đã đặt lịch ở tiệm cắt tóc nam."]]},{"word":"剃る","reading":"そる","meaning":"cạo (râu)","hanViet":"","lesson":44,"ex":[["毎朝、顔を剃ります。","Mỗi sáng tôi cạo mặt."],["父は毎朝剃ります。","Bố tôi cạo mỗi sáng."],["理髪店で剃ってもらいました。","Tôi đã nhờ cạo ở tiệm cắt tóc nam."],["兄は頭を剃りました。","Anh trai tôi đã cạo đầu."],["剃るのは難しいです。","Cạo thì khó."]]},{"word":"耳が見えるくらいに切ってください","reading":"みみがみえるくらいにきってください","meaning":"xin cắt sao cho thấy tai","hanViet":"NHĨ KIẾN THIẾT","lesson":44,"ex":[["耳が見えるくらいに切ってください。","Xin cắt sao cho thấy tai."],["きょうは耳が見えるくらいに切ってください。","Hôm nay xin cắt sao cho thấy tai."],["夏なので、耳が見えるくらいに切ってください。","Vì mùa hè nên xin cắt sao cho thấy tai."],["耳が見えるくらいに切ってください。暑いですから。","Xin cắt sao cho thấy tai. Vì trời nóng."],["耳が見えるくらいに切ってください。短いほうがいいです。","Xin cắt sao cho thấy tai. Ngắn thì tốt hơn."]]},{"word":"肩にかかるくらいにきってください","reading":"かたにかかるくらいにきってください","meaning":"xin cắt dài đến vai","hanViet":"KIÊN","lesson":44,"ex":[["肩にかかるくらいにきってください。","Xin cắt dài đến vai."],["髪は肩にかかるくらいにきってください。","Tóc xin cắt dài đến vai."],["長さは肩にかかるくらいにきってください。","Độ dài xin cắt đến vai."],["肩にかかるくらいにきってください。長くしてください。","Xin cắt dài đến vai. Để dài nhé."],["きょうは肩にかかるくらいにきってください。","Hôm nay xin cắt dài đến vai."]]},{"word":"眉が隠れるくらいにきってください","reading":"まゆがかくれるくらいにきってください","meaning":"xin cắt sao cho che lông mày","hanViet":"MI ẨN","lesson":44,"ex":[["眉が隠れるくらいにきってください。","Xin cắt sao cho che lông mày."],["前は眉が隠れるくらいにきってください。","Phía trước xin cắt sao cho che lông mày."],["眉が隠れるくらいにきってください。長くしてください。","Xin cắt sao cho che lông mày. Để dài nhé."],["きょうは眉が隠れるくらいにきってください。","Hôm nay xin cắt sao cho che lông mày."],["眉が隠れるくらいにきってください。お願いします。","Xin cắt sao cho che lông mày. Nhờ anh/chị."]]},{"word":"１センチくらいきってください","reading":"いっセンチくらいきってください","meaning":"xin cắt khoảng 1 cm","hanViet":"","lesson":44,"ex":[["１センチくらいきってください。","Xin cắt khoảng 1 cm."],["髪を１センチくらいきってください。","Xin cắt tóc khoảng 1 cm."],["前を１センチくらいきってください。","Phía trước xin cắt khoảng 1 cm."],["１センチくらいきってください。短くしすぎないでください。","Xin cắt khoảng 1 cm. Đừng cắt ngắn quá."],["きょうは１センチくらいきってください。","Hôm nay xin cắt khoảng 1 cm."]]},{"word":"この写真みたいに切ってください","reading":"このしゃしんみたいにきってください","meaning":"xin cắt giống như trong ảnh này","hanViet":"TẢ CHÂN THIẾT","lesson":44,"ex":[["この写真みたいに切ってください。","Xin cắt giống như trong ảnh này."],["髪をこの写真みたいに切ってください。","Xin cắt tóc giống như trong ảnh này."],["この写真みたいに切ってください。お願いします。","Xin cắt giống như trong ảnh này. Nhờ anh/chị."],["きょうはこの写真みたいに切ってください。","Hôm nay xin cắt giống như trong ảnh này."],["前をこの写真みたいに切ってください。","Phía trước xin cắt giống như trong ảnh này."]]},{"word":"おかっぱ","reading":"おかっぱ","meaning":"tóc bob (ngang vai)","hanViet":"","lesson":44,"ex":[["妹はおかっぱです。","Em gái tôi để tóc bob."],["おかっぱにしてください。","Xin cắt tóc bob."],["おかっぱは彼女にぴったりです。","Tóc bob rất hợp với cô ấy."],["子どもはおかっぱがかわいいです。","Trẻ con để tóc bob dễ thương."],["おかっぱの女の子がいます。","Có cô bé tóc bob."]]},{"word":"三つ編み","reading":"みつあみ","meaning":"tóc tết ba","hanViet":"TAM BIÊN","lesson":44,"ex":[["妹は三つ編みをしています。","Em gái tôi đang tết tóc ba."],["三つ編みにしてください。","Xin tết tóc ba."],["彼女は三つ編みが上手です。","Cô ấy giỏi tết tóc ba."],["三つ編みの女の子がいます。","Có cô bé tóc tết ba."],["母は三つ編みをしてくれました。","Mẹ đã tết tóc ba cho tôi."]]},{"word":"丸刈り","reading":"まるがり","meaning":"cắt đầu đinh","hanViet":"HOÀN NGẢI","lesson":44,"ex":[["兄は丸刈りです。","Anh trai tôi cắt đầu đinh."],["丸刈りにしてください。","Xin cắt đầu đinh."],["夏は丸刈りが涼しいです。","Mùa hè đầu đinh mát mẻ."],["丸刈りの男の子がいます。","Có cậu bé đầu đinh."],["父は丸刈りにしました。","Bố tôi đã cắt đầu đinh."]]},{"word":"長髪","reading":"ちょうはつ","meaning":"tóc dài","hanViet":"TRƯỜNG PHÁT","lesson":44,"ex":[["彼女は長髪です。","Cô ấy để tóc dài."],["長髪の女性がいます。","Có người phụ nữ tóc dài."],["姉は長髪が好きです。","Chị gái tôi thích tóc dài."],["長髪を短く切りました。","Tôi đã cắt tóc dài cho ngắn lại."],["長髪の男の子がいます。","Có cậu bé tóc dài."]]},{"word":"シングル","reading":"シングル","meaning":"phòng đơn","hanViet":"","lesson":44,"ex":[["シングルを予約しました。","Tôi đã đặt phòng đơn."],["シングルは1人で泊まります。","Phòng đơn dành cho 1 người ở."],["シングルとツインと、どちらがいいですか。","Phòng đơn và phòng đôi, phòng nào tốt hơn?"],["シングルの部屋は安いです。","Phòng đơn rẻ."],["シングルが1つあります。","Có 1 phòng đơn."]]},{"word":"ツイン","reading":"ツイン","meaning":"phòng đôi","hanViet":"","lesson":44,"ex":[["ツインを予約しました。","Tôi đã đặt phòng đôi."],["ツインは2人で泊まります。","Phòng đôi dành cho 2 người ở."],["ツインの部屋は広いです。","Phòng đôi rộng."],["ツインとシングルと、どちらが安いですか。","Phòng đôi và phòng đơn, phòng nào rẻ hơn?"],["ツインが1つあります。","Có 1 phòng đôi."]]},{"word":"カット","reading":"カット","meaning":"cắt tóc","hanViet":"","lesson":44,"ex":[["カットをお願いします。","Xin cắt tóc."],["カットとシャンプーをお願いします。","Xin cắt tóc và gội đầu."],["カットはいくらですか。","Cắt tóc giá bao nhiêu?"],["カットを予約しました。","Tôi đã đặt lịch cắt tóc."],["カットが上手な美容師です。","Thợ cắt tóc giỏi."]]},{"word":"シャンプー","reading":"シャンプー","meaning":"gội đầu","hanViet":"","lesson":44,"ex":[["シャンプーをお願いします。","Xin gội đầu."],["シャンプーとカットをお願いします。","Xin gội đầu và cắt tóc."],["シャンプーは気持ちがいいです。","Gội đầu rất dễ chịu."],["シャンプーを買いました。","Tôi đã mua dầu gội."],["美容院でシャンプーをしました。","Tôi đã gội đầu ở tiệm làm tóc."]]},{"word":"ショート","reading":"ショート","meaning":"kiểu ngắn","hanViet":"","lesson":44,"ex":[["ショートにしてください。","Xin cắt kiểu ngắn."],["ショートは私にぴったりです。","Kiểu ngắn rất hợp với tôi."],["彼女はショートです。","Cô ấy để tóc ngắn."],["ショートは涼しいです。","Tóc ngắn mát mẻ."],["夏はショートがいいです。","Mùa hè tóc ngắn thì tốt."]]},{"word":"DVD","reading":"ディーブイディー","meaning":"DVD","hanViet":"","lesson":44,"ex":[["DVDを見ました。","Tôi đã xem DVD."],["DVDを借りました。","Tôi đã mượn DVD."],["DVDを買いました。","Tôi đã mua DVD."],["映画のDVDを見ました。","Tôi đã xem DVD phim."],["DVDを友達に貸しました。","Tôi đã cho bạn mượn DVD."]]},{"word":"うまく","reading":"うまく","meaning":"tốt, giỏi","hanViet":"","lesson":44,"ex":[["田中さんは日本語がうまく話せます。","Anh Tanaka nói tiếng Nhật giỏi."],["妹はピアノがうまくひけます。","Em gái tôi chơi piano giỏi."],["父は車をうまく運転します。","Bố tôi lái xe giỏi."],["山田さんは料理がうまくできます。","Chị Yamada nấu ăn giỏi."],["姉は絵がうまくかけます。","Chị gái tôi vẽ tranh giỏi."]]},{"word":"謝ります","reading":"あやまります","meaning":"xin lỗi, tạ lỗi","hanViet":"TẠ","lesson":45,"ex":[["遅れて、先生に謝りました。","Tôi đến muộn nên đã xin lỗi thầy giáo."],["友達の本をなくして、友達に謝りました。","Tôi làm mất sách của bạn nên đã xin lỗi bạn."],["会議に遅れたので、課長に謝りました。","Tôi đến muộn cuộc họp nên đã xin lỗi trưởng phòng."],["メールでお客様に謝りました。","Tôi đã xin lỗi khách hàng qua email."],["弟は姉のおもちゃを壊して、姉に謝りました。","Em trai làm hỏng đồ chơi của chị nên đã xin lỗi chị."]]},{"word":"会います","reading":"あいます","meaning":"gặp (tai nạn)","hanViet":"HỘI","lesson":45,"ex":[["去年、事故に会いました。","Năm ngoái tôi gặp tai nạn."],["弟は車で事故に会いました。","Em trai tôi gặp tai nạn ô tô."],["雪の日に、事故に会いました。","Tôi đã gặp tai nạn vào ngày tuyết rơi."],["母は駅の前で事故に会いました。","Mẹ tôi gặp tai nạn trước ga."],["友達は自転車で事故に会って、病院へ行きました。","Bạn tôi gặp tai nạn xe đạp và đã đến bệnh viện."]]},{"word":"信じます","reading":"しんじます","meaning":"tin, tin tưởng","hanViet":"TÍN","lesson":45,"ex":[["私は友達の話を信じます。","Tôi tin lời bạn tôi nói."],["母は私の言葉を信じてくれました。","Mẹ đã tin lời tôi nói."],["田中さんはだれの話も信じません。","Anh Tanaka không tin lời ai cả."],["そのニュースを信じますか。","Bạn có tin tin tức đó không?"],["私は先生の言葉を信じます。","Tôi tin lời thầy giáo."]]},{"word":"用意します","reading":"よいします","meaning":"chuẩn bị","hanViet":"DỤNG Ý","lesson":45,"ex":[["旅行の前に、服を用意します。","Trước chuyến du lịch, tôi chuẩn bị quần áo."],["母は晩ごはんを用意しました。","Mẹ đã chuẩn bị bữa tối."],["パーティーの飲み物を用意します。","Tôi chuẩn bị đồ uống cho bữa tiệc."],["試験の前に、鉛筆と消しゴムを用意します。","Trước kỳ thi, tôi chuẩn bị bút chì và tẩy."],["旅行のために、水を用意しました。","Tôi đã chuẩn bị nước cho chuyến du lịch."]]},{"word":"旨くいきます","reading":"うまくいきます","meaning":"tốt, thuận lợi","hanViet":"CHỈ","lesson":45,"ex":[["仕事は旨くいっています。","Công việc đang thuận lợi."],["試験は旨くいきました。","Kỳ thi đã diễn ra tốt đẹp."],["旅行は旨くいきました。","Chuyến du lịch đã diễn ra thuận lợi."],["新しい仕事は旨くいくでしょう。","Công việc mới sẽ thuận lợi thôi."],["発表は旨くいきました。","Buổi trình bày đã diễn ra tốt đẹp."]]},{"word":"保証書","reading":"ほしょうしょ","meaning":"giấy bảo hành","hanViet":"BẢO CHỨNG THƯ","lesson":45,"ex":[["このテレビの保証書はどこですか。","Giấy bảo hành của chiếc tivi này ở đâu?"],["保証書をなくしました。","Tôi đã làm mất giấy bảo hành."],["保証書は大切にしてください。","Xin hãy giữ gìn giấy bảo hành."],["冷蔵庫を買ったとき、保証書をもらいました。","Khi mua tủ lạnh, tôi đã nhận được giấy bảo hành."],["保証書がないと、無料で直せません。","Không có giấy bảo hành thì không sửa miễn phí được."]]},{"word":"領収書","reading":"りょうしゅうしょ","meaning":"Hoá đơn, biên nhận","hanViet":"LÃNH THÂU THƯ","lesson":45,"ex":[["領収書をください。","Xin cho tôi hoá đơn."],["領収書は会社に出します。","Tôi nộp hoá đơn cho công ty."],["本を買って、領収書をもらいました。","Tôi mua sách và đã nhận hoá đơn."],["領収書をなくしたので、新しい領収書をもらいました。","Tôi làm mất hoá đơn nên đã nhận hoá đơn mới."],["領収書はいつも財布に入れています。","Tôi luôn để hoá đơn trong ví."]]},{"word":"贈り物","reading":"おくりもの","meaning":"Quà tặng","hanViet":"TẶNG VẬT","lesson":45,"ex":[["母の誕生日に贈り物を買いました。","Tôi đã mua quà tặng cho sinh nhật của mẹ."],["友達からすてきな贈り物をもらいました。","Tôi đã nhận được món quà tuyệt vời từ bạn."],["贈り物に花を買いました。","Tôi đã mua hoa làm quà tặng."],["先生に贈り物をあげました。","Tôi đã tặng quà cho thầy giáo."],["贈り物を包んでください。","Xin hãy gói quà tặng giúp tôi."]]},{"word":"間違い電話","reading":"まちがいでんわ","meaning":"điện thoại nhầm","hanViet":"GIAN VI ĐIỆN THOẠI","lesson":45,"ex":[["間違い電話でした。","Đó là cuộc điện thoại nhầm."],["すみません、間違い電話でした。","Xin lỗi, tôi gọi nhầm số."],["ゆうべ、間違い電話がかかってきました。","Tối qua có cuộc điện thoại nhầm gọi đến."],["間違い電話が多くて、困っています。","Có nhiều cuộc điện thoại nhầm nên tôi đang gặp khó khăn."],["間違い電話をかけて、謝りました。","Tôi đã gọi nhầm số và xin lỗi."]]},{"word":"係り","reading":"かかり","meaning":"nhân viên, người phụ trách","hanViet":"HỆ","lesson":45,"ex":[["受付の係りに聞いてください。","Xin hãy hỏi nhân viên lễ tân."],["図書館の係りに本の場所を聞きました。","Tôi đã hỏi nhân viên thư viện chỗ để sách."],["会場の係りに席を聞きました。","Tôi đã hỏi nhân viên ở hội trường về chỗ ngồi."],["係りの人が電話で説明してくれました。","Nhân viên đã giải thích cho tôi qua điện thoại."],["係りの山田さんにメールを送りました。","Tôi đã gửi email cho anh Yamada, người phụ trách."]]},{"word":"中止","reading":"ちゅうし","meaning":"dừng, đình chỉ","hanViet":"TRUNG CHỈ","lesson":45,"ex":[["雨で運動会は中止になりました。","Hội thao đã bị hủy vì mưa."],["台風で試合は中止になりました。","Trận đấu đã bị hủy vì bão."],["コンサートは中止になりました。","Buổi hòa nhạc đã bị hủy."],["先生の病気で、授業は中止になりました。","Buổi học đã bị hủy vì thầy giáo bị ốm."],["明日の試合は中止です。","Trận đấu ngày mai bị hủy."]]},{"word":"点","reading":"てん","meaning":"điểm","hanViet":"ĐIỂM","lesson":45,"ex":[["試験で90点をとりました。","Tôi đã được 90 điểm trong kỳ thi."],["日本語の試験は80点でした。","Bài kiểm tra tiếng Nhật được 80 điểm."],["弟は100点をとって、うれしかったです。","Em trai được 100 điểm nên rất vui."],["きのうのテストは60点でした。","Bài kiểm tra hôm qua được 60 điểm."],["点が低くて、困っています。","Điểm thấp nên tôi đang lo."]]},{"word":"～円札","reading":"～えんさつ","meaning":"tờ tiền giấy (yên)","hanViet":"VIÊN TRÁT","lesson":45,"ex":[["1000円札で払いました。","Tôi đã trả bằng tờ 1000 yên."],["財布に5000円札が一枚あります。","Trong ví có một tờ 5000 yên."],["10000円札しかありません。","Tôi chỉ có tờ 10000 yên."],["1000円札を2枚ください。","Xin cho tôi 2 tờ 1000 yên."],["10000円札を出しました。","Tôi đã đưa ra tờ 10000 yên."]]},{"word":"ちゃんと","reading":"ちゃんと","meaning":"đúng, hẳn hoi","hanViet":"","lesson":45,"ex":[["ちゃんと勉強してください。","Xin hãy học hành hẳn hoi."],["毎朝、ちゃんとごはんを食べます。","Mỗi sáng tôi ăn cơm đầy đủ."],["ちゃんと薬を飲んでください。","Xin hãy uống thuốc đầy đủ."],["子どもはちゃんとあいさつをします。","Đứa trẻ chào hỏi lễ phép."],["ちゃんと手を洗ってください。","Xin hãy rửa tay sạch sẽ."]]},{"word":"楽しみにしています","reading":"たのしみにしています","meaning":"mong đợi, lấy làm vui","hanViet":"LẠC","lesson":45,"ex":[["夏の休みを楽しみにしています。","Tôi đang mong đợi kỳ nghỉ hè."],["旅行を楽しみにしています。","Tôi đang mong chờ chuyến du lịch."],["友達に会うことを楽しみにしています。","Tôi đang mong được gặp bạn."],["新しい映画を楽しみにしています。","Tôi đang mong chờ bộ phim mới."],["来週のパーティーを楽しみにしています。","Tôi đang mong chờ bữa tiệc tuần sau."]]},{"word":"以上です","reading":"いじょうです","meaning":"xin hết","hanViet":"DĨ THƯỢNG","lesson":45,"ex":[["私の発表は以上です。","Phần trình bày của tôi xin hết tại đây."],["連絡は以上です。","Thông báo xin hết."],["説明は以上です。","Phần giải thích xin hết."],["きょうの会議は以上です。","Cuộc họp hôm nay xin hết."],["きょうの授業は以上です。","Buổi học hôm nay xin hết."]]},{"word":"係員","reading":"かかりいん","meaning":"nhân viên","hanViet":"HỆ VIÊN","lesson":45,"ex":[["駅の係員に切符を見せました。","Tôi đã cho nhân viên ga xem vé."],["係員に道を教えてもらいました。","Tôi đã được nhân viên chỉ đường."],["美術館の係員が写真を撮ってくれました。","Nhân viên bảo tàng mỹ thuật đã chụp ảnh giúp tôi."],["映画館の係員は親切でした。","Nhân viên rạp chiếu phim rất tốt bụng."],["駐車場の係員に車の場所を聞きました。","Tôi đã hỏi nhân viên bãi đỗ xe chỗ để xe."]]},{"word":"～位","reading":"～い","meaning":"thứ –, vị trí thứ –, giải –","hanViet":"VỊ","lesson":45,"ex":[["マラソンで3位になりました。","Tôi đã về thứ 3 trong cuộc thi marathon."],["田中さんはクラスで1位です。","Anh Tanaka đứng thứ nhất trong lớp."],["試験で2位でした。","Tôi đứng thứ 2 trong kỳ thi."],["日本は世界で3位です。","Nhật Bản đứng thứ 3 thế giới."],["私たちのチームはサッカーの試合で1位になりました。","Đội của chúng tôi đã giành vị trí thứ nhất trong trận bóng đá."]]},{"word":"優勝します","reading":"ゆうしょうします","meaning":"vô địch, giải nhất","hanViet":"ƯU THẮNG","lesson":45,"ex":[["私たちのチームは優勝しました。","Đội của chúng tôi đã vô địch."],["田中さんはテニスで優勝しました。","Anh Tanaka đã vô địch môn tennis."],["サッカーの大会で優勝しました。","Tôi đã vô địch giải bóng đá."],["来年も優勝したいです。","Năm sau tôi cũng muốn vô địch."],["姉はスピーチ大会で優勝しました。","Chị gái tôi đã vô địch cuộc thi hùng biện."]]},{"word":"悩み","reading":"なやみ","meaning":"Nỗi lo, điều phiền muộn","hanViet":"NÃO","lesson":45,"ex":[["仕事の悩みがあります。","Tôi có nỗi lo về công việc."],["友達に悩みを話しました。","Tôi đã tâm sự nỗi lo với bạn."],["悩みを聞いてください。","Xin hãy lắng nghe nỗi lo của tôi."],["母は弟の悩みを聞きました。","Mẹ đã lắng nghe nỗi lo của em trai."],["悩みが多くて、眠れません。","Có nhiều nỗi lo nên tôi không ngủ được."]]},{"word":"目覚まし時計","reading":"めざましどけい","meaning":"đồng hồ báo thức","hanViet":"MỤC GIÁC THỜI KẾ","lesson":45,"ex":[["目覚まし時計を買いました。","Tôi đã mua đồng hồ báo thức."],["目覚まし時計の音で起きました。","Tôi đã thức dậy nhờ tiếng đồng hồ báo thức."],["目覚まし時計が鳴らなくて、遅れました。","Đồng hồ báo thức không reo nên tôi đã đến muộn."],["新しい目覚まし時計は音が大きいです。","Đồng hồ báo thức mới có tiếng kêu to."],["目覚まし時計をベッドの横に置きます。","Tôi đặt đồng hồ báo thức bên cạnh giường."]]},{"word":"回答","reading":"かいとう","meaning":"Câu trả lời","hanViet":"HỒI ĐÁP","lesson":45,"ex":[["回答を書いてください。","Xin hãy viết câu trả lời."],["質問に回答しました。","Tôi đã trả lời câu hỏi."],["回答は明日までです。","Hạn trả lời là ngày mai."],["先生の質問に回答しました。","Tôi đã trả lời câu hỏi của thầy giáo."],["回答を先生に渡しました。","Tôi đã nộp câu trả lời cho thầy giáo."]]},{"word":"鳴ります","reading":"なります","meaning":"reo lên","hanViet":"MINH","lesson":45,"ex":[["電話が鳴っています。","Điện thoại đang reo."],["携帯電話が鳴ったので、出ました。","Điện thoại di động reo nên tôi đã nghe máy."],["学校のベルが鳴りました。","Chuông trường đã reo."],["目覚まし時計が鳴って、起きました。","Đồng hồ báo thức reo và tôi đã thức dậy."],["ベルが鳴りました。","Chuông cửa đã reo."]]},{"word":"それでも","reading":"それでも","meaning":"tuy nhiên","hanViet":"","lesson":45,"ex":[["雨でしたが、それでも試合をしました。","Trời mưa nhưng trận đấu vẫn diễn ra."],["忙しいですが、それでも毎日勉強します。","Tôi bận nhưng vẫn học mỗi ngày."],["高かったですが、それでも買いました。","Nó đắt nhưng tôi vẫn mua."],["遠いですが、それでも毎週行きます。","Xa lắm nhưng tôi vẫn đi mỗi tuần."],["難しかったですが、それでも頑張りました。","Khó lắm nhưng tôi vẫn cố gắng."]]},{"word":"非常の場合","reading":"ひじょうのばあい","meaning":"trong trường hợp khẩn cấp","hanViet":"PHI THƯỜNG TRƯỜNG HỢP","lesson":45,"ex":[["非常の場合は１１０番に電話してください。","Trong trường hợp khẩn cấp, xin hãy gọi 110."],["非常の場合はこのボタンを押してください。","Trong trường hợp khẩn cấp, xin hãy bấm nút này."],["非常の場合は先生に連絡してください。","Trong trường hợp khẩn cấp, xin hãy liên lạc với thầy giáo."],["非常の場合は１１９番に電話します。","Trong trường hợp khẩn cấp, tôi gọi 119."],["非常の場合はここから逃げてください。","Trong trường hợp khẩn cấp, xin hãy chạy thoát từ đây."]]},{"word":"キャンセルします","reading":"キャンセルします","meaning":"hủy, hủy bỏ","hanViet":"","lesson":45,"ex":[["予約をキャンセルしました。","Tôi đã hủy đặt chỗ."],["明日の会議をキャンセルしました。","Tôi đã hủy cuộc họp ngày mai."],["病気で旅行をキャンセルしました。","Tôi đã hủy chuyến du lịch vì bị ốm."],["ホテルの予約をキャンセルしてください。","Xin hãy hủy đặt phòng khách sạn."],["チケットをキャンセルしました。","Tôi đã hủy vé."]]},{"word":"キャンプ","reading":"キャンプ","meaning":"trại","hanViet":"","lesson":45,"ex":[["夏に山でキャンプをしました。","Mùa hè tôi đã đi cắm trại trên núi."],["友達とキャンプへ行きました。","Tôi đã đi cắm trại với bạn."],["キャンプは楽しいです。","Cắm trại rất vui."],["キャンプでごはんを作りました。","Tôi đã nấu cơm khi đi cắm trại."],["来月、家族とキャンプをします。","Tháng sau tôi sẽ đi cắm trại với gia đình."]]},{"word":"コース","reading":"コース","meaning":"đường chạy (ma ra tông)","hanViet":"","lesson":45,"ex":[["マラソンのコースは長いです。","Đường chạy marathon rất dài."],["コースがわかりませんでした。","Tôi đã không biết đường chạy."],["このコースは山が多いです。","Đường chạy này có nhiều núi."],["コースを走りました。","Tôi đã chạy trên đường chạy."],["新しいコースを走ってみます。","Tôi sẽ thử chạy đường chạy mới."]]},{"word":"スタート","reading":"スタート","meaning":"xuất phát","hanViet":"","lesson":45,"ex":[["マラソンは9時にスタートします。","Cuộc thi marathon bắt đầu lúc 9 giờ."],["スタートの時間になりました。","Đã đến giờ xuất phát."],["みんなでいっしょにスタートしました。","Mọi người đã cùng xuất phát."],["マラソンのスタートは公園です。","Điểm xuất phát của marathon là công viên."],["スタートが遅れました。","Việc xuất phát đã bị chậm."]]},{"word":"梅","reading":"うめ","meaning":"quả mơ, cây mơ","hanViet":"MAI","lesson":45,"ex":[["梅の花が咲きました。","Hoa mơ đã nở."],["梅は春に咲きます。","Hoa mơ nở vào mùa xuân."],["梅の木があります。","Có cây mơ."],["梅の花はきれいです。","Hoa mơ đẹp."],["梅の花を見に行きました。","Tôi đã đi ngắm hoa mơ."]]},{"word":"１１０番","reading":"ひゃくとおばん","meaning":"số điện thoại khẩn cấp (cảnh sát)","hanViet":"PHIÊN","lesson":45,"ex":[["事故のときは１１０番に電話します。","Khi có tai nạn, tôi gọi 110."],["１１０番は警察の番号です。","110 là số điện thoại của cảnh sát."],["泥棒が入ったら、１１０番に電話してください。","Nếu có trộm vào nhà, xin hãy gọi 110."],["１１０番に電話をかけました。","Tôi đã gọi điện đến 110."],["１１０番は無料です。","Gọi 110 miễn phí."]]},{"word":"１１９番","reading":"ひゃくじゅうきゅうばん","meaning":"số 119 (báo cháy khi khẩn cấp)","hanViet":"PHIÊN","lesson":45,"ex":[["火事のときは１１９番に電話します。","Khi có hỏa hoạn, tôi gọi 119."],["１１９番は火事のときの番号です。","119 là số điện thoại khi có hỏa hoạn."],["けがをしたとき、１１９番に電話しました。","Khi bị thương, tôi đã gọi 119."],["１１９番に電話をかけました。","Tôi đã gọi điện đến 119."],["具合が悪い人がいるときは１１９番に電話してください。","Khi có người không khỏe, xin hãy gọi 119."]]},{"word":"無理に","reading":"むりに","meaning":"cố, gắng (làm không hợp lý)","hanViet":"VÔ LÝ","lesson":45,"ex":[["無理に走らないでください。","Xin đừng cố chạy."],["無理に食べないでください。","Xin đừng cố ăn."],["病気のときは、無理に働かないでください。","Khi bị ốm, xin đừng cố làm việc."],["無理に運動しないでください。","Xin đừng cố tập thể dục."],["無理に笑わないでください。","Xin đừng cố cười."]]},{"word":"レバー","reading":"レバー","meaning":"tay bẻ, tay số, cần gạt","hanViet":"","lesson":45,"ex":[["レバーを右に回してください。","Xin hãy xoay cần gạt sang phải."],["レバーを押してください。","Xin hãy bấm cần gạt."],["レバーを引いてください。","Xin hãy kéo cần gạt."],["このレバーは壊れています。","Cần gạt này đã bị hỏng."],["レバーを上に上げてください。","Xin hãy nâng cần gạt lên."]]},{"word":"大学生","reading":"だいがくせい","meaning":"sinh viên đại học","hanViet":"ĐẠI HỌC SINH","lesson":45,"ex":[["私は大学生です。","Tôi là sinh viên đại học."],["兄は大学生です。","Anh trai tôi là sinh viên đại học."],["大学生はアルバイトをしています。","Sinh viên đại học đang làm thêm."],["大学生のとき、東京に住んでいました。","Khi còn là sinh viên đại học, tôi đã sống ở Tokyo."],["姉は大学生になって、京都へ行きました。","Chị gái tôi đã trở thành sinh viên đại học và đi Kyoto."]]},{"word":"セットします","reading":"セットします","meaning":"cài đặt","hanViet":"","lesson":45,"ex":[["目覚まし時計を6時にセットしました。","Tôi đã cài đồng hồ báo thức lúc 6 giờ."],["ビデオをセットしました。","Tôi đã cài đặt video."],["新しいパソコンをセットしました。","Tôi đã cài đặt máy tính mới."],["時計をセットしてください。","Xin hãy cài đặt đồng hồ."],["エアコンをセットしました。","Tôi đã cài đặt điều hòa."]]},{"word":"渡します","reading":"わたします","meaning":"trao","hanViet":"ĐỘ","lesson":46,"ex":[["先生にレポートを渡しました。","Tôi đã nộp báo cáo cho thầy giáo."],["母に手紙を渡しました。","Tôi đã đưa thư cho mẹ."],["友達にプレゼントを渡しました。","Tôi đã tặng quà cho bạn."],["係員に切符を渡しました。","Tôi đã đưa vé cho nhân viên."],["田中さんに資料を渡してください。","Xin hãy đưa tài liệu cho anh Tanaka."]]},{"word":"帰って来ます","reading":"かえってきます","meaning":"quay về","hanViet":"QUY LAI","lesson":46,"ex":[["母はもう帰って来ました。","Mẹ tôi đã về rồi."],["友達は旅行から帰って来ました。","Bạn tôi đã về từ chuyến du lịch."],["兄はアメリカから帰って来ました。","Anh trai tôi đã về từ Mỹ."],["子どもは学校から帰って来ました。","Đứa trẻ đã về từ trường."],["父は仕事から帰って来ました。","Bố tôi đã về từ chỗ làm."]]},{"word":"宅配便","reading":"たくはいびん","meaning":"dịch vụ trao tận nhà","hanViet":"TRẠCH PHỐI TIỆN","lesson":46,"ex":[["宅配便で荷物を送りました。","Tôi đã gửi hành lý bằng dịch vụ giao hàng tận nhà."],["宅配便が届きました。","Hàng giao tận nhà đã đến."],["宅配便で本を送ります。","Tôi sẽ gửi sách bằng dịch vụ giao hàng tận nhà."],["宅配便の人が来ました。","Nhân viên giao hàng đã đến."],["宅配便は便利です。","Dịch vụ giao hàng tận nhà rất tiện lợi."]]},{"word":"原因","reading":"げんいん","meaning":"Nguyên nhân","hanViet":"NGUYÊN NHÂN","lesson":46,"ex":[["病気の原因がわかりません。","Tôi không biết nguyên nhân của bệnh."],["事故の原因を調べました。","Tôi đã điều tra nguyên nhân vụ tai nạn."],["遅れた原因は雨でした。","Nguyên nhân đến muộn là mưa."],["原因がわかって、安心しました。","Tôi đã biết nguyên nhân nên yên tâm."],["火事の原因はたばこでした。","Nguyên nhân hỏa hoạn là thuốc lá."]]},{"word":"注射","reading":"ちゅうしゃ","meaning":"tiêm (thuốc)","hanViet":"CHÚ XẠ","lesson":46,"ex":[["病院で注射をしました。","Tôi đã tiêm thuốc ở bệnh viện."],["注射は痛いです。","Tiêm thuốc đau lắm."],["子どもは注射が嫌いです。","Trẻ con ghét tiêm thuốc."],["医者に注射をしてもらいました。","Tôi đã được bác sĩ tiêm thuốc."],["注射をして、熱が下がりました。","Sau khi tiêm, tôi đã hết sốt."]]},{"word":"食欲","reading":"しょくよく","meaning":"cảm giác thèm ăn","hanViet":"THỰC DỤC","lesson":46,"ex":[["食欲がありません。","Tôi không thấy thèm ăn."],["病気で食欲がありません。","Tôi bị ốm nên không thấy thèm ăn."],["元気になって、食欲が出ました。","Tôi đã khỏe lại và thấy thèm ăn."],["夏は食欲がなくなります。","Mùa hè tôi mất cảm giác thèm ăn."],["食欲があって、たくさん食べました。","Tôi thấy thèm ăn nên đã ăn rất nhiều."]]},{"word":"こちら","reading":"こちら","meaning":"chỗ (chúng tôi), phía (chúng tôi)","hanViet":"","lesson":46,"ex":[["こちらは山田です。","Tôi là Yamada."],["こちらは田中です。","Tôi là Tanaka."],["こちらこそ、よろしくお願いします。","Chính tôi mới phải nhờ anh/chị giúp đỡ."],["こちらへどうぞ。","Xin mời qua phía này."],["こちらは会社です。","Đây là công ty."]]},{"word":"ちょうど","reading":"ちょうど","meaning":"vừa đúng","hanViet":"","lesson":46,"ex":[["ちょうど9時に来ました。","Tôi đã đến đúng lúc 9 giờ."],["ちょうどいいです。","Vừa đúng ý tôi."],["ちょうど3時です。","Bây giờ đúng 3 giờ."],["ちょうど電車が来ました。","Tàu điện vừa đến đúng lúc."],["ちょうど1000円です。","Đúng 1000 yên."]]},{"word":"たった今","reading":"たったいま","meaning":"mới hồi nãy","hanViet":"KIM","lesson":46,"ex":[["たった今、帰って来ました。","Tôi vừa mới về."],["たった今、電話がありました。","Vừa mới nãy có điện thoại."],["たった今、友達が来ました。","Vừa mới nãy bạn tôi đã đến."],["たった今、荷物が届きました。","Vừa mới nãy hành lý đã đến."],["たった今、母が帰りました。","Vừa mới nãy mẹ tôi đã về."]]},{"word":"今いいでしょうか","reading":"いまいいでしょうか","meaning":"bây giờ (tôi) có thể làm phiền anh/chị được không?","hanViet":"KIM","lesson":46,"ex":[["今いいでしょうか。","Bây giờ anh/chị có tiện không?"],["すみません、今いいでしょうか。","Xin lỗi, bây giờ anh/chị có tiện không?"],["田中さん、今いいでしょうか。","Anh Tanaka, bây giờ anh có tiện không?"],["質問がありますが、今いいでしょうか。","Tôi có câu hỏi, bây giờ anh/chị có tiện không?"],["先生、今いいでしょうか。","Thầy ơi, bây giờ thầy có tiện không?"]]},{"word":"具合","reading":"ぐあい","meaning":"Tình trạng, thể trạng","hanViet":"CỤ HỢP","lesson":46,"ex":[["具合が悪いです。","Tình trạng sức khỏe của tôi không tốt."],["具合はどうですか。","Tình trạng sức khỏe của bạn thế nào?"],["具合がよくなりました。","Tình trạng sức khỏe đã tốt hơn."],["おばあさんの具合はどうですか。","Tình trạng sức khỏe của bà thế nào?"],["車の具合が悪いです。","Tình trạng chiếc xe không tốt."]]},{"word":"どちら様でしょうか","reading":"どちらさまでしょうか","meaning":"vị nào đấy ạ?","hanViet":"DẠNG","lesson":46,"ex":[["どちら様でしょうか。","Vị nào đấy ạ?"],["すみません、どちら様でしょうか。","Xin lỗi, vị nào đấy ạ?"],["はい、どちら様でしょうか。","Vâng, vị nào đấy ạ?"],["もしもし、どちら様でしょうか。","Alo, vị nào đấy ạ?"],["田中ですが、どちら様でしょうか。","Tôi là Tanaka, vị nào đấy ạ?"]]},{"word":"向かいます","reading":"むかいます","meaning":"hướng về","hanViet":"HƯỚNG","lesson":46,"ex":[["駅に向かいます。","Tôi đang hướng về phía ga."],["学校に向かいました。","Tôi đã đi về phía trường."],["北に向かいます。","Tôi đang đi về phía bắc."],["東京に向かいます。","Tôi đang đi về phía Tokyo."],["山に向かって歩きました。","Tôi đã đi bộ về phía núi."]]},{"word":"お待たせしました","reading":"おまたせしました","meaning":"xin lỗi đã để quý vị chờ lâu","hanViet":"ĐÃI","lesson":46,"ex":[["お待たせしました。","Xin lỗi đã để anh/chị chờ lâu."],["すみません、お待たせしました。","Xin lỗi, đã để anh/chị chờ lâu."],["お待たせしました、田中さん。","Xin lỗi đã để anh Tanaka chờ lâu."],["長い時間、お待たせしました。","Xin lỗi đã để anh/chị chờ một lúc lâu."],["お待たせしました、どうぞお座りください。","Xin lỗi đã để anh/chị chờ, xin mời ngồi."]]},{"word":"知識","reading":"ちしき","meaning":"Kiến thức, tri thức","hanViet":"TRI THỨC","lesson":46,"ex":[["日本語の知識が増えました。","Kiến thức tiếng Nhật của tôi đã tăng lên."],["知識が必要です。","Cần có kiến thức."],["インターネットで知識が増えました。","Tôi đã có thêm kiến thức từ Internet."],["先生は知識が多いです。","Thầy giáo có nhiều kiến thức."],["新しい知識を勉強します。","Tôi học kiến thức mới."]]},{"word":"宝庫","reading":"ほうこ","meaning":"kho báu","hanViet":"BẢO KHỐ","lesson":46,"ex":[["インターネットは情報の宝庫です。","Internet là kho báu thông tin."],["図書館は知識の宝庫です。","Thư viện là kho báu tri thức."],["この本は情報の宝庫です。","Cuốn sách này là kho báu thông tin."],["日本は文化の宝庫です。","Nhật Bản là kho báu văn hóa."],["海は魚の宝庫です。","Biển là kho báu của cá."]]},{"word":"手に入ります","reading":"てにはいります","meaning":"có, được [thông tin]","hanViet":"THỦ NHẬP","lesson":46,"ex":[["インターネットで情報が手に入ります。","Tôi có được thông tin từ Internet."],["本で知識が手に入ります。","Tôi có được kiến thức từ sách."],["図書館で古い本が手に入りました。","Tôi đã có được sách cũ ở thư viện."],["友達からチケットが手に入りました。","Tôi đã có được vé từ bạn."],["インターネットで安い切符が手に入ります。","Tôi có được vé rẻ qua Internet."]]},{"word":"一部分","reading":"いちぶぶん","meaning":"một bộ phận","hanViet":"NHẤT BỘ PHÂN","lesson":46,"ex":[["一部分だけ読みました。","Tôi chỉ đọc một phần."],["本の一部分を読みました。","Tôi đã đọc một phần của cuốn sách."],["一部分が壊れています。","Một phần đã bị hỏng."],["一部分だけ覚えています。","Tôi chỉ nhớ một phần."],["仕事の一部分が終わりました。","Một phần công việc đã xong."]]},{"word":"入力します","reading":"にゅうりょくします","meaning":"nhập vào","hanViet":"NHẬP LỰC","lesson":46,"ex":[["パソコンに名前を入力しました。","Tôi đã nhập tên vào máy tính."],["電話番号を入力してください。","Xin hãy nhập số điện thoại."],["住所を入力しました。","Tôi đã nhập địa chỉ."],["メールアドレスを入力しました。","Tôi đã nhập địa chỉ email."],["キーワードを入力してください。","Xin hãy nhập từ khóa."]]},{"word":"秒","reading":"びょう","meaning":"Giây","hanViet":"MIỂU","lesson":46,"ex":[["10秒待ってください。","Xin hãy đợi 10 giây."],["30秒で走りました。","Tôi đã chạy trong 30 giây."],["5秒だけ待ってください。","Xin hãy đợi chỉ 5 giây thôi."],["信号が10秒で変わります。","Đèn giao thông đổi sau 10 giây."],["60秒は1分です。","60 giây là 1 phút."]]},{"word":"パンフレット","reading":"パンフレット","meaning":"tờ rơi, tờ quảng cáo","hanViet":"","lesson":46,"ex":[["パンフレットをもらいました。","Tôi đã nhận được tờ rơi."],["旅行のパンフレットを見ました。","Tôi đã xem tờ rơi du lịch."],["パンフレットをください。","Xin cho tôi tờ rơi."],["駅でパンフレットをもらいました。","Tôi đã nhận tờ rơi ở ga."],["パンフレットに地図があります。","Trong tờ rơi có bản đồ."]]},{"word":"ステレオ","reading":"ステレオ","meaning":"âm thanh nổi","hanViet":"","lesson":46,"ex":[["ステレオで音楽を聞きます。","Tôi nghe nhạc bằng loa stereo."],["新しいステレオを買いました。","Tôi đã mua dàn stereo mới."],["ステレオの音が大きいです。","Âm thanh stereo rất to."],["部屋にステレオがあります。","Trong phòng có dàn stereo."],["ステレオでラジオを聞きます。","Tôi nghe radio bằng stereo."]]},{"word":"～の所","reading":"～のところ","meaning":"quanh vùng ~","hanViet":"SỞ","lesson":46,"ex":[["駅の所に本屋があります。","Quanh ga có hiệu sách."],["会社の所に公園があります。","Quanh công ty có công viên."],["学校の所で友達に会いました。","Tôi đã gặp bạn quanh trường."],["家の所に川があります。","Quanh nhà có con sông."],["東京の所に住んでいます。","Tôi sống quanh vùng Tokyo."]]},{"word":"ガスサービスセンター","reading":"ガスサービスセンター","meaning":"trung tâm dịch vụ gas","hanViet":"","lesson":46,"ex":[["ガスサービスセンターに電話しました。","Tôi đã gọi điện cho trung tâm dịch vụ gas."],["ガスサービスセンターの人が来ました。","Nhân viên trung tâm dịch vụ gas đã đến."],["ガスサービスセンターに連絡してください。","Xin hãy liên lạc với trung tâm dịch vụ gas."],["ガスが止まったので、ガスサービスセンターに電話しました。","Gas bị ngừng nên tôi đã gọi cho trung tâm dịch vụ gas."],["ガスサービスセンターは9時から5時までです。","Trung tâm dịch vụ gas mở cửa từ 9 giờ đến 5 giờ."]]},{"word":"ガスレンジ","reading":"ガスレンジ","meaning":"bếp ga","hanViet":"","lesson":46,"ex":[["ガスレンジで料理をします。","Tôi nấu ăn bằng bếp ga."],["新しいガスレンジを買いました。","Tôi đã mua bếp ga mới."],["ガスレンジが壊れました。","Bếp ga đã bị hỏng."],["ガスレンジの火がつきません。","Lửa bếp ga không cháy."],["ガスレンジを掃除しました。","Tôi đã dọn dẹp bếp ga."]]},{"word":"システム","reading":"システム","meaning":"hệ thống","hanViet":"","lesson":46,"ex":[["新しいシステムを使います。","Tôi dùng hệ thống mới."],["システムが変わりました。","Hệ thống đã thay đổi."],["このシステムは便利です。","Hệ thống này rất tiện lợi."],["システムを勉強しています。","Tôi đang học về hệ thống."],["システムに問題があります。","Hệ thống có vấn đề."]]},{"word":"キーワード","reading":"キーワード","meaning":"từ khóa, điểm then chốt","hanViet":"","lesson":46,"ex":[["キーワードを決めました。","Tôi đã quyết định từ khóa."],["キーワードで調べます。","Tôi tìm kiếm bằng từ khóa."],["キーワードは「日本語」です。","Từ khóa là \"tiếng Nhật\"."],["キーワードを教えてください。","Xin hãy cho tôi biết từ khóa."],["キーワードを忘れました。","Tôi đã quên từ khóa."]]},{"word":"ついています","reading":"ついています","meaning":"may mắn","hanViet":"","lesson":46,"ex":[["きょうはついています。","Hôm nay tôi gặp may."],["宝くじに当たって、ついています。","Tôi đã trúng xổ số, thật may mắn."],["いい天気で、ついています。","Trời đẹp, thật may mắn."],["友達に会えて、ついています。","Tôi đã gặp được bạn, thật may mắn."],["いい席が取れて、ついています。","Tôi đã lấy được chỗ ngồi tốt, thật may mắn."]]},{"word":"床","reading":"ゆか","meaning":"Sàn nhà","hanViet":"SÀNG","lesson":46,"ex":[["床を掃除しました。","Tôi đã dọn dẹp sàn nhà."],["床に本を置きました。","Tôi đã đặt sách lên sàn nhà."],["床がきれいです。","Sàn nhà sạch sẽ."],["子どもは床で遊んでいます。","Đứa trẻ đang chơi trên sàn nhà."],["床が冷たいです。","Sàn nhà lạnh."]]},{"word":"転びます","reading":"ころびます","meaning":"ngã","hanViet":"CHUYỂN","lesson":46,"ex":[["雪の日に転びました。","Tôi đã ngã vào ngày tuyết rơi."],["階段で転びました。","Tôi đã ngã ở cầu thang."],["子どもが転んで、泣きました。","Đứa trẻ ngã và đã khóc."],["暗い道で転びました。","Tôi đã ngã trên con đường tối."],["走って、転びました。","Tôi chạy và đã ngã."]]},{"word":"ベル","reading":"ベル","meaning":"chuông cửa","hanViet":"","lesson":46,"ex":[["ベルを押してください。","Xin hãy bấm chuông cửa."],["ベルの音が聞こえました。","Tôi đã nghe thấy tiếng chuông cửa."],["ベルが鳴らなくて、困りました。","Chuông cửa không reo nên tôi gặp khó khăn."],["玄関のベルを押しました。","Tôi đã bấm chuông cửa ở lối vào."],["ベルを押しても、だれも出ませんでした。","Tôi bấm chuông nhưng không ai ra."]]},{"word":"慌てて","reading":"あわてて","meaning":"vội vàng","hanViet":"HOẢNG","lesson":46,"ex":[["慌てて、家を出ました。","Tôi đã vội vàng ra khỏi nhà."],["慌てて、電話に出ました。","Tôi đã vội vàng nghe điện thoại."],["慌てて、駅へ走りました。","Tôi đã vội vàng chạy đến ga."],["慌てて、財布を忘れました。","Tôi đã vội vàng nên quên ví."],["慌てて、ドアを閉めました。","Tôi đã vội vàng đóng cửa."]]},{"word":"順番に","reading":"じゅんばんに","meaning":"theo thứ tự","hanViet":"THUẬN PHIÊN","lesson":46,"ex":[["順番に並んでください。","Xin hãy xếp hàng theo thứ tự."],["順番に名前を呼びます。","Tôi sẽ gọi tên theo thứ tự."],["順番に座ってください。","Xin hãy ngồi theo thứ tự."],["順番に発表します。","Chúng tôi sẽ trình bày theo thứ tự."],["順番に本を渡しました。","Tôi đã phát sách theo thứ tự."]]},{"word":"出来事","reading":"できごと","meaning":"sự việc","hanViet":"XUẤT LAI SỰ","lesson":46,"ex":[["きのうの出来事を話しました。","Tôi đã kể về sự việc hôm qua."],["楽しい出来事がありました。","Đã có sự việc vui vẻ."],["びっくりする出来事がありました。","Đã có sự việc đáng ngạc nhiên."],["その出来事を忘れません。","Tôi sẽ không quên sự việc đó."],["出来事を日記に書きました。","Tôi đã viết sự việc vào nhật ký."]]},{"word":"長生きします","reading":"ながいきします","meaning":"sống lâu","hanViet":"TRƯỜNG SINH","lesson":47,"ex":[["おじいさんは長生きしました。","Ông tôi đã sống lâu."],["長生きしたいです。","Tôi muốn sống lâu."],["健康に気をつけて、長生きします。","Tôi chú ý sức khỏe để sống lâu."],["祖母は100歳まで長生きしました。","Bà tôi đã sống đến 100 tuổi."],["長生きするために、運動します。","Để sống lâu, tôi tập thể dục."]]},{"word":"音がします","reading":"おとがします","meaning":"có [âm thanh], nghe thấy tiếng","hanViet":"ÂM","lesson":47,"ex":[["ピアノの音がします。","Có tiếng đàn piano."],["外で大きい音がします。","Bên ngoài có tiếng động lớn."],["電車の音がします。","Có tiếng tàu điện."],["雨の音がします。","Có tiếng mưa."],["隣の部屋から音がします。","Có tiếng động từ phòng bên cạnh."]]},{"word":"声がします","reading":"こえがします","meaning":"có [tiếng nói], nghe thấy tiếng nói","hanViet":"THANH","lesson":47,"ex":[["子どもの声がします。","Có tiếng trẻ con."],["外から声がします。","Có tiếng nói từ bên ngoài."],["隣の家から声がします。","Có tiếng nói từ nhà bên cạnh."],["母の声がします。","Có tiếng mẹ tôi."],["教室から先生の声がします。","Có tiếng thầy giáo từ lớp học."]]},{"word":"味がします","reading":"あじがします","meaning":"có [vị]","hanViet":"VỊ","lesson":47,"ex":[["このみそ汁は塩の味がします。","Món súp miso này có vị muối."],["このケーキは甘い味がします。","Chiếc bánh này có vị ngọt."],["このお茶は苦い味がします。","Trà này có vị đắng."],["このジュースはレモンの味がします。","Nước ép này có vị chanh."],["この魚はしょうゆの味がします。","Món cá này có vị nước tương."]]},{"word":"匂いがします","reading":"においがします","meaning":"có [mùi]","hanViet":"","lesson":47,"ex":[["花の匂いがします。","Có mùi hoa."],["コーヒーの匂いがします。","Có mùi cà phê."],["パンの匂いがします。","Có mùi bánh mì."],["海の匂いがします。","Có mùi biển."],["この部屋はたばこの匂いがします。","Phòng này có mùi thuốc lá."]]},{"word":"さします","reading":"さします","meaning":"giương [ô, dù]","hanViet":"","lesson":47,"ex":[["雨が降っているので、傘をさします。","Trời đang mưa nên tôi giương ô."],["大きい傘をさします。","Tôi giương chiếc ô lớn."],["母は傘をさして、歩きました。","Mẹ tôi giương ô và đi bộ."],["傘をさしてください。","Xin hãy giương ô."],["雨が降ってきたので、傘をさしました。","Trời bắt đầu mưa nên tôi đã giương ô."]]},{"word":"ひどい","reading":"ひどい","meaning":"tồi tệ, xấu","hanViet":"","lesson":47,"ex":[["ひどい雨です。","Mưa rất to."],["ひどいけがをしました。","Tôi bị thương nặng."],["ひどい風が吹いています。","Gió thổi rất mạnh."],["ひどい天気です。","Thời tiết rất xấu."],["ひどい事故でした。","Đó là vụ tai nạn nghiêm trọng."]]},{"word":"発表","reading":"はっぴょう","meaning":"Phát biểu, công bố","hanViet":"PHÁT BIỂU","lesson":47,"ex":[["明日、発表があります。","Ngày mai có buổi trình bày."],["発表をしました。","Tôi đã trình bày."],["先生の前で発表をしました。","Tôi đã trình bày trước thầy giáo."],["発表の準備をしました。","Tôi đã chuẩn bị cho buổi trình bày."],["発表のとき、緊張しました。","Khi trình bày, tôi đã hồi hộp."]]},{"word":"実験","reading":"じっけん","meaning":"thí nghiệm, thực nghiệm","hanViet":"THỰC NGHIỆM","lesson":47,"ex":[["大学で水の実験をします。","Tôi làm thí nghiệm về nước ở trường đại học."],["先生はきょう実験を見せました。","Hôm nay thầy giáo đã cho xem thí nghiệm."],["実験はとてもおもしろかったです。","Thí nghiệm rất thú vị."],["学生は毎週実験をします。","Sinh viên làm thí nghiệm mỗi tuần."],["実験の前に、先生の話をよく聞いてください。","Trước khi làm thí nghiệm, hãy nghe kỹ lời thầy giáo."]]},{"word":"人口","reading":"じんこう","meaning":"Dân số","hanViet":"NHÂN KHẨU","lesson":47,"ex":[["東京の人口はとても多いです。","Dân số Tokyo rất đông."],["この町の人口は5万人です。","Dân số thị trấn này là 50 nghìn người."],["京都の人口は東京より少ないです。","Dân số Kyoto ít hơn Tokyo."],["人口が増えましたから、新しい学校を作りました。","Vì dân số tăng nên đã xây trường mới."],["この村の人口は100人ぐらいです。","Dân số làng này khoảng 100 người."]]},{"word":"におい","reading":"におい","meaning":"mùi","hanViet":"","lesson":47,"ex":[["この花はいいにおいがします。","Bông hoa này có mùi thơm."],["コーヒーのにおいがします。","Có mùi cà phê."],["料理のにおいがとてもいいです。","Mùi món ăn rất thơm."],["この魚はにおいが強いです。","Con cá này có mùi nồng."],["部屋に変なにおいがします。","Trong phòng có mùi lạ."]]},{"word":"科学","reading":"かがく","meaning":"Khoa học","hanViet":"KHOA HỌC","lesson":47,"ex":[["私は大学で科学を勉強しています。","Tôi đang học khoa học ở trường đại học."],["科学の本をよく読みます。","Tôi thường đọc sách khoa học."],["科学の先生はとても有名です。","Thầy giáo khoa học rất nổi tiếng."],["科学の授業はおもしろいです。","Tiết học khoa học rất thú vị."],["子どもは科学に興味があります。","Trẻ em có hứng thú với khoa học."]]},{"word":"医学","reading":"いがく","meaning":"Y học","hanViet":"Y HỌC","lesson":47,"ex":[["兄は大学で医学を勉強しています。","Anh trai tôi đang học y học ở trường đại học."],["医学の本はとても難しいです。","Sách y học rất khó."],["医学は人の健康に大切です。","Y học quan trọng đối với sức khỏe con người."],["医学を勉強して、医者になりたいです。","Tôi muốn học y học và trở thành bác sĩ."],["医学の先生は病院で働いています。","Thầy giáo y học đang làm việc ở bệnh viện."]]},{"word":"文学","reading":"ぶんがく","meaning":"văn học","hanViet":"VĂN HỌC","lesson":47,"ex":[["私は日本の文学が好きです。","Tôi thích văn học Nhật Bản."],["文学の授業で小説を読みます。","Trong tiết học văn học, tôi đọc tiểu thuyết."],["文学の先生は有名な作家です。","Thầy giáo văn học là một nhà văn nổi tiếng."],["姉は大学で文学を勉強しています。","Chị gái tôi đang học văn học ở trường đại học."],["文学の本を図書館で借ります。","Tôi mượn sách văn học ở thư viện."]]},{"word":"救急車","reading":"きゅうきゅうしゃ","meaning":"xe cứu thương","hanViet":"CỨU CẤP XA","lesson":47,"ex":[["事故があったので、救急車を呼びました。","Vì có tai nạn nên tôi đã gọi xe cứu thương."],["救急車は病院へ急ぎました。","Xe cứu thương vội vã chạy đến bệnh viện."],["救急車の音が聞こえます。","Nghe thấy tiếng còi xe cứu thương."],["けがをした人は救急車で病院へ行きました。","Người bị thương đã đi bệnh viện bằng xe cứu thương."],["救急車が来ましたから、道を開けてください。","Xe cứu thương đã đến, xin hãy nhường đường."]]},{"word":"賛成","reading":"さんせい","meaning":"Tán thành, đồng ý","hanViet":"TÁN THÀNH","lesson":47,"ex":[["私は田中さんの意見に賛成です。","Tôi tán thành ý kiến của anh Tanaka."],["先生の意見に賛成する学生は多いです。","Có nhiều sinh viên tán thành ý kiến của thầy giáo."],["私もその意見に賛成です。","Tôi cũng tán thành ý kiến đó."],["賛成の人は手を上げてください。","Người tán thành xin giơ tay lên."],["父は私の旅行に賛成してくれました。","Bố đã tán thành chuyến du lịch của tôi."]]},{"word":"反対","reading":"はんたい","meaning":"phản đối; ngược lại","hanViet":"PHẢN ĐỐI","lesson":47,"ex":[["私はその意見に反対です。","Tôi phản đối ý kiến đó."],["反対の人は手を上げてください。","Người phản đối xin giơ tay lên."],["母は私がアルバイトをすることに反対しました。","Mẹ đã phản đối việc tôi làm thêm."],["会議で反対する人は2人だけでした。","Trong cuộc họp chỉ có 2 người phản đối."],["田中さんは反対でしたが、山田さんは賛成でした。","Anh Tanaka phản đối, còn anh Yamada thì tán thành."]]},{"word":"男性","reading":"だんせい","meaning":"Nam giới, đàn ông (trang trọng)","hanViet":"NAM TÍNH","lesson":47,"ex":[["この会社では男性が多く働いています。","Ở công ty này có nhiều nam giới làm việc."],["男性の平均寿命は女性より短いです。","Tuổi thọ bình quân của nam giới ngắn hơn nữ giới."],["男性の先生は3人います。","Có 3 thầy giáo nam."],["男性も女性もこのスポーツが好きです。","Cả nam giới và nữ giới đều thích môn thể thao này."],["男性の服は2階で売っています。","Quần áo nam bán ở tầng 2."]]},{"word":"女性","reading":"じょせい","meaning":"Nữ giới, phụ nữ (trang trọng)","hanViet":"NỮ TÍNH","lesson":47,"ex":[["この会社では女性が多く働いています。","Ở công ty này có nhiều nữ giới làm việc."],["女性の平均寿命は男性より長いです。","Tuổi thọ bình quân của nữ giới dài hơn nam giới."],["女性の先生は5人います。","Có 5 cô giáo nữ."],["この店は女性に人気があります。","Cửa hàng này được nữ giới yêu thích."],["女性の服は3階で売っています。","Quần áo nữ bán ở tầng 3."]]},{"word":"どうも","reading":"どうも","meaning":"dường như (dùng khi phán đoán)","hanViet":"","lesson":47,"ex":[["どうもこの電車は遅れているようです。","Dường như chuyến tàu này đang bị chậm."],["どうも頭が重いです。","Dường như đầu tôi nặng trĩu."],["どうも山田さんは忙しいようです。","Dường như anh Yamada đang bận."],["どうもこの本は難しいようです。","Dường như cuốn sách này khó."],["どうも明日は雨のようです。","Dường như ngày mai sẽ mưa."]]},{"word":"婚約します","reading":"こんやくします","meaning":"đính hôn","hanViet":"HÔN ƯỚC","lesson":47,"ex":[["兄は来年、婚約します。","Anh trai tôi sẽ đính hôn vào năm sau."],["田中さんと山田さんは婚約しました。","Anh Tanaka và chị Yamada đã đính hôn."],["婚約したら、指輪をもらいます。","Khi đính hôn, người ta nhận nhẫn."],["姉は大学の友達と婚約しました。","Chị gái tôi đã đính hôn với bạn đại học."],["婚約した二人は来年結婚します。","Hai người đã đính hôn sẽ kết hôn vào năm sau."]]},{"word":"相手","reading":"あいて","meaning":"Đối phương, bạn cùng (chơi/nói chuyện)","hanViet":"TƯƠNG THỦ","lesson":47,"ex":[["試合の相手はとても強いです。","Đối thủ trong trận đấu rất mạnh."],["相手の話をよく聞いてください。","Hãy lắng nghe kỹ lời của đối phương."],["テニスの相手は山田さんです。","Đối thủ tennis là anh Yamada."],["相手の気持ちを考えましょう。","Hãy nghĩ đến cảm xúc của đối phương."],["話す相手がいなくて、寂しいです。","Không có người để nói chuyện nên tôi thấy buồn."]]},{"word":"知り合います","reading":"しりあいます","meaning":"quen biết","hanViet":"TRI HỢP","lesson":47,"ex":[["大学で田中さんと知り合いました。","Tôi đã quen anh Tanaka ở trường đại học."],["会社で多くの人と知り合いました。","Tôi đã quen nhiều người ở công ty."],["パーティーで新しい友達と知り合いました。","Tôi đã quen bạn mới ở buổi tiệc."],["旅行で日本人の友達と知り合いました。","Tôi đã quen bạn người Nhật trong chuyến du lịch."],["日本語のクラスで外国の友達と知り合いました。","Tôi đã quen bạn nước ngoài ở lớp tiếng Nhật."]]},{"word":"平均寿命","reading":"へいきんじゅみょう","meaning":"tuổi thọ bình quân","hanViet":"BÌNH QUÂN THỌ MỆNH","lesson":47,"ex":[["日本の平均寿命は世界で一番長いです。","Tuổi thọ bình quân của Nhật Bản dài nhất thế giới."],["日本の女性の平均寿命は87歳ぐらいです。","Tuổi thọ bình quân của phụ nữ Nhật Bản khoảng 87 tuổi."],["日本の平均寿命は毎年少し長くなっています。","Tuổi thọ bình quân của Nhật Bản mỗi năm dài thêm một chút."],["平均寿命が長くなると、病院がもっと必要になります。","Khi tuổi thọ bình quân tăng lên, bệnh viện càng cần thiết hơn."],["先生は平均寿命の話をしました。","Thầy giáo đã nói chuyện về tuổi thọ bình quân."]]},{"word":"比べます","reading":"くらべます","meaning":"so sánh","hanViet":"TỈ","lesson":47,"ex":[["東京と京都を比べてみました。","Tôi đã thử so sánh Tokyo và Kyoto."],["値段を比べてから、買いましょう。","Hãy so sánh giá cả rồi mua."],["去年と今年の天気を比べます。","Tôi so sánh thời tiết năm ngoái và năm nay."],["男性と女性の平均寿命を比べました。","Tôi đã so sánh tuổi thọ bình quân của nam giới và nữ giới."],["この二つの本を比べてください。","Hãy so sánh hai cuốn sách này."]]},{"word":"博士","reading":"はかせ","meaning":"tiến sĩ, học giả uyên bác","hanViet":"BÁC SĨ","lesson":47,"ex":[["田中さんは大学で働く博士です。","Anh Tanaka là tiến sĩ làm việc ở trường đại học."],["博士は難しい問題を調べています。","Tiến sĩ đang nghiên cứu vấn đề khó."],["その博士はとても有名です。","Vị tiến sĩ đó rất nổi tiếng."],["博士の話はおもしろかったです。","Câu chuyện của tiến sĩ rất thú vị."],["将来、博士になりたいです。","Tương lai, tôi muốn trở thành tiến sĩ."]]},{"word":"脳","reading":"のう","meaning":"Não, bộ não","hanViet":"NÃO","lesson":47,"ex":[["脳は体の中で一番大切です。","Não là quan trọng nhất trong cơ thể."],["脳を使って、日本語を覚えましょう。","Hãy dùng não để ghi nhớ tiếng Nhật."],["勉強すると、脳がよく働きます。","Khi học, não hoạt động tốt."],["医者は脳の病気を調べています。","Bác sĩ đang nghiên cứu bệnh về não."],["脳のことはまだよくわかりません。","Về não, tôi vẫn chưa hiểu rõ."]]},{"word":"化粧品","reading":"けしょうひん","meaning":"mỹ phẩm","hanViet":"HÓA TRANG PHẨM","lesson":47,"ex":[["母はデパートで化粧品を買いました。","Mẹ tôi đã mua mỹ phẩm ở cửa hàng bách hóa."],["この化粧品はとても高いです。","Mỹ phẩm này rất đắt."],["化粧品の店は2階にあります。","Cửa hàng mỹ phẩm ở tầng 2."],["姉は化粧品が好きです。","Chị gái tôi thích mỹ phẩm."],["新しい化粧品を使ってみました。","Tôi đã thử dùng mỹ phẩm mới."]]},{"word":"調べ","reading":"しらべ","meaning":"cuộc điều tra, nghiên cứu","hanViet":"ĐIỀU","lesson":47,"ex":[["先生は日本の歴史の調べをしました。","Thầy giáo đã nghiên cứu về lịch sử Nhật Bản."],["この調べは長い時間がかかりました。","Cuộc điều tra này mất thời gian dài."],["学生は図書館で調べをしています。","Sinh viên đang nghiên cứu ở thư viện."],["調べによると、日本の人口は減っています。","Theo điều tra, dân số Nhật Bản đang giảm."],["先生の調べはとても有名です。","Nghiên cứu của thầy giáo rất nổi tiếng."]]},{"word":"化粧","reading":"けしょう","meaning":"Trang điểm","hanViet":"HÓA TRANG","lesson":47,"ex":[["姉は毎朝化粧をします。","Chị gái tôi trang điểm mỗi sáng."],["化粧に30分かかります。","Trang điểm mất 30 phút."],["母は化粧が上手です。","Mẹ tôi trang điểm giỏi."],["パーティーの前に、化粧をしました。","Trước buổi tiệc, tôi đã trang điểm."],["きょうは化粧をしませんでした。","Hôm nay tôi đã không trang điểm."]]},{"word":"データ","reading":"データ","meaning":"số liệu, dữ liệu","hanViet":"","lesson":47,"ex":[["仕事でデータを使います。","Tôi dùng dữ liệu trong công việc."],["データをコンピューターに入れます。","Tôi nhập dữ liệu vào máy tính."],["このデータはとても大切です。","Dữ liệu này rất quan trọng."],["データを調べました。","Tôi đã kiểm tra dữ liệu."],["新しいデータを集めました。","Tôi đã thu thập dữ liệu mới."]]},{"word":"パトカー","reading":"パトカー","meaning":"xe ô-tô cảnh sát","hanViet":"","lesson":47,"ex":[["パトカーが道を走っています。","Xe cảnh sát đang chạy trên đường."],["事故があったので、パトカーが来ました。","Vì có tai nạn nên xe cảnh sát đã đến."],["パトカーの音が聞こえました。","Đã nghe thấy tiếng còi xe cảnh sát."],["パトカーが駅の前に止まっています。","Xe cảnh sát đang đậu trước nhà ga."],["子どもはパトカーが好きです。","Trẻ em thích xe cảnh sát."]]},{"word":"～によると","reading":"～によると","meaning":"theo ~ (biểu thị nguồn thông tin)","hanViet":"","lesson":47,"ex":[["新聞によると、明日は雨です。","Theo báo, ngày mai sẽ mưa."],["天気予報によると、あしたは晴れます。","Theo dự báo thời tiết, ngày mai sẽ nắng."],["先生によると、この試験は難しいそうです。","Theo thầy giáo, kỳ thi này dường như khó."],["テレビによると、事故がありました。","Theo TV, đã có tai nạn."],["友達によると、この店は安いそうです。","Theo bạn tôi, cửa hàng này dường như rẻ."]]},{"word":"大統領","reading":"だいとうりょう","meaning":"Tổng thống","hanViet":"ĐẠI THỐNG LÃNH","lesson":47,"ex":[["大統領はテレビで話しました。","Tổng thống đã nói chuyện trên TV."],["大統領はとても有名です。","Tổng thống rất nổi tiếng."],["大統領は会議に出ました。","Tổng thống đã tham dự cuộc họp."],["新聞に大統領の写真がありました。","Trên báo có ảnh của tổng thống."],["大統領は来月日本へ来ます。","Tổng thống sẽ đến Nhật Bản vào tháng sau."]]},{"word":"イラン","reading":"イラン","meaning":"nước IRAN","hanViet":"","lesson":47,"ex":[["イランは大きい国です。","Iran là một quốc gia lớn."],["友達はイランから来ました。","Bạn tôi đã đến từ Iran."],["イランに旅行に行きたいです。","Tôi muốn đi du lịch Iran."],["イランの料理はおいしいです。","Món ăn Iran rất ngon."],["イランの友達は日本語を勉強しています。","Bạn người Iran đang học tiếng Nhật."]]},{"word":"ホルモン","reading":"ホルモン","meaning":"hooc-môn","hanViet":"","lesson":47,"ex":[["ホルモンは人の体で大切です。","Hooc-môn quan trọng đối với cơ thể con người."],["医者はホルモンの話をしました。","Bác sĩ đã nói chuyện về hooc-môn."],["ホルモンは体を元気にします。","Hooc-môn làm cho cơ thể khỏe mạnh."],["病院でホルモンを調べました。","Tôi đã kiểm tra hooc-môn ở bệnh viện."],["ホルモンの勉強は難しいです。","Việc học về hooc-môn rất khó."]]},{"word":"下ろします、降ろします","reading":"おろします","meaning":"cho xuống, hạ xuống","hanViet":"HẠ GIÁNG","lesson":48,"ex":[["荷物を車から下ろしました。","Tôi đã dỡ hành lý xuống khỏi xe."],["駅で友達を降ろしました。","Tôi đã cho bạn xuống ở nhà ga."],["重いかばんを下ろしてください。","Hãy đặt chiếc cặp nặng xuống."],["子どもを学校の前で降ろしました。","Tôi đã cho con xuống trước trường học."],["バスを降りる前に、荷物を下ろしました。","Trước khi xuống xe buýt, tôi đã lấy hành lý xuống."]]},{"word":"届けます","reading":"とどけます","meaning":"gửi đến, chuyển đến","hanViet":"GIỚI","lesson":48,"ex":[["手紙を友達の家に届けました。","Tôi đã gửi thư đến nhà bạn."],["郵便局の人が荷物を届けました。","Nhân viên bưu điện đã chuyển hành lý đến."],["この書類を先生に届けてください。","Hãy chuyển tài liệu này cho thầy giáo."],["花を母に届けました。","Tôi đã gửi hoa cho mẹ."],["明日までにレポートを届けます。","Tôi sẽ nộp báo cáo trước ngày mai."]]},{"word":"嫌","reading":"いや","meaning":"không thích, ngán","hanViet":"HIỀM","lesson":48,"ex":[["私は雨の日が嫌です。","Tôi không thích ngày mưa."],["弟は野菜が嫌です。","Em trai tôi không thích rau."],["嫌な仕事はしたくありません。","Tôi không muốn làm công việc chán ngán."],["寒い冬は嫌です。","Tôi không thích mùa đông lạnh."],["暑い夏は嫌です。","Mùa hè nóng nực thật khó chịu."]]},{"word":"塾","reading":"じゅく","meaning":"trung tâm luyện thi, lớp học thêm","hanViet":"THỤC","lesson":48,"ex":[["弟は毎週塾へ行きます。","Em trai tôi đi học thêm mỗi tuần."],["塾の先生はとても親切です。","Thầy giáo ở trung tâm luyện thi rất tốt bụng."],["塾で英語を勉強します。","Tôi học tiếng Anh ở lớp học thêm."],["塾の生徒は20人います。","Trung tâm luyện thi có 20 học sinh."],["試験の前に、塾で勉強しました。","Trước kỳ thi, tôi đã học ở lớp học thêm."]]},{"word":"生徒","reading":"せいと","meaning":"học sinh","hanViet":"SINH ĐỒ","lesson":48,"ex":[["この学校の生徒は500人います。","Trường này có 500 học sinh."],["生徒は毎日勉強しています。","Học sinh học tập mỗi ngày."],["先生は生徒に宿題を出しました。","Thầy giáo đã giao bài tập cho học sinh."],["生徒は先生の話を聞いています。","Học sinh đang nghe lời thầy giáo."],["新しい生徒がクラスに入りました。","Học sinh mới đã vào lớp."]]},{"word":"者","reading":"もの","meaning":"người (khi đề cập tới người thân hay cấp dưới)","hanViet":"GIẢ","lesson":48,"ex":[["その者は会社の社長です。","Người đó là giám đốc công ty."],["若い者が多く働いています。","Nhiều người trẻ đang làm việc."],["この者は私の友達です。","Người này là bạn tôi."],["勉強する者は図書館へ行きます。","Người học đi đến thư viện."],["その者は日本語が上手です。","Người đó giỏi tiếng Nhật."]]},{"word":"入管","reading":"にゅうかん","meaning":"sở nhập cảnh","hanViet":"NHẬP QUẢN","lesson":48,"ex":[["ビザのことで、入管へ行きました。","Vì việc visa, tôi đã đến sở nhập cảnh."],["入管は駅の近くにあります。","Sở nhập cảnh ở gần nhà ga."],["入管で書類をもらいました。","Tôi đã nhận tài liệu ở sở nhập cảnh."],["入管は午前9時から午後5時までです。","Sở nhập cảnh mở từ 9 giờ sáng đến 5 giờ chiều."],["入管の人はとても親切でした。","Người ở sở nhập cảnh rất tốt bụng."]]},{"word":"再入国ビザ","reading":"さいにゅうこくビザ","meaning":"visa tái nhập cảnh","hanViet":"TÁI NHẬP QUỐC","lesson":48,"ex":[["旅行の前に、再入国ビザを取りました。","Trước chuyến du lịch, tôi đã lấy visa tái nhập cảnh."],["再入国ビザは入管でもらえます。","Visa tái nhập cảnh có thể nhận ở sở nhập cảnh."],["再入国ビザがないと、日本に戻れません。","Không có visa tái nhập cảnh thì không thể trở lại Nhật Bản."],["再入国ビザの値段は3,000円です。","Giá visa tái nhập cảnh là 3.000 yên."],["再入国ビザを取りに、入管へ行きました。","Tôi đã đến sở nhập cảnh để lấy visa tái nhập cảnh."]]},{"word":"～間","reading":"～かん","meaning":"trong ~ (nói về thời lượng)","hanViet":"GIAN","lesson":48,"ex":[["夏の休みの間、旅行に行きました。","Trong kỳ nghỉ hè, tôi đã đi du lịch."],["3日間、家で休みました。","Tôi đã nghỉ ở nhà trong 3 ngày."],["2時間の間、勉強しました。","Tôi đã học trong 2 giờ."],["日本にいる間、日本語を勉強します。","Trong thời gian ở Nhật Bản, tôi học tiếng Nhật."],["休みの間、毎日泳ぎました。","Trong kỳ nghỉ, tôi đã bơi mỗi ngày."]]},{"word":"いいことですね","reading":"いいことですね","meaning":"hay nhỉ/ được đấy nhỉ","hanViet":"","lesson":48,"ex":[["「試験に合格しました。」「いいことですね。」","Tôi đã thi đậu. Tốt quá nhỉ."],["「来月旅行に行きます。」「いいことですね。」","Tháng sau tôi sẽ đi du lịch. Hay đấy nhỉ."],["「新しい仕事が見つかりました。」「いいことですね。」","Tôi đã tìm được công việc mới. Tốt quá nhỉ."],["「友達が日本へ来ます。」「いいことですね。」","Bạn tôi sẽ đến Nhật Bản. Hay đấy nhỉ."],["「明日は休みです。」「いいことですね。」","Ngày mai được nghỉ. Tốt quá nhỉ."]]},{"word":"お忙しいですか","reading":"おいそがしいですか","meaning":"anh/chị đang bận phải không?","hanViet":"MANG","lesson":48,"ex":[["「先生、お忙しいですか。」「いいえ、暇です。」","Thưa thầy, thầy đang bận phải không? Không, tôi rảnh."],["「田中さん、お忙しいですか。」「はい、少し忙しいです。」","Anh Tanaka, anh đang bận phải không? Vâng, hơi bận."],["社長にお忙しいですかと聞きました。","Tôi đã hỏi giám đốc là có đang bận không."],["「お忙しいですか。」「いいえ、大丈夫です。」","Anh/chị đang bận phải không? Không, không sao đâu."],["会議の前に、先生にお忙しいですかと聞きました。","Trước cuộc họp, tôi đã hỏi thầy giáo là có đang bận không."]]},{"word":"久しぶり","reading":"ひさしぶり","meaning":"Lâu rồi mới (gặp/làm lại)","hanViet":"CỬU","lesson":48,"ex":[["久しぶりに友達に会いました。","Lâu rồi tôi mới gặp bạn."],["久しぶりに東京へ行きました。","Lâu rồi tôi mới đi Tokyo."],["久しぶりに母に電話をしました。","Lâu rồi tôi mới gọi điện cho mẹ."],["久しぶりに泳ぎました。","Lâu rồi tôi mới bơi."],["久しぶりですね。元気ですか。","Lâu rồi mới gặp. Anh/chị khỏe không?"]]},{"word":"営業","reading":"えいぎょう","meaning":"Kinh doanh, hoạt động bán hàng","hanViet":"DOANH NGHIỆP","lesson":48,"ex":[["この店の営業は午前9時から始まります。","Việc kinh doanh của cửa hàng này bắt đầu từ 9 giờ sáng."],["田中さんは営業の仕事をしています。","Anh Tanaka đang làm công việc kinh doanh."],["営業の人は毎日忙しいです。","Người làm kinh doanh bận mỗi ngày."],["この会社は営業の人が多いです。","Công ty này có nhiều nhân viên kinh doanh."],["営業の会議は毎週月曜日にあります。","Cuộc họp kinh doanh có vào thứ hai mỗi tuần."]]},{"word":"それまでに","reading":"それまでに","meaning":"đến trước lúc đó","hanViet":"","lesson":48,"ex":[["宿題はそれまでに終わってください。","Hãy làm xong bài tập trước lúc đó."],["それまでにレポートを出します。","Tôi sẽ nộp báo cáo trước lúc đó."],["それまでに準備をします。","Tôi sẽ chuẩn bị trước lúc đó."],["それまでに家に帰ります。","Tôi sẽ về nhà trước lúc đó."],["それまでにこの本を読みます。","Tôi sẽ đọc xong cuốn sách này trước lúc đó."]]},{"word":"かまいません","reading":"かまいません","meaning":"được rồi, không sao, không có gì đâu","hanViet":"","lesson":48,"ex":[["「ここに座ってもいいですか。」「はい、かまいません。」","Tôi ngồi đây được không? Vâng, được rồi."],["「明日でもいいですか。」「はい、かまいません。」","Ngày mai cũng được không? Vâng, không sao đâu."],["少し遅れても、かまいません。","Trễ một chút cũng không sao."],["「コーヒーでもいいですか。」「はい、かまいません。」","Cà phê cũng được không? Vâng, được rồi."],["写真を撮っても、かまいません。","Chụp ảnh cũng không sao."]]},{"word":"楽しみです","reading":"たのしみです","meaning":"mong chờ, háo hức","hanViet":"LẠC","lesson":48,"ex":[["来月の旅行が楽しみです。","Tôi đang mong chờ chuyến du lịch tháng sau."],["明日の試合が楽しみです。","Tôi đang háo hức trận đấu ngày mai."],["新しい映画が楽しみです。","Tôi đang mong chờ bộ phim mới."],["友達に会うのが楽しみです。","Tôi đang mong chờ được gặp bạn."],["夏の休みが楽しみです。","Tôi đang mong chờ kỳ nghỉ hè."]]},{"word":"もともと","reading":"もともと","meaning":"vốn dĩ","hanViet":"","lesson":48,"ex":[["田中さんはもともと京都の人です。","Anh Tanaka vốn dĩ là người Kyoto."],["この店はもともと小さい店でした。","Cửa hàng này vốn dĩ là cửa hàng nhỏ."],["私はもともと学生でした。","Tôi vốn dĩ là sinh viên."],["もともとこの町は静かでした。","Thị trấn này vốn dĩ yên tĩnh."],["山田さんはもともと先生でした。","Anh Yamada vốn dĩ là thầy giáo."]]},{"word":"代わりをします","reading":"かわりをします","meaning":"thay thế","hanViet":"ĐẠI","lesson":48,"ex":[["病気の先生の代わりをします。","Tôi thay thế thầy giáo bị ốm."],["田中さんの代わりをします。","Tôi thay thế anh Tanaka."],["きょうは私が代わりをします。","Hôm nay tôi sẽ thay thế."],["友達の代わりをしました。","Tôi đã thay thế bạn."],["明日、母の代わりをします。","Ngày mai, tôi sẽ thay thế mẹ."]]},{"word":"競走します","reading":"きょうそうします","meaning":"chạy đua","hanViet":"CẠNH TẨU","lesson":48,"ex":[["学校で友達と競走しました。","Tôi đã chạy đua với bạn ở trường."],["子どもたちはプールで競走します。","Các em nhỏ đua bơi ở bể bơi."],["弟と競走して、負けました。","Tôi đã chạy đua với em trai và thua."],["毎週、友達と競走します。","Mỗi tuần, tôi chạy đua với bạn."],["競走する前に、準備をしました。","Trước khi chạy đua, tôi đã chuẩn bị."]]},{"word":"芸","reading":"げい","meaning":"trò diễn, tiết mục, tài năng","hanViet":"NGHỆ","lesson":48,"ex":[["子どもはテレビで芸を見ました。","Trẻ em đã xem tiết mục biểu diễn trên TV."],["友達は歌の芸を見せました。","Bạn tôi đã cho xem tiết mục hát."],["サーカスの芸はおもしろいです。","Tiết mục xiếc rất thú vị."],["友達は芸が上手です。","Bạn tôi có tài năng biểu diễn giỏi."],["芸を見て、皆さんで笑いました。","Xem tiết mục, mọi người cùng cười."]]},{"word":"姿","reading":"すがた","meaning":"hình dáng, dáng vẻ","hanViet":"TƯ","lesson":48,"ex":[["母の優しい姿を見ました。","Tôi đã thấy dáng vẻ dịu dàng của mẹ."],["先生の姿が見えません。","Không thấy dáng thầy giáo đâu."],["写真に友達の姿があります。","Trong ảnh có hình dáng của bạn tôi."],["子どもの元気な姿を見て、うれしくなりました。","Thấy dáng vẻ khỏe mạnh của trẻ em, tôi thấy vui."],["山の美しい姿が見えます。","Nhìn thấy dáng vẻ đẹp của ngọn núi."]]},{"word":"心","reading":"こころ","meaning":"Trái tim, tâm hồn","hanViet":"TÂM","lesson":48,"ex":[["友達の心は優しいです。","Tấm lòng của bạn tôi rất dịu dàng."],["心からありがとうと言いました。","Tôi đã nói cảm ơn từ tận đáy lòng."],["心が疲れました。","Tâm hồn tôi mệt mỏi."],["母の心がよくわかります。","Tôi hiểu rõ tấm lòng của mẹ."],["楽しいときは、心が元気になります。","Khi vui, tâm hồn trở nên khỏe mạnh."]]},{"word":"とらえます","reading":"とらえます","meaning":"bắt, nắm bắt; giành được","hanViet":"","lesson":48,"ex":[["チャンスをとらえて、仕事を始めました。","Nắm bắt cơ hội, tôi đã bắt đầu công việc."],["歌は皆さんの心をとらえました。","Bài hát đã chinh phục trái tim mọi người."],["子どもはボールをとらえました。","Đứa trẻ đã bắt được quả bóng."],["写真で美しい山をとらえました。","Tôi đã ghi lại ngọn núi đẹp trong ảnh."],["試合でチャンスをとらえました。","Tôi đã nắm bắt cơ hội trong trận đấu."]]},{"word":"～にとって","reading":"～にとって","meaning":"đối với~","hanViet":"","lesson":48,"ex":[["私にとって、家族は大切です。","Đối với tôi, gia đình rất quan trọng."],["学生にとって、勉強は大切です。","Đối với sinh viên, việc học rất quan trọng."],["母にとって、子どもは大切です。","Đối với mẹ, con cái rất quan trọng."],["日本人にとって、お正月は大切です。","Đối với người Nhật, Tết rất quan trọng."],["私にとって、日本語は難しいです。","Đối với tôi, tiếng Nhật rất khó."]]},{"word":"ファイル","reading":"ファイル","meaning":"kẹp tài liệu, file tài liệu","hanViet":"","lesson":48,"ex":[["仕事のファイルをコンピューターに入れました。","Tôi đã nhập file công việc vào máy tính."],["ファイルを机の上に置きました。","Tôi đã đặt kẹp tài liệu lên bàn."],["このファイルは大切です。","File này rất quan trọng."],["ファイルの中に書類があります。","Trong kẹp tài liệu có tài liệu."],["新しいファイルを買いました。","Tôi đã mua kẹp tài liệu mới."]]},{"word":"楽しみます","reading":"たのしみます","meaning":"vui, vui thích","hanViet":"LẠC","lesson":48,"ex":[["休みに旅行を楽しみます。","Tôi tận hưởng chuyến du lịch trong kỳ nghỉ."],["音楽を楽しみます。","Tôi thưởng thức âm nhạc."],["友達と映画を楽しみました。","Tôi đã thưởng thức phim cùng bạn."],["夏に海で泳ぐのを楽しみます。","Vào mùa hè, tôi thích bơi ở biển."],["母と料理を楽しみます。","Tôi thưởng thức món ăn cùng mẹ."]]},{"word":"録音します","reading":"ろくおんします","meaning":"ghi âm","hanViet":"LỤC ÂM","lesson":48,"ex":[["先生の話を録音しました。","Tôi đã ghi âm lời thầy giáo."],["歌を録音します。","Tôi ghi âm bài hát."],["日本語の授業を録音しました。","Tôi đã ghi âm tiết học tiếng Nhật."],["友達の声を録音しました。","Tôi đã ghi âm giọng nói của bạn."],["録音して、あとで聞きます。","Tôi ghi âm rồi nghe lại sau."]]},{"word":"スピード","reading":"スピード","meaning":"tốc độ","hanViet":"","lesson":48,"ex":[["車のスピードは速いです。","Tốc độ của xe nhanh."],["スピードを出して、走りました。","Tôi đã tăng tốc và chạy."],["新幹線のスピードはとても速いです。","Tốc độ của tàu Shinkansen rất nhanh."],["スピードが速すぎます。","Tốc độ quá nhanh."],["スピードを落としてください。","Hãy giảm tốc độ."]]},{"word":"サーカス","reading":"サーカス","meaning":"xiếc","hanViet":"","lesson":48,"ex":[["子どもとサーカスを見に行きました。","Tôi đã đi xem xiếc cùng con."],["サーカスはとてもおもしろかったです。","Xiếc rất thú vị."],["サーカスで動物を見ました。","Tôi đã xem động vật ở rạp xiếc."],["サーカスの芸はすごいです。","Tiết mục xiếc thật tuyệt vời."],["明日、サーカスへ行きます。","Ngày mai, tôi sẽ đi xem xiếc."]]},{"word":"親","reading":"おや","meaning":"cha mẹ","hanViet":"THÂN","lesson":48,"ex":[["親は子どものために働きます。","Cha mẹ làm việc vì con cái."],["親に電話をしました。","Tôi đã gọi điện cho cha mẹ."],["親と旅行に行きました。","Tôi đã đi du lịch cùng cha mẹ."],["親の気持ちがよくわかります。","Tôi hiểu rõ cảm xúc của cha mẹ."],["親は子どもを大切にします。","Cha mẹ trân trọng con cái."]]},{"word":"小学生","reading":"しょうがくせい","meaning":"học sinh tiểu học","hanViet":"TIỂU HỌC SINH","lesson":48,"ex":[["小学生は学校で勉強します。","Học sinh tiểu học học ở trường."],["小学生の子どもが公園で遊んでいます。","Trẻ em tiểu học đang chơi ở công viên."],["小学生は毎日元気です。","Học sinh tiểu học khỏe mạnh mỗi ngày."],["小学生に日本語を教えています。","Tôi đang dạy tiếng Nhật cho học sinh tiểu học."],["小学生のとき、よく泳ぎました。","Khi còn là học sinh tiểu học, tôi thường bơi."]]},{"word":"～パーセント","reading":"～パーセント","meaning":"–phần trăm","hanViet":"","lesson":48,"ex":[["試験で90パーセント取りました。","Tôi đã đạt 90 phần trăm trong kỳ thi."],["学生の50パーセントは女性です。","50 phần trăm sinh viên là nữ giới."],["値段が20パーセント安くなりました。","Giá đã rẻ đi 20 phần trăm."],["この店に来る人の80パーセントは日本人です。","80 phần trăm người đến cửa hàng này là người Nhật."],["100パーセント元気です。","Tôi khỏe 100 phần trăm."]]},{"word":"その次","reading":"そのつぎ","meaning":"tiếp theo đó","hanViet":"THỨ","lesson":48,"ex":[["その次は英語の授業です。","Tiếp theo đó là tiết học tiếng Anh."],["その次に、友達に会います。","Tiếp theo đó, tôi sẽ gặp bạn."],["その次はどこへ行きますか。","Tiếp theo đó sẽ đi đâu?"],["その次に、宿題をします。","Tiếp theo đó, tôi sẽ làm bài tập."],["映画を見て、その次にコーヒーを飲みました。","Sau phim, tiếp theo đó chúng tôi đã uống cà phê."]]},{"word":"習字","reading":"しゅうじ","meaning":"học viết chữ bằng bút lông","hanViet":"TẬP TỰ","lesson":48,"ex":[["小学生のとき、習字を習いました。","Khi còn là học sinh tiểu học, tôi đã học viết chữ bằng bút lông."],["習字の先生はとても上手です。","Thầy giáo thư pháp rất giỏi."],["習字で漢字を書きます。","Tôi viết chữ Hán bằng thư pháp."],["毎週、習字のクラスに行きます。","Mỗi tuần, tôi đi học lớp thư pháp."],["習字は日本の文化です。","Thư pháp là văn hóa Nhật Bản."]]},{"word":"勤めます","reading":"つとめます","meaning":"làm việc","hanViet":"CẦN","lesson":49,"ex":[["私は銀行に勤めています。","Tôi đang làm việc ở ngân hàng."],["父は会社に勤めています。","Bố tôi đang làm việc ở công ty."],["田中さんは東京の会社に勤めています。","Anh Tanaka đang làm việc ở công ty tại Tokyo."],["姉は学校に勤めています。","Chị gái tôi đang làm việc ở trường học."],["卒業してから、この会社に勤めています。","Từ khi tốt nghiệp, tôi làm việc ở công ty này."]]},{"word":"休みます","reading":"やすみます","meaning":"nghỉ ngơi","hanViet":"HƯU","lesson":49,"ex":[["きょうは会社を休みます。","Hôm nay tôi nghỉ làm."],["病気のときは、学校を休みます。","Khi bị ốm, tôi nghỉ học."],["日曜日は家で休みます。","Chủ nhật tôi nghỉ ở nhà."],["疲れましたから、少し休みます。","Vì mệt nên tôi nghỉ một chút."],["明日は仕事を休みます。","Ngày mai tôi nghỉ làm."]]},{"word":"過ごします","reading":"すごします","meaning":"trải qua (thời gian)","hanViet":"QUÁ","lesson":49,"ex":[["休みは家で過ごします。","Kỳ nghỉ tôi trải qua ở nhà."],["夏の休みは海で過ごしました。","Kỳ nghỉ hè tôi đã trải qua ở biển."],["友達と楽しい時間を過ごしました。","Tôi đã trải qua thời gian vui vẻ cùng bạn."],["お正月は家族と過ごします。","Tết tôi trải qua cùng gia đình."],["子どものときは田舎で過ごしました。","Khi còn nhỏ, tôi đã trải qua ở nông thôn."]]},{"word":"寄ります","reading":"よります","meaning":"ghé vào","hanViet":"KÍ","lesson":49,"ex":[["帰りにスーパーに寄ります。","Trên đường về, tôi ghé vào siêu thị."],["銀行に寄ってから、会社へ行きます。","Sau khi ghé ngân hàng, tôi đi đến công ty."],["本屋に寄りました。","Tôi đã ghé vào hiệu sách."],["友達の家に寄ります。","Tôi ghé vào nhà bạn."],["駅の前の店に寄りました。","Tôi đã ghé vào cửa hàng trước nhà ga."]]},{"word":"召し上がります","reading":"めしあがります","meaning":"ăn, uống (kính ngữ)","hanViet":"TRIỆU THƯỢNG","lesson":49,"ex":[["先生、どうぞお茶を召し上がってください。","Thưa thầy, xin mời dùng trà."],["先生はケーキを召し上がりました。","Thầy giáo đã ăn bánh."],["社長は昼ごはんを召し上がっています。","Giám đốc đang ăn trưa."],["田中先生はもう昼ごはんを召し上がりましたか。","Thầy Tanaka đã ăn trưa chưa ạ?"],["先生、コーヒーを召し上がりませんか。","Thưa thầy, thầy có dùng cà phê không ạ?"]]},{"word":"おっしゃいます","reading":"おっしゃいます","meaning":"nói (kính ngữ)","hanViet":"","lesson":49,"ex":[["先生は「明日は休みです」とおっしゃいました。","Thầy giáo đã nói: Ngày mai được nghỉ."],["社長は何とおっしゃいましたか。","Giám đốc đã nói gì ạ?"],["社長は会議があるとおっしゃいました。","Giám đốc đã nói là có cuộc họp."],["田中先生は「日本語はおもしろいです」とおっしゃいました。","Thầy Tanaka đã nói: Tiếng Nhật rất thú vị."],["先生がおっしゃったことを覚えています。","Tôi nhớ điều thầy giáo đã nói."]]},{"word":"なさいます","reading":"なさいます","meaning":"làm (kính ngữ)","hanViet":"","lesson":49,"ex":[["先生はきょう何をなさいますか。","Hôm nay thầy giáo làm gì ạ?"],["社長は会議をなさいます。","Giám đốc sẽ họp."],["先生は仕事をなさいました。","Thầy giáo đã làm việc."],["先生は休みに何をなさいますか。","Thầy giáo làm gì trong kỳ nghỉ ạ?"],["社長は来月旅行をなさいます。","Giám đốc sẽ đi du lịch vào tháng sau."]]},{"word":"ご覧になります","reading":"ごらんになります","meaning":"xem (kính ngữ)","hanViet":"LÃM","lesson":49,"ex":[["先生は映画をご覧になりました。","Thầy giáo đã xem phim."],["社長はテレビをご覧になっています。","Giám đốc đang xem TV."],["先生はこの写真をご覧になりますか。","Thầy giáo có xem bức ảnh này không ạ?"],["田中先生は新しい本をご覧になりました。","Thầy Tanaka đã xem cuốn sách mới."],["先生は京都をご覧になりましたか。","Thầy giáo đã ngắm Kyoto chưa ạ?"]]},{"word":"ご存知です","reading":"ごぞんじです","meaning":"biết (tôn kính ngữ của しっています)","hanViet":"TỒN TRI","lesson":49,"ex":[["先生は田中さんをご存知ですか。","Thầy giáo có biết anh Tanaka không ạ?"],["社長はこの話をご存知です。","Giám đốc biết chuyện này."],["先生は日本の歴史をご存知です。","Thầy giáo biết lịch sử Nhật Bản."],["田中先生はこの店をご存知ですか。","Thầy Tanaka có biết cửa hàng này không ạ?"],["先生は私の名前をご存知ですか。","Thầy giáo có biết tên tôi không ạ?"]]},{"word":"あいさつ","reading":"あいさつ","meaning":"lời chào hỏi","hanViet":"","lesson":49,"ex":[["朝、先生にあいさつをします。","Buổi sáng, tôi chào hỏi thầy giáo."],["あいさつは大切です。","Lời chào hỏi rất quan trọng."],["会社で皆さんにあいさつをしました。","Tôi đã chào hỏi mọi người ở công ty."],["あいさつをすると、気持ちがいいです。","Khi chào hỏi, tâm trạng thật tốt."],["子どもは元気にあいさつをします。","Trẻ em chào hỏi một cách vui vẻ."]]},{"word":"灰皿","reading":"はいざら","meaning":"Gạt tàn thuốc","hanViet":"KHÔI MÃNH","lesson":49,"ex":[["灰皿は机の上にあります。","Gạt tàn thuốc ở trên bàn."],["レストランに灰皿があります。","Trong nhà hàng có gạt tàn thuốc."],["灰皿をください。","Cho tôi xin gạt tàn thuốc."],["たばこを吸う人は灰皿を使います。","Người hút thuốc dùng gạt tàn thuốc."],["灰皿がありません。","Không có gạt tàn thuốc."]]},{"word":"旅館","reading":"りょかん","meaning":"Nhà trọ kiểu Nhật","hanViet":"LỮ QUÁN","lesson":49,"ex":[["京都の旅館に泊まりました。","Tôi đã ở nhà trọ kiểu Nhật tại Kyoto."],["旅館はとても静かです。","Nhà trọ kiểu Nhật rất yên tĩnh."],["旅館で温泉に入りました。","Tôi đã tắm suối nước nóng ở nhà trọ."],["旅行のとき、旅館に泊まります。","Khi đi du lịch, tôi ở nhà trọ kiểu Nhật."],["この旅館は有名です。","Nhà trọ này nổi tiếng."]]},{"word":"バス停","reading":"バスてい","meaning":"trạm dừng xe BUS","hanViet":"ĐÌNH","lesson":49,"ex":[["バス停は駅の前にあります。","Trạm xe buýt ở trước nhà ga."],["バス停でバスを待ちます。","Tôi đợi xe buýt ở trạm."],["バス停は学校の近くにあります。","Trạm xe buýt ở gần trường học."],["バス停まで歩いて5分です。","Đi bộ đến trạm xe buýt mất 5 phút."],["バス停に人がたくさんいます。","Ở trạm xe buýt có rất nhiều người."]]},{"word":"貿易","reading":"ぼうえき","meaning":"Thương mại, mậu dịch quốc tế","hanViet":"MẬU DỊCH","lesson":49,"ex":[["父は貿易の会社で働いています。","Bố tôi làm việc ở công ty thương mại."],["日本は貿易の国です。","Nhật Bản là quốc gia thương mại."],["貿易の仕事はおもしろいです。","Công việc thương mại rất thú vị."],["貿易の勉強をしています。","Tôi đang học về thương mại."],["貿易の会議がありました。","Đã có cuộc họp về thương mại."]]},{"word":"帰りに","reading":"かえりに","meaning":"trên đường về, ở lượt về","hanViet":"QUY","lesson":49,"ex":[["帰りにスーパーへ行きます。","Trên đường về, tôi đi siêu thị."],["帰りに本屋に寄ります。","Trên đường về, tôi ghé hiệu sách."],["帰りに友達に会いました。","Trên đường về, tôi đã gặp bạn."],["帰りに銀行へ行きました。","Trên đường về, tôi đã đi ngân hàng."],["帰りに花を買いました。","Trên đường về, tôi đã mua hoa."]]},{"word":"たまに","reading":"たまに","meaning":"đôi khi, thỉnh thoảng","hanViet":"","lesson":49,"ex":[["たまに映画を見ます。","Thỉnh thoảng tôi xem phim."],["たまに友達に電話をします。","Thỉnh thoảng tôi gọi điện cho bạn."],["たまに旅行に行きます。","Thỉnh thoảng tôi đi du lịch."],["たまに母に手紙を書きます。","Thỉnh thoảng tôi viết thư cho mẹ."],["たまに泳ぎに行きます。","Thỉnh thoảng tôi đi bơi."]]},{"word":"ちっとも","reading":"ちっとも","meaning":"một chút cũng không (dùng với thể phủ định)","hanViet":"","lesson":49,"ex":[["日本語がちっともわかりません。","Tôi không hiểu tiếng Nhật chút nào."],["きょうはちっとも寒くありません。","Hôm nay không lạnh chút nào."],["ちっとも忙しくありません。","Không bận chút nào."],["この本はちっともおもしろくありません。","Cuốn sách này không thú vị chút nào."],["ちっとも疲れていません。","Tôi không mệt chút nào."]]},{"word":"遠慮なく","reading":"えんりょなく","meaning":"xin đừng ngại","hanViet":"VIỄN LỰ","lesson":49,"ex":[["遠慮なく、どうぞ食べてください。","Xin đừng ngại, mời bạn cứ ăn nhé."],["何か質問があったら、遠慮なく聞いてください。","Nếu có câu hỏi gì, xin đừng ngại cứ hỏi nhé."],["遠慮なく意見を言ってください。","Xin đừng ngại, hãy nói ý kiến của bạn."],["困ったら、遠慮なく電話してください。","Nếu gặp khó khăn, xin đừng ngại cứ gọi điện cho tôi."],["この本は遠慮なく使ってください。","Quyển sách này, xin đừng ngại cứ dùng nhé."]]},{"word":"～年～組","reading":"～ねん～くみ","meaning":"tên lớp (ví dụ: lớp 13)","hanViet":"NIÊN TỔ","lesson":49,"ex":[["弟は3年2組です。","Em trai tôi học lớp 2 khối 3."],["娘は1年3組です。","Con gái tôi học lớp 3 khối 1."],["山田さんの子どもは5年1組です。","Con của anh Yamada học lớp 1 khối 5."],["あの教室は4年2組です。","Phòng học kia là lớp 2 khối 4."],["3年2組の教室は2階です。","Phòng học của lớp 2 khối 3 ở tầng 2."]]},{"word":"では","reading":"では","meaning":"vậy thì (dạng lịch sự của じゃ)","hanViet":"","lesson":49,"ex":[["では、始めましょう。","Vậy thì, chúng ta bắt đầu nhé."],["では、また明日。","Vậy thì, hẹn gặp lại ngày mai."],["では、失礼します。","Vậy thì, tôi xin phép."],["時間です。では、行きましょう。","Đến giờ rồi. Vậy thì, chúng ta đi thôi."],["では、よろしくお願いします。","Vậy thì, mong anh/chị giúp đỡ."]]},{"word":"よろしくお伝えください","reading":"よろしくおつたえください","meaning":"cho tôi gửi lời hỏi thăm","hanViet":"TRUYỀN","lesson":49,"ex":[["お父さんによろしくお伝えください。","Cho tôi gửi lời hỏi thăm tới bố anh/chị nhé."],["山田さんによろしくお伝えください。","Cho tôi gửi lời hỏi thăm tới anh Yamada nhé."],["奥様によろしくお伝えください。","Cho tôi gửi lời hỏi thăm tới phu nhân nhé."],["田中先生によろしくお伝えください。","Cho tôi gửi lời hỏi thăm tới thầy Tanaka nhé."],["田中さんに会ったら、よろしくお伝えください。","Nếu gặp anh Tanaka, cho tôi gửi lời hỏi thăm nhé."]]},{"word":"失礼いたします","reading":"しつれいいたします","meaning":"xin phép (dạng khiêm tốn của しつれいします)","hanViet":"THẤT LỄ","lesson":49,"ex":[["それでは、失礼いたします。","Vậy thì, tôi xin phép."],["失礼いたします。田中と申します。","Xin phép. Tôi là Tanaka."],["先に失礼いたします。お疲れ様でした。","Tôi xin phép về trước. Anh/chị đã vất vả rồi."],["どうもありがとうございました。失礼いたします。","Cảm ơn anh/chị rất nhiều. Tôi xin phép."],["失礼いたします。あした、また参ります。","Xin phép. Ngày mai tôi lại đến."]]},{"word":"講師","reading":"こうし","meaning":"Giảng viên, người giảng dạy","hanViet":"GIẢNG SƯ","lesson":49,"ex":[["あしたの講演会の講師は山田先生です。","Giảng viên của buổi nói chuyện ngày mai là thầy Yamada."],["講師は有名な作家です。","Giảng viên là một nhà văn nổi tiếng."],["講師の話はとてもおもしろかったです。","Câu chuyện của giảng viên rất thú vị."],["講師に質問しました。","Tôi đã hỏi giảng viên một câu hỏi."],["講師は京都から来ました。","Giảng viên đến từ Kyoto."]]},{"word":"多くの～","reading":"おおくの～","meaning":"nhiều ~","hanViet":"ĐA","lesson":49,"ex":[["多くの学生がこの大学で勉強しています。","Nhiều sinh viên đang học ở trường đại học này."],["多くの人がこの映画を見ました。","Nhiều người đã xem bộ phim này."],["この本は多くの国で読まれています。","Quyển sách này được đọc ở nhiều nước."],["多くの子どもがこの歌を歌います。","Nhiều trẻ em hát bài hát này."],["多くの会社員がこの電車に乗ります。","Nhiều nhân viên công ty đi chuyến tàu này."]]},{"word":"作品","reading":"さくひん","meaning":"tác phẩm","hanViet":"TÁC PHẨM","lesson":49,"ex":[["この作家の作品はとても有名です。","Tác phẩm của nhà văn này rất nổi tiếng."],["私はこの作品が好きです。","Tôi thích tác phẩm này."],["この作品は映画になりました。","Tác phẩm này đã được chuyển thể thành phim."],["作品の名前は「春の花」です。","Tên của tác phẩm là \"Hoa mùa xuân\"."],["図書館でこの作家の作品を借りました。","Tôi đã mượn tác phẩm của nhà văn này ở thư viện."]]},{"word":"受賞します","reading":"じゅしょうします","meaning":"được giải thưởng","hanViet":"THỤ THƯỞNG","lesson":49,"ex":[["この作家は去年ノーベル賞を受賞しました。","Nhà văn này năm ngoái đã nhận giải Nobel."],["山中さんは2012年にノーベル賞を受賞しました。","Ông Yamanaka đã nhận giải Nobel vào năm 2012."],["彼女は若いときにノーベル賞を受賞しました。","Cô ấy đã nhận giải Nobel khi còn trẻ."],["受賞したとき、とてもうれしかったです。","Khi nhận giải, tôi rất vui."],["受賞した人は、日本の作家です。","Người nhận giải là một nhà văn Nhật Bản."]]},{"word":"世界的に","reading":"せかいてきに","meaning":"mang tính chất thế giới, toàn cầu","hanViet":"THẾ GIỚI ĐÍCH","lesson":49,"ex":[["この作家は世界的に有名です。","Nhà văn này nổi tiếng trên toàn thế giới."],["この歌は世界的に知られています。","Bài hát này được biết đến trên toàn thế giới."],["この映画は世界的に人気があります。","Bộ phim này được yêu thích trên toàn thế giới."],["この本は世界的に読まれています。","Quyển sách này được đọc trên toàn thế giới."],["日本語は世界的に勉強されています。","Tiếng Nhật được học trên toàn thế giới."]]},{"word":"作家","reading":"さっか","meaning":"nhà văn","hanViet":"TÁC GIA","lesson":49,"ex":[["この作家の小説はおもしろいです。","Tiểu thuyết của nhà văn này rất hay."],["私は将来作家になりたいです。","Sau này tôi muốn trở thành nhà văn."],["あの作家は京都に住んでいます。","Nhà văn kia sống ở Kyoto."],["作家は毎日小説を書きます。","Nhà văn viết tiểu thuyết mỗi ngày."],["有名な作家に会いました。","Tôi đã gặp một nhà văn nổi tiếng."]]},{"word":"長男","reading":"ちょうなん","meaning":"Con trai trưởng","hanViet":"TRƯỞNG NAM","lesson":49,"ex":[["私は長男です。","Tôi là con trai trưởng."],["田中さんの長男は医者です。","Con trai trưởng của anh Tanaka là bác sĩ."],["長男は東京の大学で勉強しています。","Con trai trưởng đang học ở một trường đại học tại Tokyo."],["山田さんの長男は去年結婚しました。","Con trai trưởng của anh Yamada đã kết hôn năm ngoái."],["長男は今年大学を卒業します。","Con trai trưởng sẽ tốt nghiệp đại học năm nay."]]},{"word":"障害","reading":"しょうがい","meaning":"trở ngại, rối loạn, khuyết tật","hanViet":"CHƯỚNG HẠI","lesson":49,"ex":[["彼は耳に障害があります。","Anh ấy bị khiếm thính."],["障害があっても、毎日元気に働いています。","Dù có khuyết tật, anh ấy vẫn làm việc khỏe mạnh mỗi ngày."],["この作家は目に障害を持っています。","Nhà văn này bị khiếm thị."],["障害のある人も、この電車に乗ることができます。","Người khuyết tật cũng có thể đi chuyến tàu này."],["目に障害がある人は、この本が読めません。","Người khiếm thị không đọc được quyển sách này."]]},{"word":"お持ちです","reading":"おもちです","meaning":"có (cách nói tôn kính của もっています)","hanViet":"TRÌ","lesson":49,"ex":[["田中先生はたくさんの本をお持ちです。","Thầy Tanaka có rất nhiều sách."],["山田さんは古い時計をお持ちです。","Anh Yamada có một chiếc đồng hồ cũ."],["先生は日本の切手をお持ちですか。","Thầy có tem Nhật không ạ?"],["山田さんは車をお持ちですか。","Anh Yamada có xe ô tô không ạ?"],["お客様はパスポートをお持ちですか。","Quý khách có mang hộ chiếu không ạ?"]]},{"word":"作曲","reading":"さっきょく","meaning":"Sáng tác nhạc","hanViet":"TÁC KHÚC","lesson":49,"ex":[["彼は作曲が好きです。","Anh ấy thích sáng tác nhạc."],["この音楽家は作曲をします。","Nhạc sĩ này sáng tác nhạc."],["作曲は難しいですが、楽しいです。","Sáng tác nhạc khó nhưng vui."],["私は小さいときから作曲を勉強しています。","Tôi học sáng tác nhạc từ khi còn nhỏ."],["彼の作曲した歌は有名です。","Bài hát do anh ấy sáng tác rất nổi tiếng."]]},{"word":"活動","reading":"かつどう","meaning":"hoạt động","hanViet":"HOẠT ĐỘNG","lesson":49,"ex":[["大学でスポーツの活動をしています。","Tôi tham gia hoạt động thể thao ở trường đại học."],["ボランティアの活動をしています。","Tôi tham gia hoạt động tình nguyện."],["彼の活動は世界的に有名です。","Hoạt động của anh ấy nổi tiếng trên toàn thế giới."],["この活動は子どもたちのためにしています。","Hoạt động này là vì các em nhỏ."],["学校の活動は土曜日です。","Hoạt động của trường là vào thứ Bảy."]]},{"word":"それでは","reading":"それでは","meaning":"thế thì (chỉ sự bắt đầu hay kết thúc)","hanViet":"","lesson":49,"ex":[["それでは、始めましょう。","Vậy thì, chúng ta bắt đầu nhé."],["それでは、また来週。","Vậy thì, hẹn gặp lại tuần sau."],["それでは、今日の授業は終わりです。","Vậy thì, buổi học hôm nay kết thúc tại đây."],["それでは、行きましょう。","Vậy thì, chúng ta đi thôi."],["それでは、またあした。","Vậy thì, hẹn gặp lại ngày mai."]]},{"word":"いらっしゃいます","reading":"いらっしゃいます","meaning":"ở, có, đi, đến (tôn kính ngữ của います、いきます、きます)","hanViet":"","lesson":49,"ex":[["先生はいらっしゃいますか。","Thầy có ở đây không ạ?"],["社長は今会議室にいらっしゃいます。","Giám đốc hiện đang ở trong phòng họp."],["田中さんはあした会社にいらっしゃいますか。","Ngày mai anh Tanaka có đến công ty không ạ?"],["先生はもういらっしゃいました。","Thầy đã đến rồi ạ."],["社長は来週京都にいらっしゃいます。","Tuần sau giám đốc sẽ đến Kyoto."]]},{"word":"～様","reading":"～さま","meaning":"ngài ~, ông ~, bà ~ (tôn kính ngữ của ～さん)","hanViet":"DẠNG","lesson":49,"ex":[["田中様、電話です。","Anh Tanaka, có điện thoại cho anh ạ."],["山田様、こちらへどうぞ。","Mời anh Yamada đi lối này ạ."],["田中様、お元気ですか。","Anh Tanaka có khỏe không ạ?"],["山田様にこの手紙を渡してください。","Xin hãy đưa bức thư này cho anh Yamada."],["田中様、お荷物はこちらです。","Anh Tanaka, hành lý của anh ở đây ạ."]]},{"word":"奥様","reading":"おくさま","meaning":"Bà, phu nhân (kính ngữ)","hanViet":"ÁO DẠNG","lesson":49,"ex":[["田中さんの奥様は先生です。","Phu nhân của anh Tanaka là giáo viên."],["奥様はお元気ですか。","Phu nhân có khỏe không ạ?"],["山田さんの奥様はとても親切です。","Phu nhân của anh Yamada rất tốt bụng."],["田中さんの奥様は旅行が好きです。","Phu nhân của anh Tanaka thích đi du lịch."],["奥様はピアノが上手です。","Phu nhân chơi piano rất giỏi."]]},{"word":"どなたでも","reading":"どなたでも","meaning":"vị nào cũng (kính ngữ của だれでも)","hanViet":"","lesson":49,"ex":[["どなたでもこのコンサートに来ることができます。","Bất cứ vị nào cũng có thể đến buổi hòa nhạc này."],["この本はどなたでも読むことができます。","Quyển sách này vị nào cũng có thể đọc."],["どなたでも参加できます。","Vị nào cũng có thể tham gia."],["どなたでも入ることができます。","Vị nào cũng có thể vào."],["この講演会はどなたでも聞くことができます。","Buổi nói chuyện này vị nào cũng có thể nghe."]]},{"word":"経歴","reading":"けいれき","meaning":"Lý lịch, quá trình công tác","hanViet":"KINH LỊCH","lesson":49,"ex":[["先生の経歴を教えてください。","Xin hãy cho tôi biết lý lịch của thầy."],["この作家の経歴はおもしろいです。","Lý lịch của nhà văn này rất thú vị."],["経歴を書きました。","Tôi đã viết lý lịch."],["社長の経歴を読みました。","Tôi đã đọc lý lịch của giám đốc."],["彼の経歴を知りたいです。","Tôi muốn biết lý lịch của anh ấy."]]},{"word":"医学部","reading":"いがくぶ","meaning":"khoa y","hanViet":"Y HỌC BỘ","lesson":49,"ex":[["弟は医学部で勉強しています。","Em trai tôi đang học ở khoa y."],["私は医学部に入りたいです。","Tôi muốn vào khoa y."],["東京大学の医学部は有名です。","Khoa y của Đại học Tokyo rất nổi tiếng."],["医学部の学生は忙しいです。","Sinh viên khoa y rất bận."],["兄は医学部を卒業しました。","Anh trai tôi đã tốt nghiệp khoa y."]]},{"word":"目指します","reading":"めざします","meaning":"hướng đến, muốn trở thành","hanViet":"MỤC CHỈ","lesson":49,"ex":[["私は医者を目指しています。","Tôi đang hướng tới trở thành bác sĩ."],["弟は歌手を目指しています。","Em trai tôi đang hướng tới trở thành ca sĩ."],["私は大学の先生を目指します。","Tôi muốn trở thành giảng viên đại học."],["オリンピックを目指して、毎日練習しています。","Tôi luyện tập mỗi ngày để hướng tới Olympic."],["彼は作家を目指しています。","Anh ấy đang hướng tới trở thành nhà văn."]]},{"word":"進みます","reading":"すすみます","meaning":"học lên","hanViet":"TIẾN","lesson":49,"ex":[["弟は大学に進みます。","Em trai tôi sẽ học lên đại học."],["私は高校に進みたいです。","Tôi muốn học lên cấp ba."],["妹は医学部に進みました。","Em gái tôi đã học lên khoa y."],["来年、大学に進みます。","Năm sau tôi sẽ học lên đại học."],["多くの学生が大学に進みます。","Nhiều học sinh học lên đại học."]]},{"word":"IPS細胞","reading":"アイピーエスさいぼう","meaning":"tế bào IPS","hanViet":"TẾ BÀO","lesson":49,"ex":[["山中さんはIPS細胞を開発しました。","Ông Yamanaka đã phát triển tế bào IPS."],["IPS細胞は医学に大切です。","Tế bào IPS rất quan trọng đối với y học."],["IPS細胞はマウスから作られました。","Tế bào IPS được tạo ra từ chuột."],["山中さんはIPS細胞でノーベル賞を受賞しました。","Ông Yamanaka đã nhận giải Nobel nhờ tế bào IPS."],["IPS細胞の話はおもしろいです。","Câu chuyện về tế bào IPS rất thú vị."]]},{"word":"開発します","reading":"かいはつします","meaning":"phát triển","hanViet":"KHAI PHÁT","lesson":49,"ex":[["この会社は新しい薬を開発しました。","Công ty này đã phát triển một loại thuốc mới."],["新しいコンピューターを開発しています。","Chúng tôi đang phát triển một chiếc máy tính mới."],["彼は新しい機械を開発しました。","Anh ấy đã phát triển một cỗ máy mới."],["この会社は新しい車を開発しています。","Công ty này đang phát triển một chiếc xe mới."],["新しい薬を開発するために、毎日研究しています。","Tôi nghiên cứu mỗi ngày để phát triển thuốc mới."]]},{"word":"マウス","reading":"マウス","meaning":"chuột","hanViet":"","lesson":49,"ex":[["マウスは小さい動物です。","Chuột là một loài động vật nhỏ."],["実験でマウスを使います。","Người ta dùng chuột trong thí nghiệm."],["マウスからIPS細胞が作られました。","Tế bào IPS được tạo ra từ chuột."],["実験のマウスは白いです。","Con chuột thí nghiệm màu trắng."],["マウスとヒトは違います。","Chuột và người thì khác nhau."]]},{"word":"ヒト","reading":"ヒト","meaning":"người","hanViet":"","lesson":49,"ex":[["ヒトは考えることができます。","Con người có thể suy nghĩ."],["マウスとヒトの体は違います。","Cơ thể của chuột và người thì khác nhau."],["ヒトは病気になります。","Con người bị bệnh."],["ヒトはことばを話します。","Con người nói bằng ngôn ngữ."],["ヒトと動物は違います。","Con người và động vật thì khác nhau."]]},{"word":"講演会","reading":"こうえんかい","meaning":"buổi nói chuyện","hanViet":"GIẢNG DIỄN HỘI","lesson":49,"ex":[["あした講演会があります。","Ngày mai có buổi nói chuyện."],["講演会の講師は山田先生です。","Giảng viên của buổi nói chuyện là thầy Yamada."],["講演会で山中さんの話を聞きました。","Tôi đã nghe ông Yamanaka nói chuyện ở buổi nói chuyện."],["講演会は午後2時からです。","Buổi nói chuyện bắt đầu lúc 2 giờ chiều."],["多くの人が講演会に来ました。","Nhiều người đã đến buổi nói chuyện."]]},{"word":"山中伸弥","reading":"やまなかしんや","meaning":"nhà nghiên cứu y học người Nhật (1962 -)","hanViet":"SƠN TRUNG THÂN DI","lesson":49,"ex":[["山中伸弥さんは医学部の先生です。","Ông Yamanaka Shinya là giảng viên khoa y."],["山中伸弥さんはIPS細胞を開発しました。","Ông Yamanaka Shinya đã phát triển tế bào IPS."],["山中伸弥さんはノーベル賞を受賞しました。","Ông Yamanaka Shinya đã nhận giải Nobel."],["山中伸弥さんの講演会に行きました。","Tôi đã đi nghe buổi nói chuyện của ông Yamanaka Shinya."],["山中伸弥さんは京都大学で働いています。","Ông Yamanaka Shinya làm việc ở Đại học Kyoto."]]},{"word":"ノーベル賞","reading":"ノーベルしょう","meaning":"giải Nobel","hanViet":"THƯỞNG","lesson":49,"ex":[["山中さんはノーベル賞を受賞しました。","Ông Yamanaka đã nhận giải Nobel."],["ノーベル賞は世界的に有名です。","Giải Nobel nổi tiếng trên toàn thế giới."],["彼はノーベル賞をもらいました。","Anh ấy đã nhận giải Nobel."],["ノーベル賞の賞金は多いです。","Tiền thưởng của giải Nobel rất lớn."],["日本の作家もノーベル賞を受賞しました。","Nhà văn Nhật Bản cũng đã nhận giải Nobel."]]},{"word":"東京大学","reading":"とうきょうだいがく","meaning":"đại học Tokyo","hanViet":"ĐÔNG KINH ĐẠI HỌC","lesson":49,"ex":[["兄は東京大学で勉強しています。","Anh trai tôi đang học ở Đại học Tokyo."],["東京大学は有名な大学です。","Đại học Tokyo là một trường đại học nổi tiếng."],["私は東京大学に進みたいです。","Tôi muốn học lên Đại học Tokyo."],["東京大学の医学部で勉強しています。","Tôi đang học ở khoa y của Đại học Tokyo."],["東京大学の先生に会いました。","Tôi đã gặp một giảng viên của Đại học Tokyo."]]},{"word":"ノーベル文学賞","reading":"ノーベルぶんがくしょう","meaning":"giải Nobel văn học","hanViet":"VĂN HỌC THƯỞNG","lesson":49,"ex":[["この作家はノーベル文学賞を受賞しました。","Nhà văn này đã nhận giải Nobel Văn học."],["ノーベル文学賞は世界的に有名です。","Giải Nobel Văn học nổi tiếng trên toàn thế giới."],["日本の作家がノーベル文学賞を受賞しました。","Một nhà văn Nhật Bản đã nhận giải Nobel Văn học."],["彼はノーベル文学賞をもらいました。","Anh ấy đã nhận giải Nobel Văn học."],["ノーベル文学賞を受賞した作家の本を読みました。","Tôi đã đọc sách của nhà văn nhận giải Nobel Văn học."]]},{"word":"参ります","reading":"まいります","meaning":"đi, đến (dạng khiêm tốn của きます、いきます)","hanViet":"THAM","lesson":50,"ex":[["あした、会社に参ります。","Ngày mai tôi sẽ đến công ty."],["今から東京に参ります。","Bây giờ tôi sẽ đi Tokyo."],["7時に参ります。","Tôi sẽ đến lúc 7 giờ."],["先生のお宅に参ります。","Tôi sẽ đến nhà thầy."],["来週、京都に参ります。","Tuần sau tôi sẽ đến Kyoto."]]},{"word":"おります","reading":"おります","meaning":"có (dạng khiêm tốn của います)","hanViet":"","lesson":50,"ex":[["私は東京におります。","Tôi ở Tokyo."],["今、会社におります。","Hiện tôi đang ở công ty."],["あしたはうちにおります。","Ngày mai tôi ở nhà."],["今、会議室におります。","Hiện tôi đang ở trong phòng họp."],["来週は日本におります。","Tuần sau tôi ở Nhật."]]},{"word":"申します","reading":"もうします","meaning":"nói (dạng khiêm tốn của いいます)","hanViet":"THÂN","lesson":50,"ex":[["私は田中と申します。","Tôi tên là Tanaka."],["山田と申します。よろしくお願いします。","Tôi là Yamada. Mong anh/chị giúp đỡ."],["田中と申します。よろしくお願いします。","Tôi là Tanaka. Mong anh/chị giúp đỡ."],["山田と申します。あした参ります。","Tôi là Yamada. Ngày mai tôi sẽ đến."],["私は山田と申します。きのう電話しました。","Tôi là Yamada. Hôm qua tôi đã gọi điện."]]},{"word":"いたします","reading":"いたします","meaning":"làm (dạng khiêm tốn của します)","hanViet":"","lesson":50,"ex":[["私がいたします。","Để tôi làm."],["あした、電話いたします。","Ngày mai tôi sẽ gọi điện."],["予約をいたします。","Tôi sẽ đặt chỗ."],["私が説明いたします。","Để tôi giải thích."],["準備をいたします。","Tôi sẽ chuẩn bị."]]},{"word":"拝見します","reading":"はいけんします","meaning":"xem (dạng khiêm tốn của みます)","hanViet":"BÁI KIẾN","lesson":50,"ex":[["写真を拝見します。","Tôi xin xem ảnh."],["手紙を拝見しました。","Tôi đã xem thư."],["先生の本を拝見しました。","Tôi đã xem sách của thầy."],["あした、資料を拝見します。","Ngày mai tôi sẽ xem tài liệu."],["アルバムを拝見してもいいですか。","Tôi xem album được không ạ?"]]},{"word":"存じます","reading":"ぞんじます","meaning":"biết (dạng khiêm tốn của しります)","hanViet":"TỒN","lesson":50,"ex":[["存じません。","Tôi không biết."],["その話は存じません。","Tôi không biết chuyện đó."],["田中さんの住所は存じません。","Tôi không biết địa chỉ của anh Tanaka."],["よく存じています。","Tôi biết rõ."],["あの人の名前は存じません。","Tôi không biết tên của người kia."]]},{"word":"お目にかかります","reading":"おめにかかります","meaning":"gặp (dạng khiêm tốn của あいます)","hanViet":"MỤC","lesson":50,"ex":[["先生にお目にかかれて、うれしいです。","Được gặp thầy, tôi rất vui."],["あした、田中さんにお目にかかります。","Ngày mai tôi sẽ gặp anh Tanaka."],["社長にお目にかかりたいです。","Tôi muốn gặp giám đốc."],["またお目にかかれて、うれしいです。","Được gặp lại anh/chị, tôi rất vui."],["来週、先生にお目にかかります。","Tuần sau tôi sẽ gặp thầy."]]},{"word":"ございます","reading":"ございます","meaning":"có (dạng lịch sự của あります)","hanViet":"","lesson":50,"ex":[["こちらにございます。","Ở đây ạ."],["時間はまだございます。","Vẫn còn thời gian ạ."],["お手洗いはあちらにございます。","Nhà vệ sinh ở đằng kia ạ."],["この本はまだございますか。","Quyển sách này còn không ạ?"],["質問はございますか。","Anh/chị có câu hỏi nào không ạ?"]]},{"word":"～でございます","reading":"～でございます","meaning":"là (dạng lịch sự của ~です)","hanViet":"","lesson":50,"ex":[["私は田中でございます。","Tôi là Tanaka ạ."],["こちらは山田でございます。","Đây là Yamada ạ."],["これは日本の本でございます。","Đây là sách của Nhật ạ."],["あしたは休みでございます。","Ngày mai là ngày nghỉ ạ."],["私は学生でございます。","Tôi là học sinh ạ."]]},{"word":"私","reading":"わたくし","meaning":"tôi (dạng khiêm tốn của わたし)","hanViet":"TƯ","lesson":50,"ex":[["私は山田と申します。","Tôi tên là Yamada."],["私は会社員でございます。","Tôi là nhân viên công ty ạ."],["私の名前は田中です。","Tên tôi là Tanaka."],["私はあした参ります。","Ngày mai tôi sẽ đến."],["私は東京に住んでいます。","Tôi sống ở Tokyo."]]},{"word":"お宅","reading":"おたく","meaning":"nhà (của người khác)","hanViet":"TRẠCH","lesson":50,"ex":[["田中さんのお宅はどこですか。","Nhà anh Tanaka ở đâu ạ?"],["あした、先生のお宅に参ります。","Ngày mai tôi sẽ đến nhà thầy."],["お宅は東京ですか。","Nhà anh/chị ở Tokyo phải không ạ?"],["山田さんのお宅は大きいです。","Nhà anh Yamada rất lớn."],["お宅の近くに駅があります。","Gần nhà anh/chị có ga tàu."]]},{"word":"郊外","reading":"こうがい","meaning":"Ngoại ô","hanViet":"GIAO NGOẠI","lesson":50,"ex":[["私の家は郊外にあります。","Nhà tôi ở ngoại ô."],["郊外は静かです。","Ngoại ô rất yên tĩnh."],["郊外に新しい家を買いました。","Tôi đã mua một ngôi nhà mới ở ngoại ô."],["先生のお宅は郊外にあります。","Nhà thầy ở ngoại ô."],["郊外の空気はきれいです。","Không khí ở ngoại ô rất trong lành."]]},{"word":"さ来週","reading":"さらいしゅう","meaning":"tuần tới nữa","hanViet":"LAI CHU","lesson":50,"ex":[["さ来週、東京に行きます。","Tuần tới nữa tôi sẽ đi Tokyo."],["さ来週は試験があります。","Tuần tới nữa có kỳ thi."],["さ来週、田中さんに会います。","Tuần tới nữa tôi sẽ gặp anh Tanaka."],["さ来週の月曜日は休みです。","Thứ Hai tuần tới nữa là ngày nghỉ."],["さ来週から新しい仕事が始まります。","Công việc mới sẽ bắt đầu từ tuần tới nữa."]]},{"word":"さ来月","reading":"さらいげつ","meaning":"tháng tới nữa","hanViet":"LAI NGUYỆT","lesson":50,"ex":[["さ来月、日本に行きます。","Tháng tới nữa tôi sẽ đi Nhật."],["さ来月は誕生日です。","Tháng tới nữa là sinh nhật tôi."],["さ来月に結婚します。","Tháng tới nữa tôi sẽ kết hôn."],["さ来月、京都に旅行に行きます。","Tháng tới nữa tôi sẽ đi du lịch Kyoto."],["さ来月から大学で勉強します。","Từ tháng tới nữa tôi sẽ học ở trường đại học."]]},{"word":"さ来年","reading":"さらいねん","meaning":"năm tới nữa","hanViet":"LAI NIÊN","lesson":50,"ex":[["さ来年、大学を卒業します。","Năm tới nữa tôi sẽ tốt nghiệp đại học."],["さ来年、日本に来ます。","Năm tới nữa tôi sẽ đến Nhật."],["さ来年はオリンピックがあります。","Năm tới nữa có Olympic."],["さ来年、結婚します。","Năm tới nữa tôi sẽ kết hôn."],["さ来年から東京で働きます。","Từ năm tới nữa tôi sẽ làm việc ở Tokyo."]]},{"word":"半年","reading":"はんとし","meaning":"Nửa năm","hanViet":"BÁN NIÊN","lesson":50,"ex":[["日本に来て、半年です。","Tôi đến Nhật đã được nửa năm."],["半年日本語を勉強しています。","Tôi đã học tiếng Nhật được nửa năm."],["半年後に日本に行きます。","Nửa năm nữa tôi sẽ đi Nhật."],["この仕事は半年で終わります。","Công việc này sẽ xong trong nửa năm."],["半年前、東京に来ました。","Nửa năm trước, tôi đã đến Tokyo."]]},{"word":"最初に","reading":"さいしょに","meaning":"trước hết","hanViet":"TỐI SƠ","lesson":50,"ex":[["最初に、名前を教えてください。","Trước hết, xin hãy cho tôi biết tên."],["最初に、この本を読んでください。","Trước hết, xin hãy đọc quyển sách này."],["最初に、写真を見てください。","Trước hết, xin hãy xem ảnh."],["最初に、先生の話を聞きました。","Trước hết, tôi đã nghe thầy nói chuyện."],["最初に、歌を歌います。","Trước hết, tôi sẽ hát một bài hát."]]},{"word":"最後に","reading":"さいごに","meaning":"cuối cùng","hanViet":"TỐI HẬU","lesson":50,"ex":[["最後に、質問があります。","Cuối cùng, tôi có một câu hỏi."],["最後に、皆さんにありがとうと言いたいです。","Cuối cùng, tôi muốn nói cảm ơn mọi người."],["最後に、この歌を歌います。","Cuối cùng, tôi sẽ hát bài hát này."],["最後に、先生の話を聞きました。","Cuối cùng, tôi đã nghe thầy nói chuyện."],["最後に、写真を撮りました。","Cuối cùng, tôi đã chụp ảnh."]]},{"word":"ただ今","reading":"ただいま","meaning":"tôi đã về!","hanViet":"KIM","lesson":50,"ex":[["子どもは「ただ今」と言って、家に帰りました。","Đứa trẻ nói \"Con đã về!\" rồi về nhà."],["ただ今、会社から帰りました。","Tôi vừa từ công ty về."],["ただ今、学校から帰りました。","Tôi vừa từ trường về."],["ただ今、東京から帰りました。","Tôi vừa từ Tokyo về."],["ただ今、帰りました。","Tôi đã về."]]},{"word":"緊張します","reading":"きんちょうします","meaning":"căng thẳng","hanViet":"KHẨN TRƯƠNG","lesson":50,"ex":[["試験の前に緊張します。","Trước kỳ thi, tôi căng thẳng."],["初めての発表で緊張しました。","Tôi đã căng thẳng trong buổi thuyết trình đầu tiên."],["先生の前で緊張します。","Trước mặt thầy, tôi căng thẳng."],["初めて会う人の前で緊張します。","Trước mặt người mới gặp lần đầu, tôi căng thẳng."],["緊張して、声が小さくなりました。","Vì căng thẳng, giọng tôi nhỏ đi."]]},{"word":"放送します","reading":"ほうそうします","meaning":"phát thanh, phát hình","hanViet":"PHÓNG TỐNG","lesson":50,"ex":[["テレビでニュースを放送します。","Đài truyền hình phát tin tức."],["あした、この番組を放送します。","Ngày mai đài sẽ phát chương trình này."],["ラジオで歌を放送しました。","Đài phát thanh đã phát bài hát."],["この試合をテレビで放送します。","Đài truyền hình sẽ phát trận đấu này."],["夜9時にニュースを放送します。","Đài phát tin tức lúc 9 giờ tối."]]},{"word":"撮ります","reading":"とります","meaning":"thâu (băng hình)","hanViet":"TOÁT","lesson":50,"ex":[["写真を撮ります。","Tôi chụp ảnh."],["ビデオで子どもの誕生日を撮りました。","Tôi đã quay lại sinh nhật của con bằng máy quay."],["旅行でたくさん写真を撮りました。","Tôi đã chụp rất nhiều ảnh trong chuyến du lịch."],["友達の結婚式を撮りました。","Tôi đã quay đám cưới của bạn."],["動物園で象の写真を撮りました。","Tôi đã chụp ảnh voi ở sở thú."]]},{"word":"賞金","reading":"しょうきん","meaning":"Tiền thưởng","hanViet":"THƯỞNG KIM","lesson":50,"ex":[["賞金は100万円です。","Tiền thưởng là 1 triệu yên."],["賞金をもらいました。","Tôi đã nhận tiền thưởng."],["この試合の賞金は多いです。","Tiền thưởng của trận đấu này rất lớn."],["賞金で新しい車を買いました。","Tôi đã mua xe mới bằng tiền thưởng."],["賞金を家族にあげました。","Tôi đã tặng tiền thưởng cho gia đình."]]},{"word":"麒麟","reading":"きりん","meaning":"hươu cao cổ","hanViet":"","lesson":50,"ex":[["動物園で麒麟を見ました。","Tôi đã nhìn thấy hươu cao cổ ở sở thú."],["麒麟はとても大きい動物です。","Hươu cao cổ là một loài động vật rất lớn."],["麒麟は葉を食べます。","Hươu cao cổ ăn lá cây."],["子どもは麒麟が好きです。","Trẻ em thích hươu cao cổ."],["麒麟は動物園で人気があります。","Hươu cao cổ được yêu thích ở sở thú."]]},{"word":"象","reading":"ぞう","meaning":"con voi","hanViet":"TƯỢNG","lesson":50,"ex":[["象は大きい動物です。","Voi là một loài động vật lớn."],["動物園で象を見ました。","Tôi đã nhìn thấy voi ở sở thú."],["象は耳が大きいです。","Voi có tai lớn."],["象は水が好きです。","Voi thích nước."],["子どもは象に乗りました。","Đứa trẻ đã cưỡi voi."]]},{"word":"ころ","reading":"ころ","meaning":"lúc, thời","hanViet":"","lesson":50,"ex":[["子どものころ、よく動物園に行きました。","Hồi còn nhỏ, tôi thường đi sở thú."],["小さいころ、ピアノを習いました。","Hồi còn nhỏ, tôi đã học piano."],["学生のころ、毎日テニスをしました。","Hồi còn là học sinh, tôi chơi tennis mỗi ngày."],["子どものころの夢は医者でした。","Ước mơ hồi nhỏ của tôi là trở thành bác sĩ."],["若いころ、よく旅行に行きました。","Hồi còn trẻ, tôi thường đi du lịch."]]},{"word":"叶います","reading":"かないます","meaning":"(giấc mơ) thành hiện thực, linh ứng","hanViet":"","lesson":50,"ex":[["夢が叶いました。","Giấc mơ đã thành hiện thực."],["私の夢が叶いますように。","Mong ước mơ của tôi thành hiện thực."],["毎日頑張れば、夢が叶います。","Nếu cố gắng mỗi ngày, giấc mơ sẽ thành hiện thực."],["子どものころの夢が叶いました。","Ước mơ hồi nhỏ của tôi đã thành hiện thực."],["皆さんの夢が叶いますように。","Mong ước mơ của mọi người thành hiện thực."]]},{"word":"ひとことよろしいでしょうか","reading":"ひとことよろしいでしょうか","meaning":"cho tôi nói một lời","hanViet":"","lesson":50,"ex":[["ひとことよろしいでしょうか。私は田中と申します。","Cho tôi nói một lời. Tôi là Tanaka."],["ひとことよろしいでしょうか。皆さん、聞いてください。","Cho tôi nói một lời. Mọi người, xin hãy nghe."],["パーティーで「ひとことよろしいでしょうか」と言いました。","Ở buổi tiệc, tôi đã nói \"Cho tôi nói một lời\"."],["ひとことよろしいでしょうか。先生に感謝します。","Cho tôi nói một lời. Tôi biết ơn thầy."],["会議の最後に「ひとことよろしいでしょうか」と言いました。","Cuối cuộc họp, tôi đã nói \"Cho tôi nói một lời\"."]]},{"word":"協力します","reading":"きょうりょくします","meaning":"hiệp lực, cộng tác","hanViet":"HIỆP LỰC","lesson":50,"ex":[["皆さん、協力してください。","Mọi người, xin hãy hợp tác."],["仕事で協力します。","Tôi hợp tác trong công việc."],["友達と協力して、仕事をしました。","Tôi đã hợp tác với bạn để làm việc."],["皆さんの協力が必要です。","Cần sự hợp tác của mọi người."],["家族の協力で、大学を卒業しました。","Nhờ sự giúp đỡ của gia đình, tôi đã tốt nghiệp đại học."]]},{"word":"心から","reading":"こころから","meaning":"từ đáy lòng, thật lòng","hanViet":"TÂM","lesson":50,"ex":[["心から感謝します。","Tôi chân thành cảm ơn."],["心からありがとうと言いたいです。","Tôi muốn nói cảm ơn từ đáy lòng."],["心からうれしいです。","Tôi vui từ đáy lòng."],["心から謝ります。","Tôi chân thành xin lỗi."],["心からおめでとうございます。","Tôi xin chúc mừng từ đáy lòng."]]},{"word":"感謝します","reading":"かんしゃします","meaning":"cảm tạ, biết ơn","hanViet":"CẢM TẠ","lesson":50,"ex":[["先生に感謝します。","Tôi biết ơn thầy."],["皆さんに感謝します。","Tôi biết ơn mọi người."],["家族に感謝しています。","Tôi biết ơn gia đình."],["手伝ってくれた友達に感謝します。","Tôi biết ơn người bạn đã giúp đỡ tôi."],["皆さんの協力に感謝します。","Tôi biết ơn sự hợp tác của mọi người."]]},{"word":"拝啓","reading":"はいけい","meaning":"Kính gửi (mở đầu thư)","hanViet":"BÁI KHẢI","lesson":50,"ex":[["拝啓、田中様。お元気ですか。","Kính gửi anh Tanaka. Anh có khỏe không?"],["拝啓、山田様。日本は寒くなりました。","Kính gửi anh Yamada. Ở Nhật đã trở lạnh."],["拝啓、先生。お元気でいらっしゃいますか。","Kính gửi thầy. Thầy có khỏe không ạ?"],["拝啓、田中様。ご家族はお元気ですか。","Kính gửi anh Tanaka. Gia đình anh có khỏe không?"],["拝啓、山田様。春になりました。","Kính gửi anh Yamada. Mùa xuân đã đến."]]},{"word":"迷惑掛けます","reading":"まいわくかけます","meaning":"làm phiền","hanViet":"MÊ HOẶC QUÁI","lesson":50,"ex":[["遅くなって、迷惑掛けました。","Vì đến muộn, tôi đã làm phiền anh/chị."],["皆さんに迷惑掛けて、すみません。","Tôi đã làm phiền mọi người, xin lỗi."],["子どもが迷惑掛けました。","Đứa trẻ đã làm phiền."],["あした休んで、迷惑掛けます。","Ngày mai tôi nghỉ nên sẽ làm phiền mọi người."],["皆さんに迷惑掛けないように、気をつけます。","Tôi sẽ cẩn thận để không làm phiền mọi người."]]},{"word":"生かします","reading":"いかします","meaning":"vận dụng, ứng dụng","hanViet":"SINH","lesson":50,"ex":[["日本語を仕事に生かします。","Tôi vận dụng tiếng Nhật vào công việc."],["大学で習った日本語を仕事に生かします。","Tôi vận dụng tiếng Nhật đã học ở đại học vào công việc."],["経験を生かして、働きます。","Tôi làm việc bằng cách vận dụng kinh nghiệm."],["英語を仕事に生かします。","Tôi vận dụng tiếng Anh vào công việc."],["ピアノの経験を生かして、先生になりました。","Tôi đã vận dụng kinh nghiệm piano để trở thành giáo viên."]]},{"word":"敬具","reading":"けいぐ","meaning":"kính thư (viết cuối thư)","hanViet":"KÍNH CỤ","lesson":50,"ex":[["手紙の最後に「敬具」と書きます。","Cuối thư, tôi viết \"Kính thư\"."],["手紙の終わりに「敬具」と書きました。","Cuối thư, tôi đã viết \"Kính thư\"."],["手紙は「拝啓」で始まって、「敬具」で終わります。","Bức thư bắt đầu bằng \"Kính gửi\" và kết thúc bằng \"Kính thư\"."],["「敬具」と書いて、手紙を終わりました。","Tôi đã viết \"Kính thư\" rồi kết thúc bức thư."],["先生への手紙に「敬具」と書きました。","Tôi đã viết \"Kính thư\" trong thư gửi thầy."]]},{"word":"淹れます","reading":"いれます","meaning":"pha [cà phê]","hanViet":"","lesson":50,"ex":[["コーヒーを淹れます。","Tôi pha cà phê."],["お客様にコーヒーを淹れました。","Tôi đã pha cà phê cho khách."],["毎朝、コーヒーを淹れます。","Mỗi sáng tôi pha cà phê."],["おいしいコーヒーを淹れてください。","Xin hãy pha cà phê ngon nhé."],["先生のために、コーヒーを淹れました。","Tôi đã pha cà phê cho thầy."]]},{"word":"スケジュール","reading":"スケジュール","meaning":"thời khóa biểu, lịch làm việc","hanViet":"","lesson":50,"ex":[["あしたのスケジュールは忙しいです。","Lịch làm việc ngày mai rất bận."],["スケジュールを教えてください。","Xin hãy cho tôi biết lịch làm việc."],["スケジュールが変わりました。","Lịch làm việc đã thay đổi."],["来週のスケジュールを決めます。","Tôi sẽ quyết định lịch làm việc tuần sau."],["スケジュールを見てください。","Xin hãy xem lịch làm việc."]]},{"word":"ガイド","reading":"ガイド","meaning":"hướng dẫn viên","hanViet":"","lesson":50,"ex":[["ガイドは東京を案内します。","Hướng dẫn viên sẽ dẫn đi tham quan Tokyo."],["ガイドと京都に行きました。","Tôi đã đi Kyoto cùng hướng dẫn viên."],["英語のガイドを読みました。","Tôi đã đọc sách hướng dẫn bằng tiếng Anh."],["ガイドの話はおもしろいです。","Câu chuyện của hướng dẫn viên rất thú vị."],["ガイドに道を聞きました。","Tôi đã hỏi đường hướng dẫn viên."]]},{"word":"アルバム","reading":"アルバム","meaning":"tập ảnh, Album","hanViet":"","lesson":50,"ex":[["アルバムに写真がたくさんあります。","Trong album có rất nhiều ảnh."],["子どものころのアルバムを見ました。","Tôi đã xem album hồi nhỏ."],["アルバムを先生に見せました。","Tôi đã cho thầy xem album."],["このアルバムは家族の写真です。","Album này là ảnh của gia đình."],["アルバムを作りました。","Tôi đã làm một album."]]},{"word":"応援します","reading":"おうえんします","meaning":"cổ vũ, ủng hộ","hanViet":"ỨNG VIÊN","lesson":50,"ex":[["日本のチームを応援します。","Tôi cổ vũ cho đội Nhật Bản."],["友達を応援しています。","Tôi đang cổ vũ cho bạn."],["試合で弟を応援しました。","Tôi đã cổ vũ cho em trai trong trận đấu."],["皆さんで友達を応援します。","Mọi người cùng cổ vũ cho bạn."],["サッカーの試合を応援に行きます。","Tôi đi cổ vũ trận đấu bóng đá."]]},{"word":"メールアドレス","reading":"メールアドレス","meaning":"địa chỉ email","hanViet":"","lesson":50,"ex":[["メールアドレスを教えてください。","Xin hãy cho tôi biết địa chỉ email."],["メールアドレスを書いてください。","Xin hãy viết địa chỉ email."],["先生のメールアドレスを知りません。","Tôi không biết địa chỉ email của thầy."],["メールアドレスが変わりました。","Địa chỉ email đã thay đổi."],["メールアドレスに間違いがあります。","Địa chỉ email có lỗi."]]},{"word":"江戸東京博物館","reading":"えどとうきょうはくぶつかん","meaning":"bảo tàng Edo-Tokyo","hanViet":"GIANG HỘ ĐÔNG KINH BÁC VẬT QUÁN","lesson":50,"ex":[["江戸東京博物館に行きました。","Tôi đã đi Bảo tàng Edo-Tokyo."],["江戸東京博物館は東京にあります。","Bảo tàng Edo-Tokyo ở Tokyo."],["江戸東京博物館で古い東京の生活を見ました。","Tôi đã xem đời sống Tokyo xưa ở Bảo tàng Edo-Tokyo."],["江戸東京博物館は大きいです。","Bảo tàng Edo-Tokyo rất lớn."],["江戸東京博物館で写真を撮りました。","Tôi đã chụp ảnh ở Bảo tàng Edo-Tokyo."]]},{"word":"お礼","reading":"おれい","meaning":"lời cám ơn, sự cám ơn","hanViet":"LỄ","lesson":50,"ex":[["お礼を言います。","Tôi nói lời cảm ơn."],["先生にお礼を言いました。","Tôi đã nói lời cảm ơn với thầy."],["お礼の手紙を書きました。","Tôi đã viết thư cảm ơn."],["お礼にケーキをあげました。","Tôi đã tặng bánh để cảm ơn."],["お礼が言いたいです。","Tôi muốn nói lời cảm ơn."]]},{"word":"お元気でいらっしゃいますか","reading":"おげんきでいらっしゃいますか","meaning":"Anh/chị có khỏe không ạ?","hanViet":"NGUYÊN KHÍ","lesson":50,"ex":[["先生、お元気でいらっしゃいますか。","Thầy có khỏe không ạ?"],["田中さんはお元気でいらっしゃいますか。","Anh Tanaka có khỏe không ạ?"],["奥様はお元気でいらっしゃいますか。","Phu nhân có khỏe không ạ?"],["社長はお元気でいらっしゃいますか。","Giám đốc có khỏe không ạ?"],["お母さんはお元気でいらっしゃいますか。","Mẹ anh/chị có khỏe không ạ?"]]},{"word":"ミュンヘン","reading":"ミュンヘン","meaning":"München (Munich) (ở Đức)","hanViet":"","lesson":50,"ex":[["ミュンヘンはドイツの町です。","Munich là một thành phố ở Đức."],["ミュンヘンに旅行に行きました。","Tôi đã đi du lịch Munich."],["ミュンヘンはビールが有名です。","Munich nổi tiếng với bia."],["友達はミュンヘンに住んでいます。","Bạn tôi sống ở Munich."],["ミュンヘンから東京まで飛行機で12時間です。","Từ Munich đến Tokyo mất 12 giờ bay."]]}],"N3":[{"word":"どのように","reading":"どのように","meaning":"Như thế nào","hanViet":"","lesson":1,"ex":[["どのように日本語を勉強していますか。","Bạn học tiếng Nhật như thế nào?"],["この漢字はどのように読みますか。","Chữ Hán này đọc như thế nào?"],["どのようにして日本へ来ましたか。","Bạn đã đến Nhật Bản như thế nào?"],["先生にどのように話したらいいですか。","Nên nói với thầy như thế nào thì tốt?"],["この映画について、どのように思いますか。","Bạn nghĩ như thế nào về bộ phim này?"]]},{"word":"迷う","reading":"まよう","meaning":"Lạc đường; phân vân, do dự","hanViet":"MÊ","lesson":1,"ex":[["東京で道に迷いました。","Tôi đã bị lạc đường ở Tokyo."],["どちらを選ぶか、迷っています。","Tôi đang phân vân không biết nên chọn cái nào."],["山で迷わないように、地図を持って行きましょう。","Để không bị lạc trên núi, hãy mang theo bản đồ."],["初めての町で迷うことがあります。","Có khi tôi bị lạc ở thành phố lần đầu đến."],["友達と会う約束をしたのに、道に迷って遅れました。","Dù đã hẹn gặp bạn, tôi bị lạc đường nên đã đến muộn."]]},{"word":"先輩","reading":"せんぱい","meaning":"Tiền bối, người đi trước","hanViet":"TIÊN BỐI","lesson":1,"ex":[["先輩に日本語を教えてもらいました。","Tôi đã được anh khóa trên dạy tiếng Nhật."],["大学の先輩はとても親切です。","Anh khóa trên ở đại học rất tốt bụng."],["先輩といっしょに昼ごはんを食べました。","Tôi đã ăn trưa cùng anh khóa trên."],["仕事のことで先輩に相談しました。","Tôi đã hỏi ý kiến anh đi trước về công việc."],["先輩と話すと、とても勉強になります。","Nói chuyện với anh khóa trên, tôi học hỏi được rất nhiều."]]},{"word":"まるで","reading":"まるで","meaning":"Hệt như","hanViet":"","lesson":1,"ex":[["この部屋はまるでホテルのようです。","Căn phòng này hệt như khách sạn vậy."],["まるで夢のようです。","Hệt như một giấc mơ vậy."],["彼はまるで日本人のように日本語を話します。","Anh ấy nói tiếng Nhật hệt như người Nhật."],["まるで夏のように暑いです。","Nóng hệt như mùa hè vậy."],["その映画はまるで本当の話のようです。","Bộ phim đó hệt như câu chuyện có thật vậy."]]},{"word":"明るい","reading":"あかるい","meaning":"Sáng sủa; vui vẻ, tươi sáng","hanViet":"MINH","lesson":1,"ex":[["彼女は明るい人です。","Cô ấy là người vui vẻ."],["この部屋は明るいです。","Căn phòng này sáng sủa."],["明るい声で話してください。","Hãy nói bằng giọng vui vẻ."],["窓が大きくて、部屋が明るくなりました。","Cửa sổ lớn nên phòng trở nên sáng hơn."],["明るい色の服が好きです。","Tôi thích quần áo màu sáng."]]},{"word":"父親","reading":"ちちおや","meaning":"Bố","hanViet":"PHỤ THÂN","lesson":1,"ex":[["父親は会社で働いています。","Bố tôi đang làm việc ở công ty."],["父親の誕生日は来月です。","Sinh nhật của bố là tháng sau."],["父親といっしょに旅行に行きました。","Tôi đã đi du lịch cùng bố."],["父親は毎日早く起きます。","Bố tôi dậy sớm mỗi ngày."],["父親に電話をしました。","Tôi đã gọi điện cho bố."]]},{"word":"湖","reading":"みずうみ","meaning":"Hồ","hanViet":"HỒ","lesson":1,"ex":[["この湖はとても大きいです。","Hồ này rất lớn."],["湖の近くにホテルがあります。","Gần hồ có một khách sạn."],["休みに湖へ行って、写真を撮りました。","Ngày nghỉ tôi đã đến hồ và chụp ảnh."],["湖の水はきれいです。","Nước hồ trong sạch."],["湖のそばで昼ごはんを食べました。","Tôi đã ăn trưa bên hồ."]]},{"word":"目指す","reading":"めざす","meaning":"Hướng đến","hanViet":"MỤC CHỈ","lesson":1,"ex":[["日本の大学を目指しています。","Tôi đang hướng tới đại học Nhật Bản."],["医者を目指す学生が多いです。","Có nhiều sinh viên hướng tới nghề bác sĩ."],["試験で一番を目指して勉強しています。","Tôi đang học để hướng tới vị trí đứng đầu trong kỳ thi."],["彼は先生になることを目指しています。","Anh ấy đang hướng tới việc trở thành giáo viên."],["夢を目指して、毎日頑張ります。","Hướng tới ước mơ, tôi cố gắng mỗi ngày."]]},{"word":"命","reading":"いのち","meaning":"Sinh mạng, mạng sống","hanViet":"MỆNH","lesson":1,"ex":[["命はとても大切です。","Mạng sống rất quý giá."],["命を守ることが一番大切です。","Bảo vệ mạng sống là quan trọng nhất."],["医者は人々の命を助けます。","Bác sĩ cứu mạng sống của mọi người."],["その犬は命が危ないです。","Con chó đó đang nguy hiểm đến tính mạng."],["命の大切さを子どもたちに教えたいです。","Tôi muốn dạy cho trẻ em về sự quý giá của mạng sống."]]},{"word":"おせち料理","reading":"おせちりょうり","meaning":"Món ăn truyền thống của người Nhật vào năm mới","hanViet":"LIÊU LÍ","lesson":1,"ex":[["お正月におせち料理を食べます。","Vào dịp Tết, tôi ăn món osechi."],["母は毎年おせち料理を作ります。","Mẹ tôi làm món osechi mỗi năm."],["おせち料理は日本の伝統的な料理です。","Osechi là món ăn truyền thống của Nhật Bản."],["おせち料理を初めて食べました。","Tôi đã ăn osechi lần đầu tiên."],["おせち料理にはいろいろな意味があります。","Món osechi có nhiều ý nghĩa khác nhau."]]},{"word":"初詣で","reading":"はつもうで","meaning":"Tục lệ thăm viếng đền hoặc chùa đầu năm mới","hanViet":"SƠ NGHỆ","lesson":1,"ex":[["お正月に神社へ初詣でに行きます。","Vào dịp Tết, tôi đi lễ đầu năm ở đền thần."],["初詣ででは、お金を入れて、お願いをします。","Khi đi lễ đầu năm, tôi bỏ tiền vào hòm công đức và cầu nguyện."],["家族といっしょに初詣でに行きました。","Tôi đã đi lễ đầu năm cùng gia đình."],["初詣でに行く人が多いです。","Có nhiều người đi lễ đầu năm."],["今年も初詣でに行きたいです。","Năm nay tôi cũng muốn đi lễ đầu năm."]]},{"word":"畳","reading":"たたみ","meaning":"Chiếu Tatami","hanViet":"ĐIỆP","lesson":1,"ex":[["この部屋の床は畳です。","Sàn của phòng này là chiếu tatami."],["畳の部屋で寝るのが好きです。","Tôi thích ngủ trong phòng tatami."],["畳の上に座布団を置きました。","Tôi đã đặt đệm ngồi lên chiếu tatami."],["畳は夏は涼しくて、冬は暖かいです。","Tatami mát vào mùa hè và ấm vào mùa đông."],["新しい畳はいいにおいがします。","Chiếu tatami mới có mùi thơm."]]},{"word":"座布団","reading":"ざぶとん","meaning":"Miếng lót sàn hình vuông dùng để ngồi hoặc quỳ lên","hanViet":"TỌA BỐ ĐOÀN","lesson":1,"ex":[["座布団の上に座ってください。","Hãy ngồi lên đệm ngồi."],["友達のために座布団を出しました。","Tôi đã lấy đệm ngồi ra cho bạn."],["座布団が古くなりました。","Đệm ngồi đã cũ."],["畳の部屋には座布団があります。","Trong phòng tatami có đệm ngồi."],["座布団を重ねてしまいました。","Tôi đã chồng đệm ngồi lên nhau và cất đi."]]},{"word":"床","reading":"ゆか","meaning":"Sàn nhà","hanViet":"SÀNG","lesson":1,"ex":[["床がきれいです。","Sàn nhà sạch sẽ."],["床に本を落としました。","Tôi đã đánh rơi sách xuống sàn."],["子どもが床で遊んでいます。","Đứa trẻ đang chơi trên sàn nhà."],["床を掃除してください。","Hãy lau sàn nhà."],["床に座って話しました。","Tôi đã ngồi trên sàn và nói chuyện."]]},{"word":"正座","reading":"せいざ","meaning":"Kiểu ngồi truyền thống của người Nhật","hanViet":"CHÁNH TỌA","lesson":1,"ex":[["畳の部屋では正座をします。","Trong phòng tatami, tôi ngồi seiza."],["正座をすると、足が痛くなります。","Ngồi seiza thì chân bị đau."],["正座は日本の伝統的な座り方です。","Seiza là cách ngồi truyền thống của Nhật Bản."],["長く正座をするのは難しいです。","Ngồi seiza lâu rất khó."],["お茶の時間に正座をしました。","Tôi đã ngồi seiza trong lúc uống trà."]]},{"word":"おじぎ","reading":"おじぎ","meaning":"Cúi đầu","hanViet":"","lesson":1,"ex":[["日本では会うときにおじぎをします。","Ở Nhật Bản, khi gặp nhau người ta cúi đầu chào."],["先生におじぎをしました。","Tôi đã cúi đầu chào thầy."],["深くおじぎをしてください。","Hãy cúi đầu thật sâu."],["おじぎは日本の大切なあいさつです。","Cúi đầu là cách chào hỏi quan trọng của Nhật Bản."],["別れるときにおじぎをしました。","Khi chia tay, tôi đã cúi đầu chào."]]},{"word":"作家","reading":"さっか","meaning":"Tác giả, nhà văn","hanViet":"TÁC GIA","lesson":1,"ex":[["私は日本の作家の本が好きです。","Tôi thích sách của nhà văn Nhật Bản."],["有名な作家に会いました。","Tôi đã gặp một nhà văn nổi tiếng."],["作家になるのが夢です。","Trở thành nhà văn là ước mơ của tôi."],["その作家は毎年新しい本を書きます。","Nhà văn đó mỗi năm viết một cuốn sách mới."],["作家の本をたくさん読みました。","Tôi đã đọc nhiều sách của nhà văn."]]},{"word":"～中","reading":"～ちゅう","meaning":"Trong khi","hanViet":"TRUNG","lesson":1,"ex":[["授業中に質問をしました。","Tôi đã đặt câu hỏi trong giờ học."],["仕事中に電話がありました。","Trong giờ làm việc, có điện thoại gọi đến."],["食事中に話すのはよくありません。","Nói chuyện trong bữa ăn là không tốt."],["勉強中に音楽を聞きます。","Tôi nghe nhạc trong lúc học."],["会議中は電話を使いません。","Trong cuộc họp, tôi không dùng điện thoại."]]},{"word":"いっぱい","reading":"いっぱい","meaning":"Đầy, đông","hanViet":"","lesson":1,"ex":[["電車の中はいっぱいです。","Trong tàu điện rất đông."],["ごはんをいっぱい食べました。","Tôi đã ăn rất nhiều cơm."],["このかばんには本がいっぱい入っています。","Trong cặp này có đầy sách."],["冷蔵庫に食べ物がいっぱいあります。","Trong tủ lạnh có đầy thức ăn."],["いっぱい練習して、試験に合格しました。","Tôi đã luyện tập rất nhiều và đỗ kỳ thi."]]},{"word":"どんなに","reading":"どんなに","meaning":"Như thế nào đi nữa","hanViet":"","lesson":1,"ex":[["どんなに忙しくても、毎日日本語を勉強します。","Dù bận thế nào, tôi vẫn học tiếng Nhật mỗi ngày."],["どんなに難しくても、あきらめません。","Dù khó thế nào, tôi cũng không bỏ cuộc."],["どんなに食べても、おなかがいっぱいになりません。","Dù ăn bao nhiêu, bụng vẫn không no."],["どんなに遠くても、会いに行きたいです。","Dù xa thế nào, tôi vẫn muốn đến gặp."],["どんなに疲れても、最後まで頑張ります。","Dù mệt thế nào, tôi vẫn cố gắng đến cuối cùng."]]},{"word":"立派","reading":"りっぱ","meaning":"Tuyệt vời, hoành tráng","hanViet":"LẬP PHÁI","lesson":1,"ex":[["立派な家に住んでいます。","Tôi sống trong một ngôi nhà hoành tráng."],["立派な先生になりたいです。","Tôi muốn trở thành một thầy giáo tuyệt vời."],["立派な建物ですね。","Tòa nhà thật hoành tráng nhỉ."],["彼は立派な大人になりました。","Anh ấy đã trở thành một người trưởng thành đáng nể."],["立派な仕事をしましたね。","Bạn đã làm một công việc tuyệt vời nhỉ."]]},{"word":"欠点","reading":"けってん","meaning":"Khiếm khuyết, khuyết điểm","hanViet":"KHIẾM ĐIỂM","lesson":1,"ex":[["だれにでも欠点があります。","Ai cũng có khuyết điểm."],["私の欠点は、よく怒ることです。","Khuyết điểm của tôi là hay nổi giận."],["欠点を知って、直したいです。","Tôi muốn biết khuyết điểm của mình và sửa chữa."],["彼の欠点は、約束の時間を守らないことです。","Khuyết điểm của anh ấy là không giữ đúng giờ hẹn."],["欠点を直すのは難しいですが、頑張ります。","Sửa khuyết điểm rất khó nhưng tôi sẽ cố gắng."]]},{"word":"～過ぎ","reading":"～すぎ","meaning":"Quá ～","hanViet":"QUÁ","lesson":1,"ex":[["食べ過ぎは体によくありません。","Ăn quá nhiều không tốt cho sức khỏe."],["飲み過ぎて、頭が痛いです。","Tôi uống quá nhiều nên đau đầu."],["働き過ぎないように気をつけてください。","Hãy cẩn thận để không làm việc quá sức."],["寝過ぎて、学校に遅れました。","Tôi ngủ quá nhiều nên đến trường muộn."],["テレビの見過ぎは目によくありません。","Xem tivi quá nhiều không tốt cho mắt."]]},{"word":"似合う","reading":"にあう","meaning":"Hợp","hanViet":"TỰ HỢP","lesson":1,"ex":[["その服はあなたによく似合います。","Bộ quần áo đó rất hợp với bạn."],["この帽子は私に似合いますか。","Chiếc mũ này có hợp với tôi không?"],["赤い色が彼女によく似合います。","Màu đỏ rất hợp với cô ấy."],["その眼鏡はとても似合っています。","Chiếc kính đó rất hợp với bạn."],["似合う服を探しています。","Tôi đang tìm quần áo hợp với mình."]]},{"word":"それで","reading":"それで","meaning":"Vì thế, do đó","hanViet":"","lesson":1,"ex":[["雨が降りました。それで、家で本を読みました。","Trời đã mưa. Vì thế, tôi đã ở nhà đọc sách."],["電車が遅れました。それで、会社に遅刻しました。","Tàu đến muộn. Vì thế, tôi đã đến công ty muộn."],["財布を忘れました。それで、友達にお金を借りました。","Tôi quên ví. Vì thế, tôi đã mượn tiền bạn."],["日本語が好きです。それで、日本へ留学しました。","Tôi thích tiếng Nhật. Vì thế, tôi đã đi du học Nhật Bản."],["頭が痛いです。それで、きょうは早く帰ります。","Tôi bị đau đầu. Vì thế, hôm nay tôi về sớm."]]},{"word":"お礼","reading":"おれい","meaning":"Cám ơn, lời cám ơn","hanViet":"LỄ","lesson":1,"ex":[["お礼に花をあげました。","Tôi đã tặng hoa để cảm ơn."],["お礼を言いたいです。","Tôi muốn nói lời cảm ơn."],["お礼の手紙を書きました。","Tôi đã viết thư cảm ơn."],["先生にお礼を言いました。","Tôi đã cảm ơn thầy."],["お礼にケーキを作りました。","Tôi đã làm bánh để cảm ơn."]]},{"word":"ポイント","reading":"ポイント","meaning":"Điểm mấu chốt","hanViet":"","lesson":1,"ex":[["この問題のポイントはここです。","Điểm mấu chốt của vấn đề này là ở đây."],["試験のポイントを教えてください。","Hãy chỉ cho tôi điểm mấu chốt của kỳ thi."],["ポイントを覚えることが大切です。","Ghi nhớ điểm mấu chốt là quan trọng."],["料理のポイントは味です。","Điểm mấu chốt của món ăn là hương vị."],["日本語のポイントは、毎日使うことです。","Điểm mấu chốt của tiếng Nhật là dùng mỗi ngày."]]},{"word":"内容","reading":"ないよう","meaning":"Nội dung","hanViet":"NỘI DUNG","lesson":1,"ex":[["この本の内容はおもしろいです。","Nội dung cuốn sách này thú vị."],["内容をよく読んでください。","Hãy đọc kỹ nội dung."],["手紙の内容を教えてください。","Hãy cho tôi biết nội dung bức thư."],["会議の内容がわかりませんでした。","Tôi đã không hiểu nội dung cuộc họp."],["内容が難しくて、よくわかりませんでした。","Nội dung khó nên tôi không hiểu được."]]},{"word":"聞き取る","reading":"ききとる","meaning":"Nghe hiểu","hanViet":"VĂN THỦ","lesson":1,"ex":[["日本語のニュースを聞き取るのは難しいです。","Nghe hiểu tin tức tiếng Nhật rất khó."],["先生の日本語をよく聞き取れませんでした。","Tôi đã không nghe hiểu rõ tiếng Nhật của thầy."],["聞き取る練習を毎日しています。","Tôi luyện nghe hiểu mỗi ngày."],["速い日本語は聞き取ることができません。","Tôi không thể nghe hiểu tiếng Nhật nhanh."],["電話で名前を聞き取りました。","Tôi đã nghe hiểu tên qua điện thoại."]]},{"word":"表現","reading":"ひょうげん","meaning":"Cách diễn đạt, cách biểu đạt","hanViet":"BIỂU HIỆN","lesson":1,"ex":[["日本語の表現を勉強しています。","Tôi đang học các cách diễn đạt tiếng Nhật."],["新しい表現を覚えました。","Tôi đã nhớ một cách diễn đạt mới."],["この表現はどういう意味ですか。","Cách diễn đạt này có nghĩa là gì?"],["表現の使い方がわかりません。","Tôi không hiểu cách dùng của cách diễn đạt này."],["いろいろな表現を使って話したいです。","Tôi muốn nói chuyện bằng nhiều cách diễn đạt khác nhau."]]},{"word":"部分","reading":"ぶぶん","meaning":"Phần","hanViet":"BỘ PHÂN","lesson":1,"ex":[["この部分がわかりません。","Tôi không hiểu phần này."],["本の最初の部分を読みました。","Tôi đã đọc phần đầu của cuốn sách."],["難しい部分を先生に聞きました。","Tôi đã hỏi thầy phần khó."],["この部分をよく読んでください。","Hãy đọc kỹ phần này."],["この部分だけ日本語で書いてあります。","Chỉ phần này được viết bằng tiếng Nhật."]]},{"word":"市民","reading":"しみん","meaning":"Dân thành phố","hanViet":"THỊ DÂN","lesson":1,"ex":[["市民のための図書館があります。","Có thư viện dành cho người dân thành phố."],["多くの市民が祭りに参加しました。","Nhiều người dân thành phố đã tham gia lễ hội."],["市民の生活を守ることが大切です。","Bảo vệ cuộc sống của người dân thành phố là quan trọng."],["市民のための教室があります。","Có lớp học dành cho người dân thành phố."],["市民の声を聞くことが大切です。","Lắng nghe tiếng nói của người dân thành phố là quan trọng."]]},{"word":"会館","reading":"かいかん","meaning":"Hội quán","hanViet":"HỘI QUÁN","lesson":1,"ex":[["会館でコンサートがありました。","Ở hội quán đã có buổi hòa nhạc."],["会館の近くに公園があります。","Gần hội quán có công viên."],["会館で日本語を勉強しています。","Tôi học tiếng Nhật ở hội quán."],["会館を借りて、パーティーをしました。","Tôi đã thuê hội quán và tổ chức tiệc."],["新しい会館ができました。","Hội quán mới đã được xây xong."]]},{"word":"市民会館","reading":"しみんかいかん","meaning":"Hội quán công dân (Trung tâm sinh hoạt cộng đồng của người dân trong thành phố)","hanViet":"THỊ DÂN HỘI QUÁN","lesson":1,"ex":[["市民会館で祭りがありました。","Ở hội quán công dân đã có lễ hội."],["市民会館は駅の近くにあります。","Hội quán công dân ở gần ga."],["市民会館で日本語教室が開かれています。","Lớp học tiếng Nhật đang được mở ở hội quán công dân."],["市民会館の部屋は広いです。","Phòng của hội quán công dân rất rộng."],["市民会館で友達に会いました。","Tôi đã gặp bạn ở hội quán công dân."]]},{"word":"伝統的","reading":"でんとうてき","meaning":"Mang tính truyền thống","hanViet":"TRUYỀN THỐNG ĐÍCH","lesson":1,"ex":[["これは伝統的な日本の料理です。","Đây là món ăn truyền thống của Nhật Bản."],["伝統的な家に住みたいです。","Tôi muốn sống trong ngôi nhà truyền thống."],["伝統的な踊りを習っています。","Tôi đang học điệu múa truyền thống."],["その町は伝統的な町です。","Thị trấn đó là một thị trấn truyền thống."],["伝統的な服を着ました。","Tôi đã mặc trang phục truyền thống."]]},{"word":"実際に","reading":"じっさいに","meaning":"Thực tế","hanViet":"THỰC TẾ","lesson":1,"ex":[["実際に日本へ行ってみました。","Tôi đã thử đến Nhật Bản thật."],["実際にやってみると、難しくありませんでした。","Khi thử làm thật thì thấy không khó."],["実際に見ると、もっときれいです。","Nhìn thật thì còn đẹp hơn."],["実際に使ってみてください。","Hãy thử dùng thật xem."],["実際に話してみると、よくわかりました。","Khi nói chuyện thật thì tôi đã hiểu rõ."]]},{"word":"そういう","reading":"そういう","meaning":"Kiểu như thế","hanViet":"","lesson":1,"ex":[["そういう話は初めて聞きました。","Tôi mới nghe câu chuyện kiểu như thế lần đầu."],["そういうことはしないでください。","Đừng làm chuyện kiểu như thế."],["そういう人はあまりいません。","Người kiểu như thế không có nhiều."],["そういう日もあります。","Cũng có những ngày kiểu như thế."],["そういう考え方もいいですね。","Cách nghĩ kiểu như thế cũng tốt nhỉ."]]},{"word":"ふだん","reading":"ふだん","meaning":"Thông thường, bình thường","hanViet":"","lesson":1,"ex":[["ふだんはバスで会社へ行きます。","Thông thường tôi đi xe buýt đến công ty."],["ふだんは家でごはんを食べます。","Thông thường tôi ăn cơm ở nhà."],["ふだん何をしていますか。","Thông thường bạn làm gì?"],["ふだんはあまりテレビを見ません。","Thông thường tôi ít xem tivi."],["ふだん着ない服を着ました。","Tôi đã mặc bộ quần áo mà thông thường không mặc."]]},{"word":"何とか","reading":"なんとか","meaning":"Kiểu gì thì cũng","hanViet":"HÀ","lesson":1,"ex":[["何とか試験に合格しました。","Kiểu gì thì tôi cũng đã đỗ kỳ thi."],["何とか時間に間に合いました。","Kiểu gì thì tôi cũng đã kịp giờ."],["何とか日本語で話せました。","Kiểu gì thì tôi cũng đã nói được bằng tiếng Nhật."],["何とかやります。","Tôi sẽ làm bằng được."],["何とか宿題が終わりました。","Kiểu gì thì tôi cũng đã làm xong bài tập."]]},{"word":"イントネーション","reading":"イントネーション","meaning":"Ngữ điệu","hanViet":"","lesson":1,"ex":[["日本語のイントネーションは難しいです。","Ngữ điệu tiếng Nhật rất khó."],["イントネーションに気をつけて話してください。","Hãy chú ý ngữ điệu khi nói."],["先生のイントネーションを聞いて、練習します。","Tôi nghe ngữ điệu của thầy và luyện tập."],["イントネーションが違うと、意味が違います。","Ngữ điệu khác nhau thì ý nghĩa cũng khác nhau."],["正しいイントネーションで読みました。","Tôi đã đọc với ngữ điệu đúng."]]},{"word":"奨学金","reading":"しょうがくきん","meaning":"Học bổng","hanViet":"TƯỞNG HỌC KIM","lesson":1,"ex":[["奨学金をもらって、日本で勉強しています。","Tôi nhận học bổng và đang học ở Nhật Bản."],["奨学金を申し込みました。","Tôi đã đăng ký học bổng."],["奨学金がもらえると、うれしいです。","Nếu nhận được học bổng thì vui lắm."],["奨学金の試験があります。","Có kỳ thi học bổng."],["奨学金のおかげで、大学に行けました。","Nhờ học bổng, tôi đã có thể đi học đại học."]]},{"word":"推薦状","reading":"すいせんじょう","meaning":"Thư tiến cử","hanViet":"THÔI TIẾN TRẠNG","lesson":1,"ex":[["先生に推薦状を書いてもらいました。","Tôi đã nhờ thầy viết thư tiến cử."],["推薦状が必要です。","Cần có thư tiến cử."],["推薦状を大学に出しました。","Tôi đã nộp thư tiến cử cho đại học."],["推薦状を書いてくださいとお願いしました。","Tôi đã nhờ viết thư tiến cử."],["推薦状があれば、奨学金がもらいやすいです。","Nếu có thư tiến cử thì dễ nhận học bổng."]]},{"word":"交流","reading":"こうりゅう","meaning":"Giao lưu","hanViet":"GIAO LƯU","lesson":1,"ex":[["日本人との交流が楽しいです。","Giao lưu với người Nhật rất vui."],["留学生との交流を大切にしています。","Tôi coi trọng giao lưu với du học sinh."],["交流会に参加しました。","Tôi đã tham gia buổi giao lưu."],["文化交流が好きです。","Tôi thích giao lưu văn hóa."],["交流で日本語が上手になりました。","Nhờ giao lưu, tiếng Nhật của tôi đã giỏi hơn."]]},{"word":"司会","reading":"しかい","meaning":"Người dẫn chương trình tại buổi họp hay sự kiện xã hội","hanViet":"TY HỘI","lesson":1,"ex":[["パーティーの司会をしました。","Tôi đã làm MC cho buổi tiệc."],["司会は田中さんです。","MC là anh Tanaka."],["司会をするのは初めてです。","Đây là lần đầu tôi làm MC."],["司会が上手ですね。","Bạn làm MC giỏi nhỉ."],["司会を頼まれました。","Tôi đã được nhờ làm MC."]]},{"word":"目上","reading":"めうえ","meaning":"Người trên, người ở vai trên","hanViet":"MỤC THƯỢNG","lesson":1,"ex":[["目上の人に敬語を使います。","Tôi dùng kính ngữ với người trên."],["目上の人には丁寧に話します。","Tôi nói chuyện lịch sự với người trên."],["目上の人の前では、気をつけます。","Trước mặt người trên, tôi cẩn thận."],["目上の人に意見を言うのは難しいです。","Nói ý kiến với người trên rất khó."],["目上の人を大切にします。","Tôi coi trọng người trên."]]},{"word":"断る","reading":"ことわる","meaning":"Từ chối","hanViet":"ĐOẠN","lesson":1,"ex":[["誘いを断りました。","Tôi đã từ chối lời mời."],["断ることができませんでした。","Tôi đã không thể từ chối."],["友達の誘いを断るのは難しいです。","Từ chối lời mời của bạn rất khó."],["丁寧に断ってください。","Hãy từ chối một cách lịch sự."],["その仕事を断りました。","Tôi đã từ chối công việc đó."]]},{"word":"引き受ける","reading":"ひきうける","meaning":"Nhận","hanViet":"DẪN THỤ","lesson":1,"ex":[["仕事を引き受けました。","Tôi đã nhận công việc."],["引き受けるかどうか、考えています。","Tôi đang suy nghĩ xem có nhận hay không."],["その仕事は引き受けられません。","Tôi không thể nhận công việc đó."],["先生のお願いを引き受けました。","Tôi đã nhận lời nhờ của thầy."],["引き受けた仕事は、最後までやります。","Công việc đã nhận, tôi sẽ làm đến cuối cùng."]]},{"word":"印象","reading":"いんしょう","meaning":"Ấn tượng","hanViet":"ẤN TƯỢNG","lesson":1,"ex":[["いい印象を受けました。","Tôi đã có ấn tượng tốt."],["印象に残る映画でした。","Đó là bộ phim để lại ấn tượng."],["最初の印象が大切です。","Ấn tượng ban đầu rất quan trọng."],["強い印象を受けました。","Tôi đã có ấn tượng mạnh."],["その人の印象はとてもいいです。","Ấn tượng về người đó rất tốt."]]},{"word":"チェックする","reading":"チェックする","meaning":"Kiểm tra","hanViet":"","lesson":1,"ex":[["答えをチェックしてください。","Hãy kiểm tra đáp án."],["メールをチェックしました。","Tôi đã kiểm tra email."],["出かける前に、忘れ物がないかチェックします。","Trước khi ra ngoài, tôi kiểm tra xem có quên đồ không."],["予約をチェックしました。","Tôi đã kiểm tra đặt chỗ."],["荷物をチェックしてください。","Hãy kiểm tra hành lý."]]},{"word":"住まい","reading":"すまい","meaning":"Nơi ở","hanViet":"TRỤ","lesson":1,"ex":[["住まいは東京です。","Nơi ở của tôi là Tokyo."],["住まいを探しています。","Tôi đang tìm nơi ở."],["住まいの近くに駅があります。","Gần nơi ở của tôi có ga."],["新しい住まいに引っ越しました。","Tôi đã chuyển đến nơi ở mới."],["住まいが会社から遠いです。","Nơi ở của tôi xa công ty."]]},{"word":"たたむ","reading":"たたむ","meaning":"Gập","hanViet":"","lesson":1,"ex":[["服をたたんで、かばんに入れました。","Tôi đã gấp quần áo và bỏ vào cặp."],["布団をたたみました。","Tôi đã gấp chăn nệm."],["洗濯物をたたむのが好きです。","Tôi thích gấp quần áo đã giặt."],["紙をたたんで、箱に入れました。","Tôi đã gấp giấy và bỏ vào hộp."],["布団をたたんで、部屋を広くしました。","Tôi đã gấp chăn nệm để phòng rộng hơn."]]},{"word":"重ねる","reading":"かさねる","meaning":"Chồng lên","hanViet":"TRỌNG","lesson":1,"ex":[["本を重ねて置きました。","Tôi đã chồng sách lên nhau."],["皿を重ねてください。","Hãy chồng đĩa lên nhau."],["座布団を重ねました。","Tôi đã chồng đệm ngồi lên nhau."],["紙を重ねて、かばんに入れました。","Tôi đã chồng giấy lên nhau và bỏ vào cặp."],["服を重ねて着ます。","Tôi mặc nhiều lớp quần áo chồng lên nhau."]]},{"word":"板張り","reading":"いたばり","meaning":"Lát ván gỗ (sàn, trần, v.v.)","hanViet":"BẢN TRƯƠNG","lesson":1,"ex":[["この部屋は板張りの床です。","Phòng này có sàn gỗ."],["板張りの部屋が好きです。","Tôi thích phòng sàn gỗ."],["板張りの床は冷たいです。","Sàn gỗ lạnh."],["板張りの床を掃除しました。","Tôi đã lau sàn gỗ."],["居間は板張りです。","Phòng sinh hoạt chung là sàn gỗ."]]},{"word":"素足","reading":"すあし","meaning":"Chân trần","hanViet":"TỐ TÚC","lesson":1,"ex":[["素足で歩くのが好きです。","Tôi thích đi chân trần."],["家では素足でいます。","Ở nhà tôi đi chân trần."],["素足で畳の上に座りました。","Tôi đã ngồi chân trần lên chiếu tatami."],["夏は素足でいることが多いです。","Mùa hè tôi thường đi chân trần."],["素足で床を歩きました。","Tôi đã đi chân trần trên sàn nhà."]]},{"word":"使い分ける","reading":"つかいわける","meaning":"Thay đổi, chọn dùng cho từng mục đích, đối tượng khác nhau","hanViet":"SỬ PHÂN","lesson":1,"ex":[["敬語と普通の話し方を使い分けます。","Tôi dùng phân biệt kính ngữ và cách nói thông thường."],["ボールペンと鉛筆を使い分けます。","Tôi dùng phân biệt bút bi và bút chì."],["日本語と英語を使い分けています。","Tôi đang dùng phân biệt tiếng Nhật và tiếng Anh."],["仕事と家で、ことばを使い分けます。","Tôi dùng từ ngữ phân biệt ở công ty và ở nhà."],["丁寧なことばと普通のことばを使い分けます。","Tôi dùng phân biệt lời nói lịch sự và lời nói thông thường."]]},{"word":"良さ","reading":"よさ","meaning":"Ưu điểm, điểm tốt","hanViet":"LƯƠNG","lesson":1,"ex":[["この町の良さは、静かなことです。","Ưu điểm của thị trấn này là yên tĩnh."],["畳の良さを教えてください。","Hãy cho tôi biết ưu điểm của tatami."],["その本の良さがわかりました。","Tôi đã hiểu điểm hay của cuốn sách đó."],["日本語の良さは、丁寧な表現が多いことです。","Điểm hay của tiếng Nhật là có nhiều cách diễn đạt lịch sự."],["この部屋の良さは、明るいことです。","Ưu điểm của phòng này là sáng sủa."]]},{"word":"読み取る","reading":"よみとる","meaning":"Đọc hiểu","hanViet":"ĐỘC THỦ","lesson":1,"ex":[["文章の意味を読み取るのは難しいです。","Đọc hiểu ý nghĩa của đoạn văn rất khó."],["地図を読み取ることができます。","Tôi có thể đọc hiểu bản đồ."],["彼の気持ちを読み取ることができませんでした。","Tôi đã không thể đọc hiểu cảm xúc của anh ấy."],["手紙の内容を読み取りました。","Tôi đã đọc hiểu nội dung bức thư."],["問題の意味を読み取って、答えました。","Tôi đã đọc hiểu ý nghĩa của câu hỏi và trả lời."]]},{"word":"旅行者","reading":"りょこうしゃ","meaning":"Khách du lịch","hanViet":"LỮ HÀNH GIẢ","lesson":1,"ex":[["旅行者が多い季節です。","Đây là mùa có nhiều khách du lịch."],["旅行者のために、地図を用意しました。","Tôi đã chuẩn bị bản đồ cho khách du lịch."],["旅行者に道を教えました。","Tôi đã chỉ đường cho khách du lịch."],["旅行者が京都に来ています。","Khách du lịch đang đến Kyoto."],["旅行者と話すのが楽しいです。","Nói chuyện với khách du lịch rất vui."]]},{"word":"～者","reading":"～しゃ","meaning":"Người ～","hanViet":"GIẢ","lesson":1,"ex":[["この病院には患者が多いです。","Bệnh viện này có nhiều bệnh nhân."],["参加者が100人集まりました。","Có 100 người tham gia đã tập trung."],["旅行者が増えています。","Khách du lịch đang tăng lên."],["利用者が多くなりました。","Số người sử dụng đã tăng lên."],["学習者が増えています。","Số người học đang tăng lên."]]},{"word":"最も","reading":"もっとも","meaning":"Nhất","hanViet":"TỐI","lesson":1,"ex":[["この中で最も大きいのはどれですか。","Trong số này, cái nào lớn nhất?"],["最も好きな食べ物は寿司です。","Món ăn thích nhất của tôi là sushi."],["最も大切なのは健康です。","Quan trọng nhất là sức khỏe."],["夏で最も暑いのは8月です。","Trong mùa hè, nóng nhất là tháng 8."],["最も早く来たのは田中さんです。","Người đến sớm nhất là anh Tanaka."]]},{"word":"非常に","reading":"ひじょうに","meaning":"Rất","hanViet":"PHI THƯỜNG","lesson":1,"ex":[["非常に難しい問題です。","Đây là vấn đề rất khó."],["非常に忙しい一日でした。","Đó là một ngày rất bận."],["非常にうれしいです。","Tôi rất vui."],["非常に静かな町です。","Đó là thị trấn rất yên tĩnh."],["非常に大切なことです。","Đây là chuyện rất quan trọng."]]},{"word":"それほど","reading":"それほど","meaning":"Đến như vậy","hanViet":"","lesson":1,"ex":[["それほど難しくありません。","Không khó đến như vậy."],["それほど食べられませんでした。","Tôi đã không ăn được nhiều đến như vậy."],["それほど暑くなかったです。","Không nóng đến như vậy."],["それほど時間がかかりませんでした。","Không tốn nhiều thời gian đến như vậy."],["それほど心配しなくてもいいです。","Không cần lo lắng đến như vậy."]]},{"word":"代表する","reading":"だいひょうする","meaning":"Tiêu biểu, đại diện","hanViet":"ĐẠI BIỂU","lesson":1,"ex":[["桜は日本を代表する花です。","Hoa anh đào là loài hoa tiêu biểu cho Nhật Bản."],["寿司は日本を代表する料理です。","Sushi là món ăn tiêu biểu cho Nhật Bản."],["彼はクラスを代表して、話しました。","Anh ấy đã nói chuyện đại diện cho lớp."],["この歌はその時代を代表する歌です。","Bài hát này là bài hát tiêu biểu cho thời đại đó."],["彼は日本を代表する作家です。","Anh ấy là nhà văn tiêu biểu của Nhật Bản."]]},{"word":"全体","reading":"ぜんたい","meaning":"Toàn bộ","hanViet":"TOÀN THỂ","lesson":1,"ex":[["全体を見てください。","Hãy nhìn toàn bộ."],["全体の半分が終わりました。","Đã xong một nửa."],["クラス全体で旅行に行きました。","Cả lớp đã đi du lịch."],["全体をよく考えました。","Tôi đã suy nghĩ kỹ toàn bộ."],["全体がきれいになりました。","Toàn bộ đã trở nên sạch đẹp."]]},{"word":"敷く","reading":"しく","meaning":"Lót","hanViet":"PHU","lesson":1,"ex":[["床に畳を敷きました。","Tôi đã lót chiếu tatami lên sàn."],["テーブルの上に紙を敷きました。","Tôi đã lót giấy lên bàn."],["床に座布団を敷きました。","Tôi đã lót đệm ngồi lên sàn."],["敷いた畳の上に座りました。","Tôi đã ngồi lên chiếu tatami đã lót."],["新しい畳を敷くのは大変です。","Lót chiếu tatami mới rất vất vả."]]},{"word":"ちょうど","reading":"ちょうど","meaning":"Đúng lúc, vừa đúng, chính xác","hanViet":"","lesson":1,"ex":[["ちょうど今、家に帰りました。","Tôi vừa về nhà đúng lúc này."],["ちょうどいい時間です。","Đúng là thời gian thích hợp."],["ちょうど3時に来てください。","Hãy đến đúng 3 giờ."],["ちょうど12時に昼ごはんを食べました。","Tôi đã ăn trưa đúng 12 giờ."],["この服はちょうどいいです。","Bộ quần áo này vừa vặn."]]},{"word":"何枚も","reading":"なんまいも","meaning":"Nhiều tấm","hanViet":"HÀ MAI","lesson":1,"ex":[["写真を何枚も撮りました。","Tôi đã chụp nhiều tấm ảnh."],["何枚も紙を使いました。","Tôi đã dùng nhiều tờ giấy."],["何枚も切手を買いました。","Tôi đã mua nhiều con tem."],["何枚も皿を洗いました。","Tôi đã rửa nhiều cái đĩa."],["何枚も手紙を書きました。","Tôi đã viết nhiều bức thư."]]},{"word":"つける","reading":"つける","meaning":"Gắn, đeo, bật","hanViet":"","lesson":1,"ex":[["子どもに名前をつけました。","Tôi đã đặt tên cho con."],["電気をつけてください。","Hãy bật điện lên."],["壁にポスターをつけました。","Tôi đã dán áp phích lên tường."],["どんな名前をつけますか。","Bạn sẽ đặt tên gì?"],["子どもの名前は、父親がつけました。","Tên của con do bố đặt."]]},{"word":"やまとことば","reading":"やまとことば","meaning":"Từ thuần gốc Nhật","hanViet":"","lesson":1,"ex":[["やまとことばは、日本の古いことばです。","Yamato kotoba là từ ngữ cổ của Nhật Bản."],["やまとことばを勉強しています。","Tôi đang học từ thuần Nhật."],["「さくら」はやまとことばです。","\"Sakura\" là từ thuần Nhật."],["やまとことばは日本人のことばです。","Yamato kotoba là ngôn ngữ của người Nhật."],["やまとことばと漢字のことばがあります。","Có từ thuần Nhật và từ Hán tự."]]},{"word":"動かす","reading":"うごかす","meaning":"Dịch chuyển","hanViet":"ĐỘNG","lesson":1,"ex":[["机を動かしました。","Tôi đã dịch chuyển cái bàn."],["重い箱を動かすのは大変です。","Dịch chuyển hộp nặng rất vất vả."],["車を少し動かしてください。","Hãy dịch chuyển xe một chút."],["体を動かすことが大切です。","Vận động cơ thể rất quan trọng."],["机を動かして、部屋を掃除しました。","Tôi đã dịch chuyển bàn và lau phòng."]]},{"word":"組み合わせる","reading":"くみあわせる","meaning":"Kết hợp","hanViet":"TỔ HỢP","lesson":1,"ex":[["色を組み合わせて、服を選びます。","Tôi kết hợp màu sắc để chọn quần áo."],["ことばを組み合わせて、話します。","Tôi kết hợp từ ngữ để nói chuyện."],["野菜と肉を組み合わせて、料理を作ります。","Tôi kết hợp rau và thịt để nấu ăn."],["赤と白を組み合わせました。","Tôi đã kết hợp màu đỏ và trắng."],["二つのことばを組み合わせました。","Tôi đã kết hợp hai từ."]]},{"word":"客間","reading":"きゃくま","meaning":"Phòng khách","hanViet":"KHÁCH GIAN","lesson":1,"ex":[["客間で友達と話しました。","Tôi đã nói chuyện với bạn ở phòng khách."],["客間は畳の部屋です。","Phòng khách là phòng tatami."],["客間を掃除しました。","Tôi đã dọn phòng khách."],["客間に座布団を置きました。","Tôi đã đặt đệm ngồi ở phòng khách."],["客間は静かです。","Phòng khách yên tĩnh."]]},{"word":"居間","reading":"いま","meaning":"Phòng sinh hoạt chung","hanViet":"CƯ GIAN","lesson":1,"ex":[["居間でテレビを見ます。","Tôi xem tivi ở phòng sinh hoạt chung."],["居間は家族が集まる場所です。","Phòng sinh hoạt chung là nơi gia đình tụ họp."],["居間で本を読みました。","Tôi đã đọc sách ở phòng sinh hoạt chung."],["居間は明るいです。","Phòng sinh hoạt chung sáng sủa."],["居間でごはんを食べました。","Tôi đã ăn cơm ở phòng sinh hoạt chung."]]},{"word":"仕事部屋","reading":"しごとべや","meaning":"Phòng làm việc","hanViet":"SĨ SỰ BỘ ỐC","lesson":1,"ex":[["仕事部屋で勉強します。","Tôi học trong phòng làm việc."],["仕事部屋は静かです。","Phòng làm việc yên tĩnh."],["仕事部屋に机があります。","Trong phòng làm việc có bàn."],["仕事部屋を掃除しました。","Tôi đã dọn phòng làm việc."],["仕事部屋で仕事をしています。","Tôi đang làm việc trong phòng làm việc."]]},{"word":"ワラ","reading":"ワラ","meaning":"Rơm","hanViet":"","lesson":1,"ex":[["畳はワラで作られています。","Tatami được làm từ rơm."],["ワラのにおいがします。","Có mùi rơm."],["昔はワラの家がありました。","Ngày xưa có nhà rơm."],["ワラで作ったものがあります。","Có đồ được làm từ rơm."],["ワラは畳に使われます。","Rơm được dùng cho tatami."]]},{"word":"イグサ","reading":"イグサ","meaning":"Cói","hanViet":"","lesson":1,"ex":[["畳はイグサで作られています。","Tatami được làm từ cói."],["イグサのにおいが好きです。","Tôi thích mùi cói."],["イグサはいいにおいがします。","Cói có mùi thơm."],["イグサで畳を作ります。","Người ta dùng cói để làm tatami."],["イグサの畳は気持ちがいいです。","Tatami cói rất dễ chịu."]]},{"word":"呼吸する","reading":"こきゅうする","meaning":"Hô hấp, thở","hanViet":"HÔ HẤP","lesson":1,"ex":[["深く呼吸してください。","Hãy thở sâu."],["ゆっくり呼吸します。","Tôi thở chậm rãi."],["呼吸を止めないでください。","Đừng nín thở."],["走ったあとで、大きく呼吸しました。","Sau khi chạy, tôi đã thở mạnh."],["呼吸するたびに、体が動きます。","Mỗi lần thở, cơ thể lại chuyển động."]]},{"word":"湿気","reading":"しっけ","meaning":"Hơi ẩm, độ ẩm","hanViet":"THẤP KHÍ","lesson":1,"ex":[["湿気が多いです。","Độ ẩm cao."],["夏は湿気が多いです。","Mùa hè độ ẩm cao."],["畳は湿気を取ります。","Tatami hút ẩm."],["湿気で服が乾きません。","Vì ẩm nên quần áo không khô."],["湿気を取るために、窓を開けます。","Để hút ẩm, tôi mở cửa sổ."]]},{"word":"取る","reading":"とる","meaning":"Lấy, cầm","hanViet":"THỦ","lesson":1,"ex":[["机の上にあった本を取りました。","Tôi đã lấy cuốn sách trên bàn."],["写真を取るのが好きです。","Tôi thích chụp ảnh."],["傘を取って、家を出ました。","Tôi đã lấy ô và ra khỏi nhà."],["畳は湿気を取って、部屋を快適にします。","Tatami hút ẩm và làm phòng thoải mái."],["予約を取ることができますか。","Tôi có thể đặt chỗ được không?"]]},{"word":"快適","reading":"かいてき","meaning":"Thoải mái, dễ chịu","hanViet":"KHOÁI THÍCH","lesson":1,"ex":[["この部屋は快適です。","Căn phòng này rất thoải mái."],["快適な生活を送っています。","Tôi đang sống một cuộc sống thoải mái."],["畳の部屋は快適です。","Phòng tatami rất thoải mái."],["快適ないすです。","Chiếc ghế rất thoải mái."],["夏はエアコンがあって、快適です。","Mùa hè có điều hòa nên rất thoải mái."]]},{"word":"清潔","reading":"せいけつ","meaning":"Sạch sẽ","hanViet":"THANH KHIẾT","lesson":1,"ex":[["このレストランはいつも清潔です。","Nhà hàng này lúc nào cũng sạch sẽ."],["部屋を清潔にしておきましょう。","Hãy giữ phòng luôn sạch sẽ."],["清潔な水を飲むことは大切です。","Uống nước sạch là điều quan trọng."],["彼女は清潔な服が好きです。","Cô ấy thích quần áo sạch sẽ."],["トイレを清潔に使うことが必要です。","Cần sử dụng nhà vệ sinh một cách sạch sẽ."]]},{"word":"本文","reading":"ほんぶん","meaning":"Bài văn chính","hanViet":"BẢN VĂN","lesson":1,"ex":[["本文を読んで、質問に答えてください。","Hãy đọc bài văn chính rồi trả lời câu hỏi."],["本文の意味がよく分かりません。","Tôi không hiểu rõ ý nghĩa của bài văn chính."],["この本文は日本語で書いてあります。","Bài văn chính này được viết bằng tiếng Nhật."],["本文を読む前に、タイトルを見ましょう。","Trước khi đọc bài văn chính, hãy xem tiêu đề."],["本文に難しい漢字がたくさんあります。","Trong bài văn chính có nhiều chữ Hán khó."]]},{"word":"一戸建て","reading":"いっこだて","meaning":"Nhà nguyên căn, nhà riêng","hanViet":"NHẤT HỘ KIẾN","lesson":1,"ex":[["私の家は一戸建てです。","Nhà của tôi là nhà riêng nguyên căn."],["一戸建ての家に住みたいです。","Tôi muốn sống trong một ngôi nhà riêng nguyên căn."],["この辺りには一戸建てが多いです。","Quanh khu vực này có nhiều nhà riêng nguyên căn."],["彼は一戸建てを買いました。","Anh ấy đã mua một ngôi nhà riêng nguyên căn."],["一戸建てはマンションより広いです。","Nhà riêng nguyên căn rộng hơn chung cư."]]},{"word":"小学生","reading":"しょうがくせい","meaning":"Học sinh tiểu học","hanViet":"TIỂU HỌC SINH","lesson":1,"ex":[["私の弟は小学生です。","Em trai tôi là học sinh tiểu học."],["小学生が公園で遊んでいます。","Các học sinh tiểu học đang chơi ở công viên."],["あの小学生は毎日学校へ歩いて行きます。","Em học sinh tiểu học đó mỗi ngày đi bộ đến trường."],["小学生のとき、私は野球が好きでした。","Hồi còn là học sinh tiểu học, tôi thích bóng chày."],["小学生に日本語を教えています。","Tôi đang dạy tiếng Nhật cho học sinh tiểu học."]]},{"word":"日常生活","reading":"にちじょうせいかつ","meaning":"Cuộc sống thường ngày","hanViet":"NHẬT THƯỜNG SINH HOẠT","lesson":1,"ex":[["日本語は日常生活で役に立ちます。","Tiếng Nhật có ích trong cuộc sống thường ngày."],["日常生活の中で、新しい言葉を覚えます。","Trong cuộc sống thường ngày, tôi học những từ mới."],["日常生活について話しましょう。","Hãy nói về cuộc sống thường ngày."],["彼の日常生活はとても忙しいです。","Cuộc sống thường ngày của anh ấy rất bận rộn."],["日常生活で使う日本語を勉強しています。","Tôi đang học tiếng Nhật dùng trong cuộc sống thường ngày."]]},{"word":"ふく","reading":"ふく","meaning":"Lau, chùi","hanViet":"","lesson":2,"ex":[["窓をふいてください。","Hãy lau cửa sổ."],["テーブルをふく前に、ごみを片づけます。","Trước khi lau bàn, tôi dọn rác."],["汗をタオルでふきました。","Tôi đã lau mồ hôi bằng khăn."],["子どもは顔をふいて、学校へ行きました。","Đứa trẻ lau mặt rồi đi học."],["毎日、机をふいています。","Mỗi ngày tôi đều lau bàn."]]},{"word":"結果","reading":"けっか","meaning":"Kết quả","hanViet":"KẾT QUẢ","lesson":2,"ex":[["試験の結果が分かりました。","Tôi đã biết kết quả kỳ thi."],["結果はどうでしたか。","Kết quả thế nào?"],["いい結果が出て、うれしいです。","Có kết quả tốt nên tôi rất vui."],["結果について、先生と話しました。","Tôi đã nói chuyện với thầy về kết quả."],["努力した結果、合格しました。","Nhờ nỗ lực nên tôi đã đỗ."]]},{"word":"外来語","reading":"がいらいご","meaning":"Từ ngoại lai","hanViet":"NGOẠI LAI NGỮ","lesson":2,"ex":[["日本語には外来語が多いです。","Trong tiếng Nhật có nhiều từ ngoại lai."],["コンピューターは外来語です。","Máy tính là từ ngoại lai."],["外来語の意味を調べました。","Tôi đã tra nghĩa của từ ngoại lai."],["外来語を覚えるのは難しいです。","Nhớ từ ngoại lai thì khó."],["この本には外来語がたくさん出てきます。","Trong cuốn sách này xuất hiện nhiều từ ngoại lai."]]},{"word":"守る","reading":"まもる","meaning":"Bảo vệ, giữ gìn; giữ (lời hứa, quy tắc)","hanViet":"THỦ","lesson":2,"ex":[["地球を守ることは大切です。","Bảo vệ Trái Đất là điều quan trọng."],["約束を守らなければなりません。","Phải giữ lời hứa."],["交通の規則を守ってください。","Hãy tuân thủ luật giao thông."],["私たちは自然を守ります。","Chúng ta bảo vệ thiên nhiên."],["彼は家族を守るために働いています。","Anh ấy làm việc để bảo vệ gia đình."]]},{"word":"ソフトウェア","reading":"ソフトウェア","meaning":"Phần mềm","hanViet":"","lesson":2,"ex":[["新しいソフトウェアを買いました。","Tôi đã mua phần mềm mới."],["このソフトウェアは使いやすいです。","Phần mềm này dễ sử dụng."],["ソフトウェアを使う方法を教えてください。","Hãy chỉ cho tôi cách dùng phần mềm."],["パソコンにソフトウェアを入れました。","Tôi đã cài phần mềm vào máy tính."],["ソフトウェアが古くなりました。","Phần mềm đã cũ rồi."]]},{"word":"メール","reading":"メール","meaning":"Thư điện tử","hanViet":"","lesson":2,"ex":[["メールを送りました。","Tôi đã gửi email."],["先生にメールを書きます。","Tôi viết email cho thầy."],["メールが届きましたか。","Email đã đến chưa?"],["毎朝、メールをチェックします。","Mỗi sáng tôi kiểm tra email."],["友達からメールをもらいました。","Tôi đã nhận được email từ bạn."]]},{"word":"郵便","reading":"ゆうびん","meaning":"Bưu chính, thư tín","hanViet":"BƯU TIỆN","lesson":2,"ex":[["郵便で手紙を送ります。","Tôi gửi thư qua đường bưu điện."],["郵便は明日届きます。","Thư sẽ đến vào ngày mai."],["郵便局で郵便を出しました。","Tôi đã gửi bưu phẩm ở bưu điện."],["郵便の料金はいくらですか。","Phí bưu điện là bao nhiêu?"],["郵便で本を送ってもらいました。","Tôi đã nhờ gửi sách qua đường bưu điện."]]},{"word":"Eメール","reading":"イーメール","meaning":"E-mail, thư điện tử","hanViet":"","lesson":2,"ex":[["Eメールを送ってください。","Hãy gửi E-mail cho tôi."],["Eメールのアドレスを教えてください。","Hãy cho tôi biết địa chỉ E-mail."],["Eメールで連絡します。","Tôi sẽ liên lạc bằng E-mail."],["Eメールが届いていません。","E-mail vẫn chưa đến."],["毎日、Eメールを読みます。","Mỗi ngày tôi đọc E-mail."]]},{"word":"栄養","reading":"えいよう","meaning":"Dinh dưỡng","hanViet":"VINH DƯỠNG","lesson":2,"ex":[["野菜は栄養がたくさんあります。","Rau có nhiều dinh dưỡng."],["栄養のバランスを考えて食べましょう。","Hãy ăn uống cân nhắc cân bằng dinh dưỡng."],["この食べ物は栄養がありません。","Món ăn này không có dinh dưỡng."],["栄養について勉強しています。","Tôi đang học về dinh dưỡng."],["子どもに栄養のある食事をあげます。","Tôi cho trẻ ăn bữa ăn giàu dinh dưỡng."]]},{"word":"カロリー","reading":"カロリー","meaning":"Calo","hanViet":"","lesson":2,"ex":[["このケーキはカロリーが高いです。","Chiếc bánh này có lượng calo cao."],["カロリーを気にしています。","Tôi đang quan tâm đến lượng calo."],["低いカロリーの食べ物を選びます。","Tôi chọn món ăn ít calo."],["カロリーが少ない食事がいいです。","Bữa ăn ít calo thì tốt."],["ライスのカロリーはどのくらいですか。","Cơm có bao nhiêu calo?"]]},{"word":"エコ","reading":"エコ","meaning":"Sinh thái, quan tâm đến môi trường","hanViet":"","lesson":2,"ex":[["エコな生活をしたいです。","Tôi muốn sống một cuộc sống thân thiện với môi trường."],["エコなバッグを使っています。","Tôi đang dùng túi thân thiện với môi trường."],["エコについて考えましょう。","Hãy suy nghĩ về vấn đề sinh thái."],["この車はエコです。","Chiếc xe này thân thiện với môi trường."],["エコな商品を買います。","Tôi mua sản phẩm thân thiện với môi trường."]]},{"word":"環境","reading":"かんきょう","meaning":"Môi trường","hanViet":"HOÀN CẢNH","lesson":2,"ex":[["環境を守ることは大切です。","Bảo vệ môi trường là điều quan trọng."],["環境について話し合いました。","Chúng tôi đã thảo luận về môi trường."],["いい環境で勉強したいです。","Tôi muốn học trong môi trường tốt."],["環境が悪くなっています。","Môi trường đang trở nên xấu đi."],["環境にやさしい生活をしましょう。","Hãy sống thân thiện với môi trường."]]},{"word":"アポ","reading":"アポ","meaning":"Cuộc hẹn","hanViet":"","lesson":2,"ex":[["明日、アポがあります。","Ngày mai tôi có cuộc hẹn."],["先生とアポをとりました。","Tôi đã hẹn với thầy."],["アポの時間を変更しました。","Tôi đã đổi giờ hẹn."],["アポをキャンセルしなければなりません。","Tôi phải hủy cuộc hẹn."],["アポは午後三時です。","Cuộc hẹn lúc 3 giờ chiều."]]},{"word":"省エネ","reading":"しょうエネ","meaning":"Tiết kiệm năng lượng","hanViet":"TỈNH","lesson":2,"ex":[["省エネのために、電気を消します。","Để tiết kiệm năng lượng, tôi tắt điện."],["省エネのエアコンを買いました。","Tôi đã mua điều hòa tiết kiệm năng lượng."],["省エネについて考えています。","Tôi đang suy nghĩ về việc tiết kiệm năng lượng."],["省エネは環境にいいです。","Tiết kiệm năng lượng tốt cho môi trường."],["省エネのために、バスで会社へ行きます。","Để tiết kiệm năng lượng, tôi đi xe buýt đến công ty."]]},{"word":"学習する","reading":"がくしゅうする","meaning":"Học","hanViet":"HỌC TẬP","lesson":2,"ex":[["日本語を学習しています。","Tôi đang học tiếng Nhật."],["学習する時間が必要です。","Cần có thời gian học tập."],["毎日、漢字を学習します。","Mỗi ngày tôi học chữ Hán."],["学習したことを使いたいです。","Tôi muốn sử dụng những điều đã học."],["学習する方法を教えてください。","Hãy chỉ cho tôi phương pháp học tập."]]},{"word":"記事","reading":"きじ","meaning":"Bài báo trên một tờ báo, tạp chí, v.v.","hanViet":"KÍ SỰ","lesson":2,"ex":[["新聞の記事を読みました。","Tôi đã đọc bài báo trên báo."],["この記事はおもしろいです。","Bài báo này thú vị."],["記事について話しました。","Tôi đã nói về bài báo."],["インターネットで記事を探します。","Tôi tìm bài báo trên mạng."],["記事を書くのは難しいです。","Viết bài báo thì khó."]]},{"word":"分ける","reading":"わける","meaning":"Chia, phân loại","hanViet":"PHÂN","lesson":2,"ex":[["ごみを分けましょう。","Hãy phân loại rác."],["ケーキを四つに分けました。","Tôi đã chia bánh thành bốn phần."],["仕事を友達と分けます。","Tôi chia công việc với bạn."],["ごみを分けることは大切です。","Phân loại rác là điều quan trọng."],["教室を二つに分けました。","Tôi đã chia lớp học thành hai phần."]]},{"word":"うわさ","reading":"うわさ","meaning":"Tin đồn","hanViet":"","lesson":2,"ex":[["うわさを聞きました。","Tôi đã nghe tin đồn."],["うわさは本当ですか。","Tin đồn có đúng không?"],["うわさについて話さないでください。","Đừng nói về tin đồn."],["あのうわさはうそです。","Tin đồn đó là dối trá."],["うわさを信じません。","Tôi không tin tin đồn."]]},{"word":"辺り","reading":"あたり","meaning":"Khu vực","hanViet":"BIÊN","lesson":2,"ex":[["この辺りは静かです。","Khu vực này yên tĩnh."],["駅の辺りに店が多いです。","Quanh khu vực nhà ga có nhiều cửa hàng."],["この辺りを散歩しました。","Tôi đã đi dạo quanh khu vực này."],["辺りが暗くなりました。","Quanh đây đã trở nên tối."],["あの辺りに公園があります。","Quanh khu vực đó có công viên."]]},{"word":"アドバイス","reading":"アドバイス","meaning":"Lời khuyên","hanViet":"","lesson":2,"ex":[["先生にアドバイスをもらいました。","Tôi đã nhận được lời khuyên từ thầy."],["アドバイスをありがとうございます。","Cảm ơn lời khuyên của bạn."],["友達にアドバイスをします。","Tôi đưa ra lời khuyên cho bạn."],["いいアドバイスを聞きました。","Tôi đã nghe được lời khuyên hay."],["アドバイスが必要です。","Tôi cần lời khuyên."]]},{"word":"事件","reading":"じけん","meaning":"Vụ án","hanViet":"SỰ KIỆN","lesson":2,"ex":[["事件についてニュースで聞きました。","Tôi đã nghe về vụ án trên tin tức."],["大きな事件が起きました。","Đã xảy ra một vụ án lớn."],["事件の犯人はまだ分かりません。","Vẫn chưa biết thủ phạm của vụ án."],["事件を調べています。","Tôi đang điều tra vụ án."],["この事件は有名です。","Vụ án này nổi tiếng."]]},{"word":"奪う","reading":"うばう","meaning":"Cướp, đoạt","hanViet":"ĐOẠT","lesson":2,"ex":[["泥棒がお金を奪いました。","Kẻ trộm đã cướp tiền."],["彼は私のバッグを奪いました。","Anh ta đã cướp túi của tôi."],["奪うことはよくありません。","Việc cướp đoạt là không tốt."],["犬が子どものおもちゃを奪いました。","Con chó đã giật đồ chơi của đứa trẻ."],["彼は私の時間を奪いました。","Anh ta đã cướp mất thời gian của tôi."]]},{"word":"干す","reading":"ほす","meaning":"Phơi","hanViet":"CAN","lesson":2,"ex":[["洗濯物を干します。","Tôi phơi đồ giặt."],["洗濯物を外に干しました。","Tôi đã phơi đồ giặt ra ngoài."],["雨の日は洗濯物を干しません。","Ngày mưa tôi không phơi đồ giặt."],["シャツを干してください。","Hãy phơi áo sơ mi."],["洗濯物がよく干せました。","Đồ giặt đã được phơi khô tốt."]]},{"word":"以外","reading":"いがい","meaning":"Ngoài","hanViet":"DĨ NGOẠI","lesson":2,"ex":[["日曜日以外、毎日働きます。","Ngoài chủ nhật, tôi làm việc mỗi ngày."],["私以外、みんな日本人です。","Ngoài tôi ra, mọi người đều là người Nhật."],["これ以外に質問はありますか。","Ngoài điều này ra còn câu hỏi nào không?"],["休日以外は忙しいです。","Ngoài ngày nghỉ ra thì bận rộn."],["彼以外、だれも来ませんでした。","Ngoài anh ấy ra, không ai đến cả."]]},{"word":"つく","reading":"つく","meaning":"(trong cụm うそをつく) Nói dối","hanViet":"","lesson":2,"ex":[["うそをついてはいけません。","Không được nói dối."],["彼はうそをつきました。","Anh ấy đã nói dối."],["うそをつくのはよくありません。","Nói dối là không tốt."],["子どもはうそをつきません。","Trẻ con không nói dối."],["うそをついたことがありますか。","Bạn đã từng nói dối chưa?"]]},{"word":"ロボット","reading":"ロボット","meaning":"Rô bốt","hanViet":"","lesson":2,"ex":[["ロボットが部屋を掃除します。","Rô bốt dọn dẹp phòng."],["ロボットを作りたいです。","Tôi muốn làm rô bốt."],["このロボットは日本語を話します。","Rô bốt này nói tiếng Nhật."],["ロボットについて勉強しています。","Tôi đang học về rô bốt."],["ロボットが工場で働いています。","Rô bốt đang làm việc trong nhà máy."]]},{"word":"本物","reading":"ほんもの","meaning":"Đồ thật","hanViet":"BẢN VẬT","lesson":2,"ex":[["これは本物です。","Đây là đồ thật."],["本物の絵は高いです。","Tranh thật thì đắt."],["本物かどうか分かりません。","Tôi không biết có phải đồ thật hay không."],["本物を見たことがありますか。","Bạn đã từng thấy đồ thật chưa?"],["本物の寿司を食べたいです。","Tôi muốn ăn sushi thật."]]},{"word":"飛ぶ","reading":"とぶ","meaning":"Bay","hanViet":"PHI","lesson":2,"ex":[["鳥が空を飛んでいます。","Chim đang bay trên trời."],["飛行機が空を飛びます。","Máy bay bay trên trời."],["鳥は高く飛ぶことができます。","Chim có thể bay cao."],["紙の飛行機が飛びました。","Máy bay giấy đã bay."],["ボールが空に飛びました。","Quả bóng đã bay lên trời."]]},{"word":"オレンジ","reading":"オレンジ","meaning":"Cam","hanViet":"","lesson":2,"ex":[["オレンジを食べました。","Tôi đã ăn cam."],["オレンジのジュースを飲みます。","Tôi uống nước cam."],["オレンジが好きです。","Tôi thích cam."],["オレンジを三つ買いました。","Tôi đã mua ba quả cam."],["このオレンジは甘いです。","Quả cam này ngọt."]]},{"word":"パジャマ","reading":"パジャマ","meaning":"Đồ Pijama","hanViet":"","lesson":2,"ex":[["パジャマを着て寝ます。","Tôi mặc đồ pijama rồi đi ngủ."],["新しいパジャマを買いました。","Tôi đã mua đồ pijama mới."],["パジャマのまま、朝ごはんを食べました。","Tôi ăn sáng trong bộ đồ pijama."],["パジャマを洗いました。","Tôi đã giặt đồ pijama."],["このパジャマは着やすいです。","Bộ pijama này dễ mặc."]]},{"word":"四角い","reading":"しかくい","meaning":"Vuông","hanViet":"TỨ GIÁC","lesson":2,"ex":[["この箱は四角いです。","Cái hộp này vuông."],["四角いテーブルを買いました。","Tôi đã mua bàn vuông."],["四角い形が好きです。","Tôi thích hình vuông."],["この紙は四角いです。","Tờ giấy này vuông."],["四角い窓があります。","Có cửa sổ vuông."]]},{"word":"腕","reading":"うで","meaning":"Cánh tay","hanViet":"UYỂN","lesson":2,"ex":[["腕が痛いです。","Cánh tay tôi đau."],["腕を上げてください。","Hãy giơ cánh tay lên."],["彼は腕が長いです。","Anh ấy có cánh tay dài."],["腕に時計をしています。","Tôi đang đeo đồng hồ trên tay."],["子どもは母の腕を持ちました。","Đứa trẻ nắm lấy cánh tay mẹ."]]},{"word":"ふるさと","reading":"ふるさと","meaning":"Quê nhà","hanViet":"","lesson":2,"ex":[["ふるさとはどこですか。","Quê nhà của bạn ở đâu?"],["私のふるさとは小さい町です。","Quê nhà của tôi là một thị trấn nhỏ."],["ふるさとに帰りたいです。","Tôi muốn về quê nhà."],["ふるさとの食べ物が食べたいです。","Tôi muốn ăn món ăn quê nhà."],["ふるさとの友達に会いました。","Tôi đã gặp bạn ở quê nhà."]]},{"word":"話しかける","reading":"はなしかける","meaning":"Nói với, bắt chuyện","hanViet":"THOẠI","lesson":2,"ex":[["知らない人に話しかけました。","Tôi đã bắt chuyện với người lạ."],["先生に話しかけるのは難しいです。","Bắt chuyện với thầy thì khó."],["友達が私に話しかけました。","Bạn đã bắt chuyện với tôi."],["日本語で話しかけてください。","Hãy bắt chuyện bằng tiếng Nhật."],["話しかけても、彼は答えませんでした。","Dù tôi bắt chuyện, anh ấy vẫn không trả lời."]]},{"word":"不在連絡票","reading":"ふざいれんらくひょう","meaning":"Giấy báo đã ghé chuyển hàng nhưng người nhận vắng nhà.","hanViet":"BẤT TẠI LIÊN LẠC PHIẾU","lesson":2,"ex":[["不在連絡票がポストに入っていました。","Giấy báo vắng nhà đã được bỏ vào hộp thư."],["不在連絡票を見て、電話しました。","Tôi đã xem giấy báo vắng nhà rồi gọi điện."],["不在連絡票には電話番号が書いてあります。","Trên giấy báo vắng nhà có ghi số điện thoại."],["不在連絡票をもらいました。","Tôi đã nhận được giấy báo vắng nhà."],["不在連絡票を見て、もう一度来てもらいました。","Tôi đã xem giấy báo vắng nhà và nhờ họ đến lại lần nữa."]]},{"word":"～宅","reading":"～たく","meaning":"Nhà","hanViet":"TRẠCH","lesson":2,"ex":[["田中宅に行きました。","Tôi đã đến nhà Tanaka."],["山田宅でパーティーがありました。","Ở nhà Yamada đã có bữa tiệc."],["田中宅に電話をかけました。","Tôi đã gọi điện đến nhà Tanaka."],["山田宅の近くに公園があります。","Gần nhà Yamada có công viên."],["田中宅へ手紙を送ります。","Tôi gửi thư đến nhà Tanaka."]]},{"word":"工事","reading":"こうじ","meaning":"Thi công","hanViet":"CÔNG SỰ","lesson":2,"ex":[["工事が始まりました。","Việc thi công đã bắt đầu."],["駅の前で工事をしています。","Họ đang thi công trước ga."],["工事のために、道が通れません。","Vì thi công nên đường không đi được."],["工事はいつ終わりますか。","Thi công khi nào xong?"],["工事の音がうるさいです。","Tiếng thi công ồn ào."]]},{"word":"休日","reading":"きゅうじつ","meaning":"Ngày nghỉ","hanViet":"HƯU NHẬT","lesson":2,"ex":[["休日は家で休みます。","Ngày nghỉ tôi nghỉ ngơi ở nhà."],["休日に友達と会います。","Ngày nghỉ tôi gặp bạn bè."],["次の休日は何をしますか。","Ngày nghỉ tới bạn làm gì?"],["休日はゆっくりします。","Ngày nghỉ tôi thư giãn."],["休日が楽しみです。","Tôi mong chờ ngày nghỉ."]]},{"word":"断水","reading":"だんすい","meaning":"Mất nước","hanViet":"ĐOẠN THỦY","lesson":2,"ex":[["今日は断水です。","Hôm nay bị mất nước."],["断水のために、水が使えません。","Vì mất nước nên không dùng được nước."],["断水はいつ終わりますか。","Mất nước khi nào hết?"],["断水について、お知らせがありました。","Có thông báo về việc mất nước."],["断水の間、水を買いましょう。","Trong lúc mất nước, hãy mua nước."]]},{"word":"リモコン","reading":"リモコン","meaning":"Cái điều khiển từ xa","hanViet":"","lesson":2,"ex":[["リモコンでテレビをつけます。","Tôi bật tivi bằng điều khiển."],["リモコンがありません。","Không có điều khiển."],["リモコンをなくしました。","Tôi đã làm mất điều khiển."],["リモコンはどこですか。","Điều khiển ở đâu?"],["リモコンでエアコンをつけました。","Tôi đã bật điều hòa bằng điều khiển."]]},{"word":"ロボコン","reading":"ロボコン","meaning":"Cuộc thi rô bốt","hanViet":"","lesson":2,"ex":[["ロボコンに出ました。","Tôi đã tham gia cuộc thi rô bốt."],["ロボコンで優勝しました。","Tôi đã thắng cuộc thi rô bốt."],["ロボコンを見ました。","Tôi đã xem cuộc thi rô bốt."],["ロボコンのロボットを作っています。","Tôi đang làm rô bốt cho cuộc thi rô bốt."],["ロボコンは来月あります。","Cuộc thi rô bốt diễn ra tháng tới."]]},{"word":"苦手","reading":"にがて","meaning":"Kém, không giỏi","hanViet":"KHỔ THỦ","lesson":2,"ex":[["私は歌が苦手です。","Tôi kém hát."],["英語は苦手です。","Tôi kém tiếng Anh."],["苦手な食べ物がありますか。","Bạn có món ăn nào không thích không?"],["彼はスポーツが苦手です。","Anh ấy kém thể thao."],["苦手なことを練習しています。","Tôi đang luyện tập những điều mình kém."]]},{"word":"紛らわしい","reading":"まぎらわしい","meaning":"Không rõ ràng, gây bối rối","hanViet":"PHÂN","lesson":2,"ex":[["この二つの言葉は紛らわしいです。","Hai từ này gây bối rối."],["紛らわしい漢字が多いです。","Có nhiều chữ Hán dễ nhầm."],["あの二人は紛らわしいです。","Hai người đó dễ gây nhầm lẫn."],["紛らわしい説明でした。","Đó là lời giải thích gây bối rối."],["紛らわしいので、気をつけてください。","Vì dễ nhầm lẫn nên hãy cẩn thận."]]},{"word":"正確","reading":"せいかく","meaning":"Chính xác","hanViet":"CHÍNH XÁC","lesson":2,"ex":[["正確な時間を知りたいです。","Tôi muốn biết thời gian chính xác."],["彼の答えは正確です。","Câu trả lời của anh ấy chính xác."],["正確に答えてください。","Hãy trả lời chính xác."],["正確な情報を教えてください。","Hãy cho tôi thông tin chính xác."],["この時計は正確です。","Chiếc đồng hồ này chính xác."]]},{"word":"バランス","reading":"バランス","meaning":"Cân bằng","hanViet":"","lesson":2,"ex":[["バランスが大切です。","Cân bằng là quan trọng."],["食事のバランスを考えます。","Tôi cân nhắc sự cân bằng của bữa ăn."],["バランスをとるのは難しいです。","Giữ cân bằng thì khó."],["仕事と生活のバランスがいいです。","Cân bằng giữa công việc và cuộc sống tốt."],["バランスのいい食事をしましょう。","Hãy ăn bữa ăn cân bằng."]]},{"word":"引く","reading":"ひく","meaning":"Kéo; (線を引く) kẻ một đường","hanViet":"DẪN","lesson":2,"ex":[["線を引きました。","Tôi đã kẻ một đường."],["ドアを引いてください。","Hãy kéo cửa."],["彼は私の手を引いて歩きました。","Anh ấy nắm tay tôi kéo đi."],["カーテンを引きました。","Tôi đã kéo rèm."],["線を引くのが下手です。","Tôi kẻ đường kém."]]},{"word":"筆者","reading":"ひっしゃ","meaning":"Tác giả của một bài viết","hanViet":"BÚT GIẢ","lesson":2,"ex":[["筆者は日本人です。","Tác giả là người Nhật."],["筆者の意見に賛成です。","Tôi đồng ý với ý kiến của tác giả."],["筆者はこの本で何を言いたいですか。","Tác giả muốn nói gì trong cuốn sách này?"],["筆者について調べました。","Tôi đã tìm hiểu về tác giả."],["筆者の考えが分かりません。","Tôi không hiểu suy nghĩ của tác giả."]]},{"word":"いまだに","reading":"いまだに","meaning":"Bây giờ vẫn","hanViet":"","lesson":2,"ex":[["いまだに日本語が話せません。","Đến bây giờ tôi vẫn chưa nói được tiếng Nhật."],["いまだに彼は来ません。","Đến bây giờ anh ấy vẫn chưa đến."],["いまだにその本を読んでいます。","Đến bây giờ tôi vẫn đang đọc cuốn sách đó."],["いまだに覚えています。","Đến bây giờ tôi vẫn còn nhớ."],["いまだに雨が降っています。","Đến bây giờ trời vẫn đang mưa."]]},{"word":"とんでもない","reading":"とんでもない","meaning":"Chẳng ra sao cả","hanViet":"","lesson":2,"ex":[["とんでもないことを言いました。","Anh ấy đã nói điều chẳng ra sao cả."],["とんでもない間違いをしました。","Tôi đã mắc lỗi chẳng ra sao cả."],["それはとんでもない話です。","Đó là câu chuyện chẳng ra sao cả."],["とんでもないことが起きました。","Đã xảy ra chuyện chẳng ra sao cả."],["とんでもない値段です。","Đó là mức giá chẳng ra sao cả."]]},{"word":"宇宙人","reading":"うちゅうじん","meaning":"Người ngoài trái đất","hanViet":"VŨ TRỤ NHÂN","lesson":2,"ex":[["宇宙人はいますか。","Có người ngoài hành tinh không?"],["宇宙人を見たことがありますか。","Bạn đã từng thấy người ngoài hành tinh chưa?"],["宇宙人について話しました。","Tôi đã nói về người ngoài hành tinh."],["彼は宇宙人のようです。","Anh ấy trông như người ngoài hành tinh."],["宇宙人の映画を見ました。","Tôi đã xem phim về người ngoài hành tinh."]]},{"word":"全く","reading":"まったく","meaning":"Hoàn toàn","hanViet":"TOÀN","lesson":2,"ex":[["全く分かりません。","Tôi hoàn toàn không hiểu."],["全く違います。","Hoàn toàn khác."],["全く知りませんでした。","Tôi hoàn toàn không biết."],["全く同じです。","Hoàn toàn giống nhau."],["全く問題ありません。","Hoàn toàn không có vấn đề."]]},{"word":"別の","reading":"べつの","meaning":"Khác","hanViet":"BIỆT","lesson":2,"ex":[["別の本を読みたいです。","Tôi muốn đọc cuốn sách khác."],["別の日に来てください。","Hãy đến vào ngày khác."],["別の方法がありますか。","Có cách khác không?"],["別の人と話しました。","Tôi đã nói chuyện với người khác."],["別の部屋に行きました。","Tôi đã đi sang phòng khác."]]},{"word":"～自身","reading":"～じしん","meaning":"Tự mình, chính mình","hanViet":"TỰ THÂN","lesson":2,"ex":[["私自身がやります。","Chính tôi sẽ làm."],["彼自身は来ませんでした。","Chính anh ấy đã không đến."],["自分自身を信じてください。","Hãy tin vào chính bản thân mình."],["先生自身が説明しました。","Chính thầy đã giải thích."],["彼女自身が決めました。","Chính cô ấy đã quyết định."]]},{"word":"友人","reading":"ゆうじん","meaning":"Bạn thân","hanViet":"HỮU NHÂN","lesson":2,"ex":[["友人と会いました。","Tôi đã gặp bạn thân."],["友人に手紙を書きました。","Tôi đã viết thư cho bạn thân."],["友人が東京に住んでいます。","Bạn thân của tôi sống ở Tokyo."],["友人からプレゼントをもらいました。","Tôi đã nhận quà từ bạn thân."],["友人と一緒に旅行しました。","Tôi đã đi du lịch cùng bạn thân."]]},{"word":"また","reading":"また","meaning":"Hơn nữa, vả lại","hanViet":"","lesson":2,"ex":[["日本語が好きです。また、英語も好きです。","Tôi thích tiếng Nhật. Hơn nữa, tôi cũng thích tiếng Anh."],["彼は歌が上手です。また、ダンスも上手です。","Anh ấy hát hay. Hơn nữa, nhảy cũng giỏi."],["この店は安いです。また、おいしいです。","Cửa hàng này rẻ. Hơn nữa, còn ngon."],["雨が降っています。また、風も強いです。","Trời đang mưa. Hơn nữa, gió cũng mạnh."],["彼女は優しいです。また、頭もいいです。","Cô ấy dịu dàng. Hơn nữa, còn thông minh."]]},{"word":"ライス","reading":"ライス","meaning":"Cơm","hanViet":"","lesson":2,"ex":[["ライスをください。","Cho tôi cơm."],["ライスとパンを食べました。","Tôi đã ăn cơm và bánh mì."],["ライスが好きです。","Tôi thích cơm."],["ライスをもう少しください。","Cho tôi thêm chút cơm nữa."],["ライスはおいしいです。","Cơm ngon."]]},{"word":"アドレス","reading":"アドレス","meaning":"Địa chỉ","hanViet":"","lesson":2,"ex":[["アドレスを教えてください。","Hãy cho tôi biết địa chỉ."],["新しいアドレスに引っ越しました。","Tôi đã chuyển đến địa chỉ mới."],["アドレスを間違えました。","Tôi đã nhầm địa chỉ."],["アドレスが変わりました。","Địa chỉ đã thay đổi."],["アドレスを書いてください。","Hãy viết địa chỉ."]]},{"word":"メールアドレス","reading":"メールアドレス","meaning":"Địa chỉ email","hanViet":"","lesson":2,"ex":[["メールアドレスを教えてください。","Hãy cho tôi biết địa chỉ email."],["メールアドレスが変わりました。","Địa chỉ email đã thay đổi."],["メールアドレスを間違えました。","Tôi đã nhầm địa chỉ email."],["新しいメールアドレスを作りました。","Tôi đã tạo địa chỉ email mới."],["メールアドレスを書いてください。","Hãy viết địa chỉ email."]]},{"word":"プレゼン","reading":"プレゼン","meaning":"Bài thuyết trình","hanViet":"","lesson":2,"ex":[["プレゼンをしました。","Tôi đã thuyết trình."],["プレゼンの準備をしています。","Tôi đang chuẩn bị bài thuyết trình."],["プレゼンがうまくいきました。","Bài thuyết trình đã diễn ra tốt đẹp."],["明日、プレゼンがあります。","Ngày mai có bài thuyết trình."],["プレゼンについて話し合いました。","Chúng tôi đã thảo luận về bài thuyết trình."]]},{"word":"アイデンティティ","reading":"アイデンティティ","meaning":"Bản sắc, đặc điểm","hanViet":"","lesson":2,"ex":[["アイデンティティについて考えています。","Tôi đang suy nghĩ về bản sắc."],["自分のアイデンティティが大切です。","Bản sắc của bản thân rất quan trọng."],["アイデンティティを守りたいです。","Tôi muốn bảo vệ bản sắc của mình."],["日本人のアイデンティティについて話しました。","Tôi đã nói về bản sắc của người Nhật."],["アイデンティティはどこから来ますか。","Bản sắc đến từ đâu?"]]},{"word":"コンプライアンス","reading":"コンプライアンス","meaning":"Sự tuân thủ luật, làm đúng luật","hanViet":"","lesson":2,"ex":[["コンプライアンスが大切です。","Tuân thủ luật pháp là quan trọng."],["コンプライアンスについて勉強しています。","Tôi đang học về tuân thủ luật pháp."],["会社はコンプライアンスを守ります。","Công ty tuân thủ luật pháp."],["コンプライアンスの規則があります。","Có quy tắc về tuân thủ luật pháp."],["コンプライアンスについて話しました。","Tôi đã nói về tuân thủ luật pháp."]]},{"word":"例えば","reading":"たとえば","meaning":"Ví dụ","hanViet":"LỆ","lesson":2,"ex":[["例えば、東京は大きいです。","Ví dụ, Tokyo rất lớn."],["例えば、日本語を勉強します。","Ví dụ, tôi học tiếng Nhật."],["例えば、この本を読んでください。","Ví dụ, hãy đọc cuốn sách này."],["例えば、彼は歌が上手です。","Ví dụ, anh ấy hát hay."],["例えば、明日は休みです。","Ví dụ, ngày mai là ngày nghỉ."]]},{"word":"ポリシー","reading":"ポリシー","meaning":"Nguyên tắc, chính sách","hanViet":"","lesson":2,"ex":[["会社のポリシーがあります。","Công ty có chính sách."],["ポリシーについて話しました。","Tôi đã nói về chính sách."],["ポリシーを守らなければなりません。","Phải tuân thủ chính sách."],["新しいポリシーができました。","Đã có chính sách mới."],["ポリシーが変わりました。","Chính sách đã thay đổi."]]},{"word":"場合","reading":"ばあい","meaning":"Trường hợp","hanViet":"TRÀNG HỢP/TRƯỜNG HỢP","lesson":2,"ex":[["雨の場合は、家にいます。","Trong trường hợp trời mưa, tôi ở nhà."],["分からない場合は、先生に聞いてください。","Trong trường hợp không hiểu, hãy hỏi thầy."],["その場合は、電話してください。","Trong trường hợp đó, hãy gọi điện."],["困った場合は、私に連絡してください。","Trong trường hợp gặp khó khăn, hãy liên lạc với tôi."],["忙しい場合は、明日でもいいです。","Trong trường hợp bận, ngày mai cũng được."]]},{"word":"％","reading":"パーセント","meaning":"Tỷ lệ phần trăm","hanViet":"","lesson":2,"ex":[["十％引きです。","Giảm giá 10%."],["五％の人が来ました。","5% số người đã đến."],["この店は二十％安いです。","Cửa hàng này rẻ hơn 20%."],["百％分かりました。","Tôi đã hiểu 100%."],["三十％の学生が日本人です。","30% học sinh là người Nhật."]]},{"word":"普通に","reading":"ふつうに","meaning":"Bình thường","hanViet":"PHỔ THÔNG","lesson":2,"ex":[["普通に話してください。","Hãy nói bình thường."],["普通に食べます。","Tôi ăn bình thường."],["普通に歩いて十分かかります。","Đi bộ bình thường mất mười phút."],["普通に生活しています。","Tôi sống bình thường."],["普通に考えてください。","Hãy suy nghĩ bình thường."]]},{"word":"いまさら","reading":"いまさら","meaning":"Đến lúc này thì sự việc đã muộn","hanViet":"","lesson":2,"ex":[["いまさら、言っても遅いです。","Đến lúc này nói cũng đã muộn."],["いまさら、謝ってもだめです。","Đến lúc này xin lỗi cũng vô ích."],["いまさら、勉強しても間に合いません。","Đến lúc này học cũng không kịp nữa."],["いまさら、行きたくありません。","Đến lúc này tôi không muốn đi nữa."],["いまさら、やめても遅いです。","Đến lúc này dừng lại cũng đã muộn."]]},{"word":"必要","reading":"ひつよう","meaning":"Sự cần thiết","hanViet":"TẤT YẾU","lesson":2,"ex":[["必要な物がありますか。","Bạn có đồ cần thiết nào không?"],["お金が必要です。","Cần tiền."],["勉強は必要です。","Học tập là cần thiết."],["必要なとき、電話してください。","Khi cần, hãy gọi điện."],["パスポートが必要です。","Cần hộ chiếu."]]},{"word":"なくてはならない","reading":"なくてはならない","meaning":"Không thể thiếu, không thể không có","hanViet":"","lesson":2,"ex":[["水はなくてはならないものです。","Nước là thứ không thể thiếu."],["家族はなくてはなりません。","Gia đình là không thể thiếu."],["日本語は私になくてはなりません。","Tiếng Nhật là không thể thiếu đối với tôi."],["電気は生活になくてはなりません。","Điện là không thể thiếu trong cuộc sống."],["友達はなくてはならないものです。","Bạn bè là thứ không thể thiếu."]]},{"word":"文章","reading":"ぶんしょう","meaning":"Bài văn","hanViet":"VĂN CHƯƠNG","lesson":2,"ex":[["文章を書きました。","Tôi đã viết bài văn."],["文章を読んでください。","Hãy đọc bài văn."],["この文章は分かりやすいです。","Bài văn này dễ hiểu."],["文章の意味が分かりません。","Tôi không hiểu ý nghĩa của bài văn."],["日本語で文章を書くのは難しいです。","Viết bài văn bằng tiếng Nhật thì khó."]]},{"word":"比べる","reading":"くらべる","meaning":"So sánh","hanViet":"BỈ/TỈ","lesson":2,"ex":[["二つの本を比べます。","Tôi so sánh hai cuốn sách."],["日本とベトナムを比べました。","Tôi đã so sánh Nhật Bản và Việt Nam."],["値段を比べて、安い方を買います。","Tôi so sánh giá rồi mua cái rẻ hơn."],["昔と今を比べると、生活が変わりました。","So sánh xưa và nay, cuộc sống đã thay đổi."],["二人の歌を比べました。","Tôi đã so sánh giọng hát của hai người."]]},{"word":"インタビューする","reading":"インタビューする","meaning":"Phỏng vấn","hanViet":"","lesson":3,"ex":[["先生をインタビューしました。","Tôi đã phỏng vấn thầy."],["有名人をインタビューしたいです。","Tôi muốn phỏng vấn người nổi tiếng."],["インタビューする時間が必要です。","Cần thời gian để phỏng vấn."],["彼女をインタビューしました。","Tôi đã phỏng vấn cô ấy."],["インタビューしたことを書きました。","Tôi đã viết những điều đã phỏng vấn."]]},{"word":"担当する","reading":"たんとうする","meaning":"Phụ trách, chịu trách nhiệm","hanViet":"ĐẢM ĐƯƠNG","lesson":3,"ex":[["私は日本語を担当しています。","Tôi phụ trách tiếng Nhật."],["彼がこの仕事を担当します。","Anh ấy phụ trách công việc này."],["担当する人が分かりません。","Tôi không biết người phụ trách."],["だれが担当しますか。","Ai phụ trách?"],["先生がクラスを担当しています。","Thầy phụ trách lớp học."]]},{"word":"アルバイト先","reading":"アルバイトさき","meaning":"Chỗ làm thêm","hanViet":"TIÊN","lesson":3,"ex":[["アルバイト先はレストランです。","Chỗ làm thêm của tôi là nhà hàng."],["アルバイト先で友達ができました。","Tôi đã có bạn ở chỗ làm thêm."],["アルバイト先が遠いです。","Chỗ làm thêm xa."],["アルバイト先の人は優しいです。","Người ở chỗ làm thêm dịu dàng."],["アルバイト先に電話しました。","Tôi đã gọi điện đến chỗ làm thêm."]]},{"word":"～先","reading":"～さき","meaning":"Chỗ, nơi","hanViet":"TIÊN","lesson":3,"ex":[["旅行先は京都です。","Nơi du lịch là Kyoto."],["仕事先が東京です。","Nơi làm việc là Tokyo."],["留学先は日本です。","Nơi du học là Nhật Bản."],["旅行先で写真を撮りました。","Tôi đã chụp ảnh ở nơi du lịch."],["仕事先の人に会いました。","Tôi đã gặp người ở nơi làm việc."]]},{"word":"店長","reading":"てんちょう","meaning":"Cửa hàng trưởng","hanViet":"ĐIẾM TRƯỜNG","lesson":3,"ex":[["店長は毎朝早く店に来ます。","Cửa hàng trưởng mỗi sáng đến cửa hàng sớm."],["新しい店長はとてもやさしい人です。","Cửa hàng trưởng mới là người rất hiền."],["店長に仕事のことを話しました。","Tôi đã nói với cửa hàng trưởng về công việc."],["店長が休みの日は私が店を閉めます。","Vào ngày cửa hàng trưởng nghỉ, tôi đóng cửa hàng."],["店長になってから、仕事が忙しくなりました。","Từ khi trở thành cửa hàng trưởng, công việc trở nên bận rộn."]]},{"word":"研修","reading":"けんしゅう","meaning":"Đào tạo","hanViet":"NGHIÊN TU","lesson":3,"ex":[["新しい社員は一か月研修を受けます。","Nhân viên mới tham gia đào tạo một tháng."],["研修で日本語の敬語を勉強しました。","Trong khóa đào tạo, tôi đã học kính ngữ tiếng Nhật."],["来週から大阪で研修があります。","Từ tuần sau có khóa đào tạo ở Osaka."],["研修の先生はとても親切でした。","Thầy giáo của khóa đào tạo rất tốt bụng."],["研修が終わったら、東京の店で働きます。","Sau khi đào tạo xong, tôi sẽ làm việc ở cửa hàng tại Tokyo."]]},{"word":"話し合う","reading":"はなしあう","meaning":"Thảo luận, trao đổi ý kiến với nhau","hanViet":"THOẠI HỢP","lesson":3,"ex":[["友達と将来のことを話し合いました。","Tôi đã thảo luận với bạn về chuyện tương lai."],["家族で引っ越しについて話し合います。","Gia đình tôi sẽ thảo luận về việc chuyển nhà."],["先生と学生がクラスの問題を話し合いました。","Thầy giáo và sinh viên đã thảo luận vấn đề của lớp."],["大切なことは二人でよく話し合うべきです。","Chuyện quan trọng nên hai người thảo luận kỹ với nhau."],["会議の前に、まず二人で話し合いましょう。","Trước cuộc họp, trước hết hai người chúng ta hãy thảo luận nhé."]]},{"word":"通勤する","reading":"つうきんする","meaning":"Đi làm","hanViet":"THÔNG CẦN","lesson":3,"ex":[["私は電車で会社に通勤しています。","Tôi đi làm đến công ty bằng tàu điện."],["通勤する時間は一時間ぐらいです。","Thời gian đi làm khoảng một giờ."],["母は自転車で通勤しています。","Mẹ tôi đi làm bằng xe đạp."],["新しい家から会社まで通勤するのは楽です。","Đi làm từ nhà mới đến công ty rất tiện."],["雨の日は通勤するのが大変です。","Vào ngày mưa, việc đi làm rất vất vả."]]},{"word":"これまで","reading":"これまで","meaning":"Cho đến nay","hanViet":"","lesson":3,"ex":[["これまで日本語を三年勉強しています。","Cho đến nay tôi đã học tiếng Nhật ba năm."],["これまで一度も外国へ行ったことがありません。","Cho đến nay tôi chưa từng đi nước ngoài lần nào."],["これまで私は一人で住んでいました。","Cho đến nay tôi đã sống một mình."],["これまで読んだ本の中で、この本が一番おもしろいです。","Trong những cuốn sách đã đọc cho đến nay, cuốn này thú vị nhất."],["これまでありがとうございました。","Cảm ơn bạn cho đến nay."]]},{"word":"減らす","reading":"へらす","meaning":"Giảm","hanViet":"GIẢM","lesson":3,"ex":[["健康のために、ごはんの量を減らします。","Vì sức khỏe, tôi sẽ giảm lượng cơm."],["毎日お酒を少し減らしています。","Mỗi ngày tôi giảm rượu một chút."],["会社は今年、社員の数を減らしました。","Năm nay công ty đã giảm số nhân viên."],["ごみを減らすために、買い物に袋を持って行きます。","Để giảm rác, tôi mang túi khi đi mua sắm."],["仕事の時間を減らして、家族と過ごす時間を増やします。","Tôi giảm giờ làm việc và tăng thời gian ở bên gia đình."]]},{"word":"引っ越す","reading":"ひっこす","meaning":"Chuyển nhà","hanViet":"DẪN VIỆT","lesson":3,"ex":[["来月、東京に引っ越します。","Tháng sau tôi sẽ chuyển nhà đến Tokyo."],["会社に近くなったので、引っ越すことにしました。","Vì muốn gần công ty hơn nên tôi đã quyết định chuyển nhà."],["引っ越す前に、荷物をまとめなければなりません。","Trước khi chuyển nhà, tôi phải thu dọn hành lý."],["去年、大阪から京都に引っ越しました。","Năm ngoái tôi đã chuyển nhà từ Osaka đến Kyoto."],["新しい家に引っ越してから、通勤が楽になりました。","Từ khi chuyển đến nhà mới, việc đi làm trở nên thuận tiện hơn."]]},{"word":"～か国","reading":"～かこく","meaning":"Số nước","hanViet":"QUỐC","lesson":3,"ex":[["私はこれまでに五か国へ旅行しました。","Cho đến nay tôi đã đi du lịch năm nước."],["その会社は十か国に店があります。","Công ty đó có cửa hàng ở mười nước."],["三か国の言葉が話せますか。","Bạn có nói được tiếng của ba nước không?"],["二か国の料理を比べてみました。","Tôi đã thử so sánh món ăn của hai nước."],["何か国に行ったことがありますか。","Bạn đã từng đi bao nhiêu nước rồi?"]]},{"word":"家庭","reading":"かてい","meaning":"Gia đình","hanViet":"GIA ĐÌNH","lesson":3,"ex":[["私の家庭は五人家族です。","Gia đình tôi có năm người."],["家庭で日本語を話す練習をします。","Tôi luyện nói tiếng Nhật ở nhà."],["家庭の事情で、仕事をやめました。","Vì hoàn cảnh gia đình, tôi đã nghỉ việc."],["幸せな家庭を作りたいです。","Tôi muốn xây dựng một gia đình hạnh phúc."],["子どもの家庭での生活も大切です。","Cuộc sống ở nhà của trẻ em cũng quan trọng."]]},{"word":"事情","reading":"じじょう","meaning":"Hoàn cảnh, lý do","hanViet":"SỰ TÌNH","lesson":3,"ex":[["家庭の事情で、大学をやめました。","Vì hoàn cảnh gia đình, tôi đã nghỉ đại học."],["事情を話してくれれば、手伝います。","Nếu bạn kể cho tôi hoàn cảnh, tôi sẽ giúp."],["その事情はまだだれにも話していません。","Hoàn cảnh đó tôi chưa kể cho ai cả."],["仕事の事情で、来週は休めません。","Vì lý do công việc, tuần sau tôi không thể nghỉ."],["事情が変わったら、また連絡してください。","Nếu hoàn cảnh thay đổi, hãy liên lạc lại với tôi."]]},{"word":"幼稚園","reading":"ようちえん","meaning":"Trường mẫu giáo","hanViet":"ẤU TRĨ VIÊN","lesson":3,"ex":[["妹は幼稚園に通っています。","Em gái tôi đang học ở trường mẫu giáo."],["幼稚園の子どもたちは元気に遊んでいます。","Các em nhỏ ở trường mẫu giáo đang chơi đùa vui vẻ."],["私は幼稚園の先生になりたいです。","Tôi muốn trở thành giáo viên trường mẫu giáo."],["幼稚園の近くに大きな公園があります。","Gần trường mẫu giáo có một công viên lớn."],["子どもが幼稚園に入る前に、いろいろ準備します。","Trước khi con vào trường mẫu giáo, tôi chuẩn bị nhiều thứ."]]},{"word":"昼寝する","reading":"ひるねする","meaning":"Ngủ trưa","hanViet":"TRÚ TẨM","lesson":3,"ex":[["休みの日は昼寝することがあります。","Vào ngày nghỉ, thỉnh thoảng tôi ngủ trưa."],["昼寝をしてから、勉強を始めます。","Sau khi ngủ trưa, tôi bắt đầu học."],["子どもは昼寝する時間が決まっています。","Trẻ em có giờ ngủ trưa cố định."],["昼寝をしすぎると、夜眠れなくなります。","Nếu ngủ trưa quá nhiều, buổi tối sẽ không ngủ được."],["短い昼寝のあとは元気になります。","Sau giấc ngủ trưa ngắn, tôi trở nên khỏe khoắn."]]},{"word":"帰国する","reading":"きこくする","meaning":"Về nước","hanViet":"QUY QUỐC","lesson":3,"ex":[["来年、ベトナムに帰国するつもりです。","Năm sau tôi dự định về nước Việt Nam."],["父は来月帰国します。","Bố tôi sẽ về nước vào tháng sau."],["帰国する前に、友達に会いたいです。","Trước khi về nước, tôi muốn gặp bạn bè."],["帰国してから、日本語の先生になりました。","Sau khi về nước, tôi đã trở thành giáo viên tiếng Nhật."],["飛行機の時間に合わせて、帰国する日を決めました。","Tôi đã quyết định ngày về nước theo giờ bay."]]},{"word":"来社","reading":"らいしゃ","meaning":"Đến thăm công ty, văn phòng","hanViet":"LAI XÃ","lesson":3,"ex":[["明日、取引先の人が来社します。","Ngày mai, người của đối tác sẽ đến thăm công ty."],["来社の時間は十時です。","Thời gian đến thăm công ty là mười giờ."],["お客様の来社に合わせて、会議室を準備しました。","Tôi đã chuẩn bị phòng họp theo lịch đến thăm công ty của khách hàng."],["来社する前に、電話で連絡してください。","Trước khi đến thăm công ty, hãy liên lạc bằng điện thoại."],["社長は来社したお客様と話しました。","Giám đốc đã nói chuyện với khách đến thăm công ty."]]},{"word":"新製品","reading":"しんせいひん","meaning":"Sản phẩm mới","hanViet":"TÂN CHẾ PHẨM","lesson":3,"ex":[["会社は今月、新製品を発表しました。","Tháng này công ty đã ra mắt sản phẩm mới."],["新製品の説明を聞きました。","Tôi đã nghe giải thích về sản phẩm mới."],["この新製品はとても便利です。","Sản phẩm mới này rất tiện lợi."],["新製品を買う人が増えています。","Số người mua sản phẩm mới đang tăng lên."],["新製品について、アンケートに答えました。","Tôi đã trả lời phiếu điều tra về sản phẩm mới."]]},{"word":"新～","reading":"しん～","meaning":"～ mới","hanViet":"TÂN","lesson":3,"ex":[["新幹線で東京へ行きます。","Tôi đi Tokyo bằng tàu Shinkansen."],["新年会で友達と会いました。","Tôi đã gặp bạn bè ở tiệc đầu năm mới."],["毎朝、新聞を読みます。","Mỗi sáng tôi đọc báo."],["新製品の発表会に行きました。","Tôi đã đi dự buổi ra mắt sản phẩm mới."],["会社は新製品を作るために、新しい工場を建てました。","Công ty đã xây nhà máy mới để làm sản phẩm mới."]]},{"word":"発表会","reading":"はっぴょうかい","meaning":"Buổi giới thiệu, ra mắt","hanViet":"PHÁT BIỂU HỘI","lesson":3,"ex":[["来週、学校で発表会があります。","Tuần sau ở trường có buổi giới thiệu."],["発表会で自分の国について話しました。","Ở buổi giới thiệu, tôi đã nói về đất nước của mình."],["新製品の発表会に多くの人が来ました。","Nhiều người đã đến buổi ra mắt sản phẩm mới."],["発表会の前に、何回も練習しました。","Trước buổi giới thiệu, tôi đã luyện tập nhiều lần."],["子どもの発表会を見に行きます。","Tôi đi xem buổi biểu diễn của con."]]},{"word":"いつまでも","reading":"いつまでも","meaning":"Mãi","hanViet":"","lesson":3,"ex":[["いつまでも元気でいてください。","Hãy luôn khỏe mạnh nhé."],["この美しい景色をいつまでも忘れません。","Tôi sẽ không bao giờ quên phong cảnh đẹp này."],["いつまでも友達でいましょう。","Hãy mãi là bạn bè nhé."],["先生の言葉はいつまでも忘れません。","Tôi sẽ không bao giờ quên lời của thầy giáo."],["いつまでもここにいるわけにはいきません。","Tôi không thể ở đây mãi được."]]},{"word":"景気","reading":"けいき","meaning":"Tình trạng nền kinh tế, tình trạng kinh doanh","hanViet":"CẢNH KHÍ","lesson":3,"ex":[["最近、景気がよくなってきました。","Gần đây tình hình kinh tế đã tốt lên."],["景気が悪いので、会社は社員を増やしません。","Vì kinh tế xấu nên công ty không tăng nhân viên."],["日本の景気について新聞で読みました。","Tôi đã đọc trên báo về tình hình kinh tế Nhật Bản."],["景気がよくなれば、給料も上がるでしょう。","Nếu kinh tế tốt lên, lương cũng sẽ tăng."],["景気の話を友達としました。","Tôi đã nói chuyện với bạn về tình hình kinh tế."]]},{"word":"これ以上","reading":"これいじょう","meaning":"Hơn thế này nữa","hanViet":"DĨ THƯỢNG","lesson":3,"ex":[["これ以上待てません。","Tôi không thể đợi hơn thế này nữa."],["これ以上高くなると、買えません。","Nếu đắt hơn thế này nữa thì tôi không mua được."],["これ以上は話したくありません。","Tôi không muốn nói hơn thế này nữa."],["これ以上勉強しても、今日はもう頭に入りません。","Học hơn thế này nữa thì hôm nay đầu óc cũng không tiếp thu được."],["これ以上遅くなると、電車がありません。","Nếu muộn hơn thế này nữa thì sẽ không còn tàu điện."]]},{"word":"森","reading":"もり","meaning":"Rừng","hanViet":"SÂM","lesson":3,"ex":[["森の中を歩きました。","Tôi đã đi bộ trong rừng."],["この森にはいろいろな動物がいます。","Trong khu rừng này có nhiều loài động vật."],["森の近くに小さい村があります。","Gần rừng có một ngôi làng nhỏ."],["夏は森の中が涼しいです。","Vào mùa hè, trong rừng rất mát."],["森で鳥の声が聞こえました。","Trong rừng tôi đã nghe thấy tiếng chim."]]},{"word":"声","reading":"こえ","meaning":"Tiếng nói, ý kiến của người dân","hanViet":"THANH","lesson":3,"ex":[["先生の声がよく聞こえます。","Tôi nghe rõ giọng của thầy giáo."],["大きな声で名前を呼びました。","Tôi đã gọi tên bằng giọng lớn."],["子どもの声が外から聞こえてきます。","Tiếng trẻ em vọng lại từ bên ngoài."],["会議で自分の声を出すことが大切です。","Trong cuộc họp, việc nói lên ý kiến của mình rất quan trọng."],["声が小さいので、もっと大きな声で話してください。","Vì giọng nhỏ nên hãy nói to hơn."]]},{"word":"受ける","reading":"うける","meaning":"Nhận; dự thi; chịu (kiểm tra, phỏng vấn)","hanViet":"THỤ","lesson":3,"ex":[["来月、日本語の試験を受けます。","Tháng sau tôi sẽ dự thi kỳ thi tiếng Nhật."],["会社でインタビューを受けました。","Tôi đã trả lời phỏng vấn ở công ty."],["先生のアドバイスを受けて、作文を直しました。","Nhờ lời khuyên của thầy giáo, tôi đã sửa bài văn."],["病院で検査を受けました。","Tôi đã kiểm tra ở bệnh viện."],["友達からプレゼントを受けました。","Tôi đã nhận quà từ bạn."]]},{"word":"要望","reading":"ようぼう","meaning":"Yêu cầu, nguyện vọng","hanViet":"YẾU VỌNG","lesson":3,"ex":[["お客様の要望を聞きました。","Tôi đã lắng nghe yêu cầu của khách hàng."],["要望があれば、遠慮なく言ってください。","Nếu có yêu cầu gì, xin cứ nói đừng ngại."],["社員からの要望をまとめました。","Tôi đã tổng hợp các yêu cầu từ nhân viên."],["新製品の要望が多くなりました。","Yêu cầu về sản phẩm mới đã tăng lên."],["要望について、店長と話し合いました。","Tôi đã thảo luận với cửa hàng trưởng về các yêu cầu."]]},{"word":"本当は","reading":"ほんとうは","meaning":"Thực ra","hanViet":"BỔN ĐƯƠNG","lesson":3,"ex":[["本当は、今日は休みたかったです。","Thực ra hôm nay tôi đã muốn nghỉ."],["本当は日本語がまだ上手じゃありません。","Thực ra tiếng Nhật của tôi vẫn chưa giỏi."],["本当はその話を知りませんでした。","Thực ra tôi đã không biết chuyện đó."],["本当はもっと早く来たかったんです。","Thực ra tôi đã muốn đến sớm hơn."],["本当は、彼が好きなんです。","Thực ra tôi thích anh ấy."]]},{"word":"おとなしい","reading":"おとなしい","meaning":"Hiền ngoan","hanViet":"","lesson":3,"ex":[["妹はとてもおとなしい子です。","Em gái tôi là đứa trẻ rất ngoan."],["おとなしい犬が庭にいます。","Có một con chó hiền trong sân."],["彼はおとなしいですが、よく勉強します。","Anh ấy hiền nhưng học rất chăm."],["おとなしい性格の人が好きです。","Tôi thích người có tính cách hiền lành."],["子どもは小さいとき、おとなしかったです。","Hồi nhỏ, con tôi rất ngoan."]]},{"word":"しゃべる","reading":"しゃべる","meaning":"Nói chuyện","hanViet":"","lesson":3,"ex":[["友達と日本語でしゃべります。","Tôi nói chuyện với bạn bằng tiếng Nhật."],["電車の中でしゃべるのはやめましょう。","Hãy thôi nói chuyện trong tàu điện."],["彼女はよくしゃべる人です。","Cô ấy là người hay nói chuyện."],["授業ではしゃべってはいけません。","Không được nói chuyện trong giờ học."],["日本の友達としゃべると、日本語が上手になります。","Nói chuyện với bạn người Nhật giúp tiếng Nhật giỏi lên."]]},{"word":"振る","reading":"ふる","meaning":"Vẫy, lắc (tay); (người yêu) đá, bỏ","hanViet":"CHẤN","lesson":3,"ex":[["駅で友達に手を振りました。","Tôi đã vẫy tay chào bạn ở ga."],["彼女に振られたので、とても悲しかったです。","Vì bị bạn gái đá nên tôi rất buồn."],["ジュースを飲む前に、よく振ってください。","Trước khi uống nước ép, hãy lắc kỹ."],["友達は彼女に振られて、元気がありません。","Bạn tôi bị bạn gái đá nên không có tinh thần."],["子どもは手を振って、笑いました。","Đứa trẻ vẫy tay và cười."]]},{"word":"Tシャツ","reading":"ティーシャツ","meaning":"Áo phông, áo pull","hanViet":"","lesson":3,"ex":[["白いTシャツを買いました。","Tôi đã mua một chiếc áo phông trắng."],["夏はTシャツをよく着ます。","Vào mùa hè tôi thường mặc áo phông."],["このTシャツは安くて着やすいです。","Chiếc áo phông này rẻ và dễ mặc."],["Tシャツを三枚買いました。","Tôi đã mua ba chiếc áo phông."],["友達からTシャツをもらいました。","Tôi đã nhận áo phông từ bạn."]]},{"word":"数","reading":"かず","meaning":"Số","hanViet":"SỐ","lesson":3,"ex":[["学生の数が増えました。","Số học sinh đã tăng lên."],["数の多いクラスはにぎやかです。","Lớp đông người rất nhộn nhịp."],["車の数を数えました。","Tôi đã đếm số xe."],["その数は去年より多いです。","Con số đó nhiều hơn năm ngoái."],["数の問題は難しくありませんでした。","Bài toán về số không khó."]]},{"word":"切る","reading":"きる","meaning":"Cắt, ngắt, cúp điện thoại","hanViet":"THIẾT","lesson":3,"ex":[["はさみで紙を切ります。","Tôi cắt giấy bằng kéo."],["包丁で野菜を切ってください。","Hãy cắt rau bằng dao."],["電話を切る前に、ありがとうと言いました。","Trước khi cúp điện thoại, tôi đã nói cảm ơn."],["ケーキを四つに切ります。","Tôi cắt bánh thành bốn miếng."],["紙を小さく切って、箱に入れました。","Tôi đã cắt nhỏ giấy và bỏ vào hộp."]]},{"word":"秘書","reading":"ひしょ","meaning":"Thư kí","hanViet":"BÍ THƯ","lesson":3,"ex":[["社長の秘書は忙しいです。","Thư ký của giám đốc rất bận."],["秘書が会議の準備をしました。","Thư ký đã chuẩn bị cho cuộc họp."],["私は秘書の仕事をしています。","Tôi đang làm công việc thư ký."],["秘書に電話で連絡しました。","Tôi đã liên lạc với thư ký bằng điện thoại."],["新しい秘書は日本語が上手です。","Thư ký mới giỏi tiếng Nhật."]]},{"word":"教授","reading":"きょうじゅ","meaning":"Giáo sư","hanViet":"GIÁO THỤ","lesson":3,"ex":[["大学の教授に質問しました。","Tôi đã hỏi giáo sư đại học."],["教授の話はとてもおもしろいです。","Câu chuyện của giáo sư rất thú vị."],["その教授は有名な本を書きました。","Giáo sư đó đã viết một cuốn sách nổi tiếng."],["教授は学生と研究しています。","Giáo sư đang nghiên cứu cùng sinh viên."],["教授になるために、たくさん勉強しなければなりません。","Để trở thành giáo sư, tôi phải học rất nhiều."]]},{"word":"わざわざ","reading":"わざわざ","meaning":"Chủ ý, chiếu cố, cố công","hanViet":"","lesson":3,"ex":[["わざわざ来てくれて、ありがとう。","Cảm ơn bạn đã cất công đến."],["遠いのに、わざわざ会いに来ました。","Dù xa nhưng anh ấy đã cố công đến gặp."],["わざわざ電話をくれました。","Anh ấy đã cố công gọi điện cho tôi."],["忙しいのに、わざわざ手伝ってくれました。","Dù bận nhưng anh ấy đã cố công giúp tôi."],["わざわざ買ってきたケーキです。","Đây là bánh tôi đã cất công mua về."]]},{"word":"できれば","reading":"できれば","meaning":"Nếu được, nếu có thể","hanViet":"","lesson":3,"ex":[["できれば、明日来てください。","Nếu được, ngày mai hãy đến."],["できれば、日本語で話したいです。","Nếu có thể, tôi muốn nói bằng tiếng Nhật."],["できれば、安いホテルに泊まりたいです。","Nếu được, tôi muốn ở khách sạn rẻ."],["できれば早く帰りたいです。","Nếu được, tôi muốn về sớm."],["できれば、来週までにレポートを出してください。","Nếu được, hãy nộp báo cáo trước tuần sau."]]},{"word":"変更する","reading":"へんこうする","meaning":"Thay đổi","hanViet":"BIẾN CANH","lesson":3,"ex":[["会議の時間を変更しました。","Tôi đã thay đổi giờ họp."],["予定を変更しなければなりません。","Tôi phải thay đổi kế hoạch."],["旅行の日を変更することができますか。","Tôi có thể thay đổi ngày đi du lịch không?"],["変更する前に、みんなに連絡してください。","Trước khi thay đổi, hãy liên lạc với mọi người."],["予定が変更になったので、友達に連絡しました。","Vì kế hoạch đã thay đổi nên tôi đã liên lạc với bạn."]]},{"word":"急用","reading":"きゅうよう","meaning":"Việc gấp, việc đột xuất","hanViet":"CẤP DỤNG","lesson":3,"ex":[["急用ができたので、早く帰ります。","Vì có việc gấp nên tôi về sớm."],["急用で会議に出席できませんでした。","Vì việc gấp nên tôi đã không thể tham dự cuộc họp."],["急用があれば、電話してください。","Nếu có việc gấp, hãy gọi điện."],["母に急用ができて、家に帰りました。","Mẹ tôi có việc gấp nên đã về nhà."],["急用で、約束を変えなければなりませんでした。","Vì việc gấp nên tôi đã phải thay đổi lời hẹn."]]},{"word":"気にする","reading":"きにする","meaning":"Để tâm, bận tâm","hanViet":"KHÍ","lesson":3,"ex":[["小さいことを気にしないでください。","Xin đừng bận tâm chuyện nhỏ."],["私はあまり人の意見を気にしません。","Tôi không mấy bận tâm ý kiến của người khác."],["彼は失敗を気にしています。","Anh ấy đang bận tâm về thất bại."],["気にしすぎると、疲れます。","Bận tâm quá nhiều sẽ mệt mỏi."],["天気を気にしないで、出かけましょう。","Đừng bận tâm thời tiết, chúng ta hãy ra ngoài."]]},{"word":"取引先","reading":"とりひきさき","meaning":"Khách hàng, đối tác","hanViet":"THỦ DẪN TIÊN","lesson":3,"ex":[["取引先の人が会社に来ました。","Người của đối tác đã đến công ty."],["取引先と会議をしました。","Tôi đã họp với đối tác."],["新しい取引先が増えました。","Đối tác mới đã tăng lên."],["取引先にメールを送りました。","Tôi đã gửi email cho đối tác."],["取引先の名前を覚えなければなりません。","Tôi phải nhớ tên của đối tác."]]},{"word":"学生用","reading":"がくせいよう","meaning":"Dành cho sinh viên","hanViet":"HỌC SINH DỤNG","lesson":3,"ex":[["これは学生用の辞書です。","Đây là từ điển dành cho sinh viên."],["学生用のパソコンが図書館にあります。","Trong thư viện có máy tính dành cho sinh viên."],["学生用の本は安いです。","Sách dành cho sinh viên rẻ."],["学生用の部屋を借りました。","Tôi đã thuê phòng dành cho sinh viên."],["学生用の食堂で昼ごはんを食べます。","Tôi ăn trưa ở nhà ăn dành cho sinh viên."]]},{"word":"～用","reading":"～よう","meaning":"Dành cho ～","hanViet":"DỤNG","lesson":3,"ex":[["これは子ども用の自転車です。","Đây là xe đạp dành cho trẻ em."],["会社用のパソコンを買いました。","Tôi đã mua máy tính dùng cho công ty."],["旅行用のかばんを準備しました。","Tôi đã chuẩn bị túi dùng khi đi du lịch."],["料理用の道具を買いました。","Tôi đã mua dụng cụ dùng để nấu ăn."],["家族用の大きい車があります。","Có chiếc xe lớn dành cho gia đình."]]},{"word":"コンピューター室","reading":"コンピューターしつ","meaning":"Phòng máy tính","hanViet":"THẤT","lesson":3,"ex":[["コンピューター室で勉強します。","Tôi học trong phòng máy tính."],["コンピューター室は三階にあります。","Phòng máy tính ở tầng ba."],["コンピューター室のパソコンを使いました。","Tôi đã dùng máy tính trong phòng máy tính."],["昼休みにコンピューター室へ行きます。","Vào giờ nghỉ trưa tôi đến phòng máy tính."],["コンピューター室は静かです。","Phòng máy tính yên tĩnh."]]},{"word":"～室","reading":"～しつ","meaning":"Phòng ～","hanViet":"THẤT","lesson":3,"ex":[["会議室で話し合いをしました。","Tôi đã thảo luận trong phòng họp."],["教室の窓を開けました。","Tôi đã mở cửa sổ lớp học."],["研究室で先生と話しました。","Tôi đã nói chuyện với thầy giáo trong phòng nghiên cứu."],["寝室で本を読みます。","Tôi đọc sách trong phòng ngủ."],["和室は静かで勉強しやすいです。","Phòng kiểu Nhật yên tĩnh và dễ học."]]},{"word":"渋滞","reading":"じゅうたい","meaning":"Giao thông tắc nghẽn, kẹt xe","hanViet":"SÁP TRỆ","lesson":3,"ex":[["朝は道路が渋滞します。","Buổi sáng đường bị kẹt xe."],["渋滞で会社に遅れました。","Vì kẹt xe nên tôi đã đến công ty muộn."],["渋滞を避けるために、早く出かけます。","Để tránh kẹt xe, tôi ra ngoài sớm."],["連休は高速道路が渋滞します。","Vào kỳ nghỉ dài, đường cao tốc bị kẹt xe."],["渋滞のせいで、一時間遅れました。","Vì kẹt xe nên tôi đã muộn một giờ."]]},{"word":"瞬間","reading":"しゅんかん","meaning":"Khoảnh khắc","hanViet":"THUẤN GIAN","lesson":3,"ex":[["その瞬間、みんなが笑いました。","Khoảnh khắc đó, mọi người đã cười."],["写真を撮る瞬間、鳥が飛びました。","Khoảnh khắc chụp ảnh, con chim đã bay."],["会った瞬間、好きになりました。","Khoảnh khắc gặp nhau, tôi đã thích anh ấy."],["電車が出る瞬間、友達が見えました。","Khoảnh khắc tàu chạy, tôi đã thấy bạn."],["その瞬間のことを今でも覚えています。","Tôi vẫn còn nhớ chuyện của khoảnh khắc đó."]]},{"word":"意識","reading":"いしき","meaning":"Ý thức","hanViet":"Ý THỨC","lesson":3,"ex":[["健康について意識しています。","Tôi có ý thức về sức khỏe."],["安全に対する意識が大切です。","Ý thức về an toàn rất quan trọng."],["意識して日本語を使います。","Tôi có ý thức sử dụng tiếng Nhật."],["みんなの環境への意識が強くなりました。","Ý thức về môi trường của mọi người đã mạnh lên."],["意識が変わると、生活も変わります。","Khi ý thức thay đổi, cuộc sống cũng thay đổi."]]},{"word":"アンケート","reading":"アンケート","meaning":"Bản điều tra, phiếu điều tra","hanViet":"","lesson":3,"ex":[["アンケートに答えました。","Tôi đã trả lời phiếu điều tra."],["会社でアンケートをしました。","Tôi đã làm phiếu điều tra ở công ty."],["アンケートの結果を見ました。","Tôi đã xem kết quả phiếu điều tra."],["アンケートに協力してください。","Xin hãy hợp tác trả lời phiếu điều tra."],["アンケートの質問に答えるのは簡単でした。","Việc trả lời câu hỏi trong phiếu điều tra rất dễ dàng."]]},{"word":"調査","reading":"ちょうさ","meaning":"Điều tra","hanViet":"ĐIỀU TRA","lesson":3,"ex":[["会社は市場調査をしました。","Công ty đã làm điều tra thị trường."],["調査の結果、多くの人が車を使っていました。","Kết quả điều tra cho thấy nhiều người dùng ô tô."],["学生の生活について調査しました。","Tôi đã điều tra về cuộc sống của sinh viên."],["調査をする前に、計画を立てました。","Trước khi điều tra, tôi đã lập kế hoạch."],["調査のデータをグラフにしました。","Tôi đã đưa dữ liệu điều tra vào biểu đồ."]]},{"word":"傾向","reading":"けいこう","meaning":"Khuynh hướng, xu hướng","hanViet":"KHUYNH HƯỚNG","lesson":3,"ex":[["最近、若い人が一人で住む傾向があります。","Gần đây, người trẻ có xu hướng sống một mình."],["日本の生活に新しい傾向が見られます。","Có thể thấy xu hướng mới trong cuộc sống ở Nhật Bản."],["その傾向はこれからも続くでしょう。","Xu hướng đó có lẽ sẽ tiếp tục từ nay."],["グラフから傾向がわかります。","Từ biểu đồ có thể hiểu được xu hướng."],["景気の傾向について話し合いました。","Chúng tôi đã thảo luận về xu hướng kinh tế."]]},{"word":"避ける","reading":"さける","meaning":"Tránh","hanViet":"TỊ","lesson":3,"ex":[["危ない場所を避けてください。","Hãy tránh nơi nguy hiểm."],["渋滞を避けるために、電車で行きます。","Để tránh kẹt xe, tôi đi bằng tàu điện."],["失敗を避けることはできません。","Không thể tránh được thất bại."],["暑い時間に外に出るのを避けます。","Tôi tránh ra ngoài vào lúc nóng."],["けんかを避けるために、よく話し合います。","Để tránh cãi nhau, chúng tôi thảo luận kỹ."]]},{"word":"悲観的","reading":"ひかんてき","meaning":"Bi quan","hanViet":"BI QUAN ĐÍCH","lesson":3,"ex":[["彼は景気について悲観的です。","Anh ấy bi quan về tình hình kinh tế."],["悲観的に考えすぎないでください。","Xin đừng nghĩ bi quan quá."],["悲観的な意見が多いです。","Có nhiều ý kiến bi quan."],["試験の結果について悲観的でしたが、合格しました。","Tôi đã bi quan về kết quả thi nhưng đã đỗ."],["悲観的な気持ちを忘れて、頑張りましょう。","Hãy quên cảm giác bi quan và cố gắng."]]},{"word":"グラフ","reading":"グラフ","meaning":"Biểu đồ","hanViet":"","lesson":3,"ex":[["グラフを見ると、数が増えています。","Nhìn biểu đồ thì thấy số lượng đang tăng."],["調査の結果をグラフにしました。","Tôi đã đưa kết quả điều tra vào biểu đồ."],["グラフの説明を聞きました。","Tôi đã nghe giải thích về biểu đồ."],["このグラフは分かりやすいです。","Biểu đồ này dễ hiểu."],["グラフを書くのは難しいです。","Vẽ biểu đồ rất khó."]]},{"word":"時","reading":"とき","meaning":"Thời gian","hanViet":"THÌ","lesson":3,"ex":[["子どもの時は、よく外で遊びました。","Hồi còn nhỏ, tôi thường chơi ở ngoài."],["困った時は、友達に相談します。","Khi gặp khó khăn, tôi hỏi ý kiến bạn."],["日本に来た時は、日本語が話せませんでした。","Khi đến Nhật, tôi đã không nói được tiếng Nhật."],["時間がある時は、本を読みます。","Khi có thời gian, tôi đọc sách."],["悲しい時は、音楽を聞きます。","Khi buồn, tôi nghe nhạc."]]},{"word":"最高に","reading":"さいこうに","meaning":"Nhất, tột đỉnh","hanViet":"TỐI CAO","lesson":3,"ex":[["今日は最高に楽しい日でした。","Hôm nay là ngày vui nhất."],["この料理は最高においしいです。","Món ăn này ngon tuyệt vời."],["最高にきれいな景色を見ました。","Tôi đã thấy phong cảnh đẹp tuyệt vời."],["彼は最高にやさしい人です。","Anh ấy là người hiền lành tuyệt vời."],["最高にうれしいニュースを聞きました。","Tôi đã nghe tin vui nhất."]]},{"word":"もう一つ","reading":"もうひとつ","meaning":"Thêm một cái nữa","hanViet":"NHẤT","lesson":3,"ex":[["もう一つケーキをください。","Cho tôi thêm một chiếc bánh nữa."],["もう一つ質問があります。","Tôi có thêm một câu hỏi nữa."],["もう一つ本を買いました。","Tôi đã mua thêm một cuốn sách nữa."],["もう一つだけ教えてください。","Hãy chỉ cho tôi thêm một cái nữa thôi."],["もう一つ問題があります。","Còn một vấn đề nữa."]]},{"word":"あいだ","reading":"あいだ","meaning":"Trong lúc","hanViet":"","lesson":3,"ex":[["休みのあいだ、旅行しました。","Trong lúc nghỉ, tôi đã đi du lịch."],["仕事のあいだ、電話をしないでください。","Trong lúc làm việc, xin đừng gọi điện."],["日本にいるあいだ、日本語が上手になりました。","Trong lúc ở Nhật, tiếng Nhật của tôi đã giỏi lên."],["映画を見ているあいだ、だれも話しませんでした。","Trong lúc xem phim, không ai nói chuyện."],["子どもが寝ているあいだ、本を読みます。","Trong lúc con đang ngủ, tôi đọc sách."]]},{"word":"前者","reading":"ぜんしゃ","meaning":"Điều ở trước, cái ở trước","hanViet":"TIỀN GIẢ","lesson":3,"ex":[["前者は学生で、後者は先生です。","Cái trước là học sinh, cái sau là giáo viên."],["二つの意見がありますが、私は前者に賛成です。","Có hai ý kiến, nhưng tôi tán thành ý kiến trước."],["前者のほうが安いです。","Cái trước rẻ hơn."],["前者を選ぶ人が多いです。","Nhiều người chọn cái trước."],["前者と後者を比べてみましょう。","Hãy thử so sánh cái trước và cái sau."]]},{"word":"後者","reading":"こうしゃ","meaning":"Điều ở sau, cái ở sau","hanViet":"HẬU GIẢ","lesson":3,"ex":[["後者は先生で、とてもやさしい人です。","Người sau là giáo viên, một người rất hiền."],["二つの意見がありますが、私は後者に賛成です。","Có hai ý kiến, nhưng tôi tán thành ý kiến sau."],["後者のほうが便利です。","Cái sau tiện lợi hơn."],["後者を選ぶ人が多いです。","Nhiều người chọn cái sau."],["前者と後者では、後者のほうが新しいです。","So với cái trước, cái sau mới hơn."]]},{"word":"やはり","reading":"やはり","meaning":"Nói gì thì nói, rõ ràng là","hanViet":"","lesson":3,"ex":[["やはり、日本語は難しいです。","Nói gì thì nói, tiếng Nhật vẫn khó."],["やはり、家で食べる料理が一番おいしいです。","Rõ ràng là món ăn ở nhà ngon nhất."],["やはり、彼は来ませんでした。","Quả nhiên anh ấy đã không đến."],["やはり、電車で行くほうが早いです。","Rõ ràng là đi bằng tàu điện nhanh hơn."],["やはり、今日は休みましょう。","Nói gì thì nói, hôm nay chúng ta hãy nghỉ."]]},{"word":"恋","reading":"こい","meaning":"Tình yêu","hanViet":"LUYẾN","lesson":3,"ex":[["初めての恋は忘れられません。","Mối tình đầu không thể quên được."],["恋の話を友達としました。","Tôi đã nói chuyện tình yêu với bạn."],["彼は恋をしています。","Anh ấy đang yêu."],["恋についての本を読みました。","Tôi đã đọc sách về tình yêu."],["恋が始まると、毎日が楽しくなります。","Khi tình yêu bắt đầu, mỗi ngày trở nên vui vẻ."]]},{"word":"幸せ","reading":"しあわせ","meaning":"Hạnh phúc","hanViet":"HẠNH","lesson":3,"ex":[["家族といると、幸せを感じます。","Khi ở cùng gia đình, tôi cảm thấy hạnh phúc."],["幸せな生活を送りたいです。","Tôi muốn sống cuộc sống hạnh phúc."],["小さい幸せを大切にします。","Tôi trân trọng hạnh phúc nhỏ bé."],["彼女は今とても幸せです。","Cô ấy bây giờ rất hạnh phúc."],["幸せになるために、頑張ります。","Để trở nên hạnh phúc, tôi sẽ cố gắng."]]},{"word":"感じる","reading":"かんじる","meaning":"Cảm nhận","hanViet":"CẢM","lesson":3,"ex":[["音楽を聞くと、幸せを感じます。","Khi nghe nhạc, tôi cảm thấy hạnh phúc."],["春が来たことを感じます。","Tôi cảm nhận được mùa xuân đã đến."],["友達の言葉に元気を感じました。","Tôi đã cảm nhận được sự động viên trong lời nói của bạn."],["試験の前は緊張を感じます。","Trước kỳ thi, tôi cảm thấy căng thẳng."],["寒い風を感じます。","Tôi cảm nhận được cơn gió lạnh."]]},{"word":"寝坊する","reading":"ねぼうする","meaning":"Ngủ quên","hanViet":"TẨM PHƯỜNG","lesson":3,"ex":[["今朝、寝坊しました。","Sáng nay tôi đã ngủ quên."],["寝坊するので、目覚まし時計を二つ使います。","Vì hay ngủ quên nên tôi dùng hai đồng hồ báo thức."],["寝坊して、学校に遅れました。","Tôi đã ngủ quên nên đến trường muộn."],["きのう寝坊したので、今日は早く寝ます。","Vì hôm qua ngủ quên nên hôm nay tôi ngủ sớm."],["寝坊しないように、早く寝てください。","Để không ngủ quên, hãy ngủ sớm."]]},{"word":"危険","reading":"きけん","meaning":"Nguy hiểm","hanViet":"NGUY HIỂM","lesson":3,"ex":[["その場所は危険です。","Nơi đó nguy hiểm."],["危険なことをしないでください。","Xin đừng làm việc nguy hiểm."],["夜一人で歩くのは危険です。","Đi bộ một mình vào ban đêm rất nguy hiểm."],["危険を感じたら、すぐ逃げてください。","Nếu cảm thấy nguy hiểm, hãy chạy trốn ngay."],["子どもに危険を教えることが大切です。","Dạy cho trẻ em về nguy hiểm rất quan trọng."]]},{"word":"寝顔","reading":"ねがお","meaning":"Khuôn mặt lúc ngủ","hanViet":"TẨM NHAN","lesson":3,"ex":[["子どもの寝顔はかわいいです。","Khuôn mặt lúc ngủ của trẻ em rất dễ thương."],["赤ちゃんの寝顔を見ると、幸せになります。","Khi nhìn khuôn mặt lúc ngủ của em bé, tôi cảm thấy hạnh phúc."],["寝顔の写真を撮りました。","Tôi đã chụp ảnh khuôn mặt lúc ngủ."],["彼の寝顔はおとなしいです。","Khuôn mặt lúc ngủ của anh ấy rất hiền."],["猫の寝顔を見て、笑いました。","Nhìn khuôn mặt lúc ngủ của con mèo, tôi đã cười."]]},{"word":"検査する","reading":"けんさする","meaning":"Kiểm tra","hanViet":"KIỂM TRA","lesson":4,"ex":[["病院で健康の検査をしました。","Tôi đã kiểm tra sức khỏe ở bệnh viện."],["検査する前に、何も食べませんでした。","Trước khi kiểm tra, tôi đã không ăn gì."],["目の検査をしました。","Tôi đã kiểm tra mắt."],["検査の結果は来週わかります。","Kết quả kiểm tra sẽ biết vào tuần sau."],["車の検査をしました。","Tôi đã kiểm tra xe."]]},{"word":"明日","reading":"あす","meaning":"Ngày mai","hanViet":"MINH NHẬT","lesson":4,"ex":[["明日は休みです。","Ngày mai là ngày nghỉ."],["明日の天気はどうですか。","Thời tiết ngày mai thế nào?"],["明日、友達と会います。","Ngày mai tôi sẽ gặp bạn."],["明日までにレポートを出します。","Tôi sẽ nộp báo cáo trước ngày mai."],["明日は早く起きます。","Ngày mai tôi sẽ dậy sớm."]]},{"word":"能力","reading":"のうりょく","meaning":"Năng lực","hanViet":"NĂNG LỰC","lesson":4,"ex":[["彼は日本語の能力が高いです。","Năng lực tiếng Nhật của anh ấy cao."],["能力を上げるために、毎日勉強します。","Để nâng cao năng lực, tôi học mỗi ngày."],["自分の能力を信じています。","Tôi tin vào năng lực của mình."],["仕事に必要な能力は何ですか。","Năng lực cần thiết cho công việc là gì?"],["能力がある人は、早く仕事ができます。","Người có năng lực làm việc nhanh."]]},{"word":"バザー","reading":"バザー","meaning":"Chợ bán hàng cũ","hanViet":"","lesson":4,"ex":[["学校でバザーがあります。","Ở trường có chợ bán hàng cũ."],["バザーで古い本を買いました。","Tôi đã mua sách cũ ở chợ bán hàng cũ."],["バザーに子ども服を出しました。","Tôi đã mang quần áo trẻ em ra chợ bán hàng cũ."],["バザーのお金を学校に寄付します。","Tôi sẽ quyên góp tiền của chợ bán hàng cũ cho trường."],["バザーで安いものを買うことができます。","Ở chợ bán hàng cũ có thể mua đồ rẻ."]]},{"word":"マスク","reading":"マスク","meaning":"Khẩu trang, mặt nạ","hanViet":"","lesson":4,"ex":[["かぜのときはマスクをします。","Khi bị cảm, tôi đeo khẩu trang."],["マスクを買いました。","Tôi đã mua khẩu trang."],["病院ではマスクをしなければなりません。","Ở bệnh viện phải đeo khẩu trang."],["白いマスクを使います。","Tôi dùng khẩu trang trắng."],["マスクを忘れたので、新しいのを買いました。","Vì quên khẩu trang nên tôi đã mua cái mới."]]},{"word":"スーツケース","reading":"スーツケース","meaning":"Va li","hanViet":"","lesson":4,"ex":[["スーツケースに服を入れました。","Tôi đã bỏ quần áo vào va li."],["新しいスーツケースを買いました。","Tôi đã mua va li mới."],["スーツケースが重いです。","Va li nặng."],["旅行にスーツケースを持って行きます。","Tôi mang va li khi đi du lịch."],["スーツケースをホテルに置きました。","Tôi đã để va li ở khách sạn."]]},{"word":"目が覚める","reading":"めがさめる","meaning":"Tỉnh giấc","hanViet":"MỤC GIÁC","lesson":4,"ex":[["朝六時に目が覚めました。","Tôi đã tỉnh giấc lúc sáu giờ sáng."],["大きな音で目が覚めました。","Tôi đã tỉnh giấc vì tiếng động lớn."],["早く目が覚めるので、朝の時間が長いです。","Vì tỉnh giấc sớm nên thời gian buổi sáng dài."],["目が覚めたら、もう八時でした。","Khi tỉnh giấc thì đã tám giờ rồi."],["寒くて、夜中に目が覚めました。","Vì lạnh nên tôi đã tỉnh giấc giữa đêm."]]},{"word":"朝礼","reading":"ちょうれい","meaning":"Lễ tập trung buổi sáng, giao ban công việc buổi sáng ở công ty, trường học,...","hanViet":"TRIÊU LỄ","lesson":4,"ex":[["会社では毎朝、朝礼があります。","Ở công ty, mỗi sáng đều có lễ tập trung buổi sáng."],["朝礼で今日の仕事を確認します。","Ở buổi giao ban sáng, tôi xác nhận công việc hôm nay."],["朝礼のあと、仕事を始めます。","Sau buổi giao ban sáng, tôi bắt đầu làm việc."],["学校でも朝礼があります。","Ở trường cũng có lễ tập trung buổi sáng."],["朝礼に遅れないように、早く来ます。","Để không muộn buổi giao ban sáng, tôi đến sớm."]]},{"word":"校歌","reading":"こうか","meaning":"Bài hát truyền thống của nhà trường","hanViet":"GIÁO CA","lesson":4,"ex":[["学校の校歌を歌います。","Tôi hát bài hát truyền thống của trường."],["校歌をみんなで歌いました。","Mọi người đã cùng hát bài hát truyền thống của trường."],["朝礼で校歌を歌います。","Tôi hát bài hát truyền thống của trường ở buổi lễ tập trung buổi sáng."],["小学校の校歌を今でも覚えています。","Tôi vẫn còn nhớ bài hát truyền thống của trường tiểu học."],["校歌を歌うとき、元気になります。","Khi hát bài hát truyền thống của trường, tôi trở nên khỏe khoắn."]]},{"word":"敬語","reading":"けいご","meaning":"Kính ngữ","hanViet":"KÍNH NGỮ","lesson":4,"ex":[["敬語を使うのは難しいです。","Dùng kính ngữ rất khó."],["会社では敬語を使います。","Ở công ty tôi dùng kính ngữ."],["敬語を正しく使う練習をします。","Tôi luyện dùng kính ngữ đúng cách."],["先生に敬語で話します。","Tôi nói với thầy giáo bằng kính ngữ."],["敬語の勉強を始めました。","Tôi đã bắt đầu học kính ngữ."]]},{"word":"感想文","reading":"かんそうぶん","meaning":"Bài văn trình bày cảm tưởng như về một cuốn sách đã đọc","hanViet":"CẢM TƯỞNG VĂN","lesson":4,"ex":[["本を読んで、感想文を書きました。","Sau khi đọc sách, tôi đã viết bài cảm tưởng."],["感想文の宿題があります。","Có bài tập viết bài cảm tưởng."],["映画の感想文を書くのは楽しいです。","Viết bài cảm tưởng về phim rất vui."],["先生が感想文を読んでくれました。","Thầy giáo đã đọc bài cảm tưởng cho tôi."],["感想文に自分の気持ちを書きました。","Tôi đã viết cảm xúc của mình vào bài cảm tưởng."]]},{"word":"運動場","reading":"うんどうじょう","meaning":"Sân tập thể dục, sân vận động","hanViet":"VẬN ĐỘNG TRÀNG","lesson":4,"ex":[["運動場でサッカーをします。","Tôi chơi bóng đá ở sân vận động."],["学校の運動場は広いです。","Sân vận động của trường rộng."],["運動場で子どもたちが走っています。","Các em nhỏ đang chạy ở sân vận động."],["運動場の近くに木があります。","Gần sân vận động có cây."],["休み時間に運動場で遊びます。","Vào giờ nghỉ, tôi chơi ở sân vận động."]]},{"word":"いたずら","reading":"いたずら","meaning":"Ngịch ngợm","hanViet":"","lesson":4,"ex":[["子どもがいたずらをしました。","Đứa trẻ đã nghịch ngợm."],["犬がいたずらをして、靴をかみました。","Con chó nghịch ngợm đã cắn giày."],["いたずらをしないでください。","Xin đừng nghịch ngợm."],["いたずらをした子どもをしかりました。","Tôi đã mắng đứa trẻ nghịch ngợm."],["彼は小さいとき、いたずらばかりしていました。","Hồi nhỏ anh ấy chỉ nghịch ngợm suốt."]]},{"word":"美しい","reading":"うつくしい","meaning":"Đẹp","hanViet":"MỸ","lesson":4,"ex":[["美しい景色を見ました。","Tôi đã thấy phong cảnh đẹp."],["彼女は美しい人です。","Cô ấy là người đẹp."],["美しい花が咲いています。","Hoa đẹp đang nở."],["京都は美しい町です。","Kyoto là thành phố đẹp."],["美しい歌を聞きました。","Tôi đã nghe bài hát hay."]]},{"word":"世紀","reading":"せいき","meaning":"Thế kỷ","hanViet":"THẾ KỶ","lesson":4,"ex":[["二十一世紀はコンピューターの時代です。","Thế kỷ 21 là thời đại của máy tính."],["二十世紀に飛行機ができました。","Vào thế kỷ 20, máy bay đã ra đời."],["新しい世紀が始まります。","Một thế kỷ mới bắt đầu."],["十九世紀の本を読みました。","Tôi đã đọc sách của thế kỷ 19."],["新しい世紀には、世界が変わるでしょう。","Vào thế kỷ mới, thế giới có lẽ sẽ thay đổi."]]},{"word":"平和","reading":"へいわ","meaning":"Hòa bình","hanViet":"BÌNH HÒA","lesson":4,"ex":[["世界の人々は平和を願っています。","Mọi người trên thế giới đều mong muốn hòa bình."],["この国は長く平和が続いています。","Đất nước này đã giữ được hòa bình trong thời gian dài."],["平和な生活を守ることは大切です。","Bảo vệ cuộc sống hòa bình là điều quan trọng."],["戦争が終わって、町に平和が戻りました。","Chiến tranh kết thúc, hòa bình đã trở lại với thị trấn."],["子供たちのために、平和な未来を作りましょう。","Vì trẻ em, chúng ta hãy cùng tạo dựng một tương lai hòa bình."]]},{"word":"人々","reading":"ひとびと","meaning":"Mọi người","hanViet":"NHÂN","lesson":4,"ex":[["日曜日には、多くの人々が公園に来ます。","Vào chủ nhật, nhiều người đến công viên."],["この町の人々はとても親切です。","Người dân thị trấn này rất tốt bụng."],["祭りの日には、人々が駅前に集まります。","Vào ngày lễ hội, mọi người tập trung trước ga."],["世界の人々は日本の漫画が好きです。","Mọi người trên thế giới thích truyện tranh Nhật Bản."],["地震の後、多くの人々が病院に行きました。","Sau trận động đất, nhiều người đã đến bệnh viện."]]},{"word":"願う","reading":"ねがう","meaning":"Mong muốn, cầu mong","hanViet":"NGUYỆN","lesson":4,"ex":[["家族の健康を毎日願っています。","Tôi cầu mong gia đình luôn khỏe mạnh mỗi ngày."],["旅行の前に、いい天気になるように願いました。","Trước chuyến du lịch, tôi đã cầu mong thời tiết đẹp."],["私は子供たちの幸せを願っています。","Tôi mong các em nhỏ được hạnh phúc."],["みんなで世界の平和を願いましょう。","Chúng ta hãy cùng cầu nguyện cho hòa bình thế giới."],["私は友達の病気が治るように願っています。","Tôi cầu mong bệnh của bạn tôi mau khỏi."]]},{"word":"文","reading":"ぶん","meaning":"Câu, kiểu câu","hanViet":"VĂN","lesson":4,"ex":[["この文は少し長すぎます。","Câu này hơi dài quá."],["日本語の文を声に出して読みましょう。","Hãy đọc to các câu tiếng Nhật."],["先生は私の文の間違いを直しました。","Thầy đã sửa lỗi trong câu văn của tôi."],["短い文で答えてください。","Hãy trả lời bằng câu ngắn."],["この文の意味がわかりません。","Tôi không hiểu nghĩa của câu này."]]},{"word":"書き換える","reading":"かきかえる","meaning":"Viết lại thành","hanViet":"THƯ HOÁN","lesson":4,"ex":[["この文をひらがなに書き換えてください。","Hãy viết lại câu này bằng hiragana."],["漢字の文を易しい日本語に書き換えました。","Tôi đã viết lại câu có chữ Hán thành tiếng Nhật đơn giản."],["先生は私の作文を少し書き換えました。","Thầy đã viết lại bài văn của tôi một chút."],["この文を短い文に書き換えてみましょう。","Hãy thử viết lại câu này thành câu ngắn."],["間違えたところを書き換えて、先生に送りました。","Tôi đã viết lại chỗ sai rồi gửi cho thầy."]]},{"word":"合わせる","reading":"あわせる","meaning":"Kết hợp, làm cho khớp","hanViet":"HỢP","lesson":4,"ex":[["二人の予定を合わせて、会う日を決めました。","Tôi đã khớp lịch của hai người để quyết định ngày gặp."],["靴のサイズを足に合わせてください。","Hãy chọn giày vừa với cỡ chân."],["みんなの声を合わせて、歌を歌いました。","Mọi người đã cùng hòa giọng hát."],["時計を日本の時間に合わせました。","Tôi đã chỉnh đồng hồ theo giờ Nhật Bản."],["みんなの力を合わせて、大きな仕事が終わりました。","Mọi người đã hợp sức, công việc lớn đã hoàn thành."]]},{"word":"もともと","reading":"もともと","meaning":"Vốn dĩ","hanViet":"","lesson":4,"ex":[["もともと私は東京に住んでいました。","Vốn dĩ tôi đã sống ở Tokyo."],["この店はもともと本屋でした。","Cửa hàng này vốn là hiệu sách."],["もともと彼は静かな人です。","Vốn dĩ anh ấy là người trầm tính."],["もともとこの部屋は教室でした。","Vốn dĩ căn phòng này là phòng học."],["彼はもともと日本語が上手でした。","Vốn dĩ anh ấy đã giỏi tiếng Nhật."]]},{"word":"若者","reading":"わかもの","meaning":"Người trẻ tuổi","hanViet":"NHƯỢC GIẢ","lesson":4,"ex":[["若者は新しい音楽が好きです。","Người trẻ thích âm nhạc mới."],["この町には若者が多く住んでいます。","Thị trấn này có nhiều người trẻ sinh sống."],["若者の間で、この歌が有名です。","Bài hát này nổi tiếng trong giới trẻ."],["多くの若者が東京で働いています。","Nhiều người trẻ đang làm việc ở Tokyo."],["若者は新しいことに興味があります。","Người trẻ có hứng thú với những điều mới."]]},{"word":"～湖","reading":"～こ","meaning":"Hồ ～","hanViet":"HỒ","lesson":4,"ex":[["びわ湖は日本でとても大きい湖です。","Hồ Biwa là hồ rất lớn ở Nhật Bản."],["夏には、多くの人がびわ湖で泳ぎます。","Vào mùa hè, nhiều người bơi ở hồ Biwa."],["私たちはびわ湖のそばを歩きました。","Chúng tôi đã đi bộ dọc theo hồ Biwa."],["やまなか湖の近くにホテルがあります。","Gần hồ Yamanaka có một khách sạn."],["かわぐち湖では、多くの人が釣りをします。","Ở hồ Kawaguchi, nhiều người câu cá."]]},{"word":"深い","reading":"ふかい","meaning":"Sâu","hanViet":"THÂM","lesson":4,"ex":[["この湖はとても深いです。","Hồ này rất sâu."],["冬には雪が深くなります。","Vào mùa đông, tuyết trở nên dày."],["海の深いところには、大きな魚がいます。","Ở nơi sâu dưới biển có những con cá lớn."],["彼は日本語の意味を深く考えました。","Anh ấy đã suy nghĩ sâu về nghĩa tiếng Nhật."],["この本は深い意味があります。","Cuốn sách này có ý nghĩa sâu sắc."]]},{"word":"さまざま","reading":"さまざま","meaning":"Nhiều, đa dạng","hanViet":"","lesson":4,"ex":[["日本にはさまざまな料理があります。","Nhật Bản có nhiều món ăn đa dạng."],["さまざまな国の人がこの学校で勉強しています。","Học sinh nhiều nước đang học ở trường này."],["店にはさまざまな色の服があります。","Cửa hàng có quần áo nhiều màu sắc đa dạng."],["旅行では、さまざまな町を見ることができます。","Khi đi du lịch, có thể thấy nhiều thị trấn khác nhau."],["彼はさまざまな本を読みました。","Anh ấy đã đọc nhiều loại sách khác nhau."]]},{"word":"苦しい","reading":"くるしい","meaning":"Khổ, vất vả","hanViet":"KHỔ","lesson":4,"ex":[["仕事が多くて、毎日苦しいです。","Công việc nhiều nên mỗi ngày đều vất vả."],["お金がなくて、苦しい生活をしています。","Không có tiền nên cuộc sống rất vất vả."],["病気のときは、体が苦しくなります。","Khi bị bệnh, cơ thể trở nên khó chịu."],["日本語の勉強は苦しいですが、楽しいです。","Học tiếng Nhật vất vả nhưng vui."],["苦しいとき、友達が助けてくれました。","Khi khó khăn, bạn bè đã giúp đỡ tôi."]]},{"word":"性格","reading":"せいかく","meaning":"Tính cách","hanViet":"TÍNH CÁCH","lesson":4,"ex":[["彼女は明るい性格です。","Cô ấy có tính cách vui vẻ."],["性格は人によって違います。","Tính cách khác nhau tùy từng người."],["彼はおとなしい性格ですが、とても親切です。","Anh ấy có tính cách trầm lặng nhưng rất tốt bụng."],["私と兄は性格が全然違います。","Tôi và anh trai có tính cách hoàn toàn khác nhau."],["仕事では、明るい性格が大切です。","Trong công việc, tính cách vui vẻ là quan trọng."]]},{"word":"人気者","reading":"にんきもの","meaning":"Người được yêu thích, người được hâm mộ","hanViet":"NHÂN KHÍ GIẢ","lesson":4,"ex":[["田中さんは学校の人気者です。","Anh Tanaka là người được yêu thích ở trường."],["彼はクラスの人気者で、友達が多いです。","Anh ấy là người nổi tiếng trong lớp và có nhiều bạn."],["あの歌手は若者の人気者です。","Ca sĩ đó được giới trẻ yêu thích."],["山田さんは会社の人気者です。","Chị Yamada là người được yêu mến trong công ty."],["人気者になるには、親切な心が大切です。","Để trở thành người được yêu thích, tấm lòng tốt bụng là quan trọng."]]},{"word":"多く","reading":"おおく","meaning":"Nhiều","hanViet":"ĐA","lesson":4,"ex":[["多くの人が公園に来ました。","Nhiều người đã đến công viên."],["私は本を多く読みます。","Tôi đọc nhiều sách."],["多くの国で日本語が勉強されています。","Tiếng Nhật được học ở nhiều nước."],["彼は多くの友達がいます。","Anh ấy có nhiều bạn bè."],["雨が多いので、傘を買いました。","Vì mưa nhiều nên tôi đã mua ô."]]},{"word":"不安","reading":"ふあん","meaning":"Bất an, lo lắng","hanViet":"BẤT AN","lesson":4,"ex":[["試験の前は不安になります。","Trước kỳ thi tôi cảm thấy bất an."],["一人で旅行に行くのは不安です。","Đi du lịch một mình thật bất an."],["新しい仕事は不安ですが、頑張ります。","Công việc mới khiến tôi bất an nhưng tôi sẽ cố gắng."],["将来のことが不安です。","Tôi lo lắng về tương lai."],["彼女は試験の結果が不安だと言いました。","Cô ấy nói rằng cô ấy lo lắng về kết quả kỳ thi."]]},{"word":"出る","reading":"でる","meaning":"Ra thị trường, được bày bán","hanViet":"XUẤT","lesson":4,"ex":[["新しい本があした出ます。","Sách mới sẽ ra mắt ngày mai."],["あの歌手の新しい歌が出ました。","Bài hát mới của ca sĩ đó đã ra mắt."],["この雑誌は毎週出ます。","Tạp chí này ra hàng tuần."],["あの映画の本が出ました。","Sách về bộ phim đó đã ra mắt."],["この店では、新しい漫画がたくさん出ています。","Ở cửa hàng này, nhiều truyện tranh mới đang được bày bán."]]},{"word":"雷","reading":"かみなり","meaning":"Sấm sét","hanViet":"LÔI","lesson":4,"ex":[["雷の音が大きくて、怖かったです。","Tiếng sấm rất to nên tôi đã sợ."],["夜に雷が鳴りました。","Ban đêm sấm đã nổ."],["夜、雷の音で起きました。","Ban đêm, tôi tỉnh giấc vì tiếng sấm."],["雷が怖くて、外に出ませんでした。","Vì sợ sấm sét nên tôi không ra ngoài."],["夏には雷が多いです。","Vào mùa hè thường có nhiều sấm sét."]]},{"word":"うち","reading":"うち","meaning":"Chúng tôi","hanViet":"","lesson":4,"ex":[["うちの会社は東京にあります。","Công ty chúng tôi ở Tokyo."],["うちの学校は駅の近くにあります。","Trường chúng tôi ở gần ga."],["うちの犬はとても元気です。","Chó nhà tôi rất khỏe mạnh."],["うちの家族は五人です。","Gia đình tôi có năm người."],["うちの店では、新しいパンを売っています。","Cửa hàng chúng tôi đang bán bánh mì mới."]]},{"word":"残念","reading":"ざんねん","meaning":"Tiếc, nuối tiếc","hanViet":"TÀN NIỆM","lesson":4,"ex":[["旅行に行けなくて、残念でした。","Không đi du lịch được nên thật tiếc."],["残念ですが、あしたは仕事があります。","Tiếc là ngày mai tôi có việc."],["友達に会えなくて、残念です。","Không gặp được bạn nên thật tiếc."],["本が売り切れで、残念です。","Sách đã hết hàng nên thật tiếc."],["試験に落ちて、残念でした。","Thi trượt nên tôi rất tiếc."]]},{"word":"認める","reading":"みとめる","meaning":"Thừa nhận","hanViet":"NHẬN","lesson":4,"ex":[["彼は間違いを認めました。","Anh ấy đã thừa nhận sai lầm."],["先生は私の力を認めてくれました。","Thầy đã công nhận năng lực của tôi."],["彼は負けたことを認めました。","Anh ấy đã thừa nhận mình đã thua."],["会社は彼の仕事を認めています。","Công ty công nhận công việc của anh ấy."],["現実を認めることは大切です。","Thừa nhận thực tế là điều quan trọng."]]},{"word":"現実","reading":"げんじつ","meaning":"Thực tế","hanViet":"HIỆN THỰC","lesson":4,"ex":[["夢と現実は違います。","Ước mơ và thực tế khác nhau."],["現実は厳しいですが、頑張ります。","Thực tế khắc nghiệt nhưng tôi sẽ cố gắng."],["彼は現実を知っています。","Anh ấy hiểu rõ thực tế."],["現実の生活は忙しいです。","Cuộc sống thực tế rất bận rộn."],["この本は現実の問題について書いています。","Cuốn sách này viết về vấn đề thực tế."]]},{"word":"愛する","reading":"あいする","meaning":"Yêu","hanViet":"ÁI","lesson":4,"ex":[["私は家族を愛しています。","Tôi yêu gia đình."],["彼は日本を愛する人です。","Anh ấy là người yêu nước Nhật."],["私たちは平和を愛します。","Chúng tôi yêu hòa bình."],["彼女は音楽を心から愛しています。","Cô ấy yêu âm nhạc từ tận đáy lòng."],["子供たちを愛する親の気持ちは強いです。","Tình cảm của cha mẹ yêu các con rất mạnh mẽ."]]},{"word":"首都","reading":"しゅと","meaning":"Thủ đô","hanViet":"THỦ ĐÔ","lesson":4,"ex":[["日本の首都は東京です。","Thủ đô của Nhật Bản là Tokyo."],["首都には多くの人が住んでいます。","Thủ đô có nhiều người sinh sống."],["私は首都の大学で勉強しました。","Tôi đã học ở trường đại học tại thủ đô."],["首都の人口はとても多いです。","Dân số thủ đô rất đông."],["去年、首都へ旅行に行きました。","Năm ngoái, tôi đã đi du lịch đến thủ đô."]]},{"word":"伝言","reading":"でんごん","meaning":"Lời nhắn, tin nhắn để lại","hanViet":"TRUYỀN NGÔN","lesson":4,"ex":[["田中さんに伝言を頼みました。","Tôi đã nhờ nhắn lại cho anh Tanaka."],["電話に伝言を入れました。","Tôi đã để lại lời nhắn trên điện thoại."],["先生への伝言があります。","Có lời nhắn gửi thầy."],["伝言を聞いて、電話をかけました。","Nghe lời nhắn, tôi đã gọi điện lại."],["友達からの伝言を母に伝えました。","Tôi đã chuyển lời nhắn của bạn cho mẹ."]]},{"word":"留守番電話","reading":"るすばんでんわ","meaning":"Hộp thư thoại","hanViet":"LƯU THỦ PHIÊN ĐIỆN THOẠI","lesson":4,"ex":[["いないときは、留守番電話に伝言を入れてください。","Khi tôi không có nhà, hãy để lại lời nhắn vào hộp thư thoại."],["留守番電話のメッセージを聞きました。","Tôi đã nghe tin nhắn trong hộp thư thoại."],["電話に出られなかったので、留守番電話に話しました。","Vì không nghe được điện thoại nên tôi đã nói vào hộp thư thoại."],["留守番電話に新しいメッセージが入っています。","Trong hộp thư thoại có tin nhắn mới."],["彼は留守番電話をよく使います。","Anh ấy thường dùng hộp thư thoại."]]},{"word":"メッセージ","reading":"メッセージ","meaning":"Tin nhắn","hanViet":"","lesson":4,"ex":[["友達からメッセージが届きました。","Tin nhắn của bạn đã đến."],["メッセージを送ってください。","Hãy gửi tin nhắn cho tôi."],["先生にメッセージを書きました。","Tôi đã viết tin nhắn cho thầy."],["短いメッセージで答えました。","Tôi đã trả lời bằng tin nhắn ngắn."],["メッセージを読んで、うれしくなりました。","Đọc tin nhắn, tôi cảm thấy vui."]]},{"word":"入れる","reading":"いれる","meaning":"Để lại một tin nhắn","hanViet":"NHẬP","lesson":4,"ex":[["留守番電話に伝言を入れてください。","Hãy để lại lời nhắn vào hộp thư thoại."],["電話にメッセージを入れました。","Tôi đã để lại tin nhắn trên điện thoại."],["彼は伝言を入れて、帰りました。","Anh ấy đã để lại lời nhắn rồi về."],["伝言を入れたのに、電話が来ませんでした。","Dù đã để lại lời nhắn nhưng không có điện thoại gọi lại."],["忙しいときは、伝言を入れてください。","Khi bận, hãy để lại lời nhắn."]]},{"word":"差し上げる","reading":"さしあげる","meaning":"Biếu, tặng (cách nói khiêm nhường)","hanViet":"SOA THƯỢNG","lesson":4,"ex":[["先生に花を差し上げました。","Tôi đã tặng hoa cho thầy."],["お土産を山田さんに差し上げました。","Tôi đã biếu quà cho chị Yamada."],["旅行の後、先生にお土産を差し上げました。","Sau chuyến du lịch, tôi đã biếu quà cho thầy."],["友達の母にケーキを差し上げました。","Tôi đã tặng bánh cho mẹ của bạn."],["先生に日本の本を差し上げました。","Tôi đã tặng thầy cuốn sách Nhật."]]},{"word":"そのように","reading":"そのように","meaning":"Như thế","hanViet":"","lesson":4,"ex":[["そのようにしてください。","Hãy làm như thế."],["そのように考える人もいます。","Cũng có người nghĩ như thế."],["先生はそのように言いました。","Thầy đã nói như thế."],["そのように書いてください。","Hãy viết như thế."],["そのようにすれば、できます。","Làm như thế thì sẽ được."]]},{"word":"急","reading":"きゅう","meaning":"Gấp","hanViet":"CẤP","lesson":4,"ex":[["急な仕事が入りました。","Có công việc gấp."],["急な用事で、帰らなければなりませんでした。","Vì có việc gấp nên tôi đã phải về."],["急な電話がかかってきました。","Có cuộc điện thoại gấp gọi đến."],["急な雨が降りました。","Bỗng nhiên trời đổ mưa."],["急な病気で、病院に行きました。","Vì bệnh đột ngột nên tôi đã đến bệnh viện."]]},{"word":"入る","reading":"はいる","meaning":"Có công việc","hanViet":"NHẬP","lesson":4,"ex":[["あした仕事が入りました。","Ngày mai tôi có việc."],["午後に会議が入りました。","Buổi chiều tôi có cuộc họp."],["来週、新しい仕事が入ります。","Tuần sau tôi có việc mới."],["予定が入ったので、旅行に行けません。","Vì có lịch bận nên tôi không đi du lịch được."],["夜に仕事が入って、遅く帰りました。","Buổi tối có việc nên tôi về muộn."]]},{"word":"取り消す","reading":"とりけす","meaning":"Hủy","hanViet":"THỦ TIÊU","lesson":4,"ex":[["旅行を取り消しました。","Tôi đã hủy chuyến du lịch."],["予定を取り消して、家にいました。","Tôi đã hủy lịch và ở nhà."],["会議を取り消しました。","Tôi đã hủy cuộc họp."],["病気になったので、約束を取り消しました。","Vì bị bệnh nên tôi đã hủy hẹn."],["先生は授業を取り消しました。","Thầy đã hủy tiết học."]]},{"word":"来客中","reading":"らいきゃくちゅう","meaning":"Đang có khách","hanViet":"LAI KHÁCH TRUNG","lesson":4,"ex":[["先生は今、来客中です。","Thầy đang có khách."],["部長は来客中ですので、後で電話してください。","Trưởng phòng đang có khách nên hãy gọi lại sau."],["田中さんは来客中で、会えません。","Anh Tanaka đang có khách nên không gặp được."],["来客中ですから、静かにしてください。","Đang có khách nên hãy giữ yên lặng."],["母は来客中で、電話に出られません。","Mẹ đang có khách nên không nghe điện thoại được."]]},{"word":"食パン","reading":"しょくパン","meaning":"Bánh mì","hanViet":"THỰC","lesson":4,"ex":[["朝は食パンを食べます。","Buổi sáng tôi ăn bánh mì."],["店で食パンを買いました。","Tôi đã mua bánh mì ở cửa hàng."],["食パンが売り切れでした。","Bánh mì đã hết hàng."],["朝ごはんに食パンと卵を食べました。","Bữa sáng tôi đã ăn bánh mì và trứng."],["この店の食パンはとてもおいしいです。","Bánh mì ở cửa hàng này rất ngon."]]},{"word":"売り切れ","reading":"うりきれ","meaning":"Hết hàng","hanViet":"MẠI THIẾT","lesson":4,"ex":[["人気の本は売り切れでした。","Cuốn sách nổi tiếng đã hết hàng."],["チケットは売り切れでした。","Vé đã bán hết."],["食パンは朝早く売り切れました。","Bánh mì đã bán hết từ sáng sớm."],["この服は売り切れです。","Bộ quần áo này đã hết hàng."],["新しい雑誌は二日で売り切れました。","Tạp chí mới đã bán hết trong hai ngày."]]},{"word":"バーゲンセール","reading":"バーゲンセール","meaning":"Bán giảm giá","hanViet":"","lesson":4,"ex":[["デパートでバーゲンセールをしています。","Cửa hàng bách hóa đang bán giảm giá."],["バーゲンセールで服を安く買いました。","Tôi đã mua quần áo rẻ trong đợt giảm giá."],["あしたからバーゲンセールが始まります。","Từ ngày mai đợt giảm giá bắt đầu."],["バーゲンセールには多くの人が来ます。","Đợt giảm giá thu hút nhiều người đến."],["バーゲンセールで靴を買いました。","Tôi đã mua giày trong đợt giảm giá."]]},{"word":"案内状","reading":"あんないじょう","meaning":"Giấy mời, thư mời","hanViet":"ÁN NỘI TRẠNG","lesson":4,"ex":[["結婚式の案内状が届きました。","Giấy mời đám cưới đã đến."],["会社から案内状をもらいました。","Tôi nhận được thư mời từ công ty."],["案内状を友達に送りました。","Tôi đã gửi giấy mời cho bạn."],["パーティーの案内状を書きました。","Tôi đã viết thư mời dự tiệc."],["案内状を読んで、うれしくなりました。","Đọc giấy mời, tôi cảm thấy vui."]]},{"word":"～状","reading":"～じょう","meaning":"Thư, thiệp, giấy mời","hanViet":"TRẠNG","lesson":4,"ex":[["結婚式の招待状が届きました。","Thiệp mời đám cưới đã đến."],["友達に年賀状を送りました。","Tôi đã gửi thiệp chúc mừng năm mới cho bạn."],["学校から案内状をもらいました。","Tôi nhận được thư mời từ trường."],["招待状を書くのは楽しいです。","Viết thiệp mời thật vui."],["年賀状を十枚書きました。","Tôi đã viết mười tấm thiệp năm mới."]]},{"word":"遠い","reading":"とおい","meaning":"Xa","hanViet":"VIỄN","lesson":4,"ex":[["学校は家から遠いです。","Trường học xa nhà tôi."],["駅からここまで遠いですか。","Từ ga đến đây có xa không."],["東京はここから遠いです。","Tokyo xa chỗ này."],["電話の声が遠くて、よく聞こえません。","Tiếng trong điện thoại xa quá nên tôi nghe không rõ."],["声が遠いので、大きく話してください。","Tiếng xa quá nên hãy nói to lên."]]},{"word":"～嫌い","reading":"～ぎらい","meaning":"Ghét, không thích","hanViet":"HIỀM","lesson":4,"ex":[["私は魚嫌いです。","Tôi ghét ăn cá."],["弟は野菜嫌いです。","Em trai tôi ghét rau."],["彼は肉嫌いです。","Anh ấy ghét thịt."],["私は勉強嫌いでした。","Tôi đã từng ghét học."],["彼は掃除嫌いです。","Anh ấy ghét dọn dẹp."]]},{"word":"時代","reading":"じだい","meaning":"Thời đại, thời kỳ","hanViet":"THỜI ĐẠI","lesson":4,"ex":[["今は便利な時代です。","Bây giờ là thời đại tiện lợi."],["昔の時代には、テレビがありませんでした。","Thời ngày xưa không có ti vi."],["時代が変わりました。","Thời đại đã thay đổi."],["新しい時代が始まります。","Một thời đại mới bắt đầu."],["この本は古い時代について書いています。","Cuốn sách này viết về thời đại xưa."]]},{"word":"順に","reading":"じゅんに","meaning":"Lần lượt, theo thứ tự","hanViet":"THUẬN","lesson":4,"ex":[["名前を順に呼びました。","Tôi đã gọi tên lần lượt."],["順に並んでください。","Hãy xếp hàng lần lượt."],["問題を順に答えてください。","Hãy trả lời các câu hỏi theo thứ tự."],["みんな順に話しました。","Mọi người đã nói lần lượt."],["本を順に読んでいます。","Tôi đang đọc sách theo thứ tự."]]},{"word":"失礼","reading":"しつれい","meaning":"Thất lễ","hanViet":"THẤT LỄ","lesson":4,"ex":[["失礼ですが、お名前を教えてください。","Xin lỗi, cho tôi hỏi tên của anh là gì."],["失礼しました。","Tôi xin lỗi."],["失礼なことを言って、すみません。","Tôi đã nói điều thất lễ, xin lỗi."],["人の話を聞かないのは失礼です。","Không nghe người khác nói là thất lễ."],["失礼ですが、道を教えてください。","Xin lỗi, hãy chỉ đường cho tôi."]]},{"word":"進める","reading":"すすめる","meaning":"Tiến hành, đẩy mạnh, thúc đẩy","hanViet":"TIẾN","lesson":4,"ex":[["仕事を進めましょう。","Hãy tiến hành công việc."],["計画を進めています。","Tôi đang thúc đẩy kế hoạch."],["先生は授業を進めました。","Thầy đã tiến hành tiết học."],["話を進めてください。","Hãy tiếp tục câu chuyện."],["勉強を進めるために、毎日練習します。","Để thúc đẩy việc học, tôi luyện tập mỗi ngày."]]},{"word":"腹を立てる","reading":"はらをたてる","meaning":"Nổi cáu, tức giận","hanViet":"PHÚC LẬP","lesson":4,"ex":[["母は私の話に腹を立てました。","Mẹ đã nổi cáu vì câu chuyện của tôi."],["彼は遅刻した友達に腹を立てました。","Anh ấy đã nổi cáu với người bạn đến muộn."],["先生は学生の話に腹を立てました。","Thầy đã nổi cáu vì câu chuyện của học sinh."],["腹を立てないで、よく聞いてください。","Đừng nổi cáu, hãy nghe kỹ."],["母は私が遅く帰るので腹を立てました。","Mẹ nổi cáu vì tôi về muộn."]]},{"word":"味わう","reading":"あじわう","meaning":"Thưởng thức","hanViet":"VỊ","lesson":4,"ex":[["日本の料理を味わいました。","Tôi đã thưởng thức món ăn Nhật."],["旅行で新しい味を味わいました。","Trong chuyến du lịch, tôi đã thưởng thức hương vị mới."],["彼はワインを味わっています。","Anh ấy đang thưởng thức rượu vang."],["静かな時間を味わいました。","Tôi đã thưởng thức khoảng thời gian yên tĩnh."],["京都で日本の味を味わいました。","Tôi đã thưởng thức hương vị Nhật Bản ở Kyoto."]]},{"word":"つなぐ","reading":"つなぐ","meaning":"Nắm tay, nối dây","hanViet":"","lesson":4,"ex":[["子供たちは手をつないで歩きました。","Các em nhỏ nắm tay nhau đi bộ."],["母と手をつないで、公園に行きました。","Tôi nắm tay mẹ đi đến công viên."],["インターネットをつないで、友達と話しました。","Tôi đã kết nối internet rồi nói chuyện với bạn."],["彼は私の手をつないでくれました。","Anh ấy đã nắm tay tôi."],["手をつなぐのはうれしいです。","Nắm tay nhau thật vui."]]},{"word":"エピソード","reading":"エピソード","meaning":"Câu chuyện, giai thoại","hanViet":"","lesson":4,"ex":[["先生は楽しいエピソードを話しました。","Thầy đã kể câu chuyện vui."],["この本には多くのエピソードがあります。","Cuốn sách này có nhiều giai thoại."],["彼は学生のときのエピソードを話しました。","Anh ấy đã kể giai thoại thời còn là sinh viên."],["旅行のエピソードを友達に話しました。","Tôi đã kể câu chuyện du lịch cho bạn."],["有名な人のエピソードを読みました。","Tôi đã đọc giai thoại về người nổi tiếng."]]},{"word":"大嫌い","reading":"だいきらい","meaning":"Rất ghét","hanViet":"ĐẠI HIỀM","lesson":4,"ex":[["私は魚が大嫌いです。","Tôi rất ghét cá."],["弟は野菜が大嫌いです。","Em trai tôi rất ghét rau."],["彼は雨の日が大嫌いです。","Anh ấy rất ghét ngày mưa."],["私は寒い冬が大嫌いです。","Tôi rất ghét mùa đông lạnh."],["彼女は注射が大嫌いです。","Cô ấy rất ghét tiêm."]]},{"word":"大","reading":"だい","meaning":"Rất, cực thích/ ghét","hanViet":"ĐẠI","lesson":4,"ex":[["私は猫が大好きです。","Tôi rất thích mèo."],["彼は日本語が大好きです。","Anh ấy rất thích tiếng Nhật."],["母は花が大好きです。","Mẹ tôi rất thích hoa."],["私は肉が大嫌いです。","Tôi rất ghét thịt."],["弟はゲームが大好きです。","Em trai tôi rất thích chơi game."]]},{"word":"しつこい","reading":"しつこい","meaning":"Dai dẳng, đeo bám, lì lợm","hanViet":"","lesson":4,"ex":[["彼はしつこい人です。","Anh ấy là người dai dẳng."],["しつこく聞かないでください。","Đừng hỏi dai dẳng."],["彼はしつこく電話をかけてきます。","Anh ấy cứ gọi điện mãi."],["しつこい雨が続いています。","Cơn mưa dai dẳng vẫn tiếp tục."],["彼はしつこく同じことを言います。","Anh ấy cứ nói mãi cùng một điều."]]},{"word":"全員","reading":"ぜんいん","meaning":"Tất cả mọi người","hanViet":"TOÀN VIÊN","lesson":4,"ex":[["全員が教室に集まりました。","Tất cả mọi người đã tập trung ở phòng học."],["クラスの全員が旅行に行きました。","Cả lớp đã đi du lịch."],["全員で歌を歌いました。","Tất cả mọi người cùng hát."],["会議には全員が出席しました。","Tất cả mọi người đã tham dự cuộc họp."],["全員が日本語を勉強しています。","Tất cả mọi người đang học tiếng Nhật."]]},{"word":"数日","reading":"すうじつ","meaning":"Vài ngày","hanViet":"SỔ NHẬT","lesson":4,"ex":[["数日後、雨が降りました。","Vài ngày sau, trời đã mưa."],["彼は数日休みました。","Anh ấy đã nghỉ vài ngày."],["数日前に友達に会いました。","Vài ngày trước tôi đã gặp bạn."],["旅行は数日続きます。","Chuyến du lịch kéo dài vài ngày."],["数日間、家にいました。","Tôi đã ở nhà vài ngày."]]},{"word":"親せき","reading":"しんせき","meaning":"Họ hàng","hanViet":"THÂN","lesson":4,"ex":[["親せきが東京に住んでいます。","Họ hàng của tôi sống ở Tokyo."],["夏には親せきが集まります。","Vào mùa hè, họ hàng tập trung lại."],["親せきの家に行きました。","Tôi đã đến nhà họ hàng."],["親せきは多いです。","Tôi có nhiều họ hàng."],["親せきから手紙が届きました。","Thư của họ hàng đã đến."]]},{"word":"接続する","reading":"せつぞくする","meaning":"Kết nối","hanViet":"TIẾP TỤC","lesson":4,"ex":[["インターネットに接続しました。","Tôi đã kết nối internet."],["パソコンをインターネットに接続してください。","Hãy kết nối máy tính với internet."],["接続できませんでした。","Tôi đã không kết nối được."],["電話を接続します。","Tôi sẽ kết nối điện thoại."],["接続した後、友達と話しました。","Sau khi kết nối, tôi đã nói chuyện với bạn."]]},{"word":"申し出る","reading":"もうしでる","meaning":"Đề nghị","hanViet":"THÂN XUẤT","lesson":4,"ex":[["彼は手伝うことを申し出ました。","Anh ấy đã đề nghị giúp đỡ."],["彼女は仕事をやめることを申し出ました。","Cô ấy đã đề nghị nghỉ việc."],["私は意見を申し出ました。","Tôi đã đưa ra ý kiến."],["友達が手伝うことを申し出ました。","Bạn tôi đã đề nghị giúp đỡ."],["申し出てくれて、ありがとうございました。","Cảm ơn anh đã đề nghị."]]},{"word":"結局","reading":"けっきょく","meaning":"Kết cục, cuối cùng","hanViet":"KẾT CỤC","lesson":4,"ex":[["結局、旅行に行きませんでした。","Cuối cùng, tôi đã không đi du lịch."],["結局、彼は来ませんでした。","Cuối cùng, anh ấy đã không đến."],["結局、雨が降りました。","Cuối cùng trời đã mưa."],["結局、仕事は終わりませんでした。","Cuối cùng công việc vẫn chưa xong."],["結局、みんなで家に帰りました。","Cuối cùng, mọi người cùng về nhà."]]},{"word":"早速","reading":"さっそく","meaning":"Ngay lập tức","hanViet":"TẢO TỐC","lesson":4,"ex":[["早速、電話をかけました。","Tôi đã gọi điện ngay lập tức."],["手紙を読んで、早速電話しました。","Đọc thư xong, tôi gọi điện ngay."],["早速、仕事を始めました。","Tôi đã bắt đầu công việc ngay lập tức."],["早速、服を買いに行きました。","Tôi đã đi mua quần áo ngay."],["新しい本を買って、早速読みました。","Mua sách mới xong, tôi đọc ngay."]]},{"word":"そば","reading":"そば","meaning":"Bên cạnh","hanViet":"","lesson":4,"ex":[["駅のそばにホテルがあります。","Bên cạnh ga có một khách sạn."],["母のそばに座りました。","Tôi đã ngồi bên cạnh mẹ."],["川のそばを歩きました。","Tôi đã đi bộ bên cạnh sông."],["私のそばに来てください。","Hãy đến bên cạnh tôi."],["学校のそばに公園があります。","Bên cạnh trường có một công viên."]]},{"word":"取り付ける","reading":"とりつける","meaning":"Lắp đặt","hanViet":"THỦ PHÓ","lesson":4,"ex":[["新しいテレビを取り付けました。","Tôi đã lắp chiếc ti vi mới."],["電話を取り付けてください。","Hãy lắp điện thoại giúp tôi."],["彼は時計を取り付けました。","Anh ấy đã lắp đồng hồ."],["会社に新しいパソコンを取り付けました。","Công ty đã lắp máy tính mới."],["取り付けは一時間で終わりました。","Việc lắp đặt xong trong một giờ."]]},{"word":"出席者","reading":"しゅっせきしゃ","meaning":"Người tham dự","hanViet":"XUẤT TỊCH GIẢ","lesson":4,"ex":[["会議の出席者は十人でした。","Số người tham dự cuộc họp là mười người."],["出席者は全員日本人でした。","Tất cả người tham dự đều là người Nhật."],["パーティーの出席者が増えました。","Số người tham dự bữa tiệc đã tăng lên."],["出席者の名前を書きました。","Tôi đã viết tên những người tham dự."],["出席者は静かに話を聞きました。","Người tham dự đã lặng lẽ lắng nghe."]]},{"word":"料金","reading":"りょうきん","meaning":"Phí","hanViet":"LIỆU KIM","lesson":4,"ex":[["電車の料金はいくらですか。","Giá vé tàu điện là bao nhiêu."],["このホテルの料金は高いです。","Phí khách sạn này đắt."],["料金を払いました。","Tôi đã trả phí."],["映画の料金は安いです。","Giá vé xem phim rẻ."],["料金が高いので、ほかのホテルにしました。","Vì phí đắt nên tôi đã chọn khách sạn khác."]]},{"word":"教科書","reading":"きょうかしょ","meaning":"Giáo trình, sách giáo khoa","hanViet":"GIÁO KHOA THƯ","lesson":5,"ex":[["新しい教科書を買いました。","Tôi đã mua giáo trình mới."],["教科書を忘れました。","Tôi đã quên giáo trình."],["この教科書は日本語の勉強にいいです。","Giáo trình này tốt cho việc học tiếng Nhật."],["教科書を開いてください。","Hãy mở giáo trình ra."],["先生は教科書を使って教えます。","Thầy dạy bằng giáo trình."]]},{"word":"居酒屋","reading":"いざかや","meaning":"Quán nhậu","hanViet":"CƯ TỬU ỐC","lesson":5,"ex":[["友達と居酒屋に行きました。","Tôi đã đi quán nhậu với bạn."],["駅の近くに居酒屋があります。","Gần ga có một quán nhậu."],["居酒屋でやきとりを食べました。","Tôi đã ăn thịt gà nướng xiên ở quán nhậu."],["仕事の後、居酒屋で飲みました。","Sau giờ làm, tôi đã uống ở quán nhậu."],["この居酒屋は安いです。","Quán nhậu này rẻ."]]},{"word":"やきとり","reading":"やきとり","meaning":"Thịt gà nướng xiên","hanViet":"","lesson":5,"ex":[["やきとりはおいしいです。","Thịt gà nướng xiên rất ngon."],["友達とやきとりを食べに行きました。","Tôi đã đi ăn thịt gà nướng xiên với bạn."],["やきとりをたくさん食べました。","Tôi đã ăn nhiều thịt gà nướng xiên."],["彼はやきとりが大好きです。","Anh ấy rất thích thịt gà nướng xiên."],["やきとりを作るのは難しいです。","Làm thịt gà nướng xiên rất khó."]]},{"word":"画面","reading":"がめん","meaning":"Màn hình","hanViet":"HOẠ DIỆN","lesson":5,"ex":[["画面が大きくなりました。","Màn hình đã trở nên lớn hơn."],["テレビの画面を見ています。","Tôi đang xem màn hình ti vi."],["パソコンの画面が明るいです。","Màn hình máy tính sáng."],["画面に写真が出ました。","Ảnh đã hiện lên màn hình."],["画面をきれいにしました。","Tôi đã lau sạch màn hình."]]},{"word":"俳優","reading":"はいゆう","meaning":"Nam diễn viên","hanViet":"BÀI ƯU","lesson":5,"ex":[["あの俳優は有名です。","Nam diễn viên đó nổi tiếng."],["彼は人気の俳優です。","Anh ấy là nam diễn viên nổi tiếng."],["俳優の話を聞きました。","Tôi đã nghe câu chuyện của nam diễn viên."],["私はあの俳優が好きです。","Tôi thích nam diễn viên đó."],["俳優はテレビに出ます。","Nam diễn viên xuất hiện trên ti vi."]]},{"word":"そっくり","reading":"そっくり","meaning":"Giống y đúc, giống hệt","hanViet":"","lesson":5,"ex":[["彼女は母にそっくりです。","Cô ấy giống hệt mẹ."],["弟は父にそっくりです。","Em trai giống hệt bố."],["この絵は写真にそっくりです。","Bức tranh này giống hệt ảnh chụp."],["二人の声はそっくりです。","Giọng của hai người giống hệt nhau."],["彼は兄にそっくりです。","Anh ấy giống hệt anh trai."]]},{"word":"コンビニ","reading":"コンビニ","meaning":"Cửa hàng tiện lợi","hanViet":"","lesson":5,"ex":[["コンビニでパンを買いました。","Tôi đã mua bánh mì ở cửa hàng tiện lợi."],["駅の近くにコンビニがあります。","Gần ga có một cửa hàng tiện lợi."],["コンビニは夜も開いています。","Cửa hàng tiện lợi mở cả ban đêm."],["コンビニでお金を払いました。","Tôi đã trả tiền ở cửa hàng tiện lợi."],["コンビニはとても便利です。","Cửa hàng tiện lợi rất tiện."]]},{"word":"改札口","reading":"かいさつぐち","meaning":"Cửa soát vé","hanViet":"CẢI TRÁT KHẨU","lesson":5,"ex":[["改札口で友達に会いました。","Tôi đã gặp bạn ở cửa soát vé."],["改札口を通りました。","Tôi đã đi qua cửa soát vé."],["改札口の前で待ちました。","Tôi đã đợi trước cửa soát vé."],["改札口は駅の中にあります。","Cửa soát vé nằm trong ga."],["改札口に人が多くいます。","Ở cửa soát vé có nhiều người."]]},{"word":"運転者","reading":"うんてんしゃ","meaning":"Tài xế","hanViet":"VẬN CHUYỂN GIẢ","lesson":5,"ex":[["運転者はバスを運転します。","Tài xế lái xe buýt."],["運転者は親切な人でした。","Tài xế là người tốt bụng."],["運転者に道を聞きました。","Tôi đã hỏi đường tài xế."],["運転者は毎日忙しいです。","Tài xế ngày nào cũng bận."],["バスの運転者は日本語が上手です。","Tài xế xe buýt giỏi tiếng Nhật."]]},{"word":"かかってくる","reading":"かかってくる","meaning":"Điện thoại đổ chuông, gọi đến","hanViet":"","lesson":5,"ex":[["友達から電話がかかってきました。","Bạn tôi đã gọi điện đến."],["夜に電話がかかってきました。","Ban đêm có điện thoại gọi đến."],["会社から電話がかかってきました。","Công ty đã gọi điện đến."],["母から電話がかかってきました。","Mẹ đã gọi điện đến."],["毎朝、電話がかかってきます。","Mỗi sáng đều có điện thoại gọi đến."]]},{"word":"切れる","reading":"きれる","meaning":"Cuộc gọi bị ngắt, bị cúp","hanViet":"THIẾT","lesson":5,"ex":[["電話が切れました。","Cuộc gọi đã bị ngắt."],["話している途中で電話が切れました。","Cuộc gọi bị ngắt giữa chừng khi đang nói chuyện."],["電話が切れて、困りました。","Cuộc gọi bị ngắt nên tôi gặp khó khăn."],["電話が切れたので、後でかけました。","Vì cuộc gọi bị ngắt nên tôi đã gọi lại sau."],["電話が切れる前に、名前を聞きました。","Trước khi cuộc gọi bị ngắt, tôi đã hỏi tên."]]},{"word":"挙げる","reading":"あげる","meaning":"Đưa ra, cho ví dụ","hanViet":"CỬ","lesson":5,"ex":[["彼は三つの理由を挙げました。","Anh ấy đã đưa ra ba lý do."],["先生はいい理由を挙げました。","Thầy đã đưa ra lý do hay."],["彼女は意見を挙げました。","Cô ấy đã đưa ra ý kiến."],["答えを挙げてください。","Hãy đưa ra câu trả lời."],["私は二つの問題を挙げました。","Tôi đã đưa ra hai vấn đề."]]},{"word":"未来","reading":"みらい","meaning":"Tương lai","hanViet":"VỊ LAI","lesson":5,"ex":[["未来の日本は便利になります。","Nhật Bản trong tương lai sẽ trở nên tiện lợi."],["子供たちの未来は明るいです。","Tương lai của trẻ em tươi sáng."],["未来のために、勉強しています。","Tôi học vì tương lai."],["未来の仕事について考えています。","Tôi đang suy nghĩ về công việc tương lai."],["未来はわかりません。","Không ai biết tương lai ra sao."]]},{"word":"なくす","reading":"なくす","meaning":"Xóa bỏ, loại bỏ chiến tranh","hanViet":"","lesson":5,"ex":[["戦争をなくすことが大切です。","Xóa bỏ chiến tranh là điều quan trọng."],["世界から戦争をなくしましょう。","Hãy cùng xóa bỏ chiến tranh khỏi thế giới."],["間違いをなくすために、よく見ます。","Để không còn sai sót, tôi xem kỹ."],["病気をなくすことはできません。","Không thể xóa bỏ bệnh tật."],["事故をなくすために、安全に運転します。","Để không còn tai nạn, tôi lái xe an toàn."]]},{"word":"不思議","reading":"ふしぎ","meaning":"Kỳ lạ","hanViet":"BẤT TƯ NGHỊ","lesson":5,"ex":[["不思議な話を聞きました。","Tôi đã nghe câu chuyện kỳ lạ."],["彼は不思議な人です。","Anh ấy là người kỳ lạ."],["不思議な夢を見ました。","Tôi đã mơ giấc mơ kỳ lạ."],["この町の名前は不思議です。","Tên của thị trấn này thật kỳ lạ."],["不思議な音が聞こえました。","Tôi đã nghe thấy âm thanh kỳ lạ."]]},{"word":"増やす","reading":"ふやす","meaning":"Tăng","hanViet":"TĂNG","lesson":5,"ex":[["友達を増やしたいです。","Tôi muốn có thêm nhiều bạn."],["本を増やしました。","Tôi đã tăng số sách."],["勉強する時間を増やしました。","Tôi đã tăng thời gian học."],["お金を増やすのは難しいです。","Tăng tiền thật khó."],["仕事を増やしました。","Tôi đã tăng thêm việc làm."]]},{"word":"今ごろ","reading":"いまごろ","meaning":"Tầm này, giờ này","hanViet":"KIM","lesson":5,"ex":[["今ごろ、友達は東京にいます。","Giờ này, bạn tôi đang ở Tokyo."],["今ごろ、母は何をしていますか。","Giờ này mẹ đang làm gì."],["今ごろ、雨が降っていますか。","Giờ này trời đang mưa không."],["今ごろ、彼は家で休んでいます。","Giờ này, anh ấy đang nghỉ ngơi ở nhà."],["今ごろ、日本は夜です。","Giờ này, Nhật Bản đang là ban đêm."]]},{"word":"観光客","reading":"かんこうきゃく","meaning":"Du khách, khách du lịch","hanViet":"QUAN QUANG KHÁCH","lesson":5,"ex":[["京都には毎年多くの観光客が来ます。","Mỗi năm có nhiều du khách đến Kyoto."],["観光客はこの店でお土産を買います。","Du khách mua quà lưu niệm ở cửa hàng này."],["春になると、観光客が増えます。","Khi sang xuân, du khách tăng lên."],["観光客に道を聞かれました。","Tôi đã bị du khách hỏi đường."],["この町は観光客に人気があります。","Thị trấn này được du khách yêu thích."]]},{"word":"沿う","reading":"そう","meaning":"Dọc theo, men theo","hanViet":"DUYÊN","lesson":5,"ex":[["この道は川に沿って進みます。","Con đường này chạy dọc theo sông."],["川に沿って歩くと、公園があります。","Đi bộ dọc theo sông sẽ thấy công viên."],["電車は海に沿って走ります。","Tàu chạy dọc theo biển."],["線路に沿って歩いてはいけません。","Không được đi bộ dọc theo đường ray."],["山に沿って細い道があります。","Dọc theo núi có một con đường hẹp."]]},{"word":"大通り","reading":"おおどおり","meaning":"Phố chính, đường lớn, đại lộ","hanViet":"ĐẠI THÔNG","lesson":5,"ex":[["大通りをまっすぐ行くと、駅があります。","Đi thẳng đại lộ sẽ tới ga."],["この大通りは夜も明るいです。","Đại lộ này ban đêm cũng sáng."],["大通りには店がたくさんあります。","Trên đại lộ có nhiều cửa hàng."],["大通りを右に曲がってください。","Hãy rẽ phải ở đại lộ."],["車は大通りをたくさん通ります。","Nhiều xe đi qua đại lộ."]]},{"word":"横断歩道","reading":"おうだんほどう","meaning":"Lối qua đường cho người đi bộ (vạch sang đường)","hanViet":"HOÀNH ĐOẠN BỘ ĐẠO","lesson":5,"ex":[["横断歩道を渡るときは、車に気をつけてください。","Khi qua đường dành cho người đi bộ, hãy chú ý xe."],["横断歩道で信号が青になるのを待ちました。","Tôi đã đợi đèn xanh ở đường dành cho người đi bộ."],["子どもは横断歩道を走って渡りました。","Đứa trẻ chạy qua đường dành cho người đi bộ."],["横断歩道の前で車が止まりました。","Xe đã dừng trước đường dành cho người đi bộ."],["横断歩道がない所では、道を渡ってはいけません。","Ở nơi không có đường dành cho người đi bộ thì không được qua đường."]]},{"word":"突き当り","reading":"つきあたり","meaning":"Cuối đường","hanViet":"ĐỘT ĐƯƠNG","lesson":5,"ex":[["この道の突き当りに公園があります。","Ở cuối đường này có công viên."],["突き当りを左に曲がると、学校です。","Rẽ trái ở cuối đường là trường học."],["突き当りの家に田中さんが住んでいます。","Anh Tanaka sống ở ngôi nhà cuối đường."],["道の突き当りまで歩きました。","Tôi đã đi bộ đến cuối đường."],["突き当りには小さい神社があります。","Ở cuối đường có một ngôi đền nhỏ."]]},{"word":"線路","reading":"せんろ","meaning":"Đường ray","hanViet":"TUYẾN LỘ","lesson":5,"ex":[["線路の近くに家を建ててはいけません。","Không được xây nhà gần đường ray."],["電車が線路を走ります。","Tàu chạy trên đường ray."],["線路の向こう側に学校があります。","Phía bên kia đường ray có trường học."],["線路に入ると、危ないです。","Vào đường ray rất nguy hiểm."],["線路の下に川があります。","Dưới đường ray có sông."]]},{"word":"向こう側","reading":"むこうがわ","meaning":"Phía đối diện","hanViet":"HƯỚNG TRẮC","lesson":5,"ex":[["川の向こう側に山が見えます。","Phía bên kia sông nhìn thấy núi."],["道の向こう側にコンビニがあります。","Phía đối diện đường có cửa hàng tiện lợi."],["向こう側の席に座ってください。","Hãy ngồi vào ghế phía đối diện."],["線路の向こう側から電車が来ました。","Tàu đã đến từ phía bên kia đường ray."],["向こう側の建物は何ですか。","Tòa nhà phía đối diện là gì?"]]},{"word":"踏切","reading":"ふみきり","meaning":"Đường ngang điểm giao cắt giữa đường sắt và đường bộ","hanViet":"ĐẠP THIẾT","lesson":5,"ex":[["踏切では、電車が来ないかよく見てください。","Ở đường ngang, hãy nhìn kỹ xem tàu có đến không."],["踏切の前で車が止まりました。","Xe đã dừng trước đường ngang."],["踏切を渡るときは、気をつけてください。","Khi qua đường ngang, hãy cẩn thận."],["踏切の音が聞こえます。","Nghe thấy tiếng chuông báo ở đường ngang."],["毎朝、踏切で電車を待ちます。","Mỗi sáng, tôi đợi tàu ở đường ngang."]]},{"word":"分かれる","reading":"わかれる","meaning":"Đường tách ra, phân ra","hanViet":"PHÂN","lesson":5,"ex":[["道はここで二つに分かれます。","Đường chia làm hai ở đây."],["川はここで二つに分かれています。","Sông chia làm hai ở đây."],["この道は駅の前で分かれます。","Con đường này tách ra trước ga."],["卒業して、友だちと分かれました。","Sau khi tốt nghiệp, tôi đã chia tay bạn bè."],["グループは三つに分かれて、勉強しました。","Nhóm chia làm ba để học."]]},{"word":"芸術","reading":"げいじゅつ","meaning":"Nghệ thuật","hanViet":"NGHỆ THUẬT","lesson":5,"ex":[["芸術が好きな人は、この美術館に行きます。","Người thích nghệ thuật sẽ đến bảo tàng mỹ thuật này."],["私は芸術について勉強しています。","Tôi đang học về nghệ thuật."],["芸術は国や時代で変わります。","Nghệ thuật thay đổi theo đất nước và thời đại."],["この町は芸術で有名です。","Thị trấn này nổi tiếng về nghệ thuật."],["子どものときから、芸術に興味があります。","Từ khi còn nhỏ, tôi đã có hứng thú với nghệ thuật."]]},{"word":"道順","reading":"みちじゅん","meaning":"Cách đi, lộ trình đi","hanViet":"ĐẠO THUẬN","lesson":5,"ex":[["駅までの道順を教えてください。","Hãy chỉ cho tôi cách đi đến ga."],["道順が分からないので、地図を見ました。","Vì không biết cách đi nên tôi đã xem bản đồ."],["先生が道順を説明しました。","Thầy đã giải thích cách đi."],["道順をまちがえて、遅れました。","Tôi đã đi sai đường nên đến muộn."],["道順を紙に書きました。","Tôi đã viết cách đi ra giấy."]]},{"word":"通行人","reading":"つうこうにん","meaning":"Người qua đường","hanViet":"THÔNG HÀNH NHÂN","lesson":5,"ex":[["通行人に道を聞きました。","Tôi đã hỏi đường người qua đường."],["通行人がたくさん歩いています。","Nhiều người qua đường đang đi bộ."],["通行人は信号を守ります。","Người qua đường tuân thủ đèn giao thông."],["雨の日は通行人が少ないです。","Ngày mưa ít người qua đường."],["通行人に助けてもらいました。","Tôi đã được người qua đường giúp đỡ."]]},{"word":"通り","reading":"とおり","meaning":"Đường, phố","hanViet":"THÔNG","lesson":5,"ex":[["この通りには店がたくさんあります。","Trên phố này có nhiều cửa hàng."],["通りを歩くと、花が見えます。","Đi bộ trên phố sẽ thấy hoa."],["通りの名前を知っていますか。","Bạn có biết tên phố không?"],["静かな通りに家があります。","Nhà tôi ở trên một con phố yên tĩnh."],["通りを右に曲がってください。","Hãy rẽ phải ở phố này."]]},{"word":"川沿い","reading":"かわぞい","meaning":"Dọc theo con sông","hanViet":"XUYÊN DUYÊN","lesson":5,"ex":[["川沿いに公園があります。","Dọc theo sông có công viên."],["川沿いを歩くのが好きです。","Tôi thích đi bộ dọc theo sông."],["川沿いの道は静かです。","Con đường dọc sông rất yên tĩnh."],["川沿いに桜の木があります。","Dọc sông có cây hoa anh đào."],["川沿いを自転車で走りました。","Tôi đã đạp xe dọc sông."]]},{"word":"～沿い","reading":"～ぞい","meaning":"Dọc theo ～","hanViet":"DUYÊN","lesson":5,"ex":[["海沿いにホテルがたくさんあります。","Dọc biển có nhiều khách sạn."],["線路沿いに家が並んでいます。","Dọc đường ray nhà cửa xếp san sát."],["道沿いに花が咲いています。","Dọc đường hoa đang nở."],["海沿いのレストランで食事をしました。","Tôi đã ăn ở nhà hàng dọc biển."],["山沿いの道は細いです。","Đường dọc núi rất hẹp."]]},{"word":"流れる","reading":"ながれる","meaning":"Chảy","hanViet":"LƯU","lesson":5,"ex":[["川の水は海に流れます。","Nước sông chảy ra biển."],["涙が流れました。","Nước mắt đã chảy."],["川は静かに流れています。","Sông đang chảy lặng lẽ."],["時間は早く流れます。","Thời gian trôi nhanh."],["音楽が部屋に流れています。","Nhạc đang vang trong phòng."]]},{"word":"～方","reading":"～ほう","meaning":"Phía ～, hướng ～","hanViet":"PHƯƠNG","lesson":5,"ex":[["駅はあちらの方です。","Ga ở phía bên kia."],["右の方にコンビニがあります。","Phía bên phải có cửa hàng tiện lợi."],["左の方を見てください。","Hãy nhìn về phía bên trái."],["山の方から風が吹きます。","Gió thổi từ phía núi."],["どちらの方に行きますか。","Bạn đi về phía nào?"]]},{"word":"南北","reading":"なんぼく","meaning":"Nam bắc","hanViet":"NAM BẮC","lesson":5,"ex":[["日本は南北に長い国です。","Nhật Bản là đất nước dài theo hướng nam bắc."],["南北の気温は違います。","Nhiệt độ phía nam và phía bắc khác nhau."],["この道は南北に走っています。","Con đường này chạy theo hướng nam bắc."],["南北に長い国では、気候が変わります。","Ở đất nước dài theo hướng nam bắc, khí hậu thay đổi."],["地図で南北を調べました。","Tôi đã tra hướng nam bắc trên bản đồ."]]},{"word":"逆","reading":"ぎゃく","meaning":"Ngược lại","hanViet":"NGHỊCH","lesson":5,"ex":[["逆に考えてみてください。","Hãy thử nghĩ ngược lại."],["靴を逆にはきました。","Tôi đã đi giày ngược."],["逆の方向に行ってしまいました。","Tôi đã đi nhầm hướng ngược lại."],["晴れた日は人が少ないです。逆に、雨の日は人が多いです。","Ngày nắng thì ít người. Ngược lại, ngày mưa người đông."],["本を逆に持ちました。","Tôi đã cầm sách ngược."]]},{"word":"南半球","reading":"みなみはんきゅう","meaning":"Nam bán cầu","hanViet":"NAM BÁN CẦU","lesson":5,"ex":[["南半球の天気は日本と逆です。","Thời tiết Nam bán cầu ngược với Nhật Bản."],["南半球では、季節が逆です。","Ở Nam bán cầu, mùa ngược lại."],["南半球の国に旅行したいです。","Tôi muốn du lịch đến nước ở Nam bán cầu."],["南半球では、十二月に夏が来ます。","Ở Nam bán cầu, tháng 12 là mùa hè."],["南半球と北半球では、見える星が違います。","Ở Nam bán cầu và Bắc bán cầu, sao nhìn thấy khác nhau."]]},{"word":"北半球","reading":"きたはんきゅう","meaning":"Bắc bán cầu","hanViet":"BẮC BÁN CẦU","lesson":5,"ex":[["日本は北半球にあります。","Nhật Bản ở Bắc bán cầu."],["北半球では、十二月に冬が来ます。","Ở Bắc bán cầu, tháng 12 là mùa đông."],["北半球には国がたくさんあります。","Ở Bắc bán cầu có nhiều nước."],["北半球と南半球では、季節が逆です。","Ở Bắc bán cầu và Nam bán cầu, mùa ngược nhau."],["北半球では、夏に日が長くなります。","Ở Bắc bán cầu, mùa hè ngày dài hơn."]]},{"word":"常識","reading":"じょうしき","meaning":"Thường thức, ứng xử thông thường","hanViet":"THƯỜNG THỨC","lesson":5,"ex":[["これは常識です。","Đây là thường thức."],["常識ですから、知っておいてください。","Đây là thường thức nên hãy ghi nhớ nhé."],["国によって、常識が違います。","Thường thức khác nhau tùy theo đất nước."],["常識がないと、仕事で困ります。","Không có thường thức thì sẽ gặp khó khăn trong công việc."],["子どもに常識を教えます。","Tôi dạy thường thức cho trẻ em."]]},{"word":"差別","reading":"さべつ","meaning":"Sự phân biệt đối xử","hanViet":"SAI BIỆT","lesson":5,"ex":[["差別はいけません。","Phân biệt đối xử là không được."],["差別をなくすために、努力します。","Tôi cố gắng để xóa bỏ phân biệt đối xử."],["仕事で差別がありました。","Ở chỗ làm đã có phân biệt đối xử."],["差別について話しました。","Chúng tôi đã nói về phân biệt đối xử."],["差別は社会の問題です。","Phân biệt đối xử là vấn đề của xã hội."]]},{"word":"平等","reading":"びょうどう","meaning":"Bình đẳng","hanViet":"BÌNH ĐẲNG","lesson":5,"ex":[["人はみんな平等です。","Mọi người đều bình đẳng."],["男の人も女の人も平等です。","Đàn ông và phụ nữ đều bình đẳng."],["子どもはみんな平等です。","Trẻ em đều bình đẳng."],["学校では、子どもを平等に教えます。","Ở trường, trẻ em được dạy bình đẳng."],["平等な社会を作りたいです。","Tôi muốn tạo ra xã hội bình đẳng."]]},{"word":"位置","reading":"いち","meaning":"Vị trí","hanViet":"VỊ TRÍ","lesson":5,"ex":[["位置を地図で調べました。","Tôi đã tra vị trí trên bản đồ."],["この店の位置を教えてください。","Hãy cho tôi biết vị trí của cửa hàng này."],["位置が分かりません。","Tôi không biết vị trí."],["家の位置は駅の近くです。","Vị trí nhà tôi gần ga."],["位置によって、値段が変わります。","Giá thay đổi tùy theo vị trí."]]},{"word":"人間","reading":"にんげん","meaning":"Con người","hanViet":"NHÂN GIAN","lesson":5,"ex":[["人間は社会で生活します。","Con người sống trong xã hội."],["人間は言葉で話します。","Con người nói chuyện bằng ngôn ngữ."],["人間は大切なことを学びます。","Con người học được những điều quan trọng."],["人間は一人では生きられません。","Con người không thể sống một mình."],["人間の体は不思議です。","Cơ thể con người thật kỳ diệu."]]},{"word":"観察する","reading":"かんさつする","meaning":"Quan sát","hanViet":"QUAN SÁT","lesson":5,"ex":[["子どもは虫を観察しています。","Trẻ em đang quan sát côn trùng."],["先生は星を観察します。","Thầy quan sát các ngôi sao."],["花を観察して、ノートに書きました。","Tôi đã quan sát hoa và viết vào vở."],["人間を観察するのが好きです。","Tôi thích quan sát con người."],["毎日、空を観察しています。","Mỗi ngày tôi quan sát bầu trời."]]},{"word":"面","reading":"めん","meaning":"Mặt, bề mặt","hanViet":"DIỆN","lesson":5,"ex":[["テーブルの面は大きいです。","Mặt bàn lớn."],["この面に字を書いてください。","Hãy viết chữ lên mặt này."],["海の面は青いです。","Mặt biển màu xanh."],["この箱の面に名前を書きました。","Tôi đã viết tên lên mặt hộp này."],["この面は白いです。","Mặt này màu trắng."]]},{"word":"中央","reading":"ちゅうおう","meaning":"Trung tâm","hanViet":"TRUNG ƯƠNG","lesson":5,"ex":[["中央に駅があります。","Ở trung tâm có ga."],["町の中央に公園があります。","Ở trung tâm thị trấn có công viên."],["中央の席に座りました。","Tôi đã ngồi ghế ở giữa."],["教室の中央に机があります。","Ở giữa lớp học có bàn."],["中央に大きな木があります。","Ở trung tâm có cây to."]]},{"word":"自然に","reading":"しぜんに","meaning":"Một cách tự nhiên, bất giác","hanViet":"TỰ NHIÊN","lesson":5,"ex":[["自然に笑いました。","Tôi đã cười một cách tự nhiên."],["日本語が自然に話せるようになりました。","Tôi đã có thể nói tiếng Nhật một cách tự nhiên."],["自然に眠くなりました。","Tôi đã buồn ngủ một cách tự nhiên."],["自然に体が動きました。","Cơ thể tôi đã tự động cử động."],["自然に元気になりました。","Tôi đã tự nhiên khỏe lại."]]},{"word":"努力する","reading":"どりょくする","meaning":"Nỗ lực, cố gắng","hanViet":"NỖ LỰC","lesson":5,"ex":[["努力して、日本語を勉強します。","Tôi cố gắng học tiếng Nhật."],["毎日努力しています。","Mỗi ngày tôi đều nỗ lực."],["努力すれば、できます。","Nếu cố gắng thì sẽ làm được."],["努力することが大切です。","Nỗ lực là quan trọng."],["彼は努力して、試験に合格しました。","Anh ấy đã nỗ lực và đỗ kỳ thi."]]},{"word":"そこで","reading":"そこで","meaning":"Vì thế, vì vậy","hanViet":"","lesson":5,"ex":[["雨が降りました。そこで、家に帰りました。","Trời đã mưa. Vì thế, tôi đã về nhà."],["道が分かりません。そこで、地図を見ました。","Tôi không biết đường. Vì thế, tôi đã xem bản đồ."],["お金がありません。そこで、アルバイトを始めました。","Tôi không có tiền. Vì thế, tôi đã bắt đầu làm thêm."],["日本語が話せません。そこで、勉強を始めました。","Tôi không nói được tiếng Nhật. Vì thế, tôi đã bắt đầu học."],["電車が止まりました。そこで、バスで帰りました。","Tàu đã dừng. Vì thế, tôi đã về bằng xe buýt."]]},{"word":"普通","reading":"ふつう","meaning":"Bình thường, thông thường","hanViet":"PHỔ THÔNG","lesson":5,"ex":[["普通の生活が一番です。","Cuộc sống bình thường là tốt nhất."],["普通は八時に起きます。","Bình thường tôi dậy lúc 8 giờ."],["この店は普通の店です。","Cửa hàng này là cửa hàng bình thường."],["今日は普通の日です。","Hôm nay là một ngày bình thường."],["普通の日曜日は家で休みます。","Ngày chủ nhật bình thường tôi nghỉ ở nhà."]]},{"word":"経緯度","reading":"けいいど","meaning":"Kinh độ và vĩ độ","hanViet":"KINH VĨ ĐỘ","lesson":5,"ex":[["経緯度を調べました。","Tôi đã tra kinh độ và vĩ độ."],["この町の経緯度を知っていますか。","Bạn có biết kinh độ và vĩ độ của thị trấn này không?"],["地図に経緯度が書いてあります。","Trên bản đồ có ghi kinh độ và vĩ độ."],["経緯度で位置が分かります。","Nhờ kinh độ và vĩ độ mà biết được vị trí."],["船は経緯度を使って進みます。","Tàu dùng kinh độ và vĩ độ để đi."]]},{"word":"無意識に","reading":"むいしきに","meaning":"Vô thức, không chủ ý","hanViet":"VÔ Ý THỨC","lesson":5,"ex":[["無意識に歌を歌っていました。","Tôi đã hát một cách vô thức."],["無意識にドアを開けました。","Tôi đã mở cửa một cách vô thức."],["無意識に日本語で話しました。","Tôi đã nói tiếng Nhật một cách vô thức."],["無意識に笑っていました。","Tôi đã cười một cách vô thức."],["無意識に同じ道を歩きました。","Tôi đã đi cùng một con đường một cách vô thức."]]},{"word":"表れ","reading":"あらわれ","meaning":"Biểu hiện","hanViet":"BIỂU","lesson":5,"ex":[["顔は心の表れです。","Khuôn mặt là biểu hiện của trái tim."],["日本語が上手になったのは、努力の表れです。","Tiếng Nhật giỏi lên là biểu hiện của nỗ lực."],["その言葉は気持ちの表れです。","Lời nói đó là biểu hiện của cảm xúc."],["祭りで文化の表れを見ました。","Tôi đã thấy biểu hiện của văn hóa ở lễ hội."],["顔の表れで気持ちが分かります。","Nhờ biểu hiện trên khuôn mặt mà biết được cảm xúc."]]},{"word":"上下","reading":"じょうげ","meaning":"Trên dưới","hanViet":"THƯỢNG HẠ","lesson":5,"ex":[["上下に動かしてください。","Hãy di chuyển lên xuống."],["上下の関係が大切です。","Quan hệ trên dưới rất quan trọng."],["エレベーターは上下に動きます。","Thang máy di chuyển lên xuống."],["上下をまちがえました。","Tôi đã nhầm trên dưới."],["階段を上下しました。","Tôi đã lên xuống cầu thang."]]},{"word":"左右","reading":"さゆう","meaning":"Trái phải","hanViet":"TẢ HỮU","lesson":5,"ex":[["左右を見て、道を渡ります。","Nhìn trái phải rồi qua đường."],["左右に手を出しました。","Tôi đã đưa tay sang trái phải."],["左右の靴をまちがえました。","Tôi đã đi nhầm giày trái phải."],["左右に分かれて、座りました。","Chúng tôi chia trái phải để ngồi."],["左右の手を使います。","Tôi dùng tay trái phải."]]},{"word":"少なくとも","reading":"すくなくとも","meaning":"Ít nhất thì","hanViet":"TIỂU","lesson":5,"ex":[["少なくとも三日はかかります。","Ít nhất cũng mất ba ngày."],["少なくとも一時間は勉強します。","Ít nhất tôi học một tiếng."],["少なくとも千円は必要です。","Ít nhất cần một nghìn yên."],["少なくとも週に一度は運動します。","Ít nhất mỗi tuần tôi tập thể dục một lần."],["少なくとも五人は来ます。","Ít nhất năm người sẽ đến."]]},{"word":"文句","reading":"もんく","meaning":"Phàn nàn, than phiền","hanViet":"VĂN CÚ","lesson":5,"ex":[["文句を言ってはいけません。","Không được phàn nàn."],["彼はよく文句を言います。","Anh ấy hay phàn nàn."],["文句があるなら、言ってください。","Nếu có điều phàn nàn, hãy nói ra."],["文句を言わないで、働きました。","Tôi đã làm việc mà không phàn nàn."],["文句を言う人が多いです。","Có nhiều người hay phàn nàn."]]},{"word":"わざと","reading":"わざと","meaning":"Chủ ý, cố tình","hanViet":"","lesson":5,"ex":[["わざと遅れました。","Tôi đã cố tình đến muộn."],["わざとまちがえました。","Tôi đã cố tình làm sai."],["わざと大きな声で話しました。","Tôi đã cố tình nói to."],["わざとじゃないです。","Không phải cố tình."],["わざと静かにしました。","Tôi đã cố tình im lặng."]]},{"word":"経度","reading":"けいど","meaning":"Kinh độ","hanViet":"KINH ĐỘ","lesson":5,"ex":[["経度を調べました。","Tôi đã tra kinh độ."],["東京の経度は百三十九度です。","Kinh độ của Tokyo là 139 độ."],["経度と緯度で位置が分かります。","Nhờ kinh độ và vĩ độ mà biết vị trí."],["経度が違えば、時間が違います。","Kinh độ khác nhau thì thời gian khác nhau."],["地図に経度が書いてあります。","Trên bản đồ có ghi kinh độ."]]},{"word":"緯度","reading":"いど","meaning":"Vĩ độ","hanViet":"VĨ ĐỘ","lesson":5,"ex":[["緯度を調べました。","Tôi đã tra vĩ độ."],["緯度が高い所は寒いです。","Nơi vĩ độ cao thì lạnh."],["緯度と経度で位置が分かります。","Nhờ vĩ độ và kinh độ mà biết vị trí."],["この町の緯度を知っていますか。","Bạn có biết vĩ độ của thị trấn này không?"],["緯度が低い所は暖かいです。","Nơi vĩ độ thấp thì ấm."]]},{"word":"使用する","reading":"しようする","meaning":"Sử dụng","hanViet":"SỬ DỤNG","lesson":5,"ex":[["この部屋は使用中です。","Phòng này đang được sử dụng."],["パソコンを使用します。","Tôi sử dụng máy tính."],["使用する前に、説明を読んでください。","Trước khi sử dụng, hãy đọc hướng dẫn."],["この薬を使用してください。","Hãy sử dụng thuốc này."],["辞書を使用して、勉強します。","Tôi học bằng cách sử dụng từ điển."]]},{"word":"東西","reading":"とうざい","meaning":"Đông tây","hanViet":"ĐÔNG TÂY","lesson":5,"ex":[["この国は東西に長いです。","Đất nước này dài theo hướng đông tây."],["東西の文化は違います。","Văn hóa đông tây khác nhau."],["この道は東西に走っています。","Con đường này chạy theo hướng đông tây."],["東西の空を見ました。","Tôi đã nhìn bầu trời phía đông và phía tây."],["地図で東西を調べました。","Tôi đã tra hướng đông tây trên bản đồ."]]},{"word":"一期一会","reading":"いちごいちえ","meaning":"Gặp một lần để nhớ nhau mãi mãi, đời người chỉ gặp một lần","hanViet":"NHẤT KÌ NHẤT HỘI","lesson":6,"ex":[["一期一会の気持ちで会いました。","Tôi đã gặp với tâm trạng một lần trong đời."],["一期一会を大切にします。","Tôi trân trọng một lần gặp trong đời."],["旅行で会った人との時間は一期一会です。","Thời gian với người gặp trong chuyến du lịch là một lần trong đời."],["一期一会だから、この時間を大切にします。","Vì là một lần trong đời nên tôi trân trọng thời gian này."],["一期一会の言葉が好きです。","Tôi thích câu nói một lần gặp trong đời."]]},{"word":"フクロウ","reading":"フクロウ","meaning":"Con cú","hanViet":"","lesson":6,"ex":[["フクロウは夜に起きます。","Cú thức dậy vào ban đêm."],["森でフクロウを見ました。","Tôi đã thấy cú trong rừng."],["フクロウの目が大きいです。","Mắt cú rất to."],["フクロウは鳥です。","Cú là chim."],["フクロウの声が聞こえます。","Nghe thấy tiếng cú."]]},{"word":"学ぶ","reading":"まなぶ","meaning":"Học","hanViet":"HỌC","lesson":6,"ex":[["日本語を学びます。","Tôi học tiếng Nhật."],["歴史から学ぶことが多いです。","Có nhiều điều học được từ lịch sử."],["友だちから学ぶことが多いです。","Có nhiều điều học được từ bạn bè."],["先生から大切なことを学びました。","Tôi đã học điều quan trọng từ thầy."],["子どもは遊びながら学びます。","Trẻ em học trong khi chơi."]]},{"word":"一生","reading":"いっしょう","meaning":"Suốt cuộc đời, cả đời","hanViet":"NHẤT SANH","lesson":6,"ex":[["一生忘れません。","Suốt đời tôi không quên."],["一生大切にします。","Tôi trân trọng suốt đời."],["一生日本に住みたいです。","Tôi muốn sống ở Nhật suốt đời."],["一生の仕事です。","Đó là công việc suốt đời."],["一生の友だちができました。","Tôi đã có người bạn suốt đời."]]},{"word":"店員","reading":"てんいん","meaning":"Nhân viên cửa hàng","hanViet":"ĐIẾM VIÊN","lesson":6,"ex":[["店員に聞きました。","Tôi đã hỏi nhân viên cửa hàng."],["店員は親切です。","Nhân viên cửa hàng rất thân thiện."],["店員が元気に迎えました。","Nhân viên cửa hàng đón tiếp vui vẻ."],["店員に値段を聞きました。","Tôi đã hỏi giá nhân viên cửa hàng."],["この店の店員です。","Tôi là nhân viên của cửa hàng này."]]},{"word":"就職する","reading":"しゅうしょくする","meaning":"Xin việc","hanViet":"TỰU CHỨC","lesson":6,"ex":[["大学を卒業して、就職します。","Tốt nghiệp đại học rồi xin việc."],["東京の会社に就職しました。","Tôi đã xin việc ở công ty tại Tokyo."],["就職するために、勉強しています。","Tôi đang học để xin việc."],["来年、就職する予定です。","Năm sau tôi dự định xin việc."],["就職が決まりました。","Việc làm đã quyết định xong."]]},{"word":"自分では","reading":"じぶんでは","meaning":"Tự tôi, tự bản thân","hanViet":"TỰ PHÂN","lesson":6,"ex":[["自分ではできません。手伝ってください。","Tự tôi không làm được. Hãy giúp tôi."],["自分では分かりません。教えてください。","Tự tôi không biết. Hãy chỉ cho tôi."],["自分では決められません。相談します。","Tự tôi không quyết định được. Tôi sẽ bàn bạc."],["自分では作れません。店で買います。","Tự tôi không làm được. Tôi mua ở cửa hàng."],["自分では直せません。新しいのを買います。","Tự tôi không sửa được. Tôi mua cái mới."]]},{"word":"ゲーム","reading":"ゲーム","meaning":"Game, trò chơi","hanViet":"","lesson":6,"ex":[["ゲームをするのが好きです。","Tôi thích chơi game."],["友だちとゲームをしました。","Tôi đã chơi game với bạn."],["ゲームの時間が長いです。","Thời gian chơi game dài."],["新しいゲームを買いました。","Tôi đã mua game mới."],["ゲームで遊びました。","Tôi đã chơi game."]]},{"word":"うがい","reading":"うがい","meaning":"Súc miệng","hanViet":"","lesson":6,"ex":[["うがいをします。","Tôi súc miệng."],["外から帰ったら、うがいをします。","Về nhà từ bên ngoài, tôi súc miệng."],["うがいをして、口をきれいにします。","Tôi súc miệng để làm sạch miệng."],["毎日、うがいをしています。","Mỗi ngày tôi súc miệng."],["うがいをしてから、寝ます。","Tôi súc miệng rồi đi ngủ."]]},{"word":"ビタミンシー","reading":"ビタミンシー","meaning":"Vitamin C","hanViet":"","lesson":6,"ex":[["ビタミンシーをとります。","Tôi uống vitamin C."],["ビタミンシーは体にいいです。","Vitamin C tốt cho cơ thể."],["毎日、ビタミンシーをとっています。","Mỗi ngày tôi uống vitamin C."],["ビタミンシーが多い果物を食べます。","Tôi ăn trái cây nhiều vitamin C."],["風邪のとき、ビタミンシーをとります。","Khi bị cảm, tôi uống vitamin C."]]},{"word":"とる","reading":"とる","meaning":"Lấy, dùng, uống (thuốc/vitamin), chụp (ảnh), giữ (chỗ), nghỉ (phép)","hanViet":"","lesson":6,"ex":[["毎日、薬をとります。","Mỗi ngày tôi uống thuốc."],["ビタミンシーをとって、元気になりました。","Tôi đã uống vitamin C nên khỏe lại."],["写真をとりました。","Tôi đã chụp ảnh."],["席をとってください。","Hãy giữ chỗ giúp tôi."],["休みをとります。","Tôi nghỉ phép."]]},{"word":"遠く","reading":"とおく","meaning":"Xa","hanViet":"VIỄN","lesson":6,"ex":[["遠くに山が見えます。","Xa xa nhìn thấy núi."],["遠くから来ました。","Tôi đã đến từ xa."],["遠くの国に行きたいです。","Tôi muốn đến đất nước xa xôi."],["遠くまで歩きました。","Tôi đã đi bộ rất xa."],["遠くの友だちに手紙を書きました。","Tôi đã viết thư cho bạn ở xa."]]},{"word":"太鼓","reading":"たいこ","meaning":"Trống","hanViet":"THÁI CỔ","lesson":6,"ex":[["太鼓をたたきます。","Tôi đánh trống."],["祭りで太鼓をたたきました。","Tôi đã đánh trống ở lễ hội."],["太鼓の音が聞こえます。","Nghe thấy tiếng trống."],["太鼓の練習をします。","Tôi luyện tập trống."],["大きい太鼓があります。","Có cái trống lớn."]]},{"word":"けいこ","reading":"けいこ","meaning":"Luyện tập, thực hành","hanViet":"","lesson":6,"ex":[["けいこをします。","Tôi luyện tập."],["毎週、けいこに行きます。","Mỗi tuần tôi đi luyện tập."],["けいこで太鼓を習います。","Tôi học trống trong buổi luyện tập."],["けいこの後、友だちと話しました。","Sau buổi luyện tập, tôi đã nói chuyện với bạn."],["けいこを始めて、一年になります。","Tôi bắt đầu luyện tập được một năm rồi."]]},{"word":"サケ","reading":"サケ","meaning":"Cá hồi","hanViet":"","lesson":6,"ex":[["サケを食べます。","Tôi ăn cá hồi."],["サケは海から川に来ます。","Cá hồi từ biển đến sông."],["サケが好きです。","Tôi thích cá hồi."],["サケを買いました。","Tôi đã mua cá hồi."],["サケは海に住んでいます。","Cá hồi sống ở biển."]]},{"word":"着陸する","reading":"ちゃくりくする","meaning":"Hạ cánh máy bay","hanViet":"TRỨ LỤC","lesson":6,"ex":[["飛行機が着陸しました。","Máy bay đã hạ cánh."],["飛行機は空港に着陸します。","Máy bay hạ cánh xuống sân bay."],["着陸する前に、窓を見ました。","Trước khi hạ cánh, tôi đã nhìn ra cửa sổ."],["飛行機は午後三時に着陸しました。","Máy bay đã hạ cánh lúc 3 giờ chiều."],["着陸したら、電話します。","Sau khi hạ cánh, tôi sẽ gọi điện."]]},{"word":"タラップ","reading":"タラップ","meaning":"Cầu thang lên xuống máy bay (loại di động)","hanViet":"","lesson":6,"ex":[["タラップで飛行機から出ました。","Tôi đã ra khỏi máy bay bằng cầu thang."],["タラップの上に立ちました。","Tôi đã đứng trên cầu thang máy bay."],["タラップから飛行機に入りました。","Tôi đã vào máy bay bằng cầu thang."],["タラップの下で待ちました。","Tôi đã đợi dưới cầu thang máy bay."],["タラップの上で写真をとりました。","Tôi đã chụp ảnh trên cầu thang máy bay."]]},{"word":"ようこそ","reading":"ようこそ","meaning":"Chào mừng","hanViet":"","lesson":6,"ex":[["ようこそ、日本へ。","Chào mừng đến Nhật Bản."],["ようこそ、私の家へ。","Chào mừng đến nhà tôi."],["ようこそ、京都へ。","Chào mừng đến Kyoto."],["ようこそ、と言いました。","Tôi đã nói 'Chào mừng'."],["ようこそ、パーティーへ。","Chào mừng đến bữa tiệc."]]},{"word":"ビジネスマナー","reading":"ビジネスマナー","meaning":"Phép tắc ứng xử trong kinh doanh","hanViet":"","lesson":6,"ex":[["ビジネスマナーを学びます。","Tôi học văn hóa kinh doanh."],["ビジネスマナーは大切です。","Văn hóa kinh doanh rất quan trọng."],["ビジネスマナーの本を読みました。","Tôi đã đọc sách về văn hóa kinh doanh."],["ビジネスマナーについて話しました。","Chúng tôi đã nói về văn hóa kinh doanh."],["会社でビジネスマナーを教えました。","Tôi đã dạy văn hóa kinh doanh ở công ty."]]},{"word":"セミナー","reading":"セミナー","meaning":"Hội thảo","hanViet":"","lesson":6,"ex":[["セミナーに参加します。","Tôi tham gia hội thảo."],["明日、セミナーがあります。","Ngày mai có hội thảo."],["セミナーで勉強しました。","Tôi đã học ở hội thảo."],["セミナーの後、質問しました。","Sau hội thảo, tôi đã hỏi."],["ビジネスのセミナーに行きました。","Tôi đã đến hội thảo kinh doanh."]]},{"word":"案内","reading":"あんない","meaning":"Hướng dẫn, thông tin hướng dẫn","hanViet":"ÁN NỘI","lesson":6,"ex":[["案内をします。","Tôi hướng dẫn."],["駅の案内を見ました。","Tôi đã xem bảng hướng dẫn ở ga."],["先生が案内してくれました。","Thầy đã hướng dẫn cho tôi."],["案内の紙をもらいました。","Tôi đã nhận tờ giấy hướng dẫn."],["旅行の案内を読みました。","Tôi đã đọc hướng dẫn du lịch."]]},{"word":"費用","reading":"ひよう","meaning":"Chi phí","hanViet":"PHÍ DỤNG","lesson":6,"ex":[["費用はいくらですか。","Chi phí bao nhiêu?"],["費用が高すぎます。","Chi phí quá cao."],["費用を調べました。","Tôi đã tra chi phí."],["費用は会社が出します。","Công ty chi trả chi phí."],["費用を払いました。","Tôi đã trả chi phí."]]},{"word":"交渉する","reading":"こうしょうする","meaning":"Thương thảo, đàm phán","hanViet":"GIAO THIỆP","lesson":6,"ex":[["会社と交渉します。","Tôi thương thảo với công ty."],["値段を交渉しました。","Tôi đã đàm phán giá."],["交渉して、安くなりました。","Tôi đã đàm phán nên giá rẻ hơn."],["交渉がうまくいきました。","Đàm phán đã thành công."],["交渉するのが難しいです。","Đàm phán rất khó."]]},{"word":"条件","reading":"じょうけん","meaning":"Điều kiện","hanViet":"ĐIỀU KIỆN","lesson":6,"ex":[["条件を教えてください。","Hãy cho tôi biết điều kiện."],["条件がいいです。","Điều kiện tốt."],["条件に合います。","Phù hợp với điều kiện."],["条件を変えました。","Tôi đã thay đổi điều kiện."],["条件を聞きました。","Tôi đã hỏi điều kiện."]]},{"word":"制度","reading":"せいど","meaning":"Chế độ","hanViet":"CHẾ ĐỘ","lesson":6,"ex":[["制度が変わりました。","Chế độ đã thay đổi."],["新しい制度が始まります。","Chế độ mới bắt đầu."],["制度について勉強します。","Tôi học về chế độ."],["会社の制度がいいです。","Chế độ công ty tốt."],["制度を調べました。","Tôi đã tra chế độ."]]},{"word":"メンタルトレーニング","reading":"メンタルトレーニング","meaning":"Rèn luyện tinh thần","hanViet":"","lesson":6,"ex":[["メンタルトレーニングをします。","Tôi rèn luyện tinh thần."],["メンタルトレーニングは大切です。","Rèn luyện tinh thần rất quan trọng."],["メンタルトレーニングを始めました。","Tôi đã bắt đầu rèn luyện tinh thần."],["メンタルトレーニングで心が強くなります。","Nhờ rèn luyện tinh thần, tinh thần trở nên mạnh mẽ hơn."],["毎日、メンタルトレーニングをしています。","Mỗi ngày tôi rèn luyện tinh thần."]]},{"word":"取り入れる","reading":"とりいれる","meaning":"Áp dụng, đưa vào, kết hợp","hanViet":"THỦ NHẬP","lesson":6,"ex":[["新しい方法を取り入れます。","Tôi áp dụng phương pháp mới."],["外国の文化を取り入れました。","Tôi đã tiếp nhận văn hóa nước ngoài."],["会社は新しい制度を取り入れました。","Công ty đã áp dụng chế độ mới."],["意見を取り入れます。","Tôi tiếp nhận ý kiến."],["日本の習慣を取り入れました。","Tôi đã tiếp nhận thói quen của Nhật."]]},{"word":"ビジネス","reading":"ビジネス","meaning":"Kinh doanh","hanViet":"","lesson":6,"ex":[["ビジネスを始めます。","Tôi bắt đầu kinh doanh."],["ビジネスの本を読みます。","Tôi đọc sách kinh doanh."],["ビジネスで日本語を使います。","Tôi dùng tiếng Nhật trong kinh doanh."],["ビジネスがうまくいっています。","Kinh doanh đang thuận lợi."],["ビジネスについて話しました。","Chúng tôi đã nói về kinh doanh."]]},{"word":"レベル","reading":"レベル","meaning":"Cấp độ, mức độ","hanViet":"","lesson":6,"ex":[["レベルが上がりました。","Cấp độ đã tăng lên."],["日本語のレベルが高いです。","Trình độ tiếng Nhật cao."],["レベルに合った本を読みます。","Tôi đọc sách phù hợp với trình độ."],["レベルが違います。","Cấp độ khác nhau."],["レベルを上げたいです。","Tôi muốn nâng cấp độ."]]},{"word":"週","reading":"しゅう","meaning":"Tuần","hanViet":"CHU","lesson":6,"ex":[["週に三回、運動します。","Mỗi tuần tôi tập thể dục ba lần."],["来週、旅行に行きます。","Tuần sau tôi đi du lịch."],["今週は忙しいです。","Tuần này tôi bận."],["先週、友だちに会いました。","Tuần trước tôi đã gặp bạn."],["週末に映画を見ます。","Cuối tuần tôi xem phim."]]},{"word":"全額","reading":"ぜんがく","meaning":"Toàn bộ số tiền","hanViet":"TOÀN NGẠCH","lesson":6,"ex":[["全額払いました。","Tôi đã trả toàn bộ số tiền."],["全額を返しました。","Tôi đã trả lại toàn bộ số tiền."],["費用の全額を会社が出しました。","Công ty đã chi toàn bộ chi phí."],["全額が必要です。","Cần toàn bộ số tiền."],["全額もらいました。","Tôi đã nhận toàn bộ số tiền."]]},{"word":"半額","reading":"はんがく","meaning":"Nửa số tiền, nửa giá","hanViet":"BÁN NGẠCH","lesson":6,"ex":[["半額で買いました。","Tôi đã mua với nửa giá."],["今日は半額です。","Hôm nay giảm nửa giá."],["半額になりました。","Đã giảm còn nửa giá."],["半額を払いました。","Tôi đã trả nửa số tiền."],["半額の切符を買いました。","Tôi đã mua vé nửa giá."]]},{"word":"出す","reading":"だす","meaning":"Đưa ra, gửi, nộp, chi trả, bỏ ra","hanViet":"XUẤT","lesson":6,"ex":[["費用を出します。","Tôi chi trả chi phí."],["手紙を出しました。","Tôi đã gửi thư."],["宿題を出してください。","Hãy nộp bài tập."],["声を出しました。","Tôi đã lên tiếng."],["お金を出しました。","Tôi đã bỏ tiền ra."]]},{"word":"それでは","reading":"それでは","meaning":"Vậy thì, thế thì","hanViet":"","lesson":6,"ex":[["それでは、始めましょう。","Vậy thì, chúng ta bắt đầu nhé."],["それでは、失礼します。","Vậy thì, tôi xin phép."],["それでは、また明日。","Vậy thì, hẹn ngày mai."],["それでは、行きましょう。","Vậy thì, chúng ta đi thôi."],["それでは、終わります。","Vậy thì, kết thúc thôi."]]},{"word":"期間","reading":"きかん","meaning":"Thời gian, thời hạn","hanViet":"KỲ GIAN","lesson":6,"ex":[["期間は一週間です。","Thời hạn là một tuần."],["期間が長いです。","Thời gian dài."],["期間中に連絡してください。","Hãy liên lạc trong thời hạn."],["期間が終わりました。","Thời hạn đã kết thúc."],["期間を決めました。","Tôi đã quyết định thời hạn."]]},{"word":"日時","reading":"にちじ","meaning":"Ngày giờ","hanViet":"NHẬT THÌ","lesson":6,"ex":[["会議の日時が決まりました。","Ngày giờ của cuộc họp đã được quyết định."],["試験の日時を先生に聞きました。","Tôi đã hỏi thầy giáo về ngày giờ của kỳ thi."],["日時が変わりましたら、メールで知らせます。","Nếu ngày giờ thay đổi, tôi sẽ thông báo qua email."],["パーティーの日時をみんなに伝えました。","Tôi đã báo ngày giờ của bữa tiệc cho mọi người."],["日時を確認してから、ホテルを予約しました。","Sau khi xác nhận ngày giờ, tôi đã đặt phòng khách sạn."]]},{"word":"授業料","reading":"じゅぎょうりょう","meaning":"Học phí","hanViet":"THỤ NGHIỆP LIỆU","lesson":6,"ex":[["この学校の授業料は八十万円です。","Học phí của trường này là 800 nghìn yên."],["授業料を銀行で払いました。","Tôi đã đóng học phí ở ngân hàng."],["授業料が高いので、アルバイトを始めました。","Vì học phí cao nên tôi đã bắt đầu làm thêm."],["来月までに授業料を払わなければなりません。","Tôi phải đóng học phí trước tháng sau."],["授業料について、学校の人に聞いてみます。","Tôi sẽ thử hỏi người của trường về học phí."]]},{"word":"～料","reading":"～りょう","meaning":"~ phí","hanViet":"LIỆU","lesson":6,"ex":[["この公園の入場料は三百円です。","Phí vào cửa công viên này là 300 yên."],["銀行の手数料は二百円です。","Phí thủ tục của ngân hàng là 200 yên."],["この本を送る送料は三百円です。","Phí gửi cuốn sách này là 300 yên."],["この部屋の使用料は一時間千円です。","Phí sử dụng phòng này là 1.000 yên một giờ."],["授業料を来月までに払います。","Tôi sẽ đóng học phí trước tháng sau."]]},{"word":"日にち","reading":"ひにち","meaning":"Ngày, ngày tháng","hanViet":"NHẬT","lesson":6,"ex":[["旅行の日にちが決まりました。","Ngày đi du lịch đã được quyết định."],["試験の日にちは来月の十日です。","Ngày thi là ngày 10 tháng sau."],["歓迎会の日にちをみんなに知らせます。","Tôi sẽ thông báo ngày tổ chức tiệc chào đón cho mọi người."],["日にちを変えてもいいですか。","Tôi có thể đổi ngày được không?"],["会議の日にちが変わりました。","Ngày họp đã thay đổi."]]},{"word":"担当者","reading":"たんとうしゃ","meaning":"Người phụ trách, người điều phối","hanViet":"ĐẢM ĐƯƠNG GIẢ","lesson":6,"ex":[["この仕事の担当者は田中さんです。","Người phụ trách công việc này là anh Tanaka."],["担当者にメールで連絡しました。","Tôi đã liên lạc với người phụ trách qua email."],["担当者が変わりましたので、新しい担当者を紹介します。","Vì người phụ trách đã thay đổi nên tôi xin giới thiệu người phụ trách mới."],["何か問題があれば、担当者に聞いてください。","Nếu có vấn đề gì, hãy hỏi người phụ trách."],["担当者の名前と電話番号を教えてください。","Hãy cho tôi biết tên và số điện thoại của người phụ trách."]]},{"word":"延期する","reading":"えんきする","meaning":"Hoãn","hanViet":"DUYÊN KÌ","lesson":6,"ex":[["雨がたくさん降ったので、試合を延期しました。","Vì mưa nhiều nên trận đấu đã được hoãn lại."],["会議を来週に延期します。","Tôi sẽ hoãn cuộc họp sang tuần sau."],["先生の病気で、試験が延期になりました。","Vì thầy giáo bị ốm nên kỳ thi đã bị hoãn."],["旅行を延期することにしました。","Tôi đã quyết định hoãn chuyến du lịch."],["延期した会議の日時をあとで知らせます。","Tôi sẽ thông báo sau ngày giờ của cuộc họp bị hoãn."]]},{"word":"買い換える","reading":"かいかえる","meaning":"Mua cái mới thay cái cũ","hanViet":"MẠI HOÁN","lesson":6,"ex":[["古い車を買い換えました。","Tôi đã mua xe mới thay cho chiếc xe cũ."],["電話を買い換えるつもりです。","Tôi định mua điện thoại mới thay cái cũ."],["パソコンが古くなったので、買い換えました。","Vì máy tính đã cũ nên tôi đã mua cái mới thay."],["この自転車を買い換えたいです。","Tôi muốn mua xe đạp mới thay chiếc này."],["お母さんは冷蔵庫を買い換えました。","Mẹ tôi đã mua tủ lạnh mới thay cái cũ."]]},{"word":"講演会","reading":"こうえんかい","meaning":"Buổi nói chuyện, buổi diễn thuyết","hanViet":"GIẢNG DIỄN HỘI","lesson":6,"ex":[["大学で講演会がありました。","Ở trường đại học đã có buổi diễn thuyết."],["明日、先生の講演会に行きます。","Ngày mai tôi sẽ đi dự buổi diễn thuyết của thầy giáo."],["講演会で日本の歴史について話を聞きました。","Ở buổi diễn thuyết, tôi đã nghe nói về lịch sử Nhật Bản."],["講演会の日時を友達に知らせました。","Tôi đã thông báo ngày giờ buổi diễn thuyết cho bạn."],["この講演会にはたくさんの学生が参加しました。","Buổi diễn thuyết này có nhiều sinh viên tham gia."]]},{"word":"～会","reading":"～かい","meaning":"Hội, buổi họp ~","hanViet":"HỘI","lesson":6,"ex":[["十二月に忘年会を開きます。","Tháng 12 chúng tôi tổ chức tiệc tất niên."],["運動会で友達と会いました。","Tôi đã gặp bạn bè ở hội thao."],["新しい先生の歓迎会をしました。","Chúng tôi đã tổ chức tiệc chào đón thầy giáo mới."],["送別会で友達に本をあげました。","Ở tiệc chia tay, tôi đã tặng sách cho bạn."],["日本語の発表会に参加しました。","Tôi đã tham gia buổi thuyết trình tiếng Nhật."]]},{"word":"上司","reading":"じょうし","meaning":"Sếp, cấp trên","hanViet":"THƯỢNG TY","lesson":6,"ex":[["上司に仕事について話しました。","Tôi đã nói với sếp về công việc."],["上司からメールが来ました。","Tôi đã nhận được email từ sếp."],["上司はとても忙しい人です。","Sếp là người rất bận rộn."],["上司に休みたいと伝えました。","Tôi đã nói với sếp là tôi muốn nghỉ."],["新しい上司は優しい人です。","Sếp mới là người hiền lành."]]},{"word":"つかむ","reading":"つかむ","meaning":"Nắm bắt, nắm lấy","hanViet":"","lesson":6,"ex":[["子どもはお母さんの手をつかみました。","Đứa trẻ đã nắm tay mẹ."],["チャンスをつかんで、新しい仕事を始めました。","Nắm bắt cơ hội, tôi đã bắt đầu công việc mới."],["魚をつかむのは難しいです。","Bắt cá thì khó."],["彼はボールをつかみました。","Anh ấy đã bắt lấy quả bóng."],["この文の意味をつかむのは難しいです。","Nắm bắt ý nghĩa của câu này thì khó."]]},{"word":"そのような","reading":"そのような","meaning":"Như thế","hanViet":"","lesson":6,"ex":[["そのようなことはもうしません。","Tôi sẽ không làm việc như thế nữa."],["そのような話は聞いたことがありません。","Tôi chưa từng nghe chuyện như thế."],["そのような問題は難しいです。","Vấn đề như thế thì khó."],["そのような人はあまりいません。","Người như thế thì không nhiều lắm."],["そのような仕事をしたいです。","Tôi muốn làm công việc như thế."]]},{"word":"想像する","reading":"そうぞうする","meaning":"Tưởng tượng","hanViet":"TƯỞNG TƯỢNG","lesson":6,"ex":[["将来の自分の生活を想像します。","Tôi tưởng tượng cuộc sống tương lai của mình."],["想像していたより、この町はきれいでした。","Thị trấn này đẹp hơn tôi đã tưởng tượng."],["彼の気持ちを想像してみてください。","Hãy thử tưởng tượng cảm xúc của anh ấy."],["想像するだけで、楽しくなります。","Chỉ tưởng tượng thôi cũng thấy vui rồi."],["小さいとき、未来の車を想像しました。","Khi còn nhỏ, tôi đã tưởng tượng về chiếc xe của tương lai."]]},{"word":"イメージする","reading":"イメージする","meaning":"Hình dung, mường tượng","hanViet":"","lesson":6,"ex":[["新しい部屋をイメージしています。","Tôi đang hình dung căn phòng mới."],["この絵を見て、海をイメージしました。","Nhìn bức tranh này, tôi đã hình dung ra biển."],["日本語で話す自分をイメージしてください。","Hãy hình dung bản thân bạn đang nói tiếng Nhật."],["先生の話を聞いて、昔の日本をイメージしました。","Nghe thầy giáo kể, tôi đã hình dung ra nước Nhật ngày xưa."],["将来の仕事をイメージするのは楽しいです。","Hình dung về công việc tương lai thật là vui."]]},{"word":"具体的","reading":"ぐたいてき","meaning":"Cụ thể, mang tính cụ thể","hanViet":"CỤ THỂ ĐÍCH","lesson":6,"ex":[["具体的な計画を立ててください。","Hãy lập kế hoạch cụ thể."],["もっと具体的に説明してください。","Hãy giải thích cụ thể hơn."],["具体的な日にちを教えてください。","Hãy cho tôi biết ngày cụ thể."],["彼の話は具体的で、よくわかりました。","Câu chuyện của anh ấy cụ thể và tôi đã hiểu rõ."],["具体的な時間を教えてください。","Hãy cho tôi biết thời gian cụ thể."]]},{"word":"理想","reading":"りそう","meaning":"Lí tưởng","hanViet":"LÍ TƯỞNG","lesson":6,"ex":[["私の理想の仕事は先生です。","Công việc lý tưởng của tôi là thầy giáo."],["理想の生活をしたいです。","Tôi muốn sống cuộc sống lý tưởng."],["理想の学校はどんな学校ですか。","Ngôi trường lý tưởng là trường như thế nào?"],["彼女は理想の先生です。","Cô ấy là giáo viên lý tưởng."],["理想の旅行について友達と話しました。","Tôi đã nói với bạn về chuyến du lịch lý tưởng."]]},{"word":"近づく","reading":"ちかづく","meaning":"Đến gần, tiến đến gần","hanViet":"CẬN","lesson":6,"ex":[["試験の日が近づいてきました。","Ngày thi đã đến gần."],["犬が私に近づいてきました。","Con chó đã tiến đến gần tôi."],["春が近づいてきました。","Mùa xuân đã đến gần."],["彼はゆっくり私に近づきました。","Anh ấy từ từ tiến đến gần tôi."],["夢に近づくために、毎日勉強します。","Để tiến gần đến ước mơ, tôi học mỗi ngày."]]},{"word":"こそあど","reading":"こそあど","meaning":"Cách nói chỉ thị và nghi vấn bắt đầu với các âm こ、そ、あ và ど","hanViet":"","lesson":6,"ex":[["「これ」「それ」「あれ」はこそあどと言います。","Ba từ これ, それ, あれ được gọi là kosoado."],["こそあどを勉強しました。","Tôi đã học về kosoado."],["先生はこそあどについて説明しました。","Thầy giáo đã giải thích về kosoado."],["こそあどの練習をしました。","Tôi đã luyện tập về kosoado."],["この本でこそあどを勉強できます。","Với cuốn sách này, tôi có thể học về kosoado."]]},{"word":"指す","reading":"さす","meaning":"Chỉ","hanViet":"CHỈ","lesson":6,"ex":[["彼は空を指して、「鳥がいる」と言いました。","Anh ấy chỉ lên trời và nói \"Có con chim\"."],["彼はドアを指しました。","Anh ấy đã chỉ vào cánh cửa."],["「ここ」はこの場所を指します。","Từ \"ここ\" chỉ địa điểm này."],["先生は私を指して、名前を聞きました。","Thầy giáo chỉ vào tôi và hỏi tên."],["この写真の人はだれを指していますか。","Người trong bức ảnh này đang chỉ vào ai?"]]},{"word":"記者会見","reading":"きしゃかいけん","meaning":"Họp báo","hanViet":"KÍ GIẢ HỘI KIẾN","lesson":6,"ex":[["社長が記者会見を開きました。","Giám đốc đã tổ chức họp báo."],["テレビで記者会見を見ました。","Tôi đã xem họp báo trên ti vi."],["記者会見でたくさんの記者が質問しました。","Ở buổi họp báo, nhiều phóng viên đã đặt câu hỏi."],["記者会見は午後三時から始まります。","Buổi họp báo bắt đầu từ 3 giờ chiều."],["新しい映画の記者会見がありました。","Đã có buổi họp báo về bộ phim mới."]]},{"word":"記者","reading":"きしゃ","meaning":"Phóng viên, ký giả","hanViet":"KÍ GIẢ","lesson":6,"ex":[["彼は新聞の記者です。","Anh ấy là phóng viên báo."],["記者が社長に質問しました。","Phóng viên đã đặt câu hỏi cho giám đốc."],["記者は毎日たくさんのニュースを書きます。","Phóng viên viết nhiều tin tức mỗi ngày."],["将来、記者になりたいです。","Trong tương lai, tôi muốn trở thành phóng viên."],["記者が町の祭りについて調べました。","Phóng viên đã tìm hiểu về lễ hội của thị trấn."]]},{"word":"会見","reading":"かいけん","meaning":"Hội kiến","hanViet":"HỘI KIẾN","lesson":6,"ex":[["社長と会見しました。","Tôi đã gặp gỡ giám đốc."],["会見は来週の火曜日です。","Buổi gặp là thứ Ba tuần sau."],["会見で新しい計画について話しました。","Ở buổi gặp, chúng tôi đã nói về kế hoạch mới."],["会見の時間を決めました。","Tôi đã quyết định thời gian buổi gặp."],["会見はすぐに終わりました。","Buổi gặp đã kết thúc nhanh chóng."]]},{"word":"～ごっこ","reading":"～ごっこ","meaning":"Đóng vai ~, bắt chước làm ~","hanViet":"","lesson":6,"ex":[["子どもたちはお医者さんごっこをして遊びました。","Bọn trẻ đã chơi trò đóng vai bác sĩ."],["妹はお母さんごっこが好きです。","Em gái tôi thích chơi trò đóng vai mẹ."],["小さいとき、先生ごっこをよくしました。","Khi còn nhỏ, tôi thường chơi trò đóng vai thầy giáo."],["弟と会社員ごっこをして遊びました。","Tôi đã chơi trò đóng vai nhân viên công ty với em trai."],["子どもたちは店員ごっこをして遊びました。","Bọn trẻ đã chơi trò đóng vai nhân viên cửa hàng."]]},{"word":"キャベツ","reading":"キャベツ","meaning":"Bắp cải","hanViet":"","lesson":6,"ex":[["スーパーでキャベツを買いました。","Tôi đã mua bắp cải ở siêu thị."],["キャベツと肉で料理を作りました。","Tôi đã nấu món ăn với bắp cải và thịt."],["キャベツは安くて、おいしいです。","Bắp cải rẻ và ngon."],["お母さんはキャベツの料理が上手です。","Mẹ tôi nấu món bắp cải rất giỏi."],["このキャベツは大きいです。","Cây bắp cải này to."]]},{"word":"暗い","reading":"くらい","meaning":"Tối (thiếu ánh sáng); (nghĩa bóng) u ám, buồn rầu","hanViet":"ÁM","lesson":6,"ex":[["この部屋は暗いです。","Căn phòng này tối."],["夜の道は暗くて、怖いです。","Đường ban đêm tối và đáng sợ."],["彼は暗い顔をしていました。","Anh ấy có vẻ mặt u ám."],["暗い気持ちになりました。","Tôi đã cảm thấy buồn rầu."],["雨の日は部屋が暗いです。","Vào ngày mưa, căn phòng tối."]]},{"word":"世の中","reading":"よのなか","meaning":"Thế giới, thế gian, xã hội","hanViet":"THẾ TRUNG","lesson":6,"ex":[["世の中にはたくさんの人がいます。","Trên đời có rất nhiều người."],["世の中は広いです。","Thế gian thật rộng lớn."],["世の中のことをもっと知りたいです。","Tôi muốn biết nhiều hơn về chuyện đời."],["世の中は変わっています。","Xã hội đang thay đổi."],["子どもたちに世の中のことを教えます。","Tôi dạy bọn trẻ về chuyện đời."]]},{"word":"アホ","reading":"アホ","meaning":"Ngu ngốc, xuẩn ngốc","hanViet":"","lesson":6,"ex":[["そのようなアホなことはやめてください。","Hãy dừng việc ngu ngốc như thế lại."],["アホなことを言わないでください。","Đừng nói những điều ngu ngốc."],["彼はアホだと言われました。","Anh ấy bị nói là đồ ngốc."],["アホなことを聞かないでください。","Đừng hỏi những điều ngu ngốc."],["大阪では「ばか」のことを「アホ」と言います。","Ở Osaka, người ta gọi \"baka\" là \"aho\"."]]},{"word":"見える","reading":"みえる","meaning":"Nhìn thấy, trông thấy, có vẻ (như...)","hanViet":"KIẾN","lesson":6,"ex":[["窓から海が見えます。","Từ cửa sổ có thể nhìn thấy biển."],["この山から富士山が見えます。","Từ ngọn núi này có thể nhìn thấy núi Phú Sĩ."],["彼は元気に見えます。","Anh ấy trông có vẻ khỏe mạnh."],["この字は小さくて、よく見えません。","Chữ này nhỏ nên không nhìn rõ."],["家の窓から公園が見えます。","Từ cửa sổ nhà có thể nhìn thấy công viên."]]},{"word":"ビジネスマン","reading":"ビジネスマン","meaning":"Nhân viên văn phòng (nam), dân công sở","hanViet":"","lesson":6,"ex":[["彼はビジネスマンです。","Anh ấy là nhân viên văn phòng."],["朝、たくさんのビジネスマンが駅にいます。","Buổi sáng, nhiều nhân viên văn phòng có mặt ở ga."],["ビジネスマンは毎日会社に行きます。","Nhân viên văn phòng đi làm mỗi ngày."],["お父さんはビジネスマンです。","Bố tôi là nhân viên văn phòng."],["ビジネスマンの一日は忙しいです。","Một ngày của nhân viên văn phòng rất bận rộn."]]},{"word":"同じような","reading":"おなじような","meaning":"Giống như","hanViet":"ĐỒNG","lesson":6,"ex":[["私も同じような経験があります。","Tôi cũng có kinh nghiệm giống như thế."],["同じような問題がまた起きました。","Vấn đề giống như thế lại xảy ra."],["彼は私と同じような本を読んでいます。","Anh ấy đang đọc cuốn sách giống như của tôi."],["同じような話を聞きました。","Tôi đã nghe câu chuyện giống như thế."],["同じようなことをしないでください。","Đừng làm việc giống như thế."]]},{"word":"閉じる","reading":"とじる","meaning":"Đóng, khép lại (mắt, sách, miệng...)","hanViet":"BẾ","lesson":6,"ex":[["目を閉じて、音楽を聞きました。","Tôi nhắm mắt và nghe nhạc."],["少し休みたいので、目を閉じました。","Vì muốn nghỉ một chút nên tôi đã nhắm mắt."],["目を閉じて、ゆっくり休みました。","Tôi nhắm mắt và nghỉ ngơi từ từ."],["子どもは目を閉じて、笑っていました。","Đứa trẻ nhắm mắt và đang cười."],["目を閉じないで、見てください。","Đừng nhắm mắt, hãy nhìn đi."]]},{"word":"トレーニング","reading":"トレーニング","meaning":"Luyện tập, rèn luyện","hanViet":"","lesson":6,"ex":[["毎日トレーニングをしています。","Tôi luyện tập mỗi ngày."],["サッカーのトレーニングは楽しいです。","Luyện tập bóng đá thì vui."],["トレーニングを始めて、元気になりました。","Bắt đầu luyện tập, tôi đã trở nên khỏe mạnh."],["試合の前にトレーニングをしました。","Tôi đã luyện tập trước trận đấu."],["トレーニングの時間は一時間です。","Thời gian luyện tập là một giờ."]]},{"word":"つまり","reading":"つまり","meaning":"Tóm lại, nói cách khác","hanViet":"","lesson":6,"ex":[["つまり、日本語は難しいということです。","Tóm lại, tiếng Nhật là khó."],["つまり、明日は休みです。","Tóm lại, ngày mai được nghỉ."],["つまり、彼は来ません。","Tóm lại, anh ấy sẽ không đến."],["つまり、この問題は簡単です。","Tóm lại, vấn đề này đơn giản."],["つまり、試験は来週です。","Tóm lại, kỳ thi là tuần sau."]]},{"word":"過去","reading":"かこ","meaning":"Quá khứ","hanViet":"QUÁ KHỨ","lesson":6,"ex":[["過去のことを忘れたいです。","Tôi muốn quên chuyện quá khứ."],["過去のことをよく覚えています。","Tôi nhớ rõ chuyện quá khứ."],["過去は変えられません。","Quá khứ không thể thay đổi."],["過去の経験からいろいろなことを知りました。","Từ kinh nghiệm quá khứ, tôi đã biết nhiều điều."],["過去の写真を見ました。","Tôi đã xem những bức ảnh quá khứ."]]},{"word":"向き合う","reading":"むきあう","meaning":"Đối diện, đối mặt","hanViet":"HƯỚNG HỢP","lesson":6,"ex":[["問題に向き合うことが大切です。","Đối mặt với vấn đề là điều quan trọng."],["彼は現実に向き合いました。","Anh ấy đã đối mặt với hiện thực."],["過去に向き合うのは難しいです。","Đối mặt với quá khứ thì khó."],["お母さんは子どもの問題に向き合いました。","Mẹ đã đối mặt với vấn đề của con."],["向き合わなければ、問題は解決しません。","Nếu không đối mặt thì vấn đề sẽ không được giải quyết."]]},{"word":"そうすれば","reading":"そうすれば","meaning":"Bằng cách đó, làm như thế thì","hanViet":"","lesson":6,"ex":[["そうすれば、問題が解決します。","Làm như thế thì vấn đề sẽ được giải quyết."],["そうすれば、みんなが喜びます。","Làm như thế thì mọi người sẽ vui."],["そうすれば、日本語が上手になります。","Làm như thế thì tiếng Nhật sẽ giỏi lên."],["そうすれば、お金を使いません。","Làm như thế thì sẽ không tốn tiền."],["そうすれば、仕事がすぐ終わります。","Làm như thế thì công việc sẽ xong ngay."]]},{"word":"現在","reading":"げんざい","meaning":"Hiện tại","hanViet":"HIỆN TẠI","lesson":6,"ex":[["現在、私は東京で働いています。","Hiện tại, tôi đang làm việc ở Tokyo."],["現在の仕事は楽しいです。","Công việc hiện tại thì vui."],["現在、日本語を勉強しています。","Hiện tại, tôi đang học tiếng Nhật."],["現在の時間は午後三時です。","Thời gian hiện tại là 3 giờ chiều."],["現在、彼は大阪にいます。","Hiện tại, anh ấy đang ở Osaka."]]},{"word":"そこから","reading":"そこから","meaning":"Từ đó","hanViet":"","lesson":6,"ex":[["そこから電車に乗ります。","Từ đó, tôi sẽ đi tàu."],["そこから学校まで歩いて行きます。","Từ đó, tôi đi bộ đến trường."],["そこから海が見えます。","Từ đó có thể nhìn thấy biển."],["そこからバスに乗りました。","Từ đó, tôi đã đi xe buýt."],["そこから新しい生活が始まりました。","Từ đó, cuộc sống mới đã bắt đầu."]]},{"word":"解決する","reading":"かいけつする","meaning":"Giải quyết","hanViet":"GIẢI QUYẾT","lesson":6,"ex":[["問題を解決しました。","Tôi đã giải quyết vấn đề."],["みんなで問題を解決しました。","Mọi người đã cùng giải quyết vấn đề."],["この問題はなかなか解決しません。","Vấn đề này mãi không giải quyết được."],["先生が問題を解決してくれました。","Thầy giáo đã giải quyết vấn đề giúp tôi."],["解決する方法を考えます。","Tôi nghĩ cách giải quyết."]]},{"word":"プラン","reading":"プラン","meaning":"Kế hoạch","hanViet":"","lesson":6,"ex":[["旅行のプランを立てました。","Tôi đã lập kế hoạch du lịch."],["新しいプランを考えています。","Tôi đang nghĩ kế hoạch mới."],["プランを変えました。","Tôi đã thay đổi kế hoạch."],["このプランはいいですね。","Kế hoạch này hay nhỉ."],["プランを友達に話しました。","Tôi đã nói kế hoạch với bạn."]]},{"word":"立てる","reading":"たてる","meaning":"Lập kế hoạch","hanViet":"LẬP","lesson":6,"ex":[["旅行の計画を立てました。","Tôi đã lập kế hoạch du lịch."],["明日の予定を立てます。","Tôi lập kế hoạch cho ngày mai."],["プランを立てて、旅行に行きます。","Lập kế hoạch rồi đi du lịch."],["先生といっしょに計画を立てました。","Tôi đã lập kế hoạch cùng thầy giáo."],["来月の計画を立てています。","Tôi đang lập kế hoạch cho tháng sau."]]},{"word":"順番","reading":"じゅんばん","meaning":"Thứ tự, trình tự","hanViet":"THUẬN PHIÊN","lesson":6,"ex":[["順番に並んでください。","Hãy xếp hàng theo thứ tự."],["順番が来ました。","Đã đến lượt rồi."],["順番を変えました。","Tôi đã đổi thứ tự."],["順番に名前を呼びます。","Tôi sẽ gọi tên theo thứ tự."],["順番を忘れました。","Tôi đã quên thứ tự."]]},{"word":"歓迎会","reading":"かんげいかい","meaning":"Tiệc chào đón","hanViet":"HOAN NGHÊNH HỘI","lesson":7,"ex":[["新しい学生の歓迎会をしました。","Chúng tôi đã tổ chức tiệc chào đón sinh viên mới."],["歓迎会は来週です。","Tiệc chào đón là tuần sau."],["歓迎会でたくさんの人と話しました。","Ở tiệc chào đón, tôi đã nói chuyện với nhiều người."],["歓迎会の場所を決めました。","Tôi đã quyết định địa điểm tiệc chào đón."],["先生の歓迎会に参加しました。","Tôi đã tham gia tiệc chào đón thầy giáo."]]},{"word":"招待状","reading":"しょうたいじょう","meaning":"Thư mời","hanViet":"CHIÊU ĐÃI TRẠNG","lesson":7,"ex":[["友達から招待状をもらいました。","Tôi đã nhận được thư mời từ bạn."],["招待状を書きました。","Tôi đã viết thư mời."],["結婚式の招待状が来ました。","Thư mời lễ cưới đã đến."],["招待状を送りました。","Tôi đã gửi thư mời."],["招待状に日時が書いてあります。","Trên thư mời có ghi ngày giờ."]]},{"word":"ラーメン","reading":"ラーメン","meaning":"Ramen","hanViet":"","lesson":7,"ex":[["ラーメンが好きです。","Tôi thích ramen."],["昼にラーメンを食べました。","Buổi trưa tôi đã ăn ramen."],["この店のラーメンはおいしいです。","Ramen của quán này ngon."],["友達とラーメンを食べに行きました。","Tôi đã đi ăn ramen với bạn."],["寒い日はラーメンを食べたいです。","Vào ngày lạnh, tôi muốn ăn ramen."]]},{"word":"折り紙","reading":"おりがみ","meaning":"Origami nghệ thuật gấp giấy","hanViet":"CHIẾT CHỈ","lesson":7,"ex":[["折り紙で花を作りました。","Tôi đã gấp hoa bằng giấy origami."],["子どもは折り紙が好きです。","Trẻ em thích origami."],["折り紙を習っています。","Tôi đang học origami."],["折り紙で動物を作りました。","Tôi đã gấp động vật bằng giấy origami."],["先生に折り紙を教えてもらいました。","Tôi đã được thầy giáo dạy gấp giấy origami."]]},{"word":"ピンク","reading":"ピンク","meaning":"Màu hồng","hanViet":"","lesson":7,"ex":[["ピンクの花がきれいです。","Hoa màu hồng đẹp."],["彼女はピンクが好きです。","Cô ấy thích màu hồng."],["ピンクの本を買いました。","Tôi đã mua cuốn sách màu hồng."],["このかばんはピンクです。","Cái cặp này màu hồng."],["ピンクの花をお母さんにあげました。","Tôi đã tặng hoa màu hồng cho mẹ."]]},{"word":"送別会","reading":"そうべつかい","meaning":"Tiệc chia tay","hanViet":"TỐNG BIỆT HỘI","lesson":7,"ex":[["先生の送別会をしました。","Chúng tôi đã tổ chức tiệc chia tay thầy giáo."],["送別会は来月の十日です。","Tiệc chia tay là ngày 10 tháng sau."],["送別会で先生にありがとうと言いました。","Ở tiệc chia tay, tôi đã nói cảm ơn thầy giáo."],["送別会に参加する人は二十人です。","Số người tham gia tiệc chia tay là 20 người."],["送別会の場所はレストランです。","Địa điểm tiệc chia tay là nhà hàng."]]},{"word":"中華レストラン","reading":"ちゅうかレストラン","meaning":"Nhà hàng món ăn Trung Hoa","hanViet":"TRUNG HOA","lesson":7,"ex":[["中華レストランでラーメンを食べました。","Tôi đã ăn ramen ở nhà hàng Trung Hoa."],["駅の前に中華レストランがあります。","Trước ga có một nhà hàng Trung Hoa."],["友達と中華レストランに行きました。","Tôi đã đi nhà hàng Trung Hoa với bạn."],["この中華レストランは安いです。","Nhà hàng Trung Hoa này rẻ."],["中華レストランの料理はおいしいです。","Món ăn của nhà hàng Trung Hoa ngon."]]},{"word":"留学生会","reading":"りゅうがくせいかい","meaning":"Hội lưu học sinh","hanViet":"LƯU HỌC SINH HỘI","lesson":7,"ex":[["留学生会に入りました。","Tôi đã gia nhập hội lưu học sinh."],["留学生会の会長は田中さんです。","Chủ tịch hội lưu học sinh là anh Tanaka."],["留学生会で旅行に行きました。","Hội lưu học sinh đã đi du lịch."],["留学生会の仕事を手伝いました。","Tôi đã giúp việc của hội lưu học sinh."],["留学生会の会議があります。","Có cuộc họp của hội lưu học sinh."]]},{"word":"～会","reading":"～かい","meaning":"Hội ~","hanViet":"HỘI","lesson":7,"ex":[["学校で音楽会がありました。","Ở trường đã có buổi hòa nhạc."],["学校の発表会に参加しました。","Tôi đã tham gia buổi thuyết trình ở trường."],["大学で運動会がありました。","Ở trường đại học đã có hội thao."],["忘年会は十二月です。","Tiệc tất niên là vào tháng 12."],["歓迎会で新しい友達に会いました。","Ở tiệc chào đón, tôi đã gặp bạn mới."]]},{"word":"会長","reading":"かいちょう","meaning":"Chủ tịch","hanViet":"HỘI TRƯỜNG","lesson":7,"ex":[["彼は留学生会の会長です。","Anh ấy là chủ tịch hội lưu học sinh."],["会長が話をしました。","Chủ tịch đã nói chuyện."],["会長に選ばれました。","Tôi đã được bầu làm chủ tịch."],["会長は忙しい人です。","Chủ tịch là người bận rộn."],["新しい会長が決まりました。","Chủ tịch mới đã được quyết định."]]},{"word":"点数","reading":"てんすう","meaning":"Điểm số","hanViet":"ĐIỂM SỐ","lesson":7,"ex":[["試験の点数は九十点でした。","Điểm thi là 90 điểm."],["点数が上がりました。","Điểm số đã tăng lên."],["点数が下がりました。","Điểm số đã giảm xuống."],["点数を教えてください。","Hãy cho tôi biết điểm số."],["点数を友達と比べました。","Tôi đã so sánh điểm số với bạn."]]},{"word":"たいした","reading":"たいした","meaning":"Đáng kể, ghê gớm","hanViet":"","lesson":7,"ex":[["たいしたことはありません。","Không có gì ghê gớm cả."],["たいした問題ではありません。","Không phải là vấn đề gì ghê gớm."],["彼はたいしたものです。","Anh ấy là người đáng nể."],["たいしたけがではありませんでした。","Không phải là vết thương gì nghiêm trọng."],["たいしたお金ではありません。","Không phải là số tiền gì lớn."]]},{"word":"悪口","reading":"わるぐち","meaning":"Sự nói xấu","hanViet":"ÁC KHẨU","lesson":7,"ex":[["人の悪口を言わないでください。","Đừng nói xấu người khác."],["悪口を言われて、悲しくなりました。","Bị nói xấu, tôi đã trở nên buồn."],["悪口はやめましょう。","Hãy dừng nói xấu lại."],["彼の悪口を聞きました。","Tôi đã nghe lời nói xấu về anh ấy."],["悪口を言うのはよくありません。","Nói xấu là không tốt."]]},{"word":"夫婦","reading":"ふうふ","meaning":"Vợ chồng","hanViet":"PHU PHỤ","lesson":7,"ex":[["あの二人は若い夫婦です。","Hai người đó là cặp vợ chồng trẻ."],["夫婦で旅行に行きました。","Hai vợ chồng đã đi du lịch."],["夫婦の間に子どもがいます。","Giữa hai vợ chồng có con."],["あの夫婦はいつもいっしょにいます。","Cặp vợ chồng đó lúc nào cũng ở bên nhau."],["夫婦で新しい家を買いました。","Hai vợ chồng đã mua nhà mới."]]},{"word":"～げんか","reading":"～げんか","meaning":"Tranh cãi, cãi nhau giữa vợ chồng","hanViet":"","lesson":7,"ex":[["夫婦げんかをしました。","Hai vợ chồng đã cãi nhau."],["夫婦げんかはよくあります。","Vợ chồng cãi nhau là chuyện thường."],["夫婦げんかをして、謝りました。","Cãi nhau xong, tôi đã xin lỗi."],["小さい夫婦げんかでした。","Chỉ là cuộc cãi nhau nhỏ của vợ chồng."],["夫婦げんかをしないように気をつけます。","Tôi cẩn thận để vợ chồng không cãi nhau."]]},{"word":"医学部","reading":"いがくぶ","meaning":"Khoa Y","hanViet":"Y HỌC BỘ","lesson":7,"ex":[["彼は大学の医学部で勉強しています。","Anh ấy đang học ở khoa Y của trường đại học."],["医学部に入りたいです。","Tôi muốn vào khoa Y."],["医学部の学生は忙しいです。","Sinh viên khoa Y rất bận rộn."],["医学部を卒業しました。","Tôi đã tốt nghiệp khoa Y."],["医学部の試験は難しいです。","Kỳ thi khoa Y thì khó."]]},{"word":"～部","reading":"～ぶ","meaning":"Khoa","hanViet":"BỘ","lesson":7,"ex":[["私は文学部で勉強しています。","Tôi đang học ở khoa Văn học."],["兄は法学部を卒業しました。","Anh trai tôi đã tốt nghiệp khoa Luật."],["経済学部に入りたいです。","Tôi muốn vào khoa Kinh tế."],["工学部の学生です。","Tôi là sinh viên khoa Kỹ thuật."],["医学部の授業は難しいです。","Bài học của khoa Y thì khó."]]},{"word":"ライオン","reading":"ライオン","meaning":"Sư tử","hanViet":"","lesson":7,"ex":[["動物園でライオンを見ました。","Tôi đã xem sư tử ở sở thú."],["ライオンは強い動物です。","Sư tử là động vật mạnh."],["ライオンは大きくて、怖いです。","Sư tử to và đáng sợ."],["子どもはライオンが好きです。","Trẻ em thích sư tử."],["ライオンの絵を書きました。","Tôi đã vẽ tranh sư tử."]]},{"word":"喜ぶ","reading":"よろこぶ","meaning":"Vui, vui sướng","hanViet":"HỶ","lesson":7,"ex":[["新しい本をもらって、子どもが喜びました。","Được tặng sách mới, đứa trẻ đã vui sướng."],["みんなが喜ぶ顔を見ました。","Tôi đã thấy gương mặt vui vẻ của mọi người."],["友達が結婚して、喜びました。","Bạn tôi kết hôn, tôi đã vui mừng."],["いいニュースを聞いて、喜びました。","Nghe tin tốt, tôi đã vui mừng."],["彼女の歌を聞いて、喜びました。","Nghe cô ấy hát, tôi đã vui."]]},{"word":"冗談","reading":"じょうだん","meaning":"Đùa, bông đùa","hanViet":"NHŨNG ĐÀM","lesson":7,"ex":[["冗談を言いました。","Tôi đã nói đùa."],["それは冗談です。","Đó là nói đùa."],["冗談が好きな人です。","Anh ấy là người thích đùa."],["冗談を言って、みんなを笑わせました。","Nói đùa, tôi đã làm mọi người cười."],["冗談だと思いました。","Tôi đã nghĩ đó là nói đùa."]]},{"word":"～たち","reading":"～たち","meaning":"hậu tố chỉ số nhiều","hanViet":"","lesson":7,"ex":[["子どもたちが公園で遊んでいます。","Bọn trẻ đang chơi ở công viên."],["学生たちが教室で勉強しています。","Các sinh viên đang học ở lớp."],["友達たちと旅行に行きました。","Tôi đã đi du lịch với các bạn."],["先生たちに質問しました。","Tôi đã hỏi các thầy cô."],["私たちは日本語を勉強しています。","Chúng tôi đang học tiếng Nhật."]]},{"word":"お化け","reading":"おばけ","meaning":"Ma","hanViet":"HÓA","lesson":7,"ex":[["お化けが怖いです。","Tôi sợ ma."],["子どもはお化けの話が好きです。","Trẻ em thích chuyện ma."],["お化けの映画を見ました。","Tôi đã xem phim ma."],["夜にお化けが出るそうです。","Nghe nói ban đêm ma xuất hiện."],["お化けはいないと思います。","Tôi nghĩ là không có ma."]]},{"word":"いじめる","reading":"いじめる","meaning":"Bắt nạt, ăn hiếp, chọc ghẹo","hanViet":"","lesson":7,"ex":[["友達をいじめてはいけません。","Không được bắt nạt bạn bè."],["学校で友達をいじめる人がいます。","Ở trường có người bắt nạt bạn bè."],["弟をいじめないでください。","Đừng bắt nạt em trai."],["いじめられた子どもは泣いていました。","Đứa trẻ bị bắt nạt đã khóc."],["先生はいじめる子どもを注意しました。","Thầy giáo đã nhắc nhở đứa trẻ bắt nạt bạn."]]},{"word":"感心する","reading":"かんしんする","meaning":"Cảm phục, ấn tượng","hanViet":"CẢM TÂM","lesson":7,"ex":[["彼の日本語に感心しました。","Tôi đã cảm phục tiếng Nhật của anh ấy."],["先生の話に感心しました。","Tôi đã cảm phục câu chuyện của thầy giáo."],["子どもの絵に感心しました。","Tôi đã cảm phục bức tranh của đứa trẻ."],["彼の料理に感心しました。","Tôi đã cảm phục món ăn của anh ấy."],["感心するほど、上手でした。","Giỏi đến mức đáng cảm phục."]]},{"word":"親","reading":"おや","meaning":"Bố mẹ","hanViet":"THÂN","lesson":7,"ex":[["親に感謝しています。","Tôi biết ơn bố mẹ."],["親の言うことを聞きます。","Tôi nghe lời bố mẹ."],["親に相談しました。","Tôi đã bàn bạc với bố mẹ."],["親といっしょに旅行に行きました。","Tôi đã đi du lịch cùng bố mẹ."],["親は私のことを思っています。","Bố mẹ luôn nghĩ về tôi."]]},{"word":"あらためて","reading":"あらためて","meaning":"Lần nữa, một lần nữa","hanViet":"","lesson":7,"ex":[["あらためて、ありがとうございました。","Một lần nữa, xin cảm ơn."],["あらためて名前を言います。","Tôi xin nói lại tên một lần nữa."],["あらためて考えます。","Tôi sẽ suy nghĩ lại một lần nữa."],["あらためて会いましょう。","Hãy gặp lại nhau một lần nữa."],["あらためてメールを送ります。","Tôi sẽ gửi lại email một lần nữa."]]},{"word":"一周","reading":"いっしゅう","meaning":"Một vòng","hanViet":"NHẤT CHU","lesson":7,"ex":[["公園を一周しました。","Tôi đã đi một vòng quanh công viên."],["自転車で公園を一周しました。","Tôi đã đạp xe một vòng quanh công viên."],["地球を一周したいです。","Tôi muốn đi một vòng quanh Trái Đất."],["一周して、家に帰りました。","Đi một vòng rồi tôi về nhà."],["プールを一周泳ぎました。","Tôi đã bơi một vòng hồ bơi."]]},{"word":"～山","reading":"～さん","meaning":"Núi, ngọn (như núi Phú Sĩ)","hanViet":"SAN","lesson":7,"ex":[["富士山を見に行きました。","Tôi đã đi xem núi Phú Sĩ."],["富士山は日本で一番高い山です。","Núi Phú Sĩ là ngọn núi cao nhất Nhật Bản."],["富士山の写真を見ました。","Tôi đã xem ảnh núi Phú Sĩ."],["白山はきれいな山です。","Núi Hakusan là ngọn núi đẹp."],["富士山に雪があります。","Trên núi Phú Sĩ có tuyết."]]},{"word":"芝居","reading":"しばい","meaning":"Kịch","hanViet":"CHI CƯ","lesson":7,"ex":[["芝居を見に行きました。","Tôi đã đi xem kịch."],["芝居はおもしろかったです。","Vở kịch đã rất thú vị."],["子どもが芝居に出ました。","Đứa trẻ đã diễn kịch."],["芝居の練習をしました。","Tôi đã luyện tập kịch."],["学校で芝居をしました。","Ở trường, chúng tôi đã diễn kịch."]]},{"word":"せりふ","reading":"せりふ","meaning":"Lời thoại","hanViet":"","lesson":7,"ex":[["せりふを覚えました。","Tôi đã thuộc lời thoại."],["せりふを練習しています。","Tôi đang luyện tập lời thoại."],["せりふを忘れてしまいました。","Tôi đã quên mất lời thoại."],["この映画のせりふは難しいです。","Lời thoại của bộ phim này khó."],["せりふを言ってみました。","Tôi đã thử nói lời thoại."]]},{"word":"泣く","reading":"なく","meaning":"Khóc","hanViet":"KHẤP","lesson":7,"ex":[["子どもが泣いています。","Đứa trẻ đang khóc."],["悲しい映画を見て、泣きました。","Xem phim buồn, tôi đã khóc."],["彼女は感動して、泣きました。","Cô ấy cảm động và đã khóc."],["泣かないでください。","Đừng khóc."],["赤ちゃんが泣きました。","Em bé đã khóc."]]},{"word":"アニメ","reading":"アニメ","meaning":"Phim hoạt hình","hanViet":"","lesson":7,"ex":[["アニメが好きです。","Tôi thích phim hoạt hình."],["日本のアニメは世界で有名です。","Phim hoạt hình Nhật Bản nổi tiếng trên thế giới."],["アニメを見て、日本語を勉強しました。","Xem anime, tôi đã học tiếng Nhật."],["子どもはアニメを見ています。","Trẻ em đang xem phim hoạt hình."],["このアニメはおもしろいです。","Bộ anime này thú vị."]]},{"word":"感動する","reading":"かんどうする","meaning":"Cảm động","hanViet":"CẢM ĐỘNG","lesson":7,"ex":[["映画に感動しました。","Tôi đã cảm động với bộ phim."],["先生の話に感動しました。","Tôi đã cảm động với câu chuyện của thầy giáo."],["感動して、泣きました。","Cảm động, tôi đã khóc."],["彼の歌に感動しました。","Tôi đã cảm động với bài hát của anh ấy."],["感動する映画でした。","Đó là bộ phim cảm động."]]},{"word":"講演","reading":"こうえん","meaning":"Bài nói chuyện, bài giảng","hanViet":"GIẢNG DIỄN","lesson":7,"ex":[["先生の講演を聞きました。","Tôi đã nghe bài giảng của thầy giáo."],["講演は二時間でした。","Bài giảng kéo dài hai giờ."],["講演で質問しました。","Tôi đã hỏi ở buổi giảng."],["講演はおもしろかったです。","Bài giảng đã rất thú vị."],["大学で講演をしました。","Tôi đã giảng bài ở trường đại học."]]},{"word":"譲る","reading":"ゆずる","meaning":"Nhường, nhường lại, chuyển nhượng","hanViet":"NHƯỢNG","lesson":7,"ex":[["電車で席を譲りました。","Trên tàu, tôi đã nhường ghế."],["子どもに席を譲りました。","Tôi đã nhường ghế cho đứa trẻ."],["友達に本を譲りました。","Tôi đã nhường sách cho bạn."],["道を譲りました。","Tôi đã nhường đường."],["彼は私に本を譲ってくれました。","Anh ấy đã nhường sách cho tôi."]]},{"word":"ツアー","reading":"ツアー","meaning":"Tour du lịch","hanViet":"","lesson":7,"ex":[["京都のツアーに参加しました。","Tôi đã tham gia tour Kyoto."],["ツアーでたくさんの人と会いました。","Ở tour du lịch, tôi đã gặp nhiều người."],["ツアーは楽しかったです。","Tour du lịch đã rất vui."],["バスツアーに行きました。","Tôi đã đi tour bằng xe buýt."],["ツアーの時間は三時間です。","Thời gian tour là ba giờ."]]},{"word":"きつい","reading":"きつい","meaning":"Kín, chặt chẽ lịch trình, v.v","hanViet":"","lesson":7,"ex":[["きついスケジュールです。","Lịch trình chặt chẽ."],["この靴はきついです。","Đôi giày này chật."],["きつい練習で疲れました。","Tôi đã mệt vì buổi luyện tập khắc nghiệt."],["きつい仕事をしています。","Tôi đang làm công việc khắc nghiệt."],["このズボンはきついです。","Cái quần này chật."]]},{"word":"フリーマーケット","reading":"フリーマーケット","meaning":"Chợ trời","hanViet":"","lesson":7,"ex":[["フリーマーケットで古い本を買いました。","Tôi đã mua sách cũ ở chợ trời."],["週末にフリーマーケットに行きます。","Cuối tuần tôi đi chợ trời."],["フリーマーケットは安くて、楽しいです。","Chợ trời rẻ và vui."],["フリーマーケットで友達に会いました。","Tôi đã gặp bạn ở chợ trời."],["フリーマーケットでかばんを買いました。","Tôi đã mua cặp ở chợ trời."]]},{"word":"遠慮する","reading":"えんりょする","meaning":"Xin từ chối","hanViet":"VIỄN LỰ","lesson":7,"ex":[["忙しいので、今度のパーティーは遠慮します。","Vì bận nên tôi xin từ chối bữa tiệc lần này."],["田中さんはお酒を遠慮すると言いました。","Anh Tanaka nói rằng anh ấy xin phép không uống rượu."],["遠慮しないで、たくさん食べてください。","Đừng ngại, cứ ăn nhiều vào."],["あの人はいつも遠慮するので、みんなが心配しています。","Người đó lúc nào cũng e ngại nên mọi người đều lo lắng."],["お金がないので、旅行は遠慮することにしました。","Vì không có tiền nên tôi đã quyết định từ chối chuyến du lịch."]]},{"word":"表す","reading":"あらわす","meaning":"Bày tỏ","hanViet":"BIỂU","lesson":7,"ex":[["この絵は春の花を表しています。","Bức tranh này thể hiện hoa mùa xuân."],["その歌は若い人の夢を表しています。","Bài hát đó thể hiện ước mơ của người trẻ."],["この色は秋を表しています。","Màu này thể hiện mùa thu."],["彼はことばで気持ちを表すのが下手です。","Anh ấy không giỏi bày tỏ cảm xúc bằng lời nói."],["その小説は戦争の悲しみを表しています。","Cuốn tiểu thuyết đó thể hiện nỗi buồn của chiến tranh."]]},{"word":"着付け教室","reading":"きつけきょうしつ","meaning":"Lớp học cách mặc Kimono","hanViet":"TRỨ PHÓ GIÁO THẤT","lesson":7,"ex":[["母は毎週、着付け教室に通っています。","Mẹ tôi đến lớp học cách mặc kimono mỗi tuần."],["着付け教室で着物を着る練習をしています。","Tôi đang luyện tập mặc kimono ở lớp học cách mặc kimono."],["姉は着付け教室の先生になりたいと言っています。","Chị gái tôi nói muốn trở thành giáo viên của lớp học cách mặc kimono."],["この着付け教室は駅の近くにあります。","Lớp học cách mặc kimono này ở gần ga."],["着付け教室で習ったので、着物が自分で着られます。","Vì đã học ở lớp mặc kimono nên tôi có thể tự mặc kimono."]]},{"word":"待ち合わせる","reading":"まちあわせる","meaning":"Gặp nhau","hanViet":"ĐÃI HỢP","lesson":7,"ex":[["明日、駅前で友達と待ち合わせます。","Ngày mai tôi sẽ gặp bạn ở trước ga."],["私たちは毎週土曜日に公園で待ち合わせています。","Chúng tôi gặp nhau ở công viên vào thứ Bảy hàng tuần."],["待ち合わせの時間に遅れないように、早く家を出ました。","Tôi đã ra khỏi nhà sớm để không bị muộn giờ hẹn."],["彼女と映画館の前で待ち合わせる約束をしました。","Tôi đã hẹn gặp cô ấy trước rạp chiếu phim."],["待ち合わせる場所は駅の北口にしましょう。","Hãy hẹn gặp ở cửa phía Bắc của ga nhé."]]},{"word":"空く","reading":"あく","meaning":"Rỗi, rảnh rỗi","hanViet":"KHÔNG","lesson":7,"ex":[["午後の時間は空いていますか。","Buổi chiều bạn có rảnh không?"],["来週の日曜日なら、時間が空きます。","Nếu là Chủ nhật tuần sau thì tôi rảnh."],["席が空いたので、座ることができました。","Vì có ghế trống nên tôi đã ngồi được."],["仕事が終わって、やっと時間が空きました。","Công việc xong rồi, cuối cùng tôi cũng rảnh."],["部屋が空いているかどうか、ホテルに聞いてみます。","Tôi sẽ hỏi khách sạn xem còn phòng trống không."]]},{"word":"交流会","reading":"こうりゅうかい","meaning":"Buổi giao lưu","hanViet":"GIAO LƯU HỘI","lesson":7,"ex":[["来月、留学生の交流会があります。","Tháng sau có buổi giao lưu của du học sinh."],["交流会でいろんな国の人と話しました。","Tôi đã nói chuyện với người của nhiều nước ở buổi giao lưu."],["会社の交流会に参加するつもりです。","Tôi định tham gia buổi giao lưu của công ty."],["交流会は毎月一度、市民会館で開かれます。","Buổi giao lưu được tổ chức một lần mỗi tháng ở nhà văn hóa thành phố."],["交流会のおかげで、新しい友達ができました。","Nhờ buổi giao lưu mà tôi đã có bạn mới."]]},{"word":"いろんな","reading":"いろんな","meaning":"Nhiều, nhiều loại","hanViet":"","lesson":7,"ex":[["この店にはいろんな国の料理があります。","Quán này có món ăn của nhiều nước."],["いろんな人に会って、いろんな話を聞きました。","Tôi đã gặp nhiều người và nghe nhiều câu chuyện."],["図書館にはいろんな本が並んでいます。","Thư viện có nhiều loại sách được xếp."],["いろんな方法を考えましたが、うまくいきませんでした。","Tôi đã nghĩ nhiều cách nhưng không thành công."],["休みの日はいろんな所へ行きます。","Ngày nghỉ tôi đi nhiều nơi."]]},{"word":"ゼミ","reading":"ゼミ","meaning":"Giờ thảo luận","hanViet":"","lesson":7,"ex":[["毎週水曜日にゼミがあります。","Thứ Tư hàng tuần có giờ thảo luận."],["ゼミで日本の歴史について話し合いました。","Trong giờ thảo luận, chúng tôi đã thảo luận về lịch sử Nhật Bản."],["ゼミの先生はとても親切です。","Thầy giáo của giờ thảo luận rất tốt bụng."],["ゼミの発表の準備をしなければなりません。","Tôi phải chuẩn bị cho bài thuyết trình trong giờ thảo luận."],["大学のゼミで友達がたくさんできました。","Tôi đã có nhiều bạn ở giờ thảo luận của trường đại học."]]},{"word":"せっかく","reading":"せっかく","meaning":"Cất công, chủ ý","hanViet":"","lesson":7,"ex":[["せっかく日本に来たので、京都へ行きたいです。","Đã cất công đến Nhật Bản nên tôi muốn đi Kyoto."],["せっかく作った料理ですから、たくさん食べてください。","Vì là món ăn tôi đã cất công nấu nên hãy ăn nhiều vào."],["せっかくの休みなので、ゆっくり休みましょう。","Vì là ngày nghỉ hiếm có nên hãy nghỉ ngơi thư thả nhé."],["せっかく誘ってくれたのに、行けなくて残念です。","Bạn đã cất công mời mà tôi không đi được, tiếc quá."],["せっかく買った本をなくしてしまいました。","Tôi đã làm mất cuốn sách mà mình đã cất công mua."]]},{"word":"今回","reading":"こんかい","meaning":"Lần này, dịp này","hanViet":"KIM HỒI","lesson":7,"ex":[["今回の試験は難しかったです。","Kỳ thi lần này khó."],["今回は時間がなかったので、買い物ができませんでした。","Lần này vì không có thời gian nên tôi không đi mua sắm được."],["今回の旅行では、初めて温泉に入りました。","Trong chuyến du lịch lần này, lần đầu tiên tôi tắm suối nước nóng."],["今回は私が料理を作ります。","Lần này tôi sẽ nấu ăn."],["今回の会議は午前十時に始まります。","Cuộc họp lần này bắt đầu lúc 10 giờ sáng."]]},{"word":"同僚","reading":"どうりょう","meaning":"Đồng nghiệp","hanViet":"ĐỒNG LIÊU","lesson":7,"ex":[["同僚と一緒に昼ごはんを食べました。","Tôi đã ăn trưa cùng đồng nghiệp."],["新しい同僚は大阪から来ました。","Đồng nghiệp mới đến từ Osaka."],["同僚に仕事を手伝ってもらいました。","Tôi đã nhờ đồng nghiệp giúp công việc."],["同僚のみんなはとても親切です。","Các đồng nghiệp đều rất tốt bụng."],["同僚と飲みに行く約束をしました。","Tôi đã hẹn đi uống với đồng nghiệp."]]},{"word":"登山","reading":"とざん","meaning":"Leo núi","hanViet":"ĐĂNG SƠN","lesson":7,"ex":[["休みの日に登山を楽しみます。","Ngày nghỉ tôi thích leo núi."],["秋に友達と登山に行く予定です。","Tôi dự định đi leo núi với bạn vào mùa thu."],["登山の前に、水と食べ物を用意しました。","Trước khi leo núi, tôi đã chuẩn bị nước và đồ ăn."],["登山が好きな人は、山の景色が好きだと言います。","Người thích leo núi nói rằng họ thích phong cảnh núi."],["初めて登山をしたときは、とても疲れました。","Lần đầu tiên leo núi, tôi đã rất mệt."]]},{"word":"紅葉","reading":"こうよう","meaning":"Lá đỏ (mùa thu)","hanViet":"HỒNG DIỆP","lesson":7,"ex":[["秋になると、山の紅葉がきれいです。","Vào mùa thu, lá phong đỏ trên núi rất đẹp."],["京都の紅葉を見に行きました。","Tôi đã đi ngắm lá phong đỏ ở Kyoto."],["紅葉の写真をたくさん撮りました。","Tôi đã chụp nhiều ảnh lá phong đỏ."],["紅葉の季節には、多くの人が京都へ行きます。","Vào mùa lá phong đỏ, nhiều người đi Kyoto."],["窓から紅葉が見えます。","Từ cửa sổ có thể nhìn thấy lá phong đỏ."]]},{"word":"見物","reading":"けんぶつ","meaning":"Tham quan","hanViet":"KIẾN VẬT","lesson":7,"ex":[["京都へ見物に行きました。","Tôi đã đi tham quan Kyoto."],["友達と東京を見物しました。","Tôi đã tham quan Tokyo cùng bạn."],["見物する所がたくさんあるので、一日では足りません。","Vì có nhiều nơi để tham quan nên một ngày không đủ."],["神社を見物した後で、お土産を買いました。","Sau khi tham quan đền, tôi đã mua quà lưu niệm."],["見物に来た人で、駅は込んでいました。","Ga đông nghẹt người đến tham quan."]]},{"word":"音楽会","reading":"おんがくかい","meaning":"Buổi biểu diễn âm nhạc","hanViet":"ÂM LẠC HỘI","lesson":7,"ex":[["明日、学校で音楽会があります。","Ngày mai ở trường có buổi biểu diễn âm nhạc."],["音楽会でピアノを弾きました。","Tôi đã chơi piano ở buổi biểu diễn âm nhạc."],["姉は音楽会の準備で忙しいです。","Chị gái tôi bận chuẩn bị cho buổi biểu diễn âm nhạc."],["音楽会のチケットを二枚買いました。","Tôi đã mua hai vé buổi biểu diễn âm nhạc."],["音楽会では、いろんな国の歌を歌います。","Ở buổi biểu diễn âm nhạc, chúng tôi hát bài hát của nhiều nước."]]},{"word":"まんじゅう","reading":"まんじゅう","meaning":"Bánh ngọt nhân đậu đỏ","hanViet":"","lesson":7,"ex":[["お土産にまんじゅうを買いました。","Tôi đã mua bánh ngọt nhân đậu đỏ làm quà."],["このまんじゅうは甘くて、おいしいです。","Bánh này ngọt và ngon."],["お茶とまんじゅうをいただきました。","Tôi đã dùng trà và bánh ngọt nhân đậu đỏ."],["母はまんじゅうを作るのが上手です。","Mẹ tôi giỏi làm bánh ngọt nhân đậu đỏ."],["まんじゅうを三つ食べたら、おなかがいっぱいになりました。","Ăn ba cái bánh là tôi no căng bụng."]]},{"word":"ヘビ","reading":"ヘビ","meaning":"Rắn","hanViet":"","lesson":7,"ex":[["山でヘビを見ました。","Tôi đã thấy rắn ở trên núi."],["ヘビは怖いので、近づきません。","Vì rắn đáng sợ nên tôi không lại gần."],["森の中にヘビがいるかもしれません。","Trong rừng có thể có rắn."],["ヘビに会ったら、静かに逃げましょう。","Nếu gặp rắn, hãy lặng lẽ chạy đi nhé."],["あのヘビは長くて、大きいです。","Con rắn đó dài và to."]]},{"word":"毛虫","reading":"けむし","meaning":"Sâu róm, sâu bướm","hanViet":"MAO TRÙNG","lesson":7,"ex":[["木に毛虫がいました。","Trên cây có sâu róm."],["毛虫に触ると、かゆくなります。","Chạm vào sâu róm sẽ bị ngứa."],["庭の木に毛虫がたくさんついています。","Trên cây trong vườn có rất nhiều sâu róm."],["毛虫を見つけたら、先生に知らせます。","Nếu thấy sâu róm, hãy báo cho thầy giáo."],["毛虫は怖いですが、大きくなるのが楽しみです。","Sâu róm đáng sợ nhưng tôi mong nó lớn lên."]]},{"word":"いばる","reading":"いばる","meaning":"Kiêu ngạo, kiêu căng","hanViet":"","lesson":7,"ex":[["あの人はいつも自分の車をいばっています。","Người đó lúc nào cũng khoe khoang xe của mình."],["彼は試験に合格したといばりました。","Anh ấy khoe khoang rằng mình đã đỗ kỳ thi."],["いばる人は、あまり好きではありません。","Tôi không thích người kiêu ngạo lắm."],["彼は新しい時計を買ったので、友達にいばっています。","Vì mua đồng hồ mới nên anh ấy đang khoe với bạn bè."],["いばらないで、みんなと仲よくしましょう。","Đừng kiêu căng, hãy hòa thuận với mọi người nhé."]]},{"word":"震える","reading":"ふるえる","meaning":"Run","hanViet":"CHẤN","lesson":7,"ex":[["寒くて、手が震えています。","Vì lạnh nên tay tôi đang run."],["怖くて、声が震えました。","Vì sợ nên giọng tôi run lên."],["彼は緊張して、体が震えていました。","Anh ấy căng thẳng nên người run lên."],["地震のとき、家が震えました。","Khi động đất, ngôi nhà rung lên."],["寒いので、体が震えてきました。","Vì lạnh nên người tôi bắt đầu run."]]},{"word":"すると","reading":"すると","meaning":"Lập tức, thế là","hanViet":"","lesson":7,"ex":[["ドアを開けたら、すると犬が走ってきました。","Vừa mở cửa thì con chó chạy đến."],["本を読んでいたら、すると電話が鳴りました。","Đang đọc sách thì điện thoại reo."],["彼に声をかけたら、すると彼は笑いました。","Tôi gọi anh ấy thì anh ấy cười."],["箱を開けたら、すると中から猫が出てきました。","Vừa mở hộp thì con mèo từ trong chui ra."],["ボタンを押したら、すると電気がつきました。","Bấm nút thì đèn sáng lên."]]},{"word":"おれ","reading":"おれ","meaning":"Tao, tớ","hanViet":"","lesson":7,"ex":[["おれは明日、東京へ行きます。","Ngày mai tớ sẽ đi Tokyo."],["おれの名前は田中です。","Tên tớ là Tanaka."],["おれはこの本を読んだことがあります。","Tớ đã từng đọc cuốn sách này."],["おれが手伝います。","Tớ sẽ giúp."],["おれの友達はみんな優しいです。","Bạn bè của tớ đều tốt bụng."]]},{"word":"～ぐらい","reading":"～ぐらい","meaning":"Khoảng, chừng","hanViet":"","lesson":7,"ex":[["これぐらいは、自分でできます。","Ít nhất chừng này thì tôi tự làm được."],["あの人ぐらいは日本語が話せるようになりたいです。","Tôi muốn nói tiếng Nhật giỏi ít nhất như người đó."],["一人ぐらいは手伝ってくれると思います。","Tôi nghĩ ít nhất cũng có một người giúp."],["これぐらいは漢字が読めなければなりません。","Ít nhất chừng này chữ Hán thì phải đọc được."],["十人ぐらいは集まると思います。","Tôi nghĩ ít nhất cũng sẽ tập hợp được mười người."]]},{"word":"お前","reading":"おまえ","meaning":"Mày, cậu","hanViet":"TIỀN","lesson":7,"ex":[["お前は明日、来ることができますか。","Ngày mai cậu có đến được không?"],["お前が言ったことは本当ですか。","Điều cậu nói có thật không?"],["お前と一緒に行きたいです。","Tôi muốn đi cùng cậu."],["お前の本はどこにありますか。","Sách của cậu ở đâu?"],["お前はいつも元気ですね。","Cậu lúc nào cũng khỏe nhỉ."]]},{"word":"丸い","reading":"まるい","meaning":"Tròn","hanViet":"HOÀN","lesson":7,"ex":[["月は丸いです。","Mặt trăng tròn."],["丸いテーブルを買いました。","Tôi đã mua cái bàn tròn."],["丸い顔の子どもが笑っています。","Đứa trẻ mặt tròn đang cười."],["この石は丸くて、きれいです。","Hòn đá này tròn và đẹp."],["丸い形のケーキを作りました。","Tôi đã làm chiếc bánh hình tròn."]]},{"word":"いや","reading":"いや","meaning":"Không","hanViet":"","lesson":7,"ex":[["コーヒーを飲むかどうか聞かれて、「いや、いいです」と答えました。","Khi được hỏi có uống cà phê không, tôi đã nói không, thôi ạ."],["明日行くかどうか聞かれて、「いや、明日は忙しい」と答えました。","Khi được hỏi ngày mai có đi không, tôi đã trả lời là không, ngày mai tôi bận."],["彼は「いや」と言って、知らないと答えました。","Anh ấy nói không và trả lời rằng anh ấy không biết."],["お金が要るかどうか聞かれて、「いや、要りません」と答えました。","Khi được hỏi có cần tiền không, tôi đã trả lời là không, không cần."],["いや、それは違います。","Không, cái đó sai rồi."]]},{"word":"震え出す","reading":"ふるえだす","meaning":"Bắt đầu run rẩy","hanViet":"CHẤN XUẤT","lesson":7,"ex":[["寒くて、体が震え出しました。","Vì lạnh nên người tôi bắt đầu run."],["怖い映画を見て、手が震え出しました。","Xem phim đáng sợ, tay tôi bắt đầu run."],["彼は緊張して、声が震え出しました。","Anh ấy căng thẳng nên giọng bắt đầu run."],["地震が起きると、家が震え出しました。","Động đất xảy ra, ngôi nhà bắt đầu rung."],["怖くて、足が震え出しました。","Vì sợ nên chân tôi bắt đầu run."]]},{"word":"助ける","reading":"たすける","meaning":"Giúp, cứu","hanViet":"TRỢ","lesson":7,"ex":[["困っている人を助けたいです。","Tôi muốn giúp người đang gặp khó khăn."],["友達が私を助けてくれました。","Bạn đã giúp tôi."],["先生は生徒を助けるために、毎日働いています。","Thầy giáo làm việc mỗi ngày để giúp học sinh."],["大きな地震の後で、多くの人が助けられました。","Sau trận động đất lớn, nhiều người đã được cứu."],["彼を助けることが、私の仕事です。","Giúp anh ấy là công việc của tôi."]]},{"word":"次々に","reading":"つぎつぎに","meaning":"Liên tục","hanViet":"THỨ","lesson":7,"ex":[["人が次々に店に入ってきました。","Người lần lượt vào cửa hàng."],["電車が次々に駅に着きました。","Các chuyến tàu lần lượt đến ga."],["新しい店が次々にできています。","Các cửa hàng mới lần lượt mở ra."],["友達が次々に結婚していきます。","Bạn bè lần lượt kết hôn."],["質問が次々に出て、先生は忙しくなりました。","Câu hỏi liên tục xuất hiện, thầy giáo bận rộn hẳn lên."]]},{"word":"目の前","reading":"めのまえ","meaning":"Trước mắt","hanViet":"MỤC TIỀN","lesson":7,"ex":[["目の前に大きな山が見えます。","Trước mắt có thể thấy ngọn núi lớn."],["目の前の店でパンを買いました。","Tôi đã mua bánh mì ở cửa hàng ngay trước mắt."],["目の前に座っている人は田中さんです。","Người đang ngồi trước mặt tôi là anh Tanaka."],["目の前で事故が起きました。","Ngay trước mắt tôi đã xảy ra tai nạn."],["目の前の信号が赤になりました。","Đèn giao thông trước mặt đã chuyển sang đỏ."]]},{"word":"ポツリと","reading":"ポツリと","meaning":"lẩm bẩm","hanViet":"","lesson":7,"ex":[["彼はポツリと疲れたと言いました。","Anh ấy lẩm bẩm rằng mệt quá."],["田中さんはポツリと話しました。","Anh Tanaka nói lẩm bẩm."],["彼はポツリと帰りたいと言いました。","Anh ấy lẩm bẩm rằng muốn về nhà."],["母はポツリと寒いと言いました。","Mẹ lẩm bẩm rằng lạnh quá."],["彼はポツリと答えました。","Anh ấy trả lời lẩm bẩm."]]},{"word":"ホームページ","reading":"ホームページ","meaning":"Website, trang Web","hanViet":"","lesson":7,"ex":[["会社のホームページを見ました。","Tôi đã xem trang web của công ty."],["ホームページに新しい写真を載せました。","Tôi đã đăng ảnh mới lên trang web."],["このホームページは分かりやすいです。","Trang web này dễ hiểu."],["ホームページでチケットを予約しました。","Tôi đã đặt vé trên trang web."],["学校のホームページでお知らせを見ます。","Tôi xem thông báo trên trang web của trường."]]},{"word":"笑い話","reading":"わらいばなし","meaning":"Chuyện cười","hanViet":"TIẾU THOẠI","lesson":7,"ex":[["彼はおもしろい笑い話をしてくれました。","Anh ấy đã kể cho tôi nghe câu chuyện cười thú vị."],["笑い話を聞いて、みんなが笑いました。","Nghe chuyện cười, mọi người đều cười."],["田中さんは笑い話が上手です。","Anh Tanaka giỏi kể chuyện cười."],["笑い話を話すと、教室が明るくなります。","Kể chuyện cười thì lớp học trở nên vui vẻ."],["きのうの笑い話は本当におもしろかったです。","Chuyện cười hôm qua thật sự rất thú vị."]]},{"word":"落語","reading":"らくご","meaning":"Rakugo","hanViet":"LẠC NGỮ","lesson":7,"ex":[["落語を聞きに行きました。","Tôi đã đi nghe rakugo."],["落語は日本の伝統的な芸です。","Rakugo là nghệ thuật truyền thống của Nhật Bản."],["父は落語が好きです。","Bố tôi thích rakugo."],["落語を聞いて、たくさん笑いました。","Nghe rakugo, tôi đã cười rất nhiều."],["落語の会が来週、市民会館であります。","Buổi biểu diễn rakugo sẽ có vào tuần sau ở nhà văn hóa thành phố."]]},{"word":"眠る","reading":"ねむる","meaning":"Ngủ","hanViet":"MIÊN","lesson":8,"ex":[["子どもはもう眠っています。","Đứa trẻ đã ngủ rồi."],["疲れて、早く眠りました。","Vì mệt nên tôi ngủ sớm."],["猫は窓のそばで眠っています。","Con mèo đang ngủ bên cửa sổ."],["彼は電車の中で眠ってしまいました。","Anh ấy đã ngủ quên trên tàu điện."],["静かな部屋でゆっくり眠りたいです。","Tôi muốn ngủ thong thả trong căn phòng yên tĩnh."]]},{"word":"黙る","reading":"だまる","meaning":"Im lặng","hanViet":"MẶC","lesson":8,"ex":[["彼は何も言わないで、黙りました。","Anh ấy im lặng, không nói gì."],["先生が来ると、教室は黙りました。","Thầy giáo đến, lớp học im lặng."],["彼女は怒って、黙ってしまいました。","Cô ấy tức giận nên im lặng hẳn."],["黙って聞いていると、いろんなことが分かります。","Lặng lẽ lắng nghe thì sẽ hiểu được nhiều điều."],["彼はしばらく黙っていました。","Anh ấy im lặng một lúc."]]},{"word":"盗む","reading":"ぬすむ","meaning":"Trộm, ăn trộm","hanViet":"ĐẠO","lesson":8,"ex":[["泥棒が財布を盗みました。","Kẻ trộm đã lấy cắp ví tiền."],["自転車を盗まれて、困っています。","Tôi bị mất trộm xe đạp nên đang gặp rắc rối."],["だれかが私のかばんを盗んだようです。","Có vẻ ai đó đã lấy trộm cặp của tôi."],["お金を盗むのは、悪いことです。","Lấy trộm tiền là việc xấu."],["店の物を盗んではいけません。","Không được lấy trộm đồ trong cửa hàng."]]},{"word":"焦げる","reading":"こげる","meaning":"Cháy, cháy xém","hanViet":"TIÊU","lesson":8,"ex":[["肉が焦げてしまいました。","Thịt đã bị cháy rồi."],["魚を焼きすぎて、焦げました。","Tôi nướng cá quá lửa nên bị cháy."],["ごはんが焦げる匂いがします。","Có mùi cơm cháy."],["パンが焦げたので、もう一度焼きました。","Vì bánh mì bị cháy nên tôi nướng lại."],["焦げたパンは食べられません。","Bánh mì cháy thì không ăn được."]]},{"word":"枯れる","reading":"かれる","meaning":"Héo, khô héo","hanViet":"KHÔ","lesson":8,"ex":[["水をやらないと、花が枯れます。","Không tưới nước thì hoa sẽ héo."],["夏は暑いので、木の葉が枯れました。","Vì mùa hè nóng nên lá cây đã héo khô."],["庭の花が枯れてしまいました。","Hoa trong vườn đã héo mất rồi."],["秋になると、木の葉が枯れます。","Vào mùa thu, lá cây héo khô."],["枯れた花を見て、悲しくなりました。","Nhìn hoa héo, tôi thấy buồn."]]},{"word":"平凡","reading":"へいぼん","meaning":"Bình thường, bình dị","hanViet":"BÌNH PHÀM","lesson":8,"ex":[["私は平凡な毎日を送っています。","Tôi đang sống những ngày bình thường."],["平凡な生活ですが、幸せです。","Cuộc sống bình dị nhưng hạnh phúc."],["彼は平凡な学生です。","Anh ấy là một học sinh bình thường."],["平凡な一日でしたが、楽しかったです。","Một ngày bình thường nhưng vui vẻ."],["平凡な服を着ています。","Tôi đang mặc bộ quần áo bình thường."]]},{"word":"人生","reading":"じんせい","meaning":"Cuộc đời","hanViet":"NHÂN SANH","lesson":8,"ex":[["人生で一番大切なものは家族だと思います。","Trong cuộc đời, thứ quan trọng nhất là gia đình, tôi nghĩ vậy."],["あの人は長い人生でたくさんの仕事をしました。","Người đó trong cuộc đời dài đã làm rất nhiều công việc."],["人生には楽しいことも悲しいこともあります。","Trong cuộc đời có cả chuyện vui lẫn chuyện buồn."],["私はこれからの人生について、よく考えます。","Tôi thường suy nghĩ về cuộc đời của mình từ nay về sau."],["田中さんは人生で初めて日本に来ました。","Anh Tanaka lần đầu tiên trong đời đã đến Nhật Bản."]]},{"word":"免許","reading":"めんきょ","meaning":"Giấy phép","hanViet":"MIỄN HỨA","lesson":8,"ex":[["車を運転するには免許が必要です。","Để lái xe ô tô cần có giấy phép lái xe."],["山田さんは来週免許の試験を受けます。","Anh Yamada tuần sau sẽ thi lấy giấy phép."],["私は去年車の免許を取りました。","Tôi năm ngoái đã lấy bằng lái xe ô tô."],["免許がなければ、車を運転してはいけません。","Nếu không có giấy phép thì không được lái xe ô tô."],["田中さんはバイクの免許も持っています。","Anh Tanaka cũng có bằng lái xe máy."]]},{"word":"退職する","reading":"たいしょくする","meaning":"Về hưu, nghỉ việc","hanViet":"THỐI CHỨC","lesson":8,"ex":[["父は今年の春に会社を退職しました。","Bố tôi mùa xuân năm nay đã nghỉ việc ở công ty."],["退職したあと、田中さんは旅行を楽しみたいです。","Sau khi nghỉ việc, anh Tanaka muốn tận hưởng những chuyến du lịch."],["山田さんは来月退職するつもりです。","Anh Yamada dự định tháng sau sẽ nghỉ việc."],["母は長い間会社で働いて、退職しました。","Mẹ tôi đã làm việc ở công ty một thời gian dài rồi nghỉ việc."],["退職してから、毎日公園を歩いています。","Từ khi nghỉ việc, ngày nào tôi cũng đi bộ ở công viên."]]},{"word":"もったいない","reading":"もったいない","meaning":"Lãng phí","hanViet":"","lesson":8,"ex":[["新しい服を捨てるのはもったいないです。","Vứt quần áo còn mới thì lãng phí."],["電気をつけたまま出かけるのはもったいないです。","Ra ngoài mà để điện bật thì lãng phí."],["もったいないから、古い服は友達にあげます。","Vì phí nên tôi tặng quần áo cũ cho bạn."],["この本はおもしろいのに、読まないのはもったいないです。","Quyển sách này hay thế mà không đọc thì phí."],["この服はまだ新しいのに、捨てるのはもったいないです。","Cái áo này còn mới mà vứt đi thì phí quá."]]},{"word":"鍋","reading":"なべ","meaning":"Nồi","hanViet":"OA","lesson":8,"ex":[["母は大きい鍋でカレーライスを作りました。","Mẹ tôi nấu cơm cà ri bằng cái nồi to."],["この鍋は重いですから、気をつけて持ってください。","Cái nồi này nặng nên hãy cầm cẩn thận."],["鍋に水を入れて、火にかけます。","Đổ nước vào nồi rồi đặt lên bếp."],["冬は鍋料理がおいしいです。","Mùa đông món lẩu rất ngon."],["新しい鍋をデパートで買いました。","Tôi đã mua nồi mới ở cửa hàng bách hóa."]]},{"word":"ことば遣い","reading":"ことばづかい","meaning":"Cách dùng từ ngữ, cách sử dụng ngôn ngữ","hanViet":"KHIỂN","lesson":8,"ex":[["先生のことば遣いはとても丁寧です。","Cách dùng từ của thầy giáo rất lịch sự."],["子どもの前では、ことば遣いに気をつけます。","Trước mặt trẻ con, tôi chú ý cách dùng từ."],["仕事では正しいことば遣いが必要です。","Trong công việc cần cách dùng từ đúng đắn."],["友達とのことば遣いと、先生とのことば遣いは違います。","Cách dùng từ với bạn bè khác với cách dùng từ với thầy giáo."],["日本語のことば遣いを勉強しています。","Tôi đang học cách dùng từ tiếng Nhật."]]},{"word":"生","reading":"なま","meaning":"Sống, tươi","hanViet":"SINH","lesson":8,"ex":[["この魚は生でもおいしいです。","Con cá này ăn sống cũng ngon."],["生の野菜をたくさん食べます。","Tôi ăn nhiều rau sống."],["私は生の魚が好きです。","Tôi thích cá sống."],["生卵を食べるのが好きです。","Tôi thích ăn trứng sống."],["この肉はまだ生ですから、よく焼いてください。","Miếng thịt này còn sống nên hãy nướng kỹ."]]},{"word":"専門的","reading":"せんもんてき","meaning":"Mang tính chuyên môn","hanViet":"CHUYÊN MÔN ĐÍCH","lesson":8,"ex":[["この本は専門的で、少し難しいです。","Quyển sách này mang tính chuyên môn nên hơi khó."],["田中さんは専門的な知識を持っています。","Anh Tanaka có kiến thức chuyên môn."],["専門的な話は、初めて聞く人には分かりません。","Chuyện chuyên môn thì người nghe lần đầu không hiểu được."],["医者は専門的なことを勉強します。","Bác sĩ học những điều mang tính chuyên môn."],["この問題は専門的ですから、私には分かりません。","Vấn đề này mang tính chuyên môn nên tôi không hiểu."]]},{"word":"社会勉強","reading":"しゃかいべんきょう","meaning":"Học hỏi về xã hội xung quanh","hanViet":"XÃ HỘI MIỄN CƯỜNG","lesson":8,"ex":[["アルバイトは社会勉強になります。","Làm thêm trở thành bài học về xã hội."],["旅行も社会勉強の一つです。","Du lịch cũng là một cách học hỏi về xã hội."],["学生の間、社会勉強をたくさんしました。","Hồi còn là học sinh, tôi đã học hỏi về xã hội rất nhiều."],["社会勉強のために、ボランティアに参加しました。","Để học hỏi về xã hội, tôi đã tham gia tình nguyện."],["田中さんは社会勉強が大切だと言います。","Anh Tanaka nói rằng học hỏi về xã hội rất quan trọng."]]},{"word":"高校生","reading":"こうこうせい","meaning":"Học sinh cấp 3","hanViet":"CAO HIỆU SANH","lesson":8,"ex":[["弟は今年高校生になりました。","Em trai tôi năm nay đã trở thành học sinh cấp 3."],["高校生の間、テニスを習いました。","Hồi học cấp 3, tôi đã học chơi tennis."],["妹は高校生で、毎日勉強しています。","Em gái tôi là học sinh cấp 3, ngày nào cũng học."],["高校生は電車で学校に行きます。","Học sinh cấp 3 đi học bằng tàu điện."],["あの高校生はとても元気です。","Học sinh cấp 3 kia rất khỏe mạnh."]]},{"word":"迷子","reading":"まいご","meaning":"Trẻ lạc","hanViet":"MÊ TỬ","lesson":8,"ex":[["デパートで迷子を見つけました。","Tôi đã thấy một đứa trẻ bị lạc ở cửa hàng bách hóa."],["迷子になった子どもを助けました。","Tôi đã giúp đứa trẻ bị lạc."],["迷子がいたら、サービスカウンターに行ってください。","Nếu có trẻ bị lạc, hãy đến quầy dịch vụ."],["母は迷子にならないように、子どもを見ています。","Để con không bị lạc, mẹ luôn để mắt đến con."],["公園で迷子が泣いていました。","Ở công viên có một đứa trẻ bị lạc đang khóc."]]},{"word":"しま","reading":"しま","meaning":"Sọc","hanViet":"","lesson":8,"ex":[["私はしまのシャツが好きです。","Tôi thích áo sơ mi sọc."],["このシャツは青と白のしまです。","Chiếc áo này có sọc xanh và trắng."],["しまのズボンを買いました。","Tôi đã mua quần sọc."],["母はしまのスカートを着ています。","Mẹ tôi đang mặc váy sọc."],["この店にはしまの服がたくさんあります。","Cửa hàng này có rất nhiều quần áo sọc."]]},{"word":"花柄","reading":"はながら","meaning":"Họa tiết hoa","hanViet":"HOA BÍNH","lesson":8,"ex":[["私は花柄のシャツを買いました。","Tôi đã mua áo sơ mi họa tiết hoa."],["母は花柄のスカートが好きです。","Mẹ tôi thích váy họa tiết hoa."],["花柄の傘は春によく売れます。","Ô họa tiết hoa bán chạy vào mùa xuân."],["この花柄は大きい花が特徴です。","Họa tiết hoa này có đặc trưng là hoa to."],["花柄と無地、どちらが好きですか。","Họa tiết hoa và trơn, bạn thích cái nào hơn?"]]},{"word":"チェック","reading":"チェック","meaning":"Kẻ ca rô","hanViet":"","lesson":8,"ex":[["チェックのシャツを着ています。","Tôi đang mặc áo sơ mi kẻ ca rô."],["このチェックのスカートは新しいです。","Chiếc váy kẻ ca rô này còn mới."],["父はチェックのズボンが好きです。","Bố tôi thích quần kẻ ca rô."],["チェックとしま、どちらがいいですか。","Kẻ ca rô và sọc, cái nào tốt hơn?"],["チェックのコートをデパートで買いました。","Tôi đã mua áo khoác kẻ ca rô ở cửa hàng bách hóa."]]},{"word":"スカート","reading":"スカート","meaning":"Váy","hanViet":"","lesson":8,"ex":[["妹は赤いスカートをはいています。","Em gái tôi đang mặc váy đỏ."],["このスカートは長くて、きれいです。","Chiếc váy này dài và đẹp."],["夏は軽いスカートがいいです。","Mùa hè nên mặc váy nhẹ."],["スカートを買う前に、色をよく見ます。","Trước khi mua váy, tôi xem kỹ màu sắc."],["母は私に青いスカートをプレゼントしました。","Mẹ tôi đã tặng tôi một chiếc váy xanh."]]},{"word":"無地","reading":"むじ","meaning":"Không có họa tiết, trơn","hanViet":"VÔ ĐỊA","lesson":8,"ex":[["私は無地のシャツが好きです。","Tôi thích áo sơ mi trơn."],["無地の服は毎日着てもいいです。","Quần áo trơn mặc hàng ngày cũng được."],["この無地のTシャツは安いです。","Chiếc áo thun trơn này rẻ."],["無地と花柄、どちらが好きですか。","Trơn và họa tiết hoa, bạn thích cái nào hơn?"],["父は無地のシャツをよく着ます。","Bố tôi thường mặc áo sơ mi trơn."]]},{"word":"水玉","reading":"みずたま","meaning":"Chấm bi","hanViet":"THỦY NGỌC","lesson":8,"ex":[["水玉のスカートがかわいいです。","Váy chấm bi thật dễ thương."],["この水玉のシャツは白と青です。","Chiếc áo chấm bi này có màu trắng và xanh."],["妹は水玉の傘を持っています。","Em gái tôi có một chiếc ô chấm bi."],["水玉の服を買いました。","Tôi đã mua quần áo chấm bi."],["水玉とチェック、どちらがいいですか。","Chấm bi và kẻ ca rô, cái nào tốt hơn?"]]},{"word":"リュック","reading":"リュック","meaning":"Ba lô","hanViet":"","lesson":8,"ex":[["山に行く日は、リュックを持ちます。","Ngày đi leo núi, tôi mang ba lô."],["このリュックは大きくて、たくさん入ります。","Ba lô này to, đựng được rất nhiều đồ."],["リュックに本を入れました。","Tôi đã bỏ sách vào ba lô."],["旅行の前に、リュックに服を入れます。","Trước chuyến du lịch, tôi bỏ quần áo vào ba lô."],["新しいリュックを買いました。","Tôi đã mua ba lô mới."]]},{"word":"背負う","reading":"せおう","meaning":"Đeo","hanViet":"BỐI PHỤ","lesson":8,"ex":[["山田さんは重いリュックを背負っています。","Anh Yamada đang đeo ba lô nặng."],["子どもはリュックを背負って歩きます。","Trẻ con đeo ba lô đi bộ."],["弟は小さいリュックを背負いました。","Em trai tôi đã đeo ba lô nhỏ."],["重い荷物を背負って、山を登ります。","Tôi đeo hành lý nặng rồi leo núi."],["山に行く人は大きいリュックを背負います。","Người đi leo núi đeo ba lô to."]]},{"word":"サービスカウンター","reading":"サービスカウンター","meaning":"Quầy dịch vụ","hanViet":"","lesson":8,"ex":[["分からないことがあったら、サービスカウンターに聞いてください。","Nếu có điều gì không hiểu, hãy hỏi ở quầy dịch vụ."],["サービスカウンターで道を聞きました。","Tôi đã hỏi đường ở quầy dịch vụ."],["サービスカウンターはデパートの中にあります。","Quầy dịch vụ ở bên trong cửa hàng bách hóa."],["サービスカウンターの人が親切に教えてくれました。","Người ở quầy dịch vụ đã chỉ dẫn tôi một cách thân thiện."],["落とした財布はサービスカウンターにありました。","Chiếc ví tôi đánh rơi đã ở quầy dịch vụ."]]},{"word":"姪","reading":"めい","meaning":"Cháu gái","hanViet":"ĐIỆT","lesson":8,"ex":[["私の姪は高校生です。","Cháu gái tôi là học sinh cấp 3."],["姪に誕生日のプレゼントをあげました。","Tôi đã tặng quà sinh nhật cho cháu gái."],["姪はピアノが上手です。","Cháu gái tôi chơi piano giỏi."],["姪と映画を見ました。","Tôi đã xem phim cùng cháu gái."],["姪は来年大学に入ります。","Cháu gái tôi năm sau sẽ vào đại học."]]},{"word":"特徴","reading":"とくちょう","meaning":"Đặc trưng","hanViet":"ĐẶC TRƯNG","lesson":8,"ex":[["この町の特徴は静かなことです。","Đặc trưng của thị trấn này là yên tĩnh."],["日本の特徴について話します。","Tôi nói về đặc trưng của Nhật Bản."],["あの人の特徴は身長が高いことです。","Đặc trưng của người đó là dáng cao."],["この店の特徴は安いことです。","Đặc trưng của cửa hàng này là rẻ."],["特徴をよく見て、覚えてください。","Hãy nhìn kỹ đặc trưng rồi ghi nhớ."]]},{"word":"身長","reading":"しんちょう","meaning":"Chiều cao","hanViet":"THÂN TRƯỞNG","lesson":8,"ex":[["私の身長は弟より高いです。","Chiều cao của tôi cao hơn em trai."],["妹の身長は私と同じです。","Chiều cao của em gái tôi bằng tôi."],["身長が高い人はスポーツが上手です。","Người cao thường giỏi thể thao."],["子どもの身長は毎年高くなります。","Chiều cao của trẻ con năm nào cũng tăng lên."],["姉の身長は母より低いです。","Chiều cao của chị tôi thấp hơn mẹ."]]},{"word":"ジーンズ","reading":"ジーンズ","meaning":"Quần Jean","hanViet":"","lesson":8,"ex":[["私はジーンズが好きです。","Tôi thích quần Jean."],["新しいジーンズを買いました。","Tôi đã mua quần Jean mới."],["このジーンズは丈夫ですから、毎日はきます。","Quần Jean này bền nên ngày nào tôi cũng mặc."],["父はジーンズをはいて出かけました。","Bố tôi mặc quần Jean rồi ra ngoài."],["夏はジーンズよりスカートが涼しいです。","Mùa hè váy mát hơn quần Jean."]]},{"word":"髪型","reading":"かみがた","meaning":"Kiểu tóc","hanViet":"PHÁT HÌNH","lesson":8,"ex":[["妹は新しい髪型にしました。","Em gái tôi đã đổi kiểu tóc mới."],["この髪型は若い人に人気があります。","Kiểu tóc này được giới trẻ yêu thích."],["髪型を変えたら、みんな驚きました。","Khi tôi đổi kiểu tóc, mọi người đều ngạc nhiên."],["美容院で髪型を変えました。","Tôi đã đổi kiểu tóc ở tiệm làm tóc."],["田中さんの髪型は短いです。","Kiểu tóc của anh Tanaka ngắn."]]},{"word":"肩","reading":"かた","meaning":"Vai","hanViet":"KIÊN","lesson":8,"ex":[["重いかばんを持って、肩が疲れました。","Xách túi nặng nên vai tôi mỏi."],["肩にリュックをかけました。","Tôi đã khoác ba lô lên vai."],["肩に手を置きました。","Tôi đã đặt tay lên vai."],["肩まで髪が長いです。","Tóc dài đến vai."],["肩の上に猫が乗っています。","Có một con mèo đang ngồi trên vai tôi."]]},{"word":"持ち物","reading":"もちもの","meaning":"Đồ dùng cá nhân, đồ mang theo","hanViet":"TRÌ VẬT","lesson":8,"ex":[["旅行の前に、持ち物を準備します。","Trước chuyến du lịch, tôi chuẩn bị đồ mang theo."],["持ち物を忘れないでください。","Đừng quên đồ mang theo."],["学校の持ち物はリュックに入れます。","Đồ dùng học tập tôi bỏ vào ba lô."],["持ち物がたくさんあります。","Có rất nhiều đồ mang theo."],["持ち物を全部持っています。","Tôi mang theo tất cả đồ dùng."]]},{"word":"水色","reading":"みずいろ","meaning":"Màu xanh nhạt","hanViet":"THỦY SẮC","lesson":8,"ex":[["水色のシャツを買いました。","Tôi đã mua áo sơ mi màu xanh nhạt."],["水色の空がきれいです。","Bầu trời màu xanh nhạt thật đẹp."],["妹は水色のスカートが好きです。","Em gái tôi thích váy màu xanh nhạt."],["水色の傘は雨の日に使います。","Ô màu xanh nhạt tôi dùng vào ngày mưa."],["水色と白、どちらがいいですか。","Màu xanh nhạt và màu trắng, cái nào tốt hơn?"]]},{"word":"折りたたみ","reading":"おりたたみ","meaning":"Gập, gấp","hanViet":"CHIẾT","lesson":8,"ex":[["折りたたみ傘を持っています。","Tôi có ô gấp."],["折りたたみのいすは便利です。","Ghế gấp rất tiện lợi."],["折りたたみ傘は小さくて、かばんに入ります。","Ô gấp nhỏ gọn, bỏ vừa trong túi."],["雨が降りそうなので、折りたたみ傘を持ちます。","Vì trời sắp mưa nên tôi mang ô gấp."],["折りたたみのテーブルを買いました。","Tôi đã mua bàn gấp."]]},{"word":"青地","reading":"あおじ","meaning":"Nền màu xanh","hanViet":"THANH ĐỊA","lesson":8,"ex":[["青地のシャツを着ています。","Tôi đang mặc áo sơ mi nền xanh."],["この傘は青地に白い花があります。","Chiếc ô này nền xanh có hoa trắng."],["青地のスカートが好きです。","Tôi thích váy nền xanh."],["青地の服は夏にいいです。","Quần áo nền xanh hợp với mùa hè."],["青地に水玉のスカートを買いました。","Tôi đã mua váy nền xanh chấm bi."]]},{"word":"～地","reading":"～じ","meaning":"Nền","hanViet":"ĐỊA","lesson":8,"ex":[["白地のシャツが好きです。","Tôi thích áo sơ mi nền trắng."],["赤地のスカートを買いました。","Tôi đã mua váy nền đỏ."],["黒地に白い花の服があります。","Có quần áo nền đen hoa trắng."],["青地の傘と白地の傘、どちらがいいですか。","Ô nền xanh và ô nền trắng, cái nào tốt hơn?"],["この服は白地です。","Bộ quần áo này nền trắng."]]},{"word":"持つところ","reading":"もつところ","meaning":"Cán, tay cầm","hanViet":"TRÌ","lesson":8,"ex":[["このかばんの持つところは太いです。","Tay cầm của chiếc túi này dày."],["傘の持つところが壊れました。","Tay cầm của chiếc ô đã hỏng."],["持つところが熱いので、気をつけてください。","Tay cầm nóng nên hãy cẩn thận."],["鍋の持つところを持ってください。","Hãy cầm cán nồi."],["このバッグの持つところはどこですか。","Tay cầm của chiếc túi này ở đâu?"]]},{"word":"プラスチック","reading":"プラスチック","meaning":"Nhựa","hanViet":"","lesson":8,"ex":[["このコップはプラスチックです。","Cái cốc này bằng nhựa."],["プラスチックの傘は軽いです。","Ô nhựa nhẹ."],["プラスチックのごみが増えています。","Rác nhựa đang tăng lên."],["プラスチックの箱に本を入れます。","Tôi bỏ sách vào hộp nhựa."],["このかばんはプラスチックでできています。","Chiếc túi này làm bằng nhựa."]]},{"word":"途上国","reading":"とじょうこく","meaning":"Quốc gia đang phát triển","hanViet":"ĐỒ THƯỢNG QUỐC","lesson":8,"ex":[["途上国では水が大切です。","Ở các quốc gia đang phát triển, nước rất quan trọng."],["途上国の子どもたちに本を送ります。","Tôi gửi sách cho trẻ em ở các quốc gia đang phát triển."],["日本は途上国を助けています。","Nhật Bản đang giúp đỡ các quốc gia đang phát triển."],["途上国について勉強しています。","Tôi đang học về các quốc gia đang phát triển."],["途上国と先進国について考えます。","Tôi suy nghĩ về các quốc gia đang phát triển và các quốc gia phát triển."]]},{"word":"先進国","reading":"せんしんこく","meaning":"Quốc gia phát triển","hanViet":"TIÊN TIẾN QUỐC","lesson":8,"ex":[["日本は先進国の一つです。","Nhật Bản là một trong các quốc gia phát triển."],["先進国では車が多いです。","Ở các quốc gia phát triển có nhiều xe ô tô."],["先進国の生活について話します。","Tôi nói về cuộc sống ở các quốc gia phát triển."],["先進国と途上国は違います。","Các quốc gia phát triển khác với các quốc gia đang phát triển."],["先進国に留学したいです。","Tôi muốn đi du học ở một quốc gia phát triển."]]},{"word":"プラス","reading":"プラス","meaning":"Mặt được, điểm cộng","hanViet":"","lesson":8,"ex":[["スポーツは体にプラスです。","Thể thao tốt cho cơ thể."],["この仕事のプラスは給料が高いことです。","Điểm cộng của công việc này là lương cao."],["プラスとマイナスを考えて、決めます。","Tôi cân nhắc mặt được và mặt chưa được rồi quyết định."],["日本語の勉強は人生にプラスです。","Học tiếng Nhật là điểm cộng cho cuộc đời."],["田舎の生活のプラスは静かなことです。","Điểm cộng của cuộc sống ở nông thôn là yên tĩnh."]]},{"word":"マイナス","reading":"マイナス","meaning":"Mặt không được, điểm trừ","hanViet":"","lesson":8,"ex":[["この仕事のマイナスは忙しいことです。","Điểm trừ của công việc này là bận rộn."],["都会の生活のマイナスはお金がかかることです。","Điểm trừ của cuộc sống ở thành phố là tốn tiền."],["プラスもマイナスもあります。","Có cả mặt được lẫn mặt chưa được."],["マイナスばかり見てはいけません。","Không được chỉ nhìn vào mặt chưa được."],["冬のマイナスは寒いことです。","Điểm trừ của mùa đông là lạnh."]]},{"word":"共通","reading":"きょうつう","meaning":"Chung","hanViet":"CỘNG THÔNG","lesson":8,"ex":[["私と田中さんの意見は共通しています。","Ý kiến của tôi và anh Tanaka giống nhau."],["二人の共通の友達がいます。","Có bạn chung của hai người."],["共通の夢を持っています。","Chúng tôi có ước mơ chung."],["日本とベトナムには共通の文化があります。","Nhật Bản và Việt Nam có văn hóa chung."],["共通の趣味について話しました。","Chúng tôi đã nói chuyện về sở thích chung."]]},{"word":"関心","reading":"かんしん","meaning":"Sự quan tâm","hanViet":"QUAN TÂM","lesson":8,"ex":[["私は環境に関心があります。","Tôi quan tâm đến môi trường."],["田中さんは日本の歴史に関心があります。","Anh Tanaka quan tâm đến lịch sử Nhật Bản."],["関心のある仕事をしたいです。","Tôi muốn làm công việc mà mình quan tâm."],["子どもは動物に関心があります。","Trẻ con quan tâm đến động vật."],["社会問題に関心を持つ人が多いです。","Có nhiều người quan tâm đến vấn đề xã hội."]]},{"word":"多様化","reading":"たようか","meaning":"Đa dạng hóa","hanViet":"ĐA DẠNG HÓA","lesson":8,"ex":[["日本の社会は多様化しています。","Xã hội Nhật Bản đang đa dạng hóa."],["仕事の形が多様化しています。","Hình thức công việc đang đa dạng hóa."],["多様化する社会について考えます。","Tôi suy nghĩ về xã hội đang đa dạng hóa."],["生活の多様化について話します。","Tôi nói về sự đa dạng hóa trong cuộc sống."],["多様化はいいことだと思います。","Tôi nghĩ đa dạng hóa là điều tốt."]]},{"word":"タイトル","reading":"タイトル","meaning":"Tiêu đề","hanViet":"","lesson":8,"ex":[["この本のタイトルは「日本の山」です。","Tiêu đề của cuốn sách này là Núi Nhật Bản."],["映画のタイトルを見ただけで、どんな映画かわかりますか。","Chỉ nhìn tiêu đề phim thôi, bạn có biết đó là phim gì không?"],["私は日記のタイトルを毎日考えます。","Mỗi ngày tôi đều nghĩ tiêu đề cho nhật ký."],["タイトルがおもしろいので、この本を買いました。","Vì tiêu đề thú vị nên tôi đã mua cuốn sách này."],["この曲のタイトルを教えてください。","Hãy cho tôi biết tiêu đề của bài nhạc này."]]},{"word":"反対に","reading":"はんたいに","meaning":"Ngược lại, trái ngược","hanViet":"PHẢN ĐỐI","lesson":8,"ex":[["兄は静かですが、反対に弟はにぎやかです。","Anh trai tôi trầm tính, nhưng ngược lại em trai tôi rất ồn ào."],["東京は人が多いですが、反対にこの町は人が少ないです。","Tokyo đông người, nhưng ngược lại thị trấn này ít người."],["夏は暑いですが、反対に冬は寒いです。","Mùa hè nóng, nhưng ngược lại mùa đông lạnh."],["彼は日本語が上手ですが、反対に英語が苦手です。","Anh ấy giỏi tiếng Nhật, nhưng ngược lại tiếng Anh thì kém."],["きのうは晴れましたが、反対にきょうは雨です。","Hôm qua trời nắng, nhưng ngược lại hôm nay trời mưa."]]},{"word":"前後","reading":"ぜんご","meaning":"Trước sau","hanViet":"TIỀN HẬU","lesson":8,"ex":[["試合の前後に、選手は練習します。","Trước và sau trận đấu, các vận động viên luyện tập."],["映画の前後に、友達と会いました。","Trước và sau buổi chiếu phim, tôi đã gặp bạn."],["授業の前後に、友達と話します。","Trước và sau giờ học, tôi nói chuyện với bạn."],["試験の前後に、よく寝てください。","Trước và sau bài kiểm tra, hãy ngủ thật ngon."],["誕生日の前後に、家族の写真を撮りました。","Trước và sau ngày sinh nhật, tôi đã chụp ảnh gia đình."]]},{"word":"対象","reading":"たいしょう","meaning":"Đối tượng","hanViet":"ĐỐI TƯỢNG","lesson":8,"ex":[["この本の対象は、子どもです。","Đối tượng của cuốn sách này là trẻ em."],["この映画の対象は、大人です。","Đối tượng của bộ phim này là người lớn."],["調査の対象は、大学生です。","Đối tượng khảo sát là sinh viên đại học."],["この番組の対象は、家族です。","Đối tượng của chương trình này là các gia đình."],["この本の対象はだれですか。","Đối tượng của cuốn sách này là ai?"]]},{"word":"少女","reading":"しょうじょ","meaning":"Bé gái","hanViet":"THIẾU NỮ","lesson":8,"ex":[["公園で少女が遊んでいます。","Ở công viên, một bé gái đang chơi."],["その少女はピアノが上手です。","Bé gái đó chơi piano giỏi."],["少女は本を読んでいます。","Bé gái đang đọc sách."],["少女が歌っています。","Bé gái đang hát."],["その少女は私の妹です。","Bé gái đó là em gái tôi."]]},{"word":"アイディア","reading":"アイディア","meaning":"Ý tưởng","hanViet":"","lesson":8,"ex":[["いいアイディアがありますか。","Bạn có ý tưởng hay nào không?"],["先生は新しいアイディアを考えました。","Thầy giáo đã nghĩ ra ý tưởng mới."],["このアイディアはおもしろいですね。","Ý tưởng này thú vị nhỉ."],["友達のアイディアで、旅行の計画を作りました。","Nhờ ý tưởng của bạn mà tôi đã làm kế hoạch du lịch."],["アイディアを出すのは難しいです。","Nghĩ ra ý tưởng thật khó."]]},{"word":"輝く","reading":"かがやく","meaning":"Tỏa sáng, rực rỡ","hanViet":"HUY","lesson":8,"ex":[["星が空で輝いています。","Những ngôi sao đang tỏa sáng trên bầu trời."],["彼女の目が輝いています。","Đôi mắt cô ấy đang sáng lên."],["太陽が輝いて、暖かい日です。","Mặt trời tỏa sáng, là một ngày ấm áp."],["雪が太陽の下で輝いています。","Tuyết tỏa sáng dưới ánh mặt trời."],["月が空に輝いています。","Mặt trăng đang tỏa sáng trên bầu trời."]]},{"word":"浮力","reading":"ふりょく","meaning":"Lực nổi, lực đẩy Archimedes","hanViet":"PHÙ LỰC","lesson":8,"ex":[["浮力は、水の中で物を上に上げる力です。","Lực nổi là lực nâng vật lên trong nước."],["船は浮力で水の上に上がります。","Thuyền nổi lên mặt nước nhờ lực nổi."],["浮力が大きいと、重い船も水の上を走ります。","Khi lực nổi lớn, thuyền nặng cũng chạy trên mặt nước."],["プールで泳ぐと、浮力のおかげで体が軽くなります。","Khi bơi trong hồ bơi, nhờ lực nổi mà cơ thể trở nên nhẹ hơn."],["先生は浮力について説明しました。","Thầy giáo đã giải thích về lực nổi."]]},{"word":"少年","reading":"しょうねん","meaning":"Thiếu niên","hanViet":"THIẾU NIÊN","lesson":8,"ex":[["少年が公園でサッカーをしています。","Một thiếu niên đang chơi bóng đá ở công viên."],["その少年は私の弟です。","Thiếu niên đó là em trai tôi."],["少年は自転車に乗っています。","Thiếu niên đang đi xe đạp."],["少年が本を読んでいます。","Thiếu niên đang đọc sách."],["少年は毎日学校に行きます。","Thiếu niên đi học mỗi ngày."]]},{"word":"キノコ雲","reading":"キノコぐも","meaning":"Đám mây hình nấm được tạo ra do các vụ thử nghiệm vũ khí hạt nhân","hanViet":"VÂN","lesson":8,"ex":[["キノコ雲は、空に高く上がります。","Đám mây hình nấm bay lên cao trên bầu trời."],["写真でキノコ雲を見ました。","Tôi đã thấy đám mây hình nấm trong ảnh."],["キノコ雲は、キノコに似ています。","Đám mây hình nấm giống cây nấm."],["先生はキノコ雲について説明しました。","Thầy giáo đã giải thích về đám mây hình nấm."],["キノコ雲を見たことがありますか。","Bạn đã từng thấy đám mây hình nấm chưa?"]]},{"word":"時に","reading":"ときに","meaning":"Đôi khi, thỉnh thoảng","hanViet":"THÌ","lesson":8,"ex":[["私は時に、一人で映画を見ます。","Đôi khi tôi xem phim một mình."],["彼は時に、遅刻します。","Thỉnh thoảng anh ấy đi muộn."],["時に、友達とカラオケに行きます。","Thỉnh thoảng tôi đi karaoke với bạn."],["母は時に、ケーキを作ります。","Thỉnh thoảng mẹ tôi làm bánh."],["時に雨が降りますが、たいてい晴れています。","Thỉnh thoảng trời mưa, nhưng thường thì nắng."]]},{"word":"ダメージ","reading":"ダメージ","meaning":"Tổn thất, thiệt hại","hanViet":"","lesson":8,"ex":[["台風で、町は大きなダメージを受けました。","Vì bão mà thị trấn đã chịu thiệt hại lớn."],["地震のダメージは、とても大きいです。","Thiệt hại của trận động đất rất lớn."],["ダメージを小さくするために、準備をします。","Để giảm thiệt hại, chúng tôi chuẩn bị."],["この地震で、家はダメージを受けました。","Trong trận động đất này, ngôi nhà đã bị thiệt hại."],["ダメージがないか、見てください。","Hãy xem có thiệt hại gì không."]]},{"word":"与える","reading":"あたえる","meaning":"Gây ra, đem lại, cho","hanViet":"DỮ","lesson":8,"ex":[["台風は町に大きなダメージを与えました。","Cơn bão đã gây ra thiệt hại lớn cho thị trấn."],["地震は家にダメージを与えました。","Trận động đất đã gây thiệt hại cho ngôi nhà."],["先生の言葉は私に元気を与えました。","Lời của thầy giáo đã tiếp thêm sức mạnh cho tôi."],["彼の言葉は私に希望を与えました。","Lời của anh ấy đã cho tôi hy vọng."],["彼は私にいいアイディアを与えました。","Anh ấy đã cho tôi một ý tưởng hay."]]},{"word":"ひげ","reading":"ひげ","meaning":"Râu, ria mép","hanViet":"","lesson":8,"ex":[["父はひげがあります。","Bố tôi có râu."],["その人は白いひげがあります。","Người đó có râu trắng."],["ひげが少し伸びました。","Râu đã dài ra một chút."],["彼はひげが長いです。","Anh ấy râu dài."],["彼はひげがないので、若く見えます。","Vì không có râu nên anh ấy trông trẻ."]]},{"word":"伸びる","reading":"のびる","meaning":"Dài ra, mọc dài, cao lên, tăng lên, tiến bộ","hanViet":"THÂN","lesson":8,"ex":[["髪が伸びました。","Tóc đã dài ra."],["ひげが伸びました。","Râu đã dài ra."],["木が伸びました。","Cây đã cao lên."],["昼の時間が伸びました。","Thời gian ban ngày đã dài ra."],["私の日本語が伸びました。","Tiếng Nhật của tôi đã tiến bộ."]]},{"word":"発展する","reading":"はってんする","meaning":"Phát triển","hanViet":"PHÁT TRIỂN","lesson":8,"ex":[["この町は発展しています。","Thị trấn này đang phát triển."],["東京は大きく発展しました。","Tokyo đã phát triển lớn."],["日本の技術が発展しています。","Công nghệ của Nhật Bản đang phát triển."],["インターネットは速く発展しました。","Internet đã phát triển nhanh chóng."],["大阪はどんどん発展しています。","Osaka đang phát triển nhanh chóng."]]},{"word":"魅力","reading":"みりょく","meaning":"Sự hấp dẫn, sự quyến rũ","hanViet":"MỊ LỰC","lesson":8,"ex":[["この町には魅力があります。","Thị trấn này có sức hấp dẫn."],["彼の魅力は、声です。","Sức hấp dẫn của anh ấy là giọng nói."],["日本の魅力は、食べ物です。","Sức hấp dẫn của Nhật Bản là đồ ăn."],["この本の魅力は、写真です。","Sức hấp dẫn của cuốn sách này là những bức ảnh."],["京都の魅力について話しました。","Chúng tôi đã nói về sức hấp dẫn của Kyoto."]]},{"word":"豊か","reading":"ゆたか","meaning":"Giàu có, đầy đủ","hanViet":"PHONG","lesson":8,"ex":[["日本は豊かな国です。","Nhật Bản là đất nước giàu có."],["この町は自然が豊かです。","Thị trấn này thiên nhiên phong phú."],["豊かな心が大切です。","Một tâm hồn phong phú rất quan trọng."],["この国は水が豊かです。","Đất nước này dồi dào nước."],["豊かな生活をしたいです。","Tôi muốn có cuộc sống đầy đủ."]]},{"word":"テーマ","reading":"テーマ","meaning":"Chủ đề, đề tài","hanViet":"","lesson":8,"ex":[["きょうのテーマは「家族」です。","Chủ đề hôm nay là Gia đình."],["発表のテーマを決めました。","Tôi đã quyết định chủ đề thuyết trình."],["この映画のテーマは、家族です。","Chủ đề của bộ phim này là gia đình."],["テーマについて話しました。","Chúng tôi đã nói về chủ đề."],["先生はテーマを説明しました。","Thầy giáo đã giải thích chủ đề."]]},{"word":"述べる","reading":"のべる","meaning":"Bày tỏ, nói ra","hanViet":"THUẬT","lesson":8,"ex":[["先生は意見を述べました。","Thầy giáo đã bày tỏ ý kiến."],["彼は自分の気持ちを述べました。","Anh ấy đã bày tỏ cảm xúc của mình."],["会議で意見を述べました。","Tôi đã bày tỏ ý kiến trong cuộc họp."],["彼女は希望を述べました。","Cô ấy đã bày tỏ mong muốn."],["彼はみんなの前で意見を述べました。","Anh ấy đã bày tỏ ý kiến trước mọi người."]]},{"word":"決まる","reading":"きまる","meaning":"Được quyết định, đã định","hanViet":"QUYẾT","lesson":9,"ex":[["試合の日が決まりました。","Ngày thi đấu đã được quyết định."],["旅行の計画が決まりました。","Kế hoạch du lịch đã được quyết định."],["来週の予定が決まりました。","Lịch tuần tới đã được quyết định."],["まだ何も決まっていません。","Vẫn chưa quyết định gì cả."],["会議の時間が決まりました。","Giờ họp đã được quyết định."]]},{"word":"済む","reading":"すむ","meaning":"Xong, kết thúc","hanViet":"TẾ","lesson":9,"ex":[["宿題が済みました。","Bài tập đã xong."],["仕事が済んだら、帰ります。","Khi công việc xong, tôi sẽ về."],["準備が済みました。","Đã chuẩn bị xong."],["昼ごはんが済んだら、散歩します。","Ăn trưa xong, tôi sẽ đi dạo."],["試験が済んだら、旅行に行きます。","Thi xong, tôi sẽ đi du lịch."]]},{"word":"印鑑","reading":"いんかん","meaning":"Con dấu","hanViet":"ẤN GIÁM","lesson":9,"ex":[["印鑑を持っています。","Tôi có con dấu."],["書類に印鑑を押してください。","Hãy đóng dấu vào tài liệu."],["印鑑を忘れました。","Tôi quên mang con dấu."],["日本では、印鑑を使います。","Ở Nhật, người ta dùng con dấu."],["印鑑は銀行で使います。","Con dấu được dùng ở ngân hàng."]]},{"word":"サイン","reading":"サイン","meaning":"Chữ ký","hanViet":"","lesson":9,"ex":[["ここにサインをしてください。","Hãy ký ở đây."],["紙にサインを書きました。","Tôi đã ký vào giấy."],["サインを忘れないでください。","Đừng quên ký."],["歌手のサインをもらいました。","Tôi đã xin được chữ ký của ca sĩ."],["サインと印鑑は違います。","Chữ ký và con dấu khác nhau."]]},{"word":"性能","reading":"せいのう","meaning":"Hiệu năng, khả năng hoạt động","hanViet":"TÍNH NĂNG","lesson":9,"ex":[["このパソコンの性能はいいです。","Hiệu năng của máy tính này tốt."],["新しい車の性能は高いです。","Hiệu năng của xe mới cao."],["性能を比べてください。","Hãy so sánh hiệu năng."],["このカメラの性能はとてもいいです。","Hiệu năng của máy ảnh này rất tốt."],["性能と値段を考えて買います。","Tôi cân nhắc hiệu năng và giá cả rồi mua."]]},{"word":"タイプ","reading":"タイプ","meaning":"Kiểu","hanViet":"","lesson":9,"ex":[["どんなタイプの車が好きですか。","Bạn thích kiểu xe nào?"],["このタイプのパソコンを使います。","Tôi dùng kiểu máy tính này."],["新しいタイプのカメラを買いました。","Tôi đã mua kiểu máy ảnh mới."],["タイプが違うと、値段も違います。","Kiểu khác nhau thì giá cũng khác nhau."],["私はシンプルなタイプが好きです。","Tôi thích kiểu đơn giản."]]},{"word":"機能","reading":"きのう","meaning":"Chức năng","hanViet":"CƠ NĂNG","lesson":9,"ex":[["このカメラには新しい機能があります。","Máy ảnh này có chức năng mới."],["機能が多いパソコンを買いました。","Tôi đã mua máy tính có nhiều chức năng."],["この機能は便利です。","Chức năng này tiện lợi."],["機能を全部使いますか。","Bạn có dùng hết các chức năng không?"],["この電話の機能が増えました。","Chức năng của điện thoại này đã tăng lên."]]},{"word":"平日","reading":"へいじつ","meaning":"Các ngày trong tuần","hanViet":"BÌNH NHẬT","lesson":9,"ex":[["平日は学校に行きます。","Ngày trong tuần tôi đi học."],["平日は仕事があります。","Ngày trong tuần tôi có việc."],["平日は人が少ないです。","Ngày trong tuần ít người."],["土曜日と日曜日は休みですが、平日は働きます。","Thứ bảy và chủ nhật nghỉ, còn ngày trong tuần thì làm việc."],["平日に映画を見ました。","Tôi đã xem phim vào ngày trong tuần."]]},{"word":"将棋","reading":"しょうぎ","meaning":"Cờ tướng Nhật Bản","hanViet":"TƯƠNG KỲ","lesson":9,"ex":[["祖父は将棋が上手です。","Ông tôi chơi cờ shogi giỏi."],["友達と将棋をしました。","Tôi đã chơi shogi với bạn."],["将棋は日本のゲームです。","Shogi là trò chơi của Nhật Bản."],["毎週、将棋をします。","Mỗi tuần tôi chơi shogi."],["将棋を習っています。","Tôi đang học shogi."]]},{"word":"自慢する","reading":"じまんする","meaning":"Tự mãn, tự kiêu, hãnh diện","hanViet":"TỰ MẠN","lesson":9,"ex":[["彼は自分の車を自慢します。","Anh ấy khoe chiếc xe của mình."],["母は娘を自慢しています。","Mẹ tự hào về con gái."],["彼女は歌が上手だと自慢します。","Cô ấy khoe rằng mình hát hay."],["自慢しないでください。","Đừng khoe khoang."],["彼は英語が話せると自慢しました。","Anh ấy khoe rằng mình nói được tiếng Anh."]]},{"word":"豚肉","reading":"ぶたにく","meaning":"Thịt heo, thịt lợn","hanViet":"TRƯ NHỤC","lesson":9,"ex":[["豚肉を買いました。","Tôi đã mua thịt heo."],["豚肉で料理を作ります。","Tôi nấu ăn bằng thịt heo."],["豚肉は牛肉より安いです。","Thịt heo rẻ hơn thịt bò."],["豚肉が好きですか。","Bạn thích thịt heo không?"],["豚肉を食べません。","Tôi không ăn thịt heo."]]},{"word":"牛肉","reading":"ぎゅうにく","meaning":"Thịt bò","hanViet":"NGƯU NHỤC","lesson":9,"ex":[["牛肉は高いですが、おいしいです。","Thịt bò đắt nhưng ngon."],["牛肉を少し買いました。","Tôi đã mua một ít thịt bò."],["牛肉で料理を作りました。","Tôi đã nấu ăn bằng thịt bò."],["牛肉が好きな人は多いです。","Có nhiều người thích thịt bò."],["牛肉はどこで買いますか。","Thịt bò mua ở đâu?"]]},{"word":"バレーボール","reading":"バレーボール","meaning":"Bóng chuyền","hanViet":"","lesson":9,"ex":[["バレーボールが好きです。","Tôi thích bóng chuyền."],["友達とバレーボールをします。","Tôi chơi bóng chuyền với bạn."],["バレーボールの試合を見ました。","Tôi đã xem trận đấu bóng chuyền."],["学校でバレーボールを習っています。","Tôi đang học bóng chuyền ở trường."],["バレーボールは楽しいスポーツです。","Bóng chuyền là môn thể thao thú vị."]]},{"word":"気温","reading":"きおん","meaning":"Nhiệt độ","hanViet":"KHÍ ÔN","lesson":9,"ex":[["きょうの気温は低いです。","Nhiệt độ hôm nay thấp."],["気温が上がりました。","Nhiệt độ đã tăng."],["気温が下がりました。","Nhiệt độ đã giảm."],["夏の気温は高いです。","Nhiệt độ mùa hè cao."],["気温を見て、服を決めます。","Xem nhiệt độ rồi quyết định quần áo."]]},{"word":"降水量","reading":"こうすいりょう","meaning":"Lượng mưa","hanViet":"HÀNG THỦY LƯỢNG","lesson":9,"ex":[["きょうの降水量は多いです。","Lượng mưa hôm nay nhiều."],["この町の降水量は多いです。","Lượng mưa ở thị trấn này nhiều."],["降水量が少ない月があります。","Có những tháng lượng mưa ít."],["降水量を調べました。","Tôi đã tra lượng mưa."],["降水量が多いと、川の水が増えます。","Khi lượng mưa nhiều, nước sông tăng lên."]]},{"word":"月別","reading":"つきべつ","meaning":"Theo từng tháng","hanViet":"NGUYỆT BIỆT","lesson":9,"ex":[["降水量を月別に見ます。","Tôi xem lượng mưa theo từng tháng."],["気温を月別に調べました。","Tôi đã tra nhiệt độ theo từng tháng."],["月別の表を見てください。","Hãy xem bảng theo từng tháng."],["月別に降水量が違います。","Lượng mưa khác nhau theo từng tháng."],["月別の平均気温を調べました。","Tôi đã tra nhiệt độ trung bình theo từng tháng."]]},{"word":"平均","reading":"へいきん","meaning":"Trung bình","hanViet":"BÌNH QUÂN","lesson":9,"ex":[["平均気温を調べました。","Tôi đã tra nhiệt độ trung bình."],["平均して、毎日3時間勉強します。","Trung bình mỗi ngày tôi học 3 tiếng."],["クラスの平均点は80点です。","Điểm trung bình của lớp là 80 điểm."],["平均気温が上がっています。","Nhiệt độ trung bình đang tăng."],["平均を計算します。","Tôi tính số trung bình."]]},{"word":"予防注射","reading":"よぼうちゅうしゃ","meaning":"Tiêm phòng, tiêm vắc xin","hanViet":"DƯ PHÒNG CHÚ XẠ","lesson":9,"ex":[["子どもは予防注射を受けます。","Trẻ em tiêm phòng."],["病院で予防注射を受けました。","Tôi đã tiêm phòng ở bệnh viện."],["予防注射は怖いですか。","Tiêm phòng có đáng sợ không?"],["予防注射を受けてください。","Hãy đi tiêm phòng."],["予防注射の日が決まりました。","Ngày tiêm phòng đã được quyết định."]]},{"word":"国々","reading":"くにぐに","meaning":"Các nước","hanViet":"QUỐC","lesson":9,"ex":[["国々から留学生が来ます。","Du học sinh đến từ nhiều nước."],["国々の料理を食べました。","Tôi đã ăn món ăn của nhiều nước."],["国々で言葉が違います。","Ngôn ngữ khác nhau ở các nước."],["国々の文化を勉強します。","Tôi học văn hóa của nhiều nước."],["国々を旅行したいです。","Tôi muốn du lịch nhiều nước."]]},{"word":"都市","reading":"とし","meaning":"Thành phố, đô thị","hanViet":"ĐÔ THỊ","lesson":9,"ex":[["東京は大きな都市です。","Tokyo là thành phố lớn."],["都市に人が集まります。","Người ta tập trung về thành phố."],["都市は便利です。","Thành phố tiện lợi."],["都市と田舎では、生活が違います。","Cuộc sống ở thành phố và nông thôn khác nhau."],["この都市はきれいです。","Thành phố này đẹp."]]},{"word":"入国する","reading":"にゅうこくする","meaning":"Nhập cảnh","hanViet":"NHẬP QUỐC","lesson":9,"ex":[["日本に入国しました。","Tôi đã nhập cảnh vào Nhật Bản."],["入国するとき、パスポートを見せます。","Khi nhập cảnh, tôi trình hộ chiếu."],["入国した日に、友達に会いました。","Ngày nhập cảnh, tôi đã gặp bạn."],["入国してから、ホテルに行きました。","Sau khi nhập cảnh, tôi đã đến khách sạn."],["入国するのは初めてです。","Đây là lần đầu tôi nhập cảnh."]]},{"word":"資源","reading":"しげん","meaning":"Tài nguyên thiên nhiên","hanViet":"TƯ NGUYÊN","lesson":9,"ex":[["この国は資源が豊かです。","Đất nước này giàu tài nguyên."],["資源を大切に使います。","Chúng ta dùng tài nguyên một cách trân trọng."],["水は大切な資源です。","Nước là tài nguyên quan trọng."],["資源が少ない国があります。","Có những nước ít tài nguyên."],["資源について勉強します。","Tôi học về tài nguyên."]]},{"word":"とれる","reading":"とれる","meaning":"Thu hoạch được, lấy được, đạt được, chụp được","hanViet":"","lesson":9,"ex":[["この町では米がよくとれます。","Ở thị trấn này lúa thu hoạch tốt."],["この村では野菜がよくとれます。","Ở làng này rau thu hoạch tốt."],["テストでいい点がとれました。","Tôi đã đạt điểm tốt trong bài kiểm tra."],["魚がたくさんとれました。","Đã bắt được nhiều cá."],["この海では魚がよくとれます。","Ở biển này cá đánh bắt tốt."]]},{"word":"大雪","reading":"おおゆき","meaning":"Tuyết lớn, tuyết rơi dày","hanViet":"ĐẠI TUYẾT","lesson":9,"ex":[["きのうは大雪でした。","Hôm qua tuyết rơi dày."],["大雪で電車が止まりました。","Vì tuyết lớn mà tàu đã dừng."],["大雪の日は、家にいます。","Ngày tuyết lớn, tôi ở nhà."],["大雪で学校が休みになりました。","Vì tuyết lớn mà trường nghỉ học."],["大雪が降りました。","Tuyết lớn đã rơi."]]},{"word":"乾燥する","reading":"かんそうする","meaning":"Khô","hanViet":"KIỀN TÁO","lesson":9,"ex":[["冬は空気が乾燥します。","Mùa đông không khí khô."],["洗濯物が乾燥しました。","Quần áo giặt đã khô."],["雨の日は乾燥しません。","Ngày mưa thì không khô."],["乾燥するので、水を飲みます。","Vì khô nên tôi uống nước."],["喉が乾燥します。","Cổ họng bị khô."]]},{"word":"道路","reading":"どうろ","meaning":"Đường sá","hanViet":"ĐẠO LỘ","lesson":9,"ex":[["道路が広いです。","Đường rộng."],["道路を渡ります。","Tôi băng qua đường."],["道路を歩きます。","Tôi đi bộ trên đường."],["新しい道路ができました。","Đường mới đã được làm."],["道路で車が走っています。","Xe đang chạy trên đường."]]},{"word":"どんどん","reading":"どんどん","meaning":"Ngày càng","hanViet":"","lesson":9,"ex":[["日本語がどんどん上手になります。","Tiếng Nhật ngày càng giỏi."],["町がどんどん発展しています。","Thị trấn đang phát triển nhanh chóng."],["どんどん食べてください。","Hãy ăn nhiều vào."],["本をどんどん読みます。","Tôi đọc sách liên tục."],["どんどん寒くなります。","Trời ngày càng lạnh."]]},{"word":"最後","reading":"さいご","meaning":"Cuối cùng","hanViet":"TỐI HẬU","lesson":9,"ex":[["最後に、先生が話しました。","Cuối cùng, thầy giáo đã nói."],["試験の最後に、名前を書きます。","Cuối bài thi, tôi viết tên."],["最後の電車に乗りました。","Tôi đã lên chuyến tàu cuối cùng."],["最後まで頑張ります。","Tôi cố gắng đến cuối cùng."],["最後の問題が難しいです。","Câu hỏi cuối cùng khó."]]},{"word":"生きる","reading":"いきる","meaning":"Sống","hanViet":"SINH","lesson":9,"ex":[["人は水がなければ生きられません。","Con người không có nước thì không thể sống."],["魚は水の中で生きます。","Cá sống trong nước."],["長く生きたいです。","Tôi muốn sống lâu."],["彼は元気に生きています。","Anh ấy đang sống khỏe mạnh."],["生きることは大切です。","Sống là điều quan trọng."]]},{"word":"誕生","reading":"たんじょう","meaning":"Sự ra đời","hanViet":"ĐẢN SINH","lesson":9,"ex":[["子どもの誕生はうれしいです。","Sự ra đời của đứa trẻ thật vui mừng."],["新しい星の誕生を見ました。","Tôi đã thấy sự ra đời của ngôi sao mới."],["誕生日は誕生の日です。","Sinh nhật là ngày ra đời."],["この町は昔誕生しました。","Thị trấn này ra đời từ ngày xưa."],["誕生したばかりの会社です。","Là công ty mới ra đời."]]},{"word":"実現する","reading":"じつげんする","meaning":"Thực hiện","hanViet":"THỰC HIỆN","lesson":9,"ex":[["夢を実現しました。","Tôi đã thực hiện ước mơ."],["計画を実現します。","Tôi thực hiện kế hoạch."],["実現するのは難しいです。","Thực hiện được thật khó."],["彼の夢が実現しました。","Ước mơ của anh ấy đã thành hiện thực."],["実現するために、頑張ります。","Để thực hiện, tôi cố gắng."]]},{"word":"金メダル","reading":"きんメダル","meaning":"Huy chương vàng","hanViet":"KIM","lesson":9,"ex":[["彼は金メダルを取りました。","Anh ấy đã giành huy chương vàng."],["金メダルは金でできています。","Huy chương vàng được làm bằng vàng."],["金メダルを取ると、うれしいです。","Giành huy chương vàng thì vui."],["彼女の夢は金メダルです。","Ước mơ của cô ấy là huy chương vàng."],["金メダルは重いです。","Huy chương vàng nặng."]]},{"word":"金","reading":"きん","meaning":"Vàng","hanViet":"KIM","lesson":9,"ex":[["金は黄色いです。","Vàng có màu vàng."],["金の指輪を買いました。","Tôi đã mua nhẫn vàng."],["金でできています。","Được làm bằng vàng."],["金の時計があります。","Có đồng hồ vàng."],["金が好きです。","Tôi thích vàng."]]},{"word":"メダル","reading":"メダル","meaning":"Huy chương","hanViet":"","lesson":9,"ex":[["メダルを取りました。","Tôi đã giành huy chương."],["メダルをもらいました。","Tôi đã nhận được huy chương."],["メダルは丸いです。","Huy chương tròn."],["メダルを部屋に飾ります。","Tôi trưng huy chương trong phòng."],["メダルを取るために、練習します。","Để giành huy chương, tôi luyện tập."]]},{"word":"バスケットボール","reading":"バスケットボール","meaning":"Bóng rổ","hanViet":"","lesson":9,"ex":[["バスケットボールが好きです。","Tôi thích bóng rổ."],["友達とバスケットボールをします。","Tôi chơi bóng rổ với bạn."],["バスケットボールの試合を見ました。","Tôi đã xem trận đấu bóng rổ."],["学校でバスケットボールを習っています。","Tôi đang học bóng rổ ở trường."],["バスケットボールは楽しいスポーツです。","Bóng rổ là môn thể thao thú vị."]]},{"word":"選手","reading":"せんしゅ","meaning":"Cầu thủ, vận động viên","hanViet":"TUYỂN THỦ","lesson":9,"ex":[["彼は有名な選手です。","Anh ấy là vận động viên nổi tiếng."],["選手は毎日練習します。","Vận động viên luyện tập mỗi ngày."],["日本の選手が金メダルを取りました。","Vận động viên Nhật Bản đã giành huy chương vàng."],["選手になりたいです。","Tôi muốn trở thành vận động viên."],["選手を応援します。","Tôi cổ vũ cho vận động viên."]]},{"word":"シンプル","reading":"シンプル","meaning":"Đơn giản, giản dị","hanViet":"","lesson":9,"ex":[["シンプルな服が好きです。","Tôi thích quần áo đơn giản."],["シンプルなデザインがいいです。","Thiết kế đơn giản là tốt."],["この料理はシンプルです。","Món ăn này đơn giản."],["シンプルに考えてください。","Hãy nghĩ đơn giản."],["シンプルな答えを書いてください。","Hãy viết câu trả lời đơn giản."]]},{"word":"書き込み","reading":"かきこみ","meaning":"Viết vào, ghi vào, nhập vào","hanViet":"THƯ","lesson":9,"ex":[["書き込みをしてください。","Hãy viết vào."],["名前を書き込みました。","Tôi đã viết tên vào."],["紙に書き込みます。","Tôi viết vào giấy."],["書き込みが終わりました。","Việc viết đã xong."],["インターネットに書き込みました。","Tôi đã viết lên internet."]]},{"word":"検索","reading":"けんさく","meaning":"Tìm kiếm","hanViet":"KIỂM TÁC","lesson":9,"ex":[["インターネットで検索します。","Tôi tìm kiếm trên internet."],["言葉を検索しました。","Tôi đã tìm kiếm từ."],["検索して、答えを見つけました。","Tôi đã tìm kiếm và tìm ra đáp án."],["パソコンで検索します。","Tôi tìm kiếm bằng máy tính."],["検索は簡単です。","Tìm kiếm rất dễ."]]},{"word":"例文","reading":"れいぶん","meaning":"Câu ví dụ","hanViet":"LỆ VĂN","lesson":9,"ex":[["例文を読んでください。","Hãy đọc câu ví dụ."],["例文がわかりました。","Tôi đã hiểu câu ví dụ."],["例文を書きました。","Tôi đã viết câu ví dụ."],["例文を覚えます。","Tôi nhớ câu ví dụ."],["例文を見て、意味がわかりました。","Nhìn câu ví dụ, tôi đã hiểu nghĩa."]]},{"word":"ジャンプ機能","reading":"ジャンプきのう","meaning":"Chức năng tra từ vựng bằng cách cho phép chuyển nhanh (nhảy) giữa các loại từ điển tích hợp trong kim từ điển","hanViet":"KI NĂNG","lesson":9,"ex":[["この辞書にはジャンプ機能があります。","Từ điển này có chức năng nhảy."],["ジャンプ機能を使うと、言葉を速く調べます。","Dùng chức năng nhảy, tôi tra từ nhanh."],["ジャンプ機能は便利です。","Chức năng nhảy tiện lợi."],["ジャンプ機能で、意味がわかります。","Nhờ chức năng nhảy mà hiểu được nghĩa."],["ジャンプ機能を使ってください。","Hãy dùng chức năng nhảy."]]},{"word":"ジャンプ","reading":"ジャンプ","meaning":"Chuyển qua, nhảy qua","hanViet":"","lesson":9,"ex":[["ジャンプして、ページを変えます。","Nhảy qua, tôi đổi trang."],["ジャンプすると、速く調べられます。","Nhảy qua thì tra được nhanh."],["ジャンプするボタンを押します。","Tôi bấm nút nhảy."],["辞書でジャンプします。","Tôi nhảy qua trong từ điển."],["ジャンプして、別のページを見ます。","Nhảy qua, tôi xem trang khác."]]},{"word":"商品","reading":"しょうひん","meaning":"Hàng hóa","hanViet":"THƯƠNG PHẨM","lesson":9,"ex":[["この店の商品は安いです。","Hàng hóa của cửa hàng này rẻ."],["商品を買いました。","Tôi đã mua hàng hóa."],["新しい商品が入りました。","Hàng mới đã nhập về."],["商品を見てください。","Hãy xem hàng hóa."],["商品の値段が高いです。","Giá hàng hóa cao."]]},{"word":"～社","reading":"～しゃ","meaning":"Công ty ~","hanViet":"XÃ","lesson":9,"ex":[["父は田中社で働いています。","Bố tôi làm ở công ty Tanaka."],["山田社の本社は大阪にあります。","Trụ sở chính của công ty Yamada ở Osaka."],["あの社で働きたいです。","Tôi muốn làm ở công ty đó."],["新しい社ができました。","Công ty mới đã được thành lập."],["社の名前を教えてください。","Hãy cho tôi biết tên công ty."]]},{"word":"国語辞書","reading":"こくごじしょ","meaning":"Từ điển quốc ngữ tiếng Nhật","hanViet":"QUỐC NGỮ TỪ THƯ","lesson":9,"ex":[["国語辞書で言葉を調べます。","Tôi tra từ bằng từ điển quốc ngữ."],["国語辞書を買いました。","Tôi đã mua từ điển quốc ngữ."],["国語辞書は日本語の辞書です。","Từ điển quốc ngữ là từ điển tiếng Nhật."],["国語辞書で意味を調べました。","Tôi đã tra nghĩa bằng từ điển quốc ngữ."],["国語辞書を持っています。","Tôi có từ điển quốc ngữ."]]},{"word":"和英辞書","reading":"わえいじしょ","meaning":"Từ điển Nhật - Anh","hanViet":"HÒA ANH TỪ THƯ","lesson":9,"ex":[["和英辞書で日本語を調べます。","Tôi tra tiếng Nhật bằng từ điển Nhật-Anh."],["和英辞書を買いました。","Tôi đã mua từ điển Nhật-Anh."],["和英辞書は日本語と英語の辞書です。","Từ điển Nhật-Anh là từ điển tiếng Nhật và tiếng Anh."],["和英辞書で言葉の意味を調べました。","Tôi đã tra nghĩa của từ bằng từ điển Nhật-Anh."],["和英辞書を持っています。","Tôi có từ điển Nhật-Anh."]]},{"word":"載る","reading":"のる","meaning":"Được đăng, được đưa lên","hanViet":"TÁI","lesson":9,"ex":[["この本に例文が載っています。","Trong cuốn sách này có câu ví dụ."],["新聞に写真が載っています。","Trên báo có ảnh."],["雑誌に私の名前が載りました。","Tên tôi đã được đăng trên tạp chí."],["インターネットに情報が載っています。","Trên internet có thông tin."],["辞書に新しい言葉が載っています。","Trong từ điển có từ mới."]]},{"word":"シルバー","reading":"シルバー","meaning":"Bạc","hanViet":"","lesson":9,"ex":[["シルバーの指輪を買いました。","Tôi đã mua nhẫn bạc."],["シルバーの時計があります。","Có đồng hồ bạc."],["シルバーが好きです。","Tôi thích màu bạc."],["シルバーの車が走っています。","Xe màu bạc đang chạy."],["シルバーと金の指輪を買いました。","Tôi đã mua nhẫn bạc và nhẫn vàng."]]},{"word":"付け加える","reading":"つけくわえる","meaning":"Thêm","hanViet":"PHÓ GIA","lesson":9,"ex":[["もう一つ付け加えます。","Tôi thêm một cái nữa."],["塩を付け加えます。","Tôi thêm muối."],["言葉を付け加えます。","Tôi thêm từ."],["砂糖を付け加えます。","Tôi thêm đường."],["野菜を付け加えます。","Tôi thêm rau."]]},{"word":"編集する","reading":"へんしゅうする","meaning":"Biên tập","hanViet":"BIÊN TẬP","lesson":9,"ex":[["本を編集します。","Tôi biên tập sách."],["先生は文章を編集しました。","Thầy giáo đã biên tập bài viết."],["編集するのは難しいです。","Biên tập thật khó."],["雑誌を編集する仕事をしています。","Tôi đang làm công việc biên tập tạp chí."],["編集してから、本を出します。","Sau khi biên tập, tôi xuất bản sách."]]},{"word":"しっかり","reading":"しっかり","meaning":"Tin cậy được, ổn, chắc chắn","hanViet":"","lesson":9,"ex":[["しっかり勉強します。","Tôi học chăm chỉ."],["しっかり食べてください。","Hãy ăn thật no."],["しっかり寝てください。","Hãy ngủ thật ngon."],["しっかりと手を洗います。","Tôi rửa tay thật kỹ."],["しっかりした計画を作りました。","Tôi đã làm kế hoạch chắc chắn."]]},{"word":"留守番をする","reading":"るすばんをする","meaning":"Trông nhà","hanViet":"LƯU THỦ PHIÊN","lesson":9,"ex":[["きょうは留守番をします。","Hôm nay tôi trông nhà."],["母がいないので、留守番をします。","Vì mẹ không có nhà nên tôi trông nhà."],["留守番をするとき、本を読みます。","Khi trông nhà, tôi đọc sách."],["子どもが留守番をします。","Đứa trẻ trông nhà."],["留守番をするのは大変です。","Trông nhà thật vất vả."]]},{"word":"柄","reading":"がら","meaning":"Hoa văn, họa tiết","hanViet":"BÍNH","lesson":9,"ex":[["この服の柄が好きです。","Tôi thích họa tiết của bộ quần áo này."],["柄がきれいです。","Họa tiết đẹp."],["花の柄のシャツを買いました。","Tôi đã mua áo sơ mi họa tiết hoa."],["柄が違う服を買いました。","Tôi đã mua quần áo có họa tiết khác."],["この柄はシンプルです。","Họa tiết này đơn giản."]]},{"word":"共通語","reading":"きょうつうご","meaning":"Ngôn ngữ chung","hanViet":"CỘNG THÔNG NGỮ","lesson":9,"ex":[["共通語で話します。","Tôi nói bằng ngôn ngữ chung."],["日本語の共通語を勉強します。","Tôi học ngôn ngữ chung của tiếng Nhật."],["共通語と方言は違います。","Ngôn ngữ chung và phương ngữ khác nhau."],["共通語がわかります。","Tôi hiểu ngôn ngữ chung."],["共通語で話してください。","Hãy nói bằng ngôn ngữ chung."]]},{"word":"演奏","reading":"えんそう","meaning":"Biểu diễn âm nhạc, trình tấu","hanViet":"DIỄN TẤU","lesson":9,"ex":[["ピアノの演奏を聞きました。","Tôi đã nghe biểu diễn piano."],["演奏が上手です。","Biểu diễn giỏi."],["コンサートで演奏しました。","Tôi đã biểu diễn ở buổi hòa nhạc."],["彼の演奏はすばらしいです。","Phần biểu diễn của anh ấy tuyệt vời."],["演奏を聞いて、うれしくなりました。","Nghe biểu diễn, tôi trở nên vui vẻ."]]},{"word":"特許","reading":"とっきょ","meaning":"Bằng sáng chế","hanViet":"ĐẶC HỨA","lesson":9,"ex":[["新しい特許を取りました。","Tôi đã lấy bằng sáng chế mới."],["特許について勉強します。","Tôi học về bằng sáng chế."],["特許の数が多いです。","Số bằng sáng chế nhiều."],["特許を取ると、会社が守られます。","Khi lấy bằng sáng chế, công ty được bảo vệ."],["特許の話を聞きました。","Tôi đã nghe chuyện về bằng sáng chế."]]},{"word":"倒産","reading":"とうさん","meaning":"Phá sản","hanViet":"ĐẢO SẢN","lesson":9,"ex":[["会社が倒産しました。","Công ty đã phá sản."],["倒産する会社が多いです。","Có nhiều công ty phá sản."],["倒産しないように、頑張ります。","Tôi cố gắng để không phá sản."],["倒産のニュースを聞きました。","Tôi đã nghe tin phá sản."],["倒産すると、社員が困ります。","Khi phá sản, nhân viên sẽ khó khăn."]]},{"word":"大金持ち","reading":"おおがねもち","meaning":"Triệu phú","hanViet":"ĐẠI KIM TRÌ","lesson":9,"ex":[["彼は大金持ちです。","Anh ấy là triệu phú."],["大金持ちになりたいです。","Tôi muốn trở thành triệu phú."],["大金持ちの生活はどうですか。","Cuộc sống của triệu phú như thế nào?"],["大金持ちでも、みんな幸せではありません。","Dù là triệu phú, không phải ai cũng hạnh phúc."],["大金持ちの家は大きいです。","Nhà của triệu phú lớn."]]},{"word":"誇る","reading":"ほこる","meaning":"Tự hào","hanViet":"KHOA","lesson":9,"ex":[["彼は自分の国を誇ります。","Anh ấy tự hào về đất nước mình."],["この町は美しい海を誇ります。","Thị trấn này tự hào về biển đẹp."],["日本は桜を誇ります。","Nhật Bản tự hào về hoa anh đào."],["彼は息子を誇ります。","Anh ấy tự hào về con trai."],["この学校は歴史を誇ります。","Trường này tự hào về lịch sử của mình."]]},{"word":"表れる","reading":"あらわれる","meaning":"Biểu hiện, lộ ra, xuất hiện","hanViet":"BIỂU","lesson":9,"ex":[["空に虹が表れました。","Cầu vồng đã xuất hiện trên bầu trời."],["勉強の結果が表れました。","Kết quả học tập đã hiện ra."],["問題が表れました。","Vấn đề đã xuất hiện."],["彼の気持ちが顔に表れています。","Cảm xúc của anh ấy hiện lên mặt."],["雨の後に、太陽が表れました。","Sau cơn mưa, mặt trời đã xuất hiện."]]},{"word":"今では","reading":"いまでは","meaning":"Ngày nay, bây giờ","hanViet":"KIM","lesson":9,"ex":[["今では、日本語で手紙を書くことができます。","Ngày nay, tôi đã có thể viết thư bằng tiếng Nhật."],["今では、毎日電車で会社へ行きます。","Ngày nay, hằng ngày tôi đi làm bằng tàu điện."],["今では、みんながパソコンを使います。","Ngày nay, ai cũng dùng máy tính."],["今では、この町はとてもにぎやかです。","Ngày nay, thị trấn này rất nhộn nhịp."],["今では、子どももパソコンで勉強します。","Ngày nay, cả trẻ con cũng học bằng máy tính."]]},{"word":"ツナミ","reading":"ツナミ","meaning":"Sóng thần","hanViet":"","lesson":9,"ex":[["地震のあとで、ツナミが来ました。","Sau trận động đất, sóng thần đã đến."],["ツナミのニュースをテレビで見ました。","Tôi đã xem tin tức về sóng thần trên ti vi."],["ツナミから逃げてください。","Hãy chạy trốn khỏi sóng thần."],["ツナミで家が壊れました。","Nhà đã bị phá hủy vì sóng thần."],["海の近くに住んでいますから、ツナミが怖いです。","Vì sống gần biển nên tôi sợ sóng thần."]]},{"word":"影響","reading":"えいきょう","meaning":"Sự ảnh hưởng","hanViet":"ẢNH HƯỞNG","lesson":9,"ex":[["天気は仕事に影響があります。","Thời tiết có ảnh hưởng đến công việc."],["日本語の勉強は仕事にいい影響があります。","Việc học tiếng Nhật có ảnh hưởng tốt đến công việc."],["地震は電車に大きな影響がありました。","Động đất đã ảnh hưởng lớn đến tàu điện."],["私は先生の話から影響を受けました。","Tôi đã chịu ảnh hưởng từ câu chuyện của thầy."],["このニュースは国に大きな影響があります。","Tin tức này có ảnh hưởng lớn đến đất nước."]]},{"word":"有名人","reading":"ゆうめいじん","meaning":"Người nổi tiếng","hanViet":"HỮU DANH NHÂN","lesson":9,"ex":[["田中さんはテレビに出る有名人です。","Anh Tanaka là người nổi tiếng xuất hiện trên ti vi."],["町で有名人に会いました。","Tôi đã gặp người nổi tiếng ở thị trấn."],["有名人のサインをもらいました。","Tôi đã xin được chữ ký của người nổi tiếng."],["山田さんは有名人になりました。","Anh Yamada đã trở thành người nổi tiếng."],["有名人でも、普通の生活をします。","Dù là người nổi tiếng, họ vẫn sống cuộc sống bình thường."]]},{"word":"録音する","reading":"ろくおんする","meaning":"Ghi âm","hanViet":"LỤC ÂM","lesson":9,"ex":[["先生の声を録音しました。","Tôi đã ghi âm giọng của thầy."],["授業を録音してもいいですか。","Tôi có thể ghi âm buổi học không?"],["録音を聞いて、日本語を勉強します。","Tôi nghe bản ghi âm và học tiếng Nhật."],["電話で話を録音することはできません。","Không thể ghi âm cuộc nói chuyện qua điện thoại."],["歌を録音して、友達に聞かせました。","Tôi đã ghi âm bài hát và cho bạn nghe."]]},{"word":"ヒント","reading":"ヒント","meaning":"Gợi ý","hanViet":"","lesson":9,"ex":[["ヒントをください。","Hãy cho tôi một gợi ý."],["先生がヒントをくれました。","Thầy đã cho tôi gợi ý."],["このヒントが役に立ちました。","Gợi ý này đã có ích."],["ヒントがないと、問題が分かりません。","Nếu không có gợi ý thì không hiểu được bài toán."],["ヒントを見て、答えが分かりました。","Nhìn gợi ý, tôi đã hiểu ra đáp án."]]},{"word":"貸し出す","reading":"かしだす","meaning":"Cho mượn","hanViet":"THẢI XUẤT","lesson":9,"ex":[["図書館は本を貸し出します。","Thư viện cho mượn sách."],["この店はDVDを貸し出しています。","Cửa hàng này đang cho thuê đĩa DVD."],["図書館で本を貸し出してもらいました。","Tôi đã mượn sách ở thư viện."],["貸し出す本は三冊までです。","Sách được mượn tối đa 3 cuốn."],["新しい本はまだ貸し出していません。","Sách mới vẫn chưa cho mượn."]]},{"word":"ところが","reading":"ところが","meaning":"Tuy nhiên","hanViet":"","lesson":9,"ex":[["山田さんは来ると言いました。ところが、来ませんでした。","Anh Yamada nói sẽ đến. Tuy nhiên, anh ấy đã không đến."],["天気はいいはずでした。ところが、雨が降りました。","Đáng lẽ trời đẹp. Tuy nhiên, trời đã mưa."],["田中さんは元気でした。ところが、急に病気になりました。","Anh Tanaka vẫn khỏe. Tuy nhiên, anh ấy đột nhiên bị ốm."],["電車は時間通りに来るはずでした。ところが、三十分遅れました。","Tàu đáng lẽ đến đúng giờ. Tuy nhiên, nó đã trễ 30 phút."],["試験は易しいと思いました。ところが、とても難しかったです。","Tôi tưởng kỳ thi dễ. Tuy nhiên, nó rất khó."]]},{"word":"競争","reading":"きょうそう","meaning":"Cạnh tranh","hanViet":"CẠNH TRANH","lesson":9,"ex":[["会社と会社が競争をします。","Các công ty cạnh tranh với nhau."],["競争に勝ちました。","Tôi đã thắng trong cuộc cạnh tranh."],["この町では、店の競争が強いです。","Ở thị trấn này, sự cạnh tranh giữa các cửa hàng rất mạnh."],["競争が好きな人もいます。","Cũng có người thích cạnh tranh."],["日本の会社は世界で競争をしています。","Các công ty Nhật đang cạnh tranh trên thế giới."]]},{"word":"性別","reading":"せいべつ","meaning":"Giới tính","hanViet":"TÍNH BIỆT","lesson":9,"ex":[["性別は男性ですか、女性ですか。","Giới tính là nam hay nữ?"],["性別に関係なく、みんなが参加できます。","Bất kể giới tính, ai cũng có thể tham gia."],["この紙に性別を書いてください。","Hãy viết giới tính vào tờ giấy này."],["性別を聞いてもいいですか。","Tôi có thể hỏi giới tính không?"],["性別と年齢を教えてください。","Hãy cho tôi biết giới tính và tuổi."]]},{"word":"地域","reading":"ちいき","meaning":"Khu vực","hanViet":"ĐỊA VỰC","lesson":9,"ex":[["この地域は静かです。","Khu vực này yên tĩnh."],["地域の人が祭りに参加します。","Người dân trong khu vực tham gia lễ hội."],["地域によって、天気が違います。","Tùy theo khu vực mà thời tiết khác nhau."],["この地域には、いい病院があります。","Khu vực này có bệnh viện tốt."],["地域の図書館で本を借ります。","Tôi mượn sách ở thư viện khu vực."]]},{"word":"関係なく","reading":"かんけいなく","meaning":"Bất kể","hanViet":"QUAN HỆ","lesson":9,"ex":[["年齢に関係なく、みんなが参加できます。","Bất kể tuổi tác, ai cũng có thể tham gia."],["天気に関係なく、試合をします。","Bất kể thời tiết, trận đấu vẫn diễn ra."],["性別に関係なく、仕事ができます。","Bất kể giới tính, đều có thể làm việc."],["国に関係なく、友達になりましょう。","Bất kể quốc gia, hãy kết bạn nhé."],["時間に関係なく、電話をしてください。","Bất kể lúc nào, hãy gọi điện cho tôi."]]},{"word":"娯楽","reading":"ごらく","meaning":"Hình thức giải trí","hanViet":"NGU LẠC","lesson":9,"ex":[["映画はいい娯楽です。","Phim ảnh là hình thức giải trí tốt."],["この町には娯楽が少ないです。","Thị trấn này ít hình thức giải trí."],["娯楽の時間が必要です。","Cần có thời gian giải trí."],["昔の人の娯楽は歌でした。","Hình thức giải trí của người xưa là ca hát."],["スポーツは楽しい娯楽です。","Thể thao là hình thức giải trí vui vẻ."]]},{"word":"年寄り","reading":"としより","meaning":"Người lớn tuổi, cao niên","hanViet":"NIÊN KÍ","lesson":9,"ex":[["年寄りを助けましょう。","Hãy giúp đỡ người lớn tuổi."],["年寄りの話を聞くのが好きです。","Tôi thích nghe chuyện của người lớn tuổi."],["この地域には年寄りが多いです。","Khu vực này có nhiều người lớn tuổi."],["年寄りも元気に運動をします。","Người lớn tuổi cũng vận động khỏe mạnh."],["年寄りのために、病院があります。","Vì người lớn tuổi nên có bệnh viện."]]},{"word":"仲間","reading":"なかま","meaning":"Bạn bè","hanViet":"TRỌNG GIAN","lesson":9,"ex":[["仕事の仲間といっしょに昼ごはんを食べます。","Tôi ăn trưa cùng đồng nghiệp."],["仲間が増えました。","Bạn bè đã tăng lên."],["いい仲間に会いました。","Tôi đã gặp những người bạn tốt."],["仲間といっしょに旅行に行きました。","Tôi đã đi du lịch cùng bạn bè."],["田中さんは私の大切な仲間です。","Anh Tanaka là người bạn quan trọng của tôi."]]},{"word":"心","reading":"こころ","meaning":"Tâm hồn, trái tim","hanViet":"TÂM","lesson":9,"ex":[["心からありがとうと言いました。","Tôi đã nói cảm ơn từ tận đáy lòng."],["友達の心が分かりません。","Tôi không hiểu được lòng bạn."],["心が温かくなりました。","Lòng tôi đã trở nên ấm áp."],["心の中に夢があります。","Trong tim tôi có ước mơ."],["音楽は心を元気にします。","Âm nhạc làm cho tâm hồn phấn chấn."]]},{"word":"治す","reading":"なおす","meaning":"Chữa","hanViet":"TRÌ","lesson":9,"ex":[["医者が病気を治します。","Bác sĩ chữa bệnh."],["かぜを治すために、薬を飲みます。","Để chữa cảm, tôi uống thuốc."],["けがを治しました。","Tôi đã chữa khỏi vết thương."],["この薬は病気を治します。","Thuốc này chữa được bệnh."],["病気を治すまで、休んでください。","Hãy nghỉ ngơi cho đến khi chữa khỏi bệnh."]]},{"word":"単なる","reading":"たんなる","meaning":"Đơn thuần, đơn giản","hanViet":"ĐƠN","lesson":9,"ex":[["田中さんは単なる友達です。","Anh Tanaka chỉ là bạn đơn thuần."],["それは単なる間違いでした。","Đó chỉ là sai lầm đơn thuần."],["単なるうわさですから、信じないでください。","Chỉ là tin đồn đơn thuần nên đừng tin."],["それは単なる夢でした。","Đó chỉ là giấc mơ đơn thuần."],["単なる話です。","Chỉ là câu chuyện đơn thuần."]]},{"word":"きっかけ","reading":"きっかけ","meaning":"Lý do, cớ","hanViet":"","lesson":9,"ex":[["映画がきっかけで、日本語を勉強しました。","Nhờ bộ phim mà tôi đã học tiếng Nhật."],["友達がきっかけで、スポーツを始めました。","Nhờ bạn mà tôi bắt đầu chơi thể thao."],["この本がきっかけでした。","Cuốn sách này là cơ duyên."],["きっかけは何でしたか。","Cơ duyên là gì?"],["旅行がきっかけで、新しい友達ができました。","Nhờ chuyến du lịch mà tôi đã có bạn mới."]]},{"word":"交流協会","reading":"こうりゅうきょうかい","meaning":"Hiệp hội giao lưu","hanViet":"GIAO LƯU HIỆP HỘI","lesson":9,"ex":[["交流協会に参加しました。","Tôi đã tham gia hiệp hội giao lưu."],["交流協会で日本語を勉強します。","Tôi học tiếng Nhật ở hiệp hội giao lưu."],["交流協会の人が親切です。","Người của hiệp hội giao lưu rất tốt bụng."],["交流協会の活動に参加します。","Tôi tham gia hoạt động của hiệp hội giao lưu."],["交流協会の会員になりました。","Tôi đã trở thành hội viên của hiệp hội giao lưu."]]},{"word":"広報誌","reading":"こうほうし","meaning":"Bản tin, tạp chí tuyên truyền","hanViet":"QUẢNG BÁO CHÍ","lesson":9,"ex":[["町の広報誌を読みました。","Tôi đã đọc bản tin của thị trấn."],["広報誌に祭りのことが書いてあります。","Trong bản tin có viết về lễ hội."],["毎月、広報誌が家に届きます。","Hằng tháng, bản tin được gửi đến nhà."],["広報誌で新しい店を知りました。","Nhờ bản tin mà tôi biết cửa hàng mới."],["広報誌の写真を見ました。","Tôi đã xem ảnh trong bản tin."]]},{"word":"暮らし","reading":"くらし","meaning":"Cuộc sống","hanViet":"MỘ","lesson":9,"ex":[["日本の暮らしは楽しいです。","Cuộc sống ở Nhật rất vui."],["田舎の暮らしが好きです。","Tôi thích cuộc sống ở nông thôn."],["毎日の暮らしに日本語が必要です。","Cuộc sống hằng ngày cần tiếng Nhật."],["新しい町で暮らしが始まりました。","Cuộc sống mới đã bắt đầu ở thị trấn mới."],["暮らしが便利になりました。","Cuộc sống đã trở nên tiện lợi."]]},{"word":"役立つ","reading":"やくだつ","meaning":"Hữu ích, có ích","hanViet":"DỊCH LẬP","lesson":9,"ex":[["日本語は仕事に役立ちます。","Tiếng Nhật có ích cho công việc."],["この本は勉強に役立ちます。","Cuốn sách này có ích cho việc học."],["このヒントが役立ちました。","Gợi ý này đã có ích."],["パソコンは生活に役立ちます。","Máy tính có ích cho cuộc sống."],["役立つ情報を教えてください。","Hãy cho tôi thông tin hữu ích."]]},{"word":"参加者","reading":"さんかしゃ","meaning":"Người tham gia","hanViet":"THAM GIA GIẢ","lesson":9,"ex":[["参加者は五十人です。","Số người tham gia là 50 người."],["参加者の名前を書いてください。","Hãy viết tên người tham gia."],["参加者が増えました。","Số người tham gia đã tăng."],["参加者みんなが楽しかったです。","Tất cả người tham gia đều vui vẻ."],["参加者を集めました。","Tôi đã tập hợp người tham gia."]]},{"word":"ページ","reading":"ページ","meaning":"trang","hanViet":"","lesson":9,"ex":[["本のページを開きました。","Tôi đã mở trang sách."],["このページを読んでください。","Hãy đọc trang này."],["十ページまで読みました。","Tôi đã đọc đến trang 10."],["最後のページに答えがあります。","Ở trang cuối có đáp án."],["この本は二百ページあります。","Cuốn sách này có 200 trang."]]},{"word":"もうける","reading":"もうける","meaning":"Kiếm tiền","hanViet":"","lesson":10,"ex":[["会社がお金をもうけました。","Công ty đã kiếm được tiền."],["店でもうけるのは難しいです。","Kiếm tiền bằng cửa hàng thì khó."],["たくさんもうけたいです。","Tôi muốn kiếm thật nhiều tiền."],["この仕事でもうけることができます。","Công việc này có thể kiếm tiền."],["もうけたお金で旅行に行きます。","Tôi đi du lịch bằng số tiền đã kiếm được."]]},{"word":"見かける","reading":"みかける","meaning":"Nhìn thấy, bắt gặp","hanViet":"KIẾN","lesson":10,"ex":[["駅で友達を見かけました。","Tôi đã bắt gặp bạn ở ga."],["町で有名人を見かけました。","Tôi đã nhìn thấy người nổi tiếng ở thị trấn."],["久しぶりに先生を見かけました。","Lâu rồi tôi mới gặp lại thầy."],["道で犬を見かけました。","Tôi đã thấy con chó trên đường."],["朝、公園で鳥を見かけました。","Buổi sáng, tôi đã thấy chim ở công viên."]]},{"word":"否定する","reading":"ひていする","meaning":"Phủ định","hanViet":"PHỦ ĐỊNH","lesson":10,"ex":[["先生は私の意見を否定しました。","Thầy đã phủ định ý kiến của tôi."],["全部を否定しないでください。","Đừng phủ định tất cả."],["山田さんは話を否定しました。","Anh Yamada đã phủ định câu chuyện."],["否定する前に、よく聞いてください。","Trước khi phủ định, hãy nghe kỹ."],["私はその意見を否定しません。","Tôi không phủ định ý kiến đó."]]},{"word":"タイムマシン","reading":"タイムマシン","meaning":"Cỗ máy thời gian","hanViet":"","lesson":10,"ex":[["タイムマシンに乗りたいです。","Tôi muốn đi cỗ máy thời gian."],["タイムマシンがあれば、未来に行きます。","Nếu có cỗ máy thời gian, tôi sẽ đến tương lai."],["映画にタイムマシンが出ました。","Trong phim đã xuất hiện cỗ máy thời gian."],["タイムマシンは夢です。","Cỗ máy thời gian là giấc mơ."],["タイムマシンで過去に戻りたいです。","Tôi muốn quay về quá khứ bằng cỗ máy thời gian."]]},{"word":"宝くじ","reading":"たからくじ","meaning":"Vé số","hanViet":"BẢO","lesson":10,"ex":[["宝くじを買いました。","Tôi đã mua vé số."],["宝くじが当たったら、旅行に行きます。","Nếu trúng vé số, tôi sẽ đi du lịch."],["毎週、宝くじを買います。","Hằng tuần tôi mua vé số."],["宝くじを買って、一等が当たりました。","Tôi đã mua vé số và trúng giải nhất."],["宝くじは夢を買うことです。","Vé số là mua giấc mơ."]]},{"word":"当たる","reading":"あたる","meaning":"Trúng vé số","hanViet":"ĐƯƠNG","lesson":10,"ex":[["宝くじが当たりました。","Vé số đã trúng."],["抽選に当たりました。","Tôi đã trúng rút thăm."],["一等が当たったら、車を買います。","Nếu trúng giải nhất, tôi sẽ mua xe."],["当たるかどうか分かりません。","Không biết có trúng hay không."],["当たると思いますか。","Bạn nghĩ sẽ trúng chứ?"]]},{"word":"ワールドカップ","reading":"ワールドカップ","meaning":"World Cup","hanViet":"","lesson":10,"ex":[["ワールドカップの試合を見ました。","Tôi đã xem trận đấu World Cup."],["日本はワールドカップに出ました。","Nhật Bản đã tham dự World Cup."],["ワールドカップは有名なサッカーの大会です。","World Cup là giải đấu bóng đá nổi tiếng."],["ワールドカップのとき、みんなでテレビを見ます。","Khi có World Cup, mọi người cùng xem ti vi."],["ワールドカップの試合は楽しいです。","Trận đấu World Cup rất thú vị."]]},{"word":"カエル","reading":"カエル","meaning":"Con ếch","hanViet":"","lesson":10,"ex":[["池にカエルがいます。","Trong ao có ếch."],["雨の日にカエルを見ました。","Tôi đã thấy ếch vào ngày mưa."],["カエルは緑です。","Ếch có màu xanh lá."],["カエルが池で泳ぎます。","Ếch bơi trong ao."],["子どもはカエルが好きです。","Trẻ con thích ếch."]]},{"word":"計画","reading":"けいかく","meaning":"Kế hoạch","hanViet":"KẾ HỌA","lesson":10,"ex":[["旅行の計画を作りました。","Tôi đã lập kế hoạch du lịch."],["計画がありますか。","Bạn có kế hoạch không?"],["計画を考えました。","Tôi đã nghĩ ra kế hoạch."],["明日の計画を教えてください。","Hãy cho tôi biết kế hoạch ngày mai."],["計画を守ることが大切です。","Việc giữ đúng kế hoạch rất quan trọng."]]},{"word":"実際","reading":"じっさい","meaning":"Thực tế","hanViet":"THỰC TẾ","lesson":10,"ex":[["実際はとても難しいです。","Thực tế thì rất khó."],["実際は、あまり難しくありませんでした。","Thực tế thì không khó lắm."],["実際に行ってみると、楽しかったです。","Khi thử đi thực tế thì rất vui."],["実際は思ったより易しかったです。","Thực tế thì dễ hơn tôi nghĩ."],["実際に見てください。","Hãy xem thực tế đi."]]},{"word":"めったに","reading":"めったに","meaning":"Hiếm khi","hanViet":"","lesson":10,"ex":[["めったに映画を見ません。","Tôi hiếm khi xem phim."],["めったに雨が降りません。","Trời hiếm khi mưa."],["めったに会いません。","Hiếm khi gặp nhau."],["この町では、めったに雪が降りません。","Ở thị trấn này hiếm khi có tuyết."],["めったに遅れません。","Tôi hiếm khi đến muộn."]]},{"word":"通じる","reading":"つうじる","meaning":"Thông, được nối điện thoại","hanViet":"THÔNG","lesson":10,"ex":[["電話が通じません。","Điện thoại không liên lạc được."],["日本語が通じますか。","Tiếng Nhật có được hiểu không?"],["気持ちが通じました。","Tình cảm đã thấu hiểu nhau."],["電話が通じたら、教えてください。","Nếu điện thoại liên lạc được, hãy cho tôi biết."],["外国で日本語は通じません。","Ở nước ngoài, tiếng Nhật không được hiểu."]]},{"word":"時間通りに","reading":"じかんどおりに","meaning":"Đúng giờ","hanViet":"THỜI GIAN THÔNG","lesson":10,"ex":[["電車は時間通りに来ました。","Tàu đã đến đúng giờ."],["授業は時間通りに始まりました。","Buổi học đã bắt đầu đúng giờ."],["時間通りに着きました。","Tôi đã đến đúng giờ."],["時間通りに来てください。","Hãy đến đúng giờ."],["友達は時間通りに来ませんでした。","Bạn tôi đã không đến đúng giờ."]]},{"word":"かかる","reading":"かかる","meaning":"Động cơ khởi động","hanViet":"","lesson":10,"ex":[["車のエンジンがかかりません。","Động cơ xe không khởi động được."],["朝、エンジンがかかりました。","Buổi sáng, động cơ đã khởi động."],["寒い日はエンジンがかかりにくいです。","Vào ngày lạnh, động cơ khó khởi động."],["エンジンがかからないので、会社に遅れました。","Vì động cơ không khởi động nên tôi đã muộn làm."],["エンジンがかかったら、教えてください。","Nếu động cơ khởi động, hãy cho tôi biết."]]},{"word":"鬼","reading":"おに","meaning":"Con quỷ","hanViet":"QUỶ","lesson":10,"ex":[["昔話に鬼が出ます。","Trong truyện cổ tích có quỷ xuất hiện."],["鬼は怖いです。","Quỷ đáng sợ."],["子どもは鬼の話が好きです。","Trẻ con thích chuyện về quỷ."],["鬼のような声が聞こえました。","Tôi nghe thấy giọng nói như quỷ."],["映画の鬼は強いです。","Con quỷ trong phim rất mạnh."]]},{"word":"怒る","reading":"おこる","meaning":"Tức giận, cáu","hanViet":"NỘ","lesson":10,"ex":[["先生が怒りました。","Thầy đã tức giận."],["母は怒っています。","Mẹ đang tức giận."],["怒らないでください。","Đừng tức giận."],["遅れたので、先生に怒られました。","Vì đến muộn nên tôi đã bị thầy mắng."],["友達を怒らせました。","Tôi đã làm bạn tức giận."]]},{"word":"CO2","reading":"シーオーツー","meaning":"CO2","hanViet":"","lesson":10,"ex":[["車はCO2を出します。","Xe thải ra CO2."],["CO2が増えると、地球が暖かくなります。","Khi CO2 tăng, Trái Đất trở nên ấm hơn."],["CO2が減ることが大切です。","Việc CO2 giảm là quan trọng."],["地球のCO2が増えています。","CO2 của Trái Đất đang tăng."],["CO2について勉強しました。","Tôi đã học về CO2."]]},{"word":"抽選","reading":"ちゅうせん","meaning":"Rút thăm, xổ số","hanViet":"TRỪU TUYỂN","lesson":10,"ex":[["抽選で車が当たりました。","Tôi đã trúng xe trong rút thăm."],["抽選をします。","Tôi sẽ rút thăm."],["抽選の結果が分かりました。","Tôi đã biết kết quả rút thăm."],["抽選に当たるかどうか分かりません。","Không biết có trúng rút thăm hay không."],["店で抽選がありました。","Ở cửa hàng đã có rút thăm."]]},{"word":"一等","reading":"いっとう","meaning":"Giải nhất","hanViet":"NHẤT ĐẲNG","lesson":10,"ex":[["宝くじで一等が当たりました。","Tôi đã trúng giải nhất vé số."],["一等の賞金は多いです。","Tiền thưởng giải nhất rất nhiều."],["一等に当たったら、家を買います。","Nếu trúng giải nhất, tôi sẽ mua nhà."],["一等は一人だけです。","Giải nhất chỉ có một người."],["山田さんは一等を取りました。","Anh Yamada đã đoạt giải nhất."]]},{"word":"投票","reading":"とうひょう","meaning":"Bỏ phiếu, bầu","hanViet":"ĐẦU PHIẾU","lesson":10,"ex":[["投票をしました。","Tôi đã bỏ phiếu."],["みんなが投票をします。","Mọi người đều bỏ phiếu."],["投票に行きました。","Tôi đã đi bỏ phiếu."],["投票の結果が分かりました。","Tôi đã biết kết quả bỏ phiếu."],["投票をすることが大切です。","Việc bỏ phiếu rất quan trọng."]]},{"word":"互いに","reading":"たがいに","meaning":"Lẫn nhau","hanViet":"HỖ","lesson":10,"ex":[["互いに助けましょう。","Hãy giúp đỡ lẫn nhau."],["互いに日本語を教えます。","Chúng tôi dạy tiếng Nhật cho nhau."],["友達と互いに手紙を書きます。","Tôi và bạn viết thư cho nhau."],["互いに意見を聞きます。","Chúng tôi lắng nghe ý kiến của nhau."],["互いに頑張りましょう。","Hãy cùng cố gắng nhé."]]},{"word":"聞き返す","reading":"ききかえす","meaning":"Hỏi lại, yêu cầu nói lại","hanViet":"VĂN PHẢN","lesson":10,"ex":[["分かりませんでしたから、聞き返しました。","Vì không hiểu nên tôi đã hỏi lại."],["電話で聞き返しました。","Tôi đã hỏi lại qua điện thoại."],["聞き返すことができますか。","Tôi có thể hỏi lại không?"],["聞き返すのは大切です。","Việc hỏi lại rất quan trọng."],["聞き返したら、先生が答えました。","Khi tôi hỏi lại, thầy đã trả lời."]]},{"word":"てっきり","reading":"てっきり","meaning":"Chắc chắn, đinh ninh","hanViet":"","lesson":10,"ex":[["てっきり明日だと思いました。","Tôi đinh ninh là ngày mai."],["てっきり雨だと思いましたが、雨は降りませんでした。","Tôi đinh ninh trời mưa, nhưng trời đã không mưa."],["てっきり田中さんだと思いました。","Tôi đinh ninh đó là anh Tanaka."],["てっきり試験だと思いました。","Tôi đinh ninh là kỳ thi."],["てっきり来ると思いましたが、来ませんでした。","Tôi đinh ninh anh ấy sẽ đến, nhưng anh ấy đã không đến."]]},{"word":"倉庫","reading":"そうこ","meaning":"Kho chứa đồ, nhà kho","hanViet":"THƯƠNG KHỐ","lesson":10,"ex":[["倉庫に荷物を置きました。","Tôi đã để hành lý trong kho."],["倉庫は大きいです。","Nhà kho rất lớn."],["会社の倉庫に本があります。","Trong kho của công ty có sách."],["倉庫を掃除しました。","Tôi đã dọn dẹp nhà kho."],["倉庫の中に古い机があります。","Trong kho có bàn cũ."]]},{"word":"プリンター","reading":"プリンター","meaning":"Máy in","hanViet":"","lesson":10,"ex":[["プリンターを使います。","Tôi dùng máy in."],["プリンターが壊れました。","Máy in đã hỏng."],["新しいプリンターを買いました。","Tôi đã mua máy in mới."],["プリンターに紙を入れました。","Tôi đã cho giấy vào máy in."],["プリンターのマニュアルを読みました。","Tôi đã đọc sách hướng dẫn của máy in."]]},{"word":"マニュアル","reading":"マニュアル","meaning":"Sách hướng dẫn","hanViet":"","lesson":10,"ex":[["マニュアルを読みました。","Tôi đã đọc sách hướng dẫn."],["マニュアルを見てください。","Hãy xem sách hướng dẫn."],["車のマニュアルに書いてあります。","Trong sách hướng dẫn xe có viết."],["マニュアルがないと、分かりません。","Nếu không có sách hướng dẫn thì không hiểu."],["新しいパソコンのマニュアルです。","Đây là sách hướng dẫn của máy tính mới."]]},{"word":"親しい","reading":"したしい","meaning":"Thân thiết, gần gũi","hanViet":"THÂN","lesson":10,"ex":[["田中さんは親しい友達です。","Anh Tanaka là bạn thân."],["親しい人と話します。","Tôi nói chuyện với người thân thiết."],["山田さんと親しくなりました。","Tôi đã trở nên thân thiết với anh Yamada."],["親しい友達が増えました。","Bạn thân đã tăng lên."],["親しい人に手紙を書きました。","Tôi đã viết thư cho người thân thiết."]]},{"word":"驚く","reading":"おどろく","meaning":"Ngạc nhiên","hanViet":"KINH","lesson":10,"ex":[["ニュースに驚きました。","Tôi đã ngạc nhiên trước tin tức."],["値段に驚きました。","Tôi đã ngạc nhiên về giá cả."],["友達の話に驚きました。","Tôi đã ngạc nhiên trước câu chuyện của bạn."],["驚くことが多いです。","Có nhiều điều ngạc nhiên."],["驚かないでください。","Đừng ngạc nhiên."]]},{"word":"～代","reading":"～だい","meaning":"Tuổi ~; độ tuổi ~","hanViet":"ĐẠI","lesson":10,"ex":[["父は六十代です。","Bố tôi ở độ tuổi 60."],["田中さんは三十代です。","Anh Tanaka ở độ tuổi 30."],["二十代の人は元気です。","Người ở độ tuổi 20 rất khỏe mạnh."],["四十代の友達がいます。","Tôi có bạn ở độ tuổi 40."],["五十代になっても、勉強を続けます。","Dù đã ở độ tuổi 50, tôi vẫn tiếp tục học."]]},{"word":"誤解","reading":"ごかい","meaning":"Sự hiểu lầm","hanViet":"NGỘ GIẢI","lesson":10,"ex":[["それは誤解です。","Đó là hiểu lầm."],["誤解をしました。","Tôi đã hiểu lầm."],["誤解しないでください。","Đừng hiểu lầm."],["誤解がないように話します。","Tôi nói sao cho không có hiểu lầm."],["友達と誤解がありました。","Tôi và bạn đã có hiểu lầm."]]},{"word":"記憶","reading":"きおく","meaning":"Ký ức, trí nhớ","hanViet":"KÝ ỨC","lesson":10,"ex":[["子どものときの記憶があります。","Tôi có ký ức thời thơ ấu."],["いい記憶が残っています。","Ký ức đẹp vẫn còn lại."],["記憶が悪いです。","Trí nhớ của tôi kém."],["旅行の記憶を忘れません。","Tôi không quên ký ức chuyến du lịch."],["記憶に残る話でした。","Đó là câu chuyện đáng nhớ."]]},{"word":"型","reading":"かた","meaning":"Loại, kiểu","hanViet":"HÌNH","lesson":10,"ex":[["この型の車が好きです。","Tôi thích loại xe này."],["新しい型のテレビを買いました。","Tôi đã mua ti vi kiểu mới."],["古い型のパソコンを使います。","Tôi dùng máy tính kiểu cũ."],["どんな型ですか。","Là kiểu gì?"],["この型は便利です。","Kiểu này tiện lợi."]]},{"word":"～型","reading":"～がた","meaning":"Kiểu ~, loại ~","hanViet":"HÌNH","lesson":10,"ex":[["私はA型です。","Tôi nhóm máu A."],["山田さんはB型です。","Anh Yamada nhóm máu B."],["O型の人は多いです。","Người nhóm máu O rất nhiều."],["AB型の友達がいます。","Tôi có bạn nhóm máu AB."],["A型の人は真面目だと言われています。","Người nhóm máu A được nói là nghiêm túc."]]},{"word":"落とし物","reading":"おとしもの","meaning":"Đồ đánh rơi","hanViet":"LẠC VẬT","lesson":10,"ex":[["駅で落とし物を見つけました。","Tôi đã tìm thấy đồ đánh rơi ở ga."],["落とし物を警察に届けました。","Tôi đã nộp đồ đánh rơi cho cảnh sát."],["落とし物の財布がありました。","Có chiếc ví bị đánh rơi."],["落とし物を拾いました。","Tôi đã nhặt đồ đánh rơi."],["落とし物の傘が多いです。","Ô bị đánh rơi rất nhiều."]]},{"word":"転ぶ","reading":"ころぶ","meaning":"Ngã, té","hanViet":"CHUYỂN","lesson":10,"ex":[["雪の道で転びました。","Tôi đã ngã trên đường tuyết."],["階段で転びました。","Tôi đã ngã ở cầu thang."],["転んで、けがをしました。","Tôi ngã và bị thương."],["走って転びました。","Tôi chạy và ngã."],["転んだら、病院へ行きます。","Nếu ngã, tôi sẽ đi bệnh viện."]]},{"word":"奇数","reading":"きすう","meaning":"Số lẻ","hanViet":"KÌ SỐ","lesson":10,"ex":[["一、三、五、七、九は奇数です。","1, 3, 5, 7, 9 là số lẻ."],["十一は奇数です。","11 là số lẻ."],["奇数と偶数を覚えました。","Tôi đã nhớ số lẻ và số chẵn."],["計算で奇数を使います。","Tôi dùng số lẻ trong tính toán."],["七は奇数ですか。","7 có phải số lẻ không?"]]},{"word":"偶数","reading":"ぐうすう","meaning":"Số chẵn","hanViet":"NGẪU SỐ","lesson":10,"ex":[["二、四、六、八、十は偶数です。","2, 4, 6, 8, 10 là số chẵn."],["十二は偶数です。","12 là số chẵn."],["偶数と奇数を覚えました。","Tôi đã nhớ số chẵn và số lẻ."],["計算で偶数を使います。","Tôi dùng số chẵn trong tính toán."],["八は偶数ですか。","8 có phải số chẵn không?"]]},{"word":"ぼんやりする","reading":"ぼんやりする","meaning":"Mất tập trung","hanViet":"","lesson":10,"ex":[["授業でぼんやりしました。","Tôi đã mất tập trung trong giờ học."],["窓を見て、ぼんやりします。","Tôi nhìn ra cửa sổ và ngẩn ngơ."],["疲れたとき、ぼんやりします。","Khi mệt, tôi mất tập trung."],["空を見て、ぼんやりしました。","Tôi nhìn bầu trời và ngẩn ngơ."],["ぼんやりしないでください。","Đừng mất tập trung."]]},{"word":"あわて者","reading":"あわてもの","meaning":"Người hay hoảng hốt","hanViet":"GIẢ","lesson":10,"ex":[["田中さんはあわて者です。","Anh Tanaka là người hay hoảng hốt."],["あわて者はよく忘れます。","Người hay hoảng hốt thường hay quên."],["私はあわて者ですから、よく遅れます。","Vì tôi hay hoảng hốt nên thường đến muộn."],["あわて者はミスが多いです。","Người hay hoảng hốt hay mắc nhiều lỗi."],["あわて者でも、仕事ができます。","Dù hay hoảng hốt, vẫn có thể làm việc."]]},{"word":"ミス","reading":"ミス","meaning":"Sai lầm, lỗi","hanViet":"","lesson":10,"ex":[["仕事でミスをしました。","Tôi đã mắc lỗi trong công việc."],["ミスが多いです。","Có nhiều lỗi."],["ミスをしないように注意します。","Tôi chú ý để không mắc lỗi."],["小さいミスでした。","Đó là lỗi nhỏ."],["ミスを直しました。","Tôi đã sửa lỗi."]]},{"word":"これら","reading":"これら","meaning":"Những cái này","hanViet":"","lesson":10,"ex":[["これらの本は日本語の本です。","Những cuốn sách này là sách tiếng Nhật."],["これらの問題は難しいです。","Những bài toán này khó."],["これらの写真を見てください。","Hãy xem những bức ảnh này."],["これらの店は新しいです。","Những cửa hàng này mới."],["これらの話はおもしろいです。","Những câu chuyện này thú vị."]]},{"word":"ヒューマンエラー","reading":"ヒューマンエラー","meaning":"Lỗi chủ quan, lỗi do con người","hanViet":"","lesson":10,"ex":[["ヒューマンエラーで電車が遅れました。","Tàu đã trễ vì lỗi do con người."],["ヒューマンエラーについて勉強しました。","Tôi đã học về lỗi do con người."],["仕事でヒューマンエラーがありました。","Trong công việc đã có lỗi do con người."],["チェックリストでヒューマンエラーが減ります。","Nhờ danh sách kiểm tra mà lỗi do con người giảm."],["ヒューマンエラーはだれでもします。","Ai cũng mắc lỗi do con người."]]},{"word":"手術","reading":"しゅじゅつ","meaning":"Phẫu thuật","hanViet":"THỦ THUẬT","lesson":10,"ex":[["医者が手術をしました。","Bác sĩ đã phẫu thuật."],["手術は成功しました。","Phẫu thuật đã thành công."],["病院で手術を受けました。","Tôi đã phẫu thuật ở bệnh viện."],["手術のあと、入院しました。","Sau phẫu thuật, tôi đã nhập viện."],["手術をする前に、医者の話を聞きました。","Trước khi phẫu thuật, tôi đã nghe bác sĩ nói."]]},{"word":"患者","reading":"かんじゃ","meaning":"Bệnh nhân","hanViet":"HOẠN GIẢ","lesson":10,"ex":[["病院に患者がいます。","Trong bệnh viện có bệnh nhân."],["医者は患者を助けます。","Bác sĩ giúp đỡ bệnh nhân."],["患者が多くなりました。","Bệnh nhân đã tăng lên."],["患者に薬をあげました。","Tôi đã cho bệnh nhân thuốc."],["患者の話を聞きました。","Tôi đã nghe câu chuyện của bệnh nhân."]]},{"word":"心理学者","reading":"しんりがくしゃ","meaning":"Nhà tâm lý học","hanViet":"TÂM LÍ HỌC GIẢ","lesson":10,"ex":[["心理学者に会いました。","Tôi đã gặp nhà tâm lý học."],["心理学者は大学で働きます。","Nhà tâm lý học làm việc ở trường đại học."],["心理学者の本を読みました。","Tôi đã đọc sách của nhà tâm lý học."],["心理学者が研究します。","Nhà tâm lý học nghiên cứu."],["心理学者は心について話します。","Nhà tâm lý học nói về tâm hồn."]]},{"word":"おかす","reading":"おかす","meaning":"Phạm, mắc lỗi","hanViet":"","lesson":10,"ex":[["ミスをおかしました。","Tôi đã mắc lỗi."],["間違いをおかしました。","Tôi đã phạm sai lầm."],["うっかりミスをおかしました。","Tôi đã mắc lỗi bất cẩn."],["大きなミスをおかしました。","Tôi đã mắc lỗi lớn."],["ミスをおかさないようにします。","Tôi cố gắng không mắc lỗi."]]},{"word":"うっかりミス","reading":"うっかりミス","meaning":"Lỗi bất cẩn","hanViet":"","lesson":10,"ex":[["うっかりミスをしました。","Tôi đã mắc lỗi bất cẩn."],["うっかりミスが多いです。","Có nhiều lỗi bất cẩn."],["うっかりミスで試験に失敗しました。","Vì lỗi bất cẩn nên tôi đã trượt kỳ thi."],["チェックリストでうっかりミスが減ります。","Nhờ danh sách kiểm tra mà lỗi bất cẩn giảm."],["うっかりミスをしないように注意します。","Tôi chú ý để không mắc lỗi bất cẩn."]]},{"word":"うっかり","reading":"うっかり","meaning":"Bất cẩn","hanViet":"","lesson":10,"ex":[["うっかり忘れました。","Tôi đã quên một cách bất cẩn."],["うっかり財布を落としました。","Tôi đã bất cẩn đánh rơi ví."],["うっかりして、宿題を忘れました。","Tôi bất cẩn nên đã quên bài tập."],["うっかりして、ミスをしました。","Tôi bất cẩn nên đã mắc lỗi."],["うっかりしないでください。","Đừng bất cẩn."]]},{"word":"こういう","reading":"こういう","meaning":"Như thế này","hanViet":"","lesson":10,"ex":[["こういう本が好きです。","Tôi thích cuốn sách như thế này."],["こういう場合はどうしますか。","Trong trường hợp như thế này thì làm gì?"],["こういう人が好きです。","Tôi thích người như thế này."],["こういう問題は難しいです。","Bài toán như thế này khó."],["こういう話を聞きました。","Tôi đã nghe câu chuyện như thế này."]]},{"word":"チェックリスト","reading":"チェックリスト","meaning":"Danh sách kiểm tra","hanViet":"","lesson":10,"ex":[["チェックリストを作りました。","Tôi đã làm danh sách kiểm tra."],["チェックリストを見てください。","Hãy xem danh sách kiểm tra."],["旅行の前に、チェックリストを作ります。","Trước chuyến du lịch, tôi làm danh sách kiểm tra."],["チェックリストでミスが減ります。","Nhờ danh sách kiểm tra mà lỗi giảm."],["仕事のチェックリストがあります。","Có danh sách kiểm tra công việc."]]},{"word":"手がかり","reading":"てがかり","meaning":"Gợi ý, đầu mối","hanViet":"THỦ","lesson":10,"ex":[["手がかりを見つけました。","Tôi đã tìm thấy đầu mối."],["事件の手がかりを探します。","Tôi tìm đầu mối của vụ án."],["手がかりがありません。","Không có đầu mối."],["小さい手がかりがありました。","Có đầu mối nhỏ."],["手がかりから答えが分かりました。","Nhờ đầu mối mà tôi đã hiểu ra đáp án."]]},{"word":"一方","reading":"いっぽう","meaning":"Mặt khác","hanViet":"PHƯƠNG","lesson":10,"ex":[["田中さんは歌が好きです。一方、山田さんはスポーツが好きです。","Anh Tanaka thích hát. Mặt khác, anh Yamada thích thể thao."],["夏は暑いです。一方、冬は寒いです。","Mùa hè nóng. Mặt khác, mùa đông lạnh."],["電車は速いです。一方、歩くのは遅いです。","Tàu nhanh. Mặt khác, đi bộ thì chậm."],["田中さんは忙しいです。一方、私は暇です。","Anh Tanaka bận. Mặt khác, tôi rảnh."],["兄は東京に住んでいます。一方、弟は大阪に住んでいます。","Anh trai sống ở Tokyo. Mặt khác, em trai sống ở Osaka."]]},{"word":"深く","reading":"ふかく","meaning":"Sâu; một cách sâu (sắc)","hanViet":"THÂM","lesson":10,"ex":[["深く考えました。","Tôi đã suy nghĩ sâu sắc."],["深く眠りました。","Tôi đã ngủ sâu."],["深く感謝します。","Tôi biết ơn sâu sắc."],["この話は心に深く残りました。","Câu chuyện này đã in sâu trong tim tôi."],["日本語を深く勉強します。","Tôi học tiếng Nhật một cách sâu sắc."]]},{"word":"指","reading":"ゆび","meaning":"Ngón tay","hanViet":"CHỈ","lesson":10,"ex":[["指を切りました。","Tôi đã cắt vào ngón tay."],["指に指輪をしています。","Tôi đeo nhẫn ở ngón tay."],["指で空をさしました。","Tôi chỉ tay lên trời."],["手の指は五本あります。","Ngón tay có 5 ngón."],["指が長いです。","Ngón tay dài."]]},{"word":"聖人君子","reading":"せいじんくんし","meaning":"Thánh nhân quân tử, người toàn vẹn","hanViet":"THÁNH NHÂN QUÂN TỬ","lesson":10,"ex":[["聖人君子はいません。","Không có thánh nhân quân tử."],["だれでもミスをします。聖人君子ではありません。","Ai cũng mắc lỗi. Không phải thánh nhân quân tử."],["聖人君子のように見えます。","Trông như thánh nhân quân tử."],["聖人君子でも、間違いをします。","Dù là thánh nhân quân tử, vẫn mắc sai lầm."],["田中さんは聖人君子です。","Anh Tanaka là thánh nhân quân tử."]]},{"word":"うそつき","reading":"うそつき","meaning":"Kẻ nói dối","hanViet":"","lesson":10,"ex":[["あの人はうそつきですから、話を信じてはいけません。","Người đó là kẻ nói dối nên đừng tin lời anh ta."],["うそつきの子どもは、友達が少なくなります。","Đứa trẻ hay nói dối sẽ có ít bạn bè."],["彼はうそつきだと思います。","Tôi nghĩ anh ta là kẻ nói dối."],["うそつきにならないように、うそをつかないでください。","Đừng nói dối để không trở thành kẻ nói dối."],["母はうそつきはいけないと言いました。","Mẹ đã nói nói dối là không được."]]},{"word":"または","reading":"または","meaning":"Hay như, hoặc là","hanViet":"","lesson":10,"ex":[["土曜日または日曜日に会いましょう。","Hãy gặp nhau vào thứ Bảy hoặc Chủ nhật."],["電話またはメールで連絡してください。","Hãy liên lạc bằng điện thoại hoặc email."],["コーヒーまたは紅茶を飲みますか。","Bạn uống cà phê hay trà?"],["彼はバスまたは電車で会社へ行きます。","Anh ấy đi làm bằng xe buýt hoặc tàu điện."],["この本は日本語または英語で書いてあります。","Cuốn sách này được viết bằng tiếng Nhật hoặc tiếng Anh."]]},{"word":"エラー","reading":"エラー","meaning":"Lỗi","hanViet":"","lesson":10,"ex":[["パソコンにエラーが出ました。","Máy tính bị lỗi."],["エラーが起きたときは、先生に聞いてください。","Khi có lỗi, hãy hỏi thầy giáo."],["このメールはエラーで送れませんでした。","Email này không gửi được vì lỗi."],["エラーを直すのに時間がかかりました。","Mất thời gian để sửa lỗi."],["エラーが何回も出るので、新しいパソコンを買いたいです。","Lỗi xuất hiện nhiều lần nên tôi muốn mua máy tính mới."]]},{"word":"困った人","reading":"こまったひと","meaning":"Người gặp khó khăn, người khổ sở","hanViet":"KHỐN NHÂN","lesson":10,"ex":[["困った人がいたら、手伝ってあげてください。","Nếu có người gặp khó khăn, hãy giúp họ."],["困った人を助けるのは大切です。","Giúp đỡ người gặp khó khăn là điều quan trọng."],["彼は困った人のためにボランティアをしています。","Anh ấy làm tình nguyện vì những người gặp khó khăn."],["困った人は市役所に相談することができます。","Người gặp khó khăn có thể đến tòa thị chính để nhờ tư vấn."],["道に迷った困った人を駅まで案内しました。","Tôi đã dẫn người gặp khó khăn bị lạc đường đến ga."]]},{"word":"完成する","reading":"かんせいする","meaning":"Hoàn thành","hanViet":"HOÀN THÀNH","lesson":10,"ex":[["新しい家が来月完成します。","Ngôi nhà mới sẽ hoàn thành vào tháng sau."],["この本は来年完成する予定です。","Cuốn sách này dự định hoàn thành vào năm sau."],["橋が完成したら、町が便利になります。","Khi cầu hoàn thành, thị trấn sẽ trở nên tiện lợi."],["先生はレポートが完成したか聞きました。","Thầy giáo hỏi báo cáo đã hoàn thành chưa."],["完成するまでに時間がかかりました。","Mất thời gian cho đến khi hoàn thành."]]},{"word":"つながる","reading":"つながる","meaning":"Nối liền, liên kết; dẫn đến","hanViet":"","lesson":10,"ex":[["この道は駅につながっています。","Con đường này nối tới ga."],["不注意が事故につながることがあります。","Bất cẩn có thể dẫn đến tai nạn."],["インターネットにつながらないので、メールが送れません。","Vì không kết nối được Internet nên không gửi được email."],["二つの川がここでつながります。","Hai con sông nối nhau ở đây."],["努力が成功につながると思います。","Tôi nghĩ nỗ lực sẽ dẫn đến thành công."]]},{"word":"出来事","reading":"できごと","meaning":"Sự việc, chuyện xảy ra","hanViet":"XUẤT LAI SỰ","lesson":10,"ex":[["きのう、学校でおもしろい出来事がありました。","Hôm qua, ở trường đã có một chuyện thú vị."],["その出来事を今でも覚えています。","Tôi vẫn nhớ chuyện đó đến bây giờ."],["楽しい出来事について友達に話しました。","Tôi đã kể cho bạn nghe về chuyện vui."],["この出来事の後で、日本語の勉強を始めました。","Sau chuyện đó, tôi đã bắt đầu học tiếng Nhật."],["悲しい出来事があって、泣きました。","Có chuyện buồn nên tôi đã khóc."]]},{"word":"不注意","reading":"ふちゅうい","meaning":"Không chú ý, bất cẩn","hanViet":"BẤT CHÚ Ý","lesson":10,"ex":[["不注意でけがをしました。","Tôi bị thương vì bất cẩn."],["不注意な運転は事故を引き起こします。","Lái xe bất cẩn gây ra tai nạn."],["運転のときは不注意にならないでください。","Khi lái xe, đừng bất cẩn."],["不注意が原因で火事が起きました。","Vì bất cẩn mà đã xảy ra hỏa hoạn."],["彼は不注意で大切な書類をなくしました。","Anh ấy bất cẩn làm mất tài liệu quan trọng."]]},{"word":"引き起こす","reading":"ひきおこす","meaning":"Gây ra","hanViet":"DẪN KHỞI","lesson":10,"ex":[["地震が津波を引き起こしました。","Động đất đã gây ra sóng thần."],["たばこが火事を引き起こすことがあります。","Thuốc lá có thể gây ra hỏa hoạn."],["強い風が事故を引き起こしました。","Gió mạnh đã gây ra tai nạn."],["その問題がけんかを引き起こしました。","Vấn đề đó đã gây ra cãi nhau."],["不注意な運転が事故を引き起こすので、気をつけましょう。","Lái xe bất cẩn gây ra tai nạn nên hãy cẩn thận."]]},{"word":"ますます","reading":"ますます","meaning":"Ngày càng","hanViet":"","lesson":11,"ex":[["日本語がますます好きになりました。","Tôi ngày càng thích tiếng Nhật."],["町はますますにぎやかになっています。","Thị trấn ngày càng trở nên nhộn nhịp."],["ますます暑くなってきました。","Trời ngày càng nóng lên."],["彼はますます上手に日本語を話します。","Anh ấy ngày càng nói tiếng Nhật giỏi."],["この店はますます人気があります。","Cửa hàng này ngày càng được yêu thích."]]},{"word":"企業","reading":"きぎょう","meaning":"Công ty, doanh nghiệp","hanViet":"XÍ NGHIỆP","lesson":11,"ex":[["日本にはたくさんの企業があります。","Ở Nhật có nhiều doanh nghiệp."],["彼は大きな企業で働いています。","Anh ấy làm việc ở một công ty lớn."],["その企業は環境を大切にしています。","Doanh nghiệp đó coi trọng môi trường."],["企業で働くために、日本語を勉強しています。","Tôi học tiếng Nhật để làm việc ở doanh nghiệp."],["新しい企業が町にできました。","Một doanh nghiệp mới đã xuất hiện ở thị trấn."]]},{"word":"今後","reading":"こんご","meaning":"Từ nay trở đi","hanViet":"KIM HẬU","lesson":11,"ex":[["今後、日本語をもっと勉強したいです。","Từ nay trở đi, tôi muốn học tiếng Nhật nhiều hơn."],["今後の予定を話し合いましょう。","Hãy bàn về kế hoạch từ nay trở đi."],["今後もよろしくお願いします。","Từ nay về sau mong được giúp đỡ."],["今後、環境問題がもっと大切になります。","Từ nay trở đi, vấn đề môi trường sẽ càng quan trọng hơn."],["今後、どんな仕事をしたいですか。","Từ nay trở đi, bạn muốn làm công việc gì?"]]},{"word":"方言","reading":"ほうげん","meaning":"Tiếng địa phương","hanViet":"PHƯƠNG NGÔN","lesson":11,"ex":[["大阪の方言はおもしろいです。","Tiếng địa phương Osaka rất thú vị."],["彼は方言で話すことがあります。","Anh ấy có khi nói bằng tiếng địa phương."],["日本にはいろいろな方言があります。","Ở Nhật có nhiều tiếng địa phương."],["方言がわからなくて、困りました。","Tôi không hiểu tiếng địa phương nên đã lúng túng."],["田舎の方言を聞くのは楽しいです。","Nghe tiếng địa phương ở nông thôn rất vui."]]},{"word":"普及する","reading":"ふきゅうする","meaning":"Phổ cập","hanViet":"PHỔ CẬP","lesson":11,"ex":[["インターネットが世界中に普及しました。","Internet đã phổ cập khắp thế giới."],["この機械は日本で普及しています。","Máy này đang phổ cập ở Nhật."],["新しい技術が世界に普及しています。","Công nghệ mới đang phổ cập ra thế giới."],["普及するまでに時間がかかりました。","Mất thời gian cho đến khi phổ cập."],["コンピューターが学校に普及しました。","Máy tính đã phổ cập ở trường học."]]},{"word":"建つ","reading":"たつ","meaning":"Được xây dựng","hanViet":"KIẾN","lesson":11,"ex":[["新しいビルが駅の前に建ちました。","Tòa nhà mới đã được xây trước ga."],["この家は去年建ちました。","Ngôi nhà này được xây năm ngoái."],["ここに大きな図書館が建つ予定です。","Dự định sẽ xây một thư viện lớn ở đây."],["山の上に古い城が建っています。","Trên núi có một tòa thành cổ."],["新しい学校が町に建ちます。","Trường học mới sẽ được xây ở thị trấn."]]},{"word":"大家族","reading":"だいかぞく","meaning":"Gia đình lớn, Đại gia đình","hanViet":"ĐẠI GIA TỘC","lesson":11,"ex":[["私の家は大家族です。","Gia đình tôi là đại gia đình."],["大家族で住むのは楽しいです。","Sống trong đại gia đình rất vui."],["彼は大家族の中で生活しています。","Anh ấy đang sống trong một đại gia đình."],["大家族の食事はにぎやかです。","Bữa ăn của đại gia đình rất nhộn nhịp."],["お正月には大家族が集まります。","Vào Tết, đại gia đình tụ họp."]]},{"word":"大～","reading":"だい～","meaning":"~ lớn, ~ to","hanViet":"ĐẠI","lesson":11,"ex":[["大雨で電車が止まりました。","Mưa to làm tàu điện dừng lại."],["大雪が降って、道が白くなりました。","Tuyết rơi nhiều, đường trắng xóa."],["大人は仕事が忙しいです。","Người lớn bận công việc."],["私は日本語が大好きです。","Tôi rất thích tiếng Nhật."],["大切な本をなくしてしまいました。","Tôi đã làm mất cuốn sách quan trọng."]]},{"word":"パックツアー","reading":"パックツアー","meaning":"Tour trọn gói","hanViet":"","lesson":11,"ex":[["パックツアーで京都へ行きました。","Tôi đã đi Kyoto bằng tour trọn gói."],["パックツアーには飛行機とホテルが入っています。","Tour trọn gói bao gồm máy bay và khách sạn."],["初めての旅行はパックツアーが便利です。","Chuyến du lịch đầu tiên thì tour trọn gói tiện lợi."],["パックツアーで日本を旅行したいです。","Tôi muốn du lịch Nhật Bản bằng tour trọn gói."],["パックツアーの値段を調べました。","Tôi đã tìm hiểu giá tour trọn gói."]]},{"word":"個人","reading":"こじん","meaning":"Cá nhân","hanViet":"CÁ NHÂN","lesson":11,"ex":[["個人の意見を大切にしましょう。","Hãy tôn trọng ý kiến cá nhân."],["これは個人のコンピューターです。","Đây là máy tính cá nhân."],["個人で旅行するのが好きです。","Tôi thích du lịch một mình."],["個人の情報を守るのは大切です。","Bảo vệ thông tin cá nhân là quan trọng."],["個人の力で問題を解決しました。","Tôi đã giải quyết vấn đề bằng sức mình."]]},{"word":"いかにも","reading":"いかにも","meaning":"Quả thật, đúng là","hanViet":"","lesson":11,"ex":[["いかにも彼女らしい優しいことばです。","Đúng là lời nói dịu dàng như cô ấy."],["彼は、いかにも疲れた顔をしていました。","Anh ấy có vẻ mặt đúng là mệt mỏi."],["いかにも日本らしい景色ですね。","Đúng là phong cảnh rất Nhật Bản."],["彼女はいかにも楽しそうに笑いました。","Cô ấy cười trông thật vui vẻ."],["いかにも夏らしい暑い日でした。","Đó là một ngày nóng đúng chất mùa hè."]]},{"word":"入学式","reading":"にゅうがくしき","meaning":"Lễ nhập học","hanViet":"NHẬP HỌC THỨC","lesson":11,"ex":[["入学式は四月に行います。","Lễ nhập học tổ chức vào tháng Tư."],["入学式で新しい友達に会いました。","Tôi đã gặp bạn mới ở lễ nhập học."],["子どもの入学式に行きました。","Tôi đã đi dự lễ nhập học của con."],["入学式の日に桜が咲いていました。","Vào ngày lễ nhập học, hoa anh đào đang nở."],["入学式では先生が話をしました。","Ở lễ nhập học, thầy giáo đã phát biểu."]]},{"word":"派手","reading":"はで","meaning":"Sặc sỡ","hanViet":"PHÁI THỦ","lesson":11,"ex":[["彼女は派手な服が好きです。","Cô ấy thích quần áo sặc sỡ."],["派手な色のシャツを買いました。","Tôi đã mua áo sơ mi màu sặc sỡ."],["このネクタイは少し派手です。","Cà vạt này hơi sặc sỡ."],["派手な服より、地味な服が好きです。","Tôi thích quần áo giản dị hơn quần áo sặc sỡ."],["祭りでは派手な服を着る人が多いです。","Ở lễ hội có nhiều người mặc quần áo sặc sỡ."]]},{"word":"元気","reading":"げんき","meaning":"Khỏe mạnh","hanViet":"NGUYÊN KHÍ","lesson":11,"ex":[["お元気ですか。","Bạn có khỏe không?"],["祖父は八十歳ですが、元気です。","Ông tôi 80 tuổi nhưng vẫn khỏe."],["病気が治って、元気になりました。","Bệnh khỏi rồi, tôi đã khỏe lại."],["元気な子どもたちが公園で遊んでいます。","Những đứa trẻ khỏe mạnh đang chơi ở công viên."],["毎日運動して、元気です。","Tôi tập thể dục mỗi ngày nên khỏe mạnh."]]},{"word":"広告","reading":"こうこく","meaning":"Quảng cáo","hanViet":"QUẢNG CÁO","lesson":11,"ex":[["テレビで新しい車の広告を見ました。","Tôi đã xem quảng cáo xe mới trên TV."],["この広告はおもしろいです。","Quảng cáo này thú vị."],["広告を見て、その店へ行きました。","Tôi xem quảng cáo rồi đến cửa hàng đó."],["新聞の広告で仕事を探しました。","Tôi tìm việc qua quảng cáo trên báo."],["インターネットの広告が多くなりました。","Quảng cáo trên Internet ngày càng nhiều."]]},{"word":"美容院","reading":"びよういん","meaning":"Tiệm làm tóc, salon làm đẹp","hanViet":"MỸ DUNG VIỆN","lesson":11,"ex":[["美容院で髪を切りました。","Tôi đã cắt tóc ở tiệm làm tóc."],["美容院の予約をしました。","Tôi đã đặt lịch ở tiệm làm tóc."],["母は毎月美容院へ行きます。","Mẹ tôi đi tiệm làm tóc mỗi tháng."],["新しい美容院が駅の近くにできました。","Tiệm làm tóc mới mở gần ga."],["美容院で髪を染めました。","Tôi đã nhuộm tóc ở tiệm làm tóc."]]},{"word":"車いす","reading":"くるまいす","meaning":"Xe lăn","hanViet":"XA","lesson":11,"ex":[["お年寄りは車いすを使います。","Người già dùng xe lăn."],["車いすの人がエレベーターを使いました。","Người ngồi xe lăn đã dùng thang máy."],["病院に車いすを寄付しました。","Tôi đã quyên tặng xe lăn cho bệnh viện."],["車いすで店に入ることができます。","Có thể vào cửa hàng bằng xe lăn."],["祖母は車いすで生活しています。","Bà tôi sinh hoạt bằng xe lăn."]]},{"word":"寄付する","reading":"きふする","meaning":"Quyên góp, quyên tặng","hanViet":"KÍ PHÓ","lesson":11,"ex":[["困っている人に服を寄付しました。","Tôi đã quyên tặng quần áo cho người gặp khó khăn."],["学校に本を寄付しました。","Tôi đã quyên tặng sách cho trường học."],["寄付するお金が少なくてすみません。","Xin lỗi vì số tiền quyên góp ít."],["多くの人が寄付をしました。","Nhiều người đã quyên góp."],["寄付したお金で図書館が建ちました。","Thư viện đã được xây bằng tiền quyên góp."]]},{"word":"グレー","reading":"グレー","meaning":"Màu xám","hanViet":"","lesson":11,"ex":[["グレーのコートを買いました。","Tôi đã mua áo khoác màu xám."],["空がグレーになりました。","Bầu trời chuyển sang màu xám."],["グレーのセーターが好きです。","Tôi thích áo len màu xám."],["このズボンはグレーですか、黒ですか。","Quần này màu xám hay màu đen?"],["グレーと白のシャツを持っています。","Tôi có áo sơ mi màu xám và trắng."]]},{"word":"地味","reading":"じみ","meaning":"Giản dị","hanViet":"ĐỊA VỊ","lesson":11,"ex":[["彼女は地味な服が好きです。","Cô ấy thích quần áo giản dị."],["地味な色のネクタイを買いました。","Tôi đã mua cà vạt màu giản dị."],["彼は地味な人ですが、優しいです。","Anh ấy là người giản dị nhưng tốt bụng."],["地味な服より、派手な服が好きです。","Tôi thích quần áo sặc sỡ hơn quần áo giản dị."],["この部屋は地味な色で落ち着いています。","Căn phòng này màu giản dị nên tạo cảm giác bình yên."]]},{"word":"原爆","reading":"げんばく","meaning":"Bom hạt nhân, bom nguyên tử","hanViet":"NGUYÊN BẠO","lesson":11,"ex":[["原爆の恐ろしさを忘れてはいけません。","Không được quên sự khủng khiếp của bom nguyên tử."],["長崎に原爆が落とされました。","Bom nguyên tử đã bị thả xuống Nagasaki."],["原爆について学校で勉強しました。","Tôi đã học về bom nguyên tử ở trường."],["原爆で多くの人が亡くなりました。","Nhiều người đã chết vì bom nguyên tử."],["原爆のことを伝える博物館があります。","Có bảo tàng truyền tải về bom nguyên tử."]]},{"word":"ただ一つ","reading":"ただひとつ","meaning":"Chỉ một, duy nhất một","hanViet":"NHẤT","lesson":11,"ex":[["ただ一つの希望は家族の健康です。","Hy vọng duy nhất là sức khỏe của gia đình."],["ただ一つの問題があります。","Chỉ có một vấn đề."],["この村にただ一つの学校があります。","Trong làng này chỉ có một trường học."],["ただ一つ言いたいことがあります。","Tôi chỉ có một điều muốn nói."],["ただ一つのりんごを子どもにあげました。","Tôi đã cho đứa trẻ quả táo duy nhất."]]},{"word":"恐ろしさ","reading":"おそろしさ","meaning":"Sự khủng khiếp","hanViet":"KHỦNG","lesson":11,"ex":[["地震の恐ろしさを感じました。","Tôi đã cảm nhận sự khủng khiếp của động đất."],["戦争の恐ろしさを知っています。","Tôi biết sự khủng khiếp của chiến tranh."],["津波の恐ろしさに驚きました。","Tôi đã kinh ngạc trước sự khủng khiếp của sóng thần."],["火事の恐ろしさを子どもに教えました。","Tôi đã dạy cho trẻ về sự khủng khiếp của hỏa hoạn."],["その恐ろしさは忘れられません。","Không thể quên được sự khủng khiếp đó."]]},{"word":"ダイナマイト","reading":"ダイナマイト","meaning":"Thuốc nổ dynamite","hanViet":"","lesson":11,"ex":[["ダイナマイトは危険なものです。","Dynamite là thứ nguy hiểm."],["山を壊すためにダイナマイトを使いました。","Người ta đã dùng dynamite để phá núi."],["ダイナマイトの発明について本で読みました。","Tôi đã đọc trong sách về phát minh dynamite."],["ダイナマイトを使うときは気をつけなければなりません。","Khi dùng dynamite phải cẩn thận."],["工事でダイナマイトが使われました。","Dynamite đã được dùng trong công trình."]]},{"word":"自宅","reading":"じたく","meaning":"Nhà mình","hanViet":"TỰ TRẠCH","lesson":11,"ex":[["自宅で仕事をしています。","Tôi làm việc tại nhà."],["彼は自宅から会社へ通っています。","Anh ấy đi làm từ nhà mình."],["自宅に帰るのが楽しみです。","Tôi mong được về nhà."],["自宅で日本語を勉強しています。","Tôi học tiếng Nhật ở nhà."],["自宅の庭に花を植えました。","Tôi đã trồng hoa trong vườn nhà."]]},{"word":"あわてる","reading":"あわてる","meaning":"Hoảng hốt, vội vàng","hanViet":"","lesson":11,"ex":[["電車に遅れそうであわてました。","Tôi hoảng hốt vì sắp trễ tàu."],["あわてないで、ゆっくり話してください。","Đừng vội, hãy nói từ từ."],["彼は試験の前にあわてていました。","Anh ấy hoảng hốt trước kỳ thi."],["あわてて家を出ました。","Tôi vội vàng ra khỏi nhà."],["地震のときはあわててはいけません。","Khi động đất không được hoảng hốt."]]},{"word":"落ち着く","reading":"おちつく","meaning":"Bình tĩnh","hanViet":"LẠC TRƯỚC","lesson":11,"ex":[["音楽を聞いて、落ち着きました。","Nghe nhạc, tôi đã bình tĩnh lại."],["落ち着いて話してください。","Hãy bình tĩnh nói."],["試験の前に落ち着くことが大切です。","Trước kỳ thi, bình tĩnh là quan trọng."],["彼はすぐに落ち着きました。","Anh ấy nhanh chóng bình tĩnh lại."],["お茶を飲んで落ち着きました。","Uống trà, tôi đã bình tĩnh lại."]]},{"word":"行動する","reading":"こうどうする","meaning":"Hành động","hanViet":"HÀNH ĐỘNG","lesson":11,"ex":[["地震のときはすぐに行動しなければなりません。","Khi động đất phải hành động ngay."],["考えてから行動してください。","Hãy suy nghĩ rồi hãy hành động."],["彼は環境のために行動しています。","Anh ấy đang hành động vì môi trường."],["自分で考えて行動するのが大切です。","Tự suy nghĩ và hành động là quan trọng."],["行動する前に計画を立てましょう。","Trước khi hành động, hãy lập kế hoạch."]]},{"word":"のんびりする","reading":"のんびりする","meaning":"Thư thái, nhàn nhã","hanViet":"","lesson":11,"ex":[["休みの日は家でのんびりします。","Ngày nghỉ tôi thư thái ở nhà."],["海を見ながらのんびりしました。","Tôi đã thư thái ngắm biển."],["温泉でのんびりするのが好きです。","Tôi thích thư thái ở suối nước nóng."],["週末はのんびり過ごしたいです。","Cuối tuần tôi muốn trải qua thật thư thái."],["公園でのんびり本を読みました。","Tôi đã thư thái đọc sách ở công viên."]]},{"word":"シューズ","reading":"シューズ","meaning":"Giày","hanViet":"","lesson":11,"ex":[["新しいシューズを買いました。","Tôi đã mua giày mới."],["スポーツのシューズが必要です。","Cần giày thể thao."],["シューズをはいて出かけました。","Tôi đã mang giày ra ngoài."],["このシューズは歩きやすいです。","Đôi giày này dễ đi."],["シューズが汚れたので、洗いました。","Giày bị bẩn nên tôi đã giặt."]]},{"word":"遺跡","reading":"いせき","meaning":"Di tích","hanViet":"DI TÍCH","lesson":11,"ex":[["遺跡を見に京都へ行きました。","Tôi đã đi Kyoto để xem di tích."],["古い遺跡が村で見つかりました。","Di tích cổ đã được tìm thấy ở làng."],["この遺跡は有名です。","Di tích này nổi tiếng."],["遺跡について勉強しました。","Tôi đã học về di tích."],["遺跡を守るのは大切です。","Bảo vệ di tích là quan trọng."]]},{"word":"発掘","reading":"はっくつ","meaning":"Khai quật","hanViet":"PHÁT QUẬT","lesson":11,"ex":[["遺跡の発掘が始まりました。","Việc khai quật di tích đã bắt đầu."],["発掘で古い道具が見つかりました。","Nhờ khai quật đã tìm thấy dụng cụ cổ."],["発掘の仕事をしている人がいます。","Có người đang làm công việc khai quật."],["村で発掘が行われました。","Khai quật đã được tiến hành ở làng."],["発掘についてテレビで見ました。","Tôi đã xem về khai quật trên TV."]]},{"word":"これまでに","reading":"これまでに","meaning":"Cho đến nay, cho đến bây giờ","hanViet":"","lesson":11,"ex":[["これまでにいろいろな国へ行きました。","Cho đến nay tôi đã đi nhiều nước."],["これまでに日本語を三年勉強しました。","Cho đến nay tôi đã học tiếng Nhật ba năm."],["これまでに見た映画の中で、これが一番おもしろいです。","Trong những phim đã xem cho đến nay, phim này thú vị nhất."],["これまでに会った人の中で、彼が一番親切です。","Trong những người đã gặp cho đến nay, anh ấy tốt bụng nhất."],["これまでに三回引っ越しをしました。","Cho đến nay tôi đã chuyển nhà ba lần."]]},{"word":"南極","reading":"なんきょく","meaning":"Nam cực","hanViet":"NAM CỰC","lesson":11,"ex":[["南極はとても寒いです。","Nam Cực rất lạnh."],["南極を探検するテレビ番組を見ました。","Tôi đã xem chương trình TV thám hiểm Nam Cực."],["南極の写真を見ました。","Tôi đã xem ảnh Nam Cực."],["南極へ行くのは難しいです。","Đi Nam Cực rất khó."],["南極の研究をしている人がいます。","Có người đang nghiên cứu Nam Cực."]]},{"word":"探検","reading":"たんけん","meaning":"Thám hiểm","hanViet":"THÁM KIỂM","lesson":11,"ex":[["山を探検するのが好きです。","Tôi thích thám hiểm núi."],["探検の本を読みました。","Tôi đã đọc sách về thám hiểm."],["子どものころ、森を探検しました。","Hồi nhỏ, tôi đã thám hiểm rừng."],["南極を探検した人の話を聞きました。","Tôi đã nghe câu chuyện của người đã thám hiểm Nam Cực."],["探検に行く前に準備をしました。","Trước khi đi thám hiểm, tôi đã chuẩn bị."]]},{"word":"世界遺産","reading":"せかいいさん","meaning":"Di sản thế giới","hanViet":"THẾ GIỚI DI SẢN","lesson":11,"ex":[["京都には世界遺産がたくさんあります。","Ở Kyoto có nhiều di sản thế giới."],["世界遺産を見に行きたいです。","Tôi muốn đi xem di sản thế giới."],["この城は世界遺産です。","Tòa thành này là di sản thế giới."],["世界遺産を守るのは大切です。","Bảo vệ di sản thế giới là quan trọng."],["日本の世界遺産について勉強しました。","Tôi đã học về di sản thế giới của Nhật Bản."]]},{"word":"価値","reading":"かち","meaning":"Giá trị","hanViet":"GIÁ TRỊ","lesson":11,"ex":[["この本には大きな価値があります。","Cuốn sách này có giá trị lớn."],["時間の価値を知っていますか。","Bạn có biết giá trị của thời gian không?"],["価値のある仕事をしたいです。","Tôi muốn làm công việc có giá trị."],["古い物にも価値があります。","Đồ cũ cũng có giá trị."],["この絵の価値は高いです。","Giá trị của bức tranh này cao."]]},{"word":"やっぱり","reading":"やっぱり","meaning":"Quả nhiên, đúng như mình nghĩ; rốt cuộc vẫn là (dạng văn nói của やはり)","hanViet":"","lesson":11,"ex":[["やっぱり日本語は難しいですね。","Quả nhiên tiếng Nhật khó thật."],["やっぱり家で食べるごはんが一番おいしいです。","Quả nhiên cơm ăn ở nhà là ngon nhất."],["天気が悪いので、やっぱり行きません。","Vì thời tiết xấu nên rốt cuộc tôi không đi."],["やっぱり彼は来ませんでした。","Quả nhiên anh ấy đã không đến."],["やっぱりこの本が一番おもしろいです。","Quả nhiên cuốn sách này thú vị nhất."]]},{"word":"流氷","reading":"りゅうひょう","meaning":"Băng trôi, tảng băng trôi","hanViet":"LƯU BĂNG","lesson":11,"ex":[["寒い海で流氷を見ました。","Tôi đã xem băng trôi ở biển lạnh."],["流氷は冬に見られます。","Băng trôi có thể xem vào mùa đông."],["流氷についてテレビで見ました。","Tôi đã xem về băng trôi trên TV."],["流氷がたくさん流れています。","Nhiều băng trôi đang trôi."],["流氷を見に旅行に行きたいです。","Tôi muốn đi du lịch để xem băng trôi."]]},{"word":"自由行動","reading":"じゆうこうどう","meaning":"Tự do hành động","hanViet":"TỰ DO HÀNH ĐỘNG","lesson":11,"ex":[["旅行のときは自由行動の時間があります。","Khi du lịch có thời gian tự do hành động."],["自由行動の時間に町を歩きました。","Trong thời gian tự do hành động, tôi đã đi bộ quanh thị trấn."],["明日は自由行動です。","Ngày mai là tự do hành động."],["自由行動で博物館へ行きました。","Tôi đã đi bảo tàng trong thời gian tự do."],["自由行動のときは一人で買い物をしました。","Lúc tự do hành động, tôi đã đi mua sắm một mình."]]},{"word":"提案する","reading":"ていあんする","meaning":"Đề xuất","hanViet":"ĐỀ ÁN","lesson":11,"ex":[["新しい計画を提案しました。","Tôi đã đề xuất kế hoạch mới."],["先生に意見を提案しました。","Tôi đã đề xuất ý kiến với thầy giáo."],["会議で提案する予定です。","Tôi dự định đề xuất ở cuộc họp."],["彼のアイディアを提案しました。","Tôi đã đề xuất ý tưởng của anh ấy."],["提案された計画について話し合いました。","Chúng tôi đã bàn về kế hoạch được đề xuất."]]},{"word":"軽く","reading":"かるく","meaning":"Nhẹ, nhẹ nhàng","hanViet":"KHINH","lesson":11,"ex":[["軽く運動するのが好きです。","Tôi thích vận động nhẹ."],["軽くたたいてください。","Hãy gõ nhẹ."],["ドアを軽く閉めました。","Tôi đã đóng cửa nhẹ nhàng."],["軽く笑って答えました。","Tôi đã cười nhẹ rồi trả lời."],["かばんが軽くなりました。","Cặp đã trở nên nhẹ hơn."]]},{"word":"乗り物","reading":"のりもの","meaning":"Phương tiện đi lại","hanViet":"THỪA VẬT","lesson":11,"ex":[["乗り物で旅行するのが好きです。","Tôi thích du lịch bằng phương tiện đi lại."],["この町には乗り物が少ないです。","Ở thị trấn này có ít phương tiện đi lại."],["乗り物に酔うことがあります。","Có khi tôi bị say xe."],["どんな乗り物が好きですか。","Bạn thích phương tiện đi lại nào?"],["乗り物の値段が高くなりました。","Giá phương tiện đi lại đã tăng."]]},{"word":"酔う","reading":"よう","meaning":"Say xe/ tàu","hanViet":"TÚY","lesson":11,"ex":[["バスに乗ると酔います。","Đi xe buýt tôi bị say."],["船に酔って、気持ちが悪くなりました。","Say tàu, tôi cảm thấy khó chịu."],["酔うので、車のうしろに乗りません。","Vì say xe nên tôi không ngồi ghế sau ô tô."],["彼は酒を飲んで酔いました。","Anh ấy uống rượu rồi say."],["酔わないように、薬を飲みました。","Tôi đã uống thuốc để không bị say."]]},{"word":"コメント","reading":"コメント","meaning":"Lời nhận xét, ý kiến","hanViet":"","lesson":11,"ex":[["先生のコメントを読みました。","Tôi đã đọc nhận xét của thầy giáo."],["インターネットにコメントを書きました。","Tôi đã viết bình luận trên Internet."],["コメントをありがとうございます。","Cảm ơn lời nhận xét của bạn."],["彼のコメントはおもしろいです。","Nhận xét của anh ấy thú vị."],["コメントをもらって、うれしかったです。","Nhận được bình luận, tôi rất vui."]]},{"word":"さらに","reading":"さらに","meaning":"Hơn nữa","hanViet":"","lesson":11,"ex":[["さらに日本語を勉強したいです。","Tôi muốn học tiếng Nhật hơn nữa."],["さらに詳しく説明してください。","Hãy giải thích chi tiết hơn nữa."],["雨がさらに強くなりました。","Mưa càng mạnh hơn nữa."],["さらに多くの人が来ました。","Đã có nhiều người hơn nữa đến."],["さらに上を目指して頑張ります。","Tôi sẽ cố gắng hướng lên cao hơn nữa."]]},{"word":"仮装","reading":"かそう","meaning":"Giả trang, cải trang","hanViet":"GIẢ TRANG","lesson":11,"ex":[["祭りで仮装する人が多いです。","Ở lễ hội có nhiều người cải trang."],["子どもたちは仮装を楽しみました。","Trẻ em đã thích thú với cải trang."],["仮装パーティーに行きました。","Tôi đã đi dự tiệc cải trang."],["彼女は猫に仮装しました。","Cô ấy đã cải trang thành mèo."],["仮装のための服を買いました。","Tôi đã mua quần áo để cải trang."]]},{"word":"染める","reading":"そめる","meaning":"Nhuộm","hanViet":"NHIỄM","lesson":11,"ex":[["髪を黒く染めました。","Tôi đã nhuộm tóc màu đen."],["布を青く染めました。","Tôi đã nhuộm vải màu xanh."],["髪を染めるのは初めてです。","Nhuộm tóc là lần đầu tiên."],["母は髪を茶色に染めました。","Mẹ đã nhuộm tóc màu nâu."],["染めた髪がきれいですね。","Mái tóc đã nhuộm đẹp nhỉ."]]},{"word":"黄金","reading":"おうごん","meaning":"Vàng","hanViet":"HOÀNG KIM","lesson":11,"ex":[["黄金の指輪を買いました。","Tôi đã mua nhẫn vàng."],["黄金は高いです。","Vàng đắt."],["黄金の時計を持っています。","Tôi có đồng hồ vàng."],["昔の人は黄金を大切にしました。","Người xưa coi trọng vàng."],["黄金の色がきれいです。","Màu vàng đẹp."]]},{"word":"伝説","reading":"でんせつ","meaning":"Truyền thuyết","hanViet":"TRUYỀN THUYẾT","lesson":11,"ex":[["この村には古い伝説があります。","Làng này có truyền thuyết cổ."],["伝説について本で読みました。","Tôi đã đọc về truyền thuyết trong sách."],["その伝説は有名です。","Truyền thuyết đó nổi tiếng."],["伝説の話を祖母から聞きました。","Tôi đã nghe câu chuyện truyền thuyết từ bà."],["伝説では、昔ここに城がありました。","Theo truyền thuyết, ngày xưa ở đây có tòa thành."]]},{"word":"いくつか","reading":"いくつか","meaning":"Một vài, vài","hanViet":"","lesson":11,"ex":[["いくつか質問があります。","Tôi có vài câu hỏi."],["いくつかの本を買いました。","Tôi đã mua vài cuốn sách."],["いくつか問題が残っています。","Còn vài vấn đề."],["いくつか写真を撮りました。","Tôi đã chụp vài tấm ảnh."],["いくつかアイディアがあります。","Tôi có vài ý tưởng."]]},{"word":"屋根","reading":"やね","meaning":"Mái","hanViet":"ỐC CĂN","lesson":11,"ex":[["屋根に雪が積もっています。","Trên mái nhà tuyết đang chất đống."],["屋根を直しました。","Tôi đã sửa mái nhà."],["古い家の屋根は赤いです。","Mái nhà cũ màu đỏ."],["屋根が壊れたので、直しました。","Mái nhà bị hỏng nên tôi đã sửa."],["鳥が屋根に止まっています。","Chim đang đậu trên mái nhà."]]},{"word":"農作物","reading":"のうさくぶつ","meaning":"Cây trồng","hanViet":"NÔNG TÁC VẬT","lesson":11,"ex":[["この村では農作物を作っています。","Ở làng này người ta trồng nông sản."],["農作物が雨でだめになりました。","Cây trồng bị hỏng vì mưa."],["農作物の値段が上がりました。","Giá cây trồng đã tăng."],["農作物を育てるのは大変です。","Trồng nông sản rất vất vả."],["農作物について勉強しました。","Tôi đã học về cây trồng."]]},{"word":"金銀","reading":"きんぎん","meaning":"Vàng bạc","hanViet":"KIM NGÂN","lesson":11,"ex":[["金銀の指輪を持っています。","Tôi có nhẫn vàng bạc."],["昔の人は金銀を大切にしました。","Người xưa coi trọng vàng bạc."],["金銀が高いです。","Vàng bạc đắt."],["金銀の時計を買いました。","Tôi đã mua đồng hồ vàng bạc."],["金銀の色がきれいです。","Màu vàng bạc đẹp."]]},{"word":"掌","reading":"てのひら","meaning":"Lòng bàn tay","hanViet":"CHƯỞNG","lesson":11,"ex":[["掌が汗でぬれています。","Lòng bàn tay ướt mồ hôi."],["掌を見せてください。","Hãy cho tôi xem lòng bàn tay."],["掌の上に小さい花があります。","Trên lòng bàn tay có bông hoa nhỏ."],["掌で水を受けました。","Tôi đã hứng nước bằng lòng bàn tay."],["子どもの掌は小さいです。","Lòng bàn tay trẻ em nhỏ."]]},{"word":"後半","reading":"こうはん","meaning":"Nửa sau","hanViet":"HẬU BÁN","lesson":11,"ex":[["後半の試合が始まりました。","Hiệp hai của trận đấu đã bắt đầu."],["一年の後半に旅行へ行きます。","Tôi sẽ đi du lịch vào nửa cuối năm."],["本の後半がおもしろいです。","Nửa sau cuốn sách thú vị."],["後半は雨が降りました。","Nửa sau trời đã mưa."],["映画の後半で泣きました。","Tôi đã khóc ở nửa sau bộ phim."]]},{"word":"くぎ","reading":"くぎ","meaning":"Đinh","hanViet":"","lesson":11,"ex":[["くぎを打って、絵を掛けました。","Tôi đã đóng đinh và treo tranh."],["くぎが曲がっています。","Đinh bị cong."],["くぎを買いに店へ行きました。","Tôi đã đi cửa hàng mua đinh."],["くぎで指をけがしました。","Tôi bị thương ngón tay vì đinh."],["壁にくぎを打ちました。","Tôi đã đóng đinh vào tường."]]},{"word":"村人","reading":"むらびと","meaning":"Dân làng","hanViet":"THÔN NHÂN","lesson":11,"ex":[["村人は親切な人が多いです。","Dân làng có nhiều người tốt bụng."],["村人と一緒に祭りを楽しみました。","Tôi đã cùng dân làng vui lễ hội."],["村人が農作物を作っています。","Dân làng đang trồng nông sản."],["村人の話を聞きました。","Tôi đã nghe câu chuyện của dân làng."],["村人はみんな優しいです。","Dân làng ai cũng tốt bụng."]]},{"word":"かける","reading":"かける","meaning":"Bỏ chi phí","hanViet":"","lesson":11,"ex":[["日本語の勉強にお金をかけています。","Tôi đang bỏ tiền cho việc học tiếng Nhật."],["旅行に時間とお金をかけました。","Tôi đã bỏ thời gian và tiền cho chuyến du lịch."],["この仕事にたくさんの時間をかけました。","Tôi đã bỏ nhiều thời gian cho công việc này."],["お金をかけなくても、楽しめます。","Không cần bỏ tiền cũng có thể vui vẻ."],["子どもの教育にお金をかける人が多いです。","Có nhiều người bỏ tiền cho giáo dục của con."]]},{"word":"向き","reading":"むき","meaning":"Hướng, chiều; sự phù hợp","hanViet":"HƯỚNG","lesson":11,"ex":[["風の向きが変わりました。","Hướng gió đã thay đổi."],["この部屋は南向きです。","Căn phòng này hướng Nam."],["太陽の向きを見て、時間を考えました。","Nhìn hướng mặt trời, tôi suy ra thời gian."],["彼は先生向きの人です。","Anh ấy là người hợp làm thầy giáo."],["向きがわからなくて、迷いました。","Tôi không biết hướng nên đã lạc."]]},{"word":"抵抗","reading":"ていこう","meaning":"Sự kháng cự, chống đối; sức cản","hanViet":"ĐỂ KHÁNG","lesson":11,"ex":[["空気の抵抗で自転車が遅くなりました。","Vì sức cản không khí mà xe đạp chậm lại."],["彼はその計画に抵抗しました。","Anh ấy đã chống đối kế hoạch đó."],["抵抗する人が多かったです。","Có nhiều người chống đối."],["抵抗しても、決まったことは変わりません。","Dù chống đối, việc đã quyết cũng không thay đổi."],["水の抵抗で泳ぐのが大変です。","Vì sức cản của nước nên bơi rất vất vả."]]},{"word":"～層","reading":"～そう","meaning":"Lớp","hanViet":"TẰNG","lesson":11,"ex":[["若い層の人が多いです。","Có nhiều người thuộc tầng lớp trẻ."],["土の層が厚いです。","Lớp đất dày."],["このケーキは三層になっています。","Chiếc bánh này có ba lớp."],["社会のいろいろな層の人がいます。","Có người thuộc nhiều tầng lớp xã hội."],["年齢層によって、意見が違います。","Tùy theo độ tuổi, ý kiến khác nhau."]]},{"word":"蚕","reading":"かいこ","meaning":"Con tằm","hanViet":"TÀM","lesson":11,"ex":[["蚕は葉を食べます。","Tằm ăn lá."],["蚕を飼っている人がいます。","Có người đang nuôi tằm."],["蚕は白くて小さいです。","Tằm trắng và nhỏ."],["村で蚕を飼いました。","Tôi đã nuôi tằm ở làng."],["蚕の写真を見ました。","Tôi đã xem ảnh con tằm."]]},{"word":"火薬","reading":"かやく","meaning":"Thuốc súng","hanViet":"HỎA DƯỢC","lesson":11,"ex":[["火薬は危険です。","Thuốc súng nguy hiểm."],["火薬を使って山を壊しました。","Người ta dùng thuốc súng phá núi."],["火薬の発明について勉強しました。","Tôi đã học về phát minh thuốc súng."],["火薬を作る仕事は危険です。","Công việc làm thuốc súng nguy hiểm."],["昔、火薬は中国で作られました。","Ngày xưa, thuốc súng được làm ở Trung Quốc."]]},{"word":"製造する","reading":"せいぞうする","meaning":"Chế tạo","hanViet":"CHẾ TẠO","lesson":11,"ex":[["この会社は車を製造しています。","Công ty này đang chế tạo ô tô."],["日本で製造された製品は有名です。","Sản phẩm chế tạo ở Nhật nổi tiếng."],["新しい機械を製造しました。","Chúng tôi đã chế tạo máy mới."],["製造するのに時間がかかります。","Chế tạo tốn thời gian."],["工場でおもちゃを製造しています。","Ở nhà máy đang chế tạo đồ chơi."]]},{"word":"送る","reading":"おくる","meaning":"Gửi; trải qua (thời gian, cuộc sống)","hanViet":"TỐNG","lesson":11,"ex":[["友達に手紙を送りました。","Tôi đã gửi thư cho bạn."],["母にプレゼントを送ります。","Tôi sẽ gửi quà cho mẹ."],["日本で楽しい生活を送っています。","Tôi đang sống cuộc sống vui vẻ ở Nhật."],["忙しい毎日を送っています。","Tôi đang trải qua mỗi ngày bận rộn."],["メールで写真を送りました。","Tôi đã gửi ảnh bằng email."]]},{"word":"家内産業","reading":"かないさんぎょう","meaning":"Tiểu thủ công nghiệp","hanViet":"GIA NỘI SẢN NGHIỆP","lesson":11,"ex":[["村では家内産業が大切です。","Ở làng, tiểu thủ công nghiệp rất quan trọng."],["家内産業で生活している人がいます。","Có người sống bằng tiểu thủ công nghiệp."],["家内産業について勉強しました。","Tôi đã học về tiểu thủ công nghiệp."],["家内産業の製品は有名です。","Sản phẩm tiểu thủ công nghiệp nổi tiếng."],["家内産業で働く人が多いです。","Có nhiều người làm việc trong tiểu thủ công nghiệp."]]},{"word":"年貢","reading":"ねんぐ","meaning":"Địa tô, tô","hanViet":"NIÊN CỐNG","lesson":11,"ex":[["昔の村人は年貢を払いました。","Dân làng ngày xưa đã nộp tô."],["年貢は米で払いました。","Tô được nộp bằng gạo."],["年貢が高くて、村人は困りました。","Tô cao nên dân làng khổ sở."],["年貢について歴史の本で読みました。","Tôi đã đọc về tô trong sách lịch sử."],["年貢を払うのは大変でした。","Nộp tô rất vất vả."]]},{"word":"期待する","reading":"きたいする","meaning":"Kỳ vọng, hy vọng","hanViet":"KÌ ĐÃI","lesson":11,"ex":[["先生は学生に期待しています。","Thầy giáo kỳ vọng vào học sinh."],["期待していた映画を見ました。","Tôi đã xem bộ phim mong đợi."],["彼の成功を期待しています。","Tôi kỳ vọng vào thành công của anh ấy."],["期待するほど、結果はよくありませんでした。","Không như kỳ vọng, kết quả không tốt."],["期待して待っています。","Tôi đang mong chờ."]]},{"word":"地","reading":"ち","meaning":"Đất đai","hanViet":"ĐỊA","lesson":11,"ex":[["この地は米が有名です。","Vùng đất này nổi tiếng về gạo."],["地に座って話しました。","Chúng tôi ngồi xuống đất nói chuyện."],["ふるさとの地は懐かしいです。","Vùng đất quê hương khiến tôi nhớ nhung."],["地で農作物を作っています。","Trên đất này, người ta trồng nông sản."],["この地に住んで十年になります。","Tôi sống ở vùng đất này đã mười năm."]]},{"word":"前半","reading":"ぜんはん","meaning":"Nửa đầu","hanViet":"TIỀN BÁN","lesson":11,"ex":[["前半の試合が終わりました。","Hiệp một của trận đấu đã kết thúc."],["一年の前半に試験があります。","Nửa đầu năm có kỳ thi."],["本の前半が難しいです。","Nửa đầu cuốn sách khó."],["前半は天気がよかったです。","Nửa đầu thời tiết tốt."],["映画の前半で寝てしまいました。","Tôi đã ngủ mất ở nửa đầu bộ phim."]]},{"word":"やってくる","reading":"やってくる","meaning":"Đến, kéo đến","hanViet":"","lesson":11,"ex":[["春になると、鳥が山からやってきます。","Khi xuân đến, chim bay đến từ núi."],["毎年夏に、たくさんの人がこの村にやってきます。","Mỗi năm vào mùa hè, rất nhiều người đến làng này."],["夕方になると、子どもが公園にやってきます。","Khi chiều tối đến, trẻ con kéo đến công viên."],["大きな船が港にやってきました。","Một con tàu lớn đã đến cảng."],["冬になると、雪が北からやってきます。","Khi mùa đông đến, tuyết từ phương Bắc kéo đến."]]},{"word":"住み着く","reading":"すみつく","meaning":"Định cư","hanViet":"TRỤ TRỨ","lesson":11,"ex":[["田中さんは京都に住み着きました。","Anh Tanaka đã định cư ở Kyoto."],["鳥はこの森に住み着いています。","Chim đã định cư trong khu rừng này."],["私の祖父はこの町に住み着いて、五十年になります。","Ông tôi đã định cư ở thị trấn này được 50 năm."],["猫が庭に住み着いて、もう帰りません。","Con mèo đã ở lại trong sân và không về nữa."],["外国から来た人はこの村に住み着きました。","Người từ nước ngoài đến đã định cư ở làng này."]]},{"word":"一族","reading":"いちぞく","meaning":"Gia tộc","hanViet":"NHẤT TỘC","lesson":11,"ex":[["昔、この村に大きな一族が住んでいました。","Ngày xưa, có một gia tộc lớn sống ở làng này."],["一族の人はみんなで祭りに行きました。","Cả gia tộc cùng nhau đi lễ hội."],["この一族の歴史はとても古いです。","Lịch sử của gia tộc này rất lâu đời."],["一族の家は山の近くにあります。","Nhà của gia tộc ở gần núi."],["昔、一族の人がこの城を作りました。","Ngày xưa, người của gia tộc đã xây tòa thành này."]]},{"word":"～城","reading":"～じょう","meaning":"Thành, lâu đài ~","hanViet":"THÀNH","lesson":11,"ex":[["大阪城は日本の有名な城です。","Thành Osaka là tòa thành nổi tiếng của Nhật Bản."],["去年、大阪城を見に行きました。","Năm ngoái, tôi đã đi ngắm thành Osaka."],["姫路城は白くて美しい城です。","Thành Himeji là tòa thành trắng và đẹp."],["大阪城の近くに大きな公園があります。","Gần thành Osaka có một công viên lớn."],["姫路城は世界で有名な城です。","Thành Himeji là tòa thành nổi tiếng trên thế giới."]]},{"word":"城","reading":"しろ","meaning":"Thành, lâu đài","hanViet":"THÀNH","lesson":11,"ex":[["山の上に古い城があります。","Trên núi có một tòa thành cổ."],["昔、権力者はこの城に住んでいました。","Ngày xưa, người có quyền lực sống trong tòa thành này."],["城の中に博物館があります。","Trong thành có một bảo tàng."],["この城は五百年前に作られました。","Tòa thành này được xây cách đây 500 năm."],["子どもは城の歴史が好きです。","Trẻ con thích lịch sử của tòa thành."]]},{"word":"掘り当てる","reading":"ほりあてる","meaning":"Đào vàng, v.v","hanViet":"QUẬT ĐƯƠNG","lesson":11,"ex":[["村の人は山で水を掘り当てました。","Người dân làng đã đào trúng nước ở núi."],["昔の人はこの土地で金を掘り当てました。","Người xưa đã đào trúng vàng ở vùng đất này."],["会社は村で温泉を掘り当てました。","Công ty đã đào trúng suối nước nóng ở làng."],["水を掘り当てるのは難しい仕事です。","Việc đào trúng nước là công việc khó."],["金を掘り当てた人は有名になりました。","Người đào trúng vàng đã trở nên nổi tiếng."]]},{"word":"権力者","reading":"けんりょくしゃ","meaning":"Người có quyền lực","hanViet":"QUYỀN LỰC GIẢ","lesson":11,"ex":[["昔の権力者は大きな城に住んでいました。","Người có quyền lực ngày xưa sống trong tòa thành lớn."],["権力者は国の政治を決めます。","Người có quyền lực quyết định chính trị của đất nước."],["その権力者は人にとても優しかったです。","Người có quyền lực đó rất tốt với mọi người."],["権力者の家は町で一番大きいです。","Nhà của người có quyền lực là lớn nhất trong thị trấn."],["歴史の本に有名な権力者が出ます。","Trong sách lịch sử xuất hiện những người có quyền lực nổi tiếng."]]},{"word":"飢饉","reading":"ききん","meaning":"Nạn đói","hanViet":"CƠ CẬN","lesson":11,"ex":[["昔、雨が少なくて、飢饉がありました。","Ngày xưa, mưa ít nên đã xảy ra nạn đói."],["飢饉のとき、人は食べ物がなくて困りました。","Khi nạn đói xảy ra, người dân không có thức ăn nên khốn khổ."],["歴史の本に飢饉のことが書いてあります。","Trong sách lịch sử có viết về nạn đói."],["飢饉で村の人がたくさん死にました。","Vì nạn đói, nhiều người dân làng đã chết."],["今は飢饉がなくて、食べ物がたくさんあります。","Bây giờ không còn nạn đói, thức ăn rất nhiều."]]},{"word":"～軒","reading":"～けん","meaning":"Trợ số từ đếm nhà","hanViet":"HIÊN","lesson":11,"ex":[["この村に家が三軒あります。","Làng này có ba ngôi nhà."],["去年、この町に新しい家が十軒できました。","Năm ngoái, thị trấn này đã có thêm mười ngôi nhà mới."],["私の家の近くに店が二軒あります。","Gần nhà tôi có hai cửa hàng."],["山の近くに小さい家が五軒あります。","Gần núi có năm ngôi nhà nhỏ."],["この道に家が何軒ありますか。","Trên con đường này có bao nhiêu ngôi nhà?"]]},{"word":"数百人","reading":"すうひゃくにん","meaning":"Vài trăm người","hanViet":"SỔ BÁCH NHÂN","lesson":11,"ex":[["祭りに数百人が来ました。","Vài trăm người đã đến lễ hội."],["この学校に数百人の学生がいます。","Trường này có vài trăm học sinh."],["数百人が公園に集まりました。","Vài trăm người đã tụ tập ở công viên."],["毎年、数百人がこの山に来ます。","Mỗi năm, vài trăm người đến ngọn núi này."],["映画館に数百人が入りました。","Vài trăm người đã vào rạp chiếu phim."]]},{"word":"一人残らず","reading":"ひとりのこらず","meaning":"Không sót một ai, tất cả mọi người","hanViet":"NHẤT NHÂN TÀN","lesson":11,"ex":[["村の人は一人残らず祭りに行きました。","Người dân làng không sót một ai đều đi lễ hội."],["学生は一人残らず試験を受けました。","Học sinh không sót một ai đều đã thi."],["家族は一人残らず元気です。","Cả gia đình không thiếu một ai đều khỏe mạnh."],["社員は一人残らず会議に出ました。","Nhân viên không sót một ai đều đã dự họp."],["子どもは一人残らず学校に来ました。","Trẻ con không thiếu một em nào đều đã đến trường."]]},{"word":"消える","reading":"きえる","meaning":"Biến mất; (đèn, điện) tắt","hanViet":"TIÊU","lesson":11,"ex":[["朝になると、星が消えます。","Khi sáng đến, sao biến mất."],["電気が消えて、部屋が暗くなりました。","Điện tắt, phòng trở nên tối."],["雪が消えて、春が来ました。","Tuyết tan biến, mùa xuân đến."],["昔の村は今は消えました。","Ngôi làng ngày xưa giờ đã biến mất."],["電車の音がだんだん消えました。","Tiếng tàu điện dần dần biến mất."]]},{"word":"保管する","reading":"ほかんする","meaning":"Bảo quản","hanViet":"BẢO QUẢN","lesson":11,"ex":[["パスポートは家で保管してください。","Hãy bảo quản hộ chiếu ở nhà."],["大切な手紙は箱に保管します。","Tôi bảo quản những lá thư quan trọng trong hộp."],["薬は冷蔵庫で保管します。","Tôi bảo quản thuốc trong tủ lạnh."],["古い写真は箱に保管しています。","Tôi đang bảo quản những bức ảnh cũ trong hộp."],["食べ物は冷蔵庫で保管しなければなりません。","Thức ăn phải được bảo quản trong tủ lạnh."]]},{"word":"兆","reading":"ちょう","meaning":"Nghìn tỷ","hanViet":"TRIỆU","lesson":11,"ex":[["空には一兆の星があるそうです。","Nghe nói trên trời có một nghìn tỷ ngôi sao."],["一兆はとても大きな数です。","Một nghìn tỷ là một con số rất lớn."],["一兆円はとても大きなお金です。","Một nghìn tỷ yên là số tiền rất lớn."],["この国は一年に一兆円を使います。","Đất nước này dùng một nghìn tỷ yên trong một năm."],["星の数は一兆ぐらいです。","Số sao khoảng một nghìn tỷ."]]},{"word":"積もる","reading":"つもる","meaning":"Tuyết tích lại","hanViet":"TÍCH","lesson":11,"ex":[["冬に雪がたくさん積もります。","Vào mùa đông, tuyết tích lại rất nhiều."],["山に雪が積もって、白くなりました。","Tuyết tích trên núi, núi trở nên trắng xóa."],["きのう雪が積もったので、電車が遅れました。","Hôm qua tuyết tích lại nên tàu điện đã đến trễ."],["庭に雪が積もっています。","Tuyết đang tích lại trong sân."],["北の町では雪がとてもたくさん積もります。","Ở thị trấn phía Bắc, tuyết tích lại rất nhiều."]]},{"word":"気候","reading":"きこう","meaning":"Khí hậu","hanViet":"KHÍ HẬU","lesson":11,"ex":[["日本の気候は春と秋がいいです。","Khí hậu Nhật Bản đẹp vào mùa xuân và mùa thu."],["この町の気候は温暖です。","Khí hậu thị trấn này ấm áp."],["北の町の気候は冬にとても寒いです。","Khí hậu thị trấn phương Bắc vào mùa đông rất lạnh."],["気候がいいので、野菜がよくできます。","Vì khí hậu tốt nên rau củ mọc tốt."],["外国の気候について調べました。","Tôi đã tìm hiểu về khí hậu nước ngoài."]]},{"word":"観光案内","reading":"かんこうあんない","meaning":"Thông tin hướng dẫn du lịch","hanViet":"QUAN QUANG ÁN NỘI","lesson":11,"ex":[["駅に観光案内があります。","Ở ga có thông tin hướng dẫn du lịch."],["観光案内で地図をもらいました。","Tôi đã nhận bản đồ ở chỗ hướng dẫn du lịch."],["観光案内の人が町を案内します。","Người ở chỗ hướng dẫn du lịch dẫn đi tham quan thị trấn."],["観光案内は午前九時から午後五時までです。","Hướng dẫn du lịch mở từ 9 giờ sáng đến 5 giờ chiều."],["京都の観光案内でホテルを予約しました。","Tôi đã đặt khách sạn ở chỗ hướng dẫn du lịch Kyoto."]]},{"word":"観光地","reading":"かんこうち","meaning":"Điểm du lịch","hanViet":"QUAN QUANG ĐỊA","lesson":11,"ex":[["京都は日本の有名な観光地です。","Kyoto là điểm du lịch nổi tiếng của Nhật Bản."],["この観光地には毎年たくさんの人が来ます。","Điểm du lịch này mỗi năm có rất nhiều người đến."],["観光地の近くにホテルがたくさんあります。","Gần điểm du lịch có rất nhiều khách sạn."],["あした観光地に行って、たくさん歩きます。","Ngày mai tôi đi điểm du lịch và đi bộ nhiều."],["この観光地は春に一番きれいです。","Điểm du lịch này đẹp nhất vào mùa xuân."]]},{"word":"演奏会","reading":"えんそうかい","meaning":"Buổi biểu diễn, buổi trình diễn","hanViet":"DIỄN TẤU HỘI","lesson":12,"ex":[["あした学校で演奏会があります。","Ngày mai ở trường có buổi hòa nhạc."],["演奏会でピアノを聞きました。","Tôi đã nghe piano ở buổi hòa nhạc."],["演奏会にはたくさんの人が来ました。","Buổi hòa nhạc có rất nhiều người đến."],["友達と演奏会に行きました。","Tôi đã đi hòa nhạc với bạn."],["演奏会のチケットを買いました。","Tôi đã mua vé buổi hòa nhạc."]]},{"word":"報告書","reading":"ほうこくしょ","meaning":"Bản báo cáo","hanViet":"BÁO CÁO THƯ","lesson":12,"ex":[["報告書を書きました。","Tôi đã viết bản báo cáo."],["先生に報告書を出しました。","Tôi đã nộp bản báo cáo cho thầy."],["報告書はあしたまでに出します。","Tôi sẽ nộp bản báo cáo trước ngày mai."],["報告書の内容は会社の仕事についてです。","Nội dung bản báo cáo là về công việc của công ty."],["報告書を書くのは難しいです。","Viết báo cáo thì khó."]]},{"word":"あくび","reading":"あくび","meaning":"Ngáp","hanViet":"","lesson":12,"ex":[["授業のとき、あくびが出ました。","Trong giờ học, tôi đã ngáp."],["眠いので、あくびが出ます。","Vì buồn ngủ nên tôi ngáp."],["あくびをしたら、友達が笑いました。","Khi tôi ngáp, bạn tôi đã cười."],["映画を見て、あくびが出ました。","Xem phim, tôi đã ngáp."],["電車の中であくびが出ました。","Trên tàu điện, tôi đã ngáp."]]},{"word":"犯人","reading":"はんにん","meaning":"Kẻ tội phạm, hung thủ","hanViet":"PHẠM NHÂN","lesson":12,"ex":[["警察は犯人を探しています。","Cảnh sát đang tìm hung thủ."],["犯人は夜に逃げました。","Hung thủ đã trốn đi vào ban đêm."],["警察はまだ犯人を見つけていません。","Cảnh sát vẫn chưa tìm ra hung thủ."],["テレビで犯人のニュースを見ました。","Tôi đã xem tin về hung thủ trên TV."],["犯人は店のお金を盗みました。","Hung thủ đã lấy trộm tiền của cửa hàng."]]},{"word":"追いかける","reading":"おいかける","meaning":"Đuổi theo","hanViet":"TRUY","lesson":12,"ex":[["警察は犯人を追いかけました。","Cảnh sát đã đuổi theo hung thủ."],["犬が猫を追いかけています。","Chó đang đuổi theo mèo."],["子どもは友達を追いかけて走りました。","Trẻ con vừa đuổi theo bạn vừa chạy."],["バスを追いかけましたが、乗り遅れました。","Tôi đã đuổi theo xe buýt nhưng bị lỡ xe."],["駅まで友達を追いかけました。","Tôi đã đuổi theo bạn đến tận ga."]]},{"word":"作業","reading":"さぎょう","meaning":"Công việc","hanViet":"TÁC NGHIỆP","lesson":12,"ex":[["作業は午前九時に始まります。","Công việc bắt đầu lúc 9 giờ sáng."],["作業の前に、手を洗います。","Trước khi làm việc, tôi rửa tay."],["この作業はとても難しいです。","Công việc này rất khó."],["作業が終わったら、家に帰ります。","Khi công việc xong, tôi về nhà."],["友達が作業を手伝ってくれました。","Bạn tôi đã giúp tôi làm việc."]]},{"word":"スープ","reading":"スープ","meaning":"Súp","hanViet":"","lesson":12,"ex":[["昼にスープを飲みました。","Trưa tôi đã uống súp."],["このスープはとてもおいしいです。","Món súp này rất ngon."],["スープに野菜を加えました。","Tôi đã thêm rau vào súp."],["寒い日にスープを飲むと、元気になります。","Ngày lạnh uống súp thì khỏe ra."],["レストランでスープを食べました。","Tôi đã ăn súp ở nhà hàng."]]},{"word":"こぼす","reading":"こぼす","meaning":"Làm đổ","hanViet":"","lesson":12,"ex":[["水をこぼしました。","Tôi đã làm đổ nước."],["コーヒーを服にこぼして、困りました。","Tôi làm đổ cà phê lên áo nên khốn khổ."],["子どもが牛乳をこぼしました。","Đứa trẻ đã làm đổ sữa."],["スープをこぼさないでください。","Xin đừng làm đổ súp."],["お茶をこぼしたので、服を洗いました。","Vì làm đổ trà nên tôi đã giặt áo."]]},{"word":"シャッター","reading":"シャッター","meaning":"Cửa cuốn","hanViet":"","lesson":12,"ex":[["店のシャッターが閉まっています。","Cửa cuốn của cửa hàng đang đóng."],["夜にシャッターを閉めます。","Ban đêm tôi đóng cửa cuốn."],["シャッターが壊れて、開きません。","Cửa cuốn hỏng nên không mở được."],["朝にシャッターを開けます。","Buổi sáng tôi mở cửa cuốn."],["シャッターの音が大きいです。","Tiếng cửa cuốn to."]]},{"word":"スプレー","reading":"スプレー","meaning":"Bình xịt","hanViet":"","lesson":12,"ex":[["スプレーで水をかけます。","Tôi xịt nước bằng bình xịt."],["花にスプレーで水をかけました。","Tôi đã xịt nước cho hoa bằng bình xịt."],["このスプレーは部屋の掃除に使います。","Bình xịt này dùng để dọn phòng."],["スプレーを買いました。","Tôi đã mua bình xịt."],["スプレーが壊れました。","Bình xịt đã hỏng."]]},{"word":"落書きする","reading":"らくがきする","meaning":"Vẽ bậy, viết bậy","hanViet":"LẠC THƯ","lesson":12,"ex":[["壁に落書きしてはいけません。","Không được vẽ bậy lên tường."],["子どもが壁に落書きしました。","Đứa trẻ đã vẽ bậy lên tường."],["駅の壁に落書きがあります。","Trên tường ga có hình vẽ bậy."],["ここで落書きしないでください。","Xin đừng vẽ bậy ở đây."],["落書きを消しました。","Tôi đã xóa hình vẽ bậy."]]},{"word":"夜中","reading":"よなか","meaning":"Nửa đêm","hanViet":"DẠ TRUNG","lesson":12,"ex":[["夜中に電話が鳴りました。","Nửa đêm, điện thoại reo."],["夜中に起きました。","Nửa đêm tôi đã thức dậy."],["夜中に外を歩いてはいけません。","Nửa đêm không được đi bộ bên ngoài."],["夜中に雨が降りました。","Nửa đêm trời đã mưa."],["夜中に本を読みました。","Nửa đêm tôi đã đọc sách."]]},{"word":"日","reading":"ひ","meaning":"Ánh sáng mặt trời","hanViet":"NHẬT","lesson":12,"ex":[["日が強くて、暑いです。","Nắng mạnh nên nóng."],["日の光がきれいです。","Ánh nắng đẹp."],["冬は日が弱いです。","Mùa đông nắng yếu."],["日に当たると、体が温かいです。","Khi nắng chiếu vào, cơ thể ấm áp."],["春の日は暖かいです。","Nắng mùa xuân ấm áp."]]},{"word":"暮らす","reading":"くらす","meaning":"Sống, sinh sống","hanViet":"MỘ","lesson":12,"ex":[["田中さんは京都で暮らしています。","Anh Tanaka đang sống ở Kyoto."],["私は一人で暮らしています。","Tôi đang sống một mình."],["村で静かに暮らしたいです。","Tôi muốn sống yên tĩnh ở làng."],["祖父は山の近くで暮らしています。","Ông tôi đang sống gần núi."],["外国で暮らすのは楽しいです。","Sống ở nước ngoài thật vui."]]},{"word":"書道","reading":"しょどう","meaning":"Thư pháp","hanViet":"THƯ ĐẠO","lesson":12,"ex":[["書道を習っています。","Tôi đang học thư pháp."],["学校で書道の授業があります。","Ở trường có giờ học thư pháp."],["書道で漢字を書きます。","Tôi viết chữ Hán bằng thư pháp."],["書道の先生は優しいです。","Thầy dạy thư pháp rất tốt."],["書道は日本の文化です。","Thư pháp là văn hóa Nhật Bản."]]},{"word":"蛍光灯","reading":"けいこうとう","meaning":"Bóng đèn huỳnh quang","hanViet":"HUỲNH QUANG ĐĂNG","lesson":12,"ex":[["部屋の蛍光灯が明るいです。","Đèn huỳnh quang trong phòng sáng."],["蛍光灯が壊れました。","Đèn huỳnh quang đã hỏng."],["蛍光灯を新しくしました。","Tôi đã thay đèn huỳnh quang mới."],["夜に蛍光灯をつけます。","Ban đêm tôi bật đèn huỳnh quang."],["蛍光灯の下で本を読みます。","Tôi đọc sách dưới đèn huỳnh quang."]]},{"word":"メニュー","reading":"メニュー","meaning":"Thực đơn","hanViet":"","lesson":12,"ex":[["メニューを見てください。","Xin hãy xem thực đơn."],["メニューにスープがあります。","Trong thực đơn có súp."],["メニューから魚を選びました。","Tôi đã chọn cá từ thực đơn."],["メニューについて店員に聞きました。","Tôi đã hỏi nhân viên về thực đơn."],["新しいメニューができました。","Thực đơn mới đã ra mắt."]]},{"word":"バイク","reading":"バイク","meaning":"Xe máy","hanViet":"","lesson":12,"ex":[["バイクで学校に行きます。","Tôi đi học bằng xe máy."],["バイクが速いです。","Xe máy nhanh."],["バイクを買いました。","Tôi đã mua xe máy."],["バイクに乗るのは楽しいです。","Lái xe máy thật vui."],["バイクの音が大きいです。","Tiếng xe máy to."]]},{"word":"目覚まし時計","reading":"めざましどけい","meaning":"Đồng hồ báo thức","hanViet":"MỤC GIÁC THỜI KẾ","lesson":12,"ex":[["目覚まし時計が鳴りました。","Đồng hồ báo thức đã reo."],["目覚まし時計を午前六時にかけました。","Tôi đã đặt báo thức lúc 6 giờ sáng."],["目覚まし時計が壊れて、起きませんでした。","Đồng hồ báo thức hỏng nên tôi đã không dậy được."],["目覚まし時計はベッドの近くにあります。","Đồng hồ báo thức ở gần giường."],["新しい目覚まし時計を買いました。","Tôi đã mua đồng hồ báo thức mới."]]},{"word":"鳴る","reading":"なる","meaning":"Reng, đổ chuông","hanViet":"MINH","lesson":12,"ex":[["電話が鳴りました。","Điện thoại đã reo."],["チャイムが鳴ります。","Chuông reo."],["電車の中で電話が鳴って、困りました。","Điện thoại reo trên tàu điện nên tôi khốn khổ."],["目覚まし時計が鳴ったら、起きます。","Khi đồng hồ báo thức reo, tôi dậy."],["学校のチャイムが鳴りました。","Chuông trường đã reo."]]},{"word":"温暖","reading":"おんだん","meaning":"Ấm áp","hanViet":"ÔN NOÃN","lesson":12,"ex":[["温暖な国に旅行に行きたいです。","Tôi muốn đi du lịch đến đất nước ấm áp."],["温暖な町に住みたいです。","Tôi muốn sống ở thị trấn ấm áp."],["ここは冬も温暖です。","Nơi này mùa đông cũng ấm áp."],["温暖な気候で野菜がよくできます。","Nhờ khí hậu ấm áp mà rau củ mọc tốt."],["南の国は温暖です。","Đất nước phương Nam ấm áp."]]},{"word":"家事","reading":"かじ","meaning":"Việc nhà","hanViet":"GIA SỰ","lesson":12,"ex":[["家事を手伝います。","Tôi giúp việc nhà."],["お母さんは毎日家事をします。","Mẹ ngày nào cũng làm việc nhà."],["家事は大変です。","Việc nhà vất vả."],["家事をしながら、音楽を聞きます。","Vừa làm việc nhà vừa nghe nhạc."],["家事をしないで、遊びました。","Không làm việc nhà, tôi đã đi chơi."]]},{"word":"ぐっすり","reading":"ぐっすり","meaning":"Ngủ say, ngon","hanViet":"","lesson":12,"ex":[["きのうはぐっすり寝ました。","Hôm qua tôi đã ngủ rất say."],["旅行の後で、ぐっすり寝ました。","Sau chuyến du lịch, tôi đã ngủ rất say."],["ぐっすり寝て、元気になりました。","Ngủ say nên tôi đã khỏe ra."],["子どもはぐっすり寝ています。","Đứa trẻ đang ngủ say."],["疲れたので、ぐっすり寝ました。","Vì mệt nên tôi đã ngủ say."]]},{"word":"迷惑","reading":"めいわく","meaning":"Phiền, phiền hà","hanViet":"MÊ HOẶC","lesson":12,"ex":[["夜中に電話して、迷惑をかけました。","Nửa đêm gọi điện nên đã làm phiền."],["迷惑をかけないでください。","Xin đừng làm phiền."],["大きな音は近所に迷惑です。","Tiếng ồn lớn làm phiền hàng xóm."],["電車で電話をするのは迷惑です。","Gọi điện trên tàu điện làm phiền người khác."],["迷惑をかけて、すみません。","Xin lỗi đã làm phiền."]]},{"word":"風邪薬","reading":"かぜぐすり","meaning":"Thuốc cảm","hanViet":"PHONG TÀ DƯỢC","lesson":12,"ex":[["風邪薬を飲みました。","Tôi đã uống thuốc cảm."],["風邪薬を買ってきました。","Tôi đã mua thuốc cảm về."],["風邪薬は店で買います。","Thuốc cảm mua ở cửa hàng."],["風邪薬を飲んで、寝ました。","Uống thuốc cảm rồi tôi đi ngủ."],["風邪薬の名前を教えてください。","Hãy cho tôi biết tên thuốc cảm."]]},{"word":"乗り遅れる","reading":"のりおくれる","meaning":"Trễ xe buýt, tàu, v.v.","hanViet":"THỪA TRÌ","lesson":12,"ex":[["電車に乗り遅れました。","Tôi đã lỡ tàu điện."],["バスに乗り遅れて、遅刻しました。","Lỡ xe buýt nên tôi đã đến muộn."],["朝、電車に乗り遅れそうです。","Sáng nay, tôi suýt lỡ tàu điện."],["乗り遅れないように、午前六時に起きます。","Để không lỡ xe, tôi dậy lúc 6 giờ sáng."],["きのうも電車に乗り遅れました。","Hôm qua tôi cũng lỡ tàu điện."]]},{"word":"苦情","reading":"くじょう","meaning":"Lời than phiền, lời phàn nàn","hanViet":"KHỔ TÌNH","lesson":12,"ex":[["苦情を言いました。","Tôi đã nói lời phàn nàn."],["店に苦情を言いました。","Tôi đã phàn nàn với cửa hàng."],["苦情が多いです。","Có nhiều lời phàn nàn."],["苦情を聞きました。","Tôi đã nghe lời phàn nàn."],["近所の人から苦情が来ました。","Có lời phàn nàn từ hàng xóm."]]},{"word":"遅く","reading":"おそく","meaning":"Trễ, muộn","hanViet":"TRÌ","lesson":12,"ex":[["きのうは遅く帰りました。","Hôm qua tôi về muộn."],["遅くまで本を読みました。","Tôi đã đọc sách đến muộn."],["遅く寝ると、朝起きません。","Ngủ muộn thì sáng không dậy được."],["夜遅くに電話が来ました。","Đêm khuya có điện thoại gọi đến."],["遅くまで仕事をしました。","Tôi đã làm việc đến muộn."]]},{"word":"帰り","reading":"かえり","meaning":"Về nhà","hanViet":"QUY","lesson":12,"ex":[["帰りに店に寄りました。","Trên đường về tôi đã ghé cửa hàng."],["帰りは電車で帰ります。","Lúc về tôi đi tàu điện về."],["学校の帰りに公園に行きました。","Trên đường từ trường về, tôi đã đi công viên."],["帰りが遅くなりました。","Tôi về muộn."],["帰りに友達に会いました。","Trên đường về tôi đã gặp bạn."]]},{"word":"あまり","reading":"あまり","meaning":"Không ~ lắm","hanViet":"","lesson":12,"ex":[["あまり食べませんでした。","Tôi đã không ăn nhiều lắm."],["この店にはあまり行きません。","Tôi ít đến cửa hàng này."],["あまりお金がありません。","Tôi không có nhiều tiền lắm."],["日本語があまり話せません。","Tôi không nói tiếng Nhật giỏi lắm."],["あまり寝ませんでした。","Tôi đã không ngủ nhiều lắm."]]},{"word":"どうしても","reading":"どうしても","meaning":"Kiểu gì cũng, thế nào cũng","hanViet":"","lesson":12,"ex":[["どうしても行きたかったです。","Tôi kiểu gì cũng muốn đi."],["この漢字はどうしても覚えられません。","Chữ Hán này kiểu gì tôi cũng không nhớ được."],["どうしてもこの本がほしいです。","Kiểu gì tôi cũng muốn cuốn sách này."],["どうしても電話しなければなりません。","Kiểu gì tôi cũng phải gọi điện."],["どうしてもあした行きたいです。","Kiểu gì ngày mai tôi cũng muốn đi."]]},{"word":"自治会","reading":"じちかい","meaning":"Hội tự quản trong cộng đồng dân cư","hanViet":"TỰ TRÌ HỘI","lesson":12,"ex":[["自治会の会議があります。","Có cuộc họp của hội tự quản."],["自治会の人が来ました。","Người của hội tự quản đã đến."],["自治会で祭りをします。","Hội tự quản tổ chức lễ hội."],["自治会の会長は田中さんです。","Chủ tịch hội tự quản là anh Tanaka."],["自治会に入りました。","Tôi đã gia nhập hội tự quản."]]},{"word":"役員","reading":"やくいん","meaning":"Ủy viên ban quản trị","hanViet":"DỊCH VIÊN","lesson":12,"ex":[["役員は五人です。","Ban quản trị có 5 người."],["田中さんは自治会の役員です。","Anh Tanaka là ủy viên hội tự quản."],["役員の会議があります。","Có cuộc họp ban quản trị."],["役員を選びました。","Tôi đã chọn ủy viên."],["役員は忙しいです。","Ủy viên rất bận."]]},{"word":"DVD","reading":"ディーブイディー","meaning":"DVD","hanViet":"","lesson":12,"ex":[["DVDを見ました。","Tôi đã xem DVD."],["DVDを借りました。","Tôi đã thuê DVD."],["DVDで映画を見ました。","Tôi đã xem phim bằng DVD."],["このDVDは新しいです。","DVD này mới."],["DVDを友達に貸しました。","Tôi đã cho bạn mượn DVD."]]},{"word":"座談会","reading":"ざだんかい","meaning":"Tọa đàm bàn tròn","hanViet":"TỌA ĐÀM HỘI","lesson":12,"ex":[["座談会がありました。","Đã có buổi tọa đàm."],["座談会で話しました。","Tôi đã nói chuyện ở buổi tọa đàm."],["座談会に参加しました。","Tôi đã tham gia tọa đàm."],["座談会は午後二時からです。","Tọa đàm bắt đầu từ 2 giờ chiều."],["座談会で意見を言いました。","Tôi đã nêu ý kiến ở buổi tọa đàm."]]},{"word":"カルチャーショック","reading":"カルチャーショック","meaning":"Sốc văn hóa","hanViet":"","lesson":12,"ex":[["日本でカルチャーショックを受けました。","Tôi đã bị sốc văn hóa ở Nhật."],["カルチャーショックは大変です。","Sốc văn hóa rất vất vả."],["外国でカルチャーショックがありました。","Ở nước ngoài tôi đã gặp sốc văn hóa."],["カルチャーショックについて話しました。","Tôi đã nói về sốc văn hóa."],["外国に行って、カルチャーショックを受けました。","Đi nước ngoài, tôi đã bị sốc văn hóa."]]},{"word":"それまで","reading":"それまで","meaning":"Cho đến khi đó, trước đây","hanViet":"","lesson":12,"ex":[["それまで、私は日本語を勉強しませんでした。","Cho đến khi đó, tôi chưa học tiếng Nhật."],["それまで、この町は静かでした。","Cho đến khi đó, thị trấn này yên tĩnh."],["それまで、彼は学生でした。","Cho đến khi đó, anh ấy là học sinh."],["それまで、電車がありませんでした。","Cho đến khi đó, chưa có tàu điện."],["それまで、私は一人で暮らしていました。","Cho đến khi đó, tôi sống một mình."]]},{"word":"騒々しい","reading":"そうぞうしい","meaning":"Ồn ào","hanViet":"TAO","lesson":12,"ex":[["町は騒々しいです。","Thị trấn ồn ào."],["祭りの日は町が騒々しいです。","Ngày lễ hội, thị trấn ồn ào."],["騒々しい音が聞こえます。","Nghe thấy tiếng ồn ào."],["駅は朝から騒々しいです。","Ga ồn ào từ buổi sáng."],["騒々しいので、勉強できません。","Vì ồn ào nên tôi không học được."]]},{"word":"アナウンス","reading":"アナウンス","meaning":"Phát thanh thông báo","hanViet":"","lesson":12,"ex":[["アナウンスが聞こえました。","Tôi đã nghe thấy thông báo."],["駅でアナウンスがありました。","Ở ga có thông báo."],["アナウンスを聞きました。","Tôi đã nghe thông báo."],["アナウンスを聞いて、電車に乗りました。","Nghe thông báo, tôi đã lên tàu điện."],["電車のアナウンスは日本語です。","Thông báo trên tàu điện bằng tiếng Nhật."]]},{"word":"奥様","reading":"おくさま","meaning":"Bà nội trợ, bà vợ","hanViet":"ÁO DẠNG","lesson":12,"ex":[["田中さんの奥様は優しいです。","Vợ anh Tanaka rất tốt."],["奥様は家事をします。","Bà vợ làm việc nhà."],["奥様に会いました。","Tôi đã gặp bà vợ anh ấy."],["奥様は毎日料理を作ります。","Bà vợ ngày nào cũng nấu ăn."],["山田さんの奥様は先生です。","Vợ anh Yamada là giáo viên."]]},{"word":"おいでいただく","reading":"おいでいただく","meaning":"Đến dự, góp mặt","hanViet":"","lesson":12,"ex":[["あした、おいでいただきたいです。","Ngày mai, tôi mong anh chị đến dự."],["先生においでいただきました。","Thầy đã đến dự."],["座談会においでいただきたいです。","Tôi mong anh chị đến dự buổi tọa đàm."],["先生においでいただいて、うれしかったです。","Thầy đến dự nên tôi rất vui."],["あしたの座談会においでいただけますか。","Ngày mai anh chị có thể đến dự buổi tọa đàm không?"]]},{"word":"苦労","reading":"くろう","meaning":"Khó khăn, vất vả","hanViet":"KHỔ LAO","lesson":12,"ex":[["苦労が多いです。","Có nhiều khó khăn."],["苦労して、日本語を勉強しました。","Tôi đã vất vả học tiếng Nhật."],["苦労を知っています。","Tôi biết sự vất vả đó."],["外国で苦労しました。","Tôi đã vất vả ở nước ngoài."],["苦労した後で、元気になりました。","Sau khi vất vả, tôi đã khỏe lại."]]},{"word":"中略","reading":"ちゅうりゃく","meaning":"Lược, bỏ qua một số đoạn","hanViet":"TRUNG LƯỢC","lesson":12,"ex":[["この手紙は中略が多いです。","Bức thư này có nhiều đoạn lược bỏ."],["中略の部分は読みません。","Tôi không đọc phần lược bỏ."],["本に中略と書いてあります。","Trong sách có ghi là lược bỏ."],["中略の後を読みました。","Tôi đã đọc phần sau đoạn lược bỏ."],["先生は中略について説明しました。","Thầy đã giải thích về phần lược bỏ."]]},{"word":"おかしな","reading":"おかしな","meaning":"Buồn cười, kỳ lạ","hanViet":"","lesson":12,"ex":[["おかしな音が聞こえます。","Nghe thấy âm thanh kỳ lạ."],["おかしな人が来ました。","Một người kỳ lạ đã đến."],["おかしなことがありました。","Đã có chuyện kỳ lạ."],["おかしな顔をしています。","Anh ấy đang làm mặt buồn cười."],["おかしな夢を見ました。","Tôi đã mơ một giấc mơ kỳ lạ."]]},{"word":"サンダル","reading":"サンダル","meaning":"Giày xăng đan","hanViet":"","lesson":12,"ex":[["サンダルを買いました。","Tôi đã mua giày xăng đan."],["夏はサンダルがいいです。","Mùa hè đi xăng đan thì tốt."],["サンダルが壊れました。","Giày xăng đan đã hỏng."],["サンダルは軽いです。","Giày xăng đan nhẹ."],["サンダルで海に行きました。","Tôi đã đi biển bằng giày xăng đan."]]},{"word":"ピーピー","reading":"ピーピー","meaning":"Tiếng kêu của ấm nước sôi","hanViet":"","lesson":12,"ex":[["ピーピーという音が聞こえます。","Nghe thấy tiếng kêu pi pi."],["水を沸かすと、ピーピー鳴ります。","Khi đun nước, ấm kêu pi pi."],["ピーピー鳴ったら、台所に行きます。","Khi nghe tiếng pi pi, tôi đi vào bếp."],["ピーピーという音で起きました。","Tôi thức dậy vì tiếng kêu pi pi."],["ピーピーという音が台所から聞こえました。","Tiếng kêu pi pi vang lên từ bếp."]]},{"word":"たまらない","reading":"たまらない","meaning":"Không chịu được","hanViet":"","lesson":12,"ex":[["暑くてたまらないです。","Nóng không chịu được."],["眠くてたまらないです。","Buồn ngủ không chịu được."],["寒くてたまらないです。","Lạnh không chịu được."],["この音はうるさくてたまらないです。","Tiếng này ồn không chịu được."],["暑くてたまらないので、エアコンをつけます。","Vì nóng không chịu được nên tôi bật điều hòa."]]},{"word":"都会","reading":"とかい","meaning":"Đô thị, thành thị","hanViet":"ĐÔ HỘI","lesson":12,"ex":[["東京は大きな都会です。","Tokyo là đô thị lớn."],["都会に住みたいです。","Tôi muốn sống ở thành thị."],["都会は人が多いです。","Thành thị đông người."],["都会の生活は忙しいです。","Cuộc sống thành thị bận rộn."],["都会から村に引っ越ししました。","Tôi đã chuyển từ thành thị về làng."]]},{"word":"住宅地","reading":"じゅうたくち","meaning":"Khu dân cư","hanViet":"TRỤ TRẠCH ĐỊA","lesson":12,"ex":[["住宅地は静かです。","Khu dân cư yên tĩnh."],["住宅地に家を買いました。","Tôi đã mua nhà ở khu dân cư."],["この住宅地に公園があります。","Khu dân cư này có công viên."],["住宅地の近くに学校があります。","Gần khu dân cư có trường học."],["新しい住宅地ができました。","Khu dân cư mới đã hình thành."]]},{"word":"虫","reading":"むし","meaning":"Côn trùng","hanViet":"TRÙNG","lesson":12,"ex":[["夏に虫が多いです。","Mùa hè nhiều côn trùng."],["虫が飛んでいます。","Côn trùng đang bay."],["虫の声が聞こえます。","Nghe thấy tiếng côn trùng."],["虫を取るのが好きです。","Tôi thích bắt côn trùng."],["虫が花にいます。","Côn trùng ở trên hoa."]]},{"word":"虫の音","reading":"むしのね","meaning":"Tiếng côn trùng","hanViet":"TRÙNG ÂM","lesson":12,"ex":[["夜に虫の音が聞こえます。","Ban đêm nghe thấy tiếng côn trùng."],["虫の音は静かです。","Tiếng côn trùng yên tĩnh."],["秋に虫の音を聞きました。","Mùa thu tôi đã nghe tiếng côn trùng."],["虫の音が好きです。","Tôi thích tiếng côn trùng."],["山で虫の音を聞きながら、歩きました。","Vừa nghe tiếng côn trùng trên núi vừa đi bộ."]]},{"word":"車内","reading":"しゃない","meaning":"Trong tàu","hanViet":"XA NỘI","lesson":12,"ex":[["車内で電話をしないでください。","Xin đừng gọi điện trong tàu."],["車内は静かです。","Trong tàu yên tĩnh."],["車内で本を読みます。","Tôi đọc sách trong tàu."],["車内に人がたくさんいます。","Trong tàu có rất nhiều người."],["車内でアナウンスを聞きました。","Tôi đã nghe thông báo trong tàu."]]},{"word":"ホーム","reading":"ホーム","meaning":"Sân ga","hanViet":"","lesson":12,"ex":[["ホームで電車を待ちます。","Tôi đợi tàu ở sân ga."],["ホームに人がたくさんいます。","Sân ga có rất nhiều người."],["ホームから電車が見えます。","Từ sân ga nhìn thấy tàu điện."],["ホームで友達に会いました。","Tôi đã gặp bạn ở sân ga."],["ホームは駅の中にあります。","Sân ga ở trong nhà ga."]]},{"word":"加える","reading":"くわえる","meaning":"Thêm vào","hanViet":"GIA","lesson":12,"ex":[["スープに塩を加えます。","Tôi thêm muối vào súp."],["お茶に砂糖を加えます。","Tôi thêm đường vào trà."],["料理に水を加えました。","Tôi đã thêm nước vào món ăn."],["本に写真を加えました。","Tôi đã thêm ảnh vào sách."],["グループに新しい人を加えました。","Tôi đã thêm người mới vào nhóm."]]},{"word":"乗客","reading":"じょうきゃく","meaning":"Hành khách","hanViet":"THỪA KHÁCH","lesson":12,"ex":[["乗客がたくさんいます。","Có rất nhiều hành khách."],["乗客は電車で帰ります。","Hành khách về bằng tàu điện."],["乗客の荷物が多いです。","Hành lý của hành khách nhiều."],["乗客にアナウンスをしました。","Tôi đã thông báo cho hành khách."],["乗客は静かです。","Hành khách yên tĩnh."]]},{"word":"安全性","reading":"あんぜんせい","meaning":"Sự an toàn","hanViet":"AN TOÀN TÍNH","lesson":12,"ex":[["安全性が高いです。","Tính an toàn cao."],["この車の安全性はいいです。","Tính an toàn của chiếc xe này tốt."],["安全性について考えます。","Tôi nghĩ về sự an toàn."],["安全性を大切にします。","Tôi coi trọng sự an toàn."],["安全性が高い電車に乗ります。","Tôi đi tàu điện có tính an toàn cao."]]},{"word":"配慮する","reading":"はいりょする","meaning":"Chú ý đến, xét đến","hanViet":"PHỐI LỰ","lesson":12,"ex":[["人に配慮します。","Tôi chú ý đến người khác."],["乗客に配慮します。","Tôi chú ý đến hành khách."],["安全性に配慮します。","Tôi chú ý đến sự an toàn."],["子どもに配慮して、静かにします。","Chú ý đến trẻ con nên tôi giữ yên tĩnh."],["配慮することが大切です。","Việc chú ý đến người khác rất quan trọng."]]},{"word":"含む","reading":"ふくむ","meaning":"Bao gồm","hanViet":"HÀM","lesson":12,"ex":[["この本は写真を含みます。","Cuốn sách này bao gồm ảnh."],["試験は聞くことを含みます。","Kỳ thi bao gồm phần nghe."],["この箱は本と服を含みます。","Hộp này bao gồm sách và quần áo."],["値段は荷物を含みません。","Giá không bao gồm hành lý."],["この歌は英語を含みます。","Bài hát này bao gồm tiếng Anh."]]},{"word":"チャイム","reading":"チャイム","meaning":"Tiếng chuông, tiếng còi báo","hanViet":"","lesson":12,"ex":[["チャイムが鳴りました。","Chuông đã reo."],["学校のチャイムが鳴ります。","Chuông trường reo."],["チャイムを聞いて、教室に入りました。","Nghe chuông, tôi đã vào lớp."],["チャイムの音が大きいです。","Tiếng chuông to."],["午後のチャイムが鳴りました。","Chuông buổi chiều đã reo."]]},{"word":"発車ベル","reading":"はっしゃベル","meaning":"Chuông báo tàu xuất phát","hanViet":"PHÁT XA","lesson":12,"ex":[["発車ベルが鳴りました。","Chuông báo tàu xuất phát đã reo."],["発車ベルを聞いて、電車まで走りました。","Nghe chuông báo tàu xuất phát, tôi đã chạy đến tàu."],["発車ベルの音が聞こえます。","Nghe thấy tiếng chuông báo tàu xuất phát."],["ホームで発車ベルが鳴ります。","Chuông báo tàu xuất phát reo ở sân ga."],["発車ベルが鳴ったら、電車が出ます。","Khi chuông báo tàu xuất phát reo, tàu chạy."]]},{"word":"必ずしも","reading":"かならずしも","meaning":"Chẳng hẳn, không hẳn","hanViet":"TẤT","lesson":12,"ex":[["必ずしも安くありません。","Không hẳn là rẻ."],["必ずしも正しくありません。","Không hẳn là đúng."],["必ずしもあした天気がいいわけではありません。","Không hẳn ngày mai thời tiết đẹp."],["必ずしも新しいものがいいわけではありません。","Không hẳn đồ mới là tốt."],["必ずしも有名な店がいい店ではありません。","Không hẳn cửa hàng nổi tiếng là cửa hàng tốt."]]},{"word":"近所づきあい","reading":"きんじょづきあい","meaning":"Giao lưu với láng giềng","hanViet":"CẬN SỞ","lesson":12,"ex":[["近所づきあいは大切です。","Giao lưu với láng giềng rất quan trọng."],["近所づきあいがいいです。","Giao lưu với hàng xóm tốt."],["近所づきあいをします。","Tôi giao lưu với hàng xóm."],["近所づきあいで困ることがあります。","Có lúc tôi gặp khó khăn trong giao lưu với hàng xóm."],["近所づきあいは難しいです。","Giao lưu với hàng xóm thật khó."]]},{"word":"コマーシャル","reading":"コマーシャル","meaning":"Quảng cáo thương mại","hanViet":"","lesson":12,"ex":[["テレビでコマーシャルを見ました。","Tôi đã xem quảng cáo trên TV."],["コマーシャルが長いです。","Quảng cáo dài."],["コマーシャルの歌が好きです。","Tôi thích bài hát quảng cáo."],["コマーシャルを見て、買いました。","Xem quảng cáo rồi tôi đã mua."],["コマーシャルは多いです。","Quảng cáo nhiều."]]}],"N2":[{"word":"株式会社","reading":"かぶしきがいしゃ","meaning":"công ty cổ phần","hanViet":"CHU THỨC HỘI XÃ","lesson":13,"ex":[["お父さんは大きな株式会社で働いています。","Bố tôi làm việc ở một công ty cổ phần lớn."],["その株式会社は東京にあります。","Công ty cổ phần đó ở Tokyo."],["田中さんは株式会社の社長です。","Anh Tanaka là giám đốc của công ty cổ phần."],["私は将来、株式会社を作りたいです。","Trong tương lai, tôi muốn thành lập một công ty cổ phần."],["その株式会社は去年、大きくなりました。","Công ty cổ phần đó năm ngoái đã lớn mạnh hơn."]]},{"word":"随筆","reading":"ずいひつ","meaning":"tùy bút","hanViet":"TÙY BÚT","lesson":13,"ex":[["私は随筆を読むのが好きです。","Tôi thích đọc tùy bút."],["その随筆は日本の生活について書いてあります。","Bài tùy bút đó viết về cuộc sống ở Nhật."],["先生は有名な随筆を教室で読みました。","Thầy giáo đã đọc một bài tùy bút nổi tiếng trong lớp học."],["私は毎週、随筆を一つ読みます。","Mỗi tuần tôi đọc một bài tùy bút."],["この随筆は短くて、おもしろいです。","Bài tùy bút này ngắn và thú vị."]]},{"word":"経過（する）","reading":"けいか（する）","meaning":"trải qua","hanViet":"KINH QUÁ","lesson":13,"ex":[["時間が経過するのが速いです。","Thời gian trôi qua thật nhanh."],["日本に来てから、100日が経過しました。","Kể từ khi đến Nhật, 100 ngày đã trôi qua."],["3日が経過しましたが、天気は変わりません。","3 ngày đã trôi qua nhưng thời tiết không thay đổi."],["試験の後、7日が経過しました。","7 ngày đã trôi qua sau kỳ thi."],["授業が終わってから、時間が経過しました。","Một thời gian đã trôi qua kể từ khi tiết học kết thúc."]]},{"word":"変化（する）","reading":"へんか（する）","meaning":"thay đổi, biến đổi","hanViet":"BIẾN HÓA","lesson":13,"ex":[["この町は大きく変化しました。","Thành phố này đã thay đổi rất nhiều."],["天気が変化して、雨が降りました。","Thời tiết thay đổi rồi trời đã mưa."],["私の気持ちが変化しました。","Cảm xúc của tôi đã thay đổi."],["日本語の勉強で、私の生活が変化しました。","Việc học tiếng Nhật đã làm cuộc sống của tôi thay đổi."],["春になると、景色が変化します。","Khi mùa xuân đến, phong cảnh thay đổi."]]},{"word":"心情","reading":"しんじょう","meaning":"tâm tình, cảm xúc","hanViet":"TÂM TÌNH","lesson":13,"ex":[["友達の心情がわかります。","Tôi hiểu tâm trạng của bạn mình."],["その本は人の心情を書いています。","Cuốn sách đó viết về tâm trạng con người."],["心情をことばで伝えるのは難しいです。","Thật khó diễn tả tâm trạng bằng lời."],["先生は学生の心情を大切にします。","Thầy giáo coi trọng tâm trạng của học sinh."],["映画を見て、その人の心情がわかりました。","Xem phim, tôi đã hiểu được tâm trạng của người đó."]]},{"word":"勘違い（する）","reading":"かんちがい（する）","meaning":"hiểu nhầm, hiểu sai ý","hanViet":"KHÁM VI","lesson":13,"ex":[["私は時間を勘違いしました。","Tôi đã nhầm giờ."],["友達の話を勘違いして、びっくりしました。","Tôi hiểu nhầm lời bạn nói nên đã giật mình."],["先生の名前を勘違いしました。","Tôi đã nhầm tên của thầy giáo."],["それは勘違いです。","Đó là hiểu nhầm."],["私は道を勘違いして、遅くなりました。","Tôi nhầm đường nên đã đến muộn."]]},{"word":"日常（的）","reading":"にちじょう（てき）","meaning":"hằng ngày","hanViet":"NHẬT THƯỜNG ĐÍCH","lesson":13,"ex":[["日常の生活は忙しいです。","Cuộc sống hằng ngày thật bận rộn."],["日常的な日本語を練習します。","Tôi luyện tiếng Nhật dùng hằng ngày."],["私は日常のことを手紙に書きます。","Tôi viết những chuyện hằng ngày vào thư."],["日常のかいものは近くの店でします。","Tôi mua sắm hằng ngày ở cửa hàng gần nhà."],["日常のごはんは家で作ります。","Bữa ăn hằng ngày tôi nấu ở nhà."]]},{"word":"社交","reading":"しゃこう","meaning":"xã giao","hanViet":"XÃ GIAO","lesson":13,"ex":[["社交は仕事で大切です。","Giao tiếp xã hội rất quan trọng trong công việc."],["私は社交が苦手です。","Tôi không giỏi giao tiếp xã hội."],["パーティーで社交を楽しみます。","Tôi thích giao tiếp xã hội ở bữa tiệc."],["社交的な人は友達が多いです。","Người hòa đồng có nhiều bạn bè."],["社交の時間を大切にします。","Tôi trân trọng thời gian giao tiếp xã hội."]]},{"word":"雑談（する）","reading":"ざつだん（する）","meaning":"tán gẫu, nói chuyện phiếm","hanViet":"TẠP ĐÀM","lesson":13,"ex":[["友達と雑談するのが好きです。","Tôi thích tán gẫu với bạn bè."],["昼休みに同僚と雑談します。","Giờ nghỉ trưa tôi tán gẫu với đồng nghiệp."],["雑談で新しいことを知りました。","Qua tán gẫu, tôi biết thêm điều mới."],["電車で友達と雑談しました。","Tôi đã tán gẫu với bạn trên tàu điện."],["雑談は楽しいです。","Tán gẫu thật vui."]]},{"word":"入園料","reading":"にゅうえんりょう","meaning":"phí vào cửa","hanViet":"NHẬP VIÊN LIỆU","lesson":13,"ex":[["この動物園の入園料は高いです。","Phí vào cổng vườn thú này đắt."],["入園料は大人と小人で違います。","Phí vào cổng khác nhau giữa người lớn và trẻ em."],["公園の入園料は安いです。","Phí vào công viên rẻ."],["入園料を払って、中に入りました。","Tôi đã trả phí vào cổng rồi đi vào trong."],["入園料はいくらですか。","Phí vào cổng là bao nhiêu?"]]},{"word":"大人","reading":"おとな","meaning":"người lớn","hanViet":"ĐẠI NHÂN","lesson":13,"ex":[["大人になると、仕事をします。","Khi trưởng thành, người ta đi làm."],["大人でもこの本が好きです。","Ngay cả người lớn cũng thích cuốn sách này."],["大人になってから、日本語を勉強しました。","Sau khi trưởng thành, tôi đã học tiếng Nhật."],["大人の入園料は子どもより高いです。","Phí vào cổng của người lớn cao hơn của trẻ em."],["大人になると、自分のことを自分で決めます。","Khi trưởng thành, mình tự quyết định việc của mình."]]},{"word":"小人","reading":"しょうにん","meaning":"trẻ em","hanViet":"TIỂU NHÂN","lesson":13,"ex":[["小人の入園料は安いです。","Phí vào cổng trẻ em rẻ."],["小人は大人と動物園に行きます。","Trẻ em đi vườn thú cùng người lớn."],["小人の入園料を払いました。","Tôi đã trả phí vào cổng trẻ em."],["小人は電車に安く乗れます。","Trẻ em đi tàu điện với giá rẻ."],["公園には小人がたくさんいます。","Trong công viên có nhiều trẻ em."]]},{"word":"そのうち","reading":"","meaning":"chẳng bao lâu, rồi sẽ","hanViet":"","lesson":13,"ex":[["そのうち雨が降るでしょう。","Chẳng bao lâu nữa trời sẽ mưa."],["そのうち日本語が上手になります。","Rồi sẽ giỏi tiếng Nhật thôi."],["そのうち春が来ます。","Chẳng bao lâu nữa mùa xuân sẽ đến."],["そのうち友達が来ます。","Chẳng bao lâu nữa bạn tôi sẽ đến."],["そのうち元気になります。","Chẳng bao lâu nữa sẽ khỏe lại."]]},{"word":"注目（する）","reading":"ちゅうもく（する）","meaning":"chú ý","hanViet":"CHÚ MỤC","lesson":13,"ex":[["先生の話に注目します。","Tôi chú ý lắng nghe lời thầy giáo."],["新しい店が注目されています。","Cửa hàng mới đang được chú ý."],["新聞で注目される話を読みました。","Tôi đã đọc một câu chuyện được chú ý trên báo."],["みんながその映画に注目しています。","Mọi người đều đang chú ý đến bộ phim đó."],["子どもの勉強に注目してください。","Hãy chú ý đến việc học của con."]]},{"word":"語","reading":"ご","meaning":"từ ngữ","hanViet":"NGỮ","lesson":13,"ex":[["日本語の語は難しいです。","Từ ngữ tiếng Nhật thật khó."],["この語の意味は何ですか。","Từ này có nghĩa là gì?"],["新しい語を辞書で見ます。","Tôi tra từ mới trong từ điển."],["語を覚えるのは難しいです。","Nhớ từ ngữ thật khó."],["その語は毎日使います。","Tôi dùng từ đó mỗi ngày."]]},{"word":"思考（する）","reading":"しこう（する）","meaning":"suy nghĩ","hanViet":"TƯ KHẢO","lesson":13,"ex":[["問題について思考します。","Tôi suy nghĩ về vấn đề."],["思考する時間が大切です。","Thời gian suy nghĩ rất quan trọng."],["先生は学生の思考を大切にします。","Thầy giáo coi trọng suy nghĩ của học sinh."],["静かな場所で思考します。","Tôi suy nghĩ ở một nơi yên tĩnh."],["思考してから、答えを言います。","Tôi suy nghĩ rồi mới trả lời."]]},{"word":"問い","reading":"とい","meaning":"câu hỏi","hanViet":"VẤN","lesson":13,"ex":[["先生に問いをしました。","Tôi đã đặt câu hỏi với thầy giáo."],["この問いの答えは難しいです。","Câu hỏi này khó trả lời."],["本の中に問いがあります。","Trong sách có câu hỏi."],["問いに答えるのは難しいです。","Trả lời câu hỏi thật khó."],["友達の問いに答えました。","Tôi đã trả lời câu hỏi của bạn."]]},{"word":"全文","reading":"ぜんぶん","meaning":"toàn văn, toàn bài","hanViet":"TOÀN VĂN","lesson":13,"ex":[["文章の全文を読みました。","Tôi đã đọc toàn bộ bài viết."],["全文を読んで、意味がわかりました。","Đọc toàn bài, tôi đã hiểu ý nghĩa."],["手紙の全文を書きました。","Tôi đã viết toàn bộ bức thư."],["全文は長くて、読むのに時間がかかります。","Toàn bài dài nên đọc mất thời gian."],["全文をゆっくり読みました。","Tôi đã đọc toàn bài một cách chậm rãi."]]},{"word":"のみこむ","reading":"","meaning":"hiểu, tiếp thu, nắm bắt","hanViet":"","lesson":13,"ex":[["話の意味をのみこむのは難しいです。","Thật khó nắm bắt ý nghĩa của câu chuyện."],["新しいことをのみこむのに時間がかかります。","Tiếp thu điều mới mất thời gian."],["先生の話をのみこみました。","Tôi đã nắm bắt được lời thầy giáo."],["本の意味をのみこみました。","Tôi đã hiểu được ý nghĩa của cuốn sách."],["友達の気持ちをのみこみました。","Tôi đã hiểu được cảm xúc của bạn mình."]]},{"word":"佃煮","reading":"つくだに","meaning":"Tsukudani (một món ăn của Nhật Bản gồm cá nhỏ, ngao, sò,… nấu ngọt với đường và xì dầu).","hanViet":"ĐIỀN CHỬ","lesson":13,"ex":[["佃煮はごはんと食べます。","Tôi ăn tsukudani với cơm."],["佃煮は魚の料理です。","Tsukudani là món ăn từ cá."],["お母さんが佃煮を作りました。","Mẹ tôi đã làm tsukudani."],["佃煮はおいしいです。","Tsukudani rất ngon."],["佃煮をお土産に買いました。","Tôi đã mua tsukudani làm quà."]]},{"word":"以後","reading":"いご","meaning":"từ nay trở đi","hanViet":"DĨ HẬU","lesson":13,"ex":[["以後、毎日日本語を勉強します。","Từ nay trở đi, tôi sẽ học tiếng Nhật mỗi ngày."],["以後、毎朝6時に起きます。","Từ nay trở đi, tôi dậy lúc 6 giờ mỗi sáng."],["以後、気をつけます。","Từ nay trở đi, tôi sẽ cẩn thận."],["以後、その店には行きません。","Từ nay trở đi, tôi sẽ không đến cửa hàng đó nữa."],["以後、健康に気をつけます。","Từ nay trở đi, tôi sẽ chú ý đến sức khỏe."]]},{"word":"以降","reading":"いこう","meaning":"sau đó","hanViet":"DĨ GIÁNG","lesson":13,"ex":[["来週以降、忙しくなります。","Sau tuần sau, tôi sẽ bận rộn."],["3月以降、暖かくなります。","Sau tháng 3, trời sẽ ấm dần."],["午後6時以降、電話をください。","Sau 6 giờ chiều, hãy gọi điện cho tôi."],["来月以降、日本語の試験があります。","Sau tháng sau, có kỳ thi tiếng Nhật."],["明日以降、雨が降ります。","Từ ngày mai trở đi, trời sẽ mưa."]]},{"word":"以来","reading":"いらい","meaning":"kể từ đó","hanViet":"DĨ LAI","lesson":13,"ex":[["日本に来て以来、日本語を勉強しています。","Kể từ khi đến Nhật, tôi đang học tiếng Nhật."],["その店に来て以来、毎週かいものをします。","Kể từ khi đến cửa hàng đó, tôi mua sắm mỗi tuần."],["子どもが生まれて以来、生活が変わりました。","Kể từ khi con ra đời, cuộc sống đã thay đổi."],["友達と会って以来、毎日手紙を書きます。","Kể từ khi gặp bạn, tôi viết thư mỗi ngày."],["病気になって以来、健康に気をつけています。","Kể từ khi bị ốm, tôi luôn chú ý đến sức khỏe."]]},{"word":"一体","reading":"いったい","meaning":"rốt cuộc là (trong câu hỏi)","hanViet":"NHẤT THỂ","lesson":13,"ex":[["一体どうしたのですか。","Rốt cuộc đã xảy ra chuyện gì vậy?"],["一体だれが来ましたか。","Rốt cuộc ai đã đến vậy?"],["一体何があったのですか。","Rốt cuộc đã có chuyện gì vậy?"],["一体どこに行くのですか。","Rốt cuộc anh định đi đâu vậy?"],["一体いつ帰りますか。","Rốt cuộc khi nào anh về?"]]},{"word":"四字熟語","reading":"よじじゅくご","meaning":"thành ngữ gồm tổ hợp từ cấu tạo từ 4 chữ Hán.","hanViet":"TỨ TỰ THỤC NGỮ","lesson":13,"ex":[["四字熟語を勉強しています。","Tôi đang học thành ngữ 4 chữ Hán."],["日本語には四字熟語がたくさんあります。","Tiếng Nhật có rất nhiều thành ngữ 4 chữ Hán."],["この四字熟語の意味は何ですか。","Thành ngữ 4 chữ Hán này có nghĩa là gì?"],["先生は四字熟語を教えてくれました。","Thầy giáo đã dạy tôi thành ngữ 4 chữ Hán."],["四字熟語を覚えるのは難しいです。","Nhớ thành ngữ 4 chữ Hán thật khó."]]},{"word":"熟語","reading":"じゅくご","meaning":"cụm từ, từ ghép, ngữ cố định từ 2 thành tố trở lên","hanViet":"THỤC NGỮ","lesson":13,"ex":[["熟語の意味を辞書で見ます。","Tôi tra nghĩa của cụm từ trong từ điển."],["新しい熟語を覚えました。","Tôi đã nhớ được cụm từ mới."],["この熟語はよく使います。","Tôi thường dùng cụm từ này."],["熟語を勉強するのは楽しいです。","Học cụm từ thật thú vị."],["この熟語は漢字が二つあります。","Cụm từ này có hai chữ Hán."]]},{"word":"適度（な）","reading":"てきど（な）","meaning":"mức độ vừa phải","hanViet":"THÍCH ĐỘ","lesson":13,"ex":[["適度に運動します。","Tôi vận động vừa phải."],["適度な休みが必要です。","Cần nghỉ ngơi ở mức độ vừa phải."],["適度な勉強が大切です。","Học ở mức độ vừa phải rất quan trọng."],["適度に食べるのがいいです。","Ăn vừa phải thì tốt."],["適度に休むのが大切です。","Nghỉ ngơi vừa phải rất quan trọng."]]},{"word":"いや","reading":"","meaning":"không","hanViet":"","lesson":13,"ex":[["「いや、きょうは行きません。」","Không, hôm nay tôi không đi."],["「いや、それは違います。」","Không, cái đó không đúng."],["「いや、まだ食べていません。」","Không, tôi chưa ăn."],["「いや、私は知りません。」","Không, tôi không biết."],["「いや、明日は休みです。」","Không, ngày mai tôi nghỉ."]]},{"word":"いな","reading":"","meaning":"chẳng phải (dùng trong văn viết)","hanViet":"","lesson":13,"ex":[["これは水ではない。いな、お茶だ。","Đây không phải nước. Chẳng phải, đây là trà."],["これは犬ではない。いな、猫だ。","Đây không phải chó. Chẳng phải, đây là mèo."],["これは春ではない。いな、夏だ。","Đây không phải mùa xuân. Chẳng phải, đây là mùa hè."],["これは朝ではない。いな、夜だ。","Đây không phải buổi sáng. Chẳng phải, đây là buổi tối."],["これは問題ではない。いな、機会だ。","Đây không phải vấn đề. Chẳng phải, đây là cơ hội."]]},{"word":"適切（な）","reading":"てきせつ（な）","meaning":"thích hợp, phù hợp","hanViet":"THÍCH THIẾT","lesson":13,"ex":[["適切なことばを使います。","Tôi dùng từ ngữ thích hợp."],["適切な答えを言いました。","Tôi đã đưa ra câu trả lời thích hợp."],["適切な時間に来てください。","Hãy đến vào thời gian thích hợp."],["適切な服を選びます。","Tôi chọn trang phục thích hợp."],["適切な仕事を選びます。","Tôi chọn công việc thích hợp."]]},{"word":"一進一退","reading":"いっしんいったい","meaning":"cò cưa, lúc tiến lúc lùi","hanViet":"NHẤT TIẾN NHẤT THOÁI","lesson":13,"ex":[["景気は一進一退です。","Kinh tế lúc tiến lúc lùi."],["仕事は一進一退です。","Công việc lúc tiến lúc lùi."],["勉強は一進一退ですが、頑張ります。","Việc học lúc tiến lúc lùi, nhưng tôi sẽ cố gắng."],["子どもの病気は一進一退です。","Bệnh của con lúc đỡ lúc nặng."],["日本語の勉強は一進一退です。","Việc học tiếng Nhật lúc tiến lúc lùi."]]},{"word":"試行錯誤","reading":"しこうさくご","meaning":"thử và lặp đi lặp lại thất bại rồi đúc kết kinh nghiệm dẫn đến thành công, làm thử và rút kinh nghiệm.","hanViet":"THÍ HÀNH THÁC NGỘ","lesson":13,"ex":[["新しい料理を作るには、試行錯誤が必要です。","Để làm món ăn mới, cần thử đi thử lại và rút kinh nghiệm."],["試行錯誤をして、成功しました。","Tôi đã thử và rút kinh nghiệm rồi thành công."],["仕事では試行錯誤が大切です。","Trong công việc, việc thử và rút kinh nghiệm rất quan trọng."],["試行錯誤の毎日です。","Mỗi ngày đều là thử và rút kinh nghiệm."],["勉強も試行錯誤です。","Học tập cũng là thử và rút kinh nghiệm."]]},{"word":"月日","reading":"つきひ","meaning":"thời gian, tháng ngày","hanViet":"NGUYỆT NHẬT","lesson":13,"ex":[["月日が経過するのは速いです。","Tháng ngày trôi qua thật nhanh."],["月日が経過して、子どもは大きくなりました。","Tháng ngày trôi qua, con tôi đã lớn lên."],["月日を大切にします。","Tôi trân trọng tháng ngày."],["月日が経過して、町は変わりました。","Tháng ngày trôi qua, thành phố đã thay đổi."],["月日が経過して、日本語が上手になりました。","Tháng ngày trôi qua, tiếng Nhật của tôi đã giỏi hơn."]]},{"word":"要する","reading":"ようする","meaning":"cần phải có","hanViet":"YẾU","lesson":13,"ex":[["この仕事は時間が要します。","Công việc này cần thời gian."],["日本語の勉強には時間が要します。","Việc học tiếng Nhật cần thời gian."],["家を作るには時間が要します。","Xây nhà cần thời gian."],["この本を読むには時間が要します。","Đọc cuốn sách này cần thời gian."],["成功するには時間が要します。","Để thành công cần thời gian."]]},{"word":"ただ","reading":"","meaning":"chỉ, chỉ là","hanViet":"","lesson":13,"ex":[["ただ、時間がありません。","Tuy nhiên, tôi không có thời gian."],["ただ、明日は行けません。","Tuy nhiên, ngày mai tôi không đi được."],["ただ、天気はよくありません。","Tuy nhiên, thời tiết không tốt."],["ただ、その本は高いです。","Tuy nhiên, cuốn sách đó đắt."],["ただ、友達は来ませんでした。","Tuy nhiên, bạn tôi đã không đến."]]},{"word":"浮かぶ","reading":"うかぶ","meaning":"nổi lên, hiện lên","hanViet":"PHÙ","lesson":13,"ex":[["友達の顔が浮かびます。","Khuôn mặt bạn tôi hiện lên."],["昔の思い出が浮かびます。","Kỷ niệm xưa hiện lên."],["いい答えが浮かびました。","Câu trả lời hay hiện lên trong đầu."],["水に花が浮かんでいます。","Hoa nổi trên mặt nước."],["先生の顔が浮かびました。","Khuôn mặt thầy giáo hiện lên."]]},{"word":"月極/月決め","reading":"つきぎめ","meaning":"hợp đồng trọn tháng, cho thuê theo tháng","hanViet":"NGUYỆT CỰC NGUYỆT QUYẾT","lesson":13,"ex":[["月極の駐車場を借ります。","Tôi thuê bãi đậu xe theo tháng."],["月極の契約をしました。","Tôi đã ký hợp đồng theo tháng."],["月極の部屋を借ります。","Tôi thuê phòng theo tháng."],["この駐車場は月極です。","Bãi đậu xe này cho thuê theo tháng."],["月極の料金は安いです。","Phí thuê theo tháng rẻ."]]},{"word":"来日（する）","reading":"らいにち（する）","meaning":"đến Nhật","hanViet":"LAI NHẬT","lesson":13,"ex":[["田中さんは去年、来日しました。","Anh Tanaka năm ngoái đã đến Nhật."],["友達が来日するのを楽しみにしています。","Tôi mong chờ bạn đến Nhật."],["来日してから、日本語を勉強しています。","Kể từ khi đến Nhật, tôi đang học tiếng Nhật."],["初めて来日したとき、びっくりしました。","Khi lần đầu đến Nhật, tôi đã rất ngạc nhiên."],["来日する前に、日本語を勉強しました。","Trước khi đến Nhật, tôi đã học tiếng Nhật."]]},{"word":"詰める","reading":"つめる","meaning":"bịt, nhét","hanViet":"CẬT","lesson":13,"ex":[["本をかばんに詰めます。","Tôi nhét sách vào túi."],["荷物をかばんに詰めます。","Tôi nhét hành lý vào túi."],["服をかばんに詰めました。","Tôi đã nhét quần áo vào túi."],["子どもが口にごはんを詰めました。","Đứa trẻ đã nhét cơm vào miệng."],["手紙をかばんに詰めました。","Tôi đã nhét thư vào túi."]]},{"word":"街","reading":"まち","meaning":"thành phố, phố xá","hanViet":"NHAI","lesson":13,"ex":[["京都の街はきれいです。","Phố xá Kyoto rất đẹp."],["街に新しい店ができました。","Trong phố có cửa hàng mới mở."],["街を歩くのが好きです。","Tôi thích đi bộ trong phố."],["街の夜はにぎやかです。","Buổi tối trong phố rất nhộn nhịp."],["街の景色が好きです。","Tôi thích phong cảnh phố xá."]]},{"word":"看板","reading":"かんばん","meaning":"biển hiệu, biển quảng cáo","hanViet":"KHÁN BẢN","lesson":13,"ex":[["店の看板が大きいです。","Biển hiệu của cửa hàng rất lớn."],["看板に店の名前が書いてあります。","Trên biển hiệu có ghi tên cửa hàng."],["看板を見て、店に入りました。","Nhìn biển hiệu, tôi đã vào cửa hàng."],["新しい看板ができました。","Biển hiệu mới đã được làm xong."],["看板の字がきれいです。","Chữ trên biển hiệu rất đẹp."]]},{"word":"解読（する）","reading":"かいどく（する）","meaning":"đọc ra, giải mã","hanViet":"GIẢI ĐỘC","lesson":13,"ex":[["古い文章を解読しました。","Tôi đã đọc được bài viết cổ."],["古い手紙を解読しました。","Tôi đã đọc được bức thư cổ."],["古い地図を解読しました。","Tôi đã đọc được bản đồ cổ."],["先生が文章を解読してくれました。","Thầy giáo đã đọc giúp tôi bài viết."],["解読するのに時間がかかります。","Việc đọc ra mất thời gian."]]},{"word":"出くわす","reading":"でくわす","meaning":"tình cờ gặp, gặp phải","hanViet":"XUẤT","lesson":13,"ex":[["街で友達に出くわしました。","Tôi tình cờ gặp bạn trong phố."],["駅で先生に出くわしました。","Tôi tình cờ gặp thầy giáo ở ga."],["旅行で新しい友達に出くわしました。","Trong chuyến du lịch, tôi tình cờ gặp bạn mới."],["公園で犬に出くわしました。","Tôi tình cờ gặp một con chó trong công viên."],["きのう、電車で同僚に出くわしました。","Hôm qua, tôi tình cờ gặp đồng nghiệp trên tàu điện."]]},{"word":"パーキング","reading":"","meaning":"nơi đỗ xe","hanViet":"","lesson":13,"ex":[["パーキングは駅の近くにあります。","Bãi đậu xe ở gần ga."],["パーキングは店の前にあります。","Bãi đậu xe ở trước cửa hàng."],["パーキングが広いです。","Bãi đậu xe rộng."],["パーキングに車がたくさんあります。","Ở bãi đậu xe có nhiều xe."],["パーキングを探しています。","Tôi đang tìm bãi đậu xe."]]},{"word":"頭（～に付く）","reading":"あたま（～につく）","meaning":"(ăn sâu vào) đầu","hanViet":"ĐẦU PHÓ","lesson":13,"ex":[["新しいことばが頭に付きました。","Từ mới đã in sâu vào đầu."],["日本語が頭に付いてきました。","Tiếng Nhật dần in sâu vào đầu."],["先生の話が頭に付きません。","Lời thầy giáo không in vào đầu được."],["歌が頭に付きました。","Bài hát đã in sâu vào đầu."],["漢字が頭に付きません。","Chữ Hán không in vào đầu được."]]},{"word":"和英辞典","reading":"わえいじてん","meaning":"từ điển Nhật - Anh","hanViet":"HÒA ANH TỪ ĐIỂN","lesson":13,"ex":[["和英辞典で英語の意味を見ます。","Tôi tra nghĩa tiếng Anh trong từ điển Nhật-Anh."],["和英辞典を買いました。","Tôi đã mua từ điển Nhật-Anh."],["和英辞典は重いです。","Từ điển Nhật-Anh nặng."],["和英辞典で新しいことばを調べます。","Tôi tra từ mới trong từ điển Nhật-Anh."],["和英辞典は部屋にあります。","Từ điển Nhật-Anh ở trong phòng."]]},{"word":"辞典","reading":"じてん","meaning":"từ điển","hanViet":"TỪ ĐIỂN","lesson":13,"ex":[["辞典でことばの意味を見ます。","Tôi tra nghĩa của từ trong từ điển."],["新しい辞典を買いました。","Tôi đã mua từ điển mới."],["辞典は重くて、大きいです。","Từ điển nặng và to."],["辞典で漢字を調べます。","Tôi tra chữ Hán trong từ điển."],["辞典を読むのが好きです。","Tôi thích đọc từ điển."]]},{"word":"ひょっとして","reading":"","meaning":"phải chăng, hay là","hanViet":"","lesson":13,"ex":[["ひょっとして、田中さんですか。","Phải chăng anh là Tanaka?"],["ひょっとして、明日は雨ですか。","Hay là ngày mai trời mưa?"],["ひょっとして、先生ですか。","Phải chăng anh là giáo viên?"],["ひょっとして、きのう会いましたか。","Phải chăng hôm qua chúng ta đã gặp nhau?"],["ひょっとして、日本語がわかりますか。","Phải chăng anh hiểu tiếng Nhật?"]]},{"word":"オーナー","reading":"","meaning":"người chủ, chủ sở hữu","hanViet":"","lesson":13,"ex":[["店のオーナーは田中さんです。","Chủ cửa hàng là anh Tanaka."],["オーナーは親切な人です。","Người chủ là người tốt bụng."],["レストランのオーナーに会いました。","Tôi đã gặp chủ nhà hàng."],["オーナーが新しい店を作りました。","Người chủ đã mở cửa hàng mới."],["オーナーは毎日店に来ます。","Người chủ đến cửa hàng mỗi ngày."]]},{"word":"苗字","reading":"みょうじ","meaning":"họ","hanViet":"MIÊU TỰ","lesson":13,"ex":[["私の苗字は田中です。","Họ của tôi là Tanaka."],["苗字は何ですか。","Họ của anh là gì?"],["友達の苗字は山田です。","Họ của bạn tôi là Yamada."],["苗字を教えてください。","Hãy cho tôi biết họ của anh."],["苗字が同じです。","Họ giống nhau."]]},{"word":"あるいは","reading":"","meaning":"hoặc, hoặc là","hanViet":"","lesson":13,"ex":[["明日、あるいは来週行きます。","Ngày mai hoặc tuần sau tôi sẽ đi."],["田中さん、あるいは山田さんに聞きます。","Tôi sẽ hỏi anh Tanaka hoặc anh Yamada."],["本、あるいは雑誌を買います。","Tôi mua sách hoặc tạp chí."],["電車、あるいは車で行きます。","Tôi đi bằng tàu điện hoặc ô tô."],["朝、あるいは夜に勉強します。","Tôi học vào buổi sáng hoặc buổi tối."]]},{"word":"ムーン","reading":"","meaning":"Mặt trăng (từ vay tiếng Anh 'moon', chủ yếu dùng trong tên riêng)","hanViet":"","lesson":13,"ex":[["「ムーン」という店があります。","Có một cửa hàng tên là \"Moon\"."],["ムーンという名前の店に行きました。","Tôi đã đến cửa hàng tên Moon."],["夜、ムーンの看板がきれいです。","Ban đêm, biển hiệu Moon rất đẹp."],["ムーンという名前はおもしろいです。","Cái tên Moon thật thú vị."],["ムーンという店は駅の近くにあります。","Cửa hàng tên Moon ở gần ga."]]},{"word":"エンド","reading":"","meaning":"kết thúc, hết","hanViet":"","lesson":13,"ex":[["映画のエンドは悲しかったです。","Đoạn kết của bộ phim thật buồn."],["ゲームのエンドがおもしろいです。","Đoạn kết của trò chơi thật thú vị."],["話のエンドで、みんな笑いました。","Ở đoạn kết câu chuyện, mọi người đều cười."],["エンドまで読みました。","Tôi đã đọc đến hết."],["エンドの後、みんな帰りました。","Sau khi kết thúc, mọi người đã về."]]},{"word":"ネーミング","reading":"","meaning":"việc đặt tên","hanViet":"","lesson":13,"ex":[["店のネーミングを考えます。","Tôi nghĩ cách đặt tên cho cửa hàng."],["新しい商品のネーミングは難しいです。","Đặt tên cho sản phẩm mới thật khó."],["ネーミングがおもしろいです。","Việc đặt tên thật thú vị."],["会社のネーミングを決めました。","Tôi đã quyết định tên công ty."],["ネーミングについて話します。","Tôi nói về việc đặt tên."]]},{"word":"なんとなく","reading":"","meaning":"chẳng hiểu sao nhưng, không hiểu sao nhưng","hanViet":"","lesson":13,"ex":[["なんとなく悲しいです。","Chẳng hiểu sao tôi thấy buồn."],["なんとなくうれしいです。","Chẳng hiểu sao tôi thấy vui."],["なんとなく疲れました。","Chẳng hiểu sao tôi thấy mệt."],["なんとなくその本を買いました。","Chẳng hiểu sao tôi đã mua cuốn sách đó."],["なんとなく眠いです。","Chẳng hiểu sao tôi thấy buồn ngủ."]]},{"word":"頭に入れる","reading":"あたまにいれる","meaning":"đưa vào đầu","hanViet":"ĐẦU NHẬP","lesson":13,"ex":[["新しいことばを頭に入れます。","Tôi đưa từ mới vào đầu."],["漢字を頭に入れるのは難しいです。","Đưa chữ Hán vào đầu thật khó."],["先生の話を頭に入れました。","Tôi đã ghi nhớ lời thầy giáo."],["歌を頭に入れます。","Tôi ghi nhớ bài hát."],["毎日、単語を頭に入れます。","Mỗi ngày tôi ghi nhớ từ vựng."]]},{"word":"見慣れる","reading":"みなれる","meaning":"nhìn quen mắt","hanViet":"KIẾN QUÁN","lesson":13,"ex":[["街の景色に見慣れました。","Tôi đã nhìn quen phong cảnh phố xá."],["漢字に見慣れました。","Tôi đã nhìn quen chữ Hán."],["先生の顔に見慣れました。","Tôi đã nhìn quen khuôn mặt thầy giáo."],["新しい部屋に見慣れました。","Tôi đã nhìn quen căn phòng mới."],["新しい学校に見慣れました。","Tôi đã nhìn quen ngôi trường mới."]]},{"word":"範囲","reading":"はんい","meaning":"phạm vi","hanViet":"PHẠM VI","lesson":13,"ex":[["試験の範囲は広いです。","Phạm vi kỳ thi rộng."],["勉強の範囲を決めました。","Tôi đã quyết định phạm vi học."],["仕事の範囲が広いです。","Phạm vi công việc rộng."],["範囲を小さくしました。","Tôi đã thu hẹp phạm vi."],["試験の範囲はこの本だけです。","Phạm vi kỳ thi chỉ là cuốn sách này."]]},{"word":"広がる","reading":"ひろがる","meaning":"mở rộng, lan rộng ra","hanViet":"QUẢNG","lesson":13,"ex":[["話が広がりました。","Câu chuyện đã lan rộng."],["町が広がりました。","Thành phố đã mở rộng."],["公園が広がりました。","Công viên đã mở rộng."],["仕事の範囲が広がりました。","Phạm vi công việc đã mở rộng."],["海が広がっています。","Biển trải rộng."]]},{"word":"横断（する）","reading":"おうだん（する）","meaning":"băng qua","hanViet":"HOÀNH ĐOẠN","lesson":13,"ex":[["道を横断します。","Tôi băng qua đường."],["信号で道を横断します。","Tôi băng qua đường ở đèn tín hiệu."],["橋を横断しました。","Tôi đã băng qua cầu."],["道路を横断するとき、気をつけます。","Khi băng qua đường, tôi cẩn thận."],["子どもと道を横断しました。","Tôi đã băng qua đường cùng con."]]},{"word":"どうやら","reading":"","meaning":"có vẻ như, dường như","hanViet":"","lesson":13,"ex":[["どうやら雨が降りそうです。","Có vẻ như trời sắp mưa."],["どうやら友達は来ないようです。","Dường như bạn tôi sẽ không đến."],["どうやら春が来ました。","Dường như mùa xuân đã đến."],["どうやらみんな帰りました。","Dường như mọi người đã về."],["どうやら試験は難しかったようです。","Dường như kỳ thi đã khó."]]},{"word":"市場（駐車場～）","reading":"しじょう（ちゅうしゃじょう～）","meaning":"Thị trường (bãi đậu xe)","hanViet":"THỊ TRƯỜNG TRÚ XA TRƯỜNG","lesson":13,"ex":[["市場で野菜を買います。","Tôi mua rau ở chợ."],["市場は朝からにぎやかです。","Chợ nhộn nhịp từ buổi sáng."],["市場で魚を買いました。","Tôi đã mua cá ở chợ."],["駐車場の近くに小さい市場があります。","Gần bãi đậu xe có một khu chợ nhỏ."],["市場には店がたくさんあります。","Ở chợ có nhiều cửa hàng."]]},{"word":"独占（する）","reading":"どくせん（する）","meaning":"độc quyền, độc chiếm","hanViet":"ĐỘC CHIẾM","lesson":13,"ex":[["その会社は市場を独占しています。","Công ty đó đang độc chiếm thị trường."],["話を独占してはいけません。","Không được độc chiếm câu chuyện."],["彼は時間を独占しました。","Anh ấy đã chiếm hết thời gian."],["大きな会社が市場を独占しました。","Công ty lớn đã độc chiếm thị trường."],["独占はよくありません。","Độc chiếm là không tốt."]]},{"word":"一部上場","reading":"いちぶじょうじょう","meaning":"trong danh sách các công ty chính thức niêm yết quan trọng nhất trên sàn chứng khoán Tokyo.","hanViet":"NHẤT BỘ THƯỢNG TRƯỜNG","lesson":13,"ex":[["その会社は一部上場の会社です。","Công ty đó là công ty niêm yết sàn chính."],["一部上場の会社で働いています。","Tôi làm việc ở công ty niêm yết sàn chính."],["田中さんの会社は一部上場です。","Công ty của anh Tanaka niêm yết sàn chính."],["一部上場の会社は有名です。","Công ty niêm yết sàn chính rất nổi tiếng."],["その会社は一部上場しました。","Công ty đó đã niêm yết sàn chính."]]},{"word":"上場（する）","reading":"じょうじょう（する）","meaning":"niêm yết","hanViet":"THƯỢNG TRƯỜNG","lesson":13,"ex":[["その会社は上場しました。","Công ty đó đã niêm yết."],["上場する会社が増えています。","Số công ty niêm yết đang tăng."],["会社が上場するのは難しいです。","Việc công ty niêm yết thật khó."],["上場した会社は有名です。","Công ty đã niêm yết rất nổi tiếng."],["田中さんの会社は来年上場します。","Công ty của anh Tanaka sẽ niêm yết vào năm sau."]]},{"word":"思い込む","reading":"おもいこむ","meaning":"nghĩ rằng, cho rằng, nghĩ quá","hanViet":"TƯ","lesson":13,"ex":[["私は田中さんが先生だと思い込みました。","Tôi đã cho rằng anh Tanaka là thầy giáo."],["私は友達が来ると思い込みました。","Tôi đã cho rằng bạn sẽ đến."],["私は明日は休みだと思い込みました。","Tôi đã cho rằng ngày mai được nghỉ."],["思い込むのはよくありません。","Cho rằng như vậy là không tốt."],["私はその話が本当だと思い込みました。","Tôi đã cho rằng câu chuyện đó là thật."]]},{"word":"突っ走る","reading":"つっぱしる","meaning":"lao đầu chạy, cắm đầu cắm cổ chạy","hanViet":"ĐỘT TẨU","lesson":13,"ex":[["子どもが道を突っ走りました。","Đứa trẻ đã cắm đầu chạy trên đường."],["犬が公園を突っ走りました。","Con chó đã lao đi trong công viên."],["彼は駅まで突っ走りました。","Anh ấy đã cắm đầu chạy đến ga."],["子どもは家に突っ走りました。","Đứa trẻ đã lao về nhà."],["車が道を突っ走りました。","Ô tô đã lao đi trên đường."]]},{"word":"在日","reading":"ざいにち","meaning":"sống ở Nhật","hanViet":"TẠI NHẬT","lesson":13,"ex":[["在日の友達に会いました。","Tôi đã gặp bạn đang sống ở Nhật."],["在日の生活は楽しいです。","Cuộc sống ở Nhật thật vui."],["在日の日本語の勉強は大変です。","Việc học tiếng Nhật khi sống ở Nhật thật vất vả."],["在日の人は日本語が上手です。","Người sống ở Nhật giỏi tiếng Nhật."],["在日の仕事は大変です。","Công việc ở Nhật thật vất vả."]]},{"word":"とりあえず","reading":"","meaning":"trước tiên, trước hết","hanViet":"","lesson":13,"ex":[["とりあえず、座ってください。","Trước hết, hãy ngồi xuống."],["とりあえず、ごはんを食べましょう。","Trước hết, chúng ta ăn cơm nhé."],["とりあえず、休みましょう。","Trước hết, chúng ta nghỉ ngơi nhé."],["とりあえず、電話をします。","Trước hết, tôi sẽ gọi điện."],["とりあえず、本を読みます。","Trước hết, tôi sẽ đọc sách."]]},{"word":"観光物産館","reading":"かんこうぶっさんかん","meaning":"tòa nhà là nơi chỉ dẫn các thông tin du lịch và bày bán các đặc sản của địa phương.","hanViet":"QUAN QUANG VẬT SẢN QUÁN","lesson":13,"ex":[["観光物産館でお土産を買いました。","Tôi đã mua quà lưu niệm ở trung tâm du lịch đặc sản."],["観光物産館は駅の近くにあります。","Trung tâm du lịch đặc sản ở gần ga."],["観光物産館で観光の話を聞きました。","Tôi đã nghe thông tin du lịch ở trung tâm du lịch đặc sản."],["観光物産館には店があります。","Trong trung tâm du lịch đặc sản có cửa hàng."],["京都の観光物産館に行きました。","Tôi đã đến trung tâm du lịch đặc sản ở Kyoto."]]},{"word":"観光","reading":"かんこう","meaning":"tham quan, du lịch","hanViet":"QUAN QUANG","lesson":13,"ex":[["京都を観光しました。","Tôi đã đi tham quan Kyoto."],["観光で東京に来ました。","Tôi đến Tokyo để du lịch."],["観光の季節です。","Đây là mùa du lịch."],["観光で大阪に行きます。","Tôi đi Osaka để du lịch."],["観光が好きです。","Tôi thích du lịch."]]},{"word":"目に入る","reading":"めにはいる","meaning":"đập vào mắt","hanViet":"MỤC NHẬP","lesson":13,"ex":[["看板が目に入りました。","Biển hiệu đập vào mắt tôi."],["本が目に入りました。","Cuốn sách đập vào mắt tôi."],["広告が目に入りました。","Quảng cáo đập vào mắt tôi."],["花が目に入りました。","Hoa đập vào mắt tôi."],["店の名前が目に入りました。","Tên cửa hàng đập vào mắt tôi."]]},{"word":"国語辞典","reading":"こくごじてん","meaning":"từ điển quốc ngữ, từ điển tiếng Nhật","hanViet":"QUỐC NGỮ TỪ ĐIỂN","lesson":13,"ex":[["国語辞典で日本語の意味を見ます。","Tôi tra nghĩa tiếng Nhật trong từ điển quốc ngữ."],["国語辞典を買いました。","Tôi đã mua từ điển quốc ngữ."],["国語辞典は重いです。","Từ điển quốc ngữ nặng."],["国語辞典でことばを調べます。","Tôi tra từ trong từ điển quốc ngữ."],["国語辞典は部屋にあります。","Từ điển quốc ngữ ở trong phòng."]]},{"word":"忍ばせる","reading":"しのばせる","meaning":"giấu giếm","hanViet":"NHẪN","lesson":13,"ex":[["手紙をポケットに忍ばせました。","Tôi đã giấu bức thư vào túi áo."],["写真をかばんに忍ばせました。","Tôi đã giấu bức ảnh vào túi."],["本をかばんに忍ばせました。","Tôi đã giấu cuốn sách vào túi."],["お菓子をポケットに忍ばせました。","Tôi đã giấu kẹo vào túi áo."],["子どもは手紙を忍ばせました。","Đứa trẻ đã giấu bức thư."]]},{"word":"～ごと（つき～）","reading":"～ごと（つき～）","meaning":"hàng (tháng)","hanViet":"NGUYỆT","lesson":13,"ex":[["月ごとに本を買います。","Hàng tháng tôi mua sách."],["月ごとに試験があります。","Hàng tháng có kỳ thi."],["月ごとに友達に会います。","Hàng tháng tôi gặp bạn."],["週ごとに掃除します。","Hàng tuần tôi dọn dẹp."],["日ごとに日本語が上手になります。","Hàng ngày tiếng Nhật của tôi giỏi hơn."]]},{"word":"契約（する）","reading":"けいやく（する）","meaning":"làm hợp đồng","hanViet":"KHẾ ƯỚC","lesson":13,"ex":[["会社と契約をしました。","Tôi đã ký hợp đồng với công ty."],["部屋の契約をしました。","Tôi đã ký hợp đồng thuê phòng."],["契約の前に、よく読みました。","Trước khi ký hợp đồng, tôi đã đọc kỹ."],["仕事の契約をしました。","Tôi đã ký hợp đồng công việc."],["契約は来週です。","Việc ký hợp đồng là tuần sau."]]},{"word":"定義（する）","reading":"ていぎ（する）","meaning":"định nghĩa","hanViet":"ĐỊNH NGHĨA","lesson":13,"ex":[["ことばの定義を辞書で見ます。","Tôi xem định nghĩa của từ trong từ điển."],["先生は定義を教えてくれました。","Thầy giáo đã dạy tôi định nghĩa."],["この定義は難しいです。","Định nghĩa này khó."],["定義を読んで、意味がわかりました。","Đọc định nghĩa, tôi đã hiểu nghĩa."],["定義を紙に書きます。","Tôi viết định nghĩa ra giấy."]]},{"word":"慣用","reading":"かんよう","meaning":"cách dùng thông thường","hanViet":"QUÁN DỤNG","lesson":13,"ex":[["慣用的なことばを勉強します。","Tôi học cách dùng từ thông thường."],["慣用的な表現を覚えました。","Tôi đã nhớ cách diễn đạt thông thường."],["日本語の慣用を勉強しています。","Tôi đang học cách dùng thông thường của tiếng Nhật."],["慣用は辞書にあります。","Cách dùng thông thường có trong từ điển."],["慣用を覚えるのは難しいです。","Nhớ cách dùng thông thường thật khó."]]},{"word":"一瞬","reading":"いっしゅん","meaning":"khoảnh khắc, chốc lát","hanViet":"NHẤT THUẤN","lesson":13,"ex":[["一瞬、空が明るくなりました。","Trong khoảnh khắc, bầu trời sáng lên."],["一瞬、友達の顔が見えました。","Trong khoảnh khắc, tôi nhìn thấy khuôn mặt bạn."],["一瞬、静かになりました。","Trong khoảnh khắc, mọi thứ trở nên yên tĩnh."],["一瞬、電気が消えました。","Trong khoảnh khắc, điện đã tắt."],["一瞬、時間が止まりました。","Trong khoảnh khắc, thời gian như ngừng lại."]]},{"word":"パッと","reading":"","meaning":"trong chớp mắt, đột ngột","hanViet":"","lesson":13,"ex":[["パッと本を開きました。","Tôi mở sách ra trong chớp mắt."],["パッと友達を見ました。","Tôi liếc nhìn bạn trong chớp mắt."],["パッと笑いました。","Tôi bật cười trong chớp mắt."],["パッと顔が明るくなりました。","Khuôn mặt bỗng sáng lên trong chớp mắt."],["パッと窓を開けました。","Tôi mở cửa sổ ra trong chớp mắt."]]},{"word":"たとえ","reading":"","meaning":"cho dù, dù là","hanViet":"","lesson":13,"ex":[["たとえ雨が降っても、試合をします。","Cho dù trời mưa, trận đấu vẫn diễn ra."],["たとえ難しくても、最後まで続けます。","Cho dù khó, tôi cũng sẽ tiếp tục đến cuối."],["たとえ忙しくても、毎日日本語を勉強します。","Cho dù bận, tôi vẫn học tiếng Nhật mỗi ngày."],["たとえ遠くても、その店に行きます。","Cho dù xa, tôi cũng đến cửa hàng đó."],["たとえ失敗しても、あきらめません。","Cho dù thất bại, tôi cũng không bỏ cuộc."]]},{"word":"読み違える","reading":"よみちがえる","meaning":"đọc nhầm, đọc sai","hanViet":"ĐỘC VI","lesson":13,"ex":[["この漢字の読み方を読み違えました。","Tôi đã đọc nhầm cách đọc của chữ Hán này."],["私は名前を読み違えて、違う人に手紙を書きました。","Tôi đọc nhầm tên nên đã viết thư cho người khác."],["時間を読み違えて、約束に遅れました。","Tôi đọc nhầm giờ nên đã đến muộn buổi hẹn."],["子どもはこの文を読み違えました。","Đứa trẻ đã đọc sai câu này."],["数字を読み違えないでください。","Xin đừng đọc nhầm các con số."]]},{"word":"日々","reading":"ひび","meaning":"ngày ngày, hằng ngày, mỗi ngày","hanViet":"NHẬT","lesson":13,"ex":[["日々、日本語を勉強しています。","Ngày ngày, tôi học tiếng Nhật."],["日々の生活の中で、新しいことを学びます。","Trong cuộc sống hằng ngày, tôi học được những điều mới."],["日々忙しいですが、元気です。","Ngày ngày bận rộn nhưng tôi vẫn khỏe."],["日々、練習することが大切です。","Luyện tập hằng ngày là điều quan trọng."],["日々、新しい言葉を覚えています。","Mỗi ngày, tôi đều ghi nhớ từ mới."]]},{"word":"書き入れる","reading":"かきいれる","meaning":"điền vào, viết vào","hanViet":"THƯ NHẬP","lesson":13,"ex":[["この紙に名前を書き入れてください。","Hãy điền tên vào tờ giấy này."],["ノートに新しい言葉を書き入れました。","Tôi đã viết từ mới vào vở."],["カレンダーに予定を書き入れます。","Tôi viết lịch hẹn vào lịch."],["空いているところに答えを書き入れてください。","Hãy điền đáp án vào chỗ trống."],["日記に今日のことを書き入れました。","Tôi đã viết chuyện hôm nay vào nhật ký."]]},{"word":"かまわない","reading":"","meaning":"không sao, không vấn đề gì","hanViet":"","lesson":13,"ex":[["少し遅れてもかまわないよ。","Muộn một chút cũng không sao đâu."],["ここに座ってもかまいませんか。","Ngồi ở đây có được không?"],["雨が降ってもかまわないから、出かけましょう。","Trời mưa cũng không sao, chúng ta cứ ra ngoài thôi."],["一人で行ってもかまわないです。","Đi một mình cũng không sao."],["この本を借りてもかまいませんか。","Mượn cuốn sách này có được không?"]]},{"word":"書き留める","reading":"かきとめる","meaning":"viết ra, ghi chép lại","hanViet":"THƯ LƯU","lesson":13,"ex":[["大切なことをノートに書き留めました。","Tôi đã ghi lại những điều quan trọng vào vở."],["先生の話をよく聞いて、書き留めます。","Tôi lắng nghe lời thầy và ghi chép lại."],["忘れないように、紙に書き留めました。","Để không quên, tôi đã ghi lại ra giấy."],["旅行の思い出を日記に書き留めています。","Tôi đang ghi lại kỷ niệm du lịch vào nhật ký."],["会議の話を書き留めてください。","Hãy ghi lại câu chuyện trong cuộc họp."]]},{"word":"五月蠅い","reading":"うるさい","meaning":"ồn ào","hanViet":"NGŨ NGUYỆT DĂNG","lesson":13,"ex":[["隣の部屋が五月蠅くて、勉強できません。","Phòng bên cạnh ồn ào quá nên tôi không học được."],["子どもたちが五月蠅く遊んでいます。","Bọn trẻ đang chơi đùa ồn ào."],["夜遅くに五月蠅い音が聞こえました。","Đêm khuya tôi nghe thấy tiếng ồn ào."],["車の音が五月蠅いです。","Tiếng xe cộ ồn ào."],["五月蠅いから、少し静かにしてください。","Ồn quá, xin hãy yên lặng một chút."]]},{"word":"時雨","reading":"しぐれ","meaning":"mưa rào (cuối thu đầu đông)","hanViet":"THỜI VŨ","lesson":13,"ex":[["秋の終わりに時雨が降りました。","Cuối thu, mưa rào đã rơi."],["時雨が降って、空が暗くなりました。","Mưa rào rơi, bầu trời tối sầm lại."],["時雨の季節になりました。","Đã đến mùa mưa rào."],["朝は時雨でしたが、昼から晴れました。","Buổi sáng mưa rào nhưng từ trưa trời đã nắng."],["時雨がやんで、空が明るくなりました。","Mưa rào đã tạnh, bầu trời sáng lên."]]},{"word":"向日葵","reading":"ひまわり","meaning":"hoa hướng dương","hanViet":"HƯỚNG NHẬT QUỲ","lesson":13,"ex":[["夏になると、向日葵が咲きます。","Khi hè đến, hoa hướng dương nở."],["庭に大きな向日葵があります。","Trong vườn có hoa hướng dương lớn."],["向日葵は夏の花です。","Hoa hướng dương là hoa mùa hè."],["私は向日葵が好きです。","Tôi thích hoa hướng dương."],["向日葵の花がきれいですね。","Hoa hướng dương đẹp nhỉ."]]},{"word":"流れ（文章の～）","reading":"ながれ（ぶんしょうの～）","meaning":"mạch (mạch văn)","hanViet":"LƯU VĂN CHƯƠNG","lesson":13,"ex":[["この文章の流れがわかりにくいです。","Mạch văn của bài này khó hiểu."],["文章の流れをよく考えてから、書きました。","Tôi suy nghĩ kỹ mạch văn rồi mới viết."],["文章の流れが自然で、読みやすいです。","Mạch văn tự nhiên, dễ đọc."],["文章の流れに気をつけて、作文を書きます。","Tôi chú ý đến mạch văn khi viết bài văn."],["この小説は文章の流れが速くて、面白いです。","Tiểu thuyết này mạch văn nhanh, thú vị."]]},{"word":"ことわざ","reading":"","meaning":"tục ngữ","hanViet":"","lesson":13,"ex":[["日本のことわざを勉強しています。","Tôi đang học tục ngữ Nhật Bản."],["このことわざの意味がわかりません。","Tôi không hiểu nghĩa của câu tục ngữ này."],["ことわざは短い言葉で大切なことを教えます。","Tục ngữ dạy điều quan trọng bằng lời ngắn gọn."],["先生は授業でことわざを教えてくれました。","Thầy đã dạy tục ngữ trong giờ học."],["日本にはたくさんのことわざがあります。","Nhật Bản có rất nhiều tục ngữ."]]},{"word":"取り違える","reading":"とりちがえる","meaning":"hiểu sai, nhầm lẫn, lấy nhầm","hanViet":"THỦ VI","lesson":13,"ex":[["私は二人の名前を取り違えました。","Tôi đã nhầm lẫn tên của hai người."],["電話番号を取り違えて、違う人に電話しました。","Tôi nhầm số điện thoại nên đã gọi cho người khác."],["意味を取り違えないように、よく読みます。","Tôi đọc kỹ để không hiểu sai nghĩa."],["彼は私の言葉を取り違えました。","Anh ấy đã hiểu sai lời tôi nói."],["時間と場所を取り違えて、会えませんでした。","Tôi nhầm giờ và địa điểm nên đã không gặp được."]]},{"word":"情けは人のためならず","reading":"なさけはひとのためならず","meaning":"ở hiền gặp lành","hanViet":"TÌNH NHÂN","lesson":13,"ex":[["「情けは人のためならず」ということわざがあります。","Có câu tục ngữ \"Ở hiền gặp lành\"."],["情けは人のためならず、親切にすれば自分にもいいことがあります。","Ở hiền gặp lành, nếu đối xử tốt với người khác thì chính mình cũng gặp điều tốt."],["情けは人のためならずという言葉を覚えました。","Tôi đã ghi nhớ câu \"Ở hiền gặp lành\"."],["先生は「情けは人のためならず」と教えてくれました。","Thầy đã dạy tôi câu \"Ở hiền gặp lành\"."],["情けは人のためならず、人を助けることは大切です。","Ở hiền gặp lành, giúp đỡ người khác là điều quan trọng."]]},{"word":"お好み焼き","reading":"おこのみやき","meaning":"Okonomiyaki (một loại bánh bột chiên áp chảo với các thành phần chính là bột mì được bổ sung các thành phần như cá, thịt, rau, v.v)","hanViet":"HẢO THIÊU","lesson":13,"ex":[["大阪のお好み焼きは有名です。","Okonomiyaki của Osaka nổi tiếng."],["家でお好み焼きを作りました。","Tôi đã làm okonomiyaki ở nhà."],["お好み焼きを食べたことがありますか。","Bạn đã từng ăn okonomiyaki chưa?"],["友達とお好み焼きを食べに行きました。","Tôi đã đi ăn okonomiyaki với bạn."],["この店のお好み焼きはとてもおいしいです。","Okonomiyaki của quán này rất ngon."]]},{"word":"話題","reading":"わだい","meaning":"đề tài, chủ đề câu chuyện","hanViet":"THOẠI ĐỀ","lesson":13,"ex":[["最近の話題は新しい映画です。","Đề tài gần đây là bộ phim mới."],["そのニュースはみんなの話題になりました。","Tin tức đó đã trở thành đề tài của mọi người."],["話題が変わって、旅行の話になりました。","Đề tài thay đổi, chuyển sang chuyện du lịch."],["彼と話す話題がなくて、困りました。","Tôi không có đề tài gì để nói với anh ấy nên lúng túng."],["今日の話題は学校のことです。","Đề tài hôm nay là chuyện trường học."]]},{"word":"戻す","reading":"もどす","meaning":"đưa trở lại, trả lại","hanViet":"LỆ","lesson":13,"ex":[["本を元の場所に戻してください。","Hãy trả sách về chỗ cũ."],["借りたお金を戻しました。","Tôi đã trả lại số tiền đã mượn."],["時計の時間を戻しました。","Tôi đã chỉnh lùi giờ đồng hồ."],["子どもはおもちゃを箱に戻しました。","Đứa trẻ đã cất đồ chơi vào hộp."],["先生はテストを学生に戻しました。","Thầy đã trả bài kiểm tra cho học sinh."]]},{"word":"思い違い","reading":"おもいちがい","meaning":"sự hiểu lầm","hanViet":"TƯ VI","lesson":13,"ex":[["それは私の思い違いでした。","Đó là sự hiểu lầm của tôi."],["思い違いをしないように、よく聞いてください。","Hãy lắng nghe kỹ để không hiểu lầm."],["私の思い違いで、田中さんに迷惑をかけました。","Vì sự hiểu lầm của tôi mà tôi đã làm phiền anh Tanaka."],["場所についての思い違いがありました。","Có sự hiểu lầm về địa điểm."],["思い違いだったので、すぐに謝りました。","Vì là hiểu lầm nên tôi đã xin lỗi ngay."]]},{"word":"自分自身","reading":"じぶんじしん","meaning":"chính mình","hanViet":"TỰ PHÂN TỰ THÂN","lesson":13,"ex":[["自分自身を信じてください。","Hãy tin vào chính mình."],["自分自身で問題を考えました。","Tôi tự mình suy nghĩ về vấn đề."],["自分自身のことをよく知ることが大切です。","Hiểu rõ chính mình là điều quan trọng."],["彼女は自分自身で料理を作ります。","Cô ấy tự nấu ăn."],["自分自身を大切にしましょう。","Hãy trân trọng chính mình."]]},{"word":"わいわい","reading":"","meaning":"sôi nổi, vui vẻ","hanViet":"","lesson":13,"ex":[["子どもたちはわいわいと遊んでいます。","Bọn trẻ đang chơi đùa vui vẻ ồn ào."],["みんなでわいわいと料理を食べました。","Mọi người cùng ăn uống vui vẻ."],["パーティーではみんながわいわいと話していました。","Ở bữa tiệc, mọi người nói chuyện rôm rả."],["教室で学生がわいわいと話しています。","Trong lớp học, học sinh đang nói chuyện rôm rả."],["わいわいと楽しい一日でした。","Đó là một ngày vui vẻ rộn ràng."]]},{"word":"ホームパーティ","reading":"","meaning":"tiệc tại nhà","hanViet":"","lesson":13,"ex":[["土曜日にホームパーティをします。","Thứ bảy tôi sẽ tổ chức tiệc tại nhà."],["友達を家に呼んで、ホームパーティを開きました。","Tôi đã mời bạn đến nhà và mở tiệc tại nhà."],["ホームパーティで料理を作りました。","Tôi đã nấu ăn trong bữa tiệc tại nhà."],["ホームパーティに田中さんも来ました。","Anh Tanaka cũng đã đến dự tiệc tại nhà."],["来週、友達とホームパーティをします。","Tuần sau tôi sẽ tổ chức tiệc tại nhà với bạn bè."]]},{"word":"ぴったり","reading":"","meaning":"vừa khít, vừa vặn, khớp đúng","hanViet":"","lesson":13,"ex":[["この靴は足にぴったりです。","Đôi giày này vừa khít chân."],["この服は私にぴったり合います。","Bộ quần áo này rất hợp với tôi."],["帽子がぴったりでした。","Cái mũ vừa vặn."],["この部屋は二人で住むのにぴったりです。","Căn phòng này rất thích hợp cho hai người ở."],["予定の時間にぴったり着きました。","Tôi đã đến đúng giờ như dự định."]]},{"word":"どうにか","reading":"","meaning":"bằng cách nào đó","hanViet":"","lesson":13,"ex":[["どうにか宿題が終わりました。","Bằng cách nào đó bài tập đã xong."],["どうにか電車に間に合いました。","Bằng cách nào đó tôi đã kịp tàu."],["どうにか試験に合格しました。","Bằng cách nào đó tôi đã đỗ kỳ thi."],["どうにか雨が降る前に帰れました。","Bằng cách nào đó tôi đã về kịp trước khi trời mưa."],["どうにか一人で料理を作りました。","Bằng cách nào đó tôi đã tự nấu ăn một mình."]]},{"word":"直訳（する）","reading":"ちょくやく（する）","meaning":"trực dịch","hanViet":"TRỰC DỊCH","lesson":13,"ex":[["この文を直訳すると、意味がわかりにくいです。","Nếu dịch trực tiếp câu này thì khó hiểu nghĩa."],["直訳しないで、自然な日本語にしてください。","Đừng dịch trực tiếp, hãy dịch thành tiếng Nhật tự nhiên."],["ことわざを直訳すると、おかしい文になります。","Dịch trực tiếp tục ngữ thì thành câu kỳ lạ."],["彼は英語を直訳して、日本語にしました。","Anh ấy đã dịch trực tiếp tiếng Anh sang tiếng Nhật."],["直訳ではなく、意味を考えて日本語にします。","Không dịch trực tiếp mà suy nghĩ về nghĩa rồi chuyển sang tiếng Nhật."]]},{"word":"災い","reading":"わざわい","meaning":"điều không may mắn, tai họa","hanViet":"TAI","lesson":13,"ex":[["災いが起こらないように、気をつけます。","Tôi cẩn thận để tai họa không xảy ra."],["地震は大きな災いです。","Động đất là tai họa lớn."],["災いから家族を守りたいです。","Tôi muốn bảo vệ gia đình khỏi tai họa."],["地震のときは、災いから身を守ります。","Khi động đất, tôi bảo vệ bản thân khỏi tai họa."],["災いが起こったら、すぐに逃げてください。","Nếu tai họa xảy ra, hãy chạy ngay."]]},{"word":"遠ざける","reading":"とおざける","meaning":"để xa ra, tránh xa, giữ khoảng cách","hanViet":"VIỄN","lesson":13,"ex":[["悪いことを遠ざけるように、気をつけます。","Tôi cẩn thận để tránh xa điều xấu."],["災いを遠ざけるために、気をつけて生活します。","Để xua đi tai họa, tôi sống cẩn thận."],["彼は嫌なことを遠ざけます。","Anh ấy tránh xa những điều khó chịu."],["子どもを危ない場所から遠ざけてください。","Hãy để trẻ tránh xa nơi nguy hiểm."],["私は悪い友達を遠ざけました。","Tôi đã tránh xa những người bạn xấu."]]},{"word":"門","reading":"かど","meaning":"cổng","hanViet":"MÔN","lesson":13,"ex":[["学校の門の前に友達が待っていました。","Bạn tôi đang đợi trước cổng trường."],["門を開けると、大きな庭がありました。","Mở cổng ra, có một khu vườn lớn."],["その家の門は古いです。","Cổng của ngôi nhà đó cũ."],["門の近くに花が咲いています。","Gần cổng có hoa đang nở."],["門を出て、右に曲がると駅があります。","Ra khỏi cổng, rẽ phải sẽ thấy ga."]]},{"word":"福","reading":"ふく","meaning":"phúc lành","hanViet":"PHÚC","lesson":13,"ex":[["正月には福が来ますように。","Mong phúc lành đến trong ngày Tết."],["「笑う門には福来る」ということわざがあります。","Có câu tục ngữ \"Cười thì phúc đến\"."],["正月には福が来るといいですね。","Ngày Tết mong phúc lành đến thì tốt."],["福は笑う人に来ます。","Phúc đến với người hay cười."],["今年も福がたくさんありますように。","Mong năm nay cũng có thật nhiều phúc lành."]]},{"word":"結構（～多い）","reading":"けっこう（～おおい）","meaning":"khá (nhiều)","hanViet":"KẾT CẤU ĐA","lesson":13,"ex":[["今年は雨が結構多いです。","Năm nay mưa khá nhiều."],["このクラスには留学生が結構多いです。","Lớp này có khá nhiều du học sinh."],["この店には人が結構多いです。","Cửa hàng này có khá nhiều người."],["この映画を見た人は結構多いです。","Số người xem phim này khá nhiều."],["彼の家には本が結構多いです。","Nhà anh ấy có khá nhiều sách."]]},{"word":"辛党","reading":"からとう","meaning":"người thích uống rượu","hanViet":"TÂN ĐẢNG","lesson":13,"ex":[["父は辛党で、毎晩酒を飲みます。","Bố tôi thích rượu, tối nào cũng uống rượu."],["辛党の人は甘いものが苦手です。","Người thích rượu thường không thích đồ ngọt."],["田中さんは辛党なので、酒をあげました。","Anh Tanaka thích rượu nên tôi đã tặng rượu cho anh ấy."],["私は辛党ではありません。","Tôi không phải người thích rượu."],["辛党の山田さんは、酒が大好きです。","Anh Yamada là người thích rượu, rất mê uống rượu."]]},{"word":"甘党","reading":"あまとう","meaning":"người thích ăn đồ ngọt","hanViet":"CAM ĐẢNG","lesson":13,"ex":[["母は甘党で、ケーキが大好きです。","Mẹ tôi thích đồ ngọt, rất thích bánh ngọt."],["甘党の人は甘いお菓子をよく食べます。","Người thích đồ ngọt thường hay ăn bánh kẹo ngọt."],["私は甘党なので、チョコレートを買いました。","Tôi thích đồ ngọt nên đã mua sô-cô-la."],["甘党の田中さんに、ケーキをあげました。","Tôi đã tặng bánh cho anh Tanaka, người thích đồ ngọt."],["彼女は甘党ですが、辛いものは苦手です。","Cô ấy thích đồ ngọt nhưng không ăn được đồ cay."]]},{"word":"知ったかぶり","reading":"しったかぶり","meaning":"tỏ ra biết (dù thực sự không biết)","hanViet":"TRI","lesson":13,"ex":[["知ったかぶりをすると、恥ずかしいです。","Tỏ ra biết thì sẽ xấu hổ."],["知らないのに知ったかぶりをしてはいけません。","Không biết mà tỏ ra biết thì không được."],["彼は知ったかぶりが多くて、困ります。","Anh ấy hay tỏ ra biết nên tôi thấy khó xử."],["知ったかぶりをしないで、知らないと言いましょう。","Đừng tỏ ra biết, hãy nói là không biết."],["知ったかぶりをする人はあまり好きではありません。","Tôi không thích lắm người hay tỏ ra biết."]]},{"word":"一時","reading":"いっとき","meaning":"một lúc, chốc lát","hanViet":"NHẤT THỜI","lesson":13,"ex":[["一時、雨がやみました。","Một lúc, mưa đã tạnh."],["電車が一時止まりました。","Tàu dừng một lúc."],["一時、頭が痛くなりました。","Một lúc, đầu tôi đau."],["一時休んで、また勉強します。","Nghỉ một lúc rồi lại học tiếp."],["一時、空が暗くなりました。","Một lúc, bầu trời tối sầm."]]},{"word":"恥","reading":"はじ","meaning":"sự xấu hổ","hanViet":"SỈ","lesson":13,"ex":[["恥を知ることが大切です。","Biết xấu hổ là điều quan trọng."],["知らないことを聞くのは恥ではありません。","Hỏi điều mình không biết không phải là xấu hổ."],["うそをつくのは恥です。","Nói dối là điều xấu hổ."],["恥を忘れて、大きな声で歌いました。","Quên xấu hổ, tôi hát to."],["彼の失敗は恥ではありません。","Thất bại của anh ấy không phải là xấu hổ."]]},{"word":"関連（する）","reading":"かんれん（する）","meaning":"liên quan","hanViet":"QUAN LIÊN","lesson":13,"ex":[["この本は歴史に関連しています。","Cuốn sách này liên quan đến lịch sử."],["その仕事はコンピューターに関連します。","Công việc đó liên quan đến máy tính."],["健康に関連する本を読みました。","Tôi đã đọc sách liên quan đến sức khỏe."],["この二つの問題は関連しています。","Hai vấn đề này liên quan đến nhau."],["音楽に関連する仕事をしています。","Tôi đang làm công việc liên quan đến âm nhạc."]]},{"word":"広げる（話を～）","reading":"ひろげる（はなしを～）","meaning":"mở rộng (câu chuyện)","hanViet":"QUẢNG THOẠI","lesson":13,"ex":[["話を広げて、いろいろなことを話しました。","Tôi đã mở rộng câu chuyện, nói nhiều chuyện khác nhau."],["先生は話を広げて、面白い話をしました。","Thầy đã mở rộng câu chuyện và kể chuyện thú vị."],["話を広げるのが上手な人です。","Anh ấy là người giỏi mở rộng câu chuyện."],["話を広げすぎると、時間がかかります。","Mở rộng câu chuyện quá thì mất thời gian."],["彼は話を広げて、みんなを笑わせました。","Anh ấy mở rộng câu chuyện làm mọi người cười."]]},{"word":"ベストセラー","reading":"","meaning":"sách bán chạy","hanViet":"","lesson":13,"ex":[["この本はベストセラーになりました。","Cuốn sách này đã trở thành sách bán chạy."],["ベストセラーの小説を買いました。","Tôi đã mua tiểu thuyết bán chạy."],["そのベストセラーは世界中で読まれています。","Cuốn sách bán chạy đó được đọc trên khắp thế giới."],["このベストセラーは日本でも人気です。","Cuốn sách bán chạy này cũng được yêu thích ở Nhật."],["彼の本はベストセラーです。","Sách của anh ấy là sách bán chạy."]]},{"word":"コンパ","reading":"","meaning":"cuộc liên hoan","hanViet":"","lesson":13,"ex":[["今夜、クラスのコンパがあります。","Tối nay có buổi liên hoan của lớp."],["コンパで新しい友達ができました。","Tôi đã kết bạn mới ở buổi liên hoan."],["来週のコンパに参加します。","Tôi sẽ tham gia buổi liên hoan tuần sau."],["コンパは夜七時から始まります。","Buổi liên hoan bắt đầu từ 7 giờ tối."],["コンパでカラオケを歌いました。","Tôi đã hát karaoke ở buổi liên hoan."]]},{"word":"共感（する）","reading":"きょうかん（する）","meaning":"đồng cảm, cảm thông","hanViet":"CỘNG CẢM","lesson":13,"ex":[["彼の話に共感しました。","Tôi đã đồng cảm với câu chuyện của anh ấy."],["その意見に共感する人が多いです。","Có nhiều người đồng cảm với ý kiến đó."],["私は彼女の気持ちに共感します。","Tôi đồng cảm với cảm xúc của cô ấy."],["みんながその話に共感しました。","Mọi người đều đồng cảm với câu chuyện đó."],["共感してもらえて、うれしかったです。","Được đồng cảm, tôi rất vui."]]},{"word":"逆さま（な）","reading":"さかさま（な）","meaning":"ngược","hanViet":"NGHỊCH","lesson":13,"ex":[["絵が逆さまになっています。","Bức tranh bị treo ngược."],["本を逆さまに持ちました。","Tôi đã cầm sách ngược."],["逆さまの字が書いてあります。","Có chữ viết ngược."],["逆さまにしても、この絵は面白いです。","Dù lật ngược, bức tranh này vẫn thú vị."],["子どもは靴を逆さまにはきました。","Đứa trẻ đã đi giày ngược."]]},{"word":"言い換える","reading":"いいかえる","meaning":"nói bằng cách khác, diễn đạt lại cách khác","hanViet":"NGÔN HOÁN","lesson":13,"ex":[["難しい言葉を優しい言葉に言い換えました。","Tôi đã diễn đạt từ khó bằng từ dễ."],["その文を言い換えてください。","Hãy diễn đạt lại câu đó."],["言い換えれば、もっと練習しなければなりません。","Nói cách khác, cần phải luyện tập nhiều hơn."],["先生は答えを言い換えて説明しました。","Thầy đã diễn đạt lại đáp án để giải thích."],["その意味を別の言葉で言い換えます。","Tôi diễn đạt nghĩa đó bằng từ khác."]]},{"word":"知り合い","reading":"しりあい","meaning":"người quen","hanViet":"TRI HỢP","lesson":13,"ex":[["田中さんは私の知り合いです。","Anh Tanaka là người quen của tôi."],["知り合いに会うために、大阪に行きました。","Tôi đã đến Osaka để gặp người quen."],["その知り合いは東京に住んでいます。","Người quen đó sống ở Tokyo."],["知り合いが多くて、楽しいです。","Có nhiều người quen, thật vui."],["パーティーで新しい知り合いができました。","Tôi đã quen người mới ở bữa tiệc."]]},{"word":"石の上にも三年","reading":"いしのうえにもさんねん","meaning":"có chí thì nên","hanViet":"THẠCH THƯỢNG TAM NIÊN","lesson":13,"ex":[["「石の上にも三年」ということわざがあります。","Có câu tục ngữ \"Có chí thì nên\"."],["石の上にも三年、続ければ、できます。","Có chí thì nên, tiếp tục thì sẽ làm được."],["石の上にも三年という言葉を信じています。","Tôi tin vào câu \"Có chí thì nên\"."],["先生は「石の上にも三年」と言いました。","Thầy đã nói \"Có chí thì nên\"."],["石の上にも三年、続けることが大切です。","Có chí thì nên, tiếp tục là điều quan trọng."]]},{"word":"住めば都","reading":"すめばみやこ","meaning":"sống đâu quen đó","hanViet":"TRÚ ĐÔ","lesson":13,"ex":[["「住めば都」ということわざがあります。","Có câu tục ngữ \"Sống đâu quen đó\"."],["住めば都、新しい町にも慣れました。","Sống đâu quen đó, tôi đã quen với thị trấn mới."],["住めば都とよく言います。","Người ta thường nói \"Sống đâu quen đó\"."],["住めば都ですから、心配しないでください。","Sống đâu quen đó, xin đừng lo lắng."],["田舎に住んでも、住めば都です。","Dù sống ở quê, sống đâu quen đó."]]},{"word":"都","reading":"みやこ","meaning":"kinh đô, phố thị","hanViet":"ĐÔ","lesson":13,"ex":[["京都は古い都です。","Kyoto là kinh đô cổ."],["昔、都は京都にありました。","Ngày xưa, kinh đô ở Kyoto."],["都の生活は忙しいです。","Cuộc sống ở kinh đô bận rộn."],["都に大きな寺があります。","Ở kinh đô có ngôi chùa lớn."],["都から遠い村に住んでいます。","Tôi sống ở ngôi làng xa kinh đô."]]},{"word":"住み慣れる","reading":"すみなれる","meaning":"sống quen","hanViet":"TRÚ QUÁN","lesson":13,"ex":[["新しい町に住み慣れました。","Tôi đã sống quen ở thị trấn mới."],["東京の生活に住み慣れるまで時間がかかりました。","Phải mất thời gian mới sống quen với cuộc sống ở Tokyo."],["住み慣れた町を出るのは寂しいです。","Rời khỏi thị trấn đã sống quen thật buồn."],["子どもは新しい家に住み慣れました。","Đứa trẻ đã sống quen ở nhà mới."],["住み慣れるまで、少し時間がかかります。","Phải mất một chút thời gian mới sống quen được."]]},{"word":"猿も木から落ちる","reading":"さるもきからおちる","meaning":"nhân vô thập toàn","hanViet":"VIÊN MỘC LẠC","lesson":13,"ex":[["「猿も木から落ちる」ということわざがあります。","Có câu tục ngữ \"Nhân vô thập toàn\"."],["猿も木から落ちる、みんな失敗します。","Nhân vô thập toàn, ai cũng thất bại."],["先生でも猿も木から落ちることがあります。","Ngay cả thầy cũng có lúc sai sót."],["猿も木から落ちると言いますが、本当です。","Người ta nói \"Nhân vô thập toàn\", đúng thật."],["猿も木から落ちる、失敗を恐れないでください。","Nhân vô thập toàn, đừng sợ thất bại."]]},{"word":"木登り","reading":"きのぼり","meaning":"trèo cây","hanViet":"MỘC ĐĂNG","lesson":13,"ex":[["子どものとき、木登りが好きでした。","Hồi nhỏ tôi thích trèo cây."],["木登りをして、高い木に登りました。","Tôi đã trèo cây, leo lên cây cao."],["猿は木登りが上手です。","Khỉ giỏi trèo cây."],["木登りは危ないので、気をつけてください。","Trèo cây nguy hiểm nên hãy cẩn thận."],["子どもたちは公園で木登りをしています。","Bọn trẻ đang trèo cây ở công viên."]]},{"word":"～など","reading":"","meaning":"vân vân","hanViet":"","lesson":13,"ex":[["本やノートなどを買いました。","Tôi đã mua sách, vở vân vân."],["りんごやみかんなどを食べました。","Tôi đã ăn táo, quýt vân vân."],["映画や音楽などが好きです。","Tôi thích phim, nhạc vân vân."],["京都や大阪などを旅行しました。","Tôi đã du lịch Kyoto, Osaka vân vân."],["日本語や英語などを勉強しています。","Tôi đang học tiếng Nhật, tiếng Anh vân vân."]]},{"word":"しぼる","reading":"","meaning":"vắt","hanViet":"","lesson":13,"ex":[["レモンをしぼって、ジュースを作りました。","Tôi đã vắt chanh làm nước ép."],["タオルをしぼって、水を出しました。","Tôi vắt khăn cho ráo nước."],["オレンジをしぼりました。","Tôi đã vắt cam."],["タオルをよくしぼってください。","Hãy vắt kỹ khăn."],["みかんをしぼって、ジュースにしました。","Tôi đã vắt quýt làm nước ép."]]},{"word":"入社（する）","reading":"にゅうしゃ（する）","meaning":"vào công ty","hanViet":"NHẬP XÃ","lesson":13,"ex":[["来年、会社に入社します。","Năm sau tôi sẽ vào công ty."],["彼は大学を卒業して、入社しました。","Anh ấy tốt nghiệp đại học rồi vào công ty."],["入社してから、忙しい毎日です。","Từ khi vào công ty, ngày nào cũng bận."],["入社して、少し時間がたちました。","Từ khi vào công ty, đã trôi qua một chút thời gian."],["入社する前に、試験を受けました。","Trước khi vào công ty, tôi đã dự thi."]]},{"word":"口に出す","reading":"くちにだす","meaning":"nói ra","hanViet":"KHẨU XUẤT","lesson":13,"ex":[["思ったことを口に出して言いました。","Tôi đã nói ra điều mình nghĩ."],["口に出す前に、よく考えてください。","Trước khi nói ra, hãy suy nghĩ kỹ."],["彼は本当の気持ちを口に出しませんでした。","Anh ấy đã không nói ra cảm xúc thật."],["口に出して言えば、わかってもらえます。","Nếu nói ra, người ta sẽ hiểu."],["恥ずかしくて、口に出せませんでした。","Vì xấu hổ nên tôi đã không nói ra được."]]},{"word":"我慢（する）","reading":"がまん（する）","meaning":"chịu đựng","hanViet":"NGÃ MẠN","lesson":13,"ex":[["疲れても、我慢してください。","Dù mệt cũng hãy chịu đựng."],["我慢して、最後まで走りました。","Tôi đã chịu đựng và chạy đến cuối."],["暑いですが、我慢しています。","Trời nóng nhưng tôi đang chịu đựng."],["我慢することが大切です。","Chịu đựng là điều quan trọng."],["眠くても、我慢して勉強します。","Dù buồn ngủ, tôi vẫn chịu đựng để học."]]},{"word":"我慢強い","reading":"がまんづよい","meaning":"chịu đựng tốt, nhẫn nại","hanViet":"NGÃ MẠN CƯỜNG","lesson":13,"ex":[["彼は我慢強い人です。","Anh ấy là người nhẫn nại."],["我慢強い子どもは、泣きません。","Đứa trẻ nhẫn nại thì không khóc."],["母はとても我慢強いです。","Mẹ tôi rất nhẫn nại."],["我慢強い人になりたいです。","Tôi muốn trở thành người nhẫn nại."],["彼は我慢強くて、仕事を続けています。","Anh ấy nhẫn nại và vẫn tiếp tục công việc."]]},{"word":"掃除機","reading":"そうじき","meaning":"máy hút bụi","hanViet":"TẢO TRỪ CƠ","lesson":13,"ex":[["掃除機で部屋を掃除しました。","Tôi đã dùng máy hút bụi dọn phòng."],["新しい掃除機を買いました。","Tôi đã mua máy hút bụi mới."],["掃除機の音が大きいです。","Tiếng máy hút bụi lớn."],["掃除機が壊れました。","Máy hút bụi đã hỏng."],["毎日、掃除機で掃除します。","Mỗi ngày tôi dọn dẹp bằng máy hút bụi."]]},{"word":"ため息","reading":"ためいき","meaning":"thở dài","hanViet":"TỨC","lesson":13,"ex":[["彼は大きなため息をつきました。","Anh ấy thở dài một tiếng lớn."],["ため息をついて、窓の外を見ました。","Tôi thở dài rồi nhìn ra ngoài cửa sổ."],["疲れて、ため息が出ました。","Mệt quá, tôi thở dài."],["ため息をつくのはやめましょう。","Đừng thở dài nữa."],["試験が終わって、ため息をつきました。","Thi xong, tôi thở dài."]]},{"word":"あふれる","reading":"","meaning":"tràn ra, đầy tràn","hanViet":"","lesson":13,"ex":[["川の水があふれました。","Nước sông đã tràn ra."],["涙があふれました。","Nước mắt trào ra."],["公園は人であふれています。","Công viên đầy người."],["部屋に本があふれています。","Phòng đầy sách."],["町は祭りの人であふれていました。","Thị trấn đầy người đi lễ hội."]]},{"word":"たまる（ごみが～）","reading":"","meaning":"(rác) tích lại","hanViet":"","lesson":13,"ex":[["ごみがたまって、部屋が汚いです。","Rác tích lại nên phòng bẩn."],["ごみがたまる前に、捨てましょう。","Trước khi rác tích lại, hãy vứt đi."],["机の上にごみがたまっています。","Rác tích lại trên bàn."],["ごみがたまると、虫が来ます。","Rác tích lại thì côn trùng đến."],["少しの間に、ごみがたくさんたまりました。","Chỉ trong thời gian ngắn, rác đã tích lại rất nhiều."]]},{"word":"受験生","reading":"じゅけんせい","meaning":"thí sinh, người dự thi","hanViet":"THỤ NGHIỆM SINH","lesson":13,"ex":[["受験生は毎日勉強しています。","Thí sinh học mỗi ngày."],["兄は今年、受験生です。","Anh trai tôi năm nay là thí sinh."],["受験生の母は弁当を作ります。","Mẹ của thí sinh làm cơm hộp."],["受験生は試験の前に早く寝ます。","Thí sinh ngủ sớm trước kỳ thi."],["受験生は健康に気をつけます。","Thí sinh chú ý sức khỏe."]]},{"word":"都心","reading":"としん","meaning":"trung tâm thành phố","hanViet":"ĐÔ TÂM","lesson":13,"ex":[["都心に新しい店ができました。","Ở trung tâm thành phố có cửa hàng mới."],["都心の家賃は高いです。","Tiền thuê nhà ở trung tâm thành phố cao."],["都心まで電車で三十分かかります。","Đến trung tâm thành phố mất 30 phút đi tàu."],["都心で働いています。","Tôi làm việc ở trung tâm thành phố."],["都心の公園は人が多いです。","Công viên ở trung tâm thành phố đông người."]]},{"word":"双子","reading":"ふたご","meaning":"cặp sinh đôi, cặp song sinh","hanViet":"SONG TỬ","lesson":13,"ex":[["彼らは双子です。","Họ là cặp sinh đôi."],["双子の姉妹は同じ顔をしています。","Hai chị em sinh đôi có khuôn mặt giống nhau."],["双子の弟がいます。","Tôi có em trai sinh đôi."],["双子は同じ服を着ています。","Cặp sinh đôi mặc quần áo giống nhau."],["私の双子の妹は先生です。","Em gái sinh đôi của tôi là giáo viên."]]},{"word":"世界的（な）","reading":"せかいてき（な）","meaning":"tầm cỡ thế giới","hanViet":"THẾ GIỚI ĐÍCH","lesson":13,"ex":[["彼は世界的な歌手です。","Anh ấy là ca sĩ tầm cỡ thế giới."],["その本は世界的に有名です。","Cuốn sách đó nổi tiếng trên toàn thế giới."],["世界的な問題について話しました。","Chúng tôi đã nói về vấn đề tầm cỡ thế giới."],["彼女は世界的に有名な先生です。","Cô ấy là giáo viên nổi tiếng thế giới."],["世界的なスターに会いたいです。","Tôi muốn gặp ngôi sao tầm cỡ thế giới."]]},{"word":"スター","reading":"","meaning":"ngôi sao","hanViet":"","lesson":13,"ex":[["彼は有名なスターです。","Anh ấy là ngôi sao nổi tiếng."],["スターに会えて、うれしかったです。","Được gặp ngôi sao, tôi rất vui."],["そのスターは若い人に人気です。","Ngôi sao đó được người trẻ yêu thích."],["スターの写真を撮りました。","Tôi đã chụp ảnh ngôi sao."],["子どもはスターになりたいと言いました。","Đứa trẻ nói muốn trở thành ngôi sao."]]},{"word":"シーズン","reading":"","meaning":"mùa","hanViet":"","lesson":13,"ex":[["夏は海のシーズンです。","Mùa hè là mùa của biển."],["スキーのシーズンになりました。","Đã đến mùa trượt tuyết."],["シーズンが終わると、店が静かになります。","Mùa qua đi, cửa hàng trở nên yên tĩnh."],["桜のシーズンに京都に行きました。","Tôi đã đến Kyoto vào mùa hoa anh đào."],["このシーズンは雨が多いです。","Mùa này mưa nhiều."]]},{"word":"約～","reading":"やく～","meaning":"khoảng ~","hanViet":"ƯỚC","lesson":13,"ex":[["約百人が集まりました。","Khoảng 100 người đã tập trung."],["ここから駅まで約十分です。","Từ đây đến ga khoảng 10 phút."],["約一時間、日本語を勉強しました。","Tôi đã học tiếng Nhật khoảng 1 giờ."],["その本は約二千円です。","Cuốn sách đó khoảng 2000 yên."],["約半分の学生が試験に合格しました。","Khoảng một nửa số học sinh đã đỗ kỳ thi."]]},{"word":"割り","reading":"わり","meaning":"mười phần trăm","hanViet":"CÁT","lesson":13,"ex":[["「割り」は十分の一のことです。","Từ \"wari\" nghĩa là một phần mười."],["値段が二割安くなりました。","Giá đã rẻ đi 20%."],["本の三割が日本の本です。","30% số sách là sách Nhật."],["五割の学生がバスで来ます。","50% học sinh đến bằng xe buýt."],["八割の人がその映画を見ました。","80% số người đã xem bộ phim đó."]]},{"word":"休暇","reading":"きゅうか","meaning":"ngày nghỉ","hanViet":"HƯU HẠ","lesson":13,"ex":[["夏に休暇を取ります。","Mùa hè tôi sẽ nghỉ phép."],["休暇が終わって、仕事に戻りました。","Kỳ nghỉ kết thúc, tôi đã trở lại làm việc."],["休暇中は旅行をします。","Trong kỳ nghỉ tôi đi du lịch."],["長い休暇が欲しいです。","Tôi muốn kỳ nghỉ dài."],["休暇の日はゆっくり休みます。","Ngày nghỉ tôi nghỉ ngơi thong thả."]]},{"word":"いとこ","reading":"","meaning":"anh em họ","hanViet":"","lesson":13,"ex":[["いとこが東京に住んでいます。","Anh em họ của tôi sống ở Tokyo."],["いとこと遊びました。","Tôi đã chơi với anh em họ."],["私にはいとこが三人います。","Tôi có ba người anh em họ."],["いとこの結婚式に行きました。","Tôi đã đến dự đám cưới của anh em họ."],["いとこは私と同じ町に住んでいます。","Anh em họ sống cùng thị trấn với tôi."]]},{"word":"同士（いとこ～）","reading":"どうし","meaning":"giữa mấy (anh em họ), (anh em họ) với nhau","hanViet":"ĐỒNG SĨ","lesson":13,"ex":[["いとこ同士で旅行に行きました。","Mấy anh em họ đã cùng nhau đi du lịch."],["いとこ同士はよく遊びます。","Mấy anh em họ thường chơi với nhau."],["いとこ同士で誕生日のパーティーをしました。","Mấy anh em họ đã cùng tổ chức tiệc sinh nhật."],["いとこ同士、よく会います。","Mấy anh em họ thường gặp nhau."],["いとこ同士で写真を撮りました。","Mấy anh em họ đã cùng chụp ảnh."]]},{"word":"ルーズ（な）","reading":"","meaning":"cẩu thả, bê bối","hanViet":"","lesson":13,"ex":[["彼はルーズな性格です。","Anh ấy có tính cách cẩu thả."],["ルーズな服を着ています。","Tôi đang mặc quần áo rộng thùng thình."],["時間にルーズな人です。","Anh ấy là người cẩu thả về giờ giấc."],["ルーズに考えないで、しっかりしてください。","Đừng suy nghĩ cẩu thả, hãy nghiêm túc."],["彼の生活はルーズです。","Cuộc sống của anh ấy bê bối."]]},{"word":"売上げ","reading":"うりあげ","meaning":"doanh thu","hanViet":"MẠI THƯỢNG","lesson":13,"ex":[["売上げが増えました。","Doanh thu đã tăng."],["今年の売上げは去年より多いです。","Doanh thu năm nay nhiều hơn năm ngoái."],["売上げが下がって、困っています。","Doanh thu giảm nên tôi lo lắng."],["店の売上げを調べました。","Tôi đã kiểm tra doanh thu cửa hàng."],["売上げがよくて、うれしいです。","Doanh thu tốt, tôi rất vui."]]},{"word":"落ちる（売上げが～）","reading":"おちる（うりあげが～）","meaning":"(doanh thu) giảm sút","hanViet":"LẠC MẠI THƯỢNG","lesson":13,"ex":[["売上げが落ちました。","Doanh thu đã giảm sút."],["雨の日は売上げが落ちます。","Ngày mưa doanh thu giảm."],["売上げが落ちて、店が困っています。","Doanh thu giảm, cửa hàng gặp khó khăn."],["冬になると、売上げが落ちます。","Khi đông đến, doanh thu giảm."],["売上げが落ちないように、店をきれいにします。","Để doanh thu không giảm, tôi giữ cửa hàng sạch sẽ."]]},{"word":"工学部","reading":"こうがくぶ","meaning":"khoa kỹ thuật","hanViet":"CÔNG HỌC BỘ","lesson":13,"ex":[["彼は大学の工学部で勉強しています。","Anh ấy đang học ở khoa kỹ thuật của trường đại học."],["工学部に入りたいです。","Tôi muốn vào khoa kỹ thuật."],["兄は工学部を卒業しました。","Anh trai tôi đã tốt nghiệp khoa kỹ thuật."],["工学部の学生は実験が多いです。","Sinh viên khoa kỹ thuật có nhiều thí nghiệm."],["工学部で機械を勉強しています。","Tôi đang học về máy móc ở khoa kỹ thuật."]]},{"word":"入り直す","reading":"はいりなおす","meaning":"vào lại","hanViet":"NHẬP TRỰC","lesson":13,"ex":[["大学に入り直しました。","Tôi đã vào lại đại học."],["一度やめて、学校に入り直しました。","Tôi đã nghỉ một lần rồi vào lại trường."],["会社をやめて、大学に入り直すつもりです。","Tôi định nghỉ việc ở công ty rồi vào lại đại học."],["彼は高校に入り直しました。","Anh ấy đã vào lại trường cấp ba."],["入り直してから、毎日勉強しています。","Từ khi vào lại, tôi học mỗi ngày."]]},{"word":"関係（音楽～）","reading":"かんけい（おんがく～）","meaning":"liên quan đến (âm nhạc)","hanViet":"QUAN HỆ ÂM NHẠC","lesson":13,"ex":[["音楽関係の仕事をしています。","Tôi đang làm công việc liên quan đến âm nhạc."],["彼は音楽関係の会社で働いています。","Anh ấy làm việc ở công ty liên quan đến âm nhạc."],["音楽関係の本を読みました。","Tôi đã đọc sách liên quan đến âm nhạc."],["音楽関係の友達が多いです。","Tôi có nhiều bạn liên quan đến âm nhạc."],["音楽関係のイベントに参加しました。","Tôi đã tham gia sự kiện liên quan đến âm nhạc."]]},{"word":"ポテトチップス","reading":"","meaning":"khoai tây chiên giòn","hanViet":"","lesson":13,"ex":[["ポテトチップスを食べました。","Tôi đã ăn khoai tây chiên giòn."],["子どもはポテトチップスが好きです。","Trẻ em thích khoai tây chiên giòn."],["店でポテトチップスを買いました。","Tôi đã mua khoai tây chiên giòn ở cửa hàng."],["ポテトチップスを食べすぎました。","Tôi đã ăn quá nhiều khoai tây chiên giòn."],["ポテトチップスとジュースを買いました。","Tôi đã mua khoai tây chiên giòn và nước ép."]]},{"word":"インスタント食品","reading":"インスタントしょくひん","meaning":"thực phẩm ăn liền","hanViet":"THỰC PHẨM","lesson":13,"ex":[["インスタント食品をよく食べます。","Tôi thường ăn thực phẩm ăn liền."],["忙しいときはインスタント食品が便利です。","Khi bận, thực phẩm ăn liền rất tiện."],["インスタント食品を買って、家で食べました。","Tôi đã mua thực phẩm ăn liền và ăn ở nhà."],["インスタント食品は安くて、簡単です。","Thực phẩm ăn liền rẻ và đơn giản."],["インスタント食品の種類が多いです。","Có nhiều loại thực phẩm ăn liền."]]},{"word":"インスタント","reading":"","meaning":"ăn liền","hanViet":"","lesson":13,"ex":[["インスタントラーメンを食べました。","Tôi đã ăn mì ăn liền."],["インスタントコーヒーを飲みました。","Tôi đã uống cà phê hòa tan."],["インスタントのスープを作りました。","Tôi đã làm súp ăn liền."],["忙しい朝はインスタントコーヒーを飲みます。","Sáng bận rộn tôi uống cà phê hòa tan."],["インスタントのみそ汁を飲みました。","Tôi đã uống súp miso ăn liền."]]},{"word":"食品","reading":"しょくひん","meaning":"thực phẩm","hanViet":"THỰC PHẨM","lesson":13,"ex":[["この店は食品が安いです。","Cửa hàng này thực phẩm rẻ."],["食品を買いにスーパーに行きました。","Tôi đã đi siêu thị mua thực phẩm."],["安全な食品を選びます。","Tôi chọn thực phẩm an toàn."],["食品の値段が上がりました。","Giá thực phẩm đã tăng."],["冷蔵庫に食品がたくさんあります。","Trong tủ lạnh có nhiều thực phẩm."]]},{"word":"あきる","reading":"","meaning":"chán, ngấy","hanViet":"","lesson":13,"ex":[["毎日同じものを食べると、あきます。","Ăn cùng một món mỗi ngày thì sẽ chán."],["このゲームにあきました。","Tôi đã chán trò chơi này."],["同じ歌を聞くと、あきてしまいます。","Nghe cùng một bài hát thì sẽ chán."],["彼はすぐあきる人です。","Anh ấy là người mau chán."],["毎日同じ道を歩くと、あきます。","Đi cùng một con đường mỗi ngày thì sẽ chán."]]},{"word":"高みの見物","reading":"たかみのけんぶつ","meaning":"hóng, đứng từ xa ngó chuyện thiên hạ, làm như không liên quan","hanViet":"CAO KIẾN VẬT","lesson":13,"ex":[["高みの見物をしています。","Tôi đang đứng hóng chuyện thiên hạ."],["彼は高みの見物で、助けませんでした。","Anh ấy chỉ đứng ngó, không giúp đỡ."],["高みの見物をしないで、手伝ってください。","Đừng chỉ đứng ngó, hãy giúp tôi."],["高みの見物をしていたら、時間が過ぎました。","Đang đứng hóng thì thời gian trôi qua."],["みんなが高みの見物をしています。","Mọi người đều đang đứng ngó."]]},{"word":"気が置けない","reading":"きがおけない","meaning":"không cần giữ ý, không cần giữ kẽ","hanViet":"KHÍ TRÍ","lesson":13,"ex":[["田中さんは気が置けない友達です。","Tanaka là người bạn mà tôi không cần giữ kẽ."],["気が置けない友達と話すと、とても楽しいです。","Nói chuyện với người bạn không cần giữ kẽ thì rất vui."],["彼は気が置けない人なので、何でも話せます。","Anh ấy là người không cần giữ kẽ nên tôi có thể nói bất cứ chuyện gì."],["気が置けない友達がいて、うれしいです。","Tôi vui vì có người bạn không cần giữ kẽ."],["山田さんとは気が置けないので、よくごはんを食べます。","Tôi với Yamada không cần giữ kẽ nên thường ăn cơm cùng nhau."]]},{"word":"大家","reading":"おおや","meaning":"chủ nhà, người cho thuê nhà","hanViet":"ĐẠI GIA","lesson":13,"ex":[["大家さんが部屋を直してくれました。","Chủ nhà đã sửa phòng giúp tôi."],["大家さんに毎月お金を払います。","Tôi trả tiền cho chủ nhà mỗi tháng."],["大家さんは親切な人です。","Chủ nhà là người tốt bụng."],["部屋の問題を大家さんに話しました。","Tôi đã nói với chủ nhà về vấn đề của căn phòng."],["大家さんから電話がありました。","Có điện thoại từ chủ nhà."]]},{"word":"言い訳（する）","reading":"いいわけ（する）","meaning":"lí do lí trấu, biện bạch","hanViet":"NGÔN DỊCH","lesson":13,"ex":[["遅刻の言い訳を考えました。","Tôi đã nghĩ ra lý do biện bạch cho việc đi muộn."],["言い訳をしても、先生は信じてくれませんでした。","Dù tôi biện bạch, thầy cũng không tin."],["言い訳をしないで、謝りました。","Tôi không biện bạch mà xin lỗi."],["彼は言い訳をしましたが、だれも信じませんでした。","Anh ấy đã biện bạch nhưng không ai tin."],["言い訳をするより、すぐ仕事を終わらせましょう。","Thay vì biện bạch, hãy nhanh chóng hoàn thành công việc."]]},{"word":"手土産","reading":"てみやげ","meaning":"quà (mang theo khi đi thăm nhà ai)","hanViet":"THỦ THỔ SẢN","lesson":13,"ex":[["田中さんの家に行くとき、手土産を持っていきます。","Khi đến nhà Tanaka, tôi mang theo quà."],["手土産にケーキを買いました。","Tôi đã mua bánh làm quà mang theo."],["手土産をありがとうと言われました。","Tôi được nói cảm ơn vì món quà mang theo."],["手土産は果物がいいです。","Quà mang theo thì trái cây là tốt."],["友達の家に手土産を持っていきました。","Tôi đã mang quà đến nhà bạn."]]},{"word":"あったま、きちゃったな。","reading":"","meaning":"tức quá đi thôi! Điên quá!","hanViet":"","lesson":13,"ex":[["「あったま、きちゃったな。」と田中さんが言いました。","Tanaka nói: \"Tức quá đi thôi!\"."],["彼は遅刻して、「あったま、きちゃったな。」と言いました。","Anh ấy đi muộn và nói: \"Tức quá đi thôi!\"."],["仕事が終わらなくて、「あったま、きちゃったな。」と言いました。","Việc không xong nên tôi nói: \"Tức quá đi thôi!\"."],["電車が止まって、「あったま、きちゃったな。」と思いました。","Tàu dừng nên tôi nghĩ: \"Tức quá đi thôi!\"."],["「あったま、きちゃったな。」と彼は怒りました。","Anh ấy nổi giận nói: \"Tức quá đi thôi!\"."]]},{"word":"～奴（いい～）","reading":"～やつ","meaning":"gã, thằng (tốt bụng)","hanViet":"NÔ","lesson":13,"ex":[["田中さんはいい奴です。","Tanaka là gã tốt bụng."],["彼はほんとうにいい奴だと思います。","Tôi nghĩ anh ấy thực sự là gã tốt bụng."],["いい奴に会えて、うれしいです。","Tôi vui vì được gặp gã tốt bụng."],["山田さんはいい奴で、友達が多いです。","Yamada là gã tốt bụng nên có nhiều bạn."],["あの人はいい奴だから、信用できます。","Người đó là gã tốt bụng nên có thể tin tưởng."]]},{"word":"気にかける","reading":"きにかける","meaning":"bận lòng, bận tâm","hanViet":"KHÍ","lesson":13,"ex":[["母は私の健康を気にかけています。","Mẹ luôn bận tâm về sức khỏe của tôi."],["友達のことをいつも気にかけています。","Tôi luôn bận tâm về bạn bè."],["試験の結果を気にかけています。","Tôi đang bận tâm về kết quả kỳ thi."],["彼は人の気持ちを気にかけます。","Anh ấy bận tâm đến cảm xúc của người khác."],["学生の将来を気にかける先生が多いです。","Có nhiều thầy cô bận tâm về tương lai của học sinh."]]},{"word":"気を使う","reading":"きをつかう","meaning":"giữ kẽ, để ý","hanViet":"KHÍ SỬ","lesson":13,"ex":[["先生に気を使います。","Tôi giữ kẽ với thầy."],["彼は人に気を使う優しい人です。","Anh ấy là người tốt bụng, luôn để ý đến người khác."],["あまり気を使わないでください。","Đừng giữ kẽ quá nhé."],["初めて会う人に気を使います。","Tôi giữ kẽ với người mới gặp lần đầu."],["気を使いすぎて、疲れました。","Tôi giữ kẽ quá nên mệt."]]},{"word":"信用（する）","reading":"しんよう（する）","meaning":"tin tưởng, tin cậy","hanViet":"TÍN DỤNG","lesson":13,"ex":[["私は田中さんを信用しています。","Tôi tin tưởng Tanaka."],["彼は信用できる人です。","Anh ấy là người đáng tin."],["信用してもらうのは時間がかかります。","Để được tin tưởng thì cần thời gian."],["あの店を信用しています。","Tôi tin tưởng cửa hàng đó."],["信用されなくなると、仕事が難しくなります。","Khi không còn được tin tưởng nữa, công việc trở nên khó khăn."]]},{"word":"付き合う","reading":"つきあう","meaning":"quen, giao tiếp","hanViet":"PHÓ HỢP","lesson":13,"ex":[["田中さんと長く付き合っています。","Tôi quen Tanaka đã lâu."],["彼は山田さんと付き合っています。","Anh ấy đang quen Yamada."],["さまざまな人と付き合うのは楽しいです。","Quen biết nhiều người khác nhau thì vui."],["付き合う人を選ぶのは大切です。","Chọn người để quen biết là quan trọng."],["友達と付き合うときは、話すことが大切です。","Khi giao tiếp với bạn bè, việc nói chuyện là quan trọng."]]},{"word":"数えきれない","reading":"かぞえきれない","meaning":"vô số, không đếm xuể","hanViet":"SỐ","lesson":13,"ex":[["空には数えきれない星があります。","Trên trời có vô số ngôi sao."],["数えきれない人が駅にいました。","Có vô số người ở ga."],["数えきれない本が図書館にあります。","Trong thư viện có vô số sách."],["数えきれないほどの花が咲いています。","Có vô số hoa đang nở."],["海には数えきれない魚がいます。","Trong biển có vô số cá."]]},{"word":"シミュレーション","reading":"","meaning":"sự mô phỏng","hanViet":"","lesson":13,"ex":[["シミュレーションで地震の練習をしました。","Tôi đã luyện tập động đất bằng mô phỏng."],["コンピューターでシミュレーションをします。","Tôi mô phỏng bằng máy tính."],["シミュレーションの結果を見ました。","Tôi đã xem kết quả mô phỏng."],["先生がシミュレーションを使って説明しました。","Thầy đã dùng mô phỏng để giải thích."],["シミュレーションは勉強に使えます。","Mô phỏng có thể dùng để học."]]},{"word":"発言（する）","reading":"はつげん（する）","meaning":"phát ngôn, nói ra","hanViet":"PHÁT NGÔN","lesson":13,"ex":[["会議で発言しました。","Tôi đã phát biểu trong cuộc họp."],["彼は会議で初めて発言しました。","Anh ấy lần đầu phát biểu trong cuộc họp."],["発言する前に、よく考えます。","Tôi suy nghĩ kỹ trước khi phát biểu."],["みんなの前で発言するのは緊張します。","Phát biểu trước mọi người thì căng thẳng."],["発言の内容を書きました。","Tôi đã viết nội dung phát biểu."]]},{"word":"目にする","reading":"めにする","meaning":"xem","hanViet":"MỤC","lesson":13,"ex":[["新聞でそのニュースを目にしました。","Tôi đã thấy tin đó trên báo."],["町で珍しいものを目にしました。","Tôi đã thấy thứ hiếm ở phố."],["旅行で美しい景色を目にしました。","Trong chuyến đi, tôi đã thấy cảnh đẹp."],["本でおもしろい話を目にしました。","Tôi đã thấy câu chuyện thú vị trong sách."],["インターネットで新しい情報を目にしました。","Tôi đã thấy thông tin mới trên mạng."]]},{"word":"指摘（する）","reading":"してき（する）","meaning":"chỉ ra","hanViet":"CHỈ TRÍCH","lesson":13,"ex":[["先生が間違いを指摘しました。","Thầy đã chỉ ra lỗi sai."],["彼は問題を指摘しました。","Anh ấy đã chỉ ra vấn đề."],["指摘されて、初めてわかりました。","Được chỉ ra, tôi mới hiểu."],["友達が私の間違いを指摘してくれました。","Bạn đã chỉ ra lỗi sai của tôi."],["指摘する前に、よく聞きます。","Tôi nghe kỹ trước khi chỉ ra."]]},{"word":"傷つく","reading":"きずつく","meaning":"tổn thương","hanViet":"THƯƠNG","lesson":13,"ex":[["そのことばで傷つきました。","Tôi bị tổn thương bởi lời nói đó."],["友達に言われて、傷つきました。","Tôi bị bạn nói nên tổn thương."],["傷ついた心が治るには時間がかかります。","Để trái tim bị tổn thương lành lại cần thời gian."],["人の気持ちを傷つけないように気をつけます。","Tôi để ý để không làm tổn thương cảm xúc của người khác."],["傷ついたときは、友達に話します。","Khi bị tổn thương, tôi nói chuyện với bạn."]]},{"word":"不～（～愉快）","reading":"ふ～（～ゆかい）","meaning":"không (thoải mái)","hanViet":"BẤT DU KHOÁI","lesson":13,"ex":[["不愉快な気持ちになりました。","Tôi cảm thấy khó chịu."],["その話は不愉快でした。","Câu chuyện đó khó chịu."],["不愉快な経験をしました。","Tôi đã có trải nghiệm khó chịu."],["不愉快な顔をしないでください。","Đừng làm vẻ mặt khó chịu."],["不愉快なことがあって、すぐ帰りました。","Có chuyện khó chịu nên tôi về ngay."]]},{"word":"ふり","reading":"","meaning":"vờ, vờ như","hanViet":"","lesson":13,"ex":[["知らないふりをしました。","Tôi giả vờ không biết."],["寝たふりをして、電話に出ませんでした。","Tôi giả vờ ngủ nên không nghe điện thoại."],["彼は聞こえないふりをしました。","Anh ấy giả vờ không nghe thấy."],["笑っているふりをしました。","Tôi giả vờ đang cười."],["元気なふりをしましたけど、本当は疲れていました。","Tôi giả vờ khỏe nhưng thực ra đã mệt."]]},{"word":"～心（親切～）","reading":"～しん（しんせつ～）","meaning":"lòng (tốt)","hanViet":"TÂM THÂN THIẾT","lesson":13,"ex":[["親切心から手伝いました。","Tôi giúp đỡ vì lòng tốt."],["彼の親切心に感謝しています。","Tôi biết ơn lòng tốt của anh ấy."],["親切心で困っている人を助けました。","Tôi đã giúp người gặp khó khăn vì lòng tốt."],["親切心は大切です。","Lòng tốt là quan trọng."],["親切心を持つことはすばらしいです。","Có lòng tốt là tuyệt vời."]]},{"word":"～性（人間～）","reading":"～せい（にんげん～）","meaning":"(nhân) tính","hanViet":"TÍNH NHÂN GIAN","lesson":13,"ex":[["人間性を大切にします。","Tôi coi trọng nhân tính."],["彼の人間性が好きです。","Tôi thích nhân tính của anh ấy."],["人間性を育てることが大切です。","Nuôi dưỡng nhân tính là quan trọng."],["仕事より人間性が大切だと思います。","Tôi nghĩ nhân tính quan trọng hơn công việc."],["人間性を見ることが大切です。","Nhìn vào nhân tính là quan trọng."]]},{"word":"目下","reading":"めした","meaning":"người dưới","hanViet":"MỤC HẠ","lesson":13,"ex":[["目下の人を大切にします。","Tôi coi trọng cấp dưới."],["彼は目下に優しい上司です。","Anh ấy là cấp trên tốt bụng với cấp dưới."],["目下の意見を聞きます。","Tôi lắng nghe ý kiến của cấp dưới."],["目下の人を助けるのは上司の仕事です。","Giúp đỡ cấp dưới là công việc của cấp trên."],["目下の人を育てるのは大切です。","Nuôi dưỡng cấp dưới là quan trọng."]]},{"word":"なおさら","reading":"","meaning":"càng thêm","hanViet":"","lesson":13,"ex":[["雨が降って、なおさら寒くなりました。","Trời mưa nên càng thêm lạnh."],["忙しくて、なおさら疲れました。","Bận nên càng thêm mệt."],["彼の話を聞いて、なおさら会いたくなりました。","Nghe anh ấy nói, tôi càng muốn gặp hơn."],["安くなって、なおさら買いたくなりました。","Rẻ hơn nên tôi càng muốn mua."],["失敗して、なおさら勉強しました。","Thất bại nên tôi càng học nhiều hơn."]]},{"word":"外部","reading":"がいぶ","meaning":"bên ngoài","hanViet":"NGOẠI BỘ","lesson":13,"ex":[["外部の人と会いました。","Tôi đã gặp người bên ngoài."],["外部から意見をもらいました。","Tôi đã nhận ý kiến từ bên ngoài."],["外部の会社と協力します。","Tôi hợp tác với công ty bên ngoài."],["外部の情報を集めました。","Tôi đã thu thập thông tin bên ngoài."],["外部の目から見ると、会社は元気です。","Nhìn từ bên ngoài, công ty vẫn khỏe."]]},{"word":"クレーム","reading":"","meaning":"than phiền, phàn nàn","hanViet":"","lesson":13,"ex":[["店にクレームがありました。","Có phàn nàn ở cửa hàng."],["クレームを受けて、すぐ謝りました。","Nhận phàn nàn, tôi xin lỗi ngay."],["クレームの内容を聞きました。","Tôi đã nghe nội dung phàn nàn."],["クレームが少なくなりました。","Phàn nàn đã ít đi."],["クレームを聞いて、謝りました。","Tôi nghe phàn nàn rồi xin lỗi."]]},{"word":"何気ない","reading":"なにげない","meaning":"vô tình, không cố ý","hanViet":"HÀ KHÍ","lesson":13,"ex":[["何気ない一言がうれしかったです。","Một câu nói vô tình làm tôi vui."],["何気ない会話が楽しいです。","Cuộc trò chuyện vô tình thì vui."],["彼の何気ないことばがうれしかったです。","Lời nói vô tình của anh ấy làm tôi vui."],["何気ないことばに答えました。","Tôi đã trả lời lời nói vô tình."],["何気ないことばが人を助けます。","Lời nói vô tình giúp đỡ người khác."]]},{"word":"受け止める","reading":"うけとめる","meaning":"tiếp nhận, đón nhận (lời nói, cảm xúc, sự phê bình)","hanViet":"THỤ CHỈ","lesson":13,"ex":[["相手のことばを受け止めます。","Tôi tiếp nhận lời nói của đối phương."],["失敗を受け止めるのは難しいです。","Tiếp nhận thất bại thì khó."],["彼の意見を受け止めました。","Tôi đã tiếp nhận ý kiến của anh ấy."],["受け止める力が大切です。","Khả năng tiếp nhận là quan trọng."],["彼のことばを受け止めて、考えました。","Tôi tiếp nhận lời anh ấy rồi suy nghĩ."]]},{"word":"案ずるより産むがやすし","reading":"あんずるよりうむがやすし","meaning":"chỉ cần làm thử thì thấy đơn giản hơn mình nghĩ","hanViet":"ÁN SẢN","lesson":13,"ex":[["案ずるより産むがやすし、やってみましょう。","Cứ làm thử thì thấy dễ hơn mình nghĩ, hãy thử làm."],["試験は案ずるより産むがやすしです。","Kỳ thi thì cứ làm thử sẽ thấy dễ hơn mình nghĩ."],["案ずるより産むがやすしで、やってみたら簡単でした。","Đúng là cứ làm thử thì dễ hơn mình nghĩ, thử làm thì thấy đơn giản."],["新しい仕事は案ずるより産むがやすしでした。","Công việc mới thì cứ làm thử sẽ thấy dễ hơn mình nghĩ."],["案ずるより産むがやすしだから、心配しないでください。","Cứ làm thử thì dễ hơn mình nghĩ, nên đừng lo."]]},{"word":"反応（する）","reading":"はんのう（する）","meaning":"phản ứng","hanViet":"PHẢN ỨNG","lesson":13,"ex":[["彼の反応を見ました。","Tôi đã xem phản ứng của anh ấy."],["反応が速くて、うれしかったです。","Phản ứng nhanh nên tôi vui."],["学生の反応がおもしろいです。","Phản ứng của học sinh thú vị."],["反応しなかったので、また言いました。","Vì không có phản ứng nên tôi nói lại."],["いい反応がありました。","Có phản ứng tốt."]]},{"word":"伝わる","reading":"つたわる","meaning":"truyền đến","hanViet":"TRUYỀN","lesson":13,"ex":[["気持ちが伝わりました。","Cảm xúc đã truyền đến."],["彼のことばが心に伝わりました。","Lời anh ấy đã truyền đến trái tim."],["日本語が伝わるとうれしいです。","Tôi vui khi tiếng Nhật của mình được hiểu."],["ニュースが世界に伝わりました。","Tin tức đã truyền đến thế giới."],["声が遠くまで伝わりました。","Giọng nói truyền đến tận xa."]]},{"word":"実行（する）","reading":"じっこう（する）","meaning":"thực thi","hanViet":"THỰC HÀNH","lesson":13,"ex":[["計画を実行しました。","Tôi đã thực hiện kế hoạch."],["約束を実行するのは大切です。","Thực hiện lời hứa là quan trọng."],["実行する前に、よく考えます。","Tôi suy nghĩ kỹ trước khi thực hiện."],["実行してみたら、成功しました。","Thử thực hiện thì đã thành công."],["計画をすぐ実行しましょう。","Hãy thực hiện kế hoạch ngay."]]},{"word":"かかる（費用が～）","reading":"かかる（ひようが～）","meaning":"tốn (chi phí)","hanViet":"PHI DỤNG","lesson":13,"ex":[["費用がかかります。","Tốn chi phí."],["旅行に費用がかかります。","Đi du lịch tốn chi phí."],["費用がかかるので、よく考えます。","Vì tốn chi phí nên tôi suy nghĩ kỹ."],["費用がどのくらいかかるか聞きました。","Tôi đã hỏi chi phí tốn bao nhiêu."],["修理に費用がかかりました。","Sửa chữa đã tốn chi phí."]]},{"word":"テレビアニメ","reading":"テレビアニメ","meaning":"phim hoạt hình truyền hình","hanViet":"","lesson":14,"ex":[["テレビアニメが好きです。","Tôi thích phim hoạt hình truyền hình."],["学生のとき、テレビアニメをよく見ました。","Khi còn là học sinh, tôi thường xem phim hoạt hình truyền hình."],["テレビアニメの話を友達としました。","Tôi đã nói chuyện về phim hoạt hình truyền hình với bạn."],["新しいテレビアニメが始まります。","Phim hoạt hình truyền hình mới sắp bắt đầu."],["テレビアニメを見て、日本語を勉強します。","Tôi xem phim hoạt hình truyền hình để học tiếng Nhật."]]},{"word":"受ける","reading":"うける","meaning":"(phim hoạt hình) được đón nhận","hanViet":"THỤ","lesson":14,"ex":[["このテレビアニメは学生に受けています。","Phim hoạt hình truyền hình này được học sinh đón nhận."],["新しい番組が若者に受けています。","Chương trình mới được giới trẻ đón nhận."],["彼の歌はみんなに受けました。","Bài hát của anh ấy được mọi người đón nhận."],["そのアニメは世界中で受けています。","Phim hoạt hình đó được đón nhận trên toàn thế giới."],["受けている番組を教えてください。","Hãy cho tôi biết chương trình đang được đón nhận."]]},{"word":"解説文","reading":"かいせつぶん","meaning":"lời diễn giải","hanViet":"GIẢI THUYẾT VĂN","lesson":14,"ex":[["解説文を読みました。","Tôi đã đọc lời diễn giải."],["解説文がわかりやすいです。","Lời diễn giải dễ hiểu."],["解説文を書くのは難しいです。","Viết lời diễn giải thì khó."],["解説文を見ながら、絵を見ました。","Tôi vừa xem lời diễn giải vừa xem tranh."],["解説文で意味がわかりました。","Nhờ lời diễn giải mà tôi đã hiểu ý nghĩa."]]},{"word":"解説する","reading":"かいせつする","meaning":"diễn giải, giải thích","hanViet":"GIẢI THUYẾT","lesson":14,"ex":[["先生が問題を解説しました。","Thầy đã giải thích vấn đề."],["解説してください。","Hãy giải thích giúp tôi."],["彼は歴史を解説しました。","Anh ấy đã giải thích lịch sử."],["テレビで解説する人がいます。","Có người giải thích trên truyền hình."],["解説してもらって、よくわかりました。","Được giải thích nên tôi hiểu rõ."]]},{"word":"物事","reading":"ものごと","meaning":"sự việc","hanViet":"VẬT SỰ","lesson":14,"ex":[["物事をよく考えます。","Tôi suy nghĩ kỹ về sự việc."],["物事の見方が大切です。","Cách nhìn sự việc là quan trọng."],["物事を簡単に考えます。","Tôi suy nghĩ đơn giản về sự việc."],["物事を深く考えます。","Tôi suy nghĩ sâu về sự việc."],["物事の原因を調べます。","Tôi tìm hiểu nguyên nhân của sự việc."]]},{"word":"謎","reading":"なぞ","meaning":"điều bí ẩn","hanViet":"MÊ","lesson":14,"ex":[["謎がわかりました。","Tôi đã hiểu điều bí ẩn."],["謎の多い話です。","Là câu chuyện có nhiều điều bí ẩn."],["謎を考えるのが好きです。","Tôi thích suy nghĩ về điều bí ẩn."],["その謎はまだわかりません。","Điều bí ẩn đó vẫn chưa hiểu được."],["謎に興味があります。","Tôi có hứng thú với điều bí ẩn."]]},{"word":"美女","reading":"びじょ","meaning":"mỹ nữ, người con gái đẹp","hanViet":"MỸ NỮ","lesson":14,"ex":[["美女が映画に出ました。","Mỹ nữ đã xuất hiện trong phim."],["彼女は美女です。","Cô ấy là mỹ nữ."],["美女の写真を見ました。","Tôi đã xem ảnh mỹ nữ."],["美女と話しました。","Tôi đã nói chuyện với mỹ nữ."],["美女が町を歩いていました。","Mỹ nữ đang đi bộ trong phố."]]},{"word":"旅","reading":"たび","meaning":"chuyến đi, cuộc hành trình","hanViet":"LỮ","lesson":14,"ex":[["旅に出ました。","Tôi đã lên đường."],["楽しい旅でした。","Là chuyến đi vui vẻ."],["旅の思い出を話しました。","Tôi đã kể kỷ niệm của chuyến đi."],["一人で旅をしました。","Tôi đã đi một mình."],["旅が終わりました。","Chuyến đi đã kết thúc."]]},{"word":"ストーリーテリング","reading":"ストーリーテリング","meaning":"kể chuyện","hanViet":"","lesson":14,"ex":[["ストーリーテリングを勉強しています。","Tôi đang học kể chuyện."],["ストーリーテリングが上手な人です。","Anh ấy là người kể chuyện giỏi."],["ストーリーテリングで話すと、みんなが聞きます。","Khi tôi kể chuyện thì mọi người đều lắng nghe."],["ストーリーテリングの本を読みました。","Tôi đã đọc sách về kể chuyện."],["ストーリーテリングを練習します。","Tôi luyện tập kể chuyện."]]},{"word":"促す","reading":"うながす","meaning":"thúc đẩy, khuyến khích","hanViet":"XÚC","lesson":14,"ex":[["先生が生徒に勉強を促しました。","Thầy đã thúc giục học sinh học."],["彼にすぐ帰るよう促しました。","Tôi đã thúc giục anh ấy về ngay."],["参加を促すポスターがあります。","Có áp phích thúc giục tham gia."],["先生が意見を言うよう促しました。","Thầy đã thúc giục nói ra ý kiến."],["友達が参加を促してくれました。","Bạn đã thúc giục tôi tham gia."]]},{"word":"感想","reading":"かんそう","meaning":"cảm tưởng","hanViet":"CẢM TƯỞNG","lesson":14,"ex":[["感想を聞かせてください。","Hãy cho tôi nghe cảm tưởng của bạn."],["映画の感想を話しました。","Tôi đã nói cảm tưởng về phim."],["感想を書きました。","Tôi đã viết cảm tưởng."],["みんなの感想を聞きました。","Tôi đã nghe cảm tưởng của mọi người."],["感想を教えてください。","Hãy cho tôi biết cảm tưởng."]]},{"word":"アニメーション","reading":"アニメーション","meaning":"phim hoạt hình","hanViet":"","lesson":14,"ex":[["アニメーションが好きです。","Tôi thích phim hoạt hình."],["アニメーションの映画を見ました。","Tôi đã xem phim hoạt hình."],["アニメーションを作ります。","Tôi làm phim hoạt hình."],["アニメーションの勉強をしています。","Tôi đang học về phim hoạt hình."],["新しいアニメーションが始まります。","Phim hoạt hình mới sắp bắt đầu."]]},{"word":"放映する","reading":"ほうえいする","meaning":"phát sóng, chiếu","hanViet":"PHÓNG ÁNH","lesson":14,"ex":[["テレビで番組を放映します。","Đài phát sóng chương trình trên truyền hình."],["映画を放映しました。","Đài đã phát sóng phim."],["毎週放映する番組です。","Là chương trình phát sóng mỗi tuần."],["夜に番組を放映します。","Đài phát sóng chương trình vào buổi tối."],["放映する時間を知っています。","Tôi biết thời gian phát sóng."]]},{"word":"シリーズ","reading":"シリーズ","meaning":"xê-ri, loạt","hanViet":"","lesson":14,"ex":[["このシリーズを見ました。","Tôi đã xem loạt phim này."],["新しいシリーズが始まりました。","Loạt phim mới đã bắt đầu."],["シリーズを全部見ました。","Tôi đã xem hết loạt phim."],["このシリーズが好きです。","Tôi thích loạt phim này."],["シリーズを楽しみにしています。","Tôi đang mong chờ loạt phim."]]},{"word":"代","reading":"だい","meaning":"những năm (1960)","hanViet":"ĐẠI","lesson":14,"ex":[["1960年代の音楽が好きです。","Tôi thích âm nhạc những năm 1960."],["1980年代に生まれました。","Tôi sinh ra vào những năm 1980."],["1990年代の映画を見ました。","Tôi đã xem phim những năm 1990."],["1960年代のテレビアニメはおもしろいです。","Phim hoạt hình truyền hình những năm 1960 thú vị."],["1970年代の歌を聞きます。","Tôi nghe bài hát những năm 1970."]]},{"word":"番組","reading":"ばんぐみ","meaning":"chương trình","hanViet":"PHIÊN TỔ","lesson":14,"ex":[["番組を見ました。","Tôi đã xem chương trình."],["おもしろい番組があります。","Có chương trình thú vị."],["番組の時間を知っています。","Tôi biết thời gian chương trình."],["ニュースの番組を見ます。","Tôi xem chương trình tin tức."],["番組を見て、友達と話しました。","Tôi xem chương trình rồi nói chuyện với bạn."]]},{"word":"編成する","reading":"へんせいする","meaning":"tổ chức, xây dựng","hanViet":"BIÊN THÀNH","lesson":14,"ex":[["番組を編成します。","Tôi tổ chức chương trình."],["会社が番組を編成します。","Công ty tổ chức chương trình."],["編成するのが仕事です。","Tổ chức là công việc."],["新しい番組を編成しました。","Tôi đã tổ chức chương trình mới."],["編成の会議がありました。","Có cuộc họp về tổ chức."]]},{"word":"～際","reading":"～さい","meaning":"khi ~, lúc ~","hanViet":"TẾ","lesson":14,"ex":[["旅行の際、パスポートを持っていきます。","Khi đi du lịch, tôi mang theo hộ chiếu."],["入学の際、先生に会いました。","Khi nhập học, tôi đã gặp thầy."],["会議の際、意見を言いました。","Khi họp, tôi đã nói ý kiến."],["買い物の際、財布を忘れました。","Khi đi mua sắm, tôi quên ví."],["卒業の際、先生に感謝しました。","Khi tốt nghiệp, tôi đã cảm ơn thầy."]]},{"word":"穴埋め","reading":"あなうめ","meaning":"lấp chỗ trống","hanViet":"HUYỆT MAI","lesson":14,"ex":[["穴埋めの問題に答えました。","Tôi đã trả lời câu hỏi điền vào chỗ trống."],["穴埋めの練習をしました。","Tôi đã luyện tập điền vào chỗ trống."],["穴埋めが苦手です。","Tôi kém điền vào chỗ trống."],["穴埋めの試験がありました。","Có kỳ thi điền vào chỗ trống."],["穴埋めをしてみましょう。","Hãy thử điền vào chỗ trống."]]},{"word":"年月","reading":"ねんげつ","meaning":"năm tháng, thời gian","hanViet":"NIÊN NGUYỆT","lesson":14,"ex":[["長い年月が過ぎました。","Thời gian dài đã trôi qua."],["年月がかかる仕事です。","Là công việc tốn nhiều năm tháng."],["年月が過ぎると、町が変わります。","Thời gian trôi qua, phố thay đổi."],["年月が過ぎて、町が大きくなりました。","Thời gian trôi qua, phố đã lớn hơn."],["長い年月がかかりました。","Đã tốn nhiều năm tháng."]]},{"word":"経る","reading":"へる","meaning":"trôi qua","hanViet":"KINH","lesson":14,"ex":[["長い年月を経て、町が変わりました。","Trải qua thời gian dài, phố đã thay đổi."],["時間を経て、気持ちが変わりました。","Trải qua thời gian, cảm xúc đã thay đổi."],["長い時間を経ました。","Tôi đã trải qua thời gian dài."],["年月を経て、日本語が上手になりました。","Trải qua năm tháng, tiếng Nhật đã giỏi hơn."],["経験を経て、強くなりました。","Trải qua kinh nghiệm, tôi đã mạnh mẽ hơn."]]},{"word":"存在する","reading":"そんざいする","meaning":"có mặt, tồn tại","hanViet":"TỒN TẠI","lesson":14,"ex":[["そこに存在するものを見ました。","Tôi đã thấy thứ tồn tại ở đó."],["存在することが大切です。","Việc tồn tại là quan trọng."],["存在しないものは見えません。","Thứ không tồn tại thì không thấy được."],["彼の存在の意味を考えます。","Tôi suy nghĩ về ý nghĩa sự tồn tại của anh ấy."],["存在するだけでうれしいです。","Chỉ tồn tại thôi cũng vui rồi."]]},{"word":"無視する","reading":"むしする","meaning":"bỏ qua, vờ như không thấy","hanViet":"VÔ THỊ","lesson":14,"ex":[["彼を無視しました。","Tôi đã phớt lờ anh ấy."],["無視しないでください。","Đừng phớt lờ."],["メールを無視しました。","Tôi đã phớt lờ email."],["無視されて、悲しくなりました。","Bị phớt lờ nên tôi buồn."],["先生のことばを無視してはいけません。","Không được phớt lờ lời thầy."]]},{"word":"語る","reading":"かたる","meaning":"nói về, kể về","hanViet":"NGỮ","lesson":14,"ex":[["昔の話を語りました。","Tôi đã kể chuyện ngày xưa."],["彼は旅の思い出を語りました。","Anh ấy đã kể kỷ niệm chuyến đi."],["語ることが多いです。","Có nhiều chuyện để kể."],["母が昔のことを語りました。","Mẹ đã kể chuyện ngày xưa."],["夢を語るのが好きです。","Tôi thích kể về ước mơ."]]},{"word":"作品","reading":"さくひん","meaning":"tác phẩm","hanViet":"TÁC PHẨM","lesson":14,"ex":[["作品を見ました。","Tôi đã xem tác phẩm."],["新しい作品ができました。","Tác phẩm mới đã hoàn thành."],["作品の感想を書きました。","Tôi đã viết cảm tưởng về tác phẩm."],["彼の作品が好きです。","Tôi thích tác phẩm của anh ấy."],["作品を作るのは楽しいです。","Làm tác phẩm thì vui."]]},{"word":"原作","reading":"げんさく","meaning":"nguyên tác","hanViet":"NGUYÊN TÁC","lesson":14,"ex":[["原作を読みました。","Tôi đã đọc nguyên tác."],["原作と映画は違います。","Nguyên tác và phim khác nhau."],["原作のほうがおもしろいです。","Nguyên tác thú vị hơn."],["原作を知っています。","Tôi biết nguyên tác."],["原作をもとに映画を作りました。","Tôi đã làm phim dựa trên nguyên tác."]]},{"word":"支える","reading":"ささえる","meaning":"hỗ trợ, duy trì","hanViet":"CHI","lesson":14,"ex":[["家族を支えます。","Tôi hỗ trợ gia đình."],["友達を支えるのは大切です。","Hỗ trợ bạn bè là quan trọng."],["彼がチームを支えています。","Anh ấy đang hỗ trợ đội."],["支えてくれて、ありがとう。","Cảm ơn vì đã hỗ trợ."],["経済を支える仕事です。","Là công việc hỗ trợ kinh tế."]]},{"word":"マンガ家","reading":"マンガか","meaning":"họa sĩ vẽ truyện tranh","hanViet":"GIA","lesson":14,"ex":[["マンガ家になりたいです。","Tôi muốn trở thành họa sĩ truyện tranh."],["有名なマンガ家です。","Là họa sĩ truyện tranh nổi tiếng."],["マンガ家に会いました。","Tôi đã gặp họa sĩ truyện tranh."],["マンガ家の仕事は大変です。","Công việc của họa sĩ truyện tranh vất vả."],["マンガ家が新しい作品を作りました。","Họa sĩ truyện tranh đã làm tác phẩm mới."]]},{"word":"層","reading":"そう","meaning":"lớp","hanViet":"TẦNG","lesson":14,"ex":[["若い層に人気があります。","Được yêu thích ở lớp trẻ."],["若い層も大人の層も見ています。","Cả lớp trẻ lẫn lớp người lớn đều xem."],["さまざまな層の人が見ています。","Nhiều lớp người khác nhau đang xem."],["層によって人気が違います。","Tùy theo lớp mà mức độ yêu thích khác nhau."],["広い層に人気があります。","Được yêu thích ở nhiều tầng lớp."]]},{"word":"暑さ","reading":"あつさ","meaning":"sự nóng bức, cái nóng","hanViet":"THỬ","lesson":14,"ex":[["暑さが厳しいです。","Cái nóng gay gắt."],["暑さに負けないでください。","Đừng thua cái nóng nhé."],["夏の暑さが好きではありません。","Tôi không thích cái nóng mùa hè."],["暑さで疲れました。","Tôi mệt vì nóng."],["暑さを忘れるために、プールに行きました。","Tôi đến bể bơi để quên cái nóng."]]},{"word":"発売する","reading":"はつばいする","meaning":"phát hành, bán ra","hanViet":"PHÁT MẠI","lesson":14,"ex":[["新しい本が発売されました。","Sách mới đã phát hành."],["発売する日を楽しみにしています。","Tôi đang mong chờ ngày phát hành."],["新しい映画が発売されました。","Phim mới đã được phát hành."],["発売日に店に行きました。","Tôi đã đến cửa hàng vào ngày phát hành."],["来月、新しい本を発売します。","Tháng sau sẽ phát hành sách mới."]]},{"word":"週刊誌","reading":"しゅうかんし","meaning":"báo ra hàng tuần, tuần san","hanViet":"CHU SAN CHÍ","lesson":14,"ex":[["週刊誌を買いました。","Tôi đã mua tuần san."],["週刊誌を毎週読みます。","Tôi đọc tuần san mỗi tuần."],["週刊誌の記事を読みました。","Tôi đã đọc bài báo trên tuần san."],["週刊誌の値段は安いです。","Giá tuần san rẻ."],["週刊誌でニュースを読みます。","Tôi đọc tin tức trên tuần san."]]},{"word":"月刊誌","reading":"げっかんし","meaning":"báo ra hàng tháng, nguyệt san","hanViet":"NGUYỆT SAN CHÍ","lesson":14,"ex":[["月刊誌を買いました。","Tôi đã mua nguyệt san."],["月刊誌を毎月読みます。","Tôi đọc nguyệt san mỗi tháng."],["月刊誌の記事がおもしろいです。","Bài báo trên nguyệt san thú vị."],["月刊誌を図書館で読みます。","Tôi đọc nguyệt san ở thư viện."],["月刊誌が来月発売されます。","Nguyệt san sẽ phát hành tháng sau."]]},{"word":"～誌","reading":"～し","meaning":"báo ~","hanViet":"CHÍ","lesson":14,"ex":[["雑誌を買いました。","Tôi đã mua tạp chí."],["スポーツ誌を読みます。","Tôi đọc tạp chí thể thao."],["経済誌を読みます。","Tôi đọc tạp chí kinh tế."],["女性誌を見ました。","Tôi đã xem tạp chí phụ nữ."],["情報誌を買いました。","Tôi đã mua tạp chí thông tin."]]},{"word":"種類","reading":"しゅるい","meaning":"chủng loại, loại","hanViet":"CHỦNG LOẠI","lesson":14,"ex":[["種類が多いです。","Có nhiều loại."],["さまざまな種類があります。","Có nhiều loại khác nhau."],["種類を選ぶのは楽しいです。","Chọn loại thì vui."],["種類によって値段が違います。","Tùy theo loại mà giá khác nhau."],["新しい種類が出ました。","Loại mới đã ra."]]},{"word":"単行本","reading":"たんこうばん","meaning":"sách phát hành đơn lẻ không theo bộ","hanViet":"ĐƠN HÀNH BẢN","lesson":14,"ex":[["単行本を買いました。","Tôi đã mua sách đơn lẻ."],["単行本が発売されました。","Sách đơn lẻ đã phát hành."],["単行本を集めています。","Tôi đang sưu tầm sách đơn lẻ."],["単行本で読みます。","Tôi đọc bằng sách đơn lẻ."],["単行本を友達に貸しました。","Tôi đã cho bạn mượn sách đơn lẻ."]]},{"word":"新作","reading":"しんさく","meaning":"tác phẩm mới","hanViet":"TÂN TÁC","lesson":14,"ex":[["新作が発売されました。","Tác phẩm mới đã phát hành."],["新作を楽しみにしています。","Tôi đang mong chờ tác phẩm mới."],["新作の映画を見ました。","Tôi đã xem phim mới."],["新作が出ました。","Tác phẩm mới đã ra."],["新作の感想を書きました。","Tôi đã viết cảm tưởng về tác phẩm mới."]]},{"word":"～部","reading":"～ぶ","meaning":"bản (đơn vị đếm sách, báo, tạp chí)","hanViet":"BỘ","lesson":14,"ex":[["100万部売れました。","Đã bán được 1 triệu bản."],["10万部売れました。","Đã bán được 100 nghìn bản."],["100部買いました。","Tôi đã mua 100 bản."],["1万部売れた本です。","Là cuốn sách bán được 10 nghìn bản."],["何部売れましたか。","Đã bán được bao nhiêu bản?"]]},{"word":"ヒット作品","reading":"ヒットさくひん","meaning":"tác phẩm hit, tác phẩm được quan tâm hàng đầu","hanViet":"TÁC PHẨM","lesson":14,"ex":[["ヒット作品を見ました。","Tôi đã xem tác phẩm hit."],["ヒット作品が好きです。","Tôi thích tác phẩm hit."],["新しいヒット作品が出ました。","Tác phẩm hit mới đã ra."],["ヒット作品の感想を書きました。","Tôi đã viết cảm tưởng về tác phẩm hit."],["ヒット作品を教えてください。","Hãy cho tôi biết tác phẩm hit."]]},{"word":"ヒットする","reading":"ヒットする","meaning":"hit, được quan tâm hàng đầu","hanViet":"","lesson":14,"ex":[["この歌がヒットしました。","Bài hát này đã hit."],["新しい映画がヒットしています。","Phim mới đang hit."],["ヒットするかどうかわかりません。","Tôi không biết có hit hay không."],["ヒットしたら、うれしいです。","Nếu hit thì tôi vui."],["ヒットする作品を作りたいです。","Tôi muốn làm tác phẩm hit."]]},{"word":"エンターテインメント","reading":"エンターテインメント","meaning":"giải trí","hanViet":"","lesson":14,"ex":[["エンターテインメントが好きです。","Tôi thích giải trí."],["エンターテインメントの世界で働きたいです。","Tôi muốn làm việc trong thế giới giải trí."],["エンターテインメントは楽しいです。","Giải trí thì vui."],["エンターテインメントの番組を見ます。","Tôi xem chương trình giải trí."],["エンターテインメントについて勉強します。","Tôi học về giải trí."]]},{"word":"プロ","reading":"プロ","meaning":"nhà nghề, chuyên nghiệp","hanViet":"","lesson":14,"ex":[["プロになりたいです。","Tôi muốn trở thành nhà nghề."],["プロの選手です。","Là tuyển thủ nhà nghề."],["プロの仕事は大変です。","Công việc nhà nghề vất vả."],["プロの歌を聞きました。","Tôi đã nghe bài hát của ca sĩ nhà nghề."],["プロに教えてもらいました。","Tôi được nhà nghề dạy."]]},{"word":"～ごとく","reading":"～ごとく","meaning":"giống như, hệt như","hanViet":"","lesson":14,"ex":[["夢のごとく美しい景色でした。","Là cảnh đẹp như trong mơ."],["男の子のごとく笑いました。","Tôi cười như cậu bé."],["雪のごとく白い花が咲きました。","Hoa trắng như tuyết đã nở."],["映画のごとくおもしろい話でした。","Là câu chuyện thú vị như phim."],["星のごとく美しい海を見ました。","Tôi đã thấy biển đẹp như sao."]]},{"word":"巨大","reading":"きょだい","meaning":"khổng lồ","hanViet":"CỰ ĐẠI","lesson":14,"ex":[["巨大な建物があります。","Có tòa nhà khổng lồ."],["巨大な魚を見ました。","Tôi đã thấy cá khổng lồ."],["巨大な山が見えます。","Nhìn thấy núi khổng lồ."],["巨大な船に乗りました。","Tôi đã lên con tàu khổng lồ."],["巨大な木があります。","Có cây khổng lồ."]]},{"word":"競争原理","reading":"きょうそうげんり","meaning":"nguyên lí cạnh tranh","hanViet":"CẠNH TRANH NGUYÊN LÝ","lesson":14,"ex":[["競争原理を勉強します。","Tôi học nguyên lí cạnh tranh."],["競争原理について話しました。","Tôi đã nói về nguyên lí cạnh tranh."],["競争原理が働いています。","Nguyên lí cạnh tranh đang hoạt động."],["競争原理の意味がわかりました。","Tôi đã hiểu ý nghĩa của nguyên lí cạnh tranh."],["競争原理の本を読みました。","Tôi đã đọc sách về nguyên lí cạnh tranh."]]},{"word":"原理","reading":"げんり","meaning":"nguyên lí","hanViet":"NGUYÊN LÝ","lesson":14,"ex":[["原理を勉強します。","Tôi học nguyên lí."],["原理がわかりました。","Tôi đã hiểu nguyên lí."],["原理を説明しました。","Tôi đã giải thích nguyên lí."],["原理について考えます。","Tôi suy nghĩ về nguyên lí."],["原理の本を読みました。","Tôi đã đọc sách về nguyên lí."]]},{"word":"水準","reading":"すいじゅん","meaning":"tiêu chuẩn, chuẩn mực","hanViet":"THỦY CHUẨN","lesson":14,"ex":[["水準が高いです。","Tiêu chuẩn cao."],["水準を上げます。","Tôi nâng tiêu chuẩn."],["日本の水準は高いです。","Tiêu chuẩn của Nhật cao."],["水準を上げるのは難しいです。","Nâng tiêu chuẩn thì khó."],["水準が上がりました。","Tiêu chuẩn đã tăng lên."]]},{"word":"生み出す","reading":"うみだす","meaning":"cho ra đời","hanViet":"SINH XUẤT","lesson":14,"ex":[["新しいものを生み出します。","Tôi cho ra đời thứ mới."],["彼は新しい歌を生み出しました。","Anh ấy đã cho ra đời bài hát mới."],["生み出す力が大切です。","Khả năng sáng tạo là quan trọng."],["文化を生み出す人です。","Là người cho ra đời văn hóa."],["新しい作品を生み出しました。","Tôi đã cho ra đời tác phẩm mới."]]},{"word":"～のみ","reading":"～のみ","meaning":"chỉ ~, duy nhất ~","hanViet":"","lesson":14,"ex":[["会員のみ入れます。","Chỉ hội viên mới được vào."],["学生のみ無料です。","Chỉ học sinh mới miễn phí."],["きょうのみ安いです。","Chỉ hôm nay mới rẻ."],["3人のみ参加できます。","Chỉ 3 người mới tham gia được."],["日本のみで買えます。","Chỉ mua được ở Nhật."]]},{"word":"～さ","reading":"～さ","meaning":"tiếp vĩ ngữ tạo danh từ chỉ mức độ/tính chất","hanViet":"","lesson":14,"ex":[["このかばんの大きさはちょうどいいです。","Cái túi này có kích thước vừa phải."],["この山の高さに驚きました。","Tôi đã ngạc nhiên trước độ cao của ngọn núi này."],["きょうの暑さはすごいですね。","Cái nóng hôm nay thật khủng khiếp."],["この海の深さはわかりません。","Tôi không biết độ sâu của biển này."],["この本の長さは三百ページです。","Cuốn sách này dài ba trăm trang."]]},{"word":"保証する","reading":"ほしょうする","meaning":"bảo chứng, bảo đảm","hanViet":"BẢO CHỨNG","lesson":14,"ex":[["この店はこの時計を保証します。","Cửa hàng này bảo hành chiếc đồng hồ này."],["この会社は商品の安全を保証します。","Công ty này đảm bảo sự an toàn của sản phẩm."],["この店はこのカメラを長い期間保証します。","Cửa hàng này bảo hành chiếc máy ảnh này trong thời gian dài."],["先生は試験の結果を保証しません。","Thầy giáo không đảm bảo kết quả bài thi."],["彼は私に安全な旅行を保証しました。","Anh ấy đã đảm bảo cho tôi một chuyến đi an toàn."]]},{"word":"過剰","reading":"かじょう","meaning":"thái quá","hanViet":"QUÁ THẶNG","lesson":14,"ex":[["塩を過剰に食べると、体に悪いです。","Ăn quá nhiều muối thì không tốt cho cơ thể."],["この薬を過剰に飲んではいけません。","Không được uống quá nhiều thuốc này."],["過剰な仕事は体に悪いです。","Làm việc quá nhiều không tốt cho cơ thể."],["砂糖を過剰に食べると、歯が悪くなります。","Ăn quá nhiều đường thì răng sẽ xấu đi."],["ものを過剰に買うと、お金が少なくなります。","Mua quá nhiều đồ thì tiền sẽ ít đi."]]},{"word":"ピッチャー","reading":"ピッチャー","meaning":"cầu thủ ném bóng (bóng chày)","hanViet":"","lesson":14,"ex":[["彼はチームのピッチャーです。","Anh ấy là cầu thủ ném bóng của đội."],["ピッチャーは速いボールを投げます。","Cầu thủ ném bóng ném quả bóng nhanh."],["きのうの試合で、ピッチャーはとてもよく投げました。","Trong trận đấu hôm qua, cầu thủ ném bóng đã ném rất tốt."],["私はピッチャーになりたいです。","Tôi muốn trở thành cầu thủ ném bóng."],["ピッチャーの投げたボールはとても速かったです。","Quả bóng mà cầu thủ ném bóng ném rất nhanh."]]},{"word":"シーン","reading":"シーン","meaning":"cảnh","hanViet":"","lesson":14,"ex":[["この映画の最後のシーンはすばらしかったです。","Cảnh cuối của bộ phim này thật tuyệt vời."],["私はこのドラマの悲しいシーンが好きです。","Tôi thích cảnh buồn trong bộ phim truyền hình này."],["小説の初めのシーンは海の町です。","Cảnh đầu tiên của cuốn tiểu thuyết là một thị trấn ven biển."],["あのシーンは今も心に残ります。","Cảnh đó đến giờ vẫn còn đọng lại trong tim tôi."],["この映画のシーンはみんな美しいです。","Mọi cảnh trong bộ phim này đều đẹp."]]},{"word":"秒","reading":"びょう","meaning":"giây","hanViet":"MIỂU","lesson":14,"ex":[["彼は十秒で答えました。","Anh ấy đã trả lời trong mười giây."],["私は十秒待ちました。","Tôi đã đợi mười giây."],["この機械は三秒で動きます。","Chiếc máy này chạy trong ba giây."],["彼女は十秒で名前を書きました。","Cô ấy đã viết tên trong mười giây."],["私は一秒も休みませんでした。","Tôi đã không nghỉ dù chỉ một giây."]]},{"word":"満つ","reading":"みつ","meaning":"đầy","hanViet":"MÃN","lesson":14,"ex":[["月は今晩満ちます。","Mặt trăng tối nay sẽ tròn đầy."],["川の水は雨で満ちました。","Nước sông đã đầy vì mưa."],["彼の心は幸せで満ちています。","Trái tim anh ấy tràn đầy hạnh phúc."],["教室は学生で満ちています。","Phòng học đầy ắp sinh viên."],["私の目は涙で満ちました。","Mắt tôi đầy nước mắt."]]},{"word":"動作","reading":"どうさ","meaning":"động tác","hanViet":"ĐỘNG TÁC","lesson":14,"ex":[["ロボットの動作はとても速いです。","Động tác của robot rất nhanh."],["彼はゆっくり動作を見ました。","Anh ấy đã xem động tác một cách chậm rãi."],["この機械の動作は静かです。","Động tác của chiếc máy này rất êm."],["選手の動作は美しいです。","Động tác của vận động viên rất đẹp."],["私は彼の動作をよく見ました。","Tôi đã quan sát kỹ động tác của anh ấy."]]},{"word":"主人公","reading":"しゅじんこう","meaning":"nhân vật chính","hanViet":"CHỦ NHÂN CÔNG","lesson":14,"ex":[["この小説の主人公は少年です。","Nhân vật chính của cuốn tiểu thuyết này là một cậu bé."],["映画の主人公は女性の先生です。","Nhân vật chính của bộ phim là một cô giáo."],["私はこのドラマの主人公が好きです。","Tôi thích nhân vật chính của bộ phim này."],["主人公は最後に村へ帰りました。","Nhân vật chính cuối cùng đã trở về làng."],["主人公の名前は田中です。","Nhân vật chính tên là Tanaka."]]},{"word":"光景","reading":"こうけい","meaning":"cảnh tượng, hình ảnh","hanViet":"QUANG CẢNH","lesson":14,"ex":[["海の光景はすばらしいです。","Cảnh tượng biển thật tuyệt vời."],["朝の山の光景は美しいです。","Cảnh tượng núi buổi sáng rất đẹp."],["雪の光景は静かで美しいです。","Cảnh tượng tuyết tĩnh lặng và đẹp."],["私は窓から町の光景を見ました。","Tôi đã ngắm cảnh thị trấn từ cửa sổ."],["あの光景は今も心に残ります。","Cảnh tượng đó đến giờ vẫn còn trong tim tôi."]]},{"word":"描く","reading":"えがく","meaning":"miêu tả","hanViet":"MIÊU","lesson":14,"ex":[["画家は海の絵を描きます。","Họa sĩ vẽ tranh biển."],["彼女は子どもの絵を描きました。","Cô ấy đã vẽ tranh trẻ em."],["この小説は小さな村を描きます。","Cuốn tiểu thuyết này miêu tả một ngôi làng nhỏ."],["私は夢の町を描きます。","Tôi vẽ thị trấn trong mơ."],["彼は心の中の風景を描きました。","Anh ấy đã vẽ phong cảnh trong tim."]]},{"word":"毎回","reading":"まいかい","meaning":"mỗi lần","hanViet":"MỖI HỒI","lesson":14,"ex":[["私は毎回この店で買い物します。","Tôi lần nào cũng mua sắm ở cửa hàng này."],["彼は毎回試合に勝ちます。","Anh ấy lần nào cũng thắng trận đấu."],["先生は毎回宿題を出します。","Thầy giáo lần nào cũng giao bài tập về nhà."],["私は毎回この歌を歌います。","Tôi lần nào cũng hát bài hát này."],["母は毎回おいしい料理を作ります。","Mẹ lần nào cũng nấu món ăn ngon."]]},{"word":"直前","reading":"ちょくぜん","meaning":"ngay trước khi","hanViet":"TRỰC TIỀN","lesson":14,"ex":[["試験の直前に、彼はよく勉強しました。","Ngay trước kỳ thi, anh ấy đã học rất chăm."],["試合の直前に、選手は静かに座りました。","Ngay trước trận đấu, vận động viên đã ngồi yên lặng."],["授業の直前に、学生は教室に入りました。","Ngay trước giờ học, sinh viên đã vào lớp."],["試合の直前に雨が降りました。","Ngay trước trận đấu thì trời mưa."],["誕生日の直前に、友達が手紙を書きました。","Ngay trước sinh nhật, bạn tôi đã viết thư."]]},{"word":"起こる","reading":"おこる","meaning":"xảy ra","hanViet":"KHỞI","lesson":14,"ex":[["きのう、町で火事が起こりました。","Hôm qua, trong thị trấn đã xảy ra hỏa hoạn."],["地震が起こると、みんな逃げます。","Khi động đất xảy ra, mọi người chạy trốn."],["問題が起こったら、先生に聞きます。","Nếu có vấn đề xảy ra, tôi sẽ hỏi thầy giáo."],["事故が起こる前に、注意します。","Trước khi tai nạn xảy ra, tôi sẽ cẩn thận."],["去年、この町で大きな事件が起こりました。","Năm ngoái, trong thị trấn này đã xảy ra một vụ việc lớn."]]},{"word":"次週","reading":"じしゅう","meaning":"tuần tiếp theo","hanViet":"THỨ CHU","lesson":14,"ex":[["次週の授業は体育館です。","Tiết học tuần sau ở nhà thể chất."],["次週、母は東京へ行きます。","Tuần sau, mẹ sẽ đi Tokyo."],["次週の試合は土曜日です。","Trận đấu tuần sau là thứ Bảy."],["次週の試験は難しいです。","Kỳ thi tuần sau rất khó."],["次週、私は友達と映画を見ます。","Tuần sau, tôi sẽ xem phim với bạn."]]},{"word":"期待する","reading":"きたいする","meaning":"mong chờ","hanViet":"KỲ ĐÃI","lesson":14,"ex":[["私は新しい映画を期待します。","Tôi mong chờ bộ phim mới."],["先生は学生の成功を期待します。","Thầy giáo mong chờ sự thành công của sinh viên."],["みんなは試合の結果を期待します。","Mọi người mong chờ kết quả trận đấu."],["母は私の成功を期待します。","Mẹ mong chờ sự thành công của tôi."],["私は来年の旅行を期待します。","Tôi mong chờ chuyến du lịch năm sau."]]},{"word":"テクニック","reading":"テクニック","meaning":"kỹ thuật, kỹ xảo","hanViet":"","lesson":14,"ex":[["彼のサッカーのテクニックはすばらしいです。","Kỹ thuật bóng đá của anh ấy thật tuyệt vời."],["このテクニックを毎日練習します。","Kỹ thuật này tôi luyện tập mỗi ngày."],["先生は新しいテクニックを教えました。","Thầy giáo đã dạy kỹ thuật mới."],["写真のテクニックを習いたいです。","Tôi muốn học kỹ thuật chụp ảnh."],["料理のテクニックは本で習います。","Kỹ thuật nấu ăn học được từ sách."]]},{"word":"手法","reading":"しゅほう","meaning":"thủ pháp","hanViet":"THỦ PHÁP","lesson":14,"ex":[["この手法は仕事で使います。","Thủ pháp này được dùng trong công việc."],["先生は新しい手法を教えました。","Thầy giáo đã dạy thủ pháp mới."],["この手法はとても簡単です。","Thủ pháp này rất đơn giản."],["この本に手法が書いてあります。","Trong cuốn sách này có viết thủ pháp."],["私はこの手法を毎日使います。","Tôi dùng thủ pháp này mỗi ngày."]]},{"word":"作り上げる","reading":"つくりあげる","meaning":"tạo ra","hanViet":"TÁC THƯỢNG","lesson":14,"ex":[["彼は小さな家を作り上げました。","Anh ấy đã xây nên một ngôi nhà nhỏ."],["学生は新しいチームを作り上げました。","Sinh viên đã tạo nên một đội mới."],["画家はすばらしい絵を作り上げました。","Họa sĩ đã tạo nên một bức tranh tuyệt vời."],["会社は新しい商品を作り上げました。","Công ty đã tạo ra sản phẩm mới."],["私は長い時間でこの小説を作り上げました。","Tôi đã viết nên cuốn tiểu thuyết này trong thời gian dài."]]},{"word":"ノウハウ","reading":"ノウハウ","meaning":"bí quyết","hanViet":"","lesson":14,"ex":[["この会社は仕事のノウハウがあります。","Công ty này có bí quyết công việc."],["先生は料理のノウハウを教えました。","Thầy giáo đã dạy bí quyết nấu ăn."],["私は仕事のノウハウを友達から習いました。","Tôi đã học bí quyết công việc từ bạn bè."],["この店のノウハウはとても大切です。","Bí quyết của cửa hàng này rất quan trọng."],["ノウハウは経験から生まれます。","Bí quyết sinh ra từ kinh nghiệm."]]},{"word":"夢中","reading":"むちゅう","meaning":"sự say mê, sự say sưa","hanViet":"MỘNG TRUNG","lesson":14,"ex":[["子どもはゲームに夢中です。","Trẻ em mê trò chơi."],["私はサッカーに夢中です。","Tôi mê bóng đá."],["彼は本を読むのに夢中です。","Anh ấy say mê đọc sách."],["学生は音楽に夢中です。","Sinh viên mê âm nhạc."],["母は料理に夢中です。","Mẹ say mê nấu ăn."]]},{"word":"蓄積する","reading":"ちくせきする","meaning":"tích lũy","hanViet":"SÚC TÍCH","lesson":14,"ex":[["経験は毎日蓄積します。","Kinh nghiệm tích lũy mỗi ngày."],["知識は本を読むと蓄積します。","Kiến thức tích lũy khi đọc sách."],["お金は毎月蓄積します。","Tiền tích lũy mỗi tháng."],["ストレスは仕事で蓄積します。","Căng thẳng tích lũy trong công việc."],["データはコンピューターに蓄積します。","Dữ liệu tích lũy trong máy tính."]]},{"word":"亜流","reading":"ありゅう","meaning":"kẻ bắt chước, kẻ ăn theo","hanViet":"Á LƯU","lesson":14,"ex":[["この作品は人気の映画の亜流です。","Tác phẩm này là bản ăn theo bộ phim nổi tiếng."],["亜流の商品は人気がありません。","Sản phẩm ăn theo không được yêu thích."],["この店は有名な店の亜流です。","Cửa hàng này là bản ăn theo của cửa hàng nổi tiếng."],["亜流のデザインは本物に負けます。","Thiết kế ăn theo thua hàng thật."],["彼は亜流の歌を作りました。","Anh ấy đã làm bài hát ăn theo."]]},{"word":"トップブランド","reading":"トップブランド","meaning":"thương hiệu hàng đầu","hanViet":"","lesson":14,"ex":[["彼女はトップブランドの時計を持っています。","Cô ấy có chiếc đồng hồ thương hiệu hàng đầu."],["トップブランドの靴はとても高いです。","Giày thương hiệu hàng đầu rất đắt."],["この店はトップブランドの洋服を売ります。","Cửa hàng này bán quần áo thương hiệu hàng đầu."],["私はトップブランドのかばんを買いました。","Tôi đã mua chiếc túi thương hiệu hàng đầu."],["トップブランドの商品は人気があります。","Sản phẩm thương hiệu hàng đầu được yêu thích."]]},{"word":"別冊","reading":"べっさつ","meaning":"phụ lục được biên soạn theo tập riêng","hanViet":"BIỆT SÁCH","lesson":14,"ex":[["この雑誌の別冊は漫画です。","Phụ lục của tạp chí này là truyện tranh."],["別冊は店で買いました。","Tôi đã mua phụ lục ở cửa hàng."],["雑誌の別冊はとてもおもしろいです。","Phụ lục của tạp chí rất thú vị."],["私は別冊を友達にあげました。","Tôi đã tặng phụ lục cho bạn."],["この別冊は子どもの本です。","Phụ lục này là sách trẻ em."]]},{"word":"激しい","reading":"はげしい","meaning":"khốc liệt","hanViet":"KÍCH","lesson":14,"ex":[["きょうは激しい雨が降りました。","Hôm nay mưa rất to."],["激しい風で窓が壊れました。","Gió mạnh làm cửa sổ bị hỏng."],["試合は激しい競争でした。","Trận đấu là cuộc cạnh tranh khốc liệt."],["彼の激しい声が聞こえました。","Nghe thấy giọng nói dữ dội của anh ấy."],["激しい雨で試合は止まりました。","Mưa to làm trận đấu dừng lại."]]},{"word":"大げさ","reading":"おおげさ","meaning":"phóng đại","hanViet":"ĐẠI","lesson":14,"ex":[["彼の話は大げさです。","Câu chuyện của anh ấy phóng đại."],["大げさな表現はよくありません。","Cách diễn đạt phóng đại không tốt."],["彼女は大げさに喜びました。","Cô ấy đã vui mừng một cách phóng đại."],["彼の大げさな話はおもしろいです。","Câu chuyện phóng đại của anh ấy rất thú vị."],["大げさに言わないでください。","Đừng nói phóng đại."]]},{"word":"～程度","reading":"～ていど","meaning":"khoảng chừng ~","hanViet":"TRÌNH ĐỘ","lesson":14,"ex":[["この仕事は一時間程度で終わります。","Công việc này xong trong khoảng một giờ."],["彼は三日程度旅行します。","Anh ấy đi du lịch khoảng ba ngày."],["百人程度の学生が来ました。","Khoảng một trăm sinh viên đã đến."],["この本は五千円程度です。","Cuốn sách này khoảng năm nghìn yên."],["十人程度の友達が集まりました。","Khoảng mười người bạn đã tụ tập."]]},{"word":"取り上げる","reading":"とりあげる","meaning":"nêu ra, nêu lên","hanViet":"THỦ THƯỢNG","lesson":14,"ex":[["先生は問題を取り上げました。","Thầy giáo đã nêu ra vấn đề."],["新聞はこの話題を取り上げました。","Báo đã nêu lên chủ đề này."],["授業で先生はこの本を取り上げました。","Trong giờ học, thầy giáo đã nêu lên cuốn sách này."],["テレビはこの事件を取り上げました。","Truyền hình đã nêu lên vụ việc này."],["先生は毎回新しい問題を取り上げます。","Thầy giáo lần nào cũng nêu ra vấn đề mới."]]},{"word":"状況","reading":"じょうきょう","meaning":"tình trạng","hanViet":"TRẠNG HUỐNG","lesson":14,"ex":[["会社の状況はよくありません。","Tình hình công ty không tốt."],["天気の状況は毎日変わります。","Tình hình thời tiết thay đổi mỗi ngày."],["先生は試験の状況を説明しました。","Thầy giáo đã giải thích tình hình kỳ thi."],["町の状況はだんだんよくなります。","Tình hình thị trấn dần dần tốt lên."],["状況が変わったら、連絡します。","Nếu tình hình thay đổi, tôi sẽ liên lạc."]]},{"word":"具体例","reading":"ぐたいれい","meaning":"ví dụ cụ thể","hanViet":"CỤ THỂ LỆ","lesson":14,"ex":[["先生は具体例を出しました。","Thầy giáo đã đưa ra ví dụ cụ thể."],["この本は具体例が多いです。","Cuốn sách này có nhiều ví dụ cụ thể."],["試験の答えは具体例が必要です。","Câu trả lời bài thi cần ví dụ cụ thể."],["具体例があると、よくわかります。","Có ví dụ cụ thể thì dễ hiểu."],["先生は具体例で説明しました。","Thầy giáo đã giải thích bằng ví dụ cụ thể."]]},{"word":"昔話","reading":"むかしばなし","meaning":"truyện cổ tích","hanViet":"TÍCH THOẠI","lesson":14,"ex":[["祖母は昔話を話しました。","Bà đã kể truyện cổ tích."],["日本の昔話はおもしろいです。","Truyện cổ tích Nhật Bản rất thú vị."],["子どもは昔話をよく聞きます。","Trẻ em thường nghe truyện cổ tích."],["母は毎晩昔話を話します。","Mẹ kể truyện cổ tích mỗi tối."],["この昔話は村の話です。","Truyện cổ tích này là câu chuyện của làng."]]},{"word":"話し手","reading":"はなして","meaning":"người nói, người kể","hanViet":"THOẠI THỦ","lesson":14,"ex":[["話し手の気持ちを考えます。","Tôi suy nghĩ về cảm xúc của người nói."],["話し手はゆっくり話しました。","Người nói đã nói chậm rãi."],["話し手の声は小さかったです。","Giọng của người nói rất nhỏ."],["会話では話し手のことばが大切です。","Trong hội thoại, lời nói của người nói rất quan trọng."],["話し手は笑いながら話しました。","Người nói vừa cười vừa nói."]]},{"word":"あいづち","reading":"あいづち","meaning":"tiếng đệm, lời nói phụ họa khi hội thoại","hanViet":"","lesson":14,"ex":[["日本語の会話ではあいづちが大切です。","Trong hội thoại tiếng Nhật, tiếng đệm rất quan trọng."],["彼女は上手にあいづちを打ちます。","Cô ấy phụ họa rất khéo."],["あいづちを打つと、話し手はうれしいです。","Khi phụ họa, người nói sẽ vui."],["私はあいづちを練習します。","Tôi luyện tập tiếng đệm."],["あいづちは会話を楽しくします。","Tiếng đệm làm hội thoại vui vẻ."]]},{"word":"打つ","reading":"うつ","meaning":"nói (lời phụ họa)","hanViet":"ĐẢ","lesson":14,"ex":[["彼はあいづちを打ちます。","Anh ấy nói lời phụ họa."],["私は上手にあいづちを打ちたいです。","Tôi muốn phụ họa thật khéo."],["話を聞いて、あいづちを打ちました。","Nghe câu chuyện, tôi đã phụ họa."],["彼女は笑いながらあいづちを打ちました。","Cô ấy vừa cười vừa phụ họa."],["会話では、あいづちを打つことが大切です。","Trong hội thoại, việc phụ họa rất quan trọng."]]},{"word":"銀河","reading":"ぎんが","meaning":"ngân hà","hanViet":"NGÂN HÀ","lesson":14,"ex":[["夜の空に銀河が見えます。","Trên bầu trời đêm có thể thấy ngân hà."],["銀河はたくさんの星です。","Ngân hà là rất nhiều ngôi sao."],["私は銀河の写真を見ました。","Tôi đã xem ảnh ngân hà."],["銀河の話はおもしろいです。","Câu chuyện về ngân hà rất thú vị."],["夏の夜に銀河が見えます。","Vào đêm hè có thể thấy ngân hà."]]},{"word":"鉄道","reading":"てつどう","meaning":"đường sắt","hanViet":"THIẾT ĐẠO","lesson":14,"ex":[["日本の鉄道はとても便利です。","Đường sắt Nhật Bản rất tiện lợi."],["鉄道で東京へ行きます。","Tôi đi Tokyo bằng đường sắt."],["この町の鉄道は古いです。","Đường sắt của thị trấn này rất cũ."],["鉄道の歴史は長いです。","Lịch sử đường sắt rất dài."],["私は鉄道の旅が好きです。","Tôi thích chuyến đi bằng đường sắt."]]},{"word":"触れる","reading":"ふれる","meaning":"chạm (vào tay)","hanViet":"XÚC","lesson":14,"ex":[["子どもは犬に触れました。","Đứa trẻ đã chạm vào con chó."],["私は冷たい水に触れました。","Tôi đã chạm vào nước lạnh."],["彼の手に触れると、温かかったです。","Khi chạm vào tay anh ấy, thấy ấm."],["風が私の顔に触れました。","Gió chạm vào mặt tôi."],["母は子どもの頭に触れました。","Mẹ đã chạm vào đầu đứa trẻ."]]},{"word":"永遠","reading":"えいえん","meaning":"mãi, vĩnh viễn","hanViet":"VĨNH VIỄN","lesson":14,"ex":[["この思い出は永遠です。","Kỷ niệm này là mãi mãi."],["彼らの夢は永遠です。","Giấc mơ của họ là mãi mãi."],["永遠の平和はみんなの夢です。","Hòa bình vĩnh viễn là giấc mơ của mọi người."],["この歌は永遠に残ります。","Bài hát này sẽ còn mãi."],["永遠の思い出は心の中にあります。","Kỷ niệm vĩnh viễn ở trong tim."]]},{"word":"ストーリー","reading":"ストーリー","meaning":"câu chuyện","hanViet":"","lesson":14,"ex":[["この映画のストーリーはおもしろいです。","Câu chuyện của bộ phim này rất thú vị."],["小説のストーリーは悲しいです。","Câu chuyện của cuốn tiểu thuyết rất buồn."],["私はこのゲームのストーリーが好きです。","Tôi thích câu chuyện của trò chơi này."],["ドラマのストーリーは最後に変わります。","Câu chuyện của bộ phim truyền hình thay đổi ở cuối."],["彼女は新しいストーリーを書きました。","Cô ấy đã viết câu chuyện mới."]]},{"word":"一言","reading":"ひとこと","meaning":"một vài lời, một đôi lời","hanViet":"NHẤT NGÔN","lesson":14,"ex":[["先生は私に一言言いました。","Thầy giáo đã nói với tôi một lời."],["母は一言だけ話しました。","Mẹ chỉ nói một lời."],["彼は一言も言いませんでした。","Anh ấy đã không nói một lời nào."],["一言でお礼を言いました。","Tôi đã nói lời cảm ơn bằng một câu."],["友達は一言で答えました。","Bạn tôi đã trả lời bằng một câu."]]},{"word":"結末","reading":"けつまつ","meaning":"kết thúc, phần cuối","hanViet":"KẾT MẠT","lesson":14,"ex":[["小説の結末は悲しいです。","Kết thúc của cuốn tiểu thuyết rất buồn."],["映画の結末はすばらしかったです。","Kết thúc của bộ phim thật tuyệt vời."],["ドラマの結末はまだわかりません。","Kết thúc của bộ phim truyền hình vẫn chưa biết."],["この話の結末はおもしろいです。","Kết thúc của câu chuyện này rất thú vị."],["結末を知りたいです。","Tôi muốn biết kết thúc."]]},{"word":"コーヒーショップ","reading":"コーヒーショップ","meaning":"quán cà phê","hanViet":"","lesson":14,"ex":[["私はコーヒーショップで勉強します。","Tôi học ở quán cà phê."],["友達とコーヒーショップへ行きました。","Tôi đã đi quán cà phê với bạn."],["このコーヒーショップは静かです。","Quán cà phê này rất yên tĩnh."],["コーヒーショップでコーヒーを飲みました。","Tôi đã uống cà phê ở quán cà phê."],["母は毎朝コーヒーショップへ行きます。","Mẹ đi quán cà phê mỗi sáng."]]},{"word":"ショップ","reading":"ショップ","meaning":"quán, cửa hàng","hanViet":"","lesson":14,"ex":[["このショップは洋服を売ります。","Cửa hàng này bán quần áo."],["ショップで新しい靴を買いました。","Tôi đã mua giày mới ở cửa hàng."],["このショップは駅の前にあります。","Cửa hàng này ở trước ga."],["ショップの店員は親切です。","Nhân viên cửa hàng rất tốt bụng."],["私はこのショップが好きです。","Tôi thích cửa hàng này."]]},{"word":"映像","reading":"えいぞう","meaning":"hình ảnh","hanViet":"ÁNH TƯỢNG","lesson":14,"ex":[["この映像はとても美しいです。","Hình ảnh này rất đẹp."],["テレビの映像はすばらしいです。","Hình ảnh trên tivi thật tuyệt vời."],["私は古い映像を見ました。","Tôi đã xem hình ảnh cũ."],["映画の映像は心に残ります。","Hình ảnh của bộ phim đọng lại trong tim."],["この映像は日本の歴史です。","Hình ảnh này là lịch sử Nhật Bản."]]},{"word":"神秘的","reading":"しんぴてき","meaning":"thần bí","hanViet":"THẦN BÍ ĐÍCH","lesson":14,"ex":[["夜の海は神秘的です。","Biển đêm thật huyền bí."],["この音楽は神秘的です。","Âm nhạc này thật huyền bí."],["神秘的な雰囲気が好きです。","Tôi thích bầu không khí huyền bí."],["星の空は神秘的です。","Bầu trời sao thật huyền bí."],["神秘的な話を聞きました。","Tôi đã nghe câu chuyện huyền bí."]]},{"word":"はまる","reading":"はまる","meaning":"mê, ghiền (phim hoạt hình)","hanViet":"","lesson":14,"ex":[["私はこのゲームにはまりました。","Tôi đã mê trò chơi này."],["子どもはアニメにはまります。","Trẻ em mê anime."],["彼女はドラマにはまりました。","Cô ấy đã mê bộ phim truyền hình."],["私はこの歌にはまりました。","Tôi đã mê bài hát này."],["弟は漫画にはまっています。","Em trai đang mê truyện tranh."]]},{"word":"宇宙列車","reading":"うちゅうれっしゃ","meaning":"tàu lửa vũ trụ","hanViet":"VŨ TRỤ LIỆT XA","lesson":14,"ex":[["宇宙列車は星の中を走ります。","Tàu lửa vũ trụ chạy giữa các vì sao."],["私は宇宙列車に乗りたいです。","Tôi muốn đi tàu lửa vũ trụ."],["宇宙列車の旅は夢です。","Chuyến đi bằng tàu lửa vũ trụ là giấc mơ."],["映画の宇宙列車はすばらしいです。","Tàu lửa vũ trụ trong phim thật tuyệt vời."],["子どもは宇宙列車の話が好きです。","Trẻ em thích câu chuyện về tàu lửa vũ trụ."]]},{"word":"列車","reading":"れっしゃ","meaning":"tàu lửa","hanViet":"LIỆT XA","lesson":14,"ex":[["列車は駅を出ました。","Tàu lửa đã rời ga."],["私は列車で東京へ行きます。","Tôi đi Tokyo bằng tàu lửa."],["列車の窓から海が見えます。","Từ cửa sổ tàu lửa có thể thấy biển."],["この列車はとても速いです。","Tàu lửa này rất nhanh."],["列車の中で本を読みました。","Tôi đã đọc sách trong tàu lửa."]]},{"word":"宇宙船","reading":"うちゅうせん","meaning":"tàu vũ trụ","hanViet":"VŨ TRỤ THUYỀN","lesson":14,"ex":[["宇宙船は空へ飛びました。","Tàu vũ trụ đã bay lên trời."],["私は宇宙船に乗りたいです。","Tôi muốn đi tàu vũ trụ."],["宇宙船の中は狭いです。","Bên trong tàu vũ trụ rất chật."],["子どもは宇宙船の絵を描きました。","Trẻ em đã vẽ tranh tàu vũ trụ."],["宇宙船は星へ行きます。","Tàu vũ trụ đi đến các vì sao."]]},{"word":"機械化","reading":"きかいか","meaning":"cơ giới hóa","hanViet":"CƠ GIỚI HÓA","lesson":14,"ex":[["工場の機械化は進みます。","Cơ giới hóa nhà máy đang tiến triển."],["機械化で仕事は速くなります。","Nhờ cơ giới hóa, công việc nhanh hơn."],["会社の機械化は大切です。","Cơ giới hóa công ty rất quan trọng."],["機械化で生活は変わります。","Nhờ cơ giới hóa, cuộc sống thay đổi."],["この村の機械化はまだです。","Cơ giới hóa của làng này vẫn chưa xong."]]},{"word":"～化","reading":"～か","meaning":"~ hóa","hanViet":"HÓA","lesson":14,"ex":[["日本の高齢化は進みます。","Già hóa dân số ở Nhật Bản đang tiến triển."],["少子化は社会の問題です。","Ít con là vấn đề của xã hội."],["町の多様化は進みます。","Đa dạng hóa của thị trấn đang tiến triển."],["図書館の無料化はうれしいです。","Việc miễn phí thư viện thật đáng mừng."],["地球温暖化は世界の問題です。","Nóng lên toàn cầu là vấn đề của thế giới."]]},{"word":"取り残す","reading":"とりのこす","meaning":"chừa lại, để lại","hanViet":"THỦ TÀN","lesson":14,"ex":[["私は宿題を取り残しました。","Tôi đã để lại bài tập về nhà chưa làm."],["彼は仕事を取り残しました。","Anh ấy đã để lại công việc chưa làm."],["母は料理を取り残しました。","Mẹ đã để lại món ăn chưa ăn."],["問題を取り残してはいけません。","Không được để lại vấn đề chưa giải quyết."],["彼は弟を家に取り残しました。","Anh ấy đã để em trai ở lại nhà."]]},{"word":"生身","reading":"なまみ","meaning":"cơ thể sống, bằng xương bằng thịt","hanViet":"SINH THÂN","lesson":14,"ex":[["生身の体は大切です。","Cơ thể bằng xương bằng thịt rất quan trọng."],["生身の体で風を感じます。","Tôi cảm nhận gió bằng cơ thể sống."],["生身で会いたいです。","Tôi muốn gặp trực tiếp bằng xương bằng thịt."],["彼は生身の体で働きました。","Anh ấy đã làm việc bằng cơ thể sống."],["彼は生身の体で山に登りました。","Anh ấy đã leo núi bằng cơ thể sống."]]},{"word":"彼ら","reading":"かれら","meaning":"họ","hanViet":"BỈ","lesson":14,"ex":[["彼らは学生です。","Họ là sinh viên."],["彼らは毎週サッカーをします。","Họ chơi bóng đá mỗi tuần."],["彼らは東京に住んでいます。","Họ đang sống ở Tokyo."],["彼らの歌はすばらしいです。","Bài hát của họ thật tuyệt vời."],["私は彼らと友達です。","Tôi là bạn với họ."]]},{"word":"差別する","reading":"さべつする","meaning":"phân biệt đối xử","hanViet":"SAI BIỆT","lesson":14,"ex":[["人を差別してはいけません。","Không được phân biệt đối xử với người khác."],["会社は女性を差別しません。","Công ty không phân biệt đối xử với phụ nữ."],["学校は子どもを差別しません。","Trường học không phân biệt đối xử với trẻ em."],["彼は人を差別したことがありません。","Anh ấy chưa bao giờ phân biệt đối xử với ai."],["差別する社会はよくありません。","Xã hội phân biệt đối xử không tốt."]]},{"word":"狩猟","reading":"しゅりょう","meaning":"đi săn","hanViet":"THÚ LIỆP","lesson":14,"ex":[["村の人は狩猟で生活しました。","Người làng sống bằng nghề săn bắn."],["狩猟は山でします。","Săn bắn được thực hiện ở núi."],["狩猟の歴史は長いです。","Lịch sử săn bắn rất dài."],["彼は狩猟が好きです。","Anh ấy thích săn bắn."],["狩猟は村の大切な仕事でした。","Săn bắn là công việc quan trọng của làng."]]},{"word":"犠牲","reading":"ぎせい","meaning":"hy sinh, chết","hanViet":"HI SINH","lesson":14,"ex":[["戦争の犠牲は多いです。","Nạn nhân của chiến tranh rất nhiều."],["事故の犠牲は悲しいです。","Nạn nhân của tai nạn thật đáng buồn."],["彼は家族のために犠牲になりました。","Anh ấy đã hy sinh vì gia đình."],["犠牲を出してはいけません。","Không được để xảy ra hy sinh."],["戦争では多くの犠牲が出ます。","Trong chiến tranh có nhiều hy sinh."]]},{"word":"遺言","reading":"ゆいごん","meaning":"lời trăng trối, di ngôn","hanViet":"DI NGÔN","lesson":14,"ex":[["祖父は遺言を書きました。","Ông đã viết di ngôn."],["父の遺言は家族に残ります。","Di ngôn của cha còn lại với gia đình."],["彼は遺言を手紙に書きました。","Anh ấy đã viết di ngôn trong thư."],["彼の遺言は短かったです。","Di ngôn của anh ấy rất ngắn."],["遺言は大切なことばです。","Di ngôn là lời nói quan trọng."]]},{"word":"出会う","reading":"であう","meaning":"gặp, gặp gỡ, gặp phải","hanViet":"XUẤT HỘI","lesson":14,"ex":[["私は東京で友達に出会いました。","Tôi đã gặp bạn ở Tokyo."],["彼は旅で先生に出会いました。","Anh ấy đã gặp thầy giáo trong chuyến đi."],["私は学校で恋人に出会いました。","Tôi đã gặp người yêu ở trường."],["子どもは公園で犬に出会いました。","Đứa trẻ đã gặp con chó ở công viên."],["私は本で新しい世界に出会いました。","Tôi đã gặp thế giới mới trong sách."]]},{"word":"土星","reading":"どせい","meaning":"sao thổ","hanViet":"THỔ TINH","lesson":14,"ex":[["土星は夜の空に見えます。","Sao Thổ có thể thấy trên bầu trời đêm."],["土星の写真を見ました。","Tôi đã xem ảnh sao Thổ."],["土星は星の中で美しいです。","Sao Thổ đẹp trong số các vì sao."],["子どもは土星の話が好きです。","Trẻ em thích câu chuyện về sao Thổ."],["土星は地球より大きいです。","Sao Thổ lớn hơn Trái Đất."]]},{"word":"食堂車","reading":"しょくどうしゃ","meaning":"toa ăn uống","hanViet":"THỰC ĐƯỜNG XA","lesson":14,"ex":[["列車の食堂車でごはんを食べました。","Tôi đã ăn cơm ở toa ăn của tàu lửa."],["食堂車は列車の中にあります。","Toa ăn ở trong tàu lửa."],["私は食堂車でコーヒーを飲みました。","Tôi đã uống cà phê ở toa ăn."],["食堂車の料理はおいしいです。","Món ăn ở toa ăn rất ngon."],["友達と食堂車で話しました。","Tôi đã nói chuyện với bạn ở toa ăn."]]},{"word":"血","reading":"ち","meaning":"máu","hanViet":"HUYẾT","lesson":14,"ex":[["血は体の中にあります。","Máu ở trong cơ thể."],["けがで血が出ました。","Vì bị thương nên máu đã chảy ra."],["血は赤いです。","Máu có màu đỏ."],["病院で血を調べました。","Ở bệnh viện đã kiểm tra máu."],["血は体に大切です。","Máu rất quan trọng với cơ thể."]]},{"word":"通う","reading":"かよう","meaning":"(máu) chảy","hanViet":"THÔNG","lesson":14,"ex":[["血は体の中を通います。","Máu chảy trong cơ thể."],["温かい血が体を通います。","Dòng máu ấm chảy qua cơ thể."],["血は心から体を通います。","Máu chảy từ tim qua cơ thể."],["子どもの体に血が通います。","Máu chảy trong cơ thể đứa trẻ."],["血は体の中をゆっくり通います。","Máu chảy chậm rãi trong cơ thể."]]},{"word":"幻覚","reading":"げんかく","meaning":"ảo giác","hanViet":"HUYỄN GIÁC","lesson":14,"ex":[["病気で幻覚を見ました。","Vì bệnh nên tôi đã thấy ảo giác."],["夜に幻覚が見えました。","Vào ban đêm tôi đã thấy ảo giác."],["幻覚は夢ではありません。","Ảo giác không phải là giấc mơ."],["彼は幻覚で怖くなりました。","Anh ấy đã sợ vì ảo giác."],["幻覚の話は怖いです。","Câu chuyện về ảo giác thật đáng sợ."]]},{"word":"襲う","reading":"おそう","meaning":"xâm chiếm, tấn công","hanViet":"TẬP","lesson":14,"ex":[["敵は村を襲いました。","Kẻ thù đã tấn công làng."],["台風は町を襲いました。","Bão đã tấn công thị trấn."],["地震は夜に町を襲いました。","Động đất đã tấn công thị trấn vào ban đêm."],["不安が私を襲いました。","Nỗi lo lắng đã ập đến với tôi."],["恐怖が子どもを襲いました。","Nỗi sợ hãi đã ập đến đứa trẻ."]]},{"word":"身","reading":"み","meaning":"thân thể, cơ thể","hanViet":"THÂN","lesson":14,"ex":[["身を守ることは大切です。","Việc bảo vệ thân thể rất quan trọng."],["彼の身は強いです。","Thân thể anh ấy khỏe mạnh."],["身が疲れました。","Thân thể đã mệt mỏi."],["身を洗うことは大切です。","Việc tắm rửa thân thể rất quan trọng."],["母は子どもの身を守ります。","Mẹ bảo vệ thân thể của đứa trẻ."]]},{"word":"投げ出す","reading":"なげだす","meaning":"xả (thân)","hanViet":"ĐẦU XUẤT","lesson":14,"ex":[["彼は身を投げ出しました。","Anh ấy đã xả thân."],["彼は仕事を投げ出しました。","Anh ấy đã bỏ dở công việc."],["彼女は本を投げ出しました。","Cô ấy đã ném quyển sách đi."],["夢を投げ出してはいけません。","Không được từ bỏ giấc mơ."],["彼はボールを遠くへ投げ出しました。","Anh ấy đã ném quả bóng đi xa."]]},{"word":"粉々","reading":"こなごな","meaning":"vỡ vụn, nát thành từng mảnh nhỏ","hanViet":"PHẤN","lesson":14,"ex":[["ガラスの皿は粉々になりました。","Đĩa thủy tinh đã vỡ vụn."],["夢は粉々になりました。","Giấc mơ đã tan vỡ."],["皿は落ちて粉々になりました。","Cái đĩa rơi xuống và vỡ vụn."],["ガラスは粉々に割れました。","Thủy tinh đã vỡ vụn."],["彼の心は粉々になりました。","Trái tim anh ấy đã tan vỡ."]]},{"word":"ガラス球","reading":"ガラスだま","meaning":"viên thủy tinh","hanViet":"CẦU","lesson":14,"ex":[["ガラス球はとてもきれいです。","Viên thủy tinh rất đẹp."],["私はガラス球を買いました。","Tôi đã mua viên thủy tinh."],["ガラス球は手の中にあります。","Viên thủy tinh ở trong tay."],["子どもはガラス球で遊びました。","Trẻ em đã chơi với viên thủy tinh."],["ガラス球は月のようです。","Viên thủy tinh giống như mặt trăng."]]},{"word":"球","reading":"たま","meaning":"viên, quả hình cầu","hanViet":"CẦU","lesson":14,"ex":[["月は大きな球です。","Mặt trăng là một quả cầu lớn."],["私は小さな球を持っています。","Tôi có một quả cầu nhỏ."],["球は手から落ちました。","Quả cầu đã rơi khỏi tay."],["子どもは球で遊びます。","Trẻ em chơi với quả cầu."],["この球はガラスです。","Quả cầu này làm bằng thủy tinh."]]},{"word":"散る","reading":"ちる","meaning":"rơi, rụng, tản ra (hoa lá)","hanViet":"TÁN","lesson":14,"ex":[["桜の花は春に散ります。","Hoa anh đào rơi vào mùa xuân."],["秋に葉は散ります。","Lá rụng vào mùa thu."],["花は風で散りました。","Hoa đã rơi vì gió."],["夢は散りました。","Giấc mơ đã tan biến."],["桜は雨で散りました。","Hoa anh đào đã rơi vì mưa."]]},{"word":"美形","reading":"びけい","meaning":"dung nhan đẹp, ngoại hình đẹp","hanViet":"MỸ HÌNH","lesson":14,"ex":[["彼女は美形の女優です。","Cô ấy là nữ diễn viên có ngoại hình đẹp."],["彼は美形の俳優です。","Anh ấy là nam diễn viên có ngoại hình đẹp."],["美形の顔は人気があります。","Gương mặt đẹp được yêu thích."],["彼女の美形は有名です。","Vẻ đẹp của cô ấy nổi tiếng."],["美形の人は映画に出ます。","Người có ngoại hình đẹp xuất hiện trong phim."]]},{"word":"鉱山","reading":"こうざん","meaning":"mỏ","hanViet":"KHOÁNG SƠN","lesson":14,"ex":[["山に古い鉱山があります。","Trên núi có mỏ cũ."],["村の人は鉱山で働きました。","Người làng đã làm việc ở mỏ."],["鉱山の仕事は難しいです。","Công việc ở mỏ rất khó."],["鉱山の歴史は長いです。","Lịch sử của mỏ rất dài."],["私は鉱山を見ました。","Tôi đã xem mỏ."]]},{"word":"閉じ込める","reading":"とじこめる","meaning":"nhốt","hanViet":"BẾ","lesson":14,"ex":[["犬を部屋に閉じ込めました。","Tôi đã nhốt con chó trong phòng."],["彼は心に秘密を閉じ込めました。","Anh ấy đã giấu kín bí mật trong tim."],["子どもは箱に虫を閉じ込めました。","Đứa trẻ đã nhốt con côn trùng vào hộp."],["母は猫を部屋に閉じ込めません。","Mẹ không nhốt con mèo trong phòng."],["彼は思い出を心に閉じ込めました。","Anh ấy đã giấu kín kỷ niệm trong tim."]]},{"word":"知恵","reading":"ちえ","meaning":"trí tuệ","hanViet":"TRI HUỆ","lesson":14,"ex":[["祖母の知恵はすばらしいです。","Trí tuệ của bà thật tuyệt vời."],["本から知恵を習います。","Tôi học trí tuệ từ sách."],["知恵は生活に大切です。","Trí tuệ rất quan trọng trong cuộc sống."],["彼は知恵で難しい問題を考えました。","Anh ấy đã suy nghĩ về vấn đề khó bằng trí tuệ."],["みんなの知恵を出し合います。","Mọi người cùng góp trí tuệ."]]},{"word":"出し合う","reading":"だしあう","meaning":"góp","hanViet":"XUẤT HỢP","lesson":14,"ex":[["みんなでお金を出し合いました。","Mọi người cùng nhau góp tiền."],["学生は意見を出し合いました。","Sinh viên đã cùng nhau đưa ra ý kiến."],["友達は知恵を出し合います。","Bạn bè cùng nhau góp trí tuệ."],["力を出し合って、仕事をしました。","Cùng nhau góp sức, chúng tôi đã làm việc."],["家族はお金を出し合って、家を買いました。","Gia đình cùng nhau góp tiền và mua nhà."]]},{"word":"～後","reading":"～ご","meaning":"sau (vài ngày)","hanViet":"HẬU","lesson":14,"ex":[["試合は三日後です。","Trận đấu là ba ngày sau."],["試験は二日後です。","Kỳ thi là hai ngày sau."],["彼は数日後に帰ります。","Anh ấy sẽ về sau vài ngày."],["電車は一時間後に出ます。","Tàu sẽ khởi hành sau một giờ."],["母は三時間後に来ます。","Mẹ sẽ đến sau ba giờ."]]},{"word":"ジャングル","reading":"ジャングル","meaning":"rừng rậm nhiệt đới","hanViet":"","lesson":14,"ex":[["ジャングルは暑いです。","Rừng rậm rất nóng."],["ジャングルに動物がいます。","Trong rừng rậm có động vật."],["映画はジャングルの冒険です。","Bộ phim là cuộc phiêu lưu trong rừng rậm."],["私はジャングルへ旅行したいです。","Tôi muốn đi du lịch rừng rậm."],["ジャングルの花は大きいです。","Hoa trong rừng rậm rất lớn."]]},{"word":"兵士","reading":"へいし","meaning":"binh sĩ, người lính","hanViet":"BINH SĨ","lesson":14,"ex":[["兵士は国を守ります。","Binh sĩ bảo vệ đất nước."],["若い兵士は村にいました。","Binh sĩ trẻ ở trong làng."],["兵士の話は歴史です。","Câu chuyện của binh sĩ là lịch sử."],["兵士は平和を守ります。","Binh sĩ bảo vệ hòa bình."],["村に兵士が来ました。","Binh sĩ đã đến làng."]]},{"word":"枠組み","reading":"わくぐみ","meaning":"khung, bố cục","hanViet":"TỔ","lesson":14,"ex":[["先生は作文の枠組みを紙に書きました。","Thầy giáo đã viết bố cục bài văn ra giấy."],["この小説の枠組みは、とても簡単です。","Bố cục của cuốn tiểu thuyết này rất đơn giản."],["会議の前に、発表の枠組みを決めました。","Trước cuộc họp, tôi đã quyết định bố cục bài thuyết trình."],["私は新しい計画の枠組みを作りました。","Tôi đã làm bố cục cho kế hoạch mới."],["この映画の枠組みは、家族の話です。","Bố cục của bộ phim này là câu chuyện về gia đình."]]},{"word":"あらすじ","reading":"あらすじ","meaning":"nét chính của câu chuyện, cốt truyện","hanViet":"","lesson":14,"ex":[["映画を見る前に、あらすじを読みました。","Trước khi xem phim, tôi đã đọc cốt truyện."],["この小説のあらすじを友達に話しました。","Tôi đã kể cốt truyện của cuốn tiểu thuyết này cho bạn."],["先生は物語のあらすじを説明しました。","Thầy giáo đã giải thích cốt truyện của câu chuyện."],["あらすじだけでは、この本はよくわかりません。","Chỉ đọc cốt truyện thì không hiểu rõ cuốn sách này."],["友達は映画のあらすじをメールで送りました。","Bạn tôi đã gửi cốt truyện bộ phim qua email."]]},{"word":"場面","reading":"ばめん","meaning":"tình huống, bối cảnh","hanViet":"TRƯỜNG DIỆN","lesson":14,"ex":[["この映画で一番好きな場面は、海の場面です。","Cảnh tôi thích nhất trong bộ phim này là cảnh biển."],["小説の初めの場面は、東京の駅です。","Cảnh mở đầu của tiểu thuyết là ga ở Tokyo."],["雨の場面では、音楽がとても静かです。","Ở cảnh mưa, nhạc rất yên tĩnh."],["その場面を見て、私は涙が出ました。","Xem cảnh đó, tôi đã rơi nước mắt."],["先生は大切な場面を、ゆっくり説明しました。","Thầy giáo đã giải thích chậm rãi cảnh quan trọng."]]},{"word":"外出する","reading":"がいしゅつする","meaning":"đi ra ngoài","hanViet":"NGOẠI XUẤT","lesson":14,"ex":[["天気がいいので、私は外出しました。","Vì thời tiết đẹp nên tôi đã ra ngoài."],["母は買い物をするために外出しました。","Mẹ tôi đã ra ngoài để đi mua sắm."],["彼はあまり外出しないで、家で本を読みます。","Anh ấy ít ra ngoài, ở nhà đọc sách."],["外出するときは、鍵を持ちます。","Khi ra ngoài, tôi mang theo chìa khóa."],["雨が降っているので、外出しませんでした。","Vì trời mưa nên tôi đã không ra ngoài."]]},{"word":"PC","reading":"ピーシー","meaning":"máy tính cá nhân","hanViet":"","lesson":14,"ex":[["私は毎日PCでメールを書きます。","Hằng ngày tôi viết email bằng máy tính."],["新しいPCを買いました。","Tôi đã mua máy tính mới."],["このPCは、とても便利です。","Máy tính này rất tiện lợi."],["会社では、PCで仕事をします。","Ở công ty, tôi làm việc bằng máy tính."],["PCが壊れて、仕事ができませんでした。","Máy tính hỏng nên tôi không làm được việc."]]},{"word":"チェックインする","reading":"チェックインする","meaning":"nhận phòng","hanViet":"","lesson":14,"ex":[["午後3時にホテルでチェックインしました。","Tôi đã nhận phòng khách sạn lúc 3 giờ chiều."],["空港でチェックインする前に、パスポートを用意しました。","Trước khi làm thủ tục ở sân bay, tôi đã chuẩn bị hộ chiếu."],["チェックインの時間は、午後3時からです。","Giờ nhận phòng là từ 3 giờ chiều."],["旅行のときは、ホテルでチェックインしてから、部屋に行きます。","Khi đi du lịch, tôi nhận phòng khách sạn rồi mới đến phòng."],["チェックインをしたら、部屋の鍵をもらいました。","Sau khi nhận phòng, tôi đã nhận chìa khóa phòng."]]},{"word":"使用する","reading":"しようする","meaning":"sử dụng","hanViet":"SỬ DỤNG","lesson":14,"ex":[["図書館では、このパソコンを使用できます。","Ở thư viện, có thể sử dụng máy tính này."],["新しい薬を使用する前に、医者に相談しました。","Trước khi dùng thuốc mới, tôi đã hỏi ý kiến bác sĩ."],["この辞書は、毎日使用しています。","Tôi dùng cuốn từ điển này hằng ngày."],["会社では、新しいパソコンを使用しています。","Ở công ty, chúng tôi đang dùng máy tính mới."],["学校では、パソコンを使用する授業があります。","Ở trường có tiết học sử dụng máy tính."]]},{"word":"ちまき","reading":"ちまき","meaning":"bánh gạo gói trong lá tre","hanViet":"","lesson":14,"ex":[["ちまきは、お菓子の一つです。","Chimaki là một loại bánh kẹo."],["春に、ちまきを食べます。","Mùa xuân, tôi ăn chimaki."],["母はちまきを作ってくれました。","Mẹ đã làm chimaki cho tôi."],["この店のちまきは、有名です。","Chimaki ở cửa hàng này nổi tiếng."],["ちまきを買って、家で食べました。","Tôi đã mua chimaki và ăn ở nhà."]]},{"word":"かしわもち","reading":"かしわもち","meaning":"bánh Kashiwa-mochi, một loại bánh nếp gói lá sồi (lá kashiwa)","hanViet":"","lesson":14,"ex":[["かしわもちは、春の食べ物です。","Kashiwa-mochi là món ăn mùa xuân."],["家族でかしわもちを食べました。","Cả gia đình đã ăn kashiwa-mochi."],["このかしわもちは、中が甘いです。","Kashiwa-mochi này nhân ngọt."],["店でかしわもちを三つ買いました。","Tôi đã mua ba cái kashiwa-mochi ở cửa hàng."],["かしわもちの葉は、食べません。","Lá của kashiwa-mochi thì không ăn."]]},{"word":"受賞者","reading":"じゅしょうしゃ","meaning":"người đoạt giải","hanViet":"THỤ THƯỞNG GIẢ","lesson":14,"ex":[["受賞者は、スピーチをしました。","Người đoạt giải đã phát biểu."],["今年の受賞者は、田中さんです。","Người đoạt giải năm nay là anh Tanaka."],["受賞者の名前が、新聞に出ました。","Tên người đoạt giải đã đăng trên báo."],["受賞者の中には、若い人もいます。","Trong số người đoạt giải cũng có người trẻ."],["受賞者を見て、私も頑張りたいと思いました。","Nhìn người đoạt giải, tôi cũng muốn cố gắng."]]},{"word":"出身者","reading":"しゅっしんしゃ","meaning":"người xuất thân từ","hanViet":"XUẤT THÂN GIẢ","lesson":14,"ex":[["この学校の出身者は、世界で働いています。","Người xuất thân từ trường này đang làm việc khắp thế giới."],["京都の出身者は、京都の話をよくします。","Người xuất thân từ Kyoto thường kể chuyện về Kyoto."],["この町の出身者の田中さんは、有名です。","Anh Tanaka, người xuất thân từ thị trấn này, rất nổi tiếng."],["出身者が集まって、パーティーをしました。","Những người cùng quê đã tụ họp và mở tiệc."],["彼は東京の出身者です。","Anh ấy là người xuất thân từ Tokyo."]]},{"word":"砂漠","reading":"さばく","meaning":"sa mạc","hanViet":"SA MẠC","lesson":14,"ex":[["砂漠は、雨がほとんど降りません。","Ở sa mạc hầu như không có mưa."],["砂漠では、水がとても大切です。","Ở sa mạc, nước rất quan trọng."],["砂漠の夜は、とても寒いです。","Ban đêm ở sa mạc rất lạnh."],["砂漠を歩くのは、大変です。","Đi bộ qua sa mạc rất vất vả."],["映画で砂漠を見ました。","Tôi đã thấy sa mạc trong phim."]]},{"word":"パンダ","reading":"パンダ","meaning":"gấu trúc","hanViet":"","lesson":14,"ex":[["動物園でパンダを見ました。","Tôi đã xem gấu trúc ở sở thú."],["パンダは、白と黒の動物です。","Gấu trúc là động vật màu trắng và đen."],["パンダの写真を撮りました。","Tôi đã chụp ảnh gấu trúc."],["動物園のパンダは、毎日たくさんの人に見られます。","Gấu trúc ở sở thú được nhiều người xem mỗi ngày."],["パンダはゆっくり歩きます。","Gấu trúc đi chậm rãi."]]},{"word":"交換する","reading":"こうかんする","meaning":"trao đổi","hanViet":"GIAO HOÁN","lesson":14,"ex":[["友達と本を交換しました。","Tôi đã trao đổi sách với bạn."],["先生とメールアドレスを交換しました。","Tôi đã trao đổi địa chỉ email với thầy giáo."],["古い服と新しい服を交換しました。","Tôi đã đổi quần áo cũ lấy quần áo mới."],["旅行の前に、お金を交換しました。","Trước chuyến du lịch, tôi đã đổi tiền."],["彼は私と席を交換してくれました。","Anh ấy đã đổi chỗ ngồi với tôi."]]},{"word":"冷める","reading":"さめる","meaning":"nguội","hanViet":"LÃNH","lesson":14,"ex":[["コーヒーが冷めたので、飲めませんでした。","Cà phê đã nguội nên tôi không uống được."],["料理が冷める前に、食べましょう。","Hãy ăn trước khi món ăn nguội."],["お茶が冷めました。","Trà đã nguội."],["冬は、料理がすぐ冷めます。","Mùa đông, món ăn nguội nhanh."],["風が強くて、料理がすぐ冷めました。","Gió mạnh nên món ăn nguội nhanh."]]},{"word":"まずい","reading":"まずい","meaning":"dở","hanViet":"","lesson":14,"ex":[["この料理は、まずいです。","Món ăn này dở."],["まずい薬は、飲みにくいです。","Thuốc dở thì khó uống."],["このコーヒーは、まずいです。","Cà phê này dở."],["まずい料理を出して、すみませんでした。","Xin lỗi vì đã dọn món ăn dở."],["彼はまずい顔をしました。","Anh ấy nhăn mặt."]]},{"word":"溶ける","reading":"とける","meaning":"chảy, tan","hanViet":"DUNG","lesson":14,"ex":[["春になって、雪が溶けました。","Sang xuân, tuyết đã tan."],["アイスクリームがすぐ溶けます。","Kem tan nhanh."],["砂糖は、水に溶けます。","Đường tan trong nước."],["暑いので、チョコレートが溶けました。","Vì nóng nên sô-cô-la đã chảy."],["太陽が出て、雪が溶けました。","Mặt trời lên, tuyết đã tan."]]},{"word":"睡眠","reading":"すいみん","meaning":"giấc ngủ","hanViet":"THỤY MIÊN","lesson":14,"ex":[["睡眠は、健康にとても大切です。","Giấc ngủ rất quan trọng đối với sức khỏe."],["子どもは、大人より睡眠が長いです。","Trẻ em ngủ lâu hơn người lớn."],["睡眠が足りないと、疲れます。","Thiếu ngủ thì mệt."],["睡眠の前に、本を読みます。","Trước khi ngủ, tôi đọc sách."],["旅行のときは、睡眠が少なくなります。","Khi đi du lịch, giấc ngủ ít đi."]]},{"word":"欠く","reading":"かく","meaning":"thiếu","hanViet":"KHIẾM","lesson":14,"ex":[["睡眠を欠くと、体に悪いです。","Thiếu ngủ thì hại cho cơ thể."],["この計画は、準備を欠いています。","Kế hoạch này thiếu sự chuẩn bị."],["この料理は、味を欠いています。","Món ăn này thiếu vị."],["彼は、準備を欠いたまま、試験を受けました。","Anh ấy đã dự thi mà không chuẩn bị."],["この本は、地図を欠いています。","Cuốn sách này thiếu bản đồ."]]},{"word":"ただの","reading":"ただの","meaning":"chỉ, đơn thuần","hanViet":"","lesson":14,"ex":[["これはただの紙です。","Đây chỉ là tờ giấy bình thường."],["彼はただの学生です。","Anh ấy chỉ là sinh viên bình thường."],["ただの間違いだと思いました。","Tôi nghĩ đó chỉ là lỗi bình thường."],["これはただの冗談です。","Đây chỉ là trò đùa."],["ただの友達です。","Chỉ là bạn bè thôi."]]},{"word":"ギョーザ","reading":"ギョーザ","meaning":"Gyoza (há cảo: bánh nhồi thịt bằm)","hanViet":"","lesson":14,"ex":[["ギョーザは、日本の人気のある食べ物です。","Gyoza là món ăn nổi tiếng của Nhật."],["母はギョーザを作りました。","Mẹ đã làm gyoza."],["レストランでギョーザを食べました。","Tôi đã ăn gyoza ở nhà hàng."],["ギョーザをたくさん買いました。","Tôi đã mua nhiều gyoza."],["家でギョーザを作るのは、楽しいです。","Làm gyoza ở nhà rất vui."]]},{"word":"おふくろ","reading":"おふくろ","meaning":"mẹ tôi","hanViet":"","lesson":14,"ex":[["おふくろは、毎日料理を作ります。","Mẹ tôi nấu ăn mỗi ngày."],["おふくろに電話をしました。","Tôi đã gọi điện cho mẹ."],["おふくろは、料理が上手です。","Mẹ tôi nấu ăn giỏi."],["おふくろの料理の味は、とてもいいです。","Món ăn mẹ tôi nấu có vị rất ngon."],["おふくろといっしょに買い物に行きました。","Tôi đã đi mua sắm cùng mẹ."]]},{"word":"重要","reading":"じゅうよう","meaning":"quan trọng","hanViet":"TRỌNG YẾU","lesson":14,"ex":[["健康は、とても重要です。","Sức khỏe rất quan trọng."],["この仕事は、とても重要です。","Công việc này rất quan trọng."],["重要な会議があります。","Có cuộc họp quan trọng."],["先生は重要な話をしました。","Thầy giáo đã nói chuyện quan trọng."],["睡眠は、重要な時間です。","Giấc ngủ là thời gian quan trọng."]]},{"word":"両方","reading":"りょうほう","meaning":"cả hai, hai phía","hanViet":"LƯỠNG PHƯƠNG","lesson":14,"ex":[["両方の意見を聞きました。","Tôi đã nghe ý kiến của cả hai phía."],["両方の本を読みました。","Tôi đã đọc cả hai cuốn sách."],["彼は日本語と英語の両方を話します。","Anh ấy nói cả tiếng Nhật và tiếng Anh."],["両方の手を使いました。","Tôi đã dùng cả hai tay."],["両方のチームが頑張りました。","Cả hai đội đều đã cố gắng."]]},{"word":"立場","reading":"たちば","meaning":"lập trường","hanViet":"LẬP TRƯỜNG","lesson":14,"ex":[["彼の立場を考えました。","Tôi đã nghĩ về lập trường của anh ấy."],["立場が変わると、意見も変わります。","Khi lập trường thay đổi, ý kiến cũng thay đổi."],["私の立場では、その仕事はできません。","Ở vị trí của tôi, tôi không thể làm công việc đó."],["相手の立場を理解するのは、大切です。","Hiểu lập trường của đối phương là điều quan trọng."],["先生の立場から、学生に話しました。","Từ lập trường của thầy giáo, tôi đã nói với học sinh."]]},{"word":"建設する","reading":"けんせつする","meaning":"xây dựng","hanViet":"KIẾN THIẾT","lesson":14,"ex":[["新しい学校を建設しています。","Họ đang xây trường học mới."],["会社は新しいビルを建設しました。","Công ty đã xây tòa nhà mới."],["橋を建設するのに、長い時間がかかりました。","Xây cầu mất thời gian dài."],["京都に新しいホテルを建設します。","Họ sẽ xây khách sạn mới ở Kyoto."],["建設する前に、計画を作りました。","Trước khi xây dựng, họ đã lập kế hoạch."]]},{"word":"議論する","reading":"ぎろんする","meaning":"thảo luận, tranh luận","hanViet":"NGHỊ LUẬN","lesson":14,"ex":[["会議で新しい計画を議論しました。","Trong cuộc họp, chúng tôi đã thảo luận kế hoạch mới."],["学生は問題を議論しています。","Sinh viên đang thảo luận vấn đề."],["友達と環境について議論しました。","Tôi đã thảo luận với bạn về môi trường."],["議論する前に、資料を読みました。","Trước khi thảo luận, tôi đã đọc tài liệu."],["みんなで将来について議論しました。","Mọi người đã cùng thảo luận về tương lai."]]},{"word":"ゆれる","reading":"ゆれる","meaning":"rung","hanViet":"","lesson":14,"ex":[["地震で家がゆれました。","Nhà rung lắc vì động đất."],["風で木がゆれています。","Cây đang rung vì gió."],["電車がゆれて、少し怖かったです。","Tàu rung lắc nên tôi hơi sợ."],["橋がゆれました。","Cầu đã rung."],["地震で、建物が少しゆれました。","Tòa nhà rung nhẹ vì động đất."]]},{"word":"被害","reading":"ひがい","meaning":"thiệt hại","hanViet":"BỊ HẠI","lesson":14,"ex":[["台風で大きな被害が出ました。","Bão đã gây thiệt hại lớn."],["地震の被害をニュースで見ました。","Tôi đã xem thiệt hại động đất trên tin tức."],["被害が少ないと、聞きました。","Tôi nghe nói thiệt hại ít."],["被害を受けた人を助けます。","Tôi giúp đỡ người bị thiệt hại."],["洪水の被害は、とても大きいです。","Thiệt hại do lũ lụt rất lớn."]]},{"word":"関係者","reading":"かんけいしゃ","meaning":"người liên quan","hanViet":"QUAN HỆ GIẢ","lesson":14,"ex":[["関係者は、会議に出ました。","Người liên quan đã tham dự cuộc họp."],["関係者に連絡しました。","Tôi đã liên lạc với người liên quan."],["関係者以外は、この部屋に入れません。","Người không liên quan không được vào phòng này."],["関係者が集まって、会議をしました。","Người liên quan đã tụ họp và họp."],["関係者の名前を書きました。","Tôi đã viết tên người liên quan."]]},{"word":"負けるが勝ち","reading":"まけるがかち","meaning":"đôi lúc cần nhường đối thủ một keo để rồi giành thắng lợi chung cuộc","hanViet":"PHỤ THẮNG","lesson":14,"ex":[["「負けるが勝ち」ということわざがあります。","Có câu tục ngữ \"thua là thắng\"."],["時には、負けるが勝ちだと思います。","Đôi khi, tôi nghĩ thua cũng là thắng."],["負けるが勝ちだと思って、静かに帰りました。","Nghĩ thua là thắng, tôi lặng lẽ ra về."],["負けるが勝ちという、ことわざを知っていますか。","Bạn có biết câu tục ngữ \"thua là thắng\" không?"],["負けるが勝ちという、ことわざは有名です。","Câu tục ngữ \"thua là thắng\" rất nổi tiếng."]]},{"word":"得","reading":"とく","meaning":"lợi","hanViet":"ĐẮC","lesson":14,"ex":[["早起きは三文の得という、ことわざがあります。","Có câu tục ngữ \"dậy sớm có ba đồng lợi\"."],["この仕事は、得が多いです。","Công việc này có nhiều lợi."],["得をするために、努力します。","Để có lợi, tôi nỗ lực."],["彼は自分の得だけを考えています。","Anh ấy chỉ nghĩ đến lợi ích của mình."],["この店で買うと、得です。","Mua ở cửa hàng này thì có lợi."]]},{"word":"外食する","reading":"がいしょくする","meaning":"ăn ngoài, ăn tiệm","hanViet":"NGOẠI THỰC","lesson":14,"ex":[["週末は、よく外食します。","Cuối tuần, tôi thường ăn ngoài."],["友達と外食しました。","Tôi đã ăn ngoài với bạn."],["外食すると、お金がかかります。","Ăn ngoài thì tốn tiền."],["母はあまり外食しません。","Mẹ tôi ít ăn ngoài."],["外食するより、家で食べるほうが安いです。","Ăn ở nhà rẻ hơn ăn ngoài."]]},{"word":"ちらし寿司","reading":"ちらしずし","meaning":"Chirashizushi (một món ăn có cơm ở dưới với sashimi, gừng … ở trên)","hanViet":"THỌ TƯ","lesson":14,"ex":[["ちらし寿司は、見た目がきれいです。","Chirashizushi trông rất đẹp."],["母はちらし寿司を作りました。","Mẹ đã làm chirashizushi."],["誕生日に、ちらし寿司を食べました。","Vào sinh nhật, tôi đã ăn chirashizushi."],["ちらし寿司の上に、魚があります。","Trên chirashizushi có cá."],["レストランでちらし寿司を注文しました。","Tôi đã gọi chirashizushi ở nhà hàng."]]},{"word":"ダイレクトメール","reading":"ダイレクトメール","meaning":"thư quảng cáo","hanViet":"","lesson":14,"ex":[["ダイレクトメールが毎日届きます。","Thư quảng cáo đến mỗi ngày."],["ダイレクトメールを読んでから、捨てました。","Tôi đã đọc thư quảng cáo rồi vứt."],["会社からダイレクトメールが来ました。","Thư quảng cáo đã đến từ công ty."],["ダイレクトメールで、新しい店を知りました。","Tôi biết cửa hàng mới qua thư quảng cáo."],["ダイレクトメールが多すぎます。","Thư quảng cáo quá nhiều."]]},{"word":"宣伝する","reading":"せんでんする","meaning":"quảng cáo","hanViet":"TUYÊN TRUYỀN","lesson":14,"ex":[["会社は新しい商品を宣伝しています。","Công ty đang quảng cáo sản phẩm mới."],["テレビで宣伝する店が増えました。","Cửa hàng quảng cáo trên TV đã tăng."],["宣伝するために、ポスターを作りました。","Để quảng cáo, tôi đã làm áp phích."],["この本を宣伝する広告を見ました。","Tôi đã xem quảng cáo quảng bá cuốn sách này."],["宣伝すると、店が有名になります。","Quảng cáo thì cửa hàng trở nên nổi tiếng."]]},{"word":"郵送する","reading":"ゆうそうする","meaning":"gửi bằng đường bưu điện","hanViet":"BƯU TỐNG","lesson":14,"ex":[["手紙を郵送しました。","Tôi đã gửi thư qua bưu điện."],["本を郵送するのに、長い時間がかかりました。","Gửi sách qua bưu điện mất thời gian dài."],["書類を郵送で送りました。","Tôi đã gửi tài liệu qua đường bưu điện."],["郵送する前に、住所を書きました。","Trước khi gửi qua bưu điện, tôi đã viết địa chỉ."],["プレゼントを郵送しました。","Tôi đã gửi quà qua bưu điện."]]},{"word":"夕刊","reading":"ゆうかん","meaning":"báo phát hành vào buổi chiều","hanViet":"TỊCH SAN","lesson":14,"ex":[["夕刊を買って、読みました。","Tôi đã mua báo chiều và đọc."],["夕刊に、地震のニュースが出ました。","Tin động đất đã đăng trên báo chiều."],["夕方に、夕刊を読みます。","Buổi chiều tối, tôi đọc báo chiều."],["夕刊は、夕方に届きます。","Báo chiều đến vào buổi chiều tối."],["夕刊を読むのが、私の習慣です。","Đọc báo chiều là thói quen của tôi."]]},{"word":"発行する","reading":"はっこうする","meaning":"phát hành","hanViet":"PHÁT HÀNH","lesson":14,"ex":[["会社は新しい雑誌を発行しました。","Công ty đã phát hành tạp chí mới."],["学校は新聞を発行しています。","Trường đang phát hành báo."],["本を発行する前に、よく読みました。","Trước khi phát hành sách, tôi đã đọc kỹ."],["切手を発行する会社があります。","Có công ty phát hành tem."],["新しい切手を発行しました。","Họ đã phát hành tem mới."]]},{"word":"早起きは三文の得","reading":"はやおきはさんもんのとく","meaning":"dậy sớm có nhiều cái lợi","hanViet":"TẢO KHỞI TAM VĂN ĐẮC","lesson":14,"ex":[["「早起きは三文の得」ということわざがあります。","Có câu tục ngữ \"dậy sớm có ba đồng lợi\"."],["早起きは三文の得だと思って、毎朝起きます。","Nghĩ rằng dậy sớm có lợi, tôi dậy mỗi sáng."],["母は「早起きは三文の得」とよく言います。","Mẹ tôi thường nói \"dậy sớm có lợi\"."],["早起きは三文の得という、ことわざを先生に教えてもらいました。","Tôi đã được thầy dạy câu tục ngữ \"dậy sớm có lợi\"."],["早起きは三文の得ですから、毎朝起きましょう。","Vì dậy sớm có lợi, hãy dậy mỗi sáng."]]},{"word":"早起き","reading":"はやおき","meaning":"thức dậy sớm","hanViet":"TẢO KHỞI","lesson":14,"ex":[["早起きは、体にいいです。","Dậy sớm tốt cho cơ thể."],["私は早起きが苦手です。","Tôi không giỏi dậy sớm."],["早起きをして、散歩しました。","Tôi đã dậy sớm và đi dạo."],["早起きの習慣があります。","Tôi có thói quen dậy sớm."],["試験の前に、早起きをしました。","Trước kỳ thi, tôi đã dậy sớm."]]},{"word":"自然エネルギー","reading":"しぜんエネルギー","meaning":"năng lượng tự nhiên","hanViet":"TỰ NHIÊN","lesson":14,"ex":[["自然エネルギーは、環境にいいです。","Năng lượng tự nhiên tốt cho môi trường."],["自然エネルギーを使う会社が増えています。","Công ty dùng năng lượng tự nhiên đang tăng."],["太陽は、自然エネルギーの一つです。","Mặt trời là một trong các nguồn năng lượng tự nhiên."],["自然エネルギーについて、学校で勉強しました。","Tôi đã học về năng lượng tự nhiên ở trường."],["自然エネルギーは、これからもっと大切になります。","Năng lượng tự nhiên sẽ càng quan trọng hơn nữa."]]},{"word":"地域社会","reading":"ちいきしゃかい","meaning":"cộng đồng khu vực","hanViet":"ĐỊA VỰC XÃ HỘI","lesson":14,"ex":[["地域社会のために、ボランティアをします。","Vì cộng đồng khu vực, tôi làm tình nguyện."],["地域社会の人と話しました。","Tôi đã nói chuyện với người trong cộng đồng khu vực."],["地域社会の問題を考えました。","Tôi đã suy nghĩ về vấn đề của cộng đồng khu vực."],["地域社会をよくするために、みんなで働きます。","Để cải thiện cộng đồng khu vực, mọi người cùng làm việc."],["地域社会のために、活動しています。","Tôi đang hoạt động vì cộng đồng khu vực."]]},{"word":"分析する","reading":"ぶんせきする","meaning":"phân tích","hanViet":"PHÂN TÍCH","lesson":14,"ex":[["資料を分析しました。","Tôi đã phân tích tài liệu."],["データを分析する仕事をしています。","Tôi làm công việc phân tích dữ liệu."],["先生は問題を分析しました。","Thầy giáo đã phân tích vấn đề."],["結果を分析して、先生に話しました。","Tôi đã phân tích kết quả và nói với thầy giáo."],["分析する前に、データを集めました。","Trước khi phân tích, tôi đã thu thập dữ liệu."]]},{"word":"部署","reading":"ぶしょ","meaning":"phòng ban","hanViet":"BỘ THỰ","lesson":14,"ex":[["私の部署は、営業です。","Phòng ban của tôi là kinh doanh."],["部署の人が集まりました。","Người trong phòng ban đã tụ họp."],["新しい部署に変わりました。","Tôi đã chuyển sang phòng ban mới."],["部署で会議をしました。","Chúng tôi đã họp ở phòng ban."],["田中さんは、営業の部署で働いています。","Anh Tanaka làm việc ở phòng kinh doanh."]]},{"word":"活動する","reading":"かつどうする","meaning":"hoạt động","hanViet":"HOẠT ĐỘNG","lesson":14,"ex":[["学校で活動しています。","Tôi đang hoạt động ở trường."],["私はスポーツクラブで活動しています。","Tôi đang hoạt động ở câu lạc bộ thể thao."],["彼は大学で活動しています。","Anh ấy đang hoạt động ở trường đại học."],["活動する時間が、あまりありません。","Tôi ít có thời gian hoạt động."],["みんなで活動して、町をきれいにしました。","Mọi người cùng hoạt động, làm thị trấn sạch đẹp."]]},{"word":"ボランティア活動","reading":"ボランティアかつどう","meaning":"hoạt động tình nguyện","hanViet":"HOẠT ĐỘNG","lesson":14,"ex":[["ボランティア活動に参加しました。","Tôi đã tham gia hoạt động tình nguyện."],["週末に、ボランティア活動をします。","Cuối tuần, tôi làm hoạt động tình nguyện."],["ボランティア活動は、とても大切です。","Hoạt động tình nguyện rất quan trọng."],["学生はボランティア活動をしています。","Sinh viên đang làm hoạt động tình nguyện."],["ボランティア活動で、友達ができました。","Nhờ hoạt động tình nguyện, tôi đã có bạn."]]},{"word":"改善する","reading":"かいぜんする","meaning":"cải thiện","hanViet":"CẢI THIỆN","lesson":14,"ex":[["生活を改善しました。","Tôi đã cải thiện cuộc sống."],["仕事の方法を改善します。","Tôi cải thiện phương pháp làm việc."],["健康を改善するために、運動します。","Để cải thiện sức khỏe, tôi tập thể dục."],["学校の食堂を改善しました。","Họ đã cải thiện nhà ăn của trường."],["改善して、結果が変わりました。","Sau khi cải thiện, kết quả đã thay đổi."]]},{"word":"対策","reading":"たいさく","meaning":"giải pháp","hanViet":"ĐỐI SÁCH","lesson":14,"ex":[["地震の対策を考えました。","Tôi đã nghĩ biện pháp đối phó động đất."],["対策が必要です。","Cần có giải pháp."],["会社は新しい対策を作りました。","Công ty đã tạo giải pháp mới."],["対策をとる前に、問題を調べました。","Trước khi đưa ra giải pháp, tôi đã tìm hiểu vấn đề."],["この対策は、とてもいいです。","Giải pháp này rất tốt."]]},{"word":"ヨガ","reading":"ヨガ","meaning":"Yoga","hanViet":"","lesson":14,"ex":[["ヨガは、体にいいです。","Yoga tốt cho cơ thể."],["毎週、ヨガをします。","Mỗi tuần, tôi tập yoga."],["ヨガを始めて、元気になりました。","Bắt đầu tập yoga, tôi đã khỏe hơn."],["友達とヨガを習います。","Tôi học yoga cùng bạn."],["ヨガの教室に行きます。","Tôi đến lớp học yoga."]]},{"word":"ジャズダンス","reading":"ジャズダンス","meaning":"nhảy Jazz","hanViet":"","lesson":14,"ex":[["ジャズダンスを習っています。","Tôi đang học nhảy jazz."],["ジャズダンスは、楽しいです。","Nhảy jazz rất vui."],["ジャズダンスの教室に行きます。","Tôi đến lớp nhảy jazz."],["友達とジャズダンスを踊りました。","Tôi đã nhảy jazz cùng bạn."],["ジャズダンスを始めて、体が軽くなりました。","Bắt đầu nhảy jazz, cơ thể tôi đã nhẹ nhõm hơn."]]},{"word":"マッサージ","reading":"マッサージ","meaning":"mát-xa","hanViet":"","lesson":14,"ex":[["マッサージを受けました。","Tôi đã được mát-xa."],["肩のマッサージをしました。","Tôi đã mát-xa vai."],["マッサージをすると、体が軽くなります。","Mát-xa thì cơ thể nhẹ nhõm hơn."],["母にマッサージをしました。","Tôi đã mát-xa cho mẹ."],["マッサージの店に行きました。","Tôi đã đến tiệm mát-xa."]]},{"word":"スポーツジム","reading":"スポーツジム","meaning":"phòng gym, phòng tập thể dục","hanViet":"","lesson":14,"ex":[["スポーツジムに行きます。","Tôi đến phòng gym."],["スポーツジムで運動します。","Tôi tập thể dục ở phòng gym."],["スポーツジムの会員になりました。","Tôi đã trở thành hội viên phòng gym."],["毎週、スポーツジムで泳ぎます。","Mỗi tuần, tôi bơi ở phòng gym."],["スポーツジムは、家から近いです。","Phòng gym gần nhà."]]},{"word":"～余り","reading":"～あまり","meaning":"hơn, trên","hanViet":"DƯ","lesson":14,"ex":[["この町は、100年余りの歴史があります。","Thị trấn này có lịch sử hơn 100 năm."],["この店は、50年余りあります。","Cửa hàng này đã có hơn 50 năm."],["彼は、10年余り日本に住んでいます。","Anh ấy đã sống ở Nhật hơn 10 năm."],["この本は、200年余り前に書かれました。","Cuốn sách này được viết hơn 200 năm trước."],["100人余りの人が集まりました。","Hơn 100 người đã tụ họp."]]},{"word":"NGO","reading":"エヌジーオー","meaning":"tổ chức phi chính phủ","hanViet":"","lesson":14,"ex":[["NGOで働く人が増えています。","Người làm việc ở NGO đang tăng."],["NGOの仕事を手伝いました。","Tôi đã giúp công việc của NGO."],["NGOは、世界の子どもを助けます。","NGO giúp đỡ trẻ em trên thế giới."],["彼はNGOで働いています。","Anh ấy đang làm việc ở NGO."],["NGOの話を聞きました。","Tôi đã nghe chuyện về NGO."]]},{"word":"グローバル","reading":"グローバル","meaning":"toàn cầu","hanViet":"","lesson":14,"ex":[["グローバルな社会になりました。","Đã trở thành xã hội toàn cầu."],["グローバルな問題を考えます。","Tôi suy nghĩ về vấn đề toàn cầu."],["グローバルな会社で働きたいです。","Tôi muốn làm việc ở công ty toàn cầu."],["グローバルな時代です。","Đây là thời đại toàn cầu."],["グローバルな社会で、英語が必要です。","Trong xã hội toàn cầu, tiếng Anh là cần thiết."]]},{"word":"夏日","reading":"なつび","meaning":"ngày hè nóng bức","hanViet":"HẠ NHẬT","lesson":14,"ex":[["夏日が続いています。","Ngày hè nóng bức đang tiếp diễn."],["夏日には、水をたくさん飲みます。","Vào ngày hè nóng bức, tôi uống nhiều nước."],["夏日で、とても暑いです。","Ngày hè nóng bức, rất nóng."],["夏日が続くと、体が疲れます。","Ngày hè nóng kéo dài thì cơ thể mệt."],["夏日には、冷たいアイスクリームを食べます。","Vào ngày hè nóng, tôi ăn kem lạnh."]]},{"word":"回復する","reading":"かいふくする","meaning":"hồi phục","hanViet":"HỒI PHỤC","lesson":14,"ex":[["病気から回復しました。","Tôi đã hồi phục sau bệnh."],["体が回復しました。","Cơ thể tôi đã hồi phục."],["景気が回復しています。","Kinh tế đang hồi phục."],["元気が回復しました。","Tôi đã lấy lại sức khỏe."],["回復するまで、休みます。","Tôi nghỉ ngơi cho đến khi hồi phục."]]},{"word":"住民","reading":"じゅうみん","meaning":"người dân, cư dân","hanViet":"TRÚ DÂN","lesson":14,"ex":[["住民が集まって、会議をしました。","Cư dân đã tụ họp và họp."],["住民の意見を聞きました。","Tôi đã nghe ý kiến của cư dân."],["この町の住民は、親切です。","Cư dân thị trấn này rất tốt bụng."],["住民が増えています。","Cư dân đang tăng."],["住民のために、新しい公園を作りました。","Vì cư dân, họ đã làm công viên mới."]]},{"word":"インストールする","reading":"インストールする","meaning":"cài đặt","hanViet":"","lesson":14,"ex":[["新しいソフトをインストールしました。","Tôi đã cài phần mềm mới."],["パソコンにソフトをインストールしました。","Tôi đã cài phần mềm vào máy tính."],["インストールする前に、よく調べました。","Trước khi cài đặt, tôi đã tìm hiểu kỹ."],["インストールが終わりました。","Việc cài đặt đã xong."],["友達にインストールを手伝ってもらいました。","Tôi đã nhờ bạn giúp cài đặt."]]},{"word":"生産","reading":"せいさん","meaning":"sự sản xuất","hanViet":"SINH SẢN","lesson":14,"ex":[["この工場では、車を生産しています。","Ở nhà máy này, họ đang sản xuất ô tô."],["生産が増えました。","Sản xuất đã tăng."],["米の生産は、日本で大切です。","Sản xuất gạo quan trọng ở Nhật."],["生産する前に、計画を作ります。","Trước khi sản xuất, họ lập kế hoạch."],["生産が減りました。","Sản xuất đã giảm."]]},{"word":"野球大会","reading":"やきゅうたいかい","meaning":"giải đấu bóng chày","hanViet":"DÃ CẦU ĐẠI HỘI","lesson":14,"ex":[["野球大会に出ました。","Tôi đã tham gia giải đấu bóng chày."],["野球大会で、学校が勝ちました。","Ở giải đấu bóng chày, trường tôi đã thắng."],["野球大会を見に行きました。","Tôi đã đi xem giải đấu bóng chày."],["野球大会の前に、練習しました。","Trước giải đấu bóng chày, chúng tôi đã luyện tập."],["野球大会は、夏にあります。","Giải đấu bóng chày diễn ra vào mùa hè."]]},{"word":"悔しい","reading":"くやしい","meaning":"tiếc nuối","hanViet":"HỐI","lesson":14,"ex":[["試合に負けて、悔しいです。","Thua trận đấu nên tôi tiếc nuối."],["悔しい気持ちです。","Tôi có cảm giác tiếc nuối."],["試験に失敗して、悔しいです。","Thi trượt nên tôi tiếc."],["悔しいけれど、また頑張ります。","Tiếc nuối nhưng tôi sẽ cố gắng lại."],["悔しい試合でした。","Đó là trận đấu đầy tiếc nuối."]]},{"word":"後ろ姿","reading":"うしろすがた","meaning":"dáng vẻ nhìn từ sau lưng","hanViet":"HẬU TƯ","lesson":14,"ex":[["母の後ろ姿を見ました。","Tôi đã thấy dáng mẹ từ phía sau."],["後ろ姿が、とてもきれいです。","Dáng nhìn từ sau rất đẹp."],["彼の後ろ姿は、大きく見えます。","Dáng anh ấy nhìn từ sau trông to lớn."],["子どもの後ろ姿を写真に撮りました。","Tôi đã chụp ảnh dáng đứa trẻ từ phía sau."],["後ろ姿だけでは、だれかわかりません。","Chỉ nhìn từ sau thì không biết là ai."]]},{"word":"女優","reading":"じょゆう","meaning":"nữ diễn viên","hanViet":"NỮ ƯU","lesson":14,"ex":[["彼女は有名な女優です。","Cô ấy là nữ diễn viên nổi tiếng."],["女優の声が、とてもきれいです。","Giọng nữ diễn viên rất đẹp."],["その女優は、映画に出ました。","Nữ diễn viên đó đã đóng phim."],["女優に会いました。","Tôi đã gặp nữ diễn viên."],["女優の写真を見ました。","Tôi đã xem ảnh nữ diễn viên."]]},{"word":"演劇","reading":"えんげき","meaning":"kịch","hanViet":"DIỄN KỊCH","lesson":14,"ex":[["演劇を見に行きました。","Tôi đã đi xem kịch."],["学校で演劇をしました。","Chúng tôi đã diễn kịch ở trường."],["演劇は、とても楽しいです。","Kịch rất vui."],["演劇のために、練習しました。","Tôi đã luyện tập cho vở kịch."],["演劇部の演劇を見ました。","Tôi đã xem vở kịch của câu lạc bộ kịch."]]},{"word":"～部","reading":"～ぶ","meaning":"câu lạc bộ","hanViet":"BỘ","lesson":14,"ex":[["私は演劇部に入っています。","Tôi đang ở câu lạc bộ kịch."],["彼は野球部に入りました。","Anh ấy đã vào câu lạc bộ bóng chày."],["サッカー部とテニス部があります。","Có câu lạc bộ bóng đá và câu lạc bộ tennis."],["美術部で絵を見ます。","Tôi xem tranh ở câu lạc bộ mỹ thuật."],["部のみんなと練習しました。","Tôi đã luyện tập cùng mọi người trong câu lạc bộ."]]},{"word":"成長する","reading":"せいちょうする","meaning":"trưởng thành","hanViet":"THÀNH TRƯỞNG","lesson":14,"ex":[["子どもは、毎日成長します。","Trẻ em lớn lên mỗi ngày."],["会社は、大きく成長しました。","Công ty đã phát triển lớn."],["木が成長しています。","Cây đang lớn."],["成長するために、よく食べます。","Để lớn lên, tôi ăn nhiều."],["彼は、高校で成長しました。","Anh ấy đã trưởng thành ở trường trung học."]]},{"word":"役","reading":"やく","meaning":"vai, vai diễn","hanViet":"DỊCH","lesson":14,"ex":[["彼は、映画で大切な役をもらいました。","Anh ấy đã nhận vai quan trọng trong phim."],["この役は、私に合っています。","Vai này hợp với tôi."],["役をもらうのは、難しいです。","Nhận được vai diễn thì khó."],["彼女は、先生の役をしました。","Cô ấy đã đóng vai thầy giáo."],["彼は、役をよく覚えます。","Anh ấy nhớ vai rất tốt."]]},{"word":"最中","reading":"さいちゅう","meaning":"giữa chừng, trong khi","hanViet":"TỐI TRUNG","lesson":14,"ex":[["勉強の最中に、電話が来ました。","Đang học thì điện thoại đến."],["会議の最中に、地震がありました。","Đang họp thì có động đất."],["食事の最中に、友達が来ました。","Đang ăn thì bạn đến."],["映画の最中に、寝ました。","Đang xem phim thì tôi đã ngủ thiếp đi."],["話の最中に、友達が帰りました。","Đang nói chuyện thì bạn đã về."]]},{"word":"非常ベル","reading":"ひじょうベル","meaning":"chuông báo động","hanViet":"PHI THƯỜNG","lesson":14,"ex":[["非常ベルが鳴りました。","Chuông báo động đã reo."],["非常ベルが鳴ったら、逃げてください。","Khi chuông báo động reo, hãy chạy."],["火事のとき、非常ベルが鳴ります。","Khi có hỏa hoạn, chuông báo động reo."],["非常ベルを押しました。","Tôi đã bấm chuông báo động."],["非常ベルの音が聞こえました。","Tôi đã nghe thấy tiếng chuông báo động."]]},{"word":"実は","reading":"じつは","meaning":"thực ra","hanViet":"THỰC","lesson":14,"ex":[["実は、私は日本に住んでいます。","Thực ra, tôi đang sống ở Nhật."],["実は、彼は私の兄です。","Thực ra, anh ấy là anh trai tôi."],["実は、その本を持っています。","Thực ra, tôi có cuốn sách đó."],["実は、明日試験があります。","Thực ra, ngày mai có kỳ thi."],["実は、私はその映画を見ました。","Thực ra, tôi đã xem bộ phim đó."]]},{"word":"活気","reading":"かっき","meaning":"sức sống","hanViet":"HOẠT KHÍ","lesson":14,"ex":[["この町は、活気があります。","Thị trấn này có sức sống."],["祭りは、活気にあふれています。","Lễ hội tràn đầy sức sống."],["店に活気が戻りました。","Cửa hàng đã lấy lại sức sống."],["活気のある町です。","Đây là thị trấn đầy sức sống."],["子どもたちの声で、活気が生まれました。","Tiếng trẻ em đã mang lại sức sống."]]},{"word":"風景","reading":"ふうけい","meaning":"phong cảnh","hanViet":"PHONG CẢNH","lesson":14,"ex":[["京都の風景は、とてもきれいです。","Phong cảnh Kyoto rất đẹp."],["海の風景を見ました。","Tôi đã ngắm phong cảnh biển."],["窓から風景が見えます。","Từ cửa sổ có thể thấy phong cảnh."],["風景の写真を撮りました。","Tôi đã chụp ảnh phong cảnh."],["山の風景が好きです。","Tôi thích phong cảnh núi."]]},{"word":"生き生きする","reading":"いきいきする","meaning":"sống động, sinh động","hanViet":"SINH","lesson":14,"ex":[["子どもたちは、生き生きしています。","Trẻ em đang sống động."],["彼の目は、生き生きしています。","Mắt anh ấy đang sáng ngời."],["花が生き生きしています。","Hoa đang tươi tốt."],["魚は、生き生きと泳いでいます。","Cá đang bơi lội sống động."],["彼女は、生き生きと話します。","Cô ấy nói chuyện đầy sinh khí."]]},{"word":"実写する","reading":"じっしゃする","meaning":"quay live-action (quay bằng người thật thay vì hoạt hình)","hanViet":"THỰC TẢ","lesson":14,"ex":[["この小説を実写しました。","Họ đã chuyển thể tiểu thuyết này thành phim người đóng."],["アニメを実写するのが、人気です。","Chuyển thể anime thành live-action đang được yêu thích."],["実写した映画を見ました。","Tôi đã xem bộ phim live-action."],["この漫画を実写しました。","Họ đã chuyển thể truyện tranh này thành phim người đóng."],["実写する前に、原作を読みました。","Trước khi chuyển thể live-action, tôi đã đọc tác phẩm gốc."]]},{"word":"通り過ぎる","reading":"とおりすぎる","meaning":"đi qua, lướt qua","hanViet":"THÔNG QUÁ","lesson":14,"ex":[["電車が駅を通り過ぎました。","Tàu đã đi qua ga."],["時間が通り過ぎるのは、速いです。","Thời gian trôi qua thật nhanh."],["彼は私の前を通り過ぎました。","Anh ấy đã đi qua trước mặt tôi."],["バスが通り過ぎて、乗れませんでした。","Xe buýt đã đi qua nên tôi không lên được."],["春が通り過ぎて、夏になりました。","Mùa xuân trôi qua, mùa hè đã đến."]]},{"word":"カップラーメン","reading":"カップラーメン","meaning":"mì ly","hanViet":"","lesson":14,"ex":[["カップラーメンを食べました。","Tôi đã ăn mì ly."],["夜に、カップラーメンを作りました。","Buổi tối, tôi đã làm mì ly."],["カップラーメンは、安いです。","Mì ly rẻ."],["カップラーメンに熱い水を入れました。","Tôi đã đổ nước nóng vào mì ly."],["忙しいときは、カップラーメンを食べます。","Khi bận, tôi ăn mì ly."]]},{"word":"温泉旅館","reading":"おんせんりょかん","meaning":"khách sạn có phục vụ tắm nước nóng onsen","hanViet":"ÔN TUYỀN LỮ QUÁN","lesson":14,"ex":[["温泉旅館に泊まりました。","Tôi đã ở khách sạn suối nước nóng."],["温泉旅館で温泉に入りました。","Tôi đã tắm onsen ở khách sạn suối nước nóng."],["温泉旅館の料理の味は、とてもいいです。","Món ăn ở khách sạn suối nước nóng có vị rất ngon."],["京都の温泉旅館に行きました。","Tôi đã đến khách sạn suối nước nóng ở Kyoto."],["温泉旅館を予約しました。","Tôi đã đặt khách sạn suối nước nóng."]]},{"word":"旅館","reading":"りょかん","meaning":"khách sạn kiểu Nhật truyền thống","hanViet":"LỮ QUÁN","lesson":14,"ex":[["旅館に泊まりました。","Tôi đã ở ryokan."],["旅館の部屋は、畳です。","Phòng ryokan lót chiếu tatami."],["旅館で料理を食べました。","Tôi đã ăn món ăn ở ryokan."],["旅館の人が親切でした。","Người ở ryokan rất tốt bụng."],["旅館は、駅から近いです。","Ryokan gần ga."]]},{"word":"オリジナリティー","reading":"オリジナリティー","meaning":"nét riêng, nét độc đáo","hanViet":"","lesson":14,"ex":[["この歌はオリジナリティーがあって、とても人気があります。","Bài hát này có nét độc đáo riêng nên rất được yêu thích."],["田中さんの絵はオリジナリティーがあります。","Tranh của anh Tanaka có nét độc đáo riêng."],["私はオリジナリティーのある店を作りたいと思っています。","Tôi muốn mở một cửa hàng có nét độc đáo riêng."],["この小説のオリジナリティーは、主人公にあります。","Nét độc đáo của cuốn tiểu thuyết này nằm ở nhân vật chính."],["オリジナリティーを大切にすれば、新しいものが生まれます。","Nếu coi trọng nét độc đáo riêng, những điều mới mẻ sẽ ra đời."]]},{"word":"キャラクター","reading":"キャラクター","meaning":"nhân vật","hanViet":"","lesson":14,"ex":[["このアニメのキャラクターは、子どもたちに人気があります。","Nhân vật trong bộ anime này rất được trẻ em yêu thích."],["私はこの映画のキャラクターが大好きです。","Tôi rất thích nhân vật trong bộ phim này."],["新しいキャラクターを作るのは、とても楽しい仕事です。","Tạo ra nhân vật mới là một công việc rất thú vị."],["田中さんはキャラクターの絵を描くのが上手です。","Anh Tanaka rất giỏi vẽ nhân vật."],["その店のキャラクターは、赤い帽子をかぶっています。","Nhân vật của cửa hàng đó đội chiếc mũ đỏ."]]},{"word":"説明文","reading":"せつめいぶん","meaning":"bài văn giải thích / văn bản thuyết minh","hanViet":"THUYẾT MINH VĂN","lesson":15,"ex":[["この説明文は、子どもにもわかりやすいです。","Bài văn giải thích này dễ hiểu ngay cả với trẻ em."],["試験では、説明文を読んで、質問に答えます。","Trong bài thi, thí sinh đọc bài văn giải thích rồi trả lời câu hỏi."],["先生は説明文を書くときの大切なことを教えてくれました。","Thầy giáo đã dạy chúng tôi điều quan trọng khi viết bài văn giải thích."],["説明文を書くときは、まず大切なことを決めます。","Khi viết bài văn giải thích, trước hết cần quyết định điều quan trọng."],["この本には、おもしろい説明文がたくさんあります。","Cuốn sách này có rất nhiều bài văn giải thích thú vị."]]},{"word":"右に出る","reading":"みぎにでる","meaning":"giỏi hơn, xuất sắc hơn","hanViet":"HỮU XUẤT","lesson":15,"ex":[["料理の腕では、山田さんの右に出る人はあまりいません。","Về tài nấu ăn, ít ai giỏi hơn anh Yamada."],["田中さんは英語では右に出る人がいないほど上手です。","Anh Tanaka giỏi tiếng Anh đến mức không ai hơn được anh ấy."],["その店のコーヒーは、右に出るものがないほどおいしいです。","Cà phê của quán đó ngon đến mức không có thứ gì sánh bằng."],["歌では、彼女の右に出る人は学校にいません。","Về ca hát, trong trường không ai hơn được cô ấy."],["私の母は、料理の右に出る人がいないと言われています。","Mẹ tôi được nói là không ai nấu ăn giỏi hơn bà."]]},{"word":"切り上げる","reading":"きりあげる","meaning":"ngắt, ngừng","hanViet":"THIẾT THƯỢNG","lesson":15,"ex":[["仕事を切り上げて、早く家に帰りました。","Tôi dừng công việc rồi về nhà sớm."],["会議は五時で切り上げました。","Cuộc họp đã kết thúc lúc 5 giờ."],["話を切り上げて、食事を始めましょう。","Chúng ta dừng câu chuyện lại và bắt đầu ăn cơm nhé."],["本を読むのを切り上げて、寝ました。","Tôi dừng đọc sách rồi đi ngủ."],["先生は授業を少し早く切り上げました。","Thầy giáo đã kết thúc buổi học sớm hơn một chút."]]},{"word":"謙遜（する）","reading":"けんそん（する）","meaning":"khiêm nhường, khiêm tốn","hanViet":"KHIÊM TỐN","lesson":15,"ex":[["田中さんはいつも謙遜していますが、本当はとても上手です。","Anh Tanaka lúc nào cũng khiêm tốn, nhưng thực ra anh ấy rất giỏi."],["彼女は謙遜して、「まだです」と言いました。","Cô ấy khiêm tốn nói: \"Tôi còn kém lắm\"."],["謙遜することは、日本では大切だと考えられています。","Khiêm tốn được coi là điều quan trọng ở Nhật Bản."],["山田さんはすばらしい仕事をしても、いつも謙遜しています。","Anh Yamada dù làm công việc tuyệt vời vẫn luôn khiêm tốn."],["あまり謙遜しすぎると、自分の気持ちが伝わりません。","Khiêm tốn quá mức thì cảm xúc của mình sẽ không truyền đạt được."]]},{"word":"そこで","reading":"","meaning":"vì vậy, vì thế","hanViet":"","lesson":15,"ex":[["電車が遅れました。そこで、タクシーで会社に行きました。","Tàu điện bị trễ. Vì vậy, tôi đã đi taxi đến công ty."],["雨が降ってきました。そこで、傘を買うことにしました。","Trời bắt đầu mưa. Vì thế, tôi đã quyết định mua một chiếc ô."],["この町には本屋がありません。そこで、インターネットで本を買います。","Thị trấn này không có hiệu sách. Vì vậy, tôi mua sách trên mạng."],["田中さんは忙しいです。そこで、私が手伝うことにしました。","Anh Tanaka đang bận. Vì thế, tôi đã quyết định giúp anh ấy."],["試験の日が近づきました。そこで、毎日三時間勉強しています。","Ngày thi đã đến gần. Vì vậy, tôi học ba tiếng mỗi ngày."]]},{"word":"行列","reading":"ぎょうれつ","meaning":"hàng","hanViet":"HÀNH LIỆT","lesson":15,"ex":[["その店の前には、長い行列ができていました。","Trước cửa hàng đó có một hàng dài đang xếp."],["朝早くから、行列に並ぶ人がたくさんいます。","Từ sáng sớm đã có rất nhiều người xếp hàng."],["行列が長かったので、一時間も待ちました。","Vì hàng dài nên tôi đã phải đợi cả một tiếng."],["駅の前では、バスを待つ人の行列がありました。","Trước ga có hàng người đang đợi xe buýt."],["人気の店には、いつも行列ができています。","Cửa hàng nổi tiếng lúc nào cũng có hàng dài xếp chờ."]]},{"word":"横目","reading":"よこめ","meaning":"liếc nhìn, liếc ngang","hanViet":"HOÀNH MỤC","lesson":15,"ex":[["田中さんは横目で時計を見ました。","Anh Tanaka liếc nhìn đồng hồ."],["彼女は横目で私を見て、笑いました。","Cô ấy liếc nhìn tôi rồi cười."],["先生は横目で生徒の答えを見ました。","Thầy giáo liếc nhìn đáp án của học sinh."],["山田さんは横目で新しい車を見ました。","Anh Yamada liếc nhìn chiếc xe mới."],["子どもは横目でケーキを見ていました。","Đứa trẻ đang liếc nhìn chiếc bánh."]]},{"word":"動き回る","reading":"うごきまわる","meaning":"đi lại khắp nơi","hanViet":"ĐỘNG HỒI","lesson":15,"ex":[["子どもたちは公園で元気に動き回っています。","Bọn trẻ đang chạy nhảy khắp công viên."],["田中さんは毎日会社の中を動き回っています。","Anh Tanaka ngày nào cũng đi lại khắp công ty."],["猫は部屋の中を動き回っています。","Con mèo đang đi lại khắp phòng."],["店員は忙しく店の中を動き回っていました。","Nhân viên cửa hàng đang bận rộn đi lại khắp cửa hàng."],["休みの日は、町の中を動き回って買い物をします。","Ngày nghỉ, tôi đi lại khắp phố để mua sắm."]]},{"word":"一見","reading":"いっけん","meaning":"thoáng qua","hanViet":"NHẤT KIẾN","lesson":15,"ex":[["一見、難しい問題に見えますが、よく考えると易しいです。","Thoạt nhìn, bài toán có vẻ khó, nhưng suy nghĩ kỹ thì lại dễ."],["一見、普通の家に見えますが、中はとても広いです。","Thoáng qua trông như ngôi nhà bình thường, nhưng bên trong rất rộng."],["一見すると、彼は静かな人に見えます。","Thoáng nhìn, anh ấy có vẻ là người trầm tính."],["この本は一見難しそうですが、読んでみるとおもしろいです。","Cuốn sách này thoạt nhìn có vẻ khó, nhưng đọc thử thì thấy thú vị."],["一見、易しそうに見える問題ですが、よく読むと難しいです。","Thoạt nhìn bài toán có vẻ dễ, nhưng đọc kỹ thì khó."]]},{"word":"行き来（する）","reading":"ゆきき（する）","meaning":"đi đi lại lại","hanViet":"HÀNH LAI","lesson":15,"ex":[["田中さんは毎日東京と大阪を行き来しています。","Anh Tanaka ngày nào cũng đi đi lại lại giữa Tokyo và Osaka."],["私は家と学校のあいだを行き来しています。","Tôi đi đi lại lại giữa nhà và trường."],["船はこの川を行き来しています。","Thuyền đi đi lại lại trên con sông này."],["母は台所と部屋のあいだを行き来して、食事の準備をしています。","Mẹ tôi đi đi lại lại giữa bếp và phòng để chuẩn bị bữa ăn."],["彼は二つの国のあいだを行き来する生活をしています。","Anh ấy sống cuộc sống đi đi lại lại giữa hai nước."]]},{"word":"担ぐ","reading":"かつぐ","meaning":"khiêng, vác","hanViet":"ĐẢM","lesson":15,"ex":[["田中さんは重い荷物を担いで、山を登りました。","Anh Tanaka vác hành lý nặng leo lên núi."],["祭りでは、男の人たちが大きな太鼓を担ぎます。","Trong lễ hội, những người đàn ông khiêng chiếc trống lớn."],["子どもはお父さんの肩に担がれて、うれしそうでした。","Đứa trẻ được bố cõng trên vai, trông rất vui."],["山田さんはかばんを担いで、駅まで歩きました。","Anh Yamada vác túi đi bộ đến ga."],["昔の人は、水を担いで山を登りました。","Người xưa vác nước leo lên núi."]]},{"word":"割合","reading":"わりあい","meaning":"tỉ lệ","hanViet":"CÁT HỢP","lesson":15,"ex":[["このクラスでは、女の人の割合が高いです。","Trong lớp này, tỉ lệ nữ giới cao."],["割合で見ると、今年のほうが去年より大きいです。","Xét theo tỉ lệ, năm nay lớn hơn năm ngoái."],["この町では、子どもの割合が大きいです。","Ở thị trấn này, tỉ lệ trẻ em lớn."],["この学校では、留学生の割合は半分です。","Ở trường này, tỉ lệ du học sinh là một nửa."],["割合を計算するのは、少し難しいです。","Tính tỉ lệ hơi khó."]]},{"word":"構成（する）","reading":"こうせい（する）","meaning":"tạo thành, cấu thành","hanViet":"CẤU THÀNH","lesson":15,"ex":[["この本は三つの部分で構成されています。","Cuốn sách này được cấu thành từ ba phần."],["会社は五つのチームで構成されています。","Công ty được cấu thành từ năm nhóm."],["この映画は、二つの話で構成されています。","Bộ phim này được cấu thành từ hai câu chuyện."],["チームは十人の社員で構成されています。","Nhóm được cấu thành từ mười nhân viên."],["この料理は、三つの材料で構成されています。","Món ăn này được cấu thành từ ba nguyên liệu."]]},{"word":"新（な）","reading":"あらた（な）","meaning":"mới","hanViet":"TÂN","lesson":15,"ex":[["新たな気持ちで、今年も努力します。","Với tâm trạng mới, năm nay tôi cũng sẽ nỗ lực."],["会社は新たな計画を立てました。","Công ty đã lập kế hoạch mới."],["新たな仕事が始まって、毎日が忙しいです。","Công việc mới bắt đầu nên ngày nào cũng bận rộn."],["先生は新たな問題を出しました。","Thầy giáo đã ra bài tập mới."],["新たな友達ができて、うれしいです。","Tôi rất vui vì đã có thêm bạn mới."]]},{"word":"組織（する）","reading":"そしき（する）","meaning":"tổ chức","hanViet":"TỔ CHỨC","lesson":15,"ex":[["会社は新しいチームを組織しました。","Công ty đã tổ chức một nhóm mới."],["私たちはボランティアのグループを組織しています。","Chúng tôi đang tổ chức một nhóm tình nguyện."],["学生たちは新しいチームを組織しました。","Các học sinh đã tổ chức một đội mới."],["この会社は、いろいろな国に組織を作っています。","Công ty này đang lập tổ chức ở nhiều nước."],["組織を大きくするには、時間がかかります。","Để tổ chức lớn mạnh cần có thời gian."]]},{"word":"集団","reading":"しゅうだん","meaning":"tập đoàn, đoàn thể","hanViet":"TẬP ĐOÀN","lesson":15,"ex":[["集団でいるときは、みんなのことを考えます。","Khi ở trong tập thể, cần nghĩ đến mọi người."],["子どもたちは集団で遊ぶのが好きです。","Trẻ em thích chơi theo nhóm."],["この集団は、環境を守るために活動しています。","Tập thể này đang hoạt động để bảo vệ môi trường."],["集団の力は、一人の力より大きいです。","Sức mạnh của tập thể lớn hơn sức mạnh của một người."],["学校では、集団で生活することを学びます。","Ở trường, học sinh học cách sống tập thể."]]},{"word":"経つ（時間が～）","reading":"たつ（じかんが～）","meaning":"(thời gian ~) trôi qua","hanViet":"KINH THỜI GIAN","lesson":15,"ex":[["時間が経つのは、とても速いです。","Thời gian trôi qua rất nhanh."],["日本に来てから、三年が経ちました。","Từ khi đến Nhật Bản, ba năm đã trôi qua."],["時間が経つと、気持ちも変わります。","Thời gian trôi qua, tâm trạng cũng thay đổi."],["あれから十年が経ちましたが、まだ覚えています。","Mười năm đã trôi qua kể từ đó, nhưng tôi vẫn còn nhớ."],["時間が経つのを忘れて、本を読みました。","Tôi đọc sách mà quên cả thời gian trôi qua."]]},{"word":"比率","reading":"ひりつ","meaning":"tỷ lệ","hanViet":"TỶ SUẤT","lesson":15,"ex":[["この学校では、男の子と女の子の比率は同じです。","Ở trường này, tỉ lệ nam nữ bằng nhau."],["比率を調べると、今年のほうが大きいです。","Kiểm tra tỉ lệ thì năm nay lớn hơn."],["この町の人口の比率を調べました。","Tôi đã kiểm tra tỉ lệ dân số của thị trấn này."],["比率が高いほど、問題は大きくなります。","Tỉ lệ càng cao, vấn đề càng lớn."],["先生は比率の計算を教えてくれました。","Thầy giáo đã dạy chúng tôi cách tính tỉ lệ."]]},{"word":"分担（する）","reading":"ぶんたん（する）","meaning":"phân công","hanViet":"PHÂN ĐẢM","lesson":15,"ex":[["仕事をみんなで分担しましょう。","Chúng ta cùng phân công công việc cho mọi người nhé."],["家事は家族で分担しています。","Việc nhà được phân công cho cả gia đình."],["先生は仕事を三つのグループに分担しました。","Thầy giáo đã phân công công việc cho ba nhóm."],["料理の準備を二人で分担しました。","Hai người chúng tôi đã phân công nhau chuẩn bị nấu ăn."],["分担を決めてから、仕事を始めました。","Sau khi quyết định phân công, chúng tôi bắt đầu làm việc."]]},{"word":"さすがに","reading":"","meaning":"đúng như mong đợi, quả đúng là… không hổ danh là …","hanViet":"","lesson":15,"ex":[["さすがに田中さんは上手ですね。","Quả đúng là anh Tanaka giỏi thật."],["さすがにこの店のコーヒーはおいしいです。","Quả đúng là cà phê của quán này ngon thật."],["さすがに先生は、たくさんのことを知っています。","Quả đúng là thầy giáo biết rất nhiều điều."],["さすがに彼女は、毎日練習しているだけあって上手です。","Quả đúng là cô ấy giỏi, vì ngày nào cũng luyện tập."],["さすがに有名な店は、味がいいです。","Quả đúng là cửa hàng nổi tiếng, vị rất ngon."]]},{"word":"能率","reading":"のうりつ","meaning":"năng suất","hanViet":"NĂNG SUẤT","lesson":15,"ex":[["新しい機械で、仕事の能率が上がりました。","Nhờ máy móc mới, năng suất làm việc đã tăng lên."],["能率を上げるために、計画を立てました。","Để nâng cao năng suất, tôi đã lập kế hoạch."],["朝は能率がいいので、難しい仕事をします。","Buổi sáng năng suất tốt nên tôi làm việc khó."],["能率が上がれば、早く帰ることができます。","Nếu năng suất tăng lên, tôi có thể về sớm."],["この方法は、能率が悪いです。","Phương pháp này có năng suất kém."]]},{"word":"落ちる（能率が～）","reading":"おちる（のうりつが～）","meaning":"giảm (năng suất)","hanViet":"LẠC NĂNG SUẤT","lesson":15,"ex":[["夜遅くなると、能率が落ちます。","Khi đêm khuya, năng suất giảm xuống."],["疲れると、能率が落ちます。","Khi mệt, năng suất giảm xuống."],["昼ごはんのあと、能率が少し落ちました。","Sau bữa trưa, năng suất giảm đi một chút."],["毎日同じ仕事をしていると、能率が落ちます。","Làm cùng một công việc mỗi ngày thì năng suất sẽ giảm."],["能率が落ちたので、少し休みました。","Vì năng suất giảm nên tôi đã nghỉ một chút."]]},{"word":"登場（する）","reading":"とうじょう（する）","meaning":"xuất hiện","hanViet":"ĐĂNG TRƯỜNG","lesson":15,"ex":[["新しいキャラクターが映画に登場しました。","Nhân vật mới đã xuất hiện trong phim."],["田中さんが舞台に登場すると、みんなが拍手をしました。","Khi anh Tanaka xuất hiện trên sân khấu, mọi người đều vỗ tay."],["この小説には、おもしろい人がたくさん登場します。","Trong cuốn tiểu thuyết này có rất nhiều người thú vị xuất hiện."],["新しい製品が店に登場しました。","Sản phẩm mới đã xuất hiện ở cửa hàng."],["彼女はテレビに登場して、有名になりました。","Cô ấy xuất hiện trên TV và trở nên nổi tiếng."]]},{"word":"ご存じ","reading":"ごぞんじ","meaning":"biết (kính ngữ của từ 'shitteiru')","hanViet":"TỒN","lesson":15,"ex":[["田中さんをご存じですか。","Anh có biết anh Tanaka không?"],["この店をご存じですか。","Anh có biết cửa hàng này không?"],["山田さんは、この話をご存じです。","Anh Yamada biết chuyện này."],["あの先生をご存じの方は、多いです。","Có nhiều người biết thầy giáo đó."],["新しい社長をご存じですか。","Anh có biết giám đốc mới không?"]]},{"word":"人材","reading":"じんざい","meaning":"nhân lực","hanViet":"NHÂN TÀI","lesson":15,"ex":[["この会社は、いい人材を探しています。","Công ty này đang tìm kiếm nhân lực tốt."],["人材を育てることは、大切な仕事です。","Đào tạo nhân lực là công việc quan trọng."],["日本では、人材が足りない会社が多いです。","Ở Nhật Bản có nhiều công ty thiếu nhân lực."],["この学校は、いい人材をたくさん育てています。","Trường này đang đào tạo rất nhiều nhân lực tốt."],["人材が集まれば、会社は大きくなります。","Nếu nhân lực tụ họp lại, công ty sẽ lớn mạnh."]]},{"word":"スタート（する）","reading":"","meaning":"bắt đầu","hanViet":"","lesson":15,"ex":[["新しい生活がスタートしました。","Cuộc sống mới đã bắt đầu."],["会議は十時にスタートします。","Cuộc họp bắt đầu lúc 10 giờ."],["映画は七時にスタートします。","Bộ phim bắt đầu lúc 7 giờ."],["田中さんは新しい仕事をスタートしました。","Anh Tanaka đã bắt đầu công việc mới."],["今年の計画がスタートしました。","Kế hoạch năm nay đã bắt đầu."]]},{"word":"特命","reading":"とくめい","meaning":"sứ mệnh đặc biệt, nhiệm vụ đặc biệt","hanViet":"ĐẶC MỆNH","lesson":15,"ex":[["田中さんは特命を受けて、京都に行きました。","Anh Tanaka nhận nhiệm vụ đặc biệt và đã đi Kyoto."],["社長は山田さんに特命を出しました。","Giám đốc đã giao nhiệm vụ đặc biệt cho anh Yamada."],["特命を受けたチームは、朝から仕事を始めました。","Nhóm nhận nhiệm vụ đặc biệt đã bắt đầu công việc từ sáng."],["この特命は、とても大切です。","Nhiệm vụ đặc biệt này rất quan trọng."],["特命を終えて、田中さんは東京に帰りました。","Hoàn thành nhiệm vụ đặc biệt, anh Tanaka đã trở về Tokyo."]]},{"word":"プロジェクト","reading":"","meaning":"dự án","hanViet":"","lesson":15,"ex":[["新しいプロジェクトが始まりました。","Dự án mới đã bắt đầu."],["田中さんはこのプロジェクトのリーダーです。","Anh Tanaka là trưởng nhóm của dự án này."],["プロジェクトを成功させるために、みんなで努力します。","Để dự án thành công, mọi người cùng nỗ lực."],["このプロジェクトは、三年で終わります。","Dự án này sẽ kết thúc trong ba năm."],["プロジェクトの計画を立てました。","Tôi đã lập kế hoạch cho dự án."]]},{"word":"スタープレイヤー","reading":"","meaning":"cầu thủ nổi tiếng, cầu thủ ngôi sao","hanViet":"","lesson":15,"ex":[["田中さんはチームのスタープレイヤーです。","Anh Tanaka là cầu thủ ngôi sao của đội."],["スタープレイヤーが試合に出ると、みんながうれしくなります。","Khi cầu thủ ngôi sao ra sân, mọi người đều vui mừng."],["そのスタープレイヤーは、子どもたちに人気があります。","Cầu thủ ngôi sao đó rất được trẻ em yêu thích."],["スタープレイヤーのおかげで、チームは強くなりました。","Nhờ cầu thủ ngôi sao, đội đã trở nên mạnh hơn."],["試合では、スタープレイヤーが一番目立ちます。","Trong trận đấu, cầu thủ ngôi sao nổi bật nhất."]]},{"word":"プレイヤー","reading":"","meaning":"cầu thủ, tuyển thủ","hanViet":"","lesson":15,"ex":[["このチームのプレイヤーは、みんな若いです。","Các cầu thủ của đội này đều còn trẻ."],["プレイヤーは毎日練習しています。","Các cầu thủ luyện tập mỗi ngày."],["新しいプレイヤーがチームに入りました。","Cầu thủ mới đã gia nhập đội."],["プレイヤーの数は、十一人です。","Số lượng cầu thủ là mười một người."],["そのプレイヤーは、足が速いです。","Cầu thủ đó chạy rất nhanh."]]},{"word":"チーム","reading":"","meaning":"nhóm, đội","hanViet":"","lesson":15,"ex":[["私たちのチームは、毎日練習しています。","Đội của chúng tôi luyện tập mỗi ngày."],["チームのみんなで、よく話し合います。","Cả đội thường xuyên thảo luận với nhau."],["新しいチームができました。","Một đội mới đã được thành lập."],["チームの名前を決めました。","Chúng tôi đã quyết định tên của đội."],["チームの仕事は、一人ではできません。","Công việc của đội không thể làm một mình."]]},{"word":"からめる","reading":"","meaning":"dính tới, lôi kéo/cuốn vào","hanViet":"","lesson":15,"ex":[["彼はその計画にからめられました。","Anh ấy đã bị cuốn vào kế hoạch đó."],["田中さんはその問題にからめられました。","Anh Tanaka đã bị cuốn vào vấn đề đó."],["新しい仕事にからめられて、毎日が忙しくなりました。","Bị cuốn vào công việc mới, ngày nào tôi cũng bận rộn."],["彼は友達の話にからめられました。","Anh ấy đã bị cuốn vào câu chuyện của bạn."],["その事件にからめられたくありません。","Tôi không muốn bị dính vào vụ việc đó."]]},{"word":"法則","reading":"ほうそく","meaning":"quy luật, định luật","hanViet":"PHÁP TẮC","lesson":15,"ex":[["この法則は、だれでも知っています。","Quy luật này ai cũng biết."],["先生は新しい法則を教えてくれました。","Thầy giáo đã dạy chúng tôi quy luật mới."],["法則を覚えるのは、少し難しいです。","Nhớ quy luật hơi khó."],["この法則は、生活の中でよく使われます。","Quy luật này thường được dùng trong cuộc sống."],["法則がわかれば、問題が易しくなります。","Nếu hiểu quy luật, bài toán sẽ trở nên dễ dàng."]]},{"word":"当たる（法則が～）","reading":"あたる（ほうそくが～）","meaning":"(đúng) quy luật","hanViet":"ĐƯƠNG PHÁP TẮC","lesson":15,"ex":[["この法則は、いつも当たります。","Quy luật này lúc nào cũng đúng."],["その法則が当たったので、先生はうれしそうでした。","Vì quy luật đó đã đúng nên thầy giáo trông rất vui."],["法則が当たるかどうか、調べてみます。","Tôi sẽ thử kiểm tra xem quy luật có đúng hay không."],["この法則が当たることが、よくあります。","Quy luật này thường đúng."],["法則が当たれば、答えがわかります。","Nếu quy luật đúng, sẽ biết được đáp án."]]},{"word":"脇役","reading":"わきやく","meaning":"vai phụ","hanViet":"HIẾP DỊCH","lesson":15,"ex":[["田中さんはこの映画の脇役です。","Anh Tanaka đóng vai phụ trong bộ phim này."],["脇役でも、大切な仕事があります。","Dù là vai phụ cũng có công việc quan trọng."],["彼女は脇役の仕事が好きです。","Cô ấy thích công việc đóng vai phụ."],["脇役の人も、映画には必要です。","Người đóng vai phụ cũng cần thiết cho bộ phim."],["私は脇役のほうが好きです。","Tôi thích vai phụ hơn."]]},{"word":"脚本","reading":"きゃくほん","meaning":"kịch bản","hanViet":"CƯỚC BẢN","lesson":15,"ex":[["田中さんは映画の脚本を書きました。","Anh Tanaka đã viết kịch bản phim."],["この脚本は、とてもおもしろいです。","Kịch bản này rất thú vị."],["脚本を読むと、話がわかります。","Đọc kịch bản sẽ hiểu được câu chuyện."],["先生は脚本を書くときの大切なことを教えてくれました。","Thầy giáo đã dạy chúng tôi điều quan trọng khi viết kịch bản."],["脚本ができたら、練習を始めます。","Khi kịch bản xong, chúng tôi sẽ bắt đầu luyện tập."]]},{"word":"偉大","reading":"いだい","meaning":"to lớn, vĩ đại","hanViet":"VĨ ĐẠI","lesson":15,"ex":[["彼は偉大な人だと言われています。","Anh ấy được nói là một con người vĩ đại."],["偉大な仕事をするには、時間がかかります。","Để làm công việc vĩ đại cần có thời gian."],["その先生は、偉大なことを発見しました。","Thầy giáo đó đã phát hiện ra điều vĩ đại."],["偉大な力を持つ人は、優しいです。","Người có sức mạnh vĩ đại thì hiền lành."],["この本は、偉大な人の話です。","Cuốn sách này là câu chuyện về một con người vĩ đại."]]},{"word":"脈拍","reading":"みゃくはく","meaning":"nhịp đập của mạch","hanViet":"MẠCH PHÁCH","lesson":15,"ex":[["運動のあと、脈拍を測りました。","Sau khi vận động, tôi đã đo nhịp mạch."],["脈拍が速いときは、少し休みます。","Khi nhịp mạch nhanh, tôi nghỉ một chút."],["医者は患者の脈拍を見ました。","Bác sĩ đã xem nhịp mạch của bệnh nhân."],["走ると、脈拍が速くなります。","Khi chạy, nhịp mạch trở nên nhanh hơn."],["脈拍は、健康を知るための大切なものです。","Nhịp mạch là thứ quan trọng để biết sức khỏe."]]},{"word":"上がる（脈拍が～）","reading":"あがる（みゃくはくが～）","meaning":"(nhịp đập của mạch) tăng lên","hanViet":"THƯỢNG MẠCH PHÁCH","lesson":15,"ex":[["走ると、脈拍が上がります。","Khi chạy, nhịp mạch tăng lên."],["びっくりすると、脈拍が上がります。","Khi giật mình, nhịp mạch tăng lên."],["試験の前は、脈拍が上がりました。","Trước kỳ thi, nhịp mạch của tôi đã tăng lên."],["階段を登ると、脈拍が上がります。","Khi leo cầu thang, nhịp mạch tăng lên."],["運動をすると、脈拍が上がります。","Khi vận động, nhịp mạch tăng lên."]]},{"word":"アドレナリン","reading":"","meaning":"hóc-môn adrenalin","hanViet":"","lesson":15,"ex":[["試合の前は、アドレナリンが出ます。","Trước trận đấu, adrenalin tiết ra."],["アドレナリンが出ると、体が元気になります。","Khi adrenalin tiết ra, cơ thể trở nên khỏe khoắn."],["危険なとき、アドレナリンが出ます。","Khi nguy hiểm, adrenalin tiết ra."],["アドレナリンのおかげで、速く走ることができました。","Nhờ adrenalin, tôi đã có thể chạy nhanh."],["試験の前は、アドレナリンがたくさん出ます。","Trước kỳ thi, adrenalin tiết ra rất nhiều."]]},{"word":"徐々に","reading":"じょじょに","meaning":"từ từ, dần dần","hanViet":"TỪ","lesson":15,"ex":[["徐々に日本語が上手になってきました。","Dần dần tiếng Nhật của tôi đã giỏi lên."],["天気が徐々に悪くなりました。","Thời tiết dần dần trở nên xấu đi."],["徐々に仕事に慣れてきました。","Dần dần tôi đã quen với công việc."],["町は徐々に大きくなっています。","Thị trấn đang dần dần lớn lên."],["徐々に暖かくなってきました。","Trời dần dần ấm lên."]]},{"word":"疲弊（する）","reading":"ひへい（する）","meaning":"kiệt sức","hanViet":"BÌ TỆ","lesson":15,"ex":[["長い仕事で、田中さんは疲弊しています。","Vì công việc dài, anh Tanaka đang kiệt sức."],["毎日残業して、疲弊しました。","Làm thêm giờ mỗi ngày, tôi đã kiệt sức."],["疲弊しないように、よく休みます。","Để không kiệt sức, tôi nghỉ ngơi nhiều."],["体が疲弊したので、早く寝ました。","Vì cơ thể kiệt sức nên tôi đã đi ngủ sớm."],["疲弊しているときは、無理をしてはいけません。","Khi kiệt sức thì không được cố quá sức."]]},{"word":"理想的（な）","reading":"りそうてき（な）","meaning":"lý tưởng","hanViet":"LÝ TƯỞNG ĐÍCH","lesson":15,"ex":[["この町は、住むのに理想的な場所です。","Thị trấn này là nơi lý tưởng để sống."],["理想的な生活をするために、努力します。","Để có cuộc sống lý tưởng, tôi sẽ nỗ lực."],["この天気は、散歩をするのに理想的です。","Thời tiết này rất lý tưởng để đi dạo."],["理想的な仕事を見つけました。","Tôi đã tìm được công việc lý tưởng."],["この部屋は、勉強するのに理想的です。","Căn phòng này rất lý tưởng để học tập."]]},{"word":"現象","reading":"げんしょう","meaning":"hiện tượng","hanViet":"HIỆN TƯỢNG","lesson":15,"ex":[["この現象は、よく知られています。","Hiện tượng này được biết đến rộng rãi."],["先生はその現象を説明しました。","Thầy giáo đã giải thích hiện tượng đó."],["不思議な現象を見ました。","Tôi đã thấy một hiện tượng kỳ lạ."],["この現象は、まだよくわかっていません。","Hiện tượng này vẫn chưa được hiểu rõ."],["現象を調べるのは、おもしろいです。","Tìm hiểu hiện tượng rất thú vị."]]},{"word":"参考資料","reading":"さんこうしりょう","meaning":"tài liệu tham khảo","hanViet":"THAM KHẢO TƯ LIỆU","lesson":15,"ex":[["参考資料を読んで、レポートを書きました。","Tôi đã đọc tài liệu tham khảo rồi viết báo cáo."],["先生は参考資料をくれました。","Thầy giáo đã cho tôi tài liệu tham khảo."],["参考資料がたくさんあります。","Có rất nhiều tài liệu tham khảo."],["この参考資料は、とても役に立ちます。","Tài liệu tham khảo này rất hữu ích."],["参考資料を集めるのに、時間がかかりました。","Việc thu thập tài liệu tham khảo đã tốn thời gian."]]},{"word":"プライベート（な）","reading":"","meaning":"riêng tư","hanViet":"","lesson":15,"ex":[["プライベートな時間は、大切です。","Thời gian riêng tư rất quan trọng."],["田中さんはプライベートなことをあまり話しません。","Anh Tanaka ít khi nói về chuyện riêng tư."],["プライベートな写真を見せてくれました。","Anh ấy đã cho tôi xem ảnh riêng tư."],["仕事とプライベートのバランスが大切です。","Cân bằng giữa công việc và đời tư rất quan trọng."],["プライベートな生活を守りたいです。","Tôi muốn bảo vệ cuộc sống riêng tư."]]},{"word":"示す（興味を～）","reading":"しめす（きょうみを～）","meaning":"bày tỏ (sự hứng thú)","hanViet":"THỊ HƯNG VỊ","lesson":15,"ex":[["田中さんは日本語に興味を示しました。","Anh Tanaka đã bày tỏ sự hứng thú với tiếng Nhật."],["彼女は音楽に興味を示しています。","Cô ấy đang bày tỏ sự hứng thú với âm nhạc."],["子どもたちは科学に興味を示しました。","Bọn trẻ đã bày tỏ sự hứng thú với khoa học."],["山田さんは新しい仕事に興味を示しました。","Anh Yamada đã bày tỏ sự hứng thú với công việc mới."],["学生たちは歴史に興味を示しています。","Các học sinh đang bày tỏ sự hứng thú với lịch sử."]]},{"word":"老舗","reading":"しにせ","meaning":"cửa hàng có từ lâu đời","hanViet":"LÃO PHỐ","lesson":15,"ex":[["この店は、とても古い老舗です。","Cửa hàng này là một cửa hàng rất lâu đời."],["京都には、有名な老舗がたくさんあります。","Ở Kyoto có rất nhiều cửa hàng lâu đời nổi tiếng."],["老舗の味は、昔から変わりません。","Hương vị của cửa hàng lâu đời không thay đổi từ xưa."],["その老舗は、家族で守っています。","Cửa hàng lâu đời đó được gia đình gìn giữ."],["老舗でお菓子を買いました。","Tôi đã mua bánh kẹo ở cửa hàng lâu đời."]]},{"word":"優れる","reading":"すぐれる","meaning":"giỏi, xuất sắc","hanViet":"ƯU","lesson":15,"ex":[["田中さんは英語に優れています。","Anh Tanaka giỏi tiếng Anh."],["彼女はスポーツに優れています。","Cô ấy giỏi thể thao."],["この製品は、前の製品に優れています。","Sản phẩm này vượt trội hơn sản phẩm trước."],["山田さんは歌に優れています。","Anh Yamada giỏi hát."],["彼は頭がよくて、スポーツにも優れています。","Anh ấy thông minh và còn giỏi thể thao."]]},{"word":"営業マン","reading":"えいぎょうマン","meaning":"nhân viên kinh doanh","hanViet":"DOANH NGHIỆP","lesson":15,"ex":[["田中さんは営業マンです。","Anh Tanaka là nhân viên kinh doanh."],["営業マンは毎日お客様に会います。","Nhân viên kinh doanh gặp khách hàng mỗi ngày."],["営業マンの仕事は、忙しいです。","Công việc của nhân viên kinh doanh rất bận rộn."],["山田さんは上手な営業マンです。","Anh Yamada là nhân viên kinh doanh giỏi."],["営業マンになって、三年が経ちました。","Từ khi trở thành nhân viên kinh doanh, ba năm đã trôi qua."]]},{"word":"太鼓","reading":"たいこ","meaning":"trống (Nhật Bản)","hanViet":"THÁI CỔ","lesson":15,"ex":[["祭りでは、太鼓の音が聞こえます。","Trong lễ hội, có thể nghe thấy tiếng trống."],["田中さんは太鼓を打つのが上手です。","Anh Tanaka rất giỏi đánh trống."],["太鼓の音は、とても大きいです。","Tiếng trống rất lớn."],["子どもたちは太鼓を打って、楽しみました。","Bọn trẻ đã đánh trống và rất vui."],["太鼓を習ってから、一年が経ちました。","Từ khi học trống, một năm đã trôi qua."]]},{"word":"腕（太鼓の～）","reading":"うで（たいこの～）","meaning":"kĩ năng (chơi trống)","hanViet":"OẢN THÁI CỔ","lesson":15,"ex":[["田中さんの太鼓の腕は、すばらしいです。","Kỹ năng chơi trống của anh Tanaka thật tuyệt vời."],["太鼓の腕を上げるために、毎日練習しています。","Để nâng cao kỹ năng chơi trống, tôi luyện tập mỗi ngày."],["彼の太鼓の腕は、先生にも知られています。","Kỹ năng chơi trống của anh ấy được cả thầy giáo biết đến."],["太鼓の腕が上がって、うれしいです。","Kỹ năng chơi trống đã tiến bộ nên tôi rất vui."],["山田さんの太鼓の腕は、みんなに知られています。","Kỹ năng chơi trống của anh Yamada được mọi người biết đến."]]},{"word":"地元","reading":"じもと","meaning":"địa phương, bản địa","hanViet":"ĐỊA NGUYÊN","lesson":15,"ex":[["地元の店で買い物をします。","Tôi mua sắm ở cửa hàng địa phương."],["田中さんは地元の人です。","Anh Tanaka là người địa phương."],["地元の人たちは、とても優しいです。","Người dân địa phương rất hiền lành."],["地元の祭りは、毎年大きく行われます。","Lễ hội địa phương được tổ chức lớn mỗi năm."],["地元の食べ物は、おいしいです。","Đồ ăn địa phương rất ngon."]]},{"word":"取引先","reading":"とりひきさき","meaning":"khách hàng, công ty giao dịch","hanViet":"THỦ DẪN TIÊN","lesson":15,"ex":[["田中さんは取引先に会いに行きました。","Anh Tanaka đã đi gặp khách hàng."],["取引先から電話がありました。","Có điện thoại từ khách hàng."],["新しい取引先が増えました。","Khách hàng mới đã tăng lên."],["取引先と会議をしました。","Tôi đã họp với khách hàng."],["取引先の会社は、大阪にあります。","Công ty khách hàng ở Osaka."]]},{"word":"絨毯","reading":"じゅうたん","meaning":"tấm thảm","hanViet":"NHUNG THẢM","lesson":15,"ex":[["部屋に新しい絨毯をしきました。","Tôi đã trải tấm thảm mới trong phòng."],["絨毯の上で、子どもが遊んでいます。","Đứa trẻ đang chơi trên tấm thảm."],["赤い絨毯を買いました。","Tôi đã mua tấm thảm đỏ."],["絨毯を掃除しました。","Tôi đã dọn dẹp tấm thảm."],["この絨毯は、とてもきれいです。","Tấm thảm này rất đẹp."]]},{"word":"出張所","reading":"しゅっちょうじょ","meaning":"văn phòng chi nhánh","hanViet":"XUẤT TRƯƠNG SỞ","lesson":15,"ex":[["田中さんは大阪の出張所で働いています。","Anh Tanaka đang làm việc ở văn phòng chi nhánh Osaka."],["新しい出張所ができました。","Văn phòng chi nhánh mới đã được mở."],["出張所の人は、十人です。","Số người ở văn phòng chi nhánh là mười người."],["出張所に電話をしました。","Tôi đã gọi điện đến văn phòng chi nhánh."],["京都の出張所に行ってきました。","Tôi đã đi đến văn phòng chi nhánh Kyoto rồi về."]]},{"word":"所長","reading":"しょちょう","meaning":"trưởng văn phòng","hanViet":"SỞ TRƯỞNG","lesson":15,"ex":[["田中さんは出張所の所長です。","Anh Tanaka là trưởng văn phòng chi nhánh."],["所長に会って、話をしました。","Tôi đã gặp trưởng văn phòng và nói chuyện."],["新しい所長が来ました。","Trưởng văn phòng mới đã đến."],["所長は毎日忙しいです。","Trưởng văn phòng ngày nào cũng bận rộn."],["所長の部屋は、大きいです。","Phòng của trưởng văn phòng rất lớn."]]},{"word":"社名","reading":"しゃめい","meaning":"tên công ty","hanViet":"XÃ DANH","lesson":15,"ex":[["この会社の社名は、何ですか。","Tên công ty này là gì?"],["社名を変えることにしました。","Chúng tôi đã quyết định đổi tên công ty."],["新しい社名は、覚えやすいです。","Tên công ty mới rất dễ nhớ."],["社名を見て、会社がわかりました。","Nhìn tên công ty, tôi đã biết đó là công ty nào."],["社名の意味を調べました。","Tôi đã tìm hiểu ý nghĩa của tên công ty."]]},{"word":"名","reading":"な","meaning":"tên","hanViet":"DANH","lesson":15,"ex":[["その店の名は、有名です。","Tên của cửa hàng đó rất nổi tiếng."],["田中さんの名は、会社でよく知られています。","Tên của anh Tanaka được biết đến rộng rãi trong công ty."],["名を聞いて、よくわかりました。","Nghe tên, tôi đã hiểu rõ."],["この本の名は、覚えやすいです。","Tên của cuốn sách này rất dễ nhớ."],["名を書いてください。","Xin hãy viết tên vào."]]},{"word":"織物","reading":"おりもの","meaning":"hàng dệt may","hanViet":"CHỨC VẬT","lesson":15,"ex":[["京都は織物で有名です。","Kyoto nổi tiếng về hàng dệt may."],["この織物は、手で作られました。","Hàng dệt may này được làm bằng tay."],["織物の店で、服を買いました。","Tôi đã mua quần áo ở cửa hàng dệt may."],["織物の色は、とてもきれいです。","Màu sắc của hàng dệt may rất đẹp."],["母は織物が好きです。","Mẹ tôi thích hàng dệt may."]]},{"word":"モダン（な）","reading":"","meaning":"hiện đại","hanViet":"","lesson":15,"ex":[["この建物はモダンなデザインです。","Tòa nhà này có thiết kế hiện đại."],["モダンな部屋に住みたいです。","Tôi muốn sống trong căn phòng hiện đại."],["その店はモダンで、きれいです。","Cửa hàng đó hiện đại và đẹp."],["モダンな服を買いました。","Tôi đã mua quần áo hiện đại."],["この町には、モダンな建物が多いです。","Thị trấn này có nhiều tòa nhà hiện đại."]]},{"word":"市場開拓","reading":"しじょうかいたく","meaning":"khai thác thị trường mới","hanViet":"THỊ TRƯỜNG KHAI THÁC","lesson":15,"ex":[["会社は市場開拓を始めました。","Công ty đã bắt đầu khai thác thị trường mới."],["市場開拓は、時間がかかります。","Khai thác thị trường mới tốn thời gian."],["田中さんは市場開拓の仕事をしています。","Anh Tanaka đang làm công việc khai thác thị trường mới."],["市場開拓のために、外国に行きました。","Để khai thác thị trường mới, tôi đã đi nước ngoài."],["市場開拓がうまくいきました。","Việc khai thác thị trường mới đã diễn ra tốt đẹp."]]},{"word":"開拓（する）","reading":"かいたく（する）","meaning":"khai thác","hanViet":"KHAI THÁC","lesson":15,"ex":[["新しい場所を開拓しました。","Chúng tôi đã khai thác nơi mới."],["会社は外国で新しい仕事を開拓しています。","Công ty đang khai thác công việc mới ở nước ngoài."],["田中さんは新しい道を開拓しました。","Anh Tanaka đã mở ra con đường mới."],["開拓する仕事は、大変です。","Công việc khai thác rất vất vả."],["新しい分野を開拓しました。","Chúng tôi đã khai thác lĩnh vực mới."]]},{"word":"きっての","reading":"","meaning":"tốt nhất, xuất sắc nhất","hanViet":"","lesson":15,"ex":[["彼は日本きっての歌手です。","Anh ấy là ca sĩ xuất sắc nhất Nhật Bản."],["この店は町できっての店です。","Cửa hàng này là cửa hàng xuất sắc nhất thị trấn."],["田中さんは会社できっての営業マンです。","Anh Tanaka là nhân viên kinh doanh xuất sắc nhất công ty."],["山田さんは町できっての医者です。","Anh Yamada là bác sĩ xuất sắc nhất thị trấn."],["この町は日本きっての観光地です。","Thị trấn này là địa điểm du lịch xuất sắc nhất Nhật Bản."]]},{"word":"何しろ","reading":"なにしろ","meaning":"dù sao thì / nói gì thì nói","hanViet":"HÀ","lesson":15,"ex":[["何しろ彼は忙しいので、会えませんでした。","Dù sao thì anh ấy cũng bận nên tôi không gặp được."],["何しろ初めてですから、少し心配です。","Dù sao thì đây cũng là lần đầu nên tôi hơi lo lắng."],["何しろ天気がいいので、出かけましょう。","Dù sao thì thời tiết cũng đẹp, chúng ta ra ngoài nhé."],["何しろ安いので、買うことにしました。","Dù sao thì cũng rẻ nên tôi đã quyết định mua."],["何しろ遠いので、電車で行きます。","Dù sao thì cũng xa nên tôi sẽ đi bằng tàu điện."]]},{"word":"知識","reading":"ちしき","meaning":"kiến thức","hanViet":"TRI THỨC","lesson":15,"ex":[["本を読むと、知識が増えます。","Đọc sách thì kiến thức tăng lên."],["先生はたくさんの知識を持っています。","Thầy giáo có rất nhiều kiến thức."],["知識を得るために、勉強しています。","Tôi học tập để có được kiến thức."],["この仕事には、特別な知識が必要です。","Công việc này cần kiến thức đặc biệt."],["知識があれば、難しい問題もわかります。","Nếu có kiến thức, cả bài toán khó cũng hiểu được."]]},{"word":"成果","reading":"せいか","meaning":"thành quả","hanViet":"THÀNH QUẢ","lesson":15,"ex":[["一年の勉強の成果が出ました。","Thành quả của một năm học tập đã xuất hiện."],["成果を出すために、努力しました。","Tôi đã nỗ lực để đạt được thành quả."],["この計画の成果は、大きいです。","Thành quả của kế hoạch này rất lớn."],["成果を見て、先生はうれしそうでした。","Nhìn thành quả, thầy giáo trông rất vui."],["毎日の勉強の成果が、だんだん出てきました。","Thành quả của việc học mỗi ngày dần dần đã xuất hiện."]]},{"word":"あげる（成果を～）","reading":"あげる（せいかを～）","meaning":"đạt được (thành quả)","hanViet":"THÀNH QUẢ","lesson":15,"ex":[["田中さんは大きな成果をあげました。","Anh Tanaka đã đạt được thành quả lớn."],["チームはいい成果をあげました。","Đội đã đạt được thành quả tốt."],["長い時間努力して、成果をあげました。","Nỗ lực trong thời gian dài, tôi đã đạt được thành quả."],["成果をあげるために、毎日練習しています。","Để đạt được thành quả, tôi luyện tập mỗi ngày."],["彼女は若いのに、大きな成果をあげています。","Cô ấy còn trẻ mà đã đạt được thành quả lớn."]]},{"word":"実","reading":"み","meaning":"trái, quả","hanViet":"THỰC","lesson":15,"ex":[["木に実がなりました。","Trên cây đã kết trái."],["秋になると、実がたくさんなります。","Khi mùa thu đến, cây kết rất nhiều trái."],["この実は、食べることができます。","Quả này có thể ăn được."],["実が赤くなりました。","Trái đã chín đỏ."],["子どもは赤い実を拾いました。","Đứa trẻ đã nhặt quả đỏ."]]},{"word":"結ぶ（実を～）","reading":"むすぶ（みを～）","meaning":"kết (trái)","hanViet":"KẾT THỰC","lesson":15,"ex":[["この木は毎年実を結びます。","Cây này kết trái mỗi năm."],["桜の木は実を結びますか。","Cây anh đào có kết trái không?"],["秋に、木はたくさんの実を結びます。","Vào mùa thu, cây kết rất nhiều trái."],["実を結ぶには、時間がかかります。","Để kết trái cần có thời gian."],["この木は今年も実を結びました。","Cây này năm nay cũng đã kết trái."]]},{"word":"魅する","reading":"みする","meaning":"thu hút, hấp dẫn","hanViet":"MỊ","lesson":15,"ex":[["その歌は、たくさんの人を魅しました。","Bài hát đó đã thu hút rất nhiều người."],["彼女の声は、人を魅します。","Giọng của cô ấy thu hút mọi người."],["京都の町は、人を魅します。","Thị trấn Kyoto thu hút mọi người."],["その映画は、たくさんの人を魅しました。","Bộ phim đó đã thu hút rất nhiều người."],["田中さんの話は、人を魅します。","Câu chuyện của anh Tanaka thu hút mọi người."]]},{"word":"磨く（腕を～）","reading":"みがく（うでを～）","meaning":"mài giũa (kĩ năng)","hanViet":"MA OẢN","lesson":15,"ex":[["田中さんは毎日腕を磨いています。","Anh Tanaka mài giũa kỹ năng mỗi ngày."],["腕を磨くために、毎日練習します。","Để mài giũa kỹ năng, tôi luyện tập mỗi ngày."],["若いときから、腕を磨いてきました。","Từ khi còn trẻ, tôi đã mài giũa kỹ năng."],["腕を磨いて、先生になりました。","Mài giũa kỹ năng, tôi đã trở thành thầy giáo."],["山田さんは太鼓の腕を磨いています。","Anh Yamada đang mài giũa kỹ năng chơi trống."]]},{"word":"～好き（太鼓～）","reading":"～ずき（たいこ～）","meaning":"người yêu thích (trống)","hanViet":"HẢO THÁI CỔ","lesson":15,"ex":[["田中さんは太鼓好きです。","Anh Tanaka là người yêu thích trống."],["太鼓好きの人が、たくさん集まりました。","Nhiều người yêu thích trống đã tụ họp."],["私は太鼓好きの友達が多いです。","Tôi có nhiều bạn yêu thích trống."],["太鼓好きな人と、よく練習します。","Tôi thường luyện tập với người yêu thích trống."],["山田さんは太鼓好きで、毎日太鼓を打ちます。","Anh Yamada yêu thích trống, ngày nào cũng đánh trống."]]},{"word":"得意","reading":"とくい","meaning":"giỏi","hanViet":"ĐẮC Ý","lesson":15,"ex":[["田中さんは英語が得意です。","Anh Tanaka giỏi tiếng Anh."],["私は料理が得意です。","Tôi giỏi nấu ăn."],["彼女はスポーツが得意です。","Cô ấy giỏi thể thao."],["得意なことを仕事にしたいです。","Tôi muốn biến điều mình giỏi thành công việc."],["山田さんは歌が得意です。","Anh Yamada giỏi hát."]]},{"word":"顔負け","reading":"かおまけ","meaning":"bị người khác vượt mặt, phải chào thua","hanViet":"NHAN PHỤ","lesson":15,"ex":[["彼女の料理は、母も顔負けです。","Món ăn của cô ấy khiến cả mẹ cũng phải chào thua."],["田中さんの歌は、歌手も顔負けです。","Giọng hát của anh Tanaka khiến cả ca sĩ cũng phải chào thua."],["その店の味は、有名な店も顔負けです。","Hương vị của cửa hàng đó khiến cả cửa hàng nổi tiếng cũng phải chào thua."],["彼の英語は、先生も顔負けです。","Tiếng Anh của anh ấy khiến cả thầy giáo cũng phải chào thua."],["山田さんの太鼓は、プロも顔負けです。","Tiếng trống của anh Yamada khiến cả nghệ sĩ chuyên nghiệp cũng phải chào thua."]]},{"word":"リズム","reading":"","meaning":"nhịp điệu","hanViet":"","lesson":15,"ex":[["この歌のリズムは、楽しいです。","Nhịp điệu của bài hát này rất vui."],["リズムに合わせて、踊ります。","Tôi nhảy theo nhịp điệu."],["太鼓のリズムが聞こえます。","Có thể nghe thấy nhịp điệu của trống."],["リズムが速くなりました。","Nhịp điệu đã nhanh lên."],["子どもはリズムに合わせて、手をたたきます。","Đứa trẻ vỗ tay theo nhịp điệu."]]},{"word":"～感（リズム～）","reading":"～かん","meaning":"cảm (nhịp) (cảm giác về nhịp điệu)","hanViet":"CẢM","lesson":15,"ex":[["田中さんはリズム感がいいです。","Anh Tanaka có cảm giác nhịp điệu tốt."],["彼女はリズム感がすばらしいです。","Cô ấy có cảm giác nhịp điệu tuyệt vời."],["リズム感をよくするために、毎日練習します。","Để cải thiện cảm giác nhịp điệu, tôi luyện tập mỗi ngày."],["山田さんのリズム感は、みんなに知られています。","Cảm giác nhịp điệu của anh Yamada được mọi người biết đến."],["子どものときから、リズム感がよかったです。","Từ khi còn nhỏ, tôi đã có cảm giác nhịp điệu tốt."]]},{"word":"甘える（お言葉に～）","reading":"あまえる（おことばに～）","meaning":"xin nhận (ý tốt)","hanViet":"CAM NGÔN DIỆP","lesson":15,"ex":[["「手伝いますよ」と言われたので、お言葉に甘えました。","Vì được nói \"Tôi giúp nhé\" nên tôi đã xin nhận ý tốt đó."],["お言葉に甘えて、お茶を飲みました。","Xin nhận ý tốt, tôi đã uống trà."],["田中さんのお言葉に甘えて、昼ごはんを食べました。","Xin nhận ý tốt của anh Tanaka, tôi đã ăn trưa."],["お言葉に甘えて、少し休ませてください。","Xin nhận ý tốt, cho tôi nghỉ một chút."],["「どうぞ」と言われたので、お言葉に甘えました。","Vì được nói \"Mời anh\" nên tôi đã xin nhận ý tốt."]]},{"word":"メンバー","reading":"","meaning":"thành viên","hanViet":"","lesson":15,"ex":[["私はサッカーチームのメンバーです。","Tôi là thành viên của đội bóng đá."],["新しいメンバーが二人入りました。","Hai thành viên mới đã gia nhập."],["メンバーはみんな元気です。","Mọi thành viên đều khỏe."],["メンバーの名前を覚えました。","Tôi đã nhớ tên các thành viên."],["メンバーといっしょにサッカーをしました。","Tôi đã chơi bóng đá cùng các thành viên."]]},{"word":"リーダー","reading":"","meaning":"người cầm đầu, người lãnh đạo","hanViet":"","lesson":15,"ex":[["田中さんはチームのリーダーです。","Anh Tanaka là trưởng nhóm."],["リーダーはみんなの話を聞きます。","Người lãnh đạo lắng nghe mọi người nói."],["山田さんは新しいリーダーになりました。","Yamada đã trở thành người lãnh đạo mới."],["リーダーはみんなを助けます。","Người lãnh đạo giúp đỡ mọi người."],["リーダーの話をよく聞きました。","Tôi đã lắng nghe kỹ lời người lãnh đạo."]]},{"word":"踊り","reading":"おどり","meaning":"điệu nhảy, điệu múa","hanViet":"DŨNG","lesson":15,"ex":[["あの踊りは美しいです。","Điệu nhảy đó rất đẹp."],["日本の踊りを習います。","Tôi học múa Nhật Bản."],["踊りを練習します。","Tôi luyện tập điệu nhảy."],["子どもたちは踊りが上手です。","Bọn trẻ nhảy rất giỏi."],["踊りを見て、うれしくなりました。","Xem điệu nhảy, tôi thấy vui."]]},{"word":"ブレイクダンス","reading":"","meaning":"nhảy đường phố \"break dance\"","hanViet":"","lesson":15,"ex":[["ブレイクダンスは人気があります。","Break dance rất được yêu thích."],["彼はブレイクダンスが上手です。","Anh ấy nhảy break dance rất giỏi."],["ブレイクダンスを習いたいです。","Tôi muốn học break dance."],["ブレイクダンスの練習を毎日します。","Tôi luyện break dance mỗi ngày."],["テレビでブレイクダンスを見ました。","Tôi đã xem break dance trên tivi."]]},{"word":"才能","reading":"さいのう","meaning":"tài năng","hanViet":"TÀI NĂNG","lesson":15,"ex":[["山田さんには歌の才能があります。","Yamada có tài năng ca hát."],["才能がある人はすごいです。","Người có tài năng thật tuyệt vời."],["才能を大切にしたいです。","Tôi muốn trân trọng tài năng."],["彼は絵の才能があります。","Anh ấy có tài năng vẽ."],["才能は練習してよくなります。","Tài năng sẽ tốt lên nhờ luyện tập."]]},{"word":"シェフ","reading":"","meaning":"đầu bếp","hanViet":"","lesson":15,"ex":[["田中さんは有名なシェフです。","Anh Tanaka là đầu bếp nổi tiếng."],["シェフの料理はすばらしいです。","Món ăn của đầu bếp thật tuyệt vời."],["私は将来シェフになりたいです。","Tôi muốn trở thành đầu bếp trong tương lai."],["シェフが新しい料理を作りました。","Đầu bếp đã làm món ăn mới."],["あのレストランのシェフは田中さんです。","Đầu bếp của nhà hàng đó là anh Tanaka."]]},{"word":"好意","reading":"こうい","meaning":"ý tốt","hanViet":"HẢO Ý","lesson":15,"ex":[["先生の好意に感謝します。","Tôi biết ơn ý tốt của thầy."],["好意で本をくれました。","Anh ấy tặng tôi sách vì ý tốt."],["彼の好意を忘れません。","Tôi sẽ không quên ý tốt của anh ấy."],["好意を受けて、うれしくなりました。","Nhận được ý tốt, tôi thấy vui."],["先生の好意がうれしいです。","Tôi vui vì ý tốt của thầy."]]},{"word":"ホームカミングデイ","reading":"","meaning":"ngày đón tiếp cựu sinh viên trở về trường cũ","hanViet":"","lesson":15,"ex":[["ホームカミングデイは来月です。","Ngày hội cựu sinh viên là tháng sau."],["ホームカミングデイに学校へ行きます。","Tôi đến trường vào ngày hội cựu sinh viên."],["ホームカミングデイで友達に会いました。","Tôi đã gặp bạn bè ở ngày hội cựu sinh viên."],["ホームカミングデイを楽しみにしています。","Tôi mong chờ ngày hội cựu sinh viên."],["ホームカミングデイで先生に会いました。","Tôi đã gặp thầy cô ở ngày hội cựu sinh viên."]]},{"word":"代々","reading":"だいだい","meaning":"các thế hệ","hanViet":"ĐẠI","lesson":15,"ex":[["この家は代々ここに住んでいます。","Gia đình này đã sống ở đây qua nhiều thế hệ."],["この歌は代々歌われています。","Bài hát này được hát qua nhiều thế hệ."],["代々大切にしています。","Chúng tôi gìn giữ cẩn thận qua nhiều thế hệ."],["代々の味を守ります。","Tôi bảo vệ hương vị truyền qua nhiều thế hệ."],["その家は代々医者です。","Gia đình đó làm bác sĩ qua nhiều thế hệ."]]},{"word":"実行委員","reading":"じっこういいん","meaning":"thành viên ban tổ chức","hanViet":"THỰC HÀNH ỦY VIÊN","lesson":15,"ex":[["私は実行委員になりました。","Tôi đã trở thành thành viên ban tổ chức."],["実行委員の仕事は忙しいです。","Công việc của ban tổ chức rất bận rộn."],["実行委員がイベントの準備をします。","Ban tổ chức chuẩn bị cho sự kiện."],["田中さんは実行委員のリーダーです。","Anh Tanaka là trưởng ban tổ chức."],["実行委員が二人います。","Ban tổ chức có hai người."]]},{"word":"進行（する）","reading":"しんこう（する）","meaning":"tiến hành","hanViet":"TIẾN HÀNH","lesson":15,"ex":[["会議が進行しています。","Cuộc họp đang diễn ra."],["計画が進行しています。","Kế hoạch đang được tiến hành."],["仕事の進行は速いです。","Công việc tiến hành nhanh."],["イベントが進行しています。","Sự kiện đang diễn ra."],["準備が進行しています。","Việc chuẩn bị đang được tiến hành."]]},{"word":"部下","reading":"ぶか","meaning":"cấp dưới","hanViet":"BỘ HẠ","lesson":15,"ex":[["田中さんは私の部下です。","Anh Tanaka là cấp dưới của tôi."],["部下の話をよく聞きます。","Tôi lắng nghe kỹ lời cấp dưới."],["部下を大切にします。","Tôi trân trọng cấp dưới."],["部下が二人います。","Tôi có hai cấp dưới."],["部下といっしょに仕事をします。","Tôi làm việc cùng cấp dưới."]]},{"word":"後輩","reading":"こうはい","meaning":"đàn em, hậu bối","hanViet":"HẬU BỐI","lesson":15,"ex":[["山田さんは私の後輩です。","Yamada là đàn em của tôi."],["後輩に日本語を教えます。","Tôi dạy tiếng Nhật cho đàn em."],["後輩は元気な学生です。","Đàn em là học sinh năng động."],["後輩といっしょに勉強します。","Tôi học cùng đàn em."],["後輩の話を聞きました。","Tôi đã nghe đàn em nói."]]},{"word":"LED 電球","reading":"エルイーディーでんきゅう","meaning":"đèn LED","hanViet":"ĐIỆN CẦU","lesson":15,"ex":[["LED電球は長く使えます。","Đèn LED dùng được lâu."],["家でLED電球を使います。","Tôi dùng đèn LED ở nhà."],["LED電球は明るいです。","Đèn LED rất sáng."],["LED電球を買いました。","Tôi đã mua đèn LED."],["LED電球は電気をあまり使いません。","Đèn LED không tốn nhiều điện."]]},{"word":"電球","reading":"でんきゅう","meaning":"bóng đèn tròn","hanViet":"ĐIỆN CẦU","lesson":15,"ex":[["電球を買いました。","Tôi đã mua bóng đèn."],["電球は明るいです。","Bóng đèn rất sáng."],["新しい電球を使います。","Tôi dùng bóng đèn mới."],["電球が二つあります。","Có hai bóng đèn."],["部屋の電球は白いです。","Bóng đèn trong phòng màu trắng."]]},{"word":"寿命","reading":"じゅみょう","meaning":"tuổi thọ","hanViet":"THỌ MỆNH","lesson":15,"ex":[["この電球は寿命が長いです。","Bóng đèn này có tuổi thọ dài."],["猫の寿命は長いです。","Tuổi thọ của mèo dài."],["健康な生活は寿命を長くします。","Cuộc sống khỏe mạnh làm tuổi thọ dài hơn."],["寿命は大切です。","Tuổi thọ rất quan trọng."],["この木の寿命はとても長いです。","Cây này có tuổi thọ rất dài."]]},{"word":"用いる","reading":"もちいる","meaning":"sử dụng","hanViet":"DỤNG","lesson":15,"ex":[["この本を用います。","Tôi sử dụng cuốn sách này."],["漢字を用いて書きます。","Tôi viết bằng chữ Hán."],["辞書を用います。","Tôi sử dụng từ điển."],["パソコンを用います。","Tôi sử dụng máy tính."],["英語を用いて話します。","Tôi nói bằng tiếng Anh."]]},{"word":"お嬢さん","reading":"おじょうさん","meaning":"con gái (của người khác)","hanViet":"NƯƠNG","lesson":15,"ex":[["お嬢さんは学生ですか。","Con gái của ông/bà có phải là học sinh không?"],["お嬢さんは元気ですか。","Con gái của ông/bà có khỏe không?"],["お嬢さんに会いました。","Tôi đã gặp con gái của ông/bà."],["お嬢さんはピアノが上手です。","Con gái của ông/bà chơi piano giỏi."],["お嬢さんは今どこにいますか。","Con gái của ông/bà bây giờ ở đâu?"]]},{"word":"転職（する）","reading":"てんしょく（する）","meaning":"thay đổi công việc","hanViet":"CHUYỂN CHỨC","lesson":15,"ex":[["転職を考えています。","Tôi đang nghĩ đến việc đổi việc."],["田中さんは転職しました。","Anh Tanaka đã đổi việc."],["転職したいです。","Tôi muốn đổi việc."],["転職は難しいです。","Đổi việc rất khó."],["来年、転職するつもりです。","Sang năm, tôi định đổi việc."]]},{"word":"環境問題","reading":"かんきょうもんだい","meaning":"vấn đề môi trường","hanViet":"HOÀN CẢNH VẤN ĐỀ","lesson":15,"ex":[["環境問題は大切な問題です。","Vấn đề môi trường là vấn đề quan trọng."],["環境問題について話します。","Tôi nói về vấn đề môi trường."],["環境問題を勉強します。","Tôi học về vấn đề môi trường."],["環境問題は世界の問題です。","Vấn đề môi trường là vấn đề của thế giới."],["環境問題を考えます。","Tôi suy nghĩ về vấn đề môi trường."]]},{"word":"経営（する）","reading":"けいえい（する）","meaning":"kinh doanh","hanViet":"KINH DOANH","lesson":15,"ex":[["田中さんは会社を経営しています。","Anh Tanaka đang quản lý công ty."],["経営は難しいです。","Kinh doanh rất khó."],["父は店を経営しています。","Bố tôi đang kinh doanh cửa hàng."],["経営を勉強します。","Tôi học về kinh doanh."],["小さい会社を経営します。","Tôi kinh doanh một công ty nhỏ."]]},{"word":"すべて","reading":"","meaning":"tất cả","hanViet":"","lesson":15,"ex":[["すべて終わりました。","Mọi việc đã xong."],["すべてわかりました。","Tôi đã hiểu tất cả."],["すべて食べました。","Tôi đã ăn hết tất cả."],["すべて新しいです。","Mọi thứ đều mới."],["すべて忘れました。","Tôi đã quên tất cả."]]},{"word":"各国","reading":"かっこく","meaning":"các quốc gia, các nước","hanViet":"CÁC QUỐC","lesson":15,"ex":[["各国の料理を食べました。","Tôi đã ăn món ăn của các nước."],["各国の人が日本に来ます。","Người từ các nước đến Nhật Bản."],["各国の音楽を聞きます。","Tôi nghe nhạc của các nước."],["各国の文化はおもしろいです。","Văn hóa các nước rất thú vị."],["各国の歴史を勉強します。","Tôi học lịch sử các nước."]]},{"word":"地球温暖化","reading":"ちきゅうおんだんか","meaning":"sự nóng lên của trái đất","hanViet":"ĐỊA CẦU ÔN NOÃN HÓA","lesson":15,"ex":[["地球温暖化は大きい問題です。","Sự nóng lên toàn cầu là vấn đề lớn."],["地球温暖化について勉強します。","Tôi học về sự nóng lên toàn cầu."],["地球温暖化で夏が暑くなりました。","Do sự nóng lên toàn cầu, mùa hè đã nóng hơn."],["地球温暖化を止めたいです。","Tôi muốn ngăn chặn sự nóng lên toàn cầu."],["地球温暖化について話しました。","Tôi đã nói về sự nóng lên toàn cầu."]]},{"word":"温暖化","reading":"おんだんか","meaning":"sự nóng lên","hanViet":"ÔN NOÃN HÓA","lesson":15,"ex":[["温暖化は問題です。","Sự nóng lên là vấn đề."],["温暖化について考えます。","Tôi suy nghĩ về sự nóng lên."],["温暖化で海が暖かくなります。","Do sự nóng lên, biển trở nên ấm hơn."],["温暖化の話を聞きました。","Tôi đã nghe câu chuyện về sự nóng lên."],["温暖化を止めるために、電気を大切に使います。","Để ngăn sự nóng lên, tôi dùng điện tiết kiệm."]]},{"word":"家族関係","reading":"かぞくかんけい","meaning":"mối quan hệ gia đình","hanViet":"GIA TỘC QUAN HỆ","lesson":15,"ex":[["家族関係は大切です。","Mối quan hệ gia đình rất quan trọng."],["家族関係がいいです。","Mối quan hệ gia đình tốt."],["家族関係について話します。","Tôi nói về mối quan hệ gia đình."],["家族関係を大切にします。","Tôi trân trọng mối quan hệ gia đình."],["家族関係はとても大切だと思います。","Tôi nghĩ mối quan hệ gia đình rất quan trọng."]]},{"word":"論文","reading":"ろんぶん","meaning":"luận văn","hanViet":"LUẬN VĂN","lesson":15,"ex":[["論文を書きます。","Tôi viết luận văn."],["論文は難しいです。","Luận văn rất khó."],["論文を読みました。","Tôi đã đọc luận văn."],["大学で論文を書きました。","Tôi đã viết luận văn ở đại học."],["論文の題名を決めました。","Tôi đã quyết định tiêu đề của luận văn."]]},{"word":"題名","reading":"だいめい","meaning":"tiêu đề","hanViet":"ĐỀ DANH","lesson":15,"ex":[["本の題名は何ですか。","Tiêu đề của cuốn sách là gì?"],["題名を決めました。","Tôi đã quyết định tiêu đề."],["いい題名ですね。","Tiêu đề hay nhỉ."],["論文の題名は長いです。","Tiêu đề của luận văn dài."],["題名を見て、本を買いました。","Nhìn tiêu đề, tôi đã mua cuốn sách."]]},{"word":"ベジタリアン","reading":"","meaning":"người ăn chay","hanViet":"","lesson":15,"ex":[["山田さんはベジタリアンです。","Yamada là người ăn chay."],["ベジタリアンは肉を食べません。","Người ăn chay không ăn thịt."],["ベジタリアンの料理を作ります。","Tôi làm món ăn chay."],["ベジタリアンの友達がいます。","Tôi có bạn là người ăn chay."],["ベジタリアンになって、野菜をよく食べます。","Trở thành người ăn chay, tôi ăn nhiều rau."]]},{"word":"選挙（する）","reading":"せんきょ（する）","meaning":"tuyển cử, bầu cử","hanViet":"TUYỂN CỬ","lesson":15,"ex":[["選挙があります。","Có cuộc bầu cử."],["選挙に行きました。","Tôi đã đi bầu cử."],["選挙で投票をしました。","Tôi đã bỏ phiếu trong cuộc bầu cử."],["選挙は来月です。","Bầu cử là tháng sau."],["選挙について話しました。","Tôi đã nói về bầu cử."]]},{"word":"出る（選挙に～）","reading":"でる（せんきょに～）","meaning":"tham gia (tuyển cử), ứng cử","hanViet":"XUẤT TUYỂN CỬ","lesson":15,"ex":[["田中さんは選挙に出ます。","Anh Tanaka ứng cử."],["選挙に出るつもりです。","Tôi định ứng cử."],["選挙に出ました。","Tôi đã ứng cử."],["先生が選挙に出ます。","Thầy giáo ứng cử."],["選挙に出る人が多いです。","Có nhiều người ứng cử."]]},{"word":"混乱（する）","reading":"こんらん（する）","meaning":"hỗn loạn, rối ren","hanViet":"HỖN LOẠN","lesson":15,"ex":[["駅が混乱しました。","Nhà ga đã hỗn loạn."],["雨で駅が混乱しました。","Do mưa, nhà ga đã hỗn loạn."],["会議が混乱しました。","Cuộc họp đã hỗn loạn."],["混乱しないように、ゆっくり話します。","Để không hỗn loạn, tôi nói chậm."],["混乱は早く終わりました。","Sự hỗn loạn đã kết thúc sớm."]]},{"word":"調整（する）","reading":"ちょうせい（する）","meaning":"sắp xếp, điều chỉnh","hanViet":"ĐIỀU CHỈNH","lesson":15,"ex":[["時間を調整します。","Tôi điều chỉnh thời gian."],["会議の時間を調整しました。","Tôi đã điều chỉnh thời gian họp."],["予定を調整します。","Tôi điều chỉnh lịch trình."],["仕事の時間を調整します。","Tôi điều chỉnh thời gian làm việc."],["調整が終わりました。","Việc điều chỉnh đã xong."]]},{"word":"当番","reading":"とうばん","meaning":"phiên làm việc","hanViet":"ĐƯƠNG PHIÊN","lesson":15,"ex":[["きょうは私が当番です。","Hôm nay tôi trực."],["当番の仕事をします。","Tôi làm công việc trực."],["あしたは田中さんが当番です。","Ngày mai anh Tanaka trực."],["当番を交代しました。","Tôi đã đổi phiên trực."],["当番の日に早く来ます。","Vào ngày trực, tôi đến sớm."]]},{"word":"交代（する）","reading":"こうたい（する）","meaning":"thay thế, thay phiên","hanViet":"GIAO ĐẠI","lesson":15,"ex":[["当番を交代します。","Tôi đổi phiên trực."],["仕事を交代しました。","Tôi đã đổi ca làm việc."],["仕事を交代して、休みます。","Tôi đổi ca làm việc rồi nghỉ ngơi."],["交代の時間です。","Đã đến giờ đổi ca."],["友達と交代しました。","Tôi đã đổi phiên với bạn."]]},{"word":"ピアニスト","reading":"","meaning":"nghệ sĩ piano","hanViet":"","lesson":15,"ex":[["山田さんはピアニストです。","Yamada là nghệ sĩ piano."],["ピアニストの演奏を聞きました。","Tôi đã nghe nghệ sĩ piano biểu diễn."],["有名なピアニストが来ます。","Nghệ sĩ piano nổi tiếng sẽ đến."],["ピアニストになりたいです。","Tôi muốn trở thành nghệ sĩ piano."],["ピアニストは練習を毎日します。","Nghệ sĩ piano luyện tập mỗi ngày."]]},{"word":"楽器","reading":"がっき","meaning":"nhạc cụ","hanViet":"NHẠC KHÍ","lesson":15,"ex":[["楽器を習います。","Tôi học nhạc cụ."],["ピアノは楽器です。","Piano là nhạc cụ."],["楽器の音が好きです。","Tôi thích âm thanh của nhạc cụ."],["楽器を買いました。","Tôi đã mua nhạc cụ."],["楽器を練習します。","Tôi luyện tập nhạc cụ."]]},{"word":"一家（音楽～）","reading":"いっか（おんがく～）","meaning":"gia đình (âm nhạc)","hanViet":"NHẤT GIA ÂM NHẠC","lesson":15,"ex":[["山田さんの家は音楽一家です。","Gia đình Yamada là gia đình âm nhạc."],["私の家は音楽一家です。","Gia đình tôi là gia đình âm nhạc."],["音楽一家の子どもはピアノが上手です。","Con của gia đình âm nhạc chơi piano giỏi."],["音楽一家の歌はすばらしいです。","Bài hát của gia đình âm nhạc rất tuyệt."],["音楽一家の話を聞きました。","Tôi đã nghe câu chuyện về gia đình âm nhạc."]]},{"word":"秘密","reading":"ひみつ","meaning":"bí mật","hanViet":"BÍ MẬT","lesson":15,"ex":[["秘密を教えてください。","Hãy nói cho tôi biết bí mật."],["秘密は言えません。","Tôi không thể nói bí mật."],["秘密を守ります。","Tôi giữ bí mật."],["これは秘密です。","Đây là bí mật."],["秘密の話を聞きました。","Tôi đã nghe câu chuyện bí mật."]]},{"word":"帰国生徒","reading":"きこくせいと","meaning":"những học sinh trở về Nhật sau quá trình sống và học tập ở nước ngoài","hanViet":"QUY QUỐC SINH ĐỒ","lesson":15,"ex":[["帰国生徒が学校にいます。","Có học sinh hồi hương ở trường."],["帰国生徒は英語が上手です。","Học sinh hồi hương giỏi tiếng Anh."],["帰国生徒の話を聞きました。","Tôi đã nghe câu chuyện của học sinh hồi hương."],["帰国生徒と友達になりました。","Tôi đã kết bạn với học sinh hồi hương."],["帰国生徒は日本語を勉強しています。","Học sinh hồi hương đang học tiếng Nhật."]]},{"word":"器用（な）","reading":"きよう（な）","meaning":"khéo léo","hanViet":"KHÍ DỤNG","lesson":15,"ex":[["山田さんは器用な人です。","Yamada là người khéo léo."],["器用な手です。","Bàn tay khéo léo."],["器用に料理を作ります。","Tôi nấu ăn khéo léo."],["彼は器用です。","Anh ấy khéo léo."],["器用な子どもです。","Đó là đứa trẻ khéo léo."]]},{"word":"かく（汗を～）","reading":"かく（あせを～）","meaning":"đổ (mồ hôi)","hanViet":"HÃN","lesson":15,"ex":[["汗をかきました。","Tôi đã đổ mồ hôi."],["夏は汗をかきます。","Mùa hè tôi đổ mồ hôi."],["運動して汗をかきました。","Tôi vận động và đã đổ mồ hôi."],["汗をかいたので、水を飲みました。","Vì đổ mồ hôi, tôi đã uống nước."],["走って汗をかきました。","Tôi chạy và đã đổ mồ hôi."]]},{"word":"注文（する）","reading":"ちゅうもん（する）","meaning":"đặt, gọi","hanViet":"CHÚ VĂN","lesson":15,"ex":[["料理を注文します。","Tôi gọi món ăn."],["コーヒーを注文しました。","Tôi đã gọi cà phê."],["注文をお願いします。","Tôi muốn gọi món."],["レストランで注文します。","Tôi gọi món ở nhà hàng."],["注文した料理が来ました。","Món ăn đã gọi đã đến."]]},{"word":"マナー","reading":"","meaning":"cách cư xử, phép tắc","hanViet":"","lesson":15,"ex":[["マナーを守ります。","Tôi tuân thủ phép tắc."],["日本のマナーを勉強します。","Tôi học phép tắc của Nhật Bản."],["学校のマナーは大切です。","Phép tắc ở trường học rất quan trọng."],["マナーがいい人です。","Đó là người có phép tắc tốt."],["電車のマナーを守ります。","Tôi tuân thủ phép tắc trên tàu điện."]]},{"word":"国民栄誉賞","reading":"こくみんえいよしょう","meaning":"giải thưởng danh dự nhân dân","hanViet":"QUỐC DÂN VINH DỰ THƯỞNG","lesson":15,"ex":[["国民栄誉賞は有名です。","Giải thưởng danh dự nhân dân rất nổi tiếng."],["国民栄誉賞をもらいました。","Tôi đã nhận giải thưởng danh dự nhân dân."],["国民栄誉賞の話を聞きました。","Tôi đã nghe câu chuyện về giải thưởng danh dự nhân dân."],["国民栄誉賞はすばらしいです。","Giải thưởng danh dự nhân dân thật tuyệt vời."],["国民栄誉賞をもらう人はすごいです。","Người nhận giải thưởng danh dự nhân dân thật tuyệt vời."]]},{"word":"栄誉","reading":"えいよ","meaning":"vinh dự","hanViet":"VINH DỰ","lesson":15,"ex":[["栄誉ある人です。","Đó là người vinh dự."],["栄誉なことです。","Đó là việc vinh dự."],["栄誉を受けました。","Tôi đã nhận vinh dự."],["栄誉を受けて、うれしいです。","Tôi vui vì nhận được vinh dự."],["栄誉ある仕事です。","Đó là công việc vinh dự."]]},{"word":"信頼（する）","reading":"しんらい（する）","meaning":"tin tưởng, tin cậy","hanViet":"TÍN LẠI","lesson":15,"ex":[["友達を信頼します。","Tôi tin tưởng bạn bè."],["信頼できる人です。","Đó là người đáng tin cậy."],["先生を信頼しています。","Tôi tin tưởng thầy giáo."],["信頼が大切です。","Sự tin tưởng rất quan trọng."],["会社を信頼します。","Tôi tin tưởng công ty."]]},{"word":"思い浮かべる","reading":"おもいうかべる","meaning":"liên tưởng đến","hanViet":"TƯ PHÙ","lesson":15,"ex":[["写真を見ると、子どものときを思い浮かべます。","Nhìn ảnh, tôi nhớ lại lúc còn nhỏ."],["歌を聞くと、海を思い浮かべます。","Nghe bài hát, tôi hình dung ra biển."],["彼の声を思い浮かべます。","Tôi nhớ lại giọng nói của anh ấy."],["学校の友達を思い浮かべます。","Tôi nhớ lại bạn bè ở trường."],["日本の山を思い浮かべます。","Tôi hình dung những ngọn núi của Nhật Bản."]]},{"word":"中年","reading":"ちゅうねん","meaning":"trung niên","hanViet":"TRUNG NIÊN","lesson":15,"ex":[["中年の人が多いです。","Có nhiều người trung niên."],["中年の男性です。","Đó là người đàn ông trung niên."],["中年になっても、元気です。","Dù đến tuổi trung niên, tôi vẫn khỏe."],["中年の女性が歌います。","Người phụ nữ trung niên hát."],["中年の人は仕事が忙しいです。","Người trung niên bận rộn với công việc."]]},{"word":"提供（する）","reading":"ていきょう（する）","meaning":"đưa ra, cung cấp","hanViet":"ĐỂ CUNG","lesson":15,"ex":[["会社はサービスを提供します。","Công ty cung cấp dịch vụ."],["情報を提供します。","Tôi cung cấp thông tin."],["食べ物を提供します。","Tôi cung cấp thức ăn."],["学校は場所を提供します。","Trường học cung cấp địa điểm."],["毎日、新しい情報を提供します。","Mỗi ngày, tôi cung cấp thông tin mới."]]},{"word":"展開（する）","reading":"てんかい（する）","meaning":"triển khai","hanViet":"TRIỂN KHAI","lesson":15,"ex":[["会社は店を展開します。","Công ty triển khai cửa hàng."],["新しい仕事を展開します。","Tôi triển khai công việc mới."],["事業を展開しています。","Tôi đang triển khai kinh doanh."],["活動を展開します。","Tôi triển khai hoạt động."],["店を東京に展開します。","Tôi triển khai cửa hàng ở Tokyo."]]},{"word":"走り回る","reading":"はしりまわる","meaning":"chạy quanh","hanViet":"TẨU HỒI","lesson":15,"ex":[["子どもが走り回ります。","Đứa trẻ chạy quanh."],["犬が公園で走り回ります。","Con chó chạy quanh ở công viên."],["子どもたちは走り回って遊びます。","Bọn trẻ chạy quanh chơi đùa."],["猫が部屋で走り回りました。","Con mèo đã chạy quanh trong phòng."],["走り回って、汗をかきました。","Tôi chạy quanh nên đã đổ mồ hôi."]]},{"word":"こうして","reading":"","meaning":"như thế này","hanViet":"","lesson":15,"ex":[["こうして仕事をします。","Tôi làm việc như thế này."],["こうして毎日勉強します。","Tôi học như thế này mỗi ngày."],["こうして日本語を覚えました。","Tôi đã nhớ tiếng Nhật như thế này."],["こうして友達になりました。","Chúng tôi đã trở thành bạn bè như thế này."],["こうして料理を作ります。","Tôi nấu ăn như thế này."]]},{"word":"あっという間","reading":"あっというま","meaning":"trong nháy mắt, loáng một cái","hanViet":"GIAN","lesson":15,"ex":[["あっという間に時間が過ぎました。","Thời gian đã trôi qua trong nháy mắt."],["あっという間に夏が終わりました。","Mùa hè đã kết thúc trong nháy mắt."],["あっという間に映画が終わりました。","Bộ phim đã kết thúc trong nháy mắt."],["あっという間に休みが終わりました。","Kỳ nghỉ đã kết thúc trong nháy mắt."],["あっという間に子どもが大きくなりました。","Đứa trẻ đã lớn lên trong nháy mắt."]]},{"word":"支社","reading":"ししゃ","meaning":"chi nhánh","hanViet":"CHI XÃ","lesson":15,"ex":[["支社が大阪にあります。","Chi nhánh ở Osaka."],["支社で働きます。","Tôi làm việc ở chi nhánh."],["支社は東京にあります。","Chi nhánh ở Tokyo."],["支社の仕事は忙しいです。","Công việc ở chi nhánh bận rộn."],["支社に行きました。","Tôi đã đến chi nhánh."]]},{"word":"しみじみ","reading":"","meaning":"sâu sắc","hanViet":"","lesson":15,"ex":[["しみじみ思います。","Tôi nghĩ một cách sâu sắc."],["歌をしみじみ聞きます。","Tôi nghe bài hát một cách sâu sắc."],["しみじみ話します。","Tôi nói chuyện một cách sâu sắc."],["しみじみと日本の歌を聞きました。","Tôi đã nghe bài hát Nhật Bản một cách sâu sắc."],["しみじみ考えます。","Tôi suy nghĩ một cách sâu sắc."]]},{"word":"でかい","reading":"","meaning":"to, lớn","hanViet":"","lesson":15,"ex":[["でかい犬です。","Đó là con chó to."],["でかい家に住んでいます。","Tôi sống trong ngôi nhà to."],["でかい魚を見ました。","Tôi đã thấy con cá to."],["でかい声で話します。","Tôi nói bằng giọng to."],["でかい山が見えます。","Tôi thấy ngọn núi to."]]},{"word":"つながり（人と人との～）","reading":"つながり（ひととひととの～）","meaning":"sự kết nối (giữa người với người)","hanViet":"NHÂN NHÂN","lesson":15,"ex":[["人と人とのつながりは大切です。","Sự kết nối giữa người với người rất quan trọng."],["人と人とのつながりを大切にします。","Tôi trân trọng sự kết nối giữa người với người."],["人と人とのつながりはすばらしいです。","Sự kết nối giữa người với người thật tuyệt vời."],["人と人とのつながりを強くします。","Tôi làm sự kết nối giữa người với người mạnh mẽ hơn."],["人と人とのつながりで、仕事が楽しくなります。","Nhờ sự kết nối giữa người với người, công việc trở nên vui vẻ."]]},{"word":"金儲け","reading":"かねもうけ","meaning":"kiếm tiền","hanViet":"KIM","lesson":15,"ex":[["金儲けは悪いことではありません。","Kiếm tiền không phải là việc xấu."],["金儲けを考えます。","Tôi nghĩ về việc kiếm tiền."],["金儲けのために働きます。","Tôi làm việc để kiếm tiền."],["金儲けが上手な人です。","Đó là người giỏi kiếm tiền."],["金儲けだけを考えません。","Tôi không chỉ nghĩ đến việc kiếm tiền."]]},{"word":"緊急","reading":"きんきゅう","meaning":"khẩn cấp","hanViet":"KHẨN CẤP","lesson":15,"ex":[["緊急の電話です。","Đây là cuộc gọi khẩn cấp."],["緊急のとき、電話してください。","Trong trường hợp khẩn cấp, hãy gọi điện."],["緊急の仕事があります。","Có công việc khẩn cấp."],["緊急に病院へ行きました。","Tôi đã đến bệnh viện khẩn cấp."],["緊急に連絡しました。","Tôi đã liên lạc khẩn cấp."]]},{"word":"共生（する）","reading":"きょうせい（する）","meaning":"cộng sinh, sống chung","hanViet":"CỘNG SINH","lesson":15,"ex":[["人と自然が共生します。","Con người và thiên nhiên cùng sống."],["動物と共生します。","Tôi sống chung với động vật."],["共生は大切です。","Sống chung rất quan trọng."],["人と動物が共生する社会です。","Đó là xã hội con người và động vật cùng sống."],["共生について考えます。","Tôi suy nghĩ về sự cộng sinh."]]},{"word":"耳にする","reading":"みみにする","meaning":"nghe thấy","hanViet":"NHĨ","lesson":15,"ex":[["ニュースを耳にしました。","Tôi đã nghe tin tức."],["いい話を耳にしました。","Tôi đã nghe câu chuyện hay."],["歌を耳にしました。","Tôi đã nghe bài hát."],["町の話を耳にします。","Tôi nghe chuyện của thành phố."],["新しい歌を耳にしました。","Tôi đã nghe bài hát mới."]]},{"word":"共に","reading":"ともに","meaning":"cùng với","hanViet":"CỘNG","lesson":15,"ex":[["友達と共に勉強します。","Tôi học cùng với bạn bè."],["家族と共に住みます。","Tôi sống cùng với gia đình."],["先生と共に働きます。","Tôi làm việc cùng với thầy giáo."],["共に歌います。","Chúng ta cùng hát."],["共に頑張ります。","Chúng ta cùng cố gắng."]]},{"word":"利益","reading":"りえき","meaning":"lợi ích","hanViet":"LỢI ÍCH","lesson":15,"ex":[["利益が大きいです。","Lợi nhuận lớn."],["利益を大切にします。","Tôi trân trọng lợi ích."],["会社の利益は大切です。","Lợi nhuận của công ty rất quan trọng."],["利益のために働きます。","Tôi làm việc vì lợi nhuận."],["利益が出ました。","Đã có lợi nhuận."]]},{"word":"分かち合う","reading":"わかちあう","meaning":"chia sẻ","hanViet":"PHÂN HỢP","lesson":15,"ex":[["食べ物を分かち合います。","Tôi chia sẻ thức ăn."],["友達と悲しみを分かち合います。","Tôi chia sẻ nỗi buồn với bạn bè."],["経験を分かち合います。","Tôi chia sẻ kinh nghiệm."],["友達と分かち合います。","Tôi chia sẻ với bạn bè."],["楽しい時間を分かち合います。","Tôi chia sẻ thời gian vui vẻ."]]},{"word":"ヤドカリ","reading":"","meaning":"cua ẩn sĩ, ốc mượn hồn (chỉ loài tôm, cua ở nhờ)","hanViet":"","lesson":15,"ex":[["ヤドカリは海にいます。","Ốc mượn hồn sống ở biển."],["ヤドカリは小さい家に住みます。","Ốc mượn hồn sống trong ngôi nhà nhỏ."],["ヤドカリを見ました。","Tôi đã thấy ốc mượn hồn."],["ヤドカリはおもしろい動物です。","Ốc mượn hồn là động vật thú vị."],["水族館でヤドカリを見ました。","Tôi đã thấy ốc mượn hồn ở thủy cung."]]},{"word":"イソギンチャク","reading":"","meaning":"hải quỳ","hanViet":"","lesson":15,"ex":[["イソギンチャクは海にいます。","Hải quỳ sống ở biển."],["イソギンチャクは花のようです。","Hải quỳ giống như hoa."],["水族館でイソギンチャクを見ました。","Tôi đã thấy hải quỳ ở thủy cung."],["イソギンチャクはきれいです。","Hải quỳ rất đẹp."],["イソギンチャクと魚がいっしょにいます。","Hải quỳ và cá ở cùng nhau."]]},{"word":"用語","reading":"ようご","meaning":"thuật ngữ, từ chuyên môn","hanViet":"DỤNG NGỮ","lesson":15,"ex":[["用語を覚えます。","Tôi nhớ thuật ngữ."],["難しい用語です。","Đó là thuật ngữ khó."],["用語の意味がわかりません。","Tôi không hiểu nghĩa của thuật ngữ."],["専門の用語を勉強します。","Tôi học thuật ngữ chuyên môn."],["用語を辞書で見ます。","Tôi xem thuật ngữ trong từ điển."]]},{"word":"社会科学","reading":"しゃかいかがく","meaning":"khoa học xã hội","hanViet":"XÃ HỘI KHOA HỌC","lesson":15,"ex":[["社会科学を勉強します。","Tôi học khoa học xã hội."],["社会科学はおもしろいです。","Khoa học xã hội rất thú vị."],["大学で社会科学を習います。","Tôi học khoa học xã hội ở đại học."],["社会科学の本を読みました。","Tôi đã đọc sách về khoa học xã hội."],["社会科学の先生です。","Đó là thầy giáo khoa học xã hội."]]},{"word":"分野","reading":"ぶんや","meaning":"lĩnh vực","hanViet":"PHÂN DÃ","lesson":15,"ex":[["新しい分野を勉強します。","Tôi học lĩnh vực mới."],["この分野はおもしろいです。","Lĩnh vực này rất thú vị."],["自分の分野を大切にします。","Tôi trân trọng lĩnh vực của mình."],["分野を決めました。","Tôi đã quyết định lĩnh vực."],["経済の分野で働きます。","Tôi làm việc trong lĩnh vực kinh tế."]]},{"word":"込める（意味を～）","reading":"こめる（いみを～）","meaning":"chứa đựng, gửi gắm (nghĩa)","hanViet":"Ý VỊ","lesson":15,"ex":[["意味を込めて、歌います。","Tôi hát gửi gắm ý nghĩa."],["歌に意味を込めます。","Tôi gửi gắm ý nghĩa vào bài hát."],["意味を込めた歌です。","Đó là bài hát gửi gắm ý nghĩa."],["意味を込めて書きます。","Tôi viết gửi gắm ý nghĩa."],["名前に意味を込めました。","Tôi đã gửi gắm ý nghĩa vào tên."]]},{"word":"乗り越える","reading":"のりこえる","meaning":"vượt qua","hanViet":"THỪA VIỆT","lesson":15,"ex":[["困難を乗り越えます。","Tôi vượt qua khó khăn."],["問題を乗り越えました。","Tôi đã vượt qua vấn đề."],["壁を乗り越えます。","Tôi vượt qua bức tường."],["困難を乗り越えて、強くなりました。","Vượt qua khó khăn, tôi đã mạnh mẽ hơn."],["問題を乗り越えることができました。","Tôi đã có thể vượt qua vấn đề."]]},{"word":"怠け者","reading":"なまけもの","meaning":"kẻ lười biếng","hanViet":"ĐÃI GIẢ","lesson":15,"ex":[["怠け者は宿題をしません。","Kẻ lười biếng không làm bài tập."],["怠け者になりたくありません。","Tôi không muốn trở thành kẻ lười biếng."],["怠け者は仕事をしません。","Kẻ lười biếng không làm việc."],["怠け者だと言われました。","Tôi bị nói là kẻ lười biếng."],["怠け者は早く起きません。","Kẻ lười biếng không dậy sớm."]]},{"word":"真面目（な）","reading":"まじめ（な）","meaning":"nghiêm túc, chăm chỉ","hanViet":"CHÂN DIỆN MỤC","lesson":15,"ex":[["山田さんは真面目な学生です。","Yamada là học sinh nghiêm túc."],["真面目に勉強します。","Tôi học nghiêm túc."],["真面目な人です。","Đó là người nghiêm túc."],["真面目に仕事をします。","Tôi làm việc nghiêm túc."],["真面目に話します。","Tôi nói nghiêm túc."]]},{"word":"ナマケモノ","reading":"","meaning":"con lười","hanViet":"","lesson":15,"ex":[["ナマケモノは木に住みます。","Con lười sống trên cây."],["ナマケモノは遅い動物です。","Con lười là động vật chậm."],["動物園でナマケモノを見ました。","Tôi đã thấy con lười ở sở thú."],["ナマケモノはおもしろい動物です。","Con lười là động vật thú vị."],["ナマケモノは木にぶら下がります。","Con lười treo mình trên cây."]]},{"word":"ぶら下がる","reading":"ぶらさがる","meaning":"treo lòng thòng, rủ xuống, đu xuống","hanViet":"HẠ","lesson":15,"ex":[["猫が木にぶら下がります。","Con mèo treo mình trên cây."],["子どもが木にぶら下がります。","Đứa trẻ treo mình trên cây."],["ナマケモノが木にぶら下がります。","Con lười treo mình trên cây."],["木の枝にぶら下がります。","Tôi đu trên cành cây."],["ぶら下がって遊びます。","Tôi đu chơi."]]},{"word":"移動（する）","reading":"いどう（する）","meaning":"di chuyển","hanViet":"DI ĐỘNG","lesson":15,"ex":[["移動します。","Tôi di chuyển."],["会社が移動しました。","Công ty đã chuyển đi."],["移動の時間です。","Đã đến giờ di chuyển."],["東京へ移動します。","Tôi di chuyển đến Tokyo."],["移動は楽しいです。","Di chuyển rất vui."]]},{"word":"エネルギー","reading":"","meaning":"năng lượng","hanViet":"","lesson":15,"ex":[["エネルギーを大切にします。","Tôi trân trọng năng lượng."],["太陽のエネルギーを使います。","Tôi dùng năng lượng mặt trời."],["エネルギーをたくさん使います。","Tôi dùng nhiều năng lượng."],["エネルギーの問題を考えます。","Tôi suy nghĩ về vấn đề năng lượng."],["エネルギーを作ります。","Tôi tạo ra năng lượng."]]},{"word":"ちょうど","reading":"","meaning":"vừa đúng","hanViet":"","lesson":15,"ex":[["ちょうど一時です。","Vừa đúng một giờ."],["ちょうど今、来ました。","Tôi vừa đến ngay bây giờ."],["ちょうどいいです。","Vừa vặn."],["ちょうど二人です。","Vừa đúng hai người."],["ちょうどいい時間です。","Đúng lúc."]]},{"word":"賢い","reading":"かしこい","meaning":"thông minh, nhanh nhạy","hanViet":"HIỀN","lesson":15,"ex":[["賢い子どもです。","Đó là đứa trẻ thông minh."],["賢い犬です。","Đó là con chó thông minh."],["賢い人ですね。","Đó là người thông minh nhỉ."],["賢い猫です。","Đó là con mèo thông minh."],["賢い学生はよく勉強します。","Học sinh thông minh học chăm."]]},{"word":"個人情報","reading":"こじんじょうほう","meaning":"thông tin cá nhân","hanViet":"CÁ NHÂN TÌNH BÁO","lesson":16,"ex":[["個人情報は大切に管理しなければなりません。","Thông tin cá nhân phải được quản lý cẩn thận."],["このサイトで個人情報を書かないでください。","Trên trang web này, xin đừng viết thông tin cá nhân."],["個人情報が漏れると、大きな問題になります。","Nếu thông tin cá nhân bị rò rỉ, sẽ thành vấn đề lớn."],["会社は社員の個人情報をしっかり守っています。","Công ty đang bảo vệ chắc chắn thông tin cá nhân của nhân viên."],["個人情報を教える前に、その人をよく確認してください。","Trước khi cho biết thông tin cá nhân, hãy xác nhận kỹ người đó."]]},{"word":"流出（する）","reading":"りゅうしゅつ（する）","meaning":"rò rỉ, lộ ra","hanViet":"LƯU XUẤT","lesson":16,"ex":[["会社の情報が外に流出しました。","Thông tin của công ty đã bị rò rỉ ra ngoài."],["個人情報の流出を防ぐことが大切です。","Ngăn chặn việc rò rỉ thông tin cá nhân là quan trọng."],["流出した情報は、もう戻りません。","Thông tin đã rò rỉ thì không quay lại được nữa."],["新聞は情報の流出について大きく伝えました。","Báo chí đã đưa tin lớn về việc rò rỉ thông tin."],["この会社では情報が流出しないように気をつけています。","Công ty này đang cẩn thận để thông tin không bị rò rỉ."]]},{"word":"新聞記事","reading":"しんぶんきじ","meaning":"bài báo","hanViet":"TÂN VĂN KÝ SỰ","lesson":16,"ex":[["きょうの新聞記事を読みましたか。","Hôm nay bạn đã đọc bài báo chưa?"],["この新聞記事は短いです。","Bài báo này ngắn."],["新聞記事に、新しい店のことが書いてありました。","Trong bài báo có viết về cửa hàng mới."],["先生は新聞記事を読んで、感想を書いてくださいと言いました。","Thầy giáo bảo đọc bài báo rồi viết cảm tưởng."],["新聞記事を友達に送りました。","Tôi đã gửi bài báo cho bạn."]]},{"word":"社会面","reading":"しゃかいめん","meaning":"trang tin tức xã hội","hanViet":"XÃ HỘI DIỆN","lesson":16,"ex":[["新聞の社会面には、町のニュースが書いてあります。","Trang tin tức xã hội của báo có viết tin tức của thị trấn."],["私は毎朝、社会面から新聞を読みます。","Mỗi sáng tôi đọc báo từ trang tin tức xã hội."],["社会面の記事を読んで、事件のことを知りました。","Đọc bài trên trang xã hội, tôi đã biết về vụ việc."],["社会面に大きな写真があります。","Trên trang xã hội có một bức ảnh lớn."],["父は社会面をよく読んでいます。","Bố tôi thường đọc trang tin tức xã hội."]]},{"word":"概要","reading":"がいよう","meaning":"tóm lược, khái quát","hanViet":"KHÁI YẾU","lesson":16,"ex":[["会議の概要を説明してください。","Hãy giải thích tóm lược nội dung cuộc họp."],["この本の概要をレポートに書きました。","Tôi đã viết tóm lược cuốn sách này vào báo cáo."],["先生は授業の概要を話しました。","Thầy giáo đã nói khái quát về buổi học."],["概要を読めば、内容がだいたい頭に入ります。","Chỉ cần đọc phần tóm lược là đại khái nội dung sẽ vào đầu."],["まず、計画の概要を確認しましょう。","Trước hết, hãy cùng xác nhận tóm lược của kế hoạch."]]},{"word":"すばやい","reading":"","meaning":"nhanh chóng","hanViet":"","lesson":16,"ex":[["彼はすばやくボールを取った。","Anh ấy đã lấy bóng một cách nhanh chóng."],["すばやく答えることが大切です。","Trả lời nhanh chóng là quan trọng."],["彼女はすばやく答えました。","Cô ấy đã trả lời nhanh chóng."],["すばやい判断が求められます。","Cần có sự phán đoán nhanh chóng."],["犬はすばやく走って、ボールを取りました。","Con chó chạy nhanh và lấy được quả bóng."]]},{"word":"事実（～関係）","reading":"じじつ（～かんけい）","meaning":"sự thật","hanViet":"SỰ THỰC QUAN HỆ","lesson":16,"ex":[["事実関係をよく調べることが大切です。","Việc điều tra kỹ sự thật là quan trọng."],["警察は事実関係を調べています。","Cảnh sát đang điều tra sự thật."],["事実関係がまだはっきりしません。","Sự thật vẫn chưa rõ ràng."],["会社は事実関係を確認して、説明しました。","Công ty đã xác nhận sự thật và giải thích."],["事実関係と違う話を信じてはいけません。","Không được tin câu chuyện khác với sự thật."]]},{"word":"不幸（な）","reading":"ふこう（な）","meaning":"không may mắn, bất hạnh","hanViet":"BẤT HẠNH","lesson":16,"ex":[["不幸な事故が起きました。","Đã xảy ra một tai nạn bất hạnh."],["彼は不幸な出来事を話しました。","Anh ấy đã kể về sự việc không may."],["不幸なことに、雨が降りました。","Không may là trời đã mưa."],["不幸な人は、だれかの助けが必要です。","Người bất hạnh cần sự giúp đỡ của ai đó."],["不幸なニュースを聞いて、悲しくなりました。","Nghe tin không may, tôi đã thấy buồn."]]},{"word":"幸い","reading":"さいわい","meaning":"hạnh phúc, may mắn","hanViet":"HẠNH","lesson":16,"ex":[["幸い、けがはありませんでした。","May mắn là không có ai bị thương."],["幸い、電車に間に合いました。","May mắn là tôi đã kịp tàu."],["幸いなことに、荷物が見つかりました。","May mắn là đã tìm thấy hành lý."],["幸い、試験に合格しました。","May mắn là tôi đã đỗ kỳ thi."],["幸い、友達が助けてくれました。","May mắn là bạn đã giúp tôi."]]},{"word":"苦い（～体験）","reading":"にがい（～たいけん）","meaning":"cay đắng (trải nghiệm)","hanViet":"KHỔ THỂ NGHIỆM","lesson":16,"ex":[["苦い体験から、多くを学びました。","Từ trải nghiệm cay đắng, tôi đã học được nhiều điều."],["あの苦い体験を忘れられません。","Tôi không thể quên trải nghiệm cay đắng đó."],["苦い体験も、人生の勉強になります。","Trải nghiệm cay đắng cũng là bài học của cuộc đời."],["試験に落ちた苦い体験があります。","Tôi có trải nghiệm cay đắng là đã trượt kỳ thi."],["苦い体験をしたから、同じ失敗をしません。","Vì đã có trải nghiệm cay đắng nên tôi sẽ không mắc cùng một sai lầm."]]},{"word":"慰める","reading":"なぐさめる","meaning":"an ủi, động viên","hanViet":"ỦY","lesson":16,"ex":[["友達を慰めることばが見つかりません。","Tôi không tìm được lời an ủi bạn."],["母は泣いている子どもを慰めました。","Mẹ đã an ủi đứa trẻ đang khóc."],["彼は悲しい友達を慰めています。","Anh ấy đang an ủi người bạn buồn bã."],["慰めるために、静かにそばにいました。","Để an ủi, tôi đã lặng lẽ ở bên cạnh."],["先生は落ち込んでいる学生を慰めました。","Thầy giáo đã an ủi học sinh đang chán nản."]]},{"word":"～づける（元気～）","reading":"～づける（げんき～）","meaning":"tiếp thêm (sức mạnh)","hanViet":"NGUYÊN KHÍ","lesson":16,"ex":[["友達のことばが私を元気づけました。","Lời nói của bạn đã tiếp thêm sức mạnh cho tôi."],["先生は学生を元気づけるために、声をかけました。","Để tiếp thêm sức mạnh cho học sinh, thầy giáo đã gọi hỏi thăm."],["音楽は人を元気づけます。","Âm nhạc tiếp thêm sức mạnh cho con người."],["彼女のことばがみんなを元気づけました。","Lời nói của cô ấy đã tiếp thêm sức mạnh cho mọi người."],["元気づけることばをかけてください。","Hãy nói lời tiếp thêm sức mạnh."]]},{"word":"カード（会員～）","reading":"カード（かいいん～）","meaning":"thẻ (hội viên)","hanViet":"HỘI VIÊN","lesson":16,"ex":[["会員カードを持っていますか。","Bạn có thẻ hội viên không?"],["会員カードを見せると、安くなります。","Đưa thẻ hội viên ra thì sẽ rẻ hơn."],["この店の会員カードを作りました。","Tôi đã làm thẻ hội viên của cửa hàng này."],["会員カードを忘れたので、安くなりませんでした。","Vì quên thẻ hội viên nên không được rẻ hơn."],["会員カードの番号を教えてください。","Hãy cho tôi biết số thẻ hội viên."]]},{"word":"漏れる","reading":"もれる","meaning":"rò rỉ, lộ ra","hanViet":"LẬU","lesson":16,"ex":[["水が漏れています。","Nước đang rò rỉ."],["秘密が外に漏れました。","Bí mật đã bị lộ ra ngoài."],["情報が漏れないように気をつけます。","Tôi cẩn thận để thông tin không bị rò rỉ."],["ガスが漏れたら、窓を開けてください。","Nếu khí gas bị rò rỉ, hãy mở cửa sổ."],["屋根から雨が漏れています。","Mưa đang rò rỉ từ mái nhà."]]},{"word":"通信（する）","reading":"つうしん（する）","meaning":"liên lạc, truyền tin (viễn thông)","hanViet":"THÔNG TÍN","lesson":16,"ex":[["通信が途中で切れました。","Việc liên lạc bị ngắt giữa chừng."],["この電話は通信が速いです。","Điện thoại này truyền dữ liệu nhanh."],["通信する前に、設定を確認してください。","Trước khi liên lạc, hãy kiểm tra cài đặt."],["山の中では通信ができません。","Trong núi thì không thể liên lạc được."],["通信の料金が高くなりました。","Phí liên lạc đã đắt lên."]]},{"word":"販売（する）","reading":"はんばい（する）","meaning":"bán hàng","hanViet":"PHIẾN MẠI","lesson":16,"ex":[["この店は本を販売しています。","Cửa hàng này bán sách."],["新しい商品の販売が始まりました。","Việc bán hàng của sản phẩm mới đã bắt đầu."],["会社はインターネットで商品を販売しています。","Công ty đang bán sản phẩm trên internet."],["販売する前に、値段を決めます。","Trước khi bán, sẽ quyết định giá."],["その店では野菜も販売しています。","Cửa hàng đó cũng bán rau."]]},{"word":"同社","reading":"どうしゃ","meaning":"công ty đó (công ty vừa được nhắc đến)","hanViet":"ĐỒNG XÃ","lesson":16,"ex":[["同社は新しい工場を建てました。","Công ty đó đã xây nhà máy mới."],["同社の商品は人気があります。","Sản phẩm của công ty đó được yêu thích."],["同社は来年、店を増やす予定です。","Công ty đó dự định sang năm sẽ tăng thêm cửa hàng."],["同社の社長が会見を開きました。","Giám đốc công ty đó đã mở cuộc họp báo."],["同社は海外にも店があります。","Công ty đó cũng có cửa hàng ở nước ngoài."]]},{"word":"加入（する）","reading":"かにゅう（する）","meaning":"gia nhập","hanViet":"GIA NHẬP","lesson":16,"ex":[["チームに加入しました。","Tôi đã gia nhập đội."],["チームに加入する人が増えています。","Số người gia nhập đội đang tăng lên."],["彼は新しいチームに加入しました。","Anh ấy đã gia nhập đội mới."],["加入するには、名前を書かなければなりません。","Để gia nhập, phải viết tên."],["新しい会員がチームに加入しました。","Hội viên mới đã gia nhập đội."]]},{"word":"可能性","reading":"かのうせい","meaning":"khả năng","hanViet":"KHẢ NĂNG TÍNH","lesson":16,"ex":[["雨が降る可能性があります。","Có khả năng trời sẽ mưa."],["成功する可能性は高いです。","Khả năng thành công cao."],["可能性を信じて、勉強を続けます。","Tôi tin vào khả năng và sẽ tiếp tục học."],["失敗する可能性もあります。","Cũng có khả năng thất bại."],["新しい方法の可能性を考えています。","Tôi đang suy nghĩ về khả năng của phương pháp mới."]]},{"word":"実態","reading":"じったい","meaning":"tình hình thực tế","hanViet":"THỰC THÁI","lesson":16,"ex":[["会社の実態を調べました。","Tôi đã điều tra tình hình thực tế của công ty."],["実態は思ったより厳しいです。","Tình hình thực tế khắc nghiệt hơn tôi nghĩ."],["学校の実態を知ることが大切です。","Việc biết tình hình thực tế của trường học là quan trọng."],["実態を明らかにしました。","Đã làm rõ tình hình thực tế."],["町の実態を調べる調査が行われました。","Đã tiến hành điều tra tình hình thực tế của thị trấn."]]},{"word":"氏名","reading":"しめい","meaning":"họ tên","hanViet":"THỊ DANH","lesson":16,"ex":[["紙に氏名を書いてください。","Hãy viết họ tên vào giấy."],["氏名と住所を教えてください。","Hãy cho tôi biết họ tên và địa chỉ."],["氏名の漢字を確認しました。","Tôi đã xác nhận chữ Hán của họ tên."],["書類に氏名が書いてありません。","Trên tài liệu không có viết họ tên."],["氏名を変えました。","Tôi đã thay đổi họ tên."]]},{"word":"預金（～口座）","reading":"よきん（～こうざ）","meaning":"(tài khoản) tiền gởi","hanViet":"DỰ KIM KHẨU TỌA","lesson":16,"ex":[["預金口座を開きました。","Tôi đã mở tài khoản tiền gửi."],["預金口座にお金を入れました。","Tôi đã bỏ tiền vào tài khoản tiền gửi."],["預金口座の番号を教えてください。","Hãy cho tôi biết số tài khoản tiền gửi."],["預金口座からお金を引き出しました。","Tôi đã rút tiền từ tài khoản tiền gửi."],["新しい預金口座を作りました。","Tôi đã lập tài khoản tiền gửi mới."]]},{"word":"職業","reading":"しょくぎょう","meaning":"nghề nghiệp","hanViet":"CHỨC NGHIỆP","lesson":16,"ex":[["職業は何ですか。","Nghề nghiệp của bạn là gì?"],["彼の職業は先生です。","Nghề nghiệp của anh ấy là giáo viên."],["職業を選ぶことは大切です。","Việc chọn nghề nghiệp là quan trọng."],["将来の職業について考えています。","Tôi đang suy nghĩ về nghề nghiệp tương lai."],["職業が違うと、時間が違います。","Nếu nghề nghiệp khác nhau thì thời gian khác nhau."]]},{"word":"生年月日","reading":"せいねんがっぴ","meaning":"ngày tháng năm sinh","hanViet":"SINH NIÊN NGUYỆT NHẬT","lesson":16,"ex":[["生年月日を教えてください。","Hãy cho tôi biết ngày tháng năm sinh."],["生年月日を書類に書きました。","Tôi đã viết ngày tháng năm sinh vào tài liệu."],["生年月日はとても大切な情報です。","Ngày tháng năm sinh là thông tin rất quan trọng."],["生年月日を確認してください。","Hãy xác nhận ngày tháng năm sinh."],["彼の生年月日を知っていますか。","Bạn có biết ngày tháng năm sinh của anh ấy không?"]]},{"word":"項目","reading":"こうもく","meaning":"hạng mục, khoản","hanViet":"HẠNG MỤC","lesson":16,"ex":[["項目を全部確認しました。","Tôi đã xác nhận tất cả các hạng mục."],["この項目は大切です。","Hạng mục này quan trọng."],["項目が多すぎます。","Có quá nhiều hạng mục."],["項目にチェックを入れてください。","Hãy đánh dấu vào hạng mục."],["項目の順番を変えました。","Tôi đã thay đổi thứ tự các hạng mục."]]},{"word":"及ぶ","reading":"およぶ","meaning":"đạt đến, lên đến","hanViet":"CẬP","lesson":16,"ex":[["被害は町全体に及びました。","Thiệt hại đã lan đến toàn bộ thị trấn."],["影響は広い範囲に及びます。","Ảnh hưởng lan đến phạm vi rộng."],["参加者は百人に及びました。","Số người tham gia đã lên đến một trăm người."],["その話は海外にまで及びました。","Câu chuyện đó đã lan đến cả nước ngoài."],["被害は隣の町にまで及びました。","Thiệt hại đã lan đến cả thị trấn bên cạnh."]]},{"word":"上旬","reading":"じょうじゅん","meaning":"đầu tháng, thượng tuần","hanViet":"THƯỢNG TUẦN","lesson":16,"ex":[["上旬に会議があります。","Đầu tháng có cuộc họp."],["来月の上旬に旅行に行きます。","Đầu tháng sau tôi sẽ đi du lịch."],["上旬は天気がよかったです。","Đầu tháng thời tiết đã tốt."],["今月の上旬に引っ越しをしました。","Đầu tháng này tôi đã chuyển nhà."],["上旬までにレポートを出してください。","Hãy nộp báo cáo trước khi hết đầu tháng."]]},{"word":"覚え（身に～がない）","reading":"おぼえ（みに～がない）","meaning":"(bản thân không) nhớ","hanViet":"GIÁC THÂN","lesson":16,"ex":[["身に覚えがない請求が来ました。","Đã có yêu cầu thanh toán mà tôi không nhớ."],["身に覚えがないメールが届きました。","Đã nhận được email mà tôi không nhớ gì."],["身に覚えがないことは、はっきり言いましょう。","Chuyện mình không nhớ thì hãy nói rõ ràng."],["身に覚えがない電話がかかってきました。","Đã nhận được cuộc gọi mà tôi không nhớ gì."],["身に覚えがないので、警察に相談しました。","Vì không nhớ gì nên tôi đã báo với cảnh sát."]]},{"word":"未払い（金）","reading":"みはらい（きん）","meaning":"(khoản tiền) chưa trả, chưa thanh toán","hanViet":"VỊ PHẤT KIM","lesson":16,"ex":[["未払い金があります。","Có khoản tiền chưa trả."],["未払い金を払ってください。","Hãy trả khoản tiền chưa thanh toán."],["未払い金の金額を確認しました。","Tôi đã xác nhận số tiền chưa trả."],["未払い金があると、新しいカードが作れません。","Nếu có tiền chưa trả thì không thể làm thẻ mới."],["未払い金をすぐ払うことが大切です。","Việc trả ngay khoản tiền chưa thanh toán là quan trọng."]]},{"word":"請求書","reading":"せいきゅうしょ","meaning":"hóa đơn thanh toán","hanViet":"THỈNH CẦU THƯ","lesson":16,"ex":[["請求書が届きました。","Hóa đơn thanh toán đã đến."],["請求書の金額を確認してください。","Hãy xác nhận số tiền trên hóa đơn thanh toán."],["請求書を会社に送りました。","Tôi đã gửi hóa đơn thanh toán cho công ty."],["請求書が違っていました。","Hóa đơn thanh toán đã bị sai."],["請求書は来週届きます。","Hóa đơn thanh toán sẽ đến vào tuần sau."]]},{"word":"請求（する）","reading":"せいきゅう（する）","meaning":"yêu cầu thanh toán","hanViet":"THỈNH CẦU","lesson":16,"ex":[["会社にお金を請求しました。","Tôi đã yêu cầu công ty thanh toán tiền."],["請求する前に、金額を確認します。","Trước khi yêu cầu thanh toán, tôi xác nhận số tiền."],["請求された金額は高すぎます。","Số tiền bị yêu cầu thanh toán quá cao."],["彼に代金を請求しました。","Tôi đã yêu cầu anh ấy thanh toán tiền hàng."],["請求が来たので、銀行に行きました。","Vì có yêu cầu thanh toán đến nên tôi đã đi ngân hàng."]]},{"word":"判明（する）","reading":"はんめい（する）","meaning":"trở nên sáng tỏ, phân định rõ ràng","hanViet":"PHÁN MINH","lesson":16,"ex":[["原因が判明しました。","Nguyên nhân đã trở nên rõ ràng."],["調査で本当のことが判明しました。","Qua điều tra, sự thật đã trở nên rõ ràng."],["犯人が判明しました。","Thủ phạm đã được xác định rõ."],["判明したことを先生に話しました。","Tôi đã nói với thầy giáo những điều đã rõ ràng."],["事故の原因はまだ判明していません。","Nguyên nhân vụ tai nạn vẫn chưa rõ ràng."]]},{"word":"同様（な）","reading":"どうよう（な）","meaning":"giống","hanViet":"ĐỒNG DẠNG","lesson":16,"ex":[["同様の問題が起きました。","Vấn đề giống như vậy đã xảy ra."],["同様の意見を持つ人が多いです。","Có nhiều người có ý kiến giống như vậy."],["同様に、彼も失敗しました。","Tương tự, anh ấy cũng đã thất bại."],["同様の方法で作りました。","Tôi đã làm bằng phương pháp giống như vậy."],["同様のことがもう起きないようにします。","Tôi sẽ làm để việc giống như vậy không xảy ra lần nữa."]]},{"word":"～件","reading":"～けん","meaning":"vụ ~","hanViet":"KIỆN","lesson":16,"ex":[["事件が三件起きました。","Đã xảy ra ba vụ việc."],["問い合わせが十件ありました。","Có mười lượt hỏi thăm."],["今月は五件の注文がありました。","Tháng này có năm đơn đặt hàng."],["被害は二十件に及びました。","Thiệt hại đã lên đến hai mươi vụ."],["一件の事故が起きました。","Đã xảy ra một vụ tai nạn."]]},{"word":"寄せる","reading":"よせる","meaning":"đến, đưa đến","hanViet":"KÝ","lesson":16,"ex":[["多くの人が意見を寄せました。","Nhiều người đã gửi ý kiến đến."],["町に期待を寄せています。","Tôi đặt kỳ vọng vào thị trấn."],["応援の声を寄せてください。","Hãy gửi lời cổ vũ đến."],["市民が声を寄せました。","Người dân đã gửi tiếng nói đến."],["彼は私に信頼を寄せています。","Anh ấy đặt niềm tin vào tôi."]]},{"word":"既に","reading":"すでに","meaning":"đã, rồi","hanViet":"KÝ","lesson":16,"ex":[["既に会議は終わっています。","Cuộc họp đã kết thúc rồi."],["既に知っている話です。","Đó là câu chuyện đã biết rồi."],["既に十人が申し込んでいます。","Đã có mười người đăng ký rồi."],["既に冬が来ました。","Mùa đông đã đến rồi."],["既に本を読んだことがあります。","Tôi đã từng đọc cuốn sách này rồi."]]},{"word":"応じて","reading":"おうじて","meaning":"ứng với","hanViet":"ỨNG","lesson":16,"ex":[["働く時間に応じて、給料が変わります。","Tùy theo thời gian làm việc mà lương thay đổi."],["年齢に応じて、クラスが決まります。","Tùy theo tuổi mà lớp học được quyết định."],["天気に応じて、服を選びます。","Tùy theo thời tiết mà chọn quần áo."],["希望に応じて、部屋を用意します。","Tùy theo nguyện vọng mà chuẩn bị phòng."],["能力に応じて、仕事を分けます。","Tùy theo năng lực mà phân chia công việc."]]},{"word":"支払い","reading":"しはらい","meaning":"sự chi trả","hanViet":"CHI PHẤT","lesson":16,"ex":[["支払いは現金です。","Việc thanh toán là bằng tiền mặt."],["支払いの方法を教えてください。","Hãy cho tôi biết phương pháp thanh toán."],["支払いが遅れました。","Việc thanh toán đã bị chậm."],["支払いを忘れないでください。","Đừng quên thanh toán."],["来週、支払いがあります。","Tuần sau có khoản thanh toán."]]},{"word":"情報管理","reading":"じょうほうかんり","meaning":"sự quản lí thông tin","hanViet":"TÌNH BÁO QUẢN LÝ","lesson":16,"ex":[["情報管理が大切な仕事です。","Quản lý thông tin là công việc quan trọng."],["情報管理をしっかり行います。","Tôi thực hiện quản lý thông tin một cách chắc chắn."],["情報管理の方法を学びました。","Tôi đã học phương pháp quản lý thông tin."],["情報管理が甘いと、問題が起きます。","Nếu quản lý thông tin lỏng lẻo thì sẽ xảy ra vấn đề."],["会社は情報管理に力を入れています。","Công ty đang chú trọng vào quản lý thông tin."]]},{"word":"管理（する）","reading":"かんり（する）","meaning":"quản lí","hanViet":"QUẢN LÝ","lesson":16,"ex":[["時間を管理することが大切です。","Việc quản lý thời gian là quan trọng."],["彼は店を管理しています。","Anh ấy đang quản lý cửa hàng."],["お金を管理するのが苦手です。","Tôi kém quản lý tiền bạc."],["管理する人が必要です。","Cần có người quản lý."],["健康を管理するために、運動します。","Để quản lý sức khỏe, tôi tập thể dục."]]},{"word":"事態","reading":"じたい","meaning":"tình trạng sự việc, sự thể","hanViet":"SỰ THÁI","lesson":16,"ex":[["事態が変わりました。","Tình hình sự việc đã thay đổi."],["事態をよく見て、判断します。","Tôi xem kỹ tình hình sự việc rồi phán đoán."],["事態が悪くなっています。","Tình hình sự việc đang trở nên xấu đi."],["事態の説明を受けました。","Tôi đã nhận được giải thích về tình hình sự việc."],["事態を落ち着かせることが大切です。","Việc làm cho tình hình sự việc bình tĩnh lại là quan trọng."]]},{"word":"遺憾","reading":"いかん","meaning":"đáng tiếc","hanViet":"DI HÁM","lesson":16,"ex":[["遺憾な結果になりました。","Đã trở thành kết quả đáng tiếc."],["遺憾に思います。","Tôi thấy đáng tiếc."],["遺憾な出来事でした。","Đó là sự việc đáng tiếc."],["社長は遺憾の気持ちを表しました。","Giám đốc đã bày tỏ cảm giác đáng tiếc."],["遺憾なことですが、きょうは来られません。","Đáng tiếc nhưng hôm nay tôi không thể đến."]]},{"word":"コンピューターシステム","reading":"","meaning":"hệ thống máy tính","hanViet":"","lesson":16,"ex":[["コンピューターシステムが新しくなりました。","Hệ thống máy tính đã trở nên mới."],["コンピューターシステムの管理をしています。","Tôi đang quản lý hệ thống máy tính."],["コンピューターシステムにトラブルが起きました。","Hệ thống máy tính đã xảy ra sự cố."],["コンピューターシステムを更新しました。","Tôi đã cập nhật hệ thống máy tính."],["新しいコンピューターシステムを買いました。","Tôi đã mua hệ thống máy tính mới."]]},{"word":"システム","reading":"","meaning":"hệ thống","hanViet":"","lesson":16,"ex":[["システムが止まりました。","Hệ thống đã dừng lại."],["新しいシステムを使います。","Tôi dùng hệ thống mới."],["システムを使うのは難しいです。","Việc dùng hệ thống thì khó."],["システムを新しくしました。","Tôi đã làm mới hệ thống."],["システムが便利になりました。","Hệ thống đã trở nên tiện lợi."]]},{"word":"トラブル","reading":"","meaning":"lỗi, sự cố","hanViet":"","lesson":16,"ex":[["トラブルが起きました。","Đã xảy ra sự cố."],["トラブルをなくしました。","Tôi đã loại bỏ sự cố."],["トラブルが起きないように気をつけます。","Tôi cẩn thận để sự cố không xảy ra."],["トラブルの原因を調べます。","Tôi điều tra nguyên nhân sự cố."],["小さなトラブルがありました。","Có một sự cố nhỏ."]]},{"word":"内部","reading":"ないぶ","meaning":"nội bộ","hanViet":"NỘI BỘ","lesson":16,"ex":[["会社の内部を調べました。","Tôi đã điều tra nội bộ công ty."],["内部の情報は秘密です。","Thông tin nội bộ là bí mật."],["内部から声が上がりました。","Từ nội bộ đã có tiếng nói vang lên."],["内部の問題を直します。","Tôi sửa vấn đề nội bộ."],["建物の内部は広いです。","Bên trong tòa nhà rộng rãi."]]},{"word":"ないし","reading":"","meaning":"hoặc","hanViet":"","lesson":16,"ex":[["三人ないし四人で話し合いました。","Ba hoặc bốn người đã thảo luận với nhau."],["一時間ないし二時間かかります。","Mất một hoặc hai giờ."],["電話ないしメールで連絡してください。","Hãy liên lạc bằng điện thoại hoặc email."],["月曜日ないし火曜日に来てください。","Hãy đến vào thứ hai hoặc thứ ba."],["二人ないし三人で話します。","Hai hoặc ba người nói chuyện."]]},{"word":"引き出す","reading":"ひきだす","meaning":"rút ra, lấy ra","hanViet":"DẪN XUẤT","lesson":16,"ex":[["銀行からお金を引き出しました。","Tôi đã rút tiền từ ngân hàng."],["引き出しから本を引き出しました。","Tôi đã lấy sách ra từ ngăn kéo."],["彼の力を引き出すことが大切です。","Việc khơi gợi sức mạnh của anh ấy là quan trọng."],["財布からカードを引き出しました。","Tôi đã lấy thẻ ra từ ví."],["引き出す前に、お金を確認しました。","Trước khi rút, tôi đã xác nhận tiền."]]},{"word":"流失","reading":"りゅうしつ","meaning":"thất thoát, mất mát (thông tin/dữ liệu)","hanViet":"LƯU THẤT","lesson":16,"ex":[["大切な情報が流失しました。","Thông tin quan trọng đã bị mất đi."],["データの流失を防ぎます。","Tôi ngăn chặn việc mất dữ liệu."],["流失した情報を探しています。","Tôi đang tìm thông tin đã bị mất."],["流失の原因を調べています。","Tôi đang điều tra nguyên nhân mất mát."],["流失した書類は見つかりませんでした。","Tài liệu đã bị mất thì không tìm thấy."]]},{"word":"面（システム～）","reading":"めん（システム～）","meaning":"mặt, khía cạnh (hệ thống ~)","hanViet":"DIỆN","lesson":16,"ex":[["システム面の問題があります。","Có vấn đề về mặt hệ thống."],["システム面のトラブルが起きました。","Đã xảy ra sự cố về mặt hệ thống."],["システム面の安全が大切です。","Sự an toàn về mặt hệ thống là quan trọng."],["システム面を守ることが大切です。","Việc bảo vệ mặt hệ thống là quan trọng."],["システム面について話し合いました。","Chúng tôi đã thảo luận về mặt hệ thống."]]},{"word":"進める（調査を～）","reading":"すすめる（ちょうさを～）","meaning":"tiến hành (điều tra ~)","hanViet":"TIẾN ĐIỀU TRA","lesson":16,"ex":[["警察は調査を進めています。","Cảnh sát đang tiến hành điều tra."],["調査を進めるために、人を増やしました。","Để tiến hành điều tra, đã tăng thêm người."],["調査を進めると、新しいことを知りました。","Khi tiến hành điều tra, đã biết được điều mới."],["会社は調査を進めることを決めました。","Công ty đã quyết định tiến hành điều tra."],["調査を進めていますが、まだ終わりません。","Đang tiến hành điều tra nhưng vẫn chưa xong."]]},{"word":"求める","reading":"もとめる","meaning":"tìm kiếm, mong muốn; yêu cầu","hanViet":"CẦU","lesson":16,"ex":[["助けを求めました。","Tôi đã yêu cầu giúp đỡ."],["会社は新しい社員を求めています。","Công ty đang tìm kiếm nhân viên mới."],["彼は説明を求めました。","Anh ấy đã yêu cầu giải thích."],["説明を求める声が多いです。","Có nhiều tiếng nói yêu cầu giải thích."],["私は平和を求めています。","Tôi đang mong muốn hòa bình."]]},{"word":"おわび","reading":"","meaning":"lời xin lỗi","hanViet":"","lesson":16,"ex":[["おわびのことばを伝えました。","Tôi đã truyền đạt lời xin lỗi."],["おわびの手紙を書きました。","Tôi đã viết thư xin lỗi."],["おわびの気持ちを表しました。","Tôi đã bày tỏ cảm giác xin lỗi."],["社長がおわびを言いました。","Giám đốc đã nói lời xin lỗi."],["おわびのメールを送りました。","Tôi đã gửi email xin lỗi."]]},{"word":"書面","reading":"しょめん","meaning":"văn bản","hanViet":"THƯ DIỆN","lesson":16,"ex":[["書面で連絡します。","Tôi sẽ liên lạc bằng văn bản."],["書面に名前を書いてください。","Hãy viết tên vào văn bản."],["書面で確認しました。","Tôi đã xác nhận bằng văn bản."],["書面の内容を読みました。","Tôi đã đọc nội dung văn bản."],["書面で送ってください。","Hãy gửi bằng văn bản."]]},{"word":"更新（する）","reading":"こうしん（する）","meaning":"cập nhật, gia hạn","hanViet":"CANH TÂN","lesson":16,"ex":[["パスワードを更新しました。","Tôi đã cập nhật mật khẩu."],["情報を更新することが大切です。","Việc cập nhật thông tin là quan trọng."],["サイトの内容を更新しました。","Tôi đã cập nhật nội dung trang web."],["更新する前に、確認してください。","Trước khi cập nhật, hãy xác nhận."],["毎週、データを更新します。","Mỗi tuần tôi cập nhật dữ liệu."]]},{"word":"早急（な）","reading":"さっきゅう（な）","meaning":"nhanh, khẩn cấp","hanViet":"TẢO CẤP","lesson":16,"ex":[["早急な返事が必要です。","Cần trả lời gấp."],["早急に連絡してください。","Hãy liên lạc ngay."],["早急に手伝ってください。","Hãy giúp tôi ngay lập tức."],["早急に来てください。","Hãy đến ngay."],["早急に直すことが必要です。","Cần sửa gấp."]]},{"word":"講ずる","reading":"こうずる","meaning":"đưa ra, thực hiện (biện pháp)","hanViet":"GIẢNG","lesson":16,"ex":[["対策を講じました。","Tôi đã đưa ra biện pháp đối phó."],["会社は新しい対策を講じます。","Công ty sẽ đưa ra biện pháp đối phó mới."],["講じた対策は効果がありました。","Biện pháp đã đưa ra có hiệu quả."],["安全のための対策を講じることが大切です。","Việc đưa ra biện pháp vì an toàn là quan trọng."],["すぐに対策を講じなければなりません。","Phải đưa ra biện pháp đối phó ngay."]]},{"word":"被害者","reading":"ひがいしゃ","meaning":"nạn nhân, người bị hại","hanViet":"BỊ HẠI GIẢ","lesson":16,"ex":[["被害者の話を聞きました。","Tôi đã nghe câu chuyện của nạn nhân."],["被害者を助けることが大切です。","Việc giúp đỡ nạn nhân là quan trọng."],["被害者が増えています。","Nạn nhân đang tăng lên."],["被害者に連絡しました。","Tôi đã liên lạc với nạn nhân."],["被害者の気持ちを考えます。","Tôi suy nghĩ về cảm giác của nạn nhân."]]},{"word":"有料（～サイト）","reading":"ゆうりょう（～サイト）","meaning":"(trang web) có thu phí","hanViet":"HỮU LIỆU","lesson":16,"ex":[["有料サイトに登録しました。","Tôi đã đăng ký trang web có thu phí."],["有料サイトは情報が多いです。","Trang web có thu phí có nhiều thông tin."],["有料サイトを使うには、お金が必要です。","Để dùng trang web có thu phí, cần có tiền."],["有料サイトの会員になりました。","Tôi đã trở thành hội viên trang web có thu phí."],["有料サイトと無料サイトがあります。","Có trang web có thu phí và trang web miễn phí."]]},{"word":"サイト","reading":"","meaning":"trang web","hanViet":"","lesson":16,"ex":[["サイトを見ました。","Tôi đã xem trang web."],["このサイトは便利です。","Trang web này tiện lợi."],["サイトに情報を書きました。","Tôi đã viết thông tin lên trang web."],["サイトを開きました。","Tôi đã mở trang web."],["新しいサイトを作りました。","Tôi đã tạo trang web mới."]]},{"word":"受け取る","reading":"うけとる","meaning":"nhận","hanViet":"THỤ THỦ","lesson":16,"ex":[["手紙を受け取りました。","Tôi đã nhận thư."],["友達からプレゼントを受け取りました。","Tôi đã nhận quà từ bạn."],["受け取る前に、中身を確認しました。","Trước khi nhận, tôi đã xác nhận nội dung bên trong."],["荷物を受け取る時間を指定しました。","Tôi đã chỉ định thời gian nhận hành lý."],["お金を受け取りました。","Tôi đã nhận tiền."]]},{"word":"請求金額","reading":"せいきゅうきんがく","meaning":"số tiền thanh toán","hanViet":"THỈNH CẦU KIM NGẠCH","lesson":16,"ex":[["請求金額を確認しました。","Tôi đã xác nhận số tiền thanh toán."],["請求金額が違います。","Số tiền thanh toán bị sai."],["請求金額を教えてください。","Hãy cho tôi biết số tiền thanh toán."],["請求金額は先月より高いです。","Số tiền thanh toán cao hơn tháng trước."],["請求金額が高いです。","Số tiền thanh toán cao."]]},{"word":"指定（する）","reading":"してい（する）","meaning":"chỉ định","hanViet":"CHỈ ĐỊNH","lesson":16,"ex":[["時間を指定してください。","Hãy chỉ định thời gian."],["指定した場所で会いましょう。","Hãy gặp nhau ở địa điểm đã chỉ định."],["指定された日に行きます。","Tôi sẽ đi vào ngày đã được chỉ định."],["場所を指定します。","Tôi sẽ chỉ định địa điểm."],["指定する前に、よく考えてください。","Trước khi chỉ định, hãy suy nghĩ kỹ."]]},{"word":"振り込む","reading":"ふりこむ","meaning":"chuyển khoản","hanViet":"CHẤN","lesson":16,"ex":[["銀行にお金を振り込みました。","Tôi đã chuyển khoản tiền vào ngân hàng."],["振り込む前に、番号を確認します。","Trước khi chuyển khoản, tôi xác nhận số."],["会社の銀行に振り込んでください。","Hãy chuyển khoản vào ngân hàng của công ty."],["振り込んだお金は戻りません。","Tiền đã chuyển khoản thì không quay lại."],["毎月、家賃を振り込みます。","Mỗi tháng tôi chuyển khoản tiền thuê nhà."]]},{"word":"だます","reading":"","meaning":"lừa đảo, lừa gạt","hanViet":"","lesson":16,"ex":[["人をだましてはいけません。","Không được lừa gạt người khác."],["彼は私をだましました。","Anh ấy đã lừa tôi."],["だまされないように気をつけてください。","Hãy cẩn thận để không bị lừa."],["お金をだます人がいます。","Có người lừa tiền."],["だますことは悪いことです。","Việc lừa gạt là việc xấu."]]},{"word":"不信（に）","reading":"ふしん（に）","meaning":"ngờ vực, không tin tưởng","hanViet":"BẤT TÍN","lesson":16,"ex":[["不信に思って、電話を切りました。","Tôi thấy ngờ vực nên đã cúp điện thoại."],["不信に思うことがありました。","Có việc tôi thấy ngờ vực."],["メールの内容を不信に思いました。","Tôi thấy ngờ vực nội dung email."],["不信に思ったら、確認してください。","Nếu thấy ngờ vực, hãy xác nhận."],["彼の話を不信に思っています。","Tôi đang thấy ngờ vực câu chuyện của anh ấy."]]},{"word":"懸命（な）","reading":"けんめい（な）","meaning":"hết sức, tận lực","hanViet":"HUYỀN MỆNH","lesson":16,"ex":[["懸命に勉強しています。","Tôi đang học hết sức."],["懸命な勉強が大切です。","Học tập hết sức là quan trọng."],["彼は懸命に働いています。","Anh ấy đang làm việc hết sức."],["懸命に走りました。","Tôi đã chạy hết sức."],["懸命な練習を続けます。","Tôi tiếp tục luyện tập hết sức."]]},{"word":"何者","reading":"なにもの","meaning":"người nào, kẻ nào","hanViet":"HÀ GIẢ","lesson":16,"ex":[["何者が来ましたか。","Kẻ nào đã đến?"],["何者か知りません。","Tôi không biết là kẻ nào."],["何者がドアを開けました。","Kẻ nào đó đã mở cửa."],["何者かが電話をかけました。","Kẻ nào đó đã gọi điện thoại."],["何者か知っていますか。","Bạn có biết là kẻ nào không?"]]},{"word":"犯行","reading":"はんこう","meaning":"hành vi phạm tội","hanViet":"PHẠM HÀNH","lesson":16,"ex":[["犯行の時間を知りたいです。","Tôi muốn biết thời gian phạm tội."],["犯行を認めました。","Đã thừa nhận hành vi phạm tội."],["犯行の場所を調べました。","Đã điều tra địa điểm phạm tội."],["犯行の理由はまだはっきりしません。","Lý do phạm tội vẫn chưa rõ ràng."],["犯行を止めることが大切です。","Việc ngăn chặn hành vi phạm tội là quan trọng."]]},{"word":"日付","reading":"ひづけ","meaning":"ngày tháng","hanViet":"NHẬT PHÓ","lesson":16,"ex":[["日付を教えてください。","Hãy cho tôi biết ngày tháng."],["日付が違います。","Ngày tháng bị sai."],["日付を確認しました。","Tôi đã xác nhận ngày tháng."],["手紙に日付を書きました。","Tôi đã viết ngày tháng vào thư."],["日付は来月の十日です。","Ngày tháng là ngày mười tháng sau."]]},{"word":"タウンニュース","reading":"","meaning":"tin tức địa phương","hanViet":"","lesson":16,"ex":[["タウンニュースを読みました。","Tôi đã đọc tin tức địa phương."],["タウンニュースに町のことが書いてあります。","Trong tin tức địa phương có viết về thị trấn."],["タウンニュースの記者です。","Tôi là phóng viên tin tức địa phương."],["タウンニュースでイベントを知りました。","Tôi đã biết sự kiện qua tin tức địa phương."],["タウンニュースを毎週読みます。","Tôi đọc tin tức địa phương mỗi tuần."]]},{"word":"要素","reading":"ようそ","meaning":"yếu tố","hanViet":"YẾU TỐ","lesson":16,"ex":[["成功の要素は何ですか。","Yếu tố của thành công là gì?"],["大切な要素が三つあります。","Có ba yếu tố quan trọng."],["要素をよく考えます。","Tôi suy nghĩ kỹ các yếu tố."],["この要素が大切です。","Yếu tố này quan trọng."],["要素を組み合わせました。","Tôi đã kết hợp các yếu tố."]]},{"word":"原稿","reading":"げんこう","meaning":"bản thảo","hanViet":"NGUYÊN CÁO","lesson":16,"ex":[["原稿を書きました。","Tôi đã viết bản thảo."],["原稿をまた読みました。","Tôi đã đọc lại bản thảo."],["原稿を送りました。","Tôi đã gửi bản thảo."],["原稿の内容を確認しました。","Tôi đã xác nhận nội dung bản thảo."],["原稿を直しました。","Tôi đã sửa bản thảo."]]},{"word":"見出し","reading":"みだし","meaning":"tiêu đề, đầu đề","hanViet":"KIẾN XUẤT","lesson":16,"ex":[["見出しを読みました。","Tôi đã đọc tiêu đề."],["見出しが大きいです。","Tiêu đề lớn."],["見出しを見て、記事を選びます。","Nhìn tiêu đề, tôi chọn bài báo."],["見出しを考えました。","Tôi đã suy nghĩ tiêu đề."],["新聞の見出しが目に入りました。","Tiêu đề báo đã lọt vào mắt tôi."]]},{"word":"滑らす","reading":"すべらす","meaning":"làm trượt, trượt (cái gì đó)","hanViet":"HOẠT","lesson":16,"ex":[["雪の上で足を滑らしました。","Tôi đã trượt chân trên tuyết."],["ボールペンを滑らして、線を引きました。","Tôi trượt bút bi và vẽ đường thẳng."],["手を滑らして、皿を落としました。","Tôi trượt tay và làm rơi đĩa."],["指を滑らして、画面を変えました。","Tôi trượt ngón tay và đổi màn hình."],["ボールを滑らしました。","Tôi đã làm quả bóng trượt đi."]]},{"word":"捻挫（する）","reading":"ねんざ（する）","meaning":"bong gân, trật khớp","hanViet":"NIẾP TỎA","lesson":16,"ex":[["足を捻挫しました。","Tôi đã bị bong gân chân."],["捻挫したので、病院に行きました。","Vì bị bong gân nên tôi đã đi bệnh viện."],["手を捻挫しないように気をつけます。","Tôi cẩn thận để không bị bong gân tay."],["捻挫して、歩けません。","Bị bong gân nên tôi không đi bộ được."],["スポーツで足を捻挫しました。","Tôi đã bị bong gân chân khi chơi thể thao."]]},{"word":"後悔（する）","reading":"こうかい（する）","meaning":"hối tiếc","hanViet":"HẬU HỐI","lesson":16,"ex":[["後悔しています。","Tôi đang hối tiếc."],["後悔しないように、よく考えます。","Tôi suy nghĩ kỹ để không phải hối tiếc."],["あのときのことを後悔しています。","Tôi đang hối tiếc về chuyện lúc đó."],["後悔しても、時間は戻りません。","Dù hối tiếc, thời gian cũng không quay lại."],["後悔する前に、よく考えてください。","Trước khi hối tiếc, hãy suy nghĩ kỹ."]]},{"word":"落ち込む","reading":"おちこむ","meaning":"cảm thấy chán nản","hanViet":"LẠC","lesson":16,"ex":[["試験に落ちて、落ち込みました。","Trượt kỳ thi nên tôi đã chán nản."],["落ち込んでいる友達を慰めました。","Tôi đã an ủi người bạn đang chán nản."],["落ち込まないでください。","Đừng chán nản."],["雨の日は落ち込みます。","Ngày mưa tôi thấy chán nản."],["落ち込んだときは、音楽を聞きます。","Khi chán nản, tôi nghe nhạc."]]},{"word":"転倒（する）","reading":"てんとう（する）","meaning":"ngã","hanViet":"CHUYỂN ĐẢO","lesson":16,"ex":[["雪の上で転倒しました。","Tôi đã ngã trên tuyết."],["転倒して、足をけがしました。","Ngã nên tôi đã bị thương ở chân."],["転倒しないように気をつけてください。","Hãy cẩn thận để không bị ngã."],["自転車で転倒しました。","Tôi đã ngã xe đạp."],["転倒した人を助けました。","Tôi đã giúp người bị ngã."]]},{"word":"言い表す","reading":"いいあらわす","meaning":"bày tỏ","hanViet":"NGÔN BIỂU","lesson":16,"ex":[["気持ちを言い表すことが難しいです。","Việc bày tỏ cảm xúc rất khó."],["ことばで言い表せません。","Không thể bày tỏ bằng lời."],["うれしい気持ちを言い表すことができません。","Không thể bày tỏ cảm giác vui mừng."],["彼は気持ちをうまく言い表しました。","Anh ấy đã bày tỏ cảm xúc một cách khéo léo."],["言い表すことばが見つかりません。","Tôi không tìm được lời để bày tỏ."]]},{"word":"励ます","reading":"はげます","meaning":"khích lệ","hanViet":"LỆ","lesson":16,"ex":[["先生は私を励ましました。","Thầy giáo đã khích lệ tôi."],["母はいつも私を励まします。","Mẹ tôi luôn khích lệ tôi."],["友達が私を励ましてくれました。","Bạn tôi đã khích lệ tôi."],["試験の前に、先生は学生を励ましました。","Trước kỳ thi, thầy giáo đã khích lệ học sinh."],["失敗した友達を励ましてください。","Hãy khích lệ người bạn đã thất bại."]]},{"word":"ハンドル","reading":"","meaning":"tay lái","hanViet":"","lesson":16,"ex":[["運転手はハンドルを強く持ちました。","Tài xế đã nắm chặt tay lái."],["この車のハンドルは重いです。","Tay lái của chiếc xe này nặng."],["雨の日はハンドルが滑ります。","Ngày mưa tay lái bị trượt."],["彼はハンドルを右に切りました。","Anh ấy đã bẻ tay lái sang phải."],["ハンドルをしっかり持ちます。","Cầm chắc tay lái."]]},{"word":"切り損ねる","reading":"きりそこねる","meaning":"đánh lái không kịp","hanViet":"THIẾT TỔN","lesson":16,"ex":[["彼はハンドルを切り損ねて、事故を起こしました。","Anh ấy đánh lái không kịp nên đã gây tai nạn."],["雨の日はハンドルを切り損ねやすいです。","Ngày mưa dễ đánh lái không kịp."],["運転手は交差点でハンドルを切り損ねました。","Tài xế đã đánh lái không kịp ở ngã tư."],["ハンドルを切り損ねると、事故になります。","Đánh lái không kịp thì sẽ thành tai nạn."],["彼はスピードを出して、ハンドルを切り損ねました。","Anh ấy chạy nhanh nên đánh lái không kịp."]]},{"word":"ひっくり返る","reading":"ひっくりかえる","meaning":"ngã ngửa","hanViet":"PHẢN","lesson":16,"ex":[["子どもがひっくり返って、泣きました。","Đứa trẻ ngã ngửa rồi khóc."],["自転車がひっくり返りました。","Xe đạp bị lật ngửa."],["犬がひっくり返って、寝ています。","Con chó nằm ngửa ngủ."],["彼はひっくり返って、頭を打ちました。","Anh ấy ngã ngửa, đập đầu."],["彼は走っていて、ひっくり返りました。","Anh ấy đang chạy thì ngã ngửa."]]},{"word":"人身事故","reading":"じんしんじこ","meaning":"tai nạn giao thông gây chấn thương hoặc tử vong","hanViet":"NHÂN THÂN SỰ CỐ","lesson":16,"ex":[["この道で人身事故が起こりました。","Trên con đường này đã xảy ra tai nạn giao thông gây thương vong."],["人身事故で、人がけがをしました。","Trong vụ tai nạn, một người đã bị thương."],["運転手は人身事故を起こしました。","Tài xế đã gây tai nạn giao thông gây thương vong."],["人身事故が増えています。","Tai nạn giao thông gây thương vong đang tăng."],["雨の日は人身事故が多いです。","Ngày mưa có nhiều tai nạn giao thông gây thương vong."]]},{"word":"起こす（事故を～）","reading":"おこす（じこを～）","meaning":"gây ra (tai nạn)","hanViet":"KHỞI SỰ CỐ","lesson":16,"ex":[["彼はスピードを出して、事故を起こしました。","Anh ấy chạy nhanh nên đã gây tai nạn."],["運転手は注意しないで、事故を起こしました。","Tài xế không chú ý nên đã gây tai nạn."],["彼は酒を飲んで、事故を起こしました。","Anh ấy uống rượu rồi gây tai nạn."],["事故を起こさないように、気をつけて運転します。","Để không gây tai nạn, tôi lái xe cẩn thận."],["彼は眠くて、事故を起こしそうになりました。","Anh ấy buồn ngủ nên suýt gây tai nạn."]]},{"word":"危うく","reading":"あやうく","meaning":"suýt","hanViet":"NGUY","lesson":16,"ex":[["危うく事故を起こすところでした。","Suýt nữa thì tôi đã gây tai nạn."],["危うく電車に遅れるところでした。","Suýt nữa thì tôi lỡ tàu."],["危うく転ぶところでした。","Suýt nữa thì tôi ngã."],["危うく財布をなくすところでした。","Suýt nữa thì tôi mất ví."],["危うく遅れるところでしたが、間に合いました。","Suýt nữa thì muộn nhưng tôi đã kịp."]]},{"word":"左折（する）","reading":"させつ（する）","meaning":"rẽ trái","hanViet":"TẢ CHIẾT","lesson":16,"ex":[["交差点で左折します。","Rẽ trái ở ngã tư."],["次の交差点で左折してください。","Hãy rẽ trái ở ngã tư tiếp theo."],["車は左折して、駅の前に止まりました。","Xe rẽ trái rồi dừng trước ga."],["左折するとき、自転車に気をつけます。","Khi rẽ trái, hãy chú ý xe đạp."],["左折する前に、信号を見ます。","Trước khi rẽ trái, hãy nhìn đèn tín hiệu."]]},{"word":"飛び出す","reading":"とびだす","meaning":"chạy ra, nhảy ra, lao ra","hanViet":"PHI XUẤT","lesson":16,"ex":[["子どもが道に飛び出しました。","Đứa trẻ lao ra đường."],["犬が家から飛び出しました。","Con chó chạy ra khỏi nhà."],["猫が車の前に飛び出しました。","Con mèo lao ra trước xe."],["ボールが道に飛び出しました。","Quả bóng lăn ra đường."],["彼は部屋から飛び出して、学校へ行きました。","Anh ấy chạy ra khỏi phòng rồi đi học."]]},{"word":"切る（ハンドルを～）","reading":"きる","meaning":"bẻ (tay lái)","hanViet":"THIẾT","lesson":16,"ex":[["ハンドルを右に切ります。","Bẻ tay lái sang phải."],["ハンドルを左に切って、曲がります。","Bẻ tay lái sang trái rồi rẽ."],["運転手はハンドルを大きく切りました。","Tài xế bẻ tay lái mạnh."],["交差点でハンドルを切ります。","Bẻ tay lái ở ngã tư."],["ハンドルを大きく切ると、車が速く曲がります。","Bẻ tay lái mạnh thì xe rẽ nhanh."]]},{"word":"スリップ（する）","reading":"","meaning":"trượt","hanViet":"","lesson":16,"ex":[["雨の日は車がスリップします。","Ngày mưa xe bị trượt."],["雪の道で車がスリップしました。","Xe bị trượt trên đường tuyết."],["タイヤが古いので、車がスリップしやすいです。","Vì lốp cũ nên xe dễ bị trượt."],["スピードを出すと、車がスリップします。","Chạy nhanh thì xe bị trượt."],["彼はスリップして、事故を起こしました。","Anh ấy bị trượt bánh rồi gây tai nạn."]]},{"word":"ひざ","reading":"","meaning":"đầu gối","hanViet":"","lesson":16,"ex":[["転んで、ひざをけがしました。","Ngã nên bị thương đầu gối."],["ひざが曲がりません。","Đầu gối không gập được."],["彼はひざを打って、泣きました。","Anh ấy đập đầu gối rồi khóc."],["ひざの上に本を置きます。","Đặt sách lên đầu gối."],["長く座っていると、ひざが疲れます。","Ngồi lâu thì đầu gối mỏi."]]},{"word":"ライト","reading":"","meaning":"đèn","hanViet":"","lesson":16,"ex":[["夜は車のライトをつけます。","Buổi tối bật đèn xe."],["ライトが明るいです。","Đèn sáng."],["自転車のライトが壊れました。","Đèn xe đạp bị hỏng."],["ライトを消して、寝ます。","Tắt đèn rồi ngủ."],["暗い道ではライトが必要です。","Trên đường tối cần có đèn."]]},{"word":"カバー","reading":"","meaning":"vỏ bọc","hanViet":"","lesson":16,"ex":[["本にカバーをつけます。","Bọc bìa cho sách."],["電話にカバーをつけました。","Tôi đã lắp vỏ bọc cho điện thoại."],["カバーが汚れています。","Vỏ bọc bị bẩn."],["新しいカバーを買いました。","Tôi đã mua vỏ bọc mới."],["カバーを外して、掃除します。","Tháo vỏ bọc ra rồi lau."]]},{"word":"はねる（人を～）","reading":"はねる（ひとを～）","meaning":"đâm vào (người)","hanViet":"NHÂN","lesson":16,"ex":[["車が人をはねました。","Xe đã đâm vào người."],["自転車が子どもをはねました。","Xe đạp đã đâm vào đứa trẻ."],["彼は車にはねられて、けがをしました。","Anh ấy bị xe đâm nên bị thương."],["車にはねられないように、気をつけます。","Để không bị xe đâm, hãy cẩn thận."],["運転手は人をはねて、逃げました。","Tài xế đâm vào người rồi bỏ chạy."]]},{"word":"頭（が）痛い","reading":"あたま（が）いたい","meaning":"đau đầu","hanViet":"ĐẦU THỐNG","lesson":16,"ex":[["きょうは頭が痛いです。","Hôm nay tôi đau đầu."],["頭が痛いので、早く寝ます。","Vì đau đầu nên tôi ngủ sớm."],["頭が痛くて、勉強ができません。","Đau đầu nên không học được."],["きのうから頭が痛いです。","Từ hôm qua tôi đã đau đầu."],["頭が痛いとき、薬を飲みます。","Khi đau đầu, tôi uống thuốc."]]},{"word":"くよくよ（する）","reading":"","meaning":"rầu rĩ","hanViet":"","lesson":16,"ex":[["失敗したことをくよくよしないでください。","Đừng rầu rĩ về chuyện đã thất bại."],["彼はいつもくよくよしています。","Anh ấy lúc nào cũng rầu rĩ."],["くよくよしても、しかたがありません。","Rầu rĩ cũng chẳng giải quyết được gì."],["試験の結果をくよくよしています。","Tôi đang rầu rĩ về kết quả thi."],["くよくよしないで、前に進みましょう。","Đừng rầu rĩ, hãy tiến lên phía trước."]]},{"word":"おごる","reading":"","meaning":"chiêu đãi, khao","hanViet":"","lesson":16,"ex":[["きょうは私がおごります。","Hôm nay tôi khao."],["彼は友達にごはんをおごりました。","Anh ấy đã khao bạn ăn cơm."],["誕生日に、父がケーキをおごってくれました。","Vào sinh nhật, bố đã khao tôi bánh."],["合格したので、友達におごります。","Vì đã đỗ nên tôi khao bạn."],["彼はよく私におごってくれます。","Anh ấy thường khao tôi."]]},{"word":"締切（日）","reading":"しめきり（び）","meaning":"hạn chót","hanViet":"ĐẾ THIẾT NHẬT","lesson":16,"ex":[["締切は明日です。","Hạn chót là ngày mai."],["締切までに宿題を出します。","Nộp bài tập trước hạn chót."],["締切日は来週の月曜日です。","Ngày hạn chót là thứ Hai tuần sau."],["締切に間に合いませんでした。","Không kịp hạn chót."],["締切を忘れて、困りました。","Quên hạn chót nên tôi gặp rắc rối."]]},{"word":"よそ見","reading":"よそみ","meaning":"nhìn chỗ khác","hanViet":"KIẾN","lesson":16,"ex":[["車を運転するとき、よそ見をしないでください。","Khi lái xe, đừng nhìn chỗ khác."],["よそ見をして、事故を起こしました。","Nhìn chỗ khác nên đã gây tai nạn."],["彼はよそ見をして、人にぶつかりました。","Anh ấy nhìn chỗ khác nên đâm vào người."],["よそ見は危ないです。","Nhìn chỗ khác rất nguy hiểm."],["子どもはよそ見をして、転びました。","Đứa trẻ nhìn chỗ khác nên bị ngã."]]},{"word":"右手","reading":"みぎて","meaning":"tay phải","hanViet":"HỮU THỦ","lesson":16,"ex":[["右手で書きます。","Viết bằng tay phải."],["右手をけがしました。","Tôi bị thương tay phải."],["右手に時計をしています。","Tôi đeo đồng hồ ở tay phải."],["右手を上げてください。","Hãy giơ tay phải lên."],["彼は右手でドアを開けました。","Anh ấy mở cửa bằng tay phải."]]},{"word":"離す（目を～）","reading":"はなす（めを～）","meaning":"rời (mắt) khỏi","hanViet":"LY MỤC","lesson":16,"ex":[["運転するとき、目を道から離しません。","Khi lái xe, tôi không rời mắt khỏi đường."],["彼は本から目を離しません。","Anh ấy không rời mắt khỏi sách."],["目を離すと、子どもが走っていきます。","Rời mắt một cái là đứa trẻ chạy đi."],["テレビから目を離すことができません。","Không thể rời mắt khỏi ti vi."],["先生は学生から目を離しませんでした。","Thầy giáo không rời mắt khỏi học sinh."]]},{"word":"誤る","reading":"あやまる","meaning":"nhầm, sai","hanViet":"NGỘ","lesson":16,"ex":[["彼は道を誤りました。","Anh ấy đi nhầm đường."],["私は名前を誤りました。","Tôi nhầm tên."],["日にちを誤らないでください。","Đừng nhầm ngày."],["彼はボタンを誤って押しました。","Anh ấy bấm nhầm nút."],["計算を誤りました。","Tôi tính nhầm."]]},{"word":"入力（する）","reading":"にゅうりょく（する）","meaning":"nhập vào","hanViet":"NHẬP LỰC","lesson":16,"ex":[["パソコンに名前を入力します。","Nhập tên vào máy tính."],["パスワードを入力してください。","Hãy nhập mật khẩu."],["パソコンに住所を入力します。","Nhập địa chỉ vào máy tính."],["入力した後で、先生に聞きます。","Sau khi nhập, tôi hỏi thầy."],["入力が終わりました。","Đã nhập xong."]]},{"word":"プリントアウト（する）","reading":"","meaning":"in ra","hanViet":"","lesson":16,"ex":[["資料をプリントアウトします。","In tài liệu ra."],["プリントアウトした紙を先生に出します。","Nộp tờ giấy đã in cho thầy."],["プリントアウトしてください。","Hãy in ra."],["プリントアウトが終わるまで、待ちます。","Đợi cho đến khi in xong."],["写真をプリントアウトしました。","Tôi đã in ảnh ra."]]},{"word":"俺","reading":"おれ","meaning":"tôi (từ thường được sử dụng bởi đàn ông)","hanViet":"YÊM","lesson":16,"ex":[["俺は明日、東京へ行く。","Ngày mai tôi đi Tokyo."],["俺の名前は田中だ。","Tên tôi là Tanaka."],["俺がやる。","Để tôi làm."],["俺は車を運転できる。","Tôi lái được xe."],["俺の家は大阪だ。","Nhà tôi ở Osaka."]]},{"word":"バカ","reading":"","meaning":"ngu ngốc, ngớ ngẩn","hanViet":"","lesson":16,"ex":[["バカなことを言わないでください。","Đừng nói điều ngớ ngẩn."],["そんなバカな話はありません。","Không có chuyện ngớ ngẩn như vậy."],["彼はバカなミスをしました。","Anh ấy mắc lỗi ngớ ngẩn."],["バカだなあ、財布を忘れた。","Ngớ ngẩn thật, quên ví rồi."],["バカなことをして、先生に怒られました。","Làm điều ngớ ngẩn nên bị thầy mắng."]]},{"word":"やり直し","reading":"やりなおし","meaning":"làm lại","hanViet":"TRỰC","lesson":16,"ex":[["やり直しをしてください。","Hãy làm lại."],["宿題のやり直しをしました。","Tôi đã làm lại bài tập."],["試験のやり直しはできません。","Không thể làm lại bài thi."],["先生は私にやり直しをさせました。","Thầy bắt tôi làm lại."],["やり直しが多いです。","Phải làm lại nhiều."]]},{"word":"油","reading":"あぶら","meaning":"dầu","hanViet":"DU","lesson":16,"ex":[["油で料理を作ります。","Nấu ăn bằng dầu."],["油が熱いです。","Dầu nóng."],["油を買いに行きます。","Đi mua dầu."],["油が床に落ちました。","Dầu rơi xuống sàn."],["パンに油をつけて、食べます。","Phết dầu lên bánh mì rồi ăn."]]},{"word":"ひっくり返す","reading":"ひっくりかえす","meaning":"lật lại","hanViet":"PHẢN","lesson":16,"ex":[["パンをひっくり返します。","Lật bánh mì lại."],["本をひっくり返して、読みます。","Lật sách lại rồi đọc."],["彼は机をひっくり返しました。","Anh ấy lật bàn."],["カードをひっくり返します。","Lật thẻ lại."],["魚をひっくり返して、焼きます。","Lật cá lại rồi nướng."]]},{"word":"マット","reading":"","meaning":"nệm, đệm","hanViet":"","lesson":16,"ex":[["マットの上で寝ます。","Ngủ trên nệm."],["新しいマットを買いました。","Tôi đã mua nệm mới."],["マットが厚いです。","Nệm dày."],["床にマットを置きます。","Đặt nệm lên sàn."],["マットを洗います。","Giặt nệm."]]},{"word":"べとべと","reading":"","meaning":"dính, bết","hanViet":"","lesson":16,"ex":[["手がべとべとしています。","Tay bị dính."],["汗で体がべとべとしています。","Mồ hôi làm người dính."],["夏はべとべとする日が多いです。","Mùa hè có nhiều ngày dính bết."],["油で手がべとべとになりました。","Dầu làm tay bị dính."],["べとべとするので、シャワーを浴びます。","Vì dính bết nên tôi tắm."]]},{"word":"つく（火が～）","reading":"つく（ひが～）","meaning":"bén (lửa)","hanViet":"HỎA","lesson":16,"ex":[["火がつきました。","Lửa đã bén."],["火がついたら、料理を始めます。","Khi lửa bén, bắt đầu nấu ăn."],["雨で火がつきません。","Vì mưa nên lửa không bén."],["火がつくまで、待ちます。","Đợi cho đến khi lửa bén."],["木に火がつきました。","Lửa bén vào gỗ."]]},{"word":"見方","reading":"みかた","meaning":"cách nhìn","hanViet":"KIẾN PHƯƠNG","lesson":16,"ex":[["見方を変えると、楽しくなります。","Đổi cách nhìn thì sẽ thấy vui."],["人によって見方が違います。","Cách nhìn khác nhau tùy người."],["新しい見方を知りました。","Tôi đã biết cách nhìn mới."],["見方が大切です。","Cách nhìn rất quan trọng."],["彼の見方は正しいです。","Cách nhìn của anh ấy đúng."]]},{"word":"骨折（する）","reading":"こっせつ（する）","meaning":"gãy (xương)","hanViet":"CỐT CHIẾT","lesson":16,"ex":[["転んで、足を骨折しました。","Ngã nên gãy chân."],["彼は腕を骨折しました。","Anh ấy bị gãy tay."],["骨折して、病院に行きました。","Bị gãy xương nên đi bệnh viện."],["骨折したので、1か月休みます。","Vì gãy xương nên nghỉ 1 tháng."],["スポーツで骨折する人が多いです。","Có nhiều người gãy xương khi chơi thể thao."]]},{"word":"うまくいく","reading":"","meaning":"tiến triển tốt, thuận lợi","hanViet":"","lesson":16,"ex":[["仕事がうまくいっています。","Công việc đang thuận lợi."],["計画がうまくいきました。","Kế hoạch đã thành công."],["うまくいくといいですね。","Mong là mọi việc thuận lợi."],["試験がうまくいきました。","Kỳ thi đã thuận lợi."],["新しい仕事がうまくいっています。","Công việc mới đang thuận lợi."]]},{"word":"まいる","reading":"","meaning":"bí, chịu thua","hanViet":"","lesson":16,"ex":[["難しい問題にまいりました。","Tôi chịu thua bài toán khó."],["暑さにまいりました。","Tôi chịu thua cái nóng."],["彼の話にまいりました。","Tôi bí trước chuyện của anh ấy."],["毎日忙しくて、まいっています。","Ngày nào cũng bận nên tôi chịu thua."],["子どものいたずらにまいりました。","Tôi chịu thua trò nghịch của trẻ con."]]},{"word":"まいったなあ","reading":"","meaning":"Chết tôi rồi!","hanViet":"","lesson":16,"ex":[["まいったなあ、電車が止まった。","Chết rồi, tàu dừng rồi."],["まいったなあ、財布を忘れた。","Chết rồi, quên ví rồi."],["まいったなあ、宿題が終わらない。","Chết rồi, bài tập chưa xong."],["まいったなあ、雨が降ってきた。","Chết rồi, trời mưa rồi."],["まいったなあ、鍵をなくした。","Chết rồi, mất chìa khóa rồi."]]},{"word":"ひどい","reading":"","meaning":"kinh khủng, khủng khiếp","hanViet":"","lesson":16,"ex":[["ひどい雨が降っています。","Mưa kinh khủng."],["ひどい事故がありました。","Đã xảy ra tai nạn kinh khủng."],["彼はひどいけがをしました。","Anh ấy bị thương nặng."],["ひどい天気ですね。","Thời tiết tệ thật."],["ひどい間違いをしました。","Tôi đã mắc lỗi nghiêm trọng."]]},{"word":"開発（する）","reading":"かいはつ（する）","meaning":"phát triển","hanViet":"KHAI PHÁT","lesson":16,"ex":[["新しい薬を開発します。","Phát triển thuốc mới."],["会社は新しい車を開発しました。","Công ty đã phát triển xe mới."],["開発が進んでいます。","Việc phát triển đang tiến triển."],["新しい技術を開発します。","Phát triển kỹ thuật mới."],["開発に時間がかかります。","Phát triển mất thời gian."]]},{"word":"要求（する）","reading":"ようきゅう（する）","meaning":"yêu cầu","hanViet":"YẾU CẦU","lesson":16,"ex":[["社員は会社に給料を上げるように要求しました。","Nhân viên yêu cầu công ty tăng lương."],["彼は休みを要求しました。","Anh ấy yêu cầu nghỉ."],["要求が多すぎます。","Yêu cầu quá nhiều."],["彼は店に安くするように要求しました。","Anh ấy yêu cầu cửa hàng giảm giá."],["要求を聞いて、考えます。","Nghe yêu cầu rồi suy nghĩ."]]},{"word":"改める","reading":"あらためる","meaning":"cải cách","hanViet":"CẢI","lesson":16,"ex":[["生活を改めます。","Cải thiện lối sống."],["習慣を改めます。","Sửa thói quen."],["彼は仕事の方法を改めました。","Anh ấy đã sửa phương pháp làm việc."],["規則を改めます。","Sửa quy định."],["悪い習慣を改めましょう。","Hãy sửa thói quen xấu."]]},{"word":"従う","reading":"したがう","meaning":"tuân theo","hanViet":"TÒNG","lesson":16,"ex":[["規則に従います。","Tuân theo quy định."],["先生の言うことに従います。","Tuân theo lời thầy nói."],["法律に従います。","Tuân theo pháp luật."],["交通の規則に従ってください。","Hãy tuân theo luật giao thông."],["彼は両親に従います。","Anh ấy nghe lời bố mẹ."]]},{"word":"急激（な）","reading":"きゅうげき（な）","meaning":"nhanh, mạnh mẽ","hanViet":"CẤP KÍCH","lesson":16,"ex":[["天気が急激に変わりました。","Thời tiết thay đổi nhanh chóng."],["人口が急激に増えました。","Dân số tăng nhanh."],["気温が急激に下がりました。","Nhiệt độ giảm mạnh."],["急激に雨が降りました。","Mưa đột ngột."],["町が急激に大きくなりました。","Thành phố lớn nhanh chóng."]]},{"word":"ATM","reading":"エーティーエム","meaning":"máy rút tiền tự động ATM","hanViet":"","lesson":16,"ex":[["ATMでお金を出します。","Rút tiền ở ATM."],["ATMが壊れています。","ATM bị hỏng."],["ATMは夜も使えます。","ATM dùng được cả ban đêm."],["ATMの前に人が並んでいます。","Trước ATM có người xếp hàng."],["ATMでカードを使います。","Dùng thẻ ở ATM."]]},{"word":"とどまる","reading":"","meaning":"dừng lại","hanViet":"","lesson":16,"ex":[["彼は3日京都にとどまります。","Anh ấy ở lại Kyoto 3 ngày."],["雨で電車が駅にとどまっています。","Vì mưa tàu dừng lại ở ga."],["彼女は東京にとどまりました。","Cô ấy đã ở lại Tokyo."],["仕事がとどまっています。","Công việc đang bị đình trệ."],["台風で船が港にとどまっています。","Vì bão tàu dừng lại ở cảng."]]},{"word":"少子高齢化","reading":"しょうしこうれいか","meaning":"tỷ lệ sinh giảm và dân số già đi","hanViet":"THIỂU TỬ CAO LINH HÓA","lesson":16,"ex":[["日本は少子高齢化が進んでいます。","Nhật Bản đang có tình trạng ít con và già hóa dân số."],["少子高齢化が問題になっています。","Tình trạng ít con và già hóa dân số đang trở thành vấn đề."],["少子高齢化で、働く人が少なくなっています。","Vì ít con và già hóa dân số, số người lao động giảm."],["少子高齢化について、学校で勉強しました。","Tôi đã học về tình trạng ít con và già hóa dân số ở trường."],["少子高齢化は多くの国で問題です。","Ít con và già hóa dân số là vấn đề ở nhiều nước."]]},{"word":"高齢化","reading":"こうれいか","meaning":"sự già hóa dân số","hanViet":"CAO LINH HÓA","lesson":16,"ex":[["日本の高齢化が進んでいます。","Sự già hóa dân số ở Nhật đang tiến triển."],["高齢化で、病院が忙しくなっています。","Vì già hóa dân số, bệnh viện bận rộn hơn."],["高齢化について、新聞で読みました。","Tôi đã đọc về già hóa dân số trên báo."],["高齢化は世界の問題です。","Già hóa dân số là vấn đề của thế giới."],["高齢化が進むと、働く人が少なくなります。","Khi già hóa dân số tiến triển, số người lao động giảm."]]},{"word":"活力","reading":"かつりょく","meaning":"sức sống, sinh khí","hanViet":"HOẠT LỰC","lesson":16,"ex":[["町に活力があります。","Thành phố có sức sống."],["若い人に活力があります。","Người trẻ có sức sống."],["運動をすると、活力が出ます。","Vận động thì có sức sống."],["新しい店ができて、町に活力が出ました。","Có cửa hàng mới nên thành phố có sức sống."],["彼は活力が強いです。","Anh ấy có sức sống mạnh."]]},{"word":"業界","reading":"ぎょうかい","meaning":"ngành, ngành nghề","hanViet":"NGHIỆP GIỚI","lesson":16,"ex":[["自動車の業界で働きます。","Làm việc trong ngành ô tô."],["旅行の業界は忙しいです。","Ngành du lịch bận rộn."],["この業界は競争が激しいです。","Ngành này cạnh tranh khốc liệt."],["業界のニュースを読みます。","Đọc tin tức ngành."],["彼は音楽の業界で働いています。","Anh ấy làm việc trong ngành âm nhạc."]]},{"word":"需要","reading":"じゅよう","meaning":"nhu cầu","hanViet":"NHU YẾU","lesson":16,"ex":[["電気の需要が増えています。","Nhu cầu điện đang tăng."],["需要が多くなると、値段が上がります。","Khi nhu cầu tăng, giá tăng."],["この商品の需要は大きいです。","Nhu cầu về sản phẩm này lớn."],["需要を調べます。","Tìm hiểu nhu cầu."],["夏は水の需要が増えます。","Mùa hè nhu cầu nước tăng."]]},{"word":"新人","reading":"しんじん","meaning":"người mới, nhân viên mới","hanViet":"TÂN NHÂN","lesson":16,"ex":[["新人が会社に入りました。","Nhân viên mới đã vào công ty."],["新人を教えます。","Dạy nhân viên mới."],["新人はまだ仕事に慣れていません。","Nhân viên mới chưa quen việc."],["新人の歓迎会をします。","Tổ chức tiệc chào đón nhân viên mới."],["新人が3人入りました。","Có 3 nhân viên mới vào."]]},{"word":"挑戦（する）","reading":"ちょうせん（する）","meaning":"thử thách","hanViet":"KHIÊU CHIẾN","lesson":16,"ex":[["新しいことに挑戦します。","Thử thách với điều mới."],["彼はマラソンに挑戦しました。","Anh ấy đã thử thách marathon."],["挑戦することが大切です。","Việc thử thách rất quan trọng."],["日本語の試験に挑戦します。","Thử thách kỳ thi tiếng Nhật."],["難しい仕事に挑戦します。","Thử thách công việc khó."]]},{"word":"消費税","reading":"しょうひぜい","meaning":"thuế tiêu thụ","hanViet":"TIÊU PHI THUẾ","lesson":16,"ex":[["消費税は10パーセントです。","Thuế tiêu thụ là 10 phần trăm."],["消費税が上がりました。","Thuế tiêu thụ đã tăng."],["値段に消費税が入っています。","Giá đã bao gồm thuế tiêu thụ."],["消費税について、先生に聞きました。","Tôi đã hỏi thầy về thuế tiêu thụ."],["消費税が安い国もあります。","Cũng có nước thuế tiêu thụ rẻ."]]},{"word":"少子化","reading":"しょうしか","meaning":"tỉ lệ sinh giảm","hanViet":"THIỂU TỬ HÓA","lesson":16,"ex":[["日本の少子化が進んでいます。","Tỉ lệ sinh giảm ở Nhật đang tiến triển."],["少子化で、子どもが少なくなっています。","Vì tỉ lệ sinh giảm, trẻ em ít đi."],["少子化が問題になっています。","Tỉ lệ sinh giảm đang trở thành vấn đề."],["少子化について、テレビで見ました。","Tôi đã xem về tỉ lệ sinh giảm trên ti vi."],["少子化が進むと、学校の生徒が少なくなります。","Khi tỉ lệ sinh giảm, học sinh trong trường ít đi."]]},{"word":"備える","reading":"そなえる","meaning":"chuẩn bị","hanViet":"BỊ","lesson":16,"ex":[["地震に備えます。","Chuẩn bị cho động đất."],["冬に備えて、コートを買います。","Chuẩn bị cho mùa đông, tôi mua áo khoác."],["旅行に備えて、かばんを買います。","Chuẩn bị cho chuyến đi, tôi mua túi."],["台風に備えることが大切です。","Việc chuẩn bị cho bão rất quan trọng."],["試験に備えて、勉強します。","Chuẩn bị cho kỳ thi, tôi học."]]},{"word":"カリキュラム","reading":"","meaning":"chương trình giảng dạy","hanViet":"","lesson":16,"ex":[["学校のカリキュラムが変わります。","Chương trình giảng dạy của trường thay đổi."],["新しいカリキュラムが始まります。","Chương trình giảng dạy mới bắt đầu."],["カリキュラムを見直します。","Xem xét lại chương trình giảng dạy."],["カリキュラムについて、先生に聞きました。","Tôi đã hỏi thầy về chương trình giảng dạy."],["大学のカリキュラムは難しいです。","Chương trình giảng dạy của đại học khó."]]},{"word":"見直す","reading":"みなおす","meaning":"xem xét lại","hanViet":"KIẾN TRỰC","lesson":16,"ex":[["計画を見直します。","Xem xét lại kế hoạch."],["生活を見直しましょう。","Hãy xem xét lại lối sống."],["予算を見直します。","Xem xét lại ngân sách."],["彼は自分の生活を見直しました。","Anh ấy đã xem xét lại lối sống của mình."],["カリキュラムを見直す必要があります。","Cần xem xét lại chương trình giảng dạy."]]},{"word":"年末","reading":"ねんまつ","meaning":"cuối năm","hanViet":"NIÊN MẠT","lesson":16,"ex":[["年末に家を掃除します。","Cuối năm dọn nhà."],["年末は忙しいです。","Cuối năm bận rộn."],["年末に友達に会います。","Cuối năm gặp bạn."],["年末の休みが楽しみです。","Tôi mong chờ kỳ nghỉ cuối năm."],["年末までに仕事が終わります。","Công việc kết thúc trước cuối năm."]]},{"word":"時期","reading":"じき","meaning":"thời điểm","hanViet":"THỜI KỲ","lesson":16,"ex":[["今は旅行にいい時期です。","Bây giờ là thời điểm tốt để đi du lịch."],["桜の時期が来ました。","Thời điểm hoa anh đào đã đến."],["時期を待っています。","Tôi đang đợi thời điểm."],["この時期は雨が多いです。","Thời điểm này mưa nhiều."],["いい時期に来ましたね。","Bạn đến đúng lúc thật."]]},{"word":"予測（する）","reading":"よそく（する）","meaning":"dự đoán, dự báo","hanViet":"DỰ TRẮC","lesson":16,"ex":[["天気を予測します。","Dự báo thời tiết."],["明日の天気を予測します。","Dự báo thời tiết ngày mai."],["予測が正しいです。","Dự báo đúng."],["予測が外れました。","Dự báo sai."],["将来を予測することは難しいです。","Dự đoán tương lai rất khó."]]},{"word":"避難（する）","reading":"ひなん（する）","meaning":"lánh nạn","hanViet":"TỴ NAN","lesson":16,"ex":[["地震のとき、学校に避難します。","Khi động đất, lánh nạn ở trường."],["台風の前に避難します。","Lánh nạn trước bão."],["避難する場所を決めます。","Quyết định nơi lánh nạn."],["人々が避難しています。","Mọi người đang lánh nạn."],["避難の練習をします。","Luyện tập lánh nạn."]]},{"word":"予算","reading":"よさん","meaning":"dự toán, ngân sách","hanViet":"DỰ TOÁN","lesson":16,"ex":[["旅行の予算を決めます。","Quyết định ngân sách du lịch."],["予算が足りません。","Ngân sách không đủ."],["旅行の予算を見直します。","Xem xét lại ngân sách du lịch."],["予算の中で買い物をします。","Mua sắm trong ngân sách."],["予算は少ししかありません。","Ngân sách không nhiều."]]},{"word":"突然","reading":"とつぜん","meaning":"đột nhiên","hanViet":"ĐỘT NHIÊN","lesson":16,"ex":[["突然雨が降りました。","Đột nhiên trời mưa."],["突然電話が来ました。","Đột nhiên có điện thoại."],["突然ドアが開きました。","Đột nhiên cửa mở."],["彼は突然来ました。","Anh ấy đột nhiên đến."],["突然電気が消えました。","Đột nhiên điện tắt."]]},{"word":"訪問（する）","reading":"ほうもん（する）","meaning":"viếng thăm","hanViet":"PHỎNG VẤN","lesson":16,"ex":[["友達の家を訪問します。","Thăm nhà bạn."],["先生を訪問しました。","Tôi đã thăm thầy."],["京都を訪問します。","Thăm Kyoto."],["訪問する前に、電話をします。","Trước khi thăm, hãy gọi điện."],["彼は会社を訪問しました。","Anh ấy đã thăm công ty."]]},{"word":"歓迎（する）","reading":"かんげい（する）","meaning":"hoan nghênh, chào đón","hanViet":"HOAN NGHÊNH","lesson":16,"ex":[["新人を歓迎します。","Chào đón nhân viên mới."],["友達を歓迎します。","Chào đón bạn."],["歓迎会をします。","Tổ chức tiệc chào đón."],["先生を歓迎します。","Chào đón thầy."],["新しい学生を歓迎します。","Chào đón học sinh mới."]]},{"word":"決勝戦","reading":"けっしょうせん","meaning":"trận chung kết","hanViet":"QUYẾT THẮNG CHIẾN","lesson":16,"ex":[["決勝戦を見ます。","Xem trận chung kết."],["決勝戦は明日です。","Trận chung kết là ngày mai."],["決勝戦に出ます。","Ra sân trận chung kết."],["決勝戦が楽しみです。","Tôi mong chờ trận chung kết."],["決勝戦まで進みました。","Đã tiến tới trận chung kết."]]},{"word":"～戦","reading":"～せん","meaning":"trận ~","hanViet":"CHIẾN","lesson":16,"ex":[["第1戦は明日です。","Trận 1 là ngày mai."],["第2戦は来週です。","Trận 2 là tuần sau."],["第3戦を見に行きます。","Đi xem trận 3."],["決勝戦は一番大切な戦です。","Trận chung kết là trận quan trọng nhất."],["第4戦の前に、練習します。","Trước trận 4, hãy luyện tập."]]},{"word":"出場（する）","reading":"しゅつじょう（する）","meaning":"tham gia thi đấu, ra sân","hanViet":"XUẤT TRƯỜNG","lesson":16,"ex":[["決勝戦に出場します。","Tham gia trận chung kết."],["大会に出場します。","Tham gia giải đấu."],["彼は試合に出場しました。","Anh ấy đã tham gia trận đấu."],["出場する選手が多いです。","Có nhiều vận động viên tham gia."],["初めて大会に出場します。","Lần đầu tham gia giải đấu."]]},{"word":"上達（する）","reading":"じょうたつ（する）","meaning":"tiến bộ","hanViet":"THƯỢNG ĐẠT","lesson":16,"ex":[["日本語が上達しました。","Tiếng Nhật đã tiến bộ."],["水泳が上達しました。","Bơi đã tiến bộ."],["練習して、英語が上達します。","Luyện tập thì tiếng Anh tiến bộ."],["彼のピアノが上達しました。","Piano của anh ấy đã tiến bộ."],["上達が速いです。","Tiến bộ nhanh."]]},{"word":"高齢","reading":"こうれい","meaning":"cao tuổi","hanViet":"CAO LINH","lesson":16,"ex":[["高齢の人が増えています。","Người cao tuổi đang tăng."],["高齢の母を助けます。","Giúp mẹ cao tuổi."],["高齢の人のための病院です。","Bệnh viện dành cho người cao tuổi."],["高齢でも元気です。","Cao tuổi nhưng vẫn khỏe."],["高齢の住人が多い町です。","Thành phố có nhiều cư dân cao tuổi."]]},{"word":"当然","reading":"とうぜん","meaning":"đương nhiên","hanViet":"ĐƯƠNG NHIÊN","lesson":16,"ex":[["当然です。","Đương nhiên rồi."],["勉強すれば、当然上達します。","Học thì đương nhiên tiến bộ."],["当然知っています。","Đương nhiên tôi biết."],["当然のことです。","Đó là điều đương nhiên."],["彼は当然来ます。","Anh ấy đương nhiên sẽ đến."]]},{"word":"気配","reading":"けはい","meaning":"dấu hiệu, vẻ","hanViet":"KHÍ PHỐI","lesson":16,"ex":[["雨の気配がします。","Có dấu hiệu mưa."],["春の気配がします。","Có vẻ xuân."],["人の気配がします。","Có vẻ có người."],["秋の気配がします。","Có vẻ thu."],["気配がして、目が覚めました。","Cảm thấy có dấu hiệu nên tôi tỉnh giấc."]]},{"word":"長期","reading":"ちょうき","meaning":"dài hạn","hanViet":"TRƯỜNG KỲ","lesson":16,"ex":[["長期の旅行をします。","Đi du lịch dài hạn."],["長期の計画を作ります。","Lập kế hoạch dài hạn."],["長期に休みます。","Nghỉ dài hạn."],["長期の仕事です。","Công việc dài hạn."],["長期で東京に住みます。","Sống dài hạn ở Tokyo."]]},{"word":"追う","reading":"おう","meaning":"đuổi bắt","hanViet":"TRUY","lesson":16,"ex":[["犬が猫を追います。","Chó đuổi mèo."],["警察が泥棒を追います。","Cảnh sát đuổi kẻ trộm."],["夢を追います。","Đuổi theo ước mơ."],["彼はバスを追いました。","Anh ấy đuổi theo xe buýt."],["子どもがボールを追います。","Trẻ con đuổi theo bóng."]]},{"word":"住人","reading":"じゅうにん","meaning":"cư dân (người sống trong nhà/chung cư/khu vực)","hanViet":"TRÚ NHÂN","lesson":16,"ex":[["アパートの住人が集まりました。","Cư dân chung cư đã tập hợp."],["住人に声をかけます。","Gọi cư dân."],["マンションの住人が多いです。","Chung cư có nhiều cư dân."],["住人と話します。","Nói chuyện với cư dân."],["新しい住人が来ました。","Cư dân mới đã đến."]]},{"word":"呼びかける","reading":"よびかける","meaning":"kêu gọi","hanViet":"HÔ","lesson":16,"ex":[["先生が生徒に呼びかけます。","Thầy kêu gọi học sinh."],["みんなに助けるように呼びかけます。","Kêu gọi mọi người giúp đỡ."],["住人に呼びかけます。","Kêu gọi cư dân."],["彼は友達に呼びかけました。","Anh ấy đã gọi bạn."],["みんなに気をつけるように呼びかけます。","Kêu gọi mọi người cẩn thận."]]},{"word":"立ち上げる","reading":"たちあげる","meaning":"lập nên","hanViet":"LẬP THƯỢNG","lesson":16,"ex":[["新しい会社を立ち上げます。","Lập công ty mới."],["プロジェクトを立ち上げます。","Khởi động dự án."],["彼は店を立ち上げました。","Anh ấy đã mở cửa hàng."],["新しいチームを立ち上げます。","Lập đội mới."],["計画を立ち上げます。","Khởi động kế hoạch."]]},{"word":"高速道路","reading":"こうそくどうろ","meaning":"đường cao tốc","hanViet":"CAO TỐC ĐẠO LỘ","lesson":16,"ex":[["高速道路を運転します。","Lái xe trên đường cao tốc."],["高速道路で東京へ行きます。","Đi Tokyo bằng đường cao tốc."],["高速道路は便利です。","Đường cao tốc tiện lợi."],["高速道路は車が多いです。","Đường cao tốc nhiều xe."],["高速道路の料金が高いです。","Phí đường cao tốc cao."]]},{"word":"無料化","reading":"むりょうか","meaning":"miễn thu phí","hanViet":"VÔ LIỆU HÓA","lesson":16,"ex":[["高速道路の無料化が進んでいます。","Việc miễn phí đường cao tốc đang tiến triển."],["授業料の無料化が話題です。","Việc miễn học phí đang được bàn tán."],["バスの無料化を考えます。","Cân nhắc việc miễn phí xe buýt."],["無料化で、人が増えます。","Miễn phí thì người tăng."],["図書館の無料化は来年からです。","Việc miễn phí thư viện bắt đầu từ năm sau."]]},{"word":"引き下げる","reading":"ひきさげる","meaning":"hạ xuống, giảm","hanViet":"DẪN HẠ","lesson":16,"ex":[["この店は来月、野菜の値段を引き下げます。","Cửa hàng này sẽ giảm giá rau vào tháng sau."],["会社は電気料金を引き下げました。","Công ty đã giảm tiền điện."],["田中さんは店の商品の値段を引き下げました。","Anh Tanaka đã giảm giá hàng hóa của cửa hàng."],["学校は来年、学費を引き下げます。","Trường sẽ giảm học phí vào năm sau."],["この店は服の値段を引き下げました。","Cửa hàng này đã giảm giá quần áo."]]},{"word":"オリンピック","reading":"","meaning":"Olympic","hanViet":"","lesson":16,"ex":[["オリンピックは東京で開かれました。","Olympic đã được tổ chức ở Tokyo."],["私はオリンピックの試合を見ました。","Tôi đã xem trận đấu Olympic."],["オリンピックの選手は毎日練習します。","Các vận động viên Olympic luyện tập mỗi ngày."],["田中さんはオリンピックに出たいです。","Anh Tanaka muốn tham dự Olympic."],["オリンピックは世界中の人が見ます。","Mọi người trên khắp thế giới đều xem Olympic."]]},{"word":"出場権","reading":"しゅつじょうけん","meaning":"quyền thi đấu, suất tham gia thi đấu","hanViet":"XUẤT TRƯỜNG QUYỀN","lesson":16,"ex":[["田中選手はオリンピックの出場権を手にしました。","Vận động viên Tanaka đã giành được suất tham dự Olympic."],["チームは大会の出場権を取りました。","Đội đã giành được suất tham dự giải đấu."],["山田さんは出場権を手にするために、毎日練習しました。","Để giành suất thi đấu, anh Yamada đã luyện tập mỗi ngày."],["出場権は試合に勝った人がもらえます。","Suất thi đấu thuộc về người thắng trận."],["私は出場権を手にするのが夢です。","Giành được suất thi đấu là ước mơ của tôi."]]},{"word":"～権","reading":"～けん","meaning":"quyền","hanViet":"QUYỀN","lesson":16,"ex":[["人権は大切です。","Nhân quyền rất quan trọng."],["新政権ができました。","Chính quyền mới đã được thành lập."],["世界選手権大会を見ました。","Tôi đã xem giải vô địch thế giới."],["出場権を手にしました。","Tôi đã giành được suất thi đấu."],["権力者の話を聞きました。","Tôi đã nghe người nắm quyền lực nói chuyện."]]},{"word":"手にする","reading":"てにする","meaning":"có được, giành được","hanViet":"THỦ","lesson":16,"ex":[["田中さんは大会で金メダルを手にしました。","Anh Tanaka đã giành huy chương vàng ở giải đấu."],["山田さんは仕事でいい結果を手にしました。","Anh Yamada đã đạt được kết quả tốt trong công việc."],["私は初めて自分の家を手にしました。","Tôi đã có được ngôi nhà của riêng mình lần đầu tiên."],["チームは試合に勝って、メダルを手にしました。","Đội đã thắng trận và giành được huy chương."],["田中さんは新しい仕事を手にしました。","Anh Tanaka đã có được công việc mới."]]},{"word":"身分証明書","reading":"みぶんしょうめいしょ","meaning":"giấy chứng minh nhân dân","hanViet":"THÂN PHÂN CHỨNG MINH THƯ","lesson":16,"ex":[["銀行で新しいカードを作るとき、身分証明書が必要です。","Khi làm thẻ mới ở ngân hàng, cần giấy chứng minh nhân dân."],["身分証明書を見せてください。","Hãy xuất trình giấy chứng minh nhân dân."],["私は身分証明書を家に忘れました。","Tôi đã để quên giấy chứng minh nhân dân ở nhà."],["ホテルで身分証明書を見せました。","Tôi đã xuất trình giấy chứng minh nhân dân ở khách sạn."],["身分証明書は大切にしてください。","Hãy giữ gìn cẩn thận giấy chứng minh nhân dân."]]},{"word":"身分","reading":"みぶん","meaning":"thân phận, thân thế","hanViet":"THÂN PHÂN","lesson":16,"ex":[["昔は身分で仕事が違いました。","Ngày xưa, công việc khác nhau theo thân phận."],["身分がわかるカードを見せました。","Tôi đã xuất trình thẻ cho biết thân phận."],["彼は身分を言わないで働きました。","Anh ấy đã làm việc mà không nói thân phận."],["身分証明書は大切なものです。","Giấy chứng minh nhân dân là thứ quan trọng."],["新しい身分証明書を作りました。","Tôi đã làm giấy chứng minh nhân dân mới."]]},{"word":"証明書","reading":"しょうめいしょ","meaning":"giấy chứng minh, giấy chứng nhận","hanViet":"CHỨNG MINH THƯ","lesson":16,"ex":[["学校で証明書をもらいました。","Tôi đã nhận giấy chứng nhận ở trường."],["証明書を提出してください。","Hãy nộp giấy chứng nhận."],["病院で証明書を書いてもらいました。","Tôi đã nhờ bệnh viện viết giấy chứng nhận."],["この証明書は来月まで使えます。","Giấy chứng nhận này dùng được đến tháng sau."],["証明書をなくしました。","Tôi đã làm mất giấy chứng nhận."]]},{"word":"不要（な）","reading":"ふよう（な）","meaning":"không cần thiết","hanViet":"BẤT YẾU","lesson":16,"ex":[["この本はもう不要です。","Cuốn sách này không còn cần thiết nữa."],["不要なものは捨ててください。","Hãy vứt những thứ không cần thiết đi."],["予約は不要です。","Không cần đặt trước."],["不要なものは部屋に置かないでください。","Đừng để những thứ không cần thiết trong phòng."],["この書類は不要になりました。","Tài liệu này đã trở nên không cần thiết."]]},{"word":"問い合わせる","reading":"といあわせる","meaning":"hỏi, liên hệ hỏi","hanViet":"VẤN HỢP","lesson":16,"ex":[["会社に電話で問い合わせました。","Tôi đã gọi điện hỏi công ty."],["わからないことがあったら、先生に問い合わせてください。","Nếu có điều gì không hiểu, hãy hỏi thầy."],["ホテルに部屋について問い合わせました。","Tôi đã hỏi khách sạn về phòng."],["メールで問い合わせることができます。","Bạn có thể hỏi qua email."],["田中さんは料金について問い合わせました。","Anh Tanaka đã hỏi về phí."]]},{"word":"ネット","reading":"","meaning":"Internet","hanViet":"","lesson":16,"ex":[["ネットで本を買いました。","Tôi đã mua sách trên mạng."],["ネットで映画を見ます。","Tôi xem phim trên mạng."],["ネットでニュースを読みました。","Tôi đã đọc tin tức trên mạng."],["ネットが使えなくなりました。","Mạng đã không dùng được nữa."],["子どもはネットで勉強します。","Trẻ em học trên mạng."]]},{"word":"満席","reading":"まんせき","meaning":"kín chỗ, hết chỗ","hanViet":"MÃN TỊCH","lesson":16,"ex":[["映画館は満席でした。","Rạp chiếu phim đã kín chỗ."],["レストランは満席だったので、別の店に行きました。","Nhà hàng đã hết chỗ nên tôi đã đi quán khác."],["電車は満席で、座れませんでした。","Tàu đã kín chỗ nên tôi không ngồi được."],["コンサートは満席になりました。","Buổi hòa nhạc đã kín chỗ."],["満席の飛行機に乗りました。","Tôi đã lên máy bay kín chỗ."]]},{"word":"提出（する）","reading":"ていしゅつ（する）","meaning":"nộp","hanViet":"ĐỀ XUẤT","lesson":16,"ex":[["宿題を先生に提出しました。","Tôi đã nộp bài tập về nhà cho thầy."],["書類は来週までに提出してください。","Hãy nộp tài liệu trước tuần sau."],["レポートを提出しました。","Tôi đã nộp báo cáo."],["会社に証明書を提出しなければなりません。","Tôi phải nộp giấy chứng nhận cho công ty."],["田中さんは宿題を提出しませんでした。","Anh Tanaka đã không nộp bài tập."]]},{"word":"電気料金","reading":"でんきりょうきん","meaning":"tiền điện","hanViet":"ĐIỆN KHÍ LIỆU KIM","lesson":16,"ex":[["電気料金は毎月払います。","Tiền điện trả mỗi tháng."],["夏は電気料金が高くなります。","Mùa hè tiền điện tăng cao."],["電気料金を安くしたいです。","Tôi muốn tiền điện rẻ hơn."],["電気料金が上がりました。","Tiền điện đã tăng."],["電気料金の支払いは銀行でできます。","Có thể trả tiền điện ở ngân hàng."]]},{"word":"～料金","reading":"～りょうきん","meaning":"phí ~","hanViet":"LIỆU KIM","lesson":16,"ex":[["料金は毎月払います。","Tôi trả phí mỗi tháng."],["料金が高くなりました。","Phí đã tăng cao."],["料金は来月払います。","Tôi sẽ trả phí tháng sau."],["電気料金は安いです。","Tiền điện rẻ."],["料金はあとで払います。","Tôi sẽ trả phí sau."]]},{"word":"思わず","reading":"おもわず","meaning":"bất giác, bất chợt","hanViet":"TƯ","lesson":16,"ex":[["思わず笑ってしまいました。","Tôi đã bất giác bật cười."],["思わず大きな声を出しました。","Tôi đã bất giác kêu lên."],["きれいな花を見て、思わず写真を撮りました。","Thấy hoa đẹp, tôi đã bất giác chụp ảnh."],["思わず泣いてしまいました。","Tôi đã bất giác khóc."],["思わず大きな声で笑いました。","Tôi đã bất giác cười lớn."]]},{"word":"燃え移る","reading":"もえうつる","meaning":"cháy lan sang","hanViet":"NHIÊN DI","lesson":16,"ex":[["火が隣の家に燃え移りました。","Lửa đã cháy lan sang nhà bên cạnh."],["火事で火が木に燃え移りました。","Trong vụ hỏa hoạn, lửa đã cháy lan sang cây."],["風で火が山に燃え移りました。","Gió làm lửa cháy lan sang núi."],["火が隣の車に燃え移る前に、消しました。","Trước khi lửa cháy lan sang xe bên cạnh, tôi đã dập tắt."],["火が服に燃え移りました。","Lửa đã cháy lan sang quần áo."]]},{"word":"左手","reading":"ひだりて","meaning":"tay trái","hanViet":"TẢ THỦ","lesson":16,"ex":[["左手で字を書きます。","Tôi viết chữ bằng tay trái."],["左手を上げてください。","Hãy giơ tay trái lên."],["左手に時計をしています。","Tôi đeo đồng hồ ở tay trái."],["左手が疲れました。","Tay trái của tôi đã mỏi."],["左手でボールを取りました。","Tôi đã bắt bóng bằng tay trái."]]},{"word":"すとんと～","reading":"","meaning":"(rơi) thẳng xuống","hanViet":"","lesson":16,"ex":[["荷物がすとんと落ちました。","Hành lý đã rơi thẳng xuống."],["ボールがすとんと地面に落ちました。","Quả bóng đã rơi thẳng xuống đất."],["本がすとんと机の上に落ちました。","Cuốn sách đã rơi thẳng xuống bàn."],["りんごがすとんと落ちました。","Quả táo đã rơi thẳng xuống."],["かばんがすとんと床に落ちました。","Cặp đã rơi thẳng xuống sàn."]]},{"word":"必死（に）","reading":"ひっし（に）","meaning":"quyết tâm, hết sức","hanViet":"TẤT TỬ","lesson":16,"ex":[["必死に勉強しました。","Tôi đã học hết sức."],["必死に走りました。","Tôi đã chạy hết sức."],["田中さんは必死に働きました。","Anh Tanaka đã làm việc hết sức."],["試験に合格するために、必死に勉強しました。","Để đỗ kỳ thi, tôi đã học hết sức."],["必死に歌を練習しました。","Tôi đã luyện hát hết sức."]]},{"word":"ひっぱり上げる","reading":"ひっぱりあげる","meaning":"kéo mạnh lên","hanViet":"THƯỢNG","lesson":16,"ex":[["ひもで荷物をひっぱり上げました。","Tôi đã dùng dây kéo mạnh hành lý lên."],["田中さんは子どもをひっぱり上げました。","Anh Tanaka đã kéo mạnh đứa trẻ lên."],["山田さんは友達の手をひっぱり上げました。","Anh Yamada đã kéo mạnh tay bạn lên."],["田中さんは子どもの手をひっぱり上げました。","Anh Tanaka đã kéo mạnh tay đứa trẻ lên."],["ひもをひっぱり上げてください。","Hãy kéo mạnh sợi dây lên."]]},{"word":"無事","reading":"ぶじ","meaning":"an toàn, vô sự","hanViet":"VÔ SỰ","lesson":16,"ex":[["無事に家に着きました。","Tôi đã về nhà an toàn."],["旅行は無事に終わりました。","Chuyến du lịch đã kết thúc an toàn."],["子どもは無事でした。","Đứa trẻ đã an toàn."],["荷物は無事に届きました。","Hành lý đã đến an toàn."],["無事に帰ってきました。","Tôi đã trở về an toàn."]]},{"word":"引き上げる","reading":"ひきあげる","meaning":"kéo nâng lên","hanViet":"DẪN THƯỢNG","lesson":16,"ex":[["ひもで荷物を引き上げました。","Tôi đã dùng dây kéo hành lý lên."],["値段を引き上げました。","Tôi đã nâng giá lên."],["田中さんは子どもを引き上げました。","Anh Tanaka đã kéo đứa trẻ lên."],["先生はカーテンを引き上げました。","Thầy đã kéo rèm lên."],["ひもを引き上げてください。","Hãy kéo sợi dây lên."]]},{"word":"きょとんと～","reading":"","meaning":"ngơ ngác","hanViet":"","lesson":16,"ex":[["田中さんはきょとんと私を見ました。","Anh Tanaka đã nhìn tôi ngơ ngác."],["子どもはきょとんとしています。","Đứa trẻ đang ngơ ngác."],["質問を聞いて、きょとんとしました。","Nghe câu hỏi, tôi đã ngơ ngác."],["山田さんはきょとんとして答えられませんでした。","Anh Yamada ngơ ngác nên không trả lời được."],["きょとんとした顔をしていました。","Anh ấy có vẻ mặt ngơ ngác."]]},{"word":"たった","reading":"","meaning":"chỉ, vỏn vẹn","hanViet":"","lesson":16,"ex":[["たった一人で旅行しました。","Tôi đã đi du lịch chỉ một mình."],["たった二つしかありません。","Chỉ có hai cái."],["たった一日で終わりました。","Chỉ một ngày đã xong."],["たった一人で山に登りました。","Tôi đã leo núi chỉ một mình."],["たった一月で日本語が上手になりました。","Chỉ một tháng, tiếng Nhật đã giỏi lên."]]},{"word":"占い","reading":"うらない","meaning":"bói","hanViet":"CHIẾM","lesson":16,"ex":[["占いを見ました。","Tôi đã xem bói."],["占いで明日はいい日だと言われました。","Bói nói ngày mai là ngày tốt."],["占いを信じますか。","Bạn có tin bói toán không."],["占いの本を買いました。","Tôi đã mua sách bói toán."],["田中さんは占いが好きです。","Anh Tanaka thích bói toán."]]},{"word":"リストラ（する）","reading":"","meaning":"tái cơ cấu","hanViet":"","lesson":16,"ex":[["会社はリストラをしました。","Công ty đã tái cơ cấu."],["リストラで仕事を失いました。","Tôi đã mất việc vì tái cơ cấu."],["会社がリストラをすると聞きました。","Tôi nghe nói công ty sẽ tái cơ cấu."],["リストラのニュースを見ました。","Tôi đã xem tin tức về tái cơ cấu."],["田中さんはリストラで会社をやめました。","Anh Tanaka đã nghỉ công ty vì tái cơ cấu."]]},{"word":"契約社員","reading":"けいやくしゃいん","meaning":"nhân viên hợp đồng","hanViet":"KHẾ ƯỚC XÃ VIÊN","lesson":16,"ex":[["田中さんは契約社員です。","Anh Tanaka là nhân viên hợp đồng."],["私は契約社員で働いています。","Tôi đang làm việc với tư cách nhân viên hợp đồng."],["契約社員の給料は安いです。","Lương nhân viên hợp đồng thấp."],["契約社員は来月まで働きます。","Nhân viên hợp đồng làm việc đến tháng sau."],["契約社員の仕事は忙しいです。","Công việc của nhân viên hợp đồng rất bận."]]},{"word":"安定（する）","reading":"あんてい（する）","meaning":"ổn định, vững chắc","hanViet":"AN ĐỊNH","lesson":16,"ex":[["生活が安定しました。","Cuộc sống đã ổn định."],["仕事が安定しています。","Công việc đang ổn định."],["収入が安定しました。","Thu nhập đã ổn định."],["安定した仕事がほしいです。","Tôi muốn công việc ổn định."],["経済が安定しました。","Kinh tế đã ổn định."]]},{"word":"まさか","reading":"","meaning":"chẳng lẽ là, lẽ nào lại là","hanViet":"","lesson":16,"ex":[["まさか、田中さんが来るとは思いませんでした。","Không ngờ anh Tanaka lại đến."],["まさか雪が降るとは思いませんでした。","Không ngờ tuyết lại rơi."],["まさか合格するとは思いませんでした。","Không ngờ lại đỗ."],["まさか雨が降るとは思いませんでした。","Không ngờ mưa lại rơi."],["まさか田中さんが結婚するとは思いませんでした。","Không ngờ anh Tanaka lại kết hôn."]]},{"word":"気分転換","reading":"きぶんてんかん","meaning":"thay đổi không khí","hanViet":"KHÍ PHÂN CHUYỂN HOÁN","lesson":16,"ex":[["気分転換に公園に行きました。","Tôi đã đi công viên để thay đổi không khí."],["気分転換に映画を見ました。","Tôi đã xem phim để thay đổi không khí."],["気分転換が必要です。","Cần thay đổi không khí."],["気分転換に旅行に行きました。","Tôi đã đi du lịch để thay đổi không khí."],["気分転換に音楽を聞きました。","Tôi đã nghe nhạc để thay đổi không khí."]]},{"word":"チャンス","reading":"","meaning":"cơ hội","hanViet":"","lesson":16,"ex":[["チャンスが来ました。","Cơ hội đã đến."],["チャンスが来るのを待っています。","Tôi đang đợi cơ hội đến."],["いいチャンスです。","Đây là cơ hội tốt."],["チャンスをください。","Hãy cho tôi cơ hội."],["チャンスを大切にしてください。","Hãy trân trọng cơ hội."]]},{"word":"ウェブサイト","reading":"","meaning":"trang web","hanViet":"","lesson":16,"ex":[["ウェブサイトを見ました。","Tôi đã xem trang web."],["会社のウェブサイトで調べました。","Tôi đã tra cứu trên trang web của công ty."],["ウェブサイトで写真を見ました。","Tôi đã xem ảnh trên trang web."],["このウェブサイトは便利です。","Trang web này tiện lợi."],["ウェブサイトで予約しました。","Tôi đã đặt trước trên trang web."]]},{"word":"不正使用","reading":"ふせいしよう","meaning":"sử dụng trái phép","hanViet":"BẤT CHÍNH SỬ DỤNG","lesson":16,"ex":[["カードの不正使用がありました。","Đã có việc sử dụng trái phép thẻ."],["不正使用をなくすために、パスワードを変えました。","Để không còn việc sử dụng trái phép, tôi đã đổi mật khẩu."],["不正使用が見つかりました。","Đã phát hiện việc sử dụng trái phép."],["不正使用はよくありません。","Sử dụng trái phép là không tốt."],["銀行は不正使用を調べています。","Ngân hàng đang điều tra việc sử dụng trái phép."]]},{"word":"被害額","reading":"ひがいがく","meaning":"số tiền thiệt hại","hanViet":"BỊ HẠI NGẠCH","lesson":16,"ex":[["被害額は大きいです。","Số tiền thiệt hại lớn."],["被害額が大きくなりました。","Số tiền thiệt hại đã lớn lên."],["被害額を調べています。","Tôi đang điều tra số tiền thiệt hại."],["被害額は去年より多くなりました。","Số tiền thiệt hại đã nhiều hơn năm ngoái."],["被害額はまだわかりません。","Chưa biết số tiền thiệt hại."]]},{"word":"額（被害～）","reading":"がく（ひがい～）","meaning":"số tiền (thiệt hại)","hanViet":"NGẠCH BỊ HẠI","lesson":16,"ex":[["被害の額は大きいです。","Số tiền thiệt hại lớn."],["被害の額が大きくなりました。","Số tiền thiệt hại đã lớn lên."],["被害の額を調べています。","Tôi đang điều tra số tiền thiệt hại."],["被害の額はまだわかりません。","Chưa biết số tiền thiệt hại."],["被害の額は去年より少なくなりました。","Số tiền thiệt hại đã ít hơn năm ngoái."]]},{"word":"当たり（一人～）","reading":"あたり（ひとり～）","meaning":"mỗi (người)","hanViet":"ĐƯƠNG NHẤT NHÂN","lesson":16,"ex":[["一人当たりの値段を教えてください。","Hãy cho tôi biết giá mỗi người."],["一人当たりの料金はいくらですか。","Phí mỗi người là bao nhiêu."],["一人当たり一つください。","Mỗi người cho tôi một cái."],["一人当たりの時間は短いです。","Thời gian mỗi người ngắn."],["一人当たり二つもらいました。","Mỗi người đã nhận hai cái."]]},{"word":"金銭","reading":"きんせん","meaning":"tiền bạc","hanViet":"KIM TIỀN","lesson":16,"ex":[["金銭のトラブルがありました。","Đã có rắc rối về tiền bạc."],["金銭を大切にしてください。","Hãy coi trọng tiền bạc."],["金銭の問題は難しいです。","Vấn đề tiền bạc rất khó."],["金銭を失いました。","Tôi đã mất tiền bạc."],["金銭のことは友達に相談しました。","Tôi đã trao đổi với bạn về chuyện tiền bạc."]]},{"word":"失う","reading":"うしなう","meaning":"làm mất","hanViet":"THẤT","lesson":16,"ex":[["仕事を失いました。","Tôi đã mất việc."],["財布を失いました。","Tôi đã làm mất ví."],["自信を失いました。","Tôi đã mất tự tin."],["友達を失いました。","Tôi đã mất bạn."],["チャンスを失いました。","Tôi đã bỏ lỡ cơ hội."]]},{"word":"在住（する）","reading":"ざいじゅう（する）","meaning":"sống tại","hanViet":"TẠI TRÚ","lesson":16,"ex":[["田中さんは東京に在住しています。","Anh Tanaka đang sống tại Tokyo."],["私は京都に在住しています。","Tôi đang sống tại Kyoto."],["山田さんは大阪に在住しています。","Anh Yamada đang sống tại Osaka."],["日本に在住する人が増えています。","Số người sống tại Nhật đang tăng lên."],["田中さんは長く東京に在住しています。","Anh Tanaka đã sống tại Tokyo lâu rồi."]]},{"word":"フリーメール","reading":"","meaning":"e-mail miễn phí","hanViet":"","lesson":16,"ex":[["フリーメールを使っています。","Tôi đang dùng email miễn phí."],["フリーメールで友達に連絡しました。","Tôi đã liên lạc với bạn bằng email miễn phí."],["フリーメールのアドレスを教えてください。","Hãy cho tôi biết địa chỉ email miễn phí."],["フリーメールを作りました。","Tôi đã tạo email miễn phí."],["フリーメールにメールが来ました。","Email đã đến hộp thư miễn phí."]]},{"word":"不明","reading":"ふめい","meaning":"không rõ, chưa biết","hanViet":"BẤT MINH","lesson":16,"ex":[["原因は不明です。","Nguyên nhân chưa rõ."],["住所不明の手紙が来ました。","Đã có thư gửi đến địa chỉ không rõ."],["名前は不明です。","Tên chưa rõ."],["理由は不明です。","Lý do chưa rõ."],["場所は不明です。","Địa điểm chưa rõ."]]},{"word":"送信（する）","reading":"そうしん（する）","meaning":"gửi","hanViet":"TỐNG TÍN","lesson":16,"ex":[["メールを送信しました。","Tôi đã gửi email."],["メールを送信してください。","Hãy gửi email."],["送信ボタンを押しました。","Tôi đã bấm nút gửi."],["写真を送信しました。","Tôi đã gửi ảnh."],["メールが送信できませんでした。","Email đã không gửi được."]]},{"word":"創作（する）","reading":"そうさく（する）","meaning":"sáng tác","hanViet":"SÁNG TÁC","lesson":16,"ex":[["小説を創作しました。","Tôi đã sáng tác tiểu thuyết."],["歌を創作しました。","Tôi đã sáng tác bài hát."],["創作活動をしています。","Tôi đang hoạt động sáng tác."],["田中さんは物語を創作しました。","Anh Tanaka đã sáng tác câu chuyện."],["創作するのが好きです。","Tôi thích sáng tác."]]},{"word":"築く","reading":"きずく","meaning":"xây dựng","hanViet":"TRÚC","lesson":16,"ex":[["家を築きました。","Tôi đã xây nhà."],["田中さんは新しい家を築きました。","Anh Tanaka đã xây nhà mới."],["友達と関係を築きました。","Tôi đã xây dựng quan hệ với bạn bè."],["田中さんは会社を築きました。","Anh Tanaka đã xây dựng công ty."],["幸せな家庭を築きたいです。","Tôi muốn xây dựng gia đình hạnh phúc."]]},{"word":"強盗","reading":"ごうとう","meaning":"kẻ cướp","hanViet":"CƯỜNG ĐẠO","lesson":16,"ex":[["強盗が銀行に入りました。","Kẻ cướp đã vào ngân hàng."],["強盗に財布を取られました。","Tôi đã bị kẻ cướp lấy mất ví."],["強盗が捕まりました。","Kẻ cướp đã bị bắt."],["強盗のニュースを見ました。","Tôi đã xem tin tức về kẻ cướp."],["強盗から逃げました。","Tôi đã chạy trốn khỏi kẻ cướp."]]},{"word":"出国（する）","reading":"しゅっこく（する）","meaning":"rời khỏi đất nước","hanViet":"XUẤT QUỐC","lesson":16,"ex":[["来月、出国します。","Tháng sau tôi sẽ rời khỏi đất nước."],["出国するとき、パスポートが必要です。","Khi xuất cảnh, cần hộ chiếu."],["田中さんは出国しました。","Anh Tanaka đã xuất cảnh."],["出国の日は来月です。","Ngày xuất cảnh là tháng sau."],["出国前に本を買いました。","Tôi đã mua sách trước khi xuất cảnh."]]},{"word":"宛て（友人～）","reading":"あて（ゆうじん～）","meaning":"địa chỉ đến (bạn thân)","hanViet":"UYỂN HỮU NHÂN","lesson":16,"ex":[["友人宛ての手紙を書きました。","Tôi đã viết thư gửi bạn thân."],["友人宛ての荷物が届きました。","Hành lý gửi bạn thân đã đến."],["友人宛てのメールを送りました。","Tôi đã gửi email cho bạn thân."],["この手紙は友人宛てです。","Bức thư này gửi cho bạn thân."],["友人宛てのプレゼントを買いました。","Tôi đã mua quà gửi bạn thân."]]},{"word":"帳（アドレス～）","reading":"ちょう","meaning":"sổ ghi (địa chỉ)","hanViet":"TRƯỚNG","lesson":16,"ex":[["アドレス帳に友達の番号を書きました。","Tôi đã viết số của bạn vào sổ địa chỉ."],["アドレス帳を見ました。","Tôi đã xem sổ địa chỉ."],["アドレス帳をなくしました。","Tôi đã làm mất sổ địa chỉ."],["アドレス帳に新しい住所を書きました。","Tôi đã viết địa chỉ mới vào sổ địa chỉ."],["アドレス帳を忘れました。","Tôi đã quên sổ địa chỉ."]]},{"word":"売買","reading":"ばいばい","meaning":"mua bán","hanViet":"MẠI MÃI","lesson":16,"ex":[["車の売買をしました。","Tôi đã mua bán xe."],["土地の売買は難しいです。","Mua bán đất đai rất khó."],["売買の話を聞きました。","Tôi đã nghe câu chuyện về mua bán."],["売買でお金をもらいました。","Tôi đã nhận tiền từ mua bán."],["売買の本を読みました。","Tôi đã đọc sách về mua bán."]]},{"word":"大量","reading":"たいりょう","meaning":"số lượng lớn","hanViet":"ĐẠI LƯỢNG","lesson":16,"ex":[["大量の水を飲みました。","Tôi đã uống lượng lớn nước."],["大量の本を買いました。","Tôi đã mua số lượng lớn sách."],["大量の荷物が届きました。","Số lượng lớn hành lý đã đến."],["大量の野菜を食べました。","Tôi đã ăn lượng lớn rau."],["大量の雨が降りました。","Mưa lớn đã rơi."]]},{"word":"捕まる","reading":"つかまる","meaning":"bị bắt","hanViet":"BỔ","lesson":16,"ex":[["泥棒が捕まりました。","Kẻ trộm đã bị bắt."],["魚が網に捕まりました。","Cá đã bị mắc lưới."],["田中さんは警察に捕まりました。","Anh Tanaka đã bị cảnh sát bắt."],["子どもは木に捕まりました。","Đứa trẻ đã bám vào cây."],["ボールが木に捕まりました。","Quả bóng đã mắc trên cây."]]},{"word":"暦","reading":"こよみ","meaning":"lịch","hanViet":"LỊCH","lesson":17,"ex":[["暦を見ました。","Tôi đã xem lịch."],["日本の暦は古いです。","Lịch của Nhật rất cổ."],["暦で日曜日を調べました。","Tôi đã tra ngày chủ nhật trên lịch."],["暦を見ると、明日は休みです。","Xem lịch thì ngày mai là ngày nghỉ."],["暦は毎月変わります。","Lịch thay đổi mỗi tháng."]]},{"word":"お兄ちゃん","reading":"おにいちゃん","meaning":"anh trai","hanViet":"HUYNH","lesson":17,"ex":[["お兄ちゃんがいます。","Tôi có anh trai."],["お兄ちゃんと遊びました。","Tôi đã chơi với anh trai."],["お兄ちゃんは学生です。","Anh trai là học sinh."],["お兄ちゃんに本をもらいました。","Tôi đã nhận sách từ anh trai."],["お兄ちゃんはサッカーが上手です。","Anh trai giỏi bóng đá."]]},{"word":"呼称","reading":"こしょう","meaning":"cách xưng hô","hanViet":"HÔ XƯNG, XỨNG","lesson":17,"ex":[["日本の呼称は難しいです。","Cách xưng hô của Nhật rất khó."],["呼称を勉強しました。","Tôi đã học cách xưng hô."],["先生の呼称は「先生」です。","Cách xưng hô với thầy là \"thầy\"."],["呼称の意味を学びました。","Tôi đã học nghĩa của cách xưng hô."],["国によって呼称が違います。","Cách xưng hô khác nhau theo từng nước."]]},{"word":"スタイル","reading":"","meaning":"kiểu, cách, phong cách","hanViet":"","lesson":17,"ex":[["新しいスタイルの服を買いました。","Tôi đã mua quần áo phong cách mới."],["田中さんのスタイルはいいです。","Phong cách của anh Tanaka rất tốt."],["スタイルを変えました。","Tôi đã đổi phong cách."],["日本のスタイルが好きです。","Tôi thích phong cách Nhật."],["髪のスタイルを変えました。","Tôi đã đổi kiểu tóc."]]},{"word":"太陽暦","reading":"たいようれき","meaning":"dương lịch","hanViet":"THÁI DƯƠNG LỊCH","lesson":17,"ex":[["太陽暦は今のカレンダーです。","Dương lịch là lịch hiện nay."],["日本は太陽暦を使っています。","Nhật đang dùng dương lịch."],["太陽暦は世界で使われています。","Dương lịch được dùng trên khắp thế giới."],["太陽暦と太陰暦は違います。","Dương lịch và âm lịch khác nhau."],["太陽暦を勉強しました。","Tôi đã học dương lịch."]]},{"word":"太陰暦","reading":"たいいんれき","meaning":"âm lịch","hanViet":"THÁI ÂM LỊCH","lesson":17,"ex":[["太陰暦は月を見て作られました。","Âm lịch được tạo ra bằng cách quan sát mặt trăng."],["昔、日本は太陰暦を使っていました。","Ngày xưa, Nhật đã dùng âm lịch."],["太陰暦では月が大切です。","Trong âm lịch, mặt trăng rất quan trọng."],["太陰暦を勉強しました。","Tôi đã học âm lịch."],["太陰暦と太陽暦は違います。","Âm lịch và dương lịch khác nhau."]]},{"word":"太陰太陽暦","reading":"たいいんたいようれき","meaning":"lịch âm dương","hanViet":"THÁI ÂM THÁI DƯƠNG LỊCH","lesson":17,"ex":[["太陰太陽暦は月と太陽を使います。","Lịch âm dương dùng cả mặt trăng và mặt trời."],["日本は昔、太陰太陽暦を使っていました。","Ngày xưa, Nhật đã dùng lịch âm dương."],["太陰太陽暦は複雑です。","Lịch âm dương rất phức tạp."],["太陰太陽暦を勉強しました。","Tôi đã học lịch âm dương."],["太陰太陽暦は今も使われています。","Lịch âm dương hiện vẫn được dùng."]]},{"word":"まつわる","reading":"","meaning":"về việc, xoay quanh, liên quan tới","hanViet":"","lesson":17,"ex":[["暦にまつわる話を聞きました。","Tôi đã nghe câu chuyện xoay quanh lịch."],["お正月にまつわる習慣を学びました。","Tôi đã học phong tục liên quan đến Tết."],["神社にまつわる話があります。","Có câu chuyện liên quan đến đền thờ."],["歴史にまつわる本を読みました。","Tôi đã đọc sách về lịch sử."],["桜にまつわる歌を聞きました。","Tôi đã nghe bài hát về hoa anh đào."]]},{"word":"本来","reading":"ほんらい","meaning":"vốn dĩ","hanViet":"BẢN LAI","lesson":17,"ex":[["本来は明日行く予定でした。","Vốn dĩ ngày mai tôi định đi."],["本来の意味を調べました。","Tôi đã tra nghĩa gốc."],["本来は月曜日が休みです。","Vốn dĩ thứ hai là ngày nghỉ."],["本来の目的は勉強です。","Mục đích vốn dĩ là học tập."],["本来はそうではありません。","Vốn dĩ không phải như vậy."]]},{"word":"タコ","reading":"","meaning":"bạch tuộc","hanViet":"","lesson":17,"ex":[["タコを食べました。","Tôi đã ăn bạch tuộc."],["タコは海にいます。","Bạch tuộc sống ở biển."],["タコには足がたくさんあります。","Bạch tuộc có nhiều chân."],["店でタコを買いました。","Tôi đã mua bạch tuộc ở cửa hàng."],["タコの料理を作りました。","Tôi đã nấu món bạch tuộc."]]},{"word":"八角形","reading":"はっかくけい","meaning":"hình bát giác","hanViet":"BÁT GIÁC HÌNH","lesson":17,"ex":[["八角形の形をしています。","Nó có hình bát giác."],["八角形を書きました。","Tôi đã vẽ hình bát giác."],["この建物は八角形です。","Tòa nhà này có hình bát giác."],["八角形のテーブルを買いました。","Tôi đã mua bàn hình bát giác."],["八角形の角を数えました。","Tôi đã đếm các góc của hình bát giác."]]},{"word":"不備","reading":"ふび","meaning":"sự thiếu sót, sự không hoàn chỉnh","hanViet":"BẤT BỊ","lesson":17,"ex":[["書類に不備がありました。","Tài liệu có thiếu sót."],["不備を直しました。","Tôi đã sửa thiếu sót."],["不備が見つかりました。","Đã phát hiện thiếu sót."],["不備がないか調べました。","Tôi đã kiểm tra xem có thiếu sót không."],["不備を補いました。","Tôi đã bổ sung thiếu sót."]]},{"word":"補う","reading":"おぎなう","meaning":"bổ sung","hanViet":"BỔ","lesson":17,"ex":[["本を読んで、知識を補いました。","Tôi đã đọc sách để bổ sung kiến thức."],["野菜を食べて、栄養を補いました。","Tôi đã ăn rau để bổ sung dinh dưỡng."],["お金を補いました。","Tôi đã bổ sung tiền."],["勉強で弱いところを補いました。","Tôi đã bổ sung điểm yếu bằng việc học."],["水を補いました。","Tôi đã bổ sung nước."]]},{"word":"呼び名","reading":"よびな","meaning":"tên gọi","hanViet":"HÔ DANH","lesson":17,"ex":[["呼び名を教えてください。","Hãy cho tôi biết tên gọi."],["この花の呼び名は何ですか。","Tên gọi của hoa này là gì."],["呼び名は国によって違います。","Tên gọi khác nhau theo từng nước."],["呼び名を覚えました。","Tôi đã nhớ tên gọi."],["田中さんの呼び名は「田中さん」です。","Tên gọi của anh Tanaka là \"Tanaka-san\"."]]},{"word":"ずれる","reading":"","meaning":"lệch","hanViet":"","lesson":17,"ex":[["時間がずれました。","Thời gian đã bị lệch."],["予定がずれました。","Kế hoạch đã bị lệch."],["帽子がずれました。","Mũ đã bị lệch."],["写真がずれました。","Ảnh đã bị lệch."],["机がずれました。","Bàn đã bị lệch."]]},{"word":"改暦（する）","reading":"かいれき（する）","meaning":"thay đổi lịch","hanViet":"CẢI LỊCH","lesson":17,"ex":[["日本は昔、改暦しました。","Ngày xưa, Nhật đã đổi lịch."],["改暦の歴史を勉強しました。","Tôi đã học lịch sử đổi lịch."],["改暦によって暦が変わりました。","Nhờ đổi lịch, lịch đã thay đổi."],["改暦のあと、日本は太陽暦を使いました。","Sau khi đổi lịch, Nhật đã dùng dương lịch."],["改暦の話を聞きました。","Tôi đã nghe câu chuyện về đổi lịch."]]},{"word":"新暦","reading":"しんれき","meaning":"lịch dương","hanViet":"TÂN LỊCH","lesson":17,"ex":[["新暦は太陽暦のことです。","Lịch dương là dương lịch."],["日本は新暦を使っています。","Nhật đang dùng lịch dương."],["新暦のお正月は一月にあります。","Tết dương lịch vào tháng một."],["新暦と旧暦は違います。","Lịch dương và lịch âm khác nhau."],["新暦は今のカレンダーです。","Lịch dương là lịch hiện nay."]]},{"word":"旧暦","reading":"きゅうれき","meaning":"lịch âm","hanViet":"CỰU LỊCH","lesson":17,"ex":[["旧暦は太陰暦のことです。","Lịch âm là âm lịch."],["旧暦のお正月は春にあります。","Tết âm lịch vào mùa xuân."],["旧暦は今も使われています。","Lịch âm hiện vẫn được dùng."],["旧暦を勉強しました。","Tôi đã học lịch âm."],["旧暦と新暦は違います。","Lịch âm và lịch dương khác nhau."]]},{"word":"別","reading":"べつ","meaning":"khác, riêng; (別に) ngoài ra, đặc biệt","hanViet":"BIỆT","lesson":17,"ex":[["別の店に行きました。","Tôi đã đi cửa hàng khác."],["別に問題はありません。","Không có vấn đề gì đặc biệt."],["別に用事があります。","Tôi có việc khác."],["別に二つ買いました。","Tôi đã mua thêm hai cái khác."],["別に何もありません。","Không có gì đặc biệt."]]},{"word":"睦月","reading":"むつき","meaning":"tên gọi tháng 1 âm lịch","hanViet":"MỤC NGUYỆT","lesson":17,"ex":[["睦月は旧暦の一月の名前です。","Mutsuki là tên tháng 1 âm lịch."],["睦月にお正月があります。","Tết có trong tháng Mutsuki."],["睦月の呼び名を覚えました。","Tôi đã nhớ tên gọi Mutsuki."],["睦月は寒い月です。","Mutsuki là tháng lạnh."],["睦月は日本の古い呼び名です。","Mutsuki là tên gọi cổ của Nhật."]]},{"word":"如月","reading":"きさらぎ","meaning":"tên gọi tháng 2 âm lịch","hanViet":"NHƯ NGUYỆT","lesson":17,"ex":[["如月は旧暦の二月の名前です。","Kisaragi là tên tháng 2 âm lịch."],["如月はまだ寒い月です。","Kisaragi vẫn là tháng lạnh."],["如月の呼び名を覚えました。","Tôi đã nhớ tên gọi Kisaragi."],["如月は日本の古い呼び名です。","Kisaragi là tên gọi cổ của Nhật."],["如月に雪が降ります。","Tuyết rơi vào tháng Kisaragi."]]},{"word":"弥生","reading":"やよい","meaning":"tên gọi tháng 3 âm lịch","hanViet":"DI SINH","lesson":17,"ex":[["弥生は旧暦の三月の名前です。","Yayoi là tên tháng 3 âm lịch."],["弥生は桜が咲く月です。","Tháng Yayoi là tháng hoa anh đào nở."],["弥生の呼び名を覚えました。","Tôi đã nhớ tên gọi Yayoi."],["弥生は日本の古い呼び名です。","Yayoi là tên gọi cổ của Nhật."],["弥生は春の月です。","Yayoi là tháng mùa xuân."]]},{"word":"木の葉","reading":"きのは","meaning":"lá cây","hanViet":"MỘC DIỆP","lesson":17,"ex":[["木の葉が落ちました。","Lá cây đã rơi."],["木の葉は緑です。","Lá cây màu xanh."],["秋に木の葉は赤くなります。","Mùa thu lá cây chuyển đỏ."],["木の葉を集めました。","Tôi đã thu thập lá cây."],["木の葉が風で飛びました。","Lá cây đã bay theo gió."]]},{"word":"転じる","reading":"てんじる","meaning":"chuyển thành, đổi thành","hanViet":"CHUYỂN","lesson":17,"ex":[["話は別の話題に転じました。","Câu chuyện đã chuyển sang chủ đề khác."],["会社は新しい仕事に転じました。","Công ty đã chuyển sang công việc mới."],["気持ちが転じました。","Tâm trạng đã thay đổi."],["仕事を変えて、教師に転じました。","Tôi đã đổi việc và chuyển thành giáo viên."],["季節は秋に転じました。","Mùa đã chuyển sang thu."]]},{"word":"葉月","reading":"はづき","meaning":"tên gọi tháng 8 âm lịch","hanViet":"DIỆP NGUYỆT","lesson":17,"ex":[["葉月は旧暦の八月の名前です。","Hazuki là tên tháng 8 âm lịch."],["葉月は暑い月です。","Hazuki là tháng nóng."],["葉月の呼び名を覚えました。","Tôi đã nhớ tên gọi Hazuki."],["葉月は日本の古い呼び名です。","Hazuki là tên gọi cổ của Nhật."],["葉月に祭りがあります。","Có lễ hội vào tháng Hazuki."]]},{"word":"長月","reading":"ながつき","meaning":"tên gọi tháng 9 âm lịch","hanViet":"TRƯỜNG NGUYỆT","lesson":17,"ex":[["長月は旧暦の九月の名前です。","Nagatsuki là tên tháng 9 âm lịch."],["長月は秋の月です。","Nagatsuki là tháng mùa thu."],["長月の呼び名を覚えました。","Tôi đã nhớ tên gọi Nagatsuki."],["長月は日本の古い呼び名です。","Nagatsuki là tên gọi cổ của Nhật."],["長月は夜が長くなります。","Tháng Nagatsuki, đêm dài ra."]]},{"word":"名づける","reading":"なづける","meaning":"đặt tên","hanViet":"DANH","lesson":17,"ex":[["犬に名前を名づけました。","Tôi đã đặt tên cho con chó."],["新しい店に名前を名づけました。","Tôi đã đặt tên cho cửa hàng mới."],["猫に名前を名づけました。","Tôi đã đặt tên cho con mèo."],["田中さんは犬に名前を名づけました。","Anh Tanaka đã đặt tên cho con chó."],["新しい商品に名前を名づけました。","Tôi đã đặt tên cho sản phẩm mới."]]},{"word":"立春","reading":"りっしゅん","meaning":"bắt đầu mùa xuân, lập xuân","hanViet":"LẬP XUÂN","lesson":17,"ex":[["立春は春が始まる日です。","Lập xuân là ngày mùa xuân bắt đầu."],["立春は二月の初めにあります。","Lập xuân vào đầu tháng hai."],["立春が来ました。","Lập xuân đã đến."],["立春を過ぎると、暖かくなります。","Qua lập xuân, trời ấm dần."],["立春は日本の暦の名前です。","Lập xuân là tên trong lịch Nhật."]]},{"word":"初旬","reading":"しょじゅん","meaning":"đầu tháng (10 ngày đầu của tháng)","hanViet":"SƠ TUẦN","lesson":17,"ex":[["四月の初旬は桜の季節です。","Đầu tháng Tư là mùa hoa anh đào."],["会議は来月の初旬です。","Cuộc họp diễn ra vào đầu tháng sau."],["新しい店は五月の初旬に開きます。","Cửa hàng mới sẽ mở cửa vào đầu tháng Năm."],["初旬に旅行に行く予定です。","Tôi dự định đi du lịch vào đầu tháng."],["田中さんは六月の初旬に東京へ来ます。","Anh Tanaka sẽ đến Tokyo vào đầu tháng Sáu."]]},{"word":"生じる","reading":"しょうじる","meaning":"nảy sinh, phát sinh","hanViet":"SINH","lesson":17,"ex":[["新しい問題が生じました。","Một vấn đề mới đã phát sinh."],["仕事が変わると、いろいろな問題が生じます。","Khi công việc thay đổi, nhiều vấn đề sẽ phát sinh."],["雨の日に事故が生じることがあります。","Vào ngày mưa, tai nạn có thể xảy ra."],["旅行のとき、よく問題が生じます。","Khi đi du lịch, vấn đề thường phát sinh."],["たくさんの人が集まると、問題が生じることがあります。","Khi nhiều người tụ tập, vấn đề có thể phát sinh."]]},{"word":"長年","reading":"ながねん","meaning":"trong nhiều năm","hanViet":"TRƯỜNG NIÊN","lesson":17,"ex":[["田中さんは長年この会社で働いています。","Anh Tanaka đã làm việc ở công ty này nhiều năm."],["長年住んだ町が大好きです。","Tôi rất yêu thị trấn đã sống nhiều năm."],["山田さんは長年先生をしています。","Anh Yamada đã làm giáo viên nhiều năm."],["長年使った時計を今も大切にしています。","Tôi vẫn trân trọng chiếc đồng hồ đã dùng nhiều năm."],["長年練習して、上手になりました。","Luyện tập nhiều năm, tôi đã giỏi lên."]]},{"word":"慣れ親しむ","reading":"なれしたしむ","meaning":"quen thuộc với","hanViet":"QUÁN THÂN","lesson":17,"ex":[["新しい仕事に慣れ親しみました。","Tôi đã quen với công việc mới."],["日本の料理に慣れ親しみました。","Tôi đã quen với món ăn Nhật Bản."],["長年住んだ家に慣れ親しんでいます。","Tôi đã quen thuộc với ngôi nhà đã sống nhiều năm."],["子どものときからこの歌に慣れ親しんでいます。","Tôi đã quen thuộc với bài hát này từ khi còn nhỏ."],["新しい学校に慣れ親しみました。","Tôi đã quen với trường mới."]]},{"word":"切り替える","reading":"きりかえる","meaning":"đổi, thay đổi","hanViet":"THIẾT THẾ","lesson":17,"ex":[["仕事から休みに気持ちを切り替えます。","Tôi chuyển tâm trạng từ công việc sang nghỉ ngơi."],["スイッチを切り替えました。","Tôi đã gạt công tắc."],["勉強の方法を切り替えてみました。","Tôi đã thử đổi phương pháp học."],["仕事の方法を切り替えて、新しい計画を作りました。","Tôi đã đổi cách làm việc và lập kế hoạch mới."],["画面を切り替えて、写真を見ました。","Tôi chuyển màn hình và xem ảnh."]]},{"word":"体制","reading":"たいせい","meaning":"thể chế","hanViet":"THỂ CHẾ","lesson":17,"ex":[["新しい体制で仕事が始まりました。","Công việc đã bắt đầu với thể chế mới."],["会社は新しい体制になりました。","Công ty đã chuyển sang thể chế mới."],["国の体制が変わると、生活も変わります。","Khi thể chế của đất nước thay đổi, cuộc sống cũng thay đổi."],["この会社の体制はよくできています。","Thể chế của công ty này rất tốt."],["体制が変わって、仕事の方法も変わりました。","Thể chế thay đổi nên cách làm việc cũng thay đổi."]]},{"word":"人心","reading":"じんしん","meaning":"lòng người","hanViet":"NHÂN TÂM","lesson":17,"ex":[["人心は目に見えません。","Lòng người không nhìn thấy bằng mắt được."],["人心を知ることは大切です。","Hiểu lòng người rất quan trọng."],["いい政治は人心を大切にします。","Chính trị tốt coi trọng lòng người."],["人心が変わると、国の様子も変わります。","Lòng người thay đổi thì tình hình đất nước cũng thay đổi."],["先生は人心がよくわかります。","Thầy giáo hiểu rõ lòng người."]]},{"word":"一新（する）","reading":"いっしん（する）","meaning":"cải cách, đổi mới","hanViet":"NHẤT TÂN","lesson":17,"ex":[["会社は体制を一新しました。","Công ty đã đổi mới thể chế."],["新しい社長が会社を一新しました。","Giám đốc mới đã đổi mới công ty."],["気持ちを一新して、新しい仕事を始めます。","Tôi đổi mới tâm trạng và bắt đầu công việc mới."],["店は中を一新しました。","Cửa hàng đã làm mới bên trong."],["一新した会社で働きたいです。","Tôi muốn làm việc ở công ty đã đổi mới."]]},{"word":"閏年","reading":"うるうどし","meaning":"năm nhuận","hanViet":"NHUẬN NIÊN","lesson":17,"ex":[["閏年の二月は二十九日まであります。","Tháng Hai của năm nhuận có đến ngày 29."],["閏年の二月は一日多いです。","Tháng Hai của năm nhuận dài hơn một ngày."],["今年が閏年なら、二月は二十九日まであります。","Nếu năm nay là năm nhuận thì tháng Hai có đến ngày 29."],["閏年について学校で習いました。","Tôi đã học về năm nhuận ở trường."],["来年が閏年かどうか、調べました。","Tôi đã tìm hiểu xem năm sau có phải năm nhuận không."]]},{"word":"抱える（問題を～）","reading":"かかえる（もんだいを～）","meaning":"có (~ vấn đề)","hanViet":"BÃO VẤN ĐỀ","lesson":17,"ex":[["会社は大きな問題を抱えています。","Công ty đang có vấn đề lớn."],["田中さんはたくさんの問題を抱えています。","Anh Tanaka đang có nhiều vấn đề."],["国は財政の問題を抱えています。","Đất nước đang có vấn đề về tài chính."],["学校は生徒が少ない問題を抱えています。","Trường học đang có vấn đề là ít học sinh."],["問題を抱えたら、友達に相談してください。","Nếu có vấn đề, hãy trao đổi với bạn bè."]]},{"word":"会計","reading":"かいけい","meaning":"kế toán","hanViet":"HỘI KẾ","lesson":17,"ex":[["田中さんは会社の会計をしています。","Anh Tanaka làm kế toán của công ty."],["会計の仕事は大切です。","Công việc kế toán rất quan trọng."],["会計を勉強しています。","Tôi đang học kế toán."],["母は会計の仕事をしています。","Mẹ tôi làm công việc kế toán."],["会計の本を読みました。","Tôi đã đọc sách về kế toán."]]},{"word":"年度","reading":"ねんど","meaning":"năm tài chính","hanViet":"NIÊN ĐỘ","lesson":17,"ex":[["新しい年度が四月に始まります。","Năm tài chính mới bắt đầu vào tháng Tư."],["今年は、年度の予算が去年より多いです。","Năm nay, ngân sách năm tài chính nhiều hơn năm ngoái."],["年度の終わりに報告をします。","Cuối năm tài chính, tôi làm báo cáo."],["新しい制度は、新しい年度から始まります。","Chế độ mới sẽ bắt đầu từ năm tài chính mới."],["年度が変わると、仕事も変わります。","Khi năm tài chính thay đổi, công việc cũng thay đổi."]]},{"word":"西洋","reading":"せいよう","meaning":"phương Tây","hanViet":"TÂY DƯƠNG","lesson":17,"ex":[["西洋の料理が好きです。","Tôi thích món ăn phương Tây."],["西洋の文化を勉強しています。","Tôi đang học văn hóa phương Tây."],["この家は西洋の家です。","Ngôi nhà này là nhà kiểu phương Tây."],["西洋の音楽をよく聞きます。","Tôi thường nghe nhạc phương Tây."],["西洋と日本の文化は違います。","Văn hóa phương Tây và Nhật Bản khác nhau."]]},{"word":"ならう","reading":"ならう","meaning":"học theo","hanViet":"","lesson":17,"ex":[["子どものとき、歌をならいました。","Hồi nhỏ, tôi đã học hát."],["先生に日本語をならっています。","Tôi đang học tiếng Nhật với thầy giáo."],["母に料理をならいました。","Tôi đã học nấu ăn từ mẹ."],["友達にスポーツをならっています。","Tôi đang học thể thao với bạn."],["先輩の仕事の方法をならいました。","Tôi đã học cách làm việc của đàn anh."]]},{"word":"一定","reading":"いってい","meaning":"cố định, nhất định","hanViet":"NHẤT ĐỊNH","lesson":17,"ex":[["一定の時間に学校へ行きます。","Tôi đến trường vào một giờ cố định."],["毎月一定のお金をもらいます。","Mỗi tháng tôi nhận một số tiền cố định."],["一定の時間、毎日勉強します。","Mỗi ngày tôi học trong một khoảng thời gian nhất định."],["一定の量の水を飲みます。","Tôi uống một lượng nước cố định."],["毎日一定の時間にごはんを食べます。","Mỗi ngày tôi ăn cơm vào một giờ cố định."]]},{"word":"諸～（～外国）","reading":"しょ～（～がいこく）","meaning":"các ~ (quốc gia bên ngoài)","hanViet":"CHƯ NGOẠI QUỐC","lesson":17,"ex":[["諸外国の文化を勉強しています。","Tôi đang học văn hóa của các nước ngoài."],["諸外国の料理が好きです。","Tôi thích món ăn của các nước ngoài."],["諸外国の人と話したいです。","Tôi muốn nói chuyện với người của các nước ngoài."],["諸外国からたくさんの人が日本へ来ます。","Nhiều người từ các nước ngoài đến Nhật Bản."],["諸外国の音楽を聞きます。","Tôi nghe nhạc của các nước ngoài."]]},{"word":"実施（する）","reading":"じっし（する）","meaning":"thực hiện, thực thi","hanViet":"THỰC THI","lesson":17,"ex":[["新しい制度を実施しました。","Chế độ mới đã được thực hiện."],["会社で会議を実施します。","Công ty tổ chức cuộc họp."],["計画を実施することが大切です。","Thực hiện kế hoạch rất quan trọng."],["来月から新しい方法を実施します。","Từ tháng sau, chúng tôi sẽ áp dụng phương pháp mới."],["国は新しい制度を実施しました。","Đất nước đã thực hiện chế độ mới."]]},{"word":"唐突（な）","reading":"とうとつ（な）","meaning":"đột ngột, bất ngờ","hanViet":"ĐƯỜNG ĐỘT","lesson":17,"ex":[["唐突な話にびっくりしました。","Tôi ngạc nhiên trước câu chuyện đột ngột."],["唐突な電話がありました。","Có một cuộc điện thoại đột ngột."],["唐突なメールが来ました。","Có một email đột ngột đến."],["唐突な知らせに戸惑いました。","Tôi bối rối trước tin đột ngột."],["先生の唐突な話に戸惑いました。","Tôi bối rối trước câu chuyện đột ngột của thầy giáo."]]},{"word":"戸惑う","reading":"とまどう","meaning":"hoang mang, bối rối","hanViet":"HỘ HOẶC","lesson":17,"ex":[["新しい仕事に戸惑いました。","Tôi bối rối với công việc mới."],["唐突な話に戸惑いました。","Tôi bối rối trước câu chuyện đột ngột."],["知らない町で戸惑いました。","Tôi bối rối ở thị trấn lạ."],["先生の話に戸惑いました。","Tôi bối rối trước lời nói của thầy giáo."],["道がわからなくて戸惑いました。","Tôi bối rối vì không biết đường."]]},{"word":"真の","reading":"しんの","meaning":"thật sự","hanViet":"CHÂN","lesson":17,"ex":[["真の友達は少ないです。","Bạn thật sự thì ít."],["真の意味を知りたいです。","Tôi muốn biết ý nghĩa thật sự."],["真の目的は何ですか。","Mục đích thật sự là gì?"],["真の幸せについて考えます。","Tôi suy nghĩ về hạnh phúc thật sự."],["真の原因を調べました。","Tôi đã tìm hiểu nguyên nhân thật sự."]]},{"word":"ねらい","reading":"ねらい","meaning":"mục đích, đích nhắm tới","hanViet":"","lesson":17,"ex":[["この計画のねらいは何ですか。","Mục đích của kế hoạch này là gì?"],["勉強のねらいは日本語が上手になることです。","Mục đích học tập là giỏi tiếng Nhật."],["ねらいを決めて、勉強します。","Tôi xác định mục đích rồi học."],["旅行のねらいは新しい文化を知ることです。","Mục đích chuyến du lịch là tìm hiểu văn hóa mới."],["ねらいがはっきりしています。","Mục đích rất rõ ràng."]]},{"word":"当時","reading":"とうじ","meaning":"tại thời điểm đó, khi đó","hanViet":"ĐƯƠNG THỜI","lesson":17,"ex":[["当時、私は学生でした。","Khi đó, tôi là học sinh."],["当時の日本は今と違います。","Nhật Bản khi đó khác với bây giờ."],["当時、田中さんは東京に住んでいました。","Khi đó, anh Tanaka sống ở Tokyo."],["当時、私はまだ子どもでした。","Khi đó, tôi vẫn còn là trẻ con."],["当時の話を聞きたいです。","Tôi muốn nghe câu chuyện khi đó."]]},{"word":"支出（する）","reading":"ししゅつ（する）","meaning":"chi tiêu","hanViet":"CHI XUẤT","lesson":17,"ex":[["毎月の支出を調べます。","Tôi kiểm tra chi tiêu mỗi tháng."],["支出が多くて困ります。","Chi tiêu nhiều nên tôi khó khăn."],["家族の支出を少なくしたいです。","Tôi muốn giảm chi tiêu của gia đình."],["今月の支出は先月より多いです。","Chi tiêu tháng này nhiều hơn tháng trước."],["支出をノートに書きます。","Tôi ghi chi tiêu vào sổ."]]},{"word":"占める","reading":"しめる","meaning":"chiếm","hanViet":"CHIẾM","lesson":17,"ex":[["人件費が支出の半分を占めます。","Chi phí nhân công chiếm một nửa chi tiêu."],["日本の人口の半分を女性が占めます。","Phụ nữ chiếm một nửa dân số Nhật Bản."],["この部屋は家の半分を占めます。","Căn phòng này chiếm một nửa ngôi nhà."],["仕事が一日の半分を占めます。","Công việc chiếm một nửa ngày."],["本が部屋の半分を占めています。","Sách chiếm một nửa căn phòng."]]},{"word":"人件費","reading":"じんけんひ","meaning":"chi phí nhân công","hanViet":"NHÂN KIỆN PHÍ","lesson":17,"ex":[["会社の人件費は毎年増えます。","Chi phí nhân công của công ty tăng mỗi năm."],["人件費を調べました。","Tôi đã tìm hiểu chi phí nhân công."],["人件費が高いので、会社は困っています。","Vì chi phí nhân công cao nên công ty gặp khó khăn."],["人件費は会社の支出の中で大きいです。","Chi phí nhân công chiếm phần lớn trong chi tiêu của công ty."],["社長は人件費について話しました。","Giám đốc đã nói về chi phí nhân công."]]},{"word":"費（人件～）","reading":"ひ（じんけん～）","meaning":"chi phí (nhân công~)","hanViet":"PHÍ NHÂN KIỆN","lesson":17,"ex":[["人件費を少なくしたいです。","Tôi muốn giảm chi phí nhân công."],["人件費の表を作りました。","Tôi đã làm bảng chi phí nhân công."],["人件費が増えて、会社は困っています。","Chi phí nhân công tăng nên công ty gặp khó khăn."],["人件費について会議で話しました。","Tôi đã nói về chi phí nhân công trong cuộc họp."],["人件費は去年より増えました。","Chi phí nhân công đã tăng so với năm ngoái."]]},{"word":"不足（する）","reading":"ふそく（する）","meaning":"thiếu","hanViet":"BẤT TÚC","lesson":17,"ex":[["お金が不足しています。","Tiền đang thiếu."],["時間が不足しています。","Thời gian đang thiếu."],["人が不足しているので、会社は困っています。","Vì thiếu người nên công ty gặp khó khăn."],["睡眠が不足すると、体が疲れます。","Nếu thiếu ngủ, cơ thể sẽ mệt."],["野菜が不足しています。","Rau đang thiếu."]]},{"word":"新制度","reading":"しんせいど","meaning":"chế độ mới","hanViet":"TÂN CHẾ ĐỘ","lesson":17,"ex":[["新制度が来月から始まります。","Chế độ mới bắt đầu từ tháng sau."],["新制度を実施しました。","Chế độ mới đã được thực hiện."],["新制度について勉強しました。","Tôi đã học về chế độ mới."],["新制度で仕事が変わりました。","Công việc đã thay đổi nhờ chế độ mới."],["会社は新制度を導入しました。","Công ty đã đưa chế độ mới vào áp dụng."]]},{"word":"導入（する）","reading":"どうにゅう（する）","meaning":"đưa vào áp dụng","hanViet":"ĐẠO NHẬP","lesson":17,"ex":[["会社は新しい制度を導入しました。","Công ty đã đưa chế độ mới vào áp dụng."],["学校は新しい方法を導入しました。","Trường học đã áp dụng phương pháp mới."],["新しい機械を導入しました。","Chúng tôi đã đưa máy móc mới vào sử dụng."],["導入した制度は便利です。","Chế độ đã đưa vào áp dụng rất tiện lợi."],["来年、新しい制度を導入します。","Năm sau, chúng tôi sẽ đưa chế độ mới vào áp dụng."]]},{"word":"役人","reading":"やくにん","meaning":"công chức, viên chức","hanViet":"DỊCH NHÂN","lesson":17,"ex":[["役人は国のために働きます。","Công chức làm việc vì đất nước."],["父は役人です。","Bố tôi là công chức."],["役人の仕事は忙しいです。","Công việc của công chức rất bận."],["役人になりたいです。","Tôi muốn trở thành công chức."],["役人はたくさんの書類を作ります。","Công chức làm nhiều giấy tờ."]]},{"word":"補充（する）","reading":"ほじゅう（する）","meaning":"bổ sung, tuyển dụng thêm","hanViet":"BỔ SUNG","lesson":17,"ex":[["会社は人を補充しました。","Công ty đã tuyển thêm người."],["水を補充しました。","Tôi đã bổ sung nước."],["本を補充しました。","Tôi đã bổ sung sách."],["会社は社員を補充します。","Công ty sẽ tuyển thêm nhân viên."],["店は商品を補充しました。","Cửa hàng đã bổ sung hàng hóa."]]},{"word":"財政難","reading":"ざいせいなん","meaning":"khó khăn về tài chính","hanViet":"TÀI CHÍNH NAN","lesson":17,"ex":[["国は財政難です。","Đất nước đang gặp khó khăn về tài chính."],["財政難で、会社は困っています。","Vì khó khăn tài chính, công ty gặp khó khăn."],["財政難の国が多いです。","Nhiều nước gặp khó khăn tài chính."],["町は財政難です。","Thị trấn đang gặp khó khăn tài chính."],["財政難について新聞で読みました。","Tôi đã đọc về khó khăn tài chính trên báo."]]},{"word":"財政","reading":"ざいせい","meaning":"tài chính","hanViet":"TÀI CHÍNH","lesson":17,"ex":[["国の財政は大切です。","Tài chính của đất nước rất quan trọng."],["財政について勉強しています。","Tôi đang học về tài chính."],["財政の話を聞きました。","Tôi đã nghe câu chuyện về tài chính."],["財政が悪くなると、国は困ります。","Tài chính xấu đi thì đất nước gặp khó khăn."],["財政の本を読みました。","Tôi đã đọc sách về tài chính."]]},{"word":"難（財政～）","reading":"なん（ざいせい～）","meaning":"khó khăn (tài chính ~)","hanViet":"NAN TÀI CHÍNH","lesson":17,"ex":[["財政難の町が多いです。","Nhiều thị trấn gặp khó khăn tài chính."],["財政難で学校が困っています。","Vì khó khăn tài chính, trường học gặp khó khăn."],["財政難は大変な問題です。","Khó khăn tài chính là vấn đề lớn."],["財政難について先生に聞きました。","Tôi đã hỏi thầy giáo về khó khăn tài chính."],["財政難の国を助けたいです。","Tôi muốn giúp đỡ các nước gặp khó khăn tài chính."]]},{"word":"新政権","reading":"しんせいけん","meaning":"chính quyền mới","hanViet":"TÂN CHÍNH QUYỀN","lesson":17,"ex":[["新政権が始まりました。","Chính quyền mới đã bắt đầu."],["新政権は新しい制度を作りました。","Chính quyền mới đã tạo ra chế độ mới."],["新政権について新聞で読みました。","Tôi đã đọc về chính quyền mới trên báo."],["新政権は国のために働きます。","Chính quyền mới làm việc vì đất nước."],["新政権ができて、生活が変わりました。","Chính quyền mới ra đời, cuộc sống đã thay đổi."]]},{"word":"政権","reading":"せいけん","meaning":"chế độ, chính quyền","hanViet":"CHÍNH QUYỀN","lesson":17,"ex":[["政権が変わりました。","Chính quyền đã thay đổi."],["新しい政権が始まりました。","Chính quyền mới đã bắt đầu."],["政権について勉強しています。","Tôi đang học về chính quyền."],["政権は国の仕事をします。","Chính quyền làm công việc của đất nước."],["政権が変わると、制度も変わります。","Khi chính quyền thay đổi, chế độ cũng thay đổi."]]},{"word":"翌日","reading":"よくじつ","meaning":"ngày tiếp theo, ngày kế tiếp","hanViet":"DƯỢC NHẬT","lesson":17,"ex":[["翌日、田中さんに会いました。","Ngày hôm sau, tôi đã gặp anh Tanaka."],["旅行の翌日は休みました。","Ngày hôm sau chuyến du lịch, tôi đã nghỉ."],["翌日、雨が降りました。","Ngày hôm sau, trời đã mưa."],["翌日に手紙を書きました。","Ngày hôm sau, tôi đã viết thư."],["会議の翌日、報告をしました。","Ngày hôm sau cuộc họp, tôi đã báo cáo."]]},{"word":"決断（する）","reading":"けつだん（する）","meaning":"quyết định","hanViet":"QUYẾT ĐOẠN","lesson":17,"ex":[["田中さんは決断しました。","Anh Tanaka đã quyết định."],["決断するのが難しいです。","Quyết định rất khó."],["決断は大切です。","Quyết định rất quan trọng."],["会社をやめる決断をしました。","Tôi đã quyết định nghỉ việc ở công ty."],["決断の前に、よく考えます。","Trước khi quyết định, tôi suy nghĩ kỹ."]]},{"word":"翌年","reading":"よくねん","meaning":"năm tiếp theo, năm kế tiếp","hanViet":"DƯỢC NIÊN","lesson":17,"ex":[["翌年、日本へ来ました。","Năm sau, tôi đã đến Nhật Bản."],["翌年、田中さんは結婚しました。","Năm sau, anh Tanaka đã kết hôn."],["翌年、学校を卒業しました。","Năm sau, tôi đã tốt nghiệp."],["翌年の春に旅行に行きました。","Mùa xuân năm sau, tôi đã đi du lịch."],["翌年も同じ仕事をしました。","Năm sau tôi cũng làm công việc đó."]]},{"word":"計～","reading":"けい～","meaning":"tổng cộng ~","hanViet":"KẾ","lesson":17,"ex":[["計百人が参加しました。","Tổng cộng 100 người đã tham gia."],["計十万円を使いました。","Tôi đã dùng tổng cộng 100 nghìn yên."],["計三日旅行しました。","Tôi đã du lịch tổng cộng 3 ngày."],["計五人の友達に会いました。","Tổng cộng tôi đã gặp 5 người bạn."],["計二十人が集まりました。","Tổng cộng 20 người đã tụ tập."]]},{"word":"回避（する）","reading":"かいひ（する）","meaning":"tránh","hanViet":"HỒI TỴ","lesson":17,"ex":[["問題を回避しました。","Tôi đã tránh vấn đề."],["危険を回避することが大切です。","Tránh nguy hiểm rất quan trọng."],["事故を回避しました。","Tôi đã tránh được tai nạn."],["危険な道を回避しました。","Tôi đã tránh con đường nguy hiểm."],["問題を回避する方法を考えました。","Tôi đã nghĩ cách tránh vấn đề."]]},{"word":"もくろむ","reading":"もくろむ","meaning":"lập kế hoạch, toan tính","hanViet":"","lesson":17,"ex":[["新しい計画をもくろんでいます。","Tôi đang lập kế hoạch mới."],["田中さんは旅行をもくろんでいます。","Anh Tanaka đang lên kế hoạch đi du lịch."],["会社は新しい店をもくろんでいます。","Công ty đang lên kế hoạch mở cửa hàng mới."],["いい結果をもくろんで、毎日勉強します。","Với toan tính đạt kết quả tốt, tôi học mỗi ngày."],["友達と旅行をもくろんでいます。","Tôi đang lên kế hoạch đi du lịch với bạn."]]},{"word":"作成（する）","reading":"さくせい（する）","meaning":"viết, soạn","hanViet":"TÁC THÀNH","lesson":17,"ex":[["書類を作成しました。","Tôi đã soạn giấy tờ."],["計画を作成しました。","Tôi đã lập kế hoạch."],["表を作成しました。","Tôi đã làm bảng."],["先生はテストを作成しました。","Thầy giáo đã soạn bài kiểm tra."],["先生は授業の表を作成しました。","Thầy giáo đã làm bảng giờ học."]]},{"word":"報告（する）","reading":"ほうこく（する）","meaning":"báo cáo","hanViet":"BÁO CÁO","lesson":17,"ex":[["先生に報告しました。","Tôi đã báo cáo với thầy giáo."],["会社で報告をしました。","Tôi đã báo cáo ở công ty."],["結果を報告します。","Tôi sẽ báo cáo kết quả."],["旅行のことを友達に報告しました。","Tôi đã kể về chuyến du lịch với bạn."],["毎月、仕事の報告をします。","Mỗi tháng, tôi báo cáo công việc."]]},{"word":"歓談（する）","reading":"かんだん（する）","meaning":"nói chuyện vui vẻ, nói chuyện thoải mái","hanViet":"HOAN ĐÀM","lesson":17,"ex":[["友達と歓談しました。","Tôi đã nói chuyện vui vẻ với bạn."],["先生と歓談しました。","Tôi đã nói chuyện vui vẻ với thầy giáo."],["昼ごはんのあとで歓談しました。","Sau bữa trưa, chúng tôi đã nói chuyện vui vẻ."],["久しぶりに会った友達と歓談しました。","Tôi đã nói chuyện vui vẻ với người bạn lâu ngày gặp lại."],["家族と歓談する時間は楽しいです。","Thời gian nói chuyện vui vẻ với gia đình rất vui."]]},{"word":"節分","reading":"せつぶん","meaning":"ngày trước lập xuân","hanViet":"TIẾT PHÂN","lesson":17,"ex":[["節分には豆をまきます。","Vào ngày Setsubun, người ta rải đậu."],["節分は二月の初めにあります。","Setsubun diễn ra vào đầu tháng Hai."],["節分に家族で豆をまきました。","Vào ngày Setsubun, gia đình tôi đã rải đậu."],["節分の行事が好きです。","Tôi thích sự kiện Setsubun."],["節分にはお面をかぶります。","Vào ngày Setsubun, người ta đeo mặt nạ."]]},{"word":"行事","reading":"ぎょうじ","meaning":"sự kiện, lễ hội","hanViet":"HÀNH SỰ","lesson":17,"ex":[["学校の行事に参加しました。","Tôi đã tham gia sự kiện của trường."],["行事の準備をしました。","Tôi đã chuẩn bị cho sự kiện."],["春の行事が好きです。","Tôi thích sự kiện mùa xuân."],["町の行事に家族で行きました。","Gia đình tôi đã đến sự kiện của thị trấn."],["行事の日は忙しいです。","Ngày diễn ra sự kiện rất bận."]]},{"word":"リビングルーム","reading":"","meaning":"phòng khách","hanViet":"","lesson":17,"ex":[["リビングルームでテレビを見ます。","Tôi xem TV ở phòng khách."],["リビングルームは広いです。","Phòng khách rất rộng."],["家族はリビングルームに集まります。","Gia đình tụ tập ở phòng khách."],["リビングルームで本を読みます。","Tôi đọc sách ở phòng khách."],["リビングルームで友達と話します。","Tôi nói chuyện với bạn ở phòng khách."]]},{"word":"ご無沙汰（する）","reading":"ごぶさた（する）","meaning":"lâu ngày không liên lạc","hanViet":"VÔ SA THÁI","lesson":17,"ex":[["ご無沙汰しています。","Lâu ngày không liên lạc."],["田中さん、ご無沙汰しています。","Anh Tanaka, lâu ngày không liên lạc."],["ご無沙汰して、すみません。","Xin lỗi vì lâu ngày không liên lạc."],["ご無沙汰しています。お元気ですか。","Lâu ngày không liên lạc. Anh có khỏe không?"],["手紙でご無沙汰していますと書きました。","Tôi đã viết trong thư rằng lâu ngày không liên lạc."]]},{"word":"お久しぶり","reading":"おひさしぶり","meaning":"lâu ngày không gặp","hanViet":"CỬU","lesson":17,"ex":[["お久しぶりです。","Lâu ngày không gặp."],["田中さん、お久しぶりです。","Anh Tanaka, lâu ngày không gặp."],["お久しぶりですね。お元気ですか。","Lâu ngày không gặp. Anh có khỏe không?"],["お久しぶりです。元気でしたか。","Lâu ngày không gặp. Anh có khỏe không?"],["友達に会って、お久しぶりと言いました。","Gặp bạn, tôi đã nói lâu ngày không gặp."]]},{"word":"口に合う","reading":"くちにあう","meaning":"vừa miệng, hợp khẩu vị","hanViet":"KHẨU HỢP","lesson":17,"ex":[["この料理は口に合います。","Món ăn này hợp khẩu vị của tôi."],["日本の料理は口に合います。","Món ăn Nhật Bản hợp khẩu vị của tôi."],["この店の料理は口に合いました。","Món ăn của cửa hàng này hợp khẩu vị của tôi."],["辛い料理は口に合いません。","Món cay không hợp khẩu vị của tôi."],["母の料理は口に合います。","Món ăn của mẹ hợp khẩu vị của tôi."]]},{"word":"邪魔（する）","reading":"じゃま（する）","meaning":"cản trở, làm phiền","hanViet":"TÀ MA","lesson":17,"ex":[["勉強の邪魔をしないでください。","Xin đừng làm phiền việc học của tôi."],["仕事の邪魔をしました。","Tôi đã làm phiền công việc."],["テレビの音が勉強の邪魔です。","Tiếng TV làm phiền việc học."],["邪魔をして、すみません。","Xin lỗi đã làm phiền."],["子どもが仕事の邪魔をします。","Trẻ con làm phiền công việc."]]},{"word":"おかまい","reading":"","meaning":"sự hiếu khách, sự mến khách","hanViet":"","lesson":17,"ex":[["おかまいなく、どうぞ。","Xin cứ tự nhiên, đừng bận tâm."],["おかまいなく、座ってください。","Đừng bận tâm, xin mời ngồi."],["おかまいなく、どうぞ入ってください。","Đừng bận tâm, xin mời vào."],["おかまいなく、ゆっくり休んでください。","Đừng bận tâm, xin cứ nghỉ ngơi thoải mái."],["おかまいなく、お茶を飲んでください。","Đừng bận tâm, xin mời uống trà."]]},{"word":"おいで","reading":"","meaning":"đến","hanViet":"","lesson":17,"ex":[["どうぞ、おいでください。","Xin mời đến."],["家へおいでください。","Xin mời đến nhà tôi."],["おいで、おいで。ここに来て。","Lại đây, lại đây. Đến đây nào."],["先生、おいでください。","Thưa thầy, xin mời đến."],["どうぞおいでください。お待ちしています。","Xin mời đến. Tôi đang chờ."]]},{"word":"早いもんだよ。","reading":"はやいもんだよ。","meaning":"\"Thời gian trôi qua nhanh thật\". (biểu hiện cảm thán thân mật)","hanViet":"TẢO","lesson":17,"ex":[["早いもんだよ。もう十二月だ。","Thời gian trôi qua nhanh thật. Đã tháng Mười Hai rồi."],["早いもんだよ。もうすぐお正月だ。","Thời gian trôi qua nhanh thật. Sắp đến Tết rồi."],["早いもんだよ。子どもはもう大きい。","Thời gian trôi qua nhanh thật. Đứa trẻ đã lớn rồi."],["早いもんだよ。もう春だ。","Thời gian trôi qua nhanh thật. Đã là mùa xuân rồi."],["早いもんだよ。卒業まであと少しだ。","Thời gian trôi qua nhanh thật. Sắp tốt nghiệp rồi."]]},{"word":"お面","reading":"おめん","meaning":"mặt nạ","hanViet":"DIỆN","lesson":17,"ex":[["節分にお面をかぶります。","Vào ngày Setsubun, người ta đeo mặt nạ."],["子どもはお面が好きです。","Trẻ con thích mặt nạ."],["お面を作りました。","Tôi đã làm mặt nạ."],["祭りでお面を買いました。","Tôi đã mua mặt nạ ở lễ hội."],["鬼のお面をかぶりました。","Tôi đã đeo mặt nạ quỷ."]]},{"word":"まく（豆を～）","reading":"まく（まめを～）","meaning":"rải (đậu)","hanViet":"ĐẬU","lesson":17,"ex":[["節分に豆をまきます。","Vào ngày Setsubun, người ta rải đậu."],["家族で豆をまきました。","Gia đình tôi đã rải đậu."],["豆をまいて、悪い鬼を追い払います。","Rải đậu để xua đuổi quỷ xấu."],["子どもが豆をまきます。","Trẻ con rải đậu."],["節分に外で豆をまきました。","Vào ngày Setsubun, tôi đã rải đậu ở ngoài."]]},{"word":"追い払う","reading":"おいはらう","meaning":"xua đuổi, đuổi đi","hanViet":"TRUY PHẤT","lesson":17,"ex":[["豆をまいて、鬼を追い払います。","Rải đậu để xua đuổi quỷ."],["節分に鬼を追い払います。","Vào ngày Setsubun, người ta xua đuổi quỷ."],["犬を追い払いました。","Tôi đã xua đuổi con chó."],["鳥を追い払いました。","Tôi đã xua đuổi chim."],["虫を追い払いました。","Tôi đã xua đuổi côn trùng."]]},{"word":"今どき","reading":"いまどき","meaning":"ngày nay, thời nay","hanViet":"KIM","lesson":17,"ex":[["今どきの子どもはパソコンを使います。","Trẻ con thời nay dùng máy tính."],["今どきの学生は忙しいです。","Học sinh thời nay rất bận."],["今どき、たくさんの人が旅行に行きます。","Thời nay, nhiều người đi du lịch."],["今どきの日本は変わりました。","Nhật Bản thời nay đã thay đổi."],["今どきの生活は便利です。","Cuộc sống thời nay rất tiện lợi."]]},{"word":"よっぽど／よほど","reading":"","meaning":"rất, đến mức, lắm","hanViet":"","lesson":17,"ex":[["よほど疲れたら、休んでください。","Nếu mệt lắm thì hãy nghỉ ngơi."],["よほどでないと、会社を休みません。","Trừ khi thật sự cần thiết, tôi không nghỉ việc."],["よほど忙しい日は、昼ごはんを食べません。","Vào những ngày bận lắm, tôi không ăn trưa."],["よっぽどおいしい料理でした。","Món ăn ngon lắm."],["よほど寒い日は、外へ出ません。","Vào những ngày lạnh lắm, tôi không ra ngoài."]]},{"word":"四季","reading":"しき","meaning":"bốn mùa","hanViet":"TỨ QUÝ","lesson":17,"ex":[["日本には四季があります。","Nhật Bản có bốn mùa."],["四季の中で春が一番好きです。","Trong bốn mùa, tôi thích mùa xuân nhất."],["四季の景色が美しいです。","Phong cảnh bốn mùa rất đẹp."],["四季折々の花が咲きます。","Hoa nở theo từng mùa."],["四季を楽しみたいです。","Tôi muốn tận hưởng bốn mùa."]]},{"word":"折々（四季～）","reading":"おりおり（しき～）","meaning":"mỗi (mùa trong năm)","hanViet":"CHIẾT TỨ QUÝ","lesson":17,"ex":[["四季折々の景色が美しいです。","Phong cảnh mỗi mùa trong năm rất đẹp."],["四季折々の花を見ます。","Tôi ngắm hoa mỗi mùa trong năm."],["四季折々の料理を食べます。","Tôi ăn món ăn mỗi mùa trong năm."],["日本は四季折々の国です。","Nhật Bản là đất nước có bốn mùa rõ rệt."],["四季折々の写真を撮ります。","Tôi chụp ảnh mỗi mùa trong năm."]]},{"word":"おじさん（子どもに向かっての）","reading":"おじさん（こどもにむかっての）","meaning":"chú, bác (khi xưng hô với trẻ con)","hanViet":"TỬ HƯỚNG","lesson":17,"ex":[["おじさんが本をくれました。","Chú đã cho tôi sách."],["おじさん、遊ぼう。","Chú ơi, chơi với cháu nhé."],["おじさんが本を読んでくれました。","Chú đã đọc sách cho tôi."],["おじさん、ありがとう。","Cảm ơn chú."],["おじさんといっしょに公園へ行きました。","Tôi đã đến công viên cùng chú."]]},{"word":"ユース","reading":"","meaning":"giới trẻ, thanh niên, tuổi trẻ","hanViet":"","lesson":17,"ex":[["ユースの時代は短いです。","Thời tuổi trẻ rất ngắn."],["ユース向けの本を読みました。","Tôi đã đọc sách dành cho giới trẻ."],["ユースの意見を聞きたいです。","Tôi muốn nghe ý kiến của giới trẻ."],["ユースの活動に参加しました。","Tôi đã tham gia hoạt động của giới trẻ."],["ユースの文化が好きです。","Tôi thích văn hóa của giới trẻ."]]},{"word":"抜く（人を～）","reading":"ぬく（ひとを～）","meaning":"vượt qua (người khác)","hanViet":"BẠT NHÂN","lesson":17,"ex":[["走りで友達を抜きました。","Tôi đã vượt qua bạn khi chạy."],["テストで友達を抜きました。","Tôi đã vượt qua bạn trong bài kiểm tra."],["リレーで人を抜きました。","Tôi đã vượt qua người khác trong cuộc thi chạy tiếp sức."],["仕事で先輩を抜きたいです。","Tôi muốn vượt qua đàn anh trong công việc."],["最後の走りで友達を抜きました。","Tôi đã vượt qua bạn trong lượt chạy cuối cùng."]]},{"word":"展示品","reading":"てんじひん","meaning":"đồ trưng bày","hanViet":"TRIỂN THỊ PHẨM","lesson":17,"ex":[["美術館の展示品を見ました。","Tôi đã xem đồ trưng bày ở bảo tàng mỹ thuật."],["展示品は美しいです。","Đồ trưng bày rất đẹp."],["展示品の写真を撮りました。","Tôi đã chụp ảnh đồ trưng bày."],["博物館の展示品が多いです。","Đồ trưng bày ở bảo tàng rất nhiều."],["展示品について説明を聞きました。","Tôi đã nghe giải thích về đồ trưng bày."]]},{"word":"親子","reading":"おやこ","meaning":"bố mẹ và con","hanViet":"THÂN TỬ","lesson":17,"ex":[["親子で公園へ行きました。","Bố mẹ và con đã đến công viên."],["親子で旅行に行きました。","Bố mẹ và con đã đi du lịch."],["親子で料理を作りました。","Bố mẹ và con đã cùng nấu ăn."],["親子で映画を見ました。","Bố mẹ và con đã xem phim."],["親子で水族館へ行きました。","Bố mẹ và con đã đến thủy cung."]]},{"word":"かける（声を～）","reading":"かける（こえを～）","meaning":"cất (tiếng gọi)","hanViet":"THANH","lesson":17,"ex":[["友達に声をかけました。","Tôi đã gọi bạn."],["知らない人に声をかけました。","Tôi đã gọi người lạ."],["先生に声をかけました。","Tôi đã gọi thầy giáo."],["子どもに声をかけました。","Tôi đã gọi đứa trẻ."],["困っている人に声をかけました。","Tôi đã gọi người đang gặp khó khăn."]]},{"word":"水族館","reading":"すいぞくかん","meaning":"thủy cung","hanViet":"THỦY TỘC QUÁN","lesson":17,"ex":[["水族館へ行きました。","Tôi đã đến thủy cung."],["水族館で魚を見ました。","Tôi đã xem cá ở thủy cung."],["子どもと水族館へ行きました。","Tôi đã đến thủy cung với con."],["水族館は楽しいです。","Thủy cung rất vui."],["水族館の魚は美しいです。","Cá ở thủy cung rất đẹp."]]},{"word":"～連れ","reading":"～づれ","meaning":"dẫn theo ~, kèm theo ~","hanViet":"LIÊN","lesson":17,"ex":[["子連れで旅行に行きました。","Tôi đã đi du lịch cùng con."],["子連れで水族館へ行きました。","Tôi đã đến thủy cung cùng con."],["家族連れで公園へ行きました。","Tôi đã đến công viên cùng gia đình."],["友達連れで映画を見ました。","Tôi đã xem phim cùng bạn."],["子連れで店へ行きました。","Tôi đã đến cửa hàng cùng con."]]},{"word":"母親","reading":"ははおや","meaning":"mẹ, người mẹ","hanViet":"MẪU THÂN","lesson":17,"ex":[["母親は料理が上手です。","Mẹ tôi nấu ăn giỏi."],["母親に手紙を書きました。","Tôi đã viết thư cho mẹ."],["母親と旅行に行きました。","Tôi đã đi du lịch với mẹ."],["母親は毎日忙しいです。","Mẹ tôi bận mỗi ngày."],["母親の料理が好きです。","Tôi thích món ăn của mẹ."]]},{"word":"リレー","reading":"","meaning":"thi chạy tiếp sức","hanViet":"","lesson":17,"ex":[["リレーに参加しました。","Tôi đã tham gia thi chạy tiếp sức."],["リレーで走りました。","Tôi đã chạy trong cuộc thi tiếp sức."],["リレーは楽しいです。","Thi chạy tiếp sức rất vui."],["学校のリレーに出ました。","Tôi đã tham gia thi chạy tiếp sức của trường."],["リレーで友達を抜きました。","Tôi đã vượt qua bạn trong thi chạy tiếp sức."]]},{"word":"ひな祭り","reading":"ひなまつり","meaning":"Lễ hội búp bê","hanViet":"TẾ","lesson":17,"ex":[["ひな祭りは三月三日です。","Lễ hội búp bê là ngày 3 tháng 3."],["ひな祭りにひな人形を飾ります。","Vào lễ hội búp bê, người ta trưng bày búp bê."],["ひな祭りが好きです。","Tôi thích lễ hội búp bê."],["ひな祭りに家族でごはんを食べました。","Vào lễ hội búp bê, gia đình tôi đã ăn cơm."],["ひな祭りの歌を歌いました。","Tôi đã hát bài hát lễ hội búp bê."]]},{"word":"ひな人形","reading":"ひなにんぎょう","meaning":"búp bê trưng bày trong Lễ hội búp bê","hanViet":"NHÂN HÌNH","lesson":17,"ex":[["ひな人形を飾りました。","Tôi đã trưng bày búp bê."],["ひな人形は美しいです。","Búp bê rất đẹp."],["ひな人形を買いました。","Tôi đã mua búp bê."],["ひな祭りにひな人形を見ました。","Vào lễ hội búp bê, tôi đã xem búp bê."],["ひな人形を大切にしています。","Tôi trân trọng búp bê."]]},{"word":"身近","reading":"みぢか","meaning":"gần, gần gũi","hanViet":"THÂN CẬN","lesson":17,"ex":[["身近な人が助けてくれました。","Người gần gũi đã giúp tôi."],["身近な問題について考えます。","Tôi suy nghĩ về vấn đề gần gũi."],["身近な人を大切にします。","Tôi trân trọng những người gần gũi."],["身近な店で本を買います。","Tôi mua sách ở cửa hàng gần gũi."],["身近な公園が好きです。","Tôi thích công viên gần gũi."]]},{"word":"都道府県","reading":"とどうふけん","meaning":"các tỉnh thành của Nhật Bản","hanViet":"ĐÔ ĐẠO PHỦ HUYỆN","lesson":17,"ex":[["日本には四十七の都道府県があります。","Nhật Bản có 47 tỉnh thành."],["都道府県の名前を覚えました。","Tôi đã nhớ tên các tỉnh thành."],["都道府県を旅行したいです。","Tôi muốn du lịch các tỉnh thành."],["都道府県の文化は違います。","Văn hóa các tỉnh thành khác nhau."],["都道府県について勉強しました。","Tôi đã học về các tỉnh thành."]]},{"word":"著者","reading":"ちょしゃ","meaning":"tác giả","hanViet":"TRỨ GIẢ","lesson":17,"ex":[["本の著者は田中さんです。","Tác giả của cuốn sách là anh Tanaka."],["著者に会いたいです。","Tôi muốn gặp tác giả."],["著者の名前を忘れました。","Tôi đã quên tên tác giả."],["著者は日本の作家です。","Tác giả là nhà văn Nhật Bản."],["著者の新しい本を読みました。","Tôi đã đọc cuốn sách mới của tác giả."]]},{"word":"クッキー","reading":"","meaning":"bánh quy","hanViet":"","lesson":17,"ex":[["クッキーを食べました。","Tôi đã ăn bánh quy."],["クッキーを作りました。","Tôi đã làm bánh quy."],["クッキーが好きです。","Tôi thích bánh quy."],["母はクッキーを作ります。","Mẹ tôi làm bánh quy."],["クッキーを友達にあげました。","Tôi đã tặng bánh quy cho bạn."]]},{"word":"恋愛（する）","reading":"れんあい（する）","meaning":"yêu đương","hanViet":"LUYẾN ÁI","lesson":17,"ex":[["恋愛について話しました。","Tôi đã nói về tình yêu."],["恋愛の本を読みました。","Tôi đã đọc sách về tình yêu."],["恋愛は楽しいです。","Yêu đương rất vui."],["恋愛の映画を見ました。","Tôi đã xem phim về tình yêu."],["恋愛をしています。","Tôi đang yêu."]]},{"word":"冒険","reading":"ぼうけん","meaning":"phiêu lưu, mạo hiểm","hanViet":"MẠO HIỂM","lesson":17,"ex":[["冒険が好きです。","Tôi thích phiêu lưu."],["冒険の本を読みました。","Tôi đã đọc sách về phiêu lưu."],["冒険に行きたいです。","Tôi muốn đi phiêu lưu."],["山の冒険は楽しいです。","Phiêu lưu trên núi rất vui."],["冒険の話を聞きました。","Tôi đã nghe câu chuyện phiêu lưu."]]},{"word":"好む","reading":"このむ","meaning":"thích","hanViet":"HẢO","lesson":17,"ex":[["私は静かな音楽を好みます。","Tôi thích nhạc nhẹ nhàng."],["田中さんは辛い料理より甘い料理を好みます。","Anh Tanaka thích món ngọt hơn món cay."],["母は野菜を作ることを好みます。","Mẹ thích trồng rau."],["子どもたちは甘いお菓子を好みます。","Trẻ em thích bánh kẹo ngọt."],["私は朝早く起きることを好みます。","Tôi thích dậy sớm."]]},{"word":"地方","reading":"ちほう","meaning":"địa phương, vùng","hanViet":"ĐỊA PHƯƠNG","lesson":17,"ex":[["日本の地方には、おいしい食べ物がたくさんあります。","Ở các địa phương của Nhật Bản có nhiều món ăn ngon."],["田中さんは地方の小さい町に住んでいます。","Anh Tanaka sống ở một thị trấn nhỏ ở địa phương."],["地方の祭りを見に、たくさんの人が来ます。","Nhiều người đến xem lễ hội địa phương."],["この地方は雪が多くて、冬はとても寒いです。","Vùng này nhiều tuyết, mùa đông rất lạnh."],["地方から東京へ来た学生が増えています。","Số sinh viên từ địa phương lên Tokyo đang tăng lên."]]},{"word":"特産品","reading":"とくさんひん","meaning":"đặc sản","hanViet":"ĐẶC SẢN PHẨM","lesson":17,"ex":[["この町の特産品は、りんごです。","Đặc sản của thị trấn này là táo."],["旅行に行くと、特産品を買って帰ります。","Khi đi du lịch, tôi mua đặc sản rồi mang về."],["その地方の特産品は、駅の店で買えます。","Đặc sản của vùng đó có thể mua ở cửa hàng trong ga."],["母は特産品の野菜を使って、料理を作ります。","Mẹ dùng rau đặc sản để nấu ăn."],["特産品は友達へのお土産にいいです。","Đặc sản rất hợp làm quà cho bạn bè."]]},{"word":"玉ねぎ","reading":"たまねぎ","meaning":"hành tây","hanViet":"NGỌC","lesson":17,"ex":[["料理を作るとき、玉ねぎをたくさん使います。","Khi nấu ăn, tôi dùng nhiều hành tây."],["玉ねぎを切るのは、少し難しいです。","Cắt hành tây hơi khó."],["このスープには、玉ねぎとじゃがいもが入っています。","Món súp này có hành tây và khoai tây."],["母は玉ねぎを買うために、スーパーへ行きました。","Mẹ đã đi siêu thị để mua hành tây."],["玉ねぎと肉を煮ました。","Tôi đã hầm hành tây với thịt."]]},{"word":"じゃがいも","reading":"","meaning":"khoai tây","hanViet":"","lesson":17,"ex":[["じゃがいもを切って、鍋に入れます。","Cắt khoai tây rồi cho vào nồi."],["子どもたちはじゃがいもの料理が大好きです。","Trẻ em rất thích món khoai tây."],["じゃがいもをゆでて、食べました。","Tôi đã luộc khoai tây rồi ăn."],["店でじゃがいもをたくさん買いました。","Tôi đã mua nhiều khoai tây ở cửa hàng."],["じゃがいもは安くて、おいしいです。","Khoai tây rẻ và ngon."]]},{"word":"盛ん（な）","reading":"さかん（な）","meaning":"thịnh hành, sôi nổi, phát triển","hanViet":"THỊNH","lesson":17,"ex":[["この町では、サッカーが盛んです。","Ở thị trấn này, bóng đá rất thịnh hành."],["春になると、花見が盛んになります。","Khi xuân đến, việc ngắm hoa anh đào trở nên sôi nổi."],["この学校では、スポーツが盛んです。","Ở trường này, thể thao rất thịnh hành."],["京都では、観光が盛んです。","Ở Kyoto, du lịch rất phát triển."],["この町は、昔から祭りが盛んな町です。","Thị trấn này từ xưa đã là nơi lễ hội sôi nổi."]]},{"word":"移す","reading":"うつす","meaning":"di chuyển","hanViet":"DI","lesson":17,"ex":[["机を窓の近くに移しました。","Tôi đã dời bàn đến gần cửa sổ."],["店を駅の前に移しました。","Tôi đã chuyển cửa hàng ra trước ga."],["本を棚に移しました。","Tôi đã chuyển sách lên kệ."],["荷物を部屋の中に移してください。","Hãy chuyển hành lý vào trong phòng."],["写真をパソコンに移しました。","Tôi đã chuyển ảnh sang máy tính."]]},{"word":"コスト","reading":"","meaning":"chi phí, giá cả","hanViet":"","lesson":17,"ex":[["この店はコストが安いので、物が安く買えます。","Cửa hàng này chi phí thấp nên mua đồ rẻ."],["コストを下げるために、会社は新しい機械を買いました。","Để giảm chi phí, công ty đã mua máy mới."],["電気のコストが高くなりました。","Chi phí điện đã tăng cao."],["会社はコストを考えて、計画を作りました。","Công ty đã lập kế hoạch sau khi tính đến chi phí."],["コストが高いので、その商品は買えません。","Vì chi phí cao nên tôi không mua được sản phẩm đó."]]},{"word":"出口調査","reading":"でぐちちょうさ","meaning":"điều tra ngay tại cửa ra của phòng bỏ phiếu","hanViet":"XUẤT KHẨU ĐIỀU TRA","lesson":17,"ex":[["投票をしてから、出口調査に答えました。","Sau khi bỏ phiếu, tôi đã trả lời điều tra tại cửa ra."],["出口調査の結果は、夜のニュースで見ました。","Tôi đã xem kết quả điều tra tại cửa ra trên bản tin tối."],["投票の出口で、出口調査をしていました。","Ở cửa ra của nơi bỏ phiếu, người ta đang làm điều tra."],["出口調査では、だれに投票したかを聞きます。","Trong điều tra tại cửa ra, người ta hỏi bạn đã bỏ phiếu cho ai."],["出口調査は、テレビで見たことがあります。","Tôi đã từng thấy điều tra tại cửa ra trên TV."]]},{"word":"生活習慣病","reading":"せいかつしゅうかんびょう","meaning":"bệnh do lối sống","hanViet":"SINH HOẠT TẬP QUÁN BỆNH","lesson":17,"ex":[["生活習慣病にならないために、毎日運動します。","Để không mắc bệnh do lối sống, tôi vận động mỗi ngày."],["生活習慣病は、食べ物や運動することと関係があります。","Bệnh do lối sống liên quan đến ăn uống và vận động."],["医者は生活習慣病について、話をしました。","Bác sĩ đã nói về bệnh do lối sống."],["野菜を食べると、生活習慣病になりにくいです。","Ăn rau sẽ khó mắc bệnh do lối sống."],["生活習慣病にならないように、塩を少なくします。","Để không mắc bệnh do lối sống, tôi giảm muối."]]},{"word":"おぼれる","reading":"","meaning":"chết đuối","hanViet":"","lesson":17,"ex":[["川で泳いでいるとき、おぼれそうになりました。","Khi đang bơi ở sông, tôi suýt chết đuối."],["子どもが川でおぼれないように、大人が見ています。","Để trẻ không chết đuối ở sông, người lớn trông chừng."],["海でおぼれた人を、助けました。","Tôi đã cứu người bị đuối nước ở biển."],["雨の日、川の水が増えて、おぼれる人がいます。","Ngày mưa, nước sông dâng cao, có người bị chết đuối."],["おぼれないように、プールでは走ってはいけません。","Để không chết đuối, ở hồ bơi không được chạy."]]},{"word":"複数","reading":"ふくすう","meaning":"nhiều","hanViet":"PHỨC SỐ","lesson":17,"ex":[["複数の本を、図書館で借りました。","Tôi đã mượn nhiều cuốn sách ở thư viện."],["複数の人が、会議に参加しました。","Nhiều người đã tham gia cuộc họp."],["この店には、複数の種類のパンがあります。","Cửa hàng này có nhiều loại bánh mì."],["複数の国から、学生が来ました。","Sinh viên đến từ nhiều nước."],["複数の答えがある問題は、難しいです。","Bài toán có nhiều đáp án thì khó."]]},{"word":"足跡","reading":"あしあと","meaning":"dấu chân","hanViet":"TÚC TÍCH","lesson":17,"ex":[["雪の上に、足跡がたくさんありました。","Trên tuyết có nhiều dấu chân."],["犬の足跡が、庭にありました。","Dấu chân chó ở trong vườn."],["足跡を見て、だれが来たかわかりました。","Nhìn dấu chân, tôi biết ai đã đến."],["海の足跡は、波ですぐ消えます。","Dấu chân ở biển bị sóng xóa ngay."],["山の道に、足跡がありました。","Trên đường núi có dấu chân."]]},{"word":"頂上","reading":"ちょうじょう","meaning":"đỉnh núi","hanViet":"ĐỈNH THƯỢNG","lesson":17,"ex":[["山の頂上から、海が見えました。","Từ đỉnh núi, tôi nhìn thấy biển."],["頂上まで、三時間かかりました。","Lên đến đỉnh mất ba tiếng."],["頂上に着いたとき、みんなで写真を撮りました。","Khi lên đến đỉnh, mọi người cùng chụp ảnh."],["山の頂上は、とても寒いです。","Đỉnh núi rất lạnh."],["頂上からの景色は、とてもきれいでした。","Phong cảnh từ đỉnh núi rất đẹp."]]},{"word":"吹雪","reading":"ふぶき","meaning":"bão tuyết","hanViet":"XÚY TUYẾT","lesson":17,"ex":[["吹雪の日は、外に出てはいけません。","Ngày bão tuyết không được ra ngoài."],["吹雪で、電車が止まりました。","Vì bão tuyết, tàu điện đã dừng."],["吹雪の中を、家まで歩きました。","Tôi đã đi bộ về nhà trong bão tuyết."],["冬の山では、吹雪がよくあります。","Ở núi vào mùa đông thường có bão tuyết."],["吹雪が強くなったので、学校は休みになりました。","Vì bão tuyết mạnh lên nên trường được nghỉ."]]},{"word":"遭う（吹雪に～）","reading":"あう（ふぶきに～）","meaning":"gặp (bão tuyết)","hanViet":"TAO XÚY TUYẾT","lesson":17,"ex":[["山で吹雪に遭いました。","Tôi đã gặp bão tuyết trên núi."],["旅行のとき、吹雪に遭いました。","Khi đi du lịch, tôi đã gặp bão tuyết."],["吹雪に遭って、家に帰れませんでした。","Gặp bão tuyết nên tôi không về được nhà."],["冬に山へ行くと、吹雪に遭うことがあります。","Đi núi vào mùa đông đôi khi gặp bão tuyết."],["吹雪に遭わないように、天気を調べました。","Để không gặp bão tuyết, tôi đã kiểm tra thời tiết."]]},{"word":"引き返す","reading":"ひきかえす","meaning":"quay trở lại","hanViet":"DẪN PHẢN","lesson":17,"ex":[["忘れ物をしたので、家に引き返しました。","Vì quên đồ nên tôi đã quay về nhà."],["雨が強くなったので、途中で引き返しました。","Vì mưa to lên nên tôi đã quay lại giữa đường."],["道がわからなくて、引き返しました。","Vì không biết đường nên tôi đã quay lại."],["駅まで行ったが、引き返して家に帰りました。","Tôi đã đi đến ga nhưng quay lại về nhà."],["引き返そうと思いましたが、進みました。","Tôi định quay lại nhưng vẫn tiến lên."]]},{"word":"予想（する）","reading":"よそう（する）","meaning":"dự đoán","hanViet":"DỰ TƯỞNG","lesson":17,"ex":[["天気予報では、あした雨が降ると予想しています。","Dự báo thời tiết dự đoán mai trời mưa."],["予想より、早く終わりました。","Xong sớm hơn dự đoán."],["先生は、試験の結果を予想しました。","Thầy giáo đã dự đoán kết quả bài kiểm tra."],["予想していたより、人が多かったです。","Đông người hơn dự đoán."],["来年の天気を予想することは、難しいです。","Dự đoán thời tiết năm sau thì khó."]]},{"word":"はるかに","reading":"","meaning":"hơn hẳn, vượt xa","hanViet":"","lesson":17,"ex":[["この山は、あの山よりはるかに高いです。","Ngọn núi này cao hơn hẳn ngọn núi kia."],["兄は私よりはるかに速く走れます。","Anh trai chạy nhanh hơn hẳn tôi."],["新しい電車は、古い電車よりはるかに速いです。","Tàu mới nhanh hơn hẳn tàu cũ."],["田中さんは、山田さんよりはるかに上手です。","Anh Tanaka giỏi hơn hẳn anh Yamada."],["きょうは、きのうよりはるかに寒いです。","Hôm nay lạnh hơn hẳn hôm qua."]]},{"word":"イベント","reading":"","meaning":"sự kiện","hanViet":"","lesson":17,"ex":[["週末に、町のイベントがあります。","Cuối tuần có sự kiện của thị trấn."],["学校のイベントに、たくさんの人が来ました。","Nhiều người đã đến sự kiện của trường."],["イベントの準備を、みんなでしました。","Mọi người cùng chuẩn bị cho sự kiện."],["このイベントは、子どもも楽しめます。","Sự kiện này trẻ em cũng thích."],["イベントが終わってから、みんなで掃除しました。","Sau khi sự kiện kết thúc, mọi người cùng dọn dẹp."]]},{"word":"納得（する）","reading":"なっとく（する）","meaning":"chấp nhận","hanViet":"NẠP ĐẮC","lesson":17,"ex":[["理由を聞いて、納得しました。","Nghe lý do xong, tôi đã chấp nhận."],["先生に聞いて、納得しました。","Hỏi thầy xong, tôi đã chấp nhận."],["納得できないので、もう一度聞きました。","Vì chưa chấp nhận được nên tôi đã hỏi lại lần nữa."],["値段を聞いて、納得して買いました。","Nghe giá xong, tôi chấp nhận và mua."],["みんなが納得するまで、話しました。","Tôi đã nói cho đến khi mọi người đều chấp nhận."]]},{"word":"方針","reading":"ほうしん","meaning":"chính sách, phương châm","hanViet":"PHƯƠNG CHÂM","lesson":17,"ex":[["会社の方針が変わりました。","Phương châm của công ty đã thay đổi."],["学校の方針で、毎朝掃除します。","Theo phương châm của trường, mỗi sáng đều dọn dẹp."],["新しい方針を、みんなで決めました。","Mọi người cùng quyết định phương châm mới."],["方針を変える前に、よく考えます。","Trước khi đổi phương châm, tôi suy nghĩ kỹ."],["その方針には、賛成できません。","Tôi không thể tán thành phương châm đó."]]},{"word":"新入生","reading":"しんにゅうせい","meaning":"sinh viên mới, sinh viên năm nhất","hanViet":"TÂN NHẬP SINH","lesson":17,"ex":[["新入生が、学校に入学しました。","Sinh viên mới đã nhập học."],["新入生を、歓迎会で迎えました。","Chúng tôi đã đón sinh viên mới tại buổi chào mừng."],["新入生は、まだ学校に慣れていません。","Sinh viên mới vẫn chưa quen với trường."],["新入生の教室は、図書館の近くにあります。","Phòng học của sinh viên mới ở gần thư viện."],["新入生に、学校を案内しました。","Tôi đã dẫn sinh viên mới đi tham quan trường."]]},{"word":"持つ（子どもを～）","reading":"もつ（こどもを～）","meaning":"có (con)","hanViet":"TRÌ TỬ","lesson":17,"ex":[["田中さんは、子どもを三人持っています。","Anh Tanaka có ba đứa con."],["子どもを持つと、生活が変わります。","Khi có con, cuộc sống sẽ thay đổi."],["山田さんは、子どもを二人持っています。","Anh Yamada có hai đứa con."],["子どもを持ってから、早く帰るようになりました。","Từ khi có con, tôi về nhà sớm hơn."],["子どもを持つことは、とてもうれしいことです。","Có con là điều rất vui."]]},{"word":"ありがたい","reading":"","meaning":"biết ơn","hanViet":"","lesson":17,"ex":[["手伝ってくれて、ありがたいです。","Bạn giúp tôi, tôi rất biết ơn."],["雨がやんで、ありがたいです。","Mưa đã tạnh, thật đáng mừng."],["先生が教えてくれて、ありがたいです。","Thầy dạy cho tôi, tôi rất biết ơn."],["忙しいときに手伝ってくれるのは、ありがたいです。","Khi bận mà có người giúp thì thật đáng quý."],["ありがたい話を聞きました。","Tôi đã nghe một câu chuyện đáng quý."]]},{"word":"稼ぐ","reading":"かせぐ","meaning":"kiếm tiền","hanViet":"GIÁ","lesson":17,"ex":[["アルバイトでお金を稼いでいます。","Tôi đang kiếm tiền bằng việc làm thêm."],["田中さんは、会社でたくさん稼いでいます。","Anh Tanaka kiếm được nhiều tiền ở công ty."],["お金を稼ぐために、毎日働いています。","Để kiếm tiền, tôi làm việc mỗi ngày."],["週末に、アルバイトで稼ぎました。","Cuối tuần, tôi đã kiếm tiền bằng việc làm thêm."],["稼いだお金で、本を買いました。","Tôi đã mua sách bằng số tiền kiếm được."]]},{"word":"あきれる","reading":"","meaning":"ngao ngán, chán ngán; sửng sốt (vì điều quá đáng)","hanViet":"","lesson":17,"ex":[["彼の話に、あきれました。","Tôi ngạc nhiên trước câu chuyện của anh ấy."],["あきれるほど、人が多かったです。","Đông người đến mức ngạc nhiên."],["毎日遅刻する人に、あきれました。","Tôi ngạc nhiên với người ngày nào cũng đi muộn."],["そんなに高い値段に、あきれました。","Tôi sốc với mức giá cao như vậy."],["あきれて、何も言えませんでした。","Ngạc nhiên đến mức không nói được gì."]]},{"word":"素人","reading":"しろうと","meaning":"dân nghiệp dư, người không chuyên","hanViet":"TỐ NHÂN","lesson":17,"ex":[["私は料理の素人です。","Tôi là người không chuyên về nấu ăn."],["素人でも、この料理は作れます。","Người không chuyên cũng làm được món này."],["素人の写真ですが、きれいです。","Tuy là ảnh của người không chuyên nhưng rất đẹp."],["素人にしては、上手ですね。","Là người không chuyên mà giỏi nhỉ."],["素人なので、教えてください。","Vì tôi là người không chuyên nên hãy dạy tôi."]]},{"word":"相当（な）","reading":"そうとう（な）","meaning":"không tệ, khá","hanViet":"TƯƠNG, TƯỚNG ĐƯƠNG","lesson":17,"ex":[["相当な時間がかかりました。","Mất khá nhiều thời gian."],["相当なお金を使いました。","Tôi đã dùng khá nhiều tiền."],["その問題は、相当難しいです。","Bài toán đó khá khó."],["相当遅くなりました。","Đã khá muộn rồi."],["相当疲れました。","Tôi đã khá mệt."]]},{"word":"独学（する）","reading":"どくがく（する）","meaning":"tự học","hanViet":"ĐỘC HỌC","lesson":17,"ex":[["日本語を独学しています。","Tôi đang tự học tiếng Nhật."],["独学で、英語を勉強しました。","Tôi đã tự học tiếng Anh."],["独学するのは、難しいですが、楽しいです。","Tự học tuy khó nhưng vui."],["田中さんは独学で、ピアノを勉強しました。","Anh Tanaka đã tự học piano."],["独学で合格しました。","Tôi đã đỗ nhờ tự học."]]},{"word":"基準","reading":"きじゅん","meaning":"tiêu chuẩn","hanViet":"CƠ CHUẨN","lesson":17,"ex":[["基準を決めました。","Tôi đã đặt ra tiêu chuẩn."],["この基準に合う人は、少ないです。","Ít người đạt tiêu chuẩn này."],["基準が高いので、合格するのは難しいです。","Vì tiêu chuẩn cao nên đỗ rất khó."],["学校の基準は、はっきりしています。","Tiêu chuẩn của trường rất rõ ràng."],["基準に合わないものは、使いません。","Thứ không đạt tiêu chuẩn thì không dùng."]]},{"word":"照らす","reading":"てらす","meaning":"chiếu theo","hanViet":"CHIẾU","lesson":17,"ex":[["基準に照らして、決めました。","Tôi đã quyết định dựa theo tiêu chuẩn."],["規則に照らして、考えます。","Tôi suy nghĩ dựa theo quy định."],["昔の話に照らして、決めました。","Tôi đã quyết định dựa theo chuyện xưa."],["条件に照らして、選びました。","Tôi đã chọn dựa theo điều kiện."],["法律に照らして、調べました。","Tôi đã kiểm tra dựa theo pháp luật."]]},{"word":"新入社員","reading":"しんにゅうしゃいん","meaning":"nhân viên mới vào công ty","hanViet":"TÂN NHẬP XÃ VIÊN","lesson":17,"ex":[["新入社員が、会社に入りました。","Nhân viên mới đã vào công ty."],["新入社員を、研修で教えます。","Chúng tôi dạy nhân viên mới trong khóa đào tạo."],["新入社員は、まだ仕事に慣れていません。","Nhân viên mới vẫn chưa quen với công việc."],["新入社員の歓迎会がありました。","Đã có buổi chào mừng nhân viên mới."],["新入社員に、仕事を教えました。","Tôi đã dạy việc cho nhân viên mới."]]},{"word":"応対（する）","reading":"おうたい（する）","meaning":"ứng đối, trả lời","hanViet":"ỨNG ĐỐI","lesson":17,"ex":[["電話の応対をしました。","Tôi đã trả lời điện thoại."],["応対が丁寧ですね。","Cách ứng đối thật lịch sự."],["店の応対がいいです。","Cách phục vụ của cửa hàng tốt."],["応対が上手な人が、店にいます。","Ở cửa hàng có người ứng đối giỏi."],["新入社員は、電話の応対を練習します。","Nhân viên mới luyện tập trả lời điện thoại."]]},{"word":"学位","reading":"がくい","meaning":"học vị","hanViet":"HỌC VỊ","lesson":17,"ex":[["大学で学位を取りました。","Tôi đã lấy học vị ở đại học."],["博士の学位を取りました。","Tôi đã lấy học vị tiến sĩ."],["学位を取るために、論文を書きました。","Để lấy học vị, tôi đã viết luận văn."],["学位を取って、大学で働いています。","Lấy học vị xong, tôi làm việc ở đại học."],["学位を取ると、仕事が増えます。","Lấy học vị xong, công việc tăng lên."]]},{"word":"負けず嫌い","reading":"まけずぎらい","meaning":"ghét phải thua, hiếu thắng","hanViet":"PHỤ HIỀM","lesson":17,"ex":[["田中さんは負けず嫌いです。","Anh Tanaka rất hiếu thắng."],["負けず嫌いな人は、よく練習します。","Người hiếu thắng thường luyện tập nhiều."],["弟は負けず嫌いで、試合に負けると泣きます。","Em trai tôi hiếu thắng, thua trận là khóc."],["負けず嫌いなので、最後まで頑張ります。","Vì hiếu thắng nên tôi cố gắng đến cuối cùng."],["負けず嫌いな子どもが、多くなりました。","Trẻ em hiếu thắng ngày càng nhiều."]]},{"word":"しっかり","reading":"","meaning":"kĩ càng, chắc chắn","hanViet":"","lesson":17,"ex":[["しっかり勉強します。","Tôi học hành chăm chỉ."],["しっかり食べて、元気になりました。","Ăn uống đầy đủ nên tôi đã khỏe lên."],["しっかり寝てください。","Hãy ngủ thật ngon nhé."],["荷物をしっかり持ってください。","Hãy cầm chắc hành lý."],["しっかり覚えました。","Tôi đã nhớ kỹ."]]},{"word":"バイオリン","reading":"","meaning":"đàn vĩ cầm, vi-ô-lông","hanViet":"","lesson":17,"ex":[["バイオリンを弾きます。","Tôi chơi vĩ cầm."],["バイオリンの音が好きです。","Tôi thích tiếng vĩ cầm."],["子どもはバイオリンを習っています。","Đứa trẻ đang học vĩ cầm."],["バイオリンを、毎日練習します。","Tôi luyện vĩ cầm mỗi ngày."],["バイオリンを弾くのは、難しいです。","Chơi vĩ cầm thì khó."]]},{"word":"着替える","reading":"きがえる","meaning":"thay đồ, thay quần áo","hanViet":"TRƯỚC THẾ","lesson":17,"ex":[["服を着替えます。","Tôi thay quần áo."],["着替えてから、出かけます。","Thay đồ xong rồi ra ngoài."],["プールの前に、服を着替えます。","Trước khi xuống hồ bơi, tôi thay quần áo."],["子どもは自分で着替えます。","Đứa trẻ tự thay quần áo."],["仕事の服に着替えて、働きます。","Tôi thay sang quần áo làm việc rồi làm việc."]]},{"word":"しゃくりあげる","reading":"","meaning":"khóc nức nở, khóc nấc","hanViet":"","lesson":17,"ex":[["子どもがしゃくりあげて泣いています。","Đứa trẻ đang khóc nức nở."],["妹がしゃくりあげました。","Em gái tôi đã khóc nấc."],["しゃくりあげるほど、悲しかったです。","Buồn đến mức khóc nức nở."],["子どもはしゃくりあげながら、話しました。","Đứa trẻ vừa khóc nấc vừa nói."],["映画を見て、しゃくりあげました。","Xem phim, tôi đã khóc nức nở."]]},{"word":"甘えん坊","reading":"あまえんぼう","meaning":"đứa trẻ hay làm nũng","hanViet":"CAM PHƯỜNG","lesson":17,"ex":[["弟は甘えん坊です。","Em trai tôi hay làm nũng."],["甘えん坊な子どもは、母のそばにいます。","Đứa trẻ hay làm nũng ở bên cạnh mẹ."],["妹は甘えん坊です。","Em gái tôi hay làm nũng."],["甘えん坊な子どもが、泣いています。","Đứa trẻ hay làm nũng đang khóc."],["甘えん坊の子どもは、かわいいです。","Đứa trẻ hay làm nũng thật đáng yêu."]]},{"word":"鉦","reading":"かね","meaning":"cồng chiêng","hanViet":"CHINH","lesson":17,"ex":[["寺で鉦が鳴ります。","Ở chùa, cồng vang lên."],["鉦の音が聞こえます。","Nghe thấy tiếng cồng."],["鉦の音は、遠くまで聞こえます。","Tiếng cồng nghe thấy từ xa."],["鉦の音を聞いて、静かな気持ちになりました。","Nghe tiếng cồng, lòng tôi trở nên tĩnh lặng."],["鉦は、寺の楽器です。","Cồng là nhạc cụ của chùa."]]},{"word":"ルーツ","reading":"","meaning":"nguồn gốc","hanViet":"","lesson":17,"ex":[["日本のルーツを調べます。","Tôi tìm hiểu nguồn gốc của Nhật Bản."],["家族のルーツを調べたいです。","Tôi muốn tìm hiểu nguồn gốc gia đình."],["ルーツを調べるのは、おもしろいです。","Tìm hiểu nguồn gốc thật thú vị."],["その料理のルーツを調べました。","Tôi đã tìm hiểu nguồn gốc của món ăn đó."],["ルーツがわかると、歴史がわかります。","Khi biết nguồn gốc, sẽ hiểu lịch sử."]]},{"word":"古代","reading":"こだい","meaning":"cổ đại","hanViet":"CỔ ĐẠI","lesson":17,"ex":[["古代の人は、星を見て、時間を考えました。","Người cổ đại nhìn sao và nghĩ về thời gian."],["古代の話を読みました。","Tôi đã đọc truyện cổ đại."],["古代の国には、大きい城がありました。","Nước cổ đại có lâu đài lớn."],["古代の人は、山や川を大切にしました。","Người cổ đại trân trọng núi và sông."],["古代の遺跡を見に行きました。","Tôi đã đi xem di tích cổ đại."]]},{"word":"王国","reading":"おうこく","meaning":"vương quốc","hanViet":"VƯƠNG QUỐC","lesson":17,"ex":[["昔、この国は王国でした。","Ngày xưa, đất nước này là một vương quốc."],["王国の話を読みました。","Tôi đã đọc truyện về vương quốc."],["王国には、大きい城がありました。","Vương quốc có lâu đài lớn."],["王国の首都は、海の近くにありました。","Thủ đô của vương quốc ở gần biển."],["昔の王国の話が好きです。","Tôi thích truyện về vương quốc xưa."]]},{"word":"天文","reading":"てんもん","meaning":"thiên văn","hanViet":"THIÊN VĂN","lesson":17,"ex":[["天文が好きです。","Tôi thích thiên văn."],["天文の本を読みました。","Tôi đã đọc sách thiên văn."],["天文の勉強をしています。","Tôi đang học thiên văn."],["天文の話を聞きました。","Tôi đã nghe chuyện thiên văn."],["子どもは天文に興味があります。","Đứa trẻ có hứng thú với thiên văn."]]},{"word":"学者","reading":"がくしゃ","meaning":"học giả","hanViet":"HỌC GIẢ","lesson":17,"ex":[["学者の話を聞きました。","Tôi đã nghe học giả nói."],["歴史の学者が、本を書きました。","Học giả lịch sử đã viết sách."],["学者は星を観測します。","Học giả quan sát các vì sao."],["その学者は、古代のことを調べています。","Học giả đó đang nghiên cứu về cổ đại."],["学者になるために、大学で勉強します。","Để trở thành học giả, tôi học ở đại học."]]},{"word":"観測（する）","reading":"かんそく（する）","meaning":"quan sát","hanViet":"QUAN TRẮC","lesson":17,"ex":[["星を観測します。","Tôi quan sát các vì sao."],["観測するために、山に行きました。","Để quan sát, tôi đã lên núi."],["毎晩、月を観測しています。","Mỗi tối, tôi quan sát mặt trăng."],["観測の結果を、ノートに書きました。","Tôi đã ghi kết quả quan sát vào vở."],["学者が星を観測しています。","Học giả đang quan sát các vì sao."]]},{"word":"水星","reading":"すいせい","meaning":"Sao Thủy","hanViet":"THỦY TINH","lesson":17,"ex":[["水星は太陽に一番近い星です。","Sao Thủy là ngôi sao gần mặt trời nhất."],["水星は小さい星です。","Sao Thủy là ngôi sao nhỏ."],["水星の話を本で読みました。","Tôi đã đọc về Sao Thủy trong sách."],["水星は昼は暑くて、夜は寒いです。","Sao Thủy ban ngày nóng, ban đêm lạnh."],["水星を見るのは、難しいです。","Nhìn thấy Sao Thủy thì khó."]]},{"word":"金星","reading":"きんせい","meaning":"Sao Kim","hanViet":"KIM TINH","lesson":17,"ex":[["金星は明るい星です。","Sao Kim là ngôi sao sáng."],["金星は夕方によく見えます。","Sao Kim thường thấy vào buổi chiều tối."],["金星は地球の近くにあります。","Sao Kim ở gần Trái Đất."],["金星は美しい星です。","Sao Kim là ngôi sao đẹp."],["金星のことを、先生に聞きました。","Tôi đã hỏi thầy về Sao Kim."]]},{"word":"火星","reading":"かせい","meaning":"Sao Hỏa","hanViet":"HỎA TINH","lesson":17,"ex":[["火星は赤い星です。","Sao Hỏa là ngôi sao đỏ."],["火星は地球の近くにあります。","Sao Hỏa ở gần Trái Đất."],["火星を見るのが好きです。","Tôi thích ngắm Sao Hỏa."],["火星には、水があると言われています。","Người ta nói rằng trên Sao Hỏa có nước."],["火星の写真を見ました。","Tôi đã xem ảnh Sao Hỏa."]]},{"word":"木星","reading":"もくせい","meaning":"Sao Mộc","hanViet":"MỘC TINH","lesson":17,"ex":[["木星は一番大きい星です。","Sao Mộc là ngôi sao lớn nhất."],["木星は夜によく見えます。","Sao Mộc thường thấy vào ban đêm."],["木星を見るのが好きです。","Tôi thích ngắm Sao Mộc."],["木星は太陽から遠い星です。","Sao Mộc là ngôi sao xa mặt trời."],["木星のことを、テレビで見ました。","Tôi đã xem về Sao Mộc trên TV."]]},{"word":"支配（する）","reading":"しはい（する）","meaning":"điều khiển, chi phối","hanViet":"CHI PHỐI","lesson":17,"ex":[["王様が国を支配しました。","Vua đã cai trị đất nước."],["その王国は、大きい国に支配されました。","Vương quốc đó bị nước lớn chi phối."],["支配する人は、強い力を持っています。","Người cai trị có sức mạnh lớn."],["昔、王様が国を支配していました。","Ngày xưa, vua đã cai trị đất nước."],["その国は、王様に支配されていました。","Đất nước đó bị vua cai trị."]]},{"word":"特定（する）","reading":"とくてい（する）","meaning":"xác định","hanViet":"ĐẶC ĐỊNH","lesson":17,"ex":[["場所を特定します。","Tôi xác định địa điểm."],["特定の人を探します。","Tôi tìm một người cụ thể."],["原因を特定しました。","Tôi đã xác định nguyên nhân."],["特定の日に、会います。","Chúng tôi gặp nhau vào một ngày cụ thể."],["問題の場所を特定します。","Tôi xác định vị trí của vấn đề."]]},{"word":"割り振る","reading":"わりふる","meaning":"phân chia, phân bố","hanViet":"CÁT CHẤN","lesson":17,"ex":[["仕事を割り振ります。","Tôi phân chia công việc."],["時間を割り振って、勉強します。","Tôi phân chia thời gian để học."],["お金を割り振りました。","Tôi đã phân chia tiền."],["先生が仕事を割り振りました。","Thầy đã phân chia công việc."],["割り振られた仕事をしました。","Tôi đã làm công việc được phân chia."]]},{"word":"並び順","reading":"ならびじゅん","meaning":"thứ tự sắp xếp","hanViet":"TỊNH THUẬN","lesson":17,"ex":[["名前の並び順を決めました。","Tôi đã quyết định thứ tự sắp xếp tên."],["並び順を変えました。","Tôi đã đổi thứ tự sắp xếp."],["本の並び順を決めます。","Tôi quyết định thứ tự sắp xếp sách."],["並び順がわかりません。","Tôi không biết thứ tự sắp xếp."],["並び順を確かめました。","Tôi đã kiểm tra thứ tự sắp xếp."]]},{"word":"端午の節句","reading":"たんごのせっく","meaning":"lễ hội dành cho bé trai","hanViet":"ĐOAN NGỌ TIẾT CÚ","lesson":17,"ex":[["端午の節句に、鯉のぼりを飾ります。","Vào lễ Đoan Ngọ, người ta treo cờ cá chép."],["端午の節句は、男の子の祭りです。","Lễ Đoan Ngọ là lễ hội của bé trai."],["端午の節句に、武者人形を飾ります。","Vào lễ Đoan Ngọ, người ta trưng búp bê samurai."],["端午の節句の話を聞きました。","Tôi đã nghe chuyện về lễ Đoan Ngọ."],["端午の節句は、五月にあります。","Lễ Đoan Ngọ vào tháng 5."]]},{"word":"節句","reading":"せっく","meaning":"lễ hội theo mùa","hanViet":"TIẾT CÚ","lesson":17,"ex":[["日本の節句を勉強します。","Tôi học về lễ hội theo mùa của Nhật Bản."],["節句の日に、特別な料理を食べます。","Vào ngày lễ theo mùa, tôi ăn món đặc biệt."],["節句の話を聞きました。","Tôi đã nghe chuyện về lễ hội theo mùa."],["節句には、家族が集まります。","Vào lễ theo mùa, gia đình quây quần."],["日本には、多くの節句があります。","Nhật Bản có nhiều lễ hội theo mùa."]]},{"word":"武者人形","reading":"むしゃにんぎょう","meaning":"búp bê chiến binh samurai","hanViet":"VŨ, VÕ GIẢ NHÂN HÌNH","lesson":17,"ex":[["武者人形を飾ります。","Tôi trưng búp bê samurai."],["武者人形は、五月に飾ります。","Búp bê samurai được trưng vào tháng 5."],["武者人形は、男の子の部屋にあります。","Búp bê samurai ở trong phòng bé trai."],["武者人形を見に、店へ行きました。","Tôi đã đến cửa hàng để xem búp bê samurai."],["武者人形の顔は、強いです。","Khuôn mặt búp bê samurai trông mạnh mẽ."]]},{"word":"鯉のぼり","reading":"こいのぼり","meaning":"cờ cá chép","hanViet":"LÝ","lesson":17,"ex":[["鯉のぼりを飾ります。","Tôi treo cờ cá chép."],["鯉のぼりが空を泳いでいます。","Cờ cá chép đang bơi trên trời."],["風で、鯉のぼりが大きく動きます。","Gió thổi, cờ cá chép động đậy mạnh."],["鯉のぼりを見に、川へ行きました。","Tôi đã ra sông để xem cờ cá chép."],["子どもは鯉のぼりが好きです。","Trẻ em thích cờ cá chép."]]},{"word":"鯉","reading":"こい","meaning":"cá chép","hanViet":"LÝ","lesson":17,"ex":[["池に鯉がいます。","Trong ao có cá chép."],["鯉はきれいな魚です。","Cá chép là loài cá đẹp."],["鯉は池で泳ぎます。","Cá chép bơi trong ao."],["鯉が池を泳いでいます。","Cá chép đang bơi trong ao."],["大きい鯉を見ました。","Tôi đã thấy con cá chép lớn."]]},{"word":"伝説","reading":"でんせつ","meaning":"truyền thuyết","hanViet":"TRUYỀN THUYẾT","lesson":17,"ex":[["伝説の話を読みました。","Tôi đã đọc truyện truyền thuyết."],["その山には、伝説があります。","Ngọn núi đó có truyền thuyết."],["伝説の竜の話が好きです。","Tôi thích truyện về rồng trong truyền thuyết."],["伝説の話は、昔からあります。","Truyện truyền thuyết có từ xưa."],["伝説の話は、おもしろいです。","Truyện truyền thuyết thật thú vị."]]},{"word":"流れ（川の～）","reading":"ながれ（かわの～）","meaning":"dòng (sông)","hanViet":"LƯU XUYÊN","lesson":17,"ex":[["川の流れが速いです。","Dòng sông chảy nhanh."],["川の流れを見ています。","Tôi đang nhìn dòng sông."],["川の流れは、きれいです。","Dòng sông thật đẹp."],["川の流れに、木の葉が流れています。","Lá cây đang trôi theo dòng sông."],["川の流れが遅くなりました。","Dòng sông chảy chậm lại."]]},{"word":"滝","reading":"たき","meaning":"thác nước","hanViet":"LANG","lesson":17,"ex":[["滝を見に行きました。","Tôi đã đi xem thác nước."],["滝の音が聞こえます。","Nghe thấy tiếng thác nước."],["大きい滝があります。","Có thác nước lớn."],["滝の水は、冷たいです。","Nước thác lạnh."],["滝の近くで、写真を撮りました。","Tôi đã chụp ảnh gần thác nước."]]},{"word":"逆らう","reading":"さからう","meaning":"ngược, ngược dòng","hanViet":"NGHỊCH","lesson":17,"ex":[["川の流れに逆らって、泳ぎます。","Tôi bơi ngược dòng sông."],["風に逆らって、歩きます。","Tôi đi bộ ngược gió."],["親に逆らってはいけません。","Không được chống đối cha mẹ."],["先生の話に逆らうのは、よくありません。","Chống lại lời thầy thì không tốt."],["流れに逆らう魚がいます。","Có loài cá bơi ngược dòng."]]},{"word":"光り輝く","reading":"ひかりかがやく","meaning":"tỏa sáng","hanViet":"QUANG HUY","lesson":17,"ex":[["星が光り輝いています。","Ngôi sao đang tỏa sáng."],["太陽が光り輝いています。","Mặt trời đang tỏa sáng."],["海が光り輝いています。","Biển đang tỏa sáng."],["雪が光り輝いています。","Tuyết đang tỏa sáng."],["夜の町が光り輝いています。","Thị trấn ban đêm đang tỏa sáng."]]},{"word":"竜","reading":"りゅう","meaning":"con rồng","hanViet":"LONG","lesson":17,"ex":[["竜の話を読みました。","Tôi đã đọc truyện về rồng."],["竜は、伝説の動物です。","Rồng là con vật trong truyền thuyết."],["竜が空を飛んでいます。","Rồng đang bay trên trời."],["子どもは竜が好きです。","Trẻ em thích rồng."],["竜の絵を見ました。","Tôi đã xem tranh rồng."]]},{"word":"変身（する）","reading":"へんしん（する）","meaning":"biến hình, thay đổi hình dạng","hanViet":"BIẾN THÂN","lesson":17,"ex":[["鯉が竜に変身します。","Cá chép biến thành rồng."],["子どもは変身するのが好きです。","Trẻ em thích biến hình."],["変身した竜が、空を飛びます。","Con rồng đã biến hình bay lên trời."],["映画で、人が竜に変身しました。","Trong phim, người đã biến thành rồng."],["変身する話が好きです。","Tôi thích truyện biến hình."]]},{"word":"昇る（天に～）","reading":"のぼる（てんに～）","meaning":"lên (trời)","hanViet":"THĂNG THIÊN","lesson":17,"ex":[["竜が天に昇ります。","Rồng bay lên trời."],["太陽が空に昇ります。","Mặt trời mọc lên trời."],["煙が空に昇ります。","Khói bay lên trời."],["月が空に昇ります。","Mặt trăng mọc lên trời."],["星が空に昇ります。","Ngôi sao mọc lên trời."]]},{"word":"困難","reading":"こんなん","meaning":"khó khăn","hanViet":"KHỐN NAN","lesson":17,"ex":[["困難な問題があります。","Có vấn đề khó khăn."],["困難なとき、友達が助けてくれます。","Khi khó khăn, bạn bè giúp đỡ tôi."],["困難ですが、頑張ります。","Tuy khó khăn nhưng tôi cố gắng."],["困難な仕事をしました。","Tôi đã làm công việc khó khăn."],["困難な試験に合格しました。","Tôi đã đỗ kỳ thi khó khăn."]]},{"word":"立ち向かう","reading":"たちむかう","meaning":"đối mặt, đương đầu","hanViet":"LẬP HƯỚNG","lesson":17,"ex":[["困難に立ち向かいます。","Tôi đối mặt với khó khăn."],["問題に立ち向かいます。","Tôi đối mặt với vấn đề."],["怖いことに立ち向かいます。","Tôi đối mặt với điều đáng sợ."],["強い人に立ち向かいます。","Tôi đối mặt với người mạnh."],["立ち向かうことが大切です。","Đối mặt là điều quan trọng."]]},{"word":"生まれる（鯉のぼりが～）","reading":"うまれる（こいのぼりが～）","meaning":"(cờ cá chép) được hình thành, được tạo ra","hanViet":"SINH LÝ","lesson":17,"ex":[["鯉のぼりが生まれました。","Cờ cá chép đã ra đời."],["この祭りは、昔生まれました。","Lễ hội này ra đời từ xưa."],["新しい町が生まれました。","Thị trấn mới đã ra đời."],["子どもが生まれました。","Đứa trẻ đã ra đời."],["伝説が生まれました。","Truyền thuyết đã ra đời."]]},{"word":"鉛筆削り","reading":"えんぴつけずり","meaning":"cái gọt bút chì","hanViet":"DUYÊN BÚT TƯỚC","lesson":18,"ex":[["鉛筆削りは、鉛筆に使います。","Cái gọt bút chì dùng cho bút chì."],["鉛筆削りが、机の上にあります。","Cái gọt bút chì ở trên bàn."],["新しい鉛筆削りを買いました。","Tôi đã mua cái gọt bút chì mới."],["鉛筆削りを使って、鉛筆を書けるようにします。","Tôi dùng cái gọt để bút chì viết được."],["鉛筆削りを、かばんに入れています。","Tôi để cái gọt bút chì trong cặp."]]},{"word":"幸運","reading":"こううん","meaning":"vận may, may mắn","hanViet":"HẠNH VẬN","lesson":18,"ex":[["試験の日は、雨がやんで、幸運でした。","Vào ngày thi, trời đã tạnh mưa, thật may mắn."],["幸運な人です。","Anh ấy là người may mắn."],["幸運が来ますように。","Mong may mắn sẽ đến."],["幸運な日でした。","Đó là ngày may mắn."],["幸運にも、試験に合格しました。","May mắn thay, tôi đã đỗ kỳ thi."]]},{"word":"登場人物","reading":"とうじょうじんぶつ","meaning":"nhân vật xuất hiện","hanViet":"ĐĂNG TRƯỜNG NHÂN VẬT","lesson":18,"ex":[["本の登場人物が好きです。","Tôi thích nhân vật trong sách."],["登場人物が多くて、覚えられません。","Nhiều nhân vật quá nên tôi không nhớ nổi."],["この映画の登場人物は、みんな元気です。","Nhân vật trong phim này ai cũng khỏe mạnh."],["登場人物の名前を覚えました。","Tôi đã nhớ tên các nhân vật."],["登場人物について、話しました。","Tôi đã nói về các nhân vật."]]},{"word":"内（心の～）","reading":"うち（こころの～）","meaning":"bên trong (~ lòng)","hanViet":"NỘI TÂM","lesson":18,"ex":[["心の内を話します。","Tôi nói ra lòng mình."],["心の内は、だれにもわかりません。","Lòng người thì không ai hiểu được."],["心の内を聞きました。","Tôi đã lắng nghe lòng người."],["心の内に、夢があります。","Trong lòng tôi có ước mơ."],["心の内を書きました。","Tôi đã viết ra lòng mình."]]},{"word":"解釈（する）","reading":"かいしゃく（する）","meaning":"lý giải, giải thích","hanViet":"GIẢI THÍCH","lesson":18,"ex":[["その話を解釈します。","Tôi lý giải câu chuyện đó."],["人によって、解釈が変わります。","Tùy người mà cách lý giải thay đổi."],["夢を解釈します。","Tôi lý giải giấc mơ."],["先生の話を解釈しました。","Tôi đã lý giải lời thầy nói."],["解釈するのは、難しいです。","Lý giải thì khó."]]},{"word":"山（本の～）","reading":"やま（ほんの～）","meaning":"chồng, đống (~ sách)","hanViet":"SƠN BẢN","lesson":18,"ex":[["本の山があります。","Có chồng sách."],["机の上に、本の山があります。","Trên bàn có chồng sách."],["本の山を読みました。","Tôi đã đọc chồng sách."],["部屋に本の山があります。","Trong phòng có chồng sách."],["本の山が高くなりました。","Chồng sách đã cao lên."]]},{"word":"言い返す","reading":"いいかえす","meaning":"nói lại, cãi lại","hanViet":"NGÔN PHẢN","lesson":18,"ex":[["先生に言い返しました。","Tôi đã cãi lại thầy."],["言い返さないで、聞きました。","Tôi không cãi lại mà lắng nghe."],["言い返すのは、よくありません。","Cãi lại thì không tốt."],["友達に言い返しました。","Tôi đã cãi lại bạn."],["言い返したくなりました。","Tôi muốn cãi lại."]]},{"word":"修復（する）","reading":"しゅうふく（する）","meaning":"khôi phục, hồi phục","hanViet":"TU PHỤC","lesson":18,"ex":[["古い本を修復します。","Tôi phục hồi sách cũ."],["修復するために、時間がかかります。","Để phục hồi cần thời gian."],["家を修復しました。","Tôi đã sửa chữa ngôi nhà."],["修復された絵を見ました。","Tôi đã xem bức tranh được phục hồi."],["修復するのは、難しいです。","Phục hồi thì khó."]]},{"word":"おそらく","reading":"","meaning":"có lẽ","hanViet":"","lesson":18,"ex":[["あしたはおそらく雨が降ります。","Ngày mai có lẽ trời sẽ mưa."],["田中さんはおそらく電車で来ます。","Anh Tanaka có lẽ sẽ đến bằng tàu điện."],["この本はおそらくおもしろいと思います。","Tôi nghĩ cuốn sách này có lẽ thú vị."],["会議はおそらく午後三時に終わります。","Cuộc họp có lẽ sẽ kết thúc lúc 3 giờ chiều."],["おそらくあしたは晴れると思います。","Tôi nghĩ ngày mai có lẽ trời sẽ nắng."]]},{"word":"薄汚い","reading":"うすぎたない","meaning":"bẩn thỉu, dơ dáy","hanViet":"BẠC Ô","lesson":18,"ex":[["この古いタオルは薄汚いので、新しいタオルを買います。","Cái khăn cũ này bẩn thỉu nên tôi sẽ mua khăn mới."],["薄汚い窓をふいて、きれいにします。","Tôi lau cửa sổ bẩn thỉu cho sạch."],["薄汚い手で本を触らないでください。","Xin đừng chạm vào sách bằng bàn tay bẩn thỉu."],["薄汚いコップはもう使いません。","Tôi không dùng cái cốc bẩn thỉu đó nữa."],["子どもは薄汚い靴で部屋に入りました。","Đứa trẻ đi giày bẩn thỉu vào phòng."]]},{"word":"ぴかぴか（な）","reading":"","meaning":"lấp lánh, sáng loáng","hanViet":"","lesson":18,"ex":[["ふいた窓はぴかぴかになりました。","Cửa sổ sau khi lau trở nên sáng loáng."],["新しい車はぴかぴかで、とてもきれいです。","Chiếc xe mới sáng loáng và rất đẹp."],["ぴかぴかな靴を買いました。","Tôi đã mua đôi giày sáng loáng."],["掃除したあと、床はぴかぴかです。","Sau khi dọn dẹp, sàn nhà sáng loáng."],["ぴかぴかなコップを棚に並べます。","Tôi xếp những cái cốc sáng loáng lên kệ."]]},{"word":"新品","reading":"しんぴん","meaning":"đồ mới, hàng mới","hanViet":"TÂN PHẨM","lesson":18,"ex":[["この新品の時計はとても高いです。","Chiếc đồng hồ mới này rất đắt."],["新品のかばんを買ったので、古いかばんは捨てます。","Vì đã mua túi mới nên tôi sẽ vứt túi cũ đi."],["新品の本はきれいですが、高いです。","Sách mới thì đẹp nhưng đắt."],["田中さんは新品のパソコンを使っています。","Anh Tanaka đang dùng máy tính mới."],["この店には新品の服がたくさんあります。","Cửa hàng này có rất nhiều quần áo mới."]]},{"word":"手に入れる","reading":"てにいれる","meaning":"đạt được, có được","hanViet":"THỦ NHẬP","lesson":18,"ex":[["やっと欲しい本を手に入れました。","Cuối cùng tôi cũng có được cuốn sách mình muốn."],["田中さんは新しい仕事を手に入れました。","Anh Tanaka đã có được công việc mới."],["この切手はなかなか手に入れません。","Con tem này rất khó có được."],["小さいとき、欲しい本を手に入れるのは難しかったです。","Khi còn nhỏ, việc có được cuốn sách mình muốn rất khó."],["友達のおかげで、古い写真を手に入れました。","Nhờ bạn bè, tôi đã có được tấm ảnh cũ."]]},{"word":"ざらに","reading":"","meaning":"khá phổ biến, thông thường","hanViet":"","lesson":18,"ex":[["この町の近くには、小さい店がざらにあります。","Gần thị trấn này có rất nhiều cửa hàng nhỏ."],["東京には高いビルがざらにあります。","Ở Tokyo có rất nhiều tòa nhà cao."],["この本屋には古い本がざらにあります。","Hiệu sách này có rất nhiều sách cũ."],["京都には古い神社がざらにあります。","Ở Kyoto có rất nhiều đền cổ."],["春になると、あの公園には花がざらにあります。","Khi xuân đến, ở công viên đó có rất nhiều hoa."]]},{"word":"目をとめる","reading":"めをとめる","meaning":"chú ý, nhìn vào","hanViet":"MỤC","lesson":18,"ex":[["田中さんは新しい時計に目をとめました。","Anh Tanaka đã chú ý đến chiếc đồng hồ mới."],["本屋でおもしろい本に目をとめました。","Tôi đã chú ý đến một cuốn sách thú vị ở hiệu sách."],["先生は子どもの絵に目をとめました。","Thầy giáo đã chú ý đến bức tranh của đứa trẻ."],["きれいな花に目をとめて、写真をとりました。","Tôi chú ý đến bông hoa đẹp và đã chụp ảnh."],["母は新しい服に目をとめました。","Mẹ tôi đã chú ý đến bộ quần áo mới."]]},{"word":"しょうゆさし","reading":"","meaning":"chai nước tương","hanViet":"","lesson":18,"ex":[["しょうゆさしがこわれたので、新しいしょうゆさしを買います。","Vì chai nước tương bị vỡ nên tôi sẽ mua chai mới."],["しょうゆさしを台所の棚に置きます。","Tôi đặt chai nước tương lên kệ trong bếp."],["母はしょうゆさしをきれいに洗います。","Mẹ tôi rửa sạch chai nước tương."],["しょうゆさしからしょうゆが少し出ました。","Nước tương chảy ra một ít từ chai."],["このしょうゆさしは小さくて、かわいいです。","Chai nước tương này nhỏ và dễ thương."]]},{"word":"食塩","reading":"しょくえん","meaning":"muối","hanViet":"THỰC DIÊM","lesson":18,"ex":[["料理に食塩を少し入れます。","Tôi cho một ít muối vào món ăn."],["食塩が少ししかないので、店で買います。","Vì chỉ còn một ít muối nên tôi sẽ mua ở cửa hàng."],["この料理は食塩が多くて、味が濃いです。","Món ăn này nhiều muối nên vị đậm."],["食塩は台所の棚にあります。","Muối ở trên kệ trong bếp."],["食塩を入れすぎると、料理がまずくなります。","Nếu cho quá nhiều muối, món ăn sẽ trở nên dở."]]},{"word":"流し台","reading":"ながしだい","meaning":"bồn rửa","hanViet":"LƯU ĐÀI","lesson":18,"ex":[["流し台の水が流れません。","Nước ở bồn rửa không chảy."],["流し台で手を洗います。","Tôi rửa tay ở bồn rửa."],["母は流し台をきれいにふきます。","Mẹ tôi lau sạch bồn rửa."],["流し台の下にごみ箱があります。","Dưới bồn rửa có thùng rác."],["新しい流し台は大きくて、使いやすいです。","Bồn rửa mới to và dễ dùng."]]},{"word":"排水パイプ","reading":"はいすいパイプ","meaning":"ống thoát nước","hanViet":"BÀI THỦY","lesson":18,"ex":[["排水パイプがこわれたので、修理屋を呼びます。","Vì ống thoát nước bị hỏng nên tôi gọi thợ sửa chữa."],["排水パイプから水が漏れています。","Nước đang rò rỉ từ ống thoát nước."],["古い排水パイプを新しい排水パイプと取り替えます。","Tôi thay ống thoát nước cũ bằng ống mới."],["排水パイプの水が流れません。","Nước trong ống thoát nước không chảy."],["田中さんは排水パイプを直しました。","Anh Tanaka đã sửa ống thoát nước."]]},{"word":"排水","reading":"はいすい","meaning":"thoát nước","hanViet":"BÀI THỦY","lesson":18,"ex":[["雨のあと、排水が悪くなりました。","Sau cơn mưa, việc thoát nước trở nên kém."],["この建物の排水はよくありません。","Việc thoát nước của tòa nhà này không tốt."],["台所の排水のために、排水パイプを直します。","Để thoát nước ở bếp, tôi sửa ống thoát nước."],["台所の排水が遅いです。","Nước thoát ở bếp rất chậm."],["排水がうまくいかないので、修理屋を呼びます。","Vì thoát nước không tốt nên tôi gọi thợ sửa chữa."]]},{"word":"修理屋","reading":"しゅうりや","meaning":"thợ sửa chữa","hanViet":"TU LÝ ỐC","lesson":18,"ex":[["修理屋が来て、洗濯機を直しました。","Thợ sửa chữa đã đến và sửa máy giặt."],["修理屋を呼んだので、午後三時に来ます。","Tôi đã gọi thợ sửa chữa nên họ sẽ đến lúc 3 giờ chiều."],["この修理屋は仕事が速くて、安いです。","Thợ sửa chữa này làm việc nhanh và rẻ."],["修理屋にテレビを直してもらいました。","Tôi đã nhờ thợ sửa chữa sửa tivi."],["修理屋は排水パイプを直して、帰りました。","Thợ sửa chữa đã sửa ống thoát nước rồi về."]]},{"word":"ちらちら","reading":"","meaning":"loáng thoáng, thoáng qua","hanViet":"","lesson":18,"ex":[["雪がちらちらと降っています。","Tuyết đang rơi lất phất."],["遠くに花がちらちらと見えます。","Từ xa có thể thấy hoa thấp thoáng."],["星がちらちらと輝いています。","Ngôi sao đang lấp lánh."],["テレビの画面がちらちらしています。","Màn hình tivi đang nhấp nháy."],["ちらちらと雨が降ってきました。","Mưa bắt đầu rơi lất phất."]]},{"word":"マニアック","reading":"","meaning":"cuồng, mê mẩn quá mức, chuyên sâu quá mức","hanViet":"","lesson":18,"ex":[["田中さんはマニアックな切手のコレクターです。","Anh Tanaka là người sưu tầm tem cuồng nhiệt."],["彼はマニアックな本をたくさん集めています。","Anh ấy sưu tầm rất nhiều sách chuyên sâu."],["マニアックな趣味の話はおもしろいです。","Chuyện về sở thích cuồng nhiệt rất thú vị."],["山田さんはマニアックな音楽が好きです。","Anh Yamada thích nhạc chuyên sâu."],["マニアックな映画の話を友達としました。","Tôi đã nói chuyện về phim chuyên sâu với bạn bè."]]},{"word":"コレクター","reading":"","meaning":"người sưu tầm","hanViet":"","lesson":18,"ex":[["田中さんは切手のコレクターです。","Anh Tanaka là người sưu tầm tem."],["コレクターは古い本をたくさん集めています。","Người sưu tầm sưu tập rất nhiều sách cũ."],["あのコレクターは珍しい時計を持っています。","Người sưu tầm đó có chiếc đồng hồ hiếm."],["コレクターの家には本がたくさんあります。","Nhà của người sưu tầm có rất nhiều sách."],["友達は切手のコレクターになりました。","Bạn tôi đã trở thành người sưu tầm tem."]]},{"word":"知る由もない","reading":"しるよしもない","meaning":"không có cách nào để biết","hanViet":"TRI DO","lesson":18,"ex":[["彼はどこにいるか、知る由もありません。","Anh ấy đang ở đâu, tôi không có cách nào biết được."],["あの店がいつ開くか、知る由もありません。","Cửa hàng đó mở cửa lúc nào, tôi không có cách nào biết được."],["彼女が何を考えているか、知る由もありません。","Cô ấy đang nghĩ gì, tôi không có cách nào biết được."],["田中さんがなぜ来なかったか、知る由もありません。","Tại sao anh Tanaka không đến, tôi không có cách nào biết được."],["明日の天気がどうなるか、知る由もありません。","Thời tiết ngày mai sẽ ra sao, tôi không có cách nào biết được."]]},{"word":"鋭い","reading":"するどい","meaning":"sắc bén","hanViet":"NHUỆ","lesson":18,"ex":[["この包丁は鋭くて、よく切れます。","Con dao này sắc và cắt tốt."],["彼は鋭い目で私を見ました。","Anh ấy nhìn tôi bằng ánh mắt sắc bén."],["鋭いナイフでパンを切ります。","Tôi cắt bánh mì bằng con dao sắc."],["犬は鋭い歯を持っています。","Con chó có hàm răng sắc."],["鋭い質問に答えるのは難しいです。","Trả lời câu hỏi sắc bén rất khó."]]},{"word":"視線","reading":"しせん","meaning":"ánh nhìn","hanViet":"THỊ TUYẾN","lesson":18,"ex":[["先生の視線が私に向かいました。","Ánh nhìn của thầy giáo hướng về phía tôi."],["彼の視線は窓の外にありました。","Ánh nhìn của anh ấy ở ngoài cửa sổ."],["子どもの視線はおもちゃに向かっています。","Ánh nhìn của đứa trẻ đang hướng về phía đồ chơi."],["みんなの視線が田中さんに集まりました。","Ánh nhìn của mọi người tập trung vào anh Tanaka."],["みんなの視線の中で、田中さんは話しました。","Trước ánh nhìn của mọi người, anh Tanaka đã nói chuyện."]]},{"word":"走らす（視線を～）","reading":"はしらす（しせんを～）","meaning":"quét (ánh nhìn)","hanViet":"TẨU THỊ TUYẾN","lesson":18,"ex":[["田中さんは部屋に視線を走らせました。","Anh Tanaka quét ánh nhìn khắp phòng."],["先生は生徒たちに視線を走らせました。","Thầy giáo quét ánh nhìn qua các học sinh."],["彼女は本棚に視線を走らせました。","Cô ấy quét ánh nhìn qua giá sách."],["母は台所に視線を走らせました。","Mẹ tôi quét ánh nhìn khắp bếp."],["私は教室に視線を走らせて、友達を探しました。","Tôi quét ánh nhìn khắp lớp học và tìm bạn bè."]]},{"word":"見当","reading":"けんとう","meaning":"đoán","hanViet":"KIẾN ĐƯƠNG","lesson":18,"ex":[["荷物の重さの見当をつけました。","Tôi đã ước lượng trọng lượng của hành lý."],["先生は生徒の数の見当をつけました。","Thầy giáo đã ước lượng số học sinh."],["見当をつけて、箱の大きさを決めました。","Tôi ước lượng rồi quyết định kích cỡ của hộp."],["旅行のお金の見当をつけました。","Tôi đã ước lượng tiền cho chuyến đi."],["見当をつけるのは難しいです。","Việc ước lượng rất khó."]]},{"word":"つく（見当が～）","reading":"つく（けんとうが～）","meaning":"có thể (đoán)","hanViet":"KIẾN ĐƯƠNG","lesson":18,"ex":[["この問題の答えは見当がつきません。","Tôi không đoán được đáp án của bài toán này."],["田中さんがどこにいるか、見当がつきません。","Anh Tanaka đang ở đâu, tôi không đoán được."],["彼女が何を言いたいか、見当がつきました。","Tôi đã đoán được cô ấy muốn nói gì."],["この箱の中に何があるか、見当がつきません。","Trong hộp này có gì, tôi không đoán được."],["あの人の名前は見当がつきません。","Tôi không đoán được tên của người đó."]]},{"word":"雑然","reading":"ざつぜん","meaning":"sự bừa bãi, lộn xộn","hanViet":"TẠP NHIÊN","lesson":18,"ex":[["部屋の中は雑然としています。","Trong phòng rất bừa bãi."],["雑然とした部屋を整理します。","Tôi dọn dẹp căn phòng bừa bãi."],["机の上は雑然としています。","Trên bàn rất bừa bãi."],["雑然とした本棚を整理しました。","Tôi đã dọn dẹp giá sách bừa bãi."],["子どもの部屋は雑然としています。","Phòng của đứa trẻ rất bừa bãi."]]},{"word":"ちらばる","reading":"","meaning":"bị vứt lung tung, bị vứt rải rác","hanViet":"","lesson":18,"ex":[["おもちゃが部屋にちらばっています。","Đồ chơi vứt lung tung trong phòng."],["本が机の上にちらばっています。","Sách vứt lung tung trên bàn."],["紙が床にちらばっています。","Giấy vứt lung tung trên sàn."],["服が部屋にちらばっているので、整理します。","Vì quần áo vứt lung tung trong phòng nên tôi sẽ dọn dẹp."],["子どものおもちゃが廊下にちらばっています。","Đồ chơi của đứa trẻ vứt lung tung ở hành lang."]]},{"word":"手に取る","reading":"てにとる","meaning":"cầm lấy, nhặt lấy","hanViet":"THỦ THỦ","lesson":18,"ex":[["本を手に取って、読みました。","Tôi cầm lấy cuốn sách và đọc."],["田中さんはコップを手に取りました。","Anh Tanaka cầm lấy cái cốc."],["母はりんごを手に取って、洗いました。","Mẹ tôi cầm lấy quả táo và rửa."],["彼は手紙を手に取って、読みました。","Anh ấy cầm lấy bức thư và đọc."],["店で新しい時計を手に取りました。","Tôi cầm lấy chiếc đồng hồ mới ở cửa hàng."]]},{"word":"ごく","reading":"","meaning":"rất","hanViet":"","lesson":18,"ex":[["この本はごく普通の本です。","Cuốn sách này là cuốn sách rất bình thường."],["彼はごく小さい声で話しました。","Anh ấy nói bằng giọng rất nhỏ."],["ごく簡単な質問です。","Đây là câu hỏi rất đơn giản."],["ごく普通の家に住んでいます。","Tôi sống trong ngôi nhà rất bình thường."],["ごく短い時間で終わりました。","Việc kết thúc trong thời gian rất ngắn."]]},{"word":"あたりまえ","reading":"","meaning":"thông thường, đương nhiên","hanViet":"","lesson":18,"ex":[["毎日ごはんを食べるのはあたりまえです。","Ăn cơm mỗi ngày là chuyện đương nhiên."],["あたりまえのことですが、勉強は大切です。","Đó là chuyện đương nhiên, nhưng học tập rất quan trọng."],["約束を守るのはあたりまえです。","Giữ lời hứa là chuyện đương nhiên."],["子どもが両親を大切にするのはあたりまえです。","Con cái quý trọng cha mẹ là chuyện đương nhiên."],["彼は毎日運動するのがあたりまえです。","Việc anh ấy tập thể dục mỗi ngày là chuyện đương nhiên."]]},{"word":"手動式","reading":"しゅどうしき","meaning":"kiểu vận hành bằng tay, loại chạy bằng tay","hanViet":"THỦ ĐỘNG THỨC","lesson":18,"ex":[["この時計は手動式です。","Chiếc đồng hồ này là loại chạy bằng tay."],["手動式のドアは重いです。","Cửa loại mở bằng tay rất nặng."],["手動式の時計は毎日回します。","Đồng hồ chạy bằng tay thì mỗi ngày phải lên dây."],["この店には手動式の時計がたくさんあります。","Cửa hàng này có rất nhiều đồng hồ chạy bằng tay."],["手動式の時計を買いました。","Tôi đã mua đồng hồ chạy bằng tay."]]},{"word":"何ひとつない","reading":"なにひとつない","meaning":"không có một chút gì","hanViet":"HÀ","lesson":18,"ex":[["部屋には何ひとつない。","Trong phòng không có gì cả."],["箱の中には何ひとつありません。","Trong hộp không có gì cả."],["冷蔵庫には何ひとつないので、買い物します。","Trong tủ lạnh không có gì cả nên tôi sẽ đi mua sắm."],["机の上には何ひとつありません。","Trên bàn không có gì cả."],["彼は何ひとつない部屋に住んでいます。","Anh ấy sống trong căn phòng không có gì cả."]]},{"word":"金属","reading":"きんぞく","meaning":"kim loại","hanViet":"KIM THUỘC","lesson":18,"ex":[["この時計は金属でできています。","Chiếc đồng hồ này được làm bằng kim loại."],["金属のドアは重いです。","Cửa kim loại rất nặng."],["金属のコップは冷たいです。","Cốc kim loại lạnh."],["このナイフは金属でできています。","Con dao này được làm bằng kim loại."],["金属の時計は高いです。","Đồng hồ kim loại đắt."]]},{"word":"錆びつく","reading":"さびつく","meaning":"rỉ sét","hanViet":"","lesson":18,"ex":[["古いナイフが錆びつきました。","Con dao cũ đã bị rỉ sét."],["自転車が錆びつきました。","Xe đạp đã bị rỉ sét."],["金属のドアが錆びつきました。","Cửa kim loại đã bị rỉ sét."],["古い時計が錆びついて、動きません。","Đồng hồ cũ bị rỉ sét nên không chạy."],["錆びついたナイフはもう使いません。","Tôi không dùng con dao bị rỉ sét nữa."]]},{"word":"錆びる","reading":"さびる","meaning":"rỉ sét","hanViet":"","lesson":18,"ex":[["古い自転車が錆びました。","Xe đạp cũ đã bị rỉ."],["金属のドアが錆びました。","Cửa kim loại đã bị rỉ."],["包丁が錆びないように、よくふきます。","Để dao không bị rỉ, tôi lau kỹ."],["雨にぬれている自転車は錆びます。","Xe đạp bị ướt mưa sẽ bị rỉ."],["錆びた時計を直しました。","Tôi đã sửa chiếc đồng hồ bị rỉ."]]},{"word":"てっぺん","reading":"","meaning":"đỉnh, chóp","hanViet":"","lesson":18,"ex":[["山のてっぺんに雪があります。","Trên đỉnh núi có tuyết."],["木のてっぺんに鳥がいます。","Trên ngọn cây có con chim."],["ビルのてっぺんから町が見えます。","Từ đỉnh tòa nhà có thể thấy thị trấn."],["彼は山のてっぺんに立ちました。","Anh ấy đứng trên đỉnh núi."],["木のてっぺんに花が咲いています。","Trên ngọn cây hoa đang nở."]]},{"word":"シール","reading":"","meaning":"nhãn dán","hanViet":"","lesson":18,"ex":[["本にシールをはりました。","Tôi đã dán nhãn lên sách."],["子どもはシールが好きです。","Đứa trẻ thích nhãn dán."],["シールを箱にはりました。","Tôi đã dán nhãn lên hộp."],["このシールはきれいです。","Nhãn dán này đẹp."],["シールを箱からとりました。","Tôi đã lấy nhãn dán ra khỏi hộp."]]},{"word":"要するに","reading":"ようするに","meaning":"nói cách khác, tóm lại là","hanViet":"YẾU","lesson":18,"ex":[["要するに、彼は来ません。","Tóm lại là, anh ấy sẽ không đến."],["要するに、この本はおもしろいです。","Tóm lại là, cuốn sách này thú vị."],["要するに、時間がありません。","Tóm lại là, không có thời gian."],["要するに、田中さんは忙しいです。","Tóm lại là, anh Tanaka bận."],["要するに、私は行きたくありません。","Tóm lại là, tôi không muốn đi."]]},{"word":"刃","reading":"は","meaning":"lưỡi dao","hanViet":"NHẬN","lesson":18,"ex":[["包丁の刃が鋭いです。","Lưỡi dao sắc bén."],["刃が錆びたので、新しい包丁を買います。","Vì lưỡi dao bị rỉ nên tôi sẽ mua dao mới."],["ナイフの刃でパンを切ります。","Tôi cắt bánh mì bằng lưỡi dao."],["刃がこわれた包丁は捨てます。","Tôi vứt con dao có lưỡi bị hỏng."],["この刃はとても鋭いです。","Lưỡi dao này rất sắc."]]},{"word":"かみあわせ","reading":"","meaning":"sự ăn khớp, khớp vào nhau","hanViet":"","lesson":18,"ex":[["このドアのかみあわせが悪いです。","Độ ăn khớp của cửa này không tốt."],["かみあわせが悪いので、ドアが閉まりません。","Vì ăn khớp không tốt nên cửa không đóng được."],["時計のかみあわせを直しました。","Tôi đã sửa độ ăn khớp của đồng hồ."],["かみあわせがいいと、ドアがよく開きます。","Nếu ăn khớp tốt, cửa sẽ mở tốt."],["この箱のかみあわせはいいです。","Độ ăn khớp của hộp này tốt."]]},{"word":"タイプ","reading":"","meaning":"kiểu, loại","hanViet":"","lesson":18,"ex":[["このタイプの車が好きです。","Tôi thích kiểu xe này."],["新しいタイプの時計を買いました。","Tôi đã mua đồng hồ kiểu mới."],["彼はおもしろいタイプの人です。","Anh ấy là người kiểu thú vị."],["このタイプの本はあまり読みません。","Tôi ít đọc sách kiểu này."],["どのタイプの時計がいいですか。","Đồng hồ kiểu nào tốt?"]]},{"word":"削りかす","reading":"けずりかす","meaning":"mạt gọt, vụn gọt","hanViet":"TƯỚC","lesson":18,"ex":[["鉛筆の削りかすを捨てます。","Tôi vứt mạt gọt bút chì đi."],["机の上に鉛筆の削りかすがあります。","Trên bàn có mạt gọt bút chì."],["削りかすが床にちらばっています。","Mạt gọt vứt lung tung trên sàn."],["鉛筆を削ると、削りかすが出ます。","Khi gọt bút chì, mạt gọt sẽ ra."],["削りかすを集めて、捨てました。","Tôi đã gom mạt gọt lại và vứt đi."]]},{"word":"微妙 (に)","reading":"びみょう (に)","meaning":"tinh tế, hơi một chút; khó nói, mập mờ","hanViet":"VI DIỆU","lesson":18,"ex":[["この料理の味は微妙です。","Vị của món ăn này thật tinh tế."],["彼の答えは微妙でした。","Câu trả lời của anh ấy thật khó nói."],["微妙に色が違います。","Màu sắc hơi khác một chút."],["天気は微妙です。","Thời tiết thật khó nói."],["彼の気持ちは微妙です。","Cảm xúc của anh ấy thật khó tả."]]},{"word":"最新式","reading":"さいしんしき","meaning":"mẫu mới nhất, kiểu mới nhất","hanViet":"TỐI TÂN THỨC","lesson":18,"ex":[["最新式のテレビを買いました。","Tôi đã mua tivi mẫu mới nhất."],["この最新式の車は速いです。","Chiếc xe mẫu mới nhất này chạy nhanh."],["最新式のパソコンは高いです。","Máy tính mẫu mới nhất đắt."],["最新式の時計を使っています。","Tôi đang dùng đồng hồ mẫu mới nhất."],["この店には最新式の洗濯機があります。","Cửa hàng này có máy giặt mẫu mới nhất."]]},{"word":"持ち歩く","reading":"もちあるく","meaning":"mang theo","hanViet":"TRÌ BỘ","lesson":18,"ex":[["いつもカメラを持ち歩きます。","Tôi luôn mang theo máy ảnh."],["田中さんは本を持ち歩きます。","Anh Tanaka luôn mang theo sách."],["かばんの中に辞書を持ち歩きます。","Tôi mang theo từ điển trong túi."],["傘を持ち歩くと、雨のときに便利です。","Mang theo ô thì tiện khi trời mưa."],["彼は時計を持ち歩きません。","Anh ấy không mang theo đồng hồ."]]},{"word":"超～（～短編小説）","reading":"ちょう～（～たんぺんしょうせつ）","meaning":"siêu ~ (~ truyện ngắn)","hanViet":"SIÊU ĐOẠN BIÊN TIỂU THUYẾT","lesson":18,"ex":[["超短編小説を読みました。","Tôi đã đọc truyện siêu ngắn."],["彼は超短編小説を書きました。","Anh ấy đã viết truyện siêu ngắn."],["この超短編小説はおもしろいです。","Truyện siêu ngắn này thú vị."],["超短編小説は短いので、すぐ読めます。","Truyện siêu ngắn ngắn nên đọc xong ngay."],["田中さんは超短編小説が好きです。","Anh Tanaka thích truyện siêu ngắn."]]},{"word":"短編小説","reading":"たんぺんしょうせつ","meaning":"truyện ngắn","hanViet":"ĐOẠN BIÊN TIỂU THUYẾT","lesson":18,"ex":[["短編小説を読みました。","Tôi đã đọc truyện ngắn."],["彼は短編小説を書きました。","Anh ấy đã viết truyện ngắn."],["この短編小説はおもしろいです。","Truyện ngắn này thú vị."],["短編小説の本を買いました。","Tôi đã mua sách truyện ngắn."],["田中さんは短編小説が好きです。","Anh Tanaka thích truyện ngắn."]]},{"word":"意外（な）","reading":"いがい（な）","meaning":"ngoài dự tính, không ngờ đến","hanViet":"DĨ NGOẠI","lesson":18,"ex":[["彼の答えは意外でした。","Câu trả lời của anh ấy thật bất ngờ."],["意外なことに、田中さんは来ました。","Thật bất ngờ, anh Tanaka đã đến."],["この店は意外に安いです。","Cửa hàng này rẻ một cách bất ngờ."],["意外な人から手紙が来ました。","Tôi nhận được thư từ một người bất ngờ."],["試験は意外に易しかったです。","Bài thi dễ một cách bất ngờ."]]},{"word":"満足（する）","reading":"まんぞく（する）","meaning":"thỏa mãn","hanViet":"MÃN TÚC","lesson":18,"ex":[["この料理に満足しています。","Tôi hài lòng với món ăn này."],["田中さんは仕事に満足しています。","Anh Tanaka hài lòng với công việc."],["試験の結果に満足しました。","Tôi hài lòng với kết quả bài thi."],["新しい家に満足しています。","Tôi hài lòng với ngôi nhà mới."],["彼は今の生活に満足しています。","Anh ấy hài lòng với cuộc sống hiện tại."]]},{"word":"価値観","reading":"かちかん","meaning":"giá trị quan","hanViet":"GIÁ TRỊ QUAN","lesson":18,"ex":[["人の価値観は違います。","Giá trị quan của mỗi người khác nhau."],["価値観が違うと、わかりにくいです。","Khi giá trị quan khác nhau thì khó hiểu nhau."],["田中さんと私の価値観は違います。","Giá trị quan của anh Tanaka và tôi khác nhau."],["価値観は人によって違います。","Giá trị quan khác nhau tùy người."],["若い人の価値観は変わります。","Giá trị quan của người trẻ thay đổi."]]},{"word":"異なる","reading":"ことなる","meaning":"khác","hanViet":"DỊ","lesson":18,"ex":[["人の意見は異なります。","Ý kiến của mỗi người khác nhau."],["この二つの本は異なります。","Hai cuốn sách này khác nhau."],["田中さんの意見は私と異なります。","Ý kiến của anh Tanaka khác với tôi."],["国によって、習慣は異なります。","Tùy theo quốc gia, phong tục khác nhau."],["彼の答えは私の答えと異なります。","Câu trả lời của anh ấy khác với câu trả lời của tôi."]]},{"word":"行為","reading":"こうい","meaning":"hành vi","hanViet":"HÀNH VI","lesson":18,"ex":[["人を助ける行為はすばらしいです。","Hành vi giúp đỡ người khác thật tuyệt vời."],["その行為はよくありません。","Hành vi đó không tốt."],["子どもをほめる行為は大切です。","Hành vi khen ngợi trẻ em rất quan trọng."],["彼の行為はすばらしいです。","Hành vi của anh ấy thật tuyệt vời."],["悪い行為をしてはいけません。","Không được làm hành vi xấu."]]},{"word":"シナリオ","reading":"","meaning":"kịch bản","hanViet":"","lesson":18,"ex":[["映画のシナリオを書きました。","Tôi đã viết kịch bản phim."],["このドラマのシナリオはおもしろいです。","Kịch bản của bộ phim truyền hình này thú vị."],["シナリオを読んで、映画を見ました。","Tôi đọc kịch bản rồi xem phim."],["彼はシナリオを書く仕事をしています。","Anh ấy làm công việc viết kịch bản."],["このシナリオは短いです。","Kịch bản này ngắn."]]},{"word":"角度","reading":"かくど","meaning":"góc độ","hanViet":"GIÁC ĐỘ","lesson":18,"ex":[["違う角度から見ると、よくわかります。","Nhìn từ góc độ khác thì sẽ hiểu rõ."],["写真の角度を変えました。","Tôi đã đổi góc chụp ảnh."],["角度を変えて、考えてみました。","Tôi thử đổi góc độ và suy nghĩ."],["この角度から見る花はきれいです。","Hoa nhìn từ góc độ này rất đẹp."],["いろいろな角度から問題を考えます。","Tôi suy nghĩ vấn đề từ nhiều góc độ."]]},{"word":"うらやましい","reading":"","meaning":"ghen tị","hanViet":"","lesson":18,"ex":[["田中さんがうらやましいです。","Tôi ghen tị với anh Tanaka."],["彼の新しい車がうらやましいです。","Tôi ghen tị với chiếc xe mới của anh ấy."],["彼女の生活がうらやましいです。","Tôi ghen tị với cuộc sống của cô ấy."],["うらやましい話を聞きました。","Tôi đã nghe câu chuyện khiến người ta ghen tị."],["友達の旅行がうらやましいです。","Tôi ghen tị với chuyến du lịch của bạn bè."]]},{"word":"じっと","reading":"","meaning":"chăm chú; đứng yên, bất động","hanViet":"","lesson":18,"ex":[["子どもはじっとテレビを見ています。","Đứa trẻ chăm chú xem tivi."],["彼はじっと私を見ました。","Anh ấy nhìn chằm chằm vào tôi."],["猫はじっと魚を見ています。","Con mèo chăm chú nhìn con cá."],["先生はじっと生徒を見ました。","Thầy giáo chăm chú nhìn học sinh."],["じっと立って、話を聞きました。","Tôi đứng yên và lắng nghe câu chuyện."]]},{"word":"見つめる","reading":"みつめる","meaning":"nhìn chằm chằm","hanViet":"KIẾN","lesson":18,"ex":[["彼は星を見つめています。","Anh ấy đang nhìn chằm chằm vào ngôi sao."],["子どもはおもちゃを見つめています。","Đứa trẻ đang nhìn chằm chằm vào đồ chơi."],["彼女は写真を見つめました。","Cô ấy đã nhìn chằm chằm vào bức ảnh."],["猫は魚を見つめています。","Con mèo đang nhìn chằm chằm vào con cá."],["田中さんは空を見つめました。","Anh Tanaka đã nhìn chằm chằm lên bầu trời."]]},{"word":"いらいら（する）","reading":"","meaning":"sốt ruột, khó chịu","hanViet":"","lesson":18,"ex":[["電車が遅れて、いらいらしています。","Tàu điện đến muộn nên tôi sốt ruột."],["仕事が多くて、いらいらします。","Công việc nhiều nên tôi khó chịu."],["彼は待たされて、いらいらしました。","Anh ấy phải đợi lâu nên sốt ruột."],["雨が続いて、いらいらします。","Mưa kéo dài nên tôi khó chịu."],["いらいらしないで、ゆっくり話してください。","Đừng sốt ruột, hãy nói từ từ."]]},{"word":"気に入る","reading":"きにいる","meaning":"thích","hanViet":"KHÍ NHẬP","lesson":18,"ex":[["この時計が気に入りました。","Tôi thích chiếc đồng hồ này."],["新しい家が気に入っています。","Tôi thích ngôi nhà mới."],["田中さんはこの本が気に入りました。","Anh Tanaka thích cuốn sách này."],["この服が気に入ったので、買いました。","Vì thích bộ quần áo này nên tôi đã mua."],["彼女は新しい仕事が気に入っています。","Cô ấy thích công việc mới."]]},{"word":"仲直り（する）","reading":"なかなおり（する）","meaning":"làm lành, làm hòa","hanViet":"TRỌNG TRỰC","lesson":18,"ex":[["友達と仲直りしました。","Tôi đã làm hòa với bạn bè."],["田中さんと山田さんは仲直りしました。","Anh Tanaka và anh Yamada đã làm hòa."],["彼女と仲直りして、うれしいです。","Tôi làm hòa với cô ấy nên rất vui."],["仲直りするために、手紙を書きました。","Để làm hòa, tôi đã viết thư."],["二人はやっと仲直りしました。","Hai người cuối cùng đã làm hòa."]]},{"word":"不満","reading":"ふまん","meaning":"bất mãn, không hài lòng","hanViet":"BẤT MÃN","lesson":18,"ex":[["仕事に不満があります。","Tôi có điều không hài lòng về công việc."],["彼は新しい家に不満があります。","Anh ấy có điều không hài lòng về ngôi nhà mới."],["不満を先生に話しました。","Tôi đã nói điều không hài lòng với thầy giáo."],["料理に不満はありません。","Tôi không có điều gì không hài lòng về món ăn."],["不満が多いと、仕事が楽しくありません。","Nếu có nhiều điều không hài lòng, công việc sẽ không vui."]]},{"word":"非難（する）","reading":"ひなん（する）","meaning":"trách móc, phê phán","hanViet":"PHI NAN","lesson":18,"ex":[["彼は友達を非難しました。","Anh ấy đã trách móc bạn bè."],["人を非難するのはよくありません。","Trách móc người khác là không tốt."],["田中さんは私を非難しました。","Anh Tanaka đã trách móc tôi."],["彼を非難しないでください。","Xin đừng trách móc anh ấy."],["非難する前に、話を聞いてください。","Trước khi trách móc, hãy lắng nghe câu chuyện."]]},{"word":"皮肉","reading":"ひにく","meaning":"giễu cợt, châm chọc, mỉa mai","hanViet":"BÌ NHỤC","lesson":18,"ex":[["彼は皮肉を言いました。","Anh ấy đã nói lời mỉa mai."],["皮肉を言うのはよくありません。","Nói mỉa mai là không tốt."],["田中さんはいつも皮肉を言います。","Anh Tanaka luôn nói mỉa mai."],["皮肉を言われて、いらいらしました。","Bị nói mỉa mai nên tôi khó chịu."],["彼は皮肉が好きです。","Anh ấy thích mỉa mai."]]},{"word":"ワイングラス","reading":"","meaning":"ly uống rượu vang","hanViet":"","lesson":18,"ex":[["ワイングラスを棚に並べます。","Tôi xếp ly rượu vang lên kệ."],["ワイングラスが割れました。","Ly rượu vang đã vỡ."],["新しいワイングラスを買いました。","Tôi đã mua ly rượu vang mới."],["ワイングラスでワインを飲みます。","Tôi uống rượu vang bằng ly rượu vang."],["ワイングラスをきれいに洗います。","Tôi rửa sạch ly rượu vang."]]},{"word":"捜し物","reading":"さがしもの","meaning":"đồ vật đang tìm kiếm","hanViet":"SƯU VẬT","lesson":18,"ex":[["捜し物が見つかりません。","Tôi không tìm thấy đồ vật đang tìm."],["捜し物はどこにありますか。","Đồ vật đang tìm ở đâu?"],["捜し物を見つけました。","Tôi đã tìm thấy đồ vật đang tìm."],["捜し物を探しています。","Tôi đang tìm đồ vật."],["捜し物は机の上にありました。","Đồ vật đang tìm ở trên bàn."]]},{"word":"しょっちゅう","reading":"","meaning":"thường xuyên, lúc nào cũng","hanViet":"","lesson":18,"ex":[["彼はしょっちゅう電車に遅れます。","Anh ấy thường xuyên đến muộn tàu điện."],["しょっちゅう雨が降ります。","Trời thường xuyên mưa."],["田中さんはしょっちゅう本を買います。","Anh Tanaka thường xuyên mua sách."],["しょっちゅう電話がかかります。","Điện thoại thường xuyên reo."],["しょっちゅう友達に会います。","Tôi thường xuyên gặp bạn bè."]]},{"word":"欠ける（カップが～）","reading":"かける","meaning":"(tách) bị mẻ, bị sứt","hanViet":"KHIẾM","lesson":18,"ex":[["カップが欠けました。","Cái tách bị mẻ."],["コップが欠けたので、捨てます。","Vì cái cốc bị mẻ nên tôi vứt đi."],["皿が欠けています。","Cái đĩa bị mẻ."],["欠けたカップは使いません。","Tôi không dùng cái tách bị mẻ."],["カップが欠けないように、気をつけます。","Tôi cẩn thận để tách không bị mẻ."]]},{"word":"しまい込む","reading":"しまいこむ","meaning":"cất giữ","hanViet":"","lesson":18,"ex":[["本を箱にしまい込みました。","Tôi đã cất sách vào hộp."],["古い服を箱にしまい込みました。","Tôi đã cất quần áo cũ vào hộp."],["子どものおもちゃを箱にしまい込みます。","Tôi cất đồ chơi của đứa trẻ vào hộp."],["写真をアルバムにしまい込みました。","Tôi đã cất ảnh vào album."],["冬の服を箱にしまい込みました。","Tôi đã cất quần áo mùa đông vào hộp."]]},{"word":"だって","reading":"","meaning":"vì, chả là","hanViet":"","lesson":18,"ex":[["だって、雨が降っています。","Vì trời đang mưa mà."],["だって、田中さんは忙しいです。","Vì anh Tanaka bận mà."],["だって、時間がないんです。","Vì không có thời gian mà."],["だって、彼はいつも遅れます。","Vì anh ấy lúc nào cũng đến muộn mà."],["だって、お金がありません。","Vì không có tiền mà."]]},{"word":"新婚","reading":"しんこん","meaning":"mới cưới","hanViet":"TÂN HÔN","lesson":18,"ex":[["新婚の二人は東京に住んでいます。","Hai vợ chồng mới cưới sống ở Tokyo."],["新婚の生活は楽しいです。","Cuộc sống mới cưới rất vui."],["田中さんは新婚です。","Anh Tanaka mới cưới."],["新婚の夫婦は旅行に行きました。","Cặp vợ chồng mới cưới đã đi du lịch."],["新婚の二人は小さい家に住んでいます。","Hai vợ chồng mới cưới sống trong ngôi nhà nhỏ."]]},{"word":"思い出","reading":"おもいで","meaning":"kỷ niệm","hanViet":"TƯ XUẤT","lesson":18,"ex":[["小さいときの思い出がたくさんあります。","Tôi có rất nhiều kỷ niệm thời nhỏ."],["思い出の写真を見ました。","Tôi đã xem ảnh kỷ niệm."],["旅行の思い出を話しました。","Tôi đã kể kỷ niệm chuyến du lịch."],["思い出を大切にします。","Tôi trân trọng kỷ niệm."],["この歌は思い出の歌です。","Bài hát này là bài hát kỷ niệm."]]},{"word":"思い切る","reading":"おもいきる","meaning":"quyết tâm","hanViet":"TƯ THIẾT","lesson":18,"ex":[["思い切って、新しい仕事を始めました。","Tôi đã quyết tâm bắt đầu công việc mới."],["思い切って、高い時計を買いました。","Tôi đã quyết tâm mua chiếc đồng hồ đắt."],["彼は思い切って、旅行に行きました。","Anh ấy đã quyết tâm đi du lịch."],["思い切って、田中さんに話しました。","Tôi đã quyết tâm nói chuyện với anh Tanaka."],["思い切って、古い本を捨てました。","Tôi đã quyết tâm vứt sách cũ đi."]]},{"word":"そもそも","reading":"","meaning":"vốn dĩ, vốn là","hanViet":"","lesson":18,"ex":[["そもそも、彼は来るつもりがありません。","Vốn dĩ, anh ấy không có ý định đến."],["そもそも、この話は本当ですか。","Vốn dĩ, câu chuyện này có thật không?"],["そもそも、なぜ彼は怒っているのですか。","Vốn dĩ, tại sao anh ấy lại giận?"],["そもそも、私は行きたくありません。","Vốn dĩ, tôi không muốn đi."],["そもそも、時間がないんです。","Vốn dĩ, không có thời gian mà."]]},{"word":"とる（場所を～）","reading":"とる（ばしょを～）","meaning":"chiếm (chỗ)","hanViet":"TRƯỜNG SỞ","lesson":18,"ex":[["この箱は場所をとります。","Cái hộp này chiếm chỗ."],["大きい机は場所をとります。","Cái bàn to chiếm chỗ."],["本が多すぎて、場所をとります。","Sách quá nhiều nên chiếm chỗ."],["古い自転車は場所をとります。","Xe đạp cũ chiếm chỗ."],["この本棚は場所をとりません。","Giá sách này không chiếm chỗ."]]},{"word":"栓","reading":"せん","meaning":"nút chai","hanViet":"THUYÊN","lesson":18,"ex":[["栓を抜いて、ワインを飲みます。","Tôi mở nút chai và uống rượu vang."],["瓶の栓が開きません。","Nút chai không mở được."],["栓が硬いです。","Nút chai cứng."],["栓を閉めて、瓶を置きます。","Tôi đóng nút chai và đặt chai xuống."],["この瓶の栓は小さいです。","Nút của chai này nhỏ."]]},{"word":"抜く（栓を～）","reading":"ぬく（せんを～）","meaning":"mở (nút)","hanViet":"BẠT THUYÊN","lesson":18,"ex":[["栓を抜きました。","Tôi đã mở nút chai."],["栓を抜いて、ワインを飲みました。","Tôi đã mở nút chai và uống rượu vang."],["田中さんは栓を抜きました。","Anh Tanaka đã mở nút chai."],["栓を抜くのは難しいです。","Mở nút chai rất khó."],["栓を抜いて、瓶の中を見ました。","Tôi mở nút chai và nhìn vào trong chai."]]},{"word":"平気（な）","reading":"へいき（な）","meaning":"bình thường, không có chuyện gì","hanViet":"BÌNH KHÍ","lesson":18,"ex":[["彼は平気です。","Anh ấy bình thường, không sao."],["平気な顔で話しました。","Anh ấy nói chuyện với vẻ mặt bình thường."],["寒くても、彼は平気です。","Dù lạnh, anh ấy vẫn bình thường."],["試験でも、彼女は平気でした。","Dù là bài thi, cô ấy vẫn bình thường."],["平気なふりをしました。","Anh ấy giả vờ bình thường."]]},{"word":"おまけに","reading":"","meaning":"hơn nữa, thêm vào đó","hanViet":"","lesson":18,"ex":[["雨が降りました。おまけに、風も強いです。","Trời mưa. Hơn nữa, gió cũng mạnh."],["彼は忙しいです。おまけに、電車も遅れました。","Anh ấy bận. Hơn nữa, tàu điện cũng đến muộn."],["この本はおもしろいです。おまけに、安いです。","Cuốn sách này thú vị. Hơn nữa, còn rẻ."],["田中さんは速いです。おまけに、仕事も上手です。","Anh Tanaka nhanh. Hơn nữa, công việc cũng giỏi."],["きょうは暑いです。おまけに、雨も降ります。","Hôm nay nóng. Hơn nữa, trời còn mưa."]]},{"word":"気がない","reading":"きがない","meaning":"không quan tâm","hanViet":"KHÍ","lesson":18,"ex":[["彼は勉強に気がないです。","Anh ấy không quan tâm đến việc học."],["田中さんは旅行に気がないです。","Anh Tanaka không quan tâm đến du lịch."],["彼女は音楽に気がないです。","Cô ấy không quan tâm đến âm nhạc."],["彼はその話に気がないです。","Anh ấy không quan tâm đến câu chuyện đó."],["子どもは野菜に気がないです。","Đứa trẻ không quan tâm đến rau."]]},{"word":"そんなに","reading":"","meaning":"đến mức đó, nhiều đến thế","hanViet":"","lesson":18,"ex":[["そんなに忙しくありません。","Không bận đến thế."],["そんなに高くありません。","Không đắt đến thế."],["そんなに難しくないです。","Không khó đến thế."],["そんなに食べません。","Tôi không ăn nhiều đến thế."],["そんなに急がなくてもいいです。","Không cần vội đến thế."]]},{"word":"中断（する）","reading":"ちゅうだん（する）","meaning":"ngắt, dừng","hanViet":"TRUNG ĐOẠN","lesson":18,"ex":[["会議を中断しました。","Tôi đã tạm dừng cuộc họp."],["勉強を中断して、休みました。","Tôi tạm dừng việc học và nghỉ ngơi."],["雨で試合が中断しました。","Trận đấu bị tạm dừng vì mưa."],["仕事を中断しないでください。","Xin đừng tạm dừng công việc."],["話を中断して、電話に出ました。","Tôi tạm dừng câu chuyện và nghe điện thoại."]]},{"word":"のぞく","reading":"","meaning":"nhìn trộm, hé nhìn","hanViet":"","lesson":18,"ex":[["窓から部屋をのぞきました。","Tôi hé nhìn vào phòng từ cửa sổ."],["子どもはドアからのぞいています。","Đứa trẻ đang hé nhìn từ cửa."],["彼は箱の中をのぞきました。","Anh ấy hé nhìn vào trong hộp."],["田中さんは教室をのぞきました。","Anh Tanaka hé nhìn vào lớp học."],["猫は箱の中をのぞいています。","Con mèo đang hé nhìn vào trong hộp."]]},{"word":"シェアハウス","reading":"","meaning":"nhà ở chung","hanViet":"","lesson":18,"ex":[["シェアハウスに住んでいます。","Tôi sống trong nhà ở chung."],["田中さんはシェアハウスに住んでいます。","Anh Tanaka sống trong nhà ở chung."],["シェアハウスは家賃が安いです。","Nhà ở chung có tiền thuê rẻ."],["シェアハウスで友達と暮らしています。","Tôi sống cùng bạn bè trong nhà ở chung."],["シェアハウスの生活は楽しいです。","Cuộc sống trong nhà ở chung rất vui."]]},{"word":"散らかす","reading":"ちらかす","meaning":"làm vương vãi, vứt lung tung","hanViet":"TÁN","lesson":18,"ex":[["子どもが部屋におもちゃを散らかしました。","Đứa trẻ đã vứt đồ chơi lung tung trong phòng."],["机の上に本を散らかさないでください。","Đừng vứt sách lung tung trên bàn."],["強い風が、庭に紙を散らかしました。","Cơn gió mạnh đã thổi giấy vương vãi khắp sân."],["弟は部屋を散らかす癖があります。","Em trai tôi có thói quen làm phòng bừa bộn."],["帰る前に、散らかした服を片づけましょう。","Trước khi về, hãy dọn những bộ quần áo vứt lung tung."]]},{"word":"乱雑","reading":"らんざつ","meaning":"bừa bãi, lộn xộn","hanViet":"LOẠN TẠP","lesson":18,"ex":[["彼の机の上はいつも乱雑です。","Trên bàn của anh ấy lúc nào cũng bừa bãi."],["乱雑な部屋では、ゆっくり休めません。","Trong căn phòng bừa bộn, không thể nghỉ ngơi thoải mái được."],["本棚が乱雑なので、本が見つかりません。","Vì giá sách bừa bộn nên không tìm thấy sách."],["引っ越した後で、部屋はまだ乱雑です。","Sau khi chuyển nhà, phòng vẫn còn bừa bộn."],["乱雑な字で手紙を書きました。","Tôi đã viết thư bằng chữ viết lộn xộn."]]},{"word":"監督","reading":"かんとく","meaning":"đạo diễn","hanViet":"GIÁM ĐỐC","lesson":18,"ex":[["この映画の監督は、とても有名な人です。","Đạo diễn của bộ phim này là một người rất nổi tiếng."],["監督は俳優に細かいことを教えました。","Đạo diễn đã chỉ bảo diễn viên những điều tỉ mỉ."],["田中さんは新しい映画の監督をしています。","Anh Tanaka đang làm đạo diễn cho bộ phim mới."],["監督の話を聞いて、俳優たちは頑張りました。","Nghe đạo diễn nói, các diễn viên đã cố gắng."],["その監督は、毎年すばらしい映画を作ります。","Đạo diễn đó mỗi năm đều làm những bộ phim tuyệt vời."]]},{"word":"持ち主","reading":"もちぬし","meaning":"chủ sở hữu","hanViet":"TRÌ CHỦ","lesson":18,"ex":[["この財布の持ち主は、だれですか。","Chủ sở hữu của chiếc ví này là ai?"],["落とし物の持ち主が見つかりました。","Đã tìm thấy chủ sở hữu của đồ đánh rơi."],["かばんの持ち主は、まだ来ていません。","Chủ sở hữu của chiếc cặp vẫn chưa đến."],["持ち主がわからないので、警察に届けました。","Vì không biết chủ sở hữu là ai nên tôi đã mang đến đồn cảnh sát."],["駅で見つけた傘の持ち主を探しています。","Tôi đang tìm chủ sở hữu của chiếc ô nhặt được ở ga."]]},{"word":"きく（口を～）","reading":"きく（くちを～）","meaning":"nói (chuyện với ai)","hanViet":"KHẨU","lesson":18,"ex":[["彼は怒っていて、私と口をききません。","Anh ấy đang giận nên không nói chuyện với tôi."],["子どもは知らない人と口をききませんでした。","Đứa trẻ đã không nói chuyện với người lạ."],["久しぶりに会った友達とたくさん口をききました。","Tôi đã nói chuyện rất nhiều với người bạn lâu ngày mới gặp."],["先生は生徒たちとよく口をききます。","Thầy giáo thường nói chuyện với các học sinh."],["母は私と口をきいてくれません。","Mẹ không nói chuyện với tôi."]]},{"word":"跳ぶ","reading":"とぶ","meaning":"nhảy","hanViet":"KHIÊU","lesson":18,"ex":[["子どもがベッドの上で跳んでいます。","Đứa trẻ đang nhảy trên giường."],["猫が高い壁を跳びました。","Con mèo đã nhảy qua bức tường cao."],["うれしくて、彼は高く跳びました。","Vì vui mừng, anh ấy đã nhảy lên cao."],["池に石を投げると、魚が跳びました。","Khi ném đá xuống ao, cá đã nhảy lên."],["選手は高く跳ぶ練習をしています。","Vận động viên đang luyện tập nhảy cao."]]},{"word":"推測（する）","reading":"すいそく（する）","meaning":"suy đoán","hanViet":"SUY TRẮC","lesson":18,"ex":[["空を見て、雨が降ると推測しました。","Nhìn trời, tôi suy đoán rằng trời sẽ mưa."],["彼の話から、理由を推測することができます。","Từ câu chuyện của anh ấy, có thể suy đoán được lý do."],["結果を推測するのは、難しいです。","Việc suy đoán kết quả rất khó."],["私は彼が来ないと推測しています。","Tôi suy đoán rằng anh ấy sẽ không đến."],["データから、将来の人口を推測します。","Từ dữ liệu, người ta suy đoán dân số trong tương lai."]]},{"word":"花嫁","reading":"はなよめ","meaning":"cô dâu","hanViet":"HOA GIÁ","lesson":18,"ex":[["花嫁は白い服を着ています。","Cô dâu đang mặc trang phục màu trắng."],["結婚式で、花嫁はとても美しかったです。","Trong lễ cưới, cô dâu rất xinh đẹp."],["花嫁は幸せそうに笑っていました。","Cô dâu cười trông rất hạnh phúc."],["私の友達が来月、花嫁になります。","Bạn tôi tháng sau sẽ trở thành cô dâu."],["花嫁の母は、うれしくて泣きました。","Mẹ của cô dâu đã khóc vì vui mừng."]]},{"word":"かなう","reading":"","meaning":"thành hiện thực","hanViet":"","lesson":18,"ex":[["長い間の夢が、やっとかないました。","Ước mơ bao lâu nay cuối cùng đã thành hiện thực."],["彼の夢がかないますように。","Mong rằng ước mơ của anh ấy sẽ thành hiện thực."],["努力すれば、夢はかなうと思います。","Tôi nghĩ nếu nỗ lực thì ước mơ sẽ thành hiện thực."],["小さいころからの夢がかないました。","Ước mơ từ khi còn nhỏ đã thành hiện thực."],["その夢は、なかなかかないませんでした。","Ước mơ đó mãi vẫn chưa thành hiện thực."]]},{"word":"不平","reading":"ふへい","meaning":"bất bình","hanViet":"BẤT BÌNH","lesson":18,"ex":[["彼は仕事について、不平を言いました。","Anh ấy đã phàn nàn về công việc."],["不平を言わないで、頑張りましょう。","Đừng phàn nàn, hãy cố gắng lên."],["社員は給料に不平を持っています。","Nhân viên bất bình về tiền lương."],["彼女は天気に不平を言っています。","Cô ấy đang phàn nàn về thời tiết."],["不平を言う前に、自分で考えてみましょう。","Trước khi phàn nàn, hãy tự mình suy nghĩ thử."]]},{"word":"活躍（する）","reading":"かつやく（する）","meaning":"hoạt động tích cực, tỏa sáng, đóng vai trò nổi bật","hanViet":"HOẠT DƯỢC","lesson":18,"ex":[["彼はサッカーの試合で活躍しました。","Anh ấy đã thi đấu nổi bật trong trận bóng đá."],["若い選手が世界で活躍しています。","Vận động viên trẻ đang tỏa sáng trên thế giới."],["彼女は会社で活躍する社員です。","Cô ấy là nhân viên hoạt động tích cực trong công ty."],["彼は、いろいろな場所で活躍しています。","Anh ấy đang hoạt động tích cực ở nhiều nơi khác nhau."],["日本の俳優が海外でも活躍しています。","Diễn viên Nhật Bản cũng đang tỏa sáng ở nước ngoài."]]},{"word":"基礎","reading":"きそ","meaning":"căn bản","hanViet":"CƠ SỞ","lesson":18,"ex":[["日本語の基礎をしっかり勉強しましょう。","Hãy học thật chắc phần căn bản của tiếng Nhật."],["スポーツでは、基礎が大切です。","Trong thể thao, nền tảng cơ bản rất quan trọng."],["基礎がしっかりしていないと、上達できません。","Nếu nền tảng không vững chắc thì không thể tiến bộ được."],["彼は基礎から英語を習っています。","Anh ấy đang học tiếng Anh từ căn bản."],["基礎を身につけることが大切です。","Việc nắm vững kiến thức cơ bản rất quan trọng."]]},{"word":"置く（本屋に～）","reading":"おく（ほんやに～）","meaning":"có (ở hiệu sách)","hanViet":"TRÍ BẢN ỐC","lesson":18,"ex":[["この本は、駅前の本屋に置いてあります。","Cuốn sách này có bán ở hiệu sách trước ga."],["新しい辞書は、どこの本屋にも置いてあります。","Cuốn từ điển mới hiệu sách nào cũng có bán."],["あの本屋には、日本語の本がたくさん置いてあります。","Ở hiệu sách đó có rất nhiều sách tiếng Nhật."],["この雑誌は本屋に置いていませんでした。","Tạp chí này không có ở hiệu sách."],["人気の本は、すぐ本屋に置かれます。","Sách nổi tiếng sẽ sớm có mặt ở hiệu sách."]]},{"word":"維持（する）","reading":"いじ（する）","meaning":"duy trì","hanViet":"DUY TRÌ","lesson":18,"ex":[["健康を維持するために、毎日運動します。","Để duy trì sức khỏe, tôi tập thể dục mỗi ngày."],["彼は元気を維持しています。","Anh ấy đang duy trì sức khỏe tốt."],["彼はいい成績を維持しています。","Anh ấy đang duy trì thành tích học tập tốt."],["平和を維持することは、大切です。","Việc duy trì hòa bình rất quan trọng."],["いい関係を維持するには、話し合うことが大切です。","Để duy trì mối quan hệ tốt, việc trò chuyện rất quan trọng."]]},{"word":"おしゃれ","reading":"","meaning":"hợp thời trang, trưng diện","hanViet":"","lesson":18,"ex":[["彼女はいつもおしゃれな服を着ています。","Cô ấy lúc nào cũng mặc trang phục hợp thời trang."],["その店は、おしゃれなコーヒーショップです。","Cửa hàng đó là một quán cà phê thời thượng."],["おしゃれな帽子を買いました。","Tôi đã mua một chiếc mũ hợp thời trang."],["彼はおしゃれに気を使います。","Anh ấy rất chú ý đến thời trang."],["東京には、おしゃれな店がたくさんあります。","Ở Tokyo có rất nhiều cửa hàng thời trang."]]},{"word":"コミュニケーション","reading":"","meaning":"giao tiếp","hanViet":"","lesson":18,"ex":[["コミュニケーションは、人と人とのつながりです。","Giao tiếp là sự kết nối giữa người với người."],["日本語を話すには、コミュニケーションが大切です。","Để nói tiếng Nhật, giao tiếp rất quan trọng."],["コミュニケーションが上手な人は、友達が多いです。","Người giao tiếp giỏi có nhiều bạn bè."],["家族とのコミュニケーションを大切にしましょう。","Hãy trân trọng giao tiếp với gia đình."],["仕事では、コミュニケーションがとても重要です。","Trong công việc, giao tiếp rất quan trọng."]]},{"word":"ふさわしい","reading":"","meaning":"phù hợp, tương ứng","hanViet":"","lesson":18,"ex":[["この服は、結婚式にふさわしいです。","Bộ trang phục này phù hợp với lễ cưới."],["彼はその仕事にふさわしい人です。","Anh ấy là người phù hợp với công việc đó."],["子どもにふさわしい本を選びました。","Tôi đã chọn cuốn sách phù hợp với trẻ em."],["この場所は、静かに勉強するのにふさわしいです。","Nơi này phù hợp để học tập yên tĩnh."],["ふさわしい言葉が、なかなか見つかりません。","Mãi vẫn không tìm được từ ngữ phù hợp."]]},{"word":"出し忘れる","reading":"だしわすれる","meaning":"quên gửi, quên nộp, quên mang ra","hanViet":"XUẤT VONG","lesson":18,"ex":[["手紙を出し忘れました。","Tôi đã quên gửi thư."],["ごみを出し忘れたので、部屋にごみがたまりました。","Vì quên đổ rác nên rác chất đống trong phòng."],["宿題を出し忘れて、先生に怒られました。","Vì quên nộp bài tập nên tôi đã bị thầy mắng."],["レポートを出し忘れないように、気をつけます。","Tôi cẩn thận để không quên nộp báo cáo."],["彼は大切な書類を出し忘れました。","Anh ấy đã quên nộp tài liệu quan trọng."]]},{"word":"素直（な）","reading":"すなお（な）","meaning":"thành thật","hanViet":"TỐ TRỰC","lesson":18,"ex":[["彼は素直な人で、みんなに愛されています。","Anh ấy là người thật thà nên được mọi người yêu mến."],["子どもは素直に自分の気持ちを話しました。","Đứa trẻ đã nói thật lòng cảm xúc của mình."],["素直に謝ることは、大切です。","Việc xin lỗi một cách chân thành rất quan trọng."],["彼女は素直に間違いを認めました。","Cô ấy đã thành thật thừa nhận lỗi sai của mình."],["素直な気持ちで、話を聞きましょう。","Hãy lắng nghe câu chuyện với tấm lòng chân thành."]]},{"word":"癖","reading":"くせ","meaning":"tật, thói quen","hanViet":"PHÍCH","lesson":18,"ex":[["彼は髪を触る癖があります。","Anh ấy có thói quen sờ tóc."],["悪い癖を直すのは、難しいです。","Việc sửa thói quen xấu rất khó."],["母には、朝六時に起きる癖があります。","Mẹ tôi có thói quen dậy lúc 6 giờ sáng."],["彼は話すときに、手を動かす癖があります。","Anh ấy có thói quen cử động tay khi nói chuyện."],["癖を直すために、毎日気をつけています。","Để sửa thói quen, tôi chú ý mỗi ngày."]]},{"word":"ずっと（ずうっと）","reading":"","meaning":"liên tục, suốt","hanViet":"","lesson":18,"ex":[["ずっと雨が降っています。","Trời mưa suốt."],["彼はずっと日本に住んでいます。","Anh ấy sống ở Nhật suốt từ trước đến nay."],["ずっと同じ仕事をしています。","Tôi làm cùng một công việc suốt."],["子どものころから、ずっとピアノを習っています。","Từ khi còn nhỏ, tôi học piano suốt."],["ずっと待っていましたが、彼は来ませんでした。","Tôi đã đợi suốt nhưng anh ấy không đến."]]},{"word":"いわば","reading":"","meaning":"có thể nói như là","hanViet":"","lesson":18,"ex":[["彼は、いわば私の先生です。","Có thể nói anh ấy như là thầy của tôi."],["この本は、いわば日本語の教科書です。","Cuốn sách này có thể nói như là sách giáo khoa tiếng Nhật."],["インターネットは、いわば世界の図書館です。","Internet có thể nói như là thư viện của thế giới."],["彼は、いわばチームのリーダーです。","Có thể nói anh ấy là thủ lĩnh của đội."],["母は、いわば家族の太陽です。","Có thể nói mẹ là mặt trời của gia đình."]]},{"word":"咳払い","reading":"せきばらい","meaning":"hắng giọng, đằng hắng","hanViet":"KHÁI PHẤT","lesson":18,"ex":[["先生は咳払いをして、話を始めました。","Thầy giáo hắng giọng rồi bắt đầu nói chuyện."],["彼は咳払いをしてから、質問に答えました。","Anh ấy hắng giọng rồi trả lời câu hỏi."],["会議の前に、社長は咳払いをしました。","Trước cuộc họp, giám đốc đã hắng giọng."],["咳払いをして、彼はゆっくり話しました。","Hắng giọng xong, anh ấy nói chậm rãi."],["緊張して、何回も咳払いをしました。","Vì căng thẳng, tôi đã hắng giọng nhiều lần."]]},{"word":"昨夜","reading":"さくや","meaning":"đêm qua","hanViet":"TẠC DẠ","lesson":18,"ex":[["昨夜、雨がたくさん降りました。","Đêm qua trời đã mưa rất nhiều."],["昨夜は、友達と映画を見ました。","Đêm qua, tôi đã xem phim cùng bạn."],["昨夜遅くまで、勉強をしていました。","Đêm qua tôi đã học đến khuya."],["昨夜、地震がありました。","Đêm qua đã có động đất."],["昨夜のテレビで、面白い番組を見ました。","Đêm qua tôi đã xem chương trình thú vị trên TV."]]},{"word":"ものすごい","reading":"","meaning":"khủng khiếp","hanViet":"","lesson":18,"ex":[["ものすごい雨が降っています。","Trời đang mưa khủng khiếp."],["彼はものすごい力でドアを開けました。","Anh ấy đã mở cửa bằng sức mạnh khủng khiếp."],["ものすごい数の人が集まりました。","Một số lượng người khủng khiếp đã tụ tập."],["その映画は、ものすごい人気があります。","Bộ phim đó nổi tiếng khủng khiếp."],["ものすごい音がして、みんな驚きました。","Có tiếng động khủng khiếp nên mọi người đều giật mình."]]},{"word":"試す","reading":"ためす","meaning":"thử","hanViet":"THÍ","lesson":18,"ex":[["新しい料理を試してみました。","Tôi đã thử món ăn mới."],["この方法を試してみましょう。","Hãy thử phương pháp này xem."],["彼は新しい靴を試しています。","Anh ấy đang thử đôi giày mới."],["力を試すために、試験を受けました。","Để thử sức mình, tôi đã tham gia kỳ thi."],["まず、この薬を試してください。","Trước tiên, hãy thử loại thuốc này."]]},{"word":"超える","reading":"こえる","meaning":"vượt quá","hanViet":"SIÊU","lesson":18,"ex":[["この町の人口は、一万人を超えました。","Dân số của thị trấn này đã vượt quá 10.000 người."],["参加者の数が百を超えました。","Số người tham gia đã vượt quá 100."],["彼は前の成績を超えるために、毎日練習しています。","Để vượt qua thành tích trước đây, anh ấy luyện tập mỗi ngày."],["売上げが去年を超えました。","Doanh thu đã vượt qua năm ngoái."],["この川の水は、橋を超えました。","Nước sông này đã tràn qua cầu."]]},{"word":"口癖","reading":"くちぐせ","meaning":"câu cửa miệng, quen mồm","hanViet":"KHẨU PHÍCH","lesson":18,"ex":[["彼の口癖は、「そうですね」です。","Câu cửa miệng của anh ấy là \"そうですね\"."],["母の口癖は、「宿題をしなさい」です。","Câu cửa miệng của mẹ là \"Làm bài tập đi\"."],["先生の口癖は、学生にもよく知られています。","Câu cửa miệng của thầy giáo được học sinh biết rõ."],["私の口癖は、「大丈夫」です。","Câu cửa miệng của tôi là \"Không sao đâu\"."],["口癖を直すのは、難しいです。","Việc sửa câu cửa miệng rất khó."]]},{"word":"習得（する）","reading":"しゅうとく（する）","meaning":"học tập, lĩnh hội","hanViet":"TẬP ĐẮC","lesson":18,"ex":[["日本語を習得するために、毎日勉強しています。","Để lĩnh hội tiếng Nhật, tôi học mỗi ngày."],["新しい技術を習得しました。","Tôi đã lĩnh hội kỹ thuật mới."],["彼は英語を習得するのが速いです。","Anh ấy lĩnh hội tiếng Anh rất nhanh."],["技術を習得するには、時間がかかります。","Để lĩnh hội kỹ thuật cần có thời gian."],["彼女は短い時間で、日本語を習得しました。","Cô ấy đã lĩnh hội tiếng Nhật trong thời gian ngắn."]]},{"word":"味方","reading":"みかた","meaning":"đồng minh, người ủng hộ","hanViet":"VỊ PHƯƠNG","lesson":18,"ex":[["彼は私の味方です。","Anh ấy là người ủng hộ tôi."],["困ったとき、友達が味方になってくれました。","Khi gặp khó khăn, bạn bè đã đứng về phía tôi."],["味方が多いので、安心しています。","Vì có nhiều người ủng hộ nên tôi yên tâm."],["彼は敵ではなく、味方です。","Anh ấy không phải kẻ thù mà là đồng minh."],["みんなが私の味方になってくれました。","Mọi người đã đứng về phía tôi."]]},{"word":"ロボットコンテスト","reading":"","meaning":"cuộc thi chế tạo rô-bốt, cuộc thi robocon","hanViet":"","lesson":19,"ex":[["ロボットコンテストに、学生が参加しました。","Sinh viên đã tham gia cuộc thi chế tạo rô-bốt."],["今年のロボットコンテストは、東京で開かれます。","Cuộc thi rô-bốt năm nay được tổ chức ở Tokyo."],["彼はロボットコンテストで優勝しました。","Anh ấy đã giành chiến thắng trong cuộc thi rô-bốt."],["ロボットコンテストを見るために、東京へ行きました。","Để xem cuộc thi rô-bốt, tôi đã đến Tokyo."],["ロボットコンテストの準備をしています。","Tôi đang chuẩn bị cho cuộc thi rô-bốt."]]},{"word":"ものづくり","reading":"","meaning":"chế tạo, sản xuất","hanViet":"","lesson":19,"ex":[["日本のものづくりは、世界で有名です。","Ngành chế tạo của Nhật Bản nổi tiếng trên thế giới."],["ものづくりの技術を学びたいです。","Tôi muốn học kỹ thuật chế tạo."],["彼はものづくりの仕事をしています。","Anh ấy đang làm công việc chế tạo."],["ものづくりには、丁寧な仕事が必要です。","Chế tạo cần công việc tỉ mỉ."],["子どもたちにものづくりを教えています。","Tôi đang dạy trẻ em về chế tạo."]]},{"word":"人づくり","reading":"ひとづくり","meaning":"phát triển con người, phát triển nguồn nhân lực","hanViet":"NHÂN","lesson":19,"ex":[["人づくりは、国の未来にとって大切です。","Phát triển con người rất quan trọng đối với tương lai của đất nước."],["会社は人づくりに力を入れています。","Công ty đang chú trọng phát triển con người."],["人づくりとものづくりは、どちらも大切です。","Phát triển con người và chế tạo đều quan trọng."],["学校では、人づくりを大切にしています。","Ở trường học, người ta coi trọng việc phát triển con người."],["人づくりのために、教育にお金を使います。","Để phát triển con người, người ta chi tiền cho giáo dục."]]},{"word":"評価（する）","reading":"ひょうか（する）","meaning":"đánh giá","hanViet":"BÌNH GIÁ","lesson":19,"ex":[["先生は学生の発表を評価しました。","Thầy giáo đã đánh giá bài thuyết trình của sinh viên."],["この本は、高く評価されています。","Cuốn sách này được đánh giá cao."],["仕事の結果を評価することが大切です。","Việc đánh giá kết quả công việc rất quan trọng."],["彼は自分の力を正しく評価しています。","Anh ấy đánh giá đúng năng lực của mình."],["会社は社員の仕事を評価します。","Công ty đánh giá công việc của nhân viên."]]},{"word":"提言（する）","reading":"ていげん（する）","meaning":"khuyến nghị, đề nghị","hanViet":"ĐỀ NGÔN","lesson":19,"ex":[["研究者は、会社に提言しました。","Nhà nghiên cứu đã đưa ra khuyến nghị cho công ty."],["彼は環境問題について提言しました。","Anh ấy đã đưa ra khuyến nghị về vấn đề môi trường."],["新しい提言を、会議で話し合いました。","Khuyến nghị mới đã được thảo luận trong cuộc họp."],["提言する前に、よく調べることが大切です。","Trước khi đưa ra khuyến nghị, việc tìm hiểu kỹ rất quan trọng."],["市民の提言を、よく聞きましょう。","Hãy lắng nghe kỹ khuyến nghị của người dân."]]},{"word":"的確（な）","reading":"てきかく（な）","meaning":"rõ ràng, thích đáng","hanViet":"ĐÍCH XÁC","lesson":19,"ex":[["彼の答えは、とても的確でした。","Câu trả lời của anh ấy rất chính xác."],["的確な意見が、成功につながります。","Ý kiến chính xác dẫn đến thành công."],["先生は的確なアドバイスをくれました。","Thầy giáo đã cho tôi lời khuyên chính xác."],["的確な説明で、よくわかりました。","Nhờ lời giải thích rõ ràng, tôi đã hiểu rõ."],["彼は的確に問題を指摘しました。","Anh ấy đã chỉ ra vấn đề một cách chính xác."]]},{"word":"把握（する）","reading":"はあく（する）","meaning":"nắm rõ","hanViet":"BẢ ÁC","lesson":19,"ex":[["状況を把握することが大切です。","Việc nắm rõ tình hình rất quan trọng."],["彼は問題をよく把握しています。","Anh ấy nắm rõ vấn đề."],["全体を把握してから、仕事を始めましょう。","Sau khi nắm rõ toàn thể, hãy bắt đầu công việc."],["先生は学生の気持ちを把握しています。","Thầy giáo nắm rõ cảm xúc của học sinh."],["把握するために、データを調べました。","Để nắm rõ, tôi đã tìm hiểu dữ liệu."]]},{"word":"自慢話","reading":"じまんばなし","meaning":"chuyện khoe khoang","hanViet":"TỰ MẠN THOẠI","lesson":19,"ex":[["彼はよく自慢話をします。","Anh ấy thường khoe khoang."],["自慢話を聞くのは、詰まらないです。","Nghe chuyện khoe khoang thật chán."],["祖父は昔の自慢話が好きです。","Ông tôi thích kể chuyện khoe khoang ngày xưa."],["自慢話をしないで、話を聞きましょう。","Đừng khoe khoang nữa, hãy lắng nghe câu chuyện."],["彼の自慢話は、みんな知っています。","Chuyện khoe khoang của anh ấy, mọi người đều biết."]]},{"word":"まとまる","reading":"","meaning":"thống nhất, đâu vào đấy, được sắp xếp ổn thỏa","hanViet":"","lesson":19,"ex":[["話がまとまりました。","Câu chuyện đã được gói gọn lại."],["意見がまとまらないので、会議が長くなりました。","Vì ý kiến không thống nhất nên cuộc họp kéo dài."],["気持ちがまとまったら、話してください。","Khi đã suy nghĩ kỹ, hãy nói ra."],["チームの意見がまとまりました。","Ý kiến của đội đã thống nhất."],["計画がまとまるまで、時間がかかりました。","Mãi đến khi kế hoạch được gói gọn thì đã tốn nhiều thời gian."]]},{"word":"集まり","reading":"あつまり","meaning":"cuộc tụ họp","hanViet":"TẬP","lesson":19,"ex":[["友達の集まりに行きました。","Tôi đã đến buổi tụ họp của bạn bè."],["毎月、家族の集まりがあります。","Mỗi tháng đều có buổi tụ họp gia đình."],["集まりでは、いろいろな話をしました。","Trong buổi tụ họp, chúng tôi đã nói nhiều chuyện khác nhau."],["明日の集まりは、午後三時からです。","Buổi tụ họp ngày mai bắt đầu từ 3 giờ chiều."],["集まりの場所は、駅の近くです。","Địa điểm tụ họp ở gần ga."]]},{"word":"即席","reading":"そくせき","meaning":"ngay lập tức, ứng khẩu","hanViet":"TỨC TỊCH","lesson":19,"ex":[["即席のスピーチをしました。","Tôi đã phát biểu ứng khẩu."],["即席で料理を作りました。","Tôi đã nấu ăn ngay lập tức."],["彼は即席の答えを考えました。","Anh ấy đã nghĩ ra câu trả lời ngay lập tức."],["即席の会議が開かれました。","Cuộc họp đột xuất đã được tổ chức."],["即席で歌を歌いました。","Tôi đã hát ứng khẩu."]]},{"word":"取り組む","reading":"とりくむ","meaning":"nỗ lực, chú tâm","hanViet":"THỦ TỔ","lesson":19,"ex":[["彼は日本語の勉強に取り組んでいます。","Anh ấy đang chú tâm học tiếng Nhật."],["環境問題に取り組むことが大切です。","Việc chú tâm vào vấn đề môi trường rất quan trọng."],["新しい仕事に取り組んでいます。","Tôi đang chú tâm vào công việc mới."],["チームで問題に取り組みました。","Cả đội đã cùng nhau xử lý vấn đề."],["彼は難しい課題に取り組んでいます。","Anh ấy đang chú tâm vào nhiệm vụ khó khăn."]]},{"word":"やりとげる","reading":"","meaning":"hoàn thành trọn vẹn, làm xong xuôi","hanViet":"","lesson":19,"ex":[["彼は仕事をやりとげました。","Anh ấy đã hoàn thành công việc trọn vẹn."],["難しい仕事でも、やりとげるつもりです。","Dù công việc khó, tôi cũng quyết hoàn thành."],["最後までやりとげることが大切です。","Việc hoàn thành đến cùng rất quan trọng."],["彼は計画をやりとげました。","Anh ấy đã hoàn thành kế hoạch."],["一人で仕事をやりとげるのは、大変です。","Một mình hoàn thành công việc thật vất vả."]]},{"word":"産業用ロボット","reading":"さんぎょうようロボット","meaning":"rô-bốt công nghiệp","hanViet":"SẢN NGHIỆP DỤNG","lesson":19,"ex":[["工場では、産業用ロボットが働いています。","Trong nhà máy, rô-bốt công nghiệp đang làm việc."],["産業用ロボットは、車を作ります。","Rô-bốt công nghiệp chế tạo ô tô."],["産業用ロボットのおかげで、仕事が速くなりました。","Nhờ rô-bốt công nghiệp, công việc đã nhanh hơn."],["産業用ロボットの数が増えています。","Số lượng rô-bốt công nghiệp đang tăng lên."],["彼は産業用ロボットを研究しています。","Anh ấy đang nghiên cứu rô-bốt công nghiệp."]]},{"word":"無人探査ロボット","reading":"むじんたんさロボット","meaning":"rô-bốt thăm dò không người lái","hanViet":"VÔ NHÂN THÁM TRA","lesson":19,"ex":[["無人探査ロボットは、海の中を調べます。","Rô-bốt thăm dò không người lái khám phá dưới biển."],["無人探査ロボットが、月を調べています。","Rô-bốt thăm dò không người lái đang khám phá mặt trăng."],["無人探査ロボットは、人間が行けない場所へ行きます。","Rô-bốt thăm dò không người lái đi đến nơi con người không thể đến."],["無人探査ロボットの研究が進んでいます。","Nghiên cứu về rô-bốt thăm dò không người lái đang tiến triển."],["無人探査ロボットは、危険な場所で働きます。","Rô-bốt thăm dò không người lái làm việc ở nơi nguy hiểm."]]},{"word":"ペットロボット","reading":"","meaning":"rô-bốt thú nuôi","hanViet":"","lesson":19,"ex":[["ペットロボットは、子どもの友達です。","Rô-bốt thú nuôi là bạn của trẻ em."],["お年寄りはペットロボットと話します。","Người cao tuổi trò chuyện với rô-bốt thú nuôi."],["ペットロボットが、家で人気があります。","Rô-bốt thú nuôi được yêu thích trong nhà."],["ペットロボットは、犬と一緒に遊びます。","Rô-bốt thú nuôi chơi cùng với chó."],["新しいペットロボットを買いました。","Tôi đã mua rô-bốt thú nuôi mới."]]},{"word":"介護ロボット","reading":"かいごロボット","meaning":"rô-bốt điều dưỡng chăm sóc","hanViet":"GIỚI HỘ","lesson":19,"ex":[["介護ロボットは、お年寄りを助けます。","Rô-bốt điều dưỡng giúp đỡ người cao tuổi."],["病院では、介護ロボットが働いています。","Trong bệnh viện, rô-bốt điều dưỡng đang làm việc."],["介護ロボットのおかげで、介護がしやすくなりました。","Nhờ rô-bốt điều dưỡng, việc chăm sóc đã trở nên dễ dàng hơn."],["介護ロボットの研究が進んでいます。","Nghiên cứu về rô-bốt điều dưỡng đang tiến triển."],["介護ロボットは、将来もっと増えると思います。","Tôi nghĩ rô-bốt điều dưỡng trong tương lai sẽ tăng thêm."]]},{"word":"介護（する）","reading":"かいご（する）","meaning":"chăm sóc điều dưỡng","hanViet":"GIỚI HỘ","lesson":19,"ex":[["母は祖母を介護しています。","Mẹ tôi đang chăm sóc bà."],["お年寄りを介護する仕事をしています。","Tôi đang làm công việc chăm sóc người cao tuổi."],["介護をする人が増えています。","Số người làm công việc chăm sóc đang tăng lên."],["彼は父を介護するために、仕事をやめました。","Để chăm sóc cha, anh ấy đã nghỉ việc."],["介護は、大変な仕事です。","Chăm sóc điều dưỡng là công việc vất vả."]]},{"word":"効果","reading":"こうか","meaning":"hiệu quả","hanViet":"HIỆU QUẢ","lesson":19,"ex":[["この薬は、効果があります。","Loại thuốc này có hiệu quả."],["運動の効果で、体が元気になりました。","Nhờ hiệu quả của việc tập thể dục, cơ thể đã khỏe mạnh hơn."],["勉強の効果が、試験に出ました。","Hiệu quả của việc học đã thể hiện trong kỳ thi."],["効果を確かめるために、調べました。","Để kiểm tra hiệu quả, tôi đã tìm hiểu."],["この方法は、効果が高いです。","Phương pháp này có hiệu quả cao."]]},{"word":"箇所","reading":"かしょ","meaning":"nơi","hanViet":"CÁ SỞ","lesson":19,"ex":[["この文には、間違いが三箇所あります。","Trong câu này có ba chỗ sai."],["壊れた箇所を直しました。","Tôi đã sửa chỗ bị hỏng."],["問題の箇所を調べています。","Tôi đang tìm hiểu chỗ có vấn đề."],["この箇所は、よく読んでください。","Hãy đọc kỹ chỗ này."],["五箇所を直す必要があります。","Cần phải sửa năm chỗ."]]},{"word":"先頭","reading":"せんとう","meaning":"đầu","hanViet":"TIÊN ĐẦU","lesson":19,"ex":[["列の先頭に立っています。","Tôi đang đứng ở đầu hàng."],["先頭の車が止まりました。","Chiếc xe ở đầu đã dừng lại."],["先頭を歩く人が、道を教えます。","Người đi đầu sẽ chỉ đường."],["マラソンの先頭を走っています。","Tôi đang chạy ở vị trí dẫn đầu cuộc thi marathon."],["先頭に名前を書いてください。","Hãy viết tên ở đầu."]]},{"word":"第～（～一）","reading":"だい～（～いち）","meaning":"thứ ~ (~ thứ nhất)","hanViet":"ĐỆ NHẤT","lesson":19,"ex":[["第一の問題は、お金です。","Vấn đề thứ nhất là tiền."],["彼は第一になりました。","Anh ấy đã giành vị trí thứ nhất."],["第一に、健康が大切です。","Thứ nhất, sức khỏe quan trọng."],["第一の理由は、時間がなかったことです。","Lý do thứ nhất là không có thời gian."],["彼は第一の仕事を終えました。","Anh ấy đã hoàn thành công việc thứ nhất."]]},{"word":"結びつく","reading":"むすびつく","meaning":"dẫn đến","hanViet":"KẾT","lesson":19,"ex":[["努力は成功に結びつきます。","Nỗ lực dẫn đến thành công."],["勉強は将来に結びつきます。","Học tập dẫn đến tương lai."],["この経験は、仕事に結びつきました。","Kinh nghiệm này đã dẫn đến công việc."],["健康は幸せに結びつきます。","Sức khỏe dẫn đến hạnh phúc."],["いい結果は、努力に結びついています。","Kết quả tốt gắn liền với nỗ lực."]]},{"word":"提唱（する）","reading":"ていしょう（する）","meaning":"đề xuất","hanViet":"ĐỀ XƯỚNG","lesson":19,"ex":[["彼は新しい意見を提唱しました。","Anh ấy đã đề xuất ý kiến mới."],["先生は新しい方法を提唱しています。","Thầy giáo đang đề xuất phương pháp mới."],["環境を守ることを提唱しました。","Tôi đã đề xuất việc bảo vệ môi trường."],["彼は平和を提唱する人です。","Anh ấy là người đề xuất hòa bình."],["新しい教育を提唱する人が増えています。","Số người đề xuất nền giáo dục mới đang tăng lên."]]},{"word":"普及","reading":"ふきゅう","meaning":"phổ cập","hanViet":"PHỔ CẬP","lesson":19,"ex":[["インターネットが普及しました。","Internet đã phổ cập."],["ケータイが普及しました。","Điện thoại di động đã phổ cập."],["パソコンが普及して、仕事がしやすくなりました。","Máy tính đã phổ cập nên công việc trở nên dễ dàng hơn."],["日本語が世界に普及しています。","Tiếng Nhật đang phổ cập trên thế giới."],["新しい技術の普及は速いです。","Sự phổ cập của kỹ thuật mới rất nhanh."]]},{"word":"努める","reading":"つとめる","meaning":"phấn đấu, nỗ lực","hanViet":"NỖ","lesson":19,"ex":[["健康に努めています。","Tôi đang nỗ lực giữ gìn sức khỏe."],["彼は仕事に努めています。","Anh ấy đang nỗ lực trong công việc."],["日本語の勉強に努めましょう。","Hãy nỗ lực học tiếng Nhật."],["環境を守ることに努めています。","Tôi đang nỗ lực bảo vệ môi trường."],["彼は毎日、練習に努めています。","Anh ấy nỗ lực luyện tập mỗi ngày."]]},{"word":"課題","reading":"かだい","meaning":"nhiệm vụ, đề bài","hanViet":"KHÓA ĐỀ","lesson":19,"ex":[["今日の課題は、作文です。","Nhiệm vụ hôm nay là viết văn."],["課題を終えるために、頑張ります。","Để hoàn thành nhiệm vụ, tôi sẽ cố gắng."],["難しい課題に取り組んでいます。","Tôi đang chú tâm vào nhiệm vụ khó."],["課題がたくさんあって、忙しいです。","Có nhiều nhiệm vụ nên tôi bận."],["課題を提出しました。","Tôi đã nộp bài tập."]]},{"word":"達成（する）","reading":"たっせい（する）","meaning":"đạt được","hanViet":"ĐẠT THÀNH","lesson":19,"ex":[["彼は目的を達成しました。","Anh ấy đã đạt được mục đích."],["長い間の夢を達成しました。","Tôi đã đạt được ước mơ bao lâu nay."],["計画を達成するために、頑張ります。","Để đạt được kế hoạch, tôi sẽ cố gắng."],["彼は高い成績を達成しました。","Anh ấy đã đạt thành tích cao."],["達成するために、毎日練習しています。","Để đạt được, tôi luyện tập mỗi ngày."]]},{"word":"製作（する）","reading":"せいさく（する）","meaning":"chế tạo","hanViet":"CHẾ TÁC","lesson":19,"ex":[["彼はロボットを製作しています。","Anh ấy đang chế tạo rô-bốt."],["映画を製作する仕事をしています。","Tôi đang làm công việc sản xuất phim."],["新しい車を製作しました。","Tôi đã chế tạo chiếc xe mới."],["彼らは飛行機を製作しています。","Họ đang chế tạo máy bay."],["製作に時間がかかります。","Việc chế tạo tốn thời gian."]]},{"word":"競技（する）","reading":"きょうぎ（する）","meaning":"cạnh tranh, tranh tài","hanViet":"CẠNH KỸ","lesson":19,"ex":[["選手たちは競技をしています。","Các vận động viên đang thi đấu."],["スポーツの競技を見ました。","Tôi đã xem cuộc thi đấu thể thao."],["彼は競技で優勝しました。","Anh ấy đã giành chiến thắng trong cuộc thi đấu."],["競技する前に、練習をします。","Trước khi thi đấu, tôi luyện tập."],["いろいろな競技があります。","Có nhiều môn thi đấu khác nhau."]]},{"word":"高専","reading":"こうせん","meaning":"trường cao đẳng kỹ thuật","hanViet":"CAO CHUYÊN","lesson":19,"ex":[["彼は高専で勉強しています。","Anh ấy đang học ở trường cao đẳng kỹ thuật."],["高専の学生が、ロボットを作りました。","Sinh viên trường cao đẳng kỹ thuật đã chế tạo rô-bốt."],["高専では、技術を学びます。","Ở trường cao đẳng kỹ thuật, người ta học kỹ thuật."],["弟は高専に入りました。","Em trai tôi đã vào trường cao đẳng kỹ thuật."],["高専を卒業して、会社で働いています。","Sau khi tốt nghiệp trường cao đẳng kỹ thuật, tôi đang làm việc ở công ty."]]},{"word":"さて","reading":"","meaning":"nào","hanViet":"","lesson":19,"ex":[["さて、勉強を始めましょう。","Nào, hãy bắt đầu học thôi."],["さて、今日は何をしましょうか。","Nào, hôm nay chúng ta làm gì nhỉ."],["さて、話を続けましょう。","Nào, hãy tiếp tục câu chuyện."],["さて、次の問題は何ですか。","Nào, câu hỏi tiếp theo là gì?"],["さて、もう帰りましょう。","Nào, chúng ta về thôi."]]},{"word":"向上（する）","reading":"こうじょう（する）","meaning":"tăng cường, nâng cao","hanViet":"HƯỚNG THƯỢNG","lesson":19,"ex":[["日本語の力が向上しました。","Năng lực tiếng Nhật đã được nâng cao."],["技術の向上が大切です。","Việc nâng cao kỹ thuật rất quan trọng."],["成績を向上させるために、勉強しています。","Để nâng cao thành tích, tôi đang học."],["健康を向上させるために、運動します。","Để nâng cao sức khỏe, tôi tập thể dục."],["仕事の質が向上しました。","Chất lượng công việc đã được nâng cao."]]},{"word":"たんに","reading":"","meaning":"chỉ là, đơn thuần là, chỉ đơn giản là","hanViet":"","lesson":19,"ex":[["たんに、時間がなかっただけです。","Đơn giản là tôi không có thời gian."],["彼はたんに疲れていただけです。","Anh ấy đơn giản chỉ là mệt thôi."],["たんに間違えただけです。","Đơn giản chỉ là nhầm lẫn thôi."],["たんに、そう思っただけです。","Đơn giản là tôi chỉ nghĩ vậy thôi."],["彼はたんに忙しかっただけです。","Anh ấy đơn giản chỉ là bận thôi."]]},{"word":"削る","reading":"けずる","meaning":"gọt, giũa","hanViet":"TƯỚC","lesson":19,"ex":[["鉛筆を削ります。","Tôi gọt bút chì."],["大根を削りました。","Tôi đã gọt củ cải."],["木を削って、形を作ります。","Gọt gỗ để tạo hình."],["彼は鉛筆を削るのが上手です。","Anh ấy gọt bút chì rất giỏi."],["予算を削ることが必要です。","Việc cắt giảm ngân sách là cần thiết."]]},{"word":"欠ける","reading":"かける","meaning":"thiếu","hanViet":"KHIÊM","lesson":19,"ex":[["この本は、ページが欠けています。","Cuốn sách này bị thiếu trang."],["財布のお金が少し欠けています。","Tiền trong ví bị thiếu một ít."],["歯が欠けました。","Răng tôi bị sứt."],["この計画には、何かが欠けています。","Kế hoạch này còn thiếu điều gì đó."],["コップが欠けています。","Cái cốc bị sứt."]]},{"word":"創造（する）","reading":"そうぞう（する）","meaning":"sáng tạo","hanViet":"SÁNG TẠO","lesson":19,"ex":[["新しいものを創造することが大切です。","Việc sáng tạo ra cái mới rất quan trọng."],["彼はすばらしい作品を創造しました。","Anh ấy đã sáng tạo ra tác phẩm tuyệt vời."],["創造する力が必要です。","Cần có năng lực sáng tạo."],["子どもは自由に創造します。","Trẻ em sáng tạo một cách tự do."],["新しい世界を創造しましょう。","Hãy sáng tạo ra thế giới mới."]]},{"word":"添付（する）","reading":"てんぷ（する）","meaning":"đính kèm","hanViet":"THIÊM PHÓ","lesson":19,"ex":[["メールに写真を添付しました。","Tôi đã đính kèm ảnh vào email."],["書類をメールに添付してください。","Hãy đính kèm tài liệu vào email."],["添付したファイルを見てください。","Hãy xem tập tin đã đính kèm."],["資料を添付して、送りました。","Tôi đã đính kèm tài liệu và gửi đi."],["写真を添付するのを忘れました。","Tôi đã quên đính kèm ảnh."]]},{"word":"単純（な）","reading":"たんじゅん（な）","meaning":"đơn thuần, đơn giản","hanViet":"ĐƠN THUẦN","lesson":19,"ex":[["単純な問題です。","Đó là vấn đề đơn giản."],["彼の意見は単純です。","Ý kiến của anh ấy đơn giản."],["単純に考えましょう。","Hãy suy nghĩ đơn giản."],["この仕事は単純ですが、大切です。","Công việc này đơn giản nhưng quan trọng."],["単純な答えが、いい答えです。","Câu trả lời đơn giản là câu trả lời hay."]]},{"word":"独創（力）","reading":"どくそう（りょく）","meaning":"khả năng sáng tạo, năng lực sáng tạo","hanViet":"ĐỘC SÁNG LỰC","lesson":19,"ex":[["彼は独創力があります。","Anh ấy có năng lực sáng tạo."],["独創力が、仕事で大切です。","Năng lực sáng tạo rất quan trọng trong công việc."],["独創力を育てることが大切です。","Việc nuôi dưỡng năng lực sáng tạo rất quan trọng."],["彼の独創力は、すばらしいです。","Năng lực sáng tạo của anh ấy thật tuyệt vời."],["独創力のある人が、会社に必要です。","Công ty cần người có năng lực sáng tạo."]]},{"word":"養う","reading":"やしなう","meaning":"nuôi dưỡng","hanViet":"DƯỠNG","lesson":19,"ex":[["子どもを養うのは、大変です。","Nuôi dưỡng con cái thật vất vả."],["力を養うために、練習します。","Để nuôi dưỡng sức mạnh, tôi luyện tập."],["彼は犬を養っています。","Anh ấy đang nuôi chó."],["考える力を養いましょう。","Hãy nuôi dưỡng năng lực suy nghĩ."],["彼は家族を養っています。","Anh ấy đang nuôi dưỡng gia đình."]]},{"word":"達成感","reading":"たっせいかん","meaning":"cảm giác đạt được thành quả","hanViet":"ĐẠT THÀNH CẢM","lesson":19,"ex":[["仕事を終えて、達成感がありました。","Sau khi hoàn thành công việc, tôi có cảm giác đạt được thành quả."],["達成感を感じることが大切です。","Việc cảm nhận cảm giác đạt được thành quả rất quan trọng."],["試験に合格して、達成感を得ました。","Sau khi đỗ kỳ thi, tôi đã có cảm giác đạt được thành quả."],["達成感があると、もっと頑張れます。","Khi có cảm giác đạt được thành quả, tôi có thể cố gắng hơn nữa."],["彼は達成感を味わいました。","Anh ấy đã tận hưởng cảm giác đạt được thành quả."]]},{"word":"身につく","reading":"みにつく","meaning":"thành thạo, nhuần nhuyễn, tiếp thu được (kỹ năng, kiến thức, thói quen)","hanViet":"THÂN","lesson":19,"ex":[["日本語が身につきました。","Tôi đã thành thạo tiếng Nhật."],["技術が身につくまで、練習します。","Tôi luyện tập cho đến khi thành thạo kỹ thuật."],["いい習慣が身につきました。","Tôi đã hình thành thói quen tốt."],["知識が身につくことが大切です。","Việc tiếp thu kiến thức rất quan trọng."],["英語が身につきました。","Tôi đã thành thạo tiếng Anh."]]},{"word":"活用（する）","reading":"かつよう（する）","meaning":"tận dụng, sử dụng, khai thác","hanViet":"HOẠT DỤNG","lesson":19,"ex":[["知識を活用しましょう。","Hãy tận dụng kiến thức."],["時間を活用することが大切です。","Việc tận dụng thời gian rất quan trọng."],["彼は経験を活用しています。","Anh ấy đang tận dụng kinh nghiệm."],["インターネットを活用して、勉強しています。","Tôi đang tận dụng internet để học."],["技術を活用して、仕事をします。","Tôi tận dụng kỹ thuật để làm việc."]]},{"word":"経費","reading":"けいひ","meaning":"kinh phí","hanViet":"KINH PHÍ","lesson":19,"ex":[["経費を節約しましょう。","Hãy tiết kiệm kinh phí."],["旅行の経費はいくらですか。","Kinh phí chuyến đi là bao nhiêu?"],["経費が増えました。","Kinh phí đã tăng lên."],["会社は経費を調べています。","Công ty đang kiểm tra kinh phí."],["経費を減らすことが大切です。","Việc giảm kinh phí rất quan trọng."]]},{"word":"節約（する）","reading":"せつやく（する）","meaning":"tiết kiệm","hanViet":"TIẾT ƯỚC","lesson":19,"ex":[["お金を節約しています。","Tôi đang tiết kiệm tiền."],["電気を節約しましょう。","Hãy tiết kiệm điện."],["時間を節約するために、電車に乗ります。","Để tiết kiệm thời gian, tôi đi tàu điện."],["水を節約することが大切です。","Việc tiết kiệm nước rất quan trọng."],["彼は毎日、節約しています。","Anh ấy tiết kiệm mỗi ngày."]]},{"word":"廃品","reading":"はいひん","meaning":"phế phẩm","hanViet":"PHẾ PHẨM","lesson":19,"ex":[["廃品を回収しています。","Người ta đang thu hồi phế phẩm."],["廃品を利用して、ものを作りました。","Tôi đã tận dụng phế phẩm để làm đồ."],["廃品がたくさん出ました。","Có rất nhiều phế phẩm thải ra."],["廃品を捨てないでください。","Đừng vứt phế phẩm."],["廃品を集めて、また使います。","Tôi thu gom phế phẩm để dùng lại."]]},{"word":"廃材","reading":"はいざい","meaning":"phế liệu","hanViet":"PHẾ TÀI","lesson":19,"ex":[["廃材を使って、机を作りました。","Tôi đã dùng phế liệu để làm bàn."],["廃材が工場にたくさんあります。","Có rất nhiều phế liệu trong nhà máy."],["廃材を利用することが大切です。","Việc tận dụng phế liệu rất quan trọng."],["廃材を捨てるのは、もったいないです。","Vứt phế liệu đi thật lãng phí."],["廃材から、新しいものを作ります。","Từ phế liệu, người ta làm ra đồ mới."]]},{"word":"前～（～年度）","reading":"～ぜん（～ねんど）","meaning":"trước ~ (~ năm)","hanViet":"TIỀN NIÊN ĐỘ","lesson":19,"ex":[["前年度の売上げは、よかったです。","Doanh thu năm trước rất tốt."],["前年度より、今年は忙しいです。","Năm nay bận hơn năm trước."],["前年度の成績を超えました。","Tôi đã vượt qua thành tích năm trước."],["前年度は、雨が多かったです。","Năm trước, trời mưa nhiều."],["前年度の計画を見直しました。","Tôi đã xem lại kế hoạch năm trước."]]},{"word":"分解（する）","reading":"ぶんかい（する）","meaning":"sự tháo rời, sự phân hủy","hanViet":"PHÂN GIẢI","lesson":19,"ex":[["機械を分解して、調べました。","Tôi đã tháo rời máy móc để kiểm tra."],["古い時計を分解しました。","Tôi đã tháo rời chiếc đồng hồ cũ."],["ロボットを分解するのは、難しいです。","Việc tháo rời rô-bốt rất khó."],["分解して、壊れた部分を見つけました。","Tháo rời ra, tôi đã tìm thấy phần bị hỏng."],["プラスチックは、分解されにくいです。","Nhựa khó phân hủy."]]},{"word":"再利用（する）","reading":"さいりよう（する）","meaning":"tái sử dụng","hanViet":"TÁI LỢI DỤNG","lesson":19,"ex":[["この紙は再利用できます。","Giấy này có thể tái sử dụng được."],["古い服を再利用して、かばんを作ります。","Tôi tái sử dụng quần áo cũ để làm túi xách."],["私は古い新聞を再利用しています。","Tôi đang tái sử dụng báo cũ."],["再利用する前に、よく洗います。","Trước khi tái sử dụng, tôi rửa thật kỹ."],["学校で再利用について勉強しました。","Ở trường, tôi đã học về việc tái sử dụng."]]},{"word":"車輪","reading":"しゃりん","meaning":"bánh xe","hanViet":"XA LUÂN","lesson":19,"ex":[["自転車の車輪が壊れました。","Bánh xe đạp đã bị hỏng."],["車輪を新しくしました。","Tôi đã thay bánh xe mới."],["この車輪は大きいです。","Bánh xe này rất to."],["ロボットの車輪を作ります。","Tôi làm bánh xe cho rô-bốt."],["車輪をよく見てください。","Hãy nhìn kỹ bánh xe."]]},{"word":"用紙","reading":"ようし","meaning":"tờ giấy","hanViet":"DỤNG CHỈ","lesson":19,"ex":[["この用紙に名前を書いてください。","Hãy viết tên vào tờ giấy này."],["用紙をください。","Cho tôi giấy."],["申し込みの用紙をもらいました。","Tôi đã nhận được tờ giấy đăng ký."],["白い用紙を使います。","Tôi dùng giấy trắng."],["新しい用紙をください。","Cho tôi tờ giấy mới."]]},{"word":"ガムテープ","reading":"","meaning":"băng dính dùng đóng gói","hanViet":"","lesson":19,"ex":[["箱をガムテープで止めます。","Tôi dán chặt hộp bằng băng dính đóng gói."],["ガムテープを買いました。","Tôi đã mua băng dính đóng gói."],["ガムテープで荷物を包みます。","Tôi gói hành lý bằng băng dính đóng gói."],["ガムテープがありません。","Không có băng dính đóng gói."],["このガムテープは強いです。","Băng dính đóng gói này rất chắc."]]},{"word":"巻く","reading":"まく","meaning":"cuốn","hanViet":"QUYỂN","lesson":19,"ex":[["糸を巻きます。","Tôi cuốn sợi chỉ."],["紙を巻いて、箱に置きます。","Tôi cuốn giấy lại rồi đặt vào hộp."],["タオルを巻きます。","Tôi cuốn khăn tắm."],["先生は地図を巻きました。","Thầy giáo đã cuốn tấm bản đồ lại."],["私は糸を丁寧に巻きます。","Tôi cuốn chỉ một cách cẩn thận."]]},{"word":"芯","reading":"しん","meaning":"lõi","hanViet":"TÂM","lesson":19,"ex":[["鉛筆の芯を折りました。","Tôi đã làm gãy lõi bút chì."],["新しい芯を入れてください。","Hãy lắp lõi mới vào."],["芯が短いです。","Lõi ngắn quá."],["芯がもうありません。","Hết lõi rồi."],["この芯は細いです。","Lõi này mảnh."]]},{"word":"発泡ゴム","reading":"はっぽうゴム","meaning":"xốp cao su","hanViet":"PHÁT PHAO","lesson":19,"ex":[["発泡ゴムは軽いです。","Xốp cao su rất nhẹ."],["発泡ゴムで箱を作ります。","Tôi làm hộp bằng xốp cao su."],["この発泡ゴムは白いです。","Xốp cao su này màu trắng."],["発泡ゴムを切ります。","Tôi cắt xốp cao su."],["いすの上に発泡ゴムを置きます。","Tôi đặt xốp cao su lên ghế."]]},{"word":"ゴム","reading":"","meaning":"cao su","hanViet":"","lesson":19,"ex":[["ゴムは水に強いです。","Cao su chịu nước tốt."],["ゴムの靴を買いました。","Tôi đã mua giày cao su."],["ゴムでタイヤを作ります。","Người ta làm lốp xe bằng cao su."],["このゴムは黒いです。","Cao su này màu đen."],["ゴムを切ります。","Tôi cắt cao su."]]},{"word":"ヤスリ","reading":"","meaning":"cái giũa","hanViet":"","lesson":19,"ex":[["ヤスリで木を磨きます。","Tôi mài gỗ bằng cái giũa."],["ヤスリを買いました。","Tôi đã mua cái giũa."],["このヤスリは新しいです。","Cái giũa này mới."],["ヤスリを貸してください。","Hãy cho tôi mượn cái giũa."],["ヤスリで角を磨きます。","Tôi mài góc bằng cái giũa."]]},{"word":"かける（ヤスリを～）","reading":"","meaning":"sử dụng (giũa)","hanViet":"","lesson":19,"ex":[["毎日、ヤスリをかけます。","Mỗi ngày tôi đều giũa."],["木にヤスリをかけます。","Tôi giũa gỗ."],["ヤスリをかけて、きれいにします。","Tôi giũa rồi làm cho đẹp."],["丁寧にヤスリをかけます。","Tôi giũa một cách cẩn thận."],["ヤスリをかける前に、手袋をします。","Trước khi giũa, tôi đeo găng tay."]]},{"word":"仕上げる","reading":"しあげる","meaning":"hoàn thành, làm xong","hanViet":"SĨ THƯỢNG","lesson":19,"ex":[["仕事を仕上げました。","Tôi đã hoàn thành công việc."],["宿題を仕上げます。","Tôi làm xong bài tập về nhà."],["料理を仕上げます。","Tôi hoàn thành món ăn."],["早く仕上げたいです。","Tôi muốn làm xong sớm."],["きょう中に仕上げます。","Tôi sẽ làm xong trong hôm nay."]]},{"word":"部品","reading":"ぶひん","meaning":"linh kiện","hanViet":"BỘ PHẨM","lesson":19,"ex":[["自転車の部品を買いました。","Tôi đã mua linh kiện xe đạp."],["部品が足りません。","Không đủ linh kiện."],["この部品は高いです。","Linh kiện này đắt."],["部品を集めます。","Tôi thu thập linh kiện."],["部品を箱に入れます。","Tôi bỏ linh kiện vào hộp."]]},{"word":"生命","reading":"せいめい","meaning":"sinh mệnh, sự sống","hanViet":"SINH MỆNH","lesson":19,"ex":[["生命は大切です。","Sự sống rất quý giá."],["すべての生命を守ります。","Tôi bảo vệ mọi sự sống."],["新しい生命が生まれました。","Một sự sống mới đã ra đời."],["生命について考えます。","Tôi suy nghĩ về sự sống."],["地球の生命を大切にします。","Tôi trân trọng sự sống trên Trái Đất."]]},{"word":"入る（生命が～）","reading":"はいる（せいめいが～）","meaning":"có (sự sống)","hanViet":"NHẬP SINH MỆNH","lesson":19,"ex":[["ロボットに生命が入りました。","Rô-bốt đã có sự sống."],["この絵に生命が入っています。","Bức tranh này như có sự sống."],["作品に生命が入りました。","Tác phẩm đã có hồn."],["舞台に生命が入りました。","Sân khấu đã trở nên sống động."],["物語に生命が入ります。","Câu chuyện trở nên sống động."]]},{"word":"分身","reading":"ぶんしん","meaning":"sự phân thân","hanViet":"PHÂN THÂN","lesson":19,"ex":[["私は分身が欲しいです。","Tôi muốn có phân thân."],["分身がいたら、便利です。","Nếu có phân thân thì tiện lắm."],["忙しいとき、分身が欲しいです。","Lúc bận, tôi muốn có phân thân."],["彼は私の分身です。","Anh ấy như phân thân của tôi."],["分身の話を聞きました。","Tôi đã nghe câu chuyện về phân thân."]]},{"word":"ふるまい","reading":"","meaning":"cư xử, hành vi","hanViet":"","lesson":19,"ex":[["彼のふるまいは静かです。","Cách cư xử của anh ấy rất trầm tĩnh."],["ふるまいに気をつけます。","Tôi chú ý đến cách cư xử."],["子どものふるまいを見ます。","Tôi quan sát hành vi của trẻ em."],["彼女のふるまいは丁寧です。","Cách cư xử của cô ấy rất lịch sự."],["ふるまいを直します。","Tôi sửa lại cách cư xử."]]},{"word":"おだやか（な）","reading":"","meaning":"điềm đạm, ôn hòa","hanViet":"","lesson":19,"ex":[["彼はおだやかな人です。","Anh ấy là người điềm đạm."],["おだやかな海を見ます。","Tôi ngắm biển lặng."],["おだやかな気持ちです。","Tôi cảm thấy yên bình."],["先生はおだやかです。","Thầy giáo rất điềm đạm."],["おだやかに話します。","Tôi nói chuyện một cách ôn hòa."]]},{"word":"チームワーク","reading":"","meaning":"làm việc theo nhóm","hanViet":"","lesson":19,"ex":[["チームワークが大切です。","Làm việc nhóm rất quan trọng."],["チームワークで勝ちました。","Chúng tôi đã thắng nhờ tinh thần đồng đội."],["チームワークがよくなりました。","Tinh thần đồng đội đã tốt hơn."],["チームワークがいいです。","Tinh thần đồng đội rất tốt."],["スポーツはチームワークが大切です。","Thể thao cần tinh thần đồng đội."]]},{"word":"組む（チームを～）","reading":"くむ（チームを～）","meaning":"tạo (nhóm)","hanViet":"TỔ","lesson":19,"ex":[["私はチームを組みます。","Tôi lập nhóm."],["強いチームを組みます。","Tôi lập một đội mạnh."],["新しいチームを組みました。","Tôi đã lập nhóm mới."],["友達とチームを組みます。","Tôi lập nhóm với bạn bè."],["チームを組んで、試合に出ます。","Tôi lập đội rồi tham gia trận đấu."]]},{"word":"トーナメント","reading":"","meaning":"giải đấu","hanViet":"","lesson":19,"ex":[["トーナメントに参加します。","Tôi tham gia giải đấu."],["トーナメントで勝ちました。","Tôi đã thắng ở giải đấu."],["トーナメントは来週です。","Giải đấu diễn ra vào tuần sau."],["トーナメントの試合を見ます。","Tôi xem trận đấu của giải."],["トーナメントに負けました。","Tôi đã thua ở giải đấu."]]},{"word":"精神的（な）","reading":"せいしんてき（な）","meaning":"về mặt tinh thần","hanViet":"TINH THẦN ĐÍCH","lesson":19,"ex":[["精神的なストレスがあります。","Tôi bị căng thẳng tinh thần."],["精神的に疲れました。","Tôi mệt mỏi về mặt tinh thần."],["精神的な健康が大切です。","Sức khỏe tinh thần rất quan trọng."],["精神的に強くなりました。","Tôi đã mạnh mẽ hơn về mặt tinh thần."],["精神的に元気です。","Tôi khỏe mạnh về mặt tinh thần."]]},{"word":"登校（する）","reading":"とうこう（する）","meaning":"đi học","hanViet":"ĐĂNG HIỆU","lesson":19,"ex":[["毎日、登校します。","Mỗi ngày tôi đều đi học."],["朝7時に登校します。","Tôi đi học lúc 7 giờ sáng."],["自転車で登校します。","Tôi đi học bằng xe đạp."],["登校する前に、朝ごはんを食べます。","Trước khi đi học, tôi ăn sáng."],["雨の日も登校します。","Ngày mưa tôi vẫn đi học."]]},{"word":"拒否（する）","reading":"きょひ（する）","meaning":"cự tuyệt, từ chối","hanViet":"CỰ PHỦ","lesson":19,"ex":[["彼は申し込みを拒否しました。","Anh ấy đã từ chối đơn đăng ký."],["拒否する理由を説明します。","Tôi giải thích lý do từ chối."],["拒否はよくありません。","Việc từ chối là không tốt."],["時々、拒否します。","Thỉnh thoảng tôi từ chối."],["彼はすぐに拒否しました。","Anh ấy đã từ chối ngay lập tức."]]},{"word":"下校（する）","reading":"げこう（する）","meaning":"tan trường","hanViet":"HẠ HIỆU","lesson":19,"ex":[["午後4時に下校します。","Tôi tan trường lúc 4 giờ chiều."],["友達と下校します。","Tôi tan trường cùng bạn bè."],["下校する前に、教室を掃除します。","Trước khi tan trường, tôi dọn lớp học."],["雨の日に下校します。","Tôi tan trường vào ngày mưa."],["下校したら、宿題をします。","Tan trường về, tôi làm bài tập."]]},{"word":"標語","reading":"ひょうご","meaning":"khẩu hiệu, biểu ngữ","hanViet":"TIÊU NGỮ","lesson":19,"ex":[["標語を作ります。","Tôi làm khẩu hiệu."],["学校の標語を読みます。","Tôi đọc khẩu hiệu của trường."],["標語を壁にはります。","Tôi dán khẩu hiệu lên tường."],["新しい標語を考えます。","Tôi nghĩ khẩu hiệu mới."],["標語は短いです。","Khẩu hiệu rất ngắn."]]},{"word":"特効薬","reading":"とっこうやく","meaning":"thuốc đặc hiệu, thuốc đặc trị","hanViet":"ĐẶC HIỆU DƯỢC","lesson":19,"ex":[["特効薬を飲みます。","Tôi uống thuốc đặc trị."],["この特効薬は高いです。","Thuốc đặc trị này đắt."],["特効薬がありません。","Không có thuốc đặc trị."],["特効薬を探します。","Tôi tìm thuốc đặc trị."],["医者は特効薬を出しました。","Bác sĩ đã kê thuốc đặc trị."]]},{"word":"例外","reading":"れいがい","meaning":"ngoại lệ","hanViet":"LỆ NGOẠI","lesson":19,"ex":[["例外はありません。","Không có ngoại lệ."],["これは例外です。","Đây là ngoại lệ."],["例外もあります。","Cũng có ngoại lệ."],["規則に例外があります。","Quy định cũng có ngoại lệ."],["例外は少ないです。","Ngoại lệ rất ít."]]},{"word":"広まる（世界中に）","reading":"ひろまる（せかいじゅうに）","meaning":"lan rộng (khắp thế giới)","hanViet":"QUẢNG THẾ GIỚI TRUNG","lesson":19,"ex":[["この歌は世界中に広まりました。","Bài hát này đã lan rộng khắp thế giới."],["その話は世界中に広まります。","Câu chuyện đó sẽ lan rộng khắp thế giới."],["日本の文化が世界中に広まっています。","Văn hóa Nhật Bản đang lan rộng khắp thế giới."],["ニュースは世界中に広まります。","Tin tức lan rộng khắp thế giới."],["この映画は世界中に広まりました。","Bộ phim này đã lan rộng khắp thế giới."]]},{"word":"入会（する）","reading":"にゅうかい（する）","meaning":"gia nhập hội","hanViet":"NHẬP HỘI","lesson":19,"ex":[["サークルに入会します。","Tôi gia nhập câu lạc bộ."],["入会する前に、話を聞きます。","Trước khi gia nhập, tôi nghe giới thiệu."],["入会したら、会員になります。","Sau khi gia nhập, tôi trở thành hội viên."],["入会する人が増えています。","Số người gia nhập đang tăng."],["入会を申し込みました。","Tôi đã đăng ký gia nhập."]]},{"word":"自己紹介","reading":"じこうしょかい","meaning":"tự giới thiệu bản thân","hanViet":"TỰ KỶ THIỆU GIỚI","lesson":19,"ex":[["自己紹介をします。","Tôi tự giới thiệu bản thân."],["自己紹介をしてください。","Hãy tự giới thiệu bản thân."],["自己紹介で名前を言います。","Tôi nói tên trong phần tự giới thiệu."],["自己紹介を練習します。","Tôi luyện tập tự giới thiệu."],["自己紹介は難しいです。","Tự giới thiệu bản thân rất khó."]]},{"word":"アピール（する）","reading":"","meaning":"quảng bá","hanViet":"","lesson":19,"ex":[["自分をアピールします。","Tôi quảng bá bản thân."],["会社をアピールします。","Tôi quảng bá công ty."],["アピールする力が必要です。","Cần khả năng quảng bá."],["アピールするために、ポスターを作ります。","Để quảng bá, tôi làm áp phích."],["アピールが大切です。","Quảng bá rất quan trọng."]]},{"word":"役者","reading":"やくしゃ","meaning":"diễn viên","hanViet":"DỊCH GIẢ","lesson":19,"ex":[["彼は有名な役者です。","Anh ấy là diễn viên nổi tiếng."],["役者は舞台に立ちます。","Diễn viên đứng trên sân khấu."],["役者になりたいです。","Tôi muốn trở thành diễn viên."],["役者は毎日練習します。","Diễn viên luyện tập mỗi ngày."],["若い役者が増えています。","Diễn viên trẻ ngày càng nhiều."]]},{"word":"新入部員","reading":"しんにゅうぶいん","meaning":"thành viên mới của câu lạc bộ","hanViet":"TÂN NHẬP BỘ VIÊN","lesson":19,"ex":[["新入部員が増えました。","Thành viên mới của câu lạc bộ đã tăng lên."],["新入部員を紹介します。","Tôi giới thiệu thành viên mới."],["新入部員は3人です。","Có 3 thành viên mới."],["新入部員に歌を教えます。","Tôi dạy hát cho thành viên mới."],["新入部員と話します。","Tôi nói chuyện với thành viên mới."]]},{"word":"部員","reading":"ぶいん","meaning":"thành viên câu lạc bộ","hanViet":"BỘ VIÊN","lesson":19,"ex":[["部員が20人います。","Có 20 thành viên câu lạc bộ."],["部員はみんな元気です。","Các thành viên đều khỏe mạnh."],["部員と練習します。","Tôi luyện tập cùng các thành viên."],["部員が増えました。","Số thành viên đã tăng."],["新しい部員が来ました。","Thành viên mới đã đến."]]},{"word":"部活動","reading":"ぶかつどう","meaning":"các hoạt động của câu lạc bộ","hanViet":"BỘ HOẠT ĐỘNG","lesson":19,"ex":[["部活動に参加します。","Tôi tham gia hoạt động câu lạc bộ."],["部活動は楽しいです。","Hoạt động câu lạc bộ rất vui."],["部活動で友達が増えました。","Nhờ hoạt động câu lạc bộ, tôi có thêm bạn bè."],["部活動が終わったら、宿題をします。","Khi hoạt động câu lạc bộ kết thúc, tôi làm bài tập."],["部活動は毎日あります。","Hoạt động câu lạc bộ diễn ra mỗi ngày."]]},{"word":"役立てる","reading":"やくだてる","meaning":"tận dụng, phát huy (để có ích)","hanViet":"DỊCH LẬP","lesson":19,"ex":[["英語を役立てます。","Tôi vận dụng tiếng Anh."],["経験を役立てます。","Tôi vận dụng kinh nghiệm."],["習ったことを役立てます。","Tôi vận dụng những điều đã học."],["日本語を役立てます。","Tôi vận dụng tiếng Nhật."],["技術を役立てます。","Tôi vận dụng kỹ thuật."]]},{"word":"入部（する）","reading":"にゅうぶ（する）","meaning":"tham gia câu lạc bộ","hanViet":"NHẬP BỘ","lesson":19,"ex":[["来月、入部します。","Tháng sau tôi sẽ tham gia câu lạc bộ."],["友達と入部します。","Tôi tham gia câu lạc bộ cùng bạn bè."],["入部する前に、見学します。","Trước khi tham gia, tôi đến xem thử."],["入部したら、毎日練習します。","Sau khi tham gia, tôi luyện tập mỗi ngày."],["入部する人が多いです。","Nhiều người tham gia câu lạc bộ."]]},{"word":"ささやか（な）","reading":"","meaning":"nhỏ bé, khiêm tốn, giản dị","hanViet":"","lesson":19,"ex":[["ささやかなプレゼントをあげます。","Tôi tặng một món quà nhỏ."],["ささやかな気持ちを伝えます。","Tôi gửi gắm tấm lòng nhỏ bé."],["ささやかな家に住みます。","Tôi sống trong một ngôi nhà nhỏ."],["ささやかな夢があります。","Tôi có một ước mơ nhỏ bé."],["ささやかな生活を楽しみます。","Tôi tận hưởng cuộc sống giản dị."]]},{"word":"～祭","reading":"～さい","meaning":"lễ hội ~","hanViet":"TẾ","lesson":19,"ex":[["夏祭りに行きます。","Tôi đi lễ hội mùa hè."],["文化祭で歌を歌います。","Tôi hát ở lễ hội văn hóa."],["学園祭は来月です。","Lễ hội trường học diễn ra vào tháng sau."],["体育祭に参加します。","Tôi tham gia lễ hội thể thao."],["祭りはにぎやかです。","Lễ hội rất náo nhiệt."]]},{"word":"伝統","reading":"でんとう","meaning":"truyền thống","hanViet":"TRUYỀN THỐNG","lesson":19,"ex":[["日本の伝統を守ります。","Tôi gìn giữ truyền thống Nhật Bản."],["伝統は大切です。","Truyền thống rất quan trọng."],["伝統を子どもに伝えます。","Tôi truyền truyền thống cho trẻ em."],["伝統的な祭りがあります。","Có lễ hội truyền thống."],["伝統について勉強します。","Tôi học về truyền thống."]]},{"word":"誇り","reading":"ほこり","meaning":"sự tự hào, lòng tự hào","hanViet":"KHOA","lesson":19,"ex":[["誇りを持っています。","Tôi có lòng tự hào."],["日本の文化を誇りに思います。","Tôi tự hào về văn hóa Nhật Bản."],["誇りを感じます。","Tôi cảm thấy tự hào."],["誇りが高いです。","Lòng tự hào cao."],["国の誇りです。","Đó là niềm tự hào của đất nước."]]},{"word":"受け継ぐ","reading":"うけつぐ","meaning":"kế thừa, nối tiếp","hanViet":"THỤ KẾ","lesson":19,"ex":[["伝統を受け継ぎます。","Tôi kế thừa truyền thống."],["父の仕事を受け継ぎます。","Tôi kế thừa công việc của cha."],["技術を受け継ぎます。","Tôi kế thừa kỹ thuật."],["文化を受け継ぐことは大切です。","Việc kế thừa văn hóa rất quan trọng."],["家族の伝統を受け継ぎます。","Tôi kế thừa truyền thống gia đình."]]},{"word":"バトン","reading":"","meaning":"gậy baton","hanViet":"","lesson":19,"ex":[["バトンを受け取ります。","Tôi nhận gậy baton."],["バトンを渡します。","Tôi trao gậy baton."],["バトンを強く持ちます。","Tôi cầm chặt gậy baton."],["バトンを次に渡します。","Tôi trao gậy baton cho người tiếp theo."],["運動会でバトンを渡します。","Tôi trao gậy baton ở hội thao."]]},{"word":"舞台","reading":"ぶたい","meaning":"sân khấu","hanViet":"VŨ ĐÀI","lesson":19,"ex":[["舞台に立ちます。","Tôi đứng trên sân khấu."],["舞台で歌います。","Tôi hát trên sân khấu."],["舞台は大きいです。","Sân khấu rất lớn."],["舞台を見ます。","Tôi xem sân khấu."],["舞台で踊ります。","Tôi nhảy múa trên sân khấu."]]},{"word":"舞台装置","reading":"ぶたいそうち","meaning":"trang thiết bị sân khấu","hanViet":"VŨ ĐÀI TRANG TRÍ","lesson":19,"ex":[["舞台装置を作ります。","Tôi làm thiết bị sân khấu."],["舞台装置を運びます。","Tôi vận chuyển thiết bị sân khấu."],["舞台装置を調べます。","Tôi kiểm tra thiết bị sân khấu."],["舞台装置は大きいです。","Thiết bị sân khấu rất lớn."],["舞台装置の準備をします。","Tôi chuẩn bị thiết bị sân khấu."]]},{"word":"装置","reading":"そうち","meaning":"trang thiết bị","hanViet":"TRANG TRÍ","lesson":19,"ex":[["装置を使います。","Tôi dùng thiết bị."],["新しい装置を買いました。","Tôi đã mua thiết bị mới."],["装置が壊れました。","Thiết bị đã bị hỏng."],["装置を直します。","Tôi sửa thiết bị."],["装置を調べます。","Tôi kiểm tra thiết bị."]]},{"word":"衣装","reading":"いしょう","meaning":"trang phục","hanViet":"Y TRANG","lesson":19,"ex":[["衣装を着ます。","Tôi mặc trang phục."],["華やかな衣装を着ます。","Tôi mặc trang phục lộng lẫy."],["衣装を作ります。","Tôi làm trang phục."],["衣装を借ります。","Tôi mượn trang phục."],["衣装を選びます。","Tôi chọn trang phục."]]},{"word":"華やか（な）","reading":"はなやか（な）","meaning":"lộng lẫy, rực rỡ","hanViet":"HOA","lesson":19,"ex":[["華やかな衣装です。","Trang phục lộng lẫy."],["華やかな花があります。","Có những bông hoa rực rỡ."],["華やかな舞台です。","Sân khấu lộng lẫy."],["彼女は華やかです。","Cô ấy rất lộng lẫy."],["華やかな祭りです。","Lễ hội rực rỡ."]]},{"word":"覚悟（する）","reading":"かくご（する）","meaning":"quyết tâm, sẵn sàng đối mặt (với khó khăn)","hanViet":"GIÁC NGỘ","lesson":19,"ex":[["覚悟を決めます。","Tôi quyết tâm."],["覚悟して試験を受けます。","Tôi quyết tâm bước vào kỳ thi."],["覚悟ができました。","Tôi đã sẵn sàng."],["覚悟して話します。","Tôi nói với sự quyết tâm."],["覚悟を持って頑張ります。","Tôi cố gắng với quyết tâm."]]},{"word":"ありきたり（の）","reading":"","meaning":"bình thường, thông thường","hanViet":"","lesson":19,"ex":[["ありきたりの話です。","Câu chuyện bình thường."],["ありきたりの服です。","Quần áo bình thường."],["ありきたりの答えです。","Câu trả lời thông thường."],["ありきたりの毎日です。","Mỗi ngày đều bình thường."],["ありきたりの映画です。","Bộ phim bình thường."]]},{"word":"時計回り","reading":"とけいまわり","meaning":"chiều quay của kim đồng hồ","hanViet":"THỜI KẾ HỒI","lesson":19,"ex":[["時計回りに歩きます。","Tôi đi bộ theo chiều kim đồng hồ."],["時計回りに動きます。","Tôi di chuyển theo chiều kim đồng hồ."],["時計回りに走ります。","Tôi chạy theo chiều kim đồng hồ."],["時計回りに見てください。","Hãy nhìn theo chiều kim đồng hồ."],["時計回りに並びます。","Chúng tôi xếp hàng theo chiều kim đồng hồ."]]},{"word":"タイヤ","reading":"","meaning":"lốp xe","hanViet":"","lesson":19,"ex":[["タイヤを買いました。","Tôi đã mua lốp xe."],["タイヤが壊れました。","Lốp xe đã bị hỏng."],["タイヤを直します。","Tôi sửa lốp xe."],["新しいタイヤが必要です。","Cần lốp xe mới."],["タイヤは黒いです。","Lốp xe màu đen."]]},{"word":"ストッパー","reading":"","meaning":"cái chặn","hanViet":"","lesson":19,"ex":[["ストッパーを使います。","Tôi dùng cái chặn."],["ストッパーを買いました。","Tôi đã mua cái chặn."],["ストッパーで止めます。","Tôi chặn lại bằng cái chặn."],["ストッパーが壊れました。","Cái chặn đã bị hỏng."],["ストッパーを探します。","Tôi tìm cái chặn."]]},{"word":"筋肉","reading":"きんにく","meaning":"cơ bắp","hanViet":"CÂN NHỤC","lesson":19,"ex":[["筋肉が強いです。","Cơ bắp rất khỏe."],["筋肉が大きくなりました。","Cơ bắp đã to hơn."],["筋肉が疲れました。","Cơ bắp đã mệt."],["筋肉の力が必要です。","Cần sức mạnh cơ bắp."],["筋肉について勉強します。","Tôi học về cơ bắp."]]},{"word":"モーター","reading":"","meaning":"mô tơ","hanViet":"","lesson":19,"ex":[["モーターが動きます。","Mô tơ chạy."],["モーターを買いました。","Tôi đã mua mô tơ."],["モーターが壊れました。","Mô tơ đã bị hỏng."],["モーターを直します。","Tôi sửa mô tơ."],["モーターの音が聞こえます。","Tôi nghe thấy tiếng mô tơ."]]},{"word":"生かす","reading":"いかす","meaning":"vận dụng, sử dụng tốt","hanViet":"SINH","lesson":19,"ex":[["経験を生かします。","Tôi vận dụng kinh nghiệm."],["英語を生かします。","Tôi vận dụng tiếng Anh."],["技術を生かします。","Tôi vận dụng kỹ thuật."],["失敗した経験を生かします。","Tôi vận dụng kinh nghiệm thất bại."],["習ったことを生かします。","Tôi vận dụng những điều đã học."]]},{"word":"万年～","reading":"まんねん～","meaning":"muôn đời, vĩnh viễn","hanViet":"VẠN NIÊN","lesson":19,"ex":[["万年筆を買いました。","Tôi đã mua bút máy."],["万年筆で手紙を書きます。","Tôi viết thư bằng bút máy."],["万年雪を見ました。","Tôi đã thấy tuyết vạn năm."],["万年筆は高いです。","Bút máy đắt."],["万年筆を使います。","Tôi dùng bút máy."]]},{"word":"補欠","reading":"ほけつ","meaning":"dự bị","hanViet":"BỔ KHIÊM","lesson":19,"ex":[["補欠の選手です。","Tôi là cầu thủ dự bị."],["補欠で試合に出ます。","Tôi ra sân với tư cách dự bị."],["補欠でも頑張ります。","Dù dự bị tôi vẫn cố gắng."],["補欠からレギュラーになりました。","Tôi đã từ dự bị trở thành cầu thủ chính."],["補欠ですが、練習します。","Dù là dự bị, tôi vẫn luyện tập."]]},{"word":"レギュラー","reading":"","meaning":"cầu thủ chính","hanViet":"","lesson":19,"ex":[["レギュラーになりました。","Tôi đã trở thành cầu thủ chính."],["レギュラーの選手です。","Tôi là cầu thủ chính."],["レギュラーで試合に出ます。","Tôi ra sân với tư cách cầu thủ chính."],["レギュラーになりたいです。","Tôi muốn trở thành cầu thủ chính."],["レギュラーは練習が多いです。","Cầu thủ chính luyện tập nhiều."]]},{"word":"いわゆる","reading":"","meaning":"cái gọi là","hanViet":"","lesson":19,"ex":[["いわゆる普通の人です。","Cái gọi là người bình thường."],["いわゆる有名な店です。","Cái gọi là cửa hàng nổi tiếng."],["いわゆる新しい方法です。","Cái gọi là phương pháp mới."],["いわゆる伝統的な祭りです。","Cái gọi là lễ hội truyền thống."],["いわゆる昔の話です。","Cái gọi là chuyện ngày xưa."]]},{"word":"ボール拾い","reading":"ボールひろい","meaning":"người nhặt bóng","hanViet":"THẬP","lesson":19,"ex":[["ボール拾いをします。","Tôi nhặt bóng."],["ボール拾いの仕事です。","Công việc nhặt bóng."],["試合でボール拾いをします。","Tôi nhặt bóng trong trận đấu."],["ボール拾いは大切です。","Việc nhặt bóng rất quan trọng."],["ボール拾いが好きです。","Tôi thích nhặt bóng."]]},{"word":"下積み","reading":"したづみ","meaning":"quãng tập sự ở vị trí thấp","hanViet":"HẠ TÍCH","lesson":19,"ex":[["下積みが必要です。","Cần có quãng thời gian tập sự."],["下積みの生活です。","Cuộc sống tập sự ở vị trí thấp."],["下積みは大切です。","Quãng tập sự rất quan trọng."],["下積みが長いです。","Quãng tập sự rất dài."],["下積みを頑張ります。","Tôi cố gắng trong quãng tập sự."]]},{"word":"サークル","reading":"","meaning":"câu lạc bộ","hanViet":"","lesson":19,"ex":[["サークルに入ります。","Tôi tham gia câu lạc bộ."],["サークルのメンバーです。","Tôi là thành viên câu lạc bộ."],["サークルで歌います。","Tôi hát ở câu lạc bộ."],["サークルを作ります。","Tôi lập câu lạc bộ."],["サークルは楽しいです。","Câu lạc bộ rất vui."]]},{"word":"小話","reading":"こばなし","meaning":"chuyện tiếu lâm","hanViet":"TIỂU THOẠI","lesson":19,"ex":[["小話を話します。","Tôi kể chuyện tiếu lâm."],["おもしろい小話を聞きました。","Tôi đã nghe chuyện tiếu lâm hay."],["小話でみんなが笑います。","Mọi người cười vì chuyện tiếu lâm."],["小話を覚えます。","Tôi nhớ chuyện tiếu lâm."],["小話を集めます。","Tôi sưu tầm chuyện tiếu lâm."]]},{"word":"喜劇","reading":"きげき","meaning":"hài kịch","hanViet":"HỈ KỊCH","lesson":19,"ex":[["喜劇を見ます。","Tôi xem hài kịch."],["喜劇はおもしろいです。","Hài kịch rất hay."],["喜劇で笑います。","Tôi cười vì hài kịch."],["喜劇が好きです。","Tôi thích hài kịch."],["喜劇に出ます。","Tôi tham gia hài kịch."]]},{"word":"ユニーク（な）","reading":"","meaning":"độc đáo","hanViet":"","lesson":19,"ex":[["ユニークな人です。","Người độc đáo."],["ユニークな服です。","Quần áo độc đáo."],["ユニークな話です。","Câu chuyện độc đáo."],["ユニークな方法です。","Phương pháp độc đáo."],["ユニークな家です。","Ngôi nhà độc đáo."]]},{"word":"揃う","reading":"そろう","meaning":"đầy đủ","hanViet":"","lesson":19,"ex":[["メンバーが揃いました。","Các thành viên đã đủ mặt."],["道具が揃いました。","Dụng cụ đã đầy đủ."],["材料が揃いました。","Nguyên liệu đã đầy đủ."],["必要な物が揃いました。","Những thứ cần thiết đã đầy đủ."],["人が揃いました。","Mọi người đã đủ mặt."]]},{"word":"引き継ぐ","reading":"ひきつぐ","meaning":"tiếp nối","hanViet":"DẪN KẾ","lesson":19,"ex":[["仕事を引き継ぎます。","Tôi tiếp nối công việc."],["伝統を引き継ぎます。","Tôi tiếp nối truyền thống."],["先輩から仕事を引き継ぎます。","Tôi tiếp nối công việc từ tiền bối."],["役を引き継ぎます。","Tôi tiếp nối vai trò."],["文化を引き継ぐことは大切です。","Việc tiếp nối văn hóa rất quan trọng."]]},{"word":"引き締める","reading":"ひきしめる","meaning":"siết chặt; tập trung tinh thần","hanViet":"DẪN ĐẾ","lesson":19,"ex":[["気持ちを引き締めます。","Tôi tập trung tinh thần."],["ひもを引き締めます。","Tôi siết chặt dây."],["心を引き締めます。","Tôi tập trung tinh thần."],["試合の前に気持ちを引き締めます。","Trước trận đấu, tôi tập trung tinh thần."],["気持ちを引き締めて、頑張ります。","Tôi tập trung tinh thần và cố gắng."]]},{"word":"披露（する）","reading":"ひろう（する）","meaning":"trình diễn","hanViet":"PHI LỘ","lesson":19,"ex":[["歌を披露します。","Tôi trình diễn bài hát."],["ダンスを披露します。","Tôi trình diễn điệu nhảy."],["作品を披露します。","Tôi trình bày tác phẩm."],["舞台で歌を披露します。","Tôi trình diễn bài hát trên sân khấu."],["新しい歌を披露します。","Tôi trình diễn bài hát mới."]]},{"word":"準決勝","reading":"じゅんけっしょう","meaning":"bán kết","hanViet":"CHUẨN QUYẾT THẮNG","lesson":19,"ex":[["準決勝に出ます。","Tôi vào bán kết."],["準決勝で勝ちました。","Tôi đã thắng ở bán kết."],["準決勝は来週です。","Bán kết diễn ra vào tuần sau."],["準決勝を見ます。","Tôi xem trận bán kết."],["準決勝で負けました。","Tôi đã thua ở bán kết."]]},{"word":"電卓","reading":"でんたく","meaning":"máy tính bỏ túi, máy tính cầm tay","hanViet":"ĐIỆN TRÁC","lesson":19,"ex":[["電卓を使います。","Tôi dùng máy tính bỏ túi."],["電卓で計算します。","Tôi tính bằng máy tính bỏ túi."],["電卓を買いました。","Tôi đã mua máy tính bỏ túi."],["電卓が壊れました。","Máy tính bỏ túi đã bị hỏng."],["電卓は便利です。","Máy tính bỏ túi rất tiện."]]},{"word":"空想","reading":"くうそう","meaning":"tưởng tượng, mộng tưởng","hanViet":"KHÔNG TƯỞNG","lesson":19,"ex":[["空想が好きです。","Tôi thích tưởng tượng."],["空想を楽しみます。","Tôi tận hưởng mộng tưởng."],["空想の世界です。","Thế giới tưởng tượng."],["空想をします。","Tôi tưởng tượng."],["空想は楽しいです。","Tưởng tượng rất vui."]]},{"word":"こもる","reading":"","meaning":"thu mình","hanViet":"","lesson":19,"ex":[["部屋にこもります。","Tôi ru rú trong phòng."],["家にこもります。","Tôi ở lì trong nhà."],["部屋にこもって、本を読みます。","Tôi ru rú trong phòng đọc sách."],["週末は部屋にこもります。","Cuối tuần tôi ru rú trong phòng."],["寒い日は家にこもります。","Ngày lạnh tôi ở lì trong nhà."]]},{"word":"引きこもり","reading":"ひきこもり","meaning":"người sống ẩn dật, người sống thu mình","hanViet":"DẪN","lesson":19,"ex":[["引きこもりの人が増えています。","Số người sống thu mình đang tăng."],["引きこもりについて考えます。","Tôi suy nghĩ về hiện tượng sống thu mình."],["引きこもりの生活です。","Cuộc sống thu mình."],["引きこもりを助けます。","Tôi giúp đỡ người sống thu mình."],["引きこもりから出ました。","Tôi đã thoát khỏi cuộc sống thu mình."]]},{"word":"コンパス","reading":"","meaning":"cái la bàn","hanViet":"","lesson":19,"ex":[["コンパスを使います。","Tôi dùng la bàn."],["コンパスで北を調べます。","Tôi xác định hướng Bắc bằng la bàn."],["コンパスを買いました。","Tôi đã mua la bàn."],["コンパスがありません。","Không có la bàn."],["コンパスを持ちます。","Tôi mang theo la bàn."]]},{"word":"手放す","reading":"てばなす","meaning":"buông tay, từ bỏ, bán đi (thứ đang có)","hanViet":"THỦ PHÓNG","lesson":19,"ex":[["本を手放します。","Tôi bán đi quyển sách."],["大切な物を手放します。","Tôi từ bỏ thứ quan trọng."],["車を手放しました。","Tôi đã bán chiếc xe."],["手放したくありません。","Tôi không muốn từ bỏ."],["古い服を手放します。","Tôi bỏ đi quần áo cũ."]]},{"word":"方向音痴","reading":"ほうこうおんち","meaning":"người không xác định được phương hướng","hanViet":"PHƯƠNG HƯỚNG ÂM SI","lesson":19,"ex":[["私は方向音痴です。","Tôi là người mù phương hướng."],["方向音痴で困ります。","Tôi gặp khó khăn vì mù phương hướng."],["方向音痴なので、地図を見ます。","Vì mù phương hướng nên tôi xem bản đồ."],["方向音痴の人が多いです。","Nhiều người mù phương hướng."],["方向音痴でも大丈夫です。","Dù mù phương hướng cũng không sao."]]},{"word":"ナビゲーター","reading":"","meaning":"người dẫn đường, người định hướng","hanViet":"","lesson":19,"ex":[["ナビゲーターを使います。","Tôi dùng thiết bị định vị."],["ナビゲーターで道を調べます。","Tôi tìm đường bằng thiết bị định vị."],["車にナビゲーターがあります。","Trên xe có thiết bị định vị."],["ナビゲーターが便利です。","Thiết bị định vị rất tiện."],["ナビゲーターの声を聞きます。","Tôi nghe giọng nói của thiết bị định vị."]]},{"word":"かゆい所に手が届く","reading":"かゆいところにてがとどく","meaning":"gãi đúng chỗ ngứa","hanViet":"SỞ THỦ GIỚI","lesson":19,"ex":[["彼はかゆい所に手が届く人です。","Anh ấy là người rất chu đáo."],["この店はかゆい所に手が届きます。","Cửa hàng này rất chu đáo."],["かゆい所に手が届くサービスです。","Dịch vụ chu đáo."],["先生はかゆい所に手が届きます。","Thầy giáo rất chu đáo."],["このホテルはかゆい所に手が届きます。","Khách sạn này rất chu đáo."]]},{"word":"お人よし","reading":"おひとよし","meaning":"người hiền lành, dễ tin (dễ bị lợi dụng)","hanViet":"NHÂN","lesson":19,"ex":[["田中さんはお人よしで、だれの話でも信じてしまいます。","Anh Tanaka là người dễ tin nên ai nói gì anh cũng tin."],["お人よしの山田さんは、知らない人にもお金を貸してしまいます。","Anh Yamada dễ tin nên cho cả người lạ vay tiền."],["お人よしの人は、友達の仕事を手伝って、いつも忙しいです。","Người dễ tin thường giúp việc cho bạn bè nên lúc nào cũng bận."],["お人よしすぎると、詐欺の被害者になるかもしれません。","Quá dễ tin thì có thể trở thành nạn nhân của lừa đảo."],["私のお父さんはお人よしで、困っている人をいつも助けます。","Bố tôi là người dễ tin, lúc nào cũng giúp đỡ người gặp khó khăn."]]},{"word":"警察官","reading":"けいさつかん","meaning":"cảnh sát","hanViet":"CẢNH SÁT QUAN","lesson":19,"ex":[["警察官が交差点で車を見ています。","Cảnh sát đang quan sát xe cộ ở ngã tư."],["道がわからなかったら、警察官に聞いてください。","Nếu không biết đường thì hãy hỏi cảnh sát."],["あの警察官は毎日駅前で子どもたちを守っています。","Viên cảnh sát đó ngày nào cũng bảo vệ trẻ em trước ga."],["将来は警察官になって、人を助けたいです。","Tương lai tôi muốn trở thành cảnh sát để giúp đỡ mọi người."],["警察官になるためには、試験に合格しなければなりません。","Để trở thành cảnh sát thì phải đỗ kỳ thi."]]},{"word":"詐欺","reading":"さぎ","meaning":"sự lừa đảo","hanViet":"TRÁ KHI","lesson":19,"ex":[["最近、電話を使った詐欺が増えています。","Gần đây, các vụ lừa đảo qua điện thoại đang tăng lên."],["詐欺の被害者は、犯人にお金を払ってしまいました。","Nạn nhân đã đưa tiền cho kẻ lừa đảo."],["詐欺を防ぐためには、知らない電話に出ないことが大切です。","Để phòng tránh lừa đảo, điều quan trọng là không nghe điện thoại lạ."],["警察は詐欺について、みんなに注意するように言っています。","Cảnh sát nhắc nhở mọi người cẩn thận với lừa đảo."],["あの電話は詐欺かもしれませんから、警察に相談してください。","Cuộc điện thoại đó có thể là lừa đảo, hãy hỏi ý kiến cảnh sát."]]},{"word":"防ぐ","reading":"ふせぐ","meaning":"ngăn chặn, phòng ngừa","hanViet":"PHÒNG","lesson":19,"ex":[["毎日よく寝て、病気を防ぎましょう。","Hãy ngủ đủ mỗi ngày để phòng bệnh."],["事故を防ぐために、信号をよく見て歩きます。","Để phòng tai nạn, tôi nhìn kỹ đèn tín hiệu rồi mới đi bộ."],["この薬は、熱が上がるのを防ぎます。","Thuốc này ngăn không cho sốt tăng cao."],["先生は、事故を防ぐために、生徒に注意するように言いました。","Thầy giáo đã nhắc học sinh cẩn thận để phòng tai nạn."],["火事を防ぐために、寝る前に電気を消します。","Để phòng cháy, trước khi ngủ tôi tắt điện."]]},{"word":"幼児","reading":"ようじ","meaning":"trẻ nhỏ","hanViet":"ẤU NHI","lesson":19,"ex":[["幼児は、公園で元気に遊びます。","Trẻ nhỏ chơi đùa vui vẻ ở công viên."],["この保育園では、幼児がたくさん遊んでいます。","Ở nhà trẻ này có rất nhiều trẻ nhỏ đang chơi."],["幼児の教育は、将来のためにとても大切です。","Giáo dục trẻ nhỏ rất quan trọng cho tương lai."],["幼児は、絵本を読んでもらうのが好きです。","Trẻ nhỏ thích được đọc truyện tranh cho nghe."],["幼児と話すときは、ゆっくり話します。","Khi nói chuyện với trẻ nhỏ, tôi nói chậm rãi."]]},{"word":"流行（する）","reading":"りゅうこう（する）","meaning":"thịnh hành","hanViet":"LƯU HÀNH","lesson":19,"ex":[["今年は、この歌が若者の間で流行しています。","Năm nay, bài hát này đang thịnh hành trong giới trẻ."],["あの服は去年流行しましたが、今年はあまり着ません。","Bộ đồ đó thịnh hành năm ngoái nhưng năm nay tôi ít mặc."],["日本では、健康のためにジョギングが流行しています。","Ở Nhật, chạy bộ đang thịnh hành vì tốt cho sức khỏe."],["新しいゲームが子どもたちの間で流行しています。","Trò chơi mới đang thịnh hành trong trẻ em."],["流行している服は、店でよく売れます。","Quần áo đang thịnh hành bán rất chạy ở cửa hàng."]]},{"word":"おもに","reading":"","meaning":"chủ yếu","hanViet":"","lesson":19,"ex":[["この店では、おもに野菜を売っています。","Cửa hàng này chủ yếu bán rau."],["田中さんは、おもに夜に仕事をします。","Anh Tanaka chủ yếu làm việc vào ban đêm."],["この本は、おもに子どもが読みます。","Cuốn sách này chủ yếu dành cho trẻ em đọc."],["私は、おもに朝に勉強します。","Tôi chủ yếu học vào buổi sáng."],["この会社は、おもに外国と貿易をしています。","Công ty này chủ yếu buôn bán với nước ngoài."]]},{"word":"反抗（する）","reading":"はんこう（する）","meaning":"phản kháng","hanViet":"PHẢN KHÁNG","lesson":19,"ex":[["若者は、親に反抗することがあります。","Người trẻ đôi khi phản kháng cha mẹ."],["子どもが親に反抗したとき、親はゆっくり話します。","Khi con phản kháng cha mẹ, cha mẹ nói chuyện từ tốn với con."],["生徒は、厳しい規則に反抗しました。","Học sinh đã phản kháng những quy định nghiêm khắc."],["若い人が会社に反抗することは、あまりありません。","Người trẻ ít khi phản kháng công ty."],["反抗する前に、まず相手の気持ちを考えましょう。","Trước khi phản kháng, trước hết hãy nghĩ đến cảm xúc của đối phương."]]},{"word":"甘い（管理体制が～）","reading":"あまい（かんりたいせいが～）","meaning":"(chế độ quản lý) lỏng lẻo","hanViet":"CAM QUẢN LÝ THỂ CHẾ","lesson":19,"ex":[["この会社の管理体制が甘いので、問題が起きました。","Vì chế độ quản lý của công ty này lỏng lẻo nên đã xảy ra vấn đề."],["管理体制が甘い会社は、事故が起きやすいです。","Công ty có chế độ quản lý lỏng lẻo thì dễ xảy ra tai nạn."],["管理体制が甘いと、仕事の問題が増えます。","Chế độ quản lý lỏng lẻo thì vấn đề trong công việc tăng lên."],["先生は、管理体制が甘い学校を心配しています。","Thầy giáo lo lắng về ngôi trường có chế độ quản lý lỏng lẻo."],["管理体制が甘かったので、会社は規則を新しくしました。","Vì chế độ quản lý lỏng lẻo nên công ty đã đổi mới quy định."]]},{"word":"難民キャンプ","reading":"なんみんキャンプ","meaning":"trại tị nạn","hanViet":"NAN DÂN","lesson":19,"ex":[["難民キャンプでは、子どもたちが学校で勉強しています。","Ở trại tị nạn, trẻ em học tập ở trường."],["ボランティアは、難民キャンプで水とごはんを届けます。","Tình nguyện viên mang nước và cơm đến trại tị nạn."],["難民キャンプの子どもたちは、元気に遊んでいます。","Trẻ em ở trại tị nạn đang chơi đùa vui vẻ."],["戦争のために、難民キャンプに来る人が増えています。","Vì chiến tranh, số người đến trại tị nạn đang tăng lên."],["国連は、難民キャンプの子どもを助けています。","Liên Hợp Quốc đang giúp đỡ trẻ em ở trại tị nạn."]]},{"word":"医療活動","reading":"いりょうかつどう","meaning":"hoạt động chăm sóc y tế","hanViet":"Y LIỆU HOẠT ĐỘNG","lesson":19,"ex":[["医者は、外国で医療活動をしています。","Bác sĩ đang làm hoạt động y tế ở nước ngoài."],["医療活動のために、病院から医者が来ました。","Vì hoạt động y tế, bác sĩ đã đến từ bệnh viện."],["ボランティアは、村で医療活動を続けています。","Tình nguyện viên vẫn tiếp tục hoạt động y tế ở làng."],["医療活動は、病気の人を助ける大切な仕事です。","Hoạt động y tế là công việc quan trọng giúp đỡ người bệnh."],["田中さんは、医療活動を長く続けています。","Anh Tanaka đã làm hoạt động y tế lâu rồi."]]},{"word":"医療","reading":"いりょう","meaning":"y tế","hanViet":"Y LIỆU","lesson":19,"ex":[["この病院は、医療のレベルが高いです。","Bệnh viện này có trình độ y tế cao."],["医療が進むと、病気が治りやすくなります。","Y tế tiến bộ thì bệnh dễ chữa khỏi hơn."],["日本の医療は、世界で有名です。","Y tế Nhật Bản nổi tiếng trên thế giới."],["医療のために働く人は、毎日忙しいです。","Người làm trong ngành y tế ngày nào cũng bận."],["医療の仕事は、人を助ける仕事です。","Công việc y tế là công việc giúp đỡ con người."]]},{"word":"使命（感）","reading":"しめい（かん）","meaning":"(ý thức) sứ mệnh","hanViet":"SỬ MỆNH CẢM","lesson":19,"ex":[["医者は、人を助ける使命感を持っています。","Bác sĩ có ý thức sứ mệnh giúp đỡ con người."],["先生は、子どもを教える使命を持っています。","Thầy giáo có sứ mệnh dạy dỗ trẻ em."],["警察官は、人を守る使命感を持って働いています。","Cảnh sát làm việc với ý thức sứ mệnh bảo vệ con người."],["使命感が強い人は、難しい仕事も続けます。","Người có ý thức sứ mệnh mạnh mẽ sẽ tiếp tục cả công việc khó khăn."],["彼は、日本のために働く使命を持っています。","Anh ấy có sứ mệnh làm việc vì Nhật Bản."]]},{"word":"定年","reading":"ていねん","meaning":"tuổi nghỉ hưu","hanViet":"ĐỊNH NIÊN","lesson":19,"ex":[["田中さんは、今年定年になります。","Anh Tanaka năm nay đến tuổi nghỉ hưu."],["定年のあと、田中さんは旅行に行きます。","Sau khi nghỉ hưu, anh Tanaka sẽ đi du lịch."],["この会社では、定年は60歳です。","Ở công ty này, tuổi nghỉ hưu là 60 tuổi."],["田中さんは、もうすぐ定年になります。","Anh Tanaka sắp đến tuổi nghỉ hưu."],["定年になったら、田中さんは田舎に住みたいです。","Khi nghỉ hưu, anh Tanaka muốn sống ở nông thôn."]]},{"word":"受賞（する）","reading":"じゅしょう（する）","meaning":"nhận giải thưởng","hanViet":"THỤ THƯỞNG","lesson":19,"ex":[["田中さんは、今年受賞しました。","Anh Tanaka đã nhận giải thưởng năm nay."],["その小説は、去年受賞しました。","Cuốn tiểu thuyết đó đã nhận giải thưởng năm ngoái."],["受賞した作家は、とてもうれしそうでした。","Nhà văn nhận giải trông rất vui."],["彼女は、音楽で受賞したことがあります。","Cô ấy đã từng nhận giải thưởng về âm nhạc."],["受賞するために、彼は毎日練習しています。","Để nhận giải thưởng, anh ấy luyện tập mỗi ngày."]]},{"word":"物理","reading":"ぶつり","meaning":"vật lý","hanViet":"VẬT LÝ","lesson":19,"ex":[["私は、学校で物理を勉強しています。","Tôi đang học vật lý ở trường."],["物理は、難しいですが、楽しいです。","Vật lý khó nhưng vui."],["物理の先生は、実験が上手です。","Thầy giáo vật lý giỏi làm thí nghiệm."],["田中さんは、大学で物理を勉強しました。","Anh Tanaka đã học vật lý ở đại học."],["物理の本を読んで、世界の仕組みがわかりました。","Đọc sách vật lý, tôi đã hiểu cơ chế của thế giới."]]},{"word":"道（物理の～）","reading":"みち（ぶつりの～）","meaning":"sự nghiệp (vật lí)","hanViet":"ĐẠO VẬT LÝ","lesson":19,"ex":[["彼は、物理の道に進むことにしました。","Anh ấy đã quyết định đi theo con đường vật lý."],["物理の道は、長くて難しいです。","Con đường vật lý dài và khó khăn."],["田中さんは、子どものときから物理の道を目指していました。","Anh Tanaka đã hướng tới con đường vật lý từ khi còn nhỏ."],["物理の道で有名になるには、長い時間がかかります。","Để nổi tiếng trong con đường vật lý cần rất nhiều thời gian."],["彼女は、物理の道をあきらめませんでした。","Cô ấy đã không từ bỏ con đường vật lý."]]},{"word":"行儀作法","reading":"ぎょうぎさほう","meaning":"cách cư xử và phép xã giao","hanViet":"HÀNH NGHI TÁC PHÁP","lesson":19,"ex":[["日本では、行儀作法を大切にします。","Ở Nhật, người ta coi trọng cách cư xử và phép xã giao."],["子どもは、学校で行儀作法を習います。","Trẻ em học cách cư xử và phép xã giao ở trường."],["みんなは、行儀作法がいい人が好きです。","Mọi người thích người có cách cư xử tốt."],["先生は、生徒に行儀作法を教えています。","Thầy giáo đang dạy học sinh cách cư xử và phép xã giao."],["行儀作法を身につけることは、時間がかかります。","Để tiếp thu cách cư xử và phép xã giao cần thời gian."]]},{"word":"行儀","reading":"ぎょうぎ","meaning":"cách cư xử","hanViet":"HÀNH NGHI","lesson":19,"ex":[["子どもは、行儀よくごはんを食べます。","Trẻ em ăn cơm một cách lễ phép."],["先生は、行儀がいい子どもが好きです。","Thầy giáo thích trẻ ngoan."],["電車の中では、行儀よく座ります。","Trên tàu điện, tôi ngồi một cách lễ phép."],["行儀を習うために、子どもは学校に行きます。","Để học cách cư xử, trẻ em đến trường."],["あの子どもは、行儀がよくなくて、先生に注意されました。","Đứa trẻ đó cư xử không tốt nên bị thầy giáo nhắc nhở."]]},{"word":"作法","reading":"さほう","meaning":"phép xã giao, phép tắc, phép lịch sự","hanViet":"TÁC PHÁP","lesson":19,"ex":[["お茶の作法は、日本の文化です。","Phép tắc trà đạo là văn hóa Nhật Bản."],["結婚式では、作法を守ることが大切です。","Trong lễ cưới, việc giữ phép tắc rất quan trọng."],["作法を習うために、田中さんは教室に通っています。","Để học phép tắc, anh Tanaka đang đến lớp học."],["日本の作法は、外国でも知られています。","Phép tắc Nhật Bản cũng được biết đến ở nước ngoài."],["作法がわからないときは、先生に聞きます。","Khi không hiểu phép tắc, tôi hỏi thầy giáo."]]},{"word":"和","reading":"わ","meaning":"hài hòa, cân đối","hanViet":"HÒA","lesson":19,"ex":[["家族の和を大切にしましょう。","Hãy coi trọng sự hòa thuận trong gia đình."],["この部屋は、色の和がいいです。","Căn phòng này có sự phối hợp màu sắc hài hòa."],["チームの和を守ることが大切です。","Giữ sự hòa thuận trong đội là quan trọng."],["和のある会社では、みんなが楽しく働きます。","Ở công ty hòa thuận, mọi người làm việc vui vẻ."],["彼女は、人と人との和を大切にします。","Cô ấy coi trọng sự hòa thuận giữa người với người."]]},{"word":"深まる（理解が～）","reading":"ふかまる（りかいが～）","meaning":"sâu sắc thêm (sự hiểu biết)","hanViet":"THÂM LÝ GIẢI","lesson":19,"ex":[["日本に住んで、理解が深まりました。","Sống ở Nhật, sự hiểu biết của tôi đã sâu sắc hơn."],["本を読んで、日本の文化への理解が深まりました。","Đọc sách, sự hiểu biết về văn hóa Nhật Bản của tôi đã sâu sắc hơn."],["先生と話して、勉強への理解が深まりました。","Nói chuyện với thầy giáo, sự hiểu biết về việc học của tôi đã sâu sắc hơn."],["友達と話すたびに、理解が深まります。","Mỗi lần nói chuyện với bạn bè, sự hiểu biết lại sâu sắc thêm."],["経験が増えると、仕事への理解が深まります。","Kinh nghiệm tăng lên thì sự hiểu biết về công việc cũng sâu sắc hơn."]]},{"word":"身につける","reading":"みにつける","meaning":"tiếp thu, có được","hanViet":"THÂN","lesson":19,"ex":[["日本に住んで、日本の習慣を身につけました。","Sống ở Nhật, tôi đã tiếp thu thói quen của người Nhật."],["子どものときから、いい習慣を身につけましょう。","Từ khi còn nhỏ, hãy tập thói quen tốt."],["彼は、学校で英語を身につけました。","Anh ấy đã học được tiếng Anh ở trường."],["毎日練習して、ピアノを身につけます。","Luyện tập mỗi ngày để thành thạo piano."],["身につけたことを、仕事で使います。","Tôi dùng những điều đã học được vào công việc."]]},{"word":"取り戻す","reading":"とりもどす","meaning":"khôi phục, lấy lại","hanViet":"THỦ LỆ","lesson":19,"ex":[["病気が治って、健康を取り戻しました。","Bệnh khỏi rồi, tôi đã lấy lại sức khỏe."],["なくした本を取り戻しました。","Tôi đã lấy lại cuốn sách bị mất."],["チームは、試合の後半で元気を取り戻しました。","Đội đã lấy lại tinh thần ở hiệp hai của trận đấu."],["自信を取り戻すために、毎日練習します。","Để lấy lại sự tự tin, tôi luyện tập mỗi ngày."],["彼は、失敗したあと、元気を取り戻しました。","Sau khi thất bại, anh ấy đã lấy lại tinh thần."]]},{"word":"～号（台風～）","reading":"～ごう（たいふう～）","meaning":"(bão) số ~","hanViet":"HIỆU ĐÀI PHONG","lesson":19,"ex":[["台風10号が日本に来ています。","Bão số 10 đang đến Nhật Bản."],["台風5号は、明日上陸します。","Bão số 5 sẽ đổ bộ vào ngày mai."],["台風8号のために、電車が止まりました。","Vì bão số 8, tàu điện đã dừng chạy."],["台風12号は、大きい台風です。","Bão số 12 là cơn bão lớn."],["テレビで、台風3号の天気予報を見ました。","Tôi đã xem dự báo thời tiết về bão số 3 trên TV."]]},{"word":"上陸（する）","reading":"じょうりく（する）","meaning":"đổ bộ, vào đất liền","hanViet":"THƯỢNG LỤC","lesson":19,"ex":[["台風が明日、日本に上陸します。","Bão sẽ đổ bộ vào Nhật Bản ngày mai."],["台風が上陸したので、雨が強くなりました。","Vì bão đổ bộ nên mưa đã mạnh hơn."],["台風が上陸する前に、家に帰りました。","Trước khi bão đổ bộ, tôi đã về nhà."],["大きい台風が上陸すると、電車が止まります。","Khi bão lớn đổ bộ, tàu điện sẽ dừng."],["台風の上陸に注意してください。","Hãy chú ý khi bão đổ bộ."]]},{"word":"見込み","reading":"みこみ","meaning":"triển vọng, dự kiến, khả năng (xảy ra)","hanViet":"KIẾN","lesson":19,"ex":[["明日の天気は、雨の見込みです。","Thời tiết ngày mai dự báo có mưa."],["この仕事は、成功の見込みが高いです。","Công việc này có triển vọng thành công cao."],["試験に合格する見込みがあります。","Có triển vọng đỗ kỳ thi."],["今年の仕事の見込みは、去年よりいいです。","Triển vọng công việc năm nay tốt hơn năm ngoái."],["雨の見込みがあるので、傘を持ちます。","Vì dự báo có mưa nên tôi mang theo ô."]]},{"word":"セツブンソウ","reading":"","meaning":"Eranthis pinnatifida (một loại hoa nở vào mùa xuân)","hanViet":"","lesson":19,"ex":[["セツブンソウは、春に咲く花です。","Setsubunsou là loài hoa nở vào mùa xuân."],["セツブンソウは、山に咲きます。","Setsubunsou nở trên núi."],["セツブンソウの花は、小さいです。","Hoa setsubunsou nhỏ."],["春になると、セツブンソウが森に咲きます。","Khi xuân đến, setsubunsou nở trong rừng."],["セツブンソウを見るために、山に行きました。","Tôi đã lên núi để ngắm setsubunsou."]]},{"word":"分布（する）","reading":"ぶんぷ（する）","meaning":"phân bố","hanViet":"PHÂN BỐ","lesson":19,"ex":[["この花は、日本に広く分布しています。","Loài hoa này phân bố rộng khắp Nhật Bản."],["セツブンソウは、山に分布しています。","Setsubunsou phân bố trên núi."],["この動物は、世界の海に分布しています。","Loài động vật này phân bố ở các vùng biển trên thế giới."],["桜は、日本列島に分布しています。","Hoa anh đào phân bố khắp quần đảo Nhật Bản."],["植物の分布を調べるために、山に行きました。","Để nghiên cứu sự phân bố của thực vật, tôi đã lên núi."]]},{"word":"通勤（ラッシュ）","reading":"つうきん","meaning":"(giờ cao điểm) đi làm","hanViet":"THÔNG CẦN","lesson":19,"ex":[["朝の通勤ラッシュは、電車に人が多いです。","Giờ cao điểm đi làm buổi sáng, trên tàu điện rất đông người."],["通勤ラッシュの時間は、駅に人が多いです。","Vào giờ cao điểm đi làm, ở ga rất đông người."],["私は、通勤ラッシュの前に、早く家を出ます。","Tôi ra khỏi nhà sớm, trước giờ cao điểm đi làm."],["通勤ラッシュでは、電車に乗るのが難しいです。","Trong giờ cao điểm đi làm, việc lên tàu điện rất khó."],["通勤ラッシュが終わると、電車は静かになります。","Khi giờ cao điểm đi làm qua đi, tàu điện trở nên yên tĩnh."]]},{"word":"桜前線","reading":"さくらぜんせん","meaning":"tiền tuyến hoa anh đào","hanViet":"ANH TIỀN TUYẾN","lesson":19,"ex":[["桜前線は、春に日本を北上します。","Tiền tuyến hoa anh đào tiến lên phía Bắc Nhật Bản vào mùa xuân."],["テレビで、桜前線を見ました。","Tôi đã xem tiền tuyến hoa anh đào trên TV."],["桜前線が来ると、桜が咲きます。","Khi tiền tuyến hoa anh đào đến, hoa anh đào nở."],["今年の桜前線は、去年より早く来ます。","Tiền tuyến hoa anh đào năm nay đến sớm hơn năm ngoái."],["桜前線を見て、旅行に行きたくなります。","Nhìn tiền tuyến hoa anh đào, tôi muốn đi du lịch."]]},{"word":"～前線（桜～）","reading":"～ぜんせん（さくら～）","meaning":"tiền tuyến (hoa anh đào)","hanViet":"TIỀN TUYẾN ANH","lesson":19,"ex":[["桜前線は、南から北へ進みます。","Tiền tuyến hoa anh đào tiến từ nam lên bắc."],["桜前線が東京に来ると、桜が咲きます。","Khi tiền tuyến hoa anh đào đến Tokyo, hoa anh đào nở."],["桜前線は、天気予報でわかります。","Tiền tuyến hoa anh đào có thể biết qua dự báo thời tiết."],["桜前線を、毎日テレビで見ています。","Tôi xem tiền tuyến hoa anh đào trên TV mỗi ngày."],["桜前線が北に進むと、春が来ます。","Khi tiền tuyến hoa anh đào tiến lên phía bắc, mùa xuân đến."]]},{"word":"日本列島","reading":"にほんれっとう","meaning":"quần đảo Nhật Bản","hanViet":"NHẬT BẢN LIỆT ĐẢO","lesson":19,"ex":[["日本列島は、海の中にあります。","Quần đảo Nhật Bản nằm giữa biển."],["日本列島は、北から南まで長いです。","Quần đảo Nhật Bản dài từ bắc xuống nam."],["桜前線は、日本列島を北上します。","Tiền tuyến hoa anh đào tiến lên phía bắc quần đảo Nhật Bản."],["日本列島には、たくさんの島があります。","Quần đảo Nhật Bản có rất nhiều đảo."],["日本列島の天気は、北と南で変わります。","Thời tiết của quần đảo Nhật Bản thay đổi giữa miền bắc và miền nam."]]},{"word":"北上（する）","reading":"ほくじょう（する）","meaning":"lên phía Bắc","hanViet":"BẮC THƯỢNG","lesson":19,"ex":[["桜前線は、春に北上します。","Tiền tuyến hoa anh đào tiến lên phía bắc vào mùa xuân."],["台風が北上して、日本に来ます。","Bão tiến lên phía bắc và đến Nhật Bản."],["桜前線が北上すると、北の町にも春が来ます。","Khi tiền tuyến hoa anh đào tiến lên phía bắc, mùa xuân cũng đến các thị trấn phía bắc."],["春に、鳥が南から北上します。","Vào mùa xuân, chim từ phía nam bay lên phía bắc."],["台風の北上に、注意してください。","Hãy chú ý khi bão tiến lên phía bắc."]]},{"word":"梅雨","reading":"つゆ","meaning":"mùa mưa dầm","hanViet":"MAI VŨ","lesson":19,"ex":[["梅雨は、雨が多いです。","Mùa mưa dầm có nhiều mưa."],["梅雨のときは、雨の日が多いです。","Vào mùa mưa dầm, ngày mưa nhiều."],["梅雨が終わると、夏が来ます。","Khi mùa mưa dầm kết thúc, mùa hè đến."],["梅雨の間は、家にいることが多いです。","Trong mùa mưa dầm, tôi thường ở nhà."],["日本の梅雨は、6月に始まります。","Mùa mưa dầm ở Nhật bắt đầu vào tháng 6."]]},{"word":"見た目","reading":"みため","meaning":"vẻ bên ngoài, hình thức bên ngoài","hanViet":"KIẾN MỤC","lesson":19,"ex":[["この花は、見た目がいいです。","Bông hoa này trông đẹp."],["見た目がいい服は、よく売れます。","Quần áo trông đẹp bán rất chạy."],["彼は、見た目が若いです。","Anh ấy trông trẻ."],["見た目だけでは、人の気持ちはわかりません。","Chỉ nhìn vẻ bề ngoài thì không hiểu được cảm xúc của người khác."],["この料理は、見た目も味もいいです。","Món ăn này trông đẹp mà vị cũng ngon."]]},{"word":"評判","reading":"ひょうばん","meaning":"danh tiếng","hanViet":"BÌNH PHÁN","lesson":19,"ex":[["この店は、評判がいいです。","Cửa hàng này có tiếng tốt."],["あの先生は、生徒の間で評判がいいです。","Thầy giáo đó được học sinh đánh giá tốt."],["この映画は、評判がよくて、たくさんの人が見ます。","Bộ phim này có tiếng tốt nên nhiều người xem."],["評判のいい病院は、いつも人が多いです。","Bệnh viện có tiếng tốt lúc nào cũng đông người."],["この会社の評判は、去年よりよくなりました。","Danh tiếng của công ty này đã tốt hơn năm ngoái."]]},{"word":"国家試験","reading":"こっかしけん","meaning":"kì thi quốc gia","hanViet":"QUỐC GIA THÍ NGHIỆM","lesson":19,"ex":[["医者になるためには、国家試験に合格しなければなりません。","Để trở thành bác sĩ phải đỗ kỳ thi quốc gia."],["国家試験は、今年もあります。","Kỳ thi quốc gia năm nay cũng có."],["彼は、国家試験のために毎日勉強しています。","Anh ấy học mỗi ngày để chuẩn bị cho kỳ thi quốc gia."],["国家試験に合格すると、医者になります。","Đỗ kỳ thi quốc gia thì sẽ trở thành bác sĩ."],["国家試験は、とても難しいです。","Kỳ thi quốc gia rất khó."]]},{"word":"気が合う","reading":"きがあう","meaning":"hợp, hòa hợp","hanViet":"KHÍ HỢP","lesson":19,"ex":[["田中さんと山田さんは、気が合います。","Anh Tanaka và anh Yamada hợp nhau."],["私と彼は、気が合って、よく話します。","Tôi và anh ấy hợp nhau nên thường nói chuyện."],["気が合う友達は、大切です。","Bạn bè hợp nhau rất quý."],["気が合う人と仕事をすると、楽しいです。","Làm việc với người hợp nhau thì vui."],["彼女とは、会ったときから気が合いました。","Tôi và cô ấy đã hợp nhau ngay từ khi gặp nhau."]]},{"word":"赤字","reading":"あかじ","meaning":"thâm hụt, lỗ","hanViet":"XÍCH TỰ","lesson":19,"ex":[["この会社は、今年赤字になりました。","Công ty này năm nay bị lỗ."],["赤字が続くと、会社は困ります。","Lỗ liên tục thì công ty sẽ gặp khó khăn."],["赤字をなくすために、店の人はよく考えます。","Để hết lỗ, nhân viên cửa hàng suy nghĩ kỹ."],["赤字の会社は、給料が上がりません。","Công ty bị lỗ thì lương không tăng."],["今年の店は、赤字ではありませんでした。","Cửa hàng năm nay không bị lỗ."]]},{"word":"常に","reading":"つねに","meaning":"luôn luôn, thường xuyên","hanViet":"THƯỜNG","lesson":19,"ex":[["医者は、常に忙しいです。","Bác sĩ lúc nào cũng bận."],["彼は、常に新しいことを考えています。","Anh ấy luôn suy nghĩ những điều mới."],["安全は、常に大切です。","An toàn luôn quan trọng."],["私は、常に早く起きます。","Tôi luôn dậy sớm."],["先生は、常に生徒を助けています。","Thầy giáo luôn giúp đỡ học sinh."]]},{"word":"思い起こす","reading":"おもいおこす","meaning":"nhớ lại, gợi nhớ","hanViet":"TƯ KHỞI","lesson":19,"ex":[["この歌を聞くと、子どものときを思い起こします。","Nghe bài hát này, tôi nhớ lại thời thơ ấu."],["写真を見て、昔の旅行を思い起こしました。","Nhìn ảnh, tôi nhớ lại chuyến du lịch ngày xưa."],["彼は、学校の思い出を思い起こしました。","Anh ấy nhớ lại kỷ niệm ở trường."],["この花を見ると、田舎を思い起こします。","Nhìn bông hoa này, tôi nhớ lại quê nhà."],["先生の話を聞いて、子どものときを思い起こしました。","Nghe thầy giáo kể, tôi nhớ lại thời thơ ấu."]]},{"word":"～ごと（中身～）","reading":"～ごと（なかみ～）","meaning":"nguyên vẹn (vật bên trong)","hanViet":"TRUNG THÂN","lesson":19,"ex":[["冷蔵庫を中身ごと運びました。","Tôi đã mang cả tủ lạnh cùng đồ bên trong."],["箱を中身ごと捨てました。","Tôi đã vứt cả thùng cùng đồ bên trong."],["かばんを中身ごと忘れました。","Tôi đã quên cả cặp cùng đồ bên trong."],["袋を中身ごと持ちました。","Tôi đã mang cả túi cùng đồ bên trong."],["箱を中身ごと教室に置きました。","Tôi đã đặt cả thùng cùng đồ bên trong vào lớp học."]]},{"word":"ポピュラー（な）","reading":"","meaning":"phổ biến, thông dụng","hanViet":"","lesson":19,"ex":[["この歌は、若者にポピュラーです。","Bài hát này phổ biến với giới trẻ."],["サッカーは、日本でポピュラーなスポーツです。","Bóng đá là môn thể thao phổ biến ở Nhật."],["この本は、子どもにポピュラーです。","Cuốn sách này phổ biến với trẻ em."],["あの店は、ポピュラーな店です。","Cửa hàng đó là cửa hàng phổ biến."],["ポピュラーな映画は、たくさんの人が見ます。","Phim phổ biến thì nhiều người xem."]]},{"word":"担任","reading":"たんにん","meaning":"chủ nhiệm","hanViet":"ĐẢM NHIỆM","lesson":19,"ex":[["私の担任は、田中先生です。","Giáo viên chủ nhiệm của tôi là thầy Tanaka."],["担任の先生は、生徒をよく知っています。","Thầy giáo chủ nhiệm hiểu rõ học sinh."],["担任に、明日の授業について聞きました。","Tôi đã hỏi giáo viên chủ nhiệm về tiết học ngày mai."],["担任の先生は、毎日教室に来ます。","Thầy giáo chủ nhiệm đến lớp học mỗi ngày."],["新しい担任は、優しい先生です。","Giáo viên chủ nhiệm mới là thầy giáo hiền."]]},{"word":"保護者会","reading":"ほごしゃかい","meaning":"hội phụ huynh học sinh","hanViet":"BẢO HỘ GIẢ HỘI","lesson":19,"ex":[["保護者会は、来週あります。","Hội phụ huynh sẽ diễn ra tuần sau."],["保護者会で、先生と話しました。","Tôi đã nói chuyện với thầy giáo ở hội phụ huynh."],["お母さんは、保護者会に行きます。","Mẹ tôi sẽ đi họp phụ huynh."],["保護者会では、学校の話をします。","Ở hội phụ huynh, mọi người nói chuyện về trường học."],["保護者会のあと、担任と話しました。","Sau hội phụ huynh, tôi đã nói chuyện với giáo viên chủ nhiệm."]]},{"word":"学期（新～）","reading":"がっき（しん～）","meaning":"học kì (mới)","hanViet":"HỌC KỲ TÂN","lesson":19,"ex":[["新学期は、4月に始まります。","Học kỳ mới bắt đầu vào tháng 4."],["新学期から、新しいクラスに入ります。","Từ học kỳ mới, tôi sẽ vào lớp mới."],["新学期の前に、本を買いました。","Trước học kỳ mới, tôi đã mua sách."],["新学期は、子どもたちが元気に学校に来ます。","Học kỳ mới, trẻ em đến trường vui vẻ."],["新学期に、式があります。","Vào học kỳ mới, có buổi lễ."]]},{"word":"飼育（する）","reading":"しいく（する）","meaning":"nuôi nấng","hanViet":"TỰ DỤC","lesson":19,"ex":[["学校で、亀を飼育しています。","Ở trường, học sinh đang nuôi rùa."],["子どもたちは、犬を飼育しています。","Trẻ em đang nuôi chó."],["動物園では、たくさんの動物を飼育しています。","Ở sở thú, người ta nuôi rất nhiều động vật."],["飼育する動物は、毎日食べ物が必要です。","Động vật nuôi cần thức ăn mỗi ngày."],["彼は、家で猫を飼育しています。","Anh ấy đang nuôi mèo ở nhà."]]},{"word":"一体感","reading":"いったいかん","meaning":"ý thức đoàn kết","hanViet":"NHẤT THỂ CẢM","lesson":19,"ex":[["運動会で、クラスの一体感が生まれました。","Ở hội thao, tinh thần đoàn kết của lớp đã nảy sinh."],["チームの一体感が、試合の力になります。","Tinh thần đoàn kết của đội trở thành sức mạnh trong trận đấu."],["一体感があるクラスは、楽しいです。","Lớp có tinh thần đoàn kết thì vui vẻ."],["みんなで歌うと、一体感が生まれます。","Khi mọi người cùng hát, tinh thần đoàn kết nảy sinh."],["一体感を大切にする会社は、強いです。","Công ty coi trọng tinh thần đoàn kết thì mạnh."]]},{"word":"無用（な）","reading":"むよう（な）","meaning":"không cần","hanViet":"VÔ DỤNG","lesson":19,"ex":[["この古い本は、もう無用です。","Cuốn sách cũ này đã không cần nữa."],["無用な本は、捨てましょう。","Sách không cần nữa thì hãy vứt đi."],["無用な荷物は、家に置きます。","Hành lý không cần thì để ở nhà."],["この服は、もう無用になりました。","Bộ đồ này đã không cần nữa."],["無用な電気は、消しましょう。","Điện không cần thì hãy tắt đi."]]},{"word":"後ろ向き","reading":"うしろむき","meaning":"hướng về phía sau, thái độ tiêu cực","hanViet":"HẬU HƯỚNG","lesson":19,"ex":[["後ろ向きな気持ちは、やめましょう。","Hãy bỏ suy nghĩ tiêu cực đi."],["彼は、後ろ向きな人です。","Anh ấy là người tiêu cực."],["後ろ向きな人は、仕事が進みません。","Người tiêu cực thì công việc không tiến triển."],["後ろ向きに考えると、元気が出ません。","Nghĩ tiêu cực thì sẽ không có tinh thần."],["失敗しても、後ろ向きにならないでください。","Dù thất bại cũng đừng trở nên tiêu cực."]]},{"word":"前向き","reading":"まえむき","meaning":"hướng về phía trước, thái độ tích cực","hanViet":"TIỀN HƯỚNG","lesson":19,"ex":[["前向きな気持ちは、大切です。","Thái độ tích cực rất quan trọng."],["彼女は、前向きな人です。","Cô ấy là người tích cực."],["前向きに考えると、仕事が楽しくなります。","Nghĩ tích cực thì công việc trở nên vui vẻ."],["失敗しても、前向きに頑張ります。","Dù thất bại, tôi vẫn cố gắng tích cực."],["みんなは、前向きな人が好きです。","Mọi người thích người tích cực."]]},{"word":"油断（する）","reading":"ゆだん（する）","meaning":"chủ quan","hanViet":"DU ĐOẠN","lesson":19,"ex":[["試合で油断すると、負けます。","Chủ quan trong trận đấu thì sẽ thua."],["油断しないで、最後まで頑張りましょう。","Đừng chủ quan, hãy cố gắng đến cuối cùng."],["彼は、油断して、試合に負けました。","Anh ấy đã chủ quan và thua trận đấu."],["車を運転するときは、油断してはいけません。","Khi lái xe thì không được chủ quan."],["油断すると、失敗します。","Chủ quan thì sẽ thất bại."]]},{"word":"初回","reading":"しょかい","meaning":"lần đầu tiên","hanViet":"SƠ HỒI","lesson":19,"ex":[["初回は、明日です。","Lần đầu tiên là ngày mai."],["初回の授業は、来週あります。","Tiết học đầu tiên sẽ diễn ra tuần sau."],["初回の試合は、来週です。","Trận đấu đầu tiên là tuần sau."],["初回の試験は、難しかったです。","Kỳ thi đầu tiên rất khó."],["初回のコンサートは、楽しかったです。","Buổi hòa nhạc đầu tiên rất vui."]]},{"word":"得点","reading":"とくてん","meaning":"ghi điểm, ghi bàn","hanViet":"ĐẮC ĐIỂM","lesson":19,"ex":[["彼は、試合で得点しました。","Anh ấy đã ghi điểm trong trận đấu."],["チームは、後半に得点しました。","Đội đã ghi điểm ở hiệp hai."],["得点した選手は、とてもうれしそうでした。","Cầu thủ ghi điểm trông rất vui."],["サッカーの試合で、山田さんが得点しました。","Trong trận bóng đá, anh Yamada đã ghi điểm."],["得点するために、毎日練習しています。","Để ghi điểm, tôi luyện tập mỗi ngày."]]},{"word":"興奮（する）","reading":"こうふん（する）","meaning":"hưng phấn, hào hứng","hanViet":"HƯNG PHẤN","lesson":19,"ex":[["試合を見て、興奮しました。","Xem trận đấu, tôi đã rất hào hứng."],["子どもたちは、遊園地で興奮しました。","Trẻ em đã rất hào hứng ở công viên giải trí."],["興奮して、声を出しました。","Hào hứng quá, tôi đã hét lên."],["彼女は、コンサートで興奮しました。","Cô ấy đã rất hào hứng ở buổi hòa nhạc."],["興奮した子どもたちは、元気に遊びます。","Trẻ em hào hứng chơi đùa vui vẻ."]]},{"word":"チームメイト","reading":"","meaning":"đồng đội","hanViet":"","lesson":19,"ex":[["チームメイトと練習します。","Tôi luyện tập cùng đồng đội."],["チームメイトは、みんな優しいです。","Đồng đội ai cũng hiền."],["チームメイトと話すと、楽しいです。","Nói chuyện với đồng đội thì vui."],["新しいチームメイトは、サッカーが上手です。","Đồng đội mới chơi bóng đá giỏi."],["チームメイトに助けられて、試合に勝ちました。","Nhờ đồng đội giúp đỡ, tôi đã thắng trận đấu."]]},{"word":"以前","reading":"いぜん","meaning":"trước đây","hanViet":"DĨ TIỀN","lesson":19,"ex":[["以前は、東京に住んでいました。","Trước đây, tôi đã sống ở Tokyo."],["以前は、サッカーが下手でした。","Trước đây, tôi chơi bóng đá dở."],["以前より、日本語が上手になりました。","Tiếng Nhật của tôi đã giỏi hơn trước đây."],["以前は、毎日電車で会社に行きました。","Trước đây, tôi đi làm bằng tàu điện mỗi ngày."],["以前、この町に住んでいました。","Trước đây, tôi đã sống ở thị trấn này."]]},{"word":"掃く","reading":"はく","meaning":"quét","hanViet":"TẢO","lesson":19,"ex":[["毎日、部屋を掃きます。","Tôi quét phòng mỗi ngày."],["庭の葉を掃きました。","Tôi đã quét lá trong vườn."],["廊下を掃いて、きれいにしました。","Tôi đã quét hành lang cho sạch."],["朝、道を掃きます。","Buổi sáng, tôi quét đường."],["公園の道を掃く仕事をしています。","Tôi làm công việc quét đường trong công viên."]]},{"word":"清掃（する）","reading":"せいそう（する）","meaning":"dọn dẹp, làm vệ sinh","hanViet":"THANH TẢO","lesson":19,"ex":[["毎日、教室を清掃します。","Tôi dọn dẹp lớp học mỗi ngày."],["清掃のあと、部屋がきれいになりました。","Sau khi dọn dẹp, căn phòng đã sạch đẹp."],["先生と生徒は、学校を清掃しました。","Thầy giáo và học sinh đã dọn dẹp trường học."],["清掃するために、掃除機を使います。","Để dọn dẹp, tôi dùng máy hút bụi."],["週末に、家を清掃します。","Cuối tuần, tôi dọn dẹp nhà cửa."]]},{"word":"廃品回収","reading":"はいひんかいしゅう","meaning":"thu gom phế phẩm","hanViet":"PHẾ PHẨM HỒI THU, THÂU","lesson":19,"ex":[["廃品回収の日は、新聞を出します。","Vào ngày thu gom phế phẩm, tôi mang báo ra."],["廃品回収では、空き缶を集めます。","Thu gom phế phẩm thì gom lon rỗng."],["廃品回収の車が、町に来ました。","Xe thu gom phế phẩm đã đến thị trấn."],["廃品回収のために、古い新聞を置きます。","Để thu gom phế phẩm, tôi để báo cũ sẵn."],["廃品回収は、来週あります。","Thu gom phế phẩm sẽ diễn ra tuần sau."]]},{"word":"回収（する）","reading":"かいしゅう（する）","meaning":"thu hồi, thu gom","hanViet":"HỒI THU, THÂU","lesson":19,"ex":[["空き缶を回収します。","Tôi thu gom lon rỗng."],["会社は、古い製品を回収しました。","Công ty đã thu hồi sản phẩm cũ."],["新聞を回収する日は、来週です。","Ngày thu gom báo là tuần sau."],["ごみを回収するために、車が来ます。","Xe đến để thu gom rác."],["回収した新聞は、会社に送ります。","Tôi gửi báo đã thu gom đến công ty."]]},{"word":"電化（する）","reading":"でんか（する）","meaning":"điện khí hóa","hanViet":"ĐIỆN HÓA","lesson":19,"ex":[["この村は、電化しました。","Làng này đã được điện khí hóa."],["電化した家は、明るくなりました。","Nhà có điện đã trở nên sáng sủa."],["田舎の電化が進んでいます。","Việc điện khí hóa nông thôn đang tiến triển."],["電化のために、電気の仕事をする人が来ました。","Vì điện khí hóa, người làm việc về điện đã đến."],["電化した町は、夜も明るいです。","Thị trấn có điện thì ban đêm cũng sáng."]]},{"word":"個別","reading":"こべつ","meaning":"riêng","hanViet":"CÁ BIỆT","lesson":19,"ex":[["先生は、生徒に個別に教えます。","Thầy giáo dạy riêng từng học sinh."],["個別の問題は、先生に相談します。","Vấn đề riêng thì hỏi ý kiến thầy giáo."],["個別に勉強する時間が大切です。","Thời gian học riêng rất quan trọng."],["この学校は、個別の教育をしています。","Trường này thực hiện giáo dục riêng cho từng em."],["個別に話すために、先生に会いました。","Để nói chuyện riêng, tôi đã gặp thầy giáo."]]},{"word":"豆腐","reading":"とうふ","meaning":"đậu phụ","hanViet":"ĐẬU HỦ","lesson":19,"ex":[["豆腐は、日本の食べ物です。","Đậu phụ là món ăn của Nhật."],["毎日、豆腐を食べます。","Tôi ăn đậu phụ mỗi ngày."],["豆腐は、体にいいです。","Đậu phụ tốt cho cơ thể."],["店で、豆腐を買いました。","Tôi đã mua đậu phụ ở cửa hàng."],["豆腐の料理は、おいしいです。","Món đậu phụ ngon."]]},{"word":"手元","reading":"てもと","meaning":"gần tay, trong tầm tay; sẵn có bên người","hanViet":"THỦ NGUYÊN","lesson":19,"ex":[["手元に、本があります。","Cuốn sách ở ngay trong tầm tay tôi."],["手元の資料を見てください。","Hãy xem tài liệu trong tay."],["手元にお金がありません。","Tôi không có tiền trong người."],["手元の辞書で、意味を調べました。","Tôi đã tra nghĩa bằng từ điển trong tay."],["手元に、地図があります。","Bản đồ ở ngay trong tầm tay tôi."]]},{"word":"そうっと／そっと","reading":"","meaning":"nhẹ nhàng, nhẹ tay","hanViet":"","lesson":19,"ex":[["赤ちゃんが寝ているので、そっと歩きます。","Vì em bé đang ngủ nên tôi đi nhẹ nhàng."],["そっとドアを閉めました。","Tôi đã đóng cửa nhẹ nhàng."],["そうっと本を置きました。","Tôi đã đặt sách xuống nhẹ nhàng."],["そっと話してください。","Hãy nói khẽ."],["そうっと歩いて、部屋に入りました。","Tôi đi nhẹ nhàng và vào phòng."]]},{"word":"扱う","reading":"あつかう","meaning":"xử lý, thao tác; đối xử (với người)","hanViet":"TRÁP","lesson":19,"ex":[["このパソコンを扱うのは、難しいです。","Thao tác máy tính này khó."],["彼は、車を上手に扱います。","Anh ấy lái xe giỏi."],["先生は、生徒を優しく扱います。","Thầy giáo đối xử hiền với học sinh."],["このカメラを扱うときは、注意してください。","Khi thao tác máy ảnh này, hãy cẩn thận."],["彼は、お金を上手に扱います。","Anh ấy quản lý tiền giỏi."]]},{"word":"未～（～経験）","reading":"み～（～けいけん）","meaning":"chưa có (kinh nghiệm)","hanViet":"VỊ KINH NGHIỆM","lesson":19,"ex":[["彼は、未経験ですが、仕事を頑張ります。","Anh ấy chưa có kinh nghiệm nhưng cố gắng làm việc."],["未経験の人は、まず練習します。","Người chưa có kinh nghiệm thì trước hết luyện tập."],["未経験でも、仕事ができます。","Dù chưa có kinh nghiệm vẫn làm được việc."],["未経験の先生は、生徒に優しいです。","Thầy giáo chưa có kinh nghiệm thì hiền với học sinh."],["未経験から始めて、仕事を覚えました。","Bắt đầu từ chưa có kinh nghiệm, tôi đã học được công việc."]]},{"word":"体験（する）","reading":"たいけん（する）","meaning":"trải nghiệm","hanViet":"THỂ NGHIỆM","lesson":19,"ex":[["日本で、いろいろなことを体験しました。","Ở Nhật, tôi đã trải nghiệm nhiều điều."],["子どもたちは、田舎の生活を体験しました。","Trẻ em đã trải nghiệm cuộc sống nông thôn."],["体験して、初めてわかりました。","Trải nghiệm rồi tôi mới hiểu."],["彼は、外国での生活を体験しました。","Anh ấy đã trải nghiệm cuộc sống ở nước ngoài."],["体験することは、勉強になります。","Trải nghiệm trở thành bài học."]]},{"word":"自信","reading":"じしん","meaning":"sự tự tin","hanViet":"TỰ TÍN","lesson":19,"ex":[["自信を持って、試験を受けます。","Tôi tự tin đi thi."],["彼は、自信がありません。","Anh ấy không tự tin."],["練習して、自信が強くなりました。","Luyện tập, sự tự tin của tôi đã mạnh lên."],["自信を持つことは、大切です。","Có sự tự tin rất quan trọng."],["彼女は、自信を持って話します。","Cô ấy nói chuyện một cách tự tin."]]},{"word":"力（生きる～）","reading":"ちから（いきる～）","meaning":"sức lực (để sống)","hanViet":"LỰC SINH","lesson":19,"ex":[["生きる力を身につけることは、大切です。","Có được sức mạnh để sống rất quan trọng."],["彼は、生きる力が強いです。","Anh ấy có sức sống mạnh mẽ."],["難しいときも、生きる力を持っています。","Ngay cả lúc khó khăn, tôi vẫn có sức mạnh để sống."],["生きる力を育てるために、学校で勉強します。","Để nuôi dưỡng sức mạnh để sống, tôi học ở trường."],["生きる力は、経験から生まれます。","Sức mạnh để sống nảy sinh từ kinh nghiệm."]]},{"word":"サポート（する）","reading":"","meaning":"ủng hộ, hỗ trợ","hanViet":"","lesson":19,"ex":[["先生は、生徒をサポートします。","Thầy giáo hỗ trợ học sinh."],["家族は、私をサポートしてくれます。","Gia đình hỗ trợ tôi."],["チームメイトをサポートすることは、大切です。","Hỗ trợ đồng đội rất quan trọng."],["会社は、みんなをサポートしています。","Công ty đang hỗ trợ mọi người."],["友達のサポートで、試験に合格しました。","Nhờ bạn bè hỗ trợ, tôi đã đỗ kỳ thi."]]},{"word":"敵","reading":"てき","meaning":"địch","hanViet":"ĐỊCH","lesson":19,"ex":[["試合の敵は、強いチームです。","Đối thủ trong trận đấu là đội mạnh."],["敵に勝つために、毎日練習します。","Để thắng đối thủ, tôi luyện tập mỗi ngày."],["敵の選手は、サッカーが上手です。","Cầu thủ đối phương chơi bóng đá giỏi."],["敵と試合をするときは、油断してはいけません。","Khi thi đấu với đối thủ thì không được chủ quan."],["敵も、いいチームです。","Đối thủ cũng là đội hay."]]},{"word":"状態","reading":"じょうたい","meaning":"trạng thái","hanViet":"TRẠNG THÁI","lesson":19,"ex":[["彼の健康の状態は、いいです。","Tình trạng sức khỏe của anh ấy tốt."],["車の状態を調べました。","Tôi đã kiểm tra tình trạng của xe."],["天気の状態が、悪くなりました。","Tình trạng thời tiết đã xấu đi."],["病気の状態は、よくなりました。","Tình trạng bệnh đã tốt hơn."],["この本の状態は、いいです。","Tình trạng của cuốn sách này tốt."]]},{"word":"走りこむ","reading":"はしりこむ","meaning":"chạy vào","hanViet":"TẨU","lesson":19,"ex":[["選手がグラウンドに走りこみました。","Cầu thủ đã chạy vào sân."],["子どもたちが公園に走りこみました。","Trẻ em đã chạy vào công viên."],["試合の前に、選手がグラウンドに走りこみます。","Trước trận đấu, cầu thủ chạy vào sân."],["犬が庭に走りこみました。","Con chó đã chạy vào vườn."],["彼は、教室に走りこみました。","Anh ấy đã chạy vào lớp học."]]},{"word":"パスコース","reading":"","meaning":"đường chuyền bóng","hanViet":"","lesson":19,"ex":[["パスコースを考えて、パスをします。","Nghĩ đường chuyền bóng rồi chuyền bóng."],["いいパスコースを見つけました。","Tôi đã tìm được đường chuyền bóng tốt."],["パスコースが開いています。","Đường chuyền bóng đang mở."],["選手は、パスコースを探しています。","Cầu thủ đang tìm đường chuyền bóng."],["パスコースを変えて、試合に勝ちます。","Đổi đường chuyền bóng để thắng trận đấu."]]},{"word":"パス","reading":"","meaning":"chuyền bóng","hanViet":"","lesson":19,"ex":[["選手がチームメイトにパスをしました。","Cầu thủ đã chuyền bóng cho đồng đội."],["パスを受けて、シュートしました。","Nhận đường chuyền rồi sút bóng."],["いいパスをすると、得点できます。","Chuyền bóng tốt thì có thể ghi điểm."],["パスを練習して、上手になりました。","Luyện chuyền bóng, tôi đã giỏi hơn."],["彼は、パスが上手です。","Anh ấy chuyền bóng giỏi."]]},{"word":"シュート（する）","reading":"","meaning":"sút bóng","hanViet":"","lesson":19,"ex":[["選手がシュートしました。","Cầu thủ đã sút bóng."],["サッカーの試合で、シュートして得点しました。","Trong trận bóng đá, tôi đã sút bóng và ghi điểm."],["シュートする前に、ボールを見ます。","Trước khi sút bóng, tôi nhìn quả bóng."],["彼は、シュートが上手です。","Anh ấy sút bóng giỏi."],["シュートを練習して、試合に勝ちたいです。","Tôi luyện sút bóng vì muốn thắng trận đấu."]]},{"word":"尺八","reading":"しゃくはち","meaning":"sáo shakuhachi (sáo trúc)","hanViet":"XÍCH BÁT","lesson":20,"ex":[["尺八は、日本の楽器です。","Sáo shakuhachi là nhạc cụ của Nhật."],["彼は、尺八の演奏を聞きました。","Anh ấy đã nghe biểu diễn sáo shakuhachi."],["尺八の音は、静かです。","Âm thanh của sáo shakuhachi yên tĩnh."],["演奏会で、尺八を聞きました。","Tôi đã nghe sáo shakuhachi ở buổi hòa nhạc."],["田中さんは、尺八を練習しています。","Anh Tanaka đang luyện sáo shakuhachi."]]},{"word":"理解（する）","reading":"りかい（する）","meaning":"hiểu biết, lí giải","hanViet":"LÝ GIẢI","lesson":20,"ex":[["この本を読むと、日本の文化がよく理解できます。","Đọc cuốn sách này, bạn sẽ hiểu rõ văn hóa Nhật Bản."],["先生の説明を聞いて、問題の意味が理解できました。","Nghe thầy giải thích, tôi đã hiểu ý nghĩa của bài toán."],["外国の文化を理解することは、大切なことだと思います。","Tôi nghĩ việc hiểu văn hóa nước ngoài là điều quan trọng."],["日本語の文法は難しいですが、だんだん理解しています。","Ngữ pháp tiếng Nhật khó nhưng tôi đang dần hiểu ra."],["友達の気持ちを理解するために、よく話を聞きます。","Để hiểu cảm xúc của bạn bè, tôi thường lắng nghe họ nói chuyện."]]},{"word":"文化面（新聞の～）","reading":"ぶんかめん（しんぶんの～）","meaning":"trang văn hóa (trên báo)","hanViet":"VĂN HÓA DIỆN TÂN VĂN","lesson":20,"ex":[["新聞の文化面に、音楽会の記事が出ていました。","Trên trang văn hóa của báo có bài viết về buổi hòa nhạc."],["父は毎朝、新聞の文化面を読んでいます。","Bố tôi mỗi sáng đều đọc trang văn hóa của báo."],["文化面には、本や映画の紹介がたくさんあります。","Trang văn hóa có rất nhiều bài giới thiệu sách và phim."],["この新聞の文化面は、読みやすくておもしろいです。","Trang văn hóa của tờ báo này dễ đọc và thú vị."],["文化面の記事を読んで、新しい歌手を知りました。","Đọc bài trên trang văn hóa, tôi đã biết thêm một ca sĩ mới."]]},{"word":"プロフィール","reading":"","meaning":"hồ sơ, lý lịch","hanViet":"","lesson":20,"ex":[["この本の最後に、著者のプロフィールが書いてあります。","Ở cuối cuốn sách này có viết hồ sơ của tác giả."],["雑誌のプロフィールを読んで、歌手の誕生日を知りました。","Đọc hồ sơ trên tạp chí, tôi đã biết ngày sinh của ca sĩ."],["会社のホームページに、社長のプロフィールがあります。","Trên trang web của công ty có hồ sơ của giám đốc."],["プロフィールを見ると、その音楽家は京都で生まれました。","Xem hồ sơ, tôi biết nhạc sĩ đó sinh ra ở Kyoto."],["プロフィールを書くときは、名前と年齢を書きます。","Khi viết hồ sơ, tôi viết tên và tuổi."]]},{"word":"取る（相撲を～）","reading":"とる（すもうを～）","meaning":"thi đấu (sumo)","hanViet":"THỦ TƯƠNG, TƯỚNG PHÁC","lesson":20,"ex":[["その力士は、毎日相撲を取って練習しています。","Võ sĩ sumo đó mỗi ngày đều thi đấu sumo để luyện tập."],["相撲を取る力士は、体が大きくて強いです。","Võ sĩ thi đấu sumo có thân hình to lớn và khỏe mạnh."],["小さいころから相撲を取るのが好きでした。","Từ nhỏ tôi đã thích thi đấu sumo."],["彼は相撲を取って、有名になりました。","Anh ấy trở nên nổi tiếng nhờ thi đấu sumo."],["日本で相撲を取る選手は、世界から来ます。","Các võ sĩ thi đấu sumo ở Nhật Bản đến từ khắp nơi trên thế giới."]]},{"word":"手順","reading":"てじゅん","meaning":"quy trình, trình tự","hanViet":"THỦ THUẬN","lesson":20,"ex":[["この仕事の手順を、先生に教えてもらいました。","Tôi đã được thầy chỉ cho quy trình của công việc này."],["手順を守れば、料理が上手にできます。","Nếu làm theo đúng trình tự, bạn sẽ nấu ăn ngon."],["この機械を使う手順を説明します。","Tôi sẽ giải thích trình tự sử dụng chiếc máy này."],["手順がわからないときは、友達に聞きます。","Khi không biết trình tự, tôi hỏi bạn bè."],["試験の手順をよく読んでから、答えを書きます。","Đọc kỹ trình tự của bài thi rồi mới viết đáp án."]]},{"word":"管楽器","reading":"かんがっき","meaning":"bộ hơi (các loại nhạc cụ dùng hơi để thổi)","hanViet":"QUẢN LẠC, NHẠC KHÍ","lesson":20,"ex":[["管楽器には、フルートやトロンボーンがあります。","Bộ hơi gồm có sáo flute và kèn trombone."],["管楽器を演奏する人は、毎日練習します。","Người chơi nhạc cụ hơi luyện tập mỗi ngày."],["学校の音楽会で、管楽器の演奏を聞きました。","Tại buổi hòa nhạc ở trường, tôi đã nghe màn trình diễn của bộ hơi."],["管楽器は、息を吹いて音を出します。","Nhạc cụ hơi tạo ra âm thanh bằng cách thổi hơi vào."],["私は管楽器が好きで、フルートを習っています。","Tôi thích nhạc cụ hơi và đang học sáo flute."]]},{"word":"邦楽","reading":"ほうがく","meaning":"nhạc truyền thống của Nhật","hanViet":"BANG LẠC, NHẠC","lesson":20,"ex":[["邦楽は、日本の伝統的な音楽です。","邦楽 là âm nhạc truyền thống của Nhật Bản."],["祖父は邦楽が好きで、よく聞いています。","Ông tôi thích nhạc truyền thống Nhật và thường nghe."],["邦楽のコンサートに、初めて行きました。","Tôi đã đi nghe hòa nhạc truyền thống Nhật lần đầu tiên."],["邦楽には、琴や三味線の音があります。","Nhạc truyền thống Nhật có tiếng đàn koto và đàn shamisen."],["日本の邦楽を、世界の人に紹介したいです。","Tôi muốn giới thiệu nhạc truyền thống Nhật Bản với mọi người trên thế giới."]]},{"word":"笙","reading":"しょう","meaning":"kèn sho","hanViet":"SANH","lesson":20,"ex":[["笙は、日本の古い楽器です。","Kèn sho là nhạc cụ cổ của Nhật Bản."],["笙の音は、静かできれいです。","Âm thanh của kèn sho yên tĩnh và đẹp."],["邦楽のコンサートで、笙の演奏を聞きました。","Tại buổi hòa nhạc truyền thống, tôi đã nghe kèn sho biểu diễn."],["笙を吹く人は、あまり多くありません。","Người thổi kèn sho không nhiều lắm."],["私は笙の音色が好きです。","Tôi thích âm sắc của kèn sho."]]},{"word":"琴","reading":"こと","meaning":"đàn koto","hanViet":"CẦM","lesson":20,"ex":[["琴は、日本の伝統的な楽器です。","Đàn koto là nhạc cụ truyền thống của Nhật Bản."],["母は琴を習っていて、毎日練習します。","Mẹ tôi đang học đàn koto và luyện tập mỗi ngày."],["琴の音は、静かで美しいです。","Tiếng đàn koto yên tĩnh và đẹp."],["学校の音楽会で、琴を弾きました。","Tại buổi hòa nhạc ở trường, tôi đã chơi đàn koto."],["琴のコンサートのチケットを買いました。","Tôi đã mua vé xem hòa nhạc đàn koto."]]},{"word":"三味線","reading":"しゃみせん","meaning":"đàn shamisen","hanViet":"TAM VỊ TUYẾN","lesson":20,"ex":[["三味線は、日本の古い楽器です。","Đàn shamisen là nhạc cụ cổ của Nhật Bản."],["三味線の音を聞くと、日本の昔を思い出します。","Nghe tiếng đàn shamisen, tôi nhớ về nước Nhật ngày xưa."],["彼は三味線を上手に弾きます。","Anh ấy chơi đàn shamisen rất giỏi."],["三味線のコンサートに、友達と行きました。","Tôi đã đi xem hòa nhạc shamisen cùng bạn."],["三味線を習うために、毎週教室に行きます。","Để học đàn shamisen, tôi đến lớp học mỗi tuần."]]},{"word":"小鼓","reading":"こつづみ","meaning":"trống kotsuzumi","hanViet":"TIỂU CỔ","lesson":20,"ex":[["小鼓は、日本の伝統的な楽器です。","Trống kotsuzumi là nhạc cụ truyền thống của Nhật Bản."],["小鼓の音は、小さくて軽いです。","Tiếng trống kotsuzumi nhỏ và nhẹ."],["邦楽のコンサートで、小鼓の演奏を聞きました。","Tại buổi hòa nhạc truyền thống, tôi đã nghe trống kotsuzumi biểu diễn."],["小鼓を習うのは、難しいです。","Học trống kotsuzumi rất khó."],["小鼓と三味線の演奏を聞きました。","Tôi đã nghe trống kotsuzumi và đàn shamisen biểu diễn."]]},{"word":"民族（音楽）","reading":"みんぞく（おんがく）","meaning":"(nhạc) dân gian","hanViet":"DÂN TỘC ÂM LẠC, NHẠC","lesson":20,"ex":[["民族音楽を聞くと、その国の文化がわかります。","Nghe nhạc dân gian, bạn sẽ hiểu văn hóa của đất nước đó."],["世界の民族音楽を聞くのが好きです。","Tôi thích nghe nhạc dân gian thế giới."],["民族音楽のコンサートに、初めて行きました。","Tôi đã đi nghe hòa nhạc dân gian lần đầu tiên."],["日本の民族音楽は、古い歴史があります。","Nhạc dân gian Nhật Bản có lịch sử lâu đời."],["民族音楽を聞いて、世界の文化を勉強します。","Nghe nhạc dân gian, tôi học về văn hóa thế giới."]]},{"word":"奏者","reading":"そうしゃ","meaning":"nghệ sĩ biểu diễn","hanViet":"TẤU GIẢ","lesson":20,"ex":[["その奏者は、フルートが上手です。","Nghệ sĩ biểu diễn đó chơi sáo flute rất giỏi."],["奏者の演奏を聞いて、とてもうれしかったです。","Nghe nghệ sĩ biểu diễn, tôi rất vui."],["有名な奏者が、東京でコンサートを開きます。","Nghệ sĩ nổi tiếng sẽ tổ chức hòa nhạc ở Tokyo."],["奏者は、毎日何時間も練習します。","Nghệ sĩ biểu diễn luyện tập nhiều giờ mỗi ngày."],["その奏者の音色は、とても美しいです。","Âm sắc của nghệ sĩ đó rất đẹp."]]},{"word":"授かる","reading":"さずかる","meaning":"được phong tặng (danh hiệu)","hanViet":"THỤ","lesson":20,"ex":[["彼は有名な賞を授かりました。","Anh ấy đã được trao giải thưởng danh giá."],["先生は、大きな賞を授かりました。","Thầy đã được trao giải thưởng lớn."],["その音楽家は、若いときに大きな賞を授かりました。","Nhạc sĩ đó đã được trao giải thưởng lớn khi còn trẻ."],["賞を授かることは、とても光栄なことです。","Được trao giải thưởng là điều rất vinh dự."],["彼は努力の結果、賞を授かりました。","Nhờ nỗ lực, anh ấy đã được trao giải thưởng."]]},{"word":"内外（国の～）","reading":"ないがい（くにの～）","meaning":"trong ngoài (nước)","hanViet":"NỘI NGOẠI QUỐC","lesson":20,"ex":[["その音楽は、国の内外で有名です。","Âm nhạc đó nổi tiếng trong và ngoài nước."],["国の内外から、たくさんの人がコンサートに来ます。","Rất nhiều người từ trong và ngoài nước đến xem hòa nhạc."],["その本は、国の内外で読まれています。","Cuốn sách đó được đọc trong và ngoài nước."],["国の内外の音楽を、よく聞きます。","Tôi thường nghe nhạc trong và ngoài nước."],["彼の演奏は、国の内外の人に愛されています。","Màn trình diễn của anh ấy được mọi người trong và ngoài nước yêu thích."]]},{"word":"古典","reading":"こてん","meaning":"cổ điển","hanViet":"CỔ ĐIỂN","lesson":20,"ex":[["古典の音楽を聞くのが好きです。","Tôi thích nghe nhạc cổ điển."],["日本の古典を勉強しています。","Tôi đang học văn học cổ điển Nhật Bản."],["古典の本を読むのは、難しいです。","Đọc sách cổ điển rất khó."],["その映画は、古典の物語をもとに作られました。","Bộ phim đó được làm dựa trên câu chuyện cổ điển."],["古典を理解するために、歴史を勉強します。","Để hiểu văn học cổ điển, tôi học lịch sử."]]},{"word":"修行（する）","reading":"しゅぎょう（する）","meaning":"học, học nghề","hanViet":"TU HÀNH","lesson":20,"ex":[["彼は先生のもとで修行しています。","Anh ấy đang học nghề dưới sự chỉ dạy của thầy."],["修行を続けることは、大変です。","Tiếp tục học nghề là việc rất vất vả."],["日本の音楽を修行するために、京都に来ました。","Để học nhạc Nhật, tôi đã đến Kyoto."],["修行の時間は、長くて厳しいです。","Thời gian học nghề dài và khắc nghiệt."],["彼は長い間、修行を続けました。","Anh ấy đã tiếp tục học nghề trong thời gian dài."]]},{"word":"自ら","reading":"みずから","meaning":"tự mình","hanViet":"TỰ","lesson":20,"ex":[["自ら調べて、答えを見つけました。","Tôi đã tự mình tìm hiểu và tìm ra đáp án."],["彼は自ら音楽を作っています。","Anh ấy tự mình sáng tác nhạc."],["自ら考えることが、大切です。","Tự mình suy nghĩ là việc quan trọng."],["自ら行って、話を聞きました。","Tôi đã tự mình đến và lắng nghe câu chuyện."],["問題は、自ら解決するべきです。","Vấn đề thì nên tự mình giải quyết."]]},{"word":"半生","reading":"はんせい","meaning":"nửa đời người","hanViet":"BÁN SINH","lesson":20,"ex":[["彼は半生を音楽と過ごしました。","Anh ấy đã trải qua nửa đời người cùng âm nhạc."],["その本には、音楽家の半生が書いてあります。","Trong cuốn sách đó có viết về nửa đời người của nhạc sĩ."],["半生をかけて、日本の音楽を勉強しました。","Tôi đã dành nửa đời người để học nhạc Nhật."],["彼は半生を、外国で過ごしました。","Anh ấy đã sống nửa đời người ở nước ngoài."],["その映画を見て、歌手の半生を知りました。","Xem bộ phim đó, tôi đã biết về nửa đời người của ca sĩ."]]},{"word":"著書","reading":"ちょしょ","meaning":"sách do chính mình viết (tác phẩm của tác giả)","hanViet":"TRỨ THƯ","lesson":20,"ex":[["その著書は、日本の音楽について書かれています。","Cuốn sách đó viết về âm nhạc Nhật Bản."],["先生の著書を読みました。","Tôi đã đọc sách của thầy."],["この著書は、初心者にもわかりやすいです。","Cuốn sách này dễ hiểu ngay cả với người mới bắt đầu."],["著書の中で、音楽の歴史が説明されています。","Trong cuốn sách, lịch sử âm nhạc được giải thích."],["その著書は、国の内外で読まれています。","Cuốn sách đó được đọc trong và ngoài nước."]]},{"word":"音色","reading":"ねいろ","meaning":"âm sắc","hanViet":"ÂM SẮC","lesson":20,"ex":[["その楽器の音色は、とても美しいです。","Âm sắc của nhạc cụ đó rất đẹp."],["琴の音色を聞くと、心が静かになります。","Nghe âm sắc của đàn koto, lòng tôi trở nên yên tĩnh."],["彼のフルートの音色が好きです。","Tôi thích âm sắc của cây sáo flute của anh ấy."],["音色が美しい楽器が、たくさんあります。","Có rất nhiều nhạc cụ có âm sắc đẹp."],["奏者の音色は、人によって違います。","Âm sắc của người biểu diễn khác nhau tùy từng người."]]},{"word":"ノンフィクション","reading":"","meaning":"không hư cấu, hiện thực","hanViet":"","lesson":20,"ex":[["私はノンフィクションの本が好きです。","Tôi thích sách phi hư cấu."],["そのノンフィクションは、音楽家の生活について書いています。","Cuốn sách phi hư cấu đó viết về cuộc sống của nhạc sĩ."],["ノンフィクションを読むと、本当の話がわかります。","Đọc sách phi hư cấu, bạn sẽ hiểu câu chuyện thật."],["このノンフィクションは、とてもおもしろいです。","Cuốn sách phi hư cấu này rất thú vị."],["彼はノンフィクションを書く作家です。","Anh ấy là nhà văn viết sách phi hư cấu."]]},{"word":"～賞","reading":"～しょう","meaning":"giải thưởng ~","hanViet":"THƯỞNG","lesson":20,"ex":[["彼はノーベル賞をもらいました。","Anh ấy đã nhận giải Nobel."],["その映画は、大きな賞をもらいました。","Bộ phim đó đã nhận giải thưởng lớn."],["賞をもらうことは、とてもうれしいです。","Nhận giải thưởng là điều rất vui."],["彼女は大きな賞を取った作家です。","Cô ấy là nhà văn đã đoạt giải thưởng lớn."],["賞の発表は、来月です。","Lễ công bố giải thưởng sẽ diễn ra vào tháng sau."]]},{"word":"アフロヘアー","reading":"","meaning":"kiểu tóc quăn xù","hanViet":"","lesson":20,"ex":[["彼のアフロヘアーが好きです。","Tôi thích kiểu tóc xù của anh ấy."],["アフロヘアーの歌手が、テレビに出ました。","Ca sĩ có kiểu tóc xù đã xuất hiện trên TV."],["彼はアフロヘアーにしました。","Anh ấy đã để kiểu tóc xù."],["アフロヘアーは、昔から人気があります。","Kiểu tóc xù đã được ưa chuộng từ xưa."],["その音楽家のアフロヘアーが、有名です。","Kiểu tóc xù của nhạc sĩ đó rất nổi tiếng."]]},{"word":"もと（宗家の～）","reading":"もと（そうけの～）","meaning":"dưới sự chỉ dạy (của người đứng đầu phái nghệ thuật)","hanViet":"TÔN GIA","lesson":20,"ex":[["彼は先生のもとで、音楽を習いました。","Anh ấy đã học nhạc dưới sự chỉ dạy của thầy."],["先生のもとで、修行を続けています。","Tôi đang tiếp tục học nghề dưới sự chỉ dạy của thầy."],["先生のもとで、長い間勉強しました。","Tôi đã học dưới sự chỉ dạy của thầy trong thời gian dài."],["有名な先生のもとで、琴を習っています。","Tôi đang học đàn koto dưới sự chỉ dạy của thầy giáo nổi tiếng."],["彼のもとで、多くの学生が音楽を勉強しています。","Dưới sự chỉ dạy của anh ấy, nhiều học sinh đang học nhạc."]]},{"word":"初心者","reading":"しょしんしゃ","meaning":"người mới bắt đầu","hanViet":"SƠ TÂM GIẢ","lesson":20,"ex":[["この本は、初心者にわかりやすいです。","Cuốn sách này dễ hiểu với người mới bắt đầu."],["初心者でも、楽しく音楽を聞くことができます。","Ngay cả người mới bắt đầu cũng có thể nghe nhạc một cách vui vẻ."],["初心者のための教室があります。","Có lớp học dành cho người mới bắt đầu."],["私は琴の初心者です。","Tôi là người mới bắt đầu học đàn koto."],["初心者は、まず易しい曲から練習します。","Người mới bắt đầu luyện tập từ những bản nhạc dễ trước."]]},{"word":"厄介（な）","reading":"やっかい（な）","meaning":"phức tạp, phiền phức","hanViet":"ÁCH GIỚI","lesson":20,"ex":[["この問題は、厄介です。","Vấn đề này rất phức tạp."],["厄介な仕事が、たくさんあります。","Có rất nhiều công việc phiền phức."],["彼は厄介な問題を解決しました。","Anh ấy đã giải quyết vấn đề phức tạp."],["厄介な問題は、時間がかかります。","Vấn đề phức tạp tốn nhiều thời gian."],["厄介なことがあっても、続けます。","Dù có việc phiền phức, tôi vẫn tiếp tục."]]},{"word":"トロンボーン","reading":"","meaning":"kèn trombone","hanViet":"","lesson":20,"ex":[["トロンボーンは、管楽器の一つです。","Kèn trombone là một trong những nhạc cụ hơi."],["彼はトロンボーンを上手に吹きます。","Anh ấy thổi kèn trombone rất giỏi."],["トロンボーンの音は、大きくて明るいです。","Âm thanh của kèn trombone to và sáng."],["学校の音楽会で、トロンボーンを演奏しました。","Tại buổi hòa nhạc ở trường, tôi đã chơi kèn trombone."],["トロンボーンを習うために、毎週教室に行きます。","Để học kèn trombone, tôi đến lớp học mỗi tuần."]]},{"word":"フルート","reading":"","meaning":"ống sáo","hanViet":"","lesson":20,"ex":[["フルートは、管楽器の一つです。","Sáo flute là một trong những nhạc cụ hơi."],["彼女はフルートが上手です。","Cô ấy chơi sáo flute rất giỏi."],["フルートの音は、静かで美しいです。","Âm thanh của sáo flute yên tĩnh và đẹp."],["フルートを吹くのは、難しいです。","Thổi sáo flute rất khó."],["フルートのコンサートに行きました。","Tôi đã đi nghe hòa nhạc sáo flute."]]},{"word":"吹く","reading":"ふく","meaning":"thổi","hanViet":"XÚY","lesson":20,"ex":[["彼はフルートを吹きます。","Anh ấy thổi sáo flute."],["風が強く吹いています。","Gió đang thổi mạnh."],["彼女はトロンボーンを吹いています。","Cô ấy đang thổi kèn trombone."],["吹く練習を毎日しています。","Tôi luyện tập thổi mỗi ngày."],["管楽器を吹くのは、楽しいです。","Thổi nhạc cụ hơi rất vui."]]},{"word":"あっさり","reading":"","meaning":"một cách dễ dàng","hanViet":"","lesson":20,"ex":[["彼は問題にあっさり答えました。","Anh ấy đã trả lời câu hỏi một cách dễ dàng."],["あっさりと話が終わりました。","Câu chuyện kết thúc một cách dễ dàng."],["彼はあっさりと仕事を終えました。","Anh ấy đã hoàn thành công việc một cách dễ dàng."],["あっさり負けて、悲しくなりました。","Thua một cách dễ dàng, tôi cảm thấy buồn."],["その問題は、あっさり解決しました。","Vấn đề đó đã được giải quyết một cách dễ dàng."]]},{"word":"出す（音を）","reading":"だす（おとを）","meaning":"tạo ra âm thanh","hanViet":"XUẤT ÂM","lesson":20,"ex":[["彼はきれいな音を出します。","Anh ấy tạo ra âm thanh đẹp."],["フルートで大きな音を出しました。","Tôi đã tạo ra âm thanh lớn bằng sáo flute."],["音を出すときは、息をたくさん使います。","Khi tạo ra âm thanh, bạn dùng rất nhiều hơi."],["音を出す練習をしています。","Tôi đang luyện tập tạo ra âm thanh."],["初心者でも、音を出すことができます。","Ngay cả người mới bắt đầu cũng có thể tạo ra âm thanh."]]},{"word":"～そのもの","reading":"","meaning":"chính ~","hanViet":"","lesson":20,"ex":[["この音楽は、日本そのものです。","Âm nhạc này chính là Nhật Bản."],["彼の演奏は、音楽そのものです。","Màn trình diễn của anh ấy chính là âm nhạc."],["その映画は、歴史そのものです。","Bộ phim đó chính là lịch sử."],["この本は、日本の文化そのものです。","Cuốn sách này chính là văn hóa Nhật Bản."],["その景色は、自然そのものです。","Phong cảnh đó chính là thiên nhiên."]]},{"word":"在り方","reading":"ありかた","meaning":"trạng thái vốn có, dạng thức vốn có","hanViet":"TẠI PHƯƠNG","lesson":20,"ex":[["音楽の在り方について、考えています。","Tôi đang suy nghĩ về dạng thức vốn có của âm nhạc."],["日本の文化の在り方を、勉強しています。","Tôi đang học về trạng thái vốn có của văn hóa Nhật Bản."],["仕事の在り方が、変わりました。","Dạng thức của công việc đã thay đổi."],["学校の在り方は、昔と変わりました。","Dạng thức của trường học đã thay đổi so với xưa."],["その在り方は、昔から変わりません。","Dạng thức đó không thay đổi từ xưa đến nay."]]},{"word":"進級（する）","reading":"しんきゅう（する）","meaning":"lên lớp, lên cấp","hanViet":"TIẾN CẤP","lesson":20,"ex":[["彼はよく勉強して、進級しました。","Anh ấy học chăm chỉ và đã lên lớp."],["進級するために、毎日勉強します。","Để lên lớp, tôi học mỗi ngày."],["子どもが進級して、うれしいです。","Con tôi lên lớp, tôi rất vui."],["進級の試験は、来月です。","Kỳ thi lên lớp sẽ diễn ra vào tháng sau."],["彼は進級して、新しいクラスになりました。","Anh ấy lên lớp và vào lớp mới."]]},{"word":"重視（する）","reading":"じゅうし（する）","meaning":"coi trọng, chú trọng","hanViet":"TRỌNG THỊ","lesson":20,"ex":[["私は健康を重視しています。","Tôi coi trọng sức khỏe."],["学校は、音楽の教育を重視しています。","Trường học chú trọng giáo dục âm nhạc."],["彼は家族を重視します。","Anh ấy coi trọng gia đình."],["会社は、社員の意見を重視します。","Công ty coi trọng ý kiến của nhân viên."],["伝統を重視することが、大切です。","Coi trọng truyền thống là điều quan trọng."]]},{"word":"疑問","reading":"ぎもん","meaning":"sự hoài nghi, sự nghi vấn","hanViet":"NGHI VẤN","lesson":20,"ex":[["その話には、疑問があります。","Câu chuyện đó có điều đáng nghi ngờ."],["疑問があれば、先生に聞きます。","Nếu có thắc mắc, tôi hỏi thầy."],["彼のことばに、疑問を持ちました。","Tôi nghi ngờ lời nói của anh ấy."],["疑問を解決するために、本を読みます。","Để giải quyết thắc mắc, tôi đọc sách."],["その記事を読んで、疑問が生まれました。","Đọc bài viết đó, tôi nảy sinh thắc mắc."]]},{"word":"持つ（疑問を～）","reading":"もつ（ぎもんを～）","meaning":"mang, có (hoài nghi)","hanViet":"TRÌ NGHI VẤN","lesson":20,"ex":[["私はその話に疑問を持っています。","Tôi nghi ngờ câu chuyện đó."],["彼は先生の説明に疑問を持ちました。","Anh ấy nghi ngờ lời giải thích của thầy."],["疑問を持つことは、大切です。","Có hoài nghi là điều quan trọng."],["その本を読んで、疑問を持ちました。","Đọc cuốn sách đó, tôi đã nảy sinh nghi ngờ."],["先生の話に疑問を持つ学生がいます。","Có học sinh nghi ngờ lời thầy nói."]]},{"word":"徹底的（な）","reading":"てっていてき（な）","meaning":"một cách triệt để","hanViet":"TRIỆT ĐỂ ĐÍCH","lesson":20,"ex":[["彼は徹底的に練習しました。","Anh ấy đã luyện tập một cách triệt để."],["徹底的な準備が必要です。","Cần chuẩn bị một cách triệt để."],["問題を徹底的に調べました。","Tôi đã tìm hiểu vấn đề một cách triệt để."],["徹底的に掃除をしました。","Tôi đã dọn dẹp một cách triệt để."],["彼は徹底的な人です。","Anh ấy là người làm việc triệt để."]]},{"word":"愛好者","reading":"あいこうしゃ","meaning":"người hâm mộ, người yêu thích","hanViet":"ÁI HẢO GIẢ","lesson":20,"ex":[["音楽の愛好者が、たくさん集まりました。","Rất nhiều người yêu nhạc đã tụ họp."],["彼は邦楽の愛好者です。","Anh ấy là người yêu nhạc truyền thống Nhật."],["愛好者の数が増えています。","Số lượng người hâm mộ đang tăng lên."],["コンサートには、多くの愛好者が来ました。","Rất nhiều người hâm mộ đã đến buổi hòa nhạc."],["愛好者のために、音楽会が開かれました。","Buổi hòa nhạc đã được tổ chức cho những người hâm mộ."]]},{"word":"初演（する）","reading":"しょえん（する）","meaning":"biểu diễn lần đầu","hanViet":"SƠ DIỄN","lesson":20,"ex":[["その曲は、東京で初演されました。","Bản nhạc đó được biểu diễn lần đầu ở Tokyo."],["新しい曲の初演を聞きました。","Tôi đã nghe buổi biểu diễn đầu tiên của bản nhạc mới."],["彼は初演のとき、緊張しました。","Anh ấy đã hồi hộp khi biểu diễn lần đầu."],["初演は、来月です。","Buổi biểu diễn đầu tiên sẽ diễn ra vào tháng sau."],["その音楽家の初演は、とても成功しました。","Buổi biểu diễn đầu tiên của nhạc sĩ đó rất thành công."]]},{"word":"～人口","reading":"～じんこう","meaning":"dân số","hanViet":"NHÂN KHẨU","lesson":20,"ex":[["東京の人口は、とても多いです。","Dân số Tokyo rất đông."],["日本の人口が、減っています。","Dân số Nhật Bản đang giảm."],["町の人口は、だんだん増えています。","Dân số của thị trấn đang dần tăng lên."],["世界の人口は、多いです。","Dân số thế giới rất đông."],["人口が多い町に住んでいます。","Tôi đang sống ở thị trấn đông dân."]]},{"word":"急速（な）","reading":"きゅうそく（な）","meaning":"nhanh chóng","hanViet":"CẤP TỐC","lesson":20,"ex":[["急速に人口が増えています。","Dân số đang tăng nhanh chóng."],["技術が急速に進んでいます。","Công nghệ đang tiến bộ nhanh chóng."],["町が急速に変わって、驚きました。","Thị trấn thay đổi nhanh chóng, tôi rất ngạc nhiên."],["町は急速に大きくなりました。","Thị trấn đã lớn lên nhanh chóng."],["音楽が急速に人気になりました。","Âm nhạc đã trở nên phổ biến nhanh chóng."]]},{"word":"増加（する）","reading":"ぞうか（する）","meaning":"gia tăng","hanViet":"TĂNG GIA","lesson":20,"ex":[["人口が増加しています。","Dân số đang gia tăng."],["音楽の愛好者が増加しています。","Số người yêu nhạc đang gia tăng."],["コンサートの数が増加しました。","Số buổi hòa nhạc đã tăng lên."],["増加の理由は、音楽の人気です。","Lý do gia tăng là sự phổ biến của âm nhạc."],["学生の数が増加しています。","Số học sinh đang gia tăng."]]},{"word":"いやし","reading":"","meaning":"chữa lành, xoa dịu","hanViet":"","lesson":20,"ex":[["音楽はいやしになります。","Âm nhạc mang lại sự chữa lành."],["彼の歌はいやしです。","Bài hát của anh ấy là sự xoa dịu."],["自然の音はいやしになります。","Âm thanh của thiên nhiên mang lại sự chữa lành."],["音楽のいやしが好きです。","Tôi thích sự xoa dịu của âm nhạc."],["琴の音はいやしになります。","Tiếng đàn koto mang lại sự xoa dịu."]]},{"word":"古臭い","reading":"ふるくさい","meaning":"cũ kỹ","hanViet":"CỔ XÚ","lesson":20,"ex":[["その服は古臭いです。","Bộ quần áo đó cũ kỹ."],["古臭い家に住んでいます。","Tôi đang sống trong ngôi nhà cũ kỹ."],["その建物は古臭いです。","Tòa nhà đó cũ kỹ."],["古臭い音楽は、若い人に人気がありません。","Nhạc cũ kỹ không được giới trẻ yêu thích."],["古臭い本でも、おもしろいです。","Dù là sách cũ kỹ nhưng vẫn thú vị."]]},{"word":"斬新（な）","reading":"ざんしん（な）","meaning":"mới mẻ, mới lạ","hanViet":"TRẢM TÂN","lesson":20,"ex":[["斬新な音楽が、人気です。","Âm nhạc mới lạ đang được ưa chuộng."],["彼の方法は斬新です。","Phương pháp của anh ấy rất mới mẻ."],["斬新な方法で、問題を解決しました。","Tôi đã giải quyết vấn đề bằng phương pháp mới mẻ."],["斬新なデザインの服を買いました。","Tôi đã mua quần áo có thiết kế mới lạ."],["斬新なデザインが、必要です。","Cần có thiết kế mới lạ."]]},{"word":"先入観","reading":"せんにゅうかん","meaning":"thành kiến, định kiến","hanViet":"TIÊN NHẬP QUAN","lesson":20,"ex":[["先入観を持たないで、音楽を聞きます。","Tôi nghe nhạc mà không mang định kiến."],["先入観を捨てることが、大切です。","Bỏ đi định kiến là điều quan trọng."],["彼の先入観が変わりました。","Định kiến của anh ấy đã thay đổi."],["先入観で音楽を聞かないでください。","Xin đừng nghe nhạc bằng định kiến."],["先入観がなくて、よかったです。","Không có định kiến thì thật tốt."]]},{"word":"接する","reading":"せっする","meaning":"tiếp cận, tiếp xúc","hanViet":"TIẾP","lesson":20,"ex":[["音楽に接する機会が増えました。","Cơ hội tiếp xúc với âm nhạc đã tăng lên."],["日本の文化に接しました。","Tôi đã tiếp xúc với văn hóa Nhật Bản."],["子どもは本に接することが大切です。","Trẻ em tiếp xúc với sách là điều quan trọng."],["彼は多くの人に接しています。","Anh ấy đang tiếp xúc với nhiều người."],["外国の音楽に接するのが好きです。","Tôi thích tiếp xúc với âm nhạc nước ngoài."]]},{"word":"主張（する）","reading":"しゅちょう（する）","meaning":"khẳng định, chủ trương","hanViet":"CHỦ TRƯƠNG","lesson":20,"ex":[["彼は音楽が大切だと主張しています。","Anh ấy khẳng định rằng âm nhạc quan trọng."],["その本は、伝統が大切だと主張しています。","Cuốn sách đó khẳng định rằng truyền thống quan trọng."],["彼は自分の意見を主張しました。","Anh ấy đã khẳng định ý kiến của mình."],["主張することは、大切です。","Khẳng định quan điểm là điều quan trọng."],["先生は、練習が大切だと主張しています。","Thầy khẳng định rằng luyện tập quan trọng."]]},{"word":"財産","reading":"ざいさん","meaning":"tài sản","hanViet":"TÀI SẢN","lesson":20,"ex":[["その本は、私の大切な財産です。","Cuốn sách đó là tài sản quý giá của tôi."],["音楽は、日本の大切な財産です。","Âm nhạc là tài sản quý giá của Nhật Bản."],["財産を大切にします。","Tôi trân trọng tài sản."],["財産は、家族のものです。","Tài sản là của gia đình."],["文化は、国の財産です。","Văn hóa là tài sản của đất nước."]]},{"word":"国籍","reading":"こくせき","meaning":"quốc tịch","hanViet":"QUỐC TỊCH","lesson":20,"ex":[["彼の国籍は、日本です。","Quốc tịch của anh ấy là Nhật Bản."],["国籍が違いますが、音楽を楽しみます。","Quốc tịch khác nhau nhưng chúng tôi cùng yêu thích âm nhạc."],["国籍を聞かれました。","Tôi đã bị hỏi quốc tịch."],["彼の国籍は、わかりません。","Tôi không biết quốc tịch của anh ấy."],["国籍が違っても、音楽を楽しめます。","Dù quốc tịch khác nhau, vẫn có thể thưởng thức âm nhạc."]]},{"word":"目の色","reading":"めのいろ","meaning":"màu mắt","hanViet":"MỤC SẮC","lesson":20,"ex":[["彼女の目の色は、茶色です。","Màu mắt của cô ấy là màu nâu."],["目の色が違います。","Màu mắt khác nhau."],["彼の目の色は、黒いです。","Màu mắt của anh ấy là màu đen."],["目の色は、人によって違います。","Màu mắt khác nhau tùy từng người."],["その猫の目の色は、青いです。","Màu mắt của con mèo đó là màu xanh."]]},{"word":"すんなり","reading":"","meaning":"dễ dàng","hanViet":"","lesson":20,"ex":[["話はすんなり進みました。","Câu chuyện tiến triển một cách dễ dàng."],["彼はすんなり問題を解決しました。","Anh ấy đã giải quyết vấn đề một cách dễ dàng."],["仕事はすんなり終わりました。","Công việc đã kết thúc một cách dễ dàng."],["すんなりと答えがわかりました。","Tôi đã hiểu đáp án một cách dễ dàng."],["試験はすんなり終わりました。","Kỳ thi đã kết thúc một cách dễ dàng."]]},{"word":"宝","reading":"たから","meaning":"kho báu, của cải","hanViet":"BẢO","lesson":20,"ex":[["その本は、私の宝です。","Cuốn sách đó là kho báu của tôi."],["音楽は、国の宝です。","Âm nhạc là kho báu của đất nước."],["宝を大切にします。","Tôi trân trọng kho báu."],["日本の文化は、世界の宝です。","Văn hóa Nhật Bản là kho báu của thế giới."],["彼の宝は、古い楽器です。","Kho báu của anh ấy là nhạc cụ cổ."]]},{"word":"含める","reading":"ふくめる","meaning":"bao gồm","hanViet":"HÀM","lesson":20,"ex":[["この本には、写真も含まれています。","Cuốn sách này cũng bao gồm cả ảnh."],["値段にチケットも含まれています。","Giá đã bao gồm cả vé."],["音楽会には、邦楽も含まれています。","Buổi hòa nhạc cũng bao gồm cả nhạc truyền thống Nhật."],["その本には、多くの曲が含まれています。","Cuốn sách đó bao gồm nhiều bản nhạc."],["このクラスには、初心者も含まれています。","Lớp này cũng bao gồm cả người mới bắt đầu."]]},{"word":"伝統文化","reading":"でんとうぶんか","meaning":"văn hóa truyền thống","hanViet":"TRUYỀN THỐNG VĂN HÓA","lesson":20,"ex":[["日本の伝統文化を勉強しています。","Tôi đang học văn hóa truyền thống Nhật Bản."],["伝統文化を守ることが大切です。","Bảo vệ văn hóa truyền thống là điều quan trọng."],["伝統文化のコンサートに行きました。","Tôi đã đi xem hòa nhạc văn hóa truyền thống."],["伝統文化を世界の人に紹介します。","Tôi giới thiệu văn hóa truyền thống với mọi người trên thế giới."],["伝統文化を大切にします。","Tôi trân trọng văn hóa truyền thống."]]},{"word":"イラスト","reading":"","meaning":"hình minh họa","hanViet":"","lesson":20,"ex":[["この本のイラストが好きです。","Tôi thích hình minh họa của cuốn sách này."],["イラストを見るのが好きです。","Tôi thích xem hình minh họa."],["雑誌のイラストが、きれいです。","Hình minh họa trên tạp chí rất đẹp."],["イラストの多い本を買いました。","Tôi đã mua cuốn sách có nhiều hình minh họa."],["子どもはイラストが好きです。","Trẻ em thích hình minh họa."]]},{"word":"レイアウト","reading":"","meaning":"cách bố trí, cách sắp đặt","hanViet":"","lesson":20,"ex":[["この雑誌のレイアウトが好きです。","Tôi thích cách bố trí của tạp chí này."],["レイアウトを変えました。","Tôi đã thay đổi cách bố trí."],["本のレイアウトが、わかりやすいです。","Cách bố trí của cuốn sách dễ hiểu."],["レイアウトを考えるのは、楽しいです。","Nghĩ về cách bố trí rất thú vị."],["新しいレイアウトにしました。","Tôi đã đổi sang cách bố trí mới."]]},{"word":"工夫（する）","reading":"くふう（する）","meaning":"tìm tòi, công phu","hanViet":"CÔNG PHU","lesson":20,"ex":[["料理に工夫をしました。","Tôi đã tìm tòi trong nấu ăn."],["工夫をすることが大切です。","Tìm tòi là điều quan trọng."],["彼は工夫して、問題を解決しました。","Anh ấy đã tìm tòi và giải quyết vấn đề."],["レイアウトに工夫をしました。","Tôi đã tìm tòi trong cách bố trí."],["工夫して、音楽会を開きました。","Tôi đã tìm tòi và tổ chức buổi hòa nhạc."]]},{"word":"主催（する）","reading":"しゅうさい（する）","meaning":"chủ trì, đứng ra tổ chức","hanViet":"CHỦ THÔI","lesson":20,"ex":[["会社が音楽会を主催しました。","Công ty đã đứng ra tổ chức buổi hòa nhạc."],["学校がコンサートを主催しています。","Trường học đang tổ chức buổi hòa nhạc."],["町がコンサートを主催しました。","Thị trấn đã đứng ra tổ chức buổi hòa nhạc."],["主催する会社は、有名です。","Công ty đứng ra tổ chức rất nổi tiếng."],["彼が音楽会を主催しました。","Anh ấy đã đứng ra tổ chức buổi hòa nhạc."]]},{"word":"部門","reading":"ぶもん","meaning":"lĩnh vực, phần thi","hanViet":"BỘ MÔN","lesson":20,"ex":[["彼は音楽の部門で賞をもらいました。","Anh ấy đã nhận giải thưởng ở lĩnh vực âm nhạc."],["部門がたくさんあります。","Có rất nhiều lĩnh vực."],["会社の部門が変わりました。","Bộ phận của công ty đã thay đổi."],["その部門の仕事は、忙しいです。","Công việc của bộ phận đó rất bận rộn."],["部門の数が増えました。","Số lĩnh vực đã tăng lên."]]},{"word":"さい～（～優秀賞）","reading":"さい～（～ゆうしゅうしょう）","meaning":"cao nhất (giải thưởng)","hanViet":"ƯU TÚ THƯỞNG","lesson":20,"ex":[["彼は最優秀賞をもらいました。","Anh ấy đã nhận giải thưởng cao nhất."],["最優秀賞を取るために、練習しました。","Để đoạt giải thưởng cao nhất, tôi đã luyện tập."],["彼女は最優秀賞をもらった歌手です。","Cô ấy là ca sĩ đã nhận giải thưởng cao nhất."],["最優秀賞の発表は、来月です。","Lễ công bố giải thưởng cao nhất sẽ diễn ra vào tháng sau."],["最優秀賞をもらうことは、とてもうれしいです。","Nhận giải thưởng cao nhất là điều rất vui."]]},{"word":"広報（～誌）","reading":"こうほう（～し）","meaning":"bản tin (tạp chí)","hanViet":"QUẢNG BÁO CHÍ","lesson":20,"ex":[["町の広報誌を読みました。","Tôi đã đọc bản tin của thị trấn."],["広報誌に、音楽会の記事があります。","Bản tin có bài viết về buổi hòa nhạc."],["学校の広報誌が、毎月出ます。","Bản tin của trường ra mỗi tháng."],["広報誌のイラストがきれいです。","Hình minh họa của bản tin rất đẹp."],["広報誌を読んで、町のことを知りました。","Đọc bản tin, tôi đã biết về thị trấn."]]},{"word":"掲載（する）","reading":"けいさい（する）","meaning":"đăng tải","hanViet":"YẾT TẢI","lesson":20,"ex":[["新聞に記事が掲載されました。","Bài viết đã được đăng trên báo."],["雑誌に写真が掲載されました。","Ảnh đã được đăng trên tạp chí."],["彼の名前が新聞に掲載されました。","Tên của anh ấy đã được đăng trên báo."],["記事を掲載するために、写真を送りました。","Để đăng bài viết, tôi đã gửi ảnh."],["広報誌に音楽会のことが掲載されました。","Bản tin đã đăng tải về buổi hòa nhạc."]]},{"word":"初対面","reading":"しょたいめん","meaning":"lần đầu tiên gặp","hanViet":"SƠ ĐỐI DIỆN","lesson":20,"ex":[["初対面の人に、あいさつをしました。","Tôi đã chào hỏi người gặp lần đầu."],["初対面のとき、緊張しました。","Khi gặp lần đầu, tôi đã hồi hộp."],["彼とは初対面でした。","Tôi gặp anh ấy lần đầu tiên."],["初対面の人と、音楽の話をしました。","Tôi đã nói chuyện về âm nhạc với người gặp lần đầu."],["初対面でも、すぐに友達になりました。","Dù mới gặp lần đầu, chúng tôi đã nhanh chóng trở thành bạn bè."]]},{"word":"終える","reading":"おえる","meaning":"hoàn thành","hanViet":"CHUNG","lesson":20,"ex":[["仕事を終えました。","Tôi đã hoàn thành công việc."],["試験を終えて、うれしかったです。","Hoàn thành kỳ thi, tôi rất vui."],["勉強を終えました。","Tôi đã hoàn thành việc học."],["彼は長い修行を終えました。","Anh ấy đã hoàn thành thời gian học nghề dài."],["音楽会を終えて、家に帰りました。","Kết thúc buổi hòa nhạc, tôi về nhà."]]},{"word":"十両","reading":"じゅうりょう","meaning":"Juryo (cấp bậc của võ sĩ Sumo)","hanViet":"THẬP LƯỠNG","lesson":20,"ex":[["彼は十両になりました。","Anh ấy đã trở thành võ sĩ Juryo."],["十両の力士は、強いです。","Võ sĩ Juryo rất khỏe."],["十両になるために、毎日練習します。","Để trở thành võ sĩ Juryo, tôi luyện tập mỗi ngày."],["その力士は十両です。","Võ sĩ sumo đó ở hạng Juryo."],["十両の力士が、相撲を取りました。","Võ sĩ Juryo đã thi đấu sumo."]]},{"word":"相撲部屋","reading":"すもうべや","meaning":"lò Sumo","hanViet":"TƯƠNG, TƯỚNG PHÁC BỘ ỐC","lesson":20,"ex":[["彼は相撲部屋に入りました。","Anh ấy đã vào lò sumo."],["相撲部屋で、毎日練習します。","Tại lò sumo, tôi luyện tập mỗi ngày."],["相撲部屋の生活は、厳しいです。","Cuộc sống ở lò sumo rất khắc nghiệt."],["その相撲部屋は、東京にあります。","Lò sumo đó ở Tokyo."],["相撲部屋に入るために、日本に来ました。","Để vào lò sumo, tôi đã đến Nhật Bản."]]},{"word":"抱負","reading":"ほうふ","meaning":"hoài bão, ước mơ","hanViet":"BÃO PHỤ","lesson":20,"ex":[["彼の抱負は、十両になることです。","Hoài bão của anh ấy là trở thành võ sĩ Juryo."],["抱負を話しました。","Tôi đã nói về hoài bão của mình."],["来年の抱負を書きました。","Tôi đã viết hoài bão cho năm tới."],["抱負を持つことが大切です。","Có hoài bão là điều quan trọng."],["彼の抱負は、音楽家になることです。","Hoài bão của anh ấy là trở thành nhạc sĩ."]]},{"word":"機関誌","reading":"きかんし","meaning":"báo của một tổ chức, cơ quan","hanViet":"CƠ QUAN CHÍ","lesson":20,"ex":[["学校の機関誌を読みました。","Tôi đã đọc báo của trường."],["機関誌に、音楽会の記事があります。","Báo của cơ quan có bài viết về buổi hòa nhạc."],["会社の機関誌が、毎月出ます。","Báo của công ty ra mỗi tháng."],["機関誌の写真がきれいです。","Ảnh trên báo của cơ quan rất đẹp."],["機関誌を読んで、会社のことを知りました。","Đọc báo của cơ quan, tôi đã biết về công ty."]]},{"word":"光栄","reading":"こうえい","meaning":"vinh dự","hanViet":"QUANG VINH","lesson":20,"ex":[["賞をもらうことは、光栄です。","Nhận giải thưởng là điều vinh dự."],["光栄なことです。","Đó là điều vinh dự."],["彼と会うことができて、光栄です。","Được gặp anh ấy là điều vinh dự."],["光栄な賞をもらいました。","Tôi đã nhận giải thưởng vinh dự."],["その仕事は、とても光栄です。","Công việc đó rất vinh dự."]]},{"word":"実家","reading":"じっか","meaning":"nhà bố mẹ (nơi mình sinh ra)","hanViet":"THỰC GIA","lesson":20,"ex":[["実家は京都にあります。","Nhà bố mẹ tôi ở Kyoto."],["実家に帰りました。","Tôi đã về nhà bố mẹ."],["実家の父と母は、元気です。","Bố mẹ tôi ở quê vẫn khỏe."],["実家で、家族とご飯を食べました。","Ở nhà bố mẹ, tôi đã ăn cơm cùng gia đình."],["実家から、果物が送られてきました。","Trái cây đã được gửi từ nhà bố mẹ tôi."]]},{"word":"ジュニア","reading":"","meaning":"thiếu niên","hanViet":"","lesson":20,"ex":[["ジュニアの選手が、試合に出ました。","Vận động viên thiếu niên đã ra sân thi đấu."],["ジュニアの音楽会があります。","Có buổi hòa nhạc thiếu niên."],["ジュニアのクラスで、琴を習います。","Tôi học đàn koto ở lớp thiếu niên."],["ジュニアの力士が、相撲を取りました。","Võ sĩ sumo thiếu niên đã thi đấu sumo."],["ジュニアの選手は、元気です。","Vận động viên thiếu niên rất khỏe mạnh."]]},{"word":"世界選手権大会","reading":"せかいせんしゅけんたいかい","meaning":"giải thi đấu thế giới","hanViet":"THẾ GIỚI TUYỂN THỦ QUYỀN ĐẠI HỘI","lesson":20,"ex":[["世界選手権大会に、出ました。","Tôi đã tham gia giải thi đấu thế giới."],["世界選手権大会は、東京です。","Giải thi đấu thế giới diễn ra ở Tokyo."],["世界選手権大会の選手は、強いです。","Vận động viên của giải thi đấu thế giới rất khỏe."],["世界選手権大会で、優勝しました。","Tôi đã vô địch giải thi đấu thế giới."],["世界選手権大会を見るのが好きです。","Tôi thích xem giải thi đấu thế giới."]]},{"word":"入門（する）","reading":"にゅうもん（する）","meaning":"nhập môn, bắt đầu tham gia luyện tập","hanViet":"NHẬP MÔN","lesson":20,"ex":[["彼は相撲部屋に入門しました。","Anh ấy đã nhập môn lò sumo."],["入門してから、毎日練習しています。","Từ khi nhập môn, tôi luyện tập mỗi ngày."],["琴に入門しました。","Tôi đã bắt đầu học đàn koto."],["入門のときは、初心者でした。","Khi nhập môn, tôi là người mới bắt đầu."],["彼は若いときに入門しました。","Anh ấy đã nhập môn khi còn trẻ."]]},{"word":"初土俵","reading":"はつどひょう","meaning":"lần đầu lên võ đài","hanViet":"SƠ THỔ BIẾU","lesson":20,"ex":[["彼は初土俵を踏みました。","Anh ấy đã lần đầu lên võ đài."],["初土俵の日は、緊張しました。","Vào ngày lần đầu lên võ đài, tôi đã hồi hộp."],["初土俵のとき、彼は若かったです。","Khi lần đầu lên võ đài, anh ấy còn trẻ."],["初土俵を忘れません。","Tôi không quên lần đầu lên võ đài."],["初土俵の写真があります。","Có ảnh lần đầu lên võ đài."]]},{"word":"わずか（な）","reading":"","meaning":"ít ỏi","hanViet":"","lesson":20,"ex":[["わずかな時間で、仕事を終えました。","Tôi đã hoàn thành công việc trong thời gian ít ỏi."],["わずかなお金で、本を買いました。","Tôi đã mua sách với số tiền ít ỏi."],["わずかな人しか、コンサートに来ませんでした。","Chỉ có ít người đến buổi hòa nhạc."],["わずかですが、音楽を聞く時間があります。","Dù ít ỏi nhưng tôi có thời gian nghe nhạc."],["わずかな声で、話しました。","Tôi đã nói bằng giọng nhỏ."]]},{"word":"関取","reading":"せきとり","meaning":"danh hiệu của võ sĩ Sumo từ cấp juryo trở lên","hanViet":"QUAN THỦ","lesson":20,"ex":[["彼は関取になりました。","Anh ấy đã trở thành võ sĩ Sekitori."],["関取の力士は、強いです。","Võ sĩ Sekitori rất khỏe."],["関取になるために、毎日練習します。","Để trở thành võ sĩ Sekitori, tôi luyện tập mỗi ngày."],["その力士は関取です。","Võ sĩ sumo đó là Sekitori."],["関取の力士が、相撲を取りました。","Võ sĩ Sekitori đã thi đấu sumo."]]},{"word":"順風満帆","reading":"じゅんぷうまんぱん","meaning":"thuận buồm xuôi gió, xuôi chèo mát mái","hanViet":"THUẬN PHONG MÃN PHÀM","lesson":20,"ex":[["彼の人生は、順風満帆です。","Cuộc đời của anh ấy thuận buồm xuôi gió."],["順風満帆な毎日です。","Mỗi ngày đều thuận buồm xuôi gió."],["仕事は順風満帆です。","Công việc thuận buồm xuôi gió."],["彼の音楽の道は、順風満帆でした。","Con đường âm nhạc của anh ấy đã thuận buồm xuôi gió."],["順風満帆な生活です。","Cuộc sống thuận buồm xuôi gió."]]},{"word":"上がる（十両に～）","reading":"あがる（じゅうりょうに～）","meaning":"lên cấp (juryo)","hanViet":"THƯỢNG THẬP LƯỠNG","lesson":20,"ex":[["あの力士は来年、十両に上がります。","Võ sĩ sumo đó sẽ lên hạng juryo vào năm sau."],["彼は毎日練習して、十両に上がりました。","Anh ấy luyện tập mỗi ngày và đã lên hạng juryo."],["十両に上がるために、毎日朝から練習します。","Để lên hạng juryo, tôi luyện tập từ buổi sáng mỗi ngày."],["十両に上がったら、故郷の家族がうれしくなると思います。","Nếu lên hạng juryo, tôi nghĩ gia đình ở quê sẽ vui mừng."],["彼は十両に上がるのが夢です。","Được lên hạng juryo là ước mơ của anh ấy."]]},{"word":"命日","reading":"めいにち","meaning":"ngày giỗ","hanViet":"MỆNH NHẬT","lesson":20,"ex":[["祖父の命日を忘れません。","Tôi không quên ngày giỗ của ông tôi."],["毎年、父の命日には家族で寺に行きます。","Mỗi năm, vào ngày giỗ của bố, cả gia đình tôi đi chùa."],["祖母の命日を忘れないように、手帳に書きます。","Tôi ghi vào sổ tay để không quên ngày giỗ của bà."],["命日には、亡くなった人を思い出します。","Vào ngày giỗ, tôi nhớ về người đã mất."],["彼の命日は来月の十日です。","Ngày giỗ của anh ấy là mùng 10 tháng sau."]]},{"word":"昇進（する）","reading":"しょうしん（する）","meaning":"thăng cấp","hanViet":"THĂNG TIẾN","lesson":20,"ex":[["田中さんは今年、部長に昇進しました。","Anh Tanaka đã được thăng chức trưởng phòng trong năm nay."],["彼は長い時間働いて、やっと昇進しました。","Anh ấy làm việc trong thời gian dài rồi cuối cùng cũng được thăng chức."],["昇進するためには、仕事の結果が大切です。","Để được thăng chức, kết quả công việc rất quan trọng."],["母は昇進の知らせを聞いて、とてもうれしくなりました。","Mẹ tôi nghe tin thăng chức thì rất vui mừng."],["昇進したら、給料が上がります。","Nếu được thăng chức, lương sẽ tăng."]]},{"word":"知らせ","reading":"しらせ","meaning":"thông báo","hanViet":"TRI","lesson":20,"ex":[["先生から大切な知らせがありました。","Có thông báo quan trọng từ thầy giáo."],["試験の日が変わったという知らせが来ました。","Đã có thông báo rằng ngày thi đã thay đổi."],["知らせを聞いて、みんなが驚きました。","Nghe thông báo, mọi người đều ngạc nhiên."],["母に合格の知らせを電話で伝えました。","Tôi đã gọi điện báo cho mẹ tin tôi đỗ kỳ thi."],["新しい知らせがあれば、すぐ連絡します。","Nếu có thông báo mới, tôi sẽ liên lạc ngay."]]},{"word":"さぞ","reading":"","meaning":"hẳn là","hanViet":"","lesson":20,"ex":[["さぞ疲れたでしょう。","Chắc hẳn anh ấy đã mệt lắm."],["彼はさぞ喜んだでしょう。","Chắc hẳn anh ấy đã vui mừng lắm."],["さぞ大変だったでしょう。","Chắc hẳn đã vất vả lắm."],["母はさぞ心配したでしょう。","Chắc hẳn mẹ đã lo lắng lắm."],["さぞ寒かったでしょう。","Chắc hẳn đã lạnh lắm."]]},{"word":"離れる（故郷を～）","reading":"はなれる（こきょうを～）","meaning":"rời xa (quê hương)","hanViet":"LY CỐ HƯƠNG","lesson":20,"ex":[["彼は高校を卒業して、故郷を離れました。","Anh ấy tốt nghiệp cấp ba rồi rời quê hương."],["故郷を離れて、もう長い間になります。","Tôi rời quê hương đã lâu rồi."],["私は故郷を離れるのが寂しかったです。","Rời xa quê hương khiến tôi cảm thấy cô đơn."],["故郷を離れても、家族を忘れません。","Dù rời xa quê hương, tôi cũng không quên gia đình."],["彼女は仕事のために故郷を離れました。","Cô ấy rời quê hương vì công việc."]]},{"word":"特殊（な）","reading":"とくしゅ（な）","meaning":"đặc thù","hanViet":"ĐẶC THÙ","lesson":20,"ex":[["これは特殊な場合です。","Đây là trường hợp đặc thù."],["特殊な技術が必要です。","Cần có kỹ thuật đặc thù."],["彼は特殊な能力があります。","Anh ấy có năng lực đặc biệt."],["特殊な料理を食べました。","Tôi đã ăn món ăn đặc biệt."],["この病気には特殊な薬が必要です。","Bệnh này cần loại thuốc đặc biệt."]]},{"word":"ちゃんこ鍋","reading":"ちゃんこなべ","meaning":"lẩu chanko (lẩu thịt, cá và rau)","hanViet":"OA","lesson":20,"ex":[["力士は毎日ちゃんこ鍋を食べます。","Võ sĩ sumo ăn lẩu chanko mỗi ngày."],["東京で初めてちゃんこ鍋を食べました。","Tôi đã ăn lẩu chanko lần đầu ở Tokyo."],["ちゃんこ鍋には肉や野菜がたくさん入っています。","Lẩu chanko có nhiều thịt và rau."],["冬はちゃんこ鍋がおいしいです。","Mùa đông ăn lẩu chanko rất ngon."],["友達とちゃんこ鍋を作りました。","Tôi đã nấu lẩu chanko cùng bạn bè."]]},{"word":"わがまま（な）","reading":"","meaning":"ích kỷ, chỉ nghĩ cho bản thân","hanViet":"","lesson":20,"ex":[["弟はわがままです。","Em trai tôi là đứa trẻ ích kỷ."],["わがままを言わないでください。","Đừng nói những điều ích kỷ."],["彼はわがままな人だと思います。","Tôi nghĩ anh ấy là người ích kỷ."],["弟のわがままを聞いてあげました。","Tôi đã chiều theo sự nhõng nhẽo của em trai."],["わがままはよくありません。","Ích kỷ là không tốt."]]},{"word":"納豆","reading":"なっとう","meaning":"món natto (đậu nành lên men)","hanViet":"NẠP ĐẬU","lesson":20,"ex":[["私は毎朝納豆を食べます。","Tôi ăn natto mỗi buổi sáng."],["納豆は体にいいです。","Natto tốt cho cơ thể."],["彼は納豆が苦手です。","Anh ấy không ăn được natto."],["納豆はごはんによく合います。","Natto rất hợp với cơm."],["外国の友達は納豆を食べられません。","Bạn nước ngoài không ăn được natto."]]},{"word":"いける","reading":"","meaning":"ăn được","hanViet":"","lesson":20,"ex":[["彼は納豆がいけるそうです。","Nghe nói anh ấy ăn được natto."],["この料理は辛いですが、いけます。","Món này cay nhưng vẫn ăn được."],["初めて食べましたが、この味はいけます。","Lần đầu ăn thử nhưng vị này ăn được."],["母の料理はいつもいけます。","Món mẹ nấu lúc nào cũng ngon."],["この店のラーメンはいけるよ。","Mì ramen ở quán này ăn được đấy."]]},{"word":"四股名","reading":"しこな","meaning":"tên thi đấu của võ sĩ Sumo chuyên nghiệp","hanViet":"TỨ CỔ DANH","lesson":20,"ex":[["彼の四股名は力強い響きがあります。","Tên thi đấu của anh ấy có âm hưởng mạnh mẽ."],["力士は四股名を持っています。","Võ sĩ sumo có tên thi đấu riêng."],["四股名は師匠がつけます。","Tên thi đấu do sư phụ đặt."],["新しい四股名をもらいました。","Tôi đã nhận được tên thi đấu mới."],["四股名を聞いて、強い力士だと思いました。","Nghe tên thi đấu, tôi nghĩ đó là võ sĩ mạnh."]]},{"word":"力強い","reading":"ちからづよい","meaning":"mạnh mẽ, tràn đầy sức lực","hanViet":"LỰC CƯỜNG","lesson":20,"ex":[["彼は力強い声で話しました。","Anh ấy nói bằng giọng mạnh mẽ."],["力強い手でドアを開けました。","Anh ấy mở cửa bằng bàn tay mạnh mẽ."],["彼女の力強い声に元気をもらいました。","Tôi được tiếp thêm sức mạnh nhờ giọng nói mạnh mẽ của cô ấy."],["力強いチームが優勝しました。","Đội mạnh đã giành chức vô địch."],["力強い歌が聞こえました。","Tôi nghe thấy tiếng hát mạnh mẽ."]]},{"word":"響き","reading":"ひびき","meaning":"âm hưởng","hanViet":"HƯỞNG","lesson":20,"ex":[["この名前はいい響きがあります。","Cái tên này có âm hưởng hay."],["ピアノの響きがきれいです。","Âm thanh của piano rất đẹp."],["彼の声の響きが心に残りました。","Âm hưởng trong giọng nói của anh ấy còn đọng lại trong lòng tôi."],["この曲の響きが好きです。","Tôi thích âm hưởng của bản nhạc này."],["歌の響きが部屋に残りました。","Âm hưởng của bài hát còn đọng lại trong căn phòng."]]},{"word":"ニックネーム","reading":"","meaning":"nickname, tên thân mật","hanViet":"","lesson":20,"ex":[["友達は私をニックネームで呼びます。","Bạn bè gọi tôi bằng tên thân mật."],["彼のニックネームは短いです。","Tên thân mật của anh ấy rất ngắn."],["ニックネームで呼んでください。","Hãy gọi tôi bằng tên thân mật."],["クラスで新しいニックネームがつきました。","Tôi có tên thân mật mới ở lớp."],["彼女のニックネームはかわいいです。","Tên thân mật của cô ấy thật dễ thương."]]},{"word":"師匠","reading":"ししょう","meaning":"sư phụ","hanViet":"SƯ TƯỢNG","lesson":20,"ex":[["彼は有名な師匠に習います。","Anh ấy học với một sư phụ nổi tiếng."],["師匠の話を大切にします。","Tôi trân trọng lời dạy của sư phụ."],["師匠に会って、うれしかったです。","Được gặp sư phụ, tôi rất vui."],["師匠の家で毎日練習します。","Tôi luyện tập mỗi ngày ở nhà sư phụ."],["彼は師匠が大好きです。","Anh ấy rất yêu quý sư phụ."]]},{"word":"力士","reading":"りきし","meaning":"võ sĩ Sumo","hanViet":"LỰC SĨ","lesson":20,"ex":[["力士は体が大きいです。","Võ sĩ sumo có thân hình to lớn."],["あの力士は強いです。","Võ sĩ sumo đó rất mạnh."],["力士になるのが夢です。","Trở thành võ sĩ sumo là ước mơ của tôi."],["力士は朝から練習します。","Võ sĩ sumo luyện tập từ buổi sáng."],["たくさんの力士が東京に住んでいます。","Nhiều võ sĩ sumo sống ở Tokyo."]]},{"word":"生まれ変わる","reading":"うまれかわる","meaning":"được sinh ra một lần nữa","hanViet":"SINH BIẾN","lesson":20,"ex":[["生まれ変わったら、鳥になりたいです。","Nếu được sinh ra lần nữa, tôi muốn trở thành chim."],["病気が治って、生まれ変わった気持ちです。","Bệnh đã khỏi, tôi có cảm giác như được sinh ra lần nữa."],["生まれ変わっても、また日本語を勉強したいです。","Dù được sinh ra lần nữa, tôi vẫn muốn học tiếng Nhật."],["新しい仕事を始めて、生まれ変わりました。","Bắt đầu công việc mới, tôi như được tái sinh."],["生まれ変わると信じる人もいます。","Có người tin rằng sẽ được tái sinh."]]},{"word":"慣習","reading":"かんしゅう","meaning":"nếp sinh hoạt, lề lối","hanViet":"QUÁN TẬP","lesson":20,"ex":[["日本にはいろいろな慣習があります。","Nhật Bản có nhiều phong tục khác nhau."],["その国の慣習を知るのが大切です。","Biết phong tục của đất nước đó là điều quan trọng."],["慣習を守るのが大切です。","Giữ gìn phong tục là điều quan trọng."],["古い慣習が今も残っています。","Phong tục cũ vẫn còn đến bây giờ."],["村の慣習を大切にします。","Tôi trân trọng phong tục của làng."]]},{"word":"報いる","reading":"むくいる","meaning":"đền đáp","hanViet":"BÁO","lesson":20,"ex":[["両親の親切に報いたいです。","Tôi muốn đền đáp lòng tốt của cha mẹ."],["先生の親切に報いるために、頑張ります。","Tôi sẽ cố gắng để đền đáp lòng tốt của thầy giáo."],["応援してくれた人に報いたいです。","Tôi muốn đền đáp những người đã ủng hộ tôi."],["彼の親切に報いる方法を考えます。","Tôi nghĩ cách đền đáp lòng tốt của anh ấy."],["いい結果を出して、両親に報いました。","Tôi đã đạt kết quả tốt để đền đáp cha mẹ."]]},{"word":"応援（する）","reading":"おうえん（する）","meaning":"ủng hộ","hanViet":"ỨNG VIỆN","lesson":20,"ex":[["友達の試合を応援します。","Tôi cổ vũ bạn tôi trong trận đấu."],["母はいつも私を応援してくれます。","Mẹ luôn ủng hộ tôi."],["日本のチームを応援しましょう。","Chúng ta cùng cổ vũ đội Nhật Bản nhé."],["応援する人が多いです。","Có nhiều người ủng hộ."],["彼は友達を応援するために、東京へ行きました。","Anh ấy đã đến Tokyo để cổ vũ bạn mình."]]},{"word":"さらなる","reading":"","meaning":"hơn nữa","hanViet":"","lesson":20,"ex":[["さらなる勉強が必要です。","Cần học tập hơn nữa."],["さらなる練習ができます。","Có thể luyện tập hơn nữa."],["会社はさらなる利益を目指しています。","Công ty đang hướng tới lợi nhuận hơn nữa."],["さらなる練習が必要です。","Cần luyện tập hơn nữa."],["さらなる仕事を続けます。","Tôi sẽ tiếp tục làm việc nhiều hơn nữa."]]},{"word":"貴重（な）","reading":"きちょう（な）","meaning":"quý giá, quý trọng","hanViet":"QUÝ TRỌNG","lesson":20,"ex":[["これは貴重な経験です。","Đây là kinh nghiệm quý giá."],["貴重な時間をありがとうございます。","Cảm ơn bạn đã dành thời gian quý báu."],["貴重な意見を聞きました。","Tôi đã nghe ý kiến quý giá."],["貴重な本を大切にします。","Tôi trân trọng cuốn sách quý giá."],["貴重な資料が図書館にあります。","Tài liệu quý giá có ở thư viện."]]},{"word":"経営者","reading":"けいえいしゃ","meaning":"doanh nhân","hanViet":"KINH DOANH GIẢ","lesson":20,"ex":[["彼は有名な経営者です。","Anh ấy là doanh nhân nổi tiếng."],["経営者は会社で働きます。","Doanh nhân làm việc ở công ty."],["父は小さい会社の経営者です。","Bố tôi là chủ một công ty nhỏ."],["経営者の仕事は大変です。","Công việc của doanh nhân rất vất vả."],["彼は将来、経営者になりたいです。","Anh ấy muốn trở thành doanh nhân trong tương lai."]]},{"word":"手作り","reading":"てづくり","meaning":"làm bằng tay, làm thủ công","hanViet":"THỦ TÁC","lesson":20,"ex":[["母の手作り料理が好きです。","Tôi thích món ăn mẹ tự tay nấu."],["手作りのケーキを作りました。","Tôi đã làm bánh kem bằng tay."],["これは手作りのバッグです。","Đây là chiếc túi làm thủ công."],["手作りのプレゼントをもらいました。","Tôi đã nhận được món quà làm thủ công."],["手作りのお菓子を友達にあげました。","Tôi đã tặng bạn bè bánh kẹo tự làm."]]},{"word":"医師","reading":"いし","meaning":"bác sĩ","hanViet":"Y SƯ","lesson":20,"ex":[["医師は病院で働きます。","Bác sĩ làm việc ở bệnh viện."],["彼は医師になりたいです。","Anh ấy muốn trở thành bác sĩ."],["医師の話をよく聞きました。","Tôi đã lắng nghe kỹ lời bác sĩ."],["医師に相談しました。","Tôi đã hỏi ý kiến bác sĩ."],["医師は患者を助けます。","Bác sĩ giúp đỡ bệnh nhân."]]},{"word":"ドキュメンタリー","reading":"","meaning":"phim tài liệu","hanViet":"","lesson":20,"ex":[["ドキュメンタリーを見ました。","Tôi đã xem phim tài liệu."],["このドキュメンタリーはおもしろいです。","Bộ phim tài liệu này rất thú vị."],["ドキュメンタリーで日本の生活を学びました。","Tôi đã học về cuộc sống Nhật Bản qua phim tài liệu."],["先生がドキュメンタリーを紹介しました。","Thầy giáo đã giới thiệu phim tài liệu."],["ドキュメンタリーをテレビで見ました。","Tôi đã xem phim tài liệu trên TV."]]},{"word":"姿","reading":"すがた","meaning":"dáng vẻ","hanViet":"TƯ","lesson":20,"ex":[["彼女の姿がきれいです。","Dáng vẻ của cô ấy rất đẹp."],["母の働く姿を見ました。","Tôi đã thấy dáng vẻ làm việc của mẹ."],["山の姿が美しいです。","Dáng núi thật đẹp."],["学生の姿が見えました。","Tôi đã nhìn thấy dáng học sinh."],["彼の姿を写真に撮りました。","Tôi đã chụp ảnh dáng vẻ của anh ấy."]]},{"word":"頼る","reading":"たよる","meaning":"dựa vào","hanViet":"LẠI","lesson":20,"ex":[["困った時は、友達に頼ります。","Khi gặp khó khăn, tôi dựa vào bạn bè."],["私は母に頼っています。","Tôi đang dựa vào mẹ."],["彼は人に頼りません。","Anh ấy không dựa vào người khác."],["困ったら、私に頼ってください。","Nếu gặp khó khăn, hãy dựa vào tôi."],["妹は母に頼ります。","Em gái tôi dựa vào mẹ."]]},{"word":"寄り添う","reading":"よりそう","meaning":"gần gũi","hanViet":"KÝ THIÊM","lesson":20,"ex":[["母は妹に寄り添います。","Mẹ luôn ở gần bên em gái tôi."],["彼は悲しい友達に寄り添いました。","Anh ấy đã ở bên cạnh người bạn đang buồn."],["犬は私に寄り添って寝ます。","Con chó nằm ngủ sát bên tôi."],["医者は患者の気持ちに寄り添います。","Bác sĩ thấu hiểu cảm xúc của bệnh nhân."],["寄り添うのが大切だと思います。","Tôi nghĩ việc ở bên cạnh nhau là quan trọng."]]},{"word":"余暇","reading":"よか","meaning":"lúc rảnh rỗi","hanViet":"DƯ HẠ","lesson":20,"ex":[["余暇には本を読みます。","Lúc rảnh rỗi, tôi đọc sách."],["余暇を楽しみます。","Tôi tận hưởng thời gian rảnh."],["余暇が少ないです。","Tôi ít có thời gian rảnh."],["余暇にスポーツをします。","Lúc rảnh rỗi, tôi chơi thể thao."],["余暇の時間に音楽を聞きます。","Trong thời gian rảnh, tôi nghe nhạc."]]},{"word":"まとめる（内容を～）","reading":"まとめる（ないようを～）","meaning":"tóm tắt (nội dung)","hanViet":"NỘI DUNG","lesson":20,"ex":[["本の内容をまとめました。","Tôi đã tóm tắt nội dung cuốn sách."],["話の内容をまとめてください。","Hãy tóm tắt nội dung câu chuyện."],["内容をまとめるのは難しいです。","Tóm tắt nội dung thật khó."],["会議の内容をまとめました。","Tôi đã tóm tắt nội dung cuộc họp."],["内容を短くまとめました。","Tôi đã tóm tắt nội dung một cách ngắn gọn."]]},{"word":"共同","reading":"きょうどう","meaning":"chung","hanViet":"CỘNG ĐỒNG","lesson":20,"ex":[["共同で仕事をします。","Chúng tôi làm việc chung với nhau."],["共同のプロジェクトです。","Đây là dự án chung."],["共同で研究をします。","Chúng tôi nghiên cứu chung."],["共同の部屋を使います。","Chúng tôi dùng chung phòng."],["友達と共同で店を開きました。","Tôi đã mở cửa hàng chung với bạn bè."]]},{"word":"田植え","reading":"たうえ","meaning":"trồng lúa","hanViet":"ĐIỀN THỰC","lesson":20,"ex":[["春に田植えをします。","Mùa xuân, tôi trồng lúa."],["田植えは大変な仕事です。","Trồng lúa là công việc vất vả."],["祖父は田植えが上手です。","Ông tôi giỏi trồng lúa."],["田植えの季節になりました。","Đã đến mùa trồng lúa."],["村の人が田植えを手伝います。","Người dân trong làng giúp trồng lúa."]]},{"word":"毒ヘビ","reading":"どくへび","meaning":"rắn độc","hanViet":"ĐỘC","lesson":20,"ex":[["山には毒ヘビがいます。","Trên núi có rắn độc."],["毒ヘビに気をつけてください。","Hãy cẩn thận với rắn độc."],["毒ヘビは危険です。","Rắn độc rất nguy hiểm."],["毒ヘビを見たら、離れてください。","Nếu thấy rắn độc, hãy tránh xa."],["毒ヘビの毒は強いです。","Nọc của rắn độc rất mạnh."]]},{"word":"毒","reading":"どく","meaning":"chất độc","hanViet":"ĐỘC","lesson":20,"ex":[["この花には毒があります。","Loài hoa này có chất độc."],["毒を飲んではいけません。","Không được uống chất độc."],["毒のある魚を食べてはいけません。","Không được ăn cá có độc."],["毒に気をつけてください。","Hãy cẩn thận với chất độc."],["この植物には毒があります。","Loài cây này có chất độc."]]},{"word":"ホッとする","reading":"","meaning":"thở phào nhẹ nhõm","hanViet":"","lesson":20,"ex":[["試験が終わって、ホッとしました。","Thi xong, tôi thở phào nhẹ nhõm."],["無事に着いて、ホッとしました。","Đến nơi an toàn, tôi thở phào nhẹ nhõm."],["いい知らせを聞いて、ホッとしました。","Nghe tin tốt, tôi thở phào nhẹ nhõm."],["母の声を聞いて、ホッとしました。","Nghe giọng mẹ, tôi thở phào nhẹ nhõm."],["問題が終わって、ホッとしました。","Vấn đề đã xong, tôi thở phào nhẹ nhõm."]]},{"word":"腹が立つ","reading":"はらがたつ","meaning":"nổi giận, sôi gan","hanViet":"PHÚC LẬP","lesson":20,"ex":[["約束の時間に来なくて、腹が立ちました。","Anh ấy không đến đúng giờ hẹn, tôi rất tức giận."],["彼の話に腹が立ちました。","Tôi tức giận vì những gì anh ấy nói."],["腹が立っても、静かに話します。","Dù tức giận, tôi vẫn nói chuyện nhẹ nhàng."],["待たされて、腹が立ちました。","Bị bắt chờ đợi, tôi rất tức giận."],["よく腹が立ちます。","Tôi thường xuyên nổi giận."]]},{"word":"演奏家","reading":"えんそうか","meaning":"nghệ sĩ biểu diễn","hanViet":"DIỄN TẤU GIA","lesson":20,"ex":[["彼女は有名な演奏家です。","Cô ấy là nghệ sĩ biểu diễn nổi tiếng."],["演奏家の演奏を聞きました。","Tôi đã nghe nghệ sĩ biểu diễn."],["彼はピアノの演奏家です。","Anh ấy là nghệ sĩ piano."],["演奏家になるのが夢です。","Trở thành nghệ sĩ biểu diễn là ước mơ của tôi."],["若い演奏家がコンサートを開きました。","Nghệ sĩ trẻ đã tổ chức buổi hòa nhạc."]]},{"word":"国立大学","reading":"こくりつだいがく","meaning":"đại học quốc lập","hanViet":"QUỐC LẬP ĐẠI HỌC","lesson":20,"ex":[["彼は国立大学に通っています。","Anh ấy đang học ở đại học quốc lập."],["国立大学に入りたいです。","Tôi muốn vào đại học quốc lập."],["国立大学の学費は安いです。","Học phí đại học quốc lập rẻ."],["兄は国立大学を卒業しました。","Anh trai tôi đã tốt nghiệp đại học quốc lập."],["国立大学で日本語を勉強します。","Tôi học tiếng Nhật ở đại học quốc lập."]]},{"word":"私立大学","reading":"しりつだいがく","meaning":"đại học dân lập","hanViet":"TƯ LẬP ĐẠI HỌC","lesson":20,"ex":[["彼女は私立大学に通っています。","Cô ấy đang học ở đại học tư thục."],["私立大学の学費は高いです。","Học phí đại học tư thục cao."],["私立大学に入学しました。","Tôi đã nhập học đại học tư thục."],["弟は私立大学で経済を勉強しています。","Em trai tôi đang học kinh tế ở đại học tư thục."],["私立大学はたくさんあります。","Có nhiều đại học tư thục."]]},{"word":"経済的（な）","reading":"けいざいてき（な）","meaning":"mang tính kinh tế","hanViet":"KINH TẾ ĐÍCH","lesson":20,"ex":[["経済的な問題があります。","Có vấn đề về kinh tế."],["経済的な理由で大学をやめました。","Tôi đã nghỉ đại học vì lý do kinh tế."],["経済的に困っています。","Tôi đang gặp khó khăn về kinh tế."],["経済的に強くなりたいです。","Tôi muốn mạnh mẽ hơn về kinh tế."],["経済的な心配が大きいです。","Nỗi lo về kinh tế rất lớn."]]},{"word":"学費","reading":"がくひ","meaning":"học phí","hanViet":"HỌC PHÍ","lesson":20,"ex":[["学費が高いです。","Học phí cao."],["学費を払います。","Tôi đóng học phí."],["学費のためにアルバイトをします。","Tôi làm thêm để đóng học phí."],["学費が上がりました。","Học phí đã tăng."],["両親が学費を払ってくれます。","Cha mẹ đóng học phí cho tôi."]]},{"word":"進学（する）","reading":"しんがく（する）","meaning":"học lên","hanViet":"TIẾN HỌC","lesson":20,"ex":[["彼は大学に進学しました。","Anh ấy đã học lên đại học."],["進学するために、毎日勉強します。","Tôi học mỗi ngày để học lên cao hơn."],["高校に進学する予定です。","Tôi dự định học lên cấp ba."],["進学の準備をしています。","Tôi đang chuẩn bị để học lên."],["妹は来年高校に進学します。","Em gái tôi sẽ học lên cấp ba vào năm sau."]]},{"word":"失業（する）","reading":"しつぎょう（する）","meaning":"thất nghiệp","hanViet":"THẤT NGHIỆP","lesson":20,"ex":[["父は失業しました。","Bố tôi đã thất nghiệp."],["失業して、困っています。","Thất nghiệp nên tôi đang gặp khó khăn."],["失業したら、どうしますか。","Nếu thất nghiệp, bạn sẽ làm gì?"],["失業する人が増えています。","Số người thất nghiệp đang tăng."],["失業しても、あきらめません。","Dù thất nghiệp, tôi cũng không bỏ cuộc."]]},{"word":"悩む","reading":"なやむ","meaning":"lo lắng, phiền muộn","hanViet":"NÃO","lesson":20,"ex":[["彼女は将来について悩んでいます。","Cô ấy đang lo lắng về tương lai."],["進学について悩んでいます。","Tôi đang băn khoăn về việc học lên."],["悩んでいる友達を助けました。","Tôi đã giúp người bạn đang phiền muộn."],["悩んでも、答えが見つかりません。","Dù lo lắng, tôi cũng không tìm ra câu trả lời."],["仕事について悩む人が多いです。","Nhiều người lo lắng về công việc."]]},{"word":"引退（する）","reading":"いんたい（する）","meaning":"nghỉ hưu, giải nghệ","hanViet":"DẪN THOÁI","lesson":20,"ex":[["彼は来年引退します。","Anh ấy sẽ giải nghệ vào năm sau."],["有名な選手が引退しました。","Vận động viên nổi tiếng đã giải nghệ."],["引退して、先生になりました。","Sau khi giải nghệ, anh ấy trở thành thầy giáo."],["引退する理由を話しました。","Anh ấy đã nói lý do giải nghệ."],["引退して、ゆっくり休んでいます。","Sau khi giải nghệ, anh ấy đang nghỉ ngơi thong thả."]]},{"word":"渡り歩く","reading":"わたりあるく","meaning":"đi khắp nơi","hanViet":"ĐỘ BỘ","lesson":20,"ex":[["彼は日本を渡り歩きました。","Anh ấy đã đi khắp Nhật Bản."],["いろいろな国を渡り歩きました。","Tôi đã đi qua nhiều nước khác nhau."],["彼は店を渡り歩いて、仕事を探しました。","Anh ấy đi khắp các cửa hàng để tìm việc."],["若い時に、いろいろな町を渡り歩きました。","Khi còn trẻ, tôi đã đi qua nhiều thị trấn khác nhau."],["渡り歩く生活を続けました。","Tôi tiếp tục cuộc sống nay đây mai đó."]]},{"word":"ようやく","reading":"","meaning":"cuối cùng","hanViet":"","lesson":20,"ex":[["ようやく雨が上がりました。","Cuối cùng trời cũng tạnh mưa."],["ようやく仕事が終わりました。","Cuối cùng công việc cũng xong."],["ようやく春が来ました。","Cuối cùng mùa xuân cũng đến."],["ようやく試験に合格しました。","Cuối cùng tôi cũng đỗ kỳ thi."],["ようやく電車が来ました。","Cuối cùng tàu điện cũng đến."]]},{"word":"長時間","reading":"ちょうじかん","meaning":"thời gian dài","hanViet":"TRƯỜNG THỜI GIAN","lesson":20,"ex":[["長時間働きました。","Tôi đã làm việc trong thời gian dài."],["長時間の会議がありました。","Có cuộc họp kéo dài."],["長時間待たされました。","Tôi đã phải chờ đợi rất lâu."],["長時間勉強するのは大変です。","Học trong thời gian dài rất vất vả."],["長時間運転しました。","Tôi đã lái xe trong thời gian dài."]]},{"word":"一致（する）","reading":"いっち（する）","meaning":"nhất trí, trùng khớp","hanViet":"NHẤT TRÍ","lesson":20,"ex":[["二人の意見が一致しました。","Ý kiến của hai người đã nhất trí."],["気持ちが一致しました。","Cảm xúc của chúng tôi đã trùng khớp."],["結果が一致しました。","Kết quả đã trùng khớp."],["彼の話と結果が一致しません。","Lời anh ấy nói và kết quả không khớp nhau."],["みんなの意見が一致して、うれしいです。","Mọi người nhất trí ý kiến, tôi rất vui."]]},{"word":"延長戦","reading":"えんちょうせん","meaning":"hiệp phụ","hanViet":"DIÊN TRƯỜNG CHIẾN","lesson":20,"ex":[["試合は延長戦になりました。","Trận đấu đã bước vào hiệp phụ."],["延長戦で勝ちました。","Chúng tôi đã thắng trong hiệp phụ."],["延長戦まで続きました。","Trận đấu kéo dài đến hiệp phụ."],["延長戦は三十分です。","Hiệp phụ kéo dài ba mươi phút."],["延長戦で点を取りました。","Chúng tôi đã ghi điểm trong hiệp phụ."]]},{"word":"延長（する）","reading":"えんちょう（する）","meaning":"kéo dài","hanViet":"DIÊN TRƯỜNG","lesson":20,"ex":[["会議を延長しました。","Tôi đã kéo dài cuộc họp."],["休みを延長したいです。","Tôi muốn kéo dài kỳ nghỉ."],["試験の時間を延長しました。","Tôi đã kéo dài thời gian thi."],["旅行を延長しました。","Tôi đã kéo dài chuyến du lịch."],["仕事の時間を延長しました。","Tôi đã kéo dài thời gian làm việc."]]},{"word":"交渉（する）","reading":"こうしょう（する）","meaning":"đàm phán","hanViet":"GIAO THIỆP","lesson":20,"ex":[["会社と交渉しました。","Tôi đã đàm phán với công ty."],["給料について交渉します。","Tôi sẽ đàm phán về lương."],["交渉がうまく進みました。","Cuộc đàm phán đã tiến triển tốt đẹp."],["交渉を続けます。","Tôi sẽ tiếp tục đàm phán."],["交渉の結果、給料が上がりました。","Kết quả đàm phán, lương đã tăng."]]},{"word":"アップ（する）","reading":"","meaning":"tăng lên","hanViet":"","lesson":20,"ex":[["給料がアップしました。","Lương đã tăng lên."],["収入がアップしました。","Thu nhập đã tăng lên."],["成績がアップしました。","Thành tích học tập đã tăng lên."],["人気がアップしました。","Độ nổi tiếng đã tăng lên."],["値段がアップして、困っています。","Giá cả tăng lên nên tôi đang gặp khó khăn."]]},{"word":"愛犬","reading":"あいけん","meaning":"con chó cưng","hanViet":"ÁI KHUYỂN","lesson":20,"ex":[["愛犬と散歩します。","Tôi dắt chó cưng đi dạo."],["愛犬はかわいいです。","Chó cưng của tôi rất dễ thương."],["愛犬の写真を撮りました。","Tôi đã chụp ảnh chó cưng."],["愛犬が病気になりました。","Chó cưng của tôi bị bệnh."],["愛犬と公園で遊びます。","Tôi chơi với chó cưng ở công viên."]]},{"word":"とうとう","reading":"","meaning":"cuối cùng","hanViet":"","lesson":20,"ex":[["とうとう雨が降りました。","Cuối cùng trời cũng mưa."],["とうとう試験の日が来ました。","Cuối cùng ngày thi cũng đến."],["とうとう春が来ました。","Cuối cùng mùa xuân cũng đến."],["とうとう彼が来ました。","Cuối cùng anh ấy cũng đến."],["とうとう試合が始まりました。","Cuối cùng trận đấu cũng bắt đầu."]]},{"word":"母校","reading":"ぼこう","meaning":"trường đã tốt nghiệp","hanViet":"MẪU HIỆU","lesson":20,"ex":[["母校に行きました。","Tôi đã đến trường cũ."],["母校の先生に会いました。","Tôi đã gặp thầy giáo ở trường cũ."],["母校でスピーチをしました。","Tôi đã phát biểu ở trường cũ."],["母校は京都にあります。","Trường cũ của tôi ở Kyoto."],["母校で友達に会いました。","Tôi đã gặp bạn bè ở trường cũ."]]},{"word":"偽物","reading":"にせもの","meaning":"đồ giả","hanViet":"NGỤY VẬT","lesson":20,"ex":[["これは偽物です。","Đây là đồ giả."],["偽物を買ってしまいました。","Tôi đã lỡ mua phải đồ giả."],["偽物に気をつけてください。","Hãy cẩn thận với đồ giả."],["偽物を買わないでください。","Đừng mua đồ giả."],["そのバッグは偽物だと思います。","Tôi nghĩ chiếc túi đó là đồ giả."]]},{"word":"重い（病気が～）","reading":"おもい（びょうきが～）","meaning":"nặng (bệnh ~)","hanViet":"TRỌNG BỆNH KHÍ","lesson":20,"ex":[["彼は重い病気になりました。","Anh ấy mắc bệnh nặng."],["祖父は重い病気で入院しました。","Ông tôi nhập viện vì bệnh nặng."],["重い病気にかかりました。","Tôi đã mắc bệnh nặng."],["重い病気でも、彼は元気です。","Dù bệnh nặng, anh ấy vẫn khỏe."],["重い病気を治すために、手術を受けました。","Để chữa bệnh nặng, tôi đã phẫu thuật."]]},{"word":"沸き起こる","reading":"わきおこる","meaning":"nổi lên, trỗi dậy","hanViet":"PHÍ KHỞI","lesson":20,"ex":[["拍手が沸き起こりました。","Tiếng vỗ tay vang lên."],["会場に大きい拍手が沸き起こりました。","Tiếng vỗ tay lớn vang lên khắp hội trường."],["悲しみが沸き起こりました。","Nỗi buồn dâng lên."],["楽しい気持ちが沸き起こりました。","Cảm giác vui vẻ dâng lên."],["悔しい気持ちが沸き起こりました。","Cảm giác ấm ức bùng lên."]]},{"word":"柔らかい（頭が～）","reading":"やわらかい（あたまが～）","meaning":"linh hoạt (đầu ~)","hanViet":"NHU ĐẦU","lesson":20,"ex":[["彼は頭が柔らかいです。","Anh ấy có đầu óc linh hoạt."],["頭が柔らかい人は、新しい意見が出ます。","Người đầu óc linh hoạt đưa ra nhiều ý kiến mới."],["若い人は頭が柔らかいです。","Người trẻ có đầu óc linh hoạt."],["頭を柔らかくするために、本を読みます。","Tôi đọc sách để đầu óc linh hoạt hơn."],["頭が柔らかいので、いろいろな方法を考えます。","Vì đầu óc linh hoạt nên tôi nghĩ ra nhiều cách khác nhau."]]},{"word":"子猫","reading":"こねこ","meaning":"mèo con","hanViet":"TỬ MIÊU","lesson":20,"ex":[["子猫がかわいいです。","Mèo con rất dễ thương."],["子猫を飼っています。","Tôi đang nuôi mèo con."],["子猫が庭で遊んでいます。","Mèo con đang chơi trong sân."],["子猫にミルクをあげました。","Tôi đã cho mèo con uống sữa."],["子猫の声が聞こえました。","Tôi nghe thấy tiếng mèo con kêu."]]},{"word":"持ち出す","reading":"もちだす","meaning":"đưa ra","hanViet":"TRÌ XUẤT","lesson":20,"ex":[["大切な話を持ち出しました。","Tôi đã đưa ra câu chuyện quan trọng."],["部屋から本を持ち出しました。","Tôi lấy sách ra khỏi phòng."],["彼は新しい問題を持ち出しました。","Anh ấy đã đưa ra vấn đề mới."],["会社から書類を持ち出してはいけません。","Không được mang tài liệu ra khỏi công ty."],["写真を持ち出して、友達に見せました。","Tôi lấy ảnh ra cho bạn bè xem."]]},{"word":"拍手（する）","reading":"はくしゅ（する）","meaning":"vỗ tay","hanViet":"PHÁCH THỦ","lesson":20,"ex":[["みんなが拍手しました。","Mọi người đều vỗ tay."],["拍手が起こりました。","Tiếng vỗ tay vang lên."],["大きい拍手を送りました。","Tôi đã dành tràng vỗ tay lớn."],["拍手して、歌手を迎えました。","Chúng tôi vỗ tay chào đón ca sĩ."],["拍手が長く続きました。","Tiếng vỗ tay kéo dài rất lâu."]]},{"word":"民主主義","reading":"みんしゅしゅぎ","meaning":"chủ nghĩa dân chủ","hanViet":"DÂN CHỦ CHỦ NGHĨA","lesson":20,"ex":[["日本は民主主義の国です。","Nhật Bản là nước dân chủ."],["民主主義について勉強します。","Tôi học về chủ nghĩa dân chủ."],["民主主義は大切な制度です。","Dân chủ là chế độ quan trọng."],["民主主義の歴史を学びました。","Tôi đã học lịch sử của chủ nghĩa dân chủ."],["民主主義を守ります。","Tôi sẽ bảo vệ nền dân chủ."]]},{"word":"運動神経","reading":"うんどうしんけい","meaning":"năng khiếu vận động / khả năng vận động","hanViet":"VẬN ĐỘNG THẦN KINH","lesson":20,"ex":[["彼は運動神経がいいです。","Anh ấy có năng khiếu vận động tốt."],["弟は運動神経がとてもいいです。","Em trai tôi có năng khiếu vận động rất tốt."],["運動神経のいい人が多いです。","Có nhiều người giỏi vận động."],["運動神経がよくて、スポーツが得意です。","Vì giỏi vận động nên anh ấy chơi thể thao giỏi."],["彼女は運動神経がいいので、ダンスが上手です。","Vì có năng khiếu vận động tốt nên cô ấy nhảy giỏi."]]},{"word":"一流","reading":"いちりゅう","meaning":"hạng nhất, hàng đầu","hanViet":"NHẤT LƯU","lesson":20,"ex":[["彼は一流の歌手です。","Anh ấy là ca sĩ hàng đầu."],["一流のホテルに泊まりました。","Tôi đã ở khách sạn hạng nhất."],["一流の大学に入りたいです。","Tôi muốn vào đại học hàng đầu."],["一流の選手になりたいです。","Tôi muốn trở thành vận động viên hàng đầu."],["一流のレストランで食事しました。","Tôi đã ăn ở nhà hàng hạng nhất."]]},{"word":"商品開発","reading":"しょうひんかいはつ","meaning":"phát triển sản phẩm mới","hanViet":"THƯƠNG PHẨM KHAI PHÁT","lesson":20,"ex":[["彼は商品開発の仕事をしています。","Anh ấy làm công việc phát triển sản phẩm."],["商品開発に力を入れています。","Công ty đang tập trung vào phát triển sản phẩm."],["新しい商品開発が始まりました。","Việc phát triển sản phẩm mới đã bắt đầu."],["商品開発のために、勉強をします。","Tôi học tập để phát triển sản phẩm."],["商品開発のチームで働きます。","Tôi làm việc trong nhóm phát triển sản phẩm."]]},{"word":"アイス","reading":"","meaning":"kem","hanViet":"","lesson":20,"ex":[["アイスを食べます。","Tôi ăn kem."],["夏はアイスがおいしいです。","Mùa hè ăn kem rất ngon."],["アイスを買いました。","Tôi đã mua kem."],["妹はアイスが好きです。","Em gái tôi thích ăn kem."],["アイスを友達にあげました。","Tôi đã tặng kem cho bạn bè."]]},{"word":"原材料","reading":"げんざいりょう","meaning":"nguyên liệu","hanViet":"NGUYÊN TÀI LIỆU","lesson":20,"ex":[["原材料を調べます。","Tôi kiểm tra nguyên liệu."],["原材料は安全です。","Nguyên liệu rất an toàn."],["原材料の値段が上がりました。","Giá nguyên liệu đã tăng."],["原材料を大切に使います。","Tôi dùng nguyên liệu một cách cẩn thận."],["原材料を外国から買います。","Tôi mua nguyên liệu từ nước ngoài."]]},{"word":"試作品","reading":"しさくひん","meaning":"sản phẩm thử, mẫu thử","hanViet":"THÍ TÁC PHẨM","lesson":20,"ex":[["試作品を作りました。","Tôi đã làm sản phẩm thử."],["試作品をテストします。","Tôi thử nghiệm sản phẩm mẫu."],["試作品ができました。","Sản phẩm thử đã hoàn thành."],["試作品を見せてください。","Hãy cho tôi xem sản phẩm thử."],["試作品の数が多いです。","Số lượng sản phẩm thử rất nhiều."]]},{"word":"失敗作","reading":"しっぱいさく","meaning":"sản phẩm thất bại","hanViet":"THẤT BẠI TÁC","lesson":20,"ex":[["これは失敗作です。","Đây là sản phẩm thất bại."],["失敗作がたくさんできました。","Đã có nhiều sản phẩm thất bại."],["失敗作から学びました。","Tôi đã học được từ sản phẩm thất bại."],["失敗作でも、あきらめません。","Dù là sản phẩm thất bại, tôi cũng không bỏ cuộc."],["失敗作を捨てました。","Tôi đã vứt bỏ sản phẩm thất bại."]]},{"word":"企業秘密","reading":"きぎょうびみつ","meaning":"bí mật doanh nghiệp","hanViet":"XÍ NGHIỆP BÍ MẬT","lesson":20,"ex":[["これは企業秘密です。","Đây là bí mật doanh nghiệp."],["企業秘密を守ります。","Tôi sẽ giữ bí mật doanh nghiệp."],["企業秘密を話してはいけません。","Không được tiết lộ bí mật doanh nghiệp."],["企業秘密は大切にします。","Tôi coi trọng bí mật doanh nghiệp."],["企業秘密について聞かれました。","Tôi đã bị hỏi về bí mật doanh nghiệp."]]},{"word":"ヒント","reading":"","meaning":"gợi ý","hanViet":"","lesson":20,"ex":[["ヒントをください。","Hãy cho tôi gợi ý."],["ヒントが欲しいです。","Tôi muốn có gợi ý."],["先生がヒントをくれました。","Thầy giáo đã cho tôi gợi ý."],["ヒントを教えてください。","Hãy cho tôi biết gợi ý."],["ヒントがあれば、問題ができます。","Nếu có gợi ý, tôi có thể làm được bài toán."]]},{"word":"待ち遠しい","reading":"まちどおしい","meaning":"mong chờ","hanViet":"ĐÃI VIỄN","lesson":20,"ex":[["夏が待ち遠しいです。","Tôi mong chờ mùa hè đến."],["旅行の日が待ち遠しいです。","Tôi mong chờ ngày đi du lịch."],["試験の結果が待ち遠しいです。","Tôi mong chờ kết quả thi."],["友達に会うのが待ち遠しいです。","Tôi mong chờ được gặp bạn bè."],["春が待ち遠しいです。","Tôi mong chờ mùa xuân đến."]]},{"word":"ハープ","reading":"","meaning":"đàn Harp (còn gọi là đàn Hạc)","hanViet":"","lesson":20,"ex":[["ハープを弾きます。","Tôi chơi đàn harp."],["ハープの音がきれいです。","Âm thanh của đàn harp rất đẹp."],["彼女はハープが上手です。","Cô ấy chơi đàn harp giỏi."],["ハープを習っています。","Tôi đang học đàn harp."],["ハープの演奏を聞きました。","Tôi đã nghe biểu diễn đàn harp."]]},{"word":"優雅（な）","reading":"ゆうが（な）","meaning":"thanh tao, nhẹ nhàng","hanViet":"ƯU NHÃ","lesson":20,"ex":[["彼女は優雅な人です。","Cô ấy là người thanh tao."],["優雅な音楽を聞きました。","Tôi đã nghe nhạc nhẹ nhàng, thanh tao."],["優雅に踊りました。","Cô ấy nhảy một cách uyển chuyển."],["優雅な服を着ています。","Cô ấy đang mặc bộ đồ thanh lịch."],["優雅な姿が美しいです。","Dáng vẻ thanh tao thật đẹp."]]},{"word":"奏でる","reading":"かなでる","meaning":"chơi","hanViet":"TẤU","lesson":20,"ex":[["ピアノを奏でます。","Tôi chơi piano."],["彼女はハープを奏でます。","Cô ấy chơi đàn harp."],["美しい音を奏でました。","Tôi đã tạo ra âm thanh tuyệt đẹp."],["彼は新しい曲を奏でます。","Anh ấy chơi bản nhạc mới."],["優雅な曲を奏でました。","Tôi đã chơi bản nhạc thanh tao."]]},{"word":"背丈","reading":"せたけ","meaning":"chiều cao cơ thể","hanViet":"BỐI TRƯỢNG","lesson":20,"ex":[["彼の背丈は高いです。","Anh ấy rất cao."],["背丈が高くなりました。","Chiều cao đã tăng lên."],["弟の背丈が大きくなりました。","Chiều cao của em trai tôi đã lớn lên."],["背丈を測りました。","Tôi đã đo chiều cao."],["背丈が高い人が多いです。","Có nhiều người cao."]]},{"word":"枠","reading":"わく","meaning":"khung","hanViet":"","lesson":20,"ex":[["この写真はきれいな枠に入っています。","Bức ảnh này được đặt trong một chiếc khung đẹp."],["母は新しい枠を買って、絵を飾りました。","Mẹ tôi đã mua một chiếc khung mới và treo bức tranh lên."],["窓の枠が古くなりましたから、直したいです。","Khung cửa sổ đã cũ nên tôi muốn sửa nó."],["その枠は木で作られていて、とても強いです。","Chiếc khung đó được làm bằng gỗ nên rất chắc chắn."],["この枠の中に家族の写真を入れます。","Tôi sẽ đặt ảnh gia đình vào trong khung này."]]},{"word":"張る（弦を～）","reading":"はる（げんを～）","meaning":"căng (dây đàn)","hanViet":"TRƯƠNG HUYỀN","lesson":20,"ex":[["楽器の弦が古くなりましたから、新しい弦を張ります。","Dây đàn đã cũ nên tôi sẽ căng dây mới."],["先生は弦を張る方法を教えてくれました。","Thầy đã chỉ cho tôi cách căng dây đàn."],["弦を強く張りすぎると、音が変わります。","Nếu căng dây quá chặt, âm thanh sẽ thay đổi."],["弟は初めて楽器の弦を張りました。","Em trai tôi lần đầu tiên căng dây đàn."],["音楽会の前に、私は楽器の弦を張りました。","Trước buổi hòa nhạc, tôi đã căng dây đàn."]]},{"word":"親指","reading":"おやゆび","meaning":"ngón tay cái","hanViet":"THÂN CHỈ","lesson":20,"ex":[["親指で弦をはじくと、大きい音が出ます。","Khi móc dây đàn bằng ngón tay cái, âm thanh lớn sẽ vang lên."],["親指を使って、弦をはじきます。","Tôi dùng ngón tay cái để móc dây đàn."],["子どもの親指はとても小さいです。","Ngón tay cái của trẻ con rất nhỏ."],["親指でボタンを押します。","Tôi bấm nút bằng ngón tay cái."],["親指が疲れましたから、少し休みます。","Ngón tay cái đã mỏi nên tôi nghỉ một chút."]]},{"word":"はじく","reading":"","meaning":"móc (dây đàn)","hanViet":"","lesson":20,"ex":[["親指で弦をはじきます。","Tôi móc dây đàn bằng ngón tay cái."],["彼は楽器の弦をはじくのが上手です。","Anh ấy rất giỏi móc dây đàn."],["弦をはじくときは、力を入れすぎないでください。","Khi móc dây đàn, đừng dùng lực quá mạnh."],["弟は楽しそうに弦をはじきました。","Em trai tôi móc dây đàn một cách vui vẻ."],["弦をゆっくりはじくと、静かな音が出ます。","Khi móc dây đàn chậm rãi, âm thanh nhẹ nhàng vang lên."]]},{"word":"上半身","reading":"じょうはんしん","meaning":"nửa trên cơ thể","hanViet":"THƯỢNG BÁN THÂN","lesson":20,"ex":[["演奏するときは、上半身をまっすぐにします。","Khi biểu diễn, tôi giữ thẳng nửa thân trên."],["彼は上半身をゆっくり揺らして、歌いました。","Anh ấy đung đưa nửa thân trên một cách chậm rãi và hát."],["長い時間立っていましたから、上半身が疲れました。","Vì đứng lâu nên nửa thân trên của tôi đã mỏi."],["寒い日は、上半身を温かくします。","Vào ngày lạnh, tôi giữ ấm nửa thân trên."],["彼は上半身を前に出して、歌いました。","Anh ấy đưa nửa thân trên về phía trước và hát."]]},{"word":"揺らす","reading":"ゆらす","meaning":"đung đưa","hanViet":"DAO","lesson":20,"ex":[["風が木を揺らします。","Gió làm cây đung đưa."],["彼は体をゆっくり揺らして、歌いました。","Anh ấy đung đưa cơ thể chậm rãi và hát."],["彼は肩を揺らして、笑いました。","Anh ấy rung vai và cười."],["強い風が船を揺らしました。","Gió mạnh đã làm con thuyền chao đảo."],["電車の中で体が揺らされました。","Trong tàu điện, cơ thể tôi bị rung lắc."]]},{"word":"掛け合い","reading":"かけあい","meaning":"đối đáp","hanViet":"QUẢI HỢP","lesson":20,"ex":[["二人の掛け合いがおもしろくて、みんな笑いました。","Màn đối đáp của hai người rất thú vị, mọi người đều cười."],["先生と生徒の掛け合いが授業を楽しくしました。","Màn đối đáp giữa thầy và trò làm giờ học trở nên vui vẻ."],["友達との掛け合いを楽しみました。","Tôi đã thích thú với màn đối đáp cùng bạn bè."],["掛け合いがよかったですから、コンサートは成功しました。","Nhờ màn đối đáp hay mà buổi hòa nhạc đã thành công."],["彼は掛け合いが上手で、いつもみんなを笑わせます。","Anh ấy giỏi đối đáp, lúc nào cũng làm mọi người cười."]]},{"word":"リード（する）","reading":"","meaning":"dẫn dắt","hanViet":"","lesson":20,"ex":[["先生がクラスをリードしました。","Thầy đã dẫn dắt lớp học."],["彼はチームをリードして、みんなを助けました。","Anh ấy dẫn dắt đội và giúp đỡ mọi người."],["彼女は音楽のグループをリードしています。","Cô ấy đang dẫn dắt nhóm nhạc."],["田中さんが新しい計画をリードします。","Anh Tanaka sẽ dẫn dắt kế hoạch mới."],["リードする人は、みんなの声をよく聞きます。","Người dẫn dắt lắng nghe kỹ tiếng nói của mọi người."]]},{"word":"現地","reading":"げんち","meaning":"nơi diễn ra sự việc, tại chỗ, địa phương (nơi đó)","hanViet":"HIỆN ĐỊA","lesson":20,"ex":[["現地の音楽はとても有名です。","Âm nhạc địa phương rất nổi tiếng."],["私は現地に行って、音楽を聞きました。","Tôi đã đến đó và nghe nhạc."],["現地の生活は日本と違います。","Cuộc sống ở đó khác với Nhật Bản."],["現地で働く人は、毎日忙しいです。","Người làm việc ở đó bận rộn mỗi ngày."],["彼は現地の歌を勉強しました。","Anh ấy đã học bài hát địa phương."]]},{"word":"付け根","reading":"つけね","meaning":"gốc, phần nối (chỗ bám vào thân/vật)","hanViet":"PHÓ CĂN","lesson":20,"ex":[["指の付け根が痛みます。","Khớp nối của ngón tay bị đau."],["親指の付け根を押すと、痛みます。","Khi ấn vào khớp nối ngón tay cái thì thấy đau."],["花の付け根が折れました。","Phần nối của bông hoa đã gãy."],["彼は腕の付け根が痛みますから、病院に行きました。","Vì khớp nối cánh tay bị đau nên anh ấy đã đến bệnh viện."],["付け根をゆっくり動かすと、よくなります。","Khi cử động nhẹ khớp nối, nó sẽ đỡ hơn."]]},{"word":"痛む","reading":"いたむ","meaning":"đau, nhức","hanViet":"THỐNG","lesson":20,"ex":[["歯が痛みます。","Răng tôi bị đau."],["朝から足が痛みます。","Từ sáng chân tôi đã đau."],["肩が痛みますから、すぐ寝ます。","Vì vai đau nên tôi đi ngủ ngay."],["心が痛みます。","Lòng tôi đau nhói."],["けがをした場所が痛みます。","Chỗ bị thương đau nhức."]]},{"word":"本場","reading":"ほんば","meaning":"nơi sản sinh, nơi khơi nguồn","hanViet":"BẢN TRƯỜNG","lesson":20,"ex":[["本場の料理を食べたいです。","Tôi muốn ăn món ăn đúng gốc."],["彼は本場に行って、音楽を聞きました。","Anh ấy đã đến nơi sản sinh ra nó và nghe nhạc."],["京都のお茶は本場の味です。","Trà ở Kyoto có hương vị đúng gốc."],["本場の味を楽しむために、店に行きました。","Để thưởng thức hương vị đúng gốc, tôi đã đến cửa hàng."],["その店は本場の料理が有名です。","Cửa hàng đó nổi tiếng với món ăn đúng gốc."]]},{"word":"雰囲気","reading":"ふんいき","meaning":"không khí","hanViet":"PHÂN VI KHÍ","lesson":20,"ex":[["この店の雰囲気が好きです。","Tôi thích không khí của cửa hàng này."],["部屋の雰囲気が明るくなりました。","Không khí trong phòng đã trở nên sáng sủa."],["その店は静かな雰囲気です。","Cửa hàng đó có không khí yên tĩnh."],["コンサートの雰囲気はとてもよかったです。","Không khí buổi hòa nhạc rất tốt."],["彼女は明るい雰囲気を持っています。","Cô ấy mang một bầu không khí tươi sáng."]]},{"word":"ふと","reading":"","meaning":"tình cờ, ngẫu nhiên","hanViet":"","lesson":20,"ex":[["ふと、昔のことを思い出しました。","Tình cờ tôi nhớ lại chuyện ngày xưa."],["ふと窓の外を見ました。","Tôi tình cờ nhìn ra ngoài cửa sổ."],["ふと、いい方法を考えました。","Tình cờ tôi nghĩ ra một cách hay."],["彼はふと歩くのを止めました。","Anh ấy tình cờ dừng bước."],["ふと、子どものときの歌を歌いました。","Tình cờ tôi hát bài hát thời thơ ấu."]]},{"word":"格好良い","reading":"かっこ（う）よい","meaning":"đẹp trai, ngầu, bảnh bao","hanViet":"CÁCH HẢO LƯƠNG","lesson":20,"ex":[["彼はとても格好良いです。","Anh ấy rất đẹp trai."],["その歌手の服は格好良いです。","Trang phục của ca sĩ đó rất ngầu."],["格好良い車を見ました。","Tôi đã thấy một chiếc xe rất ngầu."],["田中さんは格好良い人です。","Anh Tanaka là người đẹp trai."],["彼は格好良い声で歌いました。","Anh ấy hát bằng giọng rất hay."]]},{"word":"ほれ込む","reading":"ほれこむ","meaning":"say mê, say đắm","hanViet":"","lesson":20,"ex":[["彼は音楽にほれ込んで、毎日練習します。","Anh ấy say mê âm nhạc, luyện tập mỗi ngày."],["私はその映画にほれ込みました。","Tôi đã say mê bộ phim đó."],["彼女は日本の文化にほれ込んで、日本に来ました。","Cô ấy say mê văn hóa Nhật Bản nên đã đến Nhật."],["彼は新しい楽器にほれ込みました。","Anh ấy đã say mê nhạc cụ mới."],["子どもはサッカーにほれ込んでいます。","Đứa trẻ đang say mê bóng đá."]]},{"word":"拍子","reading":"ひょうし／～びょうし","meaning":"nhịp","hanViet":"PHÁCH TỬ","lesson":20,"ex":[["拍子をとって、みんなで歌いました。","Mọi người cùng giữ nhịp và hát."],["この曲の拍子は速いです。","Nhịp của bài hát này nhanh."],["拍子を聞いて、踊りました。","Tôi nghe nhịp và nhảy múa."],["彼は拍子をとるのが上手です。","Anh ấy rất giỏi giữ nhịp."],["ゆっくりした拍子の曲が好きです。","Tôi thích bài hát có nhịp chậm rãi."]]},{"word":"同時進行（する）","reading":"どうじしんこう（する）","meaning":"tiến hành đồng thời","hanViet":"ĐỒNG THỜI TIẾN HÀNH","lesson":20,"ex":[["二つの仕事を同時進行します。","Tôi tiến hành hai công việc cùng lúc."],["彼は勉強と仕事を同時進行しています。","Anh ấy vừa học vừa làm cùng lúc."],["二つの計画が同時進行しています。","Hai kế hoạch đang tiến hành đồng thời."],["会社は二つの番組を同時進行で作っています。","Công ty đang sản xuất hai chương trình cùng lúc."],["同時進行するために、時間の計画が必要です。","Để tiến hành đồng thời, cần có kế hoạch thời gian."]]},{"word":"番組制作","reading":"ばんぐみせいさく","meaning":"sản xuất chương trình","hanViet":"PHIÊN TỔ CHẾ TÁC","lesson":20,"ex":[["彼は番組制作の仕事をしています。","Anh ấy làm công việc sản xuất chương trình."],["番組制作には、たくさんの人が必要です。","Sản xuất chương trình cần rất nhiều người."],["番組制作の仕事は毎日忙しいです。","Công việc sản xuất chương trình bận rộn mỗi ngày."],["番組制作のチームは、朝から夜まで働きます。","Đội sản xuất chương trình làm việc từ sáng đến tối."],["テレビの番組制作を見学しました。","Tôi đã tham quan việc sản xuất chương trình truyền hình."]]},{"word":"同時","reading":"どうじ","meaning":"cùng một lúc, đồng thời","hanViet":"ĐỒNG THỜI","lesson":20,"ex":[["二人が同時に歌いました。","Hai người cùng hát một lúc."],["私たちは同時に来ました。","Chúng tôi cùng đến một lúc."],["二つの仕事を同時に始めました。","Tôi đã bắt đầu hai công việc cùng lúc."],["同時に二つのことをしないでください。","Đừng làm hai việc cùng lúc."],["彼は同時に二つの楽器を弾きます。","Anh ấy chơi hai nhạc cụ cùng lúc."]]},{"word":"ラテン音楽","reading":"ラテンおんがく","meaning":"nhạc Latinh","hanViet":"ÂM LẠC, NHẠC","lesson":20,"ex":[["ラテン音楽は明るくて、楽しいです。","Nhạc Latinh tươi sáng và vui vẻ."],["彼はラテン音楽が好きで、毎日聞きます。","Anh ấy thích nhạc Latinh, nghe mỗi ngày."],["ラテン音楽を聞くと、踊りたくなります。","Khi nghe nhạc Latinh, tôi muốn nhảy múa."],["その店ではラテン音楽を聞くことができます。","Ở cửa hàng đó có thể nghe nhạc Latinh."],["ラテン音楽のコンサートに行きました。","Tôi đã đi nghe hòa nhạc Latinh."]]},{"word":"渡る（現地に～）","reading":"わたる（げんちに～）","meaning":"đến (địa phương)","hanViet":"ĐỘ HIỆN ĐỊA","lesson":20,"ex":[["彼は現地に渡って、音楽を勉強しました。","Anh ấy đã đến địa phương đó để học nhạc."],["去年、彼女は外国に渡りました。","Năm ngoái, cô ấy đã sang nước ngoài."],["音楽家は現地に渡って、本場の音楽を聞きました。","Nhạc sĩ đã đến đó và nghe nhạc đúng gốc."],["彼は学生のときに外国に渡りました。","Anh ấy đã sang nước ngoài khi còn là sinh viên."],["彼は来年現地に渡ります。","Anh ấy sẽ đến đó vào năm sau."]]},{"word":"夜明け","reading":"よあけ","meaning":"bình minh, rạng đông","hanViet":"DẠ MINH","lesson":20,"ex":[["夜明けの空はとてもきれいです。","Bầu trời lúc bình minh rất đẹp."],["夜明けに起きて、海を見ました。","Tôi dậy lúc bình minh và ngắm biển."],["夜明けまで働きました。","Tôi đã làm việc đến tận bình minh."],["夜明けの時間が好きです。","Tôi thích thời gian bình minh."],["夜明けに町が明るくなりました。","Lúc bình minh, thành phố đã sáng lên."]]},{"word":"即興演奏","reading":"そっきょうえんそう","meaning":"biểu diễn ngẫu hứng","hanViet":"TỨC HƯNG DIỄN TẤU","lesson":20,"ex":[["彼は即興演奏が上手です。","Anh ấy giỏi biểu diễn ngẫu hứng."],["コンサートで即興演奏をしました。","Anh ấy đã biểu diễn ngẫu hứng tại buổi hòa nhạc."],["即興演奏を聞いて、感激しました。","Nghe biểu diễn ngẫu hứng, tôi đã cảm động."],["彼女の即興演奏はとてもよかったです。","Màn biểu diễn ngẫu hứng của cô ấy rất hay."],["即興演奏をする前に、少し考えました。","Trước khi biểu diễn ngẫu hứng, tôi đã suy nghĩ một chút."]]},{"word":"即興","reading":"そっきょう","meaning":"ngẫu hứng","hanViet":"TỨC HƯNG","lesson":20,"ex":[["彼は即興で歌いました。","Anh ấy đã hát ngẫu hứng."],["即興の演奏が始まりました。","Màn biểu diễn ngẫu hứng đã bắt đầu."],["彼女は即興で曲を作りました。","Cô ấy đã sáng tác bài hát một cách ngẫu hứng."],["即興で話すのは、大変です。","Nói ngẫu hứng rất vất vả."],["即興の歌がみんなを笑わせました。","Bài hát ngẫu hứng đã làm mọi người cười."]]},{"word":"バンド","reading":"","meaning":"ban nhạc","hanViet":"","lesson":20,"ex":[["彼はバンドで歌っています。","Anh ấy hát trong ban nhạc."],["私たちはバンドを作りました。","Chúng tôi đã lập một ban nhạc."],["そのバンドはとても有名です。","Ban nhạc đó rất nổi tiếng."],["バンドは毎週練習します。","Ban nhạc luyện tập mỗi tuần."],["バンドのメンバーはみんな若者です。","Các thành viên ban nhạc đều là người trẻ."]]},{"word":"加わる","reading":"くわわる","meaning":"thêm vào","hanViet":"GIA","lesson":20,"ex":[["新しい人がグループに加わりました。","Người mới đã tham gia nhóm."],["私もその計画に加わりたいです。","Tôi cũng muốn tham gia kế hoạch đó."],["彼女がバンドに加わりました。","Cô ấy đã tham gia ban nhạc."],["新しいメンバーがチームに加わりました。","Thành viên mới đã tham gia đội."],["仕事に加わる前に、よく考えました。","Trước khi tham gia công việc, tôi đã suy nghĩ kỹ."]]},{"word":"持ち味","reading":"もちあじ","meaning":"đặc tính, bản sắc riêng","hanViet":"TRÌ VỊ","lesson":20,"ex":[["彼の持ち味は明るい声です。","Điểm riêng của anh ấy là giọng nói tươi sáng."],["その店の持ち味は安い値段です。","Điểm riêng của cửa hàng đó là giá rẻ."],["持ち味を大切にしています。","Tôi trân trọng điểm riêng của mình."],["彼女の持ち味はきれいな歌です。","Điểm riêng của cô ấy là giọng hát hay."],["自分の持ち味を考えることが大切です。","Suy nghĩ về điểm riêng của mình là quan trọng."]]},{"word":"武者修行","reading":"むしゃしゅぎょう","meaning":"đi tầm sư học đạo","hanViet":"VŨ, VÕ GIẢ TU HÀNH","lesson":20,"ex":[["彼は武者修行のために、各地を歩きました。","Anh ấy đã đi bộ khắp các nơi để tầm sư học đạo."],["その音楽家は武者修行をしています。","Nhạc sĩ đó đang đi tầm sư học đạo."],["武者修行の旅は長くて、大変でした。","Chuyến đi tầm sư học đạo dài và vất vả."],["彼は武者修行でたくさんの人と会いました。","Anh ấy đã gặp nhiều người trong chuyến tầm sư học đạo."],["武者修行をして、日本に帰りました。","Sau chuyến tầm sư học đạo, anh ấy đã trở về Nhật Bản."]]},{"word":"各地","reading":"かくち","meaning":"các nơi","hanViet":"CÁC ĐỊA","lesson":20,"ex":[["各地の音楽を聞きました。","Tôi đã nghe nhạc của các nơi."],["彼は各地を旅行しました。","Anh ấy đã đi du lịch khắp các nơi."],["各地の料理を食べました。","Tôi đã ăn món ăn của các nơi."],["各地からたくさんの人が来ました。","Nhiều người đã đến từ khắp các nơi."],["各地の文化を勉強したいです。","Tôi muốn học văn hóa của các nơi."]]},{"word":"刻む","reading":"きざむ","meaning":"khắc, chạm trổ","hanViet":"KHẮC","lesson":20,"ex":[["彼は木に星の形を刻みました。","Anh ấy đã khắc hình ngôi sao lên gỗ."],["彼は木を刻んで、花を作りました。","Anh ấy khắc gỗ thành bông hoa."],["彼女は石に名前を刻みました。","Cô ấy đã khắc tên lên đá."],["壁に字を刻みました。","Tôi đã khắc chữ lên tường."],["昔の人は石に字を刻みました。","Người xưa đã khắc chữ lên đá."]]},{"word":"自腹を切る","reading":"じばらをきる","meaning":"tự bỏ tiền túi","hanViet":"TỰ PHÚC THIẾT","lesson":20,"ex":[["彼は自腹を切って、楽器を買いました。","Anh ấy tự bỏ tiền túi mua nhạc cụ."],["自腹を切って、旅行に行きました。","Tôi tự bỏ tiền túi đi du lịch."],["会社のお金ではなく、自腹を切りました。","Không phải tiền công ty, tôi đã tự bỏ tiền túi."],["自腹を切るのは、大変です。","Tự bỏ tiền túi rất vất vả."],["彼は自腹を切って、バンドを助けました。","Anh ấy tự bỏ tiền túi giúp đỡ ban nhạc."]]},{"word":"独立（する）","reading":"どくりつ（する）","meaning":"độc lập","hanViet":"ĐỘC LẬP","lesson":20,"ex":[["彼は会社から独立しました。","Anh ấy đã tách ra độc lập khỏi công ty."],["彼女は独立して、自分の店を開きました。","Cô ấy đã độc lập và mở cửa hàng của riêng mình."],["独立するのは、大変です。","Độc lập rất vất vả."],["彼は来年独立するつもりです。","Anh ấy dự định độc lập vào năm sau."],["子どもは大人になって、独立します。","Trẻ con lớn lên thành người lớn và sống độc lập."]]},{"word":"交じる","reading":"まじる","meaning":"trộn, lẫn","hanViet":"GIAO","lesson":20,"ex":[["赤い花に白い花が交じっています。","Hoa trắng lẫn trong hoa đỏ."],["音楽に子どもの声が交じっています。","Tiếng trẻ con lẫn trong âm nhạc."],["塩が砂糖に交じりました。","Muối đã lẫn vào đường."],["彼の話に英語が交じっています。","Tiếng Anh lẫn trong câu chuyện của anh ấy."],["雨に雪が交じっています。","Tuyết lẫn trong mưa."]]},{"word":"感激（する）","reading":"かんげき（する）","meaning":"cảm động","hanViet":"CẢM KHÍCH, KÍCH","lesson":20,"ex":[["彼の歌に感激しました。","Tôi đã cảm động trước bài hát của anh ấy."],["彼女の話に感激しました。","Tôi đã cảm động trước câu chuyện của cô ấy."],["みんなの親切に感激しました。","Tôi đã cảm động trước sự thân thiện của mọi người."],["感激して、涙が出ました。","Cảm động quá, nước mắt đã rơi."],["その映画に感激して、もう一度見ました。","Cảm động trước bộ phim đó, tôi đã xem lại lần nữa."]]},{"word":"自作","reading":"じさく","meaning":"tự làm","hanViet":"TỰ TÁC","lesson":20,"ex":[["これは自作の楽器です。","Đây là nhạc cụ tự làm."],["彼は自作の曲を歌いました。","Anh ấy đã hát bài hát tự sáng tác."],["自作の料理を友達と食べました。","Tôi đã ăn món tự làm cùng bạn bè."],["彼女は自作の服を着ています。","Cô ấy đang mặc quần áo tự làm."],["自作の絵を部屋に飾りました。","Tôi đã treo bức tranh tự vẽ trong phòng."]]},{"word":"がらくた","reading":"","meaning":"rác, phế liệu","hanViet":"","lesson":20,"ex":[["部屋にがらくたがたくさんあります。","Trong phòng có rất nhiều đồ linh tinh."],["がらくたを捨てました。","Tôi đã vứt đồ linh tinh đi."],["その箱にはがらくただけが入っています。","Trong hộp đó chỉ có đồ linh tinh."],["がらくたの中から、古い写真を見つけました。","Tôi đã tìm thấy bức ảnh cũ trong đống đồ linh tinh."],["彼はがらくたを集めて、楽器を作りました。","Anh ấy gom đồ linh tinh để làm nhạc cụ."]]},{"word":"大型","reading":"おおがた","meaning":"kích cỡ lớn","hanViet":"ĐẠI HÌNH","lesson":20,"ex":[["大型の車を見ました。","Tôi đã thấy chiếc xe cỡ lớn."],["大型のテレビを買いました。","Tôi đã mua chiếc tivi cỡ lớn."],["大型の店が新しくできました。","Cửa hàng lớn mới đã được mở."],["大型の楽器は運ぶのが大変です。","Nhạc cụ cỡ lớn rất vất vả khi vận chuyển."],["大型の箱に本を入れました。","Tôi đã cho sách vào hộp lớn."]]},{"word":"空き缶","reading":"あきかん","meaning":"lon rỗng","hanViet":"KHÔNG PHẪU","lesson":20,"ex":[["空き缶を捨てました。","Tôi đã vứt lon rỗng đi."],["空き缶を集めて、楽器を作りました。","Tôi gom lon rỗng để làm nhạc cụ."],["公園に空き缶が落ちています。","Lon rỗng rơi ở công viên."],["空き缶を箱に入れました。","Tôi đã cho lon rỗng vào hộp."],["空き缶を洗って、使いました。","Tôi đã rửa lon rỗng và dùng nó."]]},{"word":"バネ","reading":"","meaning":"lò xo","hanViet":"","lesson":20,"ex":[["バネが壊れました。","Lò xo đã hỏng."],["このおもちゃにはバネが入っています。","Đồ chơi này có lò xo bên trong."],["バネを押すと、音が出ます。","Khi ấn lò xo, âm thanh vang lên."],["古いバネを直しました。","Tôi đã sửa lò xo cũ."],["バネの力が強いです。","Lực của lò xo rất mạnh."]]},{"word":"弦楽器","reading":"げんがっき","meaning":"nhạc cụ dây","hanViet":"HUYỀN LẠC, NHẠC KHÍ","lesson":20,"ex":[["弦楽器の音が好きです。","Tôi thích âm thanh của nhạc cụ dây."],["彼は弦楽器を弾きます。","Anh ấy chơi nhạc cụ dây."],["バイオリンは弦楽器の一つです。","Violin là một trong các nhạc cụ dây."],["弦楽器のコンサートに行きました。","Tôi đã đi nghe hòa nhạc cụ dây."],["子どもは弦楽器を習っています。","Đứa trẻ đang học nhạc cụ dây."]]},{"word":"エコー","reading":"","meaning":"tiếng vọng lại","hanViet":"","lesson":20,"ex":[["山で声がエコーしました。","Tiếng nói vang vọng lại ở núi."],["大きい部屋では声がエコーします。","Trong phòng lớn, tiếng nói vang vọng lại."],["エコーが聞こえました。","Tôi đã nghe thấy tiếng vọng lại."],["その部屋ではエコーが大きいです。","Trong căn phòng đó, tiếng vọng rất lớn."],["エコーを楽しみました。","Tôi đã thích thú với tiếng vọng lại."]]},{"word":"説得（する）","reading":"せっとく（する）","meaning":"thuyết phục","hanViet":"THUYẾT ĐẮC","lesson":20,"ex":[["彼は父を説得して、楽器を買いました。","Anh ấy đã thuyết phục bố và mua nhạc cụ."],["先生は生徒を説得しました。","Thầy đã thuyết phục học sinh."],["彼女を説得するのは、大変でした。","Thuyết phục cô ấy rất vất vả."],["母を説得して、旅行に行きました。","Tôi đã thuyết phục mẹ và đi du lịch."],["説得するために、よく話しました。","Để thuyết phục, tôi đã nói chuyện kỹ."]]},{"word":"素材","reading":"そざい","meaning":"vật liệu","hanViet":"TỐ TÀI","lesson":20,"ex":[["この楽器の素材は木です。","Vật liệu của nhạc cụ này là gỗ."],["いい素材を使って、料理を作ります。","Tôi dùng vật liệu tốt để nấu ăn."],["素材の値段が高いです。","Giá vật liệu cao."],["彼は素材を集めて、楽器を作りました。","Anh ấy gom vật liệu để làm nhạc cụ."],["この服の素材はいいです。","Vật liệu của bộ quần áo này tốt."]]},{"word":"表明する","reading":"ひょうめいする","meaning":"bày tỏ, thể hiện","hanViet":"BIỂU MINH","lesson":21,"ex":[["彼は自分の意見を表明しました。","Anh ấy đã bày tỏ ý kiến của mình."],["社長は新しい計画を表明しました。","Giám đốc đã bày tỏ kế hoạch mới."],["彼女は反対の気持ちを表明しました。","Cô ấy đã bày tỏ ý phản đối."],["会議で気持ちを表明しました。","Tôi đã bày tỏ cảm xúc trong cuộc họp."],["彼はテレビで気持ちを表明しました。","Anh ấy đã bày tỏ cảm xúc trên truyền hình."]]},{"word":"根拠","reading":"こんきょ","meaning":"căn cứ","hanViet":"CĂN CỨ","lesson":21,"ex":[["根拠のない話は信じません。","Tôi không tin câu chuyện không có căn cứ."],["その意見には根拠があります。","Ý kiến đó có căn cứ."],["根拠を教えてください。","Hãy cho tôi biết căn cứ."],["根拠がありませんから、信じられません。","Vì không có căn cứ nên tôi không thể tin."],["彼は根拠を説明しました。","Anh ấy đã giải thích căn cứ."]]},{"word":"基づく","reading":"もとづく","meaning":"dựa vào","hanViet":"CƠ","lesson":21,"ex":[["調査に基づいて、計画を作りました。","Dựa vào điều tra, tôi đã lập kế hoạch."],["結果に基づいて、決めました。","Dựa vào kết quả, tôi đã quyết định."],["彼の話は本に基づいています。","Câu chuyện của anh ấy dựa vào sách."],["経験に基づいて、答えました。","Dựa vào kinh nghiệm, tôi đã trả lời."],["この本は歴史に基づいています。","Cuốn sách này dựa vào lịch sử."]]},{"word":"基に","reading":"もとに","meaning":"dựa trên","hanViet":"CƠ","lesson":21,"ex":[["調査を基に、計画を作りました。","Dựa trên điều tra, tôi đã lập kế hoạch."],["本を基に、映画を作りました。","Dựa trên sách, tôi đã làm phim."],["彼の話を基に、記事を書きました。","Dựa trên câu chuyện của anh ấy, tôi đã viết bài báo."],["経験を基に、教えました。","Dựa trên kinh nghiệm, tôi đã dạy."],["結果を基に、決めました。","Dựa trên kết quả, tôi đã quyết định."]]},{"word":"図表","reading":"ずひょう","meaning":"biểu đồ","hanViet":"ĐỒ BIỂU","lesson":21,"ex":[["図表を見て、考えました。","Tôi đã xem biểu đồ và suy nghĩ."],["この図表はよくわかります。","Biểu đồ này rất dễ hiểu."],["図表を使って、説明しました。","Tôi đã dùng biểu đồ để giải thích."],["本に図表がたくさんあります。","Trong sách có nhiều biểu đồ."],["図表を作るのは、大変です。","Làm biểu đồ rất vất vả."]]},{"word":"飲み水","reading":"のみみず","meaning":"nước uống","hanViet":"ẨM THỦY","lesson":21,"ex":[["飲み水がありません。","Không có nước uống."],["飲み水を買いました。","Tôi đã mua nước uống."],["この飲み水はきれいです。","Nước uống này sạch."],["飲み水を大切にします。","Tôi trân trọng nước uống."],["山の飲み水は冷たいです。","Nước uống ở núi lạnh."]]},{"word":"こだわり","reading":"こだわり","meaning":"cầu kỳ, câu nệ","hanViet":"","lesson":21,"ex":[["彼は料理にこだわりがあります。","Anh ấy rất cầu kỳ về món ăn."],["私は水にこだわりがあります。","Tôi rất cầu kỳ về nước."],["こだわりが強い人です。","Anh ấy là người rất câu nệ."],["彼のこだわりが料理をおいしくしました。","Sự cầu kỳ của anh ấy làm món ăn ngon hơn."],["音楽にこだわりがあります。","Tôi rất cầu kỳ về âm nhạc."]]},{"word":"深さ","reading":"ふかさ","meaning":"độ sâu","hanViet":"THÂM","lesson":21,"ex":[["この湖は深さが大きいです。","Hồ này có độ sâu lớn."],["深さを調べました。","Tôi đã kiểm tra độ sâu."],["このプールは深さが大きいです。","Hồ bơi này sâu."],["深さに気をつけてください。","Hãy chú ý đến độ sâu."],["雪の深さが大きいです。","Tuyết dày."]]},{"word":"危機感","reading":"ききかん","meaning":"cảm giác nguy cơ","hanViet":"NGUY CƠ CẢM","lesson":21,"ex":[["彼は危機感を持っています。","Anh ấy có cảm giác nguy cơ."],["危機感が強くなりました。","Cảm giác nguy cơ đã mạnh lên."],["みんなに危機感があります。","Mọi người đều có cảm giác nguy cơ."],["危機感を持って、働きます。","Tôi làm việc với cảm giác nguy cơ."],["水が少なくて、危機感があります。","Nước ít nên có cảm giác nguy cơ."]]},{"word":"糸目をつけない","reading":"いとめをつけない","meaning":"không bận tâm về (tiền ~)","hanViet":"MỊCH MỤC","lesson":21,"ex":[["彼は水に糸目をつけません。","Anh ấy không tiếc tiền cho nước."],["料理に糸目をつけない人です。","Anh ấy là người không tiếc tiền cho món ăn."],["彼女は服に糸目をつけません。","Cô ấy không tiếc tiền cho quần áo."],["音楽に糸目をつけません。","Tôi không tiếc tiền cho âm nhạc."],["子どもの教育に糸目をつけません。","Tôi không tiếc tiền cho việc học của con."]]},{"word":"通人","reading":"つうじん","meaning":"người sành sỏi, người phong lưu","hanViet":"THÔNG NHÂN","lesson":21,"ex":[["彼はお茶の通人です。","Anh ấy là người sành trà."],["通人の話はおもしろいです。","Câu chuyện của người sành sỏi rất thú vị."],["彼は音楽の通人です。","Anh ấy là người sành nhạc."],["通人はいい水を知っています。","Người sành sỏi biết nước ngon."],["その通人は料理が上手です。","Người sành sỏi đó nấu ăn giỏi."]]},{"word":"茶漬け","reading":"ちゃづけ","meaning":"món chazuke (cơm trộn với nước trà)","hanViet":"TRÀ TÍ","lesson":21,"ex":[["茶漬けを食べました。","Tôi đã ăn chazuke."],["茶漬けが好きです。","Tôi thích chazuke."],["朝、茶漬けを食べました。","Buổi sáng tôi đã ăn chazuke."],["茶漬けにお茶をかけました。","Tôi đã chan trà vào chazuke."],["彼女は茶漬けを作りました。","Cô ấy đã làm chazuke."]]},{"word":"漬物","reading":"つけもの","meaning":"dưa muối","hanViet":"TÍ VẬT","lesson":21,"ex":[["漬物を食べました。","Tôi đã ăn dưa muối."],["漬物が好きです。","Tôi thích dưa muối."],["母は漬物を作りました。","Mẹ tôi đã làm dưa muối."],["漬物と魚を食べました。","Tôi đã ăn dưa muối và cá."],["この漬物は塩の味がします。","Dưa muối này có vị muối."]]},{"word":"煎茶","reading":"せんちゃ","meaning":"trà xanh","hanViet":"TIÊN TRÀ","lesson":21,"ex":[["煎茶を飲みました。","Tôi đã uống trà xanh."],["煎茶が好きです。","Tôi thích trà xanh."],["煎茶の香りがいいです。","Hương thơm của trà xanh rất tốt."],["母は煎茶を買いました。","Mẹ tôi đã mua trà xanh."],["煎茶を飲んで、休みました。","Tôi uống trà xanh và nghỉ ngơi."]]},{"word":"飯","reading":"めし","meaning":"cơm","hanViet":"PHẠN","lesson":21,"ex":[["飯を食べました。","Tôi đã ăn cơm."],["飯が好きです。","Tôi thích cơm."],["飯を炊きました。","Tôi đã nấu cơm."],["飯と魚を食べました。","Tôi đã ăn cơm và cá."],["温かい飯がおいしいです。","Cơm nóng rất ngon."]]},{"word":"代金","reading":"だいきん","meaning":"tiền thanh toán","hanViet":"ĐẠI KIM","lesson":21,"ex":[["代金を払いました。","Tôi đã trả tiền thanh toán."],["代金が高いです。","Tiền thanh toán cao."],["代金を払ってください。","Hãy trả tiền thanh toán."],["本の代金を払いました。","Tôi đã trả tiền sách."],["代金を忘れました。","Tôi đã quên trả tiền."]]},{"word":"両","reading":"りょう","meaning":"ryo (đơn vị tiền thời Edo)","hanViet":"LƯỠNG","lesson":21,"ex":[["昔のお金は両で数えました。","Tiền ngày xưa được đếm bằng ryo."],["その本は一両でした。","Cuốn sách đó giá một ryo."],["両は昔のお金です。","Ryo là tiền ngày xưa."],["彼は二両を払いました。","Anh ấy đã trả hai ryo."],["昔、一両は大きいお金でした。","Ngày xưa, một ryo là số tiền lớn."]]},{"word":"分","reading":"ぶ","meaning":"bu (đơn vị tiền thời Edo, bằng 1/4 của ryo)","hanViet":"PHÂN","lesson":21,"ex":[["一分は両の四分の一の値段です。","Một bu có giá bằng một phần tư ryo."],["その品物は三分でした。","Món đồ đó giá ba bu."],["昔の人は分を使いました。","Người xưa đã dùng bu."],["一分のお金がありません。","Tôi không có đồng một bu."],["分は昔のお金の単位です。","Bu là đơn vị tiền ngày xưa."]]},{"word":"吟味する","reading":"ぎんみする","meaning":"xem xét kỹ lưỡng, cân nhắc kỹ rồi lựa chọn","hanViet":"NGÂM VỊ","lesson":21,"ex":[["彼は水を吟味して、選びました。","Anh ấy đã xem xét kỹ nước rồi chọn."],["買う前に、品物を吟味しました。","Trước khi mua, tôi đã xem xét kỹ món đồ."],["彼女は料理の材料を吟味します。","Cô ấy xem xét kỹ nguyên liệu nấu ăn."],["吟味して、いいものを選びます。","Xem xét kỹ rồi chọn đồ tốt."],["彼は本を吟味して、買いました。","Anh ấy đã xem xét kỹ sách rồi mua."]]},{"word":"見当たる","reading":"みあたる","meaning":"tìm thấy","hanViet":"KIẾN ĐƯƠNG","lesson":21,"ex":[["部屋の中に鍵が見当たりません。","Trong phòng không tìm thấy chìa khóa."],["探した本が見当たりました。","Tôi đã tìm thấy cuốn sách đã tìm."],["いい店が見当たりません。","Không tìm thấy cửa hàng tốt."],["近くにいい店が見当たりません。","Gần đây không tìm thấy cửa hàng tốt."],["忘れ物が見当たりました。","Tôi đã tìm thấy đồ bỏ quên."]]},{"word":"上流","reading":"じょうりゅう","meaning":"thượng nguồn","hanViet":"THƯỢNG LƯU","lesson":21,"ex":[["川の上流に行きました。","Tôi đã đến thượng nguồn sông."],["上流の水はきれいです。","Nước ở thượng nguồn sạch."],["上流で魚が泳いでいます。","Ở thượng nguồn có cá đang bơi."],["上流の町は静かです。","Thị trấn ở thượng nguồn yên tĩnh."],["川の上流は山に近いです。","Thượng nguồn sông gần núi."]]},{"word":"くむ","reading":"くむ","meaning":"múc (nước)","hanViet":"","lesson":21,"ex":[["川で水をくみました。","Tôi đã múc nước ở sông."],["池で水をくみました。","Tôi đã múc nước ở ao."],["彼は川の水をくみました。","Anh ấy đã múc nước sông."],["水をくんで、料理を作りました。","Tôi múc nước và nấu ăn."],["朝、水をくみに行きました。","Buổi sáng tôi đã đi múc nước."]]},{"word":"早飛脚","reading":"はやびきゃく","meaning":"người vận chuyển đồ nhanh (từ cổ)","hanViet":"TẢO PHI CƯỚC","lesson":21,"ex":[["昔、早飛脚が手紙を運びました。","Ngày xưa, người đưa thư nhanh đã chuyển thư."],["早飛脚は速く走りました。","Người đưa thư nhanh đã chạy nhanh."],["早飛脚が町に来ました。","Người đưa thư nhanh đã đến thị trấn."],["早飛脚の仕事は大変でした。","Công việc của người đưa thư nhanh rất vất vả."],["昔の人は早飛脚を使いました。","Người xưa đã dùng người đưa thư nhanh."]]},{"word":"仕立てる","reading":"したてる","meaning":"cử, phái đi","hanViet":"SĨ LẬP","lesson":21,"ex":[["彼は早飛脚を仕立てました。","Anh ấy đã cử người đưa thư nhanh đi."],["早飛脚を仕立てて、手紙を送りました。","Anh ấy cử người đưa thư nhanh đi để gửi thư."],["会社は人を仕立てました。","Công ty đã cử người đi."],["彼は早飛脚を仕立てて、水を運びました。","Anh ấy cử người đưa thư nhanh đi để chuyển nước."],["早飛脚を仕立てるのにお金がかかりました。","Cử người đưa thư nhanh đi tốn tiền."]]},{"word":"故","reading":"ゆえ","meaning":"vì, lý do, nguyên cớ","hanViet":"CỐ","lesson":21,"ex":[["病気の故、学校を休みました。","Vì bệnh nên tôi đã nghỉ học."],["雨の故、試合がありませんでした。","Vì mưa nên không có trận đấu."],["仕事の故、東京に行きました。","Vì công việc nên tôi đã đến Tokyo."],["天気の故、旅行を止めました。","Vì thời tiết nên tôi đã dừng chuyến du lịch."],["お金の故、買えませんでした。","Vì tiền nên tôi đã không mua được."]]},{"word":"運賃","reading":"うんちん","meaning":"phí vận chuyển","hanViet":"VẬN NHẪM","lesson":21,"ex":[["運賃が高いです。","Phí vận chuyển cao."],["運賃を払いました。","Tôi đã trả phí vận chuyển."],["荷物の運賃を払いました。","Tôi đã trả phí vận chuyển hành lý."],["運賃が安くなりました。","Phí vận chuyển đã rẻ hơn."],["運賃を調べてください。","Hãy kiểm tra phí vận chuyển."]]},{"word":"二の句もつげない","reading":"にのくもつげない","meaning":"không thốt nên lời (vì quá ngạc nhiên, xúc động hoặc bối rối)","hanViet":"NHỊ CÚ","lesson":21,"ex":[["その話を聞いて、二の句もつげませんでした。","Nghe câu chuyện đó, tôi không thốt nên lời."],["先生の話を聞いて、二の句もつげませんでした。","Nghe thầy nói, tôi không thốt nên lời."],["みんな二の句もつげませんでした。","Mọi người đều không thốt nên lời."],["彼は二の句もつげないで、帰りました。","Anh ấy không thốt nên lời mà về nhà."],["その結果に二の句もつげませんでした。","Trước kết quả đó, tôi không thốt nên lời."]]},{"word":"上水","reading":"じょうすい","meaning":"nước máy","hanViet":"THƯỢNG THỦY","lesson":21,"ex":[["上水を飲みました。","Tôi đã uống nước máy."],["上水がきれいです。","Nước máy sạch."],["上水を使って、料理を作ります。","Tôi dùng nước máy để nấu ăn."],["この町の上水はおいしいです。","Nước máy ở thị trấn này ngon."],["上水が出ません。","Nước máy không chảy ra."]]},{"word":"主流","reading":"しゅりゅう","meaning":"dòng nước chính","hanViet":"CHỦ LƯU","lesson":21,"ex":[["川の主流は速いです。","Dòng chính của sông chảy nhanh."],["主流の水はきれいです。","Nước dòng chính sạch."],["川の主流に行きました。","Tôi đã đến dòng chính của sông."],["主流と小さな川があります。","Có dòng chính và sông nhỏ."],["主流の魚が多いです。","Dòng chính có nhiều cá."]]},{"word":"清冽","reading":"せいれつ","meaning":"trong vắt","hanViet":"THANH LIỆT","lesson":21,"ex":[["清冽な水を飲みました。","Tôi đã uống nước trong vắt."],["山の水は清冽です。","Nước ở núi trong vắt."],["清冽な水が好きです。","Tôi thích nước trong vắt."],["この川の水は清冽です。","Nước sông này trong vắt."],["清冽な水でお茶を作りました。","Tôi đã pha trà bằng nước trong vắt."]]},{"word":"うたう","reading":"うたう","meaning":"ca tụng","hanViet":"","lesson":21,"ex":[["人々は名水をうたいます。","Mọi người ca tụng dòng nước nổi tiếng."],["昔の人は山をうたいました。","Người xưa đã ca tụng núi."],["歌で川の水をうたいます。","Ca tụng nước sông bằng bài hát."],["彼は日本をうたいました。","Anh ấy đã ca tụng Nhật Bản."],["歌手はふるさとをうたいます。","Ca sĩ ca tụng quê hương."]]},{"word":"名水","reading":"めいすい","meaning":"(dòng nước, suối nước…) nổi tiếng","hanViet":"DANH THỦY","lesson":21,"ex":[["この町の名水はきれいです。","Dòng nước nổi tiếng ở thị trấn này trong sạch."],["名水を飲みました。","Tôi đã uống nước nổi tiếng."],["京都の名水が好きです。","Tôi thích dòng nước nổi tiếng ở Kyoto."],["名水でお茶を作りました。","Tôi đã pha trà bằng nước nổi tiếng."],["名水の話を聞きました。","Tôi đã nghe câu chuyện về dòng nước nổi tiếng."]]},{"word":"目立つ","reading":"めだつ","meaning":"đáng chú ý, nổi bật","hanViet":"MỤC LẬP","lesson":21,"ex":[["彼の赤い服が目立ちます。","Quần áo đỏ của anh ấy nổi bật."],["その店は目立ちます。","Cửa hàng đó nổi bật."],["彼女の声が目立ちます。","Giọng cô ấy nổi bật."],["大きい看板が目立ちます。","Tấm biển lớn nổi bật."],["彼の歌が目立ちました。","Bài hát của anh ấy nổi bật."]]},{"word":"産湯","reading":"うぶゆ","meaning":"lần tắm đầu tiên cho trẻ sơ sinh","hanViet":"SẢN THANG","lesson":21,"ex":[["赤ちゃんに産湯を使いました。","Tôi đã tắm lần đầu cho em bé."],["産湯は大切です。","Lần tắm đầu tiên rất quan trọng."],["母は子どもに産湯を使いました。","Mẹ đã tắm lần đầu cho con."],["産湯の水は温かいです。","Nước tắm lần đầu ấm."],["産湯を使いましたから、子どもは寝ました。","Vì đã tắm lần đầu nên đứa trẻ đã ngủ."]]},{"word":"末期","reading":"まつご","meaning":"cuối đời","hanViet":"MẠT KỲ","lesson":21,"ex":[["彼は末期に家族と会いました。","Cuối đời, anh ấy đã gặp gia đình."],["末期の時間を大切にしました。","Tôi đã trân trọng thời gian cuối đời."],["祖父は末期に静かに過ごしました。","Cuối đời, ông tôi đã sống yên bình."],["末期に水を飲みました。","Cuối đời, anh ấy đã uống nước."],["彼の末期は静かでした。","Cuối đời của anh ấy yên bình."]]},{"word":"切る","reading":"きる","meaning":"cắt (duyên)","hanViet":"THIẾT","lesson":21,"ex":[["彼は古い関係を切りました。","Anh ấy đã cắt đứt mối quan hệ cũ."],["彼女は悪い関係を切りました。","Cô ấy đã cắt đứt mối quan hệ xấu."],["彼は会社との関係を切りました。","Anh ấy đã cắt đứt quan hệ với công ty."],["友達との関係を切りました。","Tôi đã cắt đứt quan hệ với bạn bè."],["関係を切るのは、大変です。","Cắt đứt quan hệ rất khó khăn."]]},{"word":"あこがれる","reading":"あこがれる","meaning":"ước ao, mong muốn","hanViet":"","lesson":21,"ex":[["私は子どものときから先生にあこがれています。","Tôi ngưỡng mộ thầy giáo từ khi còn nhỏ."],["妹は歌手にあこがれて、毎日歌の練習をしています。","Em gái ngưỡng mộ ca sĩ nên ngày nào cũng luyện hát."],["多くの学生が東京の大学にあこがれています。","Nhiều học sinh ao ước được vào đại học ở Tokyo."],["彼は小さいときから医者にあこがれていました。","Từ nhỏ anh ấy đã ao ước trở thành bác sĩ."],["私は山の中の静かな生活にあこがれています。","Tôi ao ước cuộc sống yên tĩnh trong núi."]]},{"word":"一方的","reading":"いっぽうてき","meaning":"mang tính một chiều","hanViet":"NHẤT PHƯƠNG ĐÍCH","lesson":21,"ex":[["一方的に話すのはよくありません。","Nói một chiều thì không tốt."],["先生は一方的な意見を言ってはいけないと話しました。","Thầy giáo nói không được đưa ra ý kiến một chiều."],["一方的に決めると、みんなが困ります。","Quyết định một chiều thì mọi người sẽ khó xử."],["彼の一方的な考えで、友達が怒りました。","Vì suy nghĩ một chiều của anh ấy mà bạn đã giận."],["両方の話を聞かないで、一方的な判断をしてはいけません。","Không được phán xét một chiều mà không nghe cả hai phía."]]},{"word":"決めつける","reading":"きめつける","meaning":"vội kết luận, quy kết, gán cho một cách chủ quan","hanViet":"QUYẾT","lesson":21,"ex":[["話を聞かないで、人を決めつけてはいけません。","Không được vội gán ghép người khác mà không nghe họ nói."],["彼は私の気持ちを自分で決めつけました。","Anh ấy tự ý áp đặt suy nghĩ của tôi."],["一度会っただけで、人を決めつけるのはよくありません。","Chỉ gặp một lần mà vội đánh giá người khác thì không tốt."],["先生は学生の失敗を決めつける前に、理由を聞きました。","Trước khi quy kết lỗi của học sinh, thầy giáo đã hỏi lý do."],["母は私が勉強していないと決めつけました。","Mẹ cho rằng tôi không học bài."]]},{"word":"あおりたてる","reading":"あおりたてる","meaning":"khuấy động, kích động, thổi bùng (lửa, cảm xúc, sóng)","hanViet":"","lesson":21,"ex":[["風が火をあおりたてて、山の火事が大きくなりました。","Gió thổi bùng lửa làm đám cháy rừng lớn hơn."],["そのニュースはみんなの気持ちをあおりたてました。","Tin tức đó đã khuấy động cảm xúc của mọi người."],["彼は友達の心配をあおりたてるような話をしました。","Anh ấy nói những lời làm nỗi lo của bạn bè thêm sôi sục."],["強い風が波をあおりたてて、船が出られなくなりました。","Gió mạnh làm sóng dâng cao nên thuyền không ra khơi được."],["歌手の歌が会場の人をあおりたてました。","Bài hát của ca sĩ đã khuấy động mọi người trong hội trường."]]},{"word":"確実","reading":"かくじつ","meaning":"chắc chắn, xác thực","hanViet":"XÁC THỰC","lesson":21,"ex":[["この電車は確実に午前九時に駅に着きます。","Chuyến tàu này chắc chắn đến ga lúc 9 giờ sáng."],["確実な情報がないので、まだ決められません。","Vì chưa có thông tin chắc chắn nên chưa quyết định được."],["彼は確実な方法で問題を解決しました。","Anh ấy đã giải quyết vấn đề bằng cách chắc chắn."],["明日の天気は確実に雨です。","Ngày mai chắc chắn trời mưa."],["この店の料理は確実においしいです。","Món ăn ở quán này chắc chắn ngon."]]},{"word":"質","reading":"しつ","meaning":"chất lượng","hanViet":"CHẤT","lesson":21,"ex":[["この店は質のいい野菜を売っています。","Cửa hàng này bán rau chất lượng tốt."],["質のいい米は少し値段が高いです。","Gạo chất lượng tốt thì giá hơi cao."],["先生は量より質が大切だと言いました。","Thầy giáo nói chất lượng quan trọng hơn số lượng."],["この服は質がよくて、長く使えます。","Quần áo này chất lượng tốt, dùng được lâu."],["質の悪い水は体によくありません。","Nước chất lượng kém không tốt cho cơ thể."]]},{"word":"落とす","reading":"おとす","meaning":"giảm (chất lượng)","hanViet":"LẠC","lesson":21,"ex":[["店が値段を落としたので、お客が増えました。","Vì cửa hàng hạ giá nên khách đã tăng lên."],["彼は仕事の質を落とさないように気をつけています。","Anh ấy cẩn thận để không làm giảm chất lượng công việc."],["風が強くて、木の葉を落としました。","Gió mạnh làm lá cây rụng."],["私は財布を電車の中に落としました。","Tôi đã đánh rơi ví trong tàu điện."],["母は声を落として、静かに話しました。","Mẹ hạ giọng nói khẽ."]]},{"word":"有数","reading":"ゆうすう","meaning":"nổi tiếng, hàng đầu (một trong số ít có danh tiếng)","hanViet":"HỮU SỐ","lesson":21,"ex":[["京都は日本有数の観光地です。","Kyoto là một trong những điểm du lịch nổi tiếng hàng đầu của Nhật Bản."],["この山は日本有数の高い山です。","Ngọn núi này là một trong những ngọn núi cao nổi tiếng nhất Nhật Bản."],["彼は日本有数のピアノの先生です。","Anh ấy là một trong những giáo viên piano hàng đầu Nhật Bản."],["この川は日本有数のきれいな川です。","Con sông này là một trong những con sông đẹp nổi tiếng nhất Nhật Bản."],["大阪は日本有数の大きな町です。","Osaka là một trong những thành phố lớn nổi tiếng nhất Nhật Bản."]]},{"word":"主食","reading":"しゅしょく","meaning":"lương thực chính (cơm, bánh mì…)","hanViet":"CHỦ THỰC","lesson":21,"ex":[["日本人の主食は米です。","Lương thực chính của người Nhật là gạo."],["私の国の主食はパンです。","Lương thực chính ở nước tôi là bánh mì."],["主食と副食のバランスが大切です。","Cân bằng giữa món chính và món phụ rất quan trọng."],["朝ごはんの主食はごはんとパンです。","Món chính của bữa sáng là cơm và bánh mì."],["主食をしっかり食べると、体が元気になります。","Ăn đủ lương thực chính thì cơ thể sẽ khỏe mạnh."]]},{"word":"炊く","reading":"たく","meaning":"nấu","hanViet":"XUY","lesson":21,"ex":[["母は毎朝ごはんを炊きます。","Mẹ nấu cơm mỗi sáng."],["私は初めて自分でごはんを炊きました。","Lần đầu tiên tôi tự nấu cơm."],["この米は水を多くして炊くといいです。","Gạo này nấu với nhiều nước thì ngon."],["父は休みの日にごはんを炊いてくれます。","Vào ngày nghỉ bố nấu cơm cho tôi."],["新しい米は少し水を少なくして炊きます。","Gạo mới thì nấu với ít nước hơn một chút."]]},{"word":"自体","reading":"じたい","meaning":"tự bản thân","hanViet":"TỰ THỂ","lesson":21,"ex":[["その考え自体が間違いです。","Bản thân suy nghĩ đó đã sai."],["問題自体は難しくありません。","Bản thân vấn đề không khó."],["この計画自体はいいですが、お金が足りません。","Bản thân kế hoạch này tốt, nhưng không đủ tiền."],["日本語自体は難しいですが、勉強は楽しいです。","Bản thân tiếng Nhật thì khó, nhưng học thì vui."],["その話自体が本当かどうかわかりません。","Không biết bản thân câu chuyện đó có thật hay không."]]},{"word":"たっぷり","reading":"たっぷり","meaning":"nhiều, đầy","hanViet":"","lesson":21,"ex":[["野菜をたっぷり食べてください。","Hãy ăn thật nhiều rau."],["きょうは時間がたっぷりあります。","Hôm nay có rất nhiều thời gian."],["母はスープをたっぷり作ってくれました。","Mẹ đã nấu thật nhiều súp cho tôi."],["この部屋には日がたっぷり入ります。","Căn phòng này có rất nhiều ánh nắng."],["私は休みの日にたっぷり寝ました。","Vào ngày nghỉ tôi đã ngủ thật nhiều."]]},{"word":"副食","reading":"ふくしょく","meaning":"món phụ","hanViet":"PHÓ THỰC","lesson":21,"ex":[["ごはんと副食を両方食べます。","Ăn cả cơm lẫn món phụ."],["きょうの副食は魚と野菜です。","Món phụ hôm nay là cá và rau."],["母はいつも副食を二つ作ります。","Mẹ lúc nào cũng làm hai món phụ."],["副食に卵と野菜を食べました。","Tôi đã ăn trứng và rau làm món phụ."],["この店の副食はとてもおいしいです。","Món phụ ở quán này rất ngon."]]},{"word":"ミソ汁","reading":"みそしる","meaning":"súp miso","hanViet":"TRẤP","lesson":21,"ex":[["朝ごはんにミソ汁を飲みます。","Bữa sáng tôi uống súp miso."],["母のミソ汁はとてもおいしいです。","Súp miso mẹ nấu rất ngon."],["ミソ汁には野菜と卵が入っています。","Trong súp miso có rau và trứng."],["私は毎朝ミソ汁を作ります。","Mỗi sáng tôi nấu súp miso."],["日本の朝ごはんにはミソ汁がよく出ます。","Bữa sáng Nhật Bản thường có súp miso."]]},{"word":"大半","reading":"たいはん","meaning":"phần lớn","hanViet":"ĐẠI BÁN","lesson":21,"ex":[["大半の学生が電車で学校に来ます。","Phần lớn học sinh đến trường bằng tàu điện."],["この町の人の大半は会社で働いています。","Phần lớn người dân thị trấn này làm việc ở công ty."],["大半の時間が勉強に使われました。","Phần lớn thời gian đã dùng cho việc học."],["会議の大半は問題の話でした。","Phần lớn cuộc họp là nói về vấn đề."],["大半の店が午前十時に開きます。","Phần lớn các cửa hàng mở cửa lúc 10 giờ sáng."]]},{"word":"銘柄米","reading":"めいがらまい","meaning":"gạo thương hiệu nổi tiếng","hanViet":"MINH BÍNH MỄ","lesson":21,"ex":[["この店は銘柄米をたくさん売っています。","Cửa hàng này bán nhiều gạo thương hiệu nổi tiếng."],["銘柄米は少し値段が高いです。","Gạo thương hiệu nổi tiếng có giá hơi cao."],["私の家では銘柄米を食べています。","Nhà tôi ăn gạo thương hiệu nổi tiếng."],["この銘柄米はとてもおいしいです。","Gạo thương hiệu này rất ngon."],["銘柄米の味は店によって違います。","Vị của gạo thương hiệu khác nhau tùy cửa hàng."]]},{"word":"とびきり","reading":"とびきり","meaning":"đặc biệt, rất tốt","hanViet":"","lesson":21,"ex":[["きょうの料理はとびきりおいしいです。","Món ăn hôm nay đặc biệt ngon."],["彼女はとびきりきれいな声で歌います。","Cô ấy hát bằng giọng đặc biệt hay."],["この店のケーキはとびきり甘いです。","Bánh ở quán này đặc biệt ngọt."],["とびきりいい天気なので、散歩に行きました。","Vì thời tiết đặc biệt đẹp nên tôi đã đi dạo."],["彼はとびきり速く走ることができます。","Anh ấy có thể chạy đặc biệt nhanh."]]},{"word":"玉露","reading":"ぎょくろ","meaning":"trà thượng hạng, trà ngon nhất","hanViet":"NGỌC LỘ","lesson":21,"ex":[["玉露は日本のお茶の中で一番高いお茶です。","Trà Gyokuro là loại trà đắt nhất trong các loại trà Nhật Bản."],["おじいさんは毎朝玉露を飲みます。","Ông tôi uống trà Gyokuro mỗi sáng."],["この店では玉露を売っています。","Cửa hàng này bán trà Gyokuro."],["玉露の味はとてもやさしいです。","Vị trà Gyokuro rất dịu."],["私は初めて玉露を飲みました。","Lần đầu tiên tôi uống trà Gyokuro."]]},{"word":"極上の","reading":"ごくじょうの","meaning":"ngon nhất, thượng hạng nhất","hanViet":"CỰC THƯỢNG","lesson":21,"ex":[["これは極上の米です。","Đây là gạo thượng hạng nhất."],["極上の味を楽しみました。","Tôi đã thưởng thức hương vị tuyệt hảo nhất."],["この店は極上の魚を出します。","Quán này phục vụ cá thượng hạng nhất."],["極上のお茶を飲むことができました。","Tôi đã được uống trà thượng hạng nhất."],["彼女の料理は極上の味です。","Món ăn cô ấy nấu có hương vị tuyệt hảo nhất."]]},{"word":"地下水","reading":"ちかすい","meaning":"nước ngầm","hanViet":"ĐỊA HẠ THỦY","lesson":21,"ex":[["この町は地下水を使っています。","Thị trấn này dùng nước ngầm."],["地下水はとてもきれいです。","Nước ngầm rất sạch."],["地下水が汚れると、みんなが困ります。","Nước ngầm mà bẩn thì mọi người sẽ gặp khó khăn."],["この村は地下水で米を作っています。","Ngôi làng này dùng nước ngầm để trồng lúa."],["地下水は雨水が地の中にしみ込んでできます。","Nước ngầm được tạo thành khi nước mưa thấm vào trong đất."]]},{"word":"良質","reading":"りょうしつ","meaning":"chất lượng tốt","hanViet":"LƯƠNG CHẤT","lesson":21,"ex":[["良質な米はおいしいごはんになります。","Gạo chất lượng tốt sẽ thành cơm ngon."],["この店は良質な野菜を売っています。","Cửa hàng này bán rau chất lượng tốt."],["良質な水が健康に大切です。","Nước chất lượng tốt rất quan trọng cho sức khỏe."],["良質な肉は少し値段が高いです。","Thịt chất lượng tốt có giá hơi cao."],["先生は良質な本を読みなさいと言いました。","Thầy giáo bảo hãy đọc sách chất lượng tốt."]]},{"word":"豊富","reading":"ほうふ","meaning":"phong phú","hanViet":"PHONG PHÚ","lesson":21,"ex":[["この町は水が豊富です。","Thị trấn này có nước phong phú."],["日本は魚の種類が豊富です。","Nhật Bản có nhiều loại cá phong phú."],["この店は野菜が豊富です。","Cửa hàng này có rau phong phú."],["彼は経験が豊富な先生です。","Anh ấy là thầy giáo giàu kinh nghiệm."],["この本には写真が豊富にあります。","Cuốn sách này có nhiều ảnh phong phú."]]},{"word":"雨水","reading":"あまみず","meaning":"nước mưa","hanViet":"VŨ THỦY","lesson":21,"ex":[["雨水は山の木にしみ込みます。","Nước mưa thấm vào cây trên núi."],["雨水は地下水になります。","Nước mưa trở thành nước ngầm."],["雨水が川に流れます。","Nước mưa chảy ra sông."],["雨水で花が元気になりました。","Nhờ nước mưa mà hoa trở nên tươi tốt."],["雨水は山の土の中を通ります。","Nước mưa đi qua đất trên núi."]]},{"word":"雪解け水","reading":"ゆきどけみず","meaning":"nước tan từ tuyết","hanViet":"TUYẾT GIẢI THỦY","lesson":21,"ex":[["春になると、雪解け水が川に流れます。","Khi xuân đến, nước tuyết tan chảy ra sông."],["雪解け水はとても冷たいです。","Nước tuyết tan rất lạnh."],["この川の水は雪解け水です。","Nước sông này là nước tuyết tan."],["雪解け水で川の水が増えます。","Nước tuyết tan làm nước sông tăng lên."],["山の雪解け水はきれいです。","Nước tuyết tan trên núi rất sạch."]]},{"word":"杉","reading":"すぎ","meaning":"cây tuyết tùng ở Nhật","hanViet":"SAM","lesson":21,"ex":[["この山には杉がたくさんあります。","Trên núi này có rất nhiều cây tuyết tùng."],["杉の木はとても大きくなります。","Cây tuyết tùng lớn lên rất to."],["杉の森を歩きました。","Tôi đã đi bộ trong rừng tuyết tùng."],["杉の木で家を作りました。","Người ta đã dùng gỗ tuyết tùng để làm nhà."],["道に杉が並んでいます。","Dọc đường có cây tuyết tùng xếp hàng."]]},{"word":"松","reading":"まつ","meaning":"cây thông","hanViet":"TÙNG","lesson":21,"ex":[["松の木は冬でも緑です。","Cây thông vẫn xanh cả mùa đông."],["この公園には松がたくさんあります。","Công viên này có rất nhiều cây thông."],["松の木の下で休みました。","Tôi đã nghỉ dưới gốc cây thông."],["松は日本の大切な木です。","Cây thông là cây quan trọng của Nhật Bản."],["松の森はとても静かです。","Rừng thông rất yên tĩnh."]]},{"word":"クヌギ","reading":"クヌギ","meaning":"cây sồi","hanViet":"","lesson":21,"ex":[["この森にはクヌギがたくさんあります。","Rừng này có rất nhiều cây sồi."],["クヌギの木は大きくて強いです。","Cây sồi to và chắc."],["クヌギの葉は秋に黄色くなります。","Lá sồi chuyển sang màu vàng vào mùa thu."],["クヌギの森を散歩しました。","Tôi đã đi dạo trong rừng sồi."],["クヌギの木の下で休みました。","Tôi đã nghỉ dưới gốc cây sồi."]]},{"word":"しみ込む","reading":"しみこむ","meaning":"thấm vào","hanViet":"","lesson":21,"ex":[["雨水が土にしみ込みます。","Nước mưa thấm vào đất."],["お茶が服にしみ込んでしまいました。","Trà đã thấm vào quần áo mất rồi."],["水が木にしみ込んで、重くなりました。","Nước thấm vào gỗ làm nó trở nên nặng."],["汗がシャツにしみ込みました。","Mồ hôi đã thấm vào áo sơ mi."],["スープの味がパンにしみ込みました。","Vị súp đã thấm vào bánh mì."]]},{"word":"常時","reading":"じょうじ","meaning":"lúc nào cũng, luôn luôn","hanViet":"THƯỜNG THỜI","lesson":21,"ex":[["この店は常時たくさんのお客が来ます。","Cửa hàng này lúc nào cũng có nhiều khách."],["この電車は常時人がたくさんいます。","Chuyến tàu này lúc nào cũng có rất nhiều người."],["彼は常時働いています。","Anh ấy lúc nào cũng làm việc."],["この水は常時流れています。","Nước này lúc nào cũng chảy."],["常時電気がついています。","Điện lúc nào cũng bật."]]},{"word":"湧く","reading":"わく","meaning":"chảy ra, phun ra","hanViet":"DŨNG","lesson":21,"ex":[["山から水が湧きます。","Nước phun ra từ núi."],["温泉がこの町に湧きます。","Suối nước nóng phun lên ở thị trấn này."],["この森からきれいな水が湧きます。","Nước sạch phun ra từ khu rừng này."],["休んだら、元気が湧いてきました。","Sau khi nghỉ ngơi, tôi thấy khỏe khoắn trở lại."],["地下から水が湧いています。","Nước đang phun ra từ dưới đất."]]},{"word":"岩石","reading":"がんせき","meaning":"đá tảng","hanViet":"NHAM THẠCH","lesson":21,"ex":[["山には大きな岩石があります。","Trên núi có tảng đá lớn."],["岩石の間から水が流れています。","Nước chảy ra từ giữa các tảng đá."],["この岩石はとても硬いです。","Tảng đá này rất cứng."],["大きな岩石が山の道にあります。","Có tảng đá lớn trên đường núi."],["岩石の下から水が湧きます。","Nước phun ra từ dưới tảng đá."]]},{"word":"入り込む","reading":"はいりこむ","meaning":"tiến vào, thâm nhập vào","hanViet":"NHẬP","lesson":21,"ex":[["水が土の中に入り込みます。","Nước thấm vào trong đất."],["風が部屋の中に入り込みました。","Gió lùa vào trong phòng."],["彼は森の中に入り込みました。","Anh ấy đã đi sâu vào trong rừng."],["雨水が岩石の間に入り込みます。","Nước mưa thấm vào giữa các tảng đá."],["日が木の間に入り込んでいます。","Ánh nắng lọt vào giữa các tán cây."]]},{"word":"リゾート開発","reading":"リゾートかいはつ","meaning":"phát triển khu nghỉ dưỡng","hanViet":"KHAI PHÁT","lesson":21,"ex":[["リゾート開発で森が小さくなりました。","Phát triển khu nghỉ dưỡng làm rừng thu hẹp lại."],["この町ではリゾート開発が進んでいます。","Ở thị trấn này, phát triển khu nghỉ dưỡng đang tiến triển."],["リゾート開発は水を汚すことがあります。","Phát triển khu nghỉ dưỡng có thể làm bẩn nước."],["リゾート開発についてみんなで話しました。","Mọi người đã cùng nhau nói về phát triển khu nghỉ dưỡng."],["リゾート開発が自然に悪い影響を与えます。","Phát triển khu nghỉ dưỡng gây ảnh hưởng xấu đến thiên nhiên."]]},{"word":"ゴルフ場","reading":"ゴルフじょう","meaning":"sân gôn","hanViet":"TRƯỜNG","lesson":21,"ex":[["山の近くにゴルフ場があります。","Gần núi có sân gôn."],["父は休みの日にゴルフ場に行きます。","Vào ngày nghỉ bố tôi đến sân gôn."],["ゴルフ場はとても広いです。","Sân gôn rất rộng."],["ゴルフ場を作るために森が切られました。","Rừng đã bị chặt để làm sân gôn."],["ゴルフ場は地下水を使っています。","Sân gôn dùng nước ngầm."]]},{"word":"伐採する","reading":"ばっさいする","meaning":"chặt, đốn","hanViet":"PHẠT THÁI","lesson":21,"ex":[["森の木を伐採してはいけません。","Không được đốn cây trong rừng."],["会社は山の木を伐採しました。","Công ty đã đốn cây trên núi."],["木を伐採すると、水が汚れます。","Đốn cây sẽ làm nước bị bẩn."],["伐採する前に、よく考えなければなりません。","Trước khi đốn cây, phải suy nghĩ kỹ."],["この国では木の伐採が問題になっています。","Ở nước này, việc đốn cây đang trở thành vấn đề."]]},{"word":"破壊する","reading":"はかいする","meaning":"phá hủy, phá hoại","hanViet":"PHÁ HOẠI","lesson":21,"ex":[["森を破壊してはいけません。","Không được phá hủy rừng."],["強い雨が道を破壊しました。","Mưa lớn đã phá hủy con đường."],["自然を破壊すると、水も汚れます。","Phá hủy thiên nhiên thì nước cũng bị bẩn."],["地震が町の家を破壊しました。","Động đất đã phá hủy nhà cửa trong thị trấn."],["開発が山の自然を破壊しています。","Việc phát triển đang phá hủy thiên nhiên trên núi."]]},{"word":"汚れる","reading":"よごれる","meaning":"(nước ngầm) bẩn","hanViet":"Ô","lesson":21,"ex":[["水が汚れると、魚が住めなくなります。","Nước mà bẩn thì cá không sống được nữa."],["雨で服が汚れました。","Quần áo bị bẩn vì mưa."],["川の水が汚れています。","Nước sông đang bị bẩn."],["手が汚れたので、洗いました。","Tay bị bẩn nên tôi đã rửa."],["地下水が汚れないように気をつけます。","Tôi cẩn thận để nước ngầm không bị bẩn."]]},{"word":"英訳する","reading":"えいやくする","meaning":"dịch sang tiếng Anh","hanViet":"ANH DỊCH","lesson":21,"ex":[["この本を英訳してください。","Hãy dịch cuốn sách này sang tiếng Anh."],["先生は日本語の文を英訳しました。","Thầy giáo đã dịch câu tiếng Nhật sang tiếng Anh."],["私は手紙を英訳することができます。","Tôi có thể dịch bức thư sang tiếng Anh."],["彼は小説を英訳する仕事をしています。","Anh ấy làm công việc dịch tiểu thuyết sang tiếng Anh."],["この歌を英訳するのは難しいです。","Dịch bài hát này sang tiếng Anh rất khó."]]},{"word":"水を差す","reading":"みずをさす","meaning":"phá đám, phá bĩnh","hanViet":"THỦY SAI","lesson":21,"ex":[["彼は楽しい話に水を差しました。","Anh ấy đã phá đám câu chuyện vui."],["みんなが喜んでいるときに水を差してはいけません。","Không được phá đám khi mọi người đang vui."],["その一言が会話に水を差しました。","Câu nói đó đã phá hỏng cuộc trò chuyện."],["彼女の話に水を差すつもりはありませんでした。","Tôi không có ý phá đám câu chuyện của cô ấy."],["楽しい食事に水を差さないでください。","Đừng phá hỏng bữa ăn vui vẻ."]]},{"word":"水を向ける","reading":"みずをむける","meaning":"gợi chuyện, khơi gợi (để đối phương nói)","hanViet":"THỦY HƯỚNG","lesson":21,"ex":[["先生は学生に水を向けて、話を聞きました。","Thầy giáo gợi chuyện để nghe học sinh nói."],["彼は友達に水を向けて、旅行の話を聞きました。","Anh ấy gợi chuyện để nghe bạn kể về chuyến du lịch."],["母は父に水を向けて、昔の話を聞きました。","Mẹ gợi chuyện để nghe bố kể chuyện ngày xưa."],["インタビューでは、まず相手に水を向けます。","Trong phỏng vấn, trước tiên hãy gợi chuyện với đối phương."],["私は田中さんに水を向けて、仕事の話を聞きました。","Tôi gợi chuyện với anh Tanaka để nghe anh ấy kể về công việc."]]},{"word":"水かけ論","reading":"みずかけろん","meaning":"tranh cãi không có hồi kết","hanViet":"THỦY LUẬN","lesson":21,"ex":[["その話は水かけ論になりました。","Câu chuyện đó đã trở thành cuộc tranh cãi không hồi kết."],["水かけ論をしても、問題は解決しません。","Tranh cãi không hồi kết thì vấn đề cũng không được giải quyết."],["二人の話は水かけ論で終わりました。","Câu chuyện của hai người kết thúc bằng tranh cãi không hồi kết."],["水かけ論にならないように、よく聞きましょう。","Hãy lắng nghe kỹ để không thành tranh cãi không hồi kết."],["会議は水かけ論になってしまいました。","Cuộc họp đã trở thành tranh cãi không hồi kết mất rồi."]]},{"word":"水入らず","reading":"みずいらず","meaning":"chỉ những người trong nhà","hanViet":"THỦY NHẬP","lesson":21,"ex":[["家族水入らずで食事をしました。","Cả gia đình quây quần ăn cơm chỉ có người nhà."],["水入らずでゆっくり話しました。","Chỉ có người nhà nên đã nói chuyện thong thả."],["友達と水入らずで旅行に行きました。","Tôi đã đi du lịch chỉ với bạn bè thân thiết."],["水入らずの時間を大切にしています。","Tôi trân trọng thời gian chỉ có người nhà."],["きょうは家族水入らずで過ごします。","Hôm nay tôi sẽ dành thời gian chỉ với gia đình."]]},{"word":"誘い水","reading":"さそいみず","meaning":"nguyên cớ","hanViet":"DỤ THỦY","lesson":21,"ex":[["その一言が誘い水になって、話が始まりました。","Câu nói đó trở thành cái cớ để câu chuyện bắt đầu."],["彼の質問が誘い水になって、みんなが話を始めました。","Câu hỏi của anh ấy trở thành gợi ý để mọi người bắt đầu nói chuyện."],["この本が誘い水になって、日本語の勉強を始めました。","Cuốn sách này là động cơ để tôi bắt đầu học tiếng Nhật."],["友達の話が誘い水になって、旅行を決めました。","Câu chuyện của bạn là gợi ý để tôi quyết định đi du lịch."],["その歌が誘い水になって、昔を思い出しました。","Bài hát đó gợi nhớ để tôi nhớ về ngày xưa."]]},{"word":"堪能する","reading":"たんのうする","meaning":"thông thạo, thành thạo","hanViet":"KHAM NĂNG","lesson":21,"ex":[["彼は英語を堪能しています。","Anh ấy thông thạo tiếng Anh."],["彼女は日本語を堪能に話します。","Cô ấy nói tiếng Nhật thành thạo."],["私は日本語を堪能したいです。","Tôi muốn thông thạo tiếng Nhật."],["先生は英語と日本語を堪能しています。","Thầy giáo thông thạo tiếng Anh và tiếng Nhật."],["彼女は英語を堪能に読むことができます。","Cô ấy có thể đọc tiếng Anh thành thạo."]]},{"word":"訳す","reading":"やくす","meaning":"dịch","hanViet":"DỊCH","lesson":21,"ex":[["この文を日本語に訳してください。","Hãy dịch câu này sang tiếng Nhật."],["私は英語の本を日本語に訳します。","Tôi dịch sách tiếng Anh sang tiếng Nhật."],["先生は難しい文を訳してくれました。","Thầy giáo đã dịch những câu khó cho tôi."],["彼は手紙を英語に訳しました。","Anh ấy đã dịch bức thư sang tiếng Anh."],["この本を訳すのは難しいです。","Dịch cuốn sách này rất khó."]]},{"word":"周辺","reading":"しゅうへん","meaning":"xung quanh","hanViet":"CHU BIÊN","lesson":21,"ex":[["学校の周辺には店がたくさんあります。","Xung quanh trường học có nhiều cửa hàng."],["駅の周辺は夜も明るいです。","Xung quanh ga tàu ban đêm cũng sáng."],["この山の周辺には川があります。","Xung quanh ngọn núi này có sông."],["家の周辺を散歩しました。","Tôi đã đi dạo xung quanh nhà."],["周辺の店は午前九時に開きます。","Các cửa hàng xung quanh mở cửa lúc 9 giờ sáng."]]},{"word":"密着する","reading":"みっちゃくする","meaning":"gắn bó mật thiết","hanViet":"MẬT TRƯỚC","lesson":21,"ex":[["この町は川と密着した生活をしています。","Thị trấn này có cuộc sống gắn bó mật thiết với sông."],["彼は地域に密着して働いています。","Anh ấy làm việc gắn bó mật thiết với địa phương."],["この店はお客に密着した仕事をします。","Cửa hàng này làm việc gắn bó mật thiết với khách hàng."],["生活は水と密着しています。","Cuộc sống gắn bó mật thiết với nước."],["彼女は地域に密着して暮らしています。","Cô ấy sống gắn bó mật thiết với địa phương."]]},{"word":"独自","reading":"どくじ","meaning":"riêng, độc đáo","hanViet":"ĐỘC TỰ","lesson":21,"ex":[["この店は独自の味があります。","Quán này có hương vị riêng độc đáo."],["日本には独自の文化があります。","Nhật Bản có văn hóa riêng độc đáo."],["彼は独自の方法で勉強しています。","Anh ấy học theo cách riêng của mình."],["この町は独自の祭りがあります。","Thị trấn này có lễ hội riêng."],["独自の考えを大切にしてください。","Hãy trân trọng suy nghĩ riêng của mình."]]},{"word":"築きあげる","reading":"きずきあげる","meaning":"xây dựng nên, hình thành","hanViet":"TRÚC","lesson":21,"ex":[["彼は長い時間で会社を築きあげました。","Anh ấy đã xây dựng công ty trong thời gian dài."],["二人は強い友達の関係を築きあげました。","Hai người đã xây dựng mối quan hệ bạn bè bền chặt."],["この町は水の文化を築きあげました。","Thị trấn này đã xây dựng nên văn hóa về nước."],["先生と学生がいい関係を築きあげました。","Thầy giáo và học sinh đã xây dựng mối quan hệ tốt."],["彼は小さい店から大きな店を築きあげました。","Anh ấy đã xây dựng cửa hàng lớn từ cửa hàng nhỏ."]]},{"word":"崩れる","reading":"くずれる","meaning":"sập, đổ","hanViet":"BĂNG","lesson":21,"ex":[["古い家が崩れました。","Ngôi nhà cũ đã sập."],["大雨で山の道が崩れました。","Mưa lớn làm đường núi bị sập."],["地震で壁が崩れました。","Động đất làm tường bị sập."],["彼の計画が崩れてしまいました。","Kế hoạch của anh ấy đã đổ vỡ mất rồi."],["雪が崩れて、道が通れなくなりました。","Tuyết sập xuống làm đường không đi được nữa."]]},{"word":"共通する","reading":"きょうつうする","meaning":"chung","hanViet":"CỘNG THÔNG","lesson":21,"ex":[["二人の意見は共通しています。","Ý kiến của hai người giống nhau."],["私の国と日本は漢字で共通しています。","Nước tôi và Nhật Bản có điểm chung là chữ Hán."],["私たちは趣味が共通しています。","Chúng tôi có sở thích chung."],["この二つの町は水で共通しています。","Hai thị trấn này có điểm chung là nước."],["彼と私は考えが共通しています。","Anh ấy và tôi có suy nghĩ giống nhau."]]},{"word":"単語","reading":"たんご","meaning":"từ đơn","hanViet":"ĐƠN NGỮ","lesson":21,"ex":[["新しい単語をたくさん覚えました。","Tôi đã nhớ nhiều từ mới."],["単語を覚えるのは楽しいです。","Học thuộc từ vựng rất vui."],["この単語の意味がわかりません。","Tôi không hiểu nghĩa của từ này."],["先生は単語のテストをしました。","Thầy giáo đã kiểm tra từ vựng."],["毎日単語を五つ勉強します。","Mỗi ngày tôi học năm từ mới."]]},{"word":"ファッション","reading":"ファッション","meaning":"thời trang","hanViet":"","lesson":21,"ex":[["彼女はファッションが好きです。","Cô ấy thích thời trang."],["東京のファッションは有名です。","Thời trang Tokyo rất nổi tiếng."],["ファッションの雑誌を読みました。","Tôi đã đọc tạp chí thời trang."],["彼のファッションはいつもきれいです。","Thời trang của anh ấy lúc nào cũng đẹp."],["ファッションについて友達と話しました。","Tôi đã nói chuyện với bạn về thời trang."]]},{"word":"横這い","reading":"よこばい","meaning":"đi ngang","hanViet":"","lesson":21,"ex":[["値段は横這いが続いています。","Giá cả tiếp tục đi ngang."],["店の数は横這いです。","Số cửa hàng vẫn đi ngang."],["人の数は横這いになっています。","Số người vẫn đi ngang."],["この町の人口は横這いです。","Dân số thị trấn này đi ngang."],["経済は横這いの状態が続いています。","Kinh tế tiếp tục trong trạng thái đi ngang."]]},{"word":"進む","reading":"すすむ","meaning":"tiến lên","hanViet":"TIẾN","lesson":21,"ex":[["仕事が早く進みました。","Công việc tiến triển nhanh."],["日本語の勉強が進んでいます。","Việc học tiếng Nhật đang tiến triển."],["電車が前に進みます。","Tàu điện tiến về phía trước."],["計画がゆっくり進んでいます。","Kế hoạch đang tiến triển chậm rãi."],["時間が進むのは速いです。","Thời gian trôi qua thật nhanh."]]},{"word":"減少する","reading":"げんしょうする","meaning":"giảm","hanViet":"GIẢM THIỂU","lesson":21,"ex":[["人口が減少しています。","Dân số đang giảm."],["雨の量が減少しました。","Lượng mưa đã giảm."],["お客の数が減少しています。","Số khách đang giảm."],["森の木が減少しています。","Cây trong rừng đang giảm đi."],["この町の店が減少しました。","Cửa hàng ở thị trấn này đã giảm đi."]]},{"word":"著しい","reading":"いちじるしい","meaning":"rõ rệt, đáng kể, nổi bật","hanViet":"TRỨ","lesson":21,"ex":[["著しい結果が出ました。","Đã có kết quả rõ rệt."],["彼の日本語は著しく上手になりました。","Tiếng Nhật của anh ấy đã tiến bộ rõ rệt."],["二つの店は著しく違います。","Hai cửa hàng khác nhau rõ rệt."],["町は著しく変わりました。","Thị trấn đã thay đổi rõ rệt."],["彼女の料理は著しくおいしくなりました。","Món ăn cô ấy nấu đã ngon lên rõ rệt."]]},{"word":"とる","reading":"とる","meaning":"dùng, ăn (bữa)","hanViet":"","lesson":21,"ex":[["朝ごはんをとります。","Tôi ăn sáng."],["私は毎日朝と昼と晩に食事をとります。","Mỗi ngày tôi ăn vào buổi sáng, trưa và tối."],["休みをとって、旅行に行きました。","Tôi đã nghỉ phép để đi du lịch."],["彼は昼ごはんをとる時間もありませんでした。","Anh ấy thậm chí không có thời gian ăn trưa."],["ゆっくり食事をとりましょう。","Hãy ăn uống thong thả nhé."]]},{"word":"個食","reading":"こしょく","meaning":"ăn một mình","hanViet":"CÁ THỰC","lesson":21,"ex":[["個食が増えています。","Việc ăn một mình đang tăng lên."],["若い人の間で個食が多くなっています。","Việc ăn một mình đang nhiều lên trong giới trẻ."],["個食は家族の会話を減らします。","Ăn một mình làm giảm trò chuyện trong gia đình."],["個食の人が多くなっています。","Số người ăn một mình đang tăng lên."],["忙しい人は個食をすることが多いです。","Người bận rộn thường ăn một mình."]]},{"word":"図","reading":"ず","meaning":"biểu đồ","hanViet":"ĐỒ","lesson":21,"ex":[["本の図を見てください。","Hãy xem hình trong sách."],["図で説明します。","Tôi sẽ giải thích bằng hình vẽ."],["この図は人口の数を表しています。","Hình này thể hiện số dân."],["図を見ると、よくわかります。","Nhìn hình thì sẽ hiểu rõ."],["先生は紙に図を書きました。","Thầy giáo đã vẽ hình lên giấy."]]},{"word":"興味深い","reading":"きょうみぶかい","meaning":"thú vị","hanViet":"HƯNG VỊ THÂM","lesson":21,"ex":[["興味深い話を聞きました。","Tôi đã nghe câu chuyện thú vị."],["この本はとても興味深いです。","Cuốn sách này rất thú vị."],["興味深い問題について考えました。","Tôi đã suy nghĩ về vấn đề thú vị."],["彼の話は興味深くて、よく聞きました。","Câu chuyện của anh ấy thú vị nên tôi đã lắng nghe kỹ."],["興味深い映画を見ました。","Tôi đã xem bộ phim thú vị."]]},{"word":"ご覧ください","reading":"ごらんください","meaning":"xin mời xem","hanViet":"LÃM","lesson":21,"ex":[["こちらをご覧ください。","Xin mời xem bên này."],["この写真をご覧ください。","Xin mời xem bức ảnh này."],["次のページをご覧ください。","Xin mời xem trang tiếp theo."],["図をご覧ください。","Xin mời xem hình vẽ."],["この地図をご覧ください。","Xin mời xem tấm bản đồ này."]]},{"word":"食育","reading":"しょくいく","meaning":"giáo dục về thực phẩm, thói quen ăn uống","hanViet":"THỰC DỤC","lesson":21,"ex":[["学校で食育をしています。","Trường học đang thực hiện giáo dục về thực phẩm."],["食育は子どもに大切です。","Giáo dục về thực phẩm rất quan trọng với trẻ em."],["食育について本を読みました。","Tôi đã đọc sách về giáo dục thực phẩm."],["母は食育に関心があります。","Mẹ quan tâm đến giáo dục thực phẩm."],["食育の授業がありました。","Đã có tiết học về giáo dục thực phẩm."]]},{"word":"白書","reading":"はくしょ","meaning":"sách trắng","hanViet":"BẠCH THƯ","lesson":21,"ex":[["白書に人口のことが書いてあります。","Sách trắng viết về dân số."],["国は白書を出しました。","Nhà nước đã công bố sách trắng."],["白書を読んで、問題がわかりました。","Đọc sách trắng, tôi đã hiểu vấn đề."],["この白書は食育について書いています。","Sách trắng này viết về giáo dục thực phẩm."],["白書の内容は難しいです。","Nội dung sách trắng rất khó."]]},{"word":"調理する","reading":"ちょうりする","meaning":"nấu ăn, chế biến","hanViet":"ĐIỀU LÝ","lesson":21,"ex":[["母は魚を調理しています。","Mẹ đang chế biến cá."],["私は野菜を調理するのが好きです。","Tôi thích chế biến rau."],["調理する前に、手を洗います。","Trước khi nấu ăn, hãy rửa tay."],["彼は学校で調理を習いました。","Anh ấy đã học nấu ăn ở trường."],["調理した料理はすぐ食べましょう。","Món ăn đã nấu xong hãy ăn ngay."]]},{"word":"聞きなれる","reading":"ききなれる","meaning":"nghe quen tai","hanViet":"VĂN","lesson":21,"ex":[["日本語を聞きなれました。","Tôi đã nghe quen tiếng Nhật."],["この歌を聞きなれています。","Tôi đã nghe quen bài hát này."],["東京の人の話に聞きなれました。","Tôi đã nghe quen cách nói chuyện của người Tokyo."],["毎日聞いていると、聞きなれます。","Nghe mỗi ngày thì sẽ nghe quen."],["彼の声に聞きなれました。","Tôi đã nghe quen giọng anh ấy."]]},{"word":"～済み","reading":"～ずみ","meaning":"~ đã (chế biến)","hanViet":"TẾ","lesson":21,"ex":[["調理済みの魚を買いました。","Tôi đã mua cá đã chế biến sẵn."],["予約済みの部屋があります。","Có phòng đã đặt trước."],["支払い済みのものをください。","Hãy đưa tôi đồ đã thanh toán."],["申し込み済みの人はここに来てください。","Người đã đăng ký xin mời đến đây."],["準備済みの料理を食べました。","Tôi đã ăn món ăn đã chuẩn bị sẵn."]]},{"word":"食材","reading":"しょくざい","meaning":"nguyên liệu nấu ăn","hanViet":"THỰC TÀI","lesson":21,"ex":[["新しい食材を買いました。","Tôi đã mua nguyên liệu nấu ăn mới."],["食材はスーパーで買います。","Nguyên liệu nấu ăn mua ở siêu thị."],["この料理の食材は魚と野菜です。","Nguyên liệu của món này là cá và rau."],["食材が新しくて、おいしいです。","Nguyên liệu tươi nên rất ngon."],["食材を切って、ごはんを作ります。","Cắt nguyên liệu rồi nấu cơm."]]},{"word":"惣菜","reading":"そうざい","meaning":"các món phụ, các món ăn kèm","hanViet":"TỔNG THÁI","lesson":21,"ex":[["スーパーで惣菜を買いました。","Tôi đã mua món ăn kèm ở siêu thị."],["惣菜はすぐに食べられます。","Món ăn kèm có thể ăn ngay."],["きょうの惣菜は野菜が多いです。","Món ăn kèm hôm nay có nhiều rau."],["母は惣菜を作ってくれました。","Mẹ đã làm món ăn kèm cho tôi."],["惣菜を買って、晩ごはんにしました。","Tôi đã mua món ăn kèm làm bữa tối."]]},{"word":"手軽","reading":"てがる","meaning":"đơn giản, dễ dàng","hanViet":"THỦ KHINH","lesson":21,"ex":[["手軽に作れる料理を教えてください。","Hãy chỉ tôi món ăn nấu đơn giản."],["この料理は手軽に作れます。","Món này nấu đơn giản."],["手軽な方法で勉強します。","Tôi học theo cách đơn giản."],["手軽に買える値段です。","Giá này mua được dễ dàng."],["手軽な服を着ています。","Tôi mặc quần áo đơn giản."]]},{"word":"外部化","reading":"がいぶか","meaning":"xu hướng ra bên ngoài","hanViet":"NGOẠI BỘ HÓA","lesson":21,"ex":[["料理の外部化が進んでいます。","Xu hướng nấu ăn bên ngoài đang tiến triển."],["食事の外部化が増えています。","Xu hướng ăn uống bên ngoài đang tăng lên."],["外部化によって、家で作る料理が減りました。","Nhờ xu hướng ra bên ngoài, món ăn nấu ở nhà đã giảm đi."],["外部化は忙しい人に便利です。","Xu hướng ra bên ngoài tiện lợi cho người bận rộn."],["調理の外部化が近年増えています。","Xu hướng chế biến bên ngoài tăng lên trong những năm gần đây."]]},{"word":"再び","reading":"ふたたび","meaning":"lại","hanViet":"TÁI","lesson":21,"ex":[["再び東京に行きたいです。","Tôi muốn đến Tokyo một lần nữa."],["彼は再び日本語の勉強を始めました。","Anh ấy đã bắt đầu học tiếng Nhật trở lại."],["再び会うことができて、よかったです。","Gặp lại nhau thật tốt."],["春が再び来ました。","Mùa xuân lại đến."],["再び同じ問題が起きました。","Vấn đề tương tự lại xảy ra."]]},{"word":"近年","reading":"きんねん","meaning":"những năm gần đây","hanViet":"CẬN NIÊN","lesson":21,"ex":[["近年、日本語を勉強する人が増えています。","Những năm gần đây, số người học tiếng Nhật đang tăng lên."],["近年、この町の人口が減っています。","Những năm gần đây, dân số thị trấn này đang giảm."],["近年、個食が増えています。","Những năm gần đây, việc ăn một mình đang tăng lên."],["近年、環境の問題が大きくなっています。","Những năm gần đây, vấn đề môi trường đang lớn lên."],["近年、東京に来る人が多くなっています。","Những năm gần đây, số người đến Tokyo đang nhiều lên."]]},{"word":"依然","reading":"いぜん","meaning":"vẫn, vẫn như trước","hanViet":"Y NHIÊN","lesson":21,"ex":[["依然問題が残っています。","Vấn đề vẫn còn tồn tại."],["彼は依然忙しいです。","Anh ấy vẫn bận rộn như trước."],["この店は依然人気があります。","Cửa hàng này vẫn được yêu thích."],["依然雨が降っています。","Trời vẫn đang mưa."],["町は依然静かです。","Thị trấn vẫn yên tĩnh như trước."]]},{"word":"形態","reading":"けいたい","meaning":"hình thức, hình thái","hanViet":"HÌNH THÁI","lesson":21,"ex":[["食事の形態が変わりました。","Hình thức ăn uống đã thay đổi."],["家族の形態が変わっています。","Hình thức gia đình đang thay đổi."],["この仕事の形態は新しいです。","Hình thức công việc này mới mẻ."],["形態を変えて、店を続けます。","Đổi hình thức để tiếp tục cửa hàng."],["町の形態がゆっくり変わっています。","Hình thái thị trấn đang thay đổi chậm rãi."]]},{"word":"様変わり","reading":"さまがわり","meaning":"thay đổi","hanViet":"DẠNG BIẾN","lesson":21,"ex":[["町は様変わりしました。","Thị trấn đã thay đổi."],["近年、この店は様変わりしました。","Những năm gần đây, cửa hàng này đã thay đổi."],["食事の様変わりが見られます。","Có thể thấy sự thay đổi trong ăn uống."],["彼の生活は様変わりしました。","Cuộc sống của anh ấy đã thay đổi."],["様変わりした町を歩きました。","Tôi đã đi bộ trong thị trấn đã thay đổi."]]},{"word":"受講する","reading":"じゅこうする","meaning":"nghe giảng","hanViet":"THỤ GIẢNG","lesson":21,"ex":[["日本語の授業を受講しています。","Tôi đang tham gia lớp học tiếng Nhật."],["彼は大学で経済を受講しました。","Anh ấy đã học kinh tế ở đại học."],["食育の授業を受講しました。","Tôi đã tham gia lớp học về giáo dục thực phẩm."],["受講する学生が増えています。","Số học sinh tham gia lớp học đang tăng lên."],["私は来年その授業を受講します。","Năm sau tôi sẽ tham gia lớp học đó."]]},{"word":"気になる","reading":"きになる","meaning":"để ý, lưu tâm","hanViet":"KHÍ","lesson":21,"ex":[["天気が気になります。","Tôi lo lắng về thời tiết."],["彼の病気が気になります。","Tôi lo lắng về bệnh của anh ấy."],["この店の料理が気になります。","Tôi tò mò về món ăn ở quán này."],["子どもの勉強が気になります。","Tôi lo lắng về việc học của con."],["値段が気になるので、店で聞きました。","Vì lo lắng về giá nên tôi đã hỏi ở cửa hàng."]]},{"word":"囲む","reading":"かこむ","meaning":"quây quần (bàn ăn)","hanViet":"VI","lesson":21,"ex":[["家族でテーブルを囲みました。","Cả gia đình quây quần bên bàn."],["みんなでテーブルを囲んで、ごはんを食べました。","Mọi người quây quần bên bàn ăn cơm."],["山が町を囲んでいます。","Núi bao quanh thị trấn."],["友達が私を囲んで、話しました。","Bạn bè vây quanh tôi nói chuyện."],["木が家を囲んでいます。","Cây bao quanh ngôi nhà."]]},{"word":"回答する","reading":"かいとうする","meaning":"trả lời","hanViet":"HỒI ĐÁP","lesson":21,"ex":[["質問に回答してください。","Hãy trả lời câu hỏi."],["彼はアンケートに回答しました。","Anh ấy đã trả lời bảng khảo sát."],["学生は先生の質問に回答しました。","Học sinh đã trả lời câu hỏi của thầy giáo."],["回答する前に、よく考えてください。","Trước khi trả lời, hãy suy nghĩ kỹ."],["私はメールで回答しました。","Tôi đã trả lời bằng email."]]},{"word":"～人中～人","reading":"～にんちゅう～にん","meaning":"trong số ~ người, có ~ người","hanViet":"NHÂN TRUNG NHÂN","lesson":21,"ex":[["十人中三人が電車で会社へ行きます。","Trong số mười người, có ba người đi làm bằng tàu điện."],["五人中二人が日本語を勉強しています。","Trong số năm người, có hai người đang học tiếng Nhật."],["十人中八人がこの本を読みました。","Trong số mười người, có tám người đã đọc cuốn sách này."],["四人中一人が東京へ旅行しました。","Trong số bốn người, có một người đã đi du lịch Tokyo."],["百人中九十人がこの映画を見ました。","Trong số một trăm người, có chín mươi người đã xem bộ phim này."]]},{"word":"上昇する","reading":"じょうしょうする","meaning":"tăng lên","hanViet":"THƯỢNG THĂNG","lesson":21,"ex":[["物価が上昇しています。","Giá cả đang tăng lên."],["値段が上昇しました。","Giá đã tăng lên."],["去年、ガスの値段が上昇しました。","Năm ngoái, giá gas đã tăng lên."],["人口が上昇しています。","Dân số đang tăng lên."],["給料が上昇しました。","Lương đã tăng lên."]]},{"word":"就労する","reading":"しゅうろうする","meaning":"làm việc, lao động","hanViet":"TỰU LAO","lesson":21,"ex":[["たくさんの人が会社で就労しています。","Rất nhiều người đang làm việc ở công ty."],["大学生が夏に就労します。","Sinh viên đại học làm việc vào mùa hè."],["東京で就労したいです。","Tôi muốn làm việc ở Tokyo."],["学校を卒業して、会社で就労します。","Sau khi tốt nghiệp trường học, tôi làm việc ở công ty."],["毎日八時間就労します。","Tôi làm việc tám tiếng mỗi ngày."]]},{"word":"訪日する","reading":"ほうにちする","meaning":"đến thăm Nhật Bản","hanViet":"PHỎNG NHẬT","lesson":21,"ex":[["友達が今年訪日します。","Bạn tôi sẽ đến thăm Nhật Bản trong năm nay."],["たくさんの人が毎年訪日します。","Rất nhiều người đến thăm Nhật Bản mỗi năm."],["山田さんが来年訪日します。","Anh Yamada sẽ đến thăm Nhật Bản vào năm sau."],["田中さんの友達が先月訪日しました。","Bạn của anh Tanaka đã đến thăm Nhật Bản vào tháng trước."],["春にたくさんの人が訪日します。","Vào mùa xuân, rất nhiều người đến thăm Nhật Bản."]]},{"word":"推移する","reading":"すいいする","meaning":"biến đổi","hanViet":"THÔI DI","lesson":21,"ex":[["人口が推移しています。","Dân số đang biến đổi."],["値段が去年から推移しました。","Giá cả đã biến đổi từ năm ngoái."],["進学率が推移しています。","Tỷ lệ học lên đang biến đổi."],["経済が推移しています。","Kinh tế đang biến đổi."],["この町の人口の推移を調べます。","Tôi tìm hiểu sự biến đổi dân số của thị trấn này."]]},{"word":"キャンペーン","reading":"キャンペーン","meaning":"chiến dịch","hanViet":"","lesson":21,"ex":[["店で新しいキャンペーンがあります。","Ở cửa hàng đang có chiến dịch mới."],["このキャンペーンは今月までです。","Chiến dịch này kéo dài đến hết tháng này."],["キャンペーンで値段が安くなりました。","Nhờ chiến dịch mà giá đã rẻ đi."],["テレビでキャンペーンを見ました。","Tôi đã xem chiến dịch trên ti vi."],["キャンペーンは来週終わります。","Chiến dịch sẽ kết thúc vào tuần sau."]]},{"word":"円安","reading":"えんやす","meaning":"đồng yên rẻ","hanViet":"VIÊN AN","lesson":21,"ex":[["円安が続いています。","Đồng yên rẻ vẫn đang tiếp diễn."],["円安で品物の値段が上がりました。","Vì đồng yên rẻ nên giá hàng hóa đã tăng."],["円安になると、旅行が高くなります。","Khi đồng yên rẻ đi, du lịch sẽ đắt hơn."],["円安について新聞で読みました。","Tôi đã đọc về đồng yên rẻ trên báo."],["円安で日本へ旅行する人が増えました。","Vì đồng yên rẻ nên số người đi du lịch Nhật Bản đã tăng."]]},{"word":"最多","reading":"さいた","meaning":"nhiều nhất, đông nhất","hanViet":"TỐI ĐA","lesson":21,"ex":[["今年は旅行する人が最多です。","Năm nay, số người đi du lịch là nhiều nhất."],["最多の人が夏にこの町へ来ます。","Đông người nhất đến thị trấn này vào mùa hè."],["今年は雨の日が最多でした。","Năm nay, số ngày mưa là nhiều nhất."],["この映画を見た人が今年最多です。","Số người xem bộ phim này là nhiều nhất trong năm nay."],["今年はこの本を読む人が最多です。","Năm nay, số người đọc cuốn sách này là nhiều nhất."]]},{"word":"新型","reading":"しんがた","meaning":"loại mới","hanViet":"TÂN HÌNH","lesson":21,"ex":[["新型の車を買いました。","Tôi đã mua chiếc xe loại mới."],["新型の電話が高いです。","Điện thoại loại mới thì đắt."],["この新型のパソコンが速いです。","Chiếc máy tính loại mới này chạy nhanh."],["新型の電車が走っています。","Tàu điện loại mới đang chạy."],["新型の薬ができました。","Thuốc loại mới đã được làm ra."]]},{"word":"増減する","reading":"ぞうげんする","meaning":"tăng giảm","hanViet":"TĂNG GIẢM","lesson":21,"ex":[["人口が増減します。","Dân số tăng giảm."],["値段が毎日増減します。","Giá cả tăng giảm mỗi ngày."],["電気の使用量が増減します。","Lượng điện sử dụng tăng giảm."],["学生の数が増減します。","Số lượng học sinh tăng giảm."],["今年、来る人の数が増減しました。","Trong năm nay, số người đến đã tăng giảm."]]},{"word":"外的","reading":"がいてき","meaning":"bên ngoài","hanViet":"NGOẠI ĐÍCH","lesson":21,"ex":[["外的な原因があります。","Có nguyên nhân bên ngoài."],["外的な影響で値段が上がりました。","Vì ảnh hưởng từ bên ngoài nên giá đã tăng."],["外的な要因を調べます。","Tôi tìm hiểu các yếu tố bên ngoài."],["外的な力で物が壊れました。","Đồ vật đã bị hỏng vì lực tác động từ bên ngoài."],["外的な問題があります。","Có vấn đề từ bên ngoài."]]},{"word":"要因","reading":"よういん","meaning":"nguyên nhân","hanViet":"YẾU NHÂN","lesson":21,"ex":[["大きな要因は電気の値段です。","Nguyên nhân lớn là giá điện."],["値段が上がった要因は円安です。","Nguyên nhân khiến giá tăng là đồng yên rẻ."],["要因を調べることが大切です。","Việc tìm hiểu nguyên nhân là quan trọng."],["要因はいくつもあります。","Có rất nhiều nguyên nhân."],["この問題の要因は天気です。","Nguyên nhân của vấn đề này là thời tiết."]]},{"word":"信頼性","reading":"しんらいせい","meaning":"tính tin cậy","hanViet":"TÍN LẠI TÍNH","lesson":21,"ex":[["この会社の信頼性が高いです。","Tính tin cậy của công ty này cao."],["信頼性が高い情報を選びます。","Tôi chọn thông tin có tính tin cậy cao."],["新聞の信頼性が大切です。","Tính tin cậy của báo chí là quan trọng."],["このデータの信頼性が低いです。","Tính tin cậy của dữ liệu này thấp."],["信頼性を調べることが大切です。","Việc kiểm tra tính tin cậy là quan trọng."]]},{"word":"入手する","reading":"にゅうしゅする","meaning":"có được","hanViet":"NHẬP THỦ","lesson":21,"ex":[["新しい本を入手しました。","Tôi đã có được cuốn sách mới."],["情報を入手しました。","Tôi đã có được thông tin."],["入手した本を読みました。","Tôi đã đọc cuốn sách có được."],["インターネットで情報を入手することができます。","Tôi có thể có được thông tin trên mạng."],["この本をやっと入手しました。","Cuối cùng tôi đã có được cuốn sách này."]]},{"word":"世帯","reading":"せたい","meaning":"hộ gia đình","hanViet":"THẾ ĐÁI","lesson":21,"ex":[["この町にはたくさんの世帯があります。","Thị trấn này có rất nhiều hộ gia đình."],["一つの世帯に四人が住んでいます。","Một hộ gia đình có bốn người sinh sống."],["世帯の数が増えました。","Số hộ gia đình đã tăng lên."],["一人で住む世帯が増えています。","Số hộ gia đình sống một mình đang tăng lên."],["世帯によって電気の使用量が変わります。","Lượng điện sử dụng thay đổi tùy theo hộ gia đình."]]},{"word":"進学率","reading":"しんがくりつ","meaning":"tỷ lệ học lên","hanViet":"TIẾN HỌC SUẤT","lesson":21,"ex":[["進学率が高いです。","Tỷ lệ học lên cao."],["この町の進学率が上がりました。","Tỷ lệ học lên của thị trấn này đã tăng."],["進学率が去年より高くなりました。","Tỷ lệ học lên đã cao hơn năm ngoái."],["進学率を調べました。","Tôi đã tìm hiểu tỷ lệ học lên."],["進学率が毎年上がっています。","Tỷ lệ học lên đang tăng lên mỗi năm."]]},{"word":"保有台数","reading":"ほゆうだいすう","meaning":"số xe đăng ký sở hữu","hanViet":"BẢO HỮU ĐÀI SỐ","lesson":21,"ex":[["車の保有台数が増えました。","Số xe đăng ký sở hữu đã tăng lên."],["この町の車の保有台数を調べました。","Tôi đã tìm hiểu số xe đăng ký sở hữu của thị trấn này."],["保有台数が去年より増えました。","Số xe đăng ký sở hữu đã tăng hơn năm ngoái."],["一つの世帯の車の保有台数は二台です。","Số xe đăng ký sở hữu của một hộ gia đình là hai chiếc."],["保有台数が多い町です。","Đây là thị trấn có số xe đăng ký sở hữu nhiều."]]},{"word":"得る","reading":"える","meaning":"được","hanViet":"ĐẮC","lesson":21,"ex":[["新しい知識を得ました。","Tôi đã có được kiến thức mới."],["この仕事で経験を得ました。","Tôi đã có được kinh nghiệm nhờ công việc này."],["本から情報を得ることができます。","Tôi có thể có được thông tin từ sách."],["友達から大切な意見を得ました。","Tôi đã nhận được ý kiến quan trọng từ bạn bè."],["旅行で新しい経験を得ました。","Tôi đã có được trải nghiệm mới nhờ chuyến du lịch."]]},{"word":"よしあし","reading":"よしあし","meaning":"điểm tốt và xấu","hanViet":"","lesson":21,"ex":[["よしあしを考えてから決めます。","Tôi suy nghĩ điểm tốt và xấu rồi mới quyết định."],["この方法のよしあしがわかりますか。","Bạn có hiểu điểm tốt và xấu của cách này không?"],["よしあしを友達と話します。","Tôi nói chuyện với bạn bè về điểm tốt và xấu."],["よしあしをよく考えました。","Tôi đã suy nghĩ kỹ về điểm tốt và xấu."],["新しい方法のよしあしを調べます。","Tôi tìm hiểu điểm tốt và xấu của cách mới."]]},{"word":"名医","reading":"めいい","meaning":"danh y, bác sĩ nổi tiếng","hanViet":"DANH Y","lesson":21,"ex":[["あの病院に名医がいます。","Ở bệnh viện kia có danh y."],["名医に会いました。","Tôi đã gặp danh y."],["田中さんは有名な名医です。","Anh Tanaka là danh y nổi tiếng."],["名医の話を聞きました。","Tôi đã nghe câu chuyện của danh y."],["この町の名医がテレビに出ました。","Danh y của thị trấn này đã xuất hiện trên ti vi."]]},{"word":"けち","reading":"けち","meaning":"keo kiệt","hanViet":"","lesson":21,"ex":[["田中さんはけちです。","Anh Tanaka keo kiệt."],["けちな人はお金を使いません。","Người keo kiệt không dùng tiền."],["友達にけちだと言われました。","Tôi bị bạn bè nói là keo kiệt."],["けちな生活をしています。","Tôi đang sống keo kiệt."],["あの人はけちで有名です。","Người kia nổi tiếng keo kiệt."]]},{"word":"不器用","reading":"ぶきよう","meaning":"hậu đậu, vụng về","hanViet":"BẤT KHÍ DỤNG","lesson":21,"ex":[["私は不器用です。","Tôi vụng về."],["不器用な人は料理が難しいです。","Người vụng về thấy nấu ăn khó."],["田中さんは手が不器用です。","Anh Tanaka vụng tay."],["不器用でも練習すれば上手になります。","Dù vụng về, nếu luyện tập thì sẽ giỏi lên."],["不器用な私でもこの本は読めます。","Dù vụng về như tôi cũng đọc được cuốn sách này."]]},{"word":"俳句","reading":"はいく","meaning":"thơ Haiku","hanViet":"BÀI CÚ","lesson":21,"ex":[["俳句を作りました。","Tôi đã làm thơ haiku."],["俳句を読むのが好きです。","Tôi thích đọc thơ haiku."],["学校で俳句を習いました。","Tôi đã học thơ haiku ở trường."],["俳句には季語が必要です。","Thơ haiku cần có từ chỉ mùa."],["田中さんの俳句が上手です。","Thơ haiku của anh Tanaka rất hay."]]},{"word":"節電する","reading":"せつでんする","meaning":"tiết kiệm điện","hanViet":"TIẾT ĐIỆN","lesson":21,"ex":[["毎日節電しています。","Tôi tiết kiệm điện mỗi ngày."],["夏に節電することが大切です。","Việc tiết kiệm điện vào mùa hè là quan trọng."],["電気をあまり使わないで節電します。","Tôi tiết kiệm điện bằng cách dùng ít điện."],["家族みんなで節電します。","Cả gia đình cùng tiết kiệm điện."],["節電して電気の使用量が減りました。","Nhờ tiết kiệm điện mà lượng điện sử dụng đã giảm."]]},{"word":"使用量","reading":"しようりょう","meaning":"lượng sử dụng","hanViet":"SỬ DỤNG LƯỢNG","lesson":21,"ex":[["電気の使用量が増えました。","Lượng điện sử dụng đã tăng lên."],["水の使用量が減りました。","Lượng nước sử dụng đã giảm."],["使用量を毎月調べます。","Tôi kiểm tra lượng sử dụng mỗi tháng."],["ガスの使用量が多いです。","Lượng gas sử dụng nhiều."],["夏は電気の使用量が多くなります。","Vào mùa hè, lượng điện sử dụng trở nên nhiều hơn."]]},{"word":"報道する","reading":"ほうどうする","meaning":"đưa tin","hanViet":"BÁO ĐẠO","lesson":21,"ex":[["新聞が事件を報道しました。","Báo đã đưa tin về vụ việc."],["テレビが事故を報道しました。","Ti vi đã đưa tin về vụ tai nạn."],["この話はまだ報道されていません。","Câu chuyện này vẫn chưa được đưa tin."],["新聞で読んだ話がテレビでも報道されました。","Câu chuyện tôi đọc trên báo cũng được đưa tin trên ti vi."],["報道する前に話を調べます。","Tôi tìm hiểu câu chuyện trước khi đưa tin."]]},{"word":"出産する","reading":"しゅっさんする","meaning":"sinh sản","hanViet":"XUẤT SẢN","lesson":21,"ex":[["友達が出産しました。","Bạn tôi đã sinh con."],["病院で出産しました。","Tôi đã sinh con ở bệnh viện."],["来月出産します。","Tôi sẽ sinh con vào tháng sau."],["出産してから、家で休みます。","Sau khi sinh con, tôi nghỉ ngơi ở nhà."],["出産する日が近くなりました。","Ngày sinh con đã đến gần."]]},{"word":"口が悪い","reading":"くちがわるい","meaning":"thối mồm, ác miệng","hanViet":"KHẨU ÁC","lesson":21,"ex":[["田中さんは口が悪いです。","Anh Tanaka ác miệng."],["口が悪い人は友達が少ないです。","Người ác miệng thì ít bạn bè."],["口が悪いと言われました。","Tôi bị nói là ác miệng."],["口が悪いけれど、仕事は上手です。","Dù ác miệng nhưng công việc thì giỏi."],["口が悪くて、友達が少なくなりました。","Vì ác miệng nên bạn bè đã ít đi."]]},{"word":"評論家","reading":"ひょうろんか","meaning":"nhà phê bình","hanViet":"BÌNH LUẬN GIA","lesson":21,"ex":[["評論家が映画について話しました。","Nhà phê bình đã nói về bộ phim."],["有名な評論家が本を書きました。","Nhà phê bình nổi tiếng đã viết sách."],["評論家がこの本を読んで、意見を言いました。","Nhà phê bình đã đọc cuốn sách này và nêu ý kiến."],["テレビに評論家が出ました。","Nhà phê bình đã xuất hiện trên ti vi."],["評論家の意見を新聞で読みました。","Tôi đã đọc ý kiến của nhà phê bình trên báo."]]},{"word":"基本","reading":"きほん","meaning":"căn bản","hanViet":"CƠ BẢN","lesson":21,"ex":[["基本が大切です。","Căn bản là quan trọng."],["基本を覚えることが大切です。","Việc nhớ căn bản là quan trọng."],["日本語の基本を習いました。","Tôi đã học căn bản tiếng Nhật."],["基本から勉強します。","Tôi học từ căn bản."],["スポーツの基本は毎日練習することです。","Căn bản của thể thao là luyện tập mỗi ngày."]]},{"word":"列","reading":"れつ","meaning":"hàng","hanViet":"LIỆT","lesson":21,"ex":[["店の前に長い列ができました。","Trước cửa hàng đã có hàng dài."],["列に並んで待ちます。","Tôi xếp hàng và chờ."],["列が短くなりました。","Hàng đã ngắn đi."],["長い列を見て、帰りました。","Thấy hàng dài, tôi đã về."],["列の最後に立ちます。","Tôi đứng ở cuối hàng."]]},{"word":"積み重ねる","reading":"つみかさねる","meaning":"tích lũy, chồng chất","hanViet":"TÍCH TRỌNG","lesson":21,"ex":[["本を積み重ねました。","Tôi đã chồng sách lên nhau."],["経験を積み重ねることが大切です。","Việc tích lũy kinh nghiệm là quan trọng."],["毎日練習して、経験を積み重ねます。","Tôi luyện tập mỗi ngày và tích lũy kinh nghiệm."],["毎日練習して、知識を積み重ねます。","Tôi luyện tập mỗi ngày và tích lũy kiến thức."],["長い時間練習して、技を積み重ねました。","Tôi đã luyện tập trong thời gian dài và tích lũy kỹ thuật."]]},{"word":"それなり","reading":"それなり","meaning":"tương ứng với điều đó","hanViet":"","lesson":21,"ex":[["それなりに難しいです。","Khó ở mức tương xứng."],["それなりの理由があります。","Có lý do riêng của nó."],["それなりのお金が必要です。","Cần một số tiền tương xứng."],["それなりに上手になりました。","Tôi đã giỏi lên ở mức tương xứng."],["それなりの時間がかかります。","Tốn một khoảng thời gian tương xứng."]]},{"word":"年輪","reading":"ねんりん","meaning":"vòng tuổi (vòng gỗ) của cây","hanViet":"NIÊN LUÂN","lesson":21,"ex":[["木の年輪を見ました。","Tôi đã nhìn vòng tuổi của cây."],["年輪から木の歴史がわかります。","Từ vòng tuổi có thể hiểu lịch sử của cây."],["木を切ると、年輪が見えます。","Khi chặt cây, có thể thấy vòng tuổi."],["大きな木にはたくさんの年輪があります。","Cây lớn có rất nhiều vòng tuổi."],["長い経験がその人の年輪です。","Kinh nghiệm lâu dài là vòng tuổi của người đó."]]},{"word":"化粧する","reading":"けしょうする","meaning":"trang điểm","hanViet":"HÓA TRANG","lesson":21,"ex":[["毎朝化粧します。","Tôi trang điểm mỗi sáng."],["化粧して会社へ行きます。","Tôi trang điểm rồi đi làm."],["化粧するのが好きです。","Tôi thích trang điểm."],["化粧する時間がありません。","Tôi không có thời gian trang điểm."],["田中さんは化粧が上手です。","Chị Tanaka trang điểm giỏi."]]},{"word":"判断する","reading":"はんだんする","meaning":"phán đoán","hanViet":"PHÁN ĐOẠN","lesson":21,"ex":[["判断することが難しいです。","Việc phán đoán thì khó."],["よく考えて判断します。","Tôi suy nghĩ kỹ rồi phán đoán."],["一人で判断することができません。","Tôi không thể tự mình phán đoán."],["判断する前に情報を調べます。","Tôi tìm hiểu thông tin trước khi phán đoán."],["大切な判断をすることが多いです。","Tôi thường phải đưa ra phán đoán quan trọng."]]},{"word":"購入する","reading":"こうにゅうする","meaning":"mua","hanViet":"CẤU NHẬP","lesson":21,"ex":[["新しいパソコンを購入しました。","Tôi đã mua máy tính mới."],["インターネットで本を購入します。","Tôi mua sách trên mạng."],["購入する前に値段を調べます。","Tôi kiểm tra giá trước khi mua."],["この服を購入しました。","Tôi đã mua bộ quần áo này."],["購入した本を読みました。","Tôi đã đọc cuốn sách đã mua."]]},{"word":"検討する","reading":"けんとうする","meaning":"xem xét","hanViet":"KIỂM THẢO","lesson":21,"ex":[["計画を検討します。","Tôi xem xét kế hoạch."],["新しい方法を検討しています。","Tôi đang xem xét cách mới."],["検討してから、決めます。","Tôi xem xét rồi mới quyết định."],["みんなで検討します。","Mọi người cùng xem xét."],["検討することが多いです。","Tôi thường phải xem xét nhiều việc."]]},{"word":"災害時","reading":"さいがいじ","meaning":"khi xảy ra thảm hoạ","hanViet":"TAI HẠI THỜI","lesson":21,"ex":[["災害時は電気が止まります。","Khi xảy ra thảm họa, điện sẽ ngừng."],["災害時に使う物を持ちます。","Tôi mang theo đồ dùng khi xảy ra thảm họa."],["災害時のために水を買います。","Tôi mua nước để dùng khi xảy ra thảm họa."],["災害時は近くの学校へ行きます。","Khi xảy ra thảm họa, tôi đến trường học gần đó."],["災害時に電話が使えません。","Khi xảy ra thảm họa, không dùng được điện thoại."]]},{"word":"安全基準","reading":"あんぜんきじゅん","meaning":"tiêu chuẩn an toàn","hanViet":"AN TOÀN CƠ CHUẨN","lesson":21,"ex":[["安全基準を守ります。","Tôi tuân thủ tiêu chuẩn an toàn."],["この建物の安全基準が高いです。","Tiêu chuẩn an toàn của tòa nhà này cao."],["安全基準について調べました。","Tôi đã tìm hiểu về tiêu chuẩn an toàn."],["安全基準が大切です。","Tiêu chuẩn an toàn là quan trọng."],["新しい安全基準ができました。","Tiêu chuẩn an toàn mới đã được đặt ra."]]},{"word":"責任","reading":"せきにん","meaning":"trách nhiệm","hanViet":"TRÁCH NHIỆM","lesson":21,"ex":[["責任がある仕事です。","Đây là công việc có trách nhiệm."],["責任が重いです。","Trách nhiệm nặng nề."],["責任を持って仕事をします。","Tôi làm việc với tinh thần trách nhiệm."],["責任を取ることが大切です。","Việc chịu trách nhiệm là quan trọng."],["先生の責任が大きいです。","Trách nhiệm của thầy giáo rất lớn."]]},{"word":"遺産","reading":"いさん","meaning":"di sản","hanViet":"DI SẢN","lesson":21,"ex":[["世界の遺産を守ります。","Tôi bảo vệ di sản của thế giới."],["大切な遺産があります。","Có di sản quan trọng."],["遺産について勉強します。","Tôi học về di sản."],["京都にはたくさんの遺産があります。","Kyoto có rất nhiều di sản."],["遺産を子どもに伝えます。","Tôi truyền di sản lại cho trẻ em."]]},{"word":"外交官","reading":"がいこうかん","meaning":"nhà ngoại giao","hanViet":"NGOẠI GIAO QUAN","lesson":21,"ex":[["外交官になりたいです。","Tôi muốn trở thành nhà ngoại giao."],["田中さんは外交官です。","Anh Tanaka là nhà ngoại giao."],["外交官の仕事は難しいです。","Công việc của nhà ngoại giao thì khó."],["外交官が東京で働きます。","Nhà ngoại giao làm việc ở Tokyo."],["外交官になるために勉強します。","Tôi học để trở thành nhà ngoại giao."]]},{"word":"きずな","reading":"きずな","meaning":"sự gắn kết, sợi dây kết nối","hanViet":"","lesson":21,"ex":[["家族のきずなが大切です。","Sự gắn kết của gia đình là quan trọng."],["友達とのきずなを深めます。","Tôi làm sâu sắc thêm sự gắn kết với bạn bè."],["きずなが強いです。","Sự gắn kết rất mạnh mẽ."],["きずなを大切にします。","Tôi trân trọng sự gắn kết."],["町の人とのきずなが深くなりました。","Sự gắn kết với người dân trong thị trấn đã sâu sắc hơn."]]},{"word":"深める","reading":"ふかめる","meaning":"làm sâu sắc thêm","hanViet":"THÂM","lesson":21,"ex":[["知識を深めます。","Tôi làm sâu sắc thêm kiến thức."],["家族のきずなを深めます。","Tôi làm sâu sắc thêm sự gắn kết của gia đình."],["日本語の勉強を深めたいです。","Tôi muốn đào sâu việc học tiếng Nhật."],["友達とのきずなを深めました。","Tôi đã làm sâu sắc thêm sự gắn kết với bạn bè."],["本を読んで、知識を深めました。","Tôi đọc sách và đã làm sâu sắc thêm kiến thức."]]},{"word":"母語","reading":"ぼご","meaning":"tiếng mẹ đẻ","hanViet":"MẪU NGỮ","lesson":21,"ex":[["私の母語は日本語です。","Tiếng mẹ đẻ của tôi là tiếng Nhật."],["母語で話すことができます。","Tôi có thể nói bằng tiếng mẹ đẻ."],["母語が日本語ではない人と話します。","Tôi nói chuyện với người có tiếng mẹ đẻ không phải tiếng Nhật."],["母語を大切にします。","Tôi trân trọng tiếng mẹ đẻ."],["母語の本を読みます。","Tôi đọc sách bằng tiếng mẹ đẻ."]]},{"word":"コレステロール","reading":"コレステロール","meaning":"cholesterol, mỡ trong máu","hanViet":"","lesson":21,"ex":[["コレステロールが高いです。","Cholesterol cao."],["コレステロールの値が高いです。","Chỉ số cholesterol cao."],["コレステロールが高いので、野菜を食べます。","Vì cholesterol cao nên tôi ăn rau."],["病院でコレステロールを調べました。","Tôi đã kiểm tra cholesterol ở bệnh viện."],["コレステロールについて医者に聞きました。","Tôi đã hỏi bác sĩ về cholesterol."]]},{"word":"値","reading":"ち","meaning":"giá trị, con số (đo được) nói chung","hanViet":"TRỊ","lesson":21,"ex":[["値が高いです。","Chỉ số cao."],["値が上がりました。","Chỉ số đã tăng lên."],["値が下がりました。","Chỉ số đã giảm xuống."],["値が変わりました。","Chỉ số đã thay đổi."],["コレステロールの値を見ます。","Tôi xem chỉ số cholesterol."]]},{"word":"莫大","reading":"ばくだい","meaning":"rất nhiều, rất lớn","hanViet":"MẠC ĐẠI","lesson":21,"ex":[["莫大なお金が必要です。","Cần số tiền rất lớn."],["莫大な時間がかかります。","Tốn rất nhiều thời gian."],["莫大な数の人が来ました。","Số người rất lớn đã đến."],["莫大な電気を使います。","Tôi dùng lượng điện rất lớn."],["莫大な仕事があります。","Có khối lượng công việc rất lớn."]]},{"word":"社会貢献","reading":"しゃかいこうけん","meaning":"đóng góp cho xã hội","hanViet":"XÃ HỘI CỐNG HIẾN","lesson":21,"ex":[["社会貢献が大切です。","Đóng góp cho xã hội là quan trọng."],["会社が社会貢献をしています。","Công ty đang đóng góp cho xã hội."],["社会貢献のために働きます。","Tôi làm việc để đóng góp cho xã hội."],["社会貢献について考えます。","Tôi suy nghĩ về việc đóng góp cho xã hội."],["社会貢献をする会社が増えています。","Số công ty đóng góp cho xã hội đang tăng lên."]]},{"word":"貢献する","reading":"こうけんする","meaning":"đóng góp, cống hiến","hanViet":"CỐNG HIẾN","lesson":21,"ex":[["社会に貢献します。","Tôi đóng góp cho xã hội."],["会社に貢献したいです。","Tôi muốn đóng góp cho công ty."],["町に貢献します。","Tôi đóng góp cho thị trấn."],["貢献することが大切です。","Việc đóng góp là quan trọng."],["日本に貢献したいです。","Tôi muốn đóng góp cho Nhật Bản."]]},{"word":"ブランド","reading":"ブランド","meaning":"thương hiệu","hanViet":"","lesson":21,"ex":[["有名なブランドの服を買いました。","Tôi đã mua quần áo của thương hiệu nổi tiếng."],["このブランドが好きです。","Tôi thích thương hiệu này."],["ブランドの値段が高いです。","Giá của thương hiệu này cao."],["新しいブランドができました。","Thương hiệu mới đã ra đời."],["ブランドについて調べました。","Tôi đã tìm hiểu về thương hiệu."]]},{"word":"バリアフリー","reading":"バリアフリー","meaning":"không rào cản, xóa bỏ ngăn cách","hanViet":"","lesson":21,"ex":[["バリアフリーの店が増えています。","Số cửa hàng không rào cản đang tăng lên."],["この駅はバリアフリーです。","Nhà ga này không có rào cản."],["バリアフリーが大切です。","Việc xóa bỏ rào cản là quan trọng."],["バリアフリーの建物が増えました。","Số tòa nhà không rào cản đã tăng lên."],["バリアフリーについて考えます。","Tôi suy nghĩ về việc xóa bỏ rào cản."]]},{"word":"障害","reading":"しょうがい","meaning":"khuyết tật; trở ngại","hanViet":"CHƯỚNG HẠI","lesson":21,"ex":[["体に障害があります。","Cơ thể có khuyết tật."],["障害がある人のために、バリアフリーが大切です。","Vì người khuyết tật, việc xóa bỏ rào cản là quan trọng."],["目の障害があります。","Mắt có khuyết tật."],["障害があっても、仕事をしています。","Dù có khuyết tật, tôi vẫn làm việc."],["障害について勉強します。","Tôi học về khuyết tật."]]},{"word":"ダイビングする","reading":"ダイビングする","meaning":"lặn","hanViet":"","lesson":21,"ex":[["海でダイビングします。","Tôi lặn ở biển."],["夏にダイビングしたいです。","Tôi muốn lặn vào mùa hè."],["ダイビングするのが好きです。","Tôi thích lặn."],["友達と海でダイビングしました。","Tôi đã lặn ở biển cùng bạn bè."],["ダイビングして、魚を見ました。","Tôi đã lặn và ngắm cá."]]},{"word":"インスタントラーメン","reading":"インスタントラーメン","meaning":"mì ăn liền","hanViet":"","lesson":21,"ex":[["インスタントラーメンを食べます。","Tôi ăn mì ăn liền."],["インスタントラーメンが好きです。","Tôi thích mì ăn liền."],["夜にインスタントラーメンを作ります。","Tôi nấu mì ăn liền vào buổi tối."],["インスタントラーメンを買いました。","Tôi đã mua mì ăn liền."],["インスタントラーメンは安いです。","Mì ăn liền thì rẻ."]]},{"word":"消費量","reading":"しょうひりょう","meaning":"lượng tiêu thụ","hanViet":"TIÊU PHÍ LƯỢNG","lesson":21,"ex":[["電気の消費量が増えました。","Lượng điện tiêu thụ đã tăng lên."],["消費量を調べます。","Tôi tìm hiểu lượng tiêu thụ."],["水の消費量が減りました。","Lượng nước tiêu thụ đã giảm."],["日本の米の消費量が変わりました。","Lượng gạo tiêu thụ của Nhật Bản đã thay đổi."],["消費量が多いです。","Lượng tiêu thụ nhiều."]]},{"word":"総～","reading":"そう～","meaning":"tổng (lượng tiêu thụ)","hanViet":"TỔNG","lesson":21,"ex":[["総消費量が増えました。","Tổng lượng tiêu thụ đã tăng lên."],["町の総人口を調べます。","Tôi tìm hiểu tổng dân số của thị trấn."],["総消費量が去年より増えました。","Tổng lượng tiêu thụ đã tăng hơn năm ngoái."],["総人口が減りました。","Tổng dân số đã giảm."],["一日の総時間は二十四時間です。","Tổng thời gian một ngày là hai mươi bốn giờ."]]},{"word":"およそ","reading":"およそ","meaning":"khoảng, ước chừng","hanViet":"","lesson":21,"ex":[["およそ十人が来ました。","Khoảng mười người đã đến."],["およそ一時間かかります。","Tốn khoảng một giờ."],["およそ千人がこの町に住んでいます。","Khoảng một nghìn người đang sống ở thị trấn này."],["およそ三日で終わります。","Sẽ xong trong khoảng ba ngày."],["この店までおよそ十分かかります。","Đến cửa hàng này tốn khoảng mười phút."]]},{"word":"麺","reading":"めん","meaning":"mì sợi","hanViet":"DIỆN","lesson":21,"ex":[["麺が好きです。","Tôi thích mì sợi."],["麺を食べます。","Tôi ăn mì sợi."],["この店の麺がおいしいです。","Mì sợi của cửa hàng này ngon."],["麺を作ります。","Tôi làm mì sợi."],["熱い麺を食べました。","Tôi đã ăn mì sợi nóng."]]},{"word":"ハウス","reading":"ハウス","meaning":"nhà kính","hanViet":"","lesson":21,"ex":[["ハウスで野菜を作ります。","Tôi trồng rau trong nhà kính."],["ハウスでイチゴを育てます。","Tôi trồng dâu tây trong nhà kính."],["ハウスの中は暑いです。","Bên trong nhà kính thì nóng."],["ハウスがたくさんあります。","Có rất nhiều nhà kính."],["冬でもハウスで野菜ができます。","Dù mùa đông, rau vẫn trồng được trong nhà kính."]]},{"word":"養殖する","reading":"ようしょくする","meaning":"nuôi trồng","hanViet":"DƯỠNG THỰC","lesson":21,"ex":[["魚を養殖します。","Tôi nuôi cá."],["海で魚を養殖しています。","Tôi đang nuôi cá ở biển."],["養殖した魚を食べます。","Tôi ăn cá đã nuôi."],["養殖することが増えています。","Việc nuôi trồng đang tăng lên."],["養殖した魚を店で買いました。","Tôi đã mua cá đã nuôi ở cửa hàng."]]},{"word":"冷凍","reading":"れいとう","meaning":"đông lạnh","hanViet":"LÃNH ĐÔNG","lesson":21,"ex":[["冷凍の魚を買いました。","Tôi đã mua cá đông lạnh."],["魚を冷凍します。","Tôi đông lạnh cá."],["店で冷凍の肉を買いました。","Tôi đã mua thịt đông lạnh ở cửa hàng."],["冷凍した魚を焼きました。","Tôi đã nướng cá đông lạnh."],["冷凍の野菜が便利です。","Rau đông lạnh thì tiện lợi."]]},{"word":"出回る","reading":"でまわる","meaning":"có mặt trên thị trường","hanViet":"XUẤT HỒI","lesson":21,"ex":[["新しいイチゴが店に出回りました。","Dâu tây mới đã có mặt ở cửa hàng."],["秋にサンマが出回ります。","Vào mùa thu, cá thu đao có mặt trên thị trường."],["春に新しい野菜が出回ります。","Vào mùa xuân, rau mới có mặt trên thị trường."],["この本が店に出回りました。","Cuốn sách này đã có mặt ở cửa hàng."],["冬に新しい魚が出回ります。","Vào mùa đông, cá mới có mặt trên thị trường."]]},{"word":"乏しい","reading":"とぼしい","meaning":"nghèo nàn","hanViet":"PHẠP","lesson":21,"ex":[["お金が乏しいです。","Tiền bạc nghèo nàn."],["経験が乏しいです。","Kinh nghiệm nghèo nàn."],["水が乏しい町です。","Đây là thị trấn khan hiếm nước."],["知識が乏しいので、本を読みます。","Vì kiến thức nghèo nàn nên tôi đọc sách."],["時間が乏しいです。","Thời gian nghèo nàn."]]},{"word":"イチゴ","reading":"イチゴ","meaning":"dâu tây","hanViet":"","lesson":21,"ex":[["イチゴが好きです。","Tôi thích dâu tây."],["イチゴを食べます。","Tôi ăn dâu tây."],["春にイチゴが出回ります。","Vào mùa xuân, dâu tây có mặt trên thị trường."],["イチゴを買いました。","Tôi đã mua dâu tây."],["ハウスでイチゴを作ります。","Tôi trồng dâu tây trong nhà kính."]]},{"word":"クリスマスケーキ","reading":"クリスマスケーキ","meaning":"bánh Giáng sinh","hanViet":"","lesson":21,"ex":[["クリスマスケーキを買いました。","Tôi đã mua bánh Giáng sinh."],["クリスマスケーキを作ります。","Tôi làm bánh Giáng sinh."],["クリスマスケーキが好きです。","Tôi thích bánh Giáng sinh."],["冬にクリスマスケーキを食べます。","Tôi ăn bánh Giáng sinh vào mùa đông."],["クリスマスケーキを友達にあげました。","Tôi đã tặng bánh Giáng sinh cho bạn bè."]]},{"word":"カツオ","reading":"カツオ","meaning":"cá ngừ vằn","hanViet":"","lesson":21,"ex":[["カツオを食べます。","Tôi ăn cá ngừ vằn."],["カツオがおいしいです。","Cá ngừ vằn ngon."],["カツオを焼いて食べます。","Tôi nướng cá ngừ vằn rồi ăn."],["店でカツオを買いました。","Tôi đã mua cá ngừ vằn ở cửa hàng."],["カツオの料理を作ります。","Tôi nấu món cá ngừ vằn."]]},{"word":"サンマ","reading":"サンマ","meaning":"cá thu đao","hanViet":"","lesson":21,"ex":[["サンマを食べます。","Tôi ăn cá thu đao."],["秋にサンマを食べます。","Tôi ăn cá thu đao vào mùa thu."],["サンマを焼きました。","Tôi đã nướng cá thu đao."],["サンマが好きです。","Tôi thích cá thu đao."],["店でサンマを買いました。","Tôi đã mua cá thu đao ở cửa hàng."]]},{"word":"季語","reading":"きご","meaning":"từ chỉ mùa (thuật ngữ thơ haiku)","hanViet":"QUÝ NGỮ","lesson":21,"ex":[["俳句に季語を使います。","Tôi dùng từ chỉ mùa trong thơ haiku."],["季語は俳句に必要です。","Từ chỉ mùa là cần thiết cho thơ haiku."],["季語を覚えます。","Tôi nhớ từ chỉ mùa."],["雪は冬の季語です。","Tuyết là từ chỉ mùa đông."],["季語について勉強します。","Tôi học về từ chỉ mùa."]]},{"word":"旬","reading":"しゅん","meaning":"mùa, theo mùa","hanViet":"TUẦN","lesson":21,"ex":[["今はサンマの旬です。","Bây giờ là mùa cá thu đao."],["旬の魚がおいしいです。","Cá đúng mùa thì ngon."],["旬の野菜を食べます。","Tôi ăn rau đúng mùa."],["旬の食べ物が安いです。","Đồ ăn đúng mùa thì rẻ."],["春はイチゴの旬です。","Mùa xuân là mùa dâu tây."]]},{"word":"技","reading":"わざ","meaning":"kỹ thuật","hanViet":"KỸ","lesson":21,"ex":[["技を習います。","Tôi học kỹ thuật."],["すごい技を見ました。","Tôi đã xem kỹ thuật tuyệt vời."],["この技は難しいです。","Kỹ thuật này khó."],["田中さんの技はすばらしいです。","Kỹ thuật của anh Tanaka thật tuyệt vời."],["新しい技を練習します。","Tôi luyện tập kỹ thuật mới."]]},{"word":"しきたり","reading":"しきたり","meaning":"tập quán, lệ thói, quy tắc ứng xử truyền lại","hanViet":"","lesson":21,"ex":[["日本のしきたりを習います。","Tôi học tập quán của Nhật Bản."],["その町のしきたりを守ります。","Tôi giữ gìn tập quán của thị trấn đó."],["しきたりについて勉強します。","Tôi học về tập quán."],["しきたりが大切です。","Tập quán là quan trọng."],["京都のしきたりを調べます。","Tôi tìm hiểu tập quán của Kyoto."]]},{"word":"呉服","reading":"ごふく","meaning":"vải để may trang phục truyền thống của Nhật","hanViet":"NGÔ PHỤC","lesson":21,"ex":[["呉服の店へ行きます。","Tôi đi đến cửa hàng vải truyền thống."],["呉服を買いました。","Tôi đã mua vải may trang phục truyền thống."],["呉服の店で働きます。","Tôi làm việc ở cửa hàng vải truyền thống."],["呉服について勉強します。","Tôi học về vải may trang phục truyền thống."],["京都で呉服を見ました。","Tôi đã xem vải may trang phục truyền thống ở Kyoto."]]},{"word":"若だんな","reading":"わかだんな","meaning":"cậu chủ","hanViet":"NHƯỢC","lesson":21,"ex":[["若だんなが店を手伝います。","Cậu chủ phụ giúp cửa hàng."],["若だんなは元気な人です。","Cậu chủ là người khỏe mạnh."],["若だんなが店の人と話します。","Cậu chủ nói chuyện với người trong cửa hàng."],["若だんなが店を守ります。","Cậu chủ bảo vệ cửa hàng."],["若だんなに会いました。","Tôi đã gặp cậu chủ."]]},{"word":"あらゆる","reading":"あらゆる","meaning":"tất cả","hanViet":"","lesson":21,"ex":[["あらゆる人に会いました。","Tôi đã gặp tất cả mọi người."],["あらゆる国から人が来ます。","Người từ tất cả các nước đến."],["あらゆる方法を考えます。","Tôi nghĩ đến tất cả các cách."],["あらゆる場所へ行きます。","Tôi đi đến tất cả các nơi."],["あらゆる物を買います。","Tôi mua tất cả các thứ."]]},{"word":"番頭","reading":"ばんとう","meaning":"trưởng cửa hàng, người quản lý (cửa hàng)","hanViet":"PHIÊN ĐẦU","lesson":21,"ex":[["番頭は店の大切な人です。","Trưởng cửa hàng là người quan trọng của cửa hàng."],["番頭が店を守ります。","Trưởng cửa hàng bảo vệ cửa hàng."],["番頭に話を聞きました。","Tôi đã nghe câu chuyện từ trưởng cửa hàng."],["番頭が若だんなを手伝います。","Trưởng cửa hàng phụ giúp cậu chủ."],["番頭の仕事は忙しいです。","Công việc của trưởng cửa hàng bận rộn."]]},{"word":"思い知る","reading":"おもいしる","meaning":"hiểu rõ, nhận thấy","hanViet":"TƯ TRI","lesson":21,"ex":[["一人で生活するのが難しいことを思い知りました。","Tôi đã hiểu rõ việc sống một mình là khó."],["練習が大切なことを思い知りました。","Tôi đã hiểu rõ việc luyện tập là quan trọng."],["日本語が難しいことを思い知りました。","Tôi đã hiểu rõ tiếng Nhật là khó."],["仕事が大変なことを思い知りました。","Tôi đã hiểu rõ công việc là vất vả."],["時間が大切なことを思い知りました。","Tôi đã hiểu rõ thời gian là quan trọng."]]},{"word":"蔵","reading":"くら","meaning":"kho","hanViet":"TÀNG","lesson":21,"ex":[["蔵に古い本があります。","Trong kho có sách cũ."],["蔵の中に米があります。","Bên trong kho có gạo."],["蔵を見ました。","Tôi đã nhìn thấy kho."],["大きな蔵があります。","Có kho lớn."],["蔵の中に古い道具があります。","Bên trong kho có dụng cụ cũ."]]},{"word":"腐る","reading":"くさる","meaning":"thối hỏng","hanViet":"HỦ","lesson":21,"ex":[["食べ物が腐ります。","Đồ ăn bị thối hỏng."],["夏に食べ物が腐りやすいです。","Vào mùa hè, đồ ăn dễ bị thối hỏng."],["魚が腐りました。","Cá đã bị thối hỏng."],["腐った食べ物を食べてはいけません。","Không được ăn đồ ăn đã thối hỏng."],["食べ物が腐らないように、冷凍します。","Tôi đông lạnh để đồ ăn không bị thối hỏng."]]},{"word":"季節外れ","reading":"きせつはずれ","meaning":"trái mùa","hanViet":"QUÝ TIẾT NGOẠI","lesson":21,"ex":[["きょうは季節外れの雪が降りました。","Hôm nay tuyết rơi trái mùa."],["季節外れの暑さに、みんなが驚きました。","Mọi người đều ngạc nhiên vì cái nóng trái mùa."],["店は季節外れの花を売っています。","Cửa hàng bán hoa trái mùa."],["季節外れの雨が長く続きました。","Mưa trái mùa kéo dài."],["冬に季節外れの花が咲きました。","Hoa nở trái mùa vào mùa đông."]]},{"word":"房","reading":"ふさ","meaning":"múi","hanViet":"PHÒNG","lesson":21,"ex":[["みかんの房は大きいです。","Múi quýt này to."],["みかんの房を一つ食べました。","Tôi đã ăn một múi quýt."],["みかんの房は甘いです。","Múi quýt ngọt."],["みかんの房が机の上にあります。","Múi quýt ở trên bàn."],["母はみかんの房をくれました。","Mẹ đã cho tôi múi quýt."]]},{"word":"せいぜい","reading":"せいぜい","meaning":"nhiều nhất, tối đa","hanViet":"","lesson":21,"ex":[["せいぜい二時間しか寝られませんでした。","Tôi chỉ ngủ được tối đa hai tiếng."],["せいぜい一日二時間だけ勉強します。","Tôi chỉ học tối đa hai tiếng một ngày."],["本はせいぜい三日で読みます。","Cuốn sách này đọc tối đa ba ngày là xong."],["彼はせいぜい十人しか知りません。","Anh ấy chỉ biết tối đa mười người."],["せいぜい五千円まで出します。","Tôi chỉ trả tối đa năm nghìn yên."]]},{"word":"死亡記事","reading":"しぼうきじ","meaning":"bản cáo phó","hanViet":"TỬ VONG KÝ SỰ","lesson":22,"ex":[["新聞の死亡記事で先生の死を知りました。","Tôi biết tin thầy qua đời qua cáo phó trên báo."],["死亡記事には名前と日付が書いてあります。","Trong cáo phó có ghi tên và ngày tháng."],["彼は毎朝新聞の死亡記事を読みます。","Anh ấy đọc cáo phó trên báo mỗi sáng."],["死亡記事は短い文章で書かれます。","Cáo phó được viết bằng đoạn văn ngắn."],["死亡記事を見て、昔の友達を思い出しました。","Nhìn cáo phó, tôi nhớ lại người bạn ngày xưa."]]},{"word":"死亡する","reading":"しぼうする","meaning":"chết, qua đời","hanViet":"TỬ VONG","lesson":22,"ex":[["彼は病気で死亡しました。","Anh ấy qua đời vì bệnh."],["事故で多くの人が死亡しました。","Nhiều người đã chết trong vụ tai nạn."],["祖父は去年死亡しました。","Ông tôi qua đời năm ngoái."],["死亡する人は毎年多いです。","Số người chết mỗi năm rất nhiều."],["彼は死亡する前に手紙を書きました。","Trước khi qua đời, anh ấy đã viết một lá thư."]]},{"word":"手紙文","reading":"てがみぶん","meaning":"văn phong viết thư","hanViet":"THỦ CHỈ VĂN","lesson":22,"ex":[["手紙文は丁寧なことばで書きます。","Văn phong viết thư dùng lời lẽ lịch sự."],["私は手紙文を習っています。","Tôi đang học văn phong thư."],["手紙文では初めにあいさつを書きます。","Trong văn phong thư, đầu tiên viết lời chào hỏi."],["手紙文の本が多くあります。","Có nhiều sách về văn phong thư."],["手紙文は話すことばと違います。","Văn phong thư khác với ngôn ngữ nói."]]},{"word":"依頼状","reading":"いらいじょう","meaning":"đơn yêu cầu, đơn đề nghị","hanViet":"Y LẠI TRẠNG","lesson":22,"ex":[["会社に依頼状を送りました。","Tôi đã gửi đơn đề nghị đến công ty."],["依頼状には名前と住所を書きます。","Trong đơn đề nghị viết tên và địa chỉ."],["先生に依頼状を書いてもらいました。","Tôi đã nhờ thầy viết đơn đề nghị."],["依頼状は丁寧な文章で書きます。","Đơn đề nghị được viết bằng văn phong lịch sự."],["依頼状を出す前に内容を確認しました。","Trước khi gửi đơn đề nghị, tôi đã kiểm tra nội dung."]]},{"word":"死生観","reading":"しせいかん","meaning":"quan điểm về sự sống và cái chết","hanViet":"TỬ SINH QUAN","lesson":22,"ex":[["彼の死生観は本に書いてあります。","Quan điểm sống chết của anh ấy được viết trong sách."],["死生観は人によって違います。","Quan điểm về sống chết khác nhau tùy người."],["先生の死生観を聞いて考えました。","Nghe quan điểm sống chết của thầy, tôi đã suy nghĩ."],["映画は死生観について話します。","Bộ phim này nói về quan điểm sống chết."],["死生観について友達と話しました。","Tôi đã nói chuyện với bạn về quan điểm sống chết."]]},{"word":"ディスカッション","reading":"ディスカッション","meaning":"thảo luận","hanViet":"","lesson":22,"ex":[["授業でディスカッションをしました。","Chúng tôi đã thảo luận trong giờ học."],["ディスカッションは毎週金曜日にあります。","Buổi thảo luận có vào thứ Sáu hàng tuần."],["ディスカッションで意見を言いました。","Tôi đã nêu ý kiến trong buổi thảo luận."],["学生はディスカッションが好きです。","Các sinh viên thích thảo luận."],["ディスカッションの前に本を読みました。","Trước buổi thảo luận, tôi đã đọc sách."]]},{"word":"通信手段","reading":"つうしんしゅだん","meaning":"phương tiện liên lạc","hanViet":"THÔNG TÍN THỦ ĐOẠN","lesson":22,"ex":[["電話は大切な通信手段です。","Điện thoại là phương tiện liên lạc quan trọng."],["昔の通信手段は手紙でした。","Phương tiện liên lạc ngày xưa là thư."],["通信手段が増えて、連絡が楽になりました。","Phương tiện liên lạc tăng lên, việc liên lạc trở nên dễ dàng."],["インターネットは新しい通信手段です。","Internet là phương tiện liên lạc mới."],["通信手段について授業で習いました。","Tôi đã học về phương tiện liên lạc trong giờ học."]]},{"word":"手段","reading":"しゅだん","meaning":"phương tiện, cách thức","hanViet":"THỦ ĐOẠN","lesson":22,"ex":[["手段はいろいろあります。","Có nhiều cách thức khác nhau."],["目的のための手段を考えます。","Tôi nghĩ về cách thức để đạt mục đích."],["手段が知りたいときは先生に聞きます。","Khi muốn biết cách, tôi hỏi thầy."],["問題を考える手段を教えてください。","Hãy chỉ cho tôi cách nghĩ về vấn đề này."],["手段を変えて、またやってみます。","Tôi đổi cách làm và thử lại lần nữa."]]},{"word":"拝啓","reading":"はいけい","meaning":"kính gửi (lời mở đầu thư trang trọng)","hanViet":"BÁI KHẢI","lesson":22,"ex":[["手紙は拝啓から始まります。","Lá thư bắt đầu bằng \"kính gửi\"."],["拝啓は丁寧な手紙の初めに書きます。","\"Kính gửi\" được viết ở đầu thư trang trọng."],["拝啓と書いた後であいさつを書きます。","Sau khi viết \"kính gửi\", tôi viết lời chào hỏi."],["ビジネスの手紙は拝啓で始まります。","Thư công việc bắt đầu bằng \"kính gửi\"."],["拝啓の後には季節のあいさつが続きます。","Sau \"kính gửi\" là lời chào theo mùa."]]},{"word":"時下","reading":"じか","meaning":"thời điểm hiện tại","hanViet":"THỜI HẠ","lesson":22,"ex":[["時下、寒い日が続いています。","Hiện nay, những ngày lạnh vẫn tiếp diễn."],["手紙に時下ということばを使いました。","Tôi đã dùng từ \"thời điểm hiện tại\" trong thư."],["時下は忙しい毎日です。","Hiện nay là những ngày bận rộn."],["時下、寒くなりました。","Hiện nay, trời trở lạnh."],["時下の様子を手紙に書きました。","Tôi đã viết tình hình hiện tại vào thư."]]},{"word":"健勝","reading":"けんしょう","meaning":"sức khỏe tốt, mạnh khỏe","hanViet":"KIỆN THẮNG","lesson":22,"ex":[["先生はいつも健勝です。","Thầy luôn khỏe mạnh."],["手紙に健勝と書きました。","Tôi đã viết \"mạnh khỏe\" trong thư."],["祖父は健勝で、毎日散歩します。","Ông tôi khỏe mạnh, mỗi ngày đi dạo."],["健勝ということばは手紙でよく使います。","Từ \"mạnh khỏe\" thường được dùng trong thư."],["健勝でいることが一番大切です。","Khỏe mạnh là điều quan trọng nhất."]]},{"word":"小社","reading":"しょうしゃ","meaning":"công ty chúng tôi","hanViet":"TIỂU XÃ","lesson":22,"ex":[["小社は東京にあります。","Công ty chúng tôi ở Tokyo."],["小社の製品を紹介します。","Tôi xin giới thiệu sản phẩm của công ty chúng tôi."],["小社では新しい人を探しています。","Công ty chúng tôi đang tìm người mới."],["小社の社員は五十人です。","Công ty chúng tôi có năm mươi nhân viên."],["小社に来てくださって、ありがとうございます。","Cảm ơn đã đến công ty chúng tôi."]]},{"word":"目下","reading":"もっか","meaning":"hiện nay, hiện tại","hanViet":"MỤC HẠ","lesson":22,"ex":[["目下、仕事が忙しいです。","Hiện nay công việc bận rộn."],["目下の課題は時間です。","Vấn đề hiện nay là thời gian."],["目下、彼は東京に住んでいます。","Hiện nay anh ấy sống ở Tokyo."],["目下の生活は楽しいです。","Cuộc sống hiện nay vui vẻ."],["目下、会社は新しい店を作っています。","Hiện nay công ty đang xây cửa hàng mới."]]},{"word":"類","reading":"るい","meaning":"loại, hạng","hanViet":"LOẠI","lesson":22,"ex":[["新しい類の本が好きです。","Tôi thích sách loại mới."],["類が違うと値段も違います。","Loại khác nhau thì giá cũng khác nhau."],["難しい類の問題もあります。","Cũng có loại bài toán khó."],["同じ類の花を買いました。","Tôi đã mua hoa cùng loại."],["類によって意味が違います。","Ý nghĩa khác nhau tùy loại."]]},{"word":"ネクロロジー","reading":"ネクロロジー","meaning":"bài cáo phó / bài viết tưởng niệm người đã khuất","hanViet":"","lesson":22,"ex":[["新聞にネクロロジーが出ました。","Điếu văn đã đăng trên báo."],["ネクロロジーを読んで、先生の人生を知りました。","Đọc điếu văn, tôi biết được cuộc đời của thầy."],["先生のネクロロジーを書きました。","Tôi đã viết điếu văn cho thầy."],["ネクロロジーには業績が書いてあります。","Trong điếu văn có ghi thành tích."],["ネクロロジーは短い文章です。","Điếu văn là đoạn văn ngắn."]]},{"word":"物故者","reading":"ぶっこしゃ","meaning":"người chết, người đã khuất","hanViet":"VẬT CỐ GIẢ","lesson":22,"ex":[["物故者の名前が新聞に出ました。","Tên người đã khuất đã đăng trên báo."],["物故者の家族に手紙を書きました。","Tôi đã viết thư cho gia đình người đã khuất."],["物故者を思い出して、悲しくなりました。","Nhớ người đã khuất, tôi thấy buồn."],["物故者の写真が部屋にあります。","Ảnh của người đã khuất ở trong phòng."],["物故者の本を読みました。","Tôi đã đọc sách của người đã khuất."]]},{"word":"略伝","reading":"りゃくでん","meaning":"tiểu sử vắn tắt","hanViet":"LƯỢC TRUYỀN","lesson":22,"ex":[["本の初めに略伝があります。","Ở đầu sách có tiểu sử vắn tắt."],["略伝を読んで、先生の人生を知りました。","Đọc tiểu sử vắn tắt, tôi biết cuộc đời của thầy."],["略伝は短く書いてあります。","Tiểu sử vắn tắt được viết ngắn gọn."],["辞書の略伝はおもしろいです。","Tiểu sử vắn tắt trong từ điển rất thú vị."],["略伝で生まれた日を知りました。","Qua tiểu sử vắn tắt, tôi biết ngày sinh."]]},{"word":"編纂する","reading":"へんさんする","meaning":"biên soạn, biên tập","hanViet":"BIÊN TOẢN","lesson":22,"ex":[["先生は辞書を編纂しました。","Thầy đã biên soạn từ điển."],["本は長い時間をかけて編纂しました。","Cuốn sách được biên soạn trong thời gian dài."],["辞書を編纂する仕事は大変です。","Công việc biên soạn từ điển rất vất vả."],["彼は歴史の本を編纂しています。","Anh ấy đang biên soạn sách lịch sử."],["編纂した本が今年出ました。","Cuốn sách đã biên soạn ra mắt năm nay."]]},{"word":"玉稿","reading":"ぎょっこう","meaning":"bài viết (của người khác, cách nói tôn kính)","hanViet":"NGỌC CẢO","lesson":22,"ex":[["先生の玉稿を読みました。","Tôi đã đọc bài viết của thầy."],["玉稿を送ってください。","Xin hãy gửi bài viết của thầy."],["先生の玉稿はおもしろいです。","Bài viết của thầy thú vị."],["玉稿が雑誌に出ました。","Bài viết đã đăng trên tạp chí."],["玉稿を大切に読んでいます。","Tôi đang đọc kỹ bài viết của thầy."]]},{"word":"たまわる","reading":"たまわる","meaning":"nhận","hanViet":"","lesson":22,"ex":[["先生から本をたまわりました。","Tôi đã nhận được sách từ thầy."],["たまわった本を大切に読みます。","Tôi đọc kỹ cuốn sách đã nhận."],["昔の人は王様から土地をたまわりました。","Người xưa nhận đất từ nhà vua."],["おことばをたまわりました。","Tôi đã nhận được lời dạy."],["父から名前をたまわりました。","Tôi đã nhận tên từ cha."]]},{"word":"次第","reading":"しだい","meaning":"lý do","hanViet":"THỨ ĐỆ","lesson":22,"ex":[["そういう次第で、きょうは休みます。","Vì lý do đó, hôm nay tôi nghỉ."],["次第は手紙に書いてあります。","Lý do được viết trong thư."],["次第を先生に話しました。","Tôi đã nói lý do với thầy."],["遅れた次第を説明しました。","Tôi đã giải thích lý do đến muộn."],["次第によっては、予定が変わります。","Tùy theo lý do, kế hoạch có thể thay đổi."]]},{"word":"当の","reading":"とうの","meaning":"đó","hanViet":"ĐƯƠNG","lesson":22,"ex":[["当の本人は知りませんでした。","Chính người đó lại không biết."],["当の先生はもう帰りました。","Chính thầy ấy đã về rồi."],["当の話を聞いて驚きました。","Nghe chính câu chuyện đó, tôi đã ngạc nhiên."],["当の本は図書館にあります。","Chính cuốn sách đó ở trong thư viện."],["当の人は笑っていました。","Chính người đó đang cười."]]},{"word":"本人","reading":"ほんにん","meaning":"bản thân người đó","hanViet":"BẢN NHÂN","lesson":22,"ex":[["本人に直接聞いてください。","Hãy hỏi trực tiếp chính người đó."],["本人はまだ知りません。","Chính người đó vẫn chưa biết."],["本人の名前を確認しました。","Tôi đã xác nhận tên của chính người đó."],["本人が来て話しました。","Chính người đó đã đến và nói chuyện."],["本人の許可が必要です。","Cần có sự cho phép của chính người đó."]]},{"word":"執筆する","reading":"しっぴつする","meaning":"viết","hanViet":"CHẤP BÚT","lesson":22,"ex":[["先生は本を執筆しました。","Thầy đã viết sách."],["彼は小説を執筆しています。","Anh ấy đang viết tiểu thuyết."],["執筆するのに三年かかりました。","Việc viết mất ba năm."],["新聞に記事を執筆しました。","Tôi đã viết bài cho báo."],["執筆した本が売れました。","Cuốn sách đã viết đã bán được."]]},{"word":"点","reading":"てん","meaning":"(là) điểm","hanViet":"ĐIỂM","lesson":22,"ex":[["テストで九十点をとりました。","Tôi được chín mươi điểm trong bài kiểm tra."],["点は大切です。","Điểm số rất quan trọng."],["点を数えてみました。","Tôi đã thử đếm điểm."],["いい点をとるために勉強します。","Tôi học để được điểm tốt."],["点が高い学生もいます。","Cũng có học sinh điểm cao."]]},{"word":"存命中","reading":"ぞんめいちゅう","meaning":"còn sống","hanViet":"TỒN MỆNH TRUNG","lesson":22,"ex":[["存命中の写真が残っています。","Ảnh lúc còn sống vẫn còn."],["存命中に本を書きました。","Ông đã viết sách khi còn sống."],["存命中の話を聞きました。","Tôi đã nghe câu chuyện khi ông còn sống."],["彼は存命中に有名でした。","Ông ấy nổi tiếng khi còn sống."],["存命中の手紙を読みました。","Tôi đã đọc thư viết khi ông còn sống."]]},{"word":"人物","reading":"じんぶつ","meaning":"người, nhân vật","hanViet":"NHÂN VẬT","lesson":22,"ex":[["物語の人物は有名な作家です。","Nhân vật trong truyện là nhà văn nổi tiếng."],["人物の名前を覚えました。","Tôi đã nhớ tên nhân vật."],["物語の人物が好きです。","Tôi thích nhân vật trong truyện."],["大切な人物に会いました。","Tôi đã gặp một người quan trọng."],["人物について本を読みました。","Tôi đã đọc sách về nhân vật đó."]]},{"word":"業績","reading":"ぎょうせき","meaning":"kết quả, thành tích","hanViet":"NGHIỆP TÍCH","lesson":22,"ex":[["会社の業績が上がりました。","Thành tích của công ty đã tăng lên."],["彼の業績は有名です。","Thành tích của anh ấy nổi tiếng."],["業績を発表しました。","Tôi đã công bố thành tích."],["業績が認められました。","Thành tích đã được công nhận."],["業績について話を聞きました。","Tôi đã nghe nói về thành tích."]]},{"word":"辞世","reading":"じせい","meaning":"thơ tuyệt mệnh, lời trăn trối (trước lúc lâm chung)","hanViet":"TỪ THẾ","lesson":22,"ex":[["辞世の歌を読みました。","Tôi đã đọc bài thơ tuyệt mệnh."],["辞世のことばが残っています。","Lời trăn trối vẫn còn."],["彼は辞世を書きました。","Anh ấy đã viết thơ tuyệt mệnh."],["辞世の歌は静かです。","Bài thơ tuyệt mệnh thật lặng lẽ."],["辞世について本で読みました。","Tôi đã đọc về thơ tuyệt mệnh trong sách."]]},{"word":"墓碑銘","reading":"ぼひめい","meaning":"chữ khắc trên bia mộ, văn bia","hanViet":"MỘ BI MINH","lesson":22,"ex":[["墓碑銘に名前が書いてあります。","Trên văn bia có ghi tên."],["墓碑銘を読みました。","Tôi đã đọc văn bia."],["墓碑銘は短いです。","Văn bia rất ngắn."],["墓碑銘は古いです。","Văn bia đã cũ."],["墓碑銘を見て、先生を思いました。","Nhìn văn bia, tôi nghĩ về thầy."]]},{"word":"不謹慎","reading":"ふきんしん","meaning":"khiếm nhã, bất lịch sự","hanViet":"BẤT CẨN THẬN","lesson":22,"ex":[["不謹慎なことばを使いました。","Tôi đã dùng lời lẽ khiếm nhã."],["質問は不謹慎です。","Câu hỏi thật khiếm nhã."],["不謹慎な話はよくありません。","Chuyện khiếm nhã là không tốt."],["不謹慎なことを言って、謝りました。","Tôi đã nói điều khiếm nhã và xin lỗi."],["笑うのは不謹慎です。","Cười là khiếm nhã."]]},{"word":"興味本位","reading":"きょうみほんい","meaning":"(làm gì) vì tò mò, theo hứng tò mò","hanViet":"HƯNG VỊ BẢN VỊ","lesson":22,"ex":[["興味本位で本を買いました。","Tôi mua sách vì tò mò."],["興味本位で質問しました。","Tôi hỏi vì tò mò."],["興味本位で見てはいけません。","Không được xem vì tò mò."],["興味本位の話はやめましょう。","Hãy dừng chuyện tò mò lại."],["興味本位で集まりました。","Mọi người tụ tập vì tò mò."]]},{"word":"推察する","reading":"すいさつする","meaning":"suy ra, luận ra","hanViet":"SUY SÁT","lesson":22,"ex":[["顔から気持ちを推察しました。","Tôi suy ra cảm xúc từ khuôn mặt."],["手紙から事情を推察しました。","Tôi suy ra tình hình từ lá thư."],["推察するしかありません。","Chỉ có thể suy ra mà thôi."],["様子から推察しました。","Tôi đã suy ra từ dáng vẻ."],["推察したことを話しました。","Tôi đã nói điều mình suy ra."]]},{"word":"死","reading":"し","meaning":"cái chết","hanViet":"TỬ","lesson":22,"ex":[["死はみんなに来ます。","Cái chết đến với mọi người."],["死について考えました。","Tôi đã suy nghĩ về cái chết."],["死は悲しいです。","Cái chết thật buồn."],["死が怖い人が多いです。","Nhiều người sợ cái chết."],["死と生はつながっています。","Cái chết và sự sống gắn liền với nhau."]]},{"word":"生","reading":"せい","meaning":"sự sống","hanViet":"SINH","lesson":22,"ex":[["生は大切です。","Sự sống rất quý giá."],["生について本を読みました。","Tôi đã đọc sách về sự sống."],["生を楽しんでいます。","Tôi đang tận hưởng sự sống."],["生と死について話しました。","Tôi đã nói về sự sống và cái chết."],["生は短いです。","Sự sống thật ngắn ngủi."]]},{"word":"さらす","reading":"さらす","meaning":"lộ ra, thể hiện","hanViet":"","lesson":22,"ex":[["恥をさらしました。","Tôi đã làm xấu mặt mình."],["弱い点をさらしました。","Tôi đã lộ ra điểm yếu."],["気持ちをさらすのは難しいです。","Bộc lộ cảm xúc rất khó."],["彼は気持ちをさらしました。","Anh ấy đã thể hiện cảm xúc."],["傷をさらしたくありません。","Tôi không muốn lộ vết thương."]]},{"word":"集約する","reading":"しゅうやくする","meaning":"tổng hợp, tập hợp lại (thành một)","hanViet":"TẬP ƯỚC","lesson":22,"ex":[["意見を集約しました。","Tôi đã tổng hợp các ý kiến."],["話を集約して報告しました。","Tôi đã tóm tắt câu chuyện và báo cáo."],["資料を集約する仕事です。","Đây là công việc tổng hợp tài liệu."],["集約した内容を発表しました。","Tôi đã trình bày nội dung đã tổng hợp."],["情報を集約しました。","Tôi đã tổng hợp thông tin."]]},{"word":"人名事典","reading":"じんめいじてん","meaning":"từ điển tên người","hanViet":"NHÂN DANH SỰ ĐIỂN","lesson":22,"ex":[["人名事典で名前を調べました。","Tôi đã tra tên trong từ điển tên người."],["人名事典は図書館にあります。","Từ điển tên người ở trong thư viện."],["人名事典を買いました。","Tôi đã mua từ điển tên người."],["人名事典で有名な人の名前を見ました。","Tôi đã xem tên người nổi tiếng trong từ điển tên người."],["人名事典は大きい本です。","Từ điển tên người là cuốn sách lớn."]]},{"word":"記述する","reading":"きじゅつする","meaning":"miêu tả, mô tả","hanViet":"KÝ THUẬT","lesson":22,"ex":[["様子を記述しました。","Tôi đã miêu tả dáng vẻ."],["本の中で詳しく記述してあります。","Trong sách miêu tả chi tiết."],["記述するのが難しいです。","Việc miêu tả rất khó."],["歴史を記述した本です。","Đây là cuốn sách miêu tả lịch sử."],["記述した文章を読みました。","Tôi đã đọc đoạn văn đã miêu tả."]]},{"word":"客観的","reading":"きゃっかんてき","meaning":"khách quan","hanViet":"KHÁCH QUAN ĐÍCH","lesson":22,"ex":[["客観的な意見が大切です。","Ý kiến khách quan rất quan trọng."],["客観的に見てください。","Hãy nhìn một cách khách quan."],["客観的な文章を書きます。","Tôi viết đoạn văn khách quan."],["客観的な意見が必要です。","Cần ý kiến khách quan."],["客観的な話を聞きました。","Tôi đã nghe câu chuyện khách quan."]]},{"word":"抱く","reading":"いだく","meaning":"mang, ôm","hanViet":"BÃO","lesson":22,"ex":[["子どもを抱きました。","Tôi đã ôm đứa trẻ."],["夢を抱いています。","Tôi đang ấp ủ ước mơ."],["彼は希望を抱いています。","Anh ấy đang mang hy vọng."],["不安を抱いています。","Tôi đang mang nỗi lo lắng."],["母は赤ちゃんを抱きました。","Mẹ đã ôm em bé."]]},{"word":"別問題","reading":"べつもんだい","meaning":"vấn đề khác","hanViet":"BIỆT VẤN ĐỀ","lesson":22,"ex":[["それは別問題です。","Đó là vấn đề khác."],["別問題だと考えます。","Tôi nghĩ đó là vấn đề khác."],["別問題だから、今は話しません。","Vì là vấn đề khác nên bây giờ không nói."],["これは別問題です。","Đây là vấn đề khác."],["別問題を友達と考えました。","Tôi đã cùng bạn nghĩ về vấn đề khác."]]},{"word":"承知する","reading":"しょうちする","meaning":"biết, rõ","hanViet":"THỪA TRI","lesson":22,"ex":[["承知しました。","Tôi đã rõ."],["内容を承知しています。","Tôi biết rõ nội dung."],["承知して、約束を守ります。","Tôi đã rõ và sẽ giữ lời hứa."],["事情を承知しています。","Tôi biết rõ tình hình."],["承知しましたと答えました。","Tôi đã trả lời là đã rõ."]]},{"word":"いっそ","reading":"いっそ","meaning":"thà rằng","hanViet":"","lesson":22,"ex":[["いっそ、家にいましょう。","Thà rằng ở nhà."],["いっそ、やめたほうがいいです。","Thà rằng bỏ đi thì hơn."],["いっそ、新しいのを買いましょう。","Thà rằng mua cái mới."],["いっそ、歩いて行きます。","Thà rằng đi bộ."],["いっそ、全部忘れましょう。","Thà rằng quên hết đi."]]},{"word":"隔てる","reading":"へだてる","meaning":"cách biệt","hanViet":"CÁCH","lesson":22,"ex":[["川が町を隔てています。","Con sông ngăn cách thị trấn."],["海が二つの国を隔てています。","Biển ngăn cách hai đất nước."],["壁が部屋を隔てています。","Bức tường ngăn cách căn phòng."],["時間が二人を隔てました。","Thời gian đã cách biệt hai người."],["山が村を隔てています。","Núi ngăn cách ngôi làng."]]},{"word":"中略","reading":"ちゅうりゃく","meaning":"lược phần giữa","hanViet":"TRUNG LƯỢC","lesson":22,"ex":[["中略と書いてあります。","Có ghi \"lược phần giữa\"."],["文に中略があります。","Trong đoạn văn có phần lược giữa."],["中略の後を読みました。","Tôi đã đọc phần sau chỗ lược."],["中略して、最後だけ読みました。","Tôi đã lược phần giữa, chỉ đọc phần cuối."],["中略の前を読みました。","Tôi đã đọc phần trước chỗ lược."]]},{"word":"本書","reading":"ほんしょ","meaning":"cuốn sách này","hanViet":"BẢN THƯ","lesson":22,"ex":[["本書は日本語の本です。","Cuốn sách này là sách tiếng Nhật."],["本書では歴史を話します。","Cuốn sách này nói về lịch sử."],["本書を読みました。","Tôi đã đọc cuốn sách này."],["本書の内容はおもしろいです。","Nội dung cuốn sách này thú vị."],["本書は初心者にも優しいです。","Cuốn sách này cũng dễ cho người mới bắt đầu."]]},{"word":"意図する","reading":"いとする","meaning":"ý đồ, dụng ý","hanViet":"Ý ĐỒ","lesson":22,"ex":[["先生の意図する意味を知りました。","Tôi đã biết ý thầy muốn nói."],["意図して書いた文章です。","Đây là đoạn văn viết có dụng ý."],["意図するように、話が進みました。","Câu chuyện tiến triển như ý định."],["彼の意図は知りません。","Tôi không biết ý định của anh ấy."],["意図して、静かにしました。","Tôi cố ý giữ im lặng."]]},{"word":"敬具","reading":"けいぐ","meaning":"kính thư","hanViet":"KÍNH CỤ","lesson":22,"ex":[["手紙の最後に敬具と書きます。","Cuối thư viết \"kính thư\"."],["敬具は手紙の終わりに書きます。","\"Kính thư\" được viết ở cuối thư."],["敬具と書いて、名前を書きます。","Viết \"kính thư\" rồi viết tên."],["敬具の後に名前を書きます。","Sau \"kính thư\" viết tên."],["敬具で手紙を終えました。","Tôi đã kết thúc lá thư bằng \"kính thư\"."]]},{"word":"色は匂いへどちりぬるを","reading":"いろはにおいへどちりぬるを","meaning":"màu sắc tuy thơm ngát nhưng rồi cũng tàn phai","hanViet":"SẮC —","lesson":22,"ex":[["「色は匂いへどちりぬるを」は有名な文です。","\"Màu sắc tuy thơm ngát nhưng rồi cũng sẽ tàn phai\" là câu văn nổi tiếng."],["色は匂いへどちりぬるをと読みます。","Đọc là \"màu sắc tuy thơm ngát nhưng rồi cũng sẽ tàn phai\"."],["色は匂いへどちりぬるをという文を覚えました。","Tôi đã nhớ câu \"màu sắc tuy thơm ngát nhưng rồi cũng sẽ tàn phai\"."],["先生は色は匂いへどちりぬるをと教えました。","Thầy đã dạy câu \"màu sắc tuy thơm ngát nhưng rồi cũng sẽ tàn phai\"."],["色は匂いへどちりぬるをの意味を調べました。","Tôi đã tra nghĩa của câu \"màu sắc tuy thơm ngát nhưng rồi cũng sẽ tàn phai\"."]]},{"word":"氏","reading":"し","meaning":"ông ấy/ bà ấy","hanViet":"THỊ","lesson":22,"ex":[["田中氏は先生です。","Ông Tanaka là thầy giáo."],["山田氏に会いました。","Tôi đã gặp ông Yamada."],["田中氏は本を書きました。","Ông Tanaka đã viết sách."],["山田氏は京都に住んでいます。","Ông Yamada sống ở Kyoto."],["田中氏の話を聞きました。","Tôi đã nghe câu chuyện của ông Tanaka."]]},{"word":"生前","reading":"せいぜん","meaning":"khi còn sống, sinh thời","hanViet":"SINH TIỀN","lesson":22,"ex":[["生前、彼は有名でした。","Khi còn sống, ông ấy nổi tiếng."],["生前の写真を見ました。","Tôi đã xem ảnh lúc sinh thời."],["生前に書いた本です。","Đây là sách viết lúc sinh thời."],["生前の話を聞きました。","Tôi đã nghe câu chuyện lúc sinh thời."],["生前、彼は京都に住んでいました。","Khi còn sống, ông ấy sống ở Kyoto."]]},{"word":"遺骨","reading":"いこつ","meaning":"hài cốt, di cốt","hanViet":"DI CỐT","lesson":22,"ex":[["遺骨は部屋にあります。","Hài cốt ở trong phòng."],["遺骨を大切に守ります。","Chúng tôi giữ gìn hài cốt cẩn thận."],["遺骨を見て、悲しくなりました。","Nhìn hài cốt, tôi thấy buồn."],["遺骨の前に花を置きました。","Tôi đã đặt hoa trước hài cốt."],["遺骨について家族で話しました。","Gia đình đã nói chuyện về hài cốt."]]},{"word":"三無主義","reading":"さんむしゅぎ","meaning":"học thuyết 3 không","hanViet":"TAM VÔ CHỦ NGHĨA","lesson":22,"ex":[["三無主義について本で読みました。","Tôi đã đọc về học thuyết 3 không trong sách."],["三無主義ということばを知っています。","Tôi biết từ \"học thuyết 3 không\"."],["三無主義について先生に聞きました。","Tôi đã hỏi thầy về học thuyết 3 không."],["三無主義の意味を調べました。","Tôi đã tra nghĩa của học thuyết 3 không."],["三無主義は若者の話です。","Học thuyết 3 không là chuyện về giới trẻ."]]},{"word":"主義","reading":"しゅぎ","meaning":"chủ nghĩa, học thuyết","hanViet":"CHỦ NGHĨA","lesson":22,"ex":[["彼の主義は平和です。","Chủ nghĩa của anh ấy là hòa bình."],["主義について話しました。","Chúng tôi đã nói về chủ nghĩa."],["主義は人によって違います。","Chủ nghĩa khác nhau tùy người."],["新しい主義を唱えました。","Anh ấy đã đề xướng chủ nghĩa mới."],["主義の本を読みました。","Tôi đã đọc sách về chủ nghĩa."]]},{"word":"唱える","reading":"となえる","meaning":"đề xướng, chủ trương; xướng lên","hanViet":"XƯỚNG","lesson":22,"ex":[["新しい意見を唱えました。","Anh ấy đã đề xướng ý kiến mới."],["夢を唱える人がいます。","Có người xướng lên ước mơ."],["平和を唱えました。","Anh ấy đã đề xướng hòa bình."],["彼は主義を唱えました。","Anh ấy đã đề xướng chủ nghĩa."],["歌を唱えました。","Anh ấy đã xướng lên bài hát."]]},{"word":"遺書","reading":"いしょ","meaning":"di chúc","hanViet":"DI THƯ","lesson":22,"ex":[["遺書が残っていました。","Di chúc vẫn còn."],["遺書を読みました。","Tôi đã đọc di chúc."],["遺書に気持ちが書いてありました。","Trong di chúc có ghi cảm xúc."],["遺書を書くのは辛いです。","Viết di chúc thật đau lòng."],["遺書を見つけて、驚きました。","Tìm thấy di chúc, tôi đã ngạc nhiên."]]},{"word":"記す","reading":"しるす","meaning":"ghi","hanViet":"KÝ","lesson":22,"ex":[["名前を記しました。","Tôi đã ghi tên."],["きょうの日記を記します。","Tôi ghi nhật ký hôm nay."],["気持ちを記しました。","Tôi đã ghi cảm xúc."],["手紙に大切なことを記しました。","Tôi đã ghi điều quan trọng vào thư."],["記した紙を残しました。","Tôi đã giữ lại tờ giấy đã ghi."]]},{"word":"公言する","reading":"こうげんする","meaning":"công bố, tuyên bố","hanViet":"CÔNG NGÔN","lesson":22,"ex":[["彼は夢を公言しました。","Anh ấy đã công bố ước mơ."],["公言したことは守ります。","Tôi sẽ giữ điều đã tuyên bố."],["計画を公言しました。","Anh ấy đã công bố kế hoạch."],["公言するのは難しいです。","Tuyên bố thì khó."],["彼は意見を公言しました。","Anh ấy đã tuyên bố ý kiến."]]},{"word":"遺族","reading":"いぞく","meaning":"gia quyến","hanViet":"DI TỘC","lesson":22,"ex":[["遺族に手紙を書きました。","Tôi đã viết thư cho gia quyến."],["遺族は悲しいです。","Gia quyến buồn."],["遺族の気持ちを考えます。","Tôi nghĩ về cảm xúc của gia quyến."],["遺族に会いました。","Tôi đã gặp gia quyến."],["遺族を助けたいです。","Tôi muốn giúp đỡ gia quyến."]]},{"word":"忠実","reading":"ちゅうじつ","meaning":"trung thành, trung thực","hanViet":"TRUNG THỰC","lesson":22,"ex":[["彼は仕事に忠実です。","Anh ấy trung thành với công việc."],["忠実な犬が好きです。","Tôi thích chó trung thành."],["忠実に話を聞きました。","Tôi đã lắng nghe một cách chăm chú."],["忠実な友達がいます。","Tôi có người bạn trung thành."],["忠実に仕事をします。","Tôi làm việc một cách tận tụy."]]},{"word":"覆い隠す","reading":"おおいかくす","meaning":"che giấu, che đậy","hanViet":"PHÚC ẨN","lesson":22,"ex":[["顔を覆い隠しました。","Anh ấy đã che mặt."],["雪が山を覆い隠しました。","Tuyết đã che phủ ngọn núi."],["雪が車を覆い隠しました。","Tuyết đã che phủ chiếc xe."],["彼は気持ちを覆い隠しました。","Anh ấy đã che giấu cảm xúc."],["髪が顔を覆い隠しています。","Tóc che khuất mặt."]]},{"word":"生涯","reading":"しょうがい","meaning":"cuộc đời","hanViet":"SINH NHAI","lesson":22,"ex":[["生涯を日本で過ごしました。","Ông đã sống cả đời ở Nhật Bản."],["生涯の仕事です。","Đây là công việc cả đời."],["生涯をかけて本を書きました。","Ông đã dành cả đời để viết sách."],["生涯で一番大切な日です。","Đây là ngày quan trọng nhất trong đời."],["生涯、音楽が好きでした。","Suốt đời, ông yêu âm nhạc."]]},{"word":"宗教","reading":"しゅうきょう","meaning":"tôn giáo","hanViet":"TÔN GIÁO","lesson":22,"ex":[["宗教について勉強しました。","Tôi đã học về tôn giáo."],["宗教は国によって違います。","Tôn giáo khác nhau tùy quốc gia."],["宗教の本を読みました。","Tôi đã đọc sách về tôn giáo."],["宗教について話すのは難しいです。","Nói về tôn giáo rất khó."],["宗教の歴史を調べました。","Tôi đã tìm hiểu lịch sử tôn giáo."]]},{"word":"通す","reading":"とおす","meaning":"trải qua","hanViet":"THÔNG","lesson":22,"ex":[["生涯を通して本を読みました。","Suốt cuộc đời, ông đọc sách."],["一生を通して働きました。","Ông đã làm việc suốt đời."],["夜を通して本を読みました。","Tôi đã đọc sách suốt đêm."],["休みを通して勉強しました。","Tôi đã học suốt kỳ nghỉ."],["一日を通して雨が降りました。","Mưa suốt cả ngày."]]},{"word":"満月","reading":"まんげつ","meaning":"trăng tròn","hanViet":"MÃN NGUYỆT","lesson":22,"ex":[["今夜は満月です。","Tối nay trăng tròn."],["満月が空にあります。","Trăng tròn ở trên trời."],["満月を見て、写真を撮りました。","Ngắm trăng tròn, tôi đã chụp ảnh."],["満月が明るいです。","Trăng tròn thật sáng."],["満月の夜は美しいです。","Đêm trăng tròn thật đẹp."]]},{"word":"仰ぐ","reading":"あおぐ","meaning":"ngước nhìn","hanViet":"NGƯỠNG","lesson":22,"ex":[["空を仰ぎました。","Tôi đã ngước nhìn bầu trời."],["月を仰いで、歌を歌いました。","Ngước nhìn mặt trăng, tôi đã hát."],["山を仰ぎました。","Tôi đã ngước nhìn ngọn núi."],["星を仰いで、夢を見ました。","Ngước nhìn ngôi sao, tôi đã mơ."],["空を仰ぐと、気持ちがよくなります。","Ngước nhìn bầu trời, tâm trạng trở nên tốt hơn."]]},{"word":"夢想する","reading":"むそうする","meaning":"mơ tưởng, mộng tưởng","hanViet":"MỘNG TƯỞNG","lesson":22,"ex":[["夢想するのが好きです。","Tôi thích mơ tưởng."],["夢想して、歌を歌いました。","Mơ tưởng, tôi đã hát."],["夢想する時間は楽しいです。","Thời gian mơ tưởng thật vui."],["将来を夢想しました。","Tôi đã mơ tưởng về tương lai."],["夢想しながら歩きました。","Tôi vừa đi vừa mơ tưởng."]]},{"word":"はたして","reading":"はたして","meaning":"thật sự","hanViet":"","lesson":22,"ex":[["はたして、彼は来ましたか。","Rốt cuộc, anh ấy đã đến chưa?"],["はたして、話は本当でした。","Quả thật, câu chuyện là thật."],["はたして、彼は合格しました。","Quả thật, anh ấy đã đỗ."],["はたして、彼は元気でした。","Quả thật, anh ấy vẫn khỏe."],["はたして、結果はどうでしたか。","Rốt cuộc, kết quả thế nào?"]]},{"word":"最期","reading":"さいご","meaning":"lúc lâm chung","hanViet":"TỐI KỲ","lesson":22,"ex":[["最期まで笑っていました。","Đến lúc lâm chung, ông vẫn cười."],["最期のことばを聞きました。","Tôi đã nghe lời nói lúc lâm chung."],["最期は静かでした。","Lúc lâm chung thật yên tĩnh."],["最期に家族に会いました。","Lúc lâm chung, ông đã gặp gia đình."],["最期の時が来ました。","Thời khắc lâm chung đã đến."]]},{"word":"定か","reading":"さだか","meaning":"chắc chắn","hanViet":"ĐỊNH","lesson":22,"ex":[["定かではありません。","Không chắc chắn."],["定かな話はありません。","Không có chuyện chắc chắn."],["記憶が定かではありません。","Ký ức không rõ ràng."],["定かな答えが必要です。","Tôi cần câu trả lời chắc chắn."],["定かではありませんが、彼は来ると思います。","Không chắc chắn, nhưng tôi nghĩ anh ấy sẽ đến."]]},{"word":"悟る","reading":"さとる","meaning":"giác ngộ, hiểu ra","hanViet":"NGỘ","lesson":22,"ex":[["人生の意味を悟りました。","Tôi đã giác ngộ ý nghĩa cuộc đời."],["悟るのは難しいです。","Giác ngộ rất khó."],["彼は大切なことを悟りました。","Anh ấy đã hiểu ra điều quan trọng."],["悟った顔をしていました。","Anh ấy có vẻ mặt như đã hiểu ra."],["死の意味を悟りました。","Tôi đã hiểu ra ý nghĩa của cái chết."]]},{"word":"心得","reading":"こころえ","meaning":"kiến thức, hiểu biết","hanViet":"TÂM ĐẮC","lesson":22,"ex":[["心得が必要です。","Cần có hiểu biết."],["心得を教えてください。","Hãy chỉ cho tôi kiến thức."],["心得がある人は強いです。","Người có hiểu biết thì mạnh mẽ."],["心得を身につけました。","Tôi đã trang bị kiến thức."],["心得を大切にします。","Tôi trân trọng kiến thức."]]},{"word":"断食する","reading":"だんじきする","meaning":"nhịn ăn, ăn chay","hanViet":"ĐOẠN THỰC","lesson":22,"ex":[["彼は断食しました。","Anh ấy đã nhịn ăn."],["断食するのは辛いです。","Nhịn ăn thật khổ sở."],["断食して、よく寝ました。","Nhịn ăn, tôi đã ngủ ngon."],["断食する日があります。","Có ngày nhịn ăn."],["断食した後で、水を飲みました。","Sau khi nhịn ăn, tôi đã uống nước."]]},{"word":"往生する","reading":"おうじょうする","meaning":"ra đi, chết","hanViet":"VÃNG SINH","lesson":22,"ex":[["祖父は往生しました。","Ông tôi đã ra đi."],["静かに往生しました。","Ông đã ra đi thanh thản."],["往生する前に、家族に会いました。","Trước khi ra đi, ông đã gặp gia đình."],["彼は往生しましたと聞きました。","Tôi nghe nói ông ấy đã ra đi."],["往生した人の話を聞きました。","Tôi đã nghe câu chuyện về người đã ra đi."]]},{"word":"現時点","reading":"げんじてん","meaning":"thời điểm hiện tại","hanViet":"HIỆN THỜI ĐIỂM","lesson":22,"ex":[["現時点では、問題はありません。","Hiện tại, không có vấn đề gì."],["現時点の状況を話します。","Tôi sẽ nói về tình hình hiện tại."],["現時点では、まだ知りません。","Hiện tại vẫn chưa biết."],["現時点での意見です。","Đây là ý kiến tại thời điểm hiện tại."],["現時点では、雨が降っています。","Hiện tại trời đang mưa."]]},{"word":"すべ","reading":"すべ","meaning":"cách, cách thức","hanViet":"","lesson":22,"ex":[["すべがありません。","Không có cách nào."],["すべを考えました。","Tôi đã nghĩ cách."],["すべを知りません。","Tôi không biết cách."],["すべを探しています。","Tôi đang tìm cách."],["新しいすべを考えます。","Tôi nghĩ cách mới."]]},{"word":"かねて","reading":"かねて","meaning":"từ trước","hanViet":"","lesson":22,"ex":[["私はかねて日本へ行きたかったです。","Tôi đã muốn đi Nhật từ trước rồi."],["田中さんはかねて本を書きたかったです。","Anh Tanaka đã muốn viết sách từ trước rồi."],["私はかねてこの店に行ってみたかったです。","Tôi đã muốn thử đến cửa hàng này từ trước rồi."],["山田さんはかねて東京に住みたかったです。","Anh Yamada đã muốn sống ở Tokyo từ trước rồi."],["私はかねて先生に会いたかったです。","Tôi đã muốn gặp thầy từ trước rồi."]]},{"word":"一握り","reading":"ひとにぎり","meaning":"một nắm","hanViet":"NHẤT ÁC","lesson":22,"ex":[["子どもは一握りの花を持って帰りました。","Đứa trẻ mang một nắm hoa về nhà."],["母は一握りの塩をスープに入れました。","Mẹ cho một nắm muối vào súp."],["祖父は一握りの豆を子どもにあげました。","Ông cho đứa trẻ một nắm đậu."],["私は一握りの種を庭に植えました。","Tôi đã trồng một nắm hạt giống trong vườn."],["山田さんは一握りの花を母にあげました。","Anh Yamada tặng mẹ một nắm hoa."]]},{"word":"散骨","reading":"さんこつ","meaning":"việc rải tro cốt","hanViet":"TÁN CỐT","lesson":22,"ex":[["家族は祖父の散骨を海でしました。","Gia đình đã rải tro cốt của ông ở biển."],["家族は散骨について話しました。","Gia đình đã nói chuyện về việc rải tro cốt."],["父は散骨がいいと言いました。","Bố đã nói rằng rải tro cốt thì tốt."],["母は散骨のことを本で読みました。","Mẹ đã đọc về việc rải tro cốt trong sách."],["私たちは散骨の意味を考えました。","Chúng tôi đã suy nghĩ về ý nghĩa của việc rải tro cốt."]]},{"word":"知友","reading":"ちゆう","meaning":"bạn tri kỷ","hanViet":"TRI HỮU","lesson":22,"ex":[["田中さんは私の知友です。","Anh Tanaka là bạn tri kỷ của tôi."],["私は知友と毎週会います。","Tôi gặp bạn tri kỷ mỗi tuần."],["知友と話すと、気持ちが楽しくなります。","Nói chuyện với bạn tri kỷ, tâm trạng tôi trở nên vui vẻ."],["山田さんは知友の本を読みました。","Anh Yamada đã đọc sách của bạn tri kỷ."],["知友は私の誕生日に手紙をくれました。","Bạn tri kỷ đã gửi thư cho tôi vào ngày sinh nhật."]]},{"word":"遺灰","reading":"いはい","meaning":"tro cốt","hanViet":"DI KHÔI","lesson":22,"ex":[["家族は遺灰を大切にしました。","Gia đình đã gìn giữ tro cốt một cách trân trọng."],["遺灰は小さい箱に入っています。","Tro cốt được đặt trong chiếc hộp nhỏ."],["私たちは遺灰のことを静かに話しました。","Chúng tôi đã nói về tro cốt một cách lặng lẽ."],["父の遺灰はまだ家にあります。","Tro cốt của bố vẫn còn ở nhà."],["遺灰について、家族で考えました。","Về tro cốt, cả gia đình đã cùng suy nghĩ."]]},{"word":"みちすがら","reading":"みちすがら","meaning":"trên đường đi","hanViet":"","lesson":22,"ex":[["私はみちすがら音楽を聞きました。","Trên đường đi, tôi đã nghe nhạc."],["田中さんはみちすがら本を読みました。","Trên đường đi, anh Tanaka đã đọc sách."],["私たちはみちすがら話しました。","Trên đường đi, chúng tôi đã trò chuyện."],["山田さんはみちすがら花を買いました。","Trên đường đi, anh Yamada đã mua hoa."],["子どもはみちすがら歌を歌いました。","Trên đường đi, đứa trẻ đã hát."]]},{"word":"因縁","reading":"いんねん","meaning":"mối liên hệ","hanViet":"NHÂN DUYÊN","lesson":22,"ex":[["私と田中さんには古い因縁があります。","Tôi và anh Tanaka có mối liên hệ từ lâu."],["この町と私の家族には因縁があります。","Thị trấn này và gia đình tôi có mối liên hệ."],["因縁を大切にしたいです。","Tôi muốn trân trọng mối liên hệ này."],["田中さんはこの寺と因縁があります。","Anh Tanaka có mối liên hệ với ngôi chùa này."],["私たちは因縁について話しました。","Chúng tôi đã nói về mối liên hệ."]]},{"word":"散布する","reading":"さんぷする","meaning":"rải, rải rắc","hanViet":"TÁN BỐ","lesson":22,"ex":[["母は花の種を散布しました。","Mẹ đã rải hạt giống hoa."],["田中さんは庭に種を散布しました。","Anh Tanaka đã rải hạt giống ra vườn."],["私たちは公園で花の種を散布しました。","Chúng tôi đã rải hạt giống hoa ở công viên."],["山田さんは毎年春に種を散布します。","Anh Yamada rải hạt giống vào mỗi mùa xuân."],["子どもたちは種を散布して、楽しみました。","Các em nhỏ đã rải hạt giống và rất vui."]]},{"word":"愛唱句","reading":"あいしょうく","meaning":"bài thơ yêu thích","hanViet":"ÁI XƯỚNG CÚ","lesson":22,"ex":[["祖父の愛唱句は有名な俳句です。","Bài thơ yêu thích của ông là một bài haiku nổi tiếng."],["私は愛唱句を毎朝読みます。","Tôi đọc bài thơ yêu thích mỗi sáng."],["田中さんは愛唱句を手紙に書きました。","Anh Tanaka đã viết bài thơ yêu thích vào thư."],["母は愛唱句をよく歌います。","Mẹ thường hay ngâm bài thơ yêu thích."],["山田さんは愛唱句を本で見つけました。","Anh Yamada đã tìm thấy bài thơ yêu thích trong sách."]]},{"word":"制作意図","reading":"せいさくいと","meaning":"mục đích tạo ra","hanViet":"CHẾ TÁC Ý ĐỒ","lesson":22,"ex":[["作家は本の制作意図を話しました。","Nhà văn đã nói về mục đích tạo ra cuốn sách."],["この映画の制作意図は何ですか。","Mục đích tạo ra bộ phim này là gì?"],["先生は本の制作意図を聞きました。","Thầy đã hỏi về mục đích tạo ra cuốn sách."],["田中さんは写真の制作意図を説明しました。","Anh Tanaka đã giải thích mục đích tạo ra bức ảnh."],["制作意図を知ると、本が楽しくなります。","Khi biết mục đích tạo ra, cuốn sách trở nên thú vị."]]},{"word":"制作する","reading":"せいさくする","meaning":"sản xuất, tạo ra","hanViet":"CHẾ TÁC","lesson":22,"ex":[["田中さんは映画を制作しました。","Anh Tanaka đã làm phim."],["私たちは学校で本を制作しました。","Chúng tôi đã làm sách ở trường."],["山田さんは毎年新しい歌を制作します。","Anh Yamada sáng tác bài hát mới mỗi năm."],["会社は新しい車を制作しました。","Công ty đã sản xuất chiếc xe mới."],["子どもたちは学校で小さい本を制作しました。","Các em nhỏ đã làm cuốn sách nhỏ ở trường."]]},{"word":"夢みる","reading":"ゆめみる","meaning":"mơ ước","hanViet":"MỘNG","lesson":22,"ex":[["私は歌手になることを夢みました。","Tôi đã mơ ước trở thành ca sĩ."],["田中さんは医者になることを夢みています。","Anh Tanaka đang mơ ước trở thành bác sĩ."],["子どもは海で泳ぐことを夢みています。","Đứa trẻ đang mơ ước được bơi ở biển."],["山田さんは日本に行くことを夢みました。","Anh Yamada đã mơ ước được đi Nhật."],["私は大きな家に住むことを夢みています。","Tôi đang mơ ước được sống trong ngôi nhà lớn."]]},{"word":"山あり谷あり","reading":"やまありたにあり","meaning":"lúc thăng lúc trầm","hanViet":"SƠN CỐC","lesson":22,"ex":[["人生は山あり谷ありです。","Đời người lúc thăng lúc trầm."],["彼の人生は山あり谷ありでした。","Cuộc đời anh ấy lúc thăng lúc trầm."],["仕事は山あり谷ありです。","Công việc lúc thăng lúc trầm."],["田中さんの人生は山あり谷ありです。","Cuộc đời anh Tanaka lúc thăng lúc trầm."],["この会社の歴史は山あり谷ありです。","Lịch sử của công ty này lúc thăng lúc trầm."]]},{"word":"振り返る","reading":"ふりかえる","meaning":"nhìn lại","hanViet":"CHẤN PHẢN","lesson":22,"ex":[["私は子どものときを振り返ります。","Tôi nhìn lại thời thơ ấu."],["田中さんは去年を振り返りました。","Anh Tanaka đã nhìn lại năm ngoái."],["私たちは今年を振り返りました。","Chúng tôi đã nhìn lại năm nay."],["山田さんは学生のときを振り返りました。","Anh Yamada đã nhìn lại thời sinh viên."],["祖父は子どものときを振り返りました。","Ông đã nhìn lại thời thơ ấu."]]},{"word":"功績","reading":"こうせき","meaning":"thành tựu","hanViet":"CÔNG TÍCH","lesson":22,"ex":[["田中さんの功績は大きいです。","Thành tựu của anh Tanaka rất lớn."],["先生の功績をみんな知っています。","Mọi người đều biết thành tựu của thầy."],["この会社の功績は有名です。","Thành tựu của công ty này rất nổi tiếng."],["山田さんは功績について話しました。","Anh Yamada đã nói về thành tựu."],["私たちは祖父の功績を大切にします。","Chúng tôi trân trọng thành tựu của ông."]]},{"word":"還暦","reading":"かんれき","meaning":"sinh nhật lần thứ sáu mươi","hanViet":"HOÀN LỊCH","lesson":22,"ex":[["祖父は今年還暦を迎えます。","Ông sẽ đón sinh nhật lần thứ sáu mươi trong năm nay."],["母の還暦を家族でお祝いしました。","Cả gia đình đã chúc mừng sinh nhật lần thứ sáu mươi của mẹ."],["田中さんは還暦の誕生日を迎えました。","Anh Tanaka đã đón sinh nhật lần thứ sáu mươi."],["還暦のお祝いに、家族が来ました。","Nhân lễ mừng sinh nhật lần thứ sáu mươi, cả gia đình đã đến."],["父の還暦に、花をあげました。","Nhân sinh nhật lần thứ sáu mươi của bố, tôi đã tặng hoa."]]},{"word":"迎える","reading":"むかえる","meaning":"đón (~ sinh nhật lần thứ sáu mươi)","hanViet":"NGHÊNH","lesson":22,"ex":[["私たちは新しい年を迎えました。","Chúng tôi đã đón năm mới."],["田中さんは還暦を迎えました。","Anh Tanaka đã đón sinh nhật lần thứ sáu mươi."],["学校は春を迎えました。","Trường học đã đón mùa xuân."],["私は誕生日を友人と迎えました。","Tôi đã đón sinh nhật cùng bạn bè."],["私たちは新しい先生を迎えました。","Chúng tôi đã đón thầy giáo mới."]]},{"word":"フェア","reading":"フェア","meaning":"hội chợ","hanViet":"","lesson":22,"ex":[["東京で大きなフェアが開かれました。","Hội chợ lớn đã được tổ chức ở Tokyo."],["私は週末にフェアに行きました。","Tôi đã đi hội chợ vào cuối tuần."],["このフェアは毎年開かれます。","Hội chợ này được tổ chức mỗi năm."],["田中さんはフェアで本を買いました。","Anh Tanaka đã mua sách ở hội chợ."],["子どもたちはフェアで楽しみました。","Các em nhỏ đã vui chơi ở hội chợ."]]},{"word":"開催する","reading":"かいさいする","meaning":"tổ chức","hanViet":"KHAI THÔI","lesson":22,"ex":[["会社は東京で会議を開催しました。","Công ty đã tổ chức hội nghị ở Tokyo."],["学校は毎年祭りを開催します。","Trường học tổ chức lễ hội mỗi năm."],["私たちは来年コンサートを開催します。","Chúng tôi sẽ tổ chức buổi hòa nhạc vào năm sau."],["町は夏に祭りを開催しました。","Thị trấn đã tổ chức lễ hội vào mùa hè."],["先生はクラスで会議を開催しました。","Thầy đã tổ chức buổi họp ở lớp."]]},{"word":"資金","reading":"しきん","meaning":"vốn, kinh phí","hanViet":"TƯ KIM","lesson":22,"ex":[["会社は新しい店のために資金を使いました。","Công ty đã dùng vốn cho cửa hàng mới."],["私たちは祭りの資金について話しました。","Chúng tôi đã nói về kinh phí của lễ hội."],["学校は新しい図書館の資金を考えました。","Trường học đã tính đến kinh phí cho thư viện mới."],["田中さんは店の資金を銀行から借りました。","Anh Tanaka đã vay vốn cho cửa hàng từ ngân hàng."],["資金が少ないので、計画を変えました。","Vì vốn ít nên chúng tôi đã thay đổi kế hoạch."]]},{"word":"団体","reading":"だんたい","meaning":"tổ chức, đoàn thể","hanViet":"ĐOÀN THỂ","lesson":22,"ex":[["田中さんはボランティア団体で働いています。","Anh Tanaka đang làm việc tại tổ chức tình nguyện."],["この団体は子どもを助けます。","Tổ chức này giúp đỡ trẻ em."],["私たちは団体で音楽を楽しみます。","Chúng tôi thưởng thức âm nhạc cùng đoàn thể."],["山田さんは新しい団体を作りました。","Anh Yamada đã thành lập đoàn thể mới."],["団体は毎週会議をします。","Đoàn thể họp mỗi tuần."]]},{"word":"御中","reading":"おんちゅう","meaning":"gửi đến","hanViet":"NGỰ TRUNG","lesson":22,"ex":[["封筒に「田中会社御中」と書きました。","Tôi đã viết \"Kính gửi Công ty Tanaka\" trên phong bì."],["手紙の封筒に御中と書きます。","Trên phong bì thư, tôi viết \"Kính gửi\"."],["会社に手紙を送るとき、御中を使います。","Khi gửi thư cho công ty, tôi dùng \"御中\"."],["山田さんは封筒に御中と書きました。","Anh Yamada đã viết \"御中\" trên phong bì."],["この手紙は「山田会社御中」です。","Bức thư này gửi đến \"Công ty Yamada\"."]]},{"word":"時候","reading":"じこう","meaning":"thời tiết, tiết trời theo mùa","hanViet":"THỜI HẬU","lesson":22,"ex":[["手紙に時候のことを書きました。","Tôi đã viết về thời tiết theo mùa trong thư."],["時候がよくなりました。","Thời tiết theo mùa đã trở nên tốt."],["田中さんは時候の話をしました。","Anh Tanaka đã nói chuyện về thời tiết theo mùa."],["時候を考えて、手紙を書きます。","Suy nghĩ về thời tiết theo mùa, tôi viết thư."],["春の時候は暖かいです。","Tiết trời mùa xuân thật ấm áp."]]},{"word":"趣旨","reading":"しゅし","meaning":"nội dung chính","hanViet":"THÚ CHỈ","lesson":22,"ex":[["会議の趣旨を先生に聞きました。","Tôi đã hỏi thầy về nội dung chính của cuộc họp."],["この本の趣旨は何ですか。","Nội dung chính của cuốn sách này là gì?"],["田中さんは計画の趣旨を話しました。","Anh Tanaka đã nói về nội dung chính của kế hoạch."],["趣旨がわからないので、質問しました。","Vì không hiểu nội dung chính nên tôi đã hỏi."],["山田さんは手紙の趣旨を説明しました。","Anh Yamada đã giải thích nội dung chính của bức thư."]]},{"word":"企画する","reading":"きかくする","meaning":"(lập) kế hoạch","hanViet":"XÍ HỌA","lesson":22,"ex":[["私たちは祭りを企画しました。","Chúng tôi đã lên kế hoạch cho lễ hội."],["会社は新しいコンサートを企画します。","Công ty lên kế hoạch cho buổi hòa nhạc mới."],["田中さんは旅行を企画しました。","Anh Tanaka đã lên kế hoạch cho chuyến du lịch."],["学校は運動会を企画しました。","Trường học đã lên kế hoạch cho hội thể thao."],["私たちは来年パーティーを企画します。","Chúng tôi sẽ lên kế hoạch cho bữa tiệc vào năm sau."]]},{"word":"意義","reading":"いぎ","meaning":"ý nghĩa","hanViet":"Ý NGHĨA","lesson":22,"ex":[["この仕事の意義は何ですか。","Ý nghĩa của công việc này là gì?"],["田中さんは勉強の意義を話しました。","Anh Tanaka đã nói về ý nghĩa của việc học."],["私たちは祭りの意義を考えました。","Chúng tôi đã suy nghĩ về ý nghĩa của lễ hội."],["この本の意義は大きいです。","Ý nghĩa của cuốn sách này rất lớn."],["山田さんはボランティアの意義を知っています。","Anh Yamada hiểu ý nghĩa của hoạt động tình nguyện."]]},{"word":"依頼する","reading":"いらいする","meaning":"yêu cầu","hanViet":"Y LẠI","lesson":22,"ex":[["田中さんは会社に仕事を依頼しました。","Anh Tanaka đã yêu cầu công ty làm công việc."],["私は友人に写真を依頼しました。","Tôi đã nhờ bạn chụp ảnh."],["私たちは会社にパーティーの準備を依頼しました。","Chúng tôi đã yêu cầu công ty chuẩn bị bữa tiệc."],["先生は学生に作文を依頼しました。","Thầy đã yêu cầu học sinh viết bài văn."],["私は田中さんに手紙を依頼しました。","Tôi đã nhờ anh Tanaka viết thư."]]},{"word":"伝記","reading":"でんき","meaning":"tiểu sử","hanViet":"TRUYỀN KÝ","lesson":22,"ex":[["私は有名な人の伝記を読みました。","Tôi đã đọc tiểu sử của người nổi tiếng."],["田中さんは作家の伝記を書きました。","Anh Tanaka đã viết tiểu sử của nhà văn."],["この伝記はとても楽しいです。","Cuốn tiểu sử này rất thú vị."],["山田さんは伝記を図書館で借りました。","Anh Yamada đã mượn tiểu sử ở thư viện."],["私は母の伝記を読みたいです。","Tôi muốn đọc tiểu sử của mẹ."]]},{"word":"ゼミ","reading":"ゼミ","meaning":"lớp học chuyên đề","hanViet":"","lesson":22,"ex":[["私は大学でゼミに入りました。","Tôi đã tham gia lớp chuyên đề ở đại học."],["田中さんのゼミは毎週あります。","Lớp chuyên đề của anh Tanaka có mỗi tuần."],["ゼミで日本の歴史を勉強します。","Ở lớp chuyên đề, chúng tôi học lịch sử Nhật Bản."],["山田さんはゼミの先生に会いました。","Anh Yamada đã gặp thầy của lớp chuyên đề."],["私たちのゼミは小さいです。","Lớp chuyên đề của chúng tôi rất nhỏ."]]},{"word":"文末","reading":"ぶんまつ","meaning":"cuối câu","hanViet":"VĂN MẠT","lesson":22,"ex":[["文末に「です」を書きます。","Ở cuối câu, tôi viết \"です\"."],["田中さんは文末を考えました。","Anh Tanaka đã suy nghĩ về cuối câu."],["この文の文末がわかりません。","Tôi không hiểu cuối câu này."],["先生は文末の間違いを教えました。","Thầy đã chỉ ra lỗi ở cuối câu."],["山田さんは文末に「ます」を書きました。","Anh Yamada đã viết \"ます\" ở cuối câu."]]},{"word":"遠慮がち","reading":"えんりょがち","meaning":"hay ngại","hanViet":"VIỄN LỰ","lesson":22,"ex":[["田中さんは遠慮がちです。","Anh Tanaka hay ngại."],["私は遠慮がちなので、質問ができません。","Vì tôi hay ngại nên không thể hỏi."],["山田さんの子どもは遠慮がちです。","Con của anh Yamada hay ngại."],["遠慮がちな学生は、先生に話しませんでした。","Học sinh hay ngại đã không nói chuyện với thầy."],["私の友人は遠慮がちですが、親切です。","Bạn tôi hay ngại nhưng rất tốt bụng."]]},{"word":"意思","reading":"いし","meaning":"ý, ý định","hanViet":"Ý TƯ","lesson":22,"ex":[["田中さんの意思は強いです。","Ý chí của anh Tanaka rất mạnh mẽ."],["私の意思を先生に伝えました。","Tôi đã truyền đạt ý định của mình cho thầy."],["山田さんは意思を変えました。","Anh Yamada đã thay đổi ý định."],["意思が大切です。","Ý chí rất quan trọng."],["私たちはみんなの意思を聞きました。","Chúng tôi đã lắng nghe ý định của mọi người."]]},{"word":"議題","reading":"ぎだい","meaning":"vấn đề thảo luận","hanViet":"NGHỊ ĐỀ","lesson":22,"ex":[["会議の議題は何ですか。","Vấn đề thảo luận của cuộc họp là gì?"],["田中さんは議題を決めました。","Anh Tanaka đã quyết định vấn đề thảo luận."],["私たちは議題について話しました。","Chúng tôi đã nói về vấn đề thảo luận."],["山田さんは新しい議題を考えました。","Anh Yamada đã nghĩ ra vấn đề thảo luận mới."],["議題が多いので、会議は長くなりました。","Vì có nhiều vấn đề thảo luận nên cuộc họp đã kéo dài."]]},{"word":"産む","reading":"うむ","meaning":"sinh","hanViet":"SẢN","lesson":22,"ex":[["母は私を産みました。","Mẹ đã sinh ra tôi."],["田中さんの妻は子どもを産みました。","Vợ anh Tanaka đã sinh con."],["私の母は二人の子どもを産みました。","Mẹ tôi đã sinh hai người con."],["山田さんの母は去年子どもを産みました。","Mẹ của anh Yamada đã sinh con vào năm ngoái."],["彼女は元気な子どもを産みました。","Cô ấy đã sinh một đứa trẻ khỏe mạnh."]]},{"word":"保育所","reading":"ほいくしょ","meaning":"nhà trẻ","hanViet":"BẢO DỤC SỞ","lesson":22,"ex":[["子どもは保育所に行きます。","Đứa trẻ đi nhà trẻ."],["田中さんの子どもは保育所に行っています。","Con của anh Tanaka đang đi nhà trẻ."],["保育所は家の近くにあります。","Nhà trẻ ở gần nhà."],["山田さんは保育所で働いています。","Anh Yamada đang làm việc ở nhà trẻ."],["私たちは保育所に行きました。","Chúng tôi đã đến nhà trẻ."]]},{"word":"ためらう","reading":"ためらう","meaning":"do dự","hanViet":"","lesson":22,"ex":[["私は買うのをためらいました。","Tôi đã do dự khi mua."],["田中さんは答えるのをためらいました。","Anh Tanaka đã do dự khi trả lời."],["山田さんは行くのをためらいました。","Anh Yamada đã do dự khi đi."],["私は話すのをためらいました。","Tôi đã do dự khi nói."],["子どもは食べるのをためらいました。","Đứa trẻ đã do dự khi ăn."]]},{"word":"せめて","reading":"せめて","meaning":"ít nhất","hanViet":"","lesson":22,"ex":[["せめて水を飲んでください。","Ít nhất hãy uống nước đi."],["せめて少し勉強してください。","Ít nhất hãy học một chút đi."],["田中さんはせめて手紙を書きました。","Ít nhất anh Tanaka đã viết thư."],["せめて電話をしてください。","Ít nhất hãy gọi điện đi."],["山田さんはせめて私に会いました。","Ít nhất anh Yamada đã gặp tôi."]]},{"word":"給食","reading":"きゅうしょく","meaning":"bữa ăn ở trường","hanViet":"CẤP THỰC","lesson":22,"ex":[["子どもたちは学校で給食を食べます。","Các em nhỏ ăn trưa ở trường."],["私は学校の給食が好きです。","Tôi thích bữa ăn ở trường."],["田中さんは給食の時間に子どもと話します。","Anh Tanaka nói chuyện với trẻ em vào giờ ăn trưa."],["給食のあとで、子どもたちは遊びます。","Sau bữa ăn trưa, các em nhỏ chơi đùa."],["山田さんは給食を作ります。","Anh Yamada nấu bữa ăn ở trường."]]},{"word":"保育施設","reading":"ほいくしせつ","meaning":"cơ sở chăm sóc trẻ em","hanViet":"BẢO DỤC THI THIẾT","lesson":22,"ex":[["この町に新しい保育施設ができました。","Cơ sở chăm sóc trẻ em mới đã được xây ở thị trấn này."],["田中さんは保育施設で働いています。","Anh Tanaka đang làm việc tại cơ sở chăm sóc trẻ em."],["保育施設には子どもがたくさんいます。","Cơ sở chăm sóc trẻ em có rất nhiều trẻ em."],["私たちは保育施設に行きました。","Chúng tôi đã đến cơ sở chăm sóc trẻ em."],["山田さんの子どもは保育施設に行きます。","Con của anh Yamada đi cơ sở chăm sóc trẻ em."]]},{"word":"～施設","reading":"～しせつ","meaning":"cơ sở (chăm sóc trẻ em)","hanViet":"THI THIẾT","lesson":22,"ex":[["この町には保育施設があります。","Thị trấn này có cơ sở chăm sóc trẻ em."],["新しい保育施設ができました。","Cơ sở chăm sóc trẻ em mới đã được xây."],["山田さんは保育施設の先生に会いました。","Anh Yamada đã gặp giáo viên ở cơ sở chăm sóc trẻ em."],["保育施設の子どもたちは元気です。","Các em nhỏ ở cơ sở chăm sóc trẻ em rất khỏe mạnh."],["保育施設は朝開きます。","Cơ sở chăm sóc trẻ em mở cửa vào buổi sáng."]]},{"word":"充実する","reading":"じゅうじつする","meaning":"hoàn thiện, đầy đủ","hanViet":"SUNG THỰC","lesson":22,"ex":[["学校の生活が充実しました。","Cuộc sống ở trường đã trở nên đầy đủ."],["田中さんの毎日は充実しています。","Mỗi ngày của anh Tanaka đều rất đầy đủ và ý nghĩa."],["私は仕事が充実しました。","Công việc của tôi đã trở nên đầy đủ."],["山田さんは大学の生活が充実しています。","Anh Yamada có cuộc sống đại học đầy đủ."],["子どもたちの給食が充実しました。","Bữa ăn trưa của các em nhỏ đã trở nên đầy đủ hơn."]]},{"word":"無償","reading":"むしょう","meaning":"miễn phí","hanViet":"VÔ THƯỜNG","lesson":22,"ex":[["この本は無償でもらえます。","Cuốn sách này có thể nhận miễn phí."],["田中さんは無償で働いています。","Anh Tanaka đang làm việc miễn phí."],["学校の給食は無償です。","Bữa ăn ở trường là miễn phí."],["この映画は無償で見られます。","Bộ phim này có thể xem miễn phí."],["山田さんは無償で本をあげました。","Anh Yamada đã tặng sách miễn phí."]]},{"word":"恩恵","reading":"おんけい","meaning":"ân huệ","hanViet":"ÂN HUỆ","lesson":22,"ex":[["私たちは自然の恩恵を受けています。","Chúng ta đang nhận ân huệ của thiên nhiên."],["田中さんは先生の恩恵を忘れません。","Anh Tanaka không quên ân huệ của thầy."],["子どもたちは社会の恩恵を受けます。","Các em nhỏ nhận ân huệ của xã hội."],["私は母の恩恵に感謝しています。","Tôi biết ơn ân huệ của mẹ."],["山田さんは恩恵について話しました。","Anh Yamada đã nói về ân huệ."]]},{"word":"不公平","reading":"ふこうへい","meaning":"(cảm giác) bất công","hanViet":"BẤT CÔNG BÌNH","lesson":22,"ex":[["これは不公平です。","Điều này thật bất công."],["田中さんは不公平だと思いました。","Anh Tanaka nghĩ rằng điều đó bất công."],["子どもは不公平を感じました。","Đứa trẻ cảm thấy bất công."],["山田さんは不公平なことを話しました。","Anh Yamada đã nói về điều bất công."],["私たちは不公平をなくしたいです。","Chúng tôi muốn xóa bỏ sự bất công."]]},{"word":"核家族","reading":"かくかぞく","meaning":"gia đình hạt nhân","hanViet":"HẠCH GIA TỘC","lesson":22,"ex":[["私の家族は核家族です。","Gia đình tôi là gia đình hạt nhân."],["田中さんは核家族で暮らしています。","Anh Tanaka đang sống trong gia đình hạt nhân."],["日本には核家族が多いです。","Ở Nhật có nhiều gia đình hạt nhân."],["山田さんの家族も核家族です。","Gia đình anh Yamada cũng là gia đình hạt nhân."],["核家族の生活は静かです。","Cuộc sống của gia đình hạt nhân thật yên tĩnh."]]},{"word":"育児休暇","reading":"いくじきゅうか","meaning":"nghỉ chăm con","hanViet":"DỤC NHI HƯU HẠ","lesson":22,"ex":[["田中さんは育児休暇を使いました。","Anh Tanaka đã dùng kỳ nghỉ chăm con."],["私は来年育児休暇を使います。","Tôi sẽ dùng kỳ nghỉ chăm con vào năm sau."],["山田さんは育児休暇のあとで働きました。","Anh Yamada đã làm việc trở lại sau kỳ nghỉ chăm con."],["会社は育児休暇を大切にします。","Công ty coi trọng kỳ nghỉ chăm con."],["育児休暇は家族に大切です。","Kỳ nghỉ chăm con rất quan trọng với gia đình."]]},{"word":"育児","reading":"いくじ","meaning":"chăm con","hanViet":"DỤC NHI","lesson":22,"ex":[["育児は忙しいですが、楽しいです。","Chăm con bận rộn nhưng vui."],["田中さんは育児をしています。","Anh Tanaka đang chăm con."],["母は育児に疲れました。","Mẹ đã mệt vì chăm con."],["山田さんは育児について本を読みました。","Anh Yamada đã đọc sách về chăm con."],["私たちは育児を手伝います。","Chúng tôi giúp đỡ việc chăm con."]]},{"word":"子育て","reading":"こそだて","meaning":"nuôi dạy con","hanViet":"TỬ DỤC","lesson":22,"ex":[["子育ては大切な仕事です。","Nuôi dạy con là công việc quan trọng."],["田中さんは子育てを楽しんでいます。","Anh Tanaka đang tận hưởng việc nuôi dạy con."],["母は子育てに忙しいです。","Mẹ bận rộn với việc nuôi dạy con."],["山田さんは子育てについて話しました。","Anh Yamada đã nói về việc nuôi dạy con."],["子育ては家族みんなの仕事です。","Nuôi dạy con là công việc của cả gia đình."]]},{"word":"積極的","reading":"せっきょくてき","meaning":"tích cực","hanViet":"TÍCH CỰC ĐÍCH","lesson":22,"ex":[["田中さんは積極的な人です。","Anh Tanaka là người tích cực."],["私は積極的に勉強します。","Tôi học tập một cách tích cực."],["山田さんは積極的に仕事をします。","Anh Yamada làm việc một cách tích cực."],["子どもたちは積極的です。","Các em nhỏ rất tích cực."],["積極的な気持ちが大切です。","Tinh thần tích cực rất quan trọng."]]},{"word":"放棄する","reading":"ほうきする","meaning":"từ bỏ, ruồng bỏ","hanViet":"PHÓNG KHÍ","lesson":22,"ex":[["田中さんは仕事を放棄しませんでした。","Anh Tanaka đã không từ bỏ công việc."],["私は夢を放棄しません。","Tôi sẽ không từ bỏ ước mơ."],["山田さんは計画を放棄しました。","Anh Yamada đã từ bỏ kế hoạch."],["子どもを放棄してはいけません。","Không được ruồng bỏ trẻ em."],["私たちは仕事を放棄しません。","Chúng tôi sẽ không từ bỏ công việc."]]},{"word":"イジメ","reading":"イジメ","meaning":"sự bắt nạt","hanViet":"","lesson":22,"ex":[["学校でイジメがあってはいけません。","Ở trường không được có sự bắt nạt."],["田中さんはイジメをなくしたいです。","Anh Tanaka muốn xóa bỏ sự bắt nạt."],["先生はイジメについて話しました。","Thầy đã nói về sự bắt nạt."],["イジメは悲しいことです。","Sự bắt nạt là điều đáng buồn."],["私たちはイジメを見たら、先生に話します。","Nếu thấy bắt nạt, chúng tôi sẽ nói với thầy."]]},{"word":"任せる","reading":"まかせる","meaning":"giao phó, phó mặc","hanViet":"NHIỆM","lesson":22,"ex":[["田中さんは仕事を山田さんに任せました。","Anh Tanaka đã giao công việc cho anh Yamada."],["私は子どもを母に任せました。","Tôi đã giao con cho mẹ."],["先生はクラスを学生に任せました。","Thầy đã giao lớp cho học sinh."],["山田さんは計画を私に任せました。","Anh Yamada đã giao kế hoạch cho tôi."],["私は仕事を友人に任せました。","Tôi đã giao công việc cho bạn."]]},{"word":"縛る","reading":"しばる","meaning":"trói buộc, ràng buộc","hanViet":"PHƯỢC","lesson":22,"ex":[["私は時間に縛られたくありません。","Tôi không muốn bị thời gian ràng buộc."],["田中さんは仕事に縛られています。","Anh Tanaka đang bị công việc ràng buộc."],["私たちは時間に縛られています。","Chúng tôi đang bị thời gian ràng buộc."],["山田さんはお金に縛られたくありません。","Anh Yamada không muốn bị tiền bạc ràng buộc."],["子どもを時間に縛ってはいけません。","Không được ràng buộc trẻ em bằng thời gian."]]},{"word":"解消する","reading":"かいしょうする","meaning":"giải tỏa, giải quyết","hanViet":"GIẢI TIÊU","lesson":22,"ex":[["音楽はストレスを解消します。","Âm nhạc giúp giải tỏa căng thẳng."],["田中さんは問題を解消しました。","Anh Tanaka đã giải quyết vấn đề."],["私たちは不安を解消しました。","Chúng tôi đã giải tỏa sự bất an."],["山田さんはストレスを解消しました。","Anh Yamada đã giải tỏa căng thẳng."],["話すことはストレスを解消します。","Nói chuyện giúp giải tỏa căng thẳng."]]},{"word":"カップル","reading":"カップル","meaning":"cặp đôi","hanViet":"","lesson":22,"ex":[["田中さんと友人はカップルです。","Anh Tanaka và bạn anh ấy là một cặp đôi."],["カップルは公園で歩きました。","Cặp đôi đã đi dạo ở công viên."],["私はカップルの写真を撮りました。","Tôi đã chụp ảnh cặp đôi."],["カップルは店でごはんを食べました。","Cặp đôi đã ăn cơm ở quán."],["カップルは毎週映画を見ます。","Cặp đôi xem phim mỗi tuần."]]},{"word":"こだわる","reading":"こだわる","meaning":"câu nệ, để ý, lưu tâm","hanViet":"","lesson":22,"ex":[["田中さんは味にこだわります。","Anh Tanaka rất để ý đến hương vị."],["私は色にこだわります。","Tôi rất để ý đến màu sắc."],["山田さんは時間にこだわります。","Anh Yamada rất để ý đến thời gian."],["母は料理の味にこだわります。","Mẹ rất để ý đến hương vị món ăn."],["私たちは小さいことにこだわりません。","Chúng tôi không câu nệ chuyện nhỏ."]]},{"word":"背景","reading":"はいけい","meaning":"bối cảnh","hanViet":"BỐI CẢNH","lesson":22,"ex":[["この本の背景は何ですか。","Bối cảnh của cuốn sách này là gì?"],["田中さんは歴史の背景を話しました。","Anh Tanaka đã nói về bối cảnh lịch sử."],["私たちは問題の背景を考えました。","Chúng tôi đã suy nghĩ về bối cảnh của vấn đề."],["山田さんは映画の背景を知っています。","Anh Yamada biết bối cảnh của bộ phim."],["背景を知ると、話がわかります。","Khi biết bối cảnh, bạn sẽ hiểu câu chuyện."]]},{"word":"カギ","reading":"カギ","meaning":"chìa khóa (giải quyết vấn đề)","hanViet":"","lesson":22,"ex":[["話すことが問題のカギです。","Nói chuyện là chìa khóa để giải quyết vấn đề."],["田中さんはカギを見つけました。","Anh Tanaka đã tìm ra chìa khóa."],["勉強が仕事のカギです。","Học tập là chìa khóa của công việc."],["山田さんはカギについて考えました。","Anh Yamada đã suy nghĩ về chìa khóa."],["この本がカギになります。","Cuốn sách này sẽ là chìa khóa."]]},{"word":"未婚","reading":"みこん","meaning":"chưa kết hôn","hanViet":"VỊ HÔN","lesson":22,"ex":[["田中さんは未婚です。","Anh Tanaka chưa kết hôn."],["山田さんは未婚の友人が多いです。","Anh Yamada có nhiều bạn chưa kết hôn."],["私の友人は未婚です。","Bạn tôi chưa kết hôn."],["未婚の人は日本に多いです。","Người chưa kết hôn ở Nhật rất nhiều."],["田中さんは未婚ですが、楽しい生活をしています。","Anh Tanaka chưa kết hôn nhưng có cuộc sống vui vẻ."]]},{"word":"晩婚","reading":"ばんこん","meaning":"kết hôn muộn","hanViet":"VÃN HÔN","lesson":22,"ex":[["日本では晩婚が多いです。","Ở Nhật, kết hôn muộn rất nhiều."],["田中さんは晩婚を選びました。","Anh Tanaka đã chọn kết hôn muộn."],["山田さんは晩婚について話しました。","Anh Yamada đã nói về kết hôn muộn."],["晩婚の人が増えました。","Số người kết hôn muộn đã tăng lên."],["私は晩婚でもいいと思います。","Tôi nghĩ kết hôn muộn cũng tốt."]]},{"word":"発想する","reading":"はっそうする","meaning":"nảy ra ý tưởng, nghĩ ra","hanViet":"PHÁT TƯỞNG","lesson":22,"ex":[["田中さんは新しい計画を発想しました。","Anh Tanaka đã nảy ra kế hoạch mới."],["子どもは新しいゲームを発想しました。","Đứa trẻ đã nghĩ ra trò chơi mới."],["山田さんは新しい方法を発想しました。","Anh Yamada đã nghĩ ra phương pháp mới."],["先生は新しい仕組みを発想しました。","Thầy đã nghĩ ra cách thức mới."],["私は毎朝新しいことを発想します。","Mỗi sáng tôi nảy ra điều mới."]]},{"word":"転換する","reading":"てんかんする","meaning":"thay đổi","hanViet":"CHUYỂN HOÁN","lesson":22,"ex":[["田中さんは方針を転換しました。","Anh Tanaka đã thay đổi phương châm."],["私たちは生活の方法を転換しました。","Chúng tôi đã thay đổi cách sống."],["山田さんは生活を転換しました。","Anh Yamada đã thay đổi cuộc sống."],["会社は仕事の方法を転換しました。","Công ty đã thay đổi phương pháp làm việc."],["私は気持ちを転換しました。","Tôi đã thay đổi tâm trạng."]]},{"word":"値上げ","reading":"ねあげ","meaning":"tăng giá","hanViet":"TRỊ THƯỢNG","lesson":22,"ex":[["店はパンの値上げをしました。","Cửa hàng đã tăng giá bánh mì."],["値上げが多いので、お金が少なくなります。","Vì tăng giá nhiều nên tiền ít đi."],["田中さんは値上げについて話しました。","Anh Tanaka đã nói về việc tăng giá."],["電車の値上げがありました。","Đã có việc tăng giá vé tàu."],["山田さんは値上げを心配しています。","Anh Yamada đang lo lắng về việc tăng giá."]]},{"word":"居住","reading":"きょじゅう","meaning":"(môi trường) sinh sống","hanViet":"CƯ TRÚ","lesson":22,"ex":[["田中さんは東京に居住しています。","Anh Tanaka đang sinh sống ở Tokyo."],["私は京都に居住しています。","Tôi đang sinh sống ở Kyoto."],["山田さんは大阪に居住しています。","Anh Yamada đang sinh sống ở Osaka."],["居住する町は静かです。","Thị trấn nơi tôi sinh sống rất yên tĩnh."],["私たちはこの町に居住しています。","Chúng tôi đang sinh sống ở thị trấn này."]]},{"word":"レベル","reading":"レベル","meaning":"mức độ","hanViet":"","lesson":22,"ex":[["田中さんの日本語のレベルは高いです。","Trình độ tiếng Nhật của anh Tanaka rất cao."],["この本のレベルは高いです。","Mức độ của cuốn sách này cao."],["山田さんはレベルの高い仕事をします。","Anh Yamada làm công việc có mức độ cao."],["レベルが上がりました。","Mức độ đã tăng lên."],["私たちはレベルについて話しました。","Chúng tôi đã nói về mức độ."]]},{"word":"年金","reading":"ねんきん","meaning":"lương hưu","hanViet":"NIÊN KIM","lesson":22,"ex":[["祖父は年金で生活しています。","Ông sống bằng lương hưu."],["年金は大切なお金です。","Lương hưu là tiền quan trọng."],["田中さんは年金について話しました。","Anh Tanaka đã nói về lương hưu."],["私は年金を毎月もらいます。","Tôi nhận lương hưu mỗi tháng."],["山田さんは年金のことを考えています。","Anh Yamada đang suy nghĩ về lương hưu."]]},{"word":"年金生活者","reading":"ねんきんせいかつしゃ","meaning":"(người) sống bằng lương hưu","hanViet":"NIÊN KIM SINH HOẠT GIẢ","lesson":22,"ex":[["祖父は年金生活者です。","Ông là người sống bằng lương hưu."],["年金生活者は日本に多いです。","Người sống bằng lương hưu ở Nhật rất nhiều."],["田中さんの父は年金生活者です。","Bố của anh Tanaka là người sống bằng lương hưu."],["年金生活者の生活は静かです。","Cuộc sống của người sống bằng lương hưu thật yên tĩnh."],["山田さんは年金生活者と話しました。","Anh Yamada đã nói chuyện với người sống bằng lương hưu."]]},{"word":"安易","reading":"あんい","meaning":"dễ dàng","hanViet":"AN DỊCH","lesson":22,"ex":[["安易に決めてはいけません。","Không được quyết định một cách dễ dàng."],["田中さんは安易に答えました。","Anh Tanaka đã trả lời một cách dễ dàng."],["私は安易に計画を変えません。","Tôi sẽ không dễ dàng thay đổi kế hoạch."],["山田さんは安易に考えました。","Anh Yamada đã suy nghĩ một cách dễ dàng."],["安易な方法はありません。","Không có phương pháp dễ dàng nào."]]},{"word":"スライドする","reading":"スライドする","meaning":"điều chỉnh theo, trượt theo (giá cả)","hanViet":"","lesson":22,"ex":[["年金は物価にスライドします。","Lương hưu tăng theo giá cả."],["給料は物価にスライドします。","Lương tăng theo giá cả."],["田中さんは年金がスライドすることを話しました。","Anh Tanaka đã nói về việc lương hưu tăng theo."],["物価が上がると、年金もスライドします。","Khi giá cả tăng, lương hưu cũng tăng theo."],["山田さんは給料がスライドすると思っています。","Anh Yamada nghĩ rằng lương sẽ tăng theo."]]},{"word":"仕方がない","reading":"しかたがない","meaning":"không còn cách nào khác","hanViet":"SĨ PHƯƠNG","lesson":22,"ex":[["雨が降るので、仕方がないです。","Vì trời mưa nên không còn cách nào khác."],["田中さんは仕方がないと言いました。","Anh Tanaka đã nói không còn cách nào khác."],["電車が遅れたので、仕方がないです。","Vì tàu đến muộn nên không còn cách nào khác."],["山田さんは仕方がないと思いました。","Anh Yamada nghĩ không còn cách nào khác."],["お金がないので、仕方がないです。","Vì không có tiền nên không còn cách nào khác."]]},{"word":"交わり","reading":"まじわり","meaning":"giao thiệp, tiếp xúc","hanViet":"GIAO","lesson":22,"ex":[["田中さんとの交わりは楽しいです。","Giao thiệp với anh Tanaka rất vui."],["私は友人との交わりを大切にします。","Tôi trân trọng giao thiệp với bạn bè."],["山田さんは新しい交わりを作りました。","Anh Yamada đã tạo ra mối giao thiệp mới."],["交わりが増えました。","Mối giao thiệp đã tăng lên."],["私たちは交わりについて話しました。","Chúng tôi đã nói về giao thiệp."]]},{"word":"無駄遣い","reading":"むだづかい","meaning":"chi tiêu lãng phí","hanViet":"VÔ ĐÀ KHIỂN","lesson":22,"ex":[["お金の無駄遣いをしてはいけません。","Không được chi tiêu tiền lãng phí."],["田中さんは無駄遣いをしません。","Anh Tanaka không chi tiêu lãng phí."],["山田さんは無駄遣いが多いです。","Anh Yamada chi tiêu lãng phí nhiều."],["私は無駄遣いをなくしたいです。","Tôi muốn xóa bỏ chi tiêu lãng phí."],["無駄遣いはよくありません。","Chi tiêu lãng phí không tốt."]]},{"word":"誘惑する","reading":"ゆうわくする","meaning":"cám dỗ","hanViet":"DỤ HOẶC","lesson":22,"ex":[["ケーキが私を誘惑します。","Bánh cám dỗ tôi."],["田中さんはテレビに誘惑されました。","Anh Tanaka đã bị tivi cám dỗ."],["山田さんはケーキに誘惑されます。","Anh Yamada bị bánh cám dỗ."],["私はテレビに誘惑されません。","Tôi không bị tivi cám dỗ."],["子どもはケーキに誘惑されます。","Đứa trẻ bị bánh cám dỗ."]]},{"word":"日頃","reading":"ひごろ","meaning":"hằng ngày","hanViet":"NHẬT KHUYNH","lesson":22,"ex":[["私は日頃から勉強しています。","Tôi học tập hằng ngày."],["田中さんは日頃から本を読んでいます。","Anh Tanaka đọc sách hằng ngày."],["山田さんは日頃から歌を歌います。","Anh Yamada hát hằng ngày."],["日頃の勉強が大切です。","Việc học hằng ngày rất quan trọng."],["私は日頃から母に感謝しています。","Tôi biết ơn mẹ hằng ngày."]]},{"word":"オンラインゲーム","reading":"オンラインゲーム","meaning":"trò chơi trực tuyến","hanViet":"","lesson":22,"ex":[["子どもはオンラインゲームが好きです。","Đứa trẻ thích trò chơi trực tuyến."],["田中さんはオンラインゲームをします。","Anh Tanaka chơi trò chơi trực tuyến."],["私はオンラインゲームをしません。","Tôi không chơi trò chơi trực tuyến."],["山田さんはオンラインゲームで友人と話します。","Anh Yamada nói chuyện với bạn qua trò chơi trực tuyến."],["オンラインゲームは楽しいです。","Trò chơi trực tuyến rất vui."]]},{"word":"率直","reading":"そっちょく","meaning":"thẳng thắn, bộc trực","hanViet":"SUẤT TRỰC","lesson":22,"ex":[["田中さんは率直な人です。","Anh Tanaka là người thẳng thắn."],["私は率直に話します。","Tôi nói một cách thẳng thắn."],["山田さんは率直に答えました。","Anh Yamada đã trả lời một cách thẳng thắn."],["率直な意見が大切です。","Ý kiến thẳng thắn rất quan trọng."],["先生は率直に教えてくれました。","Thầy đã chỉ bảo tôi một cách thẳng thắn."]]},{"word":"意見交換","reading":"いけんこうかん","meaning":"trao đổi ý kiến","hanViet":"Ý KIẾN GIAO HOÁN","lesson":22,"ex":[["私たちは会議で意見交換をしました。","Chúng tôi đã trao đổi ý kiến trong cuộc họp."],["田中さんは先生と意見交換をしました。","Anh Tanaka đã trao đổi ý kiến với thầy."],["山田さんは友人と意見交換をします。","Anh Yamada trao đổi ý kiến với bạn."],["意見交換は大切です。","Trao đổi ý kiến rất quan trọng."],["私たちは毎週意見交換をします。","Chúng tôi trao đổi ý kiến mỗi tuần."]]},{"word":"まとめ役","reading":"まとめやく","meaning":"người dẫn dắt, người điều phối","hanViet":"DỊCH","lesson":22,"ex":[["田中さんは会議のまとめ役です。","Anh Tanaka là người điều phối cuộc họp."],["私はクラスのまとめ役になりました。","Tôi đã trở thành người điều phối của lớp."],["山田さんはまとめ役で働いています。","Anh Yamada đang làm việc với vai trò người điều phối."],["まとめ役はみんなの話を聞きます。","Người điều phối lắng nghe mọi người."],["私たちのまとめ役は先生です。","Người điều phối của chúng tôi là thầy."]]},{"word":"共有する","reading":"きょうゆうする","meaning":"chia sẻ","hanViet":"CỘNG HỮU","lesson":22,"ex":[["私たちは本を共有します。","Chúng tôi chia sẻ sách."],["田中さんは写真を共有しました。","Anh Tanaka đã chia sẻ ảnh."],["山田さんは気持ちを共有しました。","Anh Yamada đã chia sẻ cảm xúc."],["私たちは時間を共有します。","Chúng tôi chia sẻ thời gian."],["家族はごはんを共有します。","Gia đình chia sẻ bữa cơm."]]},{"word":"移転する","reading":"いてんする","meaning":"chuyển vị trí","hanViet":"DI CHUYỂN","lesson":22,"ex":[["会社は東京に移転しました。","Công ty đã chuyển đến Tokyo."],["学校は京都に移転しました。","Trường học đã chuyển đến Kyoto."],["田中さんの店は大阪に移転しました。","Cửa hàng của anh Tanaka đã chuyển đến Osaka."],["私たちは来年移転します。","Chúng tôi sẽ chuyển đi vào năm sau."],["山田さんは会社が移転することを知りました。","Anh Yamada đã biết công ty sẽ chuyển đi."]]},{"word":"出席率","reading":"しゅっせきりつ","meaning":"tỷ lệ tham gia, tỷ lệ có mặt","hanViet":"XUẤT TỊCH SUẤT","lesson":22,"ex":[["このクラスの出席率はとても高いです。","Tỷ lệ tham gia của lớp này rất cao."],["出席率が低い学生は試験を受けられません。","Học sinh có tỷ lệ tham gia thấp không được dự thi."],["先生は毎月出席率を調べます。","Giáo viên kiểm tra tỷ lệ tham gia mỗi tháng."],["出席率を上げるために、先生は一生懸命教えます。","Để nâng tỷ lệ tham gia, thầy giáo dạy hết mình."],["あの学校の出席率は去年より上がりました。","Tỷ lệ tham gia của trường đó đã tăng so với năm ngoái."]]},{"word":"運転免許証","reading":"うんてんめんきょしょう","meaning":"bằng lái xe","hanViet":"VẬN CHUYỂN MIỄN HỨA CHỨNG","lesson":22,"ex":[["運転免許証を持っていないと、車に乗れません。","Không có bằng lái xe thì không thể lái xe."],["運転免許証を家に忘れてしまいました。","Tôi đã để quên bằng lái xe ở nhà."],["運転免許証の写真は古いです。","Ảnh trên bằng lái xe đã cũ."],["警察は運転免許証を見せてくださいと言いました。","Cảnh sát nói hãy cho xem bằng lái xe."],["新しい運転免許証は来週届きます。","Bằng lái xe mới sẽ đến vào tuần sau."]]},{"word":"経済成長期","reading":"けいざいせいちょうき","meaning":"giai đoạn tăng trưởng kinh tế","hanViet":"KINH TẾ THÀNH TRƯỞNG KỲ","lesson":22,"ex":[["経済成長期には、たくさんの工場ができました。","Trong giai đoạn tăng trưởng kinh tế nhanh, nhiều nhà máy đã xuất hiện."],["日本の経済成長期について、本で読みました。","Tôi đã đọc trong sách về giai đoạn tăng trưởng kinh tế nhanh của Nhật Bản."],["経済成長期には、多くの人が都会へ引っ越しました。","Trong giai đoạn tăng trưởng kinh tế nhanh, nhiều người đã chuyển đến thành phố."],["経済成長期の話を祖父から聞きました。","Tôi đã nghe ông kể chuyện về giai đoạn tăng trưởng kinh tế nhanh."],["経済成長期には、新しい道路がたくさんできました。","Trong giai đoạn tăng trưởng kinh tế nhanh, nhiều con đường mới đã được làm."]]},{"word":"倍","reading":"ばい","meaning":"gấp … lần","hanViet":"BỘI","lesson":22,"ex":[["この町の人口は二倍になりました。","Dân số của thị trấn này đã tăng gấp đôi."],["この本はあの本の二倍の値段です。","Cuốn sách này có giá gấp đôi cuốn sách kia."],["仕事が三倍に増えて、とても忙しくなりました。","Công việc tăng gấp ba lần nên tôi trở nên rất bận."],["このかばんは二倍の大きさです。","Cái túi này to gấp đôi."],["値段が二倍になっても、この本を買います。","Dù giá gấp đôi, tôi vẫn mua cuốn sách này."]]},{"word":"皆様","reading":"みなさま","meaning":"mọi người, quý vị","hanViet":"GIAI DẠNG","lesson":22,"ex":[["皆様に心から感謝します。","Tôi chân thành cảm ơn quý vị."],["皆様に大切な話があります。","Tôi có chuyện quan trọng muốn nói với quý vị."],["皆様、どうぞお座りください。","Mời quý vị ngồi xuống."],["皆様の健康が大切です。","Sức khỏe của quý vị rất quan trọng."],["皆様は私の大切な友達です。","Quý vị là những người bạn quan trọng của tôi."]]},{"word":"国連","reading":"こくれん","meaning":"Liên Hiệp Quốc","hanViet":"QUỐC LIÊN","lesson":22,"ex":[["国連は世界の平和を守るために働いています。","Liên Hiệp Quốc làm việc để bảo vệ hòa bình thế giới."],["国連の会議で、環境の問題が話し合われました。","Tại hội nghị của Liên Hiệp Quốc, vấn đề môi trường đã được thảo luận."],["国連は子どもたちの教育を助けています。","Liên Hiệp Quốc đang giúp đỡ việc giáo dục trẻ em."],["国連の仕事について、学校で習いました。","Tôi đã học ở trường về công việc của Liên Hiệp Quốc."],["多くの国が国連に参加しています。","Nhiều quốc gia tham gia Liên Hiệp Quốc."]]},{"word":"通訳する","reading":"つうやくする","meaning":"phiên dịch","hanViet":"THÔNG DỊCH","lesson":22,"ex":[["田中さんは会議で日本語を通訳します。","Anh Tanaka phiên dịch tiếng Nhật tại hội nghị."],["通訳する仕事はとても難しいです。","Công việc phiên dịch rất khó."],["母は友達のために通訳しました。","Mẹ tôi đã phiên dịch cho bạn."],["通訳するには、日本語をよく知らなければなりません。","Để phiên dịch, phải biết rõ tiếng Nhật."],["彼は英語と日本語を通訳することができます。","Anh ấy có thể phiên dịch tiếng Anh và tiếng Nhật."]]},{"word":"左右する","reading":"さゆうする","meaning":"ảnh hưởng","hanViet":"TẢ HỮU","lesson":22,"ex":[["天気は試合の結果を左右します。","Thời tiết ảnh hưởng đến kết quả trận đấu."],["教育は子どもの未来を左右します。","Giáo dục ảnh hưởng đến tương lai của trẻ em."],["健康は毎日の生活を左右します。","Sức khỏe ảnh hưởng đến cuộc sống hằng ngày."],["勉強は試験の結果を左右します。","Việc học ảnh hưởng đến kết quả kỳ thi."],["母の意見は私の未来を左右しました。","Ý kiến của mẹ đã ảnh hưởng đến tương lai của tôi."]]},{"word":"乳幼児","reading":"にゅうようじ","meaning":"trẻ sơ sinh và trẻ nhỏ","hanViet":"NHŨ ẤU NHI","lesson":22,"ex":[["乳幼児の健康を守ることは大切です。","Bảo vệ sức khỏe của trẻ sơ sinh và trẻ nhỏ là điều quan trọng."],["この病院には乳幼児のための部屋があります。","Bệnh viện này có phòng dành cho trẻ sơ sinh và trẻ nhỏ."],["乳幼児はよく眠ります。","Trẻ sơ sinh và trẻ nhỏ ngủ nhiều."],["乳幼児の食べ物には気をつけなければなりません。","Phải chú ý đến thức ăn của trẻ sơ sinh và trẻ nhỏ."],["乳幼児を持つ母親は忙しいです。","Những bà mẹ có trẻ sơ sinh và trẻ nhỏ rất bận rộn."]]},{"word":"死亡率","reading":"しぼうりつ","meaning":"tỷ lệ tử vong","hanViet":"TỬ VONG SUẤT","lesson":22,"ex":[["死亡率が下がれば、多くの人が長く生きられます。","Nếu tỷ lệ tử vong giảm, nhiều người sẽ sống lâu hơn."],["医学がよくなって、死亡率は下がりました。","Nhờ y học tốt lên, tỷ lệ tử vong đã giảm."],["死亡率の高い国では、医療が大切です。","Ở những nước có tỷ lệ tử vong cao, y tế rất quan trọng."],["昔は乳幼児の死亡率が高かったです。","Ngày xưa tỷ lệ tử vong của trẻ sơ sinh và trẻ nhỏ rất cao."],["死亡率を調べることは国の仕事です。","Điều tra tỷ lệ tử vong là công việc của đất nước."]]},{"word":"生命体","reading":"せいめいたい","meaning":"sinh vật sống","hanViet":"SINH MỆNH THỂ","lesson":22,"ex":[["地球には多くの生命体がいます。","Trên Trái Đất có nhiều sinh vật sống."],["生命体は水がなければ生きられません。","Sinh vật sống không thể sống nếu không có nước."],["海の中には小さな生命体がたくさんいます。","Trong biển có rất nhiều sinh vật sống nhỏ."],["科学者は新しい生命体を探しています。","Các nhà khoa học đang tìm kiếm sinh vật sống mới."],["生命体はみんな食べ物が必要です。","Mọi sinh vật sống đều cần thức ăn."]]},{"word":"着用する","reading":"ちゃくようする","meaning":"mang, mặc","hanViet":"TRƯỚC DỤNG","lesson":22,"ex":[["工場では手袋を着用します。","Ở nhà máy, người ta đeo găng tay."],["医者は仕事のとき白い服を着用します。","Bác sĩ mặc quần áo trắng khi làm việc."],["寒い日は暖かい服を着用してください。","Vào ngày lạnh, hãy mặc quần áo ấm."],["夏は涼しい服を着用します。","Mùa hè, người ta mặc quần áo mát."],["登山のときは、丈夫な服を着用します。","Khi leo núi, người ta mặc quần áo chắc chắn."]]},{"word":"他人","reading":"たにん","meaning":"người khác","hanViet":"THA NHÂN","lesson":22,"ex":[["他人の気持ちを考えることは大切です。","Suy nghĩ về cảm xúc của người khác là điều quan trọng."],["他人の物を使わないでください。","Xin đừng dùng đồ của người khác."],["他人に迷惑をかけてはいけません。","Không được gây phiền phức cho người khác."],["他人の意見もよく聞きましょう。","Hãy lắng nghe ý kiến của người khác nữa."],["他人と比べると、自分が小さく見えます。","So với người khác, mình thấy mình nhỏ bé."]]},{"word":"発達する","reading":"はったつする","meaning":"phát triển","hanViet":"PHÁT ĐẠT","lesson":22,"ex":[["子どもの体はよく発達します。","Cơ thể trẻ em phát triển tốt."],["この町の交通はよく発達しています。","Giao thông của thị trấn này phát triển tốt."],["インターネットの技術が発達しました。","Công nghệ internet đã phát triển."],["体の力は子どものときに発達します。","Sức mạnh cơ thể phát triển khi còn nhỏ."],["発達した国では、教育が大切です。","Ở các nước phát triển, giáo dục rất quan trọng."]]},{"word":"地動説","reading":"ちどうせつ","meaning":"Thuyết Copernicus (cho rằng các hành tinh xoay quanh mặt trời)","hanViet":"ĐỊA ĐỘNG THUYẾT","lesson":22,"ex":[["地動説は地球と太陽の話です。","Thuyết địa động là câu chuyện về Trái Đất và Mặt Trời."],["地動説は昔の人には信じられませんでした。","Thuyết địa động ngày xưa không được mọi người tin."],["学校で地動説について習いました。","Tôi đã học về thuyết địa động ở trường."],["地動説は科学の歴史で大切です。","Thuyết địa động rất quan trọng trong lịch sử khoa học."],["地動説は今ではだれもが知っています。","Ngày nay ai cũng biết thuyết địa động."]]},{"word":"信念","reading":"しんねん","meaning":"niềm tin","hanViet":"TÍN NIỆM","lesson":22,"ex":[["信念を持つことは大切です。","Có niềm tin là điều quan trọng."],["彼は自分の信念を曲げませんでした。","Anh ấy đã không từ bỏ niềm tin của mình."],["信念が強い人は困難に負けません。","Người có niềm tin mạnh mẽ không thua khó khăn."],["先生の信念に感動しました。","Tôi đã cảm động trước niềm tin của thầy giáo."],["信念を持って、一生懸命働きます。","Tôi làm việc hết mình với niềm tin."]]},{"word":"にこにこする","reading":"にこにこする","meaning":"mỉm cười","hanViet":"","lesson":22,"ex":[["赤ちゃんはにこにこしています。","Em bé đang mỉm cười."],["母はいつもにこにこしています。","Mẹ tôi lúc nào cũng mỉm cười."],["先生はにこにこして学生を迎えました。","Thầy giáo mỉm cười đón học sinh."],["子どもたちはにこにこして遊んでいます。","Các em nhỏ đang mỉm cười chơi đùa."],["彼女はにこにこしながら話しました。","Cô ấy vừa mỉm cười vừa nói chuyện."]]},{"word":"待ち望む","reading":"まちのぞむ","meaning":"mong đợi","hanViet":"ĐÃI VỌNG","lesson":22,"ex":[["私たちは春を待ち望んでいます。","Chúng tôi đang mong đợi mùa xuân."],["子どもたちは休みを待ち望んでいます。","Các em nhỏ đang mong đợi kỳ nghỉ."],["彼は友達の手紙を待ち望んでいます。","Anh ấy đang mong đợi thư của bạn."],["長い間待ち望んだ日が来ました。","Ngày mong đợi bấy lâu đã đến."],["家族は彼の帰りを待ち望んでいます。","Gia đình đang mong đợi anh ấy trở về."]]},{"word":"めったに","reading":"めったに","meaning":"hiếm khi","hanViet":"","lesson":22,"ex":[["私はめったに映画を見ません。","Tôi hiếm khi xem phim."],["彼はめったに怒りません。","Anh ấy hiếm khi tức giận."],["この町ではめったに雪が降りません。","Ở thị trấn này hiếm khi có tuyết."],["私はめったに病気になりません。","Tôi hiếm khi bị bệnh."],["母はめったにテレビを見ません。","Mẹ tôi hiếm khi xem tivi."]]},{"word":"よほど","reading":"よほど","meaning":"nhiều, lắm","hanViet":"","lesson":22,"ex":[["よほど疲れたので、寝ました。","Vì mệt lắm nên tôi đã đi ngủ."],["よほどおいしい料理でした。","Đó là món ăn ngon lắm."],["よほど忙しい日でした。","Đó là một ngày bận lắm."],["よほど寒かったので、コートを着ました。","Vì lạnh lắm nên tôi đã mặc áo khoác."],["よほどうれしかったです。","Tôi vui lắm."]]},{"word":"機嫌","reading":"きげん","meaning":"tâm trạng","hanViet":"CƠ HIỀM","lesson":22,"ex":[["母の機嫌がいいです。","Tâm trạng của mẹ rất tốt."],["機嫌が悪いときは、一人でいたいです。","Khi tâm trạng xấu, tôi muốn ở một mình."],["先生の機嫌がいいので、話しました。","Vì tâm trạng của thầy giáo tốt nên tôi đã nói chuyện."],["機嫌がよくなると、仕事も進みます。","Khi tâm trạng tốt lên, công việc cũng tiến triển."],["子どもの機嫌をとるのは難しいです。","Làm cho trẻ em vui là điều khó."]]},{"word":"ストレス","reading":"ストレス","meaning":"căng thẳng, áp lực","hanViet":"","lesson":22,"ex":[["仕事のストレスがたまっています。","Áp lực công việc đang tích tụ."],["ストレスを減らすために、音楽を聞きます。","Để giảm căng thẳng, tôi nghe nhạc."],["ストレスが多いと、体に悪いです。","Nếu căng thẳng nhiều, sẽ hại cho cơ thể."],["音楽を聞くと、ストレスが減ります。","Khi nghe nhạc, căng thẳng giảm đi."],["試験の前に、ストレスがあります。","Trước kỳ thi, tôi có căng thẳng."]]},{"word":"たまる","reading":"たまる","meaning":"(căng thẳng) tích tụ","hanViet":"","lesson":22,"ex":[["ストレスがたまると、眠れなくなります。","Khi căng thẳng tích tụ, tôi không ngủ được."],["本が部屋にたまっています。","Sách đang chất đống trong phòng."],["仕事がたまって、忙しいです。","Công việc chất đống nên tôi bận."],["お金がたまったら、本を買います。","Khi tiền tích lũy đủ, tôi sẽ mua sách."],["ストレスがたまっているので、休みます。","Vì căng thẳng tích tụ nên tôi nghỉ ngơi."]]},{"word":"突く","reading":"つく","meaning":"chọc, đâm, thúc","hanViet":"ĐỘT","lesson":22,"ex":[["子どもが指で私の肩を突きました。","Đứa trẻ đã chọc vào vai tôi bằng ngón tay."],["彼は指で地面を突きました。","Anh ấy đã chọc xuống đất bằng ngón tay."],["友達が私の手を突きました。","Bạn tôi đã chọc vào tay tôi."],["彼の話は私の心を突きました。","Lời nói của anh ấy đã chạm đến trái tim tôi."],["犬が私の手を突きました。","Con chó đã húc vào tay tôi."]]},{"word":"エコロジー","reading":"エコロジー","meaning":"sinh thái học","hanViet":"","lesson":22,"ex":[["エコロジーについて学校で習いました。","Tôi đã học về sinh thái học ở trường."],["エコロジーを考えることは大切です。","Suy nghĩ về sinh thái học là điều quan trọng."],["エコロジーの本を読みました。","Tôi đã đọc sách về sinh thái học."],["エコロジーのために、ごみを減らします。","Vì sinh thái học, tôi giảm rác."],["エコロジーの活動に参加したいです。","Tôi muốn tham gia hoạt động sinh thái học."]]},{"word":"思想","reading":"しそう","meaning":"tư tưởng","hanViet":"TƯ TƯỞNG","lesson":22,"ex":[["彼の思想は多くの人を変えました。","Tư tưởng của anh ấy đã thay đổi nhiều người."],["新しい思想が世界に広がりました。","Tư tưởng mới đã lan rộng ra thế giới."],["先生の思想に感動しました。","Tôi đã cảm động trước tư tưởng của thầy giáo."],["思想について本を読みました。","Tôi đã đọc sách về tư tưởng."],["思想を大切にしましょう。","Hãy trân trọng tư tưởng."]]},{"word":"まもなく","reading":"まもなく","meaning":"chẳng mấy chốc","hanViet":"","lesson":22,"ex":[["まもなく電車が来ます。","Tàu sắp đến."],["まもなく春が来ます。","Mùa xuân sắp đến."],["まもなく試合が始まります。","Trận đấu sắp bắt đầu."],["まもなく雨が降ります。","Trời sắp mưa."],["まもなく夏が終わります。","Mùa hè sắp kết thúc."]]},{"word":"そうした","reading":"そうした","meaning":"như thế, như vậy","hanViet":"","lesson":22,"ex":[["そうした問題はよくあります。","Những vấn đề như vậy thường xảy ra."],["そうした人は多いです。","Có nhiều người như vậy."],["そうした人になりたいです。","Tôi muốn trở thành người như vậy."],["そうした仕事は難しいです。","Công việc như vậy rất khó."],["そうした話を聞くのは楽しいです。","Nghe những câu chuyện như vậy rất vui."]]},{"word":"労働力","reading":"ろうどうりょく","meaning":"lực lượng lao động","hanViet":"LAO ĐỘNG LỰC","lesson":22,"ex":[["この国では労働力が足りません。","Ở đất nước này, lực lượng lao động không đủ."],["労働力が増えることが大切です。","Lực lượng lao động tăng lên là điều quan trọng."],["若い労働力が都会へ集まります。","Lực lượng lao động trẻ tập trung về thành phố."],["労働力が足りないことが問題になっています。","Việc thiếu lực lượng lao động đang trở thành vấn đề."],["外国の労働力が増えています。","Lực lượng lao động nước ngoài đang tăng lên."]]},{"word":"依存する","reading":"いそんする","meaning":"phụ thuộc","hanViet":"Y TỒN","lesson":22,"ex":[["私たちは電気に依存しています。","Chúng ta phụ thuộc vào điện."],["インターネットに依存しすぎないでください。","Xin đừng phụ thuộc quá nhiều vào internet."],["この国は外国からの食料に依存しています。","Đất nước này phụ thuộc vào thực phẩm từ nước ngoài."],["子どもは親に依存します。","Trẻ em phụ thuộc vào cha mẹ."],["依存する生活をやめたいです。","Tôi muốn từ bỏ cuộc sống phụ thuộc."]]},{"word":"労働者","reading":"ろうどうしゃ","meaning":"công nhân, người lao động","hanViet":"LAO ĐỘNG GIẢ","lesson":22,"ex":[["労働者の数は増えています。","Số lượng người lao động đang tăng lên."],["労働者の生活を守ることが大切です。","Bảo vệ cuộc sống của người lao động là điều quan trọng."],["工場で多くの労働者が働いています。","Nhiều công nhân đang làm việc ở nhà máy."],["労働者の給料が上がりました。","Lương của người lao động đã tăng."],["労働者のために、新しい法律ができました。","Vì người lao động, luật mới đã được ban hành."]]},{"word":"受け入れる","reading":"うけいれる","meaning":"tiếp nhận","hanViet":"THỤ NHẬP","lesson":22,"ex":[["学校は外国の学生を受け入れます。","Trường học tiếp nhận học sinh nước ngoài."],["会社は新しい社員を受け入れました。","Công ty đã tiếp nhận nhân viên mới."],["彼の意見を受け入れることは難しいです。","Tiếp nhận ý kiến của anh ấy rất khó."],["日本は多くの外国の人を受け入れています。","Nhật Bản đang tiếp nhận nhiều người nước ngoài."],["新しい教育を受け入れましょう。","Hãy tiếp nhận nền giáo dục mới."]]},{"word":"労働条件","reading":"ろうどうじょうけん","meaning":"điều kiện làm việc","hanViet":"LAO ĐỘNG ĐIỀU KIỆN","lesson":22,"ex":[["労働条件がよくなりました。","Điều kiện làm việc đã tốt hơn."],["労働条件について話し合いました。","Chúng tôi đã thảo luận về điều kiện làm việc."],["労働条件の悪い会社では働きたくありません。","Tôi không muốn làm việc ở công ty có điều kiện làm việc xấu."],["労働条件を調べることが大切です。","Điều tra điều kiện làm việc là điều quan trọng."],["労働条件がよければ、社員は長く働きます。","Nếu điều kiện làm việc tốt, nhân viên sẽ làm việc lâu dài."]]},{"word":"労働","reading":"ろうどう","meaning":"lao động","hanViet":"LAO ĐỘNG","lesson":22,"ex":[["労働は生活に必要です。","Lao động cần thiết cho cuộc sống."],["労働の時間は一日八時間です。","Thời gian lao động là 8 giờ mỗi ngày."],["労働が終わったら、ゆっくり休みます。","Sau khi lao động xong, tôi nghỉ ngơi thong thả."],["労働は大切だと知りました。","Tôi đã biết lao động rất quan trọng."],["労働は体にいいです。","Lao động tốt cho cơ thể."]]},{"word":"整備する","reading":"せいびする","meaning":"bảo dưỡng, chuẩn bị, hoàn chỉnh (cơ sở vật chất, máy móc)","hanViet":"CHỈNH BỊ","lesson":22,"ex":[["道路を整備することが大切です。","Hoàn thiện đường sá là điều quan trọng."],["車を整備しました。","Tôi đã bảo dưỡng xe."],["公園を整備する計画があります。","Có kế hoạch hoàn thiện công viên."],["機械を整備する仕事をしています。","Tôi đang làm công việc bảo dưỡng máy móc."],["自転車を整備して、安全に乗ります。","Tôi bảo dưỡng xe đạp rồi đi xe an toàn."]]},{"word":"天","reading":"てん","meaning":"thiên đường","hanViet":"THIÊN","lesson":22,"ex":[["いい人は死んだら、天に行くと言われています。","Người ta nói người tốt sau khi chết sẽ lên thiên đường."],["天は美しい場所だと信じられています。","Thiên đường được tin là nơi đẹp đẽ."],["子どものころ、天の話を聞きました。","Khi còn nhỏ, tôi đã nghe chuyện về thiên đường."],["天は平和な場所です。","Thiên đường là nơi yên bình."],["天を信じる人は多いです。","Có nhiều người tin vào thiên đường."]]},{"word":"パスワード","reading":"パスワード","meaning":"mật khẩu","hanViet":"","lesson":22,"ex":[["パスワードを忘れてしまいました。","Tôi đã quên mật khẩu."],["パスワードは他人に教えてはいけません。","Không được cho người khác biết mật khẩu."],["新しいパスワードを作りました。","Tôi đã tạo mật khẩu mới."],["パスワードを変えてください。","Hãy đổi mật khẩu."],["パスワードを紙に書かないでください。","Xin đừng viết mật khẩu ra giấy."]]},{"word":"地面","reading":"じめん","meaning":"mặt đất","hanViet":"ĐỊA DIỆN","lesson":22,"ex":[["地面に雪が積もっています。","Tuyết đang phủ trên mặt đất."],["地面が乾いています。","Mặt đất đang khô."],["地面に座って休みました。","Tôi ngồi xuống mặt đất nghỉ ngơi."],["地面に花が咲いています。","Hoa đang nở trên mặt đất."],["地面の上に本を置きました。","Tôi đặt sách lên mặt đất."]]},{"word":"凍る","reading":"こおる","meaning":"đông lại","hanViet":"ĐÔNG","lesson":22,"ex":[["冬になると、水が凍ります。","Khi mùa đông đến, nước đóng băng."],["寒い夜に、道が凍りました。","Vào đêm lạnh, đường đã đóng băng."],["湖の水が凍っています。","Nước hồ đang đóng băng."],["凍った地面は滑りやすいです。","Mặt đất đóng băng rất dễ trơn."],["手が凍るほど寒いです。","Lạnh đến mức tay đóng băng."]]},{"word":"王様","reading":"おうさま","meaning":"vua","hanViet":"VƯƠNG DẠNG","lesson":22,"ex":[["王様は大きな家に住んでいました。","Nhà vua sống trong ngôi nhà lớn."],["王様の話を本で読みました。","Tôi đã đọc chuyện về nhà vua trong sách."],["人々は王様が好きでした。","Mọi người thích nhà vua."],["子どもたちは王様の物語が好きです。","Các em nhỏ thích câu chuyện về nhà vua."],["王様は人々を大切にしました。","Nhà vua coi trọng mọi người."]]},{"word":"幼い","reading":"おさない","meaning":"còn nhỏ (tuổi), non nớt, trẻ thơ","hanViet":"ẤU","lesson":22,"ex":[["幼い子どもはよく泣きます。","Trẻ nhỏ hay khóc."],["幼いとき、日本に住んでいました。","Khi còn nhỏ, tôi sống ở Nhật Bản."],["幼い顔をしています。","Anh ấy có khuôn mặt trẻ con."],["幼い子どもを一人にしないでください。","Xin đừng để trẻ nhỏ một mình."],["幼いころの思い出が大切です。","Ký ức thời thơ ấu rất quan trọng."]]},{"word":"貧しい","reading":"まずしい","meaning":"nghèo","hanViet":"BẦN","lesson":22,"ex":[["貧しい家族を助けたいです。","Tôi muốn giúp đỡ gia đình nghèo."],["貧しい国では、食料が足りません。","Ở nước nghèo, thực phẩm không đủ."],["貧しい生活を送っていました。","Tôi đã sống cuộc sống nghèo khó."],["貧しい子どもたちに本をあげました。","Tôi đã tặng sách cho trẻ em nghèo."],["貧しい人にも教育が必要です。","Người nghèo cũng cần giáo dục."]]},{"word":"援助する","reading":"えんじょする","meaning":"viện trợ","hanViet":"VIỆN TRỢ","lesson":22,"ex":[["日本は貧しい国を援助しています。","Nhật Bản đang viện trợ cho nước nghèo."],["援助するお金が集まりました。","Tiền viện trợ đã được quyên góp."],["国連は子どもたちを援助します。","Liên Hiệp Quốc viện trợ cho trẻ em."],["援助するために、お金を送りました。","Để viện trợ, tôi đã gửi tiền."],["援助を受けた国は感謝しています。","Nước nhận viện trợ đang biết ơn."]]},{"word":"刺激する","reading":"しげきする","meaning":"kích thích, tạo động lực","hanViet":"THÍCH KÍCH","lesson":22,"ex":[["新しい音楽は心を刺激します。","Âm nhạc mới kích thích trái tim."],["先生の話は学生を刺激しました。","Lời nói của thầy giáo đã tạo động lực cho học sinh."],["刺激する話を聞きました。","Tôi đã nghe câu chuyện tạo động lực."],["新しい本は心を刺激します。","Sách mới kích thích trái tim."],["友達の話が私を刺激します。","Câu chuyện của bạn tạo động lực cho tôi."]]},{"word":"食料","reading":"しょくりょう","meaning":"thức ăn","hanViet":"THỰC LIỆU","lesson":22,"ex":[["食料が足りません。","Thức ăn không đủ."],["食料を大切にしましょう。","Hãy trân trọng thức ăn."],["困ったとき、食料が必要です。","Khi gặp khó khăn, cần thức ăn."],["食料を外国から買います。","Chúng ta mua thực phẩm từ nước ngoài."],["食料の値段が上がりました。","Giá thực phẩm đã tăng."]]},{"word":"不確か","reading":"ふたしか","meaning":"không chắc chắn","hanViet":"BẤT XÁC","lesson":22,"ex":[["不確かな情報は信じないでください。","Xin đừng tin thông tin không chắc chắn."],["彼の話は不確かです。","Câu chuyện của anh ấy không chắc chắn."],["不確かな話を聞きました。","Tôi đã nghe câu chuyện không chắc chắn."],["未来は不確かです。","Tương lai không chắc chắn."],["不確かな記憶があります。","Tôi có ký ức không chắc chắn."]]},{"word":"児童公園","reading":"じどうこうえん","meaning":"công viên cho trẻ em","hanViet":"NHI ĐỒNG CÔNG VIÊN","lesson":22,"ex":[["児童公園で子どもたちが遊んでいます。","Trẻ em đang chơi ở công viên cho trẻ em."],["児童公園にはブランコがあります。","Ở công viên cho trẻ em có xích đu."],["母は子どもと児童公園へ行きました。","Mẹ đã đi đến công viên cho trẻ em cùng con."],["児童公園は家の近くにあります。","Công viên cho trẻ em ở gần nhà."],["児童公園で友達と会いました。","Tôi đã gặp bạn ở công viên cho trẻ em."]]},{"word":"児童","reading":"じどう","meaning":"trẻ em","hanViet":"NHI ĐỒNG","lesson":22,"ex":[["児童は元気に遊びます。","Trẻ em chơi đùa khỏe mạnh."],["児童の安全を守ります。","Chúng ta bảo vệ sự an toàn của trẻ em."],["児童のための本がたくさんあります。","Có nhiều sách dành cho trẻ em."],["児童は学校で勉強します。","Trẻ em học ở trường."],["児童の声が好きです。","Tôi thích tiếng nói của trẻ em."]]},{"word":"ブランコ","reading":"ブランコ","meaning":"cái xích đu","hanViet":"","lesson":22,"ex":[["ブランコに乗るのが好きです。","Tôi thích chơi xích đu."],["子どもはブランコで遊んでいます。","Đứa trẻ đang chơi xích đu."],["ブランコが高く上がります。","Xích đu lên cao."],["公園のブランコは古いです。","Xích đu ở công viên đã cũ."],["ブランコに乗って、空を見ました。","Tôi chơi xích đu và ngắm bầu trời."]]},{"word":"滑り台","reading":"すべりだい","meaning":"cầu trượt","hanViet":"HOẠT ĐÀI","lesson":22,"ex":[["子どもは滑り台で遊んでいます。","Đứa trẻ đang chơi cầu trượt."],["滑り台から滑りました。","Tôi đã trượt xuống từ cầu trượt."],["滑り台は公園にあります。","Cầu trượt ở trong công viên."],["滑り台は高くて怖いです。","Cầu trượt cao và đáng sợ."],["滑り台で友達と遊びました。","Tôi đã chơi cầu trượt với bạn."]]},{"word":"甘やかす","reading":"あまやかす","meaning":"chiều chuộng, nuông chiều","hanViet":"CAM","lesson":22,"ex":[["祖母は孫を甘やかします。","Bà chiều chuộng cháu."],["子どもを甘やかしすぎてはいけません。","Không được nuông chiều con quá mức."],["犬を甘やかすのはよくありません。","Nuông chiều chó là không tốt."],["彼は子どものころ甘やかされました。","Anh ấy đã được nuông chiều khi còn nhỏ."],["甘やかされた子どもは困ります。","Trẻ em được nuông chiều sẽ gặp khó khăn."]]},{"word":"予防接種","reading":"よぼうせっしゅ","meaning":"tiêm phòng","hanViet":"DỰ PHÒNG TIẾP CHỦNG","lesson":22,"ex":[["子どもは予防接種を受けます。","Trẻ em được tiêm phòng."],["予防接種は病気を防ぎます。","Tiêm phòng ngăn ngừa bệnh tật."],["予防接種の日を忘れないでください。","Xin đừng quên ngày tiêm phòng."],["予防接種のために病院へ行きました。","Tôi đã đến bệnh viện để tiêm phòng."],["予防接種は大切です。","Tiêm phòng rất quan trọng."]]},{"word":"生きがい","reading":"いきがい","meaning":"ý nghĩa cuộc sống, lẽ sống","hanViet":"SINH","lesson":22,"ex":[["仕事は私の生きがいです。","Công việc là lẽ sống của tôi."],["生きがいを持つことは大切です。","Có lẽ sống là điều quan trọng."],["子どもが私の生きがいです。","Con cái là lẽ sống của tôi."],["生きがいを見つけました。","Tôi đã tìm thấy lẽ sống."],["音楽は彼の生きがいです。","Âm nhạc là lẽ sống của anh ấy."]]},{"word":"童話","reading":"どうわ","meaning":"đồng thoại, truyện cổ tích","hanViet":"ĐỒNG THOẠI","lesson":22,"ex":[["童話を読むのが好きです。","Tôi thích đọc truyện cổ tích."],["母は童話を読んでくれました。","Mẹ đã đọc truyện cổ tích cho tôi."],["童話の世界は美しいです。","Thế giới truyện cổ tích thật đẹp."],["童話を子どもに話しました。","Tôi đã kể truyện cổ tích cho trẻ em."],["有名な童話を日本語で読みました。","Tôi đã đọc truyện cổ tích nổi tiếng bằng tiếng Nhật."]]},{"word":"意欲","reading":"いよく","meaning":"động lực, ý chí phấn đấu, sự hăng hái","hanViet":"Ý DỤC","lesson":22,"ex":[["意欲を持って勉強します。","Tôi học với động lực."],["彼の意欲は強いです。","Động lực của anh ấy rất mạnh."],["意欲がある学生はよく勉強します。","Học sinh có động lực học rất chăm."],["意欲が低いと、仕事が進みません。","Khi động lực thấp, công việc không tiến triển."],["意欲を大切にしましょう。","Hãy trân trọng động lực."]]},{"word":"公平","reading":"こうへい","meaning":"công bằng","hanViet":"CÔNG BÌNH","lesson":22,"ex":[["公平な心が大切です。","Trái tim công bằng rất quan trọng."],["先生は学生を公平に扱います。","Thầy giáo đối xử công bằng với học sinh."],["公平な試験を受けたいです。","Tôi muốn dự kỳ thi công bằng."],["公平に考えることが大切です。","Suy nghĩ công bằng là điều quan trọng."],["公平な社会を作りましょう。","Hãy tạo ra xã hội công bằng."]]},{"word":"科目","reading":"かもく","meaning":"môn học","hanViet":"KHOA MỤC","lesson":22,"ex":[["好きな科目は英語です。","Môn học yêu thích của tôi là tiếng Anh."],["科目の中で、歴史が一番難しいです。","Trong các môn học, lịch sử khó nhất."],["新しい科目が増えました。","Môn học mới đã tăng lên."],["科目の試験があります。","Có bài thi môn học."],["科目を選ぶことができます。","Có thể chọn môn học."]]},{"word":"社会保障","reading":"しゃかいほしょう","meaning":"an sinh xã hội","hanViet":"XÃ HỘI BẢO CHƯỚNG","lesson":22,"ex":[["社会保障は人々の生活を守ります。","An sinh xã hội bảo vệ cuộc sống của nhân dân."],["社会保障の制度について習いました。","Tôi đã học về chế độ an sinh xã hội."],["社会保障がよくなりました。","An sinh xã hội đã tốt hơn."],["社会保障は大切な問題です。","An sinh xã hội là vấn đề quan trọng."],["社会保障のために働く人がいます。","Có những người làm việc vì an sinh xã hội."]]},{"word":"爆発する","reading":"ばくはつする","meaning":"bùng nổ","hanViet":"BẠO PHÁT","lesson":22,"ex":[["人口が爆発しました。","Dân số đã bùng nổ."],["インターネットの人気が爆発しました。","Sự nổi tiếng của internet đã bùng nổ."],["爆発する音が聞こえました。","Tôi đã nghe thấy tiếng nổ."],["爆発の火が消えました。","Lửa của vụ nổ đã tắt."],["爆発のニュースをテレビで見ました。","Tôi đã xem tin tức về vụ nổ trên tivi."]]},{"word":"急増する","reading":"きゅうぞうする","meaning":"tăng nhanh","hanViet":"CẤP TĂNG","lesson":22,"ex":[["人口が急増しています。","Dân số đang tăng nhanh."],["観光客が急増しました。","Khách du lịch đã tăng nhanh."],["外国の学生が急増しています。","Học sinh nước ngoài đang tăng nhanh."],["車の数が急増しました。","Số lượng xe đã tăng nhanh."],["インターネットの人気が急増しています。","Sự nổi tiếng của internet đang tăng nhanh."]]},{"word":"雇用する","reading":"こようする","meaning":"tuyển dụng","hanViet":"CỐ DỤNG","lesson":22,"ex":[["会社は新しい社員を雇用します。","Công ty tuyển dụng nhân viên mới."],["若い人を雇用することが大切です。","Tuyển dụng người trẻ là điều quan trọng."],["雇用された人は喜びました。","Người được tuyển dụng đã rất vui."],["外国の人を雇用する会社が増えています。","Công ty tuyển dụng người nước ngoài đang tăng lên."],["雇用する人を探しています。","Tôi đang tìm người để tuyển dụng."]]},{"word":"貧困","reading":"ひんこん","meaning":"sự nghèo đói","hanViet":"BẦN KHỐN","lesson":22,"ex":[["貧困は世界の問題です。","Nghèo đói là vấn đề của thế giới."],["貧困をなくすことが大切です。","Xóa bỏ nghèo đói là điều quan trọng."],["貧困のために、学校に行けない子どもがいます。","Vì nghèo đói, có trẻ em không thể đến trường."],["貧困の国を助けたいです。","Tôi muốn giúp đỡ nước nghèo đói."],["貧困は多くの問題を生みます。","Nghèo đói sinh ra nhiều vấn đề."]]},{"word":"生む","reading":"うむ","meaning":"làm phát sinh, sinh ra","hanViet":"SINH","lesson":22,"ex":[["母は私を生みました。","Mẹ đã sinh ra tôi."],["新しい音楽が生まれました。","Âm nhạc mới đã ra đời."],["勉強は力を生みます。","Việc học sinh ra sức mạnh."],["問題が生まれました。","Vấn đề đã phát sinh."],["友達は幸せを生みます。","Bạn bè sinh ra hạnh phúc."]]},{"word":"深刻","reading":"しんこく","meaning":"nghiêm trọng","hanViet":"THÂM KHẮC","lesson":22,"ex":[["深刻な問題があります。","Có vấn đề nghiêm trọng."],["問題は深刻です。","Vấn đề rất nghiêm trọng."],["深刻な病気になりました。","Tôi đã mắc bệnh nghiêm trọng."],["深刻な話を聞きました。","Tôi đã nghe câu chuyện nghiêm trọng."],["環境の問題は深刻です。","Vấn đề môi trường rất nghiêm trọng."]]},{"word":"フェスタ","reading":"フェスタ","meaning":"lễ hội","hanViet":"","lesson":22,"ex":[["フェスタが町で開かれます。","Lễ hội được tổ chức ở thị trấn."],["フェスタに行きました。","Tôi đã đi lễ hội."],["フェスタでは音楽が流れます。","Tại lễ hội, âm nhạc vang lên."],["フェスタは毎年秋にあります。","Lễ hội diễn ra mỗi năm vào mùa thu."],["フェスタで友達と会いました。","Tôi đã gặp bạn ở lễ hội."]]},{"word":"私ども","reading":"わたくしども","meaning":"chúng tôi","hanViet":"TƯ","lesson":22,"ex":[["私どもは日本語を勉強しています。","Chúng tôi đang học tiếng Nhật."],["私どもの会社は東京にあります。","Công ty chúng tôi ở Tokyo."],["私どもに電話してください。","Xin hãy gọi điện cho chúng tôi."],["私どもの仕事は教育です。","Công việc của chúng tôi là giáo dục."],["私どもは皆様を大切にします。","Chúng tôi trân trọng quý vị."]]},{"word":"協会","reading":"きょうかい","meaning":"hiệp hội","hanViet":"HIỆP HỘI","lesson":22,"ex":[["協会の会議があります。","Có hội nghị của hiệp hội."],["協会に入りました。","Tôi đã gia nhập hiệp hội."],["協会は多くの人を助けています。","Hiệp hội đang giúp đỡ nhiều người."],["協会の仕事について話しました。","Tôi đã nói về công việc của hiệp hội."],["協会で日本語を教えています。","Tôi dạy tiếng Nhật ở hiệp hội."]]},{"word":"展示する","reading":"てんじする","meaning":"triển lãm","hanViet":"TRIỂN THỊ","lesson":22,"ex":[["博物館で絵を展示します。","Bảo tàng triển lãm tranh."],["新しい車を展示しました。","Tôi đã triển lãm xe mới."],["展示する作品を選びました。","Tôi đã chọn tác phẩm để triển lãm."],["写真を展示する場所があります。","Có nơi triển lãm ảnh."],["展示した絵が売れました。","Bức tranh được triển lãm đã bán được."]]},{"word":"詳細","reading":"しょうさい","meaning":"chi tiết","hanViet":"TƯỜNG TẾ","lesson":22,"ex":[["詳細を教えてください。","Xin hãy cho tôi biết chi tiết."],["詳細は来週知らせます。","Tôi sẽ thông báo chi tiết vào tuần sau."],["詳細を話してください。","Xin hãy nói chi tiết."],["詳細を調べました。","Tôi đã điều tra chi tiết."],["詳細は知りません。","Tôi không biết chi tiết."]]},{"word":"企画書","reading":"きかくしょ","meaning":"bản kế hoạch","hanViet":"XÍ HỌA THƯ","lesson":22,"ex":[["企画書を書きました。","Tôi đã viết bản kế hoạch."],["企画書を読んでください。","Xin hãy đọc bản kế hoạch."],["企画書を作るのは難しいです。","Làm bản kế hoạch rất khó."],["企画書を先生に見せました。","Tôi đã cho thầy giáo xem bản kế hoạch."],["企画書の内容を話しました。","Tôi đã nói về nội dung bản kế hoạch."]]},{"word":"打合わせ","reading":"うちあわせ","meaning":"sự trao đổi, sự thảo luận","hanViet":"ĐẢ HỢP","lesson":22,"ex":[["打合わせは午後三時からです。","Buổi thảo luận bắt đầu từ 3 giờ chiều."],["打合わせで新しい計画を話しました。","Tôi đã nói về kế hoạch mới trong buổi thảo luận."],["打合わせの時間を決めました。","Tôi đã quyết định thời gian thảo luận."],["打合わせが長くなりました。","Buổi thảo luận đã kéo dài."],["打合わせの前に、資料を読みました。","Trước buổi thảo luận, tôi đã đọc tài liệu."]]},{"word":"日程","reading":"にってい","meaning":"lịch trình","hanViet":"NHẬT TRÌNH","lesson":22,"ex":[["日程を教えてください。","Xin hãy cho tôi biết lịch trình."],["日程が決まりました。","Lịch trình đã được quyết định."],["日程を変えました。","Tôi đã thay đổi lịch trình."],["日程について話し合いました。","Chúng tôi đã thảo luận về lịch trình."],["日程は来週です。","Lịch trình là tuần sau."]]},{"word":"用件","reading":"ようけん","meaning":"việc, vấn đề","hanViet":"DỤNG KIỆN","lesson":22,"ex":[["用件があって、先生に会いました。","Tôi có việc nên đã gặp thầy giáo."],["用件を話してください。","Xin hãy nói việc của bạn."],["用件は何ですか。","Việc gì vậy?"],["用件が終わりました。","Việc đã xong."],["用件のために電話をしました。","Tôi đã gọi điện vì có việc."]]},{"word":"承諾する","reading":"しょうだくする","meaning":"đồng ý, chấp nhận","hanViet":"THỪA NẶC","lesson":22,"ex":[["先生は私の計画を承諾しました。","Thầy giáo đã đồng ý với kế hoạch của tôi."],["承諾する前に、よく考えてください。","Trước khi đồng ý, hãy suy nghĩ kỹ."],["会社は彼の休みを承諾しました。","Công ty đã chấp nhận kỳ nghỉ của anh ấy."],["承諾してくれて、うれしいです。","Tôi rất vui vì bạn đã đồng ý."],["承諾しなければ、仕事は始まりません。","Nếu không đồng ý, công việc sẽ không bắt đầu."]]},{"word":"無気力","reading":"むきりょく","meaning":"uể oải","hanViet":"VÔ KHÍ LỰC","lesson":22,"ex":[["無気力な日が続きます。","Những ngày uể oải cứ tiếp diễn."],["彼は無気力です。","Anh ấy uể oải."],["無気力になると、勉強が進みません。","Khi trở nên uể oải, việc học không tiến triển."],["無気力な顔をしています。","Anh ấy có vẻ mặt uể oải."],["無気力をなくすために、よく寝ます。","Để hết uể oải, tôi ngủ đủ giấc."]]},{"word":"無断","reading":"むだん","meaning":"không có sự cho phép, tùy tiện","hanViet":"VÔ ĐOẠN","lesson":22,"ex":[["無断で部屋に入ってはいけません。","Không được vào phòng mà không có sự cho phép."],["無断で写真を撮らないでください。","Xin đừng chụp ảnh mà không có sự cho phép."],["無断で休むことはよくありません。","Nghỉ mà không xin phép là không tốt."],["無断で使うことはできません。","Không thể dùng mà không có sự cho phép."],["無断で学校を休みました。","Tôi đã nghỉ học mà không xin phép."]]},{"word":"満たす","reading":"みたす","meaning":"thỏa mãn, đáp ứng","hanViet":"MÃN","lesson":22,"ex":[["条件を満たすことが大切です。","Đáp ứng điều kiện là điều quan trọng."],["彼の話は私の心を満たしました。","Câu chuyện của anh ấy đã làm đầy trái tim tôi."],["必要な条件を満たしています。","Tôi đáp ứng các điều kiện cần thiết."],["必要を満たすのは難しいです。","Đáp ứng nhu cầu rất khó."],["心を満たす音楽が好きです。","Tôi thích âm nhạc làm đầy trái tim."]]},{"word":"再会する","reading":"さいかいする","meaning":"gặp lại, tái ngộ","hanViet":"TÁI HỘI","lesson":22,"ex":[["友達と再会しました。","Tôi đã gặp lại bạn."],["久しぶりに友達と再会しました。","Lâu rồi tôi mới gặp lại bạn."],["再会する日を楽しみにしています。","Tôi đang mong chờ ngày gặp lại."],["東京で再会しましょう。","Hãy gặp lại nhau ở Tokyo."],["再会して、うれしかったです。","Gặp lại nhau, tôi rất vui."]]},{"word":"玩具","reading":"がんぐ","meaning":"đồ chơi","hanViet":"NGOẠN CỤ","lesson":22,"ex":[["玩具で遊ぶのが好きです。","Tôi thích chơi đồ chơi."],["子どもに玩具を買いました。","Tôi đã mua đồ chơi cho trẻ em."],["玩具がたくさんあります。","Có nhiều đồ chơi."],["玩具を箱に入れました。","Tôi đã cho đồ chơi vào hộp."],["古い玩具を捨てました。","Tôi đã vứt đồ chơi cũ."]]},{"word":"粘り強い","reading":"ねばりづよい","meaning":"kiên trì","hanViet":"NIÊM CƯỜNG","lesson":22,"ex":[["粘り強い人は最後まで頑張ります。","Người kiên trì cố gắng đến cuối cùng."],["粘り強く勉強しました。","Tôi đã học kiên trì."],["粘り強い心が大切です。","Trái tim kiên trì rất quan trọng."],["粘り強く頑張ります。","Tôi sẽ cố gắng kiên trì."],["粘り強い人はあきらめません。","Người kiên trì không bỏ cuộc."]]},{"word":"要望する","reading":"ようぼうする","meaning":"yêu cầu, đề nghị","hanViet":"YẾU VỌNG","lesson":22,"ex":[["市民は新しい公園を作ることを市役所に要望しました。","Người dân đã đề nghị tòa thị chính xây công viên mới."],["社員は休みを増やすことを会社に要望しました。","Nhân viên đã đề nghị công ty tăng ngày nghỉ."],["学生は図書館の時間を長くすることを学校に要望しました。","Học sinh đã đề nghị nhà trường kéo dài giờ mở cửa thư viện."],["私たちはもっと安全な道を作ることを要望しました。","Chúng tôi đã đề nghị làm con đường an toàn hơn."],["住民は夜の電車を増やすことを要望しています。","Người dân đang đề nghị tăng chuyến tàu buổi tối."]]},{"word":"息","reading":"いき","meaning":"hơi thở","hanViet":"TỨC","lesson":22,"ex":[["泳ぐ前に、息を大きく吸いました。","Trước khi bơi, tôi đã hít một hơi thật sâu."],["びっくりして、息が止まりました。","Vì giật mình nên tôi nín thở."],["走るときは、息が大切です。","Khi chạy, hơi thở rất quan trọng."],["山を歩いたあと、息が苦しくなりました。","Sau khi đi bộ trên núi, tôi thấy khó thở."],["子どもは寝ているとき、息が静かです。","Khi trẻ ngủ, hơi thở rất nhẹ."]]},{"word":"引き取る","reading":"ひきとる","meaning":"nhận lại, đón về, tiếp nhận","hanViet":"DẪN THỦ","lesson":22,"ex":[["彼は病院で静かに息を引き取りました。","Anh ấy đã trút hơi thở cuối cùng trong bệnh viện một cách bình yên."],["彼女は家族の中で息を引き取りました。","Bà đã trút hơi thở cuối cùng trong vòng tay gia đình."],["長い病気のあと、彼は息を引き取りました。","Sau thời gian dài bị bệnh, anh ấy đã trút hơi thở cuối cùng."],["昔の物語では、人は静かに息を引き取ったと言われています。","Trong câu chuyện xưa, người ta kể rằng con người đã trút hơi thở cuối cùng một cách bình yên."],["息を引き取る前に、彼は家族の名前を言いました。","Trước khi trút hơi thở cuối cùng, anh ấy đã gọi tên gia đình."]]},{"word":"褒めたたえる","reading":"ほめたたえる","meaning":"khen ngợi, ca ngợi","hanViet":"BAO","lesson":22,"ex":[["先生は学生の勉強を褒めたたえました。","Thầy giáo đã ca ngợi việc học của học sinh."],["みんなは彼女の歌を褒めたたえました。","Mọi người đã ca ngợi bài hát của cô ấy."],["社長は社員の仕事を褒めたたえました。","Giám đốc đã ca ngợi công việc của nhân viên."],["人々はその美しい絵を褒めたたえました。","Mọi người đã ca ngợi bức tranh đẹp đó."],["みんなは山田さんの料理を褒めたたえました。","Mọi người đã ca ngợi món ăn của anh Yamada."]]},{"word":"熱意","reading":"ねつい","meaning":"sự hăng hái, sự nhiệt tình","hanViet":"NHIỆT Ý","lesson":22,"ex":[["彼の熱意にみんなは驚きました。","Mọi người ngạc nhiên trước sự nhiệt tình của anh ấy."],["彼女は熱意を持って仕事をしています。","Cô ấy làm việc với sự nhiệt tình."],["学生の熱意はとても強いです。","Sự nhiệt tình của học sinh rất mạnh mẽ."],["熱意があれば、難しい仕事もできます。","Nếu có nhiệt tình, công việc khó cũng làm được."],["彼は熱意を持って新しい仕事を始めました。","Anh ấy đã bắt đầu công việc mới với sự nhiệt tình."]]},{"word":"響く","reading":"ひびく","meaning":"vang","hanViet":"HƯỞNG","lesson":22,"ex":[["山に歌が響きました。","Bài hát vang vọng trên núi."],["大きな音が部屋に響きました。","Âm thanh lớn vang trong phòng."],["彼女の話は心に響きました。","Câu chuyện của cô ấy chạm đến trái tim tôi."],["その音楽は心に響きました。","Âm nhạc đó chạm đến trái tim tôi."],["歌が海に響きました。","Bài hát vang vọng ra biển."]]},{"word":"鑑賞する","reading":"かんしょうする","meaning":"xem, thưởng thức","hanViet":"GIÁM THƯỞNG","lesson":22,"ex":[["私は美術館で絵を鑑賞しました。","Tôi đã thưởng thức tranh ở bảo tàng mỹ thuật."],["みんなで音楽を鑑賞しました。","Mọi người cùng thưởng thức âm nhạc."],["彼は映画を鑑賞するのが好きです。","Anh ấy thích xem phim."],["春に花を鑑賞しました。","Mùa xuân tôi đã thưởng thức hoa."],["私たちは静かに歌を鑑賞しました。","Chúng tôi đã thưởng thức bài hát một cách lặng lẽ."]]},{"word":"訴える","reading":"うったえる","meaning":"tác động mạnh đến lòng người; kêu gọi; kiện, tố cáo","hanViet":"TỐ","lesson":22,"ex":[["その映画は心に強く訴えました。","Bộ phim đó đã tác động mạnh mẽ đến trái tim tôi."],["彼の話は私の心に訴えました。","Câu chuyện của anh ấy đã chạm đến trái tim tôi."],["その歌は多くの人に訴えました。","Bài hát đó đã chạm đến nhiều người."],["彼女の話は心に訴えました。","Câu chuyện của cô ấy đã chạm đến trái tim."],["その本は読む人に深く訴えました。","Cuốn sách đó đã tác động sâu sắc đến người đọc."]]},{"word":"コモンズ","reading":"コモンズ","meaning":"tài nguyên đất đai thuộc sở hữu chung","hanViet":"","lesson":23,"ex":[["コモンズはみんなで使う土地です。","Commons là đất mà mọi người cùng sử dụng."],["海や山は大切なコモンズです。","Biển và núi là commons quan trọng."],["コモンズを守ることは大切です。","Bảo vệ commons là điều quan trọng."],["村の人はコモンズを大切に使います。","Người dân trong làng sử dụng commons một cách cẩn thận."],["コモンズの問題は世界の問題です。","Vấn đề commons là vấn đề của thế giới."]]},{"word":"悲劇","reading":"ひげき","meaning":"thảm kịch, bi kịch","hanViet":"BI KỊCH","lesson":23,"ex":[["その悲劇は今も人々に忘れられません。","Bi kịch đó đến nay mọi người vẫn không thể quên."],["戦争は多くの悲劇を作りました。","Chiến tranh đã tạo ra nhiều bi kịch."],["その悲劇から人々は大切なことを考えました。","Từ bi kịch đó, mọi người đã suy nghĩ về điều quan trọng."],["悲劇をなくすために、みんなで考えます。","Để không còn bi kịch, mọi người cùng suy nghĩ."],["その悲劇は本に書かれています。","Bi kịch đó được viết trong sách."]]},{"word":"地球市民","reading":"ちきゅうしみん","meaning":"công dân toàn cầu","hanViet":"ĐỊA CẦU THỊ DÂN","lesson":23,"ex":[["私たちはみんな地球市民です。","Chúng ta đều là công dân toàn cầu."],["地球市民は環境を守ります。","Công dân toàn cầu bảo vệ môi trường."],["地球市民は世界の問題を考えます。","Công dân toàn cầu suy nghĩ về vấn đề thế giới."],["子どもたちも地球市民です。","Trẻ em cũng là công dân toàn cầu."],["地球市民の心は大切です。","Tấm lòng của công dân toàn cầu rất quan trọng."]]},{"word":"オゾン層","reading":"オゾンそう","meaning":"tầng ozone","hanViet":"TẦNG","lesson":23,"ex":[["オゾン層は地球を守っています。","Tầng ozone đang bảo vệ Trái Đất."],["オゾン層が薄くなると、問題が増えます。","Khi tầng ozone mỏng đi, vấn đề sẽ tăng lên."],["オゾン層を守ることは大切です。","Bảo vệ tầng ozone là điều quan trọng."],["オゾン層は空の上にあります。","Tầng ozone ở trên bầu trời."],["オゾン層について、学校で勉強しました。","Tôi đã học về tầng ozone ở trường."]]},{"word":"熱帯雨林","reading":"ねったいうりん","meaning":"rừng nhiệt đới","hanViet":"NHIỆT ĐÁI VŨ LÂM","lesson":23,"ex":[["熱帯雨林には多くの生物がいます。","Trong rừng nhiệt đới có nhiều sinh vật."],["熱帯雨林は地球の大切な森です。","Rừng nhiệt đới là khu rừng quan trọng của Trái Đất."],["熱帯雨林が減ると、問題が増えます。","Khi rừng nhiệt đới giảm đi, vấn đề sẽ tăng lên."],["熱帯雨林を守ることは大切です。","Bảo vệ rừng nhiệt đới là điều quan trọng."],["熱帯雨林について、本で読みました。","Tôi đã đọc về rừng nhiệt đới trong sách."]]},{"word":"酸性雨","reading":"さんせいう","meaning":"mưa axit","hanViet":"TOAN TÍNH VŨ","lesson":23,"ex":[["酸性雨は森に悪い影響を与えます。","Mưa axit gây ảnh hưởng xấu đến rừng."],["酸性雨は湖の水に影響を与えます。","Mưa axit ảnh hưởng đến nước hồ."],["酸性雨の問題は世界の問題です。","Vấn đề mưa axit là vấn đề thế giới."],["酸性雨について、学校で勉強しました。","Tôi đã học về mưa axit ở trường."],["酸性雨が降ると、植物が弱くなります。","Khi mưa axit rơi, thực vật yếu đi."]]},{"word":"生物","reading":"せいぶつ","meaning":"sinh vật","hanViet":"SINH VẬT","lesson":23,"ex":[["海には多くの生物がいます。","Trong biển có nhiều sinh vật."],["生物は水がなければ生きられません。","Sinh vật không thể sống nếu không có nước."],["森の生物を守ることは大切です。","Bảo vệ sinh vật trong rừng là điều quan trọng."],["生物について、学校で勉強しました。","Tôi đã học về sinh vật ở trường."],["生物はみんな関係があります。","Các sinh vật đều có quan hệ với nhau."]]},{"word":"絶滅する","reading":"ぜつめつする","meaning":"tuyệt chủng, diệt vong","hanViet":"TUYỆT DIỆT","lesson":23,"ex":[["その動物は絶滅しました。","Loài động vật đó đã tuyệt chủng."],["多くの生物が絶滅するかもしれません。","Nhiều sinh vật có thể sẽ tuyệt chủng."],["絶滅する動物を守ることは大切です。","Bảo vệ động vật sắp tuyệt chủng là điều quan trọng."],["その鳥は絶滅する危険があります。","Loài chim đó có nguy cơ tuyệt chủng."],["絶滅する前に、動物を守らなければなりません。","Trước khi tuyệt chủng, chúng ta phải bảo vệ động vật."]]},{"word":"大気汚染","reading":"たいきおせん","meaning":"ô nhiễm không khí","hanViet":"ĐẠI KHÍ Ô NHIỄM","lesson":23,"ex":[["大気汚染は健康に悪い影響を与えます。","Ô nhiễm không khí gây ảnh hưởng xấu đến sức khỏe."],["車が増えると、大気汚染が進みます。","Khi xe tăng lên, ô nhiễm không khí tăng thêm."],["大気汚染をなくすために、みんなで考えます。","Để không còn ô nhiễm không khí, mọi người cùng suy nghĩ."],["大気汚染は世界の問題です。","Ô nhiễm không khí là vấn đề thế giới."],["大気汚染について、新聞で読みました。","Tôi đã đọc về ô nhiễm không khí trên báo."]]},{"word":"大気","reading":"たいき","meaning":"không khí","hanViet":"ĐẠI KHÍ","lesson":23,"ex":[["大気は地球の上にあります。","Không khí ở trên Trái Đất."],["大気が汚くなると、健康に悪いです。","Khi không khí bẩn đi, sức khỏe sẽ xấu đi."],["大気は私たちに酸素を与えます。","Không khí cho chúng ta oxy."],["大気について、学校で勉強しました。","Tôi đã học về không khí ở trường."],["きれいな大気は大切です。","Không khí sạch rất quan trọng."]]},{"word":"汚染する","reading":"おせんする","meaning":"ô nhiễm","hanViet":"Ô NHIỄM","lesson":23,"ex":[["工場は川の水を汚染します。","Nhà máy làm ô nhiễm nước sông."],["車は空気を汚染します。","Xe cộ làm ô nhiễm không khí."],["工場は海を汚染します。","Nhà máy làm ô nhiễm biển."],["川を汚染しないように、気をつけます。","Để không làm ô nhiễm sông, tôi cẩn thận."],["汚染された水は飲めません。","Nước bị ô nhiễm không thể uống được."]]},{"word":"現れる","reading":"あらわれる","meaning":"xuất hiện","hanViet":"HIỆN","lesson":23,"ex":[["春になると、花が現れます。","Khi mùa xuân đến, hoa xuất hiện."],["空に虹が現れました。","Cầu vồng xuất hiện trên bầu trời."],["問題が現れたとき、みんなで考えます。","Khi vấn đề xuất hiện, mọi người cùng suy nghĩ."],["彼の前に、古い友達が現れました。","Trước mặt anh ấy, một người bạn cũ đã xuất hiện."],["新しい方法が現れました。","Một phương pháp mới đã xuất hiện."]]},{"word":"共有地","reading":"きょうゆうち","meaning":"đất sở hữu chung","hanViet":"CỘNG HỮU ĐỊA","lesson":23,"ex":[["共有地はみんなで使います。","Đất sở hữu chung được mọi người cùng sử dụng."],["村の共有地は大切です。","Đất chung của làng rất quan trọng."],["共有地を守ることは大切です。","Bảo vệ đất chung là điều quan trọng."],["共有地の問題は難しいです。","Vấn đề đất chung rất khó."],["共有地で羊を育てます。","Người ta nuôi cừu trên đất chung."]]},{"word":"牧草","reading":"ぼくそう","meaning":"cỏ chăn nuôi, cỏ cho gia súc ăn","hanViet":"MỤC THẢO","lesson":23,"ex":[["農家は羊のために牧草を育てます。","Nông dân trồng cỏ chăn nuôi cho cừu."],["牧草は羊の大切な食べ物です。","Cỏ chăn nuôi là thức ăn quan trọng của cừu."],["牧草は夏にたくさん増えます。","Cỏ chăn nuôi tăng nhiều vào mùa hè."],["馬も牧草を食べます。","Ngựa cũng ăn cỏ chăn nuôi."],["羊は牧草が好きです。","Cừu thích cỏ chăn nuôi."]]},{"word":"羊","reading":"ひつじ","meaning":"con cừu","hanViet":"DƯƠNG","lesson":23,"ex":[["羊は牧草を食べます。","Cừu ăn cỏ chăn nuôi."],["羊は山で暮らします。","Cừu sống trên núi."],["白い羊が森にいます。","Có con cừu trắng trong rừng."],["羊は冬に強いです。","Cừu chịu lạnh tốt vào mùa đông."],["村の人は羊を育てます。","Người dân trong làng nuôi cừu."]]},{"word":"あげる","reading":"あげる","meaning":"tăng (~ lợi nhuận)","hanViet":"","lesson":23,"ex":[["会社は利益をあげました。","Công ty đã tăng lợi nhuận."],["利益をあげるために、みんなで考えます。","Để tăng lợi nhuận, mọi người cùng suy nghĩ."],["店は利益をあげました。","Cửa hàng đã tăng lợi nhuận."],["彼は成績をあげました。","Anh ấy đã cải thiện thành tích."],["会社は来年、利益をあげたいです。","Năm sau, công ty muốn tăng lợi nhuận."]]},{"word":"試み始める","reading":"こころみはじめる","meaning":"bắt đầu thử nghiệm","hanViet":"THÍ THỈ","lesson":23,"ex":[["彼は新しい方法を試み始めました。","Anh ấy đã bắt đầu thử phương pháp mới."],["会社は新しい仕事を試み始めました。","Công ty đã bắt đầu thử công việc mới."],["私たちは環境を守る方法を試み始めました。","Chúng tôi đã bắt đầu thử cách bảo vệ môi trường."],["村の人は新しい方法を試み始めました。","Người dân trong làng đã bắt đầu thử phương pháp mới."],["学生は新しい勉強の方法を試み始めました。","Học sinh đã bắt đầu thử phương pháp học mới."]]},{"word":"試みる","reading":"こころみる","meaning":"thử","hanViet":"THÍ","lesson":23,"ex":[["彼は新しい方法を試みました。","Anh ấy đã thử phương pháp mới."],["新しいことを試みることは大切です。","Thử điều mới là điều quan trọng."],["私は日本語で話すことを試みました。","Tôi đã thử nói bằng tiếng Nhật."],["彼女は新しい仕事を試みました。","Cô ấy đã thử công việc mới."],["失敗しても、また試みます。","Dù thất bại, tôi vẫn thử lại."]]},{"word":"荒廃する","reading":"こうはいする","meaning":"tàn phá, hủy hoại","hanViet":"HOANG PHẾ","lesson":23,"ex":[["森は荒廃しました。","Rừng đã bị tàn phá."],["戦争で町は荒廃しました。","Thành phố đã bị tàn phá bởi chiến tranh."],["土地が荒廃すると、植物が弱くなります。","Khi đất bị tàn phá, thực vật yếu đi."],["荒廃した土地を直すことは難しいです。","Sửa chữa đất bị tàn phá rất khó."],["森が荒廃しないように、守ります。","Để rừng không bị tàn phá, chúng ta bảo vệ nó."]]},{"word":"捨て去る","reading":"すてさる","meaning":"vứt bỏ","hanViet":"XÁ KHỨ","lesson":23,"ex":[["古いものを捨て去ることは難しいです。","Vứt bỏ đồ cũ rất khó."],["彼は悪い習慣を捨て去りました。","Anh ấy đã vứt bỏ thói quen xấu."],["私は古い服を捨て去りました。","Tôi đã vứt bỏ quần áo cũ."],["過去を捨て去って、新しく始めます。","Vứt bỏ quá khứ, tôi bắt đầu mới."],["彼女は悲しい思い出を捨て去りました。","Cô ấy đã vứt bỏ kỷ niệm buồn."]]},{"word":"投稿する","reading":"とうこうする","meaning":"gửi bài viết","hanViet":"ĐẦU CẢO","lesson":23,"ex":[["私は雑誌に記事を投稿しました。","Tôi đã gửi bài viết cho tạp chí."],["彼は新聞に意見を投稿しました。","Anh ấy đã gửi ý kiến cho báo."],["学生はインターネットに意見を投稿しました。","Học sinh đã gửi ý kiến lên internet."],["私は写真を投稿するのが好きです。","Tôi thích đăng ảnh."],["彼女は小説を投稿しました。","Cô ấy đã gửi tiểu thuyết."]]},{"word":"懲りる","reading":"こりる","meaning":"tỉnh ngộ, sáng mắt ra","hanViet":"TRỪNG","lesson":23,"ex":[["彼は失敗して、やっと懲りました。","Sau khi thất bại, cuối cùng anh ấy đã tỉnh ngộ."],["彼女は懲りて、もう同じ間違いをしません。","Cô ấy đã tỉnh ngộ nên không mắc lỗi giống nhau nữa."],["彼は懲りて、もう夜遅く帰りません。","Anh ấy đã tỉnh ngộ nên không về khuya nữa."],["私は懲りて、もう遅れません。","Tôi đã tỉnh ngộ nên không đến muộn nữa."],["彼は懲りたので、気をつけます。","Vì đã tỉnh ngộ nên anh ấy cẩn thận."]]},{"word":"仕組み","reading":"しくみ","meaning":"cơ chế","hanViet":"SĨ TỔ","lesson":23,"ex":[["この仕組みは難しいです。","Cơ chế này rất khó."],["仕組みを知ることは大切です。","Biết cơ chế là điều quan trọng."],["社会の仕組みについて勉強しました。","Tôi đã học về cơ chế xã hội."],["新しい仕組みを作ることは大切です。","Tạo ra cơ chế mới là điều quan trọng."],["この仕組みはみんなを助けます。","Cơ chế này giúp đỡ mọi người."]]},{"word":"掟","reading":"おきて","meaning":"luật lệ","hanViet":"","lesson":23,"ex":[["村には古い掟があります。","Trong làng có luật lệ cổ xưa."],["掟を守ることは大切です。","Tuân thủ luật lệ là điều quan trọng."],["その掟は今も生きています。","Luật lệ đó đến nay vẫn còn hiệu lực."],["掟を守らないと、問題になります。","Nếu không tuân thủ luật lệ, sẽ thành vấn đề."],["村の掟はみんなに知られています。","Luật lệ của làng được mọi người biết đến."]]},{"word":"組み込む","reading":"くみこむ","meaning":"đưa vào","hanViet":"TỔ","lesson":23,"ex":[["会社は新しい方法を仕事に組み込みました。","Công ty đã đưa phương pháp mới vào công việc."],["私たちは環境を守る方法を計画に組み込みました。","Chúng tôi đã đưa cách bảo vệ môi trường vào kế hoạch."],["先生はゲームを授業に組み込みました。","Thầy đã đưa trò chơi vào bài học."],["新しい技術を仕事に組み込みました。","Tôi đã đưa kỹ thuật mới vào công việc."],["彼は物語に自分の経験を組み込みました。","Anh ấy đã lồng kinh nghiệm của mình vào câu chuyện."]]},{"word":"物語","reading":"ものがたり","meaning":"câu chuyện","hanViet":"VẬT NGỮ","lesson":23,"ex":[["その物語は悲しいです。","Câu chuyện đó thật buồn."],["昔の物語はおもしろいです。","Câu chuyện xưa rất thú vị."],["子どもは物語が好きです。","Trẻ em thích câu chuyện."],["物語を読んで、心が温かくなりました。","Đọc câu chuyện, lòng tôi ấm áp."],["彼は新しい物語を書きました。","Anh ấy đã viết câu chuyện mới."]]},{"word":"識者","reading":"しきしゃ","meaning":"người hiểu biết","hanViet":"THỨC GIẢ","lesson":23,"ex":[["識者は環境の問題を話しました。","Người hiểu biết đã nói về vấn đề môi trường."],["識者の意見は大切です。","Ý kiến của người hiểu biết rất quan trọng."],["識者は新しい方法を提案しました。","Người hiểu biết đã đề xuất phương pháp mới."],["識者に意見を聞きました。","Tôi đã nghe ý kiến của người hiểu biết."],["識者は未来の問題を考えます。","Người hiểu biết suy nghĩ về vấn đề tương lai."]]},{"word":"規模","reading":"きぼ","meaning":"quy mô","hanViet":"QUY MÔ","lesson":23,"ex":[["その会社の規模は大きいです。","Quy mô của công ty đó rất lớn."],["問題の規模は大きくなります。","Quy mô của vấn đề ngày càng lớn."],["その祭りの規模は大きいです。","Quy mô của lễ hội đó rất lớn."],["規模が大きいと、費用も大きくなります。","Khi quy mô lớn, chi phí cũng tăng."],["小さい規模から始めることが大切です。","Bắt đầu từ quy mô nhỏ là điều quan trọng."]]},{"word":"直結する","reading":"ちょっけつする","meaning":"kết nối trực tiếp, liên quan trực tiếp","hanViet":"TRỰC KẾT","lesson":23,"ex":[["環境の問題は私たちの生活に直結します。","Vấn đề môi trường liên quan trực tiếp đến cuộc sống của chúng ta."],["健康は食べ物に直結します。","Sức khỏe liên quan trực tiếp đến thức ăn."],["仕事の結果は給料に直結します。","Kết quả công việc liên quan trực tiếp đến lương."],["その問題は未来に直結します。","Vấn đề đó liên quan trực tiếp đến tương lai."],["水の問題は生活に直結します。","Vấn đề nước liên quan trực tiếp đến cuộc sống."]]},{"word":"普遍化","reading":"ふへんか","meaning":"sự phổ quát hóa, trở nên phổ biến rộng rãi","hanViet":"PHỔ BIẾN HÓA","lesson":23,"ex":[["インターネットの普遍化は進みました。","Sự phổ biến rộng rãi của internet đã tiến triển."],["その方法の普遍化は大切です。","Việc phổ biến rộng rãi phương pháp đó rất quan trọng."],["教育の普遍化は世界の問題です。","Việc phổ cập giáo dục là vấn đề thế giới."],["普遍化が進むと、みんなが使えます。","Khi sự phổ biến tiến triển, mọi người đều có thể dùng."],["その技術の普遍化は速いです。","Sự phổ biến của kỹ thuật đó rất nhanh."]]},{"word":"公共圏","reading":"こうきょうけん","meaning":"không gian công cộng (lĩnh vực công)","hanViet":"CÔNG CỘNG KHUYÊN","lesson":23,"ex":[["公共圏はみんなの場所です。","Không gian công cộng là nơi của mọi người."],["公共圏で意見を話すことは大切です。","Nói ý kiến trong không gian công cộng là điều quan trọng."],["インターネットは新しい公共圏です。","Internet là không gian công cộng mới."],["公共圏を守ることは大切です。","Bảo vệ không gian công cộng là điều quan trọng."],["公共圏の問題は難しいです。","Vấn đề không gian công cộng rất khó."]]},{"word":"水資源","reading":"みずしげん","meaning":"tài nguyên nước","hanViet":"THỦY TƯ NGUYÊN","lesson":23,"ex":[["水資源は大切です。","Tài nguyên nước rất quan trọng."],["水資源を守ることは大切です。","Bảo vệ tài nguyên nước là điều quan trọng."],["水資源が減ると、問題が増えます。","Khi tài nguyên nước giảm, vấn đề tăng lên."],["水資源について、学校で勉強しました。","Tôi đã học về tài nguyên nước ở trường."],["世界の水資源は大切です。","Tài nguyên nước của thế giới rất quan trọng."]]},{"word":"山林","reading":"さんりん","meaning":"rừng núi","hanViet":"SƠN LÂM","lesson":23,"ex":[["山林は多くの生物の家です。","Rừng núi là nhà của nhiều sinh vật."],["山林を守ることは大切です。","Bảo vệ rừng núi là điều quan trọng."],["山林が減ると、動物が困ります。","Khi rừng núi giảm đi, động vật gặp khó khăn."],["山林で木を植えました。","Tôi đã trồng cây trong rừng núi."],["山林について、本で読みました。","Tôi đã đọc về rừng núi trong sách."]]},{"word":"河川","reading":"かせん","meaning":"sông","hanViet":"HÀ XUYÊN","lesson":23,"ex":[["河川は人々の生活に大切です。","Sông ngòi rất quan trọng đối với cuộc sống của con người."],["河川を守ることは大切です。","Bảo vệ sông ngòi là điều quan trọng."],["河川の水はきれいです。","Nước sông rất sạch."],["河川について、学校で勉強しました。","Tôi đã học về sông ngòi ở trường."],["河川が汚くなると、魚が困ります。","Khi sông ngòi bẩn đi, cá sẽ gặp khó khăn."]]},{"word":"酸素","reading":"さんそ","meaning":"ôxy","hanViet":"TOAN TỐ","lesson":23,"ex":[["酸素は生物に必要です。","Oxy cần thiết cho sinh vật."],["森は酸素を作ります。","Rừng tạo ra oxy."],["酸素がなければ、生きられません。","Nếu không có oxy, không thể sống được."],["酸素について、学校で勉強しました。","Tôi đã học về oxy ở trường."],["空気には酸素があります。","Trong không khí có oxy."]]},{"word":"少々","reading":"しょうしょう","meaning":"hơi, một chút","hanViet":"THIỂU","lesson":23,"ex":[["少々お待ちください。","Xin chờ một chút."],["少々高いですが、買います。","Hơi đắt nhưng tôi sẽ mua."],["少々疲れました。","Tôi hơi mệt."],["少々寒いです。","Hơi lạnh."],["少々難しいですが、できます。","Hơi khó nhưng tôi làm được."]]},{"word":"海洋","reading":"かいよう","meaning":"đại dương","hanViet":"HẢI DƯƠNG","lesson":23,"ex":[["海洋は地球の大切な部分です。","Đại dương là phần quan trọng của Trái Đất."],["海洋には多くの生物がいます。","Trong đại dương có nhiều sinh vật."],["海洋を守ることは大切です。","Bảo vệ đại dương là điều quan trọng."],["海洋について、学校で勉強しました。","Tôi đã học về đại dương ở trường."],["海洋の水は冷たいです。","Nước đại dương rất lạnh."]]},{"word":"神話","reading":"しんわ","meaning":"chuyện thần thoại","hanViet":"THẦN THOẠI","lesson":23,"ex":[["神話はおもしろいです。","Chuyện thần thoại rất thú vị."],["日本の神話について勉強しました。","Tôi đã học về thần thoại Nhật Bản."],["神話は昔の人の話を伝えます。","Thần thoại truyền lại câu chuyện của người xưa."],["子どもは神話が好きです。","Trẻ em thích thần thoại."],["神話を読んで、昔のことを知りました。","Đọc thần thoại, tôi biết về chuyện xưa."]]},{"word":"道徳","reading":"どうとく","meaning":"đạo đức","hanViet":"ĐẠO ĐỨC","lesson":23,"ex":[["道徳は大切です。","Đạo đức rất quan trọng."],["道徳を守ることは大切です。","Giữ đạo đức là điều quan trọng."],["学校で道徳を勉強します。","Ở trường, tôi học đạo đức."],["道徳について、先生と話しました。","Tôi đã nói chuyện với thầy về đạo đức."],["道徳は社会の大切な部分です。","Đạo đức là phần quan trọng của xã hội."]]},{"word":"支え","reading":"ささえ","meaning":"ủng hộ","hanViet":"CHI","lesson":23,"ex":[["家族の支えは大切です。","Sự ủng hộ của gia đình rất quan trọng."],["友達の支えがあって、頑張れました。","Nhờ sự ủng hộ của bạn bè, tôi đã cố gắng được."],["支えがなければ、続けられません。","Nếu không có sự ủng hộ, tôi không thể tiếp tục."],["先生の支えはありがたいです。","Sự ủng hộ của thầy thật đáng quý."],["支えは心の力になります。","Sự ủng hộ trở thành sức mạnh của lòng."]]},{"word":"自然科学","reading":"しぜんかがく","meaning":"khoa học tự nhiên","hanViet":"TỰ NHIÊN KHOA HỌC","lesson":23,"ex":[["自然科学はおもしろいです。","Khoa học tự nhiên rất thú vị."],["大学で自然科学を勉強します。","Ở đại học, tôi học khoa học tự nhiên."],["自然科学について、本で読みました。","Tôi đã đọc về khoa học tự nhiên trong sách."],["自然科学は世界を知る方法です。","Khoa học tự nhiên là cách hiểu thế giới."],["自然科学と人文科学は違います。","Khoa học tự nhiên và khoa học nhân văn khác nhau."]]},{"word":"人文科学","reading":"じんぶんかがく","meaning":"khoa học nhân văn","hanViet":"NHÂN VĂN KHOA HỌC","lesson":23,"ex":[["人文科学はおもしろいです。","Khoa học nhân văn rất thú vị."],["大学で人文科学を勉強します。","Ở đại học, tôi học khoa học nhân văn."],["人文科学について、本で読みました。","Tôi đã đọc về khoa học nhân văn trong sách."],["人文科学は人の心を勉強します。","Khoa học nhân văn nghiên cứu tâm hồn con người."],["人文科学と自然科学は違います。","Khoa học nhân văn và khoa học tự nhiên khác nhau."]]},{"word":"織り交ぜる","reading":"おりまぜる","meaning":"xen vào, lồng vào","hanViet":"CHỨC GIAO","lesson":23,"ex":[["彼は話に歌を織り交ぜました。","Anh ấy đã xen bài hát vào câu chuyện."],["先生は授業にゲームを織り交ぜました。","Thầy đã xen trò chơi vào bài học."],["彼女は小説に自分の経験を織り交ぜました。","Cô ấy đã lồng kinh nghiệm của mình vào tiểu thuyết."],["授業に歌を織り交ぜると、楽しくなります。","Khi xen bài hát vào bài học, sẽ trở nên vui vẻ hơn."],["彼は歌に物語を織り交ぜました。","Anh ấy đã lồng câu chuyện vào bài hát."]]},{"word":"ジレンマ","reading":"ジレンマ","meaning":"tình trạng khó xử, tình thế tiến thoái lưỡng nan","hanViet":"","lesson":23,"ex":[["彼はジレンマに困っています。","Anh ấy đang khó xử với tình thế tiến thoái lưỡng nan."],["ジレンマは難しい問題です。","Dilemma là vấn đề khó."],["環境と経済のジレンマは大きいです。","Dilemma giữa môi trường và kinh tế rất lớn."],["ジレンマを解決することは難しいです。","Giải quyết dilemma rất khó."],["彼女はジレンマで困っています。","Cô ấy đang khó xử vì dilemma."]]},{"word":"掘り下げる","reading":"ほりさげる","meaning":"đào sâu, hiểu thấu","hanViet":"QUẬT HẠ","lesson":23,"ex":[["問題を掘り下げることは大切です。","Đào sâu vấn đề là điều quan trọng."],["彼は環境の問題を掘り下げました。","Anh ấy đã đào sâu vấn đề môi trường."],["先生は話を掘り下げて、説明しました。","Thầy đã đào sâu câu chuyện và giải thích."],["その問題を掘り下げると、新しいことがわかります。","Khi đào sâu vấn đề đó, bạn sẽ hiểu điều mới."],["私たちは歴史を掘り下げて勉強します。","Chúng tôi học lịch sử một cách đào sâu."]]},{"word":"無数の","reading":"むすうの","meaning":"vô số","hanViet":"VÔ SỐ","lesson":23,"ex":[["空には無数の星があります。","Trên bầu trời có vô số ngôi sao."],["海には無数の生物がいます。","Trong biển có vô số sinh vật."],["無数の問題があります。","Có vô số vấn đề."],["森には無数の木があります。","Trong rừng có vô số cây."],["無数の人がその映画を見ました。","Vô số người đã xem bộ phim đó."]]},{"word":"相互作用","reading":"そうごさよう","meaning":"tương tác qua lại","hanViet":"TƯƠNG HỖ TÁC DỤNG","lesson":23,"ex":[["生物の相互作用は大切です。","Tương tác qua lại giữa các sinh vật rất quan trọng."],["相互作用について、学校で勉強しました。","Tôi đã học về tương tác qua lại ở trường."],["人と自然の相互作用は深いです。","Tương tác giữa con người và thiên nhiên rất sâu sắc."],["相互作用は世界を変えます。","Tương tác thay đổi thế giới."],["相互作用を考えることは大切です。","Suy nghĩ về tương tác là điều quan trọng."]]},{"word":"解決策","reading":"かいけつさく","meaning":"đối sách, giải pháp","hanViet":"GIẢI QUYẾT SÁCH","lesson":23,"ex":[["問題の解決策を考えます。","Tôi suy nghĩ giải pháp cho vấn đề."],["新しい解決策が必要です。","Cần giải pháp mới."],["解決策はまだ見つかりません。","Chưa tìm thấy giải pháp."],["みんなで解決策を考えます。","Mọi người cùng suy nghĩ giải pháp."],["解決策を見つけることは難しいです。","Tìm ra giải pháp rất khó."]]},{"word":"農耕","reading":"のうこう","meaning":"canh tác, trồng trọt","hanViet":"NÔNG CANH","lesson":23,"ex":[["農耕は昔から大切です。","Canh tác quan trọng từ xưa."],["農耕は米を作る仕事です。","Canh tác là công việc trồng lúa."],["農耕について、学校で勉強しました。","Tôi đã học về canh tác ở trường."],["農耕は人々の生活を支えます。","Canh tác nâng đỡ cuộc sống của mọi người."],["農耕の歴史は長いです。","Lịch sử canh tác rất dài."]]},{"word":"教訓","reading":"きょうくん","meaning":"bài học","hanViet":"GIÁO HUẤN","lesson":23,"ex":[["その教訓は大切です。","Bài học đó rất quan trọng."],["失敗から教訓を得ます。","Từ thất bại, tôi rút ra bài học."],["歴史から教訓を得ます。","Từ lịch sử, tôi rút ra bài học."],["教訓を忘れないようにします。","Tôi cố gắng không quên bài học."],["その教訓は今も大切です。","Bài học đó đến nay vẫn quan trọng."]]},{"word":"灌漑","reading":"かんがい","meaning":"thủy lợi, tưới tiêu","hanViet":"QUÁN CÁI","lesson":23,"ex":[["灌漑は土地に水を送ります。","Thủy lợi đưa nước đến đất."],["灌漑は農耕に必要です。","Thủy lợi cần thiết cho canh tác."],["灌漑について、学校で勉強しました。","Tôi đã học về thủy lợi ở trường."],["灌漑は昔から大切です。","Thủy lợi quan trọng từ xưa."],["灌漑の水は川から来ます。","Nước tưới tiêu đến từ sông."]]},{"word":"土壌","reading":"どじょう","meaning":"đất canh tác, thổ nhưỡng","hanViet":"THỔ NHƯỠNG","lesson":23,"ex":[["土壌は植物に大切です。","Thổ nhưỡng quan trọng đối với thực vật."],["土壌が悪いと、植物が弱くなります。","Khi đất xấu, thực vật yếu đi."],["土壌を守ることは大切です。","Bảo vệ thổ nhưỡng là điều quan trọng."],["土壌について、学校で勉強しました。","Tôi đã học về thổ nhưỡng ở trường."],["きれいな土壌は農耕に必要です。","Đất sạch cần thiết cho canh tác."]]},{"word":"塩類","reading":"えんるい","meaning":"các loại muối (hóa học)","hanViet":"DIÊM LOẠI","lesson":23,"ex":[["土壌に塩類が集まります。","Muối tích tụ trong đất."],["塩類が増えると、植物が弱くなります。","Khi muối tăng lên, thực vật yếu đi."],["塩類について、学校で勉強しました。","Tôi đã học về muối ở trường."],["塩類は水の中にあります。","Muối có trong nước."],["塩類の問題は農耕の問題です。","Vấn đề muối là vấn đề canh tác."]]},{"word":"集積する","reading":"しゅうせきする","meaning":"tích tụ","hanViet":"TẬP TÍCH","lesson":23,"ex":[["土壌に塩が集積します。","Muối tích tụ trong đất."],["塩が集積すると、問題になります。","Khi muối tích tụ, sẽ thành vấn đề."],["知識が集積すると、仕事が楽しくなります。","Khi kiến thức tích lũy, công việc trở nên thú vị."],["経験が集積して、仕事が上手になりました。","Kinh nghiệm tích lũy, công việc trở nên giỏi hơn."],["データが集積すると、新しいことがわかります。","Khi dữ liệu tích lũy, bạn sẽ hiểu điều mới."]]},{"word":"縮小する","reading":"しゅくしょうする","meaning":"thu nhỏ, thu hẹp","hanViet":"SÚC TIỂU","lesson":23,"ex":[["会社は仕事を縮小しました。","Công ty đã thu hẹp công việc."],["森が縮小すると、動物が困ります。","Khi rừng thu hẹp, động vật gặp khó khăn."],["工場を縮小することは難しいです。","Thu hẹp nhà máy rất khó."],["会社は費用を縮小しました。","Công ty đã cắt giảm chi phí."],["規模を縮小して、続けます。","Thu hẹp quy mô và tiếp tục."]]},{"word":"海浜","reading":"かいひん","meaning":"ven biển","hanViet":"HẢI BÂN","lesson":23,"ex":[["海浜はきれいです。","Ven biển rất đẹp."],["海浜で遊ぶのが好きです。","Tôi thích chơi ở ven biển."],["海浜を守ることは大切です。","Bảo vệ ven biển là điều quan trọng."],["海浜には多くの生物がいます。","Ở ven biển có nhiều sinh vật."],["海浜について、本で読みました。","Tôi đã đọc về ven biển trong sách."]]},{"word":"消失する","reading":"しょうしつする","meaning":"biến mất","hanViet":"TIÊU THẤT","lesson":23,"ex":[["森が消失しました。","Rừng đã biến mất."],["その動物は消失しました。","Loài động vật đó đã biến mất."],["昔の町は消失しました。","Thị trấn xưa đã biến mất."],["海浜が消失すると、問題になります。","Khi ven biển biến mất, sẽ thành vấn đề."],["消失する前に、守らなければなりません。","Trước khi biến mất, chúng ta phải bảo vệ."]]},{"word":"等々","reading":"とうとう","meaning":"vân vân","hanViet":"ĐẲNG","lesson":23,"ex":[["山、川、海等々、自然は大切です。","Núi, sông, biển vân vân, thiên nhiên rất quan trọng."],["本、雑誌、新聞等々を読みました。","Tôi đã đọc sách, tạp chí, báo vân vân."],["犬、猫、鳥等々、動物が好きです。","Chó, mèo, chim vân vân, tôi thích động vật."],["春、夏、秋等々、季節は変わります。","Xuân, hạ, thu vân vân, các mùa thay đổi."],["先生、学生等々、みんなが集まりました。","Thầy giáo, học sinh vân vân, mọi người đã tập hợp."]]},{"word":"数え上げる","reading":"かぞえあげる","meaning":"đếm từng cái, kể từng cái","hanViet":"SỐ THƯỢNG","lesson":23,"ex":[["星を数え上げることはできません。","Không thể đếm hết các ngôi sao."],["問題を数え上げると、たくさんあります。","Khi đếm từng vấn đề, có rất nhiều."],["彼はゆっくり数を数え上げました。","Anh ấy đã đếm từng số một cách chậm rãi."],["楽しいことを数え上げると、心が温かくなります。","Khi đếm những điều vui, lòng ấm áp."],["森の木を数え上げることは難しいです。","Đếm từng cây trong rừng rất khó."]]},{"word":"きり","reading":"きり","meaning":"giới hạn, điểm kết thúc","hanViet":"","lesson":23,"ex":[["問題はきりがありません。","Vấn đề không có điểm dừng."],["仕事はきりがありません。","Công việc không có điểm dừng."],["勉強はきりがありません。","Việc học không có điểm dừng."],["話はきりがありません。","Câu chuyện không có điểm dừng."],["きりがないほど問題があります。","Có vô số vấn đề."]]},{"word":"つけ","reading":"つけ","meaning":"cái giá phải trả","hanViet":"","lesson":23,"ex":[["悪いことをすると、つけを払います。","Làm điều xấu thì phải trả giá."],["過去のつけを払うときが来ました。","Đã đến lúc trả giá cho quá khứ."],["つけを払う前に、考えます。","Trước khi trả giá, tôi suy nghĩ."],["そのつけは大きいです。","Cái giá đó rất lớn."],["つけを払うのは大変です。","Trả giá rất vất vả."]]},{"word":"事象","reading":"じしょう","meaning":"hiện tượng, sự việc","hanViet":"SỰ TƯỢNG","lesson":23,"ex":[["その事象はおもしろいです。","Hiện tượng đó rất thú vị."],["事象について、学校で勉強しました。","Tôi đã học về hiện tượng ở trường."],["自然の事象は難しいです。","Hiện tượng tự nhiên rất khó."],["事象を調べることは大切です。","Điều tra hiện tượng là điều quan trọng."],["その事象はまだわかっていません。","Hiện tượng đó vẫn chưa được hiểu rõ."]]},{"word":"明確","reading":"めいかく","meaning":"rõ ràng, rành mạch","hanViet":"MINH XÁC","lesson":23,"ex":[["明確な答えが必要です。","Cần câu trả lời rõ ràng."],["彼の話は明確です。","Câu chuyện của anh ấy rất rõ ràng."],["明確に話すことは大切です。","Nói rõ ràng là điều quan trọng."],["目的を明確にすることは大切です。","Làm rõ mục đích là điều quan trọng."],["明確な理由があります。","Có lý do rõ ràng."]]},{"word":"確率","reading":"かくりつ","meaning":"xác suất","hanViet":"XÁC SUẤT","lesson":23,"ex":[["確率は低いです。","Xác suất thấp."],["成功する確率は高いです。","Xác suất thành công cao."],["確率を考えることは大切です。","Suy nghĩ về xác suất là điều quan trọng."],["雨の確率は高いです。","Xác suất mưa cao."],["確率は半分です。","Xác suất là một nửa."]]},{"word":"明らか","reading":"あきらか","meaning":"rõ ràng","hanViet":"MINH","lesson":23,"ex":[["そのことは明らかです。","Điều đó rõ ràng."],["明らかに違います。","Rõ ràng là khác."],["問題は明らかです。","Vấn đề rõ ràng."],["明らかな問題があります。","Có vấn đề rõ ràng."],["彼は明らかに疲れています。","Anh ấy rõ ràng đang mệt."]]},{"word":"不可欠","reading":"ふかけつ","meaning":"không thể thiếu","hanViet":"BẤT KHẢ KHIẾM","lesson":23,"ex":[["水は不可欠です。","Nước không thể thiếu."],["酸素は生物に不可欠です。","Oxy không thể thiếu đối với sinh vật."],["勉強は不可欠です。","Việc học không thể thiếu."],["環境を守ることは不可欠です。","Bảo vệ môi trường là điều không thể thiếu."],["友達は不可欠です。","Bạn bè không thể thiếu."]]},{"word":"段階","reading":"だんかい","meaning":"giai đoạn","hanViet":"ĐOẠN GIAI","lesson":23,"ex":[["仕事には段階があります。","Công việc có các giai đoạn."],["新しい段階に進みます。","Tôi tiến lên giai đoạn mới."],["勉強にも段階があります。","Việc học cũng có các giai đoạn."],["ゆっくり段階を進めます。","Tôi tiến từng giai đoạn một cách chậm rãi."],["仕事の段階は大切です。","Giai đoạn của công việc rất quan trọng."]]},{"word":"記号","reading":"きごう","meaning":"ký hiệu","hanViet":"KÝ HIỆU","lesson":23,"ex":[["その記号は難しいです。","Ký hiệu đó rất khó."],["記号を使って、書きます。","Tôi viết bằng ký hiệu."],["記号の意味を調べました。","Tôi đã tra ý nghĩa của ký hiệu."],["本の記号は多いです。","Ký hiệu trong sách rất nhiều."],["記号を読むことは大切です。","Đọc ký hiệu là điều quan trọng."]]},{"word":"荒れる","reading":"あれる","meaning":"bị tàn phá, bị hủy hoại","hanViet":"HOANG","lesson":23,"ex":[["海が荒れました。","Biển đã dữ dội."],["土地が荒れると、植物が弱くなります。","Khi đất hoang tàn, thực vật yếu đi."],["天気が荒れました。","Thời tiết trở nên xấu."],["森が荒れると、動物が困ります。","Khi rừng hoang tàn, động vật gặp khó khăn."],["荒れた土地を直すことは難しいです。","Sửa chữa đất hoang tàn rất khó."]]},{"word":"植物","reading":"しょくぶつ","meaning":"thực vật","hanViet":"THỰC VẬT","lesson":23,"ex":[["植物は水がなければ生きられません。","Thực vật không thể sống nếu không có nước."],["植物は酸素を作ります。","Thực vật tạo ra oxy."],["植物を育てるのは楽しいです。","Trồng thực vật rất vui."],["植物について、学校で勉強しました。","Tôi đã học về thực vật ở trường."],["森には多くの植物があります。","Trong rừng có nhiều thực vật."]]},{"word":"生育する","reading":"せいいくする","meaning":"phát triển, tăng trưởng","hanViet":"SINH DỤC","lesson":23,"ex":[["植物は水で生育します。","Thực vật phát triển nhờ nước."],["米は水で生育します。","Lúa phát triển nhờ nước."],["魚は海で生育します。","Cá phát triển trong biển."],["子どもは家族の中で生育します。","Trẻ em phát triển trong gia đình."],["植物は太陽で生育します。","Thực vật phát triển nhờ mặt trời."]]},{"word":"工業","reading":"こうぎょう","meaning":"công nghiệp","hanViet":"CÔNG NGHIỆP","lesson":23,"ex":[["工業は大切です。","Công nghiệp rất quan trọng."],["工業は国の経済を支えます。","Công nghiệp nâng đỡ kinh tế đất nước."],["工業について、学校で勉強しました。","Tôi đã học về công nghiệp ở trường."],["工業が進むと、問題も増えます。","Khi công nghiệp phát triển, vấn đề cũng tăng lên."],["工業と環境は関係があります。","Công nghiệp và môi trường có quan hệ."]]},{"word":"種々","reading":"しゅじゅ","meaning":"đa dạng, khác nhau","hanViet":"CHỦNG","lesson":23,"ex":[["この店では、種々の本を売っています。","Cửa hàng này bán đủ loại sách."],["種々の意見が出ました。","Đã có nhiều ý kiến khác nhau được đưa ra."],["先生は種々の問題を出しました。","Thầy giáo đã ra nhiều dạng bài tập khác nhau."],["種々の色の花が咲いています。","Nhiều loài hoa đủ màu đang nở."],["種々の国の人がこの学校で学んでいます。","Người từ nhiều nước khác nhau đang học ở trường này."]]},{"word":"チェックシート","reading":"チェックシート","meaning":"bảng kiểm tra","hanViet":"","lesson":23,"ex":[["仕事の前に、チェックシートを見ます。","Trước khi làm việc, tôi xem bảng kiểm tra."],["チェックシートに名前を書いてください。","Hãy viết tên vào bảng kiểm tra."],["先生はチェックシートで学生の名前を見ます。","Thầy giáo xem tên học sinh bằng bảng kiểm tra."],["このチェックシートはとても便利です。","Bảng kiểm tra này rất tiện lợi."],["旅行の前にチェックシートを作りました。","Tôi đã làm bảng kiểm tra trước chuyến đi."]]},{"word":"温度設定","reading":"おんどせってい","meaning":"thiết đặt nhiệt độ","hanViet":"ÔN ĐỘ THIẾT ĐỊNH","lesson":23,"ex":[["エアコンの温度設定を変えてください。","Hãy thay đổi thiết đặt nhiệt độ của điều hòa."],["温度設定が高すぎます。","Thiết đặt nhiệt độ quá cao."],["温度設定を低くしました。","Tôi đã hạ thiết đặt nhiệt độ xuống."],["冬は温度設定を高くします。","Vào mùa đông, tôi đặt nhiệt độ cao hơn."],["この部屋の温度設定はだれが決めましたか。","Ai đã quyết định thiết đặt nhiệt độ của phòng này?"]]},{"word":"温度","reading":"おんど","meaning":"nhiệt độ","hanViet":"ÔN ĐỘ","lesson":23,"ex":[["今日の温度は高いです。","Nhiệt độ hôm nay cao."],["温度が下がりました。","Nhiệt độ đã giảm."],["水の温度を測ります。","Tôi đo nhiệt độ của nước."],["部屋の温度がちょうどいいです。","Nhiệt độ phòng vừa phải."],["温度が高いと、体が疲れます。","Khi nhiệt độ cao, cơ thể mệt mỏi."]]},{"word":"設定する","reading":"せっていする","meaning":"thiết đặt","hanViet":"THIẾT ĐỊNH","lesson":23,"ex":[["パソコンの時間を設定しました。","Tôi đã thiết đặt thời gian trên máy tính."],["新しいパスワードを設定してください。","Hãy thiết đặt mật khẩu mới."],["目覚まし時計を六時に設定します。","Tôi đặt đồng hồ báo thức lúc 6 giờ."],["先生は試験の時間を設定しました。","Thầy giáo đã thiết đặt thời gian thi."],["この機械の設定を変えました。","Tôi đã thay đổi thiết đặt của máy này."]]},{"word":"クマゲラ","reading":"クマゲラ","meaning":"chim gõ kiến đen","hanViet":"","lesson":23,"ex":[["クマゲラは大きな鳥です。","Chim gõ kiến đen là loài chim lớn."],["森でクマゲラを見ました。","Tôi đã thấy chim gõ kiến đen trong rừng."],["クマゲラは木をたたいて音を出します。","Chim gõ kiến đen gõ vào cây để phát ra tiếng."],["クマゲラの声を聞きました。","Tôi đã nghe tiếng kêu của chim gõ kiến đen."],["この山にはクマゲラが住んでいます。","Trên núi này có chim gõ kiến đen sinh sống."]]},{"word":"林道","reading":"りんどう","meaning":"đường rừng","hanViet":"LÂM ĐẠO","lesson":23,"ex":[["林道を歩きます。","Tôi đi bộ trên đường rừng."],["林道は静かです。","Đường rừng yên tĩnh."],["車で林道を通りました。","Tôi đã đi qua đường rừng bằng ô tô."],["林道の両方に木があります。","Hai bên đường rừng có cây."],["雨の日は林道が滑りやすいです。","Vào ngày mưa, đường rừng dễ trơn."]]},{"word":"鳥類","reading":"ちょうるい","meaning":"loài chim","hanViet":"ĐIỂU LOẠI","lesson":23,"ex":[["鳥類は空を飛びます。","Loài chim bay trên bầu trời."],["この本は鳥類について書かれています。","Cuốn sách này viết về loài chim."],["日本には多くの鳥類がいます。","Ở Nhật Bản có nhiều loài chim."],["鳥類の声が聞こえます。","Nghe thấy tiếng loài chim."],["鳥類を守ることは大切です。","Bảo vệ loài chim là điều quan trọng."]]},{"word":"生息地","reading":"せいそくち","meaning":"môi trường sống","hanViet":"SINH TỨC ĐỊA","lesson":23,"ex":[["この鳥の生息地は森です。","Môi trường sống của loài chim này là rừng."],["生息地が小さくなっています。","Môi trường sống đang thu hẹp lại."],["生息地を守らなければなりません。","Phải bảo vệ môi trường sống."],["動物の生息地を調べます。","Tôi tìm hiểu môi trường sống của động vật."],["この島は鳥の生息地です。","Hòn đảo này là môi trường sống của chim."]]},{"word":"経緯","reading":"けいい","meaning":"quá trình","hanViet":"KINH VĨ","lesson":23,"ex":[["先生は事件の経緯を説明しました。","Thầy giáo đã giải thích diễn biến của sự việc."],["経緯を詳しく話してください。","Hãy kể chi tiết quá trình sự việc."],["この問題の経緯を知っていますか。","Bạn có biết quá trình của vấn đề này không?"],["経緯を調べることが大切です。","Tìm hiểu quá trình là điều quan trọng."],["会議で経緯を話しました。","Tôi đã kể quá trình tại cuộc họp."]]},{"word":"決意する","reading":"けついする","meaning":"quyết định, quyết tâm","hanViet":"QUYẾT Ý","lesson":23,"ex":[["試験に合格しようと決意しました。","Tôi đã quyết tâm đỗ kỳ thi."],["毎日勉強すると決意しました。","Tôi đã quyết tâm học mỗi ngày."],["田中さんは日本に行くと決意しました。","Anh Tanaka đã quyết định đi Nhật."],["新しい仕事を始めると決意しました。","Tôi đã quyết tâm bắt đầu công việc mới."],["決意したことは最後までやります。","Việc đã quyết tâm thì tôi làm đến cùng."]]},{"word":"棲む","reading":"すむ","meaning":"sinh sống","hanViet":"TÊ","lesson":23,"ex":[["この鳥は森に棲んでいます。","Loài chim này sinh sống trong rừng."],["魚は川に棲んでいます。","Cá sinh sống ở sông."],["多くの動物がこの山に棲んでいます。","Nhiều động vật sinh sống trên núi này."],["クマゲラは古い木に棲んでいます。","Chim gõ kiến đen sinh sống trên cây cổ thụ."],["この島には珍しい鳥が棲んでいます。","Trên đảo này có loài chim quý hiếm sinh sống."]]},{"word":"啄木鳥","reading":"きつつき","meaning":"chim gõ kiến","hanViet":"TRÁC MỘC ĐIỂU","lesson":23,"ex":[["啄木鳥は木をたたきます。","Chim gõ kiến gõ vào cây."],["森で啄木鳥を見ました。","Tôi đã thấy chim gõ kiến trong rừng."],["啄木鳥の声が聞こえます。","Nghe thấy tiếng chim gõ kiến."],["啄木鳥は虫を食べます。","Chim gõ kiến ăn côn trùng."],["啄木鳥は木の中に住んでいます。","Chim gõ kiến sống trong cây."]]},{"word":"しっぽ","reading":"しっぽ","meaning":"đuôi","hanViet":"","lesson":23,"ex":[["犬のしっぽが動いています。","Đuôi chó đang vẫy."],["猫はしっぽを上げました。","Mèo đã giơ đuôi lên."],["この鳥はしっぽが長いです。","Loài chim này có đuôi dài."],["犬はうれしいと、しっぽが上がります。","Khi vui, đuôi chó vểnh lên."],["しっぽの色は黒いです。","Màu đuôi là màu đen."]]},{"word":"羽毛","reading":"うもう","meaning":"lông vũ","hanViet":"VŨ MAO","lesson":23,"ex":[["鳥の羽毛は軽いです。","Lông vũ của chim rất nhẹ."],["羽毛の色がきれいです。","Màu lông vũ rất đẹp."],["この鳥は白い羽毛があります。","Loài chim này có lông vũ màu trắng."],["羽毛が風で飛びました。","Lông vũ đã bay theo gió."],["冬は羽毛で体を守ります。","Vào mùa đông, chim bảo vệ cơ thể bằng lông vũ."]]},{"word":"スケッチする","reading":"スケッチする","meaning":"phác thảo, phác họa","hanViet":"","lesson":23,"ex":[["山をスケッチしました。","Tôi đã phác thảo ngọn núi."],["花をスケッチするのが好きです。","Tôi thích phác thảo hoa."],["先生は鳥をスケッチしました。","Thầy giáo đã phác thảo con chim."],["公園で木をスケッチします。","Tôi phác thảo cây trong công viên."],["スケッチした絵を見せてください。","Hãy cho tôi xem bức tranh đã phác thảo."]]},{"word":"偶然","reading":"ぐうぜん","meaning":"ngẫu nhiên","hanViet":"NGẪU NHIÊN","lesson":23,"ex":[["偶然、田中さんに会いました。","Tình cờ, tôi đã gặp anh Tanaka."],["これは偶然ではありません。","Đây không phải là ngẫu nhiên."],["偶然、同じ電車に乗りました。","Tình cờ, chúng tôi lên cùng một chuyến tàu."],["偶然、古い友達に会いました。","Tình cờ, tôi đã gặp người bạn cũ."],["偶然の出会いでした。","Đó là một cuộc gặp gỡ tình cờ."]]},{"word":"ブナ","reading":"ブナ","meaning":"cây Fagus crenata (họ Dẻ – Fagaceae)","hanViet":"","lesson":23,"ex":[["ブナは大きな木です。","Cây buna là cây lớn."],["森にブナがたくさんあります。","Trong rừng có nhiều cây buna."],["ブナの葉は秋に黄色くなります。","Lá cây buna chuyển sang màu vàng vào mùa thu."],["ブナの木の下で休みました。","Tôi đã nghỉ dưới gốc cây buna."],["この山でブナを見ました。","Tôi đã thấy cây buna trên núi này."]]},{"word":"原生林","reading":"げんせいりん","meaning":"rừng nguyên sinh","hanViet":"NGUYÊN SINH LÂM","lesson":23,"ex":[["原生林は大切な自然です。","Rừng nguyên sinh là thiên nhiên quý giá."],["原生林を守らなければなりません。","Phải bảo vệ rừng nguyên sinh."],["原生林には多くの動物がいます。","Trong rừng nguyên sinh có nhiều động vật."],["原生林を歩きました。","Tôi đã đi bộ trong rừng nguyên sinh."],["この原生林は有名です。","Rừng nguyên sinh này nổi tiếng."]]},{"word":"多種多様","reading":"たしゅたよう","meaning":"đa chủng loại","hanViet":"ĐA CHỦNG ĐA DẠNG","lesson":23,"ex":[["この店には多種多様な品があります。","Cửa hàng này có đa dạng các loại hàng hóa."],["多種多様な花が咲いています。","Nhiều loại hoa đa dạng đang nở."],["日本には多種多様な食べ物があります。","Ở Nhật có nhiều món ăn đa dạng."],["多種多様な意見を聞きました。","Tôi đã nghe nhiều ý kiến đa dạng."],["多種多様な文化があります。","Có nhiều nền văn hóa đa dạng."]]},{"word":"動植物","reading":"どうしょくぶつ","meaning":"động thực vật","hanViet":"ĐỘNG THỰC VẬT","lesson":23,"ex":[["動植物を守ることは大切です。","Bảo vệ động thực vật là điều quan trọng."],["この森には多くの動植物がいます。","Trong rừng này có nhiều động thực vật."],["動植物について勉強します。","Tôi học về động thực vật."],["動植物の写真を撮りました。","Tôi đã chụp ảnh động thực vật."],["動植物は自然の中で生きています。","Động thực vật đang sống trong thiên nhiên."]]},{"word":"使い道","reading":"つかいみち","meaning":"cách sử dụng","hanViet":"SỬ ĐẠO","lesson":23,"ex":[["この道具の使い道を教えてください。","Hãy chỉ cho tôi cách sử dụng dụng cụ này."],["使い道がわかりません。","Tôi không biết cách sử dụng."],["古い本の使い道を考えます。","Tôi nghĩ về cách sử dụng sách cũ."],["この箱の使い道は多いです。","Hộp này có nhiều cách sử dụng."],["使い道を説明します。","Tôi giải thích cách sử dụng."]]},{"word":"木材","reading":"もくざい","meaning":"gỗ","hanViet":"MỘC TÀI","lesson":23,"ex":[["この家は木材で作られています。","Ngôi nhà này được làm bằng gỗ."],["木材を切ります。","Tôi cắt gỗ."],["木材の値段が上がりました。","Giá gỗ đã tăng."],["木材は大切な材料です。","Gỗ là vật liệu quan trọng."],["森から木材を運びます。","Tôi vận chuyển gỗ từ rừng."]]},{"word":"狭める","reading":"せばめる","meaning":"thu hẹp","hanViet":"HIỆP","lesson":23,"ex":[["道を狭めました。","Tôi đã thu hẹp con đường."],["部屋を狭めるのはよくありません。","Thu hẹp phòng không tốt."],["入口を狭めました。","Tôi đã thu hẹp lối vào."],["目を狭めて見ました。","Tôi nheo mắt nhìn."],["道路を狭める工事をしています。","Đang thi công thu hẹp đường."]]},{"word":"保護する","reading":"ほごする","meaning":"bảo vệ","hanViet":"BẢO HỘ","lesson":23,"ex":[["動物を保護します。","Tôi bảo vệ động vật."],["自然を保護することは大切です。","Bảo vệ thiên nhiên là điều quan trọng."],["国は鳥を保護しています。","Nhà nước đang bảo vệ loài chim."],["子どもを保護しなければなりません。","Phải bảo vệ trẻ em."],["この法律は環境を保護します。","Luật này bảo vệ môi trường."]]},{"word":"巣作り","reading":"すづくり","meaning":"làm tổ","hanViet":"SÀO TÁC","lesson":23,"ex":[["鳥は春に巣作りをします。","Chim làm tổ vào mùa xuân."],["巣作りは大変な仕事です。","Làm tổ là công việc vất vả."],["鳥の巣作りを見ました。","Tôi đã xem chim làm tổ."],["巣作りのために、鳥は木の枝を集めます。","Để làm tổ, chim thu thập cành cây."],["巣作りが終わりました。","Việc làm tổ đã xong."]]},{"word":"ねぐら","reading":"ねぐら","meaning":"nơi chim đậu","hanViet":"","lesson":23,"ex":[["鳥は夜にねぐらに帰ります。","Chim trở về chỗ đậu vào ban đêm."],["この木は鳥のねぐらです。","Cây này là chỗ đậu của chim."],["ねぐらで鳥が休んでいます。","Chim đang nghỉ ở chỗ đậu."],["鳥のねぐらを守ります。","Tôi bảo vệ chỗ đậu của chim."],["夕方、鳥がねぐらに戻ります。","Vào buổi chiều, chim trở về chỗ đậu."]]},{"word":"天然記念物","reading":"てんねんきねんぶつ","meaning":"di tích thiên nhiên (được nhà nước chỉ định bảo tồn)","hanViet":"THIÊN NHIÊN KÝ NIỆM VẬT","lesson":23,"ex":[["クマゲラは天然記念物です。","Chim gõ kiến đen là di tích thiên nhiên."],["この鳥は天然記念物になりました。","Loài chim này đã trở thành di tích thiên nhiên."],["天然記念物を守らなければなりません。","Phải bảo vệ di tích thiên nhiên."],["天然記念物は国の宝です。","Di tích thiên nhiên là báu vật của đất nước."],["この木は天然記念物です。","Cây này là di tích thiên nhiên."]]},{"word":"危惧する","reading":"きぐする","meaning":"lo ngại, e ngại (điều xấu có thể xảy ra)","hanViet":"NGUY CỤ","lesson":23,"ex":[["環境が変わることを危惧しています。","Tôi lo ngại môi trường sẽ thay đổi."],["先生は学生の健康を危惧しています。","Thầy giáo lo ngại về sức khỏe của học sinh."],["多くの人が将来を危惧しています。","Nhiều người lo ngại về tương lai."],["天気が悪くなることを危惧しました。","Tôi đã lo ngại thời tiết sẽ xấu đi."],["危惧する人が増えています。","Số người lo ngại đang tăng lên."]]},{"word":"種","reading":"しゅ","meaning":"loài, giống (nói chung)","hanViet":"CHỦNG","lesson":23,"ex":[["この種の鳥は珍しいです。","Loài chim này rất quý hiếm."],["新しい種が見つかりました。","Đã phát hiện ra loài mới."],["多くの種が絶滅の危険にあります。","Nhiều loài đang có nguy cơ tuyệt chủng."],["この種の花は日本にしかありません。","Loài hoa này chỉ có ở Nhật Bản."],["種を守ることは大切です。","Bảo vệ các loài là điều quan trọng."]]},{"word":"世界自然遺産","reading":"せかいしぜんいさん","meaning":"di sản thiên nhiên thế giới","hanViet":"THẾ GIỚI TỰ NHIÊN DI SẢN","lesson":23,"ex":[["この山は世界自然遺産です。","Ngọn núi này là di sản thiên nhiên thế giới."],["世界自然遺産を守らなければなりません。","Phải bảo vệ di sản thiên nhiên thế giới."],["世界自然遺産は国の宝です。","Di sản thiên nhiên thế giới là báu vật của đất nước."],["世界自然遺産を見に行きました。","Tôi đã đi xem di sản thiên nhiên thế giới."],["この島は世界自然遺産に登録されています。","Hòn đảo này đã được đăng ký là di sản thiên nhiên thế giới."]]},{"word":"自然遺産","reading":"しぜんいさん","meaning":"di sản thiên nhiên","hanViet":"TỰ NHIÊN DI SẢN","lesson":23,"ex":[["この森は自然遺産です。","Rừng này là di sản thiên nhiên."],["自然遺産を守ることは大切です。","Bảo vệ di sản thiên nhiên là điều quan trọng."],["自然遺産の数は増えています。","Số lượng di sản thiên nhiên đang tăng lên."],["自然遺産を見学しました。","Tôi đã tham quan di sản thiên nhiên."],["日本には自然遺産があります。","Ở Nhật Bản có di sản thiên nhiên."]]},{"word":"農地","reading":"のうち","meaning":"đất nông nghiệp","hanViet":"NÔNG ĐỊA","lesson":23,"ex":[["農地が広がっています。","Đất nông nghiệp đang mở rộng."],["農地で米を作ります。","Tôi trồng lúa trên đất nông nghiệp."],["農地を守らなければなりません。","Phải bảo vệ đất nông nghiệp."],["この村には広い農地があります。","Làng này có đất nông nghiệp rộng."],["農地が少なくなっています。","Đất nông nghiệp đang ít đi."]]},{"word":"拡大する","reading":"かくだいする","meaning":"mở rộng","hanViet":"KHUẾCH ĐẠI","lesson":23,"ex":[["会社は店を拡大しました。","Công ty đã mở rộng cửa hàng."],["農地を拡大します。","Tôi mở rộng đất nông nghiệp."],["仕事の範囲が拡大しました。","Phạm vi công việc đã mở rộng."],["店を拡大するために、お金を借りました。","Để mở rộng cửa hàng, tôi đã vay tiền."],["この計画は町を拡大します。","Kế hoạch này sẽ mở rộng thị trấn."]]},{"word":"変動する","reading":"へんどうする","meaning":"biến đổi","hanViet":"BIẾN ĐỘNG","lesson":23,"ex":[["値段が変動します。","Giá cả biến động."],["気温が変動します。","Nhiệt độ biến động."],["人口が変動しています。","Dân số đang biến động."],["天気が変動しやすいです。","Thời tiết dễ thay đổi."],["経済が変動しています。","Kinh tế đang biến động."]]},{"word":"絡み合う","reading":"からみあう","meaning":"đan xen","hanViet":"LẠC HỢP","lesson":23,"ex":[["糸が絡み合っています。","Các sợi chỉ đang đan xen nhau."],["問題が絡み合っています。","Các vấn đề đan xen nhau."],["枝が絡み合っています。","Cành cây đang đan xen nhau."],["関係が絡み合っています。","Các mối quan hệ đan xen nhau."],["糸が絡み合って、使えません。","Chỉ đan xen nhau nên không dùng được."]]},{"word":"持続する","reading":"じぞくする","meaning":"kéo dài, duy trì","hanViet":"TRÌ TỤC","lesson":23,"ex":[["雨が長く持続しました。","Mưa đã kéo dài lâu."],["努力を持続することが大切です。","Duy trì nỗ lực là điều quan trọng."],["この仕事を持続します。","Tôi duy trì công việc này."],["健康を持続するために、運動します。","Để duy trì sức khỏe, tôi tập thể dục."],["関係を持続することは難しいです。","Duy trì mối quan hệ rất khó."]]},{"word":"食糧","reading":"しょくりょう","meaning":"lương thực","hanViet":"THỰC LƯƠNG","lesson":23,"ex":[["食糧が足りません。","Lương thực không đủ."],["食糧を大切にします。","Tôi trân trọng lương thực."],["食糧の値段が上がりました。","Giá lương thực đã tăng."],["国は食糧を集めています。","Nhà nước đang thu thập lương thực."],["食糧が少なくなっています。","Lương thực đang ít đi."]]},{"word":"清聴","reading":"せいちょう","meaning":"sự chú ý lắng nghe","hanViet":"THANH THÍNH","lesson":23,"ex":[["ご清聴ありがとうございました。","Cảm ơn quý vị đã chú ý lắng nghe."],["ご清聴をお願いします。","Xin quý vị chú ý lắng nghe."],["皆さんのご清聴に感謝します。","Tôi cảm ơn sự chú ý lắng nghe của mọi người."],["最後までご清聴ください。","Xin hãy lắng nghe đến cuối."],["ご清聴ありがとうございます。","Cảm ơn quý vị đã chú ý lắng nghe."]]},{"word":"砂浜","reading":"すなはま","meaning":"bãi biển","hanViet":"SA BÂN","lesson":23,"ex":[["砂浜を歩きました。","Tôi đã đi bộ trên bãi biển."],["砂浜で遊びました。","Tôi đã chơi trên bãi biển."],["砂浜はきれいです。","Bãi biển rất đẹp."],["砂浜に子どもがいます。","Trên bãi biển có trẻ em."],["砂浜で本を読みました。","Tôi đã đọc sách trên bãi biển."]]},{"word":"打ち寄せる","reading":"うちよせる","meaning":"vỗ bờ, đánh vào bờ","hanViet":"ĐẢ KÝ","lesson":23,"ex":[["波が砂浜に打ち寄せます。","Sóng vỗ vào bãi biển."],["波が打ち寄せる音が大きいです。","Tiếng sóng vỗ rất lớn."],["海の波が打ち寄せる音が聞こえます。","Nghe thấy tiếng sóng biển vỗ bờ."],["波が打ち寄せて、音がします。","Sóng vỗ vào, phát ra tiếng."],["大きな波が打ち寄せました。","Sóng lớn đã vỗ vào bờ."]]},{"word":"現状","reading":"げんじょう","meaning":"hiện trạng","hanViet":"HIỆN TRẠNG","lesson":23,"ex":[["現状を知ることが大切です。","Biết hiện trạng là điều quan trọng."],["現状を変えたいです。","Tôi muốn thay đổi hiện trạng."],["現状を説明します。","Tôi giải thích hiện trạng."],["現状はよくありません。","Hiện trạng không tốt."],["現状を調べました。","Tôi đã tìm hiểu hiện trạng."]]},{"word":"街並み","reading":"まちなみ","meaning":"dãy phố","hanViet":"NHAI TỊNH","lesson":23,"ex":[["京都の街並みは美しいです。","Dãy phố ở Kyoto rất đẹp."],["古い街並みが残っています。","Dãy phố cổ vẫn còn lại."],["街並みを歩きました。","Tôi đã đi bộ qua dãy phố."],["街並みが変わりました。","Dãy phố đã thay đổi."],["この町の街並みが好きです。","Tôi thích dãy phố của thị trấn này."]]},{"word":"故郷","reading":"こきょう","meaning":"quê nhà","hanViet":"CỐ HƯƠNG","lesson":23,"ex":[["故郷に帰りたいです。","Tôi muốn trở về quê nhà."],["故郷の山が懐かしいです。","Tôi nhớ núi ở quê nhà."],["故郷の友達に会いました。","Tôi đã gặp bạn ở quê nhà."],["故郷の食べ物が食べたいです。","Tôi muốn ăn món ăn quê nhà."],["故郷は海の近くにあります。","Quê nhà tôi ở gần biển."]]},{"word":"たびたび","reading":"たびたび","meaning":"thường xuyên, nhiều lần","hanViet":"","lesson":23,"ex":[["たびたび、田中さんに会います。","Tôi thường xuyên gặp anh Tanaka."],["たびたび、同じ間違いをします。","Tôi thường xuyên mắc cùng một lỗi."],["たびたび、雨が降ります。","Trời thường xuyên mưa."],["たびたび、故郷に帰ります。","Tôi thường xuyên trở về quê nhà."],["たびたび、先生に質問します。","Tôi thường xuyên hỏi thầy giáo."]]},{"word":"自国","reading":"じこく","meaning":"tổ quốc mình, đất nước mình","hanViet":"TỰ QUỐC","lesson":23,"ex":[["自国の文化が好きです。","Tôi thích văn hóa của đất nước mình."],["自国の食べ物が懐かしいです。","Tôi nhớ món ăn của đất nước mình."],["自国に帰りたいです。","Tôi muốn trở về đất nước mình."],["自国の歴史を勉強します。","Tôi học lịch sử của đất nước mình."],["自国の歌を歌います。","Tôi hát bài hát của đất nước mình."]]},{"word":"引き寄せる","reading":"ひきよせる","meaning":"kéo lại gần","hanViet":"DẪN KÝ","lesson":23,"ex":[["ひもを引き寄せました。","Tôi đã kéo sợi dây lại gần."],["子どもを引き寄せました。","Tôi đã kéo đứa trẻ lại gần."],["かばんを引き寄せて、座りました。","Tôi kéo túi lại gần rồi ngồi xuống."],["網を引き寄せました。","Tôi đã kéo lưới lại gần."],["彼の話は人の心を引き寄せます。","Câu chuyện của anh ấy thu hút lòng người."]]},{"word":"事例","reading":"じれい","meaning":"trường hợp","hanViet":"SỰ LỆ","lesson":23,"ex":[["この事例は有名です。","Trường hợp này nổi tiếng."],["事例を調べました。","Tôi đã tìm hiểu trường hợp này."],["事例を紹介します。","Tôi giới thiệu trường hợp này."],["同じ事例がまだあります。","Vẫn còn trường hợp tương tự."],["事例から学ぶことが多いです。","Có nhiều điều học được từ trường hợp này."]]},{"word":"国内","reading":"こくない","meaning":"trong nước","hanViet":"QUỐC NỘI","lesson":23,"ex":[["国内の旅行が好きです。","Tôi thích du lịch trong nước."],["国内に工場があります。","Trong nước có nhà máy."],["国内のニュースを見ます。","Tôi xem tin tức trong nước."],["国内の人口が減っています。","Dân số trong nước đang giảm."],["国内で作られた品です。","Đây là hàng hóa được làm trong nước."]]},{"word":"実り","reading":"みのり","meaning":"thành quả","hanViet":"THỰC","lesson":23,"ex":[["努力の実りがありました。","Nỗ lực đã có thành quả."],["秋は実りの季節です。","Mùa thu là mùa thu hoạch."],["実りを喜びます。","Tôi vui mừng vì thành quả."],["長い勉強の実りが出ました。","Việc học lâu dài đã có thành quả."],["実りの多い一日でした。","Đó là một ngày nhiều thành quả."]]},{"word":"学力","reading":"がくりょく","meaning":"học lực","hanViet":"HỌC LỰC","lesson":23,"ex":[["学力が上がりました。","Học lực đã tăng lên."],["学力を上げることが大切です。","Nâng cao học lực là điều quan trọng."],["毎日勉強して、学力をつけます。","Học mỗi ngày để nâng cao học lực."],["学力は人によって違います。","Học lực khác nhau tùy người."],["学力を測る試験です。","Đây là kỳ thi đo học lực."]]},{"word":"努力家","reading":"どりょくか","meaning":"người chăm chỉ nỗ lực","hanViet":"NỖ LỰC GIA","lesson":23,"ex":[["田中さんは努力家です。","Anh Tanaka là người chăm chỉ nỗ lực."],["努力家の人は人気があります。","Người chăm chỉ nỗ lực được yêu mến."],["努力家になりたいです。","Tôi muốn trở thành người chăm chỉ nỗ lực."],["努力家は毎日勉強します。","Người chăm chỉ nỗ lực học mỗi ngày."],["努力家のおかげで、仕事が進みました。","Nhờ người chăm chỉ nỗ lực, công việc đã tiến triển."]]},{"word":"非常時","reading":"ひじょうじ","meaning":"khi khẩn cấp","hanViet":"PHI THƯỜNG THỜI","lesson":23,"ex":[["非常時には、このボタンを押してください。","Khi khẩn cấp, hãy bấm nút này."],["非常時のために、水を用意します。","Tôi chuẩn bị nước cho trường hợp khẩn cấp."],["非常時には、落ち着いてください。","Khi khẩn cấp, hãy bình tĩnh."],["非常時の電話番号を知っていますか。","Bạn có biết số điện thoại khẩn cấp không?"],["非常時には、先生の話を聞きます。","Khi khẩn cấp, tôi nghe lời thầy giáo."]]},{"word":"本店","reading":"ほんてん","meaning":"cửa hàng chính, chi nhánh chính","hanViet":"BỔN ĐIẾM","lesson":23,"ex":[["本店は東京にあります。","Cửa hàng chính ở Tokyo."],["本店で買い物をしました。","Tôi đã mua sắm ở cửa hàng chính."],["本店は大きいです。","Cửa hàng chính rất lớn."],["本店の場所を教えてください。","Hãy chỉ cho tôi địa điểm cửa hàng chính."],["本店に電話しました。","Tôi đã gọi điện đến cửa hàng chính."]]},{"word":"閉店する","reading":"へいてんする","meaning":"đóng cửa","hanViet":"BẾ ĐIẾM","lesson":23,"ex":[["この店は九時に閉店します。","Cửa hàng này đóng cửa lúc 9 giờ."],["店が閉店しました。","Cửa hàng đã đóng cửa."],["閉店する前に、買い物をします。","Tôi mua sắm trước khi cửa hàng đóng cửa."],["閉店の時間を知っていますか。","Bạn có biết giờ đóng cửa không?"],["この店は日曜日に閉店します。","Cửa hàng này đóng cửa vào chủ nhật."]]},{"word":"ワールドカップ","reading":"ワールドカップ","meaning":"cúp vô địch thế giới","hanViet":"","lesson":23,"ex":[["ワールドカップを見ます。","Tôi xem World Cup."],["ワールドカップは有名な大会です。","World Cup là giải đấu nổi tiếng."],["ワールドカップの試合を見ました。","Tôi đã xem trận đấu World Cup."],["ワールドカップに出たいです。","Tôi muốn tham gia World Cup."],["ワールドカップのチケットを買いました。","Tôi đã mua vé World Cup."]]},{"word":"転ばぬ先の杖","reading":"ころばぬさきのつえ","meaning":"phòng bệnh hơn chữa bệnh","hanViet":"CHUYỂN TIÊN TRƯỢNG","lesson":23,"ex":[["転ばぬ先の杖ということわざがあります。","Có câu tục ngữ phòng bệnh hơn chữa bệnh."],["転ばぬ先の杖の気持ちで、用意をします。","Với tinh thần phòng bệnh hơn chữa bệnh, tôi chuẩn bị trước."],["転ばぬ先の杖だと思って、傘を持って行きます。","Nghĩ rằng phòng bệnh hơn chữa bệnh, tôi mang theo ô."],["転ばぬ先の杖ですから、薬を用意しました。","Vì phòng bệnh hơn chữa bệnh, tôi đã chuẩn bị thuốc."],["転ばぬ先の杖の意味を知っていますか。","Bạn có biết ý nghĩa của câu phòng bệnh hơn chữa bệnh không?"]]},{"word":"杖","reading":"つえ","meaning":"cây gậy","hanViet":"TRƯỢNG","lesson":23,"ex":[["お年寄りは杖を使います。","Người già dùng gậy."],["杖をついて歩きます。","Tôi chống gậy đi bộ."],["杖が折れました。","Cây gậy đã gãy."],["山登りで杖を使います。","Tôi dùng gậy khi leo núi."],["杖を買いました。","Tôi đã mua cây gậy."]]},{"word":"朝令暮改","reading":"ちょうれいぼかい","meaning":"hay thay đổi","hanViet":"TRIỀU LỆNH MỘ CẢI","lesson":23,"ex":[["朝令暮改はいけません。","Hay thay đổi như vậy là không tốt."],["朝令暮改では、仕事が進みません。","Nếu hay thay đổi, công việc sẽ không tiến triển."],["計画が朝令暮改です。","Kế hoạch hay thay đổi."],["朝令暮改では、人はついてきません。","Nếu hay thay đổi, mọi người sẽ không theo."],["朝令暮改をしないでください。","Xin đừng hay thay đổi."]]},{"word":"品","reading":"しな","meaning":"vật phẩm, hàng hóa","hanViet":"PHẨM","lesson":23,"ex":[["この店にはいい品があります。","Cửa hàng này có hàng hóa tốt."],["品を買いました。","Tôi đã mua hàng hóa."],["品の値段が高いです。","Giá hàng hóa cao."],["品を選びます。","Tôi chọn hàng hóa."],["日本の品が好きです。","Tôi thích hàng hóa Nhật Bản."]]},{"word":"愛情","reading":"あいじょう","meaning":"tình yêu thương","hanViet":"ÁI TÌNH","lesson":23,"ex":[["母の愛情は深いです。","Tình yêu thương của mẹ rất sâu sắc."],["愛情を持って、子どもを育てます。","Tôi nuôi dạy con với tình yêu thương."],["愛情が伝わります。","Tình yêu thương được truyền đạt."],["先生の愛情を感じます。","Tôi cảm nhận được tình yêu thương của thầy giáo."],["愛情のある家庭です。","Đó là gia đình đầy tình yêu thương."]]},{"word":"引っ張る","reading":"ひっぱる","meaning":"kéo","hanViet":"DẪN TRƯƠNG","lesson":23,"ex":[["ひもを引っ張ります。","Tôi kéo sợi dây."],["犬がひもを引っ張っています。","Chó đang kéo sợi dây."],["荷物を引っ張って運びます。","Tôi kéo hành lý để vận chuyển."],["ドアを引っ張って開けます。","Tôi kéo cửa để mở."],["子どもの手を引っ張りました。","Tôi đã kéo tay đứa trẻ."]]},{"word":"進む","reading":"すすむ","meaning":"tiến triển, tiến lên (nói chung)","hanViet":"TIẾN","lesson":23,"ex":[["調査が進んでいます。","Cuộc điều tra đang tiến triển."],["仕事が進みました。","Công việc đã tiến triển."],["計画が進んでいます。","Kế hoạch đang tiến triển."],["勉強が進みました。","Việc học đã tiến triển."],["車が前に進みます。","Xe tiến về phía trước."]]},{"word":"機器","reading":"きき","meaning":"thiết bị, máy móc","hanViet":"CƠ KHÍ","lesson":23,"ex":[["新しい機器を買いました。","Tôi đã mua thiết bị mới."],["機器の使い道がわかりません。","Tôi không biết cách dùng thiết bị."],["機器を調べます。","Tôi kiểm tra thiết bị."],["この機器は便利です。","Thiết bị này rất tiện lợi."],["機器が壊れました。","Thiết bị đã hỏng."]]},{"word":"薄れる","reading":"うすれる","meaning":"nhạt dần, vơi đi (màu, ký ức, cảm xúc nói chung)","hanViet":"BẠC","lesson":23,"ex":[["悲しみが薄れました。","Nỗi buồn đã vơi đi."],["記憶が薄れています。","Ký ức đang nhạt dần."],["不安が薄れました。","Nỗi lo lắng đã vơi đi."],["色が薄れました。","Màu sắc đã nhạt đi."],["時間がたつと、悲しみが薄れます。","Khi thời gian trôi qua, nỗi buồn vơi đi."]]},{"word":"高まる","reading":"たかまる","meaning":"tăng lên, dâng cao (nói chung)","hanViet":"CAO","lesson":23,"ex":[["気温が高まります。","Nhiệt độ tăng lên."],["期待が高まっています。","Kỳ vọng đang tăng lên."],["人気が高まっています。","Sự yêu thích đang tăng lên."],["気持ちが高まります。","Cảm xúc dâng cao."],["試合の前に、人気が高まりました。","Trước trận đấu, sự yêu thích đã tăng lên."]]},{"word":"染まる","reading":"そまる","meaning":"nhuốm màu","hanViet":"NHIỄM","lesson":23,"ex":[["空が赤く染まりました。","Bầu trời đã nhuốm màu đỏ."],["山が緑に染まります。","Núi nhuốm màu xanh lá."],["夕方、空が赤く染まりました。","Vào buổi chiều, bầu trời đã nhuốm màu đỏ."],["葉が黄色に染まります。","Lá nhuốm màu vàng."],["白い紙が青く染まりました。","Giấy trắng đã nhuốm màu xanh."]]},{"word":"訪ねる","reading":"たずねる","meaning":"thăm, viếng","hanViet":"PHỎNG","lesson":23,"ex":[["友達を訪ねました。","Tôi đã thăm bạn."],["京都を訪ねました。","Tôi đã thăm Kyoto."],["先生を訪ねて、質問しました。","Tôi đã thăm thầy giáo và hỏi."],["故郷を訪ねたいです。","Tôi muốn thăm quê nhà."],["田中さんを訪ねました。","Tôi đã thăm anh Tanaka."]]},{"word":"イエス","reading":"イエス","meaning":"đồng ý (yes)","hanViet":"","lesson":23,"ex":[["イエスと言いました。","Tôi đã nói đồng ý."],["イエスと言う人もいます。","Cũng có người nói đồng ý."],["彼はイエスと答えました。","Anh ấy đã trả lời đồng ý."],["イエスと言うのは簡単です。","Nói đồng ý thì dễ dàng."],["イエスと言って、手を上げました。","Tôi đã nói đồng ý và giơ tay lên."]]},{"word":"真偽","reading":"しんぎ","meaning":"đúng sai","hanViet":"CHÂN NGỤY","lesson":23,"ex":[["真偽を確かめます。","Tôi xác minh đúng sai."],["その話の真偽はわかりません。","Tôi không biết đúng sai của câu chuyện đó."],["真偽を調べることが大切です。","Xác minh đúng sai là điều quan trọng."],["ニュースの真偽を確かめます。","Tôi xác minh đúng sai của tin tức."],["真偽がはっきりしません。","Đúng sai chưa rõ ràng."]]},{"word":"火災","reading":"かさい","meaning":"hỏa hoạn","hanViet":"HỎA TAI","lesson":23,"ex":[["火災が起きました。","Đã xảy ra hỏa hoạn."],["火災を防ぐことが大切です。","Phòng ngừa hỏa hoạn là điều quan trọng."],["火災の原因を調べます。","Tôi tìm hiểu nguyên nhân hỏa hoạn."],["火災で家が焼けました。","Nhà đã cháy vì hỏa hoạn."],["火災のとき、落ち着いてください。","Khi có hỏa hoạn, hãy bình tĩnh."]]},{"word":"スプリンクラー","reading":"スプリンクラー","meaning":"thiết bị phun nước chữa cháy","hanViet":"","lesson":23,"ex":[["スプリンクラーが動きました。","Thiết bị phun nước đã hoạt động."],["建物にスプリンクラーがあります。","Trong tòa nhà có thiết bị phun nước chữa cháy."],["スプリンクラーを設置しました。","Tôi đã lắp đặt thiết bị phun nước chữa cháy."],["火災のとき、スプリンクラーが水を出します。","Khi có hỏa hoạn, thiết bị phun nước phun nước."],["スプリンクラーを調べます。","Tôi kiểm tra thiết bị phun nước chữa cháy."]]},{"word":"設置する","reading":"せっちする","meaning":"lắp đặt","hanViet":"THIẾT TRÍ","lesson":23,"ex":[["エアコンを設置しました。","Tôi đã lắp đặt điều hòa."],["新しい機器を設置します。","Tôi lắp đặt thiết bị mới."],["スプリンクラーを設置することが大切です。","Lắp đặt thiết bị phun nước chữa cháy là điều quan trọng."],["看板を設置しました。","Tôi đã lắp đặt biển hiệu."],["学校に時計を設置しました。","Tôi đã lắp đặt đồng hồ ở trường."]]},{"word":"義務づける","reading":"ぎむづける","meaning":"(gán) nghĩa vụ","hanViet":"NGHĨA VỤ","lesson":23,"ex":[["法律は会社に掃除を義務づけています。","Luật pháp bắt buộc công ty phải dọn dẹp."],["学校は学生に運動を義務づけています。","Trường bắt buộc học sinh phải tập thể dục."],["会社は社員に練習を義務づけています。","Công ty bắt buộc nhân viên phải luyện tập."],["新しい法律は店に設置を義務づけました。","Luật mới bắt buộc cửa hàng phải lắp đặt."],["義務づけられた仕事です。","Đây là công việc bị bắt buộc."]]},{"word":"通学する","reading":"つうがくする","meaning":"đi học","hanViet":"THÔNG HỌC","lesson":23,"ex":[["毎日、電車で通学します。","Mỗi ngày, tôi đi học bằng tàu điện."],["子どもは歩いて通学します。","Trẻ em đi bộ đến trường."],["通学する時間が長いです。","Thời gian đi học rất dài."],["自転車で通学します。","Tôi đi học bằng xe đạp."],["通学する途中で、友達に会いました。","Trên đường đi học, tôi đã gặp bạn."]]},{"word":"親友","reading":"しんゆう","meaning":"bạn thân","hanViet":"THÂN HỮU","lesson":23,"ex":[["親友に会いました。","Tôi đã gặp bạn thân."],["親友と旅行しました。","Tôi đã đi du lịch với bạn thân."],["親友は京都に住んでいます。","Bạn thân tôi sống ở Kyoto."],["親友から手紙をもらいました。","Tôi đã nhận thư từ bạn thân."],["親友に誕生日のプレゼントをあげました。","Tôi đã tặng quà sinh nhật cho bạn thân."]]},{"word":"食物","reading":"しょくもつ","meaning":"thức ăn","hanViet":"THỰC VẬT","lesson":23,"ex":[["食物を大切にします。","Tôi trân trọng thức ăn."],["食物が足りません。","Thức ăn không đủ."],["おいしい食物が好きです。","Tôi thích thức ăn ngon."],["食物を買いました。","Tôi đã mua thức ăn."],["食物の値段が上がりました。","Giá thức ăn đã tăng."]]},{"word":"社会科","reading":"しゃかいか","meaning":"môn học về xã hội","hanViet":"XÃ HỘI KHOA","lesson":23,"ex":[["社会科が好きです。","Tôi thích môn xã hội."],["社会科の先生です。","Đây là thầy giáo môn xã hội."],["社会科で歴史を勉強します。","Tôi học lịch sử trong môn xã hội."],["社会科の試験がありました。","Đã có bài kiểm tra môn xã hội."],["社会科の授業は面白いです。","Giờ học môn xã hội rất thú vị."]]},{"word":"地理","reading":"ちり","meaning":"địa lý","hanViet":"ĐỊA LÝ","lesson":23,"ex":[["地理が好きです。","Tôi thích địa lý."],["地理を勉強します。","Tôi học địa lý."],["地理の先生です。","Đây là thầy giáo địa lý."],["地理の試験がありました。","Đã có bài kiểm tra địa lý."],["地理で日本の山を学びます。","Tôi học về núi Nhật Bản trong môn địa lý."]]},{"word":"ジュードー","reading":"ジュードー","meaning":"võ judo","hanViet":"","lesson":23,"ex":[["ジュードーを習います。","Tôi học judo."],["ジュードーが好きです。","Tôi thích judo."],["ジュードーの試合を見ました。","Tôi đã xem trận đấu judo."],["ジュードーを始めました。","Tôi đã bắt đầu học judo."],["ジュードーの練習をします。","Tôi luyện tập judo."]]},{"word":"ニンジャ","reading":"ニンジャ","meaning":"ninja","hanViet":"","lesson":23,"ex":[["ニンジャについての映画をよく見ます。","Tôi thường xem phim về ninja."],["昔の日本には、ニンジャがいました。","Ngày xưa ở Nhật Bản có ninja."],["子どもはニンジャの本が好きです。","Trẻ em thích sách về ninja."],["京都の町で、ニンジャのおもちゃを買いました。","Tôi đã mua đồ chơi ninja ở thành phố Kyoto."],["ニンジャは静かに歩くことができました。","Ninja có thể đi lại một cách lặng lẽ."]]},{"word":"ホストファミリー","reading":"ホストファミリー","meaning":"gia đình chủ nhà (homestay)","hanViet":"","lesson":23,"ex":[["留学生はホストファミリーの家に住みます。","Du học sinh sống ở nhà của gia đình chủ nhà."],["ホストファミリーのお母さんは、とても優しい人です。","Mẹ của gia đình chủ nhà là người rất hiền."],["私はホストファミリーと毎日日本語で話します。","Tôi nói chuyện bằng tiếng Nhật với gia đình chủ nhà mỗi ngày."],["ホストファミリーの家で、日本の料理を食べました。","Tôi đã ăn món ăn Nhật Bản ở nhà của gia đình chủ nhà."],["ホストファミリーと京都へ行きました。","Tôi đã đi Kyoto cùng gia đình chủ nhà."]]},{"word":"フナずし","reading":"フナずし","meaning":"funazushi (sushi cá diếc lên men)","hanViet":"","lesson":23,"ex":[["フナずしは日本の伝統的な食べ物です。","Funazushi là món ăn truyền thống của Nhật Bản."],["私はフナずしを食べたことがあります。","Tôi đã từng ăn funazushi."],["フナずしはにおいが強い食べ物です。","Funazushi là món ăn có mùi rất mạnh."],["母はフナずしがあまり好きではありません。","Mẹ tôi không thích funazushi lắm."],["京都の店でフナずしを買いました。","Tôi đã mua funazushi ở một cửa hàng tại Kyoto."]]},{"word":"ドリアン","reading":"ドリアン","meaning":"sầu riêng","hanViet":"","lesson":23,"ex":[["ドリアンはにおいが強い果物です。","Sầu riêng là loại trái cây có mùi rất mạnh."],["私はドリアンを食べたことがありません。","Tôi chưa từng ăn sầu riêng."],["ドリアンはベトナムでよく食べられます。","Sầu riêng thường được ăn ở Việt Nam."],["友達はドリアンが好きです。","Bạn tôi thích sầu riêng."],["ドリアンの味はとても強いです。","Vị của sầu riêng rất mạnh."]]},{"word":"農家","reading":"のうか","meaning":"nông dân","hanViet":"NÔNG GIA","lesson":23,"ex":[["農家は毎日朝から働きます。","Nông dân làm việc từ sáng mỗi ngày."],["農家の人は米や野菜を作ります。","Người nông dân trồng lúa và rau."],["この村には農家がたくさんあります。","Ngôi làng này có rất nhiều nông dân."],["農家は夏に忙しくなります。","Nông dân trở nên bận rộn vào mùa hè."],["田中さんは農家で働いています。","Anh Tanaka đang làm việc ở nông trại."]]},{"word":"蓄える","reading":"たくわえる","meaning":"tích trữ","hanViet":"SÚC","lesson":23,"ex":[["彼は毎月お金を蓄えています。","Anh ấy đang tích trữ tiền mỗi tháng."],["冬のために、食べ物を蓄える動物がいます。","Có những con vật tích trữ thức ăn cho mùa đông."],["彼女は知識を蓄えるために、毎日本を読みます。","Cô ấy đọc sách mỗi ngày để tích lũy kiến thức."],["私は将来のために、お金を蓄えたいです。","Tôi muốn tích trữ tiền cho tương lai."],["体は水を蓄えることができます。","Cơ thể có thể tích trữ nước."]]},{"word":"蒸発する","reading":"じょうはつする","meaning":"bốc hơi, bay hơi","hanViet":"CHƯNG PHÁT","lesson":23,"ex":[["夏の太陽で、水はすぐに蒸発します。","Dưới ánh nắng mùa hè, nước bốc hơi ngay lập tức."],["暑い日に、海の水が少し蒸発しました。","Vào ngày nóng, nước biển đã bốc hơi một chút."],["洗った服の水は、太陽の下で蒸発します。","Nước trên quần áo đã giặt bốc hơi dưới ánh nắng mặt trời."],["冬でも、水は少し蒸発します。","Ngay cả vào mùa đông, nước cũng bốc hơi một chút."],["お風呂の水は、朝までに少し蒸発します。","Nước trong bồn tắm sẽ bốc hơi một chút trước buổi sáng."]]},{"word":"洪水","reading":"こうずい","meaning":"lũ lụt","hanViet":"HỒNG THỦY","lesson":23,"ex":[["雨がたくさん降ったあと、町に洪水がありました。","Sau khi mưa rất nhiều, thành phố đã bị lũ lụt."],["洪水で、川の水が町に入りました。","Vì lũ lụt, nước sông đã tràn vào thành phố."],["洪水のとき、人は山へ行きます。","Khi có lũ lụt, người ta đi lên núi."],["昔、この村では洪水がよくありました。","Ngày xưa, ngôi làng này thường xuyên bị lũ lụt."],["洪水が来る前に、町の人は準備をします。","Trước khi lũ đến, người dân trong thành phố chuẩn bị."]]},{"word":"仲人","reading":"なこうど","meaning":"người mối lái","hanViet":"TRỌNG NHÂN","lesson":23,"ex":[["昔の日本では、仲人が結婚式を手伝いました。","Ngày xưa ở Nhật Bản, người mối lái đã giúp đỡ đám cưới."],["仲人は二つの家族を紹介します。","Người mối lái giới thiệu hai gia đình với nhau."],["田中さんの仲人は、会社の先輩でした。","Người mối lái của anh Tanaka là tiền bối ở công ty."],["仲人の仕事は、とても大切です。","Công việc của người mối lái rất quan trọng."],["今では、仲人がいる結婚式はあまりありません。","Ngày nay, đám cưới có người mối lái không còn nhiều."]]},{"word":"加工","reading":"かこう","meaning":"gia công, chế biến","hanViet":"GIA CÔNG","lesson":23,"ex":[["この会社では、魚を加工します。","Công ty này chế biến cá."],["加工した食べ物は、長く残ります。","Thức ăn đã qua chế biến được giữ lâu."],["野菜を加工して、新しい食べ物を作ります。","Chế biến rau để làm ra món ăn mới."],["木を加工して、机を作りました。","Tôi đã chế biến gỗ để làm bàn."],["加工する前に、魚をよく洗います。","Trước khi chế biến, tôi rửa cá thật kỹ."]]},{"word":"カキ","reading":"カキ","meaning":"hàu","hanViet":"","lesson":23,"ex":[["カキは海で見つけることができます。","Có thể tìm thấy hàu ở biển."],["私はカキが好きです。","Tôi thích hàu."],["カキは体にいい食べ物です。","Hàu là món ăn tốt cho cơ thể."],["冬にカキを食べました。","Tôi đã ăn hàu vào mùa đông."],["この店のカキはとてもおいしいです。","Hàu ở cửa hàng này rất ngon."]]},{"word":"漁師","reading":"りょうし","meaning":"ngư dân","hanViet":"NGƯ SƯ","lesson":23,"ex":[["漁師は毎朝海へ行きます。","Ngư dân ra biển mỗi buổi sáng."],["漁師は船に乗って、魚を探します。","Ngư dân lên thuyền để tìm cá."],["田中さんは漁師の仕事をしています。","Anh Tanaka đang làm công việc của ngư dân."],["漁師の家族は港の近くに住んでいます。","Gia đình của ngư dân sống gần cảng."],["漁師は天気をよく調べます。","Ngư dân thường xem xét thời tiết kỹ."]]},{"word":"栄養分","reading":"えいようぶん","meaning":"thành phần dinh dưỡng","hanViet":"VINH DƯỠNG PHÂN","lesson":23,"ex":[["野菜には栄養分がたくさんあります。","Rau có rất nhiều thành phần dinh dưỡng."],["栄養分は体の力になります。","Thành phần dinh dưỡng trở thành sức mạnh của cơ thể."],["子どもは栄養分がたくさんある食べ物を食べます。","Trẻ em ăn những món ăn có nhiều thành phần dinh dưỡng."],["この食べ物は栄養分があまりありません。","Món ăn này không có nhiều thành phần dinh dưỡng."],["栄養分について、先生に聞きました。","Tôi đã hỏi thầy giáo về thành phần dinh dưỡng."]]},{"word":"循環する","reading":"じゅんかんする","meaning":"tuần hoàn","hanViet":"TUẦN HOÀN","lesson":23,"ex":[["水は海から空へ、空から海へ循環します。","Nước tuần hoàn từ biển lên trời, từ trời xuống biển."],["お金は町の中で循環します。","Tiền tuần hoàn trong thành phố."],["空気は部屋の中を循環します。","Không khí tuần hoàn trong phòng."],["水は山から川へ、川から海へ、海から空へ循環します。","Nước tuần hoàn từ núi xuống sông, từ sông ra biển, từ biển lên trời."],["栄養分は体の中で循環します。","Thành phần dinh dưỡng tuần hoàn trong cơ thể."]]},{"word":"サケ","reading":"サケ","meaning":"cá hồi","hanViet":"","lesson":23,"ex":[["サケは川で生まれます。","Cá hồi sinh ra ở sông."],["サケは海で大きくなります。","Cá hồi lớn lên ở biển."],["私はサケの料理が好きです。","Tôi thích món ăn từ cá hồi."],["サケは秋においしくなります。","Cá hồi trở nên ngon vào mùa thu."],["川でサケを見ました。","Tôi đã thấy cá hồi ở sông."]]},{"word":"取り込む","reading":"とりこむ","meaning":"đưa vào, hấp thụ","hanViet":"THỦ","lesson":23,"ex":[["植物は水を取り込みます。","Thực vật hấp thụ nước."],["私は食べ物から栄養分を取り込みます。","Tôi hấp thụ thành phần dinh dưỡng từ thức ăn."],["体は空気を取り込みます。","Cơ thể hấp thụ không khí."],["海は川の水を取り込みます。","Biển tiếp nhận nước sông."],["この会社は新しい方法を取り込みます。","Công ty này đưa vào phương pháp mới."]]},{"word":"まさに","reading":"まさに","meaning":"quả thật (lúc đó)","hanViet":"","lesson":23,"ex":[["まさにそのとき、雨が降り始めました。","Đúng lúc đó, trời bắt đầu mưa."],["まさに今、友達から電話がありました。","Đúng lúc này, tôi nhận được điện thoại từ bạn."],["その答えは、まさに私が考えた答えでした。","Đáp án đó quả thật là đáp án tôi đã nghĩ."],["まさにここで、友達に会いました。","Đúng tại đây, tôi đã gặp bạn."],["まさに今が、始める時間です。","Quả thật bây giờ là lúc bắt đầu."]]},{"word":"見守る","reading":"みまもる","meaning":"dõi theo","hanViet":"KIẾN THỦ","lesson":23,"ex":[["母は子どもを見守ります。","Mẹ dõi theo con."],["先生は学生を見守ります。","Thầy giáo dõi theo học sinh."],["私は友達の成功を見守ります。","Tôi dõi theo sự thành công của bạn."],["お父さんは家族を見守ります。","Bố dõi theo gia đình."],["母は子どもの未来を見守ります。","Mẹ dõi theo tương lai của con."]]},{"word":"消費する","reading":"しょうひする","meaning":"tiêu thụ","hanViet":"TIÊU PHÍ","lesson":23,"ex":[["この国では、電気をたくさん消費します。","Ở nước này, người ta tiêu thụ rất nhiều điện."],["夏は水をたくさん消費します。","Vào mùa hè, người ta tiêu thụ rất nhiều nước."],["車はガソリンを消費します。","Xe ô tô tiêu thụ xăng."],["人は毎日水を消費します。","Con người tiêu thụ nước mỗi ngày."],["会社は紙をたくさん消費します。","Công ty tiêu thụ rất nhiều giấy."]]},{"word":"電化製品","reading":"でんかせいひん","meaning":"mặt hàng điện tử","hanViet":"ĐIỆN HÓA CHẾ PHẨM","lesson":23,"ex":[["この店では電化製品がたくさんあります。","Cửa hàng này có rất nhiều mặt hàng điện tử."],["電化製品は毎日使います。","Tôi dùng mặt hàng điện tử mỗi ngày."],["新しい電化製品を買いました。","Tôi đã mua mặt hàng điện tử mới."],["電化製品は生活を便利にします。","Mặt hàng điện tử làm cho cuộc sống tiện lợi hơn."],["母は電化製品があまり好きではありません。","Mẹ tôi không thích mặt hàng điện tử lắm."]]},{"word":"照明器具","reading":"しょうめいきぐ","meaning":"thiết bị chiếu sáng","hanViet":"CHIẾU MINH KHÍ CỤ","lesson":23,"ex":[["部屋の照明器具を新しくしました。","Tôi đã thay thiết bị chiếu sáng trong phòng bằng cái mới."],["照明器具は部屋を明るくします。","Thiết bị chiếu sáng làm cho phòng sáng hơn."],["この店では照明器具がたくさんあります。","Cửa hàng này có rất nhiều thiết bị chiếu sáng."],["照明器具を買うために、店へ行きました。","Tôi đã đi đến cửa hàng để mua thiết bị chiếu sáng."],["照明器具の電気を消しました。","Tôi đã tắt điện của thiết bị chiếu sáng."]]},{"word":"蛍光灯","reading":"けいこうとう","meaning":"đèn huỳnh quang","hanViet":"HUỲNH QUANG ĐĂNG","lesson":23,"ex":[["部屋の蛍光灯が暗くなりました。","Đèn huỳnh quang trong phòng đã trở nên tối."],["蛍光灯は長い時間明るいです。","Đèn huỳnh quang sáng trong thời gian dài."],["新しい蛍光灯を買いました。","Tôi đã mua đèn huỳnh quang mới."],["蛍光灯の下で本を読みます。","Tôi đọc sách dưới ánh đèn huỳnh quang."],["台所の蛍光灯が古くなりました。","Đèn huỳnh quang trong bếp đã cũ."]]},{"word":"風通し","reading":"かぜとおし","meaning":"thông gió, thoáng gió","hanViet":"PHONG THÔNG","lesson":23,"ex":[["この部屋は風通しがいいです。","Phòng này thông gió tốt."],["風通しのいい部屋で、よく寝られます。","Ở phòng thông gió tốt, tôi có thể ngủ ngon."],["窓を開けると、風通しがよくなります。","Khi mở cửa sổ, phòng sẽ thông gió tốt hơn."],["夏は風通しが大切です。","Vào mùa hè, thông gió rất quan trọng."],["風通しの悪い部屋は、暑くなります。","Phòng thông gió kém sẽ trở nên nóng."]]},{"word":"型","reading":"かた","meaning":"khuôn khổ","hanViet":"HÌNH","lesson":24,"ex":[["これは日本の古い型です。","Đây là khuôn khổ cũ của Nhật Bản."],["型を守ることも大切です。","Việc giữ khuôn khổ cũng rất quan trọng."],["新しい型を作るのは難しいです。","Việc tạo ra khuôn khổ mới rất khó."],["型にはまらないで、自分で考えましょう。","Đừng theo khuôn khổ, hãy tự mình suy nghĩ."],["この型は長い歴史があります。","Khuôn khổ này có lịch sử lâu dài."]]},{"word":"はまる（型に～）","reading":"はまる（かたに～）","meaning":"theo (khuôn khổ)","hanViet":"HÌNH","lesson":24,"ex":[["彼は型にはまることが好きです。","Anh ấy thích theo khuôn khổ."],["型にはまるのは、悪いことではありません。","Theo khuôn khổ không phải là điều xấu."],["私は型にはまりたくありません。","Tôi không muốn theo khuôn khổ."],["型にはまると、仕事がしやすくなります。","Khi theo khuôn khổ, công việc trở nên dễ làm hơn."],["彼は型にはまらない人です。","Anh ấy là người không theo khuôn khổ."]]},{"word":"好奇心","reading":"こうきしん","meaning":"tính tò mò","hanViet":"HẢO KỲ TÂM","lesson":24,"ex":[["子どもは好奇心が強いです。","Trẻ em có tính tò mò mạnh."],["好奇心が強い人は、たくさん質問します。","Người có tính tò mò mạnh hỏi rất nhiều."],["好奇心から、新しいことを始めました。","Từ tính tò mò, tôi đã bắt đầu điều mới."],["彼女は好奇心で日本へ来ました。","Cô ấy đến Nhật Bản vì tính tò mò."],["好奇心は勉強の力になります。","Tính tò mò trở thành sức mạnh của việc học."]]},{"word":"忍耐（力）","reading":"にんたい（りょく）","meaning":"(sức) chịu đựng, (sự) nhẫn nại","hanViet":"NHẪN NẠI LỰC","lesson":24,"ex":[["忍耐力は大切な力です。","Sức chịu đựng là sức mạnh quan trọng."],["彼は忍耐力が強い人です。","Anh ấy là người có sức chịu đựng mạnh."],["忍耐力は、毎日練習することで強くなります。","Sức chịu đựng trở nên mạnh hơn nhờ luyện tập mỗi ngày."],["忍耐がなければ、難しいことはできません。","Nếu không có sự nhẫn nại, không thể làm được việc khó."],["長い試験には忍耐力が必要です。","Kỳ thi dài cần có sức chịu đựng."]]},{"word":"就職試験","reading":"しゅうしょくしけん","meaning":"kỳ thi tuyển dụng","hanViet":"TỰU CHỨC THÍ NGHIỆM","lesson":24,"ex":[["就職試験は来週あります。","Kỳ thi tuyển dụng sẽ diễn ra vào tuần sau."],["就職試験のために、毎日勉強しています。","Tôi đang học mỗi ngày để chuẩn bị cho kỳ thi tuyển dụng."],["彼女は就職試験に合格しました。","Cô ấy đã đỗ kỳ thi tuyển dụng."],["就職試験はとても難しいです。","Kỳ thi tuyển dụng rất khó."],["就職試験の前に、よく寝ました。","Trước kỳ thi tuyển dụng, tôi đã ngủ thật ngon."]]},{"word":"面接（する）","reading":"めんせつ（する）","meaning":"phỏng vấn","hanViet":"DIỆN TIẾP","lesson":24,"ex":[["あした会社で面接があります。","Ngày mai có buổi phỏng vấn ở công ty."],["面接する前に、よく準備しました。","Trước khi phỏng vấn, tôi đã chuẩn bị kỹ."],["面接では、自分のことを話します。","Trong buổi phỏng vấn, tôi nói về bản thân mình."],["彼女は面接で緊張しました。","Cô ấy đã căng thẳng trong buổi phỏng vấn."],["面接が終わったあと、家へ帰りました。","Sau khi phỏng vấn xong, tôi đã về nhà."]]},{"word":"約束事","reading":"やくそくごと","meaning":"điều hứa hẹn","hanViet":"ƯỚC THÚC SỰ","lesson":24,"ex":[["約束事は必ず守ります。","Tôi nhất định giữ điều đã hứa."],["約束事を忘れないように、ノートに書きます。","Tôi viết điều đã hứa vào sổ để không quên."],["約束事がたくさんある日は、忙しくなります。","Vào ngày có nhiều điều đã hứa, tôi trở nên bận rộn."],["彼は約束事をいつも守ります。","Anh ấy luôn giữ điều đã hứa."],["約束事を守る人は、信頼されます。","Người giữ điều đã hứa được tin tưởng."]]},{"word":"守る（約束を～）","reading":"まもる（やくそくを～）","meaning":"giữ (lời hứa)","hanViet":"THỦ ƯỚC THÚC","lesson":24,"ex":[["約束を守ることは大切です。","Giữ lời hứa là điều quan trọng."],["私は約束を必ず守ります。","Tôi nhất định giữ lời hứa."],["彼は約束を守らなかったので、友達に怒られました。","Vì anh ấy không giữ lời hứa nên đã bị bạn giận."],["約束を守る人は、みんなに信頼されます。","Người giữ lời hứa được mọi người tin tưởng."],["子どものときから、約束を守ることを習いました。","Từ khi còn nhỏ, tôi đã học cách giữ lời hứa."]]},{"word":"服装","reading":"ふくそう","meaning":"quần áo, trang phục","hanViet":"PHỤC TRANG","lesson":24,"ex":[["面接では、服装が大切です。","Trong buổi phỏng vấn, trang phục rất quan trọng."],["彼の服装はいつもきれいです。","Trang phục của anh ấy lúc nào cũng đẹp."],["服装を考えて、服を選びます。","Tôi suy nghĩ về trang phục rồi chọn quần áo."],["夏の服装は、涼しい服がいいです。","Trang phục mùa hè nên là quần áo mát mẻ."],["服装が悪いと、面接で失敗します。","Nếu trang phục xấu, tôi sẽ thất bại trong buổi phỏng vấn."]]},{"word":"TPO","reading":"ティーピーオ","meaning":"TPO (thời gian, địa điểm, tình huống)","hanViet":"","lesson":24,"ex":[["TPOを考えることは大切です。","Suy nghĩ về TPO là điều quan trọng."],["服装はTPOで選びます。","Tôi chọn trang phục theo TPO."],["TPOを知らないと、失敗することがあります。","Nếu không biết TPO, có thể sẽ thất bại."],["会社ではTPOが大切です。","Ở công ty, TPO rất quan trọng."],["TPOについて、先生に聞きました。","Tôi đã hỏi thầy giáo về TPO."]]},{"word":"（お）能","reading":"（お）のう","meaning":"kịch Nô","hanViet":"NĂNG","lesson":24,"ex":[["能は日本の伝統的な芸術です。","Kịch Nô là nghệ thuật truyền thống của Nhật Bản."],["京都で能を見ました。","Tôi đã xem kịch Nô ở Kyoto."],["能の舞台は静かです。","Sân khấu kịch Nô rất tĩnh lặng."],["お能を見たことがあります。","Tôi đã từng xem kịch Nô."],["能について、本で読みました。","Tôi đã đọc về kịch Nô trong sách."]]},{"word":"破る（型を～）","reading":"やぶる（かたを～）","meaning":"phá vỡ (khuôn khổ)","hanViet":"PHÁ HÌNH","lesson":24,"ex":[["彼は型を破ることが好きです。","Anh ấy thích phá vỡ khuôn khổ."],["型を破るのは、簡単ではありません。","Phá vỡ khuôn khổ không phải là điều dễ dàng."],["新しい方法で、古い型を破りました。","Tôi đã phá vỡ khuôn khổ cũ bằng phương pháp mới."],["型を破る人は、強い心があります。","Người phá vỡ khuôn khổ có trái tim mạnh mẽ."],["彼女は型を破って、新しい道を作りました。","Cô ấy đã phá vỡ khuôn khổ và tạo ra con đường mới."]]},{"word":"とかく","reading":"","meaning":"có khuynh hướng","hanViet":"","lesson":24,"ex":[["とかく雨の日は、電車が遅れがちです。","Vào những ngày mưa, tàu điện thường có xu hướng đến muộn."],["とかく忙しい人は、ごはんの時間を忘れがちです。","Người bận rộn thường có xu hướng quên giờ ăn cơm."],["とかく初めての試験では、人は失敗しがちです。","Trong kỳ thi đầu tiên, người ta thường có xu hướng thất bại."],["とかく冬は、電気をたくさん使いがちです。","Vào mùa đông, người ta thường có xu hướng dùng nhiều điện."],["とかく新しい仕事は、難しく感じがちです。","Công việc mới thường có xu hướng cảm thấy khó khăn."]]},{"word":"見渡す","reading":"みわたす","meaning":"nhìn bao quát, nhìn tổng thể","hanViet":"KIẾN ĐỘ","lesson":24,"ex":[["山の上から、町を見渡しました。","Từ trên núi, tôi đã nhìn bao quát thành phố."],["彼は部屋を見渡しました。","Anh ấy đã nhìn bao quát căn phòng."],["海を見渡すと、島が見えました。","Khi nhìn bao quát biển, tôi đã thấy đảo."],["窓から外を見渡しました。","Tôi đã nhìn bao quát bên ngoài từ cửa sổ."],["高い山から、町を見渡すことができます。","Từ ngọn núi cao, có thể nhìn bao quát thành phố."]]},{"word":"あらざるもの","reading":"","meaning":"không phải là (cái gì đó); thứ không phải là N","hanViet":"","lesson":24,"ex":[["それは本物にあらざるものだと、あとでわかりました。","Sau này tôi mới biết đó không phải là đồ thật."],["彼は友達にあらざるものだと、思いました。","Tôi nghĩ anh ta không phải là bạn."],["それは約束にあらざるものだと言いました。","Anh ấy nói đó không phải là lời hứa."],["彼は社会人にあらざるものだと、先生が言いました。","Thầy giáo nói anh ta không phải là người đi làm."],["これは本にあらざるものだと、思います。","Tôi nghĩ đây không phải là sách."]]},{"word":"衣類","reading":"いるい","meaning":"quần áo","hanViet":"Y LOẠI","lesson":24,"ex":[["衣類は部屋にたくさんあります。","Trong phòng có rất nhiều quần áo."],["冬の衣類を買いました。","Tôi đã mua quần áo mùa đông."],["衣類を洗濯機で洗います。","Tôi giặt quần áo bằng máy giặt."],["新しい衣類が好きです。","Tôi thích quần áo mới."],["衣類は店で買うことができます。","Có thể mua quần áo ở cửa hàng."]]},{"word":"しばりあげる","reading":"しばりあげる","meaning":"trói buộc","hanViet":"","lesson":24,"ex":[["彼は糸で本をしばりあげました。","Anh ấy đã dùng chỉ buộc chặt sách lại."],["荷物を糸でしばりあげて、店へ持って行きました。","Tôi đã dùng chỉ buộc chặt hành lý lại rồi mang đến cửa hàng."],["彼は新聞をしばりあげて、捨てました。","Anh ấy đã buộc chặt báo lại rồi vứt đi."],["子どもはおもちゃを糸でしばりあげました。","Đứa trẻ đã dùng chỉ buộc chặt đồ chơi lại."],["規則は人をしばりあげます。","Quy tắc trói buộc con người."]]},{"word":"人跡","reading":"じんせき","meaning":"dấu chân người","hanViet":"NHÂN TÍCH","lesson":24,"ex":[["山奥には人跡がありません。","Sâu trong núi không có dấu chân người."],["雪の上に人跡がありました。","Trên tuyết có dấu chân người."],["人跡がない山は、静かです。","Ngọn núi không có dấu chân người rất tĩnh lặng."],["海の近くに人跡がありました。","Gần biển có dấu chân người."],["人跡を見つけて、うれしくなりました。","Tôi đã vui mừng khi tìm thấy dấu chân người."]]},{"word":"絶える","reading":"たえる","meaning":"ngừng, dừng","hanViet":"TUYỆT","lesson":24,"ex":[["山奥では、人の声が絶えました。","Sâu trong núi, tiếng người đã dứt."],["昔の歌は絶えて、人は忘れました。","Bài hát ngày xưa đã biến mất nên mọi người đã quên mất."],["昔から、この歌は絶えたことがありません。","Từ ngày xưa, bài hát này chưa bao giờ ngừng lại."],["川の水は絶えることがありません。","Nước sông không bao giờ ngừng chảy."],["人の声が絶えると、山は静かになります。","Khi tiếng người dứt, núi trở nên tĩnh lặng."]]},{"word":"山奥","reading":"やまおく","meaning":"sâu trong núi","hanViet":"SƠN ÁO","lesson":24,"ex":[["山奥には小さい村があります。","Sâu trong núi có một ngôi làng nhỏ."],["山奥の空気はきれいです。","Không khí sâu trong núi rất trong lành."],["山奥へ行くのは大変です。","Đi sâu vào trong núi rất vất vả."],["山奥では、静かに住むことができます。","Sâu trong núi, có thể sống một cách yên tĩnh."],["山奥の水は冷たくておいしいです。","Nước sâu trong núi lạnh và ngon."]]},{"word":"面倒くさい","reading":"めんどうくさい","meaning":"phiền phức","hanViet":"DIỆN ĐẢO","lesson":24,"ex":[["面倒くさいことは、あとでします。","Việc phiền phức, tôi sẽ làm sau."],["この仕事は面倒くさいです。","Công việc này rất phiền phức."],["面倒くさいので、きょうは休みます。","Vì phiền phức nên hôm nay tôi nghỉ."],["彼は面倒くさいことが好きではありません。","Anh ấy không thích việc phiền phức."],["面倒くさい仕事は、したくありません。","Tôi không muốn làm công việc phiền phức."]]},{"word":"こんがらかる","reading":"","meaning":"rối","hanViet":"","lesson":24,"ex":[["糸がこんがらかりました。","Chỉ đã bị rối."],["頭の中がこんがらかって、答えがわかりません。","Đầu óc tôi rối tung lên nên không biết đáp án."],["問題がこんがらかって、難しくなりました。","Vấn đề trở nên rối rắm và khó khăn hơn."],["糸がこんがらかるので、ゆっくりします。","Vì chỉ bị rối nên tôi làm từ từ."],["こんがらかった糸を、ゆっくり直しました。","Tôi đã từ từ gỡ sợi chỉ bị rối."]]},{"word":"糸","reading":"いと","meaning":"chỉ","hanViet":"TY, MỊCH","lesson":24,"ex":[["糸は服を作るために使います。","Chỉ được dùng để làm quần áo."],["新しい糸を買いました。","Tôi đã mua chỉ mới."],["糸は細くて長いです。","Sợi chỉ mảnh và dài."],["母は糸で服を作りました。","Mẹ đã dùng chỉ để làm quần áo."],["糸を切るために、道具を使います。","Tôi dùng dụng cụ để cắt chỉ."]]},{"word":"ズタズタ（に～）","reading":"","meaning":"nát, vụn","hanViet":"","lesson":24,"ex":[["紙がズタズタになりました。","Tờ giấy đã bị nát vụn."],["古い本がズタズタになりました。","Cuốn sách cũ đã bị nát vụn."],["子どもは紙をズタズタに切りさきました。","Đứa trẻ đã cắt giấy thành từng mảnh vụn."],["ズタズタの紙を捨てました。","Tôi đã vứt tờ giấy nát vụn đi."],["彼の服はズタズタでした。","Quần áo của anh ấy đã bị nát vụn."]]},{"word":"切りさく","reading":"きりさく","meaning":"cắt vụn","hanViet":"THIẾT","lesson":24,"ex":[["紙を切りさいて、捨てました。","Tôi đã cắt vụn giấy rồi vứt đi."],["彼は古い服を切りさきました。","Anh ấy đã cắt vụn quần áo cũ."],["母は新聞を切りさきました。","Mẹ đã cắt vụn báo."],["子どもは紙を切りさくのが好きです。","Trẻ em thích cắt vụn giấy."],["切りさいた紙で、絵を作りました。","Tôi đã dùng giấy cắt vụn để làm tranh."]]},{"word":"社会人","reading":"しゃかいじん","meaning":"thành viên của xã hội","hanViet":"XÃ HỘI NHÂN","lesson":24,"ex":[["社会人は約束を守ります。","Người đi làm giữ lời hứa."],["彼は今年から社会人になりました。","Anh ấy đã trở thành người đi làm từ năm nay."],["社会人には、仕事があります。","Người đi làm có công việc."],["社会人になると、忙しくなります。","Khi trở thành người đi làm, tôi sẽ trở nên bận rộn."],["社会人の生活は大変です。","Cuộc sống của người đi làm rất vất vả."]]},{"word":"たる（社会人～）","reading":"たる（しゃかいじん～）","meaning":"là (với tư cách là thành viên của xã hội)","hanViet":"XÃ HỘI NHÂN","lesson":24,"ex":[["社会人たるもの、約束を守らなければなりません。","Đã là người đi làm thì phải giữ lời hứa."],["社会人たるもの、時間を大切にします。","Đã là người đi làm thì coi trọng thời gian."],["社会人たるもの、仕事を大切にします。","Đã là người đi làm thì coi trọng công việc."],["社会人たるもの、約束を守るべきです。","Đã là người đi làm thì nên giữ lời hứa."],["社会人たるもの、家族を大切にします。","Đã là người đi làm thì coi trọng gia đình."]]},{"word":"なんといおうと","reading":"なんといおうと","meaning":"dù ai nói gì đi nữa","hanViet":"","lesson":24,"ex":[["なんといおうと、私は行きます。","Dù ai nói gì đi nữa, tôi vẫn đi."],["なんといおうと、彼は続けます。","Dù ai nói gì đi nữa, anh ấy vẫn tiếp tục."],["なんといおうと、この答えは変わりません。","Dù ai nói gì đi nữa, đáp án này không thay đổi."],["なんといおうと、私は勉強を続けます。","Dù ai nói gì đi nữa, tôi vẫn tiếp tục học."],["なんといおうと、彼は日本へ行きます。","Dù ai nói gì đi nữa, anh ấy vẫn đi Nhật Bản."]]},{"word":"不自由（な）","reading":"ふじゆう（な）","meaning":"không tự do; khuyết tật","hanViet":"BẤT TỰ DO","lesson":24,"ex":[["不自由な生活は、大変です。","Cuộc sống thiếu tự do rất vất vả."],["彼は足が不自由です。","Chân của anh ấy bị khuyết tật."],["不自由な体でも、元気に働きます。","Dù cơ thể bị khuyết tật, anh ấy vẫn làm việc khỏe mạnh."],["目が不自由な人は、耳で聞きます。","Người không nhìn thấy được nghe bằng tai."],["不自由なことがあっても、あきらめません。","Dù có điều bất tiện, tôi cũng không bỏ cuộc."]]},{"word":"うらやむ","reading":"","meaning":"ghen tị, đố kỵ","hanViet":"","lesson":24,"ex":[["私は彼の成功をうらやみます。","Tôi ghen tị với sự thành công của anh ấy."],["彼女をうらやむ人がいます。","Có người ghen tị với cô ấy."],["私は友達の日本語をうらやみます。","Tôi ghen tị với tiếng Nhật của bạn tôi."],["うらやむ気持ちは、だれにでもあります。","Cảm giác ghen tị ai cũng có."],["彼は私をうらやんでいます。","Anh ấy đang ghen tị với tôi."]]},{"word":"天才","reading":"てんさい","meaning":"thiên tài","hanViet":"THIÊN TÀI","lesson":24,"ex":[["彼は音楽の天才です。","Anh ấy là thiên tài âm nhạc."],["天才は小さいときから有名です。","Thiên tài nổi tiếng từ khi còn nhỏ."],["彼女は天才だと思います。","Tôi nghĩ cô ấy là thiên tài."],["天才でも、練習が必要です。","Dù là thiên tài, vẫn cần luyện tập."],["天才の本を読みました。","Tôi đã đọc sách của thiên tài."]]},{"word":"話相手","reading":"はなしあいて","meaning":"người nói chuyện cùng","hanViet":"THOẠI TƯƠNG THỦ","lesson":24,"ex":[["彼はいい話相手です。","Anh ấy là người nói chuyện cùng rất tốt."],["話相手がいると、楽しいです。","Có người nói chuyện cùng thì rất vui."],["母は私の話相手です。","Mẹ là người nói chuyện cùng với tôi."],["話相手がいないので、寂しいです。","Vì không có người nói chuyện cùng nên tôi cảm thấy cô đơn."],["お年寄りには、話相手が必要です。","Người già cần có người nói chuyện cùng."]]},{"word":"そうかといって","reading":"そうかといって","meaning":"cho dù có như vậy","hanViet":"","lesson":24,"ex":[["彼は天才ですが、そうかといって、練習しなくてもいいわけではありません。","Anh ấy là thiên tài, nhưng cho dù có như vậy, không có nghĩa là không cần luyện tập."],["お金がありますが、そうかといって、たくさん使ってもいいわけではありません。","Tôi có tiền, nhưng cho dù có như vậy, không có nghĩa là có thể tiêu nhiều."],["彼は忙しいですが、そうかといって、約束を忘れてもいいわけではありません。","Anh ấy bận, nhưng cho dù có như vậy, không có nghĩa là có thể quên lời hứa."],["雨が降っていますが、そうかといって、電車が止まるわけではありません。","Trời đang mưa, nhưng cho dù có như vậy, không có nghĩa là tàu điện sẽ dừng."],["彼は先生ですが、そうかといって、何でも知っているわけではありません。","Anh ấy là thầy giáo, nhưng cho dù có như vậy, không có nghĩa là biết mọi thứ."]]},{"word":"まぎらわす","reading":"まぎらわす","meaning":"làm khuây khỏa","hanViet":"","lesson":24,"ex":[["音楽で寂しい気持ちをまぎらわします。","Tôi dùng âm nhạc để làm khuây khỏa cảm giác cô đơn."],["彼は運動で寂しい気持ちをまぎらわします。","Anh ấy dùng vận động để làm khuây khỏa cảm giác cô đơn."],["散歩して、悲しい気持ちをまぎらわします。","Tôi đi dạo để làm khuây khỏa cảm giác buồn."],["本を読んで、寂しい気持ちをまぎらわします。","Tôi đọc sách để làm khuây khỏa cảm giác cô đơn."],["友達と話して、悲しい気持ちをまぎらわします。","Tôi nói chuyện với bạn để làm khuây khỏa cảm giác buồn."]]},{"word":"切実（な）","reading":"せつじつ（な）","meaning":"cấp thiết, tha thiết","hanViet":"THIẾT THỰC","lesson":24,"ex":[["切実な問題があります。","Có vấn đề cấp thiết."],["彼は切実な顔をしています。","Anh ấy có vẻ mặt tha thiết."],["切実な気持ちがあります。","Tôi có cảm giác tha thiết."],["この町には切実な問題があります。","Thành phố này có vấn đề cấp thiết."],["切実な声が聞こえます。","Tôi nghe thấy tiếng nói tha thiết."]]},{"word":"たより","reading":"たより","meaning":"điểm tựa, chỗ dựa","hanViet":"","lesson":24,"ex":[["彼は私のたよりです。","Anh ấy là chỗ dựa của tôi."],["家族は私のたよりです。","Gia đình là chỗ dựa của tôi."],["友達は心のたよりです。","Bạn bè là chỗ dựa tinh thần."],["先生は学生のたよりです。","Thầy giáo là chỗ dựa của học sinh."],["たよりがないと、寂しくなります。","Nếu không có chỗ dựa, tôi sẽ cảm thấy cô đơn."]]},{"word":"茶杓","reading":"ちゃしゃく","meaning":"muỗng trà (dùng trong trà đạo)","hanViet":"TRÀ CHƯỚC","lesson":24,"ex":[["茶杓は茶道で使います。","Muỗng trà được dùng trong trà đạo."],["この茶杓は古いものです。","Muỗng trà này là đồ cũ."],["茶杓はお茶の道具です。","Muỗng trà là dụng cụ pha trà."],["彼は茶杓を大切にしています。","Anh ấy rất coi trọng muỗng trà."],["茶杓は木で作ります。","Muỗng trà được làm bằng gỗ."]]},{"word":"一片","reading":"いっぺん","meaning":"miếng, mảnh","hanViet":"NHẤT PHIẾN","lesson":24,"ex":[["一片のパンを食べました。","Tôi đã ăn một miếng bánh mì."],["一片の紙に絵を描きました。","Tôi đã vẽ tranh trên một mảnh giấy."],["一片の肉を買いました。","Tôi đã mua một miếng thịt."],["一片の葉を拾いました。","Tôi đã nhặt một chiếc lá."],["一片の肉を友達にあげました。","Tôi đã cho bạn một miếng thịt."]]},{"word":"肉体","reading":"にくたい","meaning":"cơ thể","hanViet":"NHỤC THỂ","lesson":24,"ex":[["肉体は大切です。","Cơ thể rất quan trọng."],["運動は肉体を強くします。","Vận động làm cho cơ thể mạnh mẽ hơn."],["肉体が弱いときは、休みます。","Khi cơ thể yếu, tôi nghỉ ngơi."],["肉体と心は、どちらも大切です。","Cơ thể và trái tim đều quan trọng."],["肉体を大切にするために、毎日運動します。","Tôi vận động mỗi ngày để coi trọng cơ thể."]]},{"word":"まかせきる","reading":"","meaning":"giao phó hoàn toàn, phó mặc hoàn toàn","hanViet":"","lesson":24,"ex":[["私は仕事を彼にまかせきります。","Tôi giao phó hoàn toàn công việc cho anh ấy."],["彼は子どもを母にまかせきります。","Anh ấy giao phó hoàn toàn con cho mẹ."],["母は家を私にまかせきりました。","Mẹ đã giao phó hoàn toàn nhà cho tôi."],["先生は仕事を学生にまかせきりました。","Thầy giáo đã giao phó hoàn toàn công việc cho học sinh."],["私は彼に全部まかせきります。","Tôi giao phó hoàn toàn mọi thứ cho anh ấy."]]},{"word":"愛用（する）","reading":"あいよう（する）","meaning":"thích dùng, yêu thích","hanViet":"ÁI DỤNG","lesson":24,"ex":[["私はこの時計を愛用しています。","Tôi thích dùng chiếc đồng hồ này."],["彼はこのかばんを愛用しています。","Anh ấy thích dùng chiếc cặp này."],["母はこの服を愛用しています。","Mẹ thích dùng bộ quần áo này."],["私はこの自転車を愛用しています。","Tôi thích dùng chiếc xe đạp này."],["長く愛用した時計を、直しました。","Tôi đã sửa chiếc đồng hồ đã dùng yêu thích từ lâu."]]},{"word":"滅びる","reading":"ほろびる","meaning":"diệt vong, suy tàn","hanViet":"DIỆT","lesson":24,"ex":[["昔の国が滅びました。","Đất nước ngày xưa đã diệt vong."],["その町は滅びました。","Thành phố đó đã suy tàn."],["文化が滅びるのは、悲しいことです。","Văn hóa diệt vong là điều buồn."],["滅びた国の本を読みました。","Tôi đã đọc sách về đất nước đã diệt vong."],["歴史の中で、たくさんの国が滅びました。","Trong lịch sử, rất nhiều đất nước đã diệt vong."]]},{"word":"鐘（お寺の～）","reading":"かね（おてらの～）","meaning":"chuông (chùa)","hanViet":"CHUNG TỰ","lesson":24,"ex":[["寺の鐘が鳴りました。","Chuông chùa đã vang lên."],["朝、寺の鐘が聞こえます。","Vào buổi sáng, tôi nghe thấy tiếng chuông chùa."],["寺の鐘は大きいです。","Chuông chùa rất lớn."],["京都の寺の鐘を見ました。","Tôi đã thấy chuông chùa ở Kyoto."],["寺の鐘が鳴ると、静かな気持ちになります。","Khi chuông chùa vang lên, lòng tôi trở nên tĩnh lặng."]]},{"word":"余韻","reading":"よいん","meaning":"dư âm, âm vang còn lại","hanViet":"DƯ VẦN","lesson":24,"ex":[["歌の余韻が残ります。","Dư âm của bài hát còn lại."],["音楽の余韻を楽しみました。","Tôi đã thưởng thức dư âm của âm nhạc."],["余韻が長く残りました。","Dư âm còn lại rất lâu."],["彼女の歌の余韻が、心に残ります。","Dư âm bài hát của cô ấy còn lại trong lòng tôi."],["余韻を楽しむために、静かに聞きます。","Tôi lắng nghe một cách tĩnh lặng để thưởng thức dư âm."]]},{"word":"とどめる","reading":"とどめる","meaning":"giữ, lưu lại","hanViet":"","lesson":24,"ex":[["きょうのことを日記にとどめます。","Tôi lưu lại chuyện hôm nay vào nhật ký."],["彼は歌を心にとどめました。","Anh ấy đã lưu giữ bài hát trong lòng."],["先生のことばをノートにとどめます。","Tôi lưu lại lời của thầy giáo vào sổ."],["彼女の声を心にとどめます。","Tôi lưu giữ giọng nói của cô ấy trong lòng."],["歴史を本にとどめます。","Tôi lưu lại lịch sử vào sách."]]},{"word":"後の（～人々）","reading":"あとの（～ひとびと）","meaning":"(người) đời sau","hanViet":"HẬU NHÂN","lesson":24,"ex":[["後の人々のために、歴史を残します。","Tôi để lại lịch sử cho người đời sau."],["後の人々は、この本を読みます。","Người đời sau sẽ đọc cuốn sách này."],["後の人々のために、文化を守ります。","Tôi gìn giữ văn hóa cho người đời sau."],["後の人々に伝えたいことがあります。","Tôi có điều muốn truyền lại cho người đời sau."],["後の人々は、この町を知ります。","Người đời sau sẽ biết về thành phố này."]]},{"word":"おろか（な）","reading":"おろか（な）","meaning":"ngu ngốc, ngu xuẩn","hanViet":"","lesson":24,"ex":[["おろかなことをしました。","Tôi đã làm điều ngu ngốc."],["彼はおろかな人ではありません。","Anh ấy không phải là người ngu ngốc."],["おろかなことは、しないほうがいいです。","Điều ngu ngốc thì tốt nhất là không nên làm."],["おろかな失敗をしました。","Tôi đã phạm sai lầm ngu ngốc."],["おろかな質問はありません。","Không có câu hỏi nào ngu ngốc."]]},{"word":"しのぶ","reading":"しのぶ","meaning":"tưởng nhớ","hanViet":"","lesson":24,"ex":[["彼は友達をしのびます。","Anh ấy tưởng nhớ bạn."],["私は祖父をしのびます。","Tôi tưởng nhớ ông nội."],["昔の先生をしのびます。","Tôi tưởng nhớ thầy giáo ngày xưa."],["彼は母をしのんで、手紙を書きました。","Anh ấy đã viết thư để tưởng nhớ mẹ."],["遠くにいる友達をしのびます。","Tôi tưởng nhớ người bạn ở xa."]]},{"word":"でっちあげる","reading":"でっちあげる","meaning":"bịa đặt, bịa ra (chuyện/lý do/bằng chứng không có thật)","hanViet":"","lesson":24,"ex":[["彼は理由をでっちあげました。","Anh ấy đã bịa ra lý do."],["でっちあげた理由は、すぐにわかります。","Lý do bịa ra sẽ bị phát hiện ngay."],["彼はでっちあげたことを言いました。","Anh ấy đã nói điều bịa đặt."],["でっちあげるのは、よくないことです。","Bịa đặt là điều không tốt."],["彼女はでっちあげた答えを言いました。","Cô ấy đã nói đáp án bịa đặt."]]},{"word":"唯一","reading":"ゆいいつ","meaning":"duy nhất","hanViet":"DUY NHẤT","lesson":24,"ex":[["これは唯一の方法です。","Đây là phương pháp duy nhất."],["彼は私の唯一の友達です。","Anh ấy là người bạn duy nhất của tôi."],["唯一の答えは、これです。","Đáp án duy nhất là cái này."],["唯一の写真を大切にしています。","Tôi rất coi trọng bức ảnh duy nhất."],["彼は学校で唯一の留学生です。","Anh ấy là du học sinh duy nhất ở trường."]]},{"word":"近づく（利休へ～）","reading":"ちかづく（りきゅうへ～）","meaning":"tiếp cận, đến gần (Rikyu)","hanViet":"CẬN LỢI HƯU","lesson":24,"ex":[["私は先生の茶道に近づきたいです。","Tôi muốn đến gần với trà đạo của thầy."],["先生の茶道に近づくために、毎日勉強します。","Tôi học mỗi ngày để đến gần với trà đạo của thầy."],["彼は夢に近づきました。","Anh ấy đã đến gần với ước mơ."],["私は山に近づきました。","Tôi đã đến gần ngọn núi."],["子どもは先生に近づきました。","Đứa trẻ đã đến gần thầy giáo."]]},{"word":"ほんと","reading":"ほんと","meaning":"sự thật","hanViet":"","lesson":24,"ex":[["ほんとのことを言いました。","Tôi đã nói sự thật."],["それはほんとですか。","Đó có phải là sự thật không?"],["ほんとの気持ちを話しました。","Tôi đã nói cảm giác thật của mình."],["彼はほんとのことを知っています。","Anh ấy biết sự thật."],["ほんとにうれしいです。","Tôi thực sự rất vui."]]},{"word":"けっとばす","reading":"けっとばす","meaning":"đá tung, đá văng","hanViet":"","lesson":24,"ex":[["彼は小さい石をけっとばしました。","Anh ấy đã đá văng hòn đá nhỏ."],["子どもは石をけっとばして、遊びました。","Đứa trẻ đã đá hòn đá và chơi đùa."],["彼は怒って、石をけっとばしました。","Anh ấy đã tức giận và đá văng hòn đá."],["子どもはボールをけっとばしました。","Đứa trẻ đã đá văng quả bóng."],["彼はドアをけっとばしました。","Anh ấy đã đá tung cánh cửa."]]},{"word":"たしなみ","reading":"たしなみ","meaning":"thú vui tao nhã","hanViet":"","lesson":24,"ex":[["茶道は日本のたしなみです。","Trà đạo là thú vui tao nhã của Nhật Bản."],["彼はたしなみがある人です。","Anh ấy là người có thú vui tao nhã."],["たしなみを大切にします。","Tôi coi trọng thú vui tao nhã."],["日本のたしなみを勉強します。","Tôi học thú vui tao nhã của Nhật Bản."],["たしなみがある人は、静かな人です。","Người có thú vui tao nhã là người trầm lặng."]]},{"word":"もと（間違いの～）","reading":"もと（まちがいの～）","meaning":"nguồn gốc (dẫn tới nhầm lẫn, sai sót)","hanViet":"GIAN VI","lesson":24,"ex":[["間違いのもとは、小さいことです。","Nguồn gốc của sai lầm là điều nhỏ nhặt."],["間違いのもとを調べました。","Tôi đã tìm hiểu nguồn gốc của sai lầm."],["間違いのもとは、よくわかりません。","Tôi không hiểu rõ nguồn gốc của sai lầm."],["間違いのもとを直しました。","Tôi đã sửa nguồn gốc của sai lầm."],["間違いのもとがわかると、うれしくなります。","Khi hiểu được nguồn gốc của sai lầm, tôi sẽ vui mừng."]]},{"word":"後世","reading":"こうせい","meaning":"con cháu, hậu thế, đời sau","hanViet":"HẬU THẾ","lesson":24,"ex":[["後世のために、歴史を残します。","Tôi để lại lịch sử cho hậu thế."],["後世の人々は、この本を読みます。","Người đời sau sẽ đọc cuốn sách này."],["後世に文化を残したいです。","Tôi muốn để lại văn hóa cho hậu thế."],["後世のために、いいことをします。","Tôi làm điều tốt cho hậu thế."],["後世の人が、この町を知ります。","Người đời sau sẽ biết về thành phố này."]]},{"word":"残す（後世へ～）","reading":"のこす（こうせいへ～）","meaning":"để lại cho (con cháu)","hanViet":"TÀN HẬU THẾ","lesson":24,"ex":[["歴史を後世へ残します。","Tôi để lại lịch sử cho hậu thế."],["文化を後世へ残すことは大切です。","Để lại văn hóa cho hậu thế là điều quan trọng."],["私は本を後世へ残したいです。","Tôi muốn để lại sách cho hậu thế."],["いいものを後世へ残します。","Tôi để lại điều tốt đẹp cho hậu thế."],["彼は歌を後世へ残しました。","Anh ấy đã để lại bài hát cho hậu thế."]]},{"word":"凡人","reading":"ぼんじん","meaning":"người bình thường","hanViet":"PHÀM NHÂN","lesson":24,"ex":[["私は凡人ですから、毎日少し日本語を勉強します。","Tôi là người bình thường nên mỗi ngày tôi học tiếng Nhật một chút."],["凡人でも、毎日練習すれば上手になります。","Dù là người bình thường, nếu luyện tập mỗi ngày thì cũng sẽ giỏi lên."],["田中さんは凡人ですが、とても真面目な人です。","Anh Tanaka là người bình thường nhưng là người rất nghiêm túc."],["凡人の私には、この問題は難しすぎます。","Với tôi, một người bình thường, vấn đề này quá khó."],["彼は凡人ではありません。昔から特別な人です。","Anh ấy không phải người bình thường. Từ xưa anh ấy đã là người đặc biệt."]]},{"word":"獲得（する）","reading":"かくとく（する）","meaning":"có được, đạt được","hanViet":"HOẠCH ĐẮC","lesson":24,"ex":[["田中さんは試験に合格して、学位を獲得しました。","Anh Tanaka đã đỗ kỳ thi và đạt được học vị."],["この会社は去年、新しいお客様をたくさん獲得しました。","Công ty này năm ngoái đã có thêm rất nhiều khách hàng mới."],["彼は毎日練習して、いい結果を獲得しました。","Anh ấy luyện tập mỗi ngày và đã đạt được kết quả tốt."],["私は日本語の試験でいい成績を獲得しました。","Tôi đã đạt thành tích tốt trong kỳ thi tiếng Nhật."],["会社は新しい技術を獲得して、商品を作りました。","Công ty đã có được công nghệ mới và làm ra sản phẩm."]]},{"word":"製作会社","reading":"せいさくがいしゃ","meaning":"công ty sản xuất","hanViet":"CHẾ TÁC HỘI XÃ","lesson":24,"ex":[["この映画は有名な製作会社が作りました。","Bộ phim này do một công ty sản xuất nổi tiếng làm ra."],["田中さんは東京の製作会社で働いています。","Anh Tanaka đang làm việc ở một công ty sản xuất tại Tokyo."],["製作会社は新しい番組を作っています。","Công ty sản xuất đang làm chương trình mới."],["この歌は大阪の製作会社が作りました。","Bài hát này do một công ty sản xuất ở Osaka làm ra."],["製作会社の社員は毎日忙しいです。","Nhân viên công ty sản xuất ngày nào cũng bận."]]},{"word":"志望（する）","reading":"しぼう（する）","meaning":"nguyện vọng, mong muốn","hanViet":"CHÍ VỌNG","lesson":24,"ex":[["私はこの会社を志望します。","Tôi mong muốn vào công ty này."],["田中さんは大学の先生を志望しています。","Anh Tanaka đang mong muốn trở thành giảng viên đại học."],["彼女は医者を志望して、毎日勉強しています。","Cô ấy mong muốn làm bác sĩ nên ngày nào cũng học."],["私は日本で働くことを志望します。","Tôi mong muốn được làm việc tại Nhật Bản."],["山田さんは歌手になることを志望しています。","Anh Yamada đang mong muốn trở thành ca sĩ."]]},{"word":"志望動機","reading":"しぼうどうき","meaning":"động cơ xin vào công ty","hanViet":"CHÍ VỌNG ĐỘNG CƠ","lesson":24,"ex":[["履歴書に志望動機を書きました。","Tôi đã viết động cơ ứng tuyển vào sơ yếu lý lịch."],["志望動機を短く話してください。","Hãy nói ngắn gọn động cơ ứng tuyển của bạn."],["私の志望動機は、日本の文化が好きだからです。","Động cơ ứng tuyển của tôi là vì tôi thích văn hóa Nhật Bản."],["志望動機を考えるのは難しいです。","Suy nghĩ về động cơ ứng tuyển thật khó."],["先生は私の志望動機を聞きました。","Thầy đã hỏi động cơ ứng tuyển của tôi."]]},{"word":"意志","reading":"いし","meaning":"ý chí","hanViet":"Ý CHÍ","lesson":24,"ex":[["彼の意志はとても強いです。","Ý chí của anh ấy rất mạnh mẽ."],["意志が強い人は、最後まで頑張ります。","Người có ý chí mạnh mẽ sẽ cố gắng đến cùng."],["日本語を勉強する意志があります。","Tôi có ý chí học tiếng Nhật."],["意志が弱いと、すぐやめてしまいます。","Nếu ý chí yếu thì sẽ sớm bỏ cuộc."],["彼女は強い意志で毎日練習しています。","Cô ấy luyện tập mỗi ngày với ý chí mạnh mẽ."]]},{"word":"告げる","reading":"つげる","meaning":"nói, tuyên bố, thông báo","hanViet":"CÁO","lesson":24,"ex":[["先生は試験の日を告げました。","Thầy đã thông báo ngày thi."],["社長は新しい計画を社員に告げました。","Giám đốc đã thông báo kế hoạch mới cho nhân viên."],["彼は友達に結婚することを告げました。","Anh ấy đã báo với bạn bè rằng mình sẽ kết hôn."],["彼女は両親に日本へ行くことを告げました。","Cô ấy đã nói với bố mẹ rằng mình sẽ đi Nhật."],["先生は試験の結果を告げました。","Thầy đã thông báo kết quả thi."]]},{"word":"当社","reading":"とうしゃ","meaning":"công ty chúng tôi","hanViet":"ĐƯƠNG XÃ","lesson":24,"ex":[["当社は東京にある会社です。","Công ty chúng tôi là công ty ở Tokyo."],["当社の商品は日本で有名です。","Sản phẩm của công ty chúng tôi nổi tiếng ở Nhật Bản."],["当社で働く人は二百人です。","Số người làm việc ở công ty chúng tôi là hai trăm người."],["当社は来年、新しい店を開きます。","Công ty chúng tôi năm sau sẽ mở cửa hàng mới."],["当社の社長は田中さんです。","Giám đốc công ty chúng tôi là anh Tanaka."]]},{"word":"御社","reading":"おんしゃ","meaning":"quý công ty","hanViet":"NGỰ XÃ","lesson":24,"ex":[["御社の商品を毎日使っています。","Tôi dùng sản phẩm của quý công ty mỗi ngày."],["御社で働きたいと思っています。","Tôi mong muốn được làm việc ở quý công ty."],["御社の歴史について知りたいです。","Tôi muốn biết về lịch sử của quý công ty."],["御社の社員はとても親切です。","Nhân viên quý công ty rất thân thiện."],["御社を志望する理由は、日本の文化が好きだからです。","Lý do tôi mong muốn vào quý công ty là vì tôi thích văn hóa Nhật Bản."]]},{"word":"事業","reading":"じぎょう","meaning":"kinh doanh","hanViet":"SỰ NGHIỆP","lesson":24,"ex":[["この会社は新しい事業を始めました。","Công ty này đã bắt đầu kinh doanh mới."],["当社の事業は食品を作ることです。","Kinh doanh của công ty chúng tôi là sản xuất thực phẩm."],["事業が大きくなって、社員が増えました。","Kinh doanh lớn lên nên nhân viên cũng tăng."],["田中さんは事業の計画を作りました。","Anh Tanaka đã làm kế hoạch kinh doanh."],["新しい事業にはお金が必要です。","Kinh doanh mới cần có tiền."]]},{"word":"農産物","reading":"のうさんぶつ","meaning":"nông sản","hanViet":"NÔNG SẢN VẬT","lesson":24,"ex":[["この店は日本の農産物を売っています。","Cửa hàng này bán nông sản Nhật Bản."],["この店の農産物はおいしいです。","Nông sản của cửa hàng này rất ngon."],["田中さんは農産物を作る仕事をしています。","Anh Tanaka làm công việc sản xuất nông sản."],["この町の農産物は日本で有名です。","Nông sản của thị trấn này nổi tiếng ở Nhật Bản."],["農産物の値段が上がりました。","Giá nông sản đã tăng."]]},{"word":"調達（する）","reading":"ちょうたつ（する）","meaning":"thu mua, huy động","hanViet":"ĐIỀU ĐẠT","lesson":24,"ex":[["会社は材料を調達しました。","Công ty đã thu mua nguyên liệu."],["店は毎朝、新しい魚を調達します。","Cửa hàng mỗi sáng đều thu mua cá mới."],["会社はお金を調達して、新しい店を作りました。","Công ty đã huy động tiền và mở cửa hàng mới."],["会社は新しい机を調達しました。","Công ty đã mua sắm bàn mới."],["学校は新しいパソコンを調達しました。","Trường học đã mua sắm máy tính mới."]]},{"word":"確保（する）","reading":"かくほ（する）","meaning":"đảm bảo","hanViet":"XÁC BẢO","lesson":24,"ex":[["会社はいい社員を確保しました。","Công ty đã đảm bảo có nhân viên tốt."],["旅行の前に、ホテルを確保しました。","Trước chuyến du lịch, tôi đã đặt trước khách sạn."],["勉強の時間を確保することが大切です。","Đảm bảo thời gian học là điều quan trọng."],["田中さんは安全な場所を確保しました。","Anh Tanaka đã đảm bảo một nơi an toàn."],["会社は新しいお客様を確保しました。","Công ty đã đảm bảo có khách hàng mới."]]},{"word":"win-win（な）","reading":"ウィンウィン（な）","meaning":"đôi bên cùng có lợi","hanViet":"","lesson":24,"ex":[["この計画はwin-winな関係です。","Kế hoạch này là quan hệ đôi bên cùng có lợi."],["win-winな仕事をしたいです。","Tôi muốn làm công việc đôi bên cùng có lợi."],["両方の会社にwin-winな話です。","Đây là câu chuyện đôi bên cùng có lợi cho cả hai công ty."],["win-winな結果になって、みんなうれしいです。","Kết quả đôi bên cùng có lợi nên mọi người đều vui."],["この方法はwin-winな方法です。","Cách này là cách đôi bên cùng có lợi."]]},{"word":"感銘（する）","reading":"かんめい（する）","meaning":"cảm động sâu sắc","hanViet":"CẢM MINH","lesson":24,"ex":[["彼のスピーチに感銘しました。","Tôi đã cảm động sâu sắc trước bài phát biểu của anh ấy."],["映画に感銘して、泣きました。","Tôi đã cảm động sâu sắc vì bộ phim và đã khóc."],["先生の話に感銘しました。","Tôi đã cảm động sâu sắc trước câu chuyện của thầy."],["彼女の歌に感銘した人は多いです。","Nhiều người đã cảm động sâu sắc trước bài hát của cô ấy."],["その本を読んで、感銘しました。","Tôi đã đọc cuốn sách đó và cảm động sâu sắc."]]},{"word":"弊社","reading":"へいしゃ","meaning":"công ty chúng tôi","hanViet":"TỆ XÃ","lesson":24,"ex":[["弊社は東京にある小さい会社です。","Công ty chúng tôi là công ty nhỏ ở Tokyo."],["弊社の商品は日本で人気があります。","Sản phẩm của công ty chúng tôi được ưa chuộng ở Nhật Bản."],["弊社で働く人は五十人です。","Số người làm việc ở công ty chúng tôi là năm mươi người."],["弊社は来年、新しい事業を始めます。","Công ty chúng tôi năm sau sẽ bắt đầu kinh doanh mới."],["弊社の社長は山田さんです。","Giám đốc công ty chúng tôi là anh Yamada."]]},{"word":"カップ麺","reading":"カップめん","meaning":"mì ly","hanViet":"MIẾN","lesson":24,"ex":[["夜遅くにカップ麺を食べました。","Tôi đã ăn mì ly lúc đêm muộn."],["カップ麺は安くて、便利です。","Mì ly rẻ và tiện lợi."],["忙しいとき、カップ麺を食べることがあります。","Khi bận, có lúc tôi ăn mì ly."],["コンビニでカップ麺を買いました。","Tôi đã mua mì ly ở cửa hàng tiện lợi."],["カップ麺を作るのは簡単です。","Làm mì ly rất đơn giản."]]},{"word":"出会い","reading":"であい","meaning":"sự gặp gỡ, sự tiếp xúc","hanViet":"XUẤT HỘI","lesson":24,"ex":[["日本での出会いが、私の人生を変えました。","Cuộc gặp gỡ ở Nhật Bản đã thay đổi cuộc đời tôi."],["田中さんとの出会いは十年前にありました。","Cuộc gặp gỡ với anh Tanaka đã diễn ra mười năm trước."],["新しい出会いが楽しみです。","Tôi mong chờ những cuộc gặp gỡ mới."],["大学での出会いは大切です。","Những cuộc gặp gỡ ở đại học rất quan trọng."],["この本との出会いが、私を変えました。","Cuộc gặp gỡ với cuốn sách này đã thay đổi tôi."]]},{"word":"香り","reading":"かおり","meaning":"hương thơm","hanViet":"HƯƠNG","lesson":24,"ex":[["この花の香りはいいです。","Hương thơm của bông hoa này rất dễ chịu."],["コーヒーの香りが好きです。","Tôi thích hương thơm của cà phê."],["パンのいい香りがします。","Có mùi thơm ngon của bánh mì."],["春は公園で花の香りがします。","Vào mùa xuân, trong công viên có hương hoa."],["彼女の料理の香りが、台所からしてきました。","Hương thơm món ăn của cô ấy bay ra từ bếp."]]},{"word":"衝撃的（な）","reading":"しょうげきてき（な）","meaning":"gây sốc, gây chấn động","hanViet":"XUNG KÍCH ĐÍCH","lesson":24,"ex":[["そのニュースは衝撃的でした。","Tin tức đó thật gây sốc."],["衝撃的な話を聞いて、びっくりしました。","Nghe câu chuyện gây sốc, tôi đã giật mình."],["その映画の最後は衝撃的でした。","Đoạn cuối của bộ phim đó thật gây chấn động."],["衝撃的な話でしたが、本当のことでした。","Đó là câu chuyện gây sốc nhưng là sự thật."],["あの日のことは衝撃的で、今も忘れられません。","Chuyện ngày hôm đó thật gây chấn động, đến giờ tôi vẫn không quên được."]]},{"word":"自炊（する）","reading":"じすい（する）","meaning":"tự nấu ăn","hanViet":"TỰ XUY","lesson":24,"ex":[["日本に来てから、自炊を始めました。","Từ khi đến Nhật, tôi đã bắt đầu tự nấu ăn."],["自炊をすると、お金があまりかかりません。","Tự nấu ăn thì không tốn nhiều tiền."],["彼女は毎日自炊しています。","Cô ấy tự nấu ăn mỗi ngày."],["自炊が好きで、毎日料理を作ります。","Tôi thích tự nấu ăn nên ngày nào cũng nấu món ăn."],["忙しくても、自炊をするようにしています。","Dù bận tôi vẫn cố gắng tự nấu ăn."]]},{"word":"レトルト食品","reading":"レトルトしょくひん","meaning":"thức ăn chế biến sẵn đóng bao/ hộp (được xử lý tiệt trùng ở môi trường nhiệt độ cao, áp suất cao)","hanViet":"THỰC PHẨM","lesson":24,"ex":[["レトルト食品はすぐ食べられます。","Thức ăn chế biến sẵn có thể ăn ngay."],["忙しいとき、レトルト食品を食べます。","Khi bận, tôi ăn thức ăn chế biến sẵn."],["スーパーでレトルト食品を買いました。","Tôi đã mua thức ăn chế biến sẵn ở siêu thị."],["レトルト食品は長く使えます。","Thức ăn chế biến sẵn dùng được lâu."],["このレトルト食品はおいしいです。","Thức ăn chế biến sẵn này rất ngon."]]},{"word":"手に入る","reading":"てにはいる","meaning":"có được","hanViet":"THỦ NHẬP","lesson":24,"ex":[["この本は店で手に入ります。","Cuốn sách này có được ở cửa hàng."],["チケットがやっと手に入りました。","Cuối cùng tôi cũng đã có được vé."],["新しい情報が手に入りました。","Tôi đã có được thông tin mới."],["この商品は日本では手に入りません。","Sản phẩm này ở Nhật Bản không có được."],["新しい本が手に入って、うれしいです。","Tôi vui vì đã có được cuốn sách mới."]]},{"word":"贅沢（な）","reading":"ぜいたく（な）","meaning":"xa hoa, xa xỉ","hanViet":"TRỆ TRẠCH","lesson":24,"ex":[["贅沢なホテルに泊まりました。","Tôi đã ở một khách sạn xa hoa."],["贅沢な生活はしたくありません。","Tôi không muốn sống cuộc sống xa xỉ."],["毎日贅沢な料理を食べることはできません。","Tôi không thể ăn món ăn xa hoa mỗi ngày."],["彼は贅沢な車を買いました。","Anh ấy đã mua một chiếc xe xa xỉ."],["贅沢な時間を過ごしました。","Tôi đã trải qua thời gian xa xỉ."]]},{"word":"なるほど","reading":"","meaning":"hóa ra thế, tôi hiểu","hanViet":"","lesson":24,"ex":[["なるほど、そういうことですか。","Hóa ra thế, là chuyện như vậy sao."],["なるほど、よくわかりました。","Hóa ra thế, tôi hiểu rõ rồi."],["先生の話を聞いて、なるほどと思いました。","Nghe thầy nói, tôi nghĩ hóa ra là thế."],["なるほど、この店は人気があるわけですね。","Hóa ra thế, thảo nào cửa hàng này đông khách."],["なるほど、それで遅れたんですね。","Hóa ra thế, thảo nào mà đến muộn."]]},{"word":"ついていく（授業に～）","reading":"ついていく（じゅぎょうに～）","meaning":"theo kịp (giờ học)","hanViet":"THỤ NGHIỆP","lesson":24,"ex":[["日本語の授業についていくのは難しいです。","Theo kịp giờ học tiếng Nhật thật khó."],["毎日復習して、授業についていきます。","Tôi ôn tập mỗi ngày để theo kịp giờ học."],["新しい授業についていけません。","Tôi không theo kịp giờ học mới."],["友達に教えてもらって、授業についていきました。","Nhờ bạn bè chỉ dạy, tôi đã theo kịp giờ học."],["授業についていくために、毎日勉強します。","Để theo kịp giờ học, tôi học mỗi ngày."]]},{"word":"流れる（コマーシャルが～）","reading":"ながれる","meaning":"chiếu, phát (quảng cáo)","hanViet":"LƯU","lesson":24,"ex":[["テレビで新しいコマーシャルが流れています。","Trên TV đang phát quảng cáo mới."],["毎日このコマーシャルが流れます。","Quảng cáo này phát mỗi ngày."],["コマーシャルが流れるたびに、歌を覚えました。","Mỗi lần quảng cáo phát, tôi lại nhớ bài hát."],["ラジオでコマーシャルが流れました。","Trên radio đã phát quảng cáo."],["好きなコマーシャルが流れて、うれしいです。","Tôi vui vì quảng cáo mình thích đang phát."]]},{"word":"科学技術","reading":"かがくぎじゅつ","meaning":"khoa học, kĩ thuật","hanViet":"KHOA HỌC KỸ THUẬT","lesson":24,"ex":[["科学技術は速く変わります。","Khoa học kỹ thuật thay đổi nhanh chóng."],["日本の科学技術は世界で有名です。","Khoa học kỹ thuật Nhật Bản nổi tiếng trên thế giới."],["科学技術を勉強するために、大学に入りました。","Để học khoa học kỹ thuật, tôi đã vào đại học."],["科学技術が生活を便利にしました。","Khoa học kỹ thuật đã làm cuộc sống tiện lợi hơn."],["子どもたちは科学技術に興味があります。","Trẻ em có hứng thú với khoa học kỹ thuật."]]},{"word":"就く（仕事に～）","reading":"つく（しごとに～）","meaning":"làm (việc)","hanViet":"TỰU SĨ SỰ","lesson":24,"ex":[["大学を卒業して、仕事に就きました。","Tốt nghiệp đại học, tôi đã đi làm."],["彼は先生の仕事に就きました。","Anh ấy đã làm công việc giáo viên."],["新しい仕事に就くのは、大変です。","Bắt đầu công việc mới thật vất vả."],["来年、日本で仕事に就くつもりです。","Năm sau tôi dự định làm việc ở Nhật Bản."],["彼女は医者の仕事に就きました。","Cô ấy đã làm công việc bác sĩ."]]},{"word":"携わる","reading":"たずさわる","meaning":"tham gia vào","hanViet":"HUỀ","lesson":24,"ex":[["田中さんは新しい事業に携わっています。","Anh Tanaka đang tham gia vào kinh doanh mới."],["私は教育に携わる仕事をしています。","Tôi làm công việc liên quan đến giáo dục."],["彼は映画を作る仕事に携わっています。","Anh ấy đang tham gia vào công việc làm phim."],["彼女は子どもの教育に携わっています。","Cô ấy đang tham gia vào giáo dục trẻ em."],["私はこの仕事に五年携わっています。","Tôi đã tham gia vào công việc này năm năm rồi."]]},{"word":"職種","reading":"しょくしゅ","meaning":"ngành nghề","hanViet":"CHỨC CHÚNG","lesson":24,"ex":[["この会社にはたくさんの職種があります。","Công ty này có rất nhiều ngành nghề."],["好きな職種は何ですか。","Ngành nghề bạn thích là gì?"],["職種によって、給料が違います。","Tùy ngành nghề mà lương khác nhau."],["私は職種を変えたいです。","Tôi muốn đổi ngành nghề."],["職種を選ぶとき、よく考えてください。","Khi chọn ngành nghề, hãy suy nghĩ kỹ."]]},{"word":"専門性","reading":"せんもんせい","meaning":"tính chuyên môn","hanViet":"CHUYÊN MÔN TÍNH","lesson":24,"ex":[["この仕事には高い専門性が必要です。","Công việc này cần tính chuyên môn cao."],["専門性が高い人は、会社に必要です。","Người có tính chuyên môn cao rất cần thiết cho công ty."],["専門性のために、毎日勉強しています。","Vì tính chuyên môn, tôi học mỗi ngày."],["彼の専門性はとても高いです。","Tính chuyên môn của anh ấy rất cao."],["専門性のある仕事をしたいです。","Tôi muốn làm công việc có tính chuyên môn."]]},{"word":"専攻（する）","reading":"せんこう（する）","meaning":"chuyên ngành","hanViet":"CHUYÊN CÔNG","lesson":24,"ex":[["大学で日本語を専攻しました。","Ở đại học tôi đã học chuyên ngành tiếng Nhật."],["彼女は医学を専攻しています。","Cô ấy đang học chuyên ngành y học."],["田中さんは経済を専攻しました。","Anh Tanaka đã học chuyên ngành kinh tế."],["何を専攻しましたか。","Bạn đã học chuyên ngành gì?"],["大学で歴史を専攻して、先生になりました。","Tôi học chuyên ngành lịch sử ở đại học rồi trở thành giáo viên."]]},{"word":"アミノ酸","reading":"あみのさん","meaning":"axit amin","hanViet":"TOAN","lesson":24,"ex":[["アミノ酸は体に必要です。","Axit amin cần thiết cho cơ thể."],["この食品にはアミノ酸が入っています。","Thực phẩm này có chứa axit amin."],["アミノ酸について勉強しています。","Tôi đang học về axit amin."],["先生はアミノ酸のことを説明しました。","Thầy đã giải thích về axit amin."],["アミノ酸は肉や魚に入っています。","Axit amin có trong thịt và cá."]]},{"word":"卒論","reading":"そつろん","meaning":"luận văn tốt nghiệp","hanViet":"TỐT LUẬN","lesson":24,"ex":[["卒論を書くのは大変です。","Viết luận văn tốt nghiệp thật vất vả."],["卒論のテーマを決めました。","Tôi đã quyết định chủ đề luận văn tốt nghiệp."],["来月までに卒論を書かなければなりません。","Tôi phải viết xong luận văn tốt nghiệp trước tháng sau."],["卒論がやっと終わりました。","Cuối cùng luận văn tốt nghiệp cũng đã xong."],["卒論のために、図書館で本を読みました。","Vì luận văn tốt nghiệp, tôi đã đọc sách ở thư viện."]]},{"word":"応用（する）","reading":"おうよう（する）","meaning":"ứng dụng","hanViet":"ỨNG DỤNG","lesson":24,"ex":[["日本語を仕事に応用します。","Tôi ứng dụng tiếng Nhật vào công việc."],["学んだことを生活に応用しました。","Tôi đã ứng dụng những điều đã học vào cuộc sống."],["この技術は医学に応用できます。","Công nghệ này có thể ứng dụng vào y học."],["先生は文法の応用を教えました。","Thầy đã dạy cách ứng dụng ngữ pháp."],["知識を応用することが大切です。","Ứng dụng kiến thức là điều quan trọng."]]},{"word":"実績","reading":"じっせき","meaning":"thành tích thực tế","hanViet":"THỰC TÍCH","lesson":24,"ex":[["この会社は実績がたくさんあります。","Công ty này có rất nhiều thành tích thực tế."],["彼の実績は会社で一番です。","Thành tích của anh ấy là nhất trong công ty."],["実績を積むことが大切です。","Tích lũy thành tích thực tế là điều quan trọng."],["田中さんの実績はすばらしいです。","Thành tích của anh Tanaka thật tuyệt vời."],["実績のある会社を選びました。","Tôi đã chọn công ty có thành tích thực tế."]]},{"word":"医薬品","reading":"いやくひん","meaning":"thuốc, dược phẩm","hanViet":"Y DƯỢC PHẨM","lesson":24,"ex":[["医薬品は店で買えます。","Thuốc có thể mua ở cửa hàng."],["会社は新しい医薬品を作りました。","Công ty đã sản xuất thuốc mới."],["医薬品について研究しています。","Tôi đang nghiên cứu về thuốc."],["医薬品は正しく使ってください。","Hãy dùng thuốc đúng cách."],["この医薬品は有名です。","Thuốc này nổi tiếng."]]},{"word":"化粧品","reading":"けしょうひん","meaning":"mỹ phẩm","hanViet":"HÓA TRANG PHẨM","lesson":24,"ex":[["化粧品をデパートで買いました。","Tôi đã mua mỹ phẩm ở trung tâm thương mại."],["この化粧品は体に優しいです。","Mỹ phẩm này dịu nhẹ với cơ thể."],["彼女は化粧品が好きです。","Cô ấy thích mỹ phẩm."],["日本の化粧品は世界で人気があります。","Mỹ phẩm Nhật Bản được ưa chuộng trên thế giới."],["化粧品の広告をテレビで見ました。","Tôi đã xem quảng cáo mỹ phẩm trên TV."]]},{"word":"健康食品","reading":"けんこうしょくひん","meaning":"thực phẩm chức năng","hanViet":"KIỆN KHANG THỰC PHẨM","lesson":24,"ex":[["健康食品を毎日食べています。","Tôi ăn thực phẩm chức năng mỗi ngày."],["この健康食品は体にいいです。","Thực phẩm chức năng này tốt cho cơ thể."],["健康食品はスーパーで買えます。","Thực phẩm chức năng có thể mua ở siêu thị."],["田中さんは健康食品を作る会社で働いています。","Anh Tanaka đang làm việc ở công ty sản xuất thực phẩm chức năng."],["健康食品について、先生に聞きました。","Tôi đã hỏi thầy về thực phẩm chức năng."]]},{"word":"積む（経験を～）","reading":"つむ（けいけんを～）","meaning":"tích lũy (kinh nghiệm)","hanViet":"TÍCH KINH NGHIỆM","lesson":24,"ex":[["仕事で経験を積むことが大切です。","Tích lũy kinh nghiệm trong công việc là điều quan trọng."],["田中さんは十年経験を積みました。","Anh Tanaka đã tích lũy mười năm kinh nghiệm."],["たくさんの経験を積みたいです。","Tôi muốn tích lũy nhiều kinh nghiệm."],["海外で経験を積みました。","Tôi đã tích lũy kinh nghiệm ở nước ngoài."],["若いときに経験を積むことが必要です。","Khi còn trẻ cần tích lũy kinh nghiệm."]]},{"word":"突っ込む","reading":"つっこむ","meaning":"đâm vào, lao vào, thọc vào","hanViet":"ĐỘT","lesson":24,"ex":[["先生は私の答えに突っ込みました。","Thầy đã truy vấn câu trả lời của tôi."],["彼は話に突っ込んで、質問しました。","Anh ấy đã chen vào câu chuyện và hỏi."],["田中さんは私の意見に突っ込みました。","Anh Tanaka đã bắt bẻ ý kiến của tôi."],["突っ込む人に、答えるのは難しいです。","Trả lời người hay truy vấn thật khó."],["彼女は私の話に突っ込んできました。","Cô ấy đã chen vào và truy vấn câu chuyện của tôi."]]},{"word":"切り返す","reading":"きりかえす","meaning":"phản hồi lại, đáp trả lại","hanViet":"THIẾT PHẢN","lesson":24,"ex":[["彼は私の質問に上手に切り返しました。","Anh ấy đã đáp trả câu hỏi của tôi một cách khéo léo."],["彼女は笑って切り返しました。","Cô ấy đã cười và đáp trả lại."],["田中さんはすぐ切り返しました。","Anh Tanaka đã đáp trả lại ngay."],["相手の話に切り返すのは難しいです。","Đáp trả lại lời nói của đối phương thật khó."],["彼は切り返して、話を続けました。","Anh ấy đã đáp trả lại rồi tiếp tục câu chuyện."]]},{"word":"インストラクター","reading":"","meaning":"người hướng dẫn","hanViet":"","lesson":24,"ex":[["インストラクターはとても親切です。","Người hướng dẫn rất thân thiện."],["インストラクターに水泳を習いました。","Tôi đã học bơi với người hướng dẫn."],["スポーツクラブのインストラクターをしています。","Tôi làm người hướng dẫn ở câu lạc bộ thể thao."],["インストラクターの話をよく聞いてください。","Hãy nghe kỹ lời người hướng dẫn."],["新しいインストラクターが来ました。","Người hướng dẫn mới đã đến."]]},{"word":"配属（する）","reading":"はいぞく（する）","meaning":"bố trí, điều về","hanViet":"PHỐI THUỘC","lesson":24,"ex":[["田中さんは東京に配属されました。","Anh Tanaka đã được bố trí về Tokyo."],["新入社員は営業に配属されました。","Nhân viên mới đã được bố trí về bộ phận kinh doanh."],["来月、大阪に配属される予定です。","Tháng sau tôi dự định sẽ được điều về Osaka."],["彼女は新しい部署に配属されました。","Cô ấy đã được bố trí về phòng ban mới."],["配属された場所は京都でした。","Nơi được bố trí là Kyoto."]]},{"word":"配偶者","reading":"はいぐうしゃ","meaning":"vợ/ chồng","hanViet":"PHỐI NGẪU GIẢ","lesson":24,"ex":[["配偶者は日本で生まれました。","Vợ/chồng tôi sinh ra ở Nhật Bản."],["書類に配偶者の名前を書きました。","Tôi đã viết tên vợ/chồng vào giấy tờ."],["配偶者と旅行に行きました。","Tôi đã đi du lịch cùng vợ/chồng."],["田中さんの配偶者は先生です。","Vợ/chồng của anh Tanaka là giáo viên."],["配偶者がいる人は、書類に書いてください。","Người có vợ/chồng hãy viết vào giấy tờ."]]},{"word":"短所","reading":"たんしょ","meaning":"điểm yếu, sở đoản","hanViet":"ĐOẢN SỞ","lesson":24,"ex":[["私の短所は、忘れやすいことです。","Điểm yếu của tôi là hay quên."],["短所を直すために、努力しています。","Tôi đang nỗ lực để sửa điểm yếu."],["彼の短所は、急ぐことです。","Điểm yếu của anh ấy là hay vội vàng."],["短所も長所も、大切なことです。","Cả điểm yếu lẫn điểm mạnh đều là điều quan trọng."],["自分の短所を知ることが大切です。","Biết điểm yếu của mình là điều quan trọng."]]},{"word":"長所","reading":"ちょうしょ","meaning":"điểm mạnh, sở trường","hanViet":"TRƯỜNG SỞ","lesson":24,"ex":[["私の長所は、真面目なことです。","Điểm mạnh của tôi là nghiêm túc."],["長所を生かして、仕事をしています。","Tôi làm việc phát huy điểm mạnh của mình."],["彼女の長所は、明るいことです。","Điểm mạnh của cô ấy là vui vẻ."],["長所と短所を書いてください。","Hãy viết điểm mạnh và điểm yếu."],["自分の長所を知ってください。","Hãy biết điểm mạnh của mình."]]},{"word":"適性","reading":"てきせい","meaning":"năng khiếu phù hợp","hanViet":"THÍCH TÍNH","lesson":24,"ex":[["この仕事には適性が必要です。","Công việc này cần năng khiếu phù hợp."],["適性がある人は、すぐ上手になります。","Người có năng khiếu phù hợp sẽ nhanh giỏi lên."],["自分の適性を知ることが大切です。","Biết năng khiếu phù hợp của mình là điều quan trọng."],["適性を見つけるために、たくさんの仕事をしました。","Để tìm năng khiếu phù hợp, tôi đã làm nhiều công việc."],["彼女にはこの仕事の適性があります。","Cô ấy có năng khiếu phù hợp với công việc này."]]},{"word":"有無","reading":"うむ","meaning":"có hoặc không","hanViet":"HỮU VÔ","lesson":24,"ex":[["駐車場の有無を聞きました。","Tôi đã hỏi có hay không có bãi đỗ xe."],["経験の有無は問題ではありません。","Có hay không có kinh nghiệm không phải là vấn đề."],["予定の有無を教えてください。","Hãy cho tôi biết có hay không có kế hoạch."],["子どもの有無を書類に書きました。","Tôi đã viết có hay không có con vào giấy tờ."],["仕事の経験の有無が大切です。","Có hay không có kinh nghiệm làm việc là điều quan trọng."]]},{"word":"否定的（な）","reading":"ひていてき（な）","meaning":"mang tính phủ định","hanViet":"PHỦ ĐỊNH ĐÍCH","lesson":24,"ex":[["否定的な意見を言いました。","Tôi đã nói ý kiến mang tính phủ định."],["否定的な答えはよくありません。","Câu trả lời mang tính phủ định không tốt."],["彼は否定的に答えました。","Anh ấy đã trả lời một cách phủ định."],["否定的な話をしないでください。","Đừng nói chuyện mang tính phủ định."],["その話に否定的な人が多いです。","Nhiều người có thái độ phủ định với câu chuyện đó."]]},{"word":"許す","reading":"ゆるす","meaning":"tha thứ","hanViet":"HỨA","lesson":24,"ex":[["友達を許しました。","Tôi đã tha thứ cho bạn bè."],["彼を許すことができますか。","Bạn có thể tha thứ cho anh ấy không?"],["彼女は私を許してくれました。","Cô ấy đã tha thứ cho tôi."],["間違いを許してください。","Hãy tha thứ cho lỗi lầm."],["自分を許すことも大切です。","Tha thứ cho bản thân cũng là điều quan trọng."]]},{"word":"ねじ","reading":"","meaning":"ốc vít","hanViet":"","lesson":24,"ex":[["ねじをドライバーで回しました。","Tôi đã vặn ốc vít bằng tua vít."],["このねじは小さいです。","Ốc vít này nhỏ."],["ねじを店で買いました。","Tôi đã mua ốc vít ở cửa hàng."],["机のねじが取れました。","Ốc vít của cái bàn đã rơi ra."],["新しいねじを付けました。","Tôi đã gắn ốc vít mới."]]},{"word":"人工衛星","reading":"じんこうえいせい","meaning":"vệ tinh nhân tạo","hanViet":"NHÂN CÔNG VỆ TINH","lesson":24,"ex":[["人工衛星は宇宙にあります。","Vệ tinh nhân tạo ở trong vũ trụ."],["日本の人工衛星は有名です。","Vệ tinh nhân tạo của Nhật Bản nổi tiếng."],["人工衛星で天気を調べます。","Dùng vệ tinh nhân tạo để xem thời tiết."],["人工衛星が空を飛んでいます。","Vệ tinh nhân tạo đang bay trên trời."],["人工衛星の話を聞きました。","Tôi đã nghe câu chuyện về vệ tinh nhân tạo."]]},{"word":"J-pop","reading":"ジェー・ポップ","meaning":"J-pop","hanViet":"","lesson":24,"ex":[["私はJ-popが好きです。","Tôi thích J-pop."],["J-popの歌をよく聞きます。","Tôi thường nghe nhạc J-pop."],["J-popのコンサートに行きました。","Tôi đã đi xem buổi hòa nhạc J-pop."],["彼女はJ-popの歌手です。","Cô ấy là ca sĩ J-pop."],["J-popは世界で人気があります。","J-pop được ưa chuộng trên thế giới."]]},{"word":"当店","reading":"とうてん","meaning":"cửa hàng chúng tôi","hanViet":"ĐƯƠNG ĐIẾM","lesson":24,"ex":[["当店は駅の近くにあります。","Cửa hàng chúng tôi ở gần ga."],["当店の商品は安いです。","Sản phẩm của cửa hàng chúng tôi rẻ."],["当店で買ってください。","Hãy mua ở cửa hàng chúng tôi."],["当店は朝九時に開きます。","Cửa hàng chúng tôi mở cửa lúc chín giờ sáng."],["当店の料理はおいしいです。","Món ăn của cửa hàng chúng tôi rất ngon."]]},{"word":"ジャンル","reading":"","meaning":"thể loại","hanViet":"","lesson":24,"ex":[["好きなジャンルは何ですか。","Thể loại bạn thích là gì?"],["この映画のジャンルは何ですか。","Thể loại của bộ phim này là gì?"],["たくさんのジャンルの音楽を聞きます。","Tôi nghe nhạc nhiều thể loại."],["好きなジャンルの歌を探しています。","Tôi đang tìm bài hát thuộc thể loại mình thích."],["ジャンルによって、値段が違います。","Tùy thể loại mà giá khác nhau."]]},{"word":"胸（母親の～）","reading":"むね（ははおやの～）","meaning":"ngực, lòng (mẹ)","hanViet":"HUNG MẪU THÂN","lesson":24,"ex":[["母親の胸は温かいです。","Lòng mẹ thật ấm áp."],["子どもは母親の胸で眠りました。","Đứa trẻ đã ngủ trong lòng mẹ."],["子どもは母親の胸で泣きました。","Đứa trẻ đã khóc trong lòng mẹ."],["母親の胸を思い出します。","Tôi nhớ về lòng mẹ."],["赤ちゃんは母親の胸で寝ています。","Em bé đang ngủ trong lòng mẹ."]]},{"word":"座り込む","reading":"すわりこむ","meaning":"ngồi bệt xuống, ngồi rũ xuống","hanViet":"TỌA","lesson":24,"ex":[["彼は疲れて、道に座り込みました。","Anh ấy mệt nên đã ngồi bệt xuống đường."],["子どもは公園で座り込みました。","Đứa trẻ đã ngồi bệt xuống ở công viên."],["田中さんは床に座り込みました。","Anh Tanaka đã ngồi bệt xuống sàn."],["彼女は泣いて、座り込みました。","Cô ấy vừa khóc vừa ngồi rũ xuống."],["彼は重い荷物を置いて、座り込みました。","Anh ấy đặt hành lý nặng xuống rồi ngồi bệt xuống."]]},{"word":"協力（する）","reading":"きょうりょく（する）","meaning":"hợp tác","hanViet":"HIỆP LỰC","lesson":24,"ex":[["みんなで協力して、仕事をしました。","Mọi người đã hợp tác cùng nhau làm việc."],["友達と協力して、宿題をしました。","Tôi đã hợp tác với bạn bè làm bài tập."],["会社と協力して、新しい商品を作りました。","Tôi đã hợp tác với công ty để làm sản phẩm mới."],["協力することが大切です。","Hợp tác là điều quan trọng."],["家族の協力で、大学を卒業しました。","Nhờ sự hợp tác của gia đình, tôi đã tốt nghiệp đại học."]]},{"word":"別れ（永遠の～）","reading":"わかれ（えいえんの～）","meaning":"chia tay, chia ly (vĩnh viễn)","hanViet":"BIỆT VĨNH VIỄN","lesson":24,"ex":[["永遠の別れは、とても悲しいことです。","Chia ly vĩnh viễn là chuyện rất buồn."],["祖父との永遠の別れを思い出します。","Tôi nhớ về cuộc chia ly vĩnh viễn với ông."],["永遠の別れの日は、忘れられません。","Ngày chia ly vĩnh viễn không thể quên được."],["友達との永遠の別れに泣きました。","Tôi đã khóc trong cuộc chia ly vĩnh viễn với bạn bè."],["永遠の別れの前に、手紙を書きました。","Trước cuộc chia ly vĩnh viễn, tôi đã viết thư."]]},{"word":"神","reading":"かみ","meaning":"thần thánh","hanViet":"THẦN","lesson":24,"ex":[["日本の神を信じています。","Tôi tin vào thần thánh Nhật Bản."],["神社で神の話を聞きました。","Tôi đã nghe câu chuyện về thần ở đền thờ."],["神のことを本で読みました。","Tôi đã đọc về thần thánh trong sách."],["昔の人は神を信じていました。","Người xưa đã tin vào thần thánh."],["神を信じる人は多いです。","Nhiều người tin vào thần thánh."]]},{"word":"ウォーター","reading":"","meaning":"nước","hanViet":"","lesson":24,"ex":[["ウォーターを一本買いました。","Tôi đã mua một chai nước."],["暑い日はウォーターをたくさん飲みます。","Ngày nóng tôi uống nhiều nước."],["ウォーターがなかったので、買いに行きました。","Vì hết nước nên tôi đã đi mua."],["冷たいウォーターをください。","Cho tôi nước lạnh."],["ウォーターとコーヒーを買いました。","Tôi đã mua nước và cà phê."]]},{"word":"開店（する）","reading":"かいてん（する）","meaning":"mở cửa hàng, khai trương","hanViet":"KHAI ĐIẾM","lesson":24,"ex":[["新しい店が来月開店します。","Cửa hàng mới sẽ khai trương tháng sau."],["この店は九時に開店します。","Cửa hàng này mở cửa lúc chín giờ."],["田中さんは店を開店しました。","Anh Tanaka đã khai trương cửa hàng."],["開店の日は人が多かったです。","Ngày khai trương có nhiều người."],["店が開店して、町がにぎやかになりました。","Cửa hàng mở cửa nên thị trấn trở nên nhộn nhịp."]]},{"word":"チーズ","reading":"","meaning":"phomat","hanViet":"","lesson":24,"ex":[["チーズが好きです。","Tôi thích phomat."],["パンとチーズを食べました。","Tôi đã ăn bánh mì với phomat."],["チーズを買いにスーパーへ行きました。","Tôi đã đi siêu thị để mua phomat."],["このチーズはおいしいです。","Phomat này rất ngon."],["チーズとワインを買いました。","Tôi đã mua phomat và rượu vang."]]},{"word":"やぎ乳","reading":"やぎにゅう","meaning":"sữa dê","hanViet":"NHŨ","lesson":24,"ex":[["やぎ乳は体にいいです。","Sữa dê tốt cho cơ thể."],["やぎ乳を飲んだことがあります。","Tôi đã từng uống sữa dê."],["この店はやぎ乳を売っています。","Cửa hàng này bán sữa dê."],["やぎ乳でチーズを作ります。","Người ta làm phomat từ sữa dê."],["やぎ乳の味は牛乳と違います。","Vị sữa dê khác với sữa bò."]]},{"word":"非常用","reading":"ひじょうよう","meaning":"dùng trong trường hợp khẩn cấp","hanViet":"PHI THƯỜNG DỤNG","lesson":24,"ex":[["非常用の水を用意しました。","Tôi đã chuẩn bị nước dùng trong trường hợp khẩn cấp."],["非常用の食べ物を買いました。","Tôi đã mua thức ăn dùng trong trường hợp khẩn cấp."],["非常用の電池を用意しています。","Tôi đang chuẩn bị pin dùng trong trường hợp khẩn cấp."],["家に非常用のものがあります。","Ở nhà có đồ dùng trong trường hợp khẩn cấp."],["非常用のバッグを準備しました。","Tôi đã chuẩn bị túi dùng trong trường hợp khẩn cấp."]]},{"word":"何とかなる","reading":"なんとかなる","meaning":"bằng cách nào đó sẽ được, rồi cũng sẽ ổn","hanViet":"HÀ","lesson":24,"ex":[["大丈夫、何とかなります。","Không sao đâu, rồi cũng sẽ ổn thôi."],["お金がなくても、何とかなります。","Dù không có tiền thì bằng cách nào đó cũng sẽ được."],["困ったときは、何とかなると思います。","Khi gặp khó khăn, tôi nghĩ rồi cũng sẽ ổn."],["試験は難しいですが、何とかなります。","Kỳ thi khó nhưng rồi cũng sẽ ổn."],["何とかなると信じています。","Tôi tin rằng rồi cũng sẽ ổn."]]},{"word":"グラウンド","reading":"","meaning":"sân bóng","hanViet":"","lesson":24,"ex":[["グラウンドでサッカーをしました。","Tôi đã chơi bóng đá ở sân bóng."],["子どもたちはグラウンドで遊んでいます。","Trẻ em đang chơi ở sân bóng."],["グラウンドが広いです。","Sân bóng rộng."],["学校のグラウンドで運動しました。","Tôi đã vận động ở sân bóng của trường."],["グラウンドで走って、練習しました。","Tôi đã chạy và luyện tập ở sân bóng."]]},{"word":"前方","reading":"ぜんぽう","meaning":"phía trước","hanViet":"TIỀN PHƯƠNG","lesson":24,"ex":[["前方に山が見えます。","Phía trước có thể thấy núi."],["車の前方に信号があります。","Phía trước xe có đèn giao thông."],["前方を見て、歩いてください。","Hãy nhìn phía trước và đi bộ."],["前方に大きい建物があります。","Phía trước có tòa nhà lớn."],["前方に人が歩いています。","Phía trước có người đang đi bộ."]]},{"word":"出る（結論が～）","reading":"でる（けつろんが～）","meaning":"đưa ra (kết luận)","hanViet":"XUẤT KẾT LUẬN","lesson":24,"ex":[["会議で結論が出ました。","Trong cuộc họp đã đưa ra kết luận."],["結論が出るまで、時間がかかりました。","Phải mất thời gian cho đến khi đưa ra kết luận."],["みんなで話して、結論が出ました。","Mọi người đã nói chuyện và đưa ra kết luận."],["結論が出て、みんなうれしくなりました。","Kết luận đã được đưa ra nên mọi người đều vui."],["まだ結論が出ていません。","Vẫn chưa đưa ra kết luận."]]},{"word":"了承（する）","reading":"りょうしょう（する）","meaning":"đồng ý, chấp thuận","hanViet":"LIỄU THỪA","lesson":24,"ex":[["社長は計画を了承しました。","Giám đốc đã chấp thuận kế hoạch."],["先生は私の計画を了承しました。","Thầy đã chấp thuận kế hoạch của tôi."],["会社は私の休みを了承しました。","Công ty đã chấp thuận ngày nghỉ của tôi."],["田中さんは新しい方法を了承しました。","Anh Tanaka đã chấp thuận cách mới."],["了承する前に、よく考えてください。","Trước khi chấp thuận, hãy suy nghĩ kỹ."]]},{"word":"起こす（行動を～）","reading":"おこす（こうどうを～）","meaning":"thực hiện (hành động)","hanViet":"KHỞI HÀNH ĐỘNG","lesson":24,"ex":[["問題を直すために、行動を起こしました。","Để sửa vấn đề, tôi đã thực hiện hành động."],["環境のために、行動を起こすことが大切です。","Hành động vì môi trường là điều quan trọng."],["彼は夢のために、行動を起こしました。","Anh ấy đã hành động vì ước mơ."],["行動を起こさないと、何も変わりません。","Nếu không hành động thì không có gì thay đổi."],["みんなで行動を起こしましょう。","Mọi người cùng hành động nhé."]]},{"word":"銭湯","reading":"せんとう","meaning":"nhà tắm công cộng","hanViet":"TIỀN THANG","lesson":24,"ex":[["銭湯に行って、お風呂に入りました。","Tôi đã đi nhà tắm công cộng và tắm."],["日本の銭湯は有名です。","Nhà tắm công cộng Nhật Bản nổi tiếng."],["銭湯で体を洗いました。","Tôi đã tắm rửa ở nhà tắm công cộng."],["町の銭湯は夜遅くまで開いています。","Nhà tắm công cộng của thị trấn mở đến đêm muộn."],["銭湯に行くのが好きです。","Tôi thích đi nhà tắm công cộng."]]},{"word":"下駄","reading":"げた","meaning":"guốc Nhật","hanViet":"HẠ ĐÀ","lesson":24,"ex":[["新しい下駄を買いました。","Tôi đã mua guốc Nhật mới."],["夏は下駄で歩きます。","Mùa hè tôi đi bộ bằng guốc Nhật."],["下駄の音が聞こえます。","Có thể nghe tiếng guốc Nhật."],["夏に下駄を買いました。","Tôi đã mua guốc Nhật vào mùa hè."],["下駄は木でできています。","Guốc Nhật được làm bằng gỗ."]]},{"word":"押し切る","reading":"おしきる","meaning":"bất chấp, vượt qua","hanViet":"ÁP THIẾT","lesson":24,"ex":[["反対を押し切って、計画を続けました。","Bất chấp sự phản đối, tôi đã tiếp tục kế hoạch."],["彼は困難を押し切って、成功しました。","Anh ấy đã vượt qua khó khăn và thành công."],["彼は家族の反対を押し切って、日本へ来ました。","Anh ấy đã bất chấp sự phản đối của gia đình để đến Nhật Bản."],["障害を押し切って、前に進みました。","Tôi đã vượt qua trở ngại và tiến về phía trước."],["彼女はみんなの反対を押し切って、留学しました。","Cô ấy đã bất chấp sự phản đối của mọi người để đi du học."]]},{"word":"励む","reading":"はげむ","meaning":"cố gắng, gắng hết sức","hanViet":"LỆ","lesson":24,"ex":[["日本語の勉強に励んでいます。","Tôi đang cố gắng học tiếng Nhật."],["彼はスポーツに励んでいます。","Anh ấy đang cố gắng trong thể thao."],["仕事に励むことが大切です。","Cố gắng trong công việc là điều quan trọng."],["彼女はピアノに励んでいます。","Cô ấy đang cố gắng với piano."],["毎日英語の勉強に励んでいます。","Tôi cố gắng học tiếng Anh mỗi ngày."]]},{"word":"昔々","reading":"むかしむかし","meaning":"ngày xửa, ngày xưa","hanViet":"TÍCH","lesson":24,"ex":[["昔々、あるところに男の人が住んでいました。","Ngày xửa ngày xưa, ở một nơi nọ có một người đàn ông sinh sống."],["昔々の話を聞きました。","Tôi đã nghe câu chuyện ngày xửa ngày xưa."],["昔々、日本は静かな国でした。","Ngày xửa ngày xưa, Nhật Bản là đất nước yên tĩnh."],["昔々の人は、手紙を書いていました。","Người ngày xửa ngày xưa đã viết thư."],["昔々、この町は小さい村でした。","Ngày xửa ngày xưa, thị trấn này là ngôi làng nhỏ."]]},{"word":"失恋（する）","reading":"しつれん（する）","meaning":"thất tình","hanViet":"THẤT LUYẾN","lesson":24,"ex":[["失恋して、泣きました。","Thất tình, tôi đã khóc."],["失恋した友達と話しました。","Tôi đã nói chuyện với người bạn thất tình."],["失恋したとき、音楽を聞きます。","Khi thất tình, tôi nghe nhạc."],["失恋しても、前に進みます。","Dù thất tình, tôi vẫn tiến về phía trước."],["失恋の経験があります。","Tôi có kinh nghiệm thất tình."]]},{"word":"熱心（な）","reading":"ねっしん（な）","meaning":"nhiệt tình","hanViet":"NHIỆT TÂM","lesson":24,"ex":[["彼は熱心な学生です。","Anh ấy là học sinh nhiệt tình."],["熱心に勉強しています。","Tôi đang học một cách nhiệt tình."],["先生は熱心に教えてくれます。","Thầy dạy một cách nhiệt tình."],["熱心な人と働きたいです。","Tôi muốn làm việc với người nhiệt tình."],["彼女は熱心に日本語を勉強しています。","Cô ấy đang học tiếng Nhật một cách nhiệt tình."]]},{"word":"恐怖","reading":"きょうふ","meaning":"sự sợ hãi, nỗi sợ hãi","hanViet":"KHỦNG BỐ","lesson":24,"ex":[["夜、暗い道を歩くとき、恐怖を感じます。","Ban đêm, khi đi bộ trên con đường tối, tôi cảm thấy sợ hãi."],["高い場所に立つと、恐怖を感じます。","Khi đứng ở nơi cao, tôi cảm thấy sợ hãi."],["地震のとき、多くの人が恐怖を感じました。","Khi có động đất, nhiều người đã cảm thấy sợ hãi."],["恐怖を感じても、前に進まなければなりません。","Dù cảm thấy sợ hãi, vẫn phải tiến lên phía trước."],["彼は恐怖に負けないで、試験を受けました。","Anh ấy không chịu thua nỗi sợ hãi và đã tham gia kỳ thi."]]},{"word":"沈黙","reading":"ちんもく","meaning":"sự im lặng","hanViet":"TRẦM MẶC","lesson":24,"ex":[["先生が話すと、教室は沈黙になりました。","Khi thầy giáo nói, cả lớp học chìm vào im lặng."],["二人の間に長い沈黙が続きました。","Giữa hai người đã kéo dài một sự im lặng dài."],["沈黙のあとで、山田さんがゆっくり話し始めました。","Sau sự im lặng, anh Yamada bắt đầu nói chậm rãi."],["夜の森は静かで、沈黙が続いていました。","Khu rừng ban đêm yên tĩnh, sự im lặng kéo dài."],["彼は沈黙を守って、静かに座っていました。","Anh ấy giữ im lặng và ngồi yên lặng."]]},{"word":"就職活動","reading":"しゅうしょくかつどう","meaning":"hoạt động tìm việc","hanViet":"TỰU CHỨC HOẠT ĐỘNG","lesson":24,"ex":[["大学の学生は、就職活動を始めました。","Sinh viên đại học đã bắt đầu hoạt động tìm việc."],["就職活動では、多くの会社に履歴書を送ります。","Trong hoạt động tìm việc, tôi gửi sơ yếu lý lịch đến nhiều công ty."],["彼は就職活動のために、新聞を毎日読みます。","Anh ấy đọc báo mỗi ngày vì hoạt động tìm việc."],["就職活動は大変ですが、頑張らなければなりません。","Hoạt động tìm việc vất vả nhưng phải cố gắng."],["就職活動のとき、先生に相談します。","Khi tìm việc, tôi trao đổi với thầy giáo."]]},{"word":"比較（する）","reading":"ひかく（する）","meaning":"so sánh","hanViet":"TỶ GIẢO","lesson":24,"ex":[["二つの会社の給与を比較しました。","Tôi đã so sánh lương của hai công ty."],["買う前に、値段を比較することが大切です。","Trước khi mua, việc so sánh giá cả là quan trọng."],["この二つの本を比較して、読みやすいほうを選びます。","So sánh hai cuốn sách này, tôi chọn cuốn dễ đọc hơn."],["彼は東京と大阪の電車の料金を比較しました。","Anh ấy đã so sánh giá vé tàu điện ở Tokyo và Osaka."],["比較すると、この店のほうが安いです。","So sánh thì cửa hàng này rẻ hơn."]]},{"word":"従事（する）","reading":"じゅうじ（する）","meaning":"làm việc, công tác trong (một nghề/lĩnh vực); theo (nghề)","hanViet":"TÒNG SỰ","lesson":24,"ex":[["田中さんは長くこの仕事に従事しています。","Anh Tanaka đã theo đuổi công việc này lâu rồi."],["彼は子どものときから、音楽に従事しています。","Anh ấy theo đuổi âm nhạc từ khi còn nhỏ."],["彼女は長く病院の仕事に従事しています。","Cô ấy đã theo đuổi công việc ở bệnh viện lâu rồi."],["従事する仕事を選ぶとき、よく考えなければなりません。","Khi chọn công việc để theo đuổi, phải suy nghĩ kỹ."],["父は長い間、会社の運営に従事しています。","Bố tôi đã theo đuổi việc điều hành công ty trong thời gian dài."]]},{"word":"推薦（する）","reading":"すいせん（する）","meaning":"giới thiệu, tiến cử","hanViet":"THÔI TIẾN","lesson":24,"ex":[["先生が私を推薦してくださいました。","Thầy giáo đã tiến cử tôi."],["友達にこの本を推薦しました。","Tôi đã giới thiệu cuốn sách này cho bạn."],["この映画は友達に推薦したいです。","Tôi muốn giới thiệu bộ phim này cho bạn."],["先生の推薦で、この会社に入りました。","Nhờ sự giới thiệu của thầy giáo, tôi đã vào công ty này."],["彼は部長に推薦されて、新しい仕事を始めました。","Anh ấy được trưởng phòng tiến cử và đã bắt đầu công việc mới."]]},{"word":"TOEIC","reading":"トーイック","meaning":"TOEIC","hanViet":"","lesson":24,"ex":[["仕事のために、TOEICの勉強を始めました。","Vì công việc, tôi đã bắt đầu học TOEIC."],["TOEICの試験は来週あります。","Kỳ thi TOEIC sẽ diễn ra vào tuần tới."],["彼のTOEICの点数は高いです。","Điểm TOEIC của anh ấy cao."],["TOEICの勉強は毎日二時間します。","Tôi học TOEIC hai tiếng mỗi ngày."],["TOEICのために、英語の単語を覚えます。","Vì TOEIC, tôi học thuộc từ vựng tiếng Anh."]]},{"word":"全力","reading":"ぜんりょく","meaning":"toàn bộ sức lực","hanViet":"TOÀN LỰC","lesson":24,"ex":[["全力で試験を受けました。","Tôi đã tham gia kỳ thi với toàn bộ sức lực."],["彼は全力で走りました。","Anh ấy đã chạy hết sức."],["全力で頑張ります。","Tôi sẽ cố gắng hết sức."],["全力を出して、難しい仕事をしました。","Tôi đã dốc toàn lực làm công việc khó."],["彼女は全力で歌いました。","Cô ấy đã hát hết mình."]]},{"word":"運営（する）","reading":"うんえい（する）","meaning":"quản lý, điều hành","hanViet":"VẬN DOANH","lesson":24,"ex":[["田中さんは小さな店を運営しています。","Anh Tanaka đang điều hành một cửa hàng nhỏ."],["彼は学校の運営をしています。","Anh ấy đang làm công việc điều hành trường học."],["会社の運営は大変です。","Việc điều hành công ty rất vất vả."],["運営する会社が大きくなりました。","Công ty đang điều hành đã trở nên lớn hơn."],["この店は家族で運営しています。","Cửa hàng này được gia đình cùng điều hành."]]},{"word":"履歴書","reading":"りれきしょ","meaning":"sơ yếu lý lịch","hanViet":"LÝ LỊCH THƯ","lesson":24,"ex":[["会社に履歴書を送りました。","Tôi đã gửi sơ yếu lý lịch đến công ty."],["履歴書に自分の写真を使います。","Tôi dùng ảnh của mình trong sơ yếu lý lịch."],["履歴書を丁寧に書きました。","Tôi đã viết sơ yếu lý lịch một cách cẩn thận."],["面接の前に、履歴書を準備します。","Trước buổi phỏng vấn, tôi chuẩn bị sơ yếu lý lịch."],["履歴書に特技を書きました。","Tôi đã viết kỹ năng đặc biệt vào sơ yếu lý lịch."]]},{"word":"特技","reading":"とくぎ","meaning":"kỹ năng đặc biệt","hanViet":"ĐẶC KỸ","lesson":24,"ex":[["私の特技は泳ぐことです。","Kỹ năng đặc biệt của tôi là bơi."],["特技は歌を歌うことです。","Kỹ năng đặc biệt là hát."],["履歴書に特技を書きます。","Tôi viết kỹ năng đặc biệt vào sơ yếu lý lịch."],["彼の特技は速く走ることです。","Kỹ năng đặc biệt của anh ấy là chạy nhanh."],["特技があると、面接で話しやすいです。","Có kỹ năng đặc biệt thì dễ nói chuyện trong buổi phỏng vấn."]]},{"word":"給与","reading":"きゅうよ","meaning":"tiền lương","hanViet":"CẤP DỰ","lesson":24,"ex":[["この会社の給与は高いです。","Lương của công ty này cao."],["給与は毎月銀行に送られます。","Lương được gửi vào ngân hàng mỗi tháng."],["給与が上がって、皆さんは喜びました。","Lương tăng lên, mọi người đã vui mừng."],["仕事を選ぶとき、給与も大切です。","Khi chọn việc, lương cũng quan trọng."],["給与について、会社に聞きました。","Tôi đã hỏi công ty về lương."]]},{"word":"岐路","reading":"きろ","meaning":"ngã rẽ, bước ngoặt","hanViet":"KỲ LỘ","lesson":24,"ex":[["大学を卒業して、人生の岐路に立ちました。","Tốt nghiệp đại học, tôi đã đứng trước ngã rẽ của cuộc đời."],["彼は仕事の岐路に立っています。","Anh ấy đang đứng trước bước ngoặt của công việc."],["岐路に立ったとき、よく考えなければなりません。","Khi đứng trước ngã rẽ, phải suy nghĩ kỹ."],["私は岐路に立って、東京に行くことにしました。","Đứng trước ngã rẽ, tôi đã quyết định đi Tokyo."],["岐路では、自分の気持ちを大切にします。","Ở ngã rẽ, tôi trân trọng cảm xúc của chính mình."]]},{"word":"最寄り","reading":"もより","meaning":"gần nhất","hanViet":"TỐI KÝ","lesson":24,"ex":[["最寄りの駅は家から近いです。","Ga gần nhất ở gần nhà tôi."],["最寄りの店は家の前にあります。","Cửa hàng gần nhất ở trước nhà tôi."],["最寄りの公園は大きいです。","Công viên gần nhất rất lớn."],["会社から最寄りの駅まで歩きます。","Tôi đi bộ từ công ty đến ga gần nhất."],["最寄りの病院を教えてください。","Hãy chỉ cho tôi bệnh viện gần nhất."]]},{"word":"道筋","reading":"みちすじ","meaning":"tuyến đường, trục đường","hanViet":"ĐẠO CÂN","lesson":24,"ex":[["この道筋を行くと、駅があります。","Đi theo tuyến đường này sẽ có ga."],["道筋を知るために、地図を見ます。","Để biết tuyến đường, tôi xem bản đồ."],["新しい道筋ができました。","Đã có tuyến đường mới."],["道筋をよく見て、歩きます。","Tôi nhìn kỹ tuyến đường rồi đi bộ."],["会社までの道筋は二つあります。","Có hai tuyến đường đến công ty."]]},{"word":"ルート","reading":"","meaning":"lộ trình, đường đi","hanViet":"","lesson":24,"ex":[["旅行のルートを決めました。","Tôi đã quyết định lộ trình du lịch."],["電車のルートを地図で見ます。","Tôi xem lộ trình tàu điện trên bản đồ."],["このルートは時間が長いです。","Lộ trình này mất nhiều thời gian."],["ルートを変えて、バスに乗りました。","Tôi đổi lộ trình và lên xe buýt."],["京都までのルートは三つあります。","Có ba lộ trình đến Kyoto."]]},{"word":"仕事場","reading":"しごとば","meaning":"nơi làm việc","hanViet":"SĨ SỰ TRƯỜNG","lesson":24,"ex":[["私の仕事場は東京にあります。","Nơi làm việc của tôi ở Tokyo."],["仕事場は家から近いです。","Nơi làm việc gần nhà tôi."],["仕事場で友達と昼ごはんを食べます。","Tôi ăn trưa với bạn ở nơi làm việc."],["新しい仕事場は明るいです。","Nơi làm việc mới sáng sủa."],["仕事場の人は皆さん親切です。","Mọi người ở nơi làm việc đều tốt bụng."]]},{"word":"遠回り","reading":"とおまわり","meaning":"đi đường vòng","hanViet":"VIỄN HỒI","lesson":24,"ex":[["地図を見ないで、遠回りをしました。","Tôi không xem bản đồ nên đã đi đường vòng."],["遠回りをしても、駅に行くことができます。","Dù đi đường vòng, vẫn có thể đến ga."],["雨の日は遠回りをして、家に帰ります。","Ngày mưa tôi đi đường vòng rồi về nhà."],["遠回りは時間が長いです。","Đi đường vòng mất nhiều thời gian."],["遠回りをしないで、家に帰ります。","Tôi về nhà mà không đi đường vòng."]]},{"word":"飲み会","reading":"のみかい","meaning":"tiệc nhậu, bữa nhậu","hanViet":"ẨM HỘI","lesson":24,"ex":[["会社で飲み会があります。","Ở công ty có tiệc nhậu."],["飲み会で友達と話します。","Tôi nói chuyện với bạn ở tiệc nhậu."],["今週の飲み会に参加します。","Tôi sẽ tham gia tiệc nhậu tuần này."],["飲み会は夜七時に始まります。","Tiệc nhậu bắt đầu lúc bảy giờ tối."],["飲み会でビールを飲みます。","Tôi uống bia ở tiệc nhậu."]]},{"word":"選択（する）","reading":"せんたく（する）","meaning":"chọn lựa","hanViet":"TUYỂN TRẠCH","lesson":24,"ex":[["仕事を選択するとき、よく考えます。","Khi chọn lựa công việc, tôi suy nghĩ kỹ."],["大学を選択しました。","Tôi đã chọn lựa trường đại học."],["二つの仕事から一つを選択しなければなりません。","Phải chọn một trong hai công việc."],["彼は東京の会社を選択しました。","Anh ấy đã chọn công ty ở Tokyo."],["選択した仕事を大切にします。","Tôi trân trọng công việc đã chọn."]]},{"word":"彼我","reading":"ひが","meaning":"đối phương và bản thân, người và ta","hanViet":"BỈ NGÃ","lesson":24,"ex":[["彼我の力を比べてみます。","Tôi thử so sánh sức lực của ta và đối phương."],["彼我の意見を比べます。","Tôi so sánh ý kiến của ta và đối phương."],["彼我の力は同じではありません。","Sức lực của ta và đối phương không giống nhau."],["彼我の意見は同じです。","Ý kiến của ta và đối phương giống nhau."],["彼我の気持ちを大切にします。","Tôi trân trọng cảm xúc của ta và đối phương."]]},{"word":"効率","reading":"こうりつ","meaning":"hiệu quả","hanViet":"HIỆU SUẤT","lesson":24,"ex":[["仕事の効率をよくするために、計画を立てます。","Để nâng cao hiệu quả công việc, tôi lập kế hoạch."],["効率の高い仕事をします。","Tôi làm việc hiệu quả cao."],["この方法は効率が高いです。","Phương pháp này có hiệu quả cao."],["効率を考えて、仕事をします。","Tôi làm việc có tính đến hiệu quả."],["効率がいいと、時間ができます。","Hiệu quả tốt thì sẽ có thời gian."]]},{"word":"優先（する）","reading":"ゆうせん（する）","meaning":"ưu tiên","hanViet":"ƯU TIÊN","lesson":24,"ex":[["仕事より家族を優先します。","Tôi ưu tiên gia đình hơn công việc."],["勉強を優先して、テレビを見るのをやめました。","Tôi ưu tiên học tập và đã dừng xem tivi."],["健康を優先しなければなりません。","Phải ưu tiên sức khỏe."],["彼は安全を優先します。","Anh ấy ưu tiên sự an toàn."],["優先する仕事から始めます。","Tôi bắt đầu từ công việc được ưu tiên."]]},{"word":"通行（する）","reading":"つうこう（する）","meaning":"đi qua, qua lại","hanViet":"THÔNG HÀNH","lesson":24,"ex":[["この道は車が通行できます。","Con đường này xe có thể đi qua."],["雨で、この道は通行ができません。","Vì mưa, con đường này không thể đi qua."],["この橋は人が通行します。","Cây cầu này người đi qua."],["夜はこの道の通行が少ないです。","Ban đêm, việc qua lại trên con đường này ít."],["通行する車が多いです。","Có nhiều xe đi qua."]]},{"word":"長い目","reading":"ながいめ","meaning":"tầm nhìn xa","hanViet":"TRƯỜNG MỤC","lesson":24,"ex":[["長い目で仕事を考えます。","Tôi suy nghĩ về công việc với tầm nhìn xa."],["長い目で見ると、この勉強は大切です。","Nhìn với tầm nhìn xa, việc học này rất quan trọng."],["子どもの将来は長い目で考えます。","Tương lai của trẻ em cần suy nghĩ với tầm nhìn xa."],["長い目で計画を立てます。","Tôi lập kế hoạch với tầm nhìn xa."],["長い目で見て、会社を選びます。","Nhìn với tầm nhìn xa, tôi chọn công ty."]]},{"word":"人柄","reading":"ひとがら","meaning":"phẩm cách, nhân cách","hanViet":"NHÂN BÍNH","lesson":24,"ex":[["田中さんは人柄がいいです。","Anh Tanaka có phẩm cách tốt."],["人柄のいい先生です。","Là thầy giáo có phẩm cách tốt."],["彼の人柄は皆さんに知られています。","Phẩm cách của anh ấy được mọi người biết đến."],["人柄を知るために、よく話します。","Để hiểu phẩm cách, tôi nói chuyện nhiều."],["社長の人柄は親切です。","Phẩm cách của giám đốc rất tốt bụng."]]},{"word":"帰結","reading":"きけつ","meaning":"kết quả cuối cùng, kết cục (của sự việc / cuộc thảo luận)","hanViet":"QUY KẾT","lesson":24,"ex":[["話の帰結は、皆さんが東京に行くことでした。","Kết cục của câu chuyện là mọi người đi Tokyo."],["長い話の帰結はいいことでした。","Kết cục của câu chuyện dài là điều tốt."],["帰結をよく考えて、仕事をします。","Tôi suy nghĩ kỹ về kết cục rồi làm việc."],["仕事の帰結は、皆さんが喜ぶことでした。","Kết cục của công việc là mọi người đều vui mừng."],["帰結は、会社をやめることでした。","Kết cục là việc nghỉ công ty."]]},{"word":"旅路","reading":"たびじ","meaning":"chuyến đi, cuộc hành trình","hanViet":"LỮ LỘ","lesson":24,"ex":[["京都への旅路は楽しいです。","Chuyến đi đến Kyoto rất vui."],["旅路で美しい山を見ました。","Trên chuyến đi, tôi đã thấy núi đẹp."],["旅路の途中で、友達に会いました。","Giữa chuyến đi, tôi đã gặp bạn."],["長い旅路を終えて、家に帰りました。","Kết thúc chuyến đi dài, tôi đã về nhà."],["旅路で新しいことを知ります。","Trên chuyến đi, tôi biết những điều mới."]]},{"word":"いつしか","reading":"","meaning":"từ lúc nào","hanViet":"","lesson":24,"ex":[["いつしか夜になりました。","Từ lúc nào trời đã tối."],["いつしか雨が降り始めました。","Từ lúc nào trời đã bắt đầu mưa."],["いつしか彼は大きくなりました。","Từ lúc nào anh ấy đã lớn lên."],["いつしか夏が終わりました。","Từ lúc nào mùa hè đã kết thúc."],["いつしか友達が増えました。","Từ lúc nào bạn bè đã tăng lên."]]},{"word":"昆虫採集","reading":"こんちゅうさいしゅう","meaning":"sưu tập côn trùng","hanViet":"CÔN TRÙNG THÁI TẬP","lesson":24,"ex":[["子どものとき、昆虫採集が好きでした。","Hồi nhỏ, tôi thích sưu tập côn trùng."],["夏に森で昆虫採集をします。","Vào mùa hè, tôi sưu tập côn trùng trong rừng."],["昆虫採集のために、虫網を買いました。","Vì sưu tập côn trùng, tôi đã mua vợt bắt côn trùng."],["昆虫採集は子どもの楽しい時間です。","Sưu tập côn trùng là thời gian vui vẻ của trẻ em."],["昆虫採集で多くの虫を見つけます。","Khi sưu tập côn trùng, tôi tìm thấy nhiều côn trùng."]]},{"word":"昆虫","reading":"こんちゅう","meaning":"côn trùng","hanViet":"CÔN TRÙNG","lesson":24,"ex":[["夏の森には多くの昆虫がいます。","Trong rừng mùa hè có nhiều côn trùng."],["昆虫は花の近くにいます。","Côn trùng ở gần hoa."],["子どもは昆虫が好きです。","Trẻ em thích côn trùng."],["昆虫を観察するのが楽しいです。","Việc quan sát côn trùng rất vui."],["昆虫の絵を描きます。","Tôi vẽ tranh côn trùng."]]},{"word":"蝶道","reading":"ちょうどう","meaning":"đường bướm bay","hanViet":"ĐIỆP ĐẠO","lesson":24,"ex":[["森の中に蝶道があります。","Trong rừng có đường bướm bay."],["蝶道は花の近くにあります。","Đường bướm bay ở gần hoa."],["蝶道で昆虫を待ちます。","Tôi đợi côn trùng ở đường bướm bay."],["夏の蝶道は明るいです。","Đường bướm bay mùa hè sáng sủa."],["蝶道を見つけるのは難しいです。","Việc tìm ra đường bướm bay rất khó."]]},{"word":"網","reading":"あみ","meaning":"lưới","hanViet":"VÕNG","lesson":24,"ex":[["魚を取るために、網を使います。","Để bắt cá, tôi dùng lưới."],["虫を取る網は小さいです。","Lưới bắt côn trùng nhỏ."],["網を川に置きました。","Tôi đã đặt lưới ở sông."],["網の中に魚が入りました。","Cá đã vào trong lưới."],["網を使って、虫を取ります。","Tôi dùng lưới để bắt côn trùng."]]},{"word":"構える","reading":"かまえる","meaning":"bố trí, giăng sẵn (lưới)","hanViet":"CẤU","lesson":24,"ex":[["森で網を構えました。","Tôi đã giăng sẵn lưới trong rừng."],["カメラを構えて、写真を撮ります。","Tôi giơ máy ảnh lên và chụp ảnh."],["虫を取るために、網を構えます。","Để bắt côn trùng, tôi giăng sẵn lưới."],["彼は網を構えて、静かに待ちます。","Anh ấy giăng sẵn lưới và lặng lẽ chờ đợi."],["蝶道で網を構えました。","Tôi đã giăng sẵn lưới ở đường bướm bay."]]},{"word":"アゲハチョウ","reading":"","meaning":"bướm phượng","hanViet":"","lesson":24,"ex":[["夏にアゲハチョウが花に来ます。","Vào mùa hè, bướm phượng đến với hoa."],["アゲハチョウは大きい昆虫です。","Bướm phượng là côn trùng lớn."],["公園でアゲハチョウを見ました。","Tôi đã thấy bướm phượng ở công viên."],["アゲハチョウが空を飛びます。","Bướm phượng bay trên bầu trời."],["アゲハチョウの色は美しいです。","Màu của bướm phượng rất đẹp."]]},{"word":"木立","reading":"こだち","meaning":"bụi cây, lùm cây","hanViet":"MỘC LẬP","lesson":24,"ex":[["森の木立の中を歩きます。","Tôi đi bộ trong lùm cây của rừng."],["木立の近くに花があります。","Gần lùm cây có hoa."],["木立の中で休みます。","Tôi nghỉ ngơi trong lùm cây."],["木立の中は涼しいです。","Trong lùm cây mát mẻ."],["木立の中に昆虫がいます。","Trong lùm cây có côn trùng."]]},{"word":"暗がり","reading":"くらがり","meaning":"bóng tối, nơi tối","hanViet":"ÁM","lesson":24,"ex":[["暗がりを歩くのは怖いです。","Đi bộ trong bóng tối thật đáng sợ."],["夜の暗がりで音が聞こえました。","Trong bóng tối ban đêm, tôi đã nghe thấy âm thanh."],["暗がりから人が出てきました。","Một người đã bước ra từ bóng tối."],["森の暗がりは静かです。","Bóng tối trong rừng yên tĩnh."],["暗がりでは、よく見えません。","Trong bóng tối, không nhìn rõ."]]},{"word":"日照","reading":"にっしょう","meaning":"ánh sáng mặt trời","hanViet":"NHẬT CHIẾU","lesson":24,"ex":[["花には日照が必要です。","Hoa cần ánh sáng mặt trời."],["日照がいいと、植物が大きくなります。","Ánh sáng mặt trời tốt thì cây cối trở nên lớn hơn."],["夏の日照は強いです。","Ánh sáng mặt trời mùa hè mạnh."],["日照の少ない所では、花が大きくなりません。","Ở nơi ít ánh sáng mặt trời, hoa không lớn lên được."],["野菜には日照が大切です。","Đối với rau, ánh sáng mặt trời rất quan trọng."]]},{"word":"食草","reading":"しょくそう","meaning":"cây làm thức ăn","hanViet":"THỰC THẢO","lesson":24,"ex":[["昆虫は食草を食べます。","Côn trùng ăn cây làm thức ăn."],["食草の近くに昆虫がいます。","Gần cây làm thức ăn có côn trùng."],["食草の葉を食べる昆虫がいます。","Có côn trùng ăn lá của cây làm thức ăn."],["食草を探して、森を歩きます。","Tôi tìm cây làm thức ăn và đi bộ trong rừng."],["この食草は昆虫に大切です。","Cây làm thức ăn này quan trọng với côn trùng."]]},{"word":"メス","reading":"","meaning":"giống cái","hanViet":"","lesson":24,"ex":[["この昆虫はメスです。","Côn trùng này là giống cái."],["メスの色は美しいです。","Màu của con cái rất đẹp."],["メスの昆虫を見つけました。","Tôi đã tìm thấy côn trùng giống cái."],["メスは花の近くにいます。","Con cái ở gần hoa."],["メスの昆虫を探します。","Tôi tìm côn trùng giống cái."]]},{"word":"待ち構える","reading":"まちかまえる","meaning":"đợi sẵn","hanViet":"ĐÃI CẤU","lesson":24,"ex":[["蝶道で網を持って、待ち構えます。","Tôi cầm lưới và đợi sẵn ở đường bướm bay."],["花の近くで昆虫を待ち構えます。","Tôi đợi sẵn côn trùng gần hoa."],["森の中で静かに待ち構えました。","Tôi đã lặng lẽ đợi sẵn trong rừng."],["彼は網を構えて、待ち構えています。","Anh ấy giăng sẵn lưới và đang đợi sẵn."],["待ち構えていると、昆虫が来ました。","Khi đang đợi sẵn, côn trùng đã đến."]]},{"word":"収める","reading":"おさめる","meaning":"mắc vào (lưới)","hanViet":"THU, THÂU","lesson":24,"ex":[["昆虫を網に収めました。","Tôi đã bắt côn trùng vào lưới."],["網に昆虫を収めるのは難しいです。","Việc bắt côn trùng vào lưới rất khó."],["アゲハチョウを網に収めました。","Tôi đã bắt bướm phượng vào lưới."],["彼は虫を上手に網に収めます。","Anh ấy khéo léo bắt côn trùng vào lưới."],["網に収めた昆虫を見ます。","Tôi nhìn côn trùng đã bắt được vào lưới."]]},{"word":"理屈","reading":"りくつ","meaning":"lí lẽ, lí luận","hanViet":"LÝ KHUẤT","lesson":24,"ex":[["彼の理屈は正しいです。","Lí lẽ của anh ấy đúng."],["理屈で話すのは難しいです。","Việc nói bằng lí lẽ rất khó."],["理屈を聞いて、理解しました。","Nghe lí lẽ, tôi đã hiểu."],["理屈だけでは、人は動きません。","Chỉ bằng lí lẽ thôi, con người không hành động."],["理屈を説明します。","Tôi giải thích lí lẽ."]]},{"word":"虫網","reading":"むしあみ","meaning":"vợt bắt côn trùng","hanViet":"TRÙNG VÕNG","lesson":24,"ex":[["虫網を持って、森に行きます。","Tôi cầm vợt bắt côn trùng và đi vào rừng."],["虫網で昆虫を取ります。","Tôi bắt côn trùng bằng vợt."],["子どもは虫網が好きです。","Trẻ em thích vợt bắt côn trùng."],["虫網を買いました。","Tôi đã mua vợt bắt côn trùng."],["虫網は昆虫採集に必要です。","Vợt bắt côn trùng cần thiết cho việc sưu tập côn trùng."]]}]};
